INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Na początku stworzył Bóg niebo i ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'A ziemia była niekształtowna i próżna, i ciemność była nad przepaścią, a Duch Boży unaszał się nad wodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'I rzekł Bóg: Niech będzie światłość; i stała się światłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'I widział Bóg światłość, że była dobra; i uczynił Bóg rozdział między światłością i między ciemnością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'I nazwał Bóg światłość dniem a ciemność nazwał nocą; i stał się wieczór, i stał się zaranek, dzień pierwszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Potem rzekł Bóg: Niech będzie rozpostarcie, w pośrodku wód, a niech dzieli wody od wód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'I uczynił Bóg rozpostarcie; uczynił też rozdział między wodami, które są pod rozpostarciem; i między wodami, które są nad rozpostarciem; i stało się tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'I nazwał Bóg rozpostarcie niebem. I stał się wieczór, i stał się zaranek, dzień wtóry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'I rzekł Bóg: Niech się zbiorą wody, które są pod niebem, na jedno miejsce, a niech się okaże miejsce suche; i stało się tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'I nazwał Bóg suche miejsce ziemią, a zebranie wód nazwał morzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'I widział Bóg, że to było dobre. Potem rzekł Bóg: Niech zrodzi ziemia trawę, ziele, wydawające nasienie, i drzewo rodzajne, czyniące owoc, według rodzaju swego, którego by nasienie było w nim na ziemi; i stało się tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'I zrodziła ziemia trawę, ziele wydawające nasienie, według rodzaju swego, i drzewo czyniące owoc, w którym nasienie jego, według rodzaju swego; i widział Bóg, że to było dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'I stał się wieczór, i stał się zaranek, dzień trzeci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'I rzekł Bóg: Niech będą światła na rozpostarciu niebieskim, ku rozdzielaniu dnia od nocy, a niech będą na znaki, i pewne czasy, i dni, i lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'I niech będą za światła na rozpostarciu nieba, aby świeciły nad ziemią; i stało się tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'I uczynił Bóg dwa światła wielkie: światło większe, aby rządziło dzień, a światło mniejsze, aby rządziło noc, i gwiazdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'I postawił je Bóg na rozpostarciu nieba, aby świeciły nad ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'I żeby rządziły dzień i noc, i czyniły rozdział między światłością, i między ciemnością; i widział Bóg, że to było dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'I stał się wieczór, i stał się zaranek, dzień czwarty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'I rzekł Bóg: Niech hojnie wywiodą wody płaz duszy żywiącej; a ptactwo niech lata nad ziemią, pod rozpostarciem niebieskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'I stworzył Bóg wieloryby wielkie, i wszelką duszę żywiącą płazającą się, którą hojnie wywiodły wody, według rodzaju ich; i wszelkie ptactwo skrzydlaste, według rodzaju ich; i widział Bóg, że to było dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Błogosławił im tedy Bóg, mówiąc: Rozradzajcie się, i rozmnażajcie się, a napełniajcie wody morskie; i ptactwo niech się rozmnaża na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'I stał się wieczór, i stał się zaranek, dzień piąty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Rzekł też Bóg: Niech wyda ziemia duszę żywiącą według rodzaju swego; bydło i płaz, i zwierz ziemski, według rodzaju swego; i stało się tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Uczynił tedy Bóg zwierz ziemski według rodzaju swego; i bydło według rodzaju swego; i wszelki płaz ziemski według rodzaju swego; i widział Bóg, że to było dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Zatem rzekł Bóg: Uczyńmy człowieka na wyobrażenie nasze, według podobieństwa naszego; a niech panuje nad rybami morskimi, i nad ptactwem niebieskim, i nad zwierzęty, i nad wszystką ziemią, i nad wszelkim płazem, płazającym się po ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Stworzył tedy Bóg człowieka na wyobrażenie swoje; na wyobrażenie Boże stworzył go; mężczyznę i niewiastę stworzył je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'I błogosławił im Bóg, i rzekł do nich Bóg: Rozradzajcie się, i rozmnażajcie się, i napełniajcie ziemię; i czyńcie ją sobie poddaną; i panujcie nad rybami morskimi, i nad ptactwem niebieskim, i nad wszelkim zwierzem, który się rusza na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'I rzekł Bóg: Oto dałem wam wszelkie ziele, wydawające z siebie nasienie, które jest na obliczu wszystkiej ziemi; i wszelkie drzewo, na którym jest owoc drzewa, wydawające z siebie nasienie, będzie wam ku pokarmowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'I wszelkiemu zwierzowi ziemskiemu, i wszystkiemu ptactwu niebieskiemu, i wszelkiej rzeczy ruszającej się na ziemi, w której jest dusza żywiąca; wszelka jarzyna ziela będzie ku pokarmowi; i stało się tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'I widział Bóg wszystko, co uczynił, a oto było bardzo dobre; i stał się wieczór, i stał się zaranek, dzień szósty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Dokończone tedy są niebiosa i ziemia, i wszystko wojsko ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'I dokończył Bóg dnia siódmego dzieła swego, które uczynił; i odpoczął w dzień siódmy od wszelkiego dzieła swego, które uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'I błogosławił Bóg dniowi siódmemu, i poświęcił go; iż weń odpoczął od wszelkiego dzieła swego, które był stworzył Bóg, aby uczynione było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Teć są zrodzenia niebios, i ziemi, gdy były stworzone, dnia, którego uczynił Pan Bóg ziemię i niebo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Wszelką różdżkę polną, przedtem niż była na ziemi; i wszelkie ziele polne, pierwej niż weszło; albowiem nie spuścił jeszcze był dżdżu Pan Bóg na ziemię; i człowieka nie było, któryby sprawował ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Ale para wychodziła z ziemi, która odwilżała wszystek wierzch ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Stworzył tedy Pan Bóg człowieka z prochu ziemi, i natchnął w oblicze jego dech żywota. I stał się człowiek duszą żywiącą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Nasadził też był Pan Bóg sad w Eden, na wschód słońca, i postawił tam człowieka, którego był stworzył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'I wywiódł Pan Bóg z ziemi wszelkie drzewo wdzięczne na wejrzeniu, i smaczne ku jedzeniu: i drzewo żywota w pośrodku sadu; i drzewo wiadomości dobrego i złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'A rzeka wychodziła z Eden dla odwilżenia sadu; i stamtąd dzieliła się na cztery główne rzeki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Imię jednej Fyson; ta okrąża wszystką ziemię Hewila, gdzie się rodzi złoto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'A złoto ziemi onej jest wyborne. Tamże jest Bdellion, i kamień Onychyn.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'A imię rzeki drugiej Gihon; ta okrąża wszystkę ziemię Murzyńską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Imię zaś rzeki trzeciej Chydekel, ta płynie na wschód słońca ku Asyryi. A rzeka czwarta jest Eufrates.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Wziął tedy Pan Bóg człowieka, i postawił go w sadzie Eden, aby go sprawował, i aby go strzegł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Tedy rozkazał Pan Bóg człowiekowi, mówiąc: Z każdego drzewa sadu jeść będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Ale z drzewa wiadomości dobrego i złego, jeść z niego nie będziesz; albowiem dnia, którego jeść będziesz z niego, śmiercią umrzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Rzekł też Pan Bóg: Nie dobrze być człowiekowi samemu; uczynię mu pomoc, która by była przy nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'A gdy stworzył Pan Bóg z ziemi wszelki zwierz polny, i wszelkie ptactwo niebieskie, tedy je przywiódł do Adama, aby obaczył jakoby je nazwać miał; a jakoby nazwał Adam każdą duszę żywiącą, tak aby było imię jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Tedy dał Adam imiona wszystkiemu bydłu, i ptactwu niebieskiemu, i wszelkiemu zwierzowi polnemu. Lecz Adamowi nie była znaleziona pomoc, która by przy nim była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Tedy przypuścił Pan Bóg twardy sen na Adama, i zasnął; i wyjął jedno żebro jego, i napełnił ciałem miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'I zbudował Pan Bóg z żebra onego, które wyjął z Adama, niewiastę, i przywiódł ją do Adama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'I rzekł Adam: Toć teraz jest kość z kości moich, i ciało z ciała mego; dla tegoż będzie nazwana mężatką, bo ona z męża wzięta jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Przetoż opuści człowiek ojca swego i matkę swoję, a przyłączy się do żony swojej, i będą jednem ciałem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'A byli oboje nadzy, Adam i żona jego; a nie wstydzili się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'A wąż był chytrzejszy nad wszystkie zwierzęta polne, które był uczynił Pan Bóg; ten rzekł do niewiasty: Także to, że wam Bóg rzekł: Nie będziecie jedli z każdego drzewa sadu tego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'I rzekła niewiasta do węża: Z owocu drzewa sadu tego pożywamy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Ale z owocu drzewa, które jest w pośród sadu, rzekł Bóg: Nie będziecie jedli z niego, ani się go dotykać będziecie, byście snać nie pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'I rzekł wąż do niewiasty: Żadnym sposobem śmiercią nie pomrzecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Ale wie Bóg, że któregokolwiek dnia z niego jeść będziecie, otworzą się oczy wasze; a będziecie jako bogowie, znający dobre i złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Widząc tedy niewiasta, iż dobre było drzewo ku jedzeniu; a iż było wdzięczne na wejrzeniu, a pożądliwe drzewo dla nabycia umiejętności, wzięła z owocu jego, i jadła; dała też i mężowi swemu, który z nią był; i on też jadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Zatem otworzyły się oczy obojga, i poznali, że byli nagimi; i spletli liście figowe, a poczynili sobie zasłony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'A wtem usłyszeli głos Pana Boga chodzącego po sadzie z wiatrem dniowym; i skrył się Adam, i żona jego od oblicza Pana Boga między drzewa sadu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'I zawołał Pan Bóg Adama, i rzekł mu: Gdzieżeś?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Który odpowiedział: Głos twój usłyszałem w sadzie, i zlękłem się dla tego, żem nagi, i skryłem się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'I rzekł Bóg: Któż ci pokazał, żeś jest nagim? izaliś nie jadł z drzewa onego, z któregom zakazał tobie, abyś nie jadł?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Tedy rzekł Adam: Niewiasta, którąś mi dał, aby była ze mną, ona mi dała z tego drzewa, i jadłem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'I rzekł Pan Bóg do niewiasty: Cóżeś to uczyniła? i rzekła niewiasta: Wąż mię zwiódł, i jadłam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Tedy rzekł Pan Bóg do węża: Iżeś to uczynił, przeklętym będziesz nad wszystkie zwierzęta, i nad wszystkie bestyje polne; na brzuchu twoim czołgać się będziesz, a proch żreć będziesz po wszystkie dni żywota twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Nieprzyjaźń też położę między tobą i niewiastą, i między nasieniem twoim, i między nasieniem jej; to potrze tobie głowę, a ty mu potrzesz piętę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'A do niewiasty rzekł: Obficie rozmnożę boleści twoje, i poczęcia twoje; w boleści rodzić będziesz dzieci, a wola twa poddana będzie mężowi twemu, a on nad tobą panować będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Zaś rzekł do Adama: Iżeś usłuchał głosu żony twojej, a jadłeś z drzewa tego, o któremem ci przykazał, mówiąc: Nie będziesz jadł z niego; przeklęta będzie ziemia dla ciebie, w pracy z niej pożywać będziesz po wszystkie dni żywota twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'A ona ciernie i oset rodzić będzie tobie; i będziesz pożywał ziela polnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'W pocie oblicza twego będziesz pożywał chleba, aż się nawrócisz do ziemi, gdyżeś z niej wzięty; boś proch, i w proch się obrócisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'I nazwał Adam imię żony swej Ewa, iż ona była matką wszystkich żywiących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'I uczynił Pan Bóg Adamowi, i żonie jego odzienie skórzane, i oblókł je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Tedy rzekł Pan Bóg: Oto Adam stał się jako jeden z nas, wiedzący dobre i złe; tedy wyżeńmy go, by snać nie ściągnął ręki swej, i nie wziął z drzewa żywota, i nie jadł, i żyłby na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'I wypuścił go Pan Bóg z sadu Eden, ku sprawowaniu ziemi, z której był wzięty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'A tak wygnał człowieka; i postawił na wschód słońca sadu Eden Cheruby, i miecz płomienisty i obrotny ku strzeżeniu drogi do drzewa żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Potem Adam poznał Ewę, żonę swoję, która poczęła i porodziła Kaina, i rzekła: Otrzymałam męża od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'I porodził zasię brata jego Abla; i był Abel pasterzem owiec, a Kain był rolnikiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'I stało się po wielu dni, iż przyniósł Kain z owocu ziemi ofiarę Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Także i Abel przyniósł z pierworodztw trzód swoich i z tłustości ich; i wejrzał Pan na Abla i na ofiarę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Ale na Kaina i na ofiarę jego nie wejrzał; i rozgniewał się Kain bardzo, i spadła twarz jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Tedy rzekł Pan do Kaina: Przeczżeś się zapalił gniewem a czemu spadła twarz twoja?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Azaż, jeźli dobrze czynić będziesz, nie będziesz wywyższon? a jeźli nie będziesz dobrze czynił, we drzwiach grzech leży; a do ciebie chuć jego będzie, a ty nad nim panować będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'I rozmawiał Kain z Ablem bratem swoim. I stało się, gdy byli na polu, że powstał Kain na Abla brata swego, i zabił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'I rzekł Pan do Kaina: Gdzież jest Abel brat twój? który odpowiedział: Nie wiem; izalim ja stróżem brata mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'I rzekł Bóg: Cóżeś uczynił? Głos krwi brata twego woła do mnie z ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Teraz tedy przeklętym będziesz na ziemi, która otworzyła usta swe, aby przyjęła krew brata twego z ręki twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Gdy będziesz sprawował ziemię, nie wyda więcej mocy swej tobie; tułaczem, i biegunem będziesz na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Tedy rzekł Kain do Pana: Większa jest nieprawość moja, niżby mi ją odpuścić miano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Oto mię dziś wyganiasz z oblicza tej ziemi, a przed twarzą twoją skryję się, i będę tułaczem, i biegunem na ziemi; i stanie się, że ktokolwiek mię znajdzie, zabije mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'I rzekł mu Pan: Zaiste, ktobykolwiek zabił Kaina, siedmioraką odniesie pomstę. I włożył Pan na Kaina piętno, aby go nie zabijał, ktobykolwiek znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Tedy odszedł Kain od oblicza Pańskiego, i mieszkał w ziemi Nod, na wschód słońca od Eden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'I poznał Kain żonę swą, która poczęła, i porodziła Enocha; i zbudował miasto, i nazwał imię miasta tego imieniem syna swego, Enoch.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'I urodził się Enochowi Irad, a Irad spłodził Mawiaela, a Mawiael spłodził Matusaela, a Matusael spłodził Lamecha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'I pojął sobie Lamech dwie żony; imię jednej, Ada, a imię drugiej, Sella.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Tedy urodziła Ada Jabala, który był ojcem mieszkających w namieciech, i pasterzów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'A imię brata jego było Jubal, który był ojcem wszystkich grających na harfie, i na muzyckiem naczyniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Sella też urodziła Tubalkaina, rzemieślnika wszelkiej roboty, od miedzi i od żelaza. A siostra Tubalkainowa była Noema.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Tedy rzekł Lamech żonom swym, Adzie i Selli: Słuchajcie głosu mego, żony Lamechowe, posłuchajcie słów moich; zabiłbym ja męża za zranienie moje, i młodzieńca za siność moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Jeźlić siedmiokroć mścić się będą za Kaina, tedyć za Lamecha siedemdziesiąt i siedem kroć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'I poznał jeszcze Adam żonę swą, która urodziła syna, i nazwała imię jego Set, mówiąc: Dał mi Bóg inne potomstwo miasto Abla, którego zabił Kain.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Setowi też urodził się syn, i nazwał imię jego Enos. Na ten czas poczęto wzywać imienia Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Teć są księgi rodzajów Adamowych. W dzień, którego stworzył Bóg człowieka, na podobieństwo Boże uczynił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Mężczyznę i niewiastę stworzył je; i błogosławił im, i nazwał imię ich, człowiek, w dzień, którego są stworzeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'I żył Adam sto i trzydzieści lat, i spłodził syna na podobieństwo swoje, i na wyobrażenie swoje, i nazwał imię jego Set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'I było dni Adamowych po spłodzeniu Seta osiem set lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'A tak było wszystkich dni Adamowych, których żył, dziewięć set lat i trzydzieści, lat i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'A Set żył sto lat i pięć lat, i spłodził Enosa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'I żył Set po spłodzeniu Enosa, osiem set lat, i siedem lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'I było wszystkich dni Setowych dziewięć set lat, i dwanaście lat, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'A Enos żył dziewięćdziesiąt lat, i spłodził Kenana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'I żył Enos po spłodzeniu Kenana, osiem set lat, i piętnaście lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Było tedy wszystkich dni Enosowych dziewięć set lat, i pięć lat, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Kenan też żył siedemdziesiąt lat, i spłodził Mahalaleela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'I żył Kenan po spłodzeniu Mahalaleela osiem set lat, i czterdzieści lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Było tedy wszystkich dni Kenanowych dziewięć set i dziesięć lat, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'A Mahalaleel żył sześćdziesiąt i pięć lat, i spłodził Jareda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'A po spłodzeniu Jareda, żył Mahalaleel osiem set lat i trzydzieści lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'I było wszystkich dni Mahalaleelowych osiem set dziewięćdziesiąt i pięć lat, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Żył też Jared sto sześćdziesiąt i dwa lata, i spłodził Enocha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'I żył Jared po spłodzeniu Enocha osiem set lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'I było wszystkich dni Jaredowych dziewięć set sześćdziesiąt i dwa lat, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'A Enoch żył sześćdziesiąt lat, i pięć, i spłodził Matuzalema.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'I chodził Enoch z Bogiem po spłodzeniu Matuzalema trzy sta lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'I było wszystkich dni Enochowych trzy sta sześćdziesiąt i pięć lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'I chodził Enoch z Bogiem, a nie było go więcej, bo go wziął Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'I żył Matuzalem sto osiemdziesiąt i siedem lat, i spłodził Lamecha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'I żył Matuzalem po spłodzeniu Lamecha siedem set osiemdziesiąt lat, i dwa lata, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'I było wszystkich dni Matuzalemowych dziewięć set sześćdziesiąt i dziewięć lat, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'A Lamech żył sto osiemdziesiąt i dwa lat, i spłodził syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'I nazwał imię jego Noe, mówiąc: Ten nas pocieszy z pracy naszej, i z roboty rąk naszych, z strony ziemi, którą Pan przeklął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Potem żył Lamech po spłodzeniu Noego, pięć set dziewięćdziesiąt lat i pięć, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'I było wszystkich dni Lamechowych siedem set siedemdziesiąt i siedem lat, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'A gdy było Noemu pięć set lat, spłodził Noe Sema, Chama, i Jafeta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'I stało się, gdy się ludzie poczęli rozmnażać na ziemi, a córki się im zrodziły;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Że, widząc synowie Boży córki ludzkie, iż były piękne, brali je sobie za żony, ze wszystkich, które sobie upodobali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'I rzekł Pan: Nie będzie się wadził duch mój z człowiekiem na wieki, gdyż jest ciałem; i będą dni jego sto i dwadzieścia lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'A byli olbrzymowie na ziemi w one dni; nawet i potem, gdy weszli synowie Boży do córek ludzkich, rodziły im syny. A cić są mocarze, którzy od wieku byli mężowie sławni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'A widząc Pan, że wielka była złość ludzka na ziemi, a wszystko zmyślanie myśli serca ich tylko złe było po wszystkie dni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Żałował Pan, że uczynił człowieka na ziemi, i bolał w sercu swem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'I rzekł Pan: Wygładzę człowieka, któregom stworzył, z oblicza ziemi, od człowieka aż do bydlęcia, aż do gadziny, i aż do ptastwa niebieskiego; bo mi żal, żem je uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Ale Noe znalazł łaskę w oczach Pańskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Teć są rodzaje Noego: Noe mąż sprawiedliwy, doskonałym był za wieku swego; z Bogiem chodził Noe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'I spłodził Noe trzech synów, Sema, Chama, i Jafeta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Ale ziemia popsowała się była przed Bogiem; i napełniła się nieprawością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Tedy wejrzał Bóg na ziemię, a oto popsowana była (albowiem zepsowało było wszelkie ciało drogę swoję na ziemi).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'I rzekł Bóg do Noego: Koniec wszelkiego ciała przyszedł przed oblicze moje, bo napełniona jest ziemia nieprawością od oblicza ich; przetoż je wytracę z ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Uczyń sobie korab z drzewa Gofer; przegrody poczynisz w korabiu, i oblejesz go wewnątrz i zewnątrz smołą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'A uczynisz go na ten kształt: Trzy sta łokci będzie długość korabia; pięćdziesiąt łokci szerokość jego, a trzydzieści łokci wysokość jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Okno uczynisz w korabiu; a na łokieć wywiedziesz je wzwyż, i drzwi korabiu w boku jego postawisz; piętra spodnie wtóre i trzecie uczynisz w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'A Ja oto, Ja przywiodę potop wód na ziemię, ku wytraceniu wszelkiego ciała, w którem jest duch żywota pod niebem; wszystko, cokolwiek jest na ziemi, pozdycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Ale z tobą postanowię przymierze moje; i wnijdziesz do korabia, ty i synowie twoi, i żona twoja, i żony synów twoich z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'I ze wszech zwierząt wszelkiego ciała po dwojgu ze wszech, wprowadzisz do korabia, aby żywo zachowane były z tobą, samiec i samica będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Z ptastwa według rodzaju jego, i z bydła według rodzaju jego, i z wszelkiej gadziny ziemskiej według rodzaju jej, po dwojgu z każdego rodzaju wnijdą z tobą, aby żywe zostały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'A ty weźmiesz z sobą wszelkiego pokarmu, który się jeść godzi, a zbierzesz do siebie, i będzie tobie i onym na pokarm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'I uczynił Noe według wszystkiego; jako mu rozkazał Bóg, tak uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'I rzekł Pan do Noego: Wnijdź ty i wszystek dom twój do korabia; bom cię widział sprawiedliwym przed obliczem mojem w narodzie tym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Z każdego bydlęcia czystego weźmiesz z sobą siedmioro a siedmioro, samca i samicę jego; ale z zwierząt nieczystych po dwojgu, samca i samicę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Także z ptastwa niebieskiego siedmioro a siedmioro, samca i samicę, aby żywe zachowane było nasienie na wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Albowiem jeszcze po siedmiu dniach spuszczę deszcz na ziemię, przez czterdzieści dni i czterdzieści nocy, i wygładzę wszystko stworzenie, którem uczynił, z oblicza ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Uczynił tedy Noe według wszystkiego, jako mu był Pan rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'A Noemu było sześć set lat, gdy przyszedł potop wód na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'I wszedł Noe, i synowie jego, i żona jego, i żony synów jego z nim, do korabia, dla potopu wód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Z zwierząt też czystych, i z zwierząt, które nie były czyste, i z ptastwa, i ze wszystkiego, co się płaza po ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Po parze weszło do Noego do korabia, to jest samiec i samica, jako był rozkazał Bóg Noemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'I stało się po siedmiu dniach, iż wody potopu przyszły na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Roku sześćsetnego wieku Noego, miesiąca wtórego, siedemnastego dnia tegoż miesiąca, w tenże dzień przerwały się wszystkie źródła przepaści wielkiej, i okna niebieskie otworzyły się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'I padał deszcz na ziemię, czterdzieści dni i czterdzieści nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Onegoż dnia wszedł Noe i Sem i Cham i Jafet, synowie Noego, i żona Noego, i trzy żony synów jego z nim do korabia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Oni, i wszelki zwierz według rodzaju swego, i wszelkie bydlę według rodzaju swego, i wszelka gadzina płazająca się po ziemi, według rodzaju swego, i wszystko latające według rodzaju swego, i wszelki ptak, i wszelka rzecz skrzydlasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'A tak weszło do Noego w korab po parze z każdego ciała, w którem był duch żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'A które weszły, samiec i samica z każdego ciała weszły, jako mu Bóg rozkazał. I zamknął Pan za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Był tedy potop przez czterdzieści dni na ziemi, i wezbrały wody i podniosły korab, i był podniesiony od ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'I wzmogły się wody, a wezbrały bardzo nad ziemią, i pływał korab po wodach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Tedy się wody wzmogły nader bardzo nad ziemią, i okryły się wszystkie góry wysokie, które były pod wszystkiem niebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Piętnaście łokci wzwyż wezbrały wody, gdy były okryte góry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Zaginęło tedy wszelkie ciało ruchające się na ziemi, i z ptaków, i z bydła, i z zwierząt, i wszelkiej gadziny płazającej się po ziemi, i wszyscy ludzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Wszystko, którego tchnący duch żywota był w nozdrzach jego, ze wszystkiego, co na suszy było, pomarło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Tak wygładził Bóg wszystko stworzenie, które było na ziemi, od człowieka aż do bydlęcia, aż do gadziny, i aż do ptastwa niebieskiego, wygładzone są z ziemi, i został tylko Noe i którzy z nim byli w korabiu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'I trwały wody nad ziemią sto i pięćdziesiąt dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'I wspomniał Bóg na Noego i na wszystkie zwierzęta, i na wszystko bydło, które było z nim w korabiu; i przywiódł Bóg wiatr na ziemię, a zastanowiły się wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'I zawarte są źródła przepaści, i okna niebieskie, i zahamowany jest deszcz z nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'I wróciły się wody z wierzchu ziemi idąc, i wracając się; i opadły wody po skończeniu stu i pięćdziesięciu dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'I odpoczął korab miesiąca siódmego, siedemnastego dnia tegoż miesiąca, na górach Ararad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'A wody ściekały i opadały, aż do dziesiątego miesiąca, dziesiątego bowiem miesiąca, pierwszego dnia, okazały się wierzchy gór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'I stało się po skończeniu czterdziestu dni, otworzył Noe okno korabia, które był uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'I wypuścił kruka, który tam i sam latając, zasię się wracał, aż oschły wody na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Potem wypuścił gołębicę od siebie, aby obaczył, jeźli opadły wody z wierzchu ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Ale nie znalazłszy gołębica odpocznienia stopie nogi swojej, wróciła się do niego do korabia; jeszcze bowiem wody były po wszystkiej ziemi; i wyciągnąwszy rękę swoję, wziął ją, i wniósł ją do siebie do korabia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'A poczekawszy jeszcze drugie siedem dni, po wtóre wypuścił gołębicę z korabia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'I wróciła do niego gołębica pod wieczór; a oto, różdżka oliwy urwana w uściech jej; a tak poznał Noe, że opadły wody z wierzchu ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'I czekał jeszcze drugie siedem dni, i wypuścił gołębicę, która się więcej nie wróciła do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'I stało się sześćsetnego i pierwszego roku, miesiąca pierwszego, dnia pierwszego, oschły wody z ziemi; i zdjął Noe przykrycie korabia, a ujrzał, że osechł wierzch ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'A miesiąca wtórego, dwudziestego siódmego dnia tegoż miesiąca, oschła ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'I rzekł Bóg do Noego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Wynijdź z korabia, ty, i żona twoja, i synowie twoi, i żony synów twoich z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Wszystkie zwierzęta, które są z tobą, z wszelkiego ciała, z ptastwa i z bydła, i z wszelkiej gadziny, płazającej się po ziemi, wywiedź z sobą, a niech się rozpładzają na ziemi, i niech rosną, i rozmnażają się na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'I wyszedł Noe, i synowie jego, i żona jego, i żony synów jego z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Wszelkie zwierzę, wszelka gadzina, i wszelkie ptactwo, wszystko co się płaza po ziemi, według rodzajów swoich, wyszły z korabia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Zatem zbudował Noe ołtarz Panu, i wziął z każdego bydła czystego, i z każdego ptastwa czystego, i ofiarował całopalenia na ołtarzu onym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'I zawoniał Pan wonności wdzięcznej, i rzekł Pan w sercu swem: Nie będę więcej przeklinał ziemi dla człowieka: albowiem myśl serca człowieczego zła jest od młodości jego, nie zatracę więcej wszystkiego co żyje, jakom teraz uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'A póki ziemia trwać będzie, siew i żniwo, i zimno, i gorąco, i lato, i zima, i dzień, i noc nie ustaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'I błogosławił Bóg Noego, i syny jego, i rzekł im: Rozradzajcie się, i rozmnażajcie się, i napełniajcie ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'A strach wasz i bojaźń wasza będzie nad wszelkiem zwierzęciem ziemi, i nad wszystkiem ptastwem niebieskiem, i nad wszystkiem, co się rucha na ziemi, i nad wszystkiemi rybami morskiemi: w rękę waszę podane są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Wszystko co się rucha, i co żyje, wam będzie na pokarm, jako jarzynę zieloną, dałem wam to wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Wszakże mięsa z duszą jego, która jest krew jego, jeść nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'A zaiste krwi waszej, dusz waszych szukać będę, z ręki każdej bestyi szukać jej będę: także z ręki człowieczej, z ręki każdego brata jego będę szukał duszy człowieczej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Kto wyleje krew człowieczą, przez człowieka krew jego wylana będzie: bo na wyobrażenie Boże uczynion jest człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'A wy rozradzajcie się, i rozmnażajcie się, rozpładzajcie się na ziemi, i mnóżcie się na niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Tedy rzekł Bóg do Noego, i do synów jego z nim, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'A Ja, oto Ja stanowię przymierze moje z wami, i z nasieniem waszem po was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'I z każdą duszą żywiącą, która jest z wami: w ptastwie, w bydle, i w każdem zwierzęciu ziemi, które są z wami, ze wszystkich, co wyszły z korabia, aż do każdego zwierzęcia na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'I postanowię przymierze moje z wami; a nie będzie zatracone więcej wszelkie ciało wodami potopu; i nie będzie więcej potop na skażenie ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Tedy rzekł Bóg: To jest znak przymierza, który Ja dawam między mną i między wami, i między każdą duszą żywiącą, która jest z wami, w rodzaje wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Łuk mój położyłem na obłoku, który będzie na znak przymierza między mną, i między ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'I stanie się, gdy wzbudzę ciemny obłok nad ziemią, a ukaże się łuk na obłoku:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'Że wspomnę na przymierze moje, które jest między mną i między wami, i między każdą duszą żywiącą w każdem ciele; i nie będą więcej wody na potop, ku wytraceniu wszelkiego ciała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Będzie tedy łuk on na obłoku, i wejrzę nań, abym wspomniał na przymierze wieczne, między Bogiem i między wszelką duszą żywiącą w każdem ciele, które jest na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Zatem rzekł Bóg do Noego: Tenci jest znak przymierza, którem postanowił między mną, i między wszelkiem ciałem, które jest na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'A byli synowie Noego, którzy wyszli z korabia, Sem, i Cham, i Jafet; a Cham jest ojcem Chanaan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Ci trzej synowie Noego, przez które się napełniła ludem wszystka ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Tedy Noe począł uprawiać ziemię, i nasadził winnicę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Potem pił wino; a upiwszy się, odkrył się w namiocie swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'A ujrzawszy Cham, ojciec Chanaanów, nagość ojca swego, oznajmił to dwom braciom swoim na dworze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Tedy wziąwszy Sem i Jafet szatę, a włożywszy ją oba na ramiona swe, szli wspak, i zakryli nagość ojca swego; a oblicza ich odwrócone były, że nagości ojca swego nie widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'A ocuciwszy się Noe z wina swego, gdy się dowiedział, co mu uczynił syn jego młodszy, rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Przeklęty Chanaan, sługą sług braci swojej będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Rzekł też: Błogosławiony Pan Bóg Semów, a niech będzie Chanaan sługą ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Niech rozszerzy Bóg Jafeta, i niech mieszka w namieciech Semowych a niech Chanaan sługą ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'I żył Noe po potopie trzy sta lat, i pięćdziesiąt lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'I było wszystkich dni Noego, dziewięć set lat, i pięćdziesiąt lat, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Teć są rodzaje synów Noego, Sema, Chama i Jafeta, którym się narodziło synów po potopie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Synowie Jafetowi Gomer, i Magog, i Madai, i Jawan, i Tubal, i Mesech, i Tyras.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'A synowie Gomerowi: Aschenaz, i Ryfat, i Togorma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'A synowie Jawanowi: Elisa, i Tarsis, Cytym, i Dodanim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Od tych rozdzielone są wyspy narodów po swych ziemiach; każdy według języka swego, i według pokolenia swego, w narodziech swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'A synowie Chamowi: Chus, i Micraim, i Put, i Chanaan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Synowie zaś Chusowi: Seba, i Hewila, i Sabta, i Regma, i Sabtacha. A synowie Regmy: Seba i Dedan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'A Chus spłodził Nemroda, który począł być możnym na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Ten był możnym myśliwcem przed obliczem Pańskiem; przetoż się mówi: Jako Nemrod możny myśliwiec przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'A początek królestwa jego był Babel, i Erech, i Achad, i Chalne w ziemi Senaar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Z tej ziemi wyszedł Assur, i zbudował Niniwe, i Rechobot miasto, i Chale.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Także Resen, między Niniwe i między Chale; to miasto jest wielkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Micraim też spłodził Ludyma, i Hananima, i Laubima, i Neftuhyma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'I Patrusyma, i Chasluchyma, (z których poszli Filistynowie,) i Kaftoryma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Chanaan też spłodził Sydona pierworodnego swego, i Heta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'I Jebusa, i Amorra, i Gergesa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'I Hewa, i Archa, i Syma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'I Arada, i Samara, i Chamata, skąd się potem rozrodziły domy Chananejczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'A granice Chananejskie były od Sydonu idąc do Gerary, aż do Gazy, aż wnijdziesz do Sodomy i Gomorry, i Adamy, i Seboima, aż do Lazy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Ci są synowie Chamowi w familijach swych, w językach swych, w ziemiach swych, w narodziech swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'A Semowi, ojcu wszystkich synów Heberowych, bratu Jafeta starszego, urodzili się synowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Synowie Semowi: Elam i Assur, i Arfachsad, i Lud, i Aram.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Synowie zaś Aramowi: Hus, i Hul, i Geter, i Mesech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arfachsad zaś spłodził Selecha, a Selech spłodził Hebera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'A Heberowi urodzili się dwa synowie: imię jednemu Faleg, iż za dni jego rozdzielona jest ziemia; a imię brata jego Jektan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Jektan też spłodził Elmodada, i Salefa, i Hasarmota, i Jarecha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'I Adorama, i Uzala, i Dekla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'I Hebala, i Abymaela, i Sebaja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'I Ofira, i Hewila, i Jobaba: ci wszyscy są synowie Jektanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'A było mieszkanie ich od Mescha idąc, do góry Sefar na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Cić są synowie Semowi w domach swych, w językach swych, w ziemiach swych, w narodziech swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Teć są domy synów Noego, według pokolenia ich, i w narodziech ich, i od nich rozdzielone są narody na ziemi po potopie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'A była wszystka ziemia jednego języka, i jednej mowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'I stało się, gdy wyszli od wschodu słońca, znaleźli równinę w ziemi Senaar, i mieszkali tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'I rzekł jeden do drugiego: Nuże naczyńmy cegły i wypalmy ją ogniem: i mieli cegłę miasto kamienia, a glinę iłowatą mieli miasto wapna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Potem rzekli: Nużeż, zbudujmy sobie miasto i wieżą, której by wierzch dosięgał do nieba, a uczyńmy sobie imię; byśmy się snać nie rozproszyli po obliczu wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Tedy Pan zstąpił, aby oglądał miasto ono, i wieżą, którą budowali synowie ludzcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'I rzekł Pan: Oto lud jeden, i język jeden tych wszystkich; a toć jest zaczęcie dzieła ich, a teraz nie zabroni im nikt wszystkiego, co zamyślili uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Przetoż zstąpmy, a pomieszajmy tam język ich, aby jeden drugiego języka nie zrozumiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'A tak rozproszył je Pan stamtąd po obliczu wszystkiej ziemi; i przestali budować miasta onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Przetoż nazwał imię jego Babel; iż tam pomieszał Pan język wszystkiej ziemi; i stamtąd rozproszył je Pan po obliczu wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Teć są rodzaje Semowe: Sem gdy miał sto lat, spłodził Arfachsada we dwa lata po potopie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'I żył Sem po spłodzeniu Arfachsada pięć set lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arfachsad też żył trzydzieści i pięć lat, i spłodził Selecha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'I żył Arfachsad po spłodzeniu Selecha cztery sta lat, i trzy lata, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Selech zaś żył trzydzieści lat, i spłodził Hebera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'I żył Selech po spłodzeniu Hebera cztery sta lat, i trzy lata, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'I żył Heber trzydzieści lat i cztery, i spłodził Pelega.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Żył też Heber po spłodzeniu Pelega, cztery sta lat, i trzydzieści lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Żył też Peleg trzydzieści lat, i spłodził Rehu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'I żył Peleg po spłodzeniu Rehu dwieście lat, i dziewięć lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Także Rehu żył trzydzieści lat, i dwa, i spłodził Saruga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'I żył Rehu po spłodzeniu Saruga dwieście lat, i siedem lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Sarug zaś żył trzydzieści lat, i spłodził Nachora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'I żył Sarug po spłodzeniu Nachora dwieście lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Także Nachor żył dwadzieścia i dziewięć lat, i spłodził Tarego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'I żył Nachor po spłodzeniu Tarego sto lat i dziewiętnaście lat, i spłodził syny i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'I żył Tare siedemdziesiąt lat, i spłodził Abrama, Nachora i Harana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'A teć są rodzaje Tarego: Tare spłodził Abrama, Nachora i Harana. Haran zaś spłodził Lota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'I umarł Haran przed obliczem Tarego ojca swego, w ziemi narodzenia swego, w Ur Chaldejskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'I pojęli Abram i Nachor sobie żony: imię żony Abramowej było Saraj, a imię żony Nachorowej Melcha, córka Harana, ojca Melchy, i ojca Jeschy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'A była Saraj niepłodna, i nie miała dziatek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Wziął tedy Tare Abrama syna swego, i Lota syna Haranowego, wnuka swego, i Saraj niewiastę swoję, żonę Abrama syna swego; i wyszli społu z Ur Chaldejskiego, aby szli do ziemi Chananejskiej; a przyszli aż do Haranu, i mieszkali tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'I było dni Tarego dwieście lat, i pięć lat; i umarł Tare w Haranie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'I rzekł Pan do Abrama: Wynijdź z ziemi twej, i od rodziny twojej, i z domu ojca twego, do ziemi, którąć pokażę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'A uczynię cię w naród wielki, i będęć błogosławił, i uwielbię imię twoje, i będziesz błogosławieństwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'I będę błogosławił błogosławiącym tobie; a przeklinające cię przeklinać będę: i będą błogosławione w tobie wszystkie narody ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Tedy wyszedł Abram, jako mu rozkazał Pan. Poszedł też z nim i Lot. A było Abramowi siedmdziesiąt lat i pięć lat, gdy wyszedł z Haran.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Wziął też Abram Saraj żonę swoję, i Lota syna brata swego, i wszystkę swą majętność, której nabyli, i dusze, których nabyli w Haranie, i wyszli, aby szli do ziemi Chananejskiej; i przyszli do ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Tedy przeszedł Abram ziemię onę aż do miejsca Sychem, i aż do równiny Morech; a Chananejczyk na ten czas był w onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'I ukazał się Pan Abramowi, i rzekł: Nasieniu twemu dam ziemię tę; i zbudował tam ołtarz Panu, który mu się ukazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'A przeszedł stamtąd do góry na wschód Betela, i rozbił tam namiot swój, mając Betel od zachodu, a Haj od wschodu; i zbudował tam ołtarz Panu, i wzywał imienia Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Potem ruszył się Abram idąc, i ciągnąc ku południu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'A był głód w ziemi onej: przeto zstąpił Abram do Egiptu, aby tam był gościem do czasu, ciężki bowiem był głód w ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'I stało się, gdy już blisko był, aby wszedł do Egiptu, rzekł do Sarai, żony swej: Oto teraz wiem, żeś niewiasta piękna na wejrzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'I stanie się, że gdy cię obaczą Egipczanie, rzeką: Żona to jego; i zabiją mię, a ciebie żywo zostawią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Mów, proszę, żeś jest siostrą moją, aby mi dobrze było dla ciebie, i żywa została dla ciebie dusza moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'I stało się, gdy wszedł Abram do Egiptu, ujrzeli Egipczanie niewiastę onę, iż była bardzo piękną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Widzieli ją też książęta Faraonowe, i chwalili ją przed nim; i wzięto onę niewiastę do domu Faraonowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Który Abramowi dobrze czynił dla niej; i miał Abram owce, i woły, i osły i sługi, i służebnice, i oślice, i wielbłądy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Ale uderzył Pan Faraona plagami wielkiemi, i dom jego dla Sarai, żony Abramowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Przetoż wezwał Farao Abrama, i rzekł: Cóżeś mi to uczynił? czemuś mi nie oznajmił, że to żona twoja?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Przeczżeś powiedział, siostra to moja? i wziąłem ją sobie za żonę; a teraz, oto żona twoja, weźmijże ją, a idź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'I przykazał o nim Farao mężom, i puścili go wolno i żonę jego, i wszystko, co było jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'A tak wyszedł Abram z Egiptu, on i żona jego, i wszystko co miał, i Lot z nim, ku południowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'A Abram był bardzo bogaty w bydło, w srebro, i w złoto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'I szedł gościńcami swemi, od południa, i aż do Betel, aż do onego miejsca, gdzie przedtem był namiot jego, między Betel i między Haj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'Do miejsca onego ołtarza, który tam był przedtem uczynił; i wzywał tam Abram imienia Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Także Lot, który chodził z Abramem, miał owce, i woły i namioty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'I nie mogła ich znieść ona ziemia, żeby społem mieszkali, albowiem była majętność ich wielka, tak, że nie mogli mieszkać pospołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'I wszczął się poswarek między pasterzami trzody Abramowej, i między pasterzami trzody Lotowej. Chananejczyk i Ferezejczyk mieszkał na on czas w ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Rzekł tedy Abram do Lota: Niech proszę nie będzie swaru między mną i między tobą, także między pasterzami moimi i między pasterzami twoimi, ponieważeśmy bracia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Izali nie wszystka ziemia jest przed obliczem twojem? odłącz się proszę ode mnie; jeźli w lewą pójdziesz ja pójdę w prawą, a jeźli ty w prawą, ja się udam w lewą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Tedy podniósłszy Lot oczy swe, obaczył wszystkę równinę nad Jordanem, iż wszystka wilgotna była przedtem, niż zatracił Pan Sodomę i Gomorrę, jako sąd Pański, i jako ziemia Egipska, idąc do Zoar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'I obrał sobie Lot wszystkę onę równinę nad Jordanem, i odszedł Lot ku wschodu słońca, i rozłączyli się bracia jeden od drugiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram mieszkał w ziemi Chananejskiej, a Lot mieszkał w miejscach onej równiny, i rozbił namiot aż do Sodomy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Ale ludzie w Sodomie byli źli i wielcy grzesznicy przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'I rzekł Pan do Abrama, potem gdy się odłączył Lot od niego: Podnieś teraz oczy swe, a spojrzyj z miejsca, na któremeś teraz na północy, i na południe, i na wschód, i na zachód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Wszystkę bowiem ziemię, którą ty widzisz, dam tobie, i nasieniu twemu aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'A rozmnożę nasienie twoje jako proch ziemi; bo jeźli kto będzie mógł zliczyć proch ziemi, tedy i nasienie twoje zliczone będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Wstańże, schodź tę ziemię wzdłuż i wszerz, bo ją tobie dam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Ruszywszy się tedy z namiotem Abram, przyszedł i mieszkał w równinach Mamre, które są w Hebron i zbudował tam ołtarz Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'I stało się za dni Amrafela, króla Senaarskiego, Aryjocha, króla Ellasarskiego, Chodorlahomera, króla Elamskiego i Tydala, króla Goimskiego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Że podnieśli wojnę przeciw Borowi królowi Sodomskiemu, i przeciw Bersie królowi Gomorskiemu, i Senaabowi królowi Adamackiemu, i Semeberowi królowi Seboimskiemu, i królowi Belamskiemu, to jest Zoarskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Wszyscy ci zaciągnęli się w dolinę Syddym, ta jest teraz morzem słonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Bo ci dwanaście lat służyli Chodorlahomerowi, a trzynastego roku odstąpili od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'A tak roku czternastego wyciągnął Chodorlahomer z królmi, którzy z nim byli, i poraził Rafaimy w Astarot Karnaimie, i Zuzymy w Hamie, i Emimy w Sawie Karyjataim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'Także Chorajczyki na górze ich Seir, aż do równiny Paran, która jest przy puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Potem się wrócili, i przyciągnęli do En Myspat, która jest Kades, i wybili wszystkę krainę Amalekitów; także też Amorrejczyka mieszkającego w Hasesontamar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Tedy wyciągnął król Sodomski, i król Gomorski, i król Adamacki, i król Zeboimski, i król Belamski, to jest Zoarski, i uszykowali się ku bitwie przeciwko im w dolinie Syddym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Przeciwko Chodorlahomerowi królowi Elamskiemu, i Tydalowi królowi Goimskiemu, i Amrafelowi królowi Senaarskiemu, i Aryjochowi królowi Ellasarskiemu, czterech królów, przeciw pięciu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'A w onej dolinie Syddym, było wiele studzien iłowatych; i uciekali król Sodomski i Gomorski, a polegli tam, a którzy zostali, na górę uciekli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'A zabrawszy wszystkę majętność Sodomską, i Gomorską, i wszystkę żywność ich, odciągnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Zabrali też Lota synowca Abramowego, i majętność jego, i poszli; bo on mieszkał w Sodomie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'I przyszedł jeden, który uszedł, i oznajmił to Abramowi Hebrejczykowi, który mieszkał w równinach Mamrego Amorrejczyka, brata Eschola, i brata Anera; ci bowiem uczynili byli przymierze z Abramem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'A usłyszawszy Abram, iż był pojmany brat jego, wyprawił ćwiczonych sług swoich zrodzonych w domu swym, trzy sta i osiemnaście, i gonił je aż do Dan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'I rozdzieliwszy się przypadł na nie w nocy, sam i słudzy jego, i poraził je; i gonił je aż do Hoby, która leży po lewej stronie Damaszku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'I odebrał nazad wszystkę majętność, także i Lota brata swego z majętnością jego wrócił, także i niewiasty, i lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Tedy wyszedł król Sodomski przeciw niemu, gdy się wracał od porażki Chodorlahomera, i królów, którzy z nim byli na dolinie Sawe, która jest doliną królewską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'A Melchisedek, król Salemski, wyniósł chleb i wino; a ten był kapłanem Boga najwyższego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'I błogosławił mu, a rzekł: Błogosławiony Abram od Boga najwyższego, dzierżawcy nieba i ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'I błogosławiony Bóg najwyższy, który podał nieprzyjacioły twe w rękę twoję; i dał mu Abram dziesięcinę ze wszystkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Zatem rzekł król Sodomski do Abrama: Daj mi ludzie, a majętność pobierz sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Tedy rzekł Abram królowi Sodomskiemu: Podniosłem rękę swą ku Panu Bogu najwyższemu, dzierżawcy nieba i ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Że i najmniejszej nitki ani rzemyczka obuwia nie wezmę ze wszystkiego, co twego jest; żebyś nie rzekł: Jam zbogacił Abrama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Okrom tego, co strawili słudzy, i okrom działu mężów, którzy chodzili ze mną, Anera, Eschola, i Mamrego; ci niech wezmą dział swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Po tem wszystkiem stało się słowo Pańskie do Abrama w widzeniu, mówiąc: Nie bój się Abramie, jam tarczą twoją, i nagrodą twoją obfitą wielce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'I rzekł Abram: Panie Boże, cóż mi dasz? gdyż ja schodzę bez dziatek, a sprawcą domu mego jest ten Damaszczeński Eliezer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'I mówił Abram: Otoś mi nie dał potomka, ale oto sługa domu mego dziedzicem moim będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'A oto słowo Pańskie stało się do niego mówiąc: Nie będzie ten dziedzicem twoim; lecz który wynijdzie z żywota twego, ten będzie dziedzicem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'I wywiódł go na dwór, i rzekł: Spojrzyj teraz ku niebu, a zlicz gwiazdy, będzieszli je mógł zliczyć; i rzekł mu: Tak będzie nasienie twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Uwierzył tedy Panu, i poczytano mu to ku sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'I rzekł do niego: Ja Pan, którym cię wywiódł z Ur Chaldejskiego, abym ci dał ziemię tę w osiadłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Zatem rzekł Abram: Panie Boże, po czemże poznam, iż ją odziedziczę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'I odpowiedział mu: Weźmij mi jałowicę trzyletnią, i kozę trzyletnią, i barana trzyletniego, i synogarlicę, i gołąbiątko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Wziął tedy wszystko to i rozciął na poły; a jednę część położył przeciw drugiej, ale ptaków nie rozcinał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Tedy się zleciało ptactwo do onych ścierwów, i odganiał je Abram.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'I stało się, gdy słońce zachodziło, że przypadł twardy sen na Abrama, a oto strach i ciemność wielka przypadła nań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'I rzekł Pan do Abrama: Wiedz wiedząc, iż gościem będzie nasienie twoje w ziemi cudzej, i podbiją je w niewolą, i utrapią je przez cztery sta lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'A wszakże naród on, któremu służyć będą, ja sądzić będę; a potem wynijdą stamtąd z majętnością wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Ale ty pójdziesz do ojców twoich w pokoju; i pogrzebion będziesz w starości dobrej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'A w czwartem pokoleniu tu się wrócą; bo jeszcze nie wypełniła się nieprawość Amorrejczyka aż do tego czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'I stało się, gdy zaszło słońce, a ciemność była, a oto ukazał się piec kurzący się, i pochodnia ognista, która przechodziła między onemi podziały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Onegoż dnia uczynił Pan z Abramem przymierze, mówiąc: Nasieniu twemu dam tę ziemię, od rzeki Egipskiej, aż do rzeki wielkiej, rzeki Eufrates.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Kenejczyka, i Kenezejczyka, i Kadmonejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'I Hettejczyka, i Ferezejczyka, i Rafaimczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'I Amorrejczyka, i Chananejczyka, i Gergezejczyka, i Jebuzejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Saraj tedy, żona Abramowa, nie rodziła mu; ale miała sługę Egipczankę, której imię było Agar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'I rzekła Saraj do Abrama: Oto teraz zamknął mię Pan, abym nie rodziła; wnijdź, proszę, do służebnicy mojej, azali wżdy z niej będę miała dziatki; i usłuchał Abram głosu Sarai.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'I wzięła Saraj, żona Abramowa, Agarę Egipczankę, służebnicę swoję, po dziesięciu latach, jako począł Abram mieszkać w ziemi Chananejskiej; i dała ją Abramowi mężowi swemu za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Tedy wszedł do Agary, i poczęła; a widząc, że poczęła, wzgardzoną była pani jej w oczu jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'I rzekła Saraj do Abrama: Krzywdy mojej tyś winien; jamci dała służebnicę moję na łono twoje; ale ona, widząc że poczęła, wzgardziła mię w oczach swych; niech rozsądzi Pan między mną i między tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'I rzekł Abram do Sarai: Oto służebnica twoja w rękach twoich, czyń z nią coć się zda najlepszego; i trapiła ją Saraj, i uciekła od oblicza jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'I znalazł ją Anioł Pański u źródła wód na puszczy, nad źródłem, przy drodze Sur.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'I rzekł: Agaro, służebnico Sarai, skąd idziesz? i dokąd idziesz? a ona odpowiedziała: Od oblicza Sarai, pani swej, ja uciekam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Rzekł jej Anioł Pański: Wróć się do pani swej, a ukorz się pod ręce jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Rzekł jej zaś Anioł Pański: Mnożąc rozmnożę nasienie twoje, iż nie będzie mogło być zliczone przez mnóstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Potem jej rzekł Anioł Pański: Otoś ty poczęła, i porodzisz syna, a nazwiesz imię jego Ismael; bo usłyszał Pan utrapienie twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Ten będzie srogim człowiekiem: ręka jego przeciwko wszystkim, a ręka wszystkich przeciwko jemu; a przed obliczem wszystkiej braci swej mieszkać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'I nazwała imię Pana, który mówił do niej: Tyś Bóg widzący mię; rzekła bowiem: Izalim tu nie widziała tyłu widzącego mię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Przetoż nazwała studnią onę studnią żywiącego, widzącego mię; a tać jest między Kades, i między Barad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'I urodziła Agar Abramowi syna, i nazwał Abram imię syna swego, którego urodziła Agar, Ismael.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'A Abram miał osiemdziesiąt lat, i sześć lat, gdy mu urodziła Agar Ismaela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'A gdy już było Abramowi dziewięćdziesiąt lat i dziewięć lat, ukazał się Pan Abramowi, i rzekł do niego: Jam jest Bóg Wszechmogący; chodź przed obliczem mojem, a bądź doskonały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'A uczynię przymierze moje, między mną i między tobą, i rozmnożą cię bardzo obficie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Tedy upadł Abram na oblicze swoje, i rzekł do niego Bóg, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Jam jest, oto stanowię przymierze moje z tobą, i będziesz ojcem wielu narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'I nie będzie zwane dalej imię twoje Abram; ale będzie imię twoje Abraham; albowiem ojcem wielu narodów postanowiłem cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'A rozmnożę cię bardzo, i rozkrzewię cię w narody, i królowie z ciebie wynijdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'I utwierdzę przymierze moje między mną, i między tobą, i między nasieniem twojem po tobie, w narodziech ich umową wieczną; żebym ci był Bogiem i nasieniu twemu po tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Dam też tobie, i nasieniu twemu po tobie ziemię, w której teraz jesteś gościem; wszystkę ziemię Chananejską w osiadłość wieczną, i będę Bogiem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Nad to rzekł Bóg Abrahamowi: Ty też przymierza mego przestrzegać będziesz, ty i nasienie twoje po tobie, w narodziech swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'A toć jest przymierze moje, które zachowywać będziecie, między mną, i między wami, i między nasieniem twojem po tobie, aby był obrzezany między wami każdy mężczyzna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Obrzeżcie tedy ciało nieobrzezki waszej; a to będzie znakiem przymierza między mną, i między wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Syn ośmiu dni, będzie obrzezany między wami każdy mężczyzna w narodziech waszych, tak doma narodzony jako i kupiony za pieniądze, od jakiegożkolwiek cudzoziemca, któryby nie był z nasienia twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Koniecznie obrzezany będzie, urodzony w domu twoim, i kupiony za pieniądze twoje; a będzie przymierze moje na ciele waszem, na przymierze wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'A nie obrzezany mężczyzna, którego by nie było obrzezane ciało nieobrzezki jego, będzie wytracona dusza ona z ludu swego; albowiem zgwałcił przymierze moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Potem rzekł Bóg do Abrahama: Sarai, żony twojej, nie będziesz zwał imienia jej Saraj, ale Sara będzie imię jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'I będę jej błogosławił, a dam ci z niej syna; będę jej błogosławił, i będzie rozmnożona w narody, a królowie narodów z niej wynijdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Tedy Abraham padł na oblicze swoje, i roześmiał się, a mówił w sercu swem: Zaż człowiekowi stuletniemu urodzi się syn? i azaż Sara w dziewięćdziesięciu latach porodzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'I rzekł Abraham do Boga: O by tylko Ismael żył przed obliczem twojem!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'I rzekł Bóg: Zaiste, Sara, żona twoja, urodzi tobie syna, i nazowiesz imię jego Izaak; i utwierdzę przymierze moje z nim, umową wieczną, i z nasieniem jego po nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'O Ismaela też wysłuchałem cię: oto, błogosławiłem mu, i rozrodzę go, i rozmnożę go bardzo wielce. Dwanaście książąt spłodzi, i rozkrzewię go w naród wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Ale przymierze moje utwierdzę z Izaakiem, którego tobie urodzi Sara, o tym czasie w roku drugim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'A przestawszy mówić z nim, odszedł Bóg od Abrahama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Tedy wziął Abraham Ismaela, syna swego, i wszystkie urodzone w domu swym, i wszystkie kupione za pieniądze, każdego mężczyznę, z mężów domu Abrahamowego, i obrzezał ciało nieobrzeski ich, onegoż to dnia, jako mówił z nim Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'A Abrahamowi było dziewięćdziesiąt lat i dziewięć, gdy obrzezane było ciało nieobrzeski jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'A Ismaelowi synowi jego było trzynaście lat, gdy obrzezane było ciało nieobrzeski jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Tegoż dnia obrzezany jest Abraham, i Ismael, syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'I wszyscy mężowie domu jego, urodzeni w domu, i kupieni za pieniądze od cudzoziemców, obrzezani są z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Potem ukazał mu się Pan w równinie Mamre, a on siedział we drzwiach namiotu swego, gdy był najgorętszy dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'A podniósłszy oczy swe, obaczył, a oto trzej mężowie stanęli przeciw niemu; i ujrzawszy je, wybieżał przeciwko nim ze drzwi namiotu, i pokłonił się do ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'I rzekł: Panie mój, jeźlim teraz znalazł łaskę w oczach twoich, nie mijaj, proszę, sługi swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Przyniosą trochę wody, a umyjecie nogi wasze, i odpoczniecie pod drzewem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'I przyniosą kęs chleba, a posilicie serce wasze; potem odejdziecie, dla tegoście bowiem przyszli do mnie sługi swego. Tedy rzekli: Tak uczyń, jakoś powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'I pospieszył się Abraham do namiotu do Sary, i rzekł: Spiesz się: rozczyń trzy miarki mąki światłej, a uczyń podpłomyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Abraham zaś szedł do trzody, i wziął cielę młode i wyborne, i dał je słudze, który się pospieszył, i nagotował je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Wziął też masła i mleka, i cielę, które był nagotował, i postawił przed nie, a sam stał przy nich pod drzewem; i jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'I rzekli do niego: Gdzie jest Sara, żona twoja? a on odpowiedział: Oto jest w namiocie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Tedy rzekł Pan: Wrócę się pewnie do ciebie o tymże czasie w rok, a oto, będzie miała syna Sara, żona twoja; a Sara słuchała u drzwi namiotu, które były za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'A Abraham i Sara byli starzy, i zeszli w leciech,; i przestało bywać Sarze według zwyczaju niewiast.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'I roześmiała się Sara sama w sobie, mówiąc: Gdym się zestarzała, rozkoszy zażywać będę; i pan mój zestarzał się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Zatem rzekł Pan do Abrahama: Czemu się rozśmiała Sara, mówiąc: Zaż prawdziwie porodzę, gdym się zestarzała? Izali jest co trudnego u Pana?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'O tymże czasie wrócę do ciebie roku przyszłego, a Sara będzie miała syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'I zaprzała się Sara, mówiąc: Nie śmiałam się; bo się bała. A Pan rzekł: Nie mów tak; boś się śmiała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Potem wstali stamtąd mężowie oni, i obrócili się ku Sodomie; a Abraham szedł z nimi wyprowadzając je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Tedy rzekł Pan: Izali ja zataję przed Abrahamem, co mam uczynić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Ponieważ Abraham pewnie rozmnożon będzie w lud wielki i możny, a w nim będą ubłogosławione wszystkie narody ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Znam go bowiem; przetoż przykaże synom swoim, i domowi swemu po sobie, aby strzegli drogi Pańskiej, i czynili sprawiedliwość i sąd; aby przywiódł Pan na Abrahama, co mu powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Rzekł tedy Pan: Krzyk Sodomy i Gomorry, iż się rozmnożył grzech ich, iż bardzo ociężał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Zstąpię teraz, a obaczę, jeźli się według krzyku tego, który mię doszedł, do końca sprawują; a jeźliż nie, abym się wżdy dowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'I obrócili się stamtąd mężowie, i poszli do Sodomy; lecz Abraham jeszcze stał przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'I przystąpił Abraham, i rzekł: Izali też zatracisz sprawiedliwego z niezbożnym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Jeźli snać będzie pięćdziesiąt sprawiedliwych w tem mieście, izali je wytracisz, a nie przepuścisz miejscu temu dla pięćdziesiąt sprawiedliwych, którzy w niem są?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Niech to nie będzie u ciebie, abyś uczynić miał rzecz takową, i zabił sprawiedliwego z niezbożnym, a żeby był sprawiedliwy, jako niezbożny. Niech to nie będzie u ciebie. Izali Sędzia wszystkiej ziemi nie uczyni sprawiedliwości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Tedy rzekł Pan: Jeźli znajdę w Sodomie pięćdziesiąt sprawiedliwych w samem mieście, odpuszczę wszystkiemu miejscu dla nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'A odpowiadając Abraham rzekł: Otom teraz zaczął mówić do Pana mego, aczem ja proch i popiół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'A jeźliby nie stawało do pięćdziesięciu sprawiedliwych, pięciu, izali wytracisz dla tych pięciu wszystko miasto? I rzekł Pan: Nie wytracę, jeźli tam znajdę czterdziestu i pięciu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Na to jeszcze mówiąc do niego Abraham rzekł: A jeźliby się ich tam znalazło czterdzieści? i odpowiedział: Nie uczynię nic dla tych czterdziestu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'I rzekł Abraham: Proszę niech się nie gniewa Pan mój, że jeszcze mówić będę: A jeźliby się ich tam znalazło trzydzieści? odpowiedział: Nie uczynię, jeźliż tam znajdę trzydziestu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Tedy jeszcze rzekł Abraham: Otom teraz zaczął mówić do Pana mego: A jeźliby się ich tam snać znalazło dwadzieścia? odpowiedział Pan: Nie zatracę i dla tych dwudziestu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Nad to rzekł Abraham: Proszę niech się nie gniewa Pan mój, że jeszcze raz tylko przemówię: A jeźliby się ich tam znalazło dziesięć? Tedy rzekł Pan: Nie wytracę i dla tych dziesięciu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'I poszedł Pan skończywszy rozmowę z Abrahamem; a Abraham wrócił się do miejsca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'I przyszli dwaj Aniołowie do Sodomy w wieczór, a Lot siedział w bramie Sodomskiej. Gdy je tedy ujrzał Lot, wstawszy szedł przeciwko nim, i skłonił się twarzą ku ziemi, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Oto proszę panowie moi, wstąpcie teraz do domu sługi swego, a bądźcie tu na noc, i umyjcie nogi swe; potem rano wstawszy pójdziecie w drogę waszę. Którzy odpowiedzieli: Bynajmniej; ale na ulicy będziemy nocowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Ale on przymuszał ich bardzo, iż się skłonili do niego, i weszli w dom jego; zaczem sprawił im ucztę, i napiekł chleba przaśnego, i jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Lecz pierwej niż oni poszli spać, oto obywatele miasta, mężowie Sodomscy, obstąpili dom, od młodego aż do starego, wszystek lud zewsząd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'I wołali na Lota, i rzekli mu: Gdzie są mężowie, którzy przyszli do ciebie w nocy? wywiedź je do nas, abyśmy je poznali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Tedy wyszedł do nich Lot ze drzwi, i zamknął drzwi za sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'I rzekł: Nie czyńcie proszę, bracia moi, nic złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Oto teraz mam dwie córki, które nie poznały męża; wywiodę je teraz do was, a czyńcie z niemi, co się wam podoba, tylko mężom tym nic nie czyńcie; bo dlatego weszli pod cień dachu mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'A oni rzekli: Pójdźże tam; i mówili: Ten sam przyszedł, aby tu gościem był, a miałby nas sądzić? przetoż gorzej uczynimy tobie, niż onym i czynili gwałt wielki mężowi onemu Lotowi, i przystąpili, aby drzwi wyłamali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Ale mężowie oni, wyciągnąwszy rękę swoję, wwiedli Lota do siebie w dom, i zamknęli drzwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'A męże one, którzy byli u drzwi domu, pozarażali ślepotą, od najmniejszego, aż do największego; tak, iż się spracowali, szukając drzwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Tedy rzekli mężowie oni do Lota: Maszli tu jeszcze kogo, zięcia, albo syny twe, albo córki twoje, i wszystko, co masz w mieście, wyprowadź z miejsca tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Skazimy bowiem to miejsce, przeto, że się wzmógł krzyk ich przed Panem, i posłał nas Pan, abyśmy je skazili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Tedy wyszedłszy Lot mówił do zięciów swoich, którzy mieli pojąć córki jego, i rzekł: Wstańcie, wynijdźcie z miejsca tego, bo skazi Pan to miasto; ale się zdało w oczach zięciów jego, jakoby żartował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'A gdy weszła zorza, przymuszali Aniołowie Lota, mówiąc: Wstań, weźmij żonę twoję, i dwie córki twoje, które tu są, byś snać nie zginął w nieprawości miasta tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'A gdy się ociągał, ujęli mężowie oni rękę jego, i rękę żony jego, i rękę dwóch córek jego, (albowiem mu Pan folgował,) i wywiedli go, i postawili go przed miastem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'I gdy je wywiedli precz, rzekł jeden: Jeźli chcesz, zachowaj duszę twoję, a nie oglądaj się nazad, ani stawaj na tej wszystkiej równinie; uchodź na górę, byś snać nie zginął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'A Lot rzekł do nich: Nie tak, proszę, panowie moi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Oto teraz znalazł sługa twój łaskę w oczach twoich, i okazałeś obficie miłosierdzie twoje, któreś uczynił ze mną, zachowawszy duszę moję; aleć ja nie będę mógł ujść na tę górę, by mię snać nie zachwyciło to złe, i umarłbym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Ale oto tu jest miasto nie daleko, do którego bym uciekł, małeć jest; proszę niech tam ujdę, (wszak małe jest,) a będzie żywa dusza moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Tedy rzekł do niego: Oto, i wtem wysłuchałem cię, abym nie wywrócił miasta tego, o któremeś mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Śpieszże się a uchodź tam, bo nie będę mógł nic uczynić, aż ty tam dojdziesz; przetoż nazwane jest imię miasta onego Zoar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Wtem słońce weszło na ziemię, a Lot wszedł do Zoar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Tedy Pan spuścił jako deszcz na Sodomę i na Gomorrę siarkę i ogień, od Pana z nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'I wywrócił miasta one, i wszystkę onę równinę, wszystkie obywatele miast onych, i urodzaje onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'I obejrzała się żona jego idąc za nim, a obróciła się w słup solny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Wstawszy tedy Abraham rano, pospieszył się na ono miejsce, kędy stał przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'I spojrzał ku Sodomie i Gomorze, i ku wszystkiej ziemi onej równiny, i obaczył, a oto wychodził dym z onej ziemi, jako dym z pieca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'A gdy wywracał Bóg miasta onej równiny, wspomniał Bóg na Abrahama i wybawił Lota z pośrodku wywrócenia, gdy wywracał one miasta, w których Lot mieszkał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Potem wyszedł Lot z Zoar, i mieszkał na górze, i dwie córki jego z nim, albowiem się bał mieszkać w Zoar; ale mieszkał w jaskini, on i dwie córki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Tedy rzekła starsza do młodszej: Ojciec nasz stary a nie masz męża na ziemi, który by wszedł do nas, według zwyczaju wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Pójdź, upójmy ojca naszego winem, a śpijmy z nim, abyśmy zachowały z ojca naszego nasienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Dały tedy pić ojcu swemu wina onej nocy. I wszedłszy starsza spała z ojcem swym; ale on nie czuł ani kiedy się układła, ani kiedy wstała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'I stało się nazajutrz, że rzekła starsza do młodszej: Otom ja spała przeszłej nocy z ojcem swym, dajmyż mu pić wina jeszcze tej nocy, i wnijdziesz, i będziesz spała z nim, a zachowamy z ojca naszego nasienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Tedy dały pić i onej nocy ojcu swemu wina; i przyszedłszy młodsza spała z nim; ale on nie czuł, ani kiedy się układła, ani kiedy wstała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'A tak poczęły obie córki Lotowe z ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'I urodziła starsza syna, a nazwała imię jego Moab; ten jest ojcem Moabitów, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Młodsza też urodziła syna, i nazwała imię jego Benammi; ten jest ojcem synów Ammonowych, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'I ruszył się stamtąd Abraham do ziemi południowej, a mieszkał między Kades i między Sur, i był gościem w Gerar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Tam powiedział Abraham o Sarze, żonie swej: Siostra moja jest; przetoż posłał Abimelech, król Gerary, i wziął Sarę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Ale Bóg przyszedł do Abimelecha we śnie w nocy, i rzekł mu: Oto ty umrzesz dla niewiasty, którąś wziął, bo ona ma męża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Ale Abimelech nie przybliżył się był do niej, i rzekł: Panie, izali też lud sprawiedliwy zabijesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Azaż mi on sam nie powiadał, siostra moja jest? a ona też sama nie mówiła, brat mój jest? w prostości serca mojego, i w niewinności rąk moich uczyniłem to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Tedy mu rzekł Bóg we śnie: Wiemci ja, żeś to w prostości serca swego uczynił; i dla tegom cię zawściągnął, abyś nie zgrzeszył przeciwko mnie, i nie dopuściłem ci, abyś się jej dotknął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Teraz tedy wróć żonę mężowi, bo prorokiem jest; i będzie się modlił za cię, a będziesz żył; a jeźliż jej nie wrócisz, wiedz, iż śmiercią umrzesz, ty, i wszystko, co twego jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Tedy Abimelech wstawszy rano, zwołał wszystkich sług swoich, i opowiedział im to wszystko; co usłyszawszy, polękali się mężowie oni bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Potem wezwał Abimelech Abrahama, i rzekł mu: Coś nam uczynił? a com zgrzeszył przeciwko tobie? iżeś przywiódł na mię i na królestwo moje grzech wielki? uczyniłeś mi, czegoś czynić nie miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'I rzekł po wtóre Abimelech do Abrahama: Cóżeś upatrywał, żeś tę rzecz uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'I odpowiedział Abraham: Myśliłem sobie: Podobno nie masz bojaźni Bożej na tem miejscu, i zabiją mię dla żony mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'A wszakże prawdziwie siostra moja jest, córka ojca mego, choć nie córka matki mojej; pojąłem ją za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'I stało się, gdy mię wyprawił Bóg na pielgrzymowanie z domu ojca mego, żem rzekł do niej: To miłosierdzie twoje będzie, które uczynisz ze mną: Na każdem miejscu, do którego przyjdziemy, powiesz o mnie: Brat to mój jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Tedy nabrawszy Abimelech owiec, i wołów, i sług, i służebnic, dał Abrahamowi, i wrócił mu Sarę, żonę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'I rzekł Abimelech: Oto ziemia moja przed obliczem twojem; gdzieć się kolwiek podoba, mieszkaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'A do Sary rzekł: Otom dał tysiąc srebrników bratu twemu, onci jest zasłoną oczu twoich u wszystkich, którzy są z tobą; a tem wszystkiem Sara wyuczona była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'I modlił się Abraham Bogu, a uzdrowił Bóg Abimelecha, i żonę jego, i służebnice jego, i rodziły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Zawarł bowiem był Pan cale każdy żywot domu Abimelechowego dla Sary, żony Abrahamowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'A Pan nawiedził Sarę, jako był rzekł: i uczynił Pan Sarze, jako był powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Bo poczęła i porodziła Sara Abrahamowi syna w starości jego, na tenże czas, który mu był Bóg przepowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'I nazwał Abraham imię syna swego, który mu się urodził, którego mu urodziła Sara, Izaak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'I obrzezał Abraham Izaaka, syna swego, gdy był w ośmiu dniach, jako mu był rozkazał Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'A było Abrahamowi sto lat, gdy mu się urodził Izaak, syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Tedy rzekła Sara: Śmiech mi uczynił Bóg; ktokolwiek usłyszy, śmiać się będzie ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'I rzekła: Któżby to był rzekł Abrahamowi, że Sara będzie karmiła piersiami syny? gdyżem urodziła syna w starości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Rosło tedy dziecię, i odstawione jest od piersi; i uczynił Abraham ucztę wielką w dzień odstawienia Izaaka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Potem ujrzała Sara syna Hagary, Egipczanki, przeszydzającego, którego urodziła Abrahamowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'I rzekła do Abrahama: Wyrzuć tę służebnicę, i syna jej; albowiem nie będzie dziedziczył syn tej służebnicy z synem mym Izaakiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Ale się to bardzo nie podobało w oczach Abrahamowych, dla syna jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Tedy rzekł Bóg do Abrahama: Niech to przykro nie będzie w oczach twoich z strony dziecięcia, i z strony służebnicy twojej; coćkolwiek rzecze Sara, usłuchaj głosu jej; boć w Izaaku nazwane będzie nasienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Wszakże i syna służebnicy rozmnożę w naród, przeto iż nasieniem twojem jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Wstał tedy Abraham bardzo rano, a wziąwszy chleb i łagiew wody, dał Hagarze; i włożywszy to na ramię jej, i z dziecięciem, odprawił ją; która poszedłszy błąkała się po puszczy Beerseba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'A gdy nie stało wody w łagwi, porzuciła dziecię pod jednem drzewem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'I odszedłszy usiadła przeciw niemu, tak daleko, jako na strzeleniu z łuku; bo mówiła: Nie będę patrzyła na śmierć dziecięcia; a siedząc przeciw niemu, podniosła głos swój, i płakała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Tedy usłyszał Bóg głos dziecięcy, i zawołał Anioł Boży na Hagarę z nieba, i rzekł jej: Cóżci Hagaro? nie bój się, boć usłyszał Bóg głos dziecięcy z miejsca, na którem jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Wstań, weźmij dziecię, a ujmij je ręką swoją: bo w naród wielki rozmnożę je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Otworzył tedy Bóg oczy jej, że ujrzała źródło wody; a szedłszy napełniła łagiew wodą, i dała pić dziecięciu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'I był Bóg z onem dziecięciem, Które urosło, i mieszkało na puszczy, był z niego strzelec dobry z łuku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'A mieszkał na puszczy Faran; i wzięła mu matka jego żonę z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'I stało się onegoż czasu, że rzekł Abimelech, i Fikol, hetman wojska jego, do Abrahama mówiąc: Bóg z tobą we wszystkiem, co ty czynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'A tak teraz, przysiąż mi przez Boga, że mię w niczem podchodzić nie będziesz, ani syna mego, ani wnuka mego; ale według miłosierdzia, którem uczynił z tobą, uczynisz ze mną, i z ziemią, w którejś był przychodniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Tedy odpowiedział Abraham: Ja przysięgnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'I przymawiał Abraham Abimelechowi o studnią wody, którą mu byli gwałtem odjęli słudzy Abimelechowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'I rzekł Abimelech: Nie wiem kto by to uczynił, nawet i tyś mi nie oznajmił, i jam nie słyszał o tem dopiero dziś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Nabrał tedy Abraham owiec i wołów, i dał Abimelechowi, i uczynili oba przymierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'I postawił Abraham siedmioro owiec z stada osobno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Tedy Abimelech rzekł do Abrahama: Na cóż to siedmioro owiec, któreś postawił osobno?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'A on odpowiedział: Iż te siedem owiec weźmiesz z rąk moich, aby mi były na świadectwo, żem wykopał tę studnię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Dlatego nazwano miejsce ono Beerseba; albowiem tam obaj przysięgli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'A tak zawarli przymierze w Beerseba. Potem wstawszy Abimelech, i Fikol, hetman wojska jego, wrócili się do ziemi Filistyńskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'I nasadził Abraham drzewa w Beerseba, i wzywał tam imienia Pana Boga wiecznego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'I mieszkał Abraham w ziemi Filistyńskiej przez wiele dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'To gdy się stało, kusił Bóg Abrahama, i rzekł do niego: Abrahamie! A on odpowiedział: Owom ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'I rzekł Bóg: Weźmij teraz syna twego, jedynego twego, którego miłujesz, Izaaka, a idź do ziemi Moryja, i tam go ofiaruj na ofiarę paloną, na jednej górze, o którejć powiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Tedy wstawszy Abraham bardzo rano, osiodłał osła swego, i wziął dwóch sług swoich z sobą, i Izaaka syna swego, a narąbawszy drew na ofiarę paloną, wstał i szedł na miejsce, o którem mu Bóg powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'A dnia trzeciego, podniósłszy Abraham oczy swe, ujrzał ono miejsce z daleka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'I rzekł Abraham do sług swoich: Zostańcie wy tu z osłem, a ja z dziecięciem pójdziemy aż do onąd, a odprawiwszy modlitwy, wrócimy się do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Wziął tedy Abraham drwa na ofiarę paloną, i włożył je na Izaaka, syna swego, a sam wziął w rękę swoję ogień i miecz, i szli obaj pospołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'I rzekł Izaak do Abrahama, ojca swego, mówiąc: Ojcze mój! A on odpowiedział: Owom ja, synu mój. I rzekł Izaak: Oto ogień i drwa, a gdzież baranek na ofiarę paloną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Odpowiedział Abraham: Bóg sobie obmyśli baranka na ofiarę paloną, synu mój; i szli obaj pospołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'A gdy przyszli na miejsce, o którem mu Bóg powiedział, zbudował tam Abraham ołtarz, i ułożył drwa, a związawszy Izaaka, syna swego, włożył go na ołtarz na drwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'I wyciągnął Abraham rękę swoję, i wziął miecz, aby zabił syna swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Lecz zawołał nań Anioł Pański z nieba, i rzekł: Abrahamie! Abrahamie! A on rzekł: Owom ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'I rzekł Anioł: Nie wyciągaj ręki twej na dziecię, i nie czyń mu nic; bom teraz doznał, iż się ty boisz Boga, i nie sfolgowałeś synowi twemu, jedynemu twemu, dla mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'A podniósłszy Abraham oczy swe, ujrzał, a oto baran za nim uwiązł w cierniu za rogi swoje; a szedłszy Abraham, wziął barana i ofiarował go na ofiarę paloną, miasto syna swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'I nazwał Abraham imię miejsca onego: Pan obmyśli; stądże po dziś dzień mówią: Na górze Pańskiej będzie obmyślono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Tedy zawołał Anioł Pański na Abrahama po wtóre z nieba mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Przez siebie samego przysiągłem, mówi Pan: Ponieważeś to uczynił, a nie sfolgowałeś synowi twemu, jedynemu twemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Błogosławiąc, błogosławić ci będę, a rozmnażając rozmnożę nasienie twoje, jako gwiazdy niebieskie, i jako piasek, który jest na brzegu morskim; a odziedziczy nasienie twoje bramy nieprzyjaciół twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'I błogosławione będą w nasieniu twojem wszystkie narody ziemi, dla tego, żeś usłuchał głosu mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Wrócił się tedy Abraham do sług swych, i wstawszy, przyszli pospołu do Beerseba; bo mieszkał Abraham w Beerseba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'I stało się potem, iż oznajmiono Abrahamowi, mówiąc: Oto narodziła i Melcha synów Nachorowi, bratu twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Husa, pierworodnego swego, i Buza, brata jego, i Chemuela, ojca Aramczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'I Kaseda, i Kasana, i Feldasa, i Jedlafa, i Batuela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'A Batuel spłodził Rebekę; ośmioro tych dzieci urodziła Melcha Nachorowi, bratu Abrahamowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'A założnica jego, której imię Reuma, urodziła też Tabę, i Gahama, i Tahasa, i Maacha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'A żyła Sara sto lat, i dwadzieścia lat, i siedem lat; te są lata żywota Sary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'I umarła Sara w mieście Arba, które zowią Hebron, w ziemi Chananejskiej: i przyszedł Abraham, aby żałował Sary, i płakał jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Potem wstał Abraham od umarłego swego, i rzekł do synów Hetowych, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Gościem i przychodniem jestem u was; dajcież mi osiadłość grobu między wami, abym pogrzebał umarłego mego od twarzy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Tedy opowiedzieli synowie Hetowi Abrahamowi, mówiąc mu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Słuchaj nas, panie mój: Książęciem Bożym jesteś ty w pośrodku nas: w najprzedniejszych grobach naszych pogrzeb umarłego twego; żaden z nas nie będzie bronił grobu swego tobie, abyś nie miał pogrzebać umarłego twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Tedy wstawszy Abraham, pokłonił się ludowi onej ziemi, to jest synom Hetowym, i rzekł do nich, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Jeźli się wam podoba, abym pogrzebał umarłego mego od twarzy mojej, słuchajcież mię, a przyczyńcie się za mną, do Efrona, syna Socharowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Aby mi ustąpił jaskini swojej Machpela, którą ma na końcu pola swego, za słuszne pieniądze; niech mi ją spuści przed wami w osiadłość grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, '(A Efron siedział w pośrodku synów Hetowych.) Tedy odpowiedział Efron Hetejczyk Abrahamowi, w przytomności synów Hetowych, przed wszystkimi, którzy chodzili w bramę miasta jego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nie tak, panie mój, ale słuchaj mię: Pole to dam tobie i jaskinią, która jest w niem, dawam ją tobie; przed oczyma synów ludu mego, dawam ją tobie, pogrzebże umarłego twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Tedy się pokłonił Abraham przed ludem onej ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'I rzekł do Efrona, w przytomności ludu onej ziemi, mówiąc: Raczej, jeźlić się zda, proszę, słuchaj mię: dam ci pieniądze za pole, weźmijże je ode mnie, a pogrzebię tam umarłego mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'I odpowiedział Efron Abrahamowi mówiąc mu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Panie mój, słuchaj mię. Ziemia ta stoi za cztery sta syklów srebra; ale cóż to jest między mną i między tobą? pogrzeb umarłego twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'I usłuchał Abraham Efrona; i odważył Abraham Efronowi srebro, jako był rzekł w przytomności synów Hetowych, cztery sta syklów srebra, tak jako szły między kupcami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'I dostało się pole Efronowe (które jest w Machpelu przeciwko Mamre, pole i jaskinia, która jest na niem, i wszystkie drzewa, które były na polu, które były na wszystkich granicach jego w około).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Abrahamowi w osiadłość przed oczyma synów Hetowych, i wszystkich, którzy wchodzili w bramę miasta onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'A tak pogrzebał Abraham Sarę, żonę swoję, w jaskini pola w Machpelu przeciwko Mamre, to jest Hebron, w ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'I oddane jest pole i jaskinia, która była na niem, Abrahamowi w osiadłość grobu, od synów Hetowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'A Abraham był stary i podeszły w leciech, a Pan błogosławił mu we wszystkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Tedy rzekł Abraham do starszego sługi swego w domu swym, który wszystkiem rządził, co miał: Połóż, proszę, rękę twoję pod biodro moje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'A zaprzysięgnę cię przez Pana, Boga nieba, i Boga ziemi, abyś nie brał żony synowi memu z córek Chananejskich, między któremi ja mieszkam;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Ale pójdziesz do ziemi mojej, i do rodziny mojej, a stamtąd weźmiesz żonę Izaakowi, synowi memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Tedy mu rzekł sługa: A jeźliby snać nie chciała niewiasta ona iść ze mną do tej ziemi, mamże odprowadzić syna twego do ziemi, z którejś ty wyszedł?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'I rzekł mu Abraham: Strzeż się, abyś tam zasię nie zaprowadzał syna mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Pan Bóg niebieski, który mię wziął z domu ojca mego, i z ziemi rodziny mojej, i który mówił ze mną, a który mi przysiągł, mówiąc: Nasieniu twemu dam ziemię tę; on pośle Anioła swego przed obliczem twojem, i weźmiesz stamtąd żonę synowi memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'A jeźliby nie chciała ona niewiasta iść z tobą, wolny będziesz od tego poprzysiężenia mego; tylko syna mego nie zaprowadzaj tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Podłożył tedy sługa rękę swoję pod biodro Abrahama, pana swego, i przysiągł mu na to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'I wziął on sługa dziesięć wielbłądów, z wielbłądów pana swego, i poszedł; bo wszystkie dobra pana swego miał w rękach swych; a wstawszy puścił się do Aram Naharaim, do miasta Nachorowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'I postawił wielbłądy przed miastem u studni wody, pod wieczór, tego czasu, którego zwykły niewiasty wychodzić czerpać wodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'I rzekł: Panie, Boże pana mego Abrahama! Niech mię proszę spotka dziś, czego żądam, a uczyń miłosierdzie z panem moim Abrahamem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Oto, ja stoję u studni, a córki obywateli miasta tego wyjdą czerpać wodę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Panienka tedy, do której bym rzekł: Nachyl proszę wiadra twego, że się napiję, a ona by rzekła: Pij, owszem i wielbłądy twoje napoję; ta niech będzie, którąś zgotował słudze twemu Izaakowi; a po tem poznam, żeś uczynił miłosierdzie z panem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'I stało się, że pierwej niż przestał mówić, oto, Rebeka wychodziła, która się urodziła Batuelowi, synowi Melchy, żony Nachora, brata Abrahamowego, niosąc wiadro na ramieniu swem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'A dzieweczka ona była bardzo piękna na wejrzeniu, panna, a której mąż nie uznał; ta przyszedłszy do studni, napełniła wiadro swe, i wracała się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Tedy zabieżał jej on sługa, i rzekł: Daj mi się proszę napić trochę wody z wiadra twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'A ona rzekła: Pij, panie mój, i prędko złożyła wiadro swe na rękę swoję, i dała mu pić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'A gdy mu się dała napić, rzekła: I wielbłądom twoim naczerpię, aż się napiją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'I wylała prędko wodę z wiadra swego w koryto, a bieżawszy jeszcze do studni czerpać, naczerpała wszystkim wielbłądom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'A on mąż zdumiewał się nad nią, uważając z milczeniem, jeźli mu Pan zdarzył drogę jego, czyli nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'I gdy się napiły wielbłądy, wyjął on mąż nausznicę złotą, która ważyła pół sykla, i dwie manele, i dał na ręce jej, które ważyły dziesięć syklów złota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'I rzekł: Czyjaś ty córka, powiedz mi, proszę? a jeźli w domu ojca twego miejsce dla nas, gdzie byśmy przenocowali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'A ona mu rzekła: Jestem córka Batuela, syna Melchy, którego urodziła Nachorowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Nad to rzekła mu: Jest u nas dosyć plew i pastwy, i miejsce do przenocowania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'I pokłonił się on człowiek i dał chwałę Panu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'I rzekł: Błogosławiony Pan, Bóg pana mego Abrahama, który nie oddalił miłosierdzia swego i prawdy swojej od pana mojego, albowiem gdym był w drodze, przyprowadził mię Pan w dom braci pana mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Bieżała tedy dzieweczka, i oznajmiła w domu matki swej, jako się co stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'I miała Rebeka brata imieniem Labana; i wybieżał Laban przeciwko onemu mężowi aż ku studni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Bo ujrzawszy nausznicę, i manele na ręku siostry swej, i usłyszawszy słowa Rebeki, siostry swej, mówiącej: Tak mówił do mnie ten mąż; przyszedł do onego męża, a oto, on stał przy wielbłądach u studni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'I rzekł do niego: Wnijdź błogosławiony Pański; przecz byś stał na dworze, jużem ja nagotował dom, i miejsce wielbłądom?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Tedy wszedł mąż on w dom; a Laban rozsiodłał wielbłądy, i dał plew i pastwy wielbłądom, i wody dla umycia nóg jego, i nóg mężów onych, którzy z nim byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'I położył przedeń, coby jadł; ale on rzekł: Nie będę jadł, aż pierwej odprawię rzecz swoję. Tedy rzekł Laban: Mówże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'I rzekł: Jam jest sługa Abrahamów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'A Pan ubłogosławił pana mego bardzo, i stał się możnym; bo mu nadał owiec, i wołów, i srebra, i złota, i sług, i służebnic, i wielbłądów, i osłów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'A urodziła Sara, żona pana mego syna panu memu, w starości jego, któremu dał wszystko, co ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'I poprzysiągł mię pan mój, mówiąc: Nie weźmiesz żony synowi memu z córek Chananejskich, w których ziemi ja mieszkam;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Ale do domu ojca mego pójdziesz i do rodziny mojej; a weźmiesz stamtąd żonę synowi mojemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'I rzekłem do pana mego: Nie pójdzie snać ta niewiasta ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Tedy mi odpowiedział: Pan, przed któregom ja obliczem chodził, pośle Anioła swego z tobą, i poszczęści drogę twoję; a weźmiesz żonę synowi memu z rodziny mojej, i z domu ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Tedy wolen będziesz od poprzysiężenia mego, gdy przyjdziesz do rodziny mojej; ale jeźlićby jej nie dano, wolen będziesz od poprzysiężenia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Przyszedłem tedy dziś do studni, i rzekłem Panie, Boże pana mego Abrahama, jeźliż ty teraz szczęścisz drogę moję, którę ja idę:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Oto, ja stoję u studni wody; niechajże panienka, która wynijdzie czerpać wodę, a gdybym jej rzekł: Daj mi proszę napić się trochę wody z wiadra twego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'A ona by rzekła do mnie: I ty pij, naczerpię też i wielbłądom twoim: ta będzie żoną, którą zgotował Pan synowi pana mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Niżelim ja tedy przestał mówić w sercu swem, oto, Rebeka wychodziła, niosąc wiadro swe na ramieniu swem, i przyszła do studni, a czerpała; którejm rzekł: Daj mi pić proszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Ona tedy prędko złożywszy wiadro z siebie, rzekła: Pij, owszem i wielbłądy twoje napoję. I piłem; napoiła też i wielbłądy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'I pytałem jej, mówiąc: Czyjaś ty córka? i odpowiedziała: Jestem córka Batuela, syna Nachorowego, którego mu urodziła Melcha, tedym włożył nausznice na twarz jej, i manele na ręce jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Zatem pokłoniwszy się, dałem chwałę Panu, i błogosławiłem Panu, Bogu pana mego Abrahama, który mię prowadził drogą prawą, abym wziął córkę brata pana mego, synowi jego');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Przetoż teraz, jeźli chcecie uczynić miłosierdzie i prawdę z panem moim, oznajmijcie mi: a jeźli nie, powiedzcie mi też, żebym się obrócił na prawo albo na lewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Tedy odpowiedział Laban i Batuel, mówiąc: Od Pana ta rzecz wyszła; my tobie w niczem przeczyć nie możemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Oto Rebeka przed tobą; weźmij ją, a idź; a niech będzie żoną syna pana twego, jako rzekł Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'I stało się, gdy usłyszał sługa Abrahamów słowa ich pokłonił się aż do ziemi Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Zatem wyjął sługa on naczynia srebrne, i naczynia złote, i szaty, a oddał je Rebece; dał też upominki drogie bratu jej, i matce jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Jedli tedy i pili, on i mężowie, którzy z nim byli, i zostali tam na noc; a rano wstawszy, rzekł: Puśćcie mię do pana mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'I rzekł brat jej, i matka jej: Niechaj pomieszka z nami dzieweczka dzień, albo dziesięć; potem pójdziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'A on rzekł do nich: Nie zatrzymywajcie mię, gdyż Pan poszczęścił drogę moję, puśćcie mię, abym jechał do pana mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Zatem rzekli: Zawołajmy dzieweczki, a spytajmy, co na to rzecze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Tedy zawołali Rebeki, i mówili do niej: Chceszże jechać z tym człowiekiem? A ona odpowiedziała: Pojadę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'I puścili Rebekę siostrę swoję, z mamką jej, i sługę Abrahamowego, z mężami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Tedy błogosławili Rebece, mówiąc jej: Siostraś nasza, rozmnóż się w tysiąc tysięcy, a niech posiądzie nasienie twoje bramy nieprzyjaciół swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Tedy wstawszy Rebeka z dzieweczkami swemi, i wsiadłszy na wielbłądy jechały za onym mężem; i wziął sługa on Rebekę, i odjechał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'A Izaak wracał się z przechadzki od studni, którą zowią Żywiącego i Widzącego mię; bo mieszkał w ziemi południowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'A wyszedł był Izaak, dla modlitwy na pole pod wieczór, i podniósłszy oczy swe, ujrzał wielbłądy przychodzące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Podniosła też i Rebeka oczy swe, i ujrzała Izaaka, i zsiadła z wielbłąda;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Bo rzekła do sługi: Cóż on za mąż, który idzie przez pole przeciwko nam? I odpowiedział sługa: Ten jest pan mój. A ona wziąwszy rańtuch nakryła się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'I powiedział on sługa Izaakowi wszystko, co sprawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'I wprowadził ją Izaak do namiotu Sary, matki swojej; i wziął Rebekę, i była mu żoną, i miłował ją. I ucieszył się Izaak po śmierci matki swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Potem Abraham pojął drugą żonę, której imię było Ketura.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Która mu urodziła Zamrama, i Joksana, i Madana, i Midyjana, i Jesobaka, i Suacha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'A Joksan spłodził Sabę, i Dedana; a synowie Dedanowi byli Asurymowie i Letusymowie, i Leumymowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Synowie zaś Midyjanowi byli Hefa, i Hefer, i Henoch, i Abyda, i Eldaa; wszyscy ci byli synowie Ketury.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'I dał Abraham wszystko, co miał, Izaakowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'A synom założnic, które miał Abraham, dał upominki; i wyprawił je od Izaaka syna swego, jeszcze za żywota swego, ku wschodowi do krainy wschodniej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Teć są dni lat żywota Abrahamowego, które przeżył, sto i siedemdziesiąt, i pięć lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'I ustawając umarł Abraham w starości dobrej, zeszły w leciech, i syty dni; i przyłączon jest do ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'I pogrzebli go Izaak i Ismael, synowie jego, w jaskini Machpela, na polu Efrona, syna Socharowego, Hetejczyka, które było przeciwko Mamre;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Na polu, które był kupił Abraham u synów Hetowych; tam pogrzebiony jest Abraham, i Sara, żona jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'A po śmierci Abrahamowej błogosławił Bóg Izaakowi, synowi jego, a Izaak mieszkał u studni Żywiącego i Widzącego mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'A teć są rodzaje Ismaela, syna Abrahamowego, którego urodziła Hagar, Egipczanka, służebnica Sary, Abrahamowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'I te są imiona synów Ismaelowych w nazwiskach ich, według rodzajów ich: pierworodny Ismaelów, Nebajot; po nim Kedar, i Abdeel, i Mabsan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'I Masma, i Duma, i Masa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadar, i Tema, Jetur, Nafis i Kedma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Ci są synowie Ismaelowi, i te imiona ich, według miasteczek ich, i zamków ich, dwanaście książąt w familijach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'A było lat żywota Ismaelowego, sto lat, i trzydzieści lat i siedem lat, i zszedł a umarł, i przyłączon jest do ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'I mieszkali od Hewila aż do Sur, która leży na przeciwko Egiptowi, idąc do Asyryi; przed obliczem wszystkich braci swych umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Te zaś są rodzaje Izaaka syna Abrahamowego: Abraham spłodził Izaaka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'A Izaak miał czterdzieści lat, gdy sobie pojął Rebekę, córkę Batuela Syryjczyka, z krainy Syryjskiej, siostrę Labana, Syryjczyka, za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Tedy się modlił Izaak Panu za żonę swą, iż była niepłodna; i wysłuchał go Pan, i poczęła Rebeka, żona jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'A gdy się dziatki trącały w żywocie jej, rzekła: Jeźliż tak miało być, dlaczegożem poczęła? Szła tedy, aby się pytała Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'I rzekł jej Pan: dwa narody są w żywocie twoim, i dwojaki lud z żywota twego rozdzieli się, a jeden lud nad drugi lud możniejszy będzie, i większy będzie służył mniejszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'A gdy się wypełniły dni jej, aby porodziła, oto bliźnięta były w żywocie jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'I wyszedł pierwszy syn lisowaty, i wszystek jako szata kosmaty; i nazwali imię jego Ezaw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'A potem wyszedł brat jego, ręką swą trzymając za piętę, Ezawa i nazwano imię jego Jakób; a Izaakowi było sześćdziesiąt lat, gdy mu się oni narodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'A gdy urosły one dzieci, Ezaw był mężem w myślistwie biegłym i rolnikiem, a Jakób był mąż prosty mieszkający w namieciech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'I miłował Izaak Ezawa, iż jadał z łowu jego; Rebeka zaś miłowała Jakóba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'I uwarzył sobie Jakób potrawę, a na ten czas przyszedł Ezaw z pola spracowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Tedy rzekł Ezaw do Jakóba: Daj mi jeść, proszę cię z tej czerwonej potrawy, bom się spracował: a przetoż nazwano imię jego Edom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Któremu rzekł Jakób: Przedajże mi dziś pierworodztwo twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'I rzekł Ezaw: Otom ja bliski śmierci, cóż mi po pierworodztwie?.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'I rzekł Jakób: Przysiążże mi dziś, i przysiągł mu. I sprzedał pierworodztwo swoje Jakóbowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Tedy Jakób dał Ezawowi chleba, i potrawę z soczewicy, a on jadł i pił, a potem powstawszy odszedł; i pogardził Ezaw pierworodztwem swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Potem był głód na ziemi, po onym głodzie pierwszym, który był za dni Abrahamowych; I poszedł Izaak do Abimelecha, do króla Filistyńskiego do Gerar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Bo mu się był ukazał Pan i mówił: Nie zstępuj do Egiptu, ale mieszkaj w ziemi, o której Ja powiem tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Bądźże gościem w tej ziemi, a Ja będę z tobą, i będęć błogosławił; albowiem tobie i nasieniu twemu dam te wszystkie krainy, i utwierdzę przysięgę, którąm przysiągł Abrahamowi, ojcu twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'I rozmnożę nasienie twoje jako gwiazdy niebieskie, a dam nasieniu twemu wszystkie te krainy: A będą błogosławione w nasieniu twojem wszystkie narody ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Przeto, iż Abraham był posłuszny głosowi mojemu, a strzegł postanowienia mego, przykazań moich, ustaw moich i praw moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Tedy Izaak mieszkał w Gerar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'I pytali się mężowie onego miejsca o żonie jego; a on powiedział: Siostra to moja; bo się bał mówić: Żona to moja; by go snać nie zabili mężowie miejsca tego dla Rebeki, iż była piękna na wejrzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'I stało się, gdy tam mieszkał przez nie mało dni, że wyglądał Abimelech, król Filistyński, oknem, i ujrzał, że Izaak żartował z Rebeką, żoną swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Tedy przyzwał Abimelech do siebie Izaaka, i rzekł: Prawdziwieć to żona twoja; czemużeś powiadał, siostra to moja? I odpowiedział mu Izaak: Iżem u siebie mówił: Bym snać nie umarł dla niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'I rzekł Abimelech: Cóżeś nam to uczynił? bez mała ktokolwiek z ludu nie spał z żoną twoją: i przywiódłbyś był na nas grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Rozkazał tedy Abimelech wszystkiemu ludowi mówiąc: Kto by się dotknął męża tego, albo żony jego, śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Tedy siał Izaak w onej ziemi, i zebrał roku onego sto korcy, albowiem błogosławił mu Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'I zbogacił się on mąż, a im dalej, tem więcej wzmagał się, aż urósł wielce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'I miał stada owiec, i stada wołów, i czeladzi dosyć; przetoż mu zajrzeli Filistyńczycy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'I wszystkie studnie, które byli wykopali słudzy ojca jego, za dni Abrahama, ojca jego, zasypali Filistyńczycy, i napełnili je ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'I rzekł Abimelech do Izaaka: Odejdź od nas, albowiemeś daleko możniejszy niż my.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'I odszedł stamtąd Izaak, i rozbił namioty w dolinie Gerar, i mieszkał tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'I kopał zasię Izaak studnie wód, które byli wykopali za dni Abrahama, ojca jego, co je byli zasypali Filistyni po śmierci Abrahamowej, i zwał je temiż imiony, któremi je był nazwał ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Tedy kopali słudzy Izaakowi w onej dolinie, i znaleźli tam studnią wód żywych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Lecz poswarzyli się pasterze Gerarscy z pasterzami Izaakowymi, mówiąc: Nasza to woda; przeto nazwał imię studni onej, Hesek, iż się swarzyli z nim o nię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Potem wykopali drugą studnią, i swarzyli się też o nię; dla tegoż nazwał imię jej Sydna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Zatem przeniósł się stamtąd, i wykopał drugą studnią o którą żadnego sporu nie było; i nazwał imię jej Rechobot, i mówił: Oto, teraz rozszerzył nas Pan, i urośliśmy na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'I wstąpił stamtąd do Beerseby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'I ukazał mu się Pan onejże nocy, mówiąc: Jam jest Bóg Abrahama, ojca twego, nie bój się, bom Ja jest z tobą; i będęć błogosławił, i rozmnożę nasienie twoje, dla Abrahama, sługi mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Tedy tam zbudował ołtarz, i wzywał imienia Pańskiego, i rozbił tam namiot swój, tamże też wykopali słudzy Izaakowi studnię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Abimelech potem przyjechał do niego z Gerar, i Achuzat przyjaciel jego, i Fikol, hetman wojska jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Do których rzekł Izaak: Przeczżeście przyjechali do mnie, gdyż wy mnie macie w nienawiści, i wypędziliście mię od siebie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'A oni odpowiedzieli: Obaczyliśmy to dobrze, że Pan jest z tobą, i rzekliśmy: Uczyńmy teraz przysięgę między sobą, między nami i między tobą, i postanowimy przymierze z tobą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Abyś nam nic złego nie czynił, jakośmy się też ciebie nie tykali; i jakośmyć tylko dobrze czynili, a puściliśmy cię w pokoju; a tyś teraz błogosławiony od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Tedy im sprawił ucztę, a jedli i pili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Potem wstawszy bardzo rano przysięgli jeden drugiemu; i wyprowadził je Izaak, i odeszli od niego w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'I stało się onegoż dnia, przyszli słudzy Izaakowi, i powiedzieli mu o studni, którą wykopali, mówiąc mu: Znaleźliśmy wodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'I nazwał ją Syba; dlategoż imię miasta onego jest nazwane Beerseba aż do dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Potem Ezaw mając czterdzieści lat, pojął sobie za żonę Judytę, córkę Beery Hetejczyka, i Basemat, córkę Elona, Hetejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Które się bardzo naprzykrzały Izaakowi i Rebece.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'I stało się, gdy się zestarzał Izaak, i zaćmiły się oczy jego, tak, iż widzieć nie mógł: tedy wezwał Ezawa, syna swego starszego, i rzekł mu: Synu mój! a on odpowiedział: Owom ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'I rzekł Izaak: Otom się już zestarzał, a nie wiem dnia śmierci swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Przetoż teraz weźmij proszę naczynia twoje, sajdak twój, i łuk twój, a wynijdź w pole, i ułów mi zwierzynę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'I nagotuj mi potrawy smaczne, w jakich się kocham, i przynieś mi, a będę jadł, abyć błogosławiła dusza moja, pierwej, niż umrę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Ale Rebeka słyszała, gdy to mówił Izaak do Ezawa, syna swego; tedy wyszedł Ezaw na pole, aby ułowił zwierzynę i przyniósł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'I rzekła Rebeka do Jakóba, syna swego, mówiąc: Otom słyszała, gdy ojciec twój mówił do Ezawa, brata twego, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Przynieś mi co z obłowu, a nagotuj mi potrawy smaczne, abym jadł, i błogosławił ci przed obliczem Pańskiem, pierwej, niż umrę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'A tak teraz synu mój, usłuchaj głosu mego w tem, co ja rozkazuję tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'A szedłszy do trzody, przynieś mi stamtąd dwoje koźląt dobrych, a nagotuję z nich potrawy smaczne ojcu twemu, jako rad jada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'I zaniesiesz ojcu twemu, a będzie jadł; dlatego abyć błogosławił, pierwej niż umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Tedy rzekł Jakób do Rebeki, matki swej: Oto, Ezaw brat mój, człowiek kosmaty, a jam człowiek gładki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Jeźli mię pomaca ojciec mój, a będzie rozumiał, że z niego szydzę, przywiodę na się przeklęstwo, a nie błogosławieństwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'I rzekła mu matka jego: Na mię niech będzie przeklęstwo twoje, synu mój; tylko usłuchaj głosu mego, a szedłszy, przynieś mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Tedy on szedłszy wziął, i przyniósł matce swej; i nagotowała matka jego potrawy smaczne, jako rad jadał ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'I wziąwszy Rebeka szaty Ezawa, syna swego starszego, najkosztowniejsze, które miała u siebie w domu, oblokła w nie Jakóba, syna swego młodszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'A skórkami koźlęcemi obwinęła ręce jego, i gładkość szyi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'I dała chleb i potrawy smaczne, które nagotowała, w ręce Jakóba syna swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'A on wszedłszy do ojca swego mówił: Ojcze mój! a on rzekł: Owom ja! Ktoś ty jest, synu mój?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'I rzekł Jakób do ojca swego: Jam jest Ezaw, pierworodny twój. Uczyniłem, jakoś mi rozkazał; wstań proszę, siądź, a jedz z obłowu mego, aby mi błogosławiła dusza twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'I rzekł Izaak do syna swego: Cóż to jest? Prędkoś to znalazł, synu mój? a on odpowiedział: Sposobił to Pan Bóg twój, że mi się nagodziło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Zatem Izaak rzekł do Jakóba: Przystąp sam, abym cię pomacał, synu mój, jeźliś ty jest syn mój Ezaw, czyli nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Tedy przystąpił Jakób do Izaaka, ojca swego, który pomacawszy go, rzekł: Głos jest głos Jakóbów, ale ręce Ezawowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'I nie poznał go; albowiem były ręce jego jako ręce Ezawa, brata jego, kosmate; i błogosławił mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'I rzekł: Tyżeś jest syn mój Ezaw? a on odpowiedział: Ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Zatem rzekł: Podajże mi, żebym jadł z obłowu syna mego, abyć błogosławiła dusza moja. Tedy mu podał, i jadł. Przyniósł mu też wina, i pił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'I rzekł mu Izaak, ojciec jego: Przystąpże teraz a pocałuj mię, synu mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Tedy przystąpiwszy pocałował go, a skoro poczuł wonność szat jego, błogosławił mu, mówiąc: Oto wonność syna mego, jako wonność pola, któremu błogosławił Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Niechajżeć da Bóg z rosy niebieskiej, i z tłustości ziemskiej, i obfitość zboża i wina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Niechaj ci służą ludzie, a niech ci się kłaniają narodowie. Bądź panem braci twojej, a niech ci się kłaniają synowie matki twojej; którzy by cię przeklinali, niech będą przeklętymi, a którzy by cię błogosławili, niech będą błogosławionymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'I stało się, gdy przestał Izaak błogosławić Jakóbowi, i ledwie Jakób odszedł od oblicza Izaaka, ojca swego, tedy Ezaw brat jego, przyszedł z łowu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Który nagotowawszy potrawy smaczne, przyniósł je ojcu swemu, i mówił do ojca swego: Wstańże ojcze mój, a jedz z obłowu syna twego, aby mi błogosławiła dusza twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Tedy mu rzekł Izaak, ojciec jego: Któżeś ty? A on rzekł: Jam jest syn twój, pierworodny twój, Ezaw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'I zląkł się Izaak zlęknieniem bardzo wielkiem, i rzekł: Któż to, a gdzie jest ten, co ułowił zwierzynę, i przyniósł mi? i jadłem ze wszystkiego, pierwej, niżeś ty przyszedł, i błogosławiłem mu, i będzie błogosławionym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'A usłyszawszy Ezaw słowa ojca swego, zawołał głosem wielkiem, i był żałością wielką zjęty, i rzekł ojcu swemu: Błogosławże też i mnie, ojcze mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'A on mu rzekł: Przyszedł brat twój chytrze, i wziął błogosławieństwo twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Tedy Ezaw rzekł: Słusznieć nazwano imię jego Jakób, podszedł mię bowiem już dwa kroć; pierworodztwo moje wziął, a teraz oto odniósł błogosławieństwo moje. I rzekł: Toś mi nie zachował błogosławieństwa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Odpowiedział Izaak, i rzekł do Ezawa: Otom go panem postanowił nad tobą, i wszystkich braci jego dałem mu za sługi, i zbożem, i winem opatrzyłem go; a tobie cóż teraz mam uczynić, synu mój?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'I rzekł Ezaw do ojca swego: Izali tylko jedno błogosławieństwo masz, ojcze mój? Błogosławże i mnie; i jamci syn twój, ojcze mój. I podniósł Ezaw głos swój, a płakał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'I odpowiedział Izaak, ojciec jego, i rzekł mu: Oto w tłustości ziemi będzie mieszkanie twoje, i w rosie niebieskiej z góry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'A z miecza twego żyć będziesz, i bratu twemu będziesz służył; ale stanie się, że i ty panować będziesz, i zrzucisz jarzmo jego z szyi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Przetoż nienawidził Ezaw Jakóba dla błogosławieństwa, którem mu błogosławił ojciec jego; i mówił Ezaw w sercu swem: Przybliżają się dni żałoby ojca mego, a zabiję Jakóba, brata mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'I oznajmiono Rebece słowa Ezawa, syna jej starszego, która posławszy, wezwała Jakóba, syna swego młodszego, i rzekła do niego: Oto Ezaw, brat twój, cieszy się tem, iż cię zabije.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Przetoż teraz, synu mój, usłuchaj głosu mego, a wstawszy, uciecz do Labana, brata mego, do Haranu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'I pomieszkaj z nim przez jaki czas, aż ucichnie gniew brata twego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Aż się odwróci zapalczywość brata twego od ciebie, i zapomni tego, coś mu uczynił; potem ja poślę, a wezmę stamtąd; bo czemuż mam was obydwóch postradać jednego dnia?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'I rzekła Rebeka do Izaaka: Obmierzł mi żywot mój dla córek Hetejskich; jeźliże i Jakób weźmie sobie żonę z córek Hetejskich, jakie są córki ziemi tej, cóż mi po żywocie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Tedy wezwał Izaak Jakóba, i błogosławił mu, a rozkazał mu, mówiąc: Nie pojmuj żony z córek Chananejskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Ale wstawszy idź do krainy Syryjskiej, do domu Batuela, ojca matki twojej, a weźmij sobie stamtąd żonę, z córek Labana, brata matki twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'A Bóg Wszechmogący niech ci błogosławi, a niech cię rozrodzi i rozmnoży, abyś był w mnóstwo ludu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'I niech ci da błogosławieństwo Abrahamowe, tobie i nasieniu twemu z tobą, abyś odziedziczył ziemię pielgrzymstwa twojego, którą dał Bóg Abrahamowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'I tak wysłał Izaak Jakóba, który szedł do krainy Syryjskiej, do Labana, syna Batuelowego, Syryjczyka, brata Rebeki, matki Jakóbowej i Ezawowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'A widząc Ezaw, iż błogosławił Izaak Jakóbowi, i posłał go do krainy Syryjskiej, aby sobie pojął stamtąd żonę, a iż błogosławiąc mu, przykazał, mówiąc: Nie weźmiesz żony z córek Chananejskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'I Jakób posłuszny był ojcu swemu i matce swojej, i poszedł do krainy Syryjskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Widząc też Ezaw, że się nie podobają córki Chananejskie w oczach Izaaka, ojca jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Tedy szedł Ezaw do Ismaela, i pojął mimo inne żony swoje, Mahalatę córkę Ismaela, syna Abrahamowego, siostrę Nebajotowę, sobie za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'A Jakób wyszedłszy z Beerseba, szedł do Haranu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'I przyszedł na jedno miejsce, i nocował tam (albowiem już było zaszło słońce) a wziąwszy jeden z kamieni miejsca onego, podłożył pod głowę swoję, i spał na temże miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'I śniło mu się, a ono drabina stała na ziemi, a wierzch jej dosięgał nieba; a oto, Aniołowie Boży wstępowali i zstępowali po niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'A Pan stał nad nią i rzekł; Jam jest Pan, Bóg Abrahama, ojca twego, i Bóg Izaaka, ziemię tę, na której ty śpisz, tobie dam i nasieniu twojemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'A będzie nasienie twoje jako proch ziemi, i rozmnożysz się na zachód, i na wschód, i na północy, i na południe; a będą ubłogosławione w tobie wszystkie narody ziemi i w nasieniu twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'A oto, Ja jestem z tobą i strzec cię będę gdziekolwiek pójdziesz, i przywrócę cię do tej ziemi; bo nie opuszczę cię, aż uczynię com ci rzekł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Tedy gdy się ocknął Jakób ze snu swego, rzekł: Zaprawdę Pan jest na tem miejscu, a jam nie wiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'I zlęknąwszy się, rzekł: O jako to straszne miejsce! nic tu nie jest innego jedno dom Boży, a tu brama niebieska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'I wstał Jakób bardzo rano, a wziąwszy kamień, który był podłożył pod głowę swoję, postawił go na znak, i nalał oliwy na wierzch jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'I nazwał imię miejsca onego Betel; bo było przedtem imię miasta onego Luz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Tedy uczynił Jakób ślub, mówiąc: Jeźliż będzie Bóg ze mną, a strzec mię będzie na tej drodze, którą ja idę, i da mi chleb ku jedzeniu, i odzienie ku obłóczeniu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'A wrócę się w pokoju do domu ojca mego: tedy będzie mi Pan za Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'A kamień ten, którym wystawił na znak, będzie domem Bożym, a ze wszystkiego, co mi dasz, dziesięcinę pewną oddawać ci będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Tedy Jakób wstawszy, poszedł do ziemi, mieszkających na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'I ujrzał studnią na polu, i trzy stada owiec leżących przy niej; bo z onej studni napawano stada, a kamień wielki był na wierzchu onej studni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Albowiem schodziły się tam wszystkie stada, i odwalono kamień z wierzchu studni, a napawano stada; potem zaś kładziono kamień na wierzch studni na miejsce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Tedy rzekł do nich Jakób: Bracia moi, skądeście? i odpowiedzieli: Z Haranu jesteśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'I rzekł do nich Jakób: A znacie Labana, syna Nachorowego? odpowiedzieli: Znamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Zatem rzekł do nich: A dobrze się ma? a oni odpowiedzieli: Dobrze; a oto, Rachel córka jego idzie z stadem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Tedy rzekł: Oto, jeszcze dosyć dnia, i nie czas zganiać stada; napójcież owce, a idźcie, popaście ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'A oni odpowiedzieli: Nie możemy, ażby się zebrały wszystkie stada, i odwalony był kamień z wierzchu studni, abyśmy napoili stada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'A gdy to jeszcze mówił z nimi, Rachel nadeszła z owcami ojca swego, bo je ona pasła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'I gdy ujrzał Jakób Rachelę, córkę Labana, brata matki swojej, z owcami Labana, brata matki swej: tedy przystąpił Jakób, i odwalił kamień z wierzchu studni, a napoił owce Labana, brata matki swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'I pocałował Jakób Rachelę, i podniósłszy głos swój płakał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'I oznajmił Jakób Racheli, że jest bratem ojca jej, a iż jest synem Rebeki: a ona bieżawszy opowiedziała to ojcu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'A gdy usłyszał Laban wieść o Jakóbie, synu siostry swojej, wybieżał przeciwko niemu, i obłapił go, a pocałowawszy, wwiódł do domu swego. A on Labanowi powiedział o wszystkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'I rzekł mu Laban: Zaisteś ty jest kość moja, i ciało moje. I mieszkał u niego przez cały miesiąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Potem rzekł Laban do Jakóba: Izali, żeś mi brat, służyć mi będziesz darmo? powiedz mi, jaką ma być zapłata twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'A miał Laban dwie córki: imię starszej Lija, a imię młodszej Rachel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Ale Lija była chorych oczu, a Rachel zaś pięknego oblicza, i wdzięczna na wejrzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Miłował tedy Jakób Rachelę, i rzekł: Będęć służył siedem lat za Rachelę, córkę twoję młodszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Odpowiedział Laban: Lepiej że ją tobie dam, niźlibym ją miał dać mężowi innemu: mieszkajże ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'I służył Jakób za Rachelę siedem lat, i zdał mu się ten czas jako kilka dni, przeto że ją miłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Potem rzekł Jakób do Labana: Daj mi żonę moję, ponieważ się wypełniły dni moje, abym wszedł do niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Tedy wezwawszy Laban wszystkich mężów miejsca onego, sprawił ucztę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'A gdy był wieczór, wziął Liję, córkę swoję, i wwiódł ją do niego, a Jakób wszedł do niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Dał też Laban i Zelfę, dziewkę swoję, Lii, córce swej, za służebnicę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'A gdy było rano, poznał Jakób, że to Lija, i rzekł do Labana: Cóżeś mi to uczynił? Izalim ja nie za Rachelę tobie służył? czemużeś mię tedy oszukał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'I odpowiedział Laban: Nie jest to w zwyczaju u nas, aby miano wydawać za mąż młodszą przed starszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Wytrwaj z tą tydzień, a dam ci i tę za służbę, którą mi będziesz służył jeszcze drugie siedem lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'I uczynił tak Jakób, i wypełnił z tą tydzień; potem dał mu Laban Rachelę, córkę swoję, za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Dał też Laban Racheli, córce swej, Balę dziewkę swoję; dał jej za służebnicę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Tedy też wszedł Jakób do Racheli, i miłował Rachelę bardziej niż Liję, a służył mu jeszcze drugie siedem lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'A widząc Pan, że nienawidził Liję, otworzył żywot jej; a Rachel niepłodna była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Tedy począwszy Lija porodziła syna, i nazwała imię jego Ruben, bo rzekła: Zaiste wejrzał Pan na utrapienie moje; a tak teraz miłować mię będzie mąż mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'I zasię poczęła, i porodziła syna, a rzekła: Zaiste usłyszał Pan, żem ja była w nienawiści, przetoż dał mi też i tego; i nazwała imię jego Symeon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Potem jeszcze poczęła, i porodziła syna, i rzekła: I tym razem przyłączy się mąż mój do mnie, bom mu urodziła trzech synów; przetoż nazwała imię jego Lewi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Nad to jeszcze poczęła, i porodziła syna, i rzekła: Teraz już chwalić będę Pana; przetoż nazwała imię jego Juda, i przestała rodzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'A widząc Rachel, że nie rodziła Jakóbowi, zajrzała Rachel siostrze swej, rzekła do Jakóba: Daj mi syny, a jeźli nie dasz, umrę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Zapalił się tedy gniewem Jakób na Rachelę, i rzekł: Zażem ja Bóg, który zawściągnął płód żywota twego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'A ona rzekła: Oto służebnica moja Bala; wnijdźże do niej, i porodzi na kolanach moich, a będę też miała syny z niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'I dała mu Balę, służebnicę swoję, za żonę; i wszedł Jakób do niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Tedy poczęła Bala, i urodziła Jakóbowi syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'I rzekła Rachel: Skazał za mną Bóg, i usłyszał głos mój, a dał mi syna; i dlatego nazwała imię jego Dan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Potem zaś począwszy porodziła Bala, służebnica Racheli, drugiego syna Jakóbowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Tedy rzekła Rachel: Mężniem się biedziła z siostrą moją, a przemogłam; i nazwała imię jego Neftali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'A obaczywszy Lija, że przestała rodzić, wzięła też Zelfę, służebnicę swoję, i dała ją Jakóbowi za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'I urodziła Zelfa, służebnica Lii, Jakóbowi syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Zatem Lija rzekła: Przyszedł huf; i nazwała imię jego Gad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Porodziła też Zelfa, służebnica Lii, drugiego syna Jakóbowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'I rzekła Lija: To na szczęście moje; bo mię szczęśliwą będą zwały niewiasty; i nazwała imię jego Aser.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'I wyszedł Ruben czasu żniwa pszenicznego, i znalazł pokrzyki na polu, a przyniósł je do Lii, matki swej; i rzekła Rachel do Lii: Daj mi też proszę z pokrzyków syna twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'A ona jej odpowiedziała: A małoż na tem, żeś mi wzięła męża mego, iż też chcesz wziąć i pokrzyki syna mego? Tedy rzekła Rachel: Niechajże śpi z tobą tej nocy za pokrzyki syna twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'A gdy się wracał Jakób z pola pod wieczór, wyszła Lija przeciwko jemu, i rzekła: Do mnie wnijdziesz, gdyżem cię pewną zapłatą najęła sobie pokrzykami syna mego; i spał z nią onej nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Tedy wysłuchał Bóg Liję; i poczęła, i porodziła Jakóbowi syna piątego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'I rzekła Lija: Oddał mi Bóg zapłatę moją, żem była dała służebnicę moję mężowi mojemu; i nazwała imię jego Isaszar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Potem począwszy jeszcze Lija, porodziła szóstego syna Jakóbowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'I mówiła Lija: Obdarzył mnie Bóg zacnym upominkiem; już teraz będzie ze mną mieszkał mąż mój, bom mu urodziła sześciu synów; i nazwała imię jego Zabulon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Potem porodziła córkę, i nazwała imię jej Dyna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Wspomniał też Bóg, na Rachelę, i wysłuchał ją Bóg, a otworzył żywot jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Tedy począwszy porodziła syna, i rzekła: Odjął Bóg zelżywość moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'I nazwała imię jego Józef, mówiąc: Niech mi przyda Pan drugiego syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'I stało się, gdy porodziła Rachel Józefa, mówił Jakób do Labana: Puść mię, abym się wrócił do miejsca mego, i do ziemi mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Daj mi żony moje, i dzieci moje, za którem ci służył, że odejdę; bo ty wiesz posługi moje, jakom ci służył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'I rzekł do niego Laban: Proszę, jeźlim znalazł łaskę w oczach twoich, zostań ze mną; bom doznał tego, że mi Pan dla ciebie błogosławił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'I rzekł: Mianuj mi zapłatę twoję, a dam ci ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Tedy mu odpowiedział Jakób: Ty wiesz, jakom ci służył, i jaki był dobytek twój przy mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Bo ta trocha, którąś miał przede mną, rozmnożyła się wielce; i błogosławił ci Pan na przyjście moję, a teraz kiedyż ja się też starać będę o dom swój?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'I rzekł: Cóżci mam dać? I odpowiedział Jakób: Nie dasz mi nic; ale jeźli to uczynisz coć powiem, tedy się wrócę, a będę pasł i strzegł bydła twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Przejdę dziś przez wszystkie trzody twoje, odłączając stamtąd każde bydlę pstre i nakrapiane, i każde bydlę płowe między owcami, a nakrapiane i pstre między kozami; to będzie zapłatą moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'I da świadectwo o mnie sprawiedliwość moja na potem, gdy przyjdzie do zapłaty mojej przed tobą; wszystko co nie będzie pstre i nakrapiane między kozami, a płowe między owcami, niech będzie za kradzież poczytane przy mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Tedy rzekł Laban: Oby się stało według słowa twego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'I odłączył onegoż dnia kozły strokate, i nakrapiane, i wszystkie kozy pstre, i nakrapiane, i wszystkie, co jaką białą odmianę miały, także i płowe między owcami, i oddał je do rąk synów swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'I odłączył się Laban od Jakóba, jakoby na trzy dni drogi; a Jakób pasł ostatek owiec Labanowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Nabrał tedy Jakób prętów zielonych topolowych, i laskowych, i kasztanowych, i obłupił miejscami skórę ich do białego, obnażając białość, która na prętach była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'I nakładł onych prętów, które był obłupił, do rynien i do koryt, gdzie lano wody (gdy przychodziły owce, aby piły) nakładł ich przeciwko owcom, aby poczynały, gdyby pić przychodziły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'I poczynały owce patrząc na one pręty, i rodziły jagnięta strokate, pstre i nakrapiane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'I odłączył Jakób jagnięta, a stawiał owce twarzą do jagniąt strokatych, i do wszystkich płowych w stadzie Labanowem, a swoje stada stawiał osobno, ani ich obracał ku stadu Labanowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'A gdy wszystkich owiec co rańszych przypuszczanie bywało, kładł Jakób pręty przed oczy owiec w koryta, aby poczynały patrząc na pręty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Lecz gdy późniejszych owiec przypuszczanie było, nie kładł ich: i były późniejsze Labanowe, a rańsze Jakóbowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'I tak zbogacił się on człowiek bardzo, i miał owiec wiele, i służebnic i sług, i wielbłądów, i osłów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Potem gdy usłyszał Jakób słowa synów Labanowych mówiących: Pobrał Jakób wszystko, co miał ojciec nasz, i z tego, co było ojca naszego, tej wszystkiej zacności dostał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Widział też Jakób twarz Labanową, a oto, nie był takim przeciwko niemu, jako przedtem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Tedy rzekł Pan do Jakóba: Wróć się do ziemi ojców twoich, i do rodziny twojej, a będę z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Przetoż posłał Jakób, i wyzwał Rachelę i Liję na pole do trzody swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'I rzekł im: Widzę ja twarz ojca waszego, że nie jest takim przeciwko mnie, jako przedtem, lecz Bóg ojca mego był ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Wy też same wiecie, żem ze wszystkich sił moich służył ojcu waszemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Ale ojciec wasz oszukał mię, i odmienił zapłatę moję po dziesięć kroć; jednak nie dopuścił mu Bóg, aby mi szkodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Jeźli kiedy powiedział: Pstre będą zapłatą twoją, tedy rodziły wszystkie owce jagnięta pstre; a gdy zaś mówił: Strokate będą zapłatą twoją, tedy rodziły wszystkie owce jagnięta strokate.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'I odjął Bóg dobytek ojca waszego, a dał go mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Stało się bowiem w ten czas, gdy się owce złączały, żem podniósł oczy swe, i widziałem przez sen, a oto, samcy złączały się z owcami strokatemi, pstremi, i biało nakrapianemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Tedy mi rzekł Anioł Boży we śnie: Jakóbie! A jam odpowiedział: Owom ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Potem rzekł: Podnieś teraz oczy swe, a obacz wszystkie samce złączające się z owcami strokatemi, pstremi, i biało nakrapianemi; bom widział wszystko, coć Laban uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Jam Bóg Betel, gdzieś namazał kamień, gdzieś mi poślubił ślub. Teraz tedy wstań, wynijdź z ziemi tej, a wróć się do ziemi rodziny twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Tedy odpowiedziała Rachel i Lija, i rzekły mu: Izaż jeszcze mamy cząstkę jaką i dziedzictwo w domu ojca naszego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Izażeśmy za obce nie były poczytane u niego? Iż nas przedał; i miałże by jeszcze do szczętu zjeść majętność naszę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Albowiem wszystko bogactwo, które odjął Bóg ojcu naszemu, nasze jest, i synów naszych; przetoż teraz wszystko uczyń, coć Bóg rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Wstał tedy Jakób, i wsadził syny swe, i żony swe na wielbłądy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'I zabrał wszystkę trzodę swoję, i wszystkę majętność swoję, której był nabył, dobytek nabycia swego, którego był nabył w krainie Syryjskiej, aby się wrócił do Izaaka, ojca swego, do ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'A Laban odszedł był strzyc owce swoje: wtem ukradła Rachel bałwany, które miał ojciec jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'I wykradł się Jakób potajemnie od Labana Syryjczyka, tak że mu nie oznajmił, iż uciekał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'I uciekł sam ze wszystkiem co miał, a wstawszy przeprawił się przez rzekę, i udał się ku górze Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'I dano znać Labanowi dnia trzeciego, że uciekł Jakób.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Który wziąwszy bracią swoję z sobą, gonił go przez siedem dni, i doścignął go na górze Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Lecz przyszedł Bóg do Labana Syryjczyka we śnie onej nocy, i rzekł mu: Strzeż się, abyś nie mówił z Jakóbem nic przykrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'I dogonił Laban Jakóba, a Jakób już był namiot swój rozbił na górze; Laban też rozbił namiot z bracią swą na onejże górze Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Tedy Laban rzekł do Jakóba: Cóżeś uczynił, żeś się wykradł potajemnie ode mnie, a uwiodłeś córki moje, jakoby pojmane mieczem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Przeczżeś potajemnie uciekł, a wykradłeś się ode mnie, a nie oznajmiłeś mi, gdyżbym cię był puścił z radością, i z pieśniami, i z bębnem, i z harfą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'I nie dopuściłeś mi, abym pocałował syny moje, i córki moje? Zaiste głupieś sobie począł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Jest to w mocy ręki mojej, uczynić wam co złego; ale Bóg ojca waszego przeszłej nocy rzekł do mnie, mówiąc: Strzeż się abyś z Jakóbem nie mówił nic przykrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'A teraz gdyć się chciało odejść, żeś wielce pragnął do domu ojca twego, czemużeś ukradł bogi moje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'I odpowiadając Jakób, rzekł do Labana: Iżem się bał, i myślałem, byś mi snać nie wydarł córek twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Lecz ten, u kogo znajdziesz bogi twoje, niech umrze; przed bracią naszą poznajże, co twego u mnie, i weźmij sobie; a nie wiedział Jakób, że je Rachel ukradła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Wszedł tedy Laban do namiotu Jakóbowego, i do namiotu Lii, i do namiotu obydwóch służebnic, a nie znalazł; a wyszedłszy z namiotu Lii wszedł do namiotu Racheli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'A Rachel wziąwszy one bałwany włożyła je pod sidło wielbłądowe, i usiadła na nich; i zmacał Laban wszystek namiot, a nie znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Tedy ona rzekła do ojca swego: Niech się nie gniewa pan mój, że nie mogę powstać przed twarzą twoją, bo według zwyczaju niewiast przypadło na mię; i szukał, a nie znalazł bałwanów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Rozgniewał się tedy Jakób, i fukał na Labana; a odpowiadając Jakób, rzekł do Labana: Cóż za przestępstwo moje, co za grzech mój, żeś mię gonił zapaliwszy się?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Otoś zmacał wszystek sprzęt mój: cóżeś znalazł ze wszystkiego sprzętu domu twego? połóż tu przed bracią moją, i bracią twoją, a niech rozsądzą między nami dwoma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Już dwadzieścia lat mieszkałem z tobą; owce twoje i kozy twoje nie pomiatały, a baranów stada twego nie jadałem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Rozszarpanego od zwierza nie przyniosłem ci, jam szkodę nagradzał; z ręki mojej szukałeś tego, co było ukradzione we dnie, i co było ukradzione w nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Bywało to, że we dnie trapiło mię gorąco, a mróz w nocy, tak, że odchadzał sen mój od oczu moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Jużem ci dwadzieścia lat w domu twoim służył; czternaście lat za dwie córki twoje, a sześć lat za bydło twoje; a odmieniałeś zapłatę moję po dziesięć kroć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'I by był Bóg ojca mego, Bóg Abrahama, i strach Izaaka, nie był przy mnie, pewnie byś mię był teraz próżnego puścił; ale na utrapienie moje, i na pracę rąk moich wejrzał Bóg, i przestrzegał cię nocy przeszłej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Tedy odpowiedział Laban, i rzekł do Jakóba: Córki te córki są moje, i synowie ci są synowie moi, i dobytek ten dobytek mój, i wszystko co widzisz, moje jest; a tym córkom moim, cóż dziś uczynię, albo synom ich, które zrodziły?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Pójdźże tedy, a uczyńmy przymierze, ja i ty, a będzie świadectwo między mną, i między tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'I wziął Jakób kamień, a postawił go na znak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'I rzekł Jakób do braci swej: Nazbierajcie kamieni; którzy nanosili kamieni, i uczynili kupę, i jedli tam na onej kupie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'I nazwał ją Laban Jegar Sahaduta, a Jakób ją nazwał Galed.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Bo mówił Laban: Kupa ta niech będzie świadkiem między mną i między tobą dzisiaj; przetoż Jakób nazwał imię jej Galed,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'I Myspa; albowiem rzekł Laban: Niech upatruje Pan między mną i między tobą, gdy się rozejdziemy jeden od drugiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Jeźli będziesz trapił córki moje, i jeźli pojmiesz żony nad córki moje, nie masz tu nikogo między nami; bacz, że Bóg jest świadkiem między mną i między tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'I rzekł nad to Laban do Jakóba: Oto, ta kupa kamieni, i oto, znak ten, którym postanowił między mną i między tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Świadkiem ta kupa, i świadkiem ten znak będzie tego, iż ja do ciebie nie pójdę dalej za tę kupę, i ty też nie pójdziesz do mnie za tę kupę, i za ten znak, na złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Bóg Abrahamów i Bóg Nachorów niechaj rozsądzą między nami, Bóg ojca ich. Przysiągł tedy Jakób przez strach ojca swego Izaaka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'I nabił Jakób bydła na górze, i wezwał braci swej ku jedzeniu chleba. Tedy jedli chleb, i nocowali na onej górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'Potem Laban wstawszy bardzo rano, pocałował syny swoje i córki swe, i błogosławił im; a odszedłszy, wrócił się Laban na miejsce swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'A Jakób też poszedł w drogę swoję i potkali się z nim Aniołowie Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'I rzekł Jakób ujrzawszy je: Obóz to Boży; i nazwał imię miejsca onego Mahanaim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Potem posłał Jakób posły przed sobą do Ezawa, brata swego, do ziemi Seir, do krainy Edomskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'I rozkazał im mówiąc: Tak rzeczecie do pana mego Ezawa: To mówi sługa twój Jakób: U Labana byłem gościem, i mieszkałem z nim aż do tego czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'A mam woły i osły, owce, i sługi, i służebnice, a posyłam odpowiedzieć panu memu, żebym znalazł łaskę w oczach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'I wrócili się posłowie do Jakóba, mówiąc: Przyszliśmy do brata twego Ezawa, który też idzie przeciwko tobie, a cztery sta mężów z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'I zląkł się Jakób bardzo a strwożył się; i rozdzielił lud, który z nim był, i owce, i woły, i wielbłądy, na dwa hufce;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'I rzekł: Jeźliby przyszedł Ezaw do jednego hufca, a poraziłby go, tedy hufiec, który pozostanie, będzie zachowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'I rzekł Jakób: Boże ojca mego Abrahama, i Boże ojca mego Izaaka, Panie, któryś do mnie rzekł: Wróć się do ziemi twojej, i do rodziny twojej, a uczynięć dobrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Mniejszym jest niż wszystkie zmiłowania, i niż wszystka prawda, którąś uczynił z sługą swym. Albowiem tylko o lasce mojej przeszedłem ten Jordan, a teraz mam dwa hufce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Wyrwij mię proszę z ręki brata mego, z ręki Ezawa; boć się go boję, by snać przyszedłszy nie zabił mię, i matki z synami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Wszakeś rzekł: Dobrze czyniąc będęć dobrze czynił, a rozmnożę nasienie twoje jako piasek morski, który zliczon być nie może, dla mnóstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'I przenocował tam onej nocy, i wziął z tego, co miał przy ręku, upominek dla Ezawa, brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'To jest kóz dwieście, i kozłów dwadzieścia, owiec dwieście, i baranów dwadzieścia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Wielbłądzic odchowujących młode, ze źrebięty ich, trzydzieści, krów czterdzieści, i wołów dziesięć, dwadzieścia oślic, i dziesięć ośląt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'I oddał je w ręce sług swoich, każde stado z osobna, i rzekł do sług swoich: Idźcie przede mną, a plac uczyńcie między stadem a między stadem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'I rozkazał pierwszemu, mówiąc: Gdy się spotka z tobą Ezaw, brat mój, a spyta cię, mówiąc: Czyjeś ty? i dokąd idziesz? a czyje to stado przed tobą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Tedy powiesz: Sługi twego Jakóba jest to upominek, posłany panu memu Ezawowi, a oto, i sam idzie za nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Także też rozkazał drugiemu, i trzeciemu, i wszystkim idącym za temi stady, mówiąc: Temiż słowy mówcie do Ezawa, gdy go potkacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Powiecie mu też: Oto, sługa twój Jakób idzie za nami, mówił bowiem: Ubłagam oblicze jego upominkiem, który idzie przede mną, a potem ujrzę oblicze jego; owa mię snać w łaskę przyjmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'I poszedł w przód on upominek przed obliczem jego, a sam przenocował onej nocy z hufcem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Wstawszy tedy onej nocy, wziął obie żony swe, i dwie służebnice swoje, i jedenaście synów swoich, i przeszedł przez bród Jabok,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'A wziąwszy je, przeprawił je przez tęż rzekę, i przeprowadził wszystko, co miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'A tylko sam Jakób został.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'A oto, biedził się z nim mąż aż do wejścia zorzy; który widząc, że go nie mógł przemóc, uderzył Jakóba w staw biodry jego, i wytrąciła się z stawu biodra Jakóbowa, gdy się z nim mocował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'I rzekł: Puść mię, bo już wschodzi zorza. I odpowiedział: Nie puszczę cię, aż mi będziesz błogosławił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Tedy mu rzekł: Co za imię twoje? I odpowiedział: Jakób.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'I rzekł: Nie będzie nazywane więcej imię twoje Jakób, ale Izrael; boś sobie mężnie poczynał z Bogiem, i z ludźmi, i przemogłeś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'I spytał Jakób mówiąc: Oznajmij mi proszę imię twoje; a on odpowiedział: Czemu się pytasz o imieniu mojem? I tamże mu błogosławił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Tedy nazwał Jakób imię miejsca onego Fanuel, mówiąc: Iżem widział Boga twarzą w twarz, a zachowana jest dusza moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'I weszło mu słońce, kiedy minął miejsce Fanuel, a on uchramował na biodrę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Przetoż nie jadają synowie Izraelscy żyły skurczonej, która jest przy stawie biodry, aż do dnia tego, iż był uderzył w staw biodry Jakóbowej, i w żyłę skurczoną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'A podniósłszy Jakób oczy swe ujrzał, a oto, Ezaw idzie, a z nim cztery sta mężów; i rozdzielił dzieci, z osobna Lii, i z osobna Racheli, i z osobna dwu służebnic.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'I postawił służebnice, i dzieci ich, na przodku, a Liję, i syny jej, za nimi, Rachelę zaś z Józefem na ostatku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'A sam szedł przed nimi, i pokłonił się aż do ziemi siedem kroć, niż przyszedł do brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'I zaszedł mu drogę Ezaw, i obłapiwszy go, upadł na szyję jego, i całował go; i płakali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Potem podniósłszy (Ezaw) oczy swe, ujrzał żony i dzieci, i rzekł: A ci co zacz są, twoiż to? i odpowiedział: Dziatki to są, które Bóg dał z łaski słudze twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'I przybliżyły się służebnice i synowie ich, a pokłoniły się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Przybliżyła się też i Lija, i dzieci jej, i pokłonili się; a potem przybliżył się Józef i Rachel, i pokłonili się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'I rzekł Ezaw: A ów wszystek hufiec na co, z którymem się spotkał? Odpowiedział Jakób: Abym znalazł łaskę przed oczyma pana mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Tedy rzekł Ezaw: Mam ja dosyć, bracie miły, miej ty swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'I rzekł Jakób: Nie tak będzie proszę; jeźlim teraz znalazł łaskę w oczach twoich, weźmij upominek mój z ręki mojej, przeto, iżem widział oblicze twoje, jakobym widział oblicze Boże, i łaskawieś mię przyjął;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Przyjmijże proszę dar mój, którym ci przyniósł, gdyż mię hojnie błogosławił Bóg, a mam wszystkiego dosyć. A tak uprosił go, że to przyjął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Tedy rzekł Ezaw: Ruszmy się, a idźmy, a ja pójdę przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'I odpowiedział mu Jakób: Wie pan mój, że z sobą mam dziatki młode, i owce kotne, i krowy cielne, które jeźlibym przegnał dnia jednego, pozdychają wszystkie stada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Niech w przód proszę jedzie pan mój przed sługą swoim, a ja poprowadzę się z lekka, jako zdąży trzoda, która jest przede mną, i jako nadążą dzieci, aż przyjdę do pana mego do Seir.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Tedy rzekł Ezaw: Niech wżdy zostawię przy tobie cokolwiek ludu, który jest ze mną. A on odpowiedział: A na cóż to? byłem znalazł łaskę w oczach pana mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'I wrócił się dnia onego Ezaw drogą swą do Seir.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'A Jakób obrócił się do Suchot, i zbudował sobie dom, i dla stad swoich poczynił obory, a dla tego nazwał imię miejsca onego Suchot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'I przyszedł Jakób zdrowo do miasta Sychem, które było w ziemi Chananejskiej, gdy się wrócił z Padan Syryjskiego, i położył się przed miastem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'I kupił część pola, na którem rozbił namiot swój, od synów Hemora, ojca Sychemowego, za sto jagniąt;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'A postawił tam ołtarz, i nazwał go: Mocny Bóg Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'I wyszła Dyna, córka Lii, którą była urodziła Jakóbowi, aby oglądała córki onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'A ujrzawszy ją Sychem, syn Hemora Hewejczyka, książęcia ziemi onej, porwał ją, i spał z nią, i zelżył ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'I spoiła się dusza jego z Dyną, córką Jakóbową, a rozmiłowawszy się dzieweczki, mówił do serca jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Tedy Sychem rzekł do Hemora, ojca swego, mówiąc: Weźmij mi te dzieweczkę za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'A gdy Jakób usłyszał, że zgwałcona była Dyna, córka jego, a synowi jego byli z bydłem jego na polu, zamilczał tego Jakób, aż się oni zwrócili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Tedy wyszedł Hemor, ojciec Sychemów, do Jakóba, aby z nim mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'A synowie Jakóbowi gdy przyszli z pola, a usłyszeli to, boleścią zjęci byli mężowie oni, i rozgniewali się bardzo, że tę sprośność uczynił w Izraelu, śpiąc z córką Jakóbową, co być nie miało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'I rzekł Hemor do nich mówiąc: Sychem, syn mój, przyłożył serce swe ku córce waszej; dajcież mu ją proszę za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'A spowinowaćcie się z nami, córki wasze dawając nam, a córki nasze pojmując sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'I będziecie z nami mieszkać, a ziemia będzie przed wami; mieszkajcie, i handlujcie w niej, i osadzajcie się w niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'I mówił też Sychem do ojca jej, i braci jej: Niech znajdę łaskę w oczach waszych, a co mi rzeczecie, to dam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Podwyższcie mi znacznie wiana, i upominków żądajcie, a dam jako mi rzeczecie; tylko mi dajcie tę dzieweczkę za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Tedy odpowiedzieli synowie Jakóbowi Sychemowi i Hemorowi, ojcu jego, na zdradzie mówiąc z nimi, dla tego iż zgwałcił Dynę, siostrę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'I rzekli im: Nie możemy tej rzeczy uczynić, abyśmy mieli dać siostrę naszę mężowi nieobrzezanemu; bo to obrzydła rzecz u nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'A wszakże tym sposobem wam pozwolimy, jeźliże chcecie być nam podobni, aby był obrzezany między wami każdy mężczyzna;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Tedy wam damy córki nasze, a córki wasze pojmiemy sobie, i będziemy mieszkać z wami, a będziemy ludem jednym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Ale jeźlibyście nas nie usłuchali, abyście się obrzezali, weźmiemy córkę naszę, i odejdziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'I podobała się ta rzecz ich Hemorowi i Sychemowi, synowi Hemorowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Tedy nie odkładał on młodzieniec długo tej rzeczy, bo się był rozmiłował córki Jakóbowej; a on był ze wszech najzacniejszy w domu ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'I przyszedł Hemor i Sychem, syn jego, do bramy miasta swego, i rzekli do mężów miasta swego mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Mężowie ci spokojnie żyją z nami; niechże mieszkają w tej ziemi, i niech handlują w niej, gdyż oto ziemia nasza dosyć jest przestronna dla nich; córki ich będziemy brać sobie za żony, a córki nasze będziemy im dawać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Ale tym sposobem pozwalają mężowie ci, mieszkać z nami, abyśmy byli jednym ludem: żeby był obrzezan między nami każdy mężczyzna, tak jako oni są obrzezani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Trzody ich, i majętności ich, i wszystkie bydła ich, azaż nie nasze będą? na to tylko im pozwólmy, a będą mieszkać z nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'I usłuchali Hemora i Sychema, syna jego, wszyscy wychodzący z bramy miasta jego, i obrzezał się każdy mężczyzna, cokolwiek ich wychodziło z bramy miasta jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'I stało się dnia trzeciego gdy byli w najcięższym bólu, tedy wzięli dwaj synowie Jakóbowi, Symeon i Lewi, bracia Dyny, każdy miecz swój, a weszli do miasta śmiele, i pomordowali wszystkie mężczyzny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Hemora też i Sychema, syna jego, zabili mieczem, a wziąwszy Dynę z domu Sychemowego, odeszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Drudzy też synowie Jakóbowi przyszli do pobitych, i złupili miasto, przeto iż zgwałcili siostrę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Owce ich, i woły ich, i osły ich, i co w mieście było, i co na polu, pobrali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'I wszystkę majętność ich, i wszystkie dzieci ich, i żony ich, w niewolą zabrali, i wybrali wszystko, co w domach było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Tedy rzekł Jakób do Symeona i Lewiego: Zafrasowaliście mię, a przywiedliście mię w ohydę u obywateli ziemi tej, u Chananejczyków i Ferezejczyków; ja niewielką liczbę ludu mam, a zebrawszy się przeciwko mnie, porażą mię, a tak zginę ja, i dom mój');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'A oni odpowiedzieli: Izali jako wszetecznicy miał używać siostry naszej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Rzekł potem Bóg do Jakóba: Wstań, wstąp do Betela, a mieszkaj tam, i uczyń tam ołtarz Bogu, któryć się ukazał, gdyś uciekał przed obliczem Ezawa, brata twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Tedy rzekł Jakób do domowników swych, i do wszystkich, którzy z nim byli: Odrzućcie bogi cudze, którzy w pośrodku was są, a oczyśćcie się, i odmieńcie szaty wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'A wstawszy pójdźmy do Betela, i uczynię tam ołtarz Bogu, który mię wysłuchał w dzień utrapienia mego, i był ze mną w drodze, którąm chodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'A oddali Jakóbowi wszystkie bogi cudze, które mieli, i nausznice, które były na uszach ich, i zakopał je Jakób pod onym dębem, który był niedaleko Sychem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'I wyszli stamtąd; a strach Boży padł na miasta, które były około nich, iż nie gonili synów Jakóbowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Przyszedł tedy Jakób do Luzy, która jest w ziemi Chananejskiej, ta jest Betel, sam i wszystek lud, który z nim był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'I zbudował tam ołtarz, a nazwał miejsce ono El Betel; bo mu się tam był Bóg ukazał, gdy uciekał przed obliczem brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Tedy umarła Debora, mamka Rebeki, i pogrzebiona jest przy Betel pod dębem, i nazwał imię onego miejsca, Allon Bachut.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'I ukazał się Bóg znowu Jakóbowi, gdy się wracał z Padan Syryjskiego, i błogosławił mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'I rzekł mu Bóg: Imię twoje jest Jakób; nie tylko będzie zwane imię twoje na potem Jakób, ale Izrael będzie imię twoje; i nazwał imię jego Izrael.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'I rzekł mu Bóg: Jam jest Bóg wszechmogący, rozradzaj się, i rozmnażaj się; naród, i mnóstwo narodów będzie z ciebie, a królowie z biódr twoich wynijdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'I ziemię, którąm dał Abrahamowi i Izaakowi, tobie ją dam, i nasieniu twemu po tobie dam tę ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'I odszedł Bóg od niego z miejsca, na którem mówił z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Zatem postawił Jakób znak na miejscu onem, gdzie Bóg mówił z nim, a znak on był kamienny, i pokropił go pokropieniem, i polał go oliwą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'I nazwał Jakób imię miejsca onego, gdzie Bóg z nim mówił, Betel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Potem odeszli z Betel; i było jeszcze jakoby mila drogi do Efraty, i rodziła Rachel a ciężkie rodzenie miała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'A gdy ciężko pracowała przy rodzeniu, rzekła baba do niej: Nie bój się; bo i tego syna będziesz miała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'A stało się, gdy wychodziła dusza jej, (bo tamże umarła), nazwała imię jego Ben Oni; ale ojciec jego nazwał go Benjamin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'A tak umarła Rachel, i pogrzebiona jest na drodze ku Efracie; tać jest Betlehem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'I postawił Jakób znak nad grobem jej; toć jest znak grobu Rachelinego aż po dziś dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'I poszedł stamtąd Izrael, i rozbił namiot swój za wieżą Heder.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Stało się tedy, gdy mieszkał Izrael w onej krainie, że szedł Ruben, i spał z Balą, założnicą ojca swego, i usłyszał to Izrael. A było synów Jakóbowych dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Synowie Lii: pierworodny Jakóbów Ruben, i Symeon, i Lewi, i Judas, i Isaszar, i Zabulon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Synowie Racheli: Józef i Benjamin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'A synowie Bali, służebnicy Rachelinej: Dan i Neftali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Synowie też Zelfy, służebnicy Lii: Gad i Aser. Ci są synowie Jakóbowi, którzy mu się urodzili w Padanie Syryjskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'I przyszedł Jakób do Izaaka, ojca swego, do Mamre, do miasta Arba, to jest Hebron, gdzie mieszkał Abraham i Izaak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'A było dni Izaakowych sto lat, i osiemdziesiąt lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'I dokonał Izaak, i umarł, i przyłączony jest do ludu swego, stary i pełen dni; a pogrzebli go Ezaw, i Jakób, synowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'A teć są rodzaje Ezawowe, który jest Edom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ezaw pojął żony swoje z córek Chananejskich: Adę, córkę Elona, Hetejczyka; i Oolibamę, córkę Any, córki Sebeona, Hewejczyka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'I Basemat, córkę Ismaelowę, siostrę Nebajotowę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'I urodziła Ada Ezawowi Elifasa, a Basemat urodziła Rehuela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Oolibama też urodziła Jehusa, i Jeloma, i Korego. Ci są synowie Ezawowi, którzy mu się urodzili w ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'I wziął Ezaw żony swoje, i syny swoje, i córki swoje, i wszystkie dusze domu swego, i trzody swoje, i wszystko bydło swoje, i wszystkę majętność swoję, której był nabył w ziemi Chananejskiej, i odszedł do ziemi inszej od Jakóba, brata swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Bo była majętność ich wielka, że nie mogli mieszkać pospołu, i nie mogła ich znieść ziemia pielgrzymowania ich, dla mnóstwa stad ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'I mieszkał Ezaw na górze Seir, a ten Ezaw jest Edom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'A teć są pokolenia Ezawa, ojca Edomczyków, na górze Seir.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'I te są imiona synów Ezawowych: Elifas, syn Ady, żony Ezawowej, Rehuel, syn Basematy, żony Ezawowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Synowie zaś Elifasowi byli: Teman, Omar, Sefo, i Gaatan, i Kenaz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'A Tamna była założnica Elifasa, syna Ezawowego, i urodziła Elifasowi Amaleka. Ci są synowie Ady, żony Ezawowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Ci też są synowie Rehuelowi: Nahat i Zara, Samma i Meza; ci byli synowie Basematy, żony Ezawowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Ci zaś byli synowie Oolibamy, córki Any, córki Sebeona, żony Ezawowej: i urodziła Ezawowi Jehusa, i Jeloma, i Korego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Teć są książęta z synów Ezawowych, synowie Elifasa pierworodnego Ezawowego: Książę Teman, książę Omar, książę Sefo, książę Kenaz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Książę Kore, książę Gaatam, książę Amalek. Teć książęta z Elifasa poszły, w ziemi Edomskiej, ci są synowie z Ady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Ci zaś są synowie Rehuela, syna Ezawowego: Książę Nahat, książę Zara, książę Samma, książę Meza. Te książęta poszły z Rehuela, w ziemi Edomskiej, ci są synowie Basematy żony Ezawowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Ci zaś są synowie Oolibamy, żony Ezawowej: Książę Jehus, książę Jelom, książę Kore. Te książęta poszły z Oolibamy, córki Any, żony Ezawowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Ci są synowie Ezawowi, i te książęta ich. Onże jest Edom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Ci też są synowie Seira Chorejczyka, mieszkający w onej ziemi: Lotan, i Sobal, i Sebeon, i Hana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'I Dysson, i Eser, i Disan; teć są książęta Chorejskie, synowie Seirowi w ziemi Edomskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'A synowie Lotanowi byli Chory i Heman; a siostra Lotanowa Tamna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Synowie zaś Sobalowi: Halwan, i Manahat, i Hewal, Sefo, i Onam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Synowie też Sebeonowi ci są: Aja i Ana. Tenci to Ana, który wynalazł muły na puszczy, gdy pasł osły Sebeona, ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Dzieci zaś Anowe te są: Dyson, i Oolibama, córka Anowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'A synowie Dysonowi: Hamdan, i Eseban, i Jetran, i Charan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'A synowie Eserowi są ci: Balaan, i Zawan, i Akan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'A zasię synowie Dysanowi: Hus i Aran.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Teć są książęta Chorejskie: książę Lotan, książę Sobal, książę Sebeon, książę Ana,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Książę Dyson, książę Eser, książę Dysan. Te były książęta Chorejskie, według księstw ich, w ziemi Seir.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Ci też byli królowie, którzy królowali w ziemi Edomskiej, pierwej niż królował król nad syny Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Królował tedy w Edom Bela, syn Beorów, a imię miasta jego Dynhaba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'I umarł Bela, a królował miasto niego Jobab, syn Zerachów z Bosry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'I umarł Jobab, a królował miasto niego Chusam, z ziemi Temańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'I umarł Chusam, a królował miasto niego Hadad, syn Badadów, który poraził Madyjańczyki, na polu Moabskiem, a imię miasta jego Hawid.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'I umarł Hadad, a królował miasto niego Samla z Masreki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'I umarł Samla, a królował miasto niego Saul, z Rechobot u rzeki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'I umarł Saul, a królował miasto niego Balanan, syn Achborów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'I umarł Balanan, syn Achborów, a królował miasto niego Hadar, a imię miasta jego Pahu, a imię żony jego Mehetabel, córka Matredy, córki Mezaabowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Teć są imiona książąt Ezawowych, według ich pokolenia, i według miejsc ich, i imion ich: Książę Tamna, książę Halwa, książę Jetet.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Książę Oolibama, książę Ela, książę Pynon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Książę Kenaz, książę Teman, książę Mabsar');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Książę Magdyjel, książę Hyram, te są książęta Edomskie, według mieszkania ich, w ziemi osiadłości ich. Ten jest Ezaw, ojciec Edomczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'I mieszkał Jakób w ziemi, gdzie przychodniem był ojciec jego, w ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Teć są pokolenia Jakóbowe: Józef, gdy miał siedemnaście lat, pasł z bracią swoją trzody, (będąc pacholęciem), z synami Bali, i z synami Zelfy, żon ojca swego; i odnosił Józef sławę ich złą do ojca ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'A Izrael miłował Józefa nad wszystkie syny swe, iż mu się był w starości jego urodził, i sprawił mu suknią rozmaitych farb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'A widząc bracia jego, że go miłował ojciec ich nad wszystkę bracią jego, nienawidzili go, i nie mogli nic łaskawie z nim mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'I śnił się Józefowi sen, a gdy go powiedział braci swej, tem go więcej mieli w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Bo rzekł do nich: Słuchajcie proszę snu tego, który mi się śnił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Otośmy wiązali snopy na polu, a oto, wstawszy snop mój stanął, a około niego stojące snopy wasze kłaniały się snopowi mojemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'I odpowiedzieli mu bracia jego: Izali królować będziesz nad nami? i panować nam będziesz? stądże go jeszcze mieli w większej nienawiści, dla snów jego, i dla słów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Śnił mu się też jeszcze drugi sen, i powiedział go braci swej, mówiąc: Oto mi się znowu śnił sen: A ono słońce i miesiąc, i jedenaście gwiazd kłaniało mi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'I powiedział ojcu swemu i braci swej, i gromił go ojciec jego i mówił mu: Cóż to za sen, coć się śnił? Izali przyjdziemy, ja i matka twoja z bracią twoją, abyśmyć się kłaniali aż do ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'I nienawidzili go bracia jego; ale ojciec jego pilnie uważał tę rzecz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'I odeszli bracia jego, aby paśli trzody ojca swego w Sychem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Tedy rzekł Izrael do Józefa: Izali bracia twoi nie pasą w Sychem? pójdźże, a poślę cię do nich; a on odpowiedział: Otom ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Rzekł mu tedy: Idźże teraz, a dowiedz się, jako się mają bracia twoi, i co się dzieje z trzodami, i dasz mi znać. Wysłał go tedy z doliny Hebron, i przyszedł do Sychem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'I nadszedł go niektóry mąż, a on się błąkał po polu; i pytał go mąż on mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Czegóż szukasz? A on odpowiedział: Braci mojej szukam; powiedz mi proszę, gdzie oni pasą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Tedy rzekł on człowiek: Odeszli stąd; bom słyszał, gdy mówili: Pójdźmy do Dotain. I szedł Józef za bracią swoją, a znalazł je w Dotain.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'I ujrzeli go z daleka, a pierwej niż do nich przyszedł, radzili o nim, aby go zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'I mówili jeden do drugiego: Onoż mistrz on snów idzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Teraz tedy pójdźcie, a zabijmy go, i wrzućmy go w jaką studnią, a rzeczemy: Zły go zwierz pożarł; a tak obaczymy, na co mu wynijdą sny jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Co gdy usłyszał Ruben, chciał go wybawić z rąk ich, mówiąc: Nie zabijajmy go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Nad to rzekł do nich Ruben: Nie wylewajcie krwi, ale wrzućcie go w tę studnią, która jest na puszczy, a ręki nie ściągajcie nań. A to mówił, aby go wybawił z rąk ich, i powrócił go ojcu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'I stało się, gdy przyszedł Józef do braci swej, zwlekli go z sukni jego, z sukni rozmaitych farb, którą miał na sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'A porwawszy go, wrzucili go w studnią, która studnia była czcza, i nie było w niej wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'A usiadłszy, aby jedli chleb, podnieśli oczy swe, i ujrzeli, a ono poczet Ismaelitów, idących z Galaad; a wielbłądy ich niosły korzenie, i kadzidło, i myrrę, a szły, aby to zaniosły do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Tedy rzekł Judas do braci swej: Cóż za pożytek, choćbyśmy zabili brata naszego, i zataili krwi jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Pójdźcie, a przedajmy go Ismaelitom, a ręka nasza niech nie będzie na nim; brat bowiem nasz, i ciało nasze jest; i usłuchali go bracia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'A gdy mijali oni mężowie, Madyjańscy kupcy, tedy wyciągnęli, i wyjęli Józefa z studni, i sprzedali Józefa Ismaelitom za dwadzieścia srebrników, którzy zaprowadzili Józefa do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Tedy się wrócił Ruben do onej studni, a oto, już nie było Józefa w studni; i rozdarł szaty swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'A wróciwszy się do braci swej, rzekł: Pacholęcia nie masz, a ja dokąd? ja dokąd pójdę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Tedy wzięli suknią Józefowe, i zabili kozła, a umaczali suknią we krwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'I posłali onę suknią rozmaitych farb, aby ją zaniesiono do ojca jego, i rzekli: Tęś my znaleźli, poznajże teraz, jeźli to suknia syna twego, czyli nie');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'A poznawszy ją, rzekł: Suknia jest syna mego; zwierz zły pożarł go; koniecznie rozszarpany jest Józef.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Tedy rozdarłszy Jakób szaty swe, włożył wór na biodra swoje, żałując syna swego przez wiele dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'I zeszli się wszyscy synowie jego, i wszystkie córki jego, aby go cieszyli, lecz nie dał się cieszyć, ale mówił: Zaprawdę zstąpię za synem moim do grobu; i płakał go ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'A Madyjańczycy sprzedali Józefa do Egiptu Potyfarowi, dworzaninowi Faraonowemu, hetmanowi żołnierstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'I stało się czasu onego, że Judas odszedł od braci swej, i wstąpił do niektórego męża Odolamickiego, którego imię było Chyra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'I ujrzał tam Judas córkę męża Chananejskiego, którego zwano Sua; a pojąwszy ją, wszedł do niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'A ona począwszy porodziła syna, i nazwała imię jego Her.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Zasię począwszy porodziła syna, i nazwała imię jego Onan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Nad to jeszcze urodziła syna, i nazwała imię jego Sela; a Judas był w Chezybie, gdy mu urodziła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'I dał Judas żonę Herowi pierworodnemu swemu, której imię było Tamar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'I był Her, pierworodny Judasów, zły w oczach Pańskich, i zabił go Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Tedy rzekł Judas do Onana: Wnijdź do żony brata twego, a złącz się z nią prawem powinowactwa, i wzbudź nasienie bratu twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Lecz wiedząc Onan, iż to potomstwo nie jemu być miało, gdy wchodził do żony brata swego, tracił z siebie nasienie na ziemię, aby nie wzbudził potomstwa bratu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'I nie podobało się to Panu, co Onan czynił; przeto go też Pan zabił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Zatem rzekł Judas do Tamary, niewiasty swej: Mieszkaj wdową w domu ojca twego, aż urośnie Sela, syn mój, bo rzekł: By on też snać nie umarł jako bracia jego. I odeszła Tamar, i mieszkała w domu ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'A gdy minęło wiele dni, umarła córka Suego, żona Judasowa; i pocieszywszy się Judas, szedł do tych, co strzygli owce jego, sam i Chyra, towarzysz jego, Odolamita, do Timnat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'I oznajmiono to Tamarze, mówiąc: Oto, świeker twój idzie do Timnat, aby strzygł owce swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Która złożywszy z siebie szaty wdowieństwa swego, okryła się rąbkiem, i zatknęła się, i usiadła na rozstaniu drogi, która wiedzie do Timnat; bo widziała, że był urósł Sela, a ona nie była mu dana za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'A ujrzawszy ją Judas, mniemał, że to nierządnica, bo zakryła była twarz swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Tedy ustąpiwszy do niej z drogi, mówił: Proszę niech wnijdę do ciebie; albowiem nie wiedział, żeby jego synowa była. I rzekła: Cóż mi dasz, żebyś do mnie wszedł?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'I odpowiedział: Poślęć koźlątko z trzody; a ona rzekła: Daszże mi zastaw, aż mi je przyślesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'I rzekł: Cóż ci mam dać w zastaw? A ona odpowiedziała: Pierścień twój, i chustkę twoję, i laskę twoję, którą masz w ręce swej. Tedy jej dał, i wszedł do niej; a poczęła z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'A wstawszy odeszła, i złożywszy z siebie odzienie swoje, oblekła się w szaty wdowieństwa swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Potem posłał Judas koźlątko, przez rękę towarzysza swego Odolamitę, aby odebrał zastawę z ręki niewiasty onej; ale jej nie znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'I pytał mężów miejsca onego, mówiąc: Gdzie jest nierządnica ona, która była na rozstaniu tej drogi? Którzy odpowiedzieli: Nie było tu nierządnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Wrócił się tedy do Judasa, i rzekł: Nie znalazłem jej; lecz i mężowie miejsca onego powiedzieli: Nie było tu żadnej nierządnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Tedy rzekł Judas: Niechże sobie ma ten zakład, abyśmy nie byli na wzgardę; otom posyłał to koźlątko, a tyś jej nie znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'I stało się, jakoby po trzech miesiącach, powiedziano Judzie, mówiąc: Dopuściła się nierządu Tamar, synowa twoja, a oto, już brzemienna jest z nierządu. Tedy rzekł Judas: Wywiedźcie ją, aby była spalona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'A gdy była wywiedziona, posłała do świekra swego, mówiąc: Z męża, którego te rzeczy są, jestem brzemienna. Przy tem powiedziała: Poznaj proszę, czyj to pierścień, i chustka, i laska?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Tedy poznawszy to Judas rzekł: Sprawiedliwsza jest nad mię, ponieważem jej nie dał Seli, synowi memu; i więcej jej nie uznał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'I stało się, gdy przyszedł czas rodzenia jej, oto bliźnięta były w żywocie jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'A gdy rodziła, wytknęło rękę jedno dziecię, którą ująwszy baba, uwiązała u ręki nić czerwoną mówiąc:Ten pierwej wynijdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'I stało się, gdy zasię wciągnęło rękę swoję, oto, wyszedł brat jego; i rzekła: Czemuś przerwał? na tobie niech będzie rozerwanie; i nazwała imię jego Fares.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'A potem wyszedł brat jego, na którego ręce była nić czerwona; i nazwała imię jego Zera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Tedy Józef był zawiedzion do Egiptu; i kupił go Potyfar, dworzanin Faraonów, hetman żołnierstwa, mąż Egipczanin, z ręki Ismaelitów, którzy go tam byli zawiedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'I był Pan z Józefem, który był mężem szczęśliwie postępującym, a mieszkał w domu pana swego Egipczanina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'I baczył pan jego, że Pan był z nim, a iż wszystko co on czynił, Pan szczęścił w ręku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'I znalazł Józef łaskę w oczach jego, i służył mu; i przełożył go nad domem swym, a podał wszystko co miał, w ręce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'I stało się, gdy go przełożył nad domem swym, i nad wszystkiem, co miał, błogosławił Pan domowi Egipczanina dla Józefa; i było błogosławieństwo Pańskie nad wszystkiem, cokolwiek miał w domu i na polu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Przetoż poruczył wszystko, co miał, w ręce Józefowe, i ni o czem u siebie nie wiedział, tylko o chlebie, którego pożywał. A był Józef pięknej twarzy, i wdzięczny na wejrzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'I stało się potem, iż obróciła żona pana jego oczy swoje na Józefa, i rzekła: Śpij ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Ale nie chciał: i rzekł do żony pana swego: Oto, pan mój nie wie, tak jako ja, co jest w domu jego; bo wszystko, co miał, podał w ręce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'I nie masz nikogo w domu tym nad mię przedniejszego, i nie wyjął mi nic z mocy, prócz ciebie, przeto żeś ty jest żona jego; jakoż bym tedy miał uczynić tę wielką złość, i grzeszyć przeciwko Bogu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'I stało się, gdy ona namawiała Józefa na każdy dzień, a on jej nie zezwalał, aby spał z nią, albo bywał z nią:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Tedy dnia niektórego, gdy wszedł do domu, dla odprawowania pracy swej, a nie było tam z domowników nikogo w domu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Uchwyciła go za szatę jego, mówiąc: Śpij ze mną. Ale on zostawiwszy szatę swoję w ręku jej, uciekł, i wyszedł precz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'A gdy ona obaczyła, iż zostawił szatę swoję w ręku jej, a uciekł precz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Tedy zawołała na czeladź domu swego, i rzekła do nich, mówiąc: Wejcie, wprowadził pan do nas męża Hebrejczyka, aby nas zelżył; albowiem wszedł do mnie, aby ze mną spał, ażem wołała głosem wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'A gdy usłyszał, żem wyniosła głos mój, i zawołała, zostawiwszy szatę swoję u mnie, uciekł, i wyszedł precz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'I zatrzymała jego szatę u siebie, aż przyszedł pan jego do domu swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'I rzekła do niego w te słowa, mówiąc: Wszedł do mnie sługa ten Hebrejczyk, któregoś przywiódł do nas, aby mię zelżył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'A gdym podniosła głos swój, i zawołała, tedy zostawił szatę swą u mnie, i uciekł precz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'I stało się, gdy usłyszał pan jego słowa żony swojej, które rzekła do niego, mówiąc: Tak mi uczynił sługa twój, rozgniewał się bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'I wziął pan Józefa, a dał go do domu więzienia, tam, gdzie więźnie królewskie sadzano, i był tam w domu więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'A Pan był z Józefem, i skłoniwszy ku niemu miłosierdzie, dał mu łaskę w oczach przełożonego nad domem więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Tedy przełożony nad domem więzienia, podał w moc Józefowi wszystkie więźnie, którzy byli w domu więzienia; a wszystko, co tam czynić mieli, to on sprawował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'A przełożony nad domem więzienia nie doglądał tego, czego mu się powierzył, dla tego iż Pan był z nim, a co on czynił, to Pan szczęścił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'I stało się potem, że coś przewinęli podczaszy króla Egipskiego, i piekarz przeciw panu swemu, królowi Egipskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'I rozgniewał się Farao na obu dworzanów swoich, na przełożonego nad podczaszymi, i na przełożonego nad piekarzami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'A dał je do więzienia w dom hetmana żołnierzów, na miejsce, gdzie był Józef więźniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'I oddał im hetman żołnierzów Józefa, i służył im; i byli przez niemały czas w więzieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Tedy się onym obiema śnił sen, każdemu sen jego, jednejże nocy, każdemu według wykładu snu jego, podczaszemu i piekarzowi króla Egipskiego, którzy byli więźniami w domu więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'A przyszedłszy do nich Józef rano, ujrzał je, a oto byli strwożeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'I pytał dworzan Faraonowych, którzy byli z nim w więzieniu, w domu pana jego, mówiąc: Czemużeście dziś tak smutnej twarzy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'I odpowiedzieli mu: Śnił się nam sen, a nie masz kto by go wyłożył. Tedy rzekł do nich Józef: Izali nie Boże są wykłady? powiedzcie mi proszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'A tak powiedział przełożony nad podczaszymi sen swój Józefowi, i rzekł mu: Śniło mi się, a oto winna macica przede mną,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'A na winnej macicy były trzy gałązki, a ona jakoby pąki wypuszczała, a wychodził kwiat jej, i dostawały się jagody gron winnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'A kubek Faraonów był w ręce mojej, wziąłem tedy jagody, i wytłaczałem je w kubek Faraonów, i podawałem kubek w ręce Faraonowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Tedy mu powiedział Józef: Ten jest wykład snu tego: Trzy gałązki, trzy dni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Po trzech dniach wywyższy Farao głowę twą, a przywróci cię do pierwszego urzędu, i będziesz podawał kubek Faraonowi do ręki jego, według zwyczaju pierwszego, gdyś był podczaszym jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Tylko wspomnij sobie na mię, gdy się będziesz miał dobrze, i uczyń proszę ze mną miłosierdzie, abyś wzmiankę uczynił o mnie przed Faraonem, i wybawił mię z domu tego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Bo mię kradzieżą wzięto z ziemi Hebrajskiej, a do tego nicem tu nie uczynił, że mię wrzucono do tego więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'A widząc przełożony nad piekarzami, iż dobrze wyłożył, rzekł do Józefa: Jam też we śnie moim widział, a oto, trzy kosze białe nad głową moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'A w koszu najwyższym były wszelakie potrawy Faraonowe, roboty piekarskiej, a ptactwo jadło je z kosza, który był nad głową moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Tedy odpowiedział Józef, i rzekł: Tenci jest wykład jego: Trzy kosze, trzy dni są;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'A po trzech dniach odejmie Farao głowę twoję od ciebie, i obwiesi cię na drzewie, a będzie ptactwo jadło ciało twoje z ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'I stało się dnia trzeciego, dnia narodzenia Faraonowego, że uczynił ucztę na wszystkie sługi swe, i policzył głowę przełożonego nad podczaszymi, i głowę przełożonego na piekarzami w poczet sług swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'I przywrócił przełożonego nad podczaszymi do podczastwa, aby podawał kubek do rąk Faraonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'A przełożonego nad piekarzami obwiesił, jako im był sen wyłożył Józef.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Jednak nie wspomniał przełożony nad podczaszymi na Józefa, ale go zapomniał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'I stało się po wyjściu dwóch lat, że się śniło Faraonowi, jakoby stał nad rzeką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'A oto z rzeki wychodziło siedem krów, pięknych na wejrzeniu i tłustych na ciele, które się pasły na łące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Oto, też siedem krów innych wychodziło za niemi z rzeki, szpetnych na wejrzeniu, i chudych na ciele, które stały wedle krów pierwszych nad brzegiem rzeki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'I pożarły one krowy szpetne na wejrzeniu i chude na ciele, siedem krów pięknych na wejrzeniu i tłustych; zatem ocknął się Farao.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'A gdy usnął, śniło mu się po wtóre; a ono siedem kłosów wyrastało z jednego źdźbła, pełnych i cudnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Oto, też siedem kłosów cienkich i wysuszonych od wiatru wschodniego wyrastało za nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'I pożarły te kłosy cienkie, siedem onych kłosów pięknych i zupełnych; i ocknął się Farao.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'A toć był sen. A gdy było rano, strwożony był duch jego; i posławszy wezwał wszystkich wieszczków Egipskich, i wszystkich mędrców jego, i opowiedział im Farao sny swoje; a nie było, kto by je wyłożył Faraonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Zatem rzekł przełożony nad podczaszymi do Faraona, mówiąc: Grzechy moje ja dziś przypominam sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Farao rozgniewawszy się na sługi swe, dał mię był pod straż do domu hetmana żołnierzów, mnie i przełożonego nad piekarzami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Tam się nam śnił sen jednejże nocy, mnie i jemu; każdemu według wykładu snu jego śniło się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'A był tam z nami młodzieniec Hebrejczyk, sługa hetmana żołnierzów, któremuśmy powiedzieli, i wyłożył nam sny nasze, każdemu według snu jego wyłożył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'I stało się, że jako nam wyłożył, tak było; mię przywrócił król na miejsce moje, a onego obwiesił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Tedy posławszy Farao, wezwał Józefa, i prędko go wyprowadzono z więzienia; który ostrzygłszy się, i odmieniwszy szaty swoje przyszedł do Faraona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'I rzekł Farao do Józefa: Śnił mi się sen, a nie mam, kto by mi go wyłożył; alem ja o tobie słyszał, gdy mówiono, że gdy usłyszysz sen, umiesz go wyłożyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'I odpowiedział Józef Faraonowi, mówiąc: Oprócz mnie Bóg opowie rzeczy szczęśliwe Faraonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Tedy rzekł Farao do Józefa: Zdało mi się we śnie, jakobym stał na brzegu rzeki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'A oto z rzeki wychodziło siedem krów tłustych na ciele, i pięknych na wejrzeniu, a pasły się na łące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Oto, zaś wychodziło siedem krów innych za nimi, nędznych i szpetnych na wejrzeniu, i chudych na ciele; nie widziałem we wszystkiej ziemi Egipskiej tak szpetnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'I pożarły krowy chude i szpetne siedem krów pierwszych tłustych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'A choć się dostały do wnętrzności ich, przecię nie było znać, że się dostały do wnętrzności ich: bo na wejrzeniu były szpetne, jako i przedtem; i ocknąłem się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Widziałem zaś we śnie, a oto, siedem kłosów wyrastało z jednego źdźbła pełnych i pięknych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Oto, też siedem kłosów suchych, cienkich, i wyschłych od wiatru wschodniego, wyrastało za nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'I pożarły te kłosy cienkie siedem onych kłosów pięknych. I powiedziałem to wieszczkom; ale nie było, kto by mi wyłożył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Tedy rzekł Józef do Faraona: Sen Faraonów jedenże jest: co Bóg uczyni, oznajmił Faraonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Siedem krów pięknych jest siedem lat, a siedem kłosów cudnych, jest też siedem lat; sen to jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Siedem zaś krów chudych i szpetnych, które wychodziły za niemi, jest siedem lat, a siedem kłosów czczych, i wyschłych od wiatru wschodniego, będzie siedem lat głodnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'A toć jest, com powiedział Faraonowi; co Bóg będzie czynił, ukazał Faraonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Oto, siedem lat nadejdzie bardzo obfitych we wszystkiej ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'A po nich nastąpi siedem lat głodu, i w zapomnienie przyjdzie wszystka ona obfitość w ziemi Egipskiej, i wytrawi głód ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Tak, że nie będzie znać w ziemi obfitości onej dla głodu przyszłego: albowiem ciężki będzie bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'A iż się po dwa kroć śnił sen Faraonowi, znaczy, że to pewna rzecz od Boga, i pospiesza Bóg wykonać ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Przetoż teraz niech znajdzie Farao męża rozumnego i mądrego, a przełoży go nad ziemią Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Niech tak uczyni Farao, a postanowi urzędniki nad ziemią i zbierze piątą część urodzajów ziemi Egipskiej przez te siedem lat obfitych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'I niech zbierają wszelaką żywność lat dobrych następujących, i zgromadzają zboża pod rękę Faraonową, i żywność w mieściech niech chowają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'A będzie ona żywność na wychowanie ziemi na siedem lat głodu, które będą w ziemi Egipskiej aby nie niszczała ziemia od głodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'I podobało się to Faraonowi, i wszystkim sługom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'I rzekł Farao do sług swoich: Izaż znajdziemy podobnego mężowi temu, w którym by był Duch Boży?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Zatem rzekł Farao do Józefa: Ponieważ ci oznajmił Bóg to wszystko, nie masz żadnego tak rozumnego i mądrego jako ty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Ty będziesz nad domem moim, a według rozkazania ust twoich sprawować się będzie wszystek lud mój: tylko stolicą większy nad cię będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Nad to rzekł Farao do Józefa: Oto, postanowiłem cię nad wszystką ziemią Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Zdjął tedy Farao pierścień swój z ręki swej, i dał go na rękę Józefową; oblekł go też w szatę bisiorową, i włożył łańcuch złoty na szyję jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'I kazał go wozić na wtórym wozie swoim, a wołano przed nim: Kłaniajcie się. I przełożył go nad wszystką ziemią Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Zatem rzekł Farao do Józefa: Jam jest Farao, a bez twego pozwolenia nie podniesie żaden ani ręki, ani nogi swej, we wszystkiej ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'I nazwał Farao imię Józefowe, Safnat Paneach, a dał mu Asenatę, córkę Potyfara, przełożonego Ońskiego, za żonę. I wyjechał Józef na ziemię Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'A było Józefowi trzydzieści lat, gdy stanął przed Faraonem, królem Egipskim; i wyszedłszy Józef od oblicza Faraonowego, objechał wszystkę ziemię Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Zrodziła tedy ziemia w onych siedmiu latach urodzajnych obficie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'I zgromadził Józef wszystkę żywność onych siedmiu lat, która była w ziemi Egipskiej i składał żywność w mieściech; urodzaj polny każdego miasta, który był około niego, składał w niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Zaczem nagromadził Józef zboża, jako piasku morskiego bardzo wiele, aż go zaniechano liczyć; bo mu nie było liczby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'A Józefowi urodzili się dwaj synowie, pierwej niż przyszedł rok głodu, które mu urodziła Asenat, córka Potyfara, przełożonego Ońskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Nazwał tedy Józef imię pierworodnego Manases, mówiąc: Że mi dał Bóg zapomnieć wszelkiej pracy mojej, i wszystkiego domu ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'A imię drugiego nazwał Efraim, mówiąc: Iż mię rozmnożył Bóg w ziemi utrapienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Tedy się skończyło siedem lat obfitości, która była w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'I poczęło siedem lat głodu następować, jako był przepowiedział Józef. I był głód po wszystkich krainach: ale we wszystkiej ziemi Egipskiej był chleb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Jednak potem ściśniona była głodem wszystka ziemia Egipska, i wołał lud do Faraona, o chleb. I rzekł Farao wszystkim Egipczanom: Idźcie do Józefa, a co wam rzecze uczyńcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'I był głód po wszystkiej ziemi. Tedy otworzył Józef wszystkie gumna, w których było zboże, i sprzedawał Egipczanom; bo się był głód zmocnił w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'I ze wszystkiej ziemi przyjeżdżano do Egiptu, kupować żywność od Józefa; bo się był zmocnił głód po wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'A widząc Jakób, że było zboże w Egipcie, rzekł do synów swoich: Czemuż się oglądacie jeden na drugiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'I mówił im: Otom słyszał, że jest zboże w Egipcie. Jedźcież tam, a kupcie nam stamtąd, abyśmy żywi byli, a nie pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Jechało tedy dziesięć braci Józefowych kupować zboże, do Egiptu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Ale Benjamina, brata Józefowego nie posłał Jakób z bracią jego, bo mówił: By snać nie przypadło nań co złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'I szli synowie Izraelowi pospołu z innymi tamże idącymi kupować zboże; albowiem był głód w ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'A Józef był przedniejszym rządcą w onej ziemi; onże sprzedawał zboża wszystkiemu ludowi ziemi. A gdy przyszli bracia Józefowi, kłaniali mu się twarzą do ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'A ujrzawszy Józef bracią swą, poznał je; lecz stawił się im jako obcy, i mówił do nich surowo, i rzekł do nich: Skądeście przyszli? I odpowiedzieli: Z ziemi Chananejskiej, abyśmy nakupili żywności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Tedy poznał Józef bracią swą; ale go oni nie poznali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'I wspomniał Józef na sny, które mu się śniły o nich, i rzekł im: Szpiegowieście wy, a przyszliście, abyście przepatrzyli miejsca nieobronne tej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'A oni mu odpowiedzieli: Nie tak, panie mój; ale słudzy twoi przyszli, aby nakupili żywności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Wszyscyśmy synowie jednego męża; ludzieśmy szczerzy, a nie są słudzy twoi szpiegami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'A on rzekł do nich: Nie tak, aleście nieobronne miejsca tej ziemi przyszli przepatrować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'I rzekli: Dwanaście nas braci było sług twoich, synów jednego męża w ziemi Chananejskiej; a oto, najmłodszy z ojcem naszym teraz jest w domu, a jednego już nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'I rzekł im Józef: Toć jest com ja wam powiedział, mówiąc: Szpiegowieście wy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Przez to was doświadczę; żywie Farao, nie wynijdziecie stąd, aż mi tu przyjdzie brat wasz młodszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Poślijcież jednego z was, aby przywiódł brata waszego, a wy w więzieniu będziecie, ażby były doświadczone słowa wasze, jestli prawda przy was; a jeźli nie, żywie Farao, żeście wy szpiegowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Tedy je dał pod straż do trzech dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'I mówił do nich Józef dnia trzeciego: Uczyńcie tak, a żyć będziecie; boć się ja boję Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Jeźliście szczerzy, brat wasz jeden niech będzie okowany w więzieniu, gdzieście wy byli; a wy jedźcie i odnieście zboże, abyście odjęli głodowi domy wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'A brata waszego młodszego przywiedźcie do mnie, a sprawdzą się słowa wasze, i nie pomrzecie. I uczynili tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'I mówili jeden do drugiego: Zaprawdęśmy zgrzeszyli przeciwko bratu naszemu; bo widząc utrapienie duszy jego, gdy się nam modlił, nie wysłuchaliśmy go; dla tegoż przyszedł na nas ten kłopot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Odpowiedział im tedy Ruben, mówiąc: Izalim wam nie mówił temi słowy: Nie grzeszcie przeciw pacholęciu? a nie usłuchaliście; otóż teraz krwi jego z rąk naszych szukają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'A oni nie wiedzieli, żeby rozumiał Józef; bo tłumacz był między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Odwróciwszy się tedy od nich Józef, płakał; a obróciwszy się do nich, mówił z nimi, i wziąwszy od nich Symeona, związał go przed oczyma ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'I rozkazał Józef, aby napełniono wory ich zbożem, i wrócono pieniądze ich każdemu do woru jego, i żeby im dano żywności na drogę; i uczyniono tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Tedy oni włożywszy zboża swoje na osły swe, odjechali stamtąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'I rozwiązawszy jeden z nich wór swój, aby dał obrok osłowi swemu w gospodzie, ujrzał pieniądze swoje, które były na wierzchu w worze jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'I rzekł do braci swej: Wrócono mi pieniądze moje, a oto, są w worze moim. Tedy im upadło serce, i zdumieli się, jeden do drugiego mówiąc: Cóż nam to Bóg uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Zatem przyszli do Jakóba, ojca swego, do ziemi Chananejskiej, i powiedzieli mu wszystko, co się im przydało, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Mówił z nami on mąż, pan onej ziemi, surowo, i udał nas za szpiegi ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'A myśmy mu rzekli: Szczerzyśmy, nie byliśmy szpiegami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Dwanaście nas było braci synów ojca naszego; jednego już nie masz, a młodszy teraz jest z ojcem naszym w ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'I mówił do nas mąż on, pan onej ziemi: Po tem poznam, żeście szczerzy; brata waszego jednego zostawcie u mnie, a zboże dla odjęcia głodowi domów waszych weźmijcie a idźcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Potem przywiedźcie brata waszego młodszego do mnie, abym poznał, żeście wy nie szpiegowie, ale szczerzy; tedy wam wrócę brata waszego, a w tej ziemi handlować będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'I stało się, gdy wypróżniali wory swoje, a oto, każdy znalazł węzeł pieniędzy swych w worze swoim; a obaczywszy węzły z pieniędzmi swymi, oni i ojciec ich, polękali się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'I rzekł im Jakób, ojciec ich: Osierociliście mię, Józefa nie masz, i Symeona nie masz, a Benjamina weźmiecie; na mię się to wszystko złe zwaliło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'I rzekł Ruben do ojca swego, mówiąc: Dwóch synów moich zabij, jeźlić go zaś nie przywiodę; daj go do ręki mojej, a ja go tobie przywrócę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Ale on rzekł: Nie pójdzie syn mój z wami, gdyż brat jego umarł, a on sam tylko został; a jeźliby nań przypadło co złego na drodze, którą pójdziecie, tedy doprowadzicie sędziwość moję z żałością do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'A głód wielki był w onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'I stało się, gdy strawili onę żywność, którą byli przynieśli z Egiptu, że rzekł do nich ojciec ich: Idźcie znowu, a kupcie nam cokolwiek żywności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'I rzekł do niego Judas, mówiąc: Oświadczając oświadczył się przeciwko nam ten mąż mówiąc: Nie ujrzycie oblicza mojego, jeźli nie będzie brat wasz z wami:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Jeźli tedy poślesz brata naszego z nami, pojedziemy i nakupiemyć żywności;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Ale jeźli nie poślesz, nie pojedziemy; bo on mąż mówił do nas: Nie ujrzycie twarzy mojej, jeźli nie będzie brata waszego z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Tedy rzekł Izrael: Przeczżeście mi tak źle uczynili, powiedziawszy temu mężowi, że jeszcze macie brata?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'I rzekli: Pilnie się pytał on mąż o nas, i o rodzinie naszej, mówiąc: Żywże jeszcze ojciec wasz? macieli jeszcze którego brata? I odpowiedzieliśmy mu według pytania jego; cóżeśmy wiedzieli, że miał mówić: Przywiedźcie mi tu brata waszego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'I rzekł Judas do Izraela, ojca swego: Poślij tego młodzieńca ze mną, a wstawszy pojedziemy, abyśmy żyli a nie pomarli głodem, tak my, jako i ty, i dziateczki nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ja przyrzekam zań, z ręki mojej szukaj go; jeźli go nie przywiodę do ciebie, a nie stawię go przed tobą, będęć winien grzechu po wszystkie dni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Bo gdybyśmy byli nie omieszkali, już byśmy się byli dwa kroć wrócili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Tedy rzekł do nich Izrael, ojciec ich: Jeźliże tak być musi, uczyńcież to; nabierzcie najlepszych pożytków ziemi w naczynia wasze, a zanieście mężowi onemu w upominku: trochę balsamu, i trochę miodu, i rzeczy wonnych, i myrry, orzechów terebintowych, i migdałów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Pieniądze też dwoje weźmijcie do rąk waszych, a pieniądze przywrócone na wierzchu worów waszych odnieście w ręce swoje; snać się to omyłką stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Ale i brata waszego weźmijcie, a wstawszy jedźcie znowu do męża onego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'A Bóg Wszechmogący niech wam da miłosierdzie przed obliczem tego męża, aby wam wypuścił brata waszego drugiego i Benjamina; a ja jako osierociały bez dziatek będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Tedy wziąwszy oni mężowie on podarek, i dwoje pieniądze wziąwszy w ręce swe, i Benjamina, wstali, i jechali do Egiptu, i stanęli przed Józefem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'A ujrzawszy Józef z nimi Benjamina, rzekł do tego, który był sprawcą domu jego: Wprowadź te męże w dom, a zabij bydlę i nagotuj; bo ze mną jeść będą mężowie ci w południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'I uczynił on mąż, jako mu rozkazał Józef, a wprowadził on mąż one ludzie w dom Józefów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Bali się tedy mężowie oni, gdy byli wprowadzeni w dom Józefów, i mówili: Dla onychci to pieniędzy, które pierwej włożono było do worów naszych, wprowadzeni tu jesteśmy, aby potwarz na nas zwaliwszy targnął się na nas, a pobrał w niewolą nas i osły nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'A przystąpiwszy do męża tego, który był sprawcą domu Józefowego, mówili do niego we drzwiach domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'I rzekli: Słuchaj mię, panie mój! przyjechaliśmy byli pierwej kupować żywność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'I stało się, gdyśmy przyjechali do gospody, i rozwiązaliśmy wory nasze, oto, pieniądze każdego były na wierzchu woru jego, pieniądze nasze, według wagi ich, któreśmy zaś przynieśli w rękach naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Pieniądze też drugie przynieśliśmy w rękach naszych, abyśmy nakupili żywności, a nie wiemy, kto włożył te pieniądze nasze do worów naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'A on rzekł: Pokój wam, nie bójcie się; Bóg wasz, i Bóg ojca waszego dał wam skarb do worów waszych; pieniądze wasze doszły mię. I wywiódł do nich Symeona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'A przywiódłszy on mąż one ludzie w dom Józefów, dał im wody, i umyli nogi swe; dał też obrok osłom ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Zatem nagotowali podarek, niż przyszedł Józef w południe; słyszeli bowiem, iż tam mieli jeść chleb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'A gdy wszedł Józef w dom, przynieśli mu podarek, który mieli w rękach swych w domu onym, i kłaniali mu się aż do ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'I pytał ich, jakoby się mieli, i rzekł: Zdrówże jest ojciec wasz stary, o którymeście mi powiadali? Żywże jeszcze?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'A oni odpowiedzieli: Zdrówci sługa twój, ojciec nasz, jeszczeć żyw. A schyliwszy się, pokłonili mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Tedy podniósłszy oczy swe, ujrzał Benjamina, brata swego, syna matki swej, i rzekł: Tenże jest brat wasz młodszy, o którymeście mi powiadali? I rzekł mu: Bóg niech ci będzie miłościw, miły synu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'I pokwapił się Józef wynijść, bo się były wzruszyły wnętrzności jego ku bratu swemu, i szukał miejsca, gdzie by płakał, i wszedłszy do komory, płakał tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Potem umywszy twarz swoję, wyszedł zasię, i wstrzymał się, i rzekł: Kładźcie chleb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'I położono jemu osobno, i onym osobno, Egipczanom też, którzy jedli z nim, osobno; bo nie mogą jeść Egipczanie z Hebrejczykami chleba, gdyż to jest obrzydliwością Egipczanom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'I usiedli przed obliczem jego, pierworodny według pierworodztwa swego, a młodszy według młodości swej; i dziwowali się mężowie oni patrząc jeden na drugiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'I biorąc potrawy przed sobą dawał im; a dostała się pięć kroć większa część Benjaminowi nad inne części onych wszystkich; i pili, a podpili sobie z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Rozkazał tedy Józef temu, który był sprawcą domu jego, mówiąc: Napełnij wory mężów tych zbożem, jako mogą znieść, a włóż pieniądze każdego na wierzch woru jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Kubek też mój, kubek srebrny, włóż na wierzch woru młodszego z pieniędzmi za zboże jego; i uczynił według słów Józefowych, jako mu rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'A gdy było rano, mężowie oni puszczeni są, sami i osłowie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Wyszedłszy tedy z miasta, gdy nie daleko byli, rzekł Józef do tego, który był sprawcą domu jego: Wstań, goń te męże, a dogoniwszy ich, mów do nich: Czemuście oddali złe za dobre?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Azaż nie ten jest kubek, z którego pija pan mój? i azaż on pewnie nie zgadnie przezeń, jacyście wy? źleście uczynili, coście uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Dogoniwszy ich tedy, mówił do nich te słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Ale oni odpowiedzieli mu: Czemu mówi pan mój takowe słowa? nie daj tego Boże, aby to słudzy twoi uczynić mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Oto pieniądze, któreśmy byli znaleźli na wierzchu worów naszych, odnieśliśmy zaś do ciebie z ziemi Chananejskiej; a jakoż byśmy kraść mieli z domu pana twego srebro albo złoto?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'U którego by to znaleziono z sług twoich, niechaj umrze; a my będziemy pana mego niewolnikami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Tedy on rzekł: Niechże tak będzie, jako mówicie; jednak przy którym się znajdzie kubek, ten niech będzie niewolnikiem, a wy będziecie niewinnymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Prędko tedy każdy złożył wór swój na ziemię; i rozwiązali każdy wór swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'I szukał od starszego począwszy; a u młodszego przestał; i znalazł kubek w worze Benjaminowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Tedy oni rozdarli szaty swoje, i włożywszy brzemię każdy z nich na osła swego, wrócili się do miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Przyszedł tedy Judas, i bracia jego do domu Józefa, który tam jeszcze był, i upadli przed obliczem jego na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'I rzekł do nich Józef: Cóżeście to uczynili? azaście nie wiedzieli, że pewnie zgadnie mąż taki, jakim ja jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Tedy odpowiedział Judas: Cóż odpowiemy panu memu, cóż rzeczemy? i jako się my usprawiedliwić mamy? Bóg znalazł nieprawość sług twoich; otośmy niewolnikami pana mego, i my, i ten, w którego ręku znaleziony jest kubek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'A on rzekł: Nie daj Boże, abym to uczynić miał! mąż, w którego ręku znaleziony jest kubek, ten będzie niewolnikiem moim; a wy jedźcie w pokoju do ojca waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Zatem przystąpił do niego Judas i rzekł: Słuchaj mię panie mój; niechaj przemówi proszę sługa twój które słowo w uszy pana mego, a niech się nie zapala gniew twój na sługę twego, gdyżeś ty jest jako sam Farao.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Pan mój pytał sług swoich mówiąc: Macież ojca albo brata?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Tedyśmy odpowiedzieli panu swemu: Mamyć ojca starego, i chłopię w starości jego spłodzone małe, a brat jego umarł, a został sam tylko po matce swej, i ojciec jego miłuje go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Potem mówiłeś do nas sług swoich: Przywiedźcie go do mnie, abym go oglądał oczyma memi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'I mówiliśmy do pana mego: Nie będzie mogło chłopię opuścić ojca swego; bo gdyby opuściło ojca swego, umarłby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Tedyś rzekł do sług swoich: Jeźli nie przyjdzie brat wasz młodszy z wami, nie ujrzycie więcej oblicza mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'I stało się, gdyśmy odeszli do sługi twego, ojca mojego, i powiedzieliśmy mu te słowa pana mego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Tedy rzekł ojciec nasz: Jedźcie znowu, a kupcie nam trochę żywności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'I powiedzieliśmy: Nie możemy tam iść: lecz jeźli brat nasz młodszy będzie z nami, tedy pojedziemy; bo inaczej nie będziemy mogli oglądać oblicza męża onego, jeźli brat nasz młodszy nie będzie z nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'I rzekł sługa twój, ojciec mój, do nas: Wy wiecie, że dwóch synów urodziła mi żona moja;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'I wyszedł jeden ode mnie, i rzekłem: Zaiste od zwierza rozdarty jest, i nie widziałem go do tych miast;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'A weźmiecieli i tego od oblicza mego, a przypadnie nań śmierć, tedy doprowadzicie sędziwość moję z żałością do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Przetoż teraz jeślibym przyszedł do sługi twego, ojca mojego, a dziecięcia by z nami nie było, (ponieważ dusza jego jest przywiązana do duszy jego),');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'Stanie się, skoro ujrzy, iż dziecięcia nie będzie, że umrze; a odprowadzą słudzy twoi sędziwość sługi twego, ojca naszego, z żałością do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Bo sługa twój przyrzekł za to dziecię, gdy je brał od ojca swego, mówiąc: Jeźlić go zaś nie przywiodę, tedy będę winien grzechu przeciw ojcu memu po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Teraz tedy niech zostanie proszę sługa twój miasto dziecięcia tego niewolnikiem pana mego, a dziecię niech idzie z bracią swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Bo jakoż ja mam wrócić się do ojca mego, gdy tego dziecięcia ze mną nie będzie? chybabym chciał patrzyć na żałość, która by przyszła na ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Tedy się Józef nie mógł dalej wstrzymać przed wszystkimi, którzy stali przed nim, i zawołał: Wyprowadźcie wszystkie ode mnie. I nie został nikt przy nim, gdy się dał poznać Józef braci swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'I podniósł głos swój z płaczem; co słyszeli Egipczanie, słyszał też dom Faraonów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'I rzekł Józef do braci swej: Jamci jest Józef; a żywże jeszcze ojciec mój? i nie mogli mu bracia jego odpowiedzieć, bo się zlękli oblicza jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Tedy rzekł Józef do braci swej: Przystąpcie, proszę, do mnie; i przystąpili. Zatem rzekł: Jam jest Józef, brat wasz, któregoście sprzedali do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Jednak teraz nie frasujcie się, ani trwożcie sobą, żeście mię tu sprzedali; boć dla zachowania żywota waszego posłał mię Bóg przed wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Bo już dwa lata głodu było na ziemi, a jeszcze pięć lat zostaje, których nie będą orać ani żąć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Posłał mię tedy Bóg przed wami, abym was zachował ostatek na ziemi, a żebym wam dodał żywności na oswobodzenie wielkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Teraz tedy nie wyście mię tu posłali, ale Bóg, który mię postanowił ojcem Faraonowym, i panem wszystkiego domu jego, a panującym nad wszystką ziemią Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Spieszcież się, a idźcie do ojca mego, i mówcie do niego: Toć wskazuje syn twój Józef: Uczynił mię Bóg panem wszystkiego Egiptu, przyjedźże do mnie, a nie omieszkaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'I będziesz mieszkał w ziemi Gosen; a będziesz blisko mnie, ty i synowie twoi, i synowie synów twoich, i trzody twoje, i woły twoje, i wszystko, co masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'A będę cię tam żywił; bo jeszcze pięć lat głodu będzie, abyś od niedostatku nie zginął, ty, i dom twój, i wszystko, co masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'A oto, oczy wasze widzą, i oczy brata mego, Benjamina, że usta moje mówią do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Oznajmijcie też ojcu memu wszystkę zacność moje w Egipcie, i wszystko coście widzieli; spieszcie się tedy, a przyprowadźcie tu ojca mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Zatem padł na szyję Benjamina, brata swego, i płakał; Benjamin też płakał na szyi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'I pocałowawszy wszystkę bracią swoję, płakał nad nimi; a potem rozmawiali z nim bracia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'I rozgłoszono tę wieść w domu Faraonowym, mówiąc: Przyjechali bracia Józefowi; i podobało się to w oczach Faraonowych, i w oczach sług jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Tedy rzekł Farao do Józefa: Powiedz braci swej: Uczyńcie tak: nakładłszy brzemion na bydła wasze, idźcie; a wróćcie się do ziemi Chananejskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'A wziąwszy ojca waszego, i czeladź waszę, przyjedźcie do mnie; i dam wam dobre miejsce w ziemi Egipskiej, i będziecie używać tłustości ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'I rozkaż im mówiąc: To uczyńcie: weźmijcie sobie z ziemi Egipskiej wozów, dla dziatek waszych i dla żon waszych, a wziąwszy ojca waszego przyjedźcie tu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'A oko wasze niech nie żałuje sprzętu waszego, gdyż dobro wszystkiej ziemi Egipskiej wasze będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Uczynili tedy tak synowie Izraelowi; i dał im Józef wozy według rozkazania Faraonowego; dał im też żywności na drogę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Dał z onychże wszystkich każdemu odmienne szaty; ale Benjaminowi dał trzy sta srebrników, i pięcioro szat odmiennych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Ojcu też swemu posłał te rzeczy: dziesięć osłów, niosących z najlepszych rzeczy Egipskich, i dziesięć oślic, niosących zboże, i chleb, i żywność ojcu jego na drogę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Puścił tedy bracią swą, i odjechali, a mówił do nich: Nie wadźcie się na drodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Którzy wyjechawszy z Egiptu przyjechali do ziemi Chananejskiej, do Jakóba ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'I oznajmili mu, mówiąc: Jeszczeć żyw Józef, a onci jest panem nad wszystką ziemią Egipską; i zemdlało serce jego; bo im nie wierzył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Lecz oni powiedzieli mu wszystkie słowa Józefowe, które mówił do nich. A ujrzawszy wozy, które posłał Józef, aby go na nich przywieziono, tedy ożył duch Jakóba, ojca ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'I rzekł Izrael: Dosyć mam na tem, gdy jeszcze Józef, syn mój, żyje; pójdę a oglądam go, pierwej niż umrę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'A tak jechał Izrael ze wszystkiem, co miał, a przyjechawszy do Beerseby, ofiarował ofiary Bogu ojca swego Izaaka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'I rzekł Bóg do Izraela w widzeniu nocnem, mówiąc: Jakóbie, Jakóbie; a on odpowiedział: Owom ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'I rzekł: Jam jest Bóg, Bóg ojca twojego; nie bój się zstąpić do Egiptu, bo cię tam w naród wielki rozmnożę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ja zstąpię z tobą do Egiptu, i Ja cię stamtąd także zasię wywiodę, a Józef położy rękę swoję na oczy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'I powstał Jakób z Beerseby; i wzięli synowie Izraelowi Jakóba ojca swego, i dziatki swe, i żony swe na wozy, które był posłał Farao, aby go przywieziono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Pobrali też bydła swe, i majętność swoję, której byli nabyli w ziemi Chananejskiej, i przyjechali do Egiptu, Jakób i wszystka rodzina jego z nim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Syny swe, i syny synów swych, córki swe i córki synów swych, i wszystko nasienie swoje prowadził z sobą do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'A teć są imiona synów Izraelowych, którzy weszli do Egiptu: Jakób i synowie jego: pierworodny Jakóbów Ruben.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'A synowie Rubenowi: Henoch, i Fallu, i Hesron i Charmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'A synowie Symeonowi: Jemuel, i Jamyn, i Achod, i Jachyn, i Sochar, i Saul, syn niewiasty Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Synowie też Lewiego: Gerson, Kaat, i Merary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'A synowie Judasowi: Her, i Onan, i Sela, i Fares, i Zara; ale umarł Her i Onan w ziemi Chananejskiej. A byli synowie Faresowi: Hesron i Hamuel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'A synowie Isaszarowi: Tola, i Fua, i Job, i Simron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Synowie zaś Zabulonowi: Zared, i Elon, i Jaleel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'A cić są synowie Lii, które urodziła Jakóbowi w Padanie Syryjskim, i Dyna córka jego; wszystkich dusz synów jego, i córek jego, trzydzieści i trzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'A synowie Gadowi: Sefon, i Aggi, Suny, i Esebon, Ery, i Arody, i Areli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'A synowie Aser: Jemna, i Jesua, i Isui, i Beryja, i Sera, siostra ich. A synowie Beryjego: Heber, i Melchyjel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Cić są synowie Zelfy, którą był dał Laban Lii, córce swej, których ona urodziła Jakóbowi, szesnaście dusz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Synowie Racheli, żony Jakóbowej: Józef i Benjamin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Józefowi zaś urodzili się synowie w ziemi Egipskiej, które mu urodziła Asenat, córka Potyfara, książęcia Ońskiego: Manases i Efraim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'A synowie Benjaminowi: Bela, i Bechor, i Asbel, Gera, i Naamann, Echy i Ros, Mupim, i Chupim, i Ared.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Cić są synowie Racheli, którzy się urodzili Jakóbowi; wszystkich dusz czternaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'A synowie Danowi: Chusym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Synowie też Neftalimowi: Jachsyjel, i Gunny, i Jeser, i Selem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Ci są synowie Bali, którą był dał Laban Racheli, córce swej, która je urodziła Jakóbowi; wszystkich dusz siedem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Wszystkie dusze, które przyszły z Jakóbem do Egiptu, co wyszły z biódr jego, okrom żon synów Jakóbowych, wszystkich dusz było sześćdziesiąt i sześć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'A synów Józefowych, którzy mu się urodzili w Egipcie, dusz dwie. A tak wszystkich dusz domu Jakóbowego, które weszły do Egiptu, było siedemdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'I posłał przed sobą Judasa do Józefa, aby mu oznajmił pierwej, niżby przyjechał do Gosen. I przyjechali do ziemi Gosen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'A zaprzągłszy Józef wóz swój, wyjechał przeciw Izraelowi, ojcu swemu, do Gosen; a ujrzawszy go (Jakób) padł na szyję jego, i płakał na szyi jego chwilę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Tedy rzekł Izrael do Józefa: Niechże już umrę, gdym ujrzał oblicze twoje, ponieważeś ty jeszcze żyw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Zatem rzekł Józef do braci swej i do domu ojca swego: Pojadę, a opowiem Faraonowi, i rzekę mu: Bracia moi i dom ojca mego, którzy byli w ziemi Chananejskiej, przyjechali do mnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'A ci mężowie są pasterze trzód, bo się bawili chowaniem bydła; przeto owce swoje, i woły swoje, i wszystko, co mieli, przywiedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'A tak gdy was przyzowie Farao, i spyta: Czem się bawicie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Odpowiecie: Pasterze byli słudzy twoi od dzieciństwa naszego aż dotąd, i my i ojcowie nasi; a to dla tego abyście mogli mieszkać w ziemi Gosen, bo obrzydłością Egipczanom jest wszelki pasterz bydła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Tedy przyjechawszy Józef, oznajmił Faraonowi, i rzekł: Ojciec mój i bracia moi z owcami swemi, i z wołami swymi, i ze wszystkiem, co mają, przyjechali z ziemi Chananejskiej; a oto, są w ziemi Gosen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'A z liczby braci swej wziął pięciu mężów, i postawił je przed Faraonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'I rzekł Farao do braci jego: Czem się bawicie? A oni odpowiedzieli Faraonowi: Pasterzami owiec są słudzy twoi, i my i ojcowie nasi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Rzekli jeszcze do Faraona: Abyśmy byli przychodniami w tej ziemi, przyszliśmy; bo nie masz paszy dla bydła, które mają słudzy twoi, gdyż ciężki głód jest w ziemi Chananejskiej; a teraz niech mieszkają, prosimy, słudzy twoi w ziemi Gosen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Tedy rzekł Farao do Józefa mówiąc: Ojciec twój i bracia twoi przyjechali do ciebie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Ziemia Egipska przed tobą jest: w najlepszem miejscu tej ziemi daj mieszkanie ojcu twemu i braci twojej, niech mieszkają w ziemi Gosen; a zrozumieszli, że są między nimi mężowie godni, tedy je uczynisz przełożonymi nad trzodami memi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'I przywiódł Józef Jakóba, ojca swego, i postawił go przed Faraonem; a błogosławił Jakób Faraonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Tedy rzekł Farao do Jakóba: Wiele jest dni lat żywota twego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'I odpowiedział Jakób Faraonowi: Dni lat pielgrzymstwa mego jest sto i trzydzieści lat; krótkie i złe były dni lat żywota mego, i nie doszły dni lat żywota ojców moich, w których dniach oni pielgrzymowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Zatem pobłogosławiwszy Jakób Faraonowi, wyszedł od oblicza Faraonowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Tedy dał mieszkanie Józef ojcu swemu i braci swej, i dał im osiadłość w ziemi Egipskiej, w najlepszem miejscu onej krainy, w ziemi Rameses, jako był rozkazał Farao.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'I żywił Józef ojca swego i bracią swoję, i wszystek dom ojca swego chlebem aż do najmniejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'A chleba nie było po wszystkiej ziemi; bo ciężki bardzo był głód, i utrapiona była ziemia Egipska, i ziemia Chananejska od głodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Tedy zebrał Józef wszystkie pieniądze, które się znajdowały w ziemi Egipskiej i w ziemi Chananejskiej, za żywność, którą kupowano; i wniósł one pieniądze Józef do skarbu Faraonowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'A gdy nie stało pieniędzy w ziemi Egipskiej, i w ziemi Chananejskiej, tedy przyszli wszyscy Egipczanie do Józefa, mówiąc: Daj nam chleba, i czemuż mamy umierać przed tobą, gdyż nam już nie staje pieniędzy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Na to odpowiedział Józef: Dawajcie bydła wasze, a dam wam żywności za bydła wasze, ponieważ wam nie stało pieniędzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'I przygnali bydła swe do Józefa; i dał im Józef chleba za konie, i za stada owiec, i za stada wołów, i za osły, i przechował je chlebem za wszystkie bydła ich, onego roku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'A gdy wyszedł rok on, przyszli do niego roku drugiego, mówiąc mu: Nie zatajemy przed panem naszym, że nam już pieniędzy nie stało, i stada bydeł są u pana naszego; nie zostawa nam przed panem naszym, tylko ciała nasze i role nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'A czemuż umierać mamy przed oczyma twemi? i nas, i role nasze kupuj i ziemię naszę za chleb, a będziemy, my i ziemia nasza, w niewoli u Faraona; tylko nam daj nasienia, abyśmy żyli a nie pomarli, i ziemia nie spustoszała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'A tak kupił Józef wszystkę ziemię Egipską Faraonowi; bo sprzedali Egipczanie, każdy rolą swoję, gdyż się był wzmógł między nimi głód; i dostała się Faraonowi wszystka ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'I przeniósł lud do miast, od ostatnich granic Egiptu aż do końca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Tylko ziemi kapłańskiej nie kupił; bo kapłani mieli obrok postanowiony od Faraona, i żywili się obrokiem swym, który im dał Farao; dlategoż nie sprzedawali ziemi swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'I rzekł Józef do ludu: Otom was teraz poskupował i ziemię waszę Faraonowi; otóż macie nasienie, posiejcież tedy role.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'A z urodzajów waszych będziecie dawali piątą część Faraonowi; cztery zasię części będą wam na zasianie roli, i na żywność waszę i tych, którzy są w domach waszych, i na żywność dziatek waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Tedy odpowiedzieli: Zachowałeś żywot nasz; niechże znajdziemy łaskę w oczach pana swego, i będziemy niewolnikami Faraonowymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'I postanowił to Józef za prawo aż do dnia dzisiejszego w ziemi Egipskiej, aby dawana była Faraonowi piąta część; tylko ziemia samych kapłanów nie dostała się Faraonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'I mieszkał Izrael w ziemi Egipskiej, w ziemi Gosen, i osadziwszy się w niej, rozrodzili się, i rozmnożyli się wielce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'I żył Jakób w ziemi Egipskiej siedemnaście lat; a było dni Jakóbowych, lat żywota jego, sto czterdzieści i siedem lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'I przybliżyły się dni Izraelowe, aby umarł; i wezwał syna swego Józefa i rzekł do niego: Jeźlim teraz znalazł łaskę w oczach twoich, połóż proszę rękę twoję pod biodro moje, a uczyń ze mną miłosierdzie i prawdę; proszę nie chowaj mię w Egipcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Ale gdy zasnę z ojcy moimi, wyniesiesz mię z Egiptu, a pochowasz mię w grobie ich. A on rzekł: Uczynię według słowa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'A Jakób rzekł: Przysiążże mi: i przysiągł mu. Zatem nakłonił się Izrael ku głowom łoża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'To gdy się stało, dano znać Józefowi: Oto, ojciec twój zachorzał; który wziąwszy dwóch synów swoich z sobą, Manasesa i Efraima, jechał do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'I powiedziano Jakóbowi, mówiąc: Oto, syn twój Józef idzie do ciebie. A Izrael pokrzepiwszy się, usiadł na łożu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'I rzekł Jakób do Józefa: Bóg wszechmogący ukazał mi się w Luzie, w ziemi Chananejskiej, i błogosławił mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'A mówił do mnie: Oto, ja rozrodzę cię, i rozmnożę cię, i wywiodę z ciebie wielki naród; a dam ziemię tę nasieniu twemu po tobie w dziedzictwo wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Przetoż teraz dwaj synowie twoi, którzyć się urodzili w ziemi Egipskiej, pierwej niżem ja tu do ciebie przyszedł do Egiptu, moi są, Efraim i Manases; jako Ruben i Symeon moi będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Ale dzieci twoje, które po tych spłodzisz, twoje będą; imieniem braci swojej będą zwani w osiadłościach swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'A gdym się wracał z Padan, umarła mi Rachel w ziemi Chananejskiej w drodze, gdym jeszcze był jakoby na milę od Efraty, i pogrzebłem ją tam przy drodze ku Efracie; a toć jest Betlehem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'A ujrzawszy Izrael syny Józefowe, rzekł: Czyi to są?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Tedy odpowiedział Józef ojcu swemu: Synowie to moi, które mi tu dał Bóg; a on rzekł: Przywiedź je proszę do mnie, abym im błogosławił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'A oczy Izraelowe ociężały były dla starości, i nie mógł dojrzeć: i przywiódł je do niego, które Jakób pocałował i obłapił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Zatem rzekł Izrael do Józefa: Oglądać więcej oblicza twego nie spodziewałem się, a oto, dał mi Bóg widzieć i nasienie twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Tedy Józef odwiódł je od łona jego, i pokłonił się obliczem swem aż do ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'A wziąwszy Józef obydwu, postawił Efraima po prawej ręce swojej, a po lewej Izraelowej; a Manasesa po lewej ręce swojej a po prawej Izraelowej, i przywiódł je do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'A wyciągnąwszy Izrael prawicę swoję, włożył ją na głowę Efraima, który był młodszy, lewicę zaś swoję na głowę Manasesa, umyślnie przełożywszy ręce swoje, choć Mananses był pierworodny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'I błogosławił Józefowi, mówią: Bóg, przed którego obliczem chodzili ojcowie moi, Abraham i Izaak, Bóg który mię żywił od młodości mojej aż do dnia tego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Anioł, który mię wyrwał ze wszystkiego złego, niech błogosławi dzieciom tym, a niech będą nazywani od imienia mego, i od imienia ojców moich, Abrahama i Izaaka, a jako ryby niech się rozmnożą na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'A obaczywszy Józef, iż włożył ojciec jego rękę prawą swoję na głowę Efraimowę, nie miło mu było; i ujął rękę ojca swego, aby ją przeniósł z głowy Efraimowej na głowę Manasesowę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'I rzekł Józef do ojca swego: Nie tak, ojcze mój; albowiem ten jest pierworodny, włóżże prawicę swoję na głowę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Ale się zbraniał ojciec jego, i rzekł: Wiemci synu miły, wiem; i tenci się stanie w lud wielki, tenci też urośnie; a wszakże brat jego młodszy urośnie nadeń, a z nasienia jego wyjdzie mnóstwo narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Błogosławił im tedy dnia onego, mówiąc: Przez cię będzie błogosławił Izrael, mówiąc: Niech cię wystawi Bóg jako Efraima, i jako Manasesa; a tak przełożył Efraima nad Manasesa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Potem rzekł Izrael do Józefa: Oto, ja umieram, a Bóg będzie z wami, i przywróci was do ziemi ojców waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Oto, ja dawam ci część jednę mimo bracią twoję, którejm nabył z ręki Amorejczyków mieczem moim, i łukiem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Wezwał tedy Jakób synów swoich i rzekł: Zbierzcie się, a oznajmię wam, co ma przyjść na was w ostatnie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Zbierzcie się, i słuchajcie synowie Jakóbowi, a słuchajcie Izraela, ojca waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben pierworodny mój, tyś moc moja, i początek siły mojej, zacny dostojeństwem, i zacny męstwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Spłyniesz jako woda: nie będziesz zacnym, boś wstąpił na łoże ojca twego, i splugawiłeś łoże moje, i zginęło dostojeństwo twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Symeon i Lewi, bracia, naczynia nieprawości miecze ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'W radę ich niechaj nie wchodzi dusza moja, a z zgromadzeniem ich niech się nie jednoczy sława moja; bo w zapalczywości swej zabili męża, a w swej woli wywrócili mur.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Przeklęta zapalczywość ich, iż uporna, i gniew ich, iż zatwardziały. Rozdzielę je w Jakóbie, a rozproszę je w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, tyś jest, ciebie chwalić będą bracia twoi; ręka twoja będzie na szyi nieprzyjaciół twoich; kłaniać się tobie będą synowie ojca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Szczenię lwie Juda, od łupu, synu mój, wróciłeś się; skłonił się i położył się jako lew, i jako lwica, a któż go obudzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Nie będzie odjęte sceptrum od Judy, ani Zakonodawca od nóg jego, aż przyjdzie Szylo, i jemu będzie oddane posłuszeństwo narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Uwiąże u winnej macicy oślę swe, a u wybornej macicy winnej oślątko oślicy swej; omyje w winie szatę swoję, a we krwi jagód winnych odzienie swoje');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Czerwieńsze oczy jego nad wino, a bielsze zęby jego nad mleko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zabulon na brzegu morskim mieszkać będzie, i przy porcie okrętów, a granice jego aż do Sydonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isaszar jako osieł kościsty, leżący między dwoma brzemiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Upatrzył pokój, że jest dobry, i ziemię, że piękna, nachylił ramię swe ku noszeniu, dla tegoż będzie hołd dawał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan sądzić będzie lud swój, jako jedno z pokoleń Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan będzie wężem na drodze, żmiją na ścieżce, kąsając pięty końskie, że spadnie nazad jeździec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Zbawienia twego oczekiwam, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad od wojska zwyciężony będzie; ale i on potem zwycięży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Z Asera tłusty chleb jego, a on wyda rozkoszy królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Neftali jako łani wypuszczona, mówiąc piękne słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Latorośl płodna Józef, latorośl wyrastająca nad źródłem, a latorośli jego rozchodzą się po murze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Acz gorzkością napełnili go, i strzelali nań, a nienawidzili go strzelcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Jednak został potężny łuk jego, a zmocniły się ramiona rąk jego, w rękach mocnego Boga Jakóbowego, stąd się stał pasterzem i opoką Izraelową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Od Boga ojca twego, który cię wspomógł, i od Wszechmogącego, któryć błogosławił błogosławieństwy niebieskiemi z wysoka, i błogosławieństwy przepaści leżącej głęboko, i błogosławieństwy piersi i żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Błogosławieństwa ojca twego mocniejsze będą nad błogosławieństwa przodków moich, aż do granic pagórków wiecznych; będą nad głową Józefową, i nad wierzchem głowy odłączonego między bracią swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin jako wilk porywający, rano jeść będzie łup, a wieczór będzie dzielił korzyść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Teć wszystkie są dwanaście pokolenia Izraelskie, i to, co im powiedział ojciec ich, i błogosławił im; każdemu według błogosławieństwa jego błogosławił im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'A rozkazał im, i rzekł do nich: Ja będę przyłączon do ludu mego; pogrzebcież mię z ojcy moimi w jaskini, która jest na polu Efrona Hetejczyka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'W jaskini, która jest na polu Machpela, która jest na przeciwko Mamre w ziemi Chananejskiej, którą kupił Abraham z rolą od Efrona Hetejczyka, w osiadłość grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Tam pogrzebiono Abrahama, i Sarę, żonę jego; tam pogrzebiono Izaaka, i Rebekę żonę jego; tamem też pogrzebał Liję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'A kupiono tę rolą i jaskinią, która na niej, od synów Hetowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Tedy przestawszy Jakób mówić do synów swoich, złożył nogi swe na łoże i umarł, i przyłączon jest do ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Zatem upadł Józef na twarz ojca swego, i płakał nad nim, a całował go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'I rozkazał Józef sługom swym lekarzom, aby wonnemi maściami namazali ojca jego; i namazali wonnemi maściami lekarze Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'A gdy się mazania jego wypełniło czterdzieści dni, (bo się tak wypełniają dni tych, którzy wonnemi maściami mazani bywają), tedy go płakali Egipczanie przez siedemdziesiąt dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'A po wyjściu dni żałoby jego rzekł Józef do sług Faraonowych, mówiąc: Jeźlim teraz znalazł łaskę w oczach waszych, powiedzcie proszę Faraonowi, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Ojciec mój poprzysiągł mię mówiąc: Oto, ja umieram; w grobie moim, którym sobie wykopał w ziemi Chananejskiej, tam mię pogrzebiesz; a teraz niech jadę, proszę, i pogrzebię ojca mego, i zaś się wrócę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Tedy rzekł Farao: Jedź a pogrzeb ojca twego, jako cię poprzysiągł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Jechał tedy Józef, aby pogrzebał ojca swego; jechali też z nim wszyscy słudzy Faraonowi, także starsi domu jego, i wszyscy starsi ziemi Egipskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'I wszystek dom Józefów, i bracia jego, i dom ojca jego; tylko dziatki swoje, i owce swoje, i woły swoje zostawili w ziemi Gosen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Szły też z nimi i wozy, i jezdni; a był poczet bardzo wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'I przyjechali aż na pole Atad, które jest przy brodzie Jordańskim, i płakali tam płaczem wielkim i bardzo ciężkim; i obchodził Józef po ojcu swym żałobę przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'A ujrzawszy obywatele ziemi Chananejskiej żałobę onę na polu Atad, mówili: Żałoba to ciężka Egipczanów; przetoż nazwano imię miejsca onego Abel Micraim, które jest przy brodzie Jordańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Uczynili tedy z nim synowie jego, jak im był rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'I zawieźli go synowie jego do ziemi Chananejskiej, i pogrzebli go w jaskini na polu Machpela, którą Abraham był kupił z rolą na osiadłość grobu, od Efrona Hetejczyka, przeciwko Mamre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Zatem się wrócił Józef do Egiptu z bracią swą, i ze wszystkimi, którzy jeździli z nim na pogrzeb ojca jego, odprawiwszy pogrzeb ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'A widząc bracia Józefowi, że umarł ojciec ich, mówili: Podobno będzie nas miał w nienawiści Józef, i sowicie odda nam wszystko złe, któreśmy mu uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Wskazali tedy do Józefa, mówiąc: Ojciec twój rozkazał, pierwej niż umarł, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Tak powiedzcie Józefowi: Proszę, odpuść teraz przestępstwo braci twej, i grzech ich, żeć złość wyrządzili; proszę odpuść teraz występek sługom Boga ojca twego. I płakał Józef, gdy to mówili do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'I przystąpili bracia jego, a upadłszy przed nim, mówili: Otośmy sługami twoimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'I rzekł do nich Józef: Nie bójcie się: bo azażem ja wam za Boga?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Wyście złe myślili przeciwko mnie, ale Bóg obrócił to w dobre, chcąc uczynić to, co się dziś dzieje, aby zachował tak wielki lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'A przetoż nie bójcie się, ja żywić będę was i dziatki wasze; a tak cieszył je, i mówił z nimi łagodnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'I mieszkał Józef w Egipcie, sam i dom ojca jego, a żył Józef sto i dziesięć lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'I oglądał Józef syny Efraimowe aż do trzeciego pokolenia. Synowie też Machyra, syna Manasesowego, porodzili się na kolanach Józefowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'I rzekł Józef do braci swej: Ja umrę, ale Bóg zapewnie nawiedzi was, i wyprowadzi was z ziemi tej do ziemi, o którą przysiągł Abrahamowi, Izaakowi i Jakóbowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'I poprzysiągł Józef syny Izraelowe, mówiąc: Gdy was nawiedzi Pan Bóg, wynieście też kości moje stąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'I umarł Józef, mając sto i dziesięć lat; którego namazawszy wonnemi maściami, włożono do trumny w Egipcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Teć są imiona synów Izraelskich, którzy weszli do Egiptu z Jakóbem; każdy z domem swym weszli:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Symeon, Lewi, i Judas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isaszar, Zabulon, i Benjamin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan, i Neftali, Gad, i Aser.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'A było wszystkich dusz, które wyszły z biódr Jakóbowych, siedmdziesiąt dusz; a Józef był przedtem w Egipcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'I umarł Józef, i wszyscy bracia jego, i wszystek on rodzaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'A synowie Izraelscy rozrodzili się, i rozpłodzili się, i rozmnożyli się, i zmocnili się bardzo wielce, a napełniona jest ziemia nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Między tem powstał król nowy nad Egiptem, który nie znał Józefa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'I rzekł do ludu swego: Oto lud synów Izraelskich wielki, i możniejszy nad nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Przetoż mądrze sobie pocznijmy z nimi, by się snać nie rozmnożył, a jeźliby przypadła wojna, aby się nie przyłączył i on do nieprzyjaciół naszych, i nie walczył przeciwko nam, i nie uszedł z ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'A tak ustawili nad nimi poborcę, aby go dręczyli ciężarami swemi; i zbudował lud Izraelski miasta składu Faraonowi: Pytom i Rameses.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Ale im więcej go trapili, tem więcej się rozmnażał, i tem więcej rósł, tak, iż ściśnieni byli dla synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'I podbili Egipczanie syny Izraelskie w niewolą ciężką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'I przykrzyli im żywot ich robotą ciężką około gliny, i około cegieł, i około każdej roboty na polu, mimo wszelaką robotę swą, do której ich używali bez litości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'I rozkazał król Egipski babom Hebrejskim, z których imię jednej Zefora, a imię drugiej Fua;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'A rzekł: Gdy będziecie babić niewiastom Hebrejskim, a ujrzycie że rodzą, byłliby syn, zabijcież go, a jeźli córka, niech żywa zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Ale baby one bały się Boga, i nie czyniły, jako im rozkazał król Egipski, ale żywo zachowywały chłopiątka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Zaczem wezwawszy król Egipski onych bab, mówił do nich: Czemuście to uczyniły, żeście żywo zachowały chłopiątka?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'I odpowiedziały baby Faraonowi: Iż nie są jako niewiasty Egipskie, niewiasty Hebrejskie; bo są duże, pierwej niż przyjdzie do nich baba, rodzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'I czynił dobrze Bóg onym babom; i krzewił się lud, i zmocnili się bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'I stało się, przeto że się bały one baby Boga, pobudował im domy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Tedy rozkazał Farao wszystkiemu ludowi swemu, mówiąc: Każdego syna, który się urodzi, w rzekę go wrzućcie, a każdą córkę żywo zachowajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'I wyszedł mąż niektóry z domu Lewiego; który pojął córkę z pokolenia Lewiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'I poczęła ona niewiasta, a porodziła syna; a widząc go, że był nadobny, kryła go przez trzy miesiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Ale gdy go nie mogła dłużej zataić, wzięła plecionkę z sitowia i obmazała ją klejem i smołą; a włożywszy w nię ono dziecię, położyła je między rogóż na brzegu rzeki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'A stała siostra jego z daleka, aby wiedziała, co się z nim dziać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Wtem wyszła córka Faraonowa, aby się kąpała w rzece, a panny jej przechadzały się po brzegu rzeki; i ujrzała plecionkę w rogoży, i posłała służebnicę swą, aby ją wzięła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'A otworzywszy ujrzała dziecię, a ono chłopiątko płakało; a użaliwszy się go, rzekła: Z dziatek Hebrejskich jest ten.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'I rzekła siostra jego do córki Faraonowej: Chceszże, pójdę, i zawołam ci niewiasty, mamki Hebrejskiej, która być odchowała to dziecię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'I rzekła jej córka Faraonowa: Idź. Tedy poszła ona dzieweczka, i zawołała matki onegoż dziecięcia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Do której rzekła córka Faraonowa: Weźmij to dziecię, i chowaj mi je, a ja tobie dam zapłatę twoję; i wziąwszy niewiasta dziecię, chowała je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'A gdy podrosło ono dziecię, przywiodła je do córki Faraonowej, i było jej za syna; a nazwała imię jego Mojżesz, bo mówiła: Żem z wody wyciągnęła go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'I stało się za onych dni, gdy urósł Mojżesz, że wyszedł do braci swej, i widział ciężary ich; obaczył też męża Egipczanina, który bił jednego Hebrajczyka z braci jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'A obejrzawszy się tam i sam, gdy widział, że nikogo nie masz, zabił Egipczanina, i zagrzebł go w piasek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'A wyszedłszy zaś dnia wtórego, ujrzał, a oto, dwaj mężowie Hebrejscy wadzili się; i rzekł onemu, który krzywdę czynił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Czemuż bijesz bliźniego swego? Ale mu odpowiedział: Któż cię postanowił książęciem i sędzią nad nami? albo mię ty myślisz zabić, jakoś zabił Egipczanina? i zląkł się Mojżesz i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Pewnie się ta rzecz wyjawiła. Usłyszał tedy Farao tę rzecz, i szukał zabić Mojżesza. Lecz Mojżesz uciekł od twarzy Faraonowej, i mieszkał w ziemi Madyjańskiej; a przyszedłszy tam siedział u studni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'A kapłan Madyjański miał siedem córek, które wyszedłszy czerpały wodę, i nalewały do koryt, aby napoiły trzodę ojca swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'A przyszedłszy pasterze odganiali je. Tedy wstawszy Mojżesz obronił ich, i napoił bydło ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'A gdy się wróciły do Raguela, ojca swego, rzekł: Czemuście dziś tak prędko przyszły?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'I odpowiedziały: Mąż Egipski obronił nas od ręki pasterzów; nadto czerpając naczerpał nam i wody i napoił trzody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Zatem rzekł do córek swych: A gdzież ten jest? Czemuście opuściły człowieka tego? Zawołajcie go, aby jadł chleb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'I przyzwolił Mojżesz mieszkać z onym mężem, który dał Zeforę, córkę swoję, Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'I urodziła syna, a nazwał imię jego Gerson, bo mówił: Byłem przychodniem w ziemi cudzej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'I stało się po niemałym czasie, że umarł król Egipski; i wzdychali, i wołali synowie Izraelscy dla niewoli; a wstąpiło wołanie ich do Boga przed niewolą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'I usłyszał Bóg wołanie ich; i wspomniał Bóg na przymierze swoje z Abrahamem, z Izaakiem, i z Jakóbem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'I wejrzał Bóg na syny Izraelskie, i poznał Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'A Mojżesz pasł trzodę Jetra, świekra swego, kapłana Madyjańskiego; i zagnał trzodę na puszczą, a przyszedł do góry Bożej, do Horeb,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'I ukazał mu się Anioł Pański w płomieniu ognistym, z pośrodku krza; i widział, a oto, kierz gorzał ogniem, a on kierz nie zgorzał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Tedy rzekł Mojżesz: Pójdę teraz, a oglądam to widzenie wielkie, czemu nie zgore ten kierz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'A widząc Pan, iż szedł patrzać, zawołał nań Bóg z pośrodku onego krza, mówiąc: Mojżeszu, Mojżeszu! A on odpowiedział: Otom ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Tedy rzekł: Nie przystępuj sam; zzuj buty twe z nóg twoich: albowiem miejsce, na którem ty stoisz, ziemia święta jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Zatem rzekł: Jam jest Bóg ojca twego, Bóg Abrahamów, Bóg Izaaków, i Bóg Jakóbów; i zakrył Mojżesz oblicze swe, bo się bał patrzać na Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'I rzekł Pan: Widząc widziałem utrapienie ludu mojego, który jest w Egipcie, a wołanie ich słyszałem przed przystawy ich; bom doznał boleści jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Przetoż zstąpiłem, abym go wybawił z ręki Egipskiej i wywiódł go z ziemi tej do ziemi dobrej i przestronnej, do ziemi opływającej mlekiem i miodem, na miejsce Chananejczyka, i Hetejczyka, i Amorejczyka, i Ferezejczyka, i Hewejczyka, i Jebuzejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'A teraz oto krzyk synów Izraelskich przyszedł przed mię: i widziałem też ich ucisk, którym je Egipczanie uciskają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Przetoż teraz, pójdź, a poślę cię do Faraona, abyś wywiódł lud mój, syny Izraelskie z Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'I rzekł Mojżesz do Boga: Któżem ja, abym szedł do Faraona, a wywiódł syny Izraelskie z Egiptu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'I rzekł Bóg: Oto, będę z tobą, a to miej na znak, żem cię ja posłał: Gdy wywiedziesz ten lud z Egiptu, będziecie służyć Bogu na tej górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'I rzekł Mojżesz do Boga: Oto, ja pójdę do synów Izraelskich, i rzekę im: Bóg ojców waszych posłał mię do was: Jeźli mi rzeką: Które jest imię jego? Cóż im odpowiem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Tedy rzekł Bóg do Mojżesza: Będę który Będę. I rzekł: Tak powiesz synom Izraelskim: Będę posłał mię do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'I mówił jeszcze Bóg do Mojżesza: Tak rzeczesz do synów Izraelskich: Pan, Bóg ojców waszych, Bóg Abrahamów, Bóg Izaaków, i Bóg Jakóbów posłał mię do was; toć imię moje na wieki, i to pamiętne moje od narodu do narodu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Idźże, a zgromadź starsze Izraelskie, i mów do nich: Pan, Bóg ojców waszych, ukazał mi się, Bóg Abrahamów, Izaaków i Jakóbów, mówiąc: Wspominając wspomniałem na was, i widziałem, co się wam działo w Egipcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'I rzekłem: Wyprowadzę was z utrapienia Egipskiego do ziemi Chananejczyka, i Hetejczyka, i Amorejczyka, i Ferezejczyka, i Hewejczyka, i Jebuzejczyka, do ziemi opływającej mlekiem i miodem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Tedy usłuchają głosu twego, a pójdziesz ty i starsi Izraelscy do króla Egipskiego, i rzeczecie do niego: Pan, Bóg Hebrajczyków, zabieżał nam; przetoż teraz niech pójdziemy proszę w drogę trzech dni na puszczą, abyśmy ofiarowali Panu, Bogu naszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Ale ja wiem, że wam nie pozwoli król Egipski odejść, jedno przez możną rękę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'A tak wyciągnę rękę moję, i uderzę Egipt wszystkiemi cudami mojemi, które będę czynił w pośrodku jego: a potem wypuści was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'I dam łaskę ludowi temu w oczach Egipczanów: i stanie się, gdy wychodzić będziecie, że nie wynijdziecie próżni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Ale wypożyczy niewiasta u sąsiadki swojej, i u gospodyni domu swego, naczynia srebrnego, i naczynia złotego, i szat; i włożycie je na syny wasze, i na córki wasze, i złupicie Egipt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Potem odpowiadając Mojżesz, rzekł: Ale oto, nie uwierzą mi, i nie usłuchają głosu mego, bo rzeką: Nie ukazał się tobie Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'I rzekł mu Pan: Cóż jest w ręce twojej? i odpowiedział: Laska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'I rzekł: Porzuć ją na ziemię; i porzucił ją na ziemię, a obróciła się w węża, i uciekał Mojżesz przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'I rzekł Pan do Mojżesza: Wyciągnij rękę twoję, a ujmij go za ogon; i wyciągnął rękę swoję, i ujął go, i obrócił się w laskę w ręce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Abyć uwierzyli, iż ci się ukazał Pan, Bóg ojców ich, Bóg Abrahamów, Bóg Izaaków, i Bóg Jakóbów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'I rzekł mu Pan jeszcze: Włóż teraz rękę twoję w zanadrza twoje; i włożył rękę swoję w zanadrza swoje; i wyjął ją, a oto, ręka jego była trędowata jako śnieg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'I rzekł: Włóż znowu rękę twoję w zanadrza twe; i włożył znowu rękę swoję w zanadrza swe; a gdy ją wyjął z zanadrza swego, a oto, stała się znowu jako inne ciało jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'I stanie się, jeźlić nie uwierzą i nie usłuchają głosu znaku pierwszego, tedy uwierzą głosowi znaku pośledniego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'I stanie się, jeźli nie uwierzą ani tym dwom znakom, i nie usłuchają głosu twego, weźmiesz wody rzecznej, i wylejesz ją na ziemię; tedy się przemieni woda ona, którą weźmiesz z rzeki, a obróci się w krew na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'I rzekł Mojżesz do Pana. Proszę Panie, nie jestem ja mężem wymownym ani przedtem ani odtąd, jakoś mówił do sługi twego: bom ciężkich ust i ciężkiego języka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'A Pan mu rzekł: Któż uczynił usta człowiekowi? albo kto uczynił niemego, albo głuchego, albo widzącego, albo ślepego, izaż nie Ja Pan?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Idźże teraz, a Ja będę z usty twojemi, i nauczę cię, co byś miał mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'I rzekł Mojżesz: Słuchaj Panie, poślij proszę tego, kogo posłać masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'I zapalił się gniew Pański na Mojżesza, i rzekł: Azaż nie wiem, iż Aaron, brat twój Lewita wymownym jest? a oto i ten wynijdzie przeciwko tobie, i ujrzawszy cię, uraduje się w sercu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'I będziesz mówił do niego, i włożysz słowa w usta jego, a Ja będę z usty twemi, i z usty jego, i nauczę was, co byście mieli czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'On będzie mówił za cię do ludu, i stanie się, że on będzie tobie za usta, a ty mu będziesz za Boga;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Laskę też tę weźmij w rękę twoję, którą będziesz czynił znaki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Odszedł tedy Mojżesz, i wrócił się do Jetra, świekra swego, i mówił do niego: Pójdę teraz, a wrócę się do braci mojej, którzy są w Egipcie, a obaczę, sąli jeszcze żywi. A Jetro rzekł do Mojżesza: Idź w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'I rzekł Pan do Mojżesza w ziemi Madyjańskiej: Idź, wróć się do Egiptu; pomarli bowiem wszyscy mężowie, którzy szukali duszy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Wziąwszy tedy Mojżesz żonę swą, i syny swe, wsadził je na osła, i wrócił się do ziemi Egipskiej; wziął też Mojżesz laskę Bożą w rękę swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'I rzekł Pan do Mojżesza: Gdy pójdziesz i wrócisz się do Egiptu, patrzajże, abyś wszystkie cuda, którem Ja podał w rękę twoję, czynił przed Faraonem, a Ja zatwardzę serce jego, aby nie wypuścił lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'I rzeczesz do Faraona: Tak mówi Pan: Syn mój, pierworodny mój jest Izrael.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'I rzekłem do ciebie: Wypuść syna mego, aby mi służył; a żeś go nie chciał wypuścić, oto, Ja zabiję syna twojego, pierworodnego twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'I stało się w drodze, w gospodzie, że zabieżał Pan Mojżeszowi, i chciał go zabić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Tedy wziąwszy Zefora krzemień ostry, obrzezała nieobrzezkę syna swego, i porzuciła przed nogi jego, i rzekła: Zaprawdę oblubieńcem krwi jesteś mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'I odszedł od niego Pan. Tedy go nazwała oblubieńcem krwi, dla obrzezania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'I rzekł Pan do Aarona: Idź przeciwko Mojżeszowi na puszczą. I szedł i zaszedł mu na górze Bożej, i pocałował go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Tedy powiedział Mojżesz Aaronowi wszystkie słowa Pana, który go posłał, i wszystkie znaki, które mu rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Szedłszy tedy Mojżesz z Aaronem, zgromadzili wszystkie starsze synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'I powiedział Aaron wszystkie słowa, które mówił Pan do Mojżesza, a Mojżesz czynił znaki przed oczyma ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'I uwierzył lud, i zrozumieli, że nawiedził Pan syny Izraelskie, a iż wejżał na utrapienie ich; i schyliwszy się, pokłon uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Potem tedy przyszli Mojżesz i Aaron, i mówili do Faraona: Tak mówi Pan, Bóg Izraelski: Puść lud mój, aby mi obchodzili święto na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'I rzekł Farao: Któż jest Pan, żebym miał słuchać głosu Jego, i puścić Izraela? Nie znam Pana, a Izraela też nie puszczę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'I odpowiedzieli: Bóg Hebrajczyków zabieżał nam, pójdziemy teraz drogą trzech dni na puszczą, abyśmy ofiarowali Panu Bogu naszemu, by snać nie przepuścił na nas moru albo miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'I rzekł do nich król Egipski: Przecz ty Mojżeszu i Aaronie odrywacie lud od robót ich? Idźcież do robót waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Rzekł też Farao: Oto, wielki teraz jest ten lud w ziemi, a wy je odrywacie od robót ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Rozkazał tedy Farao onegoż dnia przystawom nad ludem, i urzędnikom jego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Już więcej nie będziecie dawać plew ludowi do czynienia cegły, jako przedtem; sami niech idą, i zbierają sobie plewy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'A tęż liczbę cegieł, którą czynili przedtem, włożycie im, nie umniejszycie z niej; bo próżnują, dla tego oni wołają, mówiąc: Pójdziemy i będziemy ofiarować Bogu naszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Niech się przyczyni roboty mężom tym, a niech ją wykonywają, aby nie ufali słowom kłamliwym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Wyszedłszy tedy przystawowie nad ludem i urzędnicy jego, rzekli do ludu, mówiąc: Tak mówi Farao: Ja nie będę wam dawał plew.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Sami idźcie, zbierajcie sobie plewy, gdzie znajdziecie; bo się najmniej nie umniejszy z roboty waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'I rozbieżał się lud po wszystkiej ziemi Egipskiej, aby zbierał ściernisko miasto plew.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'A przystawowie przynaglali, mówiąc: Wykonywajcie roboty wasze, zamiar każdodzienny, jako gdy wam dawano plewy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Tedy bito przystawy synów Izraelskich, które postanowili nad nimi urzędnicy Faraonowi, mówiąc: Przecz nie wykonywacie zamiaru swego w robieniu cegieł jako pierwej, ani wczoraj ani dziś?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'I przyszli przełożeni synów Izraelskich i wołali do Faraona, mówiąc: Czemuż tak czynisz sługom twoim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Plew nie dają sługom twoim, a mówią: Cegłę róbcie. I oto, sługi twe biją a lud twój grzeszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Który rzekł: Próżnujecie, próżnujecie, dla tegoż mówicie: Pójdziemy, ofiarować będziemy Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Przetoż teraz idźcie, róbcie, a plew wam nie dadzą, ale wy liczbę cegieł oddawać będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'A widząc przełożeni synów Izraelskich, że źle z nimi, ponieważ mówiono: Nie umniejszycie z cegieł waszych zamiaru każdodziennego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Tedy oni zabieżeli Mojżeszowi i Aaronowi, którzy stali, aby się z nimi spotkali, gdy wychodzili od Faraona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'I rzekli do nich: Niech wejrzy Pan na was a rozsądzi, żeście nas ohydzili w oczach Faraonowych, i w oczach sług jego, i daliście miecz w rękę ich, aby nas zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'I wrócił się Mojżesz do Pana, a rzekł: Panie, czemuś to złe wprowadził na lud twój, czemuś mię tu posłał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Bo od onego czasu, jakom wszedł do Faraona, abym mówił imieniem twojem, gorzej się obchodzi z ludem tym; a przecięś nie wybawił ludu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'I rzekł Pan do Mojżesza: Teraz ujrzysz, co uczynię Faraonowi; bo w ręce możnej wypuści je, i w ręce silnej wypędzi je z ziemi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Nadto mówił Bóg do Mojżesza i rzekł do niego: Jam Pan,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Którym się ukazał Abrahamowi, Izaakowi i Jakóbowi w tem imieniu, żem Bóg Wszechmogący; ale w imieniu mojem, Jehowa, nie jestem poznany od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Postanowiłem też i przymierze moje z nimi, abym im dał ziemię Chananejską, ziemię pielgrzymowania ich, w której przychodniami byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Jam też usłyszał krzyk synów Izraelskich, które Egipczanie w niewolą podbijają, i wspomniałem na przymierze moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'A tak rzecz do synów Izraelskich: Jam Pan, a wywiodę was z ciężarów Egipskich, i wyrwę was z niewoli ich, i wybawię was w ramieniu wyciągnionem, i w sądziech wielkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'A wezmę was sobie za lud, i będę wam za Boga, i poznacie, żem Pan, Bóg wasz, który was wywodzę z ciężarów Egipskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'A wprowadzę was do ziemi, o którą podniosłem rękę moję, abym ją dał Abrahamowi, Izaakowi, i Jakóbowi; a dam ją wam w dziedzictwo, Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'I mówił tak Mojżesz do synów Izraelskich, ale nie usłuchali Mojżesza dla ściśnionego ducha, i dla niewoli ciężkiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Rzekł tedy Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Wnijdź, mów do Faraona, króla Egipskiego, żeby wypuścił syny Izraelskie z ziemi swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'I rzekł Mojżesz przed Panem, mówiąc: Oto, synowie Izraelscy nie usłuchali mię, a jakoż mię usłucha Farao? a jam nie obrzezanych warg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Tedy rzekł Pan do Mojżesza i do Aarona, i dał im rozkazanie do synów Izraelskich i do Faraona, króla Egipskiego, aby wywiedli syny Izraelskie z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'A cić są przedniejsi z domów ojców ich; synowie Rubena, pierworodnego Izraelowego: Henoch i Falu, Hesron, i Charmi. Teć są rodzaje Rubenowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'A synowie Symeonowi: Jamuel i Jamyn, i Ahod, i Jachyn, i Sochar, i Saul, syn niewiasty Chananejskiej. Teć są rodzaje Symeonowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Imiona zaś synów Lewiego według rodzajów ich: Gerson i Kaat, i Merary; a lat żywota Lewiego było sto trzydzieści i siedem lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Synowie Gersonowi: Lobni i Semei, według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'A synowie Kaatowi: Amram, i Izaar, i Hebron, i Husyjel; a lat żywota Kaatowego było sto i trzydzieści i trzy lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Synowie też Merarego: Maheli, i Muzy. Teć są domy Lewiego według rodzajów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'I pojął Amram Jochabedę, ciotkę swoję, za żonę, która mu urodziła Aarona i Mojżesza; a lat żywota Amramowego było sto i trzydzieści i siedem lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Synowie zaś Izaarowi: Kore i Nefeg, i Zychry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'A synowie Husyjelowi: Myzael, i Elisafan, i Setry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'I pojął Aaron Elizabetę, córkę Aminadaba, siostrę Nasonowę, sobie za żonę, która mu urodziła Nadaba, i Abiu. Eleazara, i Itamara.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'A synowie Korego: Asyr, i Elkana, i Abyjazaf. Teć są domy Korytów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'A Eleazar, syn Aaronów, pojął jednę z córek Putyjelowych sobie za żonę, która mu urodziła Fyneesa. Cić są przedniejsi z ojców Lewitskich według rodzajów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Tenci jest Aaron i Mojżesz, do których mówił Pan: Wywiedźcie syny Izraelskie z ziemi Egipskiej według hufców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Cić mówili do Faraona, króla Egipskiego, aby wyprowadzili syny Izraelskie z Egiptu; toć jest ten Mojżesz i Aaron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'I stało się w ten dzień, którego mówił Pan do Mojżesza w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Że rzekł Pan do Mojżesza mówiąc: Jam Pan; mów do Faraona, króla Egipskiego, wszystko, co Ja mówię do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'I rzekł Mojżesz przed Panem: Otom ja nie obrzezanych warg, a jakoż mię usłucha Farao?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'I rzekł Pan do Mojżesza: Oto, postanowiłem cię za Boga Faraonowi, a Aaron, brat twój, będzie prorokiem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Ty powiesz wszystko, coć rozkażę: ale Aaron, brat twój, będzie mówił do Faraona, aby wypuścił syny Izraelskie z ziemi swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'A Ja zatwardzę serce Faraonowe, i rozmnożę znaki moje i cuda moje w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'I nie usłucha was Farao; lecz Ja włożę rękę moję na Egipt, i wyprowadzę wojska moje, lud mój, syny Izraelskie, z ziemi Egipskiej w sądziech wielkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'A poznają Egipczanie, żem Ja Pan, gdy wyciągnę rękę moję na Egipt, i wywiodę syny Izraelskie z pośrodku ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Uczynił tedy Mojżesz i Aaron, jako im przykazał Pan, tak uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'A Mojżesz miał osiemdziesiąt lat, a Aaron osiemdziesiąt i trzy lata, gdy mówili do Faraona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Rzekł tedy Pan do Mojżesza, i do Aarona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Gdy wam rzecze Farao, mówiąc: Uczyńcie jaki cud, tedy rzeczesz do Aarona: Weźmij laskę twoję, a porzuć przed Faraonem, a obróci się w węża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'I przyszedł Mojżesz z Aaronem do Faraona, i uczynili tak, jako rozkazał Pan; i porzucił Aaron laskę swoję przed Faraonem, i przed sługami jego, która się obróciła w węża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Wezwał też Farao mędrców i czarowników, i uczynili i ci czarownicy Egipscy przez czary swe także.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'I porzucił każdy laskę swą, a obróciły się w węże; ale pożarła laska Aaronowa laski ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'I zatwardziało serce Faraonowe, i nie usłuchał ich, jako powiedział Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Zatem rzekł Pan do Mojżesza: Ociężało serce Faraonowe; nie chce puścić ludu tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Idź do Faraona rano, oto, wynijdzie nad wodę, tedy staniesz przeciwko niemu nad brzegiem rzeki, a laskę, która się była obróciła w węża, weźmiesz w rękę twoję,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'I rzeczesz do niego: Pan Bóg Hebrejczyków posłał mię do ciebie, mówiąc: Wypuść lud mój, aby mi służyli na puszczy, a oto, nie usłuchałeś dotąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Przetoż tak mówi Pan: Po tem poznasz, żem ja Pan; oto, ja uderzę laską, która jest w ręce mojej, na wody, które są w rzece, a obrócą się w krew.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'A ryby, które są w rzece, pozdychają, i zśmierdnie się rzeka, i spracują się Egipczanie, szukając dla napoju wód z rzeki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Tedy rzekł Pan do Mojżesza: Mów do Aarona: Weźmij laskę twoję, a wyciągnij rękę twą na wody Egipskie, na rzeki ich, na strugi ich, i na jeziora ich, i na wszelkie zgromadzenie wód ich; i obrócą się w krew, i będzie krew po wszystkiej ziemi Egipskiej, tak w naczyniach drewnianych, jako w kamiennych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'I uczynili tak Mojżesz i Aaron, jako rozkazał Pan; i podniósłszy laskę uderzył wody, które były w rzece, przed oczyma Faraonowemi, i przed oczyma sług jego; i obróciły się wszystkie wody, które były w rzece, w krew.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'A ryby, które były w rzece, pozdychały, i zśmierdła się rzeka, że nie mogli Egipczanie pić wody z rzeki; i była krew po wszystkiej ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'I uczynili także czarownicy Egipscy czarami swemi; i zatwardziało serce Faraonowe, i nie usłuchał ich, jako był powiedział Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'A odwróciwszy się Farao, poszedł do domu swego, a nie przyłożył serca swego i do tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'I kopali wszyscy Egipczanie około rzeki, szukając wody, aby pili; bo nie mogli pić wody z rzeki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'I wypełniło się siedem dni, jako zaraził Pan rzekę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'I rzekł Pan do Mojżesza: Wnijdź do Faraona, a mów do niego: Tak mówi Pan: Wypuść lud mój, aby mi służył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Ale jeźli ty nie będziesz chciał puścić, oto, Ja zarażę wszystkie granice twoje żabami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'I wyda rzeka żaby, które wylezą i wnijdą do domu twego, i do komory łoża twego, i na pościel twoję, i do domu sług twoich, i między lud twój, i do pieców twoich, i w dzieże twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Tak na cię, jako na lud twój, i na wszystkie sługi twoje polezą żaby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Tedy rzekł Pan do Mojżesza: Rzecz do Aarona: Wyciągnij rękę twoję z laską twą na rzeki, na strugi, i na jeziora, a wywiedź żaby na ziemię Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Tedy wyciągnął Aaron rękę swą na wody Egipskie, i wylazły żaby, które okryły ziemię Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'I uczynili także czarownicy czarami swemi, i wywiedli żaby na ziemię Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Zatem Farao wezwał Mojżesza i Aarona, mówiąc: Módlcie się Panu, aby oddalił żaby ode mnie, i od ludu mego; a wypuszczę lud, aby ofiarowali Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'I rzekł Mojżesz do Faraona: Poczczę cię tem, a powiedz, kiedy się modlić mam za cię, i za sługi twoje, i za lud twój, aby wytracone były żaby od ciebie, i z domów twoich, a tylko w rzece zostały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'A on rzekł: Jutro. Tedy rzekł Mojżesz: Uczynię według słowa twego, abyś wiedział, że nie masz, jako Pan Bóg nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'I odejdą żaby od ciebie, i od domów twoich, i od sług twoich, i od ludu twego, tylko w rzece zostaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Wyszedł tedy Mojżesz i Aaron od Faraona. I zawołał Mojżesz do Pana, aby odjął żaby, które był przepuścił na Faraona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'I uczynił Pan według słowa Mojżeszowego, że wyzdychały żaby z domów, ze wsi, i z pól.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'I zgromadzali je na kupy, i zśmierdła się ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'A widząc Farao, że miał wytchnienie, obciążył serce swoje, i nie usłuchał ich, jako był powiedział Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'I rzekł Pan do Mojżesza: Mów do Aarona: Wyciągnij laskę twoję, a uderz w proch ziemi, aby się obrócił we wszy po wszystkiej ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'I uczynili tak; bo wyciągnął Aaron rękę swoję z laską swoją, i uderzył w proch ziemi; i były wszy na ludziach, i na bydle; wszystek proch ziemi obrócił się we wszy po wszystkiej ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Czynili też także czarownicy, przez czary swoje, aby wywiedli wszy, ale nie mogli; i były wszy na ludziach i na bydle.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Tedy rzekli czarownicy do Faraona: Palec to Boży jest. I zatwardziało serce Faraonowe, i nie usłuchał ich, jako powiedział Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'I rzekł Pan do Mojżesza: Wstań rano, a stań przed Faraonem, (oto, wynijdzie do wody,) i rzeczesz do niego: Tak mówi Pan: Wypuść lud mój, aby mi służył;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Bo jeźli ty nie wypuścisz ludu mego, oto, Ja posyłam na cię, i na sługi twe, i na lud twój, i na domy twoje rozmaite robactwo; a będą napełnione domy Egipskie rozmaitem robactwem, nadto i ziemia, na której oni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'A oddzielę dnia onego ziemię Gosen, w której lud mój mieszka, aby tam nie było rozmaitego robactwa, abyś poznał, żem Ja Pan w pośrodku ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'I położę znak odkupienia między ludem moim i między ludem twoim; jutro będzie znak ten.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Tedy uczynił tak Pan. I przyszło rozmaite robactwo ciężkie na dom Faraonów, i na dom sług jego, i na wszystkę ziemię Egipską; i psowała się ziemia od rozmaitego robactwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Zatem wezwał Farao Mojżesza i Aarona, i rzekł: Idźcie, ofiarujcie Bogu waszemu w tej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'I odpowiedział Mojżesz: Nie godzi się tak czynić; bo byśmy obrzydliwość Egipską ofiarowali Panu Bogu naszemu; a gdybyśmy ofiarowali obrzydliwość Egipską przed oczyma ich, zażby nas nie ukamionowali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Drogę trzech dni pójdziemy na puszczą, i ofiarować będziemy Panu Bogu naszemu, jako nam rozkaże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'I rzekł Farao: Jać wypuszczę was, abyście ofiarowali Panu Bogu waszemu na puszczy, wszakże daleko nie odchodźcie, i módlcie się za mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'I odpowiedział Mojżesz: Ja wychodzę od ciebie, i będę się modlił Panu, a odejdzie rozmaite robactwo od Faraona, od sług jego, i od ludu jego jutro; tylko niech więcej Farao nie kłamie, aby nie miał wypuścić ludu dla ofiarowania Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'Wyszedłszy tedy Mojżesz od Faraona, modlił się Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'I uczynił Pan według słowa Mojżeszowego, i oddalił ono rozmaite robactwo od Faraona, i od sług jego, i od ludu jego, a nie zostało i jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Jednak Farao obciążył serce swe i tym razem, a nie wypuścił ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Potem rzekł Pan do Mojżesza: Wnijdź do Faraona, a mów do niego: Tak mówi Pan, Bóg Hebrejczyków: Wypuść lud mój, aby mi służył;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Bo jeźli go ty nie będziesz chciał wypuścić, ale jeszcze zatrzymywać go będziesz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Oto, ręka Pańska będzie na bydle twojem, które jest na polu, na koniach, na osłach, na wielbłądach, na wołach i na owcach, powietrze bardzo ciężkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'I uczyni Pan rozdział między trzodami Izraelskiemi, i między trzodami Egipskiemi, aby nic nie zdechło ze wszystkiego, co jest synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'I postanowił Pan czas, mówiąc: Jutro uczyni Pan tę rzecz na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'I uczynił Pan tę rzecz nazajutrz, że wyzdychały wszystkie bydła Egipskie; ale z bydła synów Izraelskich nie zdechło ani jedno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'I posłał Farao, a oto, nie zdechło z bydła Izraelskiego i jedno; ale ociężało serce Faraonowe, i nie wypuścił ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Zatem rzekł Pan do Mojżesza i do Aarona: Weźmijcie pełne garści wasze popiołu z pieca, a niech go rozrzuci Mojżesz ku niebu przed oczyma Faraonowemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'I obróci się w proch po wszystkiej ziemi Egipskiej, i będzie na ludziach, i na bydle wrzodem czyniącym pryszczele, po wszystkiej ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Wzięli tedy popiołu z pieca, i stanęli przed Faraonem, i rozrzucił go Mojżesz ku niebu; i stał się wrzodem, pryszczele czyniącym na ludziach i na bydle;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'I nie mogli czarownicy stać przed Mojżeszem dla wrzodu; bo był wrzód na czarownikach i na wszystkich Egipczanach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'I zatwardził Pan serce Faraonowe, i nie usłuchał ich, jako był powiedział Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'I rzekł Pan do Mojżesza: Wstań rano, a stań przed Faraonem, i mów do niego: Tak mówi Pan, Bóg Hebrejczyków: Wypuść lud mój, aby mi służył:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Bo tą razą Ja posyłam wszystkie plagi moje na serce twoje, i na sługi twoje, i na lud twój, abyś wiedział, że nie masz mnie podobnego po wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Bo teraz ściągnę rękę moję a uderzę cię i lud twój powietrzem, i wytracony będziesz z ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'A zaiste, dla tegom cię zachował, abym okazał na tobie moc moję, i żeby opowiadane było imię moje po wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Jeszczeż się ty wynosisz przeciw ludowi memu, nie chcąc go wypuścić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Oto, Ja spuszczę o tym czasie jutro grad bardzo ciężki, jakiemu nie było podobnego w Egipcie ode dnia, którego jest założon, aż do tego czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'A tak poślij teraz, zgromadź bydło twoje, i wszystko, co masz na polu; bo na każdego człowieka, i na bydlę, które znalezione będzie na polu, a nie będzie zegnane w dom, spadnie na nie grad, i pozdychają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Kto się tedy uląkł słowa Pańskiego z sług Faraonowych, kazał uciekać sługom swym, i z bydłem swojem do domu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Ale kto nie przyłożył serca swego do słowa Pańskiego, ten zostawił sługi swe i bydło swe na polu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'I rzekł Pan do Mojżesza: Wyciągnij rękę twą ku niebu, że będzie grad po wszystkiej ziemi Egipskiej, na ludzi, i na bydło, i na wszelakie zioła polne w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'A tak wyciągnął Mojżesz laskę swą ku niebu, a Pan dał gromy i grad, i zstąpił ogień na ziemię, i spuścił Pan grad na ziemię Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'I był grad, i ogień zmieszany z gradem ciężkim bardzo, jakiemu nie był podobny we wszystkiej ziemi Egipskiej, jako w niej mieszkać poczęto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'I potłukł on grad po wszystkiej ziemi Egipskiej, cokolwiek było na polu, od człowieka aż do bydlęcia; i wszystko ziele polne potłukł grad, i wszystko drzewo polne połamał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Tylko w ziemi Gosen, gdzie synowie Izraelscy mieszkali, nie było gradu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Posłał tedy Farao, a wezwał Mojżesza i Aarona, mówiąc do nich: Zgrzeszyłem i tym razem; Pan jest sprawiedliwy, ale ja i lud mój niezbożniśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Módlcież się Panu,(boć dosyć jest,) aby przestały gromy Boże i grad; a wypuszczę was, i nie będziecie tu mieszkać dalej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'I rzekł Mojżesz do niego: Gdy wynijdę z miasta, wyciągnę ręce swe do Pana, a gromy ustaną, i grad nie będzie więcej, abyś wiedział, że Pańska jest ziemia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Ale ty i słudzy twoi, wiem, że się jeszcze nie boicie oblicza Pana Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Len tedy i jęczmień potłuczony jest; bo jęczmień był niedostały, a len podrastał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Pszenica jednak i żyto potłuczone nie były; bo późne były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Wyszedłszy tedy Mojżesz od Faraona z miasta, wyciągnął ręce swe do Pana; i przestały gromy i grad, a deszcz nie padał na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'A widząc Farao, że przestał deszcz, i grad, i gromy, przyczynił grzechu, a obciążył serce swe, sam i słudzy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'I zatwardziało serce Faraonowe, i nie wypuścił synów Izraelskich, jako był powiedział Pan przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Rzekł zatem Pan do Mojżesza: Wnijdź do Faraona; bom Ja obciążył serce jego, i serce sług jego, abym czynił te znaki moje między nimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'Ażebyś opowiadał w uszach synów twoich, i wnuków twoich, com uczynił w Egipcie, i znaki moje, którem pokazał na nich, abyście wiedzieli, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Wszedł tedy Mojżesz i Aaron do Faraona, i mówili mu: Tak mówi Pan, Bóg Hebrajczyków: Dokądże nie chcesz uniżyć się przede mną? Wypuść lud mój, aby mi służył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Bo jeźli nie będziesz chciał wypuścić ludu mego, oto ja przywiodę jutro szarańczę na granicę twoję,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'Która okryje wierzch ziemi, że jej widać nie będzie, i zje ostatek pozostały, który wam został po gradzie, i pogryzie każde drzewo rodzące na polu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'I na pełni domy twoje, i domy wszystkich sług twoich, i domy wszystkiego Egiptu, czego nie widzieli ojcowie twoi, i ojcowie ojców twoich od początku bytu swego na ziemi aż do tego dnia. A odwróciwszy się, wyszedł od Faraona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Tedy rzekli słudzy Faraonowi do niego: Długoż będzie nam ten ku zgorszeniu? Wypuść te męże, aby służyli Panu Bogu swemu; zaż jeszcze nie wiesz, że zniszczył Egipt?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'I zawołano zaś Mojżesza z Aaronem do Faraona, i rzekł do nich: Idźcie, służcie Panu Bogu waszemu; którzyż to są, co pójdą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'I odpowiedział Mojżesz: Z dziećmi naszemi i z starcami naszymi pójdziemy, z synami naszymi, i z córkami naszemi, z trzodami naszemi, i z bydłem naszem pójdziemy; bo święto Panu obchodzić mamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Tedy im on rzekł: Niech tak będzie Pan z wami, i jako ja was puszczę, i dzieci wasze; patrzcie, że coś złego przed sobą macie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Nie tak; ale idźcie sami mężowie, a służcie Panu, ponieważ wy tego szukacie. I wygnał je od siebie Farao.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Potem Pan rzekł do Mojżesza: Wyciągnij rękę twą na ziemię Egipską dla szarańczy, aby przyszła na ziemię Egipską, a pożarła wszystko ziele na ziemi, wszystko, co zostało po gradzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'I wyciągnął Mojżesz laskę swoję na ziemię Egipską, a Pan przywiódł wiatr wschodni na ziemię przez cały on dzień, i przez całą noc; a gdy było rano, wiatr wschodni przyniósł szarańczę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'I przyszła szarańcza na wszystkę ziemię Egipską, i przypadła na wszystkie granice Egipskie bardzo ciężka; przedtem nie było tej podobnej szarańczy, i po niej nie będzie takowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'I okryła wierzch wszystkiej ziemi, tak, iż ziemi znać nie było; a pożarła wszystkę trawę ziemi, i wszystek owoc drzewa, który został po gradzie, a nie zostało żadnej zieloności na drzewie i na trawie polnej we wszystkiej ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Przetoż co rychlej Farao wezwał Mojżesza i Aarona, i rzekł: Zgrzeszyłem przeciwko Panu Bogu waszemu, i przeciwko wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'A teraz odpuść proszę grzech mój aby ten raz, a módlcie się Panu Bogu waszemu, aby oddalił ode mnie tylko tę śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'I wyszedłszy Mojżesz od Faraona, modlił się Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'A obróciwszy Pan wiatr zachodni mocny bardzo, porwał szarańczę, i wrzucił ją do morza czerwonego, i nie została ani jedna szarańcza we wszystkich granicach Egipskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'I zatwardził Pan serce Faraonowe, i nie wypuścił synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Tedy rzekł Pan do Mojżesza: Wyciągnij rękę twą ku niebu, a będą ciemności po ziemi Egipskiej, i macać ich będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'I wyciągnął Mojżesz rękę swą ku niebu, i były ciemności gęste po wszystkiej ziemi Egipskiej przez trzy dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Nie widział jeden drugiego, ani się kto ruszył z miejsca swego przez one trzy dni; lecz u wszystkich synów Izraelskich była światłość w mieszkaniach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'A wezwawszy Farao Mojżesza, rzekł: Idźcie, służcie Panu; tylko trzody wasze, i bydła wasze niech zostaną, i dzieci wasze niech idą z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'I odpowiedział Mojżesz: Owszem ty dasz do rąk naszych ofiary i całopalenia, które ofiarować będziemy Panu, Bogu naszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Przetoż i dobytek nasz pójdzie z nami, a nie zostanie i kopyto; albowiem z tego weźmiemy do służby Panu, Bogu naszemu; bo my nie wiemy, czem służyć mamy Panu, aż tam przyjdziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'I zatwardził Pan serce Faraonowe, i nie chciał ich puścić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'I rzekł Farao do Mojżesza: Idź ode mnie, a strzeż się, abyś więcej nie widział oblicza mego; bo dnia, którego ujrzysz oblicze moje, umrzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'I odpowiedział Mojżesz: Dobrześ powiedział; nie ujrzę więcej oblicza twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'I rzekł Pan do Mojżesza: Jeszcze jednę plagę przywiodę na Faraona, i na Egipt, potem wypuści was stąd; wypuści cale, owszem wypędzi was stąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Mówże teraz do uszu ludu, aby wypożyczył każdy od bliźniego swego, i każda u sąsiadki swej naczynia srebrnego, i naczynia złotego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'A dał Pan łaskę ludowi w oczach Egipczan, i był Mojżesz mąż bardzo wielki w ziemi Egipskiej, w oczach sług Faraonowych, i w oczach ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Tedy rzekł Mojżesz: Tak mówi Pan: O północy Ja pójdę przez pośrodek Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'A umrze każde pierworodne w ziemi Egipskiej, od pierworodnego Faraonowego, który miał siedzieć na stolicy jego, aż do pierworodnego niewolnicy, która jest przy żarnach, i każde pierworodne z bydląt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'A będzie krzyk wielki po wszystkiej ziemi Egipskiej, jaki przedtem nie był, i jaki potem nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Ale u wszystkich synów Izraelskich nie ruszy językiem swym, ani pies, ani człowiek, ani bydlę, abyście wiedzieli, że Pan uczynił rozdział między Egipczany i między Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'I przyjdą ci wszyscy słudzy twoi do mnie, a kłaniać mi się będą, mówiąc: Wynijdź ty, i wszystek lud, który jest pod sprawą twoją; a potem wynijdę. I wyszedł od Faraona z wielkim gniewem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'I rzekł Pan do Mojżesza: Nie usłucha was Farao, abym rozmnożył cuda moje w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Tedy Mojżesz i Aaron czynili te wszystkie cuda przed Faraonem; ale Pan zatwardził serce Faraonowe, i nie wypuścił synów Izraelskich z ziemi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Rzekł jeszcze Pan do Mojżesza i do Aarona w ziemi Egipskiej, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Miesiąc ten będzie wam początkiem miesięcy: pierwszy wam będzie między miesiącami w roku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Rzeczcie do wszystkiego zgromadzenia Izraelskiego, mówiąc: Dziesiątego dnia miesiąca tego weźmie sobie każdy baranka według familii, baranka według domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'A jeźliby mniejszy był dom niżeliby zjeść mogli baranka, tedy przybierze i sąsiada swego, który jest najbliższy domu jego, według liczby dusz, naliczywszy tyle osób, ileby ich zjeść mogło baranka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Baranka zupełnego, samca rocznego, mieć będziecie; z owiec albo z kóz weźmiecie go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'I będziecie go chowali aż do czternastego dnia miesiąca tego; a zabije go wszystko zebranie zgromadzenia Izraelskiego między dwoma wieczorami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'I wezmą ze krwi jego, i pokropią obydwa podwoje i nadprożnik u domu; w którym go będą spożywać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'I będą jeść mięso onej nocy pieczone przy ogniu, i przaśniki, z zioły gorzkiemi będą go jeść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Nie jedzcie z niego nic surowego, ani warzonego w wodzie, ale upieczone przy ogniu. Głowę jego z nogami jego, z wnętrznościami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'A nie zostanie z niego nic do jutra; a jeźliby co z niego do jutra zostało, ogniem spalicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Tak go tedy pożywać będziecie: Biodra swe przepaszecie, obuwie wasze będzie na nogach waszych, a laska wasza w ręce waszej, a jeść go będziecie spieszno, albowiem przejście jest Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Gdyż przejdę przez ziemię Egipską tej nocy, i zabiję wszelkie pierworodne w ziemi Egipskiej, od człowieka aż do bydlęcia, i nad wszystkimi bogi Egipskimi wykonam sądy, Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'A będzie wam ona krew na znak na domach, w których będziecie; bo ujrzawszy krew, minę was, że nie będzie u was plaga ku zatraceniu, gdy będę zabijał w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'A będzie wam ten dzień na pamiątkę; i będziecie go obchodzić za święto Panu w narodziech waszych; ustawą wieczną obchodzić go będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Przez siedem dni przaśniki jeść będziecie, a pierwszego dnia zaraz wypróżnicie kwas z domów waszych; bo ktobykolwiek jadł co kwaszonego od pierwszego dnia aż do dnia siódmego, wytracona będzie dusza ona z Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'W tenże dzień pierwszy będzie zebranie święte, także dnia siódmego zgromadzenie święte mieć będziecie; żadnej roboty nie będziecie w nich czynić, oprócz tego, czego każdy do jedzenia używa, to samo gotować będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'I będziecie przestrzegać przaśników; albowiem w ten dzień wywiodłem wojska wasze z ziemi Egipskiej; przetoż przestrzegać będziecie dnia tego w narodziech waszych ustawą wieczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Pierwszego miesiąca, czternastego dnia tegoż miesiąca, na wieczór jeść będziecie przaśniki aż do dnia dwudziestego pierwszego tegoż miesiąca na wieczór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Przez siedem dni kwas niech się nie znajduje w domach waszych; bo ktobykolwiek jadł co kwaszonego, wytracona będzie dusza jego z zgromadzenia Izraelskiego, tak przychodzień, jako i zrodzony w ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nic kwaszonego jeść nie będziecie; we wszystkich mieszkaniach waszych jeść będziecie przaśniki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Wezwał tedy Mojżesz wszystkich starszych Izraelskich, i rzekł do nich: Odłączcie, a weźmijcie sobie baranka według familii swych, a zarznijcie na święto przejścia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Weźmiecie też snopek hysopu, i omoczycie we krwi, która będzie w miednicy, a pokropicie odrzwi, i oba podwoje oną krwią, która będzie w miednicy; a z was nie wynijdzie żaden ze drzwi domu swego aż do poranku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Bo przejdzie Pan zabijając Egipt; a ujrzawszy krew na odrzwiach i na obu podwojach, przestąpi Pan drzwi, i nie dopuści morderzowi, wchodzić do domów waszych zabijać was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'I przestrzegać będziecie tego za ustawę, tobie i synom twoim aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'A gdy wnijdziecie do ziemi, którą wam da Pan, jako obiecał, tych obrzędów przestrzegać będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'A gdy wam rzeką synowie wasi: Co to za obrzędy wasze?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Tedy rzeczecie: Ofiara to przejścia Pańskiego, który przestępował domy synów Izraelskich w Egipcie, gdy zabijał Egipt, a domy nasze wyzwalał. Zatem schylił się lud, i pokłonił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'I poszedłszy uczynili synowie Izraelscy, jako rozkazał Pan Mojżeszowi i Aaronowi, tak uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'I stało się o północy, że Pan zabijał wszystkie pierworodztwa w ziemi Egipskiej, i od pierworodnego Faraonowego, siedzącego na stolicy jego, aż do pierworodnego więźnia, który był w więzieniu, i wszelkie pierworodne z bydląt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Zatem wstał Farao onej nocy, i wszyscy słudzy jego, i wszystek Egipt, i wszczął się wielki krzyk w Egipcie; bo nie było domu, w którym by nie był umarły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'A wezwawszy Farao Mojżesza i Aarona w nocy, rzekł: Wstańcie, wynijdźcie z pośrodku ludu mego, i wy i synowie Izraelscy, a poszedłszy służcie Panu, jakoście mówili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Nadto trzody wasze, i bydła wasze zabierzcie, jakoście żądali, a odchodząc, mnie też błogosławcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'I przynaglali Egipczanie ludowi, aby ich co rychlej wyprawili z ziemi; bo mówili: Pomrzemy wszyscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Wziął tedy lud ciasta swe, pierwej niż zakisiały; a one ciasta swe uwinąwszy w szaty swe, kładli na ramiona swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Tedy synowie Izraelscy uczynili według rozkazania Mojżeszowego, i wypożyczali u Egipczan naczynia srebrnego, i naczynia złotego, i szat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'A Pan dał łaskę ludowi w oczach Egipczanów, że im pożyczali; i złupili Egipt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Ciągnęli tedy synowie Izraelscy z Rameses do Suchotu, około sześć kroć sto tysięcy pieszych mężów tylko, okrom dzieci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Ale i ludu pospolitego wiele szło z nimi, i owiec, i bydła, dobytek bardzo wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'I popiekli z ciasta zadziałanego, które wynieśli z Egiptu, placki przaśne; bo nie było zakwaszone, przeto że wygnani byli z Egiptu, a nie mogli zmieszkać; żywności też sobie byli nie przygotowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'A czasu mieszkania synów Izraelskich, którego mieszkali w Egipcie, było cztery sta lat, i trzydzieści lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'I stało się po czterech set lat i trzydziestu lat, stało się onegoż dnia, wyszły wszystkie wojska Pańskie z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Noc ta obchodzona ma być Panu, że je wywiódł ze ziemi Egipskiej. Ta tedy noc Panu obchodzona ma być od wszystkich synów Izraelskich w narodziech ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'I rzekł Pan do Mojżesza i do Aarona: Ta jest ustawa święta przejścia: Żaden obcy nie będzie jadł z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Przetoż każdego sługę waszego, a za pieniądze kupionego, obrzeżecie go, tedy będzie jadł z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Przychodzień i najemnik nie będzie jadł z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'W domu jednym będzie jedzony; nie wyniesiesz nic z domu z mięsa jego, a kości nie złamiecie w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Wszystko zgromadzenie Izraelskie tak uczyni z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'A jeźliby kto z przychodniów był gościem u ciebie, i chciałby obchodzić święto przejścia Panu, pierwej obrzezany będzie każdy mężczyzna jego, a zatem przystąpi obchodzić je, i będzie jako urodzony w ziemi. A ktobykolwiek nie był obrzezany, nie będzie jadł z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Prawo jedno będzie w ziemi urodzonemu i przychodniowi, który jest gościem między wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Uczynili tedy wszyscy synowie Izraelscy, jako rozkazał Pan Mojżeszowi i Aaronowi, tak uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'I stało się onegoż dnia, wywiódł Pan syny Izraelskie z ziemi Egipskiej z wojski ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'I rzekł Pan do Mojżesza mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Poświęć mi wszelkie pierworodne; cokolwiek otwiera każdy żywot między syny Izraelskimi, tak z ludzi, jako z bydła; bo moje jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Tedy rzekł Mojżesz do ludu: Pamiętajcież na ten dzień, któregoście wyszli z Egiptu, z domu niewoli; bo w możnej ręce wywiódł was Pan stamtąd; a tak nie będziecie jedli kwaszonego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Dziś wy wychodzicie, w miesiącu Abib.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'A gdy się wprowadzi Pan do ziemi Chananejczyka, i Hetejczyka, i Amorejczyka, i Hewejczyka, i Jebuzejczyka, o którą przysiągł ojcom twoim, abyć ją dał, ziemię opływającą mlekiem i miodem, tedy będziesz obchodził tę służbę w tymże miesiącu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Przez siedem dni jeść będziesz przaśniki, a dnia siódmego będzie święto Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Przaśniki jeść będziecie przez siedem dni, i nie ukaże się u ciebie nic kwaszonego, ani widziano będzie kwas we wszystkich granicach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'I opowiesz synowi twemu onegoż dnia, mówiąc: Dla tego, co mi uczynił Pan, gdym wychodził z Egiptu, obchodzę to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'I będziesz to miał za znak na ręce twojej, i na pamiętne przed oczyma twemi, aby Zakon Pański był w uściech twoich, ponieważ ręką możną wywiódł cię Pan z Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'I będziesz strzegł ustawy tej na pewny czas, od roku do roku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'A gdy cię Pan wprowadzi do ziemi Chananejczyka, jako przysiągł tobie i ojcom twoim, i da ją tobie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Tedy odłączysz wszystko, co otwiera żywot, Panu: i każdy płód otwierający żywot z bydła twego, każdy samiec będzie Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Każde zaś pierworodne oślę odkupisz barankiem; a jeźlibyś nie odkupił, tedy złamiesz mu szyję; a każde pierworodne człowieka między synami twoimi odkupisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'A gdyby cię spytał syn twój potem mówiąc: Cóż to jest? Tedy mu odpowiesz: Możną ręką wywiódł nas Pan z Egiptu, z domu niewoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Bo gdy się był zatwardził Farao, nie chcąc nas wypuścić, tedy zabił Pan wszelkie pierworodne w ziemi Egipskiej, od pierworodnego z ludzi aż do pierworodnego z bydła. Dla tegoż ja ofiaruję Panu każdego samca, otwierającego żywot, ale każde pierworodne synów moich odkupuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'I będzie to za znak na ręce twojej, i za naczelniki między oczyma twemi, iż w możnej ręce wywiódł nas Pan z Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'I stało się, gdy wypuścił Farao lud, że nie prowadził ich Bóg drogą ziemi Filistyńskiej, chociaż bliższa była; bo mówił Bóg: By snać nie żałował lud, gdyby ujrzał przeciw sobie wojnę i nie wrócił się do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Ale obwodził Bóg lud drogą pustyni nad morzem czerwonem; i uszykowani wyszli synowie Izraelscy z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Wziął też Mojżesz kości Józefowe z sobą dla tego, że był Józef przysięgą obowiązał syny Izraelskie, mówiąc: Zapewne nawiedzi was Bóg; przetoż wynieście kości moje stąd z sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'I wyciągnąwszy z Suchotu położyli się obozem w Etam, na końcu puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'A Pan szedł przed nimi we dnie w słupie obłoku, aby je prowadził drogą, a w nocy w słupie ognia, aby im świecił, żeby szli we dnie i w nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Nie odejmował słupa obłokowego we dnie, ani słupa ognistego w nocy od ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'I rzekł Pan do Mojżesza mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Mów do synów Izraelskich, niech się wrócą i położą obozem przed Fihahirot między Migdoł, i między morzem, przeciw Baalsefon, przeciw jemu położycie obóz nad morzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Będzie bowiem Farao mówił o synach Izraelskich: Strwożeni są w ziemi, zawarła je puszcza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'I zatwardzę serce Faraonowe, że je gonić będzie; i uwielbiony będę w Faraonie i we wszystkiem wojsku jego; a poznają Egipczanie, żem Ja Pan; i uczynili tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Tedy dano znać królowi Egipskiemu, że lud ucieka; i odmieniło się serce Faraonowe i sług jego przeciw ludowi, i rzekli: Cóżeśmy to uczynili, żeśmy wypuścili Izraela, aby nam nie służył?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Zaprzągł tedy wóz swój, i lud swój wziął z sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Wziął też sześć set wozów wybornych, i wszystkie wozy Egipskie, i przełożone nad tem wszystkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'I zatwardził Pan serce Faraona, króla Egipskiego, i gonił syny Izraelskie; lecz synowie Izraelscy wyszli w ręce możnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'I gonili je Egipczanie, a dogonili je w obozie nad morzem, wszystkie konie, wozy Faraonowe, i jezdne jego, i wojska jego, nie daleko Fihahirot, przeciw Baalsefon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'A gdy Farao następował, tedy podnieśli synowie Izraelscy oczy swe, a oto, Egipczanie ciągną za nimi; i bali się bardzo, i wołali synowie Izraelscy do Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'I mówili do Mojżesza: Azaż nie było grobów w Egipcie? wywiodłeś nas, abyśmy pomarli na puszczy; cóżeś nam to uczynił, żeś nas wywiódł z Egiptu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Azaż nie to jest, cośmy do ciebie mówili w Egipcie, mówiąc: Zaniechaj nas, abyśmy służyli Egipczanom? bo lepiej było nam służyć Egipczanom, niżeli pomrzeć na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'I rzekł Mojżesz do ludu: Nie bójcie się, stójcie, a patrzajcie na wybawienie Pańskie, które wam dziś uczyni; bo Egipczanów, których teraz widzicie, więcej nie oglądacie na wieki');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Pan będzie walczył za was, a wy milczeć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'I rzekł Pan do Mojżesza: Cóż wołasz do mnie? Mów do synów Izraelskich, aby ciągnęli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'A ty podnieś laskę twą, i wyciągnij rękę twoję na morze, i przedziel je; a niech idą synowie Izraelscy środkiem morza po suszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'A oto, Ja, Ja zatwardzę serce Egipczanów, że wnijdą za nimi; a będę uwielbiony w Faraonie, i we wszystkiem wojsku jego, w woziech jego, i w jezdnych jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'I dowiedzą się Egipczanie, żem Ja Pan, gdy uwielbiony będę w Faraonie, w woziech jego, i w jezdnych jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'A ruszywszy się Anioł Boży, który chodził przed obozem Izraelskim, szedł pozad ich; ruszył się też słup obłokowy, który szedł przed nimi, i stanął pozad im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'A przyszedłszy między obóz Egipski, i między obóz Izraelski, był on obłok Egipczanom ciemny a Izraelczykom oświecający noc, tak, iż przystąpić nie mogli jedni do drugich przez całą noc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'I wyciągnął Mojżesz rękę swoję na morze, a Pan rozpędził morze wiatrem wschodnim gwałtownie wiejącym przez całą noc, i osuszył morze; a rozstąpiły się wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'I szli synowie Izraelscy środkiem morza po suszy; a wody im były jako mur. po prawej stronie ich, i po lewej stronie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'A goniąc Egipczanie, weszli za nimi; wszystkie konie Faraonowe, wozy jego, i jezdni jego, w pośrodek morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Stało się tedy około straży zarannej, że wejrzał Pan na obóz Egipski z słupa ognia i obłoku, i pomieszał wojsko Egipskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'I porzucał koła wozów ich, że je wlekli z ciężkością; zaczem rzekli Egipczanie: Uciekajmy przed Izraelem, bo Pan walczy za nimi przeciwko Egipczanom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'I rzekł Pan do Mojżesza: Wyciągnij rękę twoję na morze, że się wrócą wody na Egipczany, na wozy ich, i na jezdne ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'I wyciągnął Mojżesz rękę swoję na morze, i wróciło się morze zaraz z rana do mocy swojej; a Egipczanie uciekali przeciw jemu; lecz Pan wraził Egipczany w pośród morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Wróciwszy się tedy wody, okryły wozy i jezdne, ze wszystkiem wojskiem Faraonowem, które weszło za nimi w morze, tak iż nie zostało z nich i jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Synowie zaś Izraelscy szli po suszy środkiem morza, a wody im były jako mur, po prawej stronie ich, i po lewej stronie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'I wybawił Pan w on dzień Izraela z ręki Egipczanów; i widzieli Izraelczycy Egipczany pomarłe na brzegu morskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Widział też Izrael onę moc wielką, którą uczynił Pan nad Egipczany; a bał się lud Pana, i uwierzyli Panu, i Mojżeszowi, słudze jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Zaśpiewał tedy Mojżesz i synowie Izraelscy tę pieśń Panu, a rzekli mówiąc: Śpiewać będę Panu, iż wielmożnie wywyższon jest; konia i jezdnego jego wrzucił w morze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Moc moja i chwała moja Pan, bo mi się stał zbawieniem; ten jest Bogiem moim, przetoż przybytek wystawię mu; Bóg ojca mego, przetoż wywyższać go będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Pan, mąż waleczny, Pan imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Wozy Faraonowe i wojsko jego wrzucił w morze, a wybrani wodzowie jego potopieni są w morzu czerwonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Przepaści okryły je; poszli w głębią jako kamień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Prawica twoja, Panie, uwielbiona jest w mocy, prawica twoja, Panie, potarła nieprzyjaciela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'A w wielkości Majestatu twego podwróciłeś przeciwniki twoje; puściłeś gniew twój, który je pożarł jako słomę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'A tchnieniem nozdrzy twoich zebrały się wody; stanęły jako kupa ciekące wody, zsiadły się otchłani w pośród morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Mówił nieprzyjaciel: Będę gonił, dogonię; będę dzielił łupy; nasyci się ich dusza moja, dobędę miecza mojego, wygładzi je ręka moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Wionąłeś wiatrem twym, okryło je morze; połknieni są jako ołów w wodach gwałtownych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Któż podobny tobie między bogami, Panie? któż jako ty wielmożny w świątobliwości, straszliwy w chwale, czyniący cuda?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Wyciągnąłeś prawicę twoję, pożarła je ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Prowadzisz w miłosierdziu twojem ten lud, któryś odkupił; poprowadzisz w możności twej do mieszkania świątobliwości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Usłyszą narodowie, zadrżą; boleść zdejmie obywatele Filistyńskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Tedy się polękają książęta Edomskie, mocarze Moabskie strach zdejmie; struchleją wszyscy obywatele Chananejscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Padnie na nie strach i lękanie; od wielkości ramienia twego umilkną jako kamień, aż przejdzie lud twój Panie, aż przejdzie lud ten, któregoś sobie nabył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Wprowadzisz je, i wszczepisz je na górze dziedzictwa twego, na miejscu, któreś ku mieszkaniu twemu sprawił, Panie; w świątnicy, Panie, którą umocnią ręce twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Pan królować będzie na wieki wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Bo weszły konie Faraonowe z wozami jego, i z jezdnymi jego w morze, a obrócił Pan na nie wody morskie; ale synowie Izraelscy szli po suszy środkiem morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Tedy Maryja, prorokini, siostra Aaronowa, wzięła bęben w rękę swoję, a wyszły wszystkie niewiasty za nią z bębnami i muzyką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'I mówiła do nich Maryja: Śpiewajcie Panu, albowiem możnie wywyższon jest; konia i jezdnego jego wrzucił do morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Potem ruszył Mojżesz Izraela od morza czerwonego, i weszli w puszczą Sur; a idąc trzy dni przez puszczą, nie znaleźli wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'A gdy przyszli do Mara, nie mogli pić wód z Mara, bo gorzkie były; dlategoż nazwano imię onego miejsca Mara.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Tedy szemrał lud przeciw Mojżeszowi, mówiąc: Cóż będziemy pić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'I wołał (Mojżesz) do Pana; a ukazał mu Pan drzewo, które gdy wrzucił do wód, stały się słodkie wody. Tam mu ustawił prawa i sądy, i tam go kusił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'I rzekł: Będzieszli pilnie słuchał głosu Pana Boga twego, a co dobrego w oczach jego czynić będziesz, i nakłonisz uszy ku przykazaniom jego, strzegąc wszystkich ustaw jego, żadnej niemocy, którąm dopuścił na Egipt, nie dopuszczę na cię; bom Ja Pan, który cię leczę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'I przyszli do Elim, gdzie było dwanaście źródeł wód, i siedmdziesiąt palm; i położyli się tam obozem nad wodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Ruszyli się potem z Elimu, i przyszło wszystko mnóstwo synów Izraelskich na puszczą Zyn, która leży między Elim i między Synaj, piętnastego dnia miesiąca wtórego po wyjściu ich z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'I szemrało wszystko zgromadzenie synów Izraelskich przeciw Mojżeszowi i przeciw Aaronowi na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'A mówili do nich synowie Izraelscy: Obyśmy byli pomarli od ręki Pańskiej w ziemi Egipskiej, gdyśmy siadali nad garncy mięsa, gdyśmy się najadali chleba do sytości; bo teraz wywiedliście nas na tę puszczą, abyście pomorzyli to wszystko mnóstwo głodem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Tedy rzekł Pan do Mojżesza: Oto, Ja, spuszczę wam, jako deszcz chleb z nieba, i będzie wychodził lud, a będzie zbierał, coby dość było na każdy dzień, abym go doświadczył, będzieli chodził w zakonie moim, czyli nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Ale dnia szóstego nagotują to, co przyniosą, a będzie tyle dwoje niż co zbierać zwykli na każdy dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'I mówił Mojżesz i Aaron do wszystkich synów Izraelskich: W wieczór poznacie, iż Pan wywiódł was z ziemi Egipskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'A rano oglądacie chwałę Pańską; bo usłyszał szemrania wasze przeciw Panu. A my co jesteśmy, iż szemrzecie przeciwko nam?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'I rzekł Mojżesz: Da wam Pan, w wieczór mięso do jedzenia, a chleb rano do nasycenia; bo usłyszał Pan szemrania wasze, któremi szemrzecie przeciw jemu. A my co jesteśmy? Nie przeciwko nam są szemrania wasze, ale przeciwko Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'I rzekł Mojżesz do Aarona: Mów do wszystkiego zgromadzenia synów Izraelskich: Przystąpcie przed obliczność Pańską; bo usłyszał szemranie wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'I stało się, gdy mówił Aaron do wszystkiego zgromadzenia synów Izraelskich, że spojrzeli ku puszczy, a oto, chwała Pańska ukazała się w obłoku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Usłyszałem szemranie synów Izraelskich; rzeczże do nich, mówiąc: Między dwoma wieczorami będziecie jeść mięso, a rano nasyceni będziecie chlebem, i poznacie, żem Ja Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Stało się tedy wieczór, że się zleciały przepiórki, a okryły obóz, a rano rosa leżała około obozu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'A gdy przestała padać rosa, oto, ukazało się na puszczy coś drobnego, okrągłego drobnego jako szron na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Co gdy ujrzeli synowie Izraelscy, mówili jeden do drugiego: Man hu? bo nie wiedzieli, co było. I rzekł Mojżesz do nich: Tenci jest chleb, który wam dał Pan ku jedzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Toć jest, co rozkazał Pan: Zbierajcie z niego każdy, ile trzeba ku jedzeniu, po mierze Gomer na osobę, według liczby dusz waszych; każdy na tych, którzy są w namiocie jego, zbierajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'I uczynili tak synowie Izraelscy, i zbierali jedni więcej, drudzy mniej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'I mierzyli w Gomer, i nie zbywało temu, co więcej nazbierał, ani nie dostawało temu, co mniej; każdy według tego, co mógł zjeść, nazbierał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Mówił też Mojżesz do nich: Żaden niech nie zostawia z niego aż do zarania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Jednak nie usłuchali Mojżesza; ale zostawili z niego niektórzy aż do poranku, i obróciło się w robaki, i zśmierdło się; i rozgniewał się na nie Mojżesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'A zbierali to na każdy dzień rano, każdy według tego, co mógł zjeść; a gdy się zagrzało słońce, tedy ono topniało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'A gdy było dnia szóstego, zbierali chleb w dwójnasób, po dwu Gomer na każdego. I zeszły się wszystkie książęta zgromadzenia, oznajmując to Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Który im rzekł: Toć jest, co mówił Pan: Odpocznienie sabbatu świętego Panu jutro będzie; co macie piec, pieczcie, a co macie warzyć, warzcie, a cokolwiek zbędzie, zostawcie sobie, a zachowajcie do jutra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Zostawiali tedy ono na jutro, jako był rozkazał Mojżesz; a nie zśmierdło się, i robak nie był w niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'I mówił Mojżesz: Jedzcież to dziś, bo dziś sabbat Panu; dziś nie znajdziecie tego na polu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Przez sześć dni zbierać to będziecie, a dnia siódmego sabbat; nie będzie weń manny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'I stało się dnia siódmego, wyszli niektórzy z ludu, aby zbierali; ale nie znaleźli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Tedy rzekł Pan do Mojżesza: I pókiż nie będziecie chcieli przestrzegać przykazań moich i zakonu mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Patrzcie, iż wam Pan dał sabbat, dlatego w dzień szósty daje wam chleb na dwa dni; zostawajcie każdy na miejscu swem, niech nie wychodzi żaden z miejsca swego w dzień siódmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'I odpoczywał lud dnia siódmego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'I nazwał dom Izraelski imię onego pokarmu Man, który był jako nasienie koryjandrowe, biały, a smak jego jako placki z miodem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Mówił też Mojżesz: Tak rozkazał Pan: Napełnij Gomer z niego na chowanie w narodziech waszych, aby widzieli chleb ten, którymem was karmił na puszczy, gdym was wywiódł z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Rzekł zatem Mojżesz do Aarona: Weźmij wiadro jedno, a nasyp w nie pełen Gomer manny, a postaw je przed Panem na chowanie do narodów waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Jako przykazał Pan Mojżeszowi, tak postawił je Aaron przed świadectwem na chowanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'A synowie Izraelscy jedli mannę przez czterdzieści lat, aż przyszli do ziemi mieszkania; mannę jedli, aż przyszli do granic ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'A Gomer jest dziesiąta część miary Efa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Ruszyło się tedy wszystko mnóstwo synów Izraelskich z puszczy Zyn stanowiskami swemi, według rozkazania Pańskiego, i położyli się obozem w Rafidym, gdzie wody nie było, aby pił lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Przetoż swarzył się lud z Mojżeszem, mówiąc: Dajcie nam wody, abyśmy pili. Którym odpowiedział Mojżesz: Cóż się swarzycie ze mną? a czemu kusicie Pana?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'I pragnął tam lud wody, a szemrał przeciwko Mojżeszowi, mówiąc: Po cóżeś nas wywiódł z Egiptu, abyś pomorzył mnie, i syny moje, i bydło moje pragnieniem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Zawołał tedy Mojżesz do Pana, mówiąc: Cóż mam czynić ludowi temu? blisko tego, że mię ukamionują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'I rzekł Pan do Mojżesza: Idź przed ludem, a weźmij z sobą niektóre z starszych Izraelskich; laskę też twoję którąś uderzył w rzekę, weźmij w rękę twoję, a idź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Oto, Ja stanę przed tobą tam na skale w Horeb, i uderzysz w skałę, a wynijdą z niej wody, które będzie pił lud. I uczynił tak Mojżesz przed oczyma starszych Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'I nazwał imię onego miejsca Masa i Meryba, dla swarów synów Izraelskich, a iż kusili Pana mówiąc: I jestże Pan między nami czyli nie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Tedy przyciągnął Amalek, aby walczył z Izraelem w Rafidym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'I rzekł Mojżesz do Jozuego: Wybierz nam męże, a wyszedłszy, stocz bitwę z Amalekity: a jutro stanę na wierzchu pagórka, mając laskę Bożą w ręce mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'I uczynił Jozue, jako mu rozkazał Mojżesz, i stoczył bitwę z Amalekiem; a Mojżesz, Aaron i Chur wstąpili na wierzch pagórka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'A gdy podnosił Mojżesz rękę swoję, przemagał Izrael; a gdy opuszczał rękę swoję, przemagał Amalek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Ale ręce Mojżeszowe ociężały były; wziąwszy tedy kamień, podłożyli podeń, i usiadł na nim; a Aaron, i Chur podpierali ręce jego, jeden z jednej, drugi z drugiej strony; i nie ustały ręce jego aż do zajścia słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Tedy poraził Jozue Amaleka i lud jegoż ostrzem miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Potem rzekł Pan do Mojżesza: Wpisz to dla pamięci w księgi, a włóż to w uszy Jozuego, że pewnie wygładzę pamiątkę Amaleka pod niebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'I zbudował Mojżesz ołtarz, a nazwał imię jego: Pan chorągiew moja;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Bo rzekł: Iż ręka stolicy Pańskiej, i wojna Pańska, będzie przeciwko Amalekowi od rodzaju do rodzaju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'A gdy usłyszał Jetro, kapłan Madyjański, świekier Mojżesza, wszystko, co uczynił Bóg Mojżeszowi, i Izraelowi, ludowi swemu, że wywiódł Pan Izraela z Egiptu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Tedy wziął Jetro, świekier Mojżesza, Zeforę, żonę Mojżeszowę, którą był odesłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'I dwu synów jej, z których imię jednemu Gerson; bo był powiedział Mojżesz: Byłem przychodniem w ziemi cudzej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'A imię drugiego Eliezer; iż mówił: Bóg ojca mego był mi ku pomocy, i wyrwał mię od miecza Faraonowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'I przyszedł Jetro, świekier Mojżesza, z synami jego i z żoną jego do Mojżesza na puszczą, gdzie się był obozem położył przy górze Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'I wskazał do Mojżesza: Ja świekier twój Jetro idę do ciebie, i żona twoja, i jej dwa synowie z nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Zatem Mojżesz wyszedł przeciwko świekrowi swemu, a ukłoniwszy się całował go; i przywitawszy jeden drugiego, potem weszli do namiotu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'I rozpowiadał Mojżesz świekrowi swemu wszystko, co uczynił Pan Faraonowi i Egipczanom za przyczyną Izraela; i wszystkę trudność, która je spotykała w drodze, i jako je Pan wybawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'I radował się Jetro ze wszystkiego dobrego, które uczynił Pan Izraelowi, iż go wyrwał z ręki Egipczanów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'I rzekł Jetro: Błogosławiony Pan, który was wyrwał z ręki Egipczanów i z ręki Faraonowej, który wyrwał lud z niewoli Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Terazem doznał, że większy jest Pan nad wszystkie bogi; albowiem czem oni hardzie powstawali przeciwko niemu, tem poginęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'I wziął Jetro, świekier Mojżesza, całopalenie i ofiary Bogu. Przyszedł też Aaron i wszyscy starsi Izraelscy, aby jedli chleb z świekrem Mojżeszowym przed Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'I stało się nazajutrz, że usiadł Mojżesz, aby sądził lud, i stał lud przed Mojżeszem od poranku aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'A widząc świekier Mojżesza wszystko, co on czynił z ludem, rzekł: Cóż to jest, co ty czynisz z ludem? czemuż ty sam siedzisz, a lud wszystek stoi przed tobą od poranku aż do wieczora?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Tedy Mojżesz odpowiedział świekrowi swemu: Iż przychodzi lud do mnie, aby się radził Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Gdy sprawę jaką mają, przychodzą do mnie, a rozsądzam między nimi, oznajmując ustawy Boże i prawa jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Zatem rzekł świekier Mojżesza do niego: Nie dobra rzecz, którą ty czynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Pewnie ustaniesz, i ty i lud ten, który jest z tobą, bo cięższa to rzecz nad siły twoje; nie będziesz jej mógł ty sam podołać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Przetoż usłuchaj teraz głosu mego, poradzęć, a będzie Bóg z tobą; stój ty za lud przed Bogiem, a odnoś sprawy do Boga;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'A onych też nauczaj ustaw i praw, oznajmując im drogę, którą by chodzić, i dzieło, które by czynić mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Ty też upatrz ze wszystkiego ludu męże stateczne, bojące się Boga, męże prawdomówne, którzy by nienawidzili łakomstwa, a postanów z nich przełożone, tysiączniki, setniki, pięćdziesiątniki i dziesiątniki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Którzy na każdy czas lud sądzić będą; a gdy będzie rzecz wielka, odniosą do ciebie, a każdą rzecz małą sądzić będą sami; tedy ulżysz sobie, gdy poniosą ciężar z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'To jeźli uczynisz, a rozkażeć Bóg, ostoisz się, i ten wszystek lud na miejsca swoje wracać się będzie w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'I usłuchał Mojżesz rady świekra swojego, a uczynił wszystko, jako mu powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'I wybrał Mojżesz męże stateczne ze wszystkiego Izraela, i postanowił je przełożonymi nad ludem, tysiączniki, setniki, pięćdziesiątniki i dziesiątniki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Którzy sądzili lud każdego czasu; trudne rzeczy odnosili do Mojżesza, a każdą rzecz mniejszą sami sądzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Zatem puścił od siebie Mojżesz świekra swego, który odszedł do ziemi swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Miesiąca trzeciego po wyjściu synów Izraelskich z ziemi Egipskiej, w tenże dzień przyszli na puszczą Synaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Bo ruszywszy się z Rafidym, i przyszedłszy aż na puszczą Synaj, położyli się obozem na puszczy, i rozbił tam Izrael namioty przeciw górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'A Mojżesz wstąpił do Boga, i zawołał nań Pan z góry, mówiąc: Tak powiesz domowi Jakóbowemu, i oznajmisz synom Izraelskim:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Wyście widzieli, com uczynił Egipczanom, i jakom was nosił niby na skrzydłach orłowych, i przywiodłem was do siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Przetoż teraz jeźli słuchając posłuszni będziecie głosu memu, i strzec będziecie przymierza mego, będziecie mi własnością nad wszystkie narody; chociaż moja jest wszystka ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'A wy będziecie mi królestwem kapłańskiem, i narodem świętym. Teć są słowa, które mówić będziesz do synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Przyszedłszy tedy Mojżesz zwołał starszych z ludu, i przełożył im wszystkie te słowa, które mu rozkazał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'I odpowiedział wszystek lud, spólnie mówiąc: Wszystko, co Pan rzekł, uczynimy. I odniósł Mojżesz słowa ludu do Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'I rzekł Pan do Mojżesza: Oto, Ja, przyjdę do ciebie w gęstym obłoku, aby słuchał lud, gdy będę mówił z tobą, ażeby też wierzyli tobie na wieki; albowiem opowiedział był Mojżesz słowa ludu onego Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Mówił zaś Pan do Mojżesza: Idź do ludu, a poświęć je dziś i jutro, a niech wypiorą szaty swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'I niech będą gotowi na dzień trzeci; albowiem trzeciego dnia zstąpi Pan przed oczyma wszystkiego ludu na górę Synaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'I zamierzysz granice ludowi w około, mówiąc: Strzeżcie się, abyście nie wstępowali na górę, ani się dotykali brzegu jej; wszelki, kto by się dotknął góry, śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Nie tknie się go ręka, ale kamieniem ukamionują go; albo strzelając zastrzelą go; bądź bydlę, bądź człowiek, nie będzie żył. Gdy przewłocznie trąbić będą, niech wstąpią na górę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Zstąpił tedy Mojżesz z góry do ludu, i poświęcił lud; a uprali szaty swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'I mówił do ludu: Bądźcie gotowi na dzień trzeci, nie przystępujcie do żon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Stało się tedy dnia trzeciego rano, że były grzmienia, i błyskawice, i gęsty obłok nad górą, i głos trąby bardzo potężny; a bał się wszystek lud, który był w obozie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'I wywiódł Mojżesz lud na przeciwko Bogu z obozu, a stanęli pod samą górą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'A góra Synaj kurzyła się wszystka, przeto, iż zstąpił na nią Pan w ogniu; i występował dym z niej, jako dym z pieca, i trzęsła się wszystka góra bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'A gdy się głos trąby im dalej tem bardziej rozlegał, Mojżesz mówił, a Bóg mu odpowiadał głosem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'I zstąpił Pan na górę Synaj, na wierzch góry, i wezwał Pan Mojżesza na wierzch góry, i wstąpił tam Mojżesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Zaczem rzekł Pan do Mojżesza: Zstąp, przestrzeż lud, by snać nie przestąpili kresu, chcąc Pana widzieć, aby ich nie padło wiele:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Nawet i kapłani, którzy przystępują do Pana, niech się poświęcą, by ich snać nie potracił Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'I rzekł Mojżesz do Pana: Nie będzie lud mógł wnijść na górę Synaj, ponieważeś ty nas przestrzegł, mówiąć: Ogranicz górę, a poświęć ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Któremu Pan rzekł: Idź, zstąp, a zaś tu wstąpisz, ty i Aaron z tobą: lecz kapłani i lud niech nie przestępują kresu, aby wstąpili do Pana, by ich snać nie potracił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Tedy zstąpił Mojżesz do ludu i powiedział im to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'I mówił Bóg wszystkie te słowa a rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Jam jest Pan Bóg twój, którym cię wywiódł z ziemi Egipskiej, z domu niewoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Nie będziesz miął bogów innych przede mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Nie czyń sobie obrazu rytego, ani żadnego podobieństwa rzeczy tych, które są na niebie wzgórę, i które na ziemi nisko, i które są w wodach pod ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Nie będziesz się im kłaniał, ani im będziesz służył; bom Ja Pan Bóg twój, Bóg zawistny w miłości, nawiedzający nieprawości ojców nad syny w trzeciem i w czwartem pokoleniu tych, którzy mię nienawidzą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'A czyniący miłosierdzie nad tysiącami tych, którzy mię miłują, i strzegą przykazania mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Nie bierz imienia Pana Boga twego nadaremno; bo się Pan mścić będzie nad tym, który imię jego nadaremno bierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Pamiętaj na dzień odpocznienia, abyś go święcił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sześć dni robić będziesz, i wykonasz wszystkę robotę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Ale dnia siódmego odpocznienie jest Pana Boga twego; nie będziesz czynił żadnej roboty weń, ty i syn twój, i córka twoja, sługa twój, i służebnica twoja, bydlę twoje, i gość twój, który jest w bramach twoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Bo przez sześć dni stworzył Pan niebo i ziemię, morze, i cokolwiek w nich jest, i odpoczął dnia siódmego; przetoż błogosławił Pan dzień odpocznienia, i poświęcił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Czcij ojca twego i matkę twoję, aby przedłużone były dni twoje na ziemi, którą Pan Bóg twój da tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Nie będziesz zabijał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Nie będziesz cudzołożył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Nie będziesz kradł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Nie będziesz mówił przeciw bliźniemu twemu świadectwa fałszywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Nie będziesz pożądał domu bliźniego twego, ani będziesz pożądał żony bliźniego twego, ani sługi jego, ani dziewki jego, ani wołu jego, ani osła jego, ani żadnej rzeczy bliźniego twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Tedy wszystek lud widząc gromy, i błyskawice, i głos trąby, i górę kurzącą się, to widząc lud cofnęli się, i stanęli z daleka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'I mówili do Mojżesza: Mów ty z nami, a będziemy słuchać; a niech nie mówi do nas Bóg, byśmy snać nie pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'I odpowiedział Mojżesz ludowi: Nie bójcie się; bo aby was doświadczył, przyszedł Bóg, żeby bojaźń jego była przed obliczem waszem, byście nie grzeszyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Stał tedy lud z daleka; a Mojżesz przystąpił do ciemnej mgły, w której był Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'I rzekł Pan do Mojżesza: Tak powiesz synom Izraelskim: Wyście widzieli, żem z nieba mówił do was:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Nie będziecie czynić przy mnie bogów srebrnych, ani bogów złotych nie będziecie sobie czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Ołtarz z ziemi uczynisz mi, a ofiarować będziesz na nim całopalenie twoje, i spokojne ofiary twoje, owce twoje, i woły twoje; na któremkolwiek miejscu pamiątkę uczynię imienia mego, przyjdę do ciebie, i będęć błogosławił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'A jeźli ołtarz kamienny uczynisz mi, nie buduj go z ciosanego kamienia; bo jeźlibyś żelazne naczynie twoje podniósł nań, splugawisz go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Nie będziesz wstępował po stopniach do ołtarza mojego, aby nie była odkryta nagość twoja przy nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'A teć są sądy, które przełożysz przed obliczem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Jeźli kupisz niewolnika Hebrejczyka, sześć lat służyć ci będzie, a siódmego wynijdzie wolny darmo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Jeźliby sam tylko przyszedł, sam odejdzie; a jeźliby miał żonę, i żona jego z nim wynijdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Jeźli mu pan jego dał żonę, a zrodziła mu syny albo córki, żona i dzieci jego będą pana jego, a on sam tylko odejdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'A jeźliby mówiąc rzekł niewolnik: Miłuję pana mego, żonę moję, i syny moje, nie wynijdę wolnym:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'Tedy przywiedzie go pan jego do sędziów, a postawi go u drzwi albo u podwoi; i przekole mu pan jego ucho jego szydłem, i będzie mu niewolnikiem na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Zaś jeźliby kto zaprzedał córkę swoję, aby była niewolnicą, nie wynijdzie jako wychodzą niewolnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Jeźliby się nie spodobała w oczach pana swego, a nie poślubiłby jej sobie, niech pozwoli, aby ją odkupiono; obcemu ludowi nie będzie jej mógł sprzedać, ponieważ zgrzeszył przeciwko niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'A jeźliby ją synowi swemu poślubił, według prawa córek uczyni jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Jeźliby też inną wziął mu za żonę, tedy pożywienia jej, odzienia jej, i prawa małżeńskiego nie umniejszy jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'A jeźli tych trzech rzeczy nie uczyni jej, tedy wynijdzie darmo bez okupu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Kto by uderzył człowieka, ażby umarł, śmiercią umrze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Lecz kto by nie czyhał na kogo, aleby go Bóg podał w rękę jego, naznaczęć miejsce, na które będzie miał uciec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Ale jeźliby kto umyślnie przeciw bliźniemu swemu zasadziwszy się zdradą zabił go, i od ołtarza mego weźmiesz go, aby umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Kto by uderzył ojca swego, albo matkę swoję, śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Kto by ukradł człowieka a sprzedałby go, a znaleziony by był w ręku jego, śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Kto by złorzeczył ojcu swemu albo matce swojej, śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'A gdyby się poswarzyli mężowie, i uderzyłby kto bliźniego swego kamieniem albo pięścią, a on by zaraz nie umarł, aleby się położył na łoże;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'A wstawszy chodziłby po ulicy o lasce swej, nie będzie winien ten, który uderzył; tylko omieszkanie jego nagrodzi, a na wyleczenie jego nałoży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Jeźliby zaś uderzył kto niewolnika swego, albo niewolnicę swoję kijem, i umarliby w ręku jego, koniecznie karanie odniesie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Wszakże, jeźliby dzień albo dwa żyw został, nie będzie karany; bo za pieniądze jego on jest kupiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Jeźliby się też powadziwszy mężowie, uderzył który z nich niewiastę brzemienną, tak żeby z niej płód wyszedł, jednakby nie zaszła śmierć koniecznie karanie odniesie, jakie włoży nań mąż onejże niewiasty, a da wedle uznania sędziów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Ale gdzie by śmierć zaszła, tedy dasz duszę za duszę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Oko za oko, ząb za ząb, rękę za rękę, nogę za nogę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Sparzelinę za sparzelinę, ranę za ranę, siność za siność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Jeźliby zaś kto wybił oko niewolnikowi swemu, albo oko niewolnicy swojej, ażby się zepsowało, wolno go puści za oko jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Jeźliby też kto ząb niewolnikowi swemu, albo ząb niewolnicy swojej wybił, wolno go puści za ząb jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Jeźliby też czyj wół ubódł męża albo niewiastę, a umarliby, koniecznie ukamionowany będzie on wół, a nie będą jeść mięsa jego; a pan wołu onego nie będzie winien.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Wszakże, jeźliby wół bódł przedtem, a ostrzeganoby w tym pana jego, i nie miałby go pod strażą, a zabiłby męża albo niewiastę, wół on ukamionowany będzie, nadto i pan jego umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Jeźliby nań włożono, żeby się odkupił, tedy da okup za duszę swoję, jakikolwiek nań włożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Choćby syna ubódł, albo córkę ubódł, podług tegoż sądu postąpią z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Jeźliby niewolnika ubódł wół, albo niewolnicę, srebra trzydzieści syklów da panu jego, a wół on ukamionowany będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Jeźliby kto otworzył studnią, albo jeźliby kto wykopał studnią, i nie nakryłby jej, a wpadłby w nią wół albo osieł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'Pan onej studni odda zapłatę, i nagrodzi panu ich, a co zdechło, jego będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Także, gdyby wół czyj ubódł wołu sąsiada jego, ażby zdechł, tedy sprzedadzą wołu żywego, i rozdzielą się zapłatą jego, onym też zdechłym podzielą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ale jeźliby to było wiadomo, że on wół bódł przedtem, a nie miał go pod strażą pan jego, koniecznie odda wołu za wołu, a zdechłego sobie weźmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Jeźliby kto ukradł wołu albo owcę, i zabiłby je, albo je sprzedał, pięć wołów wróci za jednego wołu, a cztery owce za jedną owcę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Jeźliby przy podkopywaniu zastany był złodziej, a ubity będąc umarłby, kto zabił, nie będzie winien krwi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Jeźliby to po wejściu słońca uczynił, krwi winien będzie, koniecznie wróci; a jeźli nie ma, sprzedany będzie za złodziejstwo swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Jeźli znaleziona będzie w ręku jego rzecz kradziona, bądź wół, bądź osieł, bądź owca, jeszcze żywe, we dwójnasób wróci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Gdyby wypasł kto pole, albo winnicę, i puściłby bydlę swoje, aby się pasło na polu cudzem: z najlepszego urodzaju pola swego, i z najlepszego urodzaju winnicy swej nagrodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Jeźliby wyszedł ogień, a trafiłby na ciernie, i spaliłby stóg, albo stojące zboże, albo pole samo, koniecznie nagrodzi ten, co zapalił, co zgorzało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Gdyby kto dał bliźniemu swemu srebro, albo naczynie do schowania, a to by ukradziono było z domu onego człowieka: jeźliby znaleziony był złodziej, wróci dwojako.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Jeźliby nie był znaleziony złodziej, stawi się pan domu onego przed sędziów, i przysięże, że nie ściągnął ręki swojej na rzecz bliźniego swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'O każdą rzecz, o którą by był spór, o wołu, o osła, o owcę, o szatę, o każdą, rzecz zgubioną, gdyby kto rzekł, że to jest moje, przed sędziów przyjdzie sprawa obydwu; kogo winnym znajdą sędziowie, nagrodzi w dwójnasób bliźniemu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Jeźliby kto dał bliźniemu swemu osła, albo wołu, albo owcę, albo inne bydlę na chowanie, a zdechłoby albo okaleczało, albo gwałtem zajęte było, gdzie by nikt nie widział:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Przysięga Pańska będzie między obiema, że nie ściągnął ręki swej na rzecz bliźniego swego: i przyjmie pan onej rzeczy przysięgę, a on nie będzie nagradzał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'A jeźliby mu to kradzieżą wzięto, nagrodzi panu rzeczy onej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Jeźliby od zwierza rozszarpane było, postawi rozszarpane za świadka, a rozszarpanego nie nagrodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Gdyby też kto pożyczył bydlęcia od bliźniego swego, a okaleczałoby, albo zdechło w niebytności pana jego, koniecznie nagrodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Jeźliby pan jego był przy nim, nie będzie nagradzał; a jeźliby najęte było, najem tylko zapłaci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Jeźliby kto zwiódł pannę, która nie jest poślubiona, i spałby z nią, da jej koniecznie wiano, i weźmie ją sobie za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Jeźliby żadną miarą ojciec jej nie chciał mu jej dać, odważy srebra według zwyczaju wiana panieńskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Czarownicy żyć nie dopuścisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Każdy, kto by się złączał z bydlęciem, śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Kto by ofiarował bogom, oprócz samego Pana, wytracony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Przychodniowi nie uczynisz krzywdy, ani go uciśniesz: boście byli przychodniami w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Żadnej wdowy ani sieroty trapić nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Jeźlibyś je bez litości trapił, a one by wołały do mnie, słysząc wysłucham wołanie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'I rozgniewa się zapalczywość moja, a pobiję was mieczem, i będą żony wasze wdowami, a synowie wasi sierotami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Jeźlibyś pieniędzy pożyczył ludowi memu ubogiemu, który mieszka z tobą, nie bądziesz mu jako lichwiarz, nie obciążycie go lichwą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Jeźli w zastawie weźmiesz szatę bliźniego twego, przed zachodem słońca wrócisz mu ją;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Bo to odzienie jego tylko to jest nakrycie ciała jego, na którem sypia; będzieli do mnie wołał, wysłucham go, bom Ja miłosierny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Sędziom nie będziesz złorzeczył, a przełożonego ludu twego nie będziesz przeklinał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Z obfitości zboża, i ciekących rzeczy twych nie omieszkasz pierwiastek ofiarować; pierworodnego z synów twoich oddasz mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Toż uczynisz z wołów twych i z owiec twoich; siedem dni będzie z matką swoją, a ósmego dnia oddasz mi je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'Ludem świętym będziecie mi, a mięsa na polu rozszarpanego jeść nie będziecie; psom je wyrzucicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Nie przyjmuj powieści kłamliwej; nie miej spółki z niepobożnym, abyś miał być świadkiem fałszywym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Nie udawaj się za wielkością do złego, i nie mów tak za sprawą, cobyś się nakłonił za wielą ich ku podwróceniu sądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'I nie szanuj ubogiego przy sprawie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Gdybyś natrafił wołu nieprzyjaciela twego, albo osła jego błądzącego, zwrócisz, a dowiedziesz go do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Jeźlibyś ujrzał, że osieł tego, który cię ma w nienawiści, leży pod brzemieniem swojem, azali zaniechasz, abyś mu pomóc nie miał? owszem poratujesz go pospołu z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Nie będziesz podwracał sądu ubogiemu twemu w sprawie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Od rzeczy kłamliwej oddalisz się, a niewinnego i sprawiedliwego nie zabijesz; bo nie usprawiedliwię niezbożnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Darów też brać nie będziesz, ponieważ dar zaślepia mądre, i wywraca słowa sprawiedliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Przychodnia też nie uciskaj: bo sami wiecie, jaki jest żywot przychodnia, boście byli przychodniami w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Przez sześć lat obsiewać będziesz ziemię twoję, a będziesz zgromadzał urodzaj jej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Ale siódmego roku zaniechasz jej; że odpocznie, aby jedli ubodzy ludu twego, a co zostanie po nich, zje zwierz polny. Także uczynisz winnicy twojej, i oliwnicy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Przez sześć dni będziesz odprawował roboty twoje; ale dnia siódmego odpoczniesz, aby sobie wytchnął wół twój, osieł twój, i żeby wytchnął syn niewolnicy twojej, i przychodzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'A we wszystkiem, com wam powiedział, ostrożnymi bądźcie. Imienia też cudzych bogów nie wspominajcie, nie będzie słyszane z ust twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Trzy kroć święto obchodzić mi będziecie na każdy rok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Święta przaśników przestrzegać będziesz; siedem dni jeść będziesz przaśniki, jakom ci rozkazał, czasu miesiąca Abiba; boś weń wyszedł z Egiptu, a nie ukażecie się przed twarz moję próżnymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Także święto żniwa pierwiastek pracy twojej, cośkolwiek siał na polu; święto też zbierania na schodzie roku, gdy zbierzesz prace twoje z pola.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Trzykroć do roku ukaże się każdy mężczyzna twój przed obliczem Panującego Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Nie będziesz ofiarował przy kwasie krwi ofiary mojej, ani zostanie przez noc tłustość ofiary mojej aż do poranku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Pierwiastki pierwszych urodzajów ziemi twej przyniesiesz w dom Pana Boga twego; nie będziesz warzył koźlęcia w mleku matki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Oto ja posyłam Anioła przed tobą, aby cię strzegł w drodze, i wprowadził cię na miejsce, którem ci zgotował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Ostrożnym bądź przed oblicznością jego; a słuchaj głosu jego; nie drażnij go, boć nie przepuści przestępstwu waszemu, gdyż imię moje w nim jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Bo jeźli pilnie słuchać będziesz głosu jego, i uczynisz, cokolwiek rzekę, nieprzyjacielem będę nieprzyjaciół twych, i trapić będę tych, którzy cię trapili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Pójdzie bowiem Anioł mój przed tobą, i wprowadzi cię do Amorejczyka, i Hetejczyka, i Ferezejczyka, i Chananejczyka, Hewejczyka, i Jebuzejczyka, i wytracę je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Nie kłaniajże się bogom ich, ani im służ, ani czyń według spraw ich; ale do gruntu popsujesz je, i wszcząt pokruszysz obrazy ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Lecz służyć będziecie Panu Bogu waszemu, a on błogosławić będzie chlebowi twemu, i wodom twoim; i odejmę niemoc z pośrodku ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Nie będzie poroniająca ani niepłodna w ziemi twojej; liczbę dni twoich dopełnię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Strach mój puszczę przed tobą, i strwożę wszelki lud, przeciw któremu pójdziesz, i uczynię, że wszyscy nieprzyjaciele twoi podadzą tył przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Poślę też szerszenie przed tobą, które wypędzą Hewejczyka, Chananejczyka, i Hetejczyka przed oblicznością twoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Nie wyrzucę go przed obliczem twojem za jeden rok, by się snać ziemia w pustynią nie obróciła, a nie namnożyło się przeciwko tobie zwierza dzikiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Pomaluczku będę je wyrzucał od oblicza twego, aż się rozmnożysz i osiądziesz ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'A położę granice twoje od morza czerwonego aż do morza Filistyńskiego, a od puszczy aż do rzeki; bo podam w ręce wasze obywatele ziemi, i wypędzisz je od oblicza twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Nie postanowisz z nimi, ani z bogami ich przymierza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Niech nie mieszkają w ziemi twej, by cię snać nie przywiedli do grzechu przeciwko mnie, gdybyś służył bogom ich, co by tobie było sidłem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'I rzekł do Mojżesza: Wstąp do Pana ty i Aaron, Nadab i Abiu, i siedmdziesiąt starszych Izraelskich, i pokłońcie się z daleka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'A sam tylko Mojżesz wstąpi do Pana; ale oni nie przybliżą się ani lud wstąpi z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Przyszedł tedy Mojżesz, i opowiedział ludowi wszystkie słowa Pańskie, i wszystkie sądy. I odpowiedział wszystek lud głosem jednym, mówiąc: Wszystkie słowa, które rzekł Pan, uczynimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'I napisał Mojżesz wszystkie słowa Pańskie: a wstawszy rano zbudował ołtarz pod górą, i dwanaście słupów według dwanaście pokolenia Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'I posłał młodzieńce z synów Izraelskich, którzy ofiarowali całopalenia; i ofiarowali za ofiary spokojne Panu, cielce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Zatem wziął Mojżesz połowę krwi i wlał w czaszę, a połowę drugą wylał na ołtarz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'I wziąwszy księgi przymierza, czytał w uszach ludu; którzy rzekli: Cokolwiek mówił Pan, uczyńmy, i posłuszni będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Wziął też Mojżesz krew, i pokropił lud i rzekł: Oto, krew przymierza, które Pan postanowił z wami, na wszystkie te słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'I wstąpił Mojżesz, i Aaron, Nadab, i Abiu, i siedemdziesiąt starszych Izraelskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'I widzieli Boga Izraelskiego; a było pod nogami jego jako robota z kamienia szafirowego, a jako niebo gdy jest jasne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'A na książęta synów Izraelskich nie ściągnął Pan ręki swej: choć widzieli Boga, przecię jedli i pili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Rzekł tedy Pan do Mojżesza: Wstąp do mnie na górę, i bądź tam a dam ci tablice kamienne, i zakon, i przykazanie którem napisał, abyś ich nauczał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Wstał tedy Mojżesz i Jozue sługa jego; i wstąpił Mojżesz na górę Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'A do starszych rzekł: Zostańcie tu, aż się wrócimy do was. A oto Aaron i Chur będą z wami; kto by miał sprawę jaką, niech idzie do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Tedy wstąpił Mojżesz na górę, a obłok zakrył górę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'I mieszkała chwała Pańska na górze Synaj, a okrył ją obłok przez sześć dni; potem zawołał na Mojżesza dnia siódmego z pośrodku obłoku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'A pozór chwały Pańskiej był jako ogień pożerający na wierzchu góry przed oczyma synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'I wszedł Mojżesz w pośrodek obłoku, wstąpiwszy na górę; i był Mojżesz na górze czterdzieści dni i czterdzieści nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'I rzekł Pan do Mojżesza mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Mów do synów Izraelskich, aby mi zebrali podarek; od każdego człowieka, którego dobrowolnym uczyni serce jego, odbierać będzie podarek mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'A ten jest podarek, który będziecie brać od nich: złoto, i srebro, i miedź,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'I hijacynt, i szarłat, i karmazyn dwa kroć farbowany; i biały jedwab, i sierść kozią;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'I skóry baranie czerwono farbowane, i skóry borsukowe, i drzewo sytym:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Oliwę do świecenia, wonne rzeczy na olejek pomazywania, i na wonne kadzenie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Kamienne onychiny, i kamienie ku osadzaniu naramiennika i napierśnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'I uczynią mi świątnicę, abym mieszkał w pośrodku ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Według wszystkiego, jako ukażę tobie podobieństwo przybytku, i podobieństwo wszystkiego naczynia jego, tak uczynicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Uczynią też skrzynią z drzewa sytym; półtrzecia łokcia będzie długość jej a półtora łokcia szerokości jej, a półtora łokcia wysokość jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'I powleczesz ją złotem czystem; z wierzchu i wewnątrz powleczesz ją, a uczynisz nad nią koronę złotą w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Ulejesz też do niej cztery kolce złote, które przyprawisz do czterech węgłów jej; dwa kolce do jednego jej boku, i dwa kolce do drugiego jej boku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'I uczynisz drążki z drzewa sytym, i powleczesz je złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'I przewleczesz drążki przez kolce na bokach skrzyni, aby na nich skrzynię noszono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'W kolcach u skrzyni będą te drążki; nie będą ich odejmować od niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'A włożysz w tę skrzynię świadectwo, któreć dam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Uczynisz też ubłagalnię ze złota czystego: półtrzecia łokcia będzie długość jej, a półtora łokcia szerokość jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'I uczynisz dwa Cheruby złote: z ciągnionego złota uczynisz je na obu końcach ubłagalni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'A uczynisz Cheruba jednego na jednym końcu, a Cheruba drugiego na drugim końcu; na ubłagalni uczynicie Cheruby na obu końcach jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'A będą mieć Cherubowie skrzydła rozciągnione z wierzchu, zakrywając skrzydłami swemi ubłagalnię; a twarze ich będą obrócone jednego ku drugiemu; ku ubłagalni będą twarze Cherubów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'I włożysz ubłagalnię na wierzch skrzyni, a do skrzyni włożysz świadectwo, któreć dam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Tam się z tobą schodzić będę, i z tobą rozmawiać z ubłagalni, z pośrodku dwu Cherubów, którzy będą nad skrzynią świadectwa, o wszystkiem, coć rozkażę synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Uczynisz też stół z drzewa sytym: dwa łokcie będzie długość jego, a łokieć szerokość jego, a półtora łokcia wysokość jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'I powleczesz go złotem czystem, a uczynisz mu koronę złotą w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Uczynisz też w około niego listwę w szerz na cztery palce, i koronę złotą w około listwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Także uczynisz do niego cztery kolce złote, i przybijesz kolce na czterech rogach, które są u czterech nóg jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Pod tą listwą będą kolce, przez które przewloką drążki do noszenia stołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'A uczynisz te drążki z drzewa sytym, i powleczesz je złotem, i będzie na nich stół noszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Sprawisz też misy jego, i przystawki jego, i czasze jego, i kubki jego do nalewania ofiar mokrych; ze złota szczerego porobisz je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'I kłaść będziesz na ten stół chleby pokładne przed twarz moję ustawicznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Urobisz też świecznik ze złota szczerego, z ciągnionego złota będzie świecznik ten; słupiec jego, pręty jego, czaszki jego, gałki jego, i kwiaty jego, z tegoż będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'A sześć prętów wychodzić będzie ze stron jego: trzy pręty świecznika ze strony jego jednej, a trzy pręty świecznika ze strony jego drugiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Trzy czaszki na kształt orzecha migdałowego na pręcie jednym, także gałka i kwiat; i trzy czaszki na kształt orzecha migdałowego na pręcie drugim, także gałka i kwiat; tak będzie na wszystkich sześciu prętach, wychodzących ze świecznika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Ale na świeczniku będą cztery czaszki na kształt orzecha migdałowego, gałki jego, i kwiaty jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'I będzie gałka pod dwiema prętami z niego, także gałka pod drugiemi dwiema prętami jego, i zaś gałka pod innemi dwiema prętami jego: tak będzie pod sześćią prętów z świecznika wychodzących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Gałki ich, i pręty ich z niego będą; to wszystko całokowane z szczerego złota będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Uczynisz też siedem lamp jego, i zaświecisz lampy jego, aby świeciły po stronach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Nożyczki też jego, i kaganki jego ze złota szczerego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Z talentu złota szczerego uczynisz go, i wszystko naczynie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Patrzajże, abyś uczynił wszystko według podobieństwa tego, któreć ukazano na górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Przybytek też uczynisz z dziesięciu opon, które będą z białego jedwabiu kręconego, z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i Cherubiny robotą haftarską uczynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Długość opony jednej osiem a dwadzieścia łokci, a szerokość opony jednej cztery łokcie: pod jedną miarą będą wszystkie opony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Pięć opon będą spinane, jedna z drugą; także drugie pięć opon będą spinane, jedna z drugą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'I naczynisz pętlic hijacyntowych na kraju opony jednej, gdzie się kraje spinać mają; także uczynisz na krajach opony drugiej, gdzie się kraje spinać mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Pięćdziesiąt pętlic uczynisz na oponie jednej, a pięćdziesiąt pętlic uczynisz po kraju opony, któremi się spinać ma z drugą; pętlica jedna przeciw drugiej będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Uczynisz też pięćdziesiąt haczyków złotych, a spoisz oponę jednę z drugą temi haczykami; i tak będzie przybytek jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Urobisz też opony z sierści koziej na namiot ku zakrywaniu przybytku z wierzchu; jedenaście takich opon urobisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Długość opony jednej trzydzieści łokci, a szerokość opony jednej cztery łokcie; jednaż miara będzie tych jedenastu opon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'I zepniesz pięć opon osobno, a sześć opon osobno; we dwoje złożysz oponę szóstą na przodku namiotu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Uczynisz też pięćdziesiąt pętlic po kraju jednej opony, na końcu, gdzie się ma spinać, i pięćdziesiąt pętlic po kraju opony ku spinaniu drugiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Uczynisz też haczyków miedzianych pięćdziesiąt, i zawiedziesz haczyki w pętlice, i spoisz namiot, aby był jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'A co zaś zbywa opon namiotowych, to jest pół opony zbywającej, zawieszono będzie w tyle przybytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'A łokieć z jednej, i łokieć z drugiej strony, który zbywa z długości opon namiotu, będzie wisiał po stronach przybytku, tam i sam, żeby go okrywał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Uczynisz też przykrycie na namiot z skór baranich czerwono farbowanych, i przykrycie z skór borsukowych na wierzch.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Naczynisz też do przybytku desek z drzewa sytym prosto stojących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Dziesięć łokci długość deski, a półtora łokcia szerokość deski jednej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Dwa czopy deska jedna mieć będzie, na kształt stopniów wschodowych sporządzone, jeden przeciw drugiemu; tak uczynisz u wszystkich desek przybytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Uczynisz też deski do przybytku, dwadzieścia desek ku stronie południowej, ku wiatrowi południowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Czterdzieści zaś podstawków urobisz srebrnych pod tych dwadzieścia desek; dwa podstawki pod jednę deskę do dwu czopów jej, także dwa podstawki do deski drugiej do dwu czopów jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Na drugim zaś boku przybytku ku stronie północnej, dwadzieścia desek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'A czterdzieści podstawków ich srebrnych; dwa podstawki pod jednę deskę, i dwa podstawki pod drugą deskę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Ale na stronie przybytku ku zachodowi uczynisz sześć desek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'A dwie deski uczynisz w kąciech przybytku w obydwu stronach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Które będą spojone od spodku, także społu spojone będą z wierzchu do jednego kolca; tak będzie przy tych obu, które we dwu kąciech będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'A tak będzie osiem desek, a podstawki ich srebrne; szesnaście podstawków, dwa podstawki pod deską jedną, a dwa podstawki pod deską drugą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Uczynisz też drągi z drzewa sytym; pięć ich będzie do desek jednej strony przybytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'Pięć także drągów do desek przybytku na drugą stronę; pięć też drągów do desek przybytku przestawających do obu węgłów na zachód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Ale drąg pośredni w pośrodku desek przewleczony będzie od jednego końca do drugiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'One też deski powleczesz złotem, a poczynisz do nich kolce złote, przez które mają być przewleczone drągi; powleczesz też i drągi złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Wystawisz tedy przybytek na ten kształt, któryć ukazano na górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Uczynisz też zasłonę z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i z białego jedwabiu kręconego; robotą haftarską uczynisz ją z Cherubiny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'I zawiesisz ją na czterech słupach z drzewa sytym powleczonych złotem, (których też haki złote) na czterech podstawkach srebrnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'A zawiesisz zasłonę na haczykach, i wniesiesz za zasłonę skrzynię świadectwa, a dzielić wam będzie ta zasłona świątnicę od świątnicy najświętszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Położysz też ubłagalnię na skrzyni świadectwa w świątnicy najświętszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'A postawisz stół przed zasłoną, a świecznik przeciw stołowi przy stronie przybytku na południe, a stół postawisz przy stronie północnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Uczynisz też zasłonę do drzwi przybytku z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i z jedwabiu białego kręconego, robotą haftarską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'A uczynisz do tej zasłony pięć słupów z drzewa sytym, które powleczesz złotem; haki ich będą złote, a ulejesz do nich pięć podstawków miedzianych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Uczynisz też ołtarz z drzewa sytym na pięć łokci wzdłuż, a na pięć łokci wszerz; czworograniasty będzie ołtarz, a na trzy łokcie wzwyż.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'I poczynisz mu rogi na czterech węgłach jego; z niego będą rogi jego, i obijesz je miedzią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Poczynisz też do niego kotły dla zsypowania popiołu; i miotły jego, i miednice jego, i widełki jego, i łopaty jego, wszystkie naczynia jego uczynisz z miedzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Uczynisz też do niego kratę, na kształt sieci, miedzianą; a uczynisz u tej kraty cztery kolce miedziane na czterech rogach jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'I włożysz ją w okrąg ołtarza na dół, a będzie ta krata aż do połowy ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Porobisz też drążki do ołtarza, drążki z drzewa sytym, a obijesz je miedzią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Które drążki przewleczone będą przez kolce; a będą te drążki na obydwu stronach ołtarza, gdy go nosić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Aby był czczy wewnątrz, uczynisz go z desek; jakoć ukazano na górze, tak go uczynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Uczynisz też sień przybytku na południe ku prawej stronie; opony tej sieni będą z białego jedwabiu kręconego; na sto łokci wzdłuż będzie strona jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Słupów też do nich dwadzieścia, a podstawków do nich dwadzieścia miedzianych; główki na słupach, i okręcenia ich będą srebrne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Na tenże kształt na stronie północnej wzdłuż opony będą, sto łokci wzdłuż; słupów też do nich dwadzieścia, a podstawków do nich dwadzieścia miedzianych; główki na słupach i okręcenia ich srebrne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'A szerokość sieni od strony zachodniej będzie miała opony na pięćdziesiąt łokci; słupów ich dziesięć, i podstawków ich dziesięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Szerokość zaś sieni na przedniej stronie, na wschód słońca, pięćdziesiąt łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Piętnaście też łokci opon na jednę stronę; słupów ich trzy i podstawków ich trzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Na drugiej zaś stronie opon piętnaście łokci; słupów ich trzy i podstawków ich trzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'A do bramy sieni zasłona na dwadzieścia łokci z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i z jedwabiu białego kręconego robotą haftarską; słupów jej cztery, i podstawków jej cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Wszystkie słupy sieni w około otoczone będą srebrem; główki ich srebrne, a podstawki ich miedziane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Długość sieni na sto łokci, a szerokość na pięćdziesiąt, wszędzie jednostajna; a wysokość na pięć łokci, z białego jedwabiu kręconego, a podstawki jej miedziane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Wszystkie naczynia przybytku do wszelakiej usługi jego, i wszystkie kołki jego, i wszystkie kołki sieni, miedziane będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'A ty rozkażesz synom Izraelskim, aby przynieśli do ciebie oliwy z oliwnego drzewa czystej, wytłoczonej, do świecenia, aby lampy zawsze gorzały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'W przybytku zgromadzenia przed zasłoną, która zakrywa skrzynię świadectwa, stawiać je będzie Aaron i synowie jego od wieczora aż do poranku przed Panem. Ta ustawa będzie wieczna w potomstwie ich między synami Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'A ty weźmij do siebie Aarona, brata twego, i syny jego z nim, z pośrodku synów Izraelskich, aby mi urząd kapłański odprawowali, Aaron, Nadab i Abiu, Eleazar, i Itamar, synowie Aaronowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'A sprawisz szaty święte Aaronowi, bratu twemu, na cześć i na ozdobę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Ty się też rozmówisz z każdym umiejętnym rzemieślnikiem, któregom napełnił Duchem mądrości, aby urobili szaty Aaronowi na poświęcenie jego, aby mi urząd kapłański odprawował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'A teć są szaty, które urobią: Napierśnik, i naramiennik, i płaszcz, i suknia haftowana, czapka i pas. I urobią te szaty święte Aaronowi bratu twemu i synom jego, aby mi kapłański urząd sprawowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'I nabiorą złota, i hijacyntu, i szarłatu, i karmazynu dwa kroć farbowanego, i jedwabiu białego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'I uczynią naramiennik ze złota, i z hijacyntu, i z szarłatu, z karmazynu dwa kroć farbowanego, i z jedwabiu białego kręconego, robotą haftarską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Dwa zwierzchne kraje zszyte mieć będzie na dwu końcach swych, a tak społu spięte będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'A przepasanie naramiennika tego, które na nim będzie, podobne będzie robocie jego; będzie także ze złota, z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i z jedwabiu białego kręconego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'I weźmiesz dwa kamienie onychiny, i wyryjesz na nich imiona synów Izraelskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Sześć imion ich na jednym kamieniu, a imion sześć drugich na drugim kamieniu, według narodzenia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Robotą snycerzów, którzy kamienie rzezą, wyryjesz na obu kamieniach imiona synów Izraelskich, i osadzisz je we złote osadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'I położysz te obadwa kamienie na wierzchnich krajach naramiennika, kamienie pamiątki dla synów Izraelskich; i nosić będzie Aaron imiona ich przed Panem na obu ramionach swych na pamiątkę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Uczynisz też haczyki złote.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Dwa też łańcuszki ze złota szczerego jednostajne; uczynisz je robotą plecioną, i zawiesisz te łańcuszki plecione na haczykach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Uczynisz też napierśnik sądu robotą haftarską, według roboty naramiennika urobisz go; ze złota, z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i z białego jedwabiu kręconego uczynisz go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Czworograniasty będzie i dwoisty, na piędzi długość jego, i na piędzi szerokość jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'I nasadzisz weń pełno kamienia, cztery rzędy kamienia, tym porządkiem: sardyjusz, topazyjusz i szmaragd w pierwszym rzędzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'W drugim zasię rzędzie: karbunkuł, szafir, i jaspis.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'A w trzecim rzędzie: linkuryjusz, achates, i ametyst.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'A w czwartym rzędzie: chryzolit, onychin i berył; te będą wsadzone w złoto w rzędziech swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'A tych kamieni z imionami synów Izraelskich będzie dwanaście według imion ich; tak jako rzezą pieczęci, każdy według imienia swego będą, dla dwunastu pokoleń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Uczynisz też do napierśnika łańcuszki jednostajne robotą plecioną ze złota szczerego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Uczynisz też do napierśnika dwa kolce złote, i przyprawisz te dwa kolce do obu krajów napierśnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'I przewleczesz dwa łańcuszki złote przez oba kolce u krajów napierśnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Drugie zasię dwa kolce dwu łańcuszków zawleczesz na dwa haczyki, i przyprawisz do wierzchnich krajów naramiennika na przodku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Uczynisz też dwa kolce złote, które przyprawisz do dwu końców napierśnika na kraju jego, który jest od naramiennika ze spodku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Do tego uczynisz dwa drugie kolce złote, które przyprawisz na dwie strony naramiennika ze spodku na przeciwko spojeniu jego, z wierzchu nad przepasaniem naramiennika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Tak zwiążą napierśnik ten kolce jego z kolcami naramiennika sznurem hijacyntowym, aby był nad przepasaniem naramiennika, żeby nie odstawał napierśnik od naramiennika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'I będzie nosił Aaron imiona synów Izraelskich na napierśniku sądu, na piersiach swych, gdy będzie wchodził do świątnicy, na pamiątkę ustawiczną przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Położysz też na napierśniku sądu Urim i Tummim, które będą na piersiach Aaronowych, gdy wchodzić będzie przed Pana; i poniesie Aaron sąd synów Izraelskich na piersiach przed Panem ustawicznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Uczynisz też płaszcz pod naramiennik, wszystek z hijacyntu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'A na wierzchu w pośród jego będzie rozpór, który rozpór obwiedziesz bramą plecioną w pancerzowy wzór, aby się nie rozdzierał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Uczynisz też na podołku jego jabłka granatowe z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego na podołku jego w około, a dzwonki złote między niemi w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Dzwonek złoty a jabłko granatowe; i zaś dzwonek złoty i jabłko granatowe u podołka płaszcza w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'A będzie to miał na sobie Aaron przy posługiwaniu, aby słyszany był dźwięk jego, gdy będzie wchodził do świątnicy przed Pana, i gdy zaś wychodzić będzie, żeby nie umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Uczynisz też blachę ze złota szczerego, a wyryjesz na niej robotą tych, co pieczęci rzezą: Świętość Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Tę przywiążesz do sznuru hijacyntowego, i będzie na czapce; na przodku na czapce będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'A ta będzie nad czołem Aaronowem, aby nosił Aaron nieprawość poświęconych rzeczy, które by poświęcali synowie Izraelscy przy wszystkich darach poświęconych rzeczy swych; a będzie nad czołem jego ustawicznie, aby im zjednał łaskę u Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Sprawisz też szatę z białego jedwabiu dzianą; także uczynisz czapkę z jedwabiu białego, pas też uczynisz robotą haftarską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Synom także Aaronowym poczynisz szaty; i poczynisz im pasy, i czapki im poczynisz na cześć i na ozdobę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'A ubierzesz w nie Aarona, brata twego, i syny jego z nim; i pomażesz je, a napełnisz ręce ich, i poświęcisz je, aby mi urząd kapłański sprawowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Urobisz im też ubiory lniane, dla zakrycia nagości ciała; od biódr aż do udów będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'A będą na Aaronie i na synach jego, gdy wchodzić będą do namiotu zgromadzenia, albo gdy będą przystępować do ołtarza, aby służyli w świątnicy, żeby niosąc nieprawość, nie pomarli. Ustawa to wieczna będzie jemu, i nasieniu jego po nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'To też uczynisz im na poświęcenie ich, aby mi odprawowali urząd kapłański: Weźmij cielca jednego młodego, i dwu baranów zupełnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'I chleby przaśne, i placki przaśne z oliwą zaczynione, i kołacze przaśne, namazane oliwą; z przedniej mąki pszenicznej naczynisz ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'A włożysz to w jeden kosz, ofiarować je będziesz w tymże koszu, z cielcem, i z dwiema barany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'A Aaronowi i synom jego przystąpić każesz do drzwi namiotu zgromadzenia, i omyjesz je wodą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'A wziąwszy szaty, obleczesz Aarona w suknią, i w płaszcz pod naramiennik, i w naramiennik, i napierśnik, i opaszesz go pasem naramiennika;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'I włożysz czapkę na głowę jego, a wstawisz koronę świętości na czapkę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Na ostatek weźmiesz olejek pomazywania, i wylejesz na głowę jego, a pomażesz go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Potem synom jego przystąpić każesz, a obleczesz je w szaty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'I opaszesz je pasem, Aarona i syny jego, a włożysz na nie czapki, i będą mieli kapłaństwo ustawą wieczną; poświęcisz też ręce Aaronowe, i ręce synów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Przywiedziesz też cielca przed namiot zgromadzenia, i włoży Aaron i synowie jego ręce swoje na głowę cielca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'I zabijesz cielca przed Panem, u drzwi namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'A wziąwszy krwi z cielca pomażesz na rogach ołtarza palcem swym, a ostatek krwi wylejesz ku spodku ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Weźmiesz też wszystkę tłustość okrywającą wnętrze, i odzieczkę z wątroby, i dwie nerki z tłustością ich, a zapalisz to na ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'A mięso cielca, i skórę jego, i gnój jego, spalisz ogniem za obozem; bo to jest ofiara za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Barana także jednego weźmiesz, na którego głowę Aaron i synowie jego włożą ręce swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'I zabijesz barana tego, a wziąwszy krwi jego, pokropisz wierzch ołtarza w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'A barana zrąbiesz na sztuki, i opłuczesz trzewa jego i nogi jego, i włożysz je na sztuki z niego i na głowę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'I zapalisz tego całego barana na ołtarzu; całopalenie to jest Panu, wonią przyjemną, ofiarą ognistą jest Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Zatem weźmiesz barana drugiego, a włoży Aaron i synowie jego ręce swoje na głowę barana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'A zabiwszy onego barana weźmiesz ze krwi jego, i pomażesz koniec ucha Aaronowego, i końce ucha prawego synów jego, i wielkie palce ręki ich prawej, także wielkie palce nogi ich prawej, a wylejesz tę krew na ołtarz w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Wziąwszy zaś ze krwi, która na ołtarzu, także z olejku pomazywania, pokropisz Aarona, i szaty jego, i szaty synów jego z nim; i będzie poświęcony on i szaty jego, i synowie jego, i szaty synów jego z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Potem weźmiesz z barana łój, i ogon, i tłustość, która okrywa wnętrze, i odzieczkę wątroby, i dwie nerki, i łój, który jest na nich, i łopatkę prawą, albowiem jest baran poświęcenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'I bochen chleba jeden, i kołacz chleba z oliwą jeden, i placek jeden z kosza przaśników, który jest przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'A położysz to wszystko na ręce Aaronowe, i na ręce synów jego, i obracać to będziesz tam i sam za ofiarę obracania przed Panem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'A wziąwszy to z ręku ich, zapalisz na ołtarzu, na całopalenie, na wonność wdzięczną przed Panem; ofiara ognista jest Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Weźmiesz też piersi z barana poświęcenia, które należą Aaronowi, i obracać je będziesz tam i sam za ofiarę obracania przed Panem, a to będzie dział twój,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Poświęcisz też piersi obracania i łopatkę podnoszenia, którą obracano, i którą podnoszono, z barana poświęcenia dla Aarona, i dla synów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'A to będzie Aaronowi i synom jego ustawą wieczną od synów Izraelskich, gdyż ofiara podnoszenia jest: i ofiara podnoszenia będzie od synów Izraelskich z ofiar ich spokojnych, ofiara podnoszenia ich będzie Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'A szaty święte, które są Aaronowe, zostaną synom jego po nim, aby pomazywani byli w nich, a były poświęcane w nich ręce ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Siedem dni będzie w nich chodził kapłan, który będzie na jego miejscu z synów jego, który wchodzić będzie do namiotu zgromadzenia, aby służył w świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Barana też poświęcenia weźmiesz, i uwarzysz mięso jego na miejscu świętem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'I jeść będą Aaron i synowie jego mięso onego barana, i chleb, który jest w koszu, u drzwi namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Będą to jeść ci, za które się oczyszczenie stało, ku poświęceniu rąk ich, aby poświęceni byli; obcy zaś nie będzie jadł z tego, bo święta rzecz jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'A zbyłoliby co mięsa poświęcenia, i chleba aż do poranku, spalisz ostatki ogniem: nie będą tego jeść, bo święta rzecz jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Tak tedy uczynisz Aaronowi, i synom jego, według wszystkiego, com ci przykazał; przez siedem dni poświęcać będziesz ręce ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Cielca też na grzech ofiarować będziesz na każdy dzień na oczyszczenie, i oczyścisz ołtarz, czyniąc oczyszczenie na nim, i pomażesz go ku poświęceniu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Siedem dni będziesz oczyszczał ołtarz, i poświęcisz go, i będzie ten ołtarz najświętszy; cóżkolwiek się dotknie ołtarza, poświęcono będzie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'A to jest, co ofiarować będziesz na ołtarzu: dwa baranki roczne, dwa na każdy dzień ustawicznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Baranka jednego ofiarować będziesz rano, a baranka drugiego ofiarować będziesz między dwoma wieczorami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Także dziesiątą część efy mąki pszennej, zmieszanej z oliwą wytłoczoną, której by było czwarta część hyn, a do ofiary mokrej czwarta część hyn wina do jednego baranka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Także baranka drugiego ofiarować będziesz między dwoma wieczorami; według obrzędu ofiary porannej i według ofiary mokrej jej, tak przy niej uczynisz nad wonią przyjemną, i ofiarę zapaloną Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Całopalenie to ustawicznie będzie w narodziech waszych u drzwi namiotu zgromadzenia przed Panem, gdzie się z wami schodzić będę, abym tam z tobą rozmawiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Tam się też schodzić będę z synami Izraelskimi, i będzie miejsce to chwałą moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Bo poświęcę namiot zgromadzenia, i ołtarz, i Aarona, i syny jego poświęcę, aby mi urząd kapłański sprawowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'I będę mieszkał w pośrodku synów Izraelskich, i będę im za Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'A poznają, żem Ja Pan Bóg ich, którym je wywiódł z ziemi Egipskiej, abym mieszkał w pośrodku ich, Ja Pan Bóg ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Uczynisz też ołtarz dla kadzenia; z drzewa sytym uczynisz go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Na łokieć wzdłuż, i na łokieć wszerz, czworograniasty będzie, a na dwa łokcie wzwyż; z niego wychodzić będą rogi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'A powleczesz go szczerem złotem, wierzch jego i ściany jego w około, i rogi jego. Uczynisz też koronę złotą około niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'I dwa kolce złote uczynisz też pod koroną we dwu kątach jego, po obu stronach jego, a przez nie przewleczesz drążki, aby noszony był na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'A uczynisz drążki one z drzewa sytym, i powleczesz je złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'I postawisz go przed zasłoną, za którą jest skrzynia świadectwa przed ubłagalnią, która jest nad świadectwem, gdzie się z tobą schodzić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'A będzie kadził na nim Aaron kadzeniem z wonnych rzeczy na każdy poranek; przygotowawszy lampy, będzie kadził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Także gdy rozpali Aaron lampy między dwoma wieczorami, kadzić będzie kadzeniem ustawicznem przed Panem w narodziech waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Nie włożycie nań kadzidła obcego, ani całopalenia, ani ofiary suchej; ani ofiary mokrej ofiarować będziecie na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Tylko wykona oczyszczenie Aaron nad rogami jego raz w rok; przez krew ofiary za grzech, w dzień oczyszczenia, raz w rok oczyszczenie odprawi na nim w narodziech waszych; bo to rzecz najświętsza Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Gdy zbierzesz główną sumę synów Izraelskich, z tych, którzy mają iść w liczbę, da każdy okup za duszę swą Panu, gdy je liczyć będziesz, aby nie przyszła na nie plaga, gdy zliczeni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'To dawać będą: każdy, który idzie w liczbę, da pół sykla według sykla świątnicy dwadzieścia pieniędzy sykiel waży; pół sykla będzie podarek Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Ktokolwiek idzie w liczbę ode dwudziestu lat i wyżej, odda podarek Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Bogaty nie da więcej, a ubogi nie da mniej nad pół sykla, gdy będą dawać ofiarę Panu, dla oczyszczenia dusz swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'A wybrawszy pieniądze oczyszczenia od synów Izraelskich, dasz je na potrzeby namiotu zgromadzenia, co będzie synom Izraelskim na pamiątkę przed Panem, ku oczyszczeniu dusz waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Uczynisz też wannę miedzianą, i stolec jej miedziany do umywania, a postawisz ją między namiotem zgromadzenia, i między ołtarzem, i nalejesz w nią wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'I umywać będą Aaron i synowie jego z niej ręce swoje i nogi swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Gdy wchodzić będą do namiotu zgromadzenia, umywać się będą wodą, aby nie pomarli; także gdyby mieli przystępować do ołtarza, aby służyli, i zapalili ofiarę ognistą Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'I będą umywali ręce swoje i nogi swoje, aby nie pomarli; i będzie im to ustawą wieczną, jemu i nasieniu jego, w rodzaju ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Rzekł jeszcze Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Ty też weźmij sobie wonnych rzeczy przednich: Myrry co najczystszej pięćset łutów, a cynamonu wonnego połowę tego, to jest, dwieście i pięćdziesiąt łutów, i tatarskiego ziela dwieście i pięćdziesiąt;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Kasyi też pięćset łutów według sykla świątnicy, i oliwy z drzew oliwnych hyn.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'I uczynisz z tego olejek pomazywania świętego, maść najwyborniejszą, robotą aptekarską: olejek to pomazywania świętego będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'I pomażesz nim namiot zgromadzenia, i skrzynię świadectwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'Także stół i wszystkie naczynia jego, i świecznik, i naczynia jego, i ołtarz, na którym kadzą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Ołtarz też do całopalenia ze wszystkiem naczyniem jego, i wannę z stolcem jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'A poświęcisz je, aby najświętsze były; cokolwiek się ich dotknie, poświęcone będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Aarona też, i syny jego pomażesz, i poświęcisz je, aby mi sprawowali urząd kapłański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'A synom Izraelskim tak powiesz, mówiąc: Olejek pomazywania świętego mnie będzie świętym w narodziech waszych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Ciało człowiecze nie będzie nim mazane, a według złożenia jego nie uczynicie temu podobnego: bo święty jest, i święty wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Ktobykolwiek uczynił taką maść, a namazałby nią kogo obcego, wytracony będzie z ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'I rzekł Pan do Mojżesza: Weźmij sobie rzeczy wonnych, balsamu, i onychy, i galbanu wonnego, i kadzidła czystego, wszystkiego w równej wadze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'A uczynisz z tego kadzenia wonne robotą aptekarską; to zmieszanie czyste i święte będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'A utłukłszy to miałko, kłaść będziesz z niego przed świadectwem w namiocie zgromadzenia, gdzie się z tobą schodzić będę; najświętsze to będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Kadzenia też, które byś czynił według złożenia tego, nie uczynicie sobie; toć będzie świętą rzeczą dla Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Ktobykolwiek uczynił co podobnego, aby woniał z niego, wytracony będzie z ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Otom wezwał z imienia Besaleela, syna Urowego, syna Churowego z pokolenia Judy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'I napełniłem go Duchem Bożym, mądrością, i rozumem, i umiejętnością we wszelakiem rzemiośle.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Ku dowcipnemu wymyślaniu, cokolwiek może być urobione ze złota, i z srebra, i z miedzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Do rzezania kamienia na osadzenie, i na wyrobienie drzewa ku wystawieniu każdej roboty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'A oto, Ja przydałem mu Acholijaba, syna Achysamechowego z pokolenia Dan, a w serce każdego dowcipnego dałem mądrość, aby zrobili wszystko com ci przykazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Namiot zgromadzenia, i skrzynię świadectwa, i ubłagalnią, która ma być nad nią, i wszystkie naczynia namiotu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Stół także i naczynia jego, i świecznik czysty ze wszystkiem naczyniem jego, i ołtarz do kadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Także ołtarz do całopalenia ze wszystkiem naczyniem jego, i wannę ze stolcem jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'Także szaty do służby, i szaty święte Aaronowi kapłanowi, i szaty synom jego ku sprawowaniu kapłaństwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'I olejek pomazywania, i kadzenie wonne do świątnicy; według wszystkiego, jakom ci rozkazał, uczynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Ty też powiedz synom Izraelskim, mówiąc: Przecię sabbatów moich przestrzegać będziecie; bo ten znak jest między mną i między wami w narodziech waszych, abyście wiedzieli, żem Ja Pan, który was poświęcam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Przetoż przestrzegajcie sabbatu, święty bowiem jest wam. Kto by go zgwałcił, śmiercią umrze; bo każdy, coby weń robotę odprawował, wytracona będzie dusza jego, z pośrodku ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Przez sześć dni odprawowana będzie robota; ale w dzień siódmy sabbat jest, odpocznienie święte Panu; każdy, kto by robił robotę w dzień sabbatu, śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Przetoż będą strzec synowie Izraelscy sabbatu, zachowując sabbat w narodziech swych ustawą wieczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Między mną i między syny Izraelskimi znakiem jest wiecznym; bo w sześciu dniach uczynił Pan niebo i ziemię, a dnia siódmego przestał i odpoczął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'I dał Pan Mojżeszowi dokonawszy mowy z nim na górze Synaj dwie tablice świadectwa, tablice kamienne, pisane palcem Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'A widząc lud, iż omieszkiwał Mojżesz zejść z góry, tedy zebrał się lud przeciw Aaronowi, i mówili do niego: Wstań, uczyń nam bogi, którzy by szli przed nami; bo Mojżeszowi, mężowi temu, który nas wywiódł z ziemi Egipskiej, nie wiemy co się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Tedy im rzekł Aaron: Odejmijcie nausznice złote, które są na uszach żon waszych, synów waszych, i córek waszych, a przynieście do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'I poodrywał wszystek lud nausznice złote, które były na uszach ich, a przynieśli do Aarona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Które gdy odebrał z ręku ich, wykształtował je rylcem i uczynił z nich cielca odlewanego. I rzekli: Ci są bogowie twoi, Izraelu, którzy cię wywiedli z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Co ujrzawszy Aaron, zbudował ołtarz przed nim; a wołając Aaron mówił: Święto Pańskie jutro będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'A wstawszy bardzo rano nazajutrz, ofiarowali całopalenia, i przywiedli ofiary spokojne; i siadł lud, aby jadł i pił, i wstali grać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Tedy rzekł Pan do Mojżesza: Idź zstąp; bo się popsował lud twój, któryś wywiódł z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Ustąpili prędko z drogi, którąm im przykazał; uczynili sobie cielca odlewanego, i kłaniali się mu, i ofiarowali mu mówiąc: Ci są bogowie twoi, Izraelu, którzy cię wywiedli z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Rzekł zasię Pan do Mojżesza: Widziałem lud ten, a oto, jest lud twardego karku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Przetoż teraz puść mię, że się rozpali popędliwość moja na nie i wygładzę je; a ciebie uczynię w naród wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'I modlił się Mojżesz Panu Bogu swemu, a rzekł: Przeczże o Panie, rozpala się popędliwość twoja przeciwko ludowi twemu, któryś wywiódł z ziemi Egipskiej mocą wielką i ręką możną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'A przeczżeby Egipczanie rzec mieli, mówiąc: Na ich złe wywiódł je, aby je pobił na górach, i aby je wygładził z wierzchu ziemi? Odwróć się od gniewu zapalczywości twojej, a ulituj się nad złem ludu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Wspomnij na Abrahama, Izaaka, i Izraela, sługi twoje, którymeś przysiągł sam przez się i mówiłeś do nich: Rozmnożę nasienie wasze jako gwiazdy niebieskie, i wszystkę tę ziemię, o którejm mówił. Dam ją nasieniu waszemu, i odziedziczą ją na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'I użalił się Pan nad złem, które mówił, że uczynić miał ludowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'A obróciwszy się Mojżesz zstąpił z góry, dwie tablice świadectwa mając w ręku swych, tablice pisane po obu stronach; i na tej, i na owej stronie były pisane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'A one tablice robotą Bożą były; pismo także pismo Boże było, wyryte na tablicach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'A usłyszawszy Jozue głos ludu wołającego, rzekł do Mojżesza: Głos bitwy w obozie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Który odpowiedział: Nie jest to głos zwyciężających, ani głos porażonych: głos śpiewających ja słyszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'I stało się, gdy się przybliżył do obozu, że ujrzał cielca i tańce; a rozgniewawszy się bardzo Mojżesz, porzucił z ręku swoich tablice, i stłukł je pod górą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Wziął też cielca, którego byli uczynili, i spalił go w ogniu, i skruszył go aż na proch, a wysypawszy na wodę, dał pić synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'I rzekł Mojżesz do Aarona: Cóż ci ten lud uczynił, żeś wprowadził nań grzech wielki?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Odpowiedział Aaron: Niech się nie rozpala gniew pana mego; ty znasz ten lud, jako do złego skłonny jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Bo mi mówili: Uczyń nam bogi, którzy by szli przed nami, gdyż Mojżeszowi, mężowi temu, który nas wywiódł z ziemi Egipskiej, nie wiemy, co się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'I odpowiedziałem im: Kto ma złoto, odrywajcie je z siebie. I dali mi, i wrzuciłem je w ogień, i ulał się ten cielec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Widząc tedy Mojżesz lud obnażony, (bo go był złupił Aaron na zelżenie przed nieprzyjaciołmi ich).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Stanął Mojżesz w bramie obozu, i rzekł: Kto Pański, przystąp do mnie. I zebrali się do niego wszyscy synowie Lewiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'I rzekł do nich: Tak mówi Pan, Bóg Izraelski: Przypasz każdy miecz swój do biodry swojej; przychodźcie a wracajcie się od bramy do bramy w obozie, a zabijajcie każdy brata swego, i każdy przyjaciela swego, i każdy bliźniego swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'I uczynili synowie Lewiego według słowa Mojżeszowego; i poległo z ludu dnia onego około trzech tysięcy mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Bo był rzekł Mojżesz: Poświęćcie ręce swoje dziś Panu, każdy na synu swym, i na bratu swym, aby wam dane było dziś błogosławieństwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'A gdy było nazajutrz, mówił Mojżesz do ludu: Wyście zgrzeszyli grzechem wielkim; przetoż teraz wstąpię do Pana, aza go ubłagam za grzech wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Wróciwszy się tedy Mojżesz do Pana, mówił: Proszę, zgrzeszył ten lud grzechem wielkim; bo sobie uczynili bogi złote.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Teraz tedy, albo odpuść grzech ich, albo jeźli nie, wymaż mię proszę z ksiąg twoich, któreś napisał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'I rzekł Pan do Mojżesza: Kto mi zgrzeszył, tego wymażę z ksiąg moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'A teraz idź, prowadź ten lud, gdziem ci rozkazał. Oto, Anioł mój pójdzie przed tobą; ale w dzień nawiedzenia mego nawiedzę też i na nich ten grzech ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Skarał tedy Pan lud, przeto, że uczynili byli cielca, którego był uczynił Aaron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Potem mówił Pan do Mojżesza: Idź, rusz się stąd, ty i lud, któryś wywiódł z ziemi Egipskiej, do ziemi, o którąm przysiągł Abrahamowi, Izaakowi i Jakóbowi, mówiąc: Nasieniu twemu dam ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'I poślę przed tobą Anioła, i wyrzucę Chananejczyka, Amorejczyka, i Hetejczyka, i Ferezejczyka, Hewejczyka, i Jebuzejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'Do ziemi opływającej mlekiem i miodem; lecz sam nie pójdę z tobą, gdyżeś jest lud karku twardego, bym cię snać nie wytracił w drodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'A usłyszawszy lud tę rzecz złą, zasmucił się, i nie włożył żaden ochędóstwa swego na się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Albowiem rzekł Pan do Mojżesza: Powiedz synom Izraelskim: Wyście ludem twardego karku; przyjdę kiedy z nagła w pośród ciebie, i wygładzę cię. Przetoż teraz złóż ochędóstwo twoje z siebie, a będę wiedział, coć bym uczynić miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'I złożyli synowie Izraelscy ochędóstwo swoje przy górze Horeb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'A Mojżesz wziąwszy namiot, rozbił go sobie za obozem, opodal od obozu, i nazwał go namiotem zgromadzenia. Tedy każdy, który chciał o co pytać Pana, wychodził do namiotu zgromadzenia, który był za obozem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'A gdy wychodził Mojżesz do namiotu, powstawał wszystek lud, i stał każdy we drzwiach namiotu swego; i patrzali za Mojżeszem, aż wszedł do namiotu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'I bywało to, że gdy wchadzał Mojżesz do namiotu, zstępował słup obłokowy, a stawał u drzwi namiotu, i mawiał Bóg z Mojżeszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'A widząc wszystek lud słup obłokowy, stojący u drzwi namiotu, powstawał wszystek lud i kłaniał się każdy u drzwi namiotu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'I mawiał Pan do Mojżesza twarzą w twarz, jako mawia człowiek do przyjaciela swego; potem wracał się do obozu, a sługa jego Jozue, syn Nunów, młodzieniec, nie odchodził z pośrodku namiotu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Tedy mówił Mojżesz do Pana: Wej, ty mi mówisz: Prowadź lud ten, a tyś mi nie oznajmił, kogo poślesz ze mną? Nad to powiedziałeś: Znam cię z imienia, znalazłeś też łaskę w oczach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Teraz tedy, jeźlim znalazł łaskę w oczach twoich, ukaż mi proszę drogę twoję, żebym cię poznał, i żebym znalazł łaskę w oczach twoich, a obacz, że ludem twoim jest naród ten.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'I odpowiedział Pan: Oblicze moje pójdzie przed tobą, a dam ci odpocznienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'I rzekł Mojżesz do niego: Nie pójdzieli oblicze twoje z nami, nie wywódź nas stąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Albowiem po czemże tu znać będzie, żem znalazł łaskę w oczach twoich, ja i lud twój? izali nie po tem, gdy pójdziesz z nami? bo tak oddzieleni będziemy, ja i lud twój, od każdego ludu, który jest na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'I rzekł Pan do Mojżesza: I tę rzecz, o którąś mówił, uczynię; boś znalazł łaskę w oczach moich, i znam cię z imienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Nad to rzekł Mojżesz: Ukaż mi proszę, chwałę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'A on odpowiedział: Ja sprawię, że przejdzie wszystko dobre moje przed twarzą twoją, i zawołam z imienia: Pan przed twarzą twoją; zmiłuję się, nad kim się zmiłuję; a zlituję się, nad kim się zlituję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'I rzekł: Nie będziesz mógł widzieć oblicza mego; bo nie ujrzy mię człowiek, aby żyw został.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'I rzekł Pan: Oto, miejsce u mnie, a staniesz na opoce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'A gdy przechodzić będzie chwała moja, tedy cię postawię w rozpadlinie opoki, i zakryję cię dłonią moją, póki nie przejdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Potem odejmę dłoń moję, i ujrzysz tył mój; ale twarz moja nie będzie widziana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'I rzekł Pan do Mojżesza: Wyciesz sobie dwie tablice kamienne, podobne pierwszym, a napiszę na tychże tablicach słowa, które były na tablicach pierwszych, któreś stłukł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'A bądź gotów rano, że wstąpisz jutro na górę Synaj, i staniesz przede mną na wierzchu tej góry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Ale żaden niech nie wstępuje z tobą, a nikt też niech nie będzie widziany po wszystkiej górze; ani owce, ani woły, niech się nie pasą przeciwko tej górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Tedy wyciosał Mojżesz dwie tablice kamienne, podobne pierwszym; i wstawszy rano, wstąpił na górę Synaj, jako mu rozkazał Pan, wziąwszy w ręce swe dwie tablice kamienne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'I zstąpił Pan w obłoku, i stanął tam z nim, i zawołał imieniem Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Bo przechodząc Pan przed twarzą jego, wołał: Pan, Pan, Bóg miłosierny i litościwy, nie rychły do gniewu, a obfity w miłosierdziu i w prawdzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Zachowujący miłosierdzie nad tysiącami, gładzący nieprawość i przestępstwo i grzech, nie usprawiedliwiający winnego, nawiedzając nieprawość ojcowską w synach i w synach synów ich do trzeciego i do czwartego pokolenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Pospieszywszy się tedy Mojżesz nachylił się ku ziemi i pokłonił się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'I rzekł; Jeźlim teraz znalazł łaskę w oczach twoich, Panie, niech idzie proszę Pan w pośrodku nas, lud bowiem ten twardego karku jest, a odpuść nieprawości nasze, i grzech nasz, a miej nas za dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Który odpowiedział: Oto, Ja postanowię przymierze; przed wszystkim ludem twoim czynić będę cuda, które nie były czynione po wszystkiej ziemi i we wszystkich narodziech; i obaczy wszystek lud, między którymeś ty, sprawę Pańską; bo straszne będzie to, co Ja uczynię z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Strzeżże tego, co Ja rozkazuję tobie: Oto, Ja wypędzę przed obliczem twojem Amorejczyka, i Chananejczyka, i Hetejczyka, i Ferezejczyka, i Hewejczyka, i Jebuzejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Strzeżże się, abyś snać nie stanowił przymierza z obywatelami ziemi onej, do której ty wnijdziesz, żebyć to nie było sidłem pośrodku ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Przetoż ołtarze ich zburzycie, bałwany ich połamiecie, i gaje ich święcone wyrąbiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Nie będziesz się kłaniał bogu innemu, przeto że Pan jest, zawistny imię jego, Bóg zawistny jest;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'By snać, uczyniwszy przymierze z obywatelami tej ziemi, gdyby oni cudzołożyli z bogami swymi, i ofiarowali bogom swym, ciebie nie wezwali, a jadłbyś z ofiar ich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'I brałbyś z córek ich żony synom swym, i cudzołożyłyby córki ich z bogi swymi, a przywiodłyby syny twoje do wszeteczeństwa z bogi swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Bogów odlewanych nie czyń sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Święto przaśników zachowywać będziesz; przez siedem dni jeść będziesz przaśniki, jakom ci rozkazał, czasu miesiąca Abib; albowiem tegoż miesiąca Abib wyszedłeś z Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Wszystko, co otwiera żywot, moje jest; i wszystko z dobytku twego cokolwiek samcem jest, pierworodne i z owiec, i z wołów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Ale pierworodne oślę odkupisz owcą; a jeźlibyś go nie odkupił, złamiesz mu szyję. Każdego pierworodnego z synów twych odkupisz, i nie ukażą się przed twarz moję próżni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sześć dni robić będziesz, a dnia siódmego odpoczniesz; czasu orania i czasu żniwa odpoczniesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Święto Tygodni uczynisz też sobie, w pierwiastki żniwa pszenicznego, i święto zbierania na skończeniu roku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Trzy kroć do roku ukaże się każdy mężczyzna twój przed obliczem Panującego Pana, Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Albowiem wypędzę narody przed tobą, a rozszerzę granice twoje; i nie będzie pożądał nikt ziemi twojej, gdy pójdziesz, abyś się ukazał przed obliczem Pana Boga twego trzy kroć do roku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Nie będziesz ofiarował przy kwasie krwi ofiary mojej, i nie zostanie nic do jutra z ofiary obchodu święta przejścia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Pierwiastki pierwszych urodzajów ziemi twej przyniesiesz w dom Pana Boga twego. Nie będziesz warzył koźlęcia w mleku matki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Zatem rzekł Pan do Mojżesza: Napisz sobie te słowa, bo według słów tych postanowiłem z tobą przymierze, i z Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'I był tam z Panem czterdzieści dni i czterdzieści nocy; chleba nie jadł, i wody nie pił; i napisał Pan na tablicach słowa przymierza, dziesięć słów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'I stało się, gdy zstępował Mojżesz z góry Synaj, a dwie tablice świadectwa miał w ręku Mojżesz, gdy zstępował z góry, że nie wiedział Mojżesz, iżby się lśniła skóra twarzy jego, gdy Pan mówił z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'I ujrzeli Aaron, i wszyscy synowie Izraelscy Mojżesza, a oto lśniła się skóra twarzy jego, i bali się przystąpić do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Ale zawołał na nich Mojżesz, i nawrócili się ku niemu Aaron, i wszystkie książęta zgromadzenia, i mówił Mojżesz do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Potem też przyszli wszyscy synowie Izraelscy, którym przykazał wszystko, co mówił Pan z nim na górze SYnaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'A póki Mojżesz mówił z nimi, miewał na twarzy swojej zasłonę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Ale gdy wchadzał Mojżesz przed twarz Pańską, aby rozmawiał z nim, odejmował zasłonę, póki nie wyszedł; a wyszedłszy, mówił do synów Izraelskich, co mu było rozkazano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Widzieli tedy synowie Izraelscy twarz Mojżeszową, że się lśniła skóra twarzy Mojżeszowej; i kładł zaś Mojżesz zasłonę na twarz swoję, póki nie wszedł aby mówił z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Potem zebrał Mojżesz wszystko zgromadzenie synów Izraelskich, i mówił do nich: Te są rzeczy, które rozkazał Pan, abyście je czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Przez sześć dni odprawowana będzie robota; ale dzień siódmy będzie wam święty, sabbat odpocznienia Pańskiego; kto by weń robił robotę, umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Nie rozniecicie ognia we wszystkich mieszkaniach waszych w dzień sabbatu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Rzekł też Mojżesz do wszystkiego zgromadzenia synów Izraelskich, mówiąc: Tać jest rzecz, którą przykazał Pan mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Złóżcie od siebie podarek Panu: każdy, kto jest ochotnego serca, przyniesie ten podarek Panu, złoto, i srebro, i miedź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'I hijacynt, i szarłat, i karmazyn dwa kroć farbowany, i biały jedwab, i sierść kozią;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Skóry też baranie czerwono farbowane i skóry borsukowe, i drzewo sytym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'I oliwę do świecenia, i rzeczy wonne na olejek pomazywania, i dla kadzenia wonnego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Kamienie też onychiny, i kamienie do osadzania naramiennika i napierśnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'A wszyscy dowcipnego serca między wami przyjdą, i robić będą, cokolwiek rozkazał Pan:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Przybytek, namiot jego, i przykrycie jego, haczyki jego, i deski jego, drągi jego, słupy jego, i podstawki jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'Skrzynie i drążki jej, ubłagalnią, i oponę do zasłony,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'Stół i drążki jego, ze wszystkiem naczyniem jego, i chleby pokładne;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'I świecznik do świecenia z naczyniem jego, i lampy jego, i oliwę do świecenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'Ołtarz także do kadzenia z drążkami jego, i olejek pomazywania, i kadzenia wonne, i zasłonę do drzwi przybytku;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'Ołtarz do całopalenia, i kratę jego miedzianą, drążki jego, i wszystkie naczynia jego, wannę z stolcem jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Opony do sieni, słupy jej, i podstawki jej, i zasłony do drzwi u sieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Kołki do przybytku i kołki do sieni z sznurami jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Szaty służebne do usługiwania w świątnicy, szaty święte Aaronowi kapłanowi, i szaty synom jego, dla sprawowania urzędu kapłańskiego');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Wyszło tedy wszystko zgromadzenie synów Izraelskich od obliczności Mojżeszowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'I przyszedł każdy mąż, którego pobudziło serce jego, i każdy, w którym dobrowolny był duch jego, przynieśli podarek Panu do robienia namiotu zgromadzenia, i do wszelkiej potrzeby jego, i na szaty święte.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Przychodzili tedy mężowie z niewiastami, każdy, kto był ochotnego serca, przynosili zapony, i nausznice, i pierścienie, i manele, i wszelakie naczynia złote, i ktokolwiek przynosił ofiarę złotą Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Każdy też co miał hijacynt, i szarłat, i karmazyn dwa kroć farbowany, i biały jedwab, i sierść kozią, i skóry baranie czerwono farbowane, i skóry borsukowe, przynosili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Ktokolwiek ofiarował podarek srebra i miedzi, przynosili na ofiarę Panu, każdy też, co miał drzewo sytym, na wszelaką potrzebę ku usłudze przynosili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'I wszystkie niewiasty dowcipnego serca rękami swemi przędły, a przynosiły co naprzędły, hijacynt, i szarłat, karmazyn dwa kroć farbowany, i biały jedwab.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'A wszystkie niewiasty których pobudziło serce ich umiejętne, przędły sierść kozią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Przełożeni zasię przynosili kamienie onychiny, i kamienie do osadzania naramiennika i napierśnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Także rzeczy wonne i oliwę do świecenia, i na olejek pomazywania i na wonne kadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Każdy mąż i niewiasta, w których ochotne serce było do ofiarowania, na każdą robotę, którą rozkazał Pan czynić przez Mojżesza, przynosili synowie Izraelscy ofiarę dobrowolną Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Zatem rzekł Mojżesz do synów Izraelskich: Oto, wezwał Pan z imienia Besaleela, syna Urowego, syna Churowego, z pokolenia Judy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'I napełnił go Duchem Bożym, mądrością, i umiejętnością wszelkiego rzemiosła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'I ku dowcipnemu wymyślaniu, cokolwiek może być urobione ze złota, i z srebra, i z miedzi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Do rzezania kamienia ku osadzeniu, i na wyrobienie drzewa, do czynienia wszelakiej roboty zmyślnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Dał nadto do serca jego, aby uczyć mógł inszych, on, i Acholijab, syn Achysamechów z pokolenia Dan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Napełnił je mądrością serca, aby robili wszelakie rzemiosło ciesielskie, i haftarskie, i tkackie z hijacyntu, i z szarłatu, z karmazynu dwa kroć farbowanego, i z białego jedwabiu tkacką robotą, aby robili każdą robotę dowcipnie wymyślając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Tedy robił Besaleel, i Acholijab, i każdy mąż dowcipny, którym dał Bóg mądrość i rozum, aby umieli urobić każdą robotę ku usłudze świątnicy, wszystko, co rozkazał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'I wezwał Mojżesz Besaleela, i Acholijaba, i każdego męża dowcipnego, któremu dał Pan mądrość w serce jego; każdego też, którego pobudziło serce jego, aby przystąpił do czynienia tej roboty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'I wzięli od Mojżesza wszystkie podarki, które byli przynieśli synowie Izraelscy na robotę ku usłudze świątnicy, aby ją wykonali; ale oni przynaszali do niego jeszcze dobrowolne dary na każdy poranek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Tedy się zeszli wszyscy dowcipni, którzy robili wszelaką robotę świątnicy, każdy opuściwszy robotę swoję, którą czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'I rzekli do Mojżesza, mówiąc: Daleko więcej lud przynosi, niż potrzeba do wyrobienia tej usługi, którą rozkazał Pan uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Rozkazał tedy Mojżesz, aby obwołano w obozie mówiąc: Ani mąż, ani niewiasta niech więcej ni przynoszą ofiar na robienie świątnicy. I zabroniono ludowi, aby nie nosili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Bo mieli potrzeb dostatek do wszystkiej roboty, aby ją wyrobili, i zbywało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'I urobili każdy dowcipny z rzemieślników tę robotę: przybytek z dziesięciu opon z białego jedwabiu kręconego, i z hijacyntu, i szarłatu i z karmazynu dwa kroć farbowanego; z Cherubiny, robotą misterną robili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Długość opony jednej dwadzieścia i osiem łokci, a szerokość opony jednej na cztery łokcie; pod jedną miarą były wszystkie opony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'I spoił pięć opon jednę z drugą, także drugie pięć opon spoił jednę z drugą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Naczynił też pętlic hijacyntowych po kraju opony jednej, na końcu, gdzie się spinać mają; także uczynił po kraju opony drugiej, na końcu, gdzie się spinać mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Pięćdziesiąt pętlic uczynił na oponie jednej, a pięćdziesiąt pętlic uczynił po kraju opony, któremi spojona była do drugiej; pętlica jedna przeciw drugiej była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Uczynił też pięćdziesiąt haczyków złotych, a spiął opony jednę ku drugiej haczykami; i tak uczyniony jest przybytek jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Urobił też opony z sierści koziej na namiot ku zakrywaniu przybytku z wierzchu, jedenaście opon urobił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Długość opony jednej trzydzieści łokci, a cztery łokcie szerokość opony jednej; jednaż miara była tych jedenaście opon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'I spoił pięć opon osobno, a sześć opon osobno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Uczynił też pętlic pięćdziesiąt po kraju jednej opony na końcu, gdzie się ma spinać; i pięćdziesiąt pętlic uczynił po kraju opony drugiej ku spinaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Uczynił też haczyków miedzianych pięćdziesiąt, do spięcia namiotu, aby był jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Nad to uczynił przykrycie na namiot z skór baranich czerwono farbowanych, i przykrycie z skór borsukowych na wierzch.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Naczynił też desek do przybytku z drzewa sytym stojących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Dziesięć łokci długość deski, a półtora łokcia szerokość deski jednej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Dwa czopy miała deska jedna, sporządzone jeden przeciwko drugiemu; tak uczynił u wszystkich desek przybytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Zgotował też i deski do przybytku, dwadzieścia desek ku stronie południowej, ku wiatrowi południowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'I czterdzieści podstawków urobił ze srebra pod dwadzieścia desek: dwa podstawki pod deskę jednę do dwóch czopów jej, także dwa podstawki pod deskę drugą do dwu czopów jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Także na drugiej stronie przybytku ku stronie północnej, uczynił dwadzieścia desek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'I czterdzieści podstawków ich srebrnych: dwa podstawki pod deskę jednę, i dwa podstawki pod deskę drugą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Lecz na stronie przybytku ku zachodowi, uczynił sześć desek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Dwie deski uczynił na węgłach po obu stronach przybytku;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'A były spojone od spodku, także spojone były od wierzchu do jednegoż kolca; tak uczynił po obu stronach na dwu węgłach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'A tak było osiem desek, i podstawków ich srebrnych szesnaście podstawków, po dwu podstawkach pod każdą deską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Naczynił i drągów z drzewa sytym; pięć do desek przybytku na jednę stronę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'Pięć także drągów do desek przybytku na drugą stronę, pięć też drągów do desek przybytku do obu węgłów, na zachód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'A uczynił też drąg pośredni, aby przechodził przez pośrodek desek od końca do końca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'A deski one powlókł złotem, i kolce do nich porobił ze złota, aby w nich drągi były, i powlókł drągi złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Uczynił zaś zasłonę z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i z białego jedwabiu kręconego; robotą misterną uczynił to z Cherubiny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'A do niej nagotował cztery słupy z drzewa sytym, i powlókł je złotem, haki też ich były złote, i ulał do nich cztery podstawki srebrne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Uczynił też zasłonę do drzwi namiotu z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i z białego jedwabiu kręconego, robotą haftarską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'A słupów do niej pięć z haczykami ich; i powlókł wierzchy ich i przepasania ich złotem, a podstawków ich było pięć miedzianych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Uczynił też Besaleel skrzynię z drzewa sytym, a była półtrzecia łokcia długość jej, a półtora łokcia szerokość jej, także półtora łokcia wysokość jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'I powlókł ją złotem szczerem wewnątrz, i zewnątrz, i uczynił jej koronę złotą w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Ulał też do niej cztery kolce złote do czterech węgłów jej: dwa kolce po jednej stronie jej, a dwa kolce po drugiej stronie jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Uczynił i drążki z drzewa sytym, a powlókł je złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'I przewlekł drążki przez kolce po stronach skrzyni, aby na nich noszona była skrzynia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Uczynił też ubłagalnią ze złota szczerego: półtrzecia łokcia długość jej, a półtora łokcia szerokość jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Urobił i dwa Cheruby złote, z ciągnionego złota urobił je na obu końcach ubłagalni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Cheruba jednego na jednym końcu, a Cheruba drugiego na drugim końcu; na ubłagalni uczynił Cheruby na obu końcach jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Którzy Cherubowie mieli rozciągnione skrzydła, z wierzchu zakrywając skrzydłami swemi ubłagalnią, a twarzy ich były jednemu ku drugiemu; ku ubłagalni były twarzy Cherubów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Przytem sprawił stół z drzewa sytym, dwa łokcie długość jego, i łokieć szerokość jego, a półtora łokcia wysokość jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'I powlókł go złotem szczerem, i uczynił mu koronę złotą w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Uczynił mu też listwę na dłoń w szerz w około; uczynił też i koronę złotą w około onej listwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'I ulał do niego cztery kolce złote, które kolce przyprawił na czterech rogach, u czterech nóg jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Na przeciwko onej listwie były kolce, w które zawłaczano drążki do noszenia stołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Porobił i drążki z drzewa sytym, i powlókł je złotem do noszenia stołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Poczynił też naczynia do stołu należące, misy jego i przystawki jego, i kubki jego, i czasze do nalewania ofiar mokrych, z szczerego złota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Urobił też świecznik ze złota szczerego, z ciągnionego złota uczynił świecznik ten, słupiec jego, i pręty jego, czaszki jego, gałki jego, i kwiaty jego z tegoż były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'A sześć prętów wychodziło po stronach jego: trzy pręty z jednej strony świecznika, a trzy pręty z drugiej strony świecznika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Trzy czaszki na kształt orzecha migdałowego na pręcie jednym, także gałka i kwiat; i trzy czaszki na kształt orzecha migdałowego na pręcie drugim, także gałka i kwiat; tak było na wszystkich sześciu prętach wychodzących z świecznika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Ale na świeczniku były cztery czaszki na kształt orzecha migdałowego, gałki jego i kwiaty jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'I była gałka pod dwiema prętami jego, także gałka pod drugiemi dwiema prętami jego, i zaś gałka pod innemi dwiema prętami jego; tak było pod sześcią prętów wychodzących z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Gałki ich i pręty ich z niego były; to wszystko ze złota całokowane było, ze złota szczerego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Uczynił też siedem lamp do niego, i nożyczki do nich i kaganki jego ze złota szczerego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Z talentu złota szczerego uczynił go, i wszystko naczynie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Uczynił też ołtarz do kadzenia z drzewa sytym, na łokieć wzdłuż, i na łokieć wszerz, czworograniasty, a na dwa łokcie wzwyż, a z niego wychodziły rogi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'I powlókł go złotem szczerem, wierzch jego, i ściany jego w około, i rogi jego; uczynił mu też koronę złotą w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Po dwu także kolcach złotych uczynił u niego, pod koroną jego, we dwu kątach jego, po obu stronach jego przez które przewłaczano drążki, aby był noszony na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Uczynił też drążki z drzewa sytym i powlókł je złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Uczynił też olejek pomazywania świętego, i kadzenie wonne, robotą aptekarską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Uczynił też ołtarz na całopalenie z drzewa sytym, na pięć łokci wzdłuż, i na pięć łokci wszerz, czworogranisty, a na trzy łokcie wzwyż.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'I uczynił mu rogi na czterech węgłach jego; z niego wychodziły rogi jego, a obił je miedzią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Poczynił też wszelakie naczynia do ołtarza, kotły, i miotły, i miednice, i widły, i łopaty, wszystkie naczynia jego uczynił z miedzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Uczynił też do ołtarza kratę miedzianą na kształt sieci między okręgiem jego, od spodku aż do połowy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'I ulał cztery kolce na czterech rogach kraty miedzianej, na zakładanie drążków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Drążki także porobił z drzewa sytym, a obił je miedzią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'I przewlókł drążki przez one kolce po stronach ołtarza, aby noszony był na nich; czczy z desek uczynił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Uczynił też wannę miedzianą, i stolec jej miedziany ze zwierciadeł niewiast gromadą przychodzących, które przychodziły do drzwi namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Uczynił i sień ku stronie południowej na południe, i opony sieni z białego jedwabiu kręconego, na sto łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Słupów do nich dwadzieścia, i podstawków do nich dwadzieścia miedzianych, główki na słupiech, i okręcenia ich srebrne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Także na stronie północnej opon na sto łokci; słupów do nich dwadzieścia i podstawków do nich miedzianych dwadzieścia; główki na słupiech i okręcenia ich srebrne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'A zasię od zachodniej strony były opony na pięćdziesiąt łokci; słupów do nich dziesięć, i podstawków ich dziesięć; główki na słupiech, i okręcenia ich srebrne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'A na stronie przedniej ku wschodowi było opon na pięćdziesiąt łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Opony na piętnaście łokci były po jednej stronie, słupów do nich trzy, i podstawków do nich trzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'A po drugiej stronie, stąd i zowąd u bramy sieni, opon piętnaście łokci, słupów do nich trzy, także podstawków do nich trzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Wszystkie opony sieni w około były z jedwabiu białego kręconego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'A podstawki słupów miedziane, główki na słupiech, i okręcenia ich srebrne, do tego przykrycie wierzchów ich srebrne, a były okręcane srebrem wszystkie słupy sieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Nad to zasłonę bramy u sieni uczynił robotą haftarską z hijacyntu, i z szarłatu i z karmazynu dwa kroć farbowanego, i z jedwabiu kręconego; na dwadzieścia łokci była długość jej, wysokość szeroka na pięć łokci, jako inne opony sieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'A słupów do nich cztery, także podstawków ich cztery miedzianych; główki ich srebrne, i zakrycia wierzchów ich, także okręcenia ich srebrne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Także wszystkie kołki przybytku, i sieni w około, były miedziane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Te są rzeczy policzone do przybytku, do przybytku świadectwa, które policzone były na rozkazanie Mojżeszowe przez Itamara, syna Aarona kapłana, ku usłudze Lewitom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'A Besaleel, syn Urów, syna Churowego z pokolenia Judy, uczynił to wszystko, co był Pan rozkazał Mojżeszowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'A z nim Acholijab, syn Achysamechów z pokolenia Dan, cieśla, subtelny rzemieślnik, i haftujący na hijacyncie, i na szarłacie, i na karmazynie dwa kroć farbowanym, i na białym jedwabiu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Wszystkiego złota wynałożonego na samą robotę, na wszystką robotę świątnicy, które złoto było podarkowe, było dziewięć i dwadzieścia talentów, siedem set i trzydzieści syklów według sykla świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Srebra zasię od policzonych w poczet zgromadzenia sto talentów, i tysiąc siedem set siedmdziesiąt i pięć syklów według sykla świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Od każdej głowy pół sykla według sykla świątnicy, od wszystkich, którzy szli w liczbę, będąc we dwudziestu lat i dalej, których ludzi było sześć kroć sto tysięcy, i trzy tysiące, i pięćset, i pięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'A było sto talentów srebra do odlewania podstawków świątnicy i podstawków zasłony; sto podstawków ze sta talentów; talent na podstawek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'A z tysiąca, siedmiu set, siedmdziesiąt i pięciu syklów uczynił haki na słupy, i powlókł wierzchy ich, i przepasał je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Miedzi zaś ofiarowanej było siedmdziesiąt talentów, dwa tysiące i cztery sta syklów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'I uczynił z niej podstawki do drzwi namiotu zgromadzenia, i ołtarz miedziany, i kratę miedzianą do niego, także wszystko naczynie do ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'I podstawki do sieni w około; także podstawki bramy siennej, i wszystkie kołki przybytku, także kołki sieni w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Także z hijacyntu i z szarłatu, z karmazynu dwa kroć farbowanego poczynili szaty do usługi, ku usługiwaniu w świątnicy. Urobili też szaty święte Aaronowi, jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'I uczynił naramiennik ze złota, z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i z białego jedwabiu kręconego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Naklepali też blaszek złotych, i nastrzygli z nich nici do przetykania hijacyntu, i do przetykania szarłatu, i do przetykania karmazynu dwa kroć farbowanego, i do przetykania białego jedwabiu, robotą haftarską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Naramienniki przytem porobili tak, aby się jeden z drugim spoić mógł; na dwu krajach ich spajały się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Pas też naramiennika, który był na nim, z tegoż był, i tąż robotą ze złota, z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i z białego jedwabiu kręconego, jako był Pan rozkazał Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Do tego wygotowali kamienie onychiny, oprawione złotem osadzeniem, rzezane, jako ryte bywają pieczęci, z imiony synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'I wprawił je na wierzchne kraje naramiennika, aby były kamieńmi na pamiątkę synom Izraelskim, jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Uczynił też napierśnik robotą haftarską, według roboty naramiennika, ze złota, z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i z białego jedwabiu kręconego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Czworograniasty był dwoisty uczynili napierśnik, na piędzi długość jego, i na piędzi szerokość jego, dwoisty był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'I nasadzili weń cztery rzędy kamienia tym porządkiem: sardyjusz, topazyjusz i szmaragd w rzędzie pierwszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'A w drugim rzędzie: karbunkuł, szafir i jaspis.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'A w trzecim rzędzie: linkuryjusz, achates i ametyst.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'A w czwartym rzędzie: chrysolit, onychin i berył, wszystkie osadzone w złoto w rzędziech swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'A tych kamieni z imionami synów Izraelskich dwanaście według imion ich było, tak, jako rzezą pieczęci; każdy według imienia swego podług dwunastu pokoleń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Poczynili też do napierśnika łańcuszki jednostajne robotą plecioną ze złota szczerego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Sprawili też dwa haczyki złote, i dwa kolce złote, i przyprawili one dwa kolce do obu krajów napierśnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'A przewlekli one dwa łańcuszki złote przez oba kolce u krajów napierśnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Drugie zaś dwa kolce obu łańcuszków zawlekli do onych dwu haczyków, i przyprawili do zwierzchnich krajów naramiennika na przodku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Uczynili także dwa kolce złote, które przyprawili do dwu końców napierśnika na kraju jego, który był po stronie naramiennika ze spodku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Uczynili jeszcze dwa kolce złote, które przyprawili na dwu stronach naramiennika ze spodku, na przodku przeciwko spojeniu jego, które jest nad przepasaniem naramiennika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'I przywiązali napierśnik do kolców jego, do kolców naramiennika sznurem hijacyntowym, aby był przepasaniem naramiennika, żeby nie odstawał napierśnik od naramiennika; jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Urobił także płaszcz pod naramiennik robotą tkaną, wszystek hijacyntowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'A rozpór płaszcza w pośród jego, jako rozpór u pancerza, i brama około kraju jego, aby się nie rozdzierał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Także u podołka płaszcza onego uczynili jabłka granatowe z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego, i z białego jedwabiu kręconego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Poczynili też dzwonki ze złota szczerego, i pozawieszali one dzwonki między one jabłka granatowe u podołka płaszcza w około, w pośród jabłek granatowych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Dzwonek a jabłko granatowe, i zaś dzwonek i jabłko granatowe, u podołka płaszcza w około ku posługiwaniu, jako rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Porobili też szaty z białego jedwabiu robotą tkacką Aaronowi, i synom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Czapeczkę też z białego jedwabiu, i czapki ozdobne z białego jedwabiu, i ubiory cienkie z białego jedwabiu kręconego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Pas także z białego jedwabiu kręconego, i z hijacyntu, i z szarłatu, i z karmazynu dwa kroć farbowanego robotą haftarską, jako rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Do tego uczynili blachę korony świętobliwości ze złota szczerego, i wyrysowali na niej robotą rytą, jako pieczęci rzezaną Świętość Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'A przyprawili do niej sznur hijacyntowy, aby przywiązana była do czapki na wierzchu, jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'A tak skończyła się wszystka robota około przybytku i namiotu zgromadzenia. I uczynili synowie Izraelscy wszystko, jako był rozkazał Pan Mojżeszowi, tak uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'I przynieśli ten przybytek do Mojżesza, namiot, i wszystkie naczynia jego, haki jego, deski jego, drągi jego, i słupy jego, i podstawki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'Przykrycie też ze skór baranich czerwono farbowanych, i przykrycie z skór borsukowych, i oponę zasłony;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'Skrzynię świadectwa, i drążki jej, i ubłagalnią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'Stół, wszystkie naczynia jego, i chleb pokładny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'Świecznik ochędożny, lampy jego, lampy sporządzone, i wszystkie naczynia jego, i oliwę ku świeceniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Ołtarz także złoty i olejek pomazywania, i kadzidło wonne, i zasłonę do drzwi namiotu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'Ołtarz miedziany, i kratę jego miedzianą, drążki jego, i wszystkie naczynia jego, wannę i stolec jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Opony do sieni, i słupy ich, i zasłonę do bramy siennej, i sznury jej, i kołki jej, i wszelakie naczynia ku służbie przybytku i namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Szaty służebne do usługowania w świątnicy, szaty święte Aaronowi kapłanowi, i szaty synów jego do odprawowania urzędu kapłańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Według wszystkiego, jako był rozkazał Pan Mojżeszowi, tak uczynili synowie Izraelscy wszystką tę robotę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'I obejrzał Mojżesz tę wszystką robotę, a oto, uczynili ją, jako był rozkazał Pan, tak uczynili; i błogosławił im Mojżesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'W dzień miesiąca pierwszego, pierwszego dnia tegoż miesiąca wystawisz przybytek, namiot zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'I postawisz tam skrzynię świadectwa, i zakryjesz ją zasłoną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Wstawisz i stół, i porządnie go sporządzisz, wniesiesz także świecznik, i zaświecisz lampy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Postawisz też ołtarz złoty do kadzenia przed skrzynią świadectwa, i zawiesisz zasłonę u drzwi przybytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Także postawisz ołtarz całopalenia przed drzwiami przybytku, namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Postawisz też wannę między namiotem zgromadzenia a między ołtarzem, w którą nalejesz wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Wystawisz też i sień w około, a zawiesisz zasłonę we drzwiach u sieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Zatem weźmiesz olejek pomazywania, i pomażesz przybytek, i wszystko, co w nim jest, i poświęcisz go ze wszystkiem naczyniem jego, a będzie świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Pomażesz też ołtarz całopalenia, i wszystkie naczynia jego, i poświęcisz ołtarz, a będzie ołtarzem najświętszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Nad to pomażesz wannę i stolec jej, a poświęcisz ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Zatem każesz przystąpić Aaronowi i synom jego do drzwi namiotu zgromadzenia, i umyjesz je wodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'I obleczesz Aarona w szaty święte, a pomażesz, i poświęcisz go, aby mi sprawował urząd kapłański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Synom także jego przystąpić każesz, i obleczesz je w szaty,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'A pomażesz je, jakoś pomazał ojca ich, aby mi sprawowali urząd kapłański; i będzie pomazanie ich onym ku wiecznemu kapłaństwu w narodziech ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Tedy uczynił Mojżesz wszystko; jako mu był rozkazał Pan, tak uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Stało się tedy miesiąca pierwszego, roku wtórego, pierwszego dnia miesiąca, że wystawiony jest przybytek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'I wystawił Mojżesz przybytek, a podstawił podstawki jego, i postawił deski jego, i założył drągi jego, i podniósł słupy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Rozbił też i namiot nad przybytkiem, i położył przykrycie namiotu nad nim z wierzchu, tak jako był Pan rozkazał Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Potem wziąwszy świadectwo, włożył je do skrzyni, i przewlókł drążki u skrzyni, i włożył ubłagalnią z wierzchu na skrzynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'I wniósł skrzynię do przybytku, i zawiesił oponę zakrycia, i zasłonił skrzynię świadectwa, jako był Pan rozkazał Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Postawił i stół w namiocie zgromadzenia ku północnej stronie przed zasłoną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'I sporządził na nim sporządzenie chlebów przed Panem, jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Postawił też świecznik w namiocie zgromadzenia na przeciwko stołowi ku południowej stronie przybytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Zapalił też lampy przed Panem, jako był Pan rozkazał Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Postawił i ołtarz złoty w namiocie zgromadzenia przed zasłoną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'I kadził na nim kadzeniem wonnem, jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Potem zawiesił zasłonę we drzwiach przybytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Nadto ołtarz postawił całopalenia przede drzwiami przybytku namiotu zgromadzenia, i ofiarował na nim całopalenie i ofiarę suchą, jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Potem postawił wannę między namiotem zgromadzenia, a między ołtarzem, w którą nalał wody dla umywania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'I umywali się z niej Mojżesz, i Aaron, i synowie jego, ręce swe i nogi swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Gdy wchodzili do namiotu zgromadzenia, i gdy mieli przystępować do ołtarza, umywali się, jako rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Na ostatek wystawił sień około przybytku i ołtarza, i zawiesił zasłonę w bramie sieni. A tak dokończył Mojżesz roboty onej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Tedy okrył obłok namiot zgromadzenia, a chwała Pańska napełniła przybytek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Tak, iż nie mógł Mojżesz wnijść do namiotu zgromadzenia; bo był nad nim obłok, a chwała Pańska napełniła była przybytek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'A gdy odstępował obłok od przybytku, ruszali się synowie Izraelscy w ciągnieniu swem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'A jeźli nie odstępował obłok, nie ruszali się aż do dnia, którego odstępował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'A obłok Pański bywał nad przybytkiem we dnie, a ogień bywał w nocy nad nim przed oczyma wszystkiego domu Izraelskiego, ilekroć ciągnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'I wezwał Pan Mojżesza, i rzekł do niego z namiotu zgromadzenia, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Mów do synów Izraelskich, a rzecz im: Gdyby kto z was ofiarował ofiarę Panu, z bydła, z wołów, i z drobnego bydła, ofiarować będziecie ofiarę waszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Jeźli całopalona ofiara jego będzie z rogatego bydła, samca zupełnego ofiarować będzie; u drzwi namiotu zgromadzenia ofiarować go będzie dobrowolnie przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'I położy rękę swą na głowę ofiary całopalenia, a będzie przyjemną zań na oczyszczenie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Zabije tedy cielca tego kapłan przed oblicznością Pańską; a synowie Aaronowi, kapłani, ofiarować będą krew, a pokropią tą krwią ołtarz z wierzchu w około, który jest przede drzwiami namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'A wziąwszy skórę z ofiary całopalenia rozrąbie ją na sztuki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Potem nałożą synowie Aarona kapłana, ogień na ołtarzu, a ułożą drwa na ogień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Potem porządnie włożą synowie Aaronowi, kapłani, one sztuki, głowę, i tłustość, na drwa, które są na ogniu, który jest na ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'A wnętrzności jego, i nogi jego, opłucze wodą, i zapali kapłan to wszystko na ołtarzu; całopalenie jest ofiary ognistej ku wdzięcznej wonności Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'A jeźliżby z drobnego bydła kto chciał ofiarować z owiec albo z kóz, na ofiarę całopalenia, samca zupełnego ofiarować będzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'I zabije go po bok ołtarza ku północy przed oblicznością Pańską; a pokropią synowie Aaronowi, kapłani, krwią jego po wierzchu ołtarza w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'I rozrąbie go na sztuki, i głowę jego, i tłustość jego; a włoży je kapłan porządnie na drwa, które są na ogniu, który jest na ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'A wnętrzności i nogi opłucze wodą; i będzie ofiarował kapłan to wszystko, i zapali to na ołtarzu. Całopalenie jest ofiary ognistej ku wdzięcznej wonności Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'A jeźliby z ptastwa całopalenia ofiarę chciał kto ofiarować Panu, tedy niech przyniesie z synogarlic, albo z gołąbiąt ofiarę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'A będzie ją ofiarował kapłan na ołtarzu, i paznogciem nadrze głowę jego, i zapali na ołtarzu, wycisnąwszy krew jego na stronie ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Odejmie też gardziel jego z pierzem jego, a porzuci je blisko ołtarza ku wschodniej stronie, na miejsce, gdzie popiół bywa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'I rozedrze mu skrzydła jego, a wszakże ich nie oderwie; i spali to kapłan na ołtarzu, na drwach, które są na ogniu; całopalenie jest ofiary ognistej ku wdzięcznej wonności Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Gdyby też kto ofiarować chciał dar ofiary śniednej Panu, pszenna mąka będzie ofiara jego; i poleje ją oliwą, i nakładzie na nią kadzidła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'I przyniesie ją do synów Aaronowych, kapłanów, a weźmie stąd pełną garść swoję tej pszennej mąki, i tej oliwy, ze wszystkiem kadzidłem; i zapali to kapłan na pamiątkę jej na ołtarzu; ofiara ognista jest ku wdzięcznej wonności Panu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Ale co zostanie od onej ofiary śniednej, Aaronowi i synom jego będzie; najświętsza rzecz jest z ognistych ofiar Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'A jeźlibyś też ofiarował dar ofiary śniednej w piecu pieczonej, niechże będzie z pszennej mąki placek przaśny zagnieciony w oliwie, i kreple przaśne, pomazane oliwą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Jeźliże zaś ofiarę śniedną smażoną w pańwi ofiarować będziesz, niechże będzie z mąki pszennej zagniecionej w oliwie, oprócz zakwaszenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Połamiesz ją na kęsy, i polejesz ją oliwą; ofiara to śniedna jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'A jeźli ofiarę śniedną w kotle zgotowaną ofiarować będziesz, z mąki pszennej z oliwą będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'I przyniesiesz ofiarę śniedną z tych rzeczy sprawioną Panu, i oddasz ją kapłanowi, a odniesie ją na ołtarz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'I weźmie kapłan z onej ofiary śniednej pamiątkę jej, i zapali na ołtarzu; ofiara to ognista ku wdzięcznej wonności Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'A co pozostanie od onej ofiary śniednej, Aaronowi i synom jego będzie; najświętsza rzecz jest z ognistych ofiar Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Wszelka ofiara śniedna, którą ofiarować będziecie Panu, bez kwasu będzie; bo żadnego kwasu i żadnego miodu nie będziecie zapalać na ofiarę ognistą Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Tylko w ofiarach pierwiastek ofiarować to będziecie Panu; ale na ołtarz nie będziecie ich kłaść ku wdzięcznej wonności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Każdy dar ofiary twojej śniednej solą posolisz a nie odejmiesz soli przymierza Boga twojego od ofiary twojej śniednej; przy każdej ofierze twojej ofiarować będziesz sól.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'A jeźli ofiarować będziesz ofiarę śniedną z pierwszych urodzajów Panu, świeże kłosy uprażysz ogniem, a zboże wykruszone z kłosów świeżych ofiarować będziesz na ofiarę śniedną pierwszych urodzajów twoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'I nalejesz na nią oliwy, a nakładziesz na nią kadzidła; bo ofiara śniedna jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Tedy zapali kapłan pamiątkę jej ze zboża wykruszonego jej, i z oliwy jej, ze wszystkiem kadzidłem jej; bo ofiara ognista jest Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'A jeźliby ofiara spokojna była ofiara jego, a byłaby z rogatego bydła, ofiarować będzie samca, albo samicę; zupełnie ofiarować je będzie przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'I położy rękę swą na głowę ofiary swojej, i zabije ją kapłan przede drzwiami namiotu zgromadzenia; i wyleją synowie Aaronowi, kapłani, krew na wierzch ołtarza w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Potem ofiarować będzie z ofiary spokojnej paloną ofiarę Panu; tłustość okrywającą wnętrzności, i wszystkę tłustość, która jest na wnętrznościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Obie też nerki z tłustością, która jest na nich, i na polędwicach, i odzieczkę, która na wątrobie, z nerkami odejmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'I zapalą to synowie Aaronowi na ołtarzu, pospołu z ofiarą całopalenia, która będzie na drwach, które są na ogniu; ofiara to ognista ku wdzięcznej wonności Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Ale jeźliby z drobnego bydła była ofiara jego na ofiarę spokojną Panu, samca albo samicę zupełne ofiarować je będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Jeźliby baranka ofiarował na ofiarę swoję, ofiarować go będzie przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'A włoży rękę swą na głowę ofiary swojej, i zabije ją przed namiotem zgromadzenia; i wyleją synowie Aaronowi krew jej na wierzch ołtarza w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'I będzie ofiarował z ofiary spokojnej ofiarę ognistą Panu, tłustość jej, ogon cały, który od grzbietu odejmie, także i tłustość, okrywającą wnętrzności, i wszystkę tłustość, która jest na wnętrznościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Obie też nerki z tłustością, która jest na nich, i na polędwicach, i odzieczkę, która na wątrobie, z nerkami odejmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'I zapali to kapłan na ołtarzu, pokarm to jest ofiary ognistej Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Jeźliby zaś koza była ofiarą jego, tedy ją ofiarować będzie przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'I położy rękę swoję na głowę jej, i zabije ją przed namiotem zgromadzenia, i wyleją synowie Aaronowi krew jej na wierzch ołtarza w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'I ofiarować będzie z niej ofiarę swoję na ofiarę ognistą Panu, tłustość okrywającą wnętrzności, i wszystkę tłustość, która jest na wnętrznościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Obie też nerki z tłustością która jest na nich i na polędwicach, i odzieczkę która na wątrobie, z nerkami odejmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'I zapali to kapłan na ołtarzu, pokarm to jest ofiary ognistej na wdzięczną wonność; bo wszystka tłustość jest Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Prawem wiecznem w narodziech waszych, we wszystkich mieszkaniach waszych, żadnej tłustości i żadnej krwi jeść nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'I rzekł Pan do Mojżesza mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Mów do synów Izraelskich, a rzecz: Gdyby kto zgrzeszył z niewiadomości, przeciw któremu ze wszystkich przykazań Pańskich, czyniąc, czego by czynić nie miał, a przestąpiłby jedno z nich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'Jeźliby kapłan pomazany zgrzeszył jako jeden z ludu pospolitego, tedy niech ofiaruje za grzech swój, którego się dopuścił, cielca młodego zupełnego Panu na ofiarę za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'I przywiedzie cielca onego do drzwi namiotu zgromadzenia przed obliczność Pańską, a włoży rękę swoję na głowę onego cielca, i zabije go przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Tedy weźmie kapłan pomazany ze krwi onego cielca, i wniesie ją do namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Potem omoczy kapłan palec swój we krwi, a kropić będzie oną krwią siedem kroć przed obliczem Pańskiem przed zasłoną świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'I pomaże kapłan krwią oną rogi ołtarza kadzenia wonnego, przed obliczem Pańskiem, który jest w namiocie zgromadzenia, a ostatek krwi onego cielca wyleje u spodku ołtarza całopalenia, który jest u drzwi namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Wszystkę zaś tłustość cielca tego za grzech ofiarowanego wyjmie z niego tłustość okrywającą wnętrzności i wszystkę tłustość, która jest na wnętrznościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Obie też nerki z tłustością, która jest na nich, i na polędwicach, i odzieczkę, która jest na wątrobie i na nerkach, odejmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Jako odejmują z wołu ofiary spokojnej, i zapali to kapłan na ołtarzu całopalonych ofiar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Skórę zaś cielca tego, i wszystko mięso jego z głową jego i z nogami jego i z wnętrznościami jego i z gnojem jego');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'Owa, całego cielca wyniesie precz za obóz na miejsce czyste, tam gdzie się wysypuje popiół, i spali go na drwach ogniem, gdzie wysypują popiół, tam spalony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Jeźliby też wszystko zgromadzenie Izraelskie z nieobaczenia zgrzeszyło, a byłaby rzecz zakryta od oczu zgromadzenia tego, i uczyniliby przeciw któremu ze wszystkich przykazań Pańskich, coby być nie miało, a byliby winni,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'I poznaliby grzech, którym zgrzeszyli, ofiarować będzie ono zgromadzenie cielca młodego na ofiarę za grzech, a przywiodą go przed namiot zgromadzenia,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'I położą starsi zgromadzenia ręce swe na głowę cielca onego przed obliczem Pańskiem i zabiją tegoż cielca przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Tedy wniesie kapłan pomazany, ze krwi cielca onego do namiotu zgromadzenia,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'I omoczy kapłan palec swój w onej krwi, a będzie nią kropił siedem kroć przed obliczem Pańskiem, przed zasłoną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'A oną krwią pomaże rogi ołtarza, który jest przed obliczem Pańskiem, w namiocie zgromadzenia; a ostatek krwi wyleje u spodku ołtarza całopalenia, który jest u drzwi namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Wszystkę też tłustość jego wyjmie z niego, i zapali na ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'I uczyni z tem cielcem, jako uczynił z cielcem, za grzech ofiarowanym, tak uczyni z nim; a tak oczyści je kapłan, i będzie im odpuszczono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Potem wyniesie cielca onego precz za obóz, i spali go, jako spalił cielca pierwszego. Tać jest ofiara za grzech zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Jeźliby książę zgrzeszył, i uczynił przeciw któremu ze wszystkich przykazań Pana Boga swego, coby być nie miało, a to z nieobaczenia, a byłby winien:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'I byłby jawny grzech jego, którym zgrzeszył, przywiedzie na ofiarę swoję kozła z kóz, samca zupełnego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'I położy rękę swoję na głowę tegoż kozła, i zabije go na miejscu, gdzie biją ofiary na całopalenie, przed obliczem Pańskiem. Ofiara to jest za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'I weźmie kapłan ze krwi ofiary za grzech na palec swój, a pomaże rogi ołtarza całopalonych ofiar, a ostatek krwi jego wyleje u spodku ołtarza całopalenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Wszystkę zaś tłustość jego zapali na ołtarzu, jako i tłustość ofiary spokojnej; a tak oczyści go kapłan od grzechu jego i będzie mu odpuszczony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'A jeźliby kto zgrzeszył z ludu pospolitego z nieobaczenia, a uczyniłby przeciw któremu z przykazań Pańskich, coby być nie miało, i byłby winien,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'A byłby znajomy grzech jego, którym zgrzeszył, przywiedzie ofiarę swoję, kozę z kóz, zupełną samicę, za grzech swój, którego się dopuścił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'A położywszy rękę swą na głowę tej ofiary za grzech, zabije tę ofiarę za grzech na miejscu ofiar całopalonych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Potem wziąwszy kapłan ze krwi onej na palec swój, pomaże rogi ołtarza całopalonych ofiar, a ostatek krwi jej wyleje u spodku onegoż ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Wszystkę także tłustość jej odejmie, jako się odejmuje tłustość od ofiary spokojnej, i spali to kapłan na ołtarzu ku wdzięcznej wonności Panu; a tak oczyści go kapłan, i będzie mu odpuszczono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'A jeźliby owcę przywiódł na ofiarę swoję za grzech, samicę zupełną niech przywiedzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'I włoży rękę swą na głowę onej ofiary za grzech, i zabije ją na ofiarę za grzech na miejscu, gdzie zabijają ofiary całopalenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Potem weźmie kapłan onej krwi z ofiary za grzech na palec swój, i pomaże rogi u ołtarza palonych ofiar, a ostatek krwi jej wyleje u spodku onego ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'I wszystkę tłustość jej odejmie, jako odejmują tłustość baranka z ofiary spokojnej, i spali ją kapłan na ołtarzu na całopaloną ofiarę Panu. A tak oczyści go kapłan od grzechu jego, którym zgrzeszył, i będzie mu odpuszczony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Jeźliby też człowiek zgrzeszył, żeby słyszał głos bluźnierstwa, a byłby świadkiem tego, co albo widział, albo słyszał, a nie oznajmiłby, poniesie karanie za nieprawość swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Albo jeźliby się kto dotknął rzeczy nieczystej, bądź ścierwu zwierza nieczystego, bądź ścierwu bydlęcia nieczystego, bądź ścierwu gadziny nieczystej, a byłoby to zakryto przed nim, przecię nieczysty będzie, i winien jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Albo jeźliby się kto dotknął nieczystości człowieczej, jakażbykolwiek była nieczystość jego, przez którą się nieczystym stawa, a byłoby to skryto przed nim, i dowiedziałby się, winien jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Albo jeźliby kto przysiągł wymówiwszy usty, że źle albo dobrze uczynił, o wszystko, co wymawia człowiek z przysięgą, a byłoby to skryto przed nim i dowiedziałby się potem, że winien jest w jednej rzeczy z tych:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'Będąc tedy winien w jednej rzeczy z tych, wyzna grzech swój;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'I przywiedzie ofiarę za winę swoję Panu za grzech swój, którym zgrzeszył, samicę z drobnego bydła, owcę, albo kozę za grzech, a oczyści go kapłan od grzechu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'A jeźliby nie przemógł ofiarować bydlątka, tedy przyniesie ofiarę za występek swój, którym zgrzeszył, parę synogarlic, albo parę gołąbiąt Panu, jedno na ofiarę za grzech, a drugie na ofiarę całopalenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'I przyniesie je do kapłana, a on naprzód ofiarować będzie to, co ma być na ofiarę za grzech, i paznogciem nadrze głowę jego ku szyi, ale jej nie oderwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'I pokropi krwią z ofiary za grzech stronę ołtarza, a ostatek onej krwi wyciśnie u spodku ołtarza. Ofiara to za grzech jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Z drugiego zasię uczyni ofiarę całopalenia według zwyczaju. A tak oczyści go kapłan od grzechu jego, którym zgrzeszył, a będzie mu odpuszczony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'A jeźliby nie przemógł ofiarować parę synogarlic, albo parę gołąbiąt, tedy przyniesie ofiarę swoję za to, co zgrzeszył, dziesiątą część efy mąki pszennej na ofiarę za grzech, nie naleje na nię oliwy, ani włoży na nię kadzidła; bo jest ofiara za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'A gdy ją przyniesie do kapłana, tedy nabrawszy kapłan z niej pełną garść swoję na pamiątkę jego, spali ją na ołtarzu mimo ofiarę ognistą Panu; ofiara to za grzech jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'I oczyści go kapłan od grzechu jego, którym zgrzeszył w którejkolwiek z tych rzeczy, a będzie mu odpuszczony; a ostatek będzie kapłanowi, jako przy ofierze śniednej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Nad to rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Gdyby człowiek przestąpił przestępstwem, a zgrzeszyłby z niewiadomości, ujmując rzeczy poświęconych Panu, tedy przywiedzie ofiarę za występek swój Panu, barana zupełnego z drobnego bydła według oszacowania twego, za dwa sykle srebra według sykla świątnicy, na ofiarę za występek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'A to, coby wziął z poświęconych rzeczy, wróci, i piątą część nadto przyda i odda kapłanowi; a kapłan go oczyści przez barana ofiary za grzech, a będzie mu odpuszczono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Jeźliby też człowiek zgrzeszył, uczyniwszy przeciw któremukolwiek z przykazań Pańskich, coby nie miało być, z niewiadomości, a byłby winien, poniesie karanie za nieprawość swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Tedy przywiedzie barana zupełnego z drobnego bydła według szacunku twojego, na ofiarę za występek do kapłana; i oczyści go kapłan od niewiadomości jego, której się dopuścił nie wiedząc, a będzie mu odpuszczono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Ofiara to za występek jest, którym wystąpił przeciwko Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Gdyby człowiek zgrzeszył, a występkiem wystąpił przeciwko Panu, a zaprzałby rzeczy sobie zwierzonej, i do schowania danej, alboby co wydarł, alboby gwałtem wziął od bliźniego swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Także jeźliby rzecz zgubioną znalazł, a zaprzałby jej, alboby też przysiągł fałszywie o którąkolwiek rzecz z tych, które czyni człowiek, grzesząc przez nię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Gdyby tedy zgrzeszył, a winien był, wróci rzecz, którą wydarł, albo którą gwałtem wziął, albo też rzecz sobie powierzoną albo rzecz zgubioną, którą znalazł;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Albo też o cobykolwiek fałszywie przysiągł: tedy wróci to całe, i piątą część do tego przyda temu, czyje było to; wróci w dzień ofiary za grzech swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'A ofiarę za występek swój przywiedzie Panu, barana zupełnego z drobnego bydła według oszacowania twego na ofiarę za grzech do kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'I oczyści go kapłan przed Panem, a będzie mu odpuszczona każda z tych rzeczy, którą uczynił, i był jej winien.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Rozkaż Aaronowi i synom jego, i rzecz: Tać będzie ustawa ofiary całopalenia; ofiara całopalenia jest od palenia na ołtarzu, przez całą noc aż do poranku; bo ogień na ołtarzu ustawicznie gorzeć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'I oblecze się kapłan w odzienie swoje lniane, i ubiory lniane oblecze na ciało swoje, i zbierze popiół, gdy spali ogień ofiarę całopalenia na ołtarzu, a wysypie go podle ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Potem zewlecze szaty swe, i oblecze się w szaty inne, a wyniesie popiół on za obóz na miejsce czyste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'A ogień na ołtarzu ustawicznie gorzeć będzie, nie będzie gaszony; a będzie zapalał na nim kapłan drwa na każdy poranek, i włoży nań ofiarę całopalenia, a palić będzie na nim tłustość ofiar spokojnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Ogień ustawicznie będzie gorzał na ołtarzu, nie będzie gaszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'A tać też jest ustawa ofiary śniednej, którą ofiarować będą synowie Aaronowi przed obliczem Pańskiem u ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Weźmie garść swoję pszennej mąki z tej ofiary śniednej, i z oliwy jej ze wszystkiem kadzidłem, które będzie na ofierze śniednej, i to spali na ołtarzu ku wdzięcznej wonności na pamiątkę jej Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'A co zostanie z niej, jeść będą Aaron i synowie jego; bez kwasu jedzone będzie na miejscu świętem; w sieni namiotu zgromadzenia jeść to będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Nie będą tego ważyć z kwasem bo za dział ich dałem im to, z ofiar moich ognistych; rzecz najświętsza to jest jako i ofiara za grzech, i jako ofiara za występek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Każdy mężczyzna z synów Aaronowych jeść to będzie; ustawa to wieczna w narodziech waszych o palonych ofiarach Pańskich; wszystko, co się ich dotknie, poświęcone będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Tać jest ofiara Aarona, i synów jego, którą ofiarować będą Panu w dzień pomazania swego: dziesiątą część efy mąki pszennej za ofiarę śniedną ustawiczną, połowę jej rano, a połowę jej w wieczór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'W pańwi z oliwą będzie gotowana; smażoną przyniesiesz ją, usmażoną ofiarę śniedną w sztukach ofiarować będziesz ku wdzięcznej wonności Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'A kapłan pomazany z synów jego po nim ofiarować ją będzie; ustawa to wieczna Panu, wszystka spalona będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'I każda śniedna ofiara kapłańska, wszystka spalona będzie; nie będą jej jeść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Mów do Aarona, i synów jego, a rzecz: Ta będzie ustawa ofiary za grzech: Na miejscu, gdzie biją ofiary całopalenia, będzie zabita ofiara za grzech przed Panem; rzecz najświętsza jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Kapłan, który by ją ofiarował za grzech, jeść ją będzie; na miejscu świętem jedzona będzie; w sieni namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Wszystko, co się dotknie mięsa jej, będzie poświęcone; a jeźliby krwią jej szata pokropiona była, co się pokropiło, omyjesz na miejscu świętem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Naczynie też gliniane, w którem by ją warzono, stłuczone będzie; a jeźliby w naczyniu miedzianem warzona była, wytrą je, i wymyją wodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Wszelki mężczyzna z kapłanów jeść ją będzie; najświętsza to rzecz jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'A żadna ofiara za grzech, której krew wnaszana bywa do namiotu zgromadzenia dla oczyszczenia w świątnicy, nie będzie jedzona, ale ogniem spalona będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Tać jest ustawa ofiary za występek, która jest najświętsza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Na miejscu, gdzie biją ofiary całopalenia, zabiją ofiarę za występek, a krwią jej pokropią ołtarz z wierzchu w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'A wszystkę tłustość jej ofiarować będzie z niej, ogon i tłustość okrywającą wnętrzności;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'Obiedwie też nerki z tłustością, która jest na nich, i na polędwicach, i odzieczkę, która jest na wątrobie i na nerkach, odejmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'I spali to kapłan na ołtarzu na ofiarę ognistą Panu; ofiara to jest za występek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Wszelki mężczyzna z kapłanów będzie ją jadł, na miejscu świętem jedzona będzie; rzecz to najświętsza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Jako ofiara za grzech, tak ofiara za występek jednaką ustawę mają; kapłanowi, który by go oczyszczał, należeć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Kapłanowi, który by czyję ofiarę całopaloną ofiarował, skóra tejże ofiary, którą ofiarował, należeć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Także każda ofiara śniedna w piecu upieczona, i wszystko, co na pańwi albo w kotle gotowane będzie, kapłanowi, który to ofiaruje, należeć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Przytem wszelaka ofiara śniedna, zagnieciona z oliwą albo prażona, wszystkim synom Aaronowym należeć będzie, tak jednemu, jako drugiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Tać też jest ustawa ofiary spokojnej, którą będą ofiarowali Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Jeźliby kto ofiarował na ofiarę dziękczynienia, tedy ofiarować będzie na ofiarę dziękczynienia placki przaśne, zagniatane z oliwą, i kreple przaśne, pomazane oliwą, i mąkę pszenną, smażoną z temi plackami w oliwie zagniecionemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Przy tych plackach będzie też chleb kwaszony ofiarował na ofiarę swoję z ofiarą dziękczynienia spokojnych ofiar swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'I będzie ofiarował z niego jeden chleb z każdej ofiary na podnoszenie Panu. Kapłanowi, który kropi krwią ofiar spokojnych, należeć to będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Mięso zaś ofiary dziękczynienia, która jest spokojna, w dzień ofiarowania ofiary jego jedzone będzie; nie zostawią z niego nic do jutra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'A jeźliby kto ślubną albo dobrowolną przyniósł ofiarę swoją, w dzień ofiarowania ofiary jego jedzone będzie; a nazajutrz, coby zostało z niej, zjedzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Ale jeźliby co zostało mięsa z tej ofiary do trzeciego dnia, ogniem spalone będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'A jeźliby kto przecię jadł mięso tej ofiary spokojnej dnia trzeciego, nie będzie przyjemny ten, który ją ofiarował; nie będzie mu płatna, owszem obrzydliwością będzie; a kto by jadł z niej, nieprawość swoję poniesie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Mięso też, które by się dotknęło czego nieczystego, nie będzie jedzone, ale ogniem spalone będzie; mięso zaś inne, każdy czysty jeść je będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'A ktobykolwiek jadł mięso z ofiary spokojnej, ofiarowanej Panu, a byłby nieczysty, wytracony będzie człowiek ten z ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Jeźliby się też kto dotknął czego nieczystego, bądź nieczystości człowieczej, bądź nieczystości bydlęcej, bądź jakiejkolwiek obrzydliwości nieczystej, a jadłby mięso z ofiary spokojnej, ofiarowanej Panu, tedy wytracony będzie człowiek ten z ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Rzekł jeszcze Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Powiedz synom Izraelskim, i rzecz: Żadnej tłustości z wołu, ani z owiec, ani z kozy, nie będziesz jadł,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Aczkolwiek tłustość bydlęcia zdechłego, albo tłustość rozszarpanego może być do wszelakiej potrzeby; ale jeść jej żadnym sposobem nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Albowiem ktobykolwiek jadł tłustość z bydlęcia, które ofiarować będzie człowiek na ofiarę ognistą Panu, niechaj wytracony będzie człowiek ten, który jadł, z ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Także żadnej krwi jeść nie będziecie we wszystkich mieszkaniach waszych, tak z ptaków, jako i z bydląt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Wszelki człowiek, który by jadł jakąkolwiek krew, wytracony będzie człowiek on z ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Rzekł jeszcze Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Mów do synów Izraelskich, a rzecz im: Kto by ofiarował ofiarę spokojną swoję Panu, przyniesie ofiarę swoję Panu z ofiary spokojnej swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Ręka jego przyniesie ofiarę ognistą Panu; tłustość z mostkiem przyniesie, a mostek niech będzie tam i sam obracany na ofiarę przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Potem spali kapłan tłustość na ołtarzu; ale mostek zostanie Aaronowi i synom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'A łopatkę prawą oddacie na podnoszenie kapłanowi z ofiar spokojnych waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Kto też z synów Aaronowych ofiarować będzie krew ofiar spokojnych i tłustość, temu się dostanie łopatka prawa działem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Albowiem mostek sam i tam obracania, i łopatkę podnoszenia, wziąłem od synów Izraelskich z ofiar ich spokojnych, i dałem je Aaronowi kapłanowi, i synom jego prawem wiecznem od synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Toć jest dział pomazanego Aarona, i pomazanych synów jego z ofiar ognistych Pańskich, od dnia, któregom im przystąpić rozkazał ku sprawowaniu urzędu kapłańskiego Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'I rozkazał Pan, aby im to dawano było od dnia, którego je pomazał, od synów Izraelskich prawem wiecznem w narodziech ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Tać jest ustawa ofiary całopalenia, ofiary śniednej, i ofiary za grzech, i za występek, i poświęcenia, i ofiary spokojnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Którą rozkazał Pan Mojżeszowi na górze Synaj, dnia, którego przykazywał synom Izraelskim, aby ofiarowali ofiary swe Panu na puszczy Synaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Weźmij Aarona i syny jego z nim, i szaty ich, i olejek pomazywania, i cielca na ofiarę za grzech, i dwa barany, i kosz chlebów przaśnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'A wszystek lud zbierz do drzwi namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'I uczynił Mojżesz, jako mu rozkazał Pan; i zebrał się wszystek lud do drzwi namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Tedy rzekł Mojżesz do zgromadzenia: Toć jest słowo, które rozkazał Pan czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'A kazawszy przystąpić Mojżesz Aaronowi i synom jego, omył je wodą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'I oblekł go w suknią, a opasał go pasem, i odział go płaszczem, i na wierzch włożył nań naramiennik, i przypasał go pasem naramiennika, i opasał go nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Włożył też nań napierśnik, i przyprawił do niego Urim i Tummim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Także włożył czapkę na głowę jego, a włożył na czapkę na przodek blachę złotą, koronę świętą, jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Wziął też Mojżesz olejek pomazywania, i pomazał przybytek, i wszystkie rzeczy, które w nim były, i poświęcił je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Potem pokropił nim ołtarz siedem kroć, i pomazał ołtarz ze wszystkiem naczyniem jego, i wannę, i stolec jej, aby je poświęcił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Wlał także olejku pomazywania na głowę Aaronowę, i pomazał go na poświęcenie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Zatem rozkazał Mojżesz przystąpić synom Aaronowym, a oblókłszy je w szaty, opasał je pasem, i włożył na nie czapki, jako był Pan rozkazał Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Tamże przywiódł cielca ku ofierze za grzech; i włożyli Aaron i synowie jego ręce swe na głowę cielca ofiary za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'I zabił go Mojżesz, a wziąwszy krwi jego, pomazał rogi ołtarza w około palcem swym, i oczyścił ołtarz. Ostatek zaś krwi wylał u spodku ołtarza, i poświęcił go dla oczyszczania na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Wziął potem wszystkę, tłustość, która na wnętrznościach była, i odzieczkę z wątroby, i dwie nerki z tłustością ich, i spalił to Mojżesz na ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'A cielca z skórą jego i z mięsem jego i z gnojem jego spalił ogniem precz za obozem, jako był Pan rozkazał Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Potem przywiódł barana na ofiarę całopalenia; i włożyli Aaron i synowie jego ręce swe na głowę tego barana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'I zabił go Mojżesz a pokropił krwią jego ołtarz z wierzchu w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'A barana porąbał na sztuki jego, i spalił Mojżesz głowę, i sztuki i tłustość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'A wnętrzności i nogi opłukał wodą; i tak spalił Mojżesz wszystkiego barana na ołtarzu. Całopalenie to jest ku wdzięcznej wonności, ofiara ognista jest Panu, jako był Pan rozkazał Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Potem kazał przywieść barana drugiego, barana poświęcenia; i włożyli Aaron i synowie jego ręce swoje na głowę tegoż barana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'A zabiwszy go Mojżesz wziął ze krwi jego, i pomazał nią koniec prawego ucha Aaronowego, i wielki palec prawej ręki jego, także palec wielki prawej nogi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Rozkazał też przystąpić synom Aaronowym, i pomazał Mojżesz onąż krwią koniec ucha ich prawego, i palce wielkie ich prawej ręki, i palce wielkie nogi ich prawej; i wylał Mojżesz krew na wierzch ołtarza w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Potem wziął tłustość i ogon, i wszystkę tłustość, która jest około wnętrzności, i odzieczkę z wątroby, i dwie nerki z tłustością ich i łopatkę prawą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Także z kosza przaśnych chlebów, które były przed Panem, wziął placek przaśny jeden, i bochen chleba z oliwą jeden, i krepel jeden, a położył je na onych tłustościach i na łopatce prawej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'I dał to wszystko w ręce Aaronowi i w ręce synów jego, i obracał to tam i sam za ofiarę obracania przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Potem ono wziął Mojżesz z rąk ich, a spalił na ołtarzu na całopalenie; poświęcenie to jest na wdzięczną wonność, ofiara ognista jest Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Wziął też Mojżesz mostek, i obracał go sam i tam za ofiarę obracania przed Panem; a z barana poświęcenia dostał się Mojżeszowi dział, jako mu był rozkazał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Wziął jeszcze Mojżesz olejku pomazywania i krwi, która była na ołtarzu, a pokropił Aarona i szaty jego, także syny jego, i szaty synów jego z nim. A tak poświęcił Aarona i szaty jego, i syny jego, i szaty synów jego z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'I rzekł Mojżesz do Aarona, i do synów jego: Warzcie to mięso u drzwi namiotu zgromadzenia, i tam je jedzcie, i chleb, który jest w koszu poświęcenia, jakom przykazał, mówiąc: Aaron i synowie jego będą je jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'A coby zostało z mięsa i z chleba, ogniem spalicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'A ze drzwi namiotu zgromadzenia nie wychodźcie przez siedem dni, aż do dnia, którego się wypełni czas poświęcenia waszego; bo przez siedem dni poświęcane będą ręce wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Jako się stało dziś, tak przykazał Pan czynić na oczyszczenie wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Przetoż przy drzwiach namiotu zgromadzenia trwać będziecie we dnie i w nocy przez siedem dni, a strzec będziecie rozrządzenia Pańskiego, abyście nie pomarli; bo mi tak rozkazano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'I uczynili Aaron i synowie jego to wszystko, co im rozkazał Pan przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'I stało się dnia ósmego, wezwał Mojżesz Aarona i synów jego, i starszych Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'I rzekł do Aarona: Weźmij sobie cielca młodego na ofiarę za grzech, i barana na ofiarę całopalenia, oboje zupełne, i ofiaruj je przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Do synów zaś Izraelskich rzeczesz, mówiąc: Weźmijcie kozła z kóz na ofiarę za grzech, i cielca, i barana, roczniaki zupełne, zdrowe, na ofiarę całopalenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Także wołu, i barana na ofiary spokojne ku ofiarowaniu przed Panem, i ofiarę śniedną nagniecioną z oliwą; albowiem się wam dziś Pan ukaże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'I przynieśli, co rozkazał Mojżesz, przed namiot zgromadzenia; a przystąpiwszy wszystek lud, stanął przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Zatem rzekł Mojżesz: Tać jest rzecz, którą wam Pan rozkazał; czyńcież ją, a ukaże się wam chwała Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Rzekł zaś Mojżesz do Aarona: Przystąp do ołtarza, a uczyń ofiarę za grzech swój, i ofiarę paloną twoję, a wykonaj oczyszczenie za się i za lud; uczyń też ofiarę od ludu, i uczyń oczyszczenie za lud, jako rozkazał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Tedy przystąpił Aaron do ołtarza, i zabił cielca na ofiarę za grzech swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'I podali mu synowie Aaronowi krew, który omoczywszy palec swój we krwi pomazał rogi ołtarza, a ostatek krwi wylał u spodku ołtarza;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Ale tłustość z nerkami, i odzieczkę z wątrobą z ofiary za grzech spalił na ołtarzu, jako był rozkazał Pan Mojżeszowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Mięso zaś i skórę spalił ogniem precz za obozem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Zabił też ofiarę całopalenia; i podali mu synowie Aaronowi krew, którą pokropił wierzch ołtarza w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Przynieśli mu też ofiarę całopalenia, i sztuki jej i głowę jej; a spalił ją na ołtarzu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Omył też wnętrzności, i nogi, i spalił je z ofiarą całopalenia na ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Potem sprawował ofiarę wszystkiego ludu, i wziął kozła na ofiarę za grzech ludu, którego zabił, i ofiarował go, jako i pierwszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Ofiarował też ofiarę całopalenia, i uczynił jej według zwyczaju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Ofiarował też ofiarę śniedną, a wziąwszy z niej pełną garść swoję, spalił na ołtarzu oprócz ofiary całopalenia porannej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Zabił też wołu, i barana na ofiarę spokojną, która była za lud; i podali mu synowie Aaronowi krew, którą pokropił ołtarz z wierzchu około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Podali mu także tłustość z wołu, i z barana ogon, i tłustość okrywającą wnętrzności i nerki, i odzieczkę z wątroby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Włożyli też tłustości na mostek, i spalili też tłustość na ołtarzu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Ale mostek i łopatkę prawą obracał Aaron tam i sam na ofiarę obracania przed obliczem Pańskiem, jako był Pan rozkazał Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Tedy podniósłszy Aaron ręce swe do ludu błogosławił im, a zstąpił od ofiarowania ofiary za grzech, i ofiary całopalenia, i ofiary spokojnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'I wszedł Mojżesz i Aaron do namiotu zgromadzenia, a wszedłszy błogosławili ludowi; i okazała się chwała Pańska wszystkiemu ludowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Bo zstąpiwszy ogień od obliczności Pańskiej spalił na ołtarzu ofiarę całopalenia i tłustości; co gdy widział wszystek lud, wykrzykali a padali na twarzy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Tedy synowie Aaronowi, Nadab i Abiju, wziąwszy każdy kadzielnicę swoję, włożyli w nią ognia, i włożywszy nań kadzidła ofiarowali przed obliczem Pańskiem ogień obcy, czego im był nie rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Przetoż wyszedłszy ogień od twarzy Pańskiej, poraził je; i pomarli przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Zatem rzekł Mojżesz do Aarona: Toć to jest, co powiedział Pan, mówiąc: W tych, którzy przystępują do mnie, poświęcony będę, i przed oblicznością wszystkiego ludu uwielbiony będę; i zamilkł Aaron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Tedy wezwał Mojżesz Misaela i Elisafana, synów Husyjela, stryja Aaronowego, i rzekł do nich: Przystąpcie, a wynieście bracią waszę z świątnicy precz za obóz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Przyszli tedy, a wynieśli je i z szatami ich precz za obóz, jako był rozkazał Mojżesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Rzekł potem Mojżesz do Aarona i do Eleazara i do Itamara, synów jego: Głów waszych nie obnażajcie, ani szat swych rozdzierajcie, byście nie pomarli, a Bóg nie rozgniewał się na wszystko zgromadzenie. Ale bracia wasi, wszystek dom synów Izraelskich, niech płaczą tego spalenia, które uczynił Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Ze drzwi też namiotu zgromadzenia nie wychodźcie, byście snać nie pomarli; albowiem olejek pomazania Pańskiego jest na was. I uczynili według rozkazania Mojżeszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Zatem rzekł Pan do Aarona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Wina i napoju mocnego nie będziesz pił, ty i synowie twoi z tobą, gdy będziecie mieli wchodzić do namiotu zgromadzenia, abyście nie pomarli; ustawa to wieczna będzie w narodziech waszych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Abyście rozeznawać mogli między rzeczą świętą, i między rzeczą pospolitą, i między rzeczą nieczystą, i między rzeczą czystą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Ażebyście nauczali synów Izraelskich wszystkich ustaw, które im rozkazał Pan przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Mówił potem Mojżesz do Aarona i do Eleazara i Itamara, synów jego, którzy byli pozostali: Weźmijcie ofiarę śniedną, która została od ognistych ofiar Pańskich, a jedzcie ją z przaśnikami przy ołtarzu; bo rzecz najświętsza jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Przetoż jeść ją będziecie na miejscu świętem, bo to prawo twoje, i prawo synów twoich, z ognistych ofiar Pańskich; bo mi tak rozkazano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Także mostek obracania, i łopatkę podnoszenia będziecie jedli na miejscu czystem, ty i synowie twoi, i córki twoje z tobą; albowiem to prawem tobie, i prawem synom twoim dano z ofiar spokojnych synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Łopatkę podnoszenia, i mostek obracania z ofiarami ognistemi, i tłustością przyniosą, aby je tam i sam obracano przed obliczem Pańskiem; a to będzie tobie i synom twoim z tobą prawem wiecznem, jako rozkazał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Potem Mojżesz szukał pilnie kozła ofiarowanego za grzech, a oto, już spalony był; i dla tego rozgniewawszy się na Eleazara i Itamara, syny Aaronowe, którzy byli pozostali, mówił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Przeczżeście nie jedli ofiary za grzech na miejscu świętem? albowiem to jest rzecz najświętsza, ponieważ ją wam dano, abyście nosili nieprawość wszystkiego ludu na oczyszczenie ich przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'A oto, nie jest wniesiona krew jego wewnątrz do świątnicy; mieliście go jeść w świątnicy, jakom rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Tedy Aaron odpowiedział Mojżeszowi: Oto, dziś ofiarowali ofiarę swoją za grzech, i ofiarę całopalenia swego przed obliczem Pańskiem, a oto mię spotkało; gdybym był jadł dziś ofiarę za grzech, izaliby się to było podobało Panu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'To gdy usłyszał Mojżesz, przestał na tem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Potem mówił Pan do Mojżesza i do Aarona, i rzekł do nich: Powiedzcie synom Izraelskim, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Te są zwierzęta, które jeść będziecie ze wszystkich zwierząt, które są na ziemi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Wszelkie bydlę, które ma rozdzielone stopy, i rozdwojone kopyta, a przeżuwa, to jeść będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Ale z tych jeść nie będziecie, które tylko przeżuwają, i z tych, które tylko kopyta dwoją: Wielbłąd, który choć przeżuwa, ale kopyta rozdzielonego nie ma, nieczystym wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Także królik, który choć przeżuwa, ale kopyta rozdzielonego nie ma, nieczystym wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Zając też, choć przeżuwa, ale kopyta rozdzielonego nie ma, nieczystym wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Świnia także, choć ma rozdzielone stopy i rozdwojone kopyto, ale iż nie przeżuwa, nieczystą wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Mięsa ich nie będziecie jeść, ani ścierwu ich dotykać się będziecie, nieczyste wam będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'To jeść będziecie ze wszystkich rzeczy żyjących w wodach, wszystko co ma skrzele i łuskę, w wodach, w morzu, i w rzekach, to jeść będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Wszystko zaś, co nie ma skrzeli i łuski w morzu i w rzekach, cokolwiek się rucha w wodach i każda rzecz żywiąca, która jest w wodach obrzydliwością wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Obrzydliwością będą wam; mięsa ich jeść nie będziecie, a ścierwem ich brzydzić się będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Owa cokolwiek nie ma skrzeli i łuski w wodach, obrzydliwością wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Tem się też brzydzić będzie z ptastwa, i jeść ich nie będziecie, bo są obrzydliwością; jako orła, i gryfa, i morskiego orła,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'I sępa, i kani, według rodzaju ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Każdego kruka według rodzaju jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'Także strusia, i sowy i wodnej kani i jastrzębia, według rodzaju ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'I puchacza, i norka i lelka,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'I łabędzia, i bąka, i bociana,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'I czapli, i sojki, według rodzaju ich, i dudka, i nietoperza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Wszystko, co się czołga po ziemi skrzydła mając, a na czterech nogach chodzi, obrzydliwością wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Wszakże jeść będziecie wszystko, co się czołga po ziemi skrzydła mające, co na czterech nogach chodzi, co ma w nogach ścięgneczka przedłuższe ku skakaniu na nich po ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Te z nich jeść będziecie: Szarańczą według rodzaju jej, i koniki według rodzaju ich, i skoczki według rodzaju ich, i chrząszcze według rodzaju ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Wszystko zaś, co się czołga po ziemi skrzydlaste, cztery nogi mające, obrzydliwością wam będzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Bo się niemi pokalacie. Kto by się dotknął zdechliny ich, nie będzie czystym aż do wieczora;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'A ktobykolwiek nosił ścierw ich, upierze szaty swoje, i będzie nieczystym aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Wszelkie bydlę, które ma rozdzieloną stopę, a kopyta rozdwojonego nie ma, ani też przeżuwa, nieczyste wam będzie; kto by się go dotknął, nieczystym będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'A cokolwiek chodzi na łapach swych ze wszystkich zwierząt, które chodzą na czterech nogach, nieczyste wam będzie; kto by się dotknął ścierwu ich, nieczystym będzie aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'A kto by nosił ścierw ich, upierze odzienie swe, a nieczystym będzie aż do wieczora, bo nieczyste wam są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Także i te za nieczyste mieć będziecie między płazami, które się włóczą po ziemi, łasica, i mysz, i żaba według rodzajów swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'I jeż, i jaszczurka, i tchórz, i ślimak, i kret.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Te nieczyste wam będą między wszystkiemi płazami; kto by się dotknął zdechliny ich, nieczystym będzie aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'A każda rzecz, na którą by co zdechłego z tych rzeczy upadło, nieczysta będzie, tak drzewiane naczynie, jako szata, tak skóra, jako wór; owa każde naczynie, w którem co sprawują, do wody włożone będzie, i nieczyste zostanie aż do wieczora, potem czyste będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Wszelkie zaś naczynie gliniane, w które by co z tych rzeczy wpadło, ze wszystkiem, coby w niem było, nieczyste się stanie, a samo stłuczone będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Każda też potrawa, którą jadają, gdyby wody nieczystej do niej wlano, nieczystą będzie; i wszelki napój, który pijają z każdego takiego naczynia, nieczystym będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Owa wszystko, na coby upadło co z onych zdechlin, nieczyste będzie; piec i ognisko rozwalone będą, bo nieczyste są, i za nieczyste wam będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Ale studnia i cysterna, i każde zgromadzenie wód czyste będą; coby się jednak dotknęło ścierwu tych rzeczy, nieczyste będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'A jeźliby upadło nieco z ścierwu ich na jakie nasienie, które siane bywa, czyste zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Ale jeźliby na nasienie w wodzie moczone upadło co z ścierwu ich, nieczyste wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Jeźliby zdechło bydlę, które jadacie: kto by się dotknął ścierwu jego, nieczystym będzie aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'A kto by jadł ścierw jego, upierze szaty swoje, i nieczystym będzie aż do wieczora; ten, coby precz wynosił on ścierw, upierze szaty swoje, i nieczystym będzie aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Wszelki także płaz, co się czołga po ziemi, obrzydliwością jest; nie będziecie go jeść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Cokolwiek się czołga po brzuchu, i cokolwiek na czterech albo więcej nogach się włóczy między wszystkim płazem, który się czołga po ziemi, nie będziecie ich jeść, bo obrzydliwością są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Nie plugawcie dusz waszych wszelkim płazem, który się czołga po ziemi, i nie mażcie się niemi, byście nie byli splugawieni przez nie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Albowiem Jam jest Pan Bóg wasz: przetoż poświęcajcie się, a bądźcie świętymi, bom Ja święty jest; a nie plugawcie dusz waszych żadnym płazem, który się czołga po ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Bom Ja jest Pan, którym was wywiódł z ziemi Egipskiej, abym wam był za Boga; przetoż bądźcie świętymi, bom Ja święty jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Tać jest ustawa około bydła, i ptastwa, i wszelkiej duszy żywej, która się rucha w wodach, i wszelkiej duszy żywej, która się czołga po ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Ku rozeznaniu między nieczystem i między czystem, a między zwierzęty, które się jeść godzi, i między zwierzęty, których się jeść nie godzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Powiedz synom Izraelskim, i rzecz: Niewiasta, która by poczęła i urodziła mężczyznę, nieczysta będzie przez siedem dni: według dni, których odłączona bywa dla choroby swej, nieczysta będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'A dnia ósmego obrzezane będzie ciało nieobrzeski jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Ale ona przez trzydzieści dni i trzy dni zostanie we krwi oczyszczenia; żadnej rzeczy świętej nie dotknie się, i ku świątnicy nie pójdzie, aż się wypełnią dni oczyszczenia jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'A jeźli dzieweczkę urodzi, nieczysta będzie przez dwie niedziele według oddzielenia swego, a sześćdziesiąt dni i sześć dni zostanie we krwi oczyszczenia swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'A gdy się wypełnią dni oczyszczenia jej po synu albo po córce, przyniesie baranka rocznego na ofiarę całopalenia, i gołąbiątko, albo synogarlicę na ofiarę za grzech do drzwi namiotu zgromadzenia do kapłana;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Którego ofiarować będzie przed obliczem Pańskiem, i oczyści ją; a tak oczyszczona będzie od pływania krwi swojej. Tać jest ustawa tej, która porodziła mężczyznę albo dzieweczkę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'A jeźli nie przemoże dać baranka, tedy weźmie parę synogarlic, albo parę gołąbiąt, jedno na ofiarę całopalenia a drugie na ofiarę za grzech; i oczyści ją kapłan, a tak oczyszczona będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Rzekł zasię Pan do Mojżesza i do Aarona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Człowiek, który by miał na skórze ciała swego sadzel, albo liszaj, albo białe blizny, tak iżby się na skórze ciała jego okazała plaga trądu, przywiedziony będzie do Aarona kapłana, albo do którego z synów jego kapłanów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Tedy ogląda kapłan on sadzel na skórze ciała jego; jeźliby włos na onym sadzelu pobielał, a on sadzel na spojrzeniu byłby głębszy, niż insza skóra ciała jego, plaga trądu jest; przetoż oglądawszy go kapłan, osądzi go być nieczystym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'A jeźliby biała tylko blizna była na skórze ciała jego, a nie byłaby głębsza na spojrzeniu, niż inna skóra, i włosy w niej nie pobielałyby, tedy zamknie kapłan mającego taką zarazę przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Potem obejrzy go kapłan dnia siódmego; a jeźliby ona blizna tak została w oczach jego, a nie szerzyła się ona blizna po skórze, tedy go zamknie kapłan przez siedem dni po wtóre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'I obejrzy go kapłan dnia siódmego po wtóre; a jeźliby ta zaraza poczerniała a nie szerzyłaby się ta zaraza po skórze, tedy go za czystego osądzi kapłan, bo świerzb jest; a on upierze szaty swe, a będzie czystym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Ale jeźliby się bardziej rozszerzał po skórze świerzb on po oglądaniu kapłanowem i po oczyszczeniu jego, pokaże się znowu kapłanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Tedy obejrzy go kapłan; a jeźliby się ta zaraza rozszerzała po skórze jego, osądzi go za nieczystego kapłan; bo trąd jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Zaraza trądu gdy będzie na człowieku, przywiedzion będzie do kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Którego obejrzy kapłan; a będzieli sadzel biały na skórze, żeby się uczyniły włosy białe, choćby i zdrowe ciało było na tym sadzelu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'Trąd zastarzały jest na skórze ciała jego; i osądzi go za nieczystego kapłan, a nie będzie go zawierał, gdyż nieczystym jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'A jeźliby się trąd rozszerzał na skórze, i okryłby trąd wszystkę skórę zarażonego od głowy jego aż do nóg jego, wszędy gdzie oczyma kapłan dojrzeć może;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'I obejrzy kapłan; a jeźli okrył trąd wszystko ciało jego, za czystą osądzi zarazę jego; bo iż wszystka pobielała, dla tego czysty jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Ale którego dnia okazałoby się na takowym mięso dziwie, nieczystym będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'A tak ogląda kapłan mięso dziwie, a osądzi go być za nieczystego; bo ono mięso dziwie nieczyste jest; trąd to jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Ale jeźliby zaś zginęło mięso dziwie, i obróciłoby się w białość, tedy przyjdzie do kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'A widząc go kapłan, iż się obróciła zaraza w białość, za czystego osądzi kapłan zarażonego; bo czystym jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Jeźliby zaś był na skórze ciała jego wrzód, a zagoiłby się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'A na miejscu wrzodu onego uczyniłby się sadzel biały, albo blizna biała zaczerwieniała, tedy okazana będzie kapłanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'A widząc kapłan, że na wejrzeniu głębsza jest, niż inna skóra, i włosy by jej pobielały, za nieczystego osądzi go kapłan; zaraza trądu jest, z wrzodu wyrosła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Ale jeźliby ją obaczył kapłan, że w niej włos nie bieleje, i nie jest głębsza nad inszą skórę, ale tylko naczerniała, tedy zamknie kapłan takowego przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'A jeźliby się szerzyła po skórze, za nieczystego osądzi go kapłan; zaraza to trądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Wszakże jeźliby blizna ona biała na swem miejscu zostawała; i nie szerzyłaby się, zapalenie wrzodu jest; przetoż za czystego osądzi go kapłan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Także ciało, na którego skórze byłaby sparzelina od ognia, a po zgojeniu onej sparzeliny byłaby blizna biała, zaczerwieniała, albo biała tylko,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'Ogląda to kapłan; a jeźliby włos w bliźnie pobielał i lśnił się, a na spojrzeniu byłaby głębsza ona blizna niż skóra, trąd jest z sparzeliny wyrosły; przetoż za nieczystego osądzi go kapłan, bo zaraza trądu jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'A jeźli kapłan obaczy, że na onej bliźnie białej włos nie pobielał, a iż nie jest głębsza nad inszą skórę, ale iż nieco naczerniała, zamknie kapłan takowego przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'I obejrzy go kapłan dnia siódmego; jeźliby się bardziej szerzyła po skórze, osądzi go za nieczystego kapłan: zaraza to trądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'A jeźliż ta blizna biała zostawa na swem miejscu, a nie szerzy się po skórze, ale się zaczerniwa, przyszczela z sparzenia jest; i osądzi go za czystego kapłan, bo blizna sparzeliny jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Gdyby mąż, albo niewiasta mieli jaką plamę na głowie albo na brodzie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'Tedy obejrzy kapłan onę plamę; a będzieli na spojrzeniu głębsza niż insza skóra, i byłby na niej włos pożółkły i subtelny, tedy takowego za nieczystego osądzi kapłan, zmaza jest; trąd na głowie albo na brodzie jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Ale jeźliby obaczył kapłan zarazę onej plamy, a oto na wejrzeniu jest głębsza nad inszą skórę, a nie byłby na niej włos czarny, zamknie kapłan zarazę plamy mającego przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Potem obejrzy kapłan tę zarazę dnia siódmego; a jeźli się nie szerzy zmaza, i nie masz na niej pożółkłego włosa, i na spojrzeniu ta zmaza nie byłaby głębsza nad inszą skórę:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'Tedy ogolony będzie ten człowiek, ale zmazy onej golić nie będzie; i zamknie kapłan mającego zmazę przez siedem dni po wtóre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'I ogląda kapłan onę zmazę dnia siódmego; a jeźli się nie rozszerzyła zmaza po skórze, a na spojrzeniu nie jest głębsza nad inszą skórę, osądzi go za czystego kapłan; a on uprawszy odzienie swoje, czystym będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'A jeźliby się poczęła szerzyć ona zmaza na skórze po oczyszczeniu jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Tedy obejrzy go kapłan; a jeźliż się szerzy ona zmaza po skórze, nie będzie więcej upatrował kapłan włosu żółtego; nieczystym jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Wszakże jeźli przed oczyma jego tak zostawa ona zmaza, i włos czarny wyrósłby na niej, zgoiła się ona zmaza, czysty jest i za czystego osądzi go kapłan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'A gdyby też na skórze ciała mężczyzny albo niewiasty były blizny białe,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'Tedy obejrzy je kapłan; a jeźliby się blizny one białe na skórze ciała jego zaczerniwały, blizna biała jest, wyrosła na skórze; czystym jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Mąż także, któremu by opadły włosy z głowy jego, łysy jest, i czysty jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'A jeźliżby przeciwko jednej stronie twarzy opadły włosy głowy jego, przełysiały jest, czysty jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Wszakże jeźliby na łysinie albo na tem przełysieniu, okazała się blizna biała a sczerwieniałaby, trąd wyrósł z łysiny jego albo z przełysienia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'I obejrzy go kapłan; a jeźliżby sadzel zarazy jego był biały, albo sczerwieniały na łysinie jego, albo na obłysieniu jego, na kształt trądu na skórze ciała:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'Takowy człowiek trędowaty jest, nieczysty jest, i osądzi go bezpiecznie kapłan za nieczystego; bo na głowie jego jest trąd jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Trędowaty zaś, który by miał na sobie tę zarazę, szaty jego będą rozdarte, i głowa jego będzie odkryta, i usta sobie zakryje; a wołać będzie: Nieczysty, nieczysty jestem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Po wszystkie dni, póki jest zaraza na nim, nieczystym będzie, bo nieczystym jest, sam będzie mieszkał; precz za obozem będzie mieszkanie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Jeźliby też na szacie była zaraza trądu, na szacie suknianej albo na szacie lnianej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'Albo na osnowie, albo na wątku ze lnu albo z wełny, albo na skórze, albo na jakiejkolwiek rzeczy skórzanej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'A byłaby ta zaraza zielona, albo czerwona na szacie, albo na skórze albo na osnowie, albo na wątku, albo na jakiemkolwiek naczyniu skórzanem, zaraza trądu jest; będzie ukazana kapłanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'A oglądawszy kapłan zarazę onę, zamknie onę rzecz zarażoną przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Potem obejrzy zarazę onę dnia siódmego: jeźliby się szerzyła zmaza ona na szacie, albo na osnowie, albo na wątku, albo na skórze, i na każdej rzeczy z skóry urobionej, trąd jest jadowity, zaraza nieczysta jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Tedy spali tę szatę, albo osnowę, albo wątek z wełny, albo ze lnu, albo jakiekolwiek naczynie skórzane, na którem by była zaraza: albowiem jest trąd jadowity, ogniem spalono będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Ale gdyby obaczył kapłan, iż ona zmaza nie szerzy się na szacie, albo na osnowie, albo na wątku, albo na jakimkolwiek naczyniu skórzanem');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'Rozkaże kapłan, aby uprano to, na czem jest zaraza, i zamknie to przez siedem dni po wtóre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'I obejrzy kapłan po upraniu onę zarazę; a jeźli nie odmieniła ona zaraza barwy swojej, choćby się ona zaraza nie rozszerzyła, rzecz nieczysta jest, ogniem ją spalisz; zaraźliwa rzecz jest, bądź na zwierzchniej bądź na spodniej stronie jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Wszakże, jeźliby kapłan obaczył, iż przyczerniejsza będzie zaraza po wypraniu swem, odedrze ją od szaty, albo od skóry, albo od osnowy, albo od wątku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'A jeźliby się jeszcze ukazała na szacie, albo na osnowie, albo na wątku, albo na jakiem naczyniu skórzanem, trąd jest szerzący się: ogniem to spalisz, na czem by była takowa zaraza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Szatę zaś, albo osnowę, albo wątek, albo każde naczynie skórzane, które byś uprał, a odeszłaby od niego zaraza, upierzesz je po wtóre, a czyste będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Tać jest ustawa o zarazie trądu, na szacie suknianej, albo lnianej albo na osnowie, albo na wątku, albo na jakiemkolwiek naczyniu skórzanem, jako to ma być rozeznano, iż jest czyste albo nieczyste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Tać jest ustawa około trędowatego w dzień oczyszczenia jego: przywiedziony będzie do kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'A wynijdzie kapłan precz za obóz: a obaczyli kapłan, że oto uleczona jest zaraza trądu, trądem zarażonego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'Tedy rozkaże kapłan temu, który się oczyszcza, aby wziął dwa wróble żywe i zdrowe, i drzewo cedrowe, i jedwabiu karmazynowego, i hizopu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'I rozkaże kapłan zabić jednego wróbla nad naczyniem glinianem, nad wodą żywą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Wróbla tedy żywego weźmie, i drzewo cedrowe, i jedwab karmazynowy i hizop, a omoczy to wszystko z wróblem żywym we krwi wróbla zabitego nad wodą żywą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'I pokropi tego, który się oczyszcza od trądu, siedem kroć, i ogłosi go być czystym, a puści wróbla żywego w pole.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'A ten, który się oczyszcza, upierze szaty swoje, i ogoli wszystkie włosy swoje, a umyje się wodą, i czystym będzie. Potem wnijdzie do obozu, a będzie mieszkał przed namiotem swoim przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Potem dnia siódmego ogoli wszystkie włosy swe, głowę swą, i brodę swą, i brwi nad oczyma swemi, i wszystkie inne włosy swe ogoli; przytem upierze szaty swe, i ciało swe omyje wodą, a tak oczyszczon będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'A dnia ósmego weźmie dwu baranków zupełnych, i owcę jednę roczną, zupełną, i trzy dziesiąte części efy mąki pszennej na ofiarę śniedną, zmieszaną z oliwą, i miarkę oliwy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Tedy kapłan, który oczyszcza człowieka, który ma być oczyszczony, postawi z temi rzeczami przed Panem, u drzwi namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Potem weźmie kapłan barana jednego, i będzie go ofiarował na ofiarę za występek, z oną miarką oliwy, i będzie to tam i sam obracał na ofiarę obracania przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Zabije też baranka onego na miejscu, gdzie biją ofiary za grzech i ofiarę całopalenia, na miejscu świętem; bo jako ofiara za grzech tak ofiara za występek należy kapłanowi; rzecz najświętsza jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'I weźmie kapłan krwi z ofiary za występek, i pomaże kapłan koniec ucha prawego onemu, który się oczyszcza; także palec wielki u prawej ręki jego i palec wielki u prawej nogi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Weźmie też kapłan z onej miarki oliwy, a naleje na dłoń swoję lewą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'A omoczy palec swój prawy w oliwie, która jest na lewej dłoni jego, i pokropi oliwą z palca swego siedem kroć przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'A z ostatku oliwy, która jest na dłoni jego, pomaże kapłan koniec ucha prawego onemu, który się oczyszcza, i wielki palec prawej ręki jego, także wielki palec prawej nogi jego z onejże krwi, która jest ofiarą za występek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'A coby zostało oliwy, która jest na dłoni kapłanowej, pomaże tem głowę onego, który się oczyszcza; i tak go oczyści kapłan przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Uczyni także kapłan ofiarę za grzech, i oczyści tego, który się oczyszcza, od nieczystości jego, a potem zabije ofiarę całopalenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'I ofiarować będzie kapłan ofiarę całopalenia, i ofiarę śniedną na ołtarzu; tak oczyści go kapłan, i czystym będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'A jeźliby kto był tak ubogi, iżby tego nie przemógł, tedy weźmie baranka jednego na ofiarę za występek na podnoszenie dla oczyszczenia swego, i jednę dziesiątą część efy mąki pszennej zagniecionej z oliwą na ofiarę śniedną i miarkę oliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Nad to dwie synogarlice, albo dwoje gołąbiąt, czego dostać może, z których jedno będzie na ofiarę za grzech, a drugie na ofiarę całopalenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'I przyniesie je w ósmy dzień oczyszczenia swego do kapłana, do drzwi namiotu zgromadzenia, przed obliczność Pańską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Weźmie tedy kapłan baranka ofiary za występek, i miarkę oliwy; i będzie to obracał tam i sam kapłan na ofiarę obracania przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'A zabije baranka na ofiarę za występek: a wziąwszy kapłan ze krwi ofiary za występek, pomaże koniec ucha prawego temu, który się oczyszcza; i palec wielki prawej ręki jego, i palec wielki prawej nogi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Oliwy także naleje kapłan na lewą dłoń swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'I kropić będzie kapłan palcem swoim prawym z oliwy, która jest na lewej ręce jego siedem kroć przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Pomaże też kapłan oną oliwą, która jest na dłoni jego, koniec ucha prawego temu, który się oczyszcza; także wielki palec prawej ręki jego, i wielki palec prawej nogi jego na miejscu krwi z ofiary za występek;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'A ostatkiem oliwy, która jest na dłoni kapłana, pomaże głowę onego, który się oczyszcza, aby go oczyścił przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Także uczyni z jedną synogarlicą, albo z jednem gołębięciem, czegokolwiek z tych dostać może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'Czego dostać mógł, jedno z tych będzie ofiarą za grzech, a drugie na ofiarę całopalenia z ofiarą śniedną; a tak oczyści kapłan tego, który się oczyszcza przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'A tać jest ustawa o tym, na którym by była zaraza trądu, który wszystkiego mieć nie może ku oczyszczeniu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Rzekł potem Pan do Mojżesza i do Aarona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Gdy wnijdziecie do ziemi Chananejskiej, którą Ja wam dawam w osiadłość, a dopuściłbym zarazę trądu na który dom osiadłości waszej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'Tedy on, którego dom jest, przyjdzie i opowie to kapłanowi, mówiąc: Jakoby zaraza trądu zda mi się być w domu moim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Rozkaże tedy kapłan wyprzątnąć dom pierwej niż sam wnijdzie, aby oglądał zarazę onę, iżby się nic nie splugawiło, coby było w domu, a potem kapłan wnijdzie, aby oglądał on dom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'A oglądając onę zarazę, ujrzeli zarazę na ścianie domu, jakoby dołki czarne, przyzieleńszym, albo przyczerwieńszym, a na spojrzeniu byłoby głębsze niż ściana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'Tedy wynijdzie kapłan z domu onego przede drzwi, i zamknie on dom przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Wróci się potem kapłan dnia siódmego i obejrzy; a jeźli się rozszerzyła zaraza na ścianach domu onego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'Rozkaże kapłan wyłamać ono kamienie, na którem by była zaraza, i wyrzucić je precz za miasto na miejsce nieczyste;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'A dom rozkaże wewnątrz oskrobać wszędy w około; i wyrzucą on proch który oskrobali, precz za miasto na miejsce nieczyste;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'I wezmą kamienie insze i wprawią na miejsce innych kamieni; i wapna też inszego wezmą a potynkują dom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'A jeźliby się odnowiła ona zaraza, i rozszerzyła się po domu po wyrzuceniu kamienia, i po wyskrobaniu domu i po tynkowaniu jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Tedy wnijdzie kapłan; a ujrzeli, że się rozszerzyła ona zaraza po domu, trąd jest jadowity w domu onym, nieczysty jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Zatem rozwalą on dom, kamienie jego, i drzewo jego i wszystko wapno domu onego, a wyniosą precz za miasto na miejsce nieczyste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'A ten kto by wszedł do domu onego, po wszystkie dni, póki był zawarty, nieczystym będzie aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'A kto by spał w onym domu, upierze szaty swoje; także kto by jadł w tymże domu, upierze szaty swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Lecz jeźliby wyszedłszy kapłan obaczył, iż się nie szerzy zaraza po domu po tynkowaniu jego, tedy osądzi kapłan, że dom on jest czysty; bo uleczona jest zaraza ona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'A weźmie na oczyszczenie onego domu dwu wróblów, i drzewo cedrowe, i jedwabiu, karmazynu, i hizopu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'I zabije wróbla jednego nad naczyniem glinianem, nad wodą żywą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'A wziąwszy drzewo cedrowe i hizop, i jedwab karmazynowy, i wróbla żywego, omoczy to wszystko we krwi wróbla zabitego i w wodzie żywej, a pokropi ten dom siedem kroć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'I tak oczyści on dom krwią wróbla onego, i wodą żywą i wróblem żywym i drzewem cedrowem, i hizopem, i jedwabiem czerwonym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Potem puści wróbla żywego precz za miasto w pole; tak oczyści on dom, i czystym będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Tać jest ustawa o każdej zarazie trądu, i plamy czarnej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'I o trądzie na szacie i na domu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'I o sadzelu, i o świerzbie, i o białej plamie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Żeby poznać, gdy kto jest nieczystym, i gdy kto czystym. Tać jest ustawa około trądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Rzekł potem Pan do Mojżesza i do Aarona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Powiedzcie synom Izraelskim, a mówcie do nich: Mąż, który by cierpiał płynienie nasienia z ciała swego, nieczysty jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'A tać będzie nieczystość płynienia jego: Jeźli wypuści ciało jego płynienie swe, albo żeby się to płynienie zastanowiło w ciele jego, nieczystość jego jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Każda pościel, na której by leżał płynienie cierpiący, nieczysta będzie, i wszystko, na czem by usiadł, nieczyste będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Kto by się dotknął pościeli jego, upierze szaty swoje, i umyje się wodą, a będzie nieczystym aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Kto by też siadł na tem, na czem ten siedział, co z niego nasienie płynie, upierze szaty swe, i umyje się wodą, a będzie nieczystym aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Jeźliby się też kto dotknął ciała męża cierpiącego płynienie, upierze szaty swe, i umyje się wodą, a będzie nieczystym aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'A jeźliby plunął płynienie cierpiący na czystego, oplwany upierze szaty swe, i umyje się wodą, a będzie nieczysty aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Każde też siodło, na którem by siedział płynienie cierpiący, nieczyste będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Kto by się też jakiejkolwiek rzeczy dotknął, która była po nim, nieczysty będzie aż do wieczora; a kto by co z tego nosił, upierze szaty swe, i umyje się wodą, a będzie nieczystym aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Także każdy, którego by się dotknął cierpiący płynienie, nie umywszy przedtem rąk swoich w wodzie, upierze szaty swoje, i umyje się wodą, i będzie nieczystym aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Naczynie też gliniane, którego by się dotknął, co płynienie cierpi, stłuczone będzie, a każde naczynie drzewiane wodą umyte będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'A gdyby oczyszczony był ten, który cierpi płynienie, od płynienia swego, naliczy sobie siedem dni podług swego oczyszczenia, i upierze szaty swe, i omyje ciało swoje wodą żywą, i będzie czystym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Potem dnia ósmego weźmie sobie dwie synogarlice, albo dwoje gołąbiąt, a przyszedłszy przed Pana do drzwi namiotu zgromadzenia, odda je kapłanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Tedy ofiarować będzie kapłan jedno z nich za grzech, a drugie na ofiarę całopalenia. Tak oczyści go kapłan przed obliczem Pańskiem od płynienia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'A mąż, z którego by wyszło nasienie złączenia, o myje wodą wszystko ciało swe, i będzie nieczystym aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Każda też szata, i każda skóra, na której by było nasienie złączenia, wyprana będzie wodą, a będzie nieczystą aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Niewiasta także, z którą by obcował mąż cierpiący płynienie nasienia, oboje umyją się wodą, a nieczystymi będą aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Także niewiasta, która by cierpiała chorobę swoję, a płynęłaby krew z ciała jej, przez siedem dni będzie w odłączeniu swem; każdy, coby się jej dotknął, nieczysty będzie aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Na czembykolwiek leżała w odłączeniu swem, nieczyste będzie; także na czem by siedziała, nieczyste będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Kto by się też dotknął pościeli jej, upierze szaty swe, i umyje się wodą, a będzie nieczysty aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Także kto by się dotknął tego, na czem by siedziała, upierze szaty swe, i umyje się wodą, a będzie nieczysty aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Jeźliby też co było na łożu jej, albo na czem by ona siedziała, a dotknąłby się kto tego, nieczystym będzie aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'A jeźliby mąż spał z nią, a zostałaby nieczystość jej na nim, nieczysty będzie przez siedem dni, i każde łoże, na którem by leżał, nieczyste będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Jeźliby też niewiasta płynienie krwi cierpiała przez wiele dni, mimo czasu miesiąców jej, albo żeby krwi płynienie cierpiała w zwyczajnej chorobie, tedy po wszystkie dni płynienia nieczystości swojej, jako i czasu choroby swojej, nieczystą będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Każda pościel jej, na której by leżała po wszystkie dni płynienia swego, jako pościel w przyrodzonej chorobie będzie, i każda rzecz, na której by siedziała, nieczysta będzie według nieczystości przyrodzonej choroby jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Kto by się kolwiek dotknął tych rzeczy, nieczystym będzie, i upierze szaty swe, i umyje się wodą, a będzie nieczystym aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'A gdy będzie oczyszczona od płynienia swego, naliczy sobie siedem dni, a potem oczyszczać się będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'A dnia ósmego weźmie sobie dwie synogarlice, albo dwoje gołąbiąt, i przyniesie je kapłanowi do drzwi namiotu zgromadzenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Z których ofiarować będzie kapłan, jedno na ofiarę za grzech, a drugie na ofiarę całopalenia: tak ją oczyści kapłan przed Panem od płynienia nieczystości jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Tak odłączać będziecie syny Izraelskie od nieczystości ich, aby nie pomarli w nieczystości swej, gdyby splugawili przybytek mój, który jest w pośrodku ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Tać jest ustawa około tego, który płynienie cierpi, i z którego wychodzi nasienie złączenia, dla czego splugawiony bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Także i około niewiasty, chorującej w odłączeniu swem, i każdego cierpiącego płynienie swe, tak mężczyzny, jako i niewiasty, i męża, który leżał z nieczystą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Potem mówił Pan do Mojżesza po śmierci dwu synów Aaronowych, którzy ofiarując przed Panem, pomarli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'I rzekł Pan do Mojżesza: Mów do Aarona, brata twego, niech nie wchodzi każdego czasu do świątnicy wewnątrz za zasłonę przed ubłagalnią, która jest na skrzyni, aby nie umarł, bo w obłoku okazować się będę nad ubłagalnią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'Ale tak wchodzić będzie Aaron do świątnicy z cielcem na ofiarę za grzech, a z baranem na ofiarę całopalenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'W szatę lnianą poświęconą oblecze się, a ubiory lniane będą na ciele jego; i pasem lnianym opasze się, i czapkę lnianą włoży na głowę; szaty święte są; i umyje wodą ciało swe, a oblecze się w nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'A od zgromadzenia synów Izraelskich weźmie dwu kozłów na ofiarę za grzech, i jednego baranka na całopalenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'I będzie ofiarował Aaron cielca swego na ofiarę za grzech, i uczyni oczyszczenie za się, i za dom swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Weźmie też dwu kozłów, a postawi je przed Panem u drzwi namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'I rzuci Aaron na oba kozły losy, los jeden Panu, a los drugi Azazelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'I będzie ofiarował Aaron onego kozła, na którego padł los Panu, i ofiarować go będzie za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Ale kozła, na którego padł los Azazela, postawi żywego przed Panem, aby oczyszczenie uczynił przezeń, a wypuścił go do Azazela na puszczę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'I będzie ofiarował Aaron cielca, na ofiarę za grzech twój, a oczyszczenie uczyni za się, i za dom swój, i zabije cielca na ofiarę za grzech swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Tedy weźmie pełną kadzielnicę węgla rozpalonego z ołtarza przed oblicznością Pańską, i pełne garści swe kadzenia wonnego utłuczonego i wniesie za zasłonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'A włoży ono kadzenie na ogień przed Panem, aby okrył dym kadzenia ubłagalnią, która jest nad świadectwem, a nie umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Potem wziąwszy ze krwi cielca onego, kropić będzie palcem swym na ubłagalni ku wschodowi słońca; także przed ubłagalnią kropić będzie siedem kroć tą krwią palcem swym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Zabije też kozła na ofiarę za grzech ludu, a wniesie wewnątrz krew jego za zasłonę; i uczyni ze krwią jego, jako uczynił ze krwią cielca, i kropić będzie nią nad ubłagalnią i przed ubłagalnią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Tak oczyści świątnicę od nieczystot synów Izraelskich, i od przestępstw ich, i od wszystkich grzechów ich; toż też uczyni namiotowi zgromadzenia, który jest między nimi, w pośrodku nieczystot ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'A żaden człowiek niech nie będzie w namiocie zgromadzenia, gdy on wchodzić będzie ku oczyszczaniu do świątnicy, aż wynijdzie i wykona oczyszczenie sam za się i za dom swój, i za wszystko zgromadzenie Izraelskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'I wynijdzie do ołtarza, który jest przed Panem, a oczyści go; i wziąwszy krwi cielcowej i krwi kozłowej, pomaże rogi ołtarza w około;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'A pokropi go z wierzchu tąż krwią palcem swym siedem kroć, a oczyści go, i poświęci go od nieczystot synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Potem gdy odprawi oczyszczenie świątnicy i namiotu zgromadzenia i ołtarza, ofiarować będzie kozła żywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'A włożywszy Aaron obie ręce swe na głowę kozła żywego, wyznawać będzie nad nim wszystkie nieprawości synów Izraelskich, i wszystkie przestępstwa ich ze wszystkiemi grzechami ich, a włoży je na głowę kozła onego, i wypuści go przez człowieka na to obranego na puszczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'A tak poniesie on kozieł na sobie wszystkie nieprawości ich do ziemi pustej; i wypuści kozła onego na puszczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Potem wróciwszy się Aaron do namiotu zgromadzenia, złoży z siebie szaty lniane, w które się był oblekł, wchodząc do świątnicy, i zostawi je tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Omyje też ciało swoje wodą, na miejscu świętem, i oblecze się w szaty swe; a wyszedłszy sprawować będzie ofiarę całopalenia swego, i ofiarę całopalenia ludu, i uczyni oczyszczenie za się, i za lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'A tłustość ofiary za grzech spali na ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'A ten, który zawiódł kozła do Azazela, upierze szaty swe; a omywszy ciało swoje wodą, potem wnijdzie do obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Cielca zaś ofiarowanego za grzech, i kozła za grzech, których krew wniesiona była ku sprawowaniu oczyszczenia do świątnicy, wyniosą precz za obóz, i spalą ogniem skóry ich, i mięso ich, i gnój ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'A ten, co je palić będzie, upierze szaty swoje, a omywszy ciało swoje wodą, potem wnijdzie do obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'To też będzie wam za ustawę wieczną: Miesiąca siódmego, dziesiątego dnia tegoż miesiąca, trapić będziecie dusze wasze, i żadnej roboty nie będziecie robić, tak w domu zrodzony, jako przychodzień, który gościem jest między wami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Bo w ten dzień oczyści was kapłan, abyście oczyszczeni byli od wszystkich grzechów waszych przed Panem oczyszczeni będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Sabatem odpocznienia będzie wam to, w który trapić będziecie dusze wasze ustawą wieczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'A oczyszczać będzie kapłan, który jest pomazany, a którego poświęcone są ręce ku sprawowaniu urzędu miasto ojca jego, a oblecze się w szaty lniane, w szaty święte;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'I oczyści świątnicę świętobliwości, i namiot zgromadzenia; i ołtarz oczyści, i kapłany, i wszystek lud zgromadzony oczyści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'I będzie to wam za ustawę wieczną ku oczyszczaniu synów Izraelskich od wszystkich grzechów ich raz w rok. I uczynił Mojżesz, jako mu był rozkazał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Tedy rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Mów do Aarona i do synów jego, i do wszystkich synów Izraelskich, a powiedz im: Tać jest rzecz, którą przykazał Pan mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Ktobykolwiek z domu Izraelskiego zabił wołu, albo owcę, albo kozę w obozie, albo kto by zabił za obozem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'A do drzwi namiotu zgromadzenia nie przywiódłby tego, aby ofiarował ofiarę Panu, przed przybytkiem Pańskim, krwi winien będzie on mąż, krew przelał; przetoż wytracony będzie on mąż z pośrodku ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Synowie tedy Izraelscy przywiodą ofiary swoje, które zabijali na polu; przywiodą je Panu do drzwi namiotu zgromadzenia, do kapłana; a tak niechaj sprawują ofiary spokojne Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'I wyleje kapłan krew na ołtarz Pański u drzwi namiotu zgromadzenia, a spali tłustość ku wdzięcznej wonności Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'I nie będą ofiarować więcej ofiar swych dyjabłom, z którymi cudzołożyli; ta ustawa wieczna będzie im w narodziech ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Nadto im jeszcze powiedz: Jeźliby kto z domu Izraelskiego, albo z przychodniów między wami mieszkających chciał ofiarować ofiarę całopalenia, albo inszą ofiarę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'A do drzwi namiotu zgromadzenia nie przywiódłby jej, aby ją ofiarował Panu, wytracony będzie człowiek ten z ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'A ktobykolwiek z domu Izraelskiego, albo z przychodniów którzy by gośćmi byli między nimi, jadł krew jaką, postawię rozgniewaną twarz swą przeciwko człowiekowi krew jedzącemu, i wygładzę go z pośrodku ludu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Albowiem dusza wszelkiego ciała we krwi jego jest; a Ja dałem ją wam na ołtarz ku oczyszczeniu dusz waszych; bo krew jest, która duszę oczyszcza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Dla tegoż powiedziałem synom Izraelskim: Żaden między wami nie będzie jadał krwi; ani przychodzień, który gościem jest między wami, nie będzie jadał krwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'I ktobykolwiek z synów Izraelskich, albo z przychodniów, którzy są gośćmi między wami, goniąc ułowił jakie zwierzę albo ptaka, co się godzi jeść, tedy krew z niego wypuści, i zasypie ją piaskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Bo dusza każdego ciała jest krew jego, która jest miasto duszy jego; przetożem powiedział synom Izraelskim: Krwi wszelkiego ciała jeść nie będziecie; bo dusza wszelkiego ciała jest krew jego; kto by ją kolwiek jadł, wytracony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Jeźliby też kto jadł co zdechłego, albo od zwierza rozszarpanego, tak w domu zrodzony, jako przychodzień, tedy upierze szaty swoje i omyje się wodą, a nieczystym będzie aż do wieczora; potem czysty będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Ale jeźliby nie uprał szat swoich, a ciała swego nie omył, poniesie nieprawość swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Rzekł jeszcze Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Mów do synów Izraelskich, i rzecz im: Jam jest Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Według obyczajów ziemi Egipskiej, w którejście mieszkali, nie czyńcie, ani według obyczajów ziemi Chananejskiej, do której Ja was prowadzę, nie czyńcie, a w ustawach ich nie chodźcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Sądy moje czyńcie, a ustaw moich strzeżcie, abyście chodzili w nich; Jam Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Przestrzegajcież tedy ustaw moich i sądów moich: które zachowywając człowiek, będzie w nich żył; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Żaden człowiek do bliskiej pokrewnej swojej nie przystępuj, aby odkrył sromotę jej; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Sromoty ojca twego, także sromoty matki twojej nie odkryjesz; matką twoją jest, nie odkryjesz sromoty jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Sromoty żony ojca twego nie odkryjesz; sromota ojca twego jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Sromoty siostry twej, córki ojca twego, także córki matki twojej, tak rodzonej, jako i przyrodniej, nie odkryjesz sromoty ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Sromoty córki syna twego, także sromoty córki córki twojej, nie odkryjesz; bo to sromota twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Sromoty córki żony ojca twego, która się narodziła z ojca twego, siostra twoja jest, nie odkryjesz sromoty jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Sromoty siostry ojca twego nie odkryjesz; bo jest pokrewna ojca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Sromoty siostry matki twojej nie odkryjesz; bo pokrewna matki twojej jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Sromoty brata ojca twego nie odkryjesz, do żony jego nie wnijdziesz; żona stryja twego jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Sromoty synowej twojej nie odkryjesz; żona jest syna twego, nie odkryjesz sromoty jej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Sromoty żony brata twego nie odkryjesz: sromota brata twego jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Sromoty żony, i córki jej, nie odkryjesz; córki syna jej, i córki córki jej nie pojmiesz, abyś odkrył sromotę jej; bo pokrewne są, i sprośna to rzecz jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Siostry żony twej nie pojmuj, abyś jej nie trapił, odkrywając sromotę jej, póki ona żywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Do niewiasty, gdy jest w odłączeniu nieczystości, nie przystępuj, abyś odkrył sromotę jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Z żoną bliźniego twego obcować nie będziesz, bo byś się splugawił z nią,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Z nasienia twego nie dopuszczaj ofiarować Molochowi, abyś nie splugawił imienia Boga twego; Jam Pan');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Z mężczyną nie będziesz obcował, jako z niewiastą; obrzydliwością to jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Także z bydlęciem żadnem obcować nie będziesz, abyś się z niem miał splugawiać. Niewiasta też niech nie podlega bydlęciu dla obcowania z nim; sprośna rzecz jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Nie plugawcież się temi wszystkiemi rzeczami; bo tem wszystkiem splugawili się poganie, które Ja wyrzucam przed obliczem waszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Bo splugawiła się ziemia; przetoż nawiedzę nieprawość jej na niej, i wyrzuci ziemia obywatele swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'A tak wy przestrzegajcie ustaw moich i sądów moich, a nie czyńcie żadnych obrzydliwości tych, w domu zrodzony, i przychodzień, który jest gościem w pośrodku was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Albowiem wszystkie te obrzydliwości czynili ludzie tej ziemi, którzy byli przed wami, czem splugawiona jest ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Aby was nie wyrzuciła ziemia, gdybyście ją splugawili, jako wyrzuciła naród, który był przed wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Albowiem ktobykolwiek co uczynił z tych wszystkich obrzydliwości, zaiste wytracone będą dusze to czyniące z pośrodku ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Strzeżcież tedy ustaw moich, nie czyniąc ustaw obrzydliwych, które czyniono przed wami, ani się plugawcie niemi; Jam Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Mów do wszystkiego zgromadzenia synów Izraelskich, a powiedz im: Świętymi bądźcie, bom Ja jest święty, Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Każdy matki swojej i ojca swego bójcie się, a sabatów moich przestrzegajcie; Jam Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Nie udawajcie się za bałwany, a bogów litych nie czyńcie sobie; Jam Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'A gdy ofiarować będziecie ofiarę spokojną Panu, tedy z dobrej woli swej ofiarować ją będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'W dzień, którego ofiarować będziecie, jedzcie ją i nazajutrz; ale coby zostało aż do trzeciego dnia, ogniem spalone będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'A jeźlibyście to jedli dnia trzeciego, obrzydłe będzie, i nie przyjemne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Ktobykolwiek to jadł, karanie za nieprawość swoję poniesie, bo świętość Pańską splugawił; przetoż wytracona będzie dusza ona z ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Gdy będziecie żąć zboża ziemi waszej, nie będziesz do końca pola twego wyrzynał, ani pozostałych kłosów żniwa twego zbierać będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Także winnicy twojej gron do szczętu obierać nie będziesz, ani jagód opadających z winnicy twej nie pozbierasz; ubogiemu i przychodniowi zostawisz je; Jam Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Nie kradnijcie, ani zapierajcie, i nie oszukiwajcie żaden bliźniego swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Nie przysięgajcie fałszywie przez imię moje, i nie lżyj imienia Boga twego; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Nie uciskaj gwałtem bliźniego twego, ani go odzieraj; nie zostanie zapłata najemnika u ciebie do jutra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Nie złorzecz głuchemu, a przed ślepym nie kładź zawady, ale się bój Boga twego; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Nie czyń nieprawości w sądzie. Nie oglądaj się na osobę ubogiego, ani szanuj osoby bogatego; sprawiedliwie sądź bliźniego twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Nie będziesz chodził jako obmówca między ludem twoim; nie będziesz stał o krew bliźniego twego; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Nie będziesz nienawidził brata twego w sercu twojem; jawnie strofować będziesz bliźniego twego, a nie ścierpisz przy nim grzechu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Nie mścij się, i nie chowaj gniewu przeciw synom ludu twego; ale miłuj bliźniego twego, jako siebie samego; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Ustaw moich przestrzegajcie; bydlęcia twego nie spuszczaj z bydlęty rodzaju inszego; pola twego nie osiewaj z mieszanem nasieniem; także szaty z różnych rzeczy utkanej, jako z wełny i ze lnu, nie obłócz na się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Jeźliby mąż spał z niewiastą, i obcował z nią, a ona będąc niewolnicą, byłaby mężowi poślubiona, a nie byłaby okupiona, ani wolnością darowana, oboje będą karani; ale nie na gardle, ponieważ nie była wolno puszczoną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'I przywiedzie ofiarę za występek swój Panu do drzwi namiotu zgromadzenia, barana za występek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Tedy oczyści go kapłan przez onego barana za występek przed Panem od grzechu jego, którym zgrzeszył; a będzie mu odpuszczony grzech jego, który popełnił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Gdy też wnijdziecie do ziemi, a naszczepicie wszelakiego drzewa rodzącego owoc, tedy oberzniecie nieobrzezkę jego, owoce jego; przez trzy lata miejcie je za nieobrzezanie, i jeść ich nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Ale roku czwartego wszystek owoc ich poświęcony będzie na ofiarę chwały Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'A piątego roku jeść będziecie owoc jego, aby się wam rozmnożył urodzaj jego; Jam Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Nie jedzcie nic ze krwią. Nie bawcie się wieszczbami, ani czarami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Nie strzyżcie w koło włosów głowy waszej, ani brody swojej oszpecajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Dla umarłego nie rzeżcie ciała waszego, ani żadnego piątna na sobie nie czyńcie; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Nie podasz na splugawienie córki twej, dopuszczając jej wszeteczeństwa, aby się ziemia nie splugawiła, i nie była napełniona ziemia sprośnością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Sabaty moje zachowywajcie, a świątnicę moję w uczciwości miejcie; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Nie udawajcie się do czarowników, ani do wieszczków, ani od nich rady szukajcie, abyście się od nich nie splugawili; Jam Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Przed człowiekiem sędziwym powstań, a czcij osobę starego, i bój się Boga swego; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Będzieli mieszkał z tobą przychodzień w ziemi waszej, nie czyńcie mu krzywdy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Jako jeden z waszych w domu zrodzonych będzie u was przychodzień, który jest u was gościem, i miłować go będziesz jako sam siebie; boście i wy przychodniami byli w ziemi Egipskiej; Jam Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Nie czyńcie nieprawości w sądzie; w rozmierzaniu, w wadze, i w mierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Szale sprawiedliwe, gwichty sprawiedliwe, korzec sprawiedliwy i kwartę sprawiedliwą mieć będziecie; Jam jest Pan, Bóg wasz, którym was wywiódł z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Przetoż strzeżcie wszystkich ustaw moich, i wszystkich sądów moich, a czyńcie je; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Powiedz synom Izraelskim: Ktobykolwiek z synów Izraelskich, albo z przychodniów mieszkających w Izraelu ofiarował potomstwo swoje Molochowi, śmiercią niech umrze; lud ziemi niechaj go ukamionuje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Bo Ja postawię twarz moję rozgniewaną przeciwko temu mężowi, i wytracę go z pośrodku ludu jego, przeto, iż potomstwo swoje ofiarował Molochowi, i splugawił świątnicę moję, a zmazał imię świątobliwości mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'A jeźliby lud ziemi nie dbając przeglądał mężowi takiemu, który by ofiarował Molochowi potomstwo swe, i nie zabiłby go:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'Tedy Ja postawię twarz moję zagniewaną przeciw temu mężowi i przeciw domowi jego, i wytracę go i wszystkie, którzy cudzołożąc, szliby za nim, aby cudzołożyli, naśladując Molocha, z pośrodku ludu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Człowiek, który by się udał do czarowników, i do wieszczków, aby cudzołożył idąc za nimi, postawię twarz swoję rozgniewaną przeciwko niemu, i wytracę go z pośrodku ludu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Przetoż poświęcajcie się, a bądźcie świętymi; bom Ja Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'A strzeżcie ustaw moich, i czyńcie je; Jam Pan poświęcający was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Ktobykolwiek złorzeczył ojcu swemu, albo matce swej, śmiercią umrze; ojcu swemu, i matce swej złorzeczył, krew jego będzie na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Kto by się kolwiek cudzołóstwa dopuścił z czyją żoną, ponieważ cudzołożył z żoną bliźniego swego, śmiercią umrze cudzołożnik on i cudzołożnica.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Ktobykolwiek też spał z żoną ojca swego, sromotę ojca swego odkrył, śmiercią umrą oboje; krew ich będzie na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Jeźliby też kto spał z synową swoją, śmiercią umrą oboje; obrzydliwości się dopuścili, krew ich będzie na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Mąż także, który by z mężczyzną obcował sposobem niewieścim, obrzydliwość uczynili oba; śmiercią umrą, krew ich będzie na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Kto by też pojął córkę z matką jej, sprośna rzecz jest; ogniem spalą onego i onę, aby nie była ta sprośność między wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Także kto by się złączył z bydlęciem, śmiercią umrze, bydlę też zabijecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Niewiasta, która by przystąpiła do jakiego bydlęcia, aby z niem obcowała, zabijesz niewiastę i bydlę; śmiercią umrą, krew ich będzie na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Kto by też pojął siostrę swoję, córkę ojca swego, albo córkę matki swej, i widziałby sromotę jej, i ona by widziała sromotę jego, rzecz haniebna jest; przetoż wytraceni będą przed oczyma synów ludu swego; sromotę siostry swej odkrył, nieprawość swoję poniesie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Kto by spał z niewiastą czasu przyrodzonej choroby jej, i odkryłby sromotę jej, i obnażyłby płynienie jej, i ona by też odkrywała płynienie krwi swojej, wytraceni będą oboje z pośrodku ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Sromoty siostry matki twej i siostry ojca twego nie odkryjesz; bo kto by pokrewną swoję obnażył, nieprawość swoję poniesie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Kto by też spał z żoną stryja swego, sromotę stryja swego odkrył, grzech swój poniosą, bez dzieci pomrą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Także kto by pojął żonę brata swego, sprośność jest; sromotę brata swego odkrył, bez dzieci będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Strzeżcież tedy wszystkich ustaw moich, i wszystkich sądów moich, a czyńcie je, aby was nie wyrzuciła ziemia, do której Ja was wprowadzę, abyście w niej mieszkali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'A nie chodźcie w ustawach tego narodu, który Ja wypędzam od oblicza waszego; bo to wszystko czynili, i obrzydziłem je sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Wam zaś powiedziałem: Wy posiądziecie ziemię ich, a Ja wam ją dam w dziedzictwo, ziemię opływającą mlekiem i miodem. Jam Pan, Bóg wasz, którym was wyłączył od innych narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'A tak wy rozeznawajcie między bydlęciem czystem i nieczystem, i między ptakiem nieczystym i czystym, a nie plugawcie dusz waszych bydłem i ptastwem i wszystkiem, co się czołga po ziemi, którem wam odłączył za nieczyste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'I będziecie mi świętymi, bom Ja święty Pan, i odłączyłem was od innych narodów, abyście byli moimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Mąż albo niewiasta, w których by był duch czarnoksięski albo wieszczy, śmiercią umrą: kamieniem ukamionują ich, krew ich będzie na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Rzekł też Pan do Mojżesza: Mów do kapłanów, synów Aaronowych, a powiedz im: Niech się nad umarłym nie plugawi żaden kapłan w ludu swym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Tylko przy pokrewnym swoim, powinowatym swoim, przy matce swej, i przy ojcu swym, i przy synu swym, i przy córce swej, i przy bracie swym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'Także przy siostrze swej, pannie sobie najbliższej, która nie miała męża; przy tych splugawić się może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Nie splugawi się przy przełożonym ludu swego, tak żeby się zmazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Nie będą sobie czynić łysiny na głowie swej, i brody swej nie mają golić, ani na ciele swem czynić będą rzezania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Świętymi będą Bogu swemu, i nie splugawią imienia Boga swego; albowiem ofiary ogniste Pańskie, chleb Boga swego, ofiarują; przetoż będą świętymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Niewiasty wszetecznej, i w panieństwie naruszonej, pojmować nie będą; także niewiasty odrzuconej od męża jej, pojmować nie będą; bo święty jest każdy z nich Bogu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'A tak będziesz go miał za świętego, bo chleb Boga twego ofiaruje; przetoż świętym będzie tobie, bom Ja święty Pan, który poświęcam was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Jeźliby się córka kapłańska nierządu dopuściła, ojca swego zelżyła, ogniem spalona będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Najwyższy też kapłan między bracią swą, na którego głowę wylany jest olejek pomazania, i który poświęcił ręce swe, aby obłoczył szaty święte, głowy swej nie obnaży i szat swoich nie rozedrze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'I do żadnego z umarłych nie przystąpi, a nawet i przy ojcu swym, i przy matce swej plugawić się nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Z świątnicy też nie wynijdzie, aby nie splugawił świątnicy Boga swego, gdyż korona olejku pomazania Boga jego jest na nim: Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Tenże pannę w panieństwie jej pojmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Wdowy, i odrzuconej i splugawionej nierządnicy, żadnej z tych nie pojmie; ale pannę z ludu swego za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'A nie będzie plugawił nasienia swego w ludu swym; bom Ja Pan, który go poświęcam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Przytem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Powiedz Aaronowi, i rzecz: Ktobykolwiek z potomstwa swego w narodziech swych, miał na sobie wadę, niechaj nie przystępuje, aby ofiarował chleb Boga swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Bo żaden mąż, który by miał na sobie wadę, przystępować nie ma; mąż ślepy, albo chromy, albo niezupełnych albo zbytnich członków;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Także mąż, który by miał złamaną nogę, albo złamaną rękę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Także garbaty, i płynących oczu, albo który ma bielmo na oku swem, albo krostawy, albo parszywy, albo wypukły:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Wszelki mąż, który by miał jaką wadę, z potomstwa Aarona kapłana nie przystąpi, aby ofiarował ofiary ogniste Panu; wada na nim jest, nie przystąpi, aby ofiarował chleb Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Chleba jednak Boga swego z rzeczy najświętszych i poświęconych pożywać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Wszakże za zasłonę nie wnijdzie, i do ołtarza nie przystąpi, bo wada na nim jest, aby nie splugawił świątnicy mojej; bom Ja Pan, który ją poświęcam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'To mówił Mojżesz do Aarona, i do synów jego, i do wszystkich synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Powiedz Aaronowi i synom jego, aby się wstrzymywali od rzeczy, które są poświęcone od synów Izraelskich, a nie plugawili świętego imienia mojego w tem, co mi oni poświęcają; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'A tak rzecz do nich: W narodziech waszych, ktobykolwiek przystąpił ze wszystkiego potomstwa waszego do poświęconych rzeczy, które by poświęcili synowie Izraelscy Panu, gdy nieczystość jego na nim jest, wytracony będzie ten od obliczności mojej; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Ktobykolwiek z nasienia Aaronowego był trędowatym albo płynienie nasienia cierpiącym, rzeczy poświęconych jeść nie będzie, póki by się nie oczyścił; także kto by się dotknął jakiej nieczystości ciała zmarłego, albo tego, z którego by płynęło nasienie złączenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Także kto by się dotknął czego, co się czołga po ziemi, przez coby się nieczystym stał, albo człowieka, przez którego by się splugawił według wszelakiej nieczystości jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Ten, kto by się czego z tych rzeczy dotknął, nieczystym będzie aż do wieczora, i nie będzie jadł rzeczy poświęconych, ażby umył ciało swoje wodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'I aż po zachodzie słońca czystym będzie; a potem będzie jeść z rzeczy poświęconych, bo to jest pokarm jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Ścierwu też i rozszarpanego od zwierza jeść nie będzie, aby się tem nie splugawił; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'A tak przestrzegać będą rozkazania mego, aby nie podlegli grzechowi, i nie pomarli w nim, gdyby się splugawili; Jam Pan, który je poświęcam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Żaden obcy nie będzie jadł z rzeczy poświęconych; komornik kapłański, ani najemnik nie będzie jadł rzeczy poświęconych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'A jeźliby kapłan człowieka kupił za pieniądze swoje, ten jeść będzie z rzeczy tych; także zrodzony w domu jego, ci będą jadać z pokarmów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Lecz córka kapłańska, która by szła za męża obcego, ta z ofiar podnoszenia rzeczy świętych jeść nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Gdyby zaś córka kapłańska wdową została, albo odrzuconą była od męża, i dziatek nie miała, a wróciłaby się w dom ojca swego, tak jako w dzieciństwie swem, chleb ojca swego jeść będzie; ale żaden obcy jeść z niego nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'A jeźliby kto jadł z niewiadomości rzeczy poświęcone, nadda piątą część do tego, i odda kapłanowi rzecz poświęconą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Aby nie plugawili rzeczy poświęconych, które synowie Izraelscy ofiarują Panu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'I nie przywodzili na się karania za występek, gdyby jedli poświęcone rzeczy ich; bom Ja Pan, który je poświęcam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Powiedz Aaronowi i synom jego, i wszystkim synom Izraelskim, a mów do nich: Ktobykolwiek z domu Izraelskiego, albo z przychodniów w Izraelu ofiarował ofiarę swoję według wszystkich ślubów swoich, i według wszystkich darów dobrowolnych swoich, które by ofiarowali Panu na ofiarę całopalenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'Z dobrej woli swej ofiarować będzie zupełnego samca z bydła rogatego, z owiec, i z kóz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Coby miało na sobie wadę, ofiarować nie będzie; bo nie będzie przyjemne od was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Jeźliby kto ofiarował ofiarę spokojną Panu, pełniąc ślub, albo dobrowolny dar oddając z rogatego bydła, albo z drobnego bydła, bez wady będzie, aby przyjemne było; żadnej wady nie będzie na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Ślepego, albo ułomnego, albo na czem ochromionego, albo guzowatego, albo krostawego, albo parszywego, nie ofiarujcie Panu, ani na ofiarę ognistą dawajcie ich na ołtarz Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Wołu też albo owcę zbytnich albo niezupełnych członków za dobrowolny dar ofiarować je możesz: ale ślub z nich przyjemny nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Zgniecionego i stłuczonego i przerwanego, i rzezanego nie będziecie ofiarować Panu; w ziemi waszej nie uczynicie tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Ani z ręki cudzoziemca nie będziecie ofiarować chleba Bogu waszemu z tych wszystkich rzeczy, bo ułomek jest w nich; wadę mają, nie będą przyjemne od was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Nad to rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Wół, albo owca, albo koza, gdy się urodzi, niech będzie siedem dni przy matce swojej, a dnia ósmego, i potem będzie przyjemne ku palonej ofierze Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Krowy też, ani owcy z płodem ich, nie zabijecie dnia jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'A gdybyście ofiarowali ofiarę dziękczynienia Panu, z dobrej woli swej ofiarować będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Onegoż dnia jedzona będzie; nie zostawicie z niej nic aż do jutra; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Przetoż strzeżcie przykazań moich, a czyńcie je; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'I nie plugawcie imienia mego świętego, abym był poświęcony w pośrodku synów Izraelskich. Ja Pan, który was poświęcam;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Którym was wywiódł z ziemi Egipskiej, abym wam był za Boga; Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Rzekł jeszcze Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Powiedz synom Izraelskim, a mów im: Święta uroczyste Pańskie, które nazywać będziecie zgromadzenia święte, te są święta uroczyste moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Przez sześć dni robić będziecie; ale w dzień siódmy sabat odpocznienia, zgromadzenie święte, żadnej roboty czynić nie będziecie; sabat Pański jest we wszystkich mieszkaniach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'A teć są uroczyste święta Pańskie, zgromadzenia święte, które obchodzić będziecie pewnego ich czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Miesiąca pierwszego, dnia czternastego tegoż miesiąca, między dwoma wieczorami święto przejścia Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Potem dnia piętnastego tegoż miesiąca, święto przaśników będzie Panu; przez siedem dni chleby przaśne jeść będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'A dnia pierwszego zgromadzenie święte mieć będziecie; żadnej roboty służebniczej czynić nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Ale będziecie ofiarowali ofiarę ognistą Panu przez siedem dni. Dnia także siódmego zgromadzenie święte będzie; żadnej roboty służebniczej czynić nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Powiedz synom Izraelskim, i rzecz im: Gdy wnijdziecie do ziemi którą Ja wam dawam, a będziecie żąć zboże wasze, tedy przyniesiecie snop pierwiastek żniwa waszego do kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'I będzie tam i sam obracał on snop przed obliczem Pańskiem, aby był przyjemny za was; nazajutrz po sabacie podnosić go będzie kapłan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Zabijecie też dnia, którego obracać będziecie on snop, baranka zupełnego, rocznego na ofiarę całopalenia Panu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Przy tem ofiarę jego śniedną ze dwu dziesiątych części efy mąki pszennej, zadziałanej z oliwą na paloną ofiarę Panu dla wdzięcznej wonności; także ofiarę jego mokrą, wina czwartą część hynu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'A chleba i prażma, i nowego zboża jeść nie będziecie aż do dnia, którego przyniesiecie ofiarę Bogu waszemu; ustawa to wieczna będzie w narodziech waszych, we wszystkich mieszkaniach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Naliczycie także sobie od dnia pierwszego po sabacie, od dnia, któregoście ofiarowali snop podnoszenia, siedem tygodni zupełnych niech będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Aż do pierwszego dnia po siódmym tygodniu naliczycie pięćdziesiąt dni; tedy ofiarować będziecie ofiarę śniedną nową Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Z domów waszych przyniesiecie chleby na obracanie tam i sam; dwa chleby, ze dwu dziesiątych części pszennej mąki z kwasem upieczone będą; pierwiastki to Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'A ofiarować z tym chlebem będziecie siedem baranków rocznych zupełnych, i cielca jednego, i dwu baranów; na ofiarę całopalenia będą Panu z ofiarą śniedną ich i z mokremi ofiarami ich; ofiara to ognista na wdzięczną wonność Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Zabijecie też kozła jednego za grzech, i dwa baranki roczne na ofiarę spokojną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'I będzie je obracał tam i sam kapłan z chlebem pierwiastek na ofiarę sam i tam obracania przed obliczem Pańskiem, i ze dwiema barankami; i będą święte rzeczy Panu dla kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'I ogłosicie w ten dzień święto; zgromadzenie święte mieć będziecie; żadnej roboty służebniczej czynić nie będziecie; ustawa to będzie wieczna we wszystkich mieszkaniach waszych, w narodziech waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'A gdy żąć będziecie zboże ziemi waszej, nie będziesz do końca pola twego dożynał, i kłosów pozostałych żniwa twego zbierać nie będziesz: ubogiemu, i przychodniowi zostawisz je; Jam Pan Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Powiedz synom Izraelskim, mówiąc: Miesiąca siódmego, pierwszego dnia tegoż miesiąca, będziecie mieli sabat, pamiątkę trąbienia, zgromadzenie święte.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Żadnej roboty służebniczej nie będziecie czynili, lecz ofiarować będziecie ofiarę ognistą Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Rzekł jeszcze Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Lecz dziesiątego dnia tegoż miesiąca siódmego, dzień oczyszczania jest; zgromadzenie święte mieć będziecie, a będziecie trapić dusze wasze, ofiarując ognistą ofiarę Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Żadnej roboty nie będziecie czynili w ten dzień; bo dzień oczyszczania jest na oczyszczenie was przed obliczem Pana, Boga waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'A wszelka dusza, która by się nie trapiła tego dnia, wytracona będzie z ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Także, ktobykolwiek czynił robotę jaką w tenże dzień, wytracę człowieka tego z pośrodku ludu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Żadnej roboty nie czyńcie; ustawa to będzie wieczna w narodziech waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Sabat odpocznienia mieć będziecie, gdy trapić będziecie dusze swe; dziewiątego dnia tegoż miesiąca, wieczór, od wieczora aż do wieczora, obchodzić będziecie sabat wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Rzekł zaś Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Powiedz synom Izraelskim, i rzecz: Piętnastego dnia tegoż siódmego miesiąca będzie święto kuczek przez siedem dni Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Dnia pierwszego zgromadzenie święte będzie; żadnej roboty służebniczej czynić nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Przez siedem dni ofiarować będziecie ofiarę ognistą Panu; dnia ósmego zgromadzenie święte mieć będziecie, a będziecie ofiarowali ofiarę ognistą Panu; święto jest, żadnej roboty służebniczej nie będziecie czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Teć są święta uroczyste Pańskie, które obchodzić będziecie, zgromadzenia święte, abyście ofiarowali ofiarę ognistą Panu, całopalenie, i ofiarę śniedną, i ofiarę spokojną i ofiary mokre, każdą w dzień swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Oprócz sabatów Pańskich, i oprócz darów waszych, i oprócz wszystkich ślubów waszych, i oprócz wszystkich dobrowolnych podarków waszych, które oddawać będziecie Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Wszakże piętnastego dnia miesiąca siódmego, gdy zbierzecie urodzaj ziemi, będziecie obchodzili święto Panu przez siedem dni; dnia pierwszego odpocznienie, także dnia ósmego odpocznienie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Tedy weźmiecie sobie pierwszego dnia owocu z drzewa co najpiękniejszego, i gałązek palmowych, i gałązek drzewa gęstego, i wierzbiny od potoku, i weselić się będziecie przed Panem Bogiem waszym przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'A obchodzić będziecie to święto Panu przez siedem dni na każdy rok. Ustawa to wieczna w narodziech waszych; każdego miesiąca siódmego obchodzić je będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'W kuczkach mieszkać będziecie przez siedem dni; każdy zrodzony w Izraelu mieszkać będzie w kuczkach,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Aby wiedzieli potomkowie wasi, iżem w namiotach kazał mieszkać synom Izraelskim, gdym je wywiódł z ziemi Egipskiej; Ja Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'I opowiedział Mojżesz święta uroczyste Pańskie synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Rozkaż synom Izraelskim, abyć przynieśli oliwy z drzewa oliwnego czystej, wytłoczonej ku świeceniu, aby lampy gorzały ustawicznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Przed zasłoną świadectwa w namiocie zgromadzenia sporządzi je Aaron, aby się paliły od wieczora aż do poranku przed obliczem Pańskiem ustawicznie; ustawa to wieczna w narodziech waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Na świeczniku czystym stawiać będzie lampy przed obliczem Pańskiem zawżdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Weźmiesz też mąki pszennej, a upieczesz z niej dwanaście placków; ze dwu dziesiątych części efy będzie placek jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Potem położysz je dwiema rzędami, sześć w rzędzie jednym na stole czystym przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Włożysz też na każdy rząd kadzidła czystego, aby było miasto chleba spalone, na pamiątkę ku ofierze ognistej Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Na każdy dzień sabatu kłaść je będzie kapłan porządnie przed Panem zawżdy, biorąc je od synów Izraelskich przymierzem wiecznem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'I będą należały Aaronowi i synom jego, którzy je jeść będą na miejscu świętem, albowiem rzeczą im to najświętszą jest z ognistych ofiar Pańskich, ustawą wieczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Tedy wyszedł syn niewiasty Izraelskiej, którego miała z mężem Egipskim, między syny Izraelskimi; i poswarzyli się w obozie syn onej niewiasty Izraelskiej z mężem Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'I złorzeczył syn niewiasty Izraelskiej a imię Boże bluźnił, dla czego przywiedziony był do Mojżesza. A imię matki jego było Salomit, córka Dybrego z pokolenia Dan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'I podali go do więzienia, ażby im oznajmiono, co z nim rozkaże Pan czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Tedy rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Wywiedź tego bluźniercę precz za obóz, a niech włożą wszyscy, którzy to słyszeli, ręce swe na głowę jego, i niech go ukamionuje wszystko zgromadzenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'A synom Izraelskim opowiedz, mówiąc: Ktobykolwiek złorzeczył Bogu swemu, odniesie karanie za grzech swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Także kto by zbluźnił imię Pańskie, śmiercią umrze, kamionując ukamionuje go wszystko zgromadzenie; tak przychodzień jako w domu zrodzony, gdyby zbluźnił imię Pańskie, umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Także jeźliby kto zabił jakiegokolwiek człowieka, śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'A jeźliby kto zabił bydlę wróci inne bydlę za bydlę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Kto by też oszkaradził bliźniego swego, według tego, jako uczynił, niech mu się stanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Złamanie za złamanie, oko za oko, ząb za ząb; według tego, jako oszkaradził człowieka, tak mu się też niech stanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Kto by zabił bydlę, wróci insze; ale kto by zabił człowieka, umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Prawo jednakie mieć będziecie; tak przychodzień, jako i w domu zrodzony będzie u was; bom ja Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'To gdy opowiedział Mojżesz synom Izraelskim, wywiedli onego bluźniercę za obóz, i ukamionowali go. I uczynili synowie Izraelscy według tego, jako przykazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Rzekł nad to Pan do Mojżesza na górze Synaj, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Powiedz synom Izraelskim, a mów do nich: Gdy wnijdziecie do ziemi, którą Ja wam daję, tedy święcić będzie ziemia sabat Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Przez sześć lat osiewać będziesz pole twoje, i przez sześć lat winnice twoje obrzynać będziesz, zbierając urodzaje z niej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Ale roku siódmego sabat odpocznienia mieć będzie ziemia, sabat Pański; pola twego nie będziesz osiewał, ani winnicy twojej obrzynał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Co się samo przez się zrodzi zboża twego, nie będziesz żął, i jagód zaniechanej winnicy twojej nie będziesz zbierał; rok odpocznienia będzie miała ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'I będzie, co się urodzi w onem odpocznieniu ziemi, tobie na pokarm, i słudze twemu, i służebnicy twej, i najemnikowi twemu i przychodniowi twemu, który mieszka z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Także bydłu twemu, i zwierzowi, który jest w ziemi twojej, będzie wszystek urodzaj jej na pokarm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Naliczysz też sobie siedem tygodni lat, to jest siedem kroć siedem lat; i uczyniąć dni siedmiu tygodni lat czterdzieści i dziewięć lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Tedy każesz zatrąbić w trąbę huczną miesiąca siódmego, dnia dziesiątego tegoż miesiąca; w dzień oczyszczenia każecie zatrąbić po wszystkiej ziemi waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'I święcić będziecie rok pięćdziesiąty, a obwołacie wolność w ziemi wszystkim obywatelom jej. Lato miłościwe mieć będziecie; i wróci się każdy do osiadłości swojej, i każdy do rodziny swojej wróci się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'To miłościwe lato pięćdziesiątego roku miewać będziecie; nie będziecie siać, i nie będziecie żąć tego, co się samo przez się zrodzi, ani zbierać będziecie gron z winnic zaniechanych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Bo miłościwy rok jest, święty wam będzie; co się na polu przedtem zrodziło, to jeść będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'W ten miłościwy rok wróci się każdy do osiadłości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Jeźli co sprzedasz bliźniemu twemu, albo co kupisz od bliźniego twego, niech nie oszukiwa jeden drugiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Według liczby lat po miłościwym roku kupisz od bliźniego twego; i według liczby lat dochody sprzeda tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Jeźli więcej będzie lat, tem drożej oszacujesz kupno ono; a jeźli mniej będzie lat, tedy też taniej oszacujesz kupno ono, ponieważ tylko liczba dochodów sprzedawa się tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'A tak nie oszukiwajcie żaden bliźniego swego, ale się bój każdy Boga swego; bom Ja Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Przestrzegajcie ustaw moich, i sądy moje zachowywajcie, i czyńcie je, abyście mieszkać mogli w ziemi onej bezpiecznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Tedy wyda ziemia owoc swój, a będziecie jeść aż do sytości, i będziecie mieszkać bezpiecznie w niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'A jeźlibyście rzekli: Cóż będziemy jeść roku siódmego, jeźli nie będziem siać ani zbierać urodzajów naszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Tedy rozkażę błogosławieństwu memu przyjść na was roku szóstego, i przyniesie urodzaj na trzy lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'I będziecie siać roku ósmego, a będziecie jeść urodzaj stary aż do roku dziewiątego; póki nie nadejdą pożytki jego, stare jeść będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Ziemia tedy nie będzie sprzedawana na wieczność; bo moja jest ziemia, a wyście gośćmi i przychodniami u mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'A po wszystkiej ziemi osiadłości waszej pozwolicie wykupywać ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Gdyby zubożał brat twój, a sprzedałby nieco z majętności swojej, i przyszedłby mający prawo odkupienia, powinny jego niech wykupi, co sprzedał brat jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'A jeźliby kto nie miał tego coby odkupić mógł, a sam by przemógł, i znalazł dostatek na to wykupno:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'Tedy obrachowawszy lata od sprzedania swego, wróci co zbywa temu, któremu sprzedał: a wróci się do majętności swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'A jeźliby nie miał dostatku, aby wrócił, tedy zostanie majętność sprzedana w ręku tego, który ją kupił, aż do roku miłościwego, i ustąpi mu jej w rok miłościwy, a on wróci się do majętności swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Jeźliby też sprzedał dom mieszkania w mieście murowanem, będzie miał wolność wykupić go, póki nie wynijdzie rok sprzedania jego, cały rok będzie miał prawo do wykupienia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'A jeźli go nie wykupi, póki nie wynijdzie rok cały, tedy zostanie on dom w mieście murowanem temu, który go kupił, dziedzicznie, i potomkom jego');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'I nie ustąpi w miłościwe lato. Ale domy we wsiach, które nie są murem obtoczone, te prawem jako pole ziemi szacowane będą; będą mogły być odkupowane, i w miłościwe lato z rąk obcych wynijdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Ale miasta Lewitów, i domy w dziedzicznych mieściech ich każdego czasu wykupowane być mogą przez Lewity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Lecz temu co kupuje od Lewitów, wynijdzie kupno domu, i miejskiej osiadłości jego, w rok miłościwy gdyż domy miast Lewickich są dziedziczne ich, w pośrodku synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Ale pole na przedmieściu ich nie będzie sprzedawane; bo dziedzictwem ich jest wiecznem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Gdyby też zubożał brat twój, a osłabiałaby ręka jego przy tobie, podeprzesz go; a jako i przychodzień niech się żywi przy tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Nie bierz od niego lichwy, ani płatu, ale się bój Boga swego, aby się żywił brat twój przy tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Pieniędzy twoich nie dawaj mu na lichwę, ani mu z zysku pożyczaj żywności twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Jam Pan, Bóg wasz, którym was wywiódł z ziemi Egipskiej, abym wam dał ziemię Chananejską, a był wam za Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Jeźliby też zubożał brat twój przy tobie, tak żeby się tobie zaprzedał, nie będziesz go dręczył służbą niewolniczą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Jako najemnik, jako przychodzień będzie u ciebie, aż do roku miłościwego służyć ci będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Potem wynijdzie od ciebie on, i dzieci jego z nim, a wróci się do rodziny swojej, i do dziedzictwa przodków swych wróci się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Słudzy bowiem moi są, którem Ja wywiódł z ziemi Egipskiej, niechże nie będą sprzedawani jako niewolnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Nie będziesz panował nad nimi surowie, ale się będziesz bał Pana Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Niewolnik też twój, i niewolnica twoja, które mieć będziesz, będą z narodów tych, które są około was, z nich kupować będziecie niewolnika i niewolnicę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Także też syny przychodniów mieszkających między wami kupować będziecie, i z potomstwa tych, którzy są z wami, które spłodzili w ziemi waszej, a ci będą wam za dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Prawem dziedzicznem trzymać je będziecie, i synowie wasi po was, abyście je dziedzicznie odzierżeli, na wieki służby ich używać będziecie; lecz nad bracią swą, syny Izraelskimi, żaden nad bratem swoim nie będzie panował surowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Jeźliby się też gość albo przychodzień zbogacił, który mieszka z tobą, a zubożałby brat twój przy nim, tak żeby się zaprzedał gościowi, albo przychodniowi, który jest z tobą, albo potomstwu z domu cudzoziemców,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'Gdyby się zaprzedał, może być wykupiony; ktokolwiek z braci jego odkupi go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Albo stryj jego, albo syn stryja jego odkupi go, albo z bliskich pokrewnych jego z rodziny jego, odkupi go, albo jeźliby przemógł, wykupi się sam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'I porachuje się z onym, co go kupił, od roku, którego mu się sprzedał, aż do miłościwego lata, aby pieniądze, za które się sprzedał, odłożone były według liczby lat, jako z najemnikiem, z nim sobie postąpi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Jeźliby jeszcze nie mało lat zostawało, wedle nich wróci okup swój z pieniędzy, za które kupiony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'A jeźliby nie wiele lat zostawało do miłościwego lata, tedy porachuje się z nim, a według onych lat wróci okup swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Jako najemnik doroczny niech będzie u niego; nie będzie nad nim surowie panował przed oczyma twemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'A jeźliby się tym obyczajem nie wykupił, tedy wynijdzie w miłościwe lato, on i dzieci jego z nim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Albowiem synowie Izraelscy są sługami moimi; sługami moimi są, którem wywiódł z ziemi Egipskiej, Ja Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Nie czyńcie sobie bałwanów, ani obrazu rytego; ani słupów stawiajcie sobie, ani kamienia w obraz wyrytego stawiajcie w ziemi waszej, abyście mu się kłaniali; bom Ja Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Sabaty moje zachowywajcie, a świątnicę moję w uczciwości miejcie; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Jeźli w ustawach moich chodzić będziecie, i przykazania moje chować i czynić będziecie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'Spuszczę wam deszcz czasu swego, i wyda ziemia urodzaj swój, i drzewa polne wydadzą owoc swój;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'I trwać będzie młoćba do zbierania wina, a zbieranie wina trwać będzie do siewu; będziecie jeść chleb swój do sytości, i mieszkać będziecie bezpiecznie w ziemi swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Bo dam pokój w ziemi, i będziecie spali, a nie będzie, kto by was przestraszył; wyplenię też złego zwierza z ziemi, a miecz nie przejdzie ziemi waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Owszem będziecie gonić nieprzyjacioły wasze, i upadną przed wami od miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Pięć waszych będą gonić sto, a sto waszych dziesięć tysięcy gonić będą, i polegną nieprzyjaciele wasi przed wami od miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Bo obrócę się do was, a rozkrzewię was, i rozmnożę was, i utwierdzę przymierze moje z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'I będziecie jedli z dawna zachowałe zboże, i stare, gdy nowe nastaną, wyprzątniecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'I wystawię przybytek mój między wami, a nie uprzykrzy was sobie dusza moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'I będę chodził między wami, a będę wam za Boga, a wy mnie będziecie za lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Jam Pan, Bóg wasz, którym was wywiódł z ziemi Egipskiej, abyście im nie służyli; i połamałem łańcuchy jarzma waszego, abyście chodzili prosto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'A jeźlibyście mię nie słuchali, i nie czynili wszystkich tych przykazań;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'I jeźli ustawy moje wzgardzicie, a sądami moimi będzie się brzydziła dusza wasza, żebyście nie czynili wszystkich przykazań moich, i wzruszylibyście przymierze moje:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'Ja też wam to uczynię: nawiedzę was strachem, suchotami i gorączką, które wam oczy popsują a boleścią napełnią dusze wasze, a siać będziecie próżno nasienie wasze, bo je zjedzą nieprzyjaciele wasi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'I postawię twarz moję przeciwko wam, i porażeni będziecie od nieprzyjaciół waszych, i panować będą nad wami, którzy was mają w nienawiści; i będziecie uciekali, choć was nikt gonić nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'A jeźliż ani tak nie usłuchacie mię, przydam siedem kroć więcej karania dla grzechów waszych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'I zetrę pychę mocy waszej, i uczynię niebo nad wami jako żelazo, a ziemię waszę jako miedź;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'I wniwecz się obróci praca wasza; bo nie wyda ziemia wasza użytku swego, i drzewa ziemi nie wydadzą owocu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'A jeźli chodzić będziecie, mnie się sprzeciwiając, a nie zechcecie mię słuchać, przydam kaźni waszych siedmiorako dla grzechów waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Bo puszczę na was zwierz polny, i osieroci was, i wyniszczy bydło wasze, i upleni was, i spustoszeją drogi wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'A jeźliż tem się nie nakarzecie, ale chodzić będziecie, mnie się sprzeciwiając:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'Ja też pójdę wam się sprzeciwiając, i bić was będę siedmiorako dla grzechów waszych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'I przywiodę na was miecz, który się sowicie zemści zgwałcenia przymierza; a gdy się zbieżycie do miast waszych, tedy puszczę powietrze morowe między was, a będziecie podani w ręce nieprzyjacielskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'A gdy złamię podporę chleba waszego, będą piekły dziesięć niewiast chleb wasz w piecu jednym, i będą wam oddawać chleb wasz pod wagą, i będziecie jeść, a nie najecie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'A jeźli i przeto nie usłuchacie mię, ale chodzić będziecie, mnie się sprzeciwiając:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'Ja też pójdę w gniewie przeciwko wam; i Ja też karać was będę siedmiorako więcej dla grzechów waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'I będziecie jeść ciało synów waszych, i ciało córek waszych jeść będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'I wygubię po górach kaplice wasze, a porozwalam słoneczne bałwany wasze; i składę trupy wasze na kloce obrzydłych bałwanów waszych, a będzie się wami brzydziła dusza moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'I podam miasta wasze na spustoszenie, a poburzę świątnice wasze, i nie przyjmę więcej wdzięcznej wonności waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'I spustoszę ziemię, że się nad nią zdumieją nieprzyjaciele wasi, mieszkając w niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'A was samych rozproszę między narody, i dobędę za wami miecza; a będzie ziemia wasza pusta, i miasta wasze zburzone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Tedy rada będzie ziemia odpocznieniu swemu po wszystkie dni spustoszenia swego; a wy będziecie w ziemi nieprzyjaciół waszych, tedy odpocznie ziemia, i rada będzie odpocznieniu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Przez wszystkie dni spustoszenia swego odpoczywać będzie; bo nie miała odpocznienia w sabaty wasze, gdyście wy mieszkali w niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'A którzy z was pozostaną, tedy przywiodę strach na serca ich, w ziemiach nieprzyjaciół ich, że je gonić będzie chrzęst liścia padającego; i będą uciekali jako przed mieczem, i padać będą, chociaż ich nikt gonić nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'I padnie jeden na drugiego jako od miecza, choć ich nikt gonić nie będzie; ani się ostoicie przed nieprzyjacioły waszymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'I poginiecie między narody, i pożre was ziemia nieprzyjaciół waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'A którzy z was zostaną, wywiędną dla nieprawości swojej w ziemi nieprzyjaciół swoich; także dla nieprawości ojców swych z nimi wywiędną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Ale jeźli wyznają nieprawość swoję, i nieprawość ojców swych według przestępstwa swego, którem wystąpili przeciwko mnie, i według którego chodzili, sprzeciwiając mi się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Żem też i Ja chodził sprzeciwiając się im, a iżem je wprowadził do ziemi nieprzyjaciół ich; jeźli, mówię, na ten czas poniży się serce ich nieobrzezane, i cierpliwie znosić będą kaźń za nieprawości swoje:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Tedy ja też wspomnę na przymierze moje z Jakóbem, i na przymierze moje z Izaakiem, i na przymierze moje z Abrahamem wspomnę, i na tę ziemię wspomnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'A ziemia będąc od nich uwolniona, rada będzie odpocznieniu swemu, gdy pusta będzie dla nich; a oni będą cierpliwie nosić karanie za nieprawość swą, przeto że sądy moje wzgardzili, i ustawami mojemi brzydziła się dusza ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Wszakże dla tego i na ten czas, gdy będą w ziemi nieprzyjaciół swoich, nie odrzucę ich, ani ich tak sobie obrzydzę, żebym je wyniszczyć miał, i wzruszyć przymierze moje z nimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Bom Ja Pan, Bóg ich. Ale wspomnę na nie dla przymierza uczynionego z przodkami ich; którem wywiódł z ziemi Egipskiej, przed oczyma poganów, abym im był za Boga, Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Teć są ustawy i sądy i prawa, które postanowił Pan między sobą, i między syny Izraelskimi na górze Synaj przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Mów do synów Izraelskich, a powiedz im: Gdyby człowiek ślubem poślubił duszę Panu, według szacunku twego da okup.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'A będzie tak szacunek twój: Za mężczyznę od dwudziestu lat aż do sześćdziesiąt lat, będzie szacunek twój pięćdziesiąt syklów srebra według wagi świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'A jeźli jest biała głowa szacunek twój będzie trzydzieści syklów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'A jeźli od piątego roku aż do dwudziestego roku, tedy będzie szacunek twój za mężczyznę dwadzieścia syklów a za białą głowę dziesięć syklów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'A jeźli za dziecię od jednego miesiąca aż do pięciu lat, tedy będzie szacunek twój za mężczyznę pięć syklów srebra, a za dzieweczkę szacunek twój trzy sykle srebra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'A jeźli od sześćdziesiąt lat i wyżej będzieli mężczyzna tedy będzie szacunek twój piętnaście syklów a za białą głowę dziesięć syklów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Lecz jeźliby był tak ubogi, żeby nie mógł oddać szacunku twego, tedy go stawią przed kapłana, i oszacuje go kapłan, według przemożenia tego który ślubował, oszacuje go kapłan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Jeźliby też bydlę z tych, które się ofiarują na ofiarę Panu, poślubił, każde, które odda Panu będzie święte.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Nie odmieni go, ani da innego za nie, lepszego za gorsze, albo gorszego za lepsze; jeźliby też jakokolwiek odmienił bydlę za bydlę, tedy i ono, i to, które za nie dano będzie święte.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'A jeźliby które nie czyste bydlę poślubił z tych, co nie bywają ofiarowane Panu, tedy stawi to bydlę przed kapłana,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'I oszacuje kapłan bądź dobre, bądź złe, a jako je oszacuje kapłan, tak będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'A jeźliby je kto odkupić chciał, przyda piątą część nad szacunek twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Jeźliby też kto poświęcił dom swój, żeby był święty Panu, tedy go oszacuje kapłan bądź dobry, bądź zły; jako go oszacuje kapłan, tak zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'A gdyby ten, który poświęcił, chciał odkupić dom swój, przyda piątą część pieniędzy na szacunek twój, i będzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Jeźli też kto część roli z dziedzictwa swego poświęcił Panu tedy będzie szacunek twój według zasiewku jej; gdzie się wysieje chomer jęczmienia, za pięćdziesiąt syklów srebra szacowane będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Jeźli do miłościwego lata poświęcił rolę swoję, według szacunku twego zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Ale jeźliżby po miłościwem lecie poświęcił rolę twoję tedy kapłan obrachuje mu pieniądze według lat zostawających do miłościwego lata i umniejszy mu się z szacunku twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'A chciałliby odkupić rolą, ten, który ją poświęcił, przyda piątą część pieniędzy do szacunku twego i zostanie przy niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Ale gdzie by nie odkupił roli onej, a sprzedana by była rola komu inszemu, nie może być odkupiona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'I będzie ona rola, gdy wynijdzie miłościwe lato święta Panu, jako rola poświęcona a przyjdzie w osiadłość kapłanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'A jeźliby kto rolą kupioną, która nie była z ról dziedzictwa jego poślubił Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'Tedy porachuje mu kapłan sumę szacunku twego aż do roku miłościwego, i da szacunek ten dnia onego za rzecz poświęconą Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'A w miłościwe lato wróci się rola od tego, od kogo ją kupiono, do tego, który dziedzicznie trzymał rolą onę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'A każdy szacunek twój będzie wedle sykla świątnicy, a dwadzieścia pieniędzy sykiel waży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Wszakże pierworodnego, a które prawem pierworodztwa bywa ofiarowane Panu z bydła, nikt go nie poświęci, bądź wół bądź owca, ponieważ Pańskie są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'A jeźliby z bydląt nieczystych było, odkupi je według szacunku twego, i przyda piątą część nad to; a jeźliby go nie odkupiono, niechże sprzedane będzie według szacunku twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Każda jednak rzecz poślubiona, którą by kto poślubił Panu ze wszystkiego, co ma z ludzi, i z bydła, i z ról osiadłości swojej, nie będzie sprzedawana, ani odkupowana; bo wszelka rzecz poślubiona najświętsza jest Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Wszelkie bydlę poślubione, które się pod ślubem oddawa, od człowieka nie będzie odkupione, ale śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Wszystkie także dziesięciny ziemi z nasienia ziemi, z owocu drzewa, Pańskie są; bo poświęcone są Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Ale kto by chciał odkupić co z dziesięcin swoich, piątą część ceny przyda do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Także wszystkie dziesięciny z rogatego bydła, i z drobnego bydła, wszystkiego, co przechodzi pod laską pasterską, każde dziesiąte będzie poświęcone Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Nie będzie przebierał między dobrem albo złem, ani go odmieniać będzie; a jeźliby je jakokolwiek odmienił, będzie to i ono odmienione poświęcone, nie ma być odkupione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Teć są przykazania, które rozkazał Pan Mojżeszowi do synów Izraelskich na górze Synaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'I mówił Pan do Mojżesza na puszczy Synaj, w namiocie zgromadzenia pierwszego dnia miesiąca wtórego, roku wtórego, po wyjściu ich z ziemi Egipskiej, temi słowy:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Obliczcie sumę wszystkiego zgromadzenia synów Izraelskich według narodów ich, i według domów ojców ich według imion ich, każdego mężczyznę według głów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Ode dwudziestu lat, i wyżej, wszystkich wychodzących na wojnę z Izraela; policzycie je według hufców ich, ty i Aaron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'I będzie z wami z każdego pokolenia jeden mąż, któryby przedniejszy był w domu ojców swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'A teć są imiona mężów, którzy z wami będą; z pokolenia Rubenowego Elizur, syn Sedeurów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Z pokolenia Symeonowego Salamijel, syn Surysaddajów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Z pokolenia Judowego Naason, syn Aminadabów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Z pokolenia Isascharowego Natanael syn Suharów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Z pokolenia Zabulonowego Elijab, syn Helonów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Z synów Józefowych, z pokolenia Efraimowego Elisama, syn Ammiudów; z pokolenia Manasesowego Gamalijel, syn Pedasurów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Z pokolenia Benjaminowego Abidan, syn Gedeonów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Z pokolenia Danowego Achyjezer, syn Ammisadajów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Z pokolenia Aserowego Pagijel, syn Ochranów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Z pokolenia Gadowego Elijazaf, syn Duelów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Z pokolenia Neftalimowego Achyra, syn Enanów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Ci zwoływani będą najzacniejsi z ludu książęta w pokoleniach ojców swych; wodzami wojsk Izraelskich będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Przyzwali tedy do siebie Mojżesz i Aaron mężów tych, którzy z imienia mianowani są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'I zebrali wszystko zgromadzenie dnia pierwszego miesiąca wtórego, i przyznawali się do rodzajów swych według familii swych, według domów ojców swych i według liczby imion, od dwudziestu lat i wyżej, według osób swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Jako rozkazał Pan Mojżeszowi, tak je policzył na puszczy Synaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'I było synów Rubena, pierworodnego Izraelowego, rodzajów ich według familii ich, według domów ojców ich, według liczby imion, według osób ich, wszystkiego pogłowia męskiego od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Naliczono ich z pokolenia Rubenowego czterdzieści i sześć tysięcy i pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Z synów Symeonowych rodzajów ich, według familii ich, według domów ojców ich, naliczonych jego, według liczby imion, według osób ich, wszystkiego pogłowia męskiego od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Naliczono ich z pokolenia Symeonowego pięćdziesiąt i dziewięć tysięcy i trzy sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Z synów Gadowych rodzajów ich według familii ich, według domów ojców ich, według liczby imion, od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Naliczono ich z pokolenia Gadowego czterdzieści i pięć tysięcy i sześć set i pięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Z synów Judowych rodzajów ich według familii ich, według domów ojców ich, według liczby imion, od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Naliczono ich z pokolenia Judowego siedemdziesiąt i cztery tysiące i sześć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Z pokolenia Isascharowego rodzajów ich według familii ich, według domów ojców ich, według liczby imion, od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Naliczono ich z pokolenia Isascharowego pięćdziesiąt i cztery tysiące i cztery sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Z synów Zabulonowych rodzajów ich według familii ich, według domów ojców ich, według liczby imion, od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Naliczono ich z pokolenia Zabulonowego pięćdziesiąt i siedem tysięcy i cztery sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Z synów Józefowych, a naprzód z synów Efraimowych, rodzajów ich według familii ich, według domów ojców ich, według liczby imion, od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Naliczono ich z pokolenia Efraimowego czterdzieści tysięcy i pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Z synów zaś Manasesowych rodzajów ich według familii ich, według domów ojców ich, według liczby imion, od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Naliczono ich z pokolenia Manasesowego trzydzieści i dwa tysiące i dwieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Z synów Benjaminowych rodzajów ich, według familii ich, według domów ojców ich, według liczby imion, od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Naliczono ich z pokolenia Benjaminowego trzydzieści i pięć tysięcy i cztery sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Z synów Danowych rodzajów ich według familii ich, według domów ojców ich, według liczby imion, od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Naliczono ich z pokolenia Danowego sześćdziesiąt i dwa tysiące i siedemset.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Z synów Aserowych rodzajów ich według familii ich, według domów ojców ich, według liczby imion, od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Naliczono ich z pokolenia Aserowego czterdzieści tysięcy i jeden i pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Z synów Neftalimowych rodzajów ich według familii ich, według domów ojców ich, według liczby imion, od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Naliczono ich z pokolenia Neftalimowego pięćdziesiąt i trzy tysiące i cztery sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Cić są policzeni, które policzył Mojżesz i Aaron, i książęta Izraelskie, dwanaście mężów, którzy byli wybrani po jednemu z domów ojców swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'I było wszystkich policzonych synów Izraelskich według domów ojców ich, od dwudziestu lat i wyżej, wszystkich wychodzących na wojnę z Izraela;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Było wszystkich policzonych sześć kroć sto tysięcy i trzy tysiące, i pięć set i pięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Ale Lewitowie według pokolenia ojców swych nie byli policzeni między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Bo rozkazał był Pan Mojżeszowi, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Tylko pokolenia Lewi nie będziesz liczył, a sumy ich nie policzysz między syny Izraelskie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Ale postanowisz Lewity nad przybytkiem świadectwa, i nad wszystkiem naczyniem jego, i nad wszystkiem co należy do niego. Oni nosić będą przybytek i wszystkie naczynia jego; oni też służyć będą w nim, a około przybytku obozem się kłaść będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'A gdy się będzie ruszał przybytek, składać go będą Lewitowie; także gdy stanowić się będzie przybytek, stawiać go będą Lewitowie; a kto by obcy do niego przystąpił, umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'I będą stawać obozem synowie Izraelscy, każdy według pułków swoich, i każdy pod chorągwią swoją, w wojsku swem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Ale Lewitowie kłaść się będą obozem około przybytku świadectwa, aby nie przyszedł gniew mój na zgromadzenie synów Izraelskich: i będą Lewitowie trzymać straż u przybytku świadectwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Uczynili tedy synowie Izraelscy według wszystkiego, co był rozkazał Pan Mojżeszowi, tak uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Zatem rzekł Pan do Mojżesza i do Aarona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Każdy z synów Izraelskich kłaść się będą obozem pod chorągwią swoją według znaków domów ojców swych; naprzeciwko około namiotu zgromadzenia kłaść się będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'A ci się obozem położą na wschód słońca: Chorągiew wojska Judowego według hufców swych, a hetmanem nad syny Judowymi Naason, syn Aminadabów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'A w wojsku jego policzonych siedemdziesiąt i cztery tysiące i sześć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Podle niego położy się obozem pokolenie Isascharowe, a hetmanem nad syny Isascharowymi Natanael, syn Suharów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'A w wojsku jego policzonych pięćdziesiąt i cztery tysiące i cztery sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Podle nich pokolenie Zabulonowe, a hetmanem nad syny Zabulonowymi Elijab, syn Helonów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'A w wojsku jego policzonych pięćdziesiąt i siedem tysięcy i cztery sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Wszystkich policzonych w obozie Judowym sto tysięcy, osiemdziesiąt tysięcy, i sześć tysięcy i cztery sta według hufców ich; ci naprzód pociągną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Chorągiew obozu Rubenowego położy się na południe według hufców swych, a hetmanem nad syny Rubenowymi Elisur, syn Sedeurów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'A w wojsku jego policzonych czterdzieści i sześć tysięcy i pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Podle niego położy się obozem pokolenie Symeonowe, a hetmanem nad syny Symeonowymi Selumijel, syn Surysaddajów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'A w wojsku jego policzonych pięćdziesiąt i dziewięć tysięcy i trzy sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Potem pokolenie Gadowe, a hetmanem nad syny Gadowymi Elijazaf, syn Rehuelów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'A w wojsku jego policzonych czterdzieści i pięć tysięcy, i sześć set i pięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Wszystkich policzonych w obozie Rubenowym sto tysięcy, pięćdziesiąt tysięcy i jeden, cztery sta i pięćdziesiąt według hufców ich; a ci w rzędzie wtórym pociągną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Potem pójdzie namiot zgromadzenia z wojskiem Lewitów, w pośrodku wojska; jakim porządkiem stawać będą obozem, takim pociągną każdy w szyku swym pod chorągwią swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Chorągiew obozu Efraimowego według hufców swych ku zachodowi, a hetmanem nad syny Efraimowymi Elisama, syn Ammiudów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'A w wojsku jego policzonych czterdzieści tysięcy i pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'A podle niego pokolenie Manasesowe, a hetmanem nad syny Manasesowymi Gamalijel, syn Pedasurów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'A w wojsku jego policzonych trzydzieści i dwa tysiące i dwieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Podle nich pokolenie Benjaminowe, a hetmanem nad syny Benjaminowymi Abidan, syn Giedeonów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'A w wojsku jego policzonych trzydzieści i pięć tysięcy i cztery sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Wszystkich policzonych w obozie Efraimowym sto tysięcy i osiem tysięcy i sto według hufców swoich; a ci w trzecim rzędzie pociągną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Chorągiew obozu Danowego położy się ku północy według hufców swych, a hetmanem nad syny Danowymi Achiezer, syn Ammisadajów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'A w wojsku jego policzonych sześćdziesiąt i dwa tysiące i siedem set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'A podle niego położy się obozem pokolenie Aserowe a hetmanem nad syny Aserowymi Pagijel, syn Ochranów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'A w wojsku jego policzonych czterdzieści tysięcy i jeden i pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Potem pokolenie Neftalimowe, a hetmanem nad syny Neftalimowymi Ahira, syn Enanów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'A w jego wojsku policzonych pięćdziesiąt i trzy tysiące i cztery sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'A tak wszystkich policzonych obozu Danowego sto tysięcy, pięćdziesiąt i siedem tysięcy i sześć set; a ci na ostatku pociągną pod chorągwią swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Cić są policzeni synów Izraelskich według domów ojców ich, wszystkich policzonych w obozie według hufców ich sześć kroć sto tysięcy, i trzy tysiące i pięć set i pięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Ale Lewitów nie liczono między syny Izraelskie, jako był Pan rozkazał Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'I uczynili synowie Izraelscy według wszystkiego; jako rozkazał Pan Mojżeszowi, tak się stanowili obozem przy chorągwiach swych, i ciągnęli każdy według familii swych, i według domów ojców swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'A teć są rodzaje Aarona i Mojżesza w dzień, którego mówił Pan z Mojżeszem na górze Synaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'A te są imiona synów Aaronowych: Pierworodny Nadab, potem Abiu, Eleazar, i Itamar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Te są imiona synów Aaronowych, kapłanów pomazanych, których ręce poświęcone były ku sprawowaniu urzędu kapłańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Ale pomarli Nadab i Abiu przed Panem, gdy ofiarowali ogień obcy przed Panem na puszczy Synaj, a zeszli bez potomstwa; dla tego Eleazar i Itamar odprawowali urząd kapłański przed obliczem Aarona, ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Tedy rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Każ przystąpić pokoleniu Lewiego, a postaw je przed Aaronem kapłanem, aby mu służyli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'A trzymali straż jego, i straż wszystkiego zgromadzenia, przed namiotem zgromadzenia, wykonywając usługę przybytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Także aby strzegli wszystkiego naczynia namiotu zgromadzenia, i trzymali straż synów Izraelskich, a odprawowali usługę przybytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Oddasz tedy Lewity Aaronowi, i synom jego; bo właśnie oddani są jemu z synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Aarona zaś i syny jego przełożysz, aby przestrzegali kapłaństwa swego: bo przystąpiłliby kto obcy, umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'A oto, Ja wziąłem Lewity z pośrodku synów Izraelskich miasto wszelkiego pierworodnego, otwierającego żywot, między synami Izraelskimi, i będą moi Lewitowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Albowiem mnie przynależy wszelkie pierworodne; ode dnia, któregom pobił wszelkie pierworodne w ziemi Egipskiej, poświęciłem sobie każde pierworodne w Izraelu; od człowieka aż do bydlęcia moi będą; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Rzekł też Pan do Mojżesza na puszczy Synaj, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Policz syny Lewiego, według domów ojców ich, według familii ich; każdego mężczyznę urodzonego od miesiąca i wyżej, policzysz je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'I policzył je Mojżesz według mowy Pańskiej, jako mu było rozkazane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'I były synów Lewiego te imiona: Gerson, i Kaat, i Merary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Te zaś imiona synów Gersonowych według domów ich: Lobni i Semei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'A synowie Kaatowi według domów swych: Amram, i Izaar, Hebron, i Husyjel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Synowie zaś Merarego według domów swych: Naheli i Muzy; te są familije Lewiego według domów ojców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Z Gersona familija Lobnicka, i familija Semeicka; teć są familije Gersonowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Policzonych ich według liczby każdego mężczyzny urodzonego od miesiąca i wyżej, było policzonych siedem tysięcy i pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Te familije Gersonowe za przybytkiem kłać się będą ku zachodowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'A książęciem domu ojca Gersonitów: Elijazaf, i syn Laelów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'A pod strażą synów Gersonowych będzie przy namiocie przybytek zgromadzenia, przybytek i namiot, przykrycie jego, i zasłona u drzwi namiotu zgromadzenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'I opony sieni, i zasłona we drzwiach u sieni, która jest przed przybytkiem i przy ołtarzu w około, i sznury jego, do wszelkiej potrzeby jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Z Kaata zaś poszła familija Amramitów, i familija Izaaritów, i familija Husyjelitów. Teć były domy Kaatytów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'W liczbie wszystkich mężczyzn urodzonych od miesiąca i wyżej, osiem tysięcy i sześć set, trzymających straż przy świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Te familije synów Kaatowych kłaść się będą obozem po bok przybytku ku południowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'A książęciem domu ojca familii Kaatytów Elisafan, syn Husyjelów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'A będzie pod strażą ich skrzynia, i stół, i świecznik, i ołtarze, i naczynia świątnicy, któremi usługować będą, i zasłona, i ze wszystkiemi potrzebami jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'A książęciem nad książęty Lewitów będzie Eleazar, syn Aarona kapłana, postanowiony nad tymi, którzy trzymają straż przy świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Od Merarego zaś poszła familija Mahelitów, i familija Muzytów; a teć są domy Merarytów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'A policzonych ich, według liczby każdego mężczyzny urodzonego od miesiąca i wyżej, sześć tysięcy i dwieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Książęciem zaś domu ojca familii Merarego Suryjel, syn Abihailów; a ci kłaść się będą po bok przybytku, ku północy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'A należeć będą do straży synów Merarego deski przybytku, i drągi jego, słupy jego, i podstawki jego, i wszystkie naczynia jego, i wszystkie potrzeby jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Także słupy sienne w około, i podstawki ich, i kotły i sznury ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'A kłaść się będą obozem przed przybytkiem, po przedniej stronie namiotu zgromadzenia, na wschód Mojżesz, i Aaron, i synowie jego, trzymający straż przy świątnicy; straż za syny Izraelskie; a obcy gdyby przystąpił, umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'A tak wszystkich policzonych Lewitów od Mojżesza i Aarona, na rozkazanie Pańskie, według domów ich, wszystkich mężczyzn urodzonych od miesiąca i wyżej, było dwadzieścia tysięcy i dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Tedy rzekł Pan do Mojżesza: Policz wszystkie pierworodne mężczyzny między syny Izraelskimi od miesiąca i wyżej, a uczyń summę imion ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'A weźmiesz mi Lewity (Ja Pan) miasto wszystkich pierworodnych w syniech Izraelskich, także bydła Lewitów ze wszystkie pierworodne bydła synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Policzył tedy Mojżesz, jako mu Pan rozkazał, wszystkie pierworodne w syniech Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'A było wszystkich pierworodnych mężczyzn według liczby imion, urodzonych od miesiąca i wyżej, policzonych ich dwadzieścia i dwa tysiące, dwieście, siedemdziesiąt i trzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Weźmij Lewity miasto wszystkich pierworodnych z synów Izraelskich, bydła także Lewitów miasto bydła ich, i będą moimi Lewitowie; Jam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'A za okup onych dwu set, siedmiudziesiąt i trzech, którzy zbywają nad liczbę Lewitów, z pierworodnych synów Izraelskich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Weźmiesz po pięć syklów na każdą głowę; według sykla świątnicy brać będziesz; dwadzieścia pieniędzy waży sykiel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'I oddasz te pieniądze Aaronowi i synom jego za okup onych, którzy zbywają nad liczbę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Wziął tedy Mojżesz pieniądze okupu od tych, którzy zbywali nad te, które okupili sobą Lewitowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Od pierworodnych synów Izraelskich wziął pieniędzy onych tysiąc, trzysta, sześćdziesiąt i pięć syklów według sykla świątnicy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'I oddał te pieniądze okupu Mojżesz Aaronowi i synom jego według słowa Pańskiego, jako Pan rozkazał Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Nad to rzekł Pan do Mojżesza i Aarona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Zbierz summę synów Kaatowych z pośród synów Lewiego według familii ich, i według domów ojców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Od tego, który ma trzydzieści lat i wyżej, i aż do tego, co ma pięćdziesiąt lat, którzy będąc sposobnymi do tej pracy, mogliby odprawować posługę w namiocie zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Tać będzie powinność synów Kaatowych przy namiocie zgromadzenia, przy miejscu najświętszem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'I przyjdzie Aaron z synami swymi, gdy się będzie miał ruszyć obóz, a zdejmą oponę zasłony, i okryją nią skrzynię świadectwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'A włożą na nię przykrycie z borsukowych skór, i przykryją z wierzchu wszystko oponą hijacyntową, i założą drążki jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Także stół chlebów pokładnych przykryją oponą hijacyntową, a położą na nim misy, i przystawki, i kubki, i czasze do nalewania; a chleb ustawicznie na nim będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'I rozciągną na tem oponę szarłatową, a przykryją to przykryciem skór borsukowych, i założą drążki do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Wezmą też oponę hijacyntową, którą nakryją świecznik do świecenia z lampami jego, i nożyczki jego, i kaganki jego, i wszystkie naczynia do oliwy jego, których używają przy nim:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'I uwiną go ze wszystkiem naczyniem jego w przykrycie z skór borsukowych, i włożą na drążki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Na ołtarz także złoty rozpostrzą oponę hijacyntową, a włożą nań przykrycie z skór borsukowych, i założą drążki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Pobiorą też wszystkie naczynia usługi, któremi służą w świątnicy, a obwinąwszy oponą hijacyntową, przykryją je przykryciem z skór borsukowych, i włożą na drążki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Do tego zmiotą popiół z ołtarza, a na nim rozpostrzą oponę szarłatową;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'I włożą nań wszystkie naczynia jego, któremi usługują przy nim, to jest łopaty, widły, i miotły, i kociełki, i wszystkie naczynia ołtarzowe, i rozpostrzą na nim przykrycie z skór borsukowych, i założą drążki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'A gdy to wykona Aaron z synami swymi, że przykryje świątnicę ze wszystkiem naczyniem świątnicy, a będzie się miał ruszyć obóz, tedy potem przyjdą synowie Kaatowi, aby one rzeczy nieśli; ale się nie będą dotykali świątnicy, aby nie pomarli. Tać jest posługa synów Kaatowych, przy namiocie zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Staranie zasię Eleazara, syna Aarona kapłana, będzie o oliwie do świecenia, o kadzeniu wonnem, o ofierze śniednej ustawicznej, i o olejku pomazywania, doglądanie przybytku, i wszystkiego, co w nim jest, i świątnicy z naczyniami jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Potem rzekł Pan do Mojżesza i Aarona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Nie zatracajcie pokolenia domów Kaatowych z pośrodku Lewitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Ale to im uczynicie, aby żyli a nie pomarli, gdy przystępować będą do miejsca najświętszego: Aaron i synowie jego przyjdą, i postanowią każdego z nich nad pracą jego i nad brzemieniem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Ale niech nie wchodzą patrzyć, gdy będą uwijane rzeczy święte, aby nie pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Zbierz summę synów Gersonowych według domów ojców ich, i według familii ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Od tego, który ma trzydzieści lat i wyżej, aż do tego, który ma pięćdziesiąt lat, policzysz je, którzy sposobni będą do tej pracy, aby mogli usługować przy namiocie zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'A tać będzie powinność domów synów Gersonowych ku posłudze i ku noszeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Nosić będą opony przybytku, i namiot zgromadzenia z przykryciem jego; także przykrycie borsukowe, które z wierzchu na nim jest, i zasłonę od drzwi namiotu zgromadzenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'I opony do sieni, i zasłonę drzwi bramy u sieni, która jest u przybytku, i przy ołtarzu w około, i sznury jej, i wszystkie naczynia usługi ich, i wszystko, czego używają około usługi ich; i to czynić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Według rozkazania Aarona i synów jego będzie wszelka usługa synów Gersonowych przy każdem brzemieniu ich, i przy każdej usłudze ich; a poruczycie im pod straż wszystkie brzemiona ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Tać będzie powinność domów synów Gersonowych w namiocie zgromadzenia, a będzie ich doglądał Itamar, syn Aarona kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Syny także Merarego według familii ich, i według domów ojców ich policzysz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Od tego, który ma trzydzieści lat i wyżej, i aż do tego, który ma pięćdziesiąt lat, policzysz je; którzy będąc sposobni do tej pracy mogliby usługować przy namiocie zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'A ta będzie powinność pracy ich we wszystkiej usłudze ich w namiocie zgromadzenia: deski przybytku, i drągi jego, i słupy jego, i podstawki jego nosić;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Przytem słupy sieni w około, i podstawki ich z kołkami ich, i sznury ich ze wszystkiem naczyniem ich, do wszelkiej służby ich; a mianowicie policzycie naczynia, które im poruczycie pod straż ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Tać powinność będzie familii synów Merarego, według wszelkiej służby ich, przy namiocie zgromadzenia pod dozorem Itamara, syna Aarona kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Obliczyli tedy Mojżesz i Aaron, i książęta zgromadzenia syny Kaatowe według familii ich, i według domów ojców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Od tych, którym było trzydzieści lat i wyżej, i aż do tych, którym było pięćdziesiąt lat, którzy sposobni będąc ku tej pracy mogliby usługować przy namiocie zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'A było ich policzonych według familii ich dwa tysiące, siedem set i pięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Cić byli policzeni z familii Kaatytów wszyscy służący przy namiocie zgromadzenia, które zliczył Mojżesz i Aaron według rozkazania Pańskiego przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Także policzeni są synowie Gersonowi wedle familii swych, i według domów ojców swych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Od tego, który miał trzydzieści lat i wyżej, i aż do tego, który miał pięćdziesiąt lat, którzy sposobni będąc ku pracy mogli usługować przy namiocie zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'A było ich policzonych według familii ich, i domów ojców ich dwa tysiące, sześć set i trzydzieści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Cić byli policzeni z familii synów Gersonowych, wszyscy służący w namiocie zgromadzenia, które zliczył Mojżesz i Aaron według słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Także policzeni z familii synów Merarego według familii swych i domów ojców swych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Od tego, który miał trzydzieści lat i wyżej, i aż do tego, który miał pięćdziesiąt lat; którzy sposobni będąc ku pracy mogli usługiwać przy namiocie zgromadzenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'A było ich policzonych według familii ich trzy tysiące i dwieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'A tać była summa policzonych z familii synów Merarego, które zliczył Mojżesz i Aaron według rozkazania Pańskiego przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Wszystkich policzonych, które policzył Mojżesz i Aaron, i książęta Izraelskie z Lewitów według familii ich, i domów ojców ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Od tego, który miał trzydzieści lat i wyżej, i aż do tego, który miał pięćdziesiąt lat, każdego przychodzącego do odprawowania powinności usługi, i powinności noszenia brzemion w namiocie zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'A było ich policzonych osiem tysięcy, i pięć set i osiemdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Według rozkazania Pańskiego policzeni są przez Mojżesza, każdy z osobna według usługi jego, i według brzemienia jego; a policzeni byli ci, które Pan rozkazał liczyć Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Rozkaż synom Izraelskim, aby wyrzucili z obozu każdego trędowatego, i każdego, który cierpi płynienie nasienia, i każdego, który się splugawił nad umarłym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Tak mężczyznę jako i niewiastę wyrzucicie; precz za obóz wyrzucicie je, aby nie splugawili obozu tych, między którymi Ja mieszkam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'I uczynili tak synowie Izraelscy, a wygnali je precz za obóz; jako rozkazał Pan Mojżeszowi, tak uczynili synowie Izraelscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Nad to rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Powiedz synom Izraelskim: Mąż albo niewiasta, gdyby popełnili jakikolwiek grzech ludzki, dopuściwszy się występku przeciwko Panu, a byłaby winna ona dusza:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Tedy wyznają grzech swój, którego się dopuścili, i wrócą to, w czem by winni byli cale; a przydawszy jeszcze nad to piątą część, oddadzą onemu, przeciw któremu zgrzeszyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'A jeźliby nie było tego, komu by szkodę trzeba nagrodzić, ona szkoda oddana będzie Panu, i zostanie kapłanowi oprócz barana oczyszczenia, przez którego ma być oczyszczony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Każda też ofiara podnoszenia ze wszech rzeczy poświęconych od synów Izraelskich, którą przyniosą do kapłana, jemu się dostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Owe rzeczy poświęcone od kogożkolwiek, jego będą; i kto by co oddał kapłanowi, jemu zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Mów do synów Izraelskich, a powiedz im: Każdy mąż, którego by żona wystąpiła, i dopuściłaby się grzechu przeciwko niemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'A złączyłby się inszy z nią złączeniem nasienia, a byłoby to skryte przed oczyma męża jej, i taiłaby się, będąc splugawioną, a świadka by nie było przeciwko niej, aniby jej zastano;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Jednak przypadłby nań duch zapalczywości, i miałby w podejrzeniu żonę swą, która by splugawiona była; albo żeby przypadł nań duch zapalczywości, i miałby w podejrzeniu żonę swą, która by splugawiona nie była:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'Tedy przywiedzie on mąż żonę swoję do kapłana, i przyniesie z nią ofiarę jej, dziesiątą część efy mąki jęczmiennej nie lejąc na nią oliwy, ani kładąc na nią kadzidła; albowiem jest ofiara podejrzenia, ofiara śniedna, pamiętna, przywodząca na pamięć grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'A tak będzie ją ofiarował kapłan, i stawi ją przed oblicznością Pańską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'I weźmie kapłan wody świętej w naczynie gliniane, i prochu, który będzie na tle przybytku, weźmie kapłan, a wsypie do wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Potem postawi kapłan niewiastę przed Panem, i odkryje głowę niewiasty, a da w ręce jej ofiarę śniedną pamiętną; ofiara to śniedna podejrzenia; a kapłan będzie miał w ręce wodę gorzką przeklęstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'I poprzysięże ją kapłan, i rzecze do niewiasty: Jeźli nie spał kto inszy z tobą, a jeźliś się nie uniosła w grzech nieczysty przy mężu swym, bądź nienaruszona od tej wody gorzkiej przeklęstwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'Ale jeźliżeś ustąpiła od męża twego, i jesteś splugawiona, a kto inny spał z tobą oprócz męża twego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'Tedy poprzysięże kapłan niewiastę onę przysięgą przeklęstwa, i rzecze do niej: Niechaj cię poda Pan na złorzeczenie, i na przeklinanie między ludem twoim, przepuściwszy, aby łono twoje wypadło, i żywot twój opuchł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Niechże przenikną te wody przeklęte wnętrzności twoje, aby opuchł żywot twój, i wypadło łono twoje; i odpowie niewiasta: Amen. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Tedy napisze te przeklęstwa kapłan na księgach, a omyje je oną wodą gorzką;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'I da się napić niewieście wody gorzkiej przeklęstwa, i przenikną ją wody przeklęstwa, i obrócą się w gorzkość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Potem weźmie kapłan z rąk niewiasty onej ofiarę śniedną podejrzenia, a będzie ją podnosił przed Panem, ofiarując ją na ołtarzu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Weźmie też kapłan na garść pamiętnego z ofiary śniednej, i spali to na ołtarzu, potem da wypić wodę niewieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'A gdy się jej da napić onej wody, stanie się, jeźliby splugawiona była, i wystąpiła grzechem przeciwko mężowi swemu, że ją przenikną wody przeklęstwa, i obrócą się w gorzkość, i opuchnie żywot jej, i wypadnie łono jej, i stanie się niewiasta ona przeklęstwem między ludem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'A jeźliby nie była splugawiona niewiasta, aleby czysta była, niewinna zostanie, i dziatki rodzić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Tać jest ustawa podejrzenia, gdyby ustąpiła żona od męża swego, i byłaby splugawiona;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Albo żeby na męża przypadł duch zapalczywy, a miałby w podejrzeniu żonę swoję, i postawiłby ją przed Panem, a uczyniłby z nią kapłan wszystko według tej ustawy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Tedy nie będzie mąż on winien grzechu; ale niewiasta ona poniesie nieprawość swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Powiedz synom Izraelskim, a mów do nich: Mąż albo niewiasta, gdy się odłączy, czyniąc ślub Nazarejstwa, aby byli odłączeni Panu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Od wina i mocnego napoju wstrzymywać się będzie; octu z wina, i octu z mocnego napoju pić nie będzie, i wszystkiego, co się z jagód wytłacza, nie będzie pił; także jagód winnych, świeżych ani suchych, jeść nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Po wszystkie dni Nazarejstwa swego ze wszystkiego, co wyrasta z macicy winnej, od ziarnka aż do łupiny, jeść nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Po wszystkie dni ślubu Nazarejstwa swego brzytwa nie postoi na głowie jego, aż wynijdzie czas, do którego się poświęcił Panu; będzie świętym, a zapuści włos na głowie swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Po wszystkie dni, których się odłączy Panu, do umarłego nie wnijdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Nad ojcem swym, i nad matką swą, nad bratem swym, i nad siostrą swą, nie splugawi się, gdyby zmarli; albowiem poświęcenie Boga swego ma na głowie swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Po wszystkie dni Nazarejstwa swego świętym będzie Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'I gdyby kto umarł przy nim z prędka a nagle, i splugawiłby głowę poświęcenia jego, ogoli głowę swoję w dzień oczyszczenia swego; dnia siódmego ogoli ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'A dnia ósmego przyniesie dwie synogarlice, albo dwoje gołąbiąt do kapłana ku drzwiom namiotu zgromadzenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'I będzie kapłan ofiarował jedno za grzech, a drugie na ofiarę całopalenia, i oczyści go od tego, czem zgrzeszył nad umarłym, a poświęci głowę jego dnia onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Potem odłączy Panu dni Nazarejstwa swego, ofiarując baranka rocznego za występek; a dni one pierwsze daremne będą, gdyż splugawione było Nazarejstwo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'A toć jest prawo Nazarejczyka: Gdy się wypełnią dni Nazarejstwa jego, przyjdzie do drzwi namiotu zgromadzenia,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'I ofiarować będzie ofiarę swą Panu, baranka rocznego, zupełnego jednego na ofiarę całopalenia, i owcę jednę roczną i zdrową na ofiarę za grzech, i barana jednego zupełnego na ofiarę spokojną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Przytem kosz chlebów przaśnych, z mąki pszennej, placki zagniatane z oliwą, i kreple przaśne oliwą namazane, z ofiarą ich śniedną, i z ofiarą ich mokrą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'I będzie ofiarował kapłan przed Panem, i uczyni ofiarę za grzech jego, i całopalenie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Barana także ofiarować będzie na spokojną ofiarę Panu z koszem chlebów przaśnych; także ofiarować będzie kapłan ofiarę jego śniedną i ofiarę jego mokrą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'I ogoli Nazarejczyk przede drzwiami namiotu zgromadzenia głowę Nazarejstwa swego, a wziąwszy włosy z głowy Nazarejstwa swego, włoży je na ogień, który jest pod ofiarą spokojną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Przytem weźmie kapłan łopatkę warzoną baranią, i jeden placek przaśny z kosza, i jeden krepel niekwaszony, a da w ręce Nazarejczykowe po ogoleniu Nazarejstwa jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'I będzie to tam i sam obracał kapłan na ofiarę obracania przed Panem; a rzecz ta poświęcona dostanie się kapłanowi, tak piersi obracania, jako i łopatka podnoszenia; a potem będzie mógł Nazarejczyk pić wino.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Toć jest prawo Nazarejczyka, któryby ślub uczynił, i ta ofiara jego Panu za Nazarejstwo jego, okrom tego, coby więcej uczynić mógł; według ślubu swego, który uczynił, tak uczyni według prawa Nazarejstwa swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Mów do Aarona i do synów jego, a rzecz: Tak błogosławić będziecie synom Izraelskim, mówiąc do nich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Niech ci błogosławi Pan, a niechaj cię strzeże;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Niech rozjaśni Pan oblicze swoje nad tobą, a niech ci miłościw będzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Niech obróci Pan twarz swoję ku tobie, a niechaj ci da pokój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'I będą wzywać imienia mego nad synami Izraelskimi, a Ja im błogosławić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'I stało się w dzień, którego dokończył Mojżesz, a wystawił przybytek, a pomazał go, i poświęcił go ze wszystkim sprzętem jego, i ołtarz ze wszystkiem naczyniem jego, pomazał je, i poświęcił je,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Że ofiarowały książęta Izraelskie, przedniejsze z domów ojców swych, (co byli hetmany z każdego pokolenia, i przełożonymi nad policzonymi.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'A przynieśli ofiary swe przed Pana: sześć wozów przykrytych, i dwanaście wołów, jeden wóz od dwojga książąt, a od każdego wół jeden, i postawili to przed przybytkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Tedy rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Weźmij od nich, aby to było na potrzebę przy służbie w namiocie zgromadzenia, i oddaj to Lewitom, każdemu według potrzeby urzędu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Wziął tedy Mojżesz one wozy i woły i oddał je Lewitom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Dwa wozy, i cztery woły dał synom Gersonowym według potrzeby urzędów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Cztery zaś wozy i osiem wołów dał synom Merarego według potrzeby urzędów ich, pod władzę Itamara, syna Aarona kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Ale synom Kaatowym nic nie dał: bo usługa świątnicy była przy nich, na ramieniu ją nosić musieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Ofiarowały tedy książęta ku poświęceniu ołtarza onegoż dnia, gdy był pomazany; i ofiarowały książęta dary swe przed ołtarzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'I rzekł Pan do Mojżesza: Jeden książę jednego dnia, drugi książę drugiego dnia oddawać będzie dary swoje ku poświęceniu ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'I ofiarował pierwszego dnia dar swój Naason, syn Aminadabów z pokolenia Judy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'A dar jego był: misa srebrna jedna, sto i trzydzieści syklów wagi jej, czasza srebrna jedna, siedemdziesiąt syklów wagi jej według sykla świątnicy, obie pełne pszennej mąki zagniecionej z oliwą na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Kadzielnica jedna z dziesięciu syklów złota, pełna kadzidła dla kadzenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Cielec jeden młody, baran jeden, i baranek jeden roczny na ofiarę paloną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Kozieł jeden z kóz za grzech;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'A na ofiarę spokojną dwa woły, baranów pięć, kozłów pięć, i baranków rocznych pięć. Tać była ofiara Naasona, syna Aminadabowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Wtórego dnia ofiarował Natanael, syn Suharów, książę z pokolenia Isascharowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'I ofiarował dar swój, misę srebrną jednę, sto i trzydzieści syklów wagi jej, czaszę srebrną jednę, siedemdziesiąt syklów wagi jej według sykla świątnicy, obie pełne pszennej mąki zagniecionej z oliwą na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Kadzielnicę jednę z dziesięciu syklów złota, pełną kadzidła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Cielca jednego młodego, barana jednego, i baranka jednego rocznego na paloną ofiarę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Kozła też jednego z kóz za grzech;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'A na ofiarę spokojną dwa woły, baranów pięć, kozłów pięć, i baranków rocznych pięć. Tać była ofiara Natanaela, syna Suharowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Trzeciego dnia książę synów Zabulon Eliab, syn Helonów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Ofiara jego była misa srebrna jedna, sto i trzydzieści syklów wagi jej, czasza srebrna jedna, siedemdziesiąt syklów wagi jej według sykla świątnicy, obie pełne mąki pszennej z oliwą zagniecionej na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Kadzielnica jedna z dziesięciu syklów złota, pełna kadzidła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Cielec jeden młody, baran jeden, i baranek roczny jeden na całopalenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Kozieł jeden z kóz, za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'A na ofiarę spokojną dwa woły, baranów pięć, kozłów pięć, baranków rocznych pięć. Ta była ofiara Eliaba, syna Helonowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Dnia czwartego książę z synów Rubenowych Elisur, syn Sedeurów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Ofiara jego była misa srebrna jedna, sto i trzydzieści syklów wagi jej, czasza srebrna jedna siedemdziesiąt syklów wagi jej według syklów świątnicy, obie pełne mąki pszennej z oliwą zagniecionej na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'Kadzielnica jedna z dziesięciu syklów złota, pełna kadzidła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'Cielec jeden młody, baran jeden, baranek jeden roczny na paloną ofiarę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'Kozieł jeden z kóz, za grzech');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'A na ofiarę spokojną dwa woły, baranów pięć, kozłów pięć, baranków rocznych pięć. Ta była ofiara Elisura, syna Sedeurowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Dnia piątego książę synów Symeonowych Selumijel, syn Surysaddajów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Ofiara jego była misa srebrna jedna, sto i trzydzieści syklów wagi jej, czasza srebrna jedna, siedemdziesiąt syklów wagi jej według sykla świątnicy, obie pełne mąki pszennej z oliwą zagniecionej na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'Kadzielnica jedna z dziesięciu syklów złota, pełna kadzidła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'Cielec jeden młody, baran jeden, baranek jeden roczny na paloną ofiarę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'Kozieł jeden z kóz, za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'A na ofiarę spokojną dwa woły, baranów pięć, kozłów pięć, baranków rocznych pięć. Ta była ofiara Selumijela, syna Surysaddajowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Dnia szóstego książę synów Gadowych Elijazaf, syn Duelów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Ofiara jego była misa srebrna jedna, sto i trzydzieści syklów wagi jej, czasza srebrna jedna, siedemdziesiąt syklów wagi jej według sykla świątnicy, obie pełne mąki pszennej z oliwą zagniecionej na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'Kadzielnica jedna z dziesięciu syklów złota, pełna kadzidła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'Cielec jeden młody, baran jeden, baranek roczny jeden na paloną ofiarę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, 'Kozieł jeden z kóz, za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'A na ofiarę spokojną dwa woły, baranów pięć, kozłów pięć, baranków rocznych pięć. Ta była ofiara Elijazafa, syna Duelowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Dnia siódmego książę synów Efraimowych, Elisama, syn Ammiudów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Ofiara jego była misa srebrna jedna, sto i trzydzieści syklów wagi jej, czasza srebrna jedna, siedemdziesiąt syklów wagi jej według sykla świątnicy, obie pełne mąki pszennej z oliwą zagniecionej, na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'Kadzielnica jedna z dziesięciu syklów złota, pełna kadzidła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'Cielec jeden młody, baran jeden, baranek jeden roczny na paloną ofiarę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'Kozieł jeden z kóz, za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'A na ofiarę spokojną dwa woły, baranów pięć, kozłów pięć, baranków rocznych pięć. Tać była ofiara Elisamy, syna Ammiudowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Dnia ósmego książę synów Manasesowych Gamalijel, syn Pedasurów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Ofiara jego była misa srebrna jedna, sto i trzydzieści syklów wagi jej, czasza srebrna jedna, siedemdziesiąt syklów wagi jej według sykla świątnicy, obie pełne mąki pszennej, z oliwą zagniecionej, na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'Kadzielnica jedna z dziesięciu syklów złota, pełna kadzidła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'Cielec jeden młody, baran jeden, baranek jeden roczny na paloną ofiarę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'Kozieł jeden z kóz, za grzech;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'A na ofiarę spokojną dwa woły, baranów pięć, kozłów pięć, baranków rocznych pięć. Ta była ofiara Gamalijela, syna Pedasurowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Dnia dziewiątego książę synów Benjaminowych Abidan, syn Gedeonów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Ofiara jego była misa srebrna jedna, sto i trzydzieści syklów wagi jej, czasza srebrna jedna, siedemdziesiąt syklów wagi jej według sykla świątnicy, obie pełne mąki pszennej, zagniecionej z oliwą na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'Kadzielnica jedna z dziesięciu syklów złota pełna kadzidła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'Cielec jeden młody, baran jeden, baranek roczny jeden na paloną ofiarę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'Kozieł jeden z kóz za grzech;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'A na ofiarę spokojną dwa woły, baranów pięć, kozłów pięć, baranków rocznych pięć. Ta była ofiara Abidana, syna Gedeonowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Dnia dziesiątego książę synów Danowych Achyjezer, syn Ammisadajów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Ofiara jego była misa srebrna jedna, sto i trzydzieści syklów wagi jej, czasza jedna srebrna, siedemdziesiąt syklów wagi jej według sykla świątnicy obie pełne mąki pszennej, zagniecionej z oliwą, na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'Kadzielnica jedna z dziesięciu syklów złota, pełna kadzidła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'Cielec jeden młody, baran jeden, baranek roczny jeden na paloną ofiarę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'Kozieł jeden z kóz, za grzech;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'A na spokojną ofiarę dwa woły, baranów pięć, kozłów pięć, baranków rocznych pięć. Ta była ofiara Achyjezera, syna Ammisadajowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Dnia jedenastego książę synów Aserowych Pagijel, syn Ochranów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Ofiara jego była misa srebrna jedna, sto i trzydzieści syklów wagi jej, i czasza jedna srebrna, siedemdziesiąt syklów wagi jej według sykla świątnicy, obie pełne pszennej mąki, zagniecionej z oliwą na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'Kadzielnica jedna, z dziesięciu syklów złota, pełna kadzidła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Cielec jeden młody, baran jeden, baranek jeden roczny na paloną ofiarę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Kozieł jeden z kóz, za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'A na ofiarę spokojną dwa woły, baranów pięć, kozłów pięć, baranków rocznych pięć. Ta była ofiara Pagijela, syna Ochranowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Dnia dwunastego książę synów Neftalimowych Ahira, syn Enanów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Ofiara jego była misa srebrna jedna, sto i trzydzieści syklów wagi jej, czasza srebrna jedna, siedemdziesiąt syklów wagi jej według sykla świątnicy, obie pełne pszennej mąki, zagniecionej z oliwą na ofiarę śniedną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Kadzielnica jedna z dziesięciu syklów złota, pełna kadzidła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Cielec jeden młody, baran jeden, baranek jeden roczny na ofiarę paloną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Kozieł jeden z kóz, za grzech;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'A na spokojną ofiarę dwa woły, baranów pięć, kozłów pięć, baranków rocznych pięć. Tać była ofiara Ahira, syna Enanowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Toć było poświęcenie ołtarza, onegoż dnia, gdy pomazan jest od książąt Izraelskich: Mis srebrnych dwanaście, czasz srebrnych dwanaście, kadzielnic złotych dwanaście;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Sto i trzydzieści syklów jedna misa srebrna ważyła, siedemdziesiąt syklów czasza jedna; wszystkiego srebra w onem naczyniu było dwa tysiące i cztery sta syklów według sykla świątnicy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Kadzielnic złotych dwanaście pełnych kadzidła; dziesięć syklów ważyła każda według sykla świątnicy; wszystkiego złota w onych kadzielnicach było sto i dwadzieścia syklów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'A wszystkiego bydła ku ofierze palonej dwanaście cielców, baranów dwanaście, z baranków rocznych dwanaście, z ofiarą ich śniedną, i kozłów z kóz za grzech dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Wszystkiego zasię bydła na ofiarę spokojną było wołów dwadzieścia i cztery, baranów sześćdziesiąt, kozłów sześćdziesiąt; baranków rocznych sześćdziesiąt. Toć było poświęcenie ołtarza po pomazaniu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'A gdy Mojżesz wchodził do namiotu zgromadzenia, by się rozmawiał z Bogiem, tedy słyszał głos mówiącego do siebie z ubłagalni, która była nad skrzynią świadectwa, między dwiema Cheruby, a stamtąd mawiał do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Potem Pan rzekł do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Powiedz Aaronowi, a rzecz mu: Gdy zapalisz lampy, siedem lamp przeciwko świecznikowi świecić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'I uczynił tak Aaron, a przeciwko świecznikowi zapalił lampy jego, jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'A była robota świecznika z ciągnionego złota, i słupiec jego, i kwiaty jego ciągnione były; na ten kształt, jaki był Pan ukazał Mojżeszowi, tak urobił świecznik.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Weźmij Lewity z pośród synów Izraelskich, a oczyść je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'A to uczynisz oczyszczając je: Pokropisz je wodą oczyszczenia; ciż ogolą brzytwą wszystko ciało swoje, a uprawszy szaty swe, czystymi będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Potem wezmą cielca młodego, z ofiarą jego śniedną, mąki pszennej, zagniecionej z oliwą, a cielca młodego drugiego weźmiesz na ofiarę za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'I przywiedziesz Lewity przed namiot zgromadzenia, a przyzowiesz wszystkiego zgromadzenia synów Izraelskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'I postawisz Lewity przed Panem, i włożą synowie Izraelscy ręce swe na Lewity;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'I ofiarować będzie Aaron Lewity na ofiarę przed panem od synów Izraelskich, aby sprawowali posługi Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Lewitowie zaś będą kłaść ręce swe na głowy onych cielców, a ofiarować będziesz jednego za grzech, a drugiego na ofiarę całopalenia Panu ku oczyszczeniu Lewitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Potem postawisz Lewity przed Aaronem, i przed syny jego, a ofiarować je będziesz na ofiarę Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'I odłączysz Lewity z pośród synów Izraelskich, i będą moimi Lewitowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'A potem przyjdą Lewitowie, aby służyli w namiocie zgromadzenia, gdy oczyścisz i poświęcisz je na ofiarę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Albowiem właśnie oddani są mnie z pośród synów Izraelskich; za każde otwierające żywot, za każde pierworodne z synów Izraelskich obrałem je sobie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Gdyż wszyscy pierworodni z synów Izraelskich moi są z ludzi i z bydła: ode dnia, któregom pobił wszystkie pierworodne w ziemi Egipskiej, poświęciłem je sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'A przyjąłem Lewity miasto wszelkiego pierworodnego z synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'I dałem Lewity darem Aaronowi i synom jego z pośród synów Izraelskich, aby odprawowali służby miasto synów Izraelskich w namiocie zgromadzenia, i oczyszczali syny Izraelskie, aby nie przyszło na syny Izraelskie karanie, gdyby przystępowali synowie Izraelscy do świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Uczynili tedy Mojżesz i Aaron i wszystko zgromadzenie synów Izraelskich z Lewitami wszystko, co rozkazał Pan Mojżeszowi o Lewitach, tak uczynili z nimi synowie Izraelscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'I oczyścili się Lewitowie, a uprali szaty swoje, i ofiarował je Aaron na ofiarę przed Panem, i oczyścił je Aaron, aby byli czystymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Dopiero potem przystąpili Lewitowie ku sprawowaniu urzędu swego w namiocie zgromadzenia przed Aaronem i przed syny jego; jako rozkazał Pan Mojżeszowi o Lewitach, tak im uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Rzekł nadto Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'To też Lewitom należy: Od dwudziestego i piątego roku i wyżej każdy przystąpi, aby sprawował urząd przy posłudze namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'A w pięćdziesiąt lat przestanie pracować w urzędzie, i więcej służyć nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Ale nadsługować będzie braci swej w namiocie zgromadzenia straż trzymającym, lecz służby samej odprawować nie będzie. Tak sobie postąpisz z Lewitami w urzędziech ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'I rzekł Pan do Mojżesza na puszczy Synaj, roku wtórego po wyjściu ich z ziemi Egipskiej, miesiąca pierwszego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Niech obchodzą synowie Izraelscy święto przejścia czasu naznaczonego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Czternastego dnia miesiąca tego, między dwoma wieczorami, obchodzić je będziecie czasu naznaczonego; według wszystkich obrzędów jego, i według wszystkich ceremonii jego, obchodzić je będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Mówił tedy Mojżesz do synów Izraelskich, aby obchodzili święto przejścia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'I obchodzili święto przejścia, pierwszego miesiąca, czternastego dnia, między dwoma wieczorami, na puszczy Synaj; według wszystkiego, jak rozkazał Pan Mojżeszowi, tak uczynili synowie Izraelscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'I byli niektórzy ludzie, którzy się byli splugawili nad umarłym człowiekiem, i nie mogli obchodzić święta przejścia dnia onego; tedy przystąpili do Mojżesza i do Aarona w tenże dzień;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'I rzekli oni ludzie do niego: Zmazaliśmy się nad umarłym: i nie będzież nam wolno oddać ofiary Panu czasu naznaczonego wespół z synami Izraelskimi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Którym odpowiedział Mojżesz: Postójcie, aż usłyszę, co rozkaże Pan o was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Tedy rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Powiedz synom Izraelskim i rzecz: Jeźliby się kto zmazał nad umarłym, alboby na drodze dalekiej był, tak z was, jako i z potomstwa waszego, przecię będzie odprawował święto przejścia Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Miesiąca wtórego, czternastego dnia, między dwoma wieczorami, odprawować je będą; z przaśnemi chleby, i z gorzkiemi zioły jeść je będą:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Nie zostawią nic z niego do jutra, i kości nie złamią w nim; według wszystkiego postanowienia święta przejścia odprawować je będą:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Ale człowiek, któryby był czysty, a nie byłby w drodze, i nie obchodziłby święta przejścia, tedy dusza ona wykorzeniona będzie z ludu swego, bo ofiary Pańskiej nie odprawował czasu naznaczonego; grzech swój poniesie on człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'A jeźliby przychodzień mieszkający między wami obchodził święto przejścia Panu, według ustawy święta przejścia i według obrzędów jego obchodzić je będzie; ustawa jedna będzie, wam i przychodniowi, i zrodzonemu w ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Dnia tedy onego, którego wystawiony był przybytek, obłok okrył przybytek nad namiotem świadectwa, a wieczór bywało nad przybytkiem jako widzenie ognia aż do poranku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Tak bywało ustawicznie; we dnie okrywał go obłok, a jako widzenie ognia w nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'A gdy się podnaszał obłok od namiotu, tedy się ruszali synowie Izraelscy; a gdziekolwiek stawał obłok, tamże stanowili obóz synowie Izraelscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Na rozkazanie Pańskie ciągnęli synowie Izraelscy, i na rozkazanie Pańskie stanowili obóz; po wszystkie dni, których zostawał obłok nad przybytkiem, i oni leżeli obozem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'A gdy trwał obłok nad przybytkiem przez wiele dni, tedy odprawowali synowie Izraelscy straż Panu, a nie ruszali się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Ale gdy nie długo trwał obłok nad przybytkiem, na rozkazanie Pańskie stanowili obóz, i na rozkazanie Pańskie ciągnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'A gdy bywał obłok od wieczora aż do poranku, a podnosił się zaś poranku, tedy ciągnęli; tak we dnie jako i w nocy, gdy się podniósł obłok, ciągnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'A jeźli przez dwa dni, albo przez miesiąc, albo też przez rok trwał obłok nad przybytkiem, zostawając nad nim, obozem leżeli synowie Izraelscy, i nie ruszali się; ale gdy się on podnosił, i oni się ruszali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Na rozkazanie Pańskie stanowili obóz, i na rozkazanie Pańskie ciągnęli, straż Pańską trzymając, jako im Pan rozkazał przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Potem Pan rzekł do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Spraw sobie dwie trąby srebrne; robotą ciągnioną uczynisz je, których używać będziesz do zwoływania ludu, i gdyby się wojsko ruszać miało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'A gdy zatrąbią w nie, tedy się do ciebie zbieży wszystek lud ku drzwiom namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'A jeźliby w jednę tylko zatrąbiono, tedy się zejdą do ciebie książęta, i hetmani wojsk Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Gdyby zaś zatrąbiono głos przerywając, tedy się ruszy obóz leżących na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'A gdy drugi raz zatrąbią, głos przerywając, tedy się ruszy obóz leżących na południe; z przerywaniem trąbić będą, gdy się ruszyć będą mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Ale gdy zwoływać lud będziecie, trąbić będziecie, a nie będziecie przerywać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'A synowie Aaronowi, kapłani, trąbić będą w trąby: i będzie wam to za ustawę wieczną w potomstwie waszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'A gdy wyciągniecie na wojnę w ziemi waszej przeciwko nieprzyjacielowi, któryby was trapił, z przerywaniem w trąby trąbić będziecie; a przyjdziecie na pamięć przed Panem, Bogiem waszym, i zachowani będziecie od nieprzyjciół waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'W dzień także wesela waszego, i w święta uroczyste wasze, i na nowiu miesięcy waszych, będziecie trąbić w te trąby przy ofiarach waszych całopalnych, i przy ofiarach waszych spokojnych, i przywiodą was na pamięć przed Bogiem waszym; Ja Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'I stało się roku wtórego, miesiąca wtórego, dnia dwudziestego tegoż miesiąca, że się podniósł obłok przybytku świadectwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'I ruszyli się synowie Izraelscy z hufcami swymi z puszczy Synaj, a stanął obłok na puszczy Faran.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'I ruszyli się najpierwej tak, jako był Pan rozkazał przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Albowiem ruszyła się chorągiew obozu synów Judowych naprzód z hufcami swemi, a nad wojskiem jego był hetman Naason, syn Aminadabów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'A nad wojskiem pokolenia synów Isascharowych był hetmanem Natanael, syn Suharów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'A nad wojskiem pokolenia synów Zabulonowych był hetmanem Elijab, syn Helonów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Zatem złożono przybytek, i ciągnęli synowie Gersonowi, i synowie Merarego, niosąc przybytek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Ruszyła się zaś chorągiew obozu Rubenowego z hufcami swemi, a nad wojskiem jego był hetmanem Elisur, syn Sedeurów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'A nad wojskiem pokolenia synów Symeonowych był hetmanem Selumijel, syn Surysaddajów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'A nad wojskiem też pokolenia synów Gadowych był hetmanem Elijazaf, syn Duelów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Zatem ruszyli się Kaatytowie, niosąc świątnicę, i stanowili przybytek, aż ci nadciągnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Potem ruszyła się chorągiew obozu synów Efraimowych z hufcami swemi, a nad wojskiem jego był hetmanem Elisama, syn Ammiudów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Nad wojskiem zaś pokolenia synów Manasesowych był hetmanem Gamalijel, syn Pedasurów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Nad wojskiem zaś pokolenia synów Benjaminowych był hetmanem Abidan, syn Gedeonów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Potem ruszyła się chorągiew obozu synów Danowych zawierając wszystkie obozy z wojski ich, a nad wojskiem jego był hetmanem Achyjezer, syn Ammisaddajów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'A nad wojskiem pokolenia synów Eserowych był hetmanem Pagijel, syn Ochranów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'A nad wojskiem pokolenia synów Neftalimowych był hetmanem Ahira, syn Enanów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Takieć było ciągnienie synów Izraelskich z hufcami ich; i tak ciągnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Potem rzekł Mojżesz do Hobaba, syna Raguelowego Madyjańczyka, świekra swego: My ciągniemy do miejsca, o którem rzekł Pan: Dam je wam. Pójdź z nami, a uczynimyć dobrze, ponieważ Pan obiecał wiele dobrego Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Któremu on odpowiedział: Nie pójdę: ale się wrócę do ziemi mojej i do rodziny mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'I rzekł Mojżesz: Proszę, nie opuszczaj nas; bo ty wiesz, gdzie byśmy na puszczy obóz stanowić mieli, i będziesz przewodnikiem naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'A jeźliż pójdziesz z nami, i spotka nas to dobre, którem nam Pan uczyni dobrze, i my dobrze uczynimy tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'I odciągnęli od góry Pańskiej drogą trzech dni, a skrzynia przymierza Pańskiego szła przed nimi drogą trzech dni, aby im upatrzyła miejsce odpocznienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'A obłok Pański szedł nad nimi we dnie, gdy się ruszali z stanowiska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'A gdy się ruszyć miała skrzynia, tedy mawiał Mojżesz: Powstań Panie, a niech będą rozproszeni nieprzyjaciele twoi, a niech uciekają, którzy cię nienawidzą, przed obliczem twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'A gdy zaś stanęła, tedy mówił: Nawróć się Panie do niezliczonego mnóstwa wojska Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'I stało się, że się lud uskarżał niesłusznie, co się nie podobało Panu. Przetoż usłyszawszy to Pan bardzo się rozgniewał, i zapalił się przeciwko nim ogień Pański, i popalił ostatnią część obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Tedy wołał lud na Mojżesza; i modlił się Mojżesz Panu, i zgasł ogień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'I nazwał imię miejsca onego Tabera: bo się zapalił przeciwko nim ogień Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'A lud pospolity, który był między nimi, chciwością wielką zjęty odwracał się; i płakali też synowie Izraelscy, mówiąc: Któż nas nakarmi mięsem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Wspominamy sobie na ryby, któreśmy jadali w Egipcie darmo, na ogórki, i na melony, i na łuczek, i na cebulę, i na czosnek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'A teraz dusza nasza wywiędła nic inszego nie mając, oprócz tej manny, przed oczyma swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'A manna była jako nasienie koryjandrowe, a barwa tej jako barwa Bdelijowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'I wychodził lud, a zbierali ją, i mełli w żarnach, albo tłukli w moździerzach a warzyli w kotłach i czynili z niej podpłomyki; a był smak jej jako smak świeżej oliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Gdy bowiem padała rosa na obóz w nocy, padała też manna nań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Tedy usłyszał Mojżesz, że lud płakał po domach swych, każdy u drzwi namiotu swego; dla czego zapaliła się popędliwość Pańska wielce, i nie podobało się też to Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'I rzekł Mojżesz do Pana: Czemużeś tak źle uczynił słudze twemu? czemużem nie znalazł łaski w oczach twoich, żeś włożył ciężar tego wszystkiego ludu na mię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Izalim ja począł ten wszystek lud? izalim go ja zrodził, iż mi mówisz: Nieś je na łonie twojem, jako piastun nosi niemowlątko, do ziemi, o którąś przysiągł ojcom ich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Gdzież mam mięso, abym dał wszystkiemu temu ludowi? bo płaczą na mię, mówiąc: Daj nam mięsa, abyśmy jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Nie mogę ja sam znieść wszystkiego ludu tego; bo to nad możność moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'A jeźli się tak ze mną obchodzić chcesz, proszę raczej mię zabij, jeźlim znalazł łaskę w oczach twoich, abym nie patrzył na swoje złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'I rzekł Pan do Mojżesza: Zbierz mi siedemdziesiąt mężów z starszych Izraelskich, które znasz, że są starszymi ludu, i książęta jego, a przywiedź je przed namiot zgromadzenia, i stać tam będę z tobą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'A Ja zstąpię, i będę tam mówił z tobą, i wziąwszy z Ducha, który jest w tobie, udzielę im; i poniosą z tobą brzemię ludu, a nie poniesiesz go ty sam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'A do ludu rzeczesz: Poświęćcie się na jutro, a będziecie jeść mięso; boście płakali w uszach Pańskich, mówiąc: Któż nas nakarmi mięsem? bo nam lepiej było w Egipcie; i da wam Pan mięsa, i będziecie jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Nie przez jeden dzień jeść będziecie, ani przez dwa dni, ani przez pięć, ani przez dziesięć dni, ani przez dwadzieścia dni:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Ale przez cały miesiąc, aż polezie przez nozdrza wasze, a zbrzydzi się wam, przeto żeście pogardzili Panem, który jest między wami, a płakaliście przed nim mówiąc: Na cóżeśmy wyszli z Egiptu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'I rzekł Mojżesz: Sześć kroć sto tysięcy pieszych jest ludu, między którym ja mieszkam, a tyś powiedział: Dam im mięsa, że będą jeść cały miesiąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Izali im owiec i wołów nabiją, aby się im dostało? Izali wszystkie ryby morskie zbiorą im, aby dostatek mieli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'I rzekł Pan do Mojżesza: Azaż ręka Pańska jest skurczona? teraz ujrzysz, jeśli się wypełni słowo moje, czyli nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Tedy wyszedł Mojżesz, i opowiedział ludowi słowa Pańskie; a zebrawszy siedemdziesiąt mężów starszych z ludu, postawił je około namiotu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'I zstąpił Pan w obłoku, i mówił do niego, a wziąwszy z Ducha, który był w nim, podzielił go między siedemdziesiąt mężów starszych; i stało się, gdy odpoczął nad nimi on Duch, tedy prorokowali, a potem nigdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Ale zostali byli dwa mężowie w obozie, imię jednego Eldad, a imię drugiego Medad; na których też odpoczął on Duch, bo oni byli napisani, choć byli nie przyszli do namiotu; a tak ci prorokowali w obozie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Tedy przybieżało pacholę, i oznajmiło Mojżeszowi, mówiąc: Eldad i Medad prorokują w obozie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Ale odpowiedziawszy Jozue, syn Nunów, sługa Mojżeszów, jeden z młodzieńców jego, rzekł: Panie mój Mojżeszu, zabroń im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Któremu odpowiedział Mojżesz: Czemuż im ty zazdrościsz dla mnie? Boże daj, aby wszystek lud Pański prorokował, a iżby dał Pan Ducha swego na nie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Wrócił się tedy Mojżesz do obozu, on i starsi Izraelscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Zatem wyszedł wiatr od Pana, i porwawszy przepiórki od morza, spuścił je na obóz, z jednej strony jako na jeden dzień chodu, z drugiej strony także jako na jeden dzień chodu, około obozu, a jakoby na dwa łokcie były nad ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Tedy wstawszy lud przez cały on dzień i przez całą noc, i nazajutrz przez wszystek dzień zbierali one przepiórki, a kto najmniej nazbierał, miał dziesięć homerów: i nawieszali ich wszędy sobie około obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Mięso jeszcze było między zębami ich nie zeżwane, gdy gniew Pański zapalił się na lud, i pobił Pan lud on plagą bardzo wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'I nazwane jest imię miejsca onego Kibrot Hataawa; albowiem tam pogrzebli lud, który pożądał mięsa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'A z Kibrot Hataawy ruszył się lud do Haserotu, i mieszkali w Haserocie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Tedy mówiła Maryja i Aaron przeciw Mojżeszowi dla żony Murzyńskiej, którą pojął; bo żonę murzynkę był pojął;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'I mówili: Izali tylko przez Mojżesza mówił Pan? azaż też nie mówił przez nas? a to usłyszał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'A Mojżesz był mąż najpokorniejszy ze wszystkich ludzi, którzy mieszkali na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'A natychmiast rzekł Pan do Mojżesza, i do Aarona, i do Maryi: Wynijdźcie was troje przed namiot zgromadzenia; i wyszli samo troje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Zatem zstąpił Pan w słupie obłokowym, i stanął we drzwiach namiotu, i zawołał Aarona i Maryi, i przyszli oboje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'I rzekł do nich: Słuchajcie teraz słów moich: Jeźli między wami będzie prorok, Ja Pan w widzeniu ukażę mu się we śnie będę mówił z nim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Ale nie taki jest sługa mój Mojżesz, który we wszystkim domu moim najwierniejszy jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Usty do ust mawiam z nim: nie w widzeniu, ani w zagadaniu, ani w podobieństwach Pana widywa; czemużeście się nie bali, mówić przeciw słudze memu Mojżeszowi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'A tak zapalił się gniewem przeciwko nim Pan, i odszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Obłok także odstąpił od namiotu, a oto, Maryja otrędowaciała, zbielawszy jako śnieg; a wejrzawszy Aaron na Maryję, ujrzał trędowatą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Potem rzekł Aaron do Mojżesza: Proszę panie mój, nie kładź teraz na nas grzechu tego, żeśmy głupio uczynili, a żeśmy zgrzeszyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Niech proszę nie będzie jako martwy płód, który gdy wychodzi z żywota matki swej, połowa ciała jego zepsowana bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Tedy zawołał Mojżesz do Pana mówiąc: Boże, proszę uzdrów ją teraz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'I odpowiedział Pan Mojżeszowi: Gdyby ojciec jej plunął na twarz jej, azażby nie miała się wstydać przez siedem dni? niech będzie wyłączona przez siedem dni z obozu, a potem przyjęta będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'I wyłączona była Maryja z obozu przez siedem dni; a lud się nie ruszył, aż była Maryja przyjęta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Potem ruszył się lud z Haserotu, a położyli się obozem na puszczy Faran.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Poślij męże, którzy by przeszpiegowali ziemię Chananejską, którą Ja dawam synom Izraelskim; po jednym mężu z każdego pokolenia poślecie, którzy by byli przedniejsi między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Wysłał je tedy Mojżesz z puszczy Faran według rozkazania Pańskiego; a oni mężowie wszyscy byli co przedniejsi z synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'A teć są imiona ich: Z pokolenia Ruben Samua, syn Zachurów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Z pokolenie Symeonowego Safat, syn Hurów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Z pokolenia Judy Kaleb, syn Jefunów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Z pokolenia Isaschar Igal, syn Józefów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Z pokolenia Efraimowego Ozeasz, syn Nunów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Z pokolenia Benjaminowego Falty, syn Rafuów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Z pokolenia Zabulon Gedyjel, syn Sodego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Z pokolenia Józefowego, to jest z potomstwa Manasesowego, Gady, syn Susego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Z pokolenia Dan Ammijel, syn Gemmalego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Z pokolenia Aser Setur, syn Michaelów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Z pokolenia Neftali, Nabi, syn Wafsego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Z pokolenia Gad Guel, syn Machego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Teć są imiona mężów, które posłał Mojżesz na przeszpiegowanie ziemi: i nazwał Mojżesz Ozeasza, syna Nunowego, Jozue.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'A posyłając je Mojżesz na przeszpiegowanie ziemi Chananejskiej, mówił do nich: Idźcie w tę stronę ku południowi, a wnijdźcie na górę:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'I oglądajcie ziemię, jaka jest, i lud, który mieszka w niej, jeźli jest mocny, czyli mdły? jeźli ich mało, czyli wiele?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Jaka też jest ziemia, w której mieszkają, jeźli dobra, czyli zła? i co są za miasta, w których mieszkają, jeźli w namieciech, czyli w obronnych miejscach?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Także co za ziemia, jeźli urodzajna, czyli niepłodna? jeźli w niej są drzewa, czyli nie? a bądźcie mężnego serca i przynieście nam owocu tamtej ziemi; a było to w ten czas, gdy się wina dostawały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'I szli, a przeszpiegowali ziemię od puszczy Syn aż do Rochob, którędy chodzą do Emat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'A idąc ku południowi przyszli aż do Hebron, gdzie byli Ahiman, Sesai i Talmai, synowie Enakowi; a Hebron siedem lat było zbudowane przed Soan Egipskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Przyszli potem aż do rzeki Eschol, i urznęli tam gałąź z gronem jednem jagód winnych, i nieśli ją na drążku, dwa także granatowe jabłka i figi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'I nazwano miejsce ono Nachal Eschol, od grona winnego, które tam byli urznęli synowie Izraelscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Zatem wrócili się od onego szpiegowania ziemi po wyjściu czterdziestu dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'A wróciwszy się, przyszli do Mojżesza i do Aarona, i do wszystkiego zgromadzenia synów Izraelskich na puszczą Faran, która jest w Kades; i dali im i wszystkiemu pospólstwu sprawę, ukazawszy im owoc onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'A powiadali im, mówiąc: Przyszliśmy do ziemi, do którejś nas był posłał, która w prawdzie opływa mlekiem i miodem, a oto, ten jest owoc jej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Tylko że mocny jest lud, który mieszka w onej ziemi; miasta także obronne są, i bardzo wielkie; do tego i syny Enakowe tameśmy widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Amalek mieszka w ziemi na południe, a Hetejczyk, i Jebuzejczyk, i Amorejczyk mieszka na górach; Chananejczyk zaś mieszka nad morzem, i nad brzegiem Jordanu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'I hamował Kaleb lud szemrzący przeciw Mojżeszowi, i mówił: Pójdźmy a posiądźmy ziemię, bo ją pewnie sobie podbijemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Ale mężowie oni, którzy z nim chodzili, rzekli: Nie będziem mogli ciągnąć przeciw tamtemu ludowi; bo mocniejszy jest nad nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'I zganili onę ziemię, którą byli przeszpiegowali, synom Izraelskim, mówiąc: Ziemia ta, którąśmy przeszli, i przeszpiegowali ją, jest ziemia pożerająca obywatele swoje, a lud wszystek, któryśmy w niej widzieli, lud jest wysokiego wzrostu. Tameśmy też widzieli olbrzymy, syny Enakowe z rodu olbrzymów; i zdaliśmy się sobie przy nich jako szarańcza, takimiż zdaliśmy się i onym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Tedy wzruszywszy się wszystko mnóstwo krzyczeli i płakał lud przez onę noc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'I szemrali przeciwko Mojżeszowi, i przeciwko Aaronowi wszyscy synowie Izraelscy; i mówiło do nich wszystko mnóstwo: Obyśmy byli pomarli w ziemi Egipskiej, albo na tej puszczy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Obyśmy byli pomarli! Czemuż wżdy Pan prowadzi nas do tej ziemi, abyśmy padli od miecza? żony nasze, i dziatki nasze aby były na łup? Izali nam nie lepiej wrócić się do Egiptu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'I mówili między sobą: Postanówmy sobie wodza, a wróćmy się do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Tedy upadł Mojżesz i Aaron na oblicze swoje przed wszystkiem zgromadzeniem synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'A Jozue, syn Nunów, i Kaleb, syn Jefunów, którzy szpiegowali ziemię, rozdarli szaty swoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'I rzekli do wszystkiego zgromadzenia synów Izraelskich, mówiąc: Ziemia, którąśmy przeszli, i przeszpiegowali ją, ziemia jest bardzo dobra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Będzieli nam Pan miłościw, tedy nas wprowadzi do tej ziemi, a da ją nam, ziemię tę, która opływa mlekiem i miodem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Jedno Panu nie bądźcie odpornymi, ani się wy bójcie ludu onej ziemi, bo jako chleb pojeść je możemy; odstąpiła obrona ich od nich, ale Pan jest z nami; nie bójcież się ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'I mówiło wszystko zgromadzenie, aby je ukamionowano; ale chwała Pańska okazała się nad namiotem zgromadzenia wszystkim synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'I rzekł Pan do Mojżesza: Dokądże mię draźnić będzie ten lud? I dokądże mi wierzyć nie będą dla tych wszystkich znaków, którem czynił między nimi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Porażę je morem, i rozproszę je; a ciebie uczynię w naród wielki i możniejszy, niż ten jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Ale rzekł Mojżesz do Pana: Oto, usłyszą Egipczanie, z których pośrodku wywiodłeś mocą swoją ten lud;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'I mówić będą z obywatelami ziemi tej, bo słyszeli, żeś ty Panie był w pośrodku ludu tego; żeś okiem w oko widziany był, o Panie, a obłok twój stawał nad nimi, a iż w słupie obłokowym chodziłeś przed nimi we dnie, a w słupie ognistym w nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Gdybyś tedy pobił lud ten wszystek aż do jednego, rzekliby poganie, którzy o twej sławie słychali, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Iż nie mógł wprowadzić Pan ludu tego do ziemi, o którą im przysiągł: przeto je pobił na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'A tak teraz niech proszę uwielbiona będzie moc Pańska, jakoś rzekł, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Pan nie rychły ku gniewowi a wielki w miłosierdziu, znosząc nieprawość i przestępstwo, który winnego nie czyni niewinnym, karząc nieprawość ojców w synach do trzeciego i do czwartego pokolenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Odpuść proszę nieprawość ludu tego według wielkości miłosierdzia twego, tak jakoś odpuszczał ludowi temu z Egiptu aż dotąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Tedy rzekł Pan: Odpuściłem według słowa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'A wszakże, jako Ja żyję, i napełniona jest chwałą Pańską wszystka ziemia:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Tak wszyscy, którzy widzieli chwałę moję, i znaki moje, którem czynił w Egipcie, i na puszczy, a kusili mię już po dziesięć kroć, ani byli posłuszni głosowi memu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Nie oglądają ziemi tej, o którąm przysiągł ojcom ich, a żaden z tych, którzy mię draźnili, nie oglądają jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Ale sługę mego Kaleba, gdyż był w nim duch inakszy, i trwał statecznie przy mnie, wprowadzę do ziemi, do której chodził, a nasienie jego odziedziczy ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Ale ponieważ Amalekita i Chananejczyk mieszkają w dolinie, przetoż jutro obróćcie się, a idźcie na puszczą, drogą ku morzu czerwonemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Nad to rzekł Pan do Mojżesza i do Aarona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'I dokądże znosić mam ten zły lud, który szemrze przeciwko mnie? długoż szemrania synów Izraelskich, którzy szemrzą przeciwko mnie, słuchać będę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Mów do nich: Żyję Ja, mówi Pan, że jakoście mówili w uszy moje, tak uczynię wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'Na tej puszczy polegą ciała wasze, i wszyscy policzeni wasi według wszystkiej liczby waszej od dwudziestego roku i wyżej, którzyście szemrali przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'A wy nie wnijdziecie do ziemi tej, o którąm podniósł rękę moję, abym ją wam dał na mieszkanie, okrom Kaleba, syna Jefunowego, i Jozuego, syna Nunowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'A dziatki wasze, o którycheście mówili, że będą na łup, te wprowadzę, i oglądają tę ziemię, którąście wy wzgardzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Ale trupy wasze, wasze trupy mówię, polegą na tej puszczy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'A synowie wasi będą się tułali po tej puszczy przez czterdzieści lat, i poniosą karanie za cudzołóstwa wasze, aż wyginą trupy wasze na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Według liczby dni, w którycheście szpiegowali ziemię, to jest czterdzieści dni, dzień każdy za rok licząc, poniesiecie nieprawości wasze czterdzieści lat, i poznacie pomstę swego odstąpienia ode mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Ja Pan mówiłem, że to uczynię temu wszystkiemu zgromadzeniu złemu, które się spiknęło przeciwko mnie; na tej puszczy poginą, i tu pomrą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Oni tedy mężowie, których słał Mojżesz na przeszpiegowanie ziemi, którzy wróciwszy się pobudzili do szemrania przeciwko niemu wszystek lud, puszczając złą sławę o ziemi onej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Pomarli mężowie oni, którzy puszczali sławę złą o ziemi, srogą plaga przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Ale Jozue, syn Nunów, i Kaleb, syn Jefunów, zostali żywi z mężów onych, którzy chodzili ku przeszpiegowaniu ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'I opowiedział Mojżesz te słowa wszystkim synom Izraelskim, i płakał lud bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Tedy rano wstawszy wstąpili na wierzch góry, mówiąc: Oto my pójdziemy na to miejsce, o którem nam Pan powiedział; bośmy zgrzeszyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Ale im powiedział Mojżesz: Przeczże wy przestępujecie słowo Pańskie? to się wam nie nada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Nie chodźcie; bo nie masz Pana między wami, abyście nie byli pobici od nieprzyjaciół waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Bo Amalekita i Chananejczyk tuż przed wami są, i polężecie od miecza; bo dla tego, żeście się odwrócili od Pana, nie będzie Pan z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'A oni przecię kusili się wnijść na wierzch góry; lecz skrzynia przymierza Pańskiego i Mojżesz nie odchodzili od obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Tedy zstąpił Amalekita i Chananejczyk, mieszkający na onej górze, a porazili je, i gonili je aż do Hormy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Powiedz synom Izraelskim, a mów do nich: Gdy przyjdziecie do ziemi mieszkania waszego, którą Ja wam dam,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'A będziecie chcieli czynić ofiarę ognistą Panu na całopalenie, albo ofiarę, bądź poślubioną bądź dobrowolną, albo też na uroczyste święta wasze, czyniąc wdzięczną wonność Panu z wołów albo z owiec:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Tedy, ktobykolwiek ofiarował ofiarę swoję Panu, niechże ofiaruje ofiarę śniedną, pszennej mąki dziesiątą część, zagniecionej z oliwą, której będzie czwarta część hynu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Przytem wina na ofiarę mokrą czwartą część hynu ofiarować będziesz przy całopaleniu, albo przy ofierze innej do każdego baranka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Przy baranie też ofiarować będziesz ofiarę śniedną, mąki pszennej dwie dziesiąte części, zaczynionej z oliwą z trzecią częścią hynu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Wina także na ofiarę mokrą trzecią część hynu ofiarować będziesz na wdzięczną wonność Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Jeźli zaś cielca ofiarować będziesz na ofiarę całopalenia, albo na ofiarę wypełnienia ślubu, albo na ofiarę spokojną Panu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'Tedy będziesz ofiarował społem z cielcem ofiarę śniedną, pszennej mąki trzy dziesiąte części, zagniecionej z oliwą z połową hynu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Wina także będziesz ofiarował na ofiarę mokrą połowę hynu, na ofiarę ognistą ku wdzięcznej wonności Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Także uczynisz przy każdym wole, i przy każdym baranie i baranku, bądź z owiec bądź z kóz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Według liczby, którą ofiarować będziecie, tak uczynicie przy każdym z nich według liczby ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Każdy w domu zrodzony tak też będzie czynił, gdy będzie oddawał ofiarę ognistą na wdzięczną wonność Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'A gdyby, gościem będąc między wami przychodzień, albo mieszkający między wami w narodziech waszych, ofiarował ognistą ofiarę ku wdzięcznej wonności Panu, jako wy czynicie, tak i on uczyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'O ludu mój! Ustawa jedna niechaj będzie tak wam, jako i przychodniowi, mieszkającemu z wami; ustawa to jest wieczna w narodziech waszych; jako wy, tak przychodzień będzie przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Prawo jedno, i jeden sąd będzie wam i przychodniowi mieszkającemu z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Powiedz synom Izraelskim, a rzecz do nich: Gdy wnijdziecie do ziemi, do której Ja was wprowadzę:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'A jeść będziecie chleb onej ziemi, ofiarować będziecie ofiarę podnoszenia Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Z pierwszych ciast waszych placek ofiarować będziecie na ofiarę podnoszenia; jako ofiarę z bojewiska, tak go ofiarować będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Z pierwszych ciast waszych ofiarować będziecie Panu ofiarę podnoszenia w narodziech waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'A gdybyście pobłądzili, i nie uczynilibyście wszystkich przykazań tych, które rozkazał Pan przez Mojżesza;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Wszystkiego, co wam Pan rozkazał przez Mojżesza, od onego dnia, którego wydał Pan przykazanie, i potem w narodziech waszych:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'Tedy jeźliby z niewiadomości zgromadzenia stało się to pobłądzenie, wszystko zgromadzenie ofiarować będzie cielca młodego jednego na całopalenie, na wdzięczną wonność Panu, także śniedną ofiarę jego, i mokrą ofiarę jego według zwyczaju, i kozła jednego z stada za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Tak oczyści kapłan wszystko zgromadzenie synów Izraelskich, i będzie im odpuszczona, gdyż się z niewiadomości stało. A oni ofiarować będą ofiarę swoję na ofiarę ognistą Panu, i na ofiarę za grzech swój przed Panem za obłądzenie swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'I będzie odpuszczono wszystkiemu zgromadzeniu synów Izraelskich, i przychodniowi, który mieszka między nimi, ponieważ wszystkiego ludu pobłądzenie jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'A jeźliby kto sam tylko zgrzeszył z niewiadomości, tedy przyniesie Panu kozę roczną na ofiarę za grzech;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'I oczyści kapłan człowieka obłądzonego, któryby zgrzeszył z niewiadomości; przed Panem oczyści go, i będzie mu odpuszczono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Tak zrodzonemu między synami Izraelskimi, jako przychodniowi, który mieszka między nimi, zakon jeden będzie wam, gdyby kto zgrzeszył z niewiadomości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Ale człowiek, któryby z hardości swawolnie zgrzeszył, tak urodzony w domu, jako i przychodzień, takowy Pana zelżył; przetoż wykorzeniony będzie on człowiek z pośrodku ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Albowiem słowem Pańskiem pogardził, i przykazanie jego zgwałcił; koniecznie wytracony będzie takowy człowiek; nieprawość jego na nim zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'I stało się, gdy byli synowie Izraelscy na puszczy, że znaleźli człowieka zbierającego drwa w dzień sabatu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'I przywiedli go, którzy go znaleźli zbierającego drwa, przed Mojżesza, i przed Aarona, i przed wszystko zgromadzenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'I dali go do więzienia; bo jeszcze im nie było oznajmiono, coby miano czynić z takowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Tedy rzekł Pan do Mojżesza: śmiercią niech umrze człowiek ten; bez litości niechaj go ukamionuje wszystko zgromadzenie za obozem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'I wywiedli go wszystko zgromadzenie za obóz, i ciskali nań kamieniem, aż umarł, jako rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Mów do synów Izraelskich, a powiedz im, aby sobie poczynili bramy na krajach szat swoich w narodziech swych, a niech przyprawią do bram sznurek hijacyntowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'I będziecie mieli te bramy, żebyście poglądając na nie, wspominali sobie na wszystkie przykazania Pańskie, abyście je czynili, i abyście się nie unosili za sercem waszem, i za oczyma waszemi, za któremi wy idąc cudzołożylibyście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Ale żebyście pamiętali i czynili wszystkie przykazania moje, a byli świętymi Bogu waszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Ja Pan, Bóg wasz, którym was wywiódł z ziemi Egipskiej, abym wam był za Boga; Jam Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Tedy się zbuntował Kore, syn Izaara, syna Kaatowego, syna Lewiego, także Datan i Abiron, synowie Elijabowi, i Hon, syn Faletów z synów Rubenowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'I powstali przeciw Mojżeszowi, a z nimi mężów z synów Izraelskich dwieście i pięćdziesiąt, książęta między ludem, których do rady przyzywano, ludzie zacni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Ci zebrawszy się przeciw Mojżeszowi, i przeciw Aaronowi, rzekli im: Wiele to na was, ponieważ wszystek ten lud, wszyscy są święci, a w pośrodku nich jest Pan; przeczże się wy wynosicie nad zgromadzeniem Pańskiem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Co gdy usłyszał Mojżesz, upadł na oblicze swoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'I rzekł do Korego i do wszystkiej roty jego, mówiąc: Rano pokaże Pan, kto jest jego, i kto jest święty, i kto ma przystępować przedeń; bo kogo sobie wybrał, temu rozkaże przystąpić do siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'To tedy uczynicie: Weźmiecie sobie kadzielnice, ty Kore, i wszystka rota twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'I nakładłszy w nie ognia, włóżcie nań kadzidła przed Panem jutro; i stanie się, że kogokolwiek obierze Pan, ten będzie świętym: wiele to na was synowie Lewiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Nad to rzekł Mojżesz do Korego: Słuchajcie proszę synowie Lewiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Izali wam to mało, że was oddzielił Bóg Izraelski od zgromadzenia Izraelskiego, abyście przystępowali do niego ku odprawowaniu usługi w przybytku Pańskim, a iżbyście stali przed zgromadzeniem, i służyli mu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'I przyjął ciebie, i wszystkę bracią twoję, syny Lewiego z tobą, że jeszcze szukacie kapłaństwa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Dla tegoż, ty i wszystka rota twoja, zbuntowaliście się przeciw Panu; bo Aaron cóż jest, żeście szemrali przeciw niemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Tedy posłał Mojżesz, aby zawołano Datana, i Abirona, synów Elijabowych, którzy odpowiedzieli: Nie pójdziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Izali mało na tem, żeś nas wywiódł z ziemi opływającej mlekiem i miodem, abyś nas pomorzył na tej puszczy, że jeszcze chcesz mieć nad nami zwierzchność i nam rozkazować?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Ku temu do ziemi opływającej mlekiem i miodem nie wprowadziłeś nas, aniś nam dał w dziedzictwo pól i winnic: izali oczy tym mężom wyłupić chcesz? Nie pójdziemy');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Tedy się rozgniewał Mojżesz bardzo, i rzekł do Pana: Nie patrz na ofiarę ich; ni jednego osła nie wziąłem od nich, anim co złego komu z nich uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Potem rzekł Mojżesz do Korego: Ty, i wszystka rota twoja, stawcie się przed Pana jutro, ty, i oni, i Aaron:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'A wziąwszy każdy kadzielnicę swoję, włóżcie w nię kadzidła, i stawcie się przed Pana, każdy z kadzielnicą swoją, dwieście i pięćdziesiąt kadzielnic, i ty, i Aaron, każdy z kadzielnicą swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Wziął tedy każdy kadzielnicę swoję, a włożywszy w nią ognia nakładli w nią kadzidła; i stanęli u drzwi namiotu zgromadzenia Mojżesz i Aaron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Ale Kore już był zebrał przeciwko nim wszystkę rotę do drzwi namiotu zgromadzenia; tedy chwała Pańska ukazała się wszystkiemu ludowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'I rzekł Pan do Mojżesza i do Aarona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Odłączcie się z pośrodku zebrania tego, abym je nagle zatracił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Lecz oni upadli na oblicza swe i rzekli: O Boże, Boże Duchów, i wszelkiego ciała! człowiek jeden zgrzeszył, a na wszystekże lud gniewać się będziesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Tedy rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Rzecz do zgromadzenia, a mów: Odstąpcie od namiotu Korego, Datana i Abirona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'A wstawszy Mojżesz, szedł do Datana i Abirona; i szli za nim starsi Izraelscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'I rzekł do zgromadzenia, mówiąc: Odstąpcie, proszę, od namiotów mężów tych niepobożnych, ani się dotykajcie wszystkiego, co ich jest, byście snać nie zginęli we wszystkich grzechach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'I odstąpili od namiotu Korego, Datana i Abirona zewsząd. Ale Datan i Abiron wyszedłszy stali u drzwi namiotów swoich, i żony ich, i synowie ich, i maluczcy ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Tedy rzekł Mojżesz: Po tem poznacie, że mię Pan posłał, abym czynił te wszystkie sprawy, a że nic z domysłu serca swego nie czynię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Jeźliże tak, jako inni ludzie umierają, pomrą ci, a zwykłem innych ludzi karaniem, karani będą, nie posłał mię Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Ale jeźliż co nowego uczyni Pan, że otworzy ziemia usta swe, i pożre je i wszystkiego co mają, i zstąpią żywo do piekła, tedy poznacie, że rozdraźnili ci mężowie Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'I stało się, gdy przestał mówić wszystkich tych słów, że się rozstąpiła ziemia pod nimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'A otworzywszy ziemia paszczękę swoję, pożarła je, i domy ich, ze wszystkimi ludźmi, którzy byli przy Korem, i wszystkie majętności ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'I zstąpili oni ze wszystkiem co mieli, żywo do piekła, i okryła je ziemia, i poginęli z pośrodku zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Wszyscy zaś Izraelitowie, którzy byli około nich, uciekali na krzyk ich, bo mówili: By snać nie pożarła i nas ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Wyszedł także ogień od Pana, i spalił onych dwieście i pięćdziesiąt mężów, którzy ofiarowali kadzenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Potem rzekł Pan do Mojżesza mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Rzecz do Eleazara, syna Aaronowego, kapłana, aby pozbierał kadzielnice z onego pogorzeliska, a ogień i tam i sam niech rozrzuci; bo są poświęcone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'A z kadzielnic tych, którzy zgrzeszyli przeciwko duszom swym, rozbiwszy je na blachy, niech obije ołtarz, bo iż w nich ofiarowali przed Panem, poświęcone są, przetoż będą na znak synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Tedy pozbierał Eleazar kapłan one miedziane kadzielnice, w których ofiarowali oni popaleni; i rozbito je na blachy, na obicie ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'Na pamiątkę synom Izraelskim, aby nie przystępował żaden obcy, któryby nie był z nasienia Aaronowego, do odprawowania kadzenia przed Panem, aby mu się nie stało jako Koremu, i jako rocie jego, jako mu był powiedział Pan przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'I szemrało wszystko zgromadzenie synów Izraelskich nazajutrz przeciwko Mojżeszowi, i przeciwko Aaronowi, mówiąc: Wyście przyczyną śmierci ludu Pańskiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'I stało się, gdy się zbierał lud przeciw Mojżeszowi, i przeciw Aaronowi, że spojrzeli ku namiotowi zgromadzenia, a oto, okrył go obłok, i okazała się chwała Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'I przyszedł Mojżesz z Aaronem przed namiot zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Wynijdźcie z pośrodku zgromadzenia tego, a wytracę je w okamgnieniu; i upadli na oblicza swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'Potem rzekł Mojżesz do Aarona: Weźmij kadzielnicę, a włóż w nią ognia z ołtarza, włóż też kadzidło, a natychmiast idź do zgromadzenia, i oczyść je; boć już wyszła popędliwość od twarzy Pańskiej, a już się zaczęło karanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Wziął tedy Aaron kadzielnicę, jako mu rozkazał Mojżesz, i przybieżał w pośrodek zgromadzenia, a oto już się była zaczęła plaga w ludzie; i uczyniwszy kadzenie oczyścił lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'I stanął Aaron między umarłymi i między żywymi, a zahamowana jest plaga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'A było umarłych od onej plagi czternaście tysięcy i siedem set, oprócz onych, którzy pomarli z przyczyny Korego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'Zatem się wrócił Aaron do Mojżesza ku drzwiom namiotu zgromadzenia, gdy plaga zahamowana była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Mów do synów Izraelskich, a weźmij od nich po lasce według domów ojców ich, to jest, od wszystkich książąt ich według domów ojców ich, dwanaście lasek, a każdego imię napiszesz na lasce jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Ale imię Aaronowe napiszesz na lasce Lewiego; bo każda laska będzie od każdego książęcia z domu ojców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'I zostawisz je w namiocie zgromadzenia przed świadectwem, gdzie się z wami schodzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'I stanie się, kogo obiorę, tego laska zakwitnie; i uśmierzę przed sobą szemrania synów Izraelskich, któremi szemrzą przeciwko wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'To gdy Mojżesz mówił do synów Izraelskich, oddali mu wszyscy książęta ich laski swoje, każdy książę laskę z domu ojca swego, dwanaście lasek; a laska Aaronowa była między laskami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'I postawił mojżesz laski one przed Panem w namiocie świadectwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'A gdy nazajutrz przyszedł Mojżesz do namiotu świadectwa, oto się zazieleniła laska Aaronowa z domu Lewiego, i wypuściła listki i wydała kwiat, i zrodziła dojrzałe migdały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'I wyniósł Mojżesz one wszystkie laski od obliczności Pańskiej do wszystkich synów Izraelskich; które gdy ujrzeli, wziął każdy laskę swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'I rzekł Pan do Mojżesza: Odnieś laskę Aaronową przed świadectwo, aby była zachowana na znak synom odpornym, a zahamujesz szemranie ich przeciwko mnie, aby nie pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'I uczynił Mojżesz; jako mu Pan rozkazał, tak uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'I rzekli synowie Izraelscy do Mojżesza, mówiąc: Oto umieramy, niszczejemy, wszyscy giniemy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Każdy, ktokolwiek przystępuje do przybytku Pańskiego, umiera; izali do szczętu wytraceni być mamy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Potem rzekł Pan do Aarona: Ty i synowie twoi, i dom ojca twego z tobą, poniesiecie nieprawość świątnicy. I ty i synowie twoi z tobą poniesiecie nieprawość kapłaństwa waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Bracią także twoję, pokolenie Lewiego, ród ojca twego, przypuścisz do siebie, aby byli przy tobie, i posługowali tobie; a ty i synowie twoi z tobą służyć będziecie przed namiotem świadectwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Oni będą przestrzegali rozkazania twego, i pilnowali wszystkiego namiotu; wszakże do naczynia śwątnicy, i do ołtarza, przystępować nie będą, aby nie pomarli, i oni i wy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'I przyłączą się do ciebie, pilnie strzegąc namiotu zgromadzenia w każdej usłudze namiotu; a nikt obcy niechaj się nie mięsza między was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Wy tedy pilnie strzeżcie świątnicy, i usługi ołtarzowej, by się napotem nie wzruszył gniew przeciwko synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Bom oto ja obrał bracią waszę Lewity, z pośród synów Izraelskich, wam za dar, oddane Panu, aby odprawowali usługę w namiocie zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Ale ty i synowie twoi z tobą, przestrzegać będziecie kapłaństwa waszego przy każdej usłudze ołtarzowej, i za zasłoną służyć będziecie; urząd kapłaństwa waszego dałem wam darmo; gdyby kto obcy przystąpił, umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Nadto mówił Pan do Aarona: Otom ja dał tobie pod straż ofiary moje podnoszone; wszystkie rzeczy poświęcone od synów Izraelskich tobiem je dał dla pomazania, i synom twoim prawem wiecznem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'To będzie twoje z rzeczy poświęconych, które nie bywają palone. Każda ofiara ich, bądź ofiara śniedna ich, bądź ofiara za grzech ich, albo ofiara za występek ich, cokolwiek mi oddawać będą to będzie rzeczą poświęconą tobie i synom twoim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Na miejscu najświętszem jadać to będziesz; wszelki mężczyzna będzie jadł z tego; rzeczą poświęconą to będzie tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'To też twoje będzie, ofiara podnoszenia darów ich ze wszystkiemi ofiarami tam i sam obracania synów Izraelskich; tobiem je dał, i synom twoim, i córkom twoim z tobą, prawem wiecznem; każdy czysty w domu twoim będzie je jadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Każdą co najprzedniejszą oliwę, i każde co najlepsze wino, i zboże, pierwiastki ich, które ofiarują Panu, tobiem je dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Pierwociny ze wszystkich rzeczy, które będą w ziemi ich, które przyniosą Panu, twoje będą; każdy czysty w domu twoim jadać je będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Wszystko, cokolwiek jest poślubione w Izraelu, twoje będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Cokolwiek otwiera żywot wszelkiego ciała, a bywa ofiarowane Panu, tak z ludzi jako z bydła, twoje będzie; ale pierworodne z ludzi okupisz, także pierworodne nieczystego bydła okupisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'A okup jego, gdy mu miesiąc minie, dasz według szacunku twego pięć syklów srebra według sykla świątnicy; dwadzieścia pieniędzy waży sykiel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Ale pierworodnego od krowy, albo pierworodnego od owcy, albo pierworodnego od kozy, nie dasz na okup; bo poświęcone są; krew ich wylejesz na ołtarz, a tłustość ich zapalisz na ofiarę ognistą dla wdzięcznej wonności Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Ale mięso ich twoje będzie; jako mostek podnoszenia, i jako łopatka prawa, twoje będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Wszystkie ofiary podnoszenia z rzeczy poświęconych, które przynosić będą synowie Izraelscy Panu, dałem tobie, i synom twym, i córkom twoim z tobą, prawem wiecznem; ustawa to nienaruszona, i wieczna przed Panem, tobie i nasieniu twemu z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Potem mówił Pan do Aarona: W ziemi ich dziedzictwa mieć nie będziesz, i działu nie będziesz miał między nimi; Jam dział twój, i dziedzictwo twoje w pośród synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Synom zaś Lewiego otom dał wszystkę dziesięcinę w Izraelu dziedzicznie za służbę ich, którą wykonywają służąc około namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'A niechaj nie przystępują więcej synowie Izraelscy do namiotu zgromadzenia, aby nie ponieśli grzechu i nie pomarli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Ale sami Lewitowie odprawować będą usługę około namiotu zgromadzenia, i sami poniosą nieprawość swoję. Ustawa to wieczna będzie w narodziech waszych, aby w pośród synów Izraelskich dziedzictwa nie mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Albowiem dziesięciny synów Izraelskich które przynosić będą na ofiarę podnoszenia Panu, dałem Lewitom za dziedzictwo; przetoż rzekłem do nich: W pośród synów Izraelskich nie będą mieli dziedzictwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Potem rzekł Pan do Mojżesza mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Mów też do Lewitów, a powiedz im: Gdy weźmiecie od synów Izraelskich dziesięciny, którem ja wam dał od nich za dziedzictwo wasze, tedy ofiarować będziecie ofiarę podnoszenia Panu dziesiątą część dziesięcin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'A poczytana wam będzie ta ofiara wasza jako zboże z bojewiska, i jako obfitość wina z prasy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Tak wy też ofiarować będziecie ofiarę podnoszenia Panu ze wszystkich dziesięcin waszych, które weźmiecie od synów Izraelskich, a oddacie z nich ofiarę podnoszenia Panu, Aaronowi kapłanowi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Ze wszystkich dochodów waszych ofiarować będziecie wszelką ofiarę podnoszenia Panu; ze wszystkiego co najlepsze jest, ofiarujecie cząstkę poświęconą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Powiesz im też: Gdy oddawać będziecie z tego, co najlepsze jest, tedy poczytano będzie Lewitom jako urodzaje z bojewiska; i jako urodzaj z prasy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'I będziecie to jeść na każdem miejscu, wy i czeladź wasza; albowiem to jest zapłata wasza za służbę waszę przy namiocie zgromadzenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'I nie poniesiecie za to grzechu, gdy ofiarować będziecie co najlepszego jest z tego, i nie splugawicie rzeczy poświęconych od synów Izraelskich, i nie pomrzecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'I rzekł Pan do Mojżesza i do Aarona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Tać jest ustawa zakonu, którą rozkazał Pan, mówiąc: Powiedz synom Izraelskim, aby przywiedli do ciebie jałowicę płową, zdrową, na której by nie było zmazy, i na której by nie postało jarzmo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Tę oddacie Eleazarowi kapłanowi, który ją wywiedzie za obóz, i zabita będzie przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'A wziąwszy Eleazar kapłan ze krwi jej na palec swój, kropić będzie przeciw namiotowi zgromadzenia oną krwią siedem kroć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Potem każe tę jałowicę spalić przed oczyma swemi; skórę jej, i mięso jej, i krew jej, z gnojem jej spali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'I weźmie kapłan drzewo cedrowe, i hizop, i karmazyn dwa kroć farbowany, a wrzuci do ognia, gdzie się jałowica pali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'I upierze szaty swe kapłan, a omyje ciało swoje wodą; a potem wnijdzie do obozu, i będzie nieczystym kapłan aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Ten też, który ją palić będzie, upierze szaty swe w wodzie, i omyje ciało swe wodą, a będzie nieczystym aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'I zbierze człowiek czysty popiół onej jałowicy, i wysypie go precz za obóz, na miejscu czystem, a będzie dla zgromadzenia synów Izraelskich chowany do wody oczyszczenia, gdyż jest ofiara za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'I upierze ten, co będzie zbierał popiół onej jałowicy, szaty swe, i będzie nieczystym aż do wieczora. A będzie to synom Izraelskim, i przychodniowi mieszkającemu między nimi, ustawą wieczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Kto by się dotknął jakiegokolwiek trupa człowieczego, nieczystym będzie przez siedem dni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Taki oczyszczać się będzie tą wodą dnia trzeciego i dnia siódmego, a czystym będzie; a jeśliby się nie oczyścił dnia trzeciego i dnia siódmego, nieczystym będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Kto by się kolwiek dotknął martwego ciała człowieka, który umarł, a nie oczyścił się, przybytek Pański splugawił; przetoż takowy wytracony będzie z Izraela, bo wodą oczyszczenia nie był pokropiony; nieczystym będzie, nieczystość jego zostanie na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Ta zaś jest ustawa: gdyby człowiek umarł w namiocie, ktobykolwiek wszedł do tego namiotu, i cokolwiek było w onym namiocie, nieczystym będzie przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Także wszelkie naczynie odkryte, które by nie miało nakrycia na sobie, nieczyste będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Także kto by się kolwiek dotknął na polu, bądź mieczem zabitego, bądź umarłego, bądź kości człowieczej, albo grobu, nieczystym będzie przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Wezmą tedy dla onego nieczystego popiołu jałowicy spalonej za grzech, i naleją nań wody żywej do naczynia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Weźmie też hizopu, i omoczy go w onej wodzie człowiek czysty, i pokropi namiot, i wszystko naczynie, i wszystkich ludzi, którzy by tam byli, także onego, który się dotknął kości, albo zabitego, albo zmarłego, albo grobu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Pokropi tedy czysty nieczystego dnia trzeciego i dnia siódmego; a gdy go oczyści dnia siódmego, tedy upierze szaty swe, i omyje się wodą, a będzie czystym w wieczór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'A mąż, któryby nieczystym będąc nie oczyścił się, wykorzeniona będzie ta dusza z pośrodku zgromadzenia, bo świątnicę Pańską splugawił; wodą oczyszczenia nie będąc pokropionym, nieczystym jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'I będzie im to za ustawę wieczną; a kto będzie pokrapiał wodą oczyszczenia, upierze szaty swoje; a kto by się dotknął tej wody oczyszczenia, nieczystym będzie aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Czegokolwiek się dotknie nieczysty, nieczyste będzie; człowiek także, któryby się tego dotknął nieczysty będzie aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'I przyszło wszystko mnóstwo synów Izraelskich na puszczą Syn, miesiąca pierwszego; i mieszkał lud w Kades; gdzie umarła Maryja, i tamże jest pogrzebiona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'A gdy lud nie miał wody, zebrali się przeciw Mojżeszowi, i przeciw Aaronowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'I swarzył się lud z Mojżeszem, i rzekli mówiąc: Obyśmy byli pomarli, gdy pomarli bracia nasi przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'I przeczżeście zawiedli to zgromadzenie Pańskie na tę puszczę, abyśmy tu pomarli, my i dobytki nasze?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'A po cóżeście nas wywiedli z Egiptu, abyście nas wprowadzili na to złe miejsce, na którem się nie rodzi ani zboże, ani figi, ani grona winne, ani jabłka granatowe; nawet wody nie masz dla napoju?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Tedy odszedł Mojżesz i Aaron od ludu do drzwi namiotu zgromadzenia, i upadli na oblicza swoje; i ukazała się chwała Pańska nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'I rzekł Pan do Mojżesza mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Weźmij laskę, a zgromadziwszy wszystek lud, ty i Aaron, brat twój, mówcie do tej skały przed oczyma ich, a wyda wodę swą; i wywiedziesz im wodę z skały, a dasz napój temu mnóstwu, i bydłu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Tedy wziął Mojżesz laskę przed obliczem Pańskiem, jako mu rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'I zgromadził Mojżesz z Aaronem wszystek lud przed skałę, i mówił do nich: Słuchajcież teraz ludzie odporni, izali z tej skały możemy wam wywieść wodę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Zatem podniósł Mojżesz rękę swoję, i uderzył w skałę laską swą dwa kroć, a wyszły wody obfite i piło ono mnóstwo, i bydło ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'I rzekł Pan do Mojżesza i do Aarona: Dlatego, żeście mi nie uwierzyli, abyście mię poświęcili przed oczyma synów Izraelskich, przetoż nie wprowadzicie zgromadzenia tego do ziemi, którąm im dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Teć są wody poswarku, o które się swarzyli synowie Izraelscy z Panem, i poświęcony jest w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Potem posłał Mojżesz posły z Kades do króla Edomskiego, mówiąc: Tak ci kazał powiedzieć brat twój Izrael: Ty wiesz o wszystkich trudnościach, które przyszły na nas;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Jako zstąpili byli ojcowie nasi do Egiptu, i mieszkaliśmy w Egipcie przez wiele lat; i jako nas trapili Egipczanie, i ojce nasze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'I wołaliśmy do Pana, a wysłuchał głos nasz, i posławszy Anioła, wywiódł nas z Egiptu; a otośmy już w Kades, mieście przy granicy twojej');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Niech, proszę, przejdziemy przez ziemię twoję; nie pójdziemy przez pola, ani przez winnice, ani będziemy pić wód z twoich studzien; gościńcem pójdziemy, nie uchylimy się na prawo ani na lewo, aż przejdziemy granice twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Na to odpowiedział mu Edom: Nie pójdziesz przez moję ziemię, bym snać z mieczem nie wyszedł przeciw tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'I rzekli mu synowie Izraelscy: Bitym gościńcem pójdziemy, a jeślibyśmy wody twoje pili, my i bydła nasze, zapłacimyć je; nic innego nie żądamy, tylko abyśmy pieszo przeszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'I powiedział: Nie przejdziesz. I ruszył się Edom przeciwko nim, z wojskiem wielkiem, i możną ręką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'A gdy nie chciał Edom pozwolić Izraelowi przejścia przez granice swoje, tedy Izrael uczynił odwrót od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'A ruszywszy się z Kades; przyszli synowie Izraelscy i wszystko zgromadzenie do góry Hor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'I rzekł Pan do Mojżesza i do Aarona na górze Hor, nad granicą ziemi Edomskiej, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Będzie Aaron przyłączon do ludu swego; albowiem nie wnijdzie do ziemi, którąm dał synom Izraelskim, przeto żeście odporni byli słowu mojemu przy wodach poswarku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Weźmijże Aarona i Eleazara syna jego, a każ im wstąpić na górę Hor;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'I zewlecz Aarona z szat jego, a oblecz w nie Eleazara, syna jego; bo Aaron przyłączon będzie do ludu swego, i tam umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'I uczynił Mojżesz, jako rozkazał Pan; i wstąpili na górę Hor przed oczyma wszystkiego zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'I zewlókł Mojżesz Aarona z szat jego, a oblekł w nie Eleazara syna jego; i umarł tam Aaron na wierzchu góry, a Mojżesz z Eleazarem zstąpili z góry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Widząc tedy wszystko zgromadzenie, iż Aaron umarł, płakali Aarona przez trzydzieści dni, wszystek dom Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'A gdy usłyszał Chananejczyk, król Harat, który mieszkał na południe, że Izraelczycy ciągnęli oną drogą, którą byli szpiegowie przeszli, tedy zwiódł bitwę z Izraelem, i pojmał ich wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Tam uczynił Izrael ślub Panu, mówiąc: Jeźliże podaż lud ten w ręce moje, do gruntu wywrócę miasta ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'I wysłuchał Pan głos Izraela, a podał mu Chananejczyki: i wytracił je z gruntu, i miasta ich, a nazwał imię onego miejsca Chorma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Potem ruszyli się od góry Hor drogą ku morzu czerwonemu, aby obeszli ziemię Edomską; i utrudził się lud bardzo w onej drodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Przetoż mówił lud przeciw Bogu, i przeciw Mojżeszowi: Przeczżeście nas wywiedli z Egiptu, aby my pomarli na tej puszczy? bo nie masz chleba, ani wody, a dusza nasza obrzydziła sobie ten chleb nikczemny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Przetoż przypuścił Pan na lud węże ogniste, którzy kąsali lud; i pomarło wiele ludu z Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'I przyszedłszy lud do Mojżesza, rzekli: Zgrzeszyliśmy, żeśmy mówili przeciw Panu, i przeciw tobie. Módl się Panu, aby oddalił od nas te węże; i modlił się Mojżesz za ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'I rzekł Pan do Mojżesza: uczyń sobie węża miedzianego, a wystaw go na drzewcu; i stanie się, ktokolwiek ukąszony będąc wejrzy nań, że żyw zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Sprawił tedy Mojżesz węża miedzianego, i wystawił go na drzewcu; i było to, gdy kogo wąż ukąsił, a spojrzał na węża miedzianego, że żyw został.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Zatem ruszyli się synowie Izraelscy, a stanęli obozem w Obot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'A z Obot ruszywszy się położyli się obozem na pagórkach gór Habarym na puszczy, która jest przeciw Moabczykom od wschodu słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'A odszedłszy stamtąd położyli się obozem nad potokiem Zered.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Stamtąd odciągnąwszy położyli się obozem u brodu Arnon, który jest na puszczy, a wychodzi z granicy Amorejskiej: albowiem Arnon jest granica Moabska między Moabczykiem i Amorejczykiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Przetoż mówi się w księgach wojen Pańskich: Przeciwko Wahebowi w wichrze walczył, i przy potokach Arnon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Bo ściekanie tych potoków, które się nachyliło (toczy) ku położeniu Har, to się ściąga ku granicy Moabskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Stamtąd potem przyszli do Beer; a tać jest ona studnia, o której mówił Pan do Mojżesza: Zgromadź lud a dam im wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Tedy śpiewał Izrael tę piosnkę: Wystąp studnio; śpiewajcież o niej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Studnia, którą wykopali książęta, wykopali ją hetmani ludu z ustawcą zakonu, laskami swojemi. A z tej puszczy ruszyli się do Matana;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'A z Matana do Nahalijelu, a z Nahalijelu do Bamotu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'A z Bamotu ku Hagaj, które jest w polach Moabskich, na wierzchu pagórka, który leży ku puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'I posłał Izrael posły do Sehona, króla Amorejskiego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Niech przejdziemy przez ziemię twoję; nie pójdziemy ani przez pola ani przez winnice; nie będziemy pić wód z studzien twoich; gościńcem pójdziemy, aż przejdziemy granice twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Ale nie pozwolił Sehon Izraelowi iść przez granice swoje; i zebrawszy Sehon wszystek lud swój, wyciągnął przeciw Izraelowi na puszczę, a gdy przyszedł do Jahazy, zwiódł bitwę z Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'I poraził go Izrael ostrzem miecza, i odziedziczył ziemię jego od Arnonu aż do Jaboku, i aż do ziemi synów Ammonowych; albowiem opatrzone były granice Ammonitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Tedy pobrał Izrael wszystkie miasta one, i mieszkał we wszystkich miastach Amorejskich, w Hesebon, i we wszystkich wsiach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Bo Hesebon było miasto Sehona, króla Amorejskiego, który, gdy pierwej walczył z królem Moabskim, wziął mu był wszystkę ziemię jego z rąk jego aż po Arnon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Dla tegoż mówią w przypowieści: Pójdźcie do Hesebon, a niech zbudują i naprawią miasto Sechonowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Albowiem wyszedł ogień z Hesebon, a płomień z miasta Sechonowego, i popalił Ar Moabskie, i obywatele wysokich miejsc Arnon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Biada tobie Moab, zginąłeś o ludu Chamos! podał syny swoje na uciekanie, i córki swoje do więzienia królowi Amorejskiemu Sehonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'A zaginęło panowanie ich od Hesebona aż do Dybona; a poburzyliśmy je aż do Nofe, które idzie aż do Medady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'I mieszkał Izrael w ziemi Amorejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Tedy posłał Mojżesz na szpiegi do Jazer, którego wsi pobrali, wypędziwszy Amorejczyki, którzy tam byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Potem obróciwszy się szli ku Basan; gdzie wyciągnął Og, król Basański, przeciwko nim, sam i wszystek lud jego, aby z nimi stoczył bitwę w Edrej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Tedy rzekł Pan do Mojżesza: Nie bój się go; bo w ręce twoje podałem go, i wszystek lud jego, i ziemię jego, i uczynisz mu, jakoś uczynił Sehonowi, królowi Amorejskiemu, który mieszkał w Hesebon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'I porazili go, i syny jego, ze wszystkim ludem jego, tak iż nikogo z niego nie zostawili, i posiedli dziedzicznie ziemię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Stamtąd ruszyli się synowie Izraelscy, i położyli się obozem na polach Moabskich, z tej strony Jordanu przeciw Jerychowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'A widząc Balak, syn Seforów, wszystko, co uczynił Izrael Amorejczykowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Uląkł się Moab tego ludu wielce, bo go było wiele; i zatrwożył sobą Moab dla synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Przetoż rzekł Moab do starszych Madyjańskich: Teraz pożre to mnóstwo wszystko, co jest około nas, jako wół pożera trawę polną. A Balak, syn Seforów, był królem Moabskim na on czas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'I posłał posły do Balaama, syna Beorowego, do Pethoru miasta, które jest nad rzeką ziemi synów ludu jego, aby go wezwano, mówiąc: Oto lud wyszedł z Egiptu, oto okrył wierzch ziemi, i osadza się przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Przetoż teraz przyjdź proszę, a przeklinaj mnie kwoli lud ten, bo możniejszy jest nad mię; owa snać go będę mógł porazić, i wygnać go z ziemi; bo ja wiem, że komu błogosławisz, błogosławiony będzie; a kogo przeklinasz, przeklęty będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Poszli tedy starsi Moabscy, i starsi Madyjańscy, mając zapłatę za wieszczbę w rękach swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'A przyszedłszy do Balaama, powiedzieli mu słowa Balakowe. I rzekł do nich: Zostańcie tu przez noc, a dam wam odpowiedź, jako mi oznajmi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'I zostały książęta Moabskie z Balaamem. Tedy przyszedł Bóg do Balaama, i rzekł: Cóż to za mężowie u ciebie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'I odpowiedział Balaam Bogu: Balak, syn Seforów, król Moabski, posłał do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Oto lud, który wyszedł z Egiptu, i okrył wierzch ziemi; terazże pójdź, przeklinaj mi go; snać będę mógł walczyć z nim, i wypędzę go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Tedy rzekł Bóg do Balaama: Nie chodź z nimi, ani przeklinaj ludu tego; bo jest błogosławiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'A wstawszy rano Balaam rzekł do książąt Balakowych: Wróćcie się do ziemi waszej; bo mi nie pozwala Pan puścić się w drogę z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Wstawszy tedy książęta Moabskie, wrócili się do Balaka, i powiedzieli: Nie chciał Balaam iść z nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Tedy po wtóre posłał Balak więcej książąt, i zacniejszych nad pierwsze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Którzy przyszedłszy do Balaama, mówili mu: Tak mówi Balak, syn Seforów: Nie ociągaj się proszę przyjść do mnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Albowiem ci wielką uczciwość wyrządzę, i wszystko, cobyś mi rzekł, uczynię; tylko przyjdź proszę a przeklinaj mi ten lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Tedy odpowiedział Balaam, i rzekł do sług Balakowych: Choćby mi dał Balak pełen dom swój srebra i złota, nie mógłbym przestąpić słów Pana, Boga mego, i uczynić przeciwko niemu, bądź mało bądź wiele;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Ale proszę zostańcie tu i wy przez noc, a dowiem się, co jeszcze Pan będzie mówił ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Tedy przyszedł Bóg do Balaama w nocy, i rzekł do niego: Jeźliż, aby cię wezwali, przyszli mężowie ci, wstańże, idź z nimi; a wszakże, coć rozkażę, to uczynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Tedy wstawszy Balaam rano, osiodłał oślicę swoją, i jechał z książęty Moabskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'I rozpalił się gniew Boży, że on jechał; i stanął Anioł Pański na drodze, aby mu zastąpił; a on jechał na oślicy swojej, i dwoje pacholąt jego z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'A gdy ujrzała oślica Anioła Pańskiego, stojącego na drodze, a miecz jego dobyty w ręce jego, tedy ustąpiła oślica z drogi a szła na rolę, lecz bił Balaam oślicę, aby ją nawiódł na drogę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Tedy stanął Anioł Pański na ścieżce u winnicy między dwoma płoty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'A widząc oślica Anioła Pańskiego, przyciskała się do płota, tak iż przyparła nogę Balaamową do ściany; a on znowu ją bił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Potem Anioł Pański szedł dalej, i stanął na miejscu ciasnem, gdzie nie było drogi do ustąpienia na prawo ani na lewo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'A widząc oślica Anioła Pańskiego, padła pod Balaamem; i rozgniewał się Balaam wielce, a bił oślicę kijem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Zatem otworzył Pan usta onej oślicy, i rzekła do Balaama: Cóżem ci uczyniła, żeś mię bił już po trzy kroć?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'I rzekł Balaam do oślicy: Iż ze mnie szydzisz; bym był miał miecz w ręku swych, byłbym cię teraz zabił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Tedy oślica rzekła do Balaama: Azażem ja nie oślica twoja, na którejś jeżdżał, jakoś mię dostał, aż do tego czasu? A on rzekł: Nigdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Wtem otworzył Pan oczy Balaamowe, że obaczył Anioła Pańskiego, stojącego na drodze, i miecz jego dobyty w ręce jego; tedy skłoniwszy się, pokłonił się twarzą swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'I rzekł do niego Anioł Pański: Przeczżeś bił oślicę swoję już po trzy kroć? Otom Ja wyszedł, abym się tobie sprzeciwił; bo przewrotna jest droga twoja przede mną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'A widząc mię oślica ustąpiła przede mną po trzy kroć, a gdyby była nie ustąpiła przede mną, już bym cię był teraz zabił a onę bym był żywą zostawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Zatem rzekł Balaam do Anioła Pańskiego: Zgrzeszyłem, albowiem nie widziałem, żeś ty stanął przeciwko mnie na drodze; przetoż teraz, jeźlić się to nie podoba, wrócę się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Lecz Anioł Pański rzekł do Balaama: Jedź z ludźmi tymi; wszakże tylko, co Ja tobie powiem, mówić będziesz. I jechał Balaam z książęty Balakowymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'A gdy usłyszał Balak, iż przyjeżdża Balaam, wyjechał przeciwko niemu, do niektórego miasta Moabskiego, które jest na granicy Arnonu, które jest przy końcu granicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Tedy rzekł Balak do Balaama: Azażem z pilnością nie posyłał do ciebie wzywając cię? Czemużeś nie przyjechał do mnie? azaż cię zacnie uczcić nie mogę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'I rzekł Balaam do Balaka: Otom przyjechał do ciebie; izali teraz, choćbym chciał, będę mógł co mówić? słowo, które włoży Bóg w usta moje, mówić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Tedy jechał Balaam z Balakiem a przyjechali do miasta Husot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'A tak Balak dał nabić wołów i owiec, i posłał do Balaama, i do książąt, którzy z nim byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'I stało się nazajutrz, że wziął Balak Balaama, i wprowadził go na wyżyny Baalowe, skąd widział i najdalszą część ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'I rzekł Balaam do Balaka: Zbuduj mi tu siedem ołtarzów, a nagotuj mi tu siedem cielców, i siedem baranów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Uczynił tedy Balak, jako mówił Balaam, i ofiarował Balak z Balaamem cielca, i barana na każdym ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Potem rzekł Balaam do Balaka: Stań przy całopaleniu twojem, a ja odejdę; owa się snać spotka Pan ze mną, a cokolwiek mi objawi, powiem ci; i odszedł sam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'I spotkał się Pan z Balaamem; i rzekł mu Balaam: Postawiłem siedem ołtarzów, i ofiarowałem cielca i barana na każdym ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Tedy Pan włożył słowa w usta Balaamowe, i rzekł: Wróć się do Balaka, a mów tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'I wrócił się do niego, a oto stał u ofiary swojej palonej, on i wszystkie książęta Moabskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'A tak zaczął przypowieść swoję, i rzekł: Z Aram przywiódł mię Balak, król Moabski, z gór wschodnich, mówiąc: Przyjdź, przeklinaj mi Jakóba, a przyjdź, złorzecz Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Jakoż ja przeklinać mam, kogo Bóg nie przeklina? albo jako złorzeczyć mam, komu Pan nie złorzeczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Bo z wierzchu skał oglądam go, a z pagórków będę nań patrzał; oto, lud ten sam mieszkać będzie, a między narody mieszać się nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Któż policzy proch Jakóbów, i liczbę czwartej części Izraela? Niech umrze dusza moja śmiercią sprawiedliwych, i niech będzie dokonanie moje, jako ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Tedy rzekł Balak do Balaama: Cóżeś mi uczynił? Na przeklinanie nieprzyjaciół moich przyzwałem cię, a oto, błogosławiąc błogosławiłeś im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'A on odpowiedział i rzekł: Azaż nie mam tego pilnować i mówić, co Pan włożył w usta moje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'I rzekł do niego Balak: Pójdź proszę ze mną na miejsce inne, żebyś go stamtąd widział; (ale tylko część jego ujrzysz, a wszystkiego widzieć nie będziesz;) przeklinajże mi go stamtąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'I zawiódł go na pole Sofim, na wierzch góry Fazga, i zbudował siedem ołtarzów, i ofiarował cielca i barana na każdym ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Rzekł tedy Balaam do Balaka: Zostań tu przy całopaleniu twojem, a ja zabieżę tam Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'I zaszedł Pan Balaamowi, który włożył słowa w usta jego, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Wróć się do Balaka, a tak mów. Przyszedł tedy do niego, a oto on stał przy całopaleniu swojem, i książęta Moabskie z nim; i rzekł mu Balak: Cóż ci powiedział Pan?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'I zaczął rzecz swą temi słowy: Wstań Balaku, a słuchaj: przyjmij w uszy swe słowa moje, synu Seforów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Nie jestci Bóg jako człowiek, aby kłamał, ani jako syn człowieczy, ażeby żałował; azaż on rzecze, a nie uczyni? wymówi, a nie wypełni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Otom wziął rozkazanie, abym błogosławił; on błogosławieństwo dał a ja go nie odwrócę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Nie baczy nieprawości w Jakóbie; ani widzi przestępstwa w Izraelu; Pan, Bóg jego, jest z nim, a trąbienie zwycięstwa królewskiego przy nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Bóg wywiódł je z Egiptu, mocą jednorożcową był mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Albowiem nie masz wieszczby przeciw Jakóbowi, ani wróżki przeciw Izraelowi; od tego czasu mówiono będzie o Jakóbie i o Izraelu, co z nimi uczynił Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Oto lud ten jako lew silny powstanie, jako lwię młode podniesie się, aż pożre łupy, i krew pobitych wypije.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Tedy rzekł Balak do Balaama: Ani ich przeklinaj więcej, ani im też błogosław więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'I odpowiedział Balaam, a rzekł do Balaka: Azażem ci nie powiadał, mówiąc, że cokolwiek mówić będzie Pan, to uczynię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'I rzekł Balak do Balaama: Pójdź, proszę, zawiodę cię na insze miejsce, jeźli snać podoba się Bogu, żebyś je stamtąd przeklinał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Tedy wiódł Balak Balaama na wierzch góry Fegor, która patrzy ku puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'I rzekł Balaam do Balaka: Zbuduj mi siedem ołtarzów, a nagotuj mi tu siedem cielców i siedem baranów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'I uczynił Balak, jako mu rozkazał Balaam, i ofiarował cielca i barana na każdym ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'A gdy obaczył Balaam, że się podobało Panu, aby błogosławił Izraelowi, już nie chodził, jako przedtem, raz i drugi dla wieszczby; ale obrócił ku puszczy twarz swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'A podniósłszy Balaam oczy swe, obaczył Izraela mieszkającego według pokoleń swoich, i był nad nim Duch Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'I zaczął przypowieść swoję, a mówił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'Rzekł Balaam, syn Beorów, rzekł mąż, którego oczy są otworzone, rzekł słyszący wymowy Boże, a który widzenie Wszechmocnego widział, który, kiedy padnie, otworzone ma oczy:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Jako piękne są namioty twoje, o Jakubie! przybytki twoje, o Izraelu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Jako potoki rozciągnęły się, jako ogrody przy rzece, jako drzewa wonne, które Pan nasadził, jako cedry nad wodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Popłynie woda z wiadra jego, a nasienie jego będzie nad wodami obfitemi, a będzie wywyższon nad Agaga król jego, a wyniesie się królestwo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Bóg wywiódł go z Egiptu, mocą jednorożcową był mu; pożre narody przeciwne sobie, a kości ich pokruszy, i strzałami swemi przerazi je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Położył się, leży jako lwię, i jako lew silny; któż go obudzi? kto być błogosławił, błogosławiony, a kto by cię przeklinał, przeklęty będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Tedy się zapalił gniew Balaka na Balaama, a klasnąwszy rękami swemi, rzekł Balak do Balaama: Dla złorzeczenia nieprzyjaciołom moim przyzwałem cię, a oto im błogosławił już po trzy kroć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Przetoż teraz uchodź na miejsce swoje; rzekłem ci był: Zacnie cię uczczę; ale oto pozbawił cię Pan tej czci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'I rzekł Balaam do Balaka: Izażem i posłom twoim, któreś słał do mnie, nie powiedział mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Choćby mi dał Balak pełen dom swój srebra i złota, nie będę mógł przestąpić słowa Pańskiego, abym czynił co dobrego albo złego sam z siebie; co mi opowie Pan, to będę mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'A teraz oto ja odchodzę do ludu mego, jednak oznajmięć, co uczyni lud ten ludowi twemu na potem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'I zaczął przypowieść swoję i rzekł: Mówił Balaam, syn Beorów, mówił mąż, którego oczy są otworzone;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Mówił ten, który słyszał wyroki Boże, a który ma umiejętność Najwyższego; który widział widzenie Wszechmocnego; który, kiedy padnie, otworzone ma oczy:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Ujrzę go, ale nie teraz; oglądam go, ale nie z bliska; wynijdzie gwiazda z Jakuba i powstanie laska z Izraela, i pobije książęta Moabskie, i wytraci wszystkie syny Setowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'I przyjdzie Edom w opanowanie, a Seir będzie pod władzą nieprzyjaciół swoich, a Izrael będzie sobie poczynał mężnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'I będzie panował, który wynijdzie z Jakuba, a wytraci ostatki z miast.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'A gdy spojrzał na Amaleka, zaczął przypowieść swoję, i rzekł: Początek narodów jest Amalek, a ostatek jego do szczętu zaginie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Potem wejrzawszy na Kenejczyka zaczął przypowieść swoję i rzekł: mocneć jest mieszkanie twoje, a założyłeś na skale gniazdo twoje');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Wszakże spustoszony będzie Kenejczyk, aż cię Assur zaprowadzi do więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Znowu zaczął przypowieść swoję, i rzekł: Ach! któż będzie żyw, gdy to uczyni Bóg?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Bo okręty przypłyną od brzegów Chyttymskich, i utrapią Assyryjany, utrapią Hebrejczyki; ale też same do szczętu zaginą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Wstał tedy Balaam i odszedł, a wrócił się na miejsce swoje; także i Balak poszedł w drogę swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Potem gdy mieszkał Izrael w Syttim, począł lud cudzołożyć z córkami Moabskiemi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Które wzywały ludu ku ofiarom bogów swoich; a jedząc lud kłaniał się bogom ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'I przyłączył się Izrael do służby Baal Fegora; skąd się rozgniewał Pan bardzo na Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Rzekł tedy Pan do Mojżesza: Zbierz wszystkie książęta z ludu, a każ im, te przestępce powieszać Panu przed słońcem, aby się odwrócił gniew popędliwości Pańskiej od Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Przetoż rzekł Mojżesz do sędziów Izraelskich: Zabijcie każdy z was męże swe, którzy się spospolitowali z Baal Fegorem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'A oto, niektóry z synów Izraelskich przyszedł i przywiódł do braci swej Madyjanitkę przed oczyma Mojżeszowemi, i przed oczyma wszystkiego zgromadzenia synów Izraelskich; a oni płakali przed drzwiami namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Co gdy ujrzał Finees, syn Eleazara, syna Aarona kapłana, wstawszy z pośrodku zgromadzenia, wziął oszczep w ręce swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'A wszedłszy za onym mężem Izraelskim do namiotu, przebił oboje, męża Izraelskiego, i niewiastę przez żywot jej, i odwrócona była plaga od synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'A było tych, co pomarli oną plagą, dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Finees syn Eleazara, syna Aarona kapłana odwrócił gniew mój od synów Izraelskich, będąc wzruszony zapalczywą miłością ku mnie w pośrodku ich, tak iżem nie wytracił synów Izraelskich w zapalczywości mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Przetoż powiedz mu: Oto, Ja stanowię z nim przymierze moje, przymierze pokoju;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'I przyjdzie nań, i na nasienie jego po nim, przymierze kapłaństwa wiecznego, że się wzruszył zapalczywością za Boga swego, i oczyścił syny Izraelskie');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'A imię onego męża Izraelskiego zabitego, który zabity był z Madyjanitką, było Zamry, syn Salów, książę domu ojca swego, z pokolenia Symeonowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Imię też niewiasty zabitej Madyjanitki było Kozba, córka Sury, książęcia w narodzie swym, w domu ojczystym między Madyjanity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Staw się nieprzyjacielem Madyjanitom, a pobijcie je,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Ponieważ i oni stawili się wam nieprzyjaciołmi zdradami swemi, a podeszli was przez Baal Fegora, i przez Kozbę, córkę książęcia Madyjańskiego, siostrę swą, która zabita jest w dzień kaźni dla bałwana Fegor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'I stało się po onej pladze, że mówił Pan do Mojżesza i do Eleazara, syna Aarona kapłana, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Policzcie poczet wszystkiego zgromadzenia synów Izraelskich, od tych, którzy mają dwadzieścia lat i wyżej, według domów ojców ich, każdego któryby mógł wynijść na wojnę z Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Tedy rzekł Mojżesz, i Eleazar kapłan do nich na polach Moabskich, nad Jordanem przeciw Jerychu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Liczcie lud, od tych, którzy mają dwadzieścia lat i wyżej, jako był rozkazał Pan Mojżeszowi, i synom Izraelskim, gdy wyszli z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben pierworodny Izraela: synowie Rubenowi Henoch, od którego poszedł dom Henochytów; Fallu, od którego dom Faalluitów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'I Hesron, od którego dom Hesronitów; Charmi, od którego dom Charmitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Teć są domy Rubenitów; a było ich policzonych czterdzieści i trzy tysiące, siedem set i trzydzieści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'A syn Fallów Elijab.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Synowie zasię Elijabowi byli: Namuel, i Datan, i Abiron. A ci, Datan i Abiron, zacniejsi byli między zgromadzeniem, którzy się swarzyli z Mojżeszem i z Aaronem w spiknieniu Korego, gdy się zbuntowali przeciwko Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'I otworzyła ziemia usta swoje, a pożarła onych, i Korego, gdy zginęła ona rota, a pożarł ich ogień dwie cię i pięćdziesiąt mężów, którzy się stali na przykład innym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Ale synowie Korego nie pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Synowie Symeonowi wedle domów swych, ci są: Namuel, od którego poszedł dom Namuelitów; Jamin, od którego dom Jaminitów; Jachin, od którego dom Jachinitów; Zare, od którego dom Zareitów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Saul, od którego dom Saulitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Teć były domy Symeonitów, których było dwadzieścia i dwa tysiące i dwieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Synowie Gadowi według domów swych: Sefon, od którego poszedł dom Sefonitów; Aggi, od którego dom Aggitów; Suni, od którego dom Sunitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Ozni, od którego dom Oznitów; Hery, od którego dom Herytów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Arod, od którego dom Arodytów; Aryjel, od którego dom Aryjelitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Teć są domy synów Gadowych, według pocztów ich czterdzieści tysięcy i pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Synowie Judowi: Her, i Onan; ale pomarli Her i Onan w ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'I byli synowie Judowi wedle domów swych: Sela, od którego poszedł dom Selaitów; Fares, od którego dom Faresytów; Zare, od którego dom Zarejczyków;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Byli też synowie Faresowi: Hesron, od którego dom Hesronitów; Hamuel, od którego dom Hamuelitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Teć są domy Judy, według pocztów ich siedemdziesiąt tysięcy, i sześć, i pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Synowie Isascharowi według domów swych: Tola, od którego dom Tolaitów; Fua, od którego dom Fuaitów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Jasub, od którego dom Jasubitów; Semram, od którego dom Semramitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Teć są domy Isascharowe, wedle pocztów ich sześćdziesiąt tysięcy i cztery, i trzy sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Synowie Zabulonowi według domów swych: Zared, od którego dom Zaredczyków; Elon, od którego dom Elonitów; Jaleel, od którego dom Jaleelitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'A teć są domy Zabulonitów, według pocztów ich sześćdziesiąt tysięcy i pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Synowie Józefowi według domów swych: Manases i Efraim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Synowie Manasesowi: Machir, od którego dom Machirytów; a Machir spłodził Galaada, od Galaada dom Galaadytów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Ci są synowie Galaadowi: Jezer, od którego dom Jezerytów; Chelek, od którego dom Chelekitów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'I Asryjel, od którego dom Asryjelitów; i Sechem, od którego dom Sechemitów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'I Semida, od którego dom Semidaitów; i Chefer, od którego dom Cheferytów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'A Salfaad, syn Cheferów, nie miał synów, tylko córki, a imiona córek Salfaadowych: Machla, i Noa, Hegla, Melcha, i Tersa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Teć są domy Manasesowe, a poczet ich pięćdziesiąt i dwa tysiące i siedem set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Synowie zaś Efraimowi według domów swych: Sutala, od którego dom Sutalitów; Becher, od którego dom Becherytów; Techen, od którego dom Techenitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'A ci są synowie Sutalego: Heran, od którego dom Heranitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Teć są domy synów Efraimowych, według pocztów ich trzydzieści tysięcy i dwa, i pięć set. Ci są synowie Józefowi według domów swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'A synowie Benjaminowi według domów swych, ci są: Bela, od którego dom Belitów; Asbel, od którego dom Asbelitów; Achiram, od którego dom Achiramitów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Sufam, od którego dom Sufamitów; Hufam, od którego dom Hufamitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Byli też synowie Beli: Hereda i Noemana; z Hereda dom Heredytów, a z Noemana dom Noemanitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Cić są synowie Benjaminowi, według domów ich, a poczet ich czterdzieści i pięć tysięcy i sześć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Synowie zaś Danowi według domów swych: Sucham, od którego dom Suchamitów. Teć były domy Danowe według familii ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Wszystkie domy Suchamitów według pocztów ich sześćdziesiąt i cztery tysiące i cztery sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Synowie Aserowi według domów swych byli: Jemna, od którego dom Jemnitów; Iswi, od którego dom Iswitów; Beryja, od którego dom Berytów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Synowie Beryjego: Heber, od którego dom Heberytów; Melchyjel, od którego dom Melchyjelitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'A imię córki Aserowej było Sara.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Te są domy synów Aserowych, według pocztów ich pięćdziesiąt i trzy tysiące i cztery sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Synowie Neftalimowi według domów swych: Jachsel, od którego dom Jachselitów; Guni, od którego dom Gunitów; Jesser, od którego dom Jesserytów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Selem, od którego dom Selemitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Teć są domy Neftalimowe, według familii ich, a poczet ich czterdzieści i pięć tysięcy i cztery sta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Tać jest liczba synów Izraelskich, sześć kroć sto tysięcy i tysiąc, siedem set i trzydzieści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Między te podzielicie tę ziemię w dziedzictwo według liczby imion.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Większej liczbie więcej dziedzictwa dasz, a mniejszej mniejsze dziedzictwo dasz; każdemu według pocztów policzonych jego będzie dane dziedzictwo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Wszakże losem niech będzie rozdzielona ziemia; według imion pokoleń ojców swych dziedzictwo brać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Losem rozdzielone będzie dziedzictwo jej bądź ich wiele bądź mało będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Ci zasię są policzeni z Lewitów według domów swych: Gerson, od którego dom Gersonitów; Kaat, od którego dom Kaatytów; Merary, od którego dom Merarytów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Teć są domy Lewi: dom Libnitów, dom Hebronitów, dom Moholitów, dom Musytów, dom Korytów; a Kaat spłodził Amrama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'A imię żony Amramowej było Jochabod, córka Lewiego, która mu się urodziła w Egipcie; ta Amramowi urodziła Aarona, i Mojżesza, i Maryją, siostrę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Aaronowi też urodzili się Nadabi i Abiju, Eleazar i Itamar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Ale pomarli Nadab i Abiju, gdy ofiarowali ogień obcy przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'A była liczba ich dwadzieścia i trzy tysiące, wszystkich mężczyzn urodzonych od miesiąca i wyżej; jednak nie byli policzeni między syny Izraelskie, bo im nie dano dziedzictwa między syny Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Ci policzeni byli od Mojżesza i Eleazara kapłana, którzy policzyli syny Izraelskie na polach Moabskich, nad Jordanem przeciw Jerychu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'A między tymi nie był żaden z onych policzonych od Mojżesza i Aarona kapłana, gdy liczyli syny Izraelskie na puszczy Synaj;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Bo rzekł był Pan o nich: Śmiercią pomrą na puszczy; a nie został żaden z nich, oprócz Kaleba, syna Jefunowego, i Jozuego, syna Nunowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Tedy przyszły córki Salfaada, syna Heferowego, syna Galaadowego, syna Machyrowego, syna Manasesowego, z pokolenia Manasesa syna Józefowego; a te są imiona córek jego: Machla, Noa i Hegla, i Melcha i Tersa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'I stanęły przed Mojżeszem i przed Eleazarem kapłanem i przed książęty i wszystkiem zgromadzeniem u drzwi namiotu zgromadzenia, i rzekły:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Ojciec nasz umarł na puszczy, a on nie był w poczcie tych, którzy się byli przeciw Panu zbuntowali w spiknieniu Korego; ale dla grzechu swego umarł, nie mając synów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Czemuż by zginąć miało imię ojca naszego z domu jego, przeto, że nie miał syna? dajcie nam dziedzictwo między bracią ojca naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Tedy odniósł Mojżesz sprawę ich do Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'I rzekł Pan do Mojżesza:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Dobrze mówią córki Salfaadowe: Daj im koniecznie osiadłość dziedzictwa między bracią ojca ich, a przenieś dziedzictwo ojca ich na nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Synom także Izraelskim powiedz, mówiąc: Gdyby kto umarł, nie mając syna, tedy przeniesiecie dziedzictwo jego na córkę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'A jeśliby nie miał i córki, tedy dacie dziedzictwo jego braci jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'A jeśliby i braci nie miał, tedy dacie dziedzictwo jego braci ojca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'A jeśliby nie było braci ojca jego, tedy dacie dziedzictwo jego pokrewnemu jego, najbliższemu jego z domu jego, aby je odziedziczył. A będzie to synom Izraelskim za ustawę prawną, jako rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Potem rzekł Pan do Mojżesza: Wstąp na tę górę Abarym, a oglądaj ziemię, którąm dał synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'A gdy ją oglądasz, przyłączon będziesz do ludu twego i ty, jako jest przyłączony Aaron, brat twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Przeto żeście byli odpornymi słowu mojemu na puszczy Syn, przy poswarku zgromadzenia, i nie poświęciliście mię przy wodach przed oczyma ich. Oneć to są wody poswarku w Kades, na puszczy Syn.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Tedy rzekł Mojżesz do Pana, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Niech opatrzy Pan, Bóg duchów wszelkiego ciała, mężem godnym to zgromadzenie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'Któryby wychodził przed nimi, i któryby wchodził przed nimi, i któryby je przywodził, aby nie był lud Pański jako owce, nie mające pasterza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Tedy rzekł Pan do Mojżesza: Weźmij do siebie Jozuego, syna Nunowego, męża, w którym jest Duch mój, a włóż nań rękę swoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'I postaw go przed Eleazarem kapłanem, i przed wszystkiem zgromadzeniem, a dasz mu naukę przed oczyma ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'A udzielisz mu zacności swej, aby go słuchało wszystko zgromadzenie synów Izraelskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Który przed twarzą Eleazara kapłana stawać będzie, aby się zań radził sądu Urim przed Panem. Na rozkazanie jego wychodzić będą, on, i wszyscy synowie Izraelscy z nim, i wszystko zgromadzenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Uczynił tedy Mojżesz, jako mu był rozkazał Pan; a wziąwszy Jozuego postawił go przed Eleazarem kapłanem, i przed wszystkiem zgromadzeniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'I włożywszy nań ręce swe, dał mu naukę, jako mówił Pan przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'I rzekł Pan do Mojżesza mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Rozkaż synom Izraelskim, a powiedz im: Ofiary mojej chleba mego, w ofiarach moich ognistych, na wdzięczność wonności mojej, przestrzegać będziecie, abyście mi je ofiarowali czasu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'I rzeczesz do nich: Tać jest ofiara ognista, którą ofiarować będziecie Panu: Baranki roczne zupełne dwa na każdy dzień, na całopalenie ustawiczne;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Baranka jednego ofiarować będziesz poranku, a baranka drugiego ofiarować będziesz między dwoma wieczorami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Do tego dziesiątą część efy mąki pszennej na ofiarę śniedną, nagniatanej z oliwą czystą z czwartą częścią hynu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Toć jest całopalenie ustawiczne, jakie było sprawowane na górze Synaj na wdzięczną wonność; ognista to ofiara Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'A ofiara jej mokra będzie czwarta część hynu do każdego baranka; w świątnicy sprawować będziesz ofiarę mokrą z mocnego napoju Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'A drugiego baranka ofiarować będziesz między dwoma wieczorami; jako ofiarę śniedną poranną, i jako ofiarę mokrą jej ofiarować będziesz na ofiarę ognistą ku wdzięcznej wonności Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Ale w dzień sabatu ofiarować będziesz dwa baranki roczne zupełne, i dwie dziesiąte części efy mąki pszennej z oliwą nagniecionej na ofiarę śniedną i z mokrą jej ofiarą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Toć jest całopalenie sobotnie w każdy sabat, oprócz całopalenia ustawicznego i mokrej ofiary jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'A na nowiu miesiąców waszych ofiarować będziecie całopalenie Panu, cielców młodych dwa, i barana jednego, baranków rocznych siedem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'I trzy dziesiąte efy mąki pszennej nagniecionej z oliwą na ofiarę śniedną do każdego cielca, i dwie dziesiąte części pszennej mąki zagniecionej z oliwą na ofiarę śniedną do każdego barana;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'A jedną dziesiątą część mąki pszennej zagniecionej z oliwą na ofiarę śniedną do każdego baranka, na całopalenie ku wdzięczności wonności na ofiarę ognistą Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Także mokre ich ofiary z wina pół hynu będzie dla każdego cielca, a trzecia część hynu do barana, czwarta zaś część hynu do każdego baranka; toć jest całopalenie na nowiu miesiąca, każdego miesiąca przez rok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Kozła też jednego z stada za grzech ofiarować będziecie Panu oprócz ustawicznego całopalenia, i mokrej ofiary jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Ale miesiąca pierwszego w dzień czternasty tegoż miesiąca, święto przejścia będzie Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'A w piętnasty dzień tegoż miesiąca uroczyste święto będzie; przez siedem dni chleby przaśne jeść będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Pierwszego dnia zgromadzenie święte; żadnej roboty służebniczej nie będziecie czynić weń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Ale ofiarować będziecie ofiarę ognistą na całopalenie Panu: dwóch cielców młodych, i barana jednego, i siedem baranków rocznych; zupełni niech wam będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'A na ofiarę ich śniedną pszennej mąki nagniecionej z oliwą trzy dziesiąte części efy do każdego cielca, a dwie dziesiąte części do każdego barana ofiarować będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Jedną dziesiątą część ofiarować będziesz przy każdym baranku z onych siedmiu baranków;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Kozła też jednego na ofiarę za grzech ku oczyszczeniu was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Nad całopalenie poranne, które ma być całopalenie ustawiczne, ofiarować to będziecie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Tak ofiarować będziecie każdego dnia przez onych siedem dni pokarm ofiary ognistej na wdzięczną wonność Panu, oprócz całopalenia ustawicznego, i mokrej ofiary jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'A dnia siódmego święte zgromadzenie mieć będziecie; żadnej roboty służebniczej nie będziecie czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'W dzień zaś pierwocin; gdy będziecie ofiarowali nową śniedną ofiarę Panu, gdy się wypełnią tygodnie wasze, zgromadzenie święte mieć będziecie; żadnej roboty służebniczej czynić nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'I ofiarować będziecie całopalenie ku wdzięczności wonności Panu: dwóch cielców młodych, barana jednego, siedem baranków rocznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'A na ofiarę śniedną ich mąki pszennej nagniecionej z oliwą trzy dziesiąte części efy do każdego cielca, dwie dziesiąte części do każdego barana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Jedną dziesiątą część do każdego baranka z onych siedmiu baranków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Kozła jednego z kóz na oczyszczenie was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Oprócz całopalenia ustawicznego i ofiary śniednej jego ofiarować to będziecie; te rzeczy zupełne niech wam będą, i z mokremi ofiarami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Miesiąca zaś siódmego w pierwszy dzień jego, zgromadzenie święte mieć będziecie; żadnej roboty służebniczej nie będziecie czynić; dzień jest wesołego trąbienia waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'A będziecie ofiarowali całopalenie ku wdzięcznej wonności Panu, cielca młodego jednego, barana jednego, baranków rocznych siedem zupełnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'A na ofiarę śniedną ich z mąki pszennej nagniecionej z oliwą trzy dziesiąte części efy do cielca, a dwie dziesiąte części do barana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'A dziesiątę część jednę do każdego baranka z onych siedmiu baranków;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Także kozła jednego z kóz ku ofierze za grzech na oczyszczenie was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Oprócz całopalenia nowego miesiąca, i ofiary śniednej jego, i oprócz całopalenia ustawicznego, i ofiary śniednej jego, i ofiar ich mokrych według obrzędów ich ku wdzięcznej wonności; ofiara to ognista Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Potem dziesiątego dnia tegoż miesiąca siódmego, zgromadzenie święte mieć będziecie, a będziecie trapić dusze wasze; żadnej roboty nie będziecie robić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'A będziecie ofiarowali całopalenie Panu ku wdzięcznej wonności: cielca młodego jednego, barana jednego, baranków rocznych siedem; zupełni niech wam będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'A na ofiarę śniedną ich z pszennej mąki nagniecionej z oliwą: trzy dziesiąte części do każdego cielca, dwie zaś dziesiąte części do każdego barana;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'A dziesiątą część jednę do każdego baranka z onych siedmiu baranków;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Kozła z kóz jednego na ofiarę za grzech, oprócz ofiary za grzech na oczyszczenie, i oprócz całopalenia ustawicznego, i ofiary śniednej jego, i mokrych ofiar ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'W piętnasty zaś dzień tegoż siódmego miesiąca zgromadzenie święte mieć będziecie; żadnej roboty służebniczej nie będziecie czynić weń; ale obchodzić będziecie święto uroczyste Panu przez siedem dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'I ofiarować będziecie całopalenie na ofiarę ognistą ku wdzięcznej wonności Panu, cielców młodych trzynaście, baranów dwa, baranków rocznych czternaście; i zupełni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'A na ofiarę ich śniedną z pszennej mąki zagniecionej z oliwą trzy dziesiąte części efy do każdego cielca z onych trzynaście cielców, dwie dziesiąte części do każdego barana z onych dwóch baranów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'A jedna dziesiąta część do każdego baranka z onych czternaście baranków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'Także kozła jednego z kóz na ofiarę za grzech, oprócz całopalenia ustawicznego, ofiary śniednej jego, i ofiary mokrej jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Wtórego zaś dnia ofiarować będziecie cielców młodych dwanaście, baranów dwa, baranków rocznych czternaście zupełnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'I ofiarę śniedną ich, i ofiary ich mokre do każdego cielca, do każdego barana, i do każdego baranka według liczby ich, i według zwyczaju ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'Nadto kozła jednego z kóz na ofiarę za grzech, oprócz całopalenia ustawicznego, i ofiary śniednej jego, i ofiar ich mokrych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Dnia zaś trzeciego ofiarować będziecie jedenaście cielców, baranów dwa, baranków rocznych czternaście zupełnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'I ofiarę śniedną ich, i ofiary mokre ich do każdego cielca, do każdego barana, i do każdego baranka według liczby ich, i według zwyczaju ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'Do tego, kozła jednego na ofiarę za grzech, okrom całopalenia ustawicznego, i ofiary śniednej jego, i mokrej ofiary jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'A dnia czwartego ofiarować będziecie cielców dziesięć, baranów dwa, baranków rocznych czternaście zupełnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Ofiarę śniedną ich, i ofiary mokre ich do każdego cielca, do każdego barana, i do każdego baranka według liczby ich, i według zwyczaju ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'Kozła też jednego z kóz na ofiarę za grzech, oprócz całopalenia ustawicznego, ofiary śniednej jego, i mokrej ofiary jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'A dnia piątego ofiarować będziecie cielców dziewięć, baranów dwa, baranków rocznych czternaście zupełnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'I ofiarę śniedną ich, i ofiary mokre ich do każdego cielca, do każdego barana, i do każdego baranka według liczby ich, i według zwyczaju ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'Także kozła jednego na ofiarę za grzech, oprócz całopalenia ustawicznego, i ofiary śniednej jego, i ofiary mokrej jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'A dnia szóstego ofiarować będziecie cielców osiem, baranów dwa, baranków rocznych czternaście zupełnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'I ofiarę śniedną ich, i ofiary mokre ich do każdego cielca, i do każdego barana, i do każdego baranka według liczby ich, według zwyczaju ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'Nadto kozła za ofiarę za grzech jednego, okrom całopalenia ustawicznego, ofiary śniednej jego, i ofiar mokrych jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Także dnia siódmego ofiarować będziecie cielców siedem, baranów dwa, baranków rocznych czternaście zupełnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'I ofiarę śniedną ich, i ofiary mokre ich do każdego cielca, do każdego barana, do każdego baranka według liczby ich, i według zwyczaju ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'Przytem kozła na ofiarę za grzech jednego, oprócz całopalenia ustawicznego i ofiary śniednej jego, i ofiary mokrej jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'A dnia ósmego zacne święto mieć będziecie; żadnej roboty służebniczej nie będziecie czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'A ofiarować będziecie całopalenie, i ofiarę ognistą ku wdzięcznej wonności Panu, cielca jednego, barana jednego, baranków rocznych siedem zupełnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Ofiarę śniedną ich, i ofiary mokre ich do cielca, do barana, do każdego baranka według liczby ich, i według zwyczaju ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'Nadto kozła na ofiarę za grzech jednego, okrom całopalenia ustawicznego, ofiary śniednej jego, i ofiary mokrej jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'To ofiarować będziecie Panu w święta uroczyste wasze, oprócz ślubów waszych i dobrowolnych ofiar waszych w całopaleniach waszych, i w śniednych ofiarach waszych, i w mokrych ofiarach waszych, i w spokojnych ofiarach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'I powiedział Mojżesz synom Izraelskim to wszystko, co rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Potem mówił Mojżesz do książąt w pokoleniach między synami Izraelskimi, i rzekł: Toć jest, co rozkazał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Jeźliby mąż poślubił ślub Panu, albo też przysięgę uczynił, obowiązkiem obowiązawszy duszę swoję, nie złamie słowa swego: według wszystkiego coby wyszło z ust jego, uczyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Ale jeźliby niewiasta poślubiła ślub Panu, i obowiązałaby się obowiązkiem w domu ojca swego w młodości swojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'A słyszałby ojciec jej on ślub jej, i obowiązek jej, którym obowiązała duszę swoję, a milczałby na to ojciec jej, tedy płatne będą wszystkie śluby jej, i każdy obowiązek, którym by obowiązała duszę swą, płatny będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Ale jeźliby był onegoż dnia przeciw temu ojciec jej, którego by słyszał wszystkie śluby jej, i obowiązki jej, któremi obowiązała duszę swoję nie będą płatne; Pan odpuści jej, bo był przeciw temu ojciec jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Ale gdyby mająca męża ślub jaki uczyniła, albo wyrzekła co usty swemi, czem by obowiązała duszę swoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'A słysząc to mąż jej, milczałby na to onegoż dnia, którego słyszał, płatne będą śluby jej, i obowiązki jej, któremi obowiązała duszę swoję, płatne będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Ale jeźliby onego dnia, którego słyszał mąż jej, sprzeciwił się temu, i wzruszyłby ślub jej, który na sobie miała, i co wymówiła usty swemi, czem obowiązała duszę swoję, także Pan odpuści jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Ale ślub każdy wdowy, i odrzuconej którym by obowiązała duszę swoję, płatny będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Lecz jeźliby, póki była w domu męża swego, ślub uczyniła, i obowiązała obowiązkiem duszę swoję z przysięgą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'A słysząc mąż jej milczałby na to, i nie sprzeciwiłby się temu, tedy płatne będą wszystkie śluby jej i każdy obowiązek, którym obowiązała duszę swoję, płatny będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Ale jeźli cale sprzeciwił się temu mąż jej dnia, którego to słyszał, wszelki ślub, który wyszedł z ust jej, i obowiązek duszy jej, nie będzie płatny; mąż jej wzruszył to, a Pan odpuści jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Wszelkiego ślubu i wszelkiej przysięgi obowiązku na utrapienie duszy, mąż jej potwierdzi go, i mąż jej wzruszy go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'A jeźliby cale milczał mąż jej ode dnia do dnia, tedy tem stwierdzi wszystkie śluby jej, i wszystkie obowiązki jej, które ma na sobie; stwierdzi je, przeto, że milczał na to w dzień, którego słyszał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'A jeźliby to koniecznie wzruszyć chciał, nie zaraz gdy słyszał, ale potem, poniesie nieprawość jej. Teć są ustawy, które przykazał Pan Mojżeszowi, między mężem a żoną jego, między ojcem a córką jego w młodości jej, póki jest w domu ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Pomścij się krzywdy synów Izraelskich nad Madyjanitami, i potem przyłączon będziesz do ludu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Tedy rzekł Mojżesz do ludu, mówiąc: Wyprawcie z pośrodku siebie męże ku bitwie, aby szli przeciw Madyjanitom, i wykonali pomstę Pańską nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Po tysiącu z każdego pokolenia, ze wszystkich pokoleń Izraelskich wyślecie na wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'I wyprawili z tysiąców Izraelskich, po tysiącu z każdego pokolenia, dwanaście tysięcy ludzi gotowych do bitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'I wysłał je Mojżesz po tysiącu z każdego pokolenia na wojnę; posłał też z nimi Fineesa, syna Eleazara kapłana, na wojnę, a naczynia święte, i trąby do trąbienia były w ręku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Tedy zwiedli bitwę z Madyjanitami, jako rozkazał Pan Mojżeszowi, i pobili wszystkie mężczyzny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Króle też Madyjańskie pobili między inszymi pobitymi ich, Ewiego, i Rechema, i Sura, i Hura, i Rebaha, pięciu królów Madyjańskich, i Balaama, syna Beorowego, zabili mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'I pobrali w niewolą synowie Izraelscy żony Madyjańczyków, i dziatki ich, i wszystko bydło ich, i wszystkie trzody ich, i wszystkie majętności ich pobrali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'A wszystkie miasta ich, w których mieszkali, i wszystkie zamki ich popalili ogniem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'I pobrali wszystkie łupy, i wszystkie plony z ludzi, i z bydła,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'I przywiedli do Mojżesza i do Eleazara kapłana, i do zgromadzenia synów Izraelskich więźnie, i łupy, i korzyści do obozu na pola Moabskie, które są nad Jordanem przeciw Jerychu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'I wyszli Mojżesz i Eleazar kapłan, i wszystkie książęta zgromadzenia przeciwko nim przed obóz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'I rozgniewał się bardzo Mojżesz na hetmany wojska onego, na pułkowniki, i na rotmistrze, którzy się byli wrócili z onej bitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'I mówił do nich Mojżesz: Przeczżeście żywo zachowali wszystkie niewiasty?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Gdyż te są, które synom Izraelskim za radą Balaamową dały przyczynę do przestępstwa przeciw Panu przy bałwanie Fegor, skąd była przyszła plaga na zgromadzenie Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Przetoż teraz pozabijajcie wszystkie mężczyzny z dzieci, i każdą niewiastę, która poznała męża, obcując z nim, zabijcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Ale wszystkie dzieweczki z białych głów, które nie poznały łoża męskiego, żywo zachowajcie sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'A wy sami zostańcie w namiecich za obozem przez siedem dni; każdy, który kogo zabił, i który się dotykał zabitego, oczyścicie się dnia trzeciego a dnia siódmego, siebie i więźnie wasze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'I wszelką szatę, i wszelkie naczynie skórzane, i wszystko, co urobiono z koziej sierści, i wszelkie naczynie drzewiane oczyścicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'I rzekł Eleazar kapłan do żołnierstwa, które chodziło na wojnę: Tać jest ustawa zakonna, którą był rozkazał Pan Mojżeszowi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Złoto jednak i srebro, miedź, żelazo, cynę i ołów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'I każdą rzecz, która znieść może ogień, wyprawicie przez ogień, a będzie oczyszczona, wszakże pierwej wodą oczyszczenia będzie oczyszczona; ale wszystko, co nie może znieść ognia, wodą oczyścicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Upierzecie też szaty wasze dnia siódmego, i czystymi będziecie, a potem wnijdziecie do obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Zbierz summę korzyści pobranych z ludzi i z bydła, ty i Eleazar kapłan, i przedniejsi z ojców w ludu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'I rozdzielisz te łupy na dwie części, między żołnierze, którzy na wojnę wychodzili, i między wszystko zgromadzenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Odbierzesz też dział na Pana od mężów rycerskich, którzy byli wyszli na wojnę, po jednemu od pięciu set, z ludzi, i z wołów, i z osłów, i z owiec;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'A z połowy ich weźmiecie, i oddacie Eleazarowi kapłanowi na ofiarę podnoszenia Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'A z połowy synów Izraelskich weźmiesz jedną część z pięciudziesiąt, z ludzi, z wołów, z osłów, i z owiec, i z wszelkiego bydła, i oddasz to Lewitom trzymającym straż w przybytku Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'I uczynił Mojżesz i Eleazar kapłan, jako rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'A było onej korzyści z pozostałych łupów, które rozchwycił lud wojenny: Owiec sześć kroć sto tysięcy, i siedemdziesiąt tysięcy i pięć tysięcy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'Wołów zaś, siedemdziesiąt i dwa tysiące;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'A osłów sześćdziesiąt tysięcy i jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'A ludzi z białych głów, które nie poznały obcowania z mężem, wszystkich było trzydzieści i dwa tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'I dostała się połowa działu tym, co wychodzili na wojnę, liczba owiec trzy kroć sto tysięcy, i trzydzieści tysięcy, i siedem tysięcy i pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Dostało się też działu na Pana owiec sześć set, siedemdziesiąt i pięć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'A z wołów trzydzieści i sześć tysięcy, a działu z nich Panu siedemdziesiąt i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Osłów też trzydzieści tysięcy i pięć set, a działu z nich Panu sześćdziesiąt i jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Przytem ludu szesnaście tysięcy, a działu z nich Panu trzydzieści i dwoje ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'I oddał Mojżesz dział na ofiarę Panu, Eleazarowi kapłanowi, jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'A z drugiej połowy synów Izraelskich, którą wziął Mojżesz od mężów, którzy byli wyszli na wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(A połowa należąca zgromadzeniu, była: Owiec trzy kroć sto tysięcy, i trzydzieści tysięcy, siedem tysięcy i pięć set;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'A wołów trzydzieści i sześć tysięcy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'A osłów trzydzieści tysięcy i pięć set;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'A ludu szesnaście tysięcy.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Wziął Mojżesz z tej połowy należącej synom Izraelskim, jednę część z pięciudziesiąt, z ludzi, i z bydła, i dał to Lewitom trzymającym straż przybytku Pańskiego, jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Tedy przyszli do Mojżesza hetmani wojska, pułkownicy, i rotmistrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'I mówili do niego: My słudzy twoi przynieśliśmyć poczet mężów wojennych, którzy byli pod sprawą naszą, a nie zginął z nas i jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'A tak przynieśliśmy tu na ofiarę Panu, każdy czego nabył, naczynie złote, zapony, i manele, pierścienie, i nausznice, i łańcuszki, dla oczyszczenia dusz naszych przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Odebrał tedy Mojżesz i Eleazar kapłan ono złoto od nich z wszelakiem naczyniem z niego urobionym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'A było onego wszystkiego złota ofiarowanego, które ofiarowali Panu, szesnaście tysięcy, siedem set i pięćdziesiąt syklów od pułkowników i od rotmistrzów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, '(Bo żołnierze, co łupem dostali, sobie otrzymali.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'A wziąwszy Mojżesz i Eleazar kapłan ono złoto od pułkowników i rotmistrzów, wnieśli je do namiotu zgromadzenia, na pamiątkę synów Izraelskich przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'I mieli synowie Rubenowi, i synowie Gadowi bydła bardzo wiele; a obaczywszy ziemię Jazer i ziemię Galaad, że miejsce ono było sposobne dla bydła,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Przyszli ciż synowie Gadowi, i synowie Rubenowi, i mówili do Mojżesza i do Eleazara kapłana, i do książąt zgromadzenia, i rzekli:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Ziemia Ataret i Dybon, i Jazer, i Nemra, i Hesebon, i Eleale, i Seban, i Nebo, i Beon:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'Ziemia, którą zwojował Pan przed zgromadzeniem Izraelskiem, jest ziemia sposobna dla bydła, a my słudzy twoi mamy bydła wiele. Przetoż rzekli:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Jeźliśmy znaleźli łaskę przed oczyma twemi, niechże będzie dana ta ziemia sługom twym na osiadłość, a niech nie chodzimy za Jordan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Tedy odpowiedział Mojżesz synom Gadowym, i synom Rubenowym: Więc bracia wasi pójdą na wojnę, a wy tu siedzieć będziecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Czemuż psujecie serce synom Izraelskim, żeby nie szli do ziemi, którą im dał Pan?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Takci uczynili ojcowie wasi, gdym je był posłał z Kades Barne ku przeszpiegowaniu tej ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Bo gdy przyszli aż do doliny Eschol, obejrzawszy onę ziemię popsowali serce synom Izraelskim, aby nie szli do ziemi, którą im dał Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Skąd zapaliwszy się gniewem Pan, dnia onego przysiągł, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Zaiste nie oglądają ludzie ci, którzy wyszli z Egiptu, od dwudziestu lat i wyżej, tej ziemi, o którąm przysiągł Abrahamowi, Izaakowi, i Jakóbowi, przeto iż mię cale nie naśladowali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Oprócz Kaleba, syna Jefunowego, Kenezejczyka, i Jozuego, syna Nunowego, ponieważ ci cale naśladowali Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'I zapalił się gniewem Pan na Izraela, i sprawił, że się tułali po puszczy przez czterdzieści lat, aż poginął wszystek on naród, który czynił źle przed oczyma Pańskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'A oto, wy powstaliście miasto ojców waszych, plemię ludzi grzesznych, abyście jeszcze przyczynili gniewu zapalczywości Pańskiej przeciwko Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Bo jeźli się odwrócicie od naśladowania jego, tedy on też zaniecha go jeszcze na tej puszczy; a tak wy zgubicie ten wszystek lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Tedy przystąpiwszy do niego rzekli: Obory bydłu i dobytkowi naszemu, i miasta dziatkom naszym tu pobudujemy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Ale sami zbrojno ochotnie pójdziemy przed syny Izraelskimi, aż je zaprowadzimy na miejsce ich, a dziatki nasze będą mieszkały w mieściech obronnych dla obywateli tej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Nie wrócimy się do domów naszych, aż posiądą synowie Izraelscy każdy dziedzictwo swoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Ani weźmiemy dziedzictwa z nimi za Jordanem i dalej, ponieważ przychodzi dziedzictwo nasze na nas z tej strony Jordanu na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'I rzekł im Mojżesz: Jeźliż uczynicie, coście rzekli, a pójdziecie zbrojno przed obliczem Pańskiem na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'I pójdzie każdy z was zbrojno za Jordan przed oblicznością Pańską, ażby wypędził nieprzyjacioły swoje od oblicza swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'I aż będzie poddana ziemia ona Panu, a potem się wrócicie, i będziecie bez winy przed Panem i przed Izraelem: tedy wam będzie ta ziemia za osiadłość przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Ale jeźli tego nie uczynicie, oto zgrzeszycie Panu, a wiedzcie, że grzech wasz znajdzie was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Budujcież tedy miasta dziatkom waszym, i obory bydłu waszemu, a co wyszło z ust waszych, uczyńcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Tedy rzekli synowie Gadowi, i synowie Rubenowi do Mojżesza, mówiąc: Słudzy twoi uczynią, jako pan nasz rozkazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Dziatki nasze, i żony nasze, stada nasze, i wszystkie bydła nasze, zostaną tu w mieściech Galaadzkich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Ale słudzy twoi pójdą wszyscy zbrojno przed Panem na wojnę, jako pan nasz mówi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'I przykazał o nich Mojżesz Eleazarowi kapłanowi, i Jozuemu, synowi Nunowemu, i książętom ojców pokoleń synów Izraelskich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'I rzekł im: Jeźli przejdą synowie Gadowi, i synowe Rubenowi z wami za Jordan, wszyscy zbrojno na wojnę przed Panem, a będzie pohołdowana ziemia przed wami, tedy im dacie ziemię Galaad w dziedzictwo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Ale jeźli nie zbrojno z wami przejdą, tedy niech mają dziedzictwo między wami w ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'I odpowiedzieli synowie Gadowi, i synowie Rubenowi, mówiąc: Co wyrzekł Pan do sług swoich, to uczynimy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Pójdziemy zbrojno przed Panem do ziemi Chananejskiej, a zostanie przy nas osiadłość dziedzictwa naszego z tej strony Jordanu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Dał tedy Mojżesz synom Gadowym, i synom Rubenowym, i połowie pokolenia Manasesa, syna Józefowego, królestwo Sehona, króla Amorejskiego, i królestwo Oga, króla Basańskiego, ziemię z miasty jej, z granicami, i miasta ziemi onej w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'I pobudowali synowie Gadowi Dybon, i Atarot, i Aroer;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'I Atrot, i Sofan, i Jazer, i Jegba,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'I Betnimera, i Betaran, miasta obronne, i obory dla bydła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Synowie też Rubenowi pobudowali Hesebon, i Eleale, i Karyjataim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'I Nebo, i Baalmeon, odmieniwszy im imiona, także Sabana; i dali imiona insze onym miastom, które pobudowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Wtargnęli też synowie Machyra, syna Manasesowego, do Galaad, a wziąwszy je, wygnali Amorejczyka, który tam mieszkał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'I dał Mojżesz Galaad Machyrowi, synowi Manasesowemu, i mieszkał w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Potem Jair, syn Manasesów, wtargnął, i pobrał wsi ich, które przezwał Chawot Jair.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Także Nobe wtargnął, i wziął Kanat z jego wsiami, i nazwał je Nobe od imienia swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Teć są ciągnienia synów Izraelskich, którzy wyszli z ziemi Egipskiej według hufów swych pod sprawą Mojżesza i Aarona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'I spisał Mojżesz wychodzenia ich, i stanowiska ich według rozkazania Pańskiego. A teć są ciągnienia ich, i stanowiska ich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Naprzód wyciągnąwszy z Ramesses, miesiąca pierwszego, piętnastego dnia tegoż pierwszego miesiąca, nazajutrz po święcie przejścia, wyszli synowie Izraelscy ręką wyniosłą przed oczyma wszystkich Egipczanów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Gdy Egipczanie grzebli one, które był Pan między nimi pomordował, to jest, wszystko pierworodztwo, i gdy nad bogami ich wykonał Pan sądy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Ruszywszy się tedy synowie Izraelscy z Ramesses, położyli się obozem w Suchot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Ruszywszy się z Suchot, położyli się obozem w Etam, które jest przy końcu puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'A ruszywszy się z Etam, nawrócili się do Fihahyrot, które jest przeciw Baalsefon, i położyli się obozem przed Migdolem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'A ruszywszy się z Fihahyrot, przeszli przez pośrodek morza na puszczą, i uszedłszy trzy dni drogi po puszczy Etam, położyli się obozem w Mara.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'A ruszywszy się z Mara, przyszli do Elim; a w Elim było dwanaście źródeł wód, i siedemdziesiąt drzew palmowych, i położyli się tam obozem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'A ruszywszy się z Elim, położyli się obozem nad morzem czerwonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'A ruszywszy się od morza czerwonego, położyli się obozem na puszczy Syn.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'A ruszywszy się z puszczy Syn, położyli się obozem w Dafka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'A ruszywszy się z Dafka, położyli się obozem w Alus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'A ruszywszy się z Alus, położyli się obozem w Rafidym, gdzie nie miał lud wód dla napoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'A ruszywszy się z Rafidym, położyli się obozem na puszczy Synaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'A ruszywszy się z puszczy Synaj, położyli się obozem w Kibrot hataawa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'A ruszywszy się z Kibrot hataawa, położyli się obozem w Hezerot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'A ruszywszy się z Hezerot, położyli się obozem w Retma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'A ruszywszy się z Retma, położyli się obozem w Remmon Fares.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'A ruszywszy się z Remmon Fares, położyli się obozem w Lebna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'A ruszywszy się z Lebna, położyli się obozem w Ressa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'A ruszywszy się z Ressa, położyli się obozem w Kieelata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'A ruszywszy się z Kieelata, położyli się obozem na górze Sefer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'A ruszywszy się z góry Sefer, położyli się obozem w Charada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'A ruszywszy się z Charada, położyli się obozem w Makelot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'A ruszywszy się z Makelot, położyli się obozem w Tahat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'A ruszywszy się z Tahatu, położyli się obozem w Tare.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'A ruszywszy się z Tare, położyli się obozem w Metka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'A ruszywszy się z Metka, położyli się obozem w Hesman.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'A ruszywszy się z Hesman, położyli się obozem w Moserot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'A ruszywszy się z Moserot, położyli się obozem w Benejaakan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'A ruszywszy się z Benejaakan, położyli się obozem w Horgidgad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'A ruszywszy się z Horgidgad, położyli się obozem u Jotbata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'A ruszywszy się z Jotbata, położyli się obozem w Habrona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'A ruszywszy się z Habrona, położyli się obozem w Asyjongaber.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'A ruszywszy się z Asyjongaber, położyli się obozem na puszczy Syn, która jest Kades.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'A ruszywszy się z Kades, położyli się obozem na górze Hor, na granicach ziemi Edomskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Tedy wstąpił Aaron kapłan na górę Hor według rozkazania Pańskiego, i tam umarł roku czterdziestego po wyjściu synów Izraelskich z ziemi Egipskiej, miesiąca piątego, pierwszego dnia onego miesiąca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'A miał Aaron sto dwadzieścia i trzy lat, gdy umarł na górze Hor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Tam usłyszał Chananejczyk, król Arad, który mieszkał na południe, w ziemi Chananejskiej, że ciągnęli synowie Izraelscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'A ruszywszy się z góry Hor, położyli się obozem w Salmona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'A ruszywszy się z Salmona, położyli się obozem w Funon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'A ruszywszy się z Funon, położyli się obozem w Obot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'A ruszywszy się z Obot, położyli się obozem przy pagórkach Abarym, na granicy Moabskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'A ruszywszy się z Abarym, położyli się obozem w Dybon Gat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'A ruszywszy się z Dybon Gat, położyli się obozem w Helmon Dyblataim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'A ruszywszy się z Helmon Dyblataim, położyli się obozem na górach Abarym, przeciwko Nebo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'A ruszywszy się z gór Abarym, położyli się obozem na polach Moabskich, nad Jordanem, przeciw Jerychu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'I tam się położyli nad Jordanem, od Betiesymot aż do Abelsytym, na polach Moabskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'I rzekł Pan do Mojżesza na polach Moabskich, nad Jordanem, przeciw Jerychu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Mów do synów Izraelskich, a powiedz im: Gdy przejdziecie za Jordan do ziemi Chananejskiej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'Tedy wypędźcie wszystkie obywatele onej ziemi od oblicza waszego, i wytraćcie wszystkie malowania ich, i wszystkie obrazy bałwanów ich wygubcie, także wszystkie wyżyny ich spustoszcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'A wypędziwszy obywatele ziemi, mieszkać będziecie w niej; bom wam dał tę ziemię w dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'I weźmiecie w dziedzictwo tę ziemię losem, według domów waszych; których więcej, tym większe dziedzictwo dacie, a których mniej, tym mniejsze dziedzictwo dacie, a które miejsce losem na kogo przypadnie, to mieć będzie; według pokolenia ojców waszych dziedzictwo brać będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Ale jeźliż nie wypędzicie obywateli tej ziemi od oblicza waszego, tedy oni, które pozostawicie z nich, będą wam jako żądła w oczach waszych, i jako ciernie na boki wasze, i będą was trapić w tej ziemi, w której wy mieszkać będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'I stanie się, że com umyślił onym uczynić, wam uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Potem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Rozkaż synom Izraelskim, a powiedz im: Gdy wnijdziecie do ziemi Chananejskiej, (tać jest ziemia, która się wam dostanie za dziedzictwo, ziemia Chananejska z granicami swemi.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Tedy będzie granica wasza ku południowi, od puszczy Syn aż do granic Edomskich, która granica południowa pójdzie od brzegu morza słonego na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'I okrąży ta granica od południa do Maaleakrabim, i pójdzie aż ku puszczy Syn, i pójdzie od południa do Kades Barne; a stamtąd wynijdzie do wsi Addar, i pójdzie aż do Asmon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'A zakrąży ta granica od Asmon aż do rzeki Egipskiej, a skończy się na zachód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Zachodnią zaś granicę będziecie mieli morze wielkie; to wam będzie granicą od zachodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'To zaś wasza będzie granica północna; od morza wielkiego wymierzycie sobie do góry Hor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Potem od góry Hor wymierzycie granice, aż gdzie wchodzą do Hemat; a będą się kończyć granice aż do Sedada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'I pójdzie ta granica aż do Zefronu, a skończy się u wsi Enan; tę będziecie mieć granice północną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Granicę też od wschodu wymierzycie od wsi Enan aż do Sefama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'A pójdzie ta granica od Sefama aż do Reblat, od wschodu miasta Ain; i uda się ta granica i dojdzie do brzegu morza Cyneret na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'A przyjdzie ta granica aż ku Jordanu, a skończy się u morza słonego. Tać będzie ziemia wasza w granicach swoich w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Tedy oznajmił Mojżesz synom Izraelskim, mówiąc: Tać jest ziemia, którą dziedzicznie otrzymacie losem, jako rozkazał Pan, abym ją dał dziewięciorgu pokoleniu, i połowie pokolenia Manasesowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Bo wzięło pokolenie synów Rubenowych według domów ojców swych, i pokolenie synów Gadowych według domów ojców swych, i połowa pokolenia Manasesowego wzięli dziedzictwo swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Dwa pokolenia, i pół pokolenia, wzięły dziedzictwo swoje z tej strony Jordanu przeciw Jerychu, ku stronie na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'I rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Teć są imiona mężów, którzy wam podzielą w dziedzictwo ziemię: Eleazar kapłan, i Jozue, syn Nunów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Księcia także jednego z każdego pokolenia weźmiecie dla podzielenia w dziedzictwo ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'A teć są imiona tych mężów: z pokolenia Juda Kaleb, syn Jefunów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'A z pokolenia synów Symeonowych Samuel, syn Ammiudów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Z pokolenia Benjamin Eliad, syn Chaselenów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'A z pokolenia synów Danowych książę Buki, syn Jogolów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Z synów Józefowych z pokolenia synów Manasesowych książę Haniel, syn Efodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'A z pokolenia synów Efraimowych książę Chemuel, syn Seftanów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Z pokolenia zaś Zabulonowego książę Elisafan, syn Farnatów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'A z pokolenia synów Isascharowych książę Faltijel, syn Ozanów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Z pokolenia synów Aserowych książę Ahiud, syn Salomiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'A z pokolenia synów Neftalimowych książę Fedael, syn Ammiudów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Cić są, którym rozkazał Pan, aby dali dziedzictwo synom Izraelskim w ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'I rzekł Pan do Mojżesza na polach Moabskich, nad Jordanem przeciw Jerychowi, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Rozkaż synom Izraelskim, aby dali Lewitom z dziedzictwa osiadłości swojej miasta do mieszkania, i przedmieścia około miast ich oddacie Lewitom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'I będą mieli miasta sobie do mieszkania, a przedmieścia ich będą im dla bydła ich, i dla majętności ich, i dla wszystkiego dobytku ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'A przedmieścia miast, które dacie Lewitom, od muru miejskiego pójdą na tysiąc łokci wszędy w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Przetoż wymierzycie za każdem miastem dwa tysiące łokci na wschód słońca, na południe też dwa tysiące łokci, także na zachód dwa tysiące łokci, i na północy dwa tysiące łokci, a miasto w pośrodku będzie; takoweć będą przedmieścia miast ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'A między temi miasty, które dacie Lewitom, sześć miast będą dla ucieczki, które dacie, aby tam uciekał mężobójca; a nad te dacie im czterdzieści miast i dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Tak iż wszystkich miast, które Lewitom dacie, będzie czterdzieści i osiem miast i z przedmieściami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'A miast, które dacie z dzierżaw synów Izraelskich, od tych, którzy więcej mają, więcej dacie, a od tych, którzy mniej mają, dacie mniej; każdy według miary dziedzictwa swego, które posiędzie, udzieli z miast swoich Lewitom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Zatem rzekł Pan do Mojżesza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Mów do synów Izraelskich, i rzecz im: Gdy przejdziecie przez Jordan do ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'Postanowcież sobie miasta; miasta dla ucieczki mieć będziecie, aby tam uciekał mężobójca, któryby zabił kogo z nieobaczenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'A będą wam te miasta dla ucieczki przed powinowatym zabitego, aby nie dał gardła ten co zabił, póki by nie stanął przed zgromadzeniem na sąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'A miast, które odłączycie, sześć miast dla ucieczki mieć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Trzy miasta dacie z tej strony Jordanu, a trzy miasta dacie w ziemi Chananejskiej; te miasta dla ucieczki będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Synom Izraelskim, i przychodniowi, i mieszkającemu między nimi, będą te sześć miast do ucieczki, aby tam uciekł każdy, kto by zabił człowieka z nieobaczenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Wszakże, jeźliby go żelazną bronią uderzył, tak żeby umarł, mężobójcą jest; śmiercią umrze on mężobójca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Albo jeźliby mając kamień w ręku, którym by mógł zabić, uderzył go, tak żeby umarł, mężobójcą jest; śmiercią umrze on mężobójca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Także jeźliby mając w ręku drewno, którem by mógł zabić, uderzył go, i umarłby, mężobójcą jest; śmiercią umrze on mężobójca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Powinowaty zabitego zabije tego mężobójcę; gdziekolwiek się z nim spotka, on zabije go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'A jeźliby kogo z nienawiści popchnął, albo nań czem cisnął z zasadzki, a umarłby;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Albo jeźliby go z waśni uderzył ręką swoją, a umarłby, śmiercią umrze ten, który uderzył, mężobójcą jest; powinny zabitego zabije mężobójcę, gdziekolwiek go trafi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Ale jeźliby z przygody bez waśni kogo popchnął, alboby nań cisnął czemkolwiek nie umyślnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Albo jeźliby jakim kamieniem, od którego by mógł umrzeć, rzucił nań z nieobaczenia, a umarłby, nie będąc mu nieprzyjacielem, ani szukając jego złego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'Tedy rozsądek uczyni zgromadzenie między tym, który zabił, a między powinnym zabitego według tego prawa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'I wybawi zgromadzenie mężobójcę tego z rąk powinnego onego zabitego, i każe mu się wrócić zgromadzenie do miasta ucieczki jego, gdzie był uciekł; i tamże będzie mieszkał aż do śmierci kapłana najwyższego, który jest pomazany olejkiem świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'A jeźliby wyszedł mężobójca za granice miasta ucieczki swojej, do którego uciekł;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'I trafiłby go powinny zabitego za granicą miasta ucieczki jego, chociażby zabił powinny zabitego mężobójcę onego, nie będzie winien krwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Albowiem w mieście ucieczki swojej mieszkać ma aż do śmierci kapłana najwyższego, a po śmierci kapłana najwyższego wróci się on mężobójca do ziemi osiadłości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'A będziecie to mieli za ustawę prawną w narodziech waszych, we wszystkich mieszkaniach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Ktobykolwiek chciał zabić człowieka, za świadectwem świadków zabije mężobójcę; ale świadek jeden nie będzie mógł świadczyć na skazanie kogo na śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Nie weźmiecie też okupu za żywot mężobójcy, który zasłużył śmierć; niech śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Nie weźmiecie też zapłaty od onego, który uciekł do miasta ucieczki swojej, aby się nawrócił na mieszkanie do ziemi swojej, pierwej niżby kapłan umarł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Byście nie splugawili ziemię, w której będziecie; bo krew takowa splugawiłaby ziemię; a ziemia nie może być oczyszczona od krwi, która jest wylana na niej, jedno krwią tego, który ją przelał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Przetoż nie plugawcie ziemi, w której mieszkacie, w której Ja też mieszkam; bom Ja Pan, który mieszkam między synami Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Tedy przystąpili mężowie przedniejsi z ojców pokolenia synów Galaada, syna Machyrowego, syna Manasesowego, z domów Józefowych, i mówili przed Mojżeszem, i przed książęty przedniejszymi ojców synów Izraelskich, i rzekli:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Tobie, panu memu, rozkazał Pan, abyś podzielił ziemię w dziedzictwo losem synom Izraelskim; nadto panu memu rozkazano od Pana, abyś dał dziedzictwo Salfaada, brata naszego, córkom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Które jeźliby kto z inszego pokolenia synów Izraelskich wziął za żony, odjęte będzie ich dziedzictwo od dziedzictwa ojców naszych, a przyłączy się do dziedzictwa onego pokolenia, do którego by je wzięto za żony, a tak z losu dziedzictwa naszego ubędzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'A gdy przyjdzie miłościwe lato synom Izraelskim, tedy przyłączone będzie dziedzictwo ich do dziedzictwa onego pokolenia, do którego by poszły za mąż; a tak od dziedzictwa pokolenia ojców naszych odjęte będzie dziedzictwo ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Tedy powiedział Mojżesz synom Izraelskim według słowa Pańskiego, mówiąc: Dobrze mówi pokolenie synów Józefowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Toć to jest, co rozkazał Pan o córkach Salfaadowych, mówiąc: Jako się im upodoba, niech idą za mąż; tylko w domu pokolenia ojców swoich niech idą za mąż.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Aby nie było przenoszone dziedzictwo synów Izraelskich z pokolenia na pokolenie; bo każdy z synów Izraelskich zostawać ma przy dziedzictwie pokolenia ojców swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'I każda córka, która by miała dziedzictwo z pokoleń synów Izraelskich, za kogokolwiek z domu pokolenia ojca swego pójdzie, żeby otrzymali dziedziczenie synowie Izraelscy, każdy dziedzictwo ojców swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Bo nie ma być przenoszone dziedzictwo, z pokolenia na pokolenie insze; ale każdy przy dziedzictwie swojem zostać ma z pokolenia synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Jako tedy rozkazał Pan Mojżeszowi, tak uczyniły córki Salfaadowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Bo Mahala, Tersa, i Hegla, i Melcha, i Noa, córki Salfaadowe, szły za mąż, za syny stryjów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'W domy synów Manasesa, syna Józefowego poszły za mąż; i tak zostało dziedzictwo ich przy pokoleniu domu ojca ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Teć są przykazania i prawa, które rozkazał Pan przez Mojżesza synom Izraelskim na polach Moabskich, nad Jordanem przeciw Jerychowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Teć są słowa, które mówił Mojżesz do wszystkiego Izraela przed Jordanem na puszczy, na równinie przeciw morzu czerwonemu, między Faran, i między Tofel, i Laban, i Haserot, i Dyzahab.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'A jest jedenaście dni drogi od Horebu przez górę Seir aż do Kades Barne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'I stało się czterdziestego roku, jedenastego miesiąca, pierwszego dnia tegoż miesiąca, że opowiedział Mojżesz synom Izraelskim to wszystko, co mu był rozkazał Pan do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Gdy poraził Sehona, króla Amorejskiego, który mieszkał w Hesebon, i Oga, króla Basańskiego, który mieszkał w Astarot w Edrej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Przed Jordanem w ziemi Moabskiej począł Mojżesz wykładać ten zakon, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Pan, Bóg nasz, mówił do nas na górze Horeb, i rzekł: Dosycieście mieszkali na tej górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Obróćcież się, a ciągnąc idźcie do góry Amorejskiej, i na wszystkie miejsca pograniczne jej, na równiny, na góry, i na doliny, i ku południowi, i ku brzegu morskiemu, ku ziemi Chananejskiej, i do Libanu, aż do wielkiej rzeki, rzeki Eufrates.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Oto, dałem wam tę ziemię; wnijdźcież a posiądźcie tę ziemię, o którą przysiągł Pan ojcom waszym, Abrahamowi, Izaakowi i Jakóbowi, iż im ją dać miał, i nasieniu ich po nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'I rzekłem do was na on czas, mówiąc: Nie mogę sam nosić was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Pan, Bóg wasz, rozmnożył was, a otoście dziś jako gwiazdy niebieskie w mnóstwie swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Pan, Bóg ojców waszych, niech rozmnoży was nad to, jakoście teraz, tysiąc kroć więcej; i niech was błogosławi, jako wam obiecał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Jakoż sam znosić mam ciężką pracę około was, i brzemię wasze, i swary wasze?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Obierzcie z siebie męże mądre i umiejętne a doświadczone w pokoleniach waszych, a postanowię je przełożonymi nad wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Tedyście mi odpowiedzieli, i rzekliście: Dobra rzecz, którąś rozkazał uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'I obrałem przedniejsze z pokoleń waszych, męże mądre, i doświadczone, i postanowiłem je przełożonymi nad wami: tysiączniki, i setniki, i pięćdziesiątniki, i dziesiątniki, i rządce w pokoleniach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'I rozkazałem sędziom waszym na on czas, mówiąc: Wysłuchywajcie spraw między bracią waszą, i sądźcie sprawiedliwie między mężem i między bratem jego, i między przychodniem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Nie miejcie względu na osoby przy sądzie; tak małego jako wielkiego wysłuchywajcie; nie bójcie się nikogo, albowiem sąd Boży jest; a jeźliby co przytrudniejszem było na was, odniesiecie do mnie, a ja tego przesłucham.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'I przykazałem wam na on czas wszystko, coście czynić mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Potem ruszywszy się z Horeb przeszliśmy wszystkę onę pustynią wielką i straszną, którąście widzieli, idąc drogą ku górze Amorejskiej, jako nam był rozkazał Pan, Bóg nasz, i przyszliśmy aż do Kades Barne');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'I rzekłem do was: Przyszliście aż do góry Amorejczyka, którego Pan, Bóg nasz, dawa nam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Oto, podawa Pan, Bóg twój, tobie tę ziemię; idźże, a posiądź ją, jakoć powiedział Pan, Bóg ojców twoich, nie bój się ani się lękaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'I przyszliście do mnie wszyscy, a mówiliście: Poślijmy męże przed sobą, którzy by nam przeszpiegowali ziemię, i dali nam pewną sprawę, którą byśmy drogą do niej wnijść mieli, i miasta, do których byśmy weszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Co gdy mi się podobało, obrałem z was dwanaście mężów, po jednym mężu z każdego pokolenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Którzy odszedłszy weszli na górę, a przyszli aż do doliny Eschol, i przeszpiegowali ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Nabrali też z sobą owocu onej ziemi, i przynieśli do nas, i dali nam o tem sprawę, a powiedzieli: Dobra jest ziemia, którą nam dawa Pan, Bóg nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Aleście nie chcieli iść: leczeście byli odpornymi słowu Pana, Boga waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'I szemraliście w namieciech waszych, mówiąc: Iż nas Pan miał w nienawiści, wywiódł nas z ziemi Egipskiej, aby nas podał w ręce Amorejczyka, i wygubił nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Dokądże iść mamy? Bracia nasi zepsowali nam serce, mówiąc: Lud ten większy i roślejszy jest, niźli my, miasta wielkie, i wymurowane aż ku niebu, a nad to, syny olbrzymów widzieliśmy tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Alem ja mówił do was: Nie lękajcie się, ani się ich bójcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Pan, Bóg wasz, który idzie przed wami, walczyć będzie za was, tak jako wam uczynił w Egipcie przed oczyma waszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'Także i na puszczy, gdzieś widział, jako cię nosił Pan, Bóg twój, jako nosi ojciec syna swego, w onej wszystkiej drodze, którąście szli, ażeście przyszli na to miejsce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Lecz ani tak uwierzyliście Panu, Bogu waszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Który chodził przed wami w drodze, przepatrując wam miejsce do stanowienia obozu, w nocy w ogniu, aby wam ukazał drogę którą byście iść mieli, we dnie zaś w obłoku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'I usłyszał Pan głos słów waszych, a rozgniewał się bardzo, i przysiągł, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Zaiste żaden z ludu tego narodu złego, nie ogląda onej ziemi dobrej, którąm przysiągł dać ojcom waszym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Oprócz Kaleba, syna Jefunowego, ten ją ogląda, i temu dam ziemię, którą deptał, i synom jego, przeto że cale szedł za Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Także i na mię rozgniewał się Pan dla was, mówiąc: I ty tam nie wnijdziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Jozue, syn Nunów, któryć służy, ten tam wnijdzie, tegoż utwierdzaj; bo ją on w dziedzictwo poda Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Dziatki też wasze, o którycheście mówili, że będą podane na łup, także synowi wasi, którzy dziś nie wiedzą dobrego ani złego, ci tam wnijdą i onym ją dam, a oni ją dziedzicznie posiędą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Ale wy obróciwszy się, idźcie na puszczą, drogą ku morzu czerwonemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'A odpowiadając mówiliście do mnie: Zgrzeszyliśmy Panu; pójdziemy, i walczyć będziemy według tego wszystkiego, jako nam rozkazał Pan, Bóg nasz; i ubrał się każdy z was we zbroje swoje, a chcieliście wnijść na górę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Lecz Pan rzekł do mnie: Powiedz im: Nie wstępójcie, ani walczcie; bom nie jest w pośrodku was, abyście nie byli porażeni od nieprzyjaciół waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Co gdym wam opowiedział, nie słuchaliście, aleście odporni byli słowu Pańskiemu, i hardzieście postąpili sobie, a weszliście na górę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Tedy wyciągnął Amorejczyk, który mieszkał na onej górze, przeciwko wam, i gonili was, jako zwykły pszczoły, i porazili was w Seir aż do Horma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'I wróciwszy się, płakaliście przed Panem; lecz nie wysłuchał Pan głosu waszego, a nie nakłonił uszu swoich do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Mieszkaliście tedy w Kades przez wiele dni według liczby dni, którycheście tam mieszkali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Potem obróciwszy się, poszliśmy na puszczą, drogą ku morzu czerwonemu, jako mówił Pan do mnie, i krążyliśmy około około góry Seir przez wiele dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Tedy rzekł Pan do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Dosycieście już krążyli około tej góry, obróćcież się ku północy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'A ludowi rozkaż mówiąc: Wy wnet pójdziecie przez granice braci waszej, synów Ezawowych, którzy mieszkają w Seir, i będą się was bali; ale się i wy pilnie strzeżcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Nie drażnijcież ich; albowiem nie dam wam ziemi ich, ani na stopę nogi, gdyżem w osiadłość dał Ezawowi górę Seir.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Żywność będziecie kupowali u nich za pieniądze, i jeść będziecie; także i wodę od nich kupować będziecie za pieniądze, i pić będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Albowiem ci Pan, Bóg twój, błogosławił we wszelkiej sprawie rąk twoich, i wiedział drogę twoję na tej puszczy wielkiej; już przez czterdzieści lat Pan, Bóg twój, był z tobą, nie schodziłoć na niczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Poszliśmy tedy od braci naszej, synów Ezawowych, mieszkających w Seir, drogą równą od Elat, i od Asyjongaber, a nawróciwszy się udaliśmy się drogą ku puszczy Moabskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'I rzekł Pan do mnie: Nie nacieraj na Moabczyki, ani podnoś wojny przeciwko nim; boć nie dam ziemi ich w osiadłość, gdyżem synom Lotowym dał Ar w dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(Emitowie pierwej mieszkali w niej, lud potężny i wielki, i wysokiego wzrostu, jako Enakimowie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Które też za olbrzymy miano, jako Enakimy, a Moabczykowie zwali je Emim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Także w Seir mieszkali Horejczycy przedtem, które synowie Ezawowi wygnali, i wygładzili je przed sobą, a mieszkali na miejscu ich, jako uczynił Izrael w ziemi osiadłości swojej, którą im dał Pan.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Wstańcież tedy, a przeprawcie się przez potok Zared; i przeprawiliśmy się przez potok Zared.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'A czasu, któregośmy chodzili od Kades Barne, ażeśmy się przeprawili przez potok Zared, było trzydzieści i osiem lat, aż wyginął wszystek on naród mężów walecznych z obozu, jako im był przysiągł Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Albowiem ręka Pańska była przeciwko nim na wytracenie ich z obozu, aż ich wygubiła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'I stało się, gdy wyginęli wszyscy mężowie waleczni, i pomarli z pośrodku ludu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Że rzekł Pan do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Ty dziś przejdziesz granicę Moabską Ar,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'I przyjdziesz blisko ku synom Ammonowym; nie nacierajże na nie, ani podnoś wojny przeciwko nim; boć nie dam ziemi synów Ammonowych w osiadłość, ponieważ synom Lotowym dałem ją w dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Tę też ziemię za ziemię olbrzymów miano; albowiem olbrzymowie mieszkali w niej przedtem, które Ammonitowie nazywali Zomzomim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Lud potężny, i wielki, i wysokiego wzrostu, jako Enakimowie; ale wygubił je Pan przed nimi, a Ammonitowie opanowali je i mieszkali na miejscu ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Jako uczynił synom Ezawowym mieszkającym w Seir, dla których wytracił Horejczyki przed obliczem ich; i wygnali je, i mieszkai na miejscach ich aż po dziś dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Hewejczyki także, którzy mieszkali w Aserym aż do Gazy, Kaftorytowie, którzy wyszli z Kaftor, wytracili je, i mieszkali na miejscu ich.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Wstawszy tedy idźcie, a przeprawcie się przez potok Arnon; oto, Ja dawam w ręce twoje Sehona, króla Hesebon Amorejczyka, i ziemię jego, pocznijże ją posiadać, a podnieś przeciwko niemu wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Dzisiaj pocznę puszczać strach i bojaźń twoję na ludzie, którzy są pod wszystkiem niebem, że gdy usłyszą wieść o tobie, drżeć i lękać się będą przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Tedym posłał posły z puszczy Kademot do Sehona, króla Hesebońskiego, z poselstwem spokojnem, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Niech przejdę przez ziemię twoję; drogą pospolitą pójdę; nie uchylę się ani na prawo ani na lewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Żywności za pieniądze sprzedasz mi, abym jadł; wody także za pieniądze dasz mi, abym pił: tylko przejdę nogami memi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Jako mi uczynili synowie Ezawowi, którzy mieszkają w Seir, i Moabczycy, którzy mieszkają w Ar, ażbyśmy się przeprawili za Jordan, do ziemi, którą Pan, Bóg nasz, dawa nam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Ale nie chciał Sehon, król Heseboński, pozwolić nam przejścia przez ziemię swoję: bo był zatwardził Pan, Bóg twój, ducha jego, i stwierdził serce jego, aby go podał w ręce twoje, jako to dziś widzisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Tedy rzekł Pan do mnie: Otom ci już począł podawać w moc Sehona, i ziemię jego: pocznijże ją posiadać, abyś odziedziczył ziemię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Ruszył się tedy Sehon przeciwko nam, sam i wszystek lud jego, chcąc z nami zwieść bitwę w Jaza;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Ale go nam podał Pan, Bóg nasz, w moc, i poraziliśmy go, i syny jego i wszystek lud jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'I wzięliśmy wszystkie miasta jego na on czas, i wniwecześmy obrócili wszystkie miasta, mężczyzny i niewiasty, i dzieci, nie zostawiwszy z nich nikogo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Tylkośmy bydło pobrali sobie, i korzyści z miast, którycheśmy dobyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Od Aroer, które leży nad brzegiem potoku Arnon, i od miasta, które jest w dolinie aż do Galaad, nie było miasta, które by się nam nie podało; wszystkie podał nam Pan, Bóg nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Tylkoś do ziemi synów Ammonowych nie dochodził ani do żadnego miejsca przyległego potokowi Jabok, ani do miast na górach, ani do żadnych miejsc, których zakazał Pan, Bóg nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Potem obróciwszy się szliśmy drogą ku Basan; i wyciągnął przeciwko nam Og, król Basański, sam, i wszystek lud jego, ku bitwie w Edrej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Tedy rzekł Pan do mnie: Nie bój się go; bom go dał w ręce twoje, i wszystek lud jego, i ziemię jego, i uczynisz mu, jakoś uczynił Sehonowi, królowi Amorejskiemu, który mieszkał w Hesebon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Dał tedy Pan, Bóg nasz, w ręce nasze i Oga, króla Basańskiego, i wszystek lud jego, i poraziliśmy go, tak że nie zostało po nim nikogo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Wzięliśmy też wszystkie miasta jego na on czas; nie było miasta, którego byśmy im nie wzięli, sześćdziesiąt miast, wszystkę krainę Argob królestwa Ogowego w Basan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Te wszystkie miasta opatrzone były murami wysokiemi, bramami, i zaworami, oprócz miasteczek murem nie obtoczonych bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'I spustoszyliśmy je, jakośmy uczynili Sehonowi, królowi Hesebońskiemu, wytraciwszy wszystkie miasta, męże, niewiasty i dzieci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Tylko wszystkie bydła i łupy z miast rozebraliśmy między się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Wzięliśmy też na on czas ziemię z ręki dwóch królów Amorejskich, która leży z tej strony Jordanu, od rzeki Arnon aż do góry Hermon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(Sydończycy zowią Hermon Szyryjon, a Amorejczycy zowią go Sanir.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Wszystkie miasta w równinie, i wszystko Galaad, i wszystko Basan aż do Selcha, i Edrej, miasta królestwa Ogowego w Basan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Bo tylko sam Og, król Basański pozostał był z olbrzymów; oto, łoże jego łoże żelazne, azaż jeszcze nie jest w Rabbat, synów Ammonowych? dziewięć łokci długość jego, a cztery łokcie szerokość jego na łokieć męski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Gdyśmy tedy ziemię tę posiedli na on czas, od Aroer, które jest nad potokiem Arnon, i połowę góry Galaad, i miasta jej dałem Rubenitom, i Gadytom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'A ostatek Galaadu, i wszystko Basan, królestwa Ogowego, dałem połowie pokolenia Manasesowego, wszystkę krainę Argob, i wszystko Basan, które zowią ziemią olbrzymów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, syn Manasesów, posiadł wszystkę krainę Argob aż do granicy Jessury i Machaty; przetoż nazwał ją od imienia swego Basan Hawot Jair, aż do dzisiejszego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Machirowi zaś dałem Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'A Rubenitom i Gadytom dałem krainę od Galaadu aż do potoku Arnon, pół potoku z pograniczem, aż do potoku Jabok, granicy synów Ammonowych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Przytem równinę i Jordan z pograniczem od Cyneret aż do morza pustego, które jest morze słone, pod górą Fazga na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'I rozkazałem wam na on czas, mówiąc: Pan, Bóg wasz, dał wam tę ziemię, abyście ją dziedzicznie posiedli, a tak zbrojno pójdziecie przed bracią waszą, syny Izraelskimi, wszyscy mężowie duży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Tylko żony wasze, i dziatki wasze, i bydła wasze, (gdyż wiem, że dobytku siła macie,) zostaną w mieściech waszych, którem wam dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Aż da odpoczynek Pan braci waszej, jako i wam, że i oni posiędą ziemię onę, którą Pan, Bóg wasz, dawa im za Jordanem: tedy się wróci każdy do osiadłości swojej, którą wam dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Jozuemu też przykazałem na on czas, mówiąc: Oczy twoje widziały wszystko, co uczynił Pan, Bóg wasz, onym dwom królom; toż uczyni Pan, wszystkim królestwom, do których ty pójdziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Nie bójcież się ich, ponieważ Pan, Bóg wasz, jest, który walczy za was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'I prosiłem Pana na on czas, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Panie Boże, tyś począł okazywać słudze twemu wielkość twoję, i rękę twoję możną; bo któż jest Bogiem na niebie, albo na ziemi, któryby czynić mógł według spraw twoich, i według możności twoich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'NIech przejdę proszę, abym oglądał tę wyborną ziemię, która jest za Jordanem, górę onę wyborną i z Libanem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Ale się rozgniewał Pan na mię dla was, i nie wysłuchał mię, i rzekł Pan do mnie: Dosyć masz, nie mówże już więcej do mnie o to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Wstąp na wierzch góry Fazga, a podnieś oczy swe ku zachodowi, i ku północy, i ku południowi, i ku wschodowi, a przypatrz się oczyma swemi; bo nie przejdziesz przez ten Jordan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Ale porucz to Jozuemu, i umocnij go, a potwierdź go; albowiem on pójdzie przed tym ludem, a on poda im w dziedzictwo ziemię, którą oglądasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'A tak mieszkaliśmy w dolinie przeciw Betfegor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Teraz tedy, o Izraelu, słuchaj ustaw, i sądów, których ja was uczę, abyście je czyniąc żyli, a wszedłszy posiedli ziemię, którą Pan, Bóg ojców waszych, dawa wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Nie przydacie do słowa, które ja wam rozkazuję, ani ujmiecie z niego, abyście strzegli przykazań Pana, Boga waszego, które ja wam rozkazuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Oczy wasze widziały, co uczynił Pan dla Baal fegora, jako każdego męża, który się udawał za Baal fegorem, wytracił Pan, Bóg twój, z pośrodku was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'A wy, którzyście trwali przy Panu, Bogu waszym, żyjecie wszyscy aż do dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Patrzcież, żem was nauczał ustaw i sądów, jako mi rozkazał Pan, Bóg mój, abyście tak czynili w ziemi tej, do której wchodzicie, abyście ją dziedzicznie posiedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Przestrzegajcież ich tedy, a czyńcie je; to bowiem jest mądrość wasza, i rozum wasz przed oczyma narodów; którzy usłyszawszy o tych wszystkich ustawach, rzeką: Tylko ten lud mądry, i rozumny, i naród wielki jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Albowiem któryż naród tak wielki jest, coby mu byli bogowie tak bliscy, jako Pan, Bóg nasz, we wszystkiem, ilekroć go wzywamy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Albo któryż naród tak wielki, któryby miał ustawy i sądy tak sprawiedliwe, jako wszystek ten zakon, który ja przedkładam wam dziś?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'A wszakże miej się na pieczy, a strzeż duszy twej pilnie, byś snać nie zapomniał na te rzeczy, które widziały oczy twoje i aby snać nie odstąpiły od serca twego po wszystkie dni żywota twego; i oznajmisz je synom twym, i synom synów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Nie zapominaj, żeś onego dnia stał przed oblicznością Pana, Boga twego, na Horeb, gdy mówił Pan do mnie: Zgromadź mi lud, abym im powiedział słowa moje, których się uczyć będą, aby się mnie bali po wszystkie dni, pokąd żyć będą na ziemi, i synów swoich nauczając tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Tedyście przystąpili, a stanęliście pod górą, a ona góra pałała ogniem aż do samego nieba, a była na niej ciemność, obłok i mgła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'I mówił Pan do was z pośród ognia; głos słów słyszeliście, aleście podobieństwa żadnego nie widzieli oprócz głosu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'I oznajmił wam przymierze swoje, które rozkazał wam, abyście je czynili, to jest dziesięć słów, które napisał na dwóch tablicach kamiennych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Mnie też rozkazał Pan na on czas, abym was nauczał ustaw i sądów, abyście je czynili w ziemi, do której idziecie, abyście ją dziedzicznie posiedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'A tak strzeżcie pilnie dusz waszych, (gdyżeście nie widzieli żadnego podobieństwa, dnia, którego mówił Pan do was na Horebie z pośrodku ognia,)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'Abyście się snać nie popsowali, i nie czynili sobie rytego bałwana, albo obrazu wszelkiego podobieństwa, kształtu mężczyzny albo niewiasty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Albo kształtu jakiego zwierzęcia, które jest na ziemi, kształtu wszelkiego ptaka skrzydlastego, który lata po powietrzu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Kształtu wszystkiego tego, co się płaza po ziemi, kształtu wszelkiej ryby, która jest w wodzie pod ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Ani podnoś oczu swych ku niebu, żebyś widząc słońce i miesiąc, i gwiazdy ze wszystkiemi zastępy niebieskiemi, nie dał się uwieść, abyś się im kłaniał, i służyłbyś im, ponieważ je oddał Pan, Bóg twój, na posługę wszystkim ludziom pod wszystkiem niebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Aleć was wziął Pan, i wywiódł was jako z żelaznego pieca, z Egiptu, abyście byli jego ludem dziedzicznym, jako dziś jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'A Pan rozgniewał się na mię dla was, a przysiągł, że nie przejdę przez Jordan, ani wnijdę do onej wybornej ziemi, którą Pan, Bóg twój, dawa tobie w dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Bo ja umrę w tej ziemi, ja nie przejdę za Jordan; ale wy przejdziecie, i dziedzicznie osiądziecie tę dobrą ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Strzeżcież się, byście snać nie zapomnieli przymierza Pana, Boga waszego, które uczynił z wami, a nie czynili sobie rytego obrazu na kształt jakiejkolwiek rzeczy, jakoć rozkazał Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Albowiem Pan, Bóg twój, jest ogień trawiący, Bóg zawisny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Gdy spłodzisz syny i wnuki, a zstarzejecie się w ziemi onej, jeźlibyście się popsowali, a czynilibyście sobie ryte bałwany na kształt jakiejkolwiek rzeczy, i uczynilibyście co złego przed oczyma Pana, Boga waszego, drażniąc go:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'Biorę na świadectwo przeciwko wam dziś niebo i ziemię, iż pewnie w rychle wyginiecie z ziemi, do której pójdziecie przez Jordan, abyście dziedzicznie ją posiedli; nie przedłużycie dni waszych w niej, bo pewnie wytraceni będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'I rozproszy was Pan między narody, a zostanie was mało między narody, do których zaprowadzi was Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Tamże będziecie służyli bogom, robocie rąk ludzkich, drewnu i kamieniowi, które ani widzą, ani słyszą, ani wąchają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'A wszakże i tam jeźli szukać będziesz Pana, Boga twego, tedy znajdziesz, będzieszli go szukał całem sercem twojem, i całą duszą swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'Gdy ucisk przyjdzie na cię, a najdą cię te wszystkie rzeczy w ostatnie dni, tedy, nawróciszli się do Pana, Boga twego, a posłusznym będziesz głosowi jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, '(Albowiem Bóg miłosierny Pan, Bóg twój jest) nie opuści cię, ani cię skazi, ani zapomni na przymierze ojców twoich, które im przysiągł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Pytaj się teraz na dni starodawne, które były przed tobą, ode dnia, którego stworzył Bóg człowieka na ziemi; a od jednego końca nieba aż do drugiego końca nieba stałali się kiedy rzecz podobna tej tak wielkiej? albo słuchanoli kiedy co takowego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Słyszałli kiedy który naród głos Boga mówiącego z pośrodku ognia, jakoś ty słyszał, a żyw został?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Albo kusiłli się który bóg przyjść a wziąć sobie naród z pośrodku innego narodu przez pokusy, przez znaki, i przez cuda, i przez wojny, i przez mocną rękę, i przez ramię wyciągnione, i w strachach wielkich, według wszystkiego, jako uczynił dla was Pan, Bóg wasz, w Egipcie przed oczyma twemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Tobie to ukazano, abyś wiedział, iż Pan jest Bóg, a nie masz innego oprócz niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Dał ci z nieba słyszeć głos swój, aby cię wyćwiczył, a na ziemi ukazał ci ogień swój wielki, a słowa jego słyszałeś z pośrodku ognia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'A iż umiłował ojce twoje, obrał nasienie ich po nich, i wywiódł cię przed sobą mocą swoją wielką z Egiptu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'Aby wygnał narody wielkie i możniejsze nad cię przed twarzą twoją, i wprowadził cię, a dał ci ziemię ich w dziedzictwo, jako to dziś widzisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Wiedzże tedy dziś, a wspomnij na to w sercu twojem, iż Pan jest Bogiem na niebie wysoko, i na ziemi nisko nie masz innego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'A tak przestrzegaj ustaw jego, i przykazań jego, które ja dziś rozkazuję tobie, abyć się dobrze wodziło, i synom twoim po tobie; abyś też przedłużył dni na ziemi, którą Pan, Bóg twój, da tobie, po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Tedy oddzielił Mojżesz trzy miasta z tej strony Jordanu na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Aby tam uciekał mężobójca, któryby zabił bliźniego swego z nieobaczenia, nie mając go w nienawiści przedtem, aby uciekłszy do jednego z tych miast, żyw został;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Beser na puszczy, w równinie w ziemi Rubenitów, i Ramot w Galaad między Gadyty, i Golam w Bazan między Manassytami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Tenci jest zakon, który przedłożył Mojżesz synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Te są świadectwa, i ustawy, i sądy, które mówił Mojżesz do synów Izraelskich, gdy wyszli z Egiptu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'Z tej strony Jordanu, w dolinie przeciw Betfegor, w ziemi Sehona, króla Amorejskiego, który mieszkał w Hesebon, którego poraził Mojżesz, i synowie Izraelscy, gdy szli z Egiptu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'I osiedli ziemię jego, i ziemię Oga, króla Basańskiego, dwóch królów Amorejskich, którzy byli z tej strony Jordanu na wschód słońca;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Od Aroer, które jest nad brzegiem potoku Arnon, i aż do góry Syon, która jest Hermon;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'I wszystkie pola nad Jordanem na wschód słońca, i aż do morza pustego, pod górą Fazga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Tedy zawoławszy Mojżesz wszystkiego Izraela; mówił do nich: Słuchaj Izraelu, ustaw i sądów, które ja dziś mówię w uszy wasze; nauczcie się ich, a przestrzegajcie tego, abyście je czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Pan, Bóg nasz, uczynił z nami przymierze na górze Horeb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Nie z ojcy naszymi uczynił Pan to przymierze, ale z nami, którzyśmy tu dziś wszyscy żywi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Twarzą w twarz mówił Pan z wami na górze, z pośrodku ognia,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, '(A jam stał między Panem, i między wami na on czas, abym wam odnosił słowo Pańskie; boście się bali ognia, a nie wstąpiliście na górę) i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Jam jest Pan, Bóg twój, którym cię wywiódł z ziemi Egipskiej, z domu niewoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Nie będziesz miał bogów innych przede mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Nie czyń sobie obrazu rytego, ani żadnego podobieństwa tych rzeczy, które są na niebie wzgórę, i które na ziemi nisko, i które w wodach pod ziemią;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Nie będziesz się im kłaniał, ani ich chwalił: bom Ja Pan, Bóg twój, Bóg zawisny w miłości, nawiedzający nieprawość ojców nad syny do trzeciego i do czwartego pokolenia tych, którzy mię nienawidzą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'A czyniący miłosierdzie nad tysiącami tych, którzy mię miłują, i strzegą przykazań moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Nie bierz imienia Pana, Boga twego, na daremno: bo się będzie mścił Pan nad tym, który imię jego na daremno bierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Przestrzegaj dnia sobotniego, abyś go święcił, jakoć rozkazał Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Przez sześć dni będziesz robił, i wykonasz wszelaką robotę twoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Ale dnia siódmego jest odpocznienie Pana, Boga twego; nie czyń żadnej roboty, ty i syn twój, i córka twoja, i sługa twój, i służebnica twoja, i wół twój, i osieł twój, i każde bydlę twoje, i gość twój, który jest w bramach twoich, aby odpoczynął sługa twój, i służebnica twoja, jako i ty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'A pamiętaj, żeś był niewolnikiem w ziemi Egipskiej, i wywiódł cię Pan, Bóg twój, stamtąd ręką możną, i ramieniem wyciągnionem; przetoż ci przykazał Pan, Bóg twój, abyś obchodził dzień sobotni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Czcij ojca twego i matkę twoję, jakoć przykazał Pan, Bóg twój, aby przedłużone były dni twoje, i żebyć się dobrze działo na ziemi, którą Pan, Bóg twój, da tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Nie będziesz zabijał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Nie będziesz cudzołożył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Nie będziesz kradł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Nie będziesz mówił przeciw bliźniemu twemu świadectwa fałszywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Nie będziesz pożądał żony bliźniego twego, ani będziesz pożądał domu bliźniego twego, roli jego, i sługi jego, i służebnicy jego, wołu jego, i osła jego, i wszystkich rzeczy, które są bliźniego twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Teć słowa mówił Pan do wszystkiego zgromadzenia waszego na górze z pośrodku ognia, obłoku, i mgły, głosem wielkim, a nic więcej nie przydał, i napisał je na dwóch tablicach kamiennych, które mnie oddał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'I stało się, gdyście usłyszeli głos z pośrodku ciemności; gdy góra ogniem pałała, żeście przystąpili do mnie, wszystkie książęta pokoleń waszych, i starsi wasi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'I mówiliście: Oto nam ukazał Pan, Bóg nasz, chwałę swoję, i wielmożność swoję, a głos jego słyszeliśmy, z pośrodku ognia; dziś widzieliśmy, że Bóg mówił z człowiekiem, a człowiek żyw został.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'A tak teraz przeczże mamy pomrzeć? albowiem nas ten ogień wielki pożre; jeźli jeszcze słyszeć będziemy głos Pana, Boga naszego, pomrzemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Albowiem cóż jest wszelkie ciało, aby słyszało głos Boga żywiącego, mówiącego z pośrodku ognia, jako my, a żywo zostało?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Idźże ty, a wysłuchaj wszystkiego, co będzie mówił Pan, Bóg nasz; ty zaś powiesz nam wszystko, co do ciebie mówić będzie Pan, Bóg nasz, a my słuchać i czynić to będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'A usłyszawszy Pan głos słów waszych, gdyście mówili do mnie, rzekł mi Pan: Słyszałem głos słów ludu tego, które mówili do ciebie; dobrze wszystko mówili, co mówili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Kto by im to dał, żeby serce ich było takie, aby się mnie bali, i strzegli wszystkich przykazań moich po wszystkie dni, aby się im dobrze działo i synom ich na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Idźże, a rzecz im: Wróćcie się do namiotów waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'A ty tu zostań przy mnie, i opowiem tobie wszystkie przykazania, i ustawy, i sądy, których ich nauczać będziesz, aby je czynili w ziemi, którą Ja im dawam, aby ją posiedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Przetoż strzeżcie, abyście czynili, jako wam rozkazał Pan, Bóg wasz, nie uchylając się na prawo ani na lewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'Wszelką też drogą, którą wam przykazał Pan, Bóg wasz, chodzić będziecie, abyście żyli, i dobrze się wam działo, i żebyście przedłużyli dni swoje na ziemi, którą posiądziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'A teć są przykazania, ustawy i sądy, które rozkazał Pan, Bóg wasz, abym was nauczył, żebyście je czynili w ziemi, do której idziecie, abyście ją posiedli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Żebyś się bał Pana, Boga twego, przestrzegając wszystkich ustaw jego i przykazań jego, które ja przykazuję tobie, ty i syn twój, i syn syna twego, po wszystkie dni żywota swego, aby się przedłużyły dni twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'A tak słuchaj Izraelu, i strzeż, abyś tak czynił, iżby się tobie dobrze działo, i żebyście się rozmnożyli bardzo (jako obiecał Pan, Bóg ojców twoich, tobie), w ziemi opływającej mlekiem i miodem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Słuchajże Izraelu: Pan, Bóg nasz, Pan jeden jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Będziesz tedy miłował Pana, Boga twego, ze wszystkiego serca twego, i ze wszystkiej duszy twojej, i ze wszystkiej siły twojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'A będą te słowa, które ja dziś rozkazuję tobie, w sercu twojem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'I będziesz je często przypominał synom twoim, i rozmawiał o nich siedząc w domu twym, i będąc w drodze, i kładąc się i wstawając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'I przywiążesz je za znak na rękach twoich, i będą jako naczelniki między oczyma twemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Napiszesz je też na podwojach domu twego, i na bramach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'A gdy cię wprowadzi Pan, Bóg twój, do ziemi, o którą przysiągł ojcom twoim Abrahamowi, Izaakowi, i Jakóbowi, że ją tobie da, miasta wielkie i dobre, którycheś nie budował;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'Przytem domy pełne dóbr wszelakich, którycheś nie naprzątał, i studnie wykopane, którycheś nie kopał, winnice i oliwnice, którycheś nie sadził, a będziesz jadł, i najesz się:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'Strzeżże się, abyś nie zapomniał Pana, który cię wywiódł z ziemi Egipskiej, z domu niewoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Pana, Boga twego, bać się będziesz, jemu służyć, a przez imię jego przysięgać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Nie udacie się za bogami obcymi, za bogami narodów, które są około was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, '(Albowiem Bóg zawisny w miłości Pan, Bóg twój, w pośrodku ciebie), by się snać gniew nie zapalił Pana, Boga twego, przeciw tobie, a wytraciłby cię z oblicza ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Nie będziecie kusić Pana, Boga waszego, jakoście go kusili w Massa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Przestrzegać będziecie z pilnością przykazań Pana, Boga waszego, i świadectw jego i ustaw jego, któreć przykazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'A czyń to, co jest prawego i dobrego przed oczyma Pańskiemi, abyć się dobrze działo, abyś wszedłszy posiadł tę wyborną ziemię, o którą przysiągł Pan ojcom twoim:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Żeby wygnał wszystkie nieprzyjacioły twoje przed tobą, jako mówił Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'A gdyby cię napotem spytał syn twój, mówiąc: Cóż to za świadectwa, i ustawy, i sądy, które wam przykazał Pan, Bóg nasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'Tedy powiesz synowi twemu: Byliśmy niewolnikami Faraonowymi w Egipcie, i wywiódł nas z Egiptu Pan w ręce możnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'I czynił Pan znaki, i cuda wielkie, i szkodliwe w Egipcie nad Faraonem, i nad wszystkim domem jego, przed oczyma naszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'A wywiódł nas stamtąd, aby nas wprowadził, i dał nam tę ziemię, o którą przysiągł ojcom naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'A tak rozkazał nam Pan, abyśmy czynili wszystkie te ustawy, bojąc się Pana, Boga naszego, żeby się nam dobrze działo po wszystkie dni, aby nas przy żywocie zachował, jako i dziś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'I będzie to sprawiedliwością naszą, gdy będziemy strzedz i czynić te wszystkie przykazania przed Panem, Bogiem naszym, jako nam przykazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Gdy cię wprowadzi Pan, Bóg twój, do ziemi, do której wchodzisz, abyś ją posiadł i wytraci narodów wiele przed twarzą twoją, Hetejczyka, i Gergiezejczyka, i Amorejczyka, i Chananejczyka, i Ferezejczyka, i Hewejczyka i Jebuzejczyka, siedem narodów, większych, i możniejszych, niżliś ty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'A poda je Pan, Bóg twój, tobie, iż je porazisz: tedy wytracisz je do szczątku, nie będziesz brał z nimi przymierza, ani się zlitujesz nad nimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Ani się spowinowacisz z nimi: córki swej nie dasz synowi jego, i córki jego nie weźmiesz synowi swemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Boby zwiodła syna twego, żeby nie szedł za mną, a służyliby bogom cudzym; za czem zapaliłby się gniew Pański przeciwko wam, a wytraciłby was prędko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Ale owszem to im uczyńcie: Ołtarze ich poobalacie, a słupy ich pokruszycie, i gaje ich poświęcone wyrąbicie, a ryte ich bałwany ogniem popalicie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Albowiemeś ty lud święty Panu, Bogu twemu; ciebie obrał Pan, Bóg twój, abyś mu był osobliwym ludem ze wszystkich narodów, które są na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Nie przeto, że was więcej nad inne narody, przyłączył się Pan do was, i obrał was, gdyż was było najmniej ze wszystkich narodów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Ale iż was umiłował Pan, i strzedz chciał onej przysięgi, którą przysiągł ojcom waszym, wywiódł was Pan ręką możną, i wykupił was z domu niewoli, z ręki Faraona, króla Egipskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'A tak wiedz, że Pan, Bóg twój, jest Bóg, Bóg wierny, chowający przymierze, i miłosierdzie tym, którzy go miłują i strzegą przykazań jego, do tysięcznego pokolenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'A oddający tym, którzy go mają w nienawiści, każdemu w twarz jego, aby go wytracił; nie omieszka temu, który go ma w nienawiści, w twarz jego odda mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Przetoż przestrzegaj przykazania, i ustaw, i sądów, które ja dziś rozkazuję tobie, abyś je czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'I stanie się, że jeźli słuchać sądów tych, a przestrzegać, i czynić je będziecie, tedy też dotrzyma Pan, Bóg twój, tobie przymierza, i miłosierdzia, które poprzysiągł ojcom twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'I umiłuje cię; i ubłogosławi cię i rozmnoży cię; bo pobłogosławi owocowi żywota twego, i owocowi ziemi twojej, zbożu twojemu, i winu twojemu, i oliwie twojej, płodowi krów twoich, i trzodom owiec twoich w ziemi, o którą przysiągł ojcom twoim, że ją da tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Błogosławionym będziesz nad wszystkie narody; nie będzie u ciebie niepłodny, i niepłodna, ani między bydłem twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Oddali też Pan od ciebie każdą niemoc, i wszelkie choroby egipskie złe, o których wiesz; nie dopuści ich na cię, ale je przepuści na wszystkie, którzy cię nienawidzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'I wytracisz wszystkie narody, które Pan, Bóg twój, poda tobie; nie sfolguje im oko twoje, ani będziesz chwalił bogów ich; boćby to było sidłem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Jeźlibyś rzekł w sercu swem: Większe są te narody niźli ja, jakoż je będę mógł wygnać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'Nie bój się ich; ale pilnie pamiętaj na to, co uczynił Pan, Bóg twój, Faraonowi, i wszystkim Egipczanom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Na one kuszenia wielkie, które widziały oczy twoje, i na znaki, na cuda, i na rękę możną, i na ramię wyciągnione, którem cię wywiódł Pan, Bóg twój; takci uczyni Pan, Bóg twój, wszystkim narodom, których się ty twarzy boisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Nad to pośle Pan, Bóg twój, na nie sierszenie, aż wygubi ostatki ich, i te, którzy by się pokryli przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Nie lękajże się twarzy ich, albowiem Pan, Bóg twój, jest w pośrodku ciebie, Bóg wielki i straszny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'I wyniszczy Pan, Bóg twój, narody one przed tobą, po lekku i po trosze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Nie będziesz ich mógł wytracić prędko, by się snać nie namnożyło przeciw tobie bestyi polnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'I poda je tobie Pan, Bóg twój, i zetrze je starciem wielkiem, aż będą wyniszczeni. A poda króle ich w ręce twoje, i wygubisz imię ich pod niebem; nie ostoi się żaden przed tobą, aż je wytracisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Obrazy ryte bogów ich popalisz ogniem; nie będziesz pożądał srebra, ani złota, które jest na nich, abyś je miał sobie brać, byś się snać nie usidlił w niem, ponieważ to obrzydliwość jest Panu, Bogu twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Nie wnośże obrzydliwości w dom twój, abyś się nie stał przeklęstwem, jako i ona; wielce się nią brzydzić będziesz, i bardzo ją sobie obmierzysz, ponieważ przeklęstwem jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Wszystkie przykazania, które ja dziś przykazuję tobie, chować i czynić będziecie, abyście żyli, rozmnożeni byli, i weszli, a osiedli tę ziemię, o którą przysiągł Pan ojcom waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Miejże w pamięci wszystkę drogę, którą cię prowadził Pan, Bóg twój, przez te czterdzieści lat po puszczy, aby cię trapił, i doświadczył, aby wiadomo było, co jest w sercu twojem, jeźlibyś przestrzegał przykazań jego, czyli nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Przetoż dręczył cię, i głodem ci dokuczał; potem karmił cię manną, którejś nie znał, ani jej też znali ojcowie twoi, aby cię nauczył, iż nie samym chlebem żyje człowiek, ale tem wszystkiem, co pochodzi z ust Pańskich, żyć będzie człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Szata twoja nie wiotszała na tobie, i noga twoja nie napuchła przez te czterdzieści lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Poznajże tedy w sercu swem, że jako ćwiczy człowiek syna swego, tak Pan, Bóg twój, ćwiczy ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'A przestrzegaj przykazań Pana, Boga twego, abyś chodził drogami jego, i bał się go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Albowiem Pan, Bóg twój, prowadzi cię do ziemi tej dobrej, do ziemi, gdzie są potoki wód, źródła i przepaści wynikające po dolinach i po górach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Do ziemi obfitej w pszenicę, i w jęczmień, i w wino, i w figi, i w jabłka granatowe; do ziemi hojnej w oliwę i w miód;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Do ziemi, w której bez niedostatku jeść będziesz chleb, a na żadnej rzeczy schodzić ci nie będzie; do ziemi, której kamienie są żelazo, a z jej gór miedź kopać będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Gdy będziesz jadł, a najesz się, będziesz chwalił Pana, Boga twego, za ziemię wyborną, którą dał tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Strzeżże się, byś snać nie zapomniał Pana, Boga twego, a nie zaniedbał przykazań jego, i sądów jego, i ustaw jego, które ja dziś rozkazuję tobie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'By snać, gdy jeść będziesz do sytości, i piękne domy pobudujesz, a mieszkać w nich będziesz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'I gdyć się wołów i owiec namnoży, srebra także i złota będziesz miał dosyć, i wszystko, co będziesz miał, rozmnoży się:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'Nie podniosło się serce twoje, i zapomniałbyś Pana, Boga twego, który cię wywiódł z ziemi Egipskiej z domu niewoli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Który cię przeprowadził przez tę puszczą wielką i straszną, gdzie były węże jadowite, i niedźwiadki; i przez ziemię suchą, gdzie nie masz wody, i wywiódł ci wodę ze skały twardej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Który cię karmił manną na puszczy, której nie znali ojcowie twoi, aby cię trapił, i doświadczał cię, abyć na ostatek dobrze uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Ani mów w sercu swem: Moc moja, i siła ręki mojej nabawiła mię tych dóbr;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Ale pamiętaj na Pana, Boga twego; bo on dodawa tobie mocy ku nabywaniu bogactw, aby potwierdził przymierza swego, które poprzysiągł ojcom twoim, jako to okazuje dzień dzisiejszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Ale jeźliż cale zapomnisz Pana, Boga twego, a pójdziesz za bogami obcymi, i będziesz im służył, i kłaniał się im, oświadczam się przeciwko wam dziś, że koniecznie zginiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Jako narody, które Pan wytraca przed wami, tak zaginiecie dla tego, iżeście posłusznymi nie byli głosu Pana, Boga waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Słuchaj Izraelu! ty przejdziesz dziś Jordan, abyś wszedłszy posiadł narody większe, i możniejsze, niżeś ty, miasta wielkie, i wymurowane aż pod niebo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Lud wielki i wysokiego wzrostu syny Enakowe, które ty znasz, i o którycheś słyszał, gdy mówiono: Któż się ostoi przed syny Enakowymi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Przetoż wiedz dzisiaj, że Pan, Bóg twój, który idzie przed tobą, jest ogień trawiący: on je wytraci, i on je poniży przed tobą, że je wypędzisz, a wygładzisz je prędko, jakoć to obiecał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Nie mówże w sercu swem, gdy je wypędzi Pan, Bóg twój, przed tobą, powiadając: Dla sprawiedliwości mojej wprowadził mię Pan, abym posiadł tę ziemię; ale dla niezbożności narodów onych Pan wygnał je przed twarzą twoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Nie dla sprawiedliwości twojej, ani dla prostości serca twego ty wnijdziesz, abyś posiadł ziemię ich; ale dla niezbożności narodów tych Pan, Bóg twój, wypędza ich przed twarzą twoją, i aby utwierdził Pan słowo, które przysiągł ojcom twoim Abrahamowi, Izaakowi, i Jakóbowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Wiedzże tedy, że nie dla sprawiedliwości twojej, Pan, Bóg twój, daje tobie tę wyborną ziemię, abyś ją posiadł, gdyżeś ty lud twardego karku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Pamiętaj, a nie zapominaj, żeś do gniewu pobudzał Pana, Boga twego, na puszczy; od onego dnia, jakoś wyszedł z ziemi Egipskiej, ażeście przyszli na to miejsce, odpornymiście byli Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Także i przy górze Horeb pobudziliście do gniewu Pana, i rozgniewał się Pan na was, aby was wygładził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Gdym wstąpił na górę, abym wziął tablice kamienne, tablice przymierza, które uczynił Pan z wami, i trwałem na górze czterdzieści dni, i czterdzieści nocy, chleba nie jedząc, ani wody pijąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Tedy mi dał Pan dwie tablice kamienne, napisane palcem Bożym, na których te wszystkie słowa były, które mówił Pan do was na górze z pośrodku ognia, w dzień zgromadzenia waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'A gdy wyszło czterdzieści dni, i czterdzieści nocy, dał mi Pan one dwie tablice kamienne, tablice przymierza;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'I rzekł Pan do mnie: Wstań, znijdź stąd rychło; albowiem się popsował lud twój, któryś wywiódł z Egiptu; odstąpili prędko z drogi, którąm im rozkazał, i uczynili sobie litego bałwana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'I rzekł Pan do mnie, mówiąc: Widziałem ten lud, a oto, lud twardego karku jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Puść mię a wytracę je, i wygładzę imię ich pod niebem, a ciebie uczynię w naród możniejszy, i większy niźli ten.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Tedym się obrócił, i zstąpiłem z góry, (a góra ona pałała ogniem), dwie tablice przymierza niosąc w obu rękach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'A gdym ujrzał, iżeście zgrzeszyli przeciw Panu, Bogu waszemu, uczyniwszy sobie cielca litego i odstąpiliście byli prędko z drogi, którą wam rozkazał Pan:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Tedy wziąwszy ja one dwie tablice, porzuciłem je z obu rąk moich, a stłukłem je przed oczyma waszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Potem upadłem przed Panem jako i pierwej, przez czterdzieści dni i czterdzieści nocy, chlebam nie jadł, i wodym nie pił dla waszych wszystkich grzechów, któremiście zgrzeszyli, czyniąc złość przed oczyma Pańskiemi, i draźniąc go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Bom się bał onej popędliwości i gniewu, którym się był zapalił Pan przeciwko wam, aby was wytracił; i wysłuchał mię Pan i tym razem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Na Aarona też rozgniewał się był Pan bardzo, chcąc go zatracić; tedym się też za Aaronem modlił tegoż czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'A grzech wasz, któryście byli uczynili, to jest cielca, porwałem, i spaliłem go ogniem, i skruszyłem go, tłukąc dobrze, aż się w proch obrócił, i wrzuciłem proch jego w potok, który płynął z onej góry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Potem w Tabera i w Massa, w Kibrot Hataawa pobudziliście do gniewu Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'A gdy was Pan wysłał z Kades Barne, mówiąc: Idźcie, a posiądźcie tę ziemię, którąm wam dał, odporniście byli słowu Pana, Boga waszego, aniście mu wierzyli, aniście usłuchali głosu jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Owa odporniście byli Panu od dnia tego, jakom was poznał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Dla tego upadłszy przed Panem, czterdzieści dni i czterdzieści nocy leżałem; bo już był Pan rzekł, że was wytracić miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'I modliłem się Panu, i rzekłem: Panie Boże, nie zatracajże ludu twego, i dziedzictwa twego, któreś odkupił wielmożnością twoją, któreś wywiódł z Egiptu ręką możną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Wspomnij na służebniki twoje, Abrahama, Izaaka, i Jakóba; nie patrz na zatwardziałość ludu tego, i na niezbożność jego, ani na grzech jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'By snać nie rzekli obywatele ziemi tej, z którejś nas wywiódł: Przeto że nie mógł Pan wprowadzić ich do ziemi, którą im obiecał, albo iż je miał w nienawiści, wywiódł je, aby je pobił na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Albowiem oni są ludem twoim, i dziedzictwem twojem, któreś wywiódł w mocy twojej wielkiej, i w ramieniu twojem wyciągnionem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Na on czas rzekł Pan do mnie: Wyciesz sobie dwie tablice kamienne, podobne pierwszym, i wstąp do mnie na górę; uczyń też sobie skrzynię drzewianą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'A napiszę na tablicach onych słowa, które były na tablicach pierwszych, któreś stłukł, a włożysz je do skrzyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Uczyniłem tedy skrzynię z drzewa syttym, i wyciosałem dwie tablice kamienne, podobne pierwszym, i wstąpiłem na górę, mając dwie tablice w rękach swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'I napisał Pan na onych tablicach, tak jako był pierwej napisał, dziesięć słów, które mówił Pan do was na górze z pośrodku ognia w dzień zgromadzenia onego; i dał mi je Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'A obróciwszy się zstąpiłem z góry, i włożyłem one tablice do skrzyni, którąm był uczynił, i były tam, jako mi rozkazał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Tedy synowie Izraelscy ruszyli się od Beerot synów Jahakonowych ku Mesera, gdzie umarł Aaron, i tamże jest pogrzebiony; a odprawował urząd kapłański Eleazar, syn jego, na miejscu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Stamtąd się ruszyli do Gadgad, a z Gadgad do Jotbata, do ziemi ciekących wód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Onegoż czasu odłączył Pan pokolenie Lewi do noszenia skrzyni przymierza Pańskiego, a iżby stawali przed obliczem Pańskiem do usługi jemu, i żeby błogosławili w i mieniu jego aż do dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Dla tego nie miało pokolenie Lewi działu, ani dziedzictwa między bracią swoją; albowiem Pan jest dziedzictwem jego, jako mu powiedział Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'A jam trwał na górze, jako i przedtem, czterdzieści dni i czterdzieści nocy, i wysłuchał mię Pan i onego razu, że cię nie chciał Pan wytracić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Potem rzekł Pan do mnie: wstań, idź wprzód przed ludem tym, że wnijdą, a posiędą ziemię, o którąm przysiągł ojcom ich, że im ją dam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'A teraz, Izraelu, czegoż Pan, Bóg twój, żąda od ciebie? jedno abyś się bał Pana, Boga twego, a chodził we wszystkich drogach jego; abyś go miłował i służył Panu, Bogu twemu, ze wszystkiego serca twego, i ze wszystkiej duszy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Strzegąc przykazań Pańskich i ustaw jego, które ja dziś rozkazuję tobie, abyć się dobrze działo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Oto Pana, Boga twego, są niebiosa, i niebiosa niebios, ziemia i wszystko co na niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Wszakże tylko w ojcach twoich upodobało się Panu, że je umiłował, i obrał nasienie ich po nich, to jest, was, ze wszystkich narodów, jako się to dziś okazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Przetoż obrzeżcie nieobrzezkę serca waszego, i karku waszego nie zatwardzajcie więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Albowiem Pan, Bóg wasz, jest Bogiem bogów, i Panem panów, Bóg wielki, możny, i straszny, który nie ma względu na osoby, ani przyjmuje darów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Który czyni sąd sierocie, i wdowie, a miłuje przychodnia, dawając mu chleb i odzienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Miłujcież tedy i wy przychodnia; boście przychodniami byli w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Pana, Boga twego, będziesz się bał, jemu służył, przy nim trwał, i przez imię jego przysięgał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Onci jest chwałą twoją, i on Bogiem twoim, który uczynił z tobą wielmożne, i straszne rzeczy, które widziały oczy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'W siedmdziesiąt dusz zstąpili ojcowie twoi do Egiptu, a teraz rozmnożył cię Pan, Bóg twój, jako gwiazdy niebieskie, w mnóstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Miłujże tedy Pana, Boga twego, i przestrzegaj obrzędów jego, i ustaw jego, i sądów jego, i przykazań jego, po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'A poznajcie dziś(bo nie mówię do synów waszych, którzy nie znali, ani widzieli karania Pana, Boga waszego); wielmożność jego, rękę jego mocną, i ramię jego wyciągnione;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'I cuda jego, i sprawy jego, które uczynił w pośród Egiptu, Faraonowi, królowi Egipskiemu, i wszystkiej ziemi jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'I co uczynił wojsku Egipskiemu, koniom jego, i wozom jego; który sprawił, że je okryły wody morza czerwonego, gdy was gonili, i wytracił je Pan aż do dnia tego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'Także co wam uczynił na puszczy, ażeście przyszli na to miejsce;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'I co uczynił Datanowi, i Abironowi, synom Elijaba, syna Rubenowego, jako otworzywszy ziemia usta swe, pożarła je, i domy ich, i namioty ich, i wszystkę majętność, która była przy nich, w pośrodku wszystkiego Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'A oczy wasze widziały wszystkie sprawy Pańskie wielkie, które czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Strzeżcież tedy każdego przykazania, które ja przykazuję wam dziś, abyście się zmocnili, a wszedłszy posiedli ziemię, do której idziecie, abyście ją odziedziczyli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'A żebyście dni swoich przedłużyli na ziemi, o którą przysiągł Pan ojcom waszym, że im ją da, i nasieniu ich, ziemię opływającą mlekiem i miodem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Albowiem ziemia, do której ty idziesz, abyś ją posiadł, nie jest jako ziemia Egipska, z którejście wyszli, w której posiawszy nasienie twoje, pokrapiaćeś musiał z pracą nóg twoich, jako ogród jarzyny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Ale ziemia, do której idziecie, abyście ją posiedli, ziemia jest mająca góry i doliny, która dżdżem niebieskim odwilżana bywa:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Ziemia, o której Pan, Bóg twój, pieczą ma, i na którą zawżdy oczy Pana, Boga twego, patrzą od początku roku, i aż do skończenia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'A tak będziecieli pilnie słuchali przykazań moich, które ja dziś przykazuję wam, żebyście miłowali Pana, Boga waszego, i służyli mu ze wszystkiego serca waszego, i ze wszystkiej duszy waszej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'Tedy dam deszcz ziemi waszej czasu swego, ranny i późny, i będziesz zbierał zboża twoje, i wino twoje, i oliwę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Dam też trawę na polach twoich, dla bydła twojego, i będziesz jadł, a najesz się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Strzeżcież się, by snać nie było zwiedzione serce wasze, abyście odstąpiwszy nie służyli bogom cudzym, i nie kłaniali się im;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Skąd by się zapalił gniew Pański przeciwko wam, i zamknąłby nieba, i nie byłoby dżdżu, aniby ziemia wydawała urodzaju swego, i zginęlibyście prędko z ziemi tej wybornej, którą Pan dawa wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Przetoż złóżcie te słowa moje do serca waszego, i do umysłu waszego, a uwiążcie je na znak na rękach waszych, i niech będą jako naczelniki między oczyma waszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'A nauczajcie ich synów waszych, rozmawiając o nich, gdy usiędziesz w domu twym, i gdy będziesz w drodze, i gdy się układziesz, i gdy wstaniesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Napiszesz je też na podwojach domu twego, i na bramach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Aby się rozmnożyły dni wasze, i dni synów waszych na ziemi, o którą przysiągł Pan ojcom waszym, że ją im da, póki niebo nad ziemią trwać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Bo jeźliż z pilnością strzedz będziecie każdego przykazania tego, które ja wam rozkazuję, abyście je czynili, żebyście miłowali Pana, Boga waszego, i chodzili we wszystkich drogach jego, trwając przy nim:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'Tedyć wypędzi Pan one wszystkie narody przed wami, i posiądziecie narody większe, i możniejsze, niżeście wy sami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Wszelkie miejsce, po którem deptać będzie stopa nogi waszej, wasze będzie; od puszczy i Libanu, od rzeki, rzeki Eufrates, aż do morza ostatniego będzie granica wasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Nie ostoi się żaden przed wami; lękanie wasze, i strach wasz puści Pan, Bóg wasz, na oblicze wszystkiej ziemi, którą będziecie deptać, jako wam powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Oto, ja dziś wam przedkładam błogosławieństwo, i przeklęstwo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Błogosławieństwo, będziecieli posłuszni przykazaniu Pana Boga waszego, które ja przykazuję wam dziś;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'A przeklęstwo, jeźli posłuszni nie będziecie przykazaniom Pana Boga waszego, i ustąpicie z drogi, którą ja wam dziś rozkazuję, udawając się za bogami obcymi, których nie znacie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'A gdy cię wprowadzi Pan, Bóg twój, do ziemi, do której idziesz, abyś ją posiadł, tedy dasz błogosławieństwo to na górze Garyzym, a przeklęstwo na górze Hebal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Azaż nie są za Jordanem, za drogą na zachód słońca, w ziemi Chananejczyków, którzy w polach mieszkają, przeciwko Galgal, przy równinie Morech?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Albowiem wy przejdziecie za Jordan, abyście wszedłszy odziedziczyli tę ziemię, którą wam dawa Pan, Bóg wasz, a posiądziecie ją i mieszkać w niej będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'Pilnujcież tedy, abyście czynili wszystkie ustawy i sądy, które ja wam dziś przedkładam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Te są ustawy i sądy, których strzedz będziecie, abyście je czynili w ziemi, którą dawa Pan, Bóg ojców twoich, tobie, żebyście ją dziedzicznie trzymali po wszystkie dni, w których żyć będziecie na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Zburzycie do szczętu wszystkie miejsca, na których służyli narodowie, które wy posiądziecie, bogom swoim, na górach wysokich, i na pagórkach, i pod każdem drzewem zielonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'I porozwalacie ołtarze ich, i połamiecie słupy ich, gaje też ich poświęcone spalicie ogniem, i bałwany bogów ich porąbiecie, a wygładzicie imię ich z miejsca onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Nie uczynicie tak Panu Bogu waszemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Ale miejsca, które obierze Pan, Bóg wasz, ze wszystkich pokoleń waszych, aby tam wystawił imię swoje, i mieszkał na niem, będziecie szukać i do niego się schadzać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Tamże będziecie przynosić całopalenia wasze, i ofiary wasze, i dziesięciny wasze, i ofiary rąk waszych, i śluby wasze, i dobrowolne dary wasze, także pierworodztwa krów waszych, i owiec waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'I tam będziecie jeść przed Panem, Bogiem waszym; i będziecie się weselić we wszystkiem, do czego ściągniecie ręce wasze, wy i domy wasze, w których ci pobłogosławi Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Nie będziecie czynić według tego wszystkiego, jako my tu dziś czynimy, każdy, co mu się zda dobrego w oczach jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Albowiemeście jeszcze nie przyszli do odpocznienia, i do dziedzictwa, które Pan, Bóg twój, dawa tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Ale gdy przeszedłszy za Jordan, mieszkać będziecie w ziemi, którą Pan, Bóg wasz, dawa wam dziedzicznie osieść, i da wam odpoczynek od wszystkich nieprzyjaciół waszych w około, a mieszkać będziecie bezpiecznie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'Tedy na miejsce, które obierze sobie Pan, Bóg wasz, aby tam mieszkało imię jego, tam znosić będziecie wszystko, co ja wam rozkazuję, całopalenia wasze, i ofiary wasze, dziesięciny wasze, i ofiary rąk waszych, i wszystko, co przedniego jest w ślubiech waszych, które ślubować będziecie Panu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'I weselić się będziecie przed Panem, Bogiem waszym, wy, i synowie wasi, i córki wasze, i słudzy wasi, i służebnice wasze, i Lewita, który jest w bramach waszych, ponieważ nie ma działu, ani dziedzictwa z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Strzeżże się, abyś nie ofiarował całopalenia twego na każdem miejscu, gdzie być się zdało:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Ale tylko na miejscu, które by obrał Pan, w któremkolwiek pokoleniu twojem, tam ofiarować będziesz całopalenia twoje, i tam czynić będziesz wszystko, co ja rozkazuję tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'A wszakże, jeźli się upodoba duszy twojej, zabijesz sobie, i będziesz jadł mięso według błogosławieństwa Pana, Boga twego, które da tobie we wszystkich bramach twoich; nieczysty i czysty jeść je będzie, jako sarnę albo jelenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Krwi tylko jeść nie będziecie, na ziemię wylejecie ją, jako wodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Nie będziesz mógł jeść w bramach twoich dziesięciny zboża twego, i wina twego, i oliwy twojej, i pierworodztw krów twoich, i owiec twoich, i wszystkich ślubów twych, które byś ślubował, i dobrowolnych darów twoich, także i ofiary ręki twej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Ale przed Panem, Bogiem twoim, jeść je będziesz na miejscu, które obierze Pan, Bóg twój, ty i syn twój, i córka twoja, i sługa twój, i służebnica twoja, i Lewita, który jest w bramach twoich; i będziesz się weselił przed Panem, Bogiem twoim, we wszystkich rzeczach, do których ściągniesz ręce twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'A strzeż się, abyś snać nie opuszczał Lewity po wszystkie dni twoje w ziemi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Gdy rozszerzy Pan, Bóg twój, granicę twoję, jakoć powiedział, i rzekłbyś: Będę jadł mięso, przeto że pożąda dusza twoja jeść mięsa; według wszystkiej żądności duszy twojej będziesz jadł mięso.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'A jeźliby dalekie było od ciebie miejsce, które obierze Pan, Bóg twój, aby tam przebywało imię jego, tedy zabijesz z wołów twoich, i z owiec twoich, któreć da Pan, jakom ci rozkazał, i będziesz jadł w bramach twoich według wszystkiej żądności duszy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Ale jako jedzą sarnę i jelenia, tak je jeść będziesz; nieczysty i czysty zarówno jeść je będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Tylko bądź statecznym, abyś krwi nie jadał, bo krew jest dusza; przetoż nie będziesz jadł duszy z mięsem jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Nie jedzże jej, na ziemię ją wylej jako wodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Nie jedz jej, aby się dobrze działo tobie, i synom twoim po tobie, gdybyś czynił, co dobrego jest przed oczyma Pańskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Ale poświęcone rzeczy twoje, które będziesz miał, i śluby twoje, weźmiesz i przyniesiesz na miejsce, które obierze Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'I będziesz ofiarował całopalenia twoje, mięso i krew, na ołtarzu Pana, Boga twego; ale krew inszych ofiar twoich wylana będzie na ołtarzu Pana, Boga twego: mięso jednak jeść będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Przestrzegajże, a słuchaj tych wszystkich słów, które ja przykazuję tobie, aby dobrze było tobie, i synom twoim po tobie, aż na wieki, gdy czynić będziesz to, co dobrego i prawego jest przed oczyma Pana, Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Gdy wytraci Pan, Bóg twój, przed obliczem twojem te narody, do których ty wnijdziesz, abyś je posiadł, i opanował je, i mieszkał w ziemi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Strzeżże się, abyś się nie usidlił, idąc za nimi, gdy wytraceni będą przed twarzą twoją; ani się też pytaj na bogi ich, mówiąc: Jako ci narodowie służyli bogom swoim, tak i ja też uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Nie uczynisz tak Panu, Bogu twemu; bo wszystko, czem się brzydzi Pan, i czego nienawidzi, czynili bogom swoim; także też i syny swoje, i córki swoje palili ogniem bogom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Cokolwiek ja wam rozkazuję, tego strzedz będziecie, abyście czynili; nie przydasz nic do tego, ani też ujmiesz z tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Gdyby powstał między wami prorok, albo sny miewający, i ukazałciby znak, albo cud;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'I stałby się on znak albo cud, o którym ci powiedział, a rzekłby: Pójdźmy za bogami obcymi, których ty nie znasz, a służmy im:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Nie usłuchasz słów proroka tego, ani tego, co sny miewa, gdyż was doświadcza Pan, Bóg wasz, aby wiedział, jeśli wy miłujecie Pana, Boga waszego, ze wszystkiego serca waszego, i ze wszystkiej duszy waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Pana, Boga waszego, naśladujcie, i onego się bójcie, a przykazań jego strzegąc, i głosu jego słuchając, służcie mu, i przy nim trwajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Ale prorok on, albo miewający sny, zabity będzie; bo to mówił, czem by was odwiódł od Pana Boga waszego, (który was wywiódł z ziemi Egipskiej, i odkupił cię z domu niewoli), aby cię zraził z drogi, którą przykazał tobie Pan, Bóg twój, żebyś nią chodził; a tak wykorzenisz to złe z pośrodku siebie');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Jeźliby cię też zwodził brat twój, syn matki twojej albo syn twój, albo córka twoja, albo żona łona twego, albo przyjaciel twój, który być był miły, jako dusza twoja, potajemnie mówiąc: Pójdźmy, a służmy bogom obcym, którycheś nie znał ty, ani ojcowie twoi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'Z bogów tych narodów, które około was są, którzy blisko są ciebie, albo daleko od ciebie, od końca ziemi, i aż do końca ziemi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Nie pozwolisz mu, ani go usłuchasz, ani mu folgować będzie oko twoje, ani się zmiłujesz nad nim, ani go utaisz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'Ale koniecznie zabijesz go; ręka twoja najpierwsza nad nim będzie, na zabicie jego, a ręka wszystkiego ludu potem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'I ukamionujesz go aż na śmierć, ponieważ chciał cię odwieść od Pana, Boga twego, który cię wywiódł z ziemi Egipskiej, z domu niewoli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Aby wszystek Izrael usłyszawszy, bał się, a nie czynił więcej nic podobnego rzeczy tej bardzo złej między wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'A jeźlibyś usłyszał, żeby w któremkolwiek mieście twojem, które Pan Bóg twój, dawa tobie ku mieszkaniu, ktokolwiek rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Wyszli niektórzy ludzie przewrotni z pośrodku ciebie, a podwiedli obywatele miasta swego mówiąc: Pójdźmy, a służmy bogom obcym, których nie znacie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Tedy będziesz szukał i dochodził, a pilnie się wywiadował; a jeźli to prawda, a rzecz pewna, że się stała obrzydliwość taka między wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'Koniecznie wytracisz obywatele miasta onego ostrzem miecza, zgładzisz je, i wszystko co w niem, i bydło jego pobijesz ostrzem miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'A wszystkie łupy jego zbierzesz w pośród ulicy jego, i spalisz ogniem jego miasto i z onym wszystkim łupem do szczętu Panu, Bogu twemu; i będzie mogiłą wieczną, a nie będzie budowane więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'I nie zostanie w rękach twoich nic z onych rzeczy przeklętych, aby się odwrócił Pan od gniewu popędliwości swojej, a uczynił z tobą miłosierdzie, i zmiłował się nad tobą, a rozmnożył cię, jako przysiągł ojcom twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Gdy słuchać będziesz głosu Pana, Boga twego, zachowywując wszystkie przykazania jego, które ja dziś przykazuję tobie, żebyś czynił, co prawego jest przed oczyma Pana, Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Synami jesteście Pana, Boga waszego: nie będziecie się rzezać, ani czynić łysiny między oczyma waszemi nad umarłym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Albowiemeś ludem świętym Panu, Bogu twemu, i obrał cię Pan, abyś mu był za lud osobliwy ze wszystkich narodów, którzy są na obliczu ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Nie będziesz jadał żadnej obrzydliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Teć są zwierzęta, które jeść będziecie: Woły, owce, i kozy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Jelenia, i sarnę, i bawołu, i dzikiego kozła, i jednorożca, i łosia, i kózkę skalną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'I wszelkie zwierzę, które ma rozdzielone kopyto, tak że się na dwa kopyta dzieli stopa jego, i które przeżuwa między zwierzęty, jeść je będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'A wszakże z tych, które przeżuwają, i które rozdzielone kopyta mają, jeść nie będziecie, wielbłąda, i zająca, i królika; albowiem chociaż te przeżuwają, ale kopyt rozdwojonych nie mają; nieczyste wam będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Także świnia, choć ma kopyto rozdwojone, ale iż nie przeżuwa, nieczysta wam będzie; mięsa ich jeść nie będziecie, i ścierwu się ich nie dotkniecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'To zaś jeść będziecie ze wszystkich rzeczy, które są w wodach; cokolwiek ma łuskę i skrzele, jeść będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Ale wszystkiego, co nie ma skrzeli, ani łuski, jeść nie będziecie, nieczyste wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Wszystko ptastwo czyste jeść będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Te zasię są, których jeść nie będziecie: Orła, i gryfa, i morskiego orła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'I sokoła, i sępa, i kani wedle rodzaju jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'Ani żadnego kruka wedle rodzaju jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'Ani strusia, ani sowy, ani wodnej kani, ani krogulca według rodzaju jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'I raroga, i lelka, i łabędzia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'I pelikana, i porfiryjona, i nurka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Ani bociana ani sójki według rodzaju ich, ani dudka ani nietoperza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Wszelki też płaz skrzydlasty nieczysty wam będzie, jeść go nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Każdego ptaka czystego jeść będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Nie będziecie jeść żadnej zdechliny; przychodniowi, który jest w bramach twoich, dasz to, a jeść to będzie, albo sprzedasz cudzoziemcowi; boś ty lud święty Panu, Bogu twemu, nie będziesz warzył koźlęcia w mleku matki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Ochotnie będziesz dawał dziesięciny ze wszystkiego urodzaju nasienia twego, co się urodzi na polu na każdy rok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'A będziesz pożywał przed Panem, Bogiem twoim, na miejscu, które obierze, żeby tam mieszkało imię jego, dziesięcin zboża twego, z wina twego, i z oliwy twojej, i z pierworodztwa wołów twoich, i z owiec twoich, abyś się uczył bać Pana, Boga twego, po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'A jeźliby daleka była droga na cię, żebyś tego tam donieść nie mógł, przeto, że odległe jest tobie ono miejsce, które by obrał Pan, Bóg twój, ku mieszkaniu tam imieniowi swemu, gdyć błogosławić będzie Pan, Bóg twój;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'Tedy to spieniężysz, a mając zawiązane pieniądze w rękach twoich, pójdziesz na miejsce, które sobie obierze Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'I za one pieniądze nakupisz wszystkiego, co się upodoba duszy twojej, wołów i owiec, i wina, i innego napoju mocnego, i wszystkiego, czego by pożądała dusza twoja, a będziesz tam jadł przed Panem, Bogiem twoim, i będziesz się weselił, ty i dom twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'A Lewity, który mieszka w bramach twoich, nie opuścisz go, ponieważ nie ma działu, ani dziedzictwa z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'A po wyjściu każdego trzeciego roku odłączysz wszystkie dziesięciny urodzaju twego onegoż roku, i złożysz je w bramach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Tedy przyjdzie Lewita, który nie ma działu i dziedzictwa z tobą, i przychodzień, i sierota, i wdowa, którzy są w bramach twoich, i będą jeść, i najedzą się, abyć błogosławił Pan, Bóg twój, w każdej sprawie rąk twoich, którą czynić będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Na początku każdego siódmego roku czynić będziesz odpuszczenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'A toć jest sposób odpuszczania, żeby odpuścił każdy, który pożyczył z ręki swej, to, czego pożyczył bliźniemu swemu; nie będzie wyciągał długu od bliźniego swego, i od brata swego, ponieważ obwołane jest odpuszczenie Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Od obcego wyciągać dług możesz: ale cobyś miał u brata twego, odpuści mu ręka twoja:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Dla tego, żeby się nie stał między wami kto przez cię ubogim, ponieważ hojnie błogosławić tobie będzie Pan w ziemi, którą Pan, Bóg twój, dawa tobie w dziedzictwo, abyś ją posiadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Tylko żebyś słuchając posłuszny był głosowi Pana, Boga twego, abyś strzegł, i czynił każde przykazanie to, które ja przykazuję tobie dzisiaj,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Albowiem Pan, Bóg twój, błogosławić cię będzie, jakoć obiecał; i będziesz pożyczał wielu narodom, a sam u nikogo nie będziesz pożyczał; i będziesz panował nad wielą narodów, a one nad tobą panować nie będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Gdyby był u ciebie ubogi ktokolwiek z braci twojej w któremkolwiek mieście twojem, w ziemi twojej, którą Pan, Bóg twój, dawa tobie, nie zatwardzaj serca swego, ani zawieraj ręki twej przed bratem twoim ubogim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Ale szczodrze otworzysz mu rękę twoję, i ochotnie pożyczysz mu, ile będzie potrzebował i czego by mu niedostawało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Strzeż się, aby nie była jaka niepobożność w sercu twojem, żebyś miał rzec: Nadchodzi rok on siódmy, rok odpuszczenia, i surowo byś się stawił bratu twemu ubogiemu, tak, żebyś mu nie użyczył, a on by wołał przeciwko tobie do Pana, i miałbyś grzech;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Ale ochotnie dawać mu będziesz, i nie będzie niechętne serce twoje, gdy mu dawać będziesz, albowiem dla tegoć pobłogosławi Pan, Bóg twój, we wszystkich sprawach twoich, i do czegokolwiek ściągniesz rękę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Boć się nie przebierze ubogich w ziemi waszej; dla tegoć rozkazuję, mówiąc: abyś szczodrze otwierał rękę twą bratu twemu, i nędznemu twemu, i ubogiemu twemu w ziemi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Jeźliby się zaprzedał tobie brat twój, Żydowin albo Żydówka, a służyłciby przez sześć lat, tedy siódmego roku wypuścisz go wolno od siebie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'A gdy go wolno puścisz od siebie, nie puścisz go próżnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Szczodrze go udarujesz z bydła twego, i z gumna twego, i z prasy twojej; z tego, w czem ci pobłogosławił Pan, Bóg twój, dasz mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'I wspomnisz sobie, żeś był niewolnikiem w ziemi Egipskiej, skąd cię wykupił Pan, Bóg twój; dla tego ja to dziś tobie przykazuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Jeźliby też rzekł do ciebie: Nie pójdę od ciebie, przeto iż cię umiłował, i dom twój, a iż się ma dobrze u ciebie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'Tedy wziąwszy szydło, przekolesz ucho jego na drzwiach, i będzie sługą twoim na wieki; toż i służebnicy swej uczynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Niech to nie będzie przykro w oczach twoich, że go puścisz wolno od siebie; bo dwojaką zapłatę najemnika zasłużył u ciebie przez sześć lat; i błogosławić będzie tobie Pan, Bóg twój, we wszystkiem, co będziesz czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Wszystkiego pierworodztwa, które się urodzi z bydła twego, albo z trzody twojej, samce, poświęcisz Panu, Bogu twemu; nie będziesz robił pierworodnym krowy twojej, ani będziesz strzygł pierworodnych owiec twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Przed Panem, Bogiem twoim, będziesz je jadł każdego roku, na miejscu, które obierze Pan, ty i dom twój,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'A jeźliby na niem była wada, żeby chrome, albo ślepe, albo z jakąkolwiek wadą złą było, nie będziesz go ofiarował Panu, Bogu twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'W bramach twych jeść je będziesz, nieczysty i czysty zarówno, jako sarnę i jako jelenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Tylko krwi jego nie będziesz jadł; na ziemię wylejesz ją, jako wodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Przestrzegaj miesiąca Abib, abyś weń obchodził święto przejścia Panu, Bogu twemu, ponieważ miesiąca Abiba wywiódł cię Pan, Bóg twój, z Egiptu w nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'A będziesz ofiarował ofiarę świętą przejścia Panu, Bogu twemu, z owiec i z wołów, na miejscu, które obierze Pan, aby tam mieszkało imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Nie będziesz z nimi jadł kwaszonego; przez siedem dni jeść będziesz z nimi przaśniki, chleb utrapienia, (boś z kwapieniem wyszedł z ziemi Egipskiej), abyś pamiętał dzień wyjścia twego z ziemi Egipskiej po wszystkie dni żywota twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'A nie pokaże się u ciebie kwas we wszystkich granicach twoich przez siedem dni, i nie zostanie nic przez noc z mięsa, które byś ofiarował w wieczór pierwszego dnia, aż do poranku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Nie będziesz mógł ofiarować ofiary święta przejścia w któremkolwiek mieście twojem, z onych, które Pan, Bóg twój, dawa tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Ale na miejscu, które obierze Pan, Bóg twój, aby tam mieszkało imię jego, ofiarować będziesz ofiarę świętą przejścia w wieczór przy zajściu słońca, w ten czas, któregoś wyszedł z Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'To upieczesz i jeść będziesz na miejscu, które obierze Pan, Bóg twój; potem wrócisz się rano, i pójdziesz do namiotów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Przez sześć dni będziesz jadł przaśniki, ale w dzień siódmy święto uroczyste będzie Pana, Boga twego; nie będziesz czynił weń żadnej roboty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Siedem też tygodni odliczysz sobie; gdy zapuścisz sierp w zboże twoje, poczniesz liczyć siedem tygodni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'A potem będziesz obchodził święto tygodni Panu, Bogu twemu; z dostatku ręki twej dobrowolnie dasz według tego, jako cię ubłogosławił Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'A będziesz się weselił przed Panem, Bogiem twoim, ty i syn twój, i córka twoja, i sługa twój, i służebnica twoja, i Lewita, który jest w bramach twoich, i przychodzień, i sierota, i wdowa, którzy będą w pośrodku ciebie, na miejscu, które obierze Pan, Bóg twój, aby tam mieszkało imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'A będziesz wspominał, żeś był niewolnikiem w Egipcie; przetoż strzedz i czynić będziesz te ustawy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Przytem święto kuczek obchodzić będziesz przez siedem dni, gdy zbierzesz pożytki z bojewiska twego, i z prasy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'I będziesz się weselił w święto uroczyste twoje, ty, i syn twój, i córka twoja, i sługa twój, i służebnica twoja, i Lewita, i przychodzień, i sierota, i wdowa, którzy będą w bramach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Przez siedem dni będziesz obchodził święto uroczyste Panu, Bogu twemu, na miejscu, które obierze Pan, gdyć błogosławić będzie Pan, Bóg twój, we wszystkich urodzajach twoich, i we wszelkiej pracy rąk twoich; a tak będziesz wesół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Trzy kroć do roku ukaże się każdy mężczyzna twój przed Panem, Bogiem twoim, na miejscu, które obierze, w święto przaśników, i w święto tygodni, i w święto kuczek, a nie ukaże się nikt przed Panem próżny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Każdy ukaże się z darem ręki swojej według błogosławieństwa Pana, Boga twego, które on da tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Sędzie i urzędniki postanowisz sobie we wszystkich bramach twoich, które Pan, Bóg twój, da tobie w każdem pokoleniu twojem, aby sądzili lud sądem sprawiedliwym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Nie będziesz podwracał sądu, ani będziesz miał względu na osobę, i daru brać nie będziesz; albowiem dar zaślepia oczy mądrych, a podwraca słowa sprawiedliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Sprawiedliwości, sprawiedliwości naśladować będziesz, abyś żył, i posiadł ziemię, którą Pan, Bóg twój, dawa tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Nie sadź sobie gaju z żadnego drzewa przy ołtarzu Pana, Boga twego, który sobie zbudujesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Ani sobie wystawiaj słupa, gdyż to ma w nienawiści Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Nie będziesz ofiarował Panu, Bogu twemu, wołu, ani bydlęcia, na którem by była skaza, albo jakakolwiek wada, gdyż to jest obrzydliwością Panu, Bogu twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Jeźliby się znalazł między wami w któremkolwiek mieście twem, które Pan, Bóg twój, dawa tobie, mąż albo niewiasta, któryby się czego złego dopuścił przed oczyma Pana, Boga twego, przestępując przymierze jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'A poszedłszy, służyłby obcym bogom, i kłaniałby się im, albo słońcu, albo miesiącowi, albo wszystkim zastępom niebieskim, czegom nie przykazał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'I oznajmionoć by to, a usłyszawszy, wywiadowałbyś się pilno, a oto, byłaby prawda, i rzecz pewna, że się stała ta obrzydliwość w Izraelu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'Tedy wywiedziesz onego męża, albo onę niewiastę, którzy uczynili tę złą rzecz, do bram twoich, męża onego, albo niewiastę, i ukamionujesz je, a pomrą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'W uściech dwóch świadków, albo trzech świadków zabity będzie, kto umrzeć ma; niech nie umiera na słowo świadka jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Ręka świadków będzie na nim najpierwsza, na zabicie jego, a ręka wszystkiego ludu potem; a tak odejmiesz złe z pośrodku siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Byłoliby też co trudnego przy sądzie, między krwią a krwią, między sprawą a sprawą, i między raną a raną, i około poswarków w bramach twoich, tedy wstaniesz, a pójdziesz na miejsce, które obierze Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'I przyjdziesz do kapłanów Lewitów, i do sędziego, który będzie na on czas, i będziesz ich pytał, a oznajmiąć, jako to osądzić masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'I uczynisz według tego, jakoć powiedzą z miejsca tego, które obrał Pan, i postąpisz sobie według wszystkiego, jako cię nauczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Według słów zakonu, którego cię nauczą, i według sądu, któryć powiedzą, sprawować się będziesz; nie ustąpisz od słowa, któreć powiedzą, ani na prawo ani na lewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'A jeźliby kto uczynił to z hardości, żeby nie chciał usłuchać kapłana tam postanowionego ku służbie przed Panem, Bogiem twoim, albo sędziego, niech umrze on mąż; i odejmiesz to złe z Izraela,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Aby wszystek lud usłyszawszy bał się, a więcej hardzie sobie nie poczynał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Gdy wnijdziesz do ziemi, którą Pan, Bóg twój, dawa tobie, a opanujesz ją, i będziesz mieszkał w niej, i rzeczesz: Postanowię nad sobą króla, jako i wszystkie narody okoliczne:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'Tego tylko postanowisz nad sobą króla, którego obierze Pan, Bóg twój; z pośrodku braci twej postanowisz nad sobą króla; nie będziesz mógł przełożyć nad sobą cudzoziemca, któryby nie był bratem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Tylko niech nie chowa wiele koni, ani nawraca ludu do Egiptu, aby wiele koni nabył, ponieważ wam Pan rzekł: Nie wracajcie się zaś tą drogą więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Nie będzie też miał wiele żon, aby się nie odwróciło serce jego; srebra też i złota niech nazbyt wiele nie nabywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'A gdy usiędzie na stolicy królestwa swego, przepisze sobie ten powtórzony zakon w księgi od kapłanów Lewitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'A będzie go miał przy sobie a będzie go czytał po wszystkie dni żywota swego, aby się uczył bać Pana, Boga swego, i przestrzegał wszystkich słów zakonu tego, i ustaw tych, a czynił je;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Aby się nie wynosiło serce jego nad bracią jego, i żeby się nie unosiło od tego przykazania na prawo, ani na lewo, aby długo żył na królestwie swojem, on i synowie jego w pośrodku Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Nie będą mieli kapłani Lewitowie, i wszystko pokolenie Lewi, działu, ani dziedzictwa z innym Izraelem: ogniste ofiary Pańskie i dziedzictwo jego jeść będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'A dziedzictwa nie będą mieli między bracią swoją; Pan jest dziedzictwem ich, jako im powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'A toć będzie prawo należące kapłanom od ludu, od ofiarujących ofiarę, bądź wołu, bądź owcę; tedy oddadzą kapłanowi łopatkę, i czeluści i kałdun.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Pierwociny zboża twego, wina twego, i oliwy twojej, także pierwociny wełny z owiec twoich oddasz mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Albowiem obrał go Pan, Bóg twój, ze wszystkich pokoleń twoich, aby stał ku usłudze w imieniu Pańskiem, on i synowie jego, po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'A gdyby przyszedł Lewita z któregokolwiek miasta twego, z całego Izraela, gdzie przemieszkiwa, a przyszedłby z całej chęci duszy swej na miejsce, które sobie obrał Pan:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Tedy służyć będzie w imieniu Pana, Boga swego, jako wszyscy bracia jego Lewitowie, którzy tam stoją przed oblicznością Pańską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'Część równą z drugimi jeść będą, oprócz tego, co im należało z dóbr ojców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Gdy tedy wnijdziesz do ziemi, którą dawa Pan, Bóg twój, tobie, nie ucz się czynić według obrzydliwości tych narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Niech się między wami nie znajduje, któryby przewodził syna swego, albo córkę swoję przez ogień; także wieszczek, guślarz, i wróżek, i czarownik.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'I czarnoksiężnik, i ten, który ma sprawę z duchy złymi, i praktykarz, i wywiadujący się czego od umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Albowiem jest obrzydliwością Panu każdy, któryby to czynił; bo dla tych obrzydliwości Pan, Bóg twój, wyrzuca te narody przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Doskonałym będziesz przed Panem, Bogiem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Albowiem narodowie ci, które ty opanujesz, wieszczków i guślarzy słuchają; ale tobie nie dopuszcza tego Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Proroka z pośrodku ciebie, z braci twej, jakom ja jest, wzbudzi tobie Pan, Bóg twój; onego słuchać będziecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Według tego wszystkiego, jakoś żądał od Pana, Boga twego, na górze Horeb, w dzień zgromadzenia, mówiąc: Niech więcej nie słucham głosu Pana, Boga mego, i na ogień ten wielki niech nie patrzę więcej, bym nie umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Przetoż rzekł Pan do mnie: Dobrze mówili, co mówili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Proroka im wzbudzę z pośrodku braci ich, jakoś ty jest, i włożę słowa moje w usta jego, i opowiadać im będzie wszystko, cokolwiek mu rozkażę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'I stanie się, że ktobykolwiek nie był posłuszny słowom moim, które on mówić będzie w imię moje, Ja tego szukać będę na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Wszakże prorok, któryby sobie hardzie począł, mówiąc słowo w imieniu mojem, któregom mu mówić nie rozkazał i któryby mówił w imię bogów obcych, niech umrze prorok takowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'A jeźlibyś rzekł w sercu swem: Jakoż rozeznamy to słowo, którego nie mówił Pan?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Jeźliby co mówił on prorok w imię Pańskie, a nie stałoby się to, ani wypełniło, onoć to jest słowo, którego nie mówił Pan; z hardości to mówił prorok on, nie bójże się go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Gdy wytraci Pan, Bóg twój, narody, których ziemię Pan, Bóg twój, dawa tobie, a posiędziesz ją, i mieszkać będziesz w miastach ich, i w domach ich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Trzy miasta odłączysz sobie w pośród ziemi twojej, którą Pan, Bóg twój dawa tobie w osiadłość;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Wyprostujesz sobie drogę, i rozdzielisz na trzy części granice ziemi twojej, którąć w dziedzictwo poda Pan, Bóg twój, żeby tam uciekał każdy mężobójca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'A toć będzie prawo mężobójcy, który tam uciecze, aby żyw został, gdyby zabił bliźniego swego z nieobaczenia, a nie miałby go przedtem w nienawiści;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Jako gdyby kto szedł z bliźnim swym do lasu drwa rąbać, a zaniósłby się ręką swą z siekierą, aby uciął drzewo, a spadłaby siekiera z toporzyska, i trafiłaby bliźniego jego, żeby umarł, ten uciecze do jednego z tych miast, aby żyw został;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'By snać nie gonił powinny zabitego mężobójcę onego, gdyby się rozpaliło serce jego, a dogoniwszy go na dalekiej drodze, nie zabił go, choćby nie był winien śmierci, ponieważ go nie miał w nienawiści przedtem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Przetoż ja przykazuję tobie, mówiąc: Trzy miasta odłączysz sobie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'A gdy rozszerzy Pan, Bóg twój, granice twoje, jako przysiągł ojcom twoim, i dać wszystkę ziemię, którą zaślubił dać ojcom twoim:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'Jeźliże będziesz strzegł wszystkich tych przykazań, i czynił je, które ja dziś rozkazuję tobie, żebyś miłował Pana, Boga twego, i chdził drogami jego po wszystkie dni, tedy przydasz sobie jeszcze trzy miasta do onych trzech miast.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Aby nie była wylewana krew niewinna w pośrodku ziemi twojej, którą Pan, Bóg twój, dawa tobie w dziedzictwo, aby nie została na tobie krew.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Ale jeźliby kto mając w nienawiści bliźniego swego, a zasadziwszy się nań, powstałby przeciw jemu, i uderzyłby go śmiertelnie, ażby umarł, a uciekł do jednego z tych miast:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'Tedy poślą starsi miasta onego, i porwą go stamtąd, i wydadzą go w ręce powinnemu zabitego, i umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Nie sfolguje mu oko twoje; ale odejmiesz krew niewinną z Izraela, abyć się dobrze działo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Nie będziesz przenosił granicy bliźniego twego, którą założyli przodkowie w dziedzictwie twojem, które osiędziesz w ziemi, którą Pan, Bóg twój dawa tobie w osiadłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Nie powstanie świadek jeden przeciwko człowiekowi w jakiejkolwiek nieprawości, albo w jakimkolwiek grzechu ze wszystkich grzechów, któremi by kto zgrzeszył; w uściech dwóch świadków, albo w uściech trzech świadków stanie każde słowo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Jeźliby powstał świadek kłamliwy przeciw komu, świadcząc przeciw niemu, że odstąpił od Boga:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'Tedy staną oni dwaj mężowie, którzy mają spór, przed Panem, przed kapłany, i przed sędziami, którzy będą na ten czas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'I będą się pilnie wywiadowali sędziowie; a obacząli, że świadek on jest świadkiem fałszywym, kłamstwo powiadając na brata swego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'Uczynicie mu, jako on myślił uczynić bratu swemu; i odejmiesz złe z pośrodku siebie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Aby drudzy usłyszawszy to, ulękli się, i nie dopuszczali się więcej takowej złości czynić w pośród ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'A nie sfolguje oko twoje; gardło za gardło, oko za oko, ząb za ząb, ręka za rękę, noga za nogę będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Gdy się ruszysz na wojnę przeciw nieprzyjaciołom twoim, a obaczysz konie, i wozy, i lud większy nad cię, nie bój się ich; bo Pan, Bóg twój, z tobą jest, który cię wywiódł z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'A gdy się przybliżać będziecie ku potykaniu, wystąpi kapłan, i przemówi do ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'A rzecze do nich: Słuchaj Izraelu, wy dziś staczacie bitwę z nieprzyjacioły waszymi; niechajże nie słabieje serce wasze, nie bójcie się i nie trwożcie sobą, ani się ich lękajcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Albowiem Pan, Bóg wasz, idzie z wami, aby walczył za was z nieprzyjacioły waszymi, a iżby was wybawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Także mówić będą hetmani do ludu, i rzeką: Jeźliż kto jest, co zbudował dom nowy, a w nim nie począł mieszkać, niech idzie, a wróci się do domu swego, by snać nie zginął w bitwie, a kto inny począłby w nim mieszkać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Albo jeźli kto jest, co nasadził winnicę, a nie używał owocu z niej, niech idzie, a wróci się do domu swego, by snać nie zginął w bitwie, a kto inny używałby z niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Albo jeźli kto jest, co ma poślubioną żonę, a jeszcze jej nie pojął, niech idzie, a wróci się do domu swego, by snać nie zginął w bitwie, a kto inny nie pojął jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Nadto hetmani mówić będą do ludu, i rzeką: Jeźli kto jest bojaźliwy, a lękliwego serca, niech idzie, a wróci się do domu swego, aby nie psował serca braci swej, jako jest zepsowane serce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'A gdy przestaną hetmani mówić do ludu, tedy postawią rotmistrze wojsk przed ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Gdy przyciągniesz do jakiego miasta, abyś go dobywał, poczęstujesz je pokojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'A jeźliże pokój ofiarowany przyjmie, i otworzyć bramy, tedy wszystek lud znaleziony w niem będzie hołdował i służył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Ale jeźli nie uczyni pokoju z tobą, lecz podniesie przeciw tobie wojnę, oblężesz je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'A gdy je da Pan, Bóg twój, w rękę twoję, tedy zabijesz w niem każdego mężczyznę ostrzem miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Tylko niewiasty, i dziatki, i bydła, i wszystko, co będzie w mieście, wszystek łup jego obrócisz sobie w korzyść, i będziesz jadł łupy nieprzyjaciół twoich, które da Pan, Bóg twój, tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tak uczynisz wszystkim miastom, daleko odległym od ciebie, które nie są z miast tych narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Ale z miast narodów tych, które Pan, Bóg twój, podawa tobie w dziedzictwo, żadnej duszy żywić nie będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Lecz do szczętu wytracisz je, Hetejczyka, Amorejczyka, Chananejczyka, i Ferezejczyka, Hewejczyka, i Jebuzejczyka, jakoć rozkazał Pan, Bóg twój;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'Przeto żeby nie uczyli was czynić według wszystkich obrzydliwości swoich, które czynili bogom swym, i zgrzeszylibyście przeciw Panu, Bogu waszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Gdy oblężesz jakie miasto, a przez wiele dni dobywać go będziesz, abyś je wziął, nie psuj drzewa jego, wycinając je siekierą, bo z niego jeść będziesz; przetoż go nie wycinaj, (bo azaż są ludźmi drzewa polne?) abyś ich używał do oblężenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Tylko drzewa, które obaczysz, że owocu nie rodzą, te psować będziesz i wycinać: i budować będziesz baszty przeciwko onemu miastu, które z tobą walczy, póki go nie opanujesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Jeźliby znaleziony był zabity w ziemi, którą Pan, Bóg twój, dawa tobie, abyś ją posiadł, leżący na polu, a nie wiedziano by, kto go zabił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'Tedy wynijdą starsi twoi, i sędziowie twoi, i rozmierzą ziemię aż do miast, które są w około onego zabitego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'A które by miasto bliższe było onego zabitego, tedy wezmą starsi miasta onego jałowicę z stada, którą jeszcze nie robiono, a która nie ciągnęła w jarzmie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'I zawiodą starsi tego miasta onę jałowicę w dolinę kamienistą, gdzie nigdy nie orano, ani siano, i utną tam szyję jałowicy w onej dolinie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Zatem przyjdą kapłani, synowie Lewiego; bo je obrał Pan, Bóg twój, aby mu służyli, i żeby błogosławili w imieniu Pańskiem, a według uznania ich kończyć się ma każdy spór, i każda rana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Także wszyscy starsi miasta onego, które jest najbliższe zabitego, umyją ręce swoje nad jałowicą ściętą w dolinie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'I oświadczą się, mówiąc: Ręce nasze nie wylały tej krwi, ani oczy nasze na to patrzały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Oczyść lud twój Izraelski, któryś odkupił, Panie, a nie poczytaj krwi niewinnej w pośrodku ludu twego Izraelskiego. Tedy oczyszczeni będą od onej krwi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'A ty odejmiesz krew niewinną z pośrodku siebie, gdy uczynisz, co prawego jest przed oczyma Pańskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Gdy też wynijdziesz na wojnę przeciw nieprzyjaciołom twoim, a podać je Pan, Bóg twój, w ręce twoje, i nabierzesz z nich więźniów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'A obaczysz między więźniami niewiastę nadobną, której rozmiłowawszy się, wziąłbyś ją sobie za żonę:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'Tedy ją wprowadzisz do domu swego; i ogoli głowę swoję, i obrzeże paznogcie swoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'A złożywszy z siebie szatę, w której jest pojmana, zostanie w domu twym, a płakać będzie ojca swego, i matki swojej przez cały miesiąc: a potem wnijdziesz do niej, i będziesz mężem jej, a ona będzie tobie za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'A jeźlibyć się potem nie podobała, tedy ją wolno puścisz, a żadną miarą nie sprzedasz jej za pieniądze, ani nią kupczyć będziesz, ponieważeś ją zelżył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Gdyby też kto miał dwie żony, jednę miłą, a drugą omierzłą, i narodziłyby mu synów, miła i omierzła, a byłby syn pierworodny omierzłej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'Tedy gdy stanowić będzie za dziedzice syny swoje, dóbr swoich: nie będzie mógł dać pierworodztwa synowi miłej przed synem pierworodnym onej omierzłej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Ale pirworodztwo synowi omierzłej przyzna, dawszy mu dwojaką część wszystkiego, co ma; ponieważ on jest początkiem siły jego, jego jest prawo pierworodztwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Jeźliby kto miał syna swawolnego, i krnąbrnego, któryby nie słuchał głosu ojca swego, i głosu matki swojej, a będąc strofowany, nie usłuchałby ich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'Tedy go wezmą ojciec jego i matka jego, i przywiodą go do starszych miasta swego, i do bramy sądowej miejsca onego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'I rzeką do starszych miasta onego: Ten nasz syn jest swawolny i krnąbrny, nieposłuszny głosu naszemu, żarłok jest i pijanica;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Tedy ukamionują go wszyscy ludzie miasta onego, i umrze; a tak odejmiesz złe z pośrodku siebie, co gdy wszystek Izrael usłyszy, bać się będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'A gdyby kto popełnił grzech godny śmierci, a byłby skazany na śmierć, a obwiesiłbyś go na drzewie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'Nie zostanie przez noc trup jego na drzewie, ale koniecznie pochowasz go tegoż dnia; bo przeklęstwem Bożem jest ten, co wisi. Przetoż nie będziesz plugawił ziemi twojej, którą Pan, Bóg twój, dawa tobie w dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Jeźlibyś ujrzał wołu brata twego, albo owcę jego obłąkaną, nie mijajże ich, ale je koniecznie odprowadź do brata twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Choćciby nie był blisko brat twój, anibyś go znał, przecię zapędzisz je do domu swego, i będzie przy tobie, ażby tego szukał brat twój, i wrócisz mu je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Toż uczynisz osłowi jego; toż też uczynisz szacie jego; toż też uczynisz wszelakiej rzeczy zgubionej brata twego, która by mu zginęła, jeźlibyś ją znalazł, nie mijajże jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Jeźlibyś ujrzał osła brata twego, albo wołu jego, że upadł na drodze, nie mijajże ich, ale go zaraz z nim podnieś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Niech nie bierze niewiasta na się szat męskich, ani niech się nie obłóczy mąż w szatę niewieścią; albowiem jest obrzydliwością Panu, Bogu twemu, kto by to czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Gdybyś trafił gniazdo ptasze przed sobą w drodze, na jakiemkolwiek drzewie, albo na ziemi, a w niem ptaszęta albo jajka, a matka by siedziała na ptaszętach albo na jajkach, nie bierzże macierzy z dziećmi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Ale wolno puściwszy matkę, dzieci weźmiesz sobie, abyć się dobrze działo, i żebyś przedłużył dni twoich');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Gdy też zbudujesz dom nowy, tedy uczynisz blanki po kraju dachu twego, abyś nie przywiódł krwi na dom twój, gdyby kto spadł z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Nie posiewaj winnicy twojej, różnem nasieniem, byś snać nie splugawił pożytku nasienia, któreś siał, i urodzaju winnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Nie będziesz orał wołem i osłem pospołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Nie obleczesz szaty utkanej z wełny i ze lnu pospołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Poczynisz sobie sznurki na czterech rogach szaty twojej, którą się odziewać będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Gdyby kto pojął żonę, a wszedłszy do niej, miałby ją w nienawiści;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'A dałby przyczynę, aby mówiono o niej, i wprowadziłby na nię złą sławę, mówiąc; Pojąłem tę żonę, a wszedłszy do niej, nie znalazłem jej panną:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Tedy weźmie ojciec dzieweczki, i matka jej, i przyniosą znaki panieństwa dzieweczki onej do starszych miasta onego do bramy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'I rzecze ojciec onej dzieweczki do starszych: Córkę swoję dałem mężowi temu za żonę; a on ją ma w nienawiści;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'A oto sam dał przyczynę, aby mówiono o niej, powiadając: Nie znalazłem przy córce twojej panieństwa: ale oto są znaki panieństwa córki mojej. Tedy rozwiną ono prześcieradło przed starszymi miasta onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'A wziąwszy starsi miasta onego męża skarzą go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'I wezmą z niego winę sto srebrników, które oddadzą ojcu onej dzieweczki, przeto, że puścił złą sławę o pannie Izraelskiej, i będzie ją miał za żonę, i nie będzie jej mógł opuścić po wszystkie dni swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Ale byłoliby prawdziwe to obwinienie jej, a nie znalazłyby się znaki panieństwa przy onej dzieweczce;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'Tedy wywiodą onę dzieweczkę przed drzwi domu ojca jej, i ukamionują ją ludzie miasta onego, i umrze: bo uczyniła hańbę w Izraelu, popełniwszy nierząd w domu ojca swego; tak odejmiesz złe z pośród siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Jeźliby kto znalezion był, obcujący z niewiastą, mającą męża, tedy niech umrą oboje, mąż, który obcował z cudzą żoną, i ona niewiasta; tak odejmiesz złe z Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Byłaliby dzieweczka panna poślubiona mężowi, a trafiłby ją kto w mieście, i obcowałby z nią;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'Tedy wywiódłszy ono oboje przed bramę miasta, ukamionujecie je, i umrą; dzieweczkę przeto, iż nie wołała w mieście, a męża przeto, iż zelżył żonę bliźniego swego: tak odejmiesz złe z pośrodku siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'A jeźliby na polu trafił mąż dzieweczkę poślubioną a porwawszy ją, zgwałciłby ją, tedy umrze mąż, który obcował z nią, sam tylko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Ale dzieweczce nic nie uczynisz; dzieweczka nie jest winna śmierci; bo jako gdyby kto powstawszy przeciwko bliźniemu swemu, zamordował go, taka to sprawa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Ponieważ ją na polu trafił, a gdy wołała dzieweczka poślubiona, nie był, kto by ją ratował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Gdyby też kto, trafiwszy dzieweczkę pannę, która nie jest za mąż zmówioną, porwał ją, i leżałby z nią, a zastano by je:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'Tedy da on mąż, który obcował z nią, ojcu dzieweczki pięćdziesiąt srebrników, i będzie mu za żonę, przeto że ją zelżył, ani jej będzie mógł opuścić po wszystkie dni swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Nie pojmie nikt żony ojca swego, i nie odkryje podołka ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Nie wnijdzie wypukły, ani trzebieniec do zgromadzenia Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Ani wnijdzie niepoczciwego łoża syn do zgromadzenia Pańskiego, i dziesiąte pokolenie jego nie wnijdzie do zgromadzenia Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Nie wnijdzie też Ammonita, i Moabczyk do zgromadzenia Pańskiego, ani dziesiąte pokolenie ich nie wnijdzie do zgromadzenia Pańskiego, aż na wieki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Dla tego, że wam nie zabieżeli z chlebem, ani z wodą w drodze, gdyście szli z Egiptu, a że najęli za zapłatę przeciw tobie Balaama, syna Beorowego, z Pethor Mesopotamii Syryjskiej, aby cię przeklinał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Acz nie chciał Pan, Bóg twój, wysłuchać Balaama, ale obrócił Pan, Bóg twój, tobie jego przeklęstwo w błogosławieństwo; bo cię umiłował Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Nie szukaj pokoju ich, ani dobrego ich, po wszystkie dni twoje na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Nie będziesz się brzydził Idumejczykiem, bo bratem twoim jest; nie będziesz się brzydził Egipczykiem, boś był przychodniem w ziemi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Synowie, którzy się im zrodzą w trzeciem pokoleniu, wnijdą do zgromadzenia Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Gdy się ruszysz z wojskiem naprzeciwko nieprzyjaciołom twoim, strzeż się od wszelkiej złej rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Jeźliby był między wami kto, coby był nieczystym z przygody nocnej, wynijdzie za obóz, a nie wróci się do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'A ku wieczorowi omyje się wodą, a po zajściu słońca wnijdzie do obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Będziecie też mieli miejsce za obozem, gdzie będziecie wychodzili na potrzebę przyrodzoną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'I będziesz miał rydlik między naczyniem swojem; a gdybyś chciał usiąść dla potrzeby, wykopiesz nim dołek, a obróciwszy się, zagrzebiesz plugastwo twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Albowiem Pan, Bóg twój, chodzi w pośrodku obozu twego, aby cię wyrwał, i podał ci nieprzyjacioły twoje; przetoż niech będzie obóz twój święty, aby nie widział przy tobie sprosności jakiej, dla której by się odwrócił od ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Nie wydasz sługi panu jego, któryby się uciekł do ciebie od pana swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Z tobą będzie mieszkał w pośrodku ciebie, na miejscu, które sobie obierze w jednem z miast twoich, gdzieby mu się podobało; nie uczynisz mu gwałtu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Nie będzie nierządnica z córek Izraelskich, ani będzie nierządnik z synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Nie wnoś zapłaty nierządnicy, ani zapłaty psa w dom Pana, Boga twego, za jakikolwiek ślub; bo obrzydliwością u Pana, Boga twego, jest to oboje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Nie dasz na lichwę bratu twemu, ani pieniędzy, ani żywności, ani jakiejkolwiek rzeczy, którą dawają na lichwę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Cudzoziemcowi na lichwę dawać możesz; ale bratu twemu na lichwę nie dasz, abyć błogosławił Pan, Bóg twój, w każdej sprawie, do której ściągniesz rękę twoję w ziemi, do której wnijdziesz, abyś ją posiadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Jeźlibyś ślubował ślub Panu, Bogu twemu, nie omieszkiwajże oddawać go; bo koniecznie upomni się go Pan, Bóg twój, od ciebie, a będzie na tobie grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'A jeźli nie będziesz ślubował, nie będzie na tobie grzechu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'To co wynijdzie z ust twoich, wypełnisz, i uczynisz, jakoś ślubował Panu, Bogu twemu, dobrowolnie, coś wymówił usty twemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Gdy wnijdziesz do winnicy bliźniego twego, jedz jagody, ileć się podoba, aż do sytości; ale do naczynia twego nie bierz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Także gdy wnijdziesz między zboże bliźniego twego, tedy narwiesz kłosów ręką twą; ale sierpa nie zapuszczaj w zboże bliźniego twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Gdyby pojął kto żonę, a stałby się jej małżonkiem, a przydałoby się, żeby nie znalazła łaski w oczach jego, przeto, że znalazł przy niej co sprośnego, tedy jej napisze list rozwodny i da w rękę jej, a puści ją z domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'A gdyby wyszła z domu jego, a odszedłszy szłaby za drugiego męża;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'A mając ją w nienawiści on mąż drugi, napisałby jej list rozwodny, i dałby w rękę jej i puściłby ją z domu swego; albo jeźliby też umarł on mąż drugi, który ją był pojął sobie za żonę:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'Nie będzie mógł mąż jej pierwszy, który ją był opuścił, znowu jej pojąć, aby mu była żoną, gdyż jest splugawiona; albowiem obrzydliwością to jest przed obliczem Pańskiem. Przetoż nie dopuszczaj grzeszyć ziemi, którą Pan, Bóg twój, dawa tobie w dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Gdyby się kto świeżo ożenił, nie wynijdzie na wojnę, ani nań włożona będzie jaka praca; wolen będzie w domu swym przez cały rok weseląc się z żoną swoją, którą pojął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Nikt nie weźmie w zastawie zwierzchniego i spodniego kamienia młyńskiego; bo takowy jakoby duszę brał w zastawie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Jeźliby kto był znalezion, coby ukradł człowieka z braci swej, synów Izraelskich, a handlowałby nim, i sprzedał go, tedy umrze on złodziej, i odejmiesz złe z pośrodku siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Strzeż się zarazy trądu, a przestrzegaj pilnie, żebyś czynił wszystko, czego was nauczą kapłani Lewitowie; jakom im rozkazał, przestrzegać tego, i czynić to będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Pamiętaj co uczynił Pan, Bóg twój, Maryi w drodze, gdyście wyszli z Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Gdy pożyczysz czego bliźniemu twemu, nie wchodźże do domu jego, abyś wziął co w zastawie od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Ale na dworze zostaniesz, a człowiek, któremuś pożyczył, wyniesie do ciebie zastaw przed dom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'A jeźliby on człowiek był ubogi, nie układziesz się z zastawem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Bez omieszkania wrócisz mu on zastaw, gdy słońce zajdzie, żeby leżał na odzieniu swem, i błogosławił ci; a będzieć to sprawiedliwością przed Panem, Bogiem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Nie uczynisz krzywdy najemnikowi ubogiemu, i potrzebnemu z braci twojej, albo z cudzoziemców twoich, którzy są w ziemi twej, w bramach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Tegoż dnia dasz mu zapłatę jego przed zajściem słońca, albowiem ubogi jest, a z tego żywi duszę swoję; żeby nie wołał przeciwko tobie do Pana, a zostałby na tobie grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Nie umrą ojcowie za syny, a synowie nie umrą za ojce; każdy za grzech swój umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Nie wywrócisz sądu przychodniowi, ani sierocie, ani weźmiesz w zastawie szaty wdowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Ale pamiętaj, żeś niewolnikiem był w Egipcie, a iż cię wybawił Pan, Bóg twój, stamtąd; dla tegoż ja przykazuję tobie, abyś to czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Gdybyś żął zboże twoje na roli twojej, a zapamiętałbyś snopa na polu, nie wracaj się, abyś go wziął; przychodniowi, sieroci, i wdowie to będzie, abyć błogosławił Pan, Bóg twój, w każdej sprawie rąk twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Gdy będziesz obierał oliwki twoje, nie oglądajże się na każdą gałązkę za sobą; przychodniowi, sierocie, i wdowie to będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Gdy będziesz obierał winnicę twoję, nie zbierajże gron pozostałych za tobą; przychodniowi, sierocie, i wdowie to będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'A pamiętaj, iżeś był niewolnikiem w ziemi Egipskiej; przetoż ja tobie przykazuję, abyś to czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Jeźliby się spór wszczął między stronami, a przyszliby do sądu, aby je sądzono: tedy usprawiedliwią sprawiedliwego, a niezbożnego osądzą za niezbożnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'A jeźli godzien będzie bicia niepobożny, tedy każe go położyć sędzia, i każe go bić przed sobą według miary nieprawości jego, pod liczbą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Czterdzieści kroć uderzy go; więcej nie przyda, by snać, jeźliby mu nad to zadano więcej plag, nie znikczemniał brat twój przed oczyma twemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Nie zawiążesz gęby wołowi młócącemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Gdyby mieszkali bracia pospołu, a zszedłby jeden z nich, nie mając syna, nie pójdzie żona onego zmarłego za męża obcego, brat jego wnijdzie do niej, a pojmie ją sobie za żonę, a prawem powinowactwa przyłączy ją sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'A pierworodny syn, którego by porodziła, nazwany będzie imieniem brata jego zmarłego, aby nie było wygładzone imię jego z Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'A jeźliby nie chciał on mąż pojąć bratowej swojej, tedy pójdzie bratowa jego do bramy przed starsze, i rzecze: Nie chce brat męża mego wzbudzić bratu swemu imienia w Izraelu, i nie chce mię prawem powinowactwa sobie przyłączyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Tedy go przyzowią starsi miasta onego, i będą mówić z nim; a stanąwszy, jeźli rzecze: Nie chcę jej pojąć,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'Przystąpi bratowa jego do niego przed oczyma starszych, a zzuje trzewik jego z nogi jego, i plunie na twarz jego, a odpowiadając rzecze: Tak się stanie mężowi, któryby nie budował domu brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'I nazywać będą imię jego w Izraela: Dom wyzutego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Gdyby się powadzili z sobą dwaj jacy mężowie, a przybieżałaby żona jednego, aby wyrwała męża swego z ręki onego, co go bije, a ściągnąwszy rękę swą, uchwyciłaby go za łono jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'Utniesz jej rękę, i nie zlituje się nad nią oko twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Nie będziesz miał w worku twoim różnych gwichtów, większego i mniejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Nie będziesz też miał w domu twoim dwojakiego korca, większego i mniejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Wagę słuszną i sprawiedliwą mieć będziesz; także korzec słuszny i sprawiedliwy mieć będziesz, aby się przedłużyły dni twoje na ziemi, którą Pan, Bóg twój, dawa tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Albowiem obrzydliwością jest Panu, Bogu twemu, każdy, który to czyni, wszelki czyniący nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Pomnij na to, coć uczynił Amalek w drodze, kiedyście szli z Egiptu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Jakoć zabieżał drogę, a pobił ostatnie wojska twego, wszystkie mdłe, idące za tobą, gdyś ty był utrudzony i spracowany, a nie bał się Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Przetoż, gdyć da odpocznienie Pan, Bóg twój, od wszystkich nieprzyjaciół twoich w około, w ziemi, którą Pan, Bóg twój dawa tobie w dziedzictwo, abyś ją posiadł, wygładzisz pamiątkę Amalekowę pod niebem. Nie zapominajże tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Gdy wnijdziesz do ziemi, którą Pan, Bóg twój, dawa tobie w dziedzictwo, a osiędziesz ją, i mieszkać w niej będziesz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'Tedy weźmiesz pierwociny ze wszystkich owoców ziemi, które ofiarować będziesz z ziemi twojej, którą Pan, Bóg twój, dawa tobie, i włożysz je w kosz, a pójdziesz na miejsce, które by obrał Pan, Bóg twój, aby tam mieszkało imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'A przyszedłszy do kapłana, który na ten czas będzie, rzeczesz do niego: Wyznawam dziś Panu, Bogu twemu, żem wszedł do ziemi, o którą przysiągł Pan ojcom naszym, że ją nam dać miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Tedy wziąwszy kapłan kosz z ręki twojej, postawi go przed ołtarzem Pana, Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Tamże odpowiesz, i rzeczesz przed obliczem Pana, Boga twego: Ojciec mój był ubogi Syryjczyk, i zstąpił do Egiptu a pielgrzymował tam w maluczkim poczcie, i stał się tam w naród wielki, możny, i obfity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'A gdy się z nami źle obchodzili Egipczanie, trapiąc nas, i kładąc na nas niewolą ciężką,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Tedyśmy wołali do Pana, Boga ojców naszych, i wysłuchał Pan głos nasz, a wejrzał na utrapienie nasze, i na pracę naszę, i na ucisk nasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'I wywiódł nas Pan z Egiptu ręką możną, i ramieniem wyciągnionem, i w strachu wielkim, i w znakach, i w cudach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'I przyprowadził nas na to miejsce, a podał nam tę ziemię, ziemię opływającą mlekiem i miodem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'A teraz oto przyniosłem pierwociny z owoców ziemi, którąś mi dał, o Panie! i zostawisz ono przed Panem, Bogiem twoim, i pokłonisz się przed Panem, Bogiem twoim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'I będziesz się weselił ze wszystkich dóbr, któreć dał Pan, Bóg twój, i domowi twemu, ty i Lewita, i przychodzień, który jest w pośrodku ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'A gdy z pełna oddasz dziesięcinę wszystkich dziesięcin urodzajów twoich roku trzeciego, który jest rokiem dziesięcin, a dasz Lewicie, przychodniowi, sierocie, i wdowie, i będą jedli w bramach twoich, i najedzą się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'Tedy rzeczesz przed obliczem Pana, Boga twego: Wyniosłem co jest poświęcone z domu swego, i dałem też z tego Lewicie, i przychodniowi, sierocie i wdowie, według wszelkiego przykazania twego, któreś mi przykazał; nie przestąpiłem przykazania twego, anim go zapominał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Nie jadłem w smętku moim z niego, anim odjął z niego na pospolite używanie, anim też dał z niego na pogrzeb; byłem posłuszny głosowi Pana, Boga mego, uczyniłem wszystko, coś mi przykazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Spojrzyjże z mieszkania świętego twojego z nieba, a błogosław ludowi twemu Izraelskiemu i ziemi, którąś nam dał, jakoś przysiągł ojcom naszym, ziemi opływającej mlekiem i miodem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Dziś Pan, Bóg twój, rozkazuje tobie, abyś zachował te ustawy i sądy; przestrzegajże tedy, a czyń je ze wszystkiego serca twego, i ze wszystkiej duszy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Przy Panuś się dziś opowiedział, abyć był za Boga, i żebyś chodził drogami jego, i strzegł ustaw jego, i przykazań jego, i sądów jego, i żebyś posłuszny był głosowi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Pan się też dziś opowiedział przy tobie, abyś mu był za lud osobliwy, jako mówił do ciebie, i żebyś strzegł wszystkich przykazań jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'I żeby cię wywyższył nad wszystkie narody, które uczynił w chwale i w sławie, i w zacności, a żebyś był ludem świętym Panu, Bogu twemu, jako mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Tedy przykazał Mojżesz i starsi Izraelscy ludowi, mówiąc: Strzeżcie wszelkiego przykazania, które ja wam dziś przykazuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'I stanie się, że którego dnia przejdziecie przez Jordan do ziemi, którąć Pan, Bóg twój, dawa, wystawisz sobie kamienie wielkie, i potynkujesz je wapnem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'I napiszesz na nich wszystkie słowa zakonu tego, skoro przejdziesz, abyś wszedł do ziemi, którą Pan, Bóg twój, dawa tobie, do ziemi opływającej mlekiem i miodem, jakoć obiecał Pan, Bóg ojców twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Gdy tedy przejdziecie przez Jordan, wystawicie te kamienie, o których ja wam dziś rozkazuję, na górze Hebal, i potynkujesz je wapnem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Tamże zbudujesz ołtarz Panu, Bogu twemu, ołtarz z kamienia; nie będziesz ich ciosał żelazem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Z kamienia całego zbudujesz ołtarz Pana, Boga swego, i ofiarować będziesz na nim całopalenia Panu, Bogu twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Także ofiarować będziesz ofiary spokojne, i będziesz tam jadł, a będziesz się weselił przed obliczem Pana, Boga twego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'I napiszesz na onych kamieniach wszystkie słowa zakonu tego znacznie i jaśnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'I rzekł Mojżesz i kapłani Lewitowie do wszystkiego Izraela mówiąc: Pilnuj a słuchaj, Izraelu! dziś stałeś się ludem Pana, Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Przetoż będziesz posłusznym głosowi Pana, Boga twego, a będziesz czynił przykazania jego, i ustawy jego, które ja dziś przykazuję tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Tedy przykazał Mojżesz ludowi dnia onego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Ci staną, aby błogosławili ludowi na górze Garyzym, gdy przejdziecie przez Jordan: Symeon, i Lewi, i Juda, i Isaschar, i Józef, i Benjamin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Ci zaś staną ku przeklinaniu na górze Hebal: Ruben, Gad, i Aser, i Zabulon, Dan, i Neftali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'I oświadczą się Lewitowie, a mówić będą do wszystkich mężów Izraelskich głosem wyniosłym:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Przeklęty człowiek, któryby czynił obraz ryty, albo odlewany, obrzydliwość Pańską, robotę rąk rzemieślniczych, choćby to postawił na miejscu skrytem; tedy odpowie wszystek lud, i rzecze: Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Przeklęty, kto lekceważy ojca swego, i matkę swoję; i rzecze wszystek lud Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Przeklęty, który przenosi granicę bliźniego swego; a rzecze wszystek lud Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Przeklęty, który zwodzi ślepego z drogi, aby błądził; i rzecze wszystek lud Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Przeklęty, który wywraca sprawiedliwość przychodniowi; sierocie, i wdowie; a rzecze wszystek lud Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Przeklęty, kto by obcował z żoną ojca swego, bo odkrył podołek ojca swego; i rzecze wszystek lud Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Przeklęty, któryby obcował z jakiemkolwiek bydlęciem; i rzecze wszystek lud Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Przeklęty, któryby obcował z siostrą swoją, córka ojca swego albo córką matki swojej; i rzecze wszystek lud Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Przeklęty, któryby obcował z świekrą swoją; i rzecze wszystek lud Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Przeklęty, któryby zabił tajemnie bliźniego swego; i rzecze wszystek lud Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Przeklęty, któryby brał dary, aby zabił człowieka, krew niewinną; i rzecze wszystek lud Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Przeklęty, kto by nie został przy słowach zakonu tego, aby je czynił; i rzecze wszystek lud Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Jeźli pilnie słuchać będziesz głosu Pana, Boga twego, strzegąc i czyniąc wszystkie przykazania jego, które ja dziś przykazuję tobie, tedy cię Pan, Bóg twój, wywyższy nad wszystkie narody ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'I przyjdą na cię te wszystkie błogosławieństwa, i trzymać się ciebie będą, jeźli będziesz posłusznym głosu Pana, Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Błogosławiony będziesz w mieście, błogosławiony będziesz i na polu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Błogosławiony owoc żywota twego, i owoc ziemi twojej, i owoc bydła twego, płód rogatego bydła twego, i trzody drobnego bydła twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Błogosławiony kosz twój, i dzieża twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Błogosławiony będziesz wchodząc, błogosławiony i wychodząc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Sprawi Pan, że nieprzyjaciele twoi, którzy powstawają przeciwko tobie, będą porażeni przed obliczem twojem; drogą jedną wyciągną przeciwko tobie, a siedmią dróg uciekać będą przed obliczem twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Przykaże Pan błogosławieństwu swemu, aby z tobą było w szpiżarniach twoich, i we wszystkiem, do czego byś ściągnął rękę twoję, i będzieć błogosławił w ziemi, którą Pan, Bóg twój dawa tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Wystawi cię Pan sobie za lud święty, jakoć przysiągł, jeźli przestrzegać będziesz przykazań Pana, Boga twego, i będziesz chodził drogami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'I obaczą wszystkie narody ziemi, że imię Pańskie wzywane jest nad tobą, a będą się ciebie lękać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'I sprawi Pan, że będziesz obfitował w dobrem, w owocu żywota twego, i w owocu bydła twego, i w owocu pola twego, w ziemi, o którą przysiągł Pan ojcom twoim, że ją tobie da.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Otworzyć Pan skarb swój wyborny, niebiosa, aby wydawały deszcz ziemi twojej czasu swego, i pobłogosławi wszelkiej sprawie rąk twoich, i będziesz pożyczał wielom narodom, a sam nie będziesz pożyczał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'I uczyni cię Pan przedniejszym, a nie pośledniejszym; i będziesz tylko wyższy, a nie będziesz niższy, jeźli posłusznym będziesz przykazaniom Pana, Boga twego, które ja dziś rozkazuję tobie, abyś ich strzegł, i czynił je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'A nie ustąpisz od żadnego słowa, które ja wam przykazuję dzisiaj, ani na prawo ani na lewo, idąc za bogami cudzymi, abyś im służył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Lecz jeźli posłuszny nie będziesz głosu Pana, Boga twego, abyś strzegł i czynił wszystkie przykazania jego i ustawy jego, które ja przykazuję tobie dziś, tedy przyjdą na cię wszystkie te przeklęstwa, i ogarną cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Przeklętym będziesz w mieście, przeklętym i na polu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Przeklęty kosz twój, i dzieża twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Przeklęty owoc żywota twego, i owoc ziemi twojej, płód rogatego bydła twego, i trzody drobnego bydła twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Przeklętym będziesz wchodząc, przeklętym i wychodząc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'I pośle Pan na cię przeklęstwo, trwogę, i zgubę we wszystkiem, do czego ściągniesz rękę twoję, i co czynić będziesz; aż cię wygładzi, i aż zaginiesz nagle dla złości spraw twoich, któremiś mię odstąpił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Przepuści Pan na cię morowe powietrze, aż cię wyniszczy z ziemi, do której idziesz, abyś ją posiadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Uderzy cię Pan suchotami, i zimnicą, i gorączką, i upaleniem, i mieczem, i suszą, i rdzą, i będą cię doganiać, aż wyginiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'I będzie niebo twoje, które jest nad głową twoją, miedzianem, i ziemia, która jest pod tobą, żelazną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Da Pan za deszcz ziemi twojej proch i popiół, a ten z nieba padać będzie na cię, aż zniszczejesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Poda cię Pan na upadek przed nieprzyjacioły twymi; drogą jedną wynijdziesz przeciwko nim, a siedmią dróg będziesz uciekał przed twarzą ich, i będziesz ku wzruszeniu wszystkim królestwom ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'A będą trupy twoje pokarmem wszelkiemu ptastwu powietrznemu, i zwierzowi ziemskiemu, a nie będzie, kto by ich odpędził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Zarazi cię Pan wrzodem Egipskim, i niemocą zadnicy, i krostami, i świerzbem, a nie będziesz mógł być uleczony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Zarazi cię Pan szaleństwem, i ślepotą, i zdrętwiałością serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'I będziesz macał o południu, jako maca ślepy w ciemności; a nie będąć się szczęściły drogi twoje; do tego też będziesz uciśniony, i szarpany po wszystkie dni, a nie będzie, kto by cię wybawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Żonę sobie poślubisz, a inszy mąż z nią będzie spał; dom zbudujesz a mieszkać w nim nie będziesz; winnicę nasadzisz, a używać jej nie będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Wołu twego zabiją przed oczyma twemi, a nie będziesz go jadł; osła twego porwą przed twarzą twoją, a nie wrócąć go; trzody twoje podane będą nieprzyjaciołom twoim, a nie będzie, kto by cię ratował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Synowie twoi, córki twoje, narodowi innemu wydane będą, a oczy twoje patrząc na to ustawać będą dla nich przez cały dzień, a nie będzie siły w ręce twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Owoc ziemi twojej, i wszystkę pracę twoję pożre naród, którego ty nie znasz, a nie będziesz jedno uciśniony, i udręczony po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'I będziesz jako szalony, widząc to oczyma twemi, na co patrzeć musisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Zarazi cię Pan wrzodem złym na kolanach i na łystach, tak, że nie będziesz mógł być uleczonym, od stopy nogi twojej i aż do wierzchu głowy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Zawiedzie Pan ciebie, i króla twego, którego postanowisz nad sobą, do narodu, któregoś nie znał, ty i ojcowie twoi, gdzie będziesz służył bogom obcym, drewnu i kamieniowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'I będziesz dziwowiskiem, baśnią, i przysłowiem u wszystkich narodów, do których cię zawiedzie Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Nasienia wiele wyniesiesz na pole, a mało zbierzesz; bo to pożre szarańcza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Winnicę nasadzisz i uprawisz, ale wina nie będziesz pił ani zbierał; bo je pożre robactwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Oliwnego drzewa dosyć mieć będziesz po wszystkich granicach twoich, a oliwą mazać się nie będziesz; bo opadają oliwki twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Synów i córek napłodzisz, ale nie będą twoje; bo pójdą w niewolą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Wszystkie drzewa twoje, i owoc ziemi, szarańcza pożre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Cudzoziemiec, który mieszka w pośrodku ciebie, urośnie nad cię znacznie; ale ty wielce poniżonym będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'On będzie pożyczał tobie, a ty mu nie będziesz pożyczał, on będzie przedniejszy, a ty będziesz pośledniejszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'I przyjdą na cię wszystkie te przeklęstwa, i będą cię goniły i ogarną cię, aż zniszczejesz, ponieważeś nie był posłuszny głosowi Pana, Boga twego, aniś chował przykazania jego, i ustaw jego, któreć przykazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'A będą te plagi na tobie i na nasieniu twem, za znak i za cud aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Dla tego, żeś nie służył Panu, Bogu twemu, z uciechą, i z weselem serca, mając wszystkiego dostatek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'I będziesz nieprzyjaciołom twoim, które na cię Pan pośle, służył w głodzie, i w pragnieniu, i w nagości, i w niedostatku wszystkiego; i włoży jarzmo żelazne na szyję twoję, aż cię wniwecz obróci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Przywiedzie Pan na cię naród z daleka, od kończyn ziemi, który przyleci jako orzeł, naród, którego języka nie zrozumiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Naród srogi, który nie będzie miał względu na starego ani się nad dziecięciem zmiłuje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'I pożre owoc bydła twego, i owoc ziemi twojej, aż cię zniszczy; i nie zostawić zboża, moszczu, ani świeżej oliwy, ani stad wołów twoich, ani trzód owiec twoich, aż cię wygubi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'I oblęże cię we wszystkich bramach twoich, aż upadną mury twe wysokie i obronne, w którycheś ty ufał po wszystkiej ziemi twojej; oblęże cię we wszystkich bramach twoich, po wszystkiej ziemi twojej, którą da Pan, Bóg twój tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'I będziesz jadł płód żywota twego, ciało synów twoich, i córek twoich, któreć dał Pan, Bóg twój, w onem oblężeniu i ściśnieniu, którem cię ściśnie nieprzyjaciel twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Mąż pieszczotliwy między wami, i w rozkoszy wychowany, będzie zajrzał bratu swemu, i własnej żonie swej, i ostatkowi synów swych, który pozostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'I nie udzieli żadnemu z nich z mięsa synów swych, które jeść będzie, przeto że mu nie zostało nic inszego w oblężeniu i ściśnieniu, którem cię ściśnie nieprzyjaciel twój we wszystkich bramach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Pieszczotliwa między wami, i w rozkoszy wychowana niewiasta, która ledwie nogą swoją dostępowała ziemi dla pieszczoty i rozkoszy, będzie zajrzała mężowi swemu własnemu i synowi swemu, i córce swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'I łożyska swego, które wychodzi z niej przy porodzeniu, i synów swych, które urodzi; bo je poje w niedostatku wszystkiego potajemnie w oblężeniu i ściśnieniu, którem cię ściśnie nieprzyjaciel twój w bramach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Jeźliże nie będziesz przestrzegał, abyś czynił wszystkie słowa zakonu tego, które napisane są w księgach tych, żebyś się bał tego imienia chwalebnego i strasznego Pana, Boga twego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'Rozmnoży na podziw Pan plagi twoje, i plagi nasienia twego, plagi wielkie i trwałe, także choroby złe i długie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'I obróci na cię wszystkie choroby Egipskie, którycheś się lękał, i chwycą się ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Wszelaką też niemoc, i wszelaką plagę, która nie jest napisana w księgach zakonu tego, przywiedzie Pan na cię, aż cię wytraci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'I zostanie was bardzo mało, którzyście przedtem byli jako gwiazdy niebieskie przez mnóstwo, ponieważeś nie był posłuszny głosowi Pana, Boga twego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'I stanie się, że jako się radował Pan nad wami, dobrze wam czyniąc i rozmnażając was, tak się radować będzie Pan nad wami tracąc was, i wygładzając was; i będziecie wykorzenieni z ziemi, do której idziecie, abyście ją posiedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'I rozproszy cię Pan między wszystkie narody, od kończyn ziemi i aż do kończyn ziemi; tamże służyć będziesz bogom cudzym, którycheś nie znał, ty i ojcowie twoi, drewnu i kamieniowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'A między onymi narodami nie wytchniesz sobie, ani będzie miała odpoczynku stopa nogi twojej, dać też Pan tamże serce lękliwe, i oczy zemdlone, i myśl sfrasowaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'I będzie żywot twój jakoby zawieszony przed tobą, i będziesz się lękał w nocy i we dnie, i nie będziesz pewien żywota twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Rano rzeczesz: Któż mi da wieczór? a w wieczór rzeczesz: Któż mi da zaranie? dla trwogi serca twego, którą się zatrwożysz, i dla tego, na co oczyma twemi patrzeć musisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'I wróci cię Pan do Egiptu w okrętach, drogą, o którejmci powiedział: Nie oglądasz jej więcej; a tam zaprzedawać się będziecie nieprzyjaciołom swoim za niewolniki, i za niewolnice, a nie będzie kto by was kupił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Teć są słowa przymierza, które przykazał Pan Mojżeszowi postanowić z synami Izraelskimi w ziemi Moabskiej nad ono przymierze, które postanowił z nimi na Horeb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Zwołał tedy Mojżesz wszystkiego Izraela, i mówił do nich: Wyście widzieli wszystko, co czynił Pan przed oczyma waszemi w ziemi Egipskiej Faraonowi, i wszystkim sługom jego, i całej ziemi jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Pokusy wielkie, które widziały oczy twoje, znaki, i cuda one wielkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Ale nie dał wam Pan serca ku zrozumieniu, i oczu ku widzeniu, ani uszu ku słyszeniu, aż do dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'I prowadziłem was przez czterdzieści lat po puszczy; nie wiotszały szaty wasze na was, i obuwie wasze nie wiotszało na nogach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Chlebaście nie jedli, i wina, i mocnego napoju nie piliście, abyście wiedzieli żem Ja Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'A gdyście przyszli na to miejsce, wyciągnął Sehon, król Heseboński, i Og, król Basański, przeciwko nam ku bitwie, i poraziliśmy je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'A wziąwszy ziemię ich, podaliśmy ją w dziedzictwo Rubenitom, i Gadytom, i połowie pokolenia Manasesowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'A tak przestrzegajcież słów przymierza tego, i czyńcie je, aby się wam szczęśliwie powodziło, wszystko, co czynić będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Wy stoicie dziś wszyscy przed Panem, Bogiem waszym, książęta wasze w pokoleniach waszych, starsi wasi, i przełożeni wasi, wszyscy mężowie Izraelscy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Dziatki wasze, żony wasze, i przychodzień twój, który mieszka w pośrodku obozu twego, od tego, który drwa rąbie, aż do tego, co wodę czerpie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Abyś wszedł w przymierze Pana, Boga twego, i w przysięgę jego, którą Pan, Bóg twój, stanowi z tobą dziś;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Aby cię sobie dziś wystawił za lud, a sam żeby tobie był za Boga, jakoć powiedział, i jako przysiągł ojcom twoim Abrahamowi, Izaakowi i Jakóbowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'A nie tylko z wami samymi ja stanowię to przymierze, i tę przysięgę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Ale z każdym, który tu stoi dziś z nami przed Panem, Bogiem naszym, i z każdym, którego tu nie masz z nami dziś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Wy bowiem wiecie, jakośmy mieszkali w ziemi Egipskiej, i jakośmy przeszli przez pośrodek narodów, któreście przeszli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'I widzieliście obrzydliwości ich, i bałwany ich, drewno i kamień, srebro i złoto, które są przy nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Niechże nie będzie między wami mąż, albo niewiasta, albo dom, albo pokolenie, którego by się dziś serce odwróciło od Pana, Boga naszego, żeby szedł, a służył bogom narodów onych, by snać nie był między wami jaki korzeń, wydawający żółć i piołun;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Bo kto by słuchał słów przeklęstwa tego, a błogosławiłby sobie w sercu swem, mówiąc: Pokój mi będzie, chociaż według zdania serca mego chodzić będę, przydawając pijaną do upragnionej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Ale Pan nie chce odpuścić takowemu; lecz zaraz zapali się gniew Pański, a zapalczywość jego przeciwko mężowi temu, i przypadnie nań wszystko przeklęstwo, które jest napisane w tych księgach, i wygładzi Pan imię jego pod niebem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'I wyłączy go Pan na złe jego ze wszystkich pokoleń Izraelskich, według każdego przeklęstwa przymierza napisanego w księgach zakonu tego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Tak, że rzecze naród potomny, synowie wasi, którzy powstaną po was, i cudzoziemiec, który przyjdzie z ziemi dalekiej (gdy obaczą plagi ziemi tej, i niemoce jej, któremi ją zarazi Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Bo siarka i sól wypali tę wszystkę ziemię, że nie będzie osiewana, ani też rodzić będzie, i nie zrośnie na niej żadna trawa, na kształt podwrócenia Sodomy i Gomorry, Adamy i Seboim, które podwrócił Pan w gniewie swym, i w popędliwości swej.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Tak rzeką wszyscy narodowie: Przeczże tak Pan uczynił tej ziemi? cóż to za gniew tej wielkiej zapalczywości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'I odpowiedzą: Przeto, że opuścili przymierze Pana, Boga ojców swych, które postanowił z nimi, gdy je wywiódł z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Albowiem poszli, a służyli bogom cudzym, i kłaniali się im; bogom, których oni nie znali, i którzy im nic nie udzielili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Przetoż zapalił się Pan gniewem przeciwko tej ziemi, aby przywiódł na nie wszelkie przeklęstwo napisane w tych księgach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'I wykorzenił je Pan z ziemi ich w gniewie i w zapalczywości, a w popędliwości wielkiej, i wyrzucił je do ziemi obcej, jako dziś widzicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Rzeczy tajemne należą Panu, Bogu naszemu, a jawne nam i synom naszym aż na wieki, abyśmy czynili wszystkie słowa zakonu tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Gdy tedy przyjdą na cię wszystkie te rzeczy, błogosławieństwo, i przeklęstwo, którem przełożył przed oczy twoje, a wspomnisz sobie w sercu twem między wszystkimi narody, do których cię wypędzi Pan, Bóg twój;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'I nawrócisz się do Pana, Boga twego, a będziesz posłuszny głosowi jego we wszystkiem, co ja rozkazuję tobie dziś, ty, i synowie twoi, ze wszystkiego serca twego, i ze wszystkiej duszy twojej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'Tedy cię wywiedzie Pan, Bóg twój, z więzienia twego, i zmiłuje się nad tobą, a przywróci i zgromadzi cię ze wszystkich narodów, do których cię rozproszył Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'By też kto z twoich wygnany był i na kraj świata, stamtąd zgromadzi cię Pan, Bóg twój, i stamtąd zbierze cię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'A przyprowadzi cię Pan, Bóg twój, do ziemi, którą odziedziczyli ojcowie twoi, i osiędziesz ją, i będzieć dobrze czynił, i rozmnoży cię nad przodki twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'I obrzeże Pan, Bóg twój, serce twoje, i serce nasienia twego, abyś miłował Pana, Boga twego, ze wszystkiego serca twego, i ze wszystkiej duszy twojej, abyś mógł żyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'I obróci Pan, Bóg twój, wszystkie te przeklęstwa na nieprzyjacioły twoje, i na te, którzy cię nienawidzili, i którzy cię prześladowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'A ty nawróciwszy się posłuszny będziesz głosowi Pańskiemu, i czynić będziesz wszystkie przykazania jego, które ja tobie dziś rozkazuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'I poszczęścić Pan, Bóg twój, w każdej sprawie rąk twoich, w owocu żywota twego, i w owocu bydła twego, i w owocu ziemi twej, ku dobremu; albowiem obróci się Pan, aby się cieszył z ciebie, czyniąc ci dobrze, jako się cieszył z ojców twoich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'Będzieszli posłusznym głosowi Pana, Boga twego, przestrzegając przykazań jego, i ustaw jego, napisanych w księgach zakonu tego, nawracając się do Pana, Boga twego, ze wszystkiego serca twego, i ze wszystkiej duszy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Albowiem przykazanie, które ja przykazuję tobie dziś, nie jest przed tobą zakryte, ani daleko odległe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Nie jest w niebie, żebyś rzekł: Któż nam wstąpi do nieba, a wziąwszy je, przyniesie do nas, i opowie je nam, abyśmy je pełnili?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Ani też jest za morzem, żebyś rzekł: Któż nam popłynie za morze, a wziąwszy je przyniesie, i opowie je nam, abyśmy je pełnili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Ale bardzo blisko ciebie jest to słowo, w uściech twoich i w sercu twojem, abyś je czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Otom położył przed oczy twoje dziś żywot i dobre, także śmierć i złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Albowiem ja rozkazuję tobie dziś, abyś miłował Pana, Boga twego, i chodził drogami jego, i przestrzegał przykazań jego, i ustaw jego, i sądów jego, abyś żył, i rozmnożył się, i żebyć błogosławił Pan, Bóg twój, w ziemi, do której idziesz, abyś ją posiadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Jeźli się zaś odwróci serce twoje, a nie usłuchasz, ale dawszy się zwieść, będziesz się kłaniał bogom obcym, i będziesz im służył:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Opowiadam wam dziś, że pewnie poginiecie, ani przedłużycie dni na ziemi, do której się przeprawiasz przez Jordan, abyście tam wszedłszy, posiedli ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Oświadczam się dziś przeciwko wam, niebem i ziemią, żem żywot i śmierć przedłożył przed oczyma twemi, błogosławieństwo, i przeklęstwo; przetoż obierz żywot, abyś żył, ty i nasienie twoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'A miłował Pana, Boga twego, i posłuszny był głosowi jego, i przy nim trwał; albowiem on jest żywotem twoim, i przedłużeniem dni twoich, żebyś mieszkał na ziemi, o którą przysiągł Pan ojcom twoim, Abrahamowi, Izaakowi, i Jakóbowi, iż im ją dać miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Przyszedłszy tedy Mojżesz, opowiedział te słowa wszystkiemu Izraelowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'I rzekł do nich: Sto i dwadzieścia lat jest mi dziś; nie mogę więcej wychodzić i wchodzić; a też mi Pan powiedział: Nie przejdziesz za ten Jordan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Pan, Bóg twój sam pójdzie przed tobą; on wytraci narody te przed tobą, i posiędziesz je: Jozue, ten pójdzie przed tobą, jako powiedział Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'I uczyni im Pan, jako uczynił Sehonowi, i Ogowi, królom Amorejskim, i ziemi ich, które wygładził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'A gdy je wam Pan poda, tedy im uczynicie według każdego przykazania, jakom wam przykazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Zmacniajcież się, a mężnie sobie poczynajcie, nie bójcie się, ani się lękajcie twarzy ich; albowiem Pan, Bóg twój, on idzie z tobą, nie odstąpi cię, ani cię opuści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Tedy przyzwawszy Mojżesz Jozuego, rzekł do niego przed oczyma wszystkiego Izraela: Zmocnij się, a mężnie sobie poczynaj; bo ty wnijdziesz z ludem tym do ziemi, o którą przysiągł Pan ojcom ich, że im ją da, a ty im ją w dziedzictwo podzielisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'A Pan on pójdzie przed tobą, on będzie z tobą, nie odstąpi cię, ani cię opuści; nie bójże się, ani się lękaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Tedy napisał Mojżesz ten zakon i oddał go kapłanom, synom Lewiego, którzy nosili skrzynię przymierza Pańskiego, i wszystkim starszym Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Przytem rozkazał im Mojżesz, mówiąc: Na początku każdego siódmego roku, w pewny czas roku odpuszczania, w święto Kuczek;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Gdy się zejdzie wszystek Izrael, aby się pokazał przed Panem, Bogiem twoim, na miejscu, które sobie obierze, obwołasz ten zakon przed wszystkim Izraelem w uszach ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'A zgromadzisz lud, męże, i niewiasty, i dziatki, i przychodnie twoje, którzy są w bramach twoich, aby słuchali, i aby się uczyli, i bali Pana, Boga waszego, i przestrzegali, aby czynili wszystkie słowa zakonu tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Synowie też ich, którzy jeszcze nie wiedzą, niechaj słuchają, i niech się uczą bać Pana, Boga waszego, po wszystkie dni, których żyć będziecie na ziemi, do której idziecie, przeprawiwszy się przez Jordan wnijdziecie, abyście ją posiedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Zatem rzekł Pan do Mojżesza: Oto, przybliżyły się dni śmierci twojej; przyzówże Jozuego, a stańcie w namiocie zgromadzenia, a przykażę mu. Szedł tedy Mojżesz i Jozue, a stanęli w namiocie zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Tedy się ukazał Pan w namiocie w słupie obłokowym; i stanął on słup obłokowy nade drzwiami namiotu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'I rzekł Pan do Mojżesza: Oto, ty zaśniesz z ojcy twoimi; a powstawszy lud ten będzie cudzołożył, naśladując bogów cudzoziemców tej ziemi, do której wchodzi, aby mieszkał w pośrodku niej i opuści mię, i złamie przymierze moje, którem postanowił z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Przetoż zapali się gniew mój przeciwko jemu onego dnia, a opuszczę je, i skryję oblicze moje przed nimi, a będzie na pożarcie, i znajdą go wiele złych rzeczy i utrapienia; i rzecze dnia onego: Azaż nie dlatego, iż Boga mego nie masz w pośrodku mnie, znalazły mię te złe rzeczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'A Ja kryjąc skryję oblicze moje w on dzień dla wszystkiego złego, które czynili, udawszy się za bogi cudzymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Teraz tedy napiszcie sobie tę pieśń, a naucz jej synów Izraelskich; włóż ją w usta ich, aby im była ta pieśń świadectwem przeciwko synom Izraelowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Albowiem wprowadzę go do ziemi, o którąm przysiągł ojcom jego, opływającej mlekiem i miodem; i będzie jadł, a naje się, i utyje, a obróci się do bogów cudzych, i służyć im będzie, i rozdraźnią mię, i zrzucą przymierze moje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'I stanie się, gdy go znajdzie wiele złego i utrapienia, że będzie ta pieśń przed nim na świadectwo; albowiem nie przyjdzie w zapamiętanie w uściech nasienia ich, gdyż wiem myśli jego, i co on jeszcze dziś czynić będzie, pierwej niż go wprowadzę do ziemi, o którąm przysiągł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'I napisał Mojżesz tę pieśń onegoż dnia, i nauczył jej synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Potem przykazał Jozuemu, synowi Nunowemu, i rzekł: Zmacniaj się, i mężnie sobie poczynaj; albowiem ty wprowadzisz syny Izraelskie do ziemi, o którąm im przysiągł; a Ja będę z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'I stało się, gdy napisał Mojżesz słowa zakonu tego w księgi, i dokończył ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Rozkazał Mojżesz Lewitom, którzy nosili skrzynię przymierza Pańskiego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Weźmijcie księgi zakonu tego i włóżcie je przy stronie do skrzyni przymierza Pana, Boga waszego, aby tam były przeciwko tobie na świadectwo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Albowiem ja znam upór twój, i kark twój twardy; oto, póki ja jeszcze dziś żyję z wami, jesteście odpornymi Panu, jakoż daleko więcej po śmierci mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Zgromadźcież do mnie wszystkie starsze pokoleń waszych, i przełożone wasze, żebym mówił w uszach ich słowa te, i będę wzywał na świadectwo przeciwko nim niebo i ziemię,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Ponieważ wiem, że po śmierci mojej popsujecie się bardzo, a ustąpicie z drogi, którąm wam rozkazał; przetoż przyjdzie na was to złe w ostatnie dni, gdy będziecie czynić złe przed oczyma Pańskiemi, draźniąc go sprawami rąk waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'I mówił Mojżesz w uszach wszystkiego zgromadzenia Izraelskiego słowa tej pieśni, aż jej dokończył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Słuchajcie niebiosa, a mówić będę; niech słucha i ziemia wymowy ust moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Kropić będzie jako deszcz nauka moja, popłynie jako rosa wymowa moja, jako drobny deszcz na zioła, a jako krople na trawę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Albowiem imienia Pańskiego będę wzywał; dajcież wielmożność Bogu naszemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Skale, której sprawy są doskonałe; bo wszystkie drogi jego są sprawiedliwe. Boć jest Bóg prawdziwy, a nie masz w nim nieprawości, sprawiedliwy i prawy jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Pokazili mu się, jakoby nie byli synami jego, sprosnością swoją, naród zły, a przewrotny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'I także to oddawacie Panu, ludu głupi i szalony? izali nie on jest ojcem twoim, który cię sobie nabył? on cię uczynił, i stworzył cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Wspomnij na dni dawne, uważajcie lata każdego wieku; spytaj ojca twego, a oznajmi tobie; starszych twoich, a powiedząć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Gdy rozdzielił dziedzictwa Najwyższy narodom, a rozsadził syny Adamowe, położył granice narodom według liczby synów Izraelskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Albowiem działem Pańskim jest lud jego, Jakób sznurem dziedzictwa jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Znalazł go w ziemi pustej, i na puszczy wielkiej i strasznej; obwodził go, uczył go, strzegł go, jako źrenicy oka swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Jako orzeł wybawia orlęta swoje, nad orlętami swojemi latając, rozszerza skrzydła swoje, bierze je i nosi je na skrzydłach swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Tak Pan sam prowadził go, a żaden obcy bóg nie był z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Wyniósł go na wysokie miejsca ziemi, aby używał urodzajów polnych, i uczynił, aby ssał miód z skały i oliwę z opoki twardej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Aby jadł masło od krów, i mleko od owiec, z tłustością jagniąt, i barany odchowane w Basan, i kozły z tłustością ziarn pszenicznych, a pił czerwone wino wyborne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'I roztył Izrael, i wierzgał (otyłeś, stłuściałeś, zgrubiałeś, i opuściłeś Boga, który cię uczynił,) i lekce poważył Boga, opokę zbawienia swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Ku zapalczywości pobudzili go przez cudze bogi, i przez obrzydliwości rozdraźnili go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Ofiarowali dyjabłom, nie Bogu, bogom, których nie znali, nowym, którzy z bliska przyszli, których się nie bali ojcowie wasi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Opoki, która cię spłodziła, zapomniałeś, zapomniałeś Boga, Stworzyciela twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Co widząc Pan poruszył się gniewem na syny swoje, i na córki swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'I rzekł: Skryję oblicze moje przed nimi, obaczę, jaki będzie koniec ich; albowiem są narodem przewrotnym, synami, w których wiary nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Oni mię wzruszyli ku zapalczywości przez to, co nie jest Bogiem; pobudzili mię próżnościami swemi. Ja też do zazdrości pobudzę je przez te, którzy nie są ludem, przez naród głupi rozdraźnię je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Albowiem ogień rozpalił się w popędliwości mojej, i będzie gorzał aż do najgłębszego piekła, i pożre ziemię, i urodzaj jej, i wypali grunty gór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Zgromadzę na nie złe rzeczy, strzały moje na nie wystrzelam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Zniszczeją od głodu, i będą strawieni gorączką, i śmiercią gorzką; zęby też bestyi poślę na nie, z jadem gadzin ziemskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Zewnątrz osieroci je miecz, a w pokojach będzie strach, tak na młodzieńca, jako na pannę, na ssącego piersi, i na męża sędziwego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Rzekłem: Rozproszę je po kątach, i wygubię między ludźmi pamiątkę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Gdybym się na pychę nieprzyjaciół nie oglądał, by się snać nie podnieśli nieprzyjaciele ich, a nie rzekli: Ręka nasza wyniosła, a nie Pan, sprawiła to wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Albowiem ten naród ginie przez rady swe, i nie ma rozumu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'O by mądrymi byli! wyrozumieliby to, i oglądaliby się na ostatnie rzeczy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Jakoby uganiał jeden z nich tysiąc, a dwaj goniliby dziesięć tysięcy! gdyby ich Bóg, opoka ich, nie zaprzedał, i Pan ich nie wydał:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Albowiem nie jako skała nasza skała ich, co nieprzyjaciele nasi sami osądzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Albowiem z macicy Sodomskiej macica ich, i z latorośli Gomorskich jagody ich, jagody jadowite, grona ich gorzkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Jad smoczy wino ich, i trucizną żmij okrutną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Izali to nie jest skryto u mnie; zapieczętowano w skarbie moim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Mojać jest pomsta i nagroda; czasu swego powinie się noga ich, ponieważ bliski jest dzień zginienia ich, a spieszą się przyszłe rzeczy do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Albowiem sądzić będzie Pan lud swój, a sług swoich użali się, gdy ujrzy, że ustała siła, a iż tak pojmany, jako zostawiony, nic nie mogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'I rzecze: Gdzież bogowie ich? Ona opoka, w której ufali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Którzy tłustość ofiar ich jadali, i pijali wino ofiar ich mokrych? Niechże wstaną, i ratują was, i niechaj będą ucieczką waszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Obaczcież teraz, żem Ja, Jam jest sam, a że nie masz bogów oprócz Mnie; Ja zabijam i ożywiam, zranię, i Ja uleczę, a nie masz kto by z ręki mojej wyrwał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Albowiem podniosę ku niebu rękę moję, i rzekę: Żyję Ja na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Jeźli zaostrzę błyszczący się miecz swój, i porwie sąd ręka moja, oddam pomstę nieprzyjaciołom moim, i tym, którzy mię nienawidzą, nagrodzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Opoję strzały moje krwią, a miecz mój naje się mięsa ze krwi pobitych i pojmanych, skoro zacznę mścić się nad nieprzyjacioły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Weselcie się narodowie z ludem jego; albowiem krwi sług swoich pomści się, i pomstę odda nieprzyjaciołom swoim, a miłościw będzie ziemi swojej, i ludowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Tedy przyszedł Mojżesz, i mówił wszystkie słowa pieśni tej w uszach ludu tego, on i Jozue, syn Nunów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'A gdy dokonał Mojżesz mówić tych wszystkich słów do wszystkiego Izraela,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Rzekł do nich: Przyłóżcie serca wasze do wszystkich słów, któremi się ja oświadczam przeciwko wam dziś, abyście je przykazywali synom waszym, żeby strzegli i pełnili wszystkie słowa zakonu tego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Albowiem to słowo nie ma być próżne u was, gdyż jest żywotem waszym; i w tem słowie przedłużycie dni na ziemi, do której się przeprawiacie przez Jordan, abyście ją osiedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'I rzekł Pan do Mojżesza tegoż dnia, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Wstąp na tę górę Abarym, na górę Nebo, która jest w ziemi Moabskiej przeciw Jerychu, a oglądaj ziemię Chananejską, którą Ja dawam synom Izraelskim w osiadłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'I umrzesz na tej górze, na którą wstąpisz, i będziesz przyłączony do ludu twego, jako umarł Aaron, brat twój, na górze Hor, i przyłączon jest do ludu swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Dla tego żeście wystąpili przeciwko mnie w pośród synów Izraelskich przy wodach w poswarku w Kades na puszczy Syn, i żeście mię nie poświęcili w pośród synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Bo przed sobą oglądasz ziemię; ale tam nie wnijdziesz, do tej ziemi, którą ja daję synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'A toć jest błogosławieństwo, którem błogosławił Mojżesz, mąż Boży, synom Izraelskim przed śmiercią swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'I rzekł: Pan z Synaj przyszedł, i pojawił się im z Seiru, objaśnił się z góry Faran, a przyszedł z dziesięcioma tysiącami świętych; z prawicy jego zakon ognisty dany im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Zaiste on miłuje lud; wszyscy święci jego są w rękach twych, i oni skupili się do nogi twej, aby co pojęli z słów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Zakon podał nam Mojżesz, dziedzictwo zebraniu Jakóbowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Bo był królem w Izraelu, gdy się zgromadzili przedniejsi z ludu, także pokolenia Izraelskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Niech żyje Ruben, a nie umiera; a niech będzie mężów jego poczet.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Potem też błogosławił Judzie, i rzekł: Wysłuchaj Panie głos Judy, a do ludu jego wprowadź go; ręka jego będzie walczyła zań, a ty go ratować będziesz przeciw nieprzyjaciołom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'A do Lewiego rzekł: Tummim twoje, i Urim twoje było przy mężu świętym twoim, któregoś kusił w Massa, i z którymeś miał spór u wód Meryba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Tenci to jest, który rzekł ojcu swemu, i matce swej: Nie oglądam się na was: i braci swych nie znał, i o synach swych nie wiedział; albowiem oni strzegą słów twych, i przymierze twoje zachowują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Będą uczyć sądów twoich Jakóba, a zakonu twego Izraela; kłaść będą kadzenie pod nozdrza twoje, a całopalenie na ołtarz twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Błogosławże, Panie, mocy jego, a sprawy rąk jego przyjmij wdzięcznie; zetrzyj biodra nieprzyjaciół jego, i tych którzy go nienawidzą, aby powstać nie mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'A do Benjamina rzekł: Ten jest najmilszy Panu; będzie mieszkał przy nim bezpiecznie; bronić go będzie na każdy dzień, a między ramiony jego przebywać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Do Józefa też rzekł: Błogosławiona od Pana ziemia jego z najlepszych rzeczy niebieskich, z rosy, i z źródeł z ziemi wynikających.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'I dla rozkosznych urodzajów słonecznych, także dla rozkosznych dostałych urodzajów miesięcznych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'I dla rozkosznych gór starodawnych, i dla rozkosznych pagórków wiecznych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'Także dla rozkosznych owoców ziemi, i obfitości jej, a dla życzliwości mieszkającego w krzu. Niech to błogosławieństwo przyjdzie na głowę Józefowę, i na wierzch głowy Nazarejczyka między bracią jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Jako pierworodnego wołu ozdoba jego, a jako rogi jednorożcowe rogi jego, temi narody zbodzie na porząd aż do ostatnich granic ziemi; a teć są dziesięć tysięcy Efraimitów, a te tysiące Manasesytów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'A do Zabulona rzekł: Wesel się Zabulon w wyjściu swem, a ty Isaschar w namiotach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Ludu na górę przyzowią; tam ofiarować będą ofiary sprawiedliwości, ponieważ obfitość morską ssać będą, i zakryte skarby piasku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'A do Gada rzekł: Błogosławiony, który rozmnaża Gada! jako lew mieszkać będzie, a porwie ramię i głowę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Który sobie upatrzył na początku mieszkanie, a iż tam o dziale swoim przez zakonodawcę ubezpieczony jest; przetoż pójdzie z książęty ludu, sprawiedliwość Pańską wykona, i sądy jego z Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'A do Dana rzekł: Dan jako szczenię lwie wyskakujące z Basan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'A do Neftalima rzekł: Neftali, nasycony przyjaźni i pełny błogosławieństwa Pańskiego, zachód i południe opanujesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'A do Asera rzekł: Błogosławiony nad inne syny Aser, będzie przyjemny braciom swoim, i omoczy w oliwie nogę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Żelazo i miedź pod obuwiem twojem; i póki będą trwać dni twoje, słynąć będzie moc twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Nie masz tak prawego, jako Bóg, który jeździ po niebie ku ratunku twemu, i w wielmożności swej na obłokach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Mieszkaniem twojem Bóg wieczny, a ze spodku ramiona wieczności. Ten wyrzuci przed tobą nieprzyjaciela, a rzeczeć: Wytrać go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Aby mieszkał Izrael bezpiecznie sam, źródło Jakóbowe, w ziemi zboża i wina, którego też niebiosa kropić będą rosą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Błogosławionyś ty, Izraelu! Któż podobny tobie? ludu zachowany przez Pana, który jest tarczą ratunku twego, a mieczem zacności twojej. Przeto obłudnieć się poddadzą nieprzyjaciele twoi, a ty wyniosłość ich deptać będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Tedy wstąpił Mojżesz z onych równin Moabskich na górę Nebo, na wierzch pagórka, który jest na przeciwko Jerychu; a ukazał mu Pan wszystkę ziemię od Galaad aż do Dan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'I wszystkę ziemię Neftalimowę, i ziemię Efraimowę, i Manasesowę, i wszystkę ziemię Judowę aż do morza ostatniego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'I stronę południową, i równinę doliny Jerycha, miasta osadzonego palmami, aż do Segor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Tedy mu rzekł Pan: Tać jest ziemia, o którąm przysiągł Abrahamowi, Izaakowi i Jakóbowi, mówiąc: Nasieniu twemu dam ją; pokazałem ją oczom twoim, ale do niej nie wnijdziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'I umarł tam Mojżesz, sługa Pański, w ziemi Moabskiej, według słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'I pogrzebł go Pan w dolinie w ziemi Moabskiej, przeciw Betfegorowi, a nie dowiedział się nikt o grobie jego aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'A Mojżesz miał sto i dwadzieścia lat, gdy umarł; nie zaćmiło się oko jego, ani się naruszyła czerstwość jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'I płakali synowie Izraelscy Mojżesza na polach Moabskich przez trzydzieści dni. A gdy się skończyły dni płaczu i żałoby Mojżeszowej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Tedy Jozue, syn Nunów, napełniony jest duchem mądrości, bo był włożył Mojżesz ręce swoje nań: i posłuszni mu byli synowie Izraelscy, a czynili, jako przykazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'I nie powstał prorok więcej w Izraelu podobny Mojżeszowi, którego by tak znał Pan, twarzą w twarz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'We wszystkich znakach, i cudach, dla których go był posłał Pan, aby je czynił w ziemi Egipskiej przed Faraonem i przed wszystkimi sługami jego, i przed wszystką ziemią jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'Także we wszystkich sprawach ręki możnej, i we wszystkich postrachach wielkich, które czynił Mojżesz przed oczyma wszystkiego Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'I stało się po śmierci Mojżesza, sługi Pańskiego, że mówił Pan do Jozuego syna Nunowego, sługi Mojżeszowego, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Mojżesz, sługa mój, umarł; przetoż teraz wstań, przepraw się przez ten Jordan, ty, i wszystek lud ten, do ziemi, którą Ja im, synom Izraelskim, dawam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Każde miejsce, po którem deptać będzie stopa nogi waszej, dałem wam, jakom obiecał Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Od puszczy i od Libanu tego, i aż do rzeki wielkiej, rzeki Eufrates, i wszystka ziemia Hetejczyków, i aż do morza wielkiego na zachód słońca, będzie granica wasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Nie ostoi się nikt przed tobą po wszystkie dni żywota twego; jakom był z Mojżeszem, tak będę z tobą, nie odstąpię cię, ani cię opuszczę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Zmacniajże się i mężnie sobie poczynaj; albowiem ty podasz w dziedzictwo ludowi temu ziemię, o którąm przysiągł ojcom ich, że im ją dam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Tylko się zmacniaj, i bardzo mężnie sobie poczynaj, abyś strzegł, i czynił wszystko według zakonu, któryć rozkazał Mojżesz, sługa mój; nie uchylaj się od niego ani na prawo ani na lewo, żebyś się roztropnie sprawował we wszystkiem, do czego się udasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Niech nie odstępują księgi zakonu tego od ust twoich; ale rozmyślaj w nich we dnie i w nocy, abyś strzegł i czynił wszystko, co napisano w nim; albowiem na ten czas poszczęścią się drogi twoje, i na ten czas roztropnym będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Azażemci nie rozkazał: Zmocnij się, i mężnie sobie poczynaj, nie lękaj się, a nie trwóż sobą, albowiem z tobą jest Pan, Bóg twój, we wszystkiem, do czegokolwiek się obrócisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'A przetoż rozkazał Jozue przełożonym nad ludem, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Przejdźcie przez pośrodek obozu, a rozkażcie ludowi, mówiąc: Gotujcie sobie żywność; albowiem po trzech dniach przejdziecie przez ten Jordan, abyście weszli, a posiedli ziemię, którą Pan, Bóg wasz, dawa wam w osiadłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Rubenitom też, i Gadytom, i połowie pokolenia Manasesowego rzekł Jozue mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Pamiętajcie na słowo, które wam rozkazał Mojżesz, sługa Pański, mówiąc: Pan, Bóg wasz, sprawił wam odpoczynienie, i dał wam tę ziemię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Żony wasze, dziatki wasze, i bydła wasze niech zostaną w ziemi, którą wam dał Mojżesz z tej strony Jordanu; ale wy pójdziecie zbrojni przed bracią waszą, wszyscy duży w sile, a będziecie ich posiłkować,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Aż odpoczynienie sprawi Pan braci waszym jako i wam, a oni posiędą ziemię, którą im dawa Pan, Bóg wasz; potem się wrócicie do ziemi osiadłości waszej, a będziecie ją trzymać, którą wam dał Mojżesz, sługa Pański, z tej strony Jordanu na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'I odpowiedzieli Jozuemu, mówiąc: Wszystko, coś nam rozkazał, uczynimy, a gdziekolwiek nas poślesz, pójdziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Jakośmy byli posłuszni Mojżeszowi, tak posłuszni będziemy i tobie; tylko niech będzie Pan, Bóg twój, z tobą, jako był z Mojżeszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Ktobykolwiek przeciwił się ustom twoim, a nie byłby posłusznym słowom twoim we wszystkiem, co mu rozkażesz, niechaj umrze; tylko się zmacniaj, a mężnie sobie poczynaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'A tak posłał Jozue, syn Nunów, z Syttim dwóch szpiegów potajemnie, mówiąc: Idźcie, wypatrujcie ziemię, i Jerycho. Szli tedy i weszli do niektórej niewiasty wszetecznej, której imię Rachab, i odpoczęli tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'I powiedziano to królowi Jerycha, mówiąc: Oto, mężowie jacyś przyszli tu tej nocy z synów Izraelskich, aby przeszpiegowali tę ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Tedy posłał król Jerycha do Rachaby, mówiąc: Wywiedź męże, którzy przyszli do ciebie, a weszli do domu twego; bo na przeszpiegowanie wszystkiej ziemi przyszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Ale wziąwszy ona niewiasta tych dwóch mężów, skryła je, i rzekła: Prawdać jest, przyszli do mnie mężowie; alem nie wiedziała, skąd byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'A gdy bramę zamykano w zmierzch, oni mężowie wyszli; i nie wiem, dokąd poszli; gońcież ich co najrychlej, bo ich dościgniecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'A ona wwiodła je była na dach, i tam je przykryła lnem nietartym, który była rozstawiła na dachu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Mężowie tedy wysłani gonili je drogą ku Jordanu aż do brodu; a bramę zamkniono, skoro wyszli ci, którzy szli za nimi w pogoń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'A tak pierwej niż posnęli, ona wstąpiła do nich na dach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'I rzekła do onych mężów: Wiem, że wam dał Pan ziemię tę; bo strach wasz przypadł na nas, i osłabiali wszyscy obywatele tej ziemi przed wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Bośmy słyszeli, jako wysuszył Pan wody morza czerwonego przed wami, gdyście wychodzili z Egiptu, i coście uczynili dwom królom Amorejskim, którzy byli z onej strony Jordanu, Sehonowi, i Ogowi, któreście pobili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Co gdyśmy usłyszeli, upadło serce nasze i nie ostał się więcej duch w nikim przed wami; albowiem Pan, Bóg wasz, jest Bogiem na niebie wzgórę, i na ziemi nisko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Przetoż teraz przysiężcie mi proszę przez Pana, iż jakom ja uczyniła z wami miłosierdzie, także uczyńcie i wy z domem ojca mego miłosierdzie, a dajcie mi znak pewny,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Iż zachowacie żywo ojca mego i matkę moję, i bracią moję, i siostry moje, i wszystko, co ich jest, a wybawicie dusze nasze od śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'I odpowiedzieli jej oni mężowie: Dusza nasza będzie za was na śmierć, jeźli nie wydacie tej sprawy naszej, i będzie to, gdy nam poda Pan tę ziemię, że uczynimy z tobą miłosierdzie i prawdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'I spuściła je na powrozie z okna; bo dom jej był przy murze i ona na murze mieszkała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'I rzekła im: Na górę idźcie, by się snać nie spotkali z wami, którzy was gonią: i tam się kryjcie przez trzy dni, aż się wrócą, którzy was gonią, a potem pójdziecie drogą waszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'I rzekli jej mężowie oni: Będziemy wolni od przysięgi tej, którąś nas poprzysięgła,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Jeźli, gdy wnijdziemy do ziemi, tego czerwonego sznuru nie uwiążesz u okna, po którymeś nas spuściła, a ojca twego, i matki twojej, i braci twojej, i wszystkiego domu ojca twego nie zbierzeszli do siebie w dom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Albowiem ktobykolwiek wyszedł ze drzwi domu twego, krew jego będzie na głowę jego, a my będziemy bez winy; ale każdego, ktokolwiek będzie z tobą w domu, krew jego obróci się na głowę naszę, jeźli się go kto rękę dotknie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Lecz jeźli wydasz tę sprawę naszę, tedy będziemy wolni od przysięgi twojej, którąś nas poprzysięgła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'I odpowiedziała; Jakoście powiedzieli, niechże tak będzie. Tedy je wypuściła, i poszli; i uwiązała sznur czerwony w onem oknie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'A odszedłszy przyszli na górę, i zostali tam przez trzy dni, aż się wrócili, którzy je gonili; bo ich szukali ci, którzy je gonili, po wszystkich drogach, ale nie znaleźli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'I wrócili się oni dwaj mężowie, a zstąpiwszy z góry, przeprawili się, i przyszli do Jozuego, syna Nunowego, i powiedzieli mu wszystko, co się z nimi działo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'I mówili do Jozuego: Dał Pan w ręce nasze tę wszystkę ziemię; bo się strwożyli wszyscy obywatele ziemi przed twarzą naszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Tedy Jozue wstał bardzo rano, i ruszyli się z Syttim, a przyszli aż do Jordanu, on i wszyscy synowie Izraelscy, i tamże przenocowali, niźli się przeprawili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'A po trzecim dniu przeszli przełożeni przez pośrodek obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'I rozkazali ludowi, mówiąc: Gdy ujrzycie skrzynię przymierza Pana, Boga waszego, i kapłany Lewity, niosące ją, wy też ruszycie się z miejsca swego, a pójdziecie za nią;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Wszakże plac między wami i między nią będzie na dwa tysiące łokci miary zwyczajnej; nie przystępujcie blisko do niej, abyście wiedzieli drogę, którą iść macie; albowiem nie chodziliście tą drogą przedtem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Tedy rzekł Jozue do ludu: Poświęćcie się; albowiem jutro uczyni Pan między wami dziwne rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Przytem rzekł Jozue do kapłanów, mówiąc: Weźmijcie skrzynię przymierza, a idźcie przed ludem; i wzięli skrzynię przymierza, i szli przed ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'I rzekł Pan do Jozuego: Dziś cię pocznę wywyższać przed oczyma wszystkiego Izraela, aby poznali, iż jakom był z Mojżeszem, tak będę i z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Rozkażże ty kapłanom, niosącym skrzynię przymierza, i rzecz im: Gdy wnijdziecie w brzeg wód Jordańskich, w Jordanie staniecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Rzekł też Jozue do synów Izraelskich: Przystąpcie sam, a słuchajcie słów Pana, Boga waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'I rzekł Jozue: W tem poznacie, że Bóg żyjący jest w pośrodku was, a iż koniecznie wypędzi przed twarzą waszą Chananejczyka, i Hetejczyka, i Hewejczyka, i Ferezejczyka, i Gergezejczyka, i Amorejczyka, i Jebuzejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Oto, skrzynia przymierza Panującego nad wszystką ziemią pójdzie przed wami przez Jordan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Przetoż teraz obierzcie sobie dwanaście mężów z pokoleń Izraelskich, po jednym mężu z każdego pokolenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'A gdy się zastanowią stopy nóg kapłanów, niosących skrzynię Pana, Panującego nad wszystką ziemią, w wodzie Jordańskiej, tedy się wody jordańskie rozstąpią, tak iż woda płynąca z góry stanie w jednej kupie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'I stało się, gdy się ruszył lud z namiotów swych, aby się przeprawili przez Jordan, a kapłani, niosący skrzynię przymierza, szli przed ludem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'A gdy przyszli niosący skrzynię aż do Jordanu, a nogi kapłanów, którzy nieśli skrzynię, omoczyły się w brzegu wód, (bo Jordan wzbiera i wylewa na wszystkie brzegi swoje, na każdy czas żniwa.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Tedy się zastanowiły wody płynące z gór, a stanęły w jednej kupie bardzo daleko od Adama, miasta, które jest ku stronie Sartan; a które płynęły na dół do morza pustego, morza słonego, zginęły i ustały; a tak lud przeprawiał się przeciwko Jerychu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'A kapłani, którzy nieśli skrzynię przymierza Pańskiego, stali na suszy w pośród Jordanu porządnie, a wszyscy Izraelczycy szli po suszy, aż się lud wszystek przeprawił przez Jordan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'A gdy się wszystek lud przeprawił za Jordan, (bo rzekł był Pan do Jozuego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Obierzcie sobie z ludu dwanaście mężów, po jednym mężu z każdego pokolenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'I rozkażcie im, mówiąc: Weźmijcie sobie stąd z pośrodku Jordanu, z tego miejsca, gdzie stały nogi kapłanów porządnie, dwanaście kamieni, które z sobą wyniósłszy postawicie na stanowisku, gdzie będziecie leżeć przez tę noc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Tedy wezwał Jozue dwanaście mężów, które był wybrał z synów Izraelskich, po jednym mężu z każdego pokolenia.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'I rzekł do nich Jozue: Idźcie przed skrzynią Pana, Boga waszego, w pośrodek Jordanu, a weźmij każdy kamień jeden na ramię swoje według liczby pokolenia synów Izraelskich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Aby to było na znak między wami, gdyby potem pytali synowie wasi mówiąc: Co wam znaczy ten kamień?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Tedy im powiecie, iż się rozstąpiły wody w Jordanie przed skrzynią przymierza Pańskiego; albowiem gdy szła przez Jordan, rozstąpiły się wody Jordańskie; i będzie ten kamień na pamiątkę synom Izraelskim aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'I uczynili tak synowie Izraelscy, jako rozkazał Jozue, i wzięli dwanaście kamieni z pośród Jordanu, jako mówił Pan do Jozuego, według liczby pokolenia synów Izraelskich, a zanieśli je z sobą aż do stanowiska, i tam je złożyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Jozue też wystawił dwanaście kamieni w pośród Jordanu, na miejscu, kędy stały nogi kapłanów, niosących skrzynię przymierza, które tam zostały aż po dziś dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'A tak kapłani niosący skrzynię stali w pośród Jordanu, aż się wypełniło to wszystko, co był rozkazał Pan Jozuemu mówić do ludu według wszystkiego, co był przykazał Mojżesz Jozuemu. Spieszył się tedy lud i przeszedł Jordan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'I stało się gdy wszystek lud przeszedł, że też przeszła i skrzynia Pańska i kapłani przed oblicznością ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Przeszli też synowie Rubenowi, i synowie Gadowi, z połową pokolenia Manasesowego, zbrojno przed syny Izraelskimi, jako im był powiedział Mojżesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Około czterdziestu tysięcy ludu zbrojnego przeszło przed Panem do boju na polu Jerycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Dnia onego wywyższył Pan Jozuego przed oczyma wszystkiego Izraela, i bali się go, jako się bali Mojżesza po wszystkie dni żywota jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Potem rzekł Pan do Jozuego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Rozkaż kapłanom, niosącym skrzynię świadectwa, aby wystąpili z Jordanu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'I rozkazał Jozue kapłanom, mówiąc: Wystąpcie z Jordanu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'I stało się, gdy wystąpili kapłani, niosący skrzynię przymierza Pańskiego, z pośrodku Jordanu, a stanęły stopy nóg kapłanów na suszy, wróciły się wody Jordańskie na miejsce swoje, a płynęły, jako przedtem, we wszystkich brzegach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'A lud, wyszedłszy z Jordanu dziesiątego dnia miesiąca pierwszego, położyli się obozem w Galgal ku stronie wschodniej Jerycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'A dwanaście onych kamieni, które wynieśli z Jordanu, postawił Jozue w Galgal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'I rzekł do synów Izraelskich, mówiąc: Co znaczy ten kamień?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'Tedy oznajmijcie synom waszym, mówiąc: Po suszy przeszedł Izrael ten Jordan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Albowiem osuszył Pan Bóg wody Jordańskie przed wami, ażeście przeszli, jako uczynił Pan, Bóg wasz, morzu czerwonemu, które wysuszył przed nami, ażeśmy przeszli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Aby poznali wszyscy narodowie ziemi rękę Pańską, że można jest, żebyście się bali Pana, Boga waszego, po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'I stało się, gdy usłyszeli wszyscy królowie Amorejscy, którzy mieszkali za Jordanem ku zachodowi, i wszyscy królowie Chananejscy, którzy mieszkali nad morzem, że wysuszył Pan wody Jordańskie przed syny Izraelskimi, aż się przeprawili, upadło serce ich, tak iż nie został więcej w nich duch przed oblicznością synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Onegoż czasu rzekł Pan do Jozuego: Uczyń sobie noże ostre, a znowu obrzeż syny Izraelskie po wtóre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'I uczynił sobie Jozue noże ostre i obrzezał syny Izraelskie na pagórku nieobrzezek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'A tać była przyczyna, dla czego je obrzezał Jozue: Wszystek lud, który wyszedł z Egiptu, płci męskiej, wszyscy mężowie wojenni, pomarli byli na puszczy, w drodze, gdy wyszli z Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Bo obrzezan był wszystek on lud, co wyszedł; ale wszystek lud, który się zrodził na puszczy, w drodze po wyjściu z Egiptu, nie był obrzezany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, '(Albowiem przez czterdzieści lat chodzili synowie Izraelscy po puszczy, aż poginął wszystek on naród mężów wojennych, którzy byli wyszli z Egiptu, którzy nie słuchali głosu Pańskiego, którym przysiągł Pan, iż im nie miał okazać ziemi, o którą przysiągł Pan ojcom ich, iż nam ją dać miał, ziemię opływającą mlekiem i miodem.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Ale syny ich, które wystawił na miejsca ich, te obrzezał Jozue, bo byli w nieobrzezce; bo ich nie obrzezano w drodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'A gdy już wszystek lud był obrzezany, mieszkał na miejscu swem w obozie, aż się wygoili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Potem rzekł Pan do Jozuego: Dzisiajm zdjął pohańbienie Egipskie z was; i nazwano imię miejsca onego Galgal, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Tedy położyli się obozem synowie Izraelscy w Galgal, a obchodzili święto przejścia czternastego dnia miesiąca w wieczór na polach Jerycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'I jedli z urodzajów onej ziemi nazajutrz po święcie przejścia chleby przaśne, i kłosy prażone onegoż dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'I przestała manna nazajutrz, gdy poczęli jeść zboża onej ziemi; i nie mieli więcej synowie Izraelscy manny, ale jedli z urodzajów ziemi Chananejskiej onegoż roku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'I stało się, gdy Jozue był u Jerycha, że podniósł oczu swych a ujrzał, a oto mąż stał przeciwko niemu, mając miecz swój dobyty w ręce swej; i przystąpiwszy do niego Jozue, rzekł mu: Z naszychżeś ty, czy z nieprzyjaciół naszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'A on rzekł: Nie; alem Ja hetman wojska Pańskiego, terazem przyszedł. Tedy upadłszy Jozue obliczem swem na ziemię, pokłonił się, i rzekł mu: Cóż Pan mój mówi do sługi swego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'I rzekł hetman wojska Pańskiego do Jozuego: Zzuj obuwie twoje z nóg twoich, bo miejsce, na którem stoisz, święte jest; i uczynił tak Jozue.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'A Jerycho było zamknione, i opatrzone przed synami Izraelskimi, i nikt z niego nie wychodził, ani do niego wchodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Tedy rzekł Pan do Jozuego: Otom dał w ręce twoje Jerycho, i króla jego, i możne wojska jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'A tak obchodzić będziecie miasto, wszyscy mężowie waleczni, około miasta chodząc raz na dzień; tak uczynicie po sześć dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Przytem siedem kapłanów poniosą siedem trąb z rogów baranich, przed skrzynią; a dnia siódmego obejdziecie miasto siedem kroć, a kapłani trąbić będą w trąby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'A gdy przewłocznie trąbić będą w trąby z rogów baranich, skoro usłyszycie głos trąby, wszystek lud uczyni okrzyk bardzo wielki, i upadnie mur miasta na miejscu swem, i wnijdzie lud do miasta, każdy przeciw miejscu, gdzie stał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Tedy wezwawszy Jozue, syn Nunów, kapłanów, rzekł do nich: weźmijcie skrzynię przymierza, a siedem kapłanów niech niosą siedem trąb z baranich rogów przed skrzynią Pańską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Potem rzekł do ludu: Idźcie a obejdźcie miasto, a zbrojni niech idą przed skrzynią Pańską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'A gdy to Jozue ludowi powiedział, siedem kapłanów wziąwszy siedem trąb z rogów baranich, szli przed skrzynią Pańską, i trąbili w trąby, a skrzynia przymierza Pańskiego szła za nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'A zbrojni szli przed kapłany trąbiącymi w trąby; ostatek też ludu pospolitego szedł za skrzynią, gdy idąc trąbiono w trąby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'A ludowi przykazał Jozue, mówiąc: Nie będziecie wołać, ani będzie słyszan głos wasz, ani wynijdzie z ust waszych słowo, aż do dnia, którego wam rzekę: Wołajcie; i uczynicie okrzyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Tedy obeszła skrzynia Pańska miasto w około raz; i wrócili się do obozu, i zostali w obozie przez noc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Wstał zasię Jozue rano, a kapłani wzięli skrzynię Pańską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'A siedem kapłanów wziąwszy siedem trąb z rogów baranich, przed skrzynią Pańską szli, idąc i trąbiąc w trąby; a zbrojni szli przed nimi, ostatek też ludu pospolitego szedł za skrzynią Pańską, gdy idąc trąbiono w trąby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'A tak obeszli miasto drugi raz dnia wtórego, i wrócili się do obozu; i tak czynili po sześć dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Ale dnia siódmego wstali rano na świtaniu, i obeszli miasto tymże sposobem siedem kroć; tylko dnia tego obeszli miasto siedem kroć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'I stało się, gdy siódmy raz obchodzili, a kapłani trąbili w trąby, rzekł Jozue do ludu: Krzyczcież teraz; albowiem Pan podał wam miasto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'I niech będzie to miasto przeklęstwem Panu, ono, i wszystko co w niem jest; tylko Rachab wszetecznica żywo zostanie, ona i wszyscy, którzy z nią są w domu, gdyż utaiła posłów, któreśmy byli posłali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'A wszakże się wy strzeżcie od rzeczy przeklętych, abyście się nie stali przeklęstwem, biorąc co z rzeczy przeklętych, abyście nie wprawili obozu Izraelskiego w przeklęstwo, i nie zamieszali go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Ale wszystko srebro i złoto i naczynia miedziane i żelazne, święte będą Panu; do skarbu Pańskiego złożone będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Tedy krzyczał lud, gdy zatrąbiono w trąby, albowiem gdy usłyszał lud głos trąb, krzyczał i lud wielkim głosem, i upadł mur na miejscu swem, i wszedł lud do miasta, każdy przeciw miejscu, gdzie stał, i wzięli miasto;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'I wytracili wszystko, co było w mieście, męże i niewiasty, dzieci i starce; woły też i owce, i osły ostrzem miecza pobili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Ale dwom mężom, którzy szpiegowali onę ziemię, rzekł Jozue: Wnijdźcie do domu niewiasty wszetecznej, a wywiedźcie stamtąd niewiastę, i wszystko, co jej jest, jakoście jej przysięgli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Tedy wszedłszy młodzieńcy oni, co byli wyszpiegowali ziemię, Rachabę, i ojca jej, matkę jej i bracią jej, i wszystko co było jej, i wszystkę rodzinę jej wywiedli, i zostawili je za obozem Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Ale miasto spalili ogniem, i wszystko, co w niem było; tylko srebro i złoto, i naczynie miedziane, i żelazne, złożyli do skarbu domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Rachabę także wszetecznicę, i dom ojca jej, i wszystko, co było jej, Jozue żywo zostawił, i mieszkała w pośrodku Izraela aż do teraźniejszego dnia, dla tego, iż utaiła posłów, które był posłał Jozue ku przeszpiegowaniu Jerycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'I wydał klątwę Jozue onego czasu, mówiąc: Przeklęty mąż przed Panem, któryby powstał a budował to miasto Jerycho; na pierworodnym swoim założy je, a na najmniejszym postawi bramy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'I był Pan z Jozuem, a rozchodziła się sława jego po wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Ale zgrzeszyli synowie Izraelscy przestępstwem przy rzeczach przeklętych; albowiem Achan, syn Charmiego, syna Zabdy, syna Zare, z pokolenia Juda, wziął nieco z rzeczy przeklętych; zaczem zapalił się gniew Pański przeciw synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Bo gdy posłał Jozue kilka mężów z Jerycha do Haj, które było blisko Betawen na wschód słońca od Betel, i rzekł do nich, mówiąc: Idźcie, a wyszpiegujcie ziemię; tedy szedłszy oni mężowie, wyszpiegowali Haj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'A wróciwszy się do Jozuego, rzekli mu: Niech nie ciągnie wszystek lud; około dwóch tysięcy mężów, albo około trzech tysięcy mężów niech idą, a zburzą Haj; nie trudź tam wszystkiego ludu, bo ich tam trocha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Poszło tedy około trzech tysięcy mężów z ludu, i uciekli przed mężami z Haj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'A porazili z nich mężowie z Haj około trzydziestu i sześciu mężów, goniąc je od bramy aż do Sabarym, a porazili je, gdy uciekali z góry, i dla tego rozpłynęło się serce ludu, i było jako woda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Tedy rozdarłszy Jozue odzienie swoje, upadł twarzą swoją na ziemię przed skrzynią Pańską, a leżał aż do wieczora, on i starsi Izraelscy, posypawszy prochem głowy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Zatem rzekł Jozue: Ach! Panie Panujący, przeczżeś przeprowadził lud ten za Jordan, abyś nas podał w rękę Amorejczyka na wytracenie? O byśmy byli raczej mieszkali za Jordanem!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'O Panie, cóż rzekę, ponieważ podawa Izrael tył nieprzyjaciołom swoim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Bo usłyszawszy Chananejczycy, i wszyscy obywatele tej ziemi, obtoczą nas zewsząd, a wytracą imię nasze z ziemi. I cóż to uczynisz imieniowi twemu wielkiemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Tedy rzekł Pan do Jozuego: Wstań; przeczżeś upadł na oblicze twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Zgrzeszył Izrael, i przestąpili przymierze moje, którem im przykazał; albowiem wzięli z rzeczy przeklętych, a ukradli je, i skłamali, i schowali je między naczynie swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'A dla tegoć synowie Izraelscy nie będą się mogli ostać przed nieprzyjacioły swymi, tył będą podawali nieprzyjaciołom swym, bo się zmazali rzeczą przeklętą; nie będę więcej z wami, jeźli nie wykorzenicie przeklęstwa tego z pośrodku was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Wstań, poświęć lud i rzeczy: Poświęćcie się na jutro; bo tak mówi Pan, Bóg Izraelski: Przeklęstwo jest w pośrodku ciebie, Izraelu; nie ostoisz się przed nieprzyjacioły twymi, aż odejmiecie przeklęstwo z pośrodku siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'A tak przystąpcie rano według pokoleń waszych; a pokolenie, które okaże Pan, przystąpi według familii; a familija, którą okaże Pan, przystąpi według domów; a dom, który okaże Pan, przystąpi według osób.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'A kto będzie znaleziony w przeklęstwie, będzie spalony ogniem, on, i wszystko, co jego jest, dla tego że przestąpił przymierze Pańskie, a dopuścił się niegodnej rzeczy w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Przetoż wstawszy Jozue rano, rozkazał przystępować Izraelowi według pokoleń ich; i znalazło się pokolenie Juda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'I kazał przystąpić familii Juda, i znalazła się familija Zare, i kazał przystąpić familii Zarego według osób, i znalazł się dom Zabdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'I kazał przystąpić domowi jego według osób, i znalazł się Achan, syn Charmiego, syna Zabdy, syna Zare, z pokolenia Juda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'I rzekł Jozue do Achana: Synu mój, daj proszę chwałę Panu, Bogu Izraelskiemu, i wyznaj przed nim, a oznajmij mi proszę, coś uczynił, nie taj przede mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Tedy odpowiedział Achan Jozuemu, mówiąc: Zaprawdę, jam zgrzeszył Panu, Bogu Izraelskiemu, tak a tak uczyniłem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Widziałem między łupy płaszcz babiloński jeden, piękny, i dwieście syklów srebra, i pręt złoty jeden, pięćdziesiąt syklów ważący, i pożądałem tego, i wziąłem to, a oto, te rzeczy są zakopane w ziemi, w pośród namiotu mego, a srebro pod niemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Tedy posłał Jozue posły, którzy bieżeli do namiotu, a oto te rzeczy były skryte w namiocie jego, a srebro pod niemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'A wziąwszy je z namiotu przynieśli je do Jozuego, i do wszystkich synów Izraelskich, a położyli je przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'A tak wziąwszy Jozue, i wszystek Izrael z nim, Achana, syna Zarego, i srebro, i płaszcz, i pręt złoty, i syny jego, i córki jego, i woły jego, i osły jego, i owce jego, i namiot jego, i wszystko co miał, wywiedli je na dolinę Achor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'I rzekł Jozue: Przeczżeś nas potrwożył? niechże cię też Pan zatrwoży dnia tego. I ukamionował go wszystek Izrael, i spalili je ogniem, ukamionowawszy je kamieńmi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Potem wystawili na nim wielką kupę kamieni, która trwa aż do dnia tego. I odwrócił się Pan od gniewu zapalczywości swojej; przetoż nazwane jest imię miejsca onego, dolina Achor, aż do dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Potem rzekł Pan do Jozuego: Nie bój się, ani się lękaj; weźmij z sobą wszystek lud wojenny, a wstawszy ciągnij do Haj, otom dał w ręce twoje króla Haj, i lud jego, i ziemię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'A uczynisz Hajowi i królowi jego, jakoś uczynił Jerychu i królowi jego, wszakże łupy jego, i bydła jego rozbierzecie między się; uczyńże zasadzkę na miasto z tyłu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'A tak wstał Jozue i wszystek lud waleczny, aby ciągnęli ku Haj; i przebrał Jozue trzydzieści tysięcy mężów bardzo mocnych, i posłał je nocą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'I rozkazał im, mówiąc: Patrzajcie wy, abyście uczynili zasadzkę za miastem; nie oddalajcie się od miasta daleko bardzo, a bądźcie wszyscy pogotowiu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'A ja, i wszystek lud, który ze mną jest, przyciągniemy pod miasto; a gdy oni wynijdą przeciwko nam, jako pierwej ucieczemy przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'A oni pójdą za nami, aż je uwiedziemy od miasta; bo rzeką: Uciekają przed nami, jako i pierwej, gdyż uciekać będziemy przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Tedy wy wstaniecie z zasadzki, i wyprzecie ostatek ludu z miasta, i da je Pan, Bóg wasz, w rękę waszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'A wziąwszy miasto, zapalicie je ogniem, według słowa Pańskiego uczynicie; patrzajcież, rozkazałem wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Posłał je tedy Jozue, i szli na zasadzkę; a zostali między Betel, i między Haj na zachód Hajowi; a Jozue przez onę noc został w pośrodku ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Potem wstawszy Jozue bardzo rano, obliczył lud, a szedł sam i starsi z Izraela przed ludem przeciw Haj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Wszystek też lud wojenny, który z nim był, ruszyli się, i przyciągnąwszy przyszli pod miasto, i położyli się obozem na stronie północnej ku Haj; a była dolina między nim, i między Haj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Nadto wziął około pięciu tysięcy mężów, które postawił na zasadzce między Betel, i między Haj, od strony zachodniej miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'I przybliżył się lud, to jest, wszystko wojsko, które było od północy miasta, i którzy byli na zasadzce jego od zachodu miasta; i przyciągnął Jozue onej nocy w pośrodek doliny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'I stało się, gdy je ujrzał król Haj, pospieszyli się i wstali rano, i wyszli ludzie z miasta przeciw Izraelowi ku bitwie, sam król, i wszystek lud jego, na czas naznaczony przed równinę, nie wiedząc, że zasadzka była uczyniona nań za miastem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Tedy Jozue i wszystek Izrael, jakoby od nich porażeni, uciekali drogą ku puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'I zwołany jest wszystek lud, który był w mieście, aby je gonili, i gonili Jozuego; i tak uwiedzieni byli od miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'I nie został nikt w Haj i w Betel, któryby nie wyszedł za Izraelem; i zostawili miasto otworzone, a gonili Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Tedy rzekł Pan do Jozuego: Podnieś chorągiew, którą masz w ręce swej, przeciwko Haj; bo je w ręce twoje dam. I podniósł Jozue chorągiew, którą miał w ręce swej, przeciwko miastu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'A oni, co byli na zasadzce, wstawszy prędko z miejsca swego; bieżali, gdy on podniósł rękę swą, a ubieżawszy miasto, wzięli je, i zaraz je zapalili ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'A obejrzawszy się mężowie miasta Haj ujrzeli, a oto, wstępował dym miasta ku niebu, i nie mieli miejsca do uciekania, ani tam, ani sam; bo lud, który uciekał ku puszczy, obrócił się na one, co je gonili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Tedy Jozue i wszystek lud Izraelski, widząc, iż oni, co byli na zasadzce, wzięli miasto, a iż wychodził dym z miasta, obrócili się i pobili męże miasta Haj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Oni też drudzy wyszli z miasta przeciwko nim, i obtoczyli je Izraelczycy, jedni stąd, a drudzy zowąd, i porazili je tak, iż z nich żaden nie został, ani uszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Tamże króla Haj pojmali żywo, i przywiedli go przed Jozuego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Gdy tedy Izraelczycy pobili wszystkie obywatele Haj na polu przy puszczy, tedy za nimi szli w pogoń, a polegli oni wszyscy od miecza, aż wygładzeni są; obrócili się wszyscy Izraelczycy do Haj, i wysiekli je ostrzem miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'I było wszystkich, którzy polegli dnia onego, od męża aż do niewiasty dwanaście tysięcy, wszystkich obywateli Haj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'A Jozue nie spuścił ręki swej, którą był podniósł z chorągwią, aż pobił wszystkie obywatele Haj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Tylko bydło, i łupy miasta onego rozebrali między się Izraelczycy według słowa Pańskiego, które rozkazał Jozuemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Tedy zapalił Jozue Haj, i uczynił je mogiłą wieczną, i pustynią aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'A króla Haj obwiesił na drzewie aż do wieczora; a gdy słońce zaszło, rozkazał Jozue, aby zdjęto trupa jego z drzewa, a porzucono go w samem wejściu bramy miejskiej, i namiotali nań kupę wielką kamieni, która jest aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Tedy Jozue zbudował ołtarz Panu, Bogu Izraelskiemu, na górze Hebal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'Jako był rozkazał Mojżesz, sługa Pański, synom Izraelskim, a jako napisano w księgach zakonu Mojżeszowego, ołtarz z całego kamienia, na którym żadne żelazo nie postało; i sprawowali na nim całopalenia Panu, ofiarowali też spokojne ofiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Tamże napisał na kamieniach powtórzenie zakonu Mojżeszowego, który napisał przed oblicznością synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'A wszystek Izrael, i starsi jego, i przełożeni, i sędziowie jego, stali po obu stronach skrzyni przed kapłanami Lewitami, którzy nosili skrzynię przymierza Pańskiego, tak przychodzień, jako w domu zrodzony, połowa ich przeciw górze Garyzym, a połowa ich przeciw górze Hebal, jako był przedtem rozkazał Mojżesz, sługa Pański, aby błogosławiono ludowi Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'A potem czytał wszystkie słowa zakonu, błogosławieństwo, i przeklęstwo, według wszystkiego, co napisano w księgach zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Nie było i słowa ze wszystkiego, co rozkazał Mojżesz, czego by nie czytał Jozue przed wszystkiem zgromadzeniem Izraelskiem, przed niewiastami, i przed dziatkami, i przed przychodniami, którzy mieszkali między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'A gdy usłyszeli wszyscy królowie, którzy byli za Jordanem na górach, i na równinach, i nad wszystkiem brzegiem morza wielkiego przeciw Libanowi, Hetejczyk, i Amorejczyk, i Chananejczyk, Ferezejczyk, Hewejczyk, i Jebuzejczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Zebrali się pospołu, aby walczyli przeciw Jozuemu, i przeciw Izraelowi, jednomyślnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Ale obywatele Gabaon, usłyszawszy, co uczynił Jozue Jerychowi i Hajowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Postąpili sobie i oni chytrze, a poszedłszy zmyślili się być posłami, i wzięli wory stare na osły swe, i łagwie winne stare, i potarte, i łatane;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'I obuwie stare i łatane na nogi swoje, i szaty stare na się, a wszystek chleb, co go z sobą nabrali w drogę, suchy był i spleśniały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Tedy przyszli do Jozuego, do obozu w Galgal, i rzekli do niego, i do mężów Izraelskich: Z ziemiśmy dalekiej przyszli; przetoż teraz uczyńcie z nami przymierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Ale odpowiedzieli mężowie Izraelscy Hewejczykowi: Podobno ty mieszkasz między nami, a jakoż z tobą możemy uczynić przymierze?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'A oni rzekli do Jozuego: Słudzy twoi jesteśmy. I rzekł do nich Jozue: Coście wy zacz, a skądeście przyszli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'I odpowiedzieli mu: Z ziemi dalekiej bardzo przyszli słudzy twoi w imieniu Pana, Boga twego; bośmy słyszeli sławę jego, i wszystko, co uczynił w Egipcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'I wszystko, co uczynił dwom królom Amorejskim, którzy byli za Jordanem, Sehonowi królowi Hesebon, i Ogowi królowi Basan, którzy mieszkali w Astarot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'I rozkazali nam starsi nasi, i wszyscy obywatele ziemi naszej, mówiąc: Nabierzcie sobie żywności na drogę, a idźcie przeciwko nim, i mówcie im: Słudzy wasi jesteśmy, przetoż teraz uczyńcie z nami przymierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Ten chleb nasz ciepłyśmy na drogę wzięli z domów naszych tego dnia, gdyśmy wyszli, abyśmy szli do was; a teraz oto wysechł, i popleśniał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'I te łagwie winne, któreśmy byli napełnili, były nowe, a oto się popękały; także te szaty nasze, i obuwie nasze zwiotszały dla bardzo dalekiej drogi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'A tak wzięli oni mężowie Izraelscy z onej żywności ich, a ust się Pańskich nie pytali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Tedy z nimi uczynił Jozue pokój, i postanowił z nimi przymierze, aby ich zachował przy żywocie; także przysięgły im książęta zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Ale po trzech dniach po uczynieniu z nimi przymierza, usłyszeli, że blisko ich byli, a iż w pośrodku ich mieszkali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'A ruszywszy się synowie Izraelscy przyciągnęli do miast ich dnia trzeciego, a miasta ich te były: Gabaon, i Kafira, i Beerot, i Karyjatyjarym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'I nie wytracili ich synowie Izraelscy; albowiem przysięgły im były książęta zgromadzenia przez Pana, Boga Izraelskiego, skąd szemrało wszystko zgromadzenie przeciw książętom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'I rzekły wszystkie książęta do całego zgromadzenia: Myśmy im przysięgli przez Pana, Boga Izraelskiego; przetoż teraz nie możemy się ich tknąć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'To im uczynimy, a zachowamy je żywo, iżby nie przyszło na nas rozgniewanie dla przysięgi, którąśmy im przysięgli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Nadto rzekły do nich książęta: Niech żyją, a niech rąbią drwa, i niech noszą wodę wszystkiemu zgromadzeniu; i przestali na tem, jako im powiedziały książęta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Potem wezwał ich Jozue, i rzekł do nich, mówiąc: Przeczżeście nas oszukali, powiadając: Dalekimiśmy od was bardzo, a wy w pośrodku nas mieszkacie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'A tak teraz przeklęci jesteście, i nie ustaną z was słudzy, i rąbiący drwa, i noszący wodę do domu Boga mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Którzy odpowiedzieli Jozuemu, i rzekli: Zapewne oznajmiono było sługom twoim, jako był rozkazał Pan, Bóg twój, Mojżeszowi słudze swemu, aby wam dał wszystkę ziemię, a iżby wygładził wszystkie mieszkające w tej ziemi przed twarzą waszą; przetoż baliśmy się bardzo o żywot nasz przed wami, i uczyniliśmy tę rzecz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'A teraz otośmy w rękach twoich; coć się dobrego i słusznego widzi uczynić z nami, uczyń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'I uczynił im tak, a wybawił je z rąk synów Izraelskich, że ich nie pobili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'I postanowił je Jozue dnia onego, aby rąbali drwa, i nosili wodę zgromadzeniu, i do ołtarza Pańskiego aż do tego dnia, na miejscu, które by obrał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'A gdy usłyszał Adonisedek, król Jerozolimski, iż wziął Jozue Haj, i zburzył je, (bo jako uczynił Jerychowi i królowi jego, tak uczynił Hajowi i królowi jego,) a iż uczynili pokój obywatele Gabaon z Izraelem, i mieszkają w pośrodku ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Tedy się uląkł bardzo, przeto że miasto wielkie było Gabaon, jako jedno z miast królewskich, a że było większe niż Haj, a wszyscy mężowie jego waleczni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Przetoż posłał Adonisedek, król Jerozolimski, do Hohama, króla Hebron, i do Faran, króla Jerymota, i do Jafija, króla Lachys, i do Dabir, króla Eglon, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Przyjedźcie do mnie, a dajcie mi pomoc, abyśmy pobili Gabaonity, którzy uczynili pokój z Jozuem, i z syny Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Zebrało się tedy, a wyciągnęło pięć królów Amorejskich, król Jerozolimski, król Hebron, król Jerymot, król Lachys, król Eglon, sami, i wszystkie wojska ich, i położyli się obozem u Gabaon, i dobywali go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Tedy posłali obywatele Gabaon do Jozuego, i do obozu w Galgal, mówiąc: Nie zawściągaj ręki swej od sług twoich; przyciągnij do nich rychło, a wybaw nas i pomóż nam; boć się zebrali przeciwko nam wszyscy królowie Amorejscy, którzy mieszkają po górach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Ruszył się tedy Jozue z Galgal, sam i wszystek lud wojenny z nim, i wszyscy mężowie waleczni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, '(Bo był rzekł Pan do Jozuego: Nie bój się ich; albowiem w ręce twoje podałem je, a nie ostoi się żaden z nich przed tobą.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'I przypadł na nie Jozue nagle; bo całą noc ciągnął z Galgal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'I potrwożył je Pan przed obliczem Izraela, który je poraził porażką wielką w Gabaon, i gonił je drogą, którą chodzą ku Betoron, a bił je aż do Aseka i aż do Maceda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'I stało się, gdy uciekali przed Izraelem, bieżąc z góry do Betoron, że Pan spuścił na nie kamienie wielkie z nieba aż do Aseka, i umierali; więcej ich pomarło od kamienia gradowego, niż ich pobili synowie Izraelscy mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Tedy mówił Jozue do Pana, dnia, którego podał Pan Amorejczyka w ręce synom Izraelskim, i rzekł przed oczyma Izraela: Słońce w Gabaon zastanów się, a miesiącu w dolinie Ajalon!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'I zastanowiło się słońce, a miesiąc stanął, aż się lud pomścił nad nieprzyjacioły swymi. Izali to nie jest napisano w księgach sprawiedliwego? Tedy stanęło słońce w pośród nieba, a nie pospieszyło się zachodzić, jakoby przez cały dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'I nie był takowy dzień przedtem, ani potem, w któryby usłuchać miał Pan głosu człowieczego, bo Pan walczył za Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Potem się wrócił Jozue, i wszystek Izrael z nim, do obozu do Galgal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'A uciekło było onych pięć królów, i skryli się w jaskinią przy Maceda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'I dano znać Jozuemu, mówiąc: Znaleziono pięć królów, którzy się pokryli w jaskini w Maceda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'I rzekł Jozue: Przywalcie kamienie wielkie do dziury jaskini, a postawcie u niej męże, aby ich strzegli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'A wy nie stójcie, gońcie nieprzyjacioły wasze, a bijcie ostatek ich, ani im dajcie uchodzić do miast ich; boć je podał Pan, Bóg wasz, w rękę waszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'A gdy przestał Jozue z syny Izraelskimi bić ich porażką bardzo wielką, aż je do szczętu wytracili, a którzy żywo zostali z nich, uszli do miast obronnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Tedy wrócił się wszystek lud zdrowo do obozu, do Jozuego w Maceda, a nie ruszył przeciwko synom Izraelskim nikt językiem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Potem rzekł Jozue: Otwórzcie tę dziurę jaskini, a wywiedźcie do mnie tych pięciu królów z jaskini.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'I uczynili tak, i wywiedli do niego pięciu królów onych z jaskini, króla Jerozolimskiego, króla Hebron, króla Jerymot, króla Lachys, króla Eglon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'A gdy wywiedli one króle do Jozuego, tedy przyzwał Jozue wszystkich mężów Izraelskich, i rzekł do rotmistrzów, mężów walecznych, którzy z nim chodzili: Przystąpcie sam, a nastąpcie nogami waszemi na szyje tych królów; którzy przystąpiwszy nastąpili nogami swemi na szyje ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Zatem rzekł do nich Jozue: Nie bójcie się, ani się lękajcie; zmacniajcie się, i mężnie sobie poczynajcie; boć tak uczyni Pan wszystkim nieprzyjaciołom waszym, przeciw którym walczycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Potem pobił je Jozue, i pomordował je, i zawiesił je na pięciu drzewach, a wisieli na drzewach aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'A gdy zaszło słońce, rozkazał Jozue, że je złożono z drzewa, i wrzucono je do jaskini, w której się byli skryli, a zawalono kamieńmi wielkiemi dziurę u jaskini, które tam są jeszcze i do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Tegoż dnia wziął Jozue Maceda, i wysiekł je ostrzem miecza, i króla ich zamordował wespół z nimi, i wszelką duszę, która była w niem; nie zostawił żadnego żywo, i uczynił królowi Maceda, jako uczynił królowi Jerycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Potem ciągnął Jozue, i wszystek Izrael z nim, z Maceda do Lebny, i dobywał Lebny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'A podał Pan i ono w ręce Izraela, i króla jego, i wysiekł je ostrzem miecza, i wszelką duszę, która była w niem; nie zostawił w niem żadnego żywo, i uczynił królowi jego, jako uczynił królowi Jerycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Potem ciągnął Jozue, i wszystek Izrael z nim, z Lebny do Lachys, a położywszy się przy niem obozem, dobywał go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'I podał Pan Lachys w ręce Izraela, i wziął je dnia drugiego, i wysiekli je ostrzem miecza, i wszelką duszę, która była w niem, tak właśnie jako uczynił Lebnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Tedy przyszedł Horam, król Gazer, na ratunek Lachysowi, ale go poraził Jozue, i lud jego, tak iż nie zostawił mu żadnego żywo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Potem ciągnął Jozue, i wszystek Izrael z nim, z Lachys do Eglon, i położyli się obozem przeciwko niemu, i dobywali go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Które wziąwszy onegoż dnia, wysiekli je ostrzem miecza, i wszelką duszę, która była w niem, onegoż dnia zabił, tak właśnie jako uczynił Lachys.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Potem się ruszył Jozue, i wszystek Izrael z nim, z Eglonu do Hebronu, i dobywał go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'I wzięli je, a wysiekli je ostrzem miecza, i króla jego, i wszystkie miasta jego, i wszelką duszę, która była w niem; nie zostawił żadnego żywo, tak właśnie jako uczynił Eglonowi, i wytracił je, i wszelką duszę, która w niem była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Stamtąd obrócił się Jozue, i wszystek Izrael z nim, do Dabir, i dobywał go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'I wziął je, i króla jego, i wszystkie miasta jego, i wysiekli je ostrzem miecza, i pomordował wszystkie dusze, które w niem były; nie zostawił żadnego żywo; jako uczynił Hebronowi tak uczynił Dabirowi i królowi jego, i jako uczynił Lebnie i królowi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'A tak pobił Jozue wszystkę ziemię górną, i południową, i polną, i podgórną, i wszystkie króle ich; nie zostawił żadnego żywo, ale wszystkie dusze wytracił, jako mu był przykazał Pan, Bóg Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'I poraził je Jozue od Kades Barny aż do Gazy, i wszystkę ziemię Gosen, i aż do Gabaon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'A wszystkie te króle, i ziemie ich, wziął Jozue jednym razem; albowiem Pan, Bóg Izraelski, walczył za Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Zatem się wrócił Jozue i wszystek Izrael z nim do obozu do Galgal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'To gdy usłyszał Jabin, król Hasor, posłał do Johaba, króla Madon, i do króla Symron, i do króla Achsaf,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'I do królów, którzy byli na północy, na górach i na polach, na południe Cynerot, i w równinach, i w krainach Dor, ku zachodowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'Do Chananejczyka na wschód i na zachód słońca, i do Amorejczyka, i do Hetejczyka, i do Ferezejczyka, i do Jebuzejczyka po górach, i do Hewejczyka pod górą Hermon, w ziemi Maswa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'I wyciągnęli sami, i wszystkie wojska ich z nimi, lud wielki, jako piasek, który jest na brzegu morskim, i koni i wozów bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'A zgromadziwszy się wszyscy oni królowie przyszli, i położyli się pospołu obozem u wód Merom, aby zwiedli bitwę z Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'I rzekł Pan do Jozuego: Nie bój się ich, albowiem jutro o tym czasie Ja podam te wszystkie pobite przed Izraelem; koniom ich żyły poderzniesz, a wozy ich ogniem spalisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Wyciągnął tedy Jozue, i wszystek lud waleczny z nim, przeciwko nim ku wodom Merom z nagła, i uderzyli na nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'I podał je Pan w rękę Izraelowi, i porazili je, a gonili je aż do Sydonu wielkiego, i aż do wód gorących, i aż do pola Masfa na wschód słońca, i pobili je, tak iż jednego z nich nie zostawili żywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'I uczynił im Jozue, jako mu był rozkazał Pan; koniom ich żyły poderznął, a wozy ich popalił ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Potem wróciwszy się Jozue tego czasu wziął Hasor, a króla jego zabił mieczem; a Hasor było przedtem głową wszystkich tych królestw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Zabili też każdą duszę, która była w niem, ostrzem miecza mordując, tak iż nie zostało nic żywego; a Hasor spalił ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Także uczynił wszystkim miastom królów onych, i wszystkie króle ich pojmał Jozue, i pobił je ostrzem miecza, mordując je, jako był rozkazał Mojżesz, sługa Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Tylko tych wszystkich miast, które były obronne, nie palił Izrael, oprócz samego Hasora, które spalił Jozue.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Wszystkie też łupy miast onych, i bydła, pobrali sobie synowie Izraelscy, tylko wszystkie ludzie zabijali ostrzem miecza, aż je wytracili, nie zostawując nikogo żywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Jako był rozkazał Pan Mojżeszowi, słudze swemu, tak rozkazał Mojżesz Jozuemu; tak też uczynił Jozue, nie opuścił niczego ze wszystkiego, co był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'A tak wziął Jozue wszystkę onę ziemię górną, i wszystkę na południe leżącą, i wszystkę ziemię Gosen, i równiny, i pola, i górę Izrael z równiną jej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Od góry Halak, która idzie ku Seir, aż do Baalgad, w równinie Libańskiej pod górą Hermon; i wszystkie króle ich pojmał, i poraził je, i pozabijał je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Przez wiele dni prowadził Jozue z onymi wszystkimi królami wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'A nie było miasta, które by pokój uczyniło z syny Izraelskimi, oprócz Hewejczyków, którzy mieszkali w Gabaon; wszystkie insze wzięli przez wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Albowiem od Pana się to stało, że zatwardził serca ich, aby szli ku bitwie przeciw Izraelowi, żeby je wyniszczył, nie mając nad nimi miłosierdzia, ale żeby je wytracił, jako był rozkazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'I ciągnął Jozue onegoż czasu, i wybił syny Enakowe z gór, z Hebronu, z Dabiru, z Anab, i ze wszystkich gór Judzkich, i ze wszystkich gór Izraelskich, pospołu z miasty ich wykorzenił je Jozue.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Nie został nikt z Enakitów, w ziemi synów Izraelskich; tylko w Gazie, w Gad, i w Azdod zostali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Wziął tedy Jozue wszystkę onę ziemię, tak jako mówił Pan do Mojżesza: i podał ją Jozue w dziedzictwo Izraelowi według działów ich, i według pokolenia ich, a uspokoiła się ziemia od wojen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'A ci są królowie ziemi, które pobili synowie Izraelscy, i posiedli ziemię ich za Jordanem ku wschodowi słońca, od potoku Arnon aż do góry Hermon, i wszystkę równinę ku wschodowi słońca:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sehon, król Amorejski, który mieszkał w Hesebon, a panował od Aroer, które leży nad brzegiem potoku Arnon, i od połowy tegoż potoku i połowy Galaadu aż do potoku Jabok, gdzie są granice synów Ammonowych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'A od równin aż do morza Cynerot na wschód słońca, i aż do morza pustyni, do morza słonego na wschód, idąc ku Betsemot, i od południa pod górę Fazga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'I granice Oga, króla Basańskiego, który był pozostał z Refaimów, a mieszkał w Astarot i w Edrej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Który też panował na górze Hermon, i w Selecha, i we wszystkiem Basan, aż do granic Gessurytów, i Mahachatytów, i nad połową Galaad ku granicy Sehona, króla Hesebońskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mojżesz, sługa Pański, i synowie Izraelscy, pobili je; i podał tę ziemię Mojżesz, sługa Pański, w dziedzictwo Rubenitom, i Gadytom, i połowie pokolenia Manasesowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Ci też są królowie ziemi, które pobił Jozue, i synowie Izraelscy za Jordanem na zachód słońca, od Baalgad na polu Libańskiem, i aż do Halak, która idzie ku Seir, którą podał Jozue pokoleniom Izraelskim w dziedzictwo według działu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Na górach, i na równinach, i w polach, i w niżynach, i na puszczy, i na południe ziemi Hetejczyka, Amorejczyka, i Chananejczyka, Ferezejczyka, Hewejczyka, i Jebuzejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Król Jerycha jeden; król Haj, które jest w bok Betel, jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Król Jeruzalem jeden; król Hebron jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Król Jerymot jeden; król Lachys jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Król Heglon jeden; król Gazer jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Król Dabir jeden; król Gader jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Król Horma jeden; król Hered jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Król Lebni jeden; król Adullam jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Król Maceda jeden; król Betel jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Król Taffua jeden; król Hefer jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Król Afek jeden; król Saron jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Król Madon jeden; król Hasor jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Król Symron Meron jeden; król Aksaf jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Król Tenach jeden; król Mageddo jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Król Kades jeden; król Jachanam z Karmelu jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'Król Dor z krainy Dor jeden; król Goim w Galgal jeden;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Król Torsa jeden. Wszystkich królów trzydzieści i jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'I zstarzał się Jozue, a był zeszły w leciech. I rzekł Pan do niego: Tyś się zstarzał, a zszedłeś w leciech, a ziemi zostawa bardzo wiele ku posiadaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Tać jest ziemia, która pozostawa: Wszystkie granice Filistynów, i wszyscy Gessurytowie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Od Nilu, który oblewa Egipt, aż do granicy Akaronu na północy, przynależy Chananejczykowi, pięcioro księstw Filistyńskich; Asackie, i Asdodziejskie, Askalońskie, Getejskie, i Akaronicki, i Hawejczycy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Od południa wszystka ziemia Chananejska, i Mara, które jest Sydończyków aż do Afeka, i aż do granicy Amorejczyka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'I ziemia Giblitów ze wszystkim Libanem na wschód słońca, od Baalgad pod górę Hermon, aż gdzie chodzą do Emat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Wszystkie mieszkające na górach od Libanu aż do wód gorących, wszystkie Sydończyki Ja wypędzę przed syny Izraelskimi; tylko ją podziel Izraelitom w dziedzictwo, jakom ci rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Przetoż teraz rozdziel tę ziemię w dziedzictwo, dziewięciorgu pokoleniu, i połowie pokolenia Manasesowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Gdyż z drugą połową Rubenitowie i Gadytowie wzięli dziedzictwo swoje, które im dał Mojżesz za Jordanem na wschód słońca, jako im dał Mojżesz, sługa Pański;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Od Aroer, które jest nad brzegiem potoku Arnon, i miasto, które jest w pośrodku potoku, i wszystkę równinę Medeba aż do Dybon;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'I wszystkie miasta Sehona, króla Amorejskiego, który królował w Hesebon, aż do granicy synów Ammonowych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'Także Galaad, i granice Gessurytów, i Machatytów, i wszystkę górę Hermon, i wszystko Basan aż do Salecha;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Wszystko królestwo Oga w Basan, który królował w Astarot, i w Edrej; ten był pozostał z Refaimitów, a pobił je Mojżesz i wygładził je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Ale nie wygnali synowie Izraelscy Gessurytów i Machatytów; przetoż mieszkał Gessur i Machat w pośród Izraelczyków aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Tylko pokoleniu Lewi nie dał dziedzictwa; ofiary ogniste Pana Boga Izraelskiego są dziedzictwem jego, jako mu powiedział Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'A tak oddał Mojżesz pokoleniu synów Rubenowych dziedzictwo według familii ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'I była granica ich od Aroer, które jest nad brzegiem potoku Arnon, i miasto, które jest w pośród potoku, i wszystka równina ku Medeba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesebon, i wszystkie miasta jego, które były w równinie; Dybon i Bamot Baal, i Bet Baal Meon;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'I Jassa, i Cedymot, i Mefaat;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'I Karyjataim, i Sebama, i Saratasar na górze w dolinie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'I Betfegor, i Asdod, Fazga, i Betyjesymot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'Wszystkie też miasta w równinie, i wszystko królestwo Sehona, króla Amorejskiego, który królował w Hesebon, którego zabił Mojżesz, i książęta Madyjańskie Ewi, i Recem, i Sur, i Hur, i Reba; książęta Sehonowe, obywatele ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'I Balaama, syna Boerowego, wieszczka, zabili synowie Izraelscy mieczem z innymi pobitymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Była tedy granica synów Rubenowych Jordan z granicami swemi. Toć jest dziedzictwo synów Rubenowych według domów ich, miast i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Dał też Mojżesz pokoleniu Gad, synom Gadowym, według domów ich dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'A były ich granice Jazer i wszystkie miasta Galaad, i połowa ziemi synów Ammonowych aż do Aroer, które jest przeciw Rabba;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'I od Hesebon aż do Ramat Massa i Betonim, a od Mahanaim aż do granicy Dabir.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'W dolinie też Beram, i Betnimra, i Sochot, i Safon, ostatek królestwa Sehona, króla Hesebońskiego, Jordan i pogranicze jego aż do końca morza Cynneret za Jordanem na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Toć jest dziedzictwo synów Gad według domów ich, miast i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Nadto dał Mojżesz osiadłość połowie pokolenia Manasesowego, i była ta połowa pokolenia synów Manasesowych według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Była granica ich od Machanaim wszystko Basan i wszystko królestwo Oga, króla Basańskiego, i wszystkie wsi Jairowe, które są w Basan, sześćdziesiąt miast.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'I połowę Galaad, i Astarot, i Erdej, miasta królestwa Oga w Basan, dał synom Machyra, syna Manasesowego, połowie synów Machyrowych według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Teć są osiadłości, które podzielił Mojżesz w polach Moabskich za Jordanem przeciw Jerychu na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Ale pokoleniu Lewi nie dał Mojżesz dziedzictwa; bo Pan, Bóg Izraelski, sam jest dziedzictwem ich, jako im powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'A toć jest, co dziedzictwem wzięli synowie Izraelscy w ziemi Chananejskiej, a co prawem dziedzicznem oddali im w osiadłość Eleazar kapłan i Jozue, syn Nunów, i przedniejsi z ojców z pokolenia synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Losem dzieląc dziedzictwo ich, jako był rozkazał Pan przez Mojżesza, dziewięciorgu pokoleniu i połowie pokolenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Albowiem Mojżesz był oddał dziedzictwo dwom pokoleniom i połowie pokolenia za Jordanem; ale Lewitom nie dał był dziedzictwa między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Bo było synów Józefowych dwa pokolenia, Manasesowe i Efraimowe; ani dali działu Lewitom w ziemi, oprócz miast ku mieszkaniu, z przedmieściami ich dla bydła ich i dla trzód ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Jako rozkazał Pan Mojżeszowi, tak uczynili synowie Izraelscy, i podzielili ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Tedy przyszli synowie Judowi do Jozuego w Galgal; i rzekł do niego Kaleb, syn Jefuna Kenezejskiego: Ty wiesz, co mówił Pan do Mojżesza, męża Bożego, o mnie i o tobie w Kades Barnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Czterdzieści mi lat było, gdy mnie słał Mojżesz, sługa Pański, z Kades Barny ku przeszpiegowaniu ziemi, i odniosłem mu tę rzecz, jako było w sercu mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Lecz bracia moi, którzy chodzili ze mną, skazili serce ludowi; alem ja przecię szedł statecznie za Panem, Bogiem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'I przysiągł Mojżesz dnia onego, mówiąc: Zaiste ziemia, którą deptała noga twoja, przyjdzie tobie w dziedzictwo, i synom twoim aż na wieki, przeto żeś statecznie chodził za Panem, Bogiem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'A teraz oto przedłużył żywota mego Pan, jako powiedział; już są czterdzieści i pięć lat od onego czasu, jako to mówił Pan do Mojżesza, a jako chodzili Izraelczycy po puszczy; a teraz oto ja dziś mam osiemdziesiąt i pięć lat:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'A jeszcze i dziś takiem duży, jakom był w on czas, gdy mię wysłał Mojżesz; a jako moc moja była na on czas, taka jest moc moja i teraz ku bojowaniu, i ku wychodzeniu i przychodzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'A tak teraz daj mi tę górę, o której powiedział Pan dnia onego; boś ty słyszał dnia onego, iż tam są Enakitowie, i miasta wielki a obronne; będzieli Pan ze mną, wypędzę je, jako mi obiecał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'I błogosławił mu Jozue, a dał Hebron Kalebowi, synowi Jefunowemu, w dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'A tak dostał się Hebron Kalebowi, synowi Jefuna Kenezejskiego, w dziedzictwo aż do dnia tego, przeto że statecznie chodził za Panem, Bogiem Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'A zwano przedtem Hebron miasto Arba, który Arba był człowiekiem wielkim między Enakity; i uspokoiła się ziemia od wojen');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'I był los pokolenia synów Judowych według domów ich przy granicach Edom, i przy puszczy Syn na południe od ostatecznej granicy południowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'A była ich granica od południa, od końca morza słonego, i od skały, która jest ku południowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'I wychodzi ku południowi, ku pagórkowi niedźwiadkowemu, a ciągnie się aż do Syn; a idąc od południa do Kades Barny bieży aż ku Efronowi, i ciągnie się aż do Adar, obtaczając Karkaa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Stamtąd idąc do Asemona idzie ku rzece Egipskiej, a idzie koniec tych granic na zachód; tać będzie granica na południu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Granica zasię od wschodu słońca jest morze słone aż do końca Jordanu, a granica z strony północnej jest od skały morskiej, od końca Jordanu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'A ciągnie się ta granica do Betaglu, i bieży od północy aż do Betaraba; a stamtąd idzie ta granica aż do kamienia Boen, syna Rubenowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Idzie także ta granica do Dabir od doliny Achor, a ku północy się udawa do Galgal, które jest przeciw górze, gdzie wstępują do Adommim, która jest na południe od rzeki, a idzie ta granica do wód Ensemes, a kończy się u studnicy Rogiel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Bieży też ta granica przez dolinę syna Hennomowego po bok Jebuzejczyka od południa, co jest Jeruzalem. Stamtąd bieży ta granica na wierzch góry, która jest przeciwko dolinie Hennom na zachód, a która jest na końcu doliny Refaimitów na północy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Obtacza też ta granica od wierzchu góry aż do źródła wody Neftoa, i bieży aż do miast góry Hefron; potem się ciągnie ta granica ku Baala, które jest Karyjatyjarym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Potem kołem bieży ta granica od Baala na zachód do góry Seir, a stamtąd przechodzi po bok góry Jarym od północy, która jest Cheslon, i spuszcza się do Betsemes, i przychodzi do Tamna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'I wychodzi ta granica po bok Akaronu na północy, a idzie kołem ta granica, aż do Sechronu, i bieży przez górę Baala; stamtąd wychodzi do Jabneel, i kończą się te granica u morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'A granica zachodnia jest przy morzu wielkiem, i przy granicach jego; tać jest granica synów Juda w okrąg podług domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Ale Kalebowi synowi Jefunowemu, dał Jozue dział między syny Juda, jak Pan powiedział Jozuemu, miasto Arba, ojca olbrzymów, to jest Hebron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'I wypędził stamtąd Kaleb trzech synów Enakowych: Sesaja, i Ahymana, i Talmaja, syny Enakowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'A wyszedł stamtąd do mieszkających w Dabir, które zwano przedtem Karyjatsefer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'I rzekł Kaleb: Kto by dobył Karyjatsefer, a wziął je, tedy mu dam Achsę, córkę swoję, za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'I dobył go Otonijel, syn Keneza, brata Kalebowego; i dał mu Achsę, córkę swoję, za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'I stało się, gdy ona przyszła do niego, namawiała go, aby prosił ojca jej o pole; przetoż zsiadła z osła, i rzekł do niej Kaleb: Cóż ci?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'A ona odpowiedziała: Daj mi błogosławieństwo; gdyżeś mi dał ziemię suchą, przydaj mi też źródła wód. I dał jej źródła wyższe, i źródła dolne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Toć jest dziedzictwo pokolenia synów Judowych według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'I były miasta w granicach pokolenia synów Judowych podle granicy Edom ku południowi: Kabseel, i Eder, i Jagur.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'I Cyna, i Dymona, i Adada;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'I Kades, i Hasor, i Jetnan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'I Zyf, i Telem, i Balot;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'I Hasor Hadata, i Karyjot Chesron, toć jest Hasor;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, i Sama, i Molada;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'I Asorgadda, i Hessemon, i Betfalet;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'I Hasersual, i Beersaba, i Bazotyja;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, i Ijim, i Esem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'I Eltolad, i Kesyl, i Horma;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'I Syceleg, i Medemena, i Sensenna;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'I Lebaot, i Selim, Ain, i Remmon; wszystkich miast dwadzieścia i dziewięć, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'W równinach zaś Estaol, i Sarea, i Asena;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'I Zanoe, i Engannim, Tepnach, i Enaim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jerymot, i Adullam, Socho, i Aseka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'I Saraim, i Adytaim, i Gedera, i Gederotaim, miast czternaście, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Sanany, i Hadasa, i Mygdalgad;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'I Delean, i Mesfa, i Jektel;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lachys, i Bassekat, i Eglon;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'I Chabbon, i Lachmas, i Chytlis;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'I Kiederot, Bet Dagon, i Naama, i Maceda, miast szesnaście, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Labana, i Eter, i Asan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'I Iftach, i Esna, i Nesyb;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'I Ceila, i Achzyb, i Maresa, miast dziewięć, i wsi ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Akkaron, i miasteczka jego, i wioski jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Od Akkaronu aż do morza wszystko, co leży po bok Asotu, i ze wsiami ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Azot, miasteczka jego, i wsi jego; Gaza, miasteczka jego, i wsi jego, aż do potoku Egipskiego, i morze wielkie za granicą jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'A na górze leżą Sam, i Jeter, i Soko;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'I Danna, i Karyjatsenna, które jest Dabir;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'I Anab, i Istemo, i Anim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'I Gosen, i Holon, i Gilo, miast jedenaście, i wsi ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, i Duma, i Esaan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'I Janum, i Bet Tafua, i Afeka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'I Chumta, i Karyjat Arbe, toć jest Hebron, i Syjor, miast dziewięć, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel, i Zyf, i Juta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'I Jezrael, i Jukiedam, i Zanoe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kain, Gabaa, i Tamna, miast dziesięć, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Betsur i Giedor;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'I Maret, i Bet Anot, i Eltekon, miast sześć, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Karyjat Baal, które jest Karyjatyjarym, i Rabba, miasta dwa, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'A na puszczy: Bet Araba, Meddyn, i Sechacha;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'I Nebsan, i miasto Soli, i Engaddy, miast sześć, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Ale Jebuzejczyka, obywatela Jeruzalemskiego, nie mogli synowie Judowi wypędzić; przetoż mieszkał Jebuzejczyk z syny Juda w Jeruzalemie aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Padł też los synom Józefowym od Jordanu ku Jerychu przy wodach Jerycha na wschód słońca, puszcza, która idzie od Jerycha przez górę Betel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'A wychodzi od Betel do Luzy, a idzie do granicy Archy, do Attarot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Potem się ciągnie ku morzu do granicy Jaflety, aż do granicy Bet Horonu dolnego, i aż do Gazer, a kończy się aż u morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'I wzięli dziedzictwo synowie Józefowi, Manase i Efraim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'A była granica synów Efraimowych według domów ich; była mówię granica dziedzictwa ich na wschód słońca od Attarot Adar aż do Bet Horon wyższego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'I wychodzi ta granica do morza od Machmeta ku północy, a idzie kołem ta granica pod wschód słońca do Tanat Selo, i przechodzi ją od wschodu aż do Janoe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'I ciągnie się od Janoe do Attarot i Naarata, a przychodzi do Jerycha, a wychodzi ku Jordanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Od Tafua bieży ta granica ku zachodowi do potoku Kana, a kończy się przy morzu. Toć jest dziedzictwo pokolenia synów Efraimowych według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Miasta też oddzielone synom Efraimowym były w pośród dziedzictwa synów Manasesowych, wszystkie miasta i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'I nie wygnali Chananejczyka, mieszkającego w Gazer; i mieszkał Chananejczyk w pośrodku Efraimitów aż do dnia tego, i hołdował im, dań dawając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Padł też los pokoleniu Manasesowemu (bo on jest pierworodny Józefów.) Machyrowi pierworodnemu Manasesowemu, ojcu Galaada, przeto, że był mężem walecznym, i dostał mu się Galaad i Basan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Dostało się też innym synom Manasesowym według domów ich, synom Abiezer, i synom Helek, i synom Esryjel, i synom Sychem, i synom Hefer, i synom Semida. Cić są synowie Manasesowi, syna Józefowego, mężczyzny według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Ale Salfaad, syn Heferów, syna Galaadowego, syna Machyrowego, syna Manasesowego, nie miał synów, jedno córki, a te imiona córek jego: Machla, i Noa, Hegla, Melcha, i Tersa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Te przyszedłszy przed Eleazara kapłana, i przed Jozuego, syna Nunowego, i przed książęta, rzekły: Pan rozkazał Mojżeszowi, aby nam dał dziedzictwo w pośród braci naszych; i dał im Jozue według rozkazania Pańskiego dziedzictwo w pośrodku braci ojca ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'I przypadło sznurów na Manasesa dziesięć, oprócz ziemi Galaad i Basan, które były za Jordanem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Albowiem córki Manasesowe otrzymały dziedzictwo między syny jego, a ziemia Galaad dostała się drugim synom Manasesowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'I była granica Manasesowa od Aser do Machmatat, które jest przeciwko Sychem, a idzie granica ta po prawej stronie do mieszkających w En Tafua.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, '(Manasesowa była ziemia Tafua; ale Tafua przy granicy Manasesowej była synów Efraimowych.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'I bieży ta granica do potoku Kana na południe tegoż potoku; a miasta Efraimitów są między miasty Manasesowemi; ale granica Manasesowa idzie od północy onego potoku, a kończy się u morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Na południe był dział Efraimów, a na północy Manasesów, a morze jest granica jego; a w pokoleniu Aser schodzą się na północy, a w Isaschar na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'I dostało się Manasesowi w pokoleniu Isaschar i w Aser, Betsan i miasteczka jego, i Jeblaam i miasteczka jego; przytem mieszkający w Dor i miasteczka ich, także mieszkający w Endor i miasteczka ich; i mieszkający też w Tanach i miasteczka ich, i mieszkający w Magiedda i miasteczka ich; trzy powiaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Ale nie mogli synowi Manasesowi wypędzić z onych miast obywateli; przetoż począł Chananejczyk mieszkać w onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'A gdy się zmocnili synowie Izraelscy, uczynili Chananejczyka hołdownikiem: ale go nie wygnali do szczętu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Tedy rzekli synowie Józefowi do Jozuego, mówiąc: Przeczżeś nam dał w dziedzictwo los jeden, i sznur jeden? a myśmy lud wielki i dotąd błogosławił nam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'I rzekł do nich Jozue: Jeźliś jest ludem wielkiem, idźże do lasu, a wysiecz sobie tam miejsca w ziemi Ferezejskiej, i Refaimskiej, jeźlić ciasna góra Efraimowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Któremu odpowiedzieli synowie Józefowi: Nie dosyć nam na tej górze; do tego wozy żelazne są u wszystkich Chananejczyków, którzy mieszkają w ziemi nadolnej, i u tych, którzy mieszkają w Betsan i w miasteczkach jego, także u tych, którzy mieszkają w dolinie Jezreel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'RZekł tedy Jozue do domu Józefowego, do Efraima i do Manasesa, mówiąc: Ludeś ty wielki, i moc twoja wielka, nie będziesz miał tylko losu jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Ale górę będziesz miał; a iż tam jest las, tedy go wyrąbiesz, i będziesz miał granice jego; bo wypędzisz Chananejczyka, choć ma wozy żelazne i choć jest potężny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Tedy się zebrało wszystko zgromadzenie synów Izraelskich do Sylo, i postawili tam namiot zgromadzenia, gdy ziemia była od nich opanowana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'A zostało było z synów Izraelskich, którym było nie oddzielono dziedzictwa ich, siedmioro pokolenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Tedy rzekł Jozue do synów Izraelskich: Dokądże zaniedbywacie wnijść, abyście posiedli ziemię, którą wam dał Pan, Bóg ojców waszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Obierzcie między sobą po trzech męża z każdego pokolenia, które poślę, aby wstawszy obeszli ziemię, a rozpisali ją według dziedzictwa ich, potem się wrócą do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'I rozdzielą ją na siedem części: Juda stanie na granicach swoich od południa, a dom Józefów stanie na granicach swoich od północy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Wy tedy rozpiszecie ziemię na siedem części a przyniesiecie tu do mnie: tedy wam rzucę los tu przed Panem, Bogiem naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Albowiem Lewitowie nie mają działu między wami, gdyż kapłaństwo Pańskie jest dziedzictwo ich; ale Gad, i Ruben, i połowa pokolenia Manasesowego wzięli dziedzictwa swe za Jordanem na wschód słońca, które im oddał Mojżesz, sługa Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Przetoż wstawszy mężowie oni odeszli; a Jozue rozkazał tym, którzy szli, aby rozpisali ziemię, mówiąc: Idźcie a obejdźcie ziemię, i popiszcie ją, a potem wróćcie się do mnie, a tu wam rzucę los przed PAnem w Sylo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Odeszli tedy mężowie oni i obchodzili ziemię, i opisywali ją według miast na siedem części w księgi; potem się wrócili do Jozuego, do obozu w Sylo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Rzucił im los Jozue w Sylo przed Panem, a podzielił tam Jozue ziemię synom Izraelskim według działów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Tedy padł los pokoleniu synów Benjaminowych według domów ich, a przyszła granica losu ich między syny Judowe, i między syny Józefowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'I była granica ich ku stronie północnej od Jordanu, a szła taż granica po bok Jerycha od północy, ciągnąc się na górę ku zachodowi, a kończyła się przy puszczy Betawen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'A stamtąd idzie ta granica do Luz, od strony południowej Luzy, która jest Betel, a puszcza się ta granica do Attarot Adar podle góry, która jest od południa Betoron dolnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'I bieży ta granica kołem po bok morza na południe od góry, która jest przeciw Betoron, na południe, i kończy się w Karyjat Baal, które jest Karyjat Jarym, miasto synów Judowych; a toć jest strona zachodnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Strona zasię na południe od końca Karyjat Jarym; a wychodzi ta granica ku morzu, i bieży ku źródłu wód Neftoa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'I ciągnie się ta granica do końca góry, która jest przeciwko dolinie synów Ennon, a jest w dolinie Refaim na północy, i idzie przez dolinę Refaim na północy, i idzie przez dolinę Ennon po stronie Jebuzejczyka na południe, stamtąd bieży do źródła Rogiel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'A idzie kołem od północy, a dochodzi do Ensemes, a wychodzi do Gelilot, które jest przeciwko górze, wstępując do Adommim, bieżąc stamtąd do kamienia Bohena, syna Rubenowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Stamtąd idzie ku stroni, która jest przeciwko równinom na północy, i ciągnie się ku Araba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Stamtąd bieży ta granica ku stronie Betogla na północy, a kończy się u skały morza słonego na północy, ku końcowi Jordanu na południe; toć jest granica południowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Jordan zaś kończy ją ku stronie na wschód słońca; a toć jest dziedzictwo synów Benjaminowych według granic ich w okrąg, wedle domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Były tedy te miasta pokolenia synów Benjaminowych według domów ich: Jerycho i Betagal, i dolina Kasys.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'I Betaraba, i Samraim, i Betel;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'I Awim, i Afara, i Ofera;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'I Kafar Hammonaj, i Ofni, i Gaba, i miast dwanaście, i wsi ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gabon, i Rama, i Berot;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'I Misfe, i Kafara, i Mosa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'I Rekiem, i Jerefel, i Tarela;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'I Sela, Elef, i Jebuz (które jest Jeruzalem), Gibeat, Kiryjat, miast czternaście, i wsi ich. toć jest dziedzictwo synów Benjaminowych według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Potem padł los wtóry Symeonowi, pokoleniu synów Symeonowych według domów ich, a było dziedzictwo ich w pośród dziedzictwa synów Judowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'A dostało się im w dziedzictwo ich Beerseba, i Seba, i Molada;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'I Hasersual, i Bala, i Asem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'I Etolat, i Betul, i Horma;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'I Syceleg, i Bet Marchabot, i Hasersusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'I Betlebaot, i Serohem, i trzynaście miast, i wsi ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Remmon, i Atar, i Asan, miasta cztery, i wsi ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'I wszystkie wsi, które były około tych miast, aż do Baalatbeer, i Ramat ku stronie południowej. Toć jest dziedzictwo pokolenia synów Symeonowych według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Z działu synów Judowych dostało się dziedzictwo synom Symeonowym, bo dział synów Judowych był wielki dla nich; przetoż wzięli dziedzictwo synowie Symeonowi pośród dziedzictwa ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Potem padł los trzeci synom Zabulonowym według domów ich, a jest granica dziedzictwa ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'A idzie granica ich morza Marala, i przychodzi do Debbaset, ciągnąc się aż do potoku, który jest przeciw Jeknoam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'I wraca się od Saryd na wschód słońca ku granicy Chasalek Tabor, a stamtąd bieży do Daberet, i ciągnie się do Jafije;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Potem stamtąd bieży na wschód słońca do Gethefer i do Itakasyn, a wychodzi w Rymmon, i kołem idzie do Nehy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Idzie także kołem taż granica od północy ku Hannaton, a kończy się u doliny Jeftael.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'I Katet, i Nahalal, i Symeron, i Jedala, i Betlehem, miast dwanaście, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Toć jest dziedzictwo synów Zabulonowych według domów ich, te miasta i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Isascharowi też padł los czwarty, to jest, synom Isascharowym według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'A była granica ich Jezreel, i Chasalot, i Sunem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'I Hafaraim, i Seon, i Anaharat;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'I Rabbot, i Cesyjom, i Abes;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'I Ramet, i Engannim, i Enhadda, i Betfeses.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'A przychodzi granica ich do Taboru, i do Sehesyma, i do Betsemes, a kończą się granice ich u Jordanu, miast szesnaście, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Toć jest dziedzictwo pokolenia synów Isascharowych według domów ich, te miasta i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Potem padł los piąty pokoleniu synów Asur według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'I była granica ich: Helkat, i Chali, i Beten, i Achsaf;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'I Elmelech, i Amaad, i Aessal, a idzie na Karmel do morza, i do Sychor, i Lobanat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Stamtąd się obraca na wschód słońca ku Betdagon, i bieży aż do Zabulon, i do doliny Jeftach El na północy, Betemek i do Nehyjel, wychodząc do Kabul ku lewej stronie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'I do Hebronu, i Rohob, i Hamon, i Kana, aż do Sydonu wielkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'A wraca się ta granica od Rama aż do miasta Zor obronnego; stamtąd się obraca ta granica aż do Hosa, a kończy się u morza podle działu Achsyba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'I Amma, i Afek, i Rohob, miast dwadzieścia i dwa, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Toć jest dziedzictwo pokolenia synów Aser według domów ich; te miasta i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Potem synom Neftalimowym padł los szósty, synom Neftalimowym według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'I była granica ich od Helef, i od Helon, do Saannanim, i Adami, które jest Necheb, i Jebnael, aż ku Lekum, i kończy się u Jordanu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Potem się obraca ta granica ku morzu do Asanot Tabor; a stamtąd bieży ku Hukoka, i idzie do Zabulonu na południe, a do Asar przychodzi ku zachodu, a do Juda ku Jordanowi na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'A miasta obronne są: Assedym Ser, i Emat, Rekat, i Cyneret;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'I Edama, i Arama, i Asor,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'I Kiedes, i Edrej, i Enhasor;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'I Jeron, i Magdalel, Horem, i Betanat, i Betsemes, miast dziewiętnaście, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Toć jest dziedzictwo pokolenia synów Neftalimowych według domów ich; te miasta i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Potem pokoleń synów Dan według domów ich, padł los siódmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'A była granica dziedzictwa ich: Saraa, i Estaol, i Isremes;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'I Selebim, i Ajalon, i Jetela;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'I Elon, i Temnata, i Ekron;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'I Eltekie, i Gebbeton i Baalat;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'I Jehut, i Bane Barak, i Getremmon;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'I Mehajarkon, i Rakon z granicą przeciwko Joppie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Ale granica synów Danowych była bardzo mała; przetoż wyszedłszy synowie Dan dobywali Lesem, i wzięli je, i wysiekli je ostrzem miecza, i wziąwszy je w dziedzictwo mieszkali w niem; i przezwali Lesem Dan według imienia Dana, ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Toć jest dziedzictwo pokolenia synów Danowych według domów ich; te miasta, i wsi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'A gdy przestali dzielić ziemię według granic jej, tedy dali synowie Izraelscy dziedzictwo Jozuemu, synowi Nunowemu, w pośród siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Według rozkazania Pańskiego dali mu miasto, którego żądał, Tamnat Saraa na górze Efraim, gdzie zbudował miasto, i mieszkał w niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Teć są dziedzictwa, które losem podzielili w osiadłość Eleazar kapłan, i Jozue, syn Nunów, i przedniejsi z ojców pokolenia synów Izraelskich w Sylo przed Panem, u drzwi namiotu zgromadzenia, i dokończyli podziału ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'POtem rzekł Pan do Jozuego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Powiedz synom Izraelskim, i rzecz: Oddzielcie sobie miasta ucieczki, o którychem mówił do was przez Mojżesza;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Aby tam uciekł mężobójca, coby zabił człowieka nie chcąc, z niewiadomości; i będą wam dla ucieczki przed tym, któryby się krwi chciał mścić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'I uciecze do jednego z miast, a stanie u wrót bramy miejskiej, i opowie starszym miasta onego sprawę swoję; i przyjmą go do miasta między się, i dadzą mu miejsce, a będzie mieszkał z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'A gdy go będzie gonił ten, któryby się chciał mścić krwi, tedy nie wydadzą mężobójcy w ręce jego; albowiem nie chcąc zabił bliźniego swego, a nie mając żadnej waśni, z nim przedtem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'I będzie mieszkał w onem mieście, a stanie przed zebraniem na sąd, i aż do śmierci kapłana wielkiego, który będzie za onych dni; tedy się wróci mężobójca, i przyjdzie do miasta swego i do domu swego, do miasta, z którego uciekł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'I oddzieli Kades w Galilei na górze Neftali, a Sychem na górze Efraim, i miasto Arba, które jest Hebron, na górze Juda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Z drugiej zasię strony Jordanu, gdzie leży Jerycho od wschodu słońca, oddzieli Bosor na puszczy, w równinie z pokolenia Rubenowego, i Ramot w Galaad z pokolenia Gad, przytem Golan w Basen z pokolenia Manasesowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Teć były miasta dla ucieczki wszystkim synom Izraelskim, i cudzoziemcom, którzy mieszkali w pośrodku ich, aby tam uciekł każdy, kto by kogo zabił z nieobaczenia, a nie był zamordowan przez tego, któryby się krwi chciał mścić, ażby pierwej stanął przed zgromadzeniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Przystąpili tedy przedniejsi z ojców Lewitów do Eleazara kapłana, i do Jozuego, syna Nunowego, i do przedniejszych z ojców w pokoleniach synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'I rzekli do nich w Sylo, w ziemi Chananejskiej, mówiąc: Pan rozkazał przez Mojżesza, abyście nam dali miasta ku mieszkaniu z przedmieściami ich dla dobytków naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Przetoż dali synowie Izraelscy Lewitom z dziedzictwa swego według słowa Pańskiego te miasta, i przedmieścia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Padł tedy los na domy Kaatytów; i dostało się synom Aarona kapłana, Lewitom z pokolenia Judowego i z pokolenia Symeonowego, i z pokolenia Benjaminowego, losem miast trzynaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'A drugim synom Kaatowym z domów pokolenia Efraimowego, i z pokolenia Danowego, i z połowy pokolenia Manasesowego, dostało się losem miast dziesięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'A synom Gersonowym z domów pokolenia Isascharowego, i z pokolenia Aserowego, i z pokolenia Neftalimowego, i z połowy pokolenia Manasesowego w Basan dostało się losem miast trzynaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Także synom Merarego według domów ich, z pokolenia Rubenowego, i z pokolenia Gadowego, i z pokolenia Zabulonowego miast dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Dali tedy synowie Izraelscy Lewitom te miasta, i przedmieścia ich, jako był rozkazał Pan przez Mojżesza, losem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'A tak dali z pokolenia synów Judowych, i z pokolenia synów Symeonowych te miasta, których tu imiona położone są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'I dostały się synom Aaronowym z domów Kaatowych z synów Lewiego; bo im padł los pierwszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'I dano im miasto Arba, ojca Enakowego, które jest Hebron na górze Juda, i przedmieścia jego około niego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Ale role miasta tego, i wsi jego dano Kalebowi, synowi Jefunowemu w osiadłość jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Synom tedy Aarona kapłana dano miasto dla ucieczki mężobójcy, Hebron i przedmieścia jego; także Lobne i przedmieścia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'I Jeter, i przedmieścia jego; Estemon, i przedmieścia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'I Helon, i przedmieścia jego, i Dabir, i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'I Ain, i przedmieścia jego, i Jeta, i przedmieścia jego; Betsemes i przedmieścia jego; miast dziewięć z tegoż dwojga pokolenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'A z pokolenia Benjaminowego Gabaon i przedmieścia jego; Gabae i przedmieścia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatot i przedmieścia jego; i Almon i przedmieścia jego; miasta cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Owa wszystkich miast synów Aaronowych, kapłanów, trzynaście miast i przedmieścia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Ale domom synów Kaatowych, Lewitom, którzy byli zostali z synów Kaatowych, dane były miasta losu ich z pokolenia Efraimowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'A dano im miasto ku ucieczce mężobójcy, Sychem i przedmieścia jego na górze Efraim; i Gazer i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'I Kibsaim i przedmieścia jego; i Betoron, i przedmieścia jego; miasta cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Także z pokolenia Danowego Elteko i przedmieścia jego; Gabaton i przedmieścia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalon i przedmieścia jego; Gatrymon i przedmieścia jego; miasta cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'A z połowy pokolenia Manasesowego Tanach i przedmieścia jego; i Gatrymon i przedmieścia jego; dwa miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Wszystkich miast dziesięć i przedmieścia ich dano domom synów Kaatowych pozostałym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Synom zaś Gersonowym z pokolenia Lewiego, od połowy pokolenia Manasesowego, dano miasta dla ucieczki mężobójcy: Golan w Basan i przedmieścia jego, i Bozran i przedmieścia jego; dwa miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Z pokolenia Isaschar: Kiesyjon i przedmieścia jego; Daberet i przedmieścia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jaramot i przedmieścia jego, i Engannim i przedmieścia jego; miasta cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'A z pokolenia Aser: Masaa i przedmieścia jego; Abdon i przedmieścia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkat i przedmieścia jego, Rohob i przedmieścia jego; miasta cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'A z pokolenia Neftalimowego dano miasto dla ucieczki mężobójcy, Kades w Galilei i przedmieścia jego; i Hamotdor i przedmieścia jego, także Kartan i przedmieścia jego; trzy miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Wszystkich miast Gersonitów według domów ich było trzynaście miast i przedmieścia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Potem domom synów Merarego Lewitom ostatnim, z pokolenia Zabulonowego dano Jeknam i przedmieścia jego; Karta i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Damna i przedmieścia jego; Nahalol i przedmieścia jego; miasta cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'A z pokolenia Rubenowego Besor i przedmieścia jego; i Jahasa i przedmieścia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemot i przedmieścia jego; i Mefaat i przedmieścia jego; miasta cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Nadto z pokolenia Gadowego dano miasta dla ucieczki mężobójcy, Ramod w Galaad i przedmieścia jego, i Mahanaim i przedmieścia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesebon i przedmieścia jego; Jazer i przedmieścia jego; wszystkich miast cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Wszystkich miast synów Merarego według domów ich, którzy jeszcze byli pozostali z domów Lewitów, przyszło im losem miast dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'A tak wszystkich miast Lewitów w pośrodku dziedzictwa synów Izraelskich miast czterdzieści osiem i przedmieścia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'A miały te wszystkie miasta, każde z osobna, przedmieścia około siebie; a tak było około wszystkich onych miast.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Dał tedy Pan Izraelowi wszystkę ziemię, o którą przysiągł, że ją dać miał ojcom ich; i posiedli ją, a mieszkali w niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Dał im też odpoczynek Pan zewsząd w około, tak jako był przysiągł ojcom ich; a nie był nikt, kto by się im oprzeć mógł ze wszystkich nieprzyjaciół ich; wszystkie nieprzyjacioły ich dał Pan w rękę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Nie chybiło żadne słowo ze wszystkich słów dobrych, które obiecał Pan domowi Izraelskiemu; wszystko się wypełniło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Tedy przyzwał Jozue Rubenitów i Gadytów, i połowę pokolenia Manasesowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'I rzekł do nich: Wyście strzegli wszystkiego, co wam rozkazał Mojżesz, sługa Pański, i byliście posłuszni głosowi memu we wszystkiem, com wam rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Nie opuściliście braci waszej przez długi czas aż do dnia tego; aleście strzegli pilnie rozkazania Pana, Boga waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'A teraz, ponieważ odpoczynek dał Pan, Bóg wasz, braciom waszym, jako im był obiecał, przetoż teraz wróćcie się, a idźcie do przybytków waszych i do ziemi osiadłości waszej, którą wam dał Mojżesz sługa Pański, przed Jordanem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Tylko strzeżcie pilnie, abyście zachowali przykazanie, i Zakon, który wam rozkazał Mojżesz, sługa Pański: abyście miłowali Pana Boga waszego, a chodzili wszystkiemi drogami jego, chowając rozkazania jego, dzierżąc się go i służąc mu ze wszystkiego serca waszego, i ze wszystkiej duszy waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'I błogosławił im Jozue, a rozpuścił je; i odeszli do przybytków swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Ale połowie pokolenia Manasesowego dał był Mojżesz osiadłość w Basan, a drugiej połowie jego dał Jozue dział z bracią ich z tej strony Jordanu na zachód słońca; a gdy je rozpuszczał Jozue do przybytku ich, błogosławił im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'I rzekł do nich, mówiąc: Z wielkiemi bogactwy wracacie się do przybytków waszych, i z majętnością bardzo wielką, ze srebrem i z złotem, i z miedzią, i z żelazem, i szat bardzo wielą; dzielcież się łupem nieprzyjaciół waszych z bracią swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Tedy wracając się odeszli synowie Rubenowi, i synowie Gadowi, i połowa pokolenia Manasesowego od synów Izraelskich z Sylo, które jest w ziemi Chananejskiej, aby szli do ziemi Galaad, do ziemi osiadłości swojej, którą dziedzicznie otrzymali według słowa Pańskiego przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'I przyszli do granic Jordanu, które były w ziemi Chananejskiej, i zbudowali tam synowie Rubenowi, i synowie Gadowi, i połowa pokolenia Manasesowego ołtarz nad Jordanem, ołtarz wielki na podziw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'I usłyszeli synowie Izraelscy, iż powiadano: Oto zbudowali synowie Rubenowi, i synowie Gadowi, i połowa pokolenia Manasesowego ołtarz przeciw ziemi Chananejskiej na granicach nad Jordanem, kędy przeszli synowie Izraelscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'To gdy usłyszeli synowie Izraelscy, zeszło się wszystko zgromadzenie ich do Sylo, aby się ruszyli przeciwko nim na wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'I posłali synowie Izraelscy do synów Rubenowych, i do synów Gadowych, i do połowy pokolenia Manasesowego, do ziemi Galaad, Fineesa, syna Eleazara kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'A z nim dziesięć książąt, po jednym książęciu z każdego domu ojcowskiego ze wszystkich pokoleń Izraelskich, a każdy książę z tych był przedniejszym w domu ojców swoich, w tysiącach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Tedy ci przyszli do synów Rubenowych, i do synów Gadowych, i do połowy pokolenia Manasesowego, do ziemi Galaad, i rzekli do nich, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Tak mówi wszystko zgromadzenie Pańskie: Cóż to jest za przestępstwo, któremeście wystąpili przeciwko Bogu Izraelskiemu, żeście się dziś odwrócili od Pana, budując sobie ołtarz, abyście dziś byli przeciwnymi Panu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Azaż nam mało na złości Fegorowej, od której nie jesteśmy oczyszczeni i po dziś dzień, skąd była pomsta w zgromadzeniu Pańskiem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Żeście się dziś odwrócili, żebyście nie szli za Panem? Zaczem stanie się, ponieważeście wy dziś odpornymi Panu, że się on jutro na wszystko zgromadzenie Izraelskie rozgniewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'A jeźliż jest nieczysta ziemia osiadłości waszej, przeprowadźcie się do ziemi dziedzictwa Pańskiego, w której przebywa przybytek Pański, i weźmiecie osiadłości w pośrodku nas; tylko Panu nie bądźcie odpornymi, a nie odpadajcie od nas, budując sobie ołtarz oprócz ołtarza Pana, Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Azaż przez Achana, syna Zarego, gdy się dopuścił przestępstwa w rzeczy przeklętej, na wszystko zgromadzenie Izraelskie nie przypadł gniew? a nie on sam jeden umarł dla nieprawości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Tedy odpowiedzieli synowie Rubenowi, i synowie Gadowi, i połowa pokolenia Manasesowego, a mówili do książąt tysiąców Izraelskich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Bóg nad Bogi, Pan, Bóg nad Bogi, Pan, on to wie, i Izrael sam pozna, jeźli się to stało z uporu, albo jeźli z przestępstwa przeciw Panu, niechże nas nie żywi dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Jeźliżeśmy sobie zbudowali ołtarz, abyśmy się odwrócili od Pana, a jeźliż ku ofiarowaniu na nim całopalenia, i ofiar śniednych, albo ku sprawowaniu na nim ofiar spokojnych, Pan niech to rozezna;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Jeźliżeśmy nie raczej obawiając się tej rzeczy, uczynili to, mówiąc: Napotem rzeką synowie wasi synom naszym, mówiąc: Cóż wam do Pana, Boga Izraelskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Oto granicę położył Pan między nami i między wami, synowie Rubenowi i synowie Gadowi, Jordan; nie macie wy działu w Panu, i odwrócą synowie wasi syny nasze od bojaźni Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Przetośmy rzekli: Uczyńmy tak, a zbudujmy sobie ołtarz, nie dla całopalenia, ani innych ofiar:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Ale iżby był świadkiem między nami i między wami, i między potomstwy naszemi po nas, i abyśmy służyli Panu przed obliczem jego w całopaleniach naszych, i w śniednych ofiarach naszych, i w spokojnych ofiarach naszych, a iżby nie rzekli synowie wasi napotem synom naszym: Nie macie cząstki w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Nadtośmy rzekli: Gdyby napotem rzekli nam, albo potomstwu naszemu, tedy rzeczemy: Patrzajcie na podobieństwo ołtarza Pańskiego, który uczynili ojcowie nasi, nie dla całopalenia, ani innych ofiar, ale żeby on był świadkiem między nami i między wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Boże nas uchowaj, żebyśmy mieli przeciwnymi być Panu, a odstąpić dziś od Pana, zbudowawszy ołtarz dla całopalonych, dla śniednych i dla innych ofiar, oprócz ołtarza Pana, Boga naszego, który jest przed przybytkiem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'A usłyszawszy Finees kapłan, i książęta zgromadzenia, i przełożeni nad tysiącmi Izraelskimi, którzy z nim byli, słowa, które mówili synowie Rubenowi, i synowie Gadowi, i synowie Manasesowi, podobało się im to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'I rzekł Finees, syn Eleazara kapłana, do synów Rubenowych i do synów Gadowych i do synów Manasesowych: Dzisiajśmy poznali, iż w pośrodku nas jest Pan, iżeście się nie dopuścili przeciw Panu przestępstwa tego, i wyswobodziliście syny Izraelskie z ręki Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'A tak wrócili się Finees, syn Eleazara kapłana, z onymi książęty od synów Rubenowych i do synów Gadowych z ziemi Galaad do ziemi Chananejskiej do synów Izraelskich, i odnieśli im tę rzecz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'I podobało się to synom Izraelskim; a błogosławili Boga synowie Izraelscy, i nie mówili więcej, żeby mieli iść przeciwko nim na wojnę, i wytracić ziemię, w której synowie Rubenowi i synowie Gadowi mieszkali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Przezwali tedy synowie Rubenowi i synowie Gadowi ołtarz on Ed, mówiąc: Świadkiem będzie między nami, że Pan jest Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'I stało się po niemałym czasie, gdy odpoczynek dał Pan Izraelowi od wszystkich nieprzyjaciół ich okolicznie, a Jozue się zstarzał, i był zeszłym w leciech,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Że przyzwał Jozue wszystkiego Izraela, starszych jego, i przedniejszych jego, i sędziów jego, i przełożonych jego, i rzekł do nich. Jam się zstarzał a zszedłem w leciech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'A wyście widzieli wszystko, co uczynił Pan, Bóg wasz, wszystkim tym narodom przed obliczem waszem: bo Pan, Bóg wasz sam walczył za was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Obaczcież, rozdzieliłem wam losem te narody pozostałe w dziedzictwo między pokolenia wasze od Jordanu, i wszystkie narody, którem wytracił, aż do morza wielkiego na zachód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'A Pan, Bóg wasz, sam je wypędzi od twarzy waszej, i wyżenie je od obliczności waszej, i posiędziecie dziedzicznie ziemię ich, jako wam to powiedział Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Zmacniajcież się bardzo, abyście strzegli a czynili wszystko, co napisano w księgach Zakonu Mojżeszowego, nie odstępując od niego na prawo ani na lewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Ani się też mieszajcie z temi narodami, które zostały z wami; ani imienia bogów ich nie wspominajcie, ani przysięgajcie przez nie, ani im służcie, ani się im kłaniajcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Ale się Pana, Boga waszego, trzymajcie, jakoście czynili aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Bo jako wypędził Pan od oblicza waszego narody wielkie i możne, i nie oparł się wam nikt aż do dnia tego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Tak mąż jeden z was będzie uganiał tysiąc; albowiem Pan, Bóg wasz, on walczy za wami, jako wam obiecał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Przetoż przestrzegajcie z pilnością, abyście miłowali Pana, Boga waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Bo jeźli się cale odwrócicie, a przystaniecie do tych pozostałych narodów, do tych, które zostawają między wami, i spowinowacicie się z nimi, a będziecie się mieszać z nimi, one też z wami:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'Wiedźcież wiedząc, żeć nie będzie więcej Pan, Bóg wasz, wyganiał tych narodów od twarzy waszej; ale będą wam sidłem, i zawadą, i biczem na boki wasze, i cierniem na oczy wasze, póki nie wyginiecie z tej przewybornej ziemi, którą wam dał Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'A oto, ja idę dziś w drogę wszystkiej ziemi; poznajcież tedy ze wszystkiego serca waszego, i ze wszystkiej duszy waszej, żeć nie chybiło żadne słowo ze wszystkich słów najlepszych, które mówił Pan, Bóg wasz o was; wszystkie się nad wami wypełniły, a nie chybiło z nich żadne słowo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Przetoż jako się wypełniło nad wami każde słowo dobre, które mówił Pan, Bóg wasz, do was, tak przywiedzie Pan na was każde słowo złe, aż was wytraci z ziemi tej przewybornej, którą wam dał Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Jeźli przestąpicie przymierze Pana, Boga waszego, który wam rozkazał, a szedłszy służyć będziecie bogom obcym, i kłaniać się im będziecie, tedy się rozpali popędliwość Pańska przeciwko wam, i zginiecie prędko z tej przewybornej ziemi, którą wam dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Tedy zebrał Jozue wszystkie pokolenia Izraelskie do Sychem, i zwołał starszych z Izraela, i przedniejszych z nich, i sędziów ich, i przełożonych ich, i stanęli przed obliczem Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'I rzekł Jozue do wszystkiego ludu: Tak mówi Pan, Bóg Izraelski: Za rzeką mieszkali ojcowie wasi od dawnych czasów, Tare, ojciec Abrahamów, i ojciec Nachorów, i służyli bogom obcym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'I wziąłem ojca waszego Abrahama z miejsca, które jest za rzeką, i prowadziłem go przez wszystkę ziemię Chananejską, i rozmnożyłem nasienie jego, dawszy mu Izaaka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Dałem też Izaakowi Jakóba i Ezawa, a podałem Ezawowi górę Seir, aby ją posiadł; ale Jakób i synowie jego zaszli do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'I posłałem Mojżesza i Aarona, a trapiłem Egipt; a gdym to uczynił w pośród niego, potemem was wywiódł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'I wywiodłem ojce wasze z Egiptu, a przyszliście aż do morza, i gonili Egipczanie ojce wasze z wozami i z jezdnymi aż do morza czerwonego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Tedy wołali do Pana, a on położył ciemności między wami i między Egipczany, i przywiódł na nie morze, a okryło je; i widziały oczy wasze, com uczynił w Egipcie, i mieszkaliście na puszczy przez długi czas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Potemem przywiódł was do ziemi Amorejczyka, mieszkającego za Jordanem, i walczyli przeciwko wam; alem je podał w rękę waszę, i posiedliście ziemię ich, a wygładziłem je przed wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Powstał też Balak, syn Seforów, król Moabski, aby walczył przeciw Izraelowi; a posławszy przyzwał Balaama, syna Beorowego, aby was przeklinał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'I nie chciałem słuchać Balaama; przetoż błogosławiąc błogosławił wam, a tak wybawiłem was z rąk jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Przeprawiliście się potem przez Jordan, i przyszliście do Jerycha, i walczyli przeciwko wam mężowie z Jerycha, Amorejczyk, i Ferezejczyk, i Chananejczyk, i Hetejczyk, i Gargiezejczyk, i Hewejczyk, i Jebuzejczyk; alem je podał w ręce wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'I posłałem przed wami sierszenie, którzy je wypędzili przed obliczem waszem, dwu królów Amorejskich, nie mieczem twoim ani łukiem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'I dałem wam ziemię, w którejście nie robili, i miasta, którycheście nie budowali, w których mieszkacie, a winnic i oliwnic, którycheście nie sadzili, pożywacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Przetoż teraz bójcie się Pana, a służcie mu w doskonałości i w prawdzie, a znieście bogi, którym służyli ojcowie wasi za rzeką, i w Egipcie, a służcie Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'A jeźli się wam zda źle służyć Panu, obierzcież sobie dziś, komu byście służyli, chociaż bogi, którym służyli ojcowie wasi, co byli za rzeką, chociaż bogi Amorejskie, w których wy ziemi mieszkacie; aleć ja i dom mój będziemy służyli Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'I odpowiedział lud mówiąc: Nie daj Boże, abyśmy mieli odstąpić Pana, a służyć bogom cudzym:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Albowiem Pan, Bóg nasz, on jest, który nas wywiódł, i ojce nasze z ziemi Egipskiej, z domu niewoli, a który uczynił przed oczyma naszemi te znaki wielkie, i strzegł nas we wszystkiej drodze, którąśmy szli, i między wszystkimi narody, przez któreśmy przeszli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'I wypędził Pan wszystkie narody, i Amorejczyka mieszkającego w ziemi przed twarzą naszą. A tak my będziemy służyli Panu; bo on jest Bóg nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Tedy rzekł Jozue do ludu: Nie możecie wy służyć Panu; bo Bóg święty jest, Bóg zapalczywy jest, nie przepuści złościom waszym, ani grzechom waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Jeźliż opuścicie Pana, a będziecie służyli bogom cudzym, obróci się, i utrapi was, i zniszczy was, choć wam przedtem dobrze czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'I odpowiedział lud Jozuemu: Nie tak; ale Panu służyć będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Tedy rzekł Jozue do ludu: Świadkami będziecie sami przeciwko, sobie, iżeście sobie obrali Pana, abyście mu służyli; a oni rzekli: Świadkami jesteśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'I rzekł: Terazże znieście bogi cudze, którzy są w pośrodku was, a nakłońcie serca wasze ku Panu, Bogu Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'I odpowiedział lud Jozuemu: Panu, Bogu naszemu, służyć będziemy, i głosowi jego posłuszni być chcemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'A tak uczynił Jozue przymierze z ludem dnia onego, i przełożył im rozkazanie i sąd w Sychem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'I napisał Jozue słowa te w księgi Zakonu Bożego; wziął też kamień wielki, i postawił go tam pod dębem, który był u świątnicy Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Tedy rzekł Jozue do wszystkiego ludu: Oto kamień ten będzie nam świadectwem; albowiem on słyszał wszystkie słowa Pańskie, które mówił z nami i będzie przeciwko wam na świadectwo, byście snać nie skłamali przeciwko Bogu waszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Zatem rozpuścił Jozue lud, każdego do dziedzictwa swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'I stało się potem, że umarł Jozue, syn Nunów, sługa Pański, we stu i w dziesięciu lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'I pogrzebali go na granicy dziedzictwa jego w Tamnat Sare, które jest na górze Efraim, ku północy góry Gaas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'I służył Izrael Panu po wszystkie dni Jozuego, i po wszystkie dni starszych, którzy długo żyli po Jozuem, a którzy wiedzieli o wszystkich sprawach Pańskich, które czynił Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Kości też Józefowe, które byli przenieśli synowie Izraelscy z Egiptu, pogrzebali w Sychem, na części pola, które był kupił Jakób od synów Hemora, ojca Sychemowego, za sto jagniąt; i były u synów Józefowych w dziedzictwie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Eleazar także, syn Aaronów, umarł; i pogrzebali go na pagórku Fineesa, syna jego, który mu był dany na górze Efraim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'I stało się po śmierci Jozuego, iż pytali synowie Izraelscy Pana, mówiąc: Któż z nas wprzód pójdzie przeciw Chananejczykowi, aby walczył z nim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'I rzekł Pan: Juda pójdzie; otom podał ziemię w rękę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'I rzekł Juda do Symeona, brata swego: Pójdź ze mną do losu mego, a będziemy walczyli przeciw Chananejczykowi; wszak ja też pójdę z tobą do losu twego. I szedł z nim Symeon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Tedy poszedł Juda, i podał Pan Chananejczyka, i Ferezejczyka w ręce ich, a porazili z nich w Bezeku dziesięć tysięcy mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Bo naleźli Adonibezeka w Bezeku, i walczyli przeciwko niemu, a porazili Chananejczyka i Ferezejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'I uciekał Adonibezek, którego oni gonili; a pojmawszy go, poucinali palce wielkie u rąk jego, i u nóg jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Tedy rzekł Adonibezek: Siedmdziesiąt królów z palcami wielkiemi obciętemi u rąk swych i u nóg swych, zbierali odrobiny pod stołem moim; jakom czynił, tak mi oddał Bóg. I przywiedli go do Jeruzalemu, i tamże umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Bo walczyli przedtem synowie Judowi przeciwko Jeruzalemowi i wzięli je, i wysiekli je ostrzem miecza, i miasto spalili ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Potem ciągnęli synowie Juda, aby walczyli przeciw Chananejczykowi mieszkającemu na górach, i na południe, i w polach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Ciągnął tedy Juda przeciwko Chananejczykowi, który mieszkał w Hebronie, (a imię Hebronu było przedtem Karyjatarbe) i poraził Sesai i Ahymana, i Talmaja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Stamtąd zasię ciągnęli do mieszkających w Dabir, (a imię Dabir było przedtem Karyjatsefer.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'I rzekł Kaleb: Kto by dobył Karyjatsefer, a wziąłby je, dam mu Achsę, córkę moję, za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'I wziął je Otonijel, syn Keneza, młodszego brata Kalebowego.; a dał mu Achsę, córkę swą, za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'I stało się, gdy przyszła do niego, namawiała go, aby prosił ojca jej o pole; i zsiadła z osła, i rzekł do niej Kaleb: Cóż ci?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'A ona rzekła: Daj mi błogosławieństwo; gdyżeś mi dał ziemię suchą, daj mi też źródła wód. I dał jej Kaleb źródła wyższe i źródła dolne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Synowie też Ceni, świekra Mojżeszowego, wyszli z miasta Palm z synami Judowymi na puszczą Judowę, która jest na południe od Arad, i przyszedłszy mieszkali z ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Potem ciągnął Juda z Symeonem, bratem swym, a porazili Chananejczyka, mieszkającego w Sefat, a zburzyli je, i nazwali imię miasta onego Horma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Wziął też Juda Gazę z granicami jego, i Akkaron z granicami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'I był Pan z Judą, i posiadł onę górę; ale nie wypędził mieszkających w dolinie, bo mieli wozy żelazne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'A tak oddano Kalebowi Hebron, jako był rozkazał Mojżesz, skąd on wygnał trzech synów Enakowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Ale Jebuzejczyka, mieszkającego w Jeruzalemie, nie wygnali synowie Benjaminowi; przetoż mieszkał Jebuzejczyk z synami Benjaminowymi w Jeruzalemie aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Udał się też dom Józefów do Betel, a Pan był z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'I szpiegował dom Józefów Betel; (a imię miasta tego było przedtem Luz.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'A ujrzawszy oni szpiegowie człowieka wychodzącego z miasta, rzekli do niego: Ukaż nam prosimy wejście do miasta, a uczynimy z tobą miłosierdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'I ukazał im wejście do miasta; i wysiekli miasto ostrzem miecza, a człowieka onego ze wszystkim domem jego puścili wolno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'A tak poszedł on człowiek do ziemi Hetejczyków, i zbudował miasto, a nazwał imię jego Luz; to jest imię jego aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Nie wypędził też Manases obywateli z Betsean i z miasteczek jego, ani z Tanach i z miasteczek jego, ani obywateli z Dor i z miasteczek jego, ani obywateli z Jeblam i z miasteczek jego, ani obywateli z Megiddo i z miasteczek jego; i począł Chananejczyk mieszkać w onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'A gdy się zmocnił Izrael, uczynił Chananejczyka hołdownikiem, a nie wygnał go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Także i Efraim nie wypędził Chananejczyka mieszkającego w Gazer; przetoż mieszkał Chananejczyk między nimi w Gazer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zabulon też nie wypędził mieszkających w Cetron, i mieszkających w Nahalol; przetoż mieszkał Chananejczyk między nimi, będąc hołdownikiem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Aser też nie wypędził mieszkających w Acho, i mieszkających w Sydonie, i w Ahalab, i w Achsyb, i w Helba, i w Afek, i w Rohob.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'I mieszkał Aser w pośrodku Chananejczyka, mieszkającego w onej ziemi; bo go nie wypędził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Neftalim też nie wypędził obywateli z Betsemes, ani obywateli z Betanat, i mieszkał między Chananejczykami mieszkającymi w onej ziemi; jednak obywatele Betsemes i Betanat byli hołdownikami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'I ścisnęli Amorejczycy syny Danowe na górach, tak iż im nie dopuścili schodzić na dolinę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'I począł mieszkać Amorejczyk na górze Hares, w Ajalon i w Salebim; i wzmocniła się ręka domu Józefowego, i byli hołdownikami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'A była granica Amorejczykowa od góry, gdzie wstępują do niedźwiadków, od skały ich i wyżej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'I przyszedł Anioł Pański z Galgal do Bochym, mówiąc: Wywiodłem was z Egiptu, i wywiodłem was do ziemi, o którąm przysiągł ojcom waszym, i mówiłem: Nie wzruszę przymierza mego z wami na wieki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Jedno wy nie wchodźcie w przymierze z mieszkającymi w tej ziemi, owszem ołtarze ich porozwalajcie; aleście nie słuchali głosu mojego. Przeczżeście to uczynili?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Przetożem tak rzekł: Nie wypędzę ich od obliczności waszej; ale będą wam jako ciernie na boki, a bogowie ich będą wam jako sidło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'I stało się, gdy mówił Anioł Pański te słowa do wszystkich synów Izraelskich, że lud podniósł głos swój, i płakali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'I nazwali imię miejsca onego Bochym, a tamże ofiarowali Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'A Jozue rozpuścił był lud, i rozeszli się synowie Izraelscy każdy do dziedzictwa swego, aby posiedli ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Tedy służył lud Panu po wszystkie dni Jozuego, i po wszystkie dni starszych, którzy długo żyli po śmierci Jozuego, a którzy widzieli wszystkie sprawy Pańskie wielkie, które uczynił Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Ale gdy umarł Jozue syn Nunów, sługa Pański, będąc we stu i w dziesięć lat;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'I gdy go pogrzebli na granicy dziedzictwa jego w Tamnatheres na górze Efraim, od północy góry Gaas;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Także gdy wszystek on rodzaj przyłączony jest do ojców swoich, i powstał po nich inszy naród, który nie znał Pana, ani też spraw, który uczynił Izraelowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Tedy uczynili synowie Izraelscy złe przed oczyma Pańskiemi, a służyli Baalom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'I opuścili Pana, Boga ojców swoich, który je wywiódł z ziemi Egipskiej, i szli za bogami cudzymi, którzy byli z bogów onych narodów okolicznych, i kłaniali się im, a tak rozdraźnili Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Bo opuścili Pana, a służyli Baalowi i Astarotowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'I rozpalił się gniew Pański przeciw Izraelowi, i podał je w ręce łupieżcom, którzy je łupili; a zaprzedał je w ręce nieprzyjaciół ich okolicznych, tak iż się nie mogli dalej ostać przed nieprzyjacioły swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'A gdzie się kolwiek ruszyli, ręka Pańska była przeciwko nim ku złemu, jako powiedział Pan, i jako im przysiągł Pan; i byli ściśnieni bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Potem Pan wzbudził sędzie, którzy je wyzwalali z rąk łupieżców ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Ale i sędziów swych nie słuchali, owszem się scudzołożyli z bogami obcymi, kłaniając się im, i ustępowali prędko z drogi, którą chodzili ojcowie ich, a słuchając przykazań Pańskich, nie czynili tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'A gdy im wzbudzał Pan sędzie, bywał Pan z każdym sędzią, i wybawiał je z rąk nieprzyjaciół ich po wszystkie dni onego sędziego; bo się użalił Pan narzekania ich, do którego je przywodzili ci, którzy je uciskali i trapili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Wszakże po śmierci sędziego odwracali się, i psowali się bardziej niż ojcowie ich, chodząc za bogami cudzymi, a służąc im, i kłaniając się im, nic nie opuszczali z spraw swoich i z drogi swojej upornej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Przetoż wzruszyła się popędliwość Pańska przeciw Izraelowi, i rzekł: Dla tego, że przestąpił ten naród przymierze moje, którem przykazał ojcom ich, a nie byli posłuszni głosowi mojemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'Ja też na potem nie wypędzę żadnego od twarzy ich z tych narodów, które pozostawił Jozue, kiedy umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Abym przez nie doświadczał Izraela, będąli strzedz drogi Pańskiej, chodząc po niej, jako jej strzegli ojcowie ich, czyli nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'I zostawił Pan one narody, nie wyganiając ich rychło, ani ich podał w rękę Jozuego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'A teć są narody, które pozostawił Pan, aby kusił przez nie Izraela, wszystkie, którzy nie wiedzieli o żadnych walkach Chananejskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Aby wżdy wiedzieli potomkowie synów Izraelskich, i poznali, co jest walka, którzy jej zgoła przedtem nie znali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Pięcioro książąt Filistyńskich i wszystkie Chananejczyki, i Sydończyki i Hewejczyki, mieszkające na górze Libanie, od góry Baal Hermon aż tam, gdzie wchodzą do Hemat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Cić byli, przez które doświadczał Izraela, aby się dowiedział, będąli posłuszni przykazaniom Pańskim, które rozkazał ojcom ich przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'A tak synowie Izraelscy mieszkali w pośród Chananejczyków, Hetejczyków, i Amorejczyków, i Ferezejczyków i Hewejczyków, i Jebuzejczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'I brali sobie córki ich za żony, a córki swe dawali synom ich, i służyli bogom ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'I czynili Izraelscy synowie złe przed oczyma Pańskiemi: zapomniawszy Pana, Boga swego, służyli Baalom, i święconym gajom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Tedy się zapalił gniew Pański przeciw Izraelowi, i podał je w rękę Chusanrasataima, króla Syrskiego w Mezopotamii: A służyli synowie Izraelscy Chusanrasataimowi przez osiem lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Potem wołali synowie Izraelscy do Pana; I wzbudził Pan wybawiciela synom Izraelskim, aby je wybawił, Otonijela, syna Kenezowego, brata Kalebowego młodszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'I był nad nim Duch Pański, a sądził Izraela; a gdy się ruszył na wojnę, podał Pan w rękę jego Chusanrasataima, króla Syryjskiego, i zmocniła się ręka jego nad Chusanrasataimem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'A tak była w pokoju ziemia przez czterdzieści lat, aż umarł Otonijel, syn Kenezów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Potem znowu synowie Izraelscy czynili złe przed oczyma Pańskiemi. I zmocnił Pan Eglona, króla Moabskiego, przeciw Izraelowi, przeto iż czynili złe przed oczyma Pańskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Bo zebrawszy do siebie syny Ammonowe i Amalekowe ruszył się, i poraził Izraela, i opanował miasto Palm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Służyli tedy synowie Izraelscy Eglonowi, królowi Moabskiemu, osiemnaście lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Potem wołali synowie Izraelscy do Pana. I wzbudził im Pan wybawiciela, Aoda, syna Gery, syna Jemini, męża ręką prawą niewładającego; i posłali synowie Izraelscy przezeń dar Eglonowi, królowi Moabskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'I uczynił sobie Aod miecz z obu stron ostry, na łokieć wzdłuż, i przypasał go pod szaty swe do prawego biodra swojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'I przyniósł dar Eglonowi, królowi Moabskiemu: a Eglon był człowiek bardzo otyły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'A gdy oddał dar, odprawił lud, który był dar przyniósł;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'A sam wróciwszy się do gór kamiennych, które były w Galgal, rzekł: Rzecz tajemną mam do ciebie, o królu! któremu on odpowiedział: Milcz; i wyszli od niego wszyscy, którzy stali przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'I wszedłszy Aod do niego, (a on sam siedział na sali letniej, którą miał sam dla siebie,) i rzekł Aod: Mam rozkazanie Boże do ciebie. I powstał z stolicy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Tedy Aod wyciągnąwszy lewą rękę swą, dobył miecza od prawego biodra swego, i wraził go w brzuch jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Tak iż wpadła i rękojeść za żelazem, i zawarło się w sadle żelazo; bo był nie wyjął miecza z brzucha jego, aż się i gnój rzucił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Wyszedł potem Aod przez przysionek, a zamknął drzwi gmachu za sobą, i zawarł zamkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'A gdy on wyszedł, słudzy jego przyszli, a widząc, iż drzwi gmachu zamknione były, rzekli: Podobno sobie król czyni wczas na sali letniej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'A naczekawszy się, aż się wstydzili, widząc, że on nie otwiera drzwi sali, wziąwszy klucz otworzyli; a oto, pan ich leżał na ziemi umarły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Lecz Aod uszedł, póki się oni bawili, a minąwszy góry kamienne, szedł do Seiratu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'A gdy przyszedł, zatrąbił w trąbę na górze Efraim; i zstąpili z nim synowie Izraelscy z góry, a on przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'I rzekł do nich: Pójdźcie za mną: albowiem podał Pan nieprzyjacioły wasze Moabity w ręce wasze. Tedy szli za nim, a odjąwszy bród Jordański Moabitom, nie dopuszczali nikomu przeprawy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'I pobili Moabitów na ten czas około dziesięciu tysięcy mężów, wszystko bogatych, i wszystko mężów dużych, a nikt nie uszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'I poniżony jest Moab dnia onego pod ręką Izraela, a była w pokoju ziemia przez osiemdziesiąt lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'A po nim był Samgar, syn Anatów, który poraził z Filistynów sześć set mężów stykiem wołowym, a wybawił i ten Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Potem znowu synowie Izraelscy czynili złe przed oczyma Pańskiemi po śmierci Aodowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'I podał je Pan w ręce Jabina, króla Chananejskiego, który królował w Hasor, a hetman wojska jego był Sysara, a sam mieszkał w Haroset pogańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Tedy wołali synowie Izraelscy do Pana; albowiem miał dziewięć set wozów żelaznych, a srodze uciskał syny Izraelskie przez dwadzieścia lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'A Debora, niewiasta prorokini, żona Lapidotowa, sądziła Izraela na on czas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'I mieszkała pod palmą Debora między Rama i między Betel na górze Efraim, i chodzili do niej synowie Izraelscy na sąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Która posławszy przyzwała Baraka, syna Abinoemowego, z Kades Neftalim, mówiąc do niego: Izali nie rozkazał Pan, Bóg Izraelski: idź, a zbierz lud na górze Tabor, a weźmij z sobą dziesięć tysięcy mężów z synów Neftalimowych, i z synów Zabulonowych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'I przywiodę do ciebie ku rzece Cyson Sysarę, hetmana wojska Jabinowego, i wozy jego, i mnóstwo jego, a podam go w ręce twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'I rzekł do niej Barak: Jeźli pójdziesz ze mną, pójdę, a jeźli nie pójdziesz ze mną, nie pójdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Która odpowiedziała: Jać w prawdzie pójdę z tobą, ale nie będzie z sławą twoją ta droga, którą ty pójdziesz; albowiem w rękę niewieścią poda Pan Sysarę. A tak wstawszy Debora, szła z Barakiem do Kades.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Zebrał tedy Barak Zabulona i Neftalima do Kades, a wywiódł z sobą dziesięć tysięcy mężów, z którym też szła i Debora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Ale Heber Cynejczyk odłączył się od Cynejczyków, od synów Hobaby, świekra Mojżeszowego, i rozbił namiot swój aż do Elon w Sananim, które jest w Kades.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'I powiedziano Sysarze, iż wyszedł Barak, syn Abinoemów na górę Tabor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Przetoż zebrał Sysara wszystkie wozy swoje, dziewięć set wozów żelaznych, i wszystek lud, który miał ze sobą od Haroset pogańskiego aż do rzeki Cyson.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Tedy rzekła Debora do Baraka: Wstań; albowiem tenci jest dzień, w który podał Pan Sysarę w ręce twoje; izali Pan nie idzie przed tobą? A tak zszedł Barak z góry Tabor, a dziesięć tysięcy mężów za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'I poraził Pan Sysarę, i wszystkie wozy, i wszystko wojsko jego ostrzem miecza przed Barakiem, a skoczywszy Sysara z wozu, uciekał pieszo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Ale Barak gonił wozy i wojsko aż do Haroset pogańskiego; i poległo wszystko wojsko Sysarowe od ostrza miecza, tak iż z nich i jeden nie został.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'A Sysara uciekł pieszo do namiotu Jaeli, żony Hebera Cynejczyka; albowiem był pokój między Jabinem, królem Hasor, i między domem Hebera Cynejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'A wyszedłszy Jael przeciwko Sysarze, rzekła do niego: Skłoń się panie mój, skłoń się do mnie, nie bój się; i skłonił się do niej do namiotu, i przykryła go kocem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Tedy rzekł do niej: Daj mi proszę, napić się trochę wody, bom upragnął; a ona otworzywszy łagiew mleka, dała mu się napić, i przykryła go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'I rzekł do niej: Stój we drzwiach u namiotu; a jeźliby kto przyszedł, i pytał cię, mówiąc: Jestże tu kto? tedy rzeczesz: Nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Potem wzięła Jael, żona Heberowa, gwóźdź od namiotu, wzięła też i młot w rękę swą, a wszedłszy do niego po cichu, przebiła gwoździem skroń jego aż utknął w ziemi, (bo był twardo usnął, będąc spracowanym,) i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'A oto, Barak gonił Sysarę, i wyszła Jael przeciwko niemu, i rzekła mu: Pójdź, a ukażęć męża, którego szukasz. I wyszedł do niej, a oto Sysara leżał umarły, a gwóźdź w skroni jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'A tak poniżył Bóg dnia onego Jabina, króla Chananejskiego, przed syny Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'I nacierała ręka synów Izraelskich tem bardziej, a ciężka była Jabinowi, królowi Chananejskiemu, aż zgładzili tegoż Jabina, króla Chananejskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'I śpiewała Debora i Barak, syn Abinoemów, dnia onego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Dla pomsty uczynionej w Izraelu, a iż się na to dobrowolnie lud ofiarował, błogosławcie Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Słuchajcie królowie, bierzcie w uszy książęta, ja, ja Panu zaśpiewam, śpiewać będę Panu, Bogu Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Panie, gdyś wyszedł z Seir, a przechodziłeś przez pole Edom, ziemia się wzruszyła, nieba też kropiły, a obłoki wydawały wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Góry się rozpłynęły od oblicza Pańskiego, a góra Synaj od oblicza Pana, Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'Za dni Samgara, syna Anatowego, i za dni Jaeli zaginęły ścieżki, a którzy szli w drogę, chodzili ścieżkami krzywemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Spustoszały wsi w Izraelu, spustoszały, ażem powstała ja Debora, ażem powstała matką w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Gdy Izrael obierał sobie bogi nowe, tedy bywała wojna w bramach; tarczy jednak nie było widać, ani drzewca między czterdziestą tysięcy w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Serce moje nakłonione do książąt Izraelskich. Ochotni z ludu błogosławcież Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Którzy jeździcie na oślicach białych, i zasiadacie na sądach, i którzy chodzicie po drogach, rozmawiajcie z sobą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Że ucichł trzask strzelców między miejscami, gdzie czerpią wodę; tam niech opowiadają sprawiedliwości Pańskie, sprawiedliwości we wsiach jego w Izraelu; tedy zstąpi do bram lud Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Powstań Deboro, powstań, powstań, a zaśpiewaj pieśń; powstań Baraku, a pojmaj więźnie twoje, synu Abinoemów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Teraz panować będzie potłoczony nad możnymi z ludu; Pan dopomógł mi panować nad mocarzami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Z Efraima wyszedł korzeń ich przeciw Amalekowi, za tobą (Efraimie,) Benjamin między ludem twoim; z Machyru wyszli zakonodawcy, a z Zabulonu pisarze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Książęta też Isaschar były z Deborą; Isaschar też jako i Barak w dolinę posłan jest pieszo; ale w dziale Rubenitów byli ludzie wysokich myśli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Czemuś siedział między dwiema oborami, słuchając wrzasku trzód? w dziale Rubenitów byli ludzie wysokich myśli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Galaad za Jordanem odpoczynął, a Dan przecz się bawił okrętami? Aser czemu siedział na brzegu morskim, a w skałach swoich mieszkał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zabulon jest lud, który wydał duszę swą na śmierć, także i Neftalim, a to na wysokich polach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Przyszli królowie, walczyli; na ten czas walczyli królowie Chananejscy w Tanach u wód Magieddo, jednak korzyści srebra nie odnieśli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Z nieba walczono: gwiazdy z miejsc swoich walczyły z Sysarą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Potok Cyson porwał je, potok Kiedumim, potok Cyson; podeptałaś, o duszo moja, możne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Tedy się popadały kopyta końskie od wielkiego tąpania mocarzów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Przeklinajcie Meroz, rzekł Anioł Pański, przeklinajcie przeklinając obywatele jego; albowiem nie przyszli na ratunek Panu, na ratunek Panu z mocarzami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Błogosławiona między niewiastami Jael, żona Hebera Cynejczyka; nad niewiasty w namiocie mieszkające błogosławiona będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Prosił o wodę, a ona mleka dała, a na przystawce książęcej przyniosła masła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Lewą rękę swą do gwoździa ściągnęła, a prawicę swoję do młota kowalskiego, i uderzyła Sysarę, przebiła głowę jego, i przeraziła, i przekłuła skronie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'U nóg jej skurczył się, padł, leżał; u nóg jej skurczył się, padł; kędy się skurczył, tam upadł zabity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Oknem wyglądała, a wołała matka Sysary przez kratę: Przeczże omieszkiwa wrócić się wóz jego? przecz się nie spieszą nogi woźników jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Przedniejsze i mędrsze niewiasty odpowiedziały, jako też i sama sobie odpowiadała:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Snać trafili na łup, i dzielą go? Panienka jedna albo dwie dostaną się mężowi jednemu; łupy rozlicznych barw oddawają Sysarze, a łupy pstro haftowane, i łupy pstro z obu stron tkane dostawają się na szyję łupy biorących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Tak niechaj zginą wszyscy nieprzyjaciele twoi, Panie, a ci, którzy ciebie miłują, niech będą jako słońce, gdy wschodzi w mocy swojej. I była w pokoju ziemia przez czterdzieści lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Potem czynili synowie Izraelscy złe przed oczyma Pańskiemi, i podał je Pan w ręce Madyjanitów przez siedem lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'A zmocniła się ręka Madyjanitów nad Izraelem, tak iż przed Madyjanitami kopali sobie synowie Izraelscy lochy, które były w górach, i jaskinie i twierdze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'A bywało, gdy czego nasiał Izrael, że przychodził Madyjan i Amalek, i ludzie ze wschodu słońca, a najeżdżali go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'I położywszy się obozem przeciwko nim, psowali zboża ziemi, aż gdzie chodzą do Gazy, nic nie zostawując na pożywienie Izraelczykom, ani owiec, ani wołów, ani osłów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Albowiem oni i stada ich przyciągali, i namioty ich, a przychodzili jako szarańcza w mnóstwie, i nie było im i wielbłądom ich liczby; tak przychodząc do ziemi spustoszyli ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Tedy znędzony był Izrael bardzo od Madyjanitów, i wołali synowie Izraelscy do Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'A gdy wołali synowie Izraelscy do Pana z przyczyny Madyjanitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Posłał Pan męża proroka do synów Izraelskich, i mówił do nich: Tak mówi Pan, Bóg Izraelski: Jam was wywiódł z ziemi Egipskiej, a wywiodłem was z domu niewoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'I wyrwałem was z ręki Egipczanów, i z ręki wszystkich, którzy was trapili, którem przed wami wygnał, i dałem wam ziemię ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'A powiedziałem wam: Jam Pan, Bóg wasz, nie bójcież się bogów Amorejskich, w których ziemi wy mieszkacie; aleście nie usłuchali głosu mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Przyszedł potem Anioł Pański i stanął pod dębem, który był w Efra, w dziedzictwie Joasa, ojca Esrowego. A Giedeon, syn jego, młócił zboże na bojewisku, aby z niem uciekł przed Madyjanitami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Tedy mu się ukazał Anioł Pański, i rzekł do niego: Pan z tobą, mężu waleczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'I odpowiedział mu Giedeon: Proszę Panie mój, jeźli Pan jest z nami, a czemuż na nas przyszło to wszystko? gdzież teraz są wszystkie cuda jego, które nam opowiadali ojcowie nasi, mówiąc: Izali z Egiptu nie wywiódł nas Pan? a teraz opuścił nas Pan, i podał nas w ręce Madyjanitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Tedy wejrzawszy nań Pan rzekł: Idźże z tą twoją mocą, a wybawisz Izraela z ręki Madyjańczyków; izalim cię nie posłał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'A on rzekł do niego: Proszę Panie mój, czemże wybawię Izraela? oto naród mój podły jest w Manase, a jam najmniejszy w domu ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'I rzekł do niego Pan: Ponieważ Ja będę z tobą, przetoż porazisz Madyjanity, jako męża jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'A on mu odpowiedział: Jeźliżem proszę znalazł łaskę przed oczyma twemi, daj mi znak, że ty mówisz ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Nie odchodź proszę stąd, aż zaś przyjdę do ciebie, a przyniosęć ofiarę moję, i położę ją przed tobą. I odpowiedział: Ja poczekam, aż się wrócisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Odszedłszy tedy Giedeon zgotował koźlątko z stada a z miary mąki przaśne chleby, a mięso włożył w kosz, a polewkę mięsną wlał w garnek, i przyniósł to do niego pod dąb, i ofiarował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'I rzekł do niego Anioł Boży: Weźmij to mięso i te chleby niekwaszone, a połóż na onej skale polewką polawszy; i uczynił tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Zatem ściągnął Anioł Pański koniec laski, którą miał w ręce swojej, i dotknął się mięsa i przaśników, i wyszedł ogień z skały, a spalił mięso i chleby przaśne; a między tem Anioł Pański odszedł od oczu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'A widząc Giedeon, iż to był Anioł Pański, rzekł: Ach, Panie Boże, czemużem widział Anioła Pańskiego twarzą w twarz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'I rzekł mu Pan: Pokój z tobą; nie bój się, nie umrzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Przetoż zbudował tam Giedeon ołtarz Panu, i nazwał go: Pan pokoju; aż do dnia tego ten jeszcze jest w Efracie, ojca Esrowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'I stało się onej nocy, że mu rzekł Pan: Weźmij cielca dorosłego, który jest ojca twego, tego cielca drugiego siedmioletniego, a rozwal ołtarz Baalów, który jest ojca twego, i gaj, który jest około niego, wysiecz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'A zbuduj ołtarz Panu, Bogu twemu, na wierzchu tej skały na równinie, a weźmij tego cielca drugiego, i uczyń z niego całopalenie przy drwach z gaju, który wysieczesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Wziąwszy tedy Giedeon dziesięć mężów z sług swoich, uczynił jako mu rozkazał Pan; a iż się bał domu ojca swego i mężów miasta, nie uczynił tego we dnie, ale uczynił w nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'A gdy wstali mężowie miasta rano, ujrzeli rozwalony ołtarz Baalów, i gaj, który był podle niego, wyrąbany, i cielca onego drugiego ofiarowanego na całopalenie na ołtarzu zbudowanym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Zatem rzekł jeden do drugiego: Któż to wżdy uczynił? A gdy się pytali i dowiadowali, powiedziano: Giedeon, syn Joasów, uczynił to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Tedy rzekli mężowie miasta do Joasa: Wywiedź syna twego, niech umrze, iż rozrzucił ołtarz Baalów, a iż wyciął gaj, który był około niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'I odpowiedział Joas wszystkim, którzy stali około niego: A wyż się to swarzyć macie o Baala? Izali wy go wybawicie? Kto by się oń zastawiał, niech umrze tegoż poranku; jeźli bogiem jest, niech się mści tego, że rozwalono ołtarz jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'I nazwano go onegoż dnia Jerubaal, mówiąc: Niech się mści nad nim Baal, iż rozwalił ołtarz jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Tedy wszyscy Madyjanitowie, i Amalekitowie, i ludzie od wschodu słońca zebrali się wespół, a przeprawiwszy się przez Jordan, położyli się obozem w dolinie Jezreel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Ale Duch Pański przyoblókł Giedeona, który zatrąbiwszy w trąbę zwołał domu Abiezerowego do siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'I wyprawił posły do wszystkiego pokolenia Manasesowego, i zebrali się do niego; posły też posłał do Asera, i do Zabulona, i do Neftalima, i zajechali im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Tedy rzekł Giedeon do Boga: Jeźli wybawisz przez rękę moję Izraela, jakoś powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Oto, ja położę runo wełny na bojewisku; jeźliż rosa tylko na runo upadnie, a wszystka ziemia sucha będzie, tedy będę wiedział, iż wybawisz przez rękę moję Izraela, jakoś powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'I stało się tak; bo wstawszy nazajutrz, ścisnął runo, i wyżdżął rosy z runa pełną czaszę wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Nadto rzekł Giedeon do Boga: Niech się nie wzrusza gniew twój przeciwko mnie, że przemówię jeszcze raz. Niech doświadczę proszę jeszcze raz na tem runie; niech będzie, proszę, suche samo runo tylko, a na wszystkiej ziemi niech będzie rosa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'I uczynił tak Bóg onej nocy, że było samo runo suche, a na wszystkiej ziemi była rosa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Wstał tedy bardzo rano Jerobaal, który jest Giedeon, i wszystek lud, który był z nim, i położyli się obozem u źródła Harod, a obóz Madyjański był im na północy od pagórka More w dolinie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'I rzekł Pan do Giedeona: Wielki jest lud z tobą; przetoż nie dam Madyjanitów w ręce ich, by się snać nie chlubił przeciw mnie Izrael, mówiąc: Ręka moja wybawiła mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'A tak zawołaj teraz, aby słyszał lud, mówiąc: Kto jest lękliwym i bojaźliwym, niech się wróci, a rano niechaj idzie precz ku górze Galaad. Tedy się wróciło z ludu dwadzieścia i dwa tysiące, a dziesięć tysięcy ich zostało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'I rzekł Pan do Giedeona: Jeszcze lud wielki. Zaprowadź ich do wody, a tam go doświadczę; albowiem o kim ci powiem: Ten niech idzie z tobą, ten pójdzie z tobą, a o kimcikolwiek powiem: Ten niech nie chodzi z tobą, ten nie pójdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Tedy zaprowadził lud do wód; i rzekł Pan do Giedeona: Każdego, który łeptać będzie językiem swoim wodę, jako pies łepce, postawisz go osobno; także każdego, który uklęknie na kolana swoje, aby pił, stanie osobno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'I była liczba tych, którzy chwytali ręką swoją do ust swoich wodę, trzy sta mężów; a wszystek inny lud uklęknąwszy na kolana swoje, pił wodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Tedy rzekł Pan do Giedeona: Przez tych trzy sta mężów, którzy łeptali wodę, wybawię was, a podam Madyjanity w ręce twoje, a inny wszystek lud, każdy niech idzie na miejsce swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'A tak on lud wziął żywności z sobą, i trąby swe; a inne wszystkie męże Izraelskie rozpuścił każdego do namiotu swego, trzy sta tylko mężów zostawiwszy; a obóz Madyjański był pod nim w dolinie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'I stało się onej nocy, że rzekł do niego Pan. Wstań, znijdź do obozu, bom go dał w ręce twoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'A jeźli się ty sam iść boisz, znijdźże z Farą, sługą twoim, do obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'I usłyszysz, co będą mówić; a potem posilą się ręce twoje, i pociągniesz na obóz. A tak szedł on sam, i Fara, sługa jego, aż na koniec zbrojnego ludu, który był w obozie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'A Madyjanitowie i Amalekitowie, i wszystek lud od wschodu słońca leżeli w dolinie, jako szarańcza przemnóstwo, i wielbłądów ich nie było liczby, jako piasek, który jest na brzegu morskim niezliczony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Tam gdy przyszedł Giedeon, oto, niektóry powiadał towarzyszowi swemu sen, i rzekł: Oto śnił mi się sen, a zdało mi się, że bochen chleba jęczmiennego toczył się do obozu Madyjańskiego, i przytoczył się aż do namiotu, i uderzył weń, aż poległ, i wywrócił go z wierzchu, i upadł namiot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Któremu odpowiedział towarzysz, jego i rzekł: Nic to nie jest innego, jedno miecz Giedeona, syna Joasowego, męża Izraelskiego; dał Bóg w rękę jego Madyjanity ze wszystkim obozem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'I stało się, gdy usłyszał Giedeon powieść snu onego, i wykład jego, podziękował Bogu, a wróciwszy się do obozu Izraelskiego, rzekł: Wstańcie; albowiem dał Pan w ręce wasze obóz Madyjański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Rozdzielił tedy one trzy sta mężów na trzy hufce, a dał trąby w ręce każdemu z nich, i dzbany czcze, i pochodnie w pośrodek dzbanów');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'I rzekł do nich: Co ujrzycie, że ja czynię, toż czyńcie; bo oto ja wnijdę w przodek obozu, a co ja czynić będę, toż wy czyńcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Gdy zatrąbię w trąbę, ja i wszyscy, którzy są ze mną, tedy wy też zatrąbicie w trąby około wszystkiego obozu, i będziecie mówili: Miecz Pański i Giedeonów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'A tak szedł Giedeon, i sto mężów, którzy z nim byli, w przodek obozu, gdy się zaczęła średnia straż; zaraz skoro przemieniono straż i trąbili w trąby, a potłukli dzbany, które w rękach swych mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Zatrąbiły też one trzy hufy w trąby, i potłukły dzbany; a wziąwszy w lewą rękę swoję pochodnie, a w prawą rękę swoję trąby, aby trąbili, wołali: Miecz Pański i Giedeonów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'I stanęli każdy na miejscu swojem koło obozu, a strwożył się wszystek obóz, i krzycząc uciekali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Gdy tedy trąbili oni trzy sta mężów w trąby, obrócił Pan miecz jednego przeciw drugiemu we wszystkim obozie; a tak uciekło wojsko aż do Betseta w Sererat, aż do granicy Abelmehola w Tabbat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'A zebrawszy się mężowie Izraelscy z Neftalim, i z Aser, i ze wszystkiego pokolenia Manasesowego, gonili Madyjańczyki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Zatem posły rozesłał Giedeon na wszystkę górę Efraimską, mówiąc: Zabiegajcie Madyjanitom, a ubieżcie przed nimi wody aż do Betabara, i do Jordanu. Zebrali się tedy wszyscy mężowie z Efraima, i ubieżeli wody aż do Betabara i do Jordanu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Przytem pojmali dwoje książąt Madyjańskich, Oreba i Zeba; a zabili Oreba na skale Oreb, a Zeba zabili u prasy Zeb, i gonili Madyjanity, a głowę Oreba i Zeba przynieśli do Giedeona za Jordan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'I rzekli do niego mężowie z Efraim: Przeczżeś to nam uczynił, iżeś nas nie wezwał, gdyś szedł walczyć przeciwko Madyjanitom? i swarzyli się z nim srodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'A on rzekł: Cóżem ja takiego uczynił, jako wy? izali nie lepsze jest poślednie zbieranie wina Efraimowe, niż pierwsze zbieranie Abieserowe?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'W rękę waszą podał Bóg książęta Madyjańskie, Oreba i Zeba; i cóżem mógł takiego uczynić, jako wy? Tedy się uśmierzył duch ich przeciw niemu, gdy mówił te słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'A gdy przyszedł Giedeon do Jordanu, przeprawił się przezeń sam, i trzy sta mężów, którzy z nim byli spracowani w pogoni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'I rzekł do mieszczan w Sokot: Dajcie proszę po bochenku chleba ludowi, który idzie za mną, bo są spracowani, a ja będę gonił Zebeę i Salmana, króle Madyjańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Ale mu rzekli przedniejsi z Sokot: Izali już moc Zeby i Salmana jest w rękach twoich, żebyśmy dać mieli wojsku twemu chleba?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Którym rzekł Giedeon: Więc kiedy poda Pan Zebeę i Salmana w rękę moję, tedy będę młócił ciała wasze cierniem z tej puszczy i ostem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Szedł zasię stamtąd do Fanuel, i mówił także do nich; ale mu odpowiedzieli mężowie z Fanuel, jako odpowiedzieli mężowie w Sokot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Tedy też powiedział mężom z Fanuel, mówiąc: Gdy się wrócę w pokoju, rozwalę tę wieżę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Ale Zebee i Salmana byli w Karkor, i wojska ich z nimi około piętnastu tysięcy, wszyscy, którzy byli pozostali ze wszystkiego wojska z ludzi od wschodu słońca; a pobitych było sto i dwadzieścia tysięcy mężów walecznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Tedy ciągnął Giedeon drogą tych, co mieszkali w namiociech, od wschodu słońca Nobe i Jegbaa, i uderzył na obóz, (a obóz się był ubezpieczył,)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'A uciekli Zebee i Salmana, i gonił je, i pojmał onych dwóch królów Madyjańskich, Zebeę i Salmana, i wszystko wojsko ich strwożył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Potem się wrócił Giedeon, syn Joasów, z bitwy, niż weszło słońce;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'A pojmawszy młodzieńca z mężów Sokot, wypytał go, który spisał mu przedniejszych w Sokot i starszych jego, siedemdziesiąt i siedem mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'A przyszedłszy do mężów Sokot, rzekł: Otóż Zebeę i Salmana, którymiście mi urągali, mówiąc: Izali moc Zeby i Salmana jest w rękach twoich, abyśmy mieli dać mężom twoim spracowanym chleba?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Przetoż wziąwszy starsze miasta onego, i ciernia z onej pustyni i ostu, dał na nich przykład innym mężom Sokot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Wieżę też Fanuel rozwalił, i pobił męże miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Rzekł potem do Zeby i do Salmana: Co zacz byli mężowie oni, któreście pobili w Tabor? A oni odpowiedzieli: Takowi byli jakoś ty; każdy z nich na wejrzeniu był, jako syn królewski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'I rzekł: Braciać to moi, synowie matki mojej byli; żywie Pan, byście je byli żywo zachowali, nie pobiłbym was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'I rzekł do Jetra, pierworodnego swego: Wstań, a pobij je. Ale nie dobył młodzieńczyk miecza swego, przeto iż się bał; bo jeszcze był pacholęciem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Tedy rzekli Zebee i Salmana: Wstań ty, a rzuć się na nas; bo jaki mąż, taka siła jego. A tak wstawszy Giedeon, zabił Zebeę i Salmana, i pobrał klejnoty, które były na szyjach wielbłądów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'I rzekli Izraelczycy do Giedeona: Panuj nad nami, i ty, i syn twój, i syn syna twego; boś nas wybawił z ręki Madyjańczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Na to odpowiedział im Giedeon: Nie będę ja panował nad wami, ani będzie panował syn mój nad wami; Pan panować będzie nad wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Nadto rzekł do nich Giedeon: Będę was prosił o jednę rzecz, aby mi każdy z was dał nausznicę z łupu swego; (bo nausznice złote mieli, będąc Ismaelczykami.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'I rzekli: Radzić damy; i rozpostarłszy szatę rzucali na nię każdy nausznicę z łupów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'I była waga nausznic onych złotych, które sobie uprosił, tysiąc i siedemset syklów złota, oprócz klejnotów i zawieszenia i szat szarłatowych, które były na królach Madyjańskich, i oprócz łańcuchów, które były na szyjach wielbłądów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'I sprawił z tego Giedeon Efod, a położył go w mieście swem w Efra; i scudzołożył się tam wszystek Izrael, chodząc za nim, a było to Giedeonowi i domowi jego sidłem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'A tak byli poniżeni Madyjańczycy przed synami Izraelskimi, i nie podnieśli więcej głowy swojej; i była w pokoju ziemia przez czterdzieści lat za dni Giedeona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Wrócił się tedy Jerobaal, syn Joasów, i mieszkał w domu swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'A miał Giedeon siedmdziesiąt synów, którzy poszli z biódr jego; albowiem miał wiele żon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Miał też założnicę, która była z Sychem, a ta mu urodziła syna, i dała mu imię Abimelech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Umarł potem Giedeon, syn Joasów, w starości dobrej, a pogrzebion jest w grobie Joasa, ojca swego w Efra, które jest ojca Esrowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'A gdy umarł Giedeon, odwrócili się synowie Izraelscy, i scudzołożyli się, idąc za Baalem, i postawili sobie Baalberyt za boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'I nie pamiętali synowie Izraelscy na Pana, Boga swego, który je wyrwał z rąk wszystkich nieprzyjaciół ich okolicznych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'I nie uczynili miłosierdzia z domem Jerobaala Giedeona według wszystkich dobrodziejstw, które on był uczynił Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Tedy odszedł Abimelech, syn Jerobaalów, do Sychem, do braci matki swojej, i mówił do nich, i do wszystkiego narodu domu ojca matki swej, a rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Mówcie proszę, gdzieby słyszeli wszyscy przełożeni Sychem: Co wam lepszego, aby nad wami panowało siedmdziesiąt mężów, wszyscy synowie Jerobaalowi, czyli żeby panował nad wami mąż jeden? Wżdy pamiętajcie, żem ja kość wasza, i ciało wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Tedy mówili bracia matki jego o nim, gdzie słyszeli wszyscy przełożeni Sychem, wszystkie te słowa, i nakłoniło się serce ich za Abimelechem, bo rzekli: Brat nasz jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'I dali mu siedmdziesiąt srebrników z domu Baalberyt, i naprzyjmował za nie Abimelech ludzi lekkomyślnych, i tułaczów, którzy chodzili za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'I przyszedł w dom ojca swego do Efra, i pobił bracią swą, syny Jerobaalowe, siedmdziesiąt mężów na jednym kamieniu; tylko został Jotam, syn Jerobaalów, najmniejszy, iż się był skrył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'I zebrali się wszyscy mężowie Sychem, i wszystek dom Mello, a szedłszy obrali Abimelecha królem na równinie, kędy stał słup w Sychem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Co gdy powiedziano Jotamowi, szedłszy stanął na wierzchu góry Garyzym, a podniósłszy głos swój wołał, i rzekł im: Posłuchajcie mię mężowie Sychem, a was też Bóg usłyszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Zeszły się drzewa, aby pomazały nad sobą króla, i rzekły do oliwnego drzewa: Króluj nad nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Którym odpowiedziało oliwne drzewo: Izali opuszczę tłustość moję, przez którą uczczony bywa Bóg i ludzie, a pójdę, abym wystawione było nad drzewy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Rzekły potem drzewa do figowego drzewa: Pójdź ty, króluj nad nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Którym odpowiedziało figowe drzewo: Izali opuszczę słodkość moję, i owoc mój wyborny, a pójdę, abym wystawione było nad drzewy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Potem rzekły drzewa do macicy winnej: Pójdź ty, króluj nad nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Tedy im odpowiedziała macica: Izali opuszczę moszcz mój, który uwesela Boga i ludzie, a pójdę, abym wystawiona była nad drzewy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'I rzekły wszystkie drzewa do ostu: Pójdź ty, króluj nad nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Tedy odpowiedział oset drzewom: jeźli wy prawdziwie chcecie pomazać mię za króla nad sobą, pójdźcież, a odpoczywajcie pod cieniem moim, a jeźliż nie, niech wynijdzie ogień z ostu, a spali Cedry Libańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'A tak teraz jeźliście prawdziwie a szczerze uczynili, obrawszy sobie królem Abimelecha; a jeźliście się dobrze obeszli z Jerobaalem i z domem jego, a jeźliście podług dobrodziejstw ręki jego uczynili z nim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, '(Albowiem walczył ojciec mój za was, i podał duszę swą w niebezpieczeństwo, aby was wyrwał z ręki Madyjańczyków;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Aleście wy powstali przeciw domowi ojca mego dziś, i pobiliście syny jego, siedmdziesiąt mężów na jednym kamieniu, i obraliście królem Abimelecha, syna służebnicy jego, nad mężami Sychem, iż bratem waszym jest.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Jeźliście prawdziwie a szczerze obeszli się z Jerobaalem, i z domem jego dnia tego, weselcież się z Abimelecha, a on niech się też weseli z was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Ale jeźliż nie, niechajże wynijdzie ogień z Abimelecha, a pożre męże Sychem, i dom Mello; niechajże też wynijdzie ogień od mężów Sychem, i z domu Mello, a pożre Abimelecha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Tedy uciekł Jotam, a uciekłszy poszedł do Beer, i mieszkał tam, bojąc się Abimelecha, brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'A tak panował Abimelech nad Izraelem przez trzy lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'I posłał Bóg ducha złego między Abimelecha i między męże Sychemskie, a złamali wiarę mężowie Sychem Abimelechowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Aby się zemszczono krzywdy siedemdziesięciu synów Jerobaalowych, aby krew ich przyszła na Abimelecha, brata ich, który je pobił, i na męże Sychemskie, którzy zmocnili ręce jego, aby pobił bracią swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'I zasadzili się nań mężowie Sychemscy na wierzchu gór, a rozbijali każdego, który jedno szedł tamtą drogą. I powiedziano to Abimelechowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Nadto przyszedł Gaal, syn Obedów, i bracia jego, i przyszedł do Sychem, a poufali mu mężowie Sychem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'A wyszedłszy na pola zbierali wina swoje, i tłoczyli, weseląc się; a wszedłszy w dom bogów swoich, jedli i pili, a złorzeczyli Abimelechowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Tedy rzekł Gaal, syn Obedów: Cóż jest Abimelech? i co jest Sychem, żebyśmy mu służyli? azaż nie jest syn Jerobaalów, a Zebul urzędnikiem jego? raczej służcie mężom Hemora, ojca Sychemowego; bo czemuż byśmy onemu służyć mieli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'O by kto podał ten lud w ręce moje, aby sprzątnął Abimelecha! I rzekł Abimelechowi: Zbierz swoje wojsko, a wynijdź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'A usłyszawszy Zebul, przełożony miasta onego, słowa Gaala, syna Obedowego, zapalił się gniew jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'I wyprawił posły do Abimelecha potajemnie, mówiąc: Oto Gaal, syn Obedów, i bracia jego przyszli do Sychem, a oto chcą walczyć z miastem przeciwko tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'A tak teraz wstań nocą, ty i lud, który jest z tobą, a uczyń zasadzkę w polu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'A rano, gdy słońce wznijdzie, wstawszy uderzysz na miasto; a gdy on i lud, który jest z nim, wynijdzie przeciw tobie, uczynisz z nim, co będzie chciała ręka twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Tedy wstawszy Abimelech, i wszystek lud, który z nim był, w nocy, zasadzili się przeciw Sychem na czterech miejscach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'A wyszedłszy Gaal, syn Obedów, stanął w samej bramie miasta; wstał też i Abimelech, i lud, który z nim był, z zasadzki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'A widząc Gaal lud, rzekł do Zebula: Oto, lud idzie z wierzchu gór. Któremu odpowiedział Zebul: Cień góry ty widzisz, jakoby ludzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Tedy po wtóre rzekł Gaal, mówiąc: Oto, lud zstępuje z góry a jeden huf idzie drogą równiny Meonenim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Tedy rzekł do niego Zebul: Gdzież teraz usta twoje, które mówiły: Co jest Abimelech, abyśmy mu służyć mieli? izali to nie ten lud, któryś wzgardził? wnijdź teraz, a walcz przeciw niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'A tak wyszedł Gaal przed mężami Sychem, a walczył przeciw Abimelechowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'I gonił go Abimelech, gdy przed nim uciekał, a poległo wiele rannych aż do samej bramy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'I został Abimelech w Aruma; a Zebul wygnał Gaala z bracią jego, aby nie mieszkali w Sychem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Ale nazajutrz wyszedł lud w pole, i powiedziano to Abimelechowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Wziąwszy tedy lud, rozdzielił go na trzy hufce, i zasadził się w polu; a widząc, a oto lud wychodził z miasta, wypadł na nie, i pobił je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Bo Abimelech i hufy, które z nim były, uderzyły na nie, i stanęli u samej bramy miasta, a inne dwa hufy uderzyły na wszystkie, którzy byli w polu, i pobili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'A Abimelech dobywał miasta przez on wszystek dzień, i wziął je; a lud, który w niem był, pomordował, a zburzywszy miasto, posiał je solą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'A usłyszawszy wszyscy mężowie, którzy byli na wieży Sychem, przyszli do twierdzy domu boga Beryt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'I opowiedziano Abimelechowi, że się tam zgromadzili wszyscy mężowie wieży Sychem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Tedy szedł Abimelech na górę Salmon, on i wszystek lud, który był z nim; a nabrawszy z sobą siekier, uciął gałąź z drzewa, a wziąwszy ją, włożył na ramiona swoje, i rzekł do ludu, który z nim był: Co widzicie, żem uczynił, prędko czyńcie tak, jak o ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'A tak uciąwszy z onego wszystkiego ludu każdy gałąź swoję, szli za Abimelechem, a kładli je około twierdzy i spalili niemi twierdzą ogniem, i poginęło tam wszystkich mężów wieży Sychemskiej około tysiąca mężów i niewiast.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Potem szedł Abimelech do Tebes, a położywszy się przeciwko Tebes, dobył go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Ale wieża była mocna w pośrodku miasta, na którą uciekli wszyscy mężowie, i niewiasty, i wszyscy przedniejsi miasta, a zamknąwszy ją za sobą, weszli na dach wieży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Tedy przyszedł Abimelech aż do samej wieży, i dobywał jej, a stanąwszy u samych drzwi wieży, chciał ją spalić ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Między tem zrzuciła niewiasta niektóra sztukę kamienia od żarn na głowę Abimelechowę, i rozbiła wierzch głowy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Który natychmiast zawoławszy pacholika, co nosił broń jego, rzekł do niego: Dobądź miecza twego, a zabij mię, by snać nie rzeczono o mnie: Niewiasta go zabiła: a tak przebił go pacholik jego, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'A widząc mężowie Izraelscy, iż umarł Abimelech, rozeszli się każdy do miejsca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'I oddał Bóg ono złe Abimelechowi, które uczynił nad ojcem swoim, zabiwszy siedmdziesiąt braci swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'I wszystko złe mężów Sychem obrócił Bóg na głowę ich; a przyszło na nie przeklęstwo Jotama, syna Jerobaalowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'I powstał po Abimelechu na obronę Izraela Tola, syn Fui, syna Dodowego, mąż z pokolenia Isascharowego, a ten mieszkał w Samir na górze Efraim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'I sądził Izraela przez dwadzieścia i trzy lata, potem umarł, i pogrzbion jest w Samir.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'A po nim powstał Jair Galaadczyk, który sądził Izraela przez dwadzieścia i dwa lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'A ten miał trzydzieści synów, którzy jeździli na trzydziestu ośląt, a mieli trzydzieści miast, które zwano Awot Jair aż po dzisiejszy dzień w ziemi Galaadskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'I umarł Jair, a pogrzebion jest w Kamon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Lecz znowu synowie Izraelscy czynili złe przed oczyma Pańskiemi, a służąc Baalowi, i Astaratowi, i bogom Syryjskim, i bogom Sydońskim, i bogom Moabskim, i bogom synów Ammon, i nawet bogom Filistyńskim, a opuściwszy Pana, nie służyli mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Przetoż się wzruszył gniewem Pan przeciw Izraelowi, i podał je w ręce Filistynów, i w ręce synów Ammonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Którzy trapili i uciskali syny Izraelskie od onego roku przez osiemnaście lat, wszystkie syny Izraelskie, którzy byli przed Jordanem w ziemi Amorejczyka, która jest w Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Przeprawili się też synowie Ammonowi za Jordan, aby walczyli z Judą, i z Benjaminem, także i z domem Efraimowym, i ścisnęli Izraelczyki bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Tedy wołali synowie Izraelscy do Pana, mówiąc: Zgrzeszyliśmy tobie, żeśmy opuścili ciebie, Boga naszego, i służyliśmy Baalom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Ale Pan rzekł do synów Izraelskich: Izalim was od Egipczyków, i od Amorejczyków, od synów Ammonowych, i od Filistynów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'I od Sydończyków, i Amalekitów, i Mahanitów, którzy was trapili, gdyście wołali do mnie, nie wybawił z ręki ich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Aleście wy mię opuścili, a służyliście bogom cudzym; przetoż was więcej nie wybawię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Idźcież, a wołajcie do bogów, któreście sobie obrali; oni niechaj was wybawią czasu ucisku waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'I odpowiedzieli synowie Izraelscy Panu: Zgrzeszyliśmy; uczyńże ty z nami, co się zda dobrego w oczach twoich, tylko wybaw nas prosimy dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'I wyrzucili bogi cudze z pośrodku siebie, a służyli Panu, i użalił się Pan utrapienia Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Zebrali się tedy synowie Ammonowi, a położyli się obozem w Galaad; zebrali się też i synowie Izraelscy, a położyli się obozem w Masfa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Tedy rzekł lud i przełożeni w Galaad między sobą: Kto się naprzód pocznie potykać z syny Ammonowymi, ten będzie hetmanem nad wszystkimi mieszkającymi w Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Ale Jefte Galaadczyk był człowiekiem bardzo mężnym, a był synem niewiasty nierządnej, z którą spłodził Galaad tegoż Jeftego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Ale i żona Galaadowa narodziła mu synów; a dorósłszy synowie tej żony, wygnali Jeftego, mówiąc mu: Nie będziesz brał dziedzictwa w domu ojca naszego, boś ty jest synem inszej niewiasty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Uciekł tedy Jefte przed bracią swoją, a mieszkał w ziemi Tob: i zebrali się do niego ludzie ogołoceni, i poszli z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'I stało się potem, że walczyli synowie Ammonowi z Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'A gdy poczęli walczyć Ammonitowie z Izraelem, tedy poszli starsi z Galaad, aby wzięli Jeftego z ziemi Tob.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'I rzekli do niego: Pójdź, a bądź nam za hetmana, a będziemy walczyli przeciwko synom Ammonowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Ale Jefte odpowiedział starszym Galaad: Izażeście wy mnie nie mieli w nienawiści, i wygnaliście mię z domu ojca mego? przeczżeście przyszli teraz do mnie, gdy ucisk przyszedł na was?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Tedy rzekli starsi z Galaad do Jeftego: Dla tegośmy się teraz wrócili do ciebie, abyś szedł z nami, a walczył przeciwko synom Ammonowym, a był nam za hetmana, wszystkim mieszkającym w Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'I odpowiedział Jefte starszym z Galaad: Ponieważ wy mnie przywracacie, a chcecie, abym walczył przeciwko synom Ammonowym, a jeźli mi je poda Pan, będęż wam za hetmana?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'I rzekli starsi z Galaad do Jeftego: Pan będzie świadkiem między nami, jeźliż tak według słowa twego nie uczynimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Tedy szedł Jefte z starszymi z Galaad, i postanowił go lud hetmanem i książęciem nad sobą; i mówił Jefte wszystkie te słowa przed Panem w Masfa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Potem wyprawił Jefte posły do króla synów Ammonowych, mówiąc: Co ja mam z tobą, żeś przyciągnął na mię, abyś walczył przeciwko ziemi mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Na co odpowiedział król synów Ammonowych posłom Jeftego: Że wziął Izrael ziemię moję, gdy szedł z Egiptu, od Arnon aż do Jabok i aż do Jordanu: przetoż teraz wróć mi ją w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Po wtóre jeszcze Jefte wyprawił posły do króla synów Ammonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'I rzekł mu: Tak mówi Jefte: Nie wziął Izrael ziemi Moabskiej, ani ziemi synów Ammonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Ale gdy z Egiptu szedł Izrael przez puszczą aż ku morzu czerwonemu, a przyszedł do Kades.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Skąd wyprawił Izrael posły do króla Edomskiego, mówiąc: Proszę niech przejdę przez ziemię twoję, i nie pozwolił król Edomski, także i do króla Moabskiego posłał, i nie pozwolił; a tak został Izrael w Kades.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'A gdy szedł przez puszczą, obszedł ziemię Edomską, i ziemię Moabską, a przyszedł od wschodu słońca ziemi Moabskiej, i położyli się obozem za Arnon, a nie wszedł w granice Moabskie; bo Arnon jest granicą Moabską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Dlategoż wyprawił Izrael posły do Sehona, króla Amorejskiego, króla w Hesebon, i rzekł mu Izrael: Niech przejdę proszę przez ziemię twoję aż do miejsca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Ale nie dowierzał Sehon Izraelowi, aby iść miał przez granicę jego; owszem zebrał Sehon wszystek lud swój, i położył się obozem w Jasa, i zwiódł bitwę z Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'I dał Pan, Bóg Izraelski, Sehona, i wszystek lud jego w ręce Izraelowe, i poraził je, a posiadł Izrael wszystkę ziemię Amorejczyka, który mieszkał w onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'A tak posiedli wszystkie granice Amorejskie od Arnon aż do Jabok, a od puszczy aż do Jordanu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Ponieważ tedy Pan, Bóg Izraelski wypędził Amorejczyka przed ludem swym Izraelskim, przecz ty chcesz panować nad nim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Azaż, coć dał posieść Kamos, bóg twój, tego nie posiędziesz? tak, kogo Pan, Bóg nasz, wygnał przed oblicznością naszą, tego też dziedzictwo posiadamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Do tego czemżeś ty lepszy nad Balaka syna Seferowego, króla Moabskiego? zaż się on kiedy wadził z Izrealem? zaż kiedy walczył przeciwko niemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Oto przez trzy sta lat mieszkał Izrael w Hesebon, i we wsiach jego, także w Aroer, i we wsiach jego, i we wszystkich miastach, które są przy granicy Arnon; czemużeście ich nie odjęli przez ten czas?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'A tak nie jam tobie winien, ale ty mnie źle czynisz, że walczysz przeciwko mnie; niech Pan, który jest Sędzią, rozsądzi dziś między syny Izraelskimi i między syny Ammonowymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Ale nie usłuchał król synów Ammonowych słów Jeftego, które wskazał do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'I był nad Jeftem duch Pański, a przeszedł przez Galaad, i przez Manase; przeszedł też przez Masfa w Galaad, a z Masfy w Galaad ciągnął przeciw synom Ammonowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Tamże uczynił Jefte ślub Panu, mówiąc: Jeźli pewnie podasz syny Ammonowe w ręce moje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'Tedy to, cobykolwiek wyszło ze drzwi domu mego przeciwko mnie, gdy się wrócę w pokoju od synów Ammonowych, to mówię będzie Panu, albo ofiarować je będę na całopalenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'A tak Jefte ciągnął przeciwko synom Ammonowym, aby walczył z nimi, i podał je Pan w ręce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'I poraził je od Aroer aż idąc do Menit, dwadzieścia miast, i aż do równiny winnic porażką bardzo wielką, a poniżeni są synowie Ammonowi przed syny Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'A gdy się wracał Jefte do Masfa do domu swego, oto, córka jego wyszła przeciw niemu, z bębny, i z muzyką; a ta była jedynaczka, bo nie miał żadnego syna ani innej córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'I stało się, gdy ją ujrzał, rozdarł odzienie swoje, i rzekł: Ach, córko moja, bardzoś mię poniżyła! i tyś jest z tych, którzy mię frasują, gdyżem ślub uczynił Panu, a nie będę mógł odmienić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Któremu ona odpowiedziała: Ojcze mój, uczyniłeś ślub Panu, uczyńże ze mną tak, jakoś wyrzekł usty twojemi, gdyć tylko dał Pan pomstę nad nieprzyjacioły twemi, nad syny Ammonowymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Nadto rzekła do ojca swego: To mi tylko uczyń: puść mię na dwa miesiące, że pójdę a wstąpię na góry i opłakiwać będę panieństwo moje, ja i towarzyszki moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'A on rzekł: Idź; i puścił ją na dwa miesiące. Poszła tedy ona i towarzyszki jej, a opłakiwała panieństwo swoje na górach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'A gdy wyszły dwa miesiące, wróciła się od ojca swego, i wypełnił nad nią ślub swój, który był uczynił; a tak ona nie poznała męża. I weszło to w zwyczaj w Izraelu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Iż na każdy rok schodziły się córki Izraelskie aby się rozmawiały z córką Jeftego Galaadczyka, przez cztery dni w rok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'I zebrali się mężowie Efraimscy, a przyszedłszy ku północy, rzekli do Jeftego: Przeczżeś szedł walczyć przeciwko synom Ammonowym, a nie wezwałeś nas, abyśmy szli z tobą? przetoż dom twój i ciebie spalimy ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'I rzekł Jefte do nich: Miałem nie mały spór ja i lud mój z syny Ammonowymi, i wzywałem was, a nie wybawiliście mię z rąk ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'A widząc, żeście mię wybawić nie chcieli, odważyłem zdrowie swoje, i ciągnąłem przeciw synom Ammonowym, a podał je Pan w ręce moje, i przeczżeście przyszli do mnie dnia tego, abyście walczyli przeciwko mnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'A tak zebrawszy Jefte wszystkie męże z Galaad, walczył z Efraimem; i porazili mężowie z Galaad Efraima, przeto iż mówili: Wy Galaadczycy, którzy się bawicie między Efraimitami i między Manasesytami, zbiegowieście od Efraimitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'I odjęli Galaadczycy brody Jordańskie Efraimowi; a gdy mówili uciekający z Efraimczyków: Niech przejdę, tedy pytali mężowie Galaadscy: A Efratejczykieś ty: A jeźli rzekł: Nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Tedy mu mówili: Wymówże teraz Szybolet; jeźli rzekł: Sybolet, a inaczej nie mógł wymówić, tedy pojmawszy go, zabijali go u brodu Jordańskiego. I poległo na on czas z Efraima czterdzieści i dwa tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'A tak sądził Jefte Galaadczyk Izraela przez sześć lat; potem umarł Jefte Galaadczyk, a pogrzebion jest w jednem z miast Galaadskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Potem sądził po nim Izraela Abesan z Betlehem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'A miał trzydzieści synów, i trzydzieści córek, które powydawał od siebie, trzydzieści żon przywiódł synom swoim zinąd, i sądził Izraela przez siedem lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Umarł potem Abesan, i pogrzebion jest w Betlehem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'A po nim sądził Izraela Elon Zabulończyk, i sądził Izraela przez dziesięć lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Potem umarł Elon Zabulończyk, i pogrzebiony jest w Ajalon w ziemi Zabulon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'A po nim sądził Izraela Abdon, syn Hellelów, Faratończyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'A ten miał czterdzieści synów, i trzydzieści wnuków, którzy jeździli na siedemdziesięciu oślętach; i sądził Izraela przez osiem lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Umarł potem Abdon, syn Hellelów, Faratończyk, i pogrzebiony jest w Faratonie w ziemi Efraimskiej, na górze Amalekitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Potem znowu synowie Izraelscy czynili złe przed oczyma Pańskiemi, i podał je Pan w ręce Filistynów przez czterdzieści lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Tedy był mąż niektóry z Saraa, z pokolenia Dan, imieniem Manue, a żona jego była niepłodną, i nie rodziła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'I ukazał się Anioł Pański onej niewieście, a rzekł do niej: Otoś teraz niepłodną, aniś rodziła; ale poczniesz i porodzisz syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Przetoż się teraz strzeż, abyś nie piła wina, i napoju mocnego, i abyś nie jadła nic nieczystego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Bo oto poczniesz i porodzisz syna, a brzytwa nie postoi na głowie jego, bo Nazarejczykiem Bożym będzie to dziecię zaraz z żywota; a on pocznie wybawiać Izraela z ręki Filistynów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Tedy przyszła niewiasta, i powiedziała to mężowi swemu, mówiąc: Mąż Boży przyszedł do mnie, którego oblicze było jako oblicze Anioła Bożego, bardzo straszne, i nie pytałam go, skąd był, ani mi imienia swego oznajmił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Tylko mi rzekł: Oto, poczniesz i porodzisz syna; przetoż teraz nie pij wina, ani napoju mocnego, ani jedz co nieczystego; bo Nazarejczykiem Bożym będzie to dziecię zaraz z żywota aż do dnia śmierci swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Tedy się modlił Manue Panu, mówiąc: Proszę Panie mój, mąż Boży, któregoś posłał, niech przyjdzie proszę znowu do nas, a nauczy nas, co czynić mamy z dziecięciem, które się narodzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'I wysłuchał Bóg głos Manuego; bo przyszedł Anioł Boży znowu do niewiasty onej, gdy siedziała na polu; ale Manue, mąż jej, nie był z nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Tedy kwapiąc się ona niewiasta, bieżała, i opowiedziała mężowi swemu, i rzekła mu: Oto mi się ukazał mąż on, który był przyszedł przedtem do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'A wstawszy Manue szedł za żoną swoją; a przyszedłszy do onego męża, rzekł mu: Tyżeś jest ten mąż, któryś mówił z żoną moją? A on rzekł: Jam jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'I rzekł Manue: Niech się teraz spełni słowo twoje; ale cóż będzie za obyczaj dziecięcia, i co za sprawa jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'I odpowiedział Anioł Pański Manuemu: Wszystkiego, com powiedział żonie twojej, niech się strzeże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Żadnej rzeczy, która pochodzi z winnej macicy, niechaj nie je; także wina ani napoju mocnego, niech nie pije, ani żadnej rzeczy nieczystej niech nie je, a com jej kolwiek przykazał, tego niech przestrzega.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Tedy rzekł Manue do Anioła Pańskiego: Daj się proszę zatrzymać, a nagotujemy przed cię koźlątko z stada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Ale Anioł Pański odpowiedział Manuemu: Choćbyś mię zatrzymał, nie będę jadł chleba twego; ale jeźli będziesz chciał sprawić całopalenie, ofiarujże je Panu; bo nie wiedział Manue, żeby on był Anioł Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Tedy rzekł Manue do Anioła Pańskiego: Cóż za imię twoje? abyśmy, gdy się spełni słowo twoje, uczcili cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Któremu odpowiedział Anioł Pański: Przeczże pytasz o imię moje, które jest dziwne?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Wziął tedy Manue koźlę z stada, i ofiarę śniedną, i ofiarował to na opoce Panu, i uczynił cud, a Manue i żona jego patrzyli na to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'A gdy wstępował płomień z ołtarza ku niebu, tedy wstąpił Anioł Pański w płomieniu ołtarzowym, a Manue, i żona jego widząc to, upadli na twarze swe na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'A potem nie ukazał się więcej Anioł Pański Manuemu, ani żonie jego; i poznał Manue, że to był Anioł Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'I rzekł Manue do żony swojej: Koniecznie pomrzemy, bośmy Boga widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Któremu odpowiedziała żona jego: Gdyby nas chciał Pan zabić, nie przyjąłby z rąk naszych całopalenia, i ofiary śniednej, aniby nam był okazał tego wszystkiego, aniby nam na ten czas był objawił takowych rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Porodziła tedy ona niewiasta syna, i nazwała imię jego Samson; i rosło dziecię, a błogosławił mu Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'I począł go Duch Pański umacniać w obozie Dan między Saraa i między Estaol.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Szedł tedy Samson do Tamnaty, a ujrzał tam niewiastę z córek Filistyńskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'A przyszedłszy oznajmił ojcu swemu i matce swojej, mówiąc; Niewiastem widział w Tamnacie z córek Filistyńskich; przetoż teraz weźmijcie mi ją za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'I rzekł mu ojciec jego, i matka jego; Azaż nie masz między córkami braci twych, i we wszystkim ludu moim niewiasty, że chcesz iść a wziąć sobie żonę z Filistynów nieobrzezanych? Odpowiedział Samson ojcu swemu: Tę mi weźmijcie, bo się podobała oczom moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'A ojciec jego i matka jego nie wiedzieli, że to było od Pana; bo on przyczyny szukał na Filistyny, gdy na on czas Filistyni panowali nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Tedy szedł Samson z ojcem swym i z matką swoją do Tamnaty, a przychodząc ku winnicom Tamnaty, oto, lew młody ryczący zabieżał mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'I przypadł nań Duch Pański, a rozdarł go, jakoby rozdarł koźlę, choć nic nie miał w rękach swych; i nie oznajmił ojcu swemu i matce swojej, co uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Przyszedłszy tedy mówił z oną niewiastą, a podobała się oczom Samsonowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'A wróciwszy się po kilku dniach, aby ją pojął, zstąpił, aby oglądał on ścierw lwi, a oto, rój pszczół był w ścierwie lwim, i miód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'A wziąwszy go w ręce swoje szedł drogą i jadł, a przyszedłszy do ojca swego i do matki swojej, dał im, i jedli; ale im nie powiedział, że z ścierwu lwiego nabrał miodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'tedy szedł ojciec jego do onej niewiasty, i sprawił tam Samson wesele; bo tak czyniwali młodzieńcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'A gdy go ujrzeli Filistyni, wzięli trzydzieści towarzyszów, aby byli przy nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Do których rzekł Samson: Zadam wam zagadkę, a jeźli ją zgadniecie przez siedem dni wesela i wyłożycie mi ją, tedy wam dam trzydzieści prześcieradeł, i trzydzieści szat odmiennych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'A jeźliż mi jej nie zgadniecie, tedy wy mnie dacie trzydzieści prześcieradeł, i trzydzieści szat odmiennych; którzy mu odpowiedzieli: Zadaj zagadkę twoję; a będziemy jej słuchali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'I rzekł do nich: Z pożerającego wyszedł pokarm, a z mocnego wyszła słodkość; i nie mogli zgadnąć onej zagadki przez trzy dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'I rzekli dnia siódmego do żony Samsonowej: Namów męża twego, aby nam powiedział zagadkę, byśmy snać nie spalili ciebie, i domu ojca twego ogniem; na tożeście nas wezwali, abyście posiedli majętność naszę, czy nie na to?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Płakała tedy żona Samsonowa nań, mówiąc: Zaprawdę mię masz w nienawiści, a nie miłujesz mię; zadałeś zagadkę synom ludu mego, a nie chcesz mi jej oznajmić. I rzekł do niej: Otom jej ojcu memu i matce mojej nie oznajmił, a tobie bym miał oznajmić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'I płakała nań przez one siedem dni, póki mieli wesele. Stało się tedy dnia siódmego, że jej oznajmił, bo mu się uprzykrzała. A ona powiedziała onę zagadkę synom ludu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Przetoż rzekli do niego mężowie onego miasta siódmego dnia przed zachodem słońca: Cóż słodszego nad miód, a co mocniejszego nad lwa? którym on odpowiedział: Byście byli nie orali jałowicą moją, nie zgadlibyście byli zagadki mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'I przypadł nań Duch Pański, a szedłszy do Aszkalonu, zabił z nich trzydzieści mężów a wziąwszy łupy z nich, dał szaty odmienne onym, którzy zgadli zagadkę, i rozgniewawszy się bardzo poszedł do domu ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'I dostała się żona Samsonowa towarzyszowi jego, z którym miał towarzystwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'I stało się po kilku dni, pod czas żniwo pszenicznego, że nawiedził Samson żonę swoję, wziąwszy koźlę z stada, i mówił: Wnijdę do żony mojej do komory; ale mu nie dopuścił ojciec jej wnijść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Bo rzekł ojciec jej, mówiąc: Mniemałem, żeś ją miał w nienawiści; przetoż dałem ją towarzyszowi twemu; azaż siostra jej młodsza nie jest cudniejsza nad nię? weźmijże ją sobie miasto niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'I odpowiedział im Samson: Już teraz nie będę winien napotem Filistynom, choć im uczynię co złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Odszedłszy tedy Samson ułapał trzy sta liszek, a nabrawszy pochodni, przywiązał ogon do ogona, i uwiązał pochodnią jednę między dwoma ogonami w pośrodku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Potem zapaliwszy ogniem pochodnie, rozpuścił je między zboża Filistyńskie, i popalił tak stogi jako zboża stojące, i winnice z oliwnicami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Tedy rzekli Filistynowie: Któż to uczynił? I odpowiedziano: Samson, zięć Tamnatczyków, przeto że mu wziął żonę jego, a dał ją towarzyszowi jego. Poszli tedy Filistynowie, i spalili ją i ojca jej ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Którym rzekł Samson: Chociaście to uczynili, przecięć się ja pomszczę nad wami, a potem przestanę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'A tak potłukł je okrutnie od biódr aż do goleni, a odszedłszy mieszkał na wierzchu opoki Etam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Przyciągnęli tedy Filistynowie, a położywszy się obozem w Juda, rozciągnęli się aż do Lechy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Tedy rzekli mężowie Juda: Przeczżeście wyciągnęli przeciwko nam? I odpowiedzieli: Przyszliśmy, abyśmy związali Samsona, i uczynili mu, jako on nam uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'A tak wyszło trzy tysiące mężów z Juda na wierzch opoki Etam, i mówili do Samsona: Azaż nie wiesz, że panują nad nami Filistynowie? I cóżeś nam to uczynił? I odpowiedział im: Jako mi uczynili, i takiem im uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'I rzekli mu: Przyszliśmy, abyśmy cię związali, i wydali w ręce Filistynów; którym odpowiedział Samson: Przysiężcie mi, że się na mię sami nie targniecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'A oni mu rzekli, mówiąc: Nie, tylko związawszy cię, wydamy cię w ręce ich; ale cię nie zabijemy. A tak związali go dwoma powrozami nowemi, i sprowadzili go z opoki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Który gdy przyszedł aż do Lechy, tedy Filistynowie krzycząc bieżeli przeciw niemu; ale Duch Pański przypadł nań, i stały się powrozy, które były na ramionach jego, jako nici lniane ogniem spalone, i rozerwały się związki z rąk jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Tedy znalazłszy czeluść oślą świeżą, a wyciągnąwszy po nię rękę swoję, wziął ją, i zabił nią tysiąc mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Zatem rzekł Samson: Czeluścią oślą kupę jednę albo dwie kupy, a czeluścią oślą zabiłem tysiąc mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'A gdy przestał mówić, porzucił czeluść z ręki swej, i nazwał miejsce ono Ramat Lechy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Zatem upragnął bardzo, i zawołał do Pana mówiąc: Tyś dał przez rękę sługi twego to wybawienie wielkie, a teraz umrę od pragnienia, albo wpadnę w ręce nieobrzezańców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'A tak rozszczepił Bóg skałę w Lechy, i wyszły z niej wody, i napił się, i wrócił się duch jego a ożył; przetoż nazwał imię onego źródła: źródło wzywającego, które jest w Lechy aż do dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'I sądził lud Izraelski za dni Filistynów przez dwadzieścia lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Potem szedł Samson do Gazy, a ujrzawszy tam niewiastę nierządną, wszedł do niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'I powiedziano mieszczanom w Gazie: Przyszedł tu Samson; którzy obstąpiwszy go, strzegli nań całą noc w bramie miejskiej, a sprawując się cicho przez onę całą noc, mówili: Gdy się pocznie rozedniwać, zabijemy go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Ale Samson spał aż do północy, a wstawszy o północy, ujął wrota bramy miejskiej ze dwiema podwojami, i wyrwał je z zaworą, i włożył na ramiona swoje, a zaniósł je na wierzch góry, która była przeciw Hebronowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'I stało się potem, że się rozmiłował niewiasty w dolinie Sorek, której imię Dalila.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'I przyszli do niej książęta Filistyńskie, i mówili jej: Oszukaj go, a wywiedz się, w czem jest moc jego wielka, a jako byśmy go przemóc i związawszy utrapić mogli? a dać każdy z nas tysiąc i sto srebrników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Tedy rzekła Dalila do Samsona: Powiedz mi proszę, w czem jest moc twoja wielka, a czem byś związany i utrapiony być mógł?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'I odpowiedział jej Samson: Jeźliby mię związano siedmią wici surowych, które jeszcze nie uschły, tedy osłabieję, i będę jako inny człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'I przyniosły jej książęta Filistyńskie siedem wici surowych, które jeszcze nie były uschły, i związała go niemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'A oni się byli nań zasadzili w komorze, i rzekła mu: Filistynowie nad tobą, Samsonie; ale on zerwał wici, jakoby kto zerwał nić zgrzebną, ogniem napaloną; i nie poznano, w czem była moc jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Rzekła potem Dalila do Samsona: Otoś mię oszukał, i skłamałeś przede mną; teraz powiedz mi proszę, czem by cię związać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'A on jej odpowiedział: Jeźliby mię związano powrozami nowemi, których jeszcze nie używano, tedy osłabieję, i będę jako inny człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'A tak wzięła Dalila powrozy nowe, i związała go niemi, i rzekła do niego: Filistynowie nad tobą, Samsonie; (a oni się byli nań zasadzili w komorze,) ale porwał je na ramionach swych jako nici.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Rzekła zatem Dalila do Samsona: Pókiż ze mnie szydzić będziesz, i kłamać przede mną? powiedzże mi, czem byś mógł być związany? I powiedział jej? Gdybyś przywiła siedem kędzierzy głowy mojej do wału tkackiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Ona tedy przybiwszy gwoździem do wału tkackiego rzekła do niego: Filistynowie nad tobą, Samsonie; ale on ocuciwszy się ze snu swego, wyrwał gwóźdź z osnową i z wałem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Znowu rzekła do niego: Jakoż mówisz, miłuję cię? a serce twoje nie jest ze mną. Jużeś mię po trzy kroć oszukał, i nie powiedziałeś mi, w czem jest twoja moc wielka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'A gdy mu się uprzykrzała słowy swemi na każdy dzień, i trapiła go, aż zemdlała dusza jego na śmierć,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Tedy jej otworzył cale serce swoje, i powiedział jej: Brzytwa nigdy nie postała na głowie mojej, gdyżem jest Nazarejczykiem Bożym zaraz z żywota matki mojej; gdyby mię ogolono, odejdzie ode mnie moc moja, i osłabieję, i będę jako inny człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Widząc tedy Dalila, że jej otworzył cale serce swoje, posłała i wezwała książąt Filistyńskich, mówiąc: Pójdźcież jeszcze raz, boć mi otworzył cale serce swoje; i przyszły do niej książęta Filistyńskie, niosąc srebro w rękach swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Tedy go uśpiła na łonie swojem, a przyzwawszy niektórego człowieka, dała ogolić siedem kędzierzy głowy jego; potem go jęła draźnić, gdy odeszła moc jego od niego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'I rzekła: Filistynowie nad tobą, Samsonie. A ocuciwszy się ze snu swego, rzekł: Wynijdę jako i pierwej, a wybiję się; a nie wiedział, że Pan odstąpił od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Tedy pojmawszy go Filistynowie, wyłupili mu oczy, i wiedli go do Gazy, związawszy go dwoma miedzianymi łańcuchami, i musiał mleć w domu więźniów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Potem poczęły włosy na głowie jego odrastać po onem goleniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'A książęta Filistyńskie zebrali się sprawować ofiary wielkie Dagonowi, bogu swemu, weselili się, i mówili: Podał bóg nasz w ręce nasze Samsona, nieprzyjaciela naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Którego też ujrzawszy lud chwalili boga swego, bo mówili: Podał bóg nasz w ręce nasze nieprzyjaciela naszego, a tego, który pustoszył ziemię naszę, i który wiele z naszych pozabijał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'I stało się, gdy byli dobrej myśli, że rzekli: Zawołajcie Samsona, aby błaznował przed nami. A tak zawołano Samsona z domu więźniów, aby błaznował przed nimi; i postawili go między dwoma słupami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Zatem rzekł Samson do chłopca, który go trzymał za rękę jego. Przywiedź mię, abym pomacał słupów, na których dom stoi, i podparł się na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'A dom pełen był mężów i niewiast; tamże były wszystkie książęta Filistyńskie, a na dachu około trzech tysięcy mężów i niewiast, którzy się przypatrowali, gdy błaznował Samson.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Wzywał tedy Samson Pana, i rzekł: Panie Boże, wspomnij na mię, proszę, a zmocnij mię proszę tylko ten raz; Boże, abym się raz pomścił obu oczu moich nad Filistynami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'A ująwszy Samson oba słupy pośrednie, na których dom stał, wsparł się o nie, o jeden prawą ręką swoją a o drugi lewą ręką swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Zatem rzekł Samson: Niech umrze dusza moja z Filistynami; a gdy się o nie mocno oparł, upadł dom na książęta, i na wszystek lud, który w nim był, i było umarłych, które on pobił umierając, więcej niż onych, które pobił za żywota swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'A przyszedłszy bracia jego, i wszystek dom ojca jego, wzięli go, a wróciwszy się pogrzebli go między Saraa, i między Estaol, w grobie Manue, ojca jego. A on sądził Izraela przez dwadzieścia lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'A był niektóry mąż z góry Efraim, imieniem Michas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Ten rzekł do matki swojej: Tysiąc i sto srebrników, któreć było ukradziono, o któreś przeklinała, i mówiłaś, gdym i ja słyszał, oto srebro to u mnie jest, jam je wziął. I rzekł matka jego: Błogosławionyś, synu mój, od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'A tak wrócił tysiąc i sto srebrników matce swojej; i rzekła matka jego: Zaiste poświęciłam to srebro Panu z ręki mojej dla ciebie, synu mój, aby uczyniono z niego ryty i lany obraz, przetoż teraz oddawam ci je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'I wrócił ono srebro matce swojej. Tedy wziąwszy matka jego dwieście srebrników, dała je złotnikowi; i uczynił z nich obraz ryty i lany, który był w domu Michasowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'A miał ten Michas kaplicę bogów, sprawił też był Efod i Terafim, a poświęcił ręce jednego z synów swych, aby mu był za kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'W one dni nie było króla w Izraelu; każdy, co był dobrego w oczach jego, czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'I był młodzieniec z Betlehem Juda, które było w pokoleniu Juda, a ten będąc Lewitą był tam przychodniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Wyszedł tedy on mąż z miasta Betlehem Juda, aby mieszkał, gdzieby mu się trafiło; i przyszedł na górę Efraim aż do domu Michasowego, idąc drogą swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Tedy rzekł do niego Michas: Skąd idziesz? I odpowiedział mu: Jam jest Lewita z Betlehem Juda, a idę, abym mieszkał gdzieby mi się trafiło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'I rzekł mu Michas: Zostań u mnie, a bądź mi za ojca i za kapłana, a jać dam dziesięć srebrników do roku, i dwie szaty, i pożywienie twoje; i szedł za nim on Lewita.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'I upodobało się Lewicie mieszkać z mężem onym; a był przy nim on młodzieniec jako jeden z synów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'I poświęcił Michas ręce Lewity, i był mu on młodzieniec za kapłana, i mieszkał w domu Michasowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Tedy rzekł Michas: Teraz wiem, że mi będzie Pan błogosławił, gdyż mam Lewitę za kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'W one dni nie było króla w Izraelu, a tegoż czasu pokolenie Dan szukało sobie dziedzictwa do mieszkania; albowiem nie przypadło im było aż do onego dnia w pośrodku pokoleń Izraelskich dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Przetoż wyprawili synowie Dan z pokolenia swego pięciu mężów z granic swoich, mężów walecznych z Saraa i Estaol, aby przepatrzyli ziemię i wyszpiegowali ją, i rzekli do nich: Idźcież, wyszpiegujcie ziemię; i przyszli na górę Efraim aż do domu Michasowego i nocowali tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'A gdy byli blisko domu Michasowego, poznali głos młodzieńca Lewity, i zstąpiwszy tam, rzekli mu: Którz cię tu przywiódł? a co tu czynisz? i co tu masz za sprawę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'A on im odpowiedział: Tak a tak postanowił ze mną Michas, i najął mię, abym u niego był za kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'I rzekli do niego: Prosimy poradź się Boga, abyśmy wiedzieli, poszczęścili się nam ta droga nasza, którą idziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'I odpowiedział im kapłan: Idźcie w pokoju; albowiem sprawuje Pan drogę waszę, którą idziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'A tak poszedłszy onych pięć mężów, przyszli do Lais, a ujrzeli lud, który w nim był, mieszkający bezpiecznie według zwyczaju Sydończyków w próżnowaniu i w bezpieczeństwie; bo nie był, kto by ich trapił w onej ziemi, albo posiadał królestwo ich; nadto odległymi byli od Sydończyków, i żadnej sprawy z nikim nie mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Gdy się tedy wrócili do braci swych do Saraa i do Estaol, rzekli im bracia ich: Cóżeście sprawili?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'I rzekli: Wstańcie, a ciągnijmy przeciwko nim; bośmy widzieli ziemię, a oto, bardzo dobra. A wy nie dbacie? NIe leńcież się iść, a przyszedłszy osieść tę ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Gdy wnijdziecie, przyjdziecie do ludu bezpiecznego, do ziemi przestronnej; bo ją dał Bóg w ręce wasze, miejsce, kędy nie masz żadnego niedostatku wszystkich rzeczy, które są na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'I wyszło stamtąd z pokolenia Dan, z Saraa i z Estaol, sześć set mężów gotowych do boju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'A idąc położyli się obozem u Karyjatyjarym w Juda; przetoż nazwali ono miejsce obóz Danów aż do dnia dzisiejszego, a jest za Karyjatyjarym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'A ruszywszy się stamtąd na górę Efraim przyszli aż do domu Michasowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'I mówili oni pięć mężowie, którzy chodzili na szpiegi do ziemi Lais, i rzekli do braci swych: Wiecież, iż w tym domu jest Efod i Terafim, i obraz ryty i lany? przetoż teraz wiedzcie, co macie czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'A zstąpiwszy tam, przyszli do domu młodzieńca Lewity, w dom Michasów, i pozdrowili go w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Ale sześć set mężów gotowych do boju, którzy byli z synów Danowych, stali przed drzwiami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'A tak wszedłszy tam oni pięć mężów, którzy chodzili na wyszpiegowanie ziemi, wzięli obraz ryty, i Efod, i Terafim, i obraz lany; a kapłan stał przede drzwiami bramy z sześcią set mężów gotowych do boju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'A ci, którzy weszli do domu Michasowego, wzięli obraz ryty, Efod i Terafim, i obraz lany; i rzekł do nich kapłan: Cóż to czynicie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'A oni mu odpowiedzieli: Milcz, włóż rękę twą na usta twoje, a pójdź z nami, a bądź nam za ojca i za kapłana; cóżci lepiej, być kapłanem w domu męża jednego, czyli być kapłanem pokolenia i domu Izraelskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'I uradowało się serce kapłanowe, a wziąwszy Efod i Terafim, i obraz ryty, wszedł w pośrodek onego ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'A oni obróciwszy się poszli, a puścili przed sobą dziatki i bydło, i co było kosztowniejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'A gdy byli opodal od domu Michasowego, tedy mężowie, którzy mieszkali w domach bliskich domu Michasowego, zebrawszy się gonili syny Dan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'I wołali za synami Dan, którzy obejrzawszy się rzekli do Michasa: Cóż ci, żeś się tak skupił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'I odpowiedział: Bogi moje, którem sprawił, pobraliście, i kapłana, a odeszliście, i cóż więcej mieć będę? a jeszcze mówicie: Cóż ci?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Na to mu odpowiedzieli synowie Dan: Niech nie słyszymy głosu twego za sobą, by się snać nie rzucili na was mężowie rozgniewani, a straciłbyś duszę twoję i duszę domu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'I poszli synowie Dan drogą swoją; a widząc Michas, że byli możniejsi niźli on, wrócił się i szedł do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Tedy oni wziąwszy to, co był sprawił Michas, i z kapłanem, którego miał, przyszli do Lais, do ludu próżnującego i bezpiecznego, i wysiekli je ostrzem miecza, a miasto spalili ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'A nie był, kto by ich ratował; albowiem byli daleko od Sydonu, i nie mieli żadnej sprawy z nikim, a to miasto leżało w dolinie, która jest w Betrohob, które znowu pobudowawszy mieszkali w niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'I nazwali imię miasta onego Dan według imienia Dana, ojca swego, który się był urodził Izraelowi; a przedtem imię miasta onego było Lais.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'A tak postawili sobie synowie Dan obraz ryty; a Jonatan, syn Gersona Manasesowego, on i synowie jego, byli kapłanami w pokoleniu Dan aż do czasu pojmania obywateli onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Wystawili tedy sobie on obraz ryty, który był uczynił Michas, po wszystkie dni, póki był dom Boży w Sylo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'I stało się w one dni, gdy króla nie było w Izraelu, że mąż niektóry Lewita, mieszkający przy stronie góry Efraim, pojął sobie żonę założnicę z Betlehem Juda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'A bawiła się nierządem przy nim założnica jego; potem odeszła od niego do domu ojca swego, do Betlehem Juda; i była tam u niego przez cztery miesiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Wstawszy tedy mąż jej, szedł za nią, aby ją ubłagawszy zasię ją przywiódł, mając z sobą sługę swego, i parę osłów. Tedy ona wwiodła go w dom ojca swego, którego gdy ujrzał ojciec onej dziewki, radował się z przyjścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'I przyjął go wdzięcznie świekier jego, ojciec dziewki onej, a mieszkał u niego, przez trzy dni, i jedli i pili i nocowali tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'A dnia czwartego, gdy wstali bardzo rano, wstał i on, aby odszedł. Ale rzekł ojciec onej dziewki do zięcia swego: Posil serce twoje trochą chleba, a potem pójdziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Tedy siedli i jedli oboje wespół, i napili się. Zatem rzekł ojciec onej dziewki do męża jej: Zostań proszę, a przenocuj tu, i bądź dobrej myśli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'A gdy wstał on mąż, chcąc przecię iść w drogę, gwałtem przymusił go świekier jego, iż się wróciwszy został tam na noc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Wstał potem bardzo rano dnia piątego, chcąc iść; ale mówił ojciec onej dziewki: Posil proszę serce twoje; i zabawili się, aż się dzień nachylił, a jedli oba społu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Wstał tedy on mąż, aby szedł sam i założnica jego, i sługa jego, któremu rzekł świekier jego, ojciec onej dziewki: Oto się już dzień nachylił ku wieczorowi, przenocujcież tu proszę; oto schodzi dzień, przenocuje tu, a bądź dobrej myśli, a jutro rano wyprawicie się w drogę swą, i pójdziesz do przybytku twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Tedy on mąż nie chciał zostać na noc, ale wstał i odszedł, a przyszedł aż ku Jebus, (które jest Jeruzalem) mając z sobą dwóch osłów z brzemiony, i założnicę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'A gdy byli blisko Jebus, a dzień się już bardzo nachylił, tedy rzekł sługa do pana swego: Pójdź proszę, a wstąpmy do tego miasta Jebuzejczyków, i przenocujmy w niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Któremu odpowiedział pan jego: Nie wstępujmy do miasta cudzoziemców, które nie jest z synów Izraelskich, ale idźmy aż do Gabaa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Nadto rzekł do sługi swego: Pójdź, abyśmy przyszli na jedno z tych miejsc, i przenocowali albo w Gabaa albo w Rama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'A minąwszy poszli: i zaszło im słońce u Gabaa, które jest pokolenia Benjaminowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'I udali się tam, aby wszedłszy przenocowali w Gabaa; a gdy wszedł, usiadł na ulicy w mieście, przeto że nie był, kto by je przyjął w dom i przenocował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'A oto, mąż stary szedł od roboty swojej z pola w wieczór; a ten mąż był z góry Efraim, będąc przychodniem w Gabaa, ale ludzie miejsca onego byli synowie Jemini.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Ten podniósłszy oczy swe ujrzał męża onego podróżnego na ulicy miasta, i rzekł do niego starzec: Dokąd idziesz, i skądeś przyszedł?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Któremu on odpowiedział: Idziemy z Betlehem Juda aż ku stronie góry Efraimowej, skądem jest; bom chodził do Betlehem Judskiego; a teraz idę do domu Pańskiego, ale nie masz nikogo, coby mię przyjął w dom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Choć i plewy i siano mam dla osłów naszych, także chleb i wino mam dla siebie i dla służebnicy twej i dla sługi, który jest ze mną, sługą twoim; nie mam niedostatku z żadnej rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Tedy mu rzekł on mąż stary: Nie frasuj się; czegoćkolwiek nie dostanie, to ja opatrzę; tylko na ulicy nie zostawaj przez noc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Wwiódł go tedy do domu swego, i dał osłom obrok; potem umywszy nogi swoje, jedli i pili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'A gdy rozweselili serce swoje, oto, mężowie miasta tego, mężowie niepobożni, obstąpili dom, kołacąc we drzwi, i rzekli do gospodarza domu onego, do męża starego, mówiąc: Wywiedź męża, który wszedł w dom twój, abyśmy go poznali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'A wyszedłszy do nich on mąż, gospodarz domu, rzekł im: Nie tak bracia moi: nie czyńcie proszę tej złości, gdyż wszedł ten mąż do domu mego, nie czyńcież tej sprosności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Oto córka moja panna, i założnica jego, wywiodę je zaraz, że je obelżycie, a uczynicie z niemi, co się wam będzie dobrego zdało; tylko mężowi temu nie czyńcie tej zelżywości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Ale nie chcieli oni mężowie słuchać głosu jego; przetoż wziąwszy on mąż założnicę swoję, wywiódł ją do nich na dwór; i poznali ją, a czynili jej gwałt przez całą noc aż do zaranku, a potem puścili ją, gdy wschodziła zorza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'A przyszedłszy ona niewiasta na świtaniu, upadła u drzwi domu onegoż męża, gdzie był pan jej, aż się rozedniało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Potem wstawszy pan jej rano, otworzył drzwi u domu, i wyszedł, chcąc iść w drogę swoję, a oto, ona niewiasta, założnica jego, leżała u drzwi domu, a ręce jej był na progu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'I rzekł do niej: Wstań a pójdźmy; ale nic nie odpowiedziała. Wziąwszy ją tedy na osła, wstał on mąż, i szedł do miejsca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Tam przyszedłszy w dom swój, porwał miecz, a zdjąwszy założnicę swoję rozrąbał ją z kościami jej na dwanaście sztuk, i rozesłał ją po wszystkich granicach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'A ktokolwiek to widział, mówił: Nigdy się to nie stało, ani co takowego widziano od onego dnia, jako wyszli synowie Izraelscy z ziemi Egipskiej, aż do tego dnia; uważajcież to z pilnością, a radźcie i mówcie o tem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Wyszli tedy wszyscy synowie Izraelscy, a zgromadziło się wszystko pospólstwo jednomyślnie od Dan aż do Beerseba, i do ziemi Galaad do Pana do Masfy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'I stanęli przedniejsi wszystkiego ludu i wszystkie pokolenia Izraelskie w zgromadzeniu ludu Bożego, cztery kroć sto tysięcy ludu pieszego, godnego do boju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, '(I usłyszeli synowie Benjamin, iż się zebrali synowie Izraelscy w Masfa.) Rzekli tedy synowie Izraelscy: Powiedzcie, jako się stał ten zły uczynek?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'I odpowiedział on mąż Lewita, małżonek niewiasty zabitej, i rzekł: Do Gabaa, które jest w Benjamin, przyszedłem, ja i założnica moja, abym tam przenocował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'I powstali przeciwko mnie mężowie z Gabaa, a obstąpili około mnie dom w nocy, umyśliwszy mię zabić; ale założnicę moję tak gwałcili, aż umarła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Wziąłem tedy założnicę moję, i rozrąbałem ją na sztuki, i rozesłałem ją do wszystkich krain dziedzictwa Izraelskiego; albowiem się dopuścili w Izraelu haniebnego i sprosnego uczynku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Otoście wy wszyscy synowie Izraelscy; uważcież to między sobą, a radźcie o tem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'I powstał wszystek lud jednostajnie, mówiąc: Nie pójdzie nikt do namiotu swego, ani odejdzie kto do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Ale teraz to uczynimy miastu Gabaa, rzuciwszy los przeciwko niemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Weźmiemy dziesięć mężów ze sta w każdem pokoleniu Izraelskiem, a sto z tysiąca, a tysiąc z dziesięciu tysięcy, żeby dodawali żywności ludowi, który przyciągnie do Gabaa Benjamin, i pomści się nad nim wszystkiej sprosności, której się dopuścili w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'A tak zebrał się wszystek lud Izraelski przeciwko miastu, zmówiwszy się jednostajnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'I posłały pokolenia Izraelskie posły do wszystkich domów synów Benjaminowych, mówiąc: Co to za zły uczynek, który się stał między wami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Przetoż teraz wydajcie męże niepobożne, którzy są w Gabaa, abyśmy je pozabijali, a uprzątnęli złe z Izraela; ale nie chcieli synowie Benjaminowi słuchać głosu braci swych, synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Owszem zgromadzili się synowie Benjaminowi z miast swoich do Gabaa, aby walczyli przeciw synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'I naliczono synów Benjaminowych dnia onego z miast ich dwadzieścia i sześć tysięcy mężów godnych do boju, oprócz obywateli Gabaa, których naliczono siedem set mężów na wybór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Między tym wszystkim ludem było siedem set mężów na wybór, którzy nie używali ręki swej prawej, a każdy z nich ciskając z procy kamieniem, i włosa nie chybiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Mężów zasię Izraelskich naliczono, oprócz synów Benjaminowych, cztery kroć sto tysięcy mężów walecznych, i wszystko godnych do boju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Wstawszy tedy szli do domu Bożego, i radzili się Boga, a mówili synowie Izraelscy: Któż za nas pójdzie wprzód na wojnę przeciw synom Benjaminowym? I odpowiedział Pan: Juda wprzód pójdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'A tak wstawszy synowie Izraelscy rano, położyli się obozem przeciw Gabaa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'A wyszedłszy mężowie Izraelscy ku bitwie przeciw synom Benjaminowym, uszykowali się mężowie Izraelscy ku potykaniu przeciw Gabaa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Ale wyszedłszy synowie Benjaminowi z Gabaa, porazili z Izraela dnia onego dwadzieścia i dwa tysiące mężów na głowę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Potem pokrzepiwszy się mężowie ludu Izraelskiego znowu się uszykowali ku bitwie na onemże miejscu, gdzie się byli uszykowali dnia pierwszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Pierwej jednak poszli synowie Izraelscy, i płakali przed Panem aż do wieczora, i pytali się Pana, mówiąc: Izali jeszcze mamy iść walczyć przeciwko synom Benjamina, brata naszego? I rzekł Pan: Idźcie przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'I ruszyli się synowie Izraelscy przeciwko synom Benjaminowym drugiego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'A wypadłszy synowie Benjaminowi przeciwko nim z Gabaa drugiego dnia, porazili synów Izraelskich znowu osiemnaście tysięcy mężów na głowę, wszystko mężów walecznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Przetoż szli wszyscy synowie Izraelscy, i wszystek lud, a przyszli do domu Bożego, i płacząc trwali tam przed Panem, i pościli dnia onego aż do wieczora, ofiarując całopalenia, i ofiary spokojne przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'I pytali synowie Izraelscy Pana, (bo tam była skrzynia przymierza Bożego na on czas;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'A Finees, syn Eleazara, syna Aaronowego, stał przed nią na ten czas,) mówiąc: Mamyli jeszcze wynijść na wojnę przeciwko synom Benjamina, brata naszego, czyli zaniechać? I odpowiedział Pan: Idźcie; bo jutro dam je w ręce wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Tedy poczynił Izrael zasadzki przeciw Gabaa zewsząd w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'A ruszywszy się synowie Izraelscy przeciwko synom Benjaminowym dnia trzeciego, uszykowali się przeciw Gabaa, jako pierwszy i wtóry raz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Wyszli też synowie Benjaminowi przeciwko ludowi, o odsadziwszy się od miasta, poczęli bić lud i siec, jako pierwszy i wtóry raz po drogach, (z których jedna szła do Betel, a druga do Gabaa,) i po polu, a zabili około trzydziestu mężów z Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'I rzekli synowie Benjaminowi: Porażeni będą od nas jako i pierwej; lecz synowie Izraelscy mówili: Uciekajmy, a uwiedźmy je od miasta, aż na wielkie drogi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Zatem wszyscy synowie Izraelscy wstawszy z miejsca swego uszykowali się w Baaltamar; zasadzki też Izraelskie wyszły z miejsca swego, z łąk Gabaa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'A tak przeszło przez Gabaa dziesięć tysięcy mężów na wybór ze wszystkiego Izraela, i była bitwa sroga, a oni nie widzieli, że ich nieszczęście potkać miało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'I poraził Pan Benjamina przed twarzą Izraela, a zabili synowie Izraelscy z Benjamina dnia onego dwadzieścia i pięć tysięcy i sto mężów, wszystko godnych do boju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'A widząc synowie Benjaminowi, że byli porażeni, (bo mężowie Izraelscy ustępowali z placu przed Benjaminem, ufając zasadzkom, które byli uczynili przeciw Gabaa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'A ci, co byli na zasadzce, pospieszyli się, i uderzyli na Gabaa, a wpadłszy pobili ostrzem miecza wszystkie, którzy byli w mieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Albowiem znak postawiony mieli mężowie Izraelscy z onymi, co byli w zasadzce, mianowicie, że gdyby dym wielki wypuścili z miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Tedy się mężowie Izraelscy obrócili ku bitwie. Synowie zaś Benjaminowi poczęli bić i siec, i zabili z mężów Izraelskich około trzydziestu mężów; bo rzekli: Zaiste porażeni są przed nami jako i w pierwszej bitwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Ale gdy płomień i dym jako słup począł wzgórę wstępować z miasta, tedy obejrzawszy się synowie Benjaminowi nazad, uderzyli, a oto, ogień z miasta, wstępował aż ku niebu.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'A iż się mężowie Izraelscy obrócili, potrwożyli się mężowie Benjaminowi, widząc, że nieszczęście następowało na nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'I uciekli przed mężami Izraelskimi drogą ku puszczy; a wojsko doganiało ich, i ci, którzy wybieżeli z miast, bili je między sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Ogarnęli tedy Benjamina, i gonili je bez przestanku, a wparli je aż do Gabaa na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Poległo tedy z Benjamina, osiemnaście tysięcy mężów, wszystko mężów dużych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'A z tych, którzy obróciwszy się uciekali na puszczą, na skałę Remmon, łapiąc je po drogach, zabili pięć tysięcy mężów, a gonili je aż do Giedeon, gdzie zamordowali z nich dwa tysiące mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'A tak było wszystkich, którzy polegli z Benjamina dnia onego, dwadzieścia i pięć tysięcy mężów walecznych, wszystko mężów dużych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Tylko się obróciło i uciekło na puszczę, na skałę Remmon, sześć set mężów, i zostali na skale Remmon przez cztery miesiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Potem mężowie Izraelscy wróciwszy się do synów Benjaminowych, wybili je ostrzem miecza, w mieście, począwszy od ludzi aż do bydlęcia, i do wszystkiego, co znaleźli; przytem i wszystkie miasta, które pozostały, popalili ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Nadto przysięgli mężowie Izraelscy w Masfa, mówiąc: Żaden z nas nie da córki swej Benjaminczykom za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'A tak poszedł lud do domu Bożego, i trwali tam aż do wieczora przed Bogiem, a podniósłszy głos swój, płakali płaczem wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'I rzekli: O Panie, Boże Izraelski, czemuż się to stało w Izraelu, że ubyło dzisiaj z Izraela jedno pokolenie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Tedy nazajutrz wstawszy rano lud zbudowali tam ołtarz, a sprawowali całopalone i spokojne ofiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Zatem rzekli synowie Izraelscy: Któż jest, co nie przyszedł do zgromadzenia ze wszystkich pokoleń Izraelskich do Pana? (Bo się byli wielką przysięgą zawiązali przeciw temu, któryby nie przyszedł do Pana do Masfa, mówiąc: Śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'I żałowali synowie Izraelscy Benjamina, brata swego, a mówili: Wygładzone jest dziś pokolenie jedno z Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Cóż uczynimy tym, co pozostali, aby mieli żony, gdyżeśmy przysięgli przez Pana, że im nie mamy dać córek naszych za żony?)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Rzekli tedy: Jestże kto z pokoleń Izraelskich, coby nie przyszedł do Pana do Masfa? a oto, nie przyszedł był nikt do obozu z Jabes Galaad do zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Bo gdy liczono lud, tedy nikogo tam nie było z obywateli Jabes Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'I posłało tam zgromadzenie dwanaście tysięcy mężów walecznych, rozkazując im i mówiąc: Idźcie, a pobijcie obywatele Jabes Galaad ostrzem miecza, i niewiasty i dzieci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'A tak sobie postąpicie: Każdego mężczyznę, i każdą niewiastę, która męża uznała, zabijecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Naleźli tedy z obywateli Jabes Galaad cztery sta dzieweczek, panien, które nie uznały męża obcując z nim, i przywiedli je do obozu do Sylo, które było w ziemi Chananejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Potem posłało wszystko zgromadzenie, a mówiło do synów Benjaminowych, którzy byli na skale Remmon, i przyzwali ich w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Przetoż wrócił się Benjamin onego czasu, i dali im żony, które byli żywo zachowali z niewiast Jabes Galaad, ale im się ich jeszcze nie dostawało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'A lud żałował Benjamina, iż uczynił Pan przerwę w pokoleniach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Tedy rzekli starsi zgromadzenia tego: A z tymi drugimi cóż uczynimy, aby mieli żony, gdyż niewiasty wygładzone są z Benjamina?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Nadto rzekli: Dziedzictwo Benjamina pozostałym należy, aby nie zaginęło pokolenie z Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'A my nie możemy im dać żon z córek naszych, (gdyż byli przysięgli synowie Izraelscy, mówiąc: Przeklęty, kto da żonę Benjaminczykowi.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Potem rzekli: Oto święto Pańskie uroczyste bywa na każdy rok w Sylo, które jest ku północy od Betel, a na wschód słońca ku drodze, która idzie od Betel ku Sychem, a pod południa leży ku Lebnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'A tak rozkazali synom Benjaminowym, mówiąc: Idźcie, a zasadźcie się w winnicach,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'A patrzajcie, gdy córki Sylo wynijdą gromadą do tańca; tam wyszedłszy z winnic, porwij każdy z was sobie żonę z córek Sylo, a potem idźcie do ziemi Benjamin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'A gdy przyjdą ojcowie ich, albo bracia ich skarżyć się przed nami, tedy im rzeczemy: Zmiłujcie się nad nimi dla nas; bośmy nie wzięli dla każdego z nich żony na wojnie, a wyście im ich też nie dali; przetoż nie jesteście winni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Tedy uczynili tak synowie Benjamin, i nabrali żon według liczby swojej z onych co tańcowały, które porwawszy odeszli, i wrócili się do dziedzictwa swego, a pobudowawszy miasta mieszkali w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'A tak rozeszli się stamtąd synowie Izraelscy onego czasu, każdy do pokolenia swego i do domu swego, a szedł stamtąd każdy do dziedzictwa swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'W one dni nie było króla w Izraelu; każdy, co mu się dobrego zdało to czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'I stało się za onych czasów, kiedy sędziowie sądzili, był głód w ziemi; i poszedł niektóry mąż z Betlehem Juda na mieszkanie do ziemi Moabskiej z żoną swoją i z dwoma synami swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'A imię męża onego było Elimelech, imię też żony jego Noemi, także imiona dwóch synów jego Mahalon i Chelijon, a ci byli Efratejczykami z Betlehem Juda, którzy zaszedłszy do krainy Moabskiej, mieszkali tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Potem umarł Elimelech, mąż Noemi, a ona pozostała z dwoma synami swoimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'I pojęli sobie żony Moabskie; imię jednej Orfa, a drugiej imię Rut; i mieszkali tam około dziesięciu lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Umarli potem i oni oba, Mahalon i Chelijon; i tak ona niewiasta osierociała po obu synach swoich i po mężu swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'A wezbrawszy się z synowemi swemi wróciła się z ziemi Moabskiej; bo słyszała w krainie Moabskiej, że był nawiedził Pan lud swój, i dał im chleb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Tedy wyszła z miejsca, na którem była z onemi dwiema synowemi swemi, a udały się w drogę, aby się wróciły do ziemi Juda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'Zatem rzekła Noemi do dwóch synowych swych: Idźcież, wróćcie się każda do domu matki twojej; niechaj uczyni Pan z wami miłosierdzie, jakoście uczyniły z umarłymi synami moimi i ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Niech wam da Pan znaleźć odpocznienie, każdej w domu męża swego; i pocałowała je, a one podniósłszy głos swój, płakały,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'I mówiły do niej: Raczej się z tobą wrócimy do ludu twojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'A Noemi rzekła: Wróćcież się córki moje; przeczżebyście ze mną iść miały? Azaż ja jeszcze mogę mieć syny, którzyby byli mężami waszymi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Wróćcież się córki moje, a idźcie, bom się już zstarzała, a nie mogę iść za mąż. Choćbym też rzekła, jeszcze mam nadzieję, albo choćbym też dobrze tej nocy była za mężem choćbym też nawet i porodziła syny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'Izali wy ich czekać będziecie, ażby dorośli? zaż się dla tego zatrzymacie, abyście nie szły za mąż? Nie tak córki moje; bo żałość moja większa jest niźli wasza, gdyż się obróciła przeciwko mnie ręka Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'Ale one podniósłszy głos swój, znowu płakały. I pocałowała Orfa świekrę swoję; a Ruta została przy niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Do której Noemi rzekła: Oto się wróciła powinna twoja do ludu swego, i do bogów swoich, wróćże się i ty za powinną swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Na co jej odpowiedziała Ruta: Nie wiedź mię do tego, abym cię opuścić i od ciebie odejść miała; owszem gdziekolwiek pójdziesz, z tobą pójdę, a gdziekolwiek mieszkać będziesz, z tobą mieszkać będę; lud twój lud mój, a Bóg twój Bóg mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Gdzie umrzesz, tam i ja umrę, i tam pogrzebiona będę. To mi niech uczyni Pan, i to niech przepuści na mię, że tylko śmierć rozłączy mię z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'A tak ona widząc, że się na to uparła, aby z nią szła, przestała jej odradzać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'I szły obie pospołu, aż przyszły do Betlehem. I stało się, gdy przyszły do Betlehem, wzruszyło się wszystko miasto dla nich, mówiąc: Izaż nie ta jest Noemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Ale ona mówiła do nich: Nie nazywajcie mię Noemi, ale mię zowcie Mara; albowiem mię gorzkościę wielką Wszechmogący napełnił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Wyszłam stąd obfitą a próżną mię przywrócił Pan. Przeczże mię tedy zowiecie Noemi, gdyż mię Pan utrapił, a Wszechmogący złe na mię dopuścił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'A tak wróciła się Noemi i Rut Moabitka, synowa jej, z nią; wróciła się z krainy Moabskiej, i przyszły do Betlehem na początku żniwa jęczmiennego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'A Noemi miała powinowatego po mężu swym, człowieka możnego z domu Elimelechowego, którego zwano Booz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'I rzekła Ruta Moabitka do Noemi: Pójdę proszę na pole, a niech zbieram kłosy za tym, przed którego oczyma łaskę znajdę; a ona rzekła: Idź, córko moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Szła tedy, a przyszedłszy zbierała na polu za żeńcami; i trafiło się, że przyszła na dział pola Boozowego, który był z domu Elimelechowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'A wtem przyszedł Booz z Betlehem, i rzekł do żeńców: Pan z wami. A oni mu odpowiedzieli: Niechżeć Pan błogosławi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Rzekł tedy Booz do sługi swego, który był przystawem nad żeńcami: Czyjaż to dzieweczka?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'I odpowiedział mu sługa on, który był przystawem nad żeńcami, i rzekł: Ta dzieweczka jest Moabitka, która przyszła z Noemi z ziemi Moabskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'I rzekła mi: Niech proszę zbieram i zgromadzam kłosy między snopami za żeńcami; a przyszedłszy bawi się tu od samego poranku aż dotąd, a bardzo mało w domu siedzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Tedy rzekł Booz do Rut: Słuchaj mię córko moja; nie chodź zbierać kłosów na insze pole i nie odchodź stąd, ale się tu trzymaj dziewek moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Pilnuj tego pola, na którem żąć będą, a chodź za nimi; bom rozkazał sługom moim, żeby się ciebie żaden nie tykał; a jeźli upragniesz, idź do naczynia, a napij się z tego, co czerpią słudzy moi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Tedy ona upadłszy na oblicze swoje, ukłoniwszy się aż do ziemi rzekła do niego: Skądżem znalazła łaskę w oczach twoich, iż mię znasz, gdyżem jest cudzoziemka?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'I odpowiedział Booz, a rzekł jej: Powiedziano mi zapewne wszystko, coś uczyniła świekrze twojej po śmierci męża twego, a jakoś opuściwszy ojca twego i matkę twoję, i ziemię, w którejś się urodziła, przyszła do ludu, któregoś nie znała przedtem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Niechżeć odda Pan uczynek twój, i niech będzie zapłata twoja doskonała od Pana, Boga Izraelskiego, gdyżeś przyszła, abyś nadzieję miała pod skrzydłami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'A ona rzekła: Znalazłam łaskę w oczach twoich, panie mój, gdyżeś mię pocieszył, a mówiłeś do serca służebnicy twojej, chociam ja nie jest, jako jedna z służebnic twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'I rzekł jej Booz: Gdy będzie czas jedzenia, przychodź tu, a jedz chleb, omoczywszy sztuczkę twoję w occie. I usiadła przy żeńcach, i podał jej prażma, które jadła aż do sytości, i jeszcze jej zbyło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'Potem wstała, aby zbierała; a Booz rozkazał sługom swoim mówiąc: Niech i między snopami zbiera, a nie brońcie jej tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Owszem umyślnie upuszczajcie jej z snopów, a zostawiajcie, aby zbierała, a nie fukajcie na nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'A tak zbierała na onem polu aż do wieczora; i wymłóciła to, co zebrała, i miała jakoby z efę jęczmienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'A wziąwszy to, szła do miasta, i oglądała świekra jej to, co nazbierała; a wyjąwszy dała jej i to, co jej zostało, gdy się najadła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'I rzekła do niej świekra jej: Kędyżeś dziś zbierała, a gdzieś robiła? niechajże ten, który na cię miał baczenie, błogosławionym będzie. I oznajmiła świekrze swej, u kogo robiła, mówiąc: Imię męża, u któregom dziś robiła, Booz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'Potem rzekła Noemi do synowy swojej: Niech będzie błogosławionym od Pana, który nie zawściągnął miłosierdzia swego od żywych i od umarłych. Nadto jeszcze rzekła Noemi: Ten mąż jest powinowatym naszym, i z pokrewnych naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'Rzekła jej też Rut Moabitka: Nadto mi jeszcze mówił on mąż: Trzymaj się czeladzi mojej, póki nie pożną wszystkiego zboża mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Tedy rzekła Noemi do Ruty, synowy swej: Dobrze, córko moja, iż będziesz chodziła z dziewkami jego, żebyć kto przeciwnym nie był na polu innem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Przetoż się trzymała służebnic Boozowych, i zbierała kłosy, póki się nie skończyło żniwo jęczmienne, i żniwo pszeniczne. Potem mieszkała u świekry swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Potem rzekła do niej Noemi, świekra jej: Córko moja, azażemci nie powinna szukać odpocznienia, żebyś się dobrze miała?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'A teraz azaż Booz nie jest powinowatym naszym, z któregoś ty służebnicami była? Oto on będzie wiał jęczmień na bojewisku tej nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Przetoż umywszy się, namaż się olejkami; weźmij też szaty twoje na się, a idź na bojewisko, a nie daj się widzieć mężowi onemu, ażby się najadł i napił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'A gdy on spać pójdzie, upatrzże miejsce, na którem się układzie, a przyszedłszy odkryjesz płaszcz z nóg jego, a tam się układziesz, a on tobie oznajmi, co będziesz miała czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'I rzekła do niej Rut: Cokolwiek mi każesz, uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'A tak szła na one bojewisko, i uczyniła to, co jej rozkazała świekra jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'A gdy się najadł Booz i napił, i rozweseliło się serce jego, poszedł a układł się przy stogu; przyszła też i ona po cichu, a odkrywszy płaszcz z nóg jego, układła się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'A gdy było o północy, uląkł się on mąż, a obróciwszy się, ujrzał, a oto,niewiasta leży u nóg jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'I rzekł: Któżeś ty? I odpowiedziała: Jam jest Rut, służebnica twoja; rozciągnijże płaszcz twój na służebnicę twoję, boś mi pokrewny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'A on rzekł: Błogosławionaś ty od Pana, córko moja; większąś pobożność po sobie pokazała teraz niż pierwej, żeś nie poszła za młodzieńcami tak ubogimi jako i bogatymi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Przetoż teraz, córko moja, nie bój się; bo wszystko, cokolwiek rzeczesz, uczynię, gdyż wie całe miasto ludu mego, żeś ty niewiasta cnotliwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'A teraz prawdać to, żem ja jest pokrewny twój, wszakże jeszcze jest pokrewny bliższy nad mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Zostańże tu tej nocy. A gdy będzie rano, jeźli cię będzie chciał pojąć prawem bliskości, dobrze, niech pojmie; jeźli cię nie będzie chciał pojąć, ja cię pojmę prawem bliskości; żywie Pan! Śpijże tu aż do poranku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'A tak spała u nóg jego aż do poranku, a wstała przedtem niż mógł rozeznać jeden drugiego; bo rzekł Booz: Niech nikt nie wie, że przyszła ta niewiasta na bojewisko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'Nadto rzekł: Daj płachtę, którą masz na sobie, a trzymaj ją; a gdy ją trzymała, namierzył jej sześć miarek jęczmienia, i założył na nię, i weszła do miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'A przyszła do świekry swej, która jej spytała: Któżeś ty córko moja? A Rut jej powiedziała wszystko, co jej uczynił on mąż,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'I rzekła: Oto sześć miarek tego jęczmienia dał mi; bo rzekł do mnie: Nie wrócisz się próżno do świekry twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'I rzekła Noemi: Potrwajże, córko moja, aż się dowiesz, jako padnie ta rzecz; boć nie zaniecha ten mąż, aż tę rzecz dziś skończy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Potem Booz szedł do bramy, i usiadł tam; a oto, pokrewny on szedł mimo, o którym powiedział był Booz; i rzekł mu: Pójdź sam a siądź tu, ty a ty; a on przyszedłszy siadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'Wziąwszy tedy dziesięć mężów starszych miasta onego, mówił do nich: Siądźcież też tu; i usiedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Zatem rzekł onemu powinowatemu: Dział roli, który był brata naszego Elimelecha, sprzedała Noemi, która się wróciła z ziemi Moabskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'I zdało mi się to odnieść do uszu twoich, mówiąc: Otrzymaj tę rolę przed tymi, którzy tu siedzą, i przed starszymi ludu mego; a chceszli ją odkupić, odkup; a jeźliż nie odkupisz, powiedz mi; bo wiem, że nad cię niemasz bliższego do wykupienia, a jam po tobie. Tedy on rzekł: Ja odkupię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Nadto rzekł Booz: Dnia, którego otrzymasz rolę z rąk Noemi, tedy też i Rutę Moabitkę, żonę zmarłego, pojmiesz, abyś wzbudził imię zmarłego w dziedzictwie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'Odpowiedział powinowaty: Nie mogę odkupić, bym snać nie stracił dziedzictwa mego. Odkupże ty sobie bliskość moję, gdyż ja nie mogę odkupić jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, '(A był to starodawny zwyczaj w Izraelu przy wykupie, i przy zamianie, aby warowniejsza była każda sprawa, tedy zzuwał jeden z nich trzewik swój, i dawał go bliźniemu swojemu; a toć było na świadectwo ustępowania dóbr w Izraelu.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Tedy rzekł on powinowaty do Booza: Otrzymajże ty; i zzuł trzewik swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Zatem rzekł Booz do onych starszych, i do wszystkiego ludu: Świadkami dziś jesteście wy, żem to wszystko otrzymał, co było Elimelechowe, i to wszystko, co było Chelijonowe, i Mahalonowe, z rąk Noemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Do tego Rutę Moabitkę, żonę Machalonowę, wziąłem sobie za żonę, abym wzbudził imię zmarłego w dziedzictwie jego, iżby nie zginęło imię onego zmarłego między bracią jego, i z bramy miejsca jego; tego wyście dzisiaj świadkami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'I rzekł wszystek lud, który był w bramie miasta, i starsi: Jesteśmy świadkami; niech ci da Pan, aby niewiasta, która wchodzi w dom twój, była jako Rachel i jako Lija, które obie zbudowały dom Izraelski. Poczynajże sobie mężnie w Efracie, zjednaj sobie imię w Betlehemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'Niechajże dom twój będzie jako dom Faresa, (którego porodziła Tamar Judzie,) z nasienia tego, któreć da Pan z tej to białej głowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'A tak pojął sobie Booz Rutę, i była mu za żonę; a gdy wszedł do niej, tedy jej dał Pan, że poczęła, i porodziła syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'I rzekły niewiasty do Noemi: Błogosławiony Pan, który cię dziś nie chciał mieć bez powinowatego, aby zostało imię jego w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'Tenci ucieszy duszę twoję, i będzie cię żywił w starości twojej; albowiem synowa twoja, która cię miłuje, porodziła go, którać daleko jest lepsza, niżeli siedm synów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'A tak wziąwszy Noemi dzieciątko, położyła je na łonie swojem, a była mu za piastunkę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'I dały mu sąsiady imię, mówiąc: Narodził się syn Noemi, i nazwały imię jego Obed; tenci jest ojciec Isajego ojca Dawidowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'A teć są rodzaje Faresowe: Fares spłodził Hesrona;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'A Hesron spłodził Rama, a Ram spłodził Aminadaba;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'A Aminadab spłodził Nahasona, a Nahason spłodził Salmona;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'A Salmon spłodził Booza, a Booz spłodził Obeda;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'A Obed spłodził Isajego, a Isaj spłodził Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Był niektóry mąż z Ramataim Sofim, z góry Efraim, któremu było imię Elkana, syn Jerohama, syna Elihu, syna Tuhu, syna Suf, Efratejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'A ten miał dwie żony, imię jednaj Anna, a imię drugiej Fenenna; i miała Fenenna dziatki, ale Anna nie miała dziatek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'I chadzał on mąż z miasta swego na każdy rok, aby chwałę dawał i ofiarował Panu zastępów w Sylo, gdzie byli dwaj synowie Heli, Ofni i Finees, kapłani Pańscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'A gdy przyszedł dzień, którego sprawował ofiary Elkana, dał Fenennie, żonie swej, i wszystkim synom jej, i córkom jej, cząstki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Ale Annie dał jednę część wyborną; bo Annę miłował, chociaż był Pan żywot jej zamknął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'I draźniła ją bardzo przeciwnica jej, aby ją tylko rozgniewała, dla tego, iż zamknął był Pan żywot jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'To gdy czynił Elkana na każdy rok, a Anna też chodziła do domu Pańskiego, tak ją draźniła przeciwnica,że płakiwała i nie jadała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'Rzekł jej tedy Elkana, mąż jej: Anno, czemu płaczesz i czemu nie jesz? a przecz się tak trapi serce twe? izalim ja tobie nie jest lepszy niż dziesięć synów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'Wstała tedy Anna, gdy się najedli i napili w Sylo; a Heli kapłan siedział na stołku u podwoja kościoła Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'A ona będąc w gorzkości serca, modliła się Panu, i wielce płakała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'I uczyniła ślub, mówiąc: Panie zastępów, jeźliż wejrzawszy wejrzysz na utrapienie służebnicy twojej, i wspomnisz na mię, a nie zabaczysz służebnicy twojej, i dasz służebnicy twojej potomstwo męskiej płci, tedy je dam Panu po wszystkie dni żywota jego, a brzytwa nie postoi na głowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'I stało się, gdy przedłużała modlitwy przed Panem, że Heli przypatrował się ustom jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Ale Anna mówiła w sercu swem, tylko wargi jej ruchały się, ale głosu jej słychać nie było; i miał ją Heli za pijaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'Przetoż rzekł do niej Heli: Długoż będziesz pijaną? wytrzeźwij się z wina twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Ale odpowiedziała Anna i rzekła: Nie tak, panie mój, niewiasta utrapionego ducha jestem, anim wina ani napoju mocnego nie piła, alem wylała duszę moję przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Nie rozumiejże o służebnicy twojej, jako o niewieście niepobożnej, gdyż z wielkiego myślenia i frasunku mego mówiłam aż dotąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Tedy odpowiedział Heli, i rzekł: Idźże w pokoju, a Bóg Izraelski niech ci da prośbę twoję, którejś żądała od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'I rzekła: Niech znajdzie służebnica twoja łaskę przed oczyma twemi; i odeszła niewiasta w drogę swą, i jadła, a twarz jej nie była więcej smętna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'I wstali bardzo rano, a pokłoniwszy się przed Panem, wrócili się, i przyszli do domu swego do Ramata. Tedy poznał Elkana Annę, żonę swą, a wspomniał na nię Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'I stało się po wypełnieniu dni, jako poczęła Anna, że porodziła syna, i nazwała imię jego Samuel; bo rzekła: U Panam go uprosiła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'Potem szedł on mąż Elkana, i wszystek dom jego, aby oddał Panu ofiarę uroczystą, i ślub swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'Ale Anna nie szła; bo mówiła mężowi swemu: Nie pójdę, aż zostawię dzieciątko, potem odwiodę je, że się ukaże przed Panem, i zostanie tam zawsze,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'I rzekł jej Elkana, mąż jej: Uczyń co jest dobrego w oczach twoich, zostań, aż go zostawisz; tylko niech utwierdzi Pan słowo swoje. Została tedy niewiasta, i karmiła piersiami syna swego, aż go zostawiła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'A gdy go zostawiła, przywiodła go z sobą ze trzema cielcami, i z jednem efa mąki, i z łagwią wina, i przywiodła go do domu Pańskiego w Sylo; a dziecię było małe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'I zabiwszy cielca, przywiedli dziecię do Heli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'A ona rzekła: Słuchaj, panie mój! żywie dusza twoja, panie mój: Jam jest ona niewiasta, któram tu stała przy tobie, modląc się Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Prosiłam o to dzieciątko, i dał mi Pan prośbę moję, którejm żądała od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Przetoż je też ja oddawam Panu; na wszystkie dni, których będzie żyło, jest oddane Panu. I pokłonili się tam Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'Tedy się modliła Anna, i rzekła: Rozweseliło się serce moje w Panu, wywyższon jest róg mój w Panu, rozszerzyły się usta moje przeciw nieprzyjaciołom moim; albowiemem się rozradowała w zbawieniu twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Niemaszci świętego jako Pan; bo niemasz innego oprócz ciebie, i niemasz tak mocnego, jak Bóg nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Niemówcież napotem słów pysznych, a niech nie wychodzą słowa harde z ust waszych; albowiem Bóg jest umiejętności Panem, a nadawają się sprawy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Łuk i mocarze pokruszeni są, a mdli przepasani są mocą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Którzy byli nasyceni, najmują się za chleb, a głodni przestali łaknąć; tak iż niepłodna siedmioro porodziła, a która rodziła wiele dziatek, zemdlała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Pan zabija i ożywia, wwodzi do grobu i wywodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Pan ubogiego czyni i zbogaca, uniża i wywyższa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'Wzbudza z prochu ubogiego, a z gnoju podnosi żebraka, aby je posadził z książęty, a dał im stolicę chwalebną osiadać; albowiem Pańskie są grunty ziemi, a na nich założył świat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'Nóg świętych swoich ochrania, a niepobożni w ciemnościach zamilkną; bo nie w sile swojej będzie się mąż zmacniał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Pan pokruszy przeciwniki swoje, a zagrzmi na nie z nieba; Pan będzie sądził granice ziemi, a da moc królowi swemu, i wywyższy róg pomazańca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'A tak odszedł Elkana do Ramaty do domu swego, a dziecię służyło Panu przed Heli kapłanem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Ale synowie Heli byli synowie bezbożni, a nie znali Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'Albowiem obyczaj kapłanów ten był około ludu: ktokolwiek sprawował ofiary, przychodził sługa kapłański, gdy warzono mięso, mając widełki o trzech zębach w ręce swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'I wrażał je w statek, albo w kocieł, albo w panew, albo w garniec, a coklowiek wyjął widełkami, to sobie brał kapłan. Tak czynili wszystkim Izraelczykom, którzy tam do Sylo przychodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Także pierwej niż zapalono tłustość, tedy przychodził sługa kapłański, a mówił do człowieka ofiarującego: Oddaj mięso, abym je upiekł kapłanowi; albowiem nie weźmie od ciebie mięsa warzonego, jedno surowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'A jeźliż mu odpowiedział on człowiek: Niech się pierwej spali tłustość, potem sobie weźmiesz, czego będzie żądała dusza twoje, tedy on mówił: Nic z tego; teraz daj! a nie daszli, wezmę gwałtem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'I był to grzech onych sług bardzo wielki przed Panem; bo się odtrącali ludzie od ofiar Pańskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Ale Samuel służył przed Panem, ubrane chłopiątko w efod lniany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'A matka jego uczyniwszy mu sukienkę małą, przynaszała mu co rok, gdy chadzała z mężem swym sprawować ofiarę uroczystą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'I błogosławił Heli Elkanie, i żonie jego, mówiąc: Niech ci da Pan potomstwo z tej niewiasty za oddanego, którego wyprosiła u Pana. I poszli na miejsca swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'Tedy nawiedził Pan Annę, która poczęła i porodziła trzech synów, i dwie córek; a pacholę Samuel urósł przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Ale Heli zstarzał się był bardzo, i słyszał wszystko, co czynili synowie jego całemu Izraelowi, i jako sypiali z niewiastami, które się schadzały przede drzwi namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'I rzekł do nich: Przeczże takie rzeczy czynicie? Cóż ja słyszę o waszych złych sprawach od wszystkiego ludu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Nie tak synowie moi; bo nie dobra sława, którą ja słyszę, że przywodzicie ku przestępstwu lud Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Gdy kto zgrzeszy przeciw człowiekowi, sądzić go będzie sędzia, ale jeźli przeciw Panu kto zgrzeszy, któż się za nim ujmie? Lecz nie usłuchali głosu ojca swego; bo je chciał Pan pobić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'Ale pacholę Samuel postępował a rósł, i podobał się tak Panu jako i ludziom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Potem przyszedł mąż Boży do Heli, i rzekł mu: Tak mówi Pan: Azalim się nie jawnie objawił domowi ojca twego, gdy byli w Egipcie w domu Faraonowym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'I obrałem go sobie ze wszystkich pokoleń Izraelskich za kapłana, aby ofiarował na ołtarzu moim, a kadził rzeczami wonnemi, i nosił efod przedemną, i dałem domowi ojca twego wszystkie ofiary palone od synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Przeczżeście podeptali ofiarę moję, i śniedną ofiarę moję, którąm rozkazał sprawować w przybytku? i więcejś uczcił syny swoje nad mię, abyście się utuczyli z pierwocin wszystkich ofiar śniednych Izraela, ludu mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Prztoż mówi Pan, Bóg Izraelski: Rzekłem wprawdzie: Dom twój i dom ojca twego będzie służył przedemną aż na wieki; ale teraz mówi Pan: Nie będzieć to, gdyż ja te, którzy nie czczą, czcić będę, a którzy mną gardzą, będą wzgardzeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Oto, dni przychodzą, a odetnę ramię twe, i ramię domu ojca twego, aby nie było starca w domu twoim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'I oglądasz wielki ucisk przybytku Pańskiego, miasto szczęścia, które Pan dawał Izraelowi, i nie będzie starca w domu twoim po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Wszakże męża nie wytracę z ciebie do końca od ołtarza mego, abym utrapił oczy twe, a boleścią ścisnął duszę twoję; a wszystko mnóstwo domu twego pomrze, dorosłszy lat męskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'A toć będzie na znak, co przyjdzie na dwóch synów twoich, Ofni i Fineesa; dnia jednego pomrą ci oba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'I wzbudzę sobie kapłana wiernego, który według serca mego, i według myśli mojej czynić będzie, i zbuduję mu dom trwały, a będzie służył przed pomazańcem moim po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'I stanie się, ktokolwiek pozostanie z domu twego, przyjdzie, aby mu się ukłonił za pieniądz srebrny i za sztukę chleba, mówiąc: Przypuść mię proszę do jednej cząstki kapłańskiej, aby jadł sztuczkę chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'A pacholę Samuel służył Panu przed Heli, a słowo Pańskie było drogie w one dni, bo nie bywało widzenia jawnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'I stało się dnia onego, gdy Heli leżał na miejscu swojem, (a oczy jego już się były poczęły zaciemniać, i nie mógł dojrzeć.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'A lampa Boża jeszcze nie była zagaszona, Samuel też spał w kościele Pańskim, gdzie była skrzynia Boża,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'Że zawołał Pan na Samuela, a on się ozwał: Owom ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'I przybieżał do Heliego i rzekł: Owom ja, gdyżeś mię wołał. A on rzekł: Nie wołałem, wróć się, śpij; i poszedł a spał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'Powtóre Pan jeszcze zawołał Samuela; i wstał Samuel, a poszedł do Heliego, i rzekł: Owom ja, gdyżeś mię wołał; któremu on rzekł: nie wołałem, synu mój, wróć się a śpij.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'A Samuel jeszcze nie znał Pana, i jeszcze mu nie było objawione słowo Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'Nadto jeszcze Pan zawołał Samuela po trzecie; a on wstawszy szedł do Heliego i rzekł: Owom ja, gdyżeś mię wołał. Tedy zrozumiał Heli, że Pan wołał pacholęcia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'I rzekł Heli do Samuela: Idź, śpij, a jeźli cię kto zawoła, rzeczesz: Mów Panie, bo słyszy sługa twój. A tak Samuel szedł i spał na miejscu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'Potem przyszedł Pan, i stanął a zawołał jako i pierwszy i drugi raz: Samuelu, Samuelu! I rzekł Samuel: Mów Panie, bo sługa twój słucha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'Tedy rzekł Pan do Samuela: Oto, Ja uczynię rzecz w Izraelu, którą ktokolwiek usłyszy, zabrzmi mu w obu uszach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'Dnia onego wzbudzę przeciw Heliemu wszystko, com mówił przeciwko domowi jego; pocznę i dokonam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'I okażę mu, iż Ja sądzę dom jego aż na wieki dla nieprawości, o której wiedział; bo wiedząc, że na się przekleństwo przywodzili synowie jego, wszakże nie bronił im tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'A przetoż przysiągłem domowi Heli, że nie będzie oczyszczona nieprawość domu Heliego żadną ofiarą, ani ofiarą śniedną, aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'I spał Samuel aż do poranku, i otworzył drzwi domu Pańskiego. A Samuel bał się oznajmić widzenia tego Heliemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Tedy zawołał Heli Samuela, i rzekł: Samuelu, synu mój; który odpowiedział: Otom ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'I rzekł: Cóż to za słowa, któreć Pan powiedział? proszę nie taj przedemną; to a toć Bóg niechaj uczyni, jeźliże co zataisz przedemną ze wszystkich słów, które mówił do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'I oznajmił mu Samuel wszystkie słowa, a nie zataił nic przed nim. A on rzekł: Pan jest; co dobrego w oczach jego, niech czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'I rósł Samuel, a Pan był z nim, i nie dopuścił upaść żadnemu ze wszystkich sług jego na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'Poznał tedy wszystek Izrael od Dan aż do Beerseba, iż Samuel był wiernym prorokiem Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'Bo i napotem ukazywał się Pan Samuelowi w Sylo, tak jako mu się przedtem objawił Pan w Sylo przez słowo swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'I stało się według mowy Samuelowej wszystkiemu Izraelowi. Bo gdy wyciągnął Izrael przeciw Filistynom na wojnę, a położył się obozem u Ebenezer, Filistynowie zaś położyli się obozem w Afeku;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'I gdy się uszykowali Filistynowie przeciwko Izraelowi, a stoczyła się bitwa: tedy porażony jest Izrael od Filistynów, a pobito ich w onej bitwie na polu około czterech tysięcy mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'I wrócił się lud do obozu. I rzekli starsi Izraelscy: Przeczże nas dziś poraził Pan przed Filistynami? weźmijmyż do siebie z Sylo skrzynię przymierza Pańskiego, a niech przyjdzie między nas, a wybawi nas z rąk nieprzyjaciół naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'Przetoż posłał lud do Sylo, i wzięli stamtąd skrzynię przymierza Pana zastępów, siedzącego na Cherubinach; byli też tam dwaj synowie Heli z skrzynią przymierza Pańskiego, Ofni i Finees.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'A gdy przyszła skrzynia przymierza Pańskiego do obozu, zakrzyknął wszystek Izrael głosem wielkim, tak iż ziemia zabrzmiała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'A usłyszawszy Filistynowie głos onego krzyku, rzekli: Cóż to za głos tak wielkiego wykrzykania w obozie Hebrejskim? I poznali, że skrzynia Pańska przyszła do obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'Przetoż zlękli się Filistynowie, gdyż mówiono: Przyszedł Bóg do obozu ich, i rzekli: Biada nam! bo nie było nic takowego przedtem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Biadaż nam! któż nas wybawi z rąk tych Bogów mocnych? cić to bogowie, którzy porazili Egipt wszelką plagą na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Zmacniajcież się, a bądźcie mężami, o Filistynowie! byście snać nie służyli Hebrejczykom, jako oni wam służyli. Bądźcież tedy mężami, a potykajcie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'Zwiedli tedy bitwę Filistynowie, i porażony jest Izrael, a uciekał każdy do namiotu swego; i stała się porażka bardzo wielka, tak iż poległo z Izraela trzydzieści tysięcy piechoty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'Tamże skrzynia Boża wzięta jest, i dwaj synowie Heli polegli, Ofni i Finees.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'I bieżał niektóry z synów Benjaminowych z bitwy, a przyszedł do Sylo tegoż dnia, mając szaty rozdarte, a proch na głowie swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'A gdy przyszedł, oto, Heli siedział na stołku przy drodze wyglądając, bo się serce jego lękało o skrzynię Bożą; a przyszedłszy on mąż, opowiedzał miastu, i krzyczało wszysytko miasto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'A usłyszawszy Heli głos krzyku onego, rzekł: Cóż to za głos rozruchu tego? lecz on mąż spiesząc się, przyszedł, aby to oznajmił Heliemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'A Heli już miał dziewiędziesiąt i ośm lat, a oczy jego już się były zaćmiły, że nie mógł dojrzeć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'Tedy rzekł on mąż do Heliego: Ja idę z bitwy, jam zaiste z bitwy dziś uciekł. Do którego on rzekł: Cóż się tam stało, synu mój?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'I odpowiedzał on poseł, i rzekł: Uciekł Izrael przed Filistynami i stała się wielka porażka ludu; tamże i dwaj synowie twoi legli, Ofni i Finees, i skrzynia Boża wzięta jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'A gdy wspomniał skrzynię Bożą, spadł Heli z stołka na wznak u bramy, a złamawszy sobie szyję umarł; albowiem był człowiek stary i ociężały. A on sądził Izraela przez czterdzieści lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Synowa też jego, żona Fineesowa, będąc brzemienną i bliską porodzenia, gdy usłyszała oną nowinę, iż wzięta jest skrzynia Boża, i że umarł świekier jej, i mąż jej, tedy się nachyliła, i porodziła; bo przypadły na nię bole jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'A gdy umierała, rzekły niewiasty, które były przy niej: Nie bój się, albowiemeś syna porodziła; ale ona nic nie odpowiedziała, ani tego przypuściła do serca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'I nazwała dzieciątko Ichabod, mówiąc: Przeprowadziła się sława od Izraela, iż wzięto skrzynię Bożą, a iż umarł świekier jej, i mąż jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'Prztoż rzekła: Przeprowadziła się sława od Izraela; bo wzięto skrzynię Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Tedy Filistynowie wzięli skrzynię Bożą, i zanieśli ją z Ebenezer do Azotu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'Wziąwszy tedy Filistynowie onę skrzynię Bożą, wprowadzili ją do domu Dagonowego, i postawili ją podle Dagona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'A gdy rano wstali Azotczanie nazajutrz, oto, Dagon leżał twarzą swoją na ziemi przed skrzynią Pańską; i ponieśli Dagona, i postawili go na miejscu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'A gdy zaś wstali rano nazajutrz, oto, Dagon leżał twarzą swoją na ziemi przed skrzynią Pańską; a łeb Dagonowy i obie dłonie rąk jego ułamane były na progu, tylko sam pień Dagonowy został podle niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Przetoż nie wstępują kapłani Dagonowi, i wszyscy, którzy wchodzą do domu Dagonowego, na próg Dagonowy w Azocie, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Tedy była ciężka ręka Pańska nad Azotczany, a gubiła je; bo je zarażała wrzodami na zadnicach, w Azocie i w granicach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'A widząc mężowie z Azotu, co się działo, rzekli: Niechaj nie zostawa skrzynia Boga Izraelskiego z nami; albowiem sroga jest ręka jego przeciwko nam, i przeciwko Dagonowi, bogu naszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'A tak obesłali i zebrali wszystkie książęta Filistyńskie do siebie, i mówili: Cóż uczynimy z skrzynią Boga Izraelskiego? I odpowiedzieli: Do Gad niech będzie doprowadzona skrzynia Boga Izraelskiego; i odprowadzono tam skrzynię Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'A gdy ją odprowadzili, powstała ręka Pańska przeciw miastu trpieniem bardzo wielkiem, i zarażała męże miasta od małego aż do wielkiego, i naczyniło się im wrzodów na skrytych miejscach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Odesłali tedy skrzynię Bożą do Akkaronu; a gdy przyszła skrzynia Boża do Akkaronu, krzyczeli Akkarończycy, mówiąc: Przyprowadzono do nas skrzynię Boga Izraelskiego, aby nas wymordowano z ludem naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Przetoż posławszy zgromadzili wszystkie książęta Filistyńskie, i rzekli: Odeślijcie skrzynię Boga Izraelskiego, a niech się wróci na miejsce swoje, i niech nas nie zabija i ludu naszego; bo był strach śmierci po wszystkiem mieście, a była tam bardzo ciężka ręka Boża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'A mężowie którzy nie pomarli, zarażeni byli wrzodami na zadnicy, tak, iż wstępował krzyk miasta do nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'I była skrzynia Pańska w ziemi Filistyńskiej przez siedm miesięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'Tedy przyzwawszy Filistynowie kapłanów i wieszczków, rzekli: Cóż uczynimy z skrzynią Pańską? powiedzcie nam, jako ją odesłać mamy na miejsce jej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Którzy odpowiedzieli: Jeźli odeślecie skrzynię Boga Izraelskiego, nie odsyłajcież jej próżnej, ale przy niej koniecznie oddajcie ofiarę za przewinienie; tedyć będziecie uzdrowieni, i dowiecie się, czemu nie odstąpiła ręka jego od was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'I rzekli: Jakaż będzie ofiara za przewinienie, którą jej oddać mamy? Odpowiedzieli: Według liczby książąt Filistyńskich pięć złotych zadnic i pięć złotych myszy; albowiem jednaka jest plaga na was wszystkich, i na książęta wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'A poczynicie podobieństwa zadnic waszych, i podobieństwa myszy waszych, które psowały ziemię, i oddacie Bogu Izraelskiemu chwałę; owa snać ulży ręki swej nad wami, i nad Bogami waszymi, i nad ziemią waszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'A czemuż obciążacie serce wasze, jako obciążali Egipczanie i Farao serce swoje? izaż nie dopiero, gdy dziwne rzeczy nad nimi czynił wypuścili je i wyszli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Przetoż teraz sprawcie wóz nowy jeden, a weźmijcie dwie krowy od cieląt, na których nie postało jarzmo, i zaprzężcie te krowy w wóz, a cielęta ich od nich odwiedźcie do domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'Weźmijcie też skrzynię Pańską, i wstawcie ją na wóz; a sztuki złote, któreście ofiarowali za przewinienie, włóżcie w skrzynkę po bok jej, a puśćcie ją, że pójdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'A patrzajcie, jeźli drogą granic swych pójdzie do Betsemes, tedyć on na nas dopuścił to wielkie złe; a jeźliż nie, tedy poznamy, że nie ręka jego dotknęła się nas, ale to z trafunku przyszło na nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'I uczynili tak oni mężowie, a wziąwszy dwie krowy od cieląt, zaprzęgli je w wóz, a cielęta ich zamknęli w domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'Potem wstawili skrzynię Pańską na wóz, i skrzynkę, i myszy złote, i podobieństwa zadnic swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'I udały się one krowy drogą, prosto ku Betsemes, a gościńcem jednym idąc szły, a ryczały; i nie zstępowały ani w prawo ani w lewo a książęta Filistyńskie szły za nimi aż do granic Betsemes.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'A na ten czas Betsemczycy żęli pszenicę w dolinie, a podniósłszy oczów swych ujrzeli skrzynię, i uradowali się ujrzawszy ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'A gdy wóz przyszedł na pole Jozuego Betsemity, tamże stanął. Tam też był kamień wielki; tedy porąbawszy drwa od onego wozu, ofiarowali one krowy na całopalenie Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Ale Lewitowie zstawili skrzynię Pańską, i skrzynkę, która była z nią, w której były sztuki złote, i postawili na onym kamieniu wielkim; a mężowie z Betsemes sprawowali całopalenia, i ofiarowali ofiary Panu onego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'Co widząc pięcioro książąt Filistyńskich, wrócili się do Akkaronu onegoż dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'A teć były zadnice złote, które oddali Filistynowie za przewinienie Panu: Od Azotu jednę, od Gazy jednę, od Aszkalonu jednę, od Gat jednę, i od Akkaronu jednę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'Myszy także złote według liczby wszytskich miast Filistyńskich, od pięciu księstw, począwszy od miasta murowanego aż do wsi bez muru, i aż do kamienia onego wielkiego, na którym postawili skrzynię Pańską, który jest aż do dnia tego na polu Jozuego Betsemity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Ale pobił Pan niektóre z mężów Betsemitskich, przeto iż zaglądali w skrzynię Pańską, i pobił z ludu pięćdziesiąt tysięcy i siedmdziesiąt mężów; i płakał lud, przeto że Pan lud wielką porażką poraził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'I rzekli mężowie z Betsemes: Któż się będzie mógł ostać przed obliczem Pana, Boga tego świętego? i do kogoż pójdzie od nas?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'A tak wyprawili posły do obywateli Karyjatyjarym mówiąc: Przywrócili Filistynowie skrzynię Pańską; pójdźcie, przeprowadźcie ją do siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'Przyszli tedy mężowie z Karyjatyjarym, i odwieźli skrzynię Pańską, a wnieśli ją do domu Abinadabowego w Gabaa; a Eleazara syna jego poświęcili, aby strzegł skrzyni Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'I stało się, gdy od onego dnia, jako została skrzynia w Karyjatyjarym, wyszedł niemały czas, to jest dwadzieścia lat, że płakał wszystek dom Izraelski za Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'I rzekł Samuel do wszystkiego domu Izraelskiego mówiąc: Jeźliże ze wszystkiego serca waszego nawracacie się do Pana, wyrzućcież bogi cudze z pośrodku siebie, i Astarota, a zgotujcie serce wasze Panu, i służcie jemu samemu, tedyć was wybawi z ręki Filistynów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Przetoż wyrzucili synowie Izraelscy Baala i Astarota, a służyli Panu samemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'Tedy rzekł Samuel: Zgromadźcie wszystkiego Izraela do Masfa, abym się modlił za wami Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'A tak zgromadzili się do Masfa, a czerpając wodę, wylewali przed Panem, i pościli tam dnia onego, mówiąc: Zgrzeszyliśmy Panu. I sądził Samuel syny Izraelskie w Masfa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'A gdy usłyszeli Filistynowie, że się zgromadzili synowie Izraelscy do Masfa, ruszyły się książęta Filisyńskie przeciw Izraelowi. Co gdy usłyszeli synowie Izraelscy, zlękli się przed Filistynami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'I rzekli synowie Izraelscy do Samuela: Nie przestawaj za nami wołać do Pana, Boga naszego, aby nas wybawił z ręki Filistynów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'Przetoż wziął Samuela baranka ssącego jednego, i ofiarował go całego na całopalenie Panu; i wołał Samuel do Pana za Izraelem, a wysłuchał go Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'I stało się, gdy Samuel sprawował całopalenie, że Filistynowie przyciągnęli blisko, aby walczyli przeciw Izraelowi; ale zagrzmiał Pan grzmotem wielkim dnia onego nad Filistynami, a potarł je, i porażeni są przed obliczem Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'A mężowie Izraelscy wypadłszy z Masfa, gonili Filistyny, i bili je aż pod Betchar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Tedy wziął Samuel kamień jeden, i postawił go między Masfa a między Sen, i nazwał imię jego Ebenezer, mówiąc: Aż póty pomagał nam Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'A tak poniżeni są Filistynowie, a potem więcej nie przychodzili na granicę Izraelską; albowiem była ręka Pańska przeciwko Filistynom po wszystkie dni Samuelowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'I przywrócone są miasta Izraelowi, które byli wzięli Filistynowie Izraelowi, od Akkaronu aż do Get, i granice ich oswobodził Izrael z ręki Filistynów; i był pokój między Izraelem, i między Amorejczykiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'I sądził Samuel Izraela po wszystkie dni żywota swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'A chodząc na każdy rok, obchodził Betel, i Gilgal, i Masfa, sądząc Izraela po onych wszystkich miejscach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Potem się wracał do Ramaty; bo tam był dom jego, i tam sądził Izraela; tamże też zbudował ołtarz Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'I stało się, gdy się zstarzał Samuel, że postanowił syny swe sędziami nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'A było imię syna jego pierworodnego Joel, a imię drugiego syna jego Abija; ci byli sędziami w Beerseba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'Ale nie chodzili synowie jego drogami jego; lecz udali się za łakomstwem, i brali dary, a wywracali sąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Przetoż zebrali się wszyscy starsi Izraelscy, i przyszli do Samuela do Ramaty,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'I rzekli mu: Otoś się ty zstarzał, a synowie twoi nie chodzą drogami twojemi; przetoż postanów nam króla, aby nas sądził, jako je wszystkie narody mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'Ale się nie podobała ta rzecz Samuelowi, że mówili: Daj nam króla, aby nas sądził; przetoż modlił się Samuel Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'Tedy rzekł Pan do Samuela: Usłuchaj głosu ludu tego we wszystkiem, coć powiedzą; albowiem nie tobą wzgardzili, ale mną wzgardzili, iżbym nie królował nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'A według wszystkich spraw, które czynili od onego dnia, któregom je wywiódł z Egiptu, aż do dnia tego, gdy mię opuścili i służyli bogom obcym, tak też czynią i tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Przetoż teraz usłuchaj głosu ich, a wszakże oświadcz się jako najpilniej przed nimi, i oznajmij im prawo króla, który nad nimi ma królować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'A tak Samuel odniósł wszystkie słowa Pańskie do ludu, który go prosił o króla,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'I mówił: Toć będzie prawo króla, który królować ma nad wami: Syny wasze brać będzie a osadzi nimi wozy swoje, i poczyni je jezdnymi, a będą biegać przed wozem jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'Poczyni też sobie z nich pułkowniki nad tysiącami, i rotmistrze nad pięćdziesięcioma; poczyni z nich oracze ról swoich, i żeńce żniwa swego, i te, którzyby robili rynsztunki wojenne, i potrzeby do wozów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Córki też wasze pobierze, by gotowały rzeczy wonne, i były kucharkami i piekarkami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Pola też wasze, i winnice wasze, i oliwnice wasze co najlepsze pobierze, a rozda sługom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Przytem z zasiewków waszych, i z winnic waszych będzie brał dziesięciny, i rozda je komornikom swoim, i sługom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'Także sługi wasze, i dziewki wasze, i młodzieńce wasze co najgrzeczniejsze będzie brał, i osły wasze pobierze, i obróci do roboty swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Z bydła waszego dziesięcinę będzie brał, a wy będziecie niewolnikami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'I będziecie wołać dnia onego dla króla waszego, którego sobie obierzecie, a nie wysłucha was Pan dnia onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Ale nie chciał lud usłuchać głosu Samuelowego; owszem mówili: Nic z tego; ale król niech będzie nad nami,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'Abyśmy byli i my, jako i wszystkie narody; będzie nas sądził król nasz, a wychodząc przed nami, będzie odprawował wojny nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'A wysłuchwaszy Samuel wszystkich słów ludu, odniósł je do uszu Pańskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'I rzekł Pan do Samuela: Usłuchaj głosu ich, a postanów nad nimi króla. Przetoż rzekł Samuel do mężów Izraelskich: Idźcie każdy do miasta swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'I był mąż z pokolenia Benjamin, którego imię było Cys, syn Abijelów, syna Seror, syna Bechorat, syna Afija, syna męża Jemini, duży w siłę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'Ten miał syna imieniem Saula, młodzieńca urodziwego, a nie było nikogo z synów Izraelskich urodziwszego nadeń; głową był wyższy nad wszystek inny lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'A zginęły były oślice Cysowi, ojcu Saulowemu. I rzekł Cys do Saula, syna swego: Weźmij teraz z sobą jednego z sług, a wstawszy idź, i szukaj oślic.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'Tedy on szedł przez górę Efraim, i przeszedł ziemię Salisa, lecz nie znaleźli. Przeszli także ziemię Salim, a nie znaleźli. Nadto przeszli i ziemię Jemini, a nie znaleźli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'A przyszedłszy do ziemi Suf, rzekł Saul do sługi swego, który był z nim: Pójdź, a wróćmy się, by snać zaniechwaszy ojciec mój oślic, nie frasował się o nas,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'Który mu odpowiedział: Oto teraz jest mąż Boży w tem mieście, a mąż to zacny; cokolwiek powie, wszystko się stawa; przetoż pójdźmy tam, snać nam powie o drodze naszej, którą iść mamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Tedy odpowiedział Saul słudze swemu: Więc pójdziemy; ale cóż przyniesiemy onemu mężowi? Bo chleba nie stało w sumkach naszych, a podarku niemasz, którybyśmy przynieśli mężowi Bożemu; cóż mamy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Tedy sługa znowu odpowiedział Saulowi, i rzekł: Otom znalazł u siebie czwartą część sykla srebrnego, którą damy mężowi Bożemu, aby nam oznajmił drogę naszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, 'Przedtem w Izraelu tak mawiał każdy, gdy się szedł radzić Boga: Chodźcie, a pójdziemy aż do widzącego; bo którego dziś zowią prorokiem, tego przedtem nazywano widzącym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Tedy rzekł Saul do sługi swego: Dobre jest słowo twoje; chodź, pójdźmy, i szli do miasta, w którem był mąż Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'A gdy wstępowali na górę miasta, a potkali dzieweczki, wychodzące czerpać wodę, rzekli im: A jestże tu widzący?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'Które odpowiadając im,rzekły: Jest, oto przed tobą; spiesz się tedy, dziś bowiem przyszedł do miasta, gdyż dziś ofiary sprawuje lud na górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Skoro wnijdziecie do miasta, znajdziecie go, pierwej niż pójdzie na górę, aby jadł; albowiem lud nie będzie jadł, aż on przyjdzie; bo on będzie błogosławił ofierze, potem będą jeść wezwani. A przetoż idźcie, bo go o tej godzinie znajdziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Weszli tedy do miasta; a gdy przyszli w pośrodek miasta, oto, Samuel wychodził przeciwko nim, aby szedł na górę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'A Pan objawił był Samuelowi dzień przedtem, niźli Saul przyszedł, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'O tym czasie jutro poślę do ciebie męża z ziemi Benjamin, którego pomażesz za wodza nad ludem moim Izraelskim; a on wybawi lud mój z rąk Filistyńskich. Bom wejrzał na lud mój, gdyż przyszło wołanie jego do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'A gdy Samuel wejrzał na Saula, rzekł mu Pan. Otóż mąż, o którymemci powiedział; tenci będzie panował nad ludem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'A tak przystąpił Saul do Samuela w pośrodku bramy, i rzekł: Proszę powiedz mi, gdzie tu jest dom widzącego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'I odpowiedział Samuel, Saulowi, mówiąc: Jam jest widzący. Wstąp przedemną na górę, a będziecie dziś jedli ze mną; potem cię odprawię rano, a cokolwiek jest w sercu twem, oznajmię tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'A o oślice, któreć zginęły dziś trzeci dzień, nie frasuj się, boć się znalazły.I czyjeż wszystko co najlepszego w Izraelu? izali nie twoje, i nie wszystkiego domu ojca twego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'A odpowiadając Saul, rzekł: Izalim ja nie syn Jemini z najmniejszego pokolenia Izraelskiego? a dom mój azaż nie najpodlejszy między wszystkiemi domy pokolenia Benjaminowego? Przeczżeś tedy mówił do mnie takowe słowa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'A tak wziąwszy Samuel Saula i sługę jego, wywiódł je na salę, i dał im miejsce przedniejsze między wezwanymi, których było około trzydziestu mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'I rzekł Samuel kucharzowi: Daj sam tę cząstkę, którąm ci dał, i o którejm ci rzekł: Schowaj ją u siebie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'A gdy przyniósł kucharz łopatkę, i to, co było na niej, położył Samuel przed Saula, i rzekł: Oto, co zostało, weźmij przed się, a jedz; bo na ten czas schowano to dla ciebie, gdym rzekł: Wezwałem ludu. I jadł Saul z Samuelem dnia onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'A gdy zstąpili z góry do miasta, rozmawiał z Saulem na dachu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'Potem wstali bardzo rano. I stało się, gdy się poczęło rozedniewać, zawołał Samuel Saula na dach, mówiąc: Wstań, a odprawię cię; wstawszy tedy Saul, wyszli obaj z domu, on i Samuel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'A gdy schodzili ku końcowi miasta, rzekł Samuel do Saula: Rzecz słudze, aby szedł przed nami, i szedł; a ty pozostań trochę, żeć opowiem słowo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Tedy Samuel wziął bańkę oliwy, i wylał na głowę jego, a pocałowawszy go, rzekł: Izali cię nie pomazał Pan nad dziedzictwem swojem za wodza?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Gdy dziś odejdziesz ode mnie, znajdziesz dwóch mężów u grobu Racheli, na granicach Benjamin w Selsa, którzyć powiedzą: Nalazły się oślice, którycheś chodził szukać, a oto zaniechawszy ojciec twój starania o oślicach, frasuje się o was, mówiąc; Cóż mam czynić z strony syna mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'Potem odszedłszy stamtąd dalej przyjdziesz aż na pole Tabor; i spotkają cię tam trzej mężowie idący do Boga, do domu Bożego, jeden niesie troje koźląt, a drugi niesie trzy bochny chleba, a trzeci niesie łagiew wina;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'I pozdrowią cię w pokoju, i dadząć dwa chleby, które weźmiesz z ręk ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Potem przyjdziesz na pagórek Boży, kędy jest straż Filistyńska; a gdy tam wnijdziesz do miasta, spotkasz się z gromadą proroków zstępujących z góry, a przed nimi będzie harfa, i bęben, i piszczałka, i lutnia, a oni będą prorokowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'I zstąpi na cię Duch Pański, i będziesz z nimi prorokował, a odmienisz się w inszego męża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'A gdy przyjdą te znaki na cię, czyń cokolwiek znajdzie ręka twoja: bo Bóg jest z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'Potem pójdziesz przedemną do Galgal, a oto, ja przyjdę do ciebie dla sprawowania ofiar całopalnych, i dla ofiarowania ofiar spokojnych; przez siedm dni będziesz czekał, aż przyjdę do ciebie i ukażęć, co będziesz miał czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'I stało się, gdy się obrócił, aby odszedł od Samuela, odmienił Bóg serce jego w insze; i spełniły się wszystkie one znaki dnia onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'I przyszli tam na pagórek, a oto, gromada proroków spotkała się z nim, i odpoczął na nim Duch Boży, i prorokował w pośrodku nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Stało się tedy, że wszyscy, którzy go przedtem znali, ujrzeli, a oto, z prorokami prorokował; i mówili wszyscy jeden do drugiego: Cóż się stało synowi Cysowemu? Izali też Saul między prorokami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'I odpowiedział mąż niektóry stamtąd, i rzekł: I któż jest ojcem ich? przetoż weszło to w przypowieść: Izali i Saul między prorokami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'I przestał prorokować, a przyszedł na górę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Potem rzekł stryj Saula do niego, i do sługi jego: Gdzieżeście chodzili? I odpowiedział: Szukać oślic; a widząc, żeśmy ich nie mogli znaleść, poszliśmy do Samuela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'I rzekł stryj Saula: Powiedz mi proszę, co wam powiedział Samuel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'I odpowiedział Saul stryjowi swemu: Oznajmił nam za pewne, iż znaleziono oślice; ale o sprawie królestwa, o którem mu Samuel powiedział, nie oznajmił mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Potem zwołał Samuel ludu do Pana do Masfa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'I rzekł do synów Izraelskich: Tak mówi Pan, Bóg Izraelski: Jam wywiódł Izraela z Egiptu, i wybawiłem was z rąk Egipczanów, i z rąk wszystkich królestw, które was trapiły;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'Aleście wy dziś odrzucili Boga waszego, który was sam wybawia od wszystkiego złego waszego, i od ucisków waszych, i rzekliście mu: Postanów króla nad nami. Przetoż teraz stańcie przed Panem według pokoleń waszych, i wedle tysiąców waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'A gdy kazał przystąpić Samuel wszystkim pokoleniom Izraelskim, padł los na pokolenie Benjaminowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'Potem kazał przystąpić pokoleniu Benjaminowemu według domów jego, i padł los na dom Metry, a trafił na Saula, syna Cysowego; i szukano go, ale go nie znaleziono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Przetoż pytali się znowu Pana: Przyjdzieli jeszcze sam ten mąż? I odpowiedział Pan: Oto się skrył między sprzętem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'Tedy poszedłszy wzięli go stamtąd. I stanął w pośród ludu, i był głową wyższy nad wszystek lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'I rzekł Samuel do wszystkiego ludu: Widzicież, kogo to Pan obrał, że mu niemasz równego między wszystkim ludem? przetoż zakrzyknął wszystek lud, mówiąc: Niech żyje król!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Tedy powiedział Samuel ludowi prawo królewskie, i spisał je na księgach, które położył przed Panem. Potem rozpuścił Samuel wszystek lud, każdego do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Także i Saul szedł do domu swego do Gabaa, i szły za nim wojska, których Bóg serca dotknął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Lecz ludzie niepobożni rzekli: Cóż, tenże nas wybawi? I wzgardzili nim, ani mu przynieśli darów; ale on czynił, jakoby nie słyszał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Tedy przyciągnął Nahas, Ammończyk, i położył się obozem przeciw Jabes Galaadskiemu. I rzekli wszyscy mężowie Jabes do Nahasa: Uczyń z nami przymierze a będziemyć służyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'I rzkł do nich Nahas, Ammończyk: W ten sposób uczynię z wami przymierze, jeźli wyłupię z was każdemu oko prawe, a włożę to obelżenie na wszystkiego Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'I rzekli do niego starsi z Jabes: Pozwól nam siedm dni, że roześlemy posły po wszystkich granicach Izraelskich; a jeźli nie będzie, ktoby nas ratował, tedy wynijdziemy do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'I przyszli posłowie do Gabaa Saulowego, a powiedzieli te słowa, gdzie słyszał lud; i podniósł wszystek lud głos swój, a płakał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'A oto, Saul szedł za wołami z pola, i rzekł Saul: Cóż się stało ludowi, iż płacze? I powiedzieli mu wszystkie słowa mężów z Jabes.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Tedy zstąpił Duch Boży na Saula, gdy usłyszał słowa te, i zapalił się gniew jego bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'A wziąwszy parę wołów, rozrąbał je na sztuki, i rozesłał po wszystkich granicach Izraelskich przez też posły, mówiąc: Ktokolwiek nie wynijdzie za Saulem i za Samuelem, tak się stanie wołom jego. I padł strach Pański na lud, i wyszli jako mąż jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'I obliczył je w Bezeku; a było synów Izraelskich trzy kroć sto tysięcy, a mężów Juda trzydzieści tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'I rzekli posłom, którzy byli przyszli: Tak powiedzcie mężom w Jabes Galaad: Jutro będziecie wybawieni, gdy ogrzeje słońce. I wrócili się posłowie, i oznajmili to mężom w Jabes, którzy się uweselili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Tedy rzekli mężowie Jabese Ammonitom: Jutro wynijdziemy do was, a uczynicie z nami wszystko, co dobrego będzie w oczach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Nazajutrz tedy rozszykował Saul lud na trzy hufy; i wtargnął w pośrodek obozu przed świtaniem; i bił Ammonity, aż się dzień ogrzał; a którzy pozostali, rozpierzchnęli się, tak, iż nie zostało z nich i dwóch pospołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'I rzekł lud do Samuela: Któż jest ten, co mówił: Saulże będzie królował nad nami? Wydajcie męże te, abyśmy je pobili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'I rzekł Saul: Nie będzie nikt zabity dnia tego; bo dziś Pan uczynił wybawienie w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Zatem rzekł Samuel do ludu: Pójdźcie, a idźmy do Galgal, a tam odnowimy królestwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'Szedł tedy wszystek lud do Galgal, i postanowili tam Saula królem przed Panem w Galgal, tamże sprawowali ofiary spokojne przed Panem. I weselił się tam Saul, i wszyscy mężowie Izraelscy bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'I rzekł Samuel do wszystkiego Izraela: Otom usłuchał głosu waszego we wszystkiem, o coście ze mną mówili, i postanowiłem nad wami króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'A oto, teraz król chodzi przed wami, a jam się zstarzał i osiwiał; oto, i synowie moi są z wami, a jam też chodził przed wami od młodosci mojej aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Otom ja tu. Świadczcież przeciwko mnie przed Panem, i przed pomazańcem jego, jeźlim wziął któremu z was wołu, albo jeźlim wziął któremu z was osła, i jeźlim kogo ucisnął, albo gwałt komu uczynił, i jeźlim z ręki czyjej wziął dar, żebym miał kryć o czy swoje dla niego; a nagrodzę wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'I odpowiedzieli: Nie ucisnąłeś nas, aniś nam gwałtu uczynił, aniś wziął z ręki czyjej żadnej rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'Nadto rzekł do nich: Świadkiem Pan przeciwko wam, i świadkiem pomazaniec jego dnia tego, iżeście nic nie znaleźli w ręce mojej. A oni rzekli: Świadkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'I rzekł Samuel do lud: Pan świadkiem, który uczynił Mojżesza i Aarona, i który wywiódł ojce wasze z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Przetoż teraz stańcie, abym się rozpierał z wami przed Panem, o wszystkie dobrodziejstwa Pańskie, które wam czynił i ojcom waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Gdy zaszedł Jakób do Egiptu, wołali ojcowie wasi do Pana, i posłał Pan Mojżesza i Aarona, którzy wywiedli ojce wasze z Egiptu, a posadzili je na tem miejscu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'A gdy zapomnieli Pana Boga swego, podał je w rękę Sysarze, hetmanowi wojska Hasor, i w rękę Filistynów, także w rękę króla Moabskiego, którzy walczyli przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Ale gdy wołali do Pana, i mówili: Zgrzeszyliśmy, żeśmy opuścili Pana, a służyliśmy Baalom i Astarotowi, przetoż teraz wybaw nas z rąk nieprzyjaciół naszych, a będziemyć służyli:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'Tedy posłał Pan Jerubaala, i Bedona, i Jeftego, i Samuela, a wyrwał was z ręki nieprzyjaciół waszych okolicznych, i mieszkaliście bezpiecznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Potem widząc, iż Nahas, król synów Ammonowych, przyciągnął przeciwko wam, rzekliście do mnie: Żadnym sposobem; ale król będzie królował nad nami: choć Pan Bóg wasz był królem waszym,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Teraz tedy oto król, któregoście obrali, któregoście żądali; oto, przełożył Pan króla nad wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Jeźli się będziecie bali Pana, a jemu służyli, i słuchali głosu jego a nie rozdraźnicie ust Pańskich, tedy i wy, i król, który króluje nad wami, będziecie szczęśliwie chodzić za Panem, Bogiem waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Ale jeźliż nie będziecie słuchać głosu Pańskiego, a rozdraźnicie usta Pańskie, będzie ręka Pańska przeciwko wam, jako i przeciwko ojcom waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Jeszcze teraz stójcie, a obaczcie tę rzecz wielką, którą Pan uczyni przed oczyma waszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Izali dziś nie pszeniczne żniwa? Będę wzywał Pana, a puści gromy i dżdże, a dowiecie się, i obaczycie, jaka jest wielka złość wasza, którejście się dopuścili przed oczyma Pańskiemi, żądając sobie króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Przetoż wołał Samuel do Pana, i puścił Pan gromy i deszcz dnia onego, i bał się wszystek lud bardzo Pana i Samuela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'I rzekł wszystek lud do Samuela: Módl się za sługami twymi Panu Bogu twemu, żebyśmy nie pomarli: bośmy przydali do wszystkich grzechów naszych tę złość, żeśmy sobie prosili o króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Tedy rzekł Samuel do ludu: Nie bójcie się, aczeście wy to wszystko złe uczynili; wszakże przeto nie odstępujcie od Pana, ale służcie Panu ze wszystkiego serca waszego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'A nie udawajcie się za próżnościami, które wam nic nie pomogą, ani was wybawią, gdyż próżnościami są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Albowiemci nie opuści Pan ludu swego, dla imienia swego wielkiego, gdyż się upodobało Panu, uczynić was sobie ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'A mnie nie daj Boże, abym miał grzeszyć przeciw Panu, przestawając modlić się za wami; owszem was będę nauczał drogi dobrej i prostej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Jedno się bójcie Pana, a służcie mu w prawdzie ze wszystkiego serca waszego, a to upatrujcie, jako wielmożnie poczynał z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Ale jeźli przecię w złości trwać będziecie, tedy i wy, i król wasz poginiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Saul tedy pierwszego roku królowania swego (bo tylko dwa lata królował nad Izraelem,)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'Wybrał sobie trzy tysiące z Izraela; i byli przy Saulu dwa tysiące w Machmas, i na górze Betel, a tysiąc był z Jonatanem w Gabaa Benjamin, a ostatek ludu rozpuścił, każdego do przybytku swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'Tedy Jonatan pobił straż Filistyńską, która była w Gabaa, i usłyszeli Filistynowie. Zatem Saul zatrąbił w trąbę po wszystkiej ziemi, mówiąc: Niech usłyszą Hebrejczycy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'A tak usłyszał wszystek Izrael, że powiadano: Pobił Saul straż Filistyńską, dla czego też obrzydłym był Izrael między Filistyny. I zwołano lud za Saulem do Galgal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Filistynowie też zebrali się, aby walczyli z Izraelem, mając trzydzieści tysięcy wozów, i sześć tysięcy jezdnych, a ludu bardzo wiele jako piasku, który jest na brzegu morskim, i ciągnęli a położyli się obozem w Machmas, na wschód słońca od Betawen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'Ale mężowie Izraelscy widząc, iż byli ściśnieni, (bo był uciśniony lud,) pokryli się w jaskini, i w obronne miejsca, i w skały, i w wieże, i w jamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Niektórzy też Hebrejczykowie przeprawili się za Jordan, do ziemi Gad i Galaad; ale Saul jeszcze pozostał był w Galgal, a wszystek lud potrwożony szedł za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'I czekał przez siedm dni według czasu zamierzonego od Samuela, a gdy nie przyszedł Samuel do Galgal, rozbieżał się lud od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Tedy rzekł Saul: Przynieście do mnie ofiarę całopalenia, i ofiary spokojne; tamże ofiarował całopalenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'A gdy dokończył ofiary całopalenia, oto Samuel przyszedł, i wyszedł Saul przeciwko niemu, żeby go przywitał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'I rzekł Samuel: Cóżeś uczynił? Odpowiedział Saul: Iżem widział, że się rozchodzi lud odemnie, a tyś nie przyszedł na czas naznaczony, Filistynowie się też zebrali do Machmas,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'Tedym rzekł: Oto przypadną Filistynowie na mię w Galgal, a jam jeszcze nie ubłagał twarzy Pańskiej, i tak poważyłem się, i ofiarowałem całopalenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'I rzekł Samuel do Saula; Głupieś uczynił, nie zachowałeś przykazania Pana Boga twego, któreć rozkazał; albowiem terazby był utwierdził Pan królestwo twoje nad Izraelem aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Ale teraz królestwo twoje nie ostoi się; Pan sobie znalazł męża według serca swego, któremu rozkazał Pan, aby był wodzem nad ludem jego, gdyżeś nie zachował, coć przykazał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'Wstawszy tedy Samuel, poszedł z Galgal do Gabaa w Benjamin, i policzył Saul lud, którego się znalazło przy nim około sześciu set mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'Przetoż Saul, i Jonatan, syn jego, i lud, który się znalazł przy nim, zostali w Gabaa w Benjamin, a Filistynowie leżeli obozem w Machmas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'I wyszły dla zdobyczy z obozu Filistyńskiego trzy hufce: hufiec jeden obrócił się drogą ku Ofra do ziemi Saul;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'A drugi hufiec obrócił się drogą ku Betoron; trzeci zaś hufiec udał się drogą ku granicy przyległej dolinie Soboim ku puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Ale kowal nie znajdował się we wszystkiej ziemi Izraelskiej; bo byli zabieżeli temu Filistynowie, żeby snać Hebrejczycy nie robili mieczów ani oszczepów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Przetoż chadzał wszystek Izrael do Filistynów, ostrzyć sobie każdy lemiesz swój, i motykę swoję, i siekierę swoję, i rydel swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'Bo stępiały były ostrza lemieszów, i motyk, i wideł, i siekier aż do ościenia, które było ostrzyć potrzeba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'I było pod czas wojny, że się nie znajdował miecz, ani oszczep w ręku wszystkiego ludu, który był z Saulem, i z Jonatanem; tylko się znajdował u Saula i Jonatana, syna jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'A straż Filistyńska wyszła na drogę ku Machmas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'I stało się dnia niektórego, że rzekł Jonatan, syn Saula, do sługi, który nosił broń jego: Pójdź, przejdziemy do straży Filistyńskiej, która jest na onej stronie; a ojcu swemu o tem nie oznajmił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'Ale Saul został był przy pagórku pod jabłonią granatową, która była w Migron, i lud, który był z nim, około sześciu set mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'A Achijas, syn Achitoba, brata Ichaboda, syna Fineesowego, syna Heli, kapłana Pańskiego w Sylo, nosił Efod: a lud nie wiedział, iż odszedł Jonatan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Ale między przechodami, kędy szukał Jonatan przejścia ku straży Filistyńskiej, była skała ostra po jednej stronie, także skała ostra po drugiej stronie; jednej imię Boses a drugiej Sene.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'Skała jedna była na północy przeciwko Machmas, a druga na południe przeciwko Gabaa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'I rzekł Jonatan do wyrostka, który nosił broń jego: Pójdźmy, a przejdziemy do straży tych nieobrzezańców, snać uczyni Pan przez nas wybawienie; boć nie trudno Panu wybawić w wielu albo w trosze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'I rzekł mu sługa, noszący broń jego: Czyń, co się podoba sercu twemu; idź, gdzie chcesz, oto ja będę z tobą według woli twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Tedy rzekł Jonatan: oto my idziemy do tych mężów, a ukażemy się im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'Jeźli nam tak rzeką: Czekajcie, aż przyjdziemy do was, stójmyż na miejscu swem, a nie chodźmy do nich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Ale jeźliż tak rzeką: Pójdźcie do nas, pójdźmyż; boć je dał Pan w ręce nasze, a to będziemy mieli za znak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Ukazali się tedy obaj straży Filistyńskiej. I rzekli Filistynowie: Onoż Hebrejczycy wychodzą z jaskini, w której się byli pokryli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'I mówili mężowie, co na straży byli, do Jonatana, i do wyrostka, co za nim broń nosił, i rzekli: Pójdźcie ku nam, a oznajmiemy wam coś. I rzekł Jonatan do sługi swego: Pójdź za mną; boć je Pan podał w ręce Izraelczykom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'Lazł tedy Jonatan na rękach swych, i na nogach swych, a wyrostek jego za nim; i padli przed Jonatanem, i przed wyrostkiem jego, który też zabijał, idąc za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'A tać była porażka pierwsza, w której pobił Jonatan i wyrostek jego, co broń za nim nosił, około dwudziestu mężów, jakoby na pół staja roli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'I przyszedł strach na obóz na polu, i na wszystek lud; straż też, i ci którzy byli wyjechali na zdobycz, lękali się, aż się ziemia trzęsła; bo była w strachu Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'I obaczyła straż Saulowa w Gabaa Benjaminowym, że się ono mnóstwo rozsypało, i pierzchło, i że się go urywało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Tedy rzekł Saul do ludu, który przy nim był: Wywiedzcie się zaraz, a obaczcie, kto odszedł z naszych; a gdy się wywiadowali, oto nie było Jonatana, i wyrostka, co za nim broń nosił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'I rzekł Saul do Achijasa: Przystaw skrzynię Bożą; (bo była skrzynia Boża dnia onego z syny Izraelskimi.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'I stało się, gdy jeszcze Saul mówił do kapłana, że zamięszanie, które było w obozie Filistyńskim, wzmagało się i rozmnażało; przetoż rzekł Saul do kapłana: Zawściągnij ręki twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'A tak zebrawszy się Saul, i wszystek lud, który był z nim, przyszli, gdzie była bitwa, a oto, każdego miecz był obrócony na towarzysza jego, i była porażka bardzo wielka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'A Hebrejczycy, którzy przedtem przestawali z Filistynami, którzy z nimi ciągnęli w obozie tam i sam, ci się też obróciwszy stanęli przy Izraelu, który był z Saulem i z Jonatanem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Nadto wszyscy mężowie Izraelscy, którzy się byli pokryli na górze Efraim, gdy usłyszeli, iż uciekają Filistynowie, szli za nimi w pogoń w onej bitwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'I wybawił Pan dnia onego Izraela, a bitwa ona zaszła aż do Betawen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'A mężowie Izraelscy strudzeni byli onego dnia. I poprzysiągł Saul lud, mówiąc: Przeklęty mąż, któryby jadł chleb przed wieczorem, aż się pomszczę nad nieprzyjacioły mymi. I nie skosztował wszystek lud chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'Tedy wszystek lud onej ziemi przyszedł do lasu, gdzie było wiele miodu na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'Wszedłszy tedy lud do lasu, ujrzał płynący miód; wszakże nie doniósł żaden z miodem ręki swojej do ust swoich, bo się bał lud onej przysięgi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Ale Jonatan nie słyszał, gdy poprzysięgał lud ojciec jego; i ściągnął koniec laski, którą miał w ręce swej, a omoczył go w plastrze miodu, i obrócił rękę swoję do ust swoich, i oświeciły się oczy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'A odpowiadając jeden z ludu, rzekł: Przysięgą zawiązał ojciec twój lud, mówiąc: Przeklęty mąż, któryby jadł chleb dzisiaj; stądże ustał lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Tedy rzekł Jonatan: Strwożył ojciec mój lud ziemi. Patrzcie proszę jako są oświecone oczy moje, iżem skosztował trochę miodu tego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Jako daleko więcej, gdyby się był najadł dziś lud z łupu nieprzyjaciół swoich, których nabył; izaliby nie była większa porażka między Filistynami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'Porazili tedy dnia onego Filistyny od Machmas aż do Ajalon, i spracował się lud bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Tedy się lud udał na łup, a nabrawszy owiec, i wołów, i cieląt, rzezali je na ziemi, a jadł lud ze krwią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'I powiedziano Saulowi mówiąc: Oto lud grzeszy przeciw Panu, jedząc ze krwią; który rzekł: Zgrzeszyliście; przytoczcież sam do mnie teraz kamień wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Zatem rzekł Saul: Rozejdźcie się między lud, a rzeczcie do nich: Przywiedźcie do mnie każdy wołu swego, i każdy owcę swą, bijcież je tu, a jedzcie, a nie zgrzeszycie przeciw Panu, jedząc ze krwią. I przywiedli wszystek lud, każdy wołu swego w ręce swej w nocy, i bito je tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'I zbudował Saul ołtarz Panu; toć najpierwszy ołtarz, który zbudował Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'I rzekł Saul: Puśćmy się za Filistynami nocą, a bijmy je aż do świtania, a nie zostawujmy z nich i jednego. Którzy mu odpowiedzieli: Cokolwiek dobrego jest w oczach twoich uczyń, ale kapłan rzekł: Przystąpmy sam do Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'Tedy się radził Saul Boga: Mamli się puścić za Filistynami? podaszli je w ręce Izraela? I nie odpowiedział mu dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'Przetoż rzekł Saul: Przystąpcie sam wszyscy celniejsi z ludu, i wywiedzcie się, a patrzcie, przy kimby grzech dziś był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Bo jako żywy Pan, który wybawia Izraela, choćby był i przy Jonatanie, synu moim, że śmiercią umrze. I nie odpowiedział mu nikt ze wszystkiego ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'Nadto rzekł do wszystkiego Izraela: Wy będziecie na jednej stronie, a ja i Jonatan, syn mój, będziemy na drugiej stronie. I odpowiedział lud Saulowi: Co dobrego jest w oczach twoich, uczyń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Zatem rzekł Saul do Pana, Boga Izraelskiego: Panie, pokaż sprawiedliwą; i nalezion jest Jonatan i Saul, a lud wyszedł z tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Potem rzekł Saul: Rzućcie los między mną i między Jonatanem, synem moim; i znaleźony jest Jonatan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'Zatem rzekł Saul do Jonatana: Powiedz mi, coś uczynił? I powiedzał mu Jonatan, i rzekł: Skosztowałem tylko końcem laski, którąm miał w ręce mojej, trochę miodu, i dla tegoż ja mam umrzeć?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'I odpowiedzał Saul: To a to mi niech Bóg uczyni, że śmiercią umrzesz Jonatanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Ale lud rzekł do Saula: Izali Jonatan umrze, który uczynił to wybawienie wielkie w Izraelu? Boże uchowaj! jako żywy Pan, nie spadnie i włos z głowy jego na ziemię; albowiem za pomocą Bożą uczynił to dzisiaj. A tak wybawił lud Jonatana, że nie umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Tedy się wrócił Saul od Filistynów, a Filistynowie odeszli na miejsce swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'A Saul otrzymawszy królestwo nad Izraelem, walczył przeciwko okolicznym wszystkim nieprzyjaciołom swoim, przeciw Moabitom, i przeciw synom Ammonowym, i przeciw Edomczykom, i przeciw królom Soba, i przeciw Filistynom; a gdzie się kolwiek obrócił, mężnie się sprawował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'Zebrawszy też wojsko, poraził Amalekity, i wyrwał Izraela z ręki tego, który go pustoszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'A miał Saul syny Jonatana, i Jesujego, i Melchisua, a imiona dwóch córek jego: imię pierworodnej Merob, a młodszej Michol;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'A imię żony Saulowej Achinoam, która była córką Achimaasową; a imię Hetmana wojska jego Abner, syn Nera, stryja Saulowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Bo Cys był ojciec Saula, a Ner ojciec Abnera, syn Abijela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'I była wojna wielka z Filistynami po wszystkie dni Saulowe. Przetoż, gdziekolwiek widział Saul jakiego silnego i dzielnego męża, przyjmował go do siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'I rzekł Samuel do Saula: Posłał mię Pan, abym cię pomazał za króla nad ludem jego Izraelskim, przetoż teraz posłuchaj głosu słów Pańskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Tak mówi Pan zastępów: Wspomniałem na to, co uczynił Amalek Izraelowi, jako się nań zasadził na drodze gdy wychodził z Egiptu. Przetoż idź, a pobij Amaleka, i wytrać jako przeklęte wszystko, co ma; nie folguj mu, ale wybij od męża aż do niewiasty, od małego aż do ssącego, od wołu aż do owcy, od wielbłąda aż do osła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'A tak Saul zebrawszy lud, policzył go w Telaim, dwa kroć sto tysięcy pieszych, a dziesięć tysięcy mężów z Juda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'A gdy przyciągnął Saul aż do miasta Amalek, aby zwiódł bitwę nad potokiem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'Rzekł Saul do Cynejczyka: Idźcie, odstąpcie, a wynijdźcie z pośrodku Amalekitów, abym was nie wytracił z nimi; boś ty uczynił miłosierdzie ze wszystkimi syny Izraelskimi, gdy szli z Egiptu. A tak odstąpił Cynejczyk z pośrodku Amalekitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'I poraził Saul Amaleka, od Hewila, którędy chodzą do Sur, które jest przeciw Egiptowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'I pojmał Agaga, króla Amalekitów, żywego, a wszystek lud pobił ostrzem miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'A przepuścił Saul i lud jego Agagowi, co najlepszym owcom, i wołom, i bydłu tłustemu, i baranom, i wszystkiemu, co było najlepszego, a nie chcieli go wygubić; tylko cokolwiek było nikczemnego i podłego, to wygubili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Przetoż stało się słowo Pańskie do Samuela, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Żal mi, żem postanowił Saula za króla; albowiem odwrócił się odemnie, a słowa mego nie wypełnił, i rozgniewał się bardzo Samuel, i wołał do Pana przez całą noc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Wstawszy tedy Samuel, szedł przeciwko Saulowi rano; bo dano znać Samuelowi, mówiąc: Przyszedł Saul do Karmelu, tamże wystawił sobie pamiątkę zwycięstwa; a obróciwszy się poszedł, i przyszedł do Galgal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'A gdy przyszedł Samuel do Saula, rzekł mu Saul: Błogosławionyś ty od Pana, wypełniłem słowo Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Ale Samuel rzekł: A to co za wrzask trzód w uszach moich, i co za ryk wołów, który ja słyszę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'I odpowiedział Saul; Od Amalekitów przygnano je; albowiem lud przepuścił co najlepszym owcom, i wołom aby je ofiarował Panu, Bogu twemu, a ostatekieśmy wytracili jako przeklęte.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Tedy rzekł Samuel do Saula: Dopuść, a powiem ci, co mówił Pan do mnie w nocy; a on mu rzekł: Powiedz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'I rzekł mu Samuel: Izali, gdyś był mały w oczach twoich, nie stałeś się głową pokoleń Izraelskich, i nie pomazał cię Pan za króla nad Izraelem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'I posłał cię Pan w tę drogę, i rzekł: Idź, a wytrać Amalekity jako przklęte grzeszniki, i walcz przeciwko nim, ażbyś je do szczętu wytracił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'Przeczżeś tedy nie usłuchał głosu Pańskiego, aleś się udał za korzyścią, i uczyniłeś złe przed oczyma Pańskiemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Tedy odpowiedział Saul Samuelowi: I owszem usłuchałem głosu Pańskiego, a szedłem drogą, którą mię posłał Pan, i przywiodłem Agaga, króla Amalekitskiego, a Amalekity wytraciłem jako przeklęte.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Ale lud pobrał z korzyści owce i woły co przedniejsze z przeklęstwa, aby je ofiarował Panu, Bogu twemu, w Galgal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'I rzekł Samuel: Izali się tak kocha Pan w całopaleniach i w ofiarach, jako gdy kto słucha głosu Pańskiego? oto, posłuszeństwo lepsze jest niżeli ofiara, a słuchać lepiej jest, niż ofiarować tłustość baranów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Bo przeciwić się jest jako grzech czarowania, a przestąpić przykazanie jest jako bałwochwalstwo i obrazy; przetoż iżeś odrzucił słowo Pańskie, tedy cię też odrzucił Pan, abyś nie był królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Tedy rzekł Saul do Samuela: Zgrzeszyłem, żem przestąpił rozkazanie Pańskie i słowa twoje, gdyżem się bał ludu, i usłuchałem głosu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'A teraz znieś proszę grzech mój, a wróć się ze mną, abym się pokłonił Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'I rzekł Samuel do Saula: Nie wrócę się z tobą; gdyżeś odrzucił słowo Pańskie, ciebie też odrzucił Pan, abyś nie był królem nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'A gdy się odwrócił Samuel, żeby odszedł, uchwycił skrzydło płaszcza jego, i oderwało się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'Tedy mu rzekł Samuel: Oderwał Pan królestwo Izraelskie dzisiaj od ciebie, i dał je bliźniemu twemu, lepszemu niżeś ty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'A zaisteć Mocarz Izraelski nie skłamie, ani będzie żałował; bo nie jest człowiekiem, aby miał żałować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'A on rzekł: Zgrzeszyłem; wszakże uczcij mię proszę przed starszymi ludu mego, i przed Izraelem, a wróć się zemną, abym się pokłonił Panu, Bogu twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'Wróciwszy się tedy Samuel szedł za Saulem, i pokłonił się Saul Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'I rzekł Samuel: Przywiedźcie do mnie Agaga, króla Amalekitskiego; i szedł do niego Agag poważnie, i rzekł Agag: Zaiste uszedłem gorzkości śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Ale rzekł Samuel: Jako osierocił niewiasty miecz twój, tak osierocona będzie nad inne niewiasty matka twoja. I rozsiekał w kęsy Samuel Agaga przed obliczem Pańskiem w Galgal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'Potem odszedł Samuel do Ramaty, a Saul szedł do domu swego, do Gabaa Saulowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'A już potem więcej Samuel nie widział Saula, aż do dnia śmierci swojej: wszakże żałował Samuel Saula, a Pan też żałował, że uczynił królem Saula nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'Tedy rzekł Pan do Samuela: I pókiż ty będziesz żałował Saula, gdyżem go Ja odrzucił, aby nie królował nad Izraelem? Napełnij róg twój oliwą, a pójdź, poślę cię do Isajego Betlehemczyka; bom tam sobie upatrzył między syny jego króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'I rzekł Samuel: Jakoż mam iść? Bo usłyszy Saul, i zabije mię. I odpowiedział Pan: Weźmij z sobą jałowicę z stada, i rzeczesz: Przyszedłem, abym ofiarował Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'I wezwiesz Isajego na ofiarę, a Ja tobie oznajmię, co masz czynić; i pomażesz mi tego, o którym ci powiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'I uczynił Samuel, jako mu powiedział Pan, a przyszedł do Betlehem; a ulękłszy się starsi miasta, zabieżeli mu, i mówili: Spokojneli jest przyjście twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'I rzekł: Spokojne; przyszedłem, abym ofiarował Panu. Poświęćcież się, a pójdźcie ze mną na ofiarę. I poświęcił Isajego, i syny jego, a wezwał ich na ofiarę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'A gdy przyszli, ujrzał Elijaba, i rzekł: Zaiste ten jest przed Panem pomazaniec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Lecz rzekł Pan do Samuela: Nie patrz na urodę jego, ani na wysokość wzrostu jego, gdyżem go odrzucił. Albowiem Ja nie patrzę na to, na co patrzy człowiek; bo człowiek patrzy na to, co jest przed oczyma, ale Pan patrzy na serce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Zawołał tedy Isaj Abinadaba, i kazał mu iść przed Samuela; który rzekł: I tego nie obrał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'Potem kazał przyjść Isaj Sammie, a on rzekł: I tego nie obrał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Tedy kazał przyjść Isaj siedmiu synom swoim przed Samuela. I rzekł Samuel do Isajego: Nie obrał Pan i tych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Potem rzekł Samuel do Isajego: Wszyscyż to już synowie? Odpowiedział: Jeszcze został najmłodszy, który pasie owce. Tedy rzekł Samuel do Isajego: Poślijże, a przywiedź go; boć nie usiądziemy, aż on tu przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'A tak posłał i przywiódł go; a on był lisowaty, i wdzięcznych oczu, a piękny na wejrzeniu. Tedy rzekł Pan: Wstań, a pomaż go, boć ten jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Wziąwszy tedy Samuel róg z oliwą, pomazał go w pośród braci jego. I został Duch Pański nad Dawidem od onegoż dnia, i na potem. Zatem Samuel wstał, i poszedł do Ramaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'A Duch Pański odstąpił od Saula, i trwożył go duch zły od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'I rzekli słudzy Saulowi do niego: Oto teraz Duch Boży zły trwoży cię:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Niech rozkaże Pan nasz, a słudzy twoi, którzy są przed tobą, poszukają męża, coby umiał grać na harfie, że gdy cię napadnie Duch Boży zły, zagra ręką swą, a ulżyć się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'Rzekł tedy Saul do sług swoich: Upatrzcie mi proszę męża, coby dobrze grać umiał, a przywiedźcie do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'I odpowiedział jeden z sług, i rzekł: Otom widział syna Isajego Betlehemczyka, który umie grać, a jest człowiek mężny, i rycerski, i sprawny, i gładki, a Pan jest z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Posłał tedy Saul posły do Isajego, mówiąc: Poślij do mnie Dawida, syna twego, który jest przy stadzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Tedy wziąwszy Isaj osła, chleb, i flaszkę wina, wziąwszy i koziołka jednego z stada, posłał przez Dawida, syna swego, Saulowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'A gdy przyszedł Dawid do Saula, stanął przed nim; a rozmiłował się go bardzo, i był u niego za wyrostka broń noszącego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'I posłał Saul do Isajego, mówiąc: Niech stoi proszę Dawid przedemną; bo znalazł łaskę w oczach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'I bywało, gdy przychodził Duch Boży na Saula, że wziąwszy Dawid harfę, grał ręką swą; tedy Saul miał ulżenie, i lepiej się miał, bo odchodził od niego on duch zły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Tedy zebrali Filistynowie wojska swe, aby walczyli, a zeszli się u Sochot, które jest w Judzie, i położyli się obozem między Sochotem i między Asekiem na granicach Domim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'A Saul i mężowie Izraelscy zebrali się, i położyli się obozem w dolinie Ela, i uszykowali wojsko przeciw Filistynom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'A Filistynowie stali na górze z jednej strony, ale Izraelczycy stali na górze z drugiej strony; a dolina była między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'I wyszedł mąż między nie z obozu Filistyńskiego imieniem Golijat z Get, wzwyż na sześciu łokci i na piędzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'A przyłbica miedziana była na głowie jego, a w karacenę łuszczastą ubierał się, a waga karaceny pięć tysięcy syklów miedzi ważyła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'Nadto nakolanki miedziane miał na nogach swoich, i tarcz miedzianą między ramionami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'A oszczepisko oszczepu jego jako nawój tkacki, a grot oszczepu jego miał sześć set syklów żelaza, a niosący tarcz jego szedł przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'I stanąwszy wołał do hufów Izraelskich, i mówił im: Nacoście wyciągnęli z wojskiem ku potykaniu? izażem ja nie jest Filistyńczyk, a wy słudzy Saulowi? Obieżcież między sobą męża, a niech mi się stawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Będzieli się mógł potkać ze mną, a zabije mię, będziemy waszymi niewolnikami; lecz jeźli go ja przemogę, i zabiję go, wy będziecie naszymi niewolnikami, i służyć nam będziecie. Nadto rzekł Filistyńczyk:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Jam dziś urągał hufom Izraelskim; dajcie mi męża, a niech czyni ze mną pojedynkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'A usłyszawszy Saul i wszystek Izrael te słowa Filistyńczyka, ulękli się, i strwożyli się bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, '(A Dawid był synem męża Efratejczyka z Betlehem Juda, którego imię Isaj, który miał ośm synów, a ten był za dni Saulowych stary i podeszły w leciech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'I poszli trzej synowie Isajego starsi za Saulem na wojnę; a imiona trzech synów jego, którzy poszli na wojnę, są te: Elijab pierworodny, a wtóry po nim Abinadab, a trzeci Samma;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'Lecz Dawid był najmłodszy; a tak trzej najstarsi poszli byli za Saulem.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'Dawid tedy odchodził i wracał się od Saula, aby pasł trzody ojca swego w Betlehem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'Ale Filistyńczyk wychadzał wstawając rano i wieczór, i stawał przez czterdzieści dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'I rzekł Isaj do Dawida, syna swego: Weźmij teraz braciom swym to efa prażma, i dziesięcioro chleba tego, a bież do obozu do braci swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'A tych dziesięć młodych serów doniesiesz rotmistrzowi; a bracią swą nawiedziwszy dowiesz się, jako się mają, i zastawę ich wydźwigniesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'A Saul, i oni, i wszyscy synowie Izraelscy leżeli w dolinie Ela, walcząc przeciwko Filistynom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'Wstawszy tedy Dawid rano na świtaniu, a poruczywszy trzodę stróżowi, wziął to na się, i szedł, jako mu był rozkazał Isaj, i przyszedł do obozu; a wojsko wyszło było do szyku, i okrzyk uczyniło ku potykaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'A już byli uszykowali Izraelczycy i Filistynowie wojsko przeciwko wojsku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'Przetoż zostawiwszy Dawid to, co przyniósł, i złożywszy to z siebie pod rękę stróża sprzętu żołnierskiego, bieżał do wojska, a przyszedłszy przywitał się z bracią swoją w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'A gdy rozmawiał z nimi, oto mąż imieniem Golijat, Filistyńczyk z Get, występował między nie z wojska Filistyńskiego, i mówił oneż słowa, co słyszał i Dawid.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'A wszyscy synowie Izraelscy ujrzawszy onego męża, uciekali od oblicza jego, i bali się bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'I mówili mężowie Izraelscy: A widzieliżeście tego męża, który wyszedł? Bo wyszedł, aby urągał Izraelowi, ale ktoby go zabił, ubogaci go król bogactwy wielkiemi, i córkę mu swoję da, a dom ojca jego uczyni wolnym w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'Tedy Dawid rzekł do mężów, którzy z nim stali, mówiąc: Co dadzą mężowi, któryby zabił tego Filistyńczyka, a odjął pohańbienie od Izraela? Bo cóż to za Filistyńczyk nieobrzezany, że urąga wojskom Boga żyjącego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'I powiedział mu lud oneż słowa, mówiąc: To dadzą mężowi, który go zabije.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'A gdy usłyszał Elijab, brat jego starszy, co mówił z onymi mężami, zapalił się gniewem Elijab na Dawida, i rzekł: Po coś tu przyszedł, a komuś poruczył onę trochę owiec na puszczy? znam ci ja pychę twoję, i złość serca twego, żeś przyszedł, abyś się przypatrywał bitwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'Tedy rzekł Dawid: Cóżem teraz uczynił? Wszakiem tu na rozkazanie przyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'I odwrócił się od niego ku drugiemu, i pytał się jako i przedtem; a odpowiedział mu lud tak jako i pierwej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'I usłyszano słowa, które mówił Dawid, i opowiedziano je Saulowi, którego Saul wziął do siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'I mówił Dawid do Saula: Niech niczyje serce nie upada dla tego; sługa twój pójdzie, a będzie się bił z tym Filistynem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'Ale Saul rzekł do Dawida: Nie możesz ty iść przeciwko temu Filistynowi, abyś się z nim potykał, boś jest dzieciną, a on jest mężem walecznym od młodości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'I odpowiedział Dawid Saulowi: Pasał sługa twój trzodę ojca swego, a gdy przychodził lew, i niedźwiedź, a porywał barana z stada,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'Tedym go gonił, i biłem go, i wydzierałem z paszczęki jego; a gdy się rzucał na mię, ułapiwszy go za gardło jego, tłukłem go, i zabijałem go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'I lwa i niedźwiedzia zabił sługa twój; tedyć też będzie i ten Filistyńczyk nieobrzezany, jako jeden z tych, gdyż urągał wojskom Boga żyjącego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Nadto rzekł Dawid: Pan, który mię wyrwał z mocy lwa, i z mocy niedźwiedzia, tenże mię wyrwie z rąk Filistyna tego. Tedy rzekł Saul do Dawida: Idź, a Pan niech będzie z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'I ubrał Saul Dawida w szaty swe, i włożył przyłbicę miedzianą na głowę jego, a oblukł go w pancerz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Przypasał też Dawid miecz jego na szaty swoje, i kosztował, jeźliby mógł chodzić (bo przedtem tego nie doświadczał). Tedy rzekł Dawid do Saula: Nie mogę w tem chodzić, bom temu nie przywykł. I złożył to Dawid z siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'Ale wziął kij swój w rękę swoję, i obrał sobie pięć gładkich kamieni z potoku, i włożył je do naczynia pasterskiego, które miał, to jest do torby, a procę swoję niósł w rękach swoich, i przybliżył się ku Filistynowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Szedł też Filistyńczyk, postępując i przybliżając się ku Dawidowi, i wyrostek, który niósł tarcz, przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'A gdy spojrzał Filistyńczyk i obaczył Dawida, lekce go sobie poważył, przeto, że był dzieciną, a lisowatym i pięknym na wejrzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'Rzekł tedy Filistyńczyk do Dawida: Izalim ja pies, iż ty idziesz na mię z kijem? I przeklinał Filistyńczyk Dawida przez bogi swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'Nadto rzekł Filistyńczyk do Dawida: Pójdź do mnie, a dam ciało twoje ptastwu powietrznemu i bestyjom polnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Tedy rzekł Dawid do Filistyna: Ty idziesz do mnie z mieczem i z oszczepem, i z tarczą, a ja idę do ciebie w imieniu Pana zastępów, Boga wojsk Izraelskich, któremuś urągał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Dziś cię poda Pan w ręce moje, a zabiję cię, i odejmę głowę twoję od ciebie, a dam trupy wojska Filistyńskiego ptastwu powietrznemu, i bestyjom ziemskim; a pozna wszystka ziemia, że jest Bóg w Izraelu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'I dozna wszystko to zgromadzenie, że nie mieczem, ani oszczepem wybawia Pan, gdyż Pańska jest walka, a poda was w ręce nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'I stało się, gdy powstał Filistyńczyk, i szedł, a przybliżał się przeciwko Dawidowi, że pospieszył i Dawid, a bieżał na spotkanie przeciwko Filistynowi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'A ściągnąwszy Dawid rękę swą do torby, wyjął z niej kamień, i cisnął z procy, a ugodził Filistyńczyka w czoło jego, tak iż utknął kamień w czole jego, i padł twarzą swą na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'A tak przemógł Dawid Filistyńczyka procą i kamieniem, a uderzywszy Filistyńczyka, zabił go, choć miecza nie miał Dawid w ręku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'A przybieżawszy Dawid, stanął nad Filistyńczykiem, i wziął miecz jego, i dobył go z pochwy jego, i zabił go, i uciął nim głowę jego. A gdy ujrzeli Filistynowie, iż umarł mocarz ich, uciekli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Powstawszy tedy mężowie Izraelscy i Judzcy, okrzyk uczynili i gonili Filistyny, aż kędy chodzą do doliny, i aż do bram Akkaronu, i padali ranni Filistynowie po drodze Saraim aż do Get i aż do Akkaronu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'A wróciwszy się synowie Izraelscy z pogoni Filistynów, rozchwycili obóz ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'Potem wziąwszy Dawid głowę onego Filistyńczyka, przyniósł ją do Jeruzalemu, a zbroję jego włożył do namiotu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'A gdy widział Saul Dawida, wychodzącego przeciw Filistynowi, mówił do Abnera, hetmana wojska swego: Czyim jest synem ten młodzieniec? Abnerze! I odpowiedział Abner: Jako żywa dusza twoja, królu, żeć niewiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'Tedy rzekł król: Pytaj, czyim jest synem ten młodzieniec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'A gdy się wracał Dawid, zabiwszy Filistyńczyka, tedy go wziął Abner, i przywiódł go przed Saula, a Dawid miał głowę Filistynowę w rękach swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'I rzekł do niego Saul: Czyjeś ty syn, młodzieńcze? I odpowiedział Dawid: Jestem syn sługi twego Isajego Betlehemczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'I stało się, gdy przestał mówić do Saula, że dusza Jonatanowa spoiła się z duszą Dwidową, i umiłował go Jonatan, jako duszę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'I wziął go Saul dnia onego, ani mu dopuścił, żeby się wracał do domu ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'A tak uczynił Jonatan z Dawidem przymierze, bo go miłował jak duszę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'A zdjawszy z siebie Jonatan płaszcz, który miał na sobie, dał go Dawidowi, i szaty swe, aż do miecza swego, i aż do pasa swego rycerskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'I wychadzał Dawid do wszystkiego, do czego go kolwiek posyłał Saul, a roztropnie się sprawował; i przełożył go Saul nad rycerstwem, i był wdzięcznym w oczach wszystkiego ludu, także i w oczach sług Saulowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'I stało się, gdy się wracali, a Dawid się też wracał od porażki Filistynów, że wyszły niewiasty ze wszystkich miast Izraelskich, śpiewając i grając przeciwko Saulowi królowi z bębnami, z weselem, i z gęślami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'A śpiewając na przemiany one niewiasty, grały i mówiły: Poraził Saul swój tysiąc, ale Dawid swoich dziesięć tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'I rozgniewał się Saul bardzo, bo się nie podobały w oczach jego te słowa; i rzekł: Przywłaszczyli Dawidowi dziesięć tysięcy, a mnie przywłaszczyli tysiąc: a czegoż mu niedostaje, jedno królestwa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'Przetoż Saul krzywo patrzył na Dawida od onegoż dnia i na potem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'I stało się drugiego dnia, że przypadł Duch Boży zły na Saula, i prorokował w pośrodku domu, a Dawid grał ręką swoją dnia onego, jako i przedtem, a Saul miał włócznią w ręce swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'I cisnął Saul włócznią, mówiąc: Przebiję Dawida aż ku ścianie; ale się uchylił Dawid przed nim po dwa kroć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'I bał się Saul Dawida, przeto że Pan był z nim, a od Saula odstąpił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'I odprawił go Saul od siebie, a uczynił go hetmanem nad tysiącem, i wychadzał a wchadzał przed ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'Owa Dawid we wszystkich drogach swych roztropnie się sprawował; bo Pan był z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'Co gdy widział Saul, iż tak bardzo roztropnie sobie poczynał, bał się go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Ale wszystek Izrael i Juda miłował Dawida; bo on wychadzał i wchadzał przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'I rzekł Saul do Dawida: Oto, córkę moję starszą Merob dam ci za żonę, jedno bądź mężem mocnym, i odprawuj wojny Pańskie; bo tak Saul sobie mówił: Niech nie będzie ręka moja na nim, ale niech będzie na nim ręka Filistynów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'Tedy rzekł Dawid do Saula: Któżem ja? albo co za stan mój, albo co za dom ojca mego w Izraelu, żebym był zięciem królewskim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'I stało się, gdy przyszedł czas, którego miała być dana Merob, córka Saulowa, Dawidowi, że ona dana jest Adryjelowi Meholatyckiemu za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'Ale się rozmiłowała Michol, córka Saulowa, Dawida; co gdy powiedziano Saulowi, miło mu to było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'I rzekł Saul: Dam mu ją, żeby mu była sidłem, a żeby była na nim ręka Filistynów. Przetoż rzekł Saul do Dawida: Po drugie będziesz zięciem moim dzisiaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'Tedy rozkazał Saul sługom swoim: Rzeczcie do Dawida potajemnie, mówiąc: Oto, upodobał cię sobie król, i wszyscy słudzy jego miłują cię, a tak teraz bądź zięciem królewskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'A gdy mówili słudzy Saulowi w uszy Dawidowe te słowa, odpowiedział Dawid: Czy się wam mała rzecz widzi, być zięciem królewskim, gdyżem ja jest mężem ubogim i podłym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'Tedy słudzy Saulowi oznajmili mu, mówiąc: Tak powiedział Dawid.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'I rzekł Saul: Tak powiedzcie Dawidowi: Nie dbać król o wiano, tylko chce mieć sto nieobrzezek Filistyńskich, aby się stała pomsta nad nieprzyjaciołmi królewskimi; bo Saul myślił, jakoby Dawida podać w ręce Filistynom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'Tedy słudzy jego powiedzieli te słowa Dawidowi; i spodobało się to Dawidowi, aby został zięciem królewskim; a jeszcze się nie były wypełniły dni one.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'Wstał tedy Dawid, i poszedł, on i mężowie jego, i zabił z Filistynów dwieście mężów, i przyniósł Dawid nieobrzezki ich, i oddano je spełna królowi, aby był zięciem królewskim. A tak dał mu Saul Michol, córkę swą za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'A widząc Saul, i bacząc, że Pan był z Dawidem, a iż Michol, córka jego, miłowała go,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'Tem więcej Saul obawiał się Dawida, i stał się Saul nieprzyjacielem Dawidowi po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'I wpadały książęta Filistyńskie do ziemi. A kiedykolwiek wpadały, roztropniej sobie poczynał Dawid nad wszystkie sługi Saulowe; przetoż sławne było imię jego bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Tedy mówił Saul do Jonatana, syna swego, i do wszystkich sług swoich, aby zabili Dawida; ale Jonatan syn Saula, kochał się w Dawidzie bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'I oznajmił to Jonatan Dawidowi, mówiąc: Saul, ojciec mój, myśli cię zabić; przetoż teraz strzeż się proszę aż do zaranku, a zataisz się, i skryjesz się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'A ja wynijdę, i stanę podle ojca mego na polu, gdzie ty będziesz, i będę mówił o tobie z ojcem moim, a cokolwiek pobaczę, toć oznajmię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'A tak mówił Jonatan o Dawidzie dobrze do Saula, ojca swego, i rzekł do niego: Niech nie grzeszy król przeciwko słudze swemu Dawidowi: boć nic nie winien, owszem sprawy jego byłyć bardzo pożyteczne;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Gdyż położył duszę swą w ręce swej, i zabił Filistyńczyka, i uczynił Pan wybawienie wielkie wszystkiemu Izraelowi. Coś widział, i uradowałeś się. Przeczżebyś tedy miał grzeszyć przeciw krwi niewinnej, chcąc zabić Dawida bez przyczyny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'I usłuchał Saul słów Jonatanowych, i przysiągł Saul: Jako żywy Pan, że nie umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'A tak przyzwał Jonatan Dawida, i opowiedział mu Jonatan wszystkie one słowa; i przywiódł Jonatan Dawida do Saula, i był przed nim, jako i przedtem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'I wszczęła się znowu wojna, a ciągnął Dawid, i walczył przeciwko Filistynom, i poraził je porażką wielką, i uciekli przed obliczem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'Wtem Duch Pański zły przypadł na Saula, który w domu swym siedział, mając włócznią swoję w ręce swej, a Dawid grał ręką swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'I myślił Saul przebić Dawida włócznią aż ku ścianie: ale się uchylił przed Saulem, i uderzyła włócznia w ścianę, a Dawid uciekł, i uszedł onej nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Potem posłał Saul posły do domu Dawidowego, aby nań strzegli, i zabili go rano. I oznajmiła to Dawidowi Michol, żona jego, mówiąc: Jeźliże nie ochronisz duszy twojej tej nocy, jutro zabity będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'Przetoż spuściła Michol Dawida oknem, który uszedłszy uciekł, i zachowany jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'A wziąwszy Michol obraz, położyła na łożu, a wezgłówko z koziej skóry położyła pod głowę jego, i przykryła szatą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'Tedy posłał Saul posły, aby porwali Dawida; ale rzekła: Choruje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Znowu posłał Saul posły, aby oglądali Dawida, mówiąc: Przynieście go na łożu do mnie, abym go zabił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'A gdy przyszli posłowie, oto obraz na łożu, a wezgłówko z koziej skóry pod głowami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'I rzekł Saul do Michol: Czemuś mię tak oszukała, a wypuściłaś nieprzyjaciela mego, aby uszedł? Tedy rzekła Michol Saulowi: Bo mi mówił, puść mię, inaczej zabiję cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'A tak Dawid uciekłszy uszedł, a przyszedł do Samuela, do Ramaty, i oznajmił mu wszystko, co mu czynił Saul. Poszedł tedy on i Samuel, a mieszkali w Najot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'I oznajmiono Saulowi, mówiąc: Oto Dawid jest w Najot w Ramacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Tedy posłał Saul posły, aby pojmali Dawida; którzy gdy ujrzeli gromadę proroków prorokujących, i Samuela stojącego, a przełożonego nad nimi, przyszedł i na posły Saulowe Duch Boży, a prorokowali i oni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Co gdy oznajmiono Saulowi, posłał inne posły, a prorokowali oni. Znowu tedy Saul posłał i trzecie posły, lecz prorokowali i ci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Potem szedł i sam do Ramaty, i przyszedł aż do studni wielkiej, która jest w Sokot, i pytał się a mówił: Gdzie jest Samuel i Dawid? i powiedziano mu: Oto są w Najot w Ramacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'I szedł tam do Najot w Ramacie, a przyszedł też nań Duch Boży; a tak idąc dalej prorokował, aż przyszedł do Najot w Ramacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'I zewlekł też sam szaty swoje, a prorokował i on przed Samuelem, a padłszy leżał nagim przez on cały dzień i przez całą noc; stądże weszło w przypowieść: Azaż i Saul między prorokami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'Ale Dawid uciekłszy z Najotu, który jest w Ramacie, przyszedł, i mówił przed Jonatanem, cóżem uczynił? co za nieprawość moja? i co za grzech mój przeciw ojcu twemu, że szuka duszy mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'Który mu odpowiedział: Boże uchowaj! nie umrzesz; oto nie czyni ojciec mój nic wielkiego albo małego, aż mi pierwej oznajmi; azażby taić miał ojciec mój przedemną i tego? Nie uczyni tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'A nadto przysiągł Dawid, rzekłszy: Wie zaiste ojciec twój, żem znalazł łaskę w oczach twoich, i myśli: Niech o tem niewie Jonatan, by się snać nie frasował; i owszem jako żywy Pan, żywa i dusza twoja, że tylko krok jeden jest między mną, i między śmiercią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'I odpowiedział Jonatan Dawidowi: Co mi kolwiek rzecze dusza twoja, uczynięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'Tedy rzekł Dawid do Jonatana: Oto, nów miesiąca jutro, a jam zwykł siadać z królem przy stole; puść mię tedy, że się skryję na polu aż do wieczora trzeciego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'A jeźliby się pilnie pytał o mnie ojciec twój, rzeczesz: Prosił mię bardzo Dawid, aby szedł do Betlehem, miasta swego; bo tam ofiarę uroczystą ma sprawować wszystka rodzina jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Jeźli tak rzecze: Dobrze, pokój będzie słudze twemu; ale jeźli się rozgniewa, wiedz, iż się dopełniła złość jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Przetoż uczyń miłosierdzie nad sługą twoim, gdyżeś w przymierze Pańskie przywiódł z sobą sługę twego; a jeźli we mnie jest nieprawość, ty mię zabij; a do ojca twego przeczbyś mię miał wodzić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'I rzekł Jonatan: Boże cię tego uchowaj; bo jeźli się pewnie dowiem, że się dopełniła złość ojca mego, aby przyszła przeciw tobie, izalibym ci tego nie oznajmił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'I rzekł Dawid do Jonatana: Któż mi oznajmi, jeźliżeć co odpowie ojciec twój przykrego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Odpowiedział Jonatan Dawidowi: Pójdź, a wynijdźmy na pole. I wyszli obaj na pole.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'Tedy rzekł Jonatan do Dawida; Pan, Bóg Izraelski, (skoro się wywiem o woli ojca mego o tym czasie jutro, albo dnia trzeciego, a będzie co dobrego o Dawidzie, a jeźli zarazem nie poślę do ciebie, i nie oznajmięć,)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'To niech uczyni Pan, Bóg Izraelski, mówię, Jonatanowi, i to niech przyczyni. A jeźliże będzie chciał ojciec mój przywieść złe na cię, i toć objawię, i puszczę cię, abyś szedł w pokoju, a niech będzie Pan z tobą, jako był z ojcem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Także i ty, będęli żyw, i ty mówię uczynisz ze mną miłosierdzie Pańskie, a choćbym i umarł,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'Przecię nie oddalisz miłosierdzia twego od domu mego aż na wieki, ani gdy wykorzeni Pan nieprzyjacioły Dawidowe wszystkie z ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'I uczynił Jonatan przymierze z domem Dawidowym, mówiąc: Niech tego szuka Pan z ręki nieprzyjaciół Dawidowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'Nadto jeszcze Jonatan przysiągł Dawidowi przez miłość, którą go miłował; bo jako miłował duszę swoję, tak go też miłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'I rzekł do niego Jonatan: Jutro nów miesiąca, a będą się pytać o tobie, ponieważ próżne będzie miejsce twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'Przetoż przez trzy dni będziesz się ukrywał, i zstąpisz prędko, a przyjdziesz na miejsce, gdzieś się był ukrył, gdy była sprawa o tobie, a będziesz siedział u kamienia Ezel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'A ja wystrzelę trzy strzały po bok jego, zmierzając sobie do celu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'A potem poślę chłopca, mówiąc mu: Idź, najdzij strzały. A jeźli rzekę chłopcu: Owo strzały za tobą sam bliżej, przynieś je, tedy przyjdź; bo masz pokój, i nie stanieć się nic złego, jako żywy Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Ale jeźliż rzekę chłopcu: Oto strzały przed tobą tam dalej; idź, bo cię wypuścił Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'A tego, o czemeśmy mówili ja i ty, tego Pan świadkiem będzie między mną a między tobą aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'A tak skrył się Dawid w polu. A gdy przyszedł nów miesiąca, siadł król do stołu, aby jadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'A gdy usiadł król na stolicy swojej według zwyczaju, na stolicy przy ścianie, powstał Jonatan; i siadł Abner podle Saula, a zostało próżne miejsce Dawidowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Lecz nie rzekł Saul nic onego dnia, bo myślał: Przydało mu się podobno coś, lub jest czystym lub nieczystym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'A gdy było nazajutrz dnia wtórego po nowiu miesiąca, było zaś próżne miejsce Dawidowe. I rzekł Saul do Jonatana, syna swego: Czemuż nie przyszedł syn Isajego, ani wczoraj, ani dziś do stołu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'Odpowiedział Jonatan Saulowi: Usilnie mię prosił Dawid, aby szedł do Betlehem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'I mówił: Puść mię proszę, bo sprawuje ofiarę rodzina nasza w mieście; tamże mię wezwał brat mój. A tak teraz jeźlim znalazł łaskę w oczach twoich, pójdę proszę, i oglądam bracią moję; dla tegoć nie przyszedł do stołu królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'I zapalił się gniewem Saul na Jonatana, i rzekł mu: Synu złośliwy, a upornej matki, azaż nie wiem, iżeś sobie obrał syna Isajego, ku zelżywości twojej, i ku pohańbieniu i sromocie matki twojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Bo po wszystkie dni, których syn Isajego będzie żył na ziemi, nie będziesz umocniony, ty i królestwo twoje; a tak teraz poślij, a przywiedź go do mnie, bo jest godzien śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Tedy odpowiedział Jonatan Saulowi, ojcu swemu, i rzekł do niego: Przecz ma umrzeć? cóż uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'I cisnął Saul włócznią na niego, aby go przebił. Tedy poznał Jonatan, że koniecznie ojciec jego umyślił zabić Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'I wstał Jonatan od stołu z wielkim gniewem, i nie jadł dnia wtórego po nowiu miesiąca chleba; bo się zafrasował o Dawida, a iż go zelżył ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'A rano wyszedł Jonatan na pole według czasu postanowionego z Dawidem, i chłopiec mały z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'I rzekł do chłopca swego: Bież, szukaj prędko strzał, które ja wystrzelę. Tedy chłopiec bieżał; a on wystrzelił strzały dalej przedeń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'A gdy przyszedł chłopiec aż na miejsce strzały, którą był wystrzelił Jonatan, zawołał Jonatan za chłopcem, i rzekł: Azaż strzała nie jest za tobą tam dalej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'I wołał Jonatan za chłopcem: Spiesz się co najrychlej, nie stój. Tedy zebrawszy chłopiec Jonatana strzały, przyszedł do pana swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, '(Ale chłopiec nic nie wiedział, tylko Jonatan i Dawid wiedzieli, co się działo.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'I dał Jonatan oręż swój chłopcu, który z nim był, i rzekł mu: Idź, odnieś do miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'A gdy odszedł chłopiec, Dawid wstał od strony południowej, i upadłszy twarzą swoją na ziemię, ukłonił się po trzy kroć, i pocałowawszy jeden drugiego, płakali pospołu; ale Dawid obficiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'I rzekł Jonatan do Dawida: Idź w pokoju; a to, cośmy sobie obaj przysięgli przez imię Pańskie, mówiąc: Pan niech będzie między mną i między tobą, i między nasieniem mojem, i między nasieniem twojem świadkiem aż na wieki, trzymać będziemy. A tak wstawszy Dawid odszedł, a Jonatan wszedł do miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'Potem, przyszedł Dawid do Noby do Achimelecha kapłana, a zlękłszy się Achimelech wyszedł przeciwko Dawidowi, i rzekł mu: Przeczżeś ty sam, a niemasz nikogo z tobą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'I odpowiedzał Dawid Achimelechowi kapłanowi: Rozkazał mi król nieco, i rzekł do mnie: Niech nikt nie wie tego, po co cię posyłam, i com ci zlecił, przetożem sługi zostawił na pewnem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'A tak teraz maszli co przy rękach twoich, aby z pięcioro chleba, daj do ręki mojej, albo cokolwiek znajdziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'I odpowiedział kapłan Dawidowi, i rzekł: Nie mam chleba pospolitego przy ręce mojej, tylko chleb poświęcony; jeźli się tylko wstrzymali słudzy od niewiast.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'Tedy odpowiedział Dawid kapłanowi, i rzekł mu: Zaiste niewiasty oddalone były od nas od wczorajszego i dziś trzeciego dnia, gdym wyszedł; przetoż były naczynia sług święte. Ale jeźli ta droga zmazana jest, wszakże i ta dzisiaj poświęcona będzie w naczyniach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'A tak dał mu kapłan chleby poświęcone; albowiem nie było tam chleba, tylko chleby pokładne, które były odjęte od obliczności Pańskiej, aby położono chleby ciepłe onegoż dnia, którego one odjęte były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'A był tam mąż z sług Saulowych onego dnia, zabawiony przed Panem, którego imię Doeg, Edomczyk, najmożniejszy z pasterzy, które miał Saul.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'I rzekł Dawid do Achimelecha: A niemaszże tu przy ręce swej włóczni, albo miecza? bom ani miecza mego, ani żadnej broni mojej nie wziął w rękę moję, gdyż słowo królewskie przynaglało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Tedy rzekł kapłan: Miecz Golijata Filistyńczyka, któregoś zabił w dolinie Ela, oto jest uwiniony w sukno za efodem; jeźli ten chcesz sobie wziąć, weźmij; bo tu inszego niemasz oprócz tego. I rzekł Dawid: Niemasz podobnego temu, daj mi go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'A tak wstał Dawid, i uciekł dnia onego przed Saulem, i przyszedł do Achisa, króla Getskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'Tedy rzekli słudzy Achisowi do niego: Izali nie ten jest Dawid, król ziemi? Izali nie temu śpiewano w hufcach, mówiąc: Poraził Saul swój tysiąc, a Dawid swoich dziesięć tysięcy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'I złożył Dawid słowa te do serca swego, a bał się bardzo Achisa, króla Getskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'Przetoż zmienił obyczaje swoje przed oczyma ich, a czynił się szalonym w rękach ich, i kreślił na drzwiach bramy, i puszczał śliny na brodę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Tedy rzekł Achis do sług swoich: Otoście widzieli człowieka szalonego, czemużeście go przywiedli do mnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Nie dostawa mi szalonych, żeście przywiedli tego, aby szalał przedemną? tenże ma wnijść do domu mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'Potem wyszedł Dawid stamtąd, i uszedł do jaskini Adullam. Co gdy usłyszeli bracia jego i wszystek dom jego, przyszli tam do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'I zebrali się do niego wszyscy, którzy byli utrapieni, i wszyscy, którzy byli dłużni, i wszyscy, którzykolwiek byli w gorzkości serca, i był nad nimi książęciem, a było z nim około czterech set mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'I poszedł Dawid stamtąd do Masfa Moabskiego, i rzekł do króla Moabskiego: Niech się przeprowadzi proszę ojciec mój, i matka moja, aby mieszkali z wami, aż się dowiem co uczyni Bóg ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'A tak przywiódł je przed króla Moabskiego; i mieszkali z nim po wszystkie dni, których był Dawid na onym zamku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'Rzekł potem Gad prorok do Dawida: Nie mieszkaj więcej na tym zamku; idź, a wróć się do ziemi Judzkiej. Tedy poszedł Dawid, a przyszedł do lasu Haret.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'A usłyszawszy Saul, że się pojawił Dawid, i mężowie, którzy byli z nim, (bo Saul mieszkał w Gabaa pod gajem w Ramacie, mając włócznią swoję w rękach swych, a wszyscy słudzy jego stali przed nim).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'Rzekł tedy Saul do sług swych, którzy stali przed nim: Słuchajcie proszę synowie Jemini: Izaż wam wszystkim da syn Isajego role i winnice, a wszystkich was poczyni półkownikami i rotmistrzami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Żeście się sprzysięgli wy wszyscy przeciwko mnie, a niemasz ktoby mi objawił? gdyż się zbuntował i syn mój z synem Isajego, a niemasz ktoby się mnie użalił między wami, a oznajmił mi, iż podburzył syn mój sługę mego przeciwko mnie, aby czyhał na mię, jako się to dziś okazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Tedy odpowiedział Doeg Edomczyk, który też stał z sługami Saulowymi, i rzekł: Widziałem syna Isajego, gdy przyszedł do Noby, do Achimelecha, syna Achitobowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'Który się oń radził Pana, i dał mu żywności, dał mu też i miecz Golijata Filistyńczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'A tak posłał król, aby przyzwano Achimelecha, syna Achitobowego, kapłana, i wszystkiego domu ojca jego kapłanów, którzy byli w Nobe. I przyszli oni wszyscy do króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'Tedy rzekł Saul: Słuchaj teraz synu Achitoba; a on rzekł: Owom ja panie mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'I rzekł do niego Saul: Czemuście się sprzysięgli przeciwko mnie, ty i syn Isajego, gdyś mu dał chleb i miecz, a radziłeś się oń Boga, aby powstał przeciwko mnie, czyhając na mię, jako się to dziś okazuje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'I odpowiedział Achimelech królowi, a rzekł: I któż jest tak wierny między wszystkimi sługami twoimi, jako Dawid, który jest i zięciem królewskim i idzie za rozkazaniem twojem, a jest zacnym w domu twoim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Azaż dziś począłem się oń radzić Boga? Uchowaj mię Boże! Niech nie wkłada król na sługę twego nic takiego, ani na wszystek dom ojca mego; bo nie wiedział sługa twój o tem wszystkiem najmniejszej rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'I rzekł król: Śmiercią umrzesz Achimelechu, ty i wszystek dom ojca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'Przytem rzekł król sługom, którzy stali przed nim: Obróćcie się, a pobijcie kapłany Pańskie; bo też ręka ich jest z Dawidem, gdyż wiedząc, że on uciekał, nie oznajmili mi. Ale słudzy królewscy nie chcieli podnieść ręki swej, ani się rzucić na kapłany Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'Przetoż rzekł król do Doega: Obróć się ty, a rzuć się na kapłany. A tak obróciwszy się Doeg Edomczyk, rzucił się na kapłany, i zabił onegoż dnia ośmdziesiąt i pięć mężów, którzy nosili efod lniane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'Nobe też miasto kapłańskie wysiekł ostrzem miecza, od męża aż do niewiasty, od małego aż do ssącego, i woły, i osły, i owce wysiekł ostrzem miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Uszedł tylko syn jeden Achimelecha, syna Achitobowego; a imię jego Abijatar; i uciekł do Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'Tedy oznajmił Abijatar Dawidowi, że pobił Saul kapłany Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'I rzekł Dawid do Abijatara: Wiedziałem onegoż dnia, gdyż tam był Doeg Edomczyk, że pewnie oznajmić miał Saulowi: Jam jest przyczyną śmierci wszystkich dusz domu ojca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Zostańże przy mnie, nie bój się; bo ktoby szukał duszy mojej, będzie szukał duszy twojej; ale ty będziesz schroniony przy mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Tedy powiedziano Dawidowi, mówiąc: Oto, Filistynowie dobywają Ceili, i plondrują gumna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'I radził się Dawid Pana, mówiąc: Mamli iść, a uderzyć na te Filistyny? I odpowiedział Pan Dawidowi: Idź, a porazisz Filistyny, i wybawisz Ceilę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'Tedy rzekli mężowie Dawidowi do niego: Oto my tu w Judzkiej ziemi boimy się, jakoż daleko więcej, jeźli pójdziemy do Ceili przeciw wojskom Filistyńskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'I pytał się jeszcze powtóre Dawid Pana. A odpowiedział mu Pan, mówiąc: Wstawszy idź do Ceili; bo ja dam Filistyny w ręce twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'Poszedł tedy Dawid i mężowie jego do Ceili, i walczył z Filistynami, i zabrał bydła ich, i poraził ich porażką wielką, i wybawił Dawid obywatele Ceili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'I stało się, gdy uciekał Abijatar, syn Achimelecha, do Dawida do Ceili, że się dostał efod w rękę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Potem powiedziano Saulowi, iż Dawid przyszedł do Ceili. Tedy rzekł Saul: Dał go Bóg w ręce moje; bo się zawarł, wszedłszy do miasta, w którem są bramy i zamki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'A tak zebrał Saul wszystek lud, aby szedł na wojnę do Ceili, i obległ Dawida, i męże jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Co gdy wzwiedział Dawid, iż Saul potajemnie przeciw niemu myślał wszystko złe, tedy rzekł do Abijatara kapłana: Włóż na się efod.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'I rzekł Dawid: Panie, Boże Izraelski, za pewne słyszał sługa twój, że Saul chce przyjść do Ceili, aby miasto zburzył dla mnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Wydadząli mnie starsi miasta Ceili w ręce jego? przyjdzieli też Saul, jako słyszał sługa twój? Panie, Boże Izraelski, oznajmij proszę słudze twemu. I odpowiedział Pan: Przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Nadto rzekł Dawid: Wydadząli starsi z Ceili mnie i męże moje w ręce Saulowe? I odpowiedział Pan: Wydadzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Wstał tedy Dawid i mężowie jego około sześciu set mężów, i wyszli z Ceili, a uchodzili kędy mogli. A gdy oznajmiono Saulowi, że uszedł Dawid z Ceili, tedy zaniechał wyciągnienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'I mieszkał Dawid na puszczy w miejscach obronnych, a został na górze w puszczy Zyf. I szukał go Saul po wszystkie dni; lecz nie podał go Bóg w ręce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'A widząc Dawid, że wyszedł Saul, aby szukał duszę jego, został Dawid na puszczy Zyf w lesie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'Wtedy wstał Jonatan, syn Saula, i szedł do Dawida do lasu, i posilił rękę jego w Bogu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'Mówiąc do niego: Nie bój się, bo cię nie znajdzie ręka Saula, ojca mego; a ty będziesz królował nad Izraelem, ja zaś będę wtórym po tobie; wszak i Saul, ojciec mój, wie o tem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'I uczynili obaj z sobą przymierze przed Panem; i został Dawid w lesie, ale Jonatan wrócił się do domu ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Tedy przyszli Zyfejczycy do Saula do Gabaa, powiadając: Azaż Dawid nie kryje się u nas po miejscach obronnych w lesie na pagórku Hachila, który jest po prawej stronie Jesymona?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Przetoż teraz według wszystkiej żądności duszy twojej, królu, zejdź co najrychlej, a my się postaramy, że go wydamy w ręce królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'Tedy rzekł Saul: Błogosławieniście wy od Pana, żeście się mnie użalili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Idźcież proszę, a starajcie się tem pilniej; wywiedzcie się, a wyszpiegujcie to miejsce jego, gdzie się obraca. Kto go tam widział? bo mi powiadano, że sobie bardzo chytrze postępuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Wypatrzcież tedy, a obaczcie wszystkie te miejsca skryte, w których się ukrywa; potem wrócicie się do mnie z czem pewnem, i pójdę z wami; a będzieli w ziemi, tedy go będę szukał po wszystkich tysiącach Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'Wstali tedy, i poszli do Zyf przed Saulem; ale Dawid i mężowie jego byli na puszczy Maon, w polach po prawej stronie Jesymon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'Bo gdy wyszedł Saul, i mężowie jego, szukać go, oznajmiono Dawidowi, który zstąpił z skały, i mieszkał na puszczy Maon. Co usłyszawszy Saul, gonił Dawida aż na puszczę Maon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'I szedł Saul po jednej stronie góry, a Dawid i mężowie jego po drugiej stronie góry. I spieszył się Dawid, aby mógł ujść przed Saulem; bo Saul i lud jego obtaczali Dawida i męże jego, aby je pojmali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'Wtem poseł przybieżał do Saula, mówiąc: Pospiesz się, a pójdź; albowiem Filistynowie wtargnęli w ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Przetoż wrócił się Saul od pogoni za Dawidem, a ciągnął przeciw Filistynom; dla tego nazwali miejsce ono Sela Hammalekot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'A tak wyciągnął stamtąd Dawid, i mieszkał na miejscach obronnych Engaddy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'I stało się, gdy się wrócił Saul z pogoni za Filistynami, powiedziano mu, mówiąc: Oto, Dawid jest na puszczy Engaddy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'Wziąwszy tedy Saul trzy tysiące mężów przebranych z wszystkiego Izraela, poszedł szukać Dawida i mężów jego, po wierzchu skał kóz dzikich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'I przyszedł ku oborom owczym, które były podle drogi, kędy była jaskinia; do której wszedł Saul na potrzebę przyrodzoną, a Dawid i mężowie jego siedzieli po stronach jaskini.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'I rzekli mężowie Dawidowi do niego: Oto dzień, o którym ci powiedział Pan: Oto Ja dawam nieprzyjaciela twego w ręce twoje, a uczynisz mu, jako się będzie podobało w oczach twoich. Wstał tedy Dawid, i urznął po cichu kraj płaszcza Saulowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'I stało się, że uderzyło Dawida serce jego, przeto że urznął kraj płaszcza Saulowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'I rzekł do mężów swoich: Uchowaj mię tego Panie, żebym to uczynić miał panu memu, pomazańcowi Pańskiemu, żebym miał ściągnąć nań rękę moję, ponieważ jest pomazańcem Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'I przełomił Dawid męże swe słowy, a nie dopuścił im powstać przeciwko Saulowi; zatem Saul wstawszy z jaskini, poszedł w drogę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'Potem też Dawid wstał, i wyszedł z jaskini, a zawołał za Saulem, mówiąc: Królu, Panie mój! Tedy się obejrzał Saul nazad, a Dawid schyliwszy się twarzą ku ziemi, pokłonił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'I rzekł Dawid do Saula: Czemuż słuchasz powieści ludzi mówiących: Otóż Dawid szuka twego złego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Oto, dnia tego widzą oczy twoje, że cię był podał Pan w ręce moje w jaskini, i mówiono mi, abym cię zabił; alem ci sfolgował, i rzekłem: Nie ściągnę ręki mojej na pana mego; bo jest pomazańcem Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Oto, ojcze mój, obacz a oglądaj kraj płaszcza twego w ręce mojej, że gdym urzynał kraj płaszcza twego, nie zabiłem cię. Poznaj a obacz, że niemasz w ręce mojej złości i nieprawości, anim zgrzeszył przeciwko tobie: a ty godzisz na duszę moję, abyś mi ją odjął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Niech rozsądzi Pan między mną i między tobą, a niech się zemści Pan krzywdy mojej nad tobą; lecz ręka moja nie będzie na tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Jako mówi przypowieść starodawna: Od niezbożnych wynijdzie niezbożność; przetoż ręka moja nie będzie na tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Za kimże wżdy wyszedł król Izraelski? kogóż gonisz? psa zdechłego? pchłę jednę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'Niechże będzie Pan sędzią, a niech rozsądzi między mną i między tobą, a niech obaczy i rozejmie przą moję, a niech mię wyswobodzi z ręki twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'A gdy przestał Dawid mówić słów tych do Saula, rzekł Saul: A twójże to głos, synu mój Dawidzie? I podniósłszy Saul głos swój, płakał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'I rzekł do Dawida: Sprawiedliwszyś ty niźli ja: bo tyś mnie oddał dobrem, a jam tobie oddał złem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Tyś zaiste okazał dzisiaj, żeś mi uczynił dobre; bo choć mię podał Pan w rękę twoję, przecięś mię nie zabił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'Izaż znalazłszy kto nieprzyjaciela swego, wypuści go na drogę dobrą? niechajżeć Pan dobrem odda za to, coś mi dziś uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'A teraz oto wiem, że zapewne będziesz królował, a ostoi się w ręce twojej królestwo Izraelskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'Przetoż proszę, przysiąż mi przez Pana, że nie wygubisz nasienia mego po mnie, i nie wytracisz imienia mego z domu ojca mego. A tak przysiągł Dawid Saulowi. I odszedł Saul do domu swego, a Dawid i mężowie jego poszli na miejsca obronne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'W tem umarł Samuel. A zebrawszy się wszyscy Izraelczycy, płakali go, i pogrzebli go w domu jego w Ramacie. Tedy wstawszy Dawid, poszedł na puszczę Faran.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'A był niektóry mąż w Maon, który miał majętność na Karmelu; a on mąż był możny bardzo, mając owiec trzy tysiące, a tysiąc kóz; i trafiło się, że strzygł owce swoje na Karmelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'A było imię męża onego Nabal, a imię żony jego Abigail, która niewiasta była mądra, i piękna; ale mąż jej był nieużyty i złych postępków, a był narodu Kalebowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'A usłyszawszy Dawid na puszczy, iż Nabal strzygł owce swoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'Posłał dziesięciu sług, i rzekł im: Idźcie do Karmelu, a przyszedłszy do Nabala, pozdrówcie go imieniem mojem spokojnie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'A mówcie tak: Żyj, a niech będzie tobie pokój, i domowi twemu pokój, i wszystkiemu, co masz, pokój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'A teraz słyszałem, że masz te, coć owce strzygą; a pasterze twoi bywali z nami, niebyliśmy im przykrymi, i nic im nie zginęło po wszystkie dni, których byli w Karmelu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Spytaj sług twoich, a powiedząć. Przetoż niech znajdą słudzy łaskę w oczach twoich, gdyżeśmy w dobry dzień przyszli; daj proszę cokolwiek znajdzie ręka twoja, sługom twoim, i synowi twemu Dawidowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'A tak przyszli słudzy Dawidowi, i mówili do Nabala wszystkie one słowa imieniem Dawidowem, i przestali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'A odpowiadając Nabal sługom Dawidowym, rzekł: Cóż jest Dawid? a co zacz syn Isajego? dziś się namnożyło sług, którzy uciekają od panów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'I wezmęż ja chleb mój, i wodę moję, i mięsa bydła mego, którem pobił dla tych, którzy strzygą owce moje, a dam mężom, których nie znam, skąd są?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'A obróciwszy się słudzy Dawidowi w drogę swoję, wrócili się, i przyszli a powiedzieli mu wszystkie te słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'Tedy rzekł Dawid mężom swym: Przypaszcie każdy miecz swój; przypasał też i Dawid miecz swój, i szło za Dawidem około czterech set mężów, a dwieście zostało przy rzeczach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Ale Abigaili, żonie Nabalowej, oznajmił to jeden czeladnik z sług Nabalowych, mówiąc: Oto przysłał Dawid posły z puszczy, aby błogosławili Panu naszemu, lecz on je sfukał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'A mężowie ci dobrzy nam byli bardzo, i nie przykrzyli się nam; nic nam nie zginęło po wszystkie dni, pókiśmy z nimi chodzili, będąc na polu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'Miasto muru byli nam, tak w nocy jako we dnie, po wszystkie dni, pókiśmy przy nich trzody paśli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Przetoż teraz obacz, a rozmyśl się, co masz czynić; boć już gotowe nieszczęście na pana naszego, i na wszystek dom jego; lecz on jest człowiekiem niezbożnym, że z nim trudno mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Pospieszyła się tedy Abigail, i wzięła dwieście chleba, i dwie łagwi wina, i pięć owiec oprawnych, i pięć miar prażma, i sto wiązanek rodzynków, i dwieście funtów fig, a włożyła to na osły;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'I rzekła sługom swoim: Idźcie przedemną, a ja pojadę za wami; ale mężowi swemu Nabalowi nie oznajmiła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'I stało się, że jadąc na ośle, i zjeżdżając głębią góry, oto też Dawid i mężowie jego zjeżdżali przeciwko niej, i spotkała się z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, '(A Dawid był rzekł: Zaprawdę darmom strzegł wszystkiego, co ten miał na puszczy, że nic nie zginęło ze wszystkiego, co ma; bo mi oddał złem za dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'To niech uczyni Bóg nieprzyjaciołom Dawidowym, i to niech przyczyni, jeźli co do zarania zostawię ze wszystkiego co ma, aż do najmniejszego szczenięcia).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'Tedy ujrzawszy Abigail Dawida, pospieszyła się, i zsiadła z osła, i upadła przed Dawidem na oblicze swoje, i ukłoniła się aż do ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'A upadłszy do nóg jego, mówiła: Niech będzie na mnie, panie mój, ta nieprawość, a niech mówi proszę służebnica twoja do uszu twoich, i posłuchaj słów służebnicy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Niech się proszę nie obraża pan mój na mężą tego bezbożnego Nabala, gdyż według imienia swego takim jest. Nabal jest imię jego, i głupstwo jest przy nim; alemci ja służebnica twoja nie widziała sług pana mego, któreś był posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Przetoż teraz panie mój, jako żywy Pan, jako żywa i dusza twoja, że cię zawściągnął Pan, abyś nie szedł na rozlanie krwi, i żeby się nie mściła ręka twoja; a teraz niech będą jako Nabal nieprzyjaciele twoi, i którzy szukają złego panu memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Teraz tedy to błogosławieństwo, które przyniosła służebnica twoja panu swemu, niech będzie dane sługom, którzy chodzą za panem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Przepuść proszę występek służebnicy twojej, gdyż zapewne uczyni Pan panu memu dom trwały, ponieważ walki Pańskie pan mój odprawuje, a złość nie jest znalezina w tobie aż dotąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'A choćby powstał człowiek, coby cię prześladował, i szukał duszy twojej, tedy będzie dusza pana mego zachowana w wiązance żywiących u Pana, Boga twego; lecz duszę nieprzyjaciół twoich Bóg jako z procy wyrzuci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'A gdy uczyni Pan panu memu wszystko, co mówił dobrego o tobie, a zlecić, abyś był wodzem nad Izraelem:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'Tedyć nie będzie to ku zachwianiu, ani ku urazie serca pana mego, jako gdyby rozlał krew niewinną, i gdyby się sam pomścił pan mój. Gdy tedy dobrze uczyni Pan panu memu, wspomnisz na służebnicę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'I rzekł Dawid do Abigaili: Błogosławiony Pan, Bóg Izraelski, który cię dziś posłał przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'Błogosławiona wymowa twoja, i błogosławionaś ty, któraś mię zawściągnęła dzisiaj, żem nie szedł na rozlanie krwi, a żem się sam nie mścił krzywdy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'A zaprawdę, jako żywy Pan, Bóg Izraelski, który mię zawściągnął, abym ci nic złego nie uczynił: bo gdybyś się była nie pospieszyła, a nie zajechała mi drogi, nie zostałoby było Nabalowi aż do świtania, i najmniejszego szczenięcia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'A tak przyjął Dawid z ręki jej, co mu była przyniosła, i rzekł do niej: Idź w pokoju do domu twego: otom usłuchał głosu twego, i przyjąłem cię łaskawie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'Tedy się wróciła Abigail do Nabala; a on miał ucztę w domu swoim, jako ucztę królewską, a serce Nabalowe było wesołe w nim, a był pijany bardzo; i nie oznajmiła mu najmniejszej rzeczy aż do poranku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Ale nazajutrz, gdy wytrzeźwiał Nabal z wina, oznajmiła mu żona jego te rzeczy: i zmartwiało w nim serce jego, i stał się jako kamień');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'A gdy wyszło jakoby dziesięć dni, uderzył Pan Nabala, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'A usłyszawszy Dawid, iż umarł Nabal, rzekł: Błogosławiony Pan, który się pomścił pohańbienia mego nad Nabalem, a sługę swego zatrzymał od złego, a złość Nabalowę obrócił Pan na głowę jego. Tedy posłał Dawid wskazując do Abigaili, że ją sobie chce wziąć za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'I przyszli słudzy Dawidowi do Abigaili do Karmelu, i rzekli do niej, mówiąc: Dawid posłał nas do ciebie, aby cię sobie wziął za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Która wstawszy, pokłoniła się obliczem do ziemi, i rzekła: Oto, służebnica twoja niech będzie sługą, aby umywała nogi sług pana mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'Przetoż pospieszywszy się wstała Abigail, i wsiadła na osła z pięcioma panienkami swemi, które z nią chodziły; i tak jechała za posłami Dawidowymi, a była mu za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Ale i Achinoamę wziął Dawid z Jezreel, i były mu te dwie za żony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Albowiem Saul dał był Michol, córkę swoję, żonę Dawidowę, Faltemu, synowi Laisowemu, który był z Gallim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'I przyszli Zyfejczycy do Saula do Gabaa, a mówili: Izali się nie kryje Dawid na pagórku Hachila, przeciw Jesymon?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Ruszył się tedy Saul, i ciągnął na puszczą Zyf, a z nim trzy tysiące mężów przebranych z Izraela, aby szukał Dawida na puszczy Zyf.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'I położył się Saul obozem na pagórku Hachila, które jest przeciw Jesymon podle drogi; a Dawid mieszkał na puszczy, i dowiedział się, że przyciągnął Saul za nim na puszczą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'Bo posławszy Dawid szpiegi dowiedział się, że przyciągnął Saul zapewne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'Przetoż wstał Dawid, i przyszedł aż ku miejscu, gdzie się położył obozem Saul; i upatrzył Dawid miejsce, gdzie spał Saul, i Abner, syn Nera, hetman wojska jego; bo Saul spał w obozie, a lud leżał około niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'I odpowiedział Dawid, a rzekł do Achimelecha Hetejczyka, i do Abisajego, syna Sarwii, brata Joabowego, mówiąc: Któż pójdzie ze mną do Saula do obozu? Odpowiedział Abisaj: Ja z tobą pójdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'A tak przyszedł Dawid i Abisaj do ludu w nocy, a oto, Saul leżąc spał w obozie, a włócznia jego była utkniona w ziemi u głowy jego; Abner też z ludem leżeli około niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Tedy rzekł Abisaj do Dawida: Zamknął dziś Bóg nieprzyjaciela twego w ręce twoje, a teraz niech go przebije proszę włócznią ku ziemi raz, a więcej nie powtórzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'Ale rzekł Dawid do Abisajego: Nie zabijaj go; bo któż ściągnąwszy rękę swą na pomazańca Pańskiego, niewinnym będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Nadto rzekł Dawid: Jako żyje Pan, że jeźli go Pan nie zabije, albo dzień jego nie przyjdzie, aby umarł, albo na wojnę wyjechawszy, nie zginie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'Tedy uchowaj mię Panie, abym miał ściągnąć rękę moję na pomazańca Pańskiego; ale weźmij proszę włócznią, która jest u głów jego, i kubek od wody, a odejdźmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Tedy wziął Dawid włócznią, i kubek od wody, który był u głów Saulowych, i odeszli, a nie był, ktoby widział, ani ktoby wiedział, ani ktoby się ocucił, ale wszyscy spali; bo sen twardy od Pana przypadł był na nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'I przyszedł Dawid na drugą stronę, i stanął na wierzchu góry z daleka, a był plac wielki między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'I zawołał Dawid na lud, i na Abnera, syna Nerowego, mówiąc: Nie ozwieszże się Abnerze? I odpowiadając Abner, rzekł: Któżeś ty, co wołasz na króla?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'I rzekł Dawid do Abnera: Azaż ty nie mąż? A któż jakoś ty w Izraelu? przeczżeś tedy nie strzegł króla, pana twego? bo przyszedł jeden z ludu, chcąc zabić króla, pana twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'Nie dobra to, coś uczynił. Jako żywy Pan, żeście winni śmierci, którzyście nie strzegli pana waszego, pomazańca Pańskiego. A teraz, patrz, kędy jest włócznia królewska, i kubek od wody, co był w głowach jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'Poznał tedy Saul głos Dawida, i rzekł: Twójże to głos, synu mój Dawidzie? Odpowiedział Dawid: Głos to mój, królu, panie mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Nadto rzekł: Czemuż pan mój prześladuje sługę swego? bo cóżem uczynił? a co jest złego w ręce mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Przetoż teraz niech posłucha proszę król, pan mój, słów sługi swego; jeźli cię Pan pobudził przeciwko mnie, niech powonia ofiary; ale jeźli synowie Judzcy, przeklęci są przed Panem, którzy mię dziś wygnali, abym nie mieszkał w dziedzictwie Pańskiem, jakoby rzekli: Idź, służ bogom cudzym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'A teraz niech nie będzie wylana krew moja na ziemię przed obliczem Pańskiem; bo wyszedł król Izraelski szukać pchły jednej, jakoby też kto gonił kuropatwę po górach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Tedy rzekł Saul: Zgrzeszyłem. Wróćże się, synu mój Dawidzie, boć już nic złego nie uczynię więcej, ponieważ droga była dusza moja w oczach twoich dnia tego; otom głupio uczynił, i zbłądziłem nader bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'A odpowiadając Dawid rzekł: Oto włócznia królewska; niech sam przyjdzie kto z sług, a weźmie ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'A Pan niech odda każdemu sprawiedliwość jego, i wiarę jego. Albowiem podał cię był Pan dziś w ręce moje; alem nie chciał ściągnąć ręki mojej na pomazańca Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'Przetoż jako dziś poważona była dusza twoja w oczach moich, tak niech będzie poważona dusza moja w oczach Pańskich, a niech mię wyrwie Pan ze wszego ucisku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'I rzekł Saul do Dawida: Błogosławionyś ty, synu mój Dawidzie; tak czyniąc dokażesz, a tak się wzmacniając, mocnym będziesz. Odszedł potem Dawid w drogę swą, a Saul się wrócił na miejsce swoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'Tedy rzekł Dawid w sercu swojem: Zginę ja kiedyżkolwiek od ręki Saulowej. Azaż mnie nie lepiej, abym co prędzej uszedł do ziemi Filistyńskiej, aby zwątpił o mnie Saul, i nie szukał mię więcej po wszystkich granicach Izraelskich, i tak abym uszedł rąk jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'Wstawszy tedy Dawid, poszedł sam i onych sześć set mężów, którzy byli z nim, do Achisa, syna Maocha, króla Get.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'I mnieszkał Dawid przy Achisie w Get, sam i mężowie jego, każdy z czeladzią swoją, Dawid i dwie żony jego, Achinoam Jezreelitka, i Abigail, żona przedtem Nabalowa z Karmelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'A gdy powiedziano Saulowi, że uciekł Dawid do Get, przestał go więcej szukać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'I rzekł Dawid do Achisa: Jeźlim proszę znalazł łaskę w oczach twoich, niech mi dadzą miejsce w jednem z miast tego kraju, abym tam mieszkał; bo czemużby miał mieszkać sługa twój w mieście królewskiem z tobą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'I dał mu Achis dnia onego Syceleg; dla tego Syceleg było królów Judzkich aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'A była liczba dni, których mieszkał Dawid w krainie Filistyńskiej, rok i cztery miesiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'I wypadał Dawid i mężowie jego, a wtargiwali do Giessurytów, i do Gierzytów, i do Amalekitów; bo ci mieszkali w onej ziemi zdawna; którędy chodzą przez Sur aż do ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'I pustoszył Dawid ziemię onę, a nie zostawiał żywego męża i niewiasty; a zabrawszy owce, i woły, i osły i wielbłądy, i szaty, wracał się zasię, i przychadzał do Achisa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'A gdy się pytał Achis: Gdzieżeście byli dziś wpadli? odpowiadał Dawid: Ku południu Judy, i ku południu w Jerameel, i ku południu Ceni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'Ale Dawid nie żywił męża, ani niewiasty, ani ich przywodził do Get, mówiąc: By snać nie skarżyli na nas, mówiąc: Tak uczynił Dawid. I był to jego zwyczaj po wszystkie dni, póki mieszkał w ziemi Filistyńskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Wierzył tedy Achis Dawidowi i mówił: Prawie się już stał obrzydłym ludowi swemu Izraelskiemu, a tak będzie mi sługą wiecznym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'I stało się w one dni, że zebrali Filistynowie wojska swe na wojnę, aby walczyli z Izraelem. Tedy Achis rzekł do Dawida: Wiedz wiedząc, iż ze mną pociągniesz na wojnę, ty i mężowie twoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'I odpowiedział Dawid Achisowi: Dopiero się ty dowiesz, co uczyni sługa twój. I rzekł Achis do Dawida: Zaiste stróżem głowy mojej postanowię cię po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'A Samuel już był umarł, i płakał go wszystek Izrael, i pogrzebli go w Ramacie, mieście jego; a Saul wygnał był wieszczki i czarowniki z ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Zebrawszy się tedy Filistynowie, przyciągnęli, a położyli się obozem u Sunam; zebrał też Saul wszystkiego Izraela, a położył się obozem w Gielboe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'A widząc Saul obóz Filistyński, bał się, a ulękło się serce jego bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'I radził się Saul Pana; ale mu nie odpowiedział Pan ani przez sny, ani przez urym, ani przez proroki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Przetoż rzekł Saul do sług swoich: Szukajcie mi niewiasty, któraby miała ducha wieszczego, a pójdę do niej, i wywiem się przez nię. I rzekli słudzy jego do niego: Oto, niewiasta w Endor, mająca ducha wieszczego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'Tedy odmienił odzienie swoje Saul, a oblókłszy się w insze szaty, szedł sam i dwaj mężowie z nim, a przyszli do niewiasty w nocy, i rzekł: Wróż mi, proszę, przez ducha wieszczego, a wywiedź tego, kogoć powiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'I rzekła do niego niewiasta: Oto ty wiesz, co uczynił Saul, iż wygładził wieszczki i czarowniki z ziemi; przeczże ty sidło kładziesz na duszę moję, abyś mię na śmierć podał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'I przysiągł jej Saul przez Pana, mówiąc: Jako żywy Pan, że nie przyjdzie na cię karanie dla tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Tedy rzekła niewiasta: Kogoż ci mam wywieść? A on rzekł: Wywiedź mi Samuela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'A widząc niewiasta Samuela, zawołała głosem wielkim, i rzekła niewiasta do Saula, mówiąc: Przeczżeś mię zdradził, gdyżeś ty jest Saul?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'I rzekł jej król: Nie bój się; cóżeś widziała? I rzekła niewiasta do Saula: Widziałam bogi występujące z ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'Tedy rzekł do niej: Co za osoba jego? I rzekła: Mąż stary wyszedł, a ten odziany płaszczem. I poznał Saul, że to był Samuel, i schyliwszy się twarzą ku ziemi, pokłonił mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'Zatem rzekł Samuel do Saula: Przecz mi nie dasz pokoju, wzbudzając mię? Odpowiedział mu Saul: Jestem uciśniony bardzo, gdyż Filistynowie walczą przeciwko mnie, a Bóg odstąpił odemnie, i nie odpowiada mi więcej, ani przez proroki, ani przez sny; przetoż przyzwałem cię, abyś mi oznajmił, co mam czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'I rzekł Samuel: Czemuż mię tedy pytasz, gdyż Pan odstąpił od ciebie, a przestawa z nieprzyjacielem twoim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'I uczynił mu Pan, jakoć powiedział przez mię, i wyrwał Pan królestwo z rąk twoich, a dał je bliźniemu twemu Dawidowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Bo żeś ty nie był posłusznym głosowi Pańskiemu, aniś wykonał gniewu zapalczywości jego nad Amalekiem, przetożci to uczynił Pan dzisiaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Nadto poda Pan i Izraela z tobą w rękę Filistynów, a jutro ty i synowie twoi ze mną będziecie; obóz też Izraelski poda Pan w ręce Filistynów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'A natychmiast Saul upadł jako długi na ziemię, bo się zląkł bardzo słów Samuelowych, i siły nie było w nim, przeto że nic nie jadł przez cały dzień i przez całą noc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'Potem weszła niewiasta do Saula, a widząc, iż się bardzo przeląkł, rzekła mu: Oto, usłuchała służebnica twoja głosu twego, i odważyłam zdrowie swoje, i usłuchałam słów twoich, któreś mówił do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Przetoż teraz usłuchaj proszę i ty głosu służebnicy twojej; a położę przed cię sztuczkę chleba, abyś jadł, i posilił się, abyś mógł iść w drogę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'Ale nie chciał, i mówił: Nie będę jadł. I przymusili go słudzy jego, także i niewiasta; i usłuchał głosu ich, a wstawszy z ziemi, usiadł na łóżku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'A ona niewiasta miała karmne cielę w domu, a pospieszywszy się, zabiła je; potem wziąwszy mąki zaczyniła, i napiekła z niej przaśników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'I przyniosła przed Saula, i przed sługi jego, którzy najadłszy się, wstali, i poszli onej nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Tedy zebrali Filistynowie wszystkie wojska swe do Afeku; a Izraelczycy położyli się obozem nad źródłem, które było w Jezreelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'A książęta Filistyńskie ciągnęli stami i tysiącami, a Dawid i mężowie jego ciągnęli pozad z Achisem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'I rzekły książęta Filistyńskie: Cóż tu czynią ci Hebrejczycy? I rzekł Achis do książąt Filistyńskich: Azaż nie to jest Dawid, sługa Saula, króla Izraelskiego, który był przy mnie przez te dni, owszem przez te lata? I nie doświadczyłem go w niczem od onego dnia, jako zbiegł do mnie, aż do dnia tego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'I rozgniewały się nań książęta Filistyńskie, i rzekły mu książęta Filistyńskie: Odpraw tego męża, a niech się wróci do miejsca swego, na któremeś go postawił; niech nie chodzi z nami na wojnę, aby się nam nie stawił nieprzyjacielem w bitwie. Bo jakoż inaczej może przyjść do łaski pana swego, jedno przez głowy tych mężów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Azaż nie ten jest Dawid, któremu śpiewano hufcami, mówiąc: Poraził Saul swój tysiąc, ale Dawid swoich dziesięć tysięcy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'A tak wezwał Achis Dawida, i rzekł mu: Jako żywy Pan, żeś ty szczery i dobry jest w oczach moich, a podoba mi się wyjście twoje, i wejście twoje ze mną do obozu, bom nie znalazł w tobie nic złego ode dnia, któregoś przyszedł do mnie, aż do dnia te go; tylko w oczach książąt nie masz łaski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Przetoż teraz wróć się, a idź w pokoju i nie czyń nic, coby było przeciwnego w oczach książąt Filistyńskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'I rzekł Dawid do Achisa: Cóżem wżdy uczynił? a coś znalazł w słudze twym ode dnia, któregom był przy tobie, aż do dnia tego, abym nie szedł i nie walczył przeciwko nieprzyjaciołom króla, pana mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'A odpowiadając Achis, rzekł Dawidowi: Wiem, iżeś ty dobry w oczach moich, jako Anioł Boży; ale książęta Filistyńskie rzekły: Niech nie chodzi z nami na wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'A przetoż wstań bardzo rano, i słudzy pana twego, którzy z tobą przyszli, a wstawszy rano, skoro pocznie świtać, odejdźcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Wstał tedy Dawid, sam i mężowie jego, aby odszedł tem raniej, i nawrócił się do ziemi Filistyńskiej, a Filistynowie ciągnęli do Jezreel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'A gdy się wrócił Dawid i mężowie jego do Sycelegu, był dzień trzeci, jako Amalekitowie wtargnęli byli na południe, i do Sycelegu, a zburzyli Syceleg, i spalili go ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'I pobrali w niewolę niewiasty, które były w nim; od najmniejszego aż do wielkiego, nie zabili nikogo, ale tylko pojmali, i odeszli drogą swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'A gdy przyszedł Dawid i mężowie jego do miasta, oto, spalone było ogniem, a żony ich, i syny ich, i córki ich w niewolę zabrano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Tedy podniósł Dawid, i lud, który był z nim, głos swój, i płakali, aż im siły do płaczu nie stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Obiedwie też żony Dawidowe były wzięte w niewolą: Achinoam Jezreelitka, i Abigail, przedtem żona Nabalowa z Karmelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'I był utrapiony Dawid bardzo; bo się zmawiał lud ukamionować go, gdyż gorzkości pełna była dusza wszystkiego ludu, każdego dla synów swych, i dla córek swych; wszakże Dawid zmocnił się w Panu, Bogu swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'Tedy rzekł Dawid do Abijatara kapłana, syna Achimelechowego: Weźmij proszę dla mnie efod; i wziął Abijatar efod dla Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'A tak się Dawid radził Pana, mówiąc; Mamli gonić to wojsko, i dogonięli go? A Pan mu rzekł: Goń; bo zapewne ich dogonisz, i zapewne odbijesz plon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'Szedł tedy Dawid, sam i one sześć set mężów, które miał z sobą, a przyszli aż do potoku Besor; a niektórzy pozostali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'I gonił je Dawid, sam i cztery sta mężów; bo pozostało było dwieście mężów spracowanych, a nie poszli za potok Besor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'I znaleźli męża Egipczanina na polu, a przywiedli go do Dawida, i dali mu chleba, i jadł; dali mu też wody, i pił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'Dali mu także i wiązankę fig i dwie gronie rodzynków. Jadł tedy, i wrócił się duch jego weń; bo nie jadł chleba, ani pił wody przez trzy dni i przez trzy nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'I rzekł do niego Dawid: Czyjeś ty? a skądeś? Który odpowiedział: jestem rodem z Egiptu, sługa męża Amalekity, i zostawił mię pan mój, żem się rozniemógł dziś trzeci dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Wtargnęliśmy byli na południe do Cerety i do Juda, i na południe do Kaleb, i spaliliśmy Syceleg ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'I rzekł mu Dawid: Mógłżebyś mię dowieść do tego wojska? Który rzekł: Przysięż mi przez Boga, iż mię nie zabijesz, ani mię wydasz w rękę pana mego; tedy cię nawiodę na to wojsko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Nawiódł go tedy; a oto, oni leżeli po wszystkiej onej ziemi, jedząc i pijąc, i weseląc się ze wszystkich korzyści wielkich, które byli zabrali z ziemi Filistyńskiej, i z ziemi Judzkiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'Przetoż bił je Dawid od wieczora aż do wieczora dnia drugiego, tak iż z nich żaden nie uszedł, oprócz czterech set młodzieńców, którzy wsiadłszy na wielbłądy, uciekli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'A tak odjął Dawid wszystko, co byli pobrali Amalekitowie, i dwie żony swoje odjął też Dawid;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Tak iż im nic nie zginęło od mała aż do wiela, i aż do synów, i córek, i do korzyści, i aż do wszystkiego, cokolwiek im zabrali, wszystko zasię przywiódł Dawid.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'Przytem zabrał Dawid wszystkie trzody i stada, które gnano przed bydłem jego, i mówiono: Toć jest korzyść Dawidowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'I przyszedł Dawid do onych dwóch set mężów, którzy byli spracowani, że nie mogli iść za Dawidem, którym był kazał zostać u potoku Besor, którzy wyszli przeciw Dawidowi i przeciw ludowi, który z nim był; a przystąpiwszy Dawid do ludu, pozdrowił je spokojnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'A odpowiadając wszyscy mężowie źli i niepobożni, którzy chodzili z Dawidem, rzekli: Ponieważ ci nie chodzili z nami, nie damy im z łupów, któreśmy odjęli, tylko każdemu żonę jego, i syny jego; te wziąwszy, niech odejdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Tedy rzekł Dawid: Nie uczynicie tak, bracia moi, z tem, co nam dał Pan, który nas strzegł, a podał wojsko, które było wyszło przeciwko nam, w ręce nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'I któż was w tem usłucha? Bo jaki dział tego, który wyszedł na wojnę, taki dział i tego, który został przy tłomokach; równo się podzielą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'I stało się od onego dnia i napotem, że uchwalono to prawo i ten zwyczaj w Izraelu, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'A tak przyszedł Dawid do Sycelega, i posłał z onego łupu starszym w Juda, przyjaciołom swym, mówiąc: Oto macie błogosławieństwo z korzyści nieprzyjaciół Pańskich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Tym, co byli w Betel, i co w Ramacie na południe, i co byli w Gieter,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'I co byli w Aroer, i co byli w Sefamot, i co byli w Estamo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'I co byli w Racha, i co byli w miastach Jerameel, i co byli w miastach Ceni,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'I co byli w Horma, i co byli w Chorasan, i co byli w Atach,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'I co byli w Hebronie, i co byli na wszystkich miejscach, kędy przemieszkiwał Dawid, sam i mężowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'A Filistynowie zwiedli bitwę z Izraelem; i uciekli mężowie Izraelscy przed Filistynami, a polegli zranieni na górze Gielboe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'I gonili Filistynowie Saula i syny jego, i zabili Filistynowie Jonatana, i Abinadaba, i Melchisuego, syny Saulowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'A gdy się wzmagała bitwa przeciwko Saulowi, trafili nań strzelcy, mężowie strzelający z łuku, i zraniony jest bardzo od strzelców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'I rzekł Saul do wyrostka swego, który nosił broń jego: Dobądź miecza twego, a przebij mię nim, by snać nie przyszli ci nieobrzezańcy, i nie przebili mię, a nie czynili igrzyska ze mnie. Ale nie chciał wyrostek jego, bo się bardzo bał. Przetoż Saul porwał miecz i upadł nań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'A widząc wyrostek jego, iż umarł Saul, padł i on na miecz swój, i umarł z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Umarł tedy Saul, i trzej synowie jego, i wyrostek jego, co za nim broń nosił, i wszyscy mężowie jego dnia onego wespół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Co gdy ujrzeli mężowie Izraelscy, którzy za doliną, i za Jordanem mieszkali, iż uciekali mężowie Izraelscy, a iż umarł Saul, i synowie jego, odbieżawszy miast, pouciekali też, a przyszedłszy Filistynowie mieszkali w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'A nazajutrz przyszli Filistynowie, aby odzierali pobite; i znaleźli Saula, i trzech synów jego leżących na górze Gielboe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'A uciąwszy głowę jego, zdarli z niego zbroję jego, i posłali po ziemi Filistyńskiej wszędzie, aby to opowiadano w kościele bałwanów ich, i między ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'I położyli zbroję jego w kościele Astarot; ale ciało jego przybili na murze Betsan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Tedy usłyszawszy o tem obywatele Jabes Galaad, co uczynili Filistynowie Saulowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'Wstali wszyscy mężowie mocni, i szli przez onę całą noc, i wzięli ciało Saulowe, i ciała synów jego z muru Betsan, a przyszedłszy do Jabes spalili je tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'A wziąwszy kości ich, pogrzebli je pod drzewem w Jabes, i pościli siedm dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'I stało się po śmierci Saulowej, gdy się Dawid wrócił od porażki Amalekitów, że zamieszkał Dawid w Sycelegu przez dwa dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'Tedy dnia trzeciego przybieżał mąż z obozu Saulowego, a szaty jego rozdarte były, i proch na głowie jego; który przyszedłszy do Dawida, upadł na ziemię, i pokłonił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'I rzekł do niego Dawid: Skąd idziesz? I odpowiedział mu: Z obozum Izraelskiego uszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'Rzekł mu znowu Dawid: Cóż się stało? proszę powiedz mi. I odpowiedział: To, że uciekł lud z bitwy, a do tego wiele poległo z ludu i pomarło, także i Saul, i Jonatan, syn jego, polegli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'Zatem rzekł Dawid do młodzieńca, który mu to powiedział: Jakoż wiesz, iż umarł Saul i Jonatan, syn jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Odpowiedział mu młodzieniec, który mu to oznajmił: Przyszedłem z trafunku na górę Gilboe, a oto, Saul tkwiał na włóczni swojej, a wozy i jezdni doganiali go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'Tedy obejrzawszy się, obaczył mię, i zawołał na mię, i rzekłem: Owom ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'I rzekł mi: Coś ty zacz? A jam mu odpowiedział: Jestem Amalekita.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'I rzekł mi: Stań, proszę, nademną, a zabij mię: bo mię zdjęły ciężkości, gdyż jeszcze wszystka dusza moja we mnie jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'Przetoż stanąwszy nad nim, zabiłem go: bom wiedzieł, że nie będzie żyw po upadku swoim, i wziąłem koronę, która była na głowie jego, i zawieszenie, które było na ramieniu jego, a przyniosłem je tu do pana mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Tedy Dawid pochwyciwszy szaty swoje, rozdarł je, także i wszyscy mężowie, którzy z nim byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'A żałując płakali, i pościli aż do wieczora dla Saula, i dla Jonatana, syna jego, i dla ludu Pańskiego, i dla domu Izraelskiego, że polegli od miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'I rzekł Dawid do młodzieńca, który mu to oznajmił: Skądeś ty? I odpowiedział: Jestem synem męża przychodnia Amalekity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'Zatem rzekł do niego Dawid: Jakożeś się nie bał ściągnąć ręki twej, abyś zabił pomazańca Pańskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'Zawołał tedy Dawid jednego z sług, i rzekł: Przystąp, a zabij go, a on go uderzył, że umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'I rzekł do niego Dawid: Krew twoja na głowę tweję: bo usta twoje świadczyły przeciw tobie, mówiąc: Jam zabił pomazańca Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'Lamentował tedy Dawid lamentem takowym nad Saulem, i nad Jonatanem, synem jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, '(Rozkazawszy jednak, aby uczono synów Judzkich z łuku strzelać, jako napisano w księgach Jasar.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'O ozdobo Izraelska! na górach twoich zranionyś jest; jakoż polegli mocarze twoi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Nie powiadajcież w Get, a nie rozgłaszajcie po ulicach w Aszkalonie, aby się snać nie weseliły córki Filistyńskie, by się snać nie radowały córki nieobrzezańców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'O góry Gielboe! ani rosa, ani deszcz niech nie upada na was, i niech tam nie będą pola urodzajne; albowiem tam porzucona jest tarcz mocarzów, tarcz Saulowa, jakoby nie był pomazany olejem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Od krwi zabitych, i od sadła mocarzów strzała łuku Jonatanowego nie wracała się na wstecz, a miecz Saulowy nie wracał się próżno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Saul i Jonatan miłośni i przyjemni za żywota swego, i w śmierci swojej nie są rozłączeni, nad orły lekciejsi, nad lwy mocniejsi byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Córki Izraelskie płaczcie nad Saulem, który was przyodziewał szarłatem rozkosznym, a który was ubierał w klejnoty złote na szaty wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Jakoż polegli mocarze pośród bitwy! Jonatan na górach twoich zabity jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Bardzo mi cię żal, bracie mój Jonatanie, byłeś mi bardzo wdzięcznym; większa u mnie była miłość twoja, niż miłość niewieścia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Jakoż polegli mocarze, a poginęła broń wojenna!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'I stało się potem, że pytał Dawid Pana, mówiąc: Mamże iść do któregokolwiek miasta Judzkiego? Któremu Pan odpowiedział: Idź. I rzekł Dawid: Dokądże pójdę? I odpowiedział: Do Hebronu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'Tedy tam jechał Dawid, także i dwie żony jego, Achinoam Jezreelitka, i Abigail żona przedtem Nabalowa z Karmelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Także męże swe, którzy z nim byli, zabrał Dawid, każdego z domem jego, i mieszkali w miastach Hebrońskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'Przyszli potem mężowie Juda, i pomazali tam Dawida za króla nad domem Juda; tedy opowiadano Dawidowi, mówiąc: Mężowie z Jabes Galaad ci pogrzebli Saula.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'Tedy wyprawił Dawid posły do mężów z Jabes Galaad, i rzekł do nich: Błogosławieniście wy od Pana, którzyście ucznili to miłosierdzie nad Panem waszym Saulem, żeście go pogrzebli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Przetoż teraz niech uczyni Pan z wami miłosierdzie, i prawdę, a ja też oddam wam to dobrodziejstwo, żeście uczynili tę rzecz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Teraz tedy niech się zmacniają ręce wasze, a bądźcie mężnymi; bo choć umarł Saul, pan wasz, wszakże mnie pomazał dom Juda za króla nad sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'A Abner, syn Nera, hetman nad wojskiem Saulowem, wziął Izboseta syna Saulowego, i przyprowadził go do Machanaim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'I uczynił go królem nad Gaaladem, i nad Assury, i nad Jezreelem, i nad Efraimem, i nad Benjaminem, i nad wszystkim Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Czterdzieści lat miał Izboset, syn Saula, gdy począł królować nad Izraelem, a dwa lata królował; tylko dom Juda stał przy Dawidzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'I była liczba dni, których był Dawid królem w Hebronie nad domem Judzkim, siedm lat i sześć miesięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'Potem wyszedł Abner, syn Nera, i słudzy Izboseta, syna Saulowego, z Machanaim do Gabaonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Joab także, syn Sarwii, z sługami Dawidowymi wyszli, i spotkali się z sobą prawie u stawu Gabaońskiego, i zostali jedni na jednej stronie stawu, a drudzy na drugiej stronie stawu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Tedy rzekł Abner do Joaba: Niech teraz wstaną młodzieńcy, a poigrają przed nami. I rzekł Joab: Niech wstaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Wstali tedy; i wyszło w liczbie dwanaście z Benjamińczyków ze strony Izboseta, syna Saulowego, a dwanaście z sług Dawidowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'Którzy uchwyciwszy się, każdy za głowę przeciwnika swego, utopił miecz swój w boku jeden drugiego, i polegli pospołu. Przetoż nazwano miejsce ono Helkatassurym, które jest w Gabaonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'I była bitwa bardzo sroga dnia onego, a porażon jest Abner i mężowie Izraelscy od sług Dawidowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'I byli też tam trzej synowie Sarwii: Joab, Abisaj, i Asael; ale Asael był prędkich nóg, jako dzika koza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'I gonił Asael Abnera, a nie ustąpił idąc ani na prawo ani na lewo, ścigając Abnera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'A obejrzawszy się Abner nazad, rzekł: Tyżeś jest Asael? A on mu odpowiedział: Ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'Tedy mu rzekł Abner: Uchyl się na prawą stronę twoję, albo na lewą stronę twoję, a pojmij sobie jednego z młodzieńców, i weźmij sobie łupy z niego; ale Asael nie chciał od niego ustąpić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'Tedy po wtóre rzekł Abner do Asaela: Idź precz ode mnie, bym cię snać nie przebił ku ziemi; bo jakoże bym śmiał podnieść twarz moję na Joaba, brata twego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'A gdy nie chciał ustąpić, uderzył go Abner końcem włóczni pod piąte żebro, tak iż wyszła włócznia na drugą stronę. Tamże padł, i umarł na onemże miejscu, a wszyscy, którzy przychodzili do onego miejsca, gdzie poległ Asael i umarł, zastanawiali się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Wszakże gonili Joab i Abisaj Abnera; i zachodziło słońce, gdy przyszli do pagórka Amma, który jest przeciw Gia na drodze pustyni Gabaońskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'Tedy się zebrali synowie Benjaminowi do Abnera, skupiwszy się w jeden huf, i stanęli na wierzchu jednego pagórka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'I zawołał Abner na Joaba i rzekł: Izali się na wieki będzie srożył ten miecz? azaż nie wiesz, że na ostatku bywa gorzkość? i dokądże nie rzeczesz ludowi, aby się wrócił od pogoni braci swych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'Tedy rzekł Joab: Jako żywy Bóg, byś ty był nie wyzywał, zarazby się był z poranku lud wrócił, każdy od pogoni braci swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'A tak zatrąbił Joab w trąbę i zastanowił się wszystek lud, a nie gonili dalej Izraela, ani się więcej potykali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Ale Abner i mężowie jego szli polem całą onę noc, a przeprawiwszy się przez Jordan, przeszli przez wszystko Betoron, aż przyszli do Mahanaim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'A Joab wróciwszy się z pogoni za Abnerem, zebrał wszystek lud, i nie dostawało mu sług Dawidowych dziewiętnastu mężów, i Asaela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'Ale słudzy Dawidowi pobili z Benjamińczyków, i z mężów Abnerowych trzy sta i sześćdziesiąt mężów, którzy tam pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'A wziąwszy Asaela, pogrzebli go w grobie ojca jego, który był w Betlehem; potem szli całą noc Joab i mężowie jego, a na świtaniu przyszli do Hebronu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'I była długa wojna między domem Saulowym i między domem Dawidowym. Wszakże Dawid postępował, i zmacniał się; ale dom Saulów schodził i niszczał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'I narodziło się Dawidowi w Hebronie synów. A był pierworodny jego Amnon z Achinoamy Jezreelitki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'Wtóry po nim był Helijab z Abigaili, żony przedtem Nabalowej z Karmelu, a trzeci Absalom, syn Moachy, córki Tolmaja króla Giessur;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'A czwarty Adonijasz, syn Hagity, a piąty Sefatyjasz, syn Abitali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'A szósty Jetraam z Egli, żony Dawidowej. Cić się urodzili Dawidowi w Hebronie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'I stało się, gdy była wojna między domem Saulowym i między domem Dawidowym, a Abner się mężnie zastawiał o dom Saulowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, '(A Saul miał założnicę, której imię było Resfa, córka Aje,) że rzekł Izboset do Abnera: Czemuś wszedł do założnicy ojca mojego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'I rozgniewał się Abner bardzo o one słowa Izbosetowe, i rzekł: Izalim ja psia głowa, którym przeciw Judzie dziś uczynił miłosierdzie nad domem Saula, ojca twego, i nad bracią jego, i nad przyjaciółmi jego, i nie wydałem cię w rękę Dawidowę, a ty d ziś szukasz na mnie nieprawości tej niewiasty?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'To niech uczyni Bóg Abnerowi, i to niech mu przyczyni, jeźliże, jako przysiągł Pan Dawidowi, nie pomogę do tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'Aby przeniesione było królestwo od domu Saulowego, a wystawiona stolica Dawidowa nad Izraelem, i nad Judą od Dan aż do Beerseba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'I nie mógł nic więcej odpowiedzieć Abnerowi, przeto że się go bał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'A tak wyprawił Abner posły do Dawida od siebie, mówiąc: Czyjaż jest ziemia? i żeby mówili: Uczyń przymierze twoje ze mną, a oto ręka moja będzie z tobą, aby obrócon był do ciebie wszystek Izrael.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'Któremu odpowiedział: Dobrze, uczynię z tobą przymierze. A wszakże o jedno cię proszę, mianowicie, abyś nie przychodził przed oblicze moje, aż mi pierwej przywiedziesz Michol, córkę Saulowę, gdy będziesz chciał przyjść, abyś widział twarz moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'I wyprawił Dawid posły do Izboseta syn Saulowego, mówiąc: Wydaj mi żonę moję Michol, którąm sobie poślubił stem nieobrzezek Filistyńskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'Przetoż posłał Izboset, i wziął ją od męża, od Faltejela, syna Laisowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'Tedy szedł z nią mąż jej, a idąc za nią, płakał jej aż do Bachurym; i rzekł do niego Abner: Idź, a wróć się; i wrócił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'Uczynił potem Abner rzecz do starszych Izraelskich mówiąc: Przeszłych czasów szukaliście Dawida, aby był królem nad wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Przetoż teraz uczyńcie tak; bo Pan rzekł o Dawidzie, mówiąc: Przez rękę Dawida, sługi mego, wybawię lud mój Izraelski z ręki Filistyńskiej, i z ręki wszystkich nieprzyjaciół jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'To też mówił Abner i do Benjamińczyków. Potem odszedł Abner, aby mówił z Dawidem w Hebronie wszystko, co dobrego było w oczach Izraela, i w oczach wszystkiego domu Benjaminowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Gdy tedy przeszedł Abner do Dawida do Hebronu, a z nim dwadzieścia mężów, sprawił Dawid na Abnera, i na męże, którzy z nim byli, ucztę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'I rzekł Abner do Dawida: Wstanę, a pójdę, abym zebrał do króla, pana mego, wszystkiego Izraela, którzy z tobą uczynią przymierze; a będziesz królował nad wszystkimi, jako żąda dusza twoja. A tak odprawił Dawid Abnera, który odszedł w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'A oto, słudzy Dawidowi i Joab wracali się z wojny, korzyści wielkie z sobą prowadząc, ale Abnera już nie było u Dawida w Hebronie: bo go był odprawił, i odszedł był w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Joab tedy i wszystko wojsko, które z nim było, przyszli tam; i dano znać Joabowi, mówiąc: Był tu Abner, syn Nera, u króla; ale go odprawił, i odszedł w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Przetoż wszedłszy Joab do króla, rzekł: Cóżeś uczynił? Oto, przyszedł był Abner do ciebie; przeczżeś go puścił, aby zaś odszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Znasz Abnera, syna Nerowego, gdyż przyszedł, aby cię zdradził, i żeby wiedział wyjście twoje, i wejście twoje, aby się wywiedział o wszystkiem, co ty czynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'Tedy odszedłszy Joab od Dawida, wyprawił posły za Abnerem, którzy go wrócili od studni Syra, o czem Dawid nie wiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'A gdy się wrócił Abner do Hebronu, odwiódł go Joab w pośród bramy, aby z nim po cichu (osobno) mówił, i przebił go tam pod piąte żebro, że umarł dla krwi Asaela, brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Co gdy potem usłyszał Dawid, rzekł: Nie jestem winien, ani królestwo moje, przed Panem aż na wieki krwi Abnera, syna Nerowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Niechaj przyjdzie na głowę Joabowę, i na wszystek dom ojca jego, i niech nie ustaje z domu Joabowego płynienie nasienia cierpiący, i trędowaty, i o kiju chodzący, i od miecza upadający, i nie mający chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'A tak Joab i Abisaj, brat jego, zabili Abnera, przeto iż on też był zabił Asaela, brata ich, w bitwie u Gabaona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'Rzekł potem Dawid do Joaba i do wszystkiego ludu, który był z nim: Porozdzierajcie odzienia wasze a opaszcie się w wory, i płaczcie nad Abnerem. A król Dawid szedł za marami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'A gdy pogrzebli Abnera w Hebronie, podniósł król głos swój, i płakał nad grobem Abnerowym; płakał też wszystek lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'A tak lamentując król nad Abnerem, rzekł: Izali tak miał umrzeć Abner, jako umiera nikczemnik?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Ręce twoje nie były związane, a nogi twoje nie były pętami obciążone; poległeś jako ten, który pada przed synami niezbożnymi. Tedy tem więcej wszystek lud płakał nad nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'Potem przyszedł wszystek lud prosić Dawida, aby jadł chleb, gdy jeszcze był jasny dzień: ale przysiągł Dawid, mówiąc: To mi niech uczyni Bóg, i to niech przyczyni, jeźli przed zajściem słońca skosztuję chleba, albo czego innego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'Co gdy wszystek lud obaczył, podobało się im to; a wszystko cokolwiek czynił król, podobało się w oczach wszystkiego ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'I poznał wszystek Izrael dnia onego, że nie z naprawy królewskiej zabity był Abner, syn Nera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'I rzekł król do sług swoich: Azaż nie wiecie, że hetman, a bardzo wielki, poległ dziś w Izraelu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'A ja dziś jako nowy, i dopiero pomazany król; ci zasię mężowie, synowie Sarwii, srożsi są niżli ja; niechże odda Pan czyniącemu złe według złości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'A usłyszawszy Izboset, syn Saula, że poległ Abner w Hebronie, zemdlały ręce jego, i wszystek Izrael był przestraszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Miał też syn Saula dwóch mężów hetmanów nad hufcami, imię jednego Baana, a imię drugiego Rechab, synowie Remmona Berotczyka z synów Benjaminowych; bo też Berot policzon był w Benjaminie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'Uciekli tedy Berotczykowie do Gietaim, i byli tam przychodniami aż do onego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'A Jonatan, syn Saula, miał jednego syna chromego na nogi,(bo gdy miał pięć lat, a przyszła wieść o śmierci Saulowej, i Jonatanowej z Jezreel, a wziąwszy go mamka jego uciekła, a gdy prędko uciekała, upadł i ochromiał,) a imię jego Mefiboset.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'Poszli tedy synowie Remmona Berotczyka, Rechab i Baana, i weszli, gdy był najgorętszy dzień, do domu Izboseta, który spał na łóżku w południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'Ci tedy weszli w dom jego, jakoby kupować zboża; tamże go przebili pod piąte żebro Rechab i Baana, brat jego, i uciekli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Bo gdy byli weszli w dom, a on spał na łóżku swem w pokoju, kędy legał, tedy go przebili, i zabili go, a uciąwszy głowę jego, wzięli ją, i poszli drogą puszczy przez całą onę noc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'I przynieśli głowę Izbosetowę do Dawida do Hebronu, i rzekli do króla; Oto, głowa Izboseta, syna Saulowego, nieprzyjaciela twego, który szukał duszy twojej; a dał Pan królowi, panu memu, pomstę dzisiaj nad Saulem i nad nasieniem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'Tedy odpowiedział Dawid Rechabowi i Baanie, bratu jego, synom Remmona Berotczyka, i rzekł do nich: Jako żyw Pan, który wybawił duszę moję od wszelkiego ucisku:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'Jeźlim onego, który mi oznajmił, mówiąc: Oto umarł Saul, (choć mu się zdało, że wesołą nowinę przyniósł,) pojmawszy zabił w Syclegu, który rozumiał, żem mu miał dać zapłatę za poselstwo jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'Jako daleko więcej ludzie niepobożne, gdyż zabili męża sprawiedliwego w domu jego, na łożu jego? A teraz, izali nie mam szukać krwi jego z ręki waszej, i wygładzić was z ziemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'A tak rozkazał Dawid sługom, i zabili je, a obciążywszy ręce ich, i nogi ich, zawiesili je nad stawem w Hebronie; ale głowę Izbosetową wziąwszy pogrzebali w grobie Abnerowym w Hebronie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Zeszły się tedy wszystkie pokolenia Izraelskie do Dawida do Hebronu, i rzekły, mówiąc: Oto, my jesteśmy kość twoja i ciało twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'A przeszłych czasów, gdy Saul był królem nad nami, tyś wywodził i przywodził Izraela. Nad to rzekł Pan do ciebie: Ty będziesz pasł lud mój Izraelski, a ty będziesz wodzem nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'A tak wszyscy starsi Izraelscy przyszli do króla do Hebronu; i uczynił z nimi król Dawid przymierze w Hebronie przed Panem; i pomazali Dawida za króla nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'Trzydzieści lat było Dawidowi, gdy począł królować, a królował przez czterdzieści lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'W Hebronie królował nad Judą przez siedm lat i przez sześć miesięcy, a w Jeruzalemie królował przez trzydzieści i trzy lata nad wszystkim Izraelem i nad Judą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'A tak poszedł król i mężowie jego do Jeruzalemu przeciw Jebuzejczykowi mieszkającmu w onej ziemi, który rzekł do Dawida, mówiąc; Nie wnijdziesz sam, aż zniesiesz ślepe i chrome, jakoby mówili: Nie wnijdzie tu Dawid.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Wszakże wziął Dawid zamek Syoński, a toć jest miasto Dawidowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Bo rzekł był Dawid onego dnia: Ktobykolwiek zabił Jebuzejczyka, a wszedłby na rynny, a pobił te ślepe i chrome, które ma w nienawiści dusza Dawidowa, postanowię go hetmanem. Dla tegoż mawiano: Ślepy i chromy nie wnijdzie do tego domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'I mieszkał Dawid na onym zamku a przezwał go miastem Dawidowem, a pobudował je Dawid wszędy w koło od Mello, i wewnątrz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'A Dawid idąc postępował i rósł; bo Pan Bóg zastępów był z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'Tedy posłał Hyram, król Tyrski, posły do Dawida, i drzewa cedrowe, i cieśle, i kamienniki, i murarze, którzy zbudowali dom Dawidowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'I poznał Dawid, iż go utwierdził Pan za króla nad Izraelem, a iż wywyższył królestwo jego dla ludu swego Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'I napojmował sobie Dawid jeszcze więcej założnic i żon z Jeruzalemu przyszedłszy z Hebronu, a narodziło się więcej Dawidowi synów i córek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'A teć są imiona tych, którzy mu się urodzili w Jeruzalemie: Samma, i Sobab, i Natan, i Salomon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'I Ibchar, i Elisua, i Nefeg, i Jafija.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'I Elisama, i Elijada, i Elifelet.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'A usłyszawszy Filistynowie, że pomazano Dawida za króla nad Izraelem, ruszyli się wszyscy Filistynowie, żeby szukali Dawida; co gdy usłyszał Dawid, ustąpił na zamek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Tedy Filistynowie przyciągnąwszy, rozpostarli się w dolinie Refaim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'I radził się Dawid Pana, mówiąc: Mamli iść przeciwko Filistynom? podaszli je w ręce moje? Odpowiedział Pan Dawidowi: Idź, bo pewnie podam Filistyny w ręce twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'A tak przyciągnął Dawid do Baal Perazym, i poraził je tam Dawid i rzekł: Rozerwał Pan nieprzyjacioły moje przedemną, jako się rozrywają wody. Przetoż nazwał imię miejsca onego Baal Perazym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'I zostawili tam ryte swe obrazy, które popalił Dawid i mężowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'Znowu jeszcze przyciągnęli Filistynowie, i rozpostarli się w dolinie Refaim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'I pytał się Dawid Pana, który odpowiedział: Nie pójdziesz przeciwko nim; ale je obtoczywszy z tyłu natrzesz na nie przeciwko morwom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'A gdy usłyszysz, iż zaszumią wierzchy morwów, tedy się ruszysz, gdyż na ten czas pójdzie Pan przed tobą, aby poraził wojska Filistyńskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'I uczynił Dawid tak jako mu rozkazał Pan, a poraził Filistyny od Gabaa, aż kędy chodzą do Gazer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'Nadto zebrał jeszcze Dawid wszystkich przebranych z Izraela trzydzieści tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'A ruszywszy się, szedł Dawid i wszystek lud, który był przy nim, z Baala Judowego, aby przenieśli stamtąd skrzynię Bożą, przy której wzywano imienia Pana zastępów, siedzącego na Cherubinach, którzy są na niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'I wstawili skrzynię Bożą na wóz nowy, wziąwszy ją z domu Abinadabowego, który jest w Gabaa; lecz Oza i Achyjo, synowie Abinadabowi, prowadzili on wóz nowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'I wzięli ją z domu Abinadaba, który był w Gabaa, a szli z skrzynią Bożą; lecz Achyjo szedł przed skrzynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'Dawid zasię i wszystek Izrael grali przed Panem na wszelakich instrumentach z cedrowego drzewa, na harfach i na skrzypcach, i na bębnach, i na piszczałkach, i na cymbałach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'A gdy przyszli do gumna Nachonowego, ściągnął Oza rękę swoję ku skrzyni Bożej, i zadzierżał ją: bo woły były wystąpiły z drogi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'Przetoż rozgniewał się bardzo Pan na Ozę, i zabił go tam Bóg dla śmiałości, i tamże umarł przy skrzyni Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'I zafrasował się Dawid, że Pan srodze zaraził Ozę, i nazwał miejsce ono Perezoza, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'A tak uląkł się Dawid Pana dnia onego, i mówił: Jakoż wnijdzie do mnie skrzynia Pańska?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'Przetoż nie chciał Dawid wprowadzić do siebie skrzyni Pańskiej do miasta swego, ale ją kazał wprowadzić do domu Obededoma Gietejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'I została skrzynia Pańska w domu Obededoma Gietejczyka przez trzy miesiące, i błogosławił Pan Obededomowi, i wszystkiemu domowi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'I oznajmiono królowi Dawidowi, mówiąc: Błogosławi Pan domowi Obededoma, i wszystkiemu, co ma, dla skrzyni Bożej. Tedy szedłszy Dawid, wziął skrzynię Bożą z domu Obededoma do miasta Dawidowego z weselem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'A gdy ci, którzy nieśli skrzynię Pańską, postąpili na sześć kroków, ofiarował wołu i barana tłustego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'I skakał Dawid ze wszystkiej mocy przed Panem, a był Dawid obleczony w efod lniany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'A tak Dawid, i wszystek dom Izraelski prowadzili skrzynię Pańską z weselem, i z trąbieniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'I stało się, gdy skrzynia Pańska wchodziła do miasta Dawidowego, że Michol, córka Saulowa, wyglądając oknem, a widząc króla Dawida ze wszystkiej mocy skaczącego przed Panem, wzgardziła go w sercu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'A gdy przynieśli skrzynię Pańską, postawili ją na miejscu swem pośrodku namiotu, który był dla niej rozbił Dawid, i ofiarował Dawid przed Panem całopalenia i spokojne ofiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'A gdy dokończył Dawid ofiarować całopalenia, i ofiar spokojnych, błogosławił ludowi w imię Pana zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'I dał między wszystek lud, i między wszystko zgromadzenie Izraelskie, od męża aż do niewiasty, każdemu bochenek chleba jeden, i jednę sztukę mięsa, i łagiew jednę wina. I odszedł wszystek lud, każdy do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Potem wrócił się Dawid, aby błogosławił domowi swemu. I wyszła Michol, córka Saulowa, przeciwko Dawidowi, a rzekła: O jakoż chwalebny był dziś król Izraelski, który się odkrywał dziś przed oczyma służebnic sług swoich, jako się zwykł odkrywać jeden z szalonych!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'Tedy rzekł Dawid do Michol: Przed Panem (który mnie raczej obrał niż ojca twego, i niżeli wszystek dom jego, rozkazując mi, abym był książęciem nad ludem Pańskim, nad Izraelem.) grałem, i będę grał przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'A im będę podlejszym, niżelim się stał i uniżeńszym w oczach moich, tem u tych służebnic, o których mi powiadasz, będę chwalebniejszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'Przetoż Michol, córka Saulowa, niemiała dziatek aż do dnia śmierci swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'I stało się, gdy siedział król w domu swym, a Pan mu dał odpocznienie zewsząd od wszystkich nieprzyjaciół jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'Że rzekł król do Natana proroka: Obacz proszę, ja mieszkam w domu cedrowym, a skrzynia Boża mieszka między kortynami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'Tedy rzekł Natan do króla: Cokolwiek jest w sercu twojem, idź, uczyń; bo Pan jest z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'Potem onejże nocy stało się słowo Pańskie do Natana, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Idź a mów do sługi mego Dawida: Tak mówi Pan: Izali mi ty zbudujesz dom ku mieszkaniu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Ponieważem nie mieszkał w domu ode dnia, któregom wywiódł syny Izraelskie z Egiptu, aż do dnia tego, alem chodził w namiocie i w przybytku;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'I wszędzie, gdziem chodził ze wszystkimi syny Izraelskimi, izalim i słowo rzekł któremu z sędziów Izraelskich, któremum rozkazał paść lud mój Izraelski, mówiąc: Czemużeście mi nie zbudowali domu cedrowego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Przetoż teraz to powiedz słudze memu Dawidowi: Tak mówi Pan zastępów: Jam ciebie wziął z owczarni od owiec, abyś był wodzem nad ludem moim, nad Izraelem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'I byłem z tobą wszędy, gdzieśkolwiek chodził, i wygładziłem wszystkie nieprzyjacioły twoje przed tobą, i uczyniłem ci imię wielkie, jako imię wielkich ludzi, którzy są na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'I postanowię miejsce ludowi memu Izraelskiemu, i wszczepię go, iż będzie mieszkał na miejscu swem, i nie będzie więcej poruszony, ani go więcej synowie nieprawości trapić będą, jako przedtem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'Ode dnia, któregom postanowił sędzie nad ludem moim Izraelskim; i dam ci odpocznienie ode wszystkich nieprzyjaciół twoich. Przetoż opowiadać Pan, że on sam tobie dom zbuduje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Gdy się wypełnią dnia twoje, i zaśniesz z ojcy twoimi, wzbudzę nasienie twoje po tobie, które wynijdzie z żywota twego, a umocnię królestwo jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'On zbuduje dom imieniowi memu, a Ja utwierdzę stolicę królestwa jego aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Ja mu będę za ojca, a on mi będzie za syna, który gdy wystąpi, skarzę go rózgą ludzką, i plagami synów człowieczych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Lecz miłosierdzie moje nie będzie odjęte od niego, jakom je odjął od Saula, któregom odrzucił przed twarzą twoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'I będzie utwierdzony dom twój, i królestwo twoje aż na wieki przed tobą, a stolica twoja będzie trwała aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Według wszystkich słów tych, i według wszystkiego widzenia tego, tak mówi Natan do Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Tedy wszedłszy król Dawid, usiadł przed obliczem Pańskiem, i rzekł: Cożem ja jest Panie Boże, i co za dom mój, żeś mię przywiódł aż dotąd?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'Lecz i to mało było przed oblicznością twoją, Panie Boże; aleś też obietnicę uczynił o domie sługi twego na czas daleki, a to prawie obyczajem ludzkim, Panie Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'I cóż więcej ma mówić Dawid przed tobą? albowiem ty znasz sługę twego, o Panie Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Dla słowa twego, a według serca twego uczyniłeś te wszystkie wielkie rzeczy, oznajmując je słudze twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Przetoż wielmożnym jesteś, Panie Boże; bo nie masz podobnego tobie, i nie masz Boga oprócz ciebie, według wszystkiego, cośmy słyszeli w uszy nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'I gdzież jest taki lud na ziemi, jako Izrael? dla któregoby Bóg szedł aby go sobie odkupił za lud, i uczynił sobie imię, i sprawił wam wielkie i straszne rzeczy w ziemi twojej, przed obliczem ludu twego, któryś sobie wykupił z Egiptu, z pogaństw a i z bogów ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'I zmocniłeś sobie lud twój Izraelski, abyć był ludem aż na wieki; a ty Panie stałeś się im za Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Przetoż teraz, o Panie Boże, słowo, któreś powiedział o słudze twoim i o domu jego, utwierdź aż na wieki, a uczyń tak jakoś mówił,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Aby uwielbione było imię twoje aż na wieki, żeby mówiono: Pan zastępów Bogiem nad Izraelem, a dom sługi twego Dawida będzie umocniony przed twarzą twoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Albowiem ty Panie zastępów, Boże Izraelski, objawiłeś słudze twemu, mówiąc: Dom zbuduję tobie. Przetoż za słuszną rzecz znalazł sługa twój w sercu swojem, aby się modlił tobie tą modlitwą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'Teraz tedy, Panie Boże, tyś sam Bóg, a słowa twe są prawdą, i rzekłeś do sługi twojego te dobre rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'Raczże już teraz błogosławić domowi sługi twego, aby trwał na wieki przed tobą; boś ty Panie Boże rzekł: Że błogosławieństwem twojem będzie ubłogosławion dom sługi twego na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'I stało się potem, że poraził Dawid Filistyny, i poniżył je; a wziął Dawid Meteg Amma z rąk Filistyńskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Poraził też i Moabity, które pomierzył sznurem, zrównawszy je z ziemią, i wymierzył ich dwa sznury na zabicie, a cały sznur na zachowanie przy żywocie; i byli Moabitowie sługami Dawidowymi, przynosząc mu podatki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'Poraził też Dawid Hadadezera, syna Rochobowego, króla Soby, gdy wyjechał, aby rozprzestrzenił granice swe nad rzeką Eufrates.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'I pojmał z nich Dawid tysiąc i siedm set jezdnych, a dwadzieście tysięcy ludu pieszego. I poderznął Dawid żyły wszystkim woźnikom, zachowawszy koni do sta wozów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'Przyciągnął tedy Syryjczyk z Damaszku na pomoc Hadadezerowi, królowi Soby, i poraził Dawid Syryjczyków dwadzieścia i dwa tysiące mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'I osadził Dawid żołnierzem Syryją Damaską. A tak Syryjczycy byli sługami Dawidowymi, przynosząc mu podatki; i bronił Pan Dawida wszędzie gdziekolwiek się obrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'Pobrał też Dawid tarcze złote, które mieli słudzy Hadadezerowi, i wniósł je do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'Przytem z Betachu i z Berotu, miast Hadadezerowych, przyniósł król Dawid bardzo wiele miedzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'To usłyszawszy Tohy, król Emat, iż poraził Dawid wszystko wojsko Hadadezerowe,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'Posłał Tohy Jorama, syna swego, do króla Dawida, aby go pozdrowił w pokoju, i winszował mu, przeto że zwalczył Hadadezera, i poraził go, (albowiem walczył z Tohym Hadadezer,) i przyniósł z sobą naczynia srebrne, i naczynia złote, i naczynia miedziane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'Które też rzeczy poświęcił król Dawid Panu z innem srebrem i złotem, które był poświęcił, pobrawszy od wszystkich narodów, które sobie podbił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'Jako od Syryjczyków, i od Moabczyków, i od synów Ammonowych, i od Filistynów, i od Amalekitów, i z łupów Hadadezera, syna Rochobowego, króla Soby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'A tak uczynił sobie Dawid imię, gdy się wrócił poraziwszy Syryjczyki w dolinie solnej, gdzie pobił ośmnaście tysięcy ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'Postanowił też straż w Edom, wszystkę ziemię Edomską osadziwszy żołnierzami; i byli wszyscy Edomczycy sługami Dawidowymi, a bronił Pan Dawida wszędzie, gdzie się obrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'I królował Dawid nad wszystkim Izraelem, i czynił sąd i sprawiedliwość wszystkiemu ludowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'A Joab, syn Sarwii, był nad wojskiem, a Jozafat syn Ahiluda, kanclerzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'A Sadok, syn Achitoba, i Achimelech, syn Abijatara, byli kapłanami, a Saraja pisarzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'Banajas też, syn Jojada, nad Cheretczykami i Feletczykami, a synowie Dawidowi byli książętami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'Tedy rzekł Dawid: Jestże jeszcze kto, coby pozostał z domu Saulowego, abym uczynił nad nim miłosierdzie dla Jonatana?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'I był z domu Saulowego sługa, którego zwano Syba: tego zawołano do Dawida. I rzekł król do niego: Tyżeś jest Syba? A on odpowiedział: Jam jest, sługa twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'Potem rzekł król: Jestże jeszcze kto z domu Saulowego, abym nad nim uczynił miłosierdzie Boże? Odpowiedział Syba królowi: Jest jeszcze syn Jonatana, chromy na nogi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'I rzekł do niego król: Gdzieli jest? A Syba odpowiedział królowi: Oto, jest w domu Machira, syna Ammijelowego, w Lodebarze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Przetoż posłał król Dawid, i wziął go z domu Machira, syna Ammijelowego z Lodebaru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'A gdy przyszedł Mefiboset, syn Jonatana, syna Saulowego, do Dawida, upadł na oblicze swe, i pokłonił się. I rzekł Dawid: Mefibosecie! Który odpowiedział: Oto, sługa twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'I rzekł do nigo Dawid: Nie bój się: bo zapewne uczynię z tobą miłosierdzie dla Jonatana, ojca twego, i przywrócęć wszystkę rolą Saula, dziada twego. a ty będziesz jadł chleb u stołu mego zawżdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'Tedy ukłoniwszy się, rzekł: Coż jest sługa twój, żeś się obejrzał na psa zdechłego, jakom ja jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Zatem wezwał król Syby, sługi Saulowego i rzekł mu: Cokolwiek miał Saul, i wszystek dom jego, dałem synowi pana twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Będziesz tedy sprawował rolą jego, ty, synowie twoi, i słudzy twoi, a będziesz dodawał, aby miał chleb syn pana twego, któryby jadł; ale Mefiboset, syn pana twego, będzie zawżdy jadał chleb u stołu mego. A Syba miał piętnaście synów i dwadzieścia sług.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'I odpowiedział Syba królowi: Wszystko, co rozkazał król, pan mój, słudze swemu, tak uczyni sługa twój, aczkolwiek Mefiboset mógłby jadać u stołu mego, jako jeden z synów królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Miał też Mefiboset syna małego, imieniem Micha; a wszyscy, którzy mieszkali w domu Sybowym, byli sługami Mefibosetowymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'A tak Mefiboset mieszkał w Jeruzalemie, bo on u stołu królewskiego zawżdy jadał; a był chromy na obie nogi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'I stało się potem, że umarł król synów Ammonowych, a królował Hanon, syn jego, po nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'Tedy rzekł Dawid: Uczynię miłosierdzie z Hanonem, synem Nahasowym, jako uczynił ojcec jego miłosierdzie ze mną.I posłał Dawid ciesząc go przez sługi swe po ojcu jego, a tak przyszli słudzy Dawidowi do ziemi synów Ammonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'Ale książęta synów Ammonowych rzekły do Hanona, pana swego: I mniemasz, żeby to uczciwość czynił Dawid ojcu twemu, iż przysłał do ciebie tych, którzyby cię cieszyli? Azaż raczej nie dla tego posłał Dawid sługi swe do ciebie aby przepatrzyli miasto, i wyszpiegowali je, aby je potem zburzył?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'A tak wziąwszy Hanon sługi Dawidowe, ogolił im po połowie brody ich, i poobrzynał szaty ich aż do połowy, aż do zadków ich, i puścił je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'A gdy to opwiedziano Dawidowi, posłał przeciwko nim,(ponieważ oni mężowie byli bardzo obelżeni,) i rzekł im król: Zostńcie w Jerycho, aż odrosną brody wasze, a potem się wrócicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'Widząc tedy synowie Ammonowi, że się zbrzydzili Dawidowi posłali ciż synowie Ammonowi, i najęli za pieniądze Syryjczyka z domu Rechob, i Syryjczyka w Soba, dwadzieścia tysięcy pieszych, a od króla Maacha tysiąc mężów, a od Istoba dwanaście tysięcy mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Co gdy usłyszał Dawid, posłał Joaba ze wszystkiem wojskiem ludzi rycerskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'Tedy synowie Ammonowi wyciągnęli, a uszykowali się do bitwy przed samem wejściem w bramę; Syryjczyk zasię z Soby, i Rechob, i Istob, i Maacha byli osobno w polu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Przetoż widząc Joab uszykowane wojska przeciwko sobie z przodku i z tyłu, wybrał niektóre ze wszystkich przebranych z Izraela, i uszykował wojsko przeciwko Syryjczykom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'A ostatek ludu dał pod rękę Abisaja, brata swego, i uszykował je przeciwko synom Ammonowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'I rzekł: Jeźli mi Syryjczycy będą silnymi, będziesz mi na pomoc, a jeźli tobie synowie Ammonowi będą silnymi przyjdęć na pomoc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Zmacniaj się, a bądźmy mężnymi za lud nasz, i za miasto Boga naszego, a Pan niech uczyni, co dobrego jest w oczach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'Nastąpił tedy Joab, i lud, który był z nim, aby zwiódł bitwę z Syryjczykami; a oni uciekali przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Tedy synowie Ammonowi ujrzawszy, że uciekli Syryjczycy; uciekli i oni przed Abisajem, i weszli do miasta. A Joab wrócił się od synów Ammonowych, i przyszedł do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'A gdy obaczyli Syryjczycy, iż są porażeni od Izraela, zebrali się wespół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'I posłał Hadadezer, a wywiódł Syryjczyki, którzy byli za rzeką, i przyciągnęli do Helam, a Sobach, hetman wojska Hadadezerowego prowadził je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'I oznajmiono to Dawidowi; który zebrawszy wszystkiego Izraela, przeprawił się przez Jordan, i przyszedł do Helam, gdzie uszykowawszy wojsko Syryjczycy przeciw Dawidowi, zwiedli z nim bitwę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'Tedy uciekli Syryjczycy przed Izraelem, i poraził Dawid Syryjczyków siedm set wozów, i czterdzieści tysięcy jezdnych; do tego Sobacha, hetmana wojska ich, ranił, który tamże umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'A gdy ujrzeli wszyscy królowie, hołdownicy Hadadezerowi, iż porażeni byli od Izraela, uczynili pokój z Izraelem, i służyli im; i bali się Syryjczycy dawać pomocy na potem synom Ammonowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'I stało się po roku tego czasu, gdy zwykli królowie wyjeżdżać na wojnę, posłał Dawid Joaba, i sługi swoje z nim, i wszystkiego Izraela, aby pustoszyli syny Ammonowe. I oblegli Rabbę, a Dawid został w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'I stało się przed wieczorem, gdy wstał Dawid z łoża swego, a przechadzał się po dachu domu królewskiego, że ujrzał z dachu niewiastę, myjącą się; a ta niewiasta była bardzo piękna na wejrzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'Tedy posłał Dawid, pytając się o onej niewieście, i rzekł: Azaż to nie Betsabee, córka Elijamowa, żona Uryjasza Hetejczyka?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'Posłał tedy Dawid posły, i wziął ją. Która gdy weszła do niego, spał z nią; a ona się była oczyściła od nieczystoty swojej: potem wróciła się do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'I poczęła ona niewiasta, a posławszy oznajmiła Dawidowi, i rzekła: Jam brzemienną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'I posłał Dawid do Joaba mówiąc: Poślij do mnie Uryjasza Hetejczyka. I posłał Joab Uryjasza do Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'A gdy przyszedł Uryjasz do niego, pytał go Dawid jakoby się powodziło Joabowi, i jakoby się powodziło ludowi, i jakoby się powodziło wojsku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'Nadto rzekł Dawid do Uryjasza: Idź do domu twego, a umyj nogi twoje. I wyszedł Uryjasz z domu królewskiego, a niesiono za nim potrawy królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Ale Uryjasz spał przede drzwiami domu królewskiego ze wszystkimi sługami pana swego, i nie szedł do domu swojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'I opowiedziano Dawidowi, mówiąc: Nie szedłci Uryjasz do domu swego. I rzekł Dawid do Uryjasza: Azażeś ty nie z drogi przyszedł? przeczżeś wżdy nie szedł do domu twego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'I rzekł Uryjasz do Dawida: Skrzynia Boża, i Izrael, i Juda zostawają w namiotach, a pan mój Joab, i słudzy pana mego w polu obozem leżą, a jabym miał wnijść do domu mego, abym jadł, i pił, i spał z żoną swą? Jakoś ty żyw, i jako żywa dusza twoja, żeć tego nie uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'Tedy rzekł Dawid do Uryjasza: Zostańże tu jeszcze dziś, a jutro cię odprawię. I został Uryjasz w Jeruzalemie przez on dzień, i nazajutrz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'Potem go wezwał Dawid, aby jadł i pił przed nim, i upoił go: wszakże wyszedłszy w wieczór, spał na łożu swojem z sługami pana swego, a do domu swego nie wszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'A gdy było rano, napisał Dawid list do Joaba, i posłał go przez ręce Uryjasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'A w liście napisał te słowa: Postawcie Uryjasza na czele bitwy najtęższej; między tem odstąpcie nazad od niego, aby będąc raniony umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'I stało się, gdy obległ Joab miasto, postawił Uryjasza na miejscu, kędy wiedział, że byli mężowie najmocniejsi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'A wypadłszy mężowie z miasta, stoczyli bitwę z Joabem, i poległo z ludu kilka sług Dawidowych, poległ też Uryjasz Hetejczyk,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Tedy posłał Joab, i oznajmił Dawidowi wszystko, co się stało w bitwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'A rozkazał posłowi, mówiąc: Gdy wypowiesz królowi, co się stało w bitwie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'Tedy jeźliby się król rozgniewał, a rzekłciby: Przeczżeście tak blisko przystąpili do miasta ku bitwie? azażeście nie wiedzieli, iż ciskają z muru?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Któż zabił Abimelecha, syna Jerubbesetowego? izali nie niewiasta zrzuciwszy nań sztukę kamienia młyńskiego z muru, tak że umarł w Tebes? przeczżeście przystępowali do muru? Tedy rzeczesz: Sługa też twój Uryjasz Hetejczyk poległ.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'A tak poszedł poseł, i przyszedłszy oznajmił Dawidowi wszystko, z czem go był posłał Joab.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'I rzekł on poseł do Dawida: Zmocnili się przeciwko nam mężowie, i wyszli przeciwko nam w pole, a goniliśmy je aż do samej bramy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'Wtem strzelili strzelcy na sługi twoje z muru, i zabito kilka sług królewskich, tamże i sługa twój Uryjasz Hetejczyk poległ.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'Tedy rzekł Dawid do posła: Tak powiesz Joabowi: Niech ci to serca nie psuje, boć tak miecz to tego, to owego pożera; następuj potężnie na miasto, i burz je, a dodawaj serca rycerstwu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'A usłyszawszy żona Uryjaszowa, iż umarł Uryjasz, mąż jej, płakała męża swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'A gdy wyszła żałoba, posłał Dawid, i wziął ją w dom swój, i była mu za żonę, i porodziła mu syna. Ale to była zła rzecz, którą uczynił Dawid przed oczyma Pańskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'Przetoż posłał Pan Natana do Dawida; który przyszedłszy do niego, rzekł mu: Dwaj mężowie byli w jednem mieście, jeden bogaty a drugi ubogi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Bogaty miał owiec i wołów bardzo wiele;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'A ubogi nie miał jedno owieczkę jednę małą, którą był kupił, i chował ją, aż urosła przy nim, także i przy dziatkach jego; z bochna jego jadała, i z kubka jego pijała, i na łonie jego sypiała, a była mu jako córka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'A gdy przyszedł gość do onego męża bogatego, żałował wziąć z owiec swoich albo z wołów swoich, aby nagotował ucztę gościowi, który był do niego przyszedł: ale wziął owieczkę męża onego ubogiego, i nagotował ją mężowi, który był do niego przyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'Tedy zapaliwszy się gniewem Dawid na onegoż męża bardzo,rzekł do Natana: Jako żywy Pan, że godzien śmierci jest mąż, który to uczynił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'Owcę tę nagrodzi czworako, przeto iż to uczynił, a nie żałował go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'I rzekł Natan do Dawida: Tyś jest tym mężem. Tak ci mówi Pan, Bóg Izraelski: Jam cię pomazał, abyś był królem nad Izraelem, i Jam cię wyrwał z rąk Saulowych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'A podałem ci dom pana twego i żony pana twego na łono twoje; nadto oddałem ci dom Izraelski i Judzki, a byłoliby to mało, przydałbym ci był daleko więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Czemużeś znieważył słowo Pańskie, czyniąc to złe przed oczyma jego? Uryjasza Hetejczyka zabiłeś mieczem, a żonę jego wziąłeś sobie za żonę, a samegoś zabił mieczem synów Ammonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Przetoż teraz nie odejdzie miecz z domu twego aż na wieki, dlatego, iżeś mię znieważył, a wziąłeś żonę Uryjasza Hetejczyka, abyć była za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Tak mówi Pan: Oto, Ja wzbudzę przeciwko tobie złe z domu twego, a pobrawszy żony twe przed oczyma twemi, dam je bliźniemu twemu, a bądzie jawnie spał z żonami twojemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'A chociażeś to ty uczynił potajemnie, Ja jednak uczynię to przed wszystkim Izraelem, i przed słońcem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'Tedy rzekł Dawid do Natana: Zgrzeszyłem Panu. Zaś rzekł Natan do Dawida: Pan też przeniósł grzech twój, nie umrzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Wszakże iżeś dał przyczynę, aby urągali nieprzyjaciele Pańscy dla tej sprawy, przetoż syn, któryć się urodził, pewnie umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'Potem odszedł Natan do domu swego. Wtem zaraził Pan dziecię, które była urodziła żona Uryjaszowa Dawidowi, i zwątpiono o niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'Tedy się modlił Dawid Bogu za dziecięciem i pościł, a wszedłszy do pokoju, leżał przez noc na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'I przyszli starsi domu jego do niego aby go podnieśli z ziemi; ale niechciał, i nie jadł z nimi chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'I stało się dnia siódmego, że umarło dziecię. A obawiali się słudzy Dawidowi, oznajmić mu, iż umarło dziecię, bo mówili: Oto, póki jeszcze dziecię było żywę, mówiliśmy z nim, a nie słuchał głosu naszego; cóż gdy mu powiemy: Umarło dziecię, dopier oż się będzie trapił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'A widząc Dawid, że słudzy jego szeptali z sobą, porozumiał Dawid, iż umarło dziecię. I rzekł Dawid do sług swoich: Albo umarło dziecię? A oni odpowiedzieli: Umarło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Tedy wstawszy Dawid z ziemi, umył się, i namazał się, i odmienił szaty swoje,a wszedłszy do domu Pańskiego, modlił się; potem wróciwszy się do domu swego, kazał sobie dać jeść, i położono przedeń chleb, i jadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'I rzekli słudzy jego do niego: Cóż to jest, coś uczynił? Dla dzicięcia,póki jeszcze żyło, pościłeś i płakałeś, a gdy umarło dziecię, wstałeś i jadłeś chleb?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'A on rzekł: Póki jeszcze dziecię żyło, pościłem i płakałem; bom mówił: Któż wie, nie zmiłujeli się Pan nademną, że będzie żywe dziecię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Ale teraz, gdy już umarło, przeczżebym miał pościć? Izali je mogę jeszcze nazad wrócić? Ja pójdę do niego, ale się ono nie wróci do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'I cieszył Dawid Betsabeę, żonę swą, a wszedłszy do niej, spał z nią. I porodziła syna, i nazwał imię jego Salomon, a Pan go miłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'Przetoż posłał Natana proroka, i nazwał imię jego Jedydyja, dla Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Potem walczył Joab przeciw Rabbie synów Ammonowych, i wziął miasto królewskie');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'A posławszy Joab posły do Dawida, rzekł: Walczyłem przeciw Rabbie i wziąłam miasto wód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Przetoż teraz zbierz ostatek ludu, a połóż się obozem przeciwko miastu, i weźmij je, bym ja snać nie wziął miasta tego, a przypisanoby zwycięstwo imieniowi memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'A tak zebrał Dawid wszystek lud, i ciągnął przeciw Rabbie, i dobywał go, a wziął je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'Wziął też koronę króla ich z głowy jego, która ważyła talent złota, a kamień drogi był na niej; i włożono ją na głowę Dawidowę, a łupów z miasta wyniósł bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Lud też, który był w mieście, wywiódłszy, podał pod piły, i pod brony żelazne, i pod siekiery żelazne, i wegnał je w piec cegielny. A tak uczynił wszystkim miastom synów Ammonowych; i wrócił się Dawid, i wszystek lud jego do Jeruzalem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'I stało się potem, że Absalom syn Dawida, miał siostrę piękną, imieniem Tamar, której się rozmiłował Amnon, syn Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'I trapił się Amnon tak, że zachorował dla Tamary, siostry swojej; bo panną była, i trudno się zdało Amnonowi, aby jej co miał uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Lecz Amnon miał przyjaciela, którego zwano Jonadab, syn Semmy, brata Dawidowego; a ten Jonadab był mężem bardzo mądrym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'Który mu rzekł: Czumuż tak schniesz, synu królewski, ode dnia do dnia? czemuż mi nie oznajmisz? Tedy mu rzekł Amnon: Romiłowałem się Tamary siostry Absaloma, brata mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'I rzekł mu Jonadab: Układź się na łóżku twojem, a uczyń się chorym; a gdy przyjdzie ojciec twój, aby cię nawiedził, rzeczesz mu: Niech przyjdzie proszę Tamar, siostra moja, i da mi jeść, a nagotuje przed oczyma memi potrawę, abym widział a jadł z ręki jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Tedy się układł Amnon, zmyślając sobie chorobę. A gdy przyszedł król nawiedzać go, rzekł Amnon do króla: Niech przyjdzie proszę Tamar, siostra moja, aby zgotowała przed oczyma memi dwa placki, abym jadł z ręki jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Przetoż posłał Dawid do Tamary w dom, mówiąc: Idź zaraz do domu Amnona, brata twego, a nagotuj mu potrawę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Przyszła tedy Tamar do domu Amnona, brata swego, a on leżał; a wziąwszy mąki rozmąciła, i uczyniła placki przed oczyma jego, i upiekła je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Potem wziąwszy panewkę, wyłożyła przedeń; ale nie chciał jeść. I rzekł Amnon: Każcie wyjść precz wszystkim odemnie; a tak wyszli wszyscy od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'Tedy rzekł Amnon do Tamary: Przynieś sama tę potrawę do pokoju, abym jadł z ręki twej. A tak wziąwszy Tamara placki, które nagotowała, przyniosła je przed Amnona, brata swego, do pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'A gdy mu podawała, aby jadł, uchwyciwszy ją, rzekł do niej: Pójdź, leż ze mną, siostro moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Która mu rzekła: Zaniechaj, bracie mój, a nie czyń mi gwałtu, bo się niema dziać nic takiego w Izraelu; nie czyńże tego szaleństwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Bo gdzieżebym się obróciła z zelżywością moją? a ty będziesz jako jeden z szalonych w Izraelu. Ale raczej mów proszę z królem; bo mię nie odmówi tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Lecz on nie chciał usłuchać głosu jej, ale zmógłszy ją, uczynił jej gwałt, i leżał z nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Potem nienawidział jej Amnon nienawiścią bardzo wielką, tak iż większa była nienawiść, którą ją nienawidział, niż miłość, którą ją pierwej miłował. I rzekł jej Amnon: Wstań, idź precz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Która mu odpowiedziała: Dlatego to większa złość, niż owa, którąś zemną popełnił, że mię wyganiasz. Ale jej on nie chciał usłuchać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'Owszem zawoławszy chłopca swego, który mu posługiwał, rzekł: Wywiedźcie tę zaraz precz odemnie, a zamknij drzwi za nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, '(Ale ona miała na sobie pstrą suknią; albowiem w takowych sukniach chadzały córki królewskie, panny,) i wywiódł ją precz sługa jego, i zawarł drzwi za nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'Tedy posypała Tamar popiołem głowę swą, a pstrą szatę, która była na niej, rozdarła, i włożywszy rękę swą na głowę swoję, poszła, a idąc krzyczała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'I rzekł do niej Absalom, brat jej: Albo Amnon, brat twój, był z tobą? Milczże, siostro moja; brat twój jest, nie przypuszczaj tego do serca swego. A tak mieszkała Tamar będąc opuszczona, w domu Absaloma, brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'A król Dawid usłyszawszy o tem wszystkiem, rozgniewał się bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'I nie mówił Absalom z Amnonem ani źle ani dobrze; bo nienawidział Absalom Amnona, przeto że zgwałcił Tamarę, siostrę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'I stało się po wyjściu dwóch lat, gdy strzyżono owce Absalomowe w Baalchasor, które jest w Efraim, że wyzwał Absalom wszystkich synów królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'Bo przyszedł Absalom do króla i rzekł: Oto teraz strzygę owce słudze twemu; niech idzie proszę król i słudzy jego z sługą twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'I rzekł król do Absaloma: Nie, synu mój; niech teraz nie chodzimy wszyscy, abyśmy cię nie obciążyli. A choć mu przynaglał, nie chciał iść, ale mu błogosławił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Rzekł potem Absalom: Ponieważ ty nie chcesz, niechże idzie proszę z nami Amnon, brat mój. I rzekł mu król: A pocóżby miał iść z tobą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'A gdy nań nalegał Absalom, posłał z nim Amnona i wszystkie syny królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Tedy przykazał Absalom sługom swoim, mówiąc: Pilnujcie proszę, gdy podweseli serce swoje Amnon winem, a rzekę do was: Bijcie Amnona, zabijcież go, nie bójcie się, bom ja wam rozkazał; zmocnijcież się, a mężnie sobie pocznijcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'I uczynili słudzy Absalomowi Amnonowi, jako im był rozkazał Absalom. Przetoż wstawszy wszyscy synowie królewscy, wsiedli każdy na muła swego, i uciekali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'Wtem gdy jeszcze byli w drodze, wieść przyszła do Dawida w te słowa: Pozabijał Absalom wszystkie syny królewskie, i nie został z nich ani jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Tedy wstał król i rozdarł szaty swoje, i padł na ziemię, a wszyscy słudzy jego stali około niego, rozdarłszy szaty swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'Ozwawszy się Jonadab syn Semmy, brata Dawidowego, rzekł: Niech nie mówi pan mój, że wszystkie młodzieńce, syny królewskie, pobito; boć tylko sam Amnon zabity, gdyż to w umyśle Absalomowym ułożono było od onego dnia, którego zgwałcił Tamarę, siost rę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Przetoż teraz niech nie przypuszcza tego król, pan mój, do serca swego, mówiąc: Wszyscy synowie królewscy polegli, gdyż tylko sam Amnon poległ.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Tedy uciekł Absalom; a podniósłszy sługa, który był na straży, oczy swe, ujrzał, a oto, lud wielki przychodził drogą, którą chadzano do niego z boku góry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'I rzekł Jonadab do króla: Oto synowie królewscy jadą; wedle słowa sługi twego tak się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'A gdy przestał mówić, oto synowie królewscy przyszli, a podniósłszy głosy swe płakali; także i król, i wszyscy słudzy jego płakali płaczem bardzo wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Ale Absalom uciekłszy uszedł do Tolmaja, syna Ammihudowego, króla Giessur; i żałował Dawid syna swego po one wszystkie dni. A Absalom uciekł, i przyszedł do Giessur, a był tam przez trzy lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Potem pragnął król Dawid widzieć Absaloma; bo już był odżałował śmierci Amnonowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'A porozumiawszy Joab, syn Sarwii, że się serce królewskie obróciło ku Absalomowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'Posłał Joab do Tekuj, i wziął stamtąd niewiastę mądrą, i rzekł do niej: Proszę zmyśl, jakobyś w żałobie była, a oblecz się proszę w szaty żałobne, i nie namazuj się olejkiem, ale bądź jako niewiasta, która przez wiele dni w żałobie chodziła po uma rłym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'I wnijdziesz do króla, a będziesz mówiła do niego w ten sposób; i nauczył jej Joab, jako miała mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'Przetoż mówiła ona niewiasta Tekuitska do króla, upadłszy obliczem swem na ziemię, a pokłoniwszy się rzekła: Ratuj królu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'I rzekł jej król: Cóż ci? A ona odpowiedziała: Zaistem ja niewiasta wdowa; bo mi mąż mój umarł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'A służebnica twoja miała dwóch synów, którzy się powadzili z sobą na polu; a gdy nie był, ktoby je rozwadził, a ranił jeden drugiego, i zabił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'A oto, powstawszy wszystka rodzina przeciw służebnicy twojej, mówią: Wydaj tego, który zabił brata swego, że go zabijemy za duszę brata jego, którego zamordował, owszem zgładzimy i dziedzica; a tak zagaszą iskierkę moję, która pozostała, aby nie z ostawili mężowi memu imienia i szczątku na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Tedy rzekł król do niewiasty: Idź do domu twego, a ja skażę za tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'I odpowiedziała niewiasta Tekuicka królowi: Królu, panie mój, niech będzie na mnie ta nieprawość, i na dom ojca mego; ale król i stolica jego niech będzie niewinna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'I rzekł król: Będzieli kto mówił przeciwko tobie, przywiedź go do mnie, a potem nie tknie się ciebie więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Tedy ona rzekła: Wspomnij proszę, królu, na Pana Boga twego, aby się nie mnożyli mściciele krwi na zgubę, a nie zgładzili syna mego. I odpowiedział: Jako żywy Pan, że nie spadnie i najmniejszy włos syna twego na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Zatem rzekła niewiasta: Niech przemówi proszę służebnica twoja do króla, pana mego, słowo. A on rzekł: Mów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'Rzekła tedy niewiasta: I czemużeś umyślił podobną rzecz przeciw ludowi Bożemu? albowiem król mówi to słowo, jakoby był winny, ponieważ nie chcesz przywrócić, królu, wygnańca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Wszyscy umieramy, a jesteśmy jako wody rozlane po ziemi, które nie mogą być zebrane; lecz jemu Bóg nie odjął żywota, ale pewnie umyślił, aby nie wyganiał od siebie wygnańca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'A teraz, żem przyszła mówić do króla, pana mego, te słowa, przyczyną jest, że mię postraszył lud; przetoż rzekła służebnica twoja: Będę teraz mówiła do króla, snać co uczyni król na prośbę służebnicy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Albowiem usłyszy to król, i wybawi służebnicę swoję z rąk męża, który wygładzić chce mnie, i syna mego społem, z dziedzictwa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Rzekła też służebnica twoja: Wżdyć mi będzie słowo króla, pana mego, ku pociesze; albowiem jako Anioł Boży, tak jest król, pan mój, słuchając dobrego i złego, a Pan Bóg twój niech będzie z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'A odpowiadając król rzekł do niewiasty: Proszę nie taj przedemną tego, o co się spytam. I rzekła niewiasta: Mów proszę, królu, panie mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Tedy rzekł król: Izali ty tego wszystkiego nie czynisz z naprawy Joabowej? I odpowiedziała niewiasta, i rzekła: Jako żyje dusza twoja, królu, panie mój, że nie można uchylić się ani na prawo, ani na lewo od wszystkiego, co mówił król, pan mój; albowiem sługa twój Joab, on mi to rozkazał, i on nauczył służebnicy twojej tych wszystkich słów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Żem odmieniła sposób tej mowy, sprawił to sługa twój Joab; lecz pan mój mądry jest, jako jest mądry Anioł Boży, wiedząc wszystko, co się dzieje na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'Przetoż rzekł król do Joaba: Otom teraz to uczynił. Idźże a przywróć dziecię me Absaloma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'I upadł Joab obliczem swem na ziemię, a pokłoniwszy się błogosławił królowi, i rzekł Joab: Dziś poznał sługa twój, żem znalazł łaskę w oczach twoich, królu, panie mój, ponieważ uczynił król zadość prośbie sługi swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'Wstał tedy Joab, a szedł do Giessur, i przywiódł Absaloma do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'I rzekł król: Niech się wróci do domu swego, ale oblicza mego niech nie widzi. A tak wrócił się Absalom do domu swego, ale oblicza królewskiego nie widział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'A nie było męża tak krasnego, jako Absalom we wszystkim Izraelu, coby miał tak wielką chwałę; od stopy nogi jego aż do wierzchu głowy jego nie było na nim zmazy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'A gdy strzygł głowę swoję, (a zwykł ją na każdy rok strzydz; bo mu ciążyła, przetoż ją strzygł,) ważyły włosy głowy jego dwieście syklów wagi królewskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'I urodzili się Absalomowi trzej synowie, i córka jedna, której imię było Tamar, która niewiasta była piękna na wejrzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'I mieszkał Absalom w Jeruzalemie dwa lata, a twarzy królewskiej nie widział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Przetoż posłał Absalom do Joaba, chcąc go posłać do króla, ale on nie chciał przyjść do niego; posłał potem powtóre, i nie chciał przyjść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Tedy rzekł do sług swoich: Przepatrzcie rolę Joabową podle roli mojej, gdzie ma jęczmień; idźcież, a spalcie go ogniem. I zapalili słudzy Absalomowi rolę onę ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Zatem wstawszy Joab, przyszedł do Absaloma w dom, i rzekł do niego: Czemóż słudzy twoi spalili rolę moję ogniem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'I odpowiedział Absalom Joabowi: Otom posłał do ciebie, mówiąc: Przyjdź sam, a poślę cię do króla, abyś mówił: Nacóżem przyszedł z Giessur? Lepiej mi było tam jeszcze zostać; przetoż teraz niech oglądam oblicze królewskie; wszak jeźli jest przy mnie nieprawość, niech mię rozkaże zabić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Tedy przyszedł Joab do króla, i oznajmił mu. I przyzwał Absaloma, który przyszedł do króla, i ukłonił się twarzą swą ku ziemi przed królem; i pocałował król Absaloma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'I stało się potem, że sobie nasprawiał Absalom wozów, i koni, i pięćdziesiąt mężów, którzy chodzili przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'I wstawając rano Absalom stawał podle drogi u bramy, a każdego męża, mającego sprawę a idącego do króla na sąd, przyzywał Absalom do siebie, i mówił: Z któregożeś ty miasta? A gdy mu odpowiedział: Z jednego pokolenia Izraelskiego jest sługa twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Mówił mu Absalom: Oto, sprawa twoja dobra jest, i sprawiedliwa; ale niemasz, ktoby cię wysłuchał u króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Nadto mówił Absalom: O ktoby mię postanowił sędzią w tej ziemi! aby do mnie chodził każdy, któryby miał sprawę u sądu, dopomógłbym mu do sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'A gdy kto przystąpił, i ukłonił mu się, ściągnął rękę swą, a ująwszy go, całował go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'A toć czynił Absalom wszystkiemu Izraelowi, który przychodził na sądy do króla, i ukradał Absalom serca mężów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'I stało się po czterdziestu latach, że rzekł Absalom do króla: Niech idę proszę, a oddam ślub mój w Hebronie, którym poślubił Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Albowiem ślub poślubił sługa twój, kiedym mieszkał w Giessur Syryjskim, mówiąc: Jeźliże mię zasię kiedy przywróci Pan do Jeruzalemu, tedy służyć będę Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'I rzekł mu król: Idź w pokoju. A on wstawszy poszedł do Hebronu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Tedy rozesłał Absalom szpiegi między wszystkie pokolenia Izraelskie, aby rzekli: Skoro usłszycie głos trąby, mówcież: Króluje Absalom w Hebronie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'A z Absalomem poszło było dwieście mężów z Jeruzalemu zaproszonych, którzy szli w prostości swojej, niewiedząc o niczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'Posłał też Absalom po Achitofela Giloniczyka, radcę Dawidowego, aby przyszedł z miasta swego Gilo, gdy miał sprawować ofiary. I stało się sprzysiężenie wielkie, a lud się schodził, i przybywało go Absalomowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'Potem przyszedł poseł do Dawida, mówiąc: Obróciło się serce mężów Izraelskich za Absalomem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'Tedy rzekł Dawid do wszystkich sług swoich, którzy z nim byli w Jeruzalemie: Wstańcie, a uciekajmy; inaczej nieuszlibyśmy przed twarzą Absalomową. Spieszcież się, azaż ujdziem, by się snać nie pospieszył, a nie zajechał nas, i nie obalił na nas z łego, i nie wysiekł miasta ostrzem miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'I rzekli słudzy królewscy do króla: Wszystko, cokolwiek sobie upodoba król, pan nasz, oto słudzy twoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'A tak wyszedł król, i wszystek dom jego pieszo; tylko zostawił król dziesięć niewiast założnic, aby strzegły domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'A gdy wyszedł król i wszystek lud pieszo, stanęli na jednem miejscu z daleka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'Wszyscy też słudzy jego szli przy nim, i wszyscy Cheretczycy, i wszyscy Feletczycy, i wszyscy Gietejczycy, sześć set mężów, którzy byli przyszli pieszo z Giet, szli przed twarzą królewską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Tedy rzekł król do Itaja Gietejczyka: Czemuż i ty z nami idziesz? Wróć się, a zostań przy królu; boś ty cudzoziemiec, a nie długo wrócisz się do miejsca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Niedawnoś przyszedł, a dziśbym cię ruszyć miał, abyś z nami szedł? Gdyż ja idę, sam nie wiem dokąd; wróćże się, a odprowadź bracią swoję: niech będzie z tobą miłosierdzie i prawda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'Ale odpowiedział Itaj królowi, mówiąc: Jako żywy Pan, jako żywy też król pan mój, że na któremkolwiek miejscu będzie król, pan mój, choć w śmierci, choć w żywocie, tam też bądzie sługa twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'I rzekł Dawid do Itaja: Pójdźże, a przejdź. I przeszedł Itaj Gietejczyk, i wszyscy mężowie jego, i wszystkie dziatki, które były z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'Tedy wszystka ziemia płakała głosem wielkim, i wszystek lud, który przechodził. A tak król przeszedł przez potok Cedron, a wszystek lud przeszedł przeciw drodze ku puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'A oto i Sadok i wszyscy Lewitowie byli z nim, niosąc skrzynię przymierza Bożego, i postawili skrzynię Bożą; szedł też Abijater, aż wszystek on lud przeszedł z miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'I rzekł król do Sadoka: Odnieś zasię skrzynię Bożą do miasta. Jeźlić znajdę łaskę w oczach Pańskich, przywróci mię zasię, a ukaże mi ją, i przbytek swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'Ale jeźliby tak rzekł: Nie podobasz mi się; otom ja, niech mi uczyni, co dobrego jest w oczach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Nadto rzekł król do Sadoka kapłana: Izaliś nie jest widzącym? Wróćże się do miasta w pokoju, i Achimaas, syn twój, i Jonatan, syn Abijatara, dwaj synowie wasi, z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Oto, ja pomieszkam w równinach na puszczy, póki nie przyjdzie od was poselstwo dawające mi znać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'A tak odprowadzili zasię Sadok i Abijatar skrzynię Bożą do Jeruzalemu, i zostali tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'Ale Dawid szedł na górę oliwną wstępując i płacząc, mając głowę przykrytą, i idąc boso; wszystek też lud, który z nim był, zakryli każdy głowę swoję, a szli wstępując i płacząc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'Tedy dano znać Dawidowi, mówiąc: Achitofel jest z tymi, którzy się zbuntowali z Absalomem. I rzekł Dawid: O Panie, proszę, obróć w głupstwo radę Achitofelowę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'I stało się, gdy Dawid przyszedł aż na wierzch góry, aby się tam pomodlił Bogu, oto, spotkał się z nim Chusaj Arachita, miawszy rozdarte szaty swe, a proch na głowie swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'I rzekł mu Dawid: Jeźli pójdziesz ze mną, będziesz mi ciężarem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'Ale jeźli się do miasta wrócisz, a rzeczesz do Absaloma: Królu, sługą twoim będę, bom był sługą ojca twego zdawna, ale teraz jam sługą twoim: tedy mi obrócisz wniwecz radę Achitofelową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Azaż tam nie będzie z tobą Sadoka i Abijatara, kapłanów? Przetoż cokolwiek usłyszysz z domu królewskiego, oznajmisz Sadokowi i Abijatarowi, kapłanom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Są też tam z nimi dwaj synowie ich, Achimaas, syn Sadoka, i Jonatan, syn Abijatara, przez które dacie mi znać o wszystkiem, co jedno usłuszycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Szedł tedy Chusaj przyjaciel Dawida do miasta, a Absalom też wjechał do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'A gdy Dawid zszedł trochę z wierzchu góry, oto Syba, sługa Mefiboseta, zaszedł mu drogę z parą osłów osiodłanych, na których było dwieście chlebów, i sto wiązanek rodzynków, i sto wiązanek fig, i łagiew wina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'Tedy rzekł król do Syby: Na cóż to? I odpowiedział Syba: Osły te dla czeladzi królewskiej, aby na nich jeździła, a chleby i figi, aby jedli słudzy, a wino, aby pił, ktoby ustał na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'I rzekł mu król: A gdzież jest syn pana twego? I odpowiedział Syba królowi: Oto został w Jeruzalemie; albowiem mówił: Dziś mi przywróci dom Izraelski królestwo ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Zatem rzekł król do Syby: Oto twoje jest wszystko, cokolwiek miał Mefiboset. I rzekł Syba, pokłon uczyniwszy: Niech znajdę łaskę przed oczyma twemi, królu, panie mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'I przyszedł król Dawid aż do Bahurym, a oto, stamtąd mąż wyszedł z rodu domu Saulowego, a imię jego było Semej, syn Giery; który wyszedłszy, idąc złorzeczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'A ciskał kamieńmi na Dawida, i na wszystkie sługi króla Dawida, choć wszystek lud, i wszystko rycerstwo szło po prawej stronie jego, i po lewej stronie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'I tak mówił Semej, złorzecząc mu: Wynijdź, wynijdź mężu krwi, i mężu niezbożny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Obrócił na cię Pan wszystkę krew domu Saulowego, na któregoś miejscu królował, a podał Pan królestwo w ręce Absaloma, syna twego; a otoś ty we złem twojem, boś jest mężem krwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'I rzekł Abisaj, syn Sarwii, do króla: Czemuż złorzeczy ten zdechły pies królowi, panu memu? Niech idę proszę, a utnę głowę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Ale król rzekł: Cóż wam do tego, synowie Sarwii, że złorzeczy? Ponieważ mu Pan rzekł: Złorzecz Dawidowi, i któżby śmiał rzec: Czemu tak czynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'Nadto rzekł Dawid do Abisajego i do wszystkich sług swoich: Oto syn mój, który wyszedł z żywota mego, szuka duszy mojej, jakoż daleko więcej teraz syn Jemini? Zaniechajcie go, niech złorzeczy; boć mu Pan rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Snać wejrzy Pan na utrapienie moje, a odda mi Pan dobrem za złorzeczenia jego dzisiejsze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'A tak szedł Dawid, i mężowie jego drogą, a Semej szedł stroną góry przeciwko niemu, a idąc złorzeczył, i ciskał kamieńmi przeciw niemu, i miotał prochem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'I przyszedł król ze wszystkim ludem, który był przy nim spracowany, i tamże odpoczął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Lecz Absalom i wszystek lud mężów Izraelskich, przyszli do Jeruzalemu, także i Achitofel z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'A gdy szedł Chusaj Arachita, przyjaciel Dawida, do Absaloma, rzekł Chusaj do Absaloma: Niech żyje król, niech żyje król!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Tedy rzekł Absalom do Chusaja: A takaż to miłość twoja ku przyjacielowi twemu? przeczżeś nie szedł z przyjacielem twoim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Odpowiedział Chusaj Absalomowi: Nie; ale którego obrał Pan, i lud ten, i wszyscy mężowie Izraelscy, tego będę, i z nim zostanę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'Do tego, komuż ja będę służył? izali nie synowi jego? Jakom służył ojcu twemu, tak będę i tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'Rzekł potem Absalom do Achitofela: Radźcież, co mam czynić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Odpowiedział Achitofel Absalomowi: Wnijdź do założnic ojca twego, które zostały, aby strzegły domu; a usłyszawszy wszystek Izrael, żeś się omierzył ojcu twemu, zmocnią się ręce wszystkich, którzy są z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Przetoż rozbili Absalomowi namiot na dachu. I szedł Absalom do założnic ojca swego przed oczyma wszystkiego Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'A rada Achitofelowa, którą dawał, była na on czas w takiej wadze, jakoby się kto radził Boga. Takować była wszelka rada Achitofelowa, jako u Dawida, tak u Absaloma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Nadto rzekł Achitofel do Absaloma: Niech proszę wybiorę dwanaście tysięcy mężów, a wstawszy będę gonił Dawida tej nocy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'I przypadnę nań, pokąd jest spracowany i zemdlonych rąk, a strwożę go, i uciecze wszystek lud, który jest z nim, a zabiję króla samego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'A tak przywrócę wszystek lud do ciebie; bo jakoby się wszyscy ku tobie nawrócili, gdy zabiję tego męża, którego ty szukasz, a wszystek się lud uspokoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'I spodobało się to Absalomowi, i wszystkim starszym Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Jednak rzekł Absalom: Zawołaj rychło i Chusaja Arachity, abyśmy usłyszeli, co on też powie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'A gdy przyszedł Chusaj do Absaloma, rzekł Absalom do niego, mówiąc: Tak powiedział Achitofel: Mamyli uczynić według rady jego, czyli nie? i ty powiedz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'Tedy odpowiedział Chusaj Absalomowi: Niedobra jest rada, którą teraz dał Achitofel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Nadto rzekł Chusaj: Świadomyś ojca twego i mężów jego, iż są mężni, i serca zajuszonego, jako niedźwiedzica osierociała w polu; do tego ojciec twój jest mąż waleczny, i nie będzie nocował z ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'A podobno i teraz się kryje w jakiej jaskini, albo na któremkolwiek miejscu. I stałoby się, jeźliżeby kto z twoich poległ na tym początku, żeby każdy, ktoby o tem usłyszał, rzekł: Stała się porażka w ludzie, który szedł za Absalomem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Tedy i najmężniejszy, którego serce jako serce lwie, bardzo osłabieje; bo wie wszystek Izrael, że mężnym jest ojciec twój, i mężni wszyscy, którzy są z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Aleć radzę, aby się do ciebie cale zebrał wszystek Izrael od Dan aż do Beerseba, jako piasek, który jest przy morzu w mnóstwie, a ty żebyś osobą swoją szedł na wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'A tak pociągniemy przeciwko niemu, na któremkolwiek miejscu znaleziony będzie, i przypadniemy nań, jako pada rosa na ziemię, i nie zostanie z niego, to jest, z tych wszystkich mężów, którzy są z nim, ani jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'A jeźliżby do którego miasta uszedł, tedy zniesie wszystek Izrael do onego miasta powrozy, a pociągniemy je aż do potoku, tak iż tam nie będzie znalezion ani kamyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Tedy rzekł Absalom i wszyscy mężowie Izraelscy: Lepsza jest rada Chusajego Arachity, niż rada Achitofelowa. Albowiem Pan był postanowił, aby rozerwana była rada Achitofelowa, która była dobra, a tak aby przywiódł Pan złe na Absaloma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'I oznajmił Chusaj Sadokowi i Abijatarowi, kapłanom: Tak a tak radził Achitofel Absalomowi, i starszym Izraelskim; alem ja tak a tak radził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Teraz tedy poślijcie co rychlej, a oznajmijcie Dawidowi, mówiąc: Nie zostawaj tej nocy w równinach puszczy; ale bez odwłoki przejdź, by snać nie był pożarty król, i wszystek lud, który jest z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'A Jonatan i Achimmas stali u studni Rogiel: i poszła dziewka, a oznajmiła im, aby poszli, i donieśli to królowi Dawidowi; bo się nie śmieli ukazać, ani wnijść do miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'Wszakże obaczył je niektóry sługa i powiedział Absalomowi. Przetoż poszedłszy obadwaj spieszno, weszli w dom niektórego męża w Bahurym, który miał studnię na dworze swym, i spuścili się do niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'A wziąwszy niewiasta płachtę, rozciągnęła ją na wierzchu studni, i nasypała na niej krup; a tak się tego nie dowiedziano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Bo gdy przyszli słudzy Absalomowi do onej niewiasty w dom, rzekli: Gdzie jest Achimaas i Jonatan? odpowiedziała im niewiasta: Przeszli przez rzekę; a poszukawszy ich, i nie znalazłszy, wrócili do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'A gdy oni odeszli, tedy owi wystąpiwszy z studni poszli, i oznajmili królowi Dawidowi, mówiąc do niego: Wstańcie, przeprawcie się co rychlej przez wodę; albowiem tak radził przeciwko wam Achitofel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Przetoż wstawszy Dawid, i wszystek lud, który był z nim, przeprawili się przez Jordan, pierwej niż się rozedniało, a nie został i jeden, któryby się nie przeprawił przez Jordan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Tedy Achitofel widząc, iż się nie stało podług rady jego, osiodłał osła, a wstawszy jechał do domu swego, do miasta swego, a rozprawiwszy dom swój, powiesił się, i umarł, a pogrzebion jest w grobie ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'A Dawid już był przyszedł do Mahanaim, gdy Absalom przeprawił się przez Jordan, on i wszyscy mężowie Izraelscy z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'I przełożył Absalom Amazę, miasto Joaba, nad wojskiem. A ten Amaza był synem męża, którego imię było Itra, Izraelczyk, który był wszedł do Abigajli, córki Nahasowej, siostry Sarwii, matki Joabowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'I położył się obozem Izrael z Absalomem na ziemi Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'I stało się, gdy przyszedł Dawid do Mahanaim, że Soby syn Nahasowy z Rabby, synów Ammonowych, i Machir, syn Ammijelowy z Lodebaru, i Barsylaj Galaadczyk z Rogielim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'Pościel, i miednice, i naczynia zduńskie, i pszenicę, i jęczmień, i mąki, i krupy, i boby, i soczewice, i prażma,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'I miodu, i masła, i owiec, i serów krowich przynieśli Dawidowi, i ludowi, który był z nim, aby jedli: bo mówili: Lud ten głodny jest, i spracowany, i pragnieniem zmorzony na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'Tedy obliczył Dawid lud, który miał z sobą, a postanowił nad nimi hetmany, i rotmistrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'I poruczył Dawid ludu trzecią część pod rękę Joabowę, a trzecią część pod rękę Abisaja, syna Sarwii, brata Joabowego, a trzecią część pod rękę Itaja Gietejczyka; i rzekł król do ludu: Wynijdę i ja także z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'Ale lud rzekł: Nie wynijdziesz; bo jeźlibyśmy my tył podali, oni mało dbać o nas będą, choć by też nas poległa połowa, mało dbać o nas będą; albowiemeś ty sam jako nas dziesięć tysięcy. Przetoż teraz lepiej, abyś nam był w mieście na pomocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'I rzekł do nich król: Co się wam zda dobrego, to uczynię. Tedy stał król przy bramie, a wszystek lud wychodził po stu i po tysiącu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'I rozkazał król Joabowi, i Abisajowi, i Itajowi, mówiąc: Łaskawie mi się obchodźcie z synem moim Absalomem. A wszystek lud słyszł, gdy przykazywał król wszystkim hetmanom o Absalomie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'A tak wyciągnął lud w pole przeciw Izraelowi, i zwiedli bitwę w lesie Efraim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'Tamże porażon jest lud Izraelski od sług Dawidowych; i stała się tam porażka wielka dnia onego, a poległo ich dwadzieścia tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Bo gdy była bitwa rozproszona po wszystkiej ziemi, więcej las pogubił ludu, niż ich miecz pożarł dnia onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'I napadł Absalom na sługi Dawidowe; a Absalom jechał na mule, i wbieżał z nim muł pod gęsty a wielki dąb, i uwięzła głowa jego na dębie, i zawisł między niebem i między ziemią; ale muł, który był pod nim, wybiegł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'Co ujrzawszy mąż niektóry, oznajmił Joabowi, mówiąc: Otom widzał Absaloma wiszącego na dębie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Tedy rzekł Joab mężowi, który mu to oznajmił: Jeźliś widział, a czmużeś go tam nie zabił i nie zrzucił na ziemię? A ja bym ci był powinien dać dziesięć srebników i jeden pas rycerski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'I odpowiedział on mąż Joabowi: A ja choćbym miał odważonych na rękach mych tysiąc srebników, nie podniósłbym ręki mojej na syna królewskiego; bośmy słyszeli, gdy przykazał król tobie i Abisajowi i Itajowi, mówiąc: Ochraniajcie wszyscy syna mego A bsaloma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Chyba, żebym chciał wdać duszę moję w niebezpieczeństwo; bo nie bywa nic zatajono przed królem; i ty sam byłbyś przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Tedy rzekł Joab: Nie będęć się ja tu bawił z tobą; przetoż wziąwszy trzy drzewca w rękę swoję, wraził je w serce Absalomowe, gdy jeszcze żyw był na dębie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'A obskoczywszy Absaloma dziesięć sług, którzy nosili broń Joabowę, bili, i zbili go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'Wtem zatrąbił Joab w trąbę, i wrócił się lud z pogoni za Izraelem; bo Joab zatrzymał lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'A wziąwszy Absaloma wrzucili go w tymże lesie w dół wielki, i nanosili nań bardzo wielką kupę kamienia. Ale wszystek Izrael uciekł, każdy do namiotów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'A Absalom wziął był, i wystawił sobie za żywota swego słup, który jest w dolinie królewskiej; bo mówił: Niemam syna; jednak zostawię pamiątkę imienia mego. Przetoż nazwał on słup imieniem swojem, który zowią miejsce Absalomowe aż do dzisiejszego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Tedy Achimaas, syn Sadoka, rzekł: Proszę niech idę a oznajmię królowi nowinę, iż go wybawił Pan z ręki nieprzyjaciół jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'Ale mu rzekł Jaob: Nie byłbyś wdzięcznym posłem dzisiaj; lecz to opowiesz dnia drugiego, a dziś nie dawaj o tem znać, przeto iż syn królewski zginął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Potem Joab rzekł do Chusego: Idź oznajmij królowi, coś widział. A tak ukłoniwszy się Chusy Joabowi, bieżał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'I mówił powtóre Achimaas, syn Sadoka, i rzekł do Joaba: Bądź co bądź, proszę niech i ja bieżę za Chusym. I rzekł Joab: Przeczbyś ty miał bieżeć synu mój, gdyż niemasz, cobyś dobrego zwiastował?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'I rzekł: Bądź co bądź, pobieżę. I rzekł mu Joab: Bieżże. A tak bieżał Achimaas prostszą drogą, i uprzedził Chusego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'A Dawid siedział między dwiema bramami. I wyszedł stróż na dach bramy na mur, a podniósłszy oczy swe, ujrzał męża jednego bieżącego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'Tedy zawoławszy stróż, opowiedział to królowi. I rzekł król: Jeźliżeć sam jest, dobre poselstwo w ustach jego. A gdy ten spiesznie szedł, i przybliżał się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'Ujrzał stróż i drugiego męża bieżącego, i zawołał stróż na wrotnego, mówiąc: Oto i drugi mąż bieży sam. I rzekł król: I ten dobre poselstwo niesie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'Nadto rzekł stróż: Zda mi się bieg pierwszego, jako bieg Achimaasa, syna Sadokowego. I rzekł król: Mąż to dobry, i z dobrem poselstwem idzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'Tedy zawołał Achimaas, i rzekł do króla: Pokój; i ukłonił się królowi twarzą swoją ku ziemi i rzekł: Błogosławiony Pan Bóg twój, któryć podał te męże, co podnieśli ręce swe przeciw królowi, panu memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'I rzekł król: Jakoli się ma syn mój Absalom? Tedy Achimaas odpowiedział: Widziałem zamięszanie wielkie, gdy posyłał sługę królewskiego Joab, i mnie, sługę twego; ale nie wiem co było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Potem rzekł król: Odstąp, a stań tam; a on odstąpiwszy stanął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'A wtem Chusy przyszedł i rzekł: Opowiada się królowi, panu memu, że cię wybawił Pan dzisiaj z ręki wszystkich, którzy powstali przeciwko tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'I rzekł król do Chusego: A jakoli się ma syn mój Absalom? Odpowiedział Chusy: Bodaj tak byli nieprzyjaciele króla, pana mego, i wszyscy, którzy powstawają przeciw tobie na złe, jako syn twój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'Tedy się zasmucił król, i wstąpił na salę onej bramy, a płakał, i tak mówił idąc: Synu mój Absalomie, synu mój! Synu mój Absalomie! obym ja był umarł miasto ciebie! Absalomie, synu mój, synu mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'I oznajmino Joabowi: Oto król płacze i żałuje Absaloma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'Przetoż się ono zwycięstwo dnia onego obróciło w płacz wszystkiemu ludowi; albowiem usłyszawszy lud dnia onego, że mówiono: Żałośny jest król dla syna swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'Zaczem wkradł się lud onego dnia wchodząc do miasta, jako się więc wkrada lud, który się wstydzi, uciekając z bitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'A król nakrywszy oblicze swoje, wołał głosem wielkim: Synu mój Absalomie, Absalomie, synu mój, synu mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'Tedy wszedł Joab do króla w dom, i rzekł: Shańbiłeś dziś oblicze wszystkich sług twoich, którzy wybawili duszę twoję dzisiaj, i duszę synów twoich, i córek twoich, i duszę żon twoich, i duszę nałożnic twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 'Miłując te, którzy cię mają w nienawiści, a nienawidząc tych, którzy cię miłują. Albowiem pokazałeś dziś, że sobie nie poważasz hetmanów, i sług twoich; bom doznał tego dziś, że gdyby Absalom był żyw, choćbyśmy my wszyscy dziś byli pobici, tedyć by się to bardzo podobało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Przetoż teraz wstań, wynijdź, a mów łagodnie do sług twoich. Boć przez Pana przysięgam, jeźli ty nie wynijdziesz, że nie zostanie żaden z tobą tej nocy, a będzieć to gorzej, niżli wszystko złe, którekolwiek na cię przychodziło od młodości twojej aż dotąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Wstał tedy król, i siadł w bramie; i opowiedziano to wszystkiemu ludowi, mówiąc: Oto król siedzi w bramie. I przyszedł wszystek lud przed oblicze królewskie; ale Izraelczycy uciekli byli, każdy do namiotu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'I stało się, że się wszystek lud sprzeczał z sobą we wszystkich pokoleniach Izraelskich, mówiąc: Król wyrwał nas z rąk nieprzyjaciół naszych, tenże nas też wyrwał z rąk Filistyńskich, a teraz uciekł z ziemi przed Absalomem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Lecz Absalom, któregośmy byli pomazali nad sobą, zginął w bitwie; a teraz przeczże wy zaniedbywacie przyprowadzić zasię króla?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'Przetoż król Dawid posłał do Sadoka i do Abijatara, kapłanów, z temi słowy: Powiedzcie starszym Judzkim, mówiąc: Przeczże macie być pośledniejszymi w przyprowadzeniu zasię króla do domu jego? Albowiem słowa wszystkiego Izraela dochodziły króla do domu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Braciaście moi, kość moja, a ciałoście moje; przeczże tedy macie być pośledniejszymi w przywróceniu króla?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'Amazie także powiedzcie: Izaliś ty nie jest kość moja, i ciało moje? To niech mi uczyni Bóg, i to niech przyczyni, jeźli hetmanem wojska nie będziesz przedemną po wszystkie dni, miasto Joaba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'A tak nakłonił serce wszystkich mężów Judzkich jako męża jednego, że posłali do króla mówiąc: Nawróć się ty, i wszyscy słudzy twoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Wrócił się tedy król, i przyszedł aż do Jordanu; a lud Judzki wyszedł był do Galgal, aby zaszedł w drodze królowi, a przeprowadził króla przez Jordan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'Pospieszył się także Semej, syn Giery, syna Jemini, który był z Bachurym, i wyszedł z mężami Judzkimi przeciwko królowi Dawidowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'A było tysiąc mężów z nim z Benjamitów; Syba także, sługa domu Saulowego, i piętnaście synów jego, i dwadzieścia sług jego z nim, i szczęśliwie się przeprawili za Jordan do króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Przeprawili też prom, aby przewieziono czeladź królewską, a iżby uczyniono, coby mu się najlepiej podobało; a Semej, syn Giery, upadł przed królem, gdy się przeprawił przez Jordan,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'I rzekł do króla: Nie przyczytaj mi, panie mój, nieprawości, ani wspominaj, co lekkomyślnie uczynił sługa twój onegoż dnia, gdy wyszedł król, pan mój, z Jeruzalemu, aby to miał przypuszczać król do serca swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Albowiem zna sługa twój, żem zgrzeszył; a otom dziś przyszedł pierwej niż kto ze wszystkiego domu Józefowego, abym zajechał drogę królowi, panu memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Tedy odpowiedział Abisaj, syn Sarwii, i rzekł: Izaż dla tego nie ma być zabity Semej, że złorzeczył pomazańcowi Pańskiemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'Ale mu rzekł Dawid: Cóż wam do tego, synowie Sarwii, żeście mi dziś przeciwnymi? Izali dziś ma być zabity kto w Izraelu? Bo azaż nie wiem, żem ja dziś został królem nad Izraelem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'I rzekł król do Semeja: Nie umrzesz; i przysiągł mu król.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Mefiboset także, wnuk Saula, wyjechał przeciw królowi; który ani obmył nóg swoich, ani czesał brody swojej, ani prał szat swoich, ode dnia, którego był wyszedł król aż do dnia, którego się wrócił w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'I stało się, gdy zabieżał w Jeruzalemie królowi, rzekł mu król: przeczżeś nie szedł ze mną, Mefibosecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'A on mu odpowiedział: Królu, panie mój, zdradził mię sługa mój; bo rzekł był sługa twój, osiodłam sobie osła, żebym siadłszy nań, jechał z królem, gdyż jest chromy sługa twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'I oskarżył sługę twego przed królem, panem moim; ale król, pan mój, jest jako Anioł Boży; przetoż czyń, co dobrego jest w oczach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Albowiem wszyscy z domu ojca mego byliśmy godni śmierci przed królem, panem moim, a przecięś ty posadził sługę twego między tymi, którzy jadają u stołu twego: I cóż jeszcze za sprawiedliwość moja, abym się miał więcej uskarżać na króla?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'Rzekł mu tedy król: Cóż masz więcej mówić w sprawie twojej? Jużem rzekł, ty i Syba, podzielcie się majętnością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'A Mefiboset rzekł do króla: I wszystko niech weźmie, gdy się tylko wrócił król, pan mój, w pokoju do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'Barsylaj też Galaatczyk wyszedłszy z Rogielim, przeprawił się z królem przez Jordan, aby go prowadził za Jordan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'A Barsylaj był bardzo stary, mając osiemdziesiąt lat, który podejmował króla, póki mieszkał w Mahanaim; bo był człowiekiem bogatym bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'I rzekł król do Barsylajego: Pójdź ze mną, a będę cię chował przy sobie w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Ale Barsylaj odpowiedział królowi: Wieleż jest dni lat żywota mego, żebym miał iść z królem do Jeruzalemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Osiemdziesiąt lat mi dzisiaj; izali mogę rozeznać między dobrem a złem? izali poczuje smak sługa twój w tem, cobym jadł, albo cobym pił? izali słuchać mogę więcej głosu śpiewaków i śpiewaczek? a przeczżeby miał być sługa twój jeszcze ciężarem królowi, panu memu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Jeszcze trochę pójdzie sługa twój za Jordan z królem: bo czemużby mi miał dawać król takową nagrodę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Niech się wróci proszę sługa twój, abym umarł w mieście mojem, przy grobie ojca mego i matki mojej; ale oto sługa twój Chymham pójdzie z królem, panem moim: uczyńże mu, co dobrego jest w oczach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'I rzekł król: Niechże ze mną idzie Chymham, a ja mu uczynię, co dobrego będzie w oczach twoich; nadto, cokolwiek żądać będziesz ode mnie, toć uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'A gdy się przeprawił wszystek lud przez Jordan, król się też przeprawił. Tedy pocałował król Barsylajego, i błogosławił mu; który się wrócił do miejsca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Potem przyszedł król do Galgal, przyszedł też z nim Chymham. Wszystek też lud Judzki prowadził króla, także i połowa ludu Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'A oto, wszyscy mężowie Izraelscy, zszedłszy się do króla, mówili do niego: Czemuż cię wykradli bracia nasi, mężowie Judzcy, i przeprowadzili króla i dom jego przez Jordan, i wszystkie męże Dawidowe z nim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'I odpowiedzieli wszyscy mężowie Judzcy mężom Izraelskim: Przeto, iż nam powinny jest król. A przeczże się gniewać macie o to? izali nam za to jeść król dawa, albo nam jakie dary rozdał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Tedy odpowiedzieli mężowie Izraelscy mężom Judzkim, i rzekli: Dziesięć kroć więcej mamy do króla; przetoż i Dawid więcej do nas należy, niż do was. Przeczżeście nas lekce poważali? Azażeśmy my o to pierwej nie mówili, abyśmy przywrócili króla swe go? Ale sroższa była mowa mężów Judzkich, niż mowa mężów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'Tedy się tam pojawił mąż niepobożny, którego zwano Seba, syn Bichry, mąż Jemini. Ten zatrąbił w trąbę, i rzekł: Nie mamy my działu w Dawidzie, ani mamy dziedzictwa w synu Isajego; wróć się każdy do namiotów swoich, o Izraelu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'A tak odstąpili wszyscy mężowie Izraelscy od Dawida za Sebą, synem Bichry; ale mężowie Judzcy trzymali się króla swego, od Jordanu aż do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'I przyszedł Dawid do domu swego w Jeruzalemie; a wziąwszy król dziesięć niewiast założnic, które był zostawił, aby strzegły domu, oddał je pod straż, i żywił je, ale do nich nie wchodził; i były pod strażą aż do dnia śmierci swojej, we wdowim stanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Potem rzekł król do Amazy: Zbierz mi męże Judzkie za trzy dni; ty się też tu staw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'A tak poszedł Amaza, aby zebrał lud Judzki; lecz się zabawił nad czas naznaczony, który mu był naznaczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'I rzekł Dawid do Abisajego: Teraz gorzej nam uczyni Seba, syn Bichry, niż Absalom; przetoż ty weźmij sługi pana twego, a goń go, by snać nie znalazł sobie miast obronnych, i nie uszedł z oczu naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'Tedy wyszli z nim mężowie Joabowi, i Chertczycy i Feletczycy, i wszystko rycerstwo, a wyszli z Jeruzalemu w pogoń za Sebą, synem Bichry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'A gdy byli u wielkiego kamienia, który jest w Gabaon, tedy im Amaza zabieżał. A Joab miał przepasaną szatę swą, w której chodził, a na niej pas z mieczem przypasany do biódr swoich w pochwach swych, którego snadnie mógł dobyć, i zaś schować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'I rzekł Joab do Amazy: Jakoż się masz, bracie mój? I ujął ręką prawą Joab Amazę za brodę, jakoby go całować miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Ale Amaza nie postrzegł miecza, który był w ręce Joabowej: i przebił go nim pod piąte żebro, i wylał trzewa jego na ziemię, a tak za jadną raną umarł. A Joab i Abisaj, brat jego, szli w pogoń za Sebą, synem Bichry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'Tedy stanął jeden nad nim z sług Joabowych, i rzekł: Ktokolwiek jest życzliwy Joabowi, a ktokolwiek trzyma z Dawidem, niech idzie za Joabem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Lecz Amaza walał się w krwi w pośród drogi. A widząc on mąż, iż się zastanawiał wszystek lud nad nim, zwlekł Amazę z drogi na pole, i przyrzucił go szatą, gdyż widział, że ktokolwiek szedł mimo niego, zastanawiał się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'A gdy był zwleczony z drogi, bieżał każdy mąż za Joabem, goniąc Sebę, syna Bichry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Który już był przeszedł przez wszystkie pokolenia Izraelskie, aż do Abel i Betmaacha, ze wszystkimi Berymczykami, którzy się też byli zebrali, a szli za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'A gdy się tam ściągnęli, oblegli go w Abeli Betmaacha, i usypali szańce przeciw miastu, tak iż stali przed murem, a wszystek lud, który był z Joabem, usiłował obalić mury.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Wtem zawołała z miasta niektóra niewiasta mądra: Słuchajcie, słuchajcie! rzeczcie proszę do Joaba: Przystąp sam, a rozmówię się z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'Który gdy do niej przystąpił, rzekła mu ona niewiasta: Tyżeś jest Joab? I odpowiedział: Jestem. Tedy mu rzekła: Słuchaj słów służebnicy twojej; i odpowiedział: Słucham.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Przetoż rzekła, mówiąc: Powiadano przedtem, mówiąc: Koniecznie pytać się będą w Abelu, a tak się wszystko sprawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Jam jest jedno miasto z spokojnych i wiernych w Izraelu, a ty szukasz, abyś zatracił miasto i matkę w Izraelu; przeczże chcesz zburzyć dziedzictwo Pańskie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'I odpowiedział jej Joab, mówiąc: Niedaj, niedaj mi tego Boże, abym miał podwrócić i zburzyć je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Nie takci się rzecz ma. Ale mąż z góry Efraim, imieniem Seba, syn Bichry, podniósł rękę swą przeciw królowi Dawidowi; wydajcież go samego, a odciągnę od miasta. Zatem rzekła niewiasta do Jaoba: Oto głowę jego zrzucą do ciebie z muru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'A tak sprawiła to ona niewiasta u wszystkigo ludu mądrością swoją, że ściąwszy głowę Sebie, synowi Bichry, zrzucili ją do Jaoaba; który zatrąbił w trąbę, i rozeszli się wszyscy od miasta, każdy do namiotów swoich; Joab się też wrócił do króla do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'I był Joab hetmanem nad wszystkiem wojskiem Izraelskiem, a Banajas, syn Jojady, nad Chretczykami i nad Feletczykami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'Adoram był poborcą, a Jozafat, syn Ahiluda, kanclerzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'Seja pisarzem, a Sadok i Abijatar byli kapłanami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'Hira także Jairtczyk był książęciem u Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'I był głód za dni Dawidowych przez trzy lata, jednego roku po drugim. Tedy szukał Dawid oblicza Pańskiego, któremu rzekł Pan: Dla Saula, i dla domu jego krwawego, przeto iż pomordował Gabaonity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'Przyzwał tedy król Gabaonitów, i rzekł do nich: (A ci Gabaonitowie nie byli z synów Izraelskich, ale z ostatków Amorejczyków, którym acz byli synowie Izraelscy przysięgli, wszakże je usiłował Saul wyplenić z gorliwości swej dla synów Izraelskich i Judzkich.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'I rzekł Dawid do Gabaonitów: Cóż wam mam uczynić? a czem was ubłagać, abyście błogosławili dziedzictwu Pańskiemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'I odpowiedzieli mu Gabaonitowie: Nie idzie nam o srebro ani o złoto z Saulem, i z domem jego, ani o to, żebyśmy zabili kogo w Izraelu. A on rzekł: Cokolwiek rzeczecie, uczynię wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'Którzy rzekli do króla: Męża, który nas wygubił, i na tem był, aby nas do szczętu wytracił, żeby nas nic nie zostało we wszystkich granicach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'Wydajcie nam siedmiu mężów z synów jego, a powiesimy je Panu w Gabaa Saula, niekiedy wybranego Pańskiego. Tedy rzekł: Wydam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Lecz sfolgował król Mefibosetowi, synowi Jonatana, syna Saulowego, dla przysięgi Pańskiej, która była między nimi, między Dawidem i między Jonatanem, synem Saulowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Ale wziął król dwóch synów Resfy, córki Ai, które porodziła Saulowi, Armoniego i Mefiboseta, i pięciu synów Micholi, córki Saulowej, które porodziła Adryjelowi, synowi Barsyla Meholatyckiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'I wydał je w ręce Gabaonitów, i powiesili je na górze przed Panem. I umarli oni siedmiu pospołu, a pobici są w pierwsze dni żniwa, na początku żniwa jęczmiennego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'A wziąwszy Resfa, córka Ai, wór, ropostarła go na skale, na początku żniwa, ażby na nie kropił deszcz z nieba, i nie dopuszczała ptastwu powietrznemu, padać na nie we dnie, ani zwierzowi polnemu w nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'Tedy oznajmiono Dawidowi, co uczyniła Resfa, córka Ai, założnica Saulowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'Przetoż szedłszy Dawid wziął kości Saulowe, i kości Jonatana, syna jego od starszych Jabez Galaadskiego, którzy je byli ukradli z ulicy Betsańskiej, kędy je byli zawiesili Filistynowie onegoż dnia, gdy porazili Filistynowie Saula w Gielboe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'A tak wziął stamtąd kości Saulowe i kości Jonatana, syna jego; zebrano też kości powieszonych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'I pogrzebli kości Saulowe i Jonatana, syna jego, w ziemi Benjamina w Sela, grobie Cysa, ojca jego, a uczynili wszystko, co był rozkazał król; a tak potem ubłagany był Bóg ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'I była zasię wojna między Filistynami i Izraelem; i ciągnął Dawid i słudzy jego z nim, a walczył przeciwko Filistynom, tak, że ustał Dawid.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'Tedy Jesbibenob, który był z synów jednego olbrzyma, (a grot drzewca jego ważył trzy sta syklów miedzi, a miał przepasany miecz nowy) umyślił był zabić Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Ale go ratował Abisaj, syn Sarwii, a raniwszy Filistyna zabił go. Przetoż przysięgli mężowie Dawidowi, mówiąc mu: Nie pójdziesz więcej z nami na wojnę, abyś nie zgasił pochodni Izraelskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'I stało się potem, że była znowu wojna w Gob z Filistynami, i zabił Sobochaj Husatycki Safa, który był z synów tegoż olbrzyma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'Była też jeszcze inna wojna w Gob z Filistynami, kędy zabił Elhana, syna Jaara Oregim, Betlehemczyk, brata Golijatowego z Giet, którego drzewce u włóczni było jako nawój tkacki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'Nadto jeszcze była wojna w Giet, kędy był mąż wielkiego wzrostu, mając po sześć palców u rąk swoich, i po sześć palców u nóg swoich, wszystkich dwadzieścia i cztery; a ten też był synem tegoż olbrzyma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Ten gdy urągał Izraelowi, zabił go Jonatan, syn Samaa, brata Dawidowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Ci czterej byli synowie jednego olbrzyma z Giet, a ci polegli od ręki Dawidowej, i od ręki sług jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'I mówił Dawid Panu słowa tej pieśni w on dzień, gdy go wybawił Pan z rąk wszystkich nieprzyjaciół jego i z ręki Saulowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'I rzekł: Pan opoka moja i twierdza moja, i wybawiciel mój ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Bóg, skała moja, w nim będę ufał, tarcz moja, róg zbawienia mego, podwyższenie moje, i ucieczka moja, zbawiciel mój, który mię od gwałtu wybawia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Wzywałem Pana chwały godnego, a od nieprzyjaciół moich byłem wybawiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Albowiem ogarnęły mię były boleści śmierci, potoki niezbożnych przestraszyły mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Boleści grobu ogarnęły mię, zachwyciły mię sidła śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'W utrapieniu mojem wzywałem Pana, a do Boga mego wołałem, i wysłuchał z kościoła swego głos mój, a wołanie moje przyszło do uszów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Tedy się wzruszyła, a zadrżała ziemia, a fundamenty nieba zatrząsnęły, i wzruszyły się dla gniewu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Wystąpił dym z nózdrz jego, a ogień z ust jego pożerający; węgle rozpaliły się od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Nakłonił niebios i zstąpił, a ciemność była pod nogami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'I jeździł na Cherubinach, i latał, i widzian jest na skrzydłach wiatrowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'Położył ciemność około siebie miasto przybytku, zgromadzenie wód z obłoki niebieskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Od jasności oblicza jego rozpaliły się węgle ogniste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Zagrzmiał Pan z nieba, a najwyższy wydał głos swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'Wypuścił i strzały, a rozproszył je, i błyskawicą potarł je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'I okazały się głębokości morskie, a odkryły się grunty świata na fukanie Pańskie, na tchnienie Ducha z nózdrz jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Posławszy z wysokości, przyjął mię, wyrwał mię z wód wielkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Wybawił mię od nieprzyjaciela mego potężnego, od tych, którzy mię mieli w nienawiści, choć byli mocniejszymi nad mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Uprzedzili mię w dzień utrapienia mego; ale Pan był podporą moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'I wywiódł mię na przestrzeństwo; wybawił mię; bo mię sobie upodobał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Oddał mi Pan według sprawiedliwości mojej, według czystości rąk moich oddał mi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Gdyżem strzegł dróg Pańskich, anim niezbożnie nie odstawał od Boga mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Albowiem wszystkie sądy jego są przed obliczem mojem i ustawy jego, nie odstąpiłem od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'A będąc doskonały przed nim, wystrzegałem się nieprawości mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'Przetoż oddał mi Pan według sprawiedliwości mojej, według czystości mojej przed oblicznością oczu swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Z miłosiernym miłosiernie postępujesz, z mężem doskonałym doskonałym jesteś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'Z czystym czysty jesteś, a z przewrotnym surowie się obchodzisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'Ale wybawiasz lud ubogi, a oczy twoje przed wyniosłymi opuszczasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Tyś zaiste pochodnią moją, o Panie, a Pan oświeci ciemności moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Bo w tobie przebiegłem wojsko, w Bogu moim przekroczyłem mur.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Droga Boża jest doskonała, wyrok Pański nader czysty, tarczą jest wszystkim, którzy w nim ufają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Albowiem któż jest Bogiem oprócz Pana? a kto opoką oprócz Boga naszego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Bóg jest mocą moją w wojsku, on czyni doskonałą drogę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Równa nogi moje z jeleniemi, na wysokich miejscach moich stawia mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Ćwiczy ręce me do boju, tak że kruszę łuk miedziany ramiony swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Albowiem dałeś mi tarcz zbawienia mego, a w cichości twojej rozmnożyłeś mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Rozszerzyłeś kroki moje podemną, tak iż się nie zachwiały kostki moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Goniłem nieprzyjacioły moje, i wytraciłem je, a nie wróciłem się, ażem je wyplenił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'I wyniszczyłem je, i poprzebijałem je, tak iż nie powstaną: upadli pod nogami mojemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Tyś mię przepasał mocą ku bitwie, a powaliłeś pod mię powstające przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'Nadto podałeś mi szyję nieprzyjaciół moich, którzy mię mieli w nienawiści, i wykorzeniłem je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Poglądali, ale nie był wybawiciel; wołali na Pana, ale ich nie wysłuchał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'I potarłem je jako proch ziemi, jako błoto na ulicach podeptawszy je, rozmiotałem je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Tyś mię od sporu ludu mego wyrwał; zachowałeś mię, abym był głową narodów; lud, któregom nie znał, służy mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Synowie obcy kłamali mną, a skoro usłyszeli, byli mi posłuszni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Synowie obcy opadali, a drżeli i w zamknieniu swem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Żyje Pan, i błogosławiona skała moja; niechże będzie wywyższony Bóg, opoka zbawienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'Bóg jest, który mi dawa pomsty, a podbija narody pod mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'Który mię wywodzi od nieprzyjaciół moich, a nad tymi, którzy powstają przeciwko mnie, wywyższasz mię, od człowieka niepobożnego wybawiasz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Przetoż będę cię wyznawał Panie między narodami; a imieniowi twemu śpiewać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'On jest wieżą zbawienia króla swego, a czyniący miłosierdzie nad pomazańcem swoim Dawidem, i nad nasieniem jego aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'A teć są ostateczne słowa Dawidowe. Rzekł Dawid, syn Isajego, rzekł mówię mąż, który był zacnie wywyższony, pomazaniec Boga Jakóbowego, i wdzięczny w pieśniach Izraelskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Duch Pański mówił przez mię, a słowa jego przechodziły przez język mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Mówił Bóg Izraelski do mnie, mówiła skała Izraelska: Ten, który panować będzie nad ludem, będzie sprawiedliwy, panować będzie w bojaźni Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'Będzie jako bywa światłość poranna, gdy słońce rano bez obłoków wschodzi, a jako od jasności po deszczu wyrasta ziele z ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'A choć nie taki jest dom mój przed Bogiem, jednak przymierze wieczne postanowił ze mną, utwierdzone we wszystkiem i obwarowane. A w temci jest wszystko zbawienie moje, i wszystka uciecha moja, aczkolwiek temu jeszcze wzrostu nie dawa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Ale nipobożni wszyscy będą jako cierń wyrwani, którego rękoma nie biorą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'Lecz kto się go jedno chce dotknąć, obwaruje się żelazem i drzewem włóczni, albo ogniem wypala go do szczętu na miejscu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Teć są imiona mocarzów, które miał Dawid: Jozeb Basebet Tachmojczyk, najprzedniejszy między trzema; który się z uciechą rzucił na ośm set ludu z włócznią, aby je zabił w jednej potrzebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'A po nim był Eleazar, syn Dodona, syna Ahohowego, między trzema mocarzami, którzy byli z Dawidem; a sromotnie lżyli Filistyny, którzy się byli zebrali ku bitwie, gdy byli odciągnęli mężowie Izraelscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'Ten powstawszy bił Filistyny, tak iż ustała ręka jego, i zdrętwiała ręka jego przy mieczu. Tedy sprawił Pan wielkie wybawienie dnia onego, tak, że się lud wrócił za nim, tylko aby korzyści zebrał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'A po nim był Semma, syn Agi, Hararczyk; albowiem gdy się byli Filistynowie zebrali do kupy, kędy była część pola pełnego soczewicy, a lud inny był uciekł przed Filistynami:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Tedy stanąwszy w pośród onej części pola, bronił go, i pobił Filistyny. A tak sprawił Pan wielkie wybawienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'Wyszli też oni trzej z trzydziestu przedniejszych, a przyszli we żniwa do Dawida, do jaskini Odollam, gdy się wojsko Filistyńskie było obozem położyło w dolinie Refaim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'A Dawid na ten czas był na miejscu obronnem: straż też Filistyńska na ten czas była w Betlehem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'Tedy pragnął Dawid, i rzekł: O by mi się kto dał napić wody z studni Betlehemskiej, która jest u bramy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'Przetoż wpadli ci trzej mocarze do obozu Filistyńskiego, i naczerpali wody z studni Betlehemskiej, która była u bramy; którą nieśli, i przynieśli do Dawida. Ale jej on nie chciał pić, lecz ją wylał przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'I rzekł: Nie daj mi tego Panie, abym to miał uczynić. Izali to nie krew mężów, którzy szli z niebezpieczeństwem dusz swoich? I nie chciał jej pić. Toć uczynili oni trzej mocarze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'Także Abisaj brat Joaba, syn Sarwii był przedniejszym między trzema. Ten podniósł włócznią swą przeciwko trzema stom, i zabił je, i był sławnym między trzema.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Z tych trzech będąc najsławniejszym, był ich hetmanem; wszakże onych trzech pierwszych nie doszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'Banajas też syn Jojady, syn męża rycerskiego, zacny w swych sprawach, z Kabseel; ten zabił dwóch mocarzów Moabskich, tenże szedłszy zabił lwa w pośrodku studni, we dni śnieżne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'Tenże zabił męża Egipczanina, męża na podziw wielkiego, który Egipczanin miał w ręku włócznią; a on szedł ku niemu z kijem, a wydarłszy włócznią z ręki Egipczanina, zabił go włócznią jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'Toć uczynił Banajas, syn Jojady, który też był sławny między onymi trzema mocarzami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'Z tych trzydziestu był najsławniejszym; wszakże onych trzech nie doszedł; i postawił go Dawid nad drabantami swoimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Był też Asael, brat Joaba, między trzydziestoma. A ci są: Elkanan, syn Dodana, Betlehemczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Samma Harodczyk; Elika Harodczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Heles Faltyczyk; Hyra, syn Ikkiesa, Tekuitczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abijezer Anatotczyk; Mobonaj Husatczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Selmon Ahohytczyk; Maharaj Netofatczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Heleb, syn Baany, Netofatczyk; Itaj, syn Rybajego, z Gabaad synów Benjaminowych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Banajas Faratończyk; Haddaj od potoku Gaas;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abijalbon Arbatczyk; Asmewet Barchomczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Elijachba Salabończyk; z synów Jassonowych Jonatana;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Semma Hororczyk; Ahijam, syn Sarara, Ararytczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifelet, syn Achasbaja, syna Machatego; Elijam, syn Achitofela Gilończyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hezraj Karmelczyk; Faraj Arbitczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Igal, syn Natana z Soby; Bani Gadczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Selek Ammonitczyk; Nacharaj Berotczyk, który nosił broń Joaba, syna Sarwii;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Hira Jetrytczyk; Gareb Jetrytczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Uryjasz Hetejczyk. Owa wszystkich trzydzieści i siedm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'Tedy się znowu popędliwość Pańska zapaliła na Izraela, gdy pobudził szatan Dawida przeciwko nim mówiąc: Idź, policz Izraela i Judę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'I rzekł król do Joaba, hetmana wojska swego: Przbież zaraz wszystkie pokolenia Izraelskie od Dan aż do Beerseba, a policzcie lud, abym wiedział poczet ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'Lecz Joab rzekł do króla: Niech przymnoży Pan, Bóg twój, ludu, jako teraz jest tyle stokroć, aby na to oczy króla, pana mego patrzały; ale król, pan mój, przeczże się tego napiera?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Wszakże przemogło słowo królewskie Joaba i hetmany wojska. Przetoż wyszedł Joab, i hetmani wojska od oblicza królewskiego, aby policzyli lud Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'A przeprawiwszy się przez Jordan, położyli się obozem przy Aroer, po prawej stronie miasta, które jest w pośród potoku Gad i przy Jazer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Potem przyszli do Galaad, i do ziemi dolnej Hadsy, a stamtąd przyszli do Dan Jaan i w okół Sydonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'Potem przyszli ku twierdzy Tyrskiej, i do wszystkich miast Hewejskich i Chananejskich, skąd wyszli na południe Judy do Beerseba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'A obszedłszy wszystkę ziemię, przyszli po dziewięciu miesiącach, i po dwudziestu dniach do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'I oddał Joab poczet obliczonego ludu królowi. A było w Izraelu ośm kroć sto tysięcy mężów rycerskich, godnych ku bojowi, a mężów Juda pięć kroć sto tysięcy mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'Potem uderzyło Dawida serce jego, gdy obliczył lud, i rzekł Dawid do Pana: Zgrzeszyłem bardzo, żem to uczynił: ale teraz o Panie! przenieś proszę nieprawość sługi twego, bomci bardzo głupio uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'A gdy wstał Dawid rano, oto słowo Pańskie stało się do Gada proroka, Widzącego Dawidowego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Idź, a powiedz Dawidowi: Tak mówi Pan: Trzyć rzeczy podawam, obierz sobie jednę z tych, abym ci uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'A tak przyszedł Gad do Dawida, i oznajmił mu, a rzekł mu: Albo przyjdzie na cię głód przez siedm lat w ziemi twojej, albo przez trzy miesiące będziesz uciekał przed nieprzyjacioły twymi, a oni cię gonić będą, albo więc przez trzy dni będzie morowe powietrze w ziemi twojej; rozmyśl że się prędko, a obacz, co mam odpowiedzieć temu, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'I rzekł Dawid do Gada: Jestem bardzo ściśniony. Niech proszę raczej wpadniemy w rękę Pańską, gdyż wielkie są zlitowania jego; ale w rękę ludzką niech nie wpadam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'Tedy przepuścił Pan powietrze morowe na Izraela od poranku aż do czasu naznaczonego, i umarło z ludu od Dan aż do Beerseba siedmdziesiąt tysięcy mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'A gdy wyciągnął Anioł rękę swą na Jeruzalem, aby je wytracił, tedy się użalił Pan onego złego, i rzekł do Anioła, który tracił lud: Dosyć teraz; zawściągnij rękę twą. A Anioł Pański był podle bojewiska Arawny Jebuzejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'I rzekł Dawid do Pana, gdy ujrzał Anioła bijącego lud, mówiąc: Otom ja zgrzeszył, jam źle uczynił; ale te owce cóż uczyniły? niech się proszę obróci ręka twoja na mię i na dom ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'Tedy przyszedł Gad do Dawida onegoż dnia, i rzekł mu: Idź, a zbuduj ołtarz Panu na bojewisku Arawy Jebuzejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'I szedł Dawid podług słowa Gadowego, jako był rozkazał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'Tedy spojrzawszy Arawna, ujrzał króla, i sługi jego, przychodzące do siebie: i wyszedł Arawna, a pokłonił się królowi twarzą swą ku ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'I rzekł Arawna: Przeczże przyszedł król, pan mój, do sługi swego? I odpowiedział Dawid: Abym kupił u ciebie to bojewisko, i zbudował na niem ołtarz Panu, żeby zahamowana była ta plaga między ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'Tedy rzekł Arawna do Dawida: Niech weźmie, a ofiaruje król, pan mój, co mu się dobrego widzi: oto woły na całopalenie, i wozy, i jarzma wołów na drwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Wszystko to dawał król Arawna królowi Dawidowi. I mówił Arawna do króla: Pan, Bóg twój, niech cię sobie upodoba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'Lecz król rzekł do Arawny: Nie tak, ale raczej kupię u ciebie i zapłacę; ani będę ofiarował Panu, Bogu memu, całopalenia darmo danego. A tak kupił Dawid ono bojewisko i woły za pięćdziesiąt syklów srebra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'Tamże zbudował Dawid ołtarz Panu, i sprawował całopalenia, i spokojne ofiary. I ubłagany był Pan ziemi, a zahamowana jest ona plaga od Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'A gdy się król Dawid zstarzał, i zaszedł w lata, chodź go odziewano szatami, przecię się zagrzać nie mógł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'I rzekli mu słudzy jego: Niech poszukają królowi, panu naszemu młodej panienki, któraby stawała przed królem, i opatrowała go, a sypiając na łonie jego, żeby zagrzewała króla, pana naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'Szukali tedy panienki pięknej po wszystkich granicach Izraelskich, i znaleźli Abisag Sunamitkę, a przywiedli ją do króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'A ta panienka była bardzo piękna, i opatrowała króla, i służyła mu; ale jej król nie uznał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Lecz Adonijasz, syn Haggity, wynosił się, mówiąc: Ja będę królował. I nasprawiał sobie wozów i jezdnych, i pięćdziesiąt mężów, którzy biegali przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'A nie gromił go nigdy ojciec jego, mówiąc: Przeczżeś to uczynił? A był i ten bardzo pięknej urody, którego była porodziła Haggita po Absalomie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'A miał zmowę z Joabem, synem Sarwii, i z Abijatarem kapłanem, którzy pomagali za Adonijaszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Ale Sadok kapłan, i Banajas, syn Jojady, i Natan prorok, i Semej, i Rehy i rycerstwo Dawidowe, nie przestawali z Adonijaszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'Tedy nabił Adonijasz owiec, i wołów, i bydła tłustego u kamienia Zohelet, który był nad źródłem Rogiel, i wezwał wszystkich braci swych, synów królewskich, i wszystkich mężów z Juda, sług królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'Ale Natana proroka, i Banajasa, i innego rycerstwa, ani Salomona, brata swego, nie wezwał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Tedy rzekł Natan do Betsaby, matki Salomonowej, mówiąc: A nie słyszałaś, iż króluje Adonijasz, syn Haggity, a Dawid, pan nasz, nie wie o tem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Przetoż teraz pójdź proszę, dam ci radę, a zachowasz zdrowie twoje i zdrowie syna twego Salomona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Idź, a wnijdź do króla Dawida, i mów do niego: Izaliś ty królu, panie mój, nieprzysiągł służebnicy twojej, mówiąc: Salomon, syn twój, będzie królował po mnie, a on będzie siedział na stolicy mojej? Przeczże tedy króluje Adonijasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'A gdy ty jeszcze tam będziesz mówiła z królem, ja przyjdę za tobą, i dopełnię słów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'A tak weszła Betsaba do króla na pokój; a król się już był bardzo zstarzał, a Abisag Sunamitka posługowała królowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'Tedy nachyliwszy się Betsaba, pokłoniła się królowi, której rzekł król: Czego chcesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'A ona mu odpowiedziała: Panie mój, tyś przysiągł przez Pana, Boga twego, służebnicy twojej, że Salomon, syn twój, będzie królował po mnie, a on będzie siedział na stolicy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'A oto, już Adonijasz króluje, a ty teraz, królu, panie mój, o tem nie wiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'Albowiem nabił wołów i bydła tłustego, i owiec bardzo wiele, i wezwał wszystkich synów królewskich, i Abijatara kapłana, i Joaba, hetmana wojska; ale Salomona, sługi twego, nie wezwał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Lecz ty królu, panie mój, wiesz, iż się oczy wszystkiego Izraela oglądają na cię, abyś im oznajmił, kto będzie siedział na stolicy króla, pana mego, po tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Inaczej stanie się, gdy zaśnie król, pan mój, z ojcy swymi, że będziemy ja i Salomon, syn mój, jako grzesznicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'A oto, gdy ona jeszcze mówiła z królem, przyszedł Natan prorok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'I opowiedziano to królowi, mówiąc: Oto Natan, prorok; który wszedłszy do króla, pokłonił się królowi twarzą swą ku ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'Rzekł zatem Natan: Królu, panie mój, zażeś ty rzekł: Adonijasz będzie królował po mnie, a on usiędzie na stolicy mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Albowiem dziś szedłszy nabił wołów i bydła tłustego, i owiec bardzo wiele, i wezwał wszystkich synów królewskich, i hetmanów wojsk, i Abijatara kapłana, a oto oni jedzą z nim i piją, i mówią: Niech żyje król Adonijasz!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Ale mnie, sługi twego, i Sadoka kapłana, i Banajasa, syna Jojadowego, i Salomona, sługi twego, nie wezwał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Izali od króla, pana mego, stała się ta rzecz? a nie oznajmiłeś słudze twemu, kto ma siedzieć na stolicy króla, pana mego, po nim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'I odpowiedział król Dawid, mówiąc: Zawołajcie do mnie Betsaby; która przyszedłszy przed obliczność królewską, stanęła przed królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'Tedy przysiągł król, mówiąc: Jako żywy Pan, który wybawił duszę moję z każdego ucisku:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'Iż jakom ci przysiągł przez Pana, Boga Izraelskiego, mówiąc: Że Salomon, syn twój, królować będzie po mnie, a on usiędzie na stolicy mojej miasto mnie, tak dziś uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'I nachyliwszy się Betsaba twarzą ku ziemi, ukłoniła się królowi, i rzekła: Niech żyje Dawid król, pan mój, na wieki!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'Zatem rzekł król Dawid: Zawołajcie do mnie Sadoka kapłana, i Natana proroka, i Banajasa, syna Jojadowego. I weszli do króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'I rzekł im król: Weźmijcie z sobą sługi pana waszego, a wsadźcie Salomona, syna mego, na mulicę moję, i prowadźcie go do Gihonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'A tam go pomaże Sadok kapłan, i Natan prorok za króla nad Izraelem; potem zatrąbicie w trąbę, a rzeczecie: Niech żyje król Salomon!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Potem pójdziecie za nim; a on przyszedłszy, siądzie na stolicy mojej, i będzie królował miasto mnie; bom mu ja rozkazał, aby był wodzem nad Izraelem i nad Judą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'I odpowiedział Banajas, syn Jojada, królowi, mówiąc: Amen. Niech to stwierdzi Pan, Bóg króla, pana mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Jako był Pan z królem, panem moim, tak niech będzie z Salomonem, a niechaj wywyższy stolicę jego nad stolicę Dawida króla, pana mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'A tak szedł Sadok kapłan, i Natan prorok, i Banajas, syn Jojada, przytem Cheretczycy, i Feletczycy, i wsadzili Salomona na mulicę króla Dawida, a prowadzili go do Gihonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'Tedy wziął Sadok kapłan róg olejku z namiotu, i pomazał Salomona. Potem trąbili w trąbę, i zakrzyknął wszystek lud: Niech żyje król Salomon!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'I szedł wszystek lud za nim. Tenże lud grał na piszczałkach, weseląc się weselem wielkiem, tak iż drżała ziemia od głosu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'Co gdy usłyszał Adonijasz, i wszyscy wezwani, którzy byli z nim, (a już się też była dokończyła uczta,) słysząc też i Joab głos trąby, rzekł: Cóż to za krzyk miasta huczącego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'A gdy on tego domawiał, oto Jonatan, syn Abijatara kapłana, przyszedł. Któremu rzekł Adonijasz: Wnijdź; boś ty mąż stateczny, a powiesz nam co dobrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'Tedy odpowiedział Jonatan, i rzekł Adonijaszowi: Dawid król, pan nasz, postanowił zapewne Salomona królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'Albowiem posłał z nim król Sadoka kapłana, i Natana proroka, i Banajasa, syna Jojadowego, do tego Cheretczyki i Feletczyki, którzy go wsadzili na mulicę królewską;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'I pomazali go Sadok kapłan, i Natan prorok za króla w Gihonie, i szli stamtąd weseląc się, tak, że zadrżało miasto; tenci jest krzyk, któryście słyszeli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'I już usiadł Salomon na stolicy królestwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'Nadto i słudzy królewscy przyszli, aby błogosławili Dawidowi królowi, panu naszemu, mówiąc: Niech sławniejsze uczyni Bóg imię Salomonowe nad imię twoje, a niech wywyższy stolicę jego nad stolicę twoję. I pokłonił się król na łożu swem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'Przytem tak rzekł król: Błogosławiony Pan, Bóg Izraelski, który dał dziś siedzącego na stolicy mojej, na co patrzą oczy moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'Zlękli się tedy, i wstali wszyscy wezwani, którzy byli z Adonijaszem, i poszli każdy w drogę swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Adonijasz także, bojąc się Salomona, wstał, i poszedł, a uchwycił się rogów ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'I oznajmiono Salomonowi, mówiąc: Oto Adonijasz boi się króla Salomona, a oto uchwycił się rogów ołtarza, mówiąc: Niech mi dziś przysięże król Salomon, że nie zabije sługi swego mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'Tedy rzekł Salomon: Jeźli będzie mężem statecznym, nie spadnie i włos z niego na ziemię; ale jeźli się w nim znajdzie co złego, pewnie umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'A tak posłał król Salomon, i przywiedziono go od ołtarza; a gdy przyszedł, ukłonił się królowi Salomonowi, i rzekł mu Salomon: Idź do domu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'A gdy się przybliżał czas śmierci Dawidowej, rozkazał Salomonowi, synowi swemu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Ja idę w drogę wszystkiej ziemi, a ty zmacniaj się, i bądź mężem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'Zachowywaj ustawy Pana, Boga twego, abyś chodził drogami jego, i przestrzegał wyroków jego, i przykazań jego i sądów jego, i świadectw jego, jako napisano w zakonie Mojżeszowym, abyć się szczęściło wszystko, co sprawować będziesz, i we wszystkiem, do czego się obrócisz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'Żeby utwierdził Pan słowo swoje, które rzekł do mnie, mówiąc: Jeźli będą strzedz synowie twoi drogi swej, chodząc przedemną w prawdzie, ze wszystkiego serca swego, i ze wszystkiej duszy swojej, tedy nie będzie wytracony po tobie mąż z stolicy Izrael skiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'A ty też wiesz, co mi uczynił Joab syn Sarwii, co uczynił dwom hetmanom wojsk Izraelskich, Abnerowi, synowi Nerowemu, i Amazie, synowi Jeterowemu, że je pozabijał, a wylał krew jako na wojnie czasu pokoju, i zmazał krwią jako na wojnie pas swój rycerski, który miał na biodrach swoich, i bóty swoje, które miał na nogach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Uczynisz tedy według mądrości twojej, a nie dopuścisz zejść sędziwości jego w pokoju do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Ale nad synami Barsylai Galaadczyka użyjesz miłosierdzia, a niech jadają wespół z inszymi u stołu twego; albowiem oni takimże sposobem przyszli do mnie, gdym uciekał przed Absalomem, bratem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Oto też jest u ciebie Semej, syn Giery, syna Jemini, z Bahurym, który mi też złorzeczył złorzeczeniem wielkiem w on dzień, gdym szedł do Mahanaim; a wszakże zaszedł mi drogę u Jordanu, i przysiągłem mu przez Pana, mówiąc: Nie zamorduję cię mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Teraz jednak nie przepuszczaj mu tego, a iżeś jest mężem mądrym, będziesz wiedział, co mu masz uczynić, abyś wprowadził sędziwość jego ze krwią do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'Zatem zasnął Dawid z ojcy swoimi, a pogrzebiony jest w mieście Dawidowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'A dni, których królował Dawid nad Izraelem, było czterdzieści lat. W Hebronie królował siedm lat, a w Jeruzalemie królował trzydzieści i trzy lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'A tak Salomon usiadł na stolicy Dawida ojca swego, i zmocniło się bardzo królestwo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Tedy przyszedł Adonijasz, syn Haggity, do Betsaby, matki Salomonowej, któremu ona rzekła: A spokojneż jest przyjście twoje? A on odpowiedział: Spokojne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Nadto rzekł: Mam nieco mówić z tobą. A ona rzekła: Mów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'Tedy rzekł: Ty wiesz, iż moje było królestwo, a na mię obrócili byli wszyscy Izraelczycy twarz swoję, abym królował; ale przeniesione jest królestwo, i dostało się bratu memu; bo mu od Pana naznaczone było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'Przetoż cię teraz proszę o jednę rzecz, a nie odmawiaj mi tego. A ona mu rzekła: Mów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'Zatem on rzekł: Mów proszę do Salomona króla, (bo wiem, żeć nie odmówi,) aby mi dał Abisag Sunamitkę za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'I odpowiedziała Betsaba: Dobrze; będę mówiła o cię z królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'A tak szła Betsaba do króla Salomona, aby z nim mówiła za Adonijaszem; i wstał król przeciwko niej, a pokłoniwszy się jej usiadł na stolicy swej; kazał też postawić stolicę matce swej, która siadła po prawicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'I rzekła: Proszę cię o jednę małą rzecz, nie odmawiaj mi. I odpowiedział jej król: Proś matko moja; albowiem ci nie odmówię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Tedy rzekła: Niech będzie dana Abisag Sunamitka Adonijaszowi, bratu twemu, za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'Lecz odpowiedział król Salomon, i rzekł matce swojej: Przeczże prosisz o Abisag Sunamitkę Adonijaszowi? uproś mu i królestwo, albowiem on jest bratem moim starszym nad mię, a ma po sobie Abijatara kapłana, i Joaba, syna Sarwii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'I przysiągł król Salomon przez Pana, mówiąc: To mi niech uczyni Bóg, i to niech przyczyni, że przeciwko duszy swej mówił Adonijasz te słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'A teraz jako żywy Pan, który mię utwierdził, i posadził na stolicy Dawida ojca mojego, i który mi zbudował dom, jako obiecał, iż dziś zabity będzie Adonijasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'A tak posłał król Salomon Banajasa, syna Jojadowego, który się nań targnął, i zabił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'A do Abijatara kapłana rzekł król: Idź do Anatot, do osiadłości twojej, albowiemeś mężem śmierci; wszakże cię dziś nie zabiję, gdyżeś nosił skrzynię Pańską przed Dawidem, ojcem moim, a iżeś to wszystko cierpiał, czem był trapiony ojciec mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'I wyrzucił Salomon Abijatara, aby nie był kapłanem Pańskim, żeby się wypełniło słowo Pańskie, które był wyrzekł nad domem Heli w Sylo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'Ta wieść gdy przyszła do Joaba, (albowiem Joab przestawał z Adonijaszem, chociaż z Absalomem nie przestawał,) tedy uciekł Joab do namiotu Pańskiego, a uchwycił się rogów ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'I oznajmiono królowi Salomonowi, że uciekł Joab do namiotu Pańskiego, a że jest u ołtarza: tedy posłał Salomon Banajasa, syna Jojadowego, mówiąc: Idź, zabij go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'A przyszedłszy Banajas do namiotu Pańskiego, rzekł do niego: Tak mówi król: Wynijdź. Który odpowiedział: Nie wyjdę, ale tu umrę. I odniósł to Banajas królowi mówiąc: Tak mówił Joab, i tak mi odpowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'I rzekł mu król: Uczyńże, jako mówił, a zabij go, i pogrzeb go, a odejmiesz krew niewinną, którą wylał Joab, odemnie i od domu ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'A obróci Pan krew jego na głowę jego: albowiem targnął się na dwóch mężów sprawiedliwszych i lepszych niżli sam, i zabił je mieczem, a ojciec mój Dawid nie wiedział o tem: Abnera, syna Nerowego, hetmana wojska Izraelskiego, i Amazę, syna Jeterowego, hetmana wojska Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'A tak wróci się krew ich na głowę Joabowę, i na głowę nasienia jego na wieki; lecz Dawidowi i nasieniu jego, i domowi jego, i stolicy jego niech będzie pokój aż na wieki od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Szedł tedy Banajas, syn Jojada, a rzuciwszy się nań zabił go, i pogrzebiony jest w domu swym na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'I postanowił król Banajasa syna Jojadowego, miasto niego nad wojskiem, a Sadoka kapłana postanowił król miasto Abijatara.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Potem posłał król, i przyzwał Semejego, i rzekł mu: Zbuduj sobie dom w Jeruzalemie, i mieszkaj tam, a nie wychodź stamtąd nigdzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Bo któregobyś dnia wyszedł a przyszedł za potok Cedron, wiedz wiedząc, że pewnie umrzesz; krew twoja będzie na głowę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'Tedy rzekł Semej do króla: Dobre jest to słowo; jako mówił król, pan mój, tak uczyni sługa twój, I mieszkał Semej w Jeruzalemie przez wiele dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'I stało się po trzech lat, że uciekli dwaj słudzy Semejemu do Achisa syna Maachy, króla Gietskiego, i opowiedziano Semejemu, mówiąc: Oto słudzy twoi są w Giet.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'Przetoż wstawszy Semej, i osiodławszy osła swego, jechał do Giet, do Achisa, aby szukał sług swoich; i wrócił się Semej i przywiódł sługi swe z Giet.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'I oznajmiono Salomonowi, że był wyjechał Semej z Jeruzalemu do Giet, i zasię się wrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'Tedy posłał król, i wezwał Semejego, i rzekł mu: Izalim cię nie poprzysiągł przez Pana, a nie oświadczyłem się przed tobą, mówiąc: Któregobyśkolwiek dnia gdzie wyszedł, wiedz wiedząc, że zapewne umrzesz? I mówiłeś do mnie: Dobre to słowo, którem słyszał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Przeczżeś tedy nie strzegł przysięgi Pańskiej i przykazania, którem ci był przykazał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Nadto król rzekł do Semejego: Ty wiesz wszystko złe, którego świadome jest serce twoje, coś uczynił Dawidowi, ojcu memu, i oddał Pan złość twoję na głowę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'Ale król Salomon błogosławiony, stolica Dawidowa będzie utwierdzona przed Panem aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'A tak rozkazał król Banajasowi, synowi Jojadowemu, który wyszedłszy targnął się nań, i zabił go. A tak utwierdzone jest królestwo w ręce Salomonowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'I spowinowacił się Salomon z Faraonem, królem Egipskim; bo pojął córkę Faraonową, i przyprowadził ją do miasta Dawidowego, ażby dobudował domu swego, i domu Pańskiego, i muru Jeruzalemskiego w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Wszakże lud ofiarował po górach, przeto, że nie był jeszcze zbudowany dom imieniowi Pańskiemu aż do onych dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'I miłował Salomon Pana, chodząc w przykazaniach Dawida, ojca swego; tylko że na górach ofiarował i kadził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Szedł tedy król do Gabaon, aby tam ofiarował; bo tam była góra największa; tysiąc ofiar całopalonych ofiarował Salomon na onym ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'I ukazał się Pan w Gabaon Salomonowi przez sen w nocy, i rzekł Bóg: Proś czego chcesz, a dam ci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'Tedy rzekł Salomon: Tyś uczynił z sługą twoim Dawidem, ojcem moim, miłosierdzie wielkie, gdyż chodził przed tobą w prawdzie i w sprawiedliwości, i w prostości serca stał przy tobie; i zachowałeś mu to miłosierdzie wielkie, iżeś mu dał syna, który by siedział na stolicy jego, jako się to dziś okazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'A teraz, o Panie Boże mój, tyś postanowił królem sługę twego miasto Dawida, ojca mego, a jam jest dziecię małe, i nie umiem wychodzić ani wchodzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'A sługa twój jest w pośrodku ludu twego, któryś obrał, ludu wielkiego, który nie może zliczony ani porachowany być przez mnóstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Przetoż daj słudze twemu serce rozumne, aby sądził lud twój, i aby rozeznawał między dobrem i złem; albowiem któż może sądzić ten lud twój tak wielki?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'I podobało się to Panu, że żądał Salomon tej rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'Tedy rzekł Bóg do niego: Dla tego, żeś o to prosił, a nieżądałeś sobie długich dni, aniś żądał sobie bogactw, aniś prosił o wytracenie nieprzyjaciół twoich, aleś sobie prosił o rozum dla rozeznania sądu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'Otożem uczynił według słów twoich; otom ci dał serce mądre i rozumne, tak, iż żaden równy tobie nie był przed tobą, ani po tobie powstanie równy tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Do tego i to, czegoś nie żądał, dałem ci, to jest bogactwa i sławę, tak aby nie było żadnego tobie równego między królmi po wszystkie dni twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'A będzieszli chodził drogami mojemi, strzegąc wyroków moich, i rozkazania mego, jako chodził Dawid, ojciec twój, tedy przedłużę dni twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'A gdy się ocucił Salomon, zrozumiał, że to był sen. I przyszedł do Jeruzalemu, a stanąwszy przed skrzynią przymierza Pańskiego, sprawował całopalenia, i ofiarował ofiary spokojne, sprawił też ucztę na wszystkie sługi swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Tedy przyszły dwie niewiasty wszetecznice do króla, i stanęły przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'I rzekła jedna z onych niewiast: Proszę panie mój, ja i ta niewiasta mieszkamy w jednym domu, i porodziłam u niej w tymże domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'I stało się dnia trzeciego po porodzeniu mojem, że porodziła i ta niewiasta; i byłyśmy pospołu, a nie było nikogo obcego z nami w domu, oprócz nas dwóch w tymże domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'I umarł syn tej niewiasty w nocy, przeto, iż go była przyległa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'A wstawszy o północy, wzięła syna mego odemnie, gdy służebnica twoja spała, i położyła go na łonie swojem, a syna swego umarłego położyła na łonie mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'A gdym wstała rano, chcąc dać ssać synowi memu, otom znalazła umarłego; któremu gdym się rano przypatrzyła, a oto nie był syn mój, któregom porodziła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'I rzekła ona druga niewiasta: Nie tak; ale syn mój jest ten żywy, a syn twój ten umarły. Ale ona rzekła: Nie; ale syn twój jest ten umarły, a syn mój ten żywy. I tak się spierały przed królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'I rzekł król: Ta mówi: Ten żywy jest syn mój, a syn twój ten umarły; a ta zasię mówi: Nie tak; ale syn twój ten umarły, a syn mój ten żywy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Przetoż rzekł król: Przynieście mi miecz. I przyniesiono miecz przed króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Tedy rzekł król: Rozetnijcie to żywe dziecię na dwoje, a dajcie połowę jednej, a połowę drugiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Ale niewiasta, której był ten syn żywy, mówiła do króla, (bo się były poruszyły wnętrzności jej nad synem jej,) i rzekła: Proszę, panie mój, dajcie jej to dziecię żywe, a żadnym sposobem nie zabijajcie go. Ale druga rzekła: Niech nie będzie ani mnie, ani tobie, rozetnijcie je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Tedy odpowiedział król, i rzekł: Dajcież tej dziecię żywe, a żadną miarą nie zabijajcie go; tać jest matka jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'A usłyszawszy wszystek lud Izraelski ten sąd, który osądził król, bali się króla: albowiem wiedzieli, że mądrość Boża była w sercu jego ku czynieniu sądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'A tak król Salomon był królem nad wszystkim Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'A teć są książęta, które miał: Azaryjasz, syn Sadoka kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elichoref i Achija, synowie Sysy, byli pisarzami; Jozafat, syn Ahiluda, kanclerzem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'A Banajas, syn Jojady, był hetmanem; Sadok zaś i Abijatar kapłanami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'A Azaryjasz, syn Natana, nad urzędnikami, a Zabud, syn Natana, był książęciem, przyjacielem królewskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'Ahisar zaś był przełożony nad domem, a Adoniram, syn Abdy, nad wybranym ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'Miał też Salomon dwanaście przełożonych nad wszystkim Izraelem, którzy dodawali żywności królowi i domowi jego. Każdy z nich przez jeden miesiąc w roku królowi żywności dodawał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'A teć są imiona ich: Syn Hura na górze Efraim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Syn Dekara w Makas, i w Salbim, i w Betsames, i w Elon i Bethanan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Syn Heseda w Arubot, który trzymał Socho i wszystkę ziemię Chefer;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Syn Abinadaba, który trzymał wszystkie granice Dor, a Tafet, córkę Salomonową, miał za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, syn Ahiluda, który trzymał Tanach i Magieddo, i wszystko Betsan, które jest podle Sartany pod Jezreelem, od Betsan aż do Abelmehola, aż za Jekmaam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Syn Gaber w Ramot Galaadskiem, który trzymał wsi Jaira, syna Manasesowego, które leżą w Galaad. Jemu też należała kraina Argob, która jest w Basan, sześćdziesiąt miast wielkich murowanych z zaworami miedzianemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Achinadab, syn Iddona, w Mahanaim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Achimaas w Neftalim, który też pojął Basematę, córkę Salomonową, za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, syn Husai, w Aser i w Alot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Jozafat, syn Paruacha, w Isaschar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Semej, syn Eli, w Benjamin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Gaber, syn Ury, w ziemi Galaad i w ziemi Sehona króla Amorejskiego, i Oga króla Basańskiego; a ten sam był rządcą onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Tedy Juda i Izrael będąc niezliczeni jako piasek, który jest nad morzem w mnóstwie, jedli, i pili, i weselili się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'A Salomon panował nad wszystkiemi królestwy od rzeki aż do ziemi Filistyńskiej, i aż do granicy Egipskiej. I przynosili dary, a służyli Salomonowi po wszystkie dni żywota jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'A tenci był rozchód Salomona na każdy dzień, trzydzieści korcy mąki białej, i sześćdziesiąt korcy innej mąki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'Dziesięć wołów karmnych, i dwadzieścia wołów pastewnych, i sto owiec, oprócz jeleni i sarn, i bawołów, i ptastwa karmnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Albowiem on panował wszędy z tej strony rzeki od Tasfa aż do Gazy nad wszystkimi królmi, którzy byli przed rzeką, a miał pokój ze wszystkich stron w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'I mieszkał Juda i Izrael bezpiecznie, każdy pod winną macicą swoją, i pod figą swoją, od Dan aż do Beerseba, po wszystkie dni Salomonowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'Miał też Salomon czterdzieści tysięcy koni na staniu do wozów swoich, a dwanaście tysięcy jezdnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'A tak podejmowali oni przełożeni króla Salomona, i wszystkie, którzy przychodzili do stołu króla Salomona, każdy miesiąca swego, nie dopuszczając, aby na czem schodzić miało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Jęczmień także, i plewy dla koni i mułów, zwozili na to miejsce, gdzie był król, każdy według tego, jako mu postanowiono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'Nadto dał Bóg Salomonowi mądrość i roztropność bardzo wielką, a przestronność serca, jako piasek, który jest na brzegu morskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'Albowiem większa była mądrość Salomonowa, niżli mądrość wszystkich narodów wschodnich, i niżli wszelka mądrość Egipczanów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Owszem mędrszym był nad wszystkie ludzie, aż i nad Etana Ezrahytę, i nad Hemana, i Chalkola, i Darda, syny Maholowe; a był sławny u wszystkich narodów okolicznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'Nadto złożył trzy tysiące przypowieści, a pieśni jego było tysiąc i pięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'Rozprawiał też o drzewach, począwszy od cedru, który jest na Libanie, aż do hizopu, który wyrasta z ściany. Mówił też o zwierzętach i o ptakach, i o gadzinach, i o rybach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'Przetoż przychodzili ze wszystkich narodów słuchać mądrości Salomonowej, i od wszystkich królów ziemi, którzy słyszeli o mądrości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'I posłał Hiram, król Tyrski, sługi swe do Salomona, bo usłyszał, że go pomazano za króla miasto ojca jego; albowiem miłował Hiram Dawida po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'Salomon też zaś posłał do Hirama, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Ty wiesz, że Dawid, ojciec mój, nie mógł budować domu imieniowi Pana, Boga swego, dla wojen, które go były ogarnęły, aż nieprzyjacioły podał Pan pod stopy nóg jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Ale teraz Pan, Bóg mój, dał mi odpoczynienie zewsząd, i niemam żadnego przeciwnika, ani zabiegu złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'A otom umyślił budować dom imieniowi Pana, Boga mego, jako powiedział Pan do Dawida, ojca mego, mówiąc: Syn twój, któremu dam miasto ciebie osiąść stolicę twoję, ten zbuduje dom ten imieniowi memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Przetoż teraz rozkaż, aby mi narąbano ceder na Libanie, a słudzy moi będą z sługami twoimi, a zapłatę sług twoich dam tobie tak, jako rzeczesz; albowiem ty wiesz, że niemasz między nami męża, któryby umiał tak rąbać drzewo, jako Sydończycy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'A gdy usłyszał Hiram słowa Salomonowe, uradował się bardzo i rzekł: Błogosławiony Pan dzisiaj, który dał Dawidowi syna mądrego nad tym ludem wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'I posłał Hiram do Salomona, mówiąc: Słyszałem z czemeś posłał do mnie. Uczynię wszystkę wolą twoję około drzewa cedrowego, i około drzewa jodłowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Słudzy moi zwiozą je z Libanu do morza, a ja je każę złożyć w tratwy, i spuścić morzem aż do miejsca, o którem mi dasz znać, i tam je rozwiążę, a ty je pobierzesz. Ty też uczynisz wolą moję, a dasz obrok czeladzi mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'A tak Hiram dodawał Salomonowi drzewa cedrowego, i drzewa jodłowego, jako wiele chciał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Salomon także dawał Hiramowi dwadzieścia tysięcy miar pszenicy na żywność czeladzi jego, i dwadzieścia tysięcy miar oliwy wybijanej; to dawał Salomon Hiramowi na każdy rok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'A Pan dał mądrość Salomonowi, jako mu był obiecał, i był pokój między Hiramem i między Salomonem, a uczynili przymierze między sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'Tedy kazał wybierać król Salomon robotniki ze wszystkiego Izraela, a było wybranych trzydzieści tysięcy mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'Które słał do Libanu po dziesięć tysięcy na każdy miesiąc, na przemiany; po miesiącu mieszkali na Libanie, a po dwa miesiące w domu swym; a Adoniram był przełożony nad tymi wybranymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'Miał też Salomon siedmdziesiąt tysięcy tych, którzy nosili ciężary, a ośmdziesiąt tysięcy tych, którzy rąbali na górze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'Oprócz przedniejszych urzędników Salomonowych, których było nad robotą trzy tysiące i trzy sta, którzy byli przełożeni nad ludem odprawującym robotę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'Rozkazał też król, aby wożono kamienie wielkie, kamienie drogie, i kamienie ciosane, na założenie gruntów domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'Ciosali tedy rzemieślnicy Salomonowi, i rzemieślnicy Hiramowi, i Gimblimczycy. A tak gotowali drzewo i kamienie na budowanie domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'I stało się czterechsetnego i ośmdziesiątego roku po wyjściu synów Izraelskich z ziemi Egipskiej, miesiąca Kwietnia (ten jest miesiąc wtóry,) roku czwartego królowania Salomonowego nad Izraelem, że począł budować dom Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'A ten dom, który budował król Salomon Panu, był wdłuż na sześćdziesiąt łokci, a wszerz na dwadzieścia, a wzwyż na trzydzieści łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'Przysionek zasię przed kościołem był na dwadzieścia łokci wdłuż, jako był szeroki dom, a wszerz był na dziesięć łokci przed domem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'I poczynił w domu okna wewnątrz przestronne, a z dworu wąskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'I zbudował przy murze kościelnym ganki wszędy w około, przy murze domu około kościoła i świątnicy; uczynił też gmachy w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'Ganek spodni był na pięć łokci wszerz, a średni był na sześć łokci wszerz, a trzeci był na siedem łokci wszerz; bo był ustępy uczynił około domu z nadworza, aby balki nie przechodziły do murów kościelnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'A gdy ten dom budowano, z kamienia wyrobionego, jakie przywożono, budowano go; a młota, ani siekiery, ani żadnego naczynia żelaznego nie słychać było w domu, gdy go budowano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Drzwi do gmachu średniego były na prawej stronie domu, któremi po okrągłych schodach wchodzono do średniego, a z średniego do trzeciego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'A tak zbudował on dom, i dokończył go, i nakrył go balkami na kształt zasklepienia, i deskami cedrowemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'Przybudował też ganki około całego domu na pięć łokci wzwyż, a przypojone były do domu balkami cedrowymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'I stało się słowo Pańskie do Salomona, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Toć jest ten dom, który ty budujesz. Jeźli będziesz chodził w ustach moich, i sądy moje będziesz czynił, i zachowywał wszystkie rozkazania moje, chodząc w nich, tedy utwierdzę słowo moje z tobą, którem wyrzekł do Dawida, ojca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'I będę mieszkał w pośrodku synów Izraelskich, a nie opuszczę ludu mego Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'A tak zbudował Salomon dom on, i dokończył go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'I obłożył mury domu wewnątrz deskami cedrowemi; od tła domu aż do stropu okrył drzewem wewnątrz, a tło domu położył tarcicami jodłowemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'Zbudował też przegrodzenie na dwadzieścia łokci wdłuż od strony do strony domu, z tarcic cedrowych od tła aż do stropu. A tak zbudował Bogu wewnątrz przybytek, aby był świątnicą najświętszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'A na czterdzieści łokci był sam dom, to jest, kościół przed świątnicą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'A na deskach cedrowych wewnątrz w domu było rzezanie nakształt jabłek leśnych, i kwiecia rozkwitłego, wszystko z cedru, tak, że ani kamienia nie było widzieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'A świątnicę najświętszą w domu wewnątrz nagotował, aby tam postawiona była skrzynia przymierza Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Która świątnica najświętsza wewnątrz była dwadzieścia łokci wdłuż, a dwadzieścia łokci wszerz, i dwadzieścia łokci wzwyż; a obił ją złotem szczerem, ołtarz także cedrowy obił złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'A tak obłożył Salomon dom on wewnątrz szczerem złotem, i zaciągnął łańcuchami złotemi przegrodzenie przed świątnicą świętych, które też obłożył złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'Także wszystek dom obił złotem, nie opuszczając żadnej strony, i cały ołtarz, który był przed świątnicą najświętszą, powlókł złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'Uczynił też w świątnicy najświętszej dwa Cherubiny z drzewa oliwnego; dziesięć łokci wzwyż był każdy z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'A było na pięć łokci skrzydło Cherubinowe jedno, a na pięć łokci skrzydło Cherubinowe drugie: dziesięć łokci było od końca skrzydła jednego aż do końca skrzydła drugiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'Także na dziesięć łokci był i Cherub drugi: miara jednaka, i rzezanie jednakie było obu Cherubinów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Wysokość Cherubina jednego była na dziesięć łokci, także i drugiego Cherubina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'I postawił one Cherubiny w pośrodku domu wnętrznego, i rozciągnęli skrzydła Cherubinowie, tak iż się dotykało skrzydło jednego jednej ściany, a skrzydło Cheruba drugiego dotykało się drugiej ściany, a skrzydła ich w pośród domu dotykały się siebie wespołek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'I powlókł one Cherubiny złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'Nadto i wszystkie ściany około domu przyozdobił wyryciem Cherubinów i palm, i kwiatów rozkwitłych wewnątrz i zewnątrz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'I tło domu położył złotem wewnątrz i zewnątrz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'Uczynił też w wejściu do świątnicy najświętszej drzwi z oliwnego drzewa, a podwoje i odrzwi były na pięć grani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'A te obie drzwi były z drzewa oliwnego, i przyozdobił je wyryciem Cherubinów, i palm, i rozkwitłych kwiatów, i powlókł je złotem; obłożył też Cherubiny i palmy złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Także też uczynił i w wejściu kościelnem podwoje z drzewa oliwnego na cztery granie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'A obie drzwi były z drzewa jodłowego; na dwie się strony jedne drzwi otwierały, także na dwie strony drzwi drugie otwierały się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'I wyrył na nich Cherubiny i palmy, i rozkwitłe kwiaty, a powlókł złotem ciągnionem to, co było wyryto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'Przytem zbudował sień wnętrzną we trzy rzędy z kamienia ciosanego, a jednym rzędem z heblowanego drzewa cedrowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'Roku czwartego, miesiąca Kwietnia, założony jest dom Pański;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'A roku jedenastego, miesiąca Października, (ten jest miesiąc ósmy,) dokonany jest dom ze wszystkiem naczyniem jego i ze wszystkiem, co do niego należało. A budował go przez siedm lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Potem dom swój budował Salomon przez trzynaście lat, i dokonał wszystkiego domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Zbudował też dom lasu Libanowego na sto łokci wdłuż, a na pięćdziesiąt łokci wszerz, a na trzydzieści łokci wzwyż, na czterech rzędach słupów cedrowych, a balki cedrowe leżały na onych słupach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'A był nakryty cedrem z wierzchu na onych balkach, które były na czterdziestu i pięciu słupach, których było w każdym rzędzie piętnaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'Okna też były we trzy rzędy, a okno przeciwko oknu trzema rzędami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'A wszystkie drzwi i podwoje były na cztery granie, i okna: a sporządzone były okna przeciw oknom trzema rzędami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'Uczynił też przysionek na słupach na pięćdziesiąt łokci wdłuż, a wszerz na trzydzieści łokci. A był on przysionek na przodku, także i słupy i balki na przodku domu tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Nadto uczynił przysionek dla stolicy, gdzie sądził, przysionek sądowy, który nakryty był cedrem od tła aż do stropu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'A w domu swym, w którym mieszkał, uczynił salę drugą za przysionkiem takąż robotą; zbudował też dom córce Faraonowej, którą był pojął Salomon, podobny temuż przysionkowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'To wszystko było z kosztownego kamienia pod miarą wyciosanego, i piłą rzezanego, wewnątrz i zewnątrz, od tła aż do stropu, a z dworu aż do wielkiej sieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'A fundament był z kamienia kosztownego, i z kamienia wielkiego, z kamienia na dziesięć łokci, i z kamienia na ośm łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'A nad tem kamienie kosztowne pod miarą wyciosane, z deskami cedrowemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Sień także wielka miała w około trzy rzędy kamienia ciosanego, a jednym rzędem drzewo cedrowe, tak jako sień wnętrzna domu Pańskiego i przysionek domu tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Posłał też król Salomon, i wezwał Hirama z Tyru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'A ten był synem niewiasty wdowy z pokolenia Neftalim, a ojciec jego był obywatel Tyrski, który robił miedzią, a był pełen mądrości i roztropności, i umiejętności na robienie wszelkiej roboty z miedzi; ten przyszedłszy do króla Salomona, zrobił wszelką robotę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Naprzód ulał dwa słupy miedziane; osimnaście łokci było wzwyż słupa jednego, a w okrąg dwanaście łokci; takiż był i drugi słup.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'Potem uczynił dwie gałki, które miano postawić na wierzchu słupów, ulane z miedzi; pięć łokci wzwyż było gałki jednej, a pięć łokci wzwyż gałki drugiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Siatki też robotą dzianą i sznury nakształt łańcuchów posprawiał do tych gałek, które były na wierzchu słupów, siedm na gałkę jednę a siedm na drugą gałkę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'A uczyniwszy słupy sprawił dwa rzędy jabłek granatowych w około na siatce jednej, aby okrywały gałki, które były na wierzchu; także też uczynił i na drugiej gałce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'A na onych gałkach, które były na wierzchu słupów w przysionku, była robota lilii, na cztery łokcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'I miały one gałki na onych dwóch słupach, tak z wierzchu jako i przeciwko środkowi pod siatką, jabłka granatowe, których było dwieście, dwoma rzędami w około, na jednej i na drugiej gałce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'I postawił one słupy w przysionku kościelnym; a postawiwszy słup prawy, nazwał imię jego Jachin; postawiwszy zaś słup lewy, nazwał imię jego Boaz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'A na wierzchu onych słupów były wyrobione lilije. A tak dokonana jest robota onych słupów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Przytem uczynił morze odlewane na dziesięć łokci od jednego brzegu do drugiego brzegu, okrągłe w około; a na pięć łokci była wysokość jego, a okrąg jego na trzydzieści łokci w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'A pod brzegiem jego były pukle nakształt jabłek leśnych, wszędy w około, w każdym łokciu po dziesięć, które okrążyły morze w około; dwa rzędy jabłek lanych z nim ulano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'To morze stało na dwunastu wołach; trzy patrzały na północy, a trzy patrzały ku zachodowi, a trzy patrzały ku południowi, a trzy patrzały ku wschodowi; a morze stało na nich z wierzchu, a wszystkie zady ich były pod morzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'A było miąższe na dłoń, a brzeg jego był jako kraje u kubka, nakształt kwiatu lilijowego, a dwa tysiące wiader brało w się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Uczynił też dziesięć podstawków miedzianych, na cztery łokcie wdłuż podstawek jeden, a na cztery łokcie wszerz, a na trzy łokcie wzwyż.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'A taka była robota każdego podstawka: listwowania miały w około, które listwowania były między krańcami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'A na onem listwowaniu, które było między krańcami, lwy, woły, i Cherubinowie były; a na krańcach był podstawek z wierzchu, a pod onemi lwami i wołmi było przydane obwiedzienie robotą ciągnioną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'A cztery koła miedziane były pod każdym podstawkiem, i deski miedziane; a na czterech rogach jego były podpory jako ramiona, a pod wanną były te ramiona ulane przy każdej stronie obwiedzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'Głębokość wanny od wierzchu do dna nad słupcem była na łokieć, także wierzch jej był okrągły, jako i słupiec, który był na półtora łokcia: a na wierzchu jej były rzezania, i listwowania czworograniste, nie okrągłe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'A tak było po cztery koła pod onem listwowaniem, a osi kół wychodziły z podstawka, a każde koło było wzwyż na półtora łokcia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'A robota tych kół była jako robota kół wozowych; osi ich, i szpice ich, i dzwona ich, i piasty ich, wszystko było odlewane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Były też cztery ramiona na czterech rogach każdego podstawka, z którego wychodziły one ramiona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'A na wierzchu podstawka był słupek wzwyż na pół łokcia zewsząd okrągły, i na wierzchu tegoż podstawka były krańce jego i listwowania, które wychodziły z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'I wyrzezał na deszczkach po krańcach jego, i po listwowaniach jego Cherubiny, lwy, i palmy, jedno podle drugiego, po każdem przydaniu w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Na tenże kształt uczynił dziesięć podstawków odlewanych; jednakiem odlewaniem, jednakiej miary, i jednakiego rzezania wszystkie były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'Przytem uczynił dziesięć wiader miedzianych; czterdzieści wanien brała w się jedna wanna, a każda wanna była na cztery łokcie; jedna wanna stała na jednym podstawku, a tak stały na dziesięciu podstawkach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'I postawił pięć podstawków po prawej stronie domu, a pięć po lewej stronie domu; postawił też morze po prawej stronie domu na wschód słońca ku południu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'Naczynił tedy Hiram wanien i łopat i miednic. A tak dokonał Hiram pracy wszystkiej roboty, którą czynił królowi Salomonowi do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'To jest, dwa słupy, i dwie gałki okrągłe, które były na wierzchu dwóch słupów, i dwie siatki, aby okrywały te dwie gałki okrągłe, które były na wierzchu słupów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'I jabłek granatowych cztery sta na onych dwóch siatkach; dwa rzędy jabłek granatowych były na każdej siatce, aby okrywały te dwie gałki okrągłe, które były na wierzchu słupów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'Także dziesięć podstawków, i dziesięć wanien na podstawkach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'I morze jedno, a wołów dwanaście pod morzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'I panwie, i łopaty, i miednice, i wszystko naczynie, które uczynił Hiram królowi Salomonowi do domu Pańskiego, było z miedzi polerowanej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'To odlewał król na równinie u Jordanu w iłowatej ziemi, między Sochotem i między Sartanem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'Ale Salomon zaniechał ważyć tego wszystkiego naczynia dla mnóstwa bardzo wielkiego; nie upatrowano wagi miedzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'Uczynił też Salomon wszystko inne naczynie do domu Pańskiego: ołtarz złoty, i stół złoty, na którym leżały chleby pokładne;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'I pięć lichtarzy po prawej stronie, a pięć po lewej stronie przed świątnicą z szczerego złota, i kwiaty, i lampy, i nożyczki ze złota;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'I kubki, i harfy, i miednice, i misy, i kadzielnice z szczerego złota, i zawiasy złote do drzwi domu wnętrznego, to jest świątnicy świętych, także do drzwi domu kościoła zawiasy złote.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'A tak dokonana jest wszystka robota, którą sprawił król Salomon do domu Pańskiego. I wniósł tam Salomon rzeczy, które był poświęcił Dawid, ojciec jego, srebro i złoto, i naczynia, i włożył do skarbu domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Tedy zebrał Salomon starsze Izraelskie, i wszystkie celniejsze z każdego pokolenia, i przedniejsze z ojców synów Izraelskich, do siebie do Jeruzalemu, aby przeniesiona była skrzynia przymierza Pańskiego z miasta Dawidowego, które jest Syon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'I zeszli się do króla Salomona wszyscy mężowie Izraelscy mięsiąca Września w uroczyste święto; a ten miesiąc jest siódmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'A gdy się zeszli wszyscy starsi Izraelscy, wzięli kapłani skrzynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'I przenieśli skrzynię Pańską, i namiot zgromadzenia, i wszystkie naczynia święte, które były w namiocie, a przenieśli je kapłani i Lewitowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'Lecz król Salomon, i wszystko mnóstwo Izraelskie, które się zeszło do niego, z nim przed skrzynią ofiarowali owce i woły, których nie liczono ani rachowano dla mnóstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'Wnieśli tedy kapłani skrzynię przymierza Pańskiego na miejsce jej do wnętrznego domu, do świątnicy świętych, pod skrzydła Cherubinów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'Albowiem Cherubinowie mieli rozciągnione skrzydła nad miejscem skrzyni, a okrywali Cherubinowie skrzynię i drążki jej z wierzchu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'I powyciągali one drążki, tak, że widać było końce ich w świątnicy na przodku świątnicy świętych; ale nie widać ich było zewnątrz; i tamże były aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Nic nie było w skrzyni tylko dwie tablice kamienne, które tam był schował Mojżesz na Horebie, gdy stanowił przymierze Pan z synami Izraelskimi, gdy szli z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'I stało się, gdy wychodzili kapłani z świątnicy, że obłok napełnił dom Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'Tak iż się nie mogli kapłani ostać i służyć dla onego obłoku; albowiem napełniła była chwała Pańska dom Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Tedy rzekł Salomon: Pan powiedział, iż miał mieszkać we mgle.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Jużem zbudował dom na mieszkanie tobie, miejsce, abyś tam przebywał na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'I obrócił król oblicze swoje, i błogosławił wszystkiemu zgromadzeniu Izraelskiemu; a wszystko zgromadzenie Izraelskie stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'I rzekł: Błogosławiony Pan, Bóg Izraelski, który mówił usty swemi do Dawida, ojca mego, i skutecznie to wypełnił, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Ode dnia, któregom wywiódł lud mój Izraelski z Egiptu, nie obrałem miasta ze wszystkich pokoleń Izraelskich ku zbudowaniu domu, gdzieby przebywało imię moje, alem obrał Dawida, aby był nad ludem moim Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Postanowiłci był wprawdzie w sercu swem Dawid, ojciec mój, zbudować dom imieniowi Pana, Boga Izraelskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Ale rzekł Pan do Dawida, ojca mego: Aczkolwiekeś postanowił w sercu twem, zbudować dom imieniowi memu, i dobrześ uczynił, żeś to umyślił w sercu twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Wszakże ty nie będziesz budował tego domu; ale syn twój, który wynijdzie z biódr twoich, ten zbuduje dom imieniowi memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'A tak utwierdził Pan słowo swoje, które był powiedział. Bom ja powstał miasto Dawida, ojca mego, i usiadłem na stolicy Izraelskiej, jako był powiedział Pan, i zbudowałem dom imieniowi Pana, Boga Izraelskiego');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'I naznaczyłem tam miejsce skrzyni, w której jest przymierze Pańskie, które uczynił z ojcy naszymi, gdy je wywiódł z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Tedy stanął Salomon przed ołtarzem Pańskim, przed wszystkiem zgromadzeniem Izraelskiem, i wyciągnął ręce swoje ku niebu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'I rzekł: Panie, Boże Izraelski, niemasz tobie podobnego Boga na niebie wzgórę, ani na ziemi nisko; który chowasz umowę i miłosierdzie sługom twym, którzy chodzą przed tobą całem sercem swojem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'Któryś spełnił słudze twemu Dawidowi, ojcu memu, coś mu powiedział; coś mówił usty swemi, toś skutecznie wypełnił, jako się dnia tego pokazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'Przetoż teraz o Panie, Boże Izraelski, ziść słudze twemu Dawidowi, ojcu memu, coś mu powiedział, mówiąc: Nie będzie odjęty przed twarzą moją z narodu twego mąż, któryby siedział na stolicy Izraelskiej, jeźli tylko będą przestrzegali synowie twoi drogi swej, chodząc przede mną, jakoś ty chodził przed oblicznością moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Przetoż teraz, o Boże Izraelski, niech będzie utwierdzone proszę słowo twoje, któreś mówił do sługi twego Dawida, ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, '(Aczci wprawdzie, izali Bóg będzie mieszkał na ziemi? Oto niebiosa, i nieba niebios, nie mogą cię ogarnąć; jakoż daleko mniej ten dom, którym zbudował.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'A wejrzyj na modlitwę sługi twego, i na prośbę jego, o Panie Boże mój, wysłuchaj wołanie i modlitwę, którą się dziś sługa twój modli przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'A niech będą otworzone oczy twoje nad tym domem w nocy i we dnie, nad tem miejscem, o któremeś powiedział: Tu będzie imię moje; abyś wysłuchiwał modlitwę, którą się będzie modlił sługa twój na miejscu tem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Wysłuchajże prośby sługi twego, i ludu twego Izraelskiego, który się modlić będzie na tem miejscu. Ty wysłuchaj z miejsca mieszkania twego, z nieba, a wysłuchawszy bądź miłościw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Gdyby człowiek zgrzeszył przeciwko bliźniemu swemu, a przywiódłby go do przysięgi, tak, żeby przysięgać musiał, a przyszłaby ta przysięga przed ołtarz twój w tym domu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'Ty wysłuchaj z nieba, a rozeznaj i rozsądź sługi twoje, potępiając niezbożnego, i obracając sprawy jego na głowę jego, a usprawiedliwiając sprawiedliwego, oddawając mu według sprawiedliwości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Gdyby był porażony lud twój Izraelski od nieprzyjaciela, przeto iż zgrzeszyli przeciw tobie, a nawróciliby się do ciebie, wyznawając imię twoje, a modląc się, przepraszaliby cię w tym domu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'Ty wysłuchaj z nieba, i odpuść grzech ludowi twemu Izraelskiemu, a przywróć je zasię do ziemi, którąś dał ojcom ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Gdyby zawarte było niebo, a nie byłoby dżdżu, przeto że zgrzeszyli przeciwko tobie, a modliliby się na tem miejscu, wyznawając imię twoje, a od grzechów swoich odwróciliby się, gdybyś je utrapił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'Ty wysłuchaj z nieba, a odpuść grzech sług twoich, i ludu twego Izraelskiego, nauczywszy ich drogi prawej, po której chodzić mają, a daj deszcz na ziemię twoję, którąś dał w dziedzictwo ludowi twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Byłliby głód na ziemi, byłliby mor, susza, rdza, szarańcza, jeźliby były chrząszcze, jeźliby go ścisnął nieprzyjaciel jego w ziemi mieszkania jego, albo jakakolwiek plaga, albo jakakolwiek niemoc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'Wszelką modlitwę, i wszelką prośbę, którąby czynił którykolwiek człowiek, albo wszystek lud twój Izraelski, ktoby jedno uznał ranę serca swego, i wyciągnąłby ręce swe w domu tym:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'Ty wysłuchaj z nieba, z miejsca mieszkania twego, a odpuść, i uczyń, i oddaj każdemu według wszelkich dróg jego, które znasz w sercu jego; bo ty, ty sam znasz serca wszystkich synów ludzkich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'Aby się ciebie bali po wszystkie dni, które żyć będą na ziemi, którąś dał ojcom naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Nadto i cudzoziemiec, który nie jest z ludu twego Izraelskiego, przyjdzieli z ziemi dalekiej dla imienia twego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(Bo usłyszą o imieniu twojem wielkiem, i o ręce twojej możnej, i o ramieniu twojem wyciągnionem,) przyjdzieli tedy, a będzie się modlił w tym domu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'Ty wysłuchaj z nieba, z miejsca mieszkania twego, a uczyń wszystko, o co zawoła do ciebie on cudzoziemiec, aby poznali wszyscy narodowie ziemscy imię twoje, i bali się ciebie, jako lud twój Izraelski, a żeby wiedzieli, że imię twoje wzywane jest nad tym domem, którym zbudował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Gdyby wyszedł lud twój na wojnę przeciwko nieprzyjacielowi swemu drogą, którą je poślesz, a modliliby się Panu, obróciwszy się ku miastu, któreś obrał, i ku domowi, którym zbudował imieniowi twemu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'Wysłuchajże z nieba modlitwę ich, i prośbę ich, a wykonaj sąd ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Gdyby też zgrzeszyli przeciwko tobie, (bo niemasz człowieka, któryby nie grzeszył,) a rozgniewawszy się na nie, podałbyś je pod moc nieprzyjacielowi, któryby je pojmawszy, zawiódł je w niewolę, do ziemi nieprzyjacielskiej, dalekiej albo bliskiej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'A upamiętaliby się w sercu swojem w onej ziemi, do której są zaprowadzeni w niewolę, i nawróciliby się, a przepraszaliby cię w ziemi tych, którzy je pojmali, mówiąc: Zgrzeszyliśmy, i źleśmy uczynili, niepobożnieśmy się sprawowali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'A tak nawróciliby się do ciebie z całego serca swego, i z całej duszy swej, w ziemi nieprzyjaciół swoich, którzy je pojmali, a modliliby się tobie, obróciwszy się ku ziemi swej, którąś dał ojcom ich, ku miastu, któreś obrał, i ku domowi, którym zbudował imieniowi twemu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'Wysłuchajże tedy z nieba, z miejsca mieszkania twego, modlitwę ich i prośbę ich, a wykonaj sąd ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'A bądź miłościw ludowi twemu, który przeciw tobie zgrzeszył, i wszystkim nieprawościom ich, któremi wystąpili przeciw tobie, a nakłoń ku nim miłosierdzia tych, którzy je pojmali, aby się zmiłowali nad nimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'Ponieważ są ludem twoim, i dziedzictwem twojem, któreś wywiódł z Egiptu, z pośrodku pieca żelaznego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Niech będą oczy twoje otwarte na prośbę sługi twego, i na prośbę ludu twego Izraelskiego, abyś je wysłuchał we wszystkiem, o co cię wzywać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Albowiemeś je ty sobie odłączył za dziedzictwo ze wszystkich narodów ziemi, jakoś powiedział przez Mojżesza, sługę twego, gdyś wywiódł ojce nasze z Egiptu, o Panie Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'I stało się, gdy Salomon modląc się Panu dokonał wszystkiej onej modlitwy i prośby, że wstał od ołtarza Pańskiego, a przestał klęczeć i podnosić rąk swoich ku niebu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'A stojąc błogosławił wszystkiemu zgromadzeniu Izraelskiemu wielkim głosem, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Błogosławiony Pan, który dał odpocznienie ludowi swemu Izraelskiemu, według wszystkiego, co powiedział; nie chybiło żadne słowo ze wszystkich słów jego dobrych, które mówił przez Mojżesza, sługę swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Niechże będzie Pan, Bóg nasz, z nami, jako był z ojcy naszymi; niech nas nie opuszcza, ani nas odrzuca;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'Ale niech nakłoni serce nasze ku sobie, żebyśmy chodzili po wszystkich drogach jego, strzegąc rozkazania jego, i wyroków jego, i sądów jego, które przykazał ojcom naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'A niech będą te słowa moje, któremim się modlił przed Panem, bliskie Pana Boga naszego we dnie i w nocy, aby wykonywał sąd sługi swego, i sąd ludu swego Izraelskiego, sądząc każdą sprawę dnia swojego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'Żeby poznali wszyscy narodowie ziemscy, iż Pan sam jest Bogiem, a nikt inszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Niechże tedy będzie serce wasze doskonałe ku Panu, Bogu naszemu, abyście chodzili w wyrokach jego, a strzegli przykazań jego, jako i dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'Tedy król, i wszystek Izrael z nim, sprawowali ofiary przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'I ofiarował Salomon ofiarę spokojną, którą sprawował Panu, wołów dwadzieścia i dwa tysiące, i owiec sto i dwadzieścia tysięcy. A tak poświęcali dom Pański król i wszyscy synowie Izraelscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Onegoż dnia poświęcił król pośrodek sieni, która była przed domem Pańskim; bo tam ofiarował całopalenie, i ofiarę śniedną, i tłustości ofiar spokojnych, przeto że ołtarz miedziany, który był przed Panem, był mały, i nie mogły się na nim zmieścić całopalenia, i ofiary śniedne, i tłustości ofiar spokojnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'A tak obchodził Salomon na on czas święto zacne, i wszystek Izrael z nim, zgromadzenie wielkie od wejścia do Emat aż do rzeki Egipskiej, przed Panem, Bogiem naszym, przez siedm dni i przez siedm dni, to jest, przez czternaście dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'A dnia ósmego rozpuścił lud; którzy błogosławiąc królowi, rozeszli się do przybytków swoich, weseląc się, i ciesząc się w sercu swem ze wszystkiego dobrego, które uczynił Pan Dawidowi, słudze swemu, i Izraelowi, ludowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'I stało się, gdy dokończył Salomon budowania domu Pańskiego, i domu królewskiego, i wszystkiego, co żądał Salomon i chciał uczynić,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'Że się Pan ukazał Salomonowi powtóre, jako mu się ukazał w Gabaon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'I rzekł Pan do niego: Wysłuchałem modlitwę twoję, i prośbę twoję, którąś się modlił przedemną, a poświęciłem ten dom, któryś zbudował, aby tam przebywało imię moje aż na wieki; i będą tam oczy moje i serce moje po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'A jeźli ty będziesz chodził przedemną, jako chodził Dawid, ojciec twój, w doskonałości serca i w prostości, a będziesz się sprawował według wszystkiego, comci przykazał, strzegąc wyroków moich i sądów moich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'Tedy utwierdzę stolicę królestwa twego nad Izraelem na wieki, jakom powiedział Dawidowi, ojcu twemu, mówiąc: Nie będzie odjęty z narodu twego mąż z stolicy Izraelskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Ale jeźli się nazad odwrócicie wy i synowie wasi ode mnie, a nie będziecie strzegli przykazań moich, i wyroków moich, którem wam podał, ale odszedłszy będziecie służyli bogom cudzym, i będziecie się im kłaniali:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'Tedy wytracę Izraela z ziemi, którąm im dał, a dom, którym poświęcił imieniowi memu, odrzucę od oblicza mego, a będzie Izrael przypowieścią i baśnią między wszystkimi narodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'A tak i ten dom, który był sławny, każdemu mimo idącemu będzie na podziw i na poświstanie, i rzecze: Przeczże tak uczynił Pan tej ziemi i temu domowi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'Tedy odpowiedzą: Przeto, iż opuścili Pana, Boga swego, który wywiódł ojce ich z ziemi Egipskiej, a chwycili się bogów cudzych, i kłaniali się im, a służyli im: dla tegoż przywiódł Pan na nie to wszystko złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'I stało się po wyjściu dwudziestu lat, w których zbudował Salomon owe oba domy, dom Pański i dom królewski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'Do czego Hiram, król Tyrski, nadał był Salomonowi drzewa cedrowego, i drzewa jodłowego, i złota, ile jedno chciał: tedy też król Salomon dał Hiramowi dwadzieścia miast w ziemi Galilejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'I wyjechał Hiram z Tyru, aby oglądał miasta, które mu dał Salomon: ale mu się niepodobały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'I rzekł: Cóż to za miasta, któreś mi dał, bracie mój? I nazwał je ziemią Chabul, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Albowiem posłał był Hiram królowi sto i dwadzieścia talentów złota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'A przyczyna poboru, który był rozkazał wybierać król Salomon, była, aby zbudował dom Pański, i dom swój, i Mello, i mury Jeruzalemskie, i Hasor, i Magieddo, i Gazer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Farao bowiem, król Egipski, wyciągnął był, i wziął Gazer, i popalił je ogniem, a Chananejczyka, który mieszkał w tem mieście, wymordował, a dał je za posag córce swej, żonie Salomonowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'A tak zbudował Salomon Gazer i Betoron niższe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'Przytem Baalat i Tadmor na puszczy w tejże ziemi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'I wszystkie miasta, w których miał składy Salomon, i miasta wozów, i miasta jezdnych, i wszystko według żądości Salomonowej, cokolwiek chciał budować w Jeruzalemie i na Libanie, i we wszystkiej ziemi państwa swojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Wszystek także lud, który był pozostał z Amorejczyków, Hetejczyków, Ferezejczyków, Hewejczyków, i Jebuzejczyków, którzy nie byli z synów Izraelskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'To jest, syny ich, którzy byli pozostali po nich w ziemi, których nie mogli synowie Izraelscy wytracić, uczynił Salomon hołdownikami i niewolnikami aż do dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'Ale z synów Izraelskich nie uczynił Salomon żadnego niewolnikiem; jedno byli ludźmi rycerskimi, i sługami jego, i książęty, i hetmany jego, i przełożonymi nad wozami jego, i nad jezdnymi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Było tych przedniejszych z przełożonych, którzy byli nad robotą Salomonową, pięć set i pięćdziesiąt, co byli nad ludźmi wykonywającymi robotę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Lecz córka Faraonowa przeprowadziła się z miasta Dawidowego do domu swego, który jej zbudował Salomon. Tedy zbudował i Mello.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'I ofiarował Salomon trzy kroć na każdy rok całopalenia a spokojne ofiary na ołtarzu, który był zbudował Panu; ale kadził na onym ołtarzu, który był przed Panem, gdy dokonał domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'Okrętów też nabudował król Salomon w Asyjongaber, które jest podle Elotu, nad brzegiem morza czerwonego, w ziemi Edomskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'I posłał Hiram na tychże okrętach sługi swe, żeglarze świadome morza, z sługami Salomonowymi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'Którzy przypłynąwszy do Ofir, wzięli stamtąd złota cztery sta i dwadzieścia talentów, i przywieźli je do króla Salomona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'A królowa z Saby usłyszawszy sławę o Salomonie i o imieniu Pańskiem przyjechała, aby go doświadczyła w zagadkach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'I wjechała do Jeruzalemu z wielkim bardzo pocztem, z wielbłądami niosącemi rzeczy wonne, i złota bardzo wiele, i kamienia drogiego, a przyszedłszy do Salomona mówiła do niego o wszystkiem, co miała w sercu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'Ale jej odpowiedział Salomon na jej wszystkie słowa; nie było nic skrytego przed królem, na coby jej nie odpowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Przetoż widząc królowa z Saby wszystkę mądrość Salomonową, i dom, który był zbudował,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'Także potrawy stołu jego, i siadania sług jego, i stawania służących mu, i szaty ich, i podczasze jego, i wschody, po których wstępował do domu Pańskiego, zdumiała się bardzo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'I rzekła do króla: Prawdziwać to mowa, którąm słyszała w ziemi mojej o sprawach twoich, i o mądrości twojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Alem nie wierzyła powieściom onym, ażem sama przyjechawszy oglądała to oczyma swemi. Ale mi tego nie powiedziano i połowy. Większa jest mądrość i dobroć twoja niżeli sława, którąm słyszała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Błogosławieni mężowie twoi, błogosławieni słudzy twoi, którzy zawsze przed tobą stoją, i słuchają mądrości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Niechże będzie Pan, Bóg twój, błogosławiony, który cię sobie upodobał, aby cię posadził na stolicy Izraelskiej, przeto iż Pan umiłował Izraela na wieki, i postanowił cię królem, abyś czynił sąd i sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'I dała królowi sto i dwadzieścia talentów złota, i rzeczy wonnych bardzo wiele, i kamienia drogiego. Nie przyszło nigdy potem tak wiele wonnych rzeczy, jako dała królowa z Saby królowi Salomonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Nadto okręty Hirama, które przynosiły złoto z Ofir, przyniosły z Ofir drzewa almugimowego bardzo wiele i kamienia drogiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'I poczynił król z drzewa almugimowego wschody do domu Pańskiego, i do domu królewskiego, i harfy, i lutnie śpiewakom; a nigdy nie przywożono takiego drzewa almugimowego, ani widziano aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'Król także Salomon dał królowej z Saby wszystko, czego chciała i czego żądała, oprócz tego, co jej dał z dobrej woli ręką królewską. Potem odjechawszy, wróciła się do ziemi swojej, ona i słudzy jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'A była waga onego złota, które przychodziło Salomonowi na każdy rok, sześć set sześćdziesiąt i sześć talentów złota,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'Oprócz tego, co przychodziło od kupców i z handlu tych, którzy rzeczami wonnemi kupczyli, i od wszystkich królów Arabskich, i książąt ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'Przetoż uczynił król Salomon dwieście tarczy ze złota ciągnionego, sześć set syklów złota wychodziło na każdą tarczą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'Przytem trzy sta puklerzy ze złota ciągnionego, trzy grzywny złota odważył na każdy puklerz. I schował je król w domu lasu Libanowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Uczynił także król stolicę wielką z kości słoniowej, i powlókł ją szczerem złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Sześć stopni było u onej stolicy, a wierzch okrągły był na stolicy z tyłu; i poręcze były z obudwu stron siedzenia, a dwa lwy stały u poręczy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'A dwanaście lwów stało na onych sześciu stopniach z obu stron. Nie było nic takiego urobiono w żadnych królestwach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Nadto wszystkie naczynia, z których pijał król Salomon, były złote, także i wszystkie naczynia domu lasu Libanowego były z szczerego złota; nic nie było ze srebra, ani go miano w jakiej cenie za dni Salomonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Albowiem okręty królewskie były na morzu z okrętami Hiramowemi: raz we trzy lata wracały się okręty z morza, przynosząc złoto i srebro, kości słoniowe, i koczkodany, i pawie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'A tak uwielmożniony jest król Salomon nad wszystkie króle ziemskie bogactwy i mądrością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'Przetoż wszyscy obywatele ziemi pragnęli widzieć Salomona, aby słuchali mądrości jego, którą był dał Bóg w serce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'I przynosił mu każdy dary swe, naczynia srebrne i naczynia złote, i szaty, i zbroje, i rzeczy wonne, konie, i muły, a to na każdy rok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'Tak iż nazgromadzał Salomon wozów, i jezdnych, a miał tysiąc i czterysta wozów, i dwanaście tysięcy jezdnych, które rozsadził po miastach wozów, i przy sobie w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'I złożył król srebra w Jeruzalemie tak wiele, jako kamienia, a ceder jako sykomorów, których na polu rośnie bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'Przywodzono też konie Salomonowi z Egiptu, i towary rozliczne; bo kupcy królewscy brali towary rozliczne za pewne pieniądze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'A wychodził i przychodził cug woźników z Egiptu za sześć set srebrników, a koń za sto i pięćdziesiąt. A tak wszyscy królowie Hetejscy, i królowie Syryjscy z rąk ich koni dostawali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'Tedy król Salomon rozmiłował się niewiast obcych wiele: nie tylko córki Faraonowej, ale i Moabitczanek, Ammonitczanek, Edomczanek, Sydończanek, Hetejczanek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'Z tych narodów, o których powiedział Pan synom Izraelskim: Nie wchodźcie do nich, i one niech nie wchodzą do was; albowiem nakłoniłyby serce wasze za bogi swymi. Do tych przylgnął Salomon miłością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'Tak iż miał żon królowych siedm set, a założnic trzy sta; i odwróciły żony jego serce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'I stało się, gdy już był Salomon stary, że żony jego nakłoniły serce jego za bogi cudzymi, tak iż nie było serce jego zupełne z Panem, Bogiem jego, jako serce Dawida, ojca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'Ale udał się Salomon za Astarotą, boginią Sydońską, i za Molochem, obrzydliwością Ammonitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'I uczynił Salomon, co się nie podobało Panu, ani chodził doskonale za Panem, jako Dawid, ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Tedy zbudował Salomon kaplicę Chamosowi, obrzydliwości Moabskiej, na górze przeciw Jeruzalemowi i Molochowi, obrzydliwości synów Ammonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'I tak uczynił wszystkim żonom swym cudzoziemkom, które kadziły, i ofiarowały bogom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'I rozgniewał się Pan na Salomona, że się odwróciło serce jego od Pana, Boga Izraelskiego, który się mu był ukazał po dwa kroć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'I zakazał mu tego, aby nie chodził za bogi cudzymi; wszakże nie strzegł tego, co Pan przykazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Przetoż rzekł Pan do Salomona: Ponieważeś się tego dopuścił, nie strzegąc przymierza mego, ani wyroków moich, którem ci przykazał, pewnie oderwę królestwo od ciebie, a dam je słudze twojemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Wszakże za dni twoich nie uczynię tego dla Dawida, ojca twego; ale z ręki syna twego oderwę je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Lecz wszystkiego królestwa nie oderwę; pokolenie jedno dam synowi twemu dla Dawida, sługi mego, i dla Jeruzalemu, którem obrał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Przetoż wzbudził Pan przeciwnika Salomonowi, Adada Edomczyka z nasienia królewskiego, który był w Edom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Albowiem stało się, gdy Dawid był w Edom, a Joab, hetman wojska, wyjechał, aby pochował pobite, i pobił wszystkie mężczyzny w Edom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(Bo tam sześć miesięcy mieszkał Joab ze wszystkimi Izraelczykami, aż wytracił wszystkie mężczyzny w Edom.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'Tedy uciekł Adad sam, i niektórzy mężowie Edomscy z sług ojca jego z nim, aby szli do Egiptu; a Adad był chłopcem nie wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'Którzy wyszedłszy z Madyjan przyszli do Faran, a wziąwszy z sobą niektóre męże z Faran weszli do Egiptu, do Faraona króla Egipskiego, który mu dał dom, i żywność mu naznaczył, dał mu też i ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'I znalazł Adad wielką łaskę w oczach Faraonowych, tak, iż mu dał za żonę siostrę żony swej, siostrę królowej Tafnes.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'I porodziła mu siostra Tafnes Gienubata, syna jego, którego odchowała Tafnes w domu Faraonowym. I był Gienubat w domu Faraonowym między syny Faraonowymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'A gdy usłyszał Adad w Egipcie, iż zasnął Dawid z ojcy swymi, a iż umarł Joab, hetman wojska, tedy rzekł Adad do Faraona: Puść mię, że pójdę do ziemi mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Któremu odpowiedział Farao: Czegoż ci niedostawa u mnie, że chcesz iść do ziemi twojej? A on rzekł: Niczego; a wszakże puść mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'Wzbudził także Bóg nań przeciwnika, Rezona, syna Elijadowego, który był uciekł od Adarezera, króla Soby, Pana swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'A zebrawszy do siebie męże, był książęciem roty, gdy je Dawid mordował; przetoż odszedłszy do Damaszku, mieszkali w nim, a królowali nad Damaszkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'I był przeciwnikiem Izraelowi po wszystkie dni Salomonowe, a to oprócz szkód, które mu czynił Adad; bo się brzydził Izraelem, gdy królował w Syryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Jeroboam też, syn Nabata Efratejczyka z Saredy, (a imię matki jego Serwa, która była wdową,) sługa Salomonowy, podniósł przeciwko królowi rękę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'A tać była przyczyna, dla której podniósł rękę swą przeciwko królowi, że Salomon zbudowawszy Mello, zaprawił dziurę w mieście Dawida, ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'A Jeroboam był mąż mocny i możny. Przetoż widząc Salomon młodzieńca, że był sprawny, postanowił go nad podatkami wszystkiemi domu Józefowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'I stało się tegoż czasu, gdy Jeroboam wyszedł z Jeruzalemu, że go znalazł na drodze Achyjasz Sylonitczyk, prorok, będąc odziany płaszczem nowym; a tylko sami dwaj byli na polu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'Tedy wziąwszy Achyjasz płaszcz nowy, który miał na sobie, rozdarł go na dwanaście sztuk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'I rzekł do Jeroboama: Weźmij sobie dziesięć sztuk; bo tak mówi Pan, Bóg Izraelski: Oto Ja oderwę królestwo z rąk Salomonowych, a dam tobie dziesięć pokoleń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, 'Jedno tylko pokolenie zostanie mu dla sługi mego Dawida, i dla miasta Jeruzalem, którem obrał ze wszystkich pokoleń Izraelskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'Przeto, że mię opuścili, a kłaniali się Astarocie, bogini Sydońskiej, i Chamosowi, bogu Moabskiemu, i Molochowi, bogu synów Ammonowych, a nie chodzili drogami mojemi, aby czynili to, co się mnie podoba, ani też strzegli wyroków moich, i sądów mo ich, jako Dawid, ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Wszakże nie odejmę wszystkiego królestwa z ręki jego, owszem zostawię go książęciem po wszystkie dni żywota jego dla Dawida, sługi mego, któregom obrał, który strzegł rozkazania mego i wyroków moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Ale wziąwszy królestwo z ręki syna jego, dam tobie z niego dziesięć pokoleń:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'A synowi jego dam pokolenie jedno, aby została pochodnia Dawidowi, słudze memu, po wszystkie dni przedemną w mieście Jeruzalemie, którem sobie obrał, aby tam przebywało imię moje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'A ciebie wezmę, abyś królował nad wszystkiem, czego żąda dusza twoja, a będziesz królem nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'Przetoż jeźli będziesz słuchał wszystkiego, coć przykażę, a będziesz chodził drogami mojemi, czyniąc to, co dobrego jest w oczach moich, strzegąc wyroków moich, i przykazań moich, jako czynił Dawid, sługa mój: tedy będę z tobą, a zbudujęć dom mocny, jakom zbudował Dawidowi, i podam ci Izraela;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'I trapić będę nasienie Dawidowe dla tego; a wszakże nie po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Przetoż Salomon chciał zabić Jaroboama; ale wstawszy Jeroboam uciekł do Egiptu, do Sesaka, króla Egipskiego, i był w Egipcie aż do śmierci Salomonowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'A inne sprawy Salomonowe, którekolwiek czynił, i mądrość jego, izali nie są wypisane w księgach spraw Salomonowych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'A dni, których królował Salomon w Jeruzalemie nad wszystkim Izraelem, było czterdzieści lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'I zasnął Salomon z ojcy swymi, a pogrzebiony jest w mieście Dawida, ojca swego; i królował Roboam, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'Tedy jechał Roboam do Sychem; bo w Sychem zebrał się był wszystek Izrael, aby go postanowili królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'I stało się, gdy usłyszał Jeroboam, syn Nabata, który był jeszcze w Egipcie; (bo był uciekł przed królem Salomonem, i mieszkał Jeroboam w Egipcie.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'Tedy posłali i wezwali go. Przetoż przyszedłszy Jeroboam, i wszystko zgromadzenie Izraelskie, rzekli do Roboama, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Ojciec twój włożył na nas jarzmo ciężkie; ale ty teraz ulżyj nam niewoli srogiej ojca twego, i jarzma jego ciężkiego, które włożył na nas, a będziemyć służyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'Który im rzekł: Odejdźcie, a po trzech dniach wróćcie się do mnie. I odszedł lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'Tedy wszedł w radę król Roboam z starszymi, którzy stawali przed Salomonem, ojcem jego, za żywota jego,mówiąc: Co wy radzicie, jakąbym miał dać odpowiedź ludowi temu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'Którzy mu odpowiedzieli, mówiąc: Jeźli dziś powolny będziesz ludowi temu, a posłuchasz ich, i dasz im odpowiedź, a będziesz mówił do nich słowa łagodne, będą sługami twymi po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Ale on opuściwszy radę starszych, którą mu podali, wszedł w radę z młodzieńcami, którzy z nim wzrośli, a którzy stawali przed nim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'I rzekł do nich: A wy co radzicie, abyśmy odpowiedzieli ludowi temu, który rzekł do mnie, mówiąc: Ulżyj jarzma, które włożył ojciec twój na nas?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Tedy mu odpowiedzieli oni młodzieńcy, którzy z nim wzrośli, mówiąc:Tak odpowiesz temu ludowi, którzy mówili do ciebie, a rzekli: Ojciec twój włożył na nas jarzmo ciężkie, ale nam go ty ulżyj; tak rzeczesz do nich: Najmniejszy palec mój mięższy jest niż biodra ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Przetoż teraz ojciec mój kładł na was jarzmo ciężkie, ale ja przydam do jarzma waszego; ojciec mój karał was biczykami, ale ja was będę karał korbaczami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Przyszedł tedy Jeroboam, i wszystek lud do Roboama dnia trzeciego, jako był rozkazał król, mówiąc: Wróćcie się do mnie dnia trzeciego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'I dał srogą odpowiedź król ludowi, opuściwszy radę starszych, którą mu byli dali,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'A rzekł do nich według rady młodzieńców, mówiąc: Ojciec mój obciążał was jarzmem ciężkiem, ale ja przydam do jarzma waszego; ojciec mój karał was biczykami, ale ja was będę karał korbaczami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'I nie usłuchał król ludu; bo była przyczyna od Pana, aby dosyć uczynił słowu swemu, które był powiedział Pan przez Achyjasza Sylonitczyka do Jeroboama, syna Nabatowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'A gdy widział wszystek Izrael, że ich nie usłuchał król, odpowiedział lud królowi, tak mówiąc: Cóż my mamy za dział w Dawidzie? a co za dziedzictwo w synu Isajowym? Idź do namiotów swych, o Izraelu, a ty Dawidzie opatrz teraz dom twój. I rozeszli się Izraelczycy do namiotów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'A tak tylko nad synami Izraelskimi, którzy mieszkali w mieściech Judzkich, królował Roboam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'I posłał król Roboam Adorama, który był poborcą, i ukamionował go wszystek Izrael, aż umarł; przetoż król Roboam, wsiadłszy co rychlej na wóz, uciekł do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'A tak odstąpili Izraelczycy od domu Dawidowego, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'I stało się, gdy usłyszał wszystek Izrael, że się wrócił Jeroboam, posławszy przyzwali go do zgromadzenia, i postanowili go królem nad wszystkim Izraelem. Nie zostało przy domu Dawidowym jedno samo pokolenie Judowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'A przyjechawszy Roboam do Jeruzalemu, zebrał wszystek dom Judowy, i pokolenie Benjaminowe, sto i ośmdziesiąt tysięcy mężów przebranych ku bojowi, aby walczyli z domem Izraelskim, ażeby przywrócone było królestwo Roboamowi, synowi Salomonowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'I stało się słowo Boże do Semejasza, męża Bożego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Powiedz Roboamowi, synowi Salomonowemu, królowi Judzkiemu i wszystkiemu domowi Judowemu i Benjaminowemu, i innemu ludowi, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Tak mówi Pan: Nie wychodźcie, ani walczcie z bracią swoją, synmi Izraelskimi; wróćcie się każdy do domu swego: albowiem odemnie się ta rzecz stała. I usłuchali rozkazania Pańskiego, a wrócili się, aby odeszli według słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Potem zbudował Jeroboam Sychem na górze Efraim, i mieszkał w nim, a stamtąd wyszedłszy pobudował Fanuel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'I rzekł Jeroboam w sercu swem: Wnetby się wróciło królestwo do domu Dawidowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Gdyby chadzał ten lud sprawować ofiary do domu Pańskiego do Jeruzalemu, i obróciłoby się serce ludu tego do pana swego, do Roboama, króla Judzkiego, a zabiwszy mię, wróciliby się do Roboama, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Przetoż naradziwszy się król, uczynił dwóch cielców złotych, i mówił do ludu: Dosycieście się nachodzili do Jeruzalemu; oto bogowie twoi, o Izraelu, którzy cię wywiedli z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'I postawił jednego w Betel, a drugiego postawił w Dan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'I było to pobudką do grzechu, bo chadzał lud do jednego z tych bogów aż do Dan,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'Uczynił też dom na wyżynach, i postanowił kapłany niektóre z pospólstwa, którzy nie byli z synów Lewiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'Nadto ustanowił Jeroboam święto uroczyste miesiąca ósmego, piętnastego dnia tegoż miesiąca, nakształt święta, które obchodzono w Judzie, i ofiarował na ołtarzu. Toż uczynił w Betel, ofiarując cielcom, które był uczynił; postanowił też kapłany w Betel na wyżynach, które był poczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'I sprawował też ofiary na ołtarzu, który był uczynił w Betel, piętnastego dnia miesiąca ósmego, onegoż miesiąca, który był wymyślił w sercu swojem; i uczynił święto uroczyste synom Izraelskim, a przystąpił do ołtarza, aby kadził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'A oto mąż Boży przyszedł z Judztwa z słowem Pańskiem do Betel, gdy Jeroboam stał u ołtarza, aby kadził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'I zawołał przeciw ołtarzowi słowem Pańskiem, i rzekł: Ołtarzu, ołtarzu, tak mówi Pan: Oto syn narodzi się domowi Dawidowemu imieniem Jozyjasz, który będzie ofiarował na tobie kapłany wyżyn, kadzące na tobie, i kości ludzkie popalą na tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'I dał mu znak dnia onegoż, mówiąc: Tenci jest znak, że to mówił Pan: Oto się ołtarz rozpadnie, a wysypie się popiół, który jest na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'A gdy usłyszał król Jeroboam słowo męża Bożego, które obwoływał przeciw ołtarzowi w Betel, ściągnął rękę swą od ołtarza, mówiąc: Pojmajcie go. I uschła ręka jego, którą był wyciągnął przeciw niemu, a niemógł jej przyciągnąć do siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Ołtarz się też rozpadł, a wysypał się popiół z ołtarza według znaku, który był dał mąż Boży słowem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'Przetoż odpowiadając król, rzekł do męża Bożego: Proszę cię, proś oblicza Pana Boga twego, a módl się za mną, aby się wróciła ręka moja do mnie. I modlił się mąż Boży obliczu Pańskiemu, i wróciła się ręka królewska do niego, i była jako pierwej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Tedy rzekł król do męża Bożego: Pójdź ze mną do domu, abyś się posilił, a dam ci upominek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'Ale rzekł mąż Boży do króla: Byśmi dał połowę domu twego, nie pojadę z tobą, ani będę jadł chleba, ani będę pił wody na tem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Bo mi tak Pan rozkazał słowem swojem, mówiąc: Nie będziesz jadł chleba, ani będziesz pił wody, ani się wrócisz tą drogą, którąś przyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'Odszedł tedy inszą drogą, a nie wrócił się tą drogą, którą był przyszedł do Betel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'A prorok niejaki stary mieszkał w Betel, którego syn przyszedłszy, opowiedział mu wszystkę sprawę, którą był uczynił onegoż dnia mąż Boży w Betel, i słowa, które mówił do króla, opowiedzieli ojcu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'I rzekł im ojciec ich: Którąż drogą poszedł? I pokazali synowie jego drogę, którą poszedł on mąż Boży, który był przyszedł z Judztwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Zatem rzekł synom swym: Osiodłajcie mi osła; i osiodłali mu osła, i wsiadł nań,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'I jechał za mężem Bożym, a znalazł go siedzącego pod dębem, i rzekł mu: Tyżeś jest on mąż Boży, któryś przyszedł z Judztwa? A on rzekł: Jestem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'I rzekł do niego: Pójdź zemną do domu, żebyś jadł chleb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'Ale mu on rzekł: Nie mogę się wrócić z tobą, ani iść z tobą, ani będę jadł chleba, ani będę pił wody z tobą na tem miejscu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'Bo się stała do mnie mowa słowem Pańskiem: Nie będziesz tam jadł chleba, ani pił wody, ani się wrócisz idąc tą drogą, którąś szedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Któremu on odpowiedział: I jam prorok jako i ty; Anioł też rzekł do mnie słowem Pańskiem, mówiąc: Wróć go z sobą do domu twego, aby jadł chleb, i pił wodę. I tak skłamał przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'I wrócił się z nim, a jadł chleb w domu jego, i pił wodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'A gdy siedzieli u stołu, stało się słowo Pańskie do proroka, który go był wrócił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'I zawołał na męża Bożego, który był przyszedł z Judztwa, mówiąc: Tak mówi Pan: Przeto żeś był odpornym ustom Pańskim, a nie strzegłeś rozkazania, któreć przykazał Pan, Bóg twój:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'Aleś się wrócił, i jadłeś chleb, a piłeś wodę na miejscu, o któremem ci był rzekł: Nie będziesz tam jadł chleba, ani pił wody: nie będzie pochowany trup twój w grobie ojców twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'A tak gdy się najadł chleba i napił się, osiodłał osła prorokowi onemu, którego był wrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'A gdy odjechał, spotkał go lew w drodze, i zabił go. A trup jego był porzucony w drodze, a osieł stał wedle niego, lew także stał podle trupa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'A oto mężowie mimo idący ujrzeli trupa porzuconego na drodze i lwa stojącego podle niego: którzy przyszedłszy powiedzieli to w mieście, w którem on stary prorok mieszkał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'Co gdy usłyszał on prorok, który go był wrócił z drogi, rzekł: Mąż Boży jest, który był odpornym ustom Pańskim; przetoż podał go Pan lwowi, który go potarł, i zabił go według słowa Pańskiego, które mu był powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'Nadto rzekł do synów swoich, mówiąc: Osiodłajcie mi osła. I osiodłali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'A wyjechawszy znalazł trupa jego porzuconego na drodze, a osła i lwa stojące przy trupie, ale nie jadł lew onego trupa, ani obraził osła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Tedy wziął prorok trupa męża Bożego, a włożywszy go na osła, przywiózł go; i przyszedł do miasta swego, aby płakał i pogrzebł go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'A położył trupa jego w grobie swoim, i płakali go, mówiąc: Ach bracie mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'A pochowawszy go, rzekł do synów swoich: Gdy ja umrę. pochowajcie mię w tym grobie, w którym jest mąż Boży pochowany; podle kości jego połóżcie kości moje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Bo zapewne się to stanie, co obwołał słowem Pańskiem, przeciw ołtarzowi, który jest w Betel, i przeciwko wszystkim domom wyżyn, które są w mieściech Samaryjskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'To gdy się stało, przecież się nie odwrócił Jeroboam od drogi swej złej, ale znowu naczynił z pospolitego ludu kapłanów wyżyn; kto jedno chciał, poświęcał rękę jego, aby był kapłanem wyżyn.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'I była ta rzecz domowi Jeroboamowemu przyczyną do grzechu, aby był wykorzeniony i wygładzony z ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'Tegoż czasu rozniemógł się Abijas, syn Jeroboama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'I rzekł Jeroboam do żony swej: Wstań teraz, a odmień się, aby nie poznano, żeś ty żoną Jeroboamową, a idź do Sylo; oto tam jest Achyjasz prorok, który mi powiedział, żem miał zostać królem nad tym ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'A wziąwszy z sobą dziesięcioro chleba, i placków, i faskę miodu, idź do niego; on ci oznajmi, co się stanie dziecięciu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'I uczyniła tak żona Jeroboamowa, a wstawszy poszła do Sylo, i weszła do domu Achyjaszowego; ale Achyjasz nie mógł już widzieć, bo mu były zaszły oczy dla starości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'A Pan rzekł do Achyjasza: Oto żona Jeroboamowa wchodzi, aby się od ciebie czego wywiedziała o synu swym, przeto że choruje; ale tak a tak rzeczesz jej, a stanie się, gdy będzie wchodziła, zmyśli się być inszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Przetoż gdy usłyszał Achyjasz tupanie nóg jej, wchodzącej we drzwi, rzekł: Wnijdź żono Jeroboamowa; przecz się zmyślasz być inszą? Jam bowiem srogim posłem do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Idź, powiedz Jeroboamowi: Tak mówi Pan, Bóg Izraelski: Ponieważem cię wywyższył z pośrodku ludu, a postanowiłem cię książęciem nad ludem moim Izraelskim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'I oderwałem królestwo od domu Dawidowego, a dałem je tobie, tyś jednak nie był jako sługa mój Dawid, który strzegł rozkazania mego, i który chodził za mną całem sercem swojem, to tylko czyniąc, co jest dobrego w oczach moich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'Aleś czynił złe nad wszystkie, którzy byli przed tobą; albowiem odszedłszy, poczyniłeś sobie bogi cudze, i lane, abyś mię pobudził do gniewu, a mnieś zarzucił w tył sobie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'Przetoż oto Ja przywiodę złe na dom Jeroboamowy, i wytracę z Jeroboama aż do najmniejszego szczenięcia, więźnia, i opuszczonego w Izraelu, i wymiotę ostatki domu Jeroboamowego, jako wymiatają gnój, aż do czysta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Tego, który z domu Jeroboamowego umrze w mieście, zjedzą psy, a który umrze na polu, zjedzą ptaki powietrzne, ponieważ Pan wyrzekł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'A ty wstawszy idź do domu twego a gdy wchodzić będziesz do miasta, tedy umrze dziecię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'I będzie go płakał wszystek Izrael, i pochowają go; bo ten sam z domu Jeroboamowego wnijdzie do grobu, przeto iż się znalazło o nim samym słowo dobre od Pana, Boga Izraelskiego w domu Jeroboamowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Wszakże postanowi sobie Pan króla nad Izraelem, który wykorzeni dom Jeroboamowy dnia tego; a co mówię, wzbudzi? I owszem już wzbudził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'I uderzy Pan Izraela, i zachwieje nim, jako się chwieje trzcina na wodach, a wykorzeni Izraela z ziemi tej dobrej, którą dał ojcom ich, i rozproszy je za rzekę, przeto iż sobie poczynili gaje, wzruszając Pana ku gniewu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'A tak wyda Izraela dla grzechu Jeroboamowego, który grzeszył, i który do grzechu przywiódł Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Tedy wstała żona Jeroboamowa, i poszła, a przyszła do Tersa; a gdy wstępowała na próg domu, umarło dziecię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'I pochowali je, a płakał go wszystek Izrael według słowa Pańskiego, które opowiedział przez sługę swego Achyjasza proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'A inne sprawy Jeroboamowe, jako walczył, i jako królował, oto spisane są w kronikach o królach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'A dni, których królował Jeroboam, było dwadzieścia i dwa lat, i zasnął z ojcy swymi, a Nadab, syn jego, królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Roboam też, syn Salomona, królował w Judzie. A było Roboamowi czterdzieści lat i jeden, gdy począł królować, a siedmnaście lat królował w mieście Jeruzalemie, które Pan obrał ze wszystkich pokoleń Izraelskich, aby tam przebywało imię jego. A imię matki jego było Naama, Ammonitka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'I czynił Juda złe przed Panem, a wzruszyli go ku gniewu grzechami swemi, któremi grzeszyli nad wszystko, co czynili ojcowie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Albowiem i oni pobudowali sobie wyżyny, i słupy, i gaje na każdym pagórku wysokim, i pod każdem drzewem zielonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Byli też i Sodomczycy w onej ziemi, sprawujący się według wszystkich obrzydliwości poganów, które wyrzucił Pan od obliczności synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'I stało się roku piątego królowania Roboama, że wyciągnął Sesak, król Egipski, przeciw Jeruzalemowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'I pobrał skarby domu Pańskiego, i skarby domu królewskiego, wszystko to pobrał; wziął też wszystkie tarcze złote, które był sprawił Salomon;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Miasto których król Roboam sprawił tarcze miedziane, i poruczył je przełożonym nad piechotą, którzy strzegli drzwi domu królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'A gdy wchodził król do domu Pańskiego, brała je piechota, i zasię odnosiła do komor swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'A inne sprawy Roboamowe, i wszystko co czynił, azaż nie są napisane w kronikach o królach Judzkich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'I była wojna między Roboamem i między Jeroboamem po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'I zasnął Roboam z ojcy swymi, a pochowany jest z nimi w mieście Dawidowem; a imię matki jego było Naama, Ammonitka. I królował Abijam, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'Roku tedy ośmnastego królowania Jeroboama, syna Nabatowego, królował Abijam nad Judą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Trzy lata królował w Jeruzalemie; a imię matki jego było Maacha, córka Abisalomowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'Ten chodził we wszystkich grzechach ojca swego, które czynił przed nim; a nie było serce jego doskonałe przy Panu, Bogu swoim, jako serce Dawida, ojca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Wszakże dla Dawida dał mu Pan, Bóg jego, pochodnią w Jeruzalemie, wzbudziwszy syna jego po nim, a utwierdziwszy Jeruzalem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'Przeto, że czynił Dawid, co było dobrego w oczach Pańskich, a nie uchylał się od wszystkiego, co mu rozkazał, po wszystkie dni żywota swego, oprócz sprawy z Uryjaszem Hetejczykiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'I była wojna między Roboamem, i między Jeroboamem po wszystkie dni żywota jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'A insze sprawy Abijamowe, i wszystko, co czynił, azaż nie jest napisane w kronikach o królach Judzkich, jako i wojna między Abijamem i między Jeroboamem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'A gdy zasnął Abijam z ojcy swymi, pochowano go w mieście Dawidowem. I królował Aza, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'A tak roku dwudziestego Jeroboama, króla Izraelskiego, królował Aza nad Judą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'Czterdzieści lat i jeden królował w Jeruzalemie, a imię matki jego było Maacha, córka Abisalomowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'I czynił Aza, co dobrego było w oczach Pańskich, jako Dawid ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Albowiem wytracił Sodomczyki z ziemi, i wyrzucił wszystkie bałwany, których byli naczynili ojcowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Nadto i Maachę, matkę swoję, zrzucił z panowania, bo była sprawiła strasznego bałwana w gaju; przetoż porąbał Aza tego strasznego bałwana jej, i spalił u potoku Cedron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'A chociaż wyżyny nie były skażone, jednak serce Azy było doskonałe przy Panu po wszystkie dni jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'I wniósł rzeczy poświęcone ojca swego, i rzeczy, które sam poświęcił, do domu Pańskiego, srebro, i złoto, i naczynia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'I była wojna między Azą i między Baazą, królem Izraelskim, po wszystkie dni ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'Albowiem Baaza, król Izraelski, wyciągnął przeciw Judzie, a zbudował Ramę, aby nie dopuścił wychodzić i wchodzić nikomu do Azy, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Ale wziąwszy Aza wszystko srebro i złoto, które było pozostało w skarbiech domu Pańskiego, i w skarbiech domu królewskiego, dał je w ręce sługom swoim; i posłał je król Aza do Benadada, syna Tabremonowego, syna Hezyjonowego, króla Syryjskiego, który mieszkał w Damaszku, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Przymierze jest między mną i między tobą, między ojcem moim i między ojcem twoim; otoć posyłam dary, srebro i złoto; idźże, wzrusz przymierze twoje z Baazą, królem Izraelskim, aby odciągnął odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'I usłuchał Benadad króla Azy; a posławszy hetmany z wojski, które miał przeciw miastom Izraelskim, zburzył Hijon i Dan i Abelbetmaachę, i wszystko Cynnerot, i wszystkę ziemię Neftalim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'Co gdy usłyszał Baaza, przestał budować Ramy, i mieszkał w Tersie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Tedy król Aza zebrał wszystek lud Judzki, nikogo nie wyjmując; a pobrali kamienie z Ramy i drzewo jego, z którego budował Baaza: a zbudował z niego król Aza Gabaa Benjaminowe, i Masfa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'A inne wszystkie sprawy Azy, i wszystka moc jego, i cokolwiek czynił, i miasta, które zbudował, azaż to nie jest napisane w kronikach o królach Judzkich? Ale czasu starości swej chorował na nogi swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'I zasnął Aza z ojcy swymi, a pochowany jest z nimi w mieście Dawida, ojca swego. A Jozafat, syn jego, królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Ale Nadab, syn Jeroboama, nastąpił na królestwo Izraelskie roku wtórego Azy, króla Judzkiego, i królował nad Izraelem dwa lata;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'I czynił złe przed oczyma Pańskiemi, chodząc drogami ojca swego, i w grzechach jego, któremi do grzechu przywodził Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'I zbuntował się przeciw niemu Baaza, syn Ahyjasza, z domu Isaschar; a poraził go Baaza u Giebbeton, które było Filistyńskie; bo Nadab ze wszystkim Izraelem obległ był Giebbeton.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'I zabił go Baaza roku trzeciego Azy, króla Judzkiego, a sam królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'I stało się, gdy począł królować, że wymordował wszystek dom Jeroboamowy; a nie zostawił żadnej duszy z narodu Jeroboamowego, aż je wytracił według słowa Pańskiego, które był opowiedział przez sługę swego Achyjasza Sylonitczyka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'A to dla grzechów Jeroboamowych, który grzeszył, i który do grzechu przywiódł Izraelczyki, i dla przestępstwa, którem wzruszył ku gniewu Pana, Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'A inne sprawy Nadabowe, i wszystko co czynił, azaż to nie jest napisane w kronikach królów Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'I była wojna między Azą, i między Baazą, królem Izraelskim, po wszystkie dni ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'Roku trzeciego Azy, króla Judzkiego, królował Baaza, syn Achyjasza, nad wszystkim Izraelem w Tersie przez dwadzieścia i cztery lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'I czynił złe przed Panem, chodząc drogami Jeroboamowemi, i w grzechu jego, którym do grzechu przywiódł Izraelity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'I stało się słowo Pańskie do Jehu, syna Hananijego, przeciw Baazie, mówiące:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Dla tego żem cię wydźwignął z prochu, a postanowiłem cię wodzem nad ludem moim Izraelskim, a tyś chodził drogami Jeroboamowemi, i przywiodłeś do grzechu lud mój Izraelski, pobudzając mię ku gniewu grzechami ich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'Otoż ja wygładzę potomki Baazy, i potomki domu jego, a uczynię dom twój, jako dom Jeroboama, syna Nabatowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Tego, który z rodu Baazy umrze w mieście, zjedzą psy, a tego, który umrze na polu, zjedzą ptaki powietrzne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'A inne sprawy Baazy, i co czynił, i moc jego, azaż to nie jest napisano w kronikach królów Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'A gdy zasnął Baaza z ojcy swymi, pochowany jest w Tersie, i królował Ela, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'A tak przez proroka Jehu, syna Hananijego, stało się słowo Pańskie przeciw Baazie i przeciw domowi jego, i przeciw wszystkiemu złemu, które czynił przed obliczem Pańskiem, wzruszając go ku gniewu sprawami rąk swoich, że ma być podobnym domowi Jeroboamowemu, i dla tego, że go zabił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'Roku dwudziestego i szóstego Azy, króla Judzkiego, królował Ela, syn Baazy, nad Izraelem w Tersie dwa lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'I sprzysiągł się przeciw niemu sługa jego Zymry, hetman nad połową wozów, gdy Ela w Tersie pijąc pijany był w domu Arsy, który był sprawcą domu królewskiego w Tersie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'Wtem przypadł Zymry i ranił go, i zabił go roku dwudziestego i siódmego Azy, króla Judzkiego, a królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'A gdy już królował i siedział na stolicy jego, wymordował wszystek dom Baazy, i powinne jego, i przyjacioły jego; nie zostawił z niego i szczeniątka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'A tak wygładził Zymry wszystek dom Baazy według słowa Pańskiego, które powiedział o Baazie przez proroka Jehu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'Dla wszystkich grzechów Baazy, i grzechów Eli, syna jego, którzy grzeszyli, i którzy przywiedli do grzechu Izraela, wzruszając ku gniewu Pana, Boga Izraelskiego, próżnościami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Ale inne sprawy Eli, i wszystko co czynił, izali nie napisane w kronikach o królach Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'Roku dwudziestego i siódmego Azy, króla Judzkiego, królował Zymry siedm dni w Tersie, gdy lud obozem leżał u Giebbeton, które jest Filistyńskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'A gdy usłyszał lud leżący w obozie takową rzecz, iż Zymry sprzysiągłszy się zabił króla: tedy wszystek Izrael postanowili królem Amrego, który był hetmanem na wojskiem Izraelskiem onegoż dnia w obozie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'Przetoż odciągnął Amry i wszystek Izrael z nim od Giebbeton, a oblegli Tersę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'A gdy obaczył Zymry, iż wzięto miasto, wszedł na pałac domu królewskiego, i spalił się ogniem z domem królewskim, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'A to się stało dla grzechów jego, których się dopuścił, czyniąc złe przed obliczem Pańskiem, a chodząc drogą Jeroboama, i w grzechach jego, których się dopuszczał, do grzechu przywodząc Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'A inne sprawy Zymry i sprzysiężenie jego, które uczynił, azaż nie jest napisane w kronikach o królach Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Tedy się rozerwał lud Izraelski na dwie części; połowa ludu szła za Tebni, synem Ginetowym, aby go uczynili królem, a połowa szła za Amrym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Ale przemógł lud, który przestawał z Amrym, on lud, który zostawał przy Tebni, synem Ginetowym; i umarł Tebni, a królował Amry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'Roku trzydziestego i pierwszego Azy, króla Judzkiego, królował Amry nad Izraelem dwanaście lat; w Tersie królował sześć lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'I kupił górę Samaryi od Semera za dwa talenty srebra, i pobudował na onej górze, a nazwał imię miasta, które zbudował imieniem Semera, pana góry onej, Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'Ale czynił Amry złe przed oczyma Pańskiemi, a dopuszczał się rzeczy gorszych, niżeli wszyscy, którzy przed nim byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Albowiem chodził wszystkiemi drogami Jeroboama, syna Nabatowego, i w grzechu jego, którym przywiódł w grzechy Izraela, wzruszając ku gniewu Pana Boga Izraelskiego, próżnościami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'A inne sprawy Amrego, i wszystko, co czynił, i moc jego, którą pokazywał, azaż to nie jest napisane w kronikach o królach Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'I zasnął Amry z ojcy swymi, a pochowany jest w Samaryi; i królował Achab, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'Achab tedy, syn Amrego, królować począł nad Izraelem roku trzydziestego i ósmego Azy, króla Judzkiego, a królował Achab, syn Amrego, nad Izraelem w Samaryi dwadzieścia i dwa lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'I czynił Achab, syn Amrego, złe przed oczyma Pańskiemi nad wszystkie, którzy byli przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'I stało się, nie mając na tem dosyć, iż chodził w grzechach Jeroboama, syna Nabatowego, że sobie wziął za żonę Jezabelę, córkę Etbaala, króla Sydońskiego, a szedłszy służył Baalowi, i kłaniał mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'I wystawił ołtarz Baalowi w domu Baalowym, który był zbudował w Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Do tego nasadził Achab gaj, a tem więcej wzruszył ku gniewu Pana, Boga Izraelskiego, nad wszystkie króle Izraelskie, którzy byli przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'Za dni jego zbudował Hijel, Betelczyk, miasto Jerycho. Na Abiramie, pierworodnym swoim, założył je, a na Segubie najmłodszym synu swym, wystawił bramy jego, według słowa Pańskiego, które powiedział przez Jozuego, syna Nunowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'Tedy rzekł Elijasz Tesbita, jeden z obywateli Galaadu, do Achaba: Jako żywy Pan, Bóg Izraelski, przed którego oblicznością stoję, że nie będzie tych lat rosy, ani deszczu, jedno według słów ust moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'I stało się słowo Pańskie do niego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Odejdź stąd, a obróć się na wschód słońca, i skryj się u potoku Charyt, który jest przeciwko Jordanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'I będziesz pił z potoku: a rozkazałem krukom, aby cię tam żywili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'I poszedł, a uczynił według słowa Pańskiego, i przyszedłszy usiadł u potoku Charyt, który był przeciwko Jordanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'A kruki przynosiły mu chleb i mięso rano, także chleb i mięso w wieczór; a pił z potoku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'Lecz po wyjściu niektórych dni wysechł on potok; bo nie padał deszcz na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'I stało się słowo Pańskie do niego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Wstań, idź do Sarepty Sydońskiej, i mieszkaj tam; otom tam rozkazał niewieście wdowie, aby cię żywiła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Tedy on wstawszy szedł do Sarepty, i przyszedł do bramy miasta, a oto tam niewiasta wdowa zbierała drwa; który zawoławszy jej, rzekł: Przynieś mi proszę trochę wody w naczyniu, abym się napił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'A gdy ona szła, aby przyniosła, tedy na nię zawołał, i rzekł: Przynieś mi też proszę sztuczkę chleba w ręce twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'I odpowiedziała: Jako żywy Pan, Bóg twój, żeć niemam pieczonego chleba, oprócz z garść pełną mąki w garncu, a trochę oliwy w bańce; a oto zbieram trochę drewek, abym szła, i zgotowała to sobie i synowi swemu, a zjadłszy to, abyśmy pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'Tedy rzekł do niej Elijasz: Nie bój się. Idź, uczyń jakoś rzekła: wszakże uczyń mi z tego pierwej podpłomyk mały, i przynieś mi; potem też sobie i synowi swemu uczynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Albowiem tak powiedział Pan, Bóg Izraelski: Mąka z garnca tego nie będzie strawiona, ani oliwy z tej bańki ubędzie, aż do dnia, gdy Pan spuści deszcz na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'I poszła, a uczyniła podług słowa Elijaszowego, i jadła ona i on, i wszystka czeladź jej, aż się wypełniły te dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Nie była strawiona mąka z onego garnca, ani oliwy z bańki ubyło, według słowa Pańskiego, które powiedział przez Elijasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'I stało się potem, że się rozniemógł syn onej niewiasty, pani domu onego, a była niemoc jego bardzo ciężka, tak, że w nim tchu nie zostało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'Przetoż rzekła do Elijasza: Cóż mnie i tobie, mężu Boży? przyszedłeś do mnie, abyś przywiódłszy na pamięć nieprawość moję, umorzył syna mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'I rzekł do niej: Daj mi syna twego; i wziąwszy go z łona jej, wniósł go na salę, na której mieszkał, i położył go na łożu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'I wołał do Pana, a rzekł: Panie, Boże mój, izali też utrapisz wdowę, u której mieszkam, iżeś zabił syna jej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'A rozciągnąwszy się nad dziecięciem po trzy kroć, wołał do Pana, mówiąc: Panie, Boże mój, niechaj się proszę wróci dusza dzieciątka tego w ciało jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'I wysłuchał Pan głos Elijaszowy: i wróciła się dusza dziecięcia w ciało jego, i ożyło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'Tedy wziął Elijasz dziecię, i zniósł je z sali do domu, a oddał go matce jego, i rzekł Elijasz: Wej, syn twój żyje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'I rzekła niewiasta do Elijasza: Terazem poznała, iżeś jest mąż Boży, a słowo Pańskie w uściech twoich jest prawda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'Potem po wielu dniach, mianowicie po onym roku trzecim, stało się słowo Pańskie do Elijasza, mówiąc: Idź, ukaż się Achabowi; bo spuszczę deszcz na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Szedł tedy Elijasz, aby się ukazał Achabowi; a był głód gwałtowny w Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'I zawołał Achab Abdyjasza, który był sprawcą domu jego. (A Abdyjasz się bardzo Pana bał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'Bo gdy mordowała Jezabel proroki Pańskie, tedy wziął Abdyjasz sto proroków, i skrył ich po pięćdziesiąt do jaskini, i żywił je chlebem i wodą.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'I rzekł Achab do Abdyjasza: Idź przez ziemię do wszystkich źródeł wód, i do wszystkich potoków, aza gdzie znajdziemy trawę, żebyśmy żywo zachowali konie i muły, i żebyśmy nie zgubili bydła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'I rozdzielili sobie ziemię, którą przejść mieli. Achab sam szedł jedną drogą, Abdyjasz też szedł drugą drogą osobno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'A gdy Abdyjasz był w drodze, oto się z nim Elijasz spotkał, który gdy go poznał, upadł na oblicze swoje, i rzekł: A tyżeś jest pan mój Elijasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'I odpowiedział mu: Jam jest. Idź, powiedz panu twemu: Oto Elijasz tu jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'Do którego on rzekł: Cóżem zgrzeszył, iż wydawasz sługę twego w ręce Achabowe, aby mię zabił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Jako żywy Pan, Bóg twój, że niemasz narodu, i królestwa, gdzieby nie posłał Pan mój, aby cię szukano; a gdy powiedziano, iż cię niemasz, tedy obowiązał przysięgą królestwa i narody, jako cię znaleść nie mogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'A ty mi teraz mówisz: Idź, a powiedz panu twemu: Oto Elijasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'I stałoby się, gdybym ja odszedł od ciebie, żeby cię Duch Pański zaniósł, gdziebym nie wiedział; a ja szedłszy opowiedziałbym Achabowi, a gdyby cię nie znalazł, zabiłby mię; a sługa twój boi się Pana od dzieciństwa swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Azaż nie powiedziano panu memu, com uczynił, gdy mordowała Jezabel proroki Pańskie? żem skrył z proroków Pańskich sto mężów, po pięćdziesiąt mężów w jaskini, i żywiłem je chlebem i wodą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'A ty teraz mówisz: Idź, powiedz panu twemu: Oto Elijasz; i zabije mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'I odpowiedział Elijasz: Jako żywy Pan zastępów, przed którego oblicznością stoję, że mu się dziś ukażę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'A tak szedł Abdyjasz przeciw Achabowi, i oznajmił mu to. Przetoż szedł Achab przeciw Elijaszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'A ujrzawszy Achab Elijasza, rzekł Achab do niego: Azaż nie ty jesteś, który czynisz zamięszanie w Izraelu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'Na co mu odpowiedział: Nie jać czynię zamięszanie w Izraelu, ale ty i dom ojca twego, gdyż opuściwszy rozkazania Pańskie naśladujecie Baalów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Przetoż teraz poślij, a zbierz do mnie wszystkiego Izraela na górę Karmel, i proroków Baalowych cztery sta i pięćdziesiąt, przytem proroków gajowych cztery sta, którzy jadają z stołu Jezabeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Posłał tedy Achab do wszystkich synów Izraelskich, i zebrał te proroki na górę Karmel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'A przystąpiwszy Elijasz do wszystkiego ludu, rzekł: I długoż będziecie chramać na obie strony? Jeźli Pan jest Bogiem, idźcież za nim; a jeźli Baal, idźcież za nim. I nie odpowiedział mu lud i słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Tedy rzekł Elijasz do ludu: Jam tylko sam został prorok Pański; a proroków Baalowych cztery sta i pięćdziesiąt mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Niech nam dadzą dwóch cielców, a niech sobie obiorą cielca jednego, a porąbią go na sztuki, i włożą na drwa; ale ognia niech nie podkładają: ja też przygotuję drugiego cielca, którego włożę na drwa, a ognia nie podłożę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'Potem wzywajcie imienia bogów waszych, a ja będę wzywał imienia Pańskiego, a Bóg, który się ozwie przez ogień, ten niech będzie Bogiem. Na co odpowiadając wszystek lud rzekł: Dobrześ powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'I rzekł Elijasz do proroków Baalowych: Obierzcie sobie cielca jednego, a zgotujcie go pierwej, bo was jest więcej; wzywajcież imienia bogów waszych, ale ognia nie podkładajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'A tak wzięli cielca, którego im dał, a zgotowawszy wzywali imienia Baalowego od poranku aż do południa, mówiąc: O Baalu, wysłuchaj nas! Ale nie było głosu, ani ktoby odpowiedział. I skakali koło ołtarza, który byli uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'A gdy było południe, naśmiewał się z nich Elijasz, mówiąc: Wołajcie większym głosem, ponieważ jest bóg; tylko że się albo zamyślił, albo jest zabawny, albo też jest w drodze; albo też śpi, aza ocuci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'A tak wołali głosem wielkim, i rzezali się według zwyczaju swego nożami i włóczenkami, aż się krwią oblewali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'I stało się, gdy minęło południe, że prorokowali aż do czasu ofiarowania ofiary śniednej; ale nie było głosu, ani ktoby odpowiedział, ani ktoby wysłuchał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Zatem rzekł Elijasz do wszystkiego ludu: Przystąpcie do mnie. I przystąpił wszystek lud do niego. Tedy naprawił ołtarz Pański, który był rozwalony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'Albowiem wziął Elijasz dwanaście kamieni; (według liczby pokolenia synów Jakóbowych, do którego się stało słowo Pańskie, mówiąc: Izrael będzie imię twoje.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'I zbudował z tego kamienia ołtarz w imię Pańskie, a uczynił około ołtarza szeroki rów, coby mógł dwie miary zboża wysiać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'Potem ułożył drwa, i na sztuki porąbał cielca, i kładł go na drwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'I rzekł: Napełnijcie cztery wiadra wodą, a wylijcie na całopalenie i na drwa. Rzekł nadto: Powtórzcie, i powtórzyli; rzekł jeszcze: Uczyńcie po trzecie, i uczynili po trzecie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'Tak że płynęły wody około ołtarza, aż i rów był napełniony wodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'I stało się, gdy był czas sprawowania ofiary śniednej, przystąpił Elijasz prorok, i rzekł: Panie, Boże Abrahama, Izaaka, i Izraela! dziś niech poznają, żeś ty jest Bogiem w Izraelu, a jam sługa twój, a żem według słowa twego uczynił to wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Wysłuchaj mię Panie, wysłuchaj mię, aby poznał ten lud, żeś ty Panie jest Bogiem, gdybyś zaś nawrócił serca ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Tedy spadł ogień Pański, i pożarł całopalenie, i drwa, i kamienie, i proch; a wodę, która była w rowie, wysuszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'Co gdy ujrzał wszystek lud, upadli na oblicze swe, i rzekli: Pan jest Bogiem, Panci jest Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Tedy rzekł Elijasz do nich: Pojmajcie proroki Baalowe, a żaden niech z nich nie uchodzi. I pojmano je. A tak odwiódł je Elijasz do potoku Cyson, i tamże je pobił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'Potem rzekł Elijasz do Achaba: Idź, jedz, a pij; albowiem oto szum dżdżu wielkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Tedy szedł Achab, aby jadł i pił; a Elijasz wstąpił na wierzch Karmelu, i położył się na ziemię, a włożył twarz swoję między kolana swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'Potem rzekł do sługi swego: Idź teraz, a spojrzyj ku morzu. Który poszedł, a spojrzawszy rzekł: Niemasz nic. Zasię rzekł: Idź, a wracaj się po siedm kroć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'A za siódmym razem rzekł: Oto obłok mały jako dłoń człowiecza występuje z morza. Tedy on rzekł: Idź, a powiedz Achabowi: Zaprzęgaj, a ujeżdżaj, aby cię deszcz nie zastał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'I stało się między tem, że się niebiosa obłokami i wiatrem zaćmiły, skąd był deszcz wielki. A tak wsiadłszy Achab, jechał do Jezreela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'A ręka Pańska była nad Elijaszem; i przepasał biodra swe, i bieżał przed Achabem, aż przyszedł do Jezreela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'Tedy oznajmił Achab Jezabeli wszystko, co uczynił Elijasz, a iż prawie wszystkie proroki pomordował mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'Przetoż posłała Jezabela posła do Elijasza, mówiąc: To mi niech uczynią bogowie, i to mi niech przyczynią, jeźli o tym czasie jutro nie położę duszy twojej, jako duszy którego z onych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'Co gdy wyrozumiał Elijasz, wstał i odszedł, aby duszę swą zachował, a przyszedł do Beerseby, która była w Judztwie, i zostawił tam sługę swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'A sam poszedł w puszczę na jeden dzień drogi: a gdy przyszedł, i usiadł pod jednym jałowcem, życzył sobie umrzeć, i rzekł: Dosyć już, o Panie; weźmijże duszę moję, bom nie jest lepszym nad ojców moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'I położył się, a zasnął pod onym jałowcem, a oto w tenże czas tknął go Anioł i rzekł mu: Wstań, a jedz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'A gdy się obejrzał, oto w głowach jego był chleb na węglu upieczony i czasza wody. A tak jadł i pił, i położył się znowu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'Potem wrócił się Anioł Pański powtóre, i tknął go, a rzekł: Wstań, jedz, albowiem daleką masz drogę przed sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'A tak wstawszy jadł i pił, a szedł w mocy pokarmu onego czterdzieści dni i czterdzieści nocy, aż do góry Bożej Horeb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'I wszedł tam do jaskini, a przenocował tam. A oto słowo Pańskie do niego, mówiąc: Cóż tu czynisz Elijaszu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Który odpowiedział; Gorliwiem się zastawiał o Pana, Boga zastępów; albowiem synowie Izraelscy opuścili przymierze twoje, ołtarze twoje zburzyli, i proroki twoje mieczem pomordowali, a zostałem ja sam, i szukają duszy mojej, aby mi ją odjęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'Tedy onże głos rzekł: Wynijdź, a stań na górze przed Panem. A oto Pan przechodził, i wiatr gwałtowny i mocny podwracający góry, i łamiący skały przed Panem; ale Pan nie był w onym wietrze. Za wiatrem było trzęsiemie ziemi; ale nie był Pan i w onem trzęsieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'Za trzęsieniem był ogień; ale Pan nie był w ogniu; za ogniem był głos cichy i wolny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'To gdy usłyszał Elijasz, zakrył oblicze swoje płaszczem swoim, a wyszedłszy stanął we drzwiach jaskini. A oto do niego głos mówiący: Co tu czynisz Elijaszu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'A on odpowiedział: Gorliwiem się zastawiał o Pana, Boga zastępów: albowiem opuścili przymierze twoje synowie Izraelscy, ołtarze twoje poburzyli, a proroki twoje mieczem pomordowali, i zostałem ja sam, a szukają duszy mojej, aby mi ją odjęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'Ale Pan rzekł do niego: idź, wróć się drogą twą na puszczę Damaską, a gdy tam przyjdziesz, pomażesz Hazaela za króla nad Syryją;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'A Jehu, syna Namsy, pomażesz za króla nad Izraelem, a Elizeusza, syna Safatowego, z Abelmechola, pomażesz za proroka miasto siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'I stanie się, że ktokolwiek ujdzie miecza Hazaelowego, zabije go Jehu, a ktokolwiek ujdzie miecza Jehu, zabije go Elizeusz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Jednakiem sobie zachował w Izraelu siedm tysięcy, których wszystkich kolana nie kłaniały się Baalowi, i których wszystkich usta nie całowały go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'A tak on odszedłszy stamtąd, znalazł Elizeusza, syna Safatowego, a on orze, a dwanaście jarzm wołów przed nim, a sam był przy dwunastem jarzmie, a idąc mimo niego Elijasz, wrzucił nań płaszcz swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'Który opuściwszy woły bierzał za Elijaszem, i rzekł: Niech pocałuję proszę ojca mego, i matkę moję, a pójdę za tobą; któremu rzekł: Idź, a wróć się zasię, ponieważ widzisz, com ci uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'A tak wróciwszy się do niego wziął parę wołów, i zabił je, a przy drwach z pługa nawarzył mięsa z nich, i dał ludowi, i jedli. A wstawszy szedł za Elijaszem, i służył mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Tedy Benadad, król Syryjski, zebrał wszystko wojsko swoje, mając z sobą trzydzieści i dwóch królów, przytem jezdne i wozy; a przyciągnąwszy obległ Samaryję i dobywał jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'I wyprawił posły do Achaba, króla Izraelskiego, do onego miasta;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'I rzekł mu: Tak mówi Benadad: Srebro twoje i złoto twoje mojeć jest; także żony twoje i synowie twoi najcudniejsi moi są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'I odpowiedział król Izraelski a rzekł: Według słowa twego królu, panie mój, twojem ja, i wszystko, co mam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'A wróciwszy się posłowie do niego, rzekli: Tak powiedział Benadad, mówiąc: Posłałem do ciebie, abyć rzeczono: Srebro twoje, i złoto twoje, i żony twoje, i syny twoje dasz mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'Ale wiedz, że jutro o tym czasie poślę sługi moje do ciebie, którzy wyszperają dom twój, i domy sług twoich, i wszystko, w czem się kochasz, w ręce swe wezmą, i rozbiorą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'A tak wezwał król Izraelski wszystkich starszych ziemi onej, i rzekł im: Uważcież proszę, a obaczcie, żeć ten złego szuka; albowiem posłał do mnie po żony moje, i po syny moje, i po srebro moje, i po złoto moje, a nie odmówiłem mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'I rzekli do niego oni wszyscy starsi, i wszystek lud: Nie słuchaj ani przyzwalaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Przetoż odpowiedział posłom Benadadowym: Powiedzcie królowi, panu memu: wszystko, o coś posłał do sługi twego przedtem, uczynię: ale tej rzeczy uczynić nie mogę. A tak posłowie odeszli, i odnieśli mu odpowiedź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Znowu posłał do niego Benadad i rzekł: Niech mi to uczynią bogowie, i to niech przyczynią, jeźli się dostanie prochu Samaryi po garści wszystkiemu ludowi, który za mną idzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'I odpowiedział król Izraelski, a rzekł: Powiedzcie mu: Niech się nie chlubi zbrojny, jako ten, który złożył zbroję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'A gdy Benadad usłyszał to słowo, (a on w tenczas z królmi pił w namiotach,) rzekł do sług swych: Ruszcie się. I ruszyli się ku miastu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'A oto, niektóry prorok przyszedł do Achaba, króla Izraelskiego, i rzekł: Tak powiada Pan: Izażeś nie wiedział tego wszystkiego wielkiego mnóstwa? Oto Ja je dam w rękę twoję dzisiaj, abyś wiedział, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'Tedy rzekł Achab: Przez kogoż? A on odpowiedział: Tak mówi Pan: przez sługi książąt powiatowych. I rzekł: Którz pocznie bitwę? Tedy mu on odpowiedział: Ty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Obliczył tedy sługi książąt powiatowych, których było dwieście trzydzieści i dwa; a po nich policzył wszystek lud, wszystkich synów Izraelskich siedm tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'I wyszli o południu. A Benadad pił, i upił się w namiotach, sam i trzydzieści i dwóch królów, pomocników jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'A tak wyszli słudzy książąt powiatowych naprzód. Tedy posłał Benadad, (gdy mu powiedziano, mówiąc: Mężowie wyszli z Samaryi,)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'I rzekł: Chociażby o pokój szli prosić, pojmajcie je żywo; chociażby też ku bitwie wyszli, żywo je pojmajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'A gdy oni słudzy książąt powiatowych wyszli z miasta, i inne wojsko za nimi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'Poraził każdy męża swego, tak, że uciekli Syryjczycy, i gonił je Izrael; uciekł też Benadad, król Syryjski, na koniu i z jezdnymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'Potem wyciągnął król Izraelski, i pobił konie i wozy, a poraził Syryjczyka porażką wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Znowu przyszedł prorok do króla Izraelskiego, i rzekł mu: Idź, zmacniaj się, a wiedz i bacz, co masz czynić; albowiem po roku król Syryjski wyciągnie przeciwko tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'Tedy słudzy króla Syryjskiego rzekli do niego: Bogowie ich są bogowie górni, przetoż nas przemogli; a wszakże zwiedźmy z nimi bitwę w polu a ujrzysz, jeźli ich nie przemożemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Przetoż tak uczyń: Odpraw królów, każdego z miejsca swego, a postanów hetmanów miasto nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'A ty nalicz sobie wojska z swoich, jako było wojsko onych, którzy polegli, a koni jako one konie, a wozów, jako one wozy, i stoczymy bitwę z nimi w polu, a ujrzysz, jeźli ich nie przemożemy. I usłuchał głosu ich, a uczynił tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'A gdy wyszedł rok, obliczył Benadad Syryjczyki, a ciągnął ku Afeku na wojnę przeciw Izraelitom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'Synowie Izraelscy także są obliczeni, a nabrawszy z sobą żywności, ciągnęli przeciwko nim. I położyli się obozem synowie Izraelscy przeciwko nim, jakoby dwa małe stadka kóz; a Syryjczycy napełnili ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'Tedy przyszedł mąż Boży, i mówił do króla Izraelskiego, a rzekł: Tak mówi Pan: Przeto iż mówili Syryjczycy: Bogiem gór jest Pan, a nie jest Bogiem równim, podam to wszystko mnóstwo wielkie w ręce twoje, abyście wiedzeli, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'A tak oni leżeli obozem przeciwko nim przez siedm dni. I stało się dnia siódmego, że stoczyli bitwę, i porazili synowie Izraelscy Syryjczyków sto tysięcy pieszych jednegoż dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'A ostatek uciekli do Afeku miasta, i upadł mur na dwadzieścia i siedm tysięcy mężów, co byli pozostali. A Benadad uciekłszy przyszedł do miasta, i skrył się do najskrytszej komory.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'Ale mu rzekli słudzy jego: Słychaliśmy za pewne, że królowie domu Izraelskiego są królowie miłosierni. Niech włożymy proszę wory na biodra nasze, i powrozy na głowy nasze, a wynijdziemy do króla Izraelskiego, snać żywo zostwi duszę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Tedy opasali wormi biodra swe, a włożyli powrozy na głowy swoje i przyszli do króla Izraelskiego, i rzekli: Benadad, sługa twój, mówi: Niech żyje proszę dusza moja! A on rzekł: a żywże jeszcze? Brat to mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'A oni mężowie wziąwszy to za dobry znak, i prędko uchwyciwszy to słowo od niego, rzekli: Bratci twój Benadad. I rzekł: Idźcież, przywiedźcie go. Przetoż wyszedł do niego Benadad, i kazał mu wsiąść na wóz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'I rzekł do niego Benadad: miasta, które wziął ojciec mój ojcu twemu, powrócę, a ty ulice sobie poczynisz w Damaszku, jako poczynił ojciec mój w Samaryi. I odpowiedzał: Ja według przymierza puszczę cię wolno. A tak z nim uczynił przmierze i puścił go wolno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'Tedy niektóry mąż z synów prorockich rzekł do bliźniego swego z rozkazania Pańskiego: Uderz mię proszę; ale go nie chciał on mąż uderzyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'I rzekł mu: Przeto iżeś nie usłuchał głosu Pańskiego, oto skoro odejdziesz odemnie, zabije cię lew. A gdy odszedł od niego, znalazł go lew, i zabił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Potem znalazł drugiego męża, i rzekł mu: Uderz mię proszę; który mąż tak go uderzył, że go ranił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Szedł tedy on prorok, a zabieżał królowi na drodze, i odmienił się, zasłoniwszy oczy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'A gdy król mijał, zawołał na króla, i rzekł; sługa twój wyszedł w pośrodek bitwy, a oto mąż przyszedłszy przywiódł do mnie męża, i rzekł: Strzeż tego męża; bo jeźlibyś go opuścił, dusza twoja będzie za duszę jego, albo talent srebra odważysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Wtem gdy się sługa twój zabawił tem i owem, oto on zniknął. Tedy rzekł do niego król Izraelski: Taki jest sąd twój, sameś się osądził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'A on zaraz odjął zasłonę od oczu swych, i poznał go król Izraelski, że był prorokiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'Zatem rzekł do niego: Tak mówi Pan: Ponieważeś wypuścił z ręki swej męża godnego śmierci, dusza twoja będzie za duszę jego, i lud twój za lud jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'Przetoż odszedł król Izraelski do domu swego smutny i zagniewany, i przyszedł do Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'I stało się potem: Miał Nabot Jezreelita winnicę, która była w Jezreelu podle pałacu Achaba, króla w Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'I rzekł Achab do Nabota, mówiąc: Daj mi winnicę twoję, abym miał z niej ogród dla jarzyn, albowiem bliska jest domu mego; a dam ci za nię winnicę lepszą, niżli ta jest; albo jeźlić się zda, dam ci pieniędzy, ile stoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'I odpowiedzał Nabot Achabowi: Nie daj tego Panie, abym ci miał dać dziedzictwo ojców moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'Tedy przyszedł Achab do domu swego smutny i zagniewany dla słowa, które mu rzekł Nabot Jezreelita, mówiąc: Nie dam ci dziedzictwa ojców moich; i układł się na łożu swem, a odwrócił twarz swoję, i nie jadł chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Wtem przyszedłszy do niego Jezabela, żona jego, rzekła mu: Przedże duch twój tak smutny, że nie jesz chleba?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'I odpowiedział jej: Przeto żem mówił z Nabotem Jezreelitą, i rzekłem mu: Daj mi winnicę twoję za pieniądze, albo jeźli chcesz, dam ci winnicę za nię; ale on odpowiedział: Nie dam ci winnicy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'Tedy rzekła do niego Jezabela, żona jego: I także ty sprawujesz królestwo Izraelskie? Wstań, jedz chleb, a bądź dobrej myśli; ja tobie dam winnicę Nabota Jezeelity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'A tak napisała list imieniem Achabowem, który zapieczętowała pieczęcią jego, i posłała on list do starszych i do przedniejszych, którzy byli w mieście jego, i mieszkali z Nabotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'A napisała on list w ten sposób: Zapowiedźcie post, a posadźcie Nabota między przedniejszymi z ludu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'I postawcie dwóch mężów przewrotnych przeciw niemu, którzyby przeciwko niemu świadczyli, mówiąc: Złożeczyłeś Bogu i królowi; potem wywiedźcie go, a ukamionujcie go, aby umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'I uczynili mężowie onego miasta starsi i przedniejsi, którzy mieszkali w onem mieście jego, jako była wskazała do nich Jezabela, według tego, jako napisano było w liście, który posłała do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Zapowiedzieli post, i posadzili Nabota między przedniejszymi z ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'Potem przyszli dwaj mężowie przewrotni, i usiedli przeciw niemu, a świadczyli przeciwko niemu oni mężowie przewrotni, to jest przeciw Nabotowi przed ludem, mówiąc: Złożeczył Nabot Bogu i królowi. I wywiedli go za miasto, i ukamionowali go, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'I posłali do Jezabeli, mówiąc: Ukamionowan jest Nabot, i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'I stało się, gdy usłyszała Jezabela, że ukamionowany był Nabot, a iż umarł, rzekła Jezabela do Achaba: Wstań, posiądź winnicę Nabota Jezreelity, któryć jej nie chciał dać za pieniądze; albowiem nie żyje Nabot, ale umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'A tak usłyszawszy Achab, że umarł Nabot, wstał, a szedł do winnicy Nabota Jezreelity, aby ją posiadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'Tedy się stało słowo Pańskie do Elijasza Tasbity, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Wstań, idź przeciw Achabowi, królowi Izraelskiemu, który jest w Samaryi; oto jest na winnicy Nabotowej, do której szedł, aby ją posiadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'I rzeczesz do niego, mówiąc: Tak mówi Pan: Azaś nie zabił i nie posiadł? Powiedzże mu, mówiąc: Tak mówi Pan: Tak jako psy lizali krew Nabotowę, tak też pewnie psy będą lizać krew twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'I rzekł Achab do Elijasza: A jużeś mię znalazł nieprzyjacielu mój? A on odpowiedział: Znalazłem; albowiemeś się zaprzedał, abyś czynił złość przed oczyma Pańskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Oto Ja przywiodę na cię złe, a odejmę potomki twe, i wytracę z domu Achabowego, aż do najmniejszego szczenięcia, i więźnia, i opuszczonego w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'A uczynię z domem twoim, jako z domem Jeroboama, syna Nabatowego, i jako z domem Baazy, syna Ahyjaszowego, dla rozdraźnienia, któremeś mię do gniewu pobudził, i przywiodłeś do grzechu Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Także i o Jezabeli rzekł Pan, mówiąc: Psy zjedzą Jezabelę między murami Jezreelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Tego, który umrze z domu Achabowego w mieście, psy zjedzą, a tego, który umrze na polu, zjedzą ptaki powietrzne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, 'Albowiem nie był nikt jako Achab, któryby siebie samego zaprzedał, aby czynił złe przed oczyma Pańskiemi; bo go poduszczała Jezabela, żona jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'Albowiem się dopuścił rzeczy bardzo obrzydłych, chodząc za bałwanami według wszystkiego, jako czynili Amorejczycy, których wygnał Pan przed obliczem synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'A gdy usłyszał Achab te słowa, rozdarł odzienie swoje, a włożywszy wór na ciało swoje, pościł i leżał w worze, a chodził po maluczku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'I stało się słowo Pańskie do Elijasza Tesbity, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Widziałżeś, jako się upokorzył Achab przed twarzą moją? Ponieważ się tedy upokorzył przed twarzą moją, nie przywiodę tego złego za dni jego; ale za dni syna jego przywiodę to złe na dom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'A nie było przez trzy lata wojny między Syryjczykami i między Izraelczykami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'I stało się roku trzeciego, że przyjechał Jozafat król Judzki, do króla Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'Tedy rzekł król Izraelski do sług swoich: Nie wiecież, iż nasze jest Ramot Galaad? A my zaniedbywamy odebrać go z ręki króla Syryjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'Przetoż rzekł do Jozafata: Pociągnieszże ze mną na wojnę przeciwko Ramot Galaad? I rzekł Jozafat do króla Izraelskiego: Jakom ja, tak i ty; jako lud mój, tak lud twój; jako konie moje, tak konie twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Nadto rzekł Jozafat do króla Izraelskiego: Spytaj się proszę dziś słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'A tak zebrał król Izraelski proroków około czterech set mężów, i rzekł do nich: Mamże ciągnąć na wojnę przeciwko Ramot Galaad? czy zaniechać? I odpowiedzieli mu: Ciągnij; bo je Pan da w ręce królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Ale Jozafat rzekł: Nie maszże tu którego proroka Pańskiego, żebyśmy się go pytali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'I rzekł król Izraelski do Jozafata: Jest jeszcze mąż jeden, przez któregobyśmy się mogli radzić Pana; ale go ja nienawidzę, bo mi nic dobrego nie prorokuje, jedno złe, Micheasz, syn Jemla. I rzekł Jozafat: Niech tak nie mówi król.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'A tak zawołał król Izraelski komornika niektórego, i rzekł: Przywiedź tu rychło Micheasza, syna Jemlowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Między tem król Izraelski, i Jozafat, król Judzki, siedzieli na stolicach swoich, ubrani w szaty królewskie, na placu u wrót bramy Samaryjskiej, a wszyscy prorocy prorokowali przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'A Sedechyjasz, syn Chenaana, sprawił sobie rogi żelazne, i rzekł: Tak mówi Pan: Temi będziesz bódł Syryjczyki, aż je wyniszczysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Także wszyscy prorocy prorokowali, mówiąc: Ciągnij do Ramot Galaad, a będzieć się szczęściło; albowiem je poda Pan w ręce królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Tedy poseł, który chodził, aby przyzwał Micheasza, rzekł do niego, mówiąc: Oto teraz słowa proroków jednemi usty dobrze tuszą królowi; niechże będzie proszę słowo twoje, jako słowo jednego z nich, a mów dobre rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'I rzekł Micheasz: Jako żywy Pan, że co mi kolwiek rzecze Pan, to mówić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'A gdy przyszedł do króla, rzekł król do niego: Micheaszu, mamyż ciągnąć na wojnę przeciw Ramot Galaad, czyli zaniechać? A on mu rzekł: Ciągnij, a będzieć się szczęściło; albowiem je poda Pan w ręce królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'I rzekł do niego król: A wieleż cię razy mam przysięgą obowiązać, abyś mi nie mówił jedno prawdę w imieniu Pańskiem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'Przetoż rzekł: Widziałem wszystek lud Izraelski rozproszony po górach jako owce, które nie mają pasterza; bo rzekł Pan: Nie mają ci pana; niech się wróci każdy do domu swego w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'I rzekł król Izraelski do Jozafata: Izażem ci nie powiadał, że mi nie miał prorokować dobrego, ale złe?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'A Micheasz rzekł: Słuchajże tedy słowa Pańskiego: Widziałem Pana siedzącego na stolicy swojej, i wszystko wojsko niebieskie stojące po prawicy jego, i po lewicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'I rzekł Pan: Kto zwiedzie Achaba, aby szedł a upadł w Ramot Galaad? A gdy mówił jeden tak, a drugi inaczej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Tedy wystąpił duch, i stanął przed Panem, mówiąc: Ja go zwiodę. A Pan mu rzekł: Przez cóż?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'Odpowiedział: Wynijdę, a będę duchem kłamliwym w ustach wszystkich proroków jego. I rzekł mu Pan: Zwiedziesz, i pewnie przemożesz. Idźże, a czyń tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Przetoż teraz oto dał Pan ducha kłamliwego w usta tych wszystkich proroków twoich, gdyż Pan wyrzekł przeciwko tobie złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Tedy przystąpiwszy Sedechyjasz, syn Chenaana, uderzył Micheasza w policzek, mówiąc: Kiedyż odszedł Duch Pański odemnie, aby z tobą mówił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'I odpowiedział Micheasz: Oto ty ujrzysz dnia onego, kiedy wnijdziesz do najskrytszej komory, abyś się skrył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'I rzekł król Izraelski: Weźmij Micheasza, a wiedź go do Amona, starosty miejskiego, i do Joasa, syna królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'I rzeczesz: Tak mówi król: Wsadźcie tego męża do więzienia; a dawajcie mu jeść chleb utrapienia i wodę ucisku, aż się wrócę w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'Ale odpowiedział Micheasz: Jeźliże się wrócisz w pokoju, tedyć nie mówił Pan przez mię. Nadto rzekł: Słuchajcież wszyscy ludzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'A tak ciągnął król Izraelski i Jozafat, król Judzki, do Ramot Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'I rzekł król Izraelski do Jozafata: Odmienię się, gdy pójdę do bitwy; ale ty ubierz się w szaty twoje. I odmienił się król Izraelski, a szedł ku bitwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'A król Syryjski rozkazał był hetmanom, których było trzydzieści i dwa nad wozami jego, mówiąc: Nie potykajcie się ani z małym, ani z wielkim, tylko z samym królem Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'I stało się, gdy ujrzeli Jozafata hetmani, co byli nad wozami, rzekli: Zaprawdę to król Izraelski; i obrócili się przeciwko niemu, chcąc się z nim potykać; ale Jozafat zawołał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Wtem obaczywszy hetmani, co byli nad wozami, że nie ten był król Izraelski, odwrócili się od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Lecz mąż niektóry strzelił z łuku na niepewne, i postrzelił króla Izraelskiego między nity i między pancerz; który rzekł woźnicy swemu: Nawróć, a wywieź mię z wojska; bom jest raniony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'I wzmogła się bitwa dnia onego, a król stał na wozie przeciw Syryjczykom: potem umarł w wieczór, a krew ciekła z rany jego na wóz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'Tedy wołał woźny w wojsku, gdy już słońce zachodziło, mówiąc: Wróć się każdy do miasta swego i każdy do ziemi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'A tak umarł król, a odwiezion jest do Samaryi, i pochowano go w Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'A gdy umywano wóz w sadzawce Samaryjskiej, lizali psy krew jego, także gdy umywano zbroję jego: według słowa Pańskiego, które był powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'A inne sprawy Achabowe i wszystko, co czynił, i dom z kości słoniowych, który zbudował, wszystkie też miasta, które pobudował, azaż to nie jest spisane w kronikach o królach Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'I zasnął Achab z ojcami swymi, a królował Ochozyjasz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'A Jozafat, syn Azy, począł królować nad Judą czwartego roku za panowania Achaba, króla Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'A Jozafat miał trzydzieści i pięć lat, gdy królować począł, a dwadzieścia i pięć lat królował w Jeruzalemie; a imię matki jego było Azuba, córka Salajowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'I chodził po wszystkiej drodze Azy, ojca swego, a nie odchylał się od niej, czyniąc to, co było dobrego przed oczyma Pańskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Wszakże iż wyżyn nie poburzyli, jeszcze lud ofiarował i kadził po wyżynach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'Uczynił też pokój Jozafat z królem Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'A inne sprawy Jozafatowe, i moc jego, której dokazywał, i jako walczył, azaż to nie jest napisane w kronikach królów Judzkich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'Ten wyplenił z ziemi ostatek Sodomczyków, którzy byli pozostali za dni Azy, ojca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'Na ten czas nie było króla w Edomskiej ziemi; tylko starosta był miasto króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'I nasprawiał Jozafat okrętów na morze, aby chodziły do Ofir po złoto. Ale nie doszły; bo się rozbiły one okręty w Asyjon Gaber.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Rzekł także był Ochozyjasz, syn Achaba, do Jozafata: Niech jadą słudzy moi z sługami twymi w okrętach. Ale niechciał Jozafat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'Zasnął tedy Jozafat z ojcami swymi, i pochowany jest z ojcami swymi w mieście Dawida, ojca swego; a królował Joram, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ochozyjasz, syn Achaba, począł królować nad Izraelem w Samaryi roku siedmnastego Jozafata, króla Judzkiego, i królował nad Izraelem dwa lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'I czynił złe przed oczyma Pańskiemi, chodząc drogą ojca swego, i drogą matki swej, i drogą Jeroboama, syna Nabatowego, który przywiódł do grzechów Izraela. Służył także Baalowi, a kłaniał mu się, i pobudzał do gniewu Pana, Boga Izraelskiego, według wszystkiego, co czynił ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'I odstąpił Moab od Izraela po śmierci Achabowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'A Ochozyjasz spadł przez kratę sali swej, którą miał w Samaryi, i rozniemógł się. I wyprawił posły, mówiąc im: Idźcie, poradźcie się Beelzebuba, boga Akkarońskiego, jeżeli powstanę z tej choroby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Ale Anioł Pański rzekł do Elijasza Tesbity: Wstań, idź przeciwko posłom króla Samaryi, i mów do nich: Izali niemasz Boga w Izraelu, iż się idziecie radzić Beelzebuba, boga Akkarońskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Przetoż tak mówi Pan: Z łoża, na któreś się położył, nie wstaniesz, ale pewnie umrzesz. I odszedł Elijasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'A gdy się posłowie wrócili do niego, rzekł do nich: Czemużeście się wrócili?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Odpowiedzieli mu: Mąż niektóry zaszedł nam drogę, i mówił do nas: Idźcie, wróćcie się do króla, który was posłał, i rzeczcie mu: Tak mówi Pan: Izaliż niemasz Boga w Izraelu, że się posyłasz radzić Beelzebuba, boga Akkarońskiego? Przetoż z łoża na któreś się położył, nie wstaniesz, ale pewnie umrzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'I rzekł do nich: Cóż za osoba była tego męża, który wam zaszedł drogę, i mówił do was te słowa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'I opowiedzieli mu: Mąż kosmaty, a pasem skórzanym przepasany na biodrach swych. I rzekł: Elijasz Tesbita jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Przetoż posłał do niego pięćdziesiątnika z pięćdziesięcioma jego, który poszedł do niego, (a oto siedział na wierzchu góry,) i rzekł mu: Mężu Boży, król rozkazał, abyś zstąpił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'A odpowiadając Elijasz, rzekł pięćdziesiątnikowi: Jeźliżem jest mąż Boży, niech ogień zstąpi z nieba, a pożre ciebie i pięćdziesięciu twoich. Zstąpił tedy ogień z nieba, i pożarł go i pięćdziesięciu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'Znowu posłał do niego pięćdziesiątnika drugiego z pięćdziesięcioma jego, który mówił do niego, i rzekł: Mężu Boży, tak mówi król: Rychło zstąp.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'I odpowiedział Elijasz, a rzekł mu: Jeźlim jest mąż Boży, niech zstąpi ogień z nieba, a pożre ciebie i pięćdziesiąt twoich. Tedy zstąpił ogień Boży z nieba, i pożarł go i pięćdziesięciu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'Tedy jeszcze posłał pięćdziesiątnika trzeciego z pięćdziesięcioma jego. Przetoż poszedł pięćdziesiątnik on trzeci, a przyszedłszy poklęknął na kolana swoje przed Elijaszem, a prosząc go pokornie, mówił do niego: Mężu Boży, proszę niech będzie droga dusza moja, i dusza tych sług twoich pięćdziesięciu w oczach twoich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Oto zstąpił ogień z nieba, i pożarł dwóch pięćdziesiątników pierwszych z pięćdziesięciu ich; ale teraz niech będzie droga dusza moja w oczach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'I rzekł Anioł Pański do Elijasza: Zstąp z nim, nie bój się twarzy jego. Który wstawszy poszedł z nim do króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'I rzekł mu: Tak mówi Pan: Przeto, żeś wyprawił posły radzić się Beelzebuba, boga Akkarońskiego, jakoby Boga nie było w Izraelu, abyś się pytał słowa jego, dlatego z łoża, na któremeś się położył, nie wstaniesz, ale pewnie umrzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'A tak umarł według słowa Pańskiego, które mówił Elijasz. I królował Joram miasto niego, roku wtórego Jorama, syna Jozafatowego, króla Judzkiego; albowiem on nie miał syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'A inne sprawy Ochozyjaszowe, które czynił, azaż nie są napisane w kronikach o królach Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'I stało się, gdy miał wziąć Pan Elijasza w wichrze do nieba, że wyszedł Elijasz z Elizeuszem z Galgal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'I rzekł Elijasz do Elizeusza: Proszę siedź tu; bo mię Pan posłał aż do Betel. I rzekł Elizeusz: Jako żywy Pan, i jako żywa dusza twoja, że się ciebie nie puszczę. I przyszli do Betel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'Tedy wyszli synowie proroccy, którzy byli w Betel, do Elizeusza, i rzekli do niego: Wieszże, iż dziś Pan weźmie od ciebie pana twego? A on rzekł: Wiemci; milczcie tylko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'Znowu rzekł mu Elijasz: Elizeuszu, proszę siedź tu; bo mię Pan posłał do Jerycha. A on odpowiedział: Jako żywy Pan, i jako żywa dusza twoja, że się ciebie nie puszczę. A tak przyszli do Jerycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'Tedy przystąpiwszy synowie proroccy, którzy byli w Jerychu, do Elizeusza, rzekli do niego: Wieszże, że dziś Pan weźmie pana twego od ciebie? A on rzekł: Wiemci; milczcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'Jeszcze mu rzekł Elijasz: Proszę siedź tu; bo mię Pan posłał do Jordanu. Który odpowiedział: Jako żywy Pan, jako żywa i dusza twoja, że się ciebie nie puszczę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'I szli obadwaj. A pięćdziesiąt mężów synów prorockich szli, i stanęli naprzeciwko z daleko; ale oni obaj stanęli nad Jordanem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'A wziąwszy Elijasz płaszcz swój, zwinął go, a uderzył nim wody, i rozdzieliły się tam i sam, tak iż przeszli obaj po suszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'A gdy przeszli, rzekł Elijasz do Elizeusza: Żądaj, czego chcesz, abym ci uczynił pierwej niż będę wzięty od ciebie. Tedy rzekł Elizeusz: Proszę niech będzie dwójnasobny duch twój we mnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Ale mu on odpowiedział: Trudnejś rzeczy pożądał; wszakże ujrzyszli mię, gdy będę wzięty od ciebie, tak ci się stanie; ale jeźli nie ujrzysz, nie stanieć się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'I stało się, gdy oni przecię szli rozmawiając, oto wóz ognisty, i konie ogniste rozłączyły obydwóch. I wstąpił Elijasz w wichrze do nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'Co Elizeusz widząc, wołał: Ojcze mój, ojcze mój! Wozie Izraelski i jazdo jego. I nie widział go więcej. A pochwyciwszy szaty swe rozdarł je na dwie części.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'I podniósł płaszcz Elijaszowy, który był spadł z niego, a wróciwszy się, stanął nad brzegiem Jordanu. A tak wziąwszy płaszcz Elijaszowy, który był spadł z niego, uderzył nim wody, mówiąc: Gdzież jest Pan, Bóg Elijaszowy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'A tak i on uderzył nim wody, a rozdzieliły się tam i sam, i przeszedł Elizeusz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'Co widząc synowie proroccy, którzy byli w Jerycho, stojąc na przeciwko, rzekli: Odpoczął duch Elijaszowy nad Elizeuszem; a wyszedłszy przeciwko niemu pokłonili mu się aż do ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'I rzekli do niego: Oto teraz jest przy sługach twych pięćdziesiąt mężów mocnych. Proszę niech idą, a niech szukają Pana twego; by go snać nie zaniósł Duch Pański, a nie porzucił go na której górze, albo w której dolinie. Ale im on rzekł: Nie posyłajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'A gdy nań nalegali aż do uprzykrzenia, rzekł: Poślijcież. A tak posłali onych pięćdziesiąt mężów, którzy szukając przez trzy dni nie znaleźli go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'A gdy się wrócili do niego, (a on mieszkał w Jerycho,) rzekł do nich: Azażem wam nie mówił: Nie chodźcie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'Rzekli też mężowie onego miasta do Elizeusza: Wej, oto mieszkanie miasta tego jest dobre, jako panie mój widzisz; ale wody złe i ziemia niepłodna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'Tedy rzekł: Przynieście mi bańkę nową, a włóżcie w nię soli. I przynieśli mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'A poszedłszy do źródła wód, wrzucił tam soli, i rzekł: Tak mówi Pan: Uzdrowiłem te wody; nie będzie więcej stamtąd śmierci, ani niepłodności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'A tak uzdrowione są one wody aż do dnia tego, według słowa Elizeuszowego, które był powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'Potem szedł stamtąd do Betel. A gdy szedł drogą, dzieci małe wyszły z miasta, i naśmiewały się z niego, i mówiły mu: Idźże łysy, idźże łysy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'Który obejrzawszy się, ujrzał je, i złorzeczył im w imieniu Pańskiem. Przetoż wyszedłszy dwie niedźwiedzice z lasu, rozdrapały z nich czterdzieści i dwoje dzieci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'I szedł stamtąd na górę Karmel, a z onąd zasię wrócił się do Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'A Joram, syn Achaba, począł królować nad Izraelem w Samaryi roku ośmnastego Jozafata, króla Judzkiego, a królował dwanaście lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'I czynił złe przed oczyma Pańskiemi, acz nie tak jako ojciec jego, i jako matka jego. Albowiem wyrzucił słupy Baalowe, których był naczynił ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Wszakże w grzechach Jeroboama, syna Nabatowego, który przywiódł do grzechu Izraela, trwał a nie odstąpił od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'A Meza, król Moabski, miał dosyć bydła, a dawał królowi Izraelskiemu sto tysięcy jagniąt, i sto tysięcy baranów z wełną ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'I stało się, gdy umarł Achab, że odstąpił król Moabski od króla Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'Wyciągnął tedy król Joram dnia onego z Samaryi, i obliczył wszystkiego Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'A wyszedłszy posłał do Jozafata, króla Judzkiego, mówiąc: Król Moabski odstąpił odemnie; pociągnieszże zemną przeciw Moabowi na wojnę? I odpowiedział: Pociągnę. Jakom ja, tak ty; jako lud mój, tak lud twój; jako konie moje, tak konie twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'Zatem rzekł: Którąż drogą pociągniemy? I odpowiedział: Drogą puszczy Edomskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'A tak wyciągnął król Izraelski i król Judzki, i król Edomski. A gdy krążyli drogą siedm dni, nie dostało wody wojsku, ani bydłu, które szło z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'I rzekł król Izraelski: Ach, ach! Albowiem wezwał Pan tych trzech królów, aby je podał w ręce Moabskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Ale Jozafat rzekł: Niemaszże tu proroka Pańskiego, żebyśmy się poradzili Pana przezeń? I odpowiedział jeden z sług króla Izraelskiego, a rzekł: Jest tu Elizeusz, syn Safata, który nalewał wody na ręce Eliaszowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Tedy rzekł Jozafat: U tegoć jest słowo Pańskie. I szli do niego król Izraelski, i Jozafat, i król Edomski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'I rzekł Elizeusz do króla Izraelskiego: Co mnie i tobie? Idź do proroków ojca twego, i do proroków matki twej. I rzekł mu król Izraelski: Nie mów tak; bo Pan powołał tych trzech królów, aby je podał w ręce Moabowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'I odpowiedział Elizeusz: Jako żywy Pan zastępów, przed którego obliczem stoję, że gdybym się nie oglądał na Jozafata, króla Judzkiego, nie dbałbym na cię, anibym na cię wejrzał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Przetoż teraz przywiedźcie mi na harfie grającego. A gdy on gracz grał, była nad nim ręka Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'I rzekł: Tak mówi Pan: Poczyńcie w tym potoku gęste doły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Albowiem tak mówi Pan: Nie ujrzycie wiatru, ani ujrzycie deszczu, wszakże ten potok będzie pełen wody, tak, że pić będziecie wy, i stada wasze, i bydła wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'Aleć to jeszcze mała w oczach Pańskich; albowiem da i Moabity w ręce wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'I poburzycie wszystkie miasta obronne, i każde miasto wyborne, a wszystkie drzewa dobre podrąbicie, i wszystkie źródła wód zatkacie, i każdą rolę dobrą kamieniem zawalicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'I stało się rano, kiedy ofiarowana bywa ofiara śniedna, oto wody przychodziły drogą Edomską, i napełniła się ziemia wodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Tedy wszyscy Moabitowie usłyszawszy, że ciągną królowie walczyć przeciwko nim, zwołali wszystkie, którzy tak starzy byli, że pas przypasać mogli, i wyżej; a stanęli na granicach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'A wstawszy rano, gdy słońce weszło nad temi wodami, ujrzeli Moabczycy naprzeciw sobie wody czerwone jako krew,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'I rzekli: Krew jest; pewnie się pobili królowie, i pobici są jeden od drugiego. A tak teraz do łupu, o Moabczycy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'A gdy przyszli do obozu Izraelskiego, powstali Izraelczycy, i porazili Moabczyki, którzy uciekali przed nimi, a oni je bili, i porazili Moabczyki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'I miasta poburzyli, i na każde pole wyborne rzucił każdy kamień swój, i zarzucili je, i wszystkie żródła wód pozatykali, i wszystkie drzewa dobre podrąbali, tak, że tylko zaniechali kamienia w murze Kichareset. A obległszy je ci, co byli z procami dobywali go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'Tedy widząc król Moabski, że przemagało przeciw niemu wojsko, wziął z sobą siedm set mężów dobywających miecza, żeby się przebił przez wojsko króla Edomskiego, ale nie mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Przetoż pojmawszy syna jego pierworodnego, który miał królować miasto niego, ofiarował go całopaleniem na murze. I stało się zagniewanie wielkie, przeciw Izraelowi, i odciągnęli od niego, a wrócili się do ziemi swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'A niewiasta jedna z żon synów prorockich wołała do Elizeusza, mówiąc: Sługa twój, mąż mój, umarł. A ty wiesz, iż sługa twój bał się Pana. A teraz przyszedł pożyczalnik, aby sobie wziął dwóch synów moich za niewolniki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Do której rzekł Elizeusz: Cóż ci mam uczynić? Powiedz, mi co masz w domu? A ona odpowiedziała: Nie ma służebnica twoja nic więcej w domu, jedno bańkę oliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'I rzekł: Idźże, napożyczaj sobie naczynia z inąd u wszystkich sąsiadek twoich, naczynia próżnego nie mało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'A wszedłszy zamknij drzwi za sobą i za synami twymi, a nalej we wszystkie te naczynia, a które będzie pełne, rozkaż odstawić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'A tak odszedłszy od niego, zamknęła drzwi za sobą i za synami swymi.(Oni przynosili do niej, a ona nalewała.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'I stało się, gdy napełniła one naczynia, rzekła do syna swego: Przynieś mi jeszcze naczynie. A on jej odpowiedział: Niemasz więcej naczynia. I zastanowiła się oliwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Potem ona przyszedłszy, oznajmiła to mężowi Bożemu, który do niej rzekł: Idźże sprzedaj tę oliwę, a oddaj pożyczalnikowi twemu, a ty i synowie twoi żywcie się ostatkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'Stało się potem czasu niektórego, iż szedł Elizeusz przez Sunem, gdzie była niewiasta zacna, która go zatrzymywała, aby jadł chleb; a tak ile kroć tamtędy chodził, wstępował do niej, aby jadł chleb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'Bo rzekła była do męża swego: Oto teraz wiem, że ten mąż Boży święty jest, który tędy przechodzi często.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Proszę, uczyńmy gmaszek mały, a postawmy mu tam łóżko i stół, i krzesło i lichtarz, że kiedy przyjdzie do nas, skłoni się tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'A tak dnia jednego, gdy tam przyszedł, skłonił się do onego gmaszku, i odpoczął tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'I rzekł do Giezego, sługi swego: Zawołaj tej Sunamitki. I zawołał jej, a stanęła przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'Tedy mu rzekł: Powiedz jej: Oto pieczołujesz a starasz się o wszystki nasze potrzeby; cóż chcesz, abym ci uczynił? Maszże jaką potrzebę u króla, albo u hetmana wojska? A ona rzekła: W pośrodku ludu mego mieszkam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'A on rzekł: Cóż wżdy mam uczynić dla niej? I odpowiedział Giezy: Oto syna nie ma, a mąż jej stary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'Przetoż rzekł: Zawołajże jej. I zawołał jej, a ona stała u drzwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'I rzekł: O tym czasie po roku będziesz piastowała syna. A ona rzekła: Nie omylajże, panie mój, mężu Boży, nie omylaj służebnicy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'A tak poczęła niewiasta, i porodziła syna o onymże czasie po roku, jako jej był powiedział Elizeusz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'I podrosło dziecię. I stało się dnia niektórego, że wyszedłszy do ojca swego, do żeńców,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Rzekło do ojca swego: Głowa moja! Głowa moja! A on rzekł słudze: Zanieś go do matki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Który wziąwszy go, zaniósł go do matki jego; i siedział na łonie jej aż do południa i umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'Tedy ona szedłszy położyła go na łóżku męża Bożego, a zamknąwszy drzwi, wyszła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'Potem przyzwała męża swego, i rzekła: Proszę cię, poślij ze mną jednego z sług, i jednę oślicę, że pobieżę aż do męża Bożego, i wrócę się zaś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'Który rzekł: Po cóż chcesz jechać do niego? Dziś nie masz nowiu miesiąca, ani sabatu. Ale ona rzekła: Daj pokój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'A tak osiodławszy oślicę, rzekła do sługi swego: Poganiaj, a jedź, i nie mieszkaj dla mnie w drodze, chyba żebym ci rozkazała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Jechała tedy, i przyjechała do męża Bożego na górę Karmel. A gdy ją ujrzał mąż Boży z daleka, rzekł do Giezego sługi swego: Oto ona Sunamitka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Przetoż wynijdź przeciwko niej, a rzecz jej: A zdrowaś dobrze? zdrów i mąż twój? zdrów i syn?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'A ona rzekła: Zdrowi dobrze. A gdy przyszła do męża Bożego na górę, uchwyciła się nóg jego; i przystąpił Giezy, aby ją odepchnął. Ale mąż Boży rzekł: Zaniechaj jej, boć w gorzkości jest dusza jej, a Pan zataił przedemną i nie oznajmił mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'A ona rzekła: Azażem pana mego prosiła o syna? Izalim nie mówiła: Nie omylaj mię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Tedy on rzekł do Giezego: Przepasz biodra twe, a weźmij laskę moję w rękę twą, a idź; jeźli kogo spotkasz, nie pozdrawiaj go; a jeźli by cię kto pozdrowił, nie odpowiadaj mu; i połóż laskę moję na oblicze dziecięcia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'A matka dziecięcia onego rzekła: Jako żywy Pan, i jako żywa dusza twoja, że się ciebie nie puszczę. A tak wstawszy szedł za nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'A Giezy uprzedził je, i położył laskę na oblicze dziecięcia; lecz nie było głosu, ani czucia. Przetoż się wrócił przeciwko niemu i oznajmił mu, mówiąc: Nie ocuciło się dziecię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'Tedy wszedł Elizeusz do domu, a oto dziecię umarłe leżało na łóżku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'A gdy tam wszedł, zamknął drzwi przed onymi obydwoma, i modlił się Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'Potem wstąpiwszy na łoże, położył się na dzieciątko, przyłożywszy usta swe do ust jego, a oczy swe do oczów jego, i ręce swe do rąk jego, i rozpostarł się na niem, tak iż się zagrzało ciało dziecięce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'A odwróciwszy się od niego, przechadzał się po domu tam i sam; potem wstąpił, a położył się na niem. Tedy kichało dziecię aż do siódmego razu, i otworzyło dziecię oczy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'Tedy zawołał Giezego, i rzekł: Zawołaj tej Sunamitki. I zawołał jej, i przyszła do niego, i rzekł: Weźmij syna twego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Która wszedłszy, upadła u nóg jego, i kłaniała się aż do ziemi, a wziąwszy syna swego, wyszła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Potem wrócił się Elizeusz do Galgal, a głód był w onej ziemi, i synowie proroccy mieszkali przy nim. Tedy rzekł do sługi swego: Przystaw garniec wielki, a uwarz kaszę synom prorockim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'Przetoż wyszedł jeden na pole, aby zbierał zioła, i znalazł macicę polną, a nazbierał z niej owoców polnych pełen płaszcz swój, a przyszedłszy nakrajał ich w garniec kaszy; bo tego nie znali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'I wylali mężom onym, aby jedli. A gdy jedli onę kaszę zawołali, i rzekli: Śmierć w garncu, mężu Boży! I nie mogli jeść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'I rzekł: Przynieście sami mąki; a wsypawszy ją w garniec rzekł: Nalej ludowi. I jedli, i nie było nic więcej złego w garncu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'Wtem mąż przyszedł z Baalsalisa, a przyniósł mężowi Bożemu chleby, z pierwocin zbóż, dwadzieścia chlebów jęczmiennych, i kłosów pełnych świeżych nie wykruszonych, i rzekł: Daj ludowi, aby jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Ale odpowiedział sługa jego: Cóż to mam dać przed sto mężów? I rzekł: Daj ludowi, aby jedli; albowiem tak mówi Pan: Będą jedli, i zbędzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'A tak położył przed nie; i jedli, a zbyło według słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'A Naaman, hetman wojska króla Syryjskiego, był mąż wielki u pana swego, i osoba zacna. Albowiem przezeń dał był Pan wybawienie Syryjczykom; a ten mąż był duży w sile, ale trędowaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'A z Syryi wyszła była swawolna kupa, która pojmała z ziemi Izraelskiej dzieweczkę nie wielką, a ta służyła żonie Naamanowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'Która rzekła do pani swej: O gdyby się pan mój dostał do proroka, który jest w Samaryi! pewnieby go uzdrowił od trądu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'Wszedł tedy Naaman, i oznajmił to panu swemu, mówiąc: Tak a tak mówiła dzieweczka, która jest z ziemi Izraelskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Na co odpowiedział król Syryjski: Idź, wypraw się, a poślę list do króla Izraelskiego. A tak jechał, wziąwszy z sobą dziesięć talentów srebra, i sześć tysięcy złotych, i dziesięcioro szat odmiennych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'I przyniósł list do króla Izraelskiego w te słowa: Jako cię prędko dojdzie ten list, wiedz, żem posłał do ciebie Naamana, sługę mego, abyś go uzdrowił od trądu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'A gdy przeczytał król Izraelski list, rozdarł odzienie swoje, mówiąc: Azażem ja jest Bóg, żebym mógł umorzyć i ożywić, iż ten do mnie śle, abym uzdrowił męża tego od trądu jego? Uważcie proszę, a obaczcie, że szuka przyczyny na mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Co gdy usłyszał Elizeusz, mąż Boży, iż rozdarł król Izraelski szaty swe, posłał do króla, mówiąc: Przeczżeś rozdarł szaty swe? Niech przyjdzie do mnie, a dowie się, że jest prorok w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'A tak przyjechał Naaman z końmi swemi, i z wozem swym, i stanął u drzwi domu Elizeuszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'I wysłał do niego Elizeusz posła, mówiąc: Idź, a omyj się siedm kroć w Jordanie, a przywrócić się zdrowie ciała twego, i będziesz oczyszczony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'Tedy rozgniewawszy się Naaman, brał się w drogę, mówiąc: Otom myślał sam u siebie, iż pewnie wynijdzie, a stanąwszy przy mnie, wzywać będzie imienia Pana, Boga swego, podniósłszy rękę swoję nad miejscem trądu, uzdrowi trędowatego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Azaż nie lepsze są rzeki Abana i Farfar w Damaszku nad wszystkie wody Izraelskie? izalibym się niemógł w nich omyć, abym się oczyścił! A tak obróciwszy się, odjeżdżał z gniewem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Ale przystąpiwszy słudzy jego, mówili do niego, i rzekli: Ojcze mój, gdybyć był co wielkiego ten prorok rozkazał, azażbyś nie miał tego uczynić? Jako daleko więcej, gdy rzekł: Omyj się, a będziesz czystym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Przetoż szedłszy omył się w Jordanie siedm kroć według słowa męża Bożego; i stało się ciało jego, jako ciało dziecięcia małego, i oczyszczony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'Potem się wrócił do męża Bożego, on i wszystek poczet jego, a przyszedłszy stanął przed nim, i rzekł: Otom teraz poznał, że nie masz Boga na wszystkiej ziemi, tylko w Izraelu; przetoż weźmij proszę te upominki od sługi twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'A on rzekł: Jako żywy Pan, przed którego obliczem stoję, że nic nie wezmę; a choć go przymuszał, aby wziął, przecię nie chciał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'I rzekł Naaman: A nie chcesz? niechże będzie dane proszę słudze twemu brzemię ziemi na dwa muły; boć nie będzie więcej sprawował sługa twój całopalenia i innych ofiar bogom cudzym, jedno Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Wszakże w tej mierze niech odpuści Pan słudze swemu, gdy wchodzi pan mój do kościoła Remmon, aby się tam kłaniał, a wesprze się na ręce mojej, że się i ja kłaniam w kościele Remmon. Takowe moje kłanianie w kościele Remmon proszę niech odpuści Pan słudze twemu w tej mierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'I rzekł mu: Idź w pokoju. A gdy odjechał od niego, jakoby na milę drogi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'Rzekł Giezy, sługa Elizeusza, męża Bożego: Oto nie dopuścił pan mój temu Naamanowi Syryjskiemu, aby dał z ręki swej, co był przywiózł; jako żywy Pan, że pobieżę za nim, a wezmę co od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'A tak bieżał Giezy za Naamanem. Którego ujrzawszy Naaman bieżącego za sobą, skoczył z wozu przeciw niemu, i rzekł: Dobrzeż się wszystko dzieje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Któremu odpowiedział: Dobrze. Pan mój posłał mię, abym ci powiedział: Oto dopiero teraz przyszli do mnie dwaj młodzieńcy z góry Efraim z synów prorockich; dajże im proszę talent srebra, i dwie odmienne szaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'Tedy rzekł Naaman; Radniej weźmij dwa talenty. I przymusił go, i zawiązał dwa talenty srebra we dwa worki, i dwie odmienne szaty, i włożył na dwóch sług swoich, którzy nieśli przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'A przyszedłszy na pagórek, wziął to z ręki ich, i złożył w niektórym domu, a męże one odprawił, i odeszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'Potem przyszedłszy stanął przed panem swym. I rzekł do niego Elizeusz: Skądże Giezy? A on odpowiedział: Nie chodził nigdzie sługa twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'Ale mu on rzekł: Azaż serce moje nie chodziło z tobą, kiedy się obrócił on mąż z wozu swego przeciwko tobie? azaż czas był do brania srebra, i do brania szat, i oliwnic, i winnic, i bydła, i wołów, i sług, i służebnic?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Przetoż trąd Naamanowy przylgnie do ciebie, i do nasienia twego na wieki. I wyszedł od twarzy jego trędowaty, jako śnieg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'I rzekli synowie proroccy do Elizeusza: Oto miejsce, na którem mieszkamy przed tobą, ciasne jest dla nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Niech idziemy proszę aż do Jordanu, a weźmiemy stamtąd każdy po jednem drzewie, i zbudujemy tam sobie miejsce ku mieszkaniu. Którym on rzekł: Idźcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'I rzekł jeden z nich: Pójdź proszę i ty z sługami twoimi. A on rzekł: I ja pójdę; i szedł z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'A przyszedłszy do Jordanu, rąbali drzewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'I stało się, gdy jeden z nich obalał drzewo, że mu siekiera wpadła w wodę; i zawołał, mówiąc: Ach, ach, panie mój! i tać była pożyczona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'Rzekł tedy mąż Boży: Gdzież upadła? i ukazał mu miejsce. A on uciąwszy drewno, wrzucił tam, i sprawił, że wypłynęła ona siekiera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'I rzekł: Weźmij ją sobie; który ściągnąwszy rękę swą, wziął ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'A gdy król Syryjski walczył z Izraelem, i naradzał się z sługami swoimi, mówiąc: Na tem a na tem miejscu położy się wojsko moje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'Tedy posłał mąż Boży do króla Izraelskiego, mówiąc: Strzeż się, abyś nie przechodził przez ono miejsce; bo tam Syryjczycy są na zasadzce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'Przetoż posłał król Izraelski na ono miejsce, o którem mu był powiedział mąż Boży, i przestrzegł go, aby się go chronił, nie raz ani dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'A tak zatrwożyło się serce króla Syryjskiego, dla tego. Przetoż zwoławszy sług swoich, rzekł do nich: Czemuż mi nie powiecie, kto wżdy z was donosi to królowi Izraelskiemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'I rzekł jeden z sług jego: Nie tak, królu, panie mój; ale Elizeusz prorok, który jest w Izraelu, oznajmuje królowi Izraelskiemu słowa, które mówisz w tajemnym pokoju twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'A on rzekł: Idźcie, a dowiedzcie się, gdzie jest, abym posłał i pojmał go. I powiedziano mu, mówiąc: Oto jest w Dotanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Przetoż posłał tam konie i wozy z wielkiem wojskiem, którzy przyciągnąwszy w nocy, oblegli miasto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'Tedy wstawszy rano sługa męża Bożego, wyszedł, a oto wojsko otoczyło miasto, i konie, i wozy. I rzekł sługa jego do niego: Ach panie mój! Cóż mamy czynić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'A on odpowiedział: Nie bój się; bo więcej ich z nami, niż z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'Modlił się tedy Elizeusz, i rzekł: O Panie, otwórz proszę oczy jego, żeby widział. I otworzył Pan oczy sługi onego, i ujrzał, a oto góra pełna koni, i wozy ogniste około Elizeusza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'A gdy Syryjczycy szli do niego, modlił się Elizeusz Panu, mówiąc: Proszę, zaraź ten lud ślepotą. I zaraził je Pan ślepotą według słowa Elizeuszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'Wtem rzekł do nich Elizeusz: Nie tać to droga, ani to miasto. Pójdźcie za mną, a zawiodę was do męża, którego szukacie. I przywiódł je do Samaryi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'A gdy weszli do Samaryi, rzekł Elizeusz: O Panie, otwórz oczy tych, aby przejrzeli. I otworzył Pan oczy ich, i widzieli, że byli w pośród Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'I rzekł król Izraelski do Elizeusza, gdy je ujrzał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'Mamże je pobić, ojcze mój? Ale on rzekł: Nie bij. Azażeś je wziął przez miecz twój, albo przez łuk twój, żebyś je miał pobić? Połóż chleb i wodę przed nie, aby jedli i pili, i wrócili się do pana swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'A tak przygotował dla nich dostatek wielki, i jedli i pili; i puścił je, i odeszli do pana swego. I nie ważyły się więcej wojska Syryjskie wpadać do ziemi Izraelskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'Stało się potem, że zebrał Benadad, król Syryjski, wszystkie wojska swe, a przyciągnął i obległ Samaryję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'Przetoż był głód wielki w Samaryi; albowiem ją było oblężono, tak, iż głowę oślą sprzedawano za ośmdziesiąt srebrników, a czwartą część miary gnoju gołębiego za pięć srebrników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'I przydało się, gdy król Izraelski przechadzał się po murze, że jedna niewiasta zawołała nań mówiąc: Ratuj mię królu, panie mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'Który rzekł: nie ratujeli cię Pan, skądże ja ciebie poratuję? izali z gumna, czyli z prasy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'Nadto rzekł jej król: Cóż ci? A ona rzekła: Ta niewiasta rzekła do mnie: Daj syna twego, żebyśmy go zjadły dzisiaj, a jutro zjemy syna mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'I uwarzyłyśmy syna mego, i zjadłyśmy go. Potem rzekłam jej dnia drugiego: Daj syna twego, abyśmy go zjadły; ale ona skryła syna swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'A gdy król usłyszał słowa onej niewiasty, rozdarł odzienie swe; a gdy się przechodził po murze, widział lud, że wór był na ciele jego od spodku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Tedy rzekł król: To niechaj mi uczyni Bóg, i to przyczyni, jeźli się głowa Elizeusza, syna Safatowego, na nim dzisiaj ostoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, '(A Elizeusz siedział w domu swoim, i starcy siedzieli z nim.) I posłał męża z tych, którzy przed nim stali; a pierwej, niż on poseł przyszedł do niego, rzekł był do starszych: Nie wiecież, iż posłał syn tego mężobójcę, aby ścięto głowę moję? Patrzcież, gdy przyjdzie ten poseł, a zamknijcież drzwi, a zahamujcie go przede drzwiami; boć tenten nóg pana jego jest już za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'A gdy to jeszcze mówił z nimi, oto poseł przychodził ku niemu, i rzekł: Oto to złe jest od Pana; czegóż mam więcej oczekiwać od Pana?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Tedy rzekł Elizeusz: Słuchajcie słowa Pańskiego. Tak mówi Pan: O tym czasie jutro miara mąki pszennej będzie za sykiel, a dwie miary jęczmienia za sykiel, w bramie Samaryjskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'I odpowiedział książe, na którego się ręce król wspierał, mężowi Bożemu i rzekł: By też Pan poczynił okna w niebie, izaliby to mogło być? Który mu rzekł: Oto ty ujrzysz oczyma twemi; ale tego jeść nie będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'A byli czterej mężowie trędowaci u wyjścia bramy, którzy rzekli jeden do drugiego: Pocóż tu mieszkamy, ażbyśmy pomarli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Jeźli wnijdziemy do miasta, głód w mieście, i pomrzemy tam, a jeźli tu zostaniemy, przecię pomrzemy. Teraz tedy pójdźcie, a zbieżmy do obozu Syryjskiego; jeźli nas żywo zostawią, będziemy żywi; jeźli nas też zabiją, pomrzemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Wstali tedy, gdy się zmierzchać poczęło, aby szli do obozu Syryjskiego; a przyszedłszy na koniec obozu Syryjskiego, oto tam nie było nikogo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Albowiem sprawił Pan, że słychać było w obozie Syryjskim grzmot wozów i tenten koni, i huk wojska wielkiego, i rzekli jeden do drugiego: Oto najął za pieniądze przeciwko nam król Izraelski króle Hetejskie, i króle Egipskie, aby przypadli na nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'A tak wstawszy uciekli w zmierzch, zostawiwszy namioty swe, i konie swe i osły swe, i obóz jaki był, a uciekli, chcąc zachować duszę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'A gdy przyszli oni trędowaci aż na przodek obozu, weszli do jednego namiotu, i jedli i pili, a nabrawszy stamtąd srebra i złota, i szat, szli i skryli. Potem się wrócili, i weszli do drugiego namiotu, a nabrawszy także stamtąd, odeszli i pokryli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Zatem rzekł jeden do drugiego: Nie dobrze czynimy. Dzień ten jest dzień dobrej nowiny, a my milczymy? Jeźli będziemy czekali aż do zaranku, będziemy winni grzechu. Przetoż teraz pójdźcie, wnijdźmy, a opowiedzmy to domowi królewskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'A tak przyszedłszy zawołali na wrotnego miejskiego, i powiedzieli im mówiąc: Przyszliśmy do obozu Syryjskiego, a oto nie było tam nikogo, ani głosu ludzkiego, oprócz koni uwiązanych, i osłów uwiązanych, i namiotów, jako przedtem były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'Tedy on zawołał na inne wrotne, a ci opowiedzieli to w domu królewskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'Wstawszy tedy król w nocy, rzekł do sług swoich: Powiem ja wam, co nam uczynili Syryjczycy; wiedzą, żeśmy zgłodniali, przetoż wyszli z obozu, a pokryli się w polu, mówiąc: Gdy wynijdą z miasta, pojmiemy je żywo, i miasto ubieżemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Tedy odpowiedział jeden z sług jego, i rzekł: Proszę niech wezmą pięć koni pozostałych, które zostały w mieście; (oto one są jako wszystko mnóstwo Izraelskie, które zostało w niem; oto one są mówię jako wszystko mnóstwo Izraelskie, które ginie,) te wyślijmy a wywiedzmy się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'A tak wziąwszy dwa wozy z końmi, posłał król do obozu Syryjskiego, mówiąc: Idźcie a obaczcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'I szli za nimi aż do Jordanu, a oto po wszystkiej drodze pełno było szat i naczynia, które porzucili Syryjczycy, kwapiąc się. Tedy wróciwszy się oni posłowie, oznajmili to królowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Przeto wyszedłszy lud, rozchwycił obóz Syryjski; a była miara pszennej mąki za sykiel, a dwie miary jęczmienia za sykiel, według słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'A król postanowił był onego książęcia, na którego się ręce wspierał, w bramie, którego lud podeptał w bramie, aż umarł, jako mu był powiedział mąż Boży, który o tem mówił, gdy był król przyszedł do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'I stało się według słowa, które był rzekł mąż Boży królowi, mówiąc: Dwie miary jęczmienia za sykiel,a miara pszennej mąki będzie za sykiel, jutro o tym czasie w bramie Samaryjskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'Na co był odpowiedział on książe mężowi Bożemu, mówiąc: By też Pan uczynił okna w niebie, izali to będzie według słowa tego? A on mu rzekł: Oto ty ujrzysz oczyma twemi, ale tego jeść nie będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'I stało mu się tak; bo go podeptał lud w bramie, aż umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'Potem Elizeusz rzekł do onej niewiasty, której był syna wskrzesił, mówiąc: Wstań a idź, ty i dom twój, a bądź gościem, kędy będziesz mogła być; bo zawołał Pan głodu, i przyjdzie na ziemię przez siedm lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'Wstała tedy ona niewiasta, i uczyniła według słowa męża Bożego; a poszła ona i dom jej, i była gościem w ziemi Filistyńskiej przez siedm lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'I stało się po wyjściu siedmiu lat, że się wróciła ona niewiasta z ziemi Filistyńskiej, i poszła, aby wołała na króla o dom swój, i o rolę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'A na ten czas król rozmawiał z Giezym, sługą męża Bożego, mówiąc: Powiedz mi proszę wszystkie zacne sprawy, które czynił Elizeusz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'A gdy on powiadał królowi, jako wskrzesił umarłego, oto niewiasta, której był wskrzesił syna, zawołała na króla o dom swój i o rolę swoję. I rzekł Giezy: Królu panie mój, tać to jest niewiasta, i ten syn jej, którego wskrzesił Elizeusz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'I pytał król niewiasty, a ona mu powiedziała. I przydał jej król komornika jednego, mówiąc: Przywróć jej wszystko, co jej było, i wszystkie dochody z pola od onego dnia, którego opuściła ziemię, aż dotąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'Potem przyszedł Elizeusz do Damaszku, a Benadad, król Syryjski, chorował. I powiedziano mu, mówiąc: Przyszedł tu mąż Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'I rzekł król do Hazaela: Weźmij w rękę swą upominek, a idź przeciwko mężowi Bożemu, i pytaj się Pana przezeń, mówiąc: Wstanęli z tej choroby?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Przetoż szedł Hazael przeciwko niemu, a wziąwszy upominek w rękę swą, i ze wszystkich dóbr Damaskich brzemion na czterdzieści wielbłądów. I przyszedł, a stanął przed nim, mówiąc: Syn twój Benadad, król Syryjski, posłał mię do ciebie, mówiąc: Wstanęli z tej choroby?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'I odpowiedział mu Elizeusz: Idź, powiedz mu: Wprawdziebyści mógł żyć; wszakże okazał mi Pan, że pewnie umrzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'Wtem pokazał mu, i stawił twarz swoję smutną, i płakał mąż Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'Któremu rzekł Hazael: Czemuż pan mój płacze? I odpowiedział: Iż wiem, co uczynisz złego synom Izraelskim. Twierdze ich popalisz ogniem, a młodzieńce ich mieczem pomordujesz, i dzieci ich poroztrącasz, i brzemienne ich porozcinasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'Tedy rzekł Hazael: Co? Izali sługa twój pies, żeby miał czynić tak wielką rzecz? I odpowiedział Elizeusz: Okazał mi Pan, że ty będziesz królem nad Syrią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'I odszedł od Elizeusza, a przyszedł do pana swego, który rzekł do niego: Cóż ci powiedział Elizeusz? A on rzekł: Powiedział mi, żebyś pewnie mógł żyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'A nazajutrz wziął Hazael kołdrę i zamaczał ją w wodzie, i rozciągnął na twarzy jego. I umarł (Benadad), a Hazael królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'A roku piątego Jorama, syna Achaba, króla Izraelskiego, i Jozafata króla Judzkiego, począł królować Joram, syn Jozafata, król Judzki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Trzydzieści i dwa lata miał, gdy królować począł, a ośm lat królował w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'Ale chodził drogami królów Izraelskich, sprawując się jako dom Achabowy; bo córkę Achabową miał za żonę, i czynił złe przed oczyma Pańskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Wszakże nie chciał Pan wytracić Judy, dla Dawida, sługi swego, jako mu był powiedział, iż mu miał dać pochodnię między synami jego, po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'Za dni jego odstąpił Edom, aby nie był pod mocą Judy; i postanowili nad sobą króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Przetoż przyciągnął Joram do Seiru, i wszystkie wozy z nim; a wstawszy w nocy poraził Edomczyki, którzy go byli otoczyli, i hetmany wozów, tak iż lud uciekał do namiotów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Wszakże odstąpił Edom, aby nie był pod mocą Judy, aż do dnia tego. Odstąpiło także i Lobne onegoż czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'A inne sprawy Joramowe, i wszystko co czynił, izali nie jest napisane w kronikach o królach Judzkich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'I zasnął Joram z ojcami swymi, a pogrzebiony jest z ojcami swymi w mieście Dawidowem; i królował Ochozyjasz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'Roku dwunastego Jorama, syna Achaba, króla Izraelskiego, począł królować Ochozyjasz, syn Jorama, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'We dwudziestu i dwóch latach był Ochozyjasz, gdy królować począł, a rok jeden królował w Jeruzalemie; a imię matki jego było Atalija, córka Amrego, króla Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'Ten chodził drogą domu Achabowego, i czynił złe przed oczyma Pańskiemi, jako i dom Achabowy; bo był zięciem domu Achabowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'Przetoż wychadzał z Joramem, synem Achabowym, na wojnę przeciw Hazaelowi, królowi Syryjskiemu, do Ramot Galaadskiego; ale porazili Syryjczycy Jorama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'A tak wrócił się król Joram, aby się leczył w Jezreelu na rany, które mu byli zadali Syryjczycy w Ramacie, gdy walczył z Hazaelem, królem Syryjskim. A Ochozyjasz, syn Jorama, króla Judzkiego, przyjechał nawiedzać Jorama, syna Achabowego, do Jezreela; bo tam chorował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'A Elizeusz prorok zawołał jednego z synów prorockich, i rzekł mu: Przepasz biodra twoje, a weźmij tę bańkę olejku w rękę twą, a idź do Ramot Galaadskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'A gdy tam przyjdziesz, ujrzysz tam Jehu, syna Jozafatowego, syna Namsy, a wszedłszy tam, odwiedziesz go z pośrodku braci jego, i wprowadzisz go do gmachu najskrytszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'A wziąwszy bańkę olejku, wylejesz na głowę jego, i rzeczesz: Tak mówi Pan: Pomazałem cię za króla nad Izraelem. A otworzywszy drzwi ucieczesz, i nie zabawisz się tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Tedy odszedł on młodzieniec, sługa prorocki, do Ramot Galaadskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'A gdy przyszedł, oto hetmani wojsk siedzieli. I rzekł: Hetmanie! mam nieco z tobą mówić. I rzekł Jehu: Z którymże ze wszystkich nas? I odpowiedział: Z tobą, hetmanie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Tedy wstawszy wszedł do gmachu, a on wylał olejek na głowę jego, i rzekł mu: Tak mówi Pan, Bóg Izraelski: Pomazałem cię za króla nad ludem Pańskim, nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'I wytracisz dom Achaba, pana twego; albowiem pomszczę się krwi sług moich proroków, i krwi wszystkich sług Pańskich, z ręki Jezabeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'A tak zginie wszystek dom Achabowy; i wykorzenię z domu Achabowego aż do najmniejszego szczenięcia, i więźnia, i opuszczonego w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'I uczynię domowi Achabowemu, jako domowi Jeroboama, syna Nabatowego, i jako domowi Baazy, syna Achyjaszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'Jezabelę też zjedzą psy na polu Jezreelskim, a nie będzie, ktoby ją pogrzebał. To rzekłszy otworzył drzwi, i uciekł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'A gdy Jehu wyszedł do sług pana swego, rzekł mu jeden: A dobrzeż wszystko? Pocóż przychodził ten szalony do ciebie? A on im odpowiedział: Wy znacie tego męża, i mowę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Tedy rzekli: Nie prawda to; proszę powiedz nam. A on rzekł: Tak a tak rzekł do mnie, mówiąc: Tak mówi Pan: Pomazałem cię za króla nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Pospieszyli się tedy, a wziąwszy każdy szatę swą, kładli je podeń na najwyższym stopniu, i zatrąbiwszy w trąbę, mówili: Króluje Jehu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Tedy się sprzysiągł Jehu, syn Jozafata, syna Namsy, przeciw Joramowi. (A na ten czas Joram strzegł Ramot Galaadskiego, on i wszystek Izrael, przed Hazaelem, królem Syryjskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'Ale się był wrócił król Joram, aby się leczył na rany, które mu byli zadali Syryjczycy, gdy walczył z Hazaelem, królem Syryjskim.) I rzekł Jehu: Jeźli się wam zda, niech nie wychodzi nikt z miasta, żeby szedł co oznajmić w Jezreelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'I wsiadł na wóz Jehu, i jechał do Jezreela, bo tam Joram leżał; Ochozyjasz także, król Judzki, przyjechał był, aby nawiedził Jorama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'Wtem stróż, który stał na wieży w Jezreelu, ujrzawszy poczet Jehu przyjeżdżający, rzekł: Poczet jakiś widzę. I rzekł Joram: Weźmij jezdnego, a wyślij przeciwko nim, aby się spytał, jeźli pokój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'A tak bieżał jezdny przeciwko niemu, i rzekł: Tak mówi król: A pokój? I odpowiedział Jehu: Co tobie do pokoju? Obróć się, jedź za mną. Przetoż oznajmił stróż mówiąc: Dojechałci poseł do nich, ale się nie wraca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Zatem posłał drugiego jezdnego, który przyjechawszy do nich, rzekł: Tak mówi król: A pokój? Odpowiedział Jehu: Co tobie do pokoju? Obróć się, a jedź za mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'Znowu oznajmił to stróż, mówiąc: Przyjechałci do nich, ale się nie wraca. A przyjazd jego, jakoby przyjazd Jehu, syna Namsy; bo szalenie jedzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'Tedy rzekł Joram: Zaprzęgaj. I zaprzężono w wóz jego. I wyjechał Joram, król Izraelski, i Ochozyjasz, król Judzki, każdy na wozie swym. A wyjechawszy przeciw Jehu, trafili go na polu Nabota Jezreelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'A gdy ujrzał Joram Jehu, rzekł: Jestże pokój Jehu? I odpowiedział: Co za pokój? ponieważ jeszcze cudzołóstwa Jezabeli, matki twojej, i czary jej wielkie są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Przetoż obróciwszy się Joram uciekł, mówiąc do Ochozyjasza: Zdrada, Ochozyjaszu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'Tedy Jehu wziąwszy w ręce swoje łuk, postrzelił Jorama między ramiona jego, aż przeszła strzała przez serce jego, tak, że padł na wozie swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Potem rzekł Jehu do Badakiera, hetmana swego: Weźmij go, a porzuć na polu Nabota Jezreelskiego; albowiem pamiętasz, gdyśmy ja i ty jechali społu za Achabem, ojcem jego, że Pan wydał był przeciwko niemu tę pogróżkę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Zaiste krwi Nabota, i krwi synów jego, którąm widział wczoraj, rzekł Pan, pomszczę się nad tobą na tem polu. Pan to rzekł: przetoż teraz weźmij go, a porzuć go na polu według słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Co Ochozyjasz, król Judzki, ujrzawszy, uciekał drogą do domu ogrodowego. Ale go gonił Jehu, i rzekł: I tego zabijcie na wozie jego. I zranili go na wstąpie Guru, który jest podle Jeblaam. A uciekł do Magieddy, i tam umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'I kazali go zawieść słudzy jego do Jeruzalemu, a pogrzebli go w grobie jego z ojcami jego w mieście Dawidowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'A roku jedenastego Jorama, syna Achabowego, królował Ochozyjasz nad Judą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'Zatem przyszedł Jehu do Jezreel. Co gdy Jezabela usłyszała, ufarbowała twarz swoję, i ochędożyła głowę swą a patrzała z okna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'A gdy Jehu wjeżdżał w bramę, rzekła: Jestże pokój, o Zymry, morderzu pana swego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'A on podniósłszy twarz swoję ku oknu, rzekł: Któż ze mną trzyma, kto? Tedy wejrzeli nań dwaj albo trzej komornicy jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'Którym rzekł: Zrzućcie ją. I zrzucili ją, i popryskała się ściana i konie krwią jej, i podeptał ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'A gdy tam wszedł, jadł i pił, i rzekł: Obaczcie proszę onę przeklętą, a pogrzebcie ją; boć córką królewską jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'Tedy szedłszy, aby ją pogrzebli, nie znaleźli z niej jedno czaszkę z głowy, i nogi, i dłoni rąk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'A wróciwszy się, oznajmili mu to. Który rzekł: Wypełniło się słowo Pańskie, które powiedział przez sługę swego Elijasza Tesbitę, mówiąc: Na polu Jezreel zjedzą psy ciało Jezabeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'Niech będzie trup Jezabeli, jako gnój na roli, na polu Jezreel, tak żeby nie mówiono. Tać jest Jezabela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'A miał Achab siedmdziesiąt synów w Samaryi. I napisał Jehu list, a posłał go do Samaryi do książąt Jezreelskich, i do starszych i do tych, którzy wychowywali syny Achabowe, w te słowa:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Skoro was dojdzie ten list, gdyż u was są synowie pana waszego, i u was wozy, i konie, i miasto obronne, i rynsztunek;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'Obierzcież najgodniejszego i najsposobniejszego z synów pana waszego, a posadźcie na stolicy ojca jego, i walczcie o dom pana waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Ale się oni bardzo bojąc rzekli: Oto dwaj królowie nie ostali się przed nim, a jakoż my się ostoimy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'A tak posłał ten, który był sprawcą domu, i ten, który był sprawcą miasta, i starsi, i ci, którzy wychowywali syny królewskie, do Jehu, mówiąc: Słudzyśmy twoi, a co nam rozkażesz, uczynimy. Nie postanowiemy króla żadnego; co dobrego jest w oczach twoich, czyń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'I napisał do nich list drugi, mówiąc: Jeźliście moi, a głosu mego słuchacie, weźmijcież głowy synów pana waszego, a przyjdźcie do mnie jutro o tym czasie do Jezreel. A synów królewskich było siedmdziesiąt mężów u najprzedniejszych w mieście, którzy je wychowywali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'A gdy ich list doszedł, wziąwszy syny królewskie, pobili onych siedmdziesiąt mężów, a składłszy głowy ich do koszów, posłali je do niego do Jezreela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'I przyszedł poseł, który mu oznajmił, mówiąc: Przyniesiono głowy synów królewskich. A on rzekł: Składźcie je na dwie kupie u wejścia bramy aż do poranku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'A gdy rano wyszedł, stanął, i rzekł do wszystkiego ludu: Sprawiedliwiście wy. Otom się ja sprzysiągł przeciwko panu memu, i zabiłem go; ale te wszystkie któż pobił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Wiedzcież teraz, że nie upadło próżno żadne z słów Pańskich na ziemię, które mówił Pan przeciwko domowi Achabowemu, gdyż uczynił Pan, co był powiedział przez sługę swego Elijasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'A tak pobił Jehu wszystkie, którzy pozostali z domu Achabowego w Jezreelu, i wszystkie najprzedniejsze jego, i przyjaciele jego, i kapłany jego, tak iż nie zostawił po nim żadnego żywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'Potem wstawszy odszedł, i pojechał do Samaryi. A gdy był a domu, gdzie pasterze strzygali owce na drodze,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'Tedy Jehu znalazł u braci Ochozyjasza króla Judzkiego, i rzekł: Któście wy? I odpowiedzieli: Braciaśmy Ochozyjaszowi, a idziemy, abyśmy pozdrowili syny królewskie, i syny królowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'Tedy rzekł: Pojmajcie je żywo. I pojmali je żywo, i pobili je u studni onegoż domu, gdzie strzygano owce, czterdziestu i dwóch mężów, i nie zostawił żadnego z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'Potem odjechawszy stamtąd, trafił Jonadaba, syna Rechabowego, idącego przeciwko sobie, a pozdrowił go i rzekł do niego: Jestże serce twoje szczere, jako serce moje z sercem twojem? I odpowiedział mu Jonadab: Jest. A jest? rzekł Jehu, dajże mi rękę twoję. Tedy mu dał rękę swą; i kazał mu wsiąść do siebie na wóz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'I rzekł: Jedź ze mną, a przypatrz się gorliwości mojej za Pana. A tak wiózł go na wozie swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'A gdy przyjechał do Samaryi, bił wszystkie, którzy byli pozostali z domu Achabowego w Samaryi, i wytracił je według słowa Pańskiego, który mówił do Elijasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'Zatem zebrał Jehu wszystek lud, i rzekł do niego: Achab służył Baalowi mało, Jehu mu będzie służył więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Przetoż teraz wszystkich proroków Baalowych, i wszystkich sług jego, i wszystkich kapłanów jego, zwołajcie do mnie aż do jednego; albowiem ofiarę wielką będę sprawował Baalowi. Ktoby się kolwiek nie stawił, nie zostanie żyw. A to Jehu chytrze czynił, chcąc wytracić chwalce Baalowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'Nadto rzekł Jehu: Zapowiedzcie święto Baalowi. I obwołano je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'I rozesłał Jehu do wszystkiego Izraela. I zeszli się wszyscy chwalcy Baalowi, tak że nie został żaden, któryby nie przyszedł. I weszli do kościoła Baalowego, a napełniony był dom Baalowy od końca aż do końca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'Tedy rzekł temu, który był nad szatami: Wynieś szaty wszystkim chwalcom Baalowym. I wyniósł im szaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'Zatem wszedł Jehu i Jonadab, syn Rechabowy, do domu Baalowego, i rzekł chwalcom Baalowym: Dowiedzcie się, a obaczcie, by snać nie był kto z wami z chwalców Pańskich, oprócz samych chwalców Baalowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'A tak weszli, aby sprawowali ofiary, i całopalenia. Ale Jehu sporządził był sobie na dworze ośmdziesiąt mężów, którym był rzekł: Jeźliby kto uszedł z ludu tego, który ja podawam w ręce wasze, dusza wasza będzie za duszę onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'A gdy się dokończyły ofiary całopalenia, rzekł Jehu żołnierzom i rotmistrzom swym: Wnijdzcie, a pomordujcie je, aby żaden nie uszedł. A tak pomordowali je ostrzem miecza, i rozrzucili je żołnierze i rotmistrze; potem odeszli do każdego miasta, gdzie był dom Baalowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'A wyrzuciwszy bałwany z domu Baalowego, popalili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'Obalili też słup Baalowy, obalili i dom jego, a uczynili z niego wychody, aż do tego czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'A tak wygładził Jehu Baala z Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Wszakże od grzechów Jeroboama, syna Nabatowego, który do grzechu przywiódł Izraela, nie odstąpił Jehu, ani opuścił cielców złotych, które były w Betel, i które były w Dan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'Tedy rzekł Pan do Jehu: Ponieważeś się pilnie starał, abyś uczynił, co dobrego jest w oczach moich, według wszystkiego, co było w sercu mojem, uczyniłeś domowi Achabowemu: synowie twoi aż do czwartego pokolenia siedzieć będą na stolicy Izraelskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Ale Jehu nie strzegł tego, aby chodził w zakonie Pana, Boga Izraelskiego, ze wszystkiego serca swego, ani odstąpił od grzechów Jeroboamowych, który do grzechu przywiódł Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'W one dni począł Pan umniejszać Izraela: bo je poraził Hazael po wszystkich granicach Izraelskich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'Od Jordanu aż na wschód słońca, wszystkę ziemię Galaadską, Gadową, i Rubenową, i Manasesową od Aroer, które jest u potoku Arnon, i Galaad, i Basan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'Ale ostatek spraw Jehu, i wszystko, co czynił, i wszystka moc jego, azaż tego nie napisano w kronikach królów Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'I zasnął Jehu z ojcami swymi, i pochowali go w Samaryi; a królował Joachaz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'A czas, którego królował Jehu nad Izraelem w Samaryi, było dwadzieścia i ośm lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Tedy Atalija, matka Ochozyjaszowa, widząc iż umarł syn jej, powstała, i wytraciła wszystko nasienie królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Ale wziąwszy Josaba, córka króla Jorama, siostra Ochzyjaszowa, Joaza, syna Ochozyjaszowego, ukradła go z pośrodku synów królewskich, które zabijano; tego i z mamką jego w pokoju łożnicy skryła przed Ataliją, i nie zabito go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'I był przy niej w domu Pańskim skryty przez sześć lat, których Atalija królowała nad ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'Potem roku siódmego posławszy Jojada, przyzwał rotmistrzów, hetmanów i żołnierzy, i wprowadził je do siebie do domu Pańskiego, a uczyniwszy z nimi przymierze, przywiódł, je do przysięgi w domu Pańskim, i ukazał im syna królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'I rozkazał im, mówiąc: Toć jest co uczynicie: trzecia część z was, którzy przychodzicie w sabat, a trzymywacie straż, niech będzie przy domu królewskim:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'A trzecia część z was zostanie w bramie Sur; trzecia część zasię będzie w bramie, która jest za żołnierzami; a będziecie trzymali straż przy tym domu dla jakiego gwałtu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'A dwie części z was wszystkich wychodzących w sabat niech trzymają straż domu Pańskiego około króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'A tak obstąpicie króla około, każdy mając broń swą w rękach swych; a ktobykolwiek przyszedł do waszego szyku, niech będzie zabity, a wy będziecie przy królu, gdy wychodzić i wchodzić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'I uczynili rotmistrze oni według wszystkiego, co im był rozkazał Jojada kapłan; a wziąwszy każdy męże swe, którzy przychodzili w sabat, i którzy odchodzili w sabat, przyszli do Jojady kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'Tedy dał kapłan rotmistrzom włócznie i tarcze, które były króla Dawida, które były w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'I stali żołnierze, każdy mając broń swoję w rękach swych, od prawej strony domu aż do lewej strony domu przeciwko ołtarzowi, i przeciwko domowi około króla zewsząd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Tedy wywiódł syna królewskiego, i włożył nań koronę, i świadectwo. I uczynili go królem, i pomazali go, a klaskając rękoma mówili: Niech żyje król!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Wtem usłyszawszy Atalija krzyk zbiegającego się ludu, weszła do ludu do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'A gdy ujrzała, że oto król stał na majestacie według zwyczaju, a książęta i trąby około króla, a wszystek lud ziemi weselący się, i trąbiący w trąby, rozdarła Atalija odzienie swoje, i wołała: Sprzysiężenie, sprzysiężenie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Przetoż rozkazał Jojada kapłan rotmistrzom, którzy byli nad wojskiem, i rzekł do nich: Wywiedźcie ją z zagrodzenia kościoła, a ktobykolwiek chciał iść za nią, niech zabity będzie mieczem; bo rzekł był kapłan: Niech nie będzie zabita w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'I uczynili jej plac; a gdy przyszła na drogę, którą wodzono konie do domu królewskiego, tamże jest zabita.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Tedy uczynił Jojada przymierze między Panem, i między królem, i między ludem, aby byli ludem Pańskim; także między królem i między ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'I wszedł wszystek lud onej ziemi do domu Baalowego, i zburzyli go; ołtarze jego i obrazy jego połamali do szczętu; nadto Matana, kapłana Baalowego, zabili przed ołtarzami. I postanowił znowu kapłan przełożone nad domem Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'Potem wziąwszy rotmistrze, i hetmany, i żołnierze, i wszystek lud onej ziemi, prowadzili króla z domu Pańskiego, i przyszli drogą aż ku bramie żołnierzy, do domu królewskiego. I usiadł na stolicy królewskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'I weselił się wszystek lud onej ziemi, a miasto się uspokoiło, gdy Ataliją zabito mieczem podle domu królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'A było siedm lat Joazowi, gdy począł królować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'Roku siódmego Jehu począł królować Joaz, a czterdzieści lat królował w Jeruzalemie; imię matki jego było Sebija z Beersaby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'I czynił Joaz, co dobrego było w oczach Pańskich, po wszystkie dni swoje, których go uczył Jojada kapłan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Wszakże wyżyny nie były zniesione; jeszcze lud ofiarował i kadził na onych wyżynach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'I rzekł Joaz do kapłanów: Wszystkie pieniądze poświęcone, które przychodzą do domu Pańskiego, pieniądze tych, którzy idą w liczbę, pieniądze każdego z osobna według szacunku jego, i wszystkie pieniądze, które ktokolwiek dobrowolnie znosi do domu Pańskiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'Te wezmą do siebie kapłani każdy od znajomego swego; a oni naprawią skazę domu Pańskiego wszędy, gdzieby się znalazła skaza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'I stało się roku dwudziestego i trzeciego króla Joaza, gdy jeszcze nie poprawili byli kapłani skazy domu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Że wezwał król Joaz Jojady kapłana, i innych kapłanów, i mówił do nich: Przecz nie oprawujecie skazy domu? Przetoż teraz nie bierzcie pieniędzy od znajomych waszych, ale one na poprawę skazy domu oddawajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'I zezwolili na to kapłani; żeby nie brali pieniędzy od ludu, i żeby nie poprawiali skazy domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'Przetoż wziąwszy Jojada kapłan skrzynię jednę, uczynił dziurę w wieku jej, a postawił ją przy ołtarzu po prawej stronie, kędy wchodzono do domu Pańskiego. I kładli w nię kapłani, którzy strzegli progu, wszystkie pieniądze, które wnoszono do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'A gdy widzieli, że było wiele pieniędzy w skrzyni, tedy przychodził pisarz królewski, i kapłan najwyższy, którzy zliczywszy chowali one pieniądze, które się znajdowały w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'I dawali pieniądze gotowe w ręce rzemieślników, przełożonych nad robotą domu Pańskiego; a ci je wydawali na cieśle, i na robotniki, którzy poprawiali domu Pańskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'I na murarze, i na te, co ciosali kamienie, i na kupowanie drzewa, i ciosanego kamienia, ku poprawie skazy domu Pańskiego, i na wszystek nakład ku poprawie domu onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'Wszakże nie sprawowano do domu Pańskiego kubków srebrnych, naczynia do muzyki, miednic, i trąb, żadnego naczynia złotego, i naczynia srebrnego, z pieniędzy, które przynoszono do domu Pańskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'Ale rzemieślnikom przełożonym nad robotą dawali je, i poprawiali za nie domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'A nie słuchano liczby tych ludzi, którym dawano pieniądze w ręce ich, aby wydawali rzemieślnikom, ponieważ to oni wiernie odprawowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Ale pieniądze za występek, i pieniądze za grzechy, nie były wnoszone do domu Pańskiego; kapłanom się dostawały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Tedy wyciągnął Hazael, król Syryjski, a walczył przeciwko Giet, i wziął je. Potem obrócił Hazael twarz swoję, aby ciągnął przeciwko Jeruzalemowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'Przetoż wziął Joaz, król Judzki, wszystkie rzeczy poświęcone, które byli poświęcili Jozafat i Joram, i Ochozyjasz, ojcowie jego, królowie Judzcy, i to, co był sam poświęcił, i wszystko złoto, które się znalazło w skarbach domu Pańskiego, i domu królewskiego, a posłał to do Hazaela, króla Syryjskiego, i odciągnął od Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Ale insze sprawy Joazowe, i wszystko co czynił, azaż to nie jest napisane w kronikach o królach Judzkich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'Potem powstawszy słudzy jego sprzysięgli się między sobą i zabili Joaza w Betmello, którędy chodzą do Selli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'To jest, zabili go Josachar, syn Semaatowy, i Jozabad, syn Sommerowy; ci słudzy jego zabili go, i umarł. A pochowali go z ojcami jego w mieście Dawidowem, i królował Amazyjasz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'Roku dwudziestego i trzeciego Joaza, syna Ochozyjasza, króla Judzkiego, królował Joachaz, syn Jehu, nad Izraelem w Samaryi siedmnaście lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'A czynił złe przed oczyma Pańskiemi; bo naśladował grzechów Jeroboama, syna Nabatowego, który przywiódł do grzechu Izraela, i nie odchylił się od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'I zapalił się gniew Pański przeciw Izraelowi, i podał je w rękę Hazaela, króla Syryjskiego, i w rękę Benadada, syna Hazaelowego, po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Ale gdy się modlił Joachaz przed obliczem Pańskiem, wysłuchał go Pan; bo widział ściśnienie Izraela, że go był ucisnął król Syryjski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, 'Przetoż dał Pan Izraelowi wybawiciela, a wyszli z ręki Syryjczyków, i mieszkali synowie Izraelscy w przybytkach swych, jako i przedtem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Wszakże nie odstąpili od grzechów domu Jeroboamowego, który przywiódł do grzechu Izraela, ale w nich chodzili; do tego jeszcze i gaj został w Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Aczkolwiek nie zostawił Joachazowi z ludu, jedno pięćdziesiąt jezdnych, i dziesięć wozów, i dziesięć tysięcy pieszych, gdyż je był wytracił król Syryjski, i w proch je pomłócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'Ale inne sprawy Joachazowe, i wszystko, co czynił, i moc jego, azaż to nie jest napisane w kronikach o królach Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'I zasnął Joachaz z ojcami swymi, i pochowano go w Samaryi, a królował Joaz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'Roku trzydziestego i siódmego Joaza, króla Judzkiego, królował Joaz, syn Joachazowy, nad Izraelem w Samaryi szesnaście lat;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'I czynił złe przed oczyma Pańskiemi, nie uchylając się od żadnych grzechów Jeroboama, syna Nabatowego, który przywiódł do grzechu Izraela; ale w nich chodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'A inne sprawy Joazowe, i wszystko co czynił, i moc jego, jako walczył przeciwko Amazyjaszowi, królowi Judzkiemu, azaż to nie jest napisane w kronikach o królach Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'I zasnął Joaz z ojcami swymi, a Jeroboam usiadł na stolicy jego. I pogrzebion jest Joaz w Samaryi z królami Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'A Elizeusz wpadł w ciężką chorobę, w której też umarł. I przyszedł do niego Joaz, król Izraelski, i płakał nad nim, mówiąc: Ojcze mój, ojcze mój! wozie Izraelski, i jazdo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'Tedy mu rzekł Elizeusz: Wemij łuk i strzały; a wziąwszy przyniósł do niego łuk i strzały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'I rzekł do króla Izraelskiego: Weźmij w rękę twoję łuk; i wziął go w rękę swoję; włożył też Elizeusz ręce swe na ręce królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'I rzekł: Otwórz to okno na wschód słońca. A gdy otworzył, rzekł Elizeusz: Strzelże! i strzelił. I rzekł: Strzała zbawienia Pańskiego, a strzała wybawienia przeciw Syryjczykom; albowiem porazisz Syryjczyki w Afeku aż do szczętu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Rzekł powtóre: Weźmij strzały! i wziął. Tedy rzekł do króla Izraelskiego: Uderz w ziemię! i uderzył trzy kroć a potem przestał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Przetoż rozgniewał się nań mąż Boży, i rzekł: Miałeś uderzyć pięć albo sześć kroć, bobyś był poraził Syryjczyki aż do szczętu: a teraz tylko po trzy kroć porazisz Syryjczyki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'Potem umarł Elizeusz, i pogrzebiono go. A kupy swawolne Moabskie wtargnęły do ziemi roku drugiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'I stało się, gdy chowano jednego człowieka, tedy ujrzawszy swawolną kupę, rzucili onego człowieka w grób Elizeuszowy, który gdy był wrzucony, a dotknął się kości Elizeuszowych, ożył i wstał na nogi swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'A Hazael, król Syryjski, trapił lud Izraelski po wszystkie dni Joachazowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'Ale ulitowawszy się ich Pan, zmiłował się nad nimi, i nawrócił się ku nim dla przymierza swego z Abrahamem, z Izaakiem, i z Jakóbem; i nie chciał ich wytracić, ani ich odrzucił od oblicza swego, aż do tego czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'I umarł Hazael, król Syryjski, a królował Benadad, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'Przetoż znowu Joaz, syn Joachazowy, odebrał miasta z ręki Benadada, syna Hazaelowego, które był wziął z rąk Joachaza, ojca jego, przez wojnę; bo po trzy kroć poraził go Joaz, i przywrócił miasta Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'Roku wtórego Joaza, syna Joachaza, króla Izraelskiego, począł królować Amazyjasz, syn Joaza, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Dwadzieścia i pięć lat miał, gdy królować począł, a dwadzieścia i dziewięć lat królował w Jeruzalemie. Imię matki jego było Joadana z Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'Ten czynił, co dobrego jest przed oczyma Pańskiemi, aczkolwiek nie tak jako Dawid, ojciec jego; według wszystkiego, co czynił Joaz, ojciec jego, postępował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Wszakże wyżyny nie były zniesione; jeszcze lud ofiarował i kadził po wyżynach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'A gdy zmocnione było królestwo w ręku jego, pobił sługi swe, którzy byli zabili króla, ojca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Lecz synów onych morderców nie pobił, jako napisano w księgach zakonu Mojżeszowego, gdzie rozkazał Pan, mówiąc: Nie pomrą ojcowie za synów, ani synowie pomrą za ojców, ale każdy za grzech swój umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'Ten też poraził Edomczyków dziesięć tysięcy w dolinie solnej, i wziął mocą Selę, a nazwał imię jej Jokteel, aż do tego czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Tedy posłał Amazyjasz posły do Joaza, syna Joachaza, syna Jehu, króla Izraelskiego, mówiąc: Pójdź, wejrzymy sobie w oczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Posłał zasię Joaz, król Izraelski, do Amazyjasza, króla Judzkiego, mówiąc: Oset, który jest na Libanie, posłał do cedru Libańskiego, mówiąc: Daj córkę twoję synowi memu za żonę. Wtem przyszedł zwierz polny, który jest na Libanie, i podeptał on oset.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Żeś ty bardzo poraził Edomczyki, dlatego się podniosło serce twoje. Chlubże się, a siedź w domu twoim; i przeczże się masz wdawać w to złe, abyś upadł ty, i Juda z tobą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Ale nie usłuchał Amazyjasz. Przetoż wyciągnął Joaz, król Izraelski, a wejrzeli sobie w oczy, on i Amazyjasz, król Judzki, w Betsemes, które jest w Judztwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'I porażony jest Juda od ludu Izraelskiego, a uciekł każdy do przybytku swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'Lecz Amazyjasza, króla Judzkiego, syna Joaza, syna Ochozyjaszowego, pojmał Joaz, król Izraelski, w Betsemes, a przyciągnąwszy do Jeruzalemu, zburzył mur Jeruzalemski od bramy Efraim aż do bramy narożnej, na cztery sta łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'I zabrał wszystko złoto i srebro i wszystkie naczynia, które się znalazły w domu Pańskim, i w skarbach domu królewskiego, i ludzie zastawne, i wrócił się do Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'A inne sprawy Joazowe, które czynił, i moc jego, i jako walczył z Amazyjaszem, królem Judzkim, azaż tego nie zapisano w kronikach o królach Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'I zasnął Joaz z ojcami swymi, a pogrzebiony jest w Samaryi z królmi Izraelskimi, a królował Jeroboam, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'I żył Amazyjasz, syn Joazowy, król Judzki, po śmierci Joaza, syn Joachaza, króla Izraelskiego, piętnaście lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'A inne sprawy Amazyjaszowe, azaż nie są opisane w kronikach o królach Judzkich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'Potem sprzysięgli się przeciwko niemu niektórzy w Jeruzalemie; ale uciekł do Lachys. Przetoż posławszy za nim do Lachys, zabili go tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'Skąd przynieśli go na koniach, i pogrzebiony jest w Jeruzalemie z ojcami swymi, w mieście Dawidowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'A tak wziąwszy wszystek lud Judzki Azaryjasza, któremu było szesnaście lat, postanowili go królem na miejscu ojca jego Amazyjasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'Ten pobudował Elat, i przywrócił je do Judy, gdy zasnął król z ojcami swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'Roku piętnastego Amazyjasza, syna Joaza, króla Judzkiego, królował Jeroboam, syn Joaza, króla Izraelskiego, w Samaryi czterdzieści lat i rok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'A czynił złe przed oczyma Pańskiemi, nie uchylając się od wszystkich grzechów Jeroboama, syn Nabatowego, który przywiódł do grzechu Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'Ten zasię przywrócił granice Izraelskie od wejścia do Emat aż do morza pustego, według słowa Pana, Boga Izraelskiego, które był wyrzekł przez sługę swego Jonasza, syna Amaty, proroka; który był z Gatefer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Albowiem widział Pan utrapienie Izraelskie, im dalej tem większe, tak, że i więzień, i opuszczony zniszczeni byli, a nie był, ktoby ratował Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'A nie rzekł był Pan, aby miał wygładzić imię Izraela, żeby nie zostało pod niebem: przetoż je wybawił przez rękę Jeroboama, syna Joazaowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'A inne sprawy Jeroboamowe, i wszystko co czynił, i moc jego, którą walczył, i którą przywrócił Damaszek i Emat Judzkie Izraelowi, azaż tego nie zapisano w kronikach o królach Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'I zasnął Jeroboam z ojcami swymi, z królmi Izraelskimi, a królował Zacharyjasz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'Roku dwudziestego i siódmego Jeroboama, króla Izraelskiego, królował Azaryjasz, syn Amazyjasza, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Szesnaście mu lat było, gdy począł królować, a pięćdziesiąt i dwa lata królował w Jeruzalemie. Imię matki jego było Jechelija z Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'Ten czynił, co dobrego jest w oczach Pańskich, według wszystkiego, jako czynił Amazyjasz, ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Wszakże wyżyny nie były zniesione: jeszcze lud ofiarował i kadził po wyżynach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'I zaraził Pan króla, a był trędowaty aż do śmierci swej, i mieszkał w domu osobnym; przetoż Joatam, syn królewski, rządził domem, sądząc lud ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'A inne sprawy Azaryjaszowe, i wszystko co czynił, azaż tego nie zapisano w kronikach o królach Judzkich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'I zasnął Azaryjasz z ojcami swymi, a pochowano go z ojcami jego w mieście Dawidowem; a królował Joatam, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'Roku trzydziestego i ósmego Azaryjasza, króla Judzkiego, królował Zacharyjasz, syn Jeroboamowy, nad Izraelem w Samaryi sześć miesięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'I czynił złe przed oczyma Pańskimi, jako czynili ojcowie jego, nie odstępując od grzechów Jeroboama, syna Nabatowego, który przywiódł do grzechu Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'I sprzysiągł się przeciw niemu Sellum, syn Jabesowy, i ranił go przed ludem, i zabił go, a królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'A inne sprawy Zacharyjaszowe, oto są napisane w kronikach o królach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'Toć jest ono słowo Pańskie, które powiedział do Jehu, mówiąc: Synowie twoi do czwartego pokolenia będą siedzieli na stolicy Izraelskiej. I tak się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Tedy Sellum, syn Jabesowy, królował roku trzydziestego i dziewiątego roku Uzyjasza, króla Judzkiego, a królował przez jeden miesiąc w Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Bo przyciągnąwszy Manachem, syn Gady, z Tersy, a przyszedłszy do Samaryi, poraził Selluma, syna Jabesowego w Samaryi, a zabiwszy go, królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'A inne sprawy Sellumowe, i sprzysiężenie jego, którem się był sprzysiągł, oto zapisane w kronikach o królach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Tedy dobył Manachem miasta Tafsy, i pobił wszystkie, którzy w niem byli, i wszystki granice jego od Tersy; przeto, że mu nie otworzyli, pomordował je, i wszystkie brzemienne w niem porozcinał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'Roku trzydziestego i dziewiątego Azaryjasza, króla Judzkiego, królował Manachem, syn Gady, nad Izraelem dziesięć lat w Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'I czynił złe przed oczyma Pańskiemi, nie odstępując od grzechów Jeroboama, syna Nabatowego, który do grzechu przywodził Izraela po wszystkie dni swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'A gdy wyciągnął Ful, król Assyryjski, przeciw ziemi Izraelskiej, dał Manachem Fulowi tysiąc talentów srebra, aby mu był na pomocy ku umocnieniu królestwa w rękach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'I ułożył Manachem podatek na Izraela, na wszystkie najbogatsze, aby dawali królowi Asyryjskiemu, po pięćdziesiąt syklów srebra, każdy z osobna; i wrócił się król Assyryjski, a nie bawił się tam w onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'A inne sprawy Manachemowe, i cokolwiek czynił, napisane są w kronikach o królach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'I zasnął Manachem z ojcami swymi, a królował Facejasz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'Roku pięćdziesiątego Azaryjasza, króla Judzkiego, królował Facejasz, syn Manachemowy, nad Izraelem w Samaryi dwa lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'I czynił złe przed oczyma Pańskiemi, nie odstępując od grzechu Jeroboama, syna Nabatowego, który przywiódł do grzechu Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'Tedy się zbuntował przeciwko niemu Facejasz, syn Romelijasza, hetman jego, i zabił go w Samaryi w pałacu domu królewskiego, z Argobem i z Aryjaszem, mając z sobą pięćdziesiąt mężów Galaadczyków, a zabiwszy go królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'A inne sprawy Facejaszowe i wszystko co czynił, oto napisano w kronikach o królach Izeraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'Roku pięćdziesiątego i wtórego Azaryjasza, króla Judzkiego, królował Facejasz syn Romelijasza, nad Izraelem w Samaryi dwadzieścia lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'I czynił złe przed oczyma Pańskiemi, nie odstępując od grzechu Jeroboama, syna Nabatowego, który przywiódł do grzechu Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'Za dni Facejasza, króla Izraelskiego, przyciągnął Teglet Falaser, król Assyryjski, i wziął Ajon i Abelbetmaacha, i Jonoe, i Kiedes, i Azor, i Galaad, i Galileę, wszystkę ziemię Neftali, a przeniósł obywatele jej do Assyryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'Tedy się zbuntował Ozeasz, syn Eli, przeciw Facejaszowi, synowi Romelijaszowemu, a raniwszy go, zabił go, i królował miasto niego roku dwudziestego Joatama, syna Uzyjaszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'A inne sprawy Facejaszowe, i wszystko co czynił, oto zapisano w kronikach o królach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'Roku wtórego Facejasza, syna Romelijaszowego, króla Izraelskiego królował Joatam, syn Uzyjasza, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Dwadzieścia i pięć lat miał, gdy królować począł, i szesnaście lat królował w Jeruzalemie. Imię matki jego Jerusa, córka Sadokowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'I czynił, co dobrego jest przed oczyma Pańskiemi; według wszystkiego, co czynił Uzyjasz, ojciec jego, postępował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Wszakże wyżyny nie były zniesione; jeszcze lud ofiarował i kadził na wyżynach. Tenże zbudował bramę najwyższą domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'A inne sprawy Joatamowe, i wszystko co czynił, zapisane w kronikach o królach Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'Za onych dni począł Pan posyłać na Judę Rasyna, króla Syryjskiego, i Facejasza, syna Romelijaszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'I zasnął Joatam z ojcami swymi, i pogrzebiony jest z ojcami swymi w mieście Dawida, ojca swego. A królował Achaz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'Roku siedmnastego Facejasza, syna Romelijaszowego, królował Achaz, syn Joatama, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Dwadzieścia lat było Achazowi, gdy królować począł, a szesnaście lat królował w Jeruzalemie; ale nie czynił, co dobrego jest przed oczyma Pana, Boga swego, jako Dawid, ojciec jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'Lecz chodził drogami królów Izraelskich. Nadto i syna swego dał przewieść przez ogień według obrzydliwości poganów, które był Pan wygnał przed obliczem synów Izraeliskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'Ofiarował też i kadził na wyżynach, i na pagórkach, i pod każdem drzewem gałęzistem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Tedy wyciągnął Rasyn, król Syryjski, i Facejasz, syn Romelijasza, król Izraelski, przeciwko Jeruzalemowi na wojnę, i oblegli Achaza; wszakże go dobyć nie mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'Tegoż czasu Rasyn, król Syryjski, przywrócił zasię Elat do Syryi, a wykorzenił Żydy z Elat, ale Syryjczycy przyszedłszy do Elat, mieszkali tam aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'I posłał Achaz posły do Teglat Falasera króla Assyryjskiego, mówiąc: Sługa twój i syn twój jestem. Przyciągnij a wybaw mię z ręki króla Syryjskiego, i z ręki króla Izraelskiego, którzy powstali przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'Tedy wziąwszy Achaz srebro i złoto, które się znalazło w domu Pańskim i w skarbach domu królewskiego, posłał dar królowi Assyryjskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'Na co mu przyzwolił król Assyryjski; a przyciągnąwszy król Assyryjski pod Damaszek wziął go, i przeniósł obywatele jego do Chyr, a Rasyna zabił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Zatem jechał król Achaz przeciw Teglat Falaserowi, królowi Assyryjskiemu, do Damaszku; a ujrzawszy król Achaz ołtarz w Damaszku, posłał do Uryjasza kapłana wizerunek ołtarza onego i kształt jego, według wszystkiego jako był urobiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'I zbudował Uryjasz kapłan ołtarz według onego wszystkiego, jako był posłał król Achaz z Damaszku; tak uczynił Uryjasz kapłan pierwej, niżeli się wrócił król Achaz z Damaszku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'A gdy się wrócił król z Damaszku, ujrzawszy ołtarz przystąpił do niego, i sprawował ofiary na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'I zapalił całopalenie swoje, i ofiarę śniedną swoję, i ofiarował ofiarę mokrą swoję, i kropił krwią ofiar spokojnych swoich na ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Ale ołtarz miedziany, który był przed Panem, przeniósł z przedniej strony domu, aby nie stał między ołtarzem jego, a między domem Pańskim; a postawił go po bok ołtarza ku północy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'I rozkazał król Achaz Uryjaszowi kapłanowi, mówiąc: Na tym większym ołtarzu będziesz zapalał całopalenie poranne i ofiarę śniedną wieczorną, i całopalenie królewskie, i ofiarę śniedną jego, i całopalenie wszystkiego ludu ziemi, i ofiarę ich śniedną, i ofiary mokre ich, i wszelką krwią całopalenia, i wszelką krwią innych ofiar będziesz kropił na nim; ale ołtarz miedziany będzie mi na radzenie się Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'I uczynił Uryjasz kapłan według wszystkiego, jako był rozkazał król Achaz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Nadto poodcinał król Achaz listwy podstawków, i pozbierał z nich wanny; do tego morze zdjął z wołów miedzianych, które były pod niem, a położył je na tle kamiennem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Zasłonę także sabatnią, którą było sprawiono w domu, i drzwi zewnętrzne, któremi król wchadzał, odjął od domu Pańskiego dla bojażni króla Assyryjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'A inne sprawy Achazowe, które czynił, zapisane są w kronikach o królach Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'I zasnął Achaz z ojcami swymi, i pogrzebiony jest z ojcami swymi w mieście Dawidowem. A królował Ezechyjasz, syn jego miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'Roku dwunastego Achaza, króla Judzkiego, królował Ozeasz, syn Eli, w Samaryi nad Izraelem dziewięć lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'I czynił złe przed oczyma Pańskiemi, wszakże nie tak jak inni królowie Izraelscy, którzy byli przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Przeciwko niemu wyciągnął Salmanasar, król Assyryjski; i stał się Ozeasz niewolnikiem jego, i dawał mu dań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'A gdy obaczył król Assyryjski, iż się Ozeasz buntował przeciw niemu, a iż wyprawił posły do Sua, króla Egipskiego, i nie posyłał dani dorocznej królowi Assyryjskiemu, obległ go król Assyryjski, a związawszy podał go do więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'I ciągnął król Assyryjski przez wszystkę ziemię, aż przyciągnął do Samaryi, pod którą leżał przez trzy lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'A roku dziewiątego Ozeasza wziął król Assyryjski Samaryję, i przeniósł Izraela do Assyryi, a osadził je w Hala i w Habor nad rzeką Gozan i w miastach Medskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'A to się stało przeto, że grzeszyli synowie Izraelscy przeciw Panu, Bogu swemu, który je wywiódł z ziemi Egipskiej, aby nie byli pod mocą Faraona, króla Egipskiego; a bali się bogów cudzych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'Chodząc w ustawach poganów, które był Pan wyrzucił przed obliczem synów Izraelskich, i w ustawach królów Izraelskich, które czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'Obłudnie synowie Izraelscy postępowali, czyniąc co nie było rzeczą dobrą przed Panem, Bogiem swym, i pobudowali sobie wyżyny po wszystkich miastach swych, od wieży strażników aż do miasta obronnego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'A nastawiali sobie słupów, i gajów na każdym pagórku wyniosłym, pod każdem drzewem gałęzistem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'Paląc tam kadzidła po wszystkich górach, jako narody, które wypędził Pan przed obliczem ich; i czynili rzeczy co najgorsze, pobudzając Pana ku gniewu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'A służyli brzydkim bałwanom, o którym im powiedział Pan, aby tego nie czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'I oświadczał się Pan przeciwko Izraelowi, i przeciwko Judzie, przez wszystkie proroki, i przez wszystkie widzące, mówiąc: Nawróćcie się od dróg waszych złych, a strzeżcie rozkazania mego, i wyroków moich według wszystkiego zakonu, którym rozkazał ojcom waszym, a z którymem posłał do was proroki, sługi moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'Lecz nie byli posłuszni; ale zatwardzili kark swój według karku ojców swych, którzy nie wierzyli w Pana, Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'I wzgardzili wyroki jego, i przymierze jego, które uczynił z ojcami ich, i oświadczenia jego, któremi się oświadczał przeciwko nim, a chodzili za próżnością, i stali się próżnymi, i naśladowali poganów, którzy byli około nich, o których im rozkazał Pan, aby nie czynili jako oni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'I opuściwszy wszystkie rozkazania Pana, Boga swego, poczynili sobie lane bałwany, mianowicie dwóch cielców; poczynili też gaje, a kłaniali się wszystkiemu wojsku niebieskiemu, i służyli Baalowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'Przewodzili też syny i córki swe przez ogień, i bawili się wieszczbami i wróżkami, i zaprzedali się, aby czynili złe przed oczyma Pańskiemi, pobudzając go do gniewu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'Przetoż się bardzo Pan rozgniewał na Izraela, a odrzucił je od oblicza swego, nic z nich nie zostawując, oprócz samego pokolenia Judy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Aleć i Juda nie strzegł przykazań Pana, Boga swego; lecz chodził w ustawach Izaelskich, których naczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Przetoż odrzucił Pan wszystko nasienie Izraelskie, i utrapił je, a podał je w rękę łupieżcom, aż je odrzucił od oblicza swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Albowiem oderwał się Izrael od domu Dawidowego, a postanowili królem Jeroboama, syna Nabatowego; ale Jeroboam odwiódł Izraela od naśladowania Pana, a przywiódł je do grzeszenia grzechem wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'I chodzili synowie Izraelscy we wszystkich grzechach Jeroboamowych, które on czynił, a nie odstąpili od nich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'A odrzucił Pan Izraela od oblicza swego, jako powiedział przez wszystkie sługi swe proroki; a tak przeniesiony jest Izrael z ziemi swej do Assyryi, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Potem przyprowadził król Assyryjski lud z Babilonu, i z Kuta, i z Awa, i z Emat, i z Sefarwaim, a osadził je w miastach Samaryi miasto synów Izraelskch; którzy posiadłszy Samaryję, mieszkali w miastach jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'A gdy tam oni mieszkać poczęli a nie bali się Pana, posłał Pan na nie lwy, którzy je zabijali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'I powiedziano to królowi Assyryjskiemu, mówiąc: Narodowie, któreś przeniósł i osadził w miastach Samaryi, nie wiedzą obyczaju Boga onej ziemi; przetoż posłał na nie lwy, a oto je zabijają, dla tego, iż nie wiedzą obyczaju Boga onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Tedy rozkazał król Assyryjski, mówiąc: Zawiedźcie tam jednego z kapłanów, któreście stamtąd przywiedli, aby poszedłszy mieszkał tam, i nauczał ich obyczaju Boga onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Przyszedł tedy jeden z kapłanów, których było wzięto z Samryi, i mieszkał w Betel, a nauczał ich, jako się mieli bać Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Wszakże naczynili sobie każdy naród bogów swych, i postawili je w domu wyżyn, które byli pobudowali Samaryjczycy, każdy naród w miastach swych, w których mieszkali,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Albowiem mężowie Babilońscy uczynili Sukkotbenot, a mężowie Kutscy uczynili Nergiel, a mężowie Ematscy uczynili Asyma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'A Hewejczycy uczynili Nebahaz, i Tartak; a Sefarwaiczycy palili syny swe w ogniu Adramelechowi, i Anamelechowi, bogom Sefarwaimskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'A tak bali się Pana, naczyniwszy sobie z pośrodku siebie kapłanów na wyżynach, którzy im usługiwali w domach wyżyn.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'A choć się Pana bali, wszakże przecię bogom swoim służyli według zwyczajów onych narodów, skąd byli przeniesieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'Ci aż do dnia tego sprawują się według zwyczajów starych, nie boją się Pana, ani czynią według wyroków jego, i według ustaw jego, i według zakonu, i według rozkazania, które przykazał Pan synom Jakóbowym, którego przezwał Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 'Uczynił też był Pan z nimi przymierze, i rozkazał im, mówiąc: Nie bójcie się bogów cudzych, i nie kłaniajcie się im, ani im służcie, ani im ofiarujcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'Ale Pana, który was wywiódł z ziemi Egipskiej mocą wielką i ramieniem wyciągnionem, tego się bójcie, i jemu się kłaniajcie, i jemu ofiarujcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'Także ustaw, i sądów, i zakonu, i przykazań, które wam napisał, strzeżcie, czyniąc je po wszystkie dni, a nie bójcie się bogów cudzych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'Więc przymierza, którem czynił z wami, nie zapominajcie, ani się bójcie bogów cudzych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'Ale Pana, Boga waszego, się bójcie, a on was wybawi z ręki wszystkich nieprzyjaciół waszych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Lecz nie usłuchali, ale owszem według obyczaju swego dawnego czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'A tak narodowie oni bali się Pana, wszakże przecię rytym bałwanom swoim służyli; a synowie ich, i synowie synów ich, według wszystkiego, co czynili ojcowie ich, tak i oni czynią, aż po dziś dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'Roku trzeciego Ozeasza, syna Eli, króla Izraelskiego, królował Ezechyjasz, syn Achaza, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Dwadzieścia i pięć lat mu było, gdy począł królować, a dwadzieścia i dziewięć lat królował w Jeruzalemie. Imię matki jego było Abi, córka Zacharyjaszowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'I czynił co było dobrego przed oczyma Pańskiemi, według wszystkiego, jako czynił Dawid, ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'On zniósł wyżyny, i skruszył bałwany, i powycinał gaje, a pokruszył węża miedzianego, którego był uczynił Mojżesz; bo aż do onych dni Izraelczycy kadzili mu, i nazwał go Nehustan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'W Panu Bogu Izraelskim ufał; a po nim nie był żaden podobny jemu między wszystkimi królami Judzkimi, i którzy byli przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Bo się trzymał Pana, nie odstępując od niego, a strzegąc przykazania jego, które był przykazał Pan Mojżeszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'A Pan był z nim; i we wszystkiem, do czego się obrócił, szczęściło mu się. Wybił się też z mocy królowi Assyryjskiemu, i nie służył mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'Tenże poraził Filistyny aż do Gazy i granic jego, od wieży strażników aż do miasta obronnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Roku czwartego króla Ezechyjasza, (który był rok siódmy Ozeasza, syna Eli, króla Izraelskiego) wyciągnął Salmanaser, król Assyryjski, przeciwko Samaryi, i obległ ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'A wziął ją przy dokończeniu trzeciego roku; roku szóstego Ezechyjasza,(który był rok dziewiąty Ozeasza, króla Izraelskiego) wzięta jest Samaryja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'Tedy przeniósł król Assyryjski Izraela do Assyryi, i osadził nimi Halach i Habor u rzeki Gazan, i miasta Medskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'Przeto, iż nie posłuchali głosu Pana Boga swego, ale przestępowali przymierze jego, i tego wszystkiego, co rozkazał Mojżesz, sługa Pański, nie słuchali i nie czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'Potem czternastego roku króla Ezechyjasza ruszył się Sennacheryb, król Assyryjski, przeciw wszystkim miastom Judzkim obronnym, i wziął je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'A tak posłał Ezechyjasz, król Judzki, do króla Assyryjskiego, do Lachys, mówiąc: Zgrzeszyłem; odciągnij odemnie, cokolwiek na mię włożysz, poniosę. Tedy włożył król Assyryjski na Ezechyjasza, króla Judzkiego, dań trzy sta talentów srebra, i trzydzieści talentów złota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'I dał Ezechyjasz wszystko srebro, które się znalazło w domu Pańskim i w skarbach domu królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'Onegoż czasu obłupił Ezechyjasz drzwi domu Pańskiego, i słupy, które samże Ezechyjasz, król Judzki, był obył, a dał je królowi Assyryjskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'Wszakże posłał król Assyryjski Tartana, i Rabsarysa, i Rabsacesa z Lachys do króla Ezechyjasza z wielkiem wojskiem do Jeruzalemu. Którzy wyciągnąwszy przyjechali ku Jeruzalemowi, a przyciągnąwszy przyszli i położyli się u rur sadzawki wyższej, która jest podle drogi brukowanej na polu blecharzowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'A gdy wołali na króla, wyszedł do nich Elijakim, syn Helkijaszowy, przełożony nad domem, i Sobna pisarz, i Joach syn Asafowy, kanclerz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'I rzekł do nich Rabsaces: Proszę powiedzcie Ezechyjaszowi: Tak mówi król wielki, król Assyryjski: Co to za ufność, na której się wspierasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Mówiłeś: (aleć to słowa daremne) Rady i mocy mam dosyć do wojny. A teraz w kimże ufasz, żeś mi się sprzeciwił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Oto teraz spolegasz na Egipcie, jako na lasce trzcinnej, i to nałamanej, którą jeźliby się kto podpierał, tedy wnijdzie w rękę jego i przekole ją. Takić jest Farao, król Egipski, wszystkim, co w nim ufają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'A jeźli mi rzeczecie: W Panu Bogu naszym ufność mamy: azaż nie ten jest, którego zniósł Ezechyjasz wyżyny i ołtarze? i rozkazał Judzie i Jeruzalemowi, mówiąc: Przed tym ołtarzem kłaniać się będziecie w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Przetoż teraz zaręcz się królowi Assyryjskiemu, panu memu, a dam ci dwa tysiące koni; będzieszli mógł mieć jezdnych tak wiele do dnich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'I jakoż się ty możesz oprzeć hetmanowi jednemu najmniejszemu z sług pana mego? choć pokładasz nadzieję w Egipcie dla wozów i jezdnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Nadto, czy bez woli Pańskiej przyciągnąłem przeciw temu miejscu, abym je zburzył? Pan mówi do mnie: Idź do tej ziemi, a spustosz ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Tedy rzekł Elijakim, syn Helkijaszowy, i Sobna, i Joach do Rabsacesa: Proszę mów do sług twoich po syryjsku, boć rozumiemy; a nie mów z nami po żydowsku, gdzie słyszy lud, który jest na murze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Którym odpowiedział Rabsaces: Azaż mię do pana twego, albo do ciebie przysłał Pan mój, abym te słowa mówił? Azaż nie do tych mężów, którzy siedzą na murze, aby jedli łajna swoje, i pili mocz swój z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'A tak stanąwszy Rabsaces wołał głosem wielkim po żydowsku, a mówiąc rzekł: Słuchajcie słów króla wielkiego, króla Assyryjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Tak mówi król: Niech was nie zwodzi Ezechyjasz; bo was nie będzie mógł wyrwać z ręki mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'A niech wam nie rozkazuje ufać Ezechyjasz w Panu, mówiąc: Pewnie nas wyrwie Pan, a nie będzie podane to miasto w ręce króla Assyryjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Nie słuchajcie Ezechyjasza. Albowiem tak mówi król Assyryjski: Uczyńcie ze mną przymierze, a wynijdźcie do mnie, a jedzcie każdy z winnicy swojej i każdy z figi swojej, i pijcie każdy wodę z studnicy swojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'Aż przyjdę a pobiorę was do ziemi podobnej ziemi waszej, do ziemi żyznej i obfitującej winem, do ziemi chleba i winnic, do ziemi drzew oliwnych, i oliwy, i miodu; i będziecie żyli, a nie pomrzecie. Nie słuchajcież Ezechyjasza; bo was zwodzi, mó wiąc: Pan was wybawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Izaż mogli bogowie narodów wybawić każdy ziemię swoję, z ręki króla Assyryjskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Gdzież jest bóg Emat i Arfad? gdzież jest bóg Sefarwaim, Ana i Awa? izali wyrwali Samaryję z rąk moich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Któryż jest między wszystkimi bogi tych ziem, któryby wyrwał ziemię swoję z ręki mojej? A miałby Pan wyrwać Jeruzalem z ręki mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Ale milczał lud, i nie odpowiedzieli mu słowa; bo takie było rozkazanie królewskie, mówiąc: Nie odpowiadajcie mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Przyszedł tedy Elijakim, syn Helkijaszowy, przełożony domu, i Sobna pisarz, i Joach, syn Asafowy, kanclerz, do Ezechyjasza, rozdarłszy szaty swe, i oznajmili mu słowa Rabsacesowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'A gdy to usłyszał król Ezechyjasz, rozdarł szaty swoje, a oblekł się w wór, i wszedł do domu Pańskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'I posłał Elijakima, sprawcę domu swego, i Sobnę pisarza, i starsze z kapłanów, obleczone w wory, do Izajasza proroka, syna Amosowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'Którzy rzekli do niego: Tak mówi Ezechyjasz: Dzień utrapienia i łajania, i bluźnierstwa jest ten dzień; albowiem synowie przyszli aż do porodzenia, a siły niemasz ku rodzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Oby usłyszał Pan, Bóg twój, wszystkie słowa Rabsacesowe, którego przysłał król Assyryjski, pan jego, urągać Bogu żywemu! aby się pomścił onych słów, które słyszał Pan, Bóg twój. Przetoż uczyń modlitwę za te ostatki, które się znajdują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Przyszli tedy słudzy króla Ezechyjasza do Izajasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'Którym odpowiedział Izajasz: Tak powiedzcie panu waszemu: To mówi Pan: Nie bój się tych słów, któreś słyszał, któremi mię lżyli słudzy króla Assyryjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Oto Ja puszczę nań ducha, i usłyszy wieść, a wróci się do ziemi swojej, i położę go mieczem w ziemi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'Ale wróciwszy się Rabsaces znalazł króla Assyryjskiego dobywającego Lebny; albowiem usłyszał, iż odciągnął był od Lachys.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'A usłyszawszy o Tyraku, królu Etyjopskim, że mówino: Oto wyciągnął na wojnę przeciwko tobie, znowu psłał posły do Ezechyjasza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'To powiedzcie królowi Ezechyjaszowi, królowi Judzkiemu, mówiąc: Niech cię nie zwodzi Bóg twój, któremu ty ufasz, a mówisz: Nie będzie podane Jeruzalem w ręce króla Assyryjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Otoś słyszał, co poczynili królowie Assyryjscy wszystkim ziemiom, burząc je; a tybyś miał być wybawiony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Izali wybawili bogowie narodów te, które wygubili ojcowie moi, Gozan, i Haran, i Resef, i syny Eden, którzy byli w Telassar?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Gdzież jest król Emat, i król Arfad, i król miasta Sefarwaim, Ana i Awa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'Przetoż wziąwszy Ezechyjasz list z ręki posłów, przeczytał go, i wszedłszy do domu Pańskiego rozciągnął go Ezechyjasz przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'I modlił się Ezechyjasz przed Panem, mówiąc: Panie, Boże Izraelski, siedzący na Cherubinach! ty, tyś sam jest Bóg wszystkich królestw ziemi, tyś stworzył niebo i ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Nakłońże, Panie! ucha twojego, a usłysz; otwórz, Panie! oczy twoje, a obacz; usłysz słowa Sennacheryba, który przysłał hańbić ciebie, Boga żywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Prawdać jest, Panie! że spustoszyli królowie Assyryjscy narody one, i ziemię ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'I powrzucali bogi ich w ogień; albowiem nie byli bogowie, ale robota rąk ludzkich, drewno, i kamień; przetoż je wygubili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'A teraz, Panie Boże nasz! wybaw nas proszę z ręki jego, aby poznały wszystkie królestwa ziemi, żeś ty, Panie! sam Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Tedy posłał Izajasz, syn Amosowy, do Ezechyjasza, mówiąc: Tak mówi Pan, Bóg Izraelski: O coś mię prosił z strony Sennacheryba, króla Assyryjskiego, wysłuchałem cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'A teć są słowa, które mówił Pan o nim: Panna, córka Syońska, wzgardziła cię, śmiała się z ciebie, kiwała głową za tobą córka Jeruzalemska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Kogożeś hańbił, i kogo bluźnił? przeciwko komużeś podniósł głos, a wyniosłeś ku górze oczy swoje? przeciw Świętemu Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Przez posły twoje hańbiłeś Pana mego, i rzekłeś: W mnóstwie wozów moich wstąpiłem na wysokie góry, i na strony Libańskie, i podrąbię wysokie cedry jego, i wyborne jodły jego, i przyjdę aż do ostatnich przybytków jego, do lasów, i wybornych ról jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Jam wykopał źródła, i piłem wody cudze, a wysuszyłem stopami nóg moich wszystkie potoki oblężonych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'Izażeś nie słyszał, żem ja zdawna uczynił a od dni starodawnych stworzyłem je? a teraz miałżebym na nie przywieść spustoszenie, i obrócić w gromady gruzu; jako insze miasta obronne?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Których obywatele stali się jako bez rąk, przestraszeni są i zawstydzeni, bywszy jako trawa polna, i jako zioła zielone, i trawy po dachach, które pierwej schną, niż się dostają,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'Mieszkanie twoje i wyjście twoje, i wejście twoje znam, także popędliwość twoję przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Ponieważeś się przeciwko mnie zajuszył, a zapędy twoje przyszły do uszów moich, przetoż założę kolce moje za nozdrza twoje, a wędzidło moje wprawię w gębę twoję, i wrócę cię tą drogą, którąś przyszedł,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'A to będziesz miał, Ezechyjaszu! za znak: Tego roku będziesz jadł samorodne zboże, i roku także drugiego samorodne zboże; ale roku trzeciego będziecie siać i żąć, i sadzić winnice i jeść owoc ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'Ostatek bowiem domu Judy, który pozostał, wkorzeni się głęboko, i wyda owoc ku górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Albowiem z Jeruzalemu wynijdą ostatki, i ci, którzy są zachowani z góry Syońskiej. Gorliwość Pana zastępów to uczyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'A przetoż tak mówi Pan o królu Assyryjskim: Nie wnijdzie do miasta tego, ani tam dojdzie strzała jego, ani go ubieży tarcza, ani usypie szańców około niego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Drogą, którą przyszedł, wróci się, a do miasta tego nie wnijdzie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Bo będę bronił miasta tego, i zachowam je sam dla siebie, i dla Dawida, sługi mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'I stało się onej nocy, że wyszedł Anioł Pański, a pobił w obozie Assyryjskim sto ośmdziesiąt i pięć tysięcy. A gdy wstali rano, oto wszędy pełno trupów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Przetoż ruszywszy się odjechał i wrócił się Seneacheryb, król Assyryjski, a mieszkał w Niniwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'A gdy chwalił boga swego Nesrocha w domu, tedy Adramelech i Sarassar, synowie jego, zabili go mieczem, a sami uciekli do ziemi Ararat. I królował Assarhaddon, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'W one dni zachorował Ezechyjasz aż na śmierć, i przyszedł do niego Izajasz prorok, syn Amosowy, i rzekł mu: Tak mówi Pan: Rozpraw dom twój; bo umrzesz, a nie będziesz żył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Tedy obrócił Ezechyjasz twarz swoję do ściany, i modlił się Panu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Proszę, o Panie! wspomnij teraz, żem chodził przed tobą w prwadzie, i w sercu całem, czyniąc to, co dobrego jest w oczach twoich. I płakał Ezechyjasz płaczem wielkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'Ale jeszcze Izajasz nie wyszedł był do pół sieni, gdy się słowo Pańskie stało do niego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Wróć się, a mów do Ezechyjasza, wodza ludu mego: Tak mówi Pan, Bóg Dawida, ojca twego: Wysłuchałem modlitwę twoję, a widziałem łzy twoje; oto Ja uzdrawiam cię, dnia trzeciego wnijdziesz do domu Pańskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'I przydam do dni twoich piętnaście lat, a z ręki króla Assyryjskiego wyrwę ciebie, i to miasto; i bronić będę tego miasta dla siebie, i dla Dawida, sługi mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'Przytem rzekł Izajasz: Przynieście bryłę fig suchych. Którą przyniósłszy włożyli na wrzód, i zgoił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'I rzekł Ezechyjasz do Izajasza: Jaki znak tego, że mię uzdrowi Pan, a iż pójdę dnia trzeciego do domu Pańskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'Odpowiedział Izajasz: Toć będzie znakiem od Pana, iż uczyni Pan tę rzecz, którąć obiecał. Chceszże, żeby cień postąpił na dziesięć stopni, albo żeby się na wstecz nawrócił na dziesięć stopni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'I rzekł Ezechyjasz: Snadniej może cień postąpić na dół na dziesięć stopni, tego nie chcę; ale niech się wróci cień na wstecz na dziesięć stopni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'Tedy wołał Izajasz prorok do Pana; i nawrócił cień po onych stponiach, któremi był postąpił na zegarze słonecznym Achazowym, na wstecz na dziesięć stopni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'Onegoż czasu posłał Berodach Baladan, syn Baladanowy, król Babiloński, list i dary do Ezechyjasza; bo zasłyszał, że był zaniemógł Ezechyjasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'I wysłuchał ich Ezechyjasz i okazał im wszystkie skarbnice klejnotów swoich, srebro, i złoto, i rzeczy wonne, i olejki najwyborniejsze, i dom rynsztunków swoich, i wszystko, co się znajdowało w skarbach jego; nie było nic czego by im nie pokazał Ezechyjasz w domu swym, i we wszystkiem państwie swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Przetoż przyszedł prorok Izajasz do króla Ezechyjasza, i rzekł mu: Coć powiedzieli ci mężowie, a skąd przyszli do ciebie? I odpowiedział Ezechyjasz: Z ziemi dalekiej przyszli z Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'I rzekł: Cóż widzieli w domu twoim? Odpowiedział Ezechyjasz: Wszystko, cokolwiek jest w domu moim, widzieli: nie było nic, czegobym im nie pokazał w skarbach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Ale Izajasz rzekł do Ezechyjasza: Słuchaj słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Oto przyjdą dni, w które zabiorą wszystko do Babilonu, cokolwiek jest w domu twoim, i cokolwiek schowali ojcowie twoi aż do dnia tego; nie zostanie ci nic, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Ale i syny twoje, którzy wynijdą z ciebie, i które spłodzisz, pobiorą, i będą komornikami na dworze króla Babilońskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'Tedy rzekł Ezechyjasz do Izajasza: Dobre jest słowo Pańskie, któreś mówił. Nadto rzekł: Zaiste dobre, jeźli tylko pokój i prawda będzie za dni moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'Ale inne sprawy Ezechyjaszowe, i wszystka moc jego, i jako uczynił sadzawkę, i rury, którymi przywiódł wodę do miasta to zapisano w kronikach o królach Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'I zasnął Ezechyjasz z ojcami swymi, a królował Manases, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'We dwunastym roku był Manases, gdy królować począł, a pięćdziesiąt i pięć lat królował w Jeruzalemie; a imię matki jego było Hadsyba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'I czynił złe przed oczyma Pańskiemi według obrzydłości tych narodów, które wygnał Pan przed obliczem synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Albowiem znowu pobudował wyżyny, które był poburzył Ezechyjasz, ojciec jego, i wystawił ołtarze Baalowi, i nasadził gaj jako był uczynił Achab, król Izraelski, i kłaniał się wszystkiemu wojsku niebieskiemu, i służył mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'Pobudował też ołtarze w domu Pańskim, o którym powiedział był Pan: W Jeruzalemie położę imię moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Nadto nabudował ołtarzy wszystkiemu wojsku niebieskiemu w obu sieniach domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'Syna także swego przewiódł przez ogień, i przestrzegał czasów, i bawił się wieszczbą, i ustawił czarnoksiężniki, i guślarze, a bardzo wiele złego czynił przed oczyma Pańskiemi, draźniąc go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Postawił także bałwana gajowego, którego był uczynił w domu, o którym był rzekł Pan do Dawida i do Salomona, syna jego: W domu tym i w Jeruzalemie, którem obrał ze wszystkiego pokolenia Izraelskiego, położę imię moje na wieki:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'A więcej się nie dopuszczę ruszyć nodze Izraela z ziemi, którąm dał ojcom ich, by jedno skutecznie strzegli wszystkiego, com im rozkazał, i wszystkiego zakonu, który im przykazał sługa mój Mojżesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Ale nie słuchali; bo je zwiódł Manases, tak iż się gorzej sprawowali niż narody, które wygładził Pan przed obliczem synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Aczkolwiek powiedział był Pan przez sługi swoje proroki, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Przeto, że czynił Manases, król Judzki, te obrzydliwości, czyniąc gorsze rzeczy nad one wszystkie, które czynili Amorejczycy, którzy byli przed nim, a że przywiódł w grzech i Judę przez brzydkie bałwany swoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'Przetoż tak mówi Pan, Bóg Izraelski: Oto Ja przywiodę złe na Jeruzalem i na Judę, tak iż każdemu, co to usłyszy, zabrzmi w obu uszach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'Bo rozciągnę nad Jeruzalem sznur Samaryjski, i wagę domu Achabowego, a wytrę Jeruzalem, jako kto wyciera misę, a wytarłszy przewraca ją dnem ku górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'I opuszczę ostatki dziedzictwa mego, a podam je w rękę nieprzyjaciół ich; i będą na łup, i na rozproszenie wszystkim nieprzyjaciołom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'Przeto, iż się dopuszczali złego przed oczyma memi, a draźnili mię ode dnia, którego wyszli ojcowie ich z Egiptu, aż do dzisiejszego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'Nadto i krwi niewinnej Manases wylał bardzo wiele, tak iż nią napełnił Jeruzalem od końca do końca, oprócz grzechu swego, przez który przywiódł do grzechu Judę, aby czynił złe przed oczyma Pańskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'A inne sprawy Manasesowe, i wszystko co czynił, i grzech jego, którego się dopuścił, to zapisano w kronikach o królach Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'I zasnął Manases z ojcami swymi, i pogrzebiony jest w ogrodzie domu swego, w ogrodzie Ozy; a królował Amon, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Dwadzieścia i dwa lata miał Amon, gdy królować począł, a dwa lata królował w Jeruzalemie. A imię matki jego było Masallemet, córka Harusa z Jateby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'I czynił złe przed oczyma Pańskiemi, jako czynił Manases, ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'A chodził wszystkimi drogami, któremi chodził ojciec jego, służąc brzydkim bałwanom, którym służył ojciec jego, i kłaniał się im;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'I opuścił Pana, Boga ojców swoich, a nie chodził drogą Pańską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'Ale się sprzysięgli słudzy Amonowi przeciwko niemu, i zabili króla w domu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'Tedy pobił lud onej ziemi wszystkie, którzy się byli sprzysięgli przeciwko królowi Amonowi; i postanowił lud onej ziemi królem Jozyjasza, syna jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Ale inne sprawy Amonowe, które czynił, opisane są w kronikach o królach Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'I pochowano go w grobie jego w ogrodzie Ozy; a królował Jozyjasz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Ośm lat było Jozyjaszowi, gdy począł królować, a trzydzieści jeden lat królował w Jeruzalemie; a imię matki jego było Jedyda, córka Adaja z Besekatu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'I czynił, co było dobrego przed oczyma Pańskiemi, chodząc wszystkimi drogami Dawida, ojca swego, a nie uchylał się ani na prawo ani na lewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'A ośmnastego roku króla Jozyjasza posłał król Safana, syna Azalijaszowego, syna Mesulama, pisarza, do domu Pańskiego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Idź do Helkijasza, kapłana najwyższego, aby zebrał pieniądze, które wnoszono do domu Pańskiego, które wybierali stróżowie progu od ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'A niech je dawają w ręce rzemieślników, przełożonych nad robotą domu Pańskiego, aby je dawali robotnikom, którzy robili w domu Pańskim, naprawiając skazę domu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'To jest, budownikom i cieślom, i murarzom, i na zkupowanie drzewa, i kamienia ciosanego ku naprawie domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'Wszakże niech nie czynią liczby z pieniędzy, które dawają do rąk ich; bo oni wiernie nimi szafować będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'I rzekł Helkijasz, kapłan najwyższy, do Safana pisarza. Księgi zakonu znalazłem w domu Pańskim. I dał Helkijasz one księgi Safanowi, i czytał je (Safan).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'Przyszedłszy tedy Safan pisarz do króla, odniósł to królowi, i rzekł: Zebrali słudzy twoi pieniądze, które się znalazły w domu Pańskim, i oddali je w ręce rzemieślników przełożonych nad robotą w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Oznajmił też Safan pisarz królowi, mówiąc: Dał mi księgę Helkijasz kapłan; i czytał ją Safan przed królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'A gdy usłyszał król słowa ksiąg zakonu, rozdarł szaty swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'I rozkazał król Helkijaszowi kapłanowi, i Ahykamowi, synowi Safanowemu, i Achborowi, synowi Micheaszowemu, i Safanowi pisarzowi, i Asajaszowi, słudze swemu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Idźcie, poradźcie się Pana o mię, i o lud, i o wszystkiego Judę z strony słów tych ksiąg, które są znalezione; bo wielki jest gniew Pański, który się zapalił przeciwko nam, przeto iż nie posłuchali ojcowie nasi słów tych ksiąg, żeby czynili według wszystkiego, co nam jest napisane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'A tak poszedł Helkijasz kapłan, i Ahykam, i Achbor, i Safan, i Azajasz, do Huldy prorokini, żony Selluma, syna Tekui, syna Araaszowego, który był stróżem szat; a ona mieszkała w Jeruzalemie na drugiej stronie miasta; i mówili z nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Która rzekła do nich: Tak mówi Pan, Bóg Izraelski. Powiedzcie mężowi, który was posłał do mnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Tak mówi Pan: Oto Ja przywiodę złe na to miejsce i na obywateli jego według wszystkich słów ksiąg tych, które czytał król Judzki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'Przeto, że mię opuścili, i kadzili bogom cudzym, aby mię draźnili wszystkiemi sprawami rąk swoich, dla czego rozpaliła się popędliwość moja przeciwko miejscu temu, i nie będzie ugaszona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'A królowi Judzkiemu, który was posłał o radę do Pana, tak powiedzcie: Tak mówi Pan, Bóg Izraelski, o słowach, któreś słyszał:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Ponieważ zmiękczone jest serce twoje, a upokorzyłeś się przed obliczem Pańskiem, słysząc, com powiedział przeciwko temu miejscu, i przeciwko obywatelom jego, iż ma przyjść w spustoszenie i w przeklęstwo; rozdarłeś szaty swe, a płakałeś przedemną, i Jam cię też wysłuchał, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Przetoż oto Ja cię zbiorę do ojców twoich, a będziesz zebrany do grobu twego w pokoju, aby nie oglądały oczy twoje wszystkiego złego, które Ja przywiodę na to miejsce. I odniesiono tę rzecz królowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Tedy posławszy król, aby się zebrali do niego wszyscy starsi Judzcy i Jeruzalemscy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'Wstąpił król do domu Pańskiego, i wszyscy mężowie Judzcy,i wszyscy obywatele Jeruzalemscy z nim, i kapłani, i prorocy, i wszystek lud od małego aż do wielkiego; i czytał, gdzie wszyscy słyszeli wszystkie słowa ksiąg przymierza, które były znalezione w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'Potem stanął król na majestacie, i uczynił przymierze przed Panem, że chce chodzić za Panem, i strzedz rozkazania jego, i świadectw jego, i wyroków jego ze wszystkiego serca, i ze wszystkiej duszy, i pełnić słowa przymierza tego, które były napisa ne w onych księgach. I przestał lud na onem przymierzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'I przykazał król Helkijaszowi, kapłanowi najwyższemu, i kapłanom wtórego rzędu, i odźwiernym, aby wyrzucili z kościoła Pańskiego wszystko naczynie, które sprawione było Baalowi, i gajowi poświęconemu, i wszystkiemu wojsku niebieskiemu, i spalił je precz za Jeruzalemem na polu Cedron, a zaniósł popiół ich do Betela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'Złożył też z urzędu popów, których byli postanowili królowie Judzcy, aby kadzili po wyżynach w miastach Judzkich i około Jeruzalemu; przytem i onych, którzy kadzili Baalowi, słońcu i miesiącowi, i planetom, i wszystkiemu wojsku niebieskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Kazał też wynieść gaj święcony z domu Pańskiego precz z Jeruzalemu ku potokowi Cedron, a spalił go u potoku Cedron, i starł go w proch, a popiół jego rozmiotał na groby synów onegoż ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'Zburzył też domy Sodomczyków, które były w domu Pańskim, kędy niewiasty tkały opony do gaju poświęconego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'I zawołał wszystkich kapłanów z miast Judzkich, a splugawił wyżyny, na których kadzili, od Gabaa aż do Beerseba, i popsuł wyżyny przy bramach, które były w wejściu bramy Jozuego książęcia miasta, a było po lewej stronie wchodzącemu w bramę miejską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Wszakże nie przystępowali kapłani wyżyn do ołtarza Pańskiego w Jeruzalemie, ale jadali chleby przaśne między braćmi swoimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'Splugawił też i Tofet, które było w dolinie syna Hennomowego, aby więcej nikt nie przewodził syna swego, ani córki swojej przez ogień ku czci Molochowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Zagubił też one konie, które byli królowie Judzcy oddali słońcu, a stały, kędy wchodzą do domu Pańskiego, podle mieszkania Natanmelecha dworzanina, które było na przedmieściu; i wozy słońca spalił ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Także ołtarze, które były na dachu sali Achazowej, które byli poczynili królowie Judzcy, i ołtarze, które był poczynił Manases w obu sieniach domu Pańskiego, pokaził król; a pospieszywszy się stamtąd kazał wrzucić proch ich w potok Cedron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'Wyżyny także, które były przed Jeruzalem, i które były po prawej stronie góry Oliwnej, których był nabudował Salomon, król Izraelski, Astarotowi, obrzydłości Sydończyków, i Chamosowi, obrzydłości Moabczyków, i Melchomowi, obrzydłości synów Amm onowych, splugawił król.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'I pokruszył słupy, a powycinał gaje, i napełnił miejsca ich kościami ludzkiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Nadto i ołtarz, który był w Betel, i wyżynę, którą był uczynił Jeroboam, syn Nabatowy, który przywiódł do grzechu lud Izraelski, i ten ołtarz, i wyżynę zepsuł, a spaliwszy onę wyżynę, starł na proch, i spalił gaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'A obróciwszy się Jozyjasz, obaczył groby, które tam były na górze, a posławszy pobrał kości z onych grobów, i popalił je na tymże ołtarzu; a tak go splugawił według słowa Pańskiego, które mówił mąż Boży, który był te rzeczy przepowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'I rzekł: Cóż to jest za napis, który widzę? I odpowiedzieli mu mężowie miasta: Grób to męża Bożego, który przyszedłszy z Judy opowiedział te rzeczy, któreś uczynił nad ołtarzem w Betel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'A on rzekł: Zaniechajcie go, niechaj nikt nie rucha kości jego. I wybawili kości jego, i kości proroka onego, który był przyszedł z Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Wszystkie też domy wyżyn, które były w miastach Samaryjskich, które byÜi pobudowali królowie Judzcy, draźniąc Pana, zniósł Jozyjasz, i uczynił im według wszystkiego, jako był uczynił w Betel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'Pozabijał także wszystkich kapłanów wyżyn, którzy tam byli na ołtarzach, i palił kości ludzkie na nich, potem się wrócił do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Rozkazał też król wszystkiemu ludowi, mówiąc: Obchodźcie święto przejścia Panu, Bogu waszemu, jako napisano w księgach przymierza tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Bo nie obchodzono takiego święta przejścia ode dni sędziów, którzy sądzili Izraela, i przez wszystkie dni królów Izraelskich, i królów Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'Jako ośmnastego roku króla Jozyjasza, obchodzono takie święto przejścia Panu w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Ale i wieszczków, i czarowników, i obrazy, i brzydkie bałwany, i wszystkie obrzydłości, co ich było widać w ziemi Judzkiej i w Jeruzalemie, wykorzenił Jozyjasz, aby wypełnił słowa zakonu napisane w księgach, które znalazł Helkijasz kapłan w dom u Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'I nie był podobny jemu król przed nim, któryby się nawrócił do Pana z całego serca swego, i ze wszystkiej duszy swojej, i ze wszystkiej siły swojej, według wszystkiego zakonu Mojżeszowego, ani po nim powstał jemu podobny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Wszakże nie odwrócił się Pan od popędliwości wielkiego gniewu swego, którą był wzruszony gniew jego przeciw Judzie dla wszelkiego rozdraźnienia, którem go był rozdraźnił Manases.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'Przetoż rzekł Pan: I Judę odrzucę od obliczności mojej, jakom odrzucił Izraela, i wzgardzę to miasto, którem był obrał, to jest Jeruzalem, i dom ten, o którymem mówił: Będzie tam imię moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'A inne sprawy Jozyjaszowe, i wszystko, co czynił, opisane jest w kronikach o królach Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'Za dni jego wyciągnął Farao Necho, król Egipski, przeciw królowi Assyryjskiemu ku rzece Eufrates; wyjechał też król Jozyjasz przeciwko niemu, którego on zabił w Megiddo, gdy go ujrzał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'I przywieźli go słudzy jego umarłego z Megiddo, a przyprowadzili go do Jeruzalemu, i pogrzebli go w grobie jego. Potem wziąwszy lud onej ziemi Joachaza, syna Jozyjaszowego, pomazali go, i królem go postanowili miasto ojca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Dwadzieścia lat i trzy miał Joachaz, gdy królować począł, a trzy miesiące królował w Jeruzalemie. A imię matki jego było Chamutal, córka Jeremijaszowa z Lebny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'I czynił złe przed oczyma Pańskiemi według wszystkiego, co czynili ojcowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'I związał go Farao Necho w Rebli w ziemi Emat, gdy królował w Jeruzalemie, a ułożył dań na onę ziemię sto talentów srebra, i talent złota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'A królem postanowił Farao Necho Elijakima, syna Jozyjaszowego, miasto Jozyjasza, ojca jego, i odmienił imię jego, a nazwał go Joakim; ale Joachaza wziął, który, gdy przyszedł do Egiptu, tamże umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'A to srebro i złoto dawał Joakim Faraonowi; przetoż szacował ziemię, aby mógł oddawać srebro według rozkazania Faraonowego; od każdego według szacunku jego, brał srebro i złoto od ludu ziemi, aby je oddawał Faraonowi Nechowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Dwadzieścia i pięć lat miał Joakim, gdy królować począł, a jedenaście lat królował w Jeruzalemie. A imię matki jego było Zebuda, córka Fadajowa z Rumy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'I czynił złe przed oczyma Pańskiemi według wszystkiego, jako czynili ojcowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'Za dni jego wyciągnął Nabuchodonozor, król Babiloński. I stał się Joakim niewolnikiem jego przez trzy lata, a potem wybił się z mocy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'Przetoż posłał Pan przeciwko niemu wojska Chaldejskie, i wojsko Syryjskie, i wojska Moabskie, i wojska synów Ammonowych; i posłał je na Judę, aby go wytracili według słowa Pańskiego, które był powiedział przez sługi swe proroki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Zaiste stało się to podług słowa Pańskiego przeciwko Judzie, aby go odrzucił od oblicza swego dla grzechów Manasesowych, według wszystkiego, co był uczynił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'I dla krwi niewinnej, którą wylewał, i napełnił Jeruzalem krwią niewinną, czego mu nie chciał Pan odpuścić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'A inne sprawy Joakimowe, i wszystko co czynił, zapisane w kronikach o królach Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'A tak zasnął Joakim z ojcami swymi, a królował Joachyn, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'Ale nie ruszał się więcej król Egipski z ziemi swej. Bo był wziął król Babiloński wszystko od rzeki Egipskiej aż do rzeki Eufrates, co przynależało królowi Egipskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Ośmnaście lat miał Joachyn, gdy królować począł, a trzy miesiące królował w Jeruzalemie. Imię matki jego było Nehusta, córka Elnatanowa z Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'I czynił złe przed oczyma Pańskiemi, według wszystkiego, jako czynił ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'Czasu onego przyciągnęli słudzy Nabuchodonozora, króla Babilońskiego, przeciwko Jeruzalemowi, i przyszło miasto w oblężenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'Przyciągnął też Nabuchodonozor, król Babiloński, przeciwko miastu, gdy słudzy jego leżeli około niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Tedy wyszedł Joachyn, król Judzki, do króla Babilońskiego, on i matka jego, i słudzy jego, i książęta jego, i dworzanie jego, i wziął go król Babiloński roku ósmego królowania swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'I wyniósł stamtąd wszystkie skarby domu Pańskiego, i skarby domu królewskiego, i potłukł wszystkie naczynia złote, które był sprawił Salomon, król Izraelski, w kościele Pańskim, jako był powiedział Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'I przeniósł wszystko Jeruzalem, i wszystkich książąt, i wszystek lud rycerski, więźniów dziesięć tysięcy, i wszystkich cieśli, i kowali, a nie został tam nikt, oprócz ubogiego ludu onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'Przeniósł i Joachyna do Babilonu, i matkę królewską, i żony królewskie, i dworzan jego, i rycerski lud onej ziemi zawiódł w niewolę z Jeruzalemu do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'Wszystkich też mężów walecznych siedm tysięcy, i cieśli, także i kowali tysiąc, i wszystkich godnych ku bojowi, tych zawiódł w niewolę król Babiloński do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'A królem postanowił król Babiloński króla Matanijasza, stryja jego, miasto niego, i odmienił mu imię, a nazwał go Sedekijasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Dwadzieścia i jeden lat miał Sedekijasz, gdy królować począł, a jedenaście lat królował w Jeruzalemie; a imię matki jego było Chamutal, córka Jermijaszowa z Lebny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'I czynił złe przed oczyma pańskiemi według wszystkiego, jako czynił Joakim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Albowiem się to stało dla rozgniewania Pańskiego przeciwko Jeruzalemowi i Judzie, aż je odrzucił od twarzy swojej. Wtem zasię odstąpił Sedekijasz od króla Babilońskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'I stało się roku dziewiątego królowania jego, miesiąca dziesiątego, dnia dziesiątego tegoż miesiąca, że przyciągnął Nabuchodonozor, król Babiloński, on i wszystko wojsko jego przeciw Jeruzalemowi, i położył się obozem u niego, a porobił przeciwko niemu szańce w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'A tak oblężone było miasto aż do jedenastego roku króla Sedekijasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Tedy dnia dziewiątego czwartego miesiąca był wielki głód w mieście, a nie miał chleba lud ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'I przełamano mur miejski, a wszyscy ludzie rycerscy uciekli w nocy drogą, kędy idą do bramy, która jest między dwoma murami, które były podle ogrodu królewskiego; a Chaldejczycy leżeli około miasta, a król uszedł drogą do pustyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'I goniło wojsko Chaldejskie króla, i pojmało go na polach Jerycho; a wszystko wojsko jego rozpierzchnęło się od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'A tak pojmawszy króla przywiedli go do króla Babilońskiego do Rebli, kędy o nim uczynili sąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'A synów Sedekijaszowych pozabijali przed oczyma jego; potem Sedekijasza oślepiwszy związali go łańcuchami miedzianemi, i zawiedli go do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Potem miesiąca piątego, siódmego dnia tegoż miesiąca, (ten jest rok dziewiętnasty królowania Nabuchodonozora, króla Babilońskiego) przyciągnął Nabuzardan, hetman żołnierski, sługa króla Babilońskiego, do Jeruzalemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'I spalił do Pański, i dom królewski, i wszystkie domy w Jeruzalemie, owa wszystko budowanie kosztowne popalił ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'Mury także Jeruzalemskie w około rozwaliło wszystko wojsko Chaldejskie, które było z onym hetmanem żołnierskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'A ostatek ludu, który był został w mieście, i zbiegi, którzy byli zbiegli do króla Babilońskiego, i inne pospólstwo, przeniósł Nabuzardan, hetman żołnierski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Tylko z ubogich onej ziemi zostawił hetman żołnierski, aby byli winiarzami i oraczami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'Nadto słupy miedziane, które były w domu Pańskim, i podstawki, i morze miedziane, które było w domu Pańskim, potłukli Chaldejczycy, i przenieśli wszystkę miedź do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Kotły też i łopaty, i naczynia muzyczne, i misy i wszystko naczynie miedziane, którem usługiwano; pobrali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'I kadzielnice, i miednice, i co było złotego w złocie, i co było srebrnego w srebrze, pobrał hetman żołnierski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Słupy dwa, morze jedno, i podstawki, które był sprawił Salomon w domu Pańskim, a nie było wagi miedzi onego wszystkiego naczynia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Ośmnaście łokci wzwyż było słupa jednego, a gałka na nim miedziana; a gałka miała na wzwyż trzy łokcie, a siatka i jabłka granatowe na gałce w około, wszystko miedziane. Takiż też był i drugi słup z siatką,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'Wziął też hetman żołnierski Sarajego, kapłana przedniego, i Sofonijasza, kapłana wtórego, i trzech odźwiernych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'Wziął też z miasta dworzanina jednego, który był przełożony nad ludem, rycerskim, i pięć mężów z tych, którzy stawali przed królem, którzy byli znalezieni w mieście, i pisarza przedniego wojskowego, który spisywał lud onej ziemi, i sześćdziesiąt mężów ludu z onej ziemi, którzy się znależli w mieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'Pojmawszy ich tedy Nabuzardan, hetman żołnierski, zawiódł ich do króla Babilońskiego do Ryblaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'I pobił ich król Babiloński, a pomordował ich w Ryblacie w ziemi Emat; a tak przeniesiony jest Juda z ziemi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Ale nad ludem, który jeszcze był został w ziemi Judzkiej, którego był zostawił Nabuchodonozor, król Babiloński, przełożył Godolijasza, syna Ahykamowego, syna Safanowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'A gdy usłyszeli wszyscy hetmani wojska, sami i mężowie ich, że przełożył król Babiloński Godolijasza, tedy przyszli do Godolijasza do Masfy; mianowicie, Izmael, syn Natanijaszowy, i Johanan, syn Kareaszowy, i Serajasz, syn Tanhumeta Netofatczyk a, i Jezonijasz, syn Maachatowy sami i mężowie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'Którym przysiągł Godolijasz, i mężom ich, i rzekł im: Nie bójcie się być poddanymi Chaldejczykom; zostańcie w ziemi, a służcie królowi Babilońskiemu, i będzie wam dobrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'I stało się miesiąca siódmego, że przyszedł Izmael, syn Natanijasza, syna Elisamowego, z nasienia królewskiego, i dziesięć mężów z nim, i zabili Godolijasza, i umarł; także Żydów i Chaldejczyków, którzy z nim byli w Masfa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'Tedy powstał wszystek lud od małego aż do wielkiego, i hetmani wojsk, a poszli do Egiptu; bo się bali Chaldejczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Stało się także trzydziestego i siódmego roku pojmania Joachyna, króla Judzkiego, dwunastego miesiąca dnia dwudziestego siódmego tegoż miesiąca, że wywyższył Ewilmerodach, król Babiloński, tegoż roku, gdy począł królować, głowę Joachyna, króla Judzkiego, uwolniwszy go z więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'I rozmawiał z nim łaskawie, a wystawił stolicę jego nad stolicę innych królów, którzy z nim byli w Babilonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'Odmienił też odzienie jego, w którem był w więzieniu, i jadł chleb zawsze przed obliczem jego po wszystkie dni żywota swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Obrok też jemu naznaczony ustawicznie mu dawano od króla, na każdy dzień po wszystkie dni żywota jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Set, Enos.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kienan, Mahalaleel, Jared.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Eonch, Matusalem, Lamech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noe, Sem, Cham, i Jafet.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Synowie Jafetowi: Gomer, i Magog, i Madaj, i Jawan, i Tubal, i Mesech, i Tyras,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'A synowie Gomerowi: Aschenaz, i Ryfat, i Togorma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'Synowie też Jawanowi: Elisa, i Tarsys, Cytym, i Dodanin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Synowie Chamowi: Chus i Misraim, Put i Chanaan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'A synowie Chusowi: Seba, i Hewila, i Sabta, i Regma, i Sabtacha; a synowie Regmy: Seba i Dedan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'Spłodził też Chus Neroda; ten począł być możnym na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Misraim też spłodził Ludyma, i Hananima, i Laubima, i Naftuhyma,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'I Patrusyma, i Chasłuchyma, (z których poszli Filistynowie) i Kaftoryma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Potem Chanaan spłodził Sydona, pierworodnego swego, i Hetejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'I Jebuzejczyka, i Amorejczyka, i Giergiezejczyka,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'I Hewejczyka, i Archajczyka, i Symejczyka,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'I Aradejczyka, i Samarejczyka, i Chamatejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Synowie Semowi: Elam, i Assur, i Arfachsad, i Lud, i Aram, i Chus, i Hul, i Gieter, i Mesech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'A Arfachsad spłodził Selecha, a Selech spłodził Hebera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'A Heberowi urodzili się dwaj synowie, z których jednemu imię było Faleg, przeto, że za jego czasów rozdzielona jest ziemia; a imię brata jego Jektan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'A Jektan spłodził Elmodada, i Salefa, i Hassarmota, i Jarecha,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'I Adorama, i Uzala, i Dekla,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'I Hebala, i Abimaela, i Sebaja,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'I Ofira, i Hewila, i Jobaba. Ci wszyscy byli synowie Jektanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arfachsad, Selech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Heber, Peleg, Rechu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Sarug, Nachor, Tare,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram; ten jest Abraham.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Synowie Abrahamowi: Izaak i Ismael.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'A teć są rodzaje ich: Pierworodny Ismaelowy Nebajot, i Kiedar, i Abdeel, i Mabsam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Masma, i Duma, Massa, Hadad, i Tema,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Nafis i Kiedma. Cić są synowie Ismaelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'A synowie Cetury, założnicy Abrahamowej, których porodziła: Zamram i Joksan, i Madan, i Midyjan, i Jesbok, i Suach. A synowie Joksanowi; Saba i Dedan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'Synowie też Madyjanowi: Hefa, i Hefer, i Henoch, i Abida, i Eldaa. Cić wszyscy są synowie Cetury.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'I spłodził Abraham Izaaka. A synowie Izaakowi byli: Ezaw i Izrael.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'A synowie Ezawowi: Elifas, Rehuel, i Jehus, i Jelom, i Kore.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Synowie Elifasowi: Teman i Omar, Sefo i Gaatan, Kienaz i syn Tamny, to jest, Amalek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Synowie Rehuelowi: Nahat, Zara, Samma, i Meza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'A synowie Seirowi: Lotan, i Sobal, i Sebeon, i Hana, i Dysson, i Eser, i Dysan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'A synowie Lotanowi: Chory, i Heman; a siostra Lotanowa była Tamna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Synowie Sobalowi: Halman, i Manaat, i Hewal, Sefo, i Onam; a synowie Sebeonowi: Ajai Ana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Synowie Ana: Dyson; a synowie Dysona: Hamdan, i Eseban, i Jetran, i Charan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Synowie Eserowi: Balaan, i Zawan, Akan. Synowie Dysanowi: Hus i Aran.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'Cić są królowie, którzy królowali w ziemi Edomskiej, przedtem niż królował król nad synami Izraelskimi: Bela, syn Beorowy, a imię miasta jego Dynhaba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'A gdy umarł Bela, królował miasto niego Jobab, syn Zerachowy z Bosry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'A gdy umarł Jobab, królował miasto niego Chusam z ziemi Temańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'A gdy umarł Chusam, królował miasto niego Hadad, syn Badadowy, który poraził Madyjańczyków na polu Moabskiem; a imię miasta jego Hawid.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'A gdy umarł Hadad, królował miasto niego Samla z Masreki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'A gdy umarł Samla, królował miasto niego Saul z Rechobot nad rzeką');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'A gdy umarł Saul, królował miasto niego Balanan, syn Achoborowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'A gdy umarł Balanan, królował miasto niego Hadar; a imię miasta jego Pehu, imię też żony jego Mehetabel, córka Matredy, córki Mezaabowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'A gdy umarł Hadar, byli książętami w Edon: książę Tamna, książę Halwa, książę Jetet,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'Książę Oolibama, książę Ela, książę Pinon,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'Książę Kienaz, książę Teman, książę Mabsar,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'Książę Magdyjel, książę Hyram. Toć byli książęta Edomscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Cić są synowie Izraelowi: Ruben, Symeon, Lewi, i Juda, Isaschar i Zabulon,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Józef, i Benjamin, Neftali, Gad i Aser.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Synowie Judy: Her, i Onan, i Sela. Ci trzej urodzili mu się z córki Sui Chananejskiej. Ale Her, pierworodny Judy, był złym przed oczyma Pańskiemi; przetoż go zabił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'Tamar zasię, niewiastka jego, urodziła mu Faresa i Zarę. Wszystkich synów Judowych pięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Synowie Faresowi: Hesron i Hamuel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'Synowie zaś Zary: Zamry, i Etan, i Heman, i Chalkol, i Darda; wszystkich tych było pięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'Asynowie Zamrego: Charmi, wnuk Acharowy, który zamięszanie uczynił w Izraelu, zgrzeszywszy kradzieżą rzeczy przeklętych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'Asynowie Etanowi: Azaryjasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'A synowie Esronowi, którzy mu się urodzili: Jerameel, i Ram, i Chalubaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'Ale Ram spłodził Aminadaba, a Aminadab spłodził Naasona, książęcia synów Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'A Naason spłodził Salmona, a Salmon spłodził Booza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'A Booz spłodził Obeda, a Obed spłodził Isajego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'A Isaj spłodził pierworodnego swego Elijaba, i Abinadaba wtórego, i Samma trzeciego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Natanaela czwartego, Raddaja piątego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Ozema szóstego, Dawida siódmego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'A siostry ich: Sareija, i Abigail; a synowie Sarwii: Abisaj, i Joab, i Asael, trzej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'A Abigail urodziła Amazę, a ojciec Amazy był Jeter Ismaelczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'A Kaleb, syn Hesronowy, spłodził z Azubą, małżonką swoją, i z Jeryjotą synów. A ci byli synowie jego: Jeser, i Sobab, i Ardon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'A gdy umarła Azuba, pojął sobie Kaleb Esratę, która mu urodziła Hura.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'A Hur spłodził Ury, a Ury spłodził Besaleela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Potem wszedł Hesron do córki Machyra, ojca Galaadowego, a pojął ją, będąc w sześćdizesiąt lat; która mu urodziła Seguba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'A Segub spłodził Jaira, który miał dwadzieścia trzy miast w ziemi Galaadskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'Bo wziął Giessurytom, i Assyryjczykom wsi Jairowe, i Kanat z miasteczkami jego, sześćdziesiąt miast. To wszystko pobrali synowie Machyra, ojca Galaadowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'A gdy umarł Hesron w Kaleb Efrata, tedy żona Hesronowa Abija porodziła mu Assura, ojca Tekui.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'Byli też synowie Jerameelowi, pierworodnego Hesronowego: Pierworodny Ram, po nim Buana, i Oren, i Osem z Abii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'Miał także drugą żonę Jerameel, imieniem Atara; ta jest matka Onamowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'Ale synowie Ramowi, pierworodnego Jerameelowego, byli: Maas, i Jamin, i Achar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'Byli też synowie Onamowi: Semaj, i Jada, a synowie Semejego: Nadad i Abisur;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'A imię żony Abisurowej Abihail, która mu urodziła Achobbana i Molida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'Synowie Nadabowi: Saled i Affaim; lecz Saled umarł bez potomstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'A synowie Affaimowi Jesy; a synowie Jesy Sesan, a córka Sesana Achialaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'A synowie Jady, brata Semejego, Jeter i Jonatan; ale Jeter umarł bez potomstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'A synowie Jonatanowi: Falet i Zyza. Cić byli synowie Jerameelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Lecz nie miał Sesan synów, jedno córki; miał też Sesan sługę Egipczanina, imieniem Jeracha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'I dał Sesan córkę Jerachowi, słudze swemu, za żonę, która mu urodziła Etaja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'Etaj spłodził Natana, a Natan spłodził Zabada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'A Zabad spłodził Efijala, a Efijal spłodził Obeda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'A obed spłodził Jehu, a Jehu spłodził Azaryjasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'A Azaryjasz spłodził Helesa, a Heles spłodził Elasa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'A Elas spłodził Sysmaja, a Sysmaj spłodził Selluma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'A Sellum spłodził Ikamijasza, a Ikamijasz spłodził Elisama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'A synowie Kaleba, brata Jerameelowego: Mesa pierworodny jego, który był ojcem Zyfejczyków i synów Maresy, ojca Hebrowowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'A synowie Hebronowi: Kore i Tafua, i Rechem, i Semma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'A Semma spłodził Rahama, syna Jerkaamowego, a Rechem spłodził Sammajego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'A Sammaj był synem Maonowym, a Maon był ojcem Betsurczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'Efa też, założnica Kalebowa, urodziła Harana, i Moze, i Giezeza; a Haran spłodził Giezeza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'A synowie Jachdajowi: Regiem, i Jotam, i Giesan, i Falet, i Efa, i Saaf,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Założnica zaś druga Kalebowa Maacha urodziła Sabera, i Tyrchana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'A żona Saafowa urodziła ojca Madmeńczyków, i Sewa, ojca Machbeńczyków, i ojca Gabaończyków; a córka Kalebowa była Achsa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Cić byli synowie Kaleba, syna Hurowego, pierworodnego Efraty: Sobal, ojciec Karyjatyjarymczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, ojciec Betlehemczyków, Charef, ojciec Betgaderczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Miał też synów Sobal, ojciec Karyjatyjarymczyków, który doglądał połowy Menuchoty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'A domy Karyjatyjarymskie były Jetrejczycy, i Futejczycy, i Sematejczycy, i Maserejczycy, z których też poszli Saraitowie, o Estaolitowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'A synowie Salmy: Betlehemczycy, i Netofatczycy, ozdoby domu Joabowego, i połowa Manachaty, ojca Sorygo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'A domy pisarzów mieszkających w Jabez: Tyryjatejczycy, Symatejczycy, Suchatejczycy. Cić są Cynejczycy, którzy poszli z Hemata, ojca domu Rechabowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Cić są synowie Dawidowi, którzy mu się urodzili w Hebronie: Pierworodny Ammon z Achynoamy Jezreelitki; wtóry Danijel z Abigaili Karmelitki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'Trzeci Absalom, syn Maachy, córki Tolmaja, króla Giessur; czwarty Adonijasz, syn Haggity;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'Piąty Sefatyjasz z Abitaili; szósty Jetraam z Egli, żony jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Tych sześć urodziło mu się w Hebronie, kędy królował przez siedm lat, i przez sześć miesięcy; a trzydzieści i trzy lata królował w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'A ci urodzili mu się w Jeruzalemie; Samna, i Sobab, i Natan, i Salomon, cztery synowie z Betsui, córki Ammielowej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'I Ibchar, i Elisama, i Elifet;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'I Noge, i Nefeg, i Jafija;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'I Elizama, i Elijada, i Elifelet, dziewięć synów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'A cić wszyscy są synowie Dawidowi, oprócz synów z założnic; a Tamar była siostra ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Syn Salomonowy Roboam; Abiam syn jego, Aza syn jego, Jozafat syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'Joram syn jego, Ochozyjasz syn jego, Joaz syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'Amazyjasz syn jego, Azaryjasz syn jego, Joatam syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'Achaz syn jego, Ezechyjasz syn jego, Manases syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'Amon syn jego, Jozyjasz syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'A synowie Jozyjaszowi: Pierworodny Johanan, wtóry Joakim, trzeci Sedekijasz, czwarty Sellum.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'A synowie Joakimowi: Jechonijasz syn jego, Sedekijasz syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'A synowie Jechonijasza więźnia: Salatyjel syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'A salatyjelowi: Malchiram, i Fadajasz, i Seneser, Jekiemija, Hosama, i Nadabija.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'A synowie Fadajaszowi: Zorobabel, i Semej; a syn Zorobabelowy Mesollam, i Hananijasz, i Selomit, siostra ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'A Mesollamowi: Hasuba, i Ohol, i Barachyjasz, i Hazadyjasz Josabchesed, pięć synów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'A syn Hananijaszowy: Faltyjasz, i Jesajasz; synowie Rafajaszowi, synowie Arnanaszowi, synowie Obadyjaszowi, synowie Sechenijaszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'A synowie Sechenijaszowi: Semejasz; a synowie Semejaszowi: Chattus, i Igal, i Baryja, i Naaryjasz, i Safat; sześć synów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'A synowie Naaryjaszowi: Elijenaj, i Ezechyjasz, i Esrykam, trzej synowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'A synowie Elijenajego: Hodawijasz i Elijasub, i Felejasz, i Akkub, i Jochanan, i Dalajasz, i Anani, siedm synów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Synowie Judowi: Fares, Hesron, i Charmi, i Hur, i Sobal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'A Rejasz, syn Sobalowy spłodził Jahata, a Jahat spłodził Achuma, i Laada. Teć są rodzaje Zaratego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'Ci też są z ojca Etama: Jezreel, i Jesema, i Idbas; a imię siostry ich Selelfuni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'A Faunuel ojciec Giedory, i Ezer ojciec Hosy. Cić są synowie Hura, pierworodnego Efraty, ojca Betlehemczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'A Assur, ojciec Tekui, miał dwie żony: Chelę i Naarę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'I urodziła mu Naara Achusama, i Hefera, i Temana, i Achastara. Cić są synowie Naary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Synowie zasię Cheli: Seret, Jesochar, i Etnan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'A Kos spłodził Anuba, i Hasoboba, i dom Acharchela, syna Harumy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'A Jabes był zacniejszy nad braci swych, któremu matka jego dała imię Jabes, mówiąc: Bom go w boleści urodziła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'I wzywał Jabes Boga Izraelskiego, mówięc: Jeźli błogosławiąc błogosławić mi będziesz, a rozszerzysz granice moje, a będzie ręka twoja ze mną, a wybawisz mię od złego, abym utrapiony nie był. I wypełnił to Bóg, o co go prosił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'A Chelub, brat Sucha, spłodził Mechyra; ten jest ojcem Estona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'A Eston spłodził Betrafa, i Paseacha, i Techynna, ojca miasta Nahas. Cić są mężowie Rechy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'A synowie Kienazowi: Otonijel, i Seraja; a synowie Otonijelowi: Hatat i Meanataj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'A Meanataj spłodził Ofra, a Serajasz spłodził Joaba, ojca w dolinie mieszkających rzemieślników; bo rzemieślnicy byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'Synowie zasię Kaleba, syna Jefumi: Hyru, Ela, i Nahain; a syn Ela jest Kienaz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'A synowie Jehaleleela: Zyf i Zyfa, Tyryja, i Azarel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'A synowie Ezry: Jeter, i Mered, i Efer, i Jalon; a żona Merodowa urodziła Miryjama, i Samaja, i Isbacha, ojca Estemoa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'Żona też jego Judaja urodziła Jereda, ojca Giedor, i Hebera, ojca Socho, i Jekutyjela, ojca Zanoach. Cić są synowie Betii, córki Faraonowej, którą był pojął Mered.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'A synowie żony Hodyjaszowej, siostry Nahama, ojca Ceili: Garmi i Estemoa Mahatczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'A synowie Symonowi: Amnon, i Rynna, Benchanan i Tylon; a synowie Isy: Zochet i Bensochet.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Synowie Seli, syna Judowego: Her, ojciec Lecha i Laada, ojciec Maraa; i rodzaje domów tych, którzy robili około bisioru w domu Asbeat,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'I Joakim i mężowie Chozeby, i Joaz i Saraf, którzy panowali w Moab, i Jasubi Lechem; ale te rzeczy są dawne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Cić są garncarze, którzy mieszkali w sadach i między płotami, którzy tam przy królu dla robót jego mieszkali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Synowie Symeonowi: Namuel, i Jamin, i Jaryb, Zera, Saul.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'Sallum syn jego, Mabsam syn jego, Misma syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'A synowie Mismy: Hamuel syn jego, Zachur syn jego, Semej syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Ten Semej miał synów szesnaście, i córek sześć; ale bracia jego nie mieli wiele synów, tak, że wszystkiej rodziny ich nie było tak wiele, jako synów Judowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'I mieszkali w Beerseba i w Molada, i w Hasersual,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'I w Bela, i w Asem, i w Etolad,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'I w Betul, i w Horma, i w Sycelegu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'I w Bet Marchabot, i w Hasersusa, i w Betbirze, i w Saaraim. Te miasta ich były, póki królował Dawid.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'A wsi ich były: Etam, i Hain, Remnon, i Tochen i Asan przy tych pięciu miastach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'I wszystkie wsi ich, które były około tych miast aż do Baal; teć były mieszkaniem ich według narodu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'A Mosobab, i Jamlech, i Josa, syn Amazyjaszowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'I Joel, i Jehu, syn Josabijasza, syna Serajaszowego, syna Asyjelowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'I Elichenaj, i Jakóba, i Jesochaja, i Asaja, i Adyjel, i Jesymijel, i Banajas;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'I Sysa, syn Syfy, syna Allonowego, syna Jodajaszowego, syna Symry, i syna Semajaszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'Ci mianowani postanowieni są za książęta w narodach swych, a domy ojców ich rozmnożyły się bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'Przetoż ruszyli się, aby szli do Gador, aż na wschód słońca onej doliny, aby szukali paszy bydłu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'I znaleźli obfite i wyborne pasze, a ziemię przestronną i spokojną i rodzajną; bo tam naród Chamów mieszkał przedtem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'Przetoż przyszedłszy ci z imienia opisani za dni Ezechyjasza, króla Judzkiego, poburzyli namioty ich i przybytki ich, które tam były znalezione; a wymordoealiich, i nie masz ich aż do dnia tego, i osiedli miejsce ich; bo tam mieli paszy dla bydeł swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'A z onych synów Symeonowych niektórzy szli na górę Seir, pięć set mężów, a Faltyjasz, i Necharyjasz, i Rafajasz, i Husel, synowie Isy, byli wodzami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'I wymordowali ostatki, które były uszły z Amalekitów, a mieszkali tam aż po dziś dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'A synowie Rubena pierworodnego Izraelowego, (ten bowiem był pierworodny; ale gdy zgwałcił łoże ojca swego, dane jest pierworodztwo jego synom Józefa, syna Izraelowego, tak jednak, że go nie poczytano za pierworodnego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Bo Judas był najmężniejsz między braćmi swymi, a książęciem między nimi; ale pierworodztwo należało Józefowi.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'Synowie mówię Rubena, pierworodnego Izraelowego, byli: Henoch i Fallu, Hesron i Charmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Synowie Joelowi: Samajasz syn jego, Gog syn jego, Semej syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'Michas syn jego, Reajasz syn jego, Baal syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'Bera syn jego, którego wziął w niewolę Teglat Falasar, król Asyryjski; ten był książęciem Rubenitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'A bracia jego według domów swych, gdy byli policzeni według ich narodów, mieli książęta Jehiela i Zacharyjasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'A Bela, syn Azazowy, syna Semmy, syna Joelowego; ten mieszkał w Aroer aż ku Nebo i Baalmeon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'Także i na wschód słońca mieszkał, aż kędy wchodzą na puszczę od rzeki Eufrates; albowiem stada ich rozmnożyły się w ziemi Galaadskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'Ci za dni Saulowych walczyli z Agareńczykami, którzy porażeni są od ręki ich; a tak mieszkali w namiotach ich po wszystkiej krainie wschodniej ziemi Galaadskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'A synowie Gadowi na przeciwko nich mieszkali w ziemi Bazan, aż do Selchy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joel był przedniejszym ich, a Safam wtóry, a Janaj i Safat zostali w Bazan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'A braci ich według domów ojców swych: Michael i Mesullam, i Seba, i Joraj, i Jachan, i Zyja, i Heber, siedm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, '(Cić są synowie Abihaila, syna Hurowego, syna Jaroachowego, syna, Galaadowego, syna Michaelowego, syna Jesysowego, syna Jachdowego, syna Buzowego;)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Achy, syn Abdyjela, syna Gunowego, książę w domu ojców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'I mieszkali w Galaad, w Bazan, i w miasteczkach jego, i po wszystkich przedmieściach Saron aż do ich granic.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Wszyscy ci policzeni byli za dni Jotama, króla Judzkiego, i za dni Jeroboama, króla Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Synów Rubenowych, i Gadowych, i połowy pokolenia Manasesowego, ludzi walecznych, mężów noszących tarczę i miecz, i ciągnących łuk, i ćwiczonych ku bojowi, czterdzieści i cztery tysiące, siedm set i sześćdziesiąt, wychodzących do bitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'Ci wiedli wojnę z Agareńczykami, z Jeturejczykami, i z Nafejczykami, i Nodabczykami,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'A mieli pomoc przeciwko nim. I podani są w rękę ich Agareńczycy ze wszystkim, co mieli, przeto iż do Boga wołali w bitwie, a on ich wysłuchał, iż ufali w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'I zabrali dobytki ich, wielbłądów ich pięćdziesiąt tysięcy, a owiec dwieście i pięćdziesiąt tysięcy, osłów dwa tysiące, a ludzi sto tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Albowiem rannych wiele poległo, iż od Boga była ona porażka. I mieszkali na miejscu ich, aż ich zabrano w niewolę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'Ale synowie połowy pokolenia Manasesowego mieszkali w onej ziemi od Bazan aż do Baal-Hermon i Sanir, które jest góra Hermon; bo i oni rozmnożeni byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'A cić są książęta domów ojców ich: Efer i Jesy, i Elijel, i Azryjel, i Jeremijasz, i Hodawijasz, i Jachdyjel, mężowie bardzo mocni, mężowie sławni, książęta domu ojców swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Ale gdy zgrzeszyli przeciw Bogu ojców swych i cudzołożyli naśladując bogów narodów onej ziemi, które wykorzenił Bóg przed twarzą ich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Wzbudził Bóg Izraelski ducha Fula króla Assyryjskiego, i ducha Teglat Falasera, króla Assyryjskiego, i przeniósł ich: Rubenitów, i Gadydtów, i połowę pokolenia Manasesowego, a zawiódł ich do Hela, i Haboru, i do Ara, i do rzeki Gozan, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Synowie Lewiego: Gerson, Kaat, i Merary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'A synowie Kaatowi: Amram, Izaar, i Hebron, i Husyjel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'A synowie Amramowi: Aaron, i Mojżesz, i córka Maryja; a synowie Aaronowi: Nadab, i Abiju, Eleazar, i Itamar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazer spłodził Fineesa; Finees spłodził Abisua.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abissue spłodził Bokki, a Bokki spłodził Uzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'A Uzy spłodził Zerachyjasza, a Zerachyjasz spłodził Merajota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajot spłodził Amaryjasza, a Amaryjasz spłodził Achytoba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'A Achytob spłodził Sadoka, a Sadok spłodził Achymaasa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'Achymaas spłodził Azaryjasza, a Azaryjasz spłodzi× Johanana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'A Johanan spłodził Azaryjasz; tenci jest, który kapłański urząd sprawował w domu, który zbudował Salomon w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Spłodził też Azaryjasz Amaryjasza, a Amaryjasz spłodził Achytoba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'A Achytob spłodził Sadoka, a Sadok spłodził Salluma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'A Sallum spłodził Helkijasza, a Helkijasz spłodził Azaryjasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'A Azaryjasz spłodził Sarajasza, a Sarajasz spłodził Jozedeka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'Ale Jozedek poszedł w niewolę, gdy Pan przeniósł Judę i Jeruzalem przez Nabuchodonozora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Synowie Lewi: Gierson, Kaat, i Merary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'A teć są imiona synów Giersonowych: Lobni i Semei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'A synowie Kaatowi: Amram i Izaar, i Hebron, i Husyjel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Synowie Merarego: Macheli, i Muzy. A teć są domy Lewitów według ojców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Giersonowi: Lobni syn jego, Jachat syn jego, Zamma syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'Joach syn jego, Iddo syn jego, Zara syn jego, Jetraj syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Synowie Kaatowi: Aminadab syn jego, Kore syn jego, Aser syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'Elkana syn jego, i Abiazaf syn jego, i Assyr syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'Tachat syn jego, Uryjel syn jego, Ozyjasz syn jego, i Saul syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'A synowie Elkamowi: Amasaj i Achymot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'Elkana. Synowie Elkanowi: Sofaj syn jego, i Nahat syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'Elijab syn jego, Jerobam syn jego, Elkana syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'A synowie Samuelowi: Pierworodny Wassni i Abijas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Synowie Merarego: Mahali; Lobni syn jego, Symej syn jego, Uza syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'Symha syn jego, Haggijasz syn jego, Asajasz syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Ci są, których postanowił do śpiewania w domu Pańskim, gdy tam postawiono skrzynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'I służyli przed przybytkiem namiotu zgromadzenia, śpiewając, aż zbudował Salomon dom Pański w Jeruzalemie, i stali według porządku swego na służbie swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'A cić są, którzy stali i synowie ich z synów Kaatowych: Heman śpiewak syn Joela, syna Samuelowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'Syna Elkanowego, syna Jerohamowego, syna Elijelowego, syna Tohu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'Syna Sufowego, syna Elkanowego, syna Machatowego, syna Amasajowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'Syna Elkanowego, syna Joelowego, syna Azaryjaszowego, syna Sofonijaszowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'Syna Tachatowego, syna Assyrowego, syna Abijasowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'Syna Korego, syna Isarowego, syna Kaatowego, syna Lewiego, syna Izraelowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'A brat jego Asaf, który stawał po prawicy jego. Asaf, syn Barachyjaszowy, syna Samaowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'Syna Michaelowego, syna Basejaszowego, syna Malchyjaszowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'Syna Etny, syna Zerachowego, syna Adajowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'Syna Etanowgo, syna Symmowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'Syna Semejowego, syna Jachatowego, syna Giersonowego, syna Lewiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'A synowie Merarego i bracia ich stawali po lewej stronie: Etan, syn Kuzego, syna Abdego, syna Malluchowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'Syna Hasabijaszowego, syna Amazyjaszowego, syna Helkijaszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'Syna Amsego, syna Banego, syna Semmerowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'Syna Moholi, syna Musego, syna Merarego, syna Lewiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'A bracia ich Lewitowie postawieni są ku wszelakiej posłudze przybytku domu Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Ale Aaron i synowie jego palili na ołtarzu całopalenia, i na ołtarzu kadzenia przy każdej posłudze świątyni świętych, i ku oczyszczaniu Izraela podług wszystkiego, jako był przykazał Mojżesz, sługa Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'A ci są synowie Aaronowi: Eleazar syn jego, Finees syn jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'Abisua syn jego, Bokki syn jego, Uzy syn jego, Zerachyjasz syn jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'Merajot syn jego, Amaryjasz syn jego, Achytob syn jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'Sadok syn jego, Achymaas syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'A te są mieszkania ich, według pałaców ich w granicy ich, to jest, synów Aaronowych według rodzaju Kaatytów: bo to był ich los.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'Przetoż dali im Hebron w ziemi Judzkiej, i przedmieścia jego około niego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'Ale pole miejskie i wsi ich dali Kalebowi, synowie Jefunowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'Synom zaś Aaronowym dali z miast Judzkich miasta ucieczki Hebron, i Lobne i przedmieścia jego, i Jeter, i Estemoa, i z przedmieściami jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'I Holon i przedmieścia jego, i Dabir i przedmieścia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'I Asan i przedmieścia jego, i Betsemes i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'A z pokolenia Benjaminowego: Gabae i przedmieścia jego, i Almat i przedmieścia jego, i Anatot i przedmieścia jego. Wszystkich miast ich trzynaście miast według domów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'A synom Kaatowym, pozostałym z rodzaju tegoż pokolenia, dostało się w połowie pokolenia Manasesowego losem miast dziesięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'A synom Giersonowym według domów ich dostało się w pokoleniu Isascharowem, i w pokoleniu Aserowem, i w pokoleniu Neftalimowem, i w pokoleniu Manasesowem w Bazan miast trzynaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Synom Merarego według domów ich dostało się w pokoleniu Rubenowem, i w pokoleniu Gadowem, i w pokoleniu Zabulonowem losem miast dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Dali też synowie Izraelscy Lewitom miasta i przedmieścia ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'A dali je losem w pokoleniu synów Judowych, i w pokoleniu synów Symeonowych, i w pokoleniu synów Benjaminowych, miasta te, które nazwali imiony swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'A tym, którzy byli z rodu synów Kaatowych, (a były miasta i granice ich w pokoleniu Efraim.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'Tym dali z miast ucieczki Sychem i przedmieścia jego na górze Efraim, i Gazer i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'I Jekmaan i przedmieścia jego, i Betoron i przedmieścia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'I Ajalon i przedmieścia jego, i Gatrymon i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'A w połowie pokolenia Manasesowego: Aner i przedmieścia jego, Balam i przedmieścia jego. To dali rodzajowi pozostałemu synów Kaatowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Synom też Giersonowym z rodu połowy pokolenia Manasesowego dali Golan w Bazan i przedmieścia jego, i Astarot i przedmieścia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'A w pokoleniu Isascharowem Kades i przedmieścia jego, Daberet i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'I Ramot i przedmieścia jego, i Anam i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'A w pokoleniu Aserowem Masal i przedmieścia jego, i Abdon i przedmieścia jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'I Hukok i przedmiescia jego, i Rohob i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'A w pokoleniu Neftalimowem: Kades w Galilei, i przedmieścia jego, i Hammon i przedmieścia jego, i Kiryjataim i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Synom Merarego, pozostałym z pokolenia Zabulon, dane są Remmon i przedmieścia jego, Tabor i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'A za Jordanem u Jerycha na wschód słońca od Jordanu, dane są w pokoleniu Rubenowem: Besor na puszczy, i przedmieścia jego, i Jahasa i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'I Kiedemot i przedmieścia jego, i Mefaat i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'A w pokoleniu Gadowem Ramot w Galaad i przedmieścia jego; i Mahanaim i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Hesebon i przedmieścia jego, i Jazer i przedmieścia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'A synowie Isascharowi: Tola i Fua, Jasub, i Semram, czterej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'A synowie Tolego: Uzy, i Rafajasz, i Jeryjel, i Jachamaj, i Jebsam, i Samuel; a cić byli książętami według domów ojców swych, którzy poszli z Tole, mężowie bardzo duży według narodów swych; poczet ich był za dni Dawodowych dwadzieścia i dwa tysiące i sześć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'A synowie Uzego: Izrahyjasz; a synowie Izrahyjaszowi: Michael i Obadyjasz, i Joel, Jesyjasz; pięć książąt wszystkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'A z nimi w narodach ich, według domów ojców ich, poczet mężów walecznych trzydzieści i sześć tysięcy; bo mieli wiele żon i synów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'A braci ich według wszystkich rodzajów Isascharowych, mężów dużych było ośmdziesiąt i siedm tysięcy, wszystkich policzonych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Synowie Benjaminowi: Bela i Bechor, i Jedyjael, trzej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'Synowie zaś Belego: Esbon i Uzy, i Uzyjel, i Jerymot, i Iry; pięć książąt domów ojcowskich, mężów dużych; naliczono dwadzieścia i dwa tysiące, i trzydzieści i cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'A synowie Bechorowi; Zamirai i Joaz, i Eliezer, i Elienaj, i Amry, i Jerymot, i Abijasz, i Anatot, i Alamat; wszyscy ci synowie Bechorowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'A naliczono ich według rodzajów ich, książąt domów ojców ich, mężów udatnych dwadzieścia tysięcy i dwieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'A synowie Jedyjaelowi: Bilan; a synowie Bilanowi: Jehus, i Banjamin, i Ehod, i Chanaan, i Zetan, i Tarsys, i Achysachar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Tych wszystkich synów Jadyjaelowych według książąt domów ojcowskich, mężów bardzo dużych siedmnaście tysięcy i dwieście, wychodzących na wojnę do bitwy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Oprócz Suppim i Ofim, synów w domu zrodzonych, i Husym, i synów w obcym kraju zrodzonych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'A synowie Neftalimowi: Jachsel, i Guni, i Jesser, i Selem, synowie Bali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'A synowie Manasesowi: Asryjel, którego mu urodziła Zona, (a założnica jego Syryjanka urodziła Machyra, ojca Galaadowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'A Machyr wziął sobie za żonę siostrę Ofimową i Suppimową, której imię było Maacha;) a imię drugiego Salfaad, i miał Salfaad córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'A urodziła Maacha, żona Machyrowa, syna, i nazwała imię jego Fares; a imię brata jego Sares, a synowie jego Ulam i Rekiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'A synowie Ulamowi Bedon. Cić są synowie Galaada, syna Machyrowego, syna Manasesowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'A siostra jego Molechet urodzi×a Isoda, i Abiezera, i Machala.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'A synowie Semidowi byli Ahyjan, i Sechem, i Likchy, i Anijam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'A synowie Efraimowi: Sutala, i Bered syn jego, i Tachat syn jego, i Elada syn jego, i Tachat syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'I Zabad syn jego, i Sutala syn jego, i Eser, i Elad. A pobili ich mężowie z Get, co się byli zrodzili w onej ziemi; albowiem byli wtargnęli, aby pobrali dobytki ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'Przetoż płakał Efraim, ojciec ich, przez wiele dni; i przyszli bracia jego, aby go cieszyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'Córkę też jego Seerę, która pobudowała Betoron niższe i wyższe, i Uzenzeera;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'I Refacha syna jego, i Resefa, i Telacha syna jego, i Techena syna jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'I Laadana syna jego, Ammiuda syna jego, Elisama syna jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'Nuna syna jego, Jozuego syna jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'A osiadłość ich i mieszkania ich, Betel i wsi jego; a na wschód słońca Naaran; a na zachód słońca Gazer i wsi jego, i Sychem i wsi jego, aż do Aza i wsi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'A podle miejsc synów Manasesowych: Betsan, i wsi jego, Tanach i wsi jego, Magieddon i wsi jego, Dor i wsi jego. W tych mieszkali synowie Józefowi, syna Izraelowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'Synowie Aserowi: Jemna i Jesua, Iswy i Beryja, i Sera, siostra ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'A synowie Beryjaszowi: Heber i Melchyjel; ten jest ojciec Birsawitów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'A Heber spłodził Jafleta, i Somera, i Hotama, i Suę, siostrę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'A synowie Jafletowi: Pasach i Bimhal i Aswat. Cić są synowie Jafletowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'A synowie Somerowi: Ahy i Rohaga, Jechuba i Aram.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'A synowie Helema, brata jego: Sofach, Jemna, i Seles, i Amal.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'Synowie Sofachowi: Suach, Harnefer, i Sual, i Bery, i Imra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Beser, i Hod, i Sema, i Silsa, i Jetram, i Bera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'A synowie Jeterowi: Jefone, i Fispa, i Ara, i Ulla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'A synowie Ullowi: Arach, i Haniel, i Rysyjasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'Ci wszyscy są synowie Aserowi, książęta domów rodzajów swych, wybrani i duży mężowie, przedniejsi z książąt, którzy policzeni są na wojnę do bitwy; poczet tych mężów dwadzieścia i sześć tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'A Benjamin spłodził Belę, pierworodnego swego, Asbela wtórego, i Abracha trzeciego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Nocha czwartego, a Rafajasza piątego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'A synowie Beli byli Addar i Giera i Abihud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'I Abisua i Noaman i Achoach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'I Giera i Sufam i Churam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'A cić są synowie Echudowi: ci są książętami narodów mieszkających w Gabaa, którzy je przenieśli do Manakat;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'To jest Noaman, i Achija, i Giera; on je przeniósł, a spłodził Uzę, i Ahyhuda, i Sacharaima.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'A Sacharaim spłodził dzieci w krainie Moabskiej, gdy one był odprawił, z Chusymą, i Barą, żonami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'Spłodził tedy z Hodes, żoną swą, Jobaba, i Sebijasza, i Mezę, i Malchama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'I Jehusa, i Sachyjasza, i Mirmę. Cić są synowiejego, książęta domów ojcowskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'A z Chysymą spłodził Abituba i Elfaala.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'A synowie Elfaalowi: Eber, i Misaam, i Samed, który zbudował Ono, i Lod i wsi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'A Beryja i Sama byli książętami narodíw mieszkających w Ajalon; ci wygnali obywateli z Get.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'A Achyjo, Sesak i Jerymot,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'I Zabadyjasz, i Arad, i Hader,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'I MIchael, i Isfa, i Jocha, synowie Berajaszowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'A Zabadyjasz, i Mesullam, i Hyszki, i Heber,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'I Ismaraj, i Islijasz, i Jobab, synowie Elfaalowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'A Jakim, i Zychry, i Zabdy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'I Elienaj, i Selataj, i Eliel,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'I Adajasz, i Berajasz, i Symrat, synowie Synchy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'A Isfan, i Eber, i Eliel,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'I Abdon, i Zychry, i Chanan,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'I Hananijasz, i Eleam, i Anatotyjasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'I Ifdajasz, i Fanuel, synowie Sesakowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'I Samseraj, i Zecharyjasz, i Atalijasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'I Jaresyjasz, i Elijasz, i Zychry, synowie Jerochamowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Ci są książęta domów ojcowskich według rodzajów swych, a ci książęta mieszkali w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'A w Gabaonie mieszkał ojciec Gabaończyków, a imię żony jego było Maacha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'A syn jego pierworodny Abdon; po nim Sur, i Cys, i Baal, i Nadab.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'I Giedor, i Achyjo, i Zechar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'Ale Michlot spłodził Symejasza; a ci także naprzeciwko braci swych mieszkali w Jeruzalemie z braćmi swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'A Ner spłodził Cysa, a Cys spłodził Saula; Saul zaś spłodził Jonatana i Melchisuego, i Abinadaba i Esbaala.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'A syn Jonatanowy był Merybbaal, a Merybbaal spłodził Michasa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'A synowie Michasowi: Fiton i Melech i Tarea i Achaz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'A Achaz spłodził Joada, a Joada spłodził Alemeta i Asmaweta i Zymrego, a Zymry spłodził Mose;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'A Mosa spłodził Binę; Refajasz syn jego, Elasa syn jego, Asel syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'Ten Asel miał sześć synów, a teć imiona ich: Asrykam, Bochru, i Ismael, i Searyjasz, i Obadyjasz, i Hanan; ci wszyscy synowie Aselowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'A syowie Eseka, brata jego: Ulam pierworodny jego. Jehus wtóry, i Elifelet trzeci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'A synowie Ulamowi byli mężowie duży, i mocno łuk ciągnący, którzy mieli wiele synów i wnuków, aż do stu i pięćdziesiąt. Ci wszyscy poszli z synów Benjaminowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'A tak wszyscy Izraelczycy obliczeni są; a oto zapisani są w księgach królów Izraelskich i Judzkich, a przeniesieni są do Babilonu dla przestępstwa swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Lecz którzy pierwsi mieszkali w osiadłościach swych i w miastach swoich, Izraelczycy, kapłani, Lewitowie, i Netynejczycy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'W Jeruzalemie mieszkali z synów Judowych, i z synów Benjaminowych, i z synów Efraimowych, i Manasesowych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Uttaj, syn Ammiuda, syna Amry, syna Imry, syna Bonny, z synów Faresa, syna Judowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'A z Sylona: Asajasz pierworodny, i synowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'A z synów Zerachowych: Jehuel i braci ich sześć set i dziewięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'A z synów Benjaminowych: Salu, syn Mesullama, syna Hodowiego, syna Asenuowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'A Ibnijasz, syn Jerochamowy, i Ela, syn Uzego, syna Michry, i Mesullam, syn Sefatyjasza, syna Rehuelowego, syna Ibnijaszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'Także braci ich według narodów ich było dziewięć set i pięćdziesiąt i sześć: ci wszyscy mężowie byli książętami rodzajów według domów ojców swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'Z kapłanów zasię: Jedejasz, i Jechojaryk, i Jachyn,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'I Azaryjasz, syn Helkijasza, syna Mesullamowego, syna Sadokowego, syna Merajatowego, syna Achytobowego, był książęciam domu Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'I Adajasz, syn Jerohama, syna Fassurowego, syna Melchyjaszowego, i Maasaj, syn Adyjela, syna Jechserowego, syna Mesulla,owego, syna Mesullemitowego, syna Immerowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'A braci ich książęt według domów ojców ich było tysiąc i siedm set i sześćdziesiąt, mążów dużych ku sprawowaniu posługi w domu Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'A z Lewitów: Semejasz, syn Hassuba, syna Asrykamowego, syna Hasabijaszowego, z synów Merarego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'I Bakkabar, Cheres, i Galal, i Matanijasz, syn Michy, syna Zychrego, syna Asafowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'Obadyjasz też, syn Semahajasza, syna Galalowego, syna Jedytunowego, i Barachyjasz, syn Asy, syna Elkanowego, który mieszkał we wsiach Netofatyckich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'A odźwierni: Sallum, i Akkub, i Talmon, i Ahyman, i nracia ich; Sallum książę między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'Który aż dotąd w bramie królewskiej stawał na wschód słońca; ci byli odźwiernymi według pocztów synów Lewiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'Ale Sallum, syn Korego, syna Abijazafowego, syna Korego, i bracia jego z domu ojca jego, Korytczycy byli ku odprawowaniu posługi, stróżami progów namiotu; a ojcowie ich byli nad obozem Pańskim stróżami wejścia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'A Finees syn Eleazarowy, był książęciem nad nimi, a Pan był z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zacharyjasz zasię, syn Mesellemijaszowy, był odźwiernym drzwi u namiotu zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Cić wszyscy są obrani za odźwiernych do drzwi, dwieście osób i dwanaście: ci we wsiach swych policzeni są, których postanowił Dawid i Samuel widzący, dla wierności ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Aby oni i synowie ich byli we drzwiach domu Pańskiego, w domu namiotu na straży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'I byli odźwierni po czterech stronach, na wschód, na zachód, na północy, i na południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'Bracia zasię ich byli we wsiach swych, przychodząc każdego siódmego dnia, od czasu aż do czasu odmieniając się z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'Albowiem pod sprawą tych czterech przedniejszych odźwiernych byli Lewitowie, a byli przełożeni nad gmachami i nad skarbami domu Bożego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'A około domu Bożego nocowali, gdyż im należała straż jego; a oni go na każdy poranek otwierali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'A z nich niektórzy byli nad naczyniem ku posługiwaniu; albowiem pod liczbą wnosili je, i pod liczbą wynosili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Niektózry zasię z nich byli postanowieni nad innem naczyniem, i nad wszystkiem naczyniem świątnicy, i nad mąką pszenną i winem, i oliwą, i kadzidłem, i nad rzeczami wonnemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'A niektórzy z synów kapłańskich sprawowali maści z rzeczy wonnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'Matatyjasz też z Lewitów, pierworodny Salluma Korytczyka, był przełożony nad rzeczami, które w panwiach smażono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'A z synów Kaatowych z braci ich, byli niektórzy przełożonymi nad chlebami pokładnemi, aby je gotowali na każdy sabat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'A z tych byli śpiewacy, przedniejsi z domów ojcowskich, między Lewitami mieszkający w gmachach, od inszych prac wolni; bo we dnie i w nocy powinności swej pilnować musieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Ci przedniejsi z domów ojcowskich między Lewitami, według narodów swych przedniejsi; ci mieszkali w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'A w Gabaonie mieszkali ojciec Gabaończyków Jehyjel, a imię żony jego Maacha;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'A syn jego pierworodny Abdon, po nim Sur, i Cys, i Baal, i Neer, i Nadab,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'I Giedeor, i Achyjo, i Zacharyjasz, i Michlot;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, '(A Michlot spłodził Symmama) a ci także przweciw braci swych mieszkali w Jeruzalemie z braćmi swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'A Neer spłodził Cysa, a Cys spłodził Saula, a Saul spłodził Jonatana, i Melchisuego, i Abidanaba, i Esbaala.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'A syn Jonatana Merybbaal; a Merybbaal spłodził Michasa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'Synowie zaś Michasowi: Fiton, i Melech, i Tarea, i Achaz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'A Achaz spłodził Jarę; a Jara spłodził Alemeta, i Asmaweta, i Zynrego; a Zymry spłodził Mosę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'A Mosa spłodził Binę; a Refajasz syn jego, Elasa syn jego, Asel syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'A Asel miał sześć synów; a teć imiona ich: Asrykam, i Bochru, i Ismael, i Searyjasz, i Obadyjasz, i Hanan. Cić są synowie Aselowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'A gdy Filistynowie walczyli z Izraelem, uciekli mężowie Izraelscy przed Filistynami a polegli, będąc porażeni na górze Gielboe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'I gonili Filistynowie Saula i synów jego; i zabili Filistynowie Jonatana, i Abinadaba, i Melchisuego, synów Saulowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'A gdy się zmocniła bitwa przeciw Saulowi, trafili na niego strzelcy, i z łuku zraniony jest od strzelców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Rzekł tedy Saul do sługi swego, co za nim broń nosił: Dobądź miecza twego, a przebij mię nim, by snać nie przyszli ci nieobrzezańcy, a nie pośmiewali się ze mnie. Ale nie chciał sługa, który nosił broń jego; bo się bardzo bał. Przetoż porwawszy Saul miech, padł nań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'A widząc sługa, co nosił broń jego, że umarł Saul, padłszy też i sam na miecz umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'A tak umarł Saul, i trzej synowie jego, i wszystek dom jego z nim pospołu zginął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Co gdy ujrzeli wszyscy mężowie Izraelscy, którzy mieszkali na dolinie, iż uciekli Izraelczycy, a iż pomarli Saul i synowie jego, opuściwszy miasta swe także uciekli. I przyszli Filistynowie, i mieszkali w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'A gdy nazajutrz przyszli Filistynowie brać łupy z pobitych, znaleźli Saula, i synów jego, leżących na górze Gielboe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'A złupiwszy go wzięli głowę jego, i zbroję jego, i posłali po ziemi Filistyńskiej w około, aby to ogłoszone było przed bałwany ich, i przed ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'I położyli zbroję jego w domu boga swego, a głowę jego zawiesili w domu Dagonowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Usłyszawszy tedy wszyscy mężowie Jabes Galaad wszystko, co uczynili Filistynowie Saulowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'Powstali wszyscy mężowie mocni, i wzięli ciało Saulowe, i ciało synów jego, a przyniósłszy do Jabes pogrzebli kości ich pod dębem w Jabes, i pościli przez siedm dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'A tak umarł Saul dla przestępstwa swego, którem był wystąpił przeciwko Panu, i przeciwko słowu Pańskiemu, któego nie przestrzegał, iż się radził ducha wieszczego, pytając się go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'A iż się nie radził Pana, zabił go, a przeniósł królestwo na Dawida, syna Isajego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Zebrał się tedy wszystek Izrael do Dawida do Hebronu, mówiąc: Otośmy kość twoja i ciało twoje!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'Jako i przedtem, gdy jeszcze był Saul królem, też wywodził i wwodził Izraela. Tak Pan, Bóg twój, rzekł tobie: Ty będziesz pasł lud mój Izraelski, a ty będziesz wodzem nad ludem moim Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'A tak przyszli wszyscy starsi Izraelscy do króla do Hebronu, i uczynił Dawid z nimi przymierze w Hebronie przed Panem, i pomazali Dawida za króla nad Izraelem według słowa Pańskiego, które powiedział przez Samuela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'Jechał tedy Dawid ze wszystkim Izraelem do Jeruzalemu, które jest Jebus, gdzie byli Jebuzejczycy obywatelami ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'I rzekli obywatele Jebuzejscy do Dawida: Nie wnijdziesz sam. Ale Dawid wziął zamek Syoński, który jest miastem Dawidowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'Bo był rzekł Dawid: Ktobykolwiek poraził Jebuzejczzyka najpierwej, ten będzie skiążęciem i hetmanem. Przetoż wstąpił najpierw Joab, syn Sarwii, i został hetmanem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'I mieszkał Dawid na onym zamku; dla tego nazwano go miastem Dawidowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'I zbudował miasto w około, od Mello aż w okrąg; a Joab pobudował ostatek miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'A tak Dawid im dalej, tem więcej rozmnażał się, i rosł; albowiem Pan zastępów był z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'A cić są najorzedniejsi rycerze, których miał Dawid, którzy się mężnie starali z nim o królestwo jego ze wszystkim Izraelem, aby go królem uczynili według słowa Pańskiego nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'A tenci jest poczet rycerzy, których miał Dawid: Jasobam, syn Chachmonowy, przedniejszy między trzydziestoma; ten podniósłszy oszczep swój na trzystu, jednym razem ich zabił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'A po nim Elezar, syn Dodonowy, Achochytczyk; ten był jednym między trzema mocarzami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'Ten był z Dawidem w Pasdamim, gdzie się zebrali byli Filistynowie ku bitwie; a była ona część pola pełna jęczmienia, a lud był uciekł przed Filistynami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'I stanęli w pośród onego pola, i obronili go, a porazili Filistynów: i wybawił Pan lud wybawieniem wielkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'Ci także trzej ze trzydziestu przedniejszych wstąpili na skałę do Dawida do jaskini Odollam, gdyż wojsko Filistyńskie leżało obozem w dolinie Rafaim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'Albowiem Dawid natenczas mieszkał na zamku, a stanowisko Filistyńskie było natenczas w Betlehem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'Pragnęł tedy Dawid: Oby mi się kto dał napić wody z studni Betlehemskiej, która jest u bramy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'Przetoż przebiwszy się ci trzej przez wojsko Filistyńskie, naczerpali wody z studni Betlehemskiej, która jest u bramy, a wziąwszy przynieśli do Dawida. Lecz jej nie chciał Dawid pić, ale ją wylał na ofiarę Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'I rzekł: Nie daj mi tego, Boże mój, abym to uczynić miał! Izali krew tych mężów pić będą, którzy odważyli żywot swój? albowiem z odwagą żywota swego przynieśli ją; i nie chciał jej pić. Toć uczynili trzej oni mocarze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'A Abisaj, brat Joabowy, był przedniejszy z onych trzech; tenże podniósł włócznię swą na trzysta ludu, które pobił, i otrzymał sławę między onymi trzema.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Z tych trzech nad innych dwóch był sławniejszy, a był ich książęciem; jednak onych trzech pierwszych nie doszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Banajas też, syn Jojady, syn męża dużego, wielkich spraw, z Kabseela, ten zabił dwóch mocarzów Moabskich; ten też zszedłszy zabił lwa w pośród jamy, gdy był śnieg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'Ten też zabił męża Egipczanina, męża, którego wzrost był na pięć łokci. A chociaż Egipczanin miał w ręku oszczep jako nawój tkacki, wszkże przyszedł do niego z kijem, i wydarł oszczep z ręki Egipczanina, i zabił go oszczepem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'To uczynił Banajas, syn Jojady, który także sławnym został między onymi trzema mocarzami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'A choć był między onymi trzydziestoma sławnym, wszakże nie doszedł onych trzech. I postanowił go Dawid nad drabantami swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'A w wojsku co mocniejsi byli: Asael, brat Joabowy, Elkanan, syn Dodonowy z Betlehem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Sammot Harodczyk, Heles Felonitczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Hyra, syn Ikkiesowy, Tekuitczyk, Abiezer Anatotczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sybbechaj Husatczyk, Ilaj Ahohytczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharaj Netofatczyk, Heled, syn Baamy, Netofatczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Itaj, syna Rybajego, z Gabaat synów Benjaminowych, Banajas Faratończyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Hutaj od potoku Gaas; Abiel Arbatczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Asmawet Bacharomczyk; Elijachba Salabończyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'Synowie Asema Gisończyka: Jonatan, syn Sagii, Hororczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ahijam, syn Zacharowy, Ararytczyk, Elifal, syn Urowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hefer Mecheratczyk, Achijas Felonitczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hesro Karmelczyk, Naaraj, syn Ezbajowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, brat Natanowy,Michbar, syn Gierego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Selek Ammonitczyk, Nacharaj Berotczyk, który nosił broń Koaba, syna Sarwii;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Hyra Itrejczyk, Gareb Itrejczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Uryjasz Hetejczyk, Zabad, syn Achalajego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adyna, syn Sysy, Rubenitczyk, książę Rubenitów, a z nim trzydzieści mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan, syn Maachy, i Jozafat Mitnitczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uzyjasz Asteratczyk, Sama i Jehijel, synowie Hotamy Aroerytczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jedinael, syn Symry, i Jocha, brat jego, Tysytczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel Machawimczyk, i Jerybaj, i Josawijasz, synowie Elnaamowi, i Itma Moabczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel, i Obed, i Jaasyjel z Mezobaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'A cić są, co byli przyszli do Dawida do Sycelegu, gdy się jeszcze krył przed Saulem, synem Cysowym; a ci byli między mocarzami posiłek dawający w bitwie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'Noszący łuk, a prawą i lewą ręką ciskający kamieńmi, i strzelający z łuku, a byli z braci Saulowych z pokolenia Benjaminowego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Książe Achyjezer, i Joaz, synowie Semmai Gabatczyka, i Jezyjel, i Falet, synowie Azmawetowi, i Baracha, i Jehu Anatotczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Ismajasz też Gabaończyk, mężny między trzydziestoma, a był przełożony nad trzydziestoma; i Jeremijasz, i Jahazyjel, Johanan, i Jozabad Gliederatczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Eluzaj, i Jerymot, i Bealijasz, i Semaryjasz, i Sefatyjasz Harufitszyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkana, i Jesyjasz, i Asareel i Joezer, i Jasobam Korchytczyk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'I Joela, i Zebadyjasz, synowie Jerohamowi z Giedor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'A z pokolenia Gadowego zbiegli byli do Dawida na miejsce obronne na puszczę mężowie duży, mężowie sposobni do boju, noszący tarcz i kopiję, których twarze były jako lwie tarze, a jako sarny po górach prędcy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Eser przedniejszy, Obadyjasz wtóry, Elijab trzeci,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Mismanna czwarty, Jeremijasz piąty,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Ataj szósty, Eliel siódmy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Jochanan ósmy, Elzebad dziewiąty,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jeremijasz dziesiąty, Machbanajasz jedenasty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Cić byli z synów Gadowych, hetmani wojska, jeden nad stem mniejszy, a większy nad tysiącem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Cić są, którzy przeszli Jordan miesiąca pierwszego, który był wylał ze wszystkich brzegów swoich; i wygnali wszystkich mieszkających w dolinach na wschód i na zachód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'Przyszli także niektórzy z synów Benjaminowych i z Judowych, do miejsca obronnego, do Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'I wyszedł Dawid przeciwko nim a odpowiadając, rzekł im: Jeźliście spokojnie przyszli do mnie, abyście mię ratowali, serce też moje złączy się z wami; ale jeźliście przyszli, abyście mię wydali nieprzyjaciołom moim, (choć nie masz nieprawości przy mnie) niech w to wejrzy Bóg ojców naszych, a niech sądzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Tedy Duch przyoblekł Amazyjasza, przedniejszego między hetmanami, i rzekł: Twoiśmy, o Dawidzie! a z tobą przestajemy, synu Isajego. Pokój, pokój tobie, i pokój pomocnikom twoim! gdyż ci pomaga Bóg twój. A tak przyjął ich Dawid, i postanowił ich hetmanami wojska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'A z pokolenia Manasesowego odpadli niektórzy do Dawida, gdy ciągnął z Filistynami przeciwko Saulowi na wojnę; ale im nie byli na pomocy, gdyż naradziwszy się książęta Filistyńscy odesłali go, mówiąc: Ten z niebezpieczeństwem głów naszych odpadnie do Saula, pana swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Gdy tedy szedł do Syceleu, uciekli do niego niektórzy z pokolenia Manasesowego: Adnach i Josabad, i Jediael, i Michael, i Jozabad i Elihu, i Sylletaj, i hetmani nad tysiącami w pokoleniu Manasesowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'A ci posiłkowali Dawida przeciw onemu hufowi; bo mężni byli wszyscy, przetoż byli hetmanami w wojsku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Nawet na każdy dzień ściągali się do Dawida na pomoc jemu, aż było wojsko wielkie jako wojsko Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'A tać jest liczba przedniejszych gotowych do boju, którzy przyszli do Dawida do Hebronu, aby przenieśli królestwo Saulowe do niego według słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Z synów Judowych, noszących tarcz i włócznię, sześć tysięcy i ośm set gotowych do boju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Z synów Symeonowych, mężnych do boju, siedm tysięcy i sto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Z synów Lewiego cztery tysiące i sześć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'Jojada także przedniejszy z synów Aaronowych, a z nim trzy tysiące i siedm set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'A Sadok młodzieniec, rycerz mężny, i z domu ojca jego książąt dwadzieścia i dwóch.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'A z synów Benjaminowych, braci Saulowych, trzy tysiące; bo jeszcze wielka część ich przestawała z domem Saulowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'A z synów Efraimowych dwadzieścia tysięcy i ośm set, ludzi mężnych, mężów sławnych w domach ojców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'A z połowy pokolenia Manasesowego ośmnaście tysięcy, którzy byli mianowani według imion, aby przyszli i postanowili Dawida królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'A z synów Isascharowych, umiejących rozeznawać czasy, tak iż wiedzieli, co kiedy czynić miał Izrael, książąt ich dwieście; a wszyscy bracia ich przestawali na radzie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Z pokolenia Zabulonowego, którzy wychodzili na wojnę, gotowych do boju z każdym orężem wojennym, pięćdziesiąt tysięcy, stawających w szyku jednostajnem sercem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'A z pokolenia Neftalimowego książąt tysiąc, a z nimi z tarczami i z kopijami trzydzieści i siedm tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'A z pokolenia Danowego, gotowych do boju, dwadzieścia i ośm tysięcy i sześć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'A z pokolenia Aserowego, którzy wychodzili na wojnę, i umieli się szykować do bitwy, czterdzieści tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'A z Za-Jordania z pokolenia Rubenowego i Gadowego, i z połowy pokolenia Manasesowego ze wszystkim orężemwojennym sto i dwadzieścia tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Ci wszyscy mężowie waleczni sprawni ku bitwie, sercem uprzejmem przyszl do Hebronu, aby postanowili Dawida królem nad wszystkim Izraelem. Nadto i wszyscy inni z Izraela jednego serca byli, aby postanowili królem Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'I byli tam z Dawidem przez trzy dni jedząc i pijąc: bo im byli nagotowali bracia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Także i którzy blisko ich byli aż do Isaschar i Zabulon i Neftalim, przynosili chleby na osłach, i na wielbłądach, i na mułach, i na wołach, potrawy, mąki, figi, rodzynki, i wino, i oliwę, i wołów, i owiec wielkim dostatkiem; bo była radość w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'A Dawid wszedł w radę z hetmanami nad tysiącami, i z setnikami, i ze wszystkimi rotmistrzami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'I mówił Dawid do wszystkiego zgromadzenia Izraelkskiego: Jeźli się wam podoba, i jeźli to jest od Pana Boga naszego, roześlijmy wszędy do braci naszych pozostałych po wszystkich krainach Izraelskich; przytem też do kapłanów i Lewitów po miastach i przedmieściach ich, a niech się zgromadzą do nas:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'Abyśmy przeprowadzili skrzynię Boga naszego do nas; albowiem nie pytaliśmy się o niej za dni Saulowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'I rzekło wszystko zgromadzenie, aby się tak stało; bo się ta rzecz podobała wszystkiemu ludowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Zebrał tedy Dawid wszystkiego Izraela od Nilu Egipskiego aż gdzie się chodzi do Emat, aby przyprowadzili skrzynię Bożą z Karyjatyjarym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'A tak przyszedł Dawid, i wszystek Izrael do Baala w Karyjatyjarym, które jest w Judzie, aby przyprowadzili stamtąd skrzynię Pana Boga siedzącego nad Cherubinami, gdzie wzywane bywa imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'I wieźli skrzynię Bożą na wozie nowym z domu Abinadabowego, a Oza i Achyjo prowadzili wóz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'Lecz Dawid i wszystek Izrael grali przed Bogiem ze wszystkiej mocy, i pieśniami, i na harfach, i na cytrach, i na bębnach, i na cymbałach, i na trąbach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'A gdy przyszli na bojewisko Chydon, ściągnął Oza rękę swą, aby zadzierżał skrzynię; bo woły były wystąpiły z drogi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'I rozgniewał się bardzo Pan na Ozę, i zabił go, przeto iż ściągnął rękę swą ku skrzyni; i umarł tamże przed Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'I zafrasował się Dawid, iż to rozerwanie Pan uczynił w Ozie; a przetoż nazwał ono miejsce Peres Oza, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'I uląkł się Dawid Boga dnia onego, a rzekł: Jakoż mam wprowadzić do siebie skrzynię Bożą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'Przetoż nie wprowadził Dawid skrzyni do siebie, do miasta Dawidowego; ale ją wprowadził do domu Obededoma Gietejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'I została skrzynia Boża między domownikami Obededomowymi w domu jego przez trzy miesiące. I błogosławił Pan domowi Obededomowemu i wszystkiemu, co miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'Potem posłał Hiram, król Tyrski, posłów do Dawida, i drzewa cedrowe, i murarzy i cieśli, aby mu zbudowali dom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'I poznał Dawid, iż go utwierdził Pam królem nad Izraelem, a iż wywyższył królestwo jego dla ludu swego Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, '(I pojął Dawid więcej żon w Jeruzalemie, a spłodził Dawid więcej synów i córek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'A teć są imiona tych, którzy mu się urodzili w Jeruzalemie: Samna, i Sobab, Natan, i Salomon,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'I Ibchar, i Elisua, i Elfalet,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'I Noga, i Nefeg, i Jafija,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'I Elisama, i Beelijada, i Elifelet.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Wtem usłyszawszy Filistynowie, że był pomazany Dawid za króla nad wszystkim Izraelem, wyciągnęli wszyscy Filistynowie, aby szukali Dawida. Co gdy usłyszał Dawid, wyszedł przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Bo Filistynowie przyciągnąwszy rozpostarli się w dolinie Rafaim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'I radził się Dawid Boga, mówiąc: Mamli iść przeciw Filistynom? a podaszli ich w ręce moje? I odpowiedział mu Pan: Idź a podam ich w ręce twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'A gdy oni przyciągnęli do Baal Perazym, poraził ich tam Dawid, i rzekł Dawid: Rozerwał Bóg nieprzyjacioły moje przez rękę moję, jako się rozrywają wody; a przetoż nazwano imię miejsca onego Baal Perazym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'I zostawili tam bogi swoje; a Dawid rozkazał, aby je spalono ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'Lecz zebrawszy się znowu Filistynowie rozpostarli się w dolinie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'Przetoż radził się znowu Dawid Boga. I rzekł mu Bóg: Nie ciągnij za nimi, ale się odwróć od nich, abyś na nich natarł przeciwko morwom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'A gdy usłyszysz szum idącego po wierzchach morwowych, tedy wynijdziesz do bitwy; bo wyszedł Bóg przed tobą, aby poraził wojska Filistyńskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'I uczynił Dawid, jako mu był rozkazał Bóg; i porazili wojska Filistyńskie od Gabaon aż do Gazer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'A tak rozsławiło się imię Dawidowe po wszystkich ziemiach: i sprawił to Pan, że był straszny wszystkim narodom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'A gdy sobie pobudował Dawid domy w mieście swojem, i nagotował miejsce skrzyni Bożej, i rozbił jej namiot,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Tedy rzekł Dawid: Niegodzi się nosić skrzyni Bożej jedno Lewitom. Tych bowiem obrał Pan, aby nosili skrzynię Bożą, i służyli mu aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'Przetoż zebrał Dawid wszystkiego Izraela do Jeruzalemu, aby przeniósł skrzynię Pańską na miejsce jej, które jej był zgotował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'I zgromadził Dawid synów Aaronowych i Lewitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Z synów Kaatowych: Uryjela przedniejszego, i braci jego sto i dwadzieścia,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'Z synów Merarego: Asajasza przedniejszego, i braci jego dwieście i dwadzieścia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'Z synów Giersonowych: Joela przedniejszego, i braci jego sto i trzydzieści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'Z synów Elisafanowych: Semejasza przedniejszego, i braci jego dwieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'Z synów Hebronowych: Elijela przedniejszego, i braci jego ośmdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'Z synów Hasyjelowych: Aminadaba przedniejszego, i braci jego sto i dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'Tedy wezwał Dawia Sadoka i Abijatara, kapłanów, także Lewitów Uryjela, Asajasza, i Joela, Semejasza, i Elijela, i Aminadaba;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'I rzekł do nich: Wyście przedniejsi z domów ojcowskich między Lewitami; poświęćcież się i z braćmi swoimi, abyście przynieśli skrzynię Pana, Boga Izraelskiego, na miejsce, którem jej nagotował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Albowiem iżeście tego pierwej nie uczynili, uczynił rozerwanie Pan, Bóg nasz, między nami; bośmy go nie szukali według przystojności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Poświęcili się tedy kapłani i Lewitowie, aby przynieśli skrzynię Pana, Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'I niesli synowie Lewitów skrzynię Bożą, jako był rozkazał Mojżesz według słowa Pańskiego, na ramionach swych, na drążkach które przy niej były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'I rzekł Dawid przedniejszym z Lewitów, aby postanowili z braci swoich śpiewaków z instrumentami muzycznemi, z lutniami, z cytrami, i z cymbałami, aby słyszany był wyniesiony głos z weselem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'I postanowili Lewitowie Hemana, syna Joelowego, a z braci jego Asafa, syna Barachyjaszowego, a z synów Merarego, braci ich, Etana syna Chysajowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'A z nimi braci ich w rzędzie wtórym: Zacharyjasza, Bena, i Jazyjela, i Semiramota, i Jechyjela, i Unni, Elijaba, i Benajasza, Maasejasza, i Matytyjasza, i Elifelego, i Miknejasza, i Obededoma, i Jehijela, odźwiernych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'A śpiewacy Heman, Asaf, i Etan na cymbałach miedzianych głośno grali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'A Zacharyjasz, i Jazyjel, i Semiramot, i Jechyjel, i Unni, i Elijab, i Maasejasz, i Benajasz grali na lutniach przy śpiewaniu wysokiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'A Matytyjasz, i Elifele, i Miknejasz, i Obededom, i Jechyjel, i Azazyjasz grali na cytrach przy śpiewaniu niskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'A Kienanijasz, przedniejszy z Lewitów, którzy nieśli skrzynię, rozrządzał, jakoby nieść miano; bo był roztropny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'Ale Bacharyjasz i Elkana byli odźwiernymi u skrzyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'A Sebanijasz i Jozafat, i Natanael, i Amasaj, i Zacharyjasz, i Benajasz, i Eliezer, kapłani, trąbili w trąby przed skrzynią Bożą; ale Obededom i Jechyjasz byli odźwiernymi u skrzyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'A tak Dawid i starsi Izraelscy, i hetmani nad tysiącami szli, aby przeprowadzili skrzynię przymierza Pańskiego z domu Obededomowego z weselem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'I stało się, gdy Bóg wspomógł Lewitów, niosących skrzynię przymierza Pańskiego, że ofiarowali siedm wołów, i siedm baranów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'A Dawid był obleczony w szatę bisiorową, także i wszyscy Lewitowie, którzy nieśli skrzynię, i śpiewacy, i Kienanijasz, rządca tych, co nieśli między śpiewakami; a Dawid miał na sobie efod lniany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'A tak wszystek Izrael prowadził skrzynię przymierza PaOskiego z weselem, i z hukiem kornetu, i trąby, i cymbałów, grając na lutniach i na cytrach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'I stało się, gdy skrzynia przymierza Pańskiego wchodziła do miasta Dawidowego, że Michol, córka Saulowa, wyglądając oknem ujrzała króla Dawida skaczącego, i grającego, i wzgardziła go w sercu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'A gdy przynieśli skrzynię Bożą, i postawili ją w pośród namiotu, który był Dawid rozbił, tedy sprawowali całopalenia i ofiary spokojne przed Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'A gdy dokończył Dawid ofiarować całopalenia, i ofiar spokojnych, błogosławił ludowi w imię Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'I rozdzielił wszystkim mężom Izraelskim, od męża aż do niewiasty, każdemu po bochenku chleba, i po sztuce mięsa, i po łagiewce wina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'A postanowił przed skrzynią Pańską z Lewitów sługu, aby wspominali, i wyznawali, i chwalili Pana, Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asaf był przedniejszy, a wtóry po nim Zacharyjasz, Jehyjel, i Semiramot, i Jechyjel i Matytyjasz, i Elijab, i Benajasz, i Obededom, i Jechyjel; ci na instrumentach, na lutniach, na harfach, ale Asaf na cymbałach, grali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'Benajasz zaś i Jachazyjel kapłani z trąbami ustawiczne byli przed skrzynią przymierza Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Dopiero dnia onego najpierwej postanowił Dawid, aby tym psalmem chwalony był Pan przez Asafa i braci jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Wysławiajcie Pana, wzywajcie imienia jego, a opowiadajcie między narodami sprawy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Śpiewajcie mu, grajcie mu, rozmawiajcie o wszystkich cudach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Chlubcie się w imieniu świętem jego, a niech się rozraduje serce szukających Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Szukajcie Pana, i mocy jego; szukajcie oblicza jego zawżdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Wspominajcie dziwne sprawy jego, które czynił, i cuda jego, i sądy ust jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'O nasienie Izraelskie, słudzy jego! O synowie Jakóbowi, wybrani jego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'On jest Pan, Bóg nasz; po wszystkiej ziemi sądy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Pamiętajcie aż na wieki na przymierze jego, na słowow, które przykazał do tysiącznego pokolenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'Które postanowił z Abrahamem, i na przysięgę jego z Izaakiem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'I postanowił to Jakóbowi za prawo, a Izraelowi za przymierze wieczne,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'Mówiąc: Tobie dam ziemię Chananejską za sznur dziedzictwa waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'Choć was była mała liczba, a przez krótki czas byliście przychodniami w niej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'I przechodzili od narodu do narodu, i od królestwa do innego ludu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Nie dopuścił nikomu, aby ich uciskać miał, i karał dla nich królów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, 'Mówiąc: Nie tykajcie pomazańców moich, a prorokom moim nie czyńcie nic złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Śpiewajcie Panu wszystka ziemio; opowiadajcie ode dnia do dnia zbawienie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Opowiadajcie między narodami chwałę jego, i między wszystkimi ludźmi dziwne sprawy jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Bo wielki jest Pan, i chwalebny bardzo, i straszniejszy nad wszystkich bogów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Gdyż bogowie pogańscy są bałwanami; ale Pan niebiosa uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Sława i zacność przed nim, moc i wesele na miejscu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Przynieście Panu pokolenia narodów, przynieście Panu chwałę i moc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Przynieście Panu chwałę imienia jego, przynieście dary, a przychodźcie przed obliczności jego; kłaniajcie się Panu w ozdobie świętobliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Bójcie się oblicza jego wszystka ziemio, a będzie utwierdzony okrąg ziemi, aby się nie poruszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Niech się rozradują niebiosa, a niech się rozweseli ziemia, a niech mówią w narodach: Pan króluje!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Niech zaszumi morze, i ze wszystkiem, co w niem jest; niech się rozraduje pole, i wszystko, co na niem jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Tedy się rozweselą drzewa leśne przed Panem; albowiem przyszedł sądzić ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Wysłwiajcie Pana; albowiem dobry, bo na wieki trwa miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'A mówcie: Zachowaj nas, Boże zbawienia naszego! i zgromadź nas, a wyrwij nas od pogan, abyśmy wielbili imię święte twoje, i chlubili się w chwale twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Błogosławiony Pan, Bóg Izraelski, od wieków aż na wieki. I rzekł wszystek lud Amen, i chwalił Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'I zostawił tam Dawid przed skrzynią przymierza Pańskiego Asafa i braci jego, aby służyli przed skrzynią ustawicznie według potrzeby dnia każdego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'Lecz Obededoma i braci ich sześdziesiąt i ośm, Obededoma mówię, syna Jedytunowego, i Hosę, uczynił odźwiernymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'A Sadoka kapłana, i braci jego kapłanów postawił przed przybytkiem Pańskim na wyżynie, która była w Gabaon,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'Aby ofiarowali całopalenia Panu na ołtarzu całopalenia ustawicznie rano i w wieczór, a to według wszystkiego, co napisano w zakonie Pańskim, który przykazał Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'A z nimi Hemana i Jedytuna, i innych na to obranych, którzy byli z imienia mianowani, aby chwalili Pana, przeto iż na wieki trwa miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'A między nimi Heman i Jedytun, trąbili i grali na trąbach, na cymbałach, i na innych instrumentach muzycznych Bogu; ale synów Jedytunowych postawił u wrót.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'A tak rozszedł się wszystek lud, każdy do domu swego. Dawid się też wrócił, aby błogosławił domowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'I stało się, gdy mieszkał Dawid w domu swym, że rzekł do Natana proroka: Oto ja mieszkam w domu cedrowym, a skrzynia przymierza Pańskiego pod kortynami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'I rzekł Natan do Dawida: Cokolwiek jest w sercu twem, uczyń, gdyż Bóg jest z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Potem onej nocy stało się słowo Boże do Natana, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Idź, a mów do Dawida, sługi mego: Tak mówi Pan: Nie ty mi będziesz budował domu do mieszkania;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Ponieważem nie mieszkał w domu ode dnia, któregom wywiódł synów Izraelskich, aż do dnia tego: alem się przechadzał z namiotu do namiotu, i z przybytku do przybytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Wszędzie gdziemkolwiek chodził ze wszystkim Izraelem, izalim i słowo rzekł któremu z sędziów Izraelskich, którymem rozkazał, aby paśli lud mój, mówiąc: Przeczżeście mi nie zbudowali domu cedrowego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Przetoż teraz tak powiesz słudze memu Dawidowi: Tak mówi Pan zastępów: Jam ciebie wziął z owczarni, gdyś chodził za trzodą, abyś był wodzem nad ludem moim Izraelskim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'I byłem z tobą wszędzie, gdzieśkolwiek chodził, a wygładziłem wszystkich nieprzyjaciół twoich przed twarzą twoją, i uczyniłem ci imię, jako imię wielkich ludzi, którzy są za ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'A postanowiłem miejsce ludowi memu Izraelskiemu, i wszczepiłem go; i będzie mieszkał na miejscu swem, a nie będzie więcej poruszowny, ani go więcej synowie nieprawości trapić, jako przedtem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'Zaraz ode dni, którychem postanowił sędziów nad ludem moim Izraelskim, i poniżyłem wszystkich nieprzyjaciół twoich, i oznajmiłem ci, żeć Pan dom zbuduje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'A gdy się wypełnią dni twoje, abyś szedł za ojcami twoimi, wzbudzę nasienie twoje po tobie, które będzie z synów twoich, i umocnię królestwo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'Ten mi zbuduje dom, i utwierdzę stolicę jego aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Ja mu będę za ojca a on mi będzie za syna, a miłosierdzia mego nie odejmę od niego, jakom je odjął od tego, który był przed tobą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'Owszem postanowię go w domu moim, i w królestwie mojem aż na wieki, a stolica jego będzie trwała aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Według tych wszystkich słów i według wszystkiego widzenia tego, tak mówił Natan do Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Zatem wszedłszy król Dawid, siadł przed obliczem Pańskiem, i rzekł: Cóżem ja jest, Panie Boże! co jest dom mój, żeś mię przywiódł aż dotąd?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'Lecz i to mało było przed oczyma twemi, o Boże! aleś też obietnicę uczynił o domie sługi twego na czas daleki, i wejrzałeś na mię według obyczaju ludzkiego, wywyższając mię, o Panie Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Cóż jeszcze więcej ma mówić Dawid przed tobą o uwielbieniu sługi twego? albowiem ty znasz sługę twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'Panie! dla sługi twego i według serca twego uczyniłeś te wszystkie wielkie rzeczy, abyś znajome uczynił te wszystkie wielmożne sprawy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'Panie! nie masz podobnego tobie, i nie masz Boga oprócz ciebie, wedle wszystkiego, cośmy słyszeli w uszy nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'I któż jest jako lud twój, jako Izrael, naród jedyny na ziemi, dla któregoby Bóg szedł, aby go sobie odkupił za lud, a uczynił sobie imię, czyniąc wielkie rzeczy i straszne, wyganiając pogany przed twarzą ludu twego, któryś wykupił z Egiptu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'I uczyniłeś lud twój Izraelski sobie za lud aż na wieki, a ty Panie! stałeś się im za Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'Przetoż teraz, o Panie! słowo, któreś powiedział o słudze twoim, i o domu jego, niech będzie stwierdzone aż na wieki, a uczyń, jakoś powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Niechajże się tak stanie, i niechaj będzie uwielbione imię twoje aż na wieki, aby mówiono: Pan zastępów, Bóg Izraelski, Bogiem jest nad Izraelem; a dom Dawida, sługi twego, niechaj umocniony będzie przed twarzą twoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Albowiemeś ty, Boże mój! objawił słudze twemu, iż mu zbudujesz dom; przetoż znalazł sługa twój u siebie, aby się modlił przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'A tak o Panie! tyś sam Bóg, a mówiłeś to dobre o słudze swym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'Teraz tedy począłeś błogosławić domowi sługi twego, aby trwał na wieki przed tobą; boś ty Panie! jemu błogosławił, a będzie ubłogosławiony na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'I stało się potem, że poraził Dawid Filistynów i poniżył ich, a wziął Get i wsi jego z rąk Filistynów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Poraził też Moabczyki, i byli Moabczyki sługami Dawidowymi, przynosząc mu hołd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'Poraził też Dawid Hadarezera, króla Soby w Emat, gdy był wyjechał, aby rozprzestrzeniał państwo swoje nad rzeką Eufrates.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'Zabrał mu tedy Dawid tyziąc wozów, i siedm tysięcy jezdnych, i dwadzieścia tysięcy mężów pieszych, i poderznął Dawid żyły wszystkich woźników, zachowawszy z nich koni do sta wozów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Przyciągnęli też Syryjczycy z Damaszku na pomoc Hadarezerowi, królowi Soby; lecz poraził Dawid z Syryjczyków dwadzieścia i dwa tysiące mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Tedy Dawid osadził żołnierzem Syryję Damaską, a byli Syryjczycy sługami Dawidowymi, oddawając mu hołd; i zachowywał Pan Dwida, gdzie się kolwiek obrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'Pobrał też Dawid tarcze złote, które mieli słudzy Hadarezerowi, i wniósł je do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Przytem z Tybchat i z Chun, miast Hadarezerowych, nabrał Dawid miedzi bardzo wiele, z której Salomon sprawił morze miedziane, i słupy, i naczynia miedziane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'A gdy usłyszał Tohy, król Emat, że poraził Dawid wszystko wojsko Hadarezera, króla Soby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'Posłał Adorama, syna swego, do króla Dawida, aby go pozdrowił w pokoju, i aby mu powinszował, przeto, że zwalczył Hadarezera, i poraził go; (albowiem walczył Tohy z Hadarezerem) który przyniósł z sobą wszelakie naczynie złote, i srebrne, i miedziane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Które też poświęcił król Dawid Panu z srebrem i ze złotem, które był pobrał od wszystkich narodów, od Edomczyków, i od Moabczyków, o od synów Ammonowych, i od Filistynów, i od Amalekitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'A Abisaj, syn Sarwii, poraził Edomczyków w dolinie solnej ośmnaście tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'I osadził Edomską ziemię żołnierzem: a byli wszyscy Edomczycy sługami Dawidowymi: i zachowywał Pan Dawida wszędzie, gdzie się obrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'A tak królował Dawid nad wszystkim Izraelem, czyniąc sąd i sprawiedliwość wszystkiemu ludowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'A był Joab, syn Sarwii, nad wojskiem, a Jozafat, syn Ahiludowy, kanclerzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'A Sadok, syn Achitobowy, i Abimelech, syn Abijatara, byli kapłanami, a Susa był pisarzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'Benajasz też, syn Jojady, był przełożonym nad Cheretczykami i Feletczykami; a synowie Dawidowi byli pierwszymi przy boku królewskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'I stało się potem, że umarł Nahas, król synów Ammonowych, a syn jego królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'Tedy rzekł Dawid: Uczynię miłosierdzie nad Hanonem, synem Nahasowym; bo ojciec jego uczynił miłosierdzie nademną. I posłał Dawid posłów, aby go cieszyli po ojcu jego; a tak przyszli słudzy Dawidowi do ziemi synów Ammonowych, do Hanona, aby go cieszyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Ale rzekli książęta synów Ammonowych do Hanona: Mniemasz, żeby Dawid czynił uczciwość ojcu twemu, iż przysłał do ciebie tych, którzyby cię cieszyli; azaż nie dla tego, aby wypatrzyli i wyszpiegowali, i zburzyli tę ziemię, przyszli słudzy jego do ciebie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Przetoż wziąwszy Hanon sługi Dawidowe, ogolił je, i pobrzynał szaty ich od połowy aż do zadków, i puścił ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'Poszli tedy niektórzy, i oznajmili Dawidowi o tych mężach. I posłał przeciwko nim, (ponieważ byli oni mężowie zelżeni bardzo,) i rzekł im król: Zostańcie w Jerycho, aż odrosną brody wasze, potem się wrócicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'A widząc synowie Ammonowi, że się obrzydłymi stali Dawidowi, posłał Hanon i synowie Ammonowi tysiąc talentów srebra, aby sobie najęli za te pieniądze z Mezopotamii i z Syryi Maacha, i z Soby wozy i jezdnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'I najęli sobie za one pieniądze trzydzieści i dwa tysiące wozów, i króla Maacha z ludem jego. Którzy przyciągnąwswzy położyli się obozem przeciw Medeba; a synowie Ammonowi zebrawszy się z miast swych, stawili się do bitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Co gdy usłyszał Dawid, posłał Joaba ze wszystkiem wojskiem ludu rycerskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'A tak wyciągnąwszy synowie Ammonowi uszykowali się do bitwy przed bramą miejską. Królowie zasię, którzy byli przyszli na pomoc, osobno w polu byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Przetoż widząc Joab uszykowane przeciwko sobie wojsko do bitwy z przodku i z tyłu, wybrał niektórych ze wszystkich przebranych z Izraela, i uszykował wojsko przeciw Syryjczykom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'A ostatek ludu dał pod rękę Abisajemu, bratu swemu; i uszykowali się przeciw synom Ammonowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'I rzekł Joab: Jeźli mi będą silnymi Syryjczycy, przyjdziesz mi na pomoc, i jeźli tobie synowie Ammonowi będą silnymi, ja tobie dam pomoc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Zmacniej się, a bądźmy mążnymi za lud nasz, i za miasta Boga naszego, a Pan, co dobrego jest w oczach jego, niech uczyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Nastąpił tedy Joab, i lud, który z ni był, do bitwy przeciwko Syryjczykom; ale oni uciekli przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Tedy synowie Ammonowi ujrzawszy, że uciekali Syryjczycy, uciekli i oni przed Abisaim, bratem jego, i uszli do miasta; a Joab wrócił się do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'A tak widząc Syryjczycy, iż byli porażeni od Izraela, wyprawili posłów, i wywiedli Syryjczyków, którzy byli za rzeką, a Sobach, hetman wojska Hadarezerowego, prowadził ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'I oznajmiono to Dawidowi, który zebrawszy wszystkiego Izraela przeprawił się przez Jordan, a przyciągnąwszy do nich uszykował wojsko przeciwko nim; a gdy uszykował wojsko Dawid przeciwko Syryjczykom ku bitwie, zwiedli z nim bitwę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'Tedy uciekli Syryjczycy przed Izraelem, i poraził Dawid z Syryjczyków siedm tysięcy wozów, i czterdzieści tysięcy mężów pieszych, i Sobacha, hetmana wojska onego, zabił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'Przetoż gdy ujrzeli słudzy Hadarezerowi, iż byli porażeni od Izraela, uczynili pokój z Dawidem, i służyli mu. I nie chcieli napotem Syryjczycy dawać pomocy synom Ammonowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'I stało się po roku tego czasu, gdy królowie zwykli wyjeżdżać na wojnę, iż wywiódł Joab co mężniejsze rycerstwo, i pustoszył ziemię synów Ammonowych, a przyciągnąwszy obległ Rabbę; (lecz Dawid zostawał w Jeruzalemie) i dobył Joab Rabby, i zburzył ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'I wziął Dawid koronę króla ich z głowy jego, a znalazł w niej talent złota, i kamienie bardzo drogie. I włożono ją na głowę Dawidową, i wywiózł łupów z miasta bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'Lud też, który był w nim, wywiódł, i dał ich potrzeć piłami i wozami żelaznemi, i porąbać siekierami. Takci uczynił Dawid wszystkim miastom synów Ammonowych, i wrócił się Dawid ze wszystkim ludem do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Potem znowu gdy była wojna w Gazer z Filistynami, zabił Sobbochaj Husatczyk Syfę, który był z narodu olbrzymów; a tak Filistynowie poniżeni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'Była też jeszcze wojna z Filistynami, gdzie zabił Elchana, syn Jairowy, Lachmiego, brata Golijata Gietejczyka, którego drzewce u włóczni było nawój tkacki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'Nadto jeszcze była wojna w Get, gdzie był mąż wzrostu wielkiego, mając po sześć palców, wszystkich dwadzieścia i cztery; a ten też był z narodu tegoż olbrzyma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Ten gdy urągał Izraelowi, zabił go Jonatan, syn Samaja, brata Dawidowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ci byli synowie jednego olbrzyma z Get, którzy polegli od ręki Dawidowej, i od ręki sług jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'Ale szatan powstał przeciw Izraelowi a pobudził Dawida, aby policzył Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'Przetoż rzekł Dawid do Joaba i do przełożonych nad ludem: Idźcie, obliczcie Izraela od Beerseba aż do Dan, a odnieście do mnie, żebym wiedział poczet ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'Ale rzekł Joab: Niech przymnoży Pan ludu swego, jako teraz jest, tyle sto kroć; izali królu, panie mój! nie są wszyscy oni sługami pana mego? Przeczże się tego dowiaduje pan mój? Przeczżeby to miało być na upadek Izraelowi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Wszakże słowo królewskie przemogło Joaba; przetoż wyszedł Joab, a obszedłszy wszystkiego Izraela, wrócił się potem do Jeruzalem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'I oddał Joab poczet porachowanego ludu Dawidowi. A było wszystkiego Izraela tysiąc tysięcy i sto tysięcy, mężów godnych ku bojowi; a z Judy było cztery kroć sto tysięcy, i siedmdziesięt tysięcy mężów walecznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'Lecz Lwitów i Benjamitów nie policzył między nich, gdyż przykre było rozkazanie królewskie Joabowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'Owszem nie podobała się Bogu ta rzecz; przetoż pokarał Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'I rzekł Dawid do Boga: Zgrzeszyłem bardzo, żem to uczynił; ale teraz oddal, proszę, nieprawość sługi twego; bom bardzo głupio uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'Zatem rzekł Pan do Gada, proroka Dawidowego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Idź, powiedz Dawidowi, a rzecz: Tak mówi Pan: Trzyć rzeczy podaję; obierz sobie jednę z nich, abym ci czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Tedy przyszedł Gad do Dawida, i rzekł mu: Tak mówi Pan: Obierz sobie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'Albo przez trzy lata głód, albo żebyś przez trzy miesiące ginął od nieprzyjaciół twych, a miecz nieprzyjaciół twoich żeby cię ścigał, albo żeby przez trzy dni miecz Pański i mor był w ziemi, a Anioł Pański żeby niszczył wszystkie granice Izraelskie. Przetoż teraz uważ, co mam odpowiedzieć temu, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'I rzekł Dawid do Gada: Bardzom ściśniony; niech wpadnę, proszę, w ręce Pańskie, gdyż bardzo wielkie są zlitowania jego, a w ręce ludzkie niechaj nie wpadam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Tedy przepuścił Pan powietrze morowe na Izraela. I poległo z Izraela siedmdziesiąt tysięcy mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'Posłał też Bóg Anioła do Jeruzalemu, aby ich tracił. A gdy ich tracił, ujrzał Pan, i użalił się nad tem złem, i rzekł Aniołowi tracącemu: Dosyć już, zawściągnij rękę twą. A Anioł Pański stał podle bojewiska Ornana Jebuzejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'Wtem podniósłszy Dawid oczy swe ujrzał Anioła Pańskiego, który stał między ziemią i między niebem, a w ręce jego miecz jego dobyty, wyciągniony przeciw Jeruzalemowi. I upadł Dawid i starsi, oblekłszy się w wory, na twarze swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'Zatem rzekł Dawid do Boga: Izalim nie ja rozkazał liczyć ludu? Jamci jest sam, którym zgrzeszył, i bardzo źle uczynił; ale te owce cóż uczyniły? Panie, Boże mój! niech się obróci, proszę, ręka twoja na mię i na dom ojca mego; ale przeciwko ludowi twemu niech się nie sroży ta plaga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Zatem Anioł Pański rzekł do Gada, aby mówił Dawidowi, żeby szedł i zbudował ołtarz Panu na bojewisku Ornana Jebuzejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'A tak szedł Dawid według słowa Gadowego, które mówił imieniem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Tedy obejrzawszy się Ornan ujrzał onego Anioła; a czterej synowie jego, którzy byli z nim, skryli się; a Ornan młócił pszenicę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'Wtem przyszedł Dawid do Ornana; a spojrzawszy Ornan obaczył Dawida, i wyszedłszy z bojewiska, pokłonił się Dawidowi twarzą do ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'I rzekł Dawid do Ornana: Daj mi plac tego bojewiska, abym zbudował na nim ołtarz Panu; za słuszne pieniądze spuść mi je, a będzie odwrócona ta plaga od ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'I rzekł Ornan do Dawida: Weźmij je sobie, a niech uczyni król, pan mój, co mu się dobrego widzi; otoć przydaję i woły na całopalenia, i wóz na drwa, i pszenicę na ofiarę śniedną: toć to wszystko daję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'I rzekł król Dawid do Ornana: Nie tak, ale raczej kupię za słuszne pieniądze; bo nie wezmę co twego jest, ani będę ofiarował Panu całopalenia darowanego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'A tak Dawid dał Ornanowi za on plac sześć syklów złota dobrej wagi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'I zbudował tam Dawid ołtarz Panu, a ofiarował całopalenia i ofiary spokojne, i wzywał Pana, który go wysłuchał, spuściwszy ogień z nieba na ołtarz całopalenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'I rzekł Pan do Anioła, aby obrócił miecz swój w pochwy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'Onego czasu widząc Dawid, iż go wysłuchał Pan na bojewisku Ornana Jebuzejczyka, ofiarował tam ofiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Albowiem przybytek Pański, który uczynił Mojżesz na puszczy, i ołtarz całopalenia, naonczas był na wyżynie w Gabaonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'A nie mógł Dawid iść do niego, aby się radził Boga; bo przestraszony był mieczem Anioła Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'I rzekł Dawid: Toć jest miejsce domu Pana Boga, i to ołtarz na całopalenie Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'Przetoż rozkazał Dawid, aby zgromadzono cudzoziemców, którzy byli w ziemi Izraelskiej; i postanowił z nich kamienników, aby ciosali kamienie czworograniaste na budowanie domu Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'Żelaza taż bardzo wiele na gwoździe, i na drzwi w bramach, i na spajanie nagotował Dawid, i miedzi wagę niezliczoną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'Drzewa taż cedrowego bez liczby, albowiem nawieźli Dawidowi Sydończycy i Tyryjczycy drzewa cedrowego bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'Bo rzekł był Dawid: Salomon, syn mój, jest młodzieńczykiem małym, a dom ma być zbudowany Panu wielki i znamienity, któregoby imię i sława po wszystkiej ziemi była; przetoż teraz nagotuję mu potrzeb. I nagotował Dawid przed śmiercią swą bardzo wiele potrzeb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'Tedy zawołał Salomona, syna swego, a przykazał mu, aby zbudował dom Panu, Bogu Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'I rzekł Dawid do Salomona: Synu mój! Umyśliłem był w sercu mojem, zbudować dom imieniowi Pana Boga mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Ale się stało do mnie słowo Pańskie, mówiąc: Wieleś krwi rozlał, i wielkieś wojny prowadził; nie będziesz budował domu imieniowi memu, przeto żeś wiele krwi rozlał na ziemię przedemną,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Oto syn, któryć się urodzi, będzie mężem spokojnym; bo mu dam odpocznienie od wszystkich nieprzyjaciół jego zewsząd. Przetoż Salomon będzie imię jego; albowiem pokój i odpocznienie dam Izraelowi za dni jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'On zbuduje dom imieniowi memu; on mi będzie za syna, a ja mu będę za ojca, i utwierdzę stolicę królestwa jego nad Izraelem aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Przetoż Pan będzie z tobą, synu mój! I będzieć się szczęściło, i zbudujesz dom Pana, Boga twego, jako mówił o tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Wszakże niech ci da Pan roztropność, i zmysł, a niech cię postanowi nad Izraelem, abyś strzegł zakonu Pana Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Tedy szczęśliwym będziesz, jeźli strzedz i czynić będziesz przykazania i sądy, które rozkazał Pan przez Mojżesza Izraelowi. Zmacniajże się, a bądź mężem, nie bój się ani się lękaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'A otom ja w utrapieniu mojem nagotował na dom Pański złota sto tysięcy talentów, i srebra tysiąc tysięcy talentów do tego miedzi i żelaza bez wagi, bo tego wiele jest: drzewa także, i kamienia nagotowałem, a ty do tego przyczynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Masz też u siebie wiele rzemieślników, kamiennikówi i murarzy, i cieśli, i wszelkich biegłych w każdem rzemieśle.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Złota, srebra, i miedzi, i żelaza niemasz liczby; wstańże a czyń, a Pan będzie z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'I przykazał Dawid wszystkim książętom Izraelakim, aby pomagali Salomonowi synowi jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Mówiąc: Izali Pan Bóg wasz nie jest z wami, który wam dał odpocznienie zewsząd? Bo dał w rękę moję obywateli tej ziemi, i poddane jest ta ziemia Panu i ludowi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Teraz tedy oddajcie serce swe i duszę swoję, abyście szukali Pana, Boga waszego; i wstańcie, a budujcie świątnicę Panu Bogu, żebyście tam wnieśżli skrzynię przymierza Pańskiego, i naczynia święte Boże, do domu, który będzie zbudowany imieniowi Pańskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'A tak Dawid będąc stary i pełen dni, postanowił królem Salomona, syna swego nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'I zgromadził wszystkich książąt Izraelskich, i kapłanów, i Lewitów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'A policzono Lewitów od trzydziestu lat i wyżej; i był poczet ich według głów ich osób trzydzieści i ośm tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Z których postanowiono na posługę domu Pańskiego dwadzieścia i cztery tysiące, a przełożonych i sędziów sześć tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'Nadto cztery tysiące odźwiernych, i cztery tysiące chwalących Pana na instrumentach, których nasprawiał Dawid ku chwaleniu Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'I rozdzielił ich Dawid na pewne hufy według synów Lewiego, to jest, Giersona, Kaata, i Merarego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Z Giersona byli Laadam, i Semej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Synowie Laadanowi: przedniejszy Jachijel, i Zetam, i Joel, ci trzej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Synowie Semejowi: Salomit, i Hazyjel, i Haran, ci trzej. Cić byli przedniejsi domów ojcowskich z Laadana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'A synowie Semejowi: Jachat, Zyna, i Jehus, i Baryjasz; cić synowie Semejowi czterej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'A Jachat był pierwszym, a Zyza wtóry; ale Jehus i Baryjasz nie mieli wiele synów; przetoż byli w domu ojcowskim policzeni za jednę familiję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Synowie Kaatowi: Amram, Izaar, Hebron, i Husyjel, czterej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Synowie Amramowi: Aaron i Mojżesz. Lecz Aaron był odłączony, aby służył w świątnicy najświętszej, sam i synowie jego aż na wieki, i aby kadzili przed Panem, a służyli mu, i błogosławili w imieniu jego aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Ale synowie Mojżesza, męża Bożego, policzeni są w pokoleniu Lewiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Synowie Mojżeszowi: Gierson i Eliezer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Synowie Giersonowi: Sebujel pierwszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'A synowie Eliezerowi byli Rechabijasz pierwszy. I nie miał Eliezer synów innych; ale synowie Rechabijaszowi rozmnożyli się bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Synowie Izaarowi: Salomit pierwszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Synowie Hebronowi: Jeryjasz pierwszy, Amaryjasz wtóry, Jehazyjel trzeci, a Jekmaan czwarty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Synowie Husyjelowi: Micha pierwszy, a Jesyjasz wtóry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Synowie Merarego: Mahelin i Musy; a synowie Mahelego: Eleazar i Cys.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'I umarł Eleazar, a nie miał synów, tylko córki, które pojmowali synowie Cysowi, bracia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Synowie Musy: Maheli, i Eder, i Jerymot, trzej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Cić są synowie Lewiego według domów ojców swych, przedniejsi domów ojcowskich, którzy policzeni byli według pocztu imion i osób swych z osobna, którzy odprawowali prace usługiwania w domu Pańskim od dwudziestu lat i wyżej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Albowiem rzekł Dawid: Dał odpocznienie Pan, Bóg Izraelski, ludowi swemu, i będzie mieszkał w Jeruzalemie aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'Do tego i Lewitowie nie będą więcej nosić przybytku i wszystkiego naczynia jego ku posługiwaniu jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Ale według postanowienia Dawidowego ostatniego, byli policzeni synowie Lewiego od dwudziestu lat i wyżej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Aby zostawali pod ręką synów Aaronowych ku usłudze domu Pańskiego w przysionkach i w gmachach, i ku oczyszczaniu wszelkich rzeczy poświęconych, i ku pracy około usługi domu Bożego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'I około chleba pokładnego, i około mąki na ofiarę, i około placków niekwaszonych, i około panewek, i około rzeczy smażonych, i około wszelkiej miary i odmierzania;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'A iżby stali na każdy poranek ku wysławianiu, i ku chwaleniu Pana, także i w wieczór;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'Nadto, przy każdem ofiarowaniu całopalenia Panu w sabaty, na nowiu miesiąca, i w uroczyste święta, według liczby i porządku ich ustawicznie przed Panem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'A tak aby pilnowali straży namiotu zgromadzenia, i straży świątnicy, i straży synów Aaronowych, braci swych, w usłudze domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'A synowie Aaronowi tym sposobem rozdzieleni byli: Synowie Aaronowi byli Nedab i Abiju, Eleazar i Itamar;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Ale iż Nadab i Abiju umarli przed obliczem ojca swego, a synów nie mieli: przetoż odprawowali urząd kapłański Eleazar i Itamar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'I podzielił ich Dawid, to jest Sadoka z synów Eleazarowych, i Achimelecha z synów Itamarrowych, według urzędu ich w usługach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'I znalazło się synów Eleazarowych więcej przedniejszych mężów, niż synów Itamarowych, gdy ich podzielił. Z synów Eleazarowych było przedniejszych według domów ojcowskich szesnaście; ale synów Itamarowych według domów ojcowskich ośm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'A rozdzieleni są losem jedni od drugich; bo byli przełożonymi nad świątnicą, i przedniejszymi przed Bogiem, tak z synów Eleazarowych, jako i z synów Itamarowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'A popisał ich Senejasz, syn Natanaelowy, pisarz, z pokolenia Lewiego, przed królem i psiążętami, i przed Sadokiem kapłanem, i Achimelechem, synem Abijatarowym, i przedniejszymi z domów ojcowskich, kapłanów i Lewitów; a naznaczono jeden dom ojcowsk i Eleazarowi, a drugi naznaczono Itamarowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'I padł los pierwszy na Jehojaryba, na Jedajasza wtóry;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'Na Haryma trzeci, na Seoryma czwarty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'Na Malchyjasza piąty, na Mijamana szósty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'Na Akkosa siódmy, na Abijasza ósmy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'Na Jesuego dziewiąty, na Sechenijasza dziesiąty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'Na Eliasyba jedenasty, na Jakima dwunasty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'Na Huppa trzynasty, na Jesebaba czternasty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'Na Bilgę piętnasty, na Immera szesnasty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'Na Chezyra siedmnasty, na Happisesa ośmnasty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'Na Petachyjasza dziewiętnasty, na Ezechyjela dwudziesty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'Na Jachyna dwudziesty i pierwszy, na Gamuela dwudziesty i wtóry;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'Na Delajasza dwudziesty i trzeci, na Maazyjasza dwudziesty i czwarty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'Cić są sporządzeni w posługiwaniu swojem, aby wchodzili do domu Pańskiego w przemianach swych, jako zwykli pod rządem Aarona, ojca ich, jako mu był rozkazał Pan, Bóg Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'A z synów Lewiego, którzy byli pozostali z synów Amramowych, Subajel; z synów Subajelowych Jechdejasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Z Rechabijasza, z synów Rechabijaszowych był przednjiejszy Jesyjasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Z Isaary Salomit, z synów Salomitowych Jachat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'A synowie Jeryjaszowi: Amaryjasz wtóry, Jehazylej trzeci, Jekmaan czwarty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Synowie Husyjelowi Micha; z synów Michy Samir.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Brat Michasowy Jesyjasz; z synów Jesyjaszowych Zacharyjasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Synowie Merarego: Maheli i Musy: synowie Jahasyjaszowi Beno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Sunowie Merarego z Jahasyjasza: Beno, i Soam, i Zachur, i Hybry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Z Mahalego Eleazar, który nie miał synów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Z Cysa, synowie Cysowi Jerahmeel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'A synowie Musy: Maheli i Eder, i Jerymot. Cić byli synowie Lewitów według domów ojców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'I ci też miotali losy naprzeciwko braci swoich, synom Aaronowym, przed Dawidem królem, i Sadokiem, i Achimelechem, i przedniejszymi domów ojcowskich, z kapłanów i Lewitów, z domów ojcowskich, każdy przedniejszy przeciwko bratu swemu młodszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'I odłączył Dawid i hetmani wojska na posługiwanie synów Asafowych i Hemanowych, i Jedytunowych, którzy prorokowali przy cytrach, i przy harfach, i przy cymbałach. A była liczba ich, to jest mążów pracujących w usłudze swej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'Z synów Asafowych: Zachur, i Józef, i Natanijasz, i Asarela. Synowie Asafowi byli pod ręką Asafową, który prorokował na rozkazanie królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Z Jedytuna: Synowie Jedytunowi: Godolijasz, i Zery, i Jesajasz, Hasabijasz, i Matytyjasz, i Symej, sześć, pod ręką ojca ich Jedytuna, który prorokował przy harfie, wyznawając i chwaląc Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Z Hemana: Synowie Hemanowi: Bukkijasz, Matanijasz, Husyjel, Zebuel, i Jerymot, Chananijasz,Chanani, Eliata, Gieddalty, i Romantyjeser, i Jasbekassa, Malloty, Hotyr, Machazyjot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'Ci wszyscy byli synowie Hemana, widzącego królewskiego w słowach Bożych, ku wywyższeniu rogu: bo dał Bóg czternaście synów Hemanowych, i trzy córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Ci wszyscy byli pod sprawą ojca swego przy śpiewaniu w domu Pańskim na cymbałach, na lutniach, i na cytrach ku służbie w domu Bożym, jako rozkazał król, i Asaf, Jedytun, i Heman.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'A był poczet ich z braci ich, którzy byli ćwiczonymi w pieśniach Pańskich, wszystkich mistrzów dwieście ośmdziesiąt i ośm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'I miotali losy, straż przeciwko straży, tak mały jako i wielki, tak mistrz jako i uczeń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'I padł los pierwszy w domu Asafowym na Józefa; na Godolijasza wtóry, z braćmi jego i z synami jego, których było dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Na Zachura trzeci, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Czwarty na Isrego, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Piąty na Natanijasza, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Szósty na Bukkijasza, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Siódmy na Jesarela, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Osmy na Jesajasza, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Dziewiąty na Matanijasza, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Dziesiąty na Symejasza, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Jedenasty na Asarela, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Dwunasty na Hasabijasza, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Trzynasty na Subajela, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Czternasty na Matytyjasza, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Piętnasty na Jerymota, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Szesnasty naChananijasza, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Siedemnasty na Jesbekassa, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Ośmnasty na Chananijego, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Dziewiętnasty na Mallotego, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Dwudziesty na Elijata, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Dwudziesty i pierwszy na Hotyra, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Dwudziesty i wtóry na Gieddaltego, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Dwudziesty i trzeci na Machazyjota, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Dwudziesty i czwarty na Romantyjesera, na synów jego i na braci jego dwanaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Roździały zaś odźwiernych były z Korejczyków: Meselemijasz, syn Korego, z synów Asafowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'A z Meselemijaszowych synów: Zacharyjasz pierworodny, Jadyjael wtóry, Zabadyjasz trzeci, Jatnijel czwarty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Elam piąty, Jachanan szósty, a Elienaj siódmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'A z Obededomowych synów: Semajasz pierworodny, Jozabad wtóry, Joach trzeci, i Sachar czwarty, a Natanael piąty,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Ammijel szósty, Isaschar siódmy, Pechulletaj ósmy; bo mu Bóg błogosławił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Semajaszowi też, synowi jego, zrodzili się synowie, którzy panowali w domu ojca swego; bo byli mężowie bardzo mocni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Synowie Semajaszowi: Otni, i Rafael i Obed, Elzabed, bracia jego, mężowie mocni, Elihu i Semachyjasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Wszyscy ci z synów Obededomowych, sami i synowie ich, i bracia ich, każdy z nich bardzo mocny i sposobny ku posługiwaniu, sześdziesiąt i dwa wszystkich z Obededoma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'A z Meselemijaszowych synów i braci, mężów mocnych, ośmnaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'A z Hosy, który był z synów Merarego, synowie byli: Semry przedniejszy; nie iżby był pierworodny, ale iż go ojciec jego uczynił przedniejszym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Helkijasz wtóry, Tebalijasz trzeci, Zacharyjasz czwarty; wszystkich synów i braci trzynaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Ci są rozdzieleni na odźwiernych, aby byli wrotnymi z mężów przedniejszych, trzymając straż na przemiany z braćmi swymi przy służbie w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'Albowiem miotali losy, tak mały jako wielki według domów ojców swych, o każdą bramę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'I padł los na wschód słońca Selemijaszowy; Zacharyjaszowi także synowi jego, radcy mądremu, rzucili losy, i padł los jego na północy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'A Obededomowi na południe; ale synom jego na dom skarbów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'Suppimowi i Hozie na zachód z bramą Zallechet, przy scieszce usypanej, idącej ku górze; a tak była straż na przeciwko straży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Na wschód słońca było Lewitów sześć, na północy na dzień czterech, na południe na dzień czterech, a przy domu skarbów dwóch a dwóch.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Przy stronie zewnętrznej na zachód było czterech na drodze sypanej, a dwóch przy stronie zewnętrznej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'Teć są roździeły odźwiernych z synów Korego, i z synów Merarego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'A z drugich Lewitów Achyjasz był nad skarbami domu Bożego, to jest nad skarbami rzeczy poświęconych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Synowie Laadanowi, którzy byli z synów Giersonickich: z Laadana Giersończyka przedniejsi w domach ojcowskich, Jehyjel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'A synowie Jehyjlowi byli Zetam, i Joel, brat jego; ci byli nad skarbami domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Z Amramczyków, i z Izaarczyków, z Hebrończyków, i Hysyjelczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'Był Sebuel, syn Giersona, syna Mojżeszowego, przełożony nad skarbami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'Ale bracia jego z Eleazara byli Rechabijasz syn jego, i Jesajasz syn jego, i Joram syn jego, i Zychry syn jego, i Salomit syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Ten Salomit i bracia jego byli na wszystkiemi skarbami rzeczy poświęconych, które był poświęcił Dawid król, i przedniejsi z domów ojcowskich, i półkownicy, i rotmistrze, i hetmani wojska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Bo z wojen i z łupów poświęcali na poprawę domu Pańskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'I wszystko, co był poświęcił Samuel widzący, i Saul, syn Cysowy, i Abner, syn Nera, i Joab, syn Sarwii, i ktokolwiek co poświęcał, oddawał do rąk Salomitowych i braci jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Z Izaarytów: Kienanijasz i synowie jego nad robotą zewnętrzną w Izraelu, byli za urzędników i za sędziów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Z Hebrończyków: Hasabijasz i braci jego, mężów dużych, było tysiąc i siedm set przełożonych nad Izraelem za Jordanem na zachód słońca, w każdej robocie Pańskiej i w posłudze królewskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'A z Hebrończyków był Jeryjasz przedniejszy nad Hebrończykami według narodów ich i domów ojcowskich. Bo roku czterdziestego królestwa Dawidowego szukano i znaleziono między nimi mężów bardzo mocnych w Jazer Galaadskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'A braci jego, mężów godnych, było dwa tysiące i siedm set przedniejszych w domach ojcowskich. I postanowił ich Dawid król nad Rubeńczykami, i nad Gadczykami, i nad połową pokolenia Manasesowego, nad wszystkiemi sprawami Bożemi i sprawami królewskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'A synów Izraelskich według liczby ich, przedniejszych w domach ojcowskich, i półkowników, i rotmistrzów, i przełożonych nad tymi, którzy służyli królowi we wszelkiej potrzebie, w podziałach swoich, przychodzących i odchodzących na każdy miesiąc przez wszystkie miesiące w roku; w każdym podziale było dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Nad hufem pierwszego miesiąca był Jasobeam, syn Sabdyjelowy, a w podziele jego było dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'Ten był z synów Faresowych przedniejszym nad wszystkiemi przełożonymi w wojsku miesiąca pierwszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'A nad podziałem wtórego miesiąca był Dodaj Achochytczyk i z podziałem swym; po nim Michlot, książę, a w podziale jego było ludu dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Przełożony trzeci wojska miesiąca trzeciego był Banajas, syn Jojady kapłana, przedniejszym, a w podziale jego dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'Ten Banajas był mocarz między trzydziestoma, i nad trzydziestoma, a nad podziałem jego był Ammisadab, syn jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Czwarty czwartego miesiąca był Asael, brat Joabowy, a po nim Zabadyjasz, syn jego, a w podziale jego dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Piąty miesiąca piątego był przełożonym Samut Jezrahytczyk, a w podziale jego dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Szósty miesiąca szóstego był Hyra, syn Ikkiessa Tekuitczyka, a w podziale jego dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Siódmy miesiąca siódmego był Heles Felonitczyk z synów Efraimowych, a w podziale jego dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Osmy miesiąca ósmego był Sobochaj Husatczyk z Zarchejczyków, a w podziale jego dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Dziewiąty miesiąca dziewiątego był Abijezer Anatotczyk z synów Jemini, a w podziale jego dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Dziesiąty miesiąca dziesiątego był Mahary Netofatczyk z Zarchejczyków, a w podziale jego dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Jedenasty miesiąca jedenastego był Banajas Faratońszyk z synów Efraimowych, a w podziale jego dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Dwunasty miesiąca dwunastego był Haldaj Netofatczyk z Otonijela, a w podziale jego dwadzieścia i cztery tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Nadto nad pokoleniem Izraelskiem byli: Nad Rubeńczykami był książęciem Elijezer, syn Zychrego; nad Symeończykami Sefatyjasz, syn Maachowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Nad pokoleniem Lewiego Chasabijasz, syn Chemuelowy; nad Aaronowem Sadok;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Nad Judowem Elihu z braci Dawidowych; nad Isascharowem Amry, syn Michaelowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Nad Zabulonowem Jesmajasz, syn Abdyjaszowy; nad Neftalimowem Jerymot, syn Asryjelowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'Nad synami Efraimowymi Hosejasz, syn Azazyjaszowy; nad połową pokolenia Manasesowego Joel, syn Fadajaszowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'Nad drugą połową pokolenia Manasesowego w Galaadzie Iddo, syn Zacharyjaszowy; nad Benjaminowem Jaasyjel, syn Abnerowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Nad Danowem Azraeel, syn Jerohamowy. Cić są książęta pokoleń Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'A nie włożył Dawid w liczbę ich żadnego, co miał dwadzieścia lat i niżej; albowiem Pan był powiedział, iż miał rozmnożyć Izraela jako gwiazdy niebieskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'A Joab, syn Sarwii, począł był liczyć, ale nie dokończył, dlatego że był gniew przypadł na Izraela. I nie weszła ta liczba w liczbę kronik o sprawach króla Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'A nad skarbami królewskiemi był Asmawet, syn Abdyjelowy; a nad dochodami z pól, z miast, i ze wsi i z zamków był Jonatan, syn Uzyjaszowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'A nad oraczami, którzy uprawiali ziemię, był Ezer, syn Chalubowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'A nad winnicami był Semejasz Ramatczyk; a nad urodzajami winnic i nad piwnicami winnemi Zabdyjasz Zyfmejczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'A nad oliwnicami, i nad drzewami figowemi, które są w polach, był Balanan Giedertczyk, a nad piwnicami oliwnemi Joas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'A nad bydłem, które paszono w Saron, Sytraj Saronitczyk; a nad bydłem po dolinach Safat, syn Adlajego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'A nad wielbłądami był Obil Ismaelitczyk, a nad oślicami był Jechdejasz Merończyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'A nad drobnem bydłem Jazys Agiertczyk. Cić wszysct byli przełożonymi nad majętnościami króla Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'Ale Jonatan, stryj Dawidowy, był radcą, mąż mądry, i nauczony; ten, i Jehijel, syn Chachmonowy, był z synami królewskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Achitofel też był radcą królewskim, a Chusaj Archytczyk przyjacielem królewsskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'A po Achitofelu był Jojada, syn Banajasowy, i Abujatar. A Joab był hetmanem wojska królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'Tedy zgromadził Dawid wszystkich książęt Izraelskich, i przedniejszych z każdego pokolenia, i przełożonych nad hyfcami, którzy służyli królowi, i półkowników, i rotmistrzów, i przełożonych nad wszystką majętnością i osiadłością królewską; synów też swoich z komornikami, i z innymi możnymi, i ze wszystkim ludem rycerskim do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'A powstawszy król Dawid na nogi swoje, rzekł: Słuchajcie mię, bracia moi, i ludu mój! Jam był umyślił w sercu swem, budować dom, gdzieby odpoczywała skrzynia przymierza Paćskiego, i na podnóżek nóg Boga naszego, i zgotowałem był potrzeby ku budowaniu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Ale Bóg rzekł do mnie: Nie będziesz budował domu imieniowi memu, przeto żeś mąż waleczny, i rozlewałeś krew.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Ale obrał mię Pan, Bóg Izraelski, ze wszystkiego domu ojca mego, abym był królem nad Izraelem na wieki; bo z Judy obrał księcia, a z narodu Judzkiego dom ojca mego; i z synów ojca mego upodobał mię sobie za króla nad wszystkim Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'A ze wszystkich synów moich (bo mi wiele synów Pan dał) obrał Salomona, syna mego, aby siedział na stolicy królestwa Pańskiego nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'I mówił do mnie: Salomon, syn twój, ten zbydyje dom mój, i przysionki moje; albowiemem go sobie obrał za syna, a Ja mu będę za ojca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'I umocnię królestwo jego aż na wieki, będzieli statecznym w pełnieniu przykazań moich i sądów moich, jako i dziś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Teraz tedy mówię wam pezed obliczem wszystkiego Izraela, zgromadzenia tego Pańskiego, gdzie słyszy Bóg nasz: Strzeżcie a szukajcie wszystkich rozkazań Pana, Boga waszego, abyście osiedli ziemię dobrą, i zostawili ją w dziedzictwo synom swoim po so bie aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'A ty Salomonie, synu mój! znaj Boga, ojca twojego, i służ mu sercem doskonałem, i umysłem dobrowolnym; bo wszystkie serca przegląda Pan, i wszystkie zamusły myśli zna. Jeźli go szukać bądziesz, znajdziesz go, a jeźli go opuścisz, odrzuci cię na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Obaczże teraz, iż cię Pan obrał, abyś zbudował dom świątnicy; zmacniajże się a wykonaj to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Tedy oddał Dawid Salomonowi, synowi swemu, wizerunek przysionka, i gmachów jego, i komor jego, i sal jego, i wnętrznych pokojów jego, i domu ubłagalni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'Przytem wizerunek wszystkiego, co był umyślił o sieni domu Paćskiego, i o wszystkich gmachach dla skarbów domu Bożego, i dla skarbów rzeczy świętych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'I dla pocztów kapłańskich, i Lewitów, i dla wszystkiej pracy w usłudze domu Pańskiego, i dla wszystkiego naczynia służby domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'Także złota pewną wagę na wszystkie naczynia złote, od wszystkiej usługi; srebra także na wszystkie naczynia srebrne pewną wagę, na wszystkie naczynia ku wszelakiej usłudze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'Mianowicie pewną wagę na świeczniki złote i na lampy ich złote według wagi każdego świecznika i lamp jego, i na świeczniki srebrne według wagi świecznika każdego i lamp jego, według potrzeby każdego świecznika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'Także pewnąwagę złota na stoły chlebów pokładbych, na każdy stół, przytem srebra na stoły srebrne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'A na widełki, i na kociołki, i na kadzielnice szczerego złota, i na czasze złote, pewnąwagę na każdą czaszę, i na czasze srebrne, pewną wagę na każdą czaszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'Takżw na ołtarz do kadzeania dał złota szczerego pewną wagę, i złota ku wystawieniu woza Cherubinów, którzyby rozciągnionemi skrzydłami okrywali skrzynię przymierza Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'To wszystko, rzekł Dawid, opisane z ręki Pańskiej mię doszło, abym zrozumiał wszystko, jako co urobić miano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'A tak rzekł Dawid do Salomona, syna swego: Zmacniaj się, a bądź mężnym, czyń to; nie bój się, ani się lękaj; bo Pan Bóg, Bóg mój, będzie z tobą, nie opuści cię, ani cię odstąpi, aż dokończysz wszystkiej roboty służby domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'A oto poczty kapłanów i Lewitów do każdej posługi w domu Bożym bądą z tobą w każdej pracy; każdy ochotny i roztropny przy wszelkiej posłudze, także książęta, i wszystek lud staną na każde rozkazanie twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'Potem mówił król Dawid do wszystkoego zgromadzenia: Salomona, syn mego jedynego, obrał Bóg młodzieńczyka małego. Ale to wielka sprawa; do nie człowiekowi pałac ten, ale Panu Bogu będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Ja według najwyższego przemożenia mego nagotowałem na dom Boga mego złota, na naczynie złote, i srebra na srebrne, i miedzi na miedziane, żelaza na żelazne, i drzewa na drewniane, kamienia onychynowego na osadzanie, i kamienia karbunkułowego, i ro zlicznych farb, a wszelakiego kamienia drogiego, i kamienia marmurowego dostatek wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Nadto z chęci mojej ku domowi Boga mego osobne złoto i srebro, które mam, oddaję na dom Boga mego, oprócz tego wszystkiego, com zgotował na dom świątnicy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'To jest trzy tysiące talentów złota, złota z Ofir, i siedm tysięcy talentów srebra najczystszego na okrycie ścian gmachów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'Złota na naczynie złote, a srebra na srebrne, i na wszystkie roboty rąk rzemieślniczych; i jeźliby jeszcze kto chciał co dobrowolnie dziś ofiarować Panu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Tedy dobrowolnie ofiarowali przedniejsi z domów i przedniejsi z pokoleń Izraelskich, i półkownicy, i rotmistrze, i przełożeni nad robotą królewską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'I złożyli na usługą domu Bożego złota talentíw pięć tysięcy, i złotych dziesięć tysięcy, a srebra talentów dziesięć tysięcy, i midzi ośmnaście tysięcy talentów, a żelaza sto tysięcy talentów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'Ci też co mieli drogie kamienie, dawali je do sksarbu domu Pańskiego, do rąk Jehijela Giersończyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'I weselił się lud, że tak ochotnie ofiaroweali. Albowiem sercem doskonałem chętnie ofiarowali Panu; także i król Dawid weselił się weselem wielkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'Przetoż błogosławił Dawid Panu przed obliczem wszystkiego zgromadzenia, i rzekł: Błogosławionyś ty Panie, Boże Izraela, ojca naszego, od wieku aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Twoja jest, Panie! wielmożność, i moc, i sława, i zwyciąstwo, i cześć, i wszystko na niebie i na ziemi; twoje jest, Panie! królestwo, a tyśjest wywższony nad wszelką zwierzchność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'I bogactwa, i sława od ciebie są, a ty panujesz nad wszystkimi, a w rękach twych jest moc i siła, i w ręce twojej jest wywyższyć i utwierdzić wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Teraz tedy, Boże nasz! wyznajemy cię, a chwalimy imię sławy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Albowiem cużem ja, i co jest lud mój, żebyśmyto siły mieli, tobie to dobrowolnie ofiarować? gdyż od ciebie jest wszystko, a z rąk twoich wziąwszy daliśmy tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Bośmy my pielgrzymami i przychodniami przed tobą, jako i wszyscy ojcowie nasi; dni nasze na ziemi jako cień, a nie masz czego oczekiwać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'O Panie, Boże nasz! ten wszystek dostatek któryśmy zgotowali tobie na budowanie domu imieniowi twemu świętemu, z ręki twojej jest, i twoje jest wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Wiemci ja, Boże mój! iż ty doświadczasz serc a kochasz się w szczerości; przetoż ja w szczerości serca mego, ochotniem pofiarował to wszystko, nawet i lud twój, który się tu znalazł, widziałem z weselem i z ochotą ofiarujący tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'Panie, Boże Abrahama, Izaaka, i Izraela, ojców naszych! zachowajże na wieki tę chęć, i umysł serca ludu twego, a przygotuj sobie serce ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'Salomonowi też, synowi memu daj serce doskonałe, aby strzegł przykazań twoich, świadectw twoich, i ustaw twoich, i czynił wszystko, i aby zbudował dom, dla któregom potrzebu zgotował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'Potem mówił Dawid do wszystkiego zgromadzenia: Błogosławcież teraz Panu, Bogu waszemu. I błogosławiło wszystko zgromadzenie Panu, Bogu ojców sowich, a naczyliwszy się pokłonili się Panu i królowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'I zatem ofiarowali Panu ofiary. Ofiarowali też całopalenia Panu nazajutrz po onym dniu, wołów tysiąc, baranów tysiąc, baranków tysiąc z mokremi ofiarami ich, i inszych ofiar wielkie mnóstwo, za wszystkiego Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'I jedli a pili przed Panem dnia onego z weselem wielkiem, a postanowili powtóre królem Salomona, syna Dawidowego, i pomazali go Panu za księcia, a Sadoka za kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'A tak usiadł Salomon na stolicy Pańskiej za króla miasto Dawida, ojca swego, i szczęściło mu się, a był mu posłuszny wszystek Izrael.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'I wszyscy książęta, i możni, także i wszyscy synowie króla Dawida, dali ręce na poddaństwo Salomonowi królowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'I uwielbił Pan Salomona bardzo zacnie przed oczyma wszystkiego Izraela, a dał mu sławę królewskoą, jakiej żaden król przed nim nie miał w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'A tak Dawid, syn Isajego, królował nad wszystkim Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'A dni, których królował nad Izraelem, było czterdzieści lat; w Hebronie królował siedm lat; a w Jeruzalemie królował trzydzieści i trzy lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'I umarł w starości dobrej, pełen dni, bogactw i sławy: a królował Salomon, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'A sprawy króla Dawida pierwsze i ostatnie, oto są zapisane w księgach Samuela widzącego, i w księdze Natana proroka, i w skiędze Gada widzącego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'Ze wszystkiem królowaniem jego, i możnością jego, i z czasami, które za niego i za Izraela, i za wszystkich królestw ziemskich przeszły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'Zmocnił się tedy Salomon, syn Dawidowy, w królestwie swem, a Pan, Bóg jego był z nim, i uwielbił go wysoce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'I przykazał Salomon wszystkiemu Izraelowi, półkownikom, rotmistrzom, i sędziom, także wszystkim przełożonym nad wszystkim Izraelem, i przedniejszym domów ojcowskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'I szedł Salomon i wszystko zgromadzenie z nim na wyżynę, która była w Gabaonie; albowiem tam był namiot zgromadzenia Bożego, który sprawił Mojżesz sługa Pański, na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, '(Ale skrzynię Bożą przeniósł był Dawid z Karyjatyjarym, nagotowawszy jej miejsce; bo jej był namiot rozbił w Jeruzalemie.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'Ołtarz też miedziany, który był urobił Besaleel, syn Urowy, syna Hurowego, był tam przed przybytkiem Pańskim, gdzie Pana szukał Salomon, i wszystko zgromadzenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'I przystąpił tam Salomon do ołtarza miedzianego, który był przed namiotem zgromadzenia i ofiarował na nim ofiar palonych tysiąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Onejże nocy ukazał się Bóg Salomonowi, i rzekł do niego: Proś czego chcesz, a dam ci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'Tedy rzekł Salomon do Boga: Tyś uczynił z Dawidem, ojcem moim, miłosierdzie wielkie, i postanowiłeś mię królem miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'A teraz, o Panie Boże! niech będzie stałe słowo twoje, któreś mówił do Dawida, ojca mego; boś ty mię uczynił królem nad ludem wielkim, który jest jako proch ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Przetoż daj mi mądrość i umiejętność, abym wychodził i wchodził przed tym ludem: albowiem któż jest, coby mógł sądzić ten lud twój tak wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'Tedy rzekł Bóg do Salomona: Dlatego, iżeś to miał w sercu swem, a nie prosiłeś o bogactwa, o majętności, i o sławę, aniś prosił o wytracenie tych, co cię nienawidzą, aniś też prosił o długie życie, aleś sobie prosił o mądrość i umiejętność, abyś sądził lud mój, nad którymem cię postanowił królem:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'Mądrość i umiejętność dana jest tobie; do tego dam ci bogactwa, i majętność, i sławę, tak, że żaden nie był tobie równy z królów, którzy byli przed tobą, i po tobie nie będzie tobie równy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'I wrócił się Salomon od onej wyżyny, która była w Gabaonie, do Jeruzalemu, od namiotu zgromadzenia, i królował nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'A nazbierał Salomon wozów i jezdnych, i miał tysiąc i cztery sta wozów, i dwanaście tysięcy jezdnych, których rozsadził po miastach wozów, i przy sobie w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'I złożył król w Jeruzalemie złota i srebra, jako kamienia, a cedrów złożył jako sykomorów, których na polu rośnie bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'I przywodzono konie Salomonowi z Egiptu, i rozliczne towary; bo kupcy królewscy brali towary rozliczne za pewne pieniądze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'A wychodzili i przywodzili z Egiptu cug woźników za sześć set srebrników, a konia za sto i za pięćdziesiąt. A tak wszyscy królowie Hetejscy, i królowie Syryjscy z rąk ich koni dostawali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'Umyślił tedy Salomon budować dom imieniowi Pańskiemu, i pałac królewski dla siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'I naliczył Salomon siedmdziesiąt tysięcy mężów, co nosili ciężary, a ośmdziesiąt tysięcy mężów, którzy rąbali drzewo na górze a do nich przystawów trzy tysiące i sześć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'Wyprawił też Salomon do Hirama, króla Tyrskiego, mówiąc: Jakoś się obchodził z Dawidem, ojcem moim, posyłając mu drzewo cedrowe, aby zbudował sobie dom do mieszkania, tak się obejdź ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Oto ja chcę budować dom imieniowi Pana, Boga mego, abym mu go poświęcił, a iżbym kadził przed nim rzeczami wonnemi, i dla ustawicznego pokładania chleba, i dla całopalenia porannego, i wieczornego w sabaty, i na nowiu miesiąców, i w święta uroczys te Pana, Boga naszego, co ma być na wieki w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'A dom, który budować mam, wielki będzie; albowiem większy jest Bóg nasz nad wszystkich bogów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'Acz któż tak wiele przemoże, aby mu mógł dom zbudować? ponieważ go niebiosa, i nieba niebios ogarnąć nie mogą; a ja cóżem jest, żebym mu dom budować miał? chyba tylko dla kadzenia przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Przetoż teraz poślij mi męża umiejętnego, coby umiał robić złotem, i srebrem, i miedzią, i żelazem, i szarłatem, i karmazynem, i hijacyntem, a coby umiał rysować i rzezać z innymi umiejętnymi, którzy przy mnie są w Judzie i w Jeruzalemie, których sporządził Dawid, ojciec mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Poślij mi też drzewa cedrowego, jodłowego, i almugimowego z Libanu; bo ja wiem, iż słudzy twoi umieją wyrąbywać drzewo na Libanie; a oto słudzy moi będą z sługami twoimi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'Aby mi wygotowali drzewa co najwięcej; bo dom, który ja budować chcę, wielki ma być na podziw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'A oto robotnikom sługom twoim, którzy mają wycinać drzewo, dam pszenicy mełtej korcy dwadzieścia tysięcy, i jęczmienia korcy dwadzieścia tysięcy, i wina wiader dwadzieścia tysięcy, i oliwy bareł dwadzieścia tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Tedy odpowiedział Hiram, król Tyrski, przez pisanie, które posłał do Salomona: Iż umiłował Pan lud swój, postanowił cię nad nim królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'I przydał Hiram mówiąc: Błogosławiony Pan, Bóg Izraelski, który uczynił niebo i ziemię, który dał Dawidowi królowi syna mądrego, i umiejętnego, rozumnego, i roztropnego, aby budował dom Panu, i pałac królewski dla siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'Posłałem ci tedy męża mądrego, i umiejętnego, i roztropnego, Chirama Abijego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'Syna niewiasty z córek Danowych, którego ojciec był obywatel Tyrski; który umiał robić złotem, srebrem, miedzią, żelazem, kamieniem, i drzewem, i szarłatem, hijacyntem ze lnu subtelnego, i jedwabiu karmazynowego; który umie rzezać wszelkie rzezanie, i wymyślić rozmaitą misterną robotę, którą mu zadadzą z mądrymi twymi, i z mądrymi pana mego Dawida, ojca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Pszenicę tylko, i jęczmień, oliwę, i wino, co obiecał pan mój, niech przyśle sługom swym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'A my nawycinamy drzewa z Libanu, ileć go będzie potrzeba, i spuścimyć na tratwach po morzu do Joppy, a ty je każesz zwieść do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'Obliczył tedy Salomon wszystkich cudzoziemców, którzy byli w ziemi Izraelskiej po onem policzeniu, którem ich policzył Dawid, ojciec jego, i znalazło się ich sto i pięćdziesiąt tysięcy, i trzy tysiące i sześć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'A postanowił z nich siedmdziesiąt tysięcy, co ciężary nosili, a ośmdziesiąt tysięcy tych, co wyrąbywali na górze, a trzy tysiące i sześć set przystawów nad robotami ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'Począł tedy Salomon budować dom Pański w Jeruzalemie na górze Moryja, która była ukazana Dawidowi, ojcu jego, na miejscu, które zgotował Dawid na bojewisku Ornana Jebuzejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'A począł go budować miesiąca wtórego, dnia wtórego, roku czwartego królestwa swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'Tenci jest pomiar Salomonowy, według którego budował dom Boży, wdłuż łokci sześćdziesiąt, łokci podług miary pierwszej, wszerz łokci dwadzieścia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'Przysionek zasię, który był przed oną długością i przed szerokością domu, był na dwadzieścia łokci, a na wzwyż sto i dwadzieścia łokci; który obłożył wewnątrz szczerem złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'A dom wielki okrył drzewem jodłowem, który też obił szczerem złotem, i dał po wierzchu naczynić palm i łańcuszków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'Nakrył też dom kamieniem drogim ozdobnie, a złoto było złoto parwaimskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Nadto powlekł dom, balki, podwoje, i ściany jego, i drzwi jego złotem, a wyrył Cherubiny na ścianach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'Sprawił też dom świątnicy najświętszej, którego długość była według szerokości domu na dwadzieścia łokci, a szerokość jego na dwadzieścia łokci, i powlekł go złota szczerego sześcią set talentów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'Gwoździe też ważyły pięćdziesiąt syklów złota, także i sale powlekł złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'Sprawił też w domu świątnicy najświętszej dwa Cherubiny robotą misterną, i oprawił je złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'A skrzydła Cherubinów były wdłuż na dwadzieścia łokci; skrzydło jedno na pięć łokci, a dosięgało ściany domu; drugie także skrzydło na pięć łokci dosięgało skrzydła Cherubina drugiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Także skrzydło Cherubina drugiego na pięć łokci dosięgało ściany domu, a skrzydło drugie na pięć łokci skrzydła Cherubina drugiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'A tak skrzydła onych Cherubinów rozszerzone były na dwadzieścia łokci; a oni stali na nogach swych, a twarze ich były w dom obrócone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'Sprawił też zasłonę z hijacyntu, i z szarłatu, i z jedwabiu, i z subtelnego lnu, i dał wyhaftować na niej Cherubiny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'Uczynił też przed domem dwa słupy na trzydzieści i na pięć łokci wzwyż, a gałka, która była na wierzchu ich, każda była na pięć łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'Sprawił też łańcuszki, jako w świątnicy, a przyprawił je na wierzch onych słupów; sprawił też sto jabłek granatowych, które wprawił między one łańcuszki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'I postawił one słupy przed kościołem, jeden po prawej a drugi po lewej stronie; i nazwał imię tego, co był na prawej stronie, Jachyn, a imię tego, co był na lewej stronie, Boaz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'Uczynił też ołtarz miedziany na dwadzieścia łokci wdłuż, i na dwadzieścia łokci wszerz, a na dziesięć łokci wzwyż.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'Dał też urobić i morze odlewane na dziesięć łokci od jednego brzegu aż do drugiego brzegu, okrągłe w około, a na pięć łokci wysokość jego, a okrąg jego był na trzydzieści łokci w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'A pod niem zewsząd w około były podobieństwa wołów, których było dziesięć w łokciu, a otaczały morze w około; a były dwa rzędy tych wołów odlanych pospołu z morzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'A stało na dwunastu wołach, z których trzy patrzały na północy, a trzy patrzały na zachód słońca, a trzy patrzały na południe, a trzy patrzały na wschód słońca; a morze stało na nich na wierzchu, a wszystkie zadki ich były pod morzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'A było miąższe na dłoni; a brzeg jego był jako kraje u kubka nakształt kwiatu lilijowego, a brało w się trzy tysiące wiader.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'Przy tem uczynił wanien dziesięć, i postawił ich pięć po prawej a pięć po lewej stronie, do umywania z nich; wszystko, co należało na całopalenie, obmywano z nich; ale morze było, iżby się kapłani z niego umywali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Uczynił też świeczników złotych dziesięć na ten kształt, jako być miały, i postawił je w kościele, pięć po prawej a pięć po lewej stronie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'Uczynił też stołów dziesięć, które postawił w kościele, pięć po prawej a pięć po lewej stronie; uczynił też czasz złotych sto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'Zbudował też sień kapłańską, i sień wielką, i drzwi u onej sieni, a drzwi ich obił miedzią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'A morze postawił po prawej stronie na wschód słońca ku południowej stronie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'Poczynił też Chiram kotły, i miotły, i miednice.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'A tak dokończył Chiram roboty, którą uczynił Salomonowi królowi do domu Bożego, to jest, słupy dwa z okręgami i z gałkami na wierzchu onych dwóch słupów, i dwie siatki, które okrywały one dwie gałki okrągłe, co były na wierzchu słupów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'Nadto jabłek granatowych cztery sta do onych dwóch siatek, które dwa rzędy jabłek granatowych były na każdej siatce, aby okrywały one dwie gałki okrągłe, które były na wierzchu słupów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'Porobił także podstawki, a wanny postawił na podstawkach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'Morze jedno, a wołów dwanaście pod niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'Do tego kotły, i miotły, i wszystkie naczynia ich porobił Chiram Abi królowi Salomonowi do domu Pańskiego z miedzi czystej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'Na równinach Jordańskich zlewał je król w iłowatej ziemi, między Sochotem i między Saredata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'A tak nasprawiał Salomon naczynia tego wszystkiego bardzo wiele, tak iż wagi miedzi nie dochodzono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'Sprawił także Salomon wszystko naczynie, które należało do domu Bożego, jako ołtarz złoty, i stoły, na których bywały chleby pokładne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'Także świeczniki, i lampy ich z szczerego złota, aby je rozświecano według obyczaju przed świątnicą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'I kwiaty, i lampy, i nożyczki złote, które złoto było wyborne;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'Naczynia też muzyczne, i miednice, i łyżki, i kadzielnice ze złota szczerego, i bramę do domu, drzwi wnętrzne do świątnicy najświętszej, i drzwi do domu, to jest do kościoła ze złota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'A tak dokończona jest wszystka robota, którą sprawił Salomon do domu Pańskiego, i wniósł tam Salomon rzeczy, które był poświęcił Dawid ojciec jego: srebro, i złoto, i wszystkie naczynia włożył do skarbów domu Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Tedy zebrał Salomon starszych z Izraela, i wszystkich przedniejszych z każdego pokolenia, i przedniejszych z ojców synów Izraelskich, do Jeruzalemu, aby przenieśli skrzynię przymierza Pańskiego z miasta Dawidowego, które jest Syon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'I zebrali się do króla wszyscy mężowie Izraelscy w święto uroczyste, które bywa miesiąca siódmego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'A gdy się zeszli wszyscy starsi z Izraela, wzięli Lewitowie skrzynię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'I nieśli skrzynię, i namiot zgromadzenia, i wszystkie naczynia święte, które były w namiocie, przenieśli je kapłani i Lewitowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'Zatem król Salomon, i wszystko zgromadzenie Izraelskie, co się byli zeszli do niego przed skrzynię, ofiarowali owce i woły, których nie można obliczyć, ani obrachować przez mnóstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'Wnieśli tedy kapłani skrzynię przymierza Pańskiego na miejsce jej, do wnętrznego domu, to jest do świątnicy najświętszej pod skrzydła Cherubinów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Albowiem Cherubinowie mieli rozciągnione skrzydła nad miejscem skrzyni, i okrywali Cherubinowie skrzynię, i drążki jej z wierzchu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'I powyciągali one drążki, tak że końce ich było widać z skrzyni na przodku świątnicy; ale ich nie widać było zewnątrz, i tamże zostały aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'A nic nie było w skrzyni, tylko dwie tablice, które tam był włożył Mojżesz na Horebie, gdy stanowił przymierze Pan z synami Izraelskimi po wyjściu ich z Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'A gdy wychodzili kapłani z świątnicy, (bo wszyscy kapłani, ile ich było, poświęcili się byli, a nie przestrzegali porządków.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'Stali Lewitowie śpiewacy, i wszyscy, którzy byli przy Asafie, Hemmanie, i Jedytunie, i synowie ich, i bracia ich, obleczeni będąc w szaty bisiorowe, z cymbałami i z harfami i z cytrami, stali mówię na wschodniej stronie ołtarza, a przy nich kapłanów sto i dwadzieścia trąbiących w trąby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'I stało się, gdy jednostajnie trąbili, i śpiewali, i wydawali jednaki głos, chwaląc i sławiąc Pana: i gdy podnosili głos na trąbach, i na cymbałach, i na innych instrumentach muzycznych, i chwalili Pana, że dobry, że na wieki miłosierdzie jego, tedy dom on napełniony jest obłokiem, to jest dom Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'Tak iż się nie mogli kapłani ostać, i służyć dla onego obłoku; albowiem napełniła była chwała Pańska dom Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Tedy rzekł Salomon: Pan powiedział, iż mieszkać miał we mgle.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'A jam zbudował dom na mieszkanie tobie, o Panie! i miejsce, gdziebyś miał mieszkać na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'A obróciwszy król oblicze swe błogosławił wszystkiemu zgromadzeniu Izraelskiemu, (a wszystko zgromadzenie Izraelskie stało.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'I rzekł: Błogosławiony Pan, Bóg Izraelski, który mówił usty swemi do Dawida, ojca mego, i wypełnił to skutecznie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Ode dnia, któregom wywiódł lud mój z ziemi Egipskiej, nie obrałem miasta ze wszystkich pokoleń Izraelskich ku zbudowaniu domu, gdzieby przebywało imię moje, anim obrał męża, któryby był wodzem nad ludem moim Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'Alem obrał Jeruzalem, aby tam przebywało imię moje; obrałem też i Dawida, aby był nad ludem moim Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Postanowił był Dawid ojciec mój, w sercu swem, zbudować dom imieniowi Pana, Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Ale rzekł Pan do Dawida, ojca mego: Aczkolwiekeś był postanowił w sercu swem, zbudować dom imieniowi memu, i dobrześ uczynił, żeś to umyślił w sercu swem:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Wszakże ty nie będziesz budował tego domu; ale syn twój, który wynijdzie z biódr twych, ten zbuduje dom imieniowi memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'A tak utwierdził Pan słowo swoje, które był powiedział; bom ja powstał miasto Dawida, ojca mego, a usiadłem na stolicy Izraelskiej, jako był powiedział Pan, zbudowałem ten dom imieniowi Pana, Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'Tamżem też postawił skrzynię oną, w której jest przymierze Pańskie, które uczynił z synami Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'Tedy stanął Salomon przed ołtarzem Pańskim, przed wszystkiem zgromadzeniem Izraelskiem, i wyciągnął ręce swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, 'Albowiem był uczynił Salomon stolec miedziany, który postawił w pośród sieni, na pięć łokci wdłuż, a na pięć łokci wszerz, a na trzy łokcie wzwyż; i wstąpił nań a poklęknąwszy na kolana swoje przed wszystkiem zgromadzeniem Izraelskiem, wyciągnął ręce swe ku niebu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'I rzekł: Panie, Boże Izraelski! nie masz tobie podobnego Boga na niebie i na ziemi, który chowasz umowę i miłosierdzie nad sługami twymi, którzy chodzą przed tobą całem sercem swem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'Któryś spełnił słudze twemu Dawidowi, ojcu memu, coś powiedział; i coś mówił usty twemi, toś skutecznie wypełnił, jako się to dziś pokazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'Przetoż teraz, o Panie, Boże Izraelski! spełń słudze twemu Dawidowi, ojcu memu, coś mu był powiedział, mówiąc: Nie będzie odjęty mąż z narodu twego przed twarzą moją, aby nie miał siedzieć na stolicy Izraelskiej, jeźli tylko przestrzegać będą syno wie twoi drogi swej chodząc w zakonie moim, jakoś ty chodził przed oblicznością moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Przetoż teraz, o Panie, Boże Izraelski! niech będzie utwierdzone słowo twoje, któreś mówił do sługi twego Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, '(Aczci wprawdzie, izali Bóg będzie mieszkał z człowiekiem na ziemi? Oto niebiosa, i nieba niebios nie mogą cię ogarnąć, jakoż daleko mniej ten dom, którym zbudował?)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'A wejrzyj na modlitwę sługi twego, i na prośbę jego, o Panie, Boże mój! wysłuchaj wołanie i modlitwę, którą się modli sługa twój przed tobą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'Aby były oczy twoje otworzone nad tym domem we dnie i w nocy; nad tem miejscem, o któremeś powiedział, że tu przebywać będzie imię twoje: abyś wysłuchiwał modlitwę, którą się będzie modlił sługa twój na tem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Wysłuchajże tedy prośbę sługi twego, i ludu twego Izraelskiego, którąć się modlić będą na tem miejscu; ty wysłuchaj z miejsca mieszkania twego, z nieba, a wysłuchawszy bądź miłościw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Gdyby człowiek zgrzeszył przeciwko bliźniemu swemu, a przywiódłby go do przysięgi, tak żeby przysięgać musiał, a przyszłaby przysięga ona przed ołtarz twój w tym domu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'Ty wysłuchaj z nieba, a rozeznaj i rozsądź sług twoich, potępiając niezbożnego, a obracając drogę jego na głowę jego, i usprawiedliwiając sprawiedliwego, a oddawając mu według sprawiedliwości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Gdyby też był porażony lud twój Izraelski od nieprzyjaciela, przeto, iż zgrzeszyli przeciwko tobie, a nawróciliby się, wyznawając imię twoje, i modląc się przepraszaliby cię w tym domu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'Ty wysłuchaj z nieba, a odpuść grzech ludowi twemu Izraelskiemu, a przywróć ich zasię do ziemi, którąś im dał i ojcom ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Także gdyby zawarte było niebo, i nie byłoby deszczu, przeto, że zgrzeszyli tobie, a modliliby się na tem miejscu, wyznawając imię twoje, i od grzechu swego odwróciliby się, gdybyś ich utrapił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'Ty wysłuchaj z nieba, a odpuść grzech sług twoich, i ludu twego Izraelskiego, nauczywszy ich drogi prawej, po której chodzić mają, a daj deszcz na ziemię twoję, którąś dał ludowi twemu w dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Byłliby głód na ziemi, byłliby mór, susza, i rdza, szarańcza i chrząszcze; jeźliby go ścisnął nieprzyjaciel jego w ziemi mieszkania jego, albo jakakolwiek plaga, albo jakakolwiek niemoc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'Wszelką modlitwę, i wszelką prośbę, którąby czynił którykolwiek człowiek, albo wszystek lud twój Izraelski, poznawszy każdy z nich karanie swoje, i boleść swoję, i podniósłby ręce swe w tym domu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'Ty wysłuchaj z nieba, z miejsca mieszkania twego, a odpuść i oddaj każdemu według wszystkich dróg jego, które znasz w sercu jego, (bo ty, ty sam znasz serca synów ludzkich.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'Aby się ciebie bali, i chodzili drogami twemi po wszyskie dni, których żyć będą na ziemi, którąś dał ojcom naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Nadto i cudzoziemiec, który nie jest z ludu twego Iraelskiego, i ten przyjdzieli z ziemi dalekiej dla imienia twego wielkiego, i ręki twej możnej, i dla ramienia twego wyciągnionego; przyjdąli a modlić się będą w tym domu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'Ty wysłuchaj z nieba, z miejsca mieszkania twego, i uczyń to wszystko, o co zawoła do ciebie on cudzoziemiec, aby poznali wszyscy narodowie ziemscy imię twoje, i bali się ciebie jako lud twój Izraelski, i wiedzieli, że imię twoje wzywane jest nad domem tym, którym zbudował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Gdyby wyszedł lud twój na wojnę przeciwko nieprzyjaciołom swoim, drogą, którąbyś ich posłał, i modlilićby się, obróciwszy się ku temu miastu, któreś obrał, i ku domowi, którym zbudował imieniowi twemu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'Wysłuchajże z nieba modlitwy ich, i prośbę ich, a wykonaj sąd ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Gdyby zgrzeszyli przeciwko tobie, (bo nie masz człowieka coby nie grzeszył) a rozgniewawszy się na nich, podałbyś ich pod moc nieprzyjacielowi, któryby ich pojmawszy zawiódł ich w niewolę do ziemi dalekiej, albo bliskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'A upamiętaliby się w sercu swojem w onej ziemi, do której są zaprowadzeni w niewolę, a nawróciwszy się modliliby się w ziemi niewoli swojej, mówiąc: Zgrzeszyliśmy źleśmy uczynili, i niepobożnieśmy się sprawowali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'A nawróciliby się do ciebie z całego serca swego, i z całej duszy swej w ziemi niewoli swojej, do której będąc pojmani zaprowadzeni byli, a modliliby się, obróciwszy się ku ziemi swej, którąś dał ojcom ich, i ku miastu, któreś obrał, i ku domowi, którym zbudował imieniowi twemu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'Wysłuchajże z nieba, z miejsca mieszkania twego, modlitwę ich i prośbę ich, a wykonaj sąd ich, i odpuść ludowi twemu, który tobie zgrzeszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'A tak teraz, o Boże! proszę, niech będą oczy twoje otworzone, i uszy twoje nakłonione ku modlitwie, uczynionej na tem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Teraz tedy powstań, o Panie Boże! ku odpocznieniu twemu, ty i skrzynia mocy twojej; kapłani twoi, o Panie Boże! niech będą obleczeni zbawieniem, a święci twoi niechaj się w dobrach radują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'O Panie Boże! nie odwracaj oblicza od pomazańca twego; pamiętaj na miłosierdzie obiecane Dawidowi, słudze twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'A gdy dokończył Salomon modlitwy, tedy ogień zstąpił z nieba, i pożarł całopalenie i inne ofiary, a chwała Pańska napełniła on dom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'I nie mogli kapłani wnijść do domu Pańskiego, przeto, że chwała Pańska napełniła dom Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'I wszyscy synowie Izraelscy, widząc, gdy zstępował ogień, i chwała Pańska na dom, upadli twarzą swą na ziemię, na tło, a kłaniając się chwalili Pana, że dobry, że na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'A król i wszystek lud sprawowali ofiary przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'Tedy nabił król Salomon na ofiary wołów dwadzieścia i dwa tysiące, a owiec sto i dwadzieścia tysięcy, gdy poświęcali dom Boży król i wszystek lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'Ale kapłani stali w rzędach swych: Lewitowie także z instrumentami muzyki Pańskiej, które był sprawił Dawid król ku chwaleniu Pana, (że na wieki miłosierdzie jego) pieśnią Dawidową, którą im podał. Inni też kapłani trąbili przeciwko nim, a wszyscy Izraelczycy stali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'Nadto poświęcił Salomon pośrodek sieni, która była przed domem Pańskim; bo tam ofiarował całopalenia, i tłustości spokojnych ofiar, przeto, że na ołtarzu miedzianym, który był sprawił Salomon, nie mogły się zmieścić całopalenia, i ofiary śniedne i tłustości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'I obchodził Salomon onego czasu święto uroczyste przez siedm dni, i wszystek Izrael z nim, zgromadzenie bardzo wielkie, od wejścia do Emat aż do rzeki Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, '(Potem uczynili dnia ósmego święto; albowiem poświęcenie ołtarza sprawowali przez siedm dni, i święto uroczyste obchodzili przez siedm dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'A dnia dwudziestego i trzeciego, miesiąca siódmego, rozpuścił lud do przybytków swoich, weselący się i cieszący się w sercu swem z dobrodziejstwa, które uczynił Pan Dawidowi i Salomonowi i Izraelowi, ludowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'A tak dokończył Salomon domu Pańskiego, i domu królewskiego, a wszystko, co był umyślił w sercu swem, uczynić w domu Pańskim i w domu swym, wykonał szczęśliwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'Potem ukazał się Pan Salomonowi w nocy, i rzekł do niego: Wysłuchałem modlitwę twoję, i obrałem to miejsce sobie za dom do ofiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Jeźli zamknę niebo, żeby nie było deszczu, i jeźli rozkażę szarańczy, aby pożarła ziemię; jeźli też poślę powietrze na lud mój;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'A jeźliby się upokorzył lud mój, nad którym wzywano imienia mego, a modliłby się, i szukałby twarzy mojej, odwróciwszy się od dróg swoich złych: tedy Ja wysłucham z nieba, i odpuszczę grzech ich, a uzdrowię ziemię ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Oczy też moje otworzone będą, a uszy moje nakłonione ku modlitwie uczynionej na tem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Bom teraz obrał i poświęcił ten dom, aby tu przebywało imię moje aż na wieki; i będą tu oczy moje, i serce moje po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'A ty będzieszli chodził przede mną, jako chodził Dawid, ojciec twój, a będziesz się sprawował według wszystkiego, com ci przykazał, strzegąc ustaw moich i sądów moich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'Tedy utwierdzę stolicę królestwa twego, jakom uczynił umowę z Dawidem, ojcem twoim, mówiąc: Nie będzie odjęty z narodu twego mąż panujący nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'A jeźli się wy odwrócicie, a opuścicie ustawy moje, i przykazania moje, którem wam podał, a odszedłszy będziecie służyli bogom cudzym, i będziecie się im kłaniali:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'Tedy ich wykorzenię z ziemi mojej, którąm im dał; a ten dom, którym poświęcił imieniowi memu, odrzucę od oblicza mego, i podam go na przypowieść, i na baśń między wszystkie narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'Nadto i ten dom, który był sławny, każdemu mimo idącemu będzie na podziw, i rzecze: Przeczże tak uczynił Pan tej ziemi i temu domowi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'Tedy odpowiedzą: Przeto, iż opuścili Pana, Boga ojców swoich, który ich wywiódł z ziemi Egipskiej, a chwycili się bogów cudzych, i kłaniali się im, i służyli im, dlategoż przywiódł na nich to wszystko złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'A po wyjściu dwudziestu lat, w których budował Salomon dom Pański i dom swój,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'Pobudował też miasta, które był wrócił Hiram Salomonowi, a dał tam mieszkanie synom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'Potem ciągnął Salomon do Emat Soby, i wziął ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'Pobudował też Tadmor na puszczy, i wszystkie miasta, w których miał składy, pobudował w Emat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Nadto zbudował Betoron wyższe i Betoron niższe, miasta obronne w murach, z bramami i z zaworami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'Także Baalat, i wszystkie miasta, w których miał składy Salomon; i wszystkie miasta dla wozów, i miasta dla jezdnych: owa wszystko według upodobania swego, cokolwiek zamyślił budować w Jeruzalemie i na Libanie, i po wszystkiej ziemi panowania sweg o.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Wszystek też lud, który był pozostał z Hetejczyków, i Amorejczyków, i Ferezejczyków, i Hewejczyków, i Jebuzejczyków, którzy nie byli z Izraela:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'Idący z synów ich, którzy byli zostali po nich w onej ziemi, których byli nie wygubili synowie Izraelscy, poczynił Salomon hołdownikami aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'Ale z synów Izraelskich, których nie poczynił Salomon niewolnikami do robót swoich, (bo oni byli mężowie waleczni, i przedniejsi hetmani jego, i przełożeni nad wozami jego i nad jezdnymi jego.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'Z tych było przedniejszych przełożonych, których miał król Salomon, dwieście i pięćdziesiąt panujących nad ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Lecz córkę Faraonową przeniósł Salomon z miasta Dawidowego do domu, który jej był zbudował; albowiem mówił: Nie będzie mieszkała żona moja w domu Dawida, króla Izraelskiego, bo święty jest: przeto iż weszła do niego skrzynia Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Tedy Salomon ofiarował całopalenia Panu na ołtarzu Pańskim, który był zbudował przed przysionkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'Cokolwiek zwyczajnie na każdy dzień ofiarować miano według rozkazania Mojżeszowego w sabaty, na nowiu miesiąca, i w święta uroczyste, trzy kroć do roku, w święto przaśników, i w święto tygodni, i w święto kuczek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'I postanowił według rozrządzenia Dawida, ojca swego, rozdziały kapłanów w posługiwaniu ich, i Lewitów w powinnościach ich, aby chwalili Boga, i służyli przy kapłanach według zwyczaju każdego dnia; odźwiernych też w rzędach ich przy każdej bramie; albowiem tak było rozkazanie Dawida, męża Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'I nie ustąpili od rozkazania królewskiego o kapłanach i o Lewitach, około wszystkich rzeczy i około skarbów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'A tak dogotowano wszystkiego dzieła Salomonowego, od onego dnia, którego założony był dom Pański, aż do wystawienia jego; i tak dokończony był dom Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Tedy jechał Salomon do Asyjongaber i do Elot, które jest nad brzegiem morskim w ziemi Edomskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'I posłał mu Hiram przez rękę sług swoich okręty i żeglarzy świadomych morza, którzy jechali z sługami Salomonowymi do Ofir, a wziąwszy stamtąd czterysta i pięćdziesiąt talentów złota, przynieśli je do króla Salomona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Tedy królowa z Saby słysząc sławę Salomonową, przyjechała do Jeruzalemu, aby doświadczała Salomona w zagadkach, z wielkim bardzo pocztem, i z wielbłądami niosącemi rzeczy wonne, i złota bardzo wiele, i kamienia drogiego, a przyszedłszy do Salomo na, mówiła z nim o wszystkiem, co miała w sercu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'Ale jej odpowiedział Salomon na wszystkie jej słowa, a nie było nic skrytego przed Salomonem, na coby jej nie odpowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Przetoż widząc królowa z Saby mądrość Salomonową, i dom, który zbudował;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'Także potrawy stołu jego, i siadania sług jego, i stawania służących mu, i szaty ich, i podczaszy jego, i szaty ich, i schody, po których wstępował do domu Pańskiego, zdumiewała się bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'I rzekła do króla: Prawdziwać to mowa, którąm słyszała w ziemi mojej o sprawach twoich, i o mądrości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Alem nie wierzyła słowom ich, ażem przyjechawszy oglądała oczyma swemi; ale oto nie powiedziano mi i połowy o wielkiej mądrości twojej; przeszedłeś sławę, o którejm słyszała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Błogosławieni mężowie twoi i błogosławieni ci słudzy twoi, którzy stoją przed tobą zawsze, a słuchają mądrości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Niechże będzie Pan, Bóg twój, błogosławiony, który cię sobie upodobał, aby cię posadził na stolicy swojej za króla przed Panem, Bogiem twoim. Dla tego, iż umiłował Bóg twój Izraela, aby go umocnił na wieki, przetoż postanowił cię nad nimi za króla, abyś czynił sąd i sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'I dała królowi sto i dwadzieścia talentów złota, i rzeczy wonnych bardzo wiele, i kamienia drogiego; a nieprzyszło nigdy więcej takich rzeczy wonnych, jakie dała królowa z Saby królowi Salomonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Nadto i słudzy Hiramowi, i słudzy Salomonowi, którzy byli przywieźli złota z Ofir, przywieźli i drzewa almugimowego, i kamienia drogiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'I poczynił król z onego drzewa almugimowego schody do domu Pańskiego, i do domu królewskiego, i harfy, i lutnie śpiewakom; a nie widziano przedtem nigdy takich rzeczy w ziemi Judzkiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'Król także Salomon dał królowej z Saby wszystko, czego chciała, i czego żądała, oprócz nagrody za to, co była przyniosła do króla. Potem się wróciła, i odjechała do ziemi swej, ona i słudzy jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'A była waga tego złota, które przychodziło Salomonowi na każdy rok, sześć set i sześćdziesiąt i sześć talentów złota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'Oprócz tego, co kupcy, i którzy handlują przynosili; także wszyscy królowie Arabscy, i książęta onej ziemi przywozili złoto i srebro Salomonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'Przetoż uczynił król Salomon dwieście tarczy ze złota ciągnionego; sześć set syklów złota ciągnionego wychodziło na każdą tarczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'Przytem trzysta puklerzy ze złota ciągnionego, trzysta syklów złotych wychodziło na każdy puklerz, które schował król w dom lasu Libanowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'Uczynił także król stolicę wielką z kości słoniowej, i powlókł ją szczerem złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'A sześć stopni było u onej stolicy, a podnóżek był ze złota, trzymający się stolicy; poręcze też były z obudwu stron, kędy siadano, a dwa lwy stały u poręczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'Dwanaście też lwów stało na sześciu stopniach z obu stron; nie było nic takowego urobiono w żadnem królestwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Nadto wszystkie naczynia, z których pijał król Salomon, były złote, i wszystek sprzęt w domu lasu Libanowego ze złota szczerego; nic nie było ze srebra, bo go nie miano w żadnej cenie za dni Salomonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Albowiem okręty królewskie chodziły na morze z sługami Hiramowymi; raz we trzy lata wracały się też okręty z morza, przynosząc złoto, i srebro, kości słoniowe, i koczkodany, i pawie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'A tak uwielbiony jest król Salomon nad wszystkich królów ziemskich, bogactwy i mądrością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'Przetoż wszyscy królowie ziemscy pragnęli widzieć Salomona, aby słuchali mądrości jego, którą był dał Bóg w serce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'I przynosili mu każdy upominek swój, naczynia srebrne, i naczynia złote, szaty, zbroje, i rzeczy wonne, konie i muły, a to na każdy rok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'I miał Salomon cztery tysiące stajen koni i wozów, a dwanaście tysięcy jezdnych, których rozsadził po miastach wozów, i przy sobie w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'I panował nad wszystkimi królmi od rzeki aż do ziemi Filistyńskiej, i aż do granicy Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'A złożył król srebra w Jeruzalemie jako kamienia, a ceder złożył jako płonnych fig, których rośnie na polu bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'Przywodzono też konie Salomonowi z Egiptu i ze wszystkich innych ziem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'A ostatek spraw Salomonowych pierwszych i ostatnich zapisano w księdze Natana proroka, i w proroctwie Achyjasza Sylonitczyka, i w widzeniach Jaddy widzącego, który prorokował przeciw Jeroboamowi, synowi Nabatowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'I królował Salomon w Jeruzalemie nad wszystkim Izraelem czterdzieści lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'Zasnął potem Salomon z ojcami swymi, a pochowano go w mieście Dawida, ojca jego, a Roboam syn jego, królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'Tedy jechał Roboam do Sychem; bo w Sychem zebrał się był wszystek Izrael, aby go postanowił królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'A gdy to usłyszał Jeroboam, syn Nabatowy, który był w Egipcie, gdzie był uciekł przed królem Salomonem, wrócił się Jeroboam z Egiptu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'Bo posłali i wezwali go. Tedy przyszedł Jeroboam i wszystek Izrael, i rzekli do Roboama, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Ojciec twój włożył na nas jarzmo ciężkie; ale ty teraz ulżyj nam niewoli srogiej ojca twego, i jarzma ciężkiego, które włożył na nas, a będziemyć służyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'Który im rzekł: Po trzech dniach wróćcie się do mnie. I odszedł lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'Międzytem wszedł król Roboam w radę z starszymi, którzy stawali przed Salomonem, ojcem jego, za żywota jego, mówiąc: Co wy radzicie? Jakąbym miał dać odpowiedź ludowi temu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'Którzy mu odpowiedzieli, mówiąc: Jeźli dziś powolny będziesz ludowi temu, a uczynisz im kwoli, i będziesz mówił do nich słowa łagodne, będą sługami twymi po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Ale on opuściwszy radę starszych, którą mu podali, wszedł w radę z młodzieńcami, którzy z nim wzrośli i stawali przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'I rzekł do nich: Cóż wy radzicie, abyśmy odpowiedzieli ludowi temu, którzy rzekli do mnie, mówiąc: Ulżyj tego jarzma, które włożył ojciec twój na nas?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Tedy mu odpowiedzieli oni młodzieńcy, którzy z nim wzrośli, mówiąc: Tak odpowiesz temu ludowi, którzy do ciebie rzekli, mówiąc: Ojciec twój włożył na nas ciężkie jarzmo, ale ty ulżyj go nam. Tak rzeczesz do nich: Najmniejszy palec mój mięższy niż biodra ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Przetoż teraz, ojciec mój kładł na was jarzmo ciężkie, ale ja przydam do jarzma waszego; ojciec mój karał was biczykami, a ja was będę karał korbaczami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Przyszedł tedy Jeroboam i wszystek lud do Roboama dnia trzeciego, jako był im rozkazał król, mówiąc: Wróćcie się do mnie dnia trzeciego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'I odpowiedział im król surowie, bo opuścił król Roboam radę starców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'A rzekł do nich według rady młodzieńców, mówiąc: Ojciec mój obciążył was jarzmem ciężkiem, ale ja przydam do niego; ojciec mój karał was biczykami, ale ja was będę karał korbaczami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'I nie usłuchał król ludu: (bo była przyczyna od Boga, aby dosyć uczynił Pan słowu swemu, które był powiedział przez Achyjasza Sylonitczyka do Jeroboama, syna Nabatowego.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'Przetoż widząc wszystek Izrael, że ich król nie usłuchał, odpowiedział lud królowi, mówiąc: Cóż mamy za dział w Dawidzie? a co za dziedzictwo w synu Isajowym? Każdy idź do namiotów swych, o Izraelu! a ty Dawidzie! opatrz teraz dom swój. I rozeszli się wszyscy Izraelczycy do namiotów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'A tak tylko nad synami Izraelskimi, którzy mieszkali w miastach Judzkich, królował Roboam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'I posłał król Roboam Adorama, który był poborcą, i ukamionowali go synowie Izraelscy, że umarł; przetoż król Roboam wsiadłszy co rychlej na wóz, uciekł do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'A tak odstąpili Izraelczycy od domu Dawidowego, aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'Przyjechawszy tedy Roboam do Jeruzalemu, zebrał dom Judowy i pokolenie Benjaminowe, sto i ośmdziesiąt tysięcy mężów przebranych do boju, aby walczyli z Izraelem, a żeby przywrócone było królestwo do Roboama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'I stało się słowo Pańskie do Semejasza, męża Bożego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Powiedz Roboamowi, synowi Salomonowemu, królowi Judzkiemu, i wszystkiemu Izraelowi w Judzie i w pokoleniu Benjaminowem, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Tak mówi Pan: Nie wychodźcie, ani walczcie z braćmi waszymi, wróćcie się każdy do domu swego; albowiem odemnie stała się ta rzecz. I usłuchali słowa Pańskiego, i wrócili się, a nie ciągnęli przeciw Jeroboamowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'I mieszkał Roboam w Jeruzalemie, a pobudował miasta obronne w Judzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'I zbudował Betlehem, i Etam i Tekue;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'I Betsur, i Soko, i Adullam:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'I Get, i Maresa, i Zyf:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'I Adoraim, i Lachis, i Aseka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'I Sora, i Ajalon, i Hebron, które były w Judzie i w pokoleniu Benjaminowem miasta obronne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'A gdy zmocnił one twierdze, postanowił w nich starostów, i wystawił szpichlerze dla zboża, i dla oliwy, i dla wina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'A w każdem mieście złożył tarcze i włócznie, a opatrzył je bardzo mocno: a tak panował nad Judą i Benjaminem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'Kapłani też i Lewitowie, którzy byli we wszystkim Izraelu, zebrali się do niego ze wszystkich granic swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Bo opuściwszy Lewitowie przedmieścia swoje, i osiadłości swoje, szli do Judy i do Jeruzalemu; (gdyż był ich wyrzucił Jeroboam i synowie jego, aby nie odprawowali urzędu kapłańskiego Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'I postanowił sobie kapłanów po wyżynach, i dyjabłom, i cielcom, których był naczynił.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'A za nimi ze wszystkich pokoleń Izraelskich, którzy obrócili serca swe ku szukaniu Pana, Boga Izraelskiego, przyszli do Jeruzalemu, aby ofiarowali Panu, Bogu ojców swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'A tak umocnili królestwo Judzkie, i utwierdzili Roboama, syna Salomonowego, przez trzy lata; albowiem chodzili drogą Dawida i Salomona przez one trzy lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'Potem pojął sobie Roboam za żonę Mahalatę córkę Jerymota, syna Dawidowego, i Abihailę, córkę Elijaba, syna Isajego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'Która mu urodziła synów: Jehusa, i Semaryjasza, i Zaama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'A po niej pojął Maachę, córkę Absalomową, która mu urodziła Abijasza, i Etaja, i Sysę, i Salomitę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'I miłował Roboam Maachę, córkę Absalomową, nad wszystkie żony swoje, i nad założnice swoje. Albowiem pojął był żon ośmnaście, a założnic sześćdziesiąt, i spłodził dwadzieścia i ośm synów i sześćdziesiąt córek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'I postanowił Roboam Abijasza, syna Maachy, za księcia, za hetmana między braćmi jego; albowiem zamyślał go uczynić królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'A roztropnie sobie postępując, rozsadził wszystkich innych synów swych po wszystkich krainach Judzkich i Benjaminowych, po wszystkich miastach obronnych, i opatrzył ich dostatkiem żywności, i nadał im wiele żon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'A gdy utwierdził królestwo swoje Roboam i zmocnił je, opuścił zakon Pański, i wszystek Izrael z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'I stało się roku piątego panowania Roboamowego, że wyciągnął Sesak, król Egipski, przeciw Jeruzalemowi (albowiem byli zgrzeszyli przeciw Panu.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'Z tysiącem i dwoma stami wozów, i z sześćdziesiąt tysięcy jezdnych, a nie było liczby ludu, który przyciągnął z nim z Egiptu, Lubimczyków, Suchymczyków, i Chusymczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'I pobrał miasta obronne, które były w Judzie, i przyciągnął aż ku Jeruzalemowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Tedy Semejasz prorok przyszedł do Roboama i do książąt Judzkich, którzy się byli zebrali do Jeruzalemu, uciekając przed Sesakiem, i rzekł do nich: Tak mówi Pan: Wyście mię opuścili, dla tegom i Ja was opuścił i podał w ręce Sesakowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'I upokorzyli się książęta Izraelscy, i król, i mówili: Sprawiedliwy jest Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'A gdy ujrzał Pan iż się upokorzyli,stało się słowo Pańskie do Semejasza, mówiąc: Upokorzyli się, nie wytracę ich; ale im dam wkrótce wybawienie, ani się wyleje zapalczywość moja przeciw Jeruzalemowi przez ręce Sesaka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Wszakże będą mu za sługi, aby wiedzieli, co to jest, służyć mnie, albo służyć królestwom ziemskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'A tak ciągnął Sesak, król Egipski, przeciw Jeruzalemowi, i pobrał skarby domu Pańskiego, i skarby domu królewskiego, wszystko to pobrał; wziął też tarcze złote, które był sprawił Salomon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'I sprawił król Roboam miasto nich tarcze miedziane, i poruczył je przełożonym nad piechotą, którzy strzegli drzwi domu królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'A gdy wchadzał król do domu Pańskiego, tedy przychodziła piechota, i brali je; potem zasię odnosili je do swoich komor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'A tak iż się upokorzył, odwrócił się od niego gniew Pański, i nie wytracił go do końca; albowiem jeszcze i w Judzie było nieco dobrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'Zmocnił się tedy król Roboam w Jeruzalemie i królował. A było czterdzieści lat i jeden rok Roboamowi, gdy królować począł, a siedmnaście lat królował w Jeruzalemie, w mieście, które obrał Pan ze wszystkich pokoleń Izraelskich, aby tam przebywało imię jego. A imię matki jego było Naama Ammonitka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'Ten czynił złe; bo nie przygotował serca swego, aby szukał Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'Ale sprawy Roboamowe pierwsze i poślednie zapisane są w księdze Semejasza proroka, i Jaddy widzącego; gdzie się opisuje porządek rodzajów, także wojny między Roboamem i Jeroboamem po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'I zasnął Roboam z ojcami swymi, i pochowan jest w mieście Dawidowem, a królował Abijasz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'Roku ośmnastego króla Jeroboama, królował Abijasz nad Judą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Trzy lata królował w Jeruzalemie, a imię matki jego było Michaja, córka Uryjelowa z Gabaa. I była wojna między Abijaszem i między Jeroboamem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'Przetoż Abijasz uszykował wojsko ludzi bardzo walecznych cztery kroć sto tysięcy mężów przebranych; Jeroboam także uszykował się przeciwko niemu, mając ośm kroć sto tysięcy mężów przebranych bardzo walecznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'Tedy stanął Abijasz na wierzchu góry Semeron, która była między górami Efraimskiemi, i rzekł: Słuchajcie mię, Jeroboamie i wszystek Izraelu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Izali wam nie należy wiedzieć, że Pan, Bóg Izraelski, dał królestwo Dawidowi nad Izraelem na wieki, onemu i synom jego przymierzem trwałem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Lecz powstał Jeroboam, syn Nabatowy, sługa Salomona, syna Dawidowego, i stał się odpornym panu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'I zebrali się do niego synowie lekkomyślni, a ludzie niepobożni, i zmocnili się przeciw Roboamowi, synowi Salomonowemu; a Roboam będąc dziecięciem, i serca lękliwego, nie mógł się im mężnie oprzeć:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Zaczem wy się teraz myślicie zmocnić przeciw królestwu Pańskiemu, które jest w rękach synów Dawidowych, a jest was kupa wielka, i macie z sobą cielce złote, których wam naczynił Jeroboam za bogów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Izażeście nie zarzucili kapłanów Pańskich, synów Aaronowych i Lewitów, a poczyniliście sobie kapłanów, jako inni narodowie ziemscy? Ktokolwiek przychodzi, aby poświęcone były ręce jego, z cielcem młodym i siedmią baranów, staje się kapłanem tych, którzy nie są bogowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Ale my jesteśmy Pana, Boga naszego, i nie opuściliśmy go; a kapłani, którzy służą Panu, są synowie Aaronowi, i Lewitowie, którzy pilnują urzędu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'I ofiarują Panu całopalenia na każdy zaranek, i na każdy wieczór, i kadzą rzeczami wonnemi, i pokładają chleby na stole czystym; także świecznik złoty, i lampy jego sporządzaja, aby gorzały na każdy wieczór. A tak my strzeżemy rozkazania Pana, Boga naszego, a wyście go opuścili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'Przetoż oto, z nami jest na czele Bóg i kapłani jego, i trąby głośne, aby brzmiały przeciwko wam. Synowie Izraelscy! nie walczcież z Panem, Bogiem ojców waszych; bo się wam nie powiedzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Międzytem obwiódł zasadzkę Jeroboam, aby na nich przypadli z tyłu; i byli jedni w oczy Judzie, a drudzy na zasadzce z tyłu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'Tedy ujrzawszy synowie Judzcy, że na nich następowała bitwa z przodku i z tyłu, wołali do Pana, a kapłani trąbili w trąby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'Uczynili też okrzyk mężowie Judy. I stało się w onym okrzyku mężów Judzkich, że Bóg poraził Jeroboama, i wszystkiego Izraela przed Abijaszem i Judą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'I uciekali synowie Izraelscy przed Judą; ale ich podał Bóg w ręce ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'I porazili ich Abijasz i lud jego porażką wielką, tak iż legło pobitych z Izraela pięć kroć sto tysięcy mężów na wybór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Przetoż poniżeni są synowie Izraelscy naonczas: a zmocnili się synowie Judzcy, ponieważ spolegali na Panu, Bogu ojców swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'I gonił Abijasz Jeroboama, a odjął mu miasta Betel i wsi jego, i Jesana i wsi jego, i Efron i wsi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'A nie mógł się więcej pokrzepić Jeroboam za dni Abijaszowych, i uderzył go Pan, że umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'Ale Abijasz zmocnił się, i pojął sobie żon czternaście, i spłodził dwadzieścia i dwóch synów, i szesnaście córek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Ale inne sprawy Abijaszowe, i postępki jego, i słowa jego, zapisane są w księdze proroka Jaddy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'A gdy zasnął Abijasz z ojcami swymi, a pochowano go w mieście Dawidowem, tedy królował Aza, syn jego, miasto niego. Za dni jego była w pokoju ziemia, przez dziesięć lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'I czynił Aza co było dobrego, i przyjemnego w oczach Pana, Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'Bo poburzył ołtarze obce, i wyżyny, i podruzgotał bałwany ich, i wyrąbał gaje ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'A przykazał Judzie, aby szukali Pana, Boga ojców swych, i przestrzegali zakonu i przykazań jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Zniósł też ze wszystkich miast Judzkich wyżyny, i słoneczne bałwany, a było w pokoju królestwo za czasu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'Nadto pobudował miasta obronne w Judzie, przeto, iż była w pokoju ziemia i nie powstała wojna przeciwko niemu za onych lat; bo mu dał Pan odpocznienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'I rzekł do Judy: Pobudujmy te miasta, i otoczmy je murem i wieżami, bramami, i zaworami, póki ziemia jest w mocy naszej; bośmy szukali Pana, Boga naszego; szukaliśmy go, i sprawił nam odpocznienie zewsząd. Przetoż budowali, a szczęściło się im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'I miał Aza wojsko noszących tarcz i drzewce: z Judy trzykroć sto tysięcy, a z Benjamina noszących puklerz i ciągnących łuk dwa kroć sto tysięcy i ośmdziesiąt tysięcy. Ci wszyscy byli bardzo mężni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Tedy wyciągnął przeciw nim Zara Etyjopczyk, mając wojska dziesięć kroć sto tysięcy, a wozów trzy sta, i przyciągnął aż do Maresy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Wyciągnął też i Aza przeciw niemu, i uszykowali wojska w dolinie Sefata u Maresy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'Tedy zawołał Aza do Pana, Boga swego, i rzekł: O Panie! ty nie potrzebujesz wielu, abyś ratował tego, który nie ma potęgi. Ratujże nas, o Panie, Boże nasz! gdyż na tobie spolegamy, a w imię twoje idziemy przeciwko temu mnóstwu. Tyś Pan, Bóg nasz; niech nie ma góry nad tobą człowiek śmiertelny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'A tak poraził Pan Etyjopczyków przed Azą i przed Judą, tak iż uciekli Etyjopczycy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'A gonił ich Aza i lud, który był z nim, aż do Gierary. I polegli Etyjopczycy, tak, że nie mogli wskórać: bo starci są przed obliczem Pańskiem i przed wojskiem jego. I nabrali łupów bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'Nadto poburzyli wszystkie miasta około Gierary; albowiem przypadł strach Pański na nich, i splundrowali one wszystkie miasta; bo w nich była wielka korzyść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Także i obory trzód poburzyli; a zająwszy owiec i wielbłądów bardzo wiele, wrócili się do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'Tedy na Azaryjasza, syna Obedowego, przypadł Duch Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'Który wyszedłszy przeciw Azie rzekł mu: Słuchajcie mię, Aza i wszystko pokolenie Judowe i Benjaminowe! Pan był z wami, pókiście byli z nim, a jeźli go szukać będziecie, znajdziecie go: ale jeźli go opuścicie, opuści was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Przez wiele dni był Izrael bez Boga prawdziwego, i bez kapłana, nauczyciela, i bez zakonu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'Wszakże gdyby się byli nawrócili w utrapieniu swem do Pana, Boga Izraelskiego, a szukali go, dałby się im był znaleść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'Ale teraźniejszych czasów niebezpieczno wychodzić i wchodzić; bo zamięszanie wielkie między wszystkimi obywatelami ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'I depcze naród po narodzie, a miasto po mieście, przeto, że ich Bóg strwożył wszelakiem uciśnieniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'Przetoż wy zmacniajcie się, a niech nie słabieją ręce wasze; bo czeka zapłata pracy waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'A gdy usłyszał Aza te słowa, i proroctwo Obeda proroka, zmocnił się, i zniósł obrzydliwości ze wszystkiej ziemi Judzkiej i Benjamińskiej, i z miast, które był pobrał na górze Efraim, i odnowił ołtarz Pański, który był przed przysionkiem Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'Potem zebrał wszystek lud z Judy i z Benjamina, i przychodniów, którzy u nich byli z Efraima, i z Manasesa i z Symeona; bo ich było bardzo wiele zbiegło z Izraela do niego, widząc, iż Pan, Bóg jego, z nim był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'I zgromadzili się do Jeruzalemu miesiąca trzeciego, roku piętnastego królestwa Azy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'I sprawowali ofiary Panu dnia onego z łupów, które byli przygnali, wołów siedm set, a owiec siedm tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'I uczynili umowę, aby szukali Pana, Boga ojców swoich, ze wszystkiego serca swego, i ze wszystkiej duszy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'A ktobykolwiek nie szukał Pana, Boga Izraelskiego, aby był zabity, od najmniejszego aż do największego, od męża aż do niewiast.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'I przysięgli Panu głosem wielkim, i z krzykiem, i z trąbami, i z kornetami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'A weselił się wszystek lud Judzki z onej przysięgi: albowiem ze wszystkiego serca swego przysięgali, i ze wszystkiej ochoty szukali go, i dał się im znaleść, i dał im Pan odpocznienie zewsząd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'Nadto i Maachę, matkę swą, król Aza z państwa złożył, przeto, że była uczyniła w gaju bałwana brzydkiego; i podciął Aza bałwana jej, i pokruszył go, a spalił u potoku Cedron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'A choć wyżyny nie były zniesione z Izraela, przecież serce Azy było doskonałe po wszystkie dni jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'Wniósł też, co był poświęcił ojciec jego, i co sam poświęcił, do domu Bożego, srebro i złoto i naczynia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'A nie było wojny aż do roku trzydziestego i piątego królowania Azy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'Roku trzydziestego i szóstego królowania Azy, wyciągnął Baaza, król Izraelski, przeciwko Judzie, i zbudował Ramę, aby nie dopuścił wychodzić i wchodzić nikomu do Azy, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Tedy wziąwszy Aza srebro i złoto ze skarbów domu Pańskiego i domu królewskiego, posłał je do Benadada, króla Syryjskiego, który mieszkał w Damaszku, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Przymierze jest między mną i między tobą, i między ojcem moim i między ojcem twoim: otoć posyłam srebro i złoto. Idźże, a wzrusz przymierze twoje z Baazą, królem Izraelskim, aby odciągnął odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'I usłuchał Benadad króla Azy, a posławszy hetmanów z wojskami, które miał, przeciwko miastom Izraelskim, zburzył Hijon i Dan i Abelmaim, i wszystkie miasta obronne Neftalimskie, w których były skarby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'To gdy usłyszał Baaza, przestał budować Ramy, i zaniechał roboty swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Tedy król Aza wziąwszy z sobą wszystek lud Judzki, pobrali z Ramy kamienie, i drzewo jego, z którego budował Baaza, a zbudował z niego Gabaa i Masfa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'A onegoż czasu przyszedł Hanani, widzący, do Azy, króla Judzkiego, i mówił do niego: Iżeś spoległ na królu Syryjskim, a nie spoległeś na Panu, Bogu twoim, dlatego uszło wojsko króla Syryjskiego z ręki twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Azaż Etyjopczycy, i Lubimczycy nie mieli wojsk bardzo wielkich z wozami i z jezdnymi w mnóstwie bardzo wielkiem? a wżdy gdyś spoległ na Panu, podał je w rękę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Albowiem oczy Pańskie przepatrują wszystkę ziemię, aby dokazywał mocy swej przy tych, którzy przy nim stoją sercem doskonałem. Głupioś to uczynił: przetoż od tego czasu powstaną przeciwko tobie wojny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'Tedy Aza rozgniewawszy się na widzącego, podał go do więzienia; bo się był nań o to rozgniewał; i utrapił Aza niektórych z ludu onego czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'Ale inne sprawy Azy pierwsze i pośledniejsze, zapisane są w księgach o królach Judzkich i Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'Potem rozniemógł się Aza roku trzydziestego i dziewiątego królowania swego, na nogi swoje, chorobą bardzo ciężką; a wszakże w onej chorobie swej nie szukał Pana, ale lekarzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'A tak zasnął Aza z ojcami swymi, a umarł roku czterdziestego i pierwszego królowania swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'I pochowano go w grobie jego, który sobie był wykopał w mieście Dawidowem; i położono go na łożu, które był napełnił rzeczami wonnemi, i rozmaitemi maściami aptekarską robotą przygotowanemi. I palili mu zapał wonny bardzo wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'Tedy królował Jozafat, syn jego miasto niego, a zmocnił się przeciw Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'I osadził żołnierzem wszystkie miasta Judzkie obronne; osadził też i ziemię Judzką, także miasta Efraimskie, które był pobrał Aza, ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'A był Pan z Jozafatem, przeto, iż chodził drogami pierwszemi Dawida, ojca swego, a nie szukał Baalów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Ale Boga ojca swego szukał, i w przykazaniach jego chodził, a nie według spraw ludu Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'I utwierdził Pan królestwo w ręce jego; a dawał wszystek lud Judzki dary Jozafatowi, tak iż miał bogactwa, i sławę bardzo wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'A nabywszy wielkiego serca na drogach Pańskich, tem więcej znosił wyżyny i gaje bałwochwalcze z ziemi Judzkiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'Potem roku trzeciego królowania swego posłał książąt swoich, Benchaila, i Obadyjasza, i Zacharyjasza, i Natanaela, i Micheasza, aby uczyli w miastach Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'A przy nich Lewitów, Semejasza, i Natanijasza, i Zabadyjasza, i Asaela i Semiramota, i Jonatana, i Adonijasza, i Tobijasza, i Tobadonijasza, Lewitów; a z nimi Elisama, i Jorama, kapłanów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'Którzy uczyli w Judzie, mając z sobą księgi zakonu Pańskiego, i obchodzili wszystkie miasta Judzkie, i nauczali lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'Przetoż przyszedł strach Pański na wszystkie królestwa ziemi, które były około Judy, i nie śmieli walczyć przeciw Jozafatowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'Nawet i Filistynowie przynosili Jozafatowi dary i dań pieniężną. Arabczycy też przygnali mu drobnego bydła, baranów siedm tysięcy i siedm set, kozłów także siedm tysięcy i siedm set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Wzmagał się tedy Jozafat, i rosł nader bardzo, i pobudował w Judzie zamki, i miasta dla składów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'A pracy wiele podjął około miast Judzkich; mężów też walecznych i potężnych miał w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'A tać jest liczba ich według domów ojców ich: z Judy książęta nad tysiącami: książę Adna, a z nim bardzo dużych mężów trzy kroć sto tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'A po nim książę Johanan, a z nim dwa kroć sto tysięcy, i ośmdziesiąt tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'A po nim Amazyjasz, syn Zychry, który się był dobrowolnie oddał Panu, a z nim dwa kroć sto tysięcy mężów dużych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'Przytem z synów Benjaminowych, mąż duży Elijada, a z nim ludu zbrojnego z łukami i z tarczami dwa kroć sto tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'A po nim Jozabad, a z nim sto i ośmdziesięt tysięcy gotowych do boju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Ci służyli królowi, oprócz tych, którymi był król osadził miasta obronne po wszystkiej ziemi Judzkiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'I miał Jozafat bogactw i sławy bardzo wiele, a spowinowacił się z Achabem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'I przyjechał po kilku latach do Achaba do Samaryi; i nabił Achab owiec i wołów wiele dla niego, i dla ludu, który był z nim, i namawiał go, aby ciągnął do Ramot Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'I rzekł Achab, król Izraelski, do Jozafata, króla Judzkiego: Pociągnijże ze mną do Ramot Galaad? A on mu odpowiedział: Jako ja, tak i ty, a jako lud twój, tak lud mój, i będziemy z tobą na wojnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'Nadto rzekł Jozafat do króla Izraelskiego: Proszę, pytaj się dziś słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'A tak zebrał król Izraelski proroków cztery sta mężów, i rzekł do nich: Mamże ciągnąć do Ramot Galaad na wojnę, czyli zaniechać? A oni odpowiedzieli: Ciągnij; bo je da Bóg w ręce królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'Ale Jozafat rzekł: Niemaszże tu jeszcze którego proroka Pańskiego, żebyśmy się go pytali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'I rzekł król Izraelski do Jozafata: Jest jeszcze mąż jeden, przez któregobyśmy się mogli radzić Pana, ale go ja nienawidzę; bo mi nie prorokuje nic dobrego, ale zawżdy złe; a tenci jest Micheasz, syn Jemlowy. I rzekł Jozafat: Niech tak nie mówi król.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Tedy zawołał król Izraelski niektórego komornika, i rzekł: Przywiedź tu rychło Micheasza, syna Jemlowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Międzytem król Izraelski, i Jozafat, król Judzki, siedzieli każdy z nich na stolicy swojej, ubrani w szaty królewskie, a siedzieli na placu u wrót bramy Samaryjskiej, a wszyscy prorocy prorokowali przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'A Sedechyjasz, syn Chanaanowy, sprawił sobie rogi żelazne, i rzekł: Tak mówi Pan: Temi będziesz bódł Syryjczyków, aż ich wyniszczysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'Toż wszyscy prorocy prorokowali, mówiąc: Ciągnij do Ramot Galaad, a będzieć się szczęściło; albowiem je poda Pan, w ręce królewskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Tedy poseł, który chodził, aby przyzwał Micheasza, rzekł do niego, mówiąc: Oto słowa proroków jednemi usty dobrze tuszą królowi; niechże będzie, proszę, słowo twoje jako jednego z nich, a mów dobre rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'I rzekł Micheasz: Jako żyje Pan, że co mi kolwiek rozkaże Bóg mój, to mówić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'A gdy przyszedł do króla, rzekł król do niego: Micheaszu! mamyż ciągnąć na wojnę przeciw Ramot Galaad, czyli zaniechać? A on odpowiedział: Ciągnijcie, a poszczęści się wam, i będą podani w ręce wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'I rzekł król do niego: A wieleż cię razy mam przysięgą zobowiązywać, abyś mi nie mówił jedno prawdę w imieniu Pańskiem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'Przetoż rzekł: Widziałem wszystek lud Izraelski rozproszony po górach jako owce, które nie mają pasterza; bo Pan rzekł: Nie mająci Pana; niech się wróci każdy do domu swego w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'I rzekł król Izraelski do Jozafata: Izażem ci nie powiadał, że mi nic dobrego prorokować nie miał, ale złe?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'Ale on rzekł: Słuchajcież tedy słowa Pańskiego: Widziałem Pana siedzącego na stolicy jego, i wszystko wojsko niebieskie stojące po prawicy jego i po lewicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'I rzekł Pan: Kto zwiedzie Achaba, króla Izraelskiego, aby szedł, a poległ w Ramot Galaad? A gdy mówił jeden tak, a drugi mówił inaczej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Wystąpił duch, i stanął przed Panem, i rzekł: Ja go zwiodę. A Pan mu rzekł: Przez cóż?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'I odpowiedział: Wynijdę, a będę kłamliwym duchem w ustach wszystkich proroków jego. I rzekł Pan: Zwiedziesz, i pewnie przemożesz: Idźże, a uczyń tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Przetoż teraz, oto dał Pan ducha kłamliwego w usta tych proroków twoich, gdyż Pan wyrzekł przeciwko tobie złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Tedy przystąpiwszy Sedechijasz, syn Chanaanowy, uderzył Micheasza w policzek, mówiąc: A którąż drogą odszedł duch Pański odemnie, aby mówił z tobą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'I odpowiedział Micheasz: Oto ty ujrzysz dnia onego, kiedy wnijdziesz do najskrytszej komory, abyś się skrył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'I rzekł król Izraelski: Weźmijcie Micheasza, a odwiedźcie go do Amona, starosty miejskiego, i do Joaza, syna królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'I rzeczecie im: Tak mówi król: Wsadźcie tego do więzienia, a dawajcie mu jeść chleb utrapienia, i wodę ucisku, aż się wrócę w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'Ale odpowiedział Micheasz: Jeźliże się wrócisz w pokoju, tedy nie mówił Pan przez mię. Nadto rzekł: Słuchajcież wszyscy ludzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'A tak ciągnął król Izraelski, i Jozafat, król Judzki, do Ramot Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'I rzekł król Izraelski do Jozafata: Odmienię się, a pójdę do bitwy: ale ty ubierzesz się w szaty swe. I odmienił się król Izraelski, a szli do bitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'A król Syryjski rozkazał był hetmanom, którzy byli nad wozami jego, mówiąc: Nie potykajcie się ani z małym ani z wielkim, tylko z samym królem Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'A gdy ujrzeli Jozafata hetmani, co byli nad wozami, rzekli: Król Izraelski jest. I obrócili się przeciw niemu, aby się z nim potykali; ale zawołał Jozafat, a Pan go ratował; i odwrócił ich Bóg od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Bo obaczywszy hetmani, co byli nad wozami, że nie ten był król Izraelski, odwrócili się od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Lecz niektóry mąż strzelił na niepewne z łuku, i postrzelił króla Izraelskiego, między nity i między pancerz; który rzekł woźnicy swemu: Nawróć, a wywieź mię z wojska; bom jest raniony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'I wzmogła się bitwa dnia onego, a król Izraelski stał na wozie przeciw Syryjczykom aż do wieczora: i umarł, gdy zachodziło słońce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'A gdy się wracał Jozafat, król Judzki, do domu swego w pokoju, do Jeruzalemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'Wyszedł przeciwko niemu Jehu, syn Hananiego, widzący, i rzekł do króla Jozafata: Izaliś niezbożnemu miał pomagać, a tych, którzy nienawidzą Pana, miłować? Przetoż nad tobą jest gniew Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Wszakże znalazły się sprawy dobre w tobie, przeto, żeś powycinał gaje święcone z ziemi, a zgotowałeś serce swe, abyś szukał Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'A pomieszkawszy Jozafat w Jeruzalemie wyjechał zaś, i objechał lud od Beersaby aż do góry Efraimskiej, i nawrócił ich do Pana, Boga ojców swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'I postanowił sędziów w ziemi po wszystkich miastach Judzkich obronnych, w każdem mieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'Tedy rzekł do sędziów: Baczcież, co czynicie; bo nie ludzki sąd odprawujecie, ale Pański, który jest z wami przy sprawie sądowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'A przetoż niechaj będzie bojaźń Pańska z wami; przestrzegajcież tego, a tak się sprawujcie; bo nie masz u Pana, Boga naszego, nieprawości, i niema względu na osoby, ani przyjmuje darów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Także i w Jeruzalemie postanowił Jozafat niektórych z Lewitów, i z kapłanów, i z przedniejszych domów ojcowskich w Izraelu, dla sądu Pańskiego, i dla sporów tych, którzy się udawali do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'I przykazał im, mówiąc: Tak czyńcie w bojaźni Pańskiej, wiernie, i sercem doskonałem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'A przy wszystkich sporach, któreby przyszły przed was od braci waszych, którzy mieszkają w miastach swych, między krwią a krwią, między zakonem a przykazaniem, ustawami i sądami, napominajcie ich, aby nie grzeszyli przeciwko Panu, aby nie przyszedł gniew na was, i na braci waszych. Tak czyńcie, a nie zgrzeszycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'A oto Amaryjasz, kapłan najwyższy, będzie między wami we wszystkich sprawach Pańskich; a Zabadyjasz, syn Ismaelowy, książę w domu Judzkim, we wszystkich sprawach królewskich: także Lewitowie będą rządzcami między wami. Zmacniajcież się, a tak czyńcie, a Pan będzie z dobrym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'I stało się potem, że przyciągnęli synowie Moabowi, i synowie Ammonowi, a z nimi niektórzy mieszkający z Ammonitami, przeciwko Jozafatowi na wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'I przyszło, a opowiedziano Jozafatowi, mówiąc: Przyciągnęło przeciwko tobie wojsko wielkie z zamorza, z Syryi, a oto są w Chasesontamar, które jest Engaddy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'I uląkł się, a obrócił Jozafat twarz swoję, aby szukał Pana, i zapowiedział post wszystkiemu ludowi Judzkiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'Tedy się zgromadził lud Judzki, aby szukali Pana; także ze wszystkich miast Judzkich zeszli się szukać Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'A tak stanął Jozafat w zgromadzeniu Judzkiem i Jeruzalemskiem w domu Pańskiem przed sienią nową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'I rzekł: Panie, Boże ojców naszych: Izaliś nie ty sam Bogiem na niebie? a nie ty panujesz na wszystkiemi królestwami narodów? azaż nie w rękach twoich jest moc i siła? a nie masz, ktoby się mógł ostać przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Izaliś nie ty, Boże nasz! wypędził obywateli tej ziemi przed twarzą ludu twego Izraelskiego, i podałeś ją nasieniu Abrahama przyjaciela twego na wieki?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'I miszkali w niej, i zbudowali tobie w niej świątnicę dla imienia twego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Jeźliby na nas przyszło złe, miecz pomsty, albo powietrze, albo głód, a staniemy przed tym domem, i przed obliczem twojem, gdyż imię twoje jest w domu tym, a zawołamy do ciebie w uciskach naszych, tedy wysłuchasz i wybawisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'Teraz tedy, oto synowie Ammonowi, i Moabowi, i góra Seir, przez którycheś ty nie dopuścił przejść Izraelowi, gdy szli z ziemi Egipskiej, ale ich minęli, a nie wytracili ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'Oto teraz nam oni oddawają, gdyż przyszli, aby nas wyrzucili z dziedzictwa twego, któreś nam dał prawem dziedzicznem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'O Boże nasz! izali ich nie będziesz sądził? W nasci zaiste nie masz żadnej mocy przeciw mnóstwu tak wielkiemu, które przyszło na nas, i nie wiemy, co czynić mamy, tylko ku tobie obracamy oczy nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'Wszystek też lud Judzki stał przed Panem, i dziatki ich, żony ich, i synowie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Ale Jehazyjel, syn Zacharyjasza, syna Benajaszowego, syna Jehyjelowego, syna Matanijaszowego, Lewita z synów Asafowych, na którego przyszedł Duch Pański w pośród onego zgromadzenia,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'Rzekł: Słuchajcie wszyscy z Judy, i obywatele Jeruzalemscy, i ty królu Jozafacie! Tak wam powiada Pan: Nie bójcie się wy, ani się lękajcie tego mnóstwa tak wielkiego; nie wasza jest walka, ale Boża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Jutro się ruszcie przeciwko nim; oto oni pójdą stroną góry Sys, i znajdziecie ich na końcu potoku przeciw puszczy Jeruel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Nie wy się potykać będziecie w tej bitwie; stawcie się, i stójcie, a oglądajcie wybawienie Pańskie nad wami, o Judo, i Jeruzalemie! Nie bójcież się, ani się lękajcie; jutro wynijdziecie przeciwko nim, a Pan będzie z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'I pokłonił się Jozafat twarzą ku ziemi, a wszystek lud Judzki, i obywatele Jeruzalemscy padli przed obliczem Pańskiem, kłaniając się Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Wstali też Lewitowie z synów Kaatowych, i z synów Korego, i chwalili Pana, Boga Izraelskiego, głosem wielkim i wyniosłym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'Potem wstawszy rano ciągnęli na puszczę Tekuła; a gdy wychodzili, stanął Jozafat, i rzekł: Słuchajcie mię Judo, i obywatele Jeruzalemscy! Wierzcie Panu, Bogu waszemu, a będziecie bezpieczni; wierzcież prorokom jego, a będzie się wam szczęściło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'A wszedłszy w radę z ludem, postanowił śpiewaków Panu, którzyby go chwalili w ozdobie świętobliwości, idąc przed uszykowanymi do bitwy, i mówiąc: Wysławiajcie Pana, albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'A wtenczas, gdy oni zaczęli śpiewanie i chwały, obrócił Pan zasadzkę na synów Ammonowych i Moabowych, i na obywateli góry Seir, która była przyszła przeciw Judzie, i bili się sami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Bo powstali synowie Ammonowi i Moabowi przeciwko obywatelom góry Seir, aby ich pobili i wygładzili. A gdy już do końca porazili onych, co mieszkali w Seir, oburzył się jeden przeciw drugiemu, aż się spólnie wybili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'A wtem lud Judzki przyszedł do Masfa, blisko puszczy; i spojrzawszy na ono mnóstwo widzieli, a oto trupy leżały po ziemi, tak iż nikt nie uszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'Przetoż przyszedł Jozafat i lud jego, aby rozchwycili łupy ich; i znaleźli przy nich bardzo wiele bogactw i na trupach klejnotów kosztownych, których rozchwycili między się tak wiele, że ich zanieść nie mogli: przez trzy dni brali one łupy, albowiem ich było bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'Potem dnia czwartego zebrali się w dolinie Beracha; bo iż tam błogosławili Pana, przetoż nazwali imię miejsca onego doliną Beracha, aż do dzisiejszego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Zatem obrócili się wszyscy mężowie Judzcy i Jeruzalemscy, i Jozafat przed nimi, aby się wrócili do Jeruzalemu z radością; albowiem ucieszył ich był Pan nad nieprzyjaciołami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'I wjechali do Jeruzalemu z harfami, i z cytrami, i z trąbami, do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'Tedy przypadł strach Boży na wszystkie królestwa ziemi, gdy usłyszały, iż Pan walczył przeciw nieprzyjaciołom ludu Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'A tak uspokoiło się królestwo Jozafatowe, bo mu dał odpocznienie Bóg jego zewsząd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'I królował Jozafat nad Judą, a miał trzydzieści i pięć lat, gdy królować począł, a dwadzieścia i pięć lat królował w Jeruzalemie; a imię matki jego było Azuba, córka Salajowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'A chodził drogą ojca swego Azy, i nie uchylał się od niej, czyniąc co było dobrego w oczach Pańskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Wszakże wyżyny nie były zniesione; bo jeszcze lud nie zgotował był serca swego ku Bogu ojców swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'A ostatek spraw Jozafatowych pierwszych i poślednich jest zapisany w księdze Jehu, syna Hananiego, któremu było rozkazane, aby to włożył w księgi królów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'Potem stowarzyszył się Jozafat, król Judzki, z Ochozyjaszem, królem Izraelskim, którego sprawy były bardzo niepobożne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'A stowarzyszył się z nim na to, aby nabudowali okrętów, któreby chodziły do Tarsys; i budowali one okręty w Asjongaber.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Przetoż prorokował Eliezer, syn Dodawahowy z Maresy, przeciw Jozafatowi mówiąc: Iżeś się stowarzyszył z Ochozyjaszem, rozerwał Pan sprawy twoje, i porozbijały się okręty, i nie mogły iść do Tarsys.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'Potem zasnął Jozafat z ojcami swymi, i pochowany jest z ojcami swymi w mieście Dawidowem, a królował Joram, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'Który miał braci, synów Jozafatowych: Azaryjasza i Jehijela, i Zacharyjasza, i Azaryjasza, i Michaela, i Sefatyjasza; wszyscy ci byli synowie Jozafata, króla Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'Którym był dał ojciec ich upominków wiele, srebra i złota, i rzeczy kosztownych z miastami obronnemi w Judzie; ale królestwo oddał Joramowi, ponieważ on był pierworodny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Nastąpił tedy Joram na królestwo ojca swego, a zmocniwszy się pozabijał wszystkich braci swoich mieczem, także i niektórych z przedniejszych w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Trzydzieści i dwa lata miał Joram, gdy począł królować, a ośm lat królował w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'I chodził drogami królów Izraelskich, jako czynił dom Achabowy, bo córka Achabowa była żoną jego; i czynił złe przed oczyma Pańskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Ale nie chciał Pan wytracić domu Dawidowego, dla przymierza, które był uczynił z Dawidem, a iż był przyrzekł dać mu pochodnię i synom jego po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'Za jego dni odstąpili Edomczycy, aby nie byli poddanymi Judzie, a postanowili nad sobą króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Przetoż się ruszył Joram z hetmanami swymi, i ze wszystkiemi wozami swemi, a wstawszy w nocy, poraził Edomczyków, którzy go byli otoczyli i hetmanów wozów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Ale przecież odstąpili Edomczycy, aby nie byli pod mocą Judy, aż do dnia tego; odstąpiła też i Lebna tegoż czasu, aby nie była pod mocą jego, przeto, iż był Joram opuścił Pana, Boga ojców swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Nadto nabudował wyżyn po górach Judzkich, i przywiódł w cudzołóstwo obywateli Jeruzalemskich, i przymuszał jako i Judę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'Tedy przyszło do niego pisanie od Elijasza proroka w ten sposób: Tak mówi Pan, Bóg Dawida, ojca twego: Przeto, iżeś nie chodził drogami Jozafata, ojca twego, i drogami Azy, króla Judzkiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'Aleś chodził drogą królów Izraelskich, a przywiodłeś w cudzołóstwo Judę, i obywateli Jeruzalemskich, tak jako cudzołożył dom Achabowy; nadto i braci twoich, dom ojca twego, lepszych nad cię, pomordowałeś:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'Otoż Pan uderzy plagą wielką lud twój, i synów twoich, i żony twoje, i wszystkę majętność twoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'Na cię też przyjdą niemocy wielkie, boleść wnętrza twego, aż wypłyną trzewa twoje dla boleści dzień ode dnia cięższej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'A tak pobudził Pan przeciwko Joramowi ducha Filistyńczyków, i Arabczyków, którzy byli pograniczni Etyjopczykom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'Którzy wtargnąwszy do ziemi Judzkiej, splundrowali ją i pobrali wszystkę majętność, która się znalazła w domu królewskim; do tego i synów jego, i żony jego, tak, iż mu nie został syn, jedno Joachaz, najmłodszy z synów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'A nad to wszystko zaraził go Pan na wnętrzu jego niemocą nieuleczoną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'A gdy dzień po dniu następował, a czas dwóch lat wychodził, wypłynęły wnętrzności jego z boleścią, i umarł w niemocach ciężkich; a nie uczynił mu lud jego przy pogrzebie zapału, jako czynili zapał ojcom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Trzydzieści i dwa lata miał, gdy królować począł, a ośm lat królował w Jeruzalemie, a zszedł tak, iż go nikt nie żałował; i pogrzebiony jest w mieście Dawidowem, wszakże nie w grobach królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'Tedy postanowili królem obywatele Jeruzalemscy Ochozyjasza, syna jego najmłodszego, miasto niego; bo wszystkich starszych pobiła była kupa swawolna, która była przyszła z Arabczykami do obozu, a tak królował Ochozyjasz, syn Jorama, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Czterdzieści i dwa lata było Ochozyjaszowi, gdy począł królować, a jeden rok królował w Jeruzalemie; a imię matki jego było Atalija, córka Amrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Ten też chodził drogami domu Achabowego; bo matka jego radziła mu, aby się niepobożnie sprawował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Przetoż czynił złe przed oczyma Pańskiemi, jako dom Achabowy; tych bowiem miał za radców swoich po śmierci ojca swego, na zginienie swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'Bo według rady ich chodził, i jechał z Joramem, synem Achabowym, królem Izraelskim, na wojnę przeciw Hazaelowi, królowi Syryjskiemu, do Ramot Galaadzkiego, kędy zranili Syryjczycy Jorama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'A gdy się wrócił, aby się leczył w Jezreelu, (albowiem miał rany, które mu zadano w Ramie, gdy się potykał z Hazaelem, królem Syryjskim) tedy Azaryjasz, syn Jorama, króla Judzkiego, przyjechał do Jezreela, nawiedzać niemocnego Jorama, syna Achabowego, bo był chory.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'A było to od Boga na upadek Ochozyjaszowi, że przyjechał do Jorama. Albowiem przyjechawszy wyjechał z Joramem przeciw Jehu, synowi Namsy, którego był pomazał Pan, aby wytracił dom Achabowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'A gdy sąd wykonywał Jehu nad domem Achabowym, znalazł niektórych książąt Judzkich, i synów braci Ochozyjaszowych, którzy służyli Ochozyjaszowi, i pobił ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Potem szukał Ochozyjasza, i pojmali go, gdy się krył w Samaryi, a przywiódłszy go do Jehu, zabili go, i pogrzebli go, bo mówili: Synci to jest Jozafata, który szukał Pana całem sercem swojem. A tak nie było nikogo w domu Ochozyjaszowem, któryby mógł otrzymać królestwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Przetoż Atalija, matka Ochozyjaszowa, widząc, że umarł syn jej, wstawszy wytraciła wszystko nasienie królewskie z domu Judy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Ale Josabet, córka królewska, wzięła Joaza, syna Ochozyjaszowego, i wykradła go z pośród synów królewskich, których zabijano, i schowała go i mamkę jego do gmachu, gdzie były łoża. I skryła go Josabet, córka króla Jorama, żona Jojady kapłana, (bo ona była siostrą Ochozyjaszową) przed Ataliją, aby go nie zabiła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'I był z nimi w domu Bożym, będąc skrytym przez sześć lat, których Atalija królowała nad tą ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'A siódmego roku zmocniwszy się Jojada, zaciągnął rotmistrzów, Azaryjasza, syna Jerohamowego, i Ismaela, syna Johananowego, i Azaryjasza, syna Obedowego, i Maasajasza, syna Adajaszowego, i Elizafata, syna Zychry, z sobą w przymierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Którzy obchodząc Judzką ziemię zebrali Lewitów ze wszystkich miast Judzkich, i przedniejszych z domów ojcowskich w Izraelu, a przyszli do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'I uczyniło wszystko zgromadzenie przymierze w domu Bożym z królem; bo im był rzekł Jojada: Oto syn królewski będzie królował, jako powiedział Pan o synach Dawidowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'Toć jest co uczynicie: Trzecia część z was, którzy przychodzicie w sabat z kapłanów i z Lewitów, będzie odźwiernymi w bramach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'A trzecia część będzie w domu królewskim, a trzecia część w bramie fundamentu; ale wszystek lud zostanie w sieniach domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'A niechaj nikt nie wchodzi w dom Pański, tylko kapłani, a usługujący Lewitowie; ci niechaj wchodzą, albowiem są poświęceni; ale wszystek inny lud niech trzyma straż Pańską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'I obstąpią Lewitowie króla zewsząd, mając każdy broń swą w ręce swej; a ktobykolwiek wszedł w dom, niech będzie zabity; a bądźcie przy królu, gdy będzie wchodził, i gdy będzie wychodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'I uczynili Lewitowie, i wszystek lud Judzki, według wszystkiego, co był rozkazał Jojada kapłan; i wziął każdy mężów swych, którzy przychodzili w sabat i którzy odchodzili w sabat, bo był nie rozpuścił Jojada kapłan pocztów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'I rozdał Jojada kapłan rotmistrzom włócznie, i tarcze, i puklerze, które były króla Dawida, które były w domu Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'Postawił też wszystek lud; a każdy miał broń w ręce swej, od prawej strony domu, aż do lewej strony domu przeciwko ołtarzowi, i domowi, około króla zewsząd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Zatem wywiedli syna królewskiego, i włożyli nań koronę i świadectwo, a postanowili go królem; i pomazali go Jojada i synowie jego, i mówili: Niech żyje król!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Wtem usłyszawszy Atalija krzyk zbiegającego się ludu, i chwalącego króla, weszła do ludu do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'A gdy ujrzała, że król stał na majestacie swoich w wejściu, i książęta i trąby około króla, i wszystek lud onej ziemi weselący się, i trąbiący w trąby, i śpiewaki z instrumentami muzycznemi, i tych, którzy zaczynali śpiewanie, tedy rozdarła Atalij a szaty swoje, mówiąc: Sprzysiężenie! sprzysiężenie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'Przetoż rozkazał wynijść Jojada kapłan rotmistrzom i hetmanom wojska, i rzekł do nich: Wywiedźcie ją z zagrodzenia kościoła, a ktoby za nią szedł, niech będzie zabity mieczem; bo był kapłan rzekł: Nie zabijajcie jej w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'I uczynili jej plac. A gdy przyszła ku wejściu bramy, którą wodzono konie do domu królewskiego, tamże ją zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Tedy uczynił Jojada przymierze między Panem, i między wszystkim ludem, i między królem, aby byli ludem Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'Potem wszedł wszystek lud do domu Baalowego, i zburzyli go, i ołtarze jego, i bałwany jego połamali, Matana także kapłana Baalowego zabili przed ołtarzami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'I postanowił znowu Jojada przełożonych nad domem Pańskim pod rządem kapłanów i Lewitów, których był rozrządził Dawid w domu Pańskim, aby ofiarowali całopalenia Panu, jako napisano w zakonie Mojżeszowym, z weselem, i z pieśniami, według rozrządzenia Dawidowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'Postawił też odźwiernych u bram domu Pańskiego, aby tam nie wchodził nieczysty dla jakiejkolwiek rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'Potem wziąwszy rotmistrzów i przedniejszych, i tych, którzy panowali nad ludem, i wszystek lud onej ziemi, prowadzili króla z domu Pańskiego; i przyszli bramą wyższą do domu królewskiego, a posadzili króla na stolicy królestwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'I weselił się wszystek lud onej ziemi, i uspokoiło się miasto, gdy Ataliję zabili mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'W siedmiu latach był, Joaz, gdy królować począł, a czterdzieści lat królował w Jeruzalemie. Imię matki jego było Sebija z Beersaby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'I czynił Joaz, co było dobrego przed oczyma Pańskiemi, po wszystkie dni Jojady kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'A Jojada dał mu dwie żony; i płodził synów i córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'I stało się potem, że umyślił w sercu swojem Joaz odnowić dom Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'Przetoż zebrawszy kapłanów i Lewitów rzekł do nich: Wynijdźcie do miast Judzkich, i wybierajcie od wszystkiego Izraela pieniądze na poprawę domu Boga waszego na każdy rok, a wy się z tem pospieszcie; ale się nie spieszyli Lewitowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Tedy wezwał król Jojady, przedniejszego kapłana, i rzekł mu: Przeczże się nie upominasz u Lewitów, aby znosili z Judy i z Jeruzalemu podarki postanowione przez Mojżesza, sługę Pańskiego, zgromadzeniu Izraelskiemu, na namiot zgromadzenia?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Bo Atalija niezbożna i synowie jej wyłupili dom Boży, a wszystkie rzeczy poświęcone z domu Pańskiego obrócili na bałwany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Przetoż rozkazał król, aby uczyniono skrzynię jednę, a postawiono ją przed bramą domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'I obwołano w Judzie i w Jeruzalemie, aby znoszono Panu podarek postanowiony przez Mojżesza, sługę Bożego, na Izraela na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'I weselili się wszyscy książęta, i wszystek lud, a przynosząc, rzucali do onej skrzyni, aż ją napełnili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'A gdy przynosili skrzynię na rozkaz królewski przez ręce Lewitów, (gdy widzieli, że było wiele pieniędzy) przychodził pisarz królewski, i przystaw kapłana najwyższego, i wypróżniali skrzynię; potem ją odnosili, i stawiali ją na miejscu swem. Tak czynili na każdy dzień, i zebrali pieniędzy bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'Które oddawał król i Jojada przełożonym nad robotą około domu Pańskiego; a ci najmowali kamienników i cieśli do poprawy domu Pańskiego, także i kowali robiących żelazem i miedzią, ku zmocnieniu domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'A tak robili robotnicy, i brało naprawę ono dzieło przez ręce ich; i przywiedli dom Boży do całości swojej, i zmocnili go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'A gdy dokończyli, przynieśli przed króla i przed Jojadę ostatek pieniędzy, a narobiono z nich naczynia do domu Pańskiego, naczynia ku posługiwaniu, i moździerzy i czasz, i innego naczynia złotego i srebrnego, a ofiarowali całopalenia w domu Pańsk im ustawicznie po wszystkie dni Jojady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'Potem zstarzał się Jojada, a będąc pełen dni, umarł; sto i trzydzieści lat miał, gdy umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'I pochowano go w mieście Dawidowem z królmi, przeto, że czynił dobrze w Izraelu, i Bogu, i domowi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'A gdy umarł Jojada, przyszli książęta Judzcy, i pokłonili się królowi; tedy ich usłuchał król.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'Skąd opuściwszy dom Pana, Boga ojców swych, służyli gajom i bałwanom; przetoż przyszedł gniew na Judę i na Jeruzalem dla tego występku ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'I posyłał do nich proroków, żeby ich nawrócili do Pana; którzy choć się oświadczali przeciw nim, ale ich przecież nie słuchali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Owszem, gdy Duch Boży wzbudził Zacharyjasza, syna Jojady kapłana, (który stanąwszy przed ludem, rzekł im: Tak mówi Bóg: Przeczże przestępujecie przykazania Pańskie? Nie poszczęści się wam; albowiem iżeście wy opuścili Pana, on was też opuści.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Tedy się sprzysięgli przeciwko niemu, i ukamionowali go za rozkazaniem królewskim w sieni domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'I nie pamiętał król Joaz na miłosierdzie, które był uczynił z nim Jojada, ojciec jego, ale zabił syna jego; który gdy umierał, mówił: Niech to obaczy Pan, a zemści się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'I stało się po roku, przyciągnęło przeciwko niemu wojsko Syryjskie, a przyszło do Judy i do Jeruzalemu, i wygładzili z ludu wszystkich książąt ich, a wszystkie łupy ich posłali królowi w Damaszku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Bo w małym poczcie ludu przyciągnęło było wojsko Syryjskie; a wżdy Pan podał w ręce ich bardzo wielkie wojsko, przeto, iż opuścili Pana, Boga ojców swoich. A tak nad Joazem wykonali sądy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'A gdy odciągnęli od niego, zostawiwszy go w wielkich niemocach, sprzysięgli się przeciwko niemu słudzy jego dla krwi synów Jojady kapłana, i zabili go na łożu jego. I tak umarł, a pochowano go w mieście Dawidowem; ale go nie pochowano w grobach królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'A cić są, którzy się byli sprzysięgli przeciw niemu: Zabat, syn Semaaty Ammonitki, i Jozabat, syn Semaryty Moabitki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'Lecz o synach jego, i o wielkim podatku nań włożonym, i o naprawie domu Bożego, to wszystko napisane w księgach królewskich; i królował Amazyjasz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Dwadzieścia i pięć lat miał Amazyjasz, gdy królować począł, a dwadzieścia i dziewięć lat królował w Jeruzalemie. Imię matki jego Joadana, z Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'I czynił co było dobrego przed oczyma Pańskiemi, wszakże nie doskonałem sercem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'I stało się, gdy było utwierdzone królestwo jego, że pomordował sługi swe, którzy zabili króla, ojca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Wszakże synów ich niepobił: ale uczynił, jako napisano w zakonie, w księgach Mojżeszowych, gdzie przykazał Pan, mówiąc: Nie umrą ojcowie za synów, ani synowie umrą za ojców, ale każdy za grzech swój umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Tedy zgromadził Amazyjasz lud Judzki, i postanowił ich według domów ojcowskich za półkowników i za rotmistrzów po wszystkiem pokoleniu Judowem, i Benjaminowem, a policzywszy ich od dwudziestu lat i wyżej, znalazł ich trzy kroć sto tysięcy na wybór, gotowych do boju, noszących drzewce i tarczę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Najął także za pieniądze z Izraela sto tysięcy mężów dużych za sto talentów srebra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'Lecz mąż Boży przyszedł do niego mówiąc: Królu! niech nie wychodzi z tobą wojsko Izraelskie; bo nie masz Pana z Izraelem i ze wszystkimi synami Efraimowymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Ale jeźli mi nie wierzysz, idź, i zmocnij się ku bitwie, a porazi cię Bóg przed nieprzyjacielem; bo w mocy Bożej jest ratować, i do upadku przywieść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Tedy rzekł Amazyjasz mężowi Bożemu: A cóż mam czynić z tem stem talentów, którem dał wojsku Izraelskiemu? Odpowiedział mąż Boży: Ma Pan skąd ci może dać daleko więcej nadto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Przetoż oddzielił Amazyjasz to wojsko, które było przyszło do niego z Efraima, aby szło na miejsce swe; i rozgniewali się bardzo na Judę, i wrócili się do miejsca swego z wielkim gniewem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Lecz Amazyjasz zmocniwszy się, wywiódł lud swój, i ciągnął na dolinę Soli, i poraził synów Seir dziesięć tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Dziesięć także tysięcy żywo pojmali synowie Judzcy, i przywiedli ich na wierzch skały, i zrzucili ich z wierzchu skały, aż się wszyscy porozpukali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Ono zasię wojsko, które rozpuścił Amazyjasz, aby nie szło z nim na wojnę, wtargnęło do miast Judzkich, od Samaryi aż do Betoronu, a poraziwszy w nich trzy tysiące ludu, zebrali korzyść wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'A gdy się Amazyjasz wrócił od porażki Idumejczyków, przyniósł z sobą bogów synów Seir, i wystawił ich sobie za bogów, a kłaniał się przed nimi, i kadził im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Przetoż rozgniewał się Pan bardzo na Amazyjasza, i posłał do niego proroka, który mu rzekł: Przeczże szukasz bogów ludu tego, którzy nie wyrwali ludu swego z ręki twej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'A gdy on do niego mówił, rzekł mu król: Izali cię za radcę królewskiego obrano? Przestań tego, aby cię nie zabito. A tak przestał prorok; wszakże rzekł: Wiem, że cię umyślił Bóg zatracić, gdyżeś to uczynił, a nie usłuchałeś rady mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Tedy naradziwszy się Amazyjasz, król Judzki, posłał do Joaza, syna Joachaza, syna Jehu, króla Izraelskiego, mówiąc: Pójdź, a wejrzymy sobie w oczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'I posłał Joaz, król Izraelski, do Amazyjasza, króla Judzkiego, mówiąc: Oset, który jest na Libanie, posłał do cedru Libańskiego, mówiąc: Daj córkę twoję synowi memu za żonę. Wtem idąc tedy zwierz polny, który był na Libanie, podeptał on oset.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Myśliłeś: Otom poraził Edomczyków; przetoż wyniosło cię serce twoje, abyś się tem chlubił. Siedźże tedy w domu twym; przecz się masz wdawać w to złe, abyś upadł, ty i Juda z tobą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Ale nie usłuchał Amazyjasz; bo to było od Boga, aby ich podał w ręce nieprzyjacielskie, przeto, że szukali bogów Idumejskich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Wyciągnął tedy Joaz, król Izraelski, i wejrzeli sobie w oczy, on i Amazyjasz, król Judzki, w Betsemes, które jest w Judzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'I porażony jest Juda przed Izraelem, a pouciekali każdy do namiotów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'Lecz Amazyjasza, króla Judzkiego, syna Joazowego, syna Joachaza, pojmał król Izraelski w Betsemes, i przywiódł go do Jeruzalemu, a obalił mury Jeruzalemskie od bramy Efraimskiej aż do bramy narożnej, na czterysta łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'I zabrał wszystko złoto i srebro, i wszystkie naczynia, które się znalazły w domu Bożym u Obededoma i w skarbach domu królewskiego, i ludzi, zastawnych, a wrócił się do Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'I żył Amazyjasz, syn Joazowy, król Judzki, po śmierci Joaza, syna Joachaza, króla Izraelskiego, piętnaście lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'A inne sprawy Amazyjaszowe, pierwsze i poślednie, izali nie są zapisane w księgi królów Judzkich i Izraelskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'A od onego czasu, jako odpadł Amazyjasz od Pana, uczyniono przeciwko niemu sprzysiężenie w Jeruzalemie. Lecz on uciekł do Lachis; ale posłano za nim do Lachis, i zabito go tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'A przyniósłszy go na koniach, pochowali go z ojcami jego w mieście Judzkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'Tedy wszystek lud Judzki wzięli Uzyjasza, który miał szesnaście lat, i postanowili go królem miasto ojca jego Amazyjasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'Ten pobudował Elat, a przywrócił je do Judy, gdy zasnął król z ojcami swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Szesnaście lat było Uzyjaszowi, gdy królować począł, a pięćdziesiąt i dwa lata królował w Jeruzalemie; a imię matki jego Jechalija z Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'Ten czynił, co było dobrego w oczach Pańskich według wszystkiego, jako czynił Amazyjasz, ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'I szukał Boga za dnia Zacharyjasza, rozumiejącego widzenia Boże; a po wszystkie one dni, których szukał Pana, szczęścił go Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'Bo ruszywszy się, walczył z Filistynami, i poburzył mury w Get, i mury w Jabnie, i mury w Azocie, a pobudował miasta w Azocie i w ziemi Filistyńskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'Albowiem pomagał mu Bóg przeciw Filistynom, i przeciw Arabczykom, którzy mieszkali w Gurbaalu, i przeciw Mahunitom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'I dawali Ammonitowie Uzyjaszowi dary, a rozniosło się imię jego aż do samego Egiptu; bo się był zmocnił nader bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'I budował Uzyjasz wieże w Jeruzalemie nad bramą narożną, i nad bramą doliny, i nad Mikzoa, i umocnił je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'Pobudował też wieże na puszczy, i pokopał wiele studzien; bo miał bardzo wiele stad, tak w dolinach, jako i w równinach, i rolników, i winiarzy po górach, i na Karmelu: albowiem się kochał w uprawianiu ról.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Miał też Uzyjasz wojsko gotowe do bitwy, które wychodziło na wojnę w pocztach swych według liczby, jako byli obliczeni przez Jechijela kanclerza, i Maasajasza kapłana, pod sprawą Hananijasza, książęcia królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Wszystka liczba przedniejszych z domów ojcowskich, ludzi rycerskich, dwa tysiące i sześć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'A pod sprawą ich ludu walecznego trzy kroć i sto tysięcy, i siedm tysięcy i pięć set, ludu sposobnego do wojny, na pomoc królowi przeciw nieprzyjacielowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'I zgotował Uzyjasz wszystkiemu onemu wojsku tarcze i drzewce, i przyłbice, i pancerze, i łuki, i kamienie do proc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Naczynił też w Jeruzalemie sztuk wojennych bardzo misternych, aby były na wieżach, i na węgłach ku wypuszczaniu strzał, i kamienia wielkiego; i rozniosło się imię jego daleko, przeto, że miał dziwną pomoc, aż się zmocnił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Ale gdy się zmocnił, podniosło się serce jego ku zginieniu jego, i wystąpił przeciw Panu, Bogu swemu, i wszedł do kościoła Pańskiego, aby kadził na ołtarzu kadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'I wszedł za nim Azaryjasz kapłan, a z nim kapłanów Pańskich ośmdziesiąt, mężów dużych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'I stanęli przeciw Uzyjaszowi królowi, a mówili mu: Nie twoja to rzecz Uzyjaszu! kadzić Panu, ale kapłanów, synów Aaronowych, którzy są poświęceni, aby kadzili. Wynijdźże z świątnicy; albowiemeś wystąpił, a nie będzieć to ku sławie przed Panem Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Przetoż się rozgniewał Uzyjasz, mając w rękach swych kadzielnicę, aby kadził. A gdy się srożył przeciwko kapłanom, trąd wystąpił na czoło jego przed kapłanami w domu Pańskim u ołtarza kadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'A wejrzawszy nań Azaryjasz, kapłan najwyższy, i wszyscy kapłani, a oto był trędowatym na czole swojem; przetoż prędko wygnali go stamtąd; owszem i sam pospieszał wynijść, przeto, iż go zaraził Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'A tak był król Uzyjasz trędowatym aż do dnia śmierci swej, i mieszkał w domu osobnym, będąc trędowatym; albowiem był wyłączon z domu Pańskiego; międzytem Joatam, syn jego, był nad domem królewskim, sądząc lud ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'A inne sprawy Uzyjaszowe, pierwsze i poślednie, opisał prorok Izajasz, syn Amosowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'I zasnął Uzyjasz z ojcami swymi, a pochowano go z ojcami jego na polu grobów królewskich; bo mówili: Trędowaty jest. A królował Joatam, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Dwadzieścia i pięć lat miał Joatam, gdy królować począł, a szesnaście lat królował w Jeruzalemie. Imię matki jego Jerusa, córka Sadokowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'I czynił, co dobrego było przed oczyma Pańskiemi według wszystkiego, jako czynił Uzyjasz, ojciec jego; wszakże nie wchadzał do kościoła Pańskiego, a lud jeszcze był zepsowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'On zbudował bramę domu Pańskiego wysoką, i na murach Ofel wiele pobudował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Nadto pobudował miasta na górach Judzkich, a w lasach pobudował pałace i wieże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Ten też walczył z królem synów Ammonowych, i zwyciężył ich. I dali mu synowie Ammonowi tegoż roku sto talentów srebra, i dziesięć tysięcy korcy pszenicy, i jęczmienia dziesięć tysięcy korcy; tyleż mu dali synowie Ammonowi i drugiego, i trzeciego roku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'A tak zmocnił się Joatam; bo zgotował drogi swoje przed Panem, Bogiem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'A inne sprawy Joatamowe, i wszystkie wojny jego, i drogi jego, są napisane w księgach o królach Izraelskich i Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Dwadzieścia i pięć lat miał, gdy począł królować, a szesnaście lat królował w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'Potem zasnął Joatam z ojcami swymi, i pochowano go w mieście Dawidowem; a królował Achaz, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Dwadzieścia lat miał Achaz, gdy królować począł, a szesnaście lat królował w Jeruzalemie, i nie czynił, co było dobrego przed oczyma Pańskiemi, jako Dawid, ojciec jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'Ale chodził drogami królów Izraelskich; nadto ulał i słupy bałwochwalskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Także i sam kadził w dolinie Benhennon, i palił synów swych ogniem według obrzydliwości pogan, których wygnał Pan przed synami Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'Ofiarował też i kadził na wyżynach, i na pagórkach, i pod każdem drzewem gałęzistem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Przetoż dał go Pan, Bóg jego, w rękę króla Syryjskiego, którzy poraziwszy go, pojmali z ludu jego więźniów wiele, a przywiedli ich do Damaszku. Nadto i w rękę króla Izraelskiego podany jest, który go poraził porażką wielka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Albowiem Facejasz, syn Romelijaszowy, pobił w Judzie sto i dwadzieścia tysięcy dnia jednego, wszystko mężów walecznych, przeto, iż opuścili Pana, Boga ojców swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'Zychry także, mocarz Efraimski, zabił Maasajasza, syna królewskiego, i Asrykama, przełożonego domu jego, i Elkana, wtórego po królu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'Nadto pojmali synowie Izraelscy z braci swych dwa kroć sto tysięcy niewiast, synów, i córek, i bardzo wiele łupów pobrali od nich, i zaprowadzili korzyść do Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'I był tam prorok Pański, imieniem Obed, który zaszedłszy onemu wojsku idącemu do Samaryi, rzekł im: Oto, rozgniewawszy się Pan, Bóg ojców waszych, na Judę, podał ich w rękę waszę, a wyście ich pomordowali w popędliwości, która aż do nieba przyszła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'A jeszcze lud z Judy i z Jeruzalemu chcecie sobie podbić za niewolników i za niewolnice; azaż i przy was samych nie ma występku przeciw Panu, Bogu waszemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Przetoż teraz mię słuchajcie, a odwiedźcie więźniów, którycheście pojmali z braci waszych; bo pewnie gniew popędliwości Pańskiej wisi nad wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Tedy powstali mężowie z książąt synów Efraimowych: Azaryjasz, syn Johananowy, Barachyjasz, syn Mesyllemotowy, i Ezechyjasz, syn Sallumowy, i Amasa, syn Hadlajowy przeciwko tym, którzy się wracali z wojny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'I rzekli do nich: Nie wodźcie tu tych więźniów; bo grzech przeciwko Panu na nas myślicie przywieść, przyczyniając do grzechów naszych, i do występków naszych: bo wielki jest grzech nasz, i gniew popędliwości nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Przetoż ono wojsko zostawiło i więźniów i łupy swe przed książętami, i przed wszystkiem zgromadzeniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'A powstawszy mężowie, którzy są z imienia mianowani, wzięli onych więźniów, a wszystkich obnażonych między nimi przyodziali z onych korzyści, a przyodziawszy ich i dawszy im obuwie, nakarmili ich, i napoili ich, i pomazali ich, i odprowadzili na osłach każdego słabego, a przyprowadzili ich do Jerycha, miasta palm, do braci ich: a potem się wrócili do Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Naonczas posłał król Achaz do królów Assyryjskich, aby mu pomoc dali:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Bo jeszcze byli przyciągnęli i Edomczycy, i porazili Judę, a nabrali więźniów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Nadto i Filistynowie wtargnęli do miast w równinach, i na południe do Judy, a wzięli Betsemes, i Ajalon, i Gaderot, i Sokot i wsi jego, i Tamne i wsi jego, i Gimzo i wsi jego, a mieszkali w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Pan bowiem poniżał Judę dla Achaza, króla Izraelskiego, przeto, iż odwrócił Judę, aby się przewrotnie obchodził z Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'I przyciągnął do niego Tyglat Filneser, król Assyryjski, który go bardziej ucisnął, aniżeli mu pomógł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'A chociaż pobrał Achaz skarby z domu Pańskiego, i z domu królewskiego, i od książąt, a dał królowi Assyryjskiemu, przecież go nie ratował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'A czasu największego swego ucisku przyczyniał grzechów przeciwko Panu. Takić był król Achaz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Albowiem ofiarował bogom z Damaszku, od których był porażony, i mówił: Ponieważ bogowie królów Syryjskich pomagają im, będę im ofiarował, aby mię ratowali; ale mu oni byli na upadek, i wszystkiemu Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'Przetoz pobrał Achaz naczynia domu Bożego, i pokruszył one naczynia domu Bożego, i zamknął drzwi domu Pańskiego, i pobudował sobie ołtarze po wszystkich kątach w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'Także i w każdem mieście Judzkiem poczynił wyżyny, aby kadził bogom cudzym, i wzruszył ku gniewu Pana, Boga ojców swoich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Ale inne sprawy jego, i wszystkie postępki jego, pierwsze i poślednie, zapisane są w księgach o królach Judzkich i Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'I zasnął Achaz z ojcami swymi, i pochowali go w mieście w Jeruzalemie; bo go nie wprowadzili do grobów królów Izraelskich; a Ezechyjasz, syn jego, królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'A Ezechyjasz gdy począł królować, miał dwadzieścia i pięć lat; a dwadzieścia i dziewięć lat królował w Jeruzalemie. Imię matki jego Abi, córka Zacharyjaszowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'A czynił co było dobrego przed oczami Pańskiemi, według wszystkiego, jako czynił Dawid ojciec jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'Ten roku pierwszego królowania swego, miesiąca pierwszego, otworzył drzwi domu Pańskiego, i poprawił je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'I przywiódł kapłanów i Lewitów, a zgromadził ich na ulicę wschodnią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'I rzekł do nich: Słuchajcie mię Lewitowie: Teraz się poświęćcie: poświęćcie też i dom Pana, Boga ojców waszych, i wyrzućcie plugastwa z świątnicy:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Albowiem zgrzeszyli ojcowie nasi, i czynili złe przed oczyma Pana, Boga naszego, opuszczając go, i odwracając oblicza swoje od przybytku Pańskiego, a obracając się tyłem do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Zamknęli też drzwi u przysionka, i pogasili lampy, a kadzidłem nie kadzili, ani całopalenia nie ofiarowali w świątnicy Bogu Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Przetoż był gniew Pański nad Judą, i nad Jeruzalemem, a podał ich na rozproszenie, na spustoszenie, i na pośmiech, jako sami widzicie oczyma waszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Bo oto polegli ojcowie nasi od miecza, a synowie nasi, i córki nasze, i żony nasze zawiedzione są w niewolę dla tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Teraz tedy umyśliłem uczynić przymierze z Panem, Bogiem Izraelskim, aby odwrócił od nas gniew popędliwości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Synowie moi! nie bądźcież już niedbałymi; bo was Pan obrał, abyście stojąc przed nim służyli mu, a byli sługami jego, i kadzili mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Tedy powstali Lewitowie: Machat, syn Amasajowy, i Joel, syn Azaryjaszowy, z synów Kaatowych, a z synów Merarego: Cys, syn Abdy, i Azaryjasz, syn Jehaleelowy; a z Giersończyków: Joach, syn Zamy, i Eden, syn Joachowy:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'A z synów Elisafanowych: Symry i Jehijel: a z synów Asafowych: Zacharyjasz i Matanijasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'A z synów Hemanowych: Jehijel i Symchy; a z synów Jedytunowych: Semejasz i Uzyjel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'I zgromadzili braci swych, którzy poświęciwszy się przyszli według rozkazania królewskiego, i rozkazania Pańskiego, aby wyczyścili dom Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'A wszedłszy kapłani do domu Pańskiego, aby go oczyścili, wynieśli wszystkie plugastwa, które znaleźli w kościele Pańskim, do sieni domu Pańskiego; a Lewitowie zabrawszy to wynieśli precz do potoku Cedron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'I poczęli pierwszego dnia miesiąca pierwszego poświęcać, a dnia ósmego tego miesiąca weszli do przysionku Pańskiego i poświęcali dom Pański przez ośm dni, a dnia szesnastego, miesiąca pierwszego, dokończyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'Potem weszli do króla Ezechyjasza, i rzekli: Oczyściliśmy wszystek dom Pański, i ołtarz całopalenia, i wszystkie naczynia jego, i stół pokładny i wszystkie naczynia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Także wszystko naczynie, które był odrzucił król Achaz za królowania swego, gdy grzeszył, zgotowaliśmy i poświęcili; a oto są przed ołtarzem Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'A tak wstawszy rano król Ezechyjasz zgromadził przedniejszych miasta, i szedł do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'I przywiedziono mu cielców siedm, i baranów siedm, i baranków siedm, i kozłów siedm, na ofiarę za grzech, za królestwo, i za świątnicę, i za Judę, a rozkazał synom Aaronowym, kapłanom, aby ofiarowali na ołtarzu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'A tak pobili one woły, a kapłani wziąwszy krew ich kropili po ołtarzu; pobili też i barany, a kropili krwią ich po ołtarzu; pobili też i baranki, a kropili krwią ich po ołtarzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'Przywiedli kozły też na ofiarę za grzech przed króla i przed zgromadzenie, którzy włożyli ręce swoje na nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'I pobili je kapłani, i oczyścili krwią ich ołtarz na oczyszczenie wszystkiego Izraela; albowiem za wszystkiego Izraela rozkazał król ofiarować całopalenie i ofiarę za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'Postanowił też i Lewitów w domu Pańskim z cymbałami, i z cytrami, i z harfami, według rozkazania Dawidowego, i Gada, widzącego królewskiego, i Natana proroka; bo to było rozkazanie Pańskie przez proroków jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'A tak stali Lewitowie z instrumentami Dawidowemi, i kapłani z trąbami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'I rozkazał Ezechyjasz, aby ofiarowali całopalenia na ołtarzu; a gdy się zaczęło całopalenie, poczęło się śpiewanie Panu, i trąbienie, i granie na instrumentach Dawida, króla Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'Tedy wszystko zgromadzenie kłaniało się, a śpiewacy śpiewali, i trębacze trąbili; co wszystko trwało, póki się nie dokończyło całopalenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'A gdy się skończyło całopalenie, poklęknęli król i wszyscy, którzy z nim byli, i modlili się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'Tedy rozkazał król Ezechyjasz i książęta Lewitom, aby chwalili Pana słowy Dawidowemi, i Asafa, widzącego; chwalili z weselem wielkiem, a kłaniając się modlili się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Zatem rzekł Ezechyjasz, mówiąc: Terazeście poświęcili ręce wasze Panu; przystąpcież, a przywiedźcie ofiary spokojne, i ofiary chwały do domu Pańskiego. Przetoż przywiodło ono zgromadzenie ofiary spokojne i ofiary chwały, i każdy ochotnego serca przywiódł ofiary na całopalenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'I była liczba ofiar na całopalenie, które przywiodło zgromadzenie, wołów siedmdziesiąt, baranów sto, baranków dwieście, wszystko to na całopalenie Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'Innych też rzeczy poświęconych było: wołów sześć set, i owiec trzy tysiące,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Lecz kapłanów mało było, tak, iż nie mogli nadążyć odzierać ze skóry wszystkich ofiar na całopalenie: przetoż im pomagali Lewitowie, bracia ich, póki nie dokończyli onej pracy, i póki się nie poświęcili drudzy kapłani; albowiem Lewitowie byli och otniejsi, aby się poświęcili, niż kapłani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Nadto i całopalenia było bardzo wiele z tłustościami spokojnych ofiar, i z mokremi ofiarami na całopalenie. A tak wygotowana była służba domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'I weselił się Ezechyjasz i wszystek lud z tego, co Bóg ludowi przygotował; bo się ta rzecz była z prędka stała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'Potem rozesłał Ezechyjasz do wszystkiego Izraela i do Judy; także też listy napisał do Efraima i do Manasesa, aby przyszli do domu Pańskiego do Jeruzalemu i obchodzili święto przejścia Panu, Bogu Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Bo uradził król i książęta jego i wszystko zgromadzenie w Jeruzalemie, aby obchodzili święto przejścia miesiąca wtórego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Gdyż nie mogli obchodzić czasu swego, przeto, iż kapłanów poświęconych nie było, ile ich było potrzeba, i lud nie był zgromadzony do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'A podobała się ta rzecz królowi i wszystkiemu zgromadzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'I postanowili, aby obwołano po wszystkim Izraelu, od Beersaby aż do Dan, żeby się zeszli na obchód święta przejścia Panu, Bogu Izraelskiemu, do Jeruzalemu; albowiem już go dawno nie obchodzili, jako było napisane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'Przetoż posłowie szli z listami od króla i od książąt jego po wszystkim Izraelu i Judzie z rozkazem królewskiem, mówiąc: Synowie Izraelscy! nawróćcie się do Pana, Boga Abrahamowego, Izaakowego, i Izraelowego, a on się nawróci do ostatków, które z was uszły z rąk królów Assyryjskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'I nie bądźcie jako ojcowie wasi, i jako bracia wasi, którzy wystąpili przeciwko Panu, Bogu ojców swoich; i podał ich w spustoszenie, jako sami widzicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Teraz tedy nie zatwardzajcie karku waszego, jako ojcowie wasi: dajcie rękę Panu, a pójdźcie do świątnicy jego, którą poświęcił na wieki, i służcie Panu, Bogu waszemu, a odwróci się od was gniew popędliwości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Albowiem jeźli się nawrócicie do Pana, bracia wasi, i synowie wasi miłosierdzie otrzymają u tych, którzy ich zawiedli w niewolę, tak, iż się nawrócą do tej ziemi; miłosierny bowiem, i dobrotliwy jest Pan, Bóg wasz, a nie odwróci od was oblicza swe go, jeźli się nawrócicie do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'A gdy oni posłowie chodzili od miasta do miasta przez ziemię Efraimową o Manasesową aż do Zabulon, naśmiewali się z nich, i szydzili z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Wszakże niektórzy mężowie z Aser, i z Manase, i z Zabulon, ukorzywszy się przyszli do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'W Judzie też już była ręka Boża, gdy im dał serce jedno, aby czynili rozkazanie królewskie i książąt, według słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'I zebrało się do Jeruzalemu wiele ludu, aby obchodzili święto uroczyste przaśników miesiąca wtórego; a było zgromadzenie bardzo wielkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'Tedy powstawszy znieśli ołtarze, które były w Jeruzalemie, wszystkie też ołtarze, na których kadzono, porozwalali, a wrzucili do potoku Cedron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'Potem ofiarowali baranka wielkanocnego, dnia czternastego, miesiąca wtórego; a kapłani i Lewitowie zawstydziwszy się, poświęcali się, a przywodzili całopalenie do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'I stali w porządku swym według zwyczaju swego, i według zakonu Mojżesza, męża Bożego; a kapłani kropili krwią, wziąwszy ją z ręki Lewitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'A iż takich było wiele w zgromadzeniu, którzy się byli nie poświęcili, przetoż Lewitowie ofiarowali ofiary święta przejścia za każdego nieczystego, aby był poświęcony Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Bo wielka liczba ludu tego, to jest, wiele ich z Efraima, i z Manasesa, i z Isaschara, i z Zabulonu nie byli oczyszczeni, a przecież jedli baranka wielkanocnego, inaczej niż napisano; ale się Ezechyjasz modlił za nich, mówiąc: Dobrotliwy Pan niech oczyści każdego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'Którykolwiek zgotował wszystko serce swe, aby szukał Boga, Pana Boga ojców swoich, choćby oczyszczony nie był według oczyszczenia świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'I wysłuchał Pan Ezechyjasza, i zachował lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'A tak obchodzili synowie Izraelscy, którzy byli w Jeruzalemie, uroczyste święto przaśników przez siedm dni z weselem wielkiem: i chwalili Pana. Lewitowie na każdy dzień, a kapłani na instrumentach sławili moc Pańską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'I mówił Ezechyjasz łaskawie do wszystkich Lewitów, którzy mieli dobre rozumienie o Panu. I jedli przez siedm dni onego święta, sprawując ofiary spokojne, a wysławiając Pana, Boga ojców swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'Tedy uradziło wszystko zgromadzenie, aby to jeszcze czynili przez drugie siedm dni; a tak obchodzili znowu siedm dni z weselem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Albowiem Ezechyjasz, król Judzki, dał był zgromadzeniu tysiąc cielców, i siedm tysięcy owiec: książęta też dali zgromadzeniu tysiąc cielców, i owiec dziesięć tysięcy. I poświęciło się kapłanów bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'A tak weseliło się wszystko zgromadzenie Judzkie, i kapłani, i Lewitowie, i wszystko zgromadzenie, które było przyszło z Izraela, i przychodniowie, którzy przyszli z ziemi Izraelskiej, i mieszkający w Judzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'I było wielkie wesele w Jeruzalemie; bo ode dni Salomona, syna Dawidowego, króla Izraelskiego, nic takiego nie było w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Potem powstali kapłani i Lewitowie, i błogosławili ludowi; a wysłuchany jest głos ich, i przyszła modlitwa ich do mieszkania świętobliwości Pańskiej, do nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'A gdy się to wszystko odprawiło, wyszedł wszystek lud Izraelski, który się znajdował w miastach Judzkich, i połamali słupy, a wyrąbali gaje, i poburzyli wyżyny i ołtarze po wszystkim Judzie i Benjaminie, i w Efraimie, i w Manasesie, aż do szczę tu; a potem się wrócili wszyscy synowie Izraelscy, każdy do osiadłości swojej, i do miasta swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'I postanowił Ezechyjasz porządki kapłanów i Lewitów według rozdziałów ich, każdego według powinności urzędu jego, kapłanów i Lewitów do całopalenia i ofiar spokojnych, aby służyli i wysławiali i chwalili Pana w bramach obozu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'Także dział z królewskiej majętności ku sprawowaniu całopalenia rano i w wieczór, także całopalenia w sabaty, i na nowiu miesiąca, i w uroczyste święta, jako napisane w zakonie Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Rozkazał też ludowi mieszkającemu w Jeruzalemie, aby oddawali dział kapłanom i Lewitom, aby byli tem pilniejszymi w zakonie Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'A gdy się ta rzecz rozgłosiła, znieśli synowie Izraelscy wiele pierwocin zboża, moszczu i oliwy, i owocu palmowego, i wszystkich urodzajów polnych, i dziesięciny ze wszystkiego bardzo wiele przynosili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'Nadto synowie Izraelscy i Judzcy, którzy mieszkali w miastach Judzkich, i oni dziesięcinę z wołów i z owiec, i dziesięcinę z rzeczy świętych, poświęconych Panu, Bogu ich, zniósłszy składli na gromady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'Trzeciego miesiąca poczęli zakładać te gromady, a miesiąca siódmego dokonali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'Tedy przyszedłszy Ezechyjasz z książętami, obaczył one gromady, i błogosławili Panu i ludowi jego Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'Zatem wywiadywał się Ezechyjasz od kapłanów i Lewitów o onych gromadach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'Któremu odpowiedział Azaryjasz kapłan najwyższy z domu Sadokowego, mówiąc: Jako poczęto te ofiary znaszać do domu Pańskiego, jedliśmy, i byliśmy nasyceni, a jeszcze zostało bardzo wiele: bo Pan błogosławił ludowi swemu, i tej wielkości, która jeszcze została.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'I rozkazał Ezechyjasz, aby sprawiono szpichlerze przy domu Pańskim. I sprawiono je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'A zniesiono tam wiernie ofiary podnoszenia, i dziesięciny, i rzeczy poświęcone; a nad nimi był przełożonym Kienanijasz Lewita, i Symchy, brat jego wtóry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Jehijel także, i Azaryjasz, i Nahat, i Asael, i Jerymot, i Josabad, i Elijel, i Ismachyjasz, i Machat, i Benajasz, byli szafarzami przy ręce Kienanijasza, i Symchy, brata jego, z rozkazania Ezechyjasza króla, i Azaryjasza, przedniejszego w domu Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'Kore też, syn Jemny, Lewita, odźwierny bramy na wschód słońca, był nad rzeczami dobrowolnie ofiarowanemi Bogu, aby rozdzielał ofiary Panu i rzeczy najświętsze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'A byli mu na pomoc Eden, i Minjamin, i Jesua, i Semejasz, Amaryjasz, i Sechanijasz po miastach kapłańskich, mężowie wierni, aby rozdawali braciom swym działy, tak wielkiemu jako i małemu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, 'Tak z narodu ich mężczyźnie we trzech latach i wyżej, jako każdemu wchodzącemu do domu Pańskiego, do powinności każdodziennej, według urzędów ich, i według usług ich, i według podziałów ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'I tym, którzy byli policzeni w narodzie kapłańskim według domów ojców ich, i Lewitom od tego, który miał dwadzieścia lat i wyżej, według posług i podziałów ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'I narodowi ich, wszystkim dziatkom ich, i żonom ich, i synom ich, i córkom ich, owa wszystkiemu zgromadzeniu; bo się oni wiernie poświęcili na urząd świętobliwością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Synom także Aaronowym, kapłanom, na polach przedmiejskich miast ich, po wszystkich miastach, ci mężowie, którzy z imienia mianowani są, oddawali działy, każdemu mężczyźnie z kapłanów, i każdemu urodzonemu z Lewitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'I uczynił tak Ezechyjasz po wszystkiem Judztwie; i czynił, co było dobrego i prawego i prawdziwego przed obliczem Pana Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'I w każdej sprawie, którą zaczął około usługi domu Bożego, i w zakonie i w przykazaniu, szukając Boga swego, wszystko czynił z całego serca swego, i szczęściło mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Po tych sprawach i pewnem ich postanowieniu przyciągnął Sennacheryb, król Assyryjski, a wtargnąwszy do Judzkiej ziemi, położył się obozem przeciw miastom obronnym, a umyślił je sobie dobyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'A widząc Ezechyjasz, że przyciągnął Sennacheryb, a iż twarz swoję obrócił, aby walczył przeciw Jeruzalemowi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'Tedy wszedł w radę z książętami swymi i z rycerstwem swem, aby zatkali źródła wód, które były za miastem; i pomogli mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Bo zebrawszy się lud wielki zatkali wszystkie źródła, i potok, który płynął przez pośrodek ziemi, mówiąc: Czemużby przyszedłszy królowie Assyryjscy mieli znaleść tak wiele wód?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'A pokrzepiwszy się, pobudował wszystkie mury obalone, i nabudował wież, przytem zewnątrz drugi mur; i zmocnił Mello w mieście Dawidowem, i poczynił broni bardzo wiele, i tarczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'Postanowił też hetmanów wojennych nad ludem, których zgromadził do siebie na ulicę bramy miejskiej, i mówił łaskawie do nich, a rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Zmacniajcie się, i mężnie sobie poczynajcie; nie bójcie się, ani się lękajcie twarzy króla Assyryjskiego, ani twarzy wszystkiego mnóstwa, które jest z nim; bo większy jest z nami niżeli z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'Z nimi jest ramię cielesne; ale z nami jest Pan, Bóg nasz, aby nas ratował i odprawiał wojny nasze. Tedy spoległ lud na słowach Ezechyjasza, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Potem posłał Sennacheryb, król Assyryjski, sługi swe do Jeruzalemu, (a sam dobywał Lachis, a wszystka moc jego była z nim,) do Ezechyjasza, króla Judzkiego, i do wszystkich z Judy, którzy byli w Jeruzalemie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Tak mówi Sennacheryb, król Assyryjski: W czemże wżdy ufacie, że siedzicie w murach Jeruzalemskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Izali Ezechyjasz nie zwodzi was, aby was pomorzył głodem i pragnieniem, mówiąc: Pan, Bóg nasz, wyrwie nas z ręki króla Assyryjskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Izali nie ten Ezechyjasz zniósł wyżyny jego, i ołtarze jego, i rozkazał Judzie i Jeruzalemczykom, mówiąc: Przy jednym tylko ołtarzu kłaniać się będziecie, i na nim kadzić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Izali nie wiecie, com uczynił ja i ojcowie moi wszystkim narodom ziemskim? Azaż jakim sposobem mogli bogowie narodów ziemskich wyrwać ziemię swoję z ręki mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Któż był ze wszystkich bogów onych narodów, które wytracili ojcowie moi, coby mógł wybawić lud swój z ręki mojej, aby też mógł Bóg wasz wyrwać was z ręki mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Przetoż teraz niech was nie zwodzi Ezechyjasz, a niech was na to nie namawia, ani mu wierzcie. Jeźlić nie mógł żaden bóg wszystkich narodów i królestw wyrwać ludu swego z ręki mojej, i z ręki ojców moich, pogotowiu Bóg wasz nie wyrwie was z ręki mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'Nadto jeszcze mówili słudzy jego przeciw Panu Bogu, i przeciwko Ezechyjaszowi słudze jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Listy też pisał, urągając Panu, Bogu Izraelskiemu, a mówiąc przeciwko niemu temi słowy: Jako bogowie narodów ziemskich nie wyrwali ludu swego z ręki mojej,tak nie wyrwie Bóg Ezechyjaszowy ludu swego z ręki mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'I wołali głosem wielkim po żydowsku przeciwko ludowi Jeruzalemskiemu, który był na murach, strasząc go i trwożąc go, aby tak miasto wzięli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'A mówili przeciw Bogu Jeruzalemskiemu, jako przeciw bogom narodów ziemskich, którzy są robotą rąk ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Tedy się modlił Ezechyjasz król, i Izajasz prorok, syn Amosa, dla tego, i krzyczeli ku niebu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'I posłał Pan Anioła, który wytracił każdego mocarza w wojsku, i wodza, i hetmana w obozie króla Assyryjskiego. I wrócił się z pohańbieniem twarzy do ziemi swojej. A gdy wszedł do domu boga swego, ci, którzy wyszli z żywota jego, tam go zabili mie czem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'A tak wybawił Pan Ezechyjasza i obywateli Jeruzalemskich z rąk Sennacheryba, króla Assyryjskiego, i z rąk wszystkich, a sprawił im pokój zewsząd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'Tedy wiele ich przynosiło Panu dary do Jeruzalemu i upominki kosztowne Ezechyjaszowi, królowi Judzkiemu; i wywyższony jest w oczach wszystkich narodów potem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'W one dni zachorował Ezechyjasz aż na śmierć, i modlił się Panu; który mówił do niego, a dał mu znak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Ale nie według dobrodziejstw sobie uczynionych sprawował się Ezechyjasz, bo się wyniosło serce jego; przetoż powstał przeciw niemu gniew, i przeciw Judzie, i przeciw Jeruzalemowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Ale gdy się upokorzył Ezechyjasz (bo się było wyniosło serce jego) on i obywatele Jeruzalemscy, nie przyszedł na nich gniew Pański za dni Ezechyjaszowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'A miał Ezechyjasz bogactwa i sławę bardzo wielką; bo sobie zebrał skarby srebra i złota, i kamieni drogich, i rzeczy wonnych, i rynsztunku, i wszelakiego naczynia kosztownego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Miał też szpichlerze dla urodzajów zboża i wina, i oliwy, i obory dla bydeł, i zwierzyniec dla rozmaitych zwierząt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Miasta też sobie pobudował, i miał stada owiec, i wołów mnóstwo; albowiem mu dał Bóg majętność bardzo wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'Ten też Ezechyjasz zatkał źródło wód w Gichonie wyższe, a przywiódł je dołem na zachód słońca ku miastu Dawidowemu; i szczęściło się Ezechyjaszowi we wszystkich sprawach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'A wszakże dla posłów książąt Babilońskich, którzy byli posłani do niego, aby go pytali o znak, który się był stał w ziemi, opuścił go Bóg, aby go kusił, a iżby wiedziano wszystko, co było w sercu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'Ale inne sprawy Ezechyjaszowe, i dobroczynności jego, napisane są w widzeniu Izajasza proroka, syna Amosowego, i w księgach królów Judzkich i Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'I zasnął Ezechyjasz z ojcami swymi, i pogrzebiony jest nad grobami synów Dawidowych. I wyrządzili mu wszystek Juda i obywatele Jeruzalemscy uczciwość przy śmierci jego. A królował Manases, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'We dwunastym roku był Manases, gdy królować począł; a pięćdziesiąt i pięć lat królował w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'Ten czynił złe przed oczyma Pańskiemi według obrzydłości onych narodów, które wygnał Pan przed obliczem synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Albowiem znowu pobudował wyżyny, które był poburzył Ezechyjasz, ojciec jego; wystawił też i ołtarze Baalom, a nasadził gajów, i kłaniał się wszystkiemu wojsku niebieskiemu, a służył mu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Pobudował też ołtarze w domu Pańskim, o którym powiedział był Pan: W Jeruzalemie będzie imię moje na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'Nadto nabudował ołtarze wszystkiemu wojsku niebieskiemu we dwóch sieniach domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'I przewodził synów swych przez ogień w dolinie synów Hennomowych; nadto czasów przestrzegał, i bawił się wieszczbą i czarnoksięstwem, a ustawił czarnoksiężników i guślarzy, i bardzo wiele złego czynił przed oczyma Pańskiemi, draźniąc go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'Postawił także bałwana rytego, którego był uczynił w domu Bożym, o którym był rzekł Bóg do Dawida i do Salomona, syna jego: W domu tym i w Jeruzalemie, którem obrał ze wszystkich pokoleń Izraelskich, położę imię moje na wieki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'A nie dopuszczę się więcej ruszyć nodze Izraela z ziemi, którąm naznaczył ojcom waszym, by jedno strzegli i sprawowali się według wszystkiego, com i rozkazał, według wszystkiego zakonu, i ustaw, i sądów wydanych przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'Ale Manases zwiódł Judę i obywateli Jeruzalemskich, tak iż się gorzej sprawowali niż narody, które Pan wygładził przed obliczem synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'Bo choć mówił Pan do Manasesa, i do ludu jego, przecież oni nie słuchali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Przetoż Pan nawiódł na nich hetmanów wojska króla Assyryjskiego, którzy pojmawszy Manasesa w cierniu, i związawszy go dwoma łańcuchami, zawiedli go do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'Który będąc uciśniony, modlił się Panu, Bogu swemu, i upokorzył się bardzo przed obliczem Boga ojców swoich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'I prosił go; a dał mu się uprosić, i wysłuchał modlitwę jego, a przywrócił go do Jeruzalemu na królestwo jego. Tedy poznał Manases, iż sam Pan jest Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Potem budował mur około miasta Dawidowego ku zachodniej stronie Gichonu potoku aż do wejścia do bramy rybnej, i otoczył murem Ofel, i wywiódł go bardzo wysoko; postanowił też hetmanów po wszystkich miastach obronnych w Judzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Zniósł też bogów cudzych, i bałwana z domu Pańskiego, i wszystkie ołtarze, które był pobudował na górze domu Pańskiego, i w Jeruzalemie, i wyrzucił za miasto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'Zatem naprawił ołtarz Pański, i sprawował na nim ofiary spokojne, i dziękczynienia, a przykazał Judzie, aby służyli Panu, Bogu Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Wszakże jeszcze lud ofiarował na wyżynach, lecz tylko Panu, Bogu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Ale inne sprawy Manasesowe, i modlitwa jego do Boga jego, i słowa widzących, którzy mawiali do niego w imię Pana, Boga Izraelskiego, są w księgach spraw królów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Modlitwa zaś jego, i jako jest wysłuchany, i każdy grzech jego, i przestępstwo jego, i miejsca, na których był pobudował wyżyny, i wystawił gaje święcone, i bałwany, przedtem niż się był upokorzył, zapisane w księgach Chozaja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'Potem zasnął Manases z ojcami swymi, i pochowali go w domu jego; a Amon, syn jego, królował miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'We dwudziestu i dwóch latach był Amon, gdy królować począł, a dwa lata królował w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'I czynił złe przed oczyma Pańskiemi, jako czynił Manases, ojciec jego; albowiem wszystkim bałwanom, których był naczynił Manases, ojciec jego, ofiarował Amon, i służył im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'A nie upokorzył się przed obliczem Pańskiem, jako się upokorzył Manases, ojciec jego; owszem ten Amon daleko więcej grzeszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'I sprzysięgli się przeciw niemu słudzy jego, i zabili go w domu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Ale lud onej ziemi pobił wszystkich, co się byli sprzysięgli przeciw królowi Amonowi; a postanowił lud ziemi królem Jozjasza, syna jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Ośm lat było Jozyjaszowi, gdy królować począł, a trzydzieści i jeden lat królował w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'Ten czynił, co było dobrego przed oczyma Pańskiemi, chodząc drogami Dawida, ojca swego, i nie uchylał się ani na prawo ani na lewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'Bo ósmego roku królowania swego, będąc jeszcze dziecięciem, począł szukać Boga Dawida, ojca swego, a dwunastego roku począł oczyszczać Judę i Jeruzalem od wyżyn i od gajów święconych, i od bałwanów, i od rytych obrazów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'Albowiem przed oczyma jego pokażono ołtarze Baalów, i bałwany słoneczne, które były w górze na nich, podciął: także i gaje święcone, i obrazy ryte, i obrazy odlane pokruszył i potarł, a rozmiotał je po grobach tych, którzy im ofiarowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'Kości też kapłanów popalił na ołtarzach ich, i oczyścił Judę i Jeruzalem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Także i miasta Manasesowe i Efraimowe, i Symeonowe, aż do Neftalima, i pustynie ich okoliczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'A tak poburzył ołtarze, i gaje święcone, i bałwany pokruszył w sztuki, i wszystkie obrazy powycinał we wszystkiej ziemi Izraelskiej; potem się wrócił do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'A roku ośmnastego królowania swego, gdy oczyścił ziemię i dom Pański, posłał Safana, syna Azalijaszowego, i Maasajasza, przełożonego miasta, i Joacha, syna Joachazowego, kanclerza, aby naprawiono dom Pana, Boga jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Którzy przyszedłszy do Helkijasza, kapłana najwyższego, oddali pieniądze zniesione do domu Bożego, które byli zebrali Lewitowie, stróżowie progu, od synów Manasesowych i Efraimowych, i od wszystkich ostatków Izraelskich, i od wszystkiego Judy i Benjamina, a wrócili się do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'I oddali je w ręce rzemieślników, przełożonych nad robotą domu Pańskiego, a oni je wydawali na robotników, którzy robili w domu Pańskim, naprawiając i utwierdzając dom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'A dawali je cieślom i murarzom za skupowanie kamienia ciosanego, i drzewa na spajanie i na piętra domów, które byli popsuli królowie Judzcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'A mężowie oni byli wiernymi w tej pracy: a nad nimi byli przełożonymi Jachat, i Abdyjasz, Lewitowie, z synów Merarego, i Zacharyjasz i Mesullam z synów Kaatowych, którzy przynaglali robocie; a każdy z Lewitów umiał grać na instrumentach muzycznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'Nad tymi też, którzy nosili brzemiona, i przynaglali robotnikom przy każdej robocie, byli z Lewitów pisarze, i przystawowie, i odźwierni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'A gdy wynaszali pieniądze zniesione do domu Pańskiego, znalazł Helkijasz kapłan księgi zakonu Pańskiego, podanego przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'Tedy odpowiedział Helkijasz i rzekł do Safana pisarza: Znalazłem księgi zakonu w domu Pańskim. I oddał Helkijasz księgę Safanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'A Safan przyniósł onę księgę do króla; a przytem oznajmił to królowi, mówiąc: Wszystko, coś poruczył w rękę sług twoich, wykonywają:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'Bo zebrawszy pieniądze, które się znalazły w domu Pańskim, oddali je w ręce przystawów i w ręce robotników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Nadto oznajmił Safan, pisarz, królowi mówiąc: Księgę mi też dał Helkijasz kapłan; i czytał ją Safan przed królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'A gdy słyszał król słowa zakonu, rozdarł szaty swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'I rozkazał król Helkijaszowi i Achykamowi, synowi Safanowemu, i Abdonowi, synowi Michasowemu, i Safanowi, pisarzowi, i Asajaszowi, słudze królewskiemu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Idźcie, radźcie się Pana o mię, i o ostatek ludu w Izraelu i w Judzie około słów tych ksiąg, które są znalezione; bo wielka jest popędliwość Pańska, która jest wylana na nas, przeto, że nie strzegli ojcowie nasi słowa Pańskiego, aby czynili według wszystkiego, co jest napisane w tych księgach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'A tak poszedł Helkijasz, i którzy byli przy królu, do Huldy prorokini, żony Selluma, syna Tekui, syna Hasrowego, stróża szat; a ona mieszkała w Jeruzalemie na drugiej stronie miasta; i mówili z nią o tem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Która rzekła do nich: Tak mówi Pan, Bóg Izraelski: Powiedzcie mężowi, który was posłał do mnie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Tak mówi Pan: Oto, Ja przywiodę złe na to miejsce, i na obywateli jego, wszystkie przeklęstwa napisane w tych księgach, które czytano przed królem Judzkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'Przeto, że mię opuścili, i kadzili bogom cudzym, aby mię draźnili wszystkiemi sprawami rąk swoich; dlaczego wyleje się popędliwość moja na to miejsce, i nie będzie ugaszona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'A królowi Judzkiemu, który was posłał o radę do Pana, tak powiedzcie: Tak mówi Pan, Bóg Izraelski, o słowach, któreś słyszał:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Gdyż serce twoje zmiękczone jest, i upokorzyłeś się przed obliczem Bożem, słysząc słowa jego przeciwko temu miejscu, i przeciwko obywatelom jego, a upokorzywszy się przedemną rozdarłeś szaty swe, i płakałeś przedemną, przetożem cię wysłuchał, mówi Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Oto ja cię zbiorę do ojców twoich, a będziesz włożony do grobu twego w pokoju, aby nie oglądały oczy twoje wszystkiego złego, które Ja przywiodę na to miejsce, i na obywateli jego. I odnieśli tę rzecz królowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Tedy posławszy król zgromadził wszystkich starszych z Judy i z Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'I wstąpił król do domu Pańskiego, i wszyscy mężowie Judzcy, i obywatele Jeruzalemscy, i kapłani i Lewitowie, i wszystek lud, od wielkiego aż do małego, i czytał gdy wszyscy słyszeli, wszystkie słowa ksiąg przymierza, które było znalezione w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'Potem stojąc król na miejscu swem, uczynił przymierze przed Panem, że chce chodzić za Panem, i strzedz przykazań jego, i świadectw jego, i ustaw jego, ze wszystkiego serca swego i ze wszystkiej duszy swojej, i pełnić słowa przymierza tego, które było w onych księgach napisane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'I rozkazał stać w tem przymierzu wszystkim, którzy znalezieni byli w Jeruzalemie i w Benjaminie; i czynili obywatele Jeruzalemscy według przymierza Boga, Boga ojców swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'Tedy uprzątnął Jozyjasz wszystkie obrzydłości ze wszystkich krain synów Izraelskich, a przywiódł do tego wszystkich, którzy się znajdowali w Izraelu, aby służyli Panu, Bogu swemu. Po wszystkie dni jego nie odstąpili od naśladowania Pana, Boga ojców swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'Potem obchodził Jozyjasz w Jeruzalemie święto przejścia Panu; i zabili baranka wielkanocnego czternastego dnia, miesiąca pierwszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'I postanowił kapłanów na urzędach ich, a potwierdził ich ku posługiwaniu w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'I rzekł Lewitom, którzy uczyli wszystkiego Izraela, i byli poświęceni Panu: Postawcie skrzynię świętą w domu, który zbudował Salomon, syn Dawidowy, król Izraelski; nie będzie więcej brzemieniem na ramionach waszych. Terazże służcie Panu, Bogu waszemu, i ludowi jego Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'A nagotujcie się według domów ojców waszych, i według podziałów waszych, jako je opisał Dawid, król Izraelski, i jako je opisał Salomon, syn jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'A stójcie w świątnicy według podziałów domów ojcowskich, braci waszych, którzy są z ludu, i według podziału domu ojcowskiego Lewitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'A tak zabijcie baranka wielkanocnego, a poświęćcie się, i przygotujcie braci waszych, sprawując się według słowa Pańskiego, podanego przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'Tedy dał Jozyjasz pospólstwu baranków z trzód, i koziełków, to wszystko na ofiary święta przejścia według tego, ile się znalazło w liczbie, trzydzieści tysięcy, a wołów trzy tysiące; to wszystko z majętności królewskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Książęta też jego dobrowolnie ludowi, kapłanom, i Lewitom dawali na ofiarę; Helkijasz, i Zacharyjasz, i Jehijel, książęta domu Bożego, oddali kapłanom na ofiary święta przejścia dwa tysiące i sześć set drobnego bydła, i wołów trzysta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Nadto Kienanijasz, i Semejasz, i Natanael, bracia jego, i Chasabijasz, i Jehijel, i Josabad, przedniejsi z Lewitów, oddali innym Lewitom na ofiary święta przejścia pięć tysięcy drobnego bydła, i wołów pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'A tak wszystko zgotowawszy ku służbie, stanęli kapłani na miejscach swych, i Lewitowie w porządkach swych według rozkazania królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'I bili baranki wielkanocne, a kapłani kropili krwią ich, a Lewitowie odzierali ze skór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'I podzielili z nich na całopalenie, aby to dali pospólstwu według podziałów domów ojcowskich na ofiarę Panu, jako napisane w księgach Mojżeszowych; także też uczynili z strony wołów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'I piekli baranki wielkanocne ogniem według zwyczaju; a inne rzeczy poświęcone warzyli w garncach, i w kotłach, i w panwiach, i rozdawali spieszno wszystkiemu pospólstwu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'Potem też nagotowali sobie i kapłanom. Bo kapłani, synowie Aaronowi, około całopalenia i tłustości zabawieni byli aż do nocy; przetoż Lewitowie gotowali sobie i kapłanom, synom Aaronowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'Także i śpiewacy, synowie Asafowi, stali w porządku swym według rozkazania Dawida i Asafa, i Hemmana, i Jedytuna, widzącego królewskiego; odźwierni też stali u każdej bramy, bo się im nie godziło odchodzić od posług ich; przetoż bracia ich Lewito wie gotowali dla nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'A tak zgotowana jest wszystka służba Pańska dnia onego dla obchodzenia święta przejścia, i dla ofiarowania całopalenia na ołtarzu Pańskim według rozkazania króla Jozyjasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'I obchodzili synowie Izraelscy, ile się ich znalazło, święto przejścia onegoż czasu, i święto uroczyste przaśników przez siedm dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'A nie było obchodzone święto przejścia temu podobne w Izraelu ode dni Samuela proroka; ani żaden z królów Izraelskich obchodził takiego święta przejścia, jakie obchodził Jozyjasz i kapłani, i Lewitowie, i wszystek lud Judzki, i Izraelski, ile się go znalazło, i obywatele Jeruzalemscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'Ośmnastego roku królowania Jozyjaszowego to święto przejścia obchodzono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Po tem wszystkiem, gdy naprawił Jozyjasz dom Boży, wyciągnął Necho, król Egipski, aby walczył przeciw Karchemis nad rzeką Eufrates; a Jozyjasz też wyjechał przeciwko niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'Ale on posłał do niego posłów swych, mówiąc: Cóż ja mam z tobą, królu Judzki? Nie przeciwkoć tobie dziś ciągnę, ale przeciwko domowi, który ze mną walczy; i rozkazał mi Bóg, abym się pospieszył. Przestań walczyć z Bogiem, który jest ze mną, aby cię nie zabił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'Ale nie odwrócił Jozyjasz twarzy swej od niego; owszem odmienił szaty swe, aby z nim walczył; a nie przestał na słowach Necha, które wyszły z ust Bożych. A tak przyciągnął, aby się z nim potykał na polu Magieddo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'I postrzelili strzelcy króla Jozyjasza. Tedy rzekł król do sług swoich: Wyprowadźcie mię z bitwy, bom jest bardzo zraniony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'I przenieśli go słudzy jego z onego wozu, a włożyli go na drugi wóz, który miał, i odwieżli go do Jeruzalemu. Tamże umarł, i pochowano go w grobach ojców jego; a wszystek lud Judzki i Jeruzalemski płakał nad Jozyjaszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'Uczynił też i Jeremijasz narzekanie nad Jozyjaszem, które przypominają wszyscy śpiewacy, i śpiewaczki w lamentach swych o Jozyjaszu aż po dziś dzień, i wprowadzili to w zwyczaj w Izraelu; a zapisano te rzeczy w lamentach Jeremijaszowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'A inne sprawy Jozyjaszowe i dobroczynności jego według tego, jako napisane w zakonie Pańskim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'I uczynki jego pierwsze i poślednie zapisane są w księgach królów Izraelskich i Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Tedy wziął lud ziemi Joachaza, syna Jozyjaszowego, a postanowił go za króla na miejscu ojca jego w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Dwadzieścia i trzy lata było Joachazowi, gdy począł królować, a trzy miesiące królował w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'Bo go złożył król Egipski w Jeruzalemie, i nałożył winę na onę ziemię sto talentów srebra, i talent złota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'I postanowił królem król Egipski Elijakima, brata jego, nad Judą i nad Jeruzalemem, i odmienił imię jego, a nazwał go Joakim; a Joachaza, brata jego, wziąwszy Necho, zawiódł go do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Dwadzieścia i pięć lat miał Joakim, gdy królować począł, a jedenaście lat królował w Jeruzalemie; i czynił złe przed oczyma Pana Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Przeciw któremu wyciągnął Nabuchodonozor, król Babiloński, i związał go dwoma łańcuchami miedzianemi, aby go zawiódł do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Naczynia też domu Pańskiego zniósł Nabuchodonozor do Babilonu, i oddał je do kościoła swego w Babilonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'A ostatek spraw Joakimowych, i obrzydłości jego, które czynił, i cokolwiek się znajdowało przy nim, to zapisane w księgach królów Izraelskich i Judzkich. A królował Joachyn, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Ośm lat miał Joachyn, gdy królować począł, a trzy miesiące i dziesięć dni królował w Jeruzalemie; i czynił złe przed oczyma Pańskimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Potem po roku posłał król Nabuchodonozor, i kazał go przywieść do Babilonu, i z naczyniem kosztownem domu Pańskiego, a postanowił królem Sedekijasza, brata jego, nad Judą i nad Jeruzalemem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Dwadzieścia i jeden lat miał Sedekijasz, gdy królować począł, a jedenaście lat królował w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'I czynił złe przed oczyma Pana, Boga swego, a nie upokorzył się przed Jeremijaszem prorokiem, który mówił z ust Pańskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'Owszem i przeciwko królowi Nabuchodonozorowi powstał, który go był przysięgą zawiązał przez Boga; a zatwardziwszy kark swój uparł się w sercu swojem, aby się nie nawrócił do Pana, Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Wszyscy też przedniejsi kapłani, i lud, wielce rozmnożyli nieprawości według wszystkich obrzydliwości pogańskich; i splugawili dom Pański, który był poświęcił w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'A Pan, Bóg ojców ich, posyłał do nich posłów swoich, a posyłał rano wstawając; bo folgował ludowi swemu, i mieszkaniu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'Ale oni szydzili z posłów Bożych, i lekce sobie poważyli słów jego, a naśmiewali się z proroków jego, aż przyszła popędliwość Pańska na lud jego, tak, iż żadnego uleczenia nie było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Bo przywiódł na nich króla Chaldejskiego, który pomordował młodzieńców ich mieczem w domu świątnicy ich, a nie przepuścił ani młodzieńcowi ani pannie, starcowi i zgrzybiałemu; wszystkich podał w ręce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'Nadto wszystkie naczynia domu Bożego, wielkie i małe, i skarby domu Pańskiego, i skarby królewskie i książąt jego, wszystko przeniósł do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'I spalili dom Boży, a zburzyli mury Jeruzalemskie, i wszystkie pałace jego popalili ogniem, i wszystkie jego naczynia kosztowne popsuli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'A tych, którzy uszli miecza, przeniósł do Babilonu; i byli niewolnikami jego i synów jego aż do królowania króla Perskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'Aby się wypełniło słowo Pańskie powiedziane przez usta Jeremijaszowe, ażby odprawiła ziemia sabaty swoje; bo po wszystkie dni spustoszenia swego odpoczywała, aż się wypełniło siedmdziesiąt lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'Potem roku pierwszego Cyrusa, króla Perskiego, aby się wypełniło słowo Pańskie powiedziane przez usta Jeremijaszowe, wzbudził Pan ducha Cyrusa, króla Perskiego, że kazał obwołać i rozpisać po wszystkiem królestwie swojem, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Tak mówi Cyrus, król Perski: Wszystkie królestwa ziemi dał mi Pan, Bóg niebieski; i ten mi rozkazał, abym mu zbudował dom w Jeruzalemie, które jest w Judztwie. Kto tedy jest między wami ze wszystkiego ludu jego, który budować chce, z tym niech będzie Pan, Bóg jego, a ten niechaj idzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'Roku pierwszego Cyrusa, króla Perskiego, aby się wypełniło słowo Pańskie powiedziane przez usta Jeremijaszowe, wzbudził Pan ducha Cyrusa, króla Perskiego, że kazał obwołać i rozpisać po wszystkiem królestwie swojem, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Tak mówi Cyrus, król Perski: Wszystkie królestwa ziemi dał mi Pan, Bóg niebieski; i ten mi rozkazał, abym mu zbudował dom w Jeruzalemie, które jest w Judztwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Kto tedy jest między wami ze wszystkiego ludu jego, z tym niech będzie Bóg jego, a ten niech idzie do Jeruzalemu, które jest w Judztwie, a niech buduje dom Pana, Boga Izraelskiego; onci jest Bóg, który jest w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'A ktoby został w któremkolwiek miejscu, gdzie jest przychodniem, niech go podpomogą mężowie miejsca onego srebrem i złotem, i majętnością, i bydłem, oprócz dobrowolnej ofiary na dom Boży, który jest w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Tedy powstali przedniejsi z domów ojcowskich, z Judy i z Benjamina, i kapłani, i Lewitowie; wszelki, którego ducha pobudził Bóg, aby szli, a budowali dom Pański, który jest w Jeruzalemie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'Których wszyscy mieszkający około nich wspomagali naczyniem srebrnem i złotem, majętnością, i bydłem, i rzeczami kosztownemi, oprócz wszystkiego, co dobrowolnie ofiarowano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Król też Cyrus wyniósł naczynia domu Pańskiego (które był zabrał Nabuchodonozor z Jeruzalemu, a oddał je był do domu Boga swego).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'A wyniósł je Cyrus, król Perski, przez ręce Mitrydatesa podskarbiego, który je pod liczbą oddał Sesbasarowi, książęciu Judzkiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'A tak jest liczba ich: Miednic złotych trzydzieści, miednic srebrnych tysiąc, nożów dwadzieścia i dziwięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'Kubków złotych trzydzieści, kubków srebrnych podlejszych cztery sta i dziesięć, a naczynia innego tysiącami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Wszystkiego naczynia złotego i srebrnego pięć tysięcy i cztery sta; wszystko to wyniósł Sesbasar, gdy się prowadził lud z niewoli, z Babilonu do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'A cić są ludzie onej krainy, którzy wyszli z pojmania i z niewoli, w którą ich był zaprowadził Nabuchodonozor, król Babiloński, do Babilonu, a wrócili się do Jeruzalemu i do Judy, każdy do miasta swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'Którzy przyszli z Zorobabelem, z Jesuą, Nehemijaszem, Sarajaszem, Rehelijaszem, Mardocheuszem, Bilsanem, Misparem Bigwajem, Rechumem, i Baaną. A poczet ludu Izraelskiego ten był:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Synów Farosowych dwa tysiące sto siedmdziesiąt i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Synów Sefatyjaszowych trzy sta siedmdziesiąt i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Synów Arachowych siedm set siedmdziesiąt i pięć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Synów Pachat Moabowych, synów Jesui Joabowych dwa tysiące ośm set i dwanaście; synów Elamowych tysiąc dwieście pięćdziesiąt i cztery;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Synów Zatuowych dziewięć set i czterdzieści i pięć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Synów Zachajowych siedm set i sześćdziesiąt;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Synów Bani sześć set czterdzieści i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Synów Bebajowych sześć set dwadzieścia i trzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Synów Azgadowych tysiąc dwieście dwadzieścia i dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Synów Adonikamowych sześć set sześćdziesiąt i sześć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Synów Bigwajowych dwa tysiące pięćdziesiąt i sześć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Synów Adynowych cztery sta pięćdziesiąt i cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Synów Aterowych, co poszli z Ezechyjasza, dziewięćdziesiąt i ośm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'Synów Besajowych trzy sta dwadzieścia i trzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Synów Jory sto i dwanaście;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Synów Hasumowych dwieście dwadzieścia i trzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Synów Gibbarowych dziewięćdziesiat i pięć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Synów z Betlehemu sto dwadzieścia i trzy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Mężów z Netofatu pięćdziesiąt i sześć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Mężów z Anatotu sto dwadzieścia i ośm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Synów z Azmawetu czterdzieści i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Synów z Karyjatyjarymu, z Kafiry i z Beerotu siedm set i czterdzieści i trzy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Synów z Ramy i z Gabaa sześć set dwadzieścia i jeden;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Mężów z Machmas sto dwadzieścia i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Mężów z Betela i z Haj dwieście dwadzieścia i trzy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Synów z Nebo pięćdziesiąt i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Synów Magbisowych sto pięćdziesiąt i sześć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Synów Elama drugiego tysiąc dwieście pięćdziesiąt i cztery;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'Synów Harymowych trzy sta i dwadzieścia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Synów Lodowych, Hadydowych, i Onowych siedm set dwadzieścia i pięć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Synów Jerechowych trzy sta czterdzieści i pięć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Synów Senaa trzy tysiące i sześć set i trzydzieści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Kapłanów: Synów Jedajaszowych z domu Jesui, dziewięć set siedmdziesiąt i trzy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Synów Immerowych tysiąc pięćdziesiąt i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Synów Pashurowych tysiąc dwieście czterdzieści i siedm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Synów Harymowych tysiąc i siedmnaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Lewitów: synów Jesui i Kadmiela, synów Hodawyjaszowych siedmdziesiąt i cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Śpiewaków: synów Asafowych sto dwadzieścia i ośm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Synów odźwiernych: synów Sallumowych, synów Aterowych, synów Talmonowych, synów Akkubowych, synów Hatytowych, synów Sobajowych, wszystkich sto trzydzieści i dziewięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Z Netynejczyków: synów Sycha, synów Chasufa, synów Tabbaota,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Synów Kierosa, synów Syaa, synów Fadona,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'Synów Lebana, synów Hagaba,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'Synów Akkuba, synów Hagaba, synów Salmaja, synów Hanana,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'Synów Gieddela, synów Gachera, synów Reajasza,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'Synów Rezyna, synów Nekoda, synów Gazama,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'Synów Uzy, synów Fasejacha, synów Besaja,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'Synów Asena, synów Mehunima, synów Nefusyma;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'Synów Bakbuka, synów Chakufa, synów Charchura,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'Synów Basluta, synów Mechyda, synów Charsa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'Synów Barkosa, synów Sysera, synów Tamacha,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'Synów Nezyjacha, synów Chatyfa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'Synów sług Salomonowych, synów Sotaja, synów Sofereta, synów Peruda,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Synów Jahala, synów Darkona, synów Giddela,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'Synów Sefatyjasza, synów Chatyla, synów Pocheret Hasebaim, synów Ami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'Wszystkich Netynejczyków, i synów sług Salomonowych trzy sta dziewięćdziesiąt i dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Ci też zasię wyszli z Telmelachu: Telcharsa, Cherub, Addam i Immer; ale nie mogli okazać domu ojców swoich, i nasienia swego, jeźli z Izraela byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'Synów Delajaszowych, synów Tobijaszowych, synów Nekodowych, sześć set pięćdziesiąt i dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'A synów kapłańskich: synowie Habajowi, synowie Kozowi, synowie Barsylajego, który był pojął żonę z córek Barsylaja Galaadczyka; i nazwany był od imienia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'Ci szukali opisania rodu swego, ale nie znaleźli; przetoż zrzuceni są z kapłaństwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'I zakazał im Tyrsata, aby nie jadali z rzeczy najświętszych, ażby powstał kapłan z Urym i z Tummim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'Wszystkiego zgromadzenia było w jednym poczcie cztredzieści tysięcy dwa tysiące trzy sta i sześćdziesiąt;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Oprócz sług ich, i służebnic ich, których było siedm tysięcy trzy sta trzydzieści i siedm, a między nimi było śpiewaków i śpiewaczek dwieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'Koni ich siedm set trzydzieści i sześć; mułów ich dwieście czterdziści i pięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Wielbłądów ich cztery sta trzydzieści i pięć; osłów sześć tysięcy siedm set i dwadzieścia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'A niektórzy z książąt domów ojcowskich przyszli do domu Pańskiego, który był w Jeruzalemie, ofiarowawszy się dobrowolnie, aby budowali dom Boży na miejscu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'Według przemożenia swego dali nakład na budowanie: złota łótów sześćdziesiąt tysięcy i jeden, a srebra grzywien pięć tysięcy, i szat kapłańskich sto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'A tak osadzili się kapłani i Lewitowie, i niektórzy z ludu, i śpiewacy, i odźwierni, i Netynejczycy w miastach swych, i wszystek Izrael w miastach swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'A gdy nastał miesiąc siódmy, a synowie Izraelscy byli w miastach, zgromadził się lud jednomyślnie do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Tedy wstawszy Jesua, syn Jozedeka, i bracia jego kapłani, i Zorobabel, syn Salatyjela, i bracia jego, zbudowali ołtarz Boga Izraelskiego, aby na nim sprawowali całopalenia, jako napisane w zakonie Mojżesza, męża Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'A gdy postawili on ołtarz na fundamencie swym, choć się bali narodów postronnych, jednak ofiarowali na nim całopalenia Panu, całopalenia rano i w wieczór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'Obchodzili też święto uroczyste kuczek, jako napisane, sprawując całopalenia na każdy dzień według liczby i według zwyczaju każdą rzecz dnia swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'Potem całopalenie ustawiczne, i na nowiu miesiąca, i na każde uroczyste święto Panu poświęcone, i od każdego dobrowolnie ofiarującego dobrowolną ofiarę Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Ode dnia pierwszego miesiąca siódmego poczęli sprawować całopalenia Panu, choć jeszcze kościół Pański nie był założony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'I oddali pieniądze kamiennikom, i rzemieślnikom, także strawę i napój, i oliwę Sydończykom, i Tyryjczykom, aby przywozili drzewo cedrowe z Libanu do morza Joppy, jako im pozwolił Cyrus, król Perski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'Potem roku wtórego po ich nawróceniu do domu Bożego w Jeruzalemie, miesiąca wtórego, zaczęli Zorobabel, syn Salatyjela, i Jesua, syn Jozedeka, i inni bracia ich kapłani, i Lewitowie, i wszyscy, którzy byli przyszli z onej niewoli do Jeruzalemu, a postanowili Lewitów od dwudziestu lat i wyżej, aby byli dozorcami nad robotą domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'I stanął Jesua, synowie jego, i bracia jego; Kadmiel też i synowie jego, synowie Judy społu, aby przynaglali tym, którzy robili około domu Bożego; synowie Chenadadowi, synowie ich, i bracia ich Lewitowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'A gdy zakładali budownicy grunty kościoła Pańskiego, postawili kapłanów ubranych z trąbami, i Lewitów, synrw Asafowych z cymbałami, aby chwalili Pana według postanowienia Dawida, króla Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'I śpiewali jedni po drugich chwaląc a wysławiając Pana, że dobry, że na wieki miłosierdzie jego nad Izraelem. Wszystek także lud krzyczał krzykiem wielkim, chwaląc Pana, przeto, iż był założony dom Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'A wiele starców, z kapłanów, i z Lewitów, i z przedniejszych domów ojcowskich, którzy widzieli dom pierwszy, gdy zakładano ten dom przed oczyma ich, płakali głosem wielkim, a zasię wiele ich krzyczało, z radością wynosząc głosy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'Tak, iż lud nie mógł rozeznać głosu krzyku wesołego od głosu płaczącego ludu; albowiem lud on krzyczał głosem wielkim, tak że głos było daleka słyszeć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'A gdy usłyszeli nieprzyjaciele Judy i Benjamina, iż lud, który przyszedł z pojmania, budowali kościół Panu, Bogu Izraelskiemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'Tedy przyszli do Zorobabela i do przedniejszych z domów ojcowskich, mówiąc im: Będziemy budować z wami, a jako i wy będziemy szukać Boga waszego, gdyżeśmy mu ofiary czynili ode dni Asarhaddona, króla Assyryjskiego, który nas tu przywiódł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Ale im rzekł Zorobabel, i Jesua, i inni przedniejsi domów ojcowskich z Izraela: Nie wam, ale nam należy budować dom Bogu naszemu; przetoż my sami budować będziemy Panu, Bogu Izraelskiemu, jako nam rozkazał Cyrus, król Perski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'A tak lud onej krainy wątlił ręce ludu Judzkiego, i przeszkadzał im, aby nie budowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'Nadto przenajmowali przeciwko nim radców, aby rozrywali radę ich po wszystkie dni Cyrusa, króla Perskiego, aż do królowania Daryjusza, króla Perskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'Bo gdy królował Aswerus, tedy na początku królestwa jego, napisali skargę przeciwko obywatelom Judzkim i Jeruzalemskim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'Tak jako za dni Artakserksesa pisał Bislan, Mitrydates, Tabeel, i inni towarzysze jego do Artakserksesa króla Perskiego; a pismo listu tego napisane było po syryjsku, i wyłożone też było po syryjsku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rechum kanclerz, i Symsaj pisarz napisali list jeden przeciwko Jeruzalemowi do Artakserksesa króla w ten sposób:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, 'To uczynili natenczas Rechum kanclerz, i Symsaj pisarz, i inni towarzysze ich, Dynajczycy, i Afarsadchajczycy, Tarpelajczycy, Afarsajczycy, Arkiewajczycy, Babilończycy, Susanchajczycy, Dehawejczycy i Elmajczycy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'I inne narody, które był przyprowadził Asnapar wielki i sławny, a osadził nimi miasta Samaryjskie; i inni, którzy byli za rzeką, i Cheenetczycy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'A tenci jest przepis listu, który posłali do Artakserksesa króla:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Słudzy twoi, ludzie mieszkający za rzeka, i Cheenetczycy. Niech będzie wiadomo królowi, że Żydowie, którzy się wrócili od ciebie, przyszedłszy do nas do Jeruzalemu, miasto odporne i złe budują, i mury zakładają, a z gruntu je wywodzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Przetoż niech będzie wiadomo królowi, Ze będzieli to miasto pobudowane, i mury jego z gruntu wywiedzione, tedy cła, czynszów, i dani dorocznej nie będą dawać, a tak dochodom królewskim ujma się stanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Teraz tedy, ponieważ używamy dobrodziejstw pałacu twego, na szkodę królewską nie godzi się nam patrzyć; dla tegośmy posłali, oznajmując to królowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'Abyś dał szukać w księgach historyj ojców swoich, a znajdziesz w księgach historyj, i dowiesz się, iż to miasto jest miasto odporne i szkodliwe królom i krainom, a iż się w niem wszczynały bunty od dawnych dni, przez co to miasto było zburzone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Nadto wiadomo czynimy królowi, że jeżli się to miasto pobuduje, i mury jego z gruntu wywiedzione będą, tedy już ta część za rzeką nie będzie twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Tedy dał odpowiedż król Rechumowi kanclerzowi, i Symsajemu pisarzowi, i innym towarzyszom ich, którzy mieszkali w Samaryi, także i innym za rzeką w Selam i w Cheet:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'List, któryście posłali do nas, jawnie przedemną czytano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'Przetoż rozkazałem, aby szukano; i znaleziono, że to miasto z dawna powstawało przeciwko królom, a bunty i rozruchy bywały w niem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'Nadto królowie możni bywali w Jeruzalemie, którzy panowali nad wszystkiem, co jest za rzeką, którym cła, czynsze, i dani doroczne dawano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Przetoż wydajcie wyrok, aby zabroniono onym mężom, aby to miasto nie było budowane, pókiby odemnie inszy rozkaz nie wyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'Patrzcież, abyście się w tem nie omylili. Przeczżeby urość miało co złego na szkodę królom?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'A tak, gdy przepis listu Artakserksesa był czytany przed Rechumem, i Symsajem pisarzem, i przed towarzyszami ich, jechali prędko do Jeruzalemu do Żydów, a zabronili im gwałtem i mocą budować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'A tak ustała robota około domu Bożego, który był w Jeruzalemie, i zaniechano jej aż do wtórego roku królestwa Daryjusza, króla Perskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Tego czasu prorokował Haggieusz prorok, i Zacharyjasz, syn Iddy, prorokując żydom, którzy byli w Judzie i w Jeruzalemie, w imię Boga Izraelsiego, mówiąc do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Tedy powstawszy Zorobabel, syn Salatyjela, i Jesua, syn Jozedeka, poczęli budować dom Boży, który jest w Jeruzalemie; a byli z nimi prorocy Boży, pomagając im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'Pod tenże czas przyszedł do nich Tattenaj, starosta za rzeką, i Setarbozenaj, i towarzysze ich, i tak mówili do nich: Któż wam rozkazał ten dom budować, i mury jego z gruntu wywodzić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Na cośmy im odpowiedzieli, i mianowaliśmy tych mężów, którzy około tego budowania robili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'Lecz oko Boga ich było nad starszymi Żydowskimi, i nie mogli im przeszkadzać, póki ta rzecz do Daryjusza nie przyszła, a pókiby przez list nie dano znać o tem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'Tenci jest przepis listu, który posłał do króla Daryjusza Tattenaj, starosta za rzeką, i Setarbozenaj, i towarzysze jego Afarsechajczycy, którzy byli za rzeką, do króla Daryjusza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'List mu posłali, w którem to było napisane: Daryjuszowi królowi pokój na wszystkiem!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Niechaj będzie wiadomo królowi, żeśmy przyszli do Judzkiej krainy, do domu Boga wielkiego, który budują z kamienia wielkiego, a drzewo kładą w ściany; ta robota sporo idzie, i szczęści się w rękach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Pytaliśmy tedy starszych onych męwiąc do nich: Któż wam rozkazał ten dom budować, i te muru z gruntu wywodzić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Nawet i o imiona ich pytaliśmy się, abyśmyć oznajmili, i opisali imiona mężów, którzy są przedniejsi między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Ale nam tak odpowiedzieli, mówiąc: Myśmy słudzy Boga nieba i ziemi, a budujemy dom, który był zbudowany przedtem przed wieloma laty, który był wielki król Izraelski zbudował i wystawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'Lecz gdy wzruszyli ku gniewu ojcowie nasi Boga niebieskiego, podał ich w ręce Nabuchodonozora, króla Babilońskiego, Chaldejczyka, który ten dom zburzył, a lud jego zawiódł w niewolę do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Wszakże roku pierwszego Cyrusa, króla Babilońskiego, król Cyrus wydał dekret, aby ten dom Boży budowano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Nadto i naczynia domu Bożego złote i srebrne, które był zabrał Nabuchodonozor z kościoła, który był w Jeruzalemie, i wniósł je do kościoła Babilońskiego, te wyniósł król Cyrus z kościoła Babilońskiego, i dane są nijakiemu Sesbasarowi, którego był książęciem uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'I rzekł mu: Te naczynia wziąwszy, idź, a złóż je w kościele, który jest w Jeruzalemie, a dom Boży niech będzie budowany na miejscu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Tedy ten Sesbasar przyszedłszy założył grunty domu Bożego, który jest w Jeruzalemie, i od onego czasu aż dotąd budują go, a nie jest dokończony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'A tak, królu! jeźlić się zda być rzeczą dobrą, niechby poszukano w domu skarbów królewskich, który jest w Babilonie, jeźliż tak jest, że król Cyrus rozkazał, aby budowano ten dom Boży, który jest w Jeruzalemie, a wola królewska o tem niech będzie do nas posłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Tedy król Daryjusz rozkazał, aby szukano w biblijotece między skarbami tamże złożonemi w Babilonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'I znaleziono w Achmecie na zamku, który jest w ziemi Medskiej, księgę jednę, a taka była zapisana w niej pamięć:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'Roku pierwszego Cyrusa króla, król Cyrus wydał wyrok o domu Bożym, który był w Jeruzalemie, aby był dom zbudowany dla miejsca, gdzieby ofiary sprawowano; aby też grunty jego były wybudowane, wysokość jego na sześćdziesiąt łokci, a szerokość jego na sześćdziesiąt łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'Trzy rzędy z kamienia wielkiego, a jeden rząd z drzewa nowego, a nakład z domu królewskiego dawany będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Nadto i naczynia domu Bożego, złote i srebrne, które był zabrał Nabuchodonozor z kościoła, który jest w Jeruzalemie, a przeniósł do Babilonu, niech wrócą, aby się dostały do kościoła, który jest w Jeruzalemie, na miejsce swe, i złożone były w domu Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Przetoż teraz Tattenaju, starosto za rzeką! z Setarbozenaimem, i z towarzyszami twymi, i Afarsechajczycy, którzyście za rzeką, ustąpcie stamtąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Dopuśćcie, żeby był budowany ten dom Boży od książęcia Żydowskiego, i od starszych Żydowskich, aby ten dom Boży zbudowali na miejscu swem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Odemnie też wyszedł wyrok o tem, cobyście mieli czynić z starszymi tych Żydów przy budowaniu tego domu Bożego; to jest, aby z majętności królewskich, z dochodów, które są za rzeką, dawano bez omieszkania nakład mężom tym, aby nie przestawali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'A ile potrzeba i wołów, i baranów, i baranków na całopalenia Bogu niebieskiemu, zboża, soli, wina, i oliwy, na rozkazanie kapłanów, którzy są w Jeruzalemie, aby im dawano na każdy dzień, a to bez omieszkania;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'Aby mieli skąd ofiarować wonne kadzenia Bogu niebieskiemu, i aby się modlili za zdrowie królewskie, i synów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Nadto uczyniony jest odemnie dekret: Ktobykolwiek wzruszył to przykazanie, aby wyjęto drzewo z domu jego, i aby je podniesiono, a na niem go powieszono, a dom jego aby był gnojowiskiem dla tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'A Bóg, który tam uczynił mieszkanie imieniowi swemu, niech zniszczy każdego króla i naród, któryby ściągnął rękę swą na odmianę i skazę tego domu Bożego, który jest w Jeruzalemie. Ja Daryjusz uczyniłem ten dekret; bez omieszkania niech będzie wyk onany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Tedy Tattenaj, starosta za rzeką, i Setarbozenaj, i towarzysze ich według tego, jako rozkazał król Daryjusz, tak uczynili bez omieszkania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'A starsi Żydowscy budowali, i szczęściło się im według proroctwa Haggieusza proroka, i Zachariasza, syna Iddy; i budowali i dokonali za rozkazaniem Boga Izraelskiego, i za rozkazaniem Cyrusa, i Daryjusza, i Artakserksesa, królów Perskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'I dokończony jest on dom trzeciego dnia miesiąca Adar, a ten był rok szósty panowania Daryjusza króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'Tedy synowie Izraelscy, kapłani i Lewitowie, i inni z ludu, którzy przyszli z więzienia, poświęcali on dom Boży z radością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'A ofiarowali przy poświęcaniu onego domu Bożego, cielców sto, baranów dwieście, baranków cztery sta, i kozłów z kóz na ofiarę za grzech za wszystkiego Izraela, dwanaście, według liczby pokolenia Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'I postawili kapłanów w rzędach swych, i Lewitów w przemianach swoich, nad służbą Bożą w Jeruzalemie, jako napisane w księgach Mojżeszowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'Obchodzili też ci, co przyszli z niewoli, swięto przejścia czternastego dnia miesiąca pierwszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Bo się oczyścili kapłani i Lewitowie jednostajnie, wszyscy byli oczyszczeni; przetoż ofiarowali baranka święta przejścia za wszystkich, którzy przyszli z niewoli, i za braci swoich kapłanów, i za siebie samych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'A tak jedli synowie Izraelscy, którzy się wrócili z niewoli, i każdy, który się odłączył od sprosności narodów onej ziemi do nich, aby szukał Pana, Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'I obchodzili święto uroczyste przaśników przez siedm dni z radością, przeto, że ich Pan był rozweselił, a obrócił serce króla Assyryjskiego do nich, aby zmocnił ręce ich w robocie około domu Bożego, Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'A po tych sprawach za królowania Artakserksesa, króla Perskiego, Ezdrasz, syn Sarajasza, syna Azaryjaszowego, syna Helkijaszowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'Syna Sallumowego, syna Sadokowego, syna Achitobowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'Syna Amaryjaszowego, syna Azaryjaszowego, syna Merajotowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'Syna Zerahyjaszowego, syna Uzego, syna Bukkiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'Syna Abisujego, syna Fineesowego, syna Eleazarowego, syna Aarona kapłana najwyższego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'Ten Ezdrasz wyszedł z Babilonu, a był człowiekiem biegłym w zakonie Mojżeszowym, który był dał Pan, Bóg Izraelski; a pozwolił mu był król według ręki Pana Boga jego nad nim, na wszystkę prośbę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, '(Wyszli też niektórzy z synów Izraelskich, i z kapłanów, i z Lewitów, i śpiewaków, i z odźwiernych, i z Netynejczyków, do Jeruzalemu roku siódmego Artakserksesa króla)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'I przyszedł do Jeruzalemu miesiąca piątego; tenci był rok siódmy króla Daryjusza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Albowiem w pierwszy dzień miesiąca pierwszego wyszedł z Babilonu, a dnia pierwszego miesiąca piątego przyszedł do Jeruzalemu według łaskawego wspomożenia Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Bo Ezdrasz przygotował był serce swe, aby szukał zakonu Pańskiego, i aby czynił, i nauczał w Izraelu ustaw i sądów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'A tenci jest przepis listu, który dał król Artakserkses Ezdraszowi, kapłanowi nauczonemu w zakonie, i biegłemu w tych rzeczach, które przykazał Pan, i w ustawach jego w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artakserkses, król nad królmi, Ezdraszowi, kapłanowi nauczonemu w zakonie Boga niebieskiego, mężowi doskonałemu, i Cheenetczykom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Wydany odemnie jest dekret, iż ktobykolwiek dobrowolnie w królestwie mojem z ludu Izraelskiego, i z kapłanów jego i z Lewitów chciał iść z tobą do Jeruzalemu, aby szedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Ponieważ od króla i od siedmiu radnych panów jego jesteś posłany, abyś dojrzał Judy i Jeruzalemu według zakonu Boga twego, który jest w rękach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'A iżbyś odniósł srebro i złoto, które król i radni panowie jego dobrowolnie ofiarowali Bogu Izraelskiemu, którego przybytek jest w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'Do tego wszystko srebro i złoto, któregobyś nabył we wszystkiej krainie Babilońskiej, z dobrowolnemi darami od ludu i od kapłanów, którzyby co dobrowolnie ofiarowali na dom Boga swego, który jest w Jeruzalemie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'Abyś prędko nakupił za to srebro cielców, baranów, baranków z śniednemi ofiarami ich, i z mokremi ofiarami ich, a ofiarował je na ołtarzu domu Boga waszego, który jest w Jeruzalemie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'A cokolwiek się tobie i braciom twoim będzie dobrego zdało, z ostatkiem srebra i złota uczynić, według woli Boga waszego uczyńcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'Naczynia też, któreć są oddane do usługi domu Boga twego, oddaj przed Bogiem w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'Także i inne rzeczy, należące do domu Boga twego, i coby potrzeba dać, dasz z domu skarbów królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'A ja, ja król Artakserkses, rozkazałem wszystkim podskarbim, którzyście za rzeką, aby wszystko, czegobykolwiek żądał od was Ezdrasz kapłan, nauczyciel zakonu Boga niebieskiego, prędko się stało,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'Aż do sta talentów srebra i aż do sta korcy pszenicy, i aż do sta wiader wina, i aż do sta bareł oliwy, a soli bez miary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Cobykolwiek było z rozkazania Boga niebieskiego, niech będzie prędko dodane do domu Boga niebieskiego; bo przecz ma być wzruszony gniew jego przeciwko królestwu, królowi i synom jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Także oznajmujemy wam, aby na żadnego z kapłanów, i z Lewitów, i z śpiewaków, i z odźwiernych, Netynejczyków, i innych sług domu Boga tego, cła, czynszów, i dani dorocznej żaden starosta nie wkładał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'A ty Ezdraszu! według mądrości Boga twego, która jest w tobie, postanowisz sędziów, i w prawie biegłych, aby sądzili wszystek lud, który jest za rzeką, ze wszystkich, którzy są powiadomi zakonu Boga twego; a ktoby nie umiał, uczyć go będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'A ktobykolwiek nie czynił dosyć zakonowi Boga twego, i prawu królewskiemu, aby prędki dekret był o nim wyadany albo na śmierć, albo na wygnanie jego, albo na skaranie na majętności, albo na więzienie. I rzekł Ezdrasz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Błogosławiony Pan, Bóg ojców naszych, który to dał w serce królewskie, aby uwielbił dom Pański, który jest w Jeruzalemie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'A ku mnie skłonił miłosierdzie przed królem i radą jego, i wszystkimi książętami królewskimi możnymi. Przetoż ja, będąc umocniony ręką Pana, Boga mojego, która jest nademną, zgromadziłem z Izraela przedniejszych, którzy wyszli zemną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'A cić są przedniejsi z domów swych ojcowskich, i ród tych, którzy wyszli zemną z Babilonu za królowania króla Artakserksesa:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Z synów Fineaszowych Gierson; z synów Itamarowych Danijel; z synów Dawidowych Hattus;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Z synów Sechanijaszowych, który był z synów Faresowych, Zacharyjasz, a z nim poczet mężów sto i pięćdziesiąt;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Z synów Pachatmoabowych Elijeoenaj, syn Zerachyjaszowy, a z nim dwieście mężów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Z synów Sechanijaszowych syn Jahazyjelowy, a z nim trzy sta mężów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'A z synów Adynowych Ebed, syn Jonatana, a z nim pięćdziesiąt mężów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'A z synów Elamowych Isajasz, syn Atalijasza, a z nim siedmdziesiąt mężów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'A z synów Sefatyjaszowych Zabadyjasz, syn Michaelowy, a z nim ośmdziesiąt mężów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Z synów Joabowych Obadyjasz, syn Jechyjelowy, a z nim dwieście i ośmnaście mężów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'A z synów Selomitowych, syn Josyfijaszowy, a z nim sto i sześćdziesiąt mężów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'A z synów Bebajowych Zacharyjasz, syn Bebajowy, a z nim dwadzieścia i ośm mężów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'A z synów Azgadowych Johanan, syn Hakatanowy, a z nim sto i dziesięć mężów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'A z synów Adonikamowych najostateczniejszych, których te są imiona: Elifelet, Jehijel, i Semejasz, a z nimi sześdziesiąt mężów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'A z synów Bigwajowych Utaj i Zabud, a z nimi siedmdziesiąt mężów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'A tak zgromadziłem ich do rzeki, która wpada do Achawy, i leżeliśmy tam obozem przez trzy dni: potem przeglądałem lud i kapłanów, a z synów Lewiego nie znalazłem tam żadnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Przetoż posłałem Elijezera, Aryjela, Semejasza, i Elnatana, i Jaryba, i Elnatana i Natana, i Zacharyjasza, i Mesullama, przedniejszych, i Jojaryba, i Elnatana, mężów uczonych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'I rozkazałem im do Iddona, przełożonego nad miejscem Kasyfii, i włożyłem w usta ich słowa, które mieli mówić do Iddona, Achywa i Netynejczyków na miejscu Kasyfii, aby nam przywiedli sług do domu Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'I przywiedli nam według ręki Boga naszego łaskawej nad nami, męża nauczonego z synów Maheli, syna Lewiego, syna Izraelowego, i Serebijasza, i synów jego, i braci jego ośmnaście;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'I Hasabijasza, a z nim Jesajasza z synów Merarego, braci jego, i synów ich dwadzieścia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'Nadto z Netynejczyków, których był postanowił Dawid i przedniejsi ku posłudze Lewitów, Netynejczyków dwieście i dwadzieścia; ci wszyscy z imienia mianowani byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Tedym tam zapowiedział post u rzeki Achawy, abyśmy się dręczyli przed Bogiem naszym, a szukali od niego drogi prostej sobie, i dziatkom naszym, i wszystkiej majętności naszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Bom się wstydził prosić u króla o jaki poczet jezdnych, aby nam byli na pomocy przeciwko nieprzyjaciołom w drodze; bośmy byli powiedzieli królowi, mówiąc: Ręka Boga naszego jest nad wszystkimi, którzy go szukają uprzejmie, ale moc jego i popędliw ość jego przeciwko wszystkim, którzy go opuszczają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'A gdyśmy pościli, i prosiliśmy o to Boga naszego, wysłuchał nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Tedym odłączył z przedniejszych kapłanów dwanaście: Serebijasza, Hasabijasza, a z nimi braci ich dziesięć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'I odważyłem im srebro, i złoto, i naczynia na ofiarę podnoszenia do domu Boga naszego, które ofiarowali król i rada jego, i książęta jego, i wszystek lud Izraelski, ile się go znalazło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Odważyłem, mówię do rąk ich srebra talentów sześćset i pięćdziesiąt, a naczynia srebrnego sto talentów, przytem złota sto talentów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'Czasz też złotych dwadzieścia, ważących po tysiąc łótów, a dwa naczynia z mosiądzu wybornego, tak piękne jako złoto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'Potemem rzekł do nich: Wyście poświęceni Panu, i naczynia także poświęcone, a to srebro i to złoto dobrowolnie ofiarowane jest Panu, Bogu ojców waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Pilnujcież a strzeżcie, aż to odważycie przed kapłanami przedniejszymi, i Lewitami, i książętami z domów ojcowskich w Izraelu w Jeruzalemie, w gmachach domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'A tak wzięli kapłani i Lewitowie wagę onego srebra, i złota, i naczynia, aby je odnieśli do Jeruzalemu, do domu Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Zatem ruszyliśmy się od rzeki Achawy dwunastego dnia, miesiąca pierwszego, abyśmy szli do Jeruzalemu; a ręka Boga naszego była nad nami, i wyrwała nas z ręki nieprzyjaciela i czyhającego na nas w drodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'I przyszliśmy do Jeruzalemu, i zamieszkaliśmy tam przez trzy dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'A dnia czwartego odważono srebro, i złoto, i naczynie ono w domu Boga naszego do ręki Meremota, syna Uryjasza kapłana, z którym był Eleazar, syn Fineesowy; z nimi też byli Josabad, syn Jesuego, i Noadyjasz, syn Binnujego, Lewitowie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'Pod liczbą i wagą wszystko, i zapisano wagę tego wszystkiego onegoż czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Wróciwszy się tedy z niewoli ci, którzy byli w pojmaniu, ofiarowali Bogu Izraelskiemu cielców dwanaście za wszystkiego Izraela, baranów dziewięćdziesiąt i sześć, baranków siedmdziesiąt i siedm, kozłów za grzech dwanaście, to wszystko na całopalenie Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'I oddali wyroki królewskie starostom królewskim, i książętom za rzeką, a ci byli pomocą ludowi i domowi Bożemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'A gdy się to odprawiło, przystąpili do mnie książęta, mówiąc: Nie odłączył się lud Izraelski, i kapłani, i Lewitowie od narodów tych ziem; ale czynią według obrzydliwości Chananejczyków, Hetejczyków, Ferezejczyków, Jebuzejczyków, Ammonitczyków, Moabczyków, Egipczyków, i Amorejczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Albowiem pojęli córki ich sobie i synom swym, a pomięszało się nasienie święte z narodami tych ziem, a ręka książąt i zwierzchności pierwsza była w tem przestępstwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Co gdym usłyszał, rozdarłem suknię moję i płaszcz mój, a rwałem włosy na głowie mojej, i na brodzie mojej, i siedziałem, zdumiawszy się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'I zgromadzili się do mnie wszyscy, którzy drżą przed słowem Boga Izraelskiego dla przestępstwa tych, którzy przyszli z niewoli, a jam siedział, zdumiawszy się, aż do ofiary wieczornej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'Ale pod czas ofiary wieczornej wstałem z utrapienia mego, mając rozdartą suknię moję i płaszcz mój, a poklęknąwszy na kolana swe, wyciągnąłem ręce swe ku Panu, Bogu memu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'I rzekłem: Boże mój! wstydci mię, i sromam się podnieść, Boże mój! oblicza mego do ciebie; albowiem nieprawości nasze rozmnożyły się nad głową, a grzechy nasze urosły aż ku niebu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Ode dni ojców naszych byliśmy w wielkim grzechu aż do dnia tego, a przez nieprawości nasze wydaniśmy, królowie nasi i kapłani nasi, w ręce królów ziemskich pod miecz, w niewolę, i na łup, i na zawstydzenie twarzy naszej, jako się to dziś dzieje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'Ale teraz, jakoby w prędkiem okamgnieniu, stała się nam łaska od Pana, Boga naszego, że nam zostawił ostatki, i dał nam mieszkanie na miejscu świętem swojem, aby oświecił oczy nasze Bóg nasz, a dał nam trochę wytchnienia z niewoli naszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Bo chociaśmy byli niewolnikami, przecież w niewoli naszej nie opuścił nas Bóg nasz, ale skłonił ku nam miłosierdzie przed królmi Perskimi, dawszy nam wytchnienie, abyśmy wystawili dom Boga naszego, i naprawili spustoszenia jego; nawet dał nam ogrodzenie w Judztwie i w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'Przetoż cóż teraz rzeczemy, o Boże nasz! po tem? ponieważeśmy opuścili rozkazania twoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'Któreś ty przykazał przez sług twoich proroków, mówiąc: Ziemia, do której wnijdziecie, abyście ją posiedli, jest ziemia nieczysta przez nieczystotę ludu tych ziem, dla obrzydłości ich, któremi ją napełnili od końca do końca nieczystością swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'A przetoż nie dawajcie córek waszych synom ich, ani bierzcie synom waszym córek ich, i nie szukajcie pokoju ich, i dobrego ich aż na wieki, abyście byli umocnieni, a pożywali dóbr tej ziemi, i podali ją w dziedzictwo synom waszym aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'A po tem wszystkiem, co przyszło na nas dla spraw naszych złych i dla grzechu naszego wielkiego, ponieważeś ty, Boże nasz! zawściągnął karania, abyśmy nie byli potłumieni dla nieprawości naszej, aleś nam dał wybawienie takowe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'Izali się obrócimy ku zgwałceniu przykazań twoich, powinowacąc się z tymi narodami obrzydłymi? izalibyś się surowie nie gniewał na nas, abyś nas wyniszczył, aby nikt nie został i nie uszedł?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'O Panie, Boże Izraelski! sprawiedliwyś ty; bośmy pozostałe ostatki, jako się to dziś pokazuje. Otośmy my przed obliczem twojem w przewinieniu naszeem, choć się nie godzi stawiać przed oblicze twoje dla tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'A gdy się modlił Ezdrasz, i wyznawał grzechy z płaczem, leżąc przed domem Bożym, zebrało się do niego z Izraela zgromadzenie bardzo wielkie mężów i niewiast i dziatek; a płakał lud wielkim płaczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'Tedy odpowiadając Sechanijasz, syn Jechyjelowy z synów Elamowych, rzekł do Ezdrasza: Myśmyć zgrzeszyli przeciwko Panu, Bogu naszemu, żeśmy pojęli żony obce z narodu tej ziemi; ale wżdy ma jeszcze nadzieję Izrael przytem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Tylko teraz uczyńmy przymierze z Bogiem naszym, że porzucimy wszystkie żony i narodzone z nich, według rady Pańskiej, i tych, którzy drżą przed przykazaniem Boga naszego, a niech to będzie podług zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Wstańże, bo ta rzecz tobie należy, a my będziemy z tobą; zmocnij się, a uczyń tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Tedy wstał Ezdrasz, i poprzysiągł książąt kapłańskich, i Lewitów, i wszystkiego Izraela, aby uczynili według tego słowa. I przysięgli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'A tak wstawszy Ezdrasz od domu Bożego szedł do komory Jochanana, syna Elijasybowego, a wszedłszy tam, nie jadł chleba, i wody nie pił; albowiem był żałośny dla przestępstwa tych, co się wrócili z niewoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'Zatem kazali obwołać w Judztwie i w Jeruzalemie między wszystkimi, którzy przyszli z niewoli, aby się zgromadzili do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'A ktobykolwiek nie przyszedł we trzech dniach według uradzenia książąt i starszych, aby przepadła wszystka majętność jego, a sam aby był wyłączony od zgromadzenia tych, co przyszli z niewoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Przetoż zgromadzili się wszyscy mężowie z Judy i z Benjamina do Jeruzalemu we trzech dniach, dwudziestego dnia miesiąca dziewiątego, i siedział wszystek lud na placu przed domem Bożym, drżąc dla onej rzeczy i dla deszczu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Tedy powstawszy Ezdrasz kapłan rzekł do nich: Wyście zgrzeszyli, iżeście pojęli żony obce, przydawając do grzechów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Przetoż uczyńcie teraz wyznanie przed Panem, Bogiem ojców waszych, a wykonajcie wolę jego, i odłączcie się od narodów tej ziemi, i od żon obcych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'I odpowiedziało wszystko ono zgromadzenie, i rzekło głosem wielkim: Jakoś nam powiedział, tak uczynimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Ale wielki jest lud, i czas dżdżysty, i nie możemy stać na dworze; dotego ta sprawa nie jest dnia jednego, ani dwóch; bo nas wiele, którzyśmy się tego przestępstwa dopuścili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Prosimy tedy, niechże będą postanowieni książęta nasi nad wszystkiem zgromadzeniem; a ktobykolwiek był w miastach naszych, co pojął żony obce, niechaj przyjdzie na czas zamierzony, a z nimi starsi z każdego miasta, sędziowie ich, abyśmy tak odwrócili gniew popędliwości Boga naszego od nas dla tej sprawy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'A tak Jonatan, syn Asahijelowy, i Jachsyjasz, syn Tekujego, byli na to wysądzeni; ale Mesullam i Sebetaj, Lewitowie, pomagali im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'Tedy uczynili tak ci, co przyszli z niewoli. I odłączeni są Ezdrasz kapłan, i mężowie przedniejsi z domów ojcowskich według domów ojców swoich; a ci wszyscy z imienia mianowani byli, i zasiedli dnia pierwszego, miesiąca dziesiątego, aby się o tem wywiadywali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'A odprawowali to przy wszystkich mężach, którzy byli pojęli żony obce, aż do pierwszego dnia, miesiąca pierwszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'I znaleźli się z synów kapłańskich, którzy byli pojęli żony obce: z synów Jesui, syna Jozedekowego, i z braci jego Maasejasz i Elijezer, i Jaryb, i Giedalijasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'I dali ręce swe, że mieli porzucić żony swe; a ci, którzy zgrzeszyli, ofiarowali każdy barana z stada za występek swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'A z synów Immerowych: Hanani i Zabadyjasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'A z synów Harymowych: Maasyjasz i Elijasz, i Semejasz, i Jechyjel, i Uzyjasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'A z synów Passurowych: Elijenaj, Maasejasz, Izmael, Natanael, Jozabad, i Elasa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'A z Lewitów: Jozabad, i Symei, i Kielajasz, (ten jest Kielita) Petachyjasz, Judas, i Elijezer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'A z śpiewaków: Elijasyb; a z odźwiernych: Sallum i Telem, i Ury.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'A z Izraela, z synów Farosowych: Ramijasz, i Jezyjasz, i Malchyjasz, i Miamin, i Elazar, i Malchyjasz, i Benajasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'A z synów Elamowych: Matanijasz, Zacharyjasz, i Jechyjel, i Abdy, i Jerymot, i Elijasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'A z synów Zattuowych: Elijenaj, Elijasyb, Matanijasz, i Jerymot, i Zabad, i Asysa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'A z synów Bebajowych: Johanan, Hananijasz, Zabbaj, Atlaj;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'A z synów Bani: Mesullam, Malluch, i Adajasz, Jasub, i Seal, Jeramot;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'A z synów Pachatmoabowych Adna, i Chelal, Benajasz, Maasejasz, Matanijasz, Besaleel, i Binnui, i Manase;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'A z synów Harymowych: Elijezer, Isyjasz, Malchyjasz, Semaajasz, Symeon,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Maluch, Samaryjasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Z synów Hasumowych: Matenajasz, Matata, Zabad, Elifelet, Jeremijasz, Manase, Symhy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Z synów Bani: Maadaj, Amram, i Uel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Banajasz, Bedyjasz, i Cheluhu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Wanijasz, Meremot, Elijasyb,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Mattanijasz, Matenajasz, i Jahasaw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'I Bani, i Binnui, Symhy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'I Selemijasz, i Natan, i Adajasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Machnadbaj, Sasaj, Saraj,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Asarel, I Selemijasz, Semaryjasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Sallum, Amaryjasz, i Józef.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Z synów Nebowych: Jehijel, Matytyjasz, Zabad, Zebina, Jaddaj, i Joel, i Benajasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Ci wszyscy pojęli byli żony obce; a były między niemi niewiasty, które im narodziły synów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Słowa Nehemijasza, syna Hachalijaszowego. I stało się miesiąca Chyslew, roku dwudziestego (Aswerusa króla) gdym był na zamku w Susan,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'Że przyszedł Chanani, jeden z braci moich, a z nim niektórzy mężowie z Judy, którychem się pytał o Żydów, którzy pozostali i wyszli z więzienia, i o Jeruzalem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'I odpowiedzieli mi: Te ostatki, które pozostały z więzienia tam w onej krainie, są w wielkiem utrapieniu, i w zelżywości: nadto mur Jeruzalemski rozwalony jest, i bramy jego spalone są ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'A gdym usłyszał te słowa, siadłszy płakałem i narzekałem przez kilka dni, poszcząc i modląc się przed obliczem Boga niebieskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'I rzekłem; Proszę Panie, Boże niebieski, mocny, wielki i straszny! który strzeżesz umowy, i miłosierdzia z tymi, którzy cię miłują, i strzegą przykazania twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Niech będzie proszę ucho twoje nakłonione, a oczy twoje otworzone, abyś usłyszał modlitwę sługi twego, którą się ja dziś modlę przed tobą we dnie i w nocy za synami Izraelskimi, sługami twymi, i wyznaję grzechy synów Izraelskich, któremiśmy zgrzes zyli przeciw tobie; i ja i dom ojca mego zgrzeszyliśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Srodześmy wystąpili przeciwko tobie, i nie przestrzegaliśmy przykazań, i ustaw, i sądów, któreś przykazał Mojżeszowi, słudze twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Wspomnij proszę na słowo, któreś przykazał Mojżeszowi, słudze twemu, mówiąc: Jeżli wy wystąpicie, tedy Ja was rozproszę między narody;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'Ale jeżli się nawrócicie do mnie, a strzedz będziecie przykazań moich, i czynić je, choćbyście byli wygnani na kraj świata, tedy i stamtąd was zgromadzę, i przyprowadzę was na miejsce, którem obrał, aby tam przebywało imię moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Wszak oni są słudzy twoi, i lud twój, któryś odkupił mocą twoją wielką, i ręką twą silną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Proszę o Panie! niech teraz będzie ucho twoje nakłonione ku modlitwie sługi twego i ku modlitwie sług twoich, którzy mają wolę bać się imienia twego; a zdarz dziś, proszę, słudze twemu, i spraw mu miłosierdzie przed tym mężem. A jam był podczaszym królewskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'I stało się miesiąca Nisan roku dwudziestego Artakserksesa króla, gdy było wino przed nim, że wziąwszy wino, podałem je królowi, a nie bywałem przedtem tak smutny przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'I rzekł mi król: Czemuż twarz twoja tak smutna, gdyż nie chorujesz? Nic to innego, jedno smutek serca. I zlękłem się nader bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'I rzekłem do króla: Niech król na wiki żyje. Jakoż nie ma być smutna twarz moja, gdyż miasto, dom grobów ojców moich, zburzono, a bramy jego ogniem popalono?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Znowu rzekł do mnie król: Czegoż ty żądasz? A jam się modlił Bogu niebieskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'I rzekłem do króla: Zdali się to za rzecz dobrą królowi, i jeżli ma łaskę sługa twój przed obliczem twojem, proszę, abyś mię posłał do ziemi Judzkiej, do miasta grobów ojców moich, abym je pobudował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'Nadto rzekł mi król (a królowa siedziała podle niego): Długoż będziesz na tej drodze, i kiedy się wrócisz? I podobało się to królowi, i posłał mię, gdym mu zamierzył pewny czas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Zatemem rzekł do króla: Zdali się to za rzecz dobrą królowi, niech mi dadzą listy do starostów za rzeką, aby mię przeprowadzili, ażbym przyszedł do ziemi Judzkiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'I list do Asafa, dozorcy lasów królewskich, aby mi dał drzewa na przykrycie bram pałacu przy domu Bożym, i na mur miejski, i na dom, do którego wnijdę. I dał mi król listy według ręki Boga mego łaskawej nademną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'A gdym przyszedł do starostów za rzeką, oddałem im listy królewskie. Posłał też był ze mną król rotmistrzów i jezdnych:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Co gdy usłyszał Sanballat Horonitczyk, i Tobijasz, sługa Ammonitczyk, bardzo ich to mierziało, że przyszedł człowiek, który się starał o dobro synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'Zatem przyszedłszy do Jeruzalemu, mieszkałem tam przez trzy dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'A wstawszy w nocy, ja i mężów trocha ze mną, nie oznajmiłem nikomu, co Bóg mój podał do serca mego, abym uczynił w Jeruzalemie; bydlęcia też nie miałem z sobą, oprócz bydlęcia, na któremem jechał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'I wyjechałem bramą nad doliną w nocy, ku żródłu smoczemu, i ku bramie gnojowej, i oglądałem mury Jeruzalemskie, które były rozwalone, i bramy jego, które były popalone ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'Potem jechałem ku bramie żródła, i ku sadzawce królewskiej, gdzie nie było miejsca bydlęciu, na któremem jechał, aby przejść mogło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Przetoż jechałem nad potokiem w nocy, a oglądałem mury; skąd wracając się, wyjechałem bramą nad doliną, i takiem powrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Ale książęta nie wiedzieli, gdziem jeżdził, i com czynił; bom Żydom, ani kapłanom, ani książętom, ani urzędnikom, ani żadnemu rzemieślnikowi tego aż dotąd nie oznajmił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Przetożem rzekł do nich: Wy widzicie, w jakiemeśmy uciśnieniu, a jako Jeruzalem spustoszone, i bramy jego popalone są ogniem. Pójdżcież, a budujmy mury Jeruzalemskie, abyśmy nie byli więcej na hańbę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'A gdym im oznajmił, że ręka Boga mego była łaskawa nademną, także i słowa królewskie, które do mnie mówił, rzekli: Wstańmyż a budujmy. I zmocnili ręce swe ku dobremu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Co słysząc Sanballat Horonitczyk, i Tobijasz, sługa Ammonitczyk i Giesem Arabczyk, szydzili z nas, i lekce nas sobie poważyli mówiąc: Cóż to za rzecz, którą czynicie? albo się przeciw królowi buntujecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'I odpowiedziałem im, a rzekłem do nich: Bóg niebieski, ten nam poszczęści, a my słudzy jego, wstańmy a budujmy; ale wy nie macie działu, ani prawa, ani pamiątki w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'Potem powstał Elijasyb, kapłan najwyższy, i bracia jego kapłani, i budowali bramę owczą. I zbudowali ją, i przyprawili wrota do niej; aż do wieży Mea zbudowali ją, i aż do wieży Chananeel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'A podle niego budowali mężowie z Jerycha, a podle nich budował Zachur, syn Immrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'A bramę rybną budowali synowie Senaa, którzy ją też przykryli i przyprawili wrota do niej, i zamki jej, i zawory jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'A podle nich poprawiał Meremot, syn Uryjasza, syna Kosowego; a podle nich poprawiał Mesullam, syn Barachyjaszowy, syna Mesezabelowego; a podle nich poprawiał Sadok, syn Baany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'Podle nich zasię poprawiali Tekuitczycy; ale ci, co byli zacniejsi z nich, nie podłożyli szyi swej pod robotę pana swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'A bramę starą poprawiali Jojada, syn Faseachowy, i Mesullam, syn Besodyjaszowy; ci ją przykryli, i przyprawili wrota do niej, i zamki jej, i zawory jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'A podle nich poprawiał Melatyjasz Gabaonitczyk, Jadon Meronitczyk, mężowie z Gabaon i z Masfa, aż do stolicy książęcej, z tej strony rzeki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Podle nich poprawiał Husyjel, syn Charchajaszowy, z złotnikami; a podle niego poprawiał Chananijasz, syn aptekarski; a Jeruzalemu zaniechali aż do muru szerokiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'A podle nich poprawiał Rafajasz, syn Churowy, przełożony nad połową powiatu Jeruzalemskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'A podle nich poprawiał Jedajasz, syn Harumafowy, i przeciw swemu domowi; a podle niego poprawiał Hattus, syn Hasbonijaszowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Części zaś drugiej poprawiał Malchyjasz, syn Harymowy, i Hasub, syn Pachatmoabowy, także i wieżę Tannurym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'A podle niego poprawiał Sallum, syn Hallochesowy, przełożony nad połową powiatu Jeruzalemskiego, sam i córki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Bramy nad doliną poprawiał Chanun, i obywatele Zanoe; cić ją budowali, i przyprawili wrota do niej, zamki jej, i zawory jej; i na tysiąc łokci muru aż do bramy gnojowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Bramy zaś gnojowej poprawiał Melchyjasz, syn Rechaby, przełożony nad powiatem Betcherem; tenci ją zbudował, i przyprawił wrota do niej, zamki jej, i zawory jej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Dotego bramy żródła poprawiał Sallon, syn Cholhozowy, przełożony nad powiatem Masfa; a ten ją zbudował, i przykrył ją, i przyprawił wrota do niej, i zamki jej, i zawory jej, i mur nad stawem Selach ku ogrodowi królewskiemu aż do schodu, po którym schodzą z miasta Dawidowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Zatem poprawiał Nehemijasz, syn Hasbuka, przełożony nad połową powiatu Betsur, aż przeciwko grobom Dawidowym i aż do stawu urobionego, i aż do domu mocarzów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Za nim poprawiali Lewitowie Rehum, syn Bani; podle niego poprawiał Hasabijasz, przełożony nad połową powiatu Ceile z powiatem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Za nim zasię poprawiali bracia ich, Bawaj, syn Chenadadowy, przełożony nad połową powiatu Ceile.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'A podle niego poprawiał Eser, syn Jesui, przełożony nad Masfą, części drugiej przeciw miejscu, kędy chodzą do zbrojowni nazwanej Mikzoa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Po nim wzruszony gorliwością poprawiał Baruch, syn Zabbajowy, części drugiej od Mikzoa aż do drzwi domu Elijasyba, najwyższego kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Za nim poprawiał Meremot, syn Uryjasza, syn Kosowego, części drugiej, ode drzwi domu Elijasybowego aż do końca domu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'A za nim poprawiali kapłani, którzy mieszkali w równinie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Za nimi poprawiał Benjamin i Hasub, przeciw domom swoim; za nimi poprawiał Azaryjasz, syn Maasejasza, syna Ananijaszowego, podle domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Za nim poprawiał Bennui, syn Chenadadowy, części drugiej od domu Azaryjaszowego aż do Mikzoa, i aż do rogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, syn Uzajego przeciw Mikzoa, i wieży wysokiej, wywiedzionej z domu królewskiego, która była w sieni więzienia; po nim poprawiał Fadajasz, syn Farosowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, 'A Netynejczycy, co mieszkali w Ofel, poprawiali aż na przeciwko bramie wodnej na wschód słońca, i wieży wysokiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Za nimi poprawiali Tekuitczykowie drugą część przeciw wieży wielkiej i wysokiej aż do muru Ofel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Od bramy końskiej poprawiali kapłani, każdy przeciw domowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Za nimi poprawiał Sadok, syn Immerowy, przeciw domowi swemu, a za nim poprawiał Semejasz, syn Sechenijaszowy, stróż barmy wschodniej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Za nim poprawiał Chananijasz, syn Selemijaszowy, i Chanun, syn Salafowy szósty, części drugiej; za nim poprawiał Mesullam, syn Berechyjaszowy, przeciw gmachowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Za nim poprawiał Malchijasz, syn złotniczy, aż do domu Netynejczyków, i kupców, przeciw bramie sądowej, i aż do sali narożnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'A między salą narożną aż do bramy owczej poprawiali złotnicy i kupcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'A gdy usłyszał Sanballat, iż budujemy mury, rozgniewał się, a rozgniewawszy się bardzo, szydził z Żydów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'I mówił przed braćmi swymi i przed rycerstwem Samaryjskiem, i rzekł: Cóż wżdy ci Żydowie niedołężni czynią? Także ich zaniechamy? I będąż ofiarować? Izali tego za dzień dokończą? Izali wskrzeszą kamienie z gromad gruzu, które spalono?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Ale Tobijasz Ammonitczyk będąc przy nim, rzekł: Niech budują; jednak kiedy przyjdzie liszka, przebije mur ich kamienny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Wysłuchajże, o Boże nasz! bośmy wzgardzeni, a obróć pohańbienie ich na głowę ich, a daj ich na łup w ziemi niewoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Nie pokrywajże nieprawości ich, a grzech ich od twarzy twej niech nie będzie zgładzony; bo cię do gniewu pobudzili dla tych, co budują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Lecześmy my budowali ten mur, i spojony jest wszystek mur aż do połowy swej, a lud miał serce do roboty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'A gdy usłyszeli Sanballat i Tobijasz, i Arabczycy, i Ammonitowie, i Azodczycy, że przybywało wzdłuż murów Jeruzalemskich, a iż się poczęli rozerwania murów zawierać, bardzo się rozgniewali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'Przetoż zbuntowali się wszyscy wespół, aby szli walczyć przeciw Jeruzalemowi, i uczynić wstręt robocie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Myśmy się jednak modlili Bogu naszemu, i postawiliśmy straż przeciwko nim we dnie i w nocy, bojąc się ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'Bo rzekli Żydowie: Zwątlała siła noszącego, a gruzu jeszcze wiele; a my nie będziemy mogli budować muru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Nadto rzekli nieprzyjaciele nasi: Niech nie wzwiedzą ani obaczą, aż przyjdziemy między nich, i pomordujemy ich, a tak zastanowimy tę robotę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'A gdy przyszli Żydowie, którzy mieszkali około nich, i powiedzieli nam na dziesięć kroć: Pilnujcie ze wszystkich miejsc, z którychby przyjść mogli do nas;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'Tedym postawił na dolnych miejscach za murem i na miejscach wysokich, postawiłem mówię lud według domów z mieczami ich, z włóczniami, i z łukami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'A gdym to oglądał, wstawszy rzekłem do starszych, i do przełożonych, i do innego ludu: Nie bójcie się ich; na Pana wielkiego i straszliwego pamiętajcie, a walczcie za braci waszych, za synów waszych, i za córki wasze, za żony wasze, i za domy was ze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'A gdy usłyszeli nieprzyjaciele nasi, iż nam to oznajmiono, tedy rozproszył Bóg radę ich, a myśmy się wszyscy wrócili do murów, każdy do roboty swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'A wszakże od onego czasu połowa sług moich robiła, a połowa ich trzymała włócznie, i tarcze, i łuki, i pancerze, a przedniejsi stali za wszystkim domem Judzkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'Ci też, którzy budowali mury, i którzy nosili brzemiona, i co nakładali, jedną ręką swoją robili, a drugą trzymali broń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'A z onych, którzy budowali, miał każdy miecz swój przypasany do biódr swych, i tak budowali; a ten co w trąbę trąbił, był przy mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'Bom rzekł do starszych i przełożonych, i do innego ludu: Robota wielka i szeroka; a myśmy się rozstrzelali po murze daleko jeden od drugiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'A przetoż na któremkolwiek byście miejscu usłyszeli głos trąby, tam się zbierajcie do nas; Bóg nasz będzie walczył za nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Pilnowaliśmy tedy roboty, a połowa ich trzymała włócznie, od wejścia zorzy, aż gwiazdy wschodziły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Na tenże czas rzekłem do ludu: Każdy z sługą swym niech nocuje w Jeruzalemie, aby nam byli w nocy dla straży, a we dnie dla roboty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Przetoż i ja, i bracia moi, i słudzy moi, i straż, która jest ze mną, nie zewleczemy szat naszych, a każdy niech ma broń swą i wodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'I wszczęło się wielkie wołanie ludu i żon ich przeciw Żydom, braciom swym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Albowiem niektórzy mówili: Wiele nas, co synów naszych i córki nasze zastawiamy, abyśmy nabywszy zboża, jeść i żyć mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'Inni zaś mówili: Role nasze, i winnice nasze, i domy nasze zastawiać musimy, abyśmy nabyli zboża w tym głodzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Inni zaś mówili: Napożyczaliśmy pieniędzy, żebyśmy dali podatek królowi, zastawiwszy role nasze i winnice nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Choć oto ciało nasze jest jako ciało braci naszych, a synowie nasi są jako synowie ich: wszakże oto my musimy dawać synów naszych i córki nasze w niewolę, i niektóre z córek naszych są już w niewolę podane, a nie mamy przemożenia w rękach naszych, abyśmy je wykupili, gdyż role nasze i winnice nasze inni trzymają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Przetoż rozgniewałem się bardzo, gdym usłyszał wołanie ich, i słowa takowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'I umyśliłem w sercu swem, abym sfukał przedniejszych i przełożonych, mówiąc do nich: Wy jesteście, którzy obciążacie każdy brata swego; i zebrałem przeciwko nim zgromadzenie wielkie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'I rzekłem do nich: Myśmy odkupili braci naszych, Żydów, którzy byli zaprzedani poganom, podług przemożenia naszego; a jeszczeż wy sprzedawać będziecie braci waszych, a tak jakoby nam ich sprzedawać będziecie? I umilknęli, i nie znaleźli, coby odpo wiedzieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Nadtom rzekł: Nie dobra to rzecz, którą wy czynicie; azaż nie w bojaźni Boga naszego chodzić macie raczej niż w hańbie poganów, nieprzyjaciół naszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'I jać też z braćmi moimi, i z sługami moimi, pożyczyliśmy im pieniędzy, i zboża; odpuśćmyż im proszę ten ciężar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Wróćcież im dziś proszę role ich, winnice ich, oliwnice ich, i domy ich, i setną część pieniędzy i zboża, wina, i oliwy, którą wy od nich wyciągacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Tedy odpowiedzieli: Wrócimy, a nie będziemy się od nich tego upominać; tak uczynimy, jakoś ty powiedział. Wezwałem też i kapłanów, a poprzysiągłem ich, aby także uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Potemem wytrząsnął zanadrza moje, i rzekłem: Niech tak wytrząśnie Bóg każdego męża z domu jego i z pracy jego, któryby nie uczynił dosyć temu słowu; a niech tak będzie wytrząśniony i wypróżniony. I rzekło wszystko zgromadzenie: Amen. I chwalili Pana, a lud uczynił jako było rzeczono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Owszem ode dnia, którego mi przykazał król, abym był książęciem ich w ziemi Judzkiej, od roku dwudziestego aż do roku trzydziestego i wtórego Artakserksesa króla, przez dwanaście lat, ja i bracia moi obrokuśmy książęcego nie jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Choć książęta pierwsi, którzy byli przedemną, obciążali lud, biorąc od nich chleb i wino, mimo srebra syklów czterdzieści; także i słudzy ich używali okrucieństwa nad ludem; alem ja tak nie czynił dla bojaźni Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Owszem i około poprawy tego muru pracowałem, a przecięśmy roli nie kupili; więc i wszyscy słudzy moi byli tam zgromadzeni dla roboty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Nadto z Żydów i przełożonych sto i pięćdziesiąt mężów, i którzy do nas przychodzili z pogan okolicznych, jadali u stołu mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'Przetoż gotowano na każdy dzień wołu jednego, owiec sześć wybornych, i ptaki gotowano dla mnie, a każdego dziesiątego dnia rozmaitego wina hojnie dawano; wszakżem się obroku książęcego nie upominał; albowiem ciężka była niewola na ten lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Wspomnijże na mię, Boże mój! ku dobremu według wszystkiego, com czynił ludowi twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'A gdy usłyszał Sanballat, i Tobijasz, i Giesem Arabczyk, i inni nieprzyjaciele nasi, żem zbudował mur, a że w nim nie zostawało żadnej rozwaliny, chociażem jeszcze wtenczas nie był przyprawił wrót do bram:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'Tedy posłał Sanballat, i Giesem do mnie mówiąc: Przyjdź, a zejdźmy się społem we wsiach, które są na polu Ono. Ale oni myślili uczynić mi co złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'Przetoż posłałem do nich posłów, wskazując: Zacząłem robotę wielką, przetoż nie mogę zjechać; bo przeczżeby miała ustać ta robota, gdybym jej zaniechawszy jechał do was?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Tedy posłali do mnie w tejże sprawie po cztery kroć. A jam im odpowiedział temiż słowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Potem Sanballat posłał do mnie w tejże sprawie piąty raz sługę swego i list otwarty, w ręce jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'W którym to było napisane: Jest posłuch między narodami, jako Gasmus powiada, że ty i Żydowie myślicie się z mocy wybić, a że ty dlatego budujesz mur, abyś był nad nimi królem ich, jako się to pokazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'Do tego, żeś i proroków postanowił, aby powiadali o tobie w Jeruzalemie, mówiąc: On jest królem w Judzie. Teraz tedy dojdzie to króla; przetoż przyjdź, a naradzimy się spółecznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Alem posłał do niego, mówiąc: Nie jest to, co powiadasz; ale sam sobie to wymyślasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Albowiem oni wszyscy straszyli nas, mówiąc: Osłabieją ręce ich przy robocie, i nie dokonają; prztoż teraz, o Boże! zmocnij ręce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'A gdym wszedł w dom Semejasza, syna Delajaszowego, syna Mehetabelowego, który był w zawarciu, rzekł mi: Zejdźmy się do domu Bożego, w pośród kościoła, i zamknijmy drzwi kościelne; bo przyjdą, chcąc cię zabić, a w nocy przyjdą, aby cię zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Któremum rzekł: Takowyżby mąż, jakim ja jest, miał uciekać? Któż takowy, jakom ja, coby wszedłszy do kościoła, żyw został? Nie wnijdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'I poznałem, że go Bóg nie posłał ale proroctwo mówił przeciwko mnie, bo go Tobijasz i Sanballat byli przenajęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'Przeto bowiem przenajęty był, abym się uląkł, i tak uczynił, i zgrzeszył, ażeby mi to u nich było na złe imię, czemby mi urągali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Pomnijże, o Boże mój! na Tobijasza i Sanballata, według takowych uczynków ich: także na Noadyję prorokinię, i na innych proroków, którzy mię straszyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'A tak dokonany jest on mur dwudziestego i piątego dnia miesiąca Elul, pięćdziesiątego i drugiego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'A gdy to usłyszeli wszyscy nieprzyjaciele nasi, i widzieli to wszyscy narodowie, którzy byli około nas, upadło im bardzo serce;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Bo poznali, że się ta sprawa od Boga naszego stała. W oneż dni wiele przedniejszych z Judy listy swe często posyłali do Tobijasza, także od Tobijasza przychodziły do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Bo wiele ich było w Judzie, co się z nim sprzysięgli, gdyż on był zięciem Sechanijasza, syna Arachowego; a Jochanan, syn jego, pojął był córkę Mesullama, syna Barachyjaszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Nadto i dobroczynność jego opowiadali przedemną, i słowa moje odnosili mu; a listy posyłał Tobijasz, aby mię straszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'A gdy był dobudowany mur, i wystawiłem wrota, i postanowieni byli odźwierni, i śpiewacy, i Lewitowie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'Rozkazałem Chananijemu, bratu memu, i Chananijaszowi, staroście zamku Jeruzalemskiego: (bo ten był mąż wierny, i bojący się Boga nad wielu innych;)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'I rzekłem do nich: Niech nie otwierają bram Jeruzalemskich, aż ogrzeje słońce; a gdy ci, co tu stawają, zamkną bramę, opatrzcież ją. A tak postanowiłem straż z obywateli Jeruzalemskich, każdego na straży jego, i każdego na przeciwko domowi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'A miasto było szerokie i wielkie, ale ludu mało w murach jego, a jeszcze nie były domy pobudowane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'Przetoż podał Bóg mój do serca mego, abym zebrał przedniejszych, i przełożonych, i lud, aby byli obliczeni podług rodzaju. I znalazłem księgi rodu tych, którzy się tu najpierwej przyprowadzili, i znalazłem w nich to opisanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Cić są ludzie onej krainy, którzy wyszli z pojmania i z niewoli, w którą ich był zaprowadził Nabuchodonozor, król Babiloński; a wrócili się do Jeruzalemu i do Judy, każdy do miasta swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'Którzy przyszli z Zorobabelem, z Jesuą, Nehemijaszem, Azaryjaszem, Rahamijaszem, Nechamanem, Mardocheuszem, Bilsanem, Misperetem, Bigwajem, Nechumem, Baaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'A poczet mężów ludu Izraelskiego taki jest: Synów Farosowych dwa tysiące sto i siedmdziesiąt i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Synów Sefatyjaszowych trzy sta siedmdziesiąt i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Synów Arachowych sześć set pięćdziesiąt i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Synów Pachatmoabowych, synów Jesui, i Joabowych dwa tysiące ośm set i ośmnaście;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Synów Elamowych tysiąc dwieście pięćdziesiąt i cztery;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Synów Zattuowych ośm set czterdzieści i pięć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Synów Zachajowych siedm set i sześćdziesiąt;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Synów Binnujowych sześć set czterdzieści i ośm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Synów Bebajowych sześć set dwadzieścia i ośm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Synów Azgadowych dwa tysiące trzy sta dwadzieścia i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Synów Adonikamowych sześć set sześćdziesiąt i siedm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Synów Bigwajowych dwa tysiące sześćdziesiąt i siedm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Synów Adynowych sześć set pięćdziesiąt i pięć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Synów Aterowych, co poszli z Ezechyjasza, dziewięćdziesiąt i ośm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Synów Hasumowych trzy sta dwadzieścia i ośm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Synów Besajowych trzy sta dwadzieścia i cztery;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Synów Charyfowych sto i dwanaście;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Synów z Gabaonu dziewięćdziesiąt i pięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Mężów z Betlehemu i Netofatu sto ośmdziesiąt i ośm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Mężów z Anatotu sto dwadzieścia i ośm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Mężów z Bet Azmawetu czterdzieści i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Mężów z Karyjatyjarymu, z Kafiry i z Beerotu siedm set czterdzieści i trzy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Mężów z Ramy i z Gabaa sześć set dwadzieścia i jeden;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Mężów z Machmas sto i dwadzieścia i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Mężów z Betela i z Haj sto dwadzieścia i trzy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'Mężów z Nebo drugiego pięćdziesiąt i dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Synów Elama drugiego tysiąc dwieście pięćdziesiąt i cztery;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Synów Harymowych trzy sta i dwadzieścia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Synów Jerechowych trzy sta czterdzieści i pięć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Synów Lodowych, Hadydowych, i Onowych siedm set i dwadzieścia i jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Synów Senaa trzy tysiące dziewięć set i trzydzieści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Kapłanów: Synów Jedajaszowych, z domu Jesui, dziewięć set siedmdziesiąt i trzy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Synów Immerowych tysiąc pięćdziesiąt i dwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Synów Passurowych tysiąc dwieście czterdzieści i siedm;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Synów Harymowych tysiąc i siedmnaście;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Lewitów: Synów Jesuego, i Kadmielowych, synów Hodowijaszowych siedmdziesiąt i cztery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Śpiewaków: Synów Asafowych sto czterdzieści i ośm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Odźwiernych: Synów Sallumowych, synów Aterowych, synów Talmonowych, synów Akkubowych, synów Hatytowych, synów Sobajowych sto trzydzieści i ośm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Z Netynejczyków: Synów Sycha, synów Chasufa, synów Tabbaota,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'Synów Kierosa, synów Syjaa, synów Fadona,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'Synów Lebana, synów Hagaba, synów Salmaja,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'Synów Hanana, synów Giddela, synów Gachara,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'Synów Raajasza, synów Rezyna, synów Nekoda,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'Synów Gazama, synów Uzy, synów Faseacha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'Synów Besaja, synów Mechynima, synów Nefusesyma,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'Synów Bakbuka, synów Chakufa, synów Charchura,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'Synów Basluta, synów Mechyda, synów Charsa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'Synów Barkosa, synów Sysera, synów Tamacha,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'Synów Nezyjacha, synów Chatyfa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Synów sług Salomonowych, synów Sotaja, synów Soferata, synów Peruda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'Synów Jahala, synów Darkona, synów Giddela,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'Synów Sefatyjasza, synów Chatyla, synów Pochereta z Hasebaim, synów Amona:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Wszystkich Netynejczyków i synów sług Salomonowych trzy sta dziewięćdziesiąt i dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'A cić są, którzy wyszli z Telmelachu i z Telcharsa: Cherub, Addan, i Immer: ale nie mogli okazać domu ojców swoich i nasienia swego, jeźli z Izraela byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'Synów Delajaszowych, synów Tobijaszowych, synów Nekodowych sześć set czterdzieści i dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'A z kapłanów synowie Hobajowi, synowie Kozowi, synowie Barsylajego; który był pojął z córek Barsylaja Galaadczyka żonę, i nazwany był od imienia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ci szukali opisania swego, wywodząc ród swój, ale nie znaleźli; przetoż zrzuceni są z kapłaństwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'I zakazał im Tyrsata, aby nie jedli z rzeczy najświętszych, ażby powstał kapłan z Urym i z Tummim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Wszystkiego zgromadzenia w jednym poczcie było czterdzieści tysięcy dwa tysiące trzy sta i sześćdziesiąt;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'Oprócz sług ich i służebnic ich, których było siedm tysięcy trzy sta trzydzieści i siedm; a między nimi było śpiewaków i śpiewaczek dwieście i czterdzieści i pięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Koni ich siedm set trzydzieści i sześć; mułów ich dwieście czterdzieści i pięć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'Wielbłądów cztery sta trzydzieści i pięć; osłów sześć tysięcy siedm set i dwadzieścia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'A niektórzy przedniejsi z domów ojcowskich dawali na robotę. Tyrsata dał do skarbu złota tysiąc łótów, czasz pięćdziesiąt, szat kapłańskich pięć set i trzydzieści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'Niektórzy też z przedniejszych domów ojcowskich dali do skarbu na robotę złota dwadzieścia tysięcy łótów, a srebra grzywien dwa tysiące i dwieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'A co dał inszy lud, było złota dwadzieścia tysięcy łótów, a srebra dwa tysiące grzywien, a szat kapłańskich sześćdziesiąt i siedm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'A tak osiedli kapłani i Lewitowie, i odźwierni, i śpiewacy, i lud pospolity, i Netynejczycy, i wszystek Izrael miasta swoje. A gdy nastał miesiąc siódmy, byli synowie Izraelscy w miastach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Zebrał się tedy wszystek lud jednostajnie na ulicę, która jest przed bramą wodną, i rzekli do Ezdrasza, nauczonego w Piśmie, aby przyniósł księgi zakonu Mojżeszowego, który był przykazał Pan Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'Tedy przyniósł Ezdrasz kapłan zakon przed ono zgromadzenie mężów i niewiast, i wszystkich, którzyby rozumnie słuchać mogli; a działo się to dnia pierwszego, miesiąca siódmego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'I czytał w nim na onej ulicy, która jest przed bramą wodną, od poranku aż do południa przed mężami i niewiastami, i którzy zrozumieć mogli, a uszy wszystkiego ludu obrócone były do ksiąg zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'I stanął Ezdrasz nauczony w Piśmie na kazalnicy, którą byli zgotowali na to, a podle niego stał Matytyjasz, i Sema, i Ananijasz, i Uryjasz, i Helkijasz, i Maasyjasz, po prawej ręce jego, a po lewej ręce jego Fedajasz, i Misael, i Malchyjasz, i Chasum, i Chasbadana, Zacharyjasz i Mesullam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'Otworzył tedy Ezdrasz księgi przed oczyma wszystkiego ludu, bo stał wyżej niż wszystek lud; a gdy je otworzył, wszystek lud powstał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'I błogosławił Ezdrasz Panu, Bogu wielkiemu, a wszystek lud odpowiadał: Amen! Amen! podnosząc ręce swoje; a nachyliwszy głowy, kłaniali się Panu twrzą ku ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Także i Jesua, i Bani, i Serebijasz, Jamin, Chakub, Sabbetaj, Hodyjasz, Maasyjasz, Kielita, Azaryjasz, Jozabad, Chanan, Felajasz, i Lewitowie nauczali ludu zakonu, a lud stał na miejscu swem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'Bo czytali w księgach zakonu Bożego wyraźnie, a wykładając zmysł objaśniali to, co czytali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'Zatem Nehemijasz (ten jest Tyrsata) i Ezdrasz kapłan, nauczony w Piśmie, i Lewitowie, którzy uczyli lud, rzekli do wszystkiego ludu: Ten dzień poświęcony jest Panu, Bogu waszemu, nie smućcież się, ani płaczcie. (Bo płakał wszystek lud, słysząc słowa zakonu.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'I rzekł im: Idźcież, jedzcie rzeczy tłuste a pijcie napój słodki, a posyłajcie cząstki tym, którzy sobie nic nie nagotowali; albowiem święty jest dzień Panu naszemu. Przetoż się nie frasujcie; albowiem wesele Pańskie jest siłą waszą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'A gdy Lewitowie uczynili milczenie między wszystkim ludem, mówiąc: Milczcież, bo dzień święty jest, a nie smućcie się:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'Tedy odszedł wszystek lud, aby jedli i pili, i aby innym cząstki posyłali. I weselili się bardzo, przeto, że zrozumieli słowa, których i nauczano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'Potem zebrali się dnia drugiego przedniejsi domów ojcowskich ze wszystkiego ludu, kapłani i Lewitowie, do Ezdrasza nauczonego w Piśmie, aby wyrozumieli słowa zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'I znaleźli napisane w zakonie, że rozkazał Pan przez Mojżesza, aby mieszkali synowie Izraelscy w kuczkach w święto uroczyste miesiąca siódmego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'A iżby to opowiedziano i obwołano we wszystkich miastach ich, i w Jeruzalemie, mówiąc: Wynijdźcie na górę, a nanoście gałęzia oliwnego, i gałęzia sosnowego, i gałęzia myrtowego, i gałęzia palmowego, i gałęzia drzewa gęstego, abyście poczynili kuczki, jako jest napisane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Przetoż wyszedł lud, a nanosili i poczynili sobie kuczki, każdy na dachu swym, i w sieniach swych, i w sieniach domu Bożego, i na ulicy bramy wodnej, i na ulicy bramy Efraimowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'A tak naczyniło kuczek wszystko zgromadzenie, które się wróciło z niewoli, i mieszkali w kuczkach, (choć tego nie czynili synowie Izraelscy ode dni Jozuego, syna Nunowego, aż do dnia onego;) i było wesele bardzo wielkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'A Ezdrasz czytał w księgach zakonu Bożego na każdy dzień; od pierwszego dnia aż do dnia ostatniego; i obchodzili święto uroczyste przez siedm dni, a dnia ósmego było zgromadzenie według zwyczaju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'Potem dnia dwudziestego i czwartego tegoż miesiąca zgromadzili się synowie Izraelscy, i pościli w worzech, i posypali się prochem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'A odłączyło się nasienie Izraelskie od wszystkich cudzoziemców, a stanąwszy wyznawali grzechy swe i nieprawości ojców swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'I powstali na miejscach swych, a czytali księgi zakonu Pana, Boga swego, cztery kroć przez dzień, i cztery kroć wyznawali a kłaniali się Panu Bogu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Zatem stanęli na stopniach Lewitów Jesua i Bani, Kadmiel, Sebanijasz, Bunni, Serebijasz, Bani, Chenani, a wołali głosem wielkim do Pana Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'I mówili Lewitowie Jesua, i Kadmiel, Bani, Hasabnejasz, Serebijasz, Odyjasz, Sebanijasz, Petachyjasz: Wstańcie, błogosławcie Panu, Bogu waszemu, od wieku aż na wieki, a niech błogosławią imieniowi twojemu chwalebnemu i wywyższonemu nad wszelkie błogosławieństwo i chwałę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Ty, Panie! sam, ty sam, tyś uczynił niebo, nieba niebios, i wszystko wojsko ich, ziemię, i wszystko co jest na niej, morza, i wszystko, co w nich jest, a ty ożywiasz to wszystko; a wojska niebieskie tobie się kłaniają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Tyś jest, Panie Boże! któryś wybrał Abrama, a wywiodłeś go z Ur Chaldejskiego, i dałeś mu imię Abraham.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'I znalazłeś serce jego wierne przed obliczem twojem, i uczyniłeś z nim przymierze, że dasz ziemię Chananejczyka, Hetejczyka, Amorejczyka, i Ferezejczyka, i Jebuzejczyka, i Giergiezejczyka, że ją dasz nasieniu jego, i ziściłeś słowa twoje; boś ty sprawiedliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Wejżałeś zaiste na utrapienie ojców naszych w Egipcie, a wołanie ich wysłuchałeś nad morzem Czerwonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'A pokazywałeś znaki i cuda na Faraonie, i na wszystkich sługach jego, i na wszystkim ludu ziemi jego; boś poznał, że sobie hardzie postępowali przeciwko nim, i uczyniłeś sobie imię, jako się to dziś pokazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'I rozdzieliłeś morze przed nimi, a przeszli przez pośrodek morza po suszy; a tych, którzy ich gonili, wrzuciłeś w głębokości, jako kamień w wody gwałtowne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'A w słupie obłokowym prowadziłeś ich we dnie, a w słupie ognistym w nocy, abyś im oświecał drogę, którą iść mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'Potemeś na górę Synaj zstąpił, i mówiłeś do nich z nieba, a dałeś im sądy prawe, i zakony prawdziwe, ustawy i rozkazania dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'I sabat twój święty oznajmiłeś im, a przykazania i ustawy, i zakon wydałeś im przez Mojżesza, sługę twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'Dałeś im też chleb w głodzie ich z nieba, i wodęś im z skały wywiódł w pragnieniu ich, a rozkazałeś im, aby szli, i posiedli ziemię, o którąś podniósł rękę swą, że im ją dasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Ale oni i ojcowie nasi hardzie sobie poczynali, i zatwardzili kark swój, i nie słuchali rozkazania twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'Owszem nie chcieli słuchać, ani wspomnieli na cuda twoje, któreś czynił, przy nich; ale zatwardziwszy kark swój postanowili sobie wodza, chcąc się wrócić w niewolę swoję w uporze swoim. Lecz ty, o Boże miłościwy, łaskawy, i miłosierny, nieskwapli wy, i wielkiego miłosierdzia! nie opuściłeś ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Nawet gdy sobie uczynili cielca ulanego, a mówili: Ten jest Bóg twój, który cię wywiódł z ziemi Egipskiej, i dopuścili się bluźnierstw wielkich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'Ty jednak dla litości twoich wielkich nie opuściłeś ich na puszczy; słup obłokowy nie odstąpił od nich we dnie, prowadząc ich w drodze, ani słup ognisty w nocy, oświecając ich, i drogę, którą iść mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Nadto ducha twojego dobrego dałeś im, aby ich uczył, i manny twojej nie odjąłeś od ust ich, i wodę dałeś im w pragnieniu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'A tak przez czterdzieści lat żywiłeś ich na puszczy; na niczem im nie schodziło, szaty ich nie zwiotszały, i nogi ich nie napuchły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'I podałeś im królestwa i narody, któreś rozegnał po kątach, tak, że posiedli ziemię Sehonową, i ziemię króla Hesebońskiego, i ziemię Oga, króla Basańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'A synów ich rozmnożyłeś jako gwiazdy niebieskie, i wwiodłeś ich do ziemi, o którejś mawiał ojcom ich, że wnijdą i posiędą ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'Bo przyszedłszy synowie ich posiedli tę ziemię, gdyś poniżył przed nimi obywateli onej ziemi, Chananejczyków, i podałeś ich w ręce ich, i królów ich, i narody onej ziemi, aby się z nimi obchodzili według woli swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'Pobrali tedy miasta obronne, i ziemię tłustą, i posiedli domy pełne wszelkich dóbr, studnie wykopane, winnice, oliwnice, i drzew rodzajnych bardzo wiele; a jedli, i byli nasyceni, i otyli, i opływali w rozkoszy z dobroci twojej wielkiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Ale gdy cię rozdraźnili, i stalić się odpornymi, zarzuciwszy zakon twój w tył swój, a proroków twoich pobili, którzy się oświadczali przed nimi, aby ich nawrócili do ciebie, i dopuszczali się bluźnierstwa wielkiego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Podałeś ich w ręce nieprzyjaciołom ich, którzy ich trapili. A gdy czasu utrapienia swego wołali do ciebie, tyś ich z nieba wysłuchał, a według litości twoich wielkich dawałeś im wybawicieli, którzy ich wybawiali z rąk nieprzyjaciół ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'Wtem, gdy trochę odpoczęli, znowu czynili złość przed twarzą twoją; przetoż opuściłeś ich w ręce nieprzyjaciół ich, aby panowali nad nimi. Lecz gdy się znowu nawrócili, a wołali do ciebie, tyś ich z nieba wysłuchał, i wybawiłeś ich według litości twoich przez wiele czasów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'I oświadczałeś się przed nimi, abyś ich nawrócił do zakonu swego; ale oni sobie hardzie poczynali, a niesłuchali przykazań twoich, owszem przeciw sądom twoim grzeszyli, które gdyby człowiek czynił, żyłby przez nie; ale uchylając ramion swych, kark swój zatwardzili, i nie słuchali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'Wszakżeś ty im folgował przez wiele lat, oświadczając się przed nimi Duchem twym przez proroków twoich; a gdy nie słuchali, podałeś ich w ręce narodów onych ziem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Ale dla litości twoich wielkich nie dałeś ich na wytracenie, aniś ich opuścił; boś ty Bóg łaskawy i miłosierny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'Teraz tedy o Boże nasz, Boże wielki, możny, i straszny! który strzeżesz przymierza i miłosierdzia, niech nie będzie małe przed tobą każde utrapienie, które przyszło na nas, na królów naszych, na kaiążąt naszych, i na kapłanów naszych, i na proroków naszych, i na ojców naszych, i na wszystek lud twój, ode dni królów Assyryjskich aż do dnia tego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Acześ ty jest sprawiedliwy we wszystkiem tem, co przyszło na nas; boś sprawiedliwie uczynił, a myśmy niezbożnie czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'I królowie nasi, książęta nasi, kapłani nasi, i ojcowie nasi nie pełnili zakonu twego, i nie przestrzegali przykazań twoich, i świadectw twych, któremiś się oświadczał przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Bo oni w królestwie swem i w dobroci twojej wielkiej, którąś im pokazał, i w ziemi przestronnej i tłustej, którąś im był dał, nie służyli tobie, ani się odwrócili od spraw złych swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Oto myśmy dziś niewolnikami, i ziemia, którąś dał ojcom naszym, aby jedli owoc jej, i dobra jej, otośmy niewolnikami w niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'Już urodzaje swoje obfite wydaje królom, któreś postanowił nad nami dla grzechów naszych; panują nad ciały naszemi, i nad bydłem naszem według woli swej, tak, żeśmy w wielkiem uciśnieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'Wszakże w tem wszystkiem czynimy mocne przymierze, i zapisujemy je, które pieczętują książęta nasi, Lewitowie nasi, i kapłani nasi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'A którzy pieczętowali, ci byli: Nehemijasz, Tyrsata, syn Hachalijaszowy, i Sedekijasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Sarajasz, Azaryjasz, Jeremijasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Passur, Amaryjasz, Malchyjasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hattus, Sebanijasz, Malluch,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harym, Meremot, Obadyjasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Danijel, Ginneton, Baruch,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesullam, Abijasz, Mijamin,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maazyjasz, Bilgaj, Semajasz. Ci byli kapłani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'A Lewitowie byli: Jesua, syn Azanijaszowy, Binnui z synów Chenadadowych, Kadmiel;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'Bracia też ich: Sebanijasz, Odyjasz, Kielita, Felejasz, Chanan,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Micha, Rechob, Hasabijasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zachur, Serebijasz, Sebanijasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Odyjasz, Bani, Beninu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Przedniejsi z ludu: Faros, Pachatmoab, Elam, Zattu, Bani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Bunni, Azgad, Bebaj,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonijasz, Bygwaj, Adyn,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Ezechyjasz, Azur,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Chodyjasz, Hasum, Besaj,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Haryf, Anatot, Nebaj,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpijasz, Mesullam, Chesyr,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesezabel, Sadok, Jaddua,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatyjasz, Chanan, Anajasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Ozeasz, Hananijasz, Hasub,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Halloches, Pilcha, Sobek,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehum, Hasabna, Maasejasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'I Achyjasz, Chanan, Anan,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Malluch, Harym, Baana,.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'Także i inni z ludu: Kapłani, Lewitowie, odźwierni, śpiewacy, Netynejczycy, i wszyscy, którzy się odłączyli od narodów onych ziem do zakonu Bożego, żony ich, synowie ich, i córki ich; wszelki umiejętny i rozumny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'Chwyciwszy się tego z braćmi swymi, i z przedniejszymi ich przychodzili, obowiązując się przeklęstwem i przysięgą, że chcą chodzić w zakonie Bożym, który jest podany przez Mojżesza, sługę Bożego, i chcą strzedz a czynić wszystkie przykazania Pana, Boga naszego, i sądy jego, i ustawy jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'A że nie damy córek naszych narodom onej ziemi, i córek ich brać nie będziemy synom naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'Ani od narodów onej ziemi, którzyby nam przynosili jakie towary, albo jakie zboże w dzień sabatu na sprzedaj, brać od nich będziemy w sabat, ani w dzień święty; a że zaniechamy roku siódmego siania roli i wyciągania wszelakiego długu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'Postanowiliśmy też między sobą prawo, abyśmy dawali po trzeciej części sykla na każdy rok na potrzebę domu Boga naszego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'Na chleby pokładne, i na ofiarę ustawiczną, i na całopalenia ustawiczne w sabaty, w pierwsze dni miesiąca, w święta uroczyste, i na rzeczy święte, i na ofiary za grzech ku oczyszczeniu Izraela, i na wszelką potrzebę domu Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'Rzuciliśmy też losy około noszenia drew między kapłanów, Lewitów, i między lud, aby ich dodawali do domu Boga naszego według domów ojców naszych, na czasy naznaczone, od roku do roku, aby gorzało na ołtarzu Pana, Boga naszego, jako jest napisane w zakonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'Także aby przynosili pierworodztwa ziemi naszej, i pierworodztwa wszelkiego owocu każdego drzewa, od roku do roku, do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'Do tego pierworodztwa synów naszych, i bydeł naszych, jako napisano w zakonie, i pierworodztwa wołów naszych, i owiec naszych, żeby przynosili do domu Boga naszego kapłanom służącym w domu Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'Nadto pierwociny ciast naszych, i podnoszonych ofiar naszych, i owoce wszelkiego drzewa, moszczu, i oliwy świeżej, aby przynosili kapłanom do gmachów domu Boga naszego, i dziesięcinę ziemi naszej Lewitom; a cić Lewitowie wybierać będą tę dziesięcinę we wszystkich miastach robót naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'A będzie kapłan, syn Aarona, przy Lewitach, gdy Lewitowie tę dziesięcinę odbierać będą; a Lewitowie wniosą dziesięcinę z dziesięciny do domu Boga naszego, do komór w domu skarbnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Bo do tych komór odnosić będą synowie Izraelscy, i synowie Lewiego, ofiarę zboża, moszczu, i oliwy świeżej, gdzie są naczynia świątnicy, i kapłani służący, i odźwierni, i śpiewacy, abyśmy nie opuszczali domu Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'Mieszkali tedy przedniejsi z ludu w Jeruzalemie, a inny lud miotali losy, aby wzięli dziesiątego człowieka na mieszkanie w Jeruzalemie, mieście świętem, a dziewięć części w innych miastach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'I błogosławił lud wszystkim mężom, którzy się dobrowolnie ofiarowali, aby mieszkali w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'A cić są przedniejsi onej krainy, którzy mieszkali w Jeruzalemie. (A w inszych miastach Judzkich mieszkał każdy w osiadłości swojej, i w miastach swych, Izraelczycy, kapłani, i Lewitowie, i Netynejczycy, i synowie sług Salomonowych.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'A tak w Jeruzalemie mieszkali niektórzy z synów Judowych i z synów Benjaminowych. Z synów Judowych: Atajasz, syn Uzyjasza, syna Zacharyjaszowego, syna Amaryjaszowego, syna Sefatyjaszowego, syna Mahaleelowego z synów Faresowych:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'Także Maasejasz, syn Barucha, syna Cholhozowego, syna Hasajaszowego, syna Hadajaszowego, syna Jojarybowego, syna Zacharyjaszowego, syna Sylończykowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Wszystkich synów Faresowych, mieszkających w Jeruzalemie, cztery sta sześćdziesiąt i ośm mężów dużych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'A synowie Benjaminowi ci są: Sallu, syn Mesullama, syna Joedowego, syna Fadajaszowego, syna Kolajaszowego, syna Maasajaszowego, syna Ityjelowego, syna Izajaszowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'A po nim Gabaj, Sallaj, wszystkich dziewięć set dwadzieścia i ośm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'I Joel, syn Zychry, był przełożonym nad nimi, a Juda, syn Senua, nad miastem wtóry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Z kapłanów mieszkali Jedajasz, syn Jojaryba, i Jachyn;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Serajasz, syn Helkijasza, syna Mesullamowego, syna Sadokowego, syna Merajotowego, syna Achytobowego, przełożony w domu Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'A braci ich, którzy odprawiali roboty domowe, ośm set dwadzieścia i dwa; i Adajasz, syn Jerohama, syna Pelalijaszowego, syna Amsego, syna Zacharyjaszowego, syna Passurowego, syna Malchyjaszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'A braci jego przedniejszych z domów ojcowskich dwieście czterdzieści i dwa; i Amasesaj, syn Asareli, syna Achzajowego, syna Mesullemitowego, syna Immerowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'A braci ich, mężów dużych, sta dwadzieścia i ośm, i przełożony nad nimi Zabdyjel, syn Giedolima.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'A z Lewitów Semejasz, syn Hassuby, syna Asrykamowego, syna Hasabijaszowego, syna Bunni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'A Sabbataj i Jozabad byli nad robotą, która była z dworu przy domu Bożym, a cić byli z przedniejszych Lewitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'A Matanijasz, syn Michasa, syna Zabadyjaszowego,syna Asafowego, był przedniejszy w zaczynaniu chwały przy modlitwie; a Bakbukijasz wtóry z braci jego, i Abda, syn Sammuj, syna Galilowego, syna Jedytunowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Wszystkich Lewitów było w mieście świętem dwieście ośmdziesiąt i czterech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'A z odźwiernych: Akkub, Talmon, i braci ich, i stróżów w bramach, sto siedemdziesiąt i dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'A drudzy z Izraela, z kapłanów, z Lewitów, mieszkali we wszystkich miastach Judzkich, każdy w dziedzictwie swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'Ale Netynejczycy mieszkali w Ofelu; a Sycha i Gipsa byli nad Netynejczykami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'A przełożony nad Lewitami w Jeruzalemie był Uzy, syn Bani, syna Chasabajaszowego, syna Matanijaszowego, syna Michasowego. Ci byli z synów Asafowych śpiewacy przy służbie domu Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Albowiem rozkazanie królewskie było o nich, i pewne opatrzenie dla śpiewaków na każdy dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'A Petachyjasz, syn Mesezabelowy, z synów Zachara, syna Judowego, był na miejscu królewskiem w każdej sprawie do ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'A we wsiach i polach ich z synów Judowych mieszkali w Karyjat Arbie i we wsiach jego, i w Dybon i we wsiach jego, i w Jekabseel i we wsiach jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'I w Jesue, i w Molada, i w Betfelet;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'I w Hasersual, i w Beersabe i we wsiach jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'I w Sycelegu, i w Mechona i we wsiach jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'I w Enrymmon, i w Saraa, i w Jerymut;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'W Zanoe, w Adullam i we wsiach ich; w Lachys i na polach jego; w Aseku i we wsiach jego. A tak mieszkali od Beerseby aż do Giehennom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'A synowie Benjaminowi z Gabaa mieszkali w Machmas, i w Haju, i w Betel i we wsiach jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'W Anatot, w Nobie, w Ananija;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'W Chasor, w Rama, w Gietaim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'W Hadyd, w Seboim, w Neballat;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'W Lod, i w Ono, i w dolinie rzemieślników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'A z Lewitów mieszkali niektórzy w działach Judzkich i w Benjamickich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'A cić są kapłani i Lewitowie, którzy przyszli z Zorobabelem, synem Sealtyjelowym, i z Jesuą: Serejasz, Jeremijasz, Ezdrasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amaryjasz, Malluch, Hattus,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sechanijasz, Rehum, Meremot,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Iddo, Ginnetoj, Abijasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Maadyjasz, Bilgal,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semejasz, i Jojaryb, Jedajasz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Sallu, Amok, Helkijasz, Jedajasz. Cić byli przedniejsi z kapłanów i z braci swych, za dni Jesuego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'A Lewitowie: Jesua, Binnui, Kadmiel, Serebijasz, Juda; Matanijasz nad pieśniami, sam i bracia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'A Bakbukijasz i Hunni, bracia ich, byli przeciwko nim w porządku swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'A Jesua spłodził Joakima, a Joakim spłodził Elijasyba, a Elijasyb spłodził Jojadę:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'A Jojada spłodził Jonatana, a Jonatan spłodził Jadduę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'A za dni Joakima byli kapłani przedniejsi z domów ojcowskich: z Serajaszowego Merajasz, z Jeremijaszowego Chananijasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Z Ezdraszowego Mesullam, z Amaryjaszowego Jochanan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Z Melchowego Jonatan, z Sechanijaszowego Józef;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Z Harymowego Adna, z Merajotowego Helkaj;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Z Iddowego Zacharyjasz, z Ginnetowego Mesullam;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Z Abijaszowego Zychry, z Miniaminowego i z Maadyjaszowego Piltaj;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Z Bilgowego Sammua, z Semejaszowego Jonatan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'A z Jojarybowego Mattenaj, z Jedajaszowego Uzy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Z Sallajowego Kalaj, z Amokowego Heber;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Z Helkijaszowego Hasabijasz, z Jedajaszowego Natanael.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'A Lewitowie za dni Elijasyba, Jojady, i Jochanana, i Jadduego popisani są, którzy byli przedniejszymi z domów ojcowskich; także i kapłani aż do królestwa Daryjusza, króla Perskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Synowie mówię Lewiego, przedniejsi z domów ojcowskich, zapisani są w księgach kroniki aż do dni Jochanana, syna Elijasybowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'Przedniejsi mówię z Lewitów byli Hasabijasz, Serebijasz, i Jesua, syn Kadmielowy, i bracia ich przeciwko nim, ku chwaleniu i wysławianiu Boga według rozkazania Dawida, męża Bożego, straż przeciwko straży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Matanijasz, i Bakbukijasz, Obadyjasz, Mesullam, Talmon, Akkub, byli stróżami odźwiernymi przy domu skarbu u bram.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Cić byli za dni Joakima, syna Jesuego, syna Jozedekowego, i za dni Nehemijasza wodza, i Ezdrasza kapłana, nauczonego w Piśmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'A przy poświęcaniu muru Jeruzalemskiego szukano Lewitów ze wszystkich miejsc ich, aby ich przywiedziono do Jeruzalemu, żeby wykonali poświęcania i wesela, a to z wysławianiem i z śpiewaniem, z cymbałami, z lutniami, i z cytrami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'Przetoż zgromadzeni są synowie śpiewaków, i z równin około Jeruzalemu, i ze wsi Netofatyckich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'Także z domu Gilgal, i z pól Gieba, i z Azmawet; bo sobie śpiewacy budowali wsi około Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'A oczyściwszy się kapłani i Lewitowie, oczyścili też lud, i bramy, i mur.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'Zatemem rozkazał wstąpić książętom Judzkim na mur, i postawiłem dwa hufy wielkie chwalących, z których jedni szli na prawo od wyższej strony muru ku bramie gnojowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'A za nimi szedł Hozajasz, i połowa książąt Judzkich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'Także Azaryjasz, Ezdrasz, i Mesullam,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, i Benjamin, i Semejasz, i Jeremijasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'Potem niektórzy z synów kapłańskich z trąbami, mianowicie Zacharyjasz, syn Jonatana, syna Semejaszowego, syna Matanijaszowego, syna Michajaszowego, syna Zachurowego, syna Asafowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'A bracia jego Semejasz, i Asarel, Milalaj, Gilalaj, Maaj, Netaneel, i Juda, Chanani, z instrumentami muzycznemi Dawida, męża Bożego, a Ezdrasz, nauczony w Piśmie, przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'Potem ku bramie źródła, która przeciwko nim była, wstępowali po schodach miasta Dawidowego, którędy chodzą na mur, a od muru przy domu Dawidowym aż do bramy wodnej na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'A drugi huf chwalących szedł przeciwko nim, a ja za nim, a połowa ludu po murze od wieży Tannurym aż do muru szerokiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'A od bramy Efraim ku bramie starej, i ku bramie rybnej, i wieży Chananeel, i wieży Mea, aż do bramy owczej. I stanął u bramy straży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Potem stanęły one dwa hufy chwalących w domu Bożym, i ja i połowa przełożonych ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'Także kapłani: Elijakim, Maasejasz, Minijamin, Michajasz, Elijenaj, Zacharyjasz, Chananijasz, z trąbami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'I Maazyjasz, i Semejasz, i Eleazar, i Uzy, i Jochanan, i Malchyjasz, i Elam, i Ezer; a śpiewacy głośno śpiewali, i Izrachyjasz, przełożony ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'Sprawowali także onegoż dnia ofiary wielkie, i weselili się; albowiem Bóg rozweselił ich był weselem wielkiem, tak, iż się i niewiasty i dziatki weseliły; i było słyszeć wesele Jeruzalemskie daleko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'Obrani też są dnia onego mężowie nad komorami skarbów, i ofiar, pierwocin, i dziesięcin, aby zgromadzali do nich z pól miejskich działy, zakonem warowane kapłanom i Lewitom; bo się weselił Juda z kapłanów i z Lewitów tam stojących;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'Którzy strzegli straży Boga swego, i straży oczyszczania, i śpiewaków, i odźwiernych, według rozkazania Dawida i Salomona, syna jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Bo za dni Dawida i Asafa byli postanowieni z starodawna przełożeni nad śpiewakami dla śpiewania, wychwalania i dziękczynienia Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'Przetoż wszystek Izrael za dni Zorobabela, i za dni Nehemijasza, dawali działy dla śpiewaków i odźwiernych, każdodzienny wymiar, a oddawali to, co poświęcili, Lewitom; Lewitowie zaś oddawali synom Aaronowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Onegoż dnia czytano w księgach Mojżeszowych, tak, iż lud słyszał. I znaleziono w nich napisane, że nie miał wchodzić Ammonitczyk i Moabczyk do zgromadzenia Bożego, aż na wieki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'Przeto, iż nie zaszli synom Izraelskim z chlebem i z wodą; owszem najęli przeciwko nim Balaama, aby ich przeklinał; ale obrócił Bóg nasz ono przeklęstwo w błogosławieństwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'A gdy usłyszeli zakon, odłączyli wszystek lud pospolity od Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Ale się przedtem Elijasyb kapłan, przełożony nad skarbnicą domu Boga naszego, spowinowacił z Tobijaszem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'I zbudował mu gmach wielki, kędy przedtem odkładano dary, kadzidło, i naczynia, i dziesięciny zboża, moszczu, i oliwy świeżej, opatrzenie Lewitom, i śpiewakom, i odźwiernym, także ofiary podnoszone kapłańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Ale przy tem wszystkiem nie byłem w Jeruzalemie; albowiem roku trzydziestego i wtórego Artakserksesa, króla Babilońskiego, przyszedłem do króla, a po wyjściu kilku lat uprosiłem się u króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'A gdym przyszedł do Jeruzalemu, wyrozumiałem to złe, które uczynił Elijasyb kwoli Tobijaszowi, iż mu zbudował gmach w sieniach domu Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'Co mi się bardzo nie podobało: przetoż wyrzuciłem wszystkie naczynia domu Tobijaszowego precz z onegoż gmachu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'I rozkazałem oczyścić one gmachy, i wniosłem tam zaś nacznia domu Bożego, dary i kadzidło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'Nadtom się dowiedział, że działy Lewitom nie były oddawane, a iż się Lewitowie i śpiewacy, którzy pilnowali pracy, rozbiegli, każdy do roli swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Przetoż zgromiłem przełożonych, mówiąc: Przeczże opuszczamy dom Boży? A tak zebrawszy ich, postawiłem ich na miejscach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'A wszystek Juda przynosili dziesięciny zboża, i moszczu, i świeżej oliwy do skarbu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'I postanowiłem podskarbich nad skarbmi: Selemijasza kapłana, i Sadoka nauczonego w Piśmie, i Fadajasza z Lewitów, a przy nich Hanana, syna Zachurowego, syna Matanijaszowego, bo ich za wiernych miano; a ich powinność była, działy rozdawać braciom swym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Wspomnij na mię o Boże mój! dla tego, a nie wymazuj dobroczynności moich, którem czynił przy domu Boga mego, i przy obrzędach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'W oneż dni widziałem w Judzie tłoczących prasy w sabat, i noszących snopy, które kładli na osły, także i winne grona, i figi, i wszelki ciężar, a przynoszących do Jeruzalemu w dzień sabatu, i zgromiłem ich onegoż dnia, którego sprzedawali żywność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Także Tyryjczycy, którzy mieszkali w niem, przynosili ryby, i rozmaite towary, a sprzedawali w sabat synom Judy, i w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Przetożem zgromił przełożonych w Judzie, mówiąc do nich: Cóż to jest za nieprawość, której się dopuszczacie, gwałcąc dzień sabatu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Izali nie toż czynili ojcowie wasi, przez co Bóg nasz przywiódł na nas to wszystko złe, i na to miasto? A wy przyczyniacie gniewu na Izraela, gwałcąc sabat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'A gdy okrył cień bramy Jeruzalemskie przed sabatem, rozkazałem zamknąć wrota, i nie kazałem ich otwierać, aż po sabacie; a niektórych z sług moich postawiłem w bramach, żeby nie wnoszono żadnych brzemion w dzień sabatu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Przetoż zostali przez noc kupcy, i sprzedawający towary rozmaite przed miastem Jeruzalemskiem, raz i drugi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'Przeciwko którym oświadczyłem się, i rzekłem do nich: Przecz wy zostawacie przez noc za murem? Uczynicieli to więcej, ściągnę rękę na was. A tak od onego czasu nie przychodzili w sabat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'I rozkazałem Lewitom, aby się oczyścili, a przyszedłszy strzegli bram, i święcili dzień sabatu. I dlatego wspomnij na mię, o Boże mój! a bądź mi miłościw według obfitości miłosierdzia twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'W tychże dniach ujrzałem też Żydów, którzy sobie pojęli żony Azotyckie, Ammonickie, Moabskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'A synowie ich na poły mówili po azotycku, nie umiejąc mówić po żydowsku, ale według języka swego narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'Przetożem ich zgromił, i przeklinałem ich, i biłem niektórych z nich, a rwałem ich za włosy, i poprzysiągłem ich przez Boga, aby nie dawali córek swoich synom ich, ani brali córek ich synom swym i sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Izaliż nie przez to zgrzeszył Salomon, król Izraelski? choć między wieloma narodami nie było króla jemu podobnego, który był miły Bogu swemu, tak, że go Bóg postanowił królem, nad wszystkim Izraelem, przecież i tego przywiodły niewiasty cudzoziemskie do grzechu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'A wam izali pozwolimy, żebyście się dopuszczali tej wielkiej złości, a występowali przeciwko Bogu naszemu pojmując żony cudzoziemskie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'Lecz jeden z synów Jojady, syna Elijasyba, kapłana najwyższego, był zięciem Sanballata Horończyka, i wygnałem go od siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Wspomnijże na to, o Boże mój! przeciw tym, którzy plugawią kapłaństwo, i umowę kapłańską i Lewitską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Przetożem ich oczyścił od wszelkiego cudzoziemca, i postanowiłem porządki kapłanom i Lewitom, każdemu w pracy jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'I ku noszeniu drew do ofiar, czasów postanowionych, także i pierwocin. Wspomnijże na mię, Boże mój! ku dobremu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'I stało się za dni Aswerusa, (który Aswerus królował od Indyi aż do Murzyńskiej ziemi, nad stem i dwudziestą i siedmią krain.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'Że za onych dni, gdy siedział król Aswerus na stolicy królestwa swego, która była w Susan, mieście stołecznem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'Roku trzeciego królowania swego sprawił u siebie ucztę na wszystkich książąt swoich, i sług swoich, na hetmanów z Persów i z Medów, na przełożonych i na starostów onych krain,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'Pokazując bogactwa, i chwałę królestwa swego, i zacność a ozdobę wielmożności swojej przez wiele dni, mianowicie przez sto i ośmdziesiąt dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, '(A gdy się dokończyły dni one, uczynił król na wszystek lud, co go kolwiek było w Susan, w mieście stołecznem, od największego aż do najmniejszego, ucztę przez siedm dni na sali w ogrodzie przy pałacu królewskim.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Opony białe, zielone i hijacyntowe zawieszono na sznurach bisiorowych i szarłatnych, na kolcach srebrnych i na słupach marmurowych; łoża złote i srebrne na tle kryształowem, i marmurowem, i paryjowem, i socharowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'A napój dawano w naczyniu złotem, a to w naczyniu co raz innem, i wina królewskiego dostatkiem, jako przystało na króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'Ale do picia, według ustawy, nikt nie przymuszał. Albowiem tak był rozkazał król wszystkim rządcom domu swego, aby czynili według woli każdego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Wasty też królowa sprawiła ucztę na białegłowy w domu królewskim króla Aswerusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'A dnia siódmego, gdy sobie król podweselił winem, rzekł do Mechumana, Bysyta, Herbona, Bygta, i Abagta, Zetara, i Charchasa, do siedmiu komorników, którzy służyli przed obliczem króla Aswerusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'Aby przywiedli Wasty królowę przed oblicze królewskie w koronie królewskiej, chcąc pokazać narodom i książętom piękność jej; bo bardzo piękna była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Ale nie chciała królowa Wasty przyjść na rozkazanie królewskie, opowiedziane przez komorników. Przetoż rozgniewał się król bardzo, a gniew jego zapalił się w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Tedy rzekł król do mędrców, rozumiejących czasy: (bo taki był zwyczaj przedkładać sprawy królewskie wszystkim biegłym w prawach i w sądach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'A najbliższymi jego byli Charsena, Setar, Admata, Tarsys, Meres, Marsena, Memuchan, siedm książąt Perskich i Medskich, którzy patrzali na oblicze królewskie, i siadali na pierwszem miejscu w królestwie.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Co czynić podług prawa z królową Wasty, przeto, iż nie uczyniła rozkazania króla Aswerusa, opowiedzianego przez komorników?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'Tedy odpowiedział Memuchan przed królem i książętami: Nie przeciwko królowi samemu wystąpiła Wasty królowa, ale przeciwko wszystkim książętom, i przeciwko wszystkim narodom, którzy są po wszystkich krainach króla Aswerusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Albowiem gdy się ta sprawa królowej doniesie do wszystkich niewiast, znieważą sobie mężów swoich w oczach swoich, i rzeką: Król Aswerus rozkazał przywieść Wasty królowę przed oblicze swoje, a nie przyszła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'Owszem dzisiaj toż rzeką księżny Perskie i Medskie, (które słyszały postępek królowej) wszystkim książętom królewskim, a będzie dosyć wzgardy i waśni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Przetoż, jeśli się za dobre widzi królowi, niech wynijdzie wyrok królewski od oblicza jego, a niech będzie wpisan między prawa Perskie i Medskie, których się przestępować nie godzi: Że nie chciała przyjść Wasty przed obliczność króla Aswerusa, przetoż królestwo jej da król innej, lepszej niż ona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'A gdy usłyszą ten wyrok królewski, który wydasz po wszystkiem królestwie swojem, jako wielkie jest, tedy wszystkie żony będą wyrządzały uczciwość małżonkom swoim od wielkiego aż do małego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'I podobała się ta rada królowi i książętom. I uczynił król według rady Memuchanowej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'A rozesłał listy do wszystkich krain królewskich, do każdej krainy pismem jej własnem, i do każdego narodu językiem jego, aby każdy mąż był panem w domu swoim. A to obwołano językiem każdego narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'To gdy się stało, a uśmierzył się gniew króla Aswerusa, wspomniał na Wasty, i na to, co była uczyniła, i na dekret, który był wydan przeciwko niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'I rzekli dworzanie królewscy, słudzy jego: Niech poszukają królowi dzieweczek, panienek pięknej urody;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'A niech postanowi król starostów po wszystkich krainach królestwa swego, którzyby zebrali wszystkie dzieweczki, panienki pięknej urody, do Susan miasta stołecznego, do domu białych głów, pod dozór Hegaja, komornika królewskiego, stróża białych głó w, a dali im ochędostwa ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'A panienka, któraby się upodobała w oczach królewskich, niech króluje miasto Wasty. I podobała się ta rzecz w oczach królewskich, i uczynił tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'A był Żyd w Susan, w mieście stołecznem, imieniem Mardocheusz, syn Jaira, syna Symhy, syna Cysowego, z pokolenia Benjaminowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'A ten był przeniesiony z Jeruzalemu z innymi pojmanymi, którzy byli przeniesieni z Jechonijaszem, królem Judzkim, których był zawiódł w niewolę Nabuchodonozor, król Babiloński.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Ten chował Hadassę, którą też zwano Ester, córkę stryja swego, przeto, iż nie miała ojca, ani matki; a była panienka pięknej urody, i wdzięcznej twarzy, którą Mardocheusz po śmierci ojca jej i matki jej za córkę przyjął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'A gdy się rozgłosiło rozkazanie królewskie, i wyrok jego, i gdy zgromadzono panienek wiele do Susan, miasta stołecznego, pod dozór Hegaja, wzięto też i Esterę do domu królewskiego pod dozór Hegaja, stróża białych głów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'I podobała mu się ona dzieweczka, a znalazła łaskę w oczach jego. Przetoż jej zaraz kazał dać ochędostwo jej, i dział jej, i siedm panienek nadobnych kazał jej dać z domu królewskiego; nadto opatrzenia jej i panienek jej polepszył w domu białogłowskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Ale nie oznajmiła Ester ludu swego, ani rodziny swej; albowiem jej był Mardocheusz przykazał, aby nie oznajmowała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'Ale Mardocheusz na każdy dzień przechadzał się przed sienią domu białogłowskiego, chcąc się dowiedzieć, jakoby się miała Ester, i coby się z nią działo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'A gdy przychodził pewny czas każdej panny, aby weszła do króla Aswerusa, gdy się wypełniło przy niej wszystko według prawa białych głów przez dwanaście miesięcy; (bo się tak wypełniały dni ochędażania ich, mażąc się przez sześć miesięcy olejkiem z myrry, a przez drugie sześć miesięcy rzeczami wonnemi, i innem ochędostwem białogłowskiem.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'Zatem panna wchodziła do króla, a o cokolwiek rzekła, to jej dano, aby z tem poszła z domu białogłowskiego aż do pokoju królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'W wieczór wchadzała, a rano się zaś wracała do drugiego domu białogłowskiego pod straż Saasgazy, komornika królewskiego, stróża założnic; nie wchadzała więcej do króla, ale jeźli się upodobała królowi, przyzywano jej z imienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'A gdy przyszedł czas pewny Esterze, córce Abihaila, stryja Mardocheuszowego, (który ją był sobie wziął za córkę.) aby weszła do króla, nie żądała niczego, tylko co jej rzekł Hegaj, komornik królewski, stróż białych głów. I miała Ester łaskę w ocz ach wszystkich, którzy ją widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'A tak wzięta jest Ester do króla Aswerusa, do domu jego królewskiego, miesiąca dziesiątego, (ten jest miesiąc Tebet,) roku siódmego królowania jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'I rozmiłował się król Estery nad wszystkie białe głowy, a miała łaskę i miłość u niego nad wszystkie panny, tak, iż włożył koronę królewską na głowę jej, a uczynił ją królową miasto Wasty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Nadto sprawił król ucztę wielką na wszystkich książąt swoich, i sług swoich, to jest ucztę Estery, i dał odpoczynek krainom, i rozdawał dary, tak jako przystoi królowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'A gdy powtóre zebrane były panny, a Mardocheusz siedział u bramy królewskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, '(A Ester nie oznajmiła była narodu swego, ani ludu swego, jako jej był rozkazał Mardocheusz; bo rozkazaniu Mardocheuszowemu dosyć czyniła Ester, jako gdy ją wychowywał u siebie.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'W oneż dni, gdy Mardocheusz siedział u bramy królewskiej, rozgniewał się Bigtan i Teres, dwaj komornicy królewscy, z tych, którzy strzegli progu, i szukali jakoby ściągnąć rękę na króla Aswerusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'Czego dowiedziawszy się Mardocheusz, oznajmił to królowej Esterze, a Estera to oznajmiła królowi imieniem Mardocheuszowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'A gdy się tego dowiadywano, znalazło się tak; i powieszono obu na szubienicy, a napisano to w księgach kroniki przed królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Po tych sprawach wielmożnym uczynił król Aswerus Hamana, syna Hamedatowego, Agagiejczyka, i wywyższył go, i wystawił stolicę jego nad wszystkich książąt, którzy byli przy nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'A wszyscy słudzy królewscy, którzy byli u bramy królewskiej, kłaniali mu się, i upadali przed Hamanem: albowiem tak był rozkazał król o nim. Ale Mardocheusz nie kłaniał się, ani upadał przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Przetoż rzekli słudzy królewscy, którzy byli w bramie królewskiej, do Mardocheusza: Czemuż ty przestępujesz rozkazanie królewskie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'A gdy tak do niego na każdy dzień mawiali, a nie usłuchał ich, oznajmili to Hamanowi, chcąc widzieć, jeźli się ostoją słowa Mardocheuszowe; bo im był powiedział, że był Żydem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'A widząc Haman, iż się Mardocheusz nie kłaniał, ani upadał przed nim, napełniony jest Haman popędliwością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'I miał to sobie za rzecz lekką, targnąć się na samego Mardocheusza; (bo mu było oznajmiono, z którego ludu był Mardocheusz,) przetoż się starał Haman, aby wytracił wszystkich Żydów, którzy byli po wszystkiem królestwie Aswerusowem, naród Mardocheu szowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'A tak miesiąca pierwszego (ten jest miesiąc Nisan) roku dwunastego króla Aswerusa rozkazał Haman miotać Pur (to jest los) przed sobą ode dnia do dnia, i od miesiąca aż do miesiąca dwunastego; (ten jest miesiąc Adar.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'Bo był rzekł Haman do króla Aswerusa: Jest lud niektóry rozproszony i rozsypany między ludem po wszystkich krainach królestwa twego, którego prawa różne są od praw wszystkich narodów, a praw królewskich nie przestrzegają; przetoż nie jest pożyteczno królowi, zaniechać ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Jeźli się tedy królowi zda, niech będzie napisano, aby byli wytraceni. A ja dziesięć tysięcy talentów srebra odważę do rąk przełożonych nad tą pracą, aby je odnieśli do skarbu królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Tedy zdjął król pierścień swój z ręki swej, i dał go Hamanowi Agagiejczykowi, synowi Hamedatowemu, nieprzyjacielowi żydowskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'I rzekł król do Hamana: Srebroć to daruję, i ten lud, abyś z nim czynił, coć się podoba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Przetoż przyzwano pisarzy królewskich miesiąca pierwszego, trzynastego dnia tegoż miesiąca, i napisano wszystko, jako był rozkazał Haman, do książąt królewskich, i do starostów, którzy byli nad każdą krainą, i do hetmanów każdego narodu, do każdej krainy według pisma jej, i do każdego narodu według języka jego. Imieniem króla Aswerusa napisano, i zapieczętowano sygnetem królewskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'I rozesłano listy przez posłów do wszystkich krain królewskich, aby wygładzono, wymordowano, i wytracono wszystkich Żydów, od młodego aż do starca, dziatki i niewiasty, dnia jednego, trzynastego dnia miesiąca dwunastego, (ten jest miesiąc Adar.) a korzyść ich aby rozchwycono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'A tać suma była tych listów, aby obwołano po wszystkich krainach, i oznajmiono wszystkim narodom, żeby byli gotowi na on dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Tedy wyjechali posłowie spieszno z rozkazaniem królewskiem; przybito też wyrok w Susan, w mieście stołecznem, a król i Haman siedzieli pijąc; ale miasto Susan było zatrwożone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'A Mardocheusz, dowiedziawszy się wszystkiego, co się było stało, rozdarł szaty swe, i oblekł się w wór, a posypawszy się popiołem, wyszedł w pośród miasta, i wołał głosem wielkim i żałośnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'I przyszedł aż przed bramę królewską; bo się nie godziło wnijść w bramę królewską obleczonemu w wór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'W każdej także krainie i miejscu, gdziekolwiek rozkazanie królewskie, i wyrok jego przyszedł, była wielka żałość między Żydami, post, i płacz, i narzekanie, a w worze, i na popiele wiele ich leżało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'Przetoż przyszedłszy panny Estery, i komornicy jej, oznajmili jej to; i zasmuciła się królowa bardzo i posłała szaty, aby obleczono Mardocheusza, zdjąwszy z niego wór jego. Ale ich on nie przyjął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Tedy zawoławszy Estera Atacha, jednego z komorników królewskich, którego jej był dał za sługę, rozkazała mu z strony Mardocheusza,aby się dowiedział, co i przeczby to było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Wyszedł tedy Atach do Mardocheusza na ulicę miejską, która była przed bramą królewską;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'I oznajmił mu Mardocheusz wszystko, co mu się przydało, i o tej sumie srebra, którą obiecał Haman odważyć do skarbu królewskiego przeciwko Żydom, aby byli wytraceni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Nadto dał mu przepis wyroku, który był przybity w Susan na wytracenie ich, aby okazał Esterze, i oznajmił jej; a żeby jej rozkazał, aby szła do króla, i prosiła go, a przyczyniła się do niego za ludem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'Tedy przyszedłszy Atach oznajmił Esterze słowa Mardocheuszowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'I rzekła Estera do Atacha, wskazując przezeń do Mardocheusza:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Wszyscy słudzy królewscy, i lud krain królewskich wiedzą, że ktobykolwiek (mąż albo biała głowa) wszedł do króla do sieni wnętrznej, nie będąc wezwany, to prawo o nim jest, aby był zabity, oprócz na kogoby wyciągnął król sceptr złoty, ten żyw z ostanie. Alem ja nie była wezwana, abym weszła do króla, już przez trzydzieści dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'A gdy oznajmiono Mardocheuszowi słowa Estery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Rzekł Mardocheusz, aby zasię powiedziano Esterze: Nie mniemaj w umyśle twoim, abyś zachowana być miała w domu królewskim mimo wszystkich Żydów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Albowiem, jeźli ty tak cale milczeć będziesz na ten czas, ulżenie i wybawienie przyjdzie Żydom skąd inąd, ale ty i dom ojca twego zginiecie; a któż wie, jeźliś nie dla tego czasu dostąpiła królestwa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'I rzekła Estera, aby zasię oznajmiono Mardocheuszowi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Idź, zbierz wszystkich Żydów, którzy się znajdują w Susan, a pośćcie za mię, a nie jedzcie ani pijcie przez trzy dni, w nocy ani we dnie. Ja też, i panny moje także, będę pościła; tedy wnijdę do króla, choć to nie według prawa, a jeźli zginę, niech zginę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Tedy szedł Mardocheusz, i uczynił wszystko, co mu była rozkazała Estera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'A dnia trzeciego ubrawszy się Ester w ubiór królewski, stanęła w sieni wewnętrznej domu królewskiego przeciw pałacowi królewskiemu. A król siedział na stolicy królewskiej swojej w pałacu królewskim przeciwko drzwiom domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'A gdy ujrzał król Esterę królowę stojącą w sieni, znalazła łaskę w oczach jego, i wyciągnął król do Estery sceptr złoty, który trzymał w ręce swej. Tedy przystąpiwszy Ester dotknęła się końca sceptru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'I rzekł do niej król: Cóż ci królowa Ester? a co za prośba twoja? Choćbyś też i o połowę królestwa prosiła, tedyć będzie dano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'I odpowiedziała Ester: Jeźli się królowi podoba, niech przyjdzie król i Haman dzisiaj na ucztę, którąm dla niego nagotowała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'I rzekł król: Zawołajcie co rychlej Hamana, aby dosyć uczynił woli Estery. Przyszedł tedy król i Haman na onę ucztę, którą była sprawiła Ester.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Potem król rzekł do Estery, napiwszy się wina: Cóż za prośba twoja? a będzieć dano; co za żądość twoja? Choćbyś i o połowę królestwa prosiła, będzieć dano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Na to odpowiedziała Ester, i rzekła: Żądość moja, i prośba moja ta jest:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Jeźlim znalazła łaskę w oczach królewskich, a jeźli się królowi podoba, aby przyzwolił na prośbę moję, i wypełnił żądość moję, aby jeszcze przyszedł król i Haman na ucztę, którą im zgotuję, a jutro uczynię według słowa królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'A tak wyszedł Haman dnia onego wesoły, i z dobrą myślą; ale gdy ujrzał Haman Mardocheusza w bramie królewskiej, że ani powstał, ani się ruszył przed nim, napełniony był Haman przeciwko Mardocheuszowi popędliwością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Wszakże zatrzymał się Haman, aż przyszedł do domu swego, a posławszy wezwał przyjaciół swoich, i Zeres, żony swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'I powiadał im Haman o sławie bogactw swoich, i o mnóstwie synów swych, i o wszystkiem, jako go uwielbił król, i jako go wywyższył nad innych książąt i sług królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Nadto rzekł Haman: Nawet nie wezwała Ester królowa z królem na ucztę, którą nagotowała, tylko mnie a jeszcze i na jutro jestem od niej z królem wezwany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'Ale mi to wszystko za nic, pokąd ja widzę Mardocheusza Żyda, siedzącego u bramy królewskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'I rzekła mu Zeres, żona jego, i wszyscy przyjaciele jego: Niech postawią szubienicę wysoką na pięćdziesiąt łokci, a rano mów do króla, aby powieszono Mardocheusza na niej, a idź z królem na ucztę z weselem. I upodobała się ta rada Hamanowi, i kazał postawić szubienicę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Onej nocy król nie mogąc spać, kazał przynieść księgi historyi pamięci godnych, i kroniki; i czytano je przed królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'I znaleźli napisane, że oznajmił Mardocheusz zdradę Bigtana i Teresa, dwóch komorników królewskich z tych, którzy strzegli progu, że szukali ściągnąć rękę na króla Aswerusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'Tedy rzekł król: Jakiejż dostąpił czci i zacności Mardocheusz dla tego? Na co odpowiedzieli słudzy królewscy, dworzanie jego: Nic za to nie odniósł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'I rzekł król: Któż jest w sieni? (a Haman przyszedł był do sieni zewnętrznej pałacu królewskiego, chcąc mówić z królem, aby powieszono Mardocheusza na szubienicy, którą mu był nagotował.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'Tedy odpowiedzieli królowi słudzy jego: Oto Haman stoi w sieni. I rzekł król: Niech sam wnijdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'I wszedł Haman. Któremu król rzekł: Coby uczynić mężowi temu, którego król chce uczcić? (a Haman myślił w sercu swem: Komużby chciał król uczciwość większą wyrządzić nad mię?)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'I odpowiedział Haman królowi: Mężowi, którego król chce uczcić,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'Niech przyniosą szatę królewską, w którą się ubiera król, i przywiodą konia, na którym jeżdża król, a niech włożą koronę królewską na głowę jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'A dawszy onę szatę i onego konia do ręki którego z książąt królewskich, z książąt najprzedniejszych, niech ubiorą męża onego, którego król chce uczcić, a niech go prowadzą na koniu po ulicy miejskiej, a niech wołają przed nim: Tak się ma stać mężowi, którego król chce uczcić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'Tedy rzekł król do Hamana: Spiesz się, weźmij szatę i konia, jakoś powiedział, a uczyń tak Mardocheuszowi Żydowi, który siedzi w bramie królewskiej, a nie opuszczaj nic z tego wszystkiego, coś mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Przetoż wziąwszy Haman szatę i konia, ubrał Mardocheusza, i prowadził go na koniu po ulicy miejskiej, wołając przed nim: Tak się ma stać mężowi, którego król chce uczcić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'Wrócił się potem Mardocheusz do bramy królewskiej, a Haman pokwapił się do domu swego z żałością, mając głowę nakrytą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'I powiedział Haman Zeresie, żonie swej, i wszystkim przyjaciołom swoim wszystko, co mu się przydało. I rzekli do niego mędrcy jego, i Zeres, żona jego: Ponieważ z narodu Żydowskiego jest Mardocheusz, przed któregoś obliczem począł upadać, nie przemożesz go, ale pewnie upadniesz przed obliczem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'A gdy oni jeszcze mówili z nim, oto komornicy królewscy przyszli, a przymusili Hamana, aby szedł na ucztę, którą była Ester sprawiła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'A tak przyszedł król i Haman na ucztę do Estery królowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'I rzekł zasię król do Estery drugiego dnia, napiwszy się wina: Cóż za prośba twoja, królowo Ester? a będzieć dano; co za żądość twoja? Choćbyś też i o połowę królestwa prosiła, stanieć się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Tedy odpowiedziała królowa Ester, i rzekła: Jeźlim znalazła łaskę przed oczyma twemi, o królu! a jeźli się królowi podoba, niech mi będzie darowany żywot mój na prośbę moję, i naród mój na żądość moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Albowiemeśmy zaprzedani, ja i naród mój, abyśmy byli wygładzeni, wymordowani i wytraceni. Gdybyśmy za niewolników i niewolnice sprzedani byli, milczałabym, choćby i tak ten nieprzyjaciel nasz nie mógł nagrodzić tej szkody królowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'Tedy odpowiedział król Aswerus, i rzekł do Estery królowej: Któż to jest? a gdzie ten jest, którego serce tak nadęte jest, aby to śmiał uczynić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'Irzekła Ester: Mąż przeciwnik, a nieprzyjaciel najgorszy jest ten Haman. I strwożył się Haman przed królem i królową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'Tedy król wstał w popędliwości swojej od onej uczty, a szedł do ogrodu przy pałacu; ale Haman został, aby prosił o żywot swój Estery królowej; bo wiedział, że mu zgotowane było nieszczęście od króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'Potem król wrócił się z ogrodu, który był przy pałacu, do domu, gdzie pił wino; a Haman upadł był na łoże, na którem siedziała Tedy rzekł król: Izali jeszcze i gwałt chce uczynić królowej u mnie w domu? A gdy te słowa wyszły z ust królewskich, zaraz twarz Hamanową nakryto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'Wtem rzekł Harbona, jeden z komorników, przed królem: Oto jeszcze szubienica, którą był zgotował Haman na Mardocheusza, który się starał o dobre królewskie, stoi przy domu Hamanowym wzwyż na pięćdziesiąt łokci. I rzekł król: Powieście go na niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'I powieszono Hamana na onej szubienicy, którą był zgotował Mardocheuszowi. A tak uspokoił się gniew królewski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Onegoż dnia dał król Aswerus Esterze królowej dom Hamana, nieprzyjaciela żydowskiego; a Mardocheusz przyszedł przed króla; bo mu była oznajmiła Ester, że był jej pokrewnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'Tedy zdjął król pierścień swój, który był wziął od Hamana, i dał go Mardocheuszowi, a Ester postanowiła Mardocheusza nad domem Hamanowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'Potem jeszcze Ester mówiła do króla, upadłszy u nóg jego, i płakała, i prosiła go, aby wniwecz obrócił złość Hamana Agagiejczyka, i zamysł jego, który był wymyślił przeciwko Żydom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Tedy wyciągnął król na Esterę sceptr złoty, a Estera wstawszy stenęła przed królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'I rzekła: Jeźli się królowi podoba, a jeźlim znalazła łaskę przed obliczem jego, i jeźli się to za słuszne zda być królowi, i jeźlim ja przyjemna w oczach jego, niech napiszą, aby były odwołane listy zamysłów Hamana, syna Hamedata Agagiejczyka, które rozpisał na wytracenie Żydów, którzy są po wszystkich krainach królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Albowiem jakożbym mogła patrzeć na to złe, któreby przyszło na lud mój? albo jakobym mogła widzieć zginienie rodziny mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'I rzekł król Aswerus do Estery królowej, i do Mardocheusza Żyda: Otom dom Hamanowy dał Esterze, a onego powieszono na szubienicy, przeto, iż ściągnął rękę swoję na Żydów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Wy tedy piszcie do Żydów, jako się wam podoba, imieniem królewskiem, i zapieczętujcie pierścieniem królewskim; albowiem to, co się pisze imieniem królewskiem, i pieczętuje się pierścieniem królewskim, nie może być odwołane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'A tak zwołano pisarzy królewskich onego czasu, miesiąca trzeciego, (ten jest miesiąc Sywan) dwudziestego i trzeciego dnia tegoż miesiąca, a pisano wszystko, jako rozkazał Mardocheusz, do Żydów i do książąt, i do starostów, i do przełożonych nad krain a mi, którzy są od Indyi aż do Murzyńskiej ziemi nad stem dwudziestą i siedmią krain, do każdej krainy pismem jej, i do każdego narodu językiem jego, i do Żydów pismen ich i językiem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'A gdy napisał imieniem króla Aswerusa, i zapieczętował pierścieniem królewskim, rozesłał listy przez posłów, którzy jeżdżali na koniach prędkich, i na mułach młodych:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'Iż król dał wolność Żydom, którzy byli we wszystkich miastach, aby się zgromadzili, a zastawiali się o duszę swoję, a żeby wytracili, wymordowali, i wygubili wszystkie wojska ludu onego, i krain tych, którzyby im gwałt czynili, dziatkom ich, i żon om ich, a łupy ich żeby rozchwycili;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'A to jednego dnia po wszystkich krainach króla Aswerusa, to jest trzynastego dnia, miesiąca dwunastego, ten jest miesiąc Adar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'Suma tych listów była: Żeby wydano wyrok w każdej krainie, i oznajmiono wszystkim narodom, aby byli Żydzi gotowi na on dzień ku pomście nad nieprzyjaciołmi swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Tedy posłowie, którzy jeżdżali na koniach prędkich i na mułach, bieżeli jak najprędzej z rozkazaniem królewskiem, a przybity był ten wyrok w Susan na pałacu królewskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'A Mardocheusz wyszedł od króla w szacie królewskiej hijacyntowej i białej, i w wielkiej koronie złotej, i w płaszczu bisiorowem, i szarłatnym; a miasto Susan weseliło i radowało się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'A Żydom weszła światłość i wesele, i radość i cześć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'Także w każdej krainie, i w każdem mieście, i na wszelkiem miejscu, gdziekolwiek rozkaz królewski, i wyrok jego doszedł, mieli Żydzi wesele, radość, uczty, i dzień ucieszny; a wiele z narodów onych krain zostawali Żydami; albowiem strach był przypadł od Żydów na nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'Potem dwunastego miesiąca, który jest miesiąc Adar, dnia trzynastego tegoż miesiąca, gdy przyszedł czas rozkazania królewskiego i wyroku jego, aby się wypełnił onegoż dnia, którego się spodziewali nieprzyjaciele żydowscy panować nad nimi, stała się rzecz przeciwna, że panowali Żydowie nad tymi, którzy ich mieli w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'Bo się byli zebrali Żydowie w miastach swych po wszystkich krainach króla Aswerusa, aby ściągnęli rękę na tych którzy złego ich szukali; a nikt się nie ostał przed nimi, bo był przypadł strach ich na wszystkie narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'A wszyscy przełożeni nad krainami, i książęta, i starostowie, i sprawcy robót królewskich, mieli w uczciwości Żydów; bo przypadł strach Mardocheuszowy na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Albowiem Mardocheusz był wielkim w domu królewskim, a sława jego rozchodziła się po wszystkich krainach, gdyż on mąż Mardocheusz postępował, i wielkim urósł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'A tak pobili Żydzi wszystkich nieprzyjaciół swoich, mieczem ich mordując, i tracąc, i niszcząc, a czyniąc z tymi, co ich nienawidzieli, według upodobania swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'Nawet i w Susan, mieście stołecznem, zabili i wytracili Żydzi pięć set mężów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'I Parsandata, i Dalfona, i Aspata,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'I Porata, i Adalijasza, i Arydata,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'I Parymasta, i Arysaja, i Arydaja, i Wajzata,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'Dziesięciu synów Hamana, syna Hamedatowego, nieprzyjaciela żydowskiego, zabili; ale na łupy ich nie ściągnęli ręki swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Onegoż dnia, gdy przyniesiono liczbę pobitych w Susan, mieście królewskiem, przed króla,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'Rzekł król do Estery królowej: W Susan, mieście stołecznem, zabili Żydzi i wytracili pięć set mężów, i dziesięć synów Hamanowych; a w innych krainach królewskich cóż uczynili? cóż jeszcze za prośba twoja? a będzieć dana; a co jeszcze za żądość twoja? a stanieć się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'I rzekła Ester: Jeźli się królowi podoba, niech będzie pozwolono i jutro Żydom, którzy są w Susan, aby uczynili według wyroku dzisiejszego, a dziesięć synów Hamanowych aby zawiesili na szubienicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'I rozkazał król, aby tak było. A tak przybity był wyrok w Susan, i powieszono dziesięć synów Hamanowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'A zgromadziwszy się Żydowie, którzy byli w Susan, i dnia czternastego miesiąca Adar, zabili w Susan trzysta mężów; wszakże na łupy ich nie ściągnęli ręki swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Inni także Żydzi, którzy byli w krainach królewskich, i zebrawszy się zastawiali się za dusze swe; a póty mieli pokój od nieprzyjaciół swych. Bo zabili nieprzyjaciół swoich siedmdziesiąt i pięć tysięcy; wszakże na łupy ich nie ściągnęli ręki swo jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'Poczęli dnia trzynastego miesiąca Adar, a przestali dnia czternastego tegoż miesiąca, a sprawowali tegoż dnia uczty i wesela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Ale Żydzi, którzy byli w Susan, zebrali się dnia trzynastego i czternastego tegoż miesiąca; a odpoczęli piętnastego dnia tegoż miesiąca, i sprawowali dnia onego uczty i wesela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Przetoż Żydzi mieszkający po wsiach, i po miasteczkach niemurowanych, obchodzą dzień czternasty miesiąca Adar z weselem, i z ucztami i z dobrą myślą, posyłając upominki jeden drugiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'Bo pisał Mardocheusz o tem, i rozesłał listy do wszystkich Żydów, którzy byli po wszystkich krainach króla Aswerusa, do bliskich i do dalekich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'Stanowiąc im, aby obchodzili dzień czternasty miesiąca Adar, i dzień piętnasty tegoż miesiąca na każdy rok,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'Według onych dni, w których odpoczęli Żydzi od nieprzyjaciół swoich, a miesiąca tego, który się im był obrócił z smutku w wesele, a z płaczu w dzień radości; aby obchodzili one dni z ucztami i z weselem, jeden drugiemu upominki, a ubogim dary po syłając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'I przyjęli to wszyscy Żydzi, że co zaczęli, czynić będą, i co pisał Mardocheusz do nich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Jako Haman, syn Hamadetowy, Agagiejczyk, nieprzyjaciel wszystkich Żydów, umyślił o Żydach, aby ich wytracił, i miotał pur, to jest los, na wytracenie ich i na wygubienie ich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'A jako Ester weszła przed oblicze królewskie, i mówiła o listy; a jako obrócone były złe zamysły jego, które był wymyślił przeciwko Żydom na głowę jego; i jako go powieszono i synów jego na szubienicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Przetoż nazwali one dni Purym, od imienia tego pur, a to za przyczyną wszystkich słów listu tego, i co widzieli przy tem, i co przyszło na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'Postanowili też i przyjęli to Żydowie na się, i na nasienie swoje, i na wszystkich, którzy się do nich przyłączyli, aby tego nie przestępowano, ale żeby obchodzono te dwa dni według opisania ich, i według postanowionego czasu ich na każdy rok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'A iż te dni będą pamiętne i sławne od wieku do wieku, od rodzaju do rodzaju w każdej krainie, i w każdem mieście. Nadto, że te dni Purym nie zaginą z pośrodku Żydów, a pamiątka ich nie ustanie u potomstwa ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'Napisała też Ester królowa, córka Abihajlowa, i Mardocheusz Żyd, ze wszelką pilnością, aby potwierdzili tym listem wtórym tych dni Purym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'Który list Mardocheusz posłał do wszystkich Żydów, do stu i dwudziestu i siedmiu krain królestwa Aswerusowego, pozdrawiając ich łaskawie i uprzejmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'A żeby statecznie przestrzegali tych dni Purym czasów swoich, jako im je postanowił Mardocheusz Żyd, i Ester królowa, i jako obowiązali siebie samych, i nasienie swoje, na pamiątkę postu i narzekania ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'A tak wyrok Estery potwierdził ustawy tych dni Purym, co zapisano w tej księdze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'Potem ułożył król Aswerus podatek na ziemię swoję, i na wyspy morskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'Awszystkie sprawy mocy jego, i możności jego, z opisaniem zacności Mardocheuszowej, którą go wielmożnym uczynił król, to zapisano w księgach kronik o królach Medskich i Perskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Albowiem Mardocheusz Żyd był wtórym po królu Aswerusie, i wielkim u Żydów, i zacny u mnóstwa braci swych, starając się o dobro ludu swego, i sprawując pokój wszystkiemu narodowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Był mąż w ziemi Uz, imieniem Ijob; a ten mąż był doskonały, i szczery, i bojący się Boga, a odstępujący od złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'I urodziło mu się siedm synów, a trzy córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'A miał dobytku siedm tysięcy owiec, i trzy tysiące wielbłądów, i pięć set jarzm wołów, i pięć set oślic, i czeladzi bardzo wiele, tak, iż on mąż był najmożniejszym nad wszystkich ludzi na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'I schadzali się synowie jego, a sprawowali uczty, każdy w domu swym, dnia swojego; i posyłali, a wzywali trzy siostry swoje, aby jadały i pijały z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'A gdy wkoło obeszły dni uczty, posyłał Ijob, a poświęcał ich, a wstawając rano sprawował całopalenia według liczby ich wszystkich; bo mówił Ijob: Podobno zgrzeszyli synowie moi, a złorzeczyli Bogu w sercach swych. Tak czynił Ijob po one wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'I stało się niektórego dnia, gdy przyszli synowie Boży, aby stanęli przed Panem, że też przyszedł i szatan między nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Tedy rzekł Pan do szatana: Skąd idziesz? I odpowiedział szatan Panu, i rzekł: Okrążałem ziemię, i przechadzałem się po niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'I rzekł Pan do szatana: Przypatrzyłżeś się słudze memu Ijobowi,że mu niemasz równego na ziemi? Mąż to doskonały i szczery, bojący się Boga, i odstępujący od złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'I odpowiedział szatan Panu i rzekł: Izaż się Boga Ijob darmo boi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Azażeś go ty nie ogrodził, i domu jego, i wszystkiego co ma, w około zewsząd? Błogosławiłeś sprawom rąk jego, i dobytek jego rozmnożył się na ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Ale ściągnij tylko rękę twoję a dotknij wszystkiego, co ma: obaczysz, jeźlić w oczy złorzeczyć nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'Tedy rzekł Pan do szatana: Oto wszystko co ma, jest w ręce twojej: tylko nań nie ściągaj ręki twej. I odszedł szatan od oblicza Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'Stało się tedy niektórego dnia, gdy synowie jego i córki jego jedli, i pili wino w domu brata swego pierworodnego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'Przybieżał poseł do Ijoba i rzekł: Woły orały, a oślice się pasły podle nich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'I przypadli Sabejczycy, i zabrali je, a sługi pozabijali ostrzem miecza; a uszedłem tylko ja, ja sam, abym ci oznajmił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'A gdy ten jeszcze mówił, przyszedł drugi, i rzekł: Ogień Boży spadł z nieba i spalił owce i sługi, i pożarł ich; a uszedłem tylko ja, ja sam, abym ci oznajmił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'A gdy ten jeszcze mówił, przyszedł i inny, i rzekł: Chaldejczycy, rozsadziwszy się na trzy hufce, wypadli na wielbłądy, i zabrali je, i sługi pozabijali ostrzem miecza; a uszedłem tylko ja, ja sam, abym ci oznajmił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'A gdy ten jeszcze mówił, przybieżał i inny, a rzekł: Synowie twoi, i córki twoje jedli i pili wino w domu brata swego pierworodnego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'A oto wiatr gwałtowny przypadł od onej strony pustyni, i uderzył na cztery węgły domu, tak, że upadł na dzieci, i pomarły; a uszedłem tylko ja, ja sam, abym ci oznajmił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Tedy wstał Ijob, i rozdarł płaszcz swój, i ogolił głowę swą, a upadłszy na ziemię, uczynił Panu pokłon,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'I rzekł: Nagim wyszedł z żywota matki mojej, i nagim się zaś tamże wrócę; Pan dał, Pan też wziął, niech będzie imię Pańskie błogosławione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'W tem wszystkiem nie zgrzeszył Ijob, a nie przypisał Bogu nic nieprzystojnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'I stało się niektórego dnia, gdy przyszli synowie Boży, aby stanęli przed Panem, przyszedł też szatan między nich, aby stanął przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'Tedy rzekł Pan do szatana: Gdzieś był, skąd idziesz? I odpowiedział szatan Panu, a rzekł: Okrążałem ziemię, i przechodziłem się po niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'Zatem rzekł Pan do szatana: Przypatrzyłżeś się słudze memu Ijobowi, że mu nie masz równego na ziemi? Mąż to doskonały i szczery, bojący się Boga, a odstępujący od złego, i który jeszcze trwa w uprzejmości swojej; a tyś mię pobudził przeciw niemu, abym go niszczył bez przyczyny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'I odpowiedział szatan Panu, i rzekł: Skórę za skórę, i wszystko, co ma człowiek, da za duszę swoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Ale ściągnij tylko rękę twoję, a dotknij kości jego, i ciała jego, ujrzysz, jeźliżeć w oczy złorzeczyć nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Tedy rzekł Pan do szatana: Oto w ręce twojej jest; wszakże żywot jego zachowaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'Wszedłszy tedy szatan od oblicza Pańskiego, zaraził Ijoba wrzodem złym od stopy nogi jego aż do wierzchu głowy jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'Tak, że wziął skorupę, aby się nią skrobał; i siedział w popiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'I rzekła mu żona jego: A jeszczeż trwasz w uprzejmosci twojej? Złorzecz Bogu, a umrzyj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'I rzekł do niej: Tak właśnie mówisz, jako szalone niewiasty mawiają. Izali tylko dobre przyjmować będziemy od Boga, a złego przyjmować nie będziemy? W tem wszystkiem nie zgrzeszył Ijob usty swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'A gdy usłyszeli trzej przyjaciele Ijobowi to wszystko utrapienie, które nań przypadło, przyszli każdy z miejsca swego: Elifas Temańczyk, i Bildad Suhytczyk, i Sofar Naamatczyk; bo się byli namówili pospołu, aby przyszedłszy pożałowali go, i cieszyli go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'A podniósłszy oczy swoje z daleka, nie poznali go, i wyniósłszy głos swój płakali, a rozdarłszy każdy płaszcz swój miotali proch nad głowy swe ku niebu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'I siedzieli z nim na ziemi siedm dni i siedm nocy, a żaden do niego słowa nie przemówił; bo widzieli, że się gwałtownie wzmagała boleść jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Potem otworzył Ijob usta swoje, i złorzeczył dniowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'I zawołał Ijob, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Bodaj był zginął dzień, któregom się urodził! i noc,w którą rzeczono: Począł się mężczyzna!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Bodaj się był on dzień obrócił w ciemność! By się był o nim nie pytał Bóg z wysokości, i nie był oświecony światłością!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Bodaj go była zaćmiła ciemność i cień śmierci! by go był ogarnął obłok, i ustraszyła go gorącość dzienna!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Bodaj była noc onę osiadła ciemność, aby nie szła w liczbę dni rocznych, i w liczbę miesięcy nie przyszła!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Bodaj noc ona była samotna, a śpiewania aby nie było w niej!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Bodaj ją byli przeklęli, którzy przeklinają dzień, którzy są gotowi, wzruszać płacz swój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Bodaj się były zaćmiły gwiazdy przy zmierzkaniu jej! a czekając światła, aby się go była nie doczekała, ani nie oglądała zorzy porannej!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'Iż nie zawarła drzwi żywota mego, a nie skryła boleści od oczu moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Przeczżem w żywocie nie umarł, albo, gdym z żywota wyszedł, czemum nie zginął?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Przeczże mię piastowano na kolanach? a przeczżem ssał piersi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Albowiembym teraz leżał i odpoczywał; spałbym i miałbym pokój,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 'Z królmi i z radcami ziemi, którzy sobie budowali na miejscach pustych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'Albo z książętami, którzy mieli złoto, a napełniali domy swe srebrem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Albo czemum się nie stał jako martwy płód skryty? albo jako niemowlątka, które nie oglądały światłości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Tam niepobożni przestawają straszyć, i tam odpoczywają zwątleni w siłę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'Tamże więźniowie sobie wydychają, a nie słyszą głosu trapiącego ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Mały i wielki tam sobie są równi a niewolnik wolny od pana swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Przecz nędznemu dana jest światłość, a żywot tym, którzy są utrapionego ducha?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'Którzy czekają śmierci, a nie przychodzi, choć jej pilniej szukają niż skarbów skrytych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'Którzyby się z radością weselili, pląsając, gdyby znaleźli grób.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Przecz dana jest światłość mężowi, którego droga skryta jest, a którego Bóg ciężkościami ogarnął?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Albowiem kiedy mam jeść, wzdychanie moje przychodzi, a rozchodzi się jako woda ryczenie moje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Bo strach, któregom się lękał, przyszedł na mię, a czegom się obawiał, przydało mi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Nie byłem bezpieczny, anim się uspokoił, anim odpoczywał, a przecież na mię przyszła trwoga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'Tedy odpowiedział Elifas Temańczyk, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Jeźli będziemy mówili z tobą, nie będzie ci to przykro? Ale któż się może od mówienia zatrzymać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Otoś ich wiele uczył, i ręceś mdłe potwierdzał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Upadającego wspierały mowy twoje, a kolana zemdlone posilałeś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'A teraz, gdy to na cię przyszło, niecierpliwie znosisz, a iż cię dotknęło, trwożysz sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Azaż pobożność twoja nie była ufnością twoją, a uprzejmość spraw twoich oczekiwaniem twojem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Wspomnij proszę, kto kiedy niewinny zginął? albo gdzieby ludzie szczerzy zniszczeli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Jakom widał, że ci, którzy orali złość, i rozsiewali przewrotność, toż też zasię żęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Bo tchnieniem Bożem giną, a od ducha gniewu jego niszczeją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Ryk lwi, i głos lwicy, i zęby lwiąt wytrącają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'Lew ginie, iż nie ma łupu, i szczenięta lwie rozproszone bywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'Nadto doszło mię słowo potajemnie, i pojęło ucho moje cokolwiek z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'W rozmyślaniu widzenia nocnego, gdy przypada twardy sen na ludzi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'Zdjął mię strach i lękanie, które wszystkie kości moje przestraszyło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'A duch szedł przed twarzą moją, tak, iż włosy wstały na ciele mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Stanął, a nie znałem twarzy jego, kształt tylko jakiś był przed oczyma memi; uciszyłem się, i słyszałem głos mówiący:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, 'Izali człowiek może być sprawiedliwszy niżeli Bóg; albo mąż czystszy niż Stworzyciel jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Oto w sługach jego niemasz doskonałości, a w Aniołach swoich znalazł niedostatek;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'Daleko więcej w tych, co mieszkają w domach glinianych, których grunt jest na prochu, i starci bywają snadniej niżeli mól.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Od poranku aż do wieczora bywają starci; a iż tego nie uważają, na wieki zginą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Azaż zacność ich nie pomija z nimi? umierają, ale nie w mądrości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Zawołajże tedy, jeźli kto jest, coćby odpowiedział? a do któregoż się z świętych obrócisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Zaiste głupiego zabija gniew, a prostaka umarza zawiść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Jam widział głupiego, iż się rozkorzenił; alem wnet źle tuszył mieszkaniu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Oddaleni będą synowie jego od zbawienia, i starci będą w bramie, a nie będzie, ktoby ich wyrwał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'Żniwo jego głodny pożre, i z samego ciernia wybierze je; a połknie chciwy bogactwa takowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Albowiem nie z prochu wychodzi utrapienie, ani z ziemi wyrasta kłopot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'Ale człowiek na kłopot się rodzi jako iskry z węgla latają w górę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Zaiste jabym szukał Boga, Bogubym przełożył sprawę swoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'Który czyni rzeczy wielkie i niewybadane, dziwne, którym liczby niemasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'Który daje deszcz na ziemię, i spuszcza wody na pola;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'Który sadza pokornych wysoko, a smutnych wywyższa ku zbawieniu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'Który w niwecz obraca myśli chytrych, tak, iż ręce ich nie sprawią nic skutecznego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'Który chwyta mądrych w chytrości ich, a radę przewrotnych prędko niszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'We dnie taczają się jako w ciemnościach, a jako w nocy macają w południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'Który zachowuje ubogiego od miecza, od ust ich, i od ręki gwałtownika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'Mać uciśniony nadzieje; ale nieprawość stuli usta swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Oto błogosławiony człowiek, którego Bóg karze; przetoż karaniem Wszechmocnego nie pogardzaj,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Bo on zrania i zawiązuje; uderza, a ręce jego uzdrawiają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Z sześciu ucisków wyrwie cię, a w siódmym nie tknie się ciebie złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'W głodzie wybawi cię od śmierci, a na wojnie z rąk miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Przed biczem języka ukryty będziesz, a nie ulękniesz się w spustoszeniu, gdy przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'W spustoszeniu i w głodzie śmiać się będziesz, a zwierząt ziemskich bać się nie będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'Bo z kamieniem polnym będzie przymierze twoje, a okrutny zwierz polny spokojnym ci się stawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'I poznasz, że jest spokojny przybytek twój, i nawiedzisz mieszkanie twoje, a nie zgrzeszysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Doznasz też, iż rozmnożone będzie nasienie twoje, a potomstwo twoje będzie jako ziele ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Wnijdziesz w sędziwości do grobu, jako znoszone bywa zboże w stóg czasu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Otośmy tego doszli, że tak jest: słuchajże tego, a uważaj to sam u siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'I odpowiedział Ijob, a rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'O gdyby pilnie zważono narzekanie moje, a biedę moję pospołu na wagę włożono,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Tedyby była cięższą nad piasek morski; przetoż mi słów niestaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Albowiem strzały Wszechmocnego tkwią we mnie, których jad wysuszył ducha mego, a strachy Boże walczą przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Izali osieł dziki ryczy nad trawą? albo wół izali ryczy nad paszą swoją?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Izali może być jedzona rzecz niesmaczna bez soli? albo jestli jaki smak w białku jajowym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Czego się przedtem nie chciała dotknąć dusza moja, to teraz jest boleścią ciała mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'Bodajże się spełniła prośba moja! Niechże mi Bóg da, czego oczekuję!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'Oby się Bogu podobało, żeby mię zniszczył, a żeby mię wyciął, rozpuściwszy rękę swoję!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Bo mam jeszcze pociechę swoję, (chociaż pałam w boleści, a Bóg mi nie folguje) żem nie taił słów Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Cóż jest za moc moja, abym potrwał? albo co za koniec mój, abym przedłużył żywota mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Izali moc kamienna moc moja? albo ciało moje miedziane?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Azaż obrony mojej niemasz przy mnie? azaż rozsądek oddalony odemnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Przeciwko temu, którego litość słabieje ku bliźniemu swemu, i który bojaźń Wszechmogącego opuścił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Bracia moi omylili mię jako potok; pominęli jako gwałtowne potoki,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'Które bywają mętne od lodu, w których się śnieg ukrywa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Czasu którego topnieją, zaginą; a czasu gorącości niszczeją z miejsca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Udawają się tam i sam z dróg swoich; rozciekają się po miejscach bezwodnych, i giną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Podróżni ludzie z krainy Teman obaczyli je; a którzy szli do Seba, mieli w nich nadzieję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'Ale się zawstydzili, iż w nich ufali; a gdy tam przyszli, oszukali się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Tak zaiste i wy, bywszy nie jesteście; widząc utrapienie moje, lękacie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Izalim mówił: Przynieście mi co, a z majętności waszej dajcie mi dary?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'I wybawcie mię z rąk nieprzyjaciela, a z rąk okrutników odkupcie mię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Nauczcież mię, a ja umilknę; a w czemem zbłądził pokażcie mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'O jakoż są mocne słowa prawdziwe! Ale cóż sprawi obwinienie wasze?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Izali słowa moje obwinić myślicie, a przewiewać mowy utrapionego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'I na sierotę targacie się, i kopiecie doły pod przyjacielem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'Przetoż przypatrzcie mi się teraz, a obaczycie, jeźli kłamię przed obliczem waszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Obaczcie się, proszę, a niech nie będzie w was nieprawość; obaczcie się, a poznacie, że jest sprawiedliwość moja przy mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'A iż nie masz w języku mym nieprawości: i nie mamże znać utrapienia mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Izali czas nie jest zamierzony człowiekowi na ziemi? a jako dni najemnicze nie są dni jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Jako sługa pragnie cienia, a jako najemnik czeka końca pracy swojej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'Takiem ja prawem dziedzicznem wziął miesiące próżne, a nocy boleśne są mi naznaczone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Układęli się, tedy mówię: Kiedyż wstanę? a rychło pominie noc? i pełen bywam myślenia aż do świtania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Obleczone jest ciało moje w robaki i w plugastwo z prochu; skóra moja popadała się, i rozsiadła się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Dni moje prędsze są, niż czółnek tkacki, i strawione są bez nadziei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Wspomnij, o Panie! iż wiatrem jest żywot mój, nie wróci się oko moje, aby widziało dobre rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Ani mię ogląda oko, które mię widywało; oczy twoje obrócone będą na mię, a mnie nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Jako niszczeje obłok i przemija, tak zstępujący do grobu nie wynijdzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'Nie wróci się więcej do domu swego, ani go więcej pozna miejsce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Przetoż ja nie mogę zawściągnąć ust moich; mówić będę w utrapieniu ducha mego, będę rozmawiał w gorzkości duszy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Izażem ja jest morze, albo wieloryb, zasię mię osadził strażą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Gdym rzekł: Pocieszy mię łoże moje, i ulży mi narzekania mego pościel moja:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'Tedy mię straszysz przez sny, i przez widzenia trwożysz mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'A przetoż obrała sobie powieszenie dusz moja, a śmierć raczej, niż zostać w kościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Sprzykrzyłem sobie żywot, nie wiecznie będę żyw. Zaniechajże mię, bo marnością są dni moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Cóż jest człowiek, że go tak wielce ważysz? a że przykładasz ku niemu serce twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'A że go nawiedzasz na każdy zaranek? i na każdą chwilę doświadczasz go?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Pokądże się nie odwrócisz odemnie? a nie zaniechasz mię, ażbym przełknął ślinę moję?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Zgrzeszyłem, cóż mam czynić? o stróżu ludzki! czemuś mię sobie za cel położył, abym był sam sobie ciężarem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Przecz nie odejmiesz przestępstwa mego, i nie przepuścisz nieprawości mojej? Bo się teraz w prochu położę, a choćbyś mię szukał rano, nie będzie mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'I odpowiedział Bildad Suhytczyk, a rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Pokądże rzeczy takowe mówić będziesz? a pokąd będą słowa ust twoich jako wiatr gwałtowny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Izażby miał Bóg sąd podwrócić? a Wszechmocny miałby sprawiedliwość wynicować?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Że synowie twoi zgrzeszyli przeciw niemu, przetoż ich puścił w rękę nieprawości ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Jeźli się ty wczas nawrócisz do Boga, a będziesz się modlił Wszechmocnemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'Jeźli będziesz czystym i szczerym; tedyć pewnie ocuci dla ciebie, i spokojne uczyni mieszkanie sprawiedliwości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'A choć początek twój mały będzie, jednak ostatek twój bardzo się rozmnoży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Bo spytaj się proszę wieku starego, a nagotuj się ku wyszpiegowaniu ojców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, '(Gdyż wczorajszymi jesteśmy, a nic nie wiemy, ponieważ jako cień są dni nasze na ziemi.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'Oni cię nauczą i powiedząć, i z serca swego wypuszczą słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Azaż urośnie sitowie bez wilgotności? Izali urośnie rogoża bez wody?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'Owszem jeszcze w zieloności swojej, niż bywa podcięta, prędzej niż inna trawa usycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Takieć są drogi wszystkich, którzy zapominają Boga; i tak nadzieja obłudnika zginie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'Podcięta bywa nadzieja jego, a jako dom pająka ufanie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Spolężeli na domu swoim, nie ostoi się; wesprzeli się na nim, nie zadzierzy się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Zieleni się na słońcu, i w ogrodzie jego świeża latorośl jego wyrasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'Nad ródłem splątają się korzenie jego, i na miejscu kamienistem rozkłada się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Ale gdy go wytną z miejsca jego, tedy się go miejsce zaprze, mówiąc: Niewidziałem cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Toć to jest wesele drogi jego, a inny z ziemi wyrośnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Oto Bóg nie odrzuci człowieka szczerego, ale złośnikom nie poda ręki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Aż się napełnią śmiechem usta twe, a wargi twoje wykrzykaniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'Gdyż, którzy cię mają w nienawiści, obleczeni będą wstydem, a przybytku niepobożnych nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'I odpowiedział Ijob, a rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Prawdziwieć wiem, że tak jest; bo jakożby miał być usprawiedliwiony człowiek przed Bogiem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Jeźliby się z nim chciał spierać, nie odpowie mu z tysiąca na jednę rzecz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Mądry jest sercem, i mocny siłą; któż użył pokoju, stawiwszy się mu upornie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'On przenosi góry, a nie wiedzą ludzie, kto je podwraca w gniewie swym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'On wzrusza ziemię z miejsca swego, a słupy jej trzęsą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'Gdy on zakaże słońcu, nie wschodzi; i gwiazdy pieczętuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'On sam rozpościera niebiosa, i depcze po wałach morskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'On sprawił wóz niebieski z gwiazd, Oryjona i Hyjady, i inne gwiazdy skryte na południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'On czyni rzeczy wielkie, a niewybadane i dziwne, którym niemasz liczby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Oto, idzieli mimo mię, nie widzę go; a przychodzili, nie baczę go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Oto gdy co porwie, któż go przymusi, aby przywrócił? Albo któż mu rzecze: Cóż czynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Gdyby Bóg nie odwrócił gniewu swego, upadliby przed nim pomocnicy hardzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Jakoż mu ja tedy odpowiem? Jakie słowa obiorę przeciwko niemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Któremu, chociażbym był sprawiedliwym, nie odpowiem; owszem się sędziemu memu upokorzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Choćbym go wzywał, a onby mi się ozwał, przecię nie wierzę, aby przypuścił do uszów głos mój:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'Bo mię starł w wichrze, i rozmnożył rany moje bez przyczyny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'Nie dopuszcza mi odetchnąć, owszem mię nasyca gorzkościami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Jeźli się udam do mocy, oto on najmocniejszy; a jeźli do sądu, któż mię z nim sprowadzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Jeźlibym się usprawiedliwiał, usta moje potępią mię; jeźlibym się doskonałym czynił, tedy mię przewrotnym być pokaże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Chociażbym był doskonały, przecież ja tego do siebie znać nie będę; ale dam naganę żywotowi memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'Jedno jest, dla czegom to mówił: że tak doskonałego, jako i niezbożnego on niszczy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Jeźli biczem nagle zabija, z pokuszenia niewinnych naśmiewa się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Ziemia podana bywa w ręce niezbożnika, oblicze sędziów jej zakrywa. A jeźliż nie on, któż tedy inny jest, co to czyni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Ale dni moje prędsze były niż poseł; uciekły, a nie widziały nic dobrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Przeminęły jako prędkie łodzie, jako orzeł lecący do żeru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Jeźli rzekę: Zapomnę narzekania mego, zaniecham gniewu swego, a posilę się:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'Tedy się lękam wszystkich boleści moich, widząc, że mię z nich nie wypuścisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Jeźlim ja niezbożny, przeczże próżno pracuję?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'A choćbym się umywał wodami śnieżnemi, i oczyściłbym mydłem ręce moje:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'Wszakże w dole zanurzysz mię, i brzydzić się mną będą szaty moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Albowiem on nie jest człowiekiem jako ja, abym mu śmiał odpowiedzieć, albo żebym z nim miał iść w prawo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Bo nie masz między nami rozjemcy, któryby mógł rozwieść sprawę naszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Niech tylko zdejmie zemnie rózgę swoję, a strach jego niech mię nie straszy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'Tedy będę mówił, a nie będę się go bał; bom ja nie jest taki sam u siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Tęskni sobie dusza moja w żywocie moim; rozpuszczę przeciw sobie narzekanie moje, a będę mówił w gorzkości duszy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Rzekę Bogu: Nie potępiajże mię; raczej mi oznajmij, czemu spór ze mną wiedziesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Cóż masz za pożytek, że mię uciskasz? a iż odrzucasz sprawę rąk twoich? a radę niepobożnych oświecasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Azaż ty masz oczy cielesne? Albo jako człowiek widzi, ty widzisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'Dni twoje, zaż są jako dni człowiecze? a lata twoje jako lata ludzkie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'Iż się wywiadujesz nieprawości mojej, a o grzechu moim badasz się?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'Ty wiesz, żem niepobożnie nie poczynał; wszakże nie jest, ktoby mię miał wyrwać z rąk twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Ręce twoje wykształtowały mię, i uczyniły mię; a przecię mię zewsząd gubisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Pomnij proszę, żeś mię jako glinę ulepił, a w proch mię zaś obrócisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Izali jako mleko nie zlałeś mię, a jako ser nie utworzyłeś mię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'Skórą i ciałem przyoblokłeś mię, a kościami i żyłami pospinałeś mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Żywotem i miłosierdziem darowałeś mię, a opatrzność twoja strzegła ducha mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'A chociażeś to skrył w sercu twojem, wiem jednak, że to jest z woli twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'Jeźli zgrzeszę, wnet tego postrzeżesz, a dla nieprawości mojej nie przepuścisz mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Jeźlim bezbożny, biada mi! a choćbym też był sprawiedliwym, nie podniosę głowy mojej, będąc nasycony pohańbieniem,i widząc utrapienie moje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'Którego przybywa; bo jako lew srogi gonisz mię, a coraz dziwniej się przeciwko mnie stawiasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'Odnawiasz świadków twoich przeciwko mnie, a rozmnażasz rozgniewanie twoje na mię; wojska jedne po drugich są przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Przeczżeś mię z żywota wywiódł? Ach, bym był umarł, żeby mię było oko nie widziało!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Obym był, jakoby mię nie było! oby mię było zaraz z żywota do grobu zaniesiono!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Izaż nie trocha dni moich? Przetoż przestań, a zaniechaj mię, abym się troszeczkę posilił,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'Pierwej niż odejdę tam, skąd się nie wrócę, do ziemi ciemności, i do cienia śmierci;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'Do ziemi ciemnej, jako chmura, i do cienia śmierci, gdzie niemasz przemiany, jedno sama gęsta ciemność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'I odpowiedział Sofar Naamatczyk, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Izaż się nie godzi na wiele słów odpowiedzieć? Albo izali mąż wielomowny będzie usprawiedliwiony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Bedąż na twoje plotki ludzie milczeć? A gdy ty sobie przeszydzasz, ciebie nikt nie zawstydzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'Albowiemeś powiedział: Czysta jest nauka moja, a jestem czystym przed oczyma twemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'Ale gdyby Bóg chciał mówić, i otworzyć usta swoje przeciwko tobie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Tedyćby objawił tajemnice mądrości, żeś dwa kroć większe karanie nadto zasłużył; przetoż uznaj, że cię Bóg przebaczył dla nieprawości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Izali tajemnice Boże wybadasz? albo doskonałości Wszechmocnego dościgniesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Wyższe są niż niebiosa, cóż uczynisz? Głębsze niż piekło, jakoż poznasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'Dłuższa miara ich, niż ziemia, a szersza, niż morze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Jeźli wypełni, albo jeźli zawrze, albo jeźli w jedno ściśnie, któż go zawściągnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Albowiem on zna marność ludzką, i widzi nieprawość; a nie miałby tego baczyć?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'Człowiek nierozumny nabywa rozumu, choć się jako źrebię leśnego osła rodzi człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Jeźli ty przygotujesz serce twoje, a wyciągniesz do niego ręce twoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'Jeźliż nieprawość jest w ręce twej oddal ją, a mieszkać nie dopuszczaj nieprawości w przybytkach twoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'Tedy podniesiesz oblicze twoje bez zmazy, a będziesz stały, i nie będziesz się bał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Albowiem zapomnisz kłopotu, a jako wody, które pominęły, wspominać go będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'I nad południe jaśniejszy nastanie czas twój; zaćmiszli się, będziesz jako zaranek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'I będziesz ufał, mając nadzieję, a jako w okopach bezpiecznie spać będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Będziesz leżał, a nikt cię nie przestraszy; i uniżać się będą przed twarzą twoją wiele ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Ale oczy niepobożnych ustaną i ucieczka ich zginie, a nadzieja ich będzie jako wyjście duszy z człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'Zatem odpowiedział Ijob i, rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Wieraście wy sami ludźmi? i z wamiż umrze mądrość?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Teżci ja mam serce jako i wy, anim jest podlejszym niżeli wy; a któż i tego nie wie, co i wy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'Pośmiewiskiem jestem przyjacielowi memu, który gdy woła do Boga, ozywa mu się; naśmiewiskiem jest sprawiedliwy i doskonały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Ten, co jest upadku bliski, jest pochodnią wzgardzoną człowiekowi, według myśli pokoju zażywającemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Spokojne i bezpieczne są namioty zbójców tych, którzy draźnią Boga, którym Bóg daje w ręce dobre rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'A nawet pytaj się proszę bydląt, a one cię nauczą; i ptastwa niebieskiego, a oznajmi tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'Albo się rozmów z ziemią, a ona cię nauczy, i rozpowiedząć ryby morskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Któż nie wie z tych wszystkich rzeczy, że to ręka Pańska sprawiła?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'W którego ręku jest dusza wszelkiej rzeczy żywej, i duch wszelkiego ciała ludzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Azaż nie ucho mowy doświadcza, jako usta pokarmu smakują?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'W ludziach starych jest mądrość, a w długich dniach roztropność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Dopieroż u Pana jest mądrość, i siła, i rada, i umiejętność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Oto on burzy, a nikt nie zbuduje; zamknie człowieka, a nikt mu nie otworzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'On gdy zatrzyma wody, wyschną; a gdy je wypuści, podwracają ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'U niego jest moc i mądrość. Jego jest błądzący, i w błąd zawodzący.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'On obiera radców z mądrości, a sędziów przywodzi do głupstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'On pas królów rozwiązuje, i znowu przepasuje pasem biodra ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Podaje książęta na łup, a mocarze podwraca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Odejmuje usta krasomówcom, a rozsądek starym odbiera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Wylewa wzgardę na książęta, a mdli siły mocarzów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'On odkrywa głębokie rzeczy z ciemności, a wywodzi na jaśnię cień śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'Rozmnaża narody, i wytraca je; rozszerza lud, i umniejsza go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'On odejmuje serca przełożonym ludu ziemi, a czyni, że błądzą po pustyni bezdrożnej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'Że macają w ciemnościach, gdzie nie masz światłości, a sprawuje, że błądzą jako pijani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Oto te wszystkie rzeczy widziało oko moje, słyszało ucho moje, i zrozumiało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Jako wy to wiecie, tak ja też wiem, i nie jestem podlejszym niźli wy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Wszakże radbym z Wszechmocnym mówił, i radbym się z Bogiem rozpierał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Boście wy sprawcy kłamstwa: wszyscyście wy lekarze nikczemni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Byście wy raczej milczeli, a poczytanoby wam to za mądrość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Słuchajcież teraz odporu mego, a dowody ust moich obaczcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Izali broniąc Boga mówić będziecie nieprawość? albo za nim mówić będziecie fałsz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Czy się na osobę jego oglądać będziecie? Czy się o Boga będziecie spierać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Zaż to dobrze będzie, gdy on was będzie próbował? Zaż, jako człowiek oszukany bywa, tak wy go oszukacie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Zaiste karać was będzie, jeźlibyście skrycie twarz jego przyjmowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Izali zacność jego nie ustraszy was? a strach jego nie przypadnie na was?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Pamiątki wasze podobne są popiołowi, a wyniosłość wasza kupie błota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Milczcież, zaniechajcie mię, a ja mówić będę; a niech przyjdzie na mię, co chce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Czemuż mam szarpać ciało moje zębami mojemi, i duszę moję kłaść w ręce swe?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Oto, choćby mię i zabił, przecię w nim będę ufał; wszakże dróg moich przed obliczem jego będę bronił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Onci sam będzie zbawieniem mojem, ale przed oblicze jego obłudnik nie przyjdzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Słuchajcież z pilnością mowy mojej, a powieść moja niech przyjdzie w uszy wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Oto się teraz gotuję do prawa, i wiem, że usprawiedliwiony będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Któż się będzie spierał ze mną, tak abym umilknął i umarł?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Tylko dwóch rzeczy, o Boże! nie czyń ze mną, przed oblicznością twoją nie skryję się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Rękę twoję odemnie oddal, a strach twój niech mną nie trwoży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Potem zawołaj mię, a ja tobie odpowiem; albo ja niech mówię, a ty mnie odpowiedz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Wieleż jest nieprawości i grzechów moich? przestępstwo moje, grzech mój pokaż mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Przeczże oblicze twoje zakrywasz, a poczytasz mię sobie za nieprzyjaciela?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Izali skruszysz liść chwiejący się? a źdźbło suche gonić będziesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Albowiem piszesz przeciwko mnie gorzkości, a przywłaszczasz mi nieprawość młodości mojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'I włożyłeś w pęta nogi moje, a podstrzegasz wszystkich ścieżek moich, i na ślad nóg moich następujesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'Choć jako spróchniałe drzewo niszczeję; a jako szata, którą mól psuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Człowiek, narodzony z niewiasty, dni krótkich jest, i pełen kłopotów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'Wyrasta jako kwiat, i bywa podcięty, a ucieka jako cień, i nie ostoi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'Wszakże i na takiego otwierasz oczy twoje, a przywodzisz mię do sądu z sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'Któż pokaże czystego z nieczystego? Ani jeden;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Gdyż zamierzone są dni jego, liczba miesięcy jego u ciebie; zamierzyłeś mu kres, którego nie może przestąpić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'Odstąpże od niego, aż odpocznie, aż przejdzie jako najemniczy dzień jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Albowiem i o drzewie jest nadzieja, choć je wytną, że się jeszcze odmłodzi, a latorośl jego nie ustanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Choć się zstarzeje w ziemi korzeń jego, i w prochu obumrze pień jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'Wszakże gdy uczuje wilgotność, puści się, i rozpuści gałęzie, jako szczep młody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Ale człowiek umiera, zemdlony będąc, a umarłszy człowiek gdzież jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Jako uchodzą wody z morza, a rzeka opada i wysycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'Tak człowiek, gdy się układzie, nie wstanie więcej, a pokąd stoją nieba, nie ocuci się, ani będzie obudzony ze snu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'Obyżeś mię w grobie ukrył i utaił, ażby się uciszył gniew twój, a iżbyś mi zamierzył kres, kędy chcesz wspomnieć na mię!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, 'Gdy umrze człowiek, izali żyć będzie? Po wszystkie dni wymierzonego czasu mego będę oczekiwał przyszłej odmiany mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Zawołasz, a ja tobie odpowiem; a spraw rąk twoich pożądasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Aczkolwiekeś teraz kroki moje obliczył, ani odwłóczysz karania za grzech mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Zapięczętowane jest w wiązance przestępstwo moje, a zgromadzasz nieprawości moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Prawdziwie jako góra padłszy rozsypuje się, a skała przenosi się z miejsca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'Jako woda wzdrąża kamienie, a powodzią zalane bywa, co samo od siebie rośnie z prochu ziemi: tak nadzieję ludzką w niwecz obracasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Przemagasz go ustawicznie, a on schodzi; odmieniasz postać jego, i wypuszczasz go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Będąli zacni synowie jego, tego on nie wie; jeźli też wzgardzeni, on nie baczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Tylko ciało jego, póki żyw, boleje, a dusza jego w nim kwili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'A odpowiadając Elifas Temańczyk rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Izali mądry ma na wiatr mówić? albo napełniać wschodnim wiatrem myśl swoję?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'Przytaczając słowa niepożyteczne, i mowy, z których nie masz pożytku?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Zaiste ty psujesz bojaźń Bożą i znosisz modlitwy do Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Albowiem pokazują nieprawość twą usta twoje, chociażeś sobie obrał język chytrych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Potępiają cię usta twoje, a nie ja; a wargi twoje świadczą przeciwko tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Czyś się najpierwszym człowiekiem urodził? czyś przed pagórkami utworzony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Izażeś tajemnic Bożych słuchał, a nie masz mądrości jedno w tobie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Cóż ty umiesz, czego my nie wiemy? albo cóż ty rozumiesz, czegobyśmy my nie rozumieli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'I sędziwyć i starzec między nami jest starszy w latach niż ojciec twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'I lekceż sobie ważysz pociechy Boskie? i maszże jeszcze co tak skrytego w sobie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Czemuż cię tak uniosło serce twoje? Czemu mrugają oczy twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'Że tak odpowiada Bogu duch twój, a wypuszczasz z ust twoich takowe mowy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Cóż jest człowiek, aby miał być czystym, albo żeby miał być sprawiedliwym, urodzony z niewiasty?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Oto i w świętych jego niemasz doskonałości, i niebiosa nie są czyste w oczach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Daleko więcej obrzydły jest, i nieużyteczny człowiek, który pije nieprawość jako wodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Okażęć, tylko mię słuchaj; a com widział, oznajmięć,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'Co mędrzy powiedzieli, a nie zataili, co mieli od przodków swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'Którym samym dana była ziemia, a żaden obcy nie przeszedł przez nię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Po wszystkie dni swoje sam siebie niepobożny boleśnie trapi, a nie wiele lat zamierzono okrutnikowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Głos straszliwy brzmi w uszach jego, że czasu pokoju pustoszący przypadnie nań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'Nie wierzy, żeby się miał nawrócić z ciemności, obawiając się zewsząd miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Tuła się za chlebem, szukając gdzieby był; wie, że zgotowany jest dla niego dzień ciemności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Straszą go utrapienie i ucisk, i zmocnią się przeciwko niemu jako król gotowy do boju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Bo wyciągną przeciw Bogu rękę swą, a przeciwko Wszechmocnemu zmocnił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'Natrze nań na szyję jego z gęstemi i wyniosłemi tarczami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'Bo okrył twarz swą tłustością swoją, a fałdów mu się naczyniło na słabiźnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'I mieszka w miastach popustoszonych, i w domach, w których nie mieszkano, które się miały obrócić w kupę rumu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'Nie zbogaci się, i nie ostoi się majętność jego, ani się rozszerzy na ziemi doskonałość takowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Nie wynijdzie z ciemności; świeżą jego latorośl ususzy płomień, a zginie od ducha ust jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Nie wierzy, że w próżności jest, który błądzi; a że próżność będzie nagrodą jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Przed wypełnieniem dni swoich wycięty będzie, a różdżka jego nie zakwitnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'Jako winna macica utraci niedojrzałe grona swoje, a jako oliwa kwiat swój zrzuci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Albowiem zgromadzenie obłudnych spustoszone będzie, a ogień pożre przybytki pobudowane za dary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Poczęli kłopot, a porodzili nieprawość; a żywot ich gotuje zdradę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'Ale odpowiedział Ijob, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Słyszałem takowych rzeczy wiele; przykrymi cieszycielami wy wszyscy jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'I kiedyż będzie koniec tym próżnym słowom? albo co cię przymusza, że tak odpowiadasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Azażbym ja tak mówił, jako wy, gdybyście wy byli na miejscu mojem? azażbym zbierał przeciwko wam słowa, i kiwałlibym nad wami głową swoją?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'Owszembym was posilał ustami memi, a ruchanie warg moich ulżyłoby boleści waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Ale jeźli będę mówił, przecież się nie ukoi boleść moja; a jeźli też przestanę, izaż odejdzie odemnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'A teraz zemdlił mię; spustoszyłeś, o Boże! wszystko zgromadzenie moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Pomarszczyłeś mię na świadectwo, a znaczne na mnie schudzenie moje na twarzy mojej, jawnie świadczy przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Popędliwość jego porwała mię, i wziął nienawiść przeciwko mnie; a zgrzytając na mię zębami swemi, jako nieprzyjaciel mój, bystremi oczyma swemi spojrzał na mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Rozdzierają na mię usta swe, i sromotnie mię policzkowali, zebrawszy się społu przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Podał mię Bóg przewrotnemu, a w ręce niepobożnych wydał mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Byłem w pokoju, ale mię potarł; a uchwyciwszy mię za szyję moję, roztrzaskał mię, i wystawił mię sobie za cel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Ogarnęli mię strzelcy jego; rozciął nerki moje, a nie przepuścił, i rozlał na ziemię żółć moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Zranił mię, raną na ranę; rzucił się na mię, jako olbrzym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Uszyłem wór na zsiniałą skórę moję, a oszpeciłem prochem głowę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Twarz moja płaczem oszpecona, a na powiekach moich jest cień śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'Chociaż żadnego łupiestwa niemasz w rękach moich, a modlitwa moja jest czysta. (a jeźli nie tak,)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'O ziemio! nie zakrywajże krwi mojej, a niech nie ma miejsca wołanie moje!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Otoć i teraz w niebie jest świadek mój, jest świadek mój na wysokości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'O krasomówcy moi, przyjaciele moi! wylewa łzy do Boga oko moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'Oby się godziło wieść spór człowiekowi z Bogiem, i jako synowi człowieczemu z bliźnim swym!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Bo lata zamierzone nadchodzą, a ścieszką, którą się nie wrócę, już idą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Dech mój skażony jest; dni moje giną; groby mię czekają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Zaiste naśmiewcy są przy mnie, a w ich draźnieniu mieszka oko moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Staw mi, proszę, rękojmię za się. Któż jest ten? Niech mi na to da rękę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Boś serce ich ukrył przed wyrozumieniem; przetoż ich nie wywyższysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Kto pochlebia przyjaciołom, oczy synów jego ustaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'Wystawił mię zaiste na przypowieść ludziom, i jako śmiechowisko przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'Zaćmione jest dla żałości oko moje, a wszystkie myśli moje są jako cień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Zdumieją się szczerzy nad tem; a niewinny przeciwko obłudnikowi powstanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'Będzie się trzymał sprawiedliwy drogi swojej; a kto ma czyste ręce, przyczyni mocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Wy tedy wszyscy nawróćcie się, a pójdźcie, proszę; bo nie znajduję między wami mądrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Dni moje przeminęły; myśli moje rozerwane są, to jest, zamysły serca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Noc mi się w dzień obraca; a światłość skraca się dla ciemości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Jeźlibym czego oczekiwał, grób będzie domem moim, a w ciemnościach uścielę łoże moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'Do dołu rzekę: Ojcem moim jesteś; a do robaków: Wy jesteście matką moją, i siostrą moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'Bo gdzież teraz jest nadzieja moja? a oczekiwanie moje któż ogląda?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'W głębię grobu zstąpię, ponieważ w prochu spólny odpoczynek wszystkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'A odpowiadając Bildad Suhytczyk rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Dokądże nie uczynicie końca mowom? pomyślcie pierwej, a potem mówić będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Czemuż nas poczytają jako bydło? zdajemy się mu przemierzłymi, jako sami widzicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Ty, który duszę twoję tracisz w zapalczywości twojej, azaż dla ciebie będzie opuszczona ziemia, a będą przeniesione skały z miejsca swego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'Owszem, światłość niepobożnych zgaśnie, i nie będzie świeciła iskra ognia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Światło się zaćmi w przybytku jego, i pochodnia jego nad nim zgaśnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Ściśnione będą kroki siły jego, a porazi go rada jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Bo zawiodą w sieci nogi jego, i w uwikłaniu chodzić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Uchwyci go sidło za piętę jego, i przemoże go łupieżca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Skryty jest w ziemi powróz jego, a samołówka jego na ścieszce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Zewsząd go straszyć będą strachy, a nacierać będą na nogi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Wymorzy się głodem siła jego, a zginienie pogotowiu jest przy boku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Pożre żyły skóry jego, pożre członki jego pierworodny śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Ufanie jego będzie wykorzenione z przybytku jego, a przywiedzie go do króla strachów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Będzie mieszkał strach w przybytku jego, chociaż nie był jego, a siarką będzie potrząśnione mieszkanie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Ze spodku korzeń jego uschnie, a z wierzchu będzie obcięta gałąź jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Pamiątka jego zginie z ziemi, a imienia jego nie wspomną po ulicach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Wypędzą go z światłości do ciemności, a z okręgu świata wyrzucą go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Nie będzie syn ani wnuk między ludem jego, i nikt nie pozostanie w mieszkaniach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Nade dniem jego zdumiewają się potomkowie, a przodków ogarnie strach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Takoweć są mieszkania niezbożnego, i do tego przychodzi temu, który nie zna Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'A odpowiadając Ijob rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Dokądże trapić będziecie duszę moję, a nacierać na mię mowami swemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Już dziesięćkroć zawstydziliście mię, i nie wstydże was, że się tak zatwardzacie przeciwko mnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'A niech tak będzie, żem zbłądził; przy mnie zostanie błąd mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'A jeźli się przeciw mnie wynosicie, a obwiniacie mię pohańbieniem mojem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'Wiedzcież, żeć mię Bóg odwrócił, i siecią swoją obtoczył mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Oto, wołamli o krzywdę, nie bywam wysłuchany; krzyczęli, niemasz sądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Drogę moję zagrodził, żebym przejść nie mógł, a na ścieszce mojej ciemności położył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Z sławy mojej złupił mię, i zdjął koronę z głowy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Popsuł mię zewsząd, abym zaginął, a wyrwał jako drzewo nadzieję moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Nadto zapalił się na mię gniew jego, a policzył mię w poczet nieprzyjaciół swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Przyszły razem hufy jego, i utorowały przeciwko mnie drogę swoję, i obległy w około namiot mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Braci moich odemnie oddalił, a znajomi moi stronią odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Opuścili mię bliscy moi, a znajomi moi zapomnieli mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Komornicy domu mego, i służebnice moje mają mię za obcego, cudzoziemcem stałem się w oczach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Wołamli na sługę mego, nie ozywa mi się, chociaż go proszę ustami memi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Tchem moim brzydzi się żona moja, choć proszę przez synów żywota mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'I najlichsi pogardzają mną, a gdy powstaję, urągają mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Brzydzą się mną wszyscy najwierniejsi moi, a którychem umiłował, stali mi się przeciwnymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Do skóry mojej, jako do ciała mego przyschła kość moja; skóra tylko została około zębów moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Zmiłujcie się nademną, zmiłujcie się nademną, wy przyjaciele moi! bo ręka Boża dotknęła mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Czemuż mię prześladujecie, jako Bóg, a ciała mego nie możecie się nasycić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'Oby teraz napisane były słowa moje! oby je na księgach wyrysowano!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Oby rylcem żelaznym i ołowiem na wieczną pamiątkę na kamieniu wydrążone były!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'Aczci ja wiem, iż Odkupiciel mój żyje, a iż w ostateczny dzień nad prochem stanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'A choć ta skóra moja roztoczona będzie, przecież w ciele mojem oglądam Boga;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'Którego ja sam oglądam, i oczy moje ujrzą go, a nie inny; choć zniszczały nerki moje we wnętrznościach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Przeczże nie mówicie: Czemuż go prześladujemy? gdyż się przy mnie znajduje grunt dobrej sprawy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'Ulęknijcie się sami miecza, bo pomsta nieprawości jest miecz; a wiedzcie, że będzie sąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'A odpowiadając Sofar Naamatczyk rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Do tego mię myśli moje przywodzą, abym odpowiedział; przetożem się pospieszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Słyszałem mnie hańbiącą naganę; ale duch wyrozumienia mego odpowie za mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Izaż nie wiesz, że to jest od wieku, od tego czasu, jako postawił Bóg człowieka na ziemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'Iż chwała niepobożnych krótka jest, a wesele obłudnika na mgnienie oka?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'By też wstąpiła aż do nieba hardość jego, a obłoku się dotknęła głowa jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'A wszakże na wieki zginie jako gnój jego, a ci, którzy go widzieli, rzeką: Gdzież się podział?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Uleci jako sen, a nie znajdą go; bo uciecze, jako widzenie nocne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Oko, które go widziało, nie ogląda go więcej, i nie ujrzy go więcej miejsce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Synowie jego będą się korzyć ubogim; bo ręce jego muszą wracać, co wydarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Kości jego napełnione są grzechami młodości jego, a w prochu z nim leżeć będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'A choć złość słodnieje w ustach jego, i tai ją pod językiem swoim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'Kocha się w niej, a nie opuszcza jej, zatrzymywając ją w pośrodku podniebienia swego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'Wszakże pokarm jego we wnętrznościach jego odmieni się; żółcią padalcową stanie się w trzewach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Bogactwa, które pożarł, zwróci, a z brzucha jego wyżenie je Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Głowę padalcową ssać będzie; zabije go język jaszczurczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Nie ogląda źródeł rzek, strumieni mówię miodu i masła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Wróci pracę cudzą, a nie zażyje jej; i choć znowu nabędzie wielkich majętności, nie ucieszy się niemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Bo ubogich dręczył i opuszczał, złupił dom, którego nie budował; przetoż nic spokojnego nie poczuje w żywocie swoim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Ani rzeczy swych wdzięcznych nie będzie mógł zatrzymać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Nic nie zostanie z pokarmów jego, ani się rozmnoży dobro jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Choćby i nazbyt miał wszystkiego, ściśniony będzie; wszelka ręka trapiących oburzy się nań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Choć będzie miał czem napełnić brzuch swój, przecież nań Bóg puści popędliwość gniewu swego, którą jako deszcz spuści nań, i na pokarmy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Gdy uciekać będzie przed bronią żelazną, przebije go łuk hartowny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Wyjęta będzie strzała z sajdaku wypuszczona, a grot przeniknie żółć jego; a gdy uchodzić będzie, ogarną go strachy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Wszystkie nieszczęścia zasadziły się nań w tajemnych miejscach jego, a pożre go ogień nierozdymany: pozostały w przybytku jego utrapiony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Odkryją niebiosa złość jego, a ziemia powstanie przeciwko niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Przeniesie się urodzaj domu jego; dobra jego rozpłyną się w dzień gniewu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'Tenci jest dział człowieka niepobożnego od Boga, to dziedzictwo naznaczone mu od Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'A odpowiadając Ijob rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Słuchajcież z pilnością słów moich, a będzie mi to od was pociechą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Znoście mię, a ja będę mówił; a gdy domówię, naśmiewajcie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Izaż do człowieka obracam narzekanie moje? a ponieważ mam o co, jakoż się niema trapić duch mój?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Wejrzyjcież na mię, a zdumiewajcie się, a połóżcie rękę na usta wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Bo co sobie wspomnę, tedy się lękam, a strach zdejmuje ciało moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Przeczże niepobożni żyją, starzeją się, i wzmagają się w bogactwa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Nasienie ich trwałe jest przed obliczem ich z nimi, a rodzina ich przed oczyma ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Domy ich bezpieczne od strachu, a niemasz rózgi Bożej nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Byk ich przypuszczon bywa, a nie traci nasienia; krowa ich rodzi, a nie pomiata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Wypuszczają maluczkie dziatki swoje jako trzodę, a synowie ich wyskakują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Wykrzykają przy bębnie i przy harfie, a weselą się przy głosie muzyki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'Trawią w dobrem dni swoje, a we mgnieniu oka do grobu zstępują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'Którzy mawiają Bogu: Odejdź od nas; bo dróg twoich znać nie chcemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Któż jest Wszechmocny, abyśmy mu służyli? a cóż nam to pomoże, choćbyśmy mu się modlili?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Ale oto, dobra ich nie są w rękach ich; przetoż rada niepobożnych daleka jest odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Częstoż pochodnia niepobożnych gaśnie? a zginienie ich przychodzi na nich? Oddziela im Bóg boleści w gniewie swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'Stawają się jako plewa przed wiatrem, i jako perz, który wicher porywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Bo Bóg chowa synom jego pomstę jego; nadgradza mu, aby to poczuł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'Oglądają oczy jego nieszczęście swoje, a z popędliwości Wszechmocnego pić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Co za staranie jego o domu jego po nim, gdyż liczba miesięcy jego umniejszona jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'Izali Boga kto nauczy umiejętności, gdyż on wysokich sądzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Ten umiera w doskonałej sile swojej, gdy zewsząd bezpieczny i spokojny jest;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'Gdy piersi jego pełne są mleka, a szpik kości jego odwilża się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Inny zaś umiera w gorzkości ducha, który nie jadał z uciechą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Spólnie w prochu leżeć będą, a robaki ich okryją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Oto ja znam myśli wasze i zamysły, które przeciwko mnie złośliwie zmyślacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Bo mówicie: Gdzież jest dom książęcy? gdzie namiot przybytków niepobożnych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Izaliście nie pytali podróżnych? a znaków ich izali znać nie chcecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'Że w dzień zatracenia zły zachowany bywa, w dzień, którego gniew przywiedziony bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Któż mu oznajmi w oczy drogę jego? a to, co czynił, kto mu odpłaci?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Wszakże i on do grobów zaprowadzony będzie, a w kupie umarłych zawżdy zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Słodnieją mu bryły grobowe, i ciągnie za sobą wszystkich ludzi; a tych, którzy go poprzedzili, niemasz liczby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Jakoż mię tedy próżno cieszycie, gdyż w odpowiedziach waszych zostaje kłamstwo?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'A odpowiadając Elifas Temańczyk rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'Izali Bogu człowiek może być pożytecznym? raczej pożyteczny jest sam sobie, mądrze się sprawując.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Izali się kocha Wszechmogący w tem, że się ty usprawiedliwiasz? albo co za zysk ma, gdy doskonałe pokazujesz drogi twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Aza cię będzie karał bojąc się ciebie? albo z tobą pójdzie do sądu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Azaż złość twoja nie jest wielka, i niemasz końca nieprawościom twoim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Albowiemeś pobierał zastaw od braci twoich bez przyczyny, a z szat odzierałeś nagich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Wodyś spracowanemu nie podał, a głodnemu odmówiłeś chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'Ale człowiekowi możnemu dałeś ziemię, a ten, który był w powadze, mieszkał w niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Wdowy puszczałeś próżne, a sierót ramiona potarłeś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'A przetoż ogarnęły cię sidła, a trwoży cię strach nagły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Albo cię ogarnęły ciemności, iż nie widzisz? a wielkości wód okryły cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Mówisz: Izali Bóg nie jest na wysokości niebios? Spojrzyj proszę na wierzch gwiazd, jako są wysokie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'Przetoż mówisz: A cóż wie Bóg? izaż przez chmury sądzić będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Obłoki są skrytością jego, iż nie widzi, a po okręgu niebieskim przechadza się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Izaż ścieszki wieku przeszłego nie baczysz, którą deptali ludzie złośliwi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'Którzy są wykorzenieni przed czasem, a powodzią zalały się grunty ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'Którzy mawiali Bogu: Odejdź od nas; cóżby im uczynił Wszechmogący?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'Gdyż on był napełnił dobrem domy ich; (ale rada niepobożnych daleka jest odemnie.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Co widząc sprawiedliwi, weselili się, a niewinny naśmiewał się z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'Zwłaszcza, iż nie była wycięta majętność nasza, lecz ostatki ich ogień pożarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Przyuczaj się, proszę, z nim przestawać, a uczyń sobie z nim pokój: boć się tak będzie szczęściło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Przyjmij, proszę, z ust jego zakon, a złóż wyroki jego w sercu twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Jeźli się nawrócisz do Wszechmocnego, zbudowany będziesz, a oddalisz nieprawość od przybytku twego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'Tedy nakładziesz po ziemi wybornego złota; a złota z Ofir, jako kamienia z potoku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'I będzie Wszechmocny wybornem złotem twojem, i srebrem, i siłą twoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Tedy się w Wszechmocnym rozkochasz, a podniesiesz ku Bogu oblicze twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Będziesz mu się modlił, a wysłucha cię, i śluby twoje oddasz mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Bo cokolwiek postanowisz, będzieć się darzyło, a na drogach twoich rozjaśni się światłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Gdy inni zniżeni będą, ty rzeczesz: Jam jest wywyższon; bo tego, co jest uniżonych oczów, Bóg zbawia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Wybawi i tego, który nie jest niewinny, i wybawion będzie w czystości rąk twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'A odpowiadając Ijob rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Czemuż jeszcze uporem zowiecie narzekanie moje, choć bieda moja cięższa jest niż wzdychanie moje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'Obym wiedział, gdziebym go mógł znaleść, szedłbym aż do stolicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Przełożyłbym przed nim sprawę moję, a usta moje napełniłbym dowodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Dowiedziałbym się, jakoby mi odpowiedział, a zrozumiałbym, coby mi rzekł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Izaż się w wielkości siły swojej będzie spierał ze mną? Nie; i owszem sam mi doda siły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Tamby się człowiek szczery rozprawił z nim, i byłbym wolnym wiecznie od sędziego mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Ale oto, pójdęli wprost, niemasz go; a jeźli nazad, nie dojdę go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'Pójdęli w lewo, choćby zatrudniony był, nie oglądam go; ukryłliby się w prawo, nie ujrzę go,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Gdyż on zna drogę moję; a będzieli mię doświadczał, jako złoto wynijdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Śladu jego trzymała się noga moja; drogim jego przestrzegał, a nie zstępowałem z niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'Od przykazania ust jego nie odchylałem się; owszem, postanowiłem u siebie zachować słowa ust jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Jeźli on przy swem stanie, któż go odwróci? bo co dusza jego żąda, to uczyni:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Bo on wykona, co postanowił o mnie, a takowych przykładów dosyć jest u niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Przetoż od oblicza jego strwożyłem się, a uważając to, lękam się go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Bóg zemdlił serce moje, a Wszechmocny zatrwożył mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Tak, żem mało nie zginął od ciemności; bo przed oblicznością moją nie zakrył zamroczenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Czemuż od Wszechmocnego nie są zakryte czasy? a którzy go znają, nie widzą dni jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Niezbożni granice przenoszą, trzody zabierają i pasą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Osła sierotek zajmują, a wołu od wdowy w zastawie biorą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Spychają ubogich z drogi; spólnie się muszą nędzni kryć na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Oto jako leśne osły w puszczach wychodzą na robotę swoję, wstawając rano na łupiestwo; pustynia jest chlebem ich, i dzieci ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Na polu ubogiego pożynają zboże, a niepobożni z winnic zbierają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Nagich nocować przymuszają bez odzienia, którzy się nie mają czem nakryć na zimnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Powodzią gór zmaczani bywają, nie mając mieszkania przytulają się do skały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Porywają sierotkę od piersi, a od ubogiego biorą zastaw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Nagiemu dopuszczają chodzić bez odzienia, a o głodzie chowają tych, którzy ich snopy noszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'A ci, którzy między murami ich wyciskają oliwę i prasy tłoczą, pragną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Ludzie w mieście wzdychają, a dusze zabitych wołają, a Bóg temu wstrętu nie czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Cić to są, którzy się sprzeciwiają światłości, a nie znają dróg jej, ani stanęli na ścieszkach jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Raniuczko wstaje mężobójca, zabija ubogiego i niedostatecznego, a w nocy jest jako złodziej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'Oko cudzołożnika pilnuje zmierzku, mówiąc: Nie ujrzy mię nikt; i zakrywa oblicze swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'Podkopywają w ciemności domy, które sobie naznaczyli, i nienawidzą światła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Ale zaranek jest im jako cień śmierci; jeźli ich kto pozna, przypada na nich strach cienia śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Lekkimi są na wodach; przeklęty dział ich na ziemi; nie patrzą na drogę wolną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Jako susza i gorącość trawią wody śnieżne, tak grób grzeszników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Zapomina go żywot matki jego, a robak słodkość z niego czuje; niemasz więcej pamiątki jego, a nieprawość połamana jest jako drzewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'Roztrąca niepłodną, która nierodziła, a wdowie nie czyni dobrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Pociąga też mocarzy możnością swoją: a gdy na nich powstał, zwątpili o żywocie swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Daje mu Bóg, na czemby bezpiecznie spolegać mógł: wszakże oczy jego patrzą na drogi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Na chwilę wywyższeni są, alić ich niemasz; zniżeni i ściśnieni będą jako inni wszyscy, a jako wierzch kłosa ścięci będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'A jeźli nie tak jest, gdzież jest ten, coby mi zadał kłamstwo, a coby obrócił wniwecz słowa moje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'A odpowiadając Bildad Suhytczyk rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Panowanie i strach jest przy nim; on czyni pokój na wysokościach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Izali jest liczba wojskom jego? a nad kim nie wschodzi światłość jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Jakoż tedy nędzny człowiek usprawiedliwiony być może przed Bogiem? albo jako może być czysty urodzony z niewiasty?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Oto i miesiącby nie świecił i gwiazdyby nie były czyste w oczach jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'Jakoż daleko mniej człowiek, który jest robakiem, a syn człowieczy, który jest czerwiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'A Ijob odpowiadając rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Jakożeś ratował tego, który nie ma mocy? a jakoś wybawił ramię, które nie ma siły?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'Jakążeś dał radę temu, co nie ma mądrości? Azaś go samej rzeczy gruntownie nie wyuczył?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Komużeś powiedział te słowa? Czyjże duch wyszedł od ciebie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'I martwe rzeczy rodzą się pod wodami, i obywatele ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Odkryte są przepaści przed nim, a nie ma przykrycia zatracenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'Rozciągnął północy nad miejscem próżnem, a ziemię zawiesił na niczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Zawiązuje wody na obłokach swoich, a nie rwie się obłok pod nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Zatrzymuje stolicę swoję, rozpostarłszy nad nią obłok swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Położył granice wodom, aż weźmie koniec światłość i ciemność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Słupy niebieskie trzęsą się, i chwieją się na gromienie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Mocą swą dzieli morze, a roztropnością swą uśmierza nawałności jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Duchem swym niebiosa przyozdobił, a ręka jego stworzyła węża skrętnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Oto teć są tylko części dróg jego, lecz i ta trocha niewybadana, cośmy słyszeli o nim, a grzmot wielkiej możności jego któż zrozumie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'Potem dalej Ijob prowadził rzecz swoję, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Jako żyje Bóg, który odrzucił sąd mój, a Wszechmocny, który gorzkości nabawił duszy mojej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, 'Że póki staje tchu we mnie, i ducha Bożego w nozdrzach moich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'Nie będą mówiły wargi moje nieprawości, a język mój nie będzie powiadał zdrady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Nie daj Boże, żebym was miał usprawiedliwiać; póki dech we mnie, nie odstąpię od niewinności mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Sprawiedliwości mojej trzymać się będę, a nie puszczę się jej; nie zawstydzi mię serce moje, pókim żyw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Nieprzyjaciel mój będzie jako niezbożnik, a który powstaje przeciwko mnie, jako złośnik.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Co bowiem za nadzieja jest obłudnika, który się w łakomstwie kocha, gdy Bóg wydrze duszę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Izali Bóg usłyszy wołanie jego, gdy nań ucisk przyjdzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'Izaż się w Wszechmocnym rozkocha? a będzie wzywał Boga na każdy czas?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Uczę was, będąc w ręce Bożej, a jako idę z Wszechmocnym, nie taję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Oto wy to wszyscy widzicie; przeczże wżdy próżność mówicie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'Tenci jest dział człowieka bezbożnego u Boga, a toć dziedzictwo okrutnicy od Wszechmocnego wezmą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Jeźli się rozmnożą synowie jego, pójdą pod miecz: a potomstwo jego nie nasyci się chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Którzy po nim zostaną w śmierci pogrzebieni będą, a wdowy jego nie będą go płakały;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Choćby srebra nazgromadzał jako prochu, a nasprawiał szat jako błota:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'Tedy nasprawiać ich on, ale sprawiedliwy oblekać je będzie, a srebro ono niewinny dzielić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Zbuduje dom swój jako mól, a jako stróż budę wystawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Bogaty zaśnie, a nie będzie pogrzebiony; spojrzyli kto, alić go niemasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Zachwycą go strachy jako wody, w nocy go porwie wicher.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Pochwyci go wiatr wschodni, a odejdzie; bo wicher ruszył go z miejsca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'Toć Bóg nań dopuści, a nie przepuści mu, choć przed ręką jego prędko uciekać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Klaśnie każdy nad nim rękoma swemi, i wysyka go z miejsca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Mać w prawdzie srebro początki żył swoich, a złoto miejsce, kędy bywa pławione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Żelazo z ziemi biorą, a z kamienia zlewają miedź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Celu ciemnościom ułożonego i końca wszystkich rzeczy on dochodzi, i kamieni, które w ciemności i cieniu śmierci leżą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Wyleje rzeka z miejsca swojego, tak, iż jej nikt przebyć nie może, bywa jednak zahamowana przemysłem nędznego człowieka, i odchodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Z ziemi wychodzi chleb, chociaż pod nią coś różnego, podobnego ogniowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'W niektórych miejscach jest kamień Safir, i piasek złoty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'A tej ścieszki ani ptak nie wie, ani jej widzało oko sępie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'Nie depczą po niej zwierzęta srogie, ani lew przeszedł przez nię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Na krzemień ściągnął rękę swoję, wywrócił góry z korzenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'Z skał wywodzi strumienie, a każdą rzecz kosztowną widzi oko jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Wylewać się rzekom nie dopuszcza, a rzeczy skryte wywodzi na jaśnię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Ale mądrość gdzież może być znaleziona? a kędy jest miejsce roztropności?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Nie wie człowiek śmiertelny ceny jej, ani bywa znaleziona w ziemi żyjących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Przepaść mówi: Niemasz jej we mnie; i morze też powiada: Niemasz jej u mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Nie dawają szczerego złota za nię; ani odważają srebra, za odmianę jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Nie może być oszacowana za złoto Ofir, ani za Onychyn drogi, ani za Safir.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Nie porówna z nią złoto, ani kryształ, ani odmiana jej może być za klejnot złota szczerego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Koralów i pereł nie wspomina, bo nabycie mądrości kosztowniejsze jest nad perły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Nie zrówna z nią i szmaragd z ziemi etyjopskiej; ani za złoto najczystsze szacowana być może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Skądże tedy mądrość pochodzi? albo gdzie jest miejsce rozumu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Gdyż zakryta jest od oczu wszystkich żyjących, i przed ptastwem niebieskim zatajona jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Zginienie i śmierć rzekły: Uszyma swemi słyszałyśmy sławę jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Bóg sam rozumie drogę jej, a on wie miejsce jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Bo on na kończyny ziemi patrzy, a wszystko, co jest pod niebem, widzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Wiatrom uczynił wagę, a wody odważył pod miarą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'On też prawo dżdżom postanowił, a drogę błyskawicom gromów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'W ten czas ją widział, i głosił ją: zgotował ją, i doszedł jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'Ale człowiekowi rzekł: Oto bojaźń Pańska jest mądrością, a warować się złego, jest rozumem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'Jeszcze dalej Ijob prowadził rzecz swoję, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'Któż mi to da, abym był jako za miesięcy dawnych, za dni onych, których mię Bóg strzegł;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'Gdy pochodnia jego świeciła nad głową moją, a przy świetle jego przechodziłem ciemności;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'Jakom był za dni młodości mojej, gdy była przytomność Boża nad przybytkiem moim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'Gdy jeszcze Wszechmocny był ze mną, a około mnie dziatki moje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'Gdy ścieszki moje opływały masłem, a opoka wylewała mi źródła oliwy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Gdym wychodził do bramy przez miasto, a na ulicy kazałem sobie gotować stolicę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'Widząc mię młodzi ukrywali się, a starcy powstawszy stali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'Przełożeni przestawali mówić, a ręką zatykali usta swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'Głos książąt ucichał, a język ich do podniebienia ich przylegał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Bo ucho słuchające błogosławiło mię, a oko widzące dawało o mnie świadectwo,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Żem wybawiał ubogiego wołającego, i sierotkę, i tego, który nie miał pomocnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Błogosławieństwo ginącego przychodziło na mię, a serce wdowy rozweselałem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'W sprawiedliwość obłoczyłem się, a ona zdobiła mię; sąd mój był jako płaszcz i korona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Byłem okiem ślepemu, a nogą chromemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Byłem ojcem ubogich, a sprawy, którejm nie wiedział, wywiadywałem się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'I kruszyłem szczęki złośnika, a z zębów jego wydzierałem łup.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Przetożem rzekł: W gniaździe swojem umrę, a jako piasek rozmnożę dni moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Korzeń mój rozłoży się przy wodach, a rosa trwać będzie przez noc na gałązkach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'Chwała moja odmłodzi się przy mnie, a łuk mój w ręce mojej odnowi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Słuchano mię, i oczekiwano na mię, a milczano na radę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Po słowie mojem nie powtarzano, tak na nich kropiła mowa moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Bo mię oczekiwali jako deszczu, a usta swe otwierali jako na deszcz późny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Jeźlim żartował z nimi, nie wierzyli, a powagi twarzy mojej nie odrzucali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Jeźlim kiedy do nich przyszedł, siadałem na przedniejszem miejscu, i mieszkałem jako król w wojsku, a jako ten, który smutnych cieszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Ale teraz śmieją się ze mnie młodsi nad mię w latach, których ojcówbym ja był nie chciał położyć ze psami trzody mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Acz na cóżby mi się była siła rąk ich przydała? bo przy nich starość ich zginęła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Albowiem dla niedostatku i głodu samotni byli, i uciekali na niepłodne, ciemne, osobne, i puste miejsce;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Którzy sobie rwali chwasty po chróstach, a korzonki jałowcowe były pokarmem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Z pośrodku ludzi wyganiano ich; wołano za nimi jako za złodziejem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Tak, iż w łożyskach potoków mieszkać musieli, w jamach podziemnych i w skałach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Między chróstami ryczeli, pod pokrzywy zgromadzali się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'Synowie ludzi wzgardzonych, i synowie ludzi bezecnych, podlejsi byli nad proch ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'Alem teraz pieśnią ich, i stałem się im przypowieścią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Brzydzą się mną, a oddalają się odemnie, i na twarz moję plwać się nie wstydzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Bo Bóg powagę moję odjął i utrapił mię; dlatego oni wędzidło przed twarzą moją odrzucili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Po prawicy mojej młodzikowie powstawają, nogi moje potrącają, i torują na przeciwko mnie drogi zginienia swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Popsuli ścieszkę moję, i nędzy do nędzy mojej przyczynili, a nie potrzebują do tego pomocnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Jako przerwą szeroką napadają na mię, i na spustoszenie moje walą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Obróciły się przeciwko mnie strachy, jako wiatr ściągają duszę moję; bo jako obłok przemija zdrowie moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'A teraz we mnie rozlała się dusza moja; ogarnęły mię dni utrapienia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Które w nocy wiercą kości moje we mnie, skąd żyły moje nie mają odpoczynku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Dla wielkiej boleści zmieniła się szata moja, a jako kołnierz sukni mojej ściska mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Wrzucił mię w błoto, a jestem podobien prochowi i popiołowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Wołam do ciebie, a nie wysłuchujesz mię; stoję przed tobą, a nie patrzysz na mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Odmieniłeś mi się w okrutnego, a mocą ręki twej sprzeciwiasz mi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Podnosisz mię na wiatr, i wsadzasz mię nań, a zdrowemu rozsądkowi rozpłynąć się dopuszczasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Wiemci, że mię na śmierć podasz, i do domu wszystkim żyjącym naznaczonego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Wszakże na grób nie ściągnie ręki swej, a gdy ich niszczyć będzie, wołać nie będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Izalim nie płakał nad dniem utrapionego? izali się nie smuciła dusza moja nad ubogim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Gdym dobrego oczekiwał, oto przyszło złe; a gdym się spodziewał światłości, przyszła ciemność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Wnętrzności moje wezwrzały, a nie uspokoiły się, i ubieżały mię dni utrapienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Chodzę szczerniawszy, ale nie od słońca; powstaję i wołam w zgromadzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Stałem się bratem smoków, a towarzyszem strusiów młodych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Skóra moja poczerniała na mnie, i kości moje wypiekły się od upalenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'Obróciła się w lament harfa moja, a instrument mój w głos płaczących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Uczyniłem przymierze z oczyma swemi, abym nie pomyślał o pannie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'Bo cóż za dział od Boga z góry? a co za dziedzictwo Wszechmocnego z wysokości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Azaż nie nagotowane zginienie złośnikom, a sroga pomsta czyniącym nieprawość?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Azaż on nie widzi dróg moich, a wszystkich kroków moich nie liczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Jeźlim chodził w kłamstwie, a spieszyła się na zdradę noga moja:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, 'Niech mię zważy na wadze sprawiedliwej, a niech Bóg pozna szczerość moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'Jeźliż ustąpiła noga moja z drogi, a za oczyma memi szłoli serce moje, i do rąk moich jeźliż przylgnęła jaka zmaza:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'Tedy niechże ja sieję, a inszy niech pożywa, a moje latorośle niech będą wykorzenione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Jeźli zwiedzione jest serce moje do niewiasty, i jeźlim czyhał u drzwi przyjaciela mego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'Niechajże mele innemu żona moja, a niechaj się nad nią inni schylają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Boć to jest sprosny występek, a nieprawość osądzenia godna,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Gdyż ten ogień aż do zatracenia pożera, a dochody moje wszystkie wykorzenić może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Jeźlim stronił od sądu z sługą moim, albo z służebnicą moją, gdy ze mną sprzeczkę mieli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, '(Bo cóżbym czynił, gdyby powstał Bóg? albo gdyby pytał, cobym mu odpowiedział?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Izaż nie ten, który mię w żywocie uczynił, nie uczynił też i onego? a nie onże nas sam w żywocie wykształtował?)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Jeźliżem odmówił ubogim, czego chcieli, a oczy wdowy jeźliżem zasmucił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'Jeźliżem jadł sztuczkę swoję sam, a nie jadała i sierota z niej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, '(Albowiem sierota z młodości mojej rosła ze mną, jako u ojca; a jakom wyszedł z żywota matki mojej, byłem wdowie za wodza.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'Jeźliżem widział kogo ginącego dla tego, że szaty nie miał, a nie dałem żebrakowi odzienia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'Jeźliże mi nie błogosławiły biodra jego, że się wełną owiec moich zagrzał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'Jeźliżem podniósł przeciwko sierocie rękę swoję, gdym widział w bramie pomoc moję:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'Tedy niech odpadnie łopatka moja od plec swych, a ramię moje z stawu swego niech wytracone będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Albowiem lękałem się skruszenia od Boga, a przed jego zacnością nie mógłbym się ostać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Jeźlim pokładał w złocie nadzieję moję, a do bryły złota mawiałem: Tyś ufanie moje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'Jeźlim się weselił z wielu bogactw moich, a iż wiele nabyła ręka moja;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'Jeźlim patrzał na światłość słońca, gdy świeciło, a na miesiąc, gdy wspaniało chodził;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'I dało się uwieść potajemnie serce moje, a całowały rękę moję usta moje:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'I toćby była nieprawość osądzenia godna; bobym się tem zaprzał Boga z wysokości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Jeźliżem się weselił z upadku nienawidzącego mię, a jeźlim się cieszył, gdy mu się źle powodziło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, '(I owszem nie dałem zgrzeszyć ustom moim, abym miał żądać przeklęstwa duszy jego.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'Azaż nie mawiali domownicy moi: Oby nam kto dał mięsa tego, nie możemy się i najeść?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'Bo gość nie nocował na dworze, a drzwi moje otwierałem podróżnemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'Jeźlim zakrywał, jako ludzie zwykli, przestępstwa moje, i chowałem w skrytości mojej nieprawość moję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'I choćbym był mógł potłumić zgraję wielką, jednak i najpodlejszy z domu ustraszył mię; przetożem milczał, i nie wychodziłem ze drzwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'Obym miał kogo, coby mię wysłuchał; ale oto ten jest znak mój, że Wszechmogący sam odpowie za mię, i księga, którą napisał przeciwnik mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Czylibym jej na ramieniu swojem nie nosił? a nie przywiązałbym jej sobie miasto korony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Liczbę kroków moich oznajmiłbym mu; jako do książęcia przystąpiłbym do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Jeźliż przeciw mnie ziemia moja wołała, a jeźliże z nią społem zagony jej płakały;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'Jeźliżem pożytków jej używał bez pieniędzy, i jeźlim do wzdychania przywodził dzierżawców jej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'Miasto pszenicy niech wznijdzie oset, a miasto jęczmienia kąkol. Tu się skończyły słowa Ijobowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'A gdy przestali oni trzej mężowie odpowiadać Ijobowi, przeto, że się sobie zdał być sprawiedliwym:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Tedy się rozpalił gniewem Elihu, syn Barachela Buzytczyka z rodu Syryjskiego, przeciw Ijobowi się rozpalił gniewem, iż usprawiedliwiał duszę swoję, więcej niż Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Także przeciwko trzem przyjaciołom jego rozpalił się gniew jego, że nie znalazłszy odpowiedzi, przecię potępiali Ijoba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Bo Elihu oczekiwał, jako oni Ijobowi odpowiedzą, gdyż oni starsi byli w latach niż on.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'Ale widząc Elihu, że nie było odpowiedzi w ustach onych trzech mężów, rozpalił się w gniewie swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'I odpowiedział Elihu, syn Barachela Buzytczyka, i rzekł: Jam najmłodszy w latach, a wyście starcy; przetoż wstydziłem się, i nie śmiałem wam oznajmić zdania swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Myślałem: Długi wiek mówić będzie, a mnóstwo lat nauczy mądrości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Aleć duch, który jest w ludziach, i natchnienie Wszechmogącego daje rozum.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Zacni nie zawsze mądrzy, a starcy nie zawżdy rozumieją sądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Przetoż mówię: słuchaj mię; ja też oznajmię zdanie swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Otom oczekiwał słów waszych, a przysłuchiwałem się dowodom waszym, czekając, ażbyście doszli rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'I przypatrywałem się wam, a oto żaden z was Ijoba przekonać nie mógł; i nie masz między wami, ktoby odpowiedział słowom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Ale snać rzeczecie: Znaleźliśmy mądrość; sam go Bóg przekonywa, nie człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Aczci się Ijob nie zemną wdał w rzecz, a ja mu też nie waszemi słowy odpowiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Polękali się, nie odpowiadają dalej; niedostaje im słów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'Czekałemci, ale nie mówią; umilknęli, a nic więcej nie odpowiadają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Odpowiem ja też z mej strony; oznajmię ja też zdanie swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Bom pełen słów; ciasno we mnie duchowi żywota mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Oto żywot mój jest jako moszcz bez oddechu, a jako beczka nowa rozpękłby się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Będę tedy mówił, a wytchnę sobie; otworzę wargi swe, i odpowiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Nie będę teraz miał względu na żadną osobę, a z człowiekiem bez tytułów mówić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Bo nie umiem tytułować, by mię w rychle nie porwał stworzyciel mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'A przetoż, Ijobie! słuchaj proszę mów moich, a wszystkie słowa moje przyjmij w uszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Oto teraz otworzę usta moje, a język mój będzie mówił w podniebieniu mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Szczerością serca mego będą słowa moje, a czyste zdania wargi moje mówić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Duch Boży uczynił mię, a tchnienie Wszechmocnego ożywiło mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Możeszli, odpowiedz mi; sporządź się, a stań przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Oto ja według słów twoich odpowiem ci za Boga, chociażem ja też z błota utworzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Oto strach mój nie zatrwoży cię, a ręka moja nie obciąży cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'A wszakżeś rzekł w uszy moje, i słyszałem głos słów moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Czystym ja bez przestępstwa; niewinnym ja, i nie masz we mnie nieprawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Oto znajduje Bóg przyczyny przeciwko mnie, a poczytuje mię za nieprzyjaciela swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Podaje w okowy nogi moje, a podstrzega wszystkich ścieżek moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Otości na to tak odpowiadam: W tem nie jesteś sprawiedliwy; bo większy jest Bóg, niż człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Przeczże się z nim spierasz, żeć wszystkich spraw swoich nie objawia?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Wszak Bóg mówi i raz i drugi, a człowiek tego nie uważa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'We śnie w widzeniu nocnem, gdy twardy sen przypada na ludzie gdy śpią na łożu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'Tedy otwiera ucho ludzkie, a to, czem ich ćwiczy, pieczętuje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'Aby człowieka odwiódł od złej sprawy jego, i pychę od męża aby odjął;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'Aby zahamował duszę jego od dołu, a żywot jego aby na miecz nie trafił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Każe go też boleścią na łożu jego, a we wszystkich kościach jego ciężką niemocą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'Tak, że sobie żywot jego chleb obrzydzi, a dusza jego pokarm wdzięczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Zniszczeje znacznie ciało jego, i wysadzą się kości jego, których nie widać było;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'I przybliża się do grobu dusza jego a żywot jego do rzeczy śmierć przynoszących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Jeźli będzie u niego jaki Anioł wymowny, jeden z tysiąca, aby opowiedział człowiekowi powinność jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'Tedy się nad nim Bóg zmiłuje, a rzecze: Wybaw go, aby nie zstępował do grobu, bom znalazł ubłaganie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'I odmłodnieje ciało jego jako dziecięce, a nawróci się do dni młodości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Będzie się modlił Bogu, i przyjmie go łaskawie, i ogląda z weselem oblicze jego, i przywróci człowiekowi sprawiedliwość jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Który poglądając na ludzi, rzecze: Zgrzeszyłem był, i co było prawego, podwróciłem; ale mi to nie było pożyteczno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Lecz Bóg wybawił duszę moję, aby nie zstąpiła do dołu, a żywot mój aby oglądał światłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Oto wszystko to czyni Bóg po dwakroć i po trzykroć z człowiekiem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'Aby odwrócił duszę jego od dołu, a żeby oświecon był światłością żyjących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Uważaj to, Ijobie, słuchaj mię; milcz, a ja będę mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Wszakże maszli co mówić, a odpowiedzże mi; mów, bobym cię rad usprawiedliwił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'A jeźli niemasz, słuchajże mię, a nauczę cię mądrości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Nadto mówił Elihu, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Słuchajcież, mądrzy! mów moich, a nauczeni posłuchajcie mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Bo ucho słów doświadcza, jako podniebienie smakuje pokarmu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Obierzmy sobie sąd, a rozeznajmy między sobą, co jest dobrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Ponieważ Ijob rzekł: Jestem sprawiedliwym, a Bóg odrzucił sprawę moję:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'I mamże kłamać, mając sprawiedliwą? Bolesny jest postrzał mój bez przewinienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Któryż jest mąż taki, jako Ijob, coby pił pośmiewisko jako wodę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'A coby chodził w towarzystwie czyniących nieprawość; i przestawałby z ludźmi niepobożnymi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Bo powiedział: Nie pomoże człowiekowi, choćby się podobał Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Przetoż mię słuchajcie, mężowie rozumni! Niech będzie daleka niepobożność od Boga, i nieprawość od Wszechmocnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Bo on według uczynku płaci człowiekowi, a według drogi jego każdemu nagradza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'A zgoła Bóg przewrotnie nie czyni, a Wszechmocny nie podwraca sądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Któż go przełożył nad ziemią? a kto wystawił cały okrąg świata?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Jeźliby obrócił przeciwko niemu serce swoje, a ducha jego, i dech jego do siebie wziął:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'Zginęłoby wszelkie ciało społu, a człowiekby się do prochu nawrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Maszli tedy rozum, słuchaj tego, a przyjmuj w uszy swe głos mowy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'Azaż ten, który ma w nienawiści sąd, panować może? azaż tego, który jest wielce sprawiedliwy, niepobożnym uczynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Zaż potępisz tego, który może rzec królowi: O bezecny! a książętom: O niepobożny!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Który nie ma względu na osoby książąt, i nie waży sobie więcej bogacza nad ubogiego; bo oni wszyscy są czynem rąk jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'Nagle umierają; a o północy wzruszony bywa naród, i przemija, a mocarz zniesiony bywa bez ręki ludzkiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Oczy bowiem jego nad drogami człowieczemi, a on widzi wszystkie kroki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Niemasz ciemności, ani cienia śmierci, kędyby się skryli ci, którzy czynią nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Bo na nikogo nie wkłada więcej, tak, żeby miał wchodzić w sąd z Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'Pociera bardzo wiele mocarzów, a inszych miasto nich wystawia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Przeto, iż zna sprawy ich, obraca im dzień w noc, aby byli potarci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Poraża ich jako niepobożnych na miejscu jawnem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'Przeto, iż odstąpili od niego, a żadnych dróg jego zrozumieć nie chcieli:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'Aby przywiódł na nich wołanie znędzniałych, a pokazał, że wysłuchuje wołanie ubogich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Gdy on sprawi pokój, któż go wzruszy? także, gdy skryje oblicze, któż go ujrzy? A to czyni tak całemu narodowi, jako każdemu człowiekowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'Aby dalej nie panował człowiek obłudny na upadek ludzki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Zaprawdę miałbyś mówić do Boga: Przepuść; poniosę, a nie będę się wzbraniał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Nadto jeźlibym czego nie baczył, ty mię naucz; jeźlim nieprawość popełnił, nie uczynię tego więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Izali według zdania twego będziesz płacił, żeć się to nie podoba, a żeś ty owo obrał, a nie on? Ale wieszli co lepszego, powiedz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Mężowie rozumni toż rzeką ze mną, a człowiek mądry przypadnie na to,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Że Ijob nie mówi mądrze, a słowa jego nie są roztropne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Boże, Ojcze mój! niech będzie Ijob doskonale doświadczony, przeto, iż nam odpowiada, jako ludziom złym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Bo przestępstwa przyczynia do grzechu swego; chlubi się między nami, i mówi bardzo wiele przeciwko Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Nadto mówił Elihu, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'I mniemasz, żeś to z rozsądkiem rzekł: Sprawiedliwość moja przechodzi Boską?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Boś powiedział: Cóż mi pomoże? a co wezmę za pożytek, choćbym nie grzeszył?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Ale ja tobie dowodnie odpowiem, i towarzyszom twoim z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Spojrzyj w niebo, a obacz; przypatrz się obłokom, jako są wyższe nad cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Jeźli zgrzeszysz, cóż uczynisz przeciwko niemu? a jeźliby były rozmnożone nieprawości twoje, cóż mu uczynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Jeźlibyś był sprawiedliwym, cóż mu dasz? albo cóż weźmie z ręki twojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Człowiekowi podobnemu tobie niezbożność twoja zaszkodzi, a synowi człowieczemu pomoże sprawiedliwość twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Z mnóstwa uciśnionych, którzy do tego przywiedzieni są; aby narzekali i wołali dla ramienia mocarzów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'Żaden nie mówi: Gdzież jest Bóg, stworzyciel mój, choć on daje śpiewanie i w nocy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'Choć nas wyucza nad bydlęta ziemskie, a nad ptastwo niebieskie czyni nas mędrszymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Tedy wołająli dla hardości złych, on ich nie wysłuchuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Bo obłudy nie wysłucha Bóg, a Wszechmocny nie patrzy na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Dopieroż nie wysłucha ciebie, ponieważ mówisz: Nie widzisz tego; osądźże się przed nim, a oczekuj go,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'Gdyż cię jedno trochę nawiedził gniew jego, jakoby nie wiedział wielkości grzechów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Przetoż Ijob próżno otwiera usta swe, a bez umiejętności rozmnaża słowa swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Do tego przydał Elihu, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Poczekaj mię maluczko, a ukażęć; bo jeszcze mam, cobym za Bogiem mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Zacznę umiejętność moję z daleka, a Stworzycielowi memu przywłaszczę sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Boć zaprawdę bez kłamstwa będą mowy moje, a mąż doskonały w umiejętności jest przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Oto Bóg mocny jest, a nie odrzuca nikogo; on jest mocny w sile serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Nie żywi niepobożnego,a u sądu ubogim dopomaga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Nie odwraca od sprawiedliwego oczów swoich; ale z królmi na stolicy sadza ich na wieki, i bywają wywyższeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'A jeźliby byli okowani w pęta, albo uwikłani powrozami utrapienia:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'Tedy przez to im oznajmuje sprawy ich, i przestępstwa ich, że się zmocniły;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'I otwiera im ucho, aby przyjęli karanie, a mówi, aby się nawrócili od nieprawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Jeźli będą posłuszni, a będą mu służyć, dokończą dni swoich w dobrem, a lat swych w rozkoszach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Ale jeźli nie usłuchają, od miecza zejdą, a pomrą bez umiejętności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Bo ludzie obłudnego serca obalają na się gniew, a nie wołają, kiedy ich wiąże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Umrze w młodości dusza ich, a żywot ich między nierządnikami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'Wyrwie utrapionego z utrapienia jego, a otworzy w uciśnieniu ucho jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Takby i ciebie wyrwał z miejsca ciasnego na przestronne, gdzie niemasz ucisku, a spokojny stół twój byłby pełen tłustości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Aleś ty sąd niepobożnego zasłużył, przetoż prawo i sąd będą cię trzymać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Zaisteć gniew Boży jest nad tobą; patrzże, aby cię nie poraził plagą wielką, tak, żeby cię nie wybawił żaden okup.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Izali sobie będzie ważył bogactwa twoje? Zaiste ani złota, ani jakiejkolwiek siły, albo potęgi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Nie kwapże się tedy ku nocy, w którą zstępują narody na miejsca swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Strzeż, abyś się nie oglądał na nieprawość, obierając ją sobie nad utrapienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Oto Bóg jest najwyższy w mocy swojej, któż tak nauczyć może jako on?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Któż mu wymierzył drogę jego? albo kto mu rzecze: Uczyniłeś nieprawość?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Pamiętajże, abyś wysławiał sprawę jego, której się przypatrują ludzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Wszyscy ludzie widzą ją, a człowiek przypatruje się jej z daleka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Oto Bóg jest wielki, a poznać go nie możemy, ani liczba lat jego dościgniona być może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Bo on wyciąga krople wód, które wylewają z obłoków jego deszcz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'Który spuszczają obłoki, a spuszczają na wiele ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, '(Nadto, któż zrozumie rozciągnienie obłoków, i grzmot namiotu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Jako rozciąga nad nim światłość swoję, a głębokości morskie okrywa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'Bo przez te rzeczy sądzi narody, i daje pokarm w hojności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Obłokami nakrywa światłość, i rozkazuje jej ukrywać się za obłok następujący.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Daje o nim znać szum jego, także i bydło i para w górę wstępująca. A nad tem zdumiewa się serce moje, i porusza się z miejsca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Słuchajcie z pilnością grzmienia głosu jego, i dźwięku który wychodzi z ust jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Pod wszystkiem niebem prosto go wypuszcza, a światłość jego po wszystkich kończynach ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Za nią wnet huczy dźwiękiem, grzmi głosem zacności swojej, i nie odkłada innych rzeczy, gdy bywa słyszany głos jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Dziwnie Bóg grzmi głosem swoim; sprawuje rzeczy tak wielkie, że ich rozumieć nie możemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Bo mówi do śniegu: Padaj na ziemię; także i do deszczu wolnego, i do deszczu gwałtownego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Rękę wszystkich ludzi zawiera, aby nikt z ludzi nie doglądał roboty swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Tedy zwierz wchodzi do jaskini, a w jamach swoich zostaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Wicher z skrytych miejsc wychodzi, a zima z wiatrów północnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Tchnieniem swojem Bóg czyni lód, tak iż się szerokość wód ściska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Także dla pokropienia ziemi obciąża obłok, i rozpędza chmurę światłem swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'A ten się obraca w koło według rady jego, aby czynił wszystko, co Bóg rozkaże, na oblicze okręgu ziemskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'A czyni to Bóg, że się stawia bądź na skaranie, bądź dla pożytku ziemi swojej, bądź dla jakiej dobroczynności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'Słuchajże tego pilnie, Ijobie! zastanów się, a uważaj dziwne sprawy Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Izali wiesz, kiedy co Bóg stanowi o tych rzeczach? albo gdy ma rozjaśnić światło obłoku swego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Izali wiesz, co za waga obłoków? Izali wiesz cuda Doskonałego we wszelakiej umiejętności?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Wieszże, jako cię szaty twoje ogrzewają, gdy ucisza ziemię od południa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Izażeś z nim rozpościerał niebiosa, które są trwałe, a zwierciadłu odlewanemu podobne?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'Ukażże nam, co mu mamy powiedzieć; bo nie możemy sporządzić słów dla ciemności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Izali mu kto odniesie to, cobym mówił? I owszem, gdyby to kto przedłożył, byłby pewnie pożarty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Wszak teraz nie mogą ludzie patrzyć i na światło, gdy jest jasne na obłokach, gdy wiatr przechodzi, i przeczyszcza je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Od północy jako złoto przychodzi, ale w Bogu straszniejsza jest chwała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Wszechmogący jest, doścignąć go nie możemy; wielki w mocy, wszakże sądem i ostrą sprawiedliwością ludzi nie trapi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Przetoż boją się go ludzie; nie ma względu na żadnego, by też był i najmędrszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Tedy odpowiedział Pan Ijobowi z wichru, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Któż to jest, co zaciemnia radę Bożą mowami nieroztropnemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Przepasz teraz jako mąż biodra swoje, a będę cię pytał, a ty mi daj sprawę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Gdzieżeś był, kiedym Ja zakładał grunty ziemi? Powiedz, jeźliże nasz rozum.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Któż uczynił rozmierzenie jej? powiedz, jeżli wiesz; albo kto sznur nad nią rozciągnął?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'Na czem są podstawki jej ugruntowane? albo kto założył kamień jej węgielny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'Gdy wespół śpiewały gwiazdy zaranne, a weselili się wszyscy synowie Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'Któż zamknął drzwiami morze, gdy się wyrywało, jakoby z żywota wychodząc?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'Gdym położył obłok za szatę jego, a ciemność za pieluchy jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'Gdym postanowił o niem dekret mój, a przyprawiłem zaworę i drzwi do niego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'I rzekłem: Aż dotąd wychodzić będziesz, a dalej nie postąpisz, a tu położysz nadęte wały twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Izażeś za dni twoich rozkazywał świtaniu, i ukazałeś zorzy miejsce jej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'Aby ogarnęła kończyny ziemi, a iżby byli z niej wyrzuceni niepobożni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Aby się odmieniała jako glina, do której pieczęć przykładają, a oni aby się stali jako szatą nakryci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'I aby była zawściągniona od niepobożnych światłość ich, a ramię wysokie było pokruszone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Izażeś przyszedł aż do źródeł morskich, a po dnie przepaści przechodziłeś się?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Azaż odkryte są tobie bramy śmierci? bramy cienia śmierci widziałżeś?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Izaliś rozumem twym doszedł szerokości ziemi? Powiedz mi, jeźli to wszystko wiesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Gdzież jest ta droga do miejsca światłości? a ciemności gdzie mają miejsce swoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'Abyś ją ująwszy odprowadził do granicy jej, ponieważ zrozumiewasz ścieszki do domu jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Wiedziałżeś na on czas, żeś się miał urodzić? i liczba dni twoich jak wielka być miała?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Izaliś przyszedł do skarbów śniegów? aby skarby gradu widzałeśli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'Które zatrzymywam na czas ucisku, na dzień bitwy i wojny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Którąż się drogą dzieli światłość, i gdzie się rozchodzi wiatr wschodni po ziemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Któż rozdzielił stok powodziom? a drogę błyskawicy gromów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'Aby szedł deszcz na ziemię, w której nikt nie mieszka, i na pustynię, gdzie niemasz człowieka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'Aby nasycił miejsce puste i niepłodne, a wywiódł z niego zieloną trawę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Izali ma deszcz ojca? a krople rosy kto płodzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Z czyjegoż żywota wychodzi mróz? a szron niebieski któż płodzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Jakoż się kamieniem wody nakrywają, gdy wierzch przepaści zamarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Możeszże związać jasne gwiazdy Bab? albo związek Oryjona rozerwać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Izali wywiedziesz gwiazdy południowe czasu swego, albo Wóz niebieski z gwiazdami jego powiedziesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'I znaszże porządek nieba? a możeszże rozrządzić panowanie jego na ziemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Izali podniesiesz ku obłokowi głos twój, aby cię wielkość wód okryła?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Izali możesz wypuścić błyskawice, aby przyszły, i rzekłyć: Otośmy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Któż złożył we wnętrznościach ludzkich mądrość, a kto dał rozumowi bystrość?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Któż obrachował niebiosa mądrością swoją? a co się leje z nieba, któż uspokoi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'Aby polany proch stężał, a bryły aby się społu zelgnęły?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Izali lwowi łup łowisz, a lwiąt żywot napełniasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Gdy się tulą w jaskiniach swoich, i czyhają w cieniu jam swoich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'Któż gotuje krukowi pokarm jego, gdy dzieci jego do Boga wołają a tułają się, nie mając pokarmu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Izali wiesz czas rodzenia kóz skalnych, a kiedy rodzą łanie, postrzegłżeś?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Możeszże zliczyć miesiące, jako długo płód noszą? a czas rodzenia ich wieszże?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'Jako się kurczą, płód swój wyciskają, a rozstępując się z boleścią go pozbywają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Jako moc biorą dzieci ich, i odchowywują się po zbożach, a odszedłszy nie wracają się do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Któż wypuścił osła dzikiego na wolność? a pęta osła dzikiego któż rozwiązał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Któremu dał pustynię miasto domu jego, a miasto mieszkania jego miejsca słone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'On się naśmiewa ze zgrai miejskiej, a na głos tego, co go goni, nic niedba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Patrzy po górach pastwy, a wszelkiej zielonej trawy szuka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Izalić będzie chciał jednorożec służyć, albo będzie nocował u jaśli twoich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Izali możesz zaprządz w powróz swój jednorożca do orania? izali powleka będzie brózdy za tobą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Izali się spuścisz nań, przeto, że wielka moc jego? albo poruczyszli mu robotę twoję?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'Powierzyszże mu się, żeby zwiózł nasienie twoje, a do gumna twojego zgromadził?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Izaliś dał pawiowi piękne skrzydła, a pierze bocianowi i strusiowi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Który niesie na ziemi jajka swoje, a w prochu ogrzewa je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'A nie pomni na to, że je noga zetrzeć, a zwierzę polne zdeptać może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Zatwardza się przeciwko dzieciom swoim, jakoby nie były jego, a żeby nie była próżna praca jego, nie obawia się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Bo mu nie dał Bóg mądrości, i nie udzielił mu wyrozumienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Według czasu podnosi się ku górze, a naśmiewa się z konia i z jeźdźca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Izali możesz dać koniowi moc? izali rzaniem ozdobisz szyję jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Izali go ustraszysz jako szarańczę? i owszem chrapanie nozdrzy jego jest straszne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Kopie dół, a weseli się w mocy swej, i bieży przeciwko zbrojnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Śmieje się z postrachu, a ani się lęka, ani nazad ustępuje przed ostrzem miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Choć na nim chrzęści sajdak, i błyszczy się oszczep, i drzewce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'Z grzmotem i z gniewem kopie ziemię, a nie stoi spokojnie na głos trąby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'Między trąbami poryza, a z daleka czuje bitwę, krzyk książąt, i wołanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Izali według twego rozumu lata jastrząb, i rozciąga skrzydła swe ku południowi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'Izali na twoje rozkazanie wzbija się orzeł w górę, i składa na wysokich miejscach gniazdo swoje? Na opoce mieszka, i bawi się na ostrej skale, jako na zamku. Stamtąd upatruje sobie pokarm, a daleko oczy jego widzą. Dzieci też jego piją krew, a gdzie są pobici, tam on jest. A tak odpowiedział Pan Ijobowi, i rzekł: Izali ten, co wiedzie spór z Wszechmogącym, uczyć go będzie? a kto chce strofować Boga, niech na to odpowie. Zatem odpowiedział Ijob Panu, i rzekł: Otom ja lichy, cóż ci mam odpowiedzieć? Rękę moję włożę na usta moje. Mówiłem raz i drugi, ale więcej nie odpowiem, i nic więcej nie przydam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'Nadto odpowiedział Pan Ijobowi z wichru, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Przepasz teraz jako mąż biodra swe: będę cię pytał, a ty mi daj sprawę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'Izali wniwecz obrócisz sąd mój? a obwinisz mię, abyś się sam usprawiedliwił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Izali masz ramię jako Bóg? a głosem zagrzmisz jako on?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Ozdóbże się teraz zacnością i dostojnością, a w chwałę i w ochędóstwo oblecz się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Rozpostrzyj popędliwość gniewu twego, a patrz na każdego pysznego, i poniż go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Spojrzyjże na każdego hardego a skróć go, a zetrzyj niepobożnych na miejscu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Zakryj ich pospołu w prochu, a oblicza ich zawiąż w skrytości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Tedyć i Ja przyznam, że cię może zachować prawica twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Oto teraz słoń, któregom uczynił jako i ciebie, trawę je jako wół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Oto teraz moc jego jest w biodrach jego, a siła jego w pępku brzucha jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Rusza ogonem swoim, jako chce, choć jest jako drzewo cedrowe; żyły łona jego są powikłane jako latorośli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Kości jego jako trąby miedziane; gnaty jego jako drąg żelazny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'On jest przedniejszym z uczynków Bożych; który go uczynił, sam nań natrzeć może mieczem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Jemuć pastwę góry przynoszą, a wszystek zwierz polny tam igra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Pod cienistem drzewem lega w skrytościach trzciny i błota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Okrywają go drzewa cieniste cieniem swoim, a ogarniają go wierzby nad potokami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Oto zatrzymuje strumień, że się nie spieszy; tuszy sobie, iż Jordan wypije gębą swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'Azali go kto przed oczyma jego ułapi? albo powrozy przeciągnie przez nozdrze jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Wyciągnieszże wędą wieloryba? albo sznurem utopionym w języku jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Izali zawleczesz kolce przez nozdrza jego? albo hakiem przekoleszli czeluść jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'Izalić się będzie wiele modlił, albo z tobą łagodnie mówić będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Izali uczyni przymierze z tobą, a przyjmiesz go za sługę wiecznego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Izali z nim będziesz igrał jako z ptaszkiem, a uwiążesz go dziatkom twoim? Sprawiże sobie nad nim towarzystwo ucztę, a podzielą go między kupców? Izali zawadzisz hakami za skórę jego, a widelcami rybackiemi za głowę jego? Połóż tylko nań rękę twą, ślubujęć, że nie wspomnisz więcej na bitwę. Oto nadzieja ułowienia jego omylna jest; izali i wejrzawszy nań człowiek nie upada?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Niemasz tak śmiałego, coby go obudził; owszem któż się stawi przed twarzą moją?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Któż mi co dał, abym mu oddał? cokolwiek jest pod wszystkiem niebem, moje jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Nie zamilczę członków jego, ani silnej mocy jego, a grzecznego kształtu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Któż odkryje wierzch odzienia jego? z dwoistemi wędzidłami swemi któż przystąpi do niego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Wrota gęby jego któż otworzy? bo strach około zębów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Łuski jego mocne jako tarcze, bardzo ściśle spojone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Jedna z drugą tak spojona, że wiatr nie wchodzi między nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Jedna do drugiej przylgnęła, ujęły się, a nie dzielą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Kichanie jego czyni blask, a oczy jego są jako powieki zorzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Z ust jego lampy wychodzą, a iskry ogniste wyrywają się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Z nozdrzy jego wychodzi dym, jako z garnca wrzącego, albo kotła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Dech jego węgle rozpala, a płomień z ust jego wychodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'W szyi jego przemieszkuje moc, a boleść przed nim ucieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Sztuki ciała jego spoiły się, całowite są w nim, że się nie porusza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Serce jego twarde jako kamień, tak twarde, jako sztuka spodniego kamienia młyńskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Gdy się podnosi, drżą mocarze, a od strachu oczyszczają się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'Miecz, który go sięga, nie ostoi się, ani drzewce, ani strzała, ani pancerz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Żelazo poczyta sobie za plewę, a miedź za drzewo zbótwiałe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Nie upłoszy go strzała, a jako źdźbło są u niego kamienie z procy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Strzelbę sobie poczyta jako słomę, a pośmiewa się z szermowania włócznią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Pod nim są ostre skorupy; ściele sobie na rzeczach ostrych jako na błocie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Czyni, że wre głębokość jako garniec, a że się mąci morze jako w moździerzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Za sobą jasną ścieszkę czyni, tak, że się zdaje, iż przepaść ma siwiznę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Niemasz na ziemi równego mu, który tak stworzony jest, że się niczego nie boi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Wszelką rzecz wysoką lekce waży; on jest królem nad wszystkiemi srogiemi zwierzętami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Tedy odpowiedział Ijob Panu, i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Wiem, że wszystko możesz, i nie może być zahamowany zamysł twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Któż jest ten, pytasz, który zaciemnia radę Bożą nieumiejętnie? Dlatego przyznaję, żem nie zrozumiał; dziwniejsze są te rzeczy, niżbym je mógł pojąć i zrozumieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Wysłuchajże, proszę, gdybym mówił; a gdy się będę pytał, oznajmijże mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Przedtem tylko ucho słyszało o tobie; ale teraz oko moje widzi cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Przetoż żałuję i pokutuję w prochu i w popiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'A gdy odmówił Pan te słowa do Ijoba, rzekł Pan do Elifasa Tamańczyka: Rozpalił się gniew mój przeciw tobie, i przeciw dwom przyjaciołom twoim, żeście o mnie nie mówili tak przystojnie, jako Ijob, sługa mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'Przetoż teraz, weźmijcie sobie siedm cielców, i siedm baranów, a idźcie do sługi mego Ijoba, i ofiarujcie całopalenie za się; a Ijob, sługa mój, niech się modli za wami; bo oblicze jego przyjmę, abym nie uczynił z wami według głupstwa waszego; boście nie mówili tak przystojnie o mnie, jako Ijob, sługa mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'A tak odeszli Elifas Temańczyk, i Bildad Suhitczyk, i Sofar Naanatczyk, i uczynili, jako im rozkazał Pan; i przyjął Pan oblicze Ijobowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'Zatem Pan przywrócił to, co było pobrane Ijobowi, gdy się modlił za przyjaciół swoich; i rozmnożył Pan wszystko, cokolwiek miał Ijob, w dwójnasób.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Zeszli się tedy do niego wszyscy bracia jego, i wszystki siostry jego, i inni wszyscy, którzy go przedtem znali, i jedli z nim chleb w domu jego, a żałując go cieszyli go z strony wszystkiego złego, które był Pan nań przywiódł; i dał mu każdy z nich upominek jeden, i każdy nausznicę złotą jedne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'A tak Pan błogosławił ostatnim czasom Ijobowym, więcej niż początkom jego. Bo miał czternaście tysięcy owiec, i sześć tysięcy wielbłądów, i tysiąc jarzm wołów, i tysiąc oślic.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Miał też siedm synów, i trzy córki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'I dał imię pierwszej Jemina, a imię drugiej Kietzyja, a imię trzeciej Kierenhappuch.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'A nie znajdowały się niewiasty tak piękne, jako córki Ijobowe, we wszystkiej onej ziemi; i dał im ojciec ich dziedzictwo między braćmi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Potem Ijob żył sto i czterdzieści lat, i oglądał synów swych, i synów synów swoich, aż do czwartego pokolenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'A umarł Ijob, będąc starym i dni sytym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Błogosławiony mąż, który nie chodzi w radzie niepobożnych, a na drodze grzesznych nie stoi, i na stolicy naśniewców nie siedzi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Ale w zakonie Pańskim jest kochanie jego, a w zakonie jego rozmyśla we dnie i w nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Albowiem będzie jako drzewo nad strumieniem wód w sadzone, które owoc swój wydaje czasu swego, a liść jego nie opada; i wszystko, cokolwiek czynić będzie, poszczęści się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Lecz nie tak niepobożni; ale są jako plewa, którą wiatr rozmiata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Przetoż się niepobożni na sądzie nie ostoją, ani grzesznicy w zgromadzeniu sprawiedliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Albowiem zna Pan drogę sprawiedliwych; ale droga niepobożnych zginie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Przeczże się poganie buntują, a narody przemyślają próżne rzeczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Schodzą się królowie ziemscy, a książęta radzą społem przeciwko Panu, i przeciw pomazańcowi jego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Potargajmy związki ich, a odrzućmy od siebie powrozy ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Ale ten, który mieszka w niebie, śmieje się; Pan szydzi z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Tedy będzie mówił do nich w popędliwości swojej, a w gniewie swoim przestraszy ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Mówiąc: Jamci postanowił króla mojego nad Syonem, górą świętą moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Opowiem ten dekret: Pan rzekł do mnie: Syn mój jesteś ty, Jam ciebie dziś spłodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Żądaj odemnie, a dam ci narody dziedzictwo twoje; a osiadłość twoję, granice ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Potrzesz ich laską żelazną, a jako naczynie zduńskie pokruszysz ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Terazże tedy zrozumiejcie, królowie, nauczcie się sędziowie ziemi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Służcie Panu w bojaźni, a rozradujcie się ze drżeniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Pocałujcie syna, by się snać nie rozgniewał, i zginęlibyście w drodze, gdyby się najmniej zapaliła popędliwość jego. Błogosławieni wszyscy, którzy w nim ufają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Psalm Dawidowy, gdy uciekał przed Absalomem, synem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Panie, jako się namnożyło nieprzyjaciół moich! wiele ich powstaje przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Wiele ich mówią o duszy mojej: Niemać ten ratunku od Boga. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Ale ty, Panie! jesteś tarczą moją, chwałą moją, i wywyższającym głowę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Głosem swym wołałem do Pana, a wysłuchał mię z góry świętej swojej. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Jam się układł, i zasnąłem, a ocuciłem się; bo mię Pan podpierał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Nie ulęknę się wielu tysięcy ludu, którzy się na mię zewsząd zasadzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Powstań, Panie! wybaw mię, Boże mój! albowiemeś ty uderzył w lice wszystkich nieprzyjaciół moich, z zęby niezbożników pokruszyłeś. Od Panać jest wybawienie, a nad ludem twoim błogosławieństwo twoje. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Przedniejszemu śpiewakowi na Neginot psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Wysłuchaj mię, gdy cię wzywam, Boże sprawiedliwości mojej! któryś mi sprawił przestrzeństwo w uciśnieniu; zmiłuj się nademną, a wysłuchaj modlitwę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Synowie ludzcy, i dokądże chwałę moję lżyć będziecie, miłując próżności, a szukając kłamstwa? Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Wiedzcież, żeć Pan odłączył sobie pobożnego; wysłucha Pan, gdy zawołam do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Lękajcież się, a nie grzeszcie; rozmyślajcie w sercach swych, na łożach waszych, a umilkniecie. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Ofiarujcież ofiary sprawiedliwości, a ufajcie w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Wieleć ich mówią: Któż nam da oglądać dobra? Ale ty, Panie! podnieś nad nami światłość oblicza twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'I sposobisz większą radość w sercu mojem, niż oni miewają, gdy się im zboża ich i wina ich obficie zrodzą. W pokoju się i położę i zasnę, bo ty sam, Panie! czynisz, że bezpiecznie mieszkam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Przedniejszemu śpiewakowi na Nechylot psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Przyjmij, Panie! w uszy swe słowa moje, i wyrozumij doległości moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Słuchaj pilnie głosu wołania mego; królu mój, i Boże mój! boć się modlę tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Panie! rano usłysz głos mój; ranoć przedłożę modlitwę moję, i będę wyglądał pomocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Albowiem ty, o Boże! nie kochasz się w nieprawości, a nie zmieszka z tobą złośnik.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Nieostoją się szaleni przed oczyma twemi: ty masz w nienawiści wszystkich, którzy broją nieprawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Wygłubisz tych, którzy mówią kłamstwo; mężem krwawym i zdradliwym brzydzi się Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Ale ja w obfitości miłosierdzia twego wnijdę do domu twego, a pokłonię się w kościele twoim świętym, w bojaźni twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Panie! prowadź mię w sprawiedliwości twojej dla nieprzyjaciół moich, a wyprostuj przed obliczem mojem drogę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Bo niemasz nic szczerego w ustach ich; wnętrzności ich złośliwe, gardło ich jako grób otwarty, językiem swym pochlebiają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Spustosz ich, o Boże! Niech upadną od rad swoich; dla wielkości przestępstwa ich rozpędź ich, ponieważ są odpornymi tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'A niechaj się rozweselą wszyscy, co ufają w tobie; na wieki niech wykrzykują, gdyż ich ty szczycić będziesz, i rozradują się w tobie, którzy miłują imię twoje. Albowiem ty, Panie! sprawiedliwemu błogosławić będziesz, a zastawisz go, jako tarczą, dobrotliwością twoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Przedniejszemu śpiewakowi na Neginot i Seminit psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Panie! w popędliwości twojej nie nacieraj na mię, a w gniewie twoim nie karz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Zmiłuj się nademną, Panie! bomci mdły; uzdrów mię, Panie! boć się strwożyły kości moje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'I dusza moja bardzo jest zatrwożona; ale ty, Panie! pokądże?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Nawróć się, Panie! wyrwij duszę moję; wybaw mię dla miłosierdzia twego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Albowiem w śmierci niemasz pamiątki o tobie, a w grobie któż cie wyznawać będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Spracowałem się od wzdychania mego; opływa na każdą noc pościel moja, a łoże moje mokre jest od łez.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Zaćmiło się dla gniewu oko moje, a zstarzała się twarz moja dla wszystkich nieprzyjaciół moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Odstąpcie odemnie wszyscy, krórzy czynicie nieprawość; albowiem Pan usłyszał głos płaczu mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Usłyszał Pan prośbę moję; Pan modlitwę moję przyjął. Niech się zawstydzą i bardzo zatrwożą wszyscy nieprzyjaciele moi; niech tył podadzą, a niech prędko pohańbieni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Syggajon Dawidowe, które śpiewał Panu dla słów Chusy, syna Jemini.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Panie, Boże mój! w tobie ufam; wybawże mię od wszystkich prześladowców moich, i wyzwól mię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'By snać duszy mojej nie porwał jako lew, a nie rozszarpał, gdyby nie było, ktoby ją wybawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Panie, Boże mój! jeźlim to uczynił, a jeźli jest nieprawość w rękach moich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Jeźlim złe oddał temu, który ze mną w pokoju mieszkał; jeźliżem nie wyrwał tego, który mię dręczył bez przyczyny:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Niechajże prześladuje nieprzyjaciel duszę moję, a niechaj pochwyci, i podepcze na ziemi żywot mój, a sławę moję niech zagrzebie w proch. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Powstańże, Panie! w popędliwości twojej, podnieś się przeciwko wściekłości nieprzyjaciół moich, ocuć się, a obróć się ku mnie; boś ty sąd postanowił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Tedy się do ciebie zbieży zgromadzenie narodów; dla nich tedy usiądź na wysokości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Pan będzie sądził narody. Osądźże mię, Panie! według sprawiedliwości mojej, i według niewinności mojej, która jest przy mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Niechże, proszę, ustanie złość niepobożnych, a umocnij sprawiedliwego, który doświadczasz serc i wnętrzności, o Boże sprawiedliwy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Bóg jest tarczą moją, który wybawia ludzi serca szczerego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Bóg jest sędzią sprawiedliwym; Bóg obrusza się co dzień na niezbożnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Jeźli się nie nawróci, naostrzy miecz swój; łuk swój wyciągnął, i nagotował go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Zgotował nań broń śmiertelną, a strzały swoje na prześladowników przyprawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Oto rodzi nieprawość, bo począł boleść; ale porodzi kłamstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Kopał dół, i wykopał go; ale wpadnie w dół, który sam uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Obróci się boleść jego na głowę jego, a na wierzch głowy jego nieprawość jego spadnie. Będę wysławiał Pana według sprawiedliwości jego, a będę śpiewał imieniowi Pana najwyższego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Przedniejszemu śpiewakowi na Gittyt psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Panie, Panie nasz! jakoż zacne jest imię twoje po wszystkiej ziemi! któryś wyniósł chwałę twoję nad niebiosa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Z ust niemowlątek i ssących ugruntowałeś moc twą dla nieprzyjaciół twoich, abyś wyniszczył nieprzyjaciela i tego, który się mści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Gdy się przypatruję niebiosom twoim, dziełu palców twoich, miesiącowi i gwiazdom, któreś wystawił,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Tedy mówię: Cóż jest człowiek, iż nań pamiętasz? albo Syn człowieczy, iż go nawiedzasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Albowiem mało mniejszym uczyniłeś go od Aniołów, chwałą i czcią ukoronowałeś go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Dałeś mu opanować sprawy rąk twoich, wszystkoś poddał pod nogi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Owce i woły wszystkie, nadto i zwierzęta polne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Ptastwo niebieskie, i ryby morskie, i cokolwiek chodzi po ścieszkach morskich. Panie, Panie nasz! jako zacne jest imię twoje po wsystkiej ziemi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Przedniejszemu śpiewakowi, na Halmutlabben pieśń Dawidowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Będę wysławiał Pana ze wszystkiego serca mego; opowiadać będę wszysteki cuda twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Rozweselę się, i rozraduję się w tobie; będę śpiewał imieniowi twemu, o Najwyższy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Że się obrócili nieprzyjaciele moi na wstecz: upadli i poginęli od obliczności twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Boś ty odprawił sąd mój, i sprawę moję; zasiadłeś na stolicy, Sędzia sprawiedliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Rozgromiłeś pogan, zatraciłeś złośnika, imię ich wygładziłeś na wieki wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'O nieprzyjacielu! azaż wykonane są spustoszenia twoie na wieczność? Poburzyłżeś miasta? i owszem ich samych pamiątka zginęła z niemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Ale Pan na wieki trwa; zgotował stolicę swoję na sąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'On będzie sądził okrąg ziemi w sprawiedliwości, i osądzi narody w prawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'I będzie Pan ucieczką ubogiemu, ucieczką czasu ucisku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'I będą ufać w tobie, którzy znają imię twoje; albowiem nie opuszczasz tych, Panie! którzy cię szukają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Śpiewajcież Panu, który mieszka na Syonie; opowiadajcie między narodami sprawy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Boć on szuka krwi, i mają w pamięci, a nie zapomina wołania utrapionych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Zmiłuj się nademną, Panie! obacz utrapienie moje od tych, którzy mię mają w nienawiści, ty, co mię wyrywasz z bram śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Abym opowiadał wszystkie chwały twoje w bramach córki Syońskiej, weseląc się w zbawieniu twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Zanurzeni są poganie w dole, który uczynili; w sieci, którą skrycie zastawili, uwięzła noga ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Oznajmił się Pan, gdy uczynił sąd; w sprawie rąk swoich się złośnik usidlił. Rzecz godna rozmyślania! Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Niepobożni się obrócą do piekła, wszystkie narody, które zapominają Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Bo nie będzie na wieki zapamiętany ubogi; oczekiwanie nędznych nie zginie na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Powstańże, Panie! niech się nie zmacnia śmiertelny człowiek; a niech narody osądzone będą przed tobą. Panie! puść na nie strach, aby poznały narody, iż są ludźmi śmiertelnymi.Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Panie! przeczże stoisz z daleka? przeczże się ukrywasz czasu ucisku?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Złośnik z hardości prześladuje ubogiego; niechajże będą uchwyceni w chytrych zamysłach, które zamyślają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Bo się chlubi niezbożnik w pożądliwościach duszy swojej, a łakomy błogosławi sobie a draźni Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Niepobożny dla pychy, którą po sobie pokazuje, nie pyta się o Boga; wszystka myśl jego, że niemasz Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Darzą mu się drogi jego na każdy czas; dalekie są sądy twoje od niego; sapa przeciwko wszystkim nieprzyjaciołom swym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Mówi w sercu swem: Nie będę wzruszony od narodu do narodu; bo się nie boję złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Usta jego pełne są złorzeczeństwa, i chytrości, i zdrady; pod językiem jego uprzykrzenie i nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Siedzi, czyhając we wsiach, w skrytościach zabija niewinnego; oczy jego upatrują ubogiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Czyha w skrytem miejscu, jako lew w jamie swojej; dybie jakoby uchwycił ubogiego, ułapiwszy go ciągnie do sieci swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Przypada, przytula się, i rzuca się mocą swoją na wiele ubogich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Mówi w sercu swem: Zapomnałci tego Bóg; zakrył oblicze swoje, nie ujrzy na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Powstańże, Panie Boże! podnieś rękę twoję; nie zapominajże ubogich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Przeczże niezbożnik draźni Boga, mówiąc w sercu swem: Nie będziesz się o tem pytał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Ale ty widzisz ucisk, i krzywdę upatrujesz, abyś im odpłacił ręką twą; na ciebieć się spuścił ubogi, tyś jest pomocnikiem sierocie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Potrzyj ramię niepobożnego i złośnika, dowiaduj się o jego niezbożności, aż go nie stanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Pan jest królem na wieki wieczne; ale narody zginą z ziemi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Żądości pokornych wysłuchiwasz, Panie! utwierdzasz serca ich, nachylasz ku nim ucha twojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Abyś sąd uczynił sierocie i chudzinie, aby go więcej nie trapił człowiek śmiertelny na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy. W Panu ja ufam. Jakoż tedy mówicie duszy mojej: Ulatuj jako ptak z góry swojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Bo oto niepobożni naciągają łuk, przykładają strzałę swą na cięciwę, aby strzelali w ciemności na uprzejmych sercem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Ale zamysły ich będą skażone; bo sprawiedliwy cóż uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Pan jest w kościele świętem swoim, stolica Pańska jest na niebie; oczy jego upatrują, powieki jego doświadczają synów ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Pan doświadcza sprawiedliwego; ale niepobożnego i miłującego nieprawość ma w nienawiści dusza jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Wyleje jako deszcz na niepobożnych sidła, ogień i siarkę, a wicher będzie cząstką kielicha ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Bo sprawiedliwy Pan, sprawiedliwość miłuje, na szczerego patrzą oczy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Przedniejszemu śpiewakowi Seminit, pieśń Dawidowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Ratuj, Panie! boć już niestaje miłosiernego, a wyginęli uprzejmi z synów ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Każdy mówi kłamstwo z bliźnim swoim: usty pochlebnemi, dwojakiem sercem mówią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Niechajże Pan wytraci wszystkie wargi pochlebne, i język mówiący rzeczy wyniosłe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Którzy mówią: Językiem naszym przewiedziemy, wargi nasze za nami są, któż jest panem naszym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Dla zniszczenia ubogich, i dla wołania nędznych teraz powstanę, mówi Pan; postawię w bezpieczności tego, na którego sidła stawiają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Słowa Pańskie są słowa czyste, jako srebro wypławione w piecu glinianym, siedm kroć przelewane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Ty, Panie! zachowaj ich; strzeż ich od rodzaju tego aż na wieki. Ze wszystkich stron niepobożni krążą, gdy wywyższeni bywają najpodlejsi między synami ludzkimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Przedniejszemu śpiewakowi pieśń Dawidowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Dokądże Panie? Zapomniszże mię na wieki? dokądże ukrywać będziesz oblicza twego przedemną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Dokądże się będę radził w duszy swojej, a trapił w sercu mojem przez cały dzień? Dokądże się będzie wywyższał nieprzyjaciel mój nademną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Wejrzyjże, wysłuchaj mię, Panie, Boże mój! oświeć oczy me, bym snać nie zasnął w śmierci;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'By snać nie rzekł nieprzyjaciel mój: Przemogłem go; ażeby się nieprzyjaciele moi nie rodowali, gdybym się zachwiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Ale ja w miłosierdziu twojem ufam: rozraduje się serce moje w zbawieniu twojem; będę śpiewał Panu, że mi dał wiele dobrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Głupi rzekł w sercu swojem: Niemasz Boga. Popsowali się, obrzydliwymi się stali w zabawach swoich: niemasz, ktoby czynił dobrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Pan z niebios spojrzał na synów ludzkich, aby obaczył, byłliby kto rozumny i szukający Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Aleć wszyscy odstąpili, jednako się nieużytecznymi stali; niemasz, ktoby czynił dobrze, niemasz i jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Azaż nie wiedzą wszyscy czyniciele nieprawości, że pożerają lud mój, jako więc chleb jedzą? ale Pana nie wzywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Tam się bardzo ulękną, gdyż Bóg jest przy narodzie sprawiedliwego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Hańbicie radę ubogiego; ale Pan jest nadzieją jego. Któż da z Syonu wybawienie Izraelowi? Gdyż zasię wyprowadzi Pan z więzienia lud swój; rozraduje się Jakób, a Izrael się rozweseli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Pieśń Dawidowa. Panie! któż będzie przebywał w przybytku twoim? Któż będzie mieszkał na świętej górze twojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Ten, który chodzi w niewinności, i czyni sprawiedliwość, a mówi prawdę w sercu swojem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Który nie obmawia językiem swoim, nic złego nie czyni bliźniemu swemu, ani zelżywości kładzie na bliźniego swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'Przed którego oczyma wzgardzony jest niezbożnik, ale tych, którzy się boją Pana, ma w uczciwości; który, choć przysięże z szkodą swoją, nie odmienia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Który pieniędzy swych nie daje na lichwę, i darów przeciwko niewinnym nie przyjmuje. Kto to czyni, nie zachwieje się na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Złota pieśń Dawidowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Strzeż mię, o Boże! bo w tobie ufam. Rzecz, duszo moja! Panu: Tyś Pan mój, a dobroć moja nic ci nie pomoże,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'Ale świętym, którzy są na ziemi, i zacnym, w których wszystko kochanie moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Rozmnożą się boleści tych, którzy się za cudzym bogiem kwapią; nie ukuszę ze krwi mokrych ofiar ich, ani wezmę imion ich w usta moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Pan jest cząstką dziedzictwa mego, i kielicha mego, ty zatrzymujesz los mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Sznury mi przypadły na miejscach wesołych, a dziedzictwo wdzięczne przyszło na mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Będę błogosławił Pana, który mi dał radę, gdyż i w nocy ćwiczą mię nerki moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Stawiałem Pana zawsze przed oczyma swemi; a iż on jest po prawicy mojej, nie będę wzruszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Przetoż uweseliło się serce moje, a rozradowała się chwała moja; dotego ciało moje mieszkać będzie bezpiecznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Bo nie zostawisz duszy mojej w grobie, ani dopuścisz świętemu twemu oglądać skażenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Oznajmisz mi drogę żywota; obfitość wesela jest przed obliczem twojem, rozkoszy po prawicy twojej aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Modlitwa Dawidowa. Wysłuchaj, Panie! sprawiedliwość moję; miej wzgląd na wołanie moje; przyjmij w uszy modlitwę moję, którą czynię usty nieobłudnemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Od obliczności twojej sąd mój niech wynijdzie; oczy twoje niech patrzą na uprzejmość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Doświadczyłeś serca mego, nawiedziłeś je w nocy; doświadczyłeś mię ogniem, aleś nic nie znalazł; myśli moje nie uprzedzają ust moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Co się tknie spraw ludzkich według słowa ust twoich, chroniłem się drogi okrutnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Zatrzymuj kroki moje na drogach twych, aby się nie chwiały nogi moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Ja cię wzywam, bo mię wysłuchiwasz, Boże! Nakłoń ucha twego ku mnie, wysłuchaj słowa moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Okaż miłosierdzie twoje, ty, który ochraniasz ufających w tobie od tych, którzy powstawają przeciwko prawicy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Strzeż mię jako źrenicy oka; pod cieniem skrzydeł twoich ukryj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'Przed twarzą niepobożnych, którzy mię niszczą, przed nieprzyjaciółmi duszy mojej, którzy mię ogarnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Tukiem swoim okryli się; hardzie mówią usty swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Gdziekolwiek idziemy, obtoczyli nas; oczy swe nasadzili, aby nas potrącili ku ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Każdy z nich podobien jest lwowi pragnącemu łupu, i lwięciu siedzącemu w jamie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Powstańże, Panie! uprzedź twarz jego, potrąć go, wyrwij duszę moję od niezbożnego mieczem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Wyrwij mię od ludzi ręką twoją, o Panie! od ludzi tego świata, których dział jest w tym żywocie, a których brzuch z szpiżarni twojej napełniasz, skąd nasyceni bywają, i synowie ich, a zostawiają ostatki swoje dzieciom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Ale ja w sprawiedliwości oglądam oblicze twoje; gdy się ocucę, nasycony będę obrazem obliczności twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Przedniejszemu śpiewakowi pieśń Dawida, sługi Pańskiego, który mówił do Pana słowa tej pieśni onego dnia, gdy go Pan wyrwał z rąk wszystkich nieprzyjaciół jego, i z ręki Saulowej; i rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Rozmiłuję się ciebie, Panie, mocy moja!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Pan opoką moją, twierdzą moją, i wybawicielem moim; Bóg mój skała moja, w nim będę ufał; tarcza moja, i róg zbawienia mego, ucieczka moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Wzywałem Pana chwalebnego, a od nieprzyjaciół moich byłem wybawiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Ogarnęły mię były boleści śmierci, a potoki niepobożnych zatrwożyły mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Boleści grobu ogarnęły mię były, zachwyciły mię sidła śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'W utrapieniu mojem wzywałem Pana, i wołałem do Boga mego; wysłuchał z kościoła swego głos mój, a wołanie moje przed oblicznością jego przyszło do uszów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Tedy się ziemia wzruszyła i zadrżała, a fundamenty gór zatrząsnęły się, i wzruszyły się od gniewu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Występował dym z nozdrzy jego, węgle się rozpaliły od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Nakłonił niebios, i zstąpił, a ciemność była pod nogami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'A wsiadłszy na Cheruba, latał; latał na skrzydłach wiatrowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Uczynił sobie z ciemności ukrycie, około siebie namiot swój z ciemnych wód, i z gęstych obłoków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Od blasku przed nim rozeszły się obłoki jego, grad i węgle ogniste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'I zagrzmiał na niebie Pan, a Najwyższy wydał głos swój, grad i węgle ogniste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Wypuścił strzały swe, i rozproszył ich, a błyskawicami gęstemi rozgromił ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'I okazały się głębokości wód, a odkryte są grunty świata na fukanie twoje, Panie! i na tchnienie wiatru nozdrzy twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Posławszy z wysokości zachwycił mię; wyciągnął mię z wód wielkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Wyrwał mię od mocnego nieprzyjaciela mego, i od tych, którzy mię mieli w nienawiści, choć byli mocniejszymi nad mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Uprzedzili mię byli w dzień utrapienia mego; ale Pan był podporą moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Wywiódł mię na przestrzeństwo; wyrwał mię, iż mię umiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Nagrodził mi Pan według sprawiedliwości mojej; według czystości rąk moich oddał mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Bom strzegł dróg Pańskich, anim odstąpił niezbożnie od Boga mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Bom miał wszystkie sądy jego przed oczyma memi, a ustaw jego nie odrzucałem od siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Owszem, byłem szczerym przed nim, a strzegłem się od nieprawości mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Przetoż oddał mi Pan według sprawiedliwości mojej, według czystości rąk moich, która była przed oczyma jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Ty, Panie! z miłosiernym miłosiernie się obejdziesz, a z mężem szczerym szczerze sobie postąpisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Z uprzejmym uprzejmie się obejdziesz, a z przewrotnym przewrotnie sobie postąpisz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Albowiem ty lud utrapiony wybawisz, a oczy wyniosłe poniżysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Ty zaiste rozświecisz pochodnię moję; Pan, Bóg mój, oświeci ciemności moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Gdyż z tobą przebiłem się przez wojsko, a z Bogiem moim przeskoczyłem mur.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Droga Boża doskonała jest; słowo Pańskie jest ogniem wypławione. Tarczą jest wszystkich, którzy w nim ufają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Bo któż jest Bóg, oprócz Pana? a kto opoką, oprócz Boga naszego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'On jest Bogiem, który mię opasuje mocą, a czyni prostą drogę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Krzepi nogi moje jako jelenie, a na wysokich miejscach moich stawia mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Çwiczy ręce moje do boju, tak, iż kruszę łuk miedziany ramionami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Dałeś mi też tarcz zbawienia twego, a prawica twoja podpierała mię, i dobrotliwość twoja uwielmożyła mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Rozszerzyłeś kroki moje podemną, tak, że się nie zachwiały golenie moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Goniłem nieprzyjaciół moich, a doścignąłem ich: i nie wróciłem się, ażem ich wytracił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Poraziłem ich tak, iż nie mogli powstać; upadli pod nogi moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Tyś mię opasał mocą ku bitwie; powstawających przeciwko mnie obaliłeś pod mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Podałeś mi tył nieprzyjaciół moich, abym tych, którzy mię nienawidzą, wykorzenił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Wołalić, ale nie był, ktoby ich wybawił; do Pana, ale ich nie wysłuchał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'I potarłem ich, jako proch od wiatru; jako błoto na ulicach podeptałem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Wyrwałeś mię od zwad ludzkich, a postawiłeś mię głową narodom; lud, któregom nie znał, służył mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Skoro usłyszeli, byli mi posłuszni; cudzoziemcy obłudnie mi się poddawali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Cudzoziemcy opadli, a drżeli w zamknieniach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Żyje Pan, błogosławiona opoka moja; przetoż niech będzie wywyższony Bóg zbawienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Bóg jest, który mi zleca pomsty, i podbija mi narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Tyś wybawiciel mój od nieprzyjaciół moich; tyś mię nad powstawających przeciwko mnie wywyższył; od męża drapieżnego wyrwałeś mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Przetoż cię, Panie! będę wyznawał między narodami, a będę śpiewał imieniowi twemu. Boś zacnie wybawił króla swego, a czynisz miłosierdzie pomazańcowi swemu Dawidowi, i nasieniu jego, aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Niebiosa opowiadają chwałę Bożą, a dzieło rąk jego rozpostarcie oznajmuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Dzień dniowi podaje słowo, a noc nocy pokazuje umiejętność,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Niemasz języka ani mowy, gdzieby głosu ich słychać nie było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'Na wszystkę ziemię wyszedł porządek ich, a na kończyny okręgu ziemi słowa ich; słońcu na nich namiot wystawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'A to jako oblubieniec wychodzi z łożnicy swojej; raduje się jako olbrzym, który ma bieżeć w drogę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Wychodzi od kończyn niebios, a obchodzi je aż do kończyn ich, a niemasz nic, coby się mogło ukryć przed gorącem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Zakon Pański jest doskonały, nawracający duszę; świadectwo Pańskie wierne, dawające mądrość nieumiejętnemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Przykazania Pańskie są prawe, uweselające serce; przykazanie Pańskie czyste, oświecające oczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Bojaźń Pańska czysta, trwająca na wieki; sądy Pańskie są prawdziwe, a przytem i sprawiedliwe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Pożądliwsze nad złoto, i nad wiele najwyborniejszego złota, i słodsze nad miód i nad plastr miodowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Sługa też twój bywa oświecony przez nie; a kto ich przestrzega, odnosi zapłatę wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Ale występki któż zrozumie? od tajemnych występków oczyść mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'I od swawolnych zachowaj sługę twego, aby nie panowali nademną; tedy doskonałym będę, a będę oczyszczony od przestępstwa wielkiego. Niechże będą przyjemne słowa ust moich, i rozmyślanie serca mego przed obliczem twojem, Panie, skało moja, i odkupicielu mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Niech cię Pan wysłucha w dzień utrapienia; niech cię wywyższy imię Boga Jakóbowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Niech ci ześle ratunek z świątnicy, a z Syonu niech cię podeprze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Niech wspomni na wszystkie ofiary twoje, a całopalenia twoje niech w popiół obróci. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Niech ci da wszystko według serca twego, a wszelką radę twoję niech wypełni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Rozweselimy się w wybawieniu twojem, a w imieniu Boga naszego chorągiew podniesiemy; niech wypełni Pan wszystkie prośby twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Teraześmy poznali, iż Pan wybawił pomazańca swego, a iż go wysłuchał z nieba swego świętego przez zbawienną moc prawicy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Jedni w wozach, a drudzy w koniach ufają; ale my na imię Pana, Boga naszego, wspominamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Onić polegli i upadli, a myśmy powstali, i ostoimy się. Panie! ty nas zachowaj, a król nas niech wysłucha w dzień wołania naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Przedniejszemu śpiewakowi pieśń Dawidowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Panie! w mocy twojej raduje się król, a w zbawieniu twojem wielce się weseli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Dałeś mu żądość serca jego, a prośby ust jego nie odmówiłeś mu. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Albowiemeś go uprzedził błogosławieństwy hojnemi; włożyłeś na głowę jego koronę ze złota szczerego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Prosił cię o żywot, a dałeś mu przedłużenie dni na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Wielka jest chwała jego w zbawieniu twojem; chwałą i zacnością przyodziałeś go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Boś go wystawił na rozmaite błogosławieństwo aż na wieki; rozweseliłeś go weselem oblicza twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Gdyż król nadzieję ma w Panu, a z miłosierdzia Najwyższego nie będzie poruszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Znajdzie ręka twoja wszystkich nieprzyjaciół twoich, prawica twoja dosięże wszystkich, co cię w nienawiści mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Uczynisz ich jako piec ognisty czasu gniewu twego; Pan w popędliwości swojej wytraci ich, a ogień ich pożre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Plemię ich z ziemi wygubisz, a nasienie ich z synów ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Albowiem czyhali na twoje złe; zmyślali radę, której dowieść nie mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Przetoż wystawisz ich za cel; cięciwę twą wyciągniesz przeciwko twarzy ich. Podnieśże się, Panie! w mocy twojej, tedy będziemy śpiewać i wysławiać możność twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Przedniejszemu śpiewakowi na czas poranny psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Boże mój! Boże mój! czemuś mię opuścił? oddaliłeś się od wybawienia mego, od słów ryku mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Boże mój! wołam we dnie, a nie ozywasz mi się; i w nocy, a nie mogę się uspokoić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Aleś ty Święty, mieszkający w chwałach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'W tobie nadzieję mieli ojcowie nasi; nadzieję mieli,a wybawiłeś ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Do ciebie wołali, a wybawieni są; w tobie nadzieję mieli, a nie byli pohańbieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Alem ja robak, a nie człowiek: pośmiewisko ludzkie, i wzgarda pospólstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Wszyscy, którzy mię widzą, szydzą ze mnie; wykrzywiają gębę, chwieją głową, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Spuścił się na Pana, niechże go wyrwie; niech go wybawi, ponieważ się w nim kocha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Aleś ty jest, któryś mię wywiódł z żywota, czyniąc mi dobrą nadzieję jeszcze u piersi matki mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Na tobie spolegam od narodzenia swego; z żywota matki mojej tyś Bogiem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Nie oddalajże się odemnie; albowiem utrapienie bliskie jest, a niemasz, ktoby ratował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Obtoczyło mię mnóstwo cielców; byki z Basan obległy mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Otworzyły na mię gębę swą jako lew szarpający i ryczący.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Rozpłynąłem się jako woda, a rozstąpiły się wszystkie kości moje; stało się serce moje jako wosk, zstopniało w pośród wnętrzności moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Wyschła jako skorupa moc moja, a język mój przysechł do podniebienia mego; nawet w prochu śmierci położyłeś mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Albowiem psy mię obskoczyły, gromada złośników obległa mię; przebodli ręce moje i nogi moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Zliczyłbym wszystkie kości moje; lecz oni na mię patrząc, przypatrują mi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Rozdzielili odzienie moje między się, a o szaty moje los miotali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Ale ty, Panie! nie oddalaj się: mocy moja! na ratunek mój pospiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Wyrwij od miecza duszę moję, z mocy psiej jedynaczkę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Wybaw mię z paszczęki lwiej, a od rogów jednorożcowych wyzwól mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Tedy opowiem imię twoje braciom mym; w pośród zgromadzenia chwalić cię będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Mówiąc: Którzy się boicie Pana, chwalcie go; wszystko potomstwo Jakóbowe wysławiajcie go, a niech się go boi wszystko nasienie Izraelskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Albowiem nie wzgardził, ani się odwrócił od utrapienia ubogiego, ani skrył od niego oblicza swego; owszem, gdy do niego wołał, wysłuchał go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'O tobie chwała moja w zgromadzeniu wielkiem; śluby moje oddam przed tymi, którzy się ciebie boją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Będą jeść ubodzy, i nasycą się; chwalić będą Pana, którzy go szukają; serce wasze żyć będzie na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Wspomną i nawrócą się do Pana wszystkie granice ziemi, i kłaniać się będą przed obliczem twojem wszystkie pokolenia narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Albowiem Pańskie jest królestwo, a on panuje nad narodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Wszyscy bogaci ziemi będą jeść, i upadać przed nim, przed oblicznością jego kłaniać się będą wszyscy zstępujący w proch, i którzy duszy swej żywo zachować nie mogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Nasienie ich służyć mu będzie, a będzie przywłaszczane Panu w każdym wieku. Zbieżą się, a będą opowiadali sprawiedliwość jego narodowi, który z nich wynijdzie, iż ją on wykonał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Psalm Dawidowy. Pan jest pasterzem moim, na niczem mi nie zejdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Na paszach zielonych postawił mię; a do wód cichych prowadzi mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Duszę moję posila: prowadzi mię ścieszkami sprawiedliwości dla imienia swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Choćbym też chodził w dolinie cienia śmierci, nie będę się bał złego, albowiemeś ty ze mną; laska twoja, i kij twój, te mię cieszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Przed obliczem mojem gotujesz stół przeciwko nieprzyjaciołom moim; pomazałeś olejkiem głowę moję, kubek mój jest opływający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Nadto dobrodziejstwo i miłosierdzie twe pójdą za mną po wszystkie dni żywota mego, a będę mieszkał w domu Pańskim na długie czasy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Psalm Dawidowy. Pańska jest ziemia, i napełnienie jej, okrąg ziemi, i którzy mieszkają na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Bo on na morzu ugruntował ją, a na rzekach utwierdził ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Któż wstąpi na górę Pańską? a kto stanie na miejscu świętem jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Człowiek niewinnych rąk i czystego serca, który nie skłania ku marności duszy swej, a nie przysięga zdradliwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Ten weźmie błogosławieństwo od Pana, i sprawiedliwość od Boga zbawiciela swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Tenci jest naród szukających go, szukających oblicza twego, Boże Jakóbowy! Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Podnieścież, o bramy! wierzchy wasze; podnieście się, wy bramy wieczne! aby wszedł król chwały!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Któryż to jest król chwały? Pan mocny i możny, Pan mocny w boju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Podnieścież, o bramy! wierzchy wasze; podnieście się, wy bramy wieczne! aby wszedł król chwały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Który to jest król chwały? Pan zastępów, tenci jest król chwały. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Psalm Dawidowy. Do ciebie, Panie! duszę moję podnoszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Boże mój! w tobie ufam; niech nie będę zawstydzony, niech się nie weselą nieprzyjaciele moi ze mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'A tak wszyscy, którzy oczekują ciebie, nie będą zawstydzeni; zawstydzeni będą bez przyczyny nieprawość czyniący.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Panie! daj mi poznać drogi twe, ścieżek twoich naucz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Daj, abym chodził w prawdzie twojej, i naucz mię; boś ty jest Bóg zbawienia mego; ciebie oczekuję dnia każdego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Wspomnij na litości twoje, Panie! i na miłosierdzia twoje, które są od wieku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Grzechów młodości mojej, i przestępstw moich nie racz pamiętać; według miłosierdzia twego wspomnij na mię, dla dobroci twojej, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Dobry i prawy jest Pan; przetoż drogi naucza grzeszników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Poprowadzi cichych w sądzie, a nauczy pokornych drogi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Wszystkie ścieżki Pańskie są miłosierdzie i prawda tym, którzy strzegą przymierza jego, i świadectwa jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Panie! dla imienia twego odpuść nieprawość moję, bo wielka jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Jestże człowiek, co się boi Pana? Nauczy go drogi, którąby miał obrać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Dusza jego w dobrem przemieszkiwać będzie, a nasienie jego odziedziczy ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Tajemnica Pańska objawiona jest tym, którzy się go boją, a przymierze swoje oznajmuje im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Oczy moje ustawicznie patrzą na Pana; albowiem on wywodzi z sieci nogi moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Wejrzyjże na mię, a zmiłuj się nademną; bom jest nędzny i opuszczony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Utrapienia serca mego rozmnożyły się; z ucisków moich wywiedź mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Obacz udręczenie moje, i pracę moję, a odpuść wszystkie grzechy moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Obacz nieprzyjaciół moich, jako się rozmnożyli, a mają mię niesłusznie w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Strzeż duszy mojej, a wyrwij mię, abym nie był pohańbiony; bo w tobie nadzieję mam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Niewinność i szczerość niech mię strzegą; bom na cię oczekiwał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'O Boże! wybawże Izraela ze wszystkich ucisków jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Psalm Dawidowy. Sądź mię, Panie! Boć ja w niewinności mojej chodzę, a w Panu ufając, nie zachwieję się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Spróbuj mię, Panie! i doświadcz mię: wypław ogniem nerki moje i serce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Albowiem miłosierdzie twoje jest przed oczyma mojemi, a będę chodził w prawdzie twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Nie zasiadałem z ludźmi kłamliwymi a z obłudnikami nie kumałem się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Nienawidziałem zgromadzenia złośników, a z niepobożnymi nie zasiadałem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Umyłem w niewinności ręce moje, a obchodzę w około ołtarz twój, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Abym ci oddawał chwałę głośną, a opowiadał wszystkie cuda twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Panie! umiłowałem mieszkanie domu twego, i miejsce przybytku chwały twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Nie zagarniajże z grzesznikami duszy mojej, ani z mężami krwawymi żywota mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'W których rękach jest przewrotność, a prawica ich pełna podarków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Ale ja w niewinności mojej chodzę: odkupże mię, a zmiłuj się nademną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Noga moja stanęła na równinie; w zgromadzeniach będę błogosławił Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Psalm Dawidowy. Pan jest światłością moją, i zbawieniem mojem, kogóż się bać będę? Pan jest mocą żywota mego, kogóż się mam lękać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Gdy się zbiorą przeciwko mnie złośnicy, aby pożarli ciało moje; przeciwnicy moi, i nieprzyjaciele moi sami się potknęli i upadli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Przetoż choćby wojsko przeciwko mnie stanęło, nie ulęknie się serce moje; choćby powstała przeciwko mnie wojna, przecież ja w tym ufam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'O jednem rzecz prosił Pana, i tej szukać będę; abym mieszkał w domu Pańskim po wszystkie dni żywota mego, a żebym oglądał wdzięczność Pańską, i dowiadywał się w kościele jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Bo mię skryje w dzień zły w przybytku swoim; zachowa mię w skrytości namiotu swego, a na skale wywyższy mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'A tak wywyższona będzie głowa moja nad nieprzyjaciołmi moimi, którzy są około mnie; i będę ofiarował w przybytku jego ofiary wykrzykania; będę śpiewał i chwały oddawał Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Wysłuchaj, Panie! głos mój, kiedy wołam, a zmiłuj się nademną, i wysłuchaj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'O tobie przemyśla serce moje, któryś rzekł: Szukajcie twarzy mojej; przetoż twarzy twojej, Panie! szukać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Nie ukrywajże twarzy twojej przedemną, ani odrzucaj w gniewie sługi twego; tyś bywał ratunkiem moim, nie opuszczajże mię, ani mię odstępuj, Boże zbawienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Choć ojciec mój, i matka moja opuścili mię, wszakże Pan przyjął mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Naucz mię, Panie! drogi twojej, a prowadź mnie ścieżką dla tych, którzy mię podstrzegają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Niepodawajże mię na wolę nieprzyjaciół moich; albowiemci powstali przeciwko mnie świadkowie fałszywi, i ten, który tchnie okrucieństwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Bym był nie wierzył, że mam oglądać dobroć Pańską w ziemi żyjących, źleby o mnie było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Oczekujże Pana, zmacniaj się, a on utwierdzi serce twoje; przetoż oczekuj Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Psalm Dawidowy. Do ciebie, Panie! wołam, skało moja! nie milcz na wołanie moje, bym snać, jeźli mi się nie ozwiesz, nie stał się podobnym zstępującym do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Wysłuchajże głos próśb moich, gdy wołam do ciebie, gdy podnoszę ręce moje do świątnicy świętej twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Nie zagarniaj mię z niezbożnymi, i z czyniącymi nieprawość, którzy mówią o pokoju z bliźnimi swymi a myślą złe w sercach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Oddajże im według spraw ich i według złych uczynków ich; według pracy rąk ich oddaj im, oddaj im zapłatę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Albowiem nie zrozumiewają spraw Pańskich, ani uczynków rąk jego; przetoż ich popsuje, a nie pobuduje ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Błogosławiony Pan; albowiem wysłuchał głos próśb moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Pan jest mocą moją i tarczą moją, w nim, nadzieję ma serce moje, a jestem poratowany; przetoż się rozweseliło serce moje, a pieśnią moją chwalić go będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Pan jest mocą swych, i mocą zbawienia pomazańca swego on jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Zbaw lud twój, Panie! a błogosław dziedzictwu twemu, i paś ich, i wywyższaj aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Psalm Dawidowy. Oddawajcie Panu synowie mocarzów, oddawajcie Panu chwałę i moc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Oddawajcie Panu chwałę imienia jego; kłaniajcie się Panu w ozdobie świętobliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Głos Pański nad wodami; Bóg chwalebny wzbudza gromy, Pan nad wodami wielkiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Głos Pański mocny, głos Pański wielmożny,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Głos Pański cedry łamie; kruszy Pan cedry Libańskie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'I czyni, że skaczą jako cielęta; Liban i Syryjon jako młody jednorożec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Głos Pański krzesze płomień ognisty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Na głos Pański z bólem pustynia rodzą; z bólem rodzi na głos Pański pustynai Kades.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Na głos Pański z bólem rodzą łanie, i odkrywają się lasy; ale w kościele swym opowiada wszystkę chwałę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Pan nad potopem siedział, i będzie siedział Pan, będąc królem na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Pan doda mocy ludowi swojemu; Pan będzie błogosławił ludowi swemu w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Psalm pieśni przy poświęceniu domu Dwidowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Panie! wywyższać cię będę; albowiem wywyższyłeś mię, a nie dałeś pociechy nieprzyjaciołom moim ze mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Panie, Boże mój! wołałem do ciebie, a uzdrowiłeś mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Panie! wywiodłeś z piekła duszę moję; zachowałeś mię przy żywocie, abym nie zstąpił do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Śpiewajcież Panu święci jego, a wysłuchajcie pamiątkę świętobliwości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Albowiem prędko przemija gniew jego, ale po wszystek żywot trwa dobra wola jego; z wieczora bywa płacz, ale z poranku wesele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Rzekłem w szczęściu swojem: Nie będę poruszony na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Albowiem ty, Panie! według woli twojej umocniłeś był górę moję mocą; ale skoroś ukrył oblicze swoje, strwożyłem się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'I wołałem do ciebie, Panie! a Panum się modlił, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Co za pożytek ze krwi mojej, gdybym zstąpił do dołu? Izali cię proch chwalić będzie? Iazali opowie prawdę twoję?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Wysłuchajże, Panie! a zmiłuj się nademną; Panie! bądź pomocnikiem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'Tedyś odmienił płacz mój w pląsanie; zdjąłeś ze mnie wór mój, a przepasałeś mię radością. Przetoż tobie śpiewać będzie chwała moja, a milczeć nie będzie. Panie, Boże mój! na wieki wysławiać cię będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'W tobie, Panie! nadzieję mam, niech nie będę zawstydzony na wieki; w sprawiedliwości twojej wybaw mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Nakłoń ku mnie ucha twego, co rychlej wybaw mię; bądźże mi mocną skałą, domem obronnym, abyś mię zachował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Boś ty jest skałą moją, i obroną moją; przetoż dla imienia twego prowadź mię, i zaprowadź mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Wywiedź mię z sieci, którą zastawili na mię; boś ty jest mocą moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'W ręce twoje poruczam ducha mego; odkupiłeś mię, Panie, Boże prawdziwy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Mam w nienawiści tych, którzy przestrzegają próżnych marności; bo ja w Panu nadzieję pokładam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Będę się radował i weselił w miłosierdziu twojem, żeś wejrzał na utrapienie moje, a poznałeś uciśnienie duszy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Aniś mię zawarł w ręce nieprzyjaciela; aleś postawił na przestrzeństwie nogi moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Zmiłuj się nademną, Panie! bom jest uciśniony; wywiędła od żałości twarz moja; także i dusza moja i żywot mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Albowiem zwątlało od boleści zdrowie moje, a lata moje od wzdychania; zemdlała dla utrapianie mego siła moja, a kości moje wyschły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'U wszystkich nieprzyjaciół moich jestem w pohańbieniu wielkiem, a najwięcej u sąsiadów moich; stałem się na postrach znajomym moim; którzy mię widzą na dworze, uciekają przedemną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Wypadłem z pamięci jako umarły; stałem się jako naczynie stłuczone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Albowiem nasłucham się uszczypków od wielu; strachu dość zewsząd, gdy się naradzają wespół przeciwko mnie, chytrze przemyśliwając, aby odjęli duszę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Ale ja w tobie mam nadzieję, Panie! Rzekłem: Tyś jest Bogiem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'W rękach twoich są czasy moje; wyrwijże mię z ręki nieprzyjaciół moich, i od tych, którzy mię prześladują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Oświeć oblicze twoje nad sługą twoim; wybaw mię przez miłosierdzie twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Panie! niech nie będę pohańbiony, ponieważ cię wzywam; niech się zawstydzą niezbożni, i zamilkną w grobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Niech zaniemieją wargi kłamliwe, które mówią przeciwko sprawiedliwemu rzeczy przykre z hardością i ze wzgardą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'O jakoż jest wielka dobroć twoja, którąś zachował bojącym się ciebie, którąś pokazywał tym, którzy ufają w tobie przed synami ludzkimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Ukrywasz ich w skrytości oblicza twego, przed hardością człowieczą ukrywasz ich, jako w namiocie, przed swarliwemi językami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Błogosławiony Pan! bo dziwnie okazał miłosierdzie swoje przeciwko mnie, jakoby w mieście obronnem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Jam rzekł w uciekaniu mojem: Odrzuconym jest od oczów twych; aleś ty wysłuchał głos modlitw moich, gdym wołał do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Miłujcież Pana wszyscy święci jego; boć Pan wiernych strzeże, oddaje sowicie hardzie postępującemu. Zmacniajcie się (a posili Bóg serca wasze) wszyscy, którzy nadzieję macie w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Pieśń Dawidowa nauczająca. Błogosławiony człowiek, któremu odpuszczono nieprawość, a którego zakryty jest grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Błogosławiony człowiek, któremu nie poczyta Pan nieprawości, a w którego duchu nie masz zdrady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Gdym milczał, schnęły kości moje w narzekaniu mojem na każdy dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Ponieważ we dnie i w nocy ociężała nademną ręka twoja, obróciła się wilgotność moja w suszę letnią. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'przetoż grzech mój oznajmiłem tobie, a nieprawości mojej nie kryłem. Rzekłem: Wyznam na się przestępstwa moje Panu, a tyś odpuścił nieprawość grzechu mego. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Oto się tobie będzie modlił każdy święty, czasu, którego możesz być znaleziony, a choć wzbiorą powodzi wód wielkich, przecież go nie dosięgną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Tyś jest ucieczką moją; od uciśnienia zachowasz mię, i piosnkami radosnego wybawienia uraczysz mię. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Dam ci rozum, i nauczę cię drogi, po której masz chodzić; dam ci radę, obróciwszy na cię oko moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Nie bądźcież jako koń, albo jako muł, którzy rozumu nie mają, których gęby uzdą i wędzidłem kiełznać musisz, aby się na cię nie porywały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Wiele boleści przypada na złośnika; ale ufającego w Panu miłosierdzie ogarnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Weselcie się w Panu, i radujcie się sprawiedliwi, a wykrzykajcie wszyscy, którzyście serca szczerego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Weselcie się w Panu sprawiedliwi; bo szczerym przystoi chwalić Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Wysławiajcie Pana na harfie, na lutni, na instrumencie o dziesięciu stronach, śpiewajcie mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Śpiewajcież mu piosnkę nową; dobrze mu i głośno grajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Albowiem szczere jest słowo Pańskie, i wszystkie sprawy jego wierne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Miłuje sąd i sprawiedliwość; pełna jest ziemia miłosierdzia Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Słowem Pańskiem są niebiosa uczynione, a Duchem ust jego wszystko wojsko ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Który zgromadził jako na kupę wody morskie, i złożył do skarbu przepaści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Niech się boi Pana wszystka ziemia; niech się go lękają wszyscy obywatele okręgu ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Albowiem on rzekł, i stało się; on rozkazał, a stanęło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Pan rozprasza rady narodów, a wniwecz obraca zamysły ludzkie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Ale rada Pańska trwa na wieki, a myśli serca jego od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Błogosławiony naród, którego Pan jest Bogiem jego; lud, który sobie obrał za dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Pan patrzy z nieba, i widzi wszystkich synów ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Z miejsca mieszkania swego spogląda na wszystkich obywateli ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Który stworzył serce każdego z nich, upatruje wszystkie sprawy ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Nie bywa król wybawiony przez wielkość wojska, ani mocarz nie ujdzie przez wielką moc swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Omylnyć jest koń ku wybawieniu, a nie wyrywa wielkością mocy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Oto oko Pańskie nad tymi, którzy się go boją, nad tymi, którzy ufają w miłosierdziu jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Aby wyrwał od śmierci duszę ich,a pożywił ich w głodzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Dusza nasza oczekuje Pana; on ratunek nasz i tarcza nasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'W nim zaprawdę rozweseli się serce nasze; bo w imieniu jego świętem ufamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Niechże będzie miłosierdzie twoje, Panie! nad nami, jakośmy nadzieję w tobie mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Psalm Dawidowy, gdy sobie odmienił postawę przed Abimelechem, od którego będąc wygnany, odszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Będę błogosławił Pana na każdy czas; zawżdy będzie chwała jego w ustach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'W Panu się chlubić będzie dusza moja, co usłyszawszy pokorni rozweselą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Wielbijcie Pana ze mną, a wywyższajmy imię jego społecznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Bom szukał Pana, i wysłuchał mię, a ze wszystkich strachów moich wyrwał mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Którzy nań spoglądają, a zbiegają się do niego, oblicza ich nie będą zawstydzone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Ten chudzina wołał, a Pan wysłuchał, i ze wszystkich ucisków jego wybawił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Zatacza obóz Anioł Pański około tych, którzy się go boją, i wyrywa ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Skosztujcież, a obaczcie, jako jest dobry Pan: błogosławiony człowiek, który w nim ufa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Bójcie się Pana święci jego; bo niemasz niedostatku bojącym się go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Lwięta niedostatek cierpią i głód; lecz szukającym Pana nie będzie schodziło na wszelkiem dobrem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Pójdźcież synowie, słuchajcie mię; bojaźni Pańskiej was nauczę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Któż jest, co chce długo żyć, a miłuje dni, aby widział dobra?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Strzeż języka twego od złego, a warg twoich, aby nie mówiły zdrady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Odwróć się od złego, a czyń dobrze; szukaj pokoju, a ścigaj go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Oczy Pańskie otworzone są na sprawiedliwych, a uszy jego na wołanie ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Ale oblicze Pańskie przeciwko tym, którzy broją złości, aby wykorzenił z ziemi pamiątkę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Wołają sprawiedliwi, a Pan ich wysłuchiwa, i ze wszystkich trudności ich wybawia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Bliski jest Pan tym, którzy są skruszonego serca, a utrapionych w duchu zachowuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Wiele złego przychodzi na sprawiedliwego; ale z tego wszystkiego wyrywa go Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'On strzeże wszystkich kości jego, tak, iż i jedna z nich nie skruszy się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Zabije złość niepobożnego, a którzy w nienawiści mają sprawiedliwego, będą spustoszeni; Ale Pan odkupi duszę sług swoich, a nie będą spustoszeni wszyscy, którzy w nim ufają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Psalm Dawidowy. Rozpieraj się, Panie! z tymi, którzy się ze mną spierają; a walcz przeciwko tym, którzy walczą przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Porwij pukierz i tarczę, a powstań na ratunek mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Dobądź włóczni, a staw się na drodze przeciwko tym, którzy mię prześladują. Rzeczże duszy mojej: Jam jest zbawieniem twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Niech będą pohańbieni i zawstydzeni, którzy szukają duszy mojej; niech tył podadzą, i niech będą zawstydzeni, którzy mi źle myślą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Niech będą jako plewy przed wiatrem, a Anioł Pański niechaj ich rozproszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Niech będzie droga ich ciemna i śliska, Anioł Pański niech ich goni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Albowiem bez przyczyny zastawili na mię w dole sieci swoje, i bez przyczyny ukopali dół duszy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Niechaj na nich przyjdzie spustoszenie, którego się nie spodziewali; a sieć ich, którą zastawili, niech ich ułowi na zginienie, a niech w nią wpadną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Ale dusza moja niech się rozraduje w Panu, niech się rozweseli w zbawieniu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Tedy wszystkie kości moje rzeką: Panie! któż podobny tobie? który wyrywasz utrapionego od mocniejszego nadeń, a nędznego i ubogiego od drapieżcy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Powstawają świadkowie fałszywi, a o czem nie wiem, pytają mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Oddawają mi złem za dobre, chcąc mię pozbawić duszy mojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Chociażem się ja w wór obłóczył, gdy oni chorowali; trapiłem postem duszę moję, i modliłem się często sam u siebie za nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Jako do przyjaciela, jako do brata mego, ustawiczniem chadzał; poniżałem się jako ten, który się smuci, chodząc po matce w żałobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Lecz oni, gdym ja chorował, weselili się, i zbierali się; zbierali się przeciwko mnie, jakoby byli dla mnie utrapieni, czegom ja nie spostrzegł; szczypali mię, a nie milczeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Z obłudnikami, z naśmiewcami, z pochlebcami zgrzytali na mię zębami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Panie! długoż na to patrzeć będziesz? wyrwijże duszę moję od zguby ich, od lwiąt jedynaczkę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Będę cię wysławiał w zgromadzeniu wielkiem; między ludem wielkim będę cię chwalił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Niech się nie weselą ze mnie, którzy mi są nieprzyjaciółmi bez przyczyny; którzy mię mają w nienawiści niesłusznie, niech nie mrugają okiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Albowiem nie mówią o pokoju; ale przeciwko spokojnym na ziemi zdradliwe słowa zmyślają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Owszem, rozdzierają na mię gębę swą, mówiąc: Ehej! ehej! widzić to oko nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Widzisz to, Panie! nie milczże Panie! nie oddalaj się odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Obudźże się, a ocuć dla sądu mego, Boże mój i Panie mój! dla sprawy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Sądź mnie według sprawiedliwości twojej, Panie Boże mój! a niech się nie weselą nademną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Niech nie mówią w sercu swojem: Ehej, duszo masza! niech nie mówią: Pożarliśmy go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Niechajże będą pohańbieni, i zawstydzeni wszyscy weselący się ze złego mego; niech będą obleczeni w hańbę, i w sromotę, którzy się chlubią przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Ale ci, którzy się kochają w sprawiedliwości mojej, niech śpiewają i radują się, a niech mówią ustawicznie: Niech będzie uwielbiony Pan, który życzy pokoju słudze swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'A język mój będzie opowiadał sprawiedliwość twoję, i na każdy dzień chwałę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Przedniejszemu śpiewakowi pieśń Dawida, sługi Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Przewrotność niepobożnego świadczy w sercu mojem: Niemasz bojaźni Bożej przed oczyma jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Bo sobie pobłaża w oczach swoich, aby wykonał nieprawość swoję aż do obmierzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Słowa ust jego są nieprawość i zdrada; nie chciał rozumieć, aby dobrze czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Nieprawość rozmyśla na łożu swojem, stoi na drodze nie dobrej, a złego się nie waruje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Panie! miłosierdzie twoje niebios sięga, prawda twoja aż pod obłoki,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Sprawiedliwość twoja, jako góry najwyższe; sądy twoje, jako przepaść wielka; ludzie i zwierzęta zachowuje, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Jakoż drogie jest miłosierdzie twoje, Boże! przetoż synowie ludzcy w cieniu skrzydeł twoich ufają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Będą upojeni hojnością domu twego, a strumieniem rozkoszy twoich napoisz ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Albowiem u ciebie jest źródło żywota, a w światłości twojej oglądamy światłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Rozciągnij miłosierdzie twoje nad tymi, którzy cię znają, a sprawiedliwość twoję nad uprzejmymi sercem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Niech nie następuje na mię noga pysznych, a ręka niepobożnych niech mię nie uwodzi. Tam, gdzie upadli, którzy czynili nieprawość, porażeni są, i nie mogli powstać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Pieśń Dawidowa. Nie obruszaj się dla złośników, ani zajrzyj czyniącym nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Bo jako trawa prędko podcięci będą, a jako liście zielone opadną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Ufaj w Panu, a czyń dobrze; mieszkajże na ziemi, a żyw się sprawiedliwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Kochaj się w Panu, a dać prośby serca twego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Spuść na Pana drogę twoję, a ufaj w nim, a on wszystko uczyni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'I wywiedzie jako światłość sprawiedliwość twoję, a sąd twój jako południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Poddaj się Panu, a oczekuj go; nie obruszaj się na tego, któremu się szczęści w sprawach jego, na człowieka, który dokazuje, cokolwiek zamyśli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Przestań gniewu, a zaniechaj popędliwości; nie zapalaj się gniewem, abyś miał źle czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Albowiem złośnicy będą wykorzenieni: lecz którzy oczekują Pana, ci odziedziczą ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Po małej chwili alić niemasz niezbożnika; spojrzyszli na miejsce jego, alić go już niemasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Lecz pokorni odziedziczą ziemię, i rozkochają się w wielkości pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Zle myśli niepobożny przeciwko sprawiedliwemu, i zgrzyta nań zębami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Ale się Pan śmieje z niego; bo widzi, że przychodzi dzień jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Miecza dobyli niezbożni, a naciągnęli łuk swój, aby porazili ubogiego, i niedostatecznego, ażeby pomordowali tych, którzy chodzą prostą drogą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Aleć miecz ich przeniknie serce ich, a łuki ich będą połamane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Lepsza jest trocha sprawiedliwego, niż wielkie bogactwa wielu niepobożnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Albowiem ramiona niezbożników będą pokruszone; ale sprawiedliwych Pan podpiera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Zna Pan dni doskonałych; przetoż dziedzictwo ich na wieki zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Nie będą zawstydzeni we zły czas, a we dni głodu będą nasyceni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Ale niezbożni poginą, a nieprzyjaciele Pańscy, jako tłustość barania z dymem niszczeje, tak oni zniszczeją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Niezbożnik pożycza, a nie ma czem oddać; ale sprawiedliwy pokazuje łaskę, i rozdaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Albowiem błogosławieni od Pana odziedziczą ziemię; ale przeklęci od niego będą wykorzenieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Od Pana bywają sprawowane drogi człowieka dobrego, a droga jego, podoba mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Gdy padnie, nie stłucze się: albowiem Pan trzyma go za rękę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Byłem młodym, i zstarzałem się, nie widziałem sprawiedliwego opuszczonego, ani nasienia jego żebrzącego chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Na każdy dzień pokazuje miłosierdzie i pożycza, a przecież nasienie jego jest w błogosławieństwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Odstąp od złego a czyń dobrze, a będziesz mieszkał na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Albowiem Pan miłuje sąd, a nie opuści świętych swoich, na wieki w straży jego będą; ale nasienie niepobożnych będzie wykorzenione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Sprawiedliwi odziedziczą ziemię, i będą w niej mieszkali na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Usta sprawiedliwego mówią mądrość, a język jego sąd opowiada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Zakon Boga jego jest w sercu jego; przetoż nie zachwieją się nogi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Wypatruje niepobożny sprawiedliwego, i szuka jakoby go zabił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Ale Pan nie zostawi go w ręku jego, i nie potępi go, gdy będzie sądzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Oczekuj Pana, i strzeż drogi jego, a on cię wywyższy, abyś odziedziczył ziemię; a oglądasz, gdy niepobożni, wytraceni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Widziałem niezbożnika nader wyniosłego, a rozłożonego jako drzewo zielone samorosłe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Ale przeminął, a oto go nie było; szukałem go, alem go znaleść nie mógł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Spojrzyj na niewinnego, a przypatrz się szczeremu, że ostatnie rzeczy takiego człowieka są spokojne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Lecz przestępcy pospołu poginą, a niezbożnicy na ostatek wykorzenieni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Wszakże zbawienie sprawiedliwych jest od Pana, który jest mocą ich czasu uciśnienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Wspomaga ich Pan, i wyrywa ich; wyrywa ich od niepobożnych, i zachowuje ich; bo w nim nadzieję mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Psalm Dawidowy ku przypominaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Panie! w popędliwości twojej nie nacieraj na mię, a w gniewie twoim nie karz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Albowiem strzały twoje utknęły we mnie, a ręka twoja dolega mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Niemasz nic całego w ciele mojem dla rozgniewania twego; niemasz odpoczynku kościom moim dla grzechu mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Bo nieprawości moje przycisnęły głowę moję; jako brzemię ciężkie obciążyły mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Zjątrzyły się, i pogniły rany moje, dla głupstwa mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Skurczyłem się, i skrzywiłem się bardzo, na każdy dzień w żałobie chodzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Albowiem wnętrzności moje pełne są brzydkości, a nie masz nic całego w ciele mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Zemdlałem, i startym jest bardzo, ryczę dla trwogi serca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Panie! przed tobą jest wszystka żądość moja, a wzdychanie moje przed tobą nie jest skryte.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Serce moje skacze; opuściła mię siła moja, a jasności oczów moich nie masz przy mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Którzy mię miłują, i przyjaciele moi, stronią od ran moich, a powinowaci moi z daleka stoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'I zastawili sidła ci, którzy szukają duszy mojej; a którzy mi szukają złego, mówili przewrotnie, i zdrady przez cały dzień zmyślali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Alem ja niby głuchy nie słyszał, a jako niemy, który ust swoich nie otwiera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'I stałem się jako człowiek, który nic nie słyszy, i niema odporu w ustach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Albowiem na cię, Panie! oczekuję; ty za mię odpowiesz, Panie, Boże mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Bom rzekł: Niechaj się nie cieszą ze mnie; gdyby szwankowała noga moja, niechaj się hardzie nie podnoszą przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Bom ja upadku bliski, a boleść moja zawżdy jest przedemną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Owszem, nieprawość moję wyznaję, a frasuję się dla grzechu mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Ale nieprzyjaciele moi weselą się, zmacniają się, i rozmnażają się ci, którzy mię nienawidzą bez przyczyny:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'A oddawając mi złem za dobre sprzeciwiają mi się, przeto, że naśladuję tego, co jest dobrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Nie opuszczajże mię, Panie, Boże mój! nie oddalajże się odemnie. Pośpiesz na ratunek mój, Panie zbawienia mego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Przedniejszemu śpiewakowi Jedytunowi psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Rzekłem: Będę strzegł dróg moich, abym nie zgrzeszył językiem swym; włożę munsztuk w usta moje, póki niepobożny będzie przedemną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Zaniemiałem milcząc; zamilknąłem i w dobrej sprawie; ale boleść moja bardziej się wzmagała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Rozpaliło się serce moje we wnętrznościach moich; w rozmyślaniu mojem rozżarzył się ogień, ażem tak rzekł językiem swoim:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Daj mi poznać, Panie! dokończenie moje, i wymiar dni moich jaki jest, abym wiedział, jak długo trwać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Otoś na dłoni wymierzył dni moje, a wiek mój jest jako nic przed tobą; zaprawdę szczerą marnością jest wszelki człowiek, choć najduższy. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Zaprawdę pomija człowiek jako cień; zaprawdę próżno się kłopocze, zgromadza, a nie wie, kto to pobierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'A teraz na cóż oczekuję, Panie? Tyś jest sam oczekiwaniem mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Przetoż od wszystkich przestępstw moich wybaw mię; na pośmiech głupiemu nie dawaj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Zaniemiałem, i nie otworzyłem ust moich, przeto, żeś to ty uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Odejmij odemnie karanie twoje; bom od smagania ręki twojej ustał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Gdy ty gromiąc karzesz człowieka dla nieprawości, wnet niszczysz jako mól grzeczność jego; zaisteć marnością jest wszelki człowiek. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Wysłuchajże modlitwę moję, Panie! a wołanie moje przyjmij w uszy swoje, nie milcz na łzy moje; bomci ja przychodniem u ciebie, i komornikiem, jako wszyscy ojcowie moi. Sfolguj mi, abym się posilił, pierwej niżeli odejdę, a nie będzie mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Z żądością oczekiwałem Pana; a skłonił się ku mnie, i wysłuchał wołanie moje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'I wyciągnął miecz z dołu szumiącego i z błota lgnącego, a postawił na skale nogi moje, i utwierdził kroki moje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'A włożył w usta moje pieśń nową, chwałę należącą Bogu naszemu, co gdy wiele ich ogląda, ulękną się, a będą mieć nadzieję w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Błogosławiony człowiek, który pokłada w Panu nadzieję swoję, a nie ogląda się na hardych, ani na tych, którzy się unoszą za kłamstwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Wieleś uczynił, Panie, Boże mój! cudów twoich, a myśli twoich o nas nikt porządnie wyliczyć nie może przed tobą; chciałlibym je wypowiedzieć i wymówić, daleko ich więcej, niżby wypowiedziane być mogły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Ofiary i obiaty nie chciałeś, aleś mi przekłół uszy; całopalenia i ofiary za grzech nie żądałeś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Tedym rzekł: Oto idę; w księgach napisano o mnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Abym czynił wolę twoję, Boże mój! pragnę, albowiem zakon twój jest w pośrodku wnętrzności moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Opowiadałem sprawiedliwość twoję w zgromadzeniu wielkiem; oto warg moich nie zawściągnąłem, ty wiesz, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Sprawiedliwości twojej nie ukryłem w pośród serca mego, prawdę twoję i zbawienie twoje opowiadałem; nie taiłem miłosierdzia twego i prawdy twojej w zgromadzeniu wielkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Przetoż ty, Panie! nie zawściągaj odemnie litości twoich; miłosierdzie twoje i prawda twoja niech mię zawżdy strzegą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Albowiem ogarnęły mię nieszczęścia, którym niemasz liczby; doścignęły mię nieprawości moje, tak, że przejrzeć nie mogę; rozmnożyły się nad włosy głowy mojej, a serce moje opuściło mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Raczże mię, Panie! wyrwać; o Panie! na ratunek mój pospiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Niech będą pohańbieni, (a niech się zawstydzą wszyscy,) którzy szukają duszy mojej, aby ją zatracili; niechajże się na wstecz cofną, a niech się zawstydzą, którzy mi życzą złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Niech będą spustoszeni za to, ze mię shańbić usiłują, mówiąc mi: Ehej! ehej!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Ale niech się rozradują i rozweselą w tobie wszyscy, którzy cię szukają, i miłują zbawienie twoje; niech mówią zawżdy: Niechaj będzie Pan uwielbiony. Jamci wprawdzie ubogi i nędzny; aleć Pan myśli o mnie. Tyś jest pomocnikiem moim i wybawicielem moim; Boże mój! nie omieszkujże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Przedniejszemu śpiewakowi pieśń Dawidowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Błogosławiony, który ma baczenie na potrzebnego; w dzień zły wybawi go Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Pan go będzie strzegł, i żywić go będzie; błogosławony będzie na ziemi, ani go poda na wolę nieprzyjaciół jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Pan go posili na łożu niemocy jego; wszystko leżenie jego odmieni w chorobie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Jam rzekł: Panie! zmiłuj się nademną, uzdrów duszę moję, bom tobie zgrzeszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Nieprzyjaciele moi mówili źle o mnie: Kiedyż wżdy umrze, a zginie imię jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Jeźli też który z nich przychodzi, aby mię nawiedził, tedy na zdradzie mówi; serce jego zgromadza sobie nieprawość, a precz odszedłszy roznosi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Społem przeciwko mnie szepczą wszyscy, którzy mię mają w nienawiści, a myślą złe o mnie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Mówiąc: Pomsta się nań za niezbożność wylała, a iż się położył, więcej nie wstanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Także i ten, z którymem żył w pokoju, któremum ufał, który chleb mój jadał, podniósł piętę przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Ale ty, Panie! zmiłuj się nademną, a podnieś mię, i oddam im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'A przez to poznam, że się kochasz we mnie, gdy się nie będzie weselił nieprzyjaciel mój ze mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Ale ty w niewinności mojej wesprzesz mię i postawisz mię przed obliczem twojem na wieki. Błogosławiony Pan, Bóg Izraelski, od wieku aż na wieki. Amen, Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Przedniejszemu śpiewakowi z synów Korego pieśń ćwicząca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Jako jeleń krzyczy do strumieni wód, tak dusza moja woła do ciebie, o Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Pragnie dusza moja do Boga, do Boga żywego, mówiąc: Kiedyż przyjdę, a okażę się przed obliczem Bożem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Łzy moje są mi miasto chleba we dnie i w nocy, gdy mi mówią co dzień: Kędyż jest Bóg twój?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Na to wspominając wylewam sam sobie duszę moję, żem bywał w poczcie innych, i chadzałem z nimi do domu Bożego, z wesołym głosem, i z chwałą, w mnóstwie weselących się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Przeczże się smucisz, duszo moja! a przecz sobą trwożysz we mnie? Czekaj na Boga; albowiem go jeszcze będę wysławiał za wielkie wybawienie twarzy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Boże mój! dusza moja tęskni sobie we mnie; przetoż na cię wspominam w ziemi Jordańskiej i Hermońskiej, na górze Mizar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Przepaść przepaści przyzywa, na szum upustów twoich: wszystkie powodzi twoje i nawałności twoje na mię się zwaliły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Wszakże we dnie udzieli mi Pan miłosierdzia swego, a w nocy piosnka jego będzie ze mną, i modlitwa do Boga żywota mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Rzekę Bogu, skale mojej: Przeczżeś mię zapomniał? I czemu smutno chodzę dla uciśnienia od nieprzyjaciela?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Jest jako rana w kościach moich, gdy mi urągają nieprzyjaciele moi, mówiąc do mnie na każdy dzień: Kędy jest Bóg twój? Przeczże się smucisz, duszo moja? a przecz sobą trwożysz we mnie? Czekaj na Boga; albowiem go jeszcze będę wysławiał, gdyż on jest wielkiem zbawieniem twarzy mojej, i Bogiem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Sądź mię, o Boże! a ujmij się o sprawę moję; od narodu niemiłosiernego, i od człowieka zdradliwego i niezbożnego wyrwij mię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Boś ty jest Bóg siły mojej. Przeczżeś mię odrzucił? a przecz smutno chodzę dla uciśnienia od nieprzyjaciela?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Ześlij światłość twoję, i prawdę twoję; te mię poprowadzą, i wprowadzą mię na świętą górę twoję, i do przybytków twoich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Abym przystąpił do ołtarza Bożego, do Boga wesela i radości mojej; i będę cię wysławiał na harfie, o Boże, Boże mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Przeczże się smucisz, duszo moja, a przecz trwożysz sobą we mnie? Czekaj na Boga, albowiem go jeszcze będę wysławiał, gdyż on jest wielkiem zbawieniem twarzy mojej, i Bogiem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Przedniejszemu śpiewakowi z synów Korego psalm nauczający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Boże! uszami naszemi słyszeliśmy; ojcowie nasi powiadali nam o sprawach, któreś czynił za dni ich, za dni starodawnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Tyś ręką swą wypędził pogan, a onycheś wszczepił; wytraciłeś narody, a onycheś rozkrzewił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Bo nie przez miecz swój posiedli ziemię, i ramię ich nie wybawiło ich, ale prawica twoja i ramię twoje, a światłość oblicza twego, przeto, żeś ich upodobał sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Tyś sam król mój, o Boże! sprawże wielkie wybawienie Jakóbowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Przez cię nieprzyjaciół naszych porażaliśmy; w imieniu twojem deptaliśmy powstawających przeciwko nam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Bom w łuku moim nie ufał, ani miecz mój obronił mię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Aleś nas ty wybawiał od nieprzyjaciół naszych, a nienawidzących nas zawstydzałeś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Przetoż chlubimy się w tobie, Boże! na każdy dzień, a imię twoje na wieki wysławiamy. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Ale teraz odrzuciłeś i zawstydziłeś nas, a nie wychodzisz z wojskami naszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Sprawiłeś, żeśmy tył podali nieprzyjacielowi, a ci, którzy nas mają w nienawiści, rozchwycili między się dobra nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Podałeś nas jako owce na żer, a między pogan rozproszyłeś nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Sprzedałeś lud twój za nic, a nie podniosłeś ceny ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Podałeś nas na wzgardę sąsiadom naszym, na szyderstwo i na pośmiech tym, którzy są około nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Wystawiłeś nas na przypowieść między poganami, tak, że nad nami narody głową kiwają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Na każdy dzień wstyd mój jest przedemną, a hańba twarzy mojej okrywa mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Dla głosu tego, który mię sromoci i potwarza, dla nieprzyjaciela, i tego, który się mści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'To wszystko przyszło na nas; a wżdyśmy cię nie zapomnieli, aniśmy wzruszyli przymierza twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Nie cofnęło się nazad serce nasze, ani się uchyliły kroki nasze od ścieżki twojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Chociażeś nas był potarł, wrzuciwszy nas na miejsce smoków, i okryłeś nas cieniem śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'Byśmyć byli zapomnieli imienia Boga naszego, a podnieśli ręce nasze do Boga cudzego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Iazliby się był Bóg o tem nie pytał? gdyż on wie skrytości serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Aleć nas dla ciebie zabijają na każdy dzień; poczytają nas jako owce na rzeź zgotowane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Ocuć się; przeczże śpisz, Panie! Przebudź się, nie odrzucaj nas na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Przeczże oblicze twoje ukrywasz, a zapominasz utrapienia naszego i ucisku naszego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Albowiem potłoczona jest aż do prochu dusza nasza, a przylgnął do ziemi żywot nasz. Powstańże na ratunek nasz, a odkup nas dla miłosierdzia twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Przedniejszemu śpiewakowi z synów Korego na Sosannim psalm nauczający, a pieśń weselna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Wydało serce moje słowo dobre; rozprawiać będę pieśni moje, o królu! język mój będzie jako pióro prędkiego pisarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Piękniejszyś nad synów ludzkich; rozlała się wdzięczność po wargach twoich, przeto, że cię pobłogosławił Bóg aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Przypasz miecz twój na biodra, o mocarzu! pokaż chwałę twoję, i zacności twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'A w dostojności twojej szczęśliwie wywiedź z słowem prawdy, cichości, i sprawiedliwości, a dokaże strasznych rzeczy prawica twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Strzały twoje ostre; od nich narody pod cię upadną, a serce nieprzyjaciół królewskich przenikną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Stolica twoja, o Boże! na wieki wieków; laska sprawiedliwości jest laska królestwa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Umiłowałeś sprawiedliwość, a nienawidziłeś nieprawości; przetoż pomazał cię, o Boże! Bóg twój olejkiem wesela nad uczęstników twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Myrrą, aloe, i kassyją wszystkie szaty twoje pachną, gdy wychodzisz z pałaców z kości słoniowych urobionych, nad tych, którzy cię uweselają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Córki królewskie są między twemi zacnemi białemi głowami; stanęła małżonka po prawicy twojej w kosztownem złocie z Ofir.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Słuchajże córko, a obacz, i nakłoń ucha twego, a zapomnij narodu twego, i domu ojca twojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'A zakocha się król w piękności twojej, albowiem on jest Panem twoim; przetoż kłaniaj się przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Tyryjczycy także z upominkami przed obliczem twojem kłaniać się będą, najbogatsi z narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Wszystka zacność córki królewskiej jest wewnątrz, a szaty jej bramowane są złotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'W odzieniu haftowanem przywiodą ją do króla; także panny za nią, towarzyszki jej, przywiodą do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Przywiodą je z weselem i z radością, a wnijdą na pałac królewski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Miasto ojców twych będziesz mieć synów twych, których postanowisz książętami po wszystkiej ziemi. Wspominać będę imię twoje od każdego rodzaju do rodzaju: dlatego cię narody wysławiać będą na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Przedniejszemu śpiewakowi z synów Korego, na Alamot pieśń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Bóg jest ucieczką i siłą naszą, ratunkiem we wszelkim ucisku najpewniejszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Przetoż się bać nie będziemy, choćby się poruszyła ziemia, choćby się przeniosły góry w pośród morza;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Choćby zaszumiały, a wzburzyły się wody jego, i zatrzęsły się góry od nawałności jego. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Strumienie rzeki jego rozweselają miasto Boże, najświętsze z przybytków najwyższego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Bóg jest w pośrodku jego, nie będzie poruszone;poratuje go Bóg zaraz z poranku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Gdy się wzburzyły narody, a zatrząsnęły się królestwa, Pan wydał głos swój, i rozpłynęła się ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Pan zastępów jest z nami; twierdzą wysoką jest nam Bóg Jakóbowy. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Pójdźcie, oglądajcie sprawy Pańskie, jakie uczynił spustoszenie na ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Który uśmierza wojny aż do kończyn ziemi, łuk kruszy, i oręże łamie, a wozy ogniem pali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Mówiąc: Uspokójcie się, a wiedzcie, żem Ja Bóg; będę wywyższony między narodami, będę wywyższony na ziemi. Pan zastępów z nami; twierdzą wysoką jest nam Bóg Jakóbowy. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Przedniejszemu śpiewakowi z synów Korego pieśń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Wszystkie narody klaskajcie rękoma, wykrzykajcie Bogu głosem wesela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Albowiem Pan najwyższy, straszny, jest królem wielkim nad wszystką ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Podbija ludzi pod moc naszę, a narody pod nogi nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Obrał nam za dziedzictwo nasze chwałę Jakóba, którego umiłował. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Wstąpił Bóg z krzykiem; Pan wstąpił z głosem trąby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Śpiewajcież Bogu, śpiewajcie; śpiewajcież królowi naszemu, śpiewajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Albowiem Bóg królem wszystkiej ziemi; śpiewajcież rozumnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Króluje Bóg nad narodami; Bóg siedzi na świętej stolicy swojej. Książęta narodów przyłączyli się do ludu Boga Abrahamowego; albowiem Boże są tarcze ziemskie; skąd on zacnie jest wywyższony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Pieśń psalmu synów Korego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Wielki jest Pan, i bardzo chwalebny w mieście Boga naszego, na górze świętej swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Ozdobą krainy, uciechą wszystkiej ziemi jest góra Syon w stronach północnych, miasto króla wielkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Bóg w pałacach jego uznany jest za twierdzę wysoką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Bo oto królowie, gdy się zgromadzili i ciągnęli wespół,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Sami to ujrzawszy bardzo się zadziwili, a przestraszeni będąc prędko uciekali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Strach ich tam ogarnął i boleść, jako niewiastę rodzącą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Wiatrem wschodnim pokruszysz okręty z Tarsys.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Jakośmy słyszeli,takeśmy widzieli w mieście Pana zastępów, w mieście Boga naszego; Bóg je ugruntował aż na wieki. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Uważamy, o Boże! miłosierdzie twoje w pośród kościoła twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Jakie jest imię twoje, Boże! taka też jest chwała twoja aż do kończyn ziemi; sprawiedliwości pełna jest prawica twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'NIech się rozweseli góra Syon: niech się rozradują córki Judzkie dla sądów twoich, Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Otoczcie Syon, i obstąpcie go; policzcie wieże jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Przypatrujcie się pilnie basztom jego, a oglądajcie pałace jego, abyście umieli powiadać narodowi potomnemu. Że ten Bóg jest Bogiem naszym na wieki wieczne, a iż on naszym hetmanem będzie aż do śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Przedniejszemu śpiewakowi z synów Korego psalm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Słuchajcie tego wszystkie narody; bierzcie to w uszy wszyscy mieszkający na okręgu ziemi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Tak z ludu pospolitego, jako z ludzi zacnych, tak bogaty jako ubogi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Usta moje będą opowiadały mądrość, a myśl serca mego roztropność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Nakłonię do przypowieści ucha mego, wyłożę przy harfie zagadkę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Przeczże się mam bać we złe dni, aby mię nieprawość tych, którzy mię depczą, miała ogarnąć?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Którzy ufają bogactwom swoim, a w mnóstwie dostatków swoich chlubią się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Gdyż brata swego nikt żadnym sposobem nie odkupi, ani może dać Bogu okupu jego zań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, '(Albowiem drogi jest okup duszy ich, i nie może się ostać na wieki.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Aby żył na wieki, a nie oglądał grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Bo widzimy, iż i mądrzy umierają, głupi i szalony zarówno giną, a zostawiają, obcym bogactwa swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'Myślą, że domy ich są wieczne, a przybytki ich trwają od narodu do narodu; przetoż je nazywają od imion swych na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Ale człowiek we czci nie zostaje, podobnym będąc bydlętom, które giną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Takowa myśl ich głupstwem ich jest, a przecież potomkowie ich pochwalają to usty swemi. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Jako owce w grobie złożeni będą, śmierć ich strawi; ale sprawiedliwi panować będą nad nimi z poranku, a kształt ich zniszczony będzie w grobie, gdy ustąpią z mieszkania swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Ale Bóg wykupi duszę moję z mocy grobu, gdy mię przyjmie. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Nie bójże się, gdy się kto zbogaci, a gdy się rozmnoży sława domu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Bo umierając nie weźmie nic z sobą, ani za nim zstąpi sława jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'A choć duszy swej za żywota swego pobłaża i chwalono go, gdy sobie dobrze czynił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Przecież musi iść za rodziną ojców swych, a na wieki nie ogląda światłości. Owóż człowiek, który jest we czci, a nie zrozumiewa tego, podobny jest bydlętom, które giną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Psalm Asafowi podany. Bóg nad Bogami, Pan mówił i przyzwał ziemię od wschodu słońca aż do zachodu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Objaśnił się Bóg z Syonu w doskonałej ozdobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Przyjdzie Bóg nasz, a nie będzie milczał; ogień przed twarzą jego będzie pożerał, a około niego powstanie wicher gwałtowny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Przyzwie z góry niebiosa i ziemię, aby sądził lud swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Mówiąc: Zgromadźcie mi świętych moich, którzy ze mną uczynili przymierze przy ofierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Tedy niebiosa opowiedzą sprawiedliwość jego; albowiem sam Bóg jest sędzią. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Słuchaj, ludu mój! a będę mówił; słuchaj, Izraelu! a oświadczę się przed tobą: Jam Bóg, Bóg twój Jam jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Nie będę cię z ofiar twoich winił, ani całopalenia twego, które są zawsze przedemną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Nie wezmę z domu twojego cielca, ani z okołu twego kozłów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Albowiem mój jest wszelki zwierz leśny, i tysiące bydła po górach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Znam wszystko ptastwo po górach, i zwierz polny jest przedemną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Będęli łaknął, nie rzekęć o to; bo mój jest okrąg ziemi, i napełnienie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Izali jadam mięso wołowe? albo pijam krew kozłową?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Ofiaruj Bogu chwałę, i oddaj Najwyższemu śluby twoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'A wzywaj mię w dzień utrapienia: tedy cię wyrwę, a ty mię uwielbisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Lecz niezbożnemu rzekł Bóg: Cóżci do tego, że opowiadasz ustawy moje, a bieżesz przymierze moje w usta twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Ponieważ masz w nienawiści karność, i zarzuciłeś słowa moje za się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Widziszli złodzieja, bieżysz z nim, a z cudzołożnikami masz skład twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Usta twoje rozpuszczasz na złe, a język twój składa zdrady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Zasiadłszy mówisz przeciwko bratu twemu, a lżysz syna matki twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Toś czynił, a Jam milczał; dlategoś mniemał, żem ja tobie podobny, ale będę cię karał, i stawięć to przed oczy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Zrozumiejcież to wżdy teraz, którzy zapominacie Boga, bym was snać nie porwał, a nie będzie ktoby was wyrwał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Kto mi ofiaruje chwałę, uczci mię; a temu, który naprawia drogę swą, ukażę zbawienie Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Gdy do niego przyszedł Natan prorok, potem jak był wszedł do Betsaby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Zmiłuj się nademną, Boże! według miłosierdzia twego; według wielkich litości twoich zgładź nieprawości moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Omyj mię doskonale od nieprawości mojej, a od grzechu mego oczyść mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Albowiem ja znam nieprawość moję, a grzech mój przedemną jest zawżdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Tobie, tobiem samemu zgrzeszył, i złem przed oczyma twemi uczynił, abyś był sprawiedliwy w mowie twojej, i czystym w sądzie twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Oto w nieprawości poczęty jestem, a w grzechu poczęła mię matka moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Oto się kochasz w prawdzie wewnętrznej, a skrytą mądrość objawiłeś mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Oczyść mię, isopem, a oczyszczon będę; omyj mię, a nad śnieg wybielony będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Daj mi słyszeć radość i wesele, a niech się rozradują kości moje, któreś pokruszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Odwróć oblicze twoje od grzechów moich, a zgładź wszystkie nieprawości moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Serce czyste stwórz we mnie, o Boże! a ducha prawego odnów we wnętrznościach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Nie odrzucaj mię od oblicza twego, a Ducha swego świętego nie odbieraj odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Przywróć mi radość zbawienia twego, a duchem dobrowolnym podeprzyj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Tedy będę nauczał przestępców dróg twoich, aby się grzesznicy do ciebie nawrócili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Wyrwij mię z pomsty za krew, o Boże, Boże zbawienia mojego! a język mój będzie wysławiał sprawiedliwość twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Panie! otwórz wargi moje, a usta moje opowiadać będą chwałę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Albowiem nie pragniesz ofiar, choćbym ci je dał, ani całopalenia przyjmiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Ofiary Bogu przyjemne duch skruszony; sercem skruszonem i strapionem nie pogardzisz, o Boże! Dobrze uczyń według upodobania twego Syonowi; pobubuj mury Jeruzalemskie. Tedy przyjmiesz ofiary sprawiedliwości, ofiary ogniste, i całopalenia; tedy cielce ofiarować będą na ołtarzu twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Przedniejszemu śpiewakowi pieśń Dawidowa nauczająca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Gdy przyszedł Doeg Edomczyk, i oznajmił Saulowi, mówiąc: Dawid przyszedł do domu Achimelechowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Przeczże się chlubisz ze złości, o mocarzu! miłosierdzie Boże trwa każdego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Złe rzeczy myśli język twój, jako brzytwa ostra czyniąc zdradę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Umiłowałeś złe, bardziej niż dobre; kłamstwo raczej mówisz, niż sprawiedliwość. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Umiłowałeś wszystkie słowa szkodliwe, i język zdradliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Przetoż cię Bóg zniszczy na wieki; porwie cię, i wyrwie cię z przybytku, i wykorzeni cię z ziemi żyjących. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'To widząc sprawiedliwi będą się bali, i będę się z niego naśmiewali, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Otoż człowiek, który nie pokładał w Bogu siły swojej; ale ufając w mnóstwie bogactw swoich, zmacniał się w złości swej. Aleć ja będę jako oliwa zielona w domu Bożym, bom nadzieję położył w miłosierdziu Bożem na wieki wieczne. Będę cię wysławiał, Panie! na wieki, żeś to uczynił, a będę oczekiwał imienia twego, gdyż jest zacne przed oblicznością świętych twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Przedniejszemu śpiewakowi na Machalat pieśń Dawidowa nauczająca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Głupi rzekł w sercu swem: Niemasz Boga. Popsowali się, i obrzydliwą czynią nieprawość; niemasz, ktoby czynił dobrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Bóg z niebios spojrzał na synów ludzkich, aby obaczył, byłliby kto rozumny i szukający Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Aleć oni wszyscy odstąpili, jednako się nieużytecznymi stali: niemasz, ktoby czynił dobrze, niemasz, i jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Azaż nie wiedzą wszyscy czyniciele nieprawości, że pożerają lud mój, jako więc chleb jedzą? ale Boga nie wzywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Tam się bardzo ulękną, gdzie niemasz strachu; albowiem Bóg rozproszy kości tych, którzy cię oblegli; ty ich pohańbisz, bo ich Bóg wzgardzi. Któż da z Syonu wybawienie Izraelowi? Gdy Bóg przywróci z więzienia lud swój, rozraduje się Jakób, rozweseli się Izrael.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Przedniejszemu śpiewakowi na Neginot pieśń Dawidowa nauczająca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Gdy przyszli Zyfejczycy, i rzekli do Saula: Dawid się kryje przed tobą u nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Boże! dla imienia twego wybaw mię, a w mocy twojej podejmij się sprawy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Boże! wysłuchaj modlitwę moję; przyjmij w uszy słowa ust moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Albowiem obcy powstali przeciwko mnie, a okrutnicy szukają duszy mojej, nie stawiając sobie Boga przed oczyma swemi. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Oto Bóg jest pomocnikiem moim: Pan jest z tymi, którzy podpierają żywot mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Oddaj złym nieprzyjaciołom moim, w prawdzie twojej wytrać ich, o Panie! Tedyć dobrowolnie będę ofiarował; będę wysławiał imię twoje, Panie! przeto, że jest dobre; Gdyż z każdego utrapienia wyrwałeś mię, a pomstę nad nieprzyjaciołmi mymi oglądało oko moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Przedniejszemu śpiewakowi na Neginot pieśń Dawidowa nauczająca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'W uszy swe przyjmij, o Boże! modlitwę moję, a nie kryj się przed prośbą moją:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Posłuchaj mię z pilnością, a wysłuchaj mię; boć się uskarżam w modlitwie swej, i trwożę sobą:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Dla głosu nieprzyjaciela, i dla uciśnienia od bezbożnika; albowiem mię zarzucają kłamstwem, a w popędliwości swej sprzeciwiają mi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Serce moje boleje we mnie, a strachy śmierci przypadły na mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Bojaźń ze drżeniem przyszła na mię, a okryła mię trwoga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'I rzekłem: Obym miał skrzydła jako gołębica, zaleciałbym, a odpocząłbym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Otobym daleko zaleciał, a mieszkałbym na puszczy. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Pospieszyłbym, abym uszedł przed wiatrem gwałtownym, i przed wichrem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Zatrać ich, Panie! rozdziel język ich; bom widział bezprawie i rozruch w mieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'We dnie i w nocy otaczają ich po murach jego, a złość i przewrotność jest w pośrodku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Ciężkości są w pośrodku jego, a nie ustępuje z ulic jego chytrość i zdrada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Albowiem nie nieprzyjaciel jaki zelżył mię, inaczej zniósłbym to był; ani ten, który mię miał w nienawiści, powstał przeciwko mnie; bobym się wżdy był skrył przed nim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Ale ty, człowiecze mnie równy, wodzu mój, i znajomy mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Którzyśmy się z sobą mile w tajności naradzali, i do domu Bożego społecznie chadzali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Oby ich śmierć z prędka załapiła, tak aby żywo zstąpili do piekła! albowiem złość jest w mieszkaniu ich, i w pośrodku ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Ale ja do Boga zawołam, a Pan mię wybawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'W wieczór i rano, i w południe modlić się, i z trzaskiem wołać będę, aż wysłucha głos mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Odkupi duszę moję, abym był w pokoju od wojny przeciwko mnie; bo ich wiele było przy mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Wysłucha Bóg i utrapi ich, (jako ten, który siedzi od wieku.Sela.) przeto, że nie masz w nich poprawy, ani się Boga boją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Wyciągnął ręce swoje na tych, którzy z nim mieli pokój, wzruszył przymierze swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Gładsze niż masło były słowa ust jego, ale walka w sercu jego: a mię kciejsze słowa jego niż olej, wszakże były jako miecze dobyte:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Wrzuć na Pana brzemię twoje, a on cię opatrzy, i nie dopuści, aby się na wieki zachwiać miał sprawiedliwy. Ale ich ty, o Boże! wepchniesz w dół zginienia; mężowie krwawi i zdradliwi nie dojdą do połowy dni swoich; ale ja w tobie nadzieję mieć będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Przedniejszemu śpiewakowi o niemej gołębicy, na miejscach odległych, złoty psalm Dawidowy, gdy go w Gat Filistynowie pojmali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Zmiłuj się nademną, o Boże!, bo mię chce pochłonąć człowiek; każdego dnia walcząc trapi mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Chcą mię połknąć nieprzyjaciele moi na każdy dzień; zaprawdęć wiele jest walczących przeciwko mnie, o Najwyższy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Któregokolwiek mię dnia strach ogarnia, ja w tobie ufam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Boga wysławiać będę dla słowa jego; w Bogu nadzieję będę miał, ani się będę bał, żeby mi co ciało uczynić mogło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Przez cały dzień słowa moje wykręcają, a przeciwko mnie są wszystkie myśli ich, na złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Zbierają się, i ukrywają się, i ślad mój upatrują, czyhając na duszę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Izali za nieprawość pomsty ujdą? strąć te narody, o Boże! w popędliwości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Tyś tułanie moje policzył; zbierzże też łzy moje w wiadro twe; izaż nie są spisane w księgach twoich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Tedy się nazad cofną nieprzyjaciele moi, któregokolwiek dnia zawołam; bo to wiem, iż Bóg jest ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'Boga wysławiać będę z słowa; Pana chwalić będę z słowa jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'W Bogu mam nadzieję, nie będę się bał, aby mi co miał uczynić człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Tobiem, o Boże! śluby uczynił; przetoż też tobie chwały oddam. Albowiemeś wyrwał duszę moję od śmierci, a nogi moje od upadku, abym statecznie chodził przed obliczem Bożem w światłości żyjących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Przedniejszemu śpiewakowi, jako: Nie zatracaj, złoty psalm Dawidowy, kiedy uciekał przed Saulem do jaskini.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Zmiłuj się nademną, o Boże! zmiłuj się nademną; albowiem w tobie ufa dusza moja, a do cienia skrzydeł twoich uciekam się; aż przeminie utrapienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Będę wołał do Boga najwyższego, do Boga, który wykonywa sprawę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'On pośle z nieba, i wybawi mię od pohańbienia tego, który mię chce pochłonąć. Sela. Pośle mi Bóg miłosierdzie swoje i prawdę swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Dusza moja jest w pośród lwów; leżę miedzy palącymi, między synami ludzkimi, których zęby jako włócznie i strzały, i język ich miecz ostry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Wywyżże się nad niebiosa, o Boże! a nade wszystką ziemią chwała twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Sieci zastawili na nogi moje, nachylili duszę moję, wykopali dół przed obliczem mojem; ale sami wpadli weń. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Gotowe jest serce moje, Boże! gotowe jest serce moje; śpiewać i wychwalać cię będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Ocuć się chwało moja! ocuć się, lutnio i harfo! gdy na świtaniu powstaję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Będę cię wysławiał między ludem, Panie! a będęć śpiewał między narodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Albowiem wielkie jest aż do niebios miłosierdzie twoje, i aż pod obłoki prawda twoja. Wywyżże się nad niebiosa, o Boże! a nade wszystką ziemię wywyż chwałę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Przedniejszemu śpiewakowi, jako: Nie zatracaj, pieśń złota Dawidowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'O zgromadzenie! Izali poprawdzie sprawiedliwość mówicie? A uprzejmież sądzicie, wy synowie ludzcy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Owszem, radniej w sercu nieprawości knujecie, a gwałty rąk waszych na ziemi odważacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Odłączyli się niezbożnicy zaraz od narodzenia; pobłądzili zaraz z żywota matki swej, mówiąc kłamstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Jad mają w sobie, jako wężowy, jako jad żmii głuchej, która zatula ucho swoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Aby nie słyszała głosu zaklinacza, ani czarownika w czarach biegłego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'O Boże! pokruszże zęby ich w ustach ich; połam, Panie! lwiąt trzonowe zęby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Niech się rozpłyną jako woda, niech się wniwecz obrócą; niech będą jako ten, który naciąga łuk, wszakże się strzały jego łamią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Jako ślimak, który schodzi i niszczeje; jako martwy płód niewieści niech nie oglądają słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Ciernie wasze pierwej niż wypuszczą tarny swoje, za zielona w gniewie Bożym jako wichrem porwane będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'I będzie się weselił sprawiedliwy, gdy ujrzy pomstę; nogi swoje umyje we krwi niepobożnego. I rzecze każdy: Zaprawdęć sprawiedliwy odniesie pożytek z sprawiedliwości swojej; zaisteć jest Bóg, który sądzi na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Przedniejszemu śpiewakowi, jako: Nie zatracaj, złota pieśń Dawidowa, gdy posłał Saul, aby strzeżono domu jego, a zabito go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Wyrwij mię od nieprzyjaciół moich, o Boże mój! a od powstawających przeciwko mnie uczyń mię bezpiecznym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Wyrwij mię od tych, którzy broją nieprawość, a od mężów krwawych wybaw mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Albowiem oto czyhają na duszę moję; zbierają się przeciwko mnie mocarze bez przestępstwa mego i bez grzechu mego, o Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Bez wszelkiej nieprawości mojej zbiegają się, i gotują się; powstańże, zabież mi, a obacz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Ty sam, Panie, Boże zastępów, Boże Izraelski! ocuć się, abyś nawiedził te wszystkie narody; a nie miej litości nad żadnym z onych przestępców złośliwych. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Nawracają się pod wieczór, a warczą jako psy, i biegają około miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Oto blegocą usty swemi, miecze są w wargach ich; albowiem mówią: Któż słyszy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Ale ty, Panie! naśmiewasz się z nich; naśmiewasz się ze wszystkich narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Gdy on moc przewodzi, na ciebie pozór mieć będę; boś ty, Boże! twierdzą moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Bóg mój miłosierny uprzedzi mię; Bóg mi da oglądać pomstę nad nieprzyjaciółmi mymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Nie zabijajże ich, aby nie zapomniał lud mój; ale ich rozprosz mocą twoją, i zrzuć ich, tarczo nasza, o Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Grzech ust swych, słowa warg swych (pojmani będąc w hardości swej dla złorzeczeństwa i kłamstwa) niech wyznawają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Wytraćże ich w popędliwości, wytrać ich, aż ich nie stanie. Niech poznają, że Bóg panuje w Jakóbie, i po krajach ziemi. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'I niech się zaś nawrócą pod wieczór; niech warczą jako psy, a biegają około miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Niech oni ciekają, chcąc się najeść, wszakże głodni będąc ukłaść się muszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Ale ja będę śpiewał o mocy twojej; zaraz z poranku wysławiać będę miłosierdzie twoje; boś ty był twierdzą moją, i ucieczką w dzień ucisku mego. O mocy moja! tobie będę śpiewał; boś ty, Boże! twierdza moja, Bóg mój miłosierny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Przedniejszemu śpiewakowi na Sussanedut złota pieśń Dawidowa do nauczania;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Gdy walczył przeciw Syryjczykom Nacharaim, i przeciw Syryjczykom Soby; gdy się wrócił Joab, poraziwszy Edomczyków w dolinie solnej dwanaście tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Boże! odrzuciłeś nas, rozproszyłeś nas, i rozgniewałeś się; nawróćże się zasię do nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Zatrząsnąłeś był ziemią, i rozsadziłeś ją; uleczże rozpadliny jej, boć się chwieje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Okazywałeś ludowi twemu przykre rzeczy, napoiłeś nas winem zawrotu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Ale teraz dałeś chorągiew tym, którzy się ciebie boją, aby ją wynieśli dla prawdy twej. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Aby byli wybawieni umiłowani twoi; zachowajże ich prawicą twoją, a wysłuchaj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Bóg ci mówił w świętobliwości swojej; przeto się rozweselę, rozdzielę Sychem, i dolinę Sukkotską pomierzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Mojeć jest Galaad, mój i Manases, i Efraim moc głowy mojej; Juda zakonodawcą moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Moab miednicą do umywania mego; na Edoma wrzucę buty moje; ty, Palestyno! wykrzykaj nademną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Któż mię wprowadzi do miasta obronnego? kto mię przyprowadzi aż do Edom?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Izali nie ty, o Boże! któryś nas był odrzucił, a nie wychodziłeś, Boże! z wojskami naszemi? Dajże nam ratunek w utrapieniu; boć omylny ratunek ludzki. W Bogu mężnie sobie poczynać będziemy, a on podepcze nieprzyjaciół naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Przedniejszemu śpiewakowi na Neginot pieśń Dawidowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Wysłuchaj, o Boże! wołanie moje, miej pozór na modlitwę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Od końca ziemi wołam do ciebie w zatrwożeniu serca mego; wprowadź mię na skałę, która jest wywyżą nad mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Albowiemeś ty był ucieczką moją, i basztą mocną przed twarzą nieprzyjaciela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Będę mieszkał w przybytku twoim na wieki, schraniając się pod zasłonę skrzydeł twoich. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Albowiemeś ty, Boże! wysłuchał żądości moje; tyś dał dziedzictwo tym, którzy się boją imienia twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Dni do dni królewskich przydaj; niech będą lata jego od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Niech mieszka na wieki przed obliczem Bożem; zgotuj miłosierdzie i prawdę, niech go strzegą. Tak będę śpiewał imieniowi twemu na wieki, a śluby moje oddawać będę na każdy dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Przedniejszemu śpiewakowi Jedytunowi psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Tylko na Boga spolega dusza moja, od niegoć jest zbawienie moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Tylkoć on jest skałą moją i wybawieniem mojem, twierdzą moją; przeto się bardzo nie zachwieję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Dokądże będziecie myślić złe przeciwko człowiekowi? Wszyscy wy zabici będziecie; będziecie jako ściana pochylona, a jako mur walący się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Przecież jednak radzą, jakoby go zepchnąć z dostojeństwa jego; kochają się w kłamstwie, usty swemi dobrorzeczą, ale w sercu swem złorzeczą. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Ty przecież na Bogu spolegaj, duszo moja! bo od niego jest oczekiwanie moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Onci sam jest skałą moją zbawieniem mojem, i twierdzą moją; przetoż nie zachwieję się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'W Bogu wybawienie moje, i chwała moja skała mocy mojej; nadzieja moja jest w Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Ufajcież w nim na każdy czas, o narody! Wylewajcie przed obliczem jego serca wasze: Bóg jest ucieczką naszą. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Zaprawdęć marnością są synowie ludzcy, kłamliwi synowie mocarzy; będąli pospołu włożeni na wagę, lekciejszymi będą nad marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Nie ufajcież w krzywdzie ani w drapiestwie, a nie będźcie marnymi; przybędzieli wam majętności, nie przykładajcież serca do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Razci rzekł Bóg, dwakrociem to słyszał, iż moc jest Boża, A że Panie! twoje jest miłosierdzie, a że ty oddasz każdemu według uczynków jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Psalm Dawidowy, gdy był na puszczy Judzkiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Boże! tyś jest Bogiem moim; z poranku cię szukam; pragnie cię dusza moja, tęskni po tobie ciało moje w ziemi suchej i upragnionej, w której nie masz wody;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Abym cię oglądał w świątnicy twojej, i widział moc twoję i chwałę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, '(Albowiem lepsze jest miłosierdzie twoje, niż żywot,) aby cię chwaliły wargi moje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Abym cię błogosławił za żywota mego, a w imieniu twojem abym podnosił ręce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Jako tłustością i sadłem byłaby tu nasycona dusza moja, a radosnem warg śpiewaniem wychwalałyby cię usta moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Zaprawdęć na cię wspominam, i na łożu mojem każdej straży nocnej rozmyślam o tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Boś mi bywał na pomocy; przetoż w cieniu skrzydeł twoich śpiewać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Przylgnęła dusza moja do ciebie; prawica twoja podpiera mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Ale ci, którzy szukają upadku duszy mojej, sami wnijdą do najgłębszej niskości ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Zabije każdego z nich ostrość miecza, i przyjdą liszkom na podział. Lecz król będzie się weselił w Bogu, a będzie się chlubił każdy, kto przezeń przysięga; albowiem zatkane będą usta mówiących kłamstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Wysłuchaj, o Boże! głos mój, gdy się modlę; od strachu nieprzyjaciela strzeż żywot mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Skryj mię przed skrytą radą złośników, przed zbuntowaniem czyniących nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Którzy zaostrzyli język swój jako miecz, nałożyli strzałę swoję, słowo jadowite,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Aby strzelali z skrytości na niewinnego; niespodzianie nań strzelają, a nikogo się nie boją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Stwierdzają się w złem; zmawiają się, jakoby zakryć sidłą, i mówią: Któż je obaczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Szukają pilnie nieprawości; giniemy od rad zdradliwie wynalezionych. Takci wnętrzność i serce człowiecze głębokie jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Ale gdy Bóg na nich wypuści prędką strzałę, porażeni będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'A do upadku przywiedzie ich własny język ich; odłączy się od nich każdy, kto ich ujrzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'I ulękną się wszyscy ludzie, a będą opowiadali sprawę Bożą, i dzieło jego zrozumieją. Ale sprawiedliwy się będzie weselił w Panu, a będzie w nim ufał; i będą się chlubili wszyscy, którzy są uprzejmego serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Przedniejszemu śpiewakowi psalm i pieśń Dawidowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Tobie przynależy, o Boże! chwała na Syonie, a tobie ślub ma być oddany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Ty wysłuchiwasz modlitwy; przetoż do ciebie przychodzi wszelkie ciało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Wielkie nieprawości, które wzięły górę nad nami, i przestępstwa nasze ty oczyszczasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Błogosławiony, kogo ty obierasz a przyjmujesz, aby mieszkał w sieniach twoich; będziemy nasyceni dobrami domu twego, w świątnicy kościoła twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Przedziwne rzeczy podług sprawiedliwości mówisz do nas, Boże zbawienia naszego, nadziejo wszystkich krajów ziemi, i morza dalekiego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Który utwierdzasz góry mocą swoją, siłą przepasany będąc;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Który uśmierzasz szum morski, szum nawałności jego, i wzruszenie narodów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Tak, że się bać muszą cudów twoich, którzy mieszkają na krajach ziemi; których nastawaniem poranku i wieczora do wesela pobudzasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Nawiedzasz ziemię, i odwilżasz ją; obficie ją ubogacasz strumieniem Bożym, napełnionym wodami, i gotujesz zboże ich, gdy ją tak przyprawiasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Zagony jej napawasz, bruzdy jej zniżasz, dżdżami ją odmiękczasz, a urodzajom jej błogosławisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Koronujesz rok dobrocią twą, a ścieżki twoje skrapiasz tłustością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Skrapiasz pastwiska na pustyniach; tak, że i pagórki radością przepasane bywają. Przyodziewają się pola stadami owiec, a doliny okrywają się zbożem; tak, że wykrzykają i śpiewają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Przedniejszemu śpiewakowi pieśń psalmu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Wykrzykuj Bogu wszystka ziemo! Śpiewajcież psalmy na chwałę imienia jego, ogłaszajcie sławę i chwałę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Rzeczcież Bogu: Jakoś straszny w sprawach twoich! Dla wielkości mocy twojej obłudnieć się podadzą nieprzyjaciele twoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Wszystkać się ziemia kłaniać, i śpiewać ci będzie; psalm śpiewać będzie imieniowi twemu. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Pójdźcież, a oglądajcie sprawy Boże; straszny jest w sprawach swoich przy synach ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Obrócił morze w ziemię suchą; rzekę przeszli suchą nogą; tameśmyć się weselili w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Panuje w mocy swej na wieki; oczy jego patrzą na narody, odporni nie wywyższą się. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Błogosławcież narody Boga naszego, i ogłaszajcie głos chwały jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Zachował przy zdrowiu duszę naszę, a nie dał się powinąć nodze naszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Albowiemeś nas doświadczył, o Boże! wypławiłeś nas ogniem, tak jako srebro pławione bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Nagnałeś nas był w sieć, a ścisnąłeś uciskiem biodra nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Wsadziłeś człowieka na głowę naszę; weszliśmy byli w ogień i w wodę, wszakżeś nas wywiódł na ochłodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Przetoż wnijdę do domu twego z całopaleniem, a oddam ci śluby moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Któreć ślubowały wargi moje, i wyrzekły usta moje w utrapieniu mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Całopalenie z tłustych baranów będęć ofiarował z kadzeniem, będęć ofiarował woły i kozły. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Pójdźcie, słuchajcie, a będę opowiadał wszystkim, którzy się boicie Boga, co uczynił duszy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Do niegom usty swemi wołał, a wywyższałem go językiem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Bym był patrzał na nieprawość w sercu mojem, nie wysłuchałby był Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Aleć zaiste wysłuchał Bóg, a był pilen głosu modlitwy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Błogosławiony Bóg, który nie odrzucił modlitwy mojej, ani odjął miłosierdzia swego odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Przedniejszemu śpiewakowi na Neginot psalm ku śpiewaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Boże! zmiłuj się nad nami, a błogosław nam, rozświeć oblicze twoje nad nami. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Aby tak poznali na ziemi drogę twoję, a po wszystkich narodach zbawienie twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Tedy cię będą wysławiały narody o Boże! Będą cię wysławiać wszyscy ludzie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Radować się będą i wykrzykać narody; bo ty będziesz sądził ludzi w sprawiedliwości, a narody będziesz sprawował na ziemi. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Będą cię wysławiać narody, o Boże! Będą cię wysławiać wszyscy ludzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Ziemia także wyda urodzaj swój; niech nam błogosławi Bóg, Bóg nasz. Niech nam błogosławi Bóg, a niech się go boją wszystkie kraje ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy ku śpiewaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Powstanie Bóg, a będą rozproszeni nieprzyjaciele jego, i pouciekają przed twarzą jego ci, którzy go mają w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Jako bywa dym rozpędzony, tak ich rozpędzasz: jako się wosk rozpływa od ognia, tak niezbożnicy poginą przed obliczem Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Ale sprawiedliwi weselić się i radować będą przed obliczem Bożem, i pląsać będą od radości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Śpiewajcie Bogu, śpiewajcie psalmy imieniowi jego; gotujcie drogę temu, który jeździ na obłokach. Pan jest imię jego, radujcież się przed obliczem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Ojcem jest sierót, i sędzią wdów, Bogiem w przybytku swym świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Bóg, który samotne w rodowite domy rozmnaża, wywodzi więźniów z oków; ale odporni mieszkać muszą w ziemi suchej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Boże! gdyś wychodził przed obliczem ludu twego, gdyś chodził po puszczy; Sela,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Ziemia się trzęsła, także i niebiosa rozpływały się przed obliczem Bożem, i ta góra Synaj drżała przed twarzą Boga, Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Deszcz obfity spuszczałeś hojnie, o Boże! na dziedzictwo twoje, a gdy omdlewało, tyś je zaś otrzeźwiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Zastępy twoje mieszkają w niem, któreś ty dla ubogiego nagotował dobrocią twoją, o Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Pan dał słowo swe, i tych, którzy pociechy zwiastowali, zastęp wielki mówiących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Królowie z wojskami uciekali, uciekali: ale ta, która przyglądała domu, dzieliła łupy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Chociażeście leżeć musieli między kotłami, przecież będziecie jako gołębica, mająca pióra posrebrzone, a której skrzydła jako żółte złoto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Gdy Wszechmogący rozproszy królów w tej ziemi, wybielejesz jako śnieg na górze Salmon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Na górze Bożej, na górze Basańskiej, na górze pogórczystej, na górze Basańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Przeczże wyskakujecie góry pogórczyste? na tejci górze ulubił sobie Bóg mieszkanie, tamci Pan będzie mieszkał na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Wozów Bożych jest dwadzieścia tysięcy, wiele tysięcy Aniołów; ale Pan między nimi jako na Synaj w świątnicy przebywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Wstąpiłeś na wysokość, wiodłeś pojmanych więźniów, nabrałeś darów dla ludzi, i najodporniejszych, Panie Boże! przywiodłeś, aby mieszkali z nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Błogosławiony Pan; na każdy dzień hojnie nas opatruje dobrami swemi Bóg zbawienia naszego. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'On jest Bóg nasz, Bóg obfitego zbawienia; panujący Pan z śmierci wywodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Zaiste Bóg zrani głowę nieprzyjaciół swoich, i wierzch głowy włosami nakryty chodzącego w grzechach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Rzekł Pan: Wyprowadzę zaś swoich jako z Basan, wywiodę ich zaś z głębokości morskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Przetoż będzie noga twoja zbroczona we krwi, i język psów twoich we krwi nieprzyjacielskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Widzieli ciągnienia twoje, Boże! ciągnienia Boga mego i króla mego w świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Wprzód szli śpiewacy, a za nimi grający na instrumentach, a w pośrodku panienki bijąc w bębny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'W zgromadzeniach błogosławcie Bogu, błogosławcie Panu, którzyście z narodu Izraelskiego. Tu niech będzie Benjamin maluczki, który ich opanował;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Tu książęta Judzcy, i hufy ich, książęta Zabulońscy, i książęta Neftalimscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Obdarzył cię Bóg twój siłą; utwierdź, o Boże! to, coś w nas sprawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Dla kościoła twego, który jest w Jeruzalemie, będąć królowie dary przynosić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Poraź poczet kopijników, zgromadzenie mocnych wodzów, i ludu bujnego, hardych, chlubiących się kęsem srebra; rozprosz narody pragnące wojny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Przyjdąć zacni książęta z Egiptu: Murzyńska ziemia pospieszy się wyciągnąć ręce swe do Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Królestwa ziemi! śpiewajcież Bogu, śpiewajcie Panu. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Temu, który jeździ na najwyższych niebiosach od wieczności; oto wydaje głos swój, głos mocy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Przyznajcie moc Bogu, nad Izraelem dostojność jego, a wielmożność jego na obłokach. Strasznyś jest, o Boże! z świętych przybytków twoich; Bóg Izraelski sam daje moc i siły ludowi swemu. Niechajże będzie Bóg błogosławiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Przedniejszemu śpiewakowi na Sosannim psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Wybaw mię, o Boże! boć przyszły wody aż do duszy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Pogrążony jestem w głębokiem błocie, gdzie dna niemasz; przyszedłem w głębokości wód, a nawałność ich porwała mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Spracowałem się wołając, wyschło gardło moje; ustały oczy moje, gdym oczekiwał Boga mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Więcej jest tych, którzy mię mają w nienawiści bez przyczyny, niż włosów na głowie mojej; zmocnili się ci, którzy mię wygubić usiłują, a są nieprzyjaciółmi mymi niesłusznie; czegom nie wydarł, musiałem nagradzać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Boże! ty znasz głupstwo moje, a występki moje nie są tajne przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Niechajże nie będą zawstydzeni dla mnie ci, którzy na cię oczekują, Panie, Panie zastępów! niech nie przychodzą dla mnie do hańby ci, którzy cię szukają, o Boże Izraelski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Bo dla ciebie ponoszę urąganie, a zelżywość okryła oblicze moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Stałem się obcym braciom moim, a cudzoziemcem synom matki mojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Przeto, że gorliwość domu twego zżarła mię, a urąganie urągających tobie przypadło na mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Gdym płakał i trapił postem duszę moję, stało mi się to pohańbienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Gdym wziął na się wór miasto szaty, byłem u nich przypowieścią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Mówili o mnie ci, którzy siedzieli w bramie, a byłem piosnką u tych, którzy pili mocny napój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Ale ja obracam modlitwę moję do ciebie, Panie! czas jest upodobania twego; o Boże! według wielkości miłosierdzia twego wysłuchajże mię, dla prawdy zbawienia twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Wyrwij mię z błota, abym nie był pogrążony; niech będę wyrwany od tych, którzy mię nienawidzą, jako z głębokości wód;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Aby mię nie zatopiły strumienie wód, i nie pożarła głębia i nie zawarła nademną studnia wierzchu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Wysłuchajże mię, Panie! boć dobre jest miłosierdzie twoje; według wielkiej litości twojej wejrzyj na mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Nie zakrywajże oblicza twego od sługi swego, bom jest w utrapieniu; pośpieszże się, wysłuchaj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Przybliż się do duszy mojej, a wybaw ją; dla nieprzyjaciół moich odkup mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Ty znasz pohańbienie moje, i zelżywość moję, i wstyd mój: przed tobąć są wszyscy nieprzyjaciele moi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Pohańbienie pokruszyło serce moje, z czegom był żałośny; oczekiwałem, azaliby się mię kto użalił, ale nikt nie był; azaliby mię kto pocieszył, alem nie znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Owszem, miasto pokarmu podali mi żółć, a w pragnieniu mojem napoili mię octem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Niechajże im będzie stół ich przed nimi sidłem, a szczęście ich na upadek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Niech się zaćmią oczy ich, aby nie widzieli, a biodra ich niech się zawżdy chwieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Wylij na nich rozgniewanie swoje, a popędliwość gniewu twego niech ich ogarnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Niech będzie mieszkanie ich puste, w namiotach ich niech nikt nie mieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Bo tego, któregoś ty ubił, prześladują, a o boleści poranionych twoich rozmawiają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Przydajże nieprawość ku nieprawości ich, a niech nie przychodzą do sprawiedliwości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Niech będą wymazani z ksiąg żyjących, a z sprawiedliwymi niech nie będą zapisani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Jamci utrapiony, i zbolały; lecz zbawienie twoje, Boże! na miejscu bezpiecznem postawi mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Tedy będę chwalił imię Boże pieśnią, a będę je wielbił z dziękczynieniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'A będzie to przyjemniejsze Panu, niżeli wół albo cielec rogaty z rozdzielonemi kopytami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'To widząc pokorni rozradują się, szukając Boga, a ożyje serce ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Iż wysłuchiwa Pan ubogich, a więźniami swymi nie gardzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Niech go chwalą niebiosa i ziemia, morze i wszystko, co się w nich rucha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Bógci zaiste zachowa Syon, i pobuduje miasta Judzkie; i będą tam mieszkać, a ziemię tę dziedzicznie otrzymają. Także i nasienie sług jego dziedzicznie ją otrzyma, a którzy miłują imię jego, będą w niej mieszkać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy na wspominamie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Boże! pospiesz się, abyś mię wyrwał; Panie! pospiesz się, abyś mi dał ratunek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Niech będą zawstydzeni i pohańbieni, którzy szukają duszy mojej; niech się obrócą na wstecz, i niech będą pohańbieni, którzy mi złego życzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Niech się obrócą nazad za to, że mię chcą pohańbić ci, którzy mi mówią: Ehej, ehej!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Ale niech się weselą i radują w tobie wszyscy, którzy cię szukają, a którzy miłują zbawienie twoje, niech mówią zawżdy: Uwielbiony bądź, Boże nasz! Jamci nędzny i ubogi; o Boże! pospiesz się ku mnie; tyś jest pomocą moją, i wybawicielem moim! Panie! nie omieszkujże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'W tobie, Panie! nadzieję mam: niech na wieki pohańbiony nie będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Według sprawiedliwości twej wybaw mię, i wyrwij mię; nakłoń ku mnie ucha twego, i zachowaj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Bądź mi skałą mieszkania, gdziebym zawżdy uchodził;przykazałeś, aby mię strzeżono; boś ty skałą moją i twierdzą moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Boże mój! wyrwij mię z ręki niezbożnika, z ręki przewrotnego i gwałtownika;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Albowiemeś ty oczekiwaniem mojem, Panie! Panie! nadziejo moja od młodości mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Na tobiem spoległ zaraz z żywota; tyś mię wywiódł z żywota matki mojej; w tobie chwała moja zawżdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Jako dziwowisko byłem u wielu; wszakże tyś jest mocną nadzieją moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Niechaj będą napełnione usta moje chwałą twoją, przez cały dzień sławą twoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Nie odrzucajże mię w starości mojej; gdy ustanie siła moja, nie opuszczaj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Albowiem mówili nieprzyjaciele moi przeciwko mnie, a ci, którzy czyhali na duszę moję, radę uczynili społem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Mówiąc: Bóg go opuścił, gońcież go, a pojmijcie go; boć nie ma, ktoby go wyrwał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Boże! nie oddalajże się odemnie; o Boże mój! pospieszże się na ratunek mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Niechże będą zawstydzeni, niech zginą przeciwnicy duszy mojej; niech będą okryci zelżywością i wstydem, którzy mi szukają złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Aleć ja zawżdy oczekiwać będę, a tem więcej rozszerzę chwałę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Usta moje opowiadać będą sprawiedliwość twoję, cały dzień zbawienie twoje, aczkolwiek liczby jego nie wiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Przystąpię do wysławiania wszelakiej mocy Pana panującego, będę wspominał własną sprawiedliwość twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Boże! uczyłeś mię od młodości mojej, i opowiadam aż po dziś dzień dziwne sprawy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'A przetoż aż do starości i sędziwości nie opuszczaj mię, Boże! aż opowiem ramię twoje temu narodowi, i wszystkim potomkom moc twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Bo sprawiedliwość twoja, Boże! wywyższona jest, czynisz zaiste rzeczy wielkie. Boże! któż jest podobien tobie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Który, acześ przypuścił na mię wielkie i ciężkie uciski, wszakże zasię do żywota przywracasz mię, a z przepaści ziemskich zasię wywodzisz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Rozmnożysz dostojność moję a zasię ucieszysz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'A ja też wysławiać cię będę na instrumentach muzycznych, i prawdę twoję, Boże mój! będęć śpiewał przy harfie, o Święty Izraelski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Rozradują się wargi moje, gdyć będę śpiewał, i dusza moja, którąś wykupił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Nadto i język mój będzie opowiadał przez cały dzień sprawiedliwość twoję; bo się zawstydzić, i hańbę odnieść musieli ci, którzy szukali nieszczęścia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Salomonowi. Boże! daj królowi sądy twoje, a sprawiedliwość twoję synowi królewskiemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Aby sądził lud twój w sprawiedliwości, a ubogich twoich w prawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Przyniosą góry ludowi pokój, a pagórki sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Będzie sądził ubogich z ludu, a wybawi synów ubogiego; ale gwałtownika pokruszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Będą się bać ciebie, póki słońce i miesiąc trwać będzie, od narodu aż do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Jako zstępuje deszcz na pokoszoną trawę, a deszcz kroplisty skrapiający ziemię:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Tak sprawiedliwy zakwitnie za dni jego, a będzie obfitość pokoju, dokąd miesiąca staje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Będzie panował od morza aż do morza, i od rzeki aż do kończyn ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Przed nim padać będą mieszkający na pustyniach, a nieprzyjaciele jego proch lizać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Królowie od morza i z wysep dary mu przyniosą; królowie Sebejscy i Sabejscy upominki oddadzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'I będą mu się kłaniać wszyscy królowie; wszystkie narody służyć mu będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Albowiem wyrwie ubogiego wołającego, i nędznego, który nie ma pomocnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Zmiłuje się nad ubogim, i nad niedostatecznym, a duszę nędznych wybawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Od zdrady i gwałtu wybawi duszę ich; bo droga jest krew ich przed oczyma jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'I będzie żył, a dawać mu będą złoto sabejskie, i ustawicznie się za nim modlić będą, cały dzień błogosławić mu będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Gdy się wrzuci garść zboża do ziemi na wierzchu gór, zaszumi jako Liban urodzaj jego, a mieszczanie zakwitną jako zioła polne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Imię jego będzie na wieki; pokąd słońce trwa, dziedziczyć będzie imię jego, a błogosławiąc sobie w nim wszystkie narody wielbić go będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Błogosławiony Pan Bóg, Bóg Izraelski, który sam cuda czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'I błogosławione imię chwały jego na wieki, a niech będzie napełniona chwałą jego wszystka ziemia. Amen, Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'A tuć się kończą modlitwy Dawida, syna Isajego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Psalm Asafowy. Zaisteć dobry jest Bóg Izraelowi, tym, którzy są czystego serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Ale nogi moje mało się były nie potknęły, a blisko tego było, że mało nie szwankowały kroki moje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Gdym był zawiścią poruszon przeciwko szalonym, widząc szczęście niepobożnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Bo nie mają związków aż do śmierci, ale w całości zostaje siła ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'W pracy ludzkiej nie są, a kaźni, jako inni ludzie, nie doznawają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Przetoż otoczeni są pychą, jako łańcuchem złotym, a przyodziani okrutnością, jako szatą ozdobną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Wystąpiły od tłustości oczy ich, a więcej mają nad pomyślenie serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Rozpuścili się, i mówią złośliwie, o uciśnieniu bardzo hardzie mówią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Wystawiają przeciwko niebu usta swe, a język ich krąży po ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'A przetoż na to przychodzi lud jego, gdy się im wody już wierzchem leją,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Że mówią:Jakoż ma Bóg o tem wiedzieć? albo mali o tem wiadomość Najwyższy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Albowiem, oto ci niezbożnymi będąc, mają pokój na świecie, i nabywają bogactw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Próżno tedy w czystości chowam ręce moje, a w niewinności serce moje omywam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Ponieważ mię cały dzień biją, a karanie cierpię na każdy poranek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Rzekęli: Będę też tak o tem mówił, tedy rodzaj synów twoich rzecze, żem im niepraw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Chciałemci tego rozumem doścignąć, ale mi się tu trudno zdało;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Ażem wszedł do świątnicy Bożej, a tum porozumiał dokończenie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Zprawdęś ich na miejscach śliskich postawił, a podajesz ich na spustoszenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Oto jakoć przychodzą na spustoszenie! niemal w okamgnieniu niszczeją i giną od strachu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Są jako sen temu, co ocucił; Panie! gdy ich obudzisz obraz ich lekce poważysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Gdy zgorzkło serce moje, a nerki moje cierpiały kłucie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Zgłupiałem był, a nicem nie rozumiał, byłem przed tobą jako bydlę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'A wszakże zawżdy byłem z tobą; boś mię trzymał za prawą rękę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Według rady swej prowadź mię, a potem do chwały przyjmiesz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Kogożbym innego miał na niebie? I na ziemi oprócz ciebie w nikim innym upodobania nie mam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Choć ciało moje, i serce moje ustanie, jednak Bóg jest skałą serca mego, i działem moim na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Gdyż oto ci, którzy się oddalają od ciebie, zginą; wytracasz tych, którzy cudzołożą odstępowaniem od ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Aleć mnie najlepsza jest trzymać się Boga; przetoż pokładam w Panu panującym nadzieję moję, abym opowiadał wszystkie sprawy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Pieśń wyuczająca, podana Asafowi. Przeczżeś nas, o Boże! do końca odrzucił? Przeczże się rozpaliła zapalczywość twoja przeciwko owcom pastwiska twego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Wspomnij na zgromadzenie twoje, któreś sobie zdawna nabył i odkupił, na pręt dziedzictwa twego, na tę górę Syon, na której mieszkasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Pospieszże się na srogie popustoszenie; a jako wszystko poburzył nieprzyjaciel w świątnicy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Ryczeli nieprzyjaciele twoi w pośrodku zgromadzenia twego, a na znak tego zostawili wiele chorągwi swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Za rycerza miano tego, który się z wysoka z siekierą zanosił, rąbiąc drzewo wiązania jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'A teraz już i rzezania jego na porząd siekierami i młotami tłuką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Założyli ogień w świątnicy twojej, a obaliwszy na ziemię, splugawili przybytek imienia twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Mówili w sercu swojem: Zburzmy je pospołu; popalili wszystkie przybytki Boże w ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Znaków naszych nie widzimy:już niemasz proroka, i niemasz między nami, któryby wiedział, póki to ma trwać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Dokądże, o Boże! przeciwnik będzie urągać? izali nieprzyjaciel będzie bluźnił imię twoje aż na wieki?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Przeczże zstrzymujesz rękę twoję; a prawicy swej z zanadrza swego cale nie dobędziesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Wszakeś ty, Boże! zdawna królem moim; ty sprawujesz hojne zbawienie w pośród ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Tyś mocą twoją rozdzielił morze, a potarłeś głowy wielorybów w wodach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Tyś skruszył głowę Lewiatana, dałeś go za pokarm ludowi na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Tyś przerwał źródła i potoki; tyś osuszył rzeki bystre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Twójci jest dzień, twoja też i noc; tyś uczynił światło i słońce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Tyś założył wszystkie granice ziemi; lato i zimę tyś sprawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Wspomnijże na to, że nieprzyjaciel zelżył Pana, a lud szalony jako urąga imieniowi twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Nie podawajże tej kupie duszy synogarlicy twojej; na stadko ubogich twoich nie zapominaj na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Obejrzyj się na przymierze twoje; albowiem i najciemniejsze kąty ziemi pełne jaskiń drapiestwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Niechajże nędznik nie odchodzi z hańbą; ubogi i żebrak niechaj chwali imię twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Powstańże, o Boże! ujmij się o sprawę twoję; wspomnij na pohańbienie twoje, które się dzieje od szalonych na każdy dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Nie zapominajże wykrzykania nieprzyjaciół twoich, i huku tych, co przeciwko tobie powstawają, który się ustawicznie sili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Przedniejszemu śpiewakowi, jako: Nie zatracaj, psalm i pieśń Asafowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Wysławiamy cię, Boże! wysławiamy: bo bliskie imię twoje; opowiadają to dziwne sprawy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Gdy przyjdzie czas ułożony, ja sprawiedliwie sądzić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Rozstąpiła się ziemia, i wszyscy obywatele jej; ale ja utwierdzę słupy jej. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Rzekę szalonym: Nie szalejcie, a niepobożnym: Nie podnoście rogów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Nie podnoście przeciwko Najwyższemu rogów swych, a nie mówcie krnąbrnie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Bo nie od wschodu, ani od zachodu, ani od puszczy przychodzi wywyższenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Ale Bóg sędzia, tego poniża, a owego wywyższa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Zaiste kielich jest w rękach Pańskich, a ten wina mętnego nalany; z tegoż nalewać będzie, tak, że i drożdże jego wyssą i wypiją wszyscy niepobożni ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Ale ja będę opowiadał sprawy Pańskie na wieki, będę śpiewał Bogu Jakóbowemu. A wszystkie rogi niezbożnikom postrącam; ale rogi sprawiedliwego będą wywyższone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Przedniejszemu śpiewakowi na Neginot, psalm i pieśń Asafowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Znajomy jest Bóg w Judzkiej ziemi, w Izraelu wielkie imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'W Salemie jest przybytek jego, a mieszkanie jego na Syonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Tamci połamał ogniste strzały łuków, tarczę, i miecz, i wojnę. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Zacnymeś się stał i dostojnym z gór łupiestwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Ci, którzy byli serca mężnego, podani są na łup, zasnęli snem swoim, nie znaleźli mężni rycerze siły w rękach swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Od gromienia twego, o Boże Jakóbowy! twardo zasnęły i wozy i konie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Tyś jest, ty bardzo straszliwy; i któż jest, coby się ostał przed obliczem twojem, gdy się zapali gniew twój?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Gdy z nieba dajesz słyszeć sąd swój, ziemia się lęka i ucicha;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Gdy Bóg na sąd powstaje, aby wybawił wszystkich pokornych na ziemi. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Zaiste i gniew człowieczy chwalić cię musi, a ty ostatek zagniewania skrócisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Śluby czyńcie, a oddawajcie je Panu, Bogu waszemu, wszyscy, którzyście około niego, wszyscy przynoście dary strasznemu. Onci odejmuje ducha książętom, a on jest na postrach królom ziemskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Przedniejszemu śpiewakowi dla Jedytuna psalm Asafowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Głos mój podnoszę do Boga, kiedy wołam; głos mój podnoszę do Boga, aby mię wysłuchał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'W dzień utrapienia mego szukałem Pana: wyciągałem w nocy ręce moje bez przestania, a nie dała się ucieszyć dusza moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Wspominałem na Boga, a trwożyłem sobą; rozmyślałem, a utrapieniem ściśniony był duch mój. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Zatrzymywałeś oczy moje, aby czuły; potartym był, ażem nie mógł mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Przychodziły mi na pamięć dni przeszłe i lata dawne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Wspominałem sobie na śpiewanie moje; w nocym w sercu swem rozmyślał, i wywiadywał się o tem duch mój, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Izali mię na wieki odrzuci Pan, a więcej mi już łaski nie ukaże?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Izali do końca ustanie miłosierdzie jego, i koniec weźmie słowo od rodzaju aż do rodzaju? Izali zapomniał Bóg zmiłować się?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Izali zatrzymał w gniewie litości swoje? Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'I rzekłem: Toć jest śmierć moja; wszakże prawica Najwyższego uczyni odmianę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Wspominać sobie będę na sprawy Pańskie, a przypominać sobie będę dziwne sprawy twoje, zdawna uczynione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'I będę rozmyślał o wszelkiem dziele twojem, i o uczynkach twoich będę mówił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Boże! święta jest droga twoja. Któryż Bóg jest tak wielki, jako Bóg nasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Tyś jest Bóg,który czynisz cuda; podałeś do znajomości między narody moc twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Odkupiłeś ramieniem twojem lud swój, syny Jakóbowe i Józefowe. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Widziały cię wody, o Boże! widziały cię wody, i ulękły się, i wzruszyły się przepaści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Obłoki wydały powodzi; niebiosa wydały gromy, a strzały twoje tam i sam biegały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Huczało grzmienie twoje po obłokach, błyskawice oświeciły okrąg ziemi, ziemia się wzruszyła i zatrzęsła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Przez morze była droga twoja, a ścieżki twoje przez wody wielkie, wszakże śladów twoich nie było. Prowadziłeś lud twój, jako stado owiec, przez rękę Mojżesza i Aarona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Pieśń wyuczająca podana Asafowi. Słuchaj, ludu mój! zakonu mego; nakłońcież uszów swych do słów ust moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Otworzę w podobieństwie usta moje, a będę opowiadał przypowiastki starodawne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Cośmy słyszeli, i poznali, i co nam ojcowie nasi opowiadali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Nie zataimy tego przed synami ich, którzy przyszłym potomkom swoim opowiadać będą chwały Pańskie, i moc jego, i cuda jego, które uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Bo wzbudził świadectwo w Jakóbie, a zakon wydał w Izraelu; przykazał ojcom naszym, aby to do wiadomości podawali synom swoim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Aby poznał wiek potomny, synowie, którzy się narodzić mieli, a oni zaś powstawszy, aby to opowiadali synom swoim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Aby pokładali w Bogu nadzieję swoję, a nie zapominali na sprawy Boże, ale strzegli przykazań jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Aby się nie stali jako ojcowie ich narodem odpornym i nieposłusznym, narodem, który nie wygotował serca swego, aby był wierny Bogu duch jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Albo jako synowie Efraimowi zbrojni, którzy, choć umieli z łuku strzelać, wszakże w dzień wojny tył podali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Bo nie przestrzegali przymierza Bożego, a według zakonu jego zbraniali się chodzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Zapomnieli na sprawy jego, i na dziwne dzieła jego, które im pokazywał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Przed ojcami ich czynił cuda w ziemi Egipskiej, na polu Soan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Rozdzielił morze, i przeprowadził ich, i sprawił, że stanęły wody jako kupa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Prowadził ich w obłoku we dnie, a każdej nocy w jasnym ogniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Rozszczepił skały na puszczy, a napoił ich, jako z przepaści wielkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Wywiódł strumienie ze skały, a uczynił, że wody ciekły jako rzeki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'A wszakże oni przyczynili grzechów przeciwko niemu, a wzruszyli Najwyższego na puszczy do gniewu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'I kusili Boga w sercu swem, żądając pokarmu według lubości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'A mówili przeciwko Bogu temi słowy: Izali może Bóg zgotować stół na tej puszczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Oto uderzył w skałę, a wypłynęły wody, i rzeki wezbrały; izali też będzie mógł dać chleb? Izali nagotuje mięsa ludowi swemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Przetoż usłyszawszy to Pan, rozgniewał się, a ogień się zapalił przeciw Jakóbowi, także i popędliwość powstała przeciw Izraelowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Przeto, iż nie wierzyli Bogu, a nie mieli nadziei w zbawieniu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Choć był rozkazał obłokom z góry, i forty niebieskie otworzył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'I spuścił im jako deszcz mannę ku pokarmowi, a pszenicę niebieską dał im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Chleb mocarzów jadł człowiek, a zesłał im pokarmów do sytości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Obrócił wiatr ze wschodu na powietrzu, a przywiódł mocą swą wiatr z południa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'I spuścił na nich mięso jako proch, i ptastwo skrzydlate jako piasek morski;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Spuścił je w pośród obozu ich, wszędy około namiotów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'I jedli, a nasyceni byli hojnie, i dał im, czego żądali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'A gdy jeszcze nie wypełnili żądości swej, gdy jeszcze pokarm był w ustach ich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'Tedy zapalczywość Boża przypadła na nich, i pobił tłustych ich, a przedniejszych z Izraela poraził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Ale w tem wszystkiem jeszcze grzeszyli, i nie wierzyli cudom jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Przetoż sprawił, że marnie dokonali dni swoich, i lat swoich w strachu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Gdy ich tracił, jeźliże go szukali, i nawracali się, a szukali z rana Boga,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Przypominając sobie, iż Bóg był skałą ich, a Bóg najwyższy odkupicielem ich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, '(Aczkolwiek pochlebiali mu usty swemi, i językiem swoim kłamali mu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'A serce ich nie było szczere przed nim, ani wiernymi byli w przymierzu jego.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'On jednak będąc miłosierny odpuszczał nieprawości ich, a nie zatracał ich, ale częstokroć odwracał gniew swój, a nie pobudzał wszystkiego gniewu swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Bo pamiętał, że są ciałem, wiatrem, który odchodzi, a nie wraca się zaś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Jako go często draźnili na puszczy, i do boleści przywodzili na pustyniach?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Bo coraz kusili Boga, a Świętemu Izraelskiemu granice zamierzali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Nie pamiętali na rękę jego, i na on dzień, w który ich wybawił z utrapienia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Gdy czynił w Egipcie znaki swoje, a cuda swe na polu Soan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Gdy obrócił w krew rzeki ich, i strumienie ich, tak, że z nich pić nie mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Przepuścił na nich rozmaite muchy, aby ich kąsały, i żaby, aby ich gubiły:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'I dał chrząszczom urodzaje ich, a prace ich szarańczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Potłukł gradem szczepy ich, a drzewa leśnych fig ich gradem lodowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'I podał gradowi bydło ich, a majętność ich węglu ognistemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Posłał na nich gniew zapalczywości swojej, popędliwość, i rozgniewanie, i uciśnienie, przypuściwszy na nich aniołów złych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Wyprostował ścieżkę gniewowi swemu, nie zachował od śmierci duszy ich, i na bydło ich powietrze dopuścił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'I pobił wszystko pierworodztwo w Egipcie, pierwiastki mocy ich w przybytkach Chamowych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Ale jako owce wyprowadził lud swój, a wodził ich jako stada po puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Wodził ich w bezpieczeństwie, tak, że się nie lękali, (a nieprzyjaciół ich okryło morze,)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Aż ich przywiódł do świętej granicy swojej, na onę górę, której nabyła prawica jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'I wyrzucił przed twarzą ich narody, i sprawił, że im przyszły na sznur dziedzictwa ich, ażeby mieszkały w przybytkach ich pokolenia Izraelskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'A wszakże przecież kusili i draźnili Boga najwyższego, a świadectwa jego nie strzegli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Ale się odwrócili, i przewrotnie się obchodzili, jako i ojcowie ich; wywrócili się jako łuk omylny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Bo go wzruszyli do gniewu wyżynami swemi, a rytemi bałwanami swemi pobudzili go do zapalczywości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Co słysząc Bóg rozgniewał się, i zbrzydził sobie bardzo Izraela,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Tak, że opuściwszy przybytek w Sylo, namiot, który postawił między ludźmi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Podał w niewolę moc swoję, i sławę swoję w ręce nieprzyjacielskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Dał pod miecz lud swój, a na dziedzictwo swoje rozgniewał się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Młodzieńców jego ogień pożarł, a panienki jego nie były uczczone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Kapłani jego od miecza polegli, a wdowy jego nie płakały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Lecz potem ocucił się Pan jako ze snu, jako mocarz wykrzykający od wina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'I zaraził nieprzyjaciół swoich na pośladkach, a na wieczną hańbę podał ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Ale choć wzgardził namiotem Józefowym, a pokolenia Efraimowego nie obrał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Wszakże obrał pokolenie Judowe, i górę Syon, którą umiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'I wystawił sobie jako pałac wysoki świątnicę swoję, jako ziemię, którą ugruntował na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'I obrał Dawida sługę swego, wziąwszy go z obór owczych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Gdy chodził za owcami kotnemi, przyprowadził go, aby pasł Jakóba, lud jego, i Izraela, dziedzictwo jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Który ich pasł w szczerości serca swego, a w roztropności rąk swoich prowadził ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Psalm podany Asafowi. O Boże! wtargnęli poganie w dziedzictwo twoje, splugawili kościół twój święty, obrócili Jeruzalem w kupy gruzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Dali trupy sług twoich na pokarm ptastwu powietrznemu, ciała świętych twoich bestyjom ziemskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Wylali krew ich jako wodę około Jeruzalemu, a nie był, ktoby ich pochował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Staliśmy się pohańbieniem u sąsiadów naszych; śmiechowiskiem i igrzyskiem u tych, którzy są około nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Dokądże, o Panie? azaż na wieki gniewać się będziesz? a jako ogień pałać będzie zapalczywość twoja?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Wylij gniew twój na pogan, którzy cię nie znają, i na królestwa, które imienia twego nie wzywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Albowiemci pożarli Jakóba, a mieszkanie jego spustoszyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Nie wspominajże nam przeszłych nieprawości naszych; niech nas rychło uprzedzi miłosierdzie twoje, bośmy bardzo znędzeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Wspomóżże nas, o Boże zbawienia naszego! dla chwały imienia twego, a wyrwij nas, i bądź miłościw grzechom naszym dla imienia twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Przeczżeby mieli mówić poganie: Gdzież jest Bóg ich? Bądź znacznym między poganami, przed oczyma naszemi, dla pomsty krwi sług twoich, która jest wylana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Niech przyjdzie przed oblicze twoje narzekanie więźniów, a według wielkości ramienia twego zachowaj ostatki tych, co są na śmierć skazani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'A oddaj sąsiadom naszym siedmiorako na łono ich za pohańbienie ich, któreć uczynili, o Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Ale my lud twój i owce pastwiska twego, będziemy cię wysławiali na wieki; od narodu do narodu będziemy opowiadać chwałę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Przedniejszemu śpiewakowi na Sosannim psalm świadectwa Asafowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'O Pasterzu Izraelski! posłuchaj, który prowadzisz Józefa jako stado owiec; który siedzisz na Cherubinach, rozjaśnij się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Wzbudź moc swoję przed Efraimem, i Benjaminem, i Manasesem, a przybądź na wybawienie nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'O Boże! przywróć nas, a rozjaśnij nad nami oblicze twoje, a będziemy zbawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Panie, Boże zastępów! dokądże się będziesz gniewał na modlitwę ludu swego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Nakarmiłeś ich chlebem płaczu, i napoiłeś ich łzami miarą wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Wystawiłeś nas na zwadę sąsiadom naszym; a nieprzyjaciołom naszym, aby sobie z nas śmiech stroili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'O Boże zastępów; przywróć nas, a rozjaśnij nad nami oblicze twoje, a będziemy zbawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Tyś macicę winną z Egiptu przeniósł; wyrzuciłeś pogan, a wsadziłeś ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Uprzątnąłeś dla niej, i sprawiłeś, że się rozkorzeniła i napełniła ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Okryte są góry cieniem jej, a gałęzie jej jako najwyższe cedry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Rozpuściła latorośle swe aż do morza, i aż do rzeki gałązki swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Przeczżeś tedy rozwalił płot winnicy, tak, że ją szarpają wszyscy, którzy mimo drogą idą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Zniszczył ją wieprz dziki, a zwierz polny spasł ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'O Boże zastępów! nawróć się proszę, spojrzyj z nieba, i obacz, a nawiedź tę winną macicę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Tę winnicę, którą szczepiła prawica twoja, i latorosłki, któreś sobie zmocnił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Spalona jest ogniem, i wyrąbana; ginie od zapalczywości oblicza twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Niech będzie ręka twoja nad mężem prawicy twojej, nad synem człowieczym, któregoś sobie zmocnił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'A nie odstąpimy od ciebie; zachowaj nas przy żywocie, a imienia twego wzywać będziemy. O Panie, Boże zastępów! nawróćże nas zasię; rozjaśnij nad nami oblicze twoje, a będziemy zbawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Przedniejszemu śpiewakowi na Gittyt, Asafowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Wesoło śpiewajcie Bogu mocy naszej; wykrzykajcie Bogu Jakóbowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Weźmijcie psalm, przydajcie bębęn, i wdzięczną harfę z lutnią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Zatrąbcie w trąbę na nowiu miesiąca, czasu ułożonego, w dzień święta naszego uroczystego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Albowiem jest postanowienie w Izraelu, prawo Boga Jakóbowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Na świadectwo w Józefie wystawił je, kiedy był wyszedł przeciw ziemi egipskiej, kędym słyszał język, któregom nie rozumiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Wybawiłem, mówi Bóg, od brzemienia ramię jego, a ręce jego od dźwigania kotłów uwolnione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Gdyś mię w ucisku wzywał. wyrwałem cię, i wysłuchałem cię w skrytości gromu, doświadczałem cię u wód poswarku. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Tedym rzekł: Słuchaj, ludu mój! a oświadczę się przeciwko tobie, o Izraelu! będzieszli mię słuchał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'I nie będziesz miał boga cudzego, ani się będziesz kłaniał bogu obcemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, '(Albowiem Jam Pan, Bóg twój, którym cię wywiódł z ziemi Egipskiej;) otwórz usta twoje, a napełnięć je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Ale lud mój nie usłuchał głosu mego, a Izrael nie przestał na mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Przetoż puściłem ich za żądzami serca ich, i chodzili za radami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Oby mię był lud mój posłuchał, a Izrael drogami mojemi chodził!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'W krótkim czasie bym był nieprzyjaciół ich poniżył, a przeciw nieprzyjaciołom ich obróciłbym rękę swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Ci, którzy w nienawiści mają Pana, choć obłudnie, poddaćby się im musieli, i byłby czas ich aż na wieki. I karmiłbym ich tłustością pszenicy, a miodem z opoki nasyciłbym ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Psalm Asafowy. Bóg stoi w zgromadzeniu Bożem, a w pośród bogów sądzi i mówi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Dokądże będziecie niesprawiedliwie sądzić, a osoby niezbożników przyjmować? Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Czyńcie sprawiedliwość ubogiemu i sierotce;utrapionego i niedostatecznego usprawiedliwiajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Wyrwijcie chudzinę i nędznego, a z ręki niepobożnej wyrwijcie go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Lecz oni nic nie wiedzą, ani rozumieją; w ciemnościach ustawicznie chodzą; zaczem się zachwiały wszystkie grunty ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Jam rzekł: Bogowieście, a synami Najwyższego wy wszyscy jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'A wszakże jako i inni ludzie pomrzecie, a jako jeden z książąt upadniecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Powstańże, o Boże! a sądź ziemię; albowiem ty dziedzicznie trzymasz wszystkie narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Pieśń i psalm Asafowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'O Boże! nie milczże, nie bądź jako ten, co nie słyszy, i nie chciej się uspokoić, o Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Bo się oto nieprzyjaciele twoi burzą, a ci, którzy cię w nienawiści mają, podnoszą głowę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Przeciwko ludowi twemu wymyślili chytrą radę, a spiknęli się przeciw tym, których ty ochraniasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Mówiąc: Pójdźcie, a wytraćmy ich, niech nie będą narodem, tak, żeby i nie wspominano więcej imienia Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Albowiem spiknęli się jednomyślnie, przymierze przeciwko tobie uczynili:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Namioty Edomczyków, i Ismaelczyków, Moabczyków, i Agareńczyków,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Giebalczyków,i Ammonitczyków, i Amalekitczyków, także Filistyńczyków z tymi, którzy mieszkają w Tyrze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Więc i Assyryjczycy złączyli się z nimi, będąc ramieniem synom Lotowym. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Uczyńże im tak jako Madyjanczykom, jako Sysarze, jako Jabinowi u potoku Cyson.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Którzy są wygładzeni w Endor; stali się jako gnój na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Obchodźże się z nimi, i z ich hetmanami, jako z Orebem, i jako z Zebą, i jako z Zebeem, i jako z Salmanem, ze wszystkimi książętami ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Bo rzekli: Posiądźmy dziedzicznie przybytki Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Boże mój! uczyńże ich jako koło, i jako źdźbło przed wiatrem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Jako ogień, który las pali, i jako płomień, który zapala góry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'Tak ich ty wichrem twoim ścigaj, a burzą twą zatrwóż ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Napełnij twarze ich pohańbieniem, aby szukali imienia twego, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Niech będą zawstydzeni i ustraszeni aż na wieki, a będąc pohańbieni niech zaginą. A tak niech poznają, żeś ty, którego imię jest Pan, tyś sam Najwyższym nad wszystką ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Przedniejszemu śpiewakowi na Gittyt, synom Korego psalm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'O jako są miłe przybytki twoje, Panie zastępów!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Żąda i bardzo tęskni dusza moja do sieni Pańskich; serce moje i ciało moje pochutniwa sobie do Boga żywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Oto i wróbel znalazł sobie domek, i jaskółka gniazdo swoje, gdzie pokłada ptaszęta swe, u ołtarzów twoich, Panie zastępów, królu mój i Boże mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Błogosławieni, którzy mieszkają w domu twoim; będą cię na wieki chwalić. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Błogosławiony człowiek, który ma siłę swoję w tobie, i w których sercu są drogi twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Którzy idąc przez dolinę morwów, za źródło go sobie pokładają, i deszcz pożegnania przychodzi na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'I idą huf za hufem, a ukazują się przed Bogiem na Syonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'O Panie, Boże zastępów! wysłuchaj modlitwę moję; przyjmij w uszy twe, o Boże Jakóbowy. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'O Boże, tarczo nasza! obacz, a wejrzyj na oblicze pomazańca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Albowiem lepszy jest dzień w sieniach twoich, niż gdzie indziej tysiąc; obrałem sobie raczej w progu siedzieć w domu Boga swego, niżeli mieszkać w przybytkach niezbożników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Albowiem Pan Bóg jest słońcem i tarczą: tuć łaski i chwały Pan udziela, i nie odmawia, co jest dobrego, tym, którzy chodzą w niewinności. Panie zastępów! błogosławiony człowiek, który ma nadzieję w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Przedniejszemu śpiewakowi synom Korego psalm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Łaskęś, Panie!niekiedy pokazywał ziemi twojej; przywróciłeś zasię z niewoli Jakóba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Odpuściłeś nieprawość ludu twojego, pokryłeś wszelki grzech ich. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Uśmierzyłeś wszystek gniew twój, odwróciłeś od zapalczywości popędliwość twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Przywróć nas, o Boże zbawienia naszego; a uczyń wstręt gniewowi swemu przeciwko nam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Izali na wieki gniewać się będziesz na nas? a rozciągniesz gniew twój od rodzaju do rodzaju?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Izali ty obróciwszy się, nie ożywisz nas, tak, aby się lud twój rozradował w tobie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Panie! okaż nam miłosierdzie twoje, a daj nam zbawienie swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Ale posłucham, co rzecze Bóg, on Pan mocny; zaiste mówi pokój do ludu swego, i do świętych swoich, byle się jedno zaś do głupstwa nie wracali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Zaisteć bliskie jest zbawienie jego tym, którzy się go boją; a przebywać będzie chwała jego w ziemi naszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Miłosierdzie i prawda spotkają się z sobą; sprawiedliwość i pokój pocałują się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Prawda z ziemi wyrośnie, a sprawiedliwość z nieba wyjrzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Da też Pan i doczesne dobra, a ziemia nasza wyda owoc swój. Sprawi, że sprawiedliwość przed twarzą jego pójdzie, gdy postawi na drodze nogi swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Modlitwa Dawidowa. Nakłoń, Panie! ucha twego, a wysłuchaj mię; bomci nędzny i ubogi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Strzeżże duszy mojej, bom jest ten, którego ty miłujesz; zachowaj sługę twego, Boże mój! który ma nadzieję w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Zmiłuj się nademną, Panie, albowiem do ciebie na każdy dzień wołam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Rozwesel duszę sługi twego; bo do ciebie, o Panie! duszę swą podnoszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Boś ty, Panie! dobry i litościwy, i wielce miłosierny wszystkim, którzy cię wzywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Wysłuchajże, Panie! modlitwę moję, a posłuchaj pilnie głosu prośby mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Wzywam cię w dzień ucisku mego; bo mię ty wysłuchasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Nie masz żadnego podobnego tobie między bogami, o Panie! i nie masz takowych spraw, jako są twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Wszystkie narody, któreś ty stworzył, przychodząc kłaniać się będą przed obliczem twojem, Panie! i wielbić będą imię twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Boś ty jest wielki, a czynisz cuda; tyś sam jest Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Naucz mię, Panie, drogi twojej, abym chodził w prawdzie twojej, a ustanów serce moje w bojaźni imienia twego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'A będę cię chwalił, Panie, Boże mój! ze wszystkiego serca mego, i będę wielbił imię twoje na wieki,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Ponieważ miłosierdzie twoje wielkie jest nademną, a tyś wyrwał duszę moję z dołu głębokiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'O Boże! powstali hardzi przeciwko mnie, a rota okrutników szukała duszy mojej, ci, którzy cię przed oczyma nie mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Ale ty, Panie, Boże miłosierny i litościwy, i nierychły ku gniewu, i wielce miłosierny, i prawdziwy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Wejrzyj na mię, a zmiłuj się nademną, dajże moc twoję słudze twemu, a zachowaj syna służebnicy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Okaż mi znak dobroci twojej, aby to widząc ci, którzy mię mają w nienawiści, zawstydzeni byli, żeś mię ty, Panie! poratował, i pocieszyłeś mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Synom Korego psalm i pieśń. Fundament jego jest na górach świętych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Umiłował Pan bramy Syońskie nad wszystkie przybytki Jakóbowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Sławne o tobie rzeczy powiadają, o miasto Boże! Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Wspomnę na Egipt, i na Babilon przed swymi znajomymi; oto i Filistyńczycy, i Tyryjczycy, i Murzyni rzeką, że się tu każdy z nich urodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Także i o Syonie mówić będą:Ten i ów urodził się w nim; a sam Najwyższy ugruntuje go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Pan policzy narody, gdy je popisywać będzie, mówiąc:Ten się tu urodził. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Przetoż o tobie śpiewać będą z pląsaniem wszystkie siły żywota mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Pieśń a psalm synów Korego przedniejszemu śpiewakowi na Machalat ku śpiewaniu, nauczający, (złożony)od Hemana Ezrahytczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Panie, Boże zbawienia mego! we dnie i w nocy wołam do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Niech przyjdzie przed oblicze twoje modlitwa moja; nakłoń ucha twego do wołania mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Bo nasycona jest utrapieniem dusza moja, a żywot mój przybliżył się aż do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Poczytano mię między tych, którzy zstępują do dołu; byłem jako człowiek bez wszelakiej mocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Policzony jestem między umarłymi; jestem jako pobici,leżący w grobie, na których więcej nie pamiętasz, którzy są od ręki twojej wytraceni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Spuściłeś mię w dół najgłębszy, do najciemniejszego i najgłębszego miejsca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Doległa mię zapalczywość twoja, a wszystkiemi nawałnościami twemi przytłoczyłeś mię. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Dalekoś oddalił znajomych moich odemnie, którymeś mię bardzo obrzydził, a takiem zawarty, że mi nie lza wynijść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Oko moje zemdlało od utrapienia mego; wzywam cię, Panie! na każdy dzień, wyciągając do ciebie ręce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Izali przed umarłymi cuda czynić będziesz? izali umarli powstaną, aby cię wysławiali? Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Izali opowiadane będzie w grobie miłosierdzie twoje? a prawda twoja w zginieniu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Izali poznają w ciemnościach cuda twoje? a sprawiedliwość twoję w ziemi zapamiętania?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Lecz ja, Panie! do ciebie wołam, a z poranku uprzedza cię modlitwa moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Przeczże, o Panie! odrzucasz duszę moję, a zakrywasz oblicze twoje przedemną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Jamci utrapiony, i prawie już umierający od gwałtu; ponoszę strachy twoje, i trwożę sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Powstał przeciwko mnie srogi gniew twój, a strachy twoje wytraciły mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Ogarniają mię jako woda przez cały dzień; otaczają mię gromadno. Oddaliłeś odemnie przyjaciela i towarzysza, a znajomym moim jestem jako w ciemności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Nauczający (złożony) od Etana Ezrahytczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'O miłosierdziach Pańskich na wieki śpiewać będę; od narodu do narodu opowiadać będę usty swemi prawdę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Rzekłem bowiem: Miłosierdzie na wieki budowane będzie; na niebiosach utwierdziłeś prawdę twoję, o którejś rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Postanowiłem przymierze z wybranym moim: przysiągłem Dawidowi, słudze swemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Że aż na wieki utwierdzę nasienie twoje, a zbuduję od narodu do narodu stolicę twoję.Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Przetoż, Panie! wysławiają niebiosa cud twój, i prawdę twoję w zgromadzeniu świętych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Albowiem któż na niebie przyrównany może być Panu? kto podobien jest Panu między synami mocarzów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'I w zgromadzeniu świętych bardzo jest Bóg straszliwy, a straszny nade wszystkich, którzy są około niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Panie, Boże zastępów! któż jest jakoś ty, Pan mocny? bo prawda twoja jest około ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Ty panujesz nad nadętością morską; gdy się podnoszą nawałności jego, ty je skracasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Tyś potawrł Egipt jako zranionego; mocą ramienia twego rozproszyłeś nieprzyjaciół twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Twojeć są niebiosa, twoja też i ziemia; okrąg świata i pełność jego tyś ugruntował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Tyś stworzył północy i południe; Tabor i Hermon śpiewają o imieniu twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Ramię twoje mocne jest; można jest ręka twoja, a wywyższona jest prawica twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Sprawiedliwość i sąd są gruntem stolicy twojej; miłosierdzie i prawda uprzedzają oblicze twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Błogosławiony lud, który zna dźwięk twój; Panie! w światłości oblicza twego chodzić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'W imieniu twojem weselić się będą każdego dnia, a w sprwiedliwości twojej wywyższać się będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Boś ty jest chwałą mocy ich, a za wolą twoją wywyższy się róg nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Bo od Pana jest tarcza nasza, a od świętego Izraelskiego król nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'W on czas mówiąc w widzeniu do świętego twego rzekłeś: Położyłem ratunek w ręku mocarza, wywyższyłem wybranego z ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Znalazłem Dawida, sługę mego; olejkiem świętym moim pomazałem go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Przetoż ręka moja będzie stała przy nim, a ramię moje posili go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Nie uciśnie go nieprzyjaciel, a syn nieprawości nie utrapi go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Bo potrę przed twarzą jego przeciwników jego, a tych, którzy go mają w nienawiści, porażę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Nadto prawda moja i miłosierdzie moje z nim będzie, a w imieniu mojem wywyższony będzie róg jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'I położę na morzu rękę jego i na rzekach prawicę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'On wołając rzecze: Tyś ojciec mój, Bóg mój, i skała zbawienia mego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Ja go też za pierworodnego wystawię, i za wyższego nad królami ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Na wieki mu zachowam miłosierdzie moje, a przymierze moje stałe będzie przy nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'I uczynię, że na wieki będzie trwało nasienie jego, a stolica jego jako dni niebios.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Ale jeźliby synowie jego opuścili zakon mój, a w sądach moich nie chodzili;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Jeźliby ustawy moje splugawili, a przykazań moich nie przestrzegali:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Tedy nawiedzę rózgą przestępstwo ich, a karaniem nieprawość ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Ale miłosierdzia swego nie odejmę od niego, ani skłamię przeciw prawdzie mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Nie splugawię przymierza mego, a tego, co wyszło z ust moich, nie odmienię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Razem przysiągł przez świętobliwość moję, że nie skłamię Dawidowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'A że nasienie jego zostanie na wieki, a stolica jego jako słońce przedemną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Jako miesiąc będzie utwierdzone na wieki, i jako świadkowie na niebie godnowierni. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Aleś go ty odrzucił i wzgardził; rozgniewałeś się na pomazańca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Zrzuciłeś przymierze z sługą twoim; strąciłeś na ziemię koronę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Roztargałeś wszystkie płoty jego, i basztyś jego rozwalił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Szarpają go wszyscy, którzy drogą mimo idą; pośmiewiskiem jest i sąsiadom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Wywyższyłeś prawicę przeciwników jego; uweseliłeś wszysstkich nieprzyjaciół jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'I ostrze miecza jego stępiłeś, a nie ratowałeś go w bitwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Zniosłeś ochędóstwo jego, a stolicę jego uderzyłeś o ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Ukróciłeś dni młodości jego, a przyodziałeś go hańbą. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Dokądże, Panie! na wiekiż się kryć będziesz? także będzie jako ogień pałać zapalczywość twoja?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Wspomnijże na mię, jako krótki jest wiek mój; azaś próżno stworzył wszystkich synów ludzkich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Któż z ludzi tak żyć może, aby nie oglądał śmierci? któż wyrwie duszę swą z mocy grobu? Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Gdzież są litości twoje dawne, o Panie! któreś przysiągł Dawidowi w prawdzie swej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Wspomnij, Panie! na zelżywość sług twoich, a jakom ponosił wzgardę w zanadrzu swem od wszystkich narodów możnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Panie! jako urągali nieprzyjaciele twoi, jako urągali ścieżkom pomazańca twego. Niech będzie błogosławiony Pan aż na wieki. Amen, Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Modlitwa Mojżesza, męża Bożego. Panie! tyś bywał ucieczką naszą od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Pierwej niżli góry stanęły i niżliś wykształtował ziemię, i okrąg świata, oto zaraz od wieku aż na wieki tyś jest Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Ty znowu człowieka w proch obracasz, a mówisz: Nawróćcie się synowie ludzcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Albowiem tysiąc lat przed oczyma twemi są jako dzień wczorajszy, który przeminął, i jako straż nocna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Powodzią porywasz ich; są jako sen, i jako trawa, która z poranku rośnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Z poranku kwitnie i rośnie; ale w wieczór bywa pokoszona, i usycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Albowiem od gniewu twego giniemy, a popędliwością twoją jesteśmy przestraszeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Położyłeś nieprawości nasze przed sobą, tajne występki nasze przed jasnością oblicza twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Skąd wszystkie dni nasze nagle przemijają dla gniewu twego; jako słowa niszczeją lata nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Dni wieku naszego jest lat siedmdziesiąt, a jeźli kto duższy, lat ośmdziesiąt, a to, co najlepszego w nich, tylko kłopot i nędza, a gdy to pominie, tedy prędko odlatujemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Ale któż zna srogość gniewu twego? albo kto bojąc się ciebie zna zapalczywość twoję?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Nauczże nas obliczać dni naszych, abyśmy przywiedli serce do mądrości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Nawróćże się, Panie! dokądże odwłaczasz? zlitujże się nad sługami twymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Nasyćże nas z poranku miłosierdziem twojem; tak, abyśmy wesoło śpiewać i radować się mogli po wszystkie dni nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Rozweselże nas według dni, którycheś nas utrapił, według lat, którycheśmy doznali złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Niech będzie znaczna przy sługach twoich sprawa twoja, a chwała twoja przy synach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Niech będzie przyjemność Pana, Boga naszego, przy nas, a sprawę rąk naszych utwierdź między nami, sprawę rąk naszych utwierdź, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Ten, który mieszka w ochronie Najwyższego, i w cieniu Wszechmocnego przebywać będzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Rzecze Panu: Nadzieja moja i zamek mój, Bóg mój, w nim nadzieję mieć będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Onci zaiste wybawi cię z sidła łowczego, i z powietrza najjadowitszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Pierzem swem okryje cię, a pod skrzydłami jego bezpiecznym będziesz; prawda jego tarczą i puklerzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Nie ulękniesz się strachu nocnego, ani strzały latającej we dnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Ani zarazy morowej, która przechodzi w ciemności, ani powietrza morowego, które zatraca w południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Padnie po boku twym tysiąc, a dziesięć tysięcy po prawej stronie twojej; ale się do ciebie nie przybliży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Tylko to oczyma twemi obaczysz, a nagrodę niepobożnych oglądasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Ponieważeś ty Pana, który jest nadzieją moją, i Najwyższego, za przybytek swój położył:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Nie spotka cię nic złego, ani jaka plaga przybliży się do namiotu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Albowiem Aniołom swoim przykazał o tobie, aby cię strzegli na wszystkich drogach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Na rękach nosić cię będą, byś snać nie obraził o kamień nogi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Po lwie, i po bazyliszku deptać będziesz, lwię i smoka podepczesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Iż się we mnie, mówi Pan, rozkochał, wyrwę go, i wywyższę go, przeto, iż poznał imię moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Będzie mię wzywał, a wysłucham go; Ja z nim będę w utrapieniu, wyrwę go, i uwielbię go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Długością dni nasycę go, i okażę mu zbawienie moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Psalm a pieśń na dzień sobotni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Dobra rzecz jest wysławiać Pana, a śpiewać imieniowi twemu, o Najwyższy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Opowiadać z poranku miłosierdzie twoje, i prawdę twoję na każdą noc,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Na instrumencie o dziesięciu strunach, na lutni, i na harfie z śpiewaniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Albowiemeś mię rozweselił, Panie! sprawami twemi; o sprawach rąk twoich śpiewać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'O jako wielmożne są sprawy twoje, Panie! bardzo głębokie są myśli twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Człowiek bydlęcy nie zna, a głupi nie zrozumiewa tego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Iż wyrastają niezbożnicy jako ziele, a kwitną wszyscy, którzy czynią nieprawość, aby byli wykorzenieni aż na wieki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Ale ty, o Najwyższy! jesteś Panem na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Albowiem, oto nieprzyjaciele twoi, Panie! albowiem oto nieprzyjaciele twoi zginą; rozproszeni będą wszyscy, którzy czynią nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Ale róg mój wywyższysz jako jednorożców; pokropiony będę olejkiem świeżym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'I ujrzy oko moje nieszczęście tych, co na mię czyhają; o złośnikach, którzy powstawają przeciwko mnie, usłyszą uszy moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Sprawiedliwy jako palma zakwitnie, jako cedra na Libanie rozmnoży się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Wszczepieni w domu Pańskim, w sieniach Boga naszego zakwitną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Nawet i w sędziwości przyniosą owoc, czerstwymi i zielonymi będą; Aby to opowiadano, że uprzejmym jest Pan, skała moja, a że w nim nie masz żadnej nieprawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Pan króluje, oblekł się w dostojność; oblekł się Pan w możność, i przepasał się; utwierdził też okrąg świata, aby się nie poruszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Utwierdzona jest stolica twoja przed wszystkiemi czasy; tyś jest od wieczności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Podniosły rzeki, o Panie! podniosły rzeki szum swój; podniosły rzeki nawałności swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Nad szum wielkich wód, nad mocne wały morskie mocniejszy jest Pan na wysokości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Świadectwa twoje są bardzo pewne; świętobliwość, Panie! jest domu twego ozdobą na wieczne dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Boże pomst! Panie Boże pomst! rozjaśnij się!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Podnieś się, o Sędzio wszystkiej ziemi! a daj zapłatę pysznym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Dokądże niepobożni, Panie! dokądże niepobożni radować się będą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Długoż będą świegotać i hardzie mówić, chlubiąc się wszyscy, którzy czynią nieprawość?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Lud twój, Panie! trzeć, a dziedzictwo twoje trapić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Wdowy i przychodniów mordować? a sierotki zabijać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Mówiąc: Nie widzi tego Pan, ani tego rozumie Bóg Jakóbowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Zrozumicież, o wy bydlęcy między ludźmi! a wy szaleni kiedyż zrozumiecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Izali ten, który szczepił ucho, nie słyszy? i który ukształtował oko, izali nie widzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Izali ten, który ćwiczy narody, nie będzie karał? który uczy człowieka umiejętności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Pan zna myśli ludzkie, iż są szczerą marnością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Błogosławiony jest mąż, którego ty ćwiczysz, Panie! a zakonu twego uczysz go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Abyś mu sprawił pokój od złych dni, ażby był wykopany dół niezbożnikowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Albowiem, nie opuści Pan ludu swego, a dziedzictwa swego nie zaniecha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Ale aż ku sprawiedliwości obróci się sąd, a za nim wszyscy serca uprzejmego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Któżby się był zastawił za mną przeciwko złośnikom? ktoby się był ujął o mnie przeciwko tym, którzy czynią nieprawość?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'By mi był Pan nie przybył na pomoc, małoby była nie mieszkała dusza moja w milczeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Jużem był rzekł: Zachwiała się noga moja; ale miłosierdzie twoje, o Panie! zatrzymało mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'W wielkości utrapienia mego, we wnętrznościach moich, pociechy twoje rozweselały duszę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Izali z tobą towarzyszy stolica nieprawości tych, którzy stanowią krzywdę miasto prawa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Którzy się zbierają przeciwko duszy sprawiedliwego, a krew niewinną potępiają?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Ale Pan jest twierdzą moją, a Bóg mój skałą ufności mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Onci obróci na nich nieprawość ich, a dla złości ich wytraci ich; wytraci ich Pan, Bóg nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Pójdźcież, śpiewajmy Panu; wykrzykujmy skale zbawienia naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Uprzedźmy oblicze jego z chwałą; psalmy mu śpiewajmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Albowiem Pan jest Bóg wielki, i król wielki nade wszystkich bogów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'W jegoż rękach są głębokości ziemi, i wierzchy gór jego są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Jegoż jest morze, bo je on uczynił; i ziemia, którą ręce jego ukształtowały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Pójdźcie, kłaniajmy się, a upadajmy przed nim; klękajmy przed Panem, stworzycielem naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Onci jest zaiste Bóg nasz, a myśmy lud pastwiska jego, i owce rąk jego. Dziś, jeźli głos jego usłyszycie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'Nie zatwardzajcież serca swego, jako w Meryba, a jako czasu kuszenia na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Kiedy mię kusili ojcowie wasi, doświadczylić mię, i widzieli sprawy moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Przez czterdzieści lat miałem spór z tym narodem, i rzekłem: Lud ten błądzi sercem, a nie poznali dróg moich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Którymem przysiągł w popędliwości mojej, że nie wnijdą do odpocznienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Śpiewajcie Panu pieśń nową; śpiewajcie Panu wszystka ziemia!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Śpiewajcież Panu, dobrorzeczcie imieniowi jego, opowiadajcie ode dnia do dnia zbawienie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Opowiadajcie między narodami chwałę jego, między wszystkimi ludźmi cuda jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Albowiem wielki Pan i wszelkiej chwały godny, i straszliwy jest nad wszystkich bogów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Wszyscy bowiem bogowie narodów są bałwani; ale Pan niebiosa uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Zacność i ochędóstwo przed obliczem jego, moc i piękność w świątnicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Oddajcie Panu, pokolenia narodów, oddajcie Panu chwałę i moc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Oddajcie Panu chwałę imienia jego; przynieście dary, a wnijdźcie do sieni jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Kłaniajcie się Panu w ozdobie świętobliwości; niech się lęka oblicza jego wszystka ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Powiadajcie między poganami: Pan króluje, a że i krąg świata utwierdzony będzie, tak, aby się nie poruszył, a iż będzie sądził ludzi w sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Niech się weselą niebiosa, a niech pląsa ziemia; niech zaszumi morze, i co w niem jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Niech pląsają pola, i wszystko co jest na nich; tedy niech wykrzykają wszystkie drzewa leśne,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Przed obliczem Pańskiem; boć idzie, idzie zaiste, aby sądził ziemię. Będzie sądził okrąg świata w sprawiedliwości, a narody w prawdzie swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Pan króluje; wyskakuj ziemio, a wesel się mnóstwo wysep!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Obłok i ciemność około niego; sprawiedliwość i sąd są gruntem stolicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Ogień przed obliczem jego idzie, a zapala w około nieprzyjaciół jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Błyskawice jego oświecają okrąg świata, co widząc ziemia zadrżała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Góry jako wosk rozpływają się przed obliczem Pańskiem, przed obliczem Pana wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Niebiosa opowiadają sprawiedliwość jego, a wszystkie narody oglądają chwałę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Niechże będą zawstydzeni wszyscy, którzy służą obrazom, którzy się chlubią w bałwanach; kłaniajcież mu się wszyscy bogowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'To usłyszawszy Syon rozweseli się, a radować się będą córki Judzkie, dla sądów twoich, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Albowiemeś ty Pan najwyższy na wszystkiej ziemi, a bardzoś wywyższony nad wszystkich bogów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Wy, którzy miłujecie Pana, miejcie złe w nienawiści; on strzeże świętych swoich, a z ręki niepobożnych wyrywa ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Światłości nasiano sprawiedliwemu, a radości tym, którzy są uprzejmego serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Weselcie się sprawiedliwi w Panu, a wysławiajcie pamiątkę świętobliwości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Psalm. Śpiewajcie Panu pieśń nową, bo dziwne rzeczy uczynił; dopomogła mu prawica jego, i ramię świętobliwości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Objawił Pan zbawienie swoje; przed oczyma pogan oznajmił sprawiedliwość swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Wspomniał na miłosierdzie swoje, i na prawdę swoję przeciw domowi Izraelskiemu; oglądały wszystkie granice ziemi zbawienie Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Śpiewajże Panu wszystka ziemio; wykrzykajcie, a weselcie się i śpiewajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Grajcie Panu na harfie; na harfie, głosem przyśpiewując.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Na trąbach i na kornetach krzykliwych głos wydawajcie przed Królem i Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Niech zaszumi morze, i co w niem jest, okrąg świata, i mieszkający na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Rzeki niech klaskają rękoma; góry wespół niech się rozradują,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Przed Panem, bo idzie sądzić ziemię. On będzie sądził okrąg świata w sprawiedliwości, i narody w prawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Pan króluje, niechże zadrżą narody; siedzi między Cherubinami, niechże się poruszy ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Pan na Syonie wielki, a wywyższony nad wszystkie narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Niech wysławiają imię twoje wielkie i straszne; albowiem święte jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Moc zaiste królewska miłuje sąd; albowiemeś ty ustanowił prawa; sąd i sprawiedliwość w Jakóbie ty wykonujesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Wywyższajcie Pana, Boga naszego, a kłaniajcie się u podnóżka nóg jego; bo święty jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mojżesz i Aaron między kapłanami jego, a Samuel między wzywającymi imienia jego, wołali do Pana, a on ich wysłuchał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'W słupie obłokowym mówił do nich; a gdy strzegli świadectw jego i ustaw, które im podał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Panie, Boże nasz! tyś ich wysłuchiwał; Boże!bywałeś im miłościwym, i gdyś ich karał dla występków ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Wywyższajcie Pana, Boga naszego, a kłaniajcie się na górze świętej jego; albowiem święty jest Pan, Bóg nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Psalm dla dziękczynienia. Wykrzykajcie Panu, wszystka ziemio!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Służcie Panu z weselem, przychodźcie przed oblicze jego z radością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Wiedzcież, żeć Pan jest Bogiem; on uczynił nas, a nie my samych siebie, abyśmy byli ludem jego, i owcami pastwiska jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Wnijdźcież w bramy jego z wysławianiem, a do sieni jego z chwałami; wysławiajcież go, dobrorzeczcież imieniowi jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Albowiem dobry jest Pan, na wieki trwa miłosierdzie jego, a od narodu aż do narodu prawda jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Psalm samego Dawida. O miłosierdziu i o sądzie śpiewać będę; tobie, o Panie! śpiewać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Ostrożnym będę na drodze uprzejmej, kiedy przyjdziesz do mnie; będę chodził ustawicznie w szczerości serca mego, w domu moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Nie położę przed oczy moje złej rzeczy; każdą sprawę występników mam w nienawiści, a nie chwyci się mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Serce przewrotne odstąpi odemnie, a o złe nie będę dbał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Tego, który potajemnie obmawia bliźniego swego, wytnę; oczów wyniosłych, i serca nadętego nie będę mógł cierpieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Oczy moje obrócone będą na prawdomównych w ziemi, aby siadali zemną; kto chodzi drogą uprzejmą, ten mi służyć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Nie będzie mieszkał w domu moim zdrajca, ten, który mówi kłamstwo, nie ostoi się przed oczyma memi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Co poranek tracić będę wszystkich niezbożnych na ziemi, abym tak wykorzenił z miasta Pańskiego wszystkich, którzy czynią nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Modlitwa utrapionego, gdy będąc w ucisku, przed Panem wylewa żądość swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Panie! wysłuchaj modlitwę moję, a wołanie moje niechaj przyjdzie do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Nie ukrywaj oblicza twego przedemną; w dzień ucisku mego nakłoń ku mnie ucha twego; w dzień którego cię wzywam, prędko mię wysłuchaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Albowiem niszczeją jako dym dni moje, a kości moje jako ognisko wypalone są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Porażone jest jako trawa, i uwiędło serce moje, tak, żem zapomniał jeść chleba swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Od głosu wzdychania mego przylgnęły kości moje do ciała mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Stałem się podobnym pelikanowi na puszczy; jestem jako puhacz na pustyniach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Czuję, a jestem jako wróbel samotny na dachu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Przez cały dzień urągają mi nieprzyjaciele moi, a naśmiewcy moi przeklinają mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Bo jadam popiół jako chleb, a napój mój mięszam ze łzami,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Dla rozgniewania twego, i dla zapalczywości gniewu twego; albowiem podniósłszy mię porzuciłeś mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Dni moje są jako cień nachylony, a jam jako trawa uwiądł;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Ale ty, Panie! trwasz na wieki, a pamiątka twoja od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Ty powstawszy zmiłujesz się nad Syonem; boć czas, żebyś się zlitował nad nim, gdyż przyszedł czas naznaczony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Albowiem upodobały się sługom twoim kamienie jego, i nad prochem jego zmiłują się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Aby się bali poganie imienia Pańskiego, a wszyscy królowie ziemscy chwały twojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Gdy pobuduje Pan Syon, i okaże się w chwale swojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Gdy wejrzy na modlitwę poniżonych, nie gardząc modlitwą ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'To zapiszą dla narodu potomnego, a lud, który ma być stworzony, chwalić będzie Pana,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Że wejrzał z wysokości świątnicy swojej, że z nieba na ziemię spojrzał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Aby wysłuchał wzdychania więźniów, i rozwiązał na śmierć skazanych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Aby opowiadali na Syonie imię Pańskie, a chwałę jego w Jeruzalemie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Gdy się pospołu zgromadzą narody i królestwa, aby służyły Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Utrapił w drodze siłę moję, ukrócił dni moich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Ażem rzekł; Boże mój! nie bierz mię w połowie dni moich; od narodu bowiem aż do narodu trwają lata twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'I pierwej niżeliś założył ziemię, i niebiosa, dzieło rąk twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'One pominą, ale ty zostajesz; wszystkie te rzeczy jako szata zwiotszeją, jako odzienie odmienisz je, i odmienione będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Ale ty tenżeś zawżdy jest, a lata twoje nigdy nie ustaną. Synowie sług twoich, u ciebie mieszkać będą, a nasienie ich zmocni się przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Psalm Dawidowy. Błogosław duszo moja Panu, i wszystkie wnętrzności moje imieniowi jego świętemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Błogosławże duszo moja Panu, a nie zapominaj wszystkich dobrodziejstw jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Który odpuszcza wszystkie nieprawości twoje; który uzdrawia wszystkie choroby twoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Który wybawia od śmierci żywot twój; który cię koronuje miłosierdziem i wielką litością:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Który nasyca dobrem usta twoje, a odnawia jako orła młodość twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Pan czyni, co sprawiedliwego jest, i sądy wszystkim uciśnionym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Oznajmił drogi swe Mojżeszowi, a synom Izraelskim sprawy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Miłosierny i litościwy jest Pan, nierychły do gniewu, i wielkiego miłosierdzia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Nie będzie się na wieki wadził, a gniewu wiecznie chował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Nie według grzechów naszych obchodzi się z nami, ani według nieprawości naszych odpłaca nam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Albowiem jako są niebiosa wysokie nad ziemią, tak jest utwierdzone miłosierdzie jego nad tymi, którzy się go boją;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'A jako daleko jest wschód od zachodu, tak daleko oddalił od nas przestępstwa nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Jako ma litość ojciec nad dziatkami, tak ma litość Pan nad tymi, którzy się go boją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Onci zaiste zna, cośmy za ulepienie, pamięta, żeśmy prochem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Dni człowiecze są jako trawa, a jako kwiat polny, tak kwitnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Gdy nań wiatr powienie, aliści go niemasz, ani go więcej pozna miejsce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Ale miłosierdzie Pańskie od wieków aż na wieki nad tymi, którzy się go boją, a sprawiedliwość jego nad synami synów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Którzy strzegą przymierza jego, i pamiętają na przykazanie jego, aby je czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Pan na niebiosach utwierdził stolicę; a królestwo jego nad wszystkimi panuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Błogosławcież Panu Aniołowie jego mocni w sile, którzy czynicie rozkazania jego, posłusznymi będąc głosowi słowa jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Błogosławcie Panu wszystkie wojska jego, słudzy jego, którzy czynicie wolę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Błogosławcie Panu wszystkie sprawy jego, na wszystkich miejscach panowania jego. Błogosław, duszo moja! Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Błogosław, duszo moja! Panu. Panie, Boże mój! wielceś jest wielmożnym; chwałę i ozdobę przyoblokłeś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Przyodziałeś się światłością jako szatą; rozciągnąłeś niebiosa jako oponę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Któryś zasklepił na wodach pałace swoje; który używasz obłoków miasto wozów; który chodzisz na skrzydłach wiatrowych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Który czynisz duchy posłami swymi; ty czynisz sługi swe ogniem pałającym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Ugruntowałeś ziemię na słupach jej, tak, że się nie poruszy na wieki wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Przepaścią jako szatą przyodziałeś ją był, tak, że wody stały nad górami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Na zgromienie twojerozbiegły się, a na głos pogromu twego prędko zuciekały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Wstąpiły góry, zniżyły się doliny na miejsce, któreś im założył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Zamierzyłeś im kres, aby go nie przestępowały, ani się wracały na okrycie ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Który wypuszczasz źródła po dolinach, aby płynęły między górami,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'A napój dawały wszystkiemu zwierzowi polnemu; a z nich gaszą leśne osły pragnienie swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Przy nich mieszka ptastwo niebieskie, a z pośród gałązek głos wydaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Który pokrapiasz góry z pałaców swoich, aby się z owoców spraw twoich nasycała ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Za twoją sprawą rośnie trawa dla bydła, a zioła na pożytek człowieczy; ty wywodzisz chleb z ziemi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'I wino, które uwesela serce człowiecze, od którego się lśni twarz jako od oleju; i chleb, który zatrzymuje żywot ludzki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Nasycone bywają i drzewa Pańskie, i cedry Libanu, których nasadził;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Na których ptaki gniazda swe mają, i bocian na jedlinach ma dom swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Góry wysokie dzikim kozom, a skały są ucieczką królikom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Uczynił miesiąc dla pewnych czasów, a słońce zna zachód swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Przywodzisz ciemność, i bywa noc, w którą wychodzą wszystkie zwierzęta leśne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Lwięta ryczą do łupu, i szukają od Boga pokarmu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Lecz gdy słońce wznijdzie, zaś się zgromadzają, i w jamach swoich kładą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Tedy wychodzi człowiek do roboty swojej, i do pracy swojej aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'O jakoż wielkie są sprawy twoje, Panie! te wszystkie mądrześ uczynił, a napełniona jest ziemia bogactwem twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'W morzu zaś wielkiem i bardzo szerokiem, tam są płazy, którym nie masz liczby, i zwierzęta małe i wielkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Po niem okręty przechodzą, i wieloryb, któregoś ty stworzył, aby w niem igrał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Wszystko to na cię oczekuje, abyś im dał pokarm czasu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Gdy im dajesz, zbierają; gdy otwierasz rękę twoję, nasycone bywają dobremi rzeczami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Lecz gdy ukrywasz oblicze twoje, trwożą sobą; gdy odbierasz ducha ich, giną, i w proch się swój obracają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Gdy wysyłasz ducha twego, stworzone bywają, i odnawiasz oblicze ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Niechajże będzie chwała Pańska na wieki; niech się rozweseli Pan w sprawach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'On gdy wejrzy na ziemię, zadrży; dotknie się gór, a zakurzą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Będę śpiewał Panu za żywota mego; będę śpiewał Bogu memu, póki mię staje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'O nim będzie wdzięczna mowa moja, a ja się rozweselę w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Oby byli wytraceni grzesznicy z ziemi, a niezbożnych aby już nie było! Błogosław, duszo moja! Panu. Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Wysławiajcie Pana; ogłaszajcie imię jego; opowiadajcie między narodami sprawy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Śpiewajcie mu, śpiewajcie mu psalmy, rozmawiajcie o wszystkich cudach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Chlubcie się imieniem świętem jego; niech się weseli serce szukających Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Szukajcież Pana i mocy jego; szukajcie oblicza jego zawsze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Przypominajcie sobie dziwy jego, które czynił, cuda jego i sądy ust jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Wy nasienie Abrahama, sługi jego! Wy synowie Jakóbowi, wybrani jego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Onci jest Pan, Bóg nasz, po wszystkiej ziemi sądy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Pamięta wiecznie na przymierze swoje: na słowo, które przykazał aż do tysiącznego pokolenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Które postanowił z Abrahamem, i na przysięgę swą uczynioną Izaakowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Bo je postanowił Jakóbowi za ustawę, a Izraelowi za umowę wieczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Mówiąc: Tobie dam ziemię Chananejską za sznur dziedzictwa waszego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Kiedy ich był mały poczet, prawie mały poczet, a jeszcze w niej byli przychodniami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Przechodzili zaiste od narodu do narodu, a z królestwa innego ludu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Nie dopuszczał nikomu, aby im miał krzywdę czynić; nawet karał dla nich i królów, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Nie tykajcie pomazańców moich, a prorokom moim nie czyńcie nic złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Gdy przywoławszy głód na ziemię, wszystkę podporę chleba pokruszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Posłał przed nimi męża, który był za niewolnika sprzedany, to jest Józefa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Którego nogi pętami trapili, a żelazo ścisnęło ciało jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Aż do onego czasu, gdy się o nim wzmianka stała; mowa Pańska doświadczała go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Posławszy król kazał go puścić; ten, który panował nad narodami, wolnym go uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Postanowił go panem domu swego, i książęciem nad wszystką dzierżawą swoją,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Aby władał i książętami jego według zdania duszy swojej, i starców jego mądrości nauczał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Potem wszedł Izrael do Egiptu, a Jakób był gościem w ziemi Chamowej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Gdzie rozmnożył Bóg lud swój bardzo, i uczynił go możniejszym nad nieprzyjaciół jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Odmienił serce ich, iż mieli w nienawiści lud jego, a zmyślali zdrady przeciw sługom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Posłał Mojżesza, sługę swego i Aarona, którego obrał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Którzy im przedłożyli słowa znaków jego, i cuda w ziemi Chamowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Posłał ciemności, i zaćmiło się, a nie byli odpornymi słowu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Obrócił wody ich w krew, a pomorzył ryby w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Wydała ziemia ich mnóstwo żab, i były w pałacach królów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Rzekł, a przyszła rozmaita mucha, i mszyce we wszystkich granicach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Dał grad miasto deszczu, ogień palący na ziemię ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Także potłukł winnice ich, i figi ich, a pokruszył drzewa w granicach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Rzekł, a przyszła szarańcza, i chrząszczów niezliczone mnóstwo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'I pożarły wszelkie ziele w ziemi ich, a pojadły urodzaje ziemi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Nawet pobił wszystko pierworodztwo w ziemi ich, początek wszystkiej siły ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Tedy ich wywiódł ze srebrem i ze złotem, a nie był nikt słaby między pokoleniem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Radował się Egipt, gdy oni wychodzili; albowiem był przypadł na nich strach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Rozpostarł obłok na okrycie ich, a ogień na oświecanie nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Na żądanie ich przywiódł przepiórki, a chlebem niebieskim nasycił ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Otworzył skałę i wypłynęły wody, a płynęły po suchych miejscach jako rzeka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Albowiem wspomniał na słowo świętobliwości swojej, które rzekł do Abrahama, sługi swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Przetoż wywiódł lud swój z weselem, a z śpiewaniem wybranych swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'I podał im ziemię pogan, a posiedli prace narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Aby zachowali ustawy jego, a prawa jego przestrzegali. Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Halleluja. Wysławiajcie Pana; albowiem dobry, albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Któż wysłowi niezmierną moc Pańską, a wypowie wszystkę chwałę jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Błogosławieni, którzy strzegą sądu, a czynią sprawiedliwość na każdy czas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Pamiętaj na mię, Panie! dla miłości ku ludowi swemu; nawiedźże mię zbawieniem swojem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Abym używał dobrego z wybranymi twoimi, a weselił się w radości narodu twego, i chlubił się wespół z dziedzictwem twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Zgrzeszyliśmy z ojcami swymi; niesprawiedliwieśmy czynili, i nieprawość popełniali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Ojcowie nasi w Egipcie nie zrozumieli cudów twoich, ani pamiętali na wielkość miłosierdzia twego; ale odpornymi byli przy morzu Czerwonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'A wszakże ich wyswobodził dla imienia swego, aby oznajmił moc swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Bo zgromił morze Czerwone, i wyschło, a przewiódł ich przez przepaści, jako przez puszczę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'A tak zachował ich od ręki tego, który ich miał w nienawiści, a wykupił ich z ręki nieprzyjacielskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'W tem okryły wody tych, którzy ich ciążyli; nie został ani jeden z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'A choć uwierzyli słowom jego, i wysławiali chwałę jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Przecież prędko zapomnieli na sprawy jego, i nie czekali na rady jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Ale zdjęci będąc chciwością na puszczy, kusili Boga na pustyniach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'I dał im, czego żądali, a wszakże przepuścił suchoty na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Zatem gdy się wzruszyli zawiścią przeciw Mojżeszowi w obozie, i przeciw Aaronowi, świętemu Pańskiemu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Otworzyła się ziemia, i pożarła Datana, i okryła rotę Abironową,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'I zapalił się ogień na zebranie ich; płomień spalił niepobożnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Sprawili i cielca na Horebie, i kłaniali się bałwanowi litemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'I odmienili chwałę swą w podobieństwo wołu, jedzącego trawę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Zapomnieli na Boga, wybawiciela swego, który czynił wielkie rzeczy w Egipcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Rzeczy dziwne w ziemi Chamowej, rzeczy straszne przy morzu Czerwonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Przetoż rzekł, że ich chciał wytracić, gdyby się był Mojżesz, wybrany jego, nie stawił w onem rozerwaniu przed nim, a nie odwrócił popędliwości jego, aby ich nie tracił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Wzgardzili też ziemią pożądaną, nie wierząc słowu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'I szemrząc w namiotach swoich, nie byli posłuszni głosowi Pańskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Przetoż podniósł rękę swoję przeciwko nim, aby ich pobił na puszczy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'A żeby rozrzucił nasienie ich między pogan, i rozproszył ich po ziemiach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Sprzęgli się też byli z bałwanem Baalfegorem, a jedli ofiary umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'A tak draźnili Boga sprawami swemi, że się na nich oborzyła plaga;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Aż się zastawił Finees, a pomstę uczynił, i rozerwana jest ona plaga;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Co mu poczytano ku sprawiedliwości od narodu do narodu, aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Znowu go byli wzruszyli do gniewu u wód Meryba, tak, iż się źle działo i z Mojżeszem dla nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Albowiem rozdraźnili ducha jego, że wyrzekł co niesłuszne usty swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Nadto nie wytracili onych narodów, o których im był Pan powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Ale pomięszawszy się z onemi narodami, nauczyli się spraw ich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'I służyli bałwanom ich, które im były sidłem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Albowiem dyjabłom ofiarowali synów swoich, i córki swoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'I wylewali krew niewinną, krew synów swoich, i córek swoich, których ofiarowali bałwanom rytym Chananejskim, tak, że splugawiona była ziemia onem krwi rozlaniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'I zmazali się sprawami swemi, a cudzołożyli wynalazkami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Przetoż zapaliwszy się Pan w popędliwości przeciw ludowi swemu, obrzydził sobie dziedzictwo swoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'I podał ich w ręce poganom; a panowali nad nimi, którzy ich mieli w nienawiści;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'I uciskali ich nieprzyjaciele ich, tak, że poniżeni byli pod ręką ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Częstokroć ich wybawiał; wszakże go oni wzruszali do gniewu radami swemi, zaczem poniżeni byli dla nieprawości swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'A wszakże wejrzał na ucisk ich, i usłyszał wołanie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Bo sobie wspomniał na przymierze swoje z nimi, a żałował tego według wielkiej litości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Tak, że im zjednał miłosierdzie przed oczyma wszystkich, którzy ich byli pojmali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Wybawże nas, Panie, Boże nasz! a zgromadź nas z tych pogan, abyśmy wysławiali imię świętobliwości twojej, a chlubili się w chwale twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Błogosławiony Pan, Bóg Izraelski, od wieków aż na wieki; na co niech rzecze wszystek lud: Amen, Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Wysławiajcie Pana: albowiem dobry; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Niech o tem powiedzą ci, których odkupił Pan, jako ich wykupił z ręki nieprzyjacielskiej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'A zgromadził ich z ziem, od wschodu i od zachodu, od północy i od morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Błądzili po puszczy, po pustyni bezdrożnej, miasta dla mieszkania nie znajdując.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Byli głodnymi i pragnącymi, aż w nich omdlewała dusza ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'A gdy wołali do Pana w utrapieniu swojem, z ucisku ich wyrywał ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'I prowadził ich drogą prostą, aby przyszli do miasta, w któremby mieszkali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Niechajże wysławiają przed Panem miłosierdzie jego, a dziwne sprawy jego przed synami ludzkimi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Iż napoił duszę pragnącą, a duszę zgłodniałą napełnił dobrami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Którzy siedzą w ciemności i w cieniu śmierci, ściśnieni będąc nędzą i żelazem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Przeto, że byli odpornymi wyrokom Bożym, a radą Najwyższego pogardzili;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Dla czego poniżył biedą serce ich; upadli, a nie był, ktoby ratował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'A gdy wołali do Pana w utrapieniu swojem, z ucisków ich wybawiał ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Wywodził ich z ciemności, i z cienia śmierci, a związki ich potargał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Niechajże wysławiają przed Panem miłosierdzie jego, a dziwne sprawy jego przed synami ludzkimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Przeto, że kruszy bramy miedziane, a zawory żelazne rąbie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Szaleni dla drogi przewrotności swojej, i dla nieprawości swej utrapieni bywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Wszelki pokarm brzydzi sobie dusza ich, aż się przybliżają do bram śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Gdy wołają do Pana w utrapieniu swojem, z ucisków ich wybawia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Posyła słowo swe, i uzdrawia ich,a wybawia ich z grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Niechajże wysławiają przed Panem miłosierdzie jego, a dziwne sprawy jego przed synami ludzkimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'I ofiarując ofiary chwały, niech opowiadają sprawy jego z wesołem śpiewaniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Którzy się pławią na morzu w okrętach, pracujący na wodach wielkich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Ci widują sprawy Pańskie, i dziwy jego na głębi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Jako jedno rzecze, wnet powstanie wiatr gwałtowny, a podnoszą się nawałności morskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Wstępują aż ku niebu, i zaś zstępują do przepaści, tak, iż się dusza ich w niebezpieczeństwie rozpływa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Bywają miotani, a potaczają się jako pijany, a wszystka umiejętność ich niszczeje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Gdy wołają do Pana w utrapieniu swojem, z ucisków ich wybawia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Obraca burzę w ciszę, tak, że umilkną nawałności ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'I weselą się, że ucichło; a tak przywodzi ich do portu pożądanego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Niechajże wysławiają przed Panem miłosierdzie jego, a dziwne sprawy jego przed synami ludzkimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Niech go wywyższają w zgromadzeniu ludu, a w radzie starców niechaj go chwalą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Obraca rzeki w pustynię, a potoki wód w suszę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Ziemię urodzajną obraca w niepłodną dla złości tych, którzy w niej mieszkają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Pustynie obraca w jeziora, a ziemię suchą w strumienie wód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'I osadza w nich głodnych, aby zakładali miasta ku mieszkaniu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Którzy posiewają pole, a sadzą winnice, i zgromadzają sobie pożytek z urodzaju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Takci im on błogosławi, że się bardzo rozmnażają, a dobytku ich nie umniejsza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Ale podczas umniejszeni i poniżeni bywają okrucieństwem, nędzą, i utrapieniem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Gdy wylewa wzgardę na książąt, dopuszczając, aby błądzili po puszczy bezdrożnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Onci nędznego z utrapienia podnosi, i rozmnaża rodzinę jego jako trzodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'To widząc uprzejmi rozweselą się, a wszelka nieprawość zatka usta swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Ale któż jest tak mądry, aby to upatrywał, i wyrozumiewał wszystkie litości Pańskie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Pieśń psalmu samego Dawida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Gotowe jest serce moje, Boże! śpiewać i wysławiać cię będę, także i chwała moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Ocućże się lutnio i harfo! gdy na świtaniu powstaję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Wysławiać cię będę między ludźmi, Panie! a będęć śpiewał między narodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Albowiem większe jest nad niebiosa miłosierdzie twoje, i aż pod obłoki prawda twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Wywyszże się nad niebiosa, o Boże! a nad wszystkę ziemię chwała twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Niech będą wybawieni umiłowami twoi; zachowajże ich prawicą swoją, a wysłuchaj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Bóg mówił przez świętobliwość swoję; dlatego się weselić będę, że rozdzielę Sychem, a dolinę Sukkot rozmierzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Mojeć jest Galaad, mój i Manases, a Efraim mocą głowy mojej, Juda zakonodawca mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Moab jest miednicą do umywania mego, na Edoma porzucę obuwie moje: przeciwko Filistynom trąbić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Któż mię zaprowadzi do miasta obronnego? Któż mię przywiedzie aż do ziemi edomskiej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Izali nie ty, o Boże! któryś nas był odrzucił, a nie wychodziłeś, o Boże! z wojskami naszemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Dajże nam pomoc z ucisku; albowiem omylna jest pomoc ludzka. W Bogu sobie mężnie poczynać będziemy, a on podepcze nieprzyjaciół naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy. O Boże chwały mojej! nie milcz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Bo się usta niepobożnego, i usta kłamliwe przeciwko mnie otworzyły; mówili przeciwko mnie językiem kłamliwym,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'A słowy jadowitemi ogarnęli mię, walcząc przeciwko mnie bez wszekiej przyczyny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Przeciwili mi się za miłość moję, chociażem się za nich modlił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Oddawają mi złem za dobre; a nienawiścią za miłość moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Postawże nad nim bezbożnika, a przeciwnik niech stoi po prawej ręce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Gdy przed sądem stanie, niech wynijdzie potępionym, a modlitwa jego niech się w grzech obróci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Niech będą dni jego krótkie, a przełożeństwo jego niech inny weźmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Niech dzieci jego będą sierotami, a żona jego wdową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Niech będą biegunami i tułaczami synowie jego, niech żebrzą, a niech żebrzą wychodząc z pustek swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Niech lichwiarz załapi wszystko, co jest jego, a niech obcy rozchwycą pracę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Niech nie będzie ktoby mu miłosierdzie pokazał, niech nie będzie, ktoby się zmiłował nad sierotami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Potomkowie jego niech z korzenia wycięci będą; w drugiem pokoleniu niech będzie wygładzone imię ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Niech przyjdzie na pamięć nieprawość przodków jego przed Panem, a grzech matki jego niechaj nie będzie zgładzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Niech będą przed Panem ustawicznie, ażby wygładził z ziemi pamiątkę ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Przeto, że nie pamiętał, aby czynił miłosierdzie, ale prześladował człowieka nędznego i ubogiego,a tego,który był serca utrapionego, chciał zamordować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Ponieważ umiłował przeklęstwo, niechże przyjdzie na niego; niechciał błogosławieństwa niechże będzie oddalone od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'A tak niech będzie obleczony w przeklęstwo, jako w szatę swoję; a niech wnijdzie jako woda we wnętrzności jego, a jako olej w kości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Niech mu to będzie jako płaszcz do przodziania, a jako pas dla ustawicznego opasywania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Takowa zapłata niech będzie przeciwnikom moim od Pana, i tym, którzy źle mówią przeciwko duszy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Ale ty, Panie! o Panie! użyj nademną litości dla imienia twego; a iż dobre jest miłosierdzie twoje, wyrwijże mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Bomci ja jest ubogi i nędzny, a serce moje zranione jest w wnętrznościach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Jako cień, który ustępuje, uchodzić muszę; zganiają mię jako szarańczę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Kolana moje upadają od postu, a ciało moje wychudło z tłustości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Nadto stałem się im pośmiewiskiem; gdy mię widzą, kiwają głowami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Wspomóżże mię, o Panie, Boże mój! zachowaj mię według miłosierdzia swego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Tak, aby poznać mogli, iż to ręka twoja, a żeś ty, Panie! to uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Niechże oni przeklinają, ty błogosław; którzy powstali, niech będą zawstydzeni, aby się weselił sługa twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Niech będą przeciwnicy moi w hańbę obleczeni, a niech się przyodzieją, jako płaszczem, zelżywością swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Będę Pana wielce wysławiał usty swemi, a w pośród wielu chwalić go będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Przeto, że stoi po prawej stronie nędznemu, aby go wybawił od tych, którzy osądzają duszę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Psalm Dawidowy. Rzekł Pan Panu memu: Siądź po prawicy mojej, dokąd nie położę nieprzyjaciół twoich podnóżkiem nóg twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Laskę mocy twojej pośle Pan z Syonu, mówiąc: Panuj w pośród nieprzyjaciół twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Lud twój będzie dobrowolny w dzień zwycięstwa twego, w ozdobie świętobliwości, a rozrodzi się płód twój z żywota jako rosa na świtaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Przysiągł Pan, a nie będzie tego żałował, mówiąc: Tyś jest kapłanem na wieki według porządku Melchisedechowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Pan po prawicy twojej potrze królów w dzień gniewu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Będzie sądził narody, i wszystko napełni trupami; potłucze głowę nad wielą ziem panującą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Z strumienia na drodze pić będzie; przetoż wywyższy głowę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Halleluja. Będę wysławiał Pana całem sercem w radzie szczerych, i w zgromadzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Wielkie sprawy Pańskie, jawne u wszystkich, którzy się w nich kochają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Chwalebne i ozdobne dzieło jego, a sprawiedliwość jego trwa na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Pamiątkę cudów swoich uczynił miłosierny a litościwy Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Dał pokarm tym, którzy się go boją, pamiętając wiecznie na przymierze swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Moc spraw swoich oznajmił ludowi swemu, dawszy im dziedzictwo pogan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Uczynki rąk jego prawda i sąd; nieodmienne są wszystkie przykazania jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Utwierdzone na wieki wieczne, uczynione w prawdzie i w szczerości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Wykupienie posławszy ludowi swemu, przykazał na wieki strzedź przymierza swego; święte i straszne jest imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Początek mądrości jest bojaźń Pańska; rozumu dobrego nabywają wszyscy, którzy rozkazanie Pańskie czyną; chwała jego trwa na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Halleluja. Błogosławiony mąż, który się Pana boi, a w przykazaniach jego ma wielkie kochanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Możne będzie na ziemi nasienie jego; rodzina szczerych błogosławiona będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Majętność i bogactwa są w domu jego, a sprawiedliwość jego trwa na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Szczerym w ciemnościach światłość wschodzi; łaskawy, miłosierny, i sprawiedliwy jest Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Dobry człowiek litościwym jest, i pożycza, a rzeczy swe miarkuje rozsądkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Bo na wieki nie będzie poruszony; w pamięci wiecznej będzie sprawiedliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Słysząc złe nowiny, nie boi się; stateczne serce jego ufa w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Umocnione serce jego nie boi się, aż ogląda pomstę nad nieprzyjaciołmi swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Rozprasza, i daje ubogim; sprawiedliwość jego trwa na wieki; róg jego wywyższy się w sławie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Widząc to niepobożny, będzie się gniewał, i zębami swemi zgrzytał, i schnąć będzie; żądość niepobożnych zginie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Halleluja. Chwalcie słudzy Pańscy, chwalcie imię Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Niechaj będzie imię Pańskie błogosławione, odtąd aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Od wschodu słońca, aż do zachodu jego, niech będzie chwalebne imię Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Pan jest nad wszystkie narody wywyższony; chwała jego nad niebiosa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Któż taki, jako Pan Bóg nasz, który mieszka na wysokości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Który się zniża, aby widział, co jest na niebie i na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Podnosi z prochu nędznego, a z gnoju wywyższa ubogiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Aby go posadził z książętami, z książętami ludu swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Który sprawia, że niepłodna w domu bywa matką weselącą się z dziatek. Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Gdy wychodził Izrael z Egiptu i dom Jakóbowy z narodu obcego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Stał się Juda poświęceniem jego, Izrael panowaniem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'To widząc morze, uciekło a Jordan wrócił się nazad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Góry skakały jako barany, pogórki jako jagnięta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Morze! cóż ci się stało, iżeś uciekło? O Jordanie! żeś się nazad wrócił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Góry! żeście skakały jako barany? pagórki! jako jagnięta?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Przed obliczem Pańskiem zadrżała ziemia, przed obliczem Boga Jakóbowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Który obraca opokę w jezioro wód, a krzemień w źródło wód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Nie nam, Panie! nie nam, ale imieniowi twemu daj chwałę dla miłosierdzia twego, i dla prawdy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Czemuż mają mówić poganie: Gdzież teraz jest Bóg ich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Wszakże Bóg nasz jest na niebie, czyniąc wszystko, co mu się podoba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Ale bałwany ich są srebro i złoto, robota rąk ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Usta mają, a nie mówią; oczy mają, a nie widzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Uszy mają, a nie słyszą; nozdrze mają, a nie wonieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Ręce mają, a nie macają; nogi mają, a nie chodzą, ani wołają gardłem swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Niech im podobni będą, którzy je czynią, i wszyscy, którzy w nich ufają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Izraelu! ufaj w Panu; bo on jest pomocnikiem ich i tarczą ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Domie Aaronowy! ufajcie w Panu; on jest pomocnikiem, i tarczą ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Którzy się boicie Pana, ufajcie w Panu; on jest pomocnikiem i tarczą ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Pan będzie pamiętał na nas, będzie błogosławił; będzie błogosławił domowi Izraelskiemu, będzie błogosławił domowi Aaronowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Będzie błogosławił tym, którzy się boją Pana, małym i wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Rozmnoży was Pan, was i synów waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Błogosławieniście wy od Pana, który stworzył niebo i ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Niebiosa są niebiosa Pańskie; ale ziemię dał synom ludzkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Umarli nie będą chwalili Pana, ani kto z tych, co zstępują do miejsca milczenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Ale my będziemy błogosławili Panu, odtąd aż na wieki. Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Miłuję Pana, iż wysłuchał głos mój, i prośby moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Albowiem nakłonił ucha swego ku mnie, gdym go wzywał za dni moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Ogarnęły mię były boleści śmierci, a utrapienia grobu zjęły mię; ucisk i boleść przyszła na mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'I wzywałem imienia Pańskiego, mówiąc: Proszę, o Panie! wybaw duszę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Miłościwy Pan i sprawiedliwy, Bóg nasz litościwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Pan prostaczków strzeże; byłem uciśniony, a wspomógł mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Nawróć się, duszo moja! do odpocznienia swego; albowiem ci Pan dobrze uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Bo wyrwał duszę moję od śmierci, oczy moje od płaczu, nogę moję od upadku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Będę chodził ustawicznie przed oblicznością Pańską w ziemi żyjących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Uwierzyłem, dlategom mówił, chociażem bardzo był utrapiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Jam był rzekł w zatrwożeniu mojem: Wszelki człowiek kłamca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Cóż oddam Panu za wszystkie dobrodziejstwa jego, które mi uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Kielich obfitego zbawienia wezmę, a imienia Pańskiego wzywać będę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Śluby moje oddam Panu, a to zaraz przed wszystkim ludem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Droga jest przed oczyma Pańskiemi śmierć świętych jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'O mój Panie! żem ja sługą twoim, jam sługą twoim, synem służebnicy twojej, rozwiązałeś związki moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Tobie ofiarować będę ofiarę chwały, i imienia Pańskiego wzywać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Śluby moje oddam Panu, a to zaraz przed wszystkim ludem jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'W przysionkach domu Pańskiego, w pośrodku ciebie, Jeruzalemie! Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Chwalcie Pana wszystkie narody! chwalcie go wszyscy ludzie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Albowiem rozszerzone jest nad nami miłosierdzie jego, a prawda Pańska trwa na wieki. Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Wysławiajcie Pana, albowiem dobry; albowiem na wieki trwa miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Rzecz teraz, Izraelu! że na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Rzecz teraz, domie Aaronowy! że na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Rzeczcież teraz, którzy się boicie Pana, że na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'W ucisku wzywałem Pana; wysłuchał mię, i na przestrzeństwie postawił mię Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Pan jest zemną, nie będę się bał, żeby mi co uczynił człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Pan jest zemną między pomocnikami mymi; przetoż ja oglądam pomstę nad tymi, którzy mię mają w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Lepiej mieć nadzieję w Panu, niżeli ufać w człowieku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Lepiej mieć nadzieję w Panu, niżeli ufać w książętach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Wszystkie narody ogarnęły mię; ale w imieniu Pańskim wygubiłem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Częstokroć mię ogarnęły; ale w imieniu Pańskiem wygubiłem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Ogarnęły mię jako pszczoły, ale zgasły jako ogień z ciernia; bo w imieniu Pańskiem wytraciłem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Bardzoś potężnie na mię nacierał, abym upadł; ale Pan poratował mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Pan jest mocą moją, i pieśnią moją; on był moim wybawicielem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Głos wykrzykania i zbawienia w przybytkach sprawiedliwych, prawica Pańska dokazała mocy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Prawica Pańska wywyższyła się; prawica Pańska dokazała mocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Nie umrę, ale będę żył, abym opowiadał sprawy Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Pokarałci mię Pan srodze; ale mię na śmierć nie podał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Otwórzcie mi bramy sprawiedliwości, a wszedłszy w nie będę wysławiał Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Tać jest brama Pańska, którą sprawiedliwi wchodzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Tuć ja ciebie wysławiać będę; boś mię wysłuchał, i byłeś wybawicielem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Kamień, którzy odrzucili budujący, uczyniony jest głową węgielną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Od Pana się to stało, a jest dziwno w oczach naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Tenci to dzień, który uczynił Pan; rozweselmyż się, a rozradujmy się weń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Proszę, Panie! zachowajże teraz; proszę Panie! zdarz teraz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Błogosławiony, który przychodzi w imię Pańskie; błogosławimy wam z domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Bógci Panem, onci nas oświecił; przywiążcie baranki powrozami ku ofierze aż do rogów ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Tyś jest Bóg mój; przetoż cię wysławiać będę, Boże mój! wywyższać cię będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Wysławiajcież Pana, albowiem jest dobry: albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Błogosławieni, którzy żyją bez nagany, którzy chodzą w zakonie Pańskim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Błogosławieni, którzy strzegą świadectw jego, i którzy go ze wszystkiego serca szukają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'I którzy nie czynią nieprawości, ale chodzą drogami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Tyś przykazał, aby pilnie strzeżono rozkazań twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Oby wyprostowane były drogi moje ku przestrzeganiu praw twoich!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Tedy nie będę zawstydzony, gdy się będę oglądał na wszystkie rozkazania twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Będę cię wysławiał w szczerości serca, gdy się nauczę praw sprawiedliwości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Ustaw twoich z pilnością strzedz będę; tylko mię nie opuszczaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Jakim sposobem oczyści młodzieniec ścieszkę swoję? Gdy się zachowa według słowa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Ze wszystkiego serca mego szukam cię; nie dopuszczajże mi błądzić od rozkazań twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'W sercu mojem składam wyroki twoje, abym nie zgrzeszył przeciwko tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Błogosławionyś ty, Panie! nauczże mię ustaw twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Wargami mojemi opowiadam wszystkie sądy ust twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'W drodze świadectw twoich kocham się więcej, niż we wszystkich bogactwach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'O przykazaniach twoich rozmyślam, i przypatruję się drogom twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'W ustawach twoich kocham się, i nie zapominam słów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Daruj to słudze twemu, abym żył, a przestrzegał słów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Odsłoń oczy moje, abym się przypatrzył dziwom z zakonu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Jestem gościem na ziemi; nie ukrywaj przedemną rozkazań twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Omdlewa dusza moja, pragnąc sądów twoich na każdy czas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Wytraciłeś pysznych; przeklęci są ci, którzy błądzą od rozkazań twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Oddal odemnie pohańbienie i wzgardę, gdyż strzegę świadecwt twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'I książęta zasiadają, a mówią przeciwko mnie; wszakże sługa twój rozmyśla w ustawach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Świadectwa twoje zaiste są mojem kochaniem, i radcami mymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Przylgnęła do prochu dusza moja; ożywże mię według słowa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Drogi moje rozpowiedziałem, a wysłuchałeś mię; naucz mię ustaw twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Daj, abym zrozumiał drogę rozkazań twoich, ażebym rozmyślał o dziwnych sprawach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Rozpływa się od smutku dusza moja; utwierdźże mię według słowa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Drogę kłamliwą oddal odemnie, a zakonem twoim udaruj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Obrałem drogę prawdy, a sądy twoje przekładam sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Przystałem do świadectw twoich; Panie! nie zawstydzajże mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Drogą przykazań twoich pobieżę, gdy rozszerzysz serce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Naucz mię, Panie! drogi ustaw twoich, a będę jej strzegł aż do końca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Daj mi rozum, abym strzegł zakonu twego, ażebym go przestrzegał ze wszystkiego serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Daj, abym chodził ścieżką przykazań twoich, gdyż w tem jest upodobanie moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Nakłoń serce moje do świadectw twoich, a nie do łakomstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Odwróć oczy moje, aby nie patrzały na marność; na drodze twojej ożyw mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Utwierdź wyrok twój słudze twemu, który się oddał bojaźni twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Oddal odemnie pohańbienie moje, którego się boję; bo sądy twoje dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Oto pragnę rozkazań twoich; w sprawiedliwości twojej ożyw mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Niech na mię przyjdą litości twoje, Panie! i zbawienie twoje według wyroku twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Tak abym odpowiedź mógł dać samą rzeczą temu, który mi urąga, gdyż ufam w słowie twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'A nie wyjmuj z ust moich słowa najprawdziwszego; albowiem sądów twoich oczekuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'I będę strzegł zakonu twego zawsze, aż na wieki wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'A ustawicznie będę chodził na przestrzeństwie, bom się dopytał rozkazań twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Owszem, będę mówił o świadectwach twoich przed królmi, a nie będę zawstydzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Bom się rozkochał w przykazaniach twoich, którem umiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Przyłożę i ręce moje do rozkazań twoich, które miłuję, a będę rozmyślał o ustawach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Wspomnij na słowo wyrzeczone do sługi twego, któremeś mię ubezpieczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Toć pociecha moja w utrapieniu mojem, że mię wyrok twój ożywia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Pyszni bardzo się ze mnie naśmiewają; wszakże się od zakonu twego nie uchylam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Bo pamiętam na sądy twoje wieczne, Panie! któremi się cieszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Strach mię ogarnął nad niezbożnymi, którzy opuszczają zakon twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Są mi ustawy twoje pieśniami w domu pielgrzymstwa mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Wspominam sobie i w nocy na imię twoje, Panie! i strzegę zakonu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Toć mam z tego, że przestrzegam przykazań twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Rzekłem: Panie! to jest cząstka moja, przestrzegać słów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Modlę się przed obliczem twojem ze wszystkiego serca; zmiłujże się nademną według słowa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Uważyłem w myślach drogi moje, a obróciłem nogi moje ku świadectwom twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Śpieszę się, a nie omieszkuję przestrzegać rozkazań twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Hufy niepobożnych złupiły mię; ale na zakon twój nie zapominam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'O północy wstaję, abym cię wysławiał w sądach sprawiedliwości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Jestem towarzyszem wszystkich, którzy się ciebie boją, i tych, którzy przestrzegają przykazań twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Panie! pełna jest ziemia miłosierdzia twego; nauczże mię ustaw twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Łaskawieś postąpił ze sługą twoim, Panie! według słowa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Dobrego rozumu i umiejętności naucz mię; bom przykazaniom twoim uwierzył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Pierwej niżem się był uniżył, błądziłem; ale teraz wyroku twego przestrzegam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Dobryś ty i dobrotliwy; nauczże mię ustaw twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Uknowali hardzi kłamstwo przeciwko mnie; ale ja ze wszystkiego serca strzegę przykazań twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Serce ich zatyło jako sadło; ale się ja zakonem twoim cieszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Jest mi to ku dobremu, żem był utrapiony, abym się nauczył ustaw twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Lepszy mi jest zakon ust twoich, niżeli tysiące złota i srebra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Ręce twoje uczyniły mię, i wykształtowały mię; dajże mi rozum, abym się nauczył przykazań twoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Aby się radowali bojący się ciebie, ujrzawszy mię, że na słowo twoje oczekuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Znam, Panie! iż są sprawiedliwe sądy twoje, a iżeś mię słusznie utrapił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Niechajże mię, proszę, ucieszy miłosierdzie twoje według wyroku twego, któryś uczynił słudze twemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Niechże na mię przyjdą litości twoje, abym żył; bo zakon twój jest kochaniem mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Niech będą zawstydzeni pyszni, przeto, że mię chytrze podwrócić chcieli; ale ja rozmyślać będę w przykazaniach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Niech się obrócą do mnie, którzy się ciebie boją, i którzy znają świadectwa twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Niech będzie serce moje uprzejme przy ustawach twoich, abym nie był zawstydzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Tęskni dusza moja po zbawieniu twojem, oczekuję na słowo twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Ustały oczy moje, czekając wyroku twego, gdy mówię: Kiedyż mię pocieszysz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Chociażem jest jako naczynie skórzane w dymie, wszakżem ustaw twoich nie zapomniał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Wieleż będzie dni sługi twego? kiedyż sąd wykonasz nad tymi, którzy mię prześladują?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Pyszni pokopali mi doły, co nie jest według zakonu twojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Wszystkie przykazania twoje są prawdą; bez przyczyny mię prześladują; ratujże mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Bez mała mię już wniwecz nie obrócili na ziemi; a wszakżem ja nie opuścił przykazań twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Według miłosierdzia twego ożyw mię, abym strzegł świadectwa ust twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'O Panie! słowo twoje trwa na wieki na niebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Od narodu do narodu prawda twoja; ugruntowałeś ziemię, i stoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Według rozrządzenia twego trwa to wszystko aż do dnia tego; wszystko to zaiste jest ku służbie twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'By był zakon twój nie był kochaniem mojem, dawnobym był zginął w utrapieniu mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Na wieki nie zapomnę na przykazania twoje, gdyżeś mię w nich ożywił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Twójcim ja, zachowajże mię; bo przykazań twoich szukam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Czekają na mię niezbożnicy, aby mię zatracili; ale ja świadectwa twoje uważam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Wszelkiej rzeczy koniec widzę; ale przykazanie twoje bardzo szerokie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'O jakom się rozmiłował zakonu twego! tak, iż każdego dnia jest rozmyślaniem mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Nad nieprzyjaciół moich mędrszym mię czynisz przykazaniem twojem; bo je mam ustawicznie przed sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Nad wszystkich nauczycieli moich stałem się rozumniejszym; bo świadectwa twoje są rozmyślaniem mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Nad starców jestem roztropniejszy; bo przykazań twoich przestrzegam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Od wszelkiej złej drogi zawściągam nogi swoje, abym strzegł słowa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Od sądów twoich nie odstępuję, przeto, że ich ty mnie uczysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'O jako są słodkie słowa twoje podniebieniu memu! nad miód są słodsze ustom moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Z przykazań twoich nabyłem rozumu: przetoż mam w nienawiści wszelką ścieszkę obłędliwą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Słowo twe jest pochodnią nogą moim, a światłością ścieszce mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Przysięgłem i uczynię temu dosyć, że będę strzegł sądów sprawiedliwości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Jestem bardzo utrapiony; o Panie! ożyw mię według słowa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Panie! dobrowolne śluby ust moich przyjmij proszę za wdzięczne, a sądów twoich naucz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Dusza moja jest w ustawicznem niebezpieczeństwie; wszakże na zakon twój nie zapominam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Sidło na mię niezbożnicy zastawili; lecz ja się od przykazań twoich nie obłądzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Za dziedzictwo wieczne wziąłem świadectwa twoje; bo są radością serca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Nakłoniłem serca mego ku wykonywaniu ustaw twoich ustawicznie, i aż do końca (żywota).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Wymysły mam w nienawiści, a zakon twój miłuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Tyś jest ucieczką moją, i tarczą moją; na słowo twoje oczekuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Odstąpcież odemnie złośnicy, abym strzegł rozkazania Boga mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Utwierdźże mię według słowa twego, abym żył, a nie zawstydzaj mię w oczekiwaniu mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Podpieraj mię, abym był zachowany, i rozmyślał w ustawach twoich ustawicznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Podeptałeś wszystkich, którzy się obłądzili od ustaw twoich; albowiem jest kłamliwa zdrada ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Odrzucasz jako zużelicę wszystkich niezbożników ziemi; dla tego miłuję świadectwa twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Drży od strachu przed tobą ciało moje; bo się sądów twoich lękam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Czynię sądy i sprawiedliwość: nie podawajże mię tym, którzy mi gwałt czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Zastąp sam sługę twego ku dobremu, aby mię hardzi nie potłoczyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Oczy moje ustały, czekając na zbawienie twoje, i na wyrok sprawiedliwości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Obchodź się z sługą twoim według miłosierdzia twego, a ustaw twoich naucz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Sługamci ja twój, dajże mi zrozumienie; abym umiał świadectwa twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Czasci już, abyś czynił Panie! albowiem wzruszono zakon twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Dlatego umiłowałem rozkazania twoje nad złoto, a nad złoto najwyborniejsze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Przeto, że wszystkie przykazania twoje, wszystkie prawdziwe być uznaję, a wszelkie ścieżki obłędliwe mam w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Dziwne są świadectwa twoje; przetoż ich strzeże dusza moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Początek słów twoich oświeca i daje rozum prostakom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Usta moje otwieram i dyszę; albowiemem przykazań twoich pragnął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Wejżyjże na mię, a zmiłuj się nademną weaług prawa tych, którzy miłują imię twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Drogi moje utwierdź w słowie twojem, a niech nademną nie panuje żadna nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Wybaw mię od uciśnienia ludzkiego, abym strzegł rozkazań twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Rozświeć nad sługą twoim oblicze twoje, a naucz mię ustaw twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Strumienie wód płyną z oczów moich dla tych, którzy nie strzegli zakonu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Sprawiedliwyś ty, Panie! i prawdziwy w sądach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Przykazałeś sprawiedliwe świadectwa twoje, i wielce prawdziwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Zniszczyła mię gorliwość moja, iż zapominają na słowo twoje nieprzyjaciele moi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Doskonale są doświadczone słowa twoje; dlatego się sługa twój w nich rozkochał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Jam maluczki i wzgardzony; wszakże przykazań twoich nie zapominam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Sprawiedliwość twoja sprawiedliwość wieczna, a zakon twój prawda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Ucisk i utrapienie przyszło na mię; przykazania twoje są kochaniem mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Sprawiedliwość świadectw twoich trwa na wieki; daj mi rozum, a żyć będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Wołam ze wszystkiego serca, wysłuchajże mię, o Panie! a będę strzegł ustaw twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Wołam do ciebie, zachowajże mię, a będę pilen świadectw twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Uprzedzam cię na świtaniu i wołam, na słowo twoje oczekując.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Uprzedzają straż nocną oczy moje, przeto, abym rozmyślał o wyrokach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Panie! głos mój usłysz według miłosierdzia twego; według sądu twego ożyw mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Przybliżają się, którzy naśladują złości, ci, którzy się od zakonu twego oddalili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Bliskoś ty jest, Panie! a wszystkie przykazania twoje są prawdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Dawno to wiem o świadectwach twoich, żeś je na wieki ugruntował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Obacz utrapienie moje, a wyrwij mię; bom na zakon twój nie zapomniał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Stań przy sprawie mojej, a obroń mię; dla słowa twego ożyw mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Dalekoć jest od niezbożników zbawienie; bo się nie badają o ustawach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Wielkie są litości twoje, Panie! według sądów twoich ożyw mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Wieleć jest prześladowców moich i nieprzyjaciół moich; wszakże od świadectw twoich nie uchylam się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Widziałem przestępców, i mierziało mię to, że wyroku twego nie przestrzegali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Obaczże Panie! iż rozkazania twoje miłuję; według miłosierdzia twego ożyw mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Najprzedniejsza rzecz słowa twego jest prawda, a na wieki trwa wszelki sąd sprawiedliwości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Książęta mię prześladują bez przyczyny; wszakże słów twoich boi się serce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Ja się weselę z wyroku twego, tak jako ten, który znajduje wielkie korzyści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Ale nienawidzę kłamstwa, i brzydzą się niem; ale zakon twój miłuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Chwalę cię siedm kroć przez dzień, dla sądów twoich sprawiedliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Pokój wielki dajesz tym, którzy miłują zakon twój, a nie doznawają żadnego obrażenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Panie! oczekuję zbawienia twego; a przykazania twoje wykonywam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Przestrzega dusza moja świadectw twoich; albowiem je bardzo miłuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Przestrzegam przykazań twoich i świadectw twoich; albowiem wszystkie drogi moje są przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Panie! niech się przybliży wołanie moje przed oblicze twoje; według słowa twego daj mi zrozumienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Niech przyjdzie prośba moja przed twarz twoję, a według obietnicy twojej wyrwij mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Chwałę wydadzą wargi moje, gdy mię nauczysz ustaw twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Opowiadać będzie język mój wyroki twoje; bo wszystkie przykazania twoje są sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Niech mi będzie na pomocy ręka twoja, gdyżem sobie obrał przykazania twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Panie! zbawienia twego pragnę, a zakon twój jest kochaniem mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Żyć będzie dusza moja, i będzie cię chwaliła, a sądy twoje będą mi na pomocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Błądzę jako owca zgubiona, szukajże sługi twego; boć przykazań twoich nie zapominam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Pieśń stopni. Wołałem do Pana w utrapieniu mojem, a wysłuchał mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Wyzwól, Panie! duszę moję od warg kłamliwych, i od języka zdradliwego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Cóż ci da, albo coć za pożytek przyniesie język zdradliwy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Który jest jako strzały ostre mocarza, i jako węgle jałowcowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Niestetyż mnie, żem tak długo gościem w Mesech, a mieszkam w namiotach Kedarskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Długo mieszka dusza moja między tymi, którzy pokój mają w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Jać radzę do pokoju; ale gdy o tem mówię, oni do wojny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Pieśń stopni. Oczy moje podnoszę na góry, skądby mi pomoc przyszła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Pomoc moja jest od Pana, który stworzył niebo i ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Nie dopuści, aby się zachwiać miała noga twoja; nie drzemieć stróż twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Oto nie drzemie ani śpi ten, który strzeże Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Pan jest stróżem twoim; Pan jest cieniem twoim po prawej ręce twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'We dnie słońce nie uderzy na cię, ani miesiąc w nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Pan cię strzec będzie od wszystkiego złego; on duszy twojej strzec będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Pan strzec będzie wyjścia twego i wejścia twego, odtąd aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Pieśń stopni Dawidowa. Weselę się z tego, że mi powiedziano: Do domu Pańskiego pójdziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Że stanęły nogi nasze w bramach twoich, o Jeruzalemie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'O Jeruzalem pięknie pobudowane jako miasto w sobie wespół spojone!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Bo tam wstępują pokolenia, pokolenia Pańskie, do świadectwa Izraelowego, aby wysławiały imię Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Albowiem tam są postawione stolice na sąd, stolice domu Dawidowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Żądajcież pokoju Jeruzalemowi, mówiąc: Niech się szczęści tym, którzy cię miłują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Niech będzie pokój w basztach twoich, a uspokojenie w pałacach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Dla braci moich i dla przyjaciół moich teraz ci będę żądał pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Dla domu Pana, Boga naszego, będę szukał twego dobrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Pieśń stopni. Do ciebie oczy moje podnoszę, który mieszkasz w niebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Oto jako oczy sług pilnują rąk panów swych, i jako oczy dziewki pilnują ręki pani swej, tak oczy nasze poglądają na Pana, Boga naszego, aż się zmiłuje nad nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Zmiłuj się nad nami, Panie, zmiłuj się nad nami; bośmy bardzo nasyceni wzgardą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Bardzo jest nasycona dusza nasza pośmiewiskiem bezbożnych, i wzgardą pysznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Pieśń stopni Dawidowa. Gdyby był Pan z nami nie był, (powiedz teraz Izraelu!)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Gdyby był Pan z nami nie był, gdy ludzie powstawali przeciwko nam:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Tedyćby nas byli żywo pożarli w rozpaleniu gniewu swego przeciwko nam;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Tedyćby nas były wody zabrały a strumień porwałby był duszę naszę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Tedyćby były porwały duszę naszę one wody gwałtowne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Błogosławiony Pan, który nas nie podał na łup zębom ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Dusza nasza jako ptaszek uszła z sidła ptaszników; sidło się potargało, a myśmy uszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Wspomożenie nasze w imieniu Pańskiem, który stworzył niebo i ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Pieśń stopni. Którzy ufają w Panu, są jako góra Syon, która się nie poruszy, ale na wieki zostaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Jako około Jeruzalemu są góry, tak Pan jest około ludu swego, od tego czasu aż i na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Albowiem nie zostanie laska niezbożników nad losem sprawiedliwych, by snać nie ściągnęli sprawiedliwi rąk swych ku nieprawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Dobrze czyń, Panie! dobrym, i tym, którzy są uprzejmego serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Ale tych, którzy się udawają krzyewemi drogami swemi, niech zapędzi Pan z tymi, którzy czynią nieprawość; lecz pokój niech będzie nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Pieśń stopni. Gdy zaś Pan nawrócił pojmanych z Syonu, byliśmy jako ci, którym się śni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Tedy były napełnione weselem usta nasze, a język nasz radością; tedy mówiono między narodami: Wielmożne rzeczy Pan uczynił z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Wielmożne rzeczy Pan uczynił z nami, z czegośmy się bardzo uradowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Przywróćże zaś, o Panie! pojmanie nasze, jako strumienie na południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Którzy siali ze łzami, żąć będą z wykrzykaniem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Tam i sam chodząc z płaczem rozsiewa lud drogie nasienie; ale zaś przyszedłszy z radością znosić będzie snopy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Pieśń stopni dla Salomona. Jeźli Pan domu nie zbuduje, próżno pracują ci, którzy go budują; jeźli Pan nie będzie strzegł miasta, próżno czuje ten, który go strzeże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Próżno macie rano wstawać, długo siadać, i jeść chleb boleści, ponieważ Pan umiłowanemu swemu sen daje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Oto dziatki są dziedzictwem od Pana, a płód żywota nagrodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Jako strzały w ręku mocarza, tak są dziatki, które się darzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Błogosławiony mąż, który niemi napełnił sajdak swój; nie będą zawstydzani, gdy się w bramie rozpierać będą z nieprzyjaciołmi swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Pieśń stopni. Błogosławiony wszelki, który się boi Pana, który chodzi drogami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Bo prace rąk twoich pożywać będziesz; błogosławionym będziesz, i będzieć się dobrze działo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Żona twoja będzie jako winna macica płodna po bokach domu twego; dziatki twoje jako latorośle oliwne około stołu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Oto takci będzie ubłogosławiony mąż, który się boi Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Niechżeć Pan błogosławi z Syonu, abyś patrzył na dobro Jeruzalemskie po wszystkie dni żywota twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'I oglądał synów synów twoich, i pokój nad Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Pieśń stopni. Bardzoć mię utrapili zaraz od młodości mojej, powiedz teraz Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Bardzoć mię utrapili od młodości mojej, wszakże mię nie przemogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Po grzbiecie moim orali oracze, i długie przeganiali brózdy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Ale Pan sprawiedliwy poprzecinał powrozy niezbożników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Zawstydzeni i nazad obróceni będą wszyscy, którzy Syon mają w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Będą jako trawa na dachu, która pierwej, niż odrośnie, usycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Z której żeńca nie może garści swej napełnić; ani naręcza swego ten, który wiąże snopy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'I mimo idący nie rzeką: Błogosławieństwo Pańskie niech będzie z wami; albo: Błogosławimy wam w imieniu Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Pieśń stopni. Z głębokości wołam do ciebie, o Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Panie! wysłuchaj głos mój: nakłoń uszów twych do głosu prośb moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Panie! będzieszli nieprawości upatrywał, Panie! któż się zostoi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Aleć u ciebie jest odpuszczenie, aby się ciebie bano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Oczekuję na Pana; oczekuje dusza moja, i jeszcze oczekuje na słowo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Dusza moja oczekuje Pana, pilniej niż straż świtania, która strzeże aż do poranku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Oczekujże, Izraelu! na Pana; albowiem u Pana jest miłosierdzie, a obfite u niego odkupienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Onci sam odkupi Izraela od wszystkich nieprawości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Pieśń stopni Dawidowa. Panie! nie wyniosło się serce moje, ani się wyniosły oczy moje, anim się kusił o rzeczy wielkie, albo wyższe nad to, niż mi należy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Izalim nie położył i nie uspokoił duszy mojej, jako dziecię odstawione od matki swej? odstawionemu dziecięciu była podobna we mnie dusza moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Miejże nadzieję w Panu, o Izraelu! odtąd aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Pieśń stopni. Na Dawida pomnij, Panie! na wszystkie utrapienia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Który przysiągł Panu, a ślub uczynił mocarzowi Jakóbowemu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Zaiste nie wnijdę do przybytku domu mego, i nie wstąpię na posłanie łoża mego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'I nie pozwolę snu oczom moim, ani powiekom moim drzemania,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Dokąd nie znajdę miejsca dla Pana, na mieszkania mocarzowi Jakóbowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Oto usłyszawszy o niej w Efracie, znaleźliśmy ją na polach leśnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Wnijdźmyż do przybytków jego, a kłaniajmy się u podnóżka nóg jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Powstańże Panie! a wnijdź do odpocznienia twego, ty, i skrzynia możności twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Kapłani twoi niech się obloką w sprawiedliwość, a święci twoi nie się rozradują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Dla Dawida, sługi twego, nie odwracaj oblicza pomazańca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Przysiągł Pan Dawidowi prawdę, a nie uchyli się od niej, mówiąc: Z owocu żywota twego posadzę na stolicy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Będąli strzegli synowie twoi przymierza mojego, i świadectw moich, których ich nauczę: tedy i synowie ich aż na wieki będą siedzieli na stolicy twojej');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Albowiem obrał Pan Syon, i upodobał go sobie na mieszkanie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Toć będzie odpocznienie moje aż na wieki; tu będę mieszkał, bom go siebie upodobał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Żywność jego będę obficie błogosławił, a ubogich jego nasycę chlebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Kapłanów jego przyoblokę zbawieniem, a święci jego weseląc się, radować się będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Tam sprawię, że zakwitnie róg Dawidowy; tam zgotuję pochodnię pomazańcowi memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Nieprzyjaciół jego przyoblokę wstydem; ale nad nim rozkwitnie się korona jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Pieśń stopni Dawidowa. Oto jako rzecz dobra, i jako wdzięczna, gdy bracia zgodnie mieszkają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Jest jako olejek najwyborniejszy wylany na głowę, ściekający na brodę, na brodę Aaronową, ściekający aż i na podołek szat jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Jako rosa Hermon, która zstępuje na góry Syońskie; albowiem tam daje Pan błogosławieństwo i żywot aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Pieśń stopni. Ej nuż błogosławcie Panu wszyscy słudzy Pańscy, którzy stawacie w domu Pańskim na każdą noc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Podnoście ręce wasze ku świątnicy, a błogosławcie Panu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Niechajżeć błogosławi Pan z Syonu, który stworzył niebo i ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Halleluja. Chwalcie imię Pańskie, chwalcie słudzy Pańscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Którzy stawacie w domu Pańskim, w sieniach domu Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Chwalcież Pana, albowiem to Pan dobry; śpiewajcież imieniowi jego, boć jest wdzięczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Albowiem sobie Jakóba Pan obrał, i Izraela za własność swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Jać zaiste uznaję, iż wielki jest Pan, a Pan nasz jest nad wszystkich bogów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Wszystko co chce Pan, to czyni, na niebie i na ziemi, w morzu i we wszystkich przepaściach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Który czyni, że występują pary od kończyn ziemi; błyskawice i dżdże przywodzi, wywodzi wiatr z skarbów swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Który pobił pierworodztwa w Egipcie, od człowieka aż do bydlęcia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Posłał znaki i cuda w pośród ciebie, Egipcie! na Faraona i na wszystkich sług jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Który poraził wiele narodów, a pobił królów możnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sehona, króla Amorejskiego, i Oga, króla Basańskiego, i wszystkie królestwa Chananejskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'I dał ziemię ich w dziedzictwo, w dziedzictwo Izraelowi, ludowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Panie! imię twoje na wieki; Panie! pamiątka twoja od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Zaite Pan sądzić będzie lud swój, a nad sługami swymi zmiłuje się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Ale bałwany pogańskie, srebro i złoto, są robotą rąk ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Usta mają, a nie mówią, oczy mają, a nie widzą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Uszy mają, a nie słyszą, ani mają tchnienia w ustach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Niech im podobni będą, którzy je robią, i wszyscy, którzy w nich ufają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Domie Izraelski! błogosławcie Panu; domie Aaronowy! błogosławcie Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Domie Lewiego! błogosławcie Panu, którzy się boicie Pana, błogosławcie Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Błogosławiony Pan z Syonu, który mieszka w Jeruzalemie. Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Wysławiajcież Pana, albowiem jest dobry; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Wysławiajcież Boga nad bogami; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Wysławiajcież Pana nad panami; albowiem na wieki miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Tego, który sam czyni cuda wielkie; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Który mądrze niebiosa uczynił; albowiem na wieki miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Który rozciągnął ziemię na wodach; albowiem na wieki miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Który uczynił światła wielkie; albowiem na wieki miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Słońce, aby panowało we dnie; albowiem na wieki miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Miesiąc i gwiazdy, aby panowały w nocy; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Który poraził Egipczan na pierworodnych ich; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Który wywiódł Izraela z pośrodku ich; albowiem na wieki miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'W ręce mocnej i w ramieniu wyciągnionem; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Który rozdzielił morze Czerwone na rozdziały; albowiem na wieki miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'I przeprowadził lud Izraelski pośrodkiem jego; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'I wrzucił Faraona z wojskiem jego w morze Czerwone; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Który prowadził lud swój przez puszczę; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Który poraził królów wielkich; albowiem na wieki miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'I pobił królów możnych; albowiem na wieki miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sehona; króla Amorejskiego; albowiem na wieki miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'I Oga, króla Basańskiego; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'I dał ziemię ich w dziedzictwo; albowiem na wieki miłosierdzie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'W dziedzictwo Izraelowi, słudze swemu; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Który w uniżeniu naszem pamięta na nas; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'I wybawił nas od nieprzyjaciół naszych; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Który daje pokarm wszelkiemu ciału; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Wysławiajcież Boga niebios; albowiem na wieki miłosierdzie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Nad rzekami Babilońskiemi, tameśmy siadali i płakali, wspominając na Syon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Na wierzbach, które są w nim, zawieszaliśmy harfy nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'A gdy nas tam pytali ci, którzy nas zawiedli w niewolę, o słowa pieśni,(chociażeśmy byli zawiesili pieśni radości,) mówiąc: Śpiewajcie nam pieśń z pieśni Syońskich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Odpowiedzieliśmy: Jakoż mamy śpiewać pieśń Pańską w ziemi cudzoziemców?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Jeźliże cię zapomnę, o Jeruzalemie! niech zapomni sama siebie prawica moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Niech przylgnie język mój do podniebienia mego, jeźlibym na cię nie pomniał, jeźlibym nie przełożył Jeruzalemu nad najwiekszę wesele moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Wspomnij, Panie! na synów Edomskich, i na dzień Jeruzalemski, w który mówili: Poburzcie, poburzcie aż do gruntu w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'O córko Babilońska! i ty będziesz spustoszona. Błogosławiony, któryć odda nagrodę twoję, za to, coś nam złego uczyniła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Błogosławiony, który pochwyci i roztrąci dziatki twe o skałę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Psalm Dawidowy. Wysławiać cię będę, Panie! ze wszystkiego serca mego; przed bogami śpiewać ci będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Będę się kłaniał ku kościołowi twemu świętemu, i będę wysławiał imię twoje dla miłosierdzia twego, i dla prawdy twojej; boś nade wszystko uwielbił imię twoje i wyroki twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'W dzień, któregom cię wzywał, wysłuchałeś mię, a posiliłeś mocą duszę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Wysławiać cię będą, Panie! wszyscy królowie ziemi, gdy usłyszą wyroki ust twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'I będą śpiewali o drogach Pańskich, a iż wielka jest chwała Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'A choć wywyższony jest Pan, wszakże na uniżonego patrzy, a wysokomyślnego z daleka poznaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Jeźlibym chodził w pośród utrapienia, ożywisz mię; przeciw popędliwości nieprzyjaciół moich wyciągniesz rękę twoję, a prawica twoja wyswobodzi mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Pan wszystko za mię wykona. O Panie! miłosierdzie twoje trwa na wieki; sprawy rąk twoich nie opuścisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy. Panie! doświadczyłeś i doznałeś mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Tedy znasz siedzenie moje, i powstanie moje, wyrozumiewasz myśli moje z daleka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Tyś chodzenie moje i leżenie moje ogarnął, świadomeś wszystkich dróg moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Nim przyjdzie słowo na język mój, oto Panie! ty to wszystko wiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Z tyłu i z przodku otoczyłeś mię, a położyłeś na mię rękę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Dziwniejsza umiejętność twoja nad dowcip mój; wysoka jest, nie mogę jej pojąć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Dokąd ujdę przed duchem twoim? a dokąd przed obliczem twojem uciekę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Jeźlibym wstąpił do nieba, jesteś tam; i jeźlibym sobie posłał w grobie, i tameś przytomny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Wziąłlibym skrzydła rannej zorzy, abym mieszkał na końcu morza,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'I tamby mię ręka twoja prowadziła, a dosięgłaby mię prawica twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Albo rzekłlibym: Wżdyć ciemności zakryją mię; aleć i noc jest światłem około mnie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Gdyż i ciemności nic nie zakryją przed tobą; owszem tobie noc jako dzień świeci; ciemnościć są jako światłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Ty zaiste w nocy masz nerki moje; okryłeś mię w żywocie matki mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Wysławiam cię dlatego, że się zdumiewam strasznym i dziwnym sprawom twoim, a dusza moja zna je wybornie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Nie zataiła się żadna kość moja przed tobą, chociażem był uczyniony w skrytości, i misternie złożony w niskościach ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Niedoskonały płód ciała mego widziały oczy twoje; w księgi twoje wszystkie członki moje wpisane są, i dni, w których kształtowane były, gdy jeszcze żadnego z nich nie było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Przetoż o jako drogie są u mnie myśli twoje, Boże! a jako ich jest wielka liczba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Jeźlibym je chciał zliczyć, nad piasek rozmnożyły się; ocucęli się, jeszczem ci ja z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'Zabiłlibyś, o Boże! niezbożnika, tedyćby mężowie krwawi odstąpili odemnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Którzy mówią przeciwko tobie obrzydłości, którzy próżno wynoszą nieprzyjaciół twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Izali tych, którzy cię w nienawiści mają, o Panie! niemam w nienawiści? a ci, którzy przeciwko tobie powstawają, izaż mi nie omierzli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Główną nienawiścią nienawidzę ich, a mam ich za nieprzyjaciół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Wyszpieguj mię, Boże! a poznaj serce moje; doświadcz mię, a poznaj myśli moje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'I obacz, jeźli droga odporności jest we mnie, a prowadź mię drogą wieczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Przedniejszemu śpiewakowi psalm Dawidowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Wyrwij mię, Panie! od człowieka złego, od męża okrutnego strzeż mię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Którzy myślą złe rzeczy w sercu, a na każdy dzień zbierają się na wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Zaostrzają język swój, jako wąż; jad żmij pod wargami ich. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Zachowaj mię, Panie! od rąk bezbożnika; od męża okrutnego strzeż mię, którzy myślili podwrócić nogi moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Hardzi na mię zastawili sidło, i powrozy; rozciągnęli sieci przy ścieszce, a sidła swe zastawili na mię. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Rzekłem Panu: Tyś jest Bóg mój! wysłuchajże, Panie! głos modlitw moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'O Panie, Panie mocy zbawienia mego, który przykrywasz głowę moję w dzień bitwy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Nie dawaj, Panie! bezbożnemu czego żąda; ani myśli jego złej góry nie dawaj, żeby się nie podniósł. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'A wodza tych, którzy mię obstąpili, nieprawość warg ich niech ich okryje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Niech na nich spadną węgle rozpalone; do ognia niech wrzuceni będą, i do dołów głębokich, skądby nie powstali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Potwarca nie będzie utwierdzony na ziemi, a mąż okrutny złością ułowiony będąc upadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Wiem, że Pan uczyni sąd utrapionemu, i pomstę nędznych. A tak sprawiedliwi będą wysławiać imię twoje, a szczerzy będą mieszkać przed obliczem twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Pieśń Dawidowa. Panie! wołam do ciebie, pośpiesz się do mnie: posłuchaj głosu mego, gdy wołam do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Niech będzie przyjemna modlitwa moja, jako kadzidło przed obliczem twoim, a podnoszenie rąk moich jako ofiara wieczorna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Panie! połóż straż ustom moim; strzeż drzwi warg moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Nie nachylaj serca mego do złej rzeczy, abym nie czynił spraw niepobożnych z mężami czyniącymi nieprawość, i żebym się nie karmił rozkoszami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Niech mię bije sprawiedliwy, a przyjmę to za miłosierdzie; i niech mię gromi, a będzie mi to za najwyborniejszy olejek, który nie zarazi głowy mojej; albowiem jeszczeć modlitwa moja płatna będzie przeciwko złości ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Niech będą zrzuceni do miejsc opoczystych sędziowie ich, aby słyszeli słowa moje, że były wdzięczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Jako gdyby kto rąbał i łupał drwa na ziemi, tak się rozlatują kości nasze aż do ust grobowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Ale do ciebie, Panie, Panie! podnoszę oczy moje; w tobie ufam, nie odpychaj duszy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Strzeż mię od sidła, które na mię zastawili, i od sideł czyniących nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Niech wpadną razem w sieci swoje niepobożni, a ja za tem przeminę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Pieśń wyuczająca Dawidowa, gdy był w jaskini, modlitwa jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Głosem moim do Pana wołam; głosem moim Panu się modlę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Wylewam przed obliczem jego żądłość moję, a utrapienie moje przed oblicznością jego oznajmuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Gdy bywa ściśniony duch mój we mnie, ty znasz ścieszkę moję; na drodze, którą chodzę, ukryli na mię sidło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Oglądamli się na prawą stronę, a przypatruję się, niemasz ktoby mię znał; zginęła ucieczka moja, niemasz ktoby się ujął o duszę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Panie! do ciebie wołam, mówiąc: Tyś nadzieja moja, tyś dział mój w ziemi żyjących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Posłuchaj pilnie wołania mego, bom bardzo znędzony; wyrwij mię od tych, którzy mię prześladują, albowiem są mocniejszymi nad mię. Wywiedźże z ciemnicy duszę moję, abym chwalił imię twoje; obstąpią mię sprawiedliwi, gdy mi dobrodziejstwo uczynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Psalm Dawidowy. Panie! wysłuchaj modlitwę moję, a przyjmij w uszy prośby moje; dla prawdy twojej wysłuchaj mię i dla sprawiedliwości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'A nie wchodź w sąd z sługą twoim; albowiem nie będzie usprawiedliwiony przed obliczem twoim żaden żyjący.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Gdyż prześladuje nieprzyjaciel duszę moję, potarł równo z ziemią żywot mój; sprawił to, że muszę mieszkać w ciemnościach, jako ci, którzy z dawna pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'I ściśniony jest we mnie duch mój, a we wnętrznościach moich niszczeje serce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Wspominam sobie dni dawne, i rozmyślam o wszystkich sprawach twoich, i uczynki rąk twoich rozbieram.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Wyciągam ręce moje ku tobie; dusza moja, jako sucha ziemia, ciebie pragnie. Sela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Pośpiesz się, a wysłuchaj mię, Panie! ustaje duch mój; nie ukrywajże oblicza twego przedemną; bomci podobny zstępującym do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Spraw, abym rano słyszał miłosierdzie twoje, bo w tobie ufam; oznajmij mi drogę, którąbym miał chodzić; bo do ciebie podnoszę duszę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Wyrwij mię od nieprzyjaciół moich, Panie! do ciebie się uciekam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Naucz mię czynić wolę twoję, albowiemeś ty Bóg mój; duch twój dobry niech mię prowadzi po ziemi prawej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Dla imienia twego, Panie!ożyw mię; dla sprawiedliwości twojej wywiedź z utrapienia duszę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'I dla miłosierdzia twego wytrać nieprzyjaciół moich, a wygładź wszystkich przeciwników duszy mojej; bom ja sługa twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Pieśń Dawidowa. Błogosławiony Pan, skała moja, który ćwiczy ręce moje do bitwy, a palce moje do wojny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Miłosierdziem mojem, i twierdzą moją, ucieczką moją, wybawicielem moim, i tarczą moją on mi jest, przetoż w nim ufam; onci podbija pod mię lud mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Panie! cóż jest człowiek, że nań masz baczenie? a syn człowieczy, że go sobie poważasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Człowiek marności jest podobny; dni jego jako cień pomijający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Panie! nakłoń niebios twoich, a zstąp; dotknij się gór, a zakurzą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Zabłyśnij błyskawicą, a rozprosz ich; puść strzały twoje, a poraź ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Ściągnij rękę swą z wysokości; wybaw mię, a wyrwij mię z wód wielkich, z ręki cudzoziemców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Których usta kłamstwo mówią, a prawica ich, prawica omylna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Boże! pieśń nową tobie zaśpiewam; na lutni, i na instrumencie o dziesięciu stronach śpiewać ci będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Bóg daje zwycięstwo królom, a Dawida, sługę swego, wybawia od miecza srogiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Wybawże mię, a wyrwij mię z ręki cudzoziemców, których usta mówią kłamstwo, a prawica ich prawica omylna;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Aby synowie nasi byli jako szczepy rosnące w młodości swojej, a córki nasze, jako kamienie węgielne, wyciosane w budynku kościelnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Szpiżarnie nasze pełne niech wydawają wszelakie potrzeby; trzody nasze niech rodzą tysiące, niech rodzą dziesięć tysięcy w oborach naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Woły nasze niech będą tłuste; niech nie będzie wtargnienia, ani zajęcia, ani narzekania po ulicach naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Błogosławiony lud, któremu się tak dzieje. Błogosławiony lud, którego Bogiem jest Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Chwalebna pieśń Dawidowa. Wywyższać cię będę, Boże mój, królu mój! i błogosławić będę imieniowi twemu na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Na każdy dzień błogosławić cię będę, a chwalić imię twoje na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Pan wielki jest i bardzo chwalebny, a wielkość jego nie może być dościgniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Naród narodowi wychwalać będzie sprawy twoje, a mocy twoje opowiadać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Ozdobę chwały wielmożności twojej, i dziwne twe sprawy wysławiać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'I moc strasznych uczynków twoich ogłaszać będą, i ja zacność twoję opowiadać będę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Pamięć obfitej dobroci twojej wysławiać, o sprawiedliwości twojej śpiewać będą, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Dobrotliwy i miłosierny jest Pan, nierychły do gniewu, i wielkiego miłosierdzia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Dobryć jest Pan wszystkim, a miłosierdzie jego nad wszystkiem sprawami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Niech cię wysławiają, Panie! wszystkie sprawy twoje, a święci twoi niech ci błogosławią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Sławę królestwa twego niech opowiadają, a o możności twojej niech rozmawiają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Aby oznajmili synom ludzkim mocy jego, a chwałę i ozdobę królestwa jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Królestwo twoje jest królestwo wszystkich wieków, a panowanie twoje nie ustaje nad wszystkimi narodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Trzyma Pan wszystkich upadających, a podnosi wszystkich obalonych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Oczy wszystkich w tobie nadzieję mają, a ty im dajesz pokarm ich czasu swojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Otwierasz rękę twoję, a nasycasz wszystko, co żyje, według upodobania twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Sprawiedliwy jest Pan we wszystkich drogach swoich, i miłosierny we wszystkich sprawach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Bliski jest Pan wszystkim, którzy go wzywają, wszystkim, którzy go wzywają w prawdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Wolę tych czyni, którzy się go boją, a wołanie ich wysłuchiwa, i ratuje ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Strzeże Pan wszystkich, którzy go miłują; ale wszystkich niepobożnych wytraci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Chwałę Pańską wysławiać będą usta moje; a błogosławić będzie wszelkie ciało imię święte jego na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Chwal, duszo moja! Pana. Chwalić będę Pana, pókim żyw; będę śpiewał Bogu memu, póki mię staje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Nie ufajcie w książętach, ani w żadnym synu ludzkim, w którym nie masz wybawienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Wynijdzie duch jego, i nawróci się do ziemi swojej; w onże dzień zginą wszystkie myśli jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Błogosławiony, którego Bóg Jakóbowy jest pomocnikiem, którego nadzieja jest w Panu, Bogu jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Który uczynił niebo, i ziemię, morze, i wszystko, co w nich jest, który przestrzega prawdy aż na wieki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Który czyni sprawiedliwość ukrzywdzonym, i daje chleb zgłodniałym; Pan rozwiązuje więźniów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Pan otwiera oczy ślepych; Pan podnosi upadłych; Pan miłuje sprawiedliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Pan strzeże przychodniów, sierotce i wdowie pomaga; ale drogę niepobożnych podwraca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Pan będzie królował na wieki; Bóg twój, o Syonie! od narodu do narodu. Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Chwalcie Pana; albowiem dobra rzecz jest, śpiewać Bogu naszemu; albowiem to wdzięczna i przystojna jest chwała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Pan Jeruzalem buduje, a rozproszonego Izraela zgromadza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Który uzdrawia skruszonych na sercu, a zawiązuje boleści ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Który rachuje liczbę gwiazd, a każdą z nich imieniem jej nazywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Wielki jest Pan nasz, i wielki w mocy; rozumienia jego niemasz liczby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Pan pokornych podnosi; ale niepobożnych aż ku ziemi uniża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Śpiewajcież Panu z chwałą; śpiewajcie Bogu naszemu na harfie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Który okrywa niebiosa obłokami, a deszcz ziemi gotuje: który czyni, że rośnie trawa po górach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Który daje bydłu pokarm ich, i kruczętom młodym, które wołają do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Nie kocha się w mocy końskiej, ani się kocha w goleniach męskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Kocha się Pan w tych, którzy się go boją, a którzy ufają w miłosierdziu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Chwalże, Jeruzalemie! Pana; chwalże, Syonie! Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Albowiem on umacnia zawory bram twoich, a błogosławi synów twoich w pośrodku ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'On czyni pokój w granicach twoich, a najwyborniejszą pszenicą nasyca cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'On wysyła słowo swe na ziemię; bardzo prędko bieży wyrok jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'On daje śnieg jako wełnę, szron jako popiół rozsypuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Rzuca lód swój jako bryły; przed zimnem jego któż się ostoi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Posyła słowo swoje, i roztapia je; powienie wiatrem swym, a rozlewają wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Oznajmuje słowo swe Jakóbowi, ustawy swe i sądy swe Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Nie uczynił tak żadnemu narodowi; przetoż nie poznali sądów jego. Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Halleluja. Chwalcie Pana na niebiosach; chwalcież go na wysokościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Chwalcie go wszyscy Aniołowie jego; chwalcie go wszystkie wojska jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Chwalcie go słońce i miesiącu; chwalcie go wszystkie jasne gwiazdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Chwalcie go niebiosa nad niebiosami, i wody, które są nad niebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Chwalcie imię Pańskie; albowiem on rozkazał, a stworzone są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'I wystawił je na wieki wieczne; założył im kres, którego nie przestępują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Chwalcie Pana na ziemi, smoki i wszystkie przepaści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Ogień i grad, śnieg i para, wiatr gwałtowny, wykonywający rozkaz jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Góry, i wszystkie pagórki, drzewa rodzaje, i wszystkie cedry;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Zwierzęta, i wszystko bydło, gadziny, i ptastwo skrzydlaste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Królowie ziemscy, i wszystkie narody; książęta i wszyscy sędziowie ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Młodzieńcy, także i panny, starzy i młodzi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Chwalcie imię Pańskie; albowiem wywyższone jest imię jego samego, a chwała jego nad ziemią i niebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'I wywyższył róg ludu swego, chwałę wszystkich świętych jego, mianowicie synów Izraelskich, ludu jemu najbliższego. Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Halleluja. Śpiewajcie Panu pieśń nową; chwała jego niechaj zabrzmi w zgromadzeniu świętych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Wesel się, Izraelu! w Twórcy swoim; synowie Syońscy! radujcie się w królu swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Chwalcie imię jego na piszczałkach; na bębnie i na harfie grajcie mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Albowiem się kocha Pan w ludu swym; pokornych zbawieniem uwielbia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Radować się będą święci w chwale Bożej, a śpiewać będą w pokojach swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Wysławiania Boże będą w ustach ich, a miecz na obie strony ostry w rękach ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Aby wykonywali pomstę nad poganami, a karali narody;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Aby wiązali pętami królów ich, a szlachtę ich okowami żelaznemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'Aby postąpili z nimi według prawa zapisanego.Tać jest sława wszystkich świętych jego. Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Halleluja. Chwalcie Boga w świątnicy jego; chwalcie go na rozpostarciu mocy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Chwalcie go ze wszelkiej mocy jego; chwalcie go według wielkiej dostojności jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Chwalcie go na głośnych trąbach; chwalcie go na lutni i na harfie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Chwalcie go na bębnie, i na piszczałce; chwalcie go stronach i na organach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Chwalcie go na cymbałach głośnych; chwalcie go cymbałach krzykliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Niech wszelki duch chwali Pana! Halleluja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Przypowieści Salomona, syna Dawidowego, króla Izraelskiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'Dla poznania mądrości i ćwiczenia, ku wyrozumieniu powieści roztropnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'Dla pojęcia ćwiczenia w rozumie, w sprawiedliwości, w sądzie i w prawości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'Dla podania prostakom ostrożności, młodemu umiejętności, i opatrzności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Tych gdy mądry słuchać będzie, przybędzie mu nauki, a roztropny w radach opatrzniejszy będzie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'Aby zrozumiał przypowieści, i wykłady ich, słowa mądrych i zagadki ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Bojaźń Pańska jest początkiem umiejętności; ale głupi mądrością i ćwiczeniem gardzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Słuchaj, synu mój! ćwiczenia ojca twego, a nie opuszczaj nauki matki twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'Bo to przyda wdzięczności głowie twojej, i będzie łańcuchem kosztownym szyi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Synu mój! jeżliby cię namawiali grzesznicy, nie przyzwalaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Jeźlićby rzekli: Pójdź z nami, czyhajmy na krew, zasadźmy się na niewinnego bez przyczyny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'Pożremyż ich żywo, jako grób, a całkiem, jako zstępujących w dół;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'Wszelkiej majętności kosztownej nabędziemy, napełnimy domy nasze korzyścią;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'Rzuć między nas los twój; mieszek jeden wszyscy mieć będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'Synu mójâ nie chodźże z nimi w drogę; zawściągnij nogi twojej od ścieżek ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Albowiem nogi ich ku złemu bieżą, i spieszą się na wylanie krwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Bo jako próżno zastawiają sieci przed oczyma wszelkiego ptaka skrzydlastego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'Tak i ci na krew swoję czyhają, a zasadzają się na duszę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Takieć są ścieszki każdego czyhającego na zysk, który duszę pana swego odbiera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Mądrość na dworzu woła, głos swój na ulicach wydaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'W największym zgiełku woła, u wrót bram, w miastach powieści swoje opowiada, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Prostacy! dokądże się kochać będziecie w prostocie? a naśmiewcy pośmiewisko miłować będziecie? a głupi nienawidzieć umiejętności będziecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Nawróćcież się na karanie moje; oto wam wydam ducha mojego, a podam wam do znajomości słowa moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Ponieważem wołała, a nie chcieliście; wyciągałam rękę moję, a nie był, ktoby uważał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'Owszem odrzuciliście wszystkę radę moję, a karności mojej nie chcieliście przyjąć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'Przetoż ja w zginieniu waszem śmiać się będę, będę z was szydziła, gdy przyjdzie, czego się strachacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'Gdy przyjdzie jako spustoszenie, czego się strachacie, i gdy zginienie wasze przypadnie jako wicher, gdy przyjdzie na was ucisk i utrapienie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Tedy mię wzywać będą, a nie nie wysłucham; szukać mię będą z poranku, a nie znajdą mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'Przeto, iż mieli w nienawiści umiejętność, a bojaźni Pańskiej nie obrali sobie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'Ani przestawali na radzie mijej, ale gardzili wszelką karnością moją:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Przetoż będą używać owocu dróg swoich, a radami swemi nasyceni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Bo odwrócenie prostaków pozabija ich, a szczęście głupich wytraci ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Ale kto mię słucha, bezpiecznie mieszkać będzie, a będzie wolny od strachu złych rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Synu mój! jeźli przyjmiesz słowa moje, a przykazanie moje zachowasz u siebie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'Nadstawiszli mądrości ucha twego, i nakłoniszli serca twego do roztropności;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'Owszem, jeźli na rozum zawołasz, a roztropności wezwieszli głosem swoim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'Jeźli jej szukać będziesz jako srebra, a jako skarbów skrytych pilnie szukać będziesz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'Tedy zrozumiesz bojaźń Pańską, a znajomość Bożą znajdziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Albowiem Pan daje mądrość, z ust jego pochodzi umiejętność i roztropność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'On zachowuje uprzejmym prawdziwą mądrość; on jest tarczą chodzącym w szczerości,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'Aby strzegli ścieżek sądu; on drogi świętych swoich strzeże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Tedy wyrozumiesz sprawiedliwość, i sąd, i prawość, i wszelką ścieszkę dobrą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Gdy wnijdzie mądrośu w serce twoje, a umiejętność duszy twojej wdzięczna będzie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'Tedy cię ostrożność strzedz będzie, a opatrzność zachowa cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'Wyrywając cię od drogi złej, i od człowieka mówiącego przewrotności;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'Od tych, którzy opuszczają ścieszki proste, udawając się drogami ciemnemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'Którzy się radują, gdy czynią złe, a weselą się w złośliwych przewrotnościach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'Których ścieszki są krzywe, a sami są przewrotnymi na drogach swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'Wyrywając cię od niewiasty postronnej i obcej, która pochlebia łagodnemi słowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'Która opuszcza wodza młodości swojej, a przymierza Boga swojego zapomina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Bo się nachyla ku śmierci dom jej, a do umarłych ścieszki jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'Wszyscy, którzy do niej wchodzą, nie wracają się, ani trafiają na ścieszkę żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'A przetoż będziesz chodził drogą dobrych, a ścieżek sprawiedliwych będziesz przestrzegał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Albowiem cnotliwi będą mieszkali na ziemi, a szczerzy trwać będą na niej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Ale niepobożni z ziemi wykorzenieni będą, a przewrotni będą z niej wygładzeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Synu mój! nie zapominaj zakonu mego, a przykazań moich niech strzeże serce twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'Boć długości dni i lat żywota, i pokoju przyczynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Miłosierdzie i prawda niech cię nie opuszczają; uwiąż je u szyi twojej, napisz je na tablicy serca twojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'Tedy znajdziesz łaskę i rozum dobry przed oczyma Bożemi i ludzkiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Ufaj w Panu ze wszystkiego serca twego, a na rozumie twoim nie spolegaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'We wszystkich drogach twoich znaj go, a on prostować będzie ścieszki twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Nie bądź mądrym sam u siebie; ale się bój Pana, a odstąp od złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'To będzie zdrowiem żywotowi twemu, a odwilżeniem kościom twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Czcij Pana z majętności twojej, i z pierwiastek wszystkich dochodów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'A gumna twoje napełnione będą obfitością, i od wina nowego prasy twoje rozpadać się będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Synu mój! karania Pańskiego nie odrzucaj, i nie uprzykrzaj sobie ćwiczenia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'Bo kogo Pan miłuje, tego karze, a to jako ojciec, który się w synu kocha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Błogosławiony człowiek, który znajduje mądrość, i człowiek, który dostanie roztropności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Bo lepiej nią kupczyć, niżeli kupczyć srebrem: owszem pożyteczniejszy nad złoto dochód jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Droższa jest nad perły, a wszystkie najmilsze rzeczy twoje nie zrównają się z nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Przedłużenie dni w prawicy jej, a w lewicy jej bogactwa i zacność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Drogi jej rozkoszne, i wszystkie ścieszki jej spokojne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Drzewem żywota jest tym, którzyby się jej chwycili; a którzy się jej trzymają, są błogosławionymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Pan mądrością ugruntował ziemię, a roztropnością umocnił niebiosa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Umiejętnością jego rozstąpiły się przepaści, a obłoki rosą kropią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Synu mój! niech to nie odstępuje od oczów twych: strzeż prawdziwej mądrości i roztropności;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'I będą żywotem duszy twojej, a ozdobą szyi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Tedy będziesz chodził bezpiecznie droga twoją, a noga twoja nie potknie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Jeźli się układziesz, nie będziesz się lękał; a gdy się uspokoisz, wdzięczny będzie sen twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Nie ulękniesz się strachu nagłego, ani spustoszenia bezbożników, gdy przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Albowiem Pan będzie ufaniem twojem, a nogi twojej będzie strzegł od samołówki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Nie zbraniaj się dobrze czynić potrzebującemu, gdy cię na to stanie, abyś dobrze czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Nie mów bliźniemu twemu: Idź, a wróć się, a jutroć dam; gdyż to masz u siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Nie knuj złego przeciwko bliźniemu twemu, gdyż on z tobą dowiernie mieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Nie wadź się z człowiekiem bez przyczyny, jeźliżeć nic złego nie wyrządził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Nie zajrzyj mężowi gwałt czyniącemu, a nie obieraj żadnej drogi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Albowiem przewrotny jest obrzydliwością przed Panem; ale z szczerymi tajemnica jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Przeklęstwo Pańskie jest w domu niezbożnika; ale przybytkowi sprawiedliwych błogosławi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Ponieważ on szydzi z pośmiewców, ale pokornym łaskę daje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Mądrzy dziedzicznie sławę osiędą, ale głupi odniosą zelżywość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Słuchajcie synowie! ćwiczenia ojcowskiego, a pilnujcie, abyście umieli roztropność;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Albowiem wam naukę dobrą daję; zakonu mego nie opuszczajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Gdybym był młodziuchnym synem u ojca mego, i jedynakiem u matki mojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'On mię uczył, powiadając mi: Niech się chwyci powieści moich serce twoje, strzeż przytkazań moich, a będziesz żył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Nabywaj mądrości, nabywaj roztropności; nie zapominaj, ani się uchylaj od powieści ust moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Nie opuszczaj jej, a będzie cię strzegła; rozmiłuj się jej, a zachowa cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Początkiem wszystkiego jest mądrość, nabywajże mądrości, a za wzystkę majętność twoję nabywaj roztropności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Wywyższaj ją, a wywyższy cię, rozsławi cię, gdy ją przyjmiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Przyda głowie twojej wdzięczności, koroną ozdoby obdarzy cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Słuchaj, synu mój! a przyjmij powieści moje, a rozmnożąć lata żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Drogi mądrości nauczam cię; po ścieszkach prostych wiodę cię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Któremi gdy pójdziesz, nie będzie ściśniony chód twój; a jeźli pobieżysz, nie potkniesz sií.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Przyjmij őwiczenie, nie puszczaj się go, strzeż go; albowiem ono jest żywotem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Ścieszką niepobożnych nie chodź, a nie udawaj się drogą złośliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Opuść ją, nie chodź po niej; uchyl się od niej, a omiń ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Boć oni nie zasną, aż co złego zbroją; ani się uspokoją, aż kogo do upadku przywiodą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Albowiem jedzą chleb niezbożności, a wino drapiestwa piją,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Ale ścieszka sprawiedliwych jako światłość jasna, która im dalej tem bardziej świeci, aż do dnia doskonałego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Droga zaś niepobożnych jest jako ciemność; nie wiedzą, o co sií otrącić mogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Synu mój! słów moich pilnuj; ku powieściom moim nakłoń ucha twojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Niech nie odchodzą od oczów twoich, zachowaj je w pośród serca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Albowiem żywotem są tym, którzy je znajdują, a wszystkiemu ciału ich lekarstwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Nad wszystko, czego ludzie strzegą, strzeż serca twego; bo z niego żywot pochodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Oddal od siebie przewrotność ust, a złośliwe wargi oddal od siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Oczy twoje niechaj na dobre rzeczy patrzą, a powieki twoje niech drogę przed tobą prostują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Umiarkuj ścieżkę nóg twoich, aby wszystkie drogi twoje pewne były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Nie uchylaj się na prawo ani na lewo; owszem, odwróć nogę twoję od złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Synu mój! bądź pilen mądrości mojej, a ku mojej roztropności nakłoń ucha twego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'Abyś strzegł ostrożności, a umiejętność aby wargi twoje zachowała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Bo choć niewiasty obcej wargi miodem opływają, a gładsze niż oliwa usta jej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Ale ostatnie rzeczy jej gorzkie jak piołun, a ostre jako miecz na obie strony ostry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Nogi jej zstępują do śmierci, a do piekła chód jej prowadzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Jeźlibyś zważyć chciał ścieszkę żywota jej, nie pewne są drogi jej, nie poznasz ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Przetoż teraz, synowie! słuchajcie mię, a nie odstępujcie od powieści ust moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Oddal od niej drogę twoję, a nie przybliżaj się ku drzwiom domu jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'Byś snać nie podał obcym sławy twojej, a lat twoich okrutnikowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'By się snać nie nasycili obcy siłą twoją, a prace twoje nie zostały w domu cudzym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'I narzekałbyś w ostateczne czasy twoje, gdybyś zniszczył czerstwość twoję i ciało twoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'I rzekłbyś: O jakożem miał ćwiczenie w nienawiści, a strofowaniem gardziło serce moje!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Nie słuchałem głosu ćwiczących mię, a tym, którzy mię uczyli, nie nakłaniałem ucha mego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Maluczkom nie przyszedł we wszystko nieszczęście, w pośród zebrania i zgromadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Pij wodę ze zdroju twego, a wody płynące ze źródła twego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Niech się precz rozchodzą źródła twoje, a po ulicach strumienie wód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Miej je sam dla siebie, a nie obcy z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Niech nie będzie zdrój twój błogosławiony, a wesel się z żony młodości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'Niechżeć będzie jako łani wdzięczna, i sarna rozkodzna; niech cię nasycają piersi jej na każdy czas, w miłości jej kochaj się ustawicznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Bo przeczże się masz kochać w obcej, synu mój! i odpoczywać na łonie cudzej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Gdyż przed oczyma Pańskiemi są drogi człowiecze, a on wszystkie ścieszki jego waży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Nieprawości własne pojmają niezbożnika, a w powrozach grzechu swego uwikle się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Onci umrze, przeto, że nie przyjmował ćwiczenia, a dla wielkości głupstwa swego będzie błądził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Synu mój! jeźlibyś ręczył za przyjaciela twego, a dałbyś obcemu rękę twoję:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'Usidliłeś się słowy ust twoich, pojmanyś mowami ust twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Przetoż uczyń tak, synu mój! a wyzwól się, gdyżeś wpadł w rękę przyjaciela twego; idźże, upokórz się, a nalegaj na przyjaciela twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Nie dawaj snu oczom twoim, ani drzemania powiekom twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'Wyrwij się jako łani z rąk myśliwca i jako ptak z ręki ptasznika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Idź do mrówki, leniwcze! obacz drogi jej, a nabądź mądrości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'Która, choć nie ma wodza, ani przełożonego, ani pana,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'Przecież w lecie gotuje pokarm swój, a zgromadza w żniwa żywność swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Leniwcze! dokądże leżeć będziesz? kiedyż wstaniesz ze snu swego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Trochę się prześpisz, trochę podrzemiesz, trochę złożysz ręce, abyś odpoczywał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'A wtem ubóstwo twoje przyjdzie jako podróżny, a niedostatek twój, jako mąż zbrojny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Człowiek niepobożny, mąż złośliwy chodzi w przewrotności ust;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'Mruga oczyma swemi, mówi nogami swemi, ukazuje palcami swemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Przewrotności są w sercu jego, myśli złe na każdy czas, a zwady rozsiewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Przetoż prędko przyjdzie upadek jego; nagle skruszony będzie bez uleczenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Sześć jest rzeczy, których nienawidzi Pan, a siódma jest obrzydliwością duszy jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'Oczów wyniosłych, języka kłamliwego, i rąk wylewających krew niewinną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'Serca, które knuje myśli złe; nóg, które się kwapią bieżeć ku złemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'Świadka fałszywego, który mówi kłamstwo, i tego, który sieje rosterki między braćmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Strzeżże, synu mój! przykazania ojca twego, a nie opuszczaj nauki matki twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'Wiążże je zawżdy u serca twego, a wieszaj je u szyi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Gdziekolwiek pójdziesz, poprowadzi cię; gdy, zaśniesz strzedz cię będzie, a gdy się ocucisz, rozmawiać z tobą będzie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, '(Bo przykazanie jest pochodnią, nauka światłością, a drogą żywota są karności ćwiczenia.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'Aby cię strzegły od niewiasty złej, i od łagodnego języka niewiasty obcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Nie pożądaj piękności jej w sercu twojem, a niech cię nie łowi powiekami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Albowiem dla niewiasty wszetecznej zubożeje człowiek aż do kęsa chleba; owszem żona cudzołożna drogą duszę łowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Izaż może kto brać ogień do zanadrzy swoich, aby szaty jego nie zgorzały?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Izaż może kto chodzić po rozpalonym węglu, aby się nogi jego nie poparzyły?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Tak kto wchodzi do żony bliźniego swego, nie będzie bez winy, ktokolwiek się jej dotknie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Nie kładą hańby na złodzieja, jeżliż co ukradnie, chcąc nasycić duszę swoję, będąc głodnym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'Ale gdy go zastaną, nagradza siedmiorako, albo wszystkę majętność domu swego daje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'Lecz cudzołożący z niewiastą głupi jest, a kto chce zatracić duszę swoję, ten to czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Karanie i zelżywość odniesie, a hańba jego nie będzie zgładzona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Bo zawisna miłość jest zapalczywością męża, a nie sfolguje w dzień pomsty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Nie będzie miał względu na żaden okup, ani przyjmie, chociażby mu najwięcej darów dawano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Synu mój! strzeż słów moich, a przykazanie moje chowaj u siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Strzeż przykazań moich, a żyć będziesz; a nauki mojej, jako źrenicy oczów swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Uwiąż je na palcach twoich,napisz je na tablicy serca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Mów mądrości: Siostraś ty moja, a roztropność przyjaciółką nazywaj,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'Aby cię strzegły od żony cudzej, i od obcej, która mówi łagodne słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Bom oknem domu swego przez kratę moję wyglądał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'I widziałem między prostakami, obaczyłem między synami młodzieńca głupiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'Który szedł ulicą przy rogu jej, drogą postępując ku domowi jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'Ze zmierzkiem pod wieczór, w ciemności nocnej, i w mroku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'A oto niewiasta spotkała go, w ubiorze wszetecznicy, chytrego serca,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Świegotliwa i nie ukrócona, a w domu własnym nie mogły się ostać nogi jej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'Raz na dworzu, raz na ulicach i po wszystkich kątach zasadzki czyniąca;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'I uchwyciła go, i pocałowała go, a złożywszy wstyd z twarzy swojej, rzekła mu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Ofiary spokojne są u mnie; dzisiajm oddała śluby moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Przetożem wyszła przeciw tobie, abym pilnie szukała twarzy twojej, i znalazłam cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'Obiłam kobiercami łoże moje, ozdobione rzezaniem i prześcieradłami egipskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'Potrząsnęłam pokój swój myrrą, aloesem, i cynamonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Pójdźże, opójmy się miłością aż do poranku, ucieszmy się miłością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Boć męża mego w domu niemasz; pojechał w drogę daleką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'Worek pieniędzy wziął z sobą; dnia pewnego wróci się do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'I nakłoniła go wielą słów swoich, a łagodnością warg swoich zniewoliła go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'Wnet poszedł za nią, jako wół, gdy go na rzeź wiodą, a jako głupi do pęta, którem karany bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'I przebiła strzałą wątrobę jego; kwapił się jako ptak do sidła, nie wiedząc, iż je zgotowano na duszę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Przetoż teraz, synowie! słuchajcie mię, a bądźcie pilni powieści ust moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Niechaj się nie uchyla za drogami jej serce twoje, ani się tułaj po ścieszkach jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Albowiem wielu zraniwszy poraziła, i mocarze wszyscy pozabijani są od niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Dom jej jest jako drogi piekielne, wiodące do gmachów śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Izali mądrość nie woła, i roztropność nie wydaje głosu swego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Na wierzchu wysokich miejsc, przy drodze i na rozstaniu dróg stoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'U bram, kędy się chodzi do miasta, i w wejściu u drzwi woła, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Na was wołam, o mężowie! a głos mój obracam do synów ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Zrozumijcie prostacy ostrożność, a głupi zrozumijcie sercem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Słuchajcie; bo o wielkich rzeczach będę mówił, a otworzenie warg moich opowie szczerość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Zaisteć prawdę mówią usta moje, a niezbożność obrzydliwością jest wargom moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Sprawiedliwe są wszystkie słowa ust moich; nie masz w nich nic nieprawego ani przewrotnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Wszystkie są prawe rozumnemu, a uprzejme tym, którzy znajdują umiejętność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Przyjmijcież ćwiczenie moje, a nie srebro, a umiejętność raczej, niż złoto wyborne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Albowiem lepsza jest mądrość niż perły, także wszystkie pożądane rzeczy nie porównają z nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Ja mądrość mieszkam z roztropnością,i umiejętność ostrożności wynajduję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Bojaźń Pańska jest, mieć w nienawiści złe. Ja nienawidzę pychy, wysokomyślności, i drogi złej, i ust przewrotnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Przy mnie jest rada, i prawdziwa mądrość; jam jest roztropność, a moc jest moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Przez mię królowie królują, i książęta stanowią sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Przez mię książęta panują, i wielmożnymi są wszyscy sędziowie ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Ja miłuję tych, którzy mię miłują; a którzy mię szukają rano, znajdują mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Bogactwo i sława przy mnie jest; majętność trwała i sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Lepszy jest owoc mój, niż złoto, i niż najkosztowniejsze złoto, a dochody moje lepsze, niż srebro wyborne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Prowadzę ścieszką sprawiedliwości, pośrodkiem ścieżek sądu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'Abym tym, którzy mię miłują, dała w dziedzictwo majętność wieczną, i skarby ich napełniła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Pan mię miał przy początku drogi swej, przed sprawami swemi, przed wszystkiemi czasy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Przed wieki jestem zrządzona, przed początkiem; pierwej niż była ziemia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Gdy jeszcze nie było przepaści, spłodzonam jest, gdy jeszcze nie było źródeł opływających wodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'Pierwej niż góry założone były, niż były pagórki, spłodzonam jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'Jeszcze był nie uczynił ziemi, i równin, ani początku prochu okręgu ziemskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Gdy gotował niebiosa, tamem była; gdy rozmierzał okrągłość nad przepaściami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'Gdy utwierdzał obłoki w górze, i umacniał źródła przepaści;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'Gdy zakładał morzu granice jego, i wodom, aby nie przestępowały rozkazania jego; gdy rozmierzał grunty ziemi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'Tedym była u niego jako wychowaniec, i byłam uciechą jego na każdy dzień, grając przed nim na każdy czas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'Gram na okręgu ziemi jego, a rozkoszy moje, mieszkać z synami ludzkimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Słuchajcież mię tedy teraz, synowie! albowiem błogosławieni, którzy strzegą dróg moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Słuchajcie ćwiczenia, nabądźcie rozumu, a nie cofajcie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Błogosławiony człowiek, który mię słucha, czując u wrót moich na każdy dzień, a strzegąc podwoi drzwi moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Bo kto mię znajduje, znajduje żywot, a otrzymuje łaskę od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Ale kto grzeszy przeciwko mnie, krzywdę czyni duszy swojej; wszyscy, którzy mię nienawidzą, miłują śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Mądrość zbudowała dom swój, i wyciosała siedm słupów swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'Pobiła bydło swoje, roztworzyła wino swoje, i stół swój przygotowała;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'A rozesłała dzieweczki swoje, woła na wierzchach najwyższych miejsc w mieście, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, 'Ktokolwiek jest prostakiem, wstąp sam; a do głupich mówi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, 'Pójdźcie, jedzcie chleb mój, i pijcie wino, którem roztworzyła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Opuśćcie prostotę, a będziecie żyli, a chodźcie drogą roztropności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Kto strofuje naśmiewcę, odnosi hańbę; a kto strofuje niezbożnika, odnosi zelżywość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Nie strofuj naśmiewcy, aby cię nie miał w nienawiści; strofuj mądrego, a będzie cię miłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Uczyń to mądremu, a mędrszym będzie; naucz sprawiedliwego, a będzie umiejętniejszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Początek mądrości jest bojaźń Pańska, a umiejętność świętych jest rozum.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Bo przez mię rozmnożą się dni twoje, i przedłużą się lata żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Będzieszli mądrym, sobie będziesz mądrym; a jeźli naśmiewcą, ty sam szkodę odniesiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Niewiasta głupia świegotliwa jest, prostaczka, i nic nieumiejąca;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'A siedzi u drzwi domu swego na stołku, na miejscach wysokich w mieście,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'Aby wołała na idących drogą, którzy prosto idą ścieszkami swemi, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, 'Ktokolwiek jest prostakiem, wstąp sam; a do głupiego mówi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, 'Wody kradzione słodsze są, a chleb pokątny smaczniejszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Ale prostak nie wie, że tam są umarli, a ci, których wezwała, są w głębokościach grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Syn mądry rozwesela ojca: ale syn głupi smutkiem jest matki swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Nie pomogą skarby niezbożności; ale sprawiedliwość wyrywa od śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Nie dopuści Pan łaknąć duszy sprawiedliwego; ale majętność niezbożników rozproszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Do nędzy przywodzi ręka zdradliwa; ale ręka pracowita ubogaca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Kto zbiera w lecie, jest syn roztropny; kto dosypia we żniwa, jest syn pohańbienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Błogosławieństwo jest nad głową sprawiedliwego; ale usta bezbożnych pokrywają nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Błogosławiona jest pamiątka sprawiedliwego; ale imię niezbożnych śmierdzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Mądre serce przyjmuje przykazanie; ale głupi od warg swoich upadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Kto chodzi w szczerości, chodzi bezpiecznie; ale kto jest przewrotnym w drogach swoich, wyjawion będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'Kto mruga okiem, przynosi frasunek, ale głupi od warg swoich upadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Usta sprawiedliwego są źródło żywota; ale usta niezbożników pokrywają nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Nienawiść wzbudza swary; ale miłość wszystkie przestępstwa pokrywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'W wargach roztropnego znajduje się mądrość; ale kij na grzbiecie szalonego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Mądrzy tają umiejętność; ale usta głupiego bliskie upadku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Majętność bogatego jest miastem jego mocnem; ale nędza jest ubogich zniszczeniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Praca sprawiedliwego jest ku żywotowi; ale dochód niepobożnych jest ku grzechowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Ścieszką żywota idzie, kto przyjmuje karność; ale kto gardzi strofowaniem, w błąd się zawodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Kto pokrywa nienawiść wargami kłamliwemi, i kto rozgłasza hańbę, głupi jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Wielomowność nie bywa bez grzechu; ale kto powściąga wargi swoje, ostrożny jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Srebro wyborne jest język sprawiedliwego; ale serce niezbożnych za nic nie stoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Wargi sprawiedliwego wiele ich żywią; ale głupi dla głupstwa umierają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Błogosławieństwo Pańskie ubogaca, a nie przynosi z sobą utrapienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Za śmiech sobie ma głupi, popełnić niecnotę, ale mąż roztropny dzierży się mądrości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Czego się boi niezbożnik, to nań przychodzi; ale czego żądają sprawiedliwi, Bóg im daje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Jako przemija wicher, tak się niepobożni nie ostoją; ale sprawiedliwy ma grunt wieczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Jako ocet zębom, i jako dym oczom, tak jest leniwy tym, którzy go posyłają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Bojaźń Pańska dni przyczynia; ale lata niezbożnego ukrócone bywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Oczekiwanie sprawiedliwych jest wesele, ale nadzieja niezbożnych zginie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Droga Pańska jest mocą szczeremu; ale strachem tym, którzy broją złości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Sprawiedliwy się na wieki nie poruszy; ale niezbożnicy nie będą mieszkali na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Usta sprawiedliwego rozmnażają mądrość; ale język przewrotny będzie wycięty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Wargi sprawiedliwego znają, co się Bogu podoba; ale usta niepobożnych są przewrotne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Waga fałszywa obrzydliwością jest Panu; ale gwichty sprawiedliwe podobają mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Za pychą przychodzi hańba; ale przy pokornych jest mądrość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Szczerość ludzi cnotliwych prowadzi ich; ale przewrotność przestępców potraci ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Niepomogą bogactwa w dzień gniewu; ale sprawiedliwość wybawia od śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Sprawiedliwość uprzejmego sprawuje drogę jego; lecz bezbożny dla bezbożności swojej upada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Sprawiedliwość uprzejmych wybawia ich: ale przewrotni w złościach pojmani bywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Gdy umiera człowiek niepobożny, ginie nadzieja jego, a oczekiwanie mocarzy niszczeje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Sprawiedliwy z ucisku wybawiony bywa; ale niepobożny przychodzi na miejsce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Obłudnik usty kazi przyjaciela swego; ale sprawiedliwi umiejętnością wybawieni bywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'Z szczęścia sprawiedliwych miasto się weseli; a gdy giną niezbożni, bywa radość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Dla błogosławieństwa sprawiedliwych bywa wywyższone miasto; ale dla ust niepobożnych bywa wywrócone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Głupi gardzi bliźnim swym; ale mąż roztropny milczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Obmówca obchodząc objawia tajemnice; ale kto jest wiernego serca, tai zwierzonej rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Gdzie niemasz dostatecznej rady, lud upada; ale gdzie wiele radców, tam jest wybawienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Bardzo sobie szkodzi, kto za obcego ręczy; ale kto się chroni rękojemstwa, bezpieczen jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Niewiasta uczciwa dostępuje sławy, a mocarze mają bogactwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Człowiek uczynny dobrze czyni duszy swej; ale okrutnik trapi ciało swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Niezbożnik czyni dzieło omylne; ale kto sieje sprawiedliwość, ma zapłatę trwałą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Jako sprawiedliwość jest ku żywotowi, tak kto naśladuje złości, bliski jest śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Obrzydliwością są Panu przewrotni sercem; ale mu się podobają, którzy żyją bez zmazy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Złośnik, choć sobie innych na pomoc weźmie, pomsty nie ujdzie; ale nasienie sprawiedliwych zachowane będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Niewiasta piękna a głupia jest jako kolce złote w pysku u świni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Żądza sprawiedliwych jest zawżdy ku dobremu; ale oczekiwanie niepobożnych, popędliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Nie jeden udziela szczodrze, a wżdy mu przybywa; a drugi skąpi więcej niż trzeba, a wżdy ubożeje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Człowiek szczodrobliwy bywa bogatszy; a kto nasyca, sam też będzie nasycony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Kto zatrzymuje zboże, tego lud przeklina; ale błogosławieństwo nad głową tego, który je sprzedaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Kto pilnie szuka dobrego, nabywa przyjaźni; ale kto szuka złego, przyjdzie nań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Kto ufa w bogactwach swych, ten upadnie; ale sprawiedliwi jako latorośl zielenieć się będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Kto czyni zamięszanie w domu swoim, odziedziczy wiatr, a głupi musi służyć mądremu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Owoc sprawiedliwego jest drzewo żywota; a kto naucza ludzi, mądry jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Oto jeźli się sprawiedliwemu na ziemi nagroda staje, tedy daleko więcej niezbożnemu i grzesznikowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Kto miłuje ćwiczenie, miłuje umiejętność; a kto ma w nienawiści karność, głupim jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Dobry odniesie łaskę od Pana; ale męża który złe myśli, Bóg potępi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Nie zmocni się człowiek z niezbożności; ale korzeń sprawiedliwych nie będzie poruszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Żona stateczna koroną jest męża swego; ale która go do hańby przywodzi, jest jako zgniłość w kościach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Myśli sprawiedliwych są prawe: ale rady niepobożnych zdradliwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Słowa niepobożnych czyhają na krew; ale usta sprawiedliwych wybawiają ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Niepobożni podwróceni bywają, tak, że ich niestaje; ale dom sprawiedliwych zostaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Z rozumu swego mąż chwalony bywa; ale kto jest przewrotnego serca, wzgardzony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Lepszy jest człowiek podły, który ma sługę, niżeli chlubny, któremu nie staje chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Sprawiedliwy ma na pieczy żywot bydlątka swego; ale serce niepobożnych okrutne jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Kto sprawuje ziemię swoję, chlebem nasycony bywa; ale kto naśladuje próżnujących, głupi jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Niepobożny pragnie obrony przeciw nieszczęściu; ale korzeń sprawiedliwych daje ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'W przestępstwie warg upląta się złośnik; ale sprawiedliwy z ucisku wychodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Z owocu ust każdy będzie nasycony dobrem, a nagrodę spraw rąk jego Bóg mu odda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Droga głupiego zda się prosta przed oczyma jego; ale kto słucha rady, mądrym jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Gniew głupiego zaraz poznany bywa; ale ostrożny pokrywa hańbę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Kto mówi prawdę, opowiada sprawiedliwość; ale świadek kłamliwy mówi zdradę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Znajdzie takowego, co mówi słowa jako miecz przerażające; ale język mądrych jest lekarstwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Wargi prawdomówne utwierdzone będą na wieki; ale króciuchno trwa język kłamliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Zdrada jest w sercu tych, którzy złe myślą; ale którzy radzą do pokoju, mają wesele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Nie spotka sprawiedliwego żadne nieszczęście; ale niezbożnicy pełni będą złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Obrzydliwością są Panu wargi kłamliwe; ale czyniący prawdę podobają mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Człowiek ostrożny tai umiejętność; ale serce głupich wywołuje głupstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Ręka pracowitych będzie panowała; ale zdradliwa będzie dań dawała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Frasunek w sercu człowieczem poniża je; ale powieść dobra uwesela je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Zacniejszy jest nad bliźniego swego sprawiedliwy; ale droga niezbożnych zawodzi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Nie upiecze chytry obłowu swojego; ale człowiek pilny majętności kosztownych nabędzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Na ścieszce sprawiedliwości żywot, a na drodze ścieszki jej niemasz śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Syn mądry przyjmuje ćwiczenie ojcowskie, ale naśmiewca nie słucha strofowania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Każdy będzie pożywał dobrego z owocu ust swoich; ale dusza przewrotnych krzywdy pożywać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Kto strzeże ust swych, strzeże duszy swojej; kto lekkomyślnie otwiera wargi swe, będzie starty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Dusza leniwego żąda, a nic nie ma; ale dusza pracowitych zbogaci się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Słowa kłamliwego nienawidzi sprawiedliwy; ale niezbożny staje się obrzydliwym i shańbionym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Sprawiedliwość strzeże tego, który żyje bez zmazy; ale niezbożność podwraca grzesznika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Znajduje się taki co się czyni bogatym, a nie ma nic; i taki, co się czyni ubogim, choć ma wiele bogactw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Okup żywota człowieczego jest bogactwo jego; ale ubogi nie słucha łajania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Światłość sprawiedliwych jasna: ale pochodnia bezbożnych zgaśnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Samą tylko pychą człowiek zwady wszczyna, ale przy tych, co radę przyjmują, jest mądrość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Bogactwa źle nabyte umniejszą się; ale kto je zgromadza ręką swą, przyczynia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Nadzieja długa wątli serce; ale żądość wypełniona jest drzewem żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Kto gardzi słowem Bożem, sam sobie szkodzi; ale kto się boi przykazania jego, odniesie nagrodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Nauka mądrego jest źródłem żywota ku ochronieniu się sideł śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Rozum dobry daje łaskę; ale droga przewrotnych jest przykra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Każdy ostrożny umiejętnie sobie poczyna; ale głupi rozpościera głupstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Poseł niezbożny upada we złe; ale poseł wierny jest lekarstwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Ubóstwo i zelżywość przyjdzie na tego, który się wyłamuje z karności; ale kto przestrzega upominania, wysławiony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Żądność wypełniona słodka jest duszy; ale odstąpić od złego, głupim jest obrzydliwością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Kto chodzi z mądrymi, mądrym będzie; ale kto towarzyszy z głupimi, startym będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Nieszczęście grzeszników ściga; ale sprawiedliwym Bóg dobrem nagrodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Dobry człowiek zostawia dziedzictwo synom synów swoich; ale majętność grzesznika sprawiedliwemu zachowana bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Obfita żywność na roli ubogich, a drugi ginie przez nieroztropność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Kto zawściąga rózgi swej, ma w nienawiści syna swego; ale kto go miłuje, wczas go karze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Sprawiedliwy je, i nasyca duszę swoję; ale żołądek niezbożnych niedostatek cierpi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Mądra niewiasta buduje dom swój; ale go głupia rękami swemi rozwala.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Kto chodzi w szczerości swojej, boi się Pana; ale przewrotny w drogach swoich gardzi nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'W ustach głupiego jest rózga hardości; ale wargi mądrych strzegą ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Gdzie niemasz wołów, żłób jest próżny; ale siłą wołów mnoży się obfitość zboża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Świadek prawdziwy nie kłamie; ale świadek fałszywy mówi kłamstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Naśmiewca szuka mądrości, a nie znajduje; ale umiejętność roztropnemu jest snadna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Idź precz od oblicza męża głupiego, gdyż nie znajdziesz przy nim warg umiejętności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Mądrość ostrożnego jest rozumieć drogę swoję, ale głupstwo głupich jest zdrada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Każdy głupi nakrywa grzech, a między uprzejmymi mieszka przyjaźń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Serce każdego uznaje gorzkość duszy swojej, a do wesela jego nie przymięsza się obcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Dom niezbożnych zgładzony będzie; ale przybytek cnotliwych zakwitnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Zda się pod czas droga być prosta człowiekowi; wszakże dokończenie jej jest drogą na śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Także i w śmiechu boleje serce, a koniec wesela bywa smutek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Drogami swemi nasyci się człowiek przewrotnego serca; ale się go chroni mąż dobry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Prostak wierzy każdemu słowu; ale ostrożny zrozumiewa postępki swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Mądry się boi, i odstępuje od złego; ale głupi dociera, i śmiałym jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Porywczy człowiek dopuszcza się głupstwa, a mąż złych myśli w nienawiści bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Głupstwo prostacy dziedzicznie trzymają; ale ostrożni bywają koronowani umiejętnością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'źli się kłaniają przed dobrymi, a niepobożni stoją u drzwi sprawiedliwego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Ubogi bywa i u przyjaciela swego w nienawiści; ale wiele jest tych, którzy bogatego miłują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Bliźnim swym grzesznik pogardza; ale kto ma litość nad ubogimi, błogosławionym jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Izali nie błądzą, którzy wymyślają złe? a miłosierdzie i prawda należy tym, którzy wymyślają dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'W każdej pracy bywa pożytek; ale gołe słowo warg tylko do nędzy służy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Bogactwo mądrych jest koroną ich; ale głupstwo głupich zostaje głupstwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Świadek prawdziwy wyzwala duszę; ale fałszywy kłamstwo mówi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Kto się boi Pana, ma ufanie mocne; a synowie jego ucieczkę mieć będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Bojaźń Pańska jest źródło żywota ku uchronieniu się sideł śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'W mnóstwie ludu jest zacność królewska; ale w trosze ludu zniszczenie hetmana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Nierychły do gniewu jest bogaty w rozum; ale porywczy pokazuje głupstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Serce zdrowe jest żywotem ciała; ale zazdrość jest zgniłością w kościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Kto ciemięży ubogiego, uwłacza stworzycielowi jego; ale go czci, kto ma litość nad ubogim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'Dla złości swojej wygnany bywa niepobożny; ale sprawiedliwy nadzieję ma i przy śmierci swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'W sercu mądrego odpoczywa mądrość, ale wnet poznać, co jest w sercu głupich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Sprawiedliwość wywyższa naród; ale grzech jest ku pohańbieniu narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Król łaskaw bywa na sługę roztropnego; ale się gniewa na tego, który mu hańbę czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Odpowiedź łagodna uśmierza gniew; ale słowa przykre wzruszają popędliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Język mądrych zdobi umiejętność; ale usta głupich wywierają głupstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Na każdem miejscu oczy Pańskie upatrują złe i dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Zdrowy język jest drzewo żywota; ale przewrotność z niego jest jako zdruzgotanie od wiatru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Głupi gardzi karaniem ojca swego; ale kto przyjmuje napomnienie, stanie się ostrożnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'W domu sprawiedliwego jest dostatek wielki; ale w dochodach niepobożnego zamięszanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Wargi mądrych sieją umiejętność; ale serce głupich nie tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Ofiara niepobożnych jest obrzydliwością Panu; ale modlitwa szczerych podoba mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Obrzydliwością Panu jest droga bezbożnego, ale tego, co idzie za sprawiedliwością, miłuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Karanie srogie należy temu, co opuszcza drogę; a kto ma w nienawiści karność, umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Piekło i zatracenie są przed Panem; jakoż daleko więcej serca synów ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Naśmiewca nie miłuje tego, który go karze, ani do mądrych przychodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Serce wesołe uwesela twarz; ale dla żałości serca duch strapiony bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Serce rozumne szuka umiejętności; ale usta głupich karmią się głupstwem');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Wszystkie dni ubogiego są złe; ale kto jest wesołego serca, ma gody ustawiczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Lepsza jest trocha w bojaźni Pańskiej, niżeli skarb wielki z kłopotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Lepszy jest pokarm z jarzyny, gdzie jest miłość, niżeli z karmnego wołu, gdzie jest nienawiść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Mąż gniewliwy wszczyna swary; ale nierychły do gniewu uśmierza zwady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Droga leniwego jest jako płot cierniowy, ale ścieszka szczerych jest równa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Syn mądry uwesela ojca; ale głupi człowiek lekce waży matkę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Głupstwo jest weselem głupiemu, ale człowiek roztropny prostuje drogę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Gdzie niemasz rady, rozsypują się myśli; ale w mnóstwie radców ostoją się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Weseli się człowiek z odpowiedzi ust swoich: bo słowo według czasu wyrzeczone, o jako jest dobre!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Drogę żywota rozumny ma ku górze, aby się uchronił piekła głębokiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Pan wywróci dom pysznych; ale wdowy granicę utwierdzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Myśli złego są obrzydliwością Panu! ale powieści czystych są przyjemne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Kto chciwie naśladuje łakomstwa, zamięszanie czyni w domu swoim; ale kto ma w nienawiści dary, będzie żył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Serce sprawiedliwego przemyśliwa, co ma mówić; ale usta niepobożnych wywierają złe rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Dalekim jest Pan od niepobożnych; ale modlitwę sprawiedliwych wysłuchiwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Światłość oczów uwesela serce, a wieść dobra tuczy kości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Ucho, które słucha karności żywota, w pośrodku mądrych mieszkać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Kto uchodzi ćwiczenia, zaniedbywa duszy swojej; ale kto przyjmuje karanie, ma rozum.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Bojaźń Pańska jest ćwiczenie się w mądrości, a sławę uprzedza poniżenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Człowiek sporządza myśli serca swego; ale od Pana jest odpowiedź języka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Wszystkie drogi człowiecze zdadzą się być czyste przed oczyma jego; ale Pan jest, który waży serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Włóż na Pana sprawy twe, a będą utwierdzone zamysły twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Pan dla siebie samego wszystko sprawił, nawet i niezbożnika na dzień zły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Obrzydliwością jest Panu każdy wyniosłego serca; który choć sobie innych na pomoc weźmie, nie ujdzie pomsty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Miłosierdziem i prawdą oczyszczona bywa nieprawość, a w bojaźni Pańskiej odstępujemy od złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Gdy się podobają Panu drogi człowieka, i nieprzyjaciół jego do zgody z nim przywodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Lepsza jest trocha z sprawiedliwością, niż wiele dochodów niesprawiedliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Serce człowiecze rozrządza drogi swe; ale Pan sprawuje kroki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Sprawiedliwy rozsądek jest w wargach królewskich; w sądzie nie błądzą usta jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Waga i szale są ustawą Pańską, a wszystkie gwichty sprawiedliwe w worku są za sprawą jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Obrzydliwością jest królom czynić niezbożność; bo sprawiedliwością stolica umocniona bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Przyjemne są królom wargi sprawiedliwe, a szczerych w mowie miłują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Gniew królewski jest posłem śmierci; ale mąż mądry ubłaga go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'W jasności twarzy królewskiej jest żywot, a łaska jego jest jako obłok z deszczem późnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Daleko lepiej jest nabyć mądrości, niżeli złota najczystszego; a nabyć roztropności lepiej, niż srebra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Gościniec uprzejmych jest odstąpić od złego; strzeże duszy swej, kto strzeże drogi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Przed zginieniem przychodzi pycha, a przed upadkiem wyniosłość ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Lepiej jest być uniżonego ducha z pokornymi, niżeli dzielić korzyści z pysznymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Kto ma wzgląd na słowa, znajduje dobre; a kto ufa w Panu, błogosławiony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Kto jest mądrego serca, słynie rozumnym, a słodkość warg przydaje nauki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Zdrój żywota jest roztropność tym, którzy ją mają; ale umiejętność głupich jest głupstwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Serce mądrego roztropnie sprawuje usta swoje, a wargami swemi przydaje nauki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Powieści wdzięczne są jako plastr miodu, słodkością duszy, a lekarstwem kościom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Zda się podczas droga być prosta człowiekowi; wszakże dokończenie jej pewna droga na śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Człowiek pracowity pracuje sobie; bo go pobudzają usta jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Człowiek niezbożny wykopuje złe, a w wargach jego jako ogień pałający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Mąż przewrotny rozsiewa zwady, a klatecznik rozłącza przyjaciół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Mąż okrutny przewabia bliźniego swego, i wprowadza go na drogę niedobrą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Kto mruga oczyma swemi, zmyśla przewrotności; a kto rucha wargami swemi, broi złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Koroną chwały jest sędziwość; znajduje się na drodze sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Lepszy jest nierychły do gniewu, niżeli mocarz; a kto panuje sercu swemu, lepszy jest, niżeli ten, co dobył miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'Los na łono rzucają; ale od Pana jest wszystko rozrządzenie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Lepszy jest kęs suchego chleba a w pokoju, niżeli pełen dom nabitego bydła ze swarem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Sługa roztropny będzie panował nad synem, który jest ku hańbie; a między braćmi będzie dzielił dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Tygiel srebra a piec złota doświadcza; ale Pan serc dośwadcza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Zły pilnuje warg złośliwych, a kłamca słucha języka przewrotnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Kto się naśmiewa z ubogiego, uwłacza stworzycielowi jego; a kto się raduje z upadku czyjego, nie ujdzie pomsty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Korona starców są synowie synów ich, a ozdoba synów są ojcowie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Nie przystoi mowa poważna głupiemu, dopieroż księciu usta kłamliwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Jako kamień drogi, tak bywa dar wdzięczny temu, który go bierze; do czegokolwiek zmierzy, zdarzy mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Kto pokrywa przestępstwo, szuka łaski; ale kto wznawia rzeczy, rozłącza przyjaciół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Więcej waży gromienie u roztropnego, niżeli sto plag u głupiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Uporny tylko złego szuka, dla tego poseł okrutny będzie nań zesłany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Lepiej jest człowiekowi spotkać się z niedźwiedzicą osierociałą, niżeli z głupim w głupstwie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Kto oddaje złem za dobre, nie wynijdzie złe z domu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Kto zaczyna zwadę, jest jako ten, co przekopuje wodę; przetoż niż się zwada rozsili, zaniechaj go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Kto usprawiedliwia niezbożnego, a winnym czyni sprawiedliwego, oba jednako są obrzydliwością Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Cóż po dostatku w ręku głupiego, ponieważ do nabycia mądrości rozumu nie ma?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Wszelkiego czasu miłuje przyjaciel, a w ucisku stawia się jako brat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Człowiek głupi daje rękę, czyniąc rękojemstwo przed twarzą przyjaciela swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Kto miłuje zwadę, miłuje grzech; a kto wynosi usta swe, szuka upadku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Przewrotny w sercu nie znajduje dobrego; a kto jest przewrotnego języka, wpadnie we złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Kto spłodził głupiego, na smutek swój spłodził go, ani się rozweseli ojciec niemądrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Serce wesołe oczerstwia jako lekarstwo; ale duch sfrasowany wysusza kości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Niezbożny potajemnie dar bierze, aby podwrócił ścieszki sądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Na twarzy roztropnego znać mądrość; ale oczy głupiego aż na kraju ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'Syn głupi żałością jest ojcu swemu, a gorzkością rodzicielce swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Zaiste nie dobra, winować sprawiedliwego, albo żeby przełożeni kogo dla cnoty bić mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Kto zawściąga mowy swe, jest umiejętnym; drogiego ducha jest mąż rozumny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Gdy głupi milczy, za mądrego poczytany bywa; a który zatula wargi swoje, za rozumnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Człowiek swej myśli, szuka tego, co mu się podoba, a w każdą rzecz wtrąca się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Nie kocha się głupi w roztropności, ale w tem, co mu objawia serce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Gdy przychodzi niezbożny, przychodzi też wzgarda, a z mężem lekkomyślnym urąganie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Słowa ust męża mądrego są jako wody głębokie, a źródło mądrości jako potok wylewający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Nie dobra to, mieć wzgląd na osobę niezbożnego, aby był podwrócony sprawiedliwy w sądzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Wargi głupiego zmierzają do swaru, a usta jego do bitwy wyzywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Usta głupiego są upadkiem jego, a wargi jego sidłem duszy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Słowa obmówcy są jako słowa zranionych, a wszakże przenikają do wnętrzności żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Kto niedbały w sprawach swoich, bratem jest utratnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Imię Pańskie jest mocną wieżą; sprawiedliwy się do niej uciecze, a wywyższony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Majętność bogatego jest miastem jego mocnem, a jako mur wysoki w myśli jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Przed upadkiem podnosi się serce człowiecze, a sławę uprzedza poniżenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Kto odpowiada, pierwej niż wysłucha, głupstwo to jego i zelżywość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Duch męża znosi niemoc swoję; ale ducha utrapionego któż zniesie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Serce rozumne nabywa umiejętności, a ucho mądrych szuka jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Dar człowieczy plac mu czyni, i przed wielmożnych przywodzi go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Sprawiedliwym zda się ten, kto pierwszy w sprawie swojej; ale gdy przychodzi bliźni jego, dochodzi go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Los uśmierza zwady, i między możnymi rozsądek czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Brat krzywdą urażony trudniejszy nad miasto niedobyte, a swary są jako zawory u pałacu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Z owocu ust każdego nasycon bywa żywot jego; urodzajem warg swych będzie nasycony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Śmierć i żywot jest w mocy języka, a kto go miłuje, będzie jadł owoce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Kto znalazł żonę, znalazł rzecz dobrą, i dostąpił łaski od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Ubogi pokornie mówi; ale bogaty odpowiada surowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Człowiek, który ma przyjaciół, ma się obchodzić po przyjacielsku, ponieważ przyjaciel bywa przychylniejszy nad brata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Lepszy jest ubogi, który chodzi w uprzejmości swej, niżeli przewrotny w wargach swoich, który jest głupim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Zaiste duszy bez umiejętności nie dobrze, a kto jest prędkich nóg, potknie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Głupstwo człowiecze podwraca drogę jego, a przecie przeciwko Panu zapala się gniewem serce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Bogactwa przyczyniają wiele przyjaciół; ale ubogi od przyjaciela swego odłączony bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Fałszywy świadek nie będzie bez pomsty; a kto mówi kłamstwo, nie ujdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Wielu się ich uniża przed księciem, a każdy jest przyjacielem mężowi szczodremu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Wszyscy bracia ubogiego nienawidzą go; daleko więcej inni przyjaciele jego oddalają się od niego; woła za nimi, a niemasz ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Nabywa rozumu, kto miłuje duszę swoję, a strzeże roztropności, aby znalazł co dobrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Świadek fałszywy nie będzie bez pomsty; a kto mówi kłamstwo, zginie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Nie przystoi głupiemu rozkosz, ani słudze panować nad książętami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Rozum człowieczy zawściąga gniew jego, a ozdoba jego jest mijać przestępstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Zapalczywość królewska jest jako ryk lwięcia; ale łaska jego jest jako rosa na trawie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Syn głupi jest utrapieniem ojcu swemu, a żona swarliwa jest jako ustawiczne kapanie przez dach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Dom i majętność dziedzictwem przypada po rodzicach; ale żona roztropna jest od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Lenistwo przywodzi twardy sen, a dusza gnuśna będzie łaknęła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Kto strzeże przykazania, strzeże duszy swojej; ale kto gardzi drogami swemi, zginie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Panu pożycza, kto ma litość nad ubogim, a on mu za dobrodziejstwo jego odda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Karz syna swego, póki o nim nadzieja, a zabiegając zginieniu jego niech mu nie folguje dusza twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Wielki gniew okazuj, kiedy odpuszczasz karanie, grożąc mu, ponieważ odpuszczasz, że potem srożej karać będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Słuchaj rady, a przyjmuj karność, abyś kiedyżkolwiek był mądrym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Wiele jest myśli w sercu człowieczem; ale rada Pańska, ta się ostoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Pożądana rzecz człowiekowi dobroczynność jego, ale lepszy jest ubogi, niż mąż kłamliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Bojażń Pańska prowadzi do żywota, a kto ją ma, w obfitości mieszka, i nie spotka go nieszczęście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Leniwy kryje rękę swą pod pachę, i do ust swych nie podnosi jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Bij naśmiewcę, żeby prostak był ostrożniejszym; a roztropnego sfukaj, żeby zrozumiał umiejętność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Syn wstyd i hańbę zadawający, ojca gubi i matkę wygania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Synu mój! przestań słuchać nauki, któraby cię odwodziła od mów rozumnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Świadek złośliwy pośmiewa się z sądu, a usta niezbożnych połykają nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Sądy są na pośmiewców zgotowane, a guzy na grzbiet głupich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Wino czyni pośmiewcę, a napój mocny zwajcę; przetoż każdy, co się w nim kocha, nie bywa mądrym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Strach królewski jest jako, ryk lwięcia; kto go rozgniewa, grzeszy przeciwko duszy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Uczciwa rzecz każdemu, poprzestać zwady; ale głupim jest, co się w nią wdaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Dla zimna leniwy nie orze; przetoż żebrać będzie we żniwa, ale nic nie otrzyma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Rada w sercu męża jest jako woda głęboka: jednak mąż rozumny naczerpnie jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Większa część ludzi przechwala się uczynnością swoją; ale w samej rzeczy, któż takiego znajdzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Sprawiedliwy chodzi w uprzejmości swojej; błogosławieni synowie jego po nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Król siedząc na stolicy sądowej rozgania oczyma swemi wszystko złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Któż rzecze: Oczyściłem serce moje? czystym jest od grzechu mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Dwojaki gwicht i dwojaka miara, to oboje obrzydliwością jest Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Po zabawach swych poznane bywa i dziecię, jeźli czysty i prawy uczynek jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Ucho, które słyszy, i oko, które widzi, Pan to oboje uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Nie kochaj się w spaniu, byś snać nie zubożał, otwórz oczy swoje, a nasycisz się chlebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, 'Złe to, złe to, mówi ten, co kupuje, a odszedłszy, ali się chlubi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Wargi umiejętne są jako złoto i obfitość pereł, i kosztowne klejnoty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Weźmij szatę tego, któryć ręczył za obcego; a od tego, który ręczył za cudzoziemkę, weźmij zastaw jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Smaczny jest drugiemu chleb kłamstwa; ale potem piaskiem napełnione będą usta jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Myśli radami utwierdzaj, a wojnę prowadź opatrznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Kto objawia tajemnicę, zdradliwie się obchodzi; przetoż z tymy, którzy pochlebiają wargami swemi, nie miej towarzystwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Kto złorzeczy ojcu swemu albo matce swojej, zgaśnie pochodnia jego w gęstych ciemnościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Dziedzictwu prędko z początku nabytemu naostatek błogosławić nie będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Nie mów: Oddam złem. Oczekuj na Pana, a wybawi cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Obrzydliwością Panu dwojaki gwicht, a szale fałszywe nie podobają mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Od Pana bywają sprawowane drogi męża; ale człowiek jakoż zrozumie drogę jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Pożreć rzecz poświęconą, jest człowiekowi sidłem; a poślubiwszy co, tego zaś szukać, jakoby tego ujść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Król mądry rozprasza niezbożnych, i przywodzi na nich pomstę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Dusza ludzka jest pochodnią Pańską, która doświadcza wszystkich skrytości wnętrznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Miłosierdzie i prawda króla strzegą, a stolica jego miłosierdziem wsparta bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Ozdoba młodzieńców jest siła ich, a sędziwość poczciwością starców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Złemu są lekarstwem siności ran, i razy przenikające do wnętrzności żywota jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Serce królewskie jest w ręce Pańskiej jako potoki wód; kędy chce, nakłoni je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Wszelka droga człowieka prosta jest przed oczyma jego; ale Pan, jest który serca waży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Czynić sprawiedliwość i sąd, bardziej się Panu podoba, niżeli ofiara.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Wyniosłość oczu i nadętość serca, i oranie niepobożnych są grzechem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Myśli pracowitego pewne dostatki przynoszą; ale każdego skwapliwego przynoszą pewną nędzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Zebrane skarby językiem kłamliwym są marnością pomijającą tych, którzy szukają śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Drapiestwo niezbożnych potrwoży ich; bo nie chcieli czynić to, co było sprawiedliwego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Mąż, którego droga przewrotna, obcym jest; ale sprawa czystego jest prosta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Lepiej jest mieszkać w kącie pod dachem, niżeli z żoną swarliwą w domu przestronnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Dusza niezbożnego pragnie złego, a przyjaciel jego nie bywa wdzięczny w oczach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Gdy karzą naśmiewcę, prostak mędrszym bywa; a gdy roztropnie postępują z mądrym, przyjmuje naukę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Bóg daje przestrogę sprawiedliwemu na domie niezbożnika, który podwraca niezbożnych dla złości ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Kto zatula ucho swe na wołanie ubogiego, i on sam będzie wołał, a nie będzie wysłuchany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Dar potajemnie dany uśmierza zapalczywość, i upominek w zanadrza włożony gniew wielki uspokaja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Radość się mnoży sprawiedliwemu, gdy się sąd odprawuje; ale strach tym, którzy czynią nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Człowiek błądzący z drogi mądrości w zebraniu umarłych odpoczywać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Mąż, który dobrą myśl miłuje, staje się ubogim; a kto miłuje wino i olejki, nie zbogaci się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Niezbożnik będzie okupem za sprawiedliwego, a za uprzejmych przewrotnik.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Lepiej mieszkać w ziemi pustej, niż z żoną swarliwą i gniewliwą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Skarb pożądany i olej są w przybytku mądrego; ale głupi człowiek pożera go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Kto naśladuje sprawiedliwości i miłosierdzia, znajduje żywot, sprawiedliwość i sławę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'Mądry ubiega miasto mocarzy, a burzy potęgę ufności ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Kto strzeże ust swoich i języka swego, strzeże od ucisków duszy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Hardego i pysznego imię jest naśmiewca, który wszysko poniewoli i z pychą czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Leniwego żądość zabija; bo ręce jego robić nie chcą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'Każdego dnia pała pożądliwością; ale sprawiedliwy udziela, a nie szczędzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Ofiara niepobożnych jest obrzydliwością, a dopieroż gdyby ją w grzechu ofiarował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Świadek fałszywy zaginie; ale mąż dobry to, co słyszy, statecznie mówić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Mąż niezbożny zatwardza twarz swoję; ale uprzejmy sam sprawuje drogę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Niemasz mądrości, ani rozumu, ani rady przeciwko Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Konia gotują na dzień bitwy; ale od Pana jest wybawienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Lepsze jest dobre imię, niż bogactwa wielkie; a przyjaźń lepsza, niż srebro i złoto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Bogaty i ubogi spotkali się z sobą; ale Pan jest obydwóch stworzycielem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Ostrożny widząc złe ukrywa się; ale prostacy wprost idąc wpadają w szkodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Pokory i bojaźni Pańskiej nagrodą jest bogactwo, i sława i żywot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Ciernie i sidła są na drodze przewrotnego; kto strzeże duszy swej, oddala się od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Ćwicz młodego według potrzeby drogi jego; bo gdy się zstarzeje, nie odstąpi od niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Bogaty nad ubogimi panuje; ale ten, co pożycza, sługą bywa tego, który mu pożycza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Kto sieje nieprawość, żąć będzie utrapienie, a rózga gniewu jego ustanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Oko dobrotliwe, toć będzie ubłogosławione; bo udziela chleba swego ubogiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Wyrzuć naśmiewcę, a ustanie zwada; owszem uspokoi się swar i pohańbienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Kto miłuje czystość serca, a jest wdzięczność w wargach jego, temu król przyjacielem będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Oczy Pańskie strzegą umiejętności; ale przedsięwzięcia przewrotnego podwraca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Leniwiec mówi: Lew na dworzu, w pośród ulicy bym był zabity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Usta obcych niewiast są dół głęboki; na kogo się Pan gniewa, wpadnie tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Głupstwo przywiązane jest do serca młodego; ale rózga karności oddali je od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Kto ciemięży ubogiego, aby sobie przysporzył, także kto daje bogatemu: pewnie zubożeje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Nakłoń ucha twego, a słuchaj słów mądrych, a serce twoje przyłóż ku nauce mojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'Boć to będzie uciechą, gdy je zachowasz w sercu twojem, gdy będą społem sporządzone w wargach twoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Aby było w Panu ufanie twoje; oznajmujęć to dziś, a ty tak czyń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Izalim ci nie napisał znamienitych rzeczy z strony rad i umiejętności,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'Abym ci do wiadomości podał pewność powieści prawdziwych, abyś umiał odnosić słowa prawdy tym, którzy cię posłali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Nie odzieraj nędznego, przeto że nędzny jest; ani ubogiego w bramie uciskaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Albowiem Pan się podejmie sprawy ich, i wydrze duszę tym, którzy im wydzierają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Nie bądź przyjacielem gniewliwemu, a z mężem popędliwym nie obcuj,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'Byś snać nie przywykł ścieszkom jego, a nie włożył sidła na duszę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Nie bywaj między tymi, którzy ręczą; ani między rękojmiami za długi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Bo jeźlibyś nie miał czem zapłacić, przeczżeby kto miał brać pościel twoją pod tobą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Nie przenoś starej granicy, którą uczynili ojcowie twoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Widziałżeś męża rątszego w sprawach swoich? Takowyć przed królami staje, a nie staje przed podłymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Gdy siądziesz, abyś jadł z panem, uważaj pilnie, kto jest przed tobą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'Inaczej wraziłbyś nóż w gardło swoje, jeźlibyś był chciwy pokarmu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Nie pragnij łakoci jego; bo są pokarmem obłudnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Nie staraj się, abyś się zbogacił; owszem, zaniechaj opatrzności twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'I miałżebyś obrócić oczy twoje na bogactwo, które prędko niszczeje? bo sobie uczyni skrzydła podobne orlim, i uleci do nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Nie jedz chleba człowieka zazdrosnego, a nie żądaj łakoci jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'Albowiem jako on ciebie waży w myśli swej, tak ty waż pokarm jego. Mówić: Jedz i pij, ale serce jego nie jest z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Sztuczkę twoję, którąś zjadł, zwrócisz, a utracisz wdzięczne słowa twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Przed głupim nie mów; albowiem wzgardzi roztropnością powieści twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Nie przenoś granicy starej, a na rolę sierotek nie wchodź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Bo obrońca ich możny; onci się podejmuje sprawy ich przeciwko tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Obróć do nauki serce twoje, a uszy twoje do powieści umiejętności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Nie odejmuj od młodego karności; bo jeźli go ubijesz rózgą, nie umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Ty go bij rózgą, a duszę jego z piekła wyrwiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Synu mój! będzieli mądre serce twoje, będzie się weseliło serce moje, serce moje we mnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'I rozweselą się nerki moje, gdy będą mówiły wargi twoje, co jest prawego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Niech nie zajrzy serce twoje grzesznikom; ale raczej chodż w bojańni Pańskiej na każdy dzień;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Bo iż jest zapłata, przeto nadzieja twoja nie będzie wykorzeniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Słuchaj, synu mój! a bądź mądry, i nawiedź na drogę serce twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Nie bywaj między pijanicami wina, ani między żarłokami mięsa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'Boć pijanica i żarłok zubożeje, a ospały w łatach chodzić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Słuchaj ojca twego, który cię spłodził, a nie pogardzaj matką twoją, gdy się zstarzeje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Kupuj prawdę, a nie sprzedawaj jej; kupuj mądrość, umiejętność i rozum.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Bardzo się raduje ojciec sprawiedliwego, a kto spłodził mądrego, weseli się z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Niech się tedy weseli ojciec twój, i matka twoja; i niech się rozraduje rodzicielka twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Synu mój! daj mi serce twoje, a oczy twoje niechaj strzegą dróg moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Bo nierządnica jest dół głęboki, a cudza żona jest studnia ciasna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'Ona też jako zbojca zasadzki czyni, a zuchwalców między ludźmi rozmnaża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Komu biada? Komu niestety? Komu zwady? Komu krzyk? Komu rany daremne? Komu zapalenie oczów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Tym, którzy siadają na winie; tym, którzy chodzą, szukając przyprawnego wina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Nie zapatruj się na wino, gdy się rumieni, i gdy wydaje w kubku łunę swoję, a prosto wyskakuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'Bo na koniec jako wąż ukąsi, a jako żmija uszczknie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Oczy twoje patrzyć będą na cudze żony, a serce twe będzie mówiło przewrotności;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'I będziesz jako ten, który leży w pośród morza, a jako ten, który śpi na wierzchu masztu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'Rzeczesz:Ubito mię, a nie stękałem, potłuczono mię, a nie czułem. Gdy się ocucę, udam się zaś do tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Nie naśladuj ludzi złych, ani żądaj przebywać z nimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'Albowiem serce ich myśli o drapiestwie, a wargi ich mówią o uciśnieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Mądrością bywa dom zbudowany, a roztropnością umocniony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'Zaiste przez umiejętność komory napełnione bywają wszelakiemi bogactwami kosztownemi i wdzięcznemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Człowiek mądry mocny jest, a mąż umiejętny przydaje siły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Albowiem przez mądrą radę zwiedziesz bitwę, a wybawienie przez mnóstwo radców mieć będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Wysokie są głupiemu mądrości; w bramie nie otworzy ust swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Kto myśli źle czynić, tego złośliwym zwać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Zła myśl głupiego jest grzechem, a pośmiewca jest obrzydliwością ludzką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Jeźli będziesz gnuśnym, tedy w dzień ucisku słaba będzie siła twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Wybawiaj pojmanych na śmierć; a od tych, którzy idą na stracenie, nie odwracaj się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Jeźli rzeczesz: Otośmy o tem nie wiedzieli; izali ten, który waży serca, nie rozumie? a ten, który strzeże duszy twojej, nie rozezna? i nie odda człowiekowi według uczynków jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Jedz miód, synu mój! bo dobry, i plastr słodki podniebieniu twemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'Tak umiejętność mądrości duszy twojej, jeźliże ją znajdziesz; onać będzie nagrodą, a nadzieja twoja nie będzie wycięta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Nie czyń zasadzki, niezbożniku! na przybytek sprawiedliwego, a nie przeszkadzaj odpocznieniu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Bo choć siedm kroć upada sprawiedliwy, przecie zaś powstaje; ale niezbożni wpadną w nieszczęście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Gdy upadnie nieprzyjaciel twój, nie ciesz się; i gdy się potknie, niech się nie raduje serce twoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'Aby snać nie ujrzał Pan, a nie podobałoby się to w oczach jego, i odwróciłby od niego gniew swój na cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Nie gniewaj się dla złośników, ani się udawaj za niepobożnymi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'Boć nie weźmie złośnik nagrody; pochodnia niepobożnych zgaśnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Synu mój! bój się Pana i króla, a z niestatecznymi nie mięszaj się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'Boć znagła powstanie zginienie ich, a upadek obydwóch któż wie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'I toć też mądrym należy: wzgląd mieć na osobę u sądu, nie dobra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Tego, który mówi niepobożnemu; Jesteś sprawiedliwy, będą ludzie przeklinać, a narody się nim brzydzić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'Ale którzy go karzą, szczęśliwi będą, a przyjdzie na nich błogosławieństwo każdego dobrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Pocałują wargi tego, co mówi słowa prawdziwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Rozrządź na polu robotę twoję, a sprawuj pilnie rolę swoję; a potem będziesz budował dom twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Nie bądź świadkiem lekkomyślnym przeciw bliźniemu swemu, ani czyń łagodnych namów wargami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Nie mów: Jako mi uczynił, tak mu uczynię; oddam mężowi temu według uczynku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Szedłem przez pole męża leniwego a przez winnicę człowieka głupiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'A oto porosła wszędzie ostem; pokrzywy wszystko pokryły, a płot kamienny jej rozwalił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Co ja ujrzawszy złożyłem to do serca mego, a widząc to wziąłem to ku przestrodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Trochę się prześpisz, trochę podrzemiesz, trochę złożysz ręce, abyś odpoczywał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'A wtem ubóstwo twoje przyjdzie jako podróżny, a niedostatek twój jako mąż zbrojny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Teć są przypowieści Salomonowe, które zebrali mężowie Ezechyjasza, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Sława to Boża, taić sprawę; ale sława królów, wywiadywać się rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Wysokość niebios, i głębokość ziemi, i serce królów nie są doścignione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Odejm zużelicę od srebra, a wynijdzie odlewającemu naczynie kosztowne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'Odejm niezbożnika od oblicza królewskiego, a umocni się w sprawiedliwości stolica jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Nie udawaj się za zacnego przed królem, a na miejscu wielmożnych nie stawaj;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'Bo lepiej jest, iż ci rzeką: Postąp sam: a niżeliby cię zniżyć miano przed księciem; co widują oczy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Nie pokwapiaj się do swaru, byś snać na ostatek nie wiedział, co masz czynić, gdyby cię zawstydził bliźni twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Prowadź do końca sprawę swoję z przyjacielem twoim, a tajemnicy drugiego nie objawiaj;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'By cię snać nie zelżył ten, co cię słucha, a niesława twoja zostałaby na tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Jakie jest jabłko złote z wyrzezaniem srebrnem, takieć jest słowo do rzeczy powiedziane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Ten, który mądrze napomina, jest u tego, co słucha, jako nausznica złota, i klejnot z szczerego złota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Jako zimno śnieżne czasu żniwa: tak poseł wierny tym, którzy go posyłają; bo dusze panów swych ochładza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Człowiek, który się chlubi darem zmyślonym, jest jako wiatr i obłoki bez deszczu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'Książę cierpliwością bywa zmiękczony, a język łagodny kości łamie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Znajdzieszli miód, jedzże, ileć potrzeba, by snać objadłszy się go nie zwrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Powściągnij nogę twoję od domu bliźniego twego, by snać będąc ciebie syt, nie miał cię w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Każdy, kto mówi fałszywe świadectwo przeciw bliźniemu swemu, jest jako młot, i miecz, i strzała ostra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Ufność w człowieku przewrotnym jest w dzień ucisku jako ząb wyłamany i noga wywiniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Jako ten, który zewłoczy odzienie czasu zimy, albo leje ocet na saletrę, taki jest ten, który śpiewa pieśni sercu smutnemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Jeźliżeby łaknął ten, co cię nienawidzi, nakarm go chlebem; a jeźliby pragnął, daj mu się napić wody;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'Bo węgle rozpalone zgromadzisz na głowę jego, a Pan ci nagrodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Jako wiatr północny deszcz przynosi: tak przynosi twarz gniewliwą język uszczypliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Lepiej mieszkać w kącie pod dachem, niżeli z żoną swarliwą w domu przestronnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Jako woda chłodna duszy pragnącej: tak wieść dobra z ziemi dalekiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Jako źródło nogami pomącone, albo zdrój zepsuty: tak sprawiedliwy, który upada przed niezbożnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Jako jeść wiele miodu nie jest rzecz dobra: tak szukanie własnej sławy jest niesławne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Mąż, który nie ma mocy nad duchem swoim, jest jako miasto rozwalone bez muru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Jako śnieg w lecie, i jako deszcz we żniwa; tak głupiemu nie przystoi chwała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Jako się ptak tam i sam tuła, i jako jaskółka lata: tak przeklęstwo niezasłużone nie przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Bicz na konia, ogłów na osła, a kij potrzebny jest na grzbiet głupiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Nie odpowiadaj głupiemu według głupstwa jego, abyś mu i ty nie był podobny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Odpowiedz głupiemu według głupstwa jego, aby się sobie nie zdał być mądrym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Jakoby nogi obciął, tak się bezprawia dopuszcza, kto się głupiemu poselstwa powierza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Jako nierówne są golenie u chromego: tak jest powieść w ustach głupich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Jako kiedy kto przywiązuje kamień drogi do procy: tak czyni ten, który uczciwość głupiemu wyrządza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Jako ciernie, gdy się dostaną w rękę pijanego: tak przypowieść jest w ustach głupich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Wielki Pan stworzył wszystko, a daje zapłatę głupiemu, daje także zapłatę przestępcom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Jako pies wraca się do zwrócenia swego: tak głupi powtarza głupstwo swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Ujrzyszli człowieka, co się sobie zda być mądrym, nadzieja o głupim lepsza jest, niżeli o nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Leniwy mówi: lew na drodze, lew na ulicach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Jako się drzwi obracają na zawiasach swoich: tak leniwiec na łóżku swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Leniwiec rękę kryje do zanadrzy swych, a ciężko mu jej podnosić do ust swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Leniwiec zda się sobie być mędrszym, niżeli siedm odpowiadających z rozsądkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Jakoby też psa za uszy łapał, kto się mimo idąc w cudzą zwadę wdaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Jako szalony wypuszcza iskry i strzały śmiertelne:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'Tak jest każdy, który podchodzi przyjaciela swego, a mówi: Azam ja nie żartował?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Gdy niestaje drew, gaśnie ogień; tak gdy nie będzie klatecznika, ucichnie zwada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Jako węgiel martwy służy do rozniecenia, i drwa do ognia; tak człowiek swarliwy do rozniecenia zwady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Słowa obmówcy są jako słowa zranionych; a wszakże przenikają do wnętrzności żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Wargi nieprzyjacielskie i serce złe są jako srebrna piana, którą polewają naczynie gliniane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Ten, co kogo nienawidzi, za inszego się udaje wargami swemi; ale w sercu swojem myśli o zdradzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'Gdyć się ochotnym mową swą ukazuje, nie wierz mu: bo siedmioraka obrzydliwość jest w sercu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Nienawiść zdradliwie bywa pokryta; ale odkryta bywa złość jej w zgromadzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Kto drugiemu dół kopie, wpada weń; a kto kamień toczy, na niego się obraca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Człowiek języka kłamliwego ma utrapienie w nienawiści, a usta łagodne przywodzą do upadku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Nie chlub się ze dnia jutrzejszego; bo nie wiesz, coć przyniesie dzień dzisiejszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Niechaj cię kto inny chwali, a nie usta twoje; obcy, a nie wargi twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Ciężkić jest kamień, i piasek ważny; ale gniew głupiego cięższy, niż to oboje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Okrutnyć jest gniew, i nagła popędliwość; ale przed zazdrością któż się ostoi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Lepsza jest przymówka jawna, niżeli miłość skryta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Lepsze są rany od przyjaciela, niż łagodne całowanie człowieka nienawidzącego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Dusza nasycona i plastr miodu podepcze; ale głodnej duszy i gorzkość wszelaka słodka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Jako ptak odlatuje od gniazda swojego: tak człowiek odchodzi od miejsca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Jako maść i kadzenie uwesela serce: tak słodkość przyjaciela uwesela więcej, niż własna rada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Przyjaciela twego, i przyjaciela ojca twego nie opuszczaj, a do domu brata twego nie wchodź w dzień utrapienia twego; bo lepszy sąsiad bliski, niż brat daleki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Bądź mądrym, synu mój! a uweselaj serce moje, abym miał co odpowiedzieć temu, któryby mi urągał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Ostrożny, upatrując złe, ukrywa się; ale prostak wprost idąc, w szkodę popada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Weźmij szatę tego, któryć ręczył za obcego; a od tego, który ręczył za cudzoziemkę, weźmij zastaw jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Temu, który przyjacielowi swemu wielkim głosem rano wstawając błogosławi, poczytane to będzie za przeklęstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Kapanie ustawiczne w dzień gwałtownego deszczu, i żona swarliwa są sobie podobni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'Kto ją kryje, kryje wiatr, a wonią wyda; jako olejek wonny w prawej ręce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Żelazo żelazem bywa naostrzone; tak mąż zaostrza oblicze przyjaciela swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Kto strzeże drzewa figowego, pożywa owocu jego; także kto strzeże pana swego, uczczony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Jako się w wodzie twarz przeciwko twarzy ukazuje: tak serce człowiecze przeciw człowiekowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Piekło i zatracenie nie mogą być nasycone; także i oczy ludzkie nasycić się nie mogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Tygiel srebra a piec złota doświadcza, a człowieka wieść sławy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Choćbyś głupiego i w stępie między krupami stąporem stłukł, nie odejdzie od niego głupstwo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Doglądaj pilnie dobytku twego, a miej pieczę o trzodach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Boć nie na wieki trwa bogactwo, ani korona od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Gdy wzrasta trawa, a ukazują się zioła, tedy z gór siano zbierają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'Owce będą na szaty twoje, a nagrodą polną kozły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'Nadto dostatek mleka koziego na pokarm twój, na pokarm domu twego, i na pożywienie dziewek twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Uciekają niezbożni, choć ich nikt nie goni: ale sprawiedliwi jako lwię młode są bez bojaźni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Dla przestępstwa ziemi wiele bywa książąt jej; ale dla człowieka roztropnego i umiejętnego trwałe bywa państwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Mąż ubogi, który uciska nędznych, podobny jest dżdżowi gwałtownemu, po którym chleba nie bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Którzy opuszczają zakon, chwalą niezbożnika; ale ci, którzy strzegą zakonu, są im odpornymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Ludzie źli nie zrozumiewają sądu; ale którzy Pana szukają, rozumieją wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Lepszy jest ubogi, który chodzi w uprzejmości swojej, niżeli przewrotny na drogach swych, chociaż jest bogaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Kto strzeże zakonu, jest synem roztropnym; ale kto karmi obżercę, czyni zelżywość ojcu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Kto rozmnaża majętność swoję z lichwy i z płatu, temu ją zbiera, który ubogiemu szczodrze będzie dawał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Kto odwraca ucho swe, aby nie słuchał zakonu, i modlitwa jego jest obrzydliwością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Kto zawodzi uprzejmych na drogę złą, w dół swój sam wpadnie; ale uprzejmi odziedziczą rzeczy dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Mąż bogaty zda się sobie być mądrym; ale ubogi roztropny dochodzi go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Gdy się radują sprawiedliwi, wielka jest sława; ale gdy powstawają niepobożni, kryje się człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Kto pokrywa przestępstwa swe, nie poszczęści mu się; ale kto je wyznaje i opuszcza, miłosierdzia dostąpi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Błogosławiony człowiek, który się zawsze boi; ale kto zatwardza serce swoje, wpada w złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Pan niezbożny, panujący nad ludem ubogim jest jako lew ryczący, i jako niedźwiedź głodny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Książę bezrozumny wielkim jest drapieżcą: ale kto nienawidzi łakomstwa, przedłuży dni swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Człowieka, który gwałt czyni krwi ludzkiej, choćby i do dołu uciekał, nikt nie zatrzyma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Kto chodzi w uprzejmości, zachowany będzie; ale przewrotny na drogach swoich oraz upadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Kto sprawuje ziemię swoję, chlebem nasycony bywa; ale kto naśladuje próżnujących, ubóstwem nasycony bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Mąż wierny przyczyni błogosławieństwa; ale kto się prędko chce zbogacić, nie bywa bez winy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Mieć wzgląd na osobę, rzecz niedobra; bo nie jeden dla kęsa chleba staje się przewrotnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Prędko chce człowiek zazdrościwy zbogatnieć, a nie wie, iż nać niedostatek przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Kto strofuje człowieka, większą potem łaskę znajduje, niż ten, co pochlebia językiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Kto łupi ojca swego, albo matkę swoją, a mówi, iż to nie grzech: towarzyszem jest mężobójcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Wysokomyślny wszczyna zwadę; ale kto nadzieję ma w Panu, dostatek mieć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Kto ufa w sercu swem, głupi jest; ale kto sobie mądrze poczyna, ten ujdzie nieszczęścia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Kto daje ubogiemu, nie będzie miał niedostatku; ale kto od niego odwraca oczy swe, wielkie przeklęstwa nań przyjdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Gdy niepobożni powstawają, kryje się człowiek; ale gdy giną, sprawiedliwi się rozmnażają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Człowiek, który na częste karanie zatwardza kark swój, nagle zniszczeje, i nie wskóra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Gdy się rozmnażają sprawiedliwi, weseli się lud; ale gdy panuje bezbożnik, wzdycha lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Mąż, który miłuje mądrość, uwesela ojca swego; ale kto chowa nierządnicę, traci majętność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Król sądem ziemię utwierdza; ale mąż, który dary bierze, podwraca ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Człowiek, który pochlebia przyjacielowi swemu, rozciąga sieć przed nogami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'Występek złego jest mu sidłem; ale sprawiedliwy śpiewa i weseli się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Sprawiedliwy wyrozumiewa sprawę nędznych; ale niezbożnik nie ma na to rozumu i umiejętności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Mężowie naśmiewcy zawodzą miasto; ale mądrzy odwracają gniew.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Mąż mądry, wiedzieli spór z mężem głupim, choćby się gniewał, choćby się też śmiał, nie będzie miał pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Mężowie krwawi nienawidzą uprzejmego; ale uprzejmi staranie wiodą o duszę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Wszystkiego ducha swego wywiera głupi, ale mądry na dalszy czas go zawściąga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Pana, który rad słucha słów kłamliwych, wszyscy słudzy jego są niepobożni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Ubogi i zdzierca spotkali się; a wszakże obydwóch oczy Pan oświeca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Króla, który sądzi uciśnionych według prawdy, stolica jego na wieki utwierdzona będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Rózga i karność mądrość daje; ale dziecię swawolne zawstydza matkę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Gdy się rozmnażają niezbożni, rozmnaża się i przestępstwo; ale sprawiedliwi upadek ich oglądają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Karz syna twego, a sprawić odpocznienie, i sposobi rozkosz duszy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Gdy proroctwo ustaje, lud bywa rozproszony; ale kto strzeże zakonu, błogosławiony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Sługa nie bywa słowami naprawiony; bo choć rozumie, jednak nie odpowiada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Ujrzysz człowieka skwapliwego w sprawach swoich; ale lepsza jest nadzieja o głupim, niż o nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Kto w rozkoszy chowa z dzieciństwa sługę swego, na ostatek będzie chciał być za syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Człowiek gniewliwy wszczyna zwadę, a pierzchliwy wiele grzeszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Pycha człowiecza poniża go; ale pokorny w duchu sławy dostępuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Kto spółkuje ze złodziejem, ma w nienawiści duszę swoję; także też kto przeklęstwa słyszy, a nie objawia go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Strach człowieczy stawia sobie sidło; ale kto ma nadzieję w Panu, wywyższony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Wiele tych, co szukają twarzy panów; aleć od Pana jest sąd każdego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Sprawiedliwym jest mąż niezbożny obrzydliwością; a zasię kto w uprzejmości chodzi, jest niezbożnym obrzydliwością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Te są słowa Agóra, syna Jakiego, i zebranie mów tegoż męża do Ityjela, do Ityjela i Uchala.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Zaistem jest głupszy nad innych, a rozumu człowieczego nie mam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'I nie nauczyłem się mądrości, a umiejętności świętych nie umiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Któż wstąpił na niebo, i zasię zstąpił? któż zgromadził wiatr do garści swych? Któż zagarnął wody do szaty swej? któż utwierdził wszystkie kończyny ziemi? Cóż za imię jego? i co za imię syna jego? Wieszże?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Wszelka mowa Boża jest czysta; on jest tarczą tym, którzy ufają w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Nie przydawaj do słów jego, aby cię nie karał, a byłbyś znaleziony w kłamstwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Dwóch rzecz żądam od ciebie, nie odmawiajże mi pierwej niż umrę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Marność i słowo kłamliwe oddal odemnie; ubóstwa i bogactwa nie dawaj mi; żyw mię tylko pokarmem według potrzeby mojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'Abym snać nasyconym będąc nie zaprzał się ciebie, i nie rzekł: Któż jest Pan? Albo zubożawszy żebym nie kradł, i nie brał nadaremno imienia Boga mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Nie podwodź na sługę przed Panem jego, być snać nie złorzeczył, a ty abyś nie zgrzeszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Jest rodzaj, który ojcu swemu złorzeczy, a matce swojej nie błogosławi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Jest rodzaj, który się zda sobie być czystym, choć od plugastwa swego nie jest omyty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Jest rodzaj, którego są wyniosłe oczy, i powieki jego wywyższone są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Jest rodzaj, którego zęby są jako miecze, a trzonowe zęby jego jako noże na pożarcie ubogich na ziemi, a nędzników między ludźmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Pijawka ma dwie córki, które mówią: Przynieś, przynieś.Trzy rzeczy są, które nie bywają nasycone, owszem cztery, które nie mówią: Dosyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Grób, i żywot niepłodny, ziemia też nie bywa nasycona wodą, a ogień nie mówi: Dosyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Oko, które się naśmiewa z ojca, i wzgardza posłuszeństwem macierzyńskiem, wykłują kruki u potoków, i orlęta je wyjedzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Te trzy rzeczy są ukryte przedemną, owszem cztery, których nie wiem:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'Drogi orlej na powietrzu, drogi wężowej na skale, drogi okrętowej w pośród morza, i drogi mężowej z panną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Takać jest droga niewiasty cudzołożącej: je, a uciera usta swoje, i mówi: Nie popełniłam złego uczynku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Dla trzech rzeczy porusza się ziemia, owszem dla czterech, których znieść nie może:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'Dla sługi, kiedy panuje, i dla głupiego, kiedy się nasyci chleba;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'Dla przemierzłej niewiasty, kiedy za mąż idzie, i dla dziewki, kiedy dziedziczy po pani swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'Teć są cztery rzeczy najmniejsze na ziemi, wszakże są mędrsze nad mędrców:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'Mrówki, huf słaby, które sobie jednak w lecie gotują pokarm swój;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'Króliki, twór słaby, którzy jednak budują w skale dom swój;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'Szarańcze króla nie mają, a wszakże wszystkie hufami wychodzą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'Pająk rękoma robi, a bywa w pałacach królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'Te trzy rzeczy są, które wspaniale chodzą, owszem cztery, które zmężyle chodzą:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'Lew najmocniejszy między zwierzętami, który przed nikim nie ustępuje:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'Koń na biodrach przepasany, i kozieł, i król, przeciw któremu żaden nie powstaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Jeźliś głupio uczynił, gdyś się wynosił, albo jeźliś źle myślił, połóżże rękę na usta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Kto tłucze śmietanę, wybija masło; a kto bardzo nos wyciera, wyciska krew; tak kto wzbudza gniew, wszczyna zwadę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Te są słowa Lemuela króla, i zebranie mów, któremi go ćwiczyła matka jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Cóż rzekę, synu mój? cóż rzekę, synu żywota mego? i cóż rzekę, synu ślubów moich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Nie dawaj niewiastom siły twojej, ani dróg twoich tym, którzy do zginienia królów przywodzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Nie królom, o Lemuelu! nie królom należy pić wino, a nie panom bawić się napojem mocnym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'By snać pijąc nie zapomniał na ustawy, a nie odmienił spraw wszystkich ludzi uciśnionych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Dajcie napój mocny ginącemu, a wino tym, którzy są ducha sfrasowanego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'Niech się napije, a zapomni ubóstwa swego, a na utrapienie swoje niech więcej nie wspomni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Otwórz usta swe za niemym w sprawie wszystkich osądzonych na śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Otwórz usta swe, sądź sprawiedliwie, a podejmij się sprawy ubogiego i nędznego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Któż znajdzie niewiastę stateczną, gdyż nad perły daleko większa jest cena jej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Serce męża jej ufa jej, a na korzyściach schodzić mu nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Dobrze mu czyni,a nie źle, po wszystkie dni żywota swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Szuka wełny i lnu, a pracuje ochotnie rękami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Podobna jest okrętom kupieckim; z daleka przywodzi żywność swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'I wstaje bardzo rano, a daje pokarm czeladzi swej, a obrok słuszny dziewkom swym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Obmyśla rolę, i ujmuje ją; z zarobku rąk swoich szczepi winnice.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Przepasuje mocą biodra swe, a posila ramiona swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Doświadcza, że jest dobra skrzętność jej, a nie gaśnie w nocy pochodnia jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Ręce swoje obraca do kądzieli, a palcami swemi trzyma wrzeciono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Rękę swą otwiera ubogiemu, a ręce swoje wyciąga ku nędznemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Nie boi się o czeladź swoję czasu śniegu; albowiem wszystka czeladź jej obłoczy się w szatę dwoistą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Kobierce sobie robi; płótno subtelne i szarłat jest odzieniem jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Znaczny jest w bramach mąż jej, gdy siedzi między starszymi ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Płótno robi, i sprzedaje, także pasy sprzedaje kupcowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Moc i przystojność jest odzieniem jej; nie frasuje się o czasy przyszłe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Mądrze otwiera usta swe, a nauka miłosierdzia jest na języku jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Dogląda rządu w domu swym, a chleba próżnując nie je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Powstawszy synowie jej błogosławią jej; także i mąż jej chwali ją,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, 'Mówiąc: Wiele niewiast grzecznie sobie poczynały; ale je ty przechodzisz wszystkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Omylna jest wdzięczność, i marna piękność; ale niewiasta, która się Pana boi, ta pochwały godna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Dajcie jej z owocu ręku jej, a niechaj ją chwalą w bramach uczynki jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Słowa kaznodziei, syna Dawidowego, króla w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Marność nad marnościami, powiedział kaznodzieja; marność nad marnościami, i wszystko marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Cóż za pożytek ma człowiek ze wszystkiej pracy swej, którą prowadzi pod słońcem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Jeden rodzaj przemija, a drugi rodzaj nastaje; lecz ziemia na wieki stoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'Słońce wschodzi i słońce zachodzi, a spieszy się do miejsca swego, kędy wschodzi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Idzie na południe, a obraca się na północy; wiatr ustawicznie krążąc idzie, a po okręgach swoich wraca się wiatr.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Wszystkie rzeki idą do morza, wszakże morze nie wylewa; do miejsca, z którego rzeki płyną, wracają się, aby zaś stamtąd wychodziły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Wszystkie rzeczy są pełne zabaw, a człowiek nie może ich wymówić; oko nie nasyci się widzeniem, a ucho nie napełni się słyszeniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Co było, jest to, co być ma; a co się teraz dzieje, jest to, co się dziać będzie, a niemasz nic nowego pod słońcem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Jestże jaka rzecz, o którejby kto rzec mógł: Wej! to coś nowego? I toć już było za onych wieków, które były przed nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Niemasz pamiątki pierwszych rzeczy; także też i potomnych, które będą, nie będzie pamiątki u tych, którzy potem nastaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Ja kaznodzieja byłem królem Izraelskim w Jeruzalemie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'I przyłożyłem do tego serce swe, abym szukał, i doszedł mądrością swoją wszystkiego, co się dzieje pod niebem.(Tę zabawę trudną dał Bóg synom ludzkim, aby się nią trapili.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Widziałem wszystkie sprawy, które się dzieją pod słońcem, a oto wszystko jest marnością i utrapieniem ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Co jest krzywego, nie może być wyprostowane, a niedostatki nie mogą być policzone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Przetoż takiem myślał w sercu swem, mówiąc: Otom ja uwielbił i rozszerzył mądrość nad wszystkich, którzy byli przedemną w Jeruzalemie, a serce moje dostąpiło wielkiej mądrości i umiejętności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'I przyłożyłem do tego serce moje, abym poznał mądrość i umiejętność, szaleństwo i głupstwo; alem doznał, iż to jest utrapieniem ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Bo gdzie wiele mądrości, tam jest wiele gniewu; a kto przyczynia umiejętności, przyczynia boleści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Rzekłem ja do serca mego: Nuże teraz doświadczę cię w weselu, używajże dobrych rzeczy; ale i toć marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Śmiechowi rzekłem: Szalejesz, a weselu: Cóż to czynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Przemyślałem w sercu swem, abym pozwolił wina ciału memu,(serce jednak swoje sprawując mądrością) i abym się trzymał głupstwa dotąd, ażbym obaczył, coby lepszego było synom ludzkim czynić pod niebem, przez wszystkie dni żywota ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Wielkiem sprawy wykonał; pobudowałem sobie domy, nasadziłem sobie winnic;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'Naczyniłem sobie ogrodów, i sadów, i naszczepiłem w nich drzew wszelakiego owocu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'Pobudowałem sobie stawy ku odwilżaniu przez nie lasu, w którym rośnie drzewo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Nabyłem sobie sług i dziewek, i miałem czeladź w domu moim; do tego i stada wołów, i wielkie trzody owiec miałem nad wszystkich, którzy byli przedemną w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Zgromadziłem też sobie srebro i złoto, i klejnoty od królów i krain. Sporządziłem też sobie śpiewaków i śpiewaczki, i inne rozkosze synów ludzkich, i muzyczne naczynia rozliczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'A tak stałem się wielkim i możniejszym nad wszystkich, którzy byli przede mną w Jeruzalemie; nadto mądrość moja zostawała przy mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'A wszystkiego, czego pożądały oczy moje, nie zabraniałem im, anim odmawiał sercu memu żadnego wesela; ale serce moje weseliło się ze wszystkiej pracy mojej. A toć był dział mój ze wszystkiej pracy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Lecz gdym się obejrzał na wszystkie sprawy swoje, które czyniły ręce moje, i na prace, którem podejmował pracując: oto wszystko marność, i utrapienie ducha, i niemasz nic pożytecznego pod słońcem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'Przetoż obróciłem się do tego, abym się przypatrywał mądrośći, i szaleństwu, i głupstwu; (bo cóżby człowiek czynił ten, który nastanie po królu? to, co już inni czynili.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'I obaczyłem, iż jest pożyteczniejsza mądrość niżeli głupstwo, tak jako jest pożyteczniejsza światłość, niżeli ciemność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Mądry ma oczy w głowie swej, ale głupi w ciemnościach chodzi; a wszakżem poznał, że jednakie przygody na wszystkich przychdzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Dlategom rzekł w sercu mojem: Mali mi się tak dziać, jako się głupiemu dzieje, przeczżem go ja tedy mądrośćią przeszedł? Przetożem rzekł w sercu mojem: I toć jest marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Albowiem nie na wieki będzie pamiątki mądrego i głupiego, dlatego, iż to, co teraz jest, we dni przyszłe wszystkiego zapomną; a jako umiera mądry, tak i głupi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Przetoż mi żywot omierzł; bo mi się nie podoba żadna rzecz, która się dzieje pod słońcem; albowiem wszystkie są marnością, i utrapieniem ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'Nawet omierzła mi i wszystka praca moja, którąm podejmował pod słońcem, przeto, że ją zostawić muszę człowiekowi, który nastanie po mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'A kto wie, będzieli mądrym, czyli głupim? a wszakże będzie panował nad wszystką pracą moją, którąm prowadził, i w którejm był mądry pod słońcem. Aleć i to marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'I przypadłem na to, abym zwątpił w sercu mojem o wszystkiej pracy, którąm się mądrze bawił pod słońcem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Nie jeden zaiste człowiek pracuje mądrze, i umiejętnie, i sprawiedliwie; a wszakże to innemu, który nie robił na to, za dział zostawi. I toć marność i wielka bieda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Bo cóż ma człowiek ze wszystkiej pracy swej, i z usiłowania serca swego, które podejmuje pod słońcem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Ponieważ wszystkie dni jego są bolesne, a zabawa jego jest frasunek, tak iż i w nocy nie odpoczywa serce jego. I toć jest marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Izali nie lepsza człowiekowi, aby jadł i pił, i dobrze uczynił duszy swojej z pracy swojej? alemci widział, że i to z ręki Bożej pochodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Albowiem któżby słuszniej miał jeść, i pożywać tego nad mię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Bo człowiekowi, który mu się podoba, daje mądrość, umiejętność, i wesele; ale grzesznikowi daje frasunek, aby zbierał i zgromadzał, coby zostawił temu, który się podoba Bogu. I toć jest marność, a utrapienie ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Każda rzecz ma swój czas, i każde przedsięwzięcie ma swój czas pod niebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Jest czas rodzenia i czas umierania; czas sadzenia, i czas wycinania tego, co sadzono;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'Czas zabijania, i czas leczenia; czas rozwalania, i czas budowania;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'Czas płaczu, i czas śmiechu; czas smutku, i czas skakania;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'Czas rozrzucania kamieni, i czas zbierania kamieni; czas obłapiania, i czas oddalenia się od obłapiania;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'Czas szukania, i czas stracenia; czas chowania, i czas odrzucenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'Czas rozdzierania, i czas zszywania; czas milczenia, i czas mówienia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'Czas miłowania, i czas nienawidzenia; czas wojny, i czas pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Cóż tedy ma ten, co pracuje, z tego, około czego pracuje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Widziałem pracę, którą dał Bóg synom ludzkim, aby się nią bawili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'Wszystko dobrze czyni czasu swego; owszem i żądość świata dał do serca ich, choć człowiek dzieła tego, które Bóg sprawuje, ani początku, ani końca nie dochodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Stąd wiem, że nic lepszego nie mają, jedno aby się weselili, a czynili dobrze za żywota swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'Acz i to, gdy każdy człowiek je i pije, i używa dobrze wszystkiej pracy swojej, jest dar Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Wiem i to, że cokolwiek Bóg czyni, trwa na wieki; i że się do tego nic nie może przydać, ani z tego co ująć; a czyni to Bóg, aby się bali oblicza jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'To, co było, teraz jest, a co będzie, już było; albowiem Bóg odnawia to, co przeminęło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Nadtom jeszcze widział pod słońcem na miejscu sądu niepobożność, a na miejscu sprawiedliwości niesprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'I rzekłem w sercu swem: Sprawiedliwego i niezbożnego Bóg sądzić będzie; bo czas każdemu przedsięwzięciu i każdej sprawy tam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Nadto rzekłem w sercu swem o sprawie synów ludzkich, że im Bóg okazał, aby wiedzieli, że są podobni bydłu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Bo przypadek synów ludzkich, i przypadek bydła, jest przypadek jednaki. Jako umiera ono, tak umiera i ten, i ducha jednakiego wszyscy mają, a nie ma człowiek nic więcej nad bydlę; bo wszystko jest marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Wszystko to idzie na jedno miejsce; a wszystko jest z prochu, i wszystko się zaś w proch obraca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'A któż wie, że duch synów ludzkich wstępuje w górę? a duch bydlęcy, że zstępuje pod ziemię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Przetoż obaczyłem, że człowiekowi niemasz nic lepszego, jedno weselić się z pracy swej, gdyż to jest dział jego; albowiem któż go do tego przywiedzie, aby poznał to, co ma być po nim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'Potemem się obrócił i ujrzałem wszystkie uciski, które się dzieją pod słońcem, a oto widziałem łzy uciśnionych, którzy nie mają pocieszyciela, ani mocy, aby uszli rąk tych, którzy ich ciemiężą; a nie mają, mówię, pocieszyciela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Dlategom ja umarłych, którzy już zeszli, więcej chwalił, niżeli żywych, którzy jeszcze aż dotąd żyją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'Owszem szczęśliwy jest nad tych obydwóch ten, który jeszcze nie był, który nie widział nic złego, które się dzieje pod słońcem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Bom widział, że wszelaka praca i każde dzieło dobre jest ku zazdrosci jednych drugim. I toć jest marność i utrapienie ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Głupi składa ręce swe, a je ciało swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Lepsza jest pełna garść z pokojem, niżeli obie garści pełne z pracą i z udręczeniem ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'Znowu obróciwszy się ujrzałem drugą marność pod słońcem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Jest kto samotny, niemając żadnego, ani syna, ani brata, a wżdy niemasz końca wszelakiej pracy jego, ani oczy jego mogą się nasycić bogactwem. Nie myśli: Komuż ja pracuję, tak że i żywotowi swemu ujmuję dobrego. I toć jest marność, i ciężkie udręc zenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Lepiej jest we dwóch być, niż jednemu; mają zaiste dobry pożytek z pracy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Bo jeźli jeden upadnie, drugi podźwignie towarzysza swego. A tak biada samotnemu, gdyby upadł! bo nie ma drugiego, coby go podźwignął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Także będąli dwaj społu leżeć, zagrzeją się; ale jeden jakoż się zagrzeje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'Owszem jeźliby kto jednego przemagał, dwaj mu się zastawią; a sznur troisty nie łacno się zerwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Lepszy jest chłopiec ubogi a mądry, niżeli król stary a głupi, który już nie umie przyjmować napominania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Bo ów z więzienia wychodzi, aby królował, a ten i w królestwie swojem zubożeć może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Widziałem wszystkich żyjących, którzy chodzą pod słońcem, że przestawali z chłopięciem, potomkiem onego, który miał nastąpić na królestwo po nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'Nie było końca niestatkowi wszystkiego ludu, którykolwiek był przed nimi; nie będąć się potomkowie cieszyć z niego. A tak i to jest marność, i utrapienie ducha. Strzeż nogi twojej, gdy idziesz do domu Bożego, a bądź skłonniejszym ku słuchaniu, niżeli ku dawaniu ofiar ludzi głupich; boć oni nie wiedzą, że źle czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Nie bywaj porywczy do mówienia, ani serce twoje prędkie na wymówienie słowa przed obliczem Bożem, albowiem Bóg jest na niebie, a ty na ziemi; przeto niech słów twoich mało będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Bo jako sen przychodzi z wielkiej pracy, tak głos głupiego z wielu słów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Gdy co Bogu poślubisz, nie omieszkiwaj tego oddać, boć mu się głupi nie podobają; cokolwiek poślubisz, oddaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Lepiej jest nie ślubować, niżeli poślubiwszy co, nie oddać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Nie dopuszczaj ustom twoim, aby do grzechu przywodziły ciało twoje, ani mów przed aniołem, że to jest błąd. Przeczże masz Boga gniewać mową swą, któryby wniwecz obrócił sprawę rąk twoich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Bo gdzie jest wiele snów, tam i marności i słów wiele; ale się ty Boga bój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Jeźli ucisk ubogiego, i zatrzymanie sądu i sprawiedliwości ujrzysz w której krainie, nie dziwuj się temu; bo wyższy wysokiego upatruje, a jeszcze wyżsi są nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Zabawa koło ziemi ma pierwsze miejsce u wszystkich; i król roli służy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'Kto miłuje pieniądze, nie nasyci się pieniędzy, a kto miłuje bogactwa, nie będzie miał pożytku. I toć jest marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Gdzie wiele majętności, wiele bywa tych, co ją jedzą. Cóż tedy za pożytek Panu z tego? jedno że na nie patrzy oczyma swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Słodki jest sen pracowitemu, chociaż mało, chociaż wiele jadł; ale nasycenie bogatego spać mu nie dopuści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Jest ciężka bieda, którąm widział pod słońcem; bogactwa zachowane na złe pana swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Bo takowe bogactwo złą sprawą giną, a syn, którego spłodzi, nie będzie miał nic w rękach swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Jako nagi wyszedł z żywota matki swojej, tak się wraca, jako był przyszedł, a nie odnosi nic z pracy swojej, coby miał wziąć w rękę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'A tak i toć jest ciężka bieda, że jako przyszedł, tak odejdzie. Cóż tedy za pożytek, że na wiatr pracował?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Dotego, że po wszystkie dni swoje w ciemności jadał z wielkim kłopotem, z boleścią i z gniewem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Toć jest, com ja obaczył, że dobra i osobliwa rzecz jest, jeść i pić, i używać dobrego ze wszystkiej pracy swej, którą człowiek podejmuje pod słońcem po wszystkie dni żywota swego, które mu dał Bóg; albowiem to jest dział jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'A któremukolwiek człowiekowi dał Bóg majętność i bogactwo, i dał mu w moc, aby ich używał, i odbierał dział swój, a weselił się z pracy swojej: to jest dar Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Bo nie będzie wiele pamiętał na dni żywota swego; przeto, że mu Bóg życzy wesela serca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Jest złe, którem widział pod słońcem, a jest ludziom zwyczajne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Gdy któremu człowiekowi Bóg dał bogactwa, i majętność, i sławę, tak że na niczem nie schodzi duszy jego, czegokolwiek żąda, jednak nie daje mu Bóg mocy pożywać tego: ale obcy człowiek pożera je. Toć jest marność i bieda ciężka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Jeźli kto spłodził sto synów, a żyłby wiele lat, i przedłużyłyby się dni lat jego, a jeźliby dusza jego nie była nasycona dobrem, a nie miałby ani pogrzebu: powiadam, że lepszy jest martwy płód, niżeli on.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Bo ten próżno przyszedłszy do ciemności odchodzi, a ciemnościami imię jego okryte bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'Owszem, słońca nie widział, i nic nie poznaje; a tak odpocznienie lepsze ma, niżeli ów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'A choćby też żył przez dwa tysiące lat, a dobregoby nie użył, azaż do jednego miejsca wszyscy nie idą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Wszystka praca człowiecza jest dla gęby jego, a wszakże dusza jego nie może się nasycić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Albowiem co ma więcej mądry nad głupiego? albo co ma więcej ubogi, który sobie umie poczynać między ludźmi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Lepiej jest co oczyma widzieć, niżeli tego żądać; aleć i to marność i utrapienie ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Czemkolwiek kto jest, już tak nazwano imię jego; i wiadomo było, że człowiekiem być miał, i że się nie może sądzić z mocniejszym nad się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'Ponieważ tedy wiele rzeczy jest, które rozmnażają marność, cóż z nich za pożytek ma człowiek?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Albowiem któż wie, co jest dobrego człowiekowi w tym żywocie po wszystkie dni żywota marności jego, które jako cień pomijają? Albo kto oznajmi człowiekowi, co po nim będzie pod słońcem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Lepsze jest imię dobre, niżeli maść wyborna; a dzień śmierci, niż dzień narodzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Lepiej iść do domu żałoby, niż iść do domu biesiady, przeto, iż tam widzimy koniec każdego człowieka, a żyjący składa to do serca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Lepszy jest smutek, niżeli śmiech; bo przez smutek twarzy naprawia się serce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Serce mądrych w domu żałoby; ale serce głupich w domu wesela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Lepiej jest słuchać gromienia mądrego, niżeli słuchać pieśni głupich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Bo jaki jest trzask ciernia pod garncem, tak jest śmiech głupiego; i toć jest marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Zaiste ucisk przywodzi mądrego do szaleństwa, a dar zaślepia serce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Lepsze jest dokończenie rzeczy, niżeli początek jej; lepszy jest człowiek cierpliwego ducha, niż ducha wyniosłego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Nie bądź porywczy w duchu twym do gniewu; bo gniew w zanadrzyu głupich odpoczywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Nie mów: Cóż to jest, że dni pierwsze lepsze były, niż teraźniejsze? Bobyś się o tem nie mądrze pytał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Dobra jest mądrość przy majętności,i jest pożteczna tym, którzy widzą słońce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Albowiem pod cieniem mądrości, i pod cieniem srebra odpoczywa człowiek, a wszakże przedniejsza jest umiejętność mądrości; bo przynosi żywot tym, którzy ją mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Przypatrz się sprawie Bożej; bo któż może wyprostować, co on skrzywi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'W dzień dobry zażywaj dobra, w dzień zły miej się na pieczy: boć ten uczynił Bóg przeciwko owemu, dlatego, aby nie doszedł człowiek tego, co nastanie po nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Tom wszystko widział za dni marności mojej: Bywa sprawiedliwy, który ginie z sprawiedliwością swoją; także bywa niezbożnik, który długo żyje we złości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Nie bądź nazbyt sprawiedliwym, ani nazbyt mądrym; przeczżebyś miał do zguby przychodzić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Nie bądź nader niepobożnym, ani nazbyt głupim; przeczżebyś miał umrzeć przed czasem swoim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Dobra jest, abyś się owego trzymał, a tego się nie puszczał; kto się boi Boga, uchodzi tego wszystkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Mądrość umacnia mądrego więcej, niżeli dziesięć książąt, którzy są w mieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Zaiste niemasz człowieka sprawiedliwego na ziemi, któryby czynił dobrze, a nie grzeszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Nie do wszystkich też słów, które mówią ludzie przykładaj serca twego; i niech cię to nie obchodzi, choćciby i sługa twój złorzeczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'Boć wie serce twoje, żeś i ty częstokroć drugim złorzeczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Wszystkiegom tego doświadczył mądrością, i rzekłem: Będę mądrym; aleć się mądrość oddaliła odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'A co dalekiego, i co bardzo głębokiego jest, któż to znajdzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Wszystkom ja przeszedł myślą swoją, abym poznał i wybadał się, i wynalazł mądrość i rozum, a żebym poznał niezbożność, głupstwo, i błąd, i szaleństwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'I znalazłem rzecz gorzciejszą nad śmierć, to jest, taką niewiastę, której serce jest jako sieci i sidło, a ręce jej jako pęta. Kto się Bogu podoba, wolny będzie od niej; ale grzesznik będzie od niej pojmany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Otom to znalazł, (mówi kaznodzieja,) stosując jedno z drugiem, abym doszedł umiejętności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Czego zaś nad to szukała dusza moja, tedym nie znalazł. Męża jednego z tysiąca znalazłem; alem niewiasty między temi wszystkiemi nie znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'To tylko obacz, com znalazł, że stworzył Bóg człowieka dobrego; ale oni udali się za rozmaitemi myślami. Któż może z mądrym porównać? a kto może wyłożyć każdą rzecz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Mądrość człowieka oświeca oblicze jego, a hardość twarzy jego odmienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Jać radzę, abyś wyroku królewskiego przestrzegał a wszakże według przysięgi Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Nie skwapiaj się odejść od oblicza jego, ani trwaj w uporze; albowiem cobykolwiek chciał, uczyniłciby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'Bo gdzie słowo królewskie, tam i moc jego: a któż mu rzecze: Co czynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Kto strzeże przykazania, nie uzna nic złego; i czas i przyczyny zna serce mądrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Albowiem wszelki zamysł ma czas i przyczyny; aleć wielka bieda trzyma się człowieka,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Że nie wie, co ma być; bo kiedy się co stanie, któż mu oznajmi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Niemasz człowieka, coby miał moc nad żywotem, żeby zahamował duszę, ani ma mocy nade dniem śmierci; ani ma, czemby się bronił w tym boju, ani wyswobodzi niezbożnego niepobożność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Tom wszystko widział, gdym przyłożył serce swoje do tego wszystkiego, co się pod słońcem dzieje; widziałem ten czas, którego panuje człowiek nad człowiekiem na jego złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'Tedym widział niezbożnych pogrzebionych, że się zaś nawrócili; ale którzy z miejsca świętego odeszli, przyszli w zapamiętanie w onem mieście, w którem dobrze czynili. I toć jest marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Bo iż nie zaraz wychodzi dekret na złe sprawy, przetoż na tem jest wszystko serce synów ludzkich, aby czynili złe rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'A chociaż grzesznik sto kroć źle czyni, i odwłacza mu się, wszakże ja wiem, że dobrze będzie bojącym się Boga, którzy się boją oblicza jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'Ale niezbożnemu nie dobrze będzie, ani się przedłużą dni jego, owszem pomija jako cień, przeto, iż się nie boi oblicza Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Jest też marność, która się dzieje na ziemi, że bywają sprawiedliwi, którym się tak powodzi, jakoby czynili uczynki niepobożnych; zasię bywają niepobożni, którym się tak powodzi, jakoby czynili uczynki sprawiedliwych. Przetożem rzekł: I toć jest marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'A tak chwaliłem wesele, przeto, iż niemasz nic lepszego człowiekowi pod słońcem, jedno jeść, i pić, i weselić się, a iż mu jedno to zostaje z pracy jego po wszystkie dni żywota jego, które mu Bóg dał pod słońcem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'A chociażem udał serce swe na to, abym doszedł mądrości, i zrozumiał kłopoty, które się dzieją na ziemi, dla których człowiek ani we dnie ani w nocy nie śpi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'A wszakże widziałem przy każdym uczynku Bożym, że nie może człowiek doścignąć sprawy, która się dzieje pod słońcem. Starać się człowiek chcąc tego dojść, ale nie dochodzi; owszem choćby rzekł mądry, że się chce dowiedzieć, nie będzie mógł znaleść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Zaprawdęm to wszystko uważał w sercu swem, abym to wszystko objaśnił, że sprawiedliwi i mądrzy z sprawami swemi są w rękach Bożych, a iż ani miłości, ani nienawiści nie zna człowiek ze wszystkich rzeczy, które są przed obliczem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Wszystko się dzieje jednakowo wszystkim; jednoż przychodzi na sprawiedliwego i niezbożnego, na dobrego i na czystego i nieczystego, na ofiarującego i na tego, który nie ofiaruje; na dobrego, i na grzesznego, na przysięgającego, i na tego, co się przysięgi boi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'A toć jest najgorsza między wszystkiem, co się dzieje pod słońcem, iż jednoż przychodzi na wszystkich; a owszem, że serce synów ludzkich pełne jest złego, a iż głupstwo trzyma się serca ich za żywota ich, a potem idą do umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Albowiem ktokolwiek się towarzyszy ze wszystkimi żywymi, ma nadzieję, (Gdyż i pies żywy lepszy jest, niż lew zdechły;)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Boć ci, co żyją, wiedzą, że umrzeć mają; ale umarli o niczem nie wiedzą, i nie mają więcej żadnej zapłaty, gdyż w zapamiętanie przyszła pamiątka ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Owszem i miłość ich, i zazdrość ich i nienawiść ich już zginęła, a nie mają więcej działu na wieki we wszystkiem, co się dzieje pod słońcem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Idźże tedy, jedz z radością chleb twój, a pij z dobrą myślą wino twoje; albowiem już wdzięczne są Bogu sprawy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Na każdy czas niech będą szaty twoje białe, a olejku na głowie twojej niech się nie przebiera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Zażywaj żywota z żoną, którąś umiłował, po wszystkie dni żywota marności twojej, któreć dał Bóg pod słońcem po wszystkie dni marności twojej; boć ten jest dział twój w żywocie twoim i w pracy twojej, którą podejmujesz pod słońcem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Wszystko, co przedsięweźmie ręka twoja do czynienia, czyń według możności twojej, albowiem niemasz żadnej pracy, ani myśli, ani umiejętności, ani mądrości w grobie, do którego ty idziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Potem obróciwszy się ujrzałem pod słońcem, że bieg nie jest w mocy prędkich, ani wojna w mocy mężnych, ani żywność w mocy mądrych, ani bogactwo w mocy roztropnych, ani łaska w mocy pomyślnych; ale czas i trafunek wszystko przynosi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Bo człowiek nie wie czasu swego; ale jako ryby, które bywają łowione siecią szkodliwą, i jako ptaki łapane bywają sidłem; tak ułowieni bywają synowie ludzcy we zły czas, gdy na nie nagle przypada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Nadto widziałem i tę mądrość pod słońcem, która jest wielka u mnie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Miasto małe, a w niem ludzi mało, przeciw któremu przyciągnął król możny, i obległ je, i usypał przeciwko niemu wały wielkie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'I znalazł się w niem mąż ubogi mądry, który wybawił miasto ono mądrością swoją; choć nikt nie wspomniał na onego męża ubogiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Przetożem ja rzekł: Lepsza jest mądrość, niżeli moc, aczkolwiek mądrość onego ubogiego była wzgardzona, i słów jego nie słuchali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Słów ludzi mądrych spokojnie słuchać należy, raczej niż krzyku panującego między głupimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Lepsza jest mądrość niż oręże wojenne; ale jeden grzesznik psuje wiele dobrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Jako muchy zdechłe zasmradzają i psują olejek aptekarski: tak człowieka z mądrości i z sławy zacnago trochę głupstwa oszpeca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Serce mądrego jest po prawej stronie jego; ale serce głupiego po lewej stronie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'I na ten czas, gdy głupi drogą idzie, serce jego niedostatek cierpi; bo pokazuje wszystkim, że głupim jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Jeźliby duch panującego powstał przeciwko tobie, nie opuszczaj miejsca twego; albowiem pokora wstręt czyni grzechom wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Jest złe, którem widział pod słońcem, to jest, błąd, który pochodzi od zwierzchności:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'Że głupi wywyższani bywają w godności wielkiej, a bogaci w mądrość nisko siadają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Widziałem sługi na koniach, a książąt chodzących piechotą jako sługi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'kto kopie dół, sam weń wpada; a kto rozrzuca płot, wąż go ukąsi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Kto przenosi kamienie, urazi się niemi; a kto łupie drwa, niebezpieczen jest od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Jeźliże się stępi żelazo, a nie naostrzyłby ostrza jego, tedy mocy przyłożyć musi; ale to daleko lepiej mądrość sprawić może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Jeźli ukąsi wąż przed zaklęciem, nic nie pomogą słowa zaklinacza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Słowa ust mądrego są wdzięczne; ale wargi głupiego pożerają go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Początek słów ust jego głupstwo, a koniec powieści jego wielkie błazeństwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Bo głupi wiele mówi, choć nie wie ten człowiek, co ma być. Albowiem któż mu oznajmi, co po nim nastanie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Głupi pracują aż do ustania, a przecie nie mogą dojść do miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Biada tobie, ziemio! której król jest dziecięciem, i której książęta rano biesiadują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Błogosławionaś ty, ziemio! której król jest synem zacnych, a której książęta czasu słusznego jadają dla posilenia, a nie dla opilstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Dla lenistwa się dach pochyla, a dla osłabiałych rąk przecieka dom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Dla uweselenia gotują uczty, i wino rozwesela żywot; ale pieniądze do wszystkiego dopomagają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Ani w myśli twojej królowi nie złorzecz, ani w skrytym pokoju twoim nie przeklinaj bogatego; albowiem i ptak niebieski doniósłby ten głos; a to, co ma skrzydła, objawiłoby powieść twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Puszczaj chleb twój po wodzie; bo po wielu dniach znajdziesz go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Daj cząstkę siedmiom albo ośmiom; bo nie wiesz, co złego będzie na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Gdy się napełniają obłoki, deszcz na ziemię wypuszcają; a gdy upada drzewo na południe, albo na północy, na któremkolwiek miejscu upadnie to drzewo, tam zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Kto upatruje wiatr, nigdy nie będzie siał; a kto się przypatruje obłokom, nie będzie żął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Jako ty nie wiesz, która jest droga wiatru, i jako się zrastają kości w żywocie brzemiennej: tak nie wiesz sprawy Bożej, który wszystko czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Poranu siej nasienie twoje, a w wieczór nie dawaj odpoczynku ręce twojej, gdyż ty nie wiesz, co jest lepszego, toli, czy owo, czyli też oboje jednako dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Zaprawdę wdzięczna jest światłość, i miła rzecz oczom widzieć słońce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'A wszakże, choćby przez wiele lat żyw był człowiek, a przez te wszystkie weseliłby się, tedy przywiódłszy sobie na pamięć dni ciemności, jako ich wiele będzie, cokolwiek przeszło, uzna być marnością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Przetoż wesel się, młodzieńcze! w młodości twojej, a niech używa dobrej myśli serce twoje za dni młodości twojej, a chodź drogami serca twego, i według zdania oczu twoich; ale wiedz, że cię dla tego wszystkiego Bóg na sąd przywiedzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'A tak oddal gniew od serca twego, i odrzuć złość od ciała twego, gdyż dzieciństwo i młodość są marnością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'Pamiętaj tedy na stworzyciela swego we dni młodości twojej, pierwej niżeli nastaną złe dni, i nadejdą lata, o których rzeczesz: Nie podobają mi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'Pierwej niż się zaćmi słońce, i światło, i miesiąc i gwiazdy, a nawrócą się obłoki po dżdżu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'W dzień, którego się poruszą stróże domowi, i zachwieją się mężowie duży i ustaną melący, przeto, iż ich mało będzie, i zaćmią się wyglądający oknami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'I zawrą się drzwi z dworu z słabym głosem mełcia; i powstanie na głos ptaszy, i ustaną wszystkie córki śpiewające.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'Nawet i wysokiego miejsca bać się będą, i będą się lękać na drodze, gdy zakwitnie migdałowe drzewo, także i szarańcza będzie mu ciężka, i żądza go ominie; bo człowiek idzie do domu wiecznego, a płaczący po ulicach chodzić będą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'Pierwej niż się przerwie sznur srebrny, i niż się stłucze czasza złota, a rozsypie się wiadro nad zdrojem, a skruszy się koło nad studnią;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'I wróci się proch do ziemi, jako przedtem był, a duch wróci się do Boga, który go dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Marność nad marnościami, mówi kaznodzieja, a wszystko marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'A czem więcej kaznodzieja był mędrszym, tem więcej nauczał umiejętności ludu, a rozważał i wywiadywał się, i składał wiele przypowieści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Starał się kaznodzieja, jakoby znalazł powieści wdzięczne, i napisał, co jest dobrego, i słowa prawdziwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Słowa mądrych podobne ościeniom, i podobne gwoździom wbitym; słowa tych, którzy je złożyli, podane są od pasterza jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'A tak, synu mój! z tych słów się dostatecznie upomnieć miożesz; albowim składaniu wielu ksiąg końca niemasz, a wiele czytać, jest spracowanie ciała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Suma wszystkiego, coś słyszał: Boga się bój, a przykazań jego przestrzegaj, bo na tem człowiekowi wszystko zależy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Ponieważ każdy uczynek, i każdą rzecz tajną, lub dobrą, lub złą, Bóg na sąd przywiedzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Pieśń najprzedniejsza z pieśni Salomonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'Niech mię pocałuje pocałowaniem ust swoich; albowiem lepsze są miłości twoje niż wino.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Dla wonności wyborne są maści twoje; imię twoje jest jako olejek rozlany; przetoż cię panienki umiłowały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Pociągnijże mię, a pobieżymy za toba. Wprowadził mię król do pokojów swoich; przetoż się w tobie radować i weselić będziemy milości twoje raczej niż wino; bo uprzejmi milują cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Czarnamci, alem wdzięczna, o córki Jeruzalemskie! Jestem jako namioty Kedarskie, jako opony Salomonowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Nie patrzajcie na mię, żem jest śniada; bo mię opalilo słonce.Synowie matki mojej rozpaliwszy się przeciwko mnie, postanowili mię, abym strzegła winnic; a winnicy mojej, którąm miała, nie strzegłam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Oznajmijże mi ty, którego miłuje dusza moja, gdzie pasiesz? gdzie trzodzie dajesz odpoczywać w południe? albowiem przeczżebym miała być jako obłąkana przy trzodach towarzyszów twoich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Jeśli nie wiesz, o najpiękniejsza między niewiastami! wynijdźże śladem trzody, a paś koźlatka twoje przy budach pasterzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Przyrównywam cię, o przyjaciółko moja! jeździe w wozach Faraonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Jagody lica twego klejnotami są ozdobione, a szyja twoja łańcuchami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Naczynimyć klejnotów złotych z nakrapianiem srebrnem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Dotąd, pokąd król jest u stołu, szpikanard mój wydaje wonność swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Jako snopek myrry jest mi miły mój na piersiach moich odpoczywający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Miły mój jest mi jako grono cyprowe na winnicach, w Engaddy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'O jakoś ty piękna, przyjaciółko moja, o jakoś ty piękna! oczy twoje jako oczy gołębicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'O jakoś ty jest piękny, miły mój! i jako wdzięczny! nawet i to łoże nasze zieleni się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Belki domów naszych są cedrowe, a stropy nasze jodłowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Jam jest jako róża Sarońska, a lilija przy dolinach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Jako lilija między cierniem, tak przyjaciółka moja między pannami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Jako jabłoń między drzewem leśnem, tak miły mój między młodzieńcami. Pragnęłam siedzieć w cieniu jego, i siedzę; bo owoc jego słodki jest ustom moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Wprowadził mię w dom wina, mając za chorągiew miłość przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Oczerstwijcie mię temi flaszami, posilcie mię temi jabłkami; boć omdlewam od miłości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Lewica jego pod głową moją, a prawica jego obłapia mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Poprzysięgam was, córki Jeruzalemskie! przez sarny i łanie polne, abyście nie budziły i nie przerywały snu miłego mego, dokąd nie zechce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Głos miłego mego! oto on idzie skacząc po tych górach, a poskakując po tych pagórkach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Miły mój podobny jest sarnie, albo młodemu jelonkowi; oto on stoi za ścianą naszą, wygląda z okien, patrzy przez kraty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Ozwał się miły mój, a rzekł mi: Wstań, przyjaciółko moja! piękna moja! a pójdź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Albowiem oto minęła zima! deszcz przeszedł, i przestał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Kwiatki się ukazują na ziemi; czas śpiewania przyszedł, a głos synogarlicy słychać w ziemi naszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'Figowe drzewo wypuściło niedojrzałe figi swoje, a macice winne rozkwitłe, wonią wydały; wstańże przyjaciółko moja, piękna moja! a pójdź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Gołębico moja mieszkająca w rozpadlinach skalnych, w skrytościach przykrych! okaż mi oblicze twoje, niech usłyszę głos twój; albowiem głos twój wdzięczny, a oblicze twoje pożądane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Połapcie nam liszki, liszki małe, które psują winnice; ponieważ winnice nasze kwitną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Miły mój jest mój, a jam jest jego, który pasie między lilijami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Ażby się okazał ten dzień, a cienie przeminęły. Nawróć się, bądź podobny, miły mój! sarnie albo jelonkowi młodemu na górach Beter.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Na łożu mojem w nocy szukałam tego, którego miłuje dusza moja; szukałam go, alem go nie znalazła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Już tedy wstanę, a obieżę miasto; po rynkach i po ulicach będę szukać tego, którego miłuje dusza moja; szukałam go, alem go nie znalazła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Natrafili mię stróżowie, którzy chodzili po mieście; i spytałem: Widzieliżeście tego któego miłuje dusza moja?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'A gdym maluczko odeszła od nich, zarazem znalazła tego, którego miłuje dusza moja. Uchwyciłam się go, a nie puszczę go, aż go wprowadzę do domu matki mojej, i do pokoju rodzicielki mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Poprzysięgam was, córki Jeruzalemskie! przez sarny i łanie polne, abyście nie budziły ani przerywały snu miłego mojego, dokądby nie zechciał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Któraż to jest, co występuje z puszczy jako słuoy dymu, okurzona będąc myrrą i kadzidłem droższem nad wszelaki proszek aptekarski?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Oto łoże Salomonowe, około którego stoi sześćdziesiąt mocarzów z mocarzów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Wszyscy ci trzymają miecz, będąc wyćwiczeni do bitwy; każdy z nich ma swój miecz przy boku swym dla strachu nocnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Pałac sobie król Salomon wystawił z drzewa Libańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Słupy jego poczynił srebrne, a pokład jego złoty, podniebienie szarłatne, a wewnątrz usłany jest miłością córek Jerozolimskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Wynijdźcie, córki Syońskie! a oglądajcie króla Salomona w koronie, którą go ukoronowała matka jego w dzień zrękowin jego, i w dzień wesela serca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'O jakoś ty piękna, przyjaciółko moja; o jakoś ty piękna! Oczy twoje jako oczy gołębicy między kędzierzami twemi; włosy twoje jako trzoda kóz, które widać na górze Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Zęby twoje jako stado owiec jednakich, gdy wychodzą z kąpieli, z których każda miewa po dwojgu, a niepłodnej niemasz między niemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Wargi twoje jako sznur karmazynowy, a wymowa twoja wdzięczna; skronie twoje między kędzierzami twemi są jako sztuka jabłka granatowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Szyja twoja jako wieża Dawidowa z obronami wystawiona, w której tysiąc tarczy wisi, i wszystka broń mocarzów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Obie piersi twoje jako dwoje bliźniąt sarnich, które się pasą między lilijami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Ażby się okazał ten dzień, a cienie przeminęły, wnijdę na górę myrry, i na pagórek kadzidła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Wszystkaś ty jest piękna, przyjaciółko moja! a zmazy niemasz na tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Pójdziesz ze mną z Libanu, o oblubienico moja! ze mną z Libanu pójdziesz, a spojrzysz z wierzchu góry Amana, z wierzchu góry Sanir i Hermon, z jaskiń lwich, i z gór lampartowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Ujęłaś serce moje, siostro moja, oblubienico moja! ujęłaś serce moje jednem okiem twojem, i jednym łańcuszkiem na szyi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'O jakoż są ucieszne miłości twoje, siostro moja! oblubienico moja! O jako daleko zacniejsze miłości twoje, niż wino, a wonność maści twoich nad wszystkie rzeczy wonne!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Plastrem miodu opływają wargi twoje, oblubienico moja! miód i mleko pod językiem twoim, a wonność szat twoich, jako wonność Libanu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Ogrodem zamknionym jesteś, siostro moja, oblubienico moja! źródło zamknione, zdrój zapieczętowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Szczepki twoje są sadem jabłek granatowych z owocem wdzięcznym cyprysu i szpikanardu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'Szpikanardu, i szafranu, kasyi, i cynamonu, ze wszystkiemi drzewami kadzidło przynoszącemi! myrry, i aloesu, ze wszystkiemi osobliwemi rzeczami wonnemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'O źródło ogrodne, zdroju wód żywych, które płyną z Libanu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Powstań wietrze północny, a przyjdź wietrze z południa, przewiej ogród mój; niech płyną wonności jego, niech przjdzie miły mój do ogrodu swego, a niech je rozkoszne owoce swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Przyszedłem do ogrodu mego, siostro moja, oblubienico moja! zbieram myrrę moję z rzeczami wonnemi mojemi; jem plastr mój z miodem moim, piję wino moje z mlekiem mojem. Jedzcież, przyjaciele! pijcie, a pijcie dostatkiem, mili moi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Jać śpię; ale serce moje czuje, i słyszy głos miłego mego, kołaczącego i mówiącego: Otwórz mi, siostro moja, przyjaciółko moja, gołębico moja, uprzejma moja! albowiem głowa moja pełna jest rosy, a kędzierze moje kropli nocnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, 'I odpowiedziałem: Zewlekłam suknię moję, jakoż ją oblec mam? umyłam nogi moje, jakoż je zmazać mam?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Miły mój ściągnął rękę swoję dziurą, a wnętrzności moje wzruszyły się we mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'I wstałam, abym otworzyła miłemu memu, a oto z rąk mych kapała myrra, a z palców moich myrra ciekąca na rękojeść zawory.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Otworzyłam miłemu memu; ale miły mój już był odszedł i minął. Omdlałam była na głos jego; szukałam go, alem go nie znalazła; wołałam go, ale mi się nieozwał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Natrafili mię stróże, co chodzą po mieście; ubili mię, zranili mię, wzięli i płaszcz mój ze mnie stróże murów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Poprzysięgam was, córki Jeruzalemskie! Jeślibyście znalazły miłego mego, abyście mu powiedziały, żem od miłości zachorowała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Cóż ma miły twój nad innych miłych, o najpiękniejsza między niewiastami? co ma miły twój nad innych miłych, że nas tak poprzysięgasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Miły mój biały i rumiany, i zacniejszy nad innych dziesięć tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Głowa jego jako bryła szczerego złota; włosy jego kędzierzawe, czarne jako kruk;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Oczy jego jako gołębicy nad strumieniami wody, jako umyte w mleku, stojące w mierze swojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Policzki jego jako zagonki ziół wonnych, jako kwiatki wonnych rzeczy; wargi jego jako lilije wypuszczające myrrę ciekącą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Ręce jego jako pierścienie złote, osadzone drogim kamieniem, hiacyntem; brzuch jego jako glanc kości słoniowej, safirem osadzonej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Golenie jego jako słupy marmurowe, postawione na podstawkach złota wybornego; oblicze jego jako Liban, wyborne jako cedry;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Usta jego nader słodkie, a wszystek jest pożądany. Taki ci jest miły mój, i taki przyjaciel mój, o córki Jeruzalemskie! Gdzież poszedł miły twój, o najpiękniejsza między niewiastami? Gdzie się obrócił miły twój? a szukać go będziemy z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Miły mój wstąpił do ogrodu swego między zagonki ziół wonnych, aby pasł w ogrodach, i żeby zbierał lilije.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Jam jest miłego mego, a miły mój jest mój, który pasie między lilijami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Pięknaś ty, przyjaciółko moja! jako Tersa; pięknaś, jako Jeruzalem; ogromna, jako wojsko uszykowane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, '(Odwróć oczy twoje odemnie, gdyż mię one srogim czynią). Włosy twoje są jako stada kóz, które wychodzą z Galaad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Zęby twoje są jako stado owiec, które wychodzą z kąpieli, z których każda miewa po dwojgu, a niepłodnej niemasz między niemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Skronie twoje między kędzierzami twemi są jako sztuka jabłka granatowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Aczkolwiek jest sześćdziesiąt żon królewskich, a ośmdziesiąt założnic, a panien bez liczby:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Wszakże jednaż jest gołębica moja, uprzejma moja, jedynaczka u matki swojej, bez zmazy u rodzicielki swojej. Ujrzawszy ją córki, błogosławioną ją nazwały; także i żony królewskie i założnice, i chwaliły ją, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'Któraż to jest, co się pokazuje jako zorza, piękna jako miesiąc, czysta jako słońce, ogromna jako wojsko uszykowane z chorągwiami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Zstąpiłam do ogrodu orzechowego, abym oglądała owoce rosnące w dolinach; abym obaczyła, jeźli kwitną winne macice, a wypuszczająli pączki jabłonie granatowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Niżem się dowiedziała, dusza moja wsadziła mię na wóz przedniejszych z ludu mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'Nawróć się, nawróć się, o Sulamitko! nawróć się, nawróć się, niech na cię patrzymy. Cóż widzicie na Sulamitce? Widzimy, jakoby hufy wojenne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'O jako piękne są nogi twoje w trzewikach, o córko książęca! Opasania biódr twoich są jako zawieszenia, ręką dobrego rzemieślnika urobione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Pępek twój jako czasza okrągła, która nie jest bez napoju; brzuch twój jest jako bróg pszenicy osadzony lilijami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Obie piersi twoje są jako dwoje bliźniąt młodych sarniąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Szyja twoja jako wieża z kości słoniowych; oczy twoje jako sadzawki w Hesebon podle bramy Batrabim; nos twój jako wieża na Libanie, która patrzy ku Damaszkowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Głowa twoja na tobie jako Karmel, a włosy głowy twojej jako szarłat.Król widząc cię byłby jako przywiązany na gankach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'O jakożeś piękna, i jako wdzięczna, o miłości przerozkoszna!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Ten twój wzrost podobny jest palmie, a piersi twoje gronom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Rzekłem: Wstąpię na palmę, dosięgnę wierzchów jej. Niechajże mi tedy będą piersi twoje jako grona winne, a wonność nozdrzy twoich jako jabłek wonnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'A usta twoje jako wino wyborne, które na prost bardzo mile płynie i sprawóje, że mówią wargi śpiących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Jam jest miłego mego, a do mnie jest rządza jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Przyjdź, miły mój; wyjdziemy na pole, a przenocujemy we wsiach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Rano wstaniemy do winnic; oglądamy, jeźli kwitnie winna macica, jeźli się zawiązują gronka, kwitnąli jabłka granatowe; tam ci oświadczę miłości moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Polne jabłuszka wydały wonność swoję, a przede drzwiami naszemi są wszystkie owoce wdzięczne, nowe i stare, którem tobie, miły mój! zachowała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'Obyżeś był jako bratem moim, pożywając piersi matki mojej! abym cię znalazłszy na dworzu, pocałowała cię, a nie była wzgardzona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Prowadziłabym cię, i wprowadziła do domu matki mojej, gdziebyś mię uczył; a jabym ci dała pić wino przyprawne i moszcz z jabłek moich granatowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Lewica jego pod głową moją, a prawicą swoją obłapia mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Poprzysięgam was, córki Jeruzalemskie! abyście nie budziły ani przerywały snu miłego mego, dokąd nie zechce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Któraż to jest, co występuje z puszczy, podparłszy się miłego swego? Pod jabłonią wzbudziłam cię, tam cię poczęła matka twoja, tam cię poczęła rodzicielka twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Przyłóż mię jako pieczęć na serce swoje, jako sygnet do ramienia swego! albowiem miłość mocna jest jako śmierć, twarda jako grób zawistna miłość; węgle jej jako węgle ogniste i jako płomień gwałtowny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Wody wielkie nie mogłyby zagasić tej miłości, ani rzeki zatopić; choćby kto wszystkę majętność domu swego dał za takową miłość, byłby pewnie wzgardzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Mamy sistrę maluczką, która jeszcze nie ma piersi. Cóż uczynimy z siostrą naszą w dzień, którego o niej mowa będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Jeźliże jest murem, zbudujmyż na niej pałac srebrny; a jeźli jest drzwiami, oprawmyż ją deszczkami cedrowymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Jam jest mur, a piersi moje jako wieże. Wtenczas byłam przed oczyma jego, jako ta, która znajduje pokój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Winnicę miał Salomon w Baalhamon, którą winnicę najął stróżom, aby każdy przynosił za owoc jej tysiąc srebrników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Ale winnica moja, którą mam, jest przedemną. Miej sobie tysiąc srebrników, Salomonie, a dwieście ci którzy strzegą owocu jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'O ty, która mieszkasz w ogrodach! przyjaciele słyuchają głosu twego; ozwijże mi się!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Pospiesz się, miły mój! a bądź podobnym sarnie, albo młodemu jelonkowi na górach ziół wonnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Widzenie Izajasza, syna Amosowego, które widział nad Judą i nad Jeruzalemem, za dni Ozeasza, Joatama, Achaza, i Ezechijasza, królów Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Słuchajcie niebiosa, a ty ziemio przyjmij w uszy swe! Albowiem Pan mówi: Synówem wychował i wywyższył; ale oni odstąpili odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Zna wół gospodarza swego, i osieł żłób pana swego; ale Izrael mię nie zna, lud mój nie zrozumiewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Biada narodowi grzesznemu, ludowi obciążonemu nieprawością, nasieniu złośliwych; synom skażonym! Opuścili Pana, do gniewu pobudzili świętego Izraelskiego, odwrócili się nazad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Przeczże tem więcej przyczyniacie przestępstwa, im więcej was biją? Wszystka głowa chora, i wszystko serce mdłe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Od stopy nogi aż do wierzchu głowy niemasz na nim nic całego; rana i siność, i rany zagniłe nie są wyciśnione, ani zawiązane, ani olejkiem odmiękczone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Ziemia wasza spustoszona, miasta wasze popalone ogniem. Ziemię waszę cudzoziemcy przed wami pożerają i pustoszą, jako zwykli cudzoziemcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'I została córka Syońska jako chłodnik na winnicy, jako budka w ogrodzie ogórczanym, i jako miasto zburzone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'By nam był Pan zastępów nie zostawił trochy ostatków, bylibyśmy jako Sodoma, stalibyśmy się byli Gomorze podobnymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Słuchajcie słowa Pańskiego, książęta Sodemscy! przyjmujcie w uszy zakon Boga naszego, ludzie Gomorscy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Cóż mi po mnóstwie ofiar waszych? mówi Pan. Jużem syty całopalenia baranów, i łoju tłustego bydła; a krwi cielców, i baranków, i kozłów nie pragnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Gdy przychodzicie, abyście się okazywali przed twarzą moją, któż tego żądał z rąk waszych, abyście deptali sieni moje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Nie ofiarujcież więcej ofiary daremnej. Kadzenie jest mi obrzydłością; nowiu miesiąca i sabatu, gdy zwoływacie zgromadzenia, nie mogę ścierpieć (bo nieprawością jest) ani dnia zapowiedzianego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Nowych miesięcy waszych, i uroczystych świąt waszych nienawidzi dusza moja; stały mi się ciężarem; upracowałem się nosząc je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Przetoż gdy wyciągniecie ręce wasze, skryję oczy moje przed wami; a gdy rozmnożycie modlitwę, nie wysłucham; bo ręce wasze krwi są pełne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Omyjcie się, czystymi bądźcie, odejmijcie złość uczynków waszych od oczów moich; przestańcie źle czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Uczcie się dobrze czynić; szukajcie sądu, podźwignijcie uciśnionego, sąd czyńcie sierocie, ujmujcie się o krzywdę wdowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Przyjdźcież teraz, a rozpierajmy się z sobą, mówi Pan: Choćby były grzechy wasze jako szarłat, jako śnieg zbieleją; choćby były czerwone jako karmazyn, jako wełna białe będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Będziecieli powolni, a posłuchacie mię, dóbr ziemi pożywać będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Lecz jeźli nie będziecie posłusznymi, ale odpornymi, od miecza pożarci będziecie; bo usta Pańskie mówiły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Jakoć się stało nierządnicą to miasto wierne, pełne sądu? Sprawiedliwość mieszkała w niem; lecz teraz mężobójcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Srebro twoje obróciło się w żużeł; wino twoje pomięszało się z wodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Książęta twoi są uporni, i towarzysze złodziei; każdy z nich miłuje dary, a jadą za nagrodą; sierocie nie czynią sprawiedliwości, a sprawa wdowy nie przychodzi przed nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Przetoż mówi Pan, Pan zastępów, możny Izraelski: Oto ucieszę się nad nieprzyjaciółmi moimi, a pomszczę się nad przeciwnikami swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'I obrócę rękę moję na cię, a wypalę aż do czysta zużelicę twoję, i odpędzę wszystkę cenę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'A przywrócę sędziów twoich, jako przedtem byli, i radców twoich, jako na początku. Potem cię nazywać będą miastem sprawiedliwości, miastem wiernem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Syon w sądzie okupione będzie, a ci, co się do niego nawrócą, w sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Ale przewrotnicy i grzesznicy wespół starci będą, a ci, co opuścili Pana, zniszczeją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Albowiem zawstydzeni będziecie dla gajów, którycheście pożądali; i pohańbieni dla ogrodów, któreście sobie obrali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Gdy się staniecie jako dąb, z którego liście opadły, a jako ogród, w którym wody niemasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'I będzie mocarz jako zgrzebia, a ten, który go uczynił, jako iskra; i zapalą się oboje pospołu, a nie będzie, ktoby zagasił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Słowo, które widział Izajasz, syn Amosowy, nad Judą i nad Jeruzalemem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'I stanie się w ostateczne dni, że będzie przygotowana góra domu Pańskiego na wierzchu gór, i wywyższy się nad pagórkami, a zbieżą się do niej wszystkie narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'I pójdzie wiele ludzi, mówiąc: Pójdźcie a wstąpmy na górę Pańską, do domu Boga Jakóbowego, a będzie nas uczył dróg swoich, i będziemy chodzili ścieszkami jego; albowiem z Syonu wyjdzie zakon, a słowo Pańskie z Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'I będzie sądził między narodami, a będzie karał wiele ludzi.I przekują miecze swe na lemiesze, a włócznie swe na sierpy; nie podniesie naród przeciw narodowi miecza, ani się będą ćwiczyć do bitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Domie Jakóbowy! pójdźcie, a chodźmy w światłości Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Aleś ty opuścił lud swój, dom Jakóbowy! gdyż są pełni obrzydliwości narodów wschodnich, i są wieszczkami jako Filistynowie, a w synach cudzych się kochali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'I napełniona jest ziemia ich srebrem i złotem, a końca niemasz skarbom ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Napełniona jest ziemia ich końmi, a końca niemasz wozom ich. Napełniona też jest ziemia ich bałwanami, robocie rąk swoich kłaniają się, które poczyniły palce ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'I kłania się pospolity człowiek, a uniża się i zacny mąż; przetoż nie odpuszczaj im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Wnijdź w skałę, a skryj się w prochu przed strachem Pańskim, i przed chwałą majestatu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Oczy wyniosłe człowiecze zniżone będą, a wysokość ludzka nachylona będzie; ale sam Pan wywyższony będzie dnia onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Albowiem dzień Pana zastępów przyjdzie na wszelkiego pysznego i wyniosłego, i na każdego wywyższonego, że będzie poniżony;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'I na wszystkie cedry Libańskie wysokie a podniosłe, i na wszystkie dęby Basańskie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'I na wszystkie góry wysokie, i na wszystkie pagórki wyniosłe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'I na każdą wieżę wysoką, i na każdy mur obronny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'I na wszystkie okręty morskie, i na wszystkie malowania rozkoszne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'I będzie nachylona wyniosłość człowiecza, a wywyższenie ludzkie zniżone będzie; ale sam Pan wywyższony będzie dnia onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Lecz bałwany ich do szczętu pokruszone będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Tedy wnijdą do jaskiń skalnych, i do jam podziemnych przed strachem Pańskim, i przed chwałą majestatu jego, gdy powstanie, aby ziemię potarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Dnia onego wrzuci człowiek bałwany swe srebrne i bałwany swe złote, które mu naczyniono, aby się im kłaniał, w dziury kretów i nietoperzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'I wnijdzie w rozpadliny skalne, i na wierzchołki opok przed strachem Pańskim, i przed chwałą majestatu jego, gdy powstanie, aby potarł ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Przestańcież ufać w człowieku, którego dech jest w nozdrzach jego; bo za cóż on ma być poczytany?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Albowiem oto panujący Pan zastępów odejmie od Jeruzalemu i od Judy łaskę, i podporę, wszelaką podporę chleba, i wszelaką podporę wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Mocarza i męża walecznego, i sędziego, i proroka, i mędrca, i starca;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Rotmistrza nad pięćdziesiąt, a męża poważnego, i radcę, i mądrego rzemieślnika, i krasomówcę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'I dam im dzieci za książęta; dzieci mówię panować będą nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'I będzie uciskał między ludem jeden drugiego, i bliźni bliźniego swego: powstanie dziecię przeciwko starcowi, a podły przeciwko zacnemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'A gdy się uchwyci każdy brata swego z domu ojca swego, i rzecze: Masz odzienie, bądźże książęciem naszym, a upadek ten zatrzymaj ręką swą:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Tedy on przysięże dnia onego, mówiąc: Nie będę zawiązywał tych ran: albowiem w domu moim niemasz chleba, ani odzienia; nie stanowcież mię książęciem nad ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Bo Jeruzalem upada, a Juda się wali, dlatego, że język ich, i sprawy ich są przeciwko Panu, pobudzając do gniewu oczy majestatu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Postawa oblicza ich świadczy przeciwko nim; grzech swój, jako Sodomczycy, opowiadają, a nie tają go. Biada duszy ich! albowiem sami na się złe przywodzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Powiedzcie sprawiedliwemu, że mu dobrze będzie; bo owocu uczynków swoich pożywać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Ale biada niepobożnemu! źle mu będzie; albowiem odpłata rąk jego dana mu będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Książęta ludu mego są dziećmi, a niewiasty panują nad nimi. O ludu mój! ci, którzy cię wodzą, zwodzą cię, a drogę ścieżek twoich ukrywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Powstał Pan, aby sądził, stoi, aby sądził lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Pan przyjdzie na sąd przeciwko starszym ludu swego, i przeciwko książętom ich, a rzecze: Wyście spustoszyli winnicę moję, zdzierstwo z ubogiego w domach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Przeczże trzecie lud mój, a oblicza ubogich bijecie? mówi Pan, Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'I rzekł Pan: Iż się wynoszą córki Syońskie, a chodzą szyje wyciągnąwszy, i mrugając oczyma przechodzą się, a drobno postępując nogami swemi szelest czynią:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'Przetoż obłysi Pan wierzch głowy córek Syońskich, a Pan sromotę ich obnaży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Dnia onego odejmie Pan ochędóstwo podwiązek, także czepce i zawieszenia,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Piżmowe jabłka, i manele, i zatyczki,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Bieretki, i zapony, i bindy, i przedniczki, i nausznice;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Pierścionki, i naczelniki,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Odmienne szaty, i płaszczyki, i podwiki, i wacki,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'Zwierciadła, i rantuszki, i tkanki, i letniki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'I będzie miasto wonnych rzeczy smród, a miasto pasa rozpasanie, a miasto utrefionych włosów łysina, a miasto szerokiej szaty opasanie worem, a miasto piękności ogorzelina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Mężowie twoi od miecza upadną, a mocarze twoi w bitwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'I zasmucą się, a płakać będą bramy jego, a spustoszony na ziemi siedzieć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'A w on dzień uchwyci się siedm niewiast męża jednego, mówiąc: Chleb swój jeść będziemy, i odzieniem swem przyodziewać się będziemy; tylko niech nas zowią od imienia twego, a odejmij pohańbienie nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'W on dzień latorośl Pańska zacna i sławna będzie, a owoc ziemi bujny i pozorny tym, którzy zachowani będą z Izraela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'I stanie się, że kto zostanie na Syonie, i który zostawiony będzie w Jeruzalemie, świętym słynąć będzie, każdy, który jest napisany do żywota w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Gdy omyje Pan plugastwo córek Syońskich, a krew Jeruzalemską opłócze z niego w duchu sądu, i w duchu zapalenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'I stworzy Pan nad każdem miejscem góry Syońskiej, i nad każdem zgromadzeniem jej obłok we dnie, a dym i jasność pałającego ognia w nocy: bo nad wszystką sławą będzie ochrona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'A będzie namiotem na zasłonę we dnie od gorąca, a na ucieczkę i ukrycie przede dżdżem i powodzią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Zaśpiewam teraz miłemu memu piosnkę miłego mego o winnicy jego. Winnicę ma miły mój na pagórku urodzajnym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Którą ogrodził, i wybrał z niej kamienie, a nasadził ją macicami wybornemi, i zbudował wieże w pośrodku niej, także i prasę postawił w niej, a czekał, aby wydała grona; ale ona zrodziła płonne wino.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'A tak, obywatele Jeruzalemscy i mężowie Judzcy! proszę, rozsądźcie teraz między mną i między winnicą moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Cóż dalej czynić było winnicy mojej, czegobym jej nie uczynił? Gdym rzekał, aby wydała grona, czemuż zrodziła płonne wino?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'A przetoż oznajmię wam, co ja uczynię winnicy mojej: Rozbiorę płot jej, a będzie spustoszona; rozwalę ogrodzenie jej, a będzie podeptana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'I uczynię ją pustą; nie będzie obrzezywana, ani okopywana, ale porośnie ostem i cierniem; obłokom też przykażę, aby na nią więcej dżdżu nie spuszczały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Winnica zaiste Pana zastępów jest dom Izraelski, a mąż Judzki szczepieniem jego rozkosznem. Oczekiwał sądu, a oto uciśnienie; oczekiwał sprawiedliwości, a oto krzyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Biada wam, którzy przyłączacie dom do domu, a rolę do roli przyczyniacie, tak, że miejsca innym nie staje, jakobyście tylko sami mieszkać mieli na ziemi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Pan zastępów rzekł w uszy moje: Zaiste wiele domów spustoszeje, a wielkie i piękne domy będą bez obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Do tego dziesięć stajan winnicy przyniosą jednę baryłę wina, a jeden chomer nasienia wyda efa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Biada tym, którzy rano wstawając chodzą za pijaństwem, a trwają na niem do wieczora, aż ich wino rozpali!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'A cytra, i lutnia, bęben i piszczałka, i wino bywa na biesiadach ich; ale na sprawy Pańskie nie patrzą, a na uczynki rąk jego nie oglądają się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Przetoż w niewolę pójdzie lud mój, iż nie ma umiejętności; a zacni jego będą głodnymi, i pospólstwo jego wyschnie od pragnienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Dlatego rozszerzyło piekło gardło swoje, a rozdarło nad miarę paszczękę swoję, i zstąpią do niego szlachta i pospólstwo jego, i zgiełk jego, i ci, którzy się weselą w niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'A tak będzie nachylony człowiek, a zacny mąż poniżony będzie, i oczy wyniosłych zniżone będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Ale Pan zastępów wywyższony będzie w sądzie, a Bóg święty ukaże się świętym w sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'I będą się paść baranki według zwyczaju swego, a przychodniowie pustyń bogaczów pożywać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Biada tym, którzy ciągną nieprawość powrozami marności, a grzech jako powrozem wozowym!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Którzy mówią: Niech się pospieszy, a niechaj nie omieszkuje sprawa jego, abyśmy ją widzieli; niech się przybliży i przyjdzie rada świętego Izraelskiego, żebyśmy się dowiedzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Biada tym, którzy nazywają złe dobrem a dobre złem; którzy pokładają ciemność za świetłość, a światłość za ciemność; którzy pokładają gorzkość za słodkość, a słodkość za gorzkość!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Biada tym, którzy się sobie zdadzą być mądrymi, a sami u siebie roztropnymi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Biada tym, którzy są mocni na picie wina, a mężom dużym ku nalewaniu napoju mocnego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'Którzy usprawiedliwiają niezbożnego za podarki, a sprawiedliwość sprawiedliwych odejmują od nich!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Przetoż jako płomień ogniowy pożera parzdzieże, i jako płomień plewy trawi: tak korzeń ich będzie jako zgnilizna, a kwiat ich jako proch ku górze pójdzie; albowiem odrzucili zakon Pana zastępów, a wyrokiem świętego Izraelskiego pogardzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Dlatego się zapaliła popędliwość Pańska przeciw ludowi swemu, a wyciągnąwszy nań rękę swą poraził go, tak że się zatrząsnęły góry, i były trupy ich jako gnój po ulicach. W tem jednak wszystkiem nie odwróciła się zapalczywość jego, ale jeszcze ręk a jego jest wyciągniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Bo podniesie chorągiew do narodu dalekiego, a zaświśnie nań od kończyn ziemi, a oto rychło i prędko przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Żadnego spracowanego i upadającego nie będzie między nimi; nie będzie drzemiącego ani śpiącego, ani się rozepnie pas na biodrach jego, ani się rozerwie rzemyk u trzewików jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Strzały jego ostre, i wszystkie łuki jego naciągnione; kopyta koni jego jako krzemień poczytane będą, a koła jego jako burza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Ryk jego jako lwi; będzie ryczał jako szczenięta lwie; będzie zgrzytał, i porwie łup, i uciecze z nim, a nie będzie ktoby go wydarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'I zaszumi nad nim dnia onego jako szum morski. Tedy spojrzymy na ziemię, a oto ciemność i ucisk; bo i światło zaćmi się przy wytraceniu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Roku, którego umarł król Uzyjasz, widziałem Pana, siedzącego na stolicy wysokiej i wyniosłej, a podołek jego napełniał kościół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Serafinowie stali nad nim, sześć skrzydeł miał każdy z nich; dwoma zakrywał twarz swoję, a dwoma przykrywał nogi swoje, a dwoma latał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'I wołał jeden do drugiego, mówiąc: Święty, święty, święty, Pan zastępów; pełna jest wszystka ziemia chwały jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'I poruszyły się podwoje u drzwi od głosu wołającego, a dom pełny był dymu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'I rzekłem: Biada mnie! jużem zginął, przeto, żem człowiek splugawionych warg, a mieszkam w pośrodku ludu, który ma splugawione wargi; a iż króla, Pana zastępów, widziały oczy moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'I przyleciał do mnie jeden z Serafinów, mając w ręce swej węgiel rozpalony, który kleszczykami wziął z ołtarza;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'I dotknął się ust moich, a rzekł: Oto się dotknął ten węgiel warg twoich, a odejdzie nieprawość twoja, a grzech twój zgładzony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Potemem słyszał głos Pana mówiącego: Kogoż poślę? a kto nam pójdzie? Tedym rzekł: Otom ja, poślij mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'A on rzekł: Idź, a powiedz ludowi temu: Słuchajcie słuchając, a nie rozumijcie, a widząc patrzajcie, a nie poznawajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Zatwardź serce ludu tego, a uszy jego obciąż, i oczy jego zawrzyj, aby nie widział oczyma swemi, a uszyma swemi nie słyszał, i sercem swem nie zrozumiał, a nie nawrócił się, i nie był uzdrowion.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'A gdym rzekł: Dokądże Panie? A on rzekł: Dokąd nie spustoszeją miasta, tak aby nie było obywatela; i domy, aby nie było w nich człowieka, a ziemia do szczętu nie spustoszeje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Dokąd Pan daleko nie zapędzi wszelkiego człowieka, a nie będzie doskonałe spustoszenie w pośród ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Dokąd jeszcze na nią dziesiąta zguba nie przyjdzie, a dopiero skażona będzie, A wszakże jako one dęby, które są przy bramie Zallechet podporą, tak nasienie święte jest podporą jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'I stało się za dni Achaza, syna Joatamowego, syna Uzyjasza, króla Judzkiego, że przyciągnął Rasyn, król Syryjski, i Facejasz, syn Romelijasza, króla Izraelskiego, pod Jeruzalem, aby walczył przeciw niemu: ale go nie mógł dobyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'I oznajmiono domowi Dawidowemu, mówiąc: Zmówiła się Syryja z Efraimem. Tedy się poruszyło serce jego, i serce ludu jego, jako się poruszają drzewa leśne od wiatru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Tedy rzekł Pan do Izajasza: Wyjdź teraz przeciw Achazowi, ty, i Sear Jasub, syn twój, na koniec rur sadzawki wyższej, na drogę pola farbierzowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'A powiedz mu: Patrz, abyś się nie frasował; nie bój się, a serce twoje niechaj się nie lęka tych dwóch ostatków głowien kurzących się, to jest, zapalczywości gniewu Rasyna z Syryjczykami, i syna Romelijaszowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Przeto, że złą radę uradzili przeciw tobie Syryjczyk, Efraim, i syn Romelijaszowy, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Ciągnijmy przeciwko ziemi Judzkiej, a utrapmy ją leżą, i oderwijmy ją do siebie, a postanówmy króla w pośród niej, syna Tabealowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'Tak mówi Pan Panujący: Nie stanie się, i nie będzie to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Albowiem głową Syryi jest Damaszek, a głową Damaszku Rasyn; a po sześćdziesięciu i pięciu latach będzie potarty Efraim, tak, iż więcej ludem nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Między tem głową Efraimową będzie Samaryja, a głową Samaryi syn Romelijaszowy. Jeźli nie uwierzycie, pewnie się nie ostoicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Nadto jeszcze rzekł Pan do Achaza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Żądaj sobie znaku od Pana, Boga twego, bądź na dole nisko, bądź wysoko w górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Tedy odpowiedział Achaz: Nie będę żądał, ani będę kusił Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'A prorok rzekł: Słuchaj teraz, domie Dawidowy! Małoż się wam zda, uprzykrzać się ludziom, że się uprzykrzacie i Bogu mojemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Przetoż wam sam Pan znak da. Oto panna pocznie i porodzi syna, a nazwie imię jego Immanuel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Masło i miód jeść będzie, ażby umiał odrzucać złe, a obierać dobre. -');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Owszem, pierwej niż będzie umiało to dziecię odrzucać złe i obierać dobre, ziemia, którą się ty brzydzisz, opuszczona będzie od dwóch królów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Ale na cię Pan przywiedzie i na lud twój, i na dom ojca twego, dni, jakich nie było ode dnia, którego odstąpił Efraim od Judy, a to przez króla Assyryjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Albowiem stanie się dnia onego, że zaświśnie Pan na muchy, które są na końcu rzek Egipskich, i na pszczoły, które są w ziemi Assyryjskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'I przyjdą a usiądą wszystkie w dolinach pustych, i w rozpadlinach skalnych, i na wszystkich drzewach urodzajnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Dnia onego ogoli Pan brzytwą najętą przez tych, którzy są za rzeką, to jest (przez króla Assyryjskiego) głowę, i włosy na nogach, także i brodę wszcząt ogoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'I stanie się dnia onego, że ledwie człowiek żywo krówkę, albo dwie owce zachowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'A wszakże dla obfitości mleka, którego nadoi, będzie jadł masło; masło zaiste i miód będzie jadł, ktokolwiek pozostanie w ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Stanie się też onegoż dnia, iż każde miejsce, gdzie było tysiąc winnych macic za tysiąc srebrników, ostem i cierniem porośnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Tedy z strzałami i z łukiem tam chodzić będą; bo ostem i cierniem zarośnie wszystka ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Na wszystkie też góry, które motyką kopane być mogą, nie przyjdzie strach ostu i ciernia; ale będą na pastwisko wołom, i na podeptanie owcom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'I rzekł Pan do mnie: Weźmij sobie księgi wielkie, a napisz na nich pismem człowieczem: Pospiesz się do łupu, pokwap się do korzyści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Tedym wziął sobie za świadków wiernych Uryjasza kapłana, i Zacharyjasza, syna Jeberechyjaszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Wtemem przystąpił do prorokini, która począwszy porodziła syna. I rzekł Pan do mnie: Nazów imię jego: Pospiesz się do łupu, pokwap się do korzyści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Albowiem niżeli będzie umiało to dziecię wołać: Ojcze mój i matko moja, lud króla Assyryjskiego pobierze bogactwa Damaszku, i łupy Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Nadto rzekł jeszcze Pan do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Ponieważ wzgardził lud ten wody Syloe, które cicho płyną, a waseli się z Rasyna, i syna Romelijaszowego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Przetoż oto Pan przywiedzie na nich wody rzeki gwałtownej i wielkiej, to jest króla Assyryjskiego, i wszystkę sławę jego, tak, że wystąpi ze wszystkich strumieni swoich, a wyleje ze wszystkich brzegów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Pociecze i przez ziemię Judzką, wyleje a rozejdzie się, aż do szyi wzbierze; a rozszerzone skrzydła jego napełnią szerokość ziemi twojej, o Immanuelu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Zbierajcie się narody, wszakże potłumione będziecie. Przyjmujcie w uszy wszyscy w dalekiej ziemi; przepaszcie się, wszakże potłumieni będziecie; przepaszcie się, wszakże potłumieni będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Wnijdźcie w radę, a będzie rozerwana; namówcie się, a nie ostoi się; bo Bóg z nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Tak bowiem Pan rzekł do mnie, ująwszy mię za rękę, i dał mi przestrogę, żebym nie chodził drogą ludu tego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Nie mówcie: Sprzysiężenie. Kiedykolwiek ten lud mówi: Sprzysiężenie, nie strachajcie się jako oni, ani się lękajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Pana zastępów samego poświęcajcie; a on niech będzie bojaźnią waszą, i on strachem waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'A będzie wam poświęceniem; ale kamieniem obrażenia i opoką otrącenia obydwom domom Izraelskim, sidłem i siecią obywatelom Jeruzalemskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'I otrąci się wielu ich o nie, upadną i skruszeni będą, usidlą się a pojmani będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Zawiąż to świadectwo, zapieczętuj zakon między uczniami moimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Tedy będę oczekiwał Pana, który skrył oblicze swoje od domu Jakóbowego, i poczekam go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Oto ja i dzieci, które mi dał Pan, są na znaki i na cuda w Izraelu, od Pana zastępów, który mieszka na górze Syon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'A tak jeźliby wam rzekli: Dowiadujcie się od czarowników i od wieszczków, którzy szepcą i markocą, rzeczcie: Izali się nie ma dowiadywać lud u Boga swego? azaż umarłych miasto żywych radzić się ma?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Do zakonu raczej i do świadectwa; ale jeźli nie chcą, niechże mówią według słowa tego, w którem niemasz żadnej zorzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Dlaczego każdy z nich utrapiony i zgłodniały tułaćby się musiał; a będąc zgłodniałym, sam w sobie gniewać się będzie, i złorzeczyć królowi swemu, i Bogu swemu, w górę poglądając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'A gdy na ziemię spojrzy, oto ucisk i ciemność, zaćmienie, bieda, i obaczy, że jest wrażony do ciemności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Ale jednak nie tak zaćmiona będzie ona ziemia, która uciśniona będzie, jako pierwszego czasu, gdy Bóg dotknął ziemię Zabulon, i ziemię Neftalim; ani jako potem, gdy obciążył ku drodze morskiej przy Jordanie Galileę ludną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Bo lud on, który chodzi w ciemności, ujrzy światłość wielką, a tym, którzy mieszkają w ziemi cienia śmierci, światłość świecić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Rozmnożyłeś ten naród, aleś nie uczynił wielkiego wesela; wszakże weselić się będą przed tobą, jako się weselą czasu żniwa, jako się radują, którzy łupy dzielą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Gdyż jarzmo brzemienia jego, a laskę ramienia jego, i pręt poborcy jego złamiesz, jako za dni Madyjańczyków,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Gdzie się wszystka bitwa bojujących z trzaskiem stała, i szaty były we krwi zbroczone, a co się spalić mogło, ogniem spalono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Albowiem dziecię narodziło się nam, a syn dany jest nam; i będzie panowanie na ramieniu jego, a nazwią imię jego: Dziwny, Radny, Bóg mocny, Ojciec wieczności, Książę pokoju;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'A ku rozmnożeniu tego państwa i pokoju, któremu końca nie będzie, usiądzie na stolicy Dawidowej, i na królestwie jego, aż je postanowi i utwierdzi w sądzie i w sprawiedliwości, odtąd aż na wieki. Uczyni to zawisna miłość Pana zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Posłał Pan słowo do Jakóba, a upadło w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'I dowie się wszystek lud Efraim, i mieszkający w Samaryi, którzy w hardości i w wyniosłości serca mówią:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Cegły upadły, ale my ciosanym kamieniem budować będziemy, podrąbano płonne figi, ale my to w cedry odmienimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Aleć Pan wywyższy nieprzyjaciół Rasynowych nadeń, a nieprzyjaciół jego zbierze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Syryjczyków z przodku, a Filistyńczyków z tyłu, i pożrą Izraela całą gębą. A wszakże w tem wszystkiem nie odwróci się zapalczywość jego, ale jeszcze ręka jego będzie wyciągniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Przeto, że się lud ten nie nawraca do tego, który go bije, a Pana zastępów nie szuka:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Dlatego Pan odetnie od Izraela głowę i ogon, gałąź i sitowie, dnia jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, '(Starzec i uczciwy człowiek, ten jest głową, a prorok, który uczy kłamstwa, ten jest ogonem.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Albowiem wodzowie ludu tego są zwodziciele, a którzy się im wodzić dadzą, zginęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Dlatego z młodzieńców jego Pan się nie ucieszy, a nad sierotami jego, i nad wdowami jego nie zmiłuje się; albowiem wszyscy są obłudni i złośliwi, a każde usta mówią sprosność. A wszakże w tem wszystkiem nie odwróci się zapalczywość jego; ale jeszcze ręka jego będzie wyciągniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Albowiem gdy się niepobożność jako ogień roznieci, pożre głóg i ciernie: potem zapali gęstwinę lasu, skąd się rozwieją jako dym na powietrzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Albowiem dla rozgniewania Pana zastępów zaćmi się ziemia, a ten lud będzie jako strawa ognia, i żaden bratu swemu nie przepuści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'A porwieli co po prawej stronie, przecie łaknąć będzie; a będzieli żarł po lewej, przecie się nie nasyci; każdy z nich ciało ramienia swego żreć będzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manases Efraima, a Efraim Manasesa, a obaj społu będą przeciwko Judzie. Wszakże w tem wszystkiem nie odwróci się zapalczywość jego; ale jeszcze ręka jego będzie wyciągniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Biada tym, którzy stanowią prawa niesprawiedliwe! i pisarzom, którzy ucisk na innych spisują!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Aby odpychali ubogiego od sądu, a wydzierali sprawiedliwość ubogich ludu mego; aby wdowy były korzyścią ich, a sierotki łupem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Cóż uczynicie w dzień nawiedzenia, i spustoszenia, które z daleka przyjdzie? do kogoż się ucieczecie o wspomożenie? a gdzie zostawicie sławę waszę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Aby się nie miała między więźniami uniżyć, i między pobitymi upaść. A wszakże w tem wszystkiem nie odwróci się zapalczywość jego; ale jeszcze ręką jego będzie wyciągniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Biada Assurowi, rózdze gniewu mego! chociaż kij rozgniewania mego jest w ręku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Na naród obłudny poślę go, a o ludu zapalczywości mojej przykażę mu, aby brał łup i wydzierał korzyści a położył go na podeptanie, jako błoto na ulicach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Lecz on nie tak będzie mniemał, i serce jego nie tak będzie myślało, ponieważ w sercu swem ułożył, aby wytracił i wykorzenił niemało narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Albowiem rzecze: Izali książęta moi nie są też i królmi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Izali Chalmo nie jest jako Karchemis? Izali Arfat nie jest jako Emat? Izali Samaryja nie jest jako Damaszek?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Jako ręka moja znalazła królestwa bałwańskie, chociaż bałwany ich większe były, niż w Jeruzalemie i w Samaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Izali Jeruzalemowi i bałwanom jego tak nie uczynię, jakom uczynił Samaryi i bałwanom jej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'I stanie się, gdy Pan wykona wszystkę sprawę swoję na górze Syońskiej i w Jeruzalemie, że nawiedzę owoc wyniosłego serca króla Assyryjskiego, i pychę wysokich oczów jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Bo rzecze: W mocy ręki mojej uczyniłem to, i w mądrości mojej; bom był mądry, i odjąłem granice narodów, a skarby ich zabrałem, i wytraciłem obywateli jako mocarz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Owszem ręka moja znalazła majętność narodów jako gniazdo; a jako zbierają jajka, które są opuszczone, takiem ja wszystkę ziemię zebrał, a nie był ktoby skrzydłem ruszył, albo otworzył usta, i coby mruczał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Izali się będzie przechwalała siekiera przeciw temu, który nią rąbie? Izali się będzie wynosiła piła przeciw temu, który nią trze? jakożby się wynosiła rózga przeciw temu, który ją podniósł? jakożby się przechwalał kij, że nie jest drewnem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Przetoż Pan, Pan zastępów, pośle na tłustych jego suchoty, a pod sławą jego z prędka się zapali, jako gwałtowny ogień;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Bo Światłość Izraelowa będzie ogniem, a Święty jego płomieniem, który spali i pożre ciernie jego i oset jego dnia jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Także wspaniałość lasu jego i urodzajnych pól jego, od duszy aż do ciała zniszczy, i stanie się jako chorąży od strachu uciekający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'A pozostałych drzew lasu jego mała liczba będzie, tak, że je i dziecię będzie popisać mogło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'I stanie się dnia onego, że ostatki Izraelskie, i ci, którzy zostali z domu Jakóbowego, nie będą więcej spolegać na tym, co ich bije; ale prawdziwie spolegać będą na Panu, Świętym Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Ostatek nawróci się, ostatek Jakóbowy do Boga mocnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Bo choćby lud twój, o Izraelu! był jako piasek morski, ostatek tylko z niego nawróci się. Wytracenie naznaczone sprawi, że ziemia będzie opływała sprawiedliwością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Wytracenie mówię naznaczone uczyni Pan, Pan zastępów, w pośrodku tej wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Przetoż tak mówi Pan, Pan zastępów: Nie bój się Assyryjczyka, ludu mój! który mieszkasz w Syonie; rózgą ubije cię, a laskę swą podniesie na cię, jako na drodze Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Albowiem po maluczkim czasie skończy się gniew mój przeciwko tobie, a na wygładzenie ich zapalczywość moja powstanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Gdyż bicz nań wzbudzi Pan zastępów, jako porażkę Madyjańczyków na skale Horeb; a jako podniósł rózgę swoję na morze na drodze Egipskiej tak ją nań podniesie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'A dnia onego zdjęte będzie brzemię jego z ramienia twego, i jarzmo jego z szyi twojej; owszem, skażone będzie jarzmo od przytomności pomazanego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Przyciągnie do Ajat, przejdzie przez Migron, w Machmas złoży oręż swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Przejdą bród, w Gieba jako w gospodzie nocować będą; ulęknie się Rama, Gabaa Saulowe uciecze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Podnieś głos twój, córko Gallim! niech słyszą w Lais, o ubogie Anatot!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Ustąpi Madmena; obywatele Gabim zbiorą się do uciekania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Jeszcze przez dzień zastanowiwszy się w Nobie, pogrozi ręką swą górze córki Syońskiej, i pagórkowi Jeruzalemskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Oto Pan, Pan zastępów, okrzesze wszystkę siłę latorośli, a te, którzy są wysokiego wzrostu, podetnie; i będą wysocy poniżeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Gęstwiny także lasów siekiera wytnie, a Liban od wielmożnego upadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Ale wyjdzie rószczka ze pnia Isajego, a latorostka z korzenia jego wyrośnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'I odpocznie na nim Duch Pański, Duch mądrości i rozumu, Duch rady i mocy, Duch umiejętności i bojaźni Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'I będzie czułym w bojaźni Pańskiej, nie będzie według widzenia oczów swoich sądził, ani według słyszenia uszów swoich karał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Ale będzie ubogich sądził w sprawiedliwości, a w prawości będzie karał cichych na ziemi. I uderzy ziemię rózgą ust swoich, a duchem warg swoich zabije niezbożnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Albowiem sprawiedliwość będzie pasem biódr jego, a prawda przepasaniem nerek jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'I będzie mieszkał wilk z barankiem, a lampart z koźlęciem będzie leżał; także cielę i szczenię lwie, i karmne bydła pospołu będą, a małe dziecię rządzić ich będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Krowa i niedźwiedzica społem paść się będą, a płód ich pospołu leżeć będzie, a lew jako wół plewy jeść będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'A dziecię ssące będzie grało nad dziurą żmijową; a to, które odstawione jest, wpuści rękę swoję do dziury bazyliszkowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Nie będą szkodzić ani zabijać na wszystkiej górze mojej świętej; bo ziemia będzie napełniona znajomością Pańską, tak jako morze wodami napełnione jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'I stanie się dnia onego, że się za korzeniem Isajego, który stanie za chorągiew narodom, poganie pytać będą; albowiem odpocznienie jego sławne będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Stanie się też dnia onego, iż Pan powtóre rękę swą przyłoży, aby posiadł ostatek ludu swego, który pozostanie od Assyryjczyków i od Egiptu, i od Patros, i od Chus, i od Elam, i od Senaar, i od Emat, i od wysep morskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'I podniesie chorągwie między poganami, a zgromadzi wygnanych z Izraela, a rozproszonych z Judy zbierze ze czterech stron ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'I ustanie nienawiść Efraimowa, a nieprzyjaciele Judowi wykorzenieni będą. Efraim nie będzie nienawidził Judy, a Juda nie będzie trapił Efraima;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Ale polecą na ramię Filistynów na zachód, a pospołu łupić będą narody na wschód słońca; na Edomczyków i Moabczyków ściągną rękę swą, a synowie Amonowi posłuszni im będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Zniszczy też Pan odnogę morza Egipskiego, i podniesie rękę swoję przeciwko rzece mocnym wiatrem swym, a rozdzieli ją na siedm potoków, i sprawi to, że ją w obuwiu przechodzić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'A będzie drogą bitą ostatkowi ludu jego, który pozostanie od Assyryjczyków, jako była Izraelowi dnia onego, kiedy wychodził z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'I rzeczesz dnia onego: Wysławiać cię będę, Panie! przeto, że będąc rozgniewany na mię, odwróciłeś zapalczywość gniewu twego, a ucieszyłeś mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Oto Bóg zbawienie moje, ufać będę, a nie ulęknę się; albowiem Pan, Bóg mój, jest mocą moją, i pieśnią moją, i zbawieniem mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'I będziecie z radością czerpać wody ze zdrojów tegoż zbawienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'I rzeczecie dnia onego: Wysławiajcie Pana wzywajcie imienia jego, opowiadajcie między narodami sprawy jego, przypominajcie, że wysokie jest imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Śpiewajcie Panu, albowiem wielkie rzeczy uczynił; niech to będzie wiadomo po wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Wykrzykaj a śpiewaj, obywatelko Syońska! albowiem wielki jest w pośrodku ciebie Święty Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Brzemię Babilonu, które widział Izajasz, syn Amosowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Na górze wysokiej podnieście chorągiew, podwyżcie głos do nich, dajcie znać ręką, a niechaj wnijdą w bramy książęce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Jam przykazał poświęconym moim; przyzwałem też i mocarzów moich do wykonania gniewu mego, którzy się weselą z wywyższenia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Głos zgrai na górach, jako ludu gęstego, głos i dźwięk królestw i narodów zgromadzonych: Pan zastępów spisuje wojsko na wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Ciągną z ziemi dalekiej, od kończyn niebios, mianowicie Pan i naczynia popędliwości jego, aby zburzył wszystkę ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Kwilcie! albowiem blisko jest dzień Pański, który przyjdzie jako spustoszenie od Wszechmocnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Dlatego wszelkie ręce osłabieją, a wszelkie serce człowiecze stopnieje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'I będą przestraszeni, uciski i trapienia ogarną ich, jako rodząca boleć będą. Każdy nad bliźnim swoim zdumieje się, oblicza ich płomieniowi podobne będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Oto dzień Pański srogi idzie w zapalczywości i popędliwości gniewu, aby obrócił tę ziemię w pustynię, a grzeszników jej aby z niej wygładził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Bo gwiazdy niebieskie i planety ich nie dopuszczą świecić światłu swemu; zaćmi się słońce, gdy wschodzić będzie, a miesiąc nie wyda światła swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'I nawiedzę na okręgu ziemskim złość, a na niezbożnych nieprawości ich; i uczynię koniec pysze hardych, a hardość okrutników zniżę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Męża droższym uczynię nad szczere złoto, a człowieka nad złoto z Ofir.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Dlatego zatrząsnę niebem, a poruszy się ziemia z miejsca swego w rozgniewaniu Pana zastępów, i w dzień popędliwego gniewu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'I będzie jako łani przepłoszona, i jako trzoda, której nie ma kto zgromadzić; każdy się do ludu swego obróci, i każdy do ziemi swojej uciecze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Ktokolwiek znaleziony będzie, przebity będzie; a każdy, którzy się kolwiek do nich przyłączy, od miecza polęże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Nadto i dziatki ich roztrącane będą przed oczyma ich; domy ich splundrowane będą, a żony ich pogwałcone będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Oto Ja pobudzę przeciwko nim Medów, którzy o srebro nie będą dbali, a w złocie nie będą się kochali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Ale z łuków dziatki postrzelają, a nad płodem żywota nie zmiłują się, oko ich synom nie przepuści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'I będzie Babilon, który był ozdobą królestw i sławą zacności Chaldejczyków, jako podwrócenie od Boga Sodomy i Gomory.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Nie będą się w nim osadzać na wieki, ani mieszkać od narodu aż do narodu; ani tam rozbije namiotu Arabczyk, ani tam pasterze z stadami odpoczywać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Ale tam zwierz odpoczywać będzie, a domy ich bestyjami napełnione będą; i będą tam mieszkać sowy, a pokusy tam skakać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'I będą się sobie ozywać straszne potwory na pałacach ich, a smoki na zamkach rozkosznych. A blisko tego że przyjdzie czas jego, a dni jego nie odwloką się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Albowiem zlituje się Pan nad Jakóbem, a obierze zasię Izraela, i da im odpocznąć w ziemi ich; a przyłączy się do nich cudzoziemiec, i przystaną do domu Jakóbowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Bo wezmą z sobą narody, i przywiodą je do miejsca swego; i weźmie je sobie dom Izraelski w ziemi Pańskiej w dziedzictwo za sługi i za służebnice; i imać będą tych, którzy ich imali, a panować będą nad tymi, którzy ich ciemiężyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'A dnia onego, któregoć Pan da odpocznienie od pracy twojej i od strachu twego, i od niewoli ciężkiej, w którąś był podbity,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Weźmiesz tę przypowieść przeciw królowi Babilońskiemu, i rzeczesz: O jako ustał poborca, ustał podatek złota!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Pan złamał kij niezbożnych, i rózgę panujących;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Tego, który ludzi bijał w zapalczywości biciem ustawicznem, panował w gniewie nad narodami bez litości dręczonemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Teraz odpoczywa i jest w pokoju wszystka ziemia, wszyscy głośno śpiewają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'I jodły się weselą nad tobą, i cedry Libańskie, mówiąc: Od tego czasu, jakoś ty poległ, nie powstał, ktoby nas podcinał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'I piekło ze spodku wzruszyło się dla ciebie, aby tobie przychodzącemu zaszło; wzbudziło dla ciebie umarłych, wszystkich książąt ziemi; rozkazało powstać z stolic swoich i wszystkim królom narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Ci wszyscy odpowiadając mówią do ciebie: I tyś zemdlony jako i my, a stałeś się nam podobnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Strącona jest do piekła, pycha twoja i dźwięk muzyki twojej; podesłanoć mole, a robaki cię przykrywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Jakoż to, żeś spadł z nieba, o jutrzenko! która wschodzisz rano? powalonyś aż na ziemię, któryś wątlił narody!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Wszakieś ty mawiał w sercu swem: Wstąpię na niebo, nad gwiazdy Boże wywyższę stolicę moję, a usiądę na górze zgromadzenia, na stronach północnych:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Wstąpię na wysokość obłoków, będę równy Najwyższemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Wszakże strącon jesteś aż do piekła, w głębokość dołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Którzy cię ujrzą, za tobą się oglądać, i przypatrywać ci się będą mówiąc: Onże to mąż, który trwożył ziemię? który trząsał królestwami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Który obrócił okrąg świata w pustynię, a miasta jego poburzył, a więźniom swoim nie otwarzał ciemnicy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Wszyscy królowie narodów, cokolwiek ich było, pochowani są w sławie, każdy w domu swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Aleś ty odrzucony od grobu swego, jako latorośl obrzydła, jako szata zabitych, których poprzebijano mieczem, którzy zstępują do grobu kamienistego, jako ścierw podeptany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Nie będzisz miał uczęstnictwa z nimi w pogrzebie; boś ziemię twoję pokaził, i lud swój pomordował; albowiem nasienie złośników nie będzie wspominane na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Gotujcie synów jego na zamordowanie dla nieprawości ojców ich, aby nie powstali, i nie odziedziczyli ziemi, nie napełnili miastami okręgu ziemskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Bo powstanę przeciwko nim, mówi Pan zastępów, a wykorzenię imię Babilonu, i ostatki jego, tak syna jako i wnuka, mówi Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'I uczynię je osiadłością bąków, i kałużami wód, i wymiotę go miotłą spustoszenia, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Przysiągł Pan zastępów, mówiąc: Zaiste, jakom umyślił, tak będzie, a jakom uradził, tak się stanie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Iż potrę Assyryjczyka w ziemi mojej, a na górach moich podepczę go; a odejdzie od nich jarzmo jego, i brzemię jego z ramienia jego zdjęte będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Tać jest rada uradzona przeciw onej wszystkiej ziemi; a tać jest ręka wyciągniona przeciwko tym wszystkim narodom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'A ponieważ Pan zastępów postanowił, któż to wzruszy? a rękę jego wyciągnioną któż odwróci?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Roku, którego umarł król Achaz, stało się to proroctwo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Nie raduj się, ty wszystka ziemio Filistyńska! iż złamana jest rózga tego, który cię bił; bo z korzenia wężowego wynijdzie bazyliszek, a płód jego będzie smok ognisty latający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'I będą się paść pierworodni nędznych, a ubodzy bezpiecznie odpoczną; ale korzeń twój głodem wygubię a ostatki twoje wybiję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Kwilże bramo! krzycz miasto! jużeś się rozpłynęła wszystka ty ziemio Filistyńska; bo od północy ogień przyjdzie, a nie będzie, coby stronił od pocztów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'A cóż odpowiedzą posłom narodu? To, że Pan ugruntował Syon, a do niego się uciekać będą ubodzy ludu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Brzemię Moabczyków. Ponieważ w nocy zburzone i spustoszone będzie Ar Moabskie, ponieważ w nocy zburzone i spustoszone będzie Kir Moabskie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Wstąpi do Bait, i do Dybon, i do Bamot z płaczem; nad Nebo, i nad Medebą Moab kwilić będzie; na każdej głowie jego będzie łysina, i każda broda ogolona będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Na ulicach jego przepaszą się worem; na dachach jego i na rynkach jego każdy kwilić będzie, wracajac się z płaczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'I będzie wołał Hesebon i Eleale, aż w Jahas słyszany będzie głos ich; owszem i zbrojni Moabscy narzekać będą, a dusza każdego z nich porzewniać sobie będzie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Serce moje ryczy nad Moabem i nad twierdzami jego, aż słyszeć w Zoar, jako jałowica trzyletnia; bo drogą Luchytską z płaczem pójdzie, a na drodze Choronaim krzyk jako w porażce podniosą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Przeto, że wody Nymrym zginą, że poschną zioła, uwiędnie trawa, a nic nie będzie zielonego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Przetoż, cokolwiek sobie zachowali, i majętności ich, odniosę do potoku Arabskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Bo obejdzie krzyk granicę Moabską, aż do Eglaim narzekanie jego, i aż do Beer Elim kwilenie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Ponieważ i wody Dymońskie krwi pełne będą: bo przyłożę Dymonowi przydatki, a na tych, którzyby uszli z Moabczyków, poślę lwy, i na ostatki w tej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Poślijcie baranki Panującemu nad ziemią, od skały aż do pustyni, do góry córki Syońskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Bo inaczej Moab będzie jako ptak tułający się, i z gniazda wypłoszony; tak będą córki Moabskie przy brodach Arnon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Wnijdź w radę, uczyń sąd, wystaw cień swój w pośród południa jako noc, skryj wygnańców, a tułającego się nie wydawaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Niech mieszkają u ciebie wygnańcy moi. O Moabie! bądź ich ochroną przed pustoszycielem; albowiem ustanie gwałtownik, ustanie pustoszyciel, a wygładzony będzie z ziemi ten, który innych depcze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'I będzie zgotowana stolica w miłosierdziu, a usiądzie na niej w prawdzie w przybytku Dawidowym ten, któryby sądził i szukał sądu, a czynił prędką sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Lecz słyszeliśmy o pysze Moabowej, że bardzo pyszny jest, o hardości, i wyniosłości jego, i o zapalczywości jego; wszakże nie przyjdą do skutku zamysły jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Przetoż narzekać będzie Moabczyk przed Moabczykiem, wszyscy kwilić będą; nad gruntami miasta Kirchareset wzdychać będą, mówiąc: Jużci są skażone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Owszem i pola Hesebońskie spustoszone są, i winna macica Sabama. Panowie narodów potarli najwyborniejsze macice jego, które aż do Jazer sięgały, a szerzyły się po puszczy; latorośli jego rozłożyły się, i przesięgły morze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Przetoż płaczę dla płaczu Jazerczyków, i dla winnicy Sabama oblewam się łzami mojemi, o Hesebonie, i Eleale! bo na letni owoc twój, i na żniwo twoje przypadł okrzyk wojenny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'I ustało wesele i radość nad polem urodzajnem; na winnicach nie śpiewają ani wykrzykają; wina w prasach nie tłoczy ten, który je tłoczył; i jać wykrzykania poprzestaję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Dlatego brzmią wnętrzności moje nad Moabem jako lutnia, a trzewa moje nad Kircharesem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'I stanie się, gdy się pokaże, że się spracował Moab nad wyżynami, tedy wnijdzie do świątnicy swojej, aby się modlił, ale nic nie sprawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Toć jest słowo, które Pan z dawna powiedział o Moabie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Ale teraz powiedział Pan, mówiąc: Po trzech latach, jakie są lata najemnicze, sława Moabowa zelżona będzie ze wszystką zgrają jego wielką, a ostatek jego lichy, maluczki i mdły będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Brzemię Damaszku. Oto Damaszek przestanie być miastem, a stanie się kupą rumu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Miasta Aroer opuszczone będą; dla trzód będą, które tam odpoczywać będą, a nie będzie, ktoby je straszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'I ustanie obrona od Efraima, i królestwo od Damaszku, i od ostatka Syryjczyków, i jako sława synów Izraelskich zniszczeją, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'I stanie się dnia onego, że umniejszona będzie sława Jakóbowa, a tłustość ciała jego schudnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Albowiem Azur będzie jako ten, który w żniwa zboże zbiera, a ramię jego żnie kłosy; i będzie jako ten, co zbiera kłosy w dolinie Refaim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Wszakże zostaną na nim pominione grona, jako na otrzęśnionej oliwie dwie albo trzy oliwiki zostaną na wierzchu drzewa, a cztery albo pięć na rodzajnych gałęziach jego, mówi Pan, Bóg Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Dnia onego obejrzy się człowiek na stworzyciela swego, a oczy jego na Świętego Izraelskiego poglądać będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'A nie obejrzy się na ołtarze, sprawę rąk swoich, ani na to, co uczyniły palce jego, patrzyć będzie, ani na gaje poświęcone, ani na obrazy słoneczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'Dnia onego miasta mocy jego będą opuszczone, jako chrościnka i rószczka, które opuszczone będą od synów Izraelskich, i będziesz ziemią spustoszoną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Boś zapomniała na Boga zbawienia swego, i na skałę mocy twojej nie wspominałaś. Przetoż choć szczepy rozkoszne szczepisz, i latorośli winne obce sadzisz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Czasu szczepienia twego szczepy aby rosły, opatrujesz; nawet tegoż poranku, co siejesz, aby się puściło, starasz się: wszakże w dzień pożytku gromadno boleść i rozpacz żąć będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Biada zgrai ludu wielkiego, którzy huczą jako szum morski, i zgiełkowi narodów, które szumią jako szum wód gwałtownych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Narodom, które szumią jako szum wód wielkich; bo je Pan sfuka, i uciekną daleko, i gonione będą od wiatru jako plewy po wierzchach gór, a jako wiecheć od wichru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Bo czasu wieczornego nastąpi trwoga, a niż poranek przyjdzie, alić go niemasz. Tenci jest dział tych, którzy nas pustoszą, i los tych, którzy nas plundrują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Biada ziemi, którą zaćmiają skrzydła, która jest przy rzekach ziemi Murzyńskiej!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'Która posyła posłów przez morze po wodach w łodziach z sitowia, mówiąc: Idźcie, posłowie prędcy! do narodu rozszarpanego i splundrowanego, do ludu strasznego z dawna i dotąd, do narodu do szczętu podeptanego, którego ziemię rzeki rozerwały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Wszyscy obywatele świata i mieszkający na ziemi ujrzycie, gdy będzie chorągiew podniesiona na górach, i gdy w trąby trąbić będą, usłyszycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Albowiem tak mówi Pan do mnie: Uspokoję się, a przypatrywać się będę z przybytku mojego, a będę jako ciepło jasne po deszczu, a jako obłok wypuszczający rosę gorącości żniwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Bo przed zbieraniem wina, gdy się puści pączki, a kwiat wyda grono cierpkie jeszcze rosnące, tedy oberznie latorostki nożami, a gałęzie odejmie i obetnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'I będą zostawione wszystkie wespół ptastwu na górach i zwierzętom ziemskim; i będzie na nich przez lato ptastwo, a wszelaki zwierz ziemski na nich zimować będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Czasu onego przyniesiony będzie dar Panu zastępów od ludu rozszarpanego i splundrowanego, od ludu strasznego z dawna i dotąd, od narodu do szczętu podeptanego, którego ziemię rzeki rozrywały; a przeniesiony będzie na miejsce imienia Pana zastępów, na górze Syon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Brzemię Egiptu. Oto Pan jedzie na obłoku lekkim, i przyciągnie do Egiptu, a poruszą się bałwany Egipskie przed oblicznością jego, a serce Egipczan rozpłynie się w pośrodku ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Bo spuszczę Egipczan z Egipczanami, tak, iż walczyć będzie każdy przeciw bratu swemu, i każdy przeciw przyjacielowi swemu, miasto przeciwko miastu, królestwo przeciwko królestwu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'I zniszczony będzie duch w Egipczanach, a radę ich w niwecz obrócę; i będą się radzić bałwanów i wieszczków, i czarowników, i wróżków swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'I podam Egipt w ręce panów okrutnych, a król srogi panować będzie nad nimi, mówi Pan, Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'I zginą wody z morza, a rzeka osiąknie i wyschnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'I pójdą na wstecz rzeki, opadną i powysychają potoki groblami ujęte, trzcina i sitowie powiędnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Trawa około rzeki i przy brzegu jej, i wszelakie siewy przy potokach poschną, i zniszczeją i zginą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'I będą się smucić rybitwi, i żałośni będą wszyscy, którzy zarzucają do rzeki wędę; a którzy rozciągają sieci po wodzie, do nędzy przyjdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Także zawstydzą się ci, którzy tkają rzeczy lniane, i subtelne, i którzy siatki robią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Albowiem sieci jego zepsowane będą, i wszyscy, którzy robią sadzawki dla ryb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Zaisteć zgłupieli książęta Soańscy, mądrych radców Faraonowych rada zgłupiała. Jakoż rzeczecie do Faraona: Jam jest syn mądrych, a syn królów starodawnych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Gdzież teraz są mędrkowie twoi? niech ci teraz oznajmią, jeźli wiedzą, co uradził Pan zastępów przeciw Egiptowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Zgłupieli książęta Soańscy, zwiedzieni są książęta Nofscy; zwiedli Egipt przedniejsi w pokoleniu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Pan puścił między nich ducha wichrowatego, i sprawi to, że pobłądzi Egipt w każdej sprawie swojej, tak jako błądzi pijany przy zwracaniu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'I nie będzie żadna sprawa w Egipcie, którąby uczynić miała głowa albo ogon, gałąź albo sitowie');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Dnia onego będzie Egipt podobny niewiastom; bo się lękać i strachać będzie przed podniesieniem ręki Pana zastępów, którą on podniesie przeciwko niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'I będzie ziemia Judzka Egiptowi na postrach; każdy, kto wspomni na nią, będzie się lękał dla rady Pana zastępów, którą postanowił o nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Dnia onego będzie pięć miast w ziemi Egipskiej, mówiących językiem Chananejskim, a przysięgających przez Pana zastępów; lecz jedno z nich miastem spustoszenia nazwane będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'Dnia onego stanie ołtarz Pański w pośród ziemi Egipskiej, a słup wystawiony będzie Panu przy granicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'A będzie na znak i na świadectwo Panu zastępów w ziemi Egipskiej. A gdy zawołają do Pana dla tych, którzy ich ciemiężyli, tedy im pośle wybawiciela i książęcia, i wybawi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'I będzie Pan w Egipcie poznany, bo poznają Pana Egipczanie dnia onego, a będą go czcić ofiarami i darami, i poślubią śluby Panu, a wypełnią je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'A tak uderzy Pan Egipt, aby go zbiwszy uzdrowił go; bo się nawrócą do Pana, a on się im da ubłagać, i uzdrowi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'Dnia onego będzie gościniec z Egiptu do Assyryi, i będą chodzić Assyryjczycy do Egiptu, a Egipczanie do Assyryi, i będą służyć Panu Egipczanie z Assyryjczykami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Dnia onego będzie Izrael jako trzeci między Egipczanem i Assyryjczykiem, a błogosławieństwo będzie w pośrodku ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Albowiem będzie im błogosławił Pan zastępów, mówiąc: Błogosławiony lud mój Egipski, a sprawą rąk moich Assyryjczykowie a Izrael dziedzictwo moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Roku, którego Tartan przyciągnął do Azotu, posłany będąc od Sargona, króla Assyryjskiego, i walczył przeciw Azotowi, i dobył go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'Onegoż czasu rzekł Pan przez Izajasza, syna Amosowego, mówiąc: Idź, a rozwiąż wór z biódr twoich, a bóty twoje zzuj z nóg twoich; i uczynił tak, i chodził nago i boso.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'I rzekł Pan: Jako chodzi sługa mój Izajasz nago i boso, na znak i na cud tego, co się ma stać trzeciego roku Egiptowi i Murzyńskiej ziemi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'Tak powiedzie król Assyryjski więźniów Egipskich, i pojmanych Murzyńskich, młodych i starych, nagich i bosych, z obnażonemi zadkami na hańbę Egipczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'I przelękną się, i wstydzić się będą za Murzynów, na których się oglądali, i za Egipczanów, z których się chlubili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Tedy rzecze dnia onego obywatel tej wyspy: Oto toć jest ucieczka nasza, do którejśmy uciekali o pomoc, abyśmy wyswobodzeni byli z mocy króla Assyryjskiego; jakożbyśmy tedy ujść mogli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Brzemię pustego morza. Jako wicher na południe bieży, tak przyjdzie z puszczy, z ziemi strasznej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Widzenie srogie jest mi okazane. Przewrotny przewrotność broi, a pustoszyciel pustoszy. Przyciągnijże, Elamie! Oblęż, Medzie! Babilon; wszelkiemu wzdychaniu jego koniec uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Dlatego napełnione są biodra moje boleścią, a ucisk ogarnął mię, jako ucisk rodzącą. Skrzywiłem się słysząc, a strwożyłem się widząc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Ulękło się serce moje, strach mię ogarnął; noc rozkoszy moich obróciła mi się w lękanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Przygotuj stół; niech straż na straży będzie; jedz, pij; wstańcie książęta, smarujcie tarcze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Albowiem tak mi rzekł Pan: Idź, postaw stróża, któryby powiedział, cokolwiek ujrzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'I ujrzał wozy, i dwa rzędy jezdnych; wozy, które osły, i wozy, które wielbłądy ciągnęły: i przypatrywał się im z wielką bardzo pilnością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Tedy zawołał jako lew: Panie mój! jać stoję na straży ustawicznie we dnie; nawet na straży mojej staję na każdą noc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, '(A oto wtem przyjechali mężowie na wozach, i jazda dwoma rzędami.) I zawołał strażnik, a rzekł: Upadł, upadł Babilon, i wszystkie ryte obrazy bogów jego pokruszone o ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Babilon jest gumno moje, i zboże bojewiska mego. Com słyszał od Pana zastępów, Boga Izraelskiego, tom wam opowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Brzemię Dumy. Woła na mię ktoś z Seiru: Hej, stróżu! co się stało w nocy? Stróżu! co się stało w nocy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Rzekł stróż: Przyszedł poranek, także i noc. Chcecieli szukać, szukajcie, nawróćcie się a przyjdźcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Brzemię na Arabiję. Po lasach Arabii noclegi miewać będziecie, o podróżni Dedańscy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Niech zabieżą pragnącemu, niosąc wodę obywatele ziemi Temańskiej; z chlebem jego niech wynijdą przeciw uciekającemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Bo przed mieczami uciekać będą, przed mieczem dobytym, przed łukiem napiętym, przed ciężkością bitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Gdyż tak rzekł Pan do mnie: Że po roku, jaki jest rok najemniczy, ustanie wszystka sława Kedar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'A ostatek pocztu strzelców mężnych synów Kedar będzie umniejszony; albowiem to Pan Bóg Izraelski mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Brzemię doliny widzenia. Cóż ci się stało, żeś wszystka na dachy wystąpiła?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Miasto pełne wrzasku, i zgiełku, miasto weselące się! Pobici twoi nie są pobici mieczem, ani zginęli w bitwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Wszyscy książęta twoi naporząd się rozpierzchnęli, od strzelców powiązani są wespół, i ci, którzy z daleka uciekają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Dlategom rzekł: Odstąpcie odemnie, abym gorzko płakał; nie kwapcie się, cieszyć mię w spustoszeniu córki ludu mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Albowiem to jest dzień ucisku i podeptania, i zamięszania od Pana, Pana zastępów, w dolinie widzenia, dzień burzenia murów, i wołania na góry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Elam też wziął sajdak z wozami ludu wojennego, a Kir okazał tarczę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'I stało się, że wyborne doliny twoje napełnione były wozami, a jezdni się potężnie zaszańcowali u bramy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'I odkryta była zasłona Judowa; a poglądałeś dnia onego na zbrojownię w domu lasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'I poglądaliście na rozwaliny miasta Dawidowego, bo ich wiele było; i zgromadziły się wody sadzawki dolnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Także policzyliście domy w Jeruzalemie, a rozwaliliście domy na oprawę murów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Uczyniliście też przekop między dwoma murami, dla wód stawu starego, a nie oglądaliście się na tego, co go sprawił, a tego, który go zdawna zbudował, nie widzieliście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Nadto, gdy wołał Pan, Pan zastępów, dnia onego do płaczu i do narzekania, i do obłysienia się, i do przepasania się worem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'A oto radość i wesele wasze, zabijać woły, i bić owce, a jedząc mięso, i pijąc wino, mówić: Jedzmy, pijmy, bo jutro pomrzemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Aleć to doszło uszów moich, mówi Pan zastępów. Przetoż wam ta nieprawość nie będzie odpuszczona; aż pomrzecie, mówi Pan, Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Tak mówi Pan, Pan zastępów: Idź, wnijdź do tego podskarbiego, do Sobny, który jest przełożonym w domu, i rzecz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Co ty tu masz? albo kogo tu masz, żeś tu sobie wykował grób? Wykowałeś sobie na wysokiem miejscu grób swój, a wystawiłeś na skale przybytek swój?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Oto Pan, który cię przykrył jako zacnego męża, a który cię kosztownie przyodział,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Prędko cię zatoczy jako kulę do ziemi szerokiej i przestronnej; tam umrzesz, tam i wozy sławy twojej zginą, o hańbo domu Pana swego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'A tak wypędzę cię z stanowiska twego, a z urzędu twego złożę cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'A dnia onego przyzwię sługę swego Elijakima, syna Helkijaszowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'I oblekę go w szatę twoję, i pasem twoim potwierdzę go, panowanie też twoje dam w rękę jego; i będzie za ojca obywatelom Jeruzalemskim, i domowi Judzkiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'I położę klucz domu Dawidowego na ramieniu jego; gdy otworzy, nikt nie zawrze, a gdy zawrze, nikt nie otworzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'I wbiję go jako gwóźdź na miejscu pewnem, a będzie stolicą chwały domu ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'A zawiśnie na nim wszystka sława domu ojca jego, synowie i córki, i wszystko naczynie by najmniejsze, od naczynia, z którego piją, aż do każdego naczynia winnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Dnia onego, mówi Pan zastępów, będzie wyjęty gwóźdź, który był wbity na miejscu pewnem, a będzie przycięty i upadnie; odcięte będzie i brzemię, które jest na nim; bo Pan mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Brzemię Tyru. Kwilcie okręty morskie! albowiem zburzony jest, tak, iż niemasz ani domu, ani ktoby przychodził z ziemi Cytym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'To mi o nich objawiono. Umilknijcież, obywatele wyspy! którą kupcy Sydońscy pływając przez morze napełniali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'A którego dochody na wielkich wodach, nasienie Sychor, żniwo jego dochód z rzeki, a w którym był skład narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Zawstydź się, Sydonie! bo rzekło morze, moc morska, mówiąc: Nie pracuję w porodzeniu, i nie rodzą, i nie wychowuję młodzieńców, ani odchowuję panien.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Jako nad powieścią o Egipcie, tak będą żałośni o Tyrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Przeprawcie się przez morze, kwilcie obywatele wyspy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Toż to jest miasto wasze weselące się? Jego starożytność jestci ode dni dawnych; ale go zawiodą nogi jego na daleką wędrówkę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Któż to postanowił o Tyrze, który koronuje insze? którego kupcy są książętami, a kramarze jego sławnymi na ziemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Pan zastępów postanowił to, aby ohydził pychę wszelkiej sławy, a żeby do zniewagi przywiódł wszystkich zacnych na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Nawróć się do ziemi swej, jako rzeka, o córko morska; niemaszci tam więcej pasa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Rękę swoję wyciągnął na morze, zatrwożył królestwa. Pan rozkazał o Chanaanie, aby zburzone były twierdze jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'I rzekł: Już się nie będziesz więcej weseliła, ty zgwałcona panno, córko Syońska! Powstań, przepraw się do Cytym; lecz i tam nie będziesz miała odpoczynku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Oto ziemia Chaldejska, ten lud nie był ludem. Assyryjczyk założył ją dla obywateli pustyń, którzy wysławili zamki jej, pobudowali pałace jej; ale on ją w gruz obrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Kwilcie okręty morskie! albowiem zburzona jest twierdza wasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'I stanie się dnia onego, że w zapamiętaniu będzie Tyr przez siedmdziesiąt lat, przez wiek króla jednego. A po siedmdziesięciu latach Tyr znowu będzie miał piosnkę, jako piosnkę nierządnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Weźmij lutnię, obchodź miasto, o nierządnico w zapomnienie podana! graj dobrze, długo śpiewaj, abyś na pamięć przyszła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'I stanie się po wyjściu siedmdziesięciu lat, że Tyr Pan nawiedzi; ale się on zaś wróci do nierządniczego zysku swego, i będzie nierząd płodził ze wszystkiemi królestwami ziemi, na obliczu ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Wszakże kupiectwo jego, i zysk jego będzie poświęcony Panu. Do skarbu odłożony, i schowany nie będzie; ale tym, którzy mieszkają przed Panem, pożyteczne będzie kupiectwo jego, aby jedli do sytości, a mieli odzienie dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Oto Pan obnaży ziemię, i spustoszy ją, i przemieni oblicze jej, a rozproszy obywateli jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'I będzie jako lud pospolity tak i książę; jako sługa, tak pan jego; jako dziewka, tak pani jej; jako kupujący, tak sprzedawający; jako pożyczający, tak i ten, co u drugiego pożycza; jako lichwiarz, tak ten, co lichwę daje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Wielce obnażona będzie ziemia, i bardzo złupiona; albowiem Pan mówił to słowo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Płakać będzie i upadnie ziemia, zwątleje i obali się okrąg ziemski; zemdleją wysokie narody ziemskie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Przeto, że ta ziemia splugawiona jest pod obywatelami swoimi; albowiem przestąpili prawa, odmienili ustawy, wzruszyli przymierze wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Dla tego przeklęstwo pożre ziemię, a zniszczeją obywatele jej; dlatego popaleni będą obywatele ziemi, a mało ludzi zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Smucić się będzie moszcz, uwiędnie winna macica, wzdychać będą wszyscy wesołego serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Ustanie wesele bębnów, ustanie wykrzykanie weselących się, ucichnie wesele cytry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Nie będą pić wina z śpiewaniem; gorzki będzie napój mocny pijącym go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Starte będzie miasto próżności; każdy dom zawarty będzie, aby do niego nie wchodzono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Narzekanie będzie na ulicach dla wina; zaćmione będzie wszelkie wesele, a przeniesie się radość ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Spustoszenie w mieście zostanie, a bramy zburzone będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Albowiem tak będzie w pośród ziemi, w pośrodku narodów, jako gdy otrzęsą oliwy, i jako bywa z gronami, gdy się dokona zbieranie wina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Ci podniosą głos swój, wykrzykać będą, w zacności Pańskiej wykrzykać będą, i przy morzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Przetoż w dolinach wysławiajcie Pana, na wyspach morskich imię Pana,Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Od kończyn ziemi słyszymy piosnkę o sławie sprawiedliwego. Alem ja rzekł: Wychudłem, wychudłem, biada mnie! Przewrotni przewrotność broją, przewrotność, mówię, bez wszelkiego wstydu broją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Strach, i dół, i sidło przyjdzie na cię, który mieszkasz na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'I stanie się, że kto uciecze przed wieścią strachu, wpadnie w dół, a kto wylizie z dołu, pojmany będzie sidłem; bo upusty z wysokości otworzone będą a zatrząsną się grunty ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Rozstępując rozstąpi się ziemia; rozsiadając rozsiądzie się ziemia; poruszając poruszy się ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Chwiejąc chwiać się będzie ziemia jako pijany a przeniesiona będzie jako budka; bo ją obciąży nieprawość jej, i upadnie, a więcej nie powstanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'A dnia onego nawiedzi Pan wojsko wysokie na wysokości, także i królów ziemskich na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'I będą zgromadzeni, jako zgromadzeni bywają więźniowie do ciemnicy, a będą zamknieni w tarasie; po wielu, mówię, dniach, nawiedzeni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'I zasromi się miesiąc, a zawstydzi się słońce, gdy królować będzie Pan zastępów, na górze Syońskiej, i w Jeruzalemie, i przed starcami swymi w wielkiej sławie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Panie! tyś Bóg mój, wywyższać cię będę i wysławiać będę imię twoje, boś uczynił rzeczy dziwne; rady twe, z dawna postanowione, są wierną prawdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Albowiemeś miasta obrócił w mogiłę; miasto obronne w rozwaliny; pałace cudzoziemców, aby nie były miastem, i aby nie były znowu na wieki budowane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Dlatego cię wielbić będzie lud możny; miasta narodów srogich ciebie się bać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Albowiemeś ty był twierdzą ubogiemu, zamkiem nędznemu w ucisku jego, ucieczką przed powodzią, zasłoną przed gorącem, gdyż wściekłość okrutników była jako powódź podwracająca ścianę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Huk cudzoziemców potłumiłeś, jako gorącość w suszę; jako gorącość cieniem obłoku, tak okrucieństwo okrutników potłumione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'I sprawi Pan zastępów na wszystkie narody na tej górze ucztę z rzeczy tłustych, ucztę z wystałego wina, z rzeczy tłustych, szpik w sobie mających, z wina wystałego i czystego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'I skazi na tej górze zasłonę, która zasłania wszystkich ludzi, i przykrycie, którem są przykryte wszystkie narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Połknie śmierć w zwycięstwie, a Pan panujący otrze łzę z każdego oblicza, i pohańbienie ludu swego odejmie ze wszystkiej ziemi; bo Pan mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'I rzecze dnia onego lud Pański: Oto Bóg nasz ten jest; oczekiwaliśmy go, i wybawił nas. Tenci jest Pan, któregośmy oczekiwali; weselić i radować się będziemy w zbawieniu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Albowiem na tej górze odpocznie ręka Pańska, a Moab podeptany od niego będzie, jako plewa w gnój wdeptana bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'I wyciągnie ręce swoje w pośród jego, jako je wyciąga pływacz ku pływaniu, a poniży wyniosłość jego łokciami rąk swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'A tak obronę i wysokość murów twoich pochyli, poniży i powali na ziemię aż do prochu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Dnia onego śpiewana będzie ta pieśń w ziemi Judzkiej: Mamy miasto obronne, Bóg zbawieniem opatrzył mury i baszty jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Otwórzcie bramy, a niech wnijdzie naród sprawiedliwy, który strzeże prawdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Człowieka spolegającego na tobie zachowywasz w pokoju, w pokoju mówię: bo w tobie ufa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Miejcie nadzieję w Panu aż na wieki; boć w Panu, w Panu jest skała wieczna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Ale poniża mieszkającego na wysokości; miasto wyniosłe poniża, poniża je aż do ziemi, i strąca je aż do prochu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Depcze je noga; nogi ubogiego, stopa nędzników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Ścieszka sprawiedliwego jest prosta; prostą drogą sprawiedliwego wyrównywasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Na drodze sądów twoich, Panie! oczekujemy cię; żądność duszy naszej jest do imienia twego, i do wspominania na cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Dusza moja żąda cię w nocy, owszem, duchem swym, który jest we mnie, rano cię szukam; albowiem gdy się sądy twoje odprawiają na ziemi, sprawiedliwości się uczą obywatele okręgu ziemskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Gdy się łaska pokazuje niepobożnemu, nie uczy się sprawiedliwości; w ziemi prawości nieprawość czyni, a nie dba nic na majestat Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Panie! choć wywyższona jest ręka twoja, przecię tego nie widzą; ujrząć, ale pohańbieni będą, zajrząc ludowi twemu; nadto i ogień tych nieprzyjaciół twoich pożre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Panie! zrządzisz nam pokój; bo wszystko, co się działo przy nas, czyniłeś ku dobremu naszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Panie Boże nasz! panowalić nad nami inni panowie oprócz ciebie; ale myśmy tylko, w tobie ufając, wspominali na imię twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Pomarli, nie ożyją; martwymi będąc nie powstaną, przeto, żeś ich nawiedził i wykorzenił, i wygładził wszystkę pamiątkę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Rozmnożyłeś naród; o Panie! rozmnożyłeś naród; uwielbionyś jest, acześ go był zapędził na wszystkie granice ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Panie! w ucisku szukali cię; gdyś ich karał, wylewali modlitwy swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Jako brzemienna, gdy się przybliża ku rodzeniu, boleje i woła w boleściach swoich, takeśmy byli przed obliczem twojem, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Poczęliśmy, boleliśmy; aleśmy tylko jakoby wiatr porodzili, a żadnegośmy wybawienia ziemi nie sprawili, i nie upadli mieszkający na okręgu ziemskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Ożyją umarli twoi, trupy moje wstaną, gdy rzeczesz: Ocućcie się, a śpiewajcie mieszkający w prochu! Albowiem rosa twoja będzie jako rosa na ziołach; ale niezbożnych o ziemię uderzysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Idź, ludu mój! wnijdź do komór swoich, a zamknij drzwi twoje za sobą; skryj się na maluczką chwilkę, dokąd nie przeminie rozgniewanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Albowiem oto Pan wychodzi z miejsca swego, aby nawiedził nieprawość mieszkających na ziemi; tedy ziemia odkryje krew swoję, a nie zakryje dalej pobitych swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Dnia onego nawiedzi Pan mieczem swoim srogim, wielkim i mocnym, Lewiatana, węża długiego, i Lewiatana, węża skręconego, a zabije smoka, który jest w morzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Dnia onego śpiewajcie o winnicy wybornego wina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Ja Pan, który jej strzegę, co chwilka odwilżać ją będę, a żeby jej kto nie psuł, w nocy i we dnie strzedz jej będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Zapalczywości żadnej we mnie niemasz. Któż mi da oset albo ciernie, abym przeciwko niej walczył, i spalił ją do szczętu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Izali kto ujmie siłę moję, aby uczynił pokój zemną? aby pokój, mówię, uczynił zemną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Przyjdzie do tego, że się Jakób rozkorzeni, zakwitnie i rozrodzi się Izrael, i napełni okrąg ziemski owocem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Bo izali go tak uderzy, jako uderzył nieprzyjaciela jego? albo izali go zamordował, jako inni są zamordowani od niego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Owszem, miernie go karał, i w ten czas, gdy go wypychał i gdy go nieprzyjaciel wiatrem swoim gwałtownym w dzień wschodniego wiatru, zabierał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Przetoż tym sposobem oczyszczona będzie nieprawość Jakóbowa; a tenci jest wszystek pożytek, że odejmie grzech jego, gdy rozrzuci wszystkie kamienie ołtarza, jako kamienie wapienne rozszarpane, a nie ostoją się gaje i obrazy słoneczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Gdy miasto obronne spustoszeje, a będzie mieszkaniem porzuconem i spustoszonem jako pustynia. Tam się paść, i tam legać będzie cielec, i ogryzie latorosłki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Gdy poschną gałązki jego, pokruszone będą, a niewiasty przyszedłszy zapalą je. Albowiem ten lud nie ma żadnego rozumu; przetoż nie zmiłuje się nad nim, który go uczynił, a który go stworzył, nie zlituje się nad nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Dnia onego, gdy się Pan będzie mścił od łożyska rzeki aż do potoku Egipskiego, wy synowie Izraelscy po jednemu zebrani będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Stanie się też dnia onego, że zatrąbią w trąbę wielką, i przyjdą, którzy byli poginęli w ziemi Assyryjskiej, i którzy byli zagnani do ziemi Egipskiej; i będą się Panu kłaniali na górze świętej w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Biada pysznej koronie,pijanicom z Efraima, i kwiatowi opadłemu z ozdoby sławy swojej! Biada tym, którzy rządzą doliną bardzo urodzajną, i znikczemniałym od wina!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Oto możny i silny Pański będąc jako nawałność gradu, jako wicher wywracający, jako bystrość wód gwałtownej powodzi uderzy ją o ziemię ręką swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Nogami podeptana będzie pyszna korona, pijanicy Efraimscy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Tedy się stanie, że kwiat opadający z ozdoby i z sławy swojej, tych, którzy rządzą doliną bardzo urodzajną, będzie jako owoc skorożrzy, pierwej niż lato bywa; który skoro kto obaczy, nie puści go z ręki, aż go zje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Dnia onego będzie Pan zastępów koroną ozdoby, i koroną sławy ostatkowi ludu swego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'I duchem sądu siedzącemu na sądzie, a mocą tym, którzy odpierają bitwę aż do bramy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Ale i ci od wina błądzą, i od mocnego napoju potaczają się. Książę i prorok błądzą od mocnego napoju, utonęli w winie, potaczają się od mocnego napoju, błądzą w widzeniu, potykają się w sądzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Albowiem wszystkie stoły ich pełne są zwracania i plugastwa, tak, aż miejsca nie staje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Kogożby uczyć miał umiejętności? a komu da zrozumieć co słyszał? Izali odstawionym od mleka, a odsadzonym od piersi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Ponieważ podawał im przykazanie za przykazaniem, przykazanie za przykazaniem, przepis za przepisem, przepis za przepisem, trochę tu, trochę owdzie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'A wszakże jakoby nieznajomą mową, i językiem obcym mówił do ludu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'A gdy im rzekł: Toć jest odpocznienie, sprawcie odpoczynek spracowanemu, toć jest odpocznienie; ale oni nie chcieli słuchać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'I będzie im słowo Pańskie: przykazanie za przykazaniem, przykazanie za przykazaniem, przepis za przepisem, przepis za przepisem; trochę tu, trochę owdzie, na to, aby szli, a padłszy wznak stłukli się, a uwikłani będąc, pochwytani byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Przetoż słuchajcie słowa Pańskiego, mężowie naśmiewcy! panujący nad tym ludem, który jest w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Dlatego, że mówicie: Uczyniliśmy przymierze z śmiercią, i z piekłem mamy porozumienie, bicz gwałtowny nas nie dojdzie, gdy przechodzić będzie; bośmy położyli kłamstwo za ucieczkę swoję, a pod fałszem utailiśmy się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Dlategoż tak powiedział panujący Pan: Oto Ja za grunt kładę w Syonie kamień, kamień doświadczony, węgielny, kosztowny, gruntownie ugruntowany; kto wierzy, nie pokwapi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'A wykonam sąd według sznuru, a sprawiedliwość według wagi; i potłucze grad nadzieję omylną, a ucieczkę wody zatopią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'A tak zgładzone będzie przymierze wasze z śmiercią, a porozumienie wasze z piekłem nie ostoi się; gdy bicz gwałtowny przechodzić będzie, będziecie od niego podeptani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Kiedy jedno pocznie przechodzić, pochwyci was; bo na każdy poranek przechodzić będzie we dnie i w nocy. A sam postrach przywiedzie was ku zrozumieniu tego, coście słyszeli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Zwłaszcza iż krótsze będzie łoże, niżby się kto mógł rozciągnąć, i nakrycie wąskie, choćby się skurczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Albowiem Pan powstanie jako na górze Perazym, a rozgniewa się jako w dolinie Gabaon, aby wykonał sprawę swoję, niezwyczajną sprawę swoję, i aby dokończył sprawy swojej, niezwyczajnej sprawy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'A tak teraz nie naśmiewajcie się, aby się niezmocniły związki wasze, bom o pewnem zepsowaniu wszystkiej ziemi słyszał od Pana, Pana zastępów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Nadstawiajcie uszów, a słuchajcie głosu mego; bądźcie pilni, a słuchajcie mowy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Izali każdego dnia oracz orze, aby siał? przegania brozdy, a włóczy rolę swoję?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Izali zrównawszy wierzch jej, nie rozsiewa wyki, i nie roztrząsa kminu, i nie sieje pszenicy wybornej, i jęczmienia przedniego, i orkiszu na miejscu sposobnem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Bo go uczy roztropności Bóg jego, i naucza go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Wyki nie młócą okowanem naczyniem, ani taczają koła wozowego po kminie; ale kijem wybijają wykę, a kmin laską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Pszenica młócona bywa; wszakże i tej nie zawżdy młócić będzie, ani jej potrze kołem woza swego, ani jej zębami jego pokruszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'I toć od Pana zastępów wyszło, który jest dziwny w radzie, a wielmożny w rzeczy samej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Biada Aryjelowi! Aryjelowi miastu, w którem mieszkał Dawid. Przydajcie rok do roku, niechaj rzeżą barany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Jednak ucisnę Aryjela, i będzie smutek i żałość, bo mi będzie jako Aryjel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Położę się zaiste obozem w około przeciwko tobie, i ścisnę cię wałami, i wystawię przeciwko tobie baszty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Tedy będąc zniżone, z ziemi mówić będziesz, i z prochu szeptać będzie mowa twoja; będzie mówił głos twój, jako wieszczka z ziemi, a z prochu mowa twoja szeptać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Bo mnóstwo nieprzyjaciół twoich będzie jako proszku drobnego, a zgraja okrutników jako plew latających; a to się nagle w okamgnieniu stanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Od Pana zastępów nawiedzione będzie gromem i trzęsieniem ziemi, i głosem wielkim, wichrem i burzą, i płomieniem ognia pożerającego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Ale jako sen widzenia nocnego, tak będzie zgraja wszystkich narodów walczących przeciwko Aryjelowi, i wszystkich bojujących przeciwko niemu i twierdzom jego, i tych, którzy go uciskają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Będzie, mówię, jako gdy się śni głodnemu, jakoby jadł; ale gdy się ocuci, alić czczy żywot jego; i jako gdy się śni pragnącemu, jakoby pił, a gdy się ocuci, alić zemdlony zostaje, a dusza jego pragnie; tak będzie zgraja wszystkich narodów walczących przeciwko górze Syońskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Jakoż tedy odwłaczacie, choćbyście się zdumiewać mieli; rozkoszujecie, choćbyście mieli na pomoc wołać. Opili się, ale nie winem; potaczają się, ale nie od mocnego napoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Bo was napełnił Pan duchem snu twardego, i zawarł oczy wasze; proroków i książąt waszych najopatrzniejszych oczy zasłonił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Przetoż wam wszelkie widzenie podobne jest słowom ksiąg zapieczętowanych, które danoliby temu, co zna pismo, a rzeczono: Czytaj to proszę, tedy odpowie: Nie mogę, bo są zapieczętowane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'A danoliby księgi temu, co nie zna pisma, a rzeczono: Czytaj to proszę, tedy odpowie: Nie znam pisma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Bo mówi Pan: Przeto, że ten lud przybliża się do mnie usty swemi, a serce jego dalekie jest odemnie, a bojaźni, którą się mnie boją, z przykazań ludzkich nauczyli się:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Dlatego Ja też sobie dziwnie pocznę z tym ludem, dziwnie i cudownie, i zginie mądrość mądrych jego, a rozum roztropnych jego skryje się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Biada tym, którzy głęboko przed Panem ukrywają radę! których każda sprawa dzieje się w ciemności, i mówią: Któż widzi? Kto wie o nas?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Przewrotne myśli wasze są jako glina garncarska. Izali rzecze robota o tym, co ją urobił: Nie urobił mię? i ulepienie izali rzecze o tym, co je ulepił: Nie rozumiał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Izali po maluczkim i króciuchnym czasie nie obróci się Liban w pole? a pole za las poczytane nie będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'I usłyszą dnia onego głusi słowa ksiąg, a z mroku i z ciemności oczy ślepych patrzać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Ale cisi nader się rozweselą w Panu, a ubodzy ludzie rozweselą się w Świętym Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Gdy ustanie okrutnik, a zniszczeje naśmiewca, wykorzenieni będą wszyscy, którzy pilnowali nieprawości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'Którzy winują człowieka dla słowa, a na tego, który ich strofuje, w bramie sidła stawiają, i bez przyczyny do upadku przywodzą sprawiedliwego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Przetoż tak mówi o domu Jakóbowym Pan, który odkupił Abrahama: Już dalej nie będzie zawstydzony Jakób, ani więcej twarz jego zblednie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Albowiem gdy ujrzy synów swoich, dzieło rąk moich, w pośrodku siebie, poświęcających imię moje; tedy będą poświęcać Świętego Jakóbowego, a Boga Izraelskiego bać się będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'I staną się rozumnymi błądzący duchem, a szemracze nauczą się umiejętności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Biada synom odpornym, mówi Pan, którzy czynią radę, ale nie ze mnie, i nakrywają ją nakryciem, ale nie z ducha mojego, aby przyczyniali grzechu do grzechu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Którzy chodzą a zstępują do Egiptu, nie radząc się ust moich, aby się zmocnili mocą Faraonową, i ukryli się w cieniu Egipskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Bo moc Faraonowa będzie wam ku zawstydzeniu, a ucieczka do cieniu Egipskiego ku pohańbieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Przeto, że byli w Soan książęta jego, a posłowie jego do Chanes chodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Wszystkich do hańby przywiedzie przez lud, który im nie będzie ku dogodzie, ani ku pomocy, ani ku pożytkowi, ale tylko ku zelżywości i ku hańbie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Brzemię odniosą na bydlętach południowych do ziemi ucisku i utrapienia,(skąd pochodzi lew i szcznię lwie, żmija i smok ognisty latający;) odniosą mówię na grzbietach bydlątek bogactwa swoje, i na garbie wielbłądów skarby swoje, do ludu, który im nic nie pomoże;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Bo Egipczanie daremno i próżno pomagać będą. Dlatego to ogłaszam, że ich moc jest, siedzieć w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Terazże idź, napisz to na tablicy przed oczyma ich, a na księgach to wyrysuj, aby to trwało do dnia ostatniego, i aż na wieki wieków:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Że ten lud jest odporny, synowie kłamliwi, synowie, którzy nie chcą słuchać zakonu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Którzy mówią widzącym: Nie miewajcie widzenia; a prorokom: Nie prorokujcie nam, co prawego jest; mówcie nam rzeczy przyjemne, prorokujcie oszukanie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Ustąpcie z drogi, zejdźcie z ścieszki; niech będzie daleki od oblicza naszego Święty Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Przetoż tak mówi Święty Izraelski: Iż gardzicie tem słowem, a ufacie w potwarzy i w przewrotności, i spolegacie na niej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'Dlatego wam ta nieprawość będzie jako mur przerwany upadający, i jako wydęcie na murze wysokim, którego bywa nagłe i prędkie obalenie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'I pokruszy ją, jako się kruszy stłuczone naczynie garncarskie; a tak mu nie sfolguje, iż się nie znajdzie po stłuczeniu jego i skorupa, którąby mógł nabrać ognia z ogniska, albo naczerpać wody z kałuży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Albowiem tak mówi panujący Pan, Święty, Izraelski: Jeźli się nawrócicie i uspokoicie się, zachowani będziecie; w milczeniu i w nadziei będzie moc wasza. Ale nie chcecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Owszem mówicie: Nie tak, ale na koniach ucieczemy; przetoż uciekać będziecie. Na prędkich koniach ujedziemy; ale prędsi będą ci, którzy was gonić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Tysiąc ich uciecze przed okrzyknieniem jednego, a przed okrzyknieniem pięciu wszyscy ucieczecie, aż zostaniecie jako maszt na wierzchu góry, a jako chorągiew na pagórku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'A dlategoć Pan czekać będzie, aby się zmiłował nad wami, i dlatego się wywyższy, aby się zlitował nad wami; albowiem Pan jest Bogie sądu; błogosławieni wszyscy, którzy nań oczekują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Bo lud na Syonie i w Jeruzalemie będzie mieszkać; płakać więcej nie będziesz. Zapewne zlituje się nad tobą na głos wołania twego (Pan), a skoro usłyszy, ozwieć się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'A choć wam Pan da chleb utrapienia, i wodę ucisku, jednak nie odlecą więcej od ciebie nauczyciele twoi, ale oczy twoje patrzać będą na nauczycieli twoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'I uszy twoje usłyszą słowo z tyłu do ciebie mówiącego: Tać jest droga, chodźcie po niej, lubbyście się w prawo albo w lewo udali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Tedy zarzucicie okrycie srebrnych swoich bałwanów rytych, i odzienie złotych swoich bałwanów odlewanych; rozproszysz je jako plugastwo niewiasty przyrodzoną niemoc cierpiącej, a rzeczesz im: Precz stąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Da Bóg i deszcz na siewy twoje, któremibyś posiał ziemię, a chleb z urodzaju ziemi będzie syty i obfity; dnia onego paść się będą i bydła twoje na pastwisku szerokiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Woły także i osły sprawujące ziemię, pastwę czystą jeść będą, która opałką i łopatą wywiana bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'I będą na każdej górze wysokiej, i na każdym pagórku wyniosłym strumienie i potoki wód w dzień porażki wielkiej, gdy wieże upadną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Światłość też miesiąca będzie jako światłość słoneczna; a światłość słoneczna będzie w siedmiornasób, jako światłość siedmiu dni, dnia, którego zawiąże Pan złamanie ludu swego, a ranę zbicia jego uleczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Oto imię Pańskie przychodzi z daleka, zapaliła się popędliwość jego, i ciężka jest ku znoszeniu; wargi jego pełne są gniewu, a język jego jako ogień pożerający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'A duch jego jest jako rzeka wylewająca, która aż do gardła sięga, aby przewiewał narody, ażby się wniwecz obróciły, a wędzidłem kiełznał czeluści narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Tedy zaśpiewacie, jako gdy się w nocy obchodzi uroczyste święto, a rozweselicie się w sercu jako ten, który idzie z piszczałką, idąc na górę Pańską, do skały Izraelskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Gdy da usłyszeć Pan wielmożność głosu swego, i wyciągnione ramię swoje okaże w popędliwości gniewu swojego, i w płomieniu ognia pożerającego z rozproszeniem, z gwałtownym dżdżem, i z gradem kamiennym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Bo od głosu Pańskiego starty będzie Assyryjczyk, który innym kijem bijał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'I stanie się, że na samym każde uderzenie kijowe, którem go Pan uderzy, znaczne będzie, gdy z bębnami i z lutniami, i z bitwą wesołą walczyć będzie przeciwko niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Albowiem dawno już jest nagotowane piekło, i dla samego króla nagotowane jest; które głębokie i szerokie uczynił, podniaty jego ognia i drew siła jest; poddymanie Pańskie jako rzeka siarczana zapala je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Biada tym, którzy zstępują do Egiptu o pomoc, a na koniach spolegają, i ufają w wozach, że ich wiele, i w jezdnych, iż są mocni bardzo, a nie oglądają się na Świętego Izraelskiego, a Pana nie szukają!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Aleć on też jest mądry, przetoż przywiedzie złe, a słów swoich nie odmieni; lecz powstanie przeciw domowi złośników i przeciwko ratunkowi tych, którzy broją nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Albowiem Egipczanie są ludzie a nie Bóg, a konie ich ciało, a nie duch. Przetoż skoro Pan wyciągnie rękę swą, padnie i pomocnik, padnie i ten, któremu dawają pomoc; a tak wszyscy społem zginą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Bo tak rzekł Pan do mnie: Jako gdy ryczy lew, i szczenię lwie nad łupem swym, a choć zwoływają przeciwko niemu gromadę pasterzy, przecie się on wrzasku ich nie lęka, ani się korzy przed hukiem ich; tak Pan zastępów zstąpi, aby walczył o górę Syońską, i o pagórek jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Jako ptaki latają około gniazda swego, tak obroni Pan zastępów Jeruzalem, i owszem, broni i wybawia, a przechodząc z pomstę zachowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Nawróćcie się do tego, od którego głęboko zabrnęli synowie Izraelscy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Albowiem dnia onego odrzuci każdy bałwany swe srebrne, i bałwany swe złote, które wam naczyniły ręce wasze na grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'I upadnie Assyryjczyk od miecza nie męskiego, a miecz nie człowieczy pożre go: i uciecze przed mieczem, a młodzieńcy jego hołdownikami będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'A tak opokę swoję od strachu minie, a książęta jego ulękną się przed chorągwią, mówi Pan, którego ogień jest na Syonie, a piec w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Oto król będzie królował w sprawiedliwości, a książęta w sądzie panować będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Bo mąż on będzie jako zasłona od wiatru, i jako zakrycie przed powodzią; jako strumienie wód na miejscu suchem, jako cień skały wielkiej w ziemi upragnionej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'I nie będą się błąkać oczy widzących, i uszy słuchających pilnie słuchać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Serce głupich zrozumie umiejętność, a język jąkających się prędko i rzetelnie mówić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'I nie będą więcej zwać nieszlachetnego szlachetnym, a skąpy nie będzie słyną szczodrym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Przeto, że nieszlachetny o nieszlachetności mówi, a serce jego zmyśla nieprawość, aby wykonał obłudność, a mówił przeciwko Panu zdrożnie; aby wyniszczył duszę łaknącego, a napój pragnącego odjął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Skąpego też usiłowania złe są: bo chytrze obmyśla, jakoby wniwecz obrócił utrapionych słowy kłamliwemi, i mówił przeciwko nędznemu przed sądem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Ale szczodrobliwy o szczodrobliwości myśli, a przy szczodrobliwości stać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Niewiasty spokojne! powstańcie, słuchajcie głosu mego; córki bezpieczne! bierzcie w uszy swe powieści moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Przez wiele dni i lat trwożyć się będziecie, wy bezpieczne! albowiem ustanie zbieranie wina, a sprzątania urodzajów nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Zatrwożcie się, a ulęknijcie się, bezpieczne! zewleczcie się, i obnażcie się, a przepaszcie biodra wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Kwiląc nad piersiami, nad rolami rozkosznemi, i nad winną macicą urodzajną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Na ziemi ludu mojego ciernie i oset wyrośnie, owszem, na wszystkich domach wesołych miasta radującego się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Albowiem pałac opuszczony będzie, huk miasta ustanie, zamek i baszty jaskiniami zostaną aż na wieki, na radość dzikim osłom i na pastwiska trzodom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Póki nie będzie wylany na nas duch z wysokości, a nie obróci się pustynia w pole urodzajne, a pole urodzajne za las poczytane nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'I będzie sąd przemieszkiwał na puszczy, a sprawiedliwość pole urodzajne osiądzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'I będzie pokój dzieło sprawiedliwości, a skutek sprawiedliwości odpocznienie i bezpieczność aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Bo będzie mieszkał lud mój w przybytku pokoju, i w przybytkach bezpiecznych, i w odpoczywaniu spokojnem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Choćby i grad spadł na las, a miasto bardzo poniżone było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Błogosławieni jesteście, którzy siejecie na wszelakich miejscach urodzajnych, wpuszczając tam woły i osły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Biada tobie, który łupisz, chociażeś sam nie złupiony, i który zdradzasz, chociażeś sam nie był zdradzony! Gdy łupić przestaniesz, będziesz też złupiony; gdy zdradzać przestaniesz, będą cię też zdradzać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Panie! zmiłuj się nad nami, ciebie oczekujemy. Bądź ramieniem swoich na każdy poranek, a zbawieniem naszem czasu utrapienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Przed głosem ogromnym rozpierzchną się narody; przed wywyższeniem twojem rozproszą się poganie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'I będą zebrane łupy wasze, jako zbierają chrząszcze; a jako przypada szarańcza, tak oni przypadną na nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Pan będzie wywyższony, bo mieszka na wysokości; napełni Syon sądem i sprawiedliwością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Mądrość i umiejętność będą utwierdzeniem czasów twoich, siłą i obfitem zbawieniem twem, a bojaźń Pańska skarbem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Oto mocarze ich wołają na dworze, posłowie pokoju gorzko płaczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Spustoszały drogi, przestano ścieszką chodzić; złamał przymierze, znieważył miasta, a człowieka za nic sobie nie ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Płakała i zwątlała ziemia; zawstydzony jest Liban i uwiądł; Saron się stał jako pustynia, i otłuczono Basan i Karmel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Teraz powstanę, mówi Pan, teraz się wywyższę, teraz się podniosę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Począwszy słomę, urodzicie mierzwę; duch wasz was pożre jako ogień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'I będą narody, jako wypalone wapno; będą jako ciernie wycięte, ogniem spalone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Słuchajcie, którzyście daleko, com uczynił, a bliscy poznajcie moc moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Zlękli się na Syonie grzesznicy, strach zdjął obłudników mówiących: Któż z nas ostać się może przed ogniem pożerającym? Któż z nas ostać się może przed płomieniem wiecznym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Ten, który chodzi w sprawiedliwości, a mówi, co jest prawego; który się zyskiem niesprawiedliwym brzydzi; który otrząsa ręce swe, aby darów nie brał; który zatula uszy swe, aby nie słuchał o rozlaniu krwi, i zamruża oczy swoje, aby nie patrzał na złe:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Ten na wysokościach mieszkać będzie, zamki na skałach będą ucieczką jego; chleb jego dany mu będzie, wody jego nie ustaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Króla w piękności jego oglądają oczy twoje, ujrzą i ziemię daleką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Serce twoje będzie rozmyślało o starchu, mówiąc: Gdzie teraz jest pisarz? gdzież teraz jest poborca? gdzież jest obliczający wieże?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Ludu okrutnego nie oglądasz, ludu głębokiej mowy, któregoś nie słyszał, i języka obcego, któregobyś nie rozumiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Wejrzyj na Syon, miasto uroczystych swiąt naszych, oczy twoje niechaj patrzą na Jeruzalem, na mieszkanie spokojne, na namiot,który nie będzie przeniesion; kołki jego na wieki się nie poruszą, a żaden powróz jego nie zerwie się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Przeto, że nam na tem miejscu Pan wielmożny jest rzekami strumieni szerokich, po których nie pójdą z wiosłami, ani okręt wielki po nich przechodzić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Bo Pan jest sędzia nasz, Pan zakonodawca nasz; Pan król nasz; on nas zbawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Osłabiały powrozy twoje, nie będą mogły w klubie zatrzymać masztu twego, ani rozciągną żaglów. Tedy rozdzielone będą łupy korzyści wielkiej, że i chromi rozchwycą łupy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'A nie rzecze żaden z obywateli: Zachorowałem; lud, który mieszka w nim, uwolniony będzie od nieprawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Przystąpcie, narody! ku słuchaniu, a wy ludzie pilnie uważajcie! Niech słucha ziemia, i pełność jej, okrąg ziemi, i wszystko, co się rodzi na niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Bo rozgniewanie Pańskie jest na wszystkie narody, a popędliwość jego na wszystko wojsko ich; wytraci je jako przeklęte, a poda je na zabicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'I będą wyrzuceni pobici ich, a z trupów ich smród wynijdzie, a krew ich z gór popłynie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'I niszczeć będzie wszystko wojsko niebieskie, a niebiosa jako księgi zwinione będą, i wszystko wojsko ich opadnie, jako opada liść z winnej macicy, i jako opada niedojrzały owoc z figowego drzewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Albowiem opojony jest na niebie miecz mój; oto zstąpi na Edomczyków, i na sąd ludu przeklętego odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Miecz Pański pełny będzie krwi, utłuści się w łoju i we krwi baranków i kozłów, w łoju nerek baranich; bo ofiara Pańska będzie w Bocra, a porażka wielka w ziemi Edomskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Zstąpią z nimi i jednorożce, i byki z wołami, i opojona będzie krwią ziemia ich, a proch ich będzie opojony tukiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Albowiem to dzień pomsty Pańskiej będzie, i rok odpłaty, aby się pomszczono Syonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'I obrócą się potoki jej w smołę, a proch jej w siarkę, a ziemia jej obróci się w smołę gorejącą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Ani w nocy ani we dnie nie zagaśnie, na wieki będzie występował dym jej; od narodu do narodu pustą zostanie; na wieki wieczne nie będzie, ktoby szedł przez nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Ale ją pelikan i bąk posiędą, a sowa i kruk mieszkać w niej będą; i rozciągnie po niej sznur spustoszenia, i wagi próżności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Szlachty jej na królestwo wzywać będą, ale nie będzie tam żadnego; bo wszyscy książęta jej wniwecz się obrócą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'I urosną na pałacach ich ciernie, pokrzywy i oset na zamkach ich; i będzie przybytkiem smoków, a mieszkaniem strusiów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Tam się będą potykały dzikie zwierzęta z koczkodanami, i pokusa jedna drugiej ozywać się będzie; tam leżeć będzie jędza, a znajdzie sobie odpocznienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Tam sobie sęp gniazdo uczyni, zniesie jajka, i wylęże, a schowa pod cień swój; tamże się zlecą kanie jedna do drugiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Szukajcież w księgach Pańskich, a czytajcie; ani jedno z tych nie uchybi, a jedno bez drugiego nie będzie; albowiem usta Pańskie to rozkazały, a duch jego sam zgromadzi je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Bo im on los rzucił, a ręka jego onę im sznurem rozmierzyła; aż na wieki dziedzicznie ją posiądą, od narodu do narodu mieszkać w niej będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Weselić się z tego będzie pustynia i miejsce leśne, a rozraduje się i zakwitnie jako róża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Ślicznie zakwitnie, i radując się weselić się będzie z wykrzykaniem; chwała Libanu będzie jej dana, i ozdoba Karmelu i Saronu. One ujrzą chwałę Pańską i ozdobę Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Umacniajcie ręce osłabiałe, a kolana zemdlałe posilajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Mówcie do zatrwożonych w sercu: Zmocnijcie się, nie bójcie się; oto Bóg wasz z pomstą przyjdzie; z nagrodą Bóg sam przyjdzie, i zbawi was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Tedy się otworzą oczy ślepych, a uszy głuchych tworzone będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Tedy poskoczy chromy jako jeleń, a niemych język śpiewać będzie; albowiem wody na puszczy wynikną, a potoki na pustyniach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'I stanie się miejsce suche jeziorem, a bezwodne źródłami wód; w łożyskach smoków, kędy legali, trawa, trzcina, i sitowie rość będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'I będzie tam droga i ścieszka, która drogą świętą słynąć będzie; nie pójdzie po niej nieczysty, ale będzie dla onych samych. Którzy tą drogą pójdą, i głupi nawet, nie zbłądzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Nie będzie tam lwa, a okrutny zwierz nie będzie chodził po niej, ani się tam znajdzie; ale wybawieni po niej chodzić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Odkupieni, mówię, Pańscy nawrócą się, i przyjdą na Syon z śpiewaniem, a wesele wieczne będzie na głowie ich; radość i wesele otrzymają, a żałość i smutek uciecze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'I stło się czternastego roku królowania Ezechyjasza, że przyciągnął Sennacheryb, król Assyryjski, przeciwko wszystkim miastom Judzkim obronnym, i pobrał je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'I posłał król Assyryjski Rabsacesa z Lachys, do Jeruzalemu, do króla Ezechyjasza z wielkiem wojskiem, który stanął u rur sadzawki wyższej przy drodze pola blecharzowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Tedy wyszedł do niego Elijakim, syn Helkijaszowy, przełożony nad domem, i Sobna pisarz, i Joach, syn Asafowy, kanclerz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'I rzekł do nich Rabsaces: Proszę, powiedzcie Ezechyjaszowi: Tak mówi król wielki, król Assyryjski: Cóż to za ufność, którą ufasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Rzekłbym: (Acz to rzecz daremna) Snać rady i mocy do wojny dosyć masz; ale w kimże ufasz, że mi się sprzeciwiasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Otoś spoległ na lasce tej trzciny nałamanej, na Egipcie, którą jeźliby się kto podparł, wnijdzie w rękę jego, i przekole ją. Takić jest Farao, król Egipski, wszystkim, którzy w nim ufają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'A jeźli mi rzeczesz: W Panu, Bogu naszym, ufamy; azaż nie ten jest, którego zniósł Ezechyjasz wyżyny i ołtarze, i przykazał Judzie i Jeruzalemowi mówiąc: Przed tym ołtarzem kłaniać się będziecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Przetoż teraz proszę, zaręcz się Panu memu, królowi Assyryjskiemu, a ja tobie dam dwa tysiące koni, będzieszli je mógł osadzić jezdnymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'I jakoż się ty możesz oprzeć hetmanowi jednemu najmniejszemu z sług pana mego, choć ufasz w Egipcie dla wozów i jezdnych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Nadto czy bez woli Pańskiej przyciągnąłem do tej ziemi, abym ją spustoszył? Pan rzekł do mnie: Ciągnij do tej ziemi, a spustosz ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Tedy rzekł Elijakim, i Sobna, i Joach do Rabsacesa: Proszę, mów do sług twoich po syryjsku, wszak rozumiemy, a nie mów do nas po żydowsku przed tym ludem, który jest na murze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'I odpowiedział Rabsaces: Azaż mię do Pana twego albo do ciebie posłał Pan mój, abym te słowa mówił? Posłał mię raczej do mężów, którzy siedzą na murze, aby jedli łajna swoje, a mocz swój pospołu z wami pili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'A tak stanął Rabsaces i wołał głosem wielkim po żydowsku, mówiąc: Słuchajcie słów króla wielkiego, króla Assyryjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Tak mówi król: Niech was nie zwodzi Ezechyjasz: bo was nie będzie mógł wybawić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'A niech wam nie rozkazuje Ezechyjasz ufać w Panu, mówiąc: Zapewne nas Pan wybawi, a nie będzie to miasto podane w rękę króla Assyryjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Nie słuchajcież Ezechyjasza; albowiem tak powiedział król Assyryjski: Uczyńcie zemną przymierze, a wynijdźcie do mnie, a jedz każdy z was z winnicy swojej, i każdy z figowego drzewa swego, a pij każdy z was wodę z studni swojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Aż przyjdę a pobiorę was do ziemi podobnej ziemi waszej, do ziemi zboża i wina, do ziemi chleba i winnic.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Niech was nie zwodzi Ezechyjasz, mówiąc: Pan nas wybawi. Izaż mogli bogowie narodów wybawić każdy ziemię swoję z ręki króla Assyryjskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Gdzież są bogowie Emat i Arfad? Gdzie są bogowie Sefarwaim? Azaż wybawił Samaryję z ręki mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Którzyż są między wszystkimi bogami tych ziem, którzyby wydarli ziemię swoję z ręki mojej? A miałby Pan wybawić Jeruzalem z ręki mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Ale oni milczeli, i nie odpowiedzieli mu i słowa; bo takie było rozkazanie królewskie, mówiąc: Nie odpowiadajcie mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'I przyszedł Elijakim, syn Helkijaszowy, przełożony domu, i Sobna pisarz, i Joach, syn Asafowy, kanclerz, do Ezechyjasza, rozdarłszy szaty swe, i oznajmili mu słowa Rabsacesowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'A gdy to usłyszał król Ezechyjasz, rozdarł szaty swoje, a oblókłszy się w wór, wszedł do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'I posłał Elijakima, sprawcę domu swego, i Sobnę pisarza, i starszych z kapłanów obleczonych w wory, do Izajasza proroka, syna Amosowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Którzy rzekli do niego: Tak mówi Ezechyjasz: Dzień ten jest dzień utrapienia, i łajania, i bluźnienia; albowiem synowie przyszli aż do porodzenia, ale siły niemasz ku rodzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Oby usłyszał Pan, Bóg twój, słowa Rabsacesowe, którego posłał król Assyryjski, pan jego, aby urągał Bogu żyjącemu, i pomścił się Pan Bóg twój, tych słów, które słyszał! Przetoż uczyń modlitwę za te ostatki ludu, które się znajdują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Przyszły tedy słudzy króla Ezechyjasza do Izajasza;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Którym odpowiedział Izajasz: Tak powiedzcie Panu waszemu, tak mówi Pan: Nie bój się tych słów, któreś słyszał, któremi mię lżyli słudzy króla Assyryjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Oto ja mu dam innego ducha, aby usłyszawszy wieść nawrócił się do ziemi swojej; i sprawię to, że polegnie od miecza w ziemi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Ale Rabsaces wróciwszy się znalazł króla Assyryjskiego dobywającego Lebny; albowiem usłyszał, iż odciągnął był od Lachys.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'A usłyszawszy o Tyraku, królu Etyjopskim, że mówiono: Oto ciągnie, aby walczył przeciwko tobie; usłyszawszy to, mówię, przecie posłał posłów do Ezechyjasza z temi słowy:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'To powiedzcie Ezechyjaszowi, królowi Judzkiemu, mówiąc: Niech cię nie zwodzi Bóg twój, któremu ty ufasz, a mówisz: Nie będzie podane Jeruzalem w ręce króla Assyryjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Otoś słyszał, co poczynili królowie Assyryjscy wszystkim ziemiom, które wygładzili; a tybyś miał być wybawiony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Izali je wybawili bogowie tych narodów, które wygubili ojcowie moi: Gozan, i Haran, i Resef, i synów Eden, którzy byli w Telassar?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Gdzież jest król Elmat, i król Arfad, i król miasta Sefarwaim, Ana, i Awa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Przetoż wziąwszy Ezechyjasz list z ręki posłów, przeczytał go, a wszedłszy do domu Pańskiego, rozciągnął go Ezechyjasz przed Panem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'I modlił się Ezechyjasz Panu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Panie zastępów, Boże Izraelski, siedzący na Cherubinach! Ty, tyś sam jest Bóg wszystkich królestw ziemi, tyś stworzył niebo i ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Nakłońże, Panie! ucha twego, a usłysz; otwórz, Panie! oczy twoje, a obacz; usłysz wszystkie słowa Sennacherybowe, który przysłał hańbić ciebie, Boga żywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Prawdać jest, Panie! że sputoszyli królowie Assyryjscy wszystkie te krainy, i ziemię ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'I powrzucali bogów ich w ogień; albowiem nie byli bogami, ale robotą rąk ludzkich, drewno i kamień; przetoż ich wygubili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'A teraz, o Panie, Boże nasz! wybaw nas z ręki jego, aby poznały wszystkie królestwa ziemi, żeś ty, Panie! sam Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Tedy posłał Izajasz, syn Amosowy, do Ezechyjasza, mówiąc: Tak mówi Pan Bóg Izraelski: O coś mię prosił z strony Sennacheryba, króla Assyryjskiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Tedy to jest słowo, które mówił Pan o nim: Panna, córka Syońska, wzgardziła cię, śmiała się z ciebie, kiwała głową za tobą córka Jeruzalemska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Kogożeś hańbił, i kogoś bluźnił? przeciwko komużeś podniósł głos, i wyniosłeś ku górze oczy swe? przeciwko Świętemu Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Przez sługi twoje hańbiłeś Pana, i mówiłeś: W mnóstwie wozów moich wstąpiłem ja na wysokie góry, na strony Libańskie, i porąbię wysokie cedry jego, i wyborne jodły jego; i wnijdę na samę wysokość wierzchu jego, do lasów, i urodzajnych ról jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Jam wykopał źródła i piłem wody, a wysuszyłem stopami nóg moich wszystkie potoki miejsc oblężonych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Izażeś nie słyszał, żem to z dawna uczynił, i ode dni starodawnych to sprawił? A teraz do tego przywodzę, aby w pustynie i w kupy rumu miasta obronne obrócone były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'A obywatele ich ręce skurczone mając, przestraszeni są i zawstydzeni, stali się jako trawa polna, i jako ziele wschodzące, i trawy na dachach, a siewy rdzą zepsowane, pierwej niżeliby dorosły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Mieszkanie twoje, i wyjście twoje, i wejście twoje znam, i popędliwość twoję przeciwko sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Ponieważeś się przeciwko mnie zajuszył, a zapędy twoje przyszły do uszów moich, przetoż założę kolce moje za nozdrza twoje, a wędzidło moje wprawię w gębę twoję, i wrócę cię tą drogą, którąś przyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'A to miej za znak, Ezechyjaszu! Tego roku jeść będziesz samorodne zboże, także i drugiego roku samorodne zboże; ale roku trzeciego będziecie siać i żąć, i winnice sadzić, i pożywać owoce ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Ostatek bowiem domu Judy, który pozostał, wkorzeni się głęboko, i wyda owoc ku górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Albowiem z Jeruzalemu wyjdą ostatki, i zachowani z góry Syońskiej. Gorliwość Pana zastępów to uczyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Przetoż tak mówi Pan o królu Assyryjskim: Nie wnijdzie do miasta tego, ani tam strzały wystrzeli, ani go zaprzątnie tarcza, ani usypie około niego szańców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Drogą, którą przyszedł, zaś się wróci, a do miasta tego nie wnijdzie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Bo będę bronił miasta tego, i zachowam je sam dla siebie, i dla Dawida, sługi mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Tedy wyszedł Anioł Pański, i pobił w obozie Assyryjskim sto ośmdziesiąt, i pięć tysięcy; a gdy wstali bardzo rano, oto wszędy pełno trupów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Przetoż ruszywszy się, odjechał, i wrócił się Sennacheryb, król Assyryjski, a mieszkał w Niniwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'A gdy chwalił Nesrocha, boga swego, w domu, tedy Adramelach i Sarasar, synowie jego, zabili go mieczem, a sami uciekli do ziemi Ararat; a królował Assarhaddon, syn jego, miasto niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'W one dni zachorował Ezechyjasz aż na śmierć. I przyszedł do niego Izajasz prorok, syn Amosowy, a rzekł do niego: Tak mówi Pan: Rozpraw dom swój; albowiem umrzesz, a nie zostaniesz żyw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Tedy obrócił Ezechyjasz twarz swoję do ściany, a modlił się Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'I rzekł: Proszę, o Panie! wspomnij teraz, żem chodził przed tobą w prawdzie i w sercu uprzejmem, czyniąc to, co dobrego jest w oczach twoich. I płakał Ezechyjasz płaczem wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'I stało się słowo Pańskie do Izajasza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Idź, a powiedz Ezechyjaszowi: Tak mówi Pan, Bóg Dawida, ojca twego: Wysłuchałem modlitwę twoję, widziałem łzy twoje; oto Ja przyczynię do dni twoich piętnaście lat;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'I z ręki króla Assyryjskiego wyrwę ciebie i to miasto, a będę bronił miasta tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'A to będziesz miał za znak od Pana, że Pan uczyni to, co mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Oto Ja wrócę nazad cień po stopniach po których szedł, na zegarze słonecznym Achazowym na dziesięć stopni po tychże stopniach, po których było zeszło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Pisanie Ezechyjasza, króla Judzkiego, gdy był zachorował i wyzdrowiał z niemocy swojej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Jam rzekł w ukróceniu dni moich: Wnijdę do bram grobu, pozbawion będę ostatka lat swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Rzekłem, że nie ujrzę Pana, Pana w ziemi żyjących; nie oglądam więcej człowieka między obywatelami na świecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Pobyt mój pomija, a przenosi się odemnie, jako namiot pasterski; oderznąłem żywot swój, jako tkacz; od krosien oderznie mię; dziś, pierwej niż noc nadejdzie, dokonasz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Rozmyślałem sobie z poranku, że jako lew potrze wszystkie kości moje, dziś, pierwej niż noc nadejdzie, dokonasz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Jako żóraw i jaskółka szczebiotałem, stękałem jako gołębica; oczy moje ku górze podniesione były, i rzekłem: Panie! gwałt cierpię, przedłuż mi żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Ale cóż mam więcej rzec? Onci mi odpowiedział, i sam uczynił, że żyć będę mimo wszystkie lata swe po gorzkości duszy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Panie! kto po nich i w nich żyć będzie, wszystkim znajomy będzie żywot dychania mego, żeś mi zdrowie przywrócił, a zachowałeś mię przy żywocie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Oto czasu pokoju przyszła na mię była gorzkość najgorzciejsza; ale się tobie podobało wyrwać duszę moję z przepaści skażenia, przeto, żeś zarzucił w tył swój wszystkie grzechy moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Albowiem nie grób wysławia cię, ani śmierć chwali cię, ani ci, którzy w dół wstępują, oczekują prawdy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Żywy, żywy, ten cię wysławiać będzie, jako ja dzisiaj, a ojciec synom oznajmi prawdę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Pan mię wybawił; przetoż pieśń moję śpiewać będziemy po wszystkie dni żywota naszego w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'I rzekł był Izajasz: Niech wezmą bryłę suchych fig, i przyłożą na wrzód, a będzie uzdrowiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'I rzekł był Ezechyjasz: Cóż jest za znak, że wstąpię do domu Pańskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Onego czasu posłał Merodach Baladan, syn Baladanowy, król Babiloński, list i dary do Ezechyjasza; bo zasłyszał, że zachorowawszy zaś ozdrowiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'I weselił się z tego Ezechyjasz, i ukazał im skarbnicę klejnotów swoich srebra i złota, i rzeczy wonnych, i olejki najwyborniejsze, także i dom rynsztunków swoich, i cokolwiek się znajdowało w skarbach jego: nie było nic, czegoby im nie ukazał Ezechyjasz w domu swym, i we wszystkiem państwie swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Wtem przyszedł Izajasz prorok do króla Ezechyjasza, i rzekł mu: Coć powiedzieli ci mężowie, i skąd przyszli do ciebie? I odpowiedział Ezechyjasz: Z ziemi dalekiej przyszli do mnie, z Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Nadto rzekł: Cóż widzieli w domu twoim? Odpowiedział Ezechyjasz: Wszystko, co jest w domu moim, widzieli; niemasz nic, czegobym im nie ukazał w skarbach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Tedy rzekł Izajasz do Ezechyjasza: Słuchaj słowa Pana zastępów:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Oto przyjdą te dni, w które zabiorą wszystko do Babilonu, cokolwiek jest w domu twoim, i cokolwiek zachowali ojcowie twoi aż do dnia tego; nie zostanie nic, mówi Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Ale i synów twoich, którzy wyjdą z ciebie, których spłodzisz, pobiorą, i będą komornikami na dworze króla Babilińskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Tedy rzekł Ezechyjasz do Izajasza: Dobre jest słowo Pańskie, któreś mówił; (i dołożył: Dobre,) przeto, że pokój i prawda będzie za dni moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Cieszcie, cieszcie lud mój! mówi Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Mówcie do serca Jeruzalemu: ogłaszajcie mu, że się już dopełnił czas postanowiony jego, że jest odpuszczona nieprawość jego, i że wziął z ręki Pańskiej w dwójnasób za wszystkie grzechy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Głos wołającego na puszczy: Gotujcie drogę Pańską, prostą czyńcie na pustyni ścieszkę Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Każda dolina niech podniesiona będzie, a każda góra i pagórek niech poniżony będzie; co jest krzywego, niech się wyprostuje, a miejsca nierówne niech będą równiną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Bo się objawi chwała Pańska, a ujrzy wszelkie ciało społem, iż usta Pańskie mówiły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Głos mówiącego: Wołaj. I rzekł: Cóż mam wołać? To: Wszelkie ciało jest trawa, a wszystka zacność jego jako kwiat polny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Trawa usycha, kwiat opada; skoro wiatr Pański powionie nań; zaprawdęć ludzie są tą trawą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Trawa usycha, kwiat opada; ale słowo Boga naszego trwa na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Wstąp sobie na górę wysoką, Syonie! który opowiadasz rzeczy ucieszne. Podnieś mocno głos twój, Jeruzalemie! które opowiadasz rzeczy pocieszne; podnieś, nie bój się, rzecz miastom Judzkim: Oto Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Oto panujący Pan przyjdzie przeciwko mocnemu, a ramię jego panować będzie nad nim; oto zapłata jego z nim, a dzieło jego przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Jako pasterz trzodę swoję paść będzie; do naręcza swego zgromadzi baranki, i na łonie swem piastować je będzie, a kotne zwolna poprowadzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kto zmierzył wody garścią swoją, a niebiosa piędzią rozmierzył? a kto proch ziemi miarą zmierzył? kto zważył na wadze góry, a pagórki na szalach?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Któż doścignął ducha Pańskiego, a kto radcą jego był, żeby mu oznajmił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Z kim wszedł w radę, żeby mu rozumu przydał, a nauczył go ścieżek sądu? Kto go nauczył umiejętności, a drogę wszelakiej roztropności ukazał mu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Oto narody są jako kropla z wiadra, a jako proszek na szalach poczytane są; wyspy jako najmniejszą rzecz porywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'I Liban nie wystarczyłby ku wznieceniu ognia, i zwierzęta jego nie wystarczyłyby na całopalenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Wszystkie narody są jako nic przed nim; za nic i za marność poczytane są u niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Komuż tedy podobnym uczynicie Boga? A jakie podobieństwo przyrównacie mu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Rzemieślnik uleje bałwana a złotnik złotem go powlecze, i łańcuszki srebrne do niego odleje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'A ten, który dla ubóstwa nie ma co ofiarować, obiera drzewo, któreby nie próchniało, i rzemieślnika umiejętnego sobie szuka, aby wygotował bałwana rytego, któryby się nie poruszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Izali nie wiecie? Izali nie słyszycie? Izali się wam nie opowiada od początku? Izali nie zrozumiewacie od założenia gruntów ziemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Ten, który siedzi nad okręgiem ziemi, której obywatele są jako szarańcza; ten, który rozpostarł niebiosa jako cienkie płótno, a rozciągnął je, jako namiot ku mieszkaniu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Tenci książąt w niwecz obraca, sędziów ziemskich jako nic rozprasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Że nie bywają szczepieni ani wsiani, ani się też wkorzeni w ziemi pień ich; i jako jedno powienie na nich, wnet usychają, a wicher jako źdźbło unosi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Komuż mię tedy przyrównacie, abym mu był podobny? mówi Święty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Podnieście ku górze oczy wasze, a obaczcie! Kto to stworzył? kto wywiódł w poczcie wojsko ich, a to wszystko z imienia przyzywa, według wielkości siły, i wielkiej mocy, tak, że ani jedno z nich nie zginie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Przeczże tedy powiadasz, Jakóbie! przeczże tak mówisz Izraelu: Skryta jest droga moja przed Panem, a sprawa moja przed Boga mego nie przychodzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Izali nie wiesz? izaliś nie słyszał, że Bóg wieczny Pan, który stworzył granice ziemi, nie ustanie, ani się spracuje, i że nie może być dościgniona mądrość jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Który dodaje spracowanemu siły, a tego, który nie ma żadnej siły, moc rozmnaża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Młódź ustaje i omdlewa, a młodzieńcy w młodości upadają:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Ale którzy oczekują Pana, nabywają nowej siły; podnoszą się piórami jako orły, bieżą a nie spracują się, chodzą a nie ustawają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Umilknijcie przedemną, wyspy! a narody niech się posilą. Niech przystąpią a niech mówią: Przystąpmy społem do sądu');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Któż wzbudził od wschodu słońca sprawiedliwego, i wezwał go, aby go naśladował? Któż mu podbił narody, aby nad królami panował, podawszy je jako proch pod miecz jego, a jako plewy rozproszone pod łuk jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Uganiał się z nimi, przeszedł spokojnie ścieszkę, po której nogami swemi nie chadzał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Któż to sprawił i uczynił? któż wzywał rodzaje od początku? Ja Pan, pierwszy i ostatni, Ja sam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Widziały wyspy, i ulękły się; kończyny ziemi zdumiały się; zgromadziły się, i zeszły się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Jeden drugiemu pomagał, a bratu swemu mówił: Zmacniaj się!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'A tak zmacniał teszarz złotnika, blachę młotem gładzącego, kującego na kowadle, mówiąc: Do lutowania to dobre. Potem to stwierdził gwoździami, aby się nie ruszyło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Ale ty, Izraelu, sługo mój! ty Jakóbie, któregom obrał, nasienie Abrahama, przyjaciela mego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Ty, któregom pochwycił od kończyn ziemi, owszem, pominąwszy przedniejszych ich, powołałem cię mówiąc do ciebie: Sługaś ty mój, obrałem cię, a nie odrzuciłem cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Nie bój się! bom Ja z tobą. Nie lękaj się! bom Ja Bogiem twoim. Zmocnię cię, a dam ci pomoc, i podeprę cię prawicą sprawiedliwości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Oto zawstydzą się, a będą pohańbieni wszyscy gniewem pałający przeciwko tobie: staną się jako nic, i zginą ci, którzy się tobie sprzeciwiają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Szukałlibyś ich, nie znajdziesz ich; ci, którzy się sprzeciwiają tobie, będą jako nic, a ci, którzy walczą z tobą, w niwecz obróceni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Bom ja Pan, Bóg twój, trzymam cię za prawicę twoję, a mówięć: Nie bój się! Ja cię wspomogę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Nie bój się, robaczku Jakóbie, garstko ludu Izraelskiego! Jać będę na pomocy, mówi Pan a odkupiciel twój, Święty Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Otom cię uczynił jako wóz z zębami nowemi po obu stronach; i pomłócisz góry, a potrzesz je, a pagórki jako plewę położysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Przewiejesz je, wtem je wiatr porwie, a wicher rozproszy je; ale się ty rozradujesz w Panu, w Świętym Izraelskim będziesz się chlubił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Ubogich i nędznych, którzy szukają wody, a niemasz jej, których język usechł od pragnienia, Ja Pan wysłucham ich; Ja, Bóg Izraelski, nie opuszczę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Otworzę rzeki na miejscach wysokich, a źródła w pośród równin; obrócę pustynie w jeziora wód, a ziemię suchą w strumienie wód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Nasadzę na puszczy cedrów, wybornych cedrów, sosien, i oliwnych drzew; nasadzę pustynię jedliną, wiązem, i bukszpanem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Aby widzieli, i poznali, i uważali, i zrozumieli, że to ręka Pańska uczyniła, i że to Święty Izraelski stworzył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Przedłóżcie sprawę waszę, mówi Pan; ukażcie mocne dowody swoje, mówi król Jakóbowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Niech przystąpi, a niech nam oznajmi to, co się ma stać; rzeczy pierwsze, które były, powiedzcie, abyśmy uważyli w sercu swem, a poznali cel ich; albo przynajmniej nam przyszłe rzeczy oznajmijcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Oznajmijcie, co ma przyjść napotem, a poznamy, żeście bogowie; albo uczyńcie co dobrego lub złego, abyśmy się zdumiewali, gdybyśmy to społem widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Otoście wy zgoła na nic, a sprawa wasza także na nic nie jest; przetoż obrzydły jest ten, co was sobie obiera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Wzbudzę od północy lud, ten przyciągnie; i od wschodu słońca, ten wzywać będzie imienia mego; oborzy się na książąt jako na błoto, a podepcze ich, jako garncarz glinę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kto oznajmi od początku? tedy będziemy wiedzieli; albo co było od dawnych czasów? tedy rzeczemi: Tyś jest sprawiedliwy? Niemasz zgoła nikogo, coby oznajmił, ani jest, ktoby się dał słyszeć, albo ktoby słyszał mowy wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Jam pierwszy, który Syonowi opowiadam: Oto, oto są; a Jeruzalemowi dam opowiadaczy rzeczy pociesznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Bo widzę, że niemasz nikogo, niemasz nikogo między nimi, coby dał radę; acz się ich pytają, wszakże nie odpowiadają i słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Oto ci wszyscy są marnością, za nic nie stoją uczynki ich; wiatrem i próżnością są odlewane bałwany ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Oto sługa mój, spolegać będę na nim, wybrany mój, którego sobie upodobała dusza moja. Dam mu Ducha swego, on sąd narodom wyda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Nie będzie wołał, ani się będzie wywyższał, ani będzie słyszany na ulicy głos jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Trzciny nałamanej nie dołamie, a lnu kurzącego się nie dogasi; ale sąd wyda według prawdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Nie zamroczy się, ani ustanie, dokąd nie wykona sądu na ziemi, a nauki jego wyspy oczekiwać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Tak mówi Bóg, Pan, który stworzył niebiosa i rozpostarł je; który rozszerzył ziemię, i co się rodzi z niej; który daje tchnienie ludowi mieszkającemu na niej, a ducha tym, co chodzą po niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Ja Pan wezwałem cię w sprawiedliwości, i ująłem cię za rękę twą; przetoż strzedz cię będę, i dam cię za przymierze ludowi, i za światłość narodom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Aby otwierał oczy ślepych, a wywodził więźniów z ciemnicy, i z domu więzienia siedzących w ciemnościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Ja Pan, toć jest imię moje, a chwały mojej nie dam innemu, ani sławy mojej bałwanom rytym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Oto pierwsze rzeczy przyszły, Ja też nowe opowiadam, pierwej, niż się zaczną, dam wam o nich słyszeć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Śpiewajcie Panu pieśń nową, chwała jego jest od kończyn ziemi, którzy się pławicie po morzu, i wszystko, co w niem jest, wyspy i obywatele ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Podnieście głos pustynie, i miasta jej, i wsi, w których mieszka Kedar; wykrzykajcie obywatele skał, z wierzchu gór wołajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Oddajcie cześć Panu, a chwałę jego na wyspach opowiadajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Pan wynijdzie jako mocarz, jako mąż waleczny wzruszy się gorliwością; trąbić, owszem krzyczeć będzie, a przeciw nieprzyjaciołom swoim mężnie sobie pocznie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Mówiąc: Milczałem dość długo, jakobym nie słyszał, wstrzymywałem się; ale już jako rodząca krzyczeć będę, spustoszę, i wszystkich oraz połknę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'W pustynie góry i pagórki obrócę, i wszystkie zioła ich posuszę; obrócę i rzeki w wyspy, a jeziora wysuszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'I powiodę ślepych drogą, której nie znali, a ścieszkami, o których nie wiedzieli, poprowadzę ich; obrócę przed nimi ciemności w światłość, a co nierównego, w równinę. Toć jest, co im uczynię, a nie opuszczę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Cofną się nazad, i zawstydzą się bardzo, którzy ufają w bałwanach rytych, którzy mówią obrazom litym: Wyście bogowie nasi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'O głusi! słuchajcie; a wy ślepi! przejrzyjcie, abyście widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Któż ślepy, jedno sługa mój? a kto głuchy, jedno poseł mój, którego posyłam? Któż tak ślepy jako doskonały, ślepy, mówię, jako sługa Pański?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Widzi wiele rzeczy, a wszakże nie zrozumiewa; otworzone ma uszy, wszakże nie słyszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Pan go sobie upodobał dla sprawiedliwości swojej; uwielbił go zakonem, i sławnym go uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Ale ten lud jest złupiony i rozszarpany, którego młodzieńców ile ich kolwiek jest, imają, i do ciemnic podawają; podani są na łup, a niemasz ktoby ich wybawił; podani są na rozchwycenie, ani jest, ktoby rzekł: Wróć ich zaś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Któż to z was w uszy przyjmuje? kto zrozumiewa, aby czulszym był napotem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kto podał na rozszarpanie Jakóba, a Izraela łupieżcom? Izali nie Pan, przeciwko któremuśmy zgrzeszyli? Bo nie chcieli drogami jego chodzić, ani słuchać zakonu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Dlatego nań Pan wylał popędliwość gniewu swego, i gwałtowną wojnę, a zapalił go w około, a wszakże nie poznał tego; zapalił go, mówię, a wszakże tego do serca nie przypuścił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Ale teraz tak mówi Pan, który cię stworzył, o Jakóbie; i który cię uczynił, o Izraelu! Nie bój się, bom cię odkupił, a wezwałem cię imieniem twojem; mójeś ty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Gdy pójdziesz przez wody, będę z tobą, a jeźli przez rzeki, nie zaleją cię; pójdzieszli przez ogień, nie spalisz się, a płomień nie imie się ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Bom Ja Pan, Bóg twój,Święty Izraelski, zbawiciel twój. Dałem za cię na okup Egipt, ziemię Murzyńską, i Sabę miasto ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Zaraz jakoś drogim uczyniony przed oczyma memi, jesteś uwielbionym, a Jam cię umiłował; przetoż dałem ludzi za cię, i narody za żywot twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Nie bój się, bom Ja z tobą; od wschodu słońca przyprowadzę zaś nasienie twoje, i od zachodu zgromadzę cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Rzekę północnej stronie: Wróć: a południowi: Nie zabraniaj. Przywiedź zasię synów moich z daleka, a córki moje od kończyn ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'Każdego, który się nazywa imieniem mojem, i któregom ku chwale swojej stworzył, któregom ukształtował, i któregom uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Wywiedź lud ślepy, który już ma oczy i głuchy, który już ma uszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Wszystkie narody niech się społu zejdą, i niech się zgromadzą ludzie. Któż jest między nimi, coby to opowiedział, a przeszłe rzeczy nam oznajmił? Niech stawią świadków swoich, a będą usprawiedliwieni; albo niech słyszą i rzekną: Prawdać jest!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Wyście świadkowie moi, mówi Pan, i sługa mój, któregom obrał, abyście wiedzieli i wierzyli mi, i zrozumieli, żem Ja jest, a że przedemną nie był stworzony Bóg, ani po mnie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Ja, Jam jest Pan, a niemasz oprócz mnie zbawiciela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Ja oznajmuję i wyswabadzam, i opowiadam, a niemasz nikogo między wami z obcych bogów; i wyście mi tego świadkami, mówi Pan, żem ja Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Pierwej niż dzień był, Jam jest, a niemasz, ktoby wyrwał z ręki mojej; gdy co uczynię, i któż to odwróci?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Tak mówi Pan, odkupiciel wasz, Święty Izraelski: Dla was poślę do Babilonu, i oderwę wszystkie zawory, i Chaldejczyków z okrętami, w których się oni chlubią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Jam jest Pan, Święty wasz; Stworzyciel Izraelowy, Król wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Tak mówi Pan, który sposobił na morzu drogę, i ścieszkę na bystrych wodach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'Który wywodzi wozy i konie, wojsko i siłę; czyni, że oraz upadają, a nie powstawają: gasną jako knot gaśnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Nie wspominajcie pierwszych rzeczy, a starodawnych nie uważajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Oto Ja czynię rzecz nową, a zaraz się zjawi; izali tego nie poznacie Nadto sposobię na puszczy drogę, a na pustyni rzeki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Chwalić mię będzie zwierz polny, smoki, i sowy, żem wywiódł na puszczy wody, a rzeki na pustyni, abym dał napój ludowi memu, wybranemu ludowi memu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Lud ten, którym sobie stworzył, chwałę moję opowiadać będzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'A tyś mię nie wzywał, o Jakóbie! owszemeś sobie utęsknił ze mną, o Izraelu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Nie przywiodłeś mi bydlątka na całopalenie twoje, i ofiarami twemi nie uczciłeś mię; nie przymuszałem cię, abyś mi służył ofiarami śniednemi, anim cię obciążał tem, abyś mi kadził;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Nie kupiłeś mi za pieniądze wonnych rzeczy, aniś mię tłustością ofiar twoich opoił; aleś mię obciążył grzechami twemi, a zadałeś mi pracę nieprawościami twojemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Ja, Ja sam gładzę przestępstwa twoje dla siebie, a grzechów twoich nie wspomnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Przywiedź mi na pamięć, sądźmy się społu; powiedz ty, maszli, czembyś się usprawiedliwił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Ojciec twój pierwszy zgrzeszył, a nauczyciele twoi wystąpili przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'A tak zrzucę książąt z miejsc świętych, i podam na przeklęstwo Jakóba, a Izraela na pohańbienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'A teraz słuchaj Jakóbie sługo mój! i ty, Izraelu! któregom wybrał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Tak mówi Pan, który cię uczynił, i który cię ukształtował zaraz z żywota matki, i który cię wspomaga: Nie bój się Jakóbie, sługo mój! i uprzejmy, któregom wybrał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Bo wyleję wody na pragnącego, a potoki na suchą ziemię; wyleję Ducha mego na nasienie twoje, i błogosławieństwo moje na potomki twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'I rozkrzewią się jako między trawą, i jako wierzby przy ciekących wodach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Ten rzecze: Jam jest Pański, a ów się ozowie do imienia Jakóbowego, a inny się zapisze ręką swą Panu, i imieniem Izraelskim będzie się nazywał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Tak mówi Pan, król Izraelski, i odkupiciel jego, Pan zastępów: oprócz mnie niemasz Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Bo któż jako Ja ogłasza i opowiada to, i sporządza mi to, zaraz od onego czasu, jakom rozsądził lud na świecie? a kto przyszłe rzeczy, i to, co ma być, oznajmi im?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Nie bójcież się, ani sobą trwożcie. Izalim wam tego z dawna nie oznajmił, i nie opowiedział? Tegoście wy mnie sami świadkami. Izali jest Bóg oprócz mnie? Niemasz zaiste skały; Ja o żadnej nie wiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Tworzyciele bałwanów wszyscy nic nie są, i te najmilsze rzeczy ich nic im nie pomogą; czego oni sobie sami świadkami będąc, nic nie widzą, ani rozumieją, żeby się wstydzić mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Kto tworzy boga, i bałwana leje, do niczego się to nie przygodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Oto wszyscy, i uczestnicy ich będą pohańbieni; owszem, rzemieślnicy ich, ci nad innych ludzi, choćby się wszyscy zebrali i stanęli, lękać się muszą, i społem pohańbieni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Kowal kleszczami robi przy węglu, a młotami kształtuje bałwana; gdy go robi mocą ramienia swego, aż od głodu w nim i siły ustają, ani pije wody, aż i omdlewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Cieśla zaś rozcięga sznur, znaczy sznurem farbowanym, i ociosuje toporem, i cyrklem rozmierza go, i czyni go na podobieństwo męża, i na podobieństwo pięknego człowieka, aby mieszkał w domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Narąbie sobie cedrów, i bierze cyprys i dąb, albo to, co jest najmocniejszego między drzewem leśnem, albo wsadzi jawór, który za deszczem odrasta;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'I używa tego człowiek do palenia, albo wziąwszy z niego, ogrzewa się przy nim, także roznieca ogień, aby napiekł chleba, nadto z tegoż drzewa robi sobie boga, i kłania mu się; czyni z niego bałwana, i klęka przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Część jego pali ogniem, przy drugiej części jego mięso je, piecze pieczeń i nasycony bywa; także rozgrzewa się, i mówi: Ehej! rozgrzałem się, widziałem ogień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'A z ostatku jego czyni boga, bałwana swego; klęka przed nim, kłania się, i modli mu się, mówiąc: Wybaw mię, boś ty bóg mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Nie wiedzą, ani rozumieją, przeto, że Bóg zaślepił oczy ich, aby nie widzieli, i serca ich, aby nie rozumieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'I nie uważają tego w sercu swojem, nie mająż to umiejętności ani baczenia, aby rzekli: Część z niego spaliłem ogniem, a przy węglu jego napiekłem chleba, upiekłem mięso, i najadłem się; i mamże ja z ostatku jego obrzydliwość uczynić, a przed kloc em drewnianym klękać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Taki się karmi popiołem, serce jego zwiedzione unosi go, aby nie mógł wybawić duszy swojej, ani rzec: Izali to nie jest oszukanie, co jest w prawicy mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Pomnijże na to, Jakóbie i Izraelu! przeto, żeś ty jest sługą moim. Stworzyłem cię, sługaś ty mój; o Izraelu! nie zapomnę na cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Gładzę nieprawości twoje jako obłok, a grzechy twoje jako mgłę; nawróć się do mnie, bom cię odkupił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Śpiewajcie niebiosa, bo to Pan uczynił; wykrzykajcie niskości ziemi, zabrzmijcie chwałę góry, las, i wszystkie drzewa w nim; albowiem Pan odkupił Jakóba, a w Izraelu sławnym się uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Tak mówi Pan, odkupiciel twój, i który cię utworzył wnet z żywota matki: Ja Pan wszystko czynię, sam rozciągam niebiosa, rozpościeram ziemię mocą swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Wniwecz obracam znamiona praktykarzów, i wieszczków do szaleństwa przywodzę; i mędrców na wstecz obracam, a umiejętność ich głupią czynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Potwierdzam słowa sługi swego, a radę posłów swych wykonywam. Który mówię o Jeruzalemie: Mieszkać w niem będę; a o miastach Judzkich: Pobudowane będą; bo spustoszenia ich pobuduję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Który mówię głębinie: Wyschnij, Ja potoki twe wysuszę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Który mówię o Cyrusie: On pasterz mój, bo wszystkę wolę moję wykona; i rzecze Jeruzalemowi: Będziesz zbudowane; a kościołowi: Będziesz założony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'To mówi Pan pomazańcowi swemu Cyrusowi, którego prawicę ujmę, a porażę przed nim narody, i biodra królów rozpaszę, a pootwieram przed nim wrota, i bramy nie będą zamknięte.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Ja przed tobą pójdę, a krzywe drogi wyprostuję, wrota miedziane skruszę, a zawory żelazne porąbię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'I dam ci skarby skryte, i klejnoty schowane, abyś poznał, żem Ja Pan, Bóg Izraelski, który cię przyzywam imieniem twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Dla sługi mego Jakóba, i dla Izraela, wybranego mego, nazwałem cię imieniem twojem, przezwiskiem twojem, chociaż mię nie znasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Jam Pan, a niemasz żadnego więcej, oprócz mnie niemasz żadnego Boga; przepasałem cię, aczkolwiek mię nie znasz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Aby poznali od wschodu słońca, i od zachodu słońca, iż niemasz żadnego oprócz mnie, Jam Pan, a niemasz żadnego więcej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Który czynię światłość, i stwarzam ciemności; sprawuję pokój, i stwarzam złe. Ja Pan czynię to wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Spuście niebiosa rosę z góry, a obłoki niech kropią sprawiedliwość; niech się otworzy ziemia, a niech wyrośnie zbawienie, a sprawiedliwość niech wespół zakwitnie. Ja Pan sprawię to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Biada temu, który się spiera z stworzycielem swoim, będąc skorupą, jako inne skorupy gliniane. Izali glina rzecze garncarzowi swemu: Cóż czynisz? Robota twoja zaprawdę nikczemna jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Biada temu, który mówi ojcu: Cóż płodzisz? a niewieście: Cóż porodzisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Tak mówi Pan, Święty Izraelski, i Twórca jego: O przyszłe rzeczy pytajcie mię, a synów moich, i sprawę rąk moich poruczajcie mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Jam uczynił ziemię, i człowiekam na niej stworzył. Jam jest, którego ręce rozciągnęły niebiosa, a wszystkiemu wojsku ich rozkazuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Jam go wzbudził w sprawiedliwości, i wszystkie drogi jego wyprostuję. Onci zbuduje miasto moje, a więźniów moich wypuści, nie za okup, ani za dar, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Tak mówi Pan: Praca Egipska, i kupiectwo Murzynów, i Sebejczyków, mężowie wysocy do ciebie przyjdą, a twoi będą; za tobą chodzić będą, w pętach pójdą, tobie się kłaniać, i tobie się korzyć będą, mówiąc: Tylko w tobie jest Bóg, a niemasz żadnego więcej, oprócz tego Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Zaprawdę tyś jest Bóg skryty, Bóg Izraelski, zbawiciel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Wszyscy się oni zawstydzą, i pohańbieni będą; czyniciele bałwanów społu z hańbą odstąpią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Ale Izrael zbawion będzie przez Pana zbawieniem wiecznem; nie zawstydzicie się, ani będziecie pohańbieni, aż na wieki wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Bo tak mówi Pan, który stworzył niebiosa (ten Bóg, który stworzył ziemię, i uczynił ją! który ją utwierdził, nie na próżno stworzył ją, na mieszkanie utworzył ją): Jam Pan, a niemasz żadnego więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Nie mówiłem potajemnie na miejscu ziemskiem ciemnem; nie na próżno mówię nasieniu Jakóbowemu: Szukajcie mię. Ja Pan mówię sprawiedliwość, a zwiastuję prawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Zgromadźcie się, a przyjdźcie; przybliżcie się wespół, wy, którzyście pozostali między poganami. Nic nie wiedzą, którzy się z drewnianemi bałwanami swemi noszą; bo się modlą bogu, który nie może wybawić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Oznajmujcież a przywiedźcie innych, a niech pospołu w radę wnijdą, a ukażą, kto to od dawnego czasu przepowiedział? kto od onego czasu oznajmił? Izali nie Ja Pan? Boć niemasz żadnego innego Boga oprócz mnie. Niemasz Boga sprawiedliwego, i zbawiciela innego oprócz mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Obejrzyjcież się na mię, abyście zbawione były wszystkie kończyny ziemi; bom Ja Bóg, a niemasz żadnego więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Przysiągłem sam przez się; wyszło z ust moich słowo sprawiedliwe, które się nazad nie wróci: Że się mnie kłaniać będzie wszelkie kolano, i przysięgać każdy język.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Mówiąc: Tylko w Panu mam wszelką sprawiedliwość i siłę. Takowi aż do niego przyjdą; ale pohańbieni będą wszyscy, którzy się gniewem zapalają przeciwko niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'W Panu usprawiedliwione będzie, i przechwalać się będzie wszystko nasienie Izraelskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Pochylił się Bel, upadł Nebo; bałwany ich włożone są na bestyje, i na bydlęta; tem zaiste, co wy nosicie, będą bardzo obciążone aż do ustania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Pochyliły się, i upadły społem, i Babilończycy nie będą mogli ratować brzemion; owszem, i dusza ich w niewolę pójdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Słuchajcie mię, domie Jakóbowy, i wszystkie ostatki domu Izraelskiego! które noszę zaraz z żywota, które piastuję zaraz od narodzenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Ja sam aż do starości, i owszem aż do sędziwości was nosić będę. Jam was uczynił, Ja też nosić będę; Ja mówię nosić was będę, i wybawię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Komuż mię przypodobacie, i przyrównacie, albo podobnym uczynicie, żebym mu był podobny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Ci, którzy marnie wydawają złoto z worka, a srebro na szalach ważą, najmują za zapłatę złotnika, aby uczynił z niego boga, przed którym padają i kłaniają się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Noszą go na ramieniu, dźwigają go, i stawiają go na miejscu jego. I stoi, a z miejsca swego się nie ruszy; jeźli kto zawoła do niego, nie ozywa się, ani go z utrapienia jego wybawia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Pamiętajcież na to, a wstydźcie się; przypuśćcie to do serca, o przestępnicy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Wspomnijcie sobie na rzeczy pierwsze, które się działy od wieku; bom Ja Bóg, a niemasz żadnego Boga więcej, i niemasz mnie podobnego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Który opowiadam od początku rzeczy ostatnie, i zdawna to, co się jeszcze nie stało; rzekęli co, rada moja ostoi się, i wszystkę wolę moję uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Który zawołam od wschodu słońca ptaka, z ziemi dalekiej tego, któryby wykonał radę moję. Rzekłem, a dowiodę tego; umyśliłem, a uczynię to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Słuchajcie mię, wy upornego serca, którzy jesteście dalekimi od sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Sprawię, że się przybliży sprawiedliwość moja, nie pójdzie w długą, a zbawienie moje nie omieszka; bo położę w Syonie zbawienie, a w Izraelu sławę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Zstąp, a usiądź w prochu, panno, córko Babilońska! siądź na ziemi, a nie na stolicy, córko Chaldejska! bo cię nie będą więcej nazywać kochanką i rozkosznicą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Weźmij żarna, a miel mąkę; odkryj warkocze swoje, obnaż nogi, odkryj golenie, brnij przez rzekę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Odkryta będzie nagość twoja, a hańba twoja widziana będzie; wezmę pomstę z ciebie, a nie dam się nikomu zahamować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'To mówi odkupiciel nasz, imię jego Pan zastępów, Święty Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Siedź milcząc, a wnijdź do ciemności, córko Chaldejska! bo cię więcej nie będą nazywać panią królestw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Rozgniewałem się był na lud mój, splugawiłem dziedzictwo moje, a dałem je w ręce twoje; aleś im ty nie okazała miłosierdzia, i starców obciążałaś jarzmem twojem bardzo,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'I rzekłaś: Na wieki panią będę; i tak nie przypuściłaś tego do serca swego, aniś sobie przywodziła na pamięć dokończenia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Przetoż słuchaj tego teraz, rozkosznico! (która mieszkasz bezpiecznie, a mówisz w sercu swem: Jam jest, a niemasz oprócz mnie innej, nie będę wdową, ani uznam sieroctwa;)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Że to oboje przyjdzie na cię nagle dnia jednego, sieroctwo i wdowstwo, a doskonale przypanie na cię dla mnóstwa guseł twoich, i dla wielkości czarów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Bo ufasz w złości twojej, a mówisz: Nie widzi mię nikt. Mądrość twoja i umiejętność twoja, ta cię przewrotną uczyniła, abyś mówiła w sercu swem: Jam jest, a niemasz oprócz mnie innej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Dlatego przyjdzie na cię złe, którego wyjścia nie wiesz, i przypadnie na cię bieda, której nie będziesz mogła zbyć; a przyjdzie na cię nagle spustoszenie, nim wzwiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Stańże teraz z czarami swemi, i z mnóstwem guseł twoich, któremiś się parała od młodości twojej, azażbyś co sobie mogła pomódz, albo się snać czem zmocnić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Ustawasz z mnóstwem rad twoich; niechajże teraz staną praktykarze, którzy się przypatrują gwiazdom, którzy dawają znać, co ma być każdego miesiąca, a niech cię wybawią z tego, co ma przyjść na cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Oto są jako plewa; ogień popali ich, nie wybawią ani duszy swej z mocy płomienia; nie zostanie węgla do ogrzania się, ani ognia, coby posiedzieć przy nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Takci się stanie kupcom twoim, z którymiś się zabawiała od młodości twojej: każdy się z nich w swą stronę uda, nie będzie, ktoby cię wybawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Słuchajcie tego, domie Jakóbowy! którzy się nazywacie imieniem Izraelowem, a poszliście z wód Judzkich; którzy przysięgacie przez imię Pańskie, a Boga Izraelskiego przypominacie, ale nie w prawdzie ani w sprawiedliwości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Aczkolwiek od miasta świętego mianujecie się, a na Bogu Izraelskim spolegacie, Pan zastępów imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Pierwsze rzeczy z dawnam opowiadał, a co z ust moich wyszło i com ogłaszał, naglem czynił, i przychodziło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Wiedziałem, żeś ty twardy, a szyja twoja żyłą żelazną, a czoło twoje miedziane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Przetoż oznajmiałem ci z dawna; pierwej niż się co stało, ogłaszałem, byś snać nie rzekł: Bałwan mój uczynił to, a obraz mój albo ulanie moje rozkazało to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Słyszałeś o tem, spojrzyjże na to wszystko; a wy izali tego nie opowiecie? Teraz już ogłaszam nowe i tajemne rzeczy, i o którycheś nie wiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Teraz stworzone są, a nie onego czasu, o którycheś przed tym dniem nic nie słyszał, byś snać nie rzekł: Otom wiedział o tem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Owszem aniś słyszał, aniś wiedział; ani się to w on czas doniosło ucha twego; bom wiedział, że zapewne wystąpisz, a że przestępcą będziesz zaraz z żywota matki twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Dla imienia mego zatrzymam popędliwość moję, a dla chwały mojej zahamuję gniew przeciwko tobie, abym cię nie wygładził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Oto wypławię cię, ale nie jako srebro; przebiorę cię w piecu utrapienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Sam dla siebie, dla siebie to uczynię; bo jakożby miało być splugawione imię moje? Zaiste chwały mojej nie dam innemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Słuchaj mię, Jakóbie i Izraelu, wezwany mój! Jam jest, Jam pierwszy, Jam i ostateczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'A ręka moja założyła ziemię, i prawica moja piędzią rozmierzyła niebiosa; zawołałem je, a zaraz stanęły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Zbierzcie się wszyscy, a słuchajcie. Któż z nich to opowiedział? Pan umiłował go, on wykona wolę jego nad Babilonem, a ramię jego przeciw Chaldejczykom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Ja, Jam mówił; przetoż wezwę go, przywiodę go, a poszczęści mu się droga jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Przybliżcie się do mnie, a słuchajcie tego! Nie mówiłem od początku w skrytości; ale od onegoż czasu, którego się to działo, tamem był. A teraz panujący Pan posłał mię, i duch jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Tak mówi Pan, odkupiciel twój, Święty Izraelski: Jam Pan, Bóg twój, który cię uczę, abyś postępował; a prowadzę cię drogą, po której chodzić masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'Obyżeś był pilnował przykazania mego! byłby jako rzeka pokój twój, a sprawiedliwość twoja jako wały morskie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'A nasienie twoje byłoby jako piasek, a płód żywota twego jako drzastwo jego; a nie byłoby wycięte ani wygładzone imię jego przed obliczem mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Wynijdźcie z Babilonu, ucieczcie od Chaldejczyków; głosem to rozsławiajcie, rozgłaszajcie to, roznaszajcie to, aż do kończyn ziemi; mówcie: Pan odkupił sługę swego Jakóba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Nie upragną, gdy ich przez pustynie powiedzie; wody z skały wywiedzie im; bo rozszczepi opokę, i wypłyną wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Niemasz pokoju niepobożnym, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Słuchajcie mię wyspy, a narody dalekie pilnujcie! Pan zaraz z żywota wezwał mię, zaraz z żywota matki mojej uczynił wzmiankę imienia mego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'I uczynił usta moje jako miecz ostry, w cieniu ręki swej zakrył mię, a uczyniwszy mię strzałą wypolerowaną, do sajdaku swego schował mię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'I rzekł mi: Sługaś ty mój, w Izraelu tobą się chlubić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'A Jam rzekł: Nadarmom pracował, próżnom i daremnie zniszczył siłę moję; wszakże sąd mój jest u Pana, a praca moja u Boga mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'A teraz mówi Pan, który mię zaraz z żywota za sługę sobie utworzył, abym zaś przywiódł do niego Jakóba. (Choćby Izrael nie był zebrany, sławnym jednak będę przed oczyma Pańskiemi; albowiem Bóg mój jest siłą moją.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'I rzekł: Małoby mi to było, abyś mi był sługą ku podźwignieniu pokoleń Jakóbowych, i ku nawróceniu ostatków z Izraela; przetoż dałem cię za światłość poganom, abyś był zbawieniem mojem aż do kończyn ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Tak mówi Pan, odkupiciel Izraelowy, Święty jego, do tego, którym każdy gardzi, a którym się brzydzą narody, do sługi panujących: Królowie widząc cię powstaną, a książęta kłaniać ci się będą dla Pana, który jest wierny, dla Świętego Izraelskiego, który cię obrał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Tak mówi Pan: Czasu przyjemnego wysłucham cię, a w dzień zbawienia poratuję cię; nadto strzedz cię będę, i dam cię za przymierze ludowi, abyś utwierdził ziemię, a podał w osiadłość dziedzictwa spustoszałe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Abyś mówił więźniom: Wynijdźcie; a tym, co są w ciemnościach: Okażcie się. Podle dróg paść się będą, a po wszystkich miejscach wysokich będą pastwiska ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Nie będą łaknąć, ani pragnąć, i nie uderzy na nich gorącość, ani słońce, bo ten, który ma litość nad nimi, poprowadzi ich, i podle źródeł wód powiedzie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Nadto sposobię na wszystkich górach moich drogę, a gościńce moje będą powyższone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Oto ci z daleka przyjdą, a oto drudzy od północy i od morza, a drudzy z ziemi Synim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Śpiewajcie niebiosa, rozraduj się ziemio, i głośno zabrzmijcie góry! albowiem Pan pocieszył lud swój, a nad ubogimi swoimi zmiłował się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Ale Syon rzekł: Opuścił mię Pan, a Pan zapomniał na mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Izali może zapomnieć niewiasta niemowlątka swego, aby się nie zlitowała nad płodem żywota swego? A choćby też i one zapomniały, wszakże Ja ciebie nie zapomnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Oto na dłoniach swoich wyrysowałem cię; mury twoje zawżdy są przedemną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Pospieszą się do ciebie synowie twoi, a ci, którzy cię burzyli i kazili, odejdą od ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Podnieś w około oczy swe, a obacz; ci wszyscy zgromadziwszy się przyjdą do ciebie. Jakom żywy Ja, mówi Pan, że tymi wszystkimi jako ochędóstwem przyodziejesz się, i obłożysz się nimi jako oblubienica;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Przeto, że pustynie twoje, i spustoszałe miejsca twoje, i ziemia zburzenia twego teraz będą ciasne dla obywateli, gdyż oddaleni będą ci, którzy cię pożerali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Tak, że rzeką w uszy twoje synowie sieroctwa twego: Ciasne mi jest to miejsce; ustąpże mi, abym mieszkać mógł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'I rzeczesz w sercu swem: Któż mi tych napłodził? bom ja była osierociała, i samotna, wygnanam była, i tułałam się; któż wżdy tych odchował? Otom Ja tylko sama pozostała była, gdzież ci byli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Tak mówi panujący Pan: Oto wzniosę na narody rękę moję, a do ludzi podniosę choręgiew moję, aby przynieśli synów twoich na ręku, i córki twoje aby na ramionach przynoszone były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'I będą królowie piastunami twoimi, a księżny ich mamkami twemi; twarzą ku ziemi kłaniać ci się będą, i proch nóg twoich lizać będą; a dowiesz się, żem Ja Pan, a iż nie bywają zawstydzeni, którzy na mię oczekują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'I rzeczesz: Izali korzyść od mocarza odjęta będzie? Izali pojmany lud sprawiedliwego wybawiony będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Owszem, tak mówi Pan: I pojmany lud mocarzowi odjęty będzie, i korzyść okrutnikowi wydarta będzie; albowiem przeciwnikowi twemu Ja się sprzeciwię, a synów twoich Ja wyswobodzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'I tych, którzy cię pustoszą, własnem ich ciałem nakarmię, a krwią swoją jako moszczem upiją się. I pozna wszelkie ciało, żem Ja Pan, zbawiciel twój, i odkupiciel twój, mocny Jakóbowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Tak mówi Pan: Gdzie jest list rozwodny matki waszej, którymem ją wolno puścił? albo kto jest z pożyczalników moich, któremum was zaprzedał? Otoście nieprawościami swojemi sami siebie zaprzedali, a dla przestępstw waszych wolno puszczona jest matka wasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Przeczże, gdy przychodzę, niemasz nikogo? a gdy wołam, nikt się nie ozywa? Izali tak jest ukrócona ręka moja, aby nie mogła odkupić? Izali niemasz we mnie mocy ku wybawieniu? Oto fukiem moim osuszam morze, obracam rzeki w pustynie, tak iż zaśmier dną ryby ich dla niedostatku wody, i zdychają od pragnienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Obłoczę niebiosa w ciemności, a wór daję za odzienie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Panujący Pan dał mi język umiejętny, abym umiał czasu przygodnego mówić słowo upracowanemu. Budzi mię na każdy zaranek, pobudza uszy moje, abym słuchał tak jako uczący się pilnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Panujący Pan otwiera mi uszy, a Ja się nie sprzeciwiam, ani się na wstecz wracam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Ciała mego nadstawiam bijącym, a policzków moich tym, którzy mię targają; twarzy mojej nie zakrywam od obelżenia i plwania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Bo panujący Pan wspomaga mię; przetoż nie bywam pohańbiony. Dla tego postawiłem twarz moję jako krzemień, gdyż wiem, że pohańbiony nie będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Bliskoć jest ten, który mię usprawiedliwia. Któż się sprzeczać będzie ze mną? Stańmy społem; kto ma prawo ze mną, niech przystąpi ku mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Oto panujący Pan pomagać mi będzie; któż jest, coby mię potępił? Oto wszyscy takowi jako odzienie zwiotszeją, a mól zgryzie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kto jest między wami bojący się Pana, posłuchaj głosu sługi jego; kto jest, co chodzi w ciemnościach a nie ma światłości? ufaj w imieniu Pańskiem, a spolegaj na Bogu swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Oto wy wszyscy, którzy rozniecacie ogień, a przepasujecie się iskrami, chodźcież w światłości ognia waszego, i w iskrach, któreście rozniecili; z ręki mojej wam się to stanie, że w boleści leżeć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Słuchajcie mię, którzy naśladujecie sprawiedliwości, którzy szukacie Pana. Spojrzyjcie na skałę, z którejście wycięci, i na głębokość dołu, skądeście wykopani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Spojrzyjcie na Abrahama, ojca waszego, i na Sarę, która was porodziła, żem go jednego wezwał, i pobłogosławiłem mu, a rozmnożyłem go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Gdyż pocieszy Pan Syon, pocieszy wszystkie pustynie jego, a uczyni puszczę jego bardzo rozkoszną, a pustynię jego jako ogród Pański, radość i wesele znajdzie się w nim, dziękczynienie, i głos śpiewania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Pilnujcie mię, ludu mój i rodzino moja! nadstawcie mi uszów; bo zakon odemnie wyjdzie, a sąd mój za światłość narodom wystawię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Blisko jest sprawiedliwość moja, wynijdzie zbawienie moje, a ramiona moje narody sądzić będą. Na mię wyspy oczekują, a po ramieniu mojem tęsknią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Podnieście ku niebu oczy wasze, a spojrzyjcie na ziemię na dół. Niebiosa jako dym zniszczeją, a ziemia jako odzienie zwiotszeje, i obywatele jej, jako i ona zginą; ale zbawienie moje na wieki będzie, a sprawiedliwość moja nie ustanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Słuchajcie mię, którzy znacie sprawiedliwość ludu, w którego sercu jest zakon mój! Nie bójcie się urągania ludzkiego, a sromocenia ich nie lękajcie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Albowiem ich mól jako szatę pożre, a robak ich jako wełnę pogryzie; ale sprawiedliwość moja na wieki będzie, a zbawienie moje od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Ocuć się, ocuć się, oblecz się w siłę, o ramię Pańskie! Ocuć się jako za dni dawnych, i za rodzajów przeszłych! Izaliś nie ty jest, któreś zgładziło Egipt, i zraniło smoka?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Izaliś nie ty jest, któreś wysuszyło morze, wody przepaści wielkiej? któreś obróciło głębokości morskie w drogę, aby przeszli wybawieni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'A tak ci, których odkupił Pan, niech się nawrócą, i przyjdą do Syonu z śpiewaniem, a wesele wieczne niech będzie nad głową ich; wesela i radości niech dostąpią, a niech uciecze smutek i wzdychanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Ja, Jam jest pocieszyciel wasz. Któżeś ty, że się boisz człowieka śmiertelnego, i syna człowieczego trawie podobnego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Że zapominasz na Pana stworzyciela swego, który rozciągnął niebiosa, i założył ziemię? a że się lękasz ustawicznie każdego dnia popędliwości trapiącego, gdy się gotuje, aby zatracał? Ale gdzież jest ta popędliwość trapiącego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Pospieszy się, aby więzień był uwolniony; bo nie umrze w dole, ani będzie miał jaki niedostatek chleba swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Ja zaiste jestem Pan, Bóg twój, który rozdzielam morze, tak, że szumią wały jego; Pan zastępów jest imię moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Jam włożył słowa moje w usta twoje, a cieniem ręki mojej zakryłem cię, abyś szczepił niebiosa, a założył ziemię, i rzekł Syonowi: Tyś jest lud mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Ocuć się, ocuć się, powstań Jeruzalemie! któreś piło z ręki Pańskiej kubek zapalczywości jego, drożdże z kubka trucizny śmiertelnej wypiłoś i wysączyłoś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Nikt go nie prowadził ze wszystkich synów, których napłodziło, i nikt go nie ujął za rękę jego ze wszystkich synów, które wychowało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Dwie rzeczy są, które cię spotkały; (któż się ciebie użalił?) Spustoszenie i skruszenie, głód i miecz; któż cię pocieszy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Synowie twoi pomdlawszy leżeli na rogach wszystkich ulic, jako bawół w sieci, pełni będąc popędliwości Pańskiej, gromienia Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'A przetoż słuchaj teraz tego, o utrapiona i pijana, ale nie winem!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Tak mówi Pan twój, Pan i Bóg twój, który się zastawia za lud swój: Oto biorę z ręki twojej kubek trucizny śmiertelnej, i drożdże kubka popędliwości mojej; nie będziesz więcej pić z niego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Ale podam go w rękę tych, którzy cię trapią, którzy mówili duszy twojej: Nachyl się, niech przez cię przejdziemy; a tyś pokładało jako ziemię grzbiet swój, i jako ulicę przechodzącym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Ocuć się, ocuć się, oblecz się w moc twoję, Syonie! oblecz się w szatę ochędóstwa twego, o Jeruzalemie, miasto święte! Albowiem nie natrze na cię nieobrzezany i nieczysty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Otrząśnij się z prochu, powstań, siądź, Jeruzalemie! dobądź się z oków szyi swojej, o pojmana córko Syońska!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Tak zaista Pan mówi: Darmoście się zaprzedali, przetoż bez pieniędzy odkupieni będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Bo tak mówi panujący Pan: Do Egiptu wstąpił lud mój przedtem, aby tam pielgrzymował; ale Assyryjczyk bez przyczyny go trapi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'A teraz cóż mam czynić? mówi Pan, ponieważ lud mój darmo jest pojmany, a ci, którzy panują nad nim, do wzdychania go przywodzą, mówi Pan; nadto ustawicznie każdego dnia imię moje bluźnione bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Przetoż pozna lud mój imię moje, przetoż pozna, mówię, dnia onego, żem Ja jest ten, który mówię; otom Ja przytomny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'O jako piękne są na górach nogi tego, co pocieszne rzeczy zwiastuje, i opowiada pokój; tego, co zwiastuje dobre, i opowiada zbawienie, a mówi do Syonu: Bóg twój króluje!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Wynoszą głos stróżowie twoi, głos wynoszą, a społem wykrzykać będą; bo okiem w oko ujrzą, że zasię Pan Syon przywiedzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Wykrzykajcie a śpiewajcie społem, pustynie Jeruzalemskie! bo pocieszył Pan lud swój, odkupił Jeruzalem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Wysmuknął Pan ramię świętobliwości swojej przed oczyma wszystkich narodów, aby oglądały wszystkie kończyny ziemi zbawienie Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Odstąpcie, odstąpcie wynijdźcie z Babilonu, nieczystego się nie dotykajcie, wynijdźcie z pośrodku jego; oczyście się wy, którzy nosicie naczynie Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Bo nie z trzaskiem wynijdziecie, ani uciekając pójdziecie; pójdzie zaiste Pan przed wami, a zgromadzi was Bóg Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Oto się szczęśliwie powiedzie słudze memu. Wywyższony i podniesiony i bardzo uwielbiony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Jako wiele ich zdumieją się nad nim, że przemierzła jest nad innych ludzi osoba jego, a kształt jego nad synów ludzkich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'Tak zasię pokropi wiele narodów, i królowie przed nim zatulą usta swe, przeto, że czego im nie powiadano, to oglądają, a to, o czem nie słyszeli, wyrozumieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Któż uwierzył kazaniu naszemu, a ramię Pańskie komu objawione jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Bo wyrósł jako latorostka przed nim, a jako korzeń z ziemi suchej, nie mając kształtu ani piękności; i widzieliśmy go; ale nic nie było widzieć, czemubyśmy go żądać mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Najwzgardzeńszy był, i najpodlejszy z ludzi, mąż boleści, a świadomy niemocy, i jako zakrywający twarz swoję; najwzgardzeńszy mówię, skądeśmy go za nic nie mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Zaiste on niemocy nasze wziął na się, a boleści nasze własne nosił; a myśmy mniemali, że jest zraniony, ubity od Boga i utrapiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Lecz on zraniony jest dla występków naszych, starty jest dla nieprawości naszych; kaźń pokoju naszego jest na nim, a sinością jego jesteśmy uzdrowieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Wszyscyśmy jako owce zbłądzili, każdy na drogę swą obróciliśmy się, a Pan włożył nań nieprawość wszystkich nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Uciśniony jest i utrapiony, a nie otworzył ust swoich; jako baranek na zabicie wiedziony był, i jako owca przed tymi, którzy ją strzygą, oniemiał, i nie otworzył ust swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Z więzienia i z sądu wyjęty jest; przetoż rodzaj jego któż wypowie? Albowiem wycięty jest z ziemi żyjących, a zraniony dla przestępstwa ludu mojego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Który to lud podał niezbożnym grób jego, a bogatemu śmierć jego, choć jednak nieprawości nie uczynił, ani zdrada znaleziona jest w ustach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Takci się Panu upodobało zetrzeć go, i niemocą utrapić, aby położywszy ofiarą za grzech duszę swą, ujrzał nasienie swoje, przedłużył dni swoich; a to, co się podoba Panu, przez rękę jego aby się szczęśliwie wykonało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Z pracy duszy swej ujrzy owoc, którym nasycon będzie. Znajomością swoją wielu usprawiedliwi sprawiedliwy sługa mój; bo nieprawości ich on sam poniesie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Przetoż mu dam dział dla wielu, aby się dzielił korzyścią z mocarzami, ponieważ wylał na śmierć duszę swoję, a z przestępcami policzon będąc, on sam grzech wielu odniósł, i za przestępców się modlił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Śpiewaj niepłodna! która nie rodzisz, śpiewaj głośno, a krzycz, która w porodzeniu nie pracujesz; bo więcej będzie synów opuszczonej, niż synów tej, która ma męża, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Rozprzestrzeń miejsce namiotu swego, a opon przybytków swych nie zabraniaj rozciągnąć: wyciągnij powrozy twoje, a kołki twoje utwierdź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Bo się na prawo i na lewo rozsilisz, a nasienie twoje narody odziedziczy, i miasta spustoszone osadzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Nie bój się, bo pohańbiona nie będziesz; a nie zapalaj się, bo nie przyjdziesz na posromocenie; owszem na zelżywość młodości twojej zapomnisz, a na pohańbienie wdowstwa twego więcej nie wspomnisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Albowiem małżonkiem twoim jest stworzycie twój, Pan zastępów imię jego, a odkupiciel twój, Święty Izraelski, Bogiem wszystkiej ziemi zwany będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Bo cię jako żony opuszczonej i strapionej w duchu, Pan powoła, a jako żony młodej, gdy odrzuconą będziesz, mówi Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Na małą chwilkę opuściłem cię; ale zaś w litościach wielkich zgromadzę cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'W maluczkim gniewie skryłem maluczko twarz swoję przed tobą; ale w miłosierdziu wiecznem zlituję się nad tobą, mówi Pan, odkupiciel twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Bo to jest u mnie, co przy potopie Noego; jakom przysiągł, że się więcej nie będą rozlewać wody Noego po ziemi: takem przysiągł, że się nie rozgniewam na cię, ani cię zgromię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'A choćby się i góry poruszyły, i pagórki się zachwiały: jednak miłosierdzie moje od ciebie nie odstąpi, a przymierze pokoju mego nie wzruszy się, mówi twój miłościwy Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'O utrapiona, wichrem rozmiotana, z pociechy obrana! oto Ja położę na karbunkułach kamienie twoje, a na szafirach założę cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'I uczynię z kryształu okna twoje, a bramy twoje z kamienia rubinowego, i wszystkie granice twoje z kamienia kosztownego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'A wszyscy synowie twoi będą wyuczeni od Pana, i obfitość pokoju będą mieli synowie twoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Na sprawiedliwości ugruntowana będziesz; od ucisku się oddalisz, przetoż się go bać nie będziesz; i od starcia; bo się nie przybliży do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Oto nie jeden mieszkać będzie z tobą, który nie jest mój; ale ktoby mieszkając z tobą, był przeciwnym tobie, upadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Otom ja stworzył kowala poddymającego węgle w ogniu, a wyjmującego naczynie ku robocie swojej: Jam też stworzył pustoszyciela, aby wytracał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Żadne naczynie urobione przeciw tobie nie zdarzy się, a każdy język powstawający przeciw tobie na sądzie potępisz. Toć jest dziedzictwo sług Pańskich, a sprawiedliwość ich odemnie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Nuż wszyscy pragnący pójdźcie do wód, i wy, co niemacie pieniędzy, pójdźcie, kupujcie a jedzcie; pójdźcie, mówię, kupujcie bez pieniędzy i bez zapłaty, wino i mleko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Przecz wynakładacie pieniądze nie za chleb, a pracę swą na to, co nie nasyca? Słuchając słuchajcie mię, a jedzcie to, co jest dobrego, i niech się rozkocha w tłustości dusza wasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Nakłońcie ucha swego, a pójdźcie do mnie; słuchajcie, a będzie żyła dusza wasza. I postanowię z wami przymierze wieczne, miłosierdzie Dawidowe pewne wyleję na was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Oto dałem go za świadka narodom, za wodza i za nauczyciela narodom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Oto naród, któregoś nie znał, powołasz, a narody, które cię nie znały, zbieżą się do ciebie dla Pana, Boga twego, i Świętego Izraelskiego; bo cię uwielbi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Szukajcie Pana, póki może być znaleziony; wzywajcie go, póki blisko jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Niech opuści niepobożny drogę swoję, a człowiek nieprawy myśli swoje i niech się nawróci do Pana, a zmiłuje się; i do Boga naszego, gdyż jest hojnym w odpuszczaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Boć zaiste myśli moje nie są jako myśli wasze, ani drogi wasze jako drogi moje, mówi Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Ale jako wyższe są niebiosa niż ziemia, tak przewyższają drogi moje drogi wasze, a myśli moje myśli wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Bo jako zstępuje deszcz i śnieg z nieba, a tam się więcej nie wraca, ale napawa ziemię, a czyni ją płodną, czyni ją też urodzajną, tak że wydaje nasienie siejącemu, a chleb jedzącemu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'Takci będzie słowo moje, które wynijdzie z ust moich; nie wróci się do mnie próżno, ale uczyni to, co mi się podoba, i poszczęści mu się w tem, na co je poślę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Przetoż w weselu wynijdziecie, a w pokoju doprowadzeni będziecie. Góry i pagórki chwałę przed wami głośno zaśpiewają, a wszystkie drzewa polne rękami klaskać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Miasto ciernia wyrośnie jedlina, a miasto pokrzywy wyrośnie mirt; a to będzie Panu ku sławie, na znak wieczny, który nigdy nie będzie wygładzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Tak mówi Pan: Strzeżcie sądu, a czyńcie sprawiedliwość; bo blisko tego, że zbawienie moje przyjdzie, a sprawiedliwość moja objawiona będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Błogosławiony człowiek, który to czyni, i syn człowieczy, który się trzyma tego, przestrzegając sabatu, aby go nie splugawił, a strzegąc ręki swej, aby nie uczyniła nic złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Niech tedy nie mówi cudzoziemiec, który przystaje do Pana, mówiąc: Zaiste Pan mię odłączył od ludu swego; niech też nie mówi trzebieniec: Otom ja drzewo suche.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Albowiem tak mówi Pan o trzebieńcach, którzyby przestrzegali sabatów moich, a obrali to, co mi się podoba, i trzymali przymierze moje:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'Żeć im dam w domu swym i między murami mojemi miejsce, i imię lepsze niżeli synów i córek; dam im imię wieczne, które nie będzie wygładzone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'A cudzoziemców, którzyby przystali do Pana, aby mu służyli, a miłowali imię Pańskie, będąc u niego za sługi, wszystkich przestrzegających sabaty, aby go nie splugawili, i zachowujących przymierze moje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'Tych przywiodę na górę świętobliwości mojej, a uweselę ich w domu modlitwy mojej; całopalenia ich i ofiary ich przyjemne będą na ołtarzu moim; bo dom mój domem modlitwy nazwany będzie u wszystkich narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Tak mówi panujący Pan, który zgromadza rozpędzonych z Izraela: Jeszcze zgromadzę do niego, i do zgromadzonych jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Wszystkie zwierzęta polne przyjdźcie na pożarcie, i wszystkie zwierzęta leśne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Stróżowie jego ślepi, wszyscy zgoła nic nie umieją, wszyscy są psami niememi, nie mogą szczekać; ospałymi są, leżą, kochają się w drzemaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'A są psami obżartemi, nie mogą się nigdy nasycić; sami się pasąc nie umieją nauczać. Wszyscy się za drogą swoją udali, każdy za łakomstwem swojem z strony swej, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Pójdźcie, nabiorę wina, a upijemy się mocnym napojem, a będzie nam jako dziś tak i jutro, i jeszcze daleko obficiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Sprawiedliwy ginie, a nikt tego do serca nieprzypuszcza; i mężowie pobożni schodzą, a nikt tego nie uważa, że przed przyjściem złego sprawiedliwy zebrany bywa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Że wschodzi do pokoju, a odpoczywa na łożu swojem, ktokolwiek chodzi w uprzejmości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Ale wy sami przystąpcie, synowie czarownicy, nasienie cudzołożnika i wszetecznicy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Nad kimże się cieszycie? przeciwko komuż rozdzieracie gębę, i wywieszacie język? Izali nie jesteście synowie nierządu, nasienie kłamliwe?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Którzy nierząd płodzicie w gajach pod każdem drzewem zielonem zabijając synów swych przy potokach, pod wysokiemi skałami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Między gładkim kamieniem potokowym jest dział twój. Cić są, ci losem twoim, na które też wylewasz ofiarę mokrą, a ofiarujesz ofiarę śniedną, i w temże bym się Ja kochał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Na górze wysokiej i wyniosłej postawiłeś łoże twoje, a tam wstępujesz ku sprawowaniu ofiar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'A za drzwiami i za podwojem położyłaś pamiątkę twoję, gdyż odemnie odchodząc odkrywasz się, a wstąpiwszy rozszerzasz łoże swe, czyniąc je przestworniejsze, niżeli poganie; umiłowałaś łoże ich, gdziekolwiek miejsce upatrzysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Chodzisz i do króla, z olejkiem i z rozmaitemi wonnemi maściami twemi; posyłasz bowiem posłów swych daleko, a poniżasz się aż do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Mnóstwem dróg swoich spracowałaś się, a nie mówisz: Daremnać to. Znalazłaś pomoc ręce swojej, dlategoś nie zemdlała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Kogożeś się obawiała i lękała, iżeś kłamała? Na mięś nie pomniała, aniś tego przypuściła do serca swego: dlategoż to, żem Ja milczał, a to z dawna, nie boisz się mnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Ja opowiem sprawiedliwość twoję i sprawy twoje, któreć nic nie pomogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Gdy zawołasz, niech cię wybawi zgraja twoja; ale wszystkie one rozniesie wiatr, i pochwyci marność. Lecz ten, co we mnie ufa, odziedziczy ziemię, a posiądzie górę świętą moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Bo rzeką: Wyrównajcie, wyrównajcie, zgotujcie drogę, uprzątnijcie zawady z drogi ludu mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Bo tak mówi on najdostojniejszy i najwyższy, który mieszka w wieczności, a święte jest imię jego: Ja, który mieszkam na wysokości na miejscu świętem, mieszkam i z tym, który jest skruszonego i uniżonego ducha, ożywiając ducha pokornych, ożywiając serce skruszonych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Nie będę się zaiste na wieki wadził, ani się wiecznie gniewał; boćby duch przed obliczem mojem zemdlał, i dusze, którem Ja uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Dla nieprawości łakomstwa jego rozgniewałem się, a uderzyłem go; ukryłem się, a rozgniewałem się, przeto, że odpornym będąc, poszedł drogą serca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Widzę drogi jego, wszakże uzdrowię go; doprowadzę go; i przywrócę mu pociechy, i tym, którzy z nim płaczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Stworzę owoc warg, pokój dalekiemu i bliskiemu, mówi Pan; a tak uzdrowię go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Lecz niepobożni będą jako morze wzburzone, gdy się uspokoić nie może, a którego wody wymiatają kał i błoto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Niemasz pokoju niepobożnym, mówi Bóg mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Wołaj wszystkiem gardłem, nie zawściągaj; wynoś głos swój jako trąba, a opowiedz ludowi mojemu przestępstwa ich, a domowi Jakóbowemu grzechy ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Chociaż mię każdego dnia szukają, a znać chcą drogi moje, jako naród, który sprawiedliwość czyni, a sądu Boga swego nie opuszcza; pytają mię o sądach sprawiedliwości a przgną się przybliżyć do Boga mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Przeczże pościmy, gdyż na to nie patrzysz? trapimy duszę naszę, a nie widzisz? Oto w dzień postu waszego przewodzicie wolę swoję, a wszystkie prace swoje wyciągacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Oto pościcie na swary, i na zwady, i bijecie pięścią niemiłościwie; nie pościcie, jak się godzi tych dni, aby był słyszany na wysokości głos wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Izali to jest takowy post, jakim obrał, a dzień, w któryby trapił człowiek duszę swoję? żeby zwiesił jako sitowie głowę swoję, a wór i popiół sobie podścielał? Toż to nazwiesz postem, i dniem przyjemnym Panu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Ale to jest post, którym obrał: Rozwiąż związki niepobożności, rozwiąz brzemiona ciężkie, i wolno puść skruszonych, a tak wszelakie jarzmo rozerwij;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Ułamuj łaknącemu chleba twego, a ubogich wygnańców wprowadź do domu twego; ujrzyszli nagiego, przyodziej go, a przed ciałem swojem nie ukrywaj się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Tedy wyniknie jako zorza ranna światłość twoja, a zdrowie twoje prędko zakwitnie! i pójdzie przed tobą sprawiedliwość twoja, a chwała Pańska zbierze cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Tedy wzywać będziesz, a Pan wysłucha; zawołasz, a odpowieć: Owom Ja. Jeźli odejmiesz z pośrodku siebie i jarzmo, a przestaniesz palca wyciągać, i mówić nieprawości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Jeźli wylejesz łaknącemu duszę swoję, a duszę utrapioną nasycisz: tedy wejdzie w ciemności światłość twoja, a zmierzk twój będzie jako południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Bo cię Pan ustawicznie poprowadzi, i nasyci pod największą suszą duszę twoję, a kości twoje utuczy, i będziesz jako ogród wilgotny, a jako zdrój wód, którego wody nie ustawają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'I pobudują spłodzeni od ciebie pustynie starodawne, grunty od narodu do narodu wywiedziesz; i nazwą cię naprawcą obalin, i przeprawcą ścieżek ku mieszkaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Jeźliże odwrócisz od sabatu nogę swoję, abyś nie przewodził woli swojej w dzień mój święty; i jeżeli nazwiesz sabat rozkoszą, dniem świętym a Panu sławnym, i będzieszli go miał w uczciwości, tak, abyś weń nie czynił dróg swoich, i nie przewodził woli swej, i nie mówił słowo próżnego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Tedy będziesz rozkoszował w Panu; i wprowadzą cię na wysokie miejsca ziemi, i sprawię to, abyś pożywał dziedzictwa Jakóba, ojca twego; bo usta Pańskie mówiły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Oto nie jest ukrócona ręka Pańska, aby zbawić nie mogła; a nie jest obciążone ucho jego, aby wysłuchać nie mogło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Ale nieprawości wasze roździał uczyniły między wami i między Bogiem waszym, a grzechy wasze sprawiły, że ukrył twarz przed wami, aby nie słyszał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Bo ręce wasze krwią są zmazane, a palce wasze nieprawością; wargi wasze mówią kłamstwo, a język wasz nieprawość świegoce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Niemasz ktoby się zastawiał o sprawiedliwość, ani jest ktoby się zasadzał o prawdę. Ufają w próżności, a mówią kłamstwo; poczynają ucisk, a rodzą nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Jaja bazyliszkowe wylęgli, a płótna pajęczego natkali. Ktoby jadł jaja ich, umrze, a jeźli je stłucze, wynijdzie jaszczórka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Płótna ich nie godzą się na szatę, ani się przyodzieją robotami swemi. Uczynki ich są uczynki nieprawości, a sprawa łupiestwa jest w rękach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Nogi ich bieżą do złego, i kwapią się na wylanie krwi niewinnej. Myśli ich są myśli nieprawości; spustoszenie i starcie jest na drogach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Drogi pokoju nieznają, i niemasz sprawiedliwości w drogach ich; ścieszki swe sami pokrzywili u siebie; każdy, kto po nich chodzi, nie zna pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Dlatego oddalił się sąd od nas, a nie dochodzi nas sprawiedliwość; czekamy na światłość, a oto ciemność; na jasność, ale w ćmie chodzimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Macamy ściany jako ślepi, a macamy, jakobyśmy oczów nie mieli. Potykamy się w południe jako w zmierzk; w wielkich dostatkach podobniśmy umarłym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Mruczymy wszyscy jako niedźwiedź, jako gołębica ustawicznie stękamy; oczekujemy na sąd, ale go niemasz; na wybawienie, ale dalekie jest od nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Bo się rozmnożyły przestępstwa nasze przed tobą, a grzechy nasze świadczą przeciwko nam, ponieważ nieprawości nasze są przy nas, i złości nasze uznajemy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Żeśmy wystąpili, i kłamali przeciw Panu, i odwróciliśmy się, abyśmy nie szli za Bogiem naszym; żeśmy mówili o potwarzy i o odstąpieniu, żeśmy zmyślali i wywierali z serca swego słowa kłamliwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Tak, że się sąd opak obrócił, a sprawiedliwość z daleka stoi; bo na ulicy prawda szwankowała, a prawość przejścia nie ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Owszem, prawda zginęła, a ten, co odstępuje od złego, na łup podany bywa. To widzi Pan, i nie podoba się to w oczach jego, że niemasz sądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Gdy tedy widział, że niemasz żadnego męża, aż się zdumiał, że niemasz żadnego, coby się zastawił, a przetoż wybawienie sprawiło mu ramię jego, a sprawiedliwość jego sama go podparła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Bo się przyoblókł w sprawiedliwość jako w pancerz, a hełm zbawienia na głowie jego; oblókł się w odzienie pomsty jako w szatę, a odział się zapalczywością jako płaszczem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Aby według uczynków, aby według nich odpłacił popędliwością przeciwnikom swoim, aby nagrodę nieprzyjaciołom swoim, a wyspom zapłatę oddał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'I będą się bali, którzy są na zachód, imienia Pańskiego, i którzy na wschód słońca, sławy jego. Gdy przypadnie nieprzyjaciel jako rzeka, tedy go duch Pański precz zapędzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Bo przyjdzie do Syonu odkupiciel, i do tych, którzy się odwracają od występków w Jakóbie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'A toć będzie przymierze moje z nimi, mówi Pan: Duch mój, który jest w tobie, i słowa moje, którem włożył w usta twoje, nie odstąpią od ust twoich, ani od ust nasienia twego, ani od ust potomków nasienia twego, mówi Pan, odtąd aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Powstań, objaśnij się! ponieważ przyszła światłość twoja, a chwała Pańska weszła nad tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Bo oto ciemności okryją ziemię, a zaćmienie narody; ale nad tobą wejdzie Pan, a chwała jego nad tobą widziana będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'I będą chodzić narody w światłości twojej, a królowie w jasności, która wejdzie nad tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Podnieś w około oczy twe, a spojrzyj; ci wszyscy, którzy się zgromadzili, pójdą do ciebie; synowie twoi z daleka przyjdą, a córki twoje przy boku twoim chowane będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Tedy oglądasz to, a rozweselisz się; tedy się zdumieje i rozszerzy serce twoje, gdy się obróci ku tobie zgraja morska, a moc narodów przyjdzie do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Obfitość wielbłądów okryje cię, także dromedarze z Madyjan i z Efy. Wszyscy ci przyjdą z Saby, złoto i kadzidło przyniosą, a chwały Pańskie opowiadać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Wszystkie stada z Kedar zgromadzą się do ciebie; barany z Nebajotu służyć ci będą, a ofiarowane będąc na ołtarzu moim, przyjemne będą; a tak dom majestatu mego ozdobię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'I rzeczesz: Którzyż to są, co się jako obłoki zlatują, i jako gołębie do okien swoich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Na mięć zaiste wyspy oczekują, i okręty morskie zdawna, aby przywiedli synów twoich z daleka, także srebro swoje z sobą, i złoto swoje imieniowi Pana, Boga twego, i Świętego Izraelskiego; bo cię uwielbi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'I pobudują cudzoziemcy mury twoje, a królowie ich służyć ci będą, gdyż w rozgniewaniu mojem uderzę cię, a w upodobaniu mojem zlituję się nad tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'I będą otworzone bramy twoje ustawicznie; we dnie i w nocy nie będą zatkane, aby przywiedziono do ciebie moc pogan, i królowie ich aby byli przywiedzieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Naród ten i królestwo, którećby nie służyło, zginie; narody takie, mówię, do szczętu spustoszone będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Sława Libanu do ciebie przyjdzie, jedlina, sosna, także bukszpan, dla ozdoby miejsca świątnicy mojej, abym miejsce nóg moich uwielbił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Przyjdą także do ciebie w pokorze synowie tych, którzy cię trapili, i będą się kłaniać stopom nóg twoich, którzykolwiek pogardzili tobą, i nazwią cię miastem Pańskiem, Syonem Świętego Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Miasto tego, coś opuszczona i w nienawiści była, tak, że nie było, ktoby przez cię chodził, wystawię cię za dostojność wieczną, i wesele od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Bo ssać będziesz mleko narodów, i piersiami królów karmiona będziesz; i poznasz, iżem Ja Pan, zbawieciel twój i odkupiciel twój, mocarz Jakóbowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Miasto miedzi naniosę złota, a miasto żelaza naniosę srebra, a miasto drew miedzi, a miasto kamienia żelaza; i postawię nad tobą dozorców spokojnych, i urzędników sprawiedliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Nie będzie więcej słychać o drapiestwie w ziemi twojej, o zburzeniu i spustoszeniu na granicach twoich; ale ogłaszać będziesz zbawienie na murach twoich, a chwałę w bramach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Nie będziesz miał więcej słońca za światłość dzienną, a jasność miesiąca nie oświeci cię, ale Pan będzie światłością twoją wieczną, a Bóg twój sławą twoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Nie zajdzie więcej słońce twoje, a miesiąc twój nie skryje się; bo Pan będzie wieczną światłością twoją; a tak dokonają się dni smutku twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Lud także twój, którzybykolwiek byli sprawiedliwi, na wieki odziedziczą ziemię; będą latoroślą szczepienia mego, dziełem rąk moich, abym w niem był uwielbiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Najmniejszy rozmnoży się na tysiące, a maluczki poczet w naród niezliczony. Ja Pan czasu swego prędko to uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Duch Panującego Pana jest nademną; przeto mię pomazał Pan, abym opowiadał Ewangeliję cichym, posłał mię, abym związał rany tych, którzy są skruszonego serca, abym zwiastował pojmanym wyzwolenie, a więźniom otworzenie ciemnicy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Abym ogłosił miłościwy rok Pański, i dzień pomsty Boga naszego; abym cieszył wszystkich płaczących;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Abym sprawił radość płaczącym w Syonie, a dał im ozdobę miasto popiołu, olejek wesela miasto smutku, odzienie chwały miasto ściśnionego; i będą nazwani drzewami sprawiedliwości, szczepieniem Pańskiem, abym był uwielbiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Tedy pobudują spustoszenie starodawne, pustynie stare naprawią, a odnowią miasta spustoszone, puste za wielu narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Bo się stawią cudzoziemcy, a paść będą stada wasze, a synowie cudzoziemców oraczami waszymi i winiarzami waszymi będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Ale wy kapłanami Pańskimi nazwani będziecie, sługami Boga naszego zwać was będą; majętności pogan używać będziecie, a w sławie ich wywyższeni będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Za dwojakie pohańbienie i zelżywość waszę śpiewać będziecie; z działu ich, i w ziemi ich dwojakie dziedzictwo posiądziecie, a tak wesele wieczne mieć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Ja Pan miłuję sąd, a mam w nienawiści łupiestwo przy całopaleniu; przetoż sprawię, aby uczynki ich działy się w prawdzie, a przymierze wieczne postanowię z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'I znajome będzie między poganami nasienie ich, a potomstwo ich w pośrodku narodów; wszyscy, którzy ich ujrzą, poznają ich, że są nasieniem, któremu Pan pobłogosławił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Weseląc weselić się będą w Panu, a dusza moja rozraduje się w Bogu moim; bo mię oblókł w szaty zbawienia, a płaszczem sprawiedliwości przyodział mię, jako oblubieńca ozdobnego chwałą, i jako oblubienicę ozdobioną w klejnoty swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Bo jako ziemia wydaje płód swój, a jako ogród nasienie swoje wywodzi, tak panujący Pan wywiedzie sprawiedliwość i chwałę swoję przed wszystkie narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Dla Syonu milczeć nie będę, a dla Jeruzalemu nie uspokoję się, dokąd sprawiedliwość jego nie wynijdzie jako jasność, a zbawienie jego jako pochodnia gorzeć nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'I oglądają narody sprawiedliwość twoję, i wszyscy królowie sławę twoję i nazwą cię imieniem nowem, które usta Pańskie mianować będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'I będziesz koroną ozdobną w ręce Pańskiej, i koroną królestwa w ręce Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Nie będą cię więcej zwać opuszczoną, i ziemia twoja nie będzie więcej zwana spustoszoną; ale ty nazywana będziesz rozkoszą moją, a ziemia twoja mężatką; bo Pan będzie miał rozkosz w tobie, a ziemia twoja będzie zamężna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Albowiem jako młodzieniec pannę pojmuje, tak cię sobie pojmą synowie twoi; a jako się oblubieniec weseli z oblubienicy, tak się weselić będzie z ciebie Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Na murach twoich, o Jeruzalem! postawię stróżów, którzy przez cały dzień całą noc nigdy nie umilkną; którzy wspominacie Pana, nie milczcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'A nie dawajcie mu odpocznienia, dokąd nie utwierdzi, i dokąd nie sposobi, aby Jeruzalem było sławne na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Przysiągł Pan przez prawicę swoję i przez ramię mocy swojej, mówiąc: Nie podam więcej pszenicy twojej na pokarm nieprzyjaciołom twoim, i nie będą pić cudzoziemcy wina twego, około któregoś pracował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Ale ci, którzy je zgromadzą, pożywać go, i chwalić Pana będą; a którzy je zbierają, będą je pić w sieniach świątnicy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Przechodźcie, przechodźcie przez bramy! gotujcie drogę ludowi; wyrównajcie, wyrównajcie gościńce; wybierzcie kamienie, podnieście chorągiew do narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Oto Pan rozkaże obwołać aż do kończyn ziemi; powiedzcie córce Syońskiej: Oto zbawiciel twój idzie, oto zapłata jego z nim, a dzieło jego przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'I nazwią synów twoich ludem świętym, odkupionymi Pańskimi, a ciebie nazwią miastem zacnem i nie opuszczonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Któż to jest, który idzie z Edom, w szatach ubroczonych we krwi z Bocra? Ten przyozdobiony szatą swoją, postępujący w wielkości mocy swojej? Jam jest, który mówię sprawiedliwość, dostateczny do wybawienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Przeczże jest czerwone odzienie twoje? a szaty twoje jako tego, który tłoczy w prasie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Prasę tłoczyłem Ja sam, a nikt z ludu nie był zemnę; Ja, mówię, tłoczyłem nieprzyjaciół w gniewie swym, i podeptałem ich w popędliwości mojej, aż pryskała krew mocarzów ich na szaty moje; a tak wszystko odzienie moje spluskałem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Albowiem dzień pomsty był w sercu mojem, a rok odkupionych moich przyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Lecz gdym widział, że nie było pomocnika, ażem się zdumał, że nikogo nie było, coby mię podparł, przetoż mi wybawienie sprawiło ramię moje, a popędliwość moja, ta mię podparła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'I podeptałem narody w gniewie swym, a opoiłem je w zapalczywości mojej, i uderzyłem o ziemię mocarzy ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Miłosierdzia Pańskie wspominać będę, i chwały Pańskie za wszystko, cokolwiek nam uczynił Pan, i hojność dóbr, które pokazał domowi Izraelskiemu według miłosierdzia swego, i według wielkich litości swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Bo rzekł: Wżdyć są ludem moim, są synami, nie przeniewierzą mi się; przetoż był ich zbawicielem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'We wszelakiem uciśnieniu ich i on był uciśniony: ale Anioł oblicza jego wybawił ich. Z miłości swej, i z litości swojej on sam odkupił ich, piastował ich i nosił ich po wszystkie dni wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Ale oni odpornymi byli, i zasmucali Ducha jego Świętego; dla tego obrócił się im w nieprzyjaciela, a sam walczył przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'I wspominał sobie lud jego na dni starodawne, i na Mojżesza, mówiąc: Gdzież jest ten, który ich wywiódł z morza, z pasterzem trzody swojej? Gdzież jest ten, który położył w pośrodku jego Ducha swego Świętego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Który ich wiódł po prawicy Mojżeszowej ramieniem wielmożności swojej? który rozdzielił wody przed nimi, aby sobie uczynił imię wieczne?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Który ich przeprowadził przez przepaści, jako konia po puszczy, a nie szwankowali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Jako gdy bydlę na dół zstępuje: tak Duch Pański zwolna prowadził z nich każdego; takeś wiódł lud swój, abyś sobie uczynił imię sławne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Spojrzyjże z nieba, a obacz z mieszkania świętobliwości twojej, i ozdoby twojej. Gdzież jest gorliwość twoja, i wielka siła twoja? Gdzie wzruszenie wnętrzności twoich, i litości twoich? Przedemnąż zawściągnione będą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Tyś zaiste ojciec nasz: bo Abraham nie wie o nas, a Izrael nie zna nas. Tyś, Panie! ojciec nasz, odkupiciel nasz; toć jest od wieku imię twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Przeczżeś nam, Panie! dopuścił błądzić z dróg twoich? przeczżeś zatwardził serce nasze, abyśmy się ciebie nie bali? Nawróćże się dla sług twoich, dla pokolenia dziedzictwa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Na mały czas posiadł ziemię lud świętobliwości twojej; nieprzyjaciele nasi podeptali świątnicę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Myśmy twoi od wieku, a nad tymi nigdyś nie panował, ani wzywano imienia twego nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Obyś rozdarł niebiosa, i zstąpił, aby się od oblicza twego góry rozpłynęły!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, '(Jako od gorejącego ognia, ognia roztapiającego, woda wre,) abyś oznajmił imię twoje nieprzyjaciołom twoim, ażeby się od oblicza twego narody zatrwożyły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Jako gdyś czynił dziwy, którycheśmy się nie spodziewali; zstąpiłeś, a od oblicza twego góry się rozpływały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Czego od wieków nie słyszano ani to do uszów przychodziło; oko nie widziało Boga innego oprócz ciebie, coby tak uczynił temu, co nań oczekuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Zabieżałeś weselącemu się i czyniącemu sprawiedliwość, i tym, którzy na drogach twoich wspominali na cię. Otoś się ty rozgniewał, przeto żeśmy grzeszyli na tych drogach ustawicznie, wszakże zachowani będziemy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Aczkolwiek jesteśmy jako nieczysty my wszyscy, i jako szata splugawiona są wszystkie sprawiedliwości nasze; przetoż wszyscy opadamy jako liść, a nieprawości nasze jako wiatr unoszą nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Nadto niemasz, ktoby wzywał imienia twego, i pobudził się do tego, aby się chwycił ciebie, przynajmniej teraz, gdyś zakrył twarz swoję przed nami, a sprawiłeś, abyśmy niszczeli dla nieprawości naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Ale teraz, o Panie! tyś jest ojciec nasz, myśmy glina, a tyś twórca nasz; a takeśmy wszyscy dziełem ręki twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Nie gniewaj się, Panie! tak bardzo, a nie na wieki pomnij nieprawości naszej: oto wejrzyj proszę, myśmy wszyscy ludem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Miasta świętobliwości twojej obrócone są w pustynię, Syon w pustynię, a Jeruzalem w spustoszenie obrócone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Dom świętobliwości naszej i ozdoby naszej, w którym cię chwalili ojcowie nasi, ogniem jest spalony, i wszystkie najkosztowniejsze rzeczy nasze obróciły się w pustki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Izali nad tem zatrzymasz się Panie? izali milczeć a nas tak bardzo trapić będziesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Objawiłem się tym, którzy się o mię nie pytali; znalezionym jest od tych, którzy mię nie szukali; do narodu, który się nie nazywał imieniem mojem. rzekłem: Otom Ja! otom Ja!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Rozciągnąłem ręce moje na każdy dzień do ludu upornego, który chodzi drogą nie dobrą za myślami swemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Do ludu, który mię jawnie wzrusza do gniewu, ustawicznie ofiarując w ogrodach, a kadząc na cegłach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Którzy siadają przy grobach, a przy bałwanach swoich nocują; którzy jedzą świnie mięso, i polewkę obrzydłą z naczynia swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Mówiąc: Odstąp precz, nie przystępuj do mnie; bom jest świętobliwszy niżeli ty. Cić są dymem w nozdrzach moich, i ogniem pałającym przez cały dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Oto zapisano to przedemną: Nie zamilczę, ale oddam i odpłacę na łono ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'Nieprawości wasze, także i nieprawości ojców waszych, mówi Pan, którzy kadzili po górach, a na pagórkach hańbili mię; przetoż odmierzę sprawę ich pierwszą na łono ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Tak mówi Pan: Jako gdyby kto znalazł wino w gronie, i rzekłby: Nie psuj go, bo błogosławieństwo jest w niem; tak i Ja uczynię dla sług moich, że ich wszystkich nie wygubię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Bo wywiodę z Jakóba nasienie, a z Judy dzierżawcę gór moich; i posiędą ją wybrani moi, a słudzy moi tam mieszkać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'A Saron będzie za pastwisko owcom, a dolina Achor za legowisko wołów ludu mojego, którzy mię szukali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Ale was, którzyście opuścili Pana, którzy zapominacie na górę świętobliwości mojej, którzy gotujecie temu wojsku stół, a którzy oddawacie temu pocztowi mokre ofiary:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'Was, mówię policzę pod miecz, tak, że wy wszyscy do zabicia schylać się będziecie, przeto, żem wołał, a nie ozwaliście mi się, mówiłem, a nie słyszeliście, aleście czynili, co złego jest przed oczyma mojemi, a czegom Ja nie chciał, obieraliście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Przetoż tak mówi panujący Pan: Oto słudzy moi jeść będą, a wy łaknąć będziecie; oto słudzy moi pić będą, a wy pragnąć będziecie; oto słudzy moi weselić się będą, a wy zawstydzeni będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Oto słudzy moi wykrzykać będą od radości serdecznej, a wy będziecie wołać od boleści serca, i od skruszenia ducha wyć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'I zostawicie imię wasze na przeklinanie wybranym moim, gdy was pomorduje panujący Pan, a sługi swe nazwie innem imieniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'Ten, który sobie będzie błogosławił na ziemi, będzie sobie błogosławił w Bogu prawdziwym; a kto będzie przysięgał na ziemi, będzie przysięgał przez Boga prawdziwego; w zapomnienie zaiste przyjdą te uciski pierwsze, a będą zakryte od oczów moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Albowiem oto Ja tworzę niebiosa nowe, i ziemię nową, a nie będą wspominane rzeczy pierwsze, ani wstąpią na serce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Owszem weselcie się, a radujcie się na wieki wieków z tego, co Ja stworzę; bo oto Ja stworzę Jeruzalem na radość, a lud jego na wesele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'I rozraduję się w Jeruzalemie, a weselić się będę w ludu moim; a nie będzie słychać w nim głosu płaczu i głosu narzekania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Nie będzie tam więcej nikogo w wieku dziecinnym, ani starca, któryby nie dopełnił dni swoich; bo dziecię we stu latach umrze; ale grzesznik, choćby miał i sto lat, przeklęty będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Pobudują też domy, a będą w nich mieszkali; nasadzą też winnic, a będą jeść owoce ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Nie będą budować tak, aby tam inszy mieszkał; nie będą szczepić, aby inny jadł; bo dni ludu mojego będą jako dni drzewa, a dzieła rąk swoich do zwietszenia używać będą wybrani moi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Nie będą robić próżno, ani płodzić będą na postrach; bo będą nasieniem błogosławionych od Pana, oni i potomkowie ich z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Nadto stanie się, że pierwej niż zawołają, Ja się ozwę; jeszcze mówić będą, a Ja wysłucham.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Wilk z barankiem paść się będą społem; lew jako wół plewy jeść będzie, a wężowi proch będzie chlebem jego; nie będą szkodzić ani zatracać na wszystkiej górze świętej mojej, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Tak mówi Pan: Niebo jest stolicą moją, a ziemia podnóżkiem nóg moich. Gdzież tedy będzie ten dom, który mi zbudujecie? albo gdzie będzie miejsce odpocznienia mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Bo to wszystko ręka moja uczyniła, i nią stanęło to wszystko, mówi Pan. Wszakże Ja na tego patrzę, który jest utrapionego i skruszonego ducha, a który drży na słowo moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Inaczej ten, kto zabija wołu na ofiarę, jakoby zabił człowieka; kto zabija na ofiarę bydlątko, jakoby psa ściął; kto ofiaruje ofiarę suchą, jakoby krew świnią ofiarował; kto kadzi kadzidłem, jakoby bałwanowi błogosławił. A jako oni sobie obrali drogi swoje, i w obrzydliwościach swoich kochała się dusza ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Tak i Ja obiorę za wynalazki ich, a to, czego się boją, przywiodę na nich, przeto, że gdym wołał, żaden się nie ozwał, gdym mówił, nie słuchali, ale czynili to, co złego jest przed oczyma mojemi, a to, czegom nie chciał, obierali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Słuchajcie słowa Pańskiego, wy którzy drżycie na słowo jego. Bracia wasi nienawidzący was, a wyganiający was dla imienia mego, mówią: Niech się okaże sława Pańska. Okażeć się zaiste ku pociesze waszej; ale oni pohańbieni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Głos grzmotu z miasta słyszany będzie, głos z kościoła, głos Pana oddawającego zapłatę nieprzyjaciołom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Pierwej niż pracowała ku porodzeniu, porodziła, pierwej niż ją ogarnęła boleść, porodziła mężczyznę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Któż słyszał co takowego? Kto widział co podobnego? Możeż to być, aby ziemia narodziła ludu za jeden dzień? Izali naród spłodzony bywa jednym razem? Ale Syon ledwie począł pracować ku porodzeniu, alić porodził synów swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Cóżbym Ja, który otwieram żywot, rodzić nie miał? mówi Pan. Cóżbym Ja, który to czynię, że rodzą, zawartym był? mówi Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Weselcie się z Jeruzalemem a radujcie się w nim wszyscy, którzy go miłujecie. Wesewlcie się z nim wielce, wszyscy którzykolwiek płakali nad nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Przeto, że ssać będziecie, i sycić się piersiami pociech jego, ssać będziecie, i rozkoszami opływać w jasności chwały jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Bo tak mówi Pan: Oto Ja obrócę na nich pokój jako rzekę, a sławę narodów jako strumień zalewający, i będziecie ssać; na ręku noszeni, i na kolanach rozkosznie piastowani będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Jako ten, którego cieszy matka jego, tak Ja was cieszyć będę; a tak w Jeruzalemie uciechy miewać będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Ujrzycie zaiste, a radować się będzie serce wasze, a kości wasze jako trawa zakwitną. I poznana będzie ręka Pańska przy sługach jego; ale się gniewem zapali przeciwko nieprzyjaciołom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Bo oto Pan w ogniu przyjdzie, a poczwórne jego jako wicher, aby wylał gniew swój w popędliwości, a łajanie swoje w płomieniu ognia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Pan, mówię, przez ogień sądzić będzie, i przez miecz swój wszelkie ciało, a pobitych od Pana wiele będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'I ci, którzy się poświęcają i oczyszczają w ogrodach, jeden za drugim jawnie; którzy jedzą mięso świnie, i inną obrzydłość, i myszy, koniec także wezmą, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Albowiem Ja znam sprawy ich, i myśli ich; i przyjdzie ten czas, że zgromadzę wszystkie narody, i języki, i przyjdą a oglądają chwałę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'I położę na nich znak, a poślę z tych, którzy zachowani będą, do narodów przy morzu do Pul i Lud, którzy ciągną łuk do Tubala, i do Jawanu, na wyspy dalekie, które nic o mnie nie słyszały, i nie widziały chwały mojej; i będą opowiadały chwałę moję między narodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'I przywiodę wszystkich braci waszych ze wszystkich narodów Panu w dary, na koniach i na wozach, i na lektykach, i na mułach, i na zawidnikach, na górę świętobliwości mojej do Jeruzalemu, mówi Pan, tak jako przynoszą synowie Izraelscy dar w naczyniu czystem do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'I z tych też nabiorę kapłanów i Lewitów, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Bo jako te niebiosa nowe, i ta ziemia nowa, którą Ja uczynię, stanie przedemną, mówi Pan, tak stanie nasienie wasze i imię wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'I stanie się, że od nowiu miesiąca do nowiu miesiąca, i od sabatu do sabatu przychodzić będzie wszelkie ciało, aby się kłaniało przed oblicznością moją, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'I wynijdą a oglądają trupy ludzi tych, którzy wystąpili przeciwko mnie; albowiem robak ich nie zdechnie, a ogień ich nie zgaśnie, a będą obrzydliwością wszelkiemu ciału.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Słowa Jeremijasza, syna Helkijaszowego, z kapłanów, którzy byli w Anatot, w ziemi Benjamin');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'Do którego stało się słowo Pańskie za dni Jozyjasza, syna Amonowego, króla Judzkiego trzynastego roku królowania jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'A stało się za dni Joakima, syna Jozyjaszowego, króla Judzkiego, aż do skończenia jedenastego roku Sedekijasza, syna Jozyjasza, króla Judzkiego, aż do przeprowadzenia Jeruzalemczyków, miesiąca piątego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Stało się mówię, słowo Pańskie do mnie, mówiąc');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Pierwej niżelim cię utworzył w żywocie, znałem cię, a pierwej niżeliś wyszedł z żywota, poświęciłem cię, za proroka narodom dałem cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'I rzekłem: Ach, ach panujący Panie! Oto nie umiem mówić, bom jest dziecięciem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Ale Pan rzekł do mnie: Nie mów: Jestem dziecięciem, owszem, na wszystko, na co cię poślę, idź, a wszystko, coć rozkażę, mów');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Nie bój się oblicza ich, bom Ja jest z tobą, abym cię wybawił, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'A wyciągnąwszy Pan rękę swoję, dotknął się ust moich, i rzekł mi Pan: Otom dał słowa moje do ust twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Oto cię dziś postanawiam nad narodami i nad królestwami, abyś wykorzeniał, i psuł, i wytracał, i obalał, i abyś budował i szczepił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Potem stało się słowo Pańskie do mnie, mówiąc: Co widzisz Jeremijaszu? I rzekłem: Widzę rózgę migdałową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'I rzekł Pan do mnie: Dobrze widzisz: albowiem się Ja pospieszam z słowem swem, abym je wykonał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'I stało się słowo Pańskie do mnie powtóre, mówiąc: Co widzisz? I rzekłem: Widzę garniec wrzący, a przednia strona jego ku stronie północnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'I rzekł Pan do mnie: Od północy przypadnie złe na wszystkich mieszkających na tej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Bo oto Ja zawołam wszystkich rodzajów z królestw północnych, mówi Pan, aby przyciągnąwszy każdy z nich, postanowił stolicę swoję w wejściu bram Jeruzalemskich i przy wszystkich murach jego, i przy wszystkich miastach Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'A tak opowiem sądy moje przeciwko nim dla wszelakiej złości tych, którzy mię opuścili, a kadzili bogom obcym, i kłaniali się robocie rąk swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Przetoż ty przepasz biodra swoje, a wstawszy mów do nich wszystko, co Ja tobie rozkazuję, nie bój się ich bym cię snać nie starł przed obliczem ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Bo oto Ja postanawiam cię dziś miastem obronnem, i słupem żelaznym, i murem miedzianym przeciwko tej wszystkiej ziemi, przeciwko królom Judzkim, przeciwko książętom ich, przeciwko kapłanom ich, i przeciwko ludowi tej ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Którzy walczyć będą przeciwko tobie, ale cię nie przemogą: bom Ja z tobą mówi Pan, abym cię wybawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Idź, a wołaj w uszy Jeruzalemskie, mówiąc: Tak mówi Pan: Wspomniałem na cię dla miłosierdzia młodości twojej pokazanego, i dla miłości ślubin twoich; gdyś chodziła za mną na puszczy, w ziemi, w której nie osiewają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Kiedy Izrael był świątobliwością Panu, i pierwocinami urodzajów jego; wszyscy, którzy go pożerali, winni byli, złe rzeczy przyszły na nich, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Słuchajcie słowa Pańskiego, domie Jakóbowy, i wszystkie rodzaje domu Izraelowego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Tak mówi Pan: Jakąż nieprawość znaleźli ojcowie wasi przy mnie, iż się oddalili odemnie, a chodząc za marnością marnymi się stali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Tak iż ani rzekli: Gdzież jest Pan, który was wywiódł z ziemi Egipskiej? który nas wodził po puszczy, po ziemi pustej i strasznej, po ziemi suchej i cieniu śmierci, po ziemi, po której nikt nie chodził, a gdzie żaden człowiek nie mieszkał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Owszem, gdym was wprowadził do ziemi obfitej, abyście pożywali owoców jej, i dóbr jej, wszedłszy tam splugawiliście ziemię moję, a dziedzictwo moje uczyniliście obrzydliwością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Kapłani nie rzekli: Gdzież jest Pan? ani ci, którzy się obierają uczeni w zakonie, poznali mię, i pasterze odstąpili odemnie, i prorocy prorokowali przez Baala, i za rzeczami nie użytecznemi chodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Przeczże się wżdy wadzę z wami, mówi Pan, a z synami synów waszych śpierać się muszę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Przejdźcie przynajmniej wyspy Cytym, a obaczcie; i do Kedar poślijcie a uważajcie pilnie, i przypatrzcie się, jeźli się stało co takowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Jeźli odmienił który naród bogów swoich, chociaż oni nie są bogami; ale lud mój odmienił sławę swoję w rzecz niepożyteczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Zdumiejcie się niebiosa nad tem, a ulęknijcie się, a zatrwożcie się bardzo, mówi Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Bo dwojaką złość popełnił lud mój: mnie opuścili, źródło wód żywych, a wykopali sobie cysterny, cysterny dziurawe, które wody zatrzymać nie mogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Izali Izrael jest niewolnikiem albo wychowańcem w domu spłodzonym? Czemuż jest podany na łup?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Ryczą nań lwięta, i wydawają głos swój, a obracają ziemię jego w pustynię; miasta jego spalone są, tak, że niemasz i jednego obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Synowie też Nof i Tachpanes wierzch głowy twojej zetrą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Zaż tego sam sobie nie sprawujesz? opuszczając Pana, Boga swego, wtenczas, kiedy cię prowadzi drogą swą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'A teraz co za sprawę masz na drogach Egipskich, iż pijesz wodę z Nilu? albo co masz za sprawę na drogach Assyryjczyków, iż pijesz wodę z rzeki ich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Skarze cię złość twoja a odwrócenie twoje sfuka cię. Wiedzże tedy i obacz, iż jest rzecz zła i gorzka, iżeś opuścił Pana, Boga twego, a niemasz bojaźni mojej w tobie, mówi Pan, Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Gdym dawno połamał jarzmo twoje, i rozerwałem związki twoje mówiłaś: Nie będę służyła bałwanom; a przecie na każdym pagórku wysokim, i pod każdem drzewem gałęzistem tułasz się, o nierządnico!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'A Jam cię był nasadził winną macicą wyborną, którejby wszystko nasienie było prawdziwe; jakożeś mi się tedy odmieniła w płonne gałęzie obcej macicy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Bo choćbyś się umywała i saletrą, i mydłem się jako najbardziej tarła, przecież znaczna zostanie nieprawość twoja przedemną, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Jakoż mówisz: Nie jestem splugawiona, za Baalami nie chodziłam? Spojrzyj na drogę twoję w tej dolinie, obacz, coś czyniła, o wielbłądzico prędka, która wiklesz drogi swoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Oślicaś dzika, przywykłaś na puszczy, która według żądzy duszy swej wiatr łapie, gdy się jej przyczyna da; któż ją odwróci? Wszyscy którzy jej szukają, nie strudzą się, i w miesiącu jej znajdą ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Rzekęlić: Zawściągnij nogi twojej, aby bosa nie była, i gardło twe od pragnienia, tedy mówisz: Już to próżno, nie uczynię; bom się rozmiłowała w cudzych, i za nimi pójdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Jako wstyd złodzieja, kiedy go zastaną, tak się zawstydzi dom Izraelski, sami królowie ich, książęta ich, i kapłani ich, i prorocy ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'Którzy mówią drewnu: Tyś jest ojciec mój, a kamieniowi: Tyś mię spłodził. Bo się do mnie obrócili tyłem, a nie twarzą; ale czasu utrapienia swego mawiają: Wstań a wybaw nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'I gdzież są bogowie twoi, którycheś sobie naczynił? Niech wstaną, jeźli cię mogą wybawić czasu utrapienia twego, ponieważ ile masz miast swoich, tyle masz bogów swoich, o Judo!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Czemuż się zemną spierać chcecie? Wyście wszyscy odstąpili odemnie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Próżnom bił synów waszych, karania nie przyjęli; miecz wasz pożarł przecie proroków waszych, jako lew tracący.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'O narodzie! wy rozsądźcie słowa Pańskie. Izalim był pustynią Izraelowi? Izali ziemią ciemną? Przeczże mówi lud mój: Panujemy, nie pójdziemy więcej do ciebie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Izali zapomina panna ubioru swego, i oblubienica klejnotów swoich? Ale lud mój zapomniał mię przez dni niezliczone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Przecz dobrą być twierdzisz drogę twoję, szukając tego, w czem się kochasz? Przecz i innych nierządnic uczysz złośliwych dróg twoich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Nadto i na podołkach twoich znajduje się krew dusz ubogich i niewinnych; nie z pracą znalazłem to, bo to widzieć na wszystkich podołkach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'A przecież mówisz: Ponieważem niewinną, pewnie odwrócona jest zapalczywość jego odemnie. Oto Ja w sąd wnijdę z tobą, przeto, że mówisz: Nie zgrzeszyłam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Przeczże tak biegasz, odmieniając drogi swe? Tak będziesz pohańbiona od Egipczanów, jakoś pohańbiona była od Assyryjczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'I stamtąd wyjdziesz, mając ręce swe nad głową swą: bo Pan odrzuca ufności twoje, a nie poszczęścić się w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Pan mówi: Opuściłliby mąż żonę swoję, a ona odszedłszy od niego szłaby za innego męża, izali się więcej do niej wróci? Izaliby nie była wielce splugawiona ona ziemia? Ale ty, chociażeś nierząd płodziła z wielą zalotników, wszakże nawróć się d o mnie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Podnieś oczu swych na miejsca wysokie, a obacz, jeźliś gdzie nierządu nie płodziła. Na drogach siadałaś kwoli nim, jako Arabczyk na puszczy, a splugawiłaś ziemię wszeteczeństwem twem, i złością twoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'A chociaż zawściągnione są dżdże jesienne, a deszczu na wiosnę nie bywało, przecieżeś czoło niewiasty wszetecznej mając, nie chciałaś się wstydzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Azaż od tego czasu wołać będziesz na mnie: Ojcze mój! Tyś wodzem młodości mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Izali Bóg zatrzyma gniew na wieczność? Izali go zachowa na wieki? Oto mówisz i czynisz złe, ile możesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Tedy Pan rzekł do mnie za dni Jozyjasza króla: Widziałżeś, co uczyniła odporna córka Izraelska? jako chodziła na każdą górę wysoką, i pod każde drzewo zielone, i tam nierząd płodziła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'A chociażem rzekł, gdy to wszystko uczyniła: Nawróć się do mnie! przecie się nie nawróciła; a na to patrzyła przestępnica siostra jej, córka Judzka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'A tak zdało mi się dla tych wszystkich przyczyn, ponieważ nierząd płodziła uporna córka Izraelska, opuścić ją, i dać jej list rozwodny; a przecież się nie ulękła przestępnica siostra jej, córka Judzka, ale szedłszy i sama nierząd płodziła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'I stało się, że haniebnym nierządem swoim splugawiła ziemię; bo cudzołożyła z kamieniem i z drewnem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'A wszakże w tem wszystkiem nie nawróciła się do mnie przestępnica siostra jej, córka Judzka, z wszystkiego serca swego; ale obłudnie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Przetoż rzekł Pan do mnie: Usprawiedliwiła duszę swą odporna córka Izraelska więcej, niżeli przestępnica Judzka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Idźże, a wołaj temi słowy ku północy a mów: Nawróć się, odporna córko Izraelska! mówi Pan, a nie obórzy się twarz moja surowa na was, bom Ja dobrotliwy, mówi Pan, a nie chowam gniewu na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Tylko uznaj nieprawość twoję, żeś od Pana, Boga swego, odstąpiła, a tam i sam biegała drogami swemi do obcych bogów pod każde drzewo zielone, a głosu mojego nie słuchaliście, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Nawróćcież się, synowie uporni! mówi Pan; bom Ja jest małżonkiem waszym, a przyjmę was jednego z miasta, a dwóch z rodzaju, abym was wprowadził do Syonu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Gdzie wam dam pasterzy według serca mego, i będą was paść umiejętnie i rozumnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'I stanie się, gdy się rozmnożycie a rozrodzicie się w tej ziemi w oneż dni, mówi Pan, nie będą więcej mówić: \"Skrzynia przymierza Pańskiego\", ani wstąpi na serce, ani wspomną na nią, ani jej nawiedzać, ani jej więcej poważać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Czasu onego nazwane będzie Jeruzalem stolicą Pańską, a zgromadzą się do niego wszystkie narody, do imienia Pańskiego, do Jeruzalemu, i nie będą więcej chodzić za uporem serca swego złośliwego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'W one dni pójdą dom Judzki z domem Izraelskim, i przyjdą pospołu z ziemi północnej do ziemi, którąm dał w dziedzictwo ojcom waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Chociażem Ja rzekł: Jakożbym cię położył między synami, a dał ci ziemię pożądaną, dziedzictwo zacne zastępów pogańskich? chyba żebyś mię wzywał, mówiąc: Ojcze mój! a od naśladowania mnie nie odwrócił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Ponieważ jako żona przeniewierza się mężowi swemu, takeście mi się przeniewierzyli, o domie Izraelski! mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Głos na wysokich miejscach niech będzie słyszany, płacz modlitw synów Izraelskich; bo przewrotne uczyniwszy drogi swe zapamiętali na Pana, Boga swego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Mówiącego: Nawróćcie się, synowie odporni! a uleczę odwrócenia wasze; mówcie: Oto my idziemy do ciebie, boś ty jest Pan, Bóg nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Zaiste próżna jest nadzieja w pagórkach i w mnóstwie gór; zaiste w Panu, Bogu naszym, jest zbawienie Izraelskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Bo ta hańba pożarła pracę ojców naszych od młodości naszej, trzody ich, i stada ich, syny ich, i córki ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Leżymy w pohańbieniu swem, a przykrywa nas zelżywość nasza; albowiemśmy przeciwko Panu, Bogu naszemu, zgrzeszyli, my i ojcowie nasi, od młodości naszej aż do dnia tego, a nie usłuchaliśmu głosu Pana, Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Jeźlibyś się chciał nawrócić, Izraelu! mówi Pan, do mnie się nawróć. Bo jeźli odejmiesz obrzydłości twoje od oblicza mego, a nie będziesz się tułał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'I przysiężeszli w prawdzie, w sądzie i w sprawiedliwości, mówiąc: Jako żyje Pan; tedy błogosławić sobie w nim będą narody, i w nim się przechwalać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Albowiem tak mówi Pan mężom Judzkim i Jeruzalemskim: Poorzcie sobie nowinę, a nie siejcie na cierniu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Obrzeżcie się Panu, a odejmijcie nieobrzezki serca waszego, mężowie Judzcy, a obywatele Jeruzalemscy! by snać nie wyszła jako ogień popędliwość moja, a nie zapaliła się, a nie byłby, ktoby ugasił dla złości przedsięwzięcia waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Opowiadajcie w Judzie, a w Jeruzalemie ogłaszajcie, i mówcie: Zatrąbcie w trąbę w ziemi, zwołajcie, zgromadźcie lud, a mówcie: Zbierzcie się, a wejdźmy do miast obronnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Podnieście chorągiew na Syonie, bądźcie serca dobrego, nie zastanawiajcie się; bo Ja złe przywiodę od północy, i porażkę wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Wychodzi lew z jaskini swojej, a ten, który niszczy narody, wyszedłszy z miejsca swego, ciągnie, aby obrócił ziemię twoję w pustynię, a miasta twoje aby zburzone były, aby nie było żadnego obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Przetoż przepaście się worami, narzekajcie a kwilcie, bo nie jest odwrócony gniew zapalczywości Pańskiej od nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'I stanie się dnia onego, mówi Pan, że zginie serce królewskie, i serce książąt, a zdumieją się kapłani, i prorocy dziwować się będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'I rzekłem: Ach panujący Panie! zaprawdęś bardzo ten lud i Jeruzalem omylił, mówiąc: Pokój mieć będziecie! a wżdy miecz przeniknął aż do duszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Czasu onego rzeką temu ludowi i Jeruzalemowi: Wiatr gwałtowny z miejsc wysokich na puszczy idzie prosto na lud mój, nie żeby przewiewał, ani wyczyszczał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Wiatr gwałtowniejszy niż oni przyjdzie mi; teraz Ja też opowiem im sądy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Oto występuje jako obłoki, a wozy jego jako wicher, prędsze są niż orły konie jego. Biada nam! bośmy spustoszeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Omyj od złości serce twoje, Jeruzalem! abyś wybawione było. Dokądże trwać będą w pośrodku ciebie myśli nieprawości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Bo głos opowiadającego idzie od Danu, a tego, który ogłasza nieprawość, z góry Efraim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Przypominajcież tym narodom: Oto ogłaszajcie Jeruzalemczykom, że stróżowie przychodzą z ziemi dalekiej, a wydawają przeciwko miastom Judzkim głos swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Jako stróżowie pól położą się przeciwko niemu w około; bo mię do gniewu wzruszyło, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Droga twoja i postępki twoje to uczyniły tobie; toć złość twoja przyniosła, że to jest gorzkie, a że przenika aż do serca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'O wnętrzności moje, wnętrzności moje! boleść cierpię. O osierdzia moje! trwoży się we mnie serce moje, nie zamilczę; bo głos trąby słyszysz, duszo moja! i okrzyk wojenny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Porażka za porażką ogłasza się, spustoszona będzie zaiste wszystka ziemia; nagle spustoszone będą namioty moje, i opony moje w okamgnieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Dokądże widzieć będę chorągiew, i słyszeć głos trąby?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Bo głupi lud mój nie zna mię, synowie niemądrzy i nierozumni są; mądrzy są do czynienia złego, ale dobrze czynić nie umieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Spojrzęli na ziemię, a oto jest niepozorna i próżna; jeżeli na niebo, nie masz na niem światłości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Spojrzęli na góry, a oto się trzęsą, i wszystkie pagórki chwieją się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Spojrzęli, a oto niemasz człowieka, i wszelkie ptastwo niebieskie odleciało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Spojrzęli, a oto pole urodzajne jest pustynią, a wszystkie miasta jego zburzone są od oblicza Pańskiego, i od oblicza gniewu zapalczywości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Bo tak mówi Pan: Spustoszona będzie wszystka ziemia, wszakże końca jeszcze nie uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Nad tem ziemia kwilić będzie, a niebiosa w górze zaćmią się, przeto, żem mówił, com umyślił, a nie żałuję, ani się odwrócę od tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Przed grzmotem jeźdźców i strzelających z łuku uciecze wszystko miasto; wejdą do gęstych obłoków, i na skały wstąpią. Wszystkie miasta opuszczone będą, a nie będzie, ktoby w nich mieszkał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'A ty zburzona będąc cóż uczynisz? Choćbyś się ubrała w szarłat, choćbyś się ozdobiła ozdobą złotą, choćbyś też oblicze twe przyprawiła barwiczką, próżno się stroisz; wzgardzą tobą zalotnicy twoi, a duszy twojej szukać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Bom słyszał głos jako rodzącej, uciski jako pierworodzącej, głos córki Syońskiej narzekającej, a załamującej ręce swe, mówiąc: Biada mnie teraz! bo ustała dusza moja dla morderców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Obchodźcie ulice Jeruzalemskie, a upatrujcie teraz, i obaczcie, a szukajcie po ulicach jego, jeźli znajdziecie męża, jeźli kto jest coby czynił sąd i szukał prawdy, a przepuszczę mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Ale choć mówią: Jako żyje Pan, tedy przecię krzywo przysięgają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'O Panie! izali oczy twoje nie patrzą na prawdę? Bijesz ich, ale ich nie boli; wniwecz ich obracasz, ale nie chcą przyjąć karania; zatwardzili oblicza swe nad opokę, nie chcą się nawrócić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Tedym Ja rzekł: Podobno ci nędzni są, głupio sobie poczynają; bo nie są powiadomi drogi Pańskiej, i sądu Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Pójdę do celniejszych, i będę mówił do nich; bo oni są powiadomi drogi Pańskiej, i sądu Boga swego; ale i ci wespół połamali jarzmo, potargali związki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Przetoż ich pobije lew z lasu, wilk wieczorny wygubi ich, lampart czyhać będzie u miast ich. Ktokolwiek wyjdzie z nich, rozszarpany będzie; bo się rozmnożyły przestępstwa ich, i zmogły się odwrócenia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Jestże co, dlaczegobym ci miał przepuścić? Synowie twoi opuścili mię, a przysięgają przez onych, którzy nie są bogami. Jakom ich jedno nakarmił, zaraz cudzołożą, a do domu wszetecznicy hurmem się walą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Rano wstawając są jako konie wytuczone, każdy z nich rży do żony bliźniego swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Izali dlatego nawiedzić ich nie mam? mówi Pan; izali się nad takim narodem nie ma mścić dusza moja?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Wstąpcie na mury jego, a rozwalcie je, wszakże ich do gruntu nie znoście; znieście filarzyki murów jego, gdyż nie są Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Wielce zaiste wystąpił przeciwko mnie dom Izraelski i dom Judzki, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Zadali kłamstwo Panu, i rzekli: Nie tak, nie przyjdzieć na nas nic złego, a miecza i głodu nie doznamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'A ci prorocy pominą z wiatrem, a żadnego słowa Bożego niemasz u nich; i owszem tak się im samym stanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Przetoż tak mówi Pan, Bóg zastępów: Ponieważeście to mówili, oto Ja kładę słowa moje w usta twoje za ogień, a lud ten za drwa, i pożre ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Oto Ja przywiodę na was naród z daleka, o domie Izraelski! mówi Pan, naród mocny, naród starodawny, naród, którego języka umieć nie będziesz, ani zrozumiesz, co mówi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Którego sajdak jako grób otwarty, wszyscy są mężni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'I zjedzą urodzaj twój, i chleb twój: pożrą synów twoich i córki twoje; poje trzody twoje i woły twoje; poje winną macicę twoję, i figi twoje, a miasta twoje obronne, w których ty ufasz, mieczem znędzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'A wszakże i w one dni, mówi Pan, końca z wami nie uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Albowiem gdy rzeczecie: Przeczże nam Pan, Bóg nasz, to wszystko czyni? Tedy im odpowiesz: Jakoście mię opuścili, a służyli bogom cudzym w ziemi waszej, tak służyć będziecie cudzoziemcom w ziemi nie waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Oznajmijcie to domowi Jakóbowemu, a rozgłoście w Judzie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Słuchajcież teraz tego, ludu głupi! który niemasz serca, który oczy mając, a nie widzisz, który uszy mając, a nie słyszysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'I nie będziecież się mnie bali? mówi Pan; a przed obliczem mojem nie będziecież się lękali? którym położył morzu piasek za granicę ustawą wieczną, a nie przestąpi jej. Choć się wzruszą, wszakże nie przemogą; choć się wzburzą wały jego, wszakże nie przeskoczą go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Ale ten lud ma serce ociążałe i odporne; odstąpili odemnie i odeszli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Ani rzekli w sercu swem: Bójmy się już Pana, Boga naszego, który daje deszcz i w jesieni i na wiosnę czasu swego, który tygodni pewnych i żniwa naszego przestrzega.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Ale nieprawości wasze odwróciły to, a grzechy wasze zahamowały to dobro od was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Bo się znajdują w ludu moim niezbożnicy, którzy czyhają jako łowcy, rozciągają sieci, zastawiają sidła, a łapią ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Jako klatka pełna ptaków, tak domy ich pełne są zdrady; przetoż się wzmogli i zbogacili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Roztyli, lśnią się, i innych w złościach przewyższają; sprawy nie sądzą, ani sprawy sierotki; wszakże się im szczęści, chociaż sprawy ubogiego nie rozsądzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Izali dlatego nie nawiedzę ich? mówi Pan; izali się nad narodem takowym nie będzie mścić dusza moja?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Rzecz dziwna i sroga dzieje się w tej ziemi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Prorocy kłamliwie prorokują, a kapłani panują przez ręce ich, a lud mój kocha się w tem; czegożbyście na ostatek nie uczynili?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Zgromadźcie się, synowie Benjaminowi! z pośrodku Jeruzalemu, a w Tekue trąbcie w trąbę, i nad Betcherem podnieście chorągiew! bo złe ukazało się z północy, i zburzenie wielkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Pięknej, rozkosznej pannie przypodobałem był córkę Syońską;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Ale do niej przyciągną pasterze i trzody ich; rozbiją przeciwko niej namioty w około, spasie każdy miejsce swoje, i rzeką:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Podnieście przeciwko niej wojnę, wstańcie, a wtargniemy w południe; biada nam, że się nachylił dzień, że się rozciągnęły cienie wieczorne!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Wstańcie, a wtargniemy w nocy, i rozwalmy pałace jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Bo tak mówi Pan zastępów: Narąbcie drzewa, a usypcie przeciw Jeruzalemowi szańce; toć to miasto jest, które ma być nawiedzione; jakożkolwiek wielkie, niemasz jedno ucisk w pośrodku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Jako źródło wylewa wody swe, tak ono wylewa złość swoję; ucisk i spustoszenie słychać w niem przed obliczem mojem ustawicznie, boleść i bicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Ćwicz się Jeruzalemie! by snać nie odstąpiła dusza moja od ciebie, bym cię snać nie obrócił w pustynię ziemi do mieszkania niesposobną,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Tak mówi Pan zastępów: Ostatek Izraela aż do grona wyzbierają, jako winnicę, i rzeką: Sięgaj ręką twoją, jako ten, co zbiera wino do kosza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Do kogoż mówić będę, i kim oświadczę, aby słyszeli? Oto nieobrzezane są uszy ich, tak, że słuchać nie mogą; oto słowo Pańskie mają za hańbę i nie kochają się w niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Przetoż pełenem zapalczywości Pańskiej, upracowałem się, zawściągając ją w sobie. Wylana będzie tak na maluczkiego na ulicy, jako i na zebranie młodzieńców; owszem, i mąż z żoną, a starzec ze zgrzybiałym pojmany będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'I przypadną domy ich na inszych, także pola i żony ich, gdyż wyciągnę rękę moję na obywateli tej ziemi, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Zaiste, od najmniejszego z nich aż do największego z nich, wszyscy się udali za łakomstwem; od proroka aż do kapłana, wszyscy zgoła bawią się kłamstwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'I leczą skruszenie córki ludu mego tylko po wierzchu, mówiąc: Pokój, pokój! choć niemasz pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Izali się zawstydzili, przeto że obrzydłość czynili? Zaiste ani się lud wstydził, ani ich prorocy do wstydu przywieść mogli; przetoż upadną między padającymi; czasu, którego ich nawiedzę, upadną, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Gdy tak Pan mawiał: Zastanówcie się na drogach, a spojrzyjcie i pytajcie się o ścieszkach starych, któraby była droga dobra, a chodźcie nią, a znajdziecie odpocznienie duszy waszej: tedy odpowiadali: Nie będziemy chodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'A gdym postanawiał nad wami stróżów, mówiąc: Słuchajcie głosu trąby! tedy mawiali: Nie będziemy słuchać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Przetoż słuchajcie, o narody! a poznaj, o zgromadzenie! co się dzieje między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Słuchaj, o ziemio! Oto Ja przywiodę złe na ten lud, owoce myśli ich, przeto, że nie słuchają słów moich, ani zakonu mego, ale go odrzucają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Na cóż mi kadzidło z Saby przychodzi, a cynamon wonny wyborny z ziemi dalekiej? Całopalenia wasze nie są mi przyjemne, i ofiary wasze nie podobają mi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Przetoż tak mówi Pan: Oto ja nakładę ludowi temu zawad, o które się otrącać będą ojcowie, także i synowie, sąsiad i bliźni jego, i poginą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Tak mówi Pan: Oto lud przyciągnie z ziemi północnej, a naród wielki powstanie od kończyn ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Łuk i włócznię pochwyci, okrutny będzie, a nie zlituje się. Głos ich jako morze zahuczy, a na koniach jeździć będą, naród uszykowany jako mąż do boju przeciwko tobie, o córko Syońska!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Skoro usłyszymy wieść o nim, osłabieją ręce nasze, ucisk nas ogarnie, i boleść jako rodzącą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Nie wychodźcie na pole, i w drogę nie chodźcie; bo miecz nieprzyjacielski a strach w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'O córko ludu mojego! przepasz się worem a walaj się w popiele; uczyń sobie żal jako po jedynaku, żal gorzki; bo na nas nagle burzyciel przypadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Dałem cię za basztę i za wieżę w ludu moim, abyś upatrywał i doświadczał drogi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Wszyscy są między krnąbrnymi najkrnąbrniejsi, chodzą jako obmowca, są jako miedź i żelaza; wszyscy zgoła są skażonymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Murzszeją miechy, ołów od ognia niszczeje, próżno ustawicznie złotnik pławi; bo złe rzeczy nie mogą być oddalone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Srebrem fałszywem będą nazwani; bo ich Pan odrzucił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Słowo, które się stało do Jeremijasza od Pana, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Staw się w bramie domu Pańskiego, a opowiadaj tam to słowo, i mów: Słuchajcie słowa Pańskiego wszystek Judo, którzy wchodzicie do bram ich, abyście się kłaniali Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Tak mówi Pan zastępów, Bóg Izraelski: Polepszajcie dróg swoich, i przedsięwzięcia swego, a sprawię to, abyście mieszkali na tem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Nie pokładajcie nadziei swej w słowach kłamliwych, mówiąc: Kościół Pański, kościół Pański, kościół Pański jest!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Ale jeźliże polepszając polepszycie dróg swoich, i przedsięwzięcia swego; jeźliże sprawiedliwy sąd czynić będziecie między mężem a między bliźnim jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Przychodnia, sierotki i wdowy nie uciśniecie, i krwi niewinnej nie rozlejecie na tem miejscu, a za bogami cudzymi nie pójdziecie na swe złe:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Tedy sprawię, abyście mieszkali na tem miejscu w ziemi, którąm dał ojcom waszym, od wieku aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Oto wy pokładacie nadzieję swoję w słowach kłamliwych, które nie pomogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Izali kradnąc, zabijając, i cudzołożąc, i krzywoprzysięgając, i kadząc Baalowi, a chodząc za bogami obcymi, których nie znacie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Przecież chodzić a stawać będziecie przed obliczem mojem w tym domu, który nazwany jest od imienia mego, i mówić: Wybawieniśmy, abyśmy czynili te wszystkie obrzydliwości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Azaż jaskinią łotrowską jest dom ten przed oczyma waszemi, który nazwany jest od imienia mego? Oto widzęć Ja to, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Ale idźcie przynajmniej na miejsce moje, które było w Sylo, gdziem był sprawił przybytek imieniowi memu z początku, a obaczcie, com mu uczynił dla złości ludu mego Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Przetoż teraz, ponieważ czynicie te wszystkie sprawy, mówi Pan, a gdy mówię do was rano wstawając a to ustawicznie, a nie słuchacie, gdy wołam na was, a nie ozywacie się:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'Przetoż uczynię domowi temu, który nazwany jest od imienia mego, w którym wy ufacie, i miejscu temu, którem wam dał i ojcom waszym, jakom uczynił Sylo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'I odrzucę was od oblicza mego, jakom odrzucił braci waszych, wszystko nasienie Efraimowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Ty tedy nie módl się za tym ludem, ani podnoś za nim głosu modlitwy, i nie przyczyniaj się do mnie; bo cię nie wysłucham.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Azaż sam nie widzisz, co oni broją w miastach Judzkich i po ulicach Jeruzalemskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Synowie zbierają drwa, a ojcowie rozniecają ogień, a żony ich rozczyniają ciasto, aby czyniły placki królowej niebieskiej, i sprawowały mokre ofiary bogom cudzym, aby mię do gniewu pobudzali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Izali to przeciwko mnie jest, że mię do gniewu wzruszają? mówi Pan; izali to nie raczej przeciwko nim, ku pohańbieniu twarzy ich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Przetoż tak mówi panujący Pan: Oto gniew mój i popędliwość moja będzie wylana na to miejsce, na ludzi i na bydlęta, i na drzewa polne, i na owoce ziemi, i zapali się, a nie ugaśnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Tak mówi Pan zastępów, Bóg Izraelski: Całopalenie wasze przydajcie do ofiar waszych, a jedzcie mięso.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Bom nie mówił z ojcami waszymi, anim im przykazał onego dnia, któregom ich wywiódł z ziemi Egipskiej, o całopaleniu i ofiarach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Ale tom im przykazał, mówiąc: Słuchajcie głosu mojego, i będę Bogiem waszym, a wy będziecie ludem moim; a chodźcie każdą drogą, którąm wam przykazał, aby wam dobrze było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Lecz nie posłuchali, ani nakłonili ucha swego, aby chodzili za radami i za uporem serca swego złego; i obrócili się grzbietem, a nie twarzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Ode dnia, którego wyszli ojcowie wasi z ziemi egipskiej, aż do dnia tego, posyłałem do was wszystkich sług moich proroków, co dzień rano wstawając i posyłając;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'A wszakże nie słuchali mię, i nie nakłonili ucha swego, ale zatwardziwszy kark swój, gorzej czynili niźeli ojcowie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Gdy im będziesz mówił te wszystkie słowa, i ciebie nie usłuchają; a gdy na nich wołać będziesz, nie ozwąć się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Przetoż mów do nich: Ten jest naród, który nie słucha głosu Pana, Boga swego, ani przyjmuje nauki; zginęła prawda, i odjęta jest od ust ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Ogól włosy swe i odrzuć, a narzekaj głośno na miejscach wysokich; bo odrzucił Pan i opuścił rodzaj, na który się bardzo gniewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Zaiste synowie Judzcy czynili złość przed oczyma mojemi, mówi Pan; nastawiali obrzydliwości swych w tym domu, który nazwany jest od imienia mojego, aby go splugawili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Nadto pobudowali wyżyny Tofet, które jest w dolinie syna Hennomowego, aby palili synów swych i córki swe ogniem, czegom nie rozkazał, ani wstąpiło na serce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Dlatego oto dni idą, mówi Pan, gdy to więcej nie będzie zwano Tofet, ani dolina syna Hennomowego, ale dolina morderstwa; i będą pogrzebywać w Tofet; bo indziej miejsca nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'I będą trupy ludu tego pokarmem ptastwu niebieskiemu, i zwierzowi ziemskiemu, a nie będzie, ktoby odegnał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'I uczynię, że ustanie w miastach Judzkich, i w ulicach Jeruzalemskich głos radości, i głos wesela, głos oblubieńca, i głos oblubienicy; bo ziemia będzie spustoszona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Czasu onego, mówi Pan, wybiorą kości królów Judzkich, i kości książąt ich, i kości kapłanów, i kości proroków, i kości obywateli Jeruzalemskich z grobów ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'I rozrzucą je przed słońce, i przed miesiąc, i przed wszystko wojsko niebieskie, które miłują, i którym służą, i za którymi chodzą, i których szukają, i którym się kłaniają; nie pozbierają ich, ani pogrzebią, ale będą miasto gnoju na wierzchu ziem i.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'I obiorą raczej śmierć niżeli żywot wszystkie ostatki, które zostaną z tego rodzaju złośliwego po wszystkich miejscach, gdziebykolwiek zostali, tam, kędy ich zapędzę, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Przetoż rzeczesz do nich: Tak mówi Pan: Także upadli, aby nie mogli powstać? także się odwrócił, aby się zaś nie mógł nawrócić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Przeczże się odwrócił ten lud Jeruzalemski odwróceniem wiecznem? chwytają się kłamstwa a nie chcą się nawracać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Pilnowałem i słuchałem: nic nie mówiąc, co jest prawego; niemasz ktoby żałował złości swej, mówiąc: Cóżem uczynił? Każdy się obrócił za biegiem swoim, jako koń, który pędem bieży ku potkaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'I bocian na powietrzu zna ustawione czasy swoje, i synogarlica, i żuraw, i jaskółka przestrzegają czasu przylecenia swego; ale lud mój nie zna sądu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Jakoż mówicie: Myśmy mądrzy, a zakon Pański jest przy nas? zaprawdę, oto daremnie pióro pisarz czyni; daremnie są w zakonie biegłymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Kogoż zawstydzili ci mędrcy? Którzyż są przestraszeni i pojmani? Oto słowo Pańskie odrzucają; cóż to tedy za mądrość ich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Dlatego dam żony ich innym, pola ich tym, którzy ich opanują; bo od najmniejszego aż do największego, wszyscy zgoła udali się za łakomstwem; od proroka aż do kapłana wszyscy przewodzą kłamstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Bo leczą skruszenie córki ludu mego tylko po wierzchu, mówiąc: Pokój, pokój! choć niemasz pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Izali się zawstydzili, przeto, że obrzydliwość czynili? Zaiste, ani się zapałać ani wstydzić umieli; przetoż upadną między padającymi, czasu nawiedzenia swego upadną, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Do szczętu ich wykorzenię, mówi Pan; nie będzie żadnego grona na winnej macicy, ani żadnych fig na drzewie figowem; nawet i liść opadnie, a com im dał, odjęte będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Przecz my tu siedzimy? Zejdźcie się, a wynijdżmy do miast obronnych, a tam odpoczniemy; ale Pan, Bóg nasz każe nam odpocznąć, gdy nas napoi wodą żółci, iżeśmy zgrzeszyli przeciwko Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Czekaj pokoju, alić nic dobrego; czasu uzdrowienia, alić oto strach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Od Dan słyszeć chrapanie koni jego, od głosu wykrzykania mocarzy jego wszystka ziemia zadrżała, którzy ciągną, aby pożarli ziemię, i wszystko, co jest na niej, miasto i tych, którzy mieszkają w niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Bo oto Ja poślę na was węże najjadowitsze, przeciwko którym niemasz zaklinania; i pokąsają was, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Serce moje we mnie, któreby mię miało posilać w smutku, mdłe jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Oto głos krzyku córki ludu mego z ziemi bardzo dalekiej mówiącej: Izali Pana niemasz na Syonie? Izali króla jego niemasz na nim? Przeczże mię wzruszyli do gniewu bałwanami swemi, próżnościami cudzoziemców?mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Pominęło żniwo, skończyło się lato, a myśmy nie wybawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Dla skruszenia córki ludu mojego skruszonym jest, żałobę ponoszę, zdumienie zdjęło mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Izali niemasz balsamu w Galaad? Izali tam niemasz lekarza? Czemuż tedy nie jest uleczona córka ludu mojego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Kto mi to da, aby głowa moja wodą była, a oczy moje źródłem łez, abym we dnie i w nocy płakał pomordowanych córki ludu mego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Któż mi da na puszczy gospodę podróżnych, abym opuścił lud mój, i odszedł od nich? bo wszyscy są cudzołożnicy, zgraja przestępników;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'I naciągają języka swego do kłamstwa jako łuku swego, zmocnili się na ziemi, ale nie ku prawdzie; bo ze złego w złe postępują, a mnie nie znają, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Każdy niech się strzeże bliźniego swego, a nie każdemu bratu dowierza; bo każdy brat jest na tem jakoby podszedł, a każdy bliźni zdradliwie postępuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Każdy też bliźniego swego oszukuje, a prawdy nie mówi; naucza języka swego mówić kłamstwo, źle czyniąc ustawają');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Mieszkanie twoje, o proroku! jest w pośrodku ludu zdradliwego; dla zdrad nie chcą mię poznać, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'A przetoż tak mówi Pan zastępów: Oto Ja pławiąc ich próbowałem ich; jakoż się tedy już mam obchodzić z córką ludu mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Strzałą śmiertelną jest język ich, zdradę mówi; usty swemi o pokoju z przyjacielem swym mówi, ale w sercu swem zakłada nań sidła swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Izali dlatego nienawidzę ich? mówi Pan; izali nad narodem takowym nie pomści się dusza moja?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Dla tych gór udam się na płacz i na narzekanie, i dla pastwisk, które są na puszczy, na kwilenie; bo spalone będą, tak, że nie będzie, ktoby je przechodził, ani tam głosu bydlęcia słychać będzie; ptastwo niebieskie i bydlęta rozbieżą się i odejdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'I obrócę Jeruzalem w gromady rumu, w mieszkanie smoków; a miasta Judzkie obrócę w pustynię, tak, iż nie będzie obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Któż jest tak mądry, coby to wyrozumiał? a do kogo mówiły usta Pańskie, coby to oznajmił, dlaczego zginąć ma ta ziemia, i wypalona być ma jako pustynia, tak aby nie było, ktoby ją przeszedł?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Bo Pan mówi: Iż opuścili zakon mój, którym im przedłożył, a nie słuchali głosu mojego, ani chodzili za nim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Ale chodzili za uporem serca swego i za Baalem, czego ich nauczyli ojcowie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Dlatego tak mówi Pan zastępów, Bóg Izraelski: Oto Ja nakarmię ich, to jest lud ten, piołunem, a napoję ich wodą żółci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'Albowiem rozproszę ich między narody, których nie znali oni i ojcowie ich, i poślę za nimi miecz, aż ich do końca wygładzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Tak mówi Pan zastępów: Uważcie to, a przyzówcie narzekających niewiast, niech przyjdą, a do tych, które są w tem wyćwiczone, poślijcie, aby przyszły;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Niech się pospieszą, a niech uczynią nad nami narzekanie, aby oczy nasze łzy wylewały, a powieki nasze opływały wodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Głos zaiste narzekania słyszeć z Syonu: O jakośmy spustoszeni! bardzośmy zelżeni; bośmy stracili ziemię, bo rozrzucone są przybytki nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Owszem, słuchajcie niewiasty! słowa Pańskiego, a niech przyjmie ucho wasze wyrok ust jego, abyście uczyły córek swoich lamentu, a każda z was towarzyszkę swoję narzekania;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Bo wlazła śmierć oknami naszemi, weszła na pałace nasze, aby wytraciła dzieci z rynku, a młodzieńce z ulic.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, '(Mów i to: Tak mówi Pan:) I padły trupy ludzkie jako gnój po polu, a jako snopy za żeńcami, a niemasz ktoby pochował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Tak mówi Pan: Niech się nie chlubi mądry z mądrości swojej, i niech się nie chlubi mocarz z mocy swojej, i niech się nie chlubi bogaty z bogactw swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Ale w tem niechaj się chlubi, kto się chlubi, że rozumie a zna mię, żem Ja jest Pan, który czynię miłosierdzie, sąd i sprawiedliwość na ziemi; bo mi się to podoba, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Oto dni idą, mówi Pan, w których nawiedzę każdego obrzezańca i nieobrzezańca:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Egipczanów, i Judę, i Edomczyków, i Amonitczyków, i Moabczyków, i wszystkich, którzy w ostatnim kącie mieszkają na puszczy; bo te wszystkie narody nieobrzezane są, a wszystek dom Izraelski jest nieobrzezany sercem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Słuchajcie słowa tego, które Pan mówi do was, o domie Izraelski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Tak mówi Pan: Drogi pogańskiej nie uczcie się, a zanamion niebieskich nie bójcie się; bo się ich poganie boją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Ustawy zaiste tych narodów są wierutna marność; bo uciąwszy drzewo siekierą w lesie, dzieło rąk rzemieślnika,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Srebrem i złotem ozdabia je, gwoździami i młotami utwierdza je, aby się nie ruchało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Stoją prosto jako palma, a nie mówią; noszone być muszą, bo chodzić nie mogą. Nie bójcie się ich; bo źle czynić nie mogą, i dobrze czynić nie mogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Żaden z tych nie jest tobie podobny, Panie! wielkiś ty, i wielkie jest imię twoje w mocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Któżby się ciebie nie bał? Królu narodów! Tobie to zaiste należy, ponieważ między wszystkimi mędrcami narodów, i we wszystkich królestwach ich nigdy nie był podobny tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'A wszakże społem zgłupieli i poszaleli; z drewna brać naukę, jest wierutna marność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Srebro ciągnione z zamorza przywożone bywa, a złoto z Ufas, dzieło rzemieślnicze, i ręki złotnika; hijacynt i szarłat odzienie ich, wszystko to jest dzieło umiejętnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Ale Pan jest Bóg prawy, jest Bóg żywy, i król wieczny; przed jego zapalczywością ziemia drży, a narody nie mogą znieść rozgniewania jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Tak im tedy powiecie: Bogowie ci, którzy nieba i ziemi nie stworzyli, niech zginą z ziemi, a niech ich nie będzie pod niebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Ale on uczynił ziemię mocą swą; on utwierdził okrąg świata mądrością swoją, i roztropnością swoją rozciągnął niebiosa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Gdy on wydaje głos, szum wód bywa na niebie, i to sposabia, aby występowały pary z krajów ziemi; błyskawice z deszczem przywodzi, a wywodzi wiatry z skarbów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Tak zgłupiał każdy człowiek, że tego nie zna, iż pohańbiony bywa każdy rzemieślnik dla bałwana; bo fałszem jest to, co ulał, i niemasz ducha w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Marnością są, a dziełem błędów; czasu nawiedzenia swego poginą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Nie jest tym podobien dział Jakóbowy, bo on jest stworzyciel wszystkiego; Izrael także jest prętem dziedzictwa jego, Pan zastępów jest imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Zbierz z ziemi towary twoje, ty, która mieszkasz na miejscu obronnem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Bo tak mówi Pan: Oto Ja jako z procy ugodzę obywateli ziemi jednym razem, i udręczę, aby tego doznali i rzekli:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Biada mnie nad zniszczeniem mojem: bolesna jest rana moja, chociażem był rzekł: Zaiste tę niemoc będę mógł znieść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Namiot mój zburzony jest, i wszystkie powrozy moje porwane są; synowie moi poszli odemnie, i niemasz ich; niemasz, ktoby więcej rozbijał namiot mój, a rozciągał opony moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Bo pasterze zgłupieli, a Pana się nie dokładali; dlatego nie powodzi się im szczęśliwie, a wszystka trzoda pastwiska ich rozproszona jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Oto wieść pewna przychodzi, a wzruszenie wielkie z ziemi północnej, aby obrócone były miasta Judzkie w pustynie, i w mieszkanie smoków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Wiem, Panie! że nie jest w mocy człowieka droga jego, ani jest w mocy męża tego, który chodzi, aby sprawował postępki swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Karz mię, Panie! ale łaskawie, nie w gniewie swym, byś mię snać wniwecz nie obrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Wylej popędliwość twoję na te narody, które cię nie znają, i na rodzaje, które imienia twego nie wzywają; bo jedzą Jakóba, i pożerają go, aby go wszystkiego strawili, i mieszkanie jego w pustki obrócili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Słowo, które się stało do Jeremijasza od Pana mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Słuchajcie słów przymierza tego, którebyście mówili do mężów Judzkich i do obywateli Jeruzalemskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'A rzeczesz do nich: Tak mówi Pan, Bóg Izraelski: Przeklęty ten człowiek, któryby nie usłuchał słów przymierza tego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Którem przykazał ojcom waszym dnia, któregom ich wywiódł z ziemi Egipskiej, z pieca żelaznego, mówiąc: Słuchajcie głosu mojego, a czyńcie to wszystko, co wam rozkazuję, i będziecie ludem moim, a Ja będę Bogiem waszym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Abym spełnił przysięgę, którąm przysiągł ojcom waszym, że im dam ziemię opływającą mlekiem i miodem: jako się to dziś okazuje. Któremu odpowiedziawszy rzekłem: Amen, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'I rzekł Pan do mnie:Obwoływaj wszystkie te słowa w miastach Judzkich i po ulicach Jeruzalemskich, mówiąc: Słuchajcie słów przymierza tego, a czyńcie je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Bo oświadczając oświadczałem się przed ojcami waszymi ode dnia, któregom ich wywiódł z ziemi Egipskiej, aż do dnia tego; rano wstawając i oświadczając się, mawiałem: Słuchajcie głosu mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Ale nie usłuchali, ani nakłonili ucha swego; owszem każdy szedł za uporem serca swego złego. Przetożem przywiódł na nich wszystkie słowa przymierza tego, którem rozkazał, aby czynili; ale oni nie czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'I rzekł Pan do mnie: Znalazło się sprzysiężenie miedzy mężami Judzkimi, i między obywatelami Jeruzalemskimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Obrócili się do nieprawości ojców swoich pierwszych, którzy nie chcieli słuchać słów moich; także i ci chodzą za bogami cudzymi, służąc im; zgwałcili dom Izraelski i dom Judzki przymierze moje, którem był postanowił z ojcami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Dlatego tak mówi Pan: Oto Ja przywiodę na nich złe, z którego nie będą mogli wyjść; choćby wołali do mnie, nie wysłucham ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'I pójdą miasta Judzkie i obywatele Jeruzalemscy, a będą wołali do bogów, którym kadzą; ale ich żadnym sposobem nie wybawią czasu utrapienia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Aczkolwiek ile jest miast twoich, tyle bogów twoich, o Judo! a ile ulic Jeruzalemskich, tyleście nastawiali ołtarzów obrzydliwości, ołtarzów do kadzenia Baalowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Przetoż się ty nie módl za tym ludem, ani podnoś za nimi głosu i modlitwy; bo Ja ich nie wysłucham natenczas, gdy do mnie zawołają w utrapieniu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Cóż miłemu memu do domu mego? ponieważ bez wstydu pacha złości z wieloma, a ofiary święte odeszły od ciebie; i że się w złości swojej radujesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Oliwą zieloną, piękną, dla owocu ślicznego nazwał był Pan imię twoje; ale z szumem burzy wielkiej zapali ją ogniem z góry, gdy połamie gałęzie jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Bo Pan zastępów, który cię był wszczepił, wyrzekł złe przeciwko tobie dla złości domu Izraelskiego i domu Judzkiego, które czynili między sobą, aby mię draźnili, kadząc Baalowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Pan zaiste oznajmił mi, i dowiedziałem się; tedyś mi ukazał przedsięwzięcia ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Gdym był jako baranek i wół, którego wiodą na rzeź; bom nie wiedział, aby przeciwko mnie rady zmyślali mówiąc: Popsujemy drzewo z owocem jego, a wykorzeńmy go z ziemi żyjących, aby imię jego nie było więcej wspomniane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Ale, o Panie zastępów! który sprawiedliwie sądzisz, a doświadczasz nerek i serca, niech widzę pomstę twoję nad nimi; bom ci objawił sprawę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Dlatego tak mówi Pan o mężach z Anatot, którzy szukają duszy twojej, a mówią: Nie prorokuj w imieniu Pańskiem, abyś nie umarł od rąk naszych:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'A przetoż tak mówi Pan zastępów: Oto ja nawiedzę ich; młodzieńcy ich pomrą od miecza, synowie ich i córki ich pomrą głodem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'I nic nie zostanie z nich; bo przywiodę złe na mężów z Anatot roku nawiedzenia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Sprawiedliwym zostaniesz, Panie! jeźli się z tobą rozpierać będę; a wszakże o sądach twoich z tobą mówić będę. Czemuż się droga niezbożnych szczęści? Czemuż spokojnie żyją wszyscy, którzy bardzo wystąpili przeciwko tobie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Wszczepiłeś ich, i rozkorzenili się; rosną i owoc wydawają ci, którycheś ust bliskim, ale dalekim od nerek ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Ale ty, Panie, znasz mię, wypatrujesz mię, a doświadczyłeś serca mego, że z tobą jest; ale onych ciągniesz jako owce na rzeź i gotujesz ich na dzień zabicia, i mówisz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Dokądżeby ziemia płakać, a trawa na wszystkich polach schnąć miała? Dla złości mieszkających w niej giną wszystkie zwierzęta i ptastwo; bo mówią: Nie widzić Pan skończenia naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Ponieważ cię z pieszymi bieżącego do ustania przywodzą, jakożbyś miał zdążyć przy koniach? a ponieważ w ziemi pokoju, w którejś ufał, ustawasz, a cóż sprawisz przy tej nadętości Jordanu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Bo i bracia twoi i dom ojca twego przeniewierzyli się tobie, i ci także wołają za tobą pełnemi usty; ale nie wierzz im, choćby mówili z tobą po przyjacielsku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Opuściłem dom swój, odrzuciłem dziedzictwo moje; dałem to, co miłowała dusza moja, w ręce nieprzyjaciół jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Stało mi się dziedzictwo moje jako lew w lesie; wydaje przeciwko mnie głos swój, przetoż go nienawidzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Izali ptakiem drapieżnym jest mi dziedzictwo moje? Izali ptastwo będzie w około przeciwko niemu? Idźcież, zbierzcie się wszystkie zwierzęta polne, zejdźci się do żeru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Wiele pasterzy popsuje winnicę moję, podepczą dział mój; dział mój bardzo miły obrócą w pustynię srogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Obrócą go w pustynię; płakać będzie, spustoszony będąc odemnie; ta wszystka ziemia spustoszeje, bo niemasz, ktoby to składał do serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Na wszystkie miejsca wysokie w pustyniach przyjdą burzyciele, bo miecz Pański pożre wszystko od końca ziemi aż do końca ziemi; nie będzie miało pokoju żadne ciało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Nasieją pszenicy, ale ciernie żąć będą; frasować się będą, ale nic nie sprawią, i wstydzić się będą za urodzaje swoje dla gniewu popędliwości Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Tak mówi Pan o wszystkich złych sąsiadach moich, którzy się dotykają dziedzictwa, którem dał w dziedzictwo ludowi memu Izraelskiemu: Oto Ja wykorzenię ich z ziemi ich, kiedy dom Judzki wyplenię z pośrodku ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Wszakże gdy ich wyplenię, nawrócę się i zmiłuję się nad nimi, a przywiodę zasię każdego z nich do dziedzictwa jego, i każdego z nich do ziemi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'I stanie się, jeźli się ucząc nauczą dróg ludu mojego, a przysięgać będą w imieniu mojem, mówiąc: Jako żyje Pan, jako oni nauczali lud mój przysięgać przez Baala, tedy pobudowani będą w pośrodku ludu mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Ale jeźliby nie usłuchali, tedy wykorzenię ten naród, wyplenię i wytracę go, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Tak rzekł Pan do mnie: Idź, a kup sobie pas lniany, a opasz nim biodra swoje; ale do wody nie kładź go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Kupiłem tedy pas według rozkazania Pańskiego, i opasałem biodra moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Potem stało się słowo Pańskie do mnie powtóre, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Weźmij ten pas, któryś kupił, który jest na biodrach twoich, a wstawszy idź do Eufratesa, a skryj go tam w dziurę skalną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'I szedłem a skryłem go u Eufratesa, jako mi był Pan rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'A po wyjściu wielu dni rzekł Pan do mnie: Wstań, idź do Eufratesa, a weźmij stamtąd on pas, którym ci tam rozkazał skryć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Szedłem tedy do Eufratesa, a wykopawszy wziąłem on pas z miejsca onego, gdziem go był skrył, a oto skażony był on pas, tak, iż się niczemu nie godził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Tak mówi Pan: Tak skażę pychę Judzką i wielką pychę Jeruzalemską,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Ludu tego bardzo złego, który się zbrania słuchać słów moich, który chodzi w uporze serca swego, i chodzi za bogami obcymi, służąc im i kłaniając się im; i będzie podobien temu pasowi, który się niczemu nie godzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Bo jako pas przylega do biódr męża, takiem Ja był przypoił do siebie wszystek dom Izraelski, i wszystek dom Judzki, mówi Pan, aby byli ludem moim, a to ku sławie i ku chwale, i ku ozdobie; ale nie byli posłuszni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Przetoż rzecz im to słowo. Tak mówi Pan, Bóg Izraelski: Wszelkie naczynie winne bywa napełnione winem; a gdy rzeką: Wiemyć to dobrze, że wszelkie naczynie winne bywa napełnione winem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'Tedy im rzeczesz: Tak mówi Pan: Oto Ja napełnię wszystkich obywateli tej ziemi, i królów, którzy siedzą miasto Dawida na stolicy jego, i kapłanów i proroków, także i wszystkich obywateli Jeruzalemskich pijaństwem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'I rozrażę jednego o drugiego, jako ojców tak i synów, mówi Pan; nie przepuszczę, nie sfolguję, ani się zmiłuję, abym ich skazić nie miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Słuchajcież, a pojmujcie uszyma, nie podnoście się; boć Pan mówi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Dajcie Panu, Bogu swemu, chwałę, pierwej niżby ciemności przywiódł,a pierwej niżby się obraziły nogi wasze o góry ciemne; i czekalibyście światłości, ale Bóg obróciłby je w cień śmierci i przemieniłby je w zaćmienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'A jeźliż tego słuchać nie będziecie, w skrytościach płakać będzie dusza moja dla pychy waszej, a płacząc płakać będzie, i wyleje oko moje łzy, bo pojmana będzie trzoda Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Mów królowi i królowej: Upokorzcie się, usiądźcie na ziemi; bo spadła z głowy waszej korona chwały waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Miasta na południe zawarte będą, tak, że nie będzie, ktoby je otworzył; przeniesiony będzie wszystek Juda, przeniesiony będzie do szczętu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Podnieście oczy wasze, a obaczcie tych, którzy idą z północy. Gdzie jest ta trzoda, którejć się zwierzono? gdzie jest stado chwały twojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Cóż rzeczesz, gdy cię (nieprzyjaciel) nawiedzi? Boś ich ty nauczyła, aby byli nad tobą książętami przednimi; izali cię boleści nie ogarną, jako niewiastę rodzącą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Mówiszli w sercu swojem: Przeczżeby to przypaść miało na mię? Dla mnóstwa nieprawości twojej odkryte będą podołki twoje, gwałtem obnażone będą pięty twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Azaż może murzyn odmienić skórę swoję, albo lampart pstrociny swoje? także i wy, azaż będziecie mogli dobrze czynić, nauczywszy się źle czynić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Przetoż rozproszę ich jako źdźbło, które się rozlatuje od wiatru z pustyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Tenci będzie los twój, i dział odmierzony tobie odemnie, mówi Pan, przeto, żeś mię zapomniała, a ufałaś w kłamstwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'A tak i Ja odkryję podołek twój aż na twarz twoję, aby się okazała sromota twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Widziałem cudzołóstwa twoje i poryzanie twoje, sprosność wszeteczeństwa twego na pagórkach, i na polu; widziałem, mówię, obrzydliwości twoje. Biada tobie, Jeruzalemie! i pókiż się nie oczyścisz? kiedyż to wżdy będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Słowo Pańskie, które się stało do Jeremijasza o suszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Ziemia Judzka płakać będzie, a bramy jej zemdleją, żałobę nosić będą na ziemi, a narzekanie Jeruzalemskie wstąpi w górę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'I zacniejsi z nich rozsyłać będą najpodlejszych swoich po wodę; a przyszedłszy do cystern, i nie znalazłszy wody, nawrócą się z naczyniem swojem próżnem, zapłonąwszy i zawstydziwszy się; przetoż nakryją głowę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Dla ziemi upragnionej, przeto, że deszczu nie będzie na ziemi, i oracze wstydząc się nakryją głowy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Owszem i łani, co na polu porodziła, opuści; bo na polu trawy nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'A osły dzikie, stając na wysokich miejscach, chwytać będą wiatr jako smoki; ustaną oczy ich, bo nie będzie trawy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'O Panie! ponieważ nieprawości nasze świadczą przeciwko nam, zmiłuj się dla imienia twego; boć wielkie są odwrócenia nasze, tobieśmy zgrzeszyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'O nadzejo Izraelowa, wybawicielu jego czasu utrapienia! czemuż masz być jako przychodzień w tej ziemi, a jako podróżny wstępujący na nocleg?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Czemuż się pokazujesz jako mąż strudzony, albo jako mocarz, który nie może wybawić? Wszakeś ty jest w pośrodku nas, Panie! a imię twoje wzywane jest nad nami; nie opuszczajże nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Tak mówi Pan o tym ludu: Iż tak miłują tułanie, a nóg swych nie powściągają, przetoż się Panu nie podobają, i teraz wspomina nieprawości ich, a nawiedza grzechy ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Potem rzekł Pan do mnie: Nie módl się za tym ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Gdy pościć będą, Ja nie wysłucham wołania ich; a gdy ofiarować będą całopalenie, i ofiarę śniedną, Ja tego nie przyjmę; ale mieczem, i głodem, i morem wytracę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'I rzekłem: Ach, panujący Panie! oto im ci prorocy mówią: Nie oglądacie miecza, a głód nie przyjdzie na was, ale pokój pewny dam wam na tem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'I rzekł Pan do mnie: Fałsz prorokują ci prorocy w imieniu mojem; nie posłałem ich, anim im rozkazał, owszem, anim mówił do nich; widzenie kłamliwe, i wieszczbę, i marność, i kłamstwo serca swego oni wam prorokują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Przetoż tak mówi Pan o prorokach, którzy prorokują w imieniu mojem, chociażem Ja ich nie posłał, i którzy mówią: Miecza ani głodu nie będzie w tej ziemi; ci sami prorocy mieczem i głodem zginą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'A lud ten, któremu oni prorokują, rozrzucony będzie po ulicach Jeruzalemskich od głodu i od miecza, a nie będzie, ktoby ich pogrzebał, onych samych, żony ich, i synów ich, i córki ich; tak wyleję na nich złość ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Przetoż rzeczesz do nich to słowo: Oczy moje wylewają łzy w nocy i we dnie bez przestanku; bo skruszeniem wielkiem skruszona będzie panna, córka ludu mojego, i raną bardzo bolesną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Wyjdęli na pole, oto tam pomordowani mieczem; wyjdęli do miasta, oto i tam zmorzeni głodem; bo jako prorok tak i kapłan obchodząc kupczą ziemią, a ludzie tego nie baczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Izali do końca odrzucasz Judę? Izali Syon obrzydziła sobie dusza twoja? Przecz nas bijesz, tak abyśmy już nie byli uzdrowieni? Oczekujemyli na pokój, alić oto następuje nic dobrego; a jeźli na czas uleczenia, a oto zatrwożenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Uznajemy, Panie! niezbożność swoję, i nieprawość ojców naszych, iżeśmy zgrzeszyli przeciw tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Nie odrzucajże nas dla imienia twego, nie podawajże w lekkość stolicy chwały twojej; wspomnijże, nie targaj przymierza twego z nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Izali są między marnościami pogańskiemi, coby spuszczali deszcz? albo niebiosa mogąli same przez się dawać deszcze? Izaliś nie ty sam Pan, Bóg nasz? Przetoż oczekujemy na cię; bo to wszystko ty czynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Tedy rzekł Pan do mnie: Choćby stanął Mojżesz i Samuel przed obliczem mojem, nie miałbym serca do ludu tego; puść ich od oblicza mego, a niech precz idą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'A jeźliby rzekli: Dokądże pójdziemy? Tedy im rzeczesz: Tak mówi Pan: Kto oddany na śmierć, na śmierć pójdzie; a kto pod miecz, pod miecz; a kto na głód, na głód; a kto w niewolę, w niewolę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Bo ich tą czworaką rzeczą nawiedzę, mówi Pan: Mieczem na zamordowanie, i psami na rozszarpanie, i ptastwem niebieskiem, i zwierzętami ziemskiemi na pożarcie i na wygubienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'I podam ich na potłukanie się po wszystkich królestwach ziemi dla Manasesa, syna Ezechijasza, króla Judzkiego, za to, co uczynił w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Bo któżby się zmiłował nad tobą? Jeruzalemie! albo ktoby się użalił nad tobą? albo ktoby przyszedł, aby się pytał, jakoć się powodzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Tyś mię opuściło, mówi Pan, poszłoś nazad. Przetoż wyciągnę rękę moję na cię, abym cię wytracił; ustałem od żalu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Przetoż ich rozwieję wiejaczką po bramach tej ziemi, osierocę i wygubię ich; bo się od dróg swoich nie nawracali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Więcej się namnoży wdów jego, niż piasku morskiego; przywiodę na nich, na matki, na młodzieńców burzyciela i w południe; sprawię, że przypadną nagle na to miasto; i będą przestraszeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Zemdleje i ta, która rodziła po siedmiorgu, wypuści duszę swoję, zajdzie jej słońce jeszcze za dnia, zapłonie i wstydzić się będzie; a ostatek ich dam pod miecz przed obliczem nieprzyjaciół ich, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Biada mnie, matko moja! żeś mię urodziła męża swaru, i męża sporu po wszystkiej ziemi; nie dawałem im na lichwę, ani mnie oni na lichwę dawali, a wżdy mi każdy złorzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'I rzekł Pan: Izali tobie, który pozostaniesz, nie będzie dobrze? Izali się nie zastawię o cię nieprzyjacielowi czasu utrapienia i czasu ucisku?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Izali żelazo proste pokruszy żelazo północne i stal?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Majętność twoję, o Judo! i skarby twoje dam w rozszarpanie darmo po wszystkich granicach twoich, a to dla wszystkich grzechów twoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'A sprawię to, że pójdziesz z nieprzyjaciółmi twymi do ziemi, którejś nie znał; albowiem ogień rozniecony w zapalczywości mojej na was pałać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Ty mię znasz, Panie! wspomnijże na mię, a nawiedź mię, i pomścij się za mię nad tymi, co docierają na mię; odwłaczając zapalczywości twojej przeciwko nim, nie porywaj mię; wiedz, że podejmuję dla ciebie pohańbienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Gdy się znalazły mowy twoje, zjadłem ich, a było mi słowo twoje weselem i radością serca mego, ponieważ się nazywam od imienia twego, Panie, Boże zastępów!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Nie siadam w radzie naśmiewców, ani się z nimi raduję; ale dla surowości ręki twojej samotny siadam; bo zapalczywością napełniłeś mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Przeczże ma być żal mój wieczny? a rana moja śmiertelna, która się uleczyć nie da? Przeczże mi tak masz być jako omylny, jako wody niepewne?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Przetoż tak mówi Pan: Jeźli się nawrócisz, tedy cię nawrócę, abyś stał przed obliczem mojem; a jeźli odłączysz rzecz kosztowną od nikczemnej, będziesz jako usta moje; oni niech się obrócą do ciebie, ale się ty nie obracaj do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Bom cię postawił przeciw ludowi temu jako mur miedziany i obronny; i będą walczyć przeciwko tobie, ale cię nie przemogą; bom Ja z tobą, abym cię wybawiał i wyrywał, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Wyrwę cię zaiste z rąk ludzi złych, i odkupię cię z rąk okrutników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Nie pojmuj sobie żony, ani miej synów ani córek na tem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Albowiem tak mówi Pan o synach i o córkach spłodzonych na tem miejscu, i o matkach ich, które ich zrodziły, i o ojcach ich, którzy ich spłodzili w tej ziemi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Śmierciami ciężkiemi pomrą; nie będą ich płakać, ani ich pochowają, ale miasto gnoju na wierzchu ziemi będą; a mieczem i głodem wytraceni będą; i będą trupy ich pokarmem ptastwu niebieskiemu i i zwierzowi ziemskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Bo tak mówi Pan: Nie wchodź do domu żałoby, ani chodź na płacz, ani ich żałuj; bom odjął pokój mój od ludu tego, miłosierdzie i litość, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Gdy pomrą wielcy i mali w tej ziemi, nie będą pogrzebieni, ani ich płakać będą; i nie będą się rzezać, ani sobie łysiny czynić dla nich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Ani im dadzą jeść, aby ich w smutku cieszyli nad umarłym; ani im dadzą pić z kubka pocieszenia po ojcu ich i po matce ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Także do domu uczty nie wchodź, abyś zasiadał z nimi, i jadł, i pił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Albowiem tak mówi Pan zastępów, Bóg Izraelski: Oto Ja sprawię, iż ustanie na tem miejscu przed oczyma waszemi, i za dni waszych głos wesela, i głos radości, głos oblubieńca, i głos oblubienicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'A gdy opowiesz ludowi temu wszystkie te słowa, a rzekliby do ciebie: Przecz Pan wyrzekł przeciwko nam to wszystko wielkie złe? I cóż jest za nieprawość nasza, i co za grzech nasz, którymeśmy zgrzeszyli przeciwko Panu, Bogu naszemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'Tedy rzeczesz do nich: Przeto, iż mię opuścili ojcowie wasi, (mówi Pan) a chodzili za bogami cudzymi, i służyli im, i kłaniali się im, lecz mnie opuścili, i zakonu mego nie przestrzegali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'A wy dalekoście gorzej czynili, niż ojcowie wasi; albowiem oto każdy chodzi za uporem złego serca swego, nie słuchając mię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Dlatego wyrzucę was z tej ziemi do ziemi, którejście nie znali, wy i ojcowie wasi, a tam służyć będziecie bogom cudzym we dnie i w nocy, dokąd wam nie okażę miłosierdzia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Przetoż oto dni idą, mówi Pan, że nie rzeką więcej: Jako żyje Pan, który wywiódł synów Izraelskich z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Ale: Jako żyje Pan, który wywiódł synów Izraelskich z ziemi północnej, i ze wszystkich ziem, do których ich był wygnał, gdy ich zasię przywiodę do ziemi ich, którąm dał ojcom ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Oto Ja poślę do wielu rybitwów, (mówi Pan) aby ich łowili; potem poślę do wielu łowców, aby ich łapali na wszelkiej górze i na wszelkim pagórku, i w dziurach skalnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Oczy moje patrzą na wszystkie drogi ich; nie są utajone przed obliczem mojem, ani jest zakryta nieprawość ich przed oczyma mojemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'I oddam im pierwej w dwójnasób za nieprawości ich, i za grzechy ich, przeto, że ziemię moję splugawili trupami obrzydliwości swojej, i sprosnościami swemi napełnili dziedzictwo moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Panie, mocy moja i siło moja, i ucieczko moja w dzień utrapienia! do ciebie przyjdą narody od kończyn ziemi, i rzekną: Zaiste się fałszu trzymali ojcowie nasi, i marności, w których żadnego pożytku nie było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Izali sobie człowiek uczynić może bogów? ponieważ sami nie są bogami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Dlatego oto Ja sprawię, aby poznali tym razem; sprawię, mówię, aby poznali rękę moję i moc moję, i dowiedzieli się, że imię moje jest Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Grzech Judzki napisany jest piórem żelaznem, a ostrym dyjamentem wyryty jest na tablicy serca ich, i na rogach ołtarzów waszych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Gdy wspominają synowie ich na ołtarze ich, i na gaje ich pod drzewem zielonem, na pagórkach wysokich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'O góro, i pole moje! majętność twoję i wszystkie skarby twoje podam na rozszarpanie dla grzechu wyżyn twoich, które masz po wszystkich granicach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'A ty musisz zaniechać za przewinieniem twojem dziedzictwa twego, którem ci dał. I dam cię w niewolę nieprzyjaciołom twoim, i ziemi, której nie znasz; boście ogień rozniecili w popędliwości mojej, który aż na wieki gorzeć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Tak mówi Pan:Przeklęty mąż, który ufa w człowieku, i który pokłada ciało ramieniem swojem, a od Pana odstępuje serce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Albowiem stanie się jako wrzos na puszczy, który nie czuje, gdy co dobrego przychodzi, ale bywa na suchych miejscach na puszczy w ziemi słonej, i w której nikt nie mieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Błogosławiony mąż, który ufa w Panu, a Pan jest nadzieją jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Bo będzie jako drzewo wszczepione nad wodami, a nad strumieniem zapuszczające korzenie swoje, które nie czuje, gdy przychodzi gorącość, ale liść jego zostaje zielony, a roku suchego nie frasuje się, i nie przestaje przynosić owocu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Najzdradliwsze jest serce nadewszystko i najprzewrotniejsze, któż je pozna?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Ja Pan, który się badam serca, i doświadczam nerek, tak abym każdemu oddał według drogi jego, i według owocu spraw jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Jako kuropatwa zgromadza jajka, ale ich nie wylęga: tak, kto zbiera bogactwa, a niesprawiedliwie, w połowie dni swoich opuści je, a na ostatek będzie głupim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Ale miejsce świątnicy naszej, to jest stolica chwały Najwyższego, wiecznie trwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'O nadziejo Izraelska, Panie! wszyscy, którzy cię opuszczają, niech będą zawstydzeni; którzy odstępują odemnie, niech na ziemi zapisani będą; albowiem opuścili źródło wód żywych, Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Uzdrów mię, Panie! a będę uzdrowiony: zbaw mię, a będę zbawiony; albowiemeś ty chwała moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Oto oni do mnie mówią: Gdzież jest to słowo Pańskie? Niechże już przyjdzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Chociażem Ja tego nie zabiegał, abym był pasterzem twoim, anim dnia boleści pragnął, ty wiesz, cokolwiek wyszło z ust moich, przed obliczem twojem jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Nie bądźże mi na postrach; tyś nadzieja moja w dzień utrapienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Niech będą pochańbieni, którzy mię prześladują, a ja niech nie będę zawstydzony; niech się oni lękają, a ja niech się nie lękam; przywiedź na nich dzień utrapienia, a dwojakiem skruszeniem skrusz ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Tak Pan rzekł do mnie: Idź, a stań w bramie synów ludu tego, którą wchodzą królowie Judzcy, i którą wychodzą, i we wszystkich bramach Jeruzalemskich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'I rzecz do nich: Słuchajcie słowa Pańskiego, królowie Judzcy, i wszystek Judo, i wszyscy obywatele Jeruzalemscy, którzy chadzacie temi bramami!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Tak mówi Pan: Strzeżcie pilnie dusz waszych, a nie noście brzemion żadnych w dzień sabatu, ani ich wnoście bramami Jeruzalemskiemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Ani wynaszajcie brzemion z domów waszych w dzień sabatu, ani żadnej roboty odprawujcie, ale święćcie dzień sabatu, jakom rozkazał ojcom waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Wszakże nie usłuchali, ani nakłonili ucha swego, owszem, zatwardzili kark swój, nie słuchając ani przyjmując nauki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'A jeźli mię pilnie słuchać będziecie, mówi Pan, tak, żebyście nie wnosili brzemion bramami miasta tego w dzień sabatu, ale święcili dzień sabatu, nie odprawując weń żadnej roboty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Tedy wchodzić będą bramami miasta tego królowie i książęta siedzący na stolicy Dawidowej, jeżdżąc na wozach i na koniach, oni i książęta ich, mężowie Judzcy i obywatele Jeruzalemscy, i stać będzie to miasto aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'I zbieżą się z miast Judzkich i z okolicznych miejsc Jeruzalemskich, i z ziemi Benjaminowej, i z równin, i z tej góry, i od południa, przynosząc całopalenie, i ofiarę, i dar, i kadzidło, także i dziękczynienie niosąc do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Ale jeźli mię nie usłuchacie, abyście święcili dzień sabatu, a nie nosili brzemion, wchodząc bramami Jeruzalemskiemi w dzień sabatu, tedy rozniecę ogień w bramach jego, który pożre pałace Jeruzalemskie, a nie będzie ugaszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Słowo, które się stało do Jeremijasza od Pana mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Wstań, a wstąp do domu garncarzowego, a tam sprawię, że usłyszysz słowa moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'I wstąpiłem do domu garncarzowego, a oto on robił robotę na kręgu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'A gdy się zepsuło naczynie w ręce garncarzowej, które on czynił z gliny, tedy zaś uczynił z niej naczynie insze, jako się mu najlepiej zdało uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Izalibym tak nie mógł z wami postąpić, jako ten garncarz, o domie Izraelski? mówi Pan. Oto jako glina w ręce garncarzowej, takeście wy w ręce mojej, o domie Izraelski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Jeźlibym rzekł nagle przeciwko narodowi, i przeciwko królestwu, że je wykorzenię, i zepsuję, i wygubię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Wszakże jeźliby się odwrócił on naród od złości swojej, przeciw któremum mówił; i Jabym żałował tego złego, którem mu umyślił uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Zasię, jeźlibym rzekł nagle o narodzie i o królestwie, że je pobuduję i wszczepię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Wszakże jeźliby czynił, co złego jest przed oczyma memi, nie słuchając głosu mego: i Jabym żałował tego dobrodziejstwa, którem mu obiecał uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'A przetoż rzecz teraz do mężów Judzkich, i do obywateli Jeruzalemskich, mówiąc: Tak mówi Pan: Oto Ja gotuję na was złą rzecz, i myślę coś przeciwko wam. Nawróćcież się już każdy od złej drogi swojej, a poprawcie każdy dróg waszych, i spraw waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Ale oni rzekli: Nic z tego; bo za myślami naszemi pójdziemy, a każdy upór serca swojego złego czynić będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Przetoż tak mówi Pan: Pytajcie teraz między poganami, któż słyszał co takowego? Sprosność wielką popełniła panna Izraelska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Izali kto opuści pola moje dla skał i dla śniegu na Libanie? Izali kto opuści wody ciekące dla wody bardzo zimnej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Ale lud mój zapomniawszy na mię, marności kadzą i potykają się na drogach swych, na ścieszkach starodawnych, chodząc ścieszkami drogi nieutorowanej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Tak, abym podał ziemię ich na spustoszenie, na świstanie wieczne, aby każdy, ktoby szedł przez nią, zdumiał się, i kiwał głową swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Wiatrem wschodnim rozproszę ich przed nieprzyjacielem; tył a nie twarz ukażę im w dzień zatracenia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'I rzekli: Pójdźcie a wymyślmy co przeciwko Jeremijaszowi; bo nie zginie zakon od kapłana, ani rada od mądrego, ani słowo od proroka; pójdźcież, a ubijmy go językiem, a nie dbajmy na żadne słowa jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Pilnuj mię Panie! a słuchaj głosu tych, którzy się spierają ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Izali się ma oddawać złem za dobre, że ukopali dół duszy mojej? Wspomnij, żem stawał przed obliczem twojem, abym za nimi mówił ku ich dobremu, i odwrócił zapalczywość twoję od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Dlatego dopuść głód na synów ich, a spraw, że okrutnie będą pobici od miecza, że będą żony ich osierociałe i owdowiałe, a mężowie ich że będą haniebnie zamordowani, a dzieci ich pobite mieczem na wojnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Niech będzie słyszany krzyk z domów ich, gdy na nich nagle wojsko przywiedziesz; bo ukopali dół, aby mię ułapili a sidła ukryli na nogi moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Aleś ty, Panie! powiadomy wszystkiej rady ich przeciwko mnie na śmierć: nie bądź miłościw nieprawościom ich, a grzechu ich przed obliczem twojem nie zagładzaj; ale niech się potkną przed oblicznością twoją, czasu zapalczywośli twojej surowo się o bchodź z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Tak mówi Pan: Idź, a kup dzban gliniany od garncarza, a wziąwszy niektórych z starszych ludu i z starszych kapłanów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Wnijdź do doliny syna Hennomowego, która jest u wrót bramy wschodniej, a tam opowiadaj słowa, które do ciebie mówić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'A rzecz: Słuchajcie słowa Pańskiego, królowie Judzcy i obywatele Jeruzalemscy! Tak mówi pan zastępów, Bóg Izraelski: Oto Ja przywiodę złe na to miejsce, o którem ktokolwiek usłyszy, zabrzmi mu w uszach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Przeto, że mię opuścili, a splugawili to miejsce, kadząc na niem bogom cudzym, których nie znali oni i ojcowie ich, i królowie Judzcy, i napełnili to miejsce krwią niewinnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'I pobudowali wyżyny Baalowi, aby palili synów swych ogniem na całopalenie Baalowi, czegom nie rozkazał, anim oto mówił, ani to wstąpiło na serce moje:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Dlatego oto dni idą, mówi Pan, w których nie będzie nazywane więcej to miejsce Tofet, ani doliną syna Hennomowego, ale doliną mordu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Bo wniwecz obrócę radę Judzką i Jeruzalemską na tem miejscu, a sprawię, że oni upadną od miecza przed twarzą nieprzyjaciół swoich, i od ręki szukających duszy ich; i dam trupy ich na pokarm ptastwu niebieskiemu, i zwierzowi ziemskiemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Podam także to miasto na spustoszenie i na świstanie; każdy idący mimo nie zdumieje się, a świstać będzie nad wszystkiemi plagami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'I sprawię to, że będą jeść ciała synów swoich, i ciała córek swoich, a każdy z nich ciało bliźniego swego jeść będzie w oblężeniu i w uciśnieniu, którem ich ucisną nieprzyjaciele ich, i ci, którzy szukają duszy ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Potem stłucz ten dzban przed oczyma mężów, którzy pójdą z tobą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'A rzecz do nich: Tak mówi Pan zastępów: Tak stłukę ten lud, i to miasto, jako gdy kto tłucze naczynie garncarskie, które więcej naprawione być nie może: a w Tofet pogrzebywać będą, iż miejsca inszego nie będzie ku pogrzebowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Tak uczynię temu miejscu, mówi Pan, i obywatelom jego, i postąpię sobie z tem miastem, tak jako z Tofet.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Bo będą domy Jeruzalemskie i domy królów Judzkich, jako to miejsce Tofet, nieczyste ze wszystkiemi domami temi, na których dachach kadzili wszystkiemu wojsku niebieskiemu, i sprawowali ofiary mokre bogom cudzym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Tedy wróciwszy się Jeremijasz z Tofet, gdzie go był Pan posłał, aby tam prorokował, stanął w sieni domu Pańskiego, i rzekł do wszystkiego ludu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Tak mówi Pan zastępów, Bóg Izraelski: Oto Ja przywiodę na to miasto i na wszystkie miasto jego wszystko to złe, którem wyrzekł przeciw niemu; bo zatwardzili kark swój, aby nie słuchali słów moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Tedy usłyszawszy Fassur, syn Immerowy, kapłan, który był postanowiony przedniejszym w domu Pańskim, Jeremijasza prorokującego o tem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Ubił Fassur Jeremijasza proroka, i dał go do więzienia, które było najwyższe w bramie Benjaminowej, a ta była przy domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'A nazajutrz, gdy wywiódł Fassur Jeremijasza z więzienia, rzekł do niego Jeremijasz: Nie nazwał cię Pan Fassurem, ale Magor Missabib.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Bo tak mówi Pan: Oto Ja puszczę na cię strach, na cię i na wszystkich przyjaciół twoich, którzy upadną od miecza nieprzyjaciół swych, na co oczy twoje patrzyć będą; a wszystkiego Judę podam w ręce króla Babilońskiego, który ich zaprowadzi do Babil onu, i pozabija ich mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Dam też wszystkę majętność miasta tego, i wszstkę pracę jego, i wszystkie kosztowne rzeczy jego, i wszstkie skarby królów Judzkich dam w ręce nieprzyjaciół ich; i rozchwycą je, i zabiorą je, i zaprowadzą je do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Ale ty, Fassurze! i wszyscy, którzy mieszkają w domu twym, pójdziecie w pojmanie, i do Babilonu przyjdziesz, i tam umrzesz, i tam pogrzebiony będziesz; ty i wszyscy miłujący cię, którymeś kłamliwie prorokował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Namówiłeś mię, Panie! a dałem się namówić; mocniejszyś był niż ja, i przemogłeś; jestem na pośmiech każdy dzień, każdy się ze mnie naśmiewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Bo jakom począł mówić, wołam, dla gwałtu i spustoszenia krzyczę; bo mi słowo Pańskie jest ku pohańbieniu i na pośmiech każdy dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'I rzekłem: Nie będę go wspominał, ani będę więcej mówił w imieniu jego; ale słowo Boże jest w sercu mojem, jako ogień pałający, zamkniony w kościach moich, którym usiłował zatrzymać, alem nie mógł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Chociaż słyszę urąganie od wielu i od Magor Missabiba, mówiących: Powiedzcie co nań, a oznajmiemy to królowi. Wszyscy przyjaciele moi czyhają na upadek mój, mówiąc: Aza snać zwiedziony będzie, i przemożemy go, a pomścimy się nad nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Aleć Pan jest ze mną, jako mocarz straszny; przetoż ci, którzy mię prześladują, upadną, a nie przemogą; bardzo będą pohańbieni, że sobie niemądrze poczęli, hańba ich wieczna nie będzie zapamiętana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Przetoż, o Panie zastępów! który doświadczasz sprawiedliwego, który wypatrujesz nerki i serce, niech widzę pomstę twoję nad nimi; tobiem zaiste odkrył sprawę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Śpiewajcież Panu, chwalcie Pana, że wybawił duszę ubogiego z ręki złośników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Przeklęty dzień, w którym się urodził; dzień, którego mię porodziła matka moja, niech nie będzie błogosławiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Przeklęty mąż, który oznajmił ojcu memu, mówiąc: Urodziłoć się dziecię płci męskiej, aby go bardzo uweselił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Niechże będzie on mąż jako miasta, które Pan podwrócił, a nie żałował tego; niech słyszy krzyk z poranku, i narzekanie czasu południa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'O że mię nie zabił zaraz z żywota! Oby mi była matka moja grobem moim, a żywot jej wiecznie brzemiennym!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Przeczżem wyszedł z żywota, abym doznał pracy i smutku, a żeby dni moje w hańbie strawione były?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Słowo, które się stało do Jeremijasza od Pana, gdy do niego król Sedekijasz posłał Fassura, syna Malchyjaszowego, i Sofonijasza, syna Maasejaszowego, kapłana, aby rzekli:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Poradź się, proszę, o nas Pana; bo Nabuchodonozor, król Babiloński, walczy przeciwko nam: owa snać uczyni Pan z nami według wszystkich dziwnych spraw swoich, żeby odciągnął od nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'I rzekł Jeremijasz do nich: Tak powiedzcie Sedekijaszowi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Tak mówi Pan, Bóg Izraelski: Oto Ja odwrócę naczynia wojenne, które są w rękach waszych, i któremi wy walczycie przeciw królowi Babilońskiemu, i Chaldejczykom, którzy was oblegli około muru, i zgromadzę ich w pośrodek miasta tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'A Ja sam walczyć będę przeciwko wam ręką wyciągnioną i ramieniem możnem, a to w gniewie, i w popędliwości, i w zapalczywości wielkiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'I uderzę obywateli tego miasta, tak, że i ludzie i bydlęta morem wielkim pomrą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'A potem, tak mówi Pan, podam Sedekijasza, króla Judzkiego, i sługi jego, i lud, to jest tych, którzy pozostaną w tem mieście po morze, i po mieczu, i po głodzie, w rękę Nabuchodonozora, króla Babilońskiego i w rękę nieprzyjaciół ich, a tak w rękę szukających duszy ich, który ich pobije ostrzem miecza: nie przepuści im, ani im sfolguje, ani się zmiłuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Przetoż rzecz do ludu tego: Tak mówi Pan: Oto ja kładę przed wami drogę żywota i drogę śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Ktokolwiek zostanie w tem mieście, zginie od miecza, albo od głodu, albo od moru: ale kto wyjdzie i poda się Chaldejczykom, którzy was oblegli, pewnie żyw zostanie, i będzie mu dusza jego w korzyści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Bom obrócił oblicze moje przeciwko temu miastu ku złemu, a nie ku dobremu, mówi Pan. W rękę króla Babilońskiego podane będzie, i spali je ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Ale domowi króla Judzkiego rzecz: Słuchajcie słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'O domie Dawidowy! Tak mówi Pan: Odprawujcie sąd każdego poranku, a wyrywajcie uciśnionego z ręki gwałtownika, by snać nie wyszła jako ogień zapalczywość moja, a nie gorzała, tak, żeby nie był, ktoby ugasił dla złości spraw waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Otom Ja przeciwko tobie, która mieszkasz w tej dolinie, jako skała w tej równinie, mówi Pan, którzy mówicie: Któż przyciągnie na nas? a kto wnijdzie do przybytków naszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Bo was nawiedzę według owocu spraw waszych, mówi Pan; a rozniecę ogień w lesie twoim, który pożre wszystko około niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Tak mówi Pan: Zstąp do domu króla Judzkiego, a mów tam to słowo,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'I rzecz: Słuchaj słowa Pańskiego, królu Judzki! który siedzisz na stolicy Dawidowej, ty i słudzy twoi, i lud twój, którzy chodzicie bramami temi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Tak mówi Pan: Czyńcie sąd i sprawiedliwość, a wyzwalajcie uciśnionego z ręki gwałtownika, a przychdniowi, sierotce i wdowie nie czyńcie krzywdy, ani ich uciskajcie; ani krwi niewinnej nie wylewajcie na tem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Bo jeźli czyniąc uczynicie to słowo, tedy pewnie wnijdą bramami domu tego królowie, siedzący miasto Dawida na stolicy jego, jeżdżący na wozach i na koniach, sam król i słudzy jego, i lud jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Lecz jeżli nie posłuchacie tych słów, sam na się przysięgam, mówi Pan, że ten dom pustynią będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Bo tak mówi Pan o domie króla Judzkiego: Tyś mi był jako Galaad i wierzch Libański; ale cię pewnie obrócę w pustenię, i miasta, w których nie mieszkają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'I zgotuję na cię burzycieli, każdego z orężem jego, którzy wyrąbią wyborne cedry twoje, i wrzucą je na ogień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'A gdy pójdzie wiele narodów mimo to miasto, i rzecze jeden do drugiego: Dlaczegoż tak uczynił Pan temu miastu wielkimu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Tedy odpowiedzą: Przeto, iż opuścili przymierze Pana, Boga swego, a kłaniali się bogom cudzym, i służyli im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Nie płaczcież umarłego, ani go żałujcie, ale ustawicznie płaczcie nad tym, który odchodzi; bo się więcej nie wróci, aby oglądał ziemię, w której się narodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Bo tak mówi Pan o Sellumie, synu Jozyjasza, króla Judzkiego, który króluje miasto Jozyjasza, ojca swego: Gdy wyjdzie z miejsca tego, nie wróci się więcej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Ale tam na onem miejscu, gdzie go przeniosą, umrze, a tak tej ziemi więcej nie ogląda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Biada temu, kto buduje dom swój z niesprawiedliwością, a pałace swoje z krzywdą, który bliźniego swego darmo zniewala, a zapłaty mu jego nie daje!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Który mówi: Zbuduję sobie dom wielki, i pałace przestworne; i wycina sobie okna, a obija drzewem cedrowem, i maluje cynobrem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Izali będziesz królował, że mieszkasz między cedrami? Ojciec twój izali nie jadał i nie pijał? kiedy czynił sąd i sprawiedliwość, tedy się miał dobrze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Gdy sądził sprawę ubogiego, i nędznego, tedy się miał dobrze; izali to nie jest poznać mię? mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Ale oczy twoje i serce twoje nie szuka jedno łakomstwa swego, i abyś krew niewinną wylewał, a gwałt i krzywdę czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Przetoż tak mówi Pan o Joakimie, synu Jozyjasza, króla Judzkiego: Nie bądą go płakać ani mówić: Ach bracie mój! albo: Ach siostro! Nie będą go płakać ani mówić: Ach panie! albo: Ach! gdzież dostojność jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Pogrzebem oślim pogrzebiony bądzie; wywleczony i wyrzucony będzie za bramy Jeruzalemskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Wstąp na Liban, a wołaj, i na górze Basan wydaj głos twój; wołaj i u brodów, gdyż starci będą wszyscy miłośnicy twoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Mawiałem z tobą w największem szczęściu twojem; aleś ty rzekła: Nie posłucham. Tać jest droga twoja od dzieciństwa twego, nie usłuchałeś zaiste głosu mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Wszystkich pasterzy twoich wiatr spasie, a miłośnicy twoi w niewolę pójdą; tedy się zaiste zapałać i wstydzić będziesz dla wszelakiej złości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'O ty, która mieszkasz na Libanie, która sobie gniazdo czynisz na cedrach! jako wdzięczna będziesz, gdy cię ogarną boleści, a ucisk jako rodzącą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Jako żyję Ja, mówi Pan, iż choćby był Chonijasz, syn Joakima, króla Judzkiego, sygnetem na prawej ręce mojej, wszakże cię i stamtąd zerwę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'I podam cię w rękę tych, którzy szukaj duszy twojej,i w rękę tych, których się ty twarzy lękasz, to jest, w rękę Nabuchodonozora, króla Babilońskiego, i w rękę Chaldejczyków;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'A wyrzucę cię i matkę twoję, która cię urodziła, do ziemi cudzej, w którejście się nie rodzili, i tam pomrzecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Ale do ziemi, do której tęsknić będziecie, abyście się tam wrócili, nie wrócicie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Izali ten mąż Chonijasz będzie bałwanem nikczemnym, który podruzgotany bywa? Albo naczyniem, w którem niemasz żednej wdzięczności? Przeczżeby odrzuceni byli on i nasienie jego, a wyrzuceni do ziemi, której nie znają?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'O ziemio, ziemio, ziemio! słuchaj słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Tak mówi Pan: Zapiszcie to, że ten mąż będzie bez dzieci, a że mu się nie poszczęści za dni jego; owszem, nie poszczęści się i mężowi, któryby z nasienia jego siedział na stolicy Dawidowej, a panował jeszcze w Judzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Biada pasterzom gubiącym i rozpraszającym trzodę pastwiska mego! mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Przetoż tak mówi Pan, Bóg Izraelski, do pasterzy, którzy pasą lud mój: Wy rozpraszacie owce moje, owszem, rozganiacie je, a nie nawiedzacie ich; oto Ja nawiedzę was dla złości spraw waszych, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'A ostatek owiec moich Ja zgromadzę ze wszystkich ziem, do którychem je rozegnał, i przywrócę je do obór ich, gdzie się rozpłodzą i rozmnożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Nadto posanowię nad niemi pasterzy, którzyby je paśli, aby się więcej nie lękały, ani strachały, i żeby ich nie ubywało, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Oto idą dni, mówi Pan, których wzbudzę Dawidowi latorośl sprawiedliwą, i będzie królował król, a poszczęści mu się; sąd zaiste i sprawiedliwość będzie czynił na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'Za dni jego Juda zbawiony będzie, a Izrael bezpiecznie mieszkać będzie; a toć jest imię jego, którem go zwać będą: Pan sprawiedliwość nasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Przetoż oto przychodzą dni, mówi Pan, których nie rzeką więcej: Jako żyje Pan, który wywiódł synów Izraelskich z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Ale: Jako żyje Pan, który wywiódł, i który sprowadził nasienie domu Izraelskiego z ziemi północnej i ze wszystkich ziem, do którychem ich był rozegnał; gdyż będą mieszkać w ziemi swoiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Dla proroków skruszyło się serce moje we mnie, poruszyły się wszystkie kości moje, stałem się jako człowiek pijany, a jako mąż, po którym się rozeszło wino, dla Pana i dla słów świętobliwości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Bo ta ziemia pełna jest cudzołożników, a dla krzywoprzysięstwa płacze ta ziemia, pastwiska na puszczy poschły; zaiste zły jest bieg ich, a moc ich nieprawa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Bo i prorok i kapłan są obłudnikami, a domu moim znajduje się złość ich, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Przetoż im będzie droga ich jako ślizgawica w ciemności, na którą wepchnieni będą i upadną, gdy przywiodę na nich biedę czasu nawiedzenia ich, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Także przy prorokach Samaryjskich widziałem głupstwo, prorokowali przez Baale, i zwodzili lud mój Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Ale przy prorokach Jeruzalemskich widzę rzecz brzydką, że cudzołożąc i kłamliwie się obchodząc utwierdzają też ręce złośników, aby się nie nawracali żaden od złości swojej; stali się wszyscy przedemną jako Sodoma, a obywatele jego jako Gomora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Dlategoż tak mówi Pan zastępów o tych prorokach: Oto Ja nakarmię ich piołunem, a napoję ich wodą gorzką; bo od proroków Jeruzalemskich wyszło splugawienie na tę wszystkę ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Tak mówi Pan zastępów: Nie słuchajcie słów tych proroków, którzy wam prorokują, i zwodzą was, widzenie serca swego opowiadają, a nie z ust Pańskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Ustawicznie mówią tym, którzy mną gardzą: Pan mówił, pokój mieć będziecie; i każdemu chodzącemu według uporu serca swego, mówią: Nie przyjdzie na was nic złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Bo któż stanął w radzie Pańskiej, a widział i słyszał słowo jego? kto pilnował słowa jego, i słuchał go?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Oto wicher Pański z zapalczywością wyjdzie, a wicher trwały nad głową niepobożnych zostanie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Nie odwróci się gniew Pański, aż uczyni i wykona myśli serca swego; w ostateczne dni to doskonale zrozumiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Nie posyłałem tych proroków, a wszakże bieżeli; nie mówiłem do nich, a wszakże oni prorokowali,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Bo gdyby byli stali w radzie mojej, tedyby byli ogłaszali słowa moje ludowi memu, a byliby ich odwracali od drogi ich złej, i od złości spraw ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Izalim Ja tylko Bogiem z bliska? mówi Pan, a nie jestem Bogiem i z daleka?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Izali się kto skryje w skrytości, abym go Ja nie widział? mówi Pan. Izali Ja nieba i ziemi nie napełniam? mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Słyszęć Ja, co mówią prorocy, którzy prorokują, kłamstwo w imieniu mojem, mówiąc: Śniło mi się, śniło mi się!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Długoż tego będzie? Izali w sercu tych proroków, którzy prorokują, niemasz kłamstwa? owszem, są prorokami zdrady serca swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Którzy myślą, jakoby z pamięci wywieść ludowi mojemu imię moje snami swemi, które powiadają każdy bliźniemu swemu, jako zapomnieli ojcowie ich na imię moje dla Baala.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Prorok, który ma sen, niech powiada sen: ale który ma słowo moje, niech mówi słowo moje w prawdzie. Cóż plewie do pszenicy? mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Izali słowo moje nie jest jako ogień? mówi Pan, i jako młot kruszący skałę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Przetoż oto Ja powstaję przeciwko tym prorokom, mówi Pan, którzy kradną słowa moje, każdy przed bliźnim swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Oto Ja powstaję przeciwko tym prorokom, mówi Pan, którzy używają języka swego, aby mówili: Mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Oto Ja powstaję, mówi Pan, przeciwko tym, którzy prorokują sny kłamliwe, a opowiadając je zwodzą lud mój kłamstwami swemi i plotkami swemi, chociażem Ja ich nie posłał, anim im rozkazał; skąd zgoła nic nie pomagają ludowi twemu, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Przetoż gdyby się ciebie pytał lud ten, albo prorok, albo kapłan, mówiąc: Cóż jest za brzemię Pańskie? Tedy rzeczesz do nich które brzemię. To: Opuszczę was, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Bo proroka i kapłana tego, i lud ten, któryby rzekł: Toć jest brzemię Pańskie, pewnie nawiedzę męża tego i dom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Ale tak mówcie każdy do bliźniego swego, i każdy do brata swego: Cóż odpowiedział Pan? albo: Cóż mówił Pan?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'A brzmienia Pańskiego nie wspominajcie więcej; bo brzmieniem będzie każdemu słowo jego, gdyżeście wy wywrócili słowa Boga żywego, Pana zastępów, Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Tak tedy rzeczesz do proroka: Cóż ci odpowiedział Pan? albo: Co mówił Pan?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Ale ponieważ mówicie: Brzemię Pańskie, tedy tak mówi Pan: Ponieważ mówicie to słowo: Brzemię Pańskie, chociażem do was posyłał, mówiąc: Nie mówcie: Brzemię Pańskie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Przetoż oto i Ja was zapomnę do końca, i odrzucę was i to miasto, którem wam dał i ojcom waszym, od oblicza mego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'I podam was na urąganie wieczne, i na hańbę wieczną, która nigdy nie przyjdzie w zapamiętanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Ukazał mi Pan, a oto dwa kosze fig postawione były przed kościołem Pańskim, gdy był w niewolę zabrał Nabuchodonozor, król Babiloński, Jechonijasza, syna Joakima, króla Judzkiego, i książąt Judzkich, i cieśli, i kowali z Jeruzalemu, a zawiódł ich do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Kosz jeden miał figi bardzo dobre, jako bywają figi dojrzałe; a kosz drugi miał figi bardzo złe, których jeść nie można, przeto, iż były złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'I rzekł Pan do mnie: Cóż widzisz? Jeremijaszu! I rzekłem: Figi. Figi dobre są bardzo dobre, a złe są bardzo złe, których jeść nie mogą, przeto, iż są złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Tak mówi Pan, Bóg Izraelski: Jako te figi są dobre, tak mi przyjemni będą w niewolę zaprowadzeni z Judy, którychem wysłał z miejsca tego do ziemi Chaldejskiej ku dobremu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'I obrócę oko moje na nich ku dobremu, i przywiodę ich do tej ziemi, gdzie ich pobuduję, a nie skażę, i wszczepię ich, a nie wykorzenię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Albowiem dam im serce, aby mię poznali, żem Ja Pan; i będą mi ludem moim, a Ja będę Bogiem ich, gdy się nawrócą do mnie całem sercem swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'A jako figi złe, których nie jadają, przeto, że są złe, tak zarzucę (toć zaiste mówi Pan,) Sedekijasza, króla Judzkiego, i książąt jego, i ostatki z Jeruzalemu, które pozostały w tej ziemi, i tych, którzy mieszkają w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Podam ich, mówię, na utrapienie, i na ucisk po wszystkich królestwach ziemi, na pohańbienie i na przypowieść, na przysłowie i na przeklęstwo po wszystkich miejscach, do których ich zapędzę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'I będę posyłał na nich miecz, głód i mór, aż do końca wytraceni będą z ziemi, którąm był dał im, i ojcom ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Słowo, które się stało do Jeremijasza przeciwko wszystkiemu ludowi Judzkiemu roku czwartego Joakima, syna Jozyjaszowego, króla Judzkiego, (który jest rok pierwszy Nabuchodonozora, króla Babilońskiego;)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'Które mówił Jeremijasz prorok do wszystkiego ludu Judzkiego, i do wszystkich obywateli Jeruzalemskich mówiąc;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Od trzynastego roku Jozyjasza, syna Amonowego, króla Judzkiego, aż do dnia tego, już to przez dwadzieścia i trzy lata bywało słowo Pańskie do mnie, którem do was mawiał, rano wstawając i opowiadając; aleście nie słuchali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Posyłał też Pan do was wszystkich sług swoich proroków, rano wstawając, i posyłając, (którycheście nie usłuchali, aniście nakłonili ucha swego, abyście słyszeli;)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Którzy mówili: Nawróćcie się teraz każdy od złej drogi swojej, i od złości spraw waszych; a tak będziecie mieszkali w tej ziemi, którą wam dał Pan, i ojcom waszym od wieku aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'A nie chodźcie za bogami cudzymi, abyście im służyli, i kłaniali się im, ani mię gniewajcie sprawą rąk waszych, a Ja wam źle nie uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Aleście mię nie usłuchali, mówi Pan, abyście mię pobudzali do gniewu sprawą rąk swioch na swe złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Przetoż tak mówi Pan zastępów: Dlatego, iżeście nie usłuchali słów moich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Oto Ja poślę i pobiorę wszystkie narody północne, mówi Pan, i do Nabuchodonozora króla Babilońskiego, sługi mego, i przywiodę je na tę ziemię, i na obywateli jej, i na te wszystkie narody okoliczne, które do szczętu wygładzę, i położę je na podziw, i na poświstanie, i na spustoszenie wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'I sprawię to, aby im zginął głos wesela, i głos radości, głos oblubieńca, i głos oblubienicy, głos żarn, i światłość pochodni,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'I będzie ta wszystka ziemia spustoszeniem, i zdumieniem, a służyć będą te narody królowi Babilońskiemu siedmdziesiąt lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Ale potem, gdy się wypełni siedmdzisiśąt lat, nawiedzę na królu Babilońskim i na tym narodzie, mówi Pan, nieprawość ich, i na ziemi Chaldejskiej, tak, że ją obrócę w pustynie wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'A przywiodę na tę ziemię wszystkie słowa moje, którem mówił o niej, mianowicie to wszystko, co napisano w tych księgach, cokolwiek prorokował Jaremijasz o wszystkich narodach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Gdyż w niewolę podbici będą od narodów, także jako i oni możnych, i od królów wielkich, tedy im oddam według spraw ich i według uczynków rąk ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Bo tak rzekł Pan, Bóg Izraelski, do mnie: Weźmij kubek wina tej popędliwości z ręki mojej, a napawaj nim wszystkie narody, do których Ja ciebie poślę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Aby pili i potaczli się, owszem, aby szaleli od ostrza miecza, który Ja poślę między nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Wziąłem tedy kubek z ręki Pańskiej, i napoiłem wszystkie one narody, do których mię Pan posłał:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jeruzalem, i miasta ziemi Judzkiej, i królów jej, i książąt jej, abym ich podał na spustoszenie, na zdumienie, na poświstanie, i na przeklęstwo, jako się to dziś okazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Faraona też, króla Egipskiego, i sług jego, i książąt jego, i wszystek lud jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'I to wszystko pospólstwo, także wszystkich króli ziemi Uz, i wszystkich króli ziemi Filistyńskiej, i Aszkalon, i Gazę, i Akkaron, i ostatek Azotu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edomczyków, i Moabczyków, i synów Ammonowych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'I wszystkich królów Tyrskich, i wszystkich królów Sydońskich, i królów tej krainy, która jest przy morzu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedana i Temę, i Buzę, i wszystkich, którzy mieszkają w ostatnich kątach:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'I wszystkich królów Arabskich, i wszystkich królów tego pospólstwa, które mieszka na puszczy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'Także wszystkich królów Zymry i wszystkich królów Elam, i wszystkich królów Medskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'Owszem, wszystkich królów północnych, bliskich i dalekich, jednego jako drugiego; wszystkie też królestwa ziemi, którekolwiek są na obliczu ziemi; a król Sesak będzie pił po nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'I rzecz do nich: Tak mówi Pan zastępów, Bóg Izraelski: Pijcie, a popijcie się, owszem zwracajcie, i padajcie tak, abyście nie powstali dla miecza, który Ja poślę między was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'A jeźliby nie chcieli wziąć kubka z ręki twojej, aby pili, tedy rzeczesz do nich: Tak mówi Pan zastępów: Koniecznie pić musicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Bo ponieważ na to miasto, które nazwane jest od imienia mego, Ja zaczynam przywodzić złe rzecz, a wybyście bez karania być mieli? Nie będziecie bez karania; bom Ja miecz przyzwał na wszystkich obywateli tej ziemi, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Przetoż ty prorokuj przeciwko nim te wszyskie słowa, a mów do nich: Pan z wysoka zaryczy, a mieszkania świętobliwości swojej wyda głos swój, rycząc zaryczy z mieszkania swego; krzyk pobudzających się jako tłoczących prasę, rozlegać się będzie prze ciwko wszystkim obywatelom tej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'I przejdzie huk aż do kończyn ziemi; bo się Pan rozpiera z tymi narodami, w sąd sam wchodzi ze wszelkiem ciałem, niezbożnych poda pod miecz, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Tak mówi Pan zastępów: Oto udręczenie pójdzie z narodu do narodu, a wicher wielki powstanie od kończyn ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'I będą pobici od Pana czasu onego od końca ziemi aż do końca ziemi; nie będą ich płakać, ani zbierać, ani chować; będą jako gnój na polu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Narzekajcie pasterze i wołajcie, a walajcie się w popiele, wy najzacniejsi tej trzody! bo się wypełniły dni wasze, zabicia i rozproszenia waszego, i upadniecie jako naczynie drogie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'I zginie ucieczka pasterzom, a ujście najzacniejszym tej trzody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Głos wołania pasterzy, i narzekanie najzacniejszych tej trzody słychać będzie; bo Pan spustoszy pastwiska ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'I zagubione będą spokojne pastwiska dla zapalczywości gniewu Pańskiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Który opuści jako lew jaskinię swoję; bo ziemia ich przyjdzie na spustoszenie dla zapalczywości pustoszyciela, i dla popędliwości gniewu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Na początku królowania Joakima, syna Jozyjasza, króla Judzkiego, stało się to słowo od Pana, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Tak mówi Pan: Stań w sieni domu Pańskiego, a mów do wszystkich miast Judzkich, do przychodzących kłaniać się w domu Pańskim, wszystkie słowa, któreć rozkazuję mówić do nich; nie ujmuj i słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Owa snać usłuchają, a nawrócą się każdy od złej drogi swej, abym pożałował złego, którem im umyślił uczynić dla złości spraw ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'I rzecz do nich: Tak mówi Pan: Jeźli mię nie usłuchacie, żebyście chodzili w zakonie moim, którym wam przedłożył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'Słuchając słów sług moich proroków, których Ja posyłam do was, jakoście, gdym ich rano wstawając posyłał, nie usłuchali:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'Tedy uczynię temu domowi jako Sylo, a to miasto dam na przeklęstwo wszystkim narodom ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'A kapłani i prorocy i wszystek lud słyszeli Jeremijasza mówiącego te słowa w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'A skoro przestał Jeremijasz mówić wszystko, co mu był rozkazał Pan mówić wszystkiemu ludowi, pojmali go oni kapłani i prorocy, i wszystek on lud mówiąc: Śmiercią umrzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Czemuś prorokował w imię Pańskie, mówiąc: Stanie się temu domowi jako Sylo, a to miasto tak spustoszeje, że w niem nie będzie obywatela? I zgromadzał się wszystek lud przeciwko Jeremijaszowi do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Tedy usłyszawszy te rzeczy książęta Judzcy, przyszli z domu królewskiego do domu Pańskiego, i usiedli w wejściu nowej bramy Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'I rzekli kapłani i prorocy do onych książąt, i do wszystkiego ludu, mówiąc: Ten mąż godzien jest śmierci; bo prorokował przeciwko miastu temu, jakoście to słyszeli w uszy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Tedy rzekł Jeremijasz do wszystkich książąt, i do wszystkiego ludu, mówiąc: Pan mię posłał, abym prorokował o tym domu i o tem mieście wszystko to, coście słyszeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Przetoż teraz poprawcie drogi swoje i sprawy swe, a usłuchajcie głosu Pana, Boga swego, a pożałuje Pan tego złego, które wyrzekł przeciwko wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'A ja otom jest w rękach waszych; czyńcie zemną, co dobrego i sprawiedliwego jest w oczach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'A wszakże zapewne wiedzcie, jeźliż mię zabijecie, że krew niewinną zwalicie na się i na to miasto, i na obywateli jego; bo mię zaprawdę Pan do was posłał, abym mówił te wszystkie słowa w uszy wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'I rzekli książęta i wszystek lud do kapłanów i do onych proroków: Niema być żadnym sposobem ten mąż osądzony na śmierć, ponieważ w imieniu Pana, Boga naszego, mówił do nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Tedy powstali niektórzy z starszych onej ziemi, i uczynili rzecz do wszystkiego zgromadzenia ludu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Micheasz Morastytczyk prorokował za dni Ezechijasza, króla Judzkiego, i rzekł do wszystkiego ludu Judzkiego, mówiąc: Tak mówi Pan zastępów: Syon jako pole poorany będzie, a Jeruzalem jako gromady rumu będzie, a góra domu tego jako wysokie lasy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Izali go zaraz dlatego zabili Ezechijasz, król Judzki, i wszystek Juda? izali się nie ulękł Pana, a nie modlił się Panu? I żałował Pan onego złego, które był wyrzekł przeciwko nim: przetoż my złą rzecz czynimy przeciwko duszom naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Także też był mąż prorokujący w imieniu Pańskiem, Uryjasz, syn Semejaszowy, z Karyjatyjarym, który prorokował o tem mieście i o tej ziemi według wszystkich słów Jeremijaszowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'A gdy usłyszał król Joakim, i wszystko rycerstwo jego, i wszyscy książęta słowa jego, zaraz go chciał król zabić, co usłyszawszy Uryjasz uląkł się, a uciekłszy przyszedł do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Ale król Joakim posłał niektórych do Egiptu, Elnatana, syna Achborowego, i innych z nim do Egiptu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Którzy wywiódłszy Uryjasza z Egiptu, przywiedli go do króla Joakima; i zabił go mieczem, i wrzucił trupa jego do grobów ludu pospolitego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Wszakże ręka Achikama, syna Safanowego, była przy Jeremijaszu, aby nie był wydan w ręce ludu, i nie był zabity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Na początku królowania Joakima, syna Jozyjasza, króla Judzkiego, stało się to słowo do Jeremijasza od Pana, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Tak mówi Pan do mnie: Uczyń sobie okowy i jarzma, a włóż je na szyję swoję:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Potem je poślij do króla Edomskiego, i do króla Moabskiego, i do króla synów Ammonowych, i do króla Tyrskiego, i do króla Sydońskiego, przez rękę posłów, którzy przyjdą do Jeruzalemu do Sedekijasza, króla Judzkiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'A rozkaż im, aby panom swym powiedzieli: Tak mówi Pan zastępów, Bóg Izraelski, tak powiecie panom waszym:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Jam uczynił ziemię, także człowieka i bydlęta, którekolwiek są na obliczu ziemi, mocą swoją wielką i ramieniem swojem wyciągnionem: przeto ja daję temu, który się podoba oczom moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'A teraz dałem te wszystkie ziemie w rękę Nabuchodonozora, króla Babilońskiego, sługi mego; nadto i zwierzęta polne dałem mu, aby mu służyły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Przetoż będą mu służyły te wszystkie narody, i synowi jego i synowi syna jego, dokądby nie przyszedł czas ziemi jego i jego samego, gdy go też zaś sobie w niewolę podbiją narody zacne, i królowie wielcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'A ten naród i to królestwo, któreby mu nie służyło, to jest Nabuchodonozorowi, królowi Babilońskiemu, i któryby nie poddał szyi swojej pod jarzmo króla Babilońskiego, mieczem, i głodem, i morem nawiedzę ten naród, mówi Pan, dokądbym ich do końca nie wytracił ręką jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Przetoż wy nie słuchajcie proroków swoich, i wieszczków swoich, ani snów swoich, ani wróżków swoich, i czarowników swoich, którzy wam powiadają, mówiąc: Nie będziecie służyli królowi Babilońskiemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Bo wam oni kłamstwo prorokują, abym was oddalił od ziemi waszej, a wygnał was, abyście poginęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'A naród, który poddał szyję swą pod jarzmo króla Babilońskiego, a któryby mu służył, ten zaiste zostawię w ziemi jego, (mówi Pan,) aby ją sprawował, i mieszkał w niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'A do Sedekijasza, króla Judzkiego, rzekłem według tych wszystkich słów, mówiąc: Poddajcie szyje wasze pod jarzmo króla Babilońskiego, a służcie mu i ludowi jego, a żyć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Przeczże macie zginąć, ty i lud twój, od miecza, od głodu i od powietrza, jako mówił Pan o narodzie, któryby nie służył królowi Babilońskiemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Nie słuchajcież tedy słów tych proroków, którzy mówiąc do was powiadają: Nie będziecie służyli królowi Babilońskiemu; albowiem wam oni kłamstwo prorokują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Nie posłałem ich zaiste, mówi Pan; wszakże oni prorokują w imię moje kłamliwie, abym was zapędził, gdziebyście zginęli, wy i ci prorocy, którzy wam prorokują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Do kapłanów też, i do tego wszystkiego ludu rzekłem, mówiąc: Tak mówi Pan: Nie słuchajcie słów proroków swoich, którzy wam prorokują, mówiąc: Oto naczynia domu Pańskiego teraz w rychle przywrócone będą z Babilonu; bo wam oni kłamstwo prorokują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Nie słuchajcież ich; służcie królowi Babilońskiemu, a żyć będziecie; przeczżeby to miasto miało być pustynią?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'A jeźliż oni są prorokami, i jeźli jest słowo Pańskie w nich, proszę, niech zabieżą Panu zastępów, aby te naczynia, które pozostały w domu Pańskim; i w domu króla Judzkiego, i w Jeruzalemie, nie dostały się do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Bo tak mówi Pan zastępów o tych słupach, i o tem morzu, i o tych podstawkach, i o ostatku naczynia, które pozostało w tem mieście;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'Którego nie zabrał Nabuchodonozor, król Babiloński, gdy w niewolę prowadził Jechonijasza, syna Joakimowego, króla Judzkiego, z Jeruzalemu do Babilonu, i wszystkich przedniejszych, z Judy i z Jeruzalemu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Tak zaiste mówi Pan zastępów, Bóg Izraelski, o tych naczyniach, które pozostały w domu Pańskim, i w domu króla Judzkiego, i w Jeruzalemie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Do Babilonu zawiezione będą, a będą tam aż do dnia, którego je nawiedzę, mówi Pan, i każę je przywieźć i przywrócić na to miejsce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'I stało się roku onego, na początku królowania Sedekijasza, króla Judzkiego, roku czwartego, miesiąca piątego: Hananijasz, syn Asurowy, prorok, który był z Gabaonu, rzekł do mnie w domu Pańskim przed kapłanami i przed wszystkim ludem, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Tak mówi Pan zastępów, Bóg Izraelski: Połamałem jarzmo króla Babilońskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Po dwóch latach przywrócę zasię na to miejsce wszystkie naczynia domu Pańskiego, które pobrał Nabuchodonozor, król Babiloński, z tego miejsca, a zawiózł je do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Także Jechonijasza, syna Joakimowego, króla Judzkiego, i wszystkich, którzy są w niewolę zaprowadzeni z Judy, którzy się dostali do Babilonu, Ja zasię przywiodę na to miejsce, mówi Pan; bo skruszę jarzmo króla Babilońskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Tedy rzekł Jeremijasz prorok do Hananijasza proroka przed oczyma kapłanów, i przed oczyma wszystkiego ludu, którzy stali w domu Pańskim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Rzekł, mówię, Jeremijasz prorok: Amen, niech tak uczyni Pan; niech utwierdzi Pan słowa twoje, któreś prorokował o przywróceniu z Babilonu na to miejsce naczynia domu Pańskiego, i wszystkich, którzy są zaprowadzeni w niewolę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Wszakże posłuchaj teraz słowa tego, które ja mówię w uszy twoje, i w uszy tego wszystkiego ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Prorocy, którzy byli przedemną i przed tobą z dawna, ci prorokowali przeciwko ziemiom zacnym, i przeciwko królestwom wielkim o wojnie, i o uciśnieniu, i o morze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Ten prorok, który prorokuje o pokoju, ten prorok, mówię, wtenczas poznany bywa, że go Pan prawdziwie posłał, gdy się iści słowo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Tedy zdjął Hananijasz prorok jarzmo z szyi Jeremijasza proroka, i połamał je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'I rzekł Hananijasz przed oczyma wszystkiego ludu, mówiąc: Tak mówi Pan: Tak połamię jarzmo Nabuchodonozora, króla Babilońskiego, po dwóch latach z szyi wszystkich narodów. I poszedł Jeremijasz prorok w drogę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Ale stało się słowo Pańskie do Jeremijasza, gdy połamał Hananijasz prorok ono jarzmo z szyi Jeremijasza proroka, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Idź; a rzecz do Hananijasza, mówiąc: Tak mówi Pan: Połamałeś jarzma drewniane; przetoż uczyń na to miejsce jarzmo żelazne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Bo tak mówi Pan zastępów, Bóg Izraelski: Jarzmo żelazne włożę na szyję tych wszystkich narodów, aby służyły Nabuchodonozorowi, królowi Babilońskiemu, i będą mu służyły; także i zwierzęta polne podałem mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Zatem rzekł Jeremijasz prorok do Hananijasza proroka: Słuchaj teraz Hananijaszu! Nie posłał cię Pan, a tyś kazał nadzieję mieć temu ludowi w kłamstwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Przetoż tak mówi Pan: Oto Ja ciebie uprzątnę z tej ziemi, tego roku umrzesz; boś radził, aby odstąpił lud od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'I umarł Hananijasz prorok onegoż roku, miesiąca siódmego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'A teć są słowa listu, który posłał Jeremijasz prorok z Jeruzalemu do ostatków starszych, którzy byli w pojmaniu, i do kapłanów, i do proroków, i do wszystkiego ludu, których był przeniósł Nabuchodonozor z Jeruzalemu do Babilonu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Gdy wyszedł Jechonijasz król i królowa, i komornicy, książęta Judzcy, i Jeruzalemscy, także cieśle i kowale z Jeruzalemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Przez Elhasa, syna Safanowego, i Giemaryjasza, syna Helkijaszowego, (których był posłał Sedekijasz, król Judzki, do Nabuchodonozora, króla Babilońskiego, do Babilonu) mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Tak mówi Pan zastępów, Bóg Izraelski, do wszystkich pojmanych, którychem przeniósł z Jeruzalemu do Babilonu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Budujcie domy, i osadzajcie się; szczepcie też sady, a jedzcie owoc ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Pojmujcie żony, a płodźcie synów i córki, i dawajcie synom waszym żony, a córki wasze wydawajcie za mąż, aby rodziły synów i córki; rozmnażajcie się tam, i niech was nie ubywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Szukajcie też pokoju miastu temu, do któregom was przeniósł, a módlcie się za nie Panu; bo w pokoju jego będziecie mieli pokój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Tak zaiste mówi Pan zastępów, Bóg Izraelski: Niech was nie zwodzą prorocy wasi, którzy są między wami, i wieszczkowie wasi, a nie sprawujcie się snami waszemi, które się wam śnią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Bo wam oni kłamliwie prorokują w imieniu mojem; nie posłałem ich, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Tak zaiste mówi Pan: Jako się jedno wypełnią siedmdziesiąt lat Babilonowi, nawiedzę was, a potwierdzę wam słowa swego wybornego o przywróceniu was na to miejsce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Bo Ja najlepiej wiem myśli, które myślę o was, mówi Pan: myśli o pokoju, a nie o utrapieniu, abym uczynił koniec pożądany biedom waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Gdy mię wzywać będziecie, a pójdziecie, i modlić mi się będziecie, tedy was wysłucham;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'A szukając mię, znajdziecie; gdy mię szukać będziecie ze wszystkiego serca swego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Dam się wam zaiste znaleść, mówi Pan: a przywrócę więźniów waszych, i zgromadzę was ze wszystkich narodów, i ze wszystkich miejsc, gdziemkolwiek was zagnał, mówi Pan; i przyprowadzę was na to miejsce, skądem was wyprowadził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Gdy rzeczecie: Wzbudzał nam Pan proroków prorokujących o zaprowadzeniu do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Bo tak mówi Pan o królu, który siedzi na stolicy Dawidowej, i o wszystkim ludu, który mieszka w tem mieście, braciach waszych, którzy nie wyszli z wami w tę niewolę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'Tak mówi Pan zastępów: Oto Ja poślę na nich miecz, głód, i mór, a uczynię ich jako złe figi, których nie jadają, przeto, że są złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Albowiem prześladować ich będę mieczem, głodem i morem, i dam ich na potłukanie po wszystkich królestwach ziemi, na przeklęstwo, i na zdumienie, owszem, na poświstanie, i na urąganie między wszystkimi narodami, tam, gdzie ich zapędzę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Przeto, iż nie słuchają słów moich, mówi Pan, gdy posyłam do nich sług swoich, proroków, rano wstawając i posyłając; a nie słuchaliście, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Przetoż słuchajcie słowa Pańskiego wy wszyscy pojmani, którychem wysłał z Jeruzalemu do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Tak mówi Pan zastępów, Bóg Izraelski, o Achabie, synu Kolajaszowym, i o Sedekijaszu, synu Maazejaszowym, którzy wam prorokują w imieniu mojem kłamstwo: Oto Ja podam ich w rękę Nabuchodonozora, króla Babilońskiego, aby ich pobił przed oczyma wasze mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'I będzie wzięte z nich przeklinanie między wszystkich pojmanych z Judy, którzy są w Babilonie, aby mówili: Niech cię uczyni Pan jako Sedekijasza, i jako Achaba, których upiekł król Babiloński na ogniu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Przeto, że popełniali złość w Izraelu, cudzołożąc z żonami bliźnich swoich, a kłamliwie mówiąc słowo w imieniu mojem, czegom im nie przykazał; a Ja o tem wiem, i jestem tego świadkiem, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'A do Semejasza Nechalamity rzecz, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Tak powiada Pan zastępów, Bóg Izraelski, mówiąc: Przeto żeś ty posłał imieniem swojem listy do wszystkiego ludu, który jest w Jeruzalemie, i do Sofonijasza, syna Maazejaszowego, kapłana, i do wszystkich kapłanów, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Pan cię dał za kapłana miasto Jojady kapłana, abyście mieli dozór w domu Pańskim na każdego męża w rozum zaszłego a prorokującego, abyś dał takowego do więzienia i do kłody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Przeczżeś tedy teraz nie zgromił Jeremijasza Anatotczyka, który wam prorokuje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'Bo posłał do nas do Babilonu, mówiąc: Jeszczeć długo czekać; budujcie domy, a osadzajcie się, szczepcie sady, a jedzcie owoce ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Bo Sofonijasz kapłan czytał ten list przed Jeremijaszem prorokiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'I stało się słowo Pańsie do Jeremijasza mówiąc: Poślij do wszystkich zabranych w niewolę, mówiąc: Tak mówi Pan o Semejaszu Nechalamitczyku: Przeto, że wam prorokował Semejasz, chociażem go Ja nie posłał, a przywodzi was do tego, abyście mieli nad zieję w kłamstwie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Przetoż tak mówi Pan: Oto Ja nawiedzę Semejasza Nechalamitczyka i nasienie jego; nie będzie miał nikogo, ktoby mieszkał w pośrodku ludu tego, ani ogląda tego dobra, które Ja uczynię ludowi swemu, mówi Pan; bo radził, aby odstąpił lud od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Słowo, które się stało do Jeremijasza od Pana, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Tak powiada Pan, Bóg Izraelski, mówiąc: Napisz sobie wszystkie słowa, którem mówił do ciebie, na księgach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Albowiem oto dni idą, mówi Pan, a przywrócę więźniów ludu swego Izraelskiego i Judzkiego, mówi Pan, i przyprowadzę ich do ziemi, którąm był dał ojcom ich, i posiędą ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'A teć są słowa, które mówił Pan o Izraelu i o Judzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Tak zaiste mówi Pan: Słyszeliśmy głos strachu i lękania, i że niemasz pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Pytajcież się teraz, a obaczcie, jeźli rodzi mężczyzna; przeczże tedy widzę, że każdy mąż rękami swemi trzyma się za biodra swe jako rodząca, i że się obróciły wszystkich oblicza w bladość?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Biada! bo wielki jest ten dzień, tak, że mu nie było podobnego; ale jakiżkolwiek jest czas utrapienia Jakóbowego, przecie z niego wybawiony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Stanie się bowiem dnia onego, mówi Pan zastępów, iż skruszę jarzmo jego z szyi twojej, a związki twoje potargam, i nie będą go więcej cudzoziemcy w niewolę podbijać;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Ale służyć będą Panu, Bogu swemu, i Dawidowi, królowi swemu, którego im wzbudzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Przetoż nie bój się ty, sługo mój Jakóbie! mówi Pan, ani się strachaj o Izraelu! bo oto Ja cię wybawię z daleka, i nasienie twoje z ziemi pojmania ich. I wróci się Jakób, aby odpoczywał i pokój miał, a nie będzie, ktoby go ustraszył;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Bom Ja z tobą, mówi Pan, abym cię wybawił. Ponieważ uczynię koniec wszystkim narodom, między które cię rozproszę, wszakże tobie nie uczynię końca, ale cię miernie karać będę, a cale cię bez karania nie zaniecham.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Tak zaiste mówi Pan: Ciężkie bardzo będzie skruszenie twoje, nader bolesna rana twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Nie będzie, ktoby sądził sprawę twoję ku uleczeniu; lekarstwa ku uleczeniu mieć nie będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Wszyscy miłośnicy twoi zapomną cię, ani cię nawiedzą, gdy cię zranię raną nieprzyjacielską, i okrutnem karaniem, dla wielkości nieprawości twojej i niezliczonych grzechów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Przeczże wołasz nad skruszeniem swem i ciężką boleścią swoją? Dla wielkości nieprawości twojej, i dla niezliczonych grzechów twoich uczyniłem ci to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'A wszakże wszyscy, którzy cię pożerają, pożarci będą; a wszyscy, którzy cię ciemiężą, wszyscy, mówię, w niewolę pójdą; a którzy cię plundrują, splundrowani będą; a wszystkich, którzy cię łupią, podam na łup.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Tedyć zdrowie przywrócę, i od ran twoich uleczę cię, mówi Pan, przeto, że wygnaną nazwali cię (mówiąc:) Tać jest Syon, niemasz nikogo, ktoby ją nawiedził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Tak mówi Pan: Oto Ja przywrócę pojmanych z namiotów Jakóbowych, a nad przybytkami jego zmiłuję się; i będzie zaś zbudowane miasto na pagórku swoim, a pałac według porządku swego wystawiony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'I wynijdzie od nich dziękczynienie, i głos weselących się; bo ich rozmnożę, a nie ubędzie ich, i uwielbię ich, a nie będą poniżeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'I będą synowie jego, jako i przedtem, a zgromadzenie jego przedemną utwierdzone będzie; ale nawiedzę wszystkich, którzy ich trapią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'I powstanie z niego najzacniejszy jego, a panujący nad nim z pośrodku jego wynijdzie, któremu się rozkażę przybliżyć, aby przystąpił przed mię; bo któż jest ten, coby ręczył za się, że przystąpi przed mię? mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'I będziecie ludem moim, a Ja będę Bogiem waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Oto wicher Pański z popędliwością wynijdzie, wicher trwający nad głową niezbożników zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Nie odwróci się zapalczywość gniewu Pańskiego, póki nie uczyni tego, a póki nie wykona umysłu serca swego; w ostatnie dni zrozumiecie to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Czasu onego, mówi Pan, będę Bogiem wszystkim rodzajom Izraelskim, a oni będą ludem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Tak mówi Pan: Znalazł łaskę na puszczy lud, który uszedł miecza, gdym chodził przed nim, abym odpocznienie uczynił Izraelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Rzeczeszli: Zdawna mi się Pan ukazywał. I owszem, miłością wieczną umiłowałem cię, dlategoć ustawicznie miłosierdzie pokazuję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Jeszcze cię zbuduję, a zbudowana będziesz, panno Izraelska! jeszcze się weselić będziesz przy bębnach swoich, a wychodzić z hufem pląsających;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Jeszcze będziesz sadziła winnice na górach Samaryjskich; a szczepiący szczepić będą i jeść będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Bo nastanie dzień, którego stróżowie wołać będą na górze Efraimowej: Wstańcie a wstąpmy na Syon do Pana, Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Tak zaiste mówi Pan: Śpiewajcie Jakóbowi o rzeczach wesołych, a wykrzykajcie jawnie przed tymi narodami; wydawajcie głos, chwałę oddawajcie a mówcie: Panie! wybaw ostatek ludu twego Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Oto Ja przywiodę ich z ziemi północnej, a zbiorę ich ze wszystkich stron ziemi; z nimi pospołu ślepego i chromego, brzemienną i rodzącą: tu się gromadą wielką nawrócą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Przywiodę ich zasię z płaczem i z modlitwami idących, a powiodę ich podle potoków wód drogą prostą, na którejby się nie potknęli; bom się stał Izraelowi ojcem, a Efraim jest pierworodnym moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Słuchajcie słowa Pańskiego, o narody! a opowiadajcie je na wyspach dalekich, i mówcie: Ten, który rozproszył Izraela, zgromadzi go, a strzedz go będzie, jako pasterz trzody swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Bo wykupił Pan Jakóba; przeto wybawi go z ręki tego, który jest mocniejszy nadeń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'I przyjdą a śpiewać będą na wysokości Syonu, i zbieżą się do dobrotliwości Pańskiej ze zbożem i z winem, i z oliwą i z jagniętami, i z cielętami, a dusza ich podobna będzie ogrodowi wilgotnemu, a nie będzie się więcej smuciła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Tedy się weselić będzie panna z pląsaniem, także młodzieńcy i starcy społem; albowiem kwilenie ich obrócę w radość, a pocieszę ich, i rozweselę ich po smutku ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'I opoję duszę kapłanów tłustością, a lud mój dobrocią moją nasyci się, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Tak mówi Pan: Głos w Rama słyszany jest, narzekanie i płacz bardzo gorzki; Rachel płacząca synów swoich nie dała się pocieszyć po synach swoich, przeto, że ich niemasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Tak mówi Pan: Zawściągnij głos swój od płaczu, a oczy swe od łez; bo będziesz miała zapłatę za pracę swoję, mówi Pan, że się nawrócą z ziemi nieprzyjacielskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Jest mówię nadzieja, że się potem nawrócą, mówi Pan, synowie twoi do krainy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Wprawdzie słyszę Efraima, że sobie utyskuje, mówiąc: Pokarałeś mię, abym był pokarany jako cielec nieokrócony. Nawróć mię abym był nawrócony; tyś zaiste Panie! Bóg mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Bo po nawróceniu mojem pokutować będą; a gdy samego siebie poznam, uderzę się w biodro; wstydzę się, owszem i zapałam się, że odnoszę hańbę dzieciństwa swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Izali synem moim miłym nie jest Efraim? Izali nie jest dziecięciem rozkosznem? Bo od onego czasu, jakom mówił przeciwko niemu, przecież nań ustawicznie wspominam; dlatego poruszają się wnętrzności moje nad nim, zaiste zlituję się nad nim, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Wystaw sobie pamiątki; nakładź sobie gromad kamieni; pamiętaj na ten gościniec, i na drogę, którąś chodziła: nawróć się, panno Izraelska! nawróć się do tych miast swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Dokądże się tułać będziesz, córko odporna? Bo uczyni Pan rzecz nową na ziemi: niewiasta ogarnie męża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Tak mówi Pan zastępów, Bóg Izraelski: Jeszcze mówić będę słowo to w ziemi Judzkiej, i w miastach jej, gdy przywiodę więźniów ich: Niech cię błogosławi Pan, o mieszkanie sprawiedliwości! o góro świętobliwości!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Albowiem osadzać się będą w ziemi Judzkiej we wszystkich miastach jego społem oracze, i ci, którzy chodzą za stadem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Napoję zaiste duszę spracowaną, a wszelką duszę smutną nasycę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Wtemem ocucił i spojrzałem, a sen mój był mi wdzięczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Oto dni idą, mówi Pan, w których posieję dom Izraelski i dom Judzki nasieniem człowieczem i nasieniem bydlęcem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'A jakom się starał, abym ich wykorzenił, i burzył, i kaził, i gubił, i trapił: tak się starać będę, abym ich pobudował i rozsadził, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'Za onych dni nie będą więcej mówić: Ojcowie jedli grona cierpkie, a synów zęby ścierpnęły;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Owszem, raczej rzeką: każdy dla nieprawości swojej umrze; każdego człowieka, któryby jadł grona cierpkie, ścierpną zęby jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Oto dni idą, mówi Pan, których uczynię z domem Izraelskim i z domem Judzkim przymierze nowe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Nie takie przymierze, jakiem uczynił z ojcami ich w on dzień, któregom ich ujął za rękę ich, abym ich przywiódł z ziemi Egipskiej; albowiem oni przymierze moje wzruszyli, chociażem Ja był małżonkiem ich, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Ale to jest przymierze, które postanowię z domem Izraelskim po tych dniach, mówi Pan: Dam zakon mój do wnętrzności ich, a na sercu ich napiszę go, i będę Bogiem ich, a oni będą ludem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'I nie będzie więcej uczył żaden bliźniego swego, i żaden brata swego, mówiąc: Poznajcie Pana; bo mię oni wszyscy poznają, od najmniejszego z nich aż do największego z nich, mówi Pan; bo miłościw będę nieprawościom ich, a grzechów ich nie wspomnę więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Tak mówi Pan, który daje słońce na światłość we dnie, postanowienie miesiąca i gwiazd na światłość w nocy; który rozdziela morze, a huczą nawałności jego; Pan zastępów imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Jeźli odstąpią te ustawy od oblicza mego, mówi Pan, tedyć i nasienie Izraelskie przestanie być narodem przed obliczem mojem po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Tak mówi Pan: Jeźli mogą być rozmierzone niebiosa z góry, a doścignione grunty ziemi na dole, tedyć i Ja cale odrzucę nasienie Izraelskie dla tego wszystkiego, co uczynili, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Oto idą dni (mówi Pan,) których będzie zbudowane to miasto Panu od wieży Chananeel aż do bramy narożnej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'A pójdzie jeszcze sznur pomiaru na przeciwko niej ku pagórkowi Gareb, a uda się ku Goa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'I wszystka dolina trupów i popiołu, i to wszystko pole aż do potoku Cedron, aż do węgła bramy końskiej wschodniej, poświęcone będą Panu; nie będzie wykorzenione ani zepsute więcej na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Słowo, które się stało do Jeremijasza od Pana roku dziesiątego Sedekijasza, króla Judzkiego, który jest rok ośmnasty Nabuchodonozora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, '(A wtenczas wojsko króla Babilońskiego obległo było Jeruzalem, a Jeremijasz prorok zamknięty był w sieni ciemnicy, która była w domu króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Bo go był dał wsadzić Sedekijasz, król Judzki, mówiąc: Czemu ty prorokujesz, mówiąc: Tak mówi Pan: Oto Ja to miasto podam w rękę króla Babiolońskiego, i weźmie je?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Sedekijasz także król Judzki nie ujdzie ręki Chaldejczyków; ale zapewne wydany będzie w rękę króla Babilońskiego, i będą mówiły usta jego z usty jego, a oczy jego oczy jego ogladają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'I zawiedzie Sedekijasza do Babilonu, aby tam był, aż go nawiedzę, mówi Pan; ponieważ walczycie z Chaldejczykami, nie poszczęści się wam.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Tedy rzekł Jeremijasz: Stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Oto Chanameel, syn Salluma, stryja twego, przyjdzie do ciebie, mówiąc: Kup sobie rolę moję, która jest w Anatot; bo tobie należy prawem bliskości, abyś ją kupił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'A gdy przyszedł do mnie Chanameel, syn stryja mego, według słowa Pańskiego do sieni ciemnicy, i rzekł do mnie: Proszę, kup rolę moję, która jest w Anatot, które jest w ziemi Benjaminowej, bo tobie należy prawem dziedzicznem, i bliskościąć przypada, kupże ją sobie: tedy zrozumiawszy, że to było słowo Pańskie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Kupiłem od Chanameela, syna stryja swego onę rolę, która jest w Anatot, i odważyłem mu pieniędzy, siedmnaście syklów srebra;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'A uczyniwszy zapis zapieczętowałem i oświadczyłem świadkami, odważywszy pieniądze na wadze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Potemem wziął według przykazania i prawa zapis kupna zapieczętowany i otwarty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'I oddałem on zapis kupna Baruchowi, synowi Neryjasza, syna Maasejaszowego, przed oczyma Chanameela, stryja swego, i przed oczyma świadków, którzy się podpisali w onym zapisie kupna, przed oczyma wszystkich Żydów, którzy byli usiedli w sieni ciemnicy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'I rozkazałem Baruchowi przed oczyma ich, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Tak mówi Pan zastępów, Bóg Izraelski: Weźmij te zapisy, ten zapis tego kupna, jako zapieczętowany, tak i ten zapis otworzony, a włóż je w naczynie gliniane, aby trwały przez wiele lat;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Bo tak mówi Pan zastępów, Bóg Izraelski: Jeszcze będą kupowane domy, i role, i winnice w tej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Potem modliłem się Panu, kiedym oddał on zapis kupna Baruchowi, synowi Neryjaszowemu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Ach panujący Panie!otoś ty uczynił niebo i ziemię mocą swoją wielką i ramianiem twoim wyciągnionem, nie jestci skryta przed tobą żadna rzecz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Czynisz miłosierdzie nad tysiącami, i oddajesz nieprawość ojcowską do łona synów ich po nich; Bóg wielki mocny, Pan zastępów imię twoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Wielki w radzie i możny w sprawie, ponieważ oczy twoje otworzone są na wszystkie drogi synów ludzkich, abyś oddał każdemu według dróg jego, i według owoców spraw jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Któryś uczynił znaki i cuda na ziemi Egipskiej aż do dnia tego, i w Izraelu, i między innymi ludźmi, i uczyniłeś sobie imię, jako się to dziś okazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Boś wywiódł lud twój Izraeski z ziemi Egipskiej w znakach i w cudach, i w ręce mocnej, i w ramieniu wyciągnionem i w strachu wielkim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'A podałeś im tę ziemię, o którąś przysiągł ojcom ich, żeś im miał dać ziemię opływającą mlekiem i miodem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Ale że wszedłszy do niej, a posiadłszy ją, nie usłuchali głosu twojego, i w zakonie twoim nie chodzili, wszystkiego, coś im rozkazał czynić, nie czynili; przetoż sprawiłeś to, aby nań przyszło to wszystko złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Oto strzelbę zatoczono przeciwko miastu, aby je wzięto, a miasto podane jest w ręce Chaldejczyków walczących przeciw niemu przez miecz, i głód, o mór; a tak cośkolwiek rzekł, dzieje się, to sam widzisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'A ty przecie mówisz do mnie, panujący Panie: Kup sobie tę rolę za pieniądze, a oświadcz to świadkami, choć już to miasto podane jest w ręcę Chaldejczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'I stało się słowo Pańskie do Jeremijasza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Otom Ja Pan, Bóg wszelkiego ciała; izaliż przedemną może być skryta która rzecz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Przetoż tak mówi Pan: Oto Ja daję to miasto w rękę Chaldejczyków, i w rękę Nabuchodonozora, króla Babilońskiego, i weźmie je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'A wszedłszy Chaldejczycy, którzy walczą przeciwko temu miastu, zapalą to miasto ogniem, i spalą je i te domy, na których dachach kadzili Baalowi, a sprawowali ofiary mokre bogom cudzym, aby mię wzruszali do gniewu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Bo synowie Izraelscy i synowie Judzcy od dzieciństwa swego to tylko czynią, co jest złego przed oczyma mojemi; synowie, mówię, Izraelscy tylko mię draźnili sprawą rąk swoich, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Zaiste na zapalczywość moję, i na gniew mój robi sobie to miasto ode dnia, którego je zbudowali, aż do dnia tego, tak, że mi przyjdzie oddalić od oblicza mego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'A to dla wszelkiej złości synów Izraelskich i synów Judzkich, którą popełniali, pobudzając mię do gniewu, sami, królowie ich, książęta ich, kapłani ich i prorocy ich, jako mężowie Judzcy, tak obywatele Jeruzalemscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Obracając się do mnie tyłem a nie twarzą; a gdy ich nauczam rano wstawając i nauczając, wszakże nie słuchają, aby przyjęli naukę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Nadto nastawiali obrzydliwości swych w tym domu, który nazwany jest od imienia mego, aby go splugawili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Nabudowali, mówię, wyżyn Baalowi, które są w dolinie Ben Hennon, aby przenaszali przez ognień synów swoich i córki swoje Molochowi, chociażem im tego nie rozkazał, ani to wstąpiło na serce moje, aby kiedy czynić mieli tę obrzydliwość, a do grzech u Judą przywodzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'A teraz dlatego tak mówi Pan, Bóg Izraelski, o tem mieście, o którem wy powiadacie: Podane jest w rękę króla Babilońskiego przez miecz, i głód, i mór:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Oto Ja zgromadzę ich ze wszystkich ziem, do którychem ich wygnał w popędliwości mojej i w gniewie moim, i w zapalczywości wielkiej, i przywiodę ich zaś na to miejsce, i uczynie, aby bezpiecznie mieszkali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'I będą ludem moim, a Ja będę Bogiem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'I dam im serce jedno, i drogę jednę, aby się mnie bali po wszystkie dni, tak, aby się im dobrze działo, i synom ich po nich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'I uczynię z nimi przymierze wieczne, że się nie odwrócę od nich, abym im nie miał dobrze czynić; nadto bojaźń moję dam do serca ich, aby nie odstępowali odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'I będę się weselił z nich, dobrze im czyniąc, gdyż ich wszczepię w tej ziemi warownie, ze wszystkiego serca mego i ze wszystkiej duszy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Bo tak mówi Pan: Jakom przywiódł na ten lud to wszystko wielkie złe, tak przywiodę na nich to wszystko dobre, o któremem z nimi mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Tedy będą kupować rolę w tej ziemi, o której wy powiadacie: Spustoszona jest tak, że w niej niemasz ani człowieka ani bydlęcia, podana jest w rękę Chaldejczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Rolę za pieniądze kupować będą, i zapisem warować, i pieczętować, i świadkami oświadczać w ziemi Benjaminowej, i około Jeruzalemu, i w miastach Judzkich, jako w miastach na górach tak w miastach na równinach, i w miastach na południe, gdy zaś przywrócę pojmanych ich, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'I stało się słowo Pańskie do Jeremijasza po wtóre, gdy jeszcze był zamknięty w sieni ciemnicy, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Tak mówi Pan, który to uczyni: Pan, który to utworzy, potwierdzi to, Pan jest imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Wołaj do mnie, a ozwęć się i oznajmięć rzeczy wielkie i skryte, o których nie wiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Albowiem tak mówi Pan, Bóg Izraelski, o domach miasta tego, i o domach królów Judzkich, które pokażone być mają taranami wojennemi i mieczem:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Pociągną, żeby walczyli z Chaldejczykami, a żeby napełnili te domy trupami ludzi, które pobiję w zapalczywości mojej i w gniewie moim, zakrywając twarz moję od tego miasta dla wszelakich złości ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Wszakże Ja przywiodę ich do zdrowia, i uleczę a uzdrowię ich, i objawię im obfitość pokoju, a pokoju pewnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Bo przywrócę pojmanych z Judy, i pojmanych z Izraela, a pobuduję ich jako przedtem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'I oczyszczę ich od wszelkiej nieprawości ich, którą zgrzeszyli przeciwko mnie, i przepuszczę wszystkim złościom ich, któremi zgrzeszyli przeciwko mnie, i któremi wystąpili przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'A będzie mi to sławą, weselem, chwałą, i ozdobą przed wszystkiemi narodami ziemi, które usłyszą o wszystkiem dobrem, które Ja im czynię, i ulękną się, a zatrwożą się nad wszystkiem dobrem i nad wszystkim pokojem, który Ja im sposobię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Tak mówi Pan: Jeszcze słyszany będzie na tem miejscu, (o którem wy powiadacie: Jest spustoszone, tak, że niemasz ani człowieka, ani bydlęcia, w miastach Judzkich i na ulicach Jeruzalemskich spustoszonych, tak, że niemasz ani człowieka, ani obywa tela, ani bydlęcia.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Słyszany, mówię, będzie głos radości, i głos wesela, głos oblubieńca, i głos oblubienicy, głos mówiących: Wysławiajcie Pana zastępów; albowiem dobry jest Pan, albowiem na wieki miłosierdzie jego; i głos przynoszący ofiarę chwały do domu Pańskiego, gdyż przywrócę pojmanych z tej ziemi, jako na początku, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Tak mówi Pan zastępów: Jeszcze będzie na tem miejscu pustem, na którem niemasz ani człowieka, ani bydlęcia, i we wszystkich miastach jego mieszkanie pasterzy, gdzieby chowali trzody;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'W miastach na górach, w miastach na równinach, i w miastach na południe, i w ziemi Benjaminowej, i około Jeruzalemu, i w miastach Judzkich jeszcze przychodzić będą trzody pod ręką liczącego, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Oto dni idą, mówi Pan, w których utwierdzę to słowo dobre, którem był wyrzekł o domu Izraelskim i o domu Judzkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'W one dni w onym czasie uczynię to, iż wyrośnie Dawidowi latorośl sprawiedliwa, która czynić będzie sąd i sprawiedliwość na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'Onych dni będzie zbawiony Juda, a Jeruzalem bezpiecznie mieszkać będzie. A toć jest imię, którem ją nazowią: Pan sprawiedliwość nasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Bo tak mówi Pan: Nie będzie wykorzeniony mąż z rodu Dawidowego, aby nie miał siedzieć na stolicy domu Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Z kapłanów też i z Lewitów nie będzie wykorzeniony mąż od oblicza mego, aby nie miał ofiarować całopalenia, i zapalać śniednej ofiary, i sprawować ofiar po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Potem stało się słowo Pańskie do Jeremijasza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Tak mówi Pan: Jeźli będziecie mogli złamać przymierze moje ze dniem, i przymierze moje z nocą, aby nie bywało dnia ani nocy czasu swego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'Tedy też przymierze moje złamane będzie z Dawidem, sługą moim, aby nie miał syna, któryby królował na stolicy jego, i z Lewitami kapłanami, aby nie byli sługami moimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'A jako nie może policzone być wojsko niebieskie, ani zmierzony piasek morski, tak rozmnożę nasienie Dawida, sługi mojego, i Lewitów, którzy mi służą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Znowu się stało słowo Pańskie do Jeremijasza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Aza nie widzisz, co ten lud powiada, mówiąc: Że dwa domy, które był Pan obrał, te już odrzucił, a że ludem moim pogardzają, jakoby nie był więcej narodem przed obliczem ich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Tak mówi Pan: Nie będzieli przymierze moje ze dniem i z nocą stałe, a jeźlim początku niebios i ziemi nie postanowił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'Tedyć i nasienie Jakóbowe i Dawida sługi mego odrzucę, abym nie brał z nasienia jego tych, którzyby panować mieli nad nasieniem Abrahamowem, Izaakowem, i Jakóbowem, gdyż przywrócę więźniów ich, a zlituję się nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Słowo, które się stało do Jeremijasza od Pana, (gdy Nabuchodonozor, król Babiloński, i wszystko wojsko jego, i wszystkie królestwa ziemi, które były pod władzą ręki jego, i wszystkie narody walczyły przeciwko Jeruzalemowi i przeciwko wszystkim miastom jego,) mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Tak mówi Pan, Bóg Izraelski: Idź, a mów Sedekijaszowi, królowi Judzkiemu, i powiedz mu: Tak mówi Pan: Oto Ja to miasto podam w rękę króla Babilońskiego, aby je ogniem spalił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'I ty nie ujdziesz ręki jego, ale zapewne będziesz pojmany, i w ręce jego podany, a oczy twoje oglądają oczy króla Babilońskiego, i usta jego z usty twemi mówić będą, a do Babilonu wnijdziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'A wszakże słuchaj słowa Pańskiego, Sedekijaszu, królu Judzki! Tak mówi Pan o tobie: Nie umrzesz od miecza:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'W pokoju umrzesz; a jako wonne rzeczy palono ojcom twoim, królom przeszłym, którzy byli przed tobą, tak palić będą i tobie, a płakać cię będą, mówiąc: Ach, panie! Bom Ja to słowo rzekł, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Tedy mówił Jeremijasz prorok do Sedekijasza, króla Judzkiego, wszystkie te słowa w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Gdy wojsko króla Babilońskiego walczyło przeciwko Jeruzalemowi, i przeciwko wszystkim miastom Judzkim pozostałym, przeciwko Lachys, i przeciw Asekowi; albowiem te były pozostały z miast Judzkich miasta obronne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Słowo, które się stało do Jeremijasza od Pana, gdy uczynił król Sedekijasz przymierze ze wszystkim ludem, co był w Jeruzalemie, wolność im ogłaszając;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'To jest, aby każdy wolno puścił sługę swego, i każdy służebnicę swoję, Żyda i Żydówkę, aby sobie nikt nie zniewalał Żyda, brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'A tak usłuchały wszyscy książęta, i wszystek lud, którzy byli weszli w przymierze, żeby każdy wolno puścił sługę swego, i każdy służebnicę swoję, aby ich więcej nie zniewalali; usłuchali, mówię, i puścili ich wolno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Lecz potem rozmyśliwszy się, pobrali zaś sługi i służebnice, które byli puścili wolno, a zniewolili ich sobie za sługi i za służebnice.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'I stało się słowo Pańskie do Jeremijasza od Pana, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Tak mówi Pan, Bóg Izraelski: Jam postanowił przymierze z ojcami waszymi w dzień, któregom ich wywiódł z ziemi Egipskiej, z domu niewoli, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Gdy się skończą siedm lat, niech wolno puści każdy brata swego Żyda, któryćby był sprzedany, a służyłciby przez sześć lat; wolno, mówię, puści go od siebie. Ale mię nie słuchali ojcowie wasi, ani nakłonili ucha swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Wyścieć się zaiste dziś nawrócili, i uczyniliście to, co jest dobrego przed oczyma mojemi, żeście ogłosili wolność każdy bliźniemu swemu, i uczyniliście przymierze przed twarzą moją w domu tym, który jest nazwany od imienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Aleście się zaś cofnęli, i splugawiliście imię moje, żeście zaś wzięli każdy sługę swego, i każdy służebnicę swoję, któreście byli wolno puścili według żądności ich, i zniewoliliście ich, aby byli sługami i służebnicami waszymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Dlategoż tak mówi Pan: Wyście mię nie słuchali, abyście ogłosili wolność każdy bratu swemu, i każdy bliźniemu swemu; otoż Ja przeciwko wam ogłaszam wolność, mówi Pan, miecza, moru, i głodu, a podam was na potłukanie po wszystkich królestwach ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Podam zaiste tych ludzi, którzy przestąpili przymierze moje, którzy nie dotrzymali słów przymierza tego, które uczynili przed twarzą moją, gdy cielca na dwoje rozcięli, i przeszli między częściami jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'To jest książąt Judzkich, i książąt Jeruzalemskich, komorników i kapłanów, i wszystek lud tej ziemi, którzy przeszli między częściami tego cielca,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Podam ich mówię, w rękę nieprzyjaciół ich, i w rękę szukających duszy ich, i będą trupy ich żerem ptastwu niebieskiemu i bestyjom ziemskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Sedekijasza też, króla Judzkiego, i książąt jego podam w rękę nieprzyjaciół ich, i w rękę szukających duszy ich, w rękę, mówię, wojska króla Babilońskiego, które odstąpiło od was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Oto Ja rozkażę, mówi Pan, i przywiodę ich zaś na to miasto, aby walczyli przeciwko niemu, a wziąwszy je spalili je ogniem; miasta też Judzkie obrócę w pustynię, tak iż będą bez obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Słowo, które się stało do Jeremijasza od Pana za dni Joakima, syna Jozyjaszowego, króla Judzkiego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Idź do domu Rechabitów, a mów z nimi, i wprowadź ich do domu Pańskiego, do jednej komory, a daj im pić wino.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Wziąłem tedy z sobą Jasanijasza, syna Jeremijaszowego, syna Chabazymijaszowego, i braci jego, i wszystkich synów jego, i wszystek dom Rechabitów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'I wprowadziłem ich do domu Pańskiego, do komory synów Chanana, syna Jegdalijaszowego, męża Bożego, która była podle komory książęcej, która była nad komorą Maasejasza, syna Sallumowego, strzegącego progu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Potem postawiłem przed synami domu Rechabitów czaszę pełną wina i kubki, i mówiłem do nich: Pijcie wino.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Którzy odpowiedzieli: Nie pijamy wina; bo Jonadab, syn Rechabowy, ojciec nasz, zakazał nam, mówiąc: Nie pijajcie wina, wy i synowie wasi aż na wieki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'A domu nie budujcie, i nasienia nie rozsiewajcie, i winnicy nie sadźcie, ani miewajcie; ale w namiotach mieszkajcie po wszystkie dni wasze, abyście żyli przez wiele dni na obliczu ziemi,w której jesteście przechodniami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Przetoż usłuchaliśmy głosu Jonadaba, syna Rechabowego, ojca naszego, we wszystkiem, co nam rozkazał, żebyśmy nie pili wina po wszystkie dni nasze, my, żony nasze, synowie nasi, i córki nasze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'I żebyśmy nie budowali domów ku mieszkaniu naszemu, a winnicy, i roli, i żadnego siewu nie mieli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Ale abyśmy mieszkali w namiotach; i usłuchaliśmy, i uczynimy według wszystkiego, co nam rozkazał Jonadab, ojciec nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'A gdy przyciągnął, Nabuchodonozor król Babiloński, do ziemi naszej, rzekliśmy: Pójdźcie, a ustąpmy do Jeruzalemu przed wojskiem Chaldejskiem, i przed wojskiem Syryjskiem; a takeśmy zostali w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'I stało się słowo Pańskie do Jeremijasza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Tak mówi Pan zastępów, Bóg Izraelski: Idź, a rzecz mężom Judzkim i obywatelom Jeruzalemskim: I nie przyjmiecież ćwiczenia, abyście posłuszni byli słowom moim? mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Ważne są słowa Jonadaba, syna Rechabowego, które przykazał synom swoim, żeby nie pili wina; i nie piją go aż do dnia tego, bo posłuszni są przykazaniu ojca swego; ale Ja mówię do was, rano wstawając i mówiąc, a przecie jesteście nieposłuszni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Posyłam też do was wszystkich sług swych, proroków w rano wstawając i posyłając, aby mówili: Nawróćcie się już każdy od złej drogi swej, a polepszajcie spraw swoich, a nie naśladujcie bogów cudzych, ani im służcie; a tak mieszkajcie w tej ziemi, którąm dał wam, i ojcom waszym; aleście nie nakłonili ucha swego, aniście mię usłuchali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Choć synowie Jonadaba, syna Rechabowego, dosyć uczynili rozkazaniu ojca swego, które im przykazał, ale ten lud nie jest mi posłuszny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Przetoż tak mówi Pan, Bóg zastępów, Bóg Izraelski: Oto Ja przywiodę na Judę i na wszystkich obywateli Jeruzalemskich wszystko złe, którem wyrzekł przeciwko im, przeto, żem mówił do nich, a nie słuchali, i wołałem ich, a nie ozwali mi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'A domowi Rechabitów rzekł Jeremijasz: Tak mówi Pan zastępów, Bóg Izraelski: Dlatego, żeście posłuszni rozkazaniu Jonadaba, ojca waszego, i strzeżecie wszystkich przykazań jego, a czynicie według wszystkiego, co wam rozkazał:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'Przetoż tak mówi Pan zastępów, Bóg Izraelski: Nie będzie wygładzony mąż z rodu Jonadaba, syna Rechabowego, któryby stał przed obliczem mojem po wszystkie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'I stało się roku czwartego Joakima, syna Jozyjaszowego, króla Judzkiego; stało się, mówię, to słowo do Jeremijasza od Pana, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Weźmij sobie księgi, a napisz na nich wszystkie słowa, którem mówił do ciebie przeciw Izraelowi, i przeciw Judzie, i przeciw wszystkim narodom, ode dnia, króregom mawiał z tobą, ode dni Jozyjaszowych aż do dnia tego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Aza snać, gdy usłyszy dom Judzki o tem wszystkiem złem, które Ja im myślę uczynić, nawróci się każdy od złej drogi swej, abym był miłościw nieprawościom ich i grzechom ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Przetoż wezwał Jeremijasz Barucha, syna Neryjaszowego; i napisał Baruch w księgi z ust Jeremijaszowych wszystkie słowa Pańskie, które mówił do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Potem przykazał Jeremijasz Baruchowi, mówiąc: Ja będąc zatrzymany nie mogę wnijść do domu Pańskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'Przetoż ty idź, a czytaj na tych księgach, coś napisał z ust moich, słowa Pańskie, przed uszyma ludu w domu Pańskim w dzień postu; także też przed uszyma wszystkich z Judy którzyby przyszli z miast swoich, czytaj je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Owa snać przyjdzie modlitwa ich przed oblicze Pańskie, a nawróci się każdy od złej drogi swojej; bo wielka jest zapalczywość i gniew, w którym mówił Pan przeciwko temu ludowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Tedy uczynił Baruch, syn Neryjaszowy, według wszystkiego, co mu rozkazał Jeremijasz prorok, czytając z ksiąg słowa Pańskie w domu Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'I stało się roku piątego za Joakima. syna Jozyjaszowego, króla Judzkiego, w miesiącu dziewiątym, że zapowiedziano post przed twarzą Pańską wszystkiemu ludowi w Jeruzalemie, i wszystkiemu ludowi, który się był zszedł z miast Judzkich do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'I czytał Baruch z ksiąg słowa Jeremijaszowe w domu Pańskim, w pokoju Giemaryjasza, syna Safanowego, pisarza, w sieni wyższej, w wejściu bramy nowej domu Pańskiego przed uszyma wszystkiego ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'A gdy usłyszał Micheasz, syn Giemaryjasza, syna Safanowego, wszystkie słowa Pańskie z ksiąg,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Zstąpił do domu królewskiego, do komory pisarzowej, a oto tam wszyscy książęta siedzieli: Elisama pisarz, i Delajasz, syn Semajaszowy, i Elnatan, syn Achborowy, i Giemaryjasz, syn Safanowy, i Sedekijasz, syn Chananijaszowy, i wszyscy książęta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'I powiedział im Micheasz wszystkie słowa, które słyszał, gdy czytał Baruch z ksiąg przed uszyma ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Przetoż posłali wszyscy książęta do Barucha Jehudę, syna Natanijaszowego, syna Selemijaszowego, syna Chusowego, aby rzekł: Księgi, na którycheś czytał przed uszyma ludu, weźmij w rękę twą a pójdź. Wziął tedy Baruch, syn Neryjaszowy, księgi w rękę swą i przyszedł do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'I rzekli do niego: Siądź proszę, a czytaj to przed uszyma naszemi. I czytał Baruch przed uszyma ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'A gdy usłyszeli wszystkie one słowa, ulękłszy się wejrzał jeden na drugiego, i rzekli do Barucha: Zaiste oznajmiemy królowi te wszystkie słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'I pytali Barucha, mówiąc: Powiedz nam teraz, jakoś pisał wszystkie te słowa z ust jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'I rzekł im Baruch: Z ust swych mówił do mnie wszystkie te słowa, a jam pisał na księgach inkaustem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Tedy rzekli książęta do Barucha: Idź, a skryj się, ty i Jeremijasz, a niech nikt nie wie, gdzieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Potem weszli do króla do sieni, a księgi dali schować do komory Elisama, pisarza, i oznajmili przed królem te wszystkie słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Posłał tedy król Juhudę, aby wziął one księgi; który je wziął z komory Elisama, pisarza. I czytał je Jehuda przed uszyma królewskiemi, i przed uszyma wszystkich książąt, którzy stali przed królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'A król siedział w domu, w którym w zimie bywał, miesiąca dziewiątego, a na ognisku przed nim palił się ogień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'A gdy przeczytał Jehuda trzy albo cztery karty, porzezał je król nożykiem pisarskim, i wrzucił je w ogień, który był na ognisku, aż zgorzały wszystkie księgi w ogniu, który był na ognisku;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Ale się nie ulękli, ani rozdarli szat swoich, król i wszyscy słudzy jego, którzy słyszeli wszystkie te słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Owszem, jeszcze gdy Elnatan, i Delajasz, i Giemaryjasz przyczyniali się do króla, aby nie palił onych ksiąg, tedy ich nie usłuchał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Ale rozkazał król Jerameelowi, synowi królewskiemu, i Sarajaszowi, synowi Abdeelowemu, aby pojmali Barucha pisarza, i Jeremijasza proroka; ale ich Pan skrył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'I stało się słowo Pańskie do Jeremijasza, gdy król spalił one księgi i słowa, które był spisał Baruch z ust Jeremijaszowych, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Weźmij sobie zasię księgi inne, a napisz na nich wszystkie słowa pierwsze, które były w onych księgach pierwszych, które spalił Joakim, król Judzki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'A o Joakimie, królu Judzkim, rzeczesz: Tak mówi Pan: Tyś spalił te księgi, mówiąc: Czemuś pisał na nich, rzekłszy: Zapewne przyciągnie król Babiloński, i spustoszy tę ziemię, i wygładzi z niej człowieka i bydlę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Przetoż tak mówi Pan o Joakimie, królu Judzkim: Nie będzie miał, ktoby siedział na stolicy Dawidowej, a trup jego wyrzucony będzie na gorącość we dnie, a na mróz w nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Bo nawiedzę na nim, i na nasieniu jego, i na sługach jego nieprawość ich, i przywiodę na nich i na obywateli Jeruzalemskich, i na mężów Judzkich to wszystko złe, o któremem mawiał do nich; ale nie słuchali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Tedy Jeremijasz wziął księgi inne, i dał je Baruchowi, synowi Neryjaszowemu, pisarzowi, który na nich spisał z ust Jeremijaszowych wszystkie słowa onych ksiąg, które był spalił ogniem Joakim, król Judzki; a nadto przydano do onych słów wiele rzec zy tym podobnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Potem królował król Sedekijasz, syn Jozyjaszowy, miasto Chonijasza, syna Joakimowego, którego Nabuchodonozor, król Babiloński, w ziemi Judzkiej królem postanowił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Lecz nie był posłuszny on, i słudzy jego, i lud onej ziemi słowom Pańskim, które mówił przez Jeremijasza proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Ale jednak król Sedekijasz posłał Jechuchala, syna Selemijaszowego, i Sofonijasza, syna Maazejaszowego, kapłana, do Jeremijasza proroka, aby mówili: Módl się proszę za nami Panu, Bogu naszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Bo Jeremijasz jeszcze wolno chodził między ludem, i jeszcze go było nie wsadzono do więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'A wojsko Faraonowe wyciągnęło było z Egiptu; (a usłyszawszy Chaldejczycy, którzy byli oblegli Jeruzalem, wieść o tem, odciągnęli od Jeruzalemu.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'I stało się słowo Pańskie do Jeremijasza proroka, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'To mówi Pan, Bóg Izraelski: Tak powiedzcie królowi Judzkiemu, który was posłał do mnie, abyście się mnie radzili: Oto wojsko Faraonowe, które wam przyciągnęło na pomoc, wróci się do ziemi swojej do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'I wrócą się zasię Chaldejczycy, i będą walczyli przeciwko temu miastu, i wezmą je, i spalą je ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Tak mówi Pan: Nie zwodźcie dusz waszych, mówiąc: Zapewne odciągną od nas Chaldejczycy; boć nie odciągną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Owszem, choćbyście porazili wszystko wojsko Chaldejczyków, którzy walczą z wami, a zostaliby z nich tylko zranieni, ci z namiotów swoich powstaną, a to miasto ogniem spalą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Gdy tedy odciągnęło wojsko Chaldejczyków od Jeruzalemu przed wojskiem Faraonowem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Wychodził Jeremijasz z Jeruzalemu, aby szedł do ziemi Benjaminowej, aby tak uszedł z pośrodku ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'A gdy już był w bramie Benjaminowej, był tam przełożony nad strażą, imieniem Jeryjasz, syn Selemijasza, syna Chananijaszowego, który pojmał Jeremijasza proroka, mówiąc: Do Chaldejczyków ty uciekasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'A Jeremijasz odpowiedział: Nieprawda, nie uciekam do Chaldejczyków; ale go nie chciał słuchać, owszem, pojmał Jeryjasz Jeremijasza, i przywiódł go do książąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Tedy rozgniewawszy się książęta na Jeremijasza, ubili go, i podali go do więzienia, do domu Jonatana pisarza; bo z niego byli uczynili dom więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'A gdy wszedł Jeremijasz do onego domu a do tarasu ich, i siedział tam Jeremijasz przez wiele dni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Tedy posławszy król Sedekijasz, wziął go, i pytał go król w domu swoim potajemnie, mówiąc: Jestże jakie słowo od Pana? I odpowiedział Jeremijasz: Jest; przytem rzekł: W rękę króla Babilońskiego podany będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Nadto rzekł Jeremijasz do króla Sedekijasza: Cóżem zgrzeszył przeciwko tobie, i sługom twoim, i ludowi twemu, żeście mię podali do tego domu więzienia?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'I gdzież są prorocy wasi, którzy wam prorokują, mówiąc: Nie przyjdzie król Babiloński na was, ani na tę ziemię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Słuchajże teraz, proszę, królu, panie mój! niech będzie, proszę, ważna prośba moja przed tobą: Nie odsyłajże mię do domu Jonatana pisarza, abym tam nie umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'A tak rozkazał król Sedekijasz, aby wsadzony był Jeremijasz do sieni straży, a iżby mu dawano bochenek chleba na dzień z ulicy piekarskiej, pókiby nie był strawiony wszystek chleb w mieście. A tak siedział Jeremijasz w sieni straży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'I usłyszał Sefatyjasz, syn Matanowy, i Godolijasz, syn Fassurowy, i Juchal, syn Selemijaszowy, i Fassur, syn Melchijaszowy, słowa, które Jeremijasz mówił do wszystkiego ludu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Tak mówi Pan: Ktoby został w tem mieście, zginie od miecza, od głodu i od moru; ale ktoby wyszedł do Chaldejczyków, żyć będzie, a będzie mu dusza jego za korzyść, i żyw zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Tak mówi Pan: Pewnie podane będzie to miasto w ręce wojska króla Babilońskiego, i weźmie je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Przetoż rzekli oni książęta do króla: Niech umrze ten mąż, ponieważ on osłabia ręce mężów walecznych, pozostałych w tem mieście, i ręce wszystkiego ludu, mówiąc do nich takie słowa; albowiem ten mąż nie szuka pokoju ludowi temu, ale złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Tedy rzekł król Sedekijasz: Oto jest w ręce waszej; bo król nic zgoła nie może przeciwko wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'A tak wzięli Jeremijasza, który był w sieni straży, i wrzucili go do dołu Malchyjasza, syna królewskiego, i puścili Jeremijasza po powrozach; a w tym dole nie było nic wody, tylko błoto, a tak tonął Jeremijasz w onem błocie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Ale gdy usłyszał Ebedmelech Murzyn, dworzanin, który był w domu królewskim, że Jeremijasza podano do dołu, (a król siedział w bramie Benjaminowej,)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Wnet wyszedł Ebedmelech z domu królewskiego, i rzekł do króla, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Królu, panie mój! źle uczynili ci mężowie wszystko, co uczynili Jeremijaszowi prorokowi, że go wrzucili do tego dołu; boćby był umarł na pierwszem miejscu od głodu, ponieważ już niemasz żadnego chleba w mieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Przetoż rozkazał król Ebedmelechowi Murzynowi, mówiąc: Weźmij z sobą stąd trzydzieści mężów, a wyciągnij Jeremijasza proroka z tego dołu, niżby umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Tedy wziął Ebedmelech onych mężów z sobą, i wszedł do domu królewskiego pod skarbnicę, i nabrał stamtąd starych szmacisk podartych, szmacisk, mówię, zbótwiałych, które spuścił do Jeremijasza do onego dołu po powrozach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'I rzekł Ebidmelech Murzyn do Jeremijasza: Nuże podłóż te stare podarte i zbótwiałe szmaciska pod pachy rąk twoich pod powrozy; i uczynił tak Jeremijasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'I wyciągnęli tedy Jeremijasza powrozami, i dobyli go z onego dołu; i siedział Jeremijasz w sieni straży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Tedy posłał król Sedekijasz i wziął Jeremijasza proroka do siebie do trzecich drzwi, które były przy domu Pańskim. I rzekł król Jeremijaszowi: Spytam cię o jednę rzecz, nie taj nic przedemną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'I rzekł Jeremijasz do króla Sedekijasza: Jeźlić co powiem, pewnie mię zabijesz? A jeźlić co poradzę, nie usłuchasz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Tedy przysiągł król Sedekijasz Jeremijaszowi potajemnie, mówiąc: Jeko żyje Pan, który nam tę duszę stworzył, że cię nie zabiję, ani cię wydam w rękę mężów tych, którzy szukają duszy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'I rzekł Jeremijasz do Sedekijasza: Tak mówi Pan, Bóg zastępów, Bóg Izraelski: Jeźli dobrowolnie wynijdziesz do książąt króla Babilońskiego, tedy żyć będzie dusza twoja, a to miasto nie będzie spalone ogniem; a tak żyw zostaniesz ty i dom twój;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Ale jeźli nie wynijdziesz do książąt króla Babilońskiego, pewnie będzie podane to miasto w rękę Chaldejczyków, i spalą je ogniem, a i ty nie ujdziesz ręki ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Tedy rzekł król Sedekijasz do Jeremijasza: Bardzo się boję Żydów, którzy pouciekali do Chaldejczyków, bym snać nie był wydany w rękę ich, a szydziliby ze mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'I rzekł Jeremijasz: Nie wydadzą, słuchaj proszę głosu Pańskiego, któryć ja opowiadam, a będzieć dobrze, i żyć będzie dusza twoja;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'A jeźli się będziesz zbraniał wynijść, tedy to jest słowo, które mi Pan pokazał:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Że oto wszystkie niewiasty, które zostały w domu króla Judzkiego, będą wywiedzione do książąt króla Babilońskiego, a te same rzeką: Namówili cię, i otrzymali to na tobie przyjaciele twoi, że ulgnęły w błocie nogi twoje, i cofnęły się nazad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Wszystkie także żony twoje i synów twoich wywiodą do Chaldejczyków, i ty sam nie ujdziesz ręki ich, owszem ręką króla Babilońskiego będziesz pojmany, i to miasto spalą ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Tedy rzekł Sedekijasz do Jeremijasza: Niechaj nikt nie wie o tem, abyś nie umarł;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'A jeźliby książęta usłyszawszy, żem mówił z tobą, przyszli do ciebie, i rzeklić: Powiedz nam, proszę, coś mówił z królem, nie taj przed nami, a nie zabijemy cię: co z tobą król mówił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'Tedy im rzeczesz: Przełożyłem prośbę moję przed królem, aby mię zaś nie kazał odwiść do domu Jonatanowego, żebym tam nie umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'A zeszli się wszyscy książęta do Jeremijasza, i pytali go; który im powiedział według tego wszsytkiego, jako mu był król rozkazał. A tak milcząc odeszli od niego, gdyż się to było nie ogłosiło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'A Jeremijasz siedział w sieni straży aż do onego dnia, którego wzięto Jeruzalem, gdzie był, gdy dobywano Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Roku dziewiątego Sedekijasza, króla Judzkiego, miesiąca dziesiątego, przyciągnął Nabuchodonozor, król Babiloński, ze wszystkiem wojskiem swojem do Jeruzalemu, i oblegli je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'A jedenastego roku Sedekijasza, miesiąca czwartego, dziewiątego dnia tegoż miesiąca, dobyto miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'I wpadli do niego wszyscy książęta króla Babilońskiego, i usiedli w bramie średniej: Nergalscharezer, Samgarnebu, Sarsechym, Rabsarys, Nergalscharezer, Rabmag, i wszyscy inni książęta króla Babilońskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'A gdy ich ujrzał Sedekijasz, król Judzki, i że wszyscy mężowie waleczni uciekli, i wyszli w nocy z miasta drogą ogrodu królewskiego, bramą między dwoma murami, uszedł też i król drogą ku puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'A wojsko Chaldejczyków goniło ich, i doścignęli Sedekijasza na równinach Jerycha, i wzięli go, i przywiedli go do Nabuchodonozora, króla Babilońskiegp, do Reble, do ziemi Emat, gdzie wydał przeciwko niemu dekret.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Bo pomordował król Babiloński synów Sedekijaszowych w Rebli przed oczyma jego, i wszystkich najprzedniejszych z Judy pomordował król Babiloński.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Ale oczy Sedekijaszowi wyłupił, a związawszy go łańcuchami miedzianemi prowadził go do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Dom także królewski i dom onego ludu spalili Chaldejczycy ogniem, i mury Jeruzalemskie rozwalili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Ale ostatek ludu, który był został w mieście, i zbiegi, którzy byli pouciekali do niego, i inny lud pozostały zawiódł Nabuzardan, hetman żołnierski, do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Tylko najpodlejszych z ludu, którzy nic nie mieli, zastawił Nabuzardan, hetman żołnierski, w ziemi Judzkiej, którym rozdał winnice i role dnia onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'A o Jeremijaszu przykazał Nabuchodonozor, król Babiloński, Nabuzardanowi, hetmanowi żołnierskiemu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Weźmij go, a pilnie go doglądaj, a nie czyń mu nic złego, ale jakoć rzekę, tak z nim postąp.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Przetoż posławszy Nabuzardan, hetman żołnierski, i Nebusasban, Rabsarys i Nergalscharezer, Rabmag, i wszyscy hetmani króla Babilońskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'Posławszy, mówię, wzięli Jeremijasza z sieni straży, i poruczyli go Godolijaszowi, synowi Ahikama, syna Safanowego, aby go dowiódł do domu. A tak mieszkał w pośród ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'I stało się do Jeremijasza słowo Pańskie, gdy jeszcze był zamknięty w sieni straży, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Idź, a powiedz Ebedmelechowi Murzynowi, mówiąc: Tak mówi Pan zastępów, Bóg Izraelski: Oto Ja przywiodę słowa moje na to miasto ku złemu a nie ku dobremu, i wypełnią się przed obliczem twojem dnia onego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Ale ciebie wybawię onegoż dnia, mówi Pan, i nie będziesz podany w rękę mężów, których się ty oblicza boisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Albowiem cię pewnie wyrwę, abyś od miecza nie upadł; ale będziesz miał duszę twoję za korzyść, przeto, żeś położył nadzieję we mnie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Słowo, które się stało do Jeremijasza od Pana, gdy go wypuścił Nabuzardan, hetman żołnierski, z Ramy, wziąwszy go, gdy był związany łańcuchami w pośród wszystkich więźniów Jeruzalemskich i Judzkich, których wiedziono do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'A tak wziął hetman żołnierski Jeremijasza, i rzekł do niego: Pan, Bóg twój, opowiedział był to złe przeciwko miejscu temu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Przetoż je przywiódł, i uczynił Pan, jako mówił; boście zgrzeszyli Panu, a nie słuchaliście głosu jego, i dlatego się wam to stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Teraz tedy, oto cię rozwiązuję dziś z tych łańcuchów, które są na rękach twoich. Jeźlić się zda rzeczą dobrą, iść zemną do Babilonu, pójdź, ja o tobie będę zawiadywał; a jeźlić się nie podoba iść zemną do Babilonu, tedy zaniechaj. Oto ta wszystka ziemia jest przed obliczem twojem; gdzie wolisz, a gdzieć się podoba iść, tam idź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'A ponieważ się tu on więcej nie wróci, udaj się do Godolijasza, syna Ahikamowego, syna Safanowego, którego przełożył król Babiloński nad miastami Judzkiemi, a mieszkaj z nim w pośród ludu, albo gdzieć się kolwiek podoba iść, idź. I dał mu hetman żołnierski na drogę i upominek, i odprawił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Przyszedł tedy Jeremijasz do Godolijasza, syna Ahikamowego, do Masfy, i mieszkał z nim w pośród ludu, który był pozostał w ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'A gdy usłyszeli wszyscy hetmani wojsk, którzy byli w polach, oni i wszystek lud ich, że król Babiloński postanowił Godolijasza, syna Ahikamowego, nad oną ziemią, a iż mu zlecił mężów, i niewiasty, i dziatki, a to najpodlejszych onej ziemi, tych, którzy nie byli zaprowadzeni do Babilonu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Tedy przyszli do Godolijasza do Masfy, to jest, Izmael, syn Natanijaszowy, także Johanan i Jonatan, synowie Kareaszowi, i Serajasz, syn Tanchumetowy, i synowie Efaj Netofatczyka, i Jasanijasz, syn Machatowy, oni i lud ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Tedy im przysiągł Godolijasz, syn Ahikama, syna Safanowego, i ludowi ich, mówiąc: Nie bójcie się służyć Chaldejczykom, zostańcie w ziemi, i służcie królowi Babilońskiemu, a dobrze wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Bo oto i ja mieszkam w Masfie, abym służył Chaldejczykom, którzy przychodzą do nas; a wy zbierajcie wino i letni owoc i oliwę, a składajcie do naczynia waszego, i mieszkajcie w miastach waszych, które trzymacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Także i wszyscy Żydzi, którzy byli u Moabczyków, i między synami Ammonowymi, i między Edomczykami, i którzy byli we wszystkich ziemiach, usłyszawszy, że król Babiloński zostawił ostatek ludu z Judy, a iż przełożył nad nimi Godolijasza, syna Ahika ma, syna Safanowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Wrócili się więc wszyscy Żydzi ze wszystkich miejsc, do których byli zagnani, i przyszli do ziemi Judzkiej do Godolijasza do Masfy, i nazbierali wina, i letniego owocu bardzo wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Ale Johanan, syn Kareaszowy, i wszyscy książęta wojsk, którzy byli w polu, przyszli do Godolijasza do Masfy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'I rzekli do niego: Wieszże o tem, że Baalis, król synów Ammonowych, posłał Izmaela, syna Natanijaszowego, aby cię zabił? Ale im nie uwierzył Godolijasz, syn Ahikama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Nadto Johanan, syn Kareaszowy, rzekł do Godolijasza potajemnie w Masfie, mówiąc: Niech idę, proszę, a zabiję Izmaela, syna Natanijaszowego, wszak się o tem nikt nie dowie.Przeczby cię miał zabić, a rozproszeniby mieli być wszyscy Żydowie, którzy się zebrali do ciebie, i zginąć ostatek z Judy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Ale Godolijasz, syn Ahikamowy, rzekł do Johanana, syna Kareaszowego: Nie czyń tego; bo ty nieprawdę mówisz o Izmaelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'I stało się miesiąca siódmego, że przyszedł Izmael, syn Natanijasza, syna Elisamowego, z nasienia królewskiego, i hetmani królewscy, to jest, dziesięć mężów z nim, do Godolijasza, syna Ahikamowego, do Masfy, i jedli tam społu chleb w Masfie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Potem wstawszy Izmael, syn Natanijaszowy, i dziesięć mężów, którzy z nim byli, zabili Godolijasza, syna Ahikama, syna Safanowego, mieczem; zabili mówię tego, którego był przełożył król Babiloński nad oną ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Wszystkich także Żydów, którzy byli z nim, z Godolijaszem w Masfie, i onych Chaldejczyków, których tam znalazł, mężów walecznych, pobił Izmael.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'A dnia wtórego, gdy zabił Godolijasza, (o czem nikt nie zwiedział.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Przyszli niektórzy z Sychem, z Sylo, i z Samaryi, mężów ośmdziesiąt, ogoliwszy brody, i rozdarłszy szaty, i podrapawszy się, którzy ofiarę śniedną, i kadzidło w rękach swych mieli, aby je odnieśli do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Tedy Izmael, syn Natanijaszowy, wyszedł przeciwko nim z Masfy, a idąc szedł i płakał; a gdy się spotkał z nimi, rzekł do nich: Pójdźcie do Godolijasza, syna Ahikamowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Ale gdy przyszli w pośród miasta, pobił ich Izmael, syn Natanijaszowy, i wrzucił ich w dół, sam i mężowie, którzy z nim byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Lecz się dziesięć mężów znalazło między nimi, którzy rzekli do Izmaela: Nie zabijaj nas, bo mamy skarby skryte w polu, pszenicy i jęczmienia, i oliwy, i miodu. I pohamował się; a nie zabił ich między braćmi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'A dół, do którego Izmael wrzucił do Godolijasza wszystkie trupy onych mężów, których pobił, ten jest, który uczynił król Aza, bojąc się Baazy, króla Izraelskiego, który napełnił Izmael syn Natanijaszowy pobitymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'I pobrał w niewolę Izmael wszystkie ostatki ludu, które były w Masfie, córki królewskie, i wszystek lud, który był został w Masfie, które był poruczył Nabuzardan, hetman żołnierski, Godolijaszowi, synowi Ahikamowemu, i wziął je w pojmanie Izmael, syn Natanijaszowy, i poszedł uchodząc do synów Ammonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Wtem usłyszał Johanan, syn Kareaszowy, i wszyscy hetmani owych wojsk, którzy byli z nim, o tem wszystkiem złem, które uczynił Izmael, syn Natanijaszowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'I wzięli wszystek swój lud, i ciągnęli, aby zwiedli bitwę z Izmaelem, synem Natanijaszowym, którego znaleźli u wód wielkich, które są w Gabaon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'A gdy ujrzał wszystek lud, który był z Izmaelem, Johanana, syna Kareaszowego, i wszystkich książąt wojsk, którzy z nim byli, uradowali się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'A obróciwszy się wszystek on lud, który był wziął w niewolę Izmael z Masfy, wrócił się zasię, a przyszedł do Johanana, syna Kareaszowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Ale Izmael, syn Natanijaszowy, uszedł z ośmioma mężami przed Johananem, i przyszedł do synów Ammonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Przetoż wziął Johanan, syn Kareaszowy, i wszyscy książęta wojsk, którzy z nim byli, wszystek ostatek ludu, który zaś przywiódł od Izmaela, syna Natanijaszowego, z Masfy, gdy zabił Godolijasza, syna Ahikamowego, mężów walecznych, i niewiasty, i dziatki, i komorników, których zaś przywiódł z Gabaonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'A odszedłszy pomieszkali w gospodzie Chimchamowej, która jest u Betlehemu, aby idąc uszli do Egiptu przed Chaldejczykami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'Bo się ich bali, przeto, że był zabił Izmael, syn Natanijaszowy, Godolijasza,syna Ahikamowego,którego był przełożył król Babiloński nad oną ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Potem przystąpili wszyscu książęta wojsk, i Johanan, syn Karyjaszowy, i Jasanijasz, syn Hosajaszowy, i wszystek lud od małego aż do wielkiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'I rzekli do Jeremijasza proroka:Niech przyjdzie proszę prośba nasza przed oblicze twoje, a módl się za nami Panu, Bogu twemu, za wszystek ten ostatek; bo nas mało zostało z wielu, jako to widzisz oczyma twemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'A niech nam oznajmi Pan, Bóg twój, drogę, którąbyśmy chodzić, i cobyśmy czynić mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'I rzekł do nich Jeremijasz prorok: Słyszę; oto ja modlić się będę Panu, Bogu waszemu, według słów waszych, a cokolwiek wam Pan odpowie, oznajmię wam, nie zataję nic przed wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Oni zaś rzekli do Jeremiasza: Niech będzie Pan między nami świadkiem prawdziwym i wiernym, jeźli nie uczynimy według każdego słowa, z którem cię pośle Pan, Bóg twój, do nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Bądź dobrze bądź źle, głosu Pana, Boga naszego, dla którego cię posyłamy do niego, usłuchamy, aby się nam dobrze działo, gdy będziemy słuchać głosu Pana, Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'A po wyjściu dziesięciu dni, gdy się stało słowo Pańskie do Jeremijasza,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Zawołał Johanana, syna Karejaszowego, i wszystkich książąt wojsk, którzy z nim byli, i wszystkiego ludu, od małego aż do wielkiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'I rzekł do nich: Tak mówi Pan, Bóg Izraelski, do któregoście mię posłali, abym przedłożył prośbę waszą przed obliczem jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Jeźli się nawrócicie, i zostaniecie w tej ziemi, zaiste pobuduję was, a nie zepsuję, i wszczepię was, a nie wykorzenię; bo mi żal tego złego, którem wam uczynił. Nie bójcież się oblicza króla Babilońskiego, którego się wy boicie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Nie bójcie się go, mówi Pan; bom jest z wami, abym was wybawił i wyrwał was z ręki jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Nadto zjednam wam łaskę, aby się zmiłował nad wami, i dał się wam wrócić do ziemi waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Ale rzeczecieli: Nie zostaniemy w tej ziemi, nie słuchając głosu Pana, Boga waszego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'A mówiąc: Żadną miarą; ale do ziemi Egipskiej pójdziemy, gdzie nie ujrzymy wojny, ani głosu trąby nie usłyszymy, a chleba łaknąć nie będziemy, i tam mieszkać będziemy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'Przetoż teraz słuchajcie słowa Pańskiego, ostatki Judzkie! Tak mówi Pan zastępów, Bóg Izraelski: Jeźli wy upornie przy tem zostaniecie, abyście szli do ziemi Egipskiej, a pójdziecieli, abyście tam mieszkali:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'Tedy was pewnie miecz, którego się boicie, tam w ziemi Egipskiej doścignie; i głód, którego się obawiacie, tam przyjdzie na was w Egipcie, i tam pomrzecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Takci się stanie tym wszystkim mężom, którzy się na to koniecznie udali iść do Egiptu, aby tam pielgrzymowali, że pomrą od miecza, od głodu i od moru, a żaden z nich nie zostanie, ani kto ujdzie przed tem złem, które ja przywiodę na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Bo tak mówi Pan zastępów, Bóg Izraelski: Jako się wylała popędliwość moja i gniew mój na obywateli Jeruzalemskich, tak się wyleje zapalczywość moja na was, gdy wnijdziecie do Egiptu; i będziecie na przeklinanie, i na zdumienie i na złożeczenie i na hańbę, a nie oglądacie więcej miejsca tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Do wasci mówi Pan, o ostatki Judzkie! Nie wchodźcie do Egiptu; wiedzcie wiedząc, (bo się dziś oświadczam przeciwko wam,)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Ponieważeście zwiedli dusze wasze, posławszy mię do Pana, Boga waszego, mówiąc: Módl się za nami Panu, Bogu naszemu, a według wszystkiego, cokolwiek powie Pan, Bóg nasz, tak nam oznajmij, a my uczynimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'A gdy wam to dziś oznajmuję, wszakże nie słuchacie głosu Pana, Boga waszego, we wszystkiem, o co mię do was posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Przetoż mówię: Wiedzcie wiedząc, że mieczem, głodem i morem pomrzecie na tem miejscu, do którego pragniecie wnijść, abyście tam pielgrzymowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'A gdy przestał Jeremijasz mówić do wszystkiego ludu wszystkich słów Pana, Boga ich, z któremi go był posłał Pan, Bóg ich, do nich, wszystkich mówię tych słów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Rzekł Azaryjasz syn Hosajaszowy i Johanan, syn Karejaszowy, i wszyscy mężowie pyszni, mówiąc do Jeremijasza: Kłamstwo ty powiadasz; nie posłał cię Pan, Bóg nasz, mówiąc: Nie chodźcie do Egiptu, abyście tam mieszkali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Ale Baruch, syn Neryjaszowy, podszczuwa cię przeciwko nam, aby nas wydał w ręce Chaldejczyków, żeby nas pobili, albo nas zabrali do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'I nie usłuchał Johanan, syn Karejaszowy, i wszyscy książęta wojsk, także i wszystek lud głosu Pańskiego, żeby zostali w ziemi Judzkiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Ale Johanan, syn Karejaszowy, i wszyscy książęta wojsk wzięli wszystek ostatek z Judy, którzy się byli wrócili ze wszystkich narodów, do których byli wygnani, aby, mieszkali w ziemi Judzkiej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Mężów, i niewiasty, i dzieci, i córki królewskie, i każdą duszę, którą Nabuzardan, hetman żołnierski, z Godolijaszem, synem Ahikamowym, syna Safanowego, zostawił, i z Jeremijaszem prorokiem, i z Baruchem, synem Neryjaszowym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'I weszli do ziemi Egipskiej, bo nie byli posłuszni głosowi Pańskiemu, i przyszli do Tachpanches.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'I stało się słowo Pańskie do Jeremijasza w Tachpanchos, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Nabierz w ręce swe kamieni wielkich, a skryj je w glinę w cegielnicy, która jest przed bramą domu Faraonowego w Tachpanches, przed oczyma mężów Judzkich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'A rzecz im: Tak mówi Pan zastępów, Bóg Izraelski: Oto Ja poślę i przywiodę Nabuchodonozora, króla Babilońskiego, sługę mego i postawię stolicę jego na tych kamieniach, którem skrył: i rozbije majestat swój na nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Bo przyciągnąwszy wytraci ziemię Egipską; którzy na śmierć oddani, na śmierć pójdą, a którzy do więzienia, do więzienia, a którzy pod miecz, pod miecz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'I zapalę ogień w domach bogów Egipskich, i popali je, a one pobierze do więzienia: i odzieje się ziemią Egipską jako się odziewa pasterz szatą swoją, i wynijdzie stamtąd w pokoju,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Gdy pokruszy słupy w Betsemes, które jest w ziemi Egipskiej, i domy bogów Egipskich popali ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Słowo, które się stało do Jeremijasza o wszystkich Żydach, którzy mieszkali w ziemi Egipskiej, którzy mieszkali w Migdolu, i w Tachpanches, i w Nof, i w ziemi Patros, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Tak mówi Pan zastępów, Bóg Izraelski: Wyście widzieli wszystko ono złe, którem przywiódł na Jeruzalem, i na wszystkie miasta Judzkie, że oto puste są po dziś dzień, niemasz w nich obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Dla złości ich, którą czynili, aby mię do gniewu pobudzali, chodząc kadzić i służyć Bogom cudzym, których nie znali sami, wy i ojcowie wasi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Chociażem posyłał do was wszystkich sług moich, proroków, rano wstawając i posyłając a mówiąc: Nie czyńcie proszę tej obrzydliwości, której nienawidzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Ale nie usłuchali ani nakłonili ucha swego, aby się odwrócili od złości swojej, a nie kadzili bogom cudzym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Przetoż wylany jest gniew mój, a zapalczywość moja zapaliła się w miastach Judzkich, i w ulicach Jeruzalemskich, i obróciły się w pustynie, i wzburzenie, jako się to dziś pokazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Teraz tedy tak mówi Pan, Bóg zastępów, Bóg Izraelski: Czemu wy czynicie tę złość wielką przeciwko duszom waszym, aby z was był wykorzeniony mąż i niewiasta, dziecię i ssący z pośrodku Judy, tak, żeby z was nic nie zostało,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Draźniąc mię sprawami rąk waszych, kadząc bogom cudzym w ziemi Egipskiej, do którejście weszli, abyście tam pielgrzymowali, iżbyście byli wykorzenieni, a byli na przeklęstwo i na hańbę u wszystkich narodów na ziemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Azaście zapamiętali na złość ojców waszych, i na złość królów Judzkich, i na złość żon ich, i na złości wasze, i na złości żon waszych, których się dopuściły w ziemi Judzkiej i po ulicach Jeruzalemskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Nie upokorzyli się aż do dnia tego, i nie bali się, ani chodzili w zakonie moim i w ustawach moich, które podaję wam i ojcom waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Przetoż tak mówi Pan zastępów, Bóg Izraelski: Oto Ja obrócę oblicze moje przeciwko wam na złe, aby wykorzenił wszystkiego Judę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Wygubię zaiste ostatki Judzkie, którzy upornie weszli do ziemi Egipskiej, aby tam pielgrzymowali, tak, że zniszczeją wszyscy w ziemi Egipskiej, polegną od miecza, od głodu zniszczeją od najmniejszego aż do największego, od miecza i od głodu pomrą; nadto będą na przeklinanie, i na zdumienie, i na złoszczenie, i na hańbę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Bo nawiedzę tych, którzy mieszkają w ziemi Egipskiej, jakom nawiedził Jeruzalem mieczem, głodem i morem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'I nie będzie ktoby uszedł i został z ostatków Judzkich, którzy weszli do ziemi Egipskiej, aby tam pielgrzymowali, aby się zaś wrócić mieli do ziemi Judzkiej, do której się oni pragną wrócić, i mieszkać tam; ale się nie wrócą, tylko ci, którzy ujdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Tedy odpowiedzieli Jeremijaszowi wszyscy mężowie, którzy wiedzieli, iż kadzały żony ich bogom cudzym, one wszystkie niewiasty, których stało mnóstwo wielkie, i wszystek lud, który mieszkał w ziemi Egipskiej w Patros, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'W słowie, któreś mówił do nas imieniem Pańskiem, nie usłuchały cię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Ale dosyć czynimy każdemu słowu, które wynijdzie z ust naszych, kadząc królowej niebieskiej, i sprawując jej ofiary mokre, jakośmy czynili, my i ojcowie nasi, królowie nasi, i książęta nasi w miastach Judzkich i po ulicach Jeruzalemskich, a najad aliśmy się chleba, i dobrze nam było, a nic złegośmy nie widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Ale odtąd jakośmy przestali kadzić królowej niebieskiej, i sprawować jej ofiary mokre, na wszystkiem nam schodzi, a od miecza i od głodu niszczejemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'A gdy kadzimy królowej niebieskiej, i sprawujemy jej ofiary mokre, izali jej bez mężów naszych placki czynimy, kształtując ją, i sprawując jej ofiary mokre?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Tedy rzekł Jeremijasz do wszystkiego ludu, do mężów i do niewiast, i do wszystkiego pospólstwa, którzy mu tak odpowiedzieli, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Izali na kadzenie, któremeście kadzili w miastach Judzkich i w ulicach Jeruzalemskich, wy i ojcowie wasi, królowie wasi, i książęta wasi, i lud ziemi, nie wspomniał Pan, i nie wstąpiło to na serce jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Tak, że nie mógł Pan dalej znosić złości spraw waszych, i obrzydliwości, któreście broili; dlatego się stała ziemia wasza spustoszeniem i zdumieniem, i przeklęstwem, tak, że niemasz w niej obywatela, jako się to dziś pokazuje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Dlatego, żeście kadziili bałwanom, i żeście grzeszyli przeciw Panu, a nie słuchaliście głosu Pańskiego, a tak w zakonie jego, i w ustawach jego, ani w świadectwach jego nie chodziliście, dlatego przyszło na was to złe, jako się to dziś pokazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Nadto rzekł Jeremijasz do wszystkiego ludu, i do wszystkich niewiast: Słuchajcie słowa Pańskiego wszyscy ludzie Judzcy, którzyście z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Tak rzekł Pan zastępów, Bóg Izraelski, mówiąc: Wy i żony wasze mówiliście usty swemi, i wypełniliście rękami swemi, mówiąc: Uczynimy dosyć ślubom naszym, któreśmy poślubili, abyśmy kadzili królowej niebieskiej, i sprawowali jej ofiary mokre, a tak wszystką siłą wypełniacie śluby wasze, i samym skutkiem wykonywacie śluby wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Przetoż słuchajcie słowa Pańskiego wszyscy ludzie Judzcy, którzy mieszkacie w ziemi Egipskiej: Oto Ja przysięgam przez imię moje wielkie, mówi Pan, że nie będzie więcej imię moje wzywane usty żadnego męża Judzkiego po wszystkiej ziemi Egipskiej, któryby rzekł: Jako żyje panujący Pan!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Oto Ja będę czuł nad nimi na złe, a nie na dobre; i niszczeć będą wszyscy mężowie Judzcy, którzy są w ziemi Egipskiej, mieczem i głodem, aż do szczętu wyginą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'A którzy ujdą miecza, wrócą się z ziemi Egipskiej do ziemi Judzkiej, ludu mały poczet; i pozna wszystek ostatek Judzki, którzy weszli do ziemi Egipskiej, aby tam pielgrzymowali, czyje się słowo ostoi, mojeli, czyli ich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'A to miejcie za znak, mówi Pan, że Ja was nawiedzę na tem miejscu, abyście wiedzieli, iż się prawdziwie spełnią słowa moje nad wami ku złemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Tak mówi Pan: Oto Ja podam Faraona Chofra, króla Egipskiego, w rękę nieprzyjaciół jego, i w rękę szukających duszy jego, jakom podał Sedekijasza, króla Judzkiego, w rękę Nabuchodonozora, króla Babilońskiego, nieprzyjaciela jego, który szukał duszy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Słowo, które mówił Jeremijasz prorok do Barucha, syna Neryjaszowego, gdy pisał te słowa w księgi z ust Jeremijaszowych roku czwartego za Joakima, syna Jozyjasza, króla Judzkiego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Tak mówi Pan, Bóg Izraelski, o tobie, Baruchu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Rzekłeś: Biada mnie teraz! bo Pan przyczynia żałości do bolaści mojej; upracowałem się w wzdychaniu mojem, a odpoczynku nie znajduję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Tak rzeczesz do niego: Tak mówi Pan: Oto com zbudował, Ja rozwalam, a com wszczepił, Ja wyrywam, i tę wszystkę ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'A ty sobie szukasz rzeczy wielkich? Nie szukaj. Bo oto Ja przywiodę złe na wszelkie ciało, mówi Pan: ale tobie dam duszę twoję w korzyści na wszelkich miejscach, dokądkolwiek pójdziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Słowo Pańskie, które się stało do Jeremijasza proroka przeciwko tym narodom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Przeciwko Egiptowi. Przeciwko wojsku Faraona Necha, króla Egipskiego, (które było nad rzeką Eufrates u Karchemis, które poraził Nabuchodonozor, król Babiloński) roku czwartego Joakima, syna Jozyjaszowego, króla Judzkiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Gotujcie tarcz i pawężę, a wychodźcie na wojnę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Zaprzęgajcie konie, a wsiadajcie jezdni, stańcie w hełmach, wycierajcie oszczepy, obleczcie się w pancerze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Czemuż tych widzę zatrwożonych, tył podawających, a mocarzy ich startych i prędko uciekających, tak, że się ani oglądają? Strach jest zewsząd, mówi Pan,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Aby nie uciekł prędki, a nie uszedł mocarz; aby się na północy o brzeg rzeki Eufrates otrącili i upadli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Któż to jest, który jako rzeka wzbiera? Którego się wody wzruszają jako rzeki?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egipt jako rzeka wzbiera, a jego wody wzruszają się jako rzeki, i mówi: Pociągnę, okryję ziemię, wygubię miasto, i tych, co w niem mieszkają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Poskoczcie konie, a zagrzmijcie wozy, a niech się ruszą i mocarze, Murzynowie, i Putejczycy noszący tarcz, i Ludymczycy, którzy noszą i ciągną łuk,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Bo ten dzień panującego Pana zastępów będzie dzień pomsty, aby się pomścił nad nieprzyjaciołmi swymi, których miecz pożre, a nasyci się, i opije się krwią ich; bo ofiara panującego Pana zastępów będzie w ziemi północnej u rzeki Eufrates.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Wstąp do Galaad, a nabierz soku balsamowego, panno, córko Egipska! Aleć próżno używasz wiele lekarstw; bo nie będziesz uleczona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Narody usłyszą o sromocie twojej, a narzekanie twoje napełniło ziemię; bo mocarz na mocarza natarł, tak, że społem oba upadają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Słowo, które mówił Pan do Jeremijasza, proroka, o tem, że ma przyjść Nabuchodonozor, król Babiloński, a porazić ziemię Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Oznajmijcie w Egipcie, a rozgłoście w Migdolu; opowiadajcie także w Nof, i w Tachpanches; rzeczcie: Postuj a nagotuj się; wszakże miecz pożre to, co jest około ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Przecz porażony jest każdy z mocarzów twoich? Nie może się ostać, przeto, że Pan natarł nań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Wieleć będzie tych, którzy poszwankują a padną jeden na drugiego, i rzeką: Wstań, a wróćmy się do ludu naszego, i do ziemi urodzenia naszego przed ostrzem miecza pustoszącego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Tam będą wołać: Farao, król Egipski, jest tylko próżny trzask, już mu pominął czas postanowiony,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Jakom żywy Ja, mówi król, Pan zastępów imię jego; że jako Tabor między górami, i jako Karmel przy morzu, tak to przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Spraw sobie naczynie przeprowadzenia, obywatelko, córko Egipska! bo Nof pustynią będzie i spustoszeje, i będzie bez obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Egipt jest jako piękna jałowica; ale zabicie jej od północy idzie, idzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Więc i najemnicy jego w pośrodku niego są jako ciele utuczone, ale i oni także obróciwszy się uciekną społem, nie ostoją się; bo dzień porażki ich przyszedł na nich, czas nawiedzenia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Głos jego wynijdzie jako wężowy; bo z wojskiem idą, a z siekierami przyjdą nań, jako ci, co wyrąbują drzewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Wyrąbią las jego, mówi Pan, choć policzony być nie może; bo się nad szarańczę rozmnożyli, i niemasz im liczby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Zawstydzi się córka Egipska; podana będzie w rękę ludu północnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Pan zastępów, Bóg Izraelski, mówi: Oto Ja nawiedzę ludne miasto No, także Faraona i Egipt, i bogów jego, i królów jego, Faraona mówię, i tych, którzy w nim ufają:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'I podam ich w rękę tych, którzy szukają duszy ich, to jest w rękę Nabuchodonozora, króla Babilońskiego, i ręką sług jego; lecz potem mieszkać w nim będą, jako za dawnych dni, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Ale się ty nie bój, sługo mój Jakóbie! a nie lękaj się, o Izraelu! Bo oto Ja ciebie wybawię z daleka, i nasienie twoje z ziemi pojmania ich; i wróci się Jakób, aby odpoczywał i aby miał pokój, a nie będzie, ktoby go postraszył;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Ty, mówię, Jakóbie, sługo mój! nie bój się, mówi Pan; bom Ja z tobą. Uczynię zaiste koniec wszystkim narodom, do których cię wypędzę; lecz tobie nie uczynię końca, ale cię miernie karać będę, a cale cię bez karania nie zostawię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Słowo Pańskie, które się stało do Jeremijasza proroka przeciwko Filistyńczykom, przedtem, niż Farao dobił Gazy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Tak mówi Pan: Oto wody występują od północy, i będą jako powódź gwałtowna, a zatopią ziemię i co jest na niej, miasto i mieszkających w niem, dlaczego wołać będą ludzie, i zawyją wszyscy obywatele ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Dla głosu tętnienia kopyt waśniwych koni jego, dla grzmotu wozów jego, i trzasku kół jego nie obejrzą się ojcowie na synów, mając opuszczone ręce;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'Dla dnia, który przyjść ma na zburzenie wszystkich Filistyńczyków, i na wykorzenienie Tyru i Sydonu ze wszystką pozostałą pomocą; bo zburzy Pan Filistyńczyków, ostatek wyspy Kaftor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Przyjdzie obłysienie na Gazę, i wykorzeniony będzie Aszkalon i ostatki doliny ich; dokądże się rzezać będziesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'O mieczu Pański, dokąd się nie uspokoisz? Wróć się do pochew twoich, uśmierz się, a ucichnij.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Ale jakożbyś się uspokoił? Wszak mu Pan przykazał; przeciwko Aszkalonowi i przeciwko brzegowi morskiemu, tam go postawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Przeciwko Moabowi. Tak mówi Pan zastępów, Bóg Izraelski: Biada miastu Nebo, bo spustoszone będzie; pohańbione i wzięte będzie Karyjataim; zawstydzone będzie miasto na miejscu wysokiem, i bać się będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Nie będzie się więcej chlubił Moab z Hesebonu; myślą złe przeciwko niemu, mówiąc: Pójdźcie, a wytraćmy ich z narodu. I ty, Madmenie! wykorzeniony będziesz, miecz pójdzie za tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Głos krzyku z Choronaim: O spustoszenie i zburzenie wielkie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Starty będzie Moab, słyszany będzie krzyk maluczkich jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Przeto, że na drodze Luchytskiej będzie ustawiczny płacz, a którędy zstępują do Choronaim, nieprzyjaciele krzyk zburzenia słyszeć będą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Mówiących: Uciekajcie, wybawcie duszę swoję, a stańcie się jako wrzos na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Bo dlatego, że masz nadzieję w dostatku twoim, i w skarbach twoich, będziesz też wzięte, i Chamos pójdzie w pojmanie, kapłani jego, także i książęta jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Bo burzyciel przyjdzie na każde miasto, a żadne miasto nie ujdzie; zginie i dolina, i równiny spustoszone będą, jako mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Dajcie skrzydła Moabowi, niech prędko uleci; bo miasta jego przyjdą w spustoszenie, tak, że nie będzie w nich obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Przeklęty, kto zdradliwie czyni sprawę Pańską; przeklęty także, kto hamuje miecz swój ode krwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Miałci Moab pokój od dzieciństwa swego, i usadził się na drożdżach swoich, ani był przelewany z naczynia w naczynie, to jest, w pojmanie nie chodził, dla czego został w nim smak jego, a woń jego nie zmieniła się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Przetoż oto dni idą, mówi Pan, że poślę nań tych, którzy wtargnienia czynią, a pojmają go, i naczynia jego wypróżnią, a łagwie jego potłuką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'I zawstydzony będzie Moab od Chamosa, jako zawstydzony jest dom Izraelski od Betel, nadziei swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Jakoż mówicie: Mocniśmy, a mężowie duży do boju?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Zburzony będzie Moab, i z miast swoich wynijdzie, a wyborni młodzieńcy jego pójdą na zabicie, mówi król, Pan zastępów imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Blisko jest zginienie Moabowe, i przyjdzie; a nieszczęście jego prędko się pospieszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Użalcie się go wszyscy, którzy mieszkacie około niego, i wszyscy, którzy znacie imię jego, mówcie: Jakoż się złamała laska mocy, i kij ozdobny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Zstąp z sławy, a siądź w pragnieniu, obywatelko, córko Dybońska! bo zburzyciel Moabu przyciągnie przeciwko tobie, rozrzuci twierdze twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Stań na drodze a przypatrz się pilnie, obywatelko Aroer! pytaj tego, który ucieka, i tej, która uchodzi, mówiąc: Co się dzieje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Zawstydzony jest Moab, bo jest potarty; narzekajcie a wołajcie, opowiadajcie w Arnon, że pustoszą Moaba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Bo sąd przyszedł na ziemię tej równiny, na Holon, i na Jassa, i na Mefaat,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'I na Dybon, i na Nebo, i na Bet Dyblataim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'I na Kiryjataim, i na Betgamul, i Betmehon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'I na Karyjot, i na Bocrę, i na wszystkie miasta ziemi Moabskiej, dalekie i bliskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Odcięty będzie róg Moabski, i ramię jego będzie starte, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Opójcie go, ponieważ się przeciw Panu podniósł; niech się wala Moab w blwocinach swoich, niech będzie i on na pośmiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Bo azaż w pośmiewisku nie był u ciebie Izrael? Izali go między złodziejami zastano? że, ilekroć mówisz o nim, wyskakujesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Opuszczajcie miasta a mieszkajcie na skale, obywatele Moabscy! a bądźcie jako gołębica, która ściele gniazdo swoje na kraju dziury.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Słyszeliśmy o pysze Moabowej, że jest bardzo pyszny; o wysokomyślności jego, i o hardości jego, i o nadętości jego, i o wyniosłości serca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Znamci Ja, mówi Pan, zagniewanie jego; lecz nie ma siły; kłamstwa jego nie dowiodą tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Dlatego nad Moabczykami narzekam, a nade wszystkim Moabem wołam, a dla obywateli Kircheres wzdycha serce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Bardziej niż płakano Jazerczyków, płaczę nad tobą, o winna macico Sabama! Latorośli twoje dostaną się za morze, aż do morza Jazer dosięgną; na letnie owoce twoje, i na zbieranie wina twego burzyciel przypadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'I ustanie wesele i radość nad polem urodzajnem w ziemi Moabskiej, a winu z prasy wstręt uczynię; nie będą go tłoczyć z wykrzykaniem, a wykrzykanie nie będzie wykrzykaniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Bardziej krzyczeć będą niż Hesebończycy; aż do Eleale, aż do Jazy wydadzą głos swój, od Zoar aż do Choronaim, jako jałowica trzecioletnia; bo też i wody Nimrym zniszczeją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'I uczynię, mówi Pan, że ustanie w Moabie ofiarujący na wyżynach, i kadzący bogom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Przetoż serce moje nad Moabem jako piszczałki piszczeć będzie; także nad obywatelami w Kircheres serce moje jako piszczałki piszczeć będzie, i dlatego, że i zboże zgromadzone wniwecz się obróci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Bo na każdej głowie będzie łysina, i każda broda ogolona będzie; na wszystkich rękach będą szramy, a na biodrach wór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Po wszystkich dachach Moabskich i po ulicach jego, wszędy nic nie będzie, tylko narzekanie; bom skruszył Moaba jako naczynie nieużyteczne, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Narzekać będą, mówiąc: Jakoć jest starty! Jako tył podał Moab z hańbą! i jest Moab pośmiewiskiem, i postrachem wszystkim, którzy są około niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Bo tak mówi Pan: Oto nieprzyjaciel jako orzeł przyleci, a rozciągnie skrzydła swe na Moaba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Karyjot wzięte będzie, i zamki wzięte będą, a serce mocarzów Moabskich dnia onego będzie jako serce niewiasty bolejącej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'I wygładzony będzie Moab z ludu; bo się przeciwko Panu podnosił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Strach i dół, i sidło nad tobą, o obywatelu Moabski! mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Kto uciecze przed strachem, wpadnie w dół; a kto wynijdzie z dołu, sidłem ułapiony będzie; bo przywiodę nań, to jest na Moaba, rok nawiedzienia jego, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'W cieniu Hesebon stawali ci, którzy uciekali przed gwałtem; ale ogień wynijdzie z Hesebonu, i płomień z pośrodku Sehonu, i pożre kąt Moabski, i wierzch głowy tych, którzy go burzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Biada tobie, Moabie!zaginieć lud Chamosowy; bo synowie twoi zabrani będą w niewolę, i córki twoje do więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Wszakże zasię przywrócę więźniów Moabskich w ostateczne dni, mówi Pan. Aż dotąd sąd o Moabie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Przeciwko synom Amonowym. Tak mówi Pan: Izali Izrael nie ma synów? Izali żadnego dziedzica nie ma? czemuż król ich dziedzicznie opanował Gad, a lud jego czemu mieszka w miastach jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Przetoż oto dni idą, mówi Pan, sprawię, że usłyszą trąbienie wojenne przeciwko Rabbie synów Amonowych, i będzie obrócona w kupę rumu, a inne miasta jego ogniem spalone będą, i posiędzie Izrael dzierżawców swoich, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Rozrzewnij się, Hesebonie! bo Haj spustoszone będzie; krzyczcie, o córki Rabby! przepaszcie się worami, narzekajcie, a tułajcie się około płotów; bo król wasz do więzienia pójdzie, także kapłani jego, i książęta jego społem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Cóż się przechwalasz dolinami? Spłynęła dolina twoja, o córko uporna! która ufasz w skarbach twoich, mówiąc: Któż przyciągnie przeciwko mnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Oto Ja przywiodę na cię strach, mówi Pan, Pan zastępów od wszystkich, którzy są około ciebie, przez który rozegnani będziecie jeden od drugiego, a nie będzie, ktoby zebrał tułających się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Wszakże potem przywiodę zaś więźniów synów Amonowych, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Przeciwko Edomczykom. Tak mówi Pan zastępów: Izali niemasz więcej mądrości w Teman? Izali zginęła rada od roztropnych, a wniwecz się obróciła mądrość ich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Uciekajcie, obróćcie się, zstąpcie w głębokość na mieszkanie, obywatele Dedan! bo przywiodę zatracenie na Ezawa czasu nawiedzenia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Gdyby ci, którzy zbierają wino, przyszli na cię, izaliby nie zostawili jakich gron? gdyby się wkradli złodzieje w nocy, azażby szkodzili więcej nad potrzebę swoję?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Lecz Ja obnażę Ezawa, odkryję skrytości jego, tak, iż się ukryć nie będzie mógł: zniszczone będzie nasienie jego, i bracia jego, i sąsiedzi jego, tak, że zgoła nie będzie, ktoby rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Zaniechaj sierotek twoich, ja je żywić będę, a wdowy twoje we mnie ufać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Tak zaiste mówi Pan: Oto ci, którym nie przysądzono pić z kubka tego, przecie piją z niego, a tybyś miał zgoła tego ujść?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Nie ujdziesz, ale koniecznie pić będziesz; bo przez się przysięgam, mówi Pan, iż na spustoszenie, na pohańbienie, na zburzenie, i na przeklęstwo Bocra przyjdzie, i wszystkie miasta jego będą pustemi na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Słyszałem wieść od Pana, że do narodów posłany jest poseł mówiący: Zgromadźcie się, a ciągnijcie, przeciwko niemu, wstańcież do bitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Bo oto sprawię, abyś był najlichszym między narodami, i wzgardzonym miedzy ludźmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Hardość twoja zdradzi cię, i pycha serca twego, ty, który mieszkasz w rozsiadlinach skalnych, który się trzymasz wysokich pogórków; byś też wywyższył jako orzeł gniazdo swoje, i stamtąd cię stargnę, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'I będzie ziemia Edomska pustynią, i ktokolwiek pójdzie przez nię, zdumieje się, i świstać będzie nad wszystkiemi plagami jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Jako podwrócona jest Sodoma i Gomora z przyległościami swojemi, mówi Pan, tak się tam nikt nie osadzi, ani w niej syn człowieczy mieszkać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Oto aczkolwiek jako lew występuje, i bardziej niż nadęcie Jordanu się podnosi przeciwko przybytkowi Mocnego: wszakże go nagle wypędzę z tej ziemi, a tego, który jest obrany, przełożę nad nią: bo któż mnie jest podobny? i kto mi da rok; a kto jest tym pasterzem, któryby się postawił przeciwko mnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Przetoż słuchajcie rady Pańskiej, którą uradził przeciwko Edomczykom; i zamysłów jego, które umyślił przeciwko obywatelom Temańskim; zaiste żeć ich wywleką najmniejsi z tej trzody, zaiste pobudzą ich, i przybytki ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Od grzmotu upadku ich wzruszy się ziemia; głos i krzyk ich słyszeć będą na morzu Czerwonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Oto jako orzeł przypadnie i przyleci, a rozciągnie skrzydła swe nad Bocrą, i stanie się serce mocarzów z Edom dnia onego, jako serce niewiasty bolejącej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Przeciwko Damaszkowi. Zawstydzi się Emat i Arfad; bo wieść złą usłyszą, i zatrwożą się, tak że się i morze wzruszy, a nie będzie się mogło uspokoić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Osłabieje Damaszek, uda się do uciekania, a strach go ogarnie; uciski i boleści ogarną go, jako rodzącą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Ale rzeką: Jakożby się nie miało ostać miasto sławne, miasto wesela mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Przetoż upadną młodzieńcy jego na ulicach jego, a wszyscy mężowie waleczni dnia onego wytraceni będą, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'I rozniecę ogień w murze Damaszku, który strawi pałace Benadadowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Przeciwko Kiedar, i przeciwko królestwom Hasor, które wytracić ma Nabuchodonozor, król Babiloński; tak mówi Pan: Wstańcie, ciągnijcie przeciwko Kiedar, a zburzcie narody wschodnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Namioty ich i trzody ich zabiorą; opony ich ze wszystkiem naczyniem ich i wielbłądy ich wezmą ze sobą, i zawołają na nich: Strach zewsząd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Uciekajcie, rozpierzchnijcie się prędko, zstąpcie w głębokości na mieszkanie, obywatele Hasor! mówi Pan; bo zawarł radę przeciwko wam Nabuchodonozor, król Babiloński, i umyślił przeciwko wam zdradę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Wstańcie, ciągnijcie przeciwko narodowi spokojnemu, mieszkającemu bezpiecznie, mówi Pan: nie ma ani wrót, ani zawór, samotni mieszkają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Będą zaiste wielbłądy ich podane na łup, a mnóstwo dobytku ich na korzyść; i rozproszę na wszystkie wiatry tych, którzy i w najostateczniejszych kątach mieszkają, i ze wszystkich stron złe na nich przywiodę, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'I stanie się Hasor mieszkaniem smoków, pustynią aż na wieki; nie osadzi się tam nikt, ani mieszkać będzie w nim syn człowieczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Słowo Pańskie, które się stało do Jeremijasza proroka przeciwko Elamczykom na początku królowania Sedekijasza, króla Judzkiego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Tak mówi Pan zastępów: Oto ja złamię łuk Elamczyków, największą siłę ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'A przywiodę przeciwko Elamczykom cztery wiatry ze czterech stron świata, i rozproszę ich na wszystkie one wiatry, tak, iż nie będzie narodu, do któregoby się nie dostali wygnańcy z Elam;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'I zatrwożę Elamczyków przed obliczem nieprzyjaciół ich, i przed obliczem tych, którzy szukają duszy ich; przywiodę, mówię, na nich złe, gniew popędliwości mojej, mówi Pan, a posyłać za nimi będę miecz, dokąd ich nie wyniszczę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'I postawię stolicę moję między Elamczykami, a wytracę stamtąd króla i książąt, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Wszakże stanie się, że w ostateczne dni przywrócę zaś więźniów Elam, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Słowo, które mówł Pan przeciwko Babilonowi, i przeciwko ziemi Chaldejskiej przez Jeremijasza proroka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Opowiadajcie między narodami, a rozgłaszajcie, podnieście chorągiew, rozgłaszajcie, nie tajcie, mówcie: Wzięty będzie Babilon, pohańbiony będzie Bel, potarty będzie Merodach, pohańbione będą bałwany jego, pokruszeni będą plugawi bogowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Bo przyciągnie przeciwko niemu naród z północy, który ziemię jego obróci w pustynię, tak, że nie będzie, coby mieszkał w niej; tak ludzie jako i bydlęta ruszą się i odejdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'W onych dniach, i w onych czasach, mówi Pan, przyjdą synowie Izraelscy, oni i synowie Judzcy; płacząc społem ochotnie pójdą, a Pana, Boga swego, szukać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'O drodze do Syonu pytać się będą, a obuciwszy się tam twarzą, rzekną: Pójdźcie, a przyłączcie się do Pana przymierzem wiecznem, które nie przyjdzie w zapamiętanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Lud mój jest jako trzoda owiec straconych, pasterze ich zawiedli ich w błąd, po górach rozegnali ich: z góry na pagórek chodziły, zapomniawszy legowiska swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Wszyscy, którzy ich znajdują, pożerają ich, a nieprzyjaciele ich mówią: Nie będziemy nic winni, przeto, że zgrzeszyli Panu w przybytku sprawiedliwości, Panu, który jest nadzieją ojców ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Uchodźcie z pośrodku Babilonu, a z ziemi Chaldejskiej wychodzcie, i będźcie jako kozły przed trzodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Bo oto Ja wzbudzę i przywiodę na Babilon zgromadzenie narodów wielkich z ziemi północnej; którzy się uszykują przeciwko niemu, a stamtąd go wezmą; których strzały są jako mocarza osieracającego, z których żadna się nie wróci próżno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'I będzie Chaldejska ziemia na łup, a wszyscy,którzy ją złupią, nasyceni będą, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Przeto, że się weselicie, przeto, że się radujecie, rozchwytając dziedzictwo moje, przeto, żeście nabrali ciała jako jałowica utuczona, a wyskakujecie jako mocarze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Zawstydzona będzie matka wasza bardzo; zapłonie się rodzicielka wasza; oto najpośledniejszą będzie z narodów, pustą ziemią, suchą i bezdrożną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Dla gniewu Pańskiego nie bądą w niej mieszkać, ale ona wszystka obróci się w pustynię; ktokolwiek pójdzie mimo Babilonu, zdumieje się, i zaświśnie nad wszystkiemi plagami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Szykujcie wojska przeciw Babilonowi zewsząd wszyscy, co ciągniecie łuk, strzelajcie do niego, nie żałujcie strzał; bo przeciwko Panu zgrzeszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Wołajcie przeciwko niemu zewsząd; poddał się, upadły grunty jego, skażone są mury jego; bo pomsta Pańska jest. Pomścijcież się nad nim; jako on czynił innym, tak mu też uczyńcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Wytraćcie siejącego z Babilonu, i tego, który trzyma śierp czasu żniwa; przed ostrzem miecza burzącego każdy niech się do ludu swego obróci, i każdy do ziemi swojej niech uciecze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Izrael jest jako bydlądko zagnane, które lwy zapłoszyły. Król Assyryjski najpierwszy był, który go żreć począł, a ten ostateczny, Nabuchodonozor, król Babiloński, kości jego pokruszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Przetoż tak mówi Pan zastępów, Bóg Izraelski: Oto Ja nawiedzę króla Babilońskiego i ziemię jego, jakom nawiedził króla Assyryskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'I przywrócę zaś Izraela do mieszkania jego, a paść się będzie na Karmelu, i na Basanie, i na górze Efraimowej, a w Galaadzie nasycona będzie dusza jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'W onych dniach i w onych czasach, mówi Pan, będą szukać nieprawości Izraelowej, ale żadnej nie będzie; i grzechów Judzkich, ale nie będą znalezione; bo odpuszczę tym, których pozostawię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Wyciągnij przeciwko tej ziemi odpornych, przeciwko niej, mówię, a obywateli jej nawiedź; spustosz a wygładź, goniąc ich, mówi Pan; uczyńże według wszystkiego, jakoć rozkazuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Niech będzie głos wojenny w tej ziemi, i spustoszenie wielkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Jakożby posiekany i połamany być miał młot wszystkiej ziemi? Jakożby się Babilon stał zdumienie między narodami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Sidłom zastawił na cię, i będziesz pojmany, o Babilonie! nim się obaczysz; znaleziony nawet i pojmany będziesz, ponieważeś z Panem zwadę zaczął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Otworzył Pan skarb swój, a wyniósł naczynia gniewu swego; bo to jest sprawa Pana, Pana zastępów w ziemi Chaldejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Pójdźcież przeciwko niej od kończyn ziemi, otwórzcież szpichlerze jej podepczcie ją jako stogi, a wygładźcie ją tak, aby jaj nic nie zostało;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Pozabijajcie wszystkie cielce jej, niech zstępują na zabicie. Biada im! bo przyszedł dzień ich, czas nawiedzenia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Głos uciekających, i tych, co uchodzą, z ziemi Babilońskiej, aby oznajmili na Syonie pomstę Pana, Boga naszego, pomstę kościoła jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Zgromadzcie przeciwko Babilonowi wszystkich strzelców, którzy łuk ciągną; połóżcie się obozem przeciw niemu w około, aby nikt nie uszedł; oddajcie mu według spraw jego, według wszystkiego, co innym czynił, uczyńcie mu; bo się przeciwko Panu wynosił, przeciwko Świętemu Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Przetoż polegną młodzieńcy jego na ulicach jego, i wszyscy mężowie waleczni jego wygładzeni będą dnia onego, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Otom ja przeciwko tobie, o hardy! mówi Pan, Pan zastępów; bo już przyszedł dzień twój i czas, abym cię nawiedził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Potknie się zaiste hardy, i upadnie, a nie będzie, ktoby go podniósł; i rozniecę ogień w miastach jego, który pożre wszystko około niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Tak mówi Pan zastępów: Gwałt się dzieje synom Izraelskim i synom Judzkim społem, a wszyscy, którzy ich pojmali, trzymają ich, nie chcą ich puścić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Ale odkupiciel ich możny, Pan zastępów imię jego, pewnie że się ujmie o krzywdę ich, aby sprawił pokój tej ziemi, i poruszył obywateli Babilońskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Miecz przyjdzie na Chaldejczyków, mówi Pan, i na obywateli Babilońskich, i na książąt jego, i na mędrców jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Miecz na kłamców, aby zgłupieli, miecz na mocarzy jego, aby skruszeni byli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Miecz na konie jego, i na wozy jego, i na wszystko pospólstwo, które jest w pośrodku jego, aby byli jako niewasty; miecz na skarby jego, aby były rozchwycone;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Susza na wody jego, aby wyschły; bo ziemia jest pełna obrazów rytych, a przy bałwanach swoich szaleją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Przeto tam mieszkać będą bestyje i straszne zwierzęta, mieszkać w nim będą młode sowy; a nie będą w nim mieszkać więcej na wieki, i nie będą w nim mieszkać od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Jako Pan podwrócił Sodomę i Gomorę, i przyległości ich, mówi Pan, tak się tam nikt nie osadzi, ani będzie mieszkał w niej syn człowieczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Oto lud przyciągnie od północy, i naród wielki, i królowie wielcy wzbudzeni będą ze stron ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Łuk i włóczni pochwycą, okrutnymi będą, a nie zmiłują się; głos ich jako morze zaszumi, a na koniach pojadą, uszykowani jako mąż do bitwy przeciwko tobie, o córko Babilońska!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Jako usłyszy król Babiloński wieść o nich, osłabieją ręce jego, a ucisk ogarnie go, i boleść jako rodzącą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Oto aczkolwiek jako lew występuje, i bardzej niż nadętość Jordanu się podnosi przeciwko przybytkowi mocnego, wszakże go w okamgnieniu wypędzę z niej, a tego, który jest wybrany, przełożę nad nią; bo któż jest mnie podobnym; i kto mi da rok? a kto jest tym pasterzem, któryby się postawił przeciwko mnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Przetoż słuchajcie rady Pańskiej, którą uradził przeciwko Babilonowi; i zamysłów jego, które umyślił przeciwko ziemi Chaldejskiej; zaiste żeć ich wywloką najmniejsi z tej trzody, zaiste poburzą ich i przybytek ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Od huku przy dobywaniu Babilonu poruszy się ta ziemia, a krzyk między narodami słyszany będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Tak mówi Pan: Oto Ja wzbudzę przeciwko Babilonowi, i przeciwko tym, którzy mieszkają w pośród powstawających przeciwko mnie, wiatr zaraźliwy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'I poślę na Babiilon przewiewaczy, którzy go przewiewać będą, i wypróżnią ziemię jego, gdyż będą przeciwko niemu zewsząd w dzień ucisku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Do tego, który mocno ciągnie łuk swój, a postępuje w pancerzu swoim, rzekę: Nie folgujcie młodzieńcom jego, wygładźcie wszystko wojsko jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Niech polegną pobici w ziemi Chaldejskiej, a poprzebijani po ulicach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Bo nie jest opuszczony Izrael i Juda od Boga swego, od Pana zastępów, choć ziemia ich pełna jest przestępstwa przeciwko Świętemu Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Uciekajcie z pośrodku Babilonu, a niech zachowa każdy duszę swoję, abyście nie byli zatraceni w nieprawości jego; bo czas będzie pomsty Pańskiej, sam mu zapłatę odda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Byłci Babilon kubkiem złotym w ręce Pańskiej, upajającym wszystkę ziemię; wino jego piły narody, dlatego poszalały narody;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Ale nagle upadnie Babilon, i starty będzie; rozkwilcie się nad nim, nabierzcie olejku balsamowego dla boleści jego, owa się wyleczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Leczyliśmy Babilon, ale nie jest uleczony. Opuśćmyż go, a pójdźmy każdy do ziemi swej; bo sąd jego aż do nieba sięga, i wyniósł się aż pod obłoki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Wywiódł Pan sprawiedliwości nasze. Pójdźcie, a opowiadajmy na Syonie dzieło Pana, Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Wyostrzcie strzały, sporządżcie tarcze. Wzbudził Pan ducha królów Medskich; bo przeciwko Babilonowi zamysł jego, aby go wytracił, gdyż pomsta Pańska jest pomsta kościoła jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Podnieście chorągiew na murach Babilońskich, przyczyńcie straży, postawcie stróżów, nagotujcie zasadzki; bo i umyślił Pan i wykona, co wyrzekł przeciwko obywatelom Babilońskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'O ty, który mieszkasz nad wodami wielkiemi! o bogaty w skarby! przyszedł koniec twój, kres łakomstwa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Przysiągł Pan zastępów na duszę swoję, że cię napełni ludźmi, jako chrząszczami, którzy uczynią nad tobą okrzyk wojenny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Onci to jest, który uczynił ziemię mocą swoją, który utwierdził okrąg świata mądrością swoją, i roztropnością swoją rozpostarł niebiosa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Który gdy głos wypuszcza, wody na niebie szumią, a który sprawuje, aby występowały pary od kończyn ziemi, i błyskawice ze dżdżem przywodzi, a wywodzi wiatr z skarbów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Tak zgłupiał każdy człowiek, że tego nie zna, że pohańbiony bywa złotnik od obrazu rytego; bo kłamstwem jest ulanie jego, a niemasz w nich ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Marnością są a dzieło błędów; zginą czasu nawiedzenia swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Nie takowyć jest dział Jakóbowy; bo on jest który wszystko stworzył, a Izrael jest prętem dziedzictwa jego; Pan zastępów imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Młotemeś ty moim kruszącym, orężem wojennym, abym pokruszył przez cię narody,i poburzył przez cię królestwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Abym pokruszył przez cię konia i jezdnego, abym pokruszył przez cię wóz i tego, co na nim jeździ;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Abym pokruszył przez cię męża i niewiastę, abym pokruszył przez cię starca i dziecię, abym pokruszył przez cię młodzieńca i pannę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Abym pokruszył przez cię pasterza i trzodę jego, abym pokruszył przez cię oracza, i sprzężaj jego, abym pokruszył przez cię książąt i hetmanów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Ale już oddam Babilonowi, i wszystkim obywatelom Chaldejskim za wszystkie złości ich, które czynili Syonowi przed oczyma waszemi, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Otom Ja jest przeciwko tobie, o góro każąca! mówi Pan, która kazisz wszystkę ziemię, i wyciągnę rękę moję przeciwko tobie, a zwalę cię z skał, i uczynię cię górą spalenia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'A nie wezmą z ciebie kamienia do węgła, ani kamienia do gruntów; bo pustynią wieczną będziesz, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Podnieście chorągiew w ziemi, trąbcie w trąbę między narodami, zgotujcie przeciwko niemu narody, zwołajcie przeciwko niemu królestwa Ararad, Minny, i Aschenas; postanówcie przeciwko niemu hetmana, przywiedźcie konie jako chrząszcze najeżone;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Zgotujcie przeciwko niemu narody, królów Medskich, książąt ich, i wszystkich hetmanów ich, ze wszystką ziemią władzy ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'Tedy zadrży ziemia, i rozboleje się, gdy wykonane będą przeciwko Babilonowi myśli Pańskie, aby obrócił ziemię Babilońską w pustynię, aby została bez obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Przestaną mocarze Babilońscy walczyć, usiądą w zamkach, ustanie męstwo ich, będą jako niewiasty; zapali mieszkania ich, pokruszone będą zawory ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Goniec spotka drugiego gońca, a poseł zabieży posłowi, aby opowiedzieli królowi Babilońskiemu, iż wzięto miasto jego z jednej strony,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'A iż brody ubieżono, i jeziora wypalano ogniem, a mężowie waleczni ustraszeni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Bo tak mówi Pan zastępów, Bóg Izraelski: Córka Babilońska jest jako bojewisko, czas deptania jej przyszedł; jeszcze maluczko, a przyjdzie czas żniwa jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Pożarł mię, potarł mię Nabuchodonozor, król Babiloński, uczynił mię naczyniem próżnem, połknął mię jako smok, napełnił brzuch swój rozkoszami mojemi, i wygnał mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Gwałt mnie i ciału memu uczyniony niech przyjdzie na Babilon, mówi obywatelka Syońska, a krew moja na obywateli Chaldejskich, mówi Jeruzalem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Przetoż tak mówi Pan: Oto się Ja zastawię o krzywdę twoję, a pomszczę się za cię; bo wysuszę morze jego, wysuszę i źródła jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'I będzie Babilon obrócony w mogiły, w mieszkanie smoków, w zdumienie, i w poświstanie, i będzie bez obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Pospołu jako lwy ryczeć będą, a skomleć jako szczenięta lwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Gdy się zapalą, uczynię im ucztę, i tak ich upoję, że krzyczeć i snem wiecznym zasnąć muszą, tak, aby nie ocucili, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Powiodę ich jako baranki ku zabiciu, jako barany i kozły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Jakożby dobyty mógł być Sesach? Jakożby wzięta być mogła chwała wszystkiej ziemi? Jakożby mógł przyjść na spustoszenie Babilon między narodami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Wystąpi przeciwko Babilonowi morze, mnóstwem wałów jego okryte będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Miasta jego będą spustoszeniem, ziemią suchą i pustą, ziemią, w której miastach nikt nie będzie mieszkał, ani będzie chodził przez nią syn człowieczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Nawiedzę też Bela w Babilonie, i wydrę, co był połknął, z gęby jego; i nie będą się więcej do niego zbiegać narody, i mury także Babilońskie upadną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Wyjdźcie z pośrodku jego, ludu mój! a wybaw każdy duszę swoję przed gniewem zapalczywości Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'A nie bądźcie miękkiego serca, ani się lękajcie wieści, którą będzie słychać w tej ziemi; gdy przyjdzie jednego roku nowina, potem drugiego roku wieść i gwałt w ziemi, a pan na pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Przetoż oto dni przyjdą, w które Ja nawiedzę bałwany ryte Babilońskie, a wszystka ziemia jego pohańbiona będzie, i wszyscy pobici jego polegną w pośrodku niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'I będą nad Babilonem śpiewać niebiosa i ziemia, i wszystko, co na nich jest, gdy z północy przyjdą nań pustoszyciele, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Jako Babilon poraził onych pobitych Izraelskich, tak z Babilonu polegną pobici po wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'O którzyście uszli miecza, idźcie, nie stójcie! wspominajcie z daleka na Pana, a Jeruzalem niech wstępuje na serce wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Rzeczcie: Wstydzimy się, że słyszymy urąganie; hańba okryła twarzy nasze, bo cudzoziemcy wchodzą do świątnic domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Przetoż oto dni przychodzą, mówi Pan, że nawiedzę ryte bałwany jego, a po wszystkiej ziemi jego zraniony stękać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Chociażby Babilon wstąpił na niebo, i obwarował na wysokości moc swoję, przecie odemnie przyjdą pustoszyciele jego, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Głos wołania z Babilonu, a starcie wielkie z ziemi Chaldejskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Bo Pan Babilon zburzy i wytraci z niego głos wielki, choćby huczały wały ich jako wody wielkie, i wydany był szum głosu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Gdy nań, to jest na Babilon, pustoszyciel przyciągnie pojmani będą mocarze jego, pokruszone będą łuki ich; bo Bóg nagrody, Pan nagrodzi im sowicie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Opoi książąt jego i mędrców jego, wodzów jego, i urzędników jego, i mocarzy jego, aby zasnęli snem wiecznym, a nie ocucili, mówi król, Pan zastępów imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Tak mówi Pan zastępów: Mur Babiloński szeroki do gruntu zburzony będzie, i bramy jego wysokie ogniem spalone będą, a ludzie darmo pracować będą, a narody przy ogniu pomdleją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Toć jest słowo, które rozkazał Jeremijasz prorok Sarajaszowi, synowi Neryjasza, syna Maasejaszowego, gdy odszedł od Sedekijasza, króla Judzkiego, do Babilonu, roku czwartego królowania jego; (a Sarajasz był książęciem w Menucha.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Gdy zapisał Jeremijasz wszystko złe, które przyjść miało na Babilon, w księgi jedne, wszystkie te słowa, które są napisane przeciwko Babilonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'I rzekł Jeremijasz do Sarajasza: Gdy przyjdziesz do Babilonu, i oglądasz go, tedy przeczytasz te wszystkie słowa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'A rzeczesz: O Panie! tyś mówił przeciwko miejscu temu, że je wytracisz, aby w niem nie mieszkał nikt, ani z ludzi ani z bydląt, ale żeby było pustkami wiecznemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'A gdy do końca przeczytasz te księgi, przywiążesz do nich kamień, i wrzucisz je w pośród Eufratesa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'A rzeczesz: Tak zatopiony będzie Babilon, a nie powstanie więcej z tego złego, które Ja nań przywiodę, choć ustawać będą. Aż dotąd słowa Jeremijaszowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Dwadzieścia i jeden lat miał Sedekijasz, gdy królować począł, a jedenaście lat królował w Jeruzalemie; a imię matki jego było Chamutal, córka Jeremijaszowa z Lebny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'I czynił złość przed oczyma Pańskiemi według wszystkiego, co czynił Joakim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Albowiem się to stało dla rozgniewania Pańskiego przeciwko Jeruzalemowi i Judzie, aż ich odrzucił od twarzy swej. Wtem zasię odstąpił Sedekijasz od króla Babilońskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'I stało się roku dziewiątego królestwa jego, miesiąca dziesiątego, dnia dziesiątego tegoż miesiąca, że przyciągnął Nabuchodonozor, król Babiloński, on i wszystko wojsko jego przeciwko Jeruzalemowi, i położył się obozem u niego, i porobił przeciwko niemu szańce w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'A tak było miasto oblężone aż do jedenastego roku króla Sedekijasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Tedy miesiąca czwartego, dziewiątego dnia tegoż miesiąca, był wielki głód w mieście, i nie miał chleba lud onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'I przełamano mur miejski, a wszyscy ludzie rycerscy pouciekali, i wyszli z miasta w nocy drogą do bramy, która jest między dwoma murami podle ogrodu królewskiego; (ale Chaldejczycy leżeli około miasta,) i poszli drogą ku pustyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'I goniło wojsko Chaldejskie króla, a doścignęli Sedekijasza na polach u Jerycha, a wszystko wojsko jego rozpierzchnęło się od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'A tak pojmawszy króla przywiedli go do króla Babilońskiego do Ryblaty w ziemi Eamat, kędy o nim uczynił sąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'I pozabijał król Babiloński synów Sedekijaszowych przed oczyma jego, także też wszystkich książąt Judzkich pozabijał w Ryblacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'A Sedekijasza oślepiwszy i związawszy go łańcuchami miedzianemi, zawiódł go król Babiloński do Babilonu, i podał go do domu więzienia aż do śmierci jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Potem miesiąca piątego, dnia dziesiątego tegoż miesiąca, ten jest rok dziewiętnasty królowania Nabuchodonozora, króla Babilońskiego, przyciągnął Nabuzardan, hetman żołnierski, który stawał przed królem Babilońskim, do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'I spalił dom Pański, i dom królewski, i wszystkie domy Jeruzalemskie; owa wszystko budowanie kosztowne popalił ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'I wszystkie mury Jeruzalemskie w około rozwaliło wszystko wojsko Chaldejskie, które było z onym hetmanem żołnierskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'A z ubogich ludzi i z ostatku pospólstwa, które było pozostało w mieście i zbiegów, którzy byli zbiegli do króla babilońskiego, i inne pospólstwo przeniósł Nabuzardan, hetman żołnierski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Tylko z ubogich onej ziemi zostawił Nabuzardan, hetman żołnierski, aby byli winiarzami i oraczami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Nadto słupy miedziane, które były w domu Pańskim, i podstawki, i morze miedziane, które było w domu Pańskim, potłukli Chaldejczycy, i przenieśli wszystkę miedź ich do Babilonu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Kotły też i łopaty, i naczynia muzyczne, i miednice, i czasze, i wszystko naczynie miedziane, którem usługiwano, pobrali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Nadto wiadra, i kadzielnice, i miednice, i garnce, i świeczniki, i czaszki, i kufle, co było złotego w złocie, a co było srebrnego w srebrze, pobrał hetman żołnierski;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Słupy dwa, morze jedno, i wołów miedzianych dwanaście, które były pod podstawkami, które był sprawił król Salomon w domu Pańskim; nie było wagi miedzi onego wszystkiego naczynia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'A z tych słupów ośmnaście łokci wzwyż był słup jeden, a w mięsz w około dwanaście łokci, a w miąższość jego cztery palce, a wewnątrz był dęty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'A gałka na nim miedziana, a wysokość gałki jednej była na pięć łokci, siatka też i jabłka granatowe na gałce w około wszystko miedziane; taki też był i drugi słup z jabłkami granatowemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'A było jabłek granatowych dziewięćdziesiąt i sześć po każdej stronie; wszystkich jabłek granatowych było po sto na siatce w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Wziął też hetman żołnierski Sarajego, kapłana przedniego, i Sofonijasza, kapłana wtórego po nim, i trzech stróżów progu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Wziął też z miasta dworzanina niektórego, który był przełożonym nad ludem rycerskim, i siedmiu mężów z tych, którzy stawali przed królem, którzy się znaleźli w mieście, i pisarza przedniego wojskowego, który spisywał wojsko z ludu ziemi, i sześćd ziesiąt mężów z ludu ziemi, którzy się znaleźli w mieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Wziąwszy ich tedy Nabuzardan, hetman żołnierski, zawiódł ich do króla Babilońskiego do Ryblaty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'I pobił ich król Babiloński, a pomordował ich w Ryblacie w ziemi Emat. A tak przeniesiony jest Juda z ziemi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Tenci jest lud, który zaprowadził Nabuchodonozor roku siódmego: Żydów trzy tysiące, i dwadzieścia i trzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'Roku ośmnastego Nabuchodonozora, zaprowadził z Jeruzalemu dusz ośm set, trzydzieści i dwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Roku dwudziestego i trzeciego Nabuchodonozora; zaprowadził Nabuzardan, hetman żołnierski, z Żydów dusz siedm set, czterdzieści i pięć; wszystkich dusz cztery tysiące i sześć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'A trzydziestego i siódmego roku, po pojmaniu Joachyna, króla Judzkiego, dwunastego miesiąca, dwudziestego i piątego dnia tegoż miesiąca, wywyższył Ewilmerodach, król Babiloński, tego roku, gdy począł królować, głowę Joachyna, króla Judzkiego, uwol niwszy go z domu więzienia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'I rozmawiał z nim łaskawie, i wystawił stolicę jego nad stolice królów, którzy byli z nim w Babilonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Odmienił też i odzienie, w którem był w więzieniu, i jadał chleb zawsze przed obliczem jego po wszystkie dni żywota swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Obrok też jemu naznaczony, obrok ustawiczny dawano mu od króla Babilońskiego na każdy dzień aż do śmierci jego, po wszystkie dni żywota jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'W biblii siedmdziesięciu tłómaczów, ta księga święta tak się zaczyna. I stało się, gdy Izrael pojmany był, a Jeruzalem spustoszone, że Jeremijasz siedział płacząc, i narzekał narzekaniem takiem nad Jeruzalemem, a rzekł: Ach miasto tak ludne jakoż siedzi samotne! stało się jako wdowa; zacne między narodami, przednie między krainami stało się hołdowne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Ustawicznie w nocy płacze, a łzy jego na jagodach jego; niemasz, ktoby je cieszył ze wszystkich miłośników jego; wszyscy przyjaciele jego przeniewierzyli mu się, stali mu się nieprzyjaciołmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Przeniósł się Juda dla utrapienia i dla wielkiej niewoli; wszakże mieszkając między narodami nie znajduje odpocznienia; wszyscy, którzy je gonią połapali je w cieśni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Drogi Syońskie płaczą, że nikt nie przychodzi na święto uroczyste. Wszystkie bramy jego spustoszały, kapłani jego wzdychają, panny jego smutne są, a samo pełne jest gorzkości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Nieprzyjaciele jego są głową, przeciwnikom jego szczęśliwie się powodzi; bo go Pan utrapił dla mnóstwa przestępstwa jego; maluczcy jego poszli w niewolę przed obliczem trapiącego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'A tak odjęta jest od córki Syońskiej wszystka ozdoba jej; książęta jej stały się jako jelenie nie znajdujący paszy, i uchodzą bez siły przed tym, który je goni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Wspomina córka Jeruzalemska we dni utrapienia swego i kwilenia swego na wszystkie uciechy swoje, które miewała ode dni dawnych, gdy pada lud jej od ręki nieprzyjacielskiej, nie mając, ktoby jej ratował; widząc ją nieprzyjaciele naśmiewali się z są batów jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Ciężko zgrzeszyła córka Jeruzalemska, przetoż jako nieczysta odłączona jest. Wszyscy, którzy ją w uczciwości mieli, lekce ją sobie ważą, przeto, że widzą nagość jej, a ona wzdycha, i tyłem się obraca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Nieczystota jej na podołkach jej, a nie pomniała na koniec swój; przetoż znacznie jest zniżona, nie mając, ktoby ją pocieszył. Wejrzyj, Panie! na utrapienie moje; boć się wyniósł nieprzyjaciel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Rękę swoję wyciągnął nieprzyjaciel na wszystkie kochania jej; bo musi patrzyć na pogan wchodzących do świątnicy jej, o czemeś był przykazał, aby nie wchodzili do zgromadzenia twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Wszystek lud jej wzdychając chleba szuka, daje kosztowne rzeczy swoje za pokarm ku posileniu duszy. Wejrzyj, Panie! a obacz; bom znieważona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Nicże was to nie obchodzi? o wszyscy, którzy mimo idziecie drogą! Obaczcie, a oglądajcie, jeźli jest boleść, jako moja boleść, która mi jest zadana, jako mię zasmucił Pan w dzień gniewu zapalczywości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Z wysokości posłał ogień w kości moje, który je opanował; rozciągnął sieć nogom moim, obrócił mię na wstecz, podał mię na spustoszenie, przez cały dzień żałośną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Związane jest jarzmo nieprawości moich ręką jego, splotły się, wstąpiły na szyję moję; toć poraziło siłę moję; podał mię Pan w ręce nieprzyjaciół, nie mogę powstać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Pan podeptał wszystkich mocarzy moich w pośród mnie, zwołał przeciwko mnie gromady, aby starł młodzieńców moich, Pan tłoczył jako w prasie pannę, córkę Judzką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Przetoż ja płaczę; z oczów moich, z oczów moich, mówię, wody cieką, że jest daleko odemnie pocieszyciel, któryby ochłodził duszę moję, synowie moi wytraceni są, przeto, iż wziął górę nieprzyjaciel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Rozciąga córka Sydońska ręce swoje, nie ma, ktoby ją cieszył; wzbudził Pan na Jakóba zewsząd w około nieprzyjaciół jego; córka Jeruzalemska jest między nimi, niby dla nieczystości oddalona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Sprawiedliwy jest Pan; bom ustom jego odporna była. Słuchajcie, proszę, wszyscy ludzie, a obaczcie boleść moję; panny moje, i młodzieńcy moi poszli w niewolę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Wołałam na przyjaciół moich, oni mię zdradzili; kapłani moi i starcy moi w mieście zginęli, szukając sobie pokarmu, aby posilili duszę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Wejrzyż, Panie, bomci utrapiona, wnętrzności moje strwożone są, wywróciło się serce moje we mnie, przeto, żem była bardzo odporna; na dworze miecz osieraca, a w domu nic niemasz jedno śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Słysząć, że ja wzdycham, ale niemasz, ktoby mię pocieszył; wszyscy nieprzyjaciele moi słysząc o nieszczęściu mojem weselą się, żeś ty to uczynił, a przywiodłeś dzień przedtem ogłoszony; aleć będą mnie podobni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Niech przyjdzie wszystka złość ich przed obliczność twoję, a uczyń im, jakoś mnie uczynił dla wszystkich przestępstw moich; bo wielkie są wzdychania moje, a serce moje żałośne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Jokoż zaćmił Pan w zapalczywości swoję córkę Syjońską! zrzucił z nieba na ziemię sławę Izraelską, a nie wspomniał na podnóżek nóg swoich w dzień zapalczywości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Połknął Pan bez wszelkiej litości wszystkie przybytki Jakóbowe, zburzył w popędliwości swojej twierdze córki Judzkiej, uderzył je o ziemię, w hańbę oddał królestwo i książąt jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'Odciął w gniewie zapalczywości wszystek róg Izraelski, odwrócił nazad prawicę swoję od nieprzyjaciela, a rozpaliwszy się przeciwko Jakóbowi, jako ogień pałający pożera do szczętu w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Naciągnął łuk swój, jako nieprzyjaciel, postawił prawicę swoję jako przeciwnik, i pozabijał wszystkich najpozorniejszych z ludu, a w namiocie córki Syońskiej wylał jako ogień popędliwość swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Pan się stał jako nieprzyjaciel, połknął Izraela, połknął wszystkie pałace jego, popsuł twierdze jego, i rozmnożył w ludu Judzkim płacz i narzekanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Oderwał mocą płot swój jako od ogrodu, zepsuł namiot swój; Pan przywiódł w zapamiętanie w Syonie uroczyste święta i sabaty, a odrzucił w gniewie popędliwości swojej króla i kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Pan odrzucił ołtarz swój, zbrzydził sobie świątnicę swoję, podał do rąk nieprzyjacielskich mury i pałace Syońskie; krzyczeli w domu Pańskim jako w dzień święta uroczystego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Umyślił Pan rozwalić mur córki Syońskiej, rozciągnął sznur, a nie odwrócił ręki swojej od skażenia; rozkwilił baszty, i mur, tak że wespół omdlewają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Zapadły w ziemię bramy jej, połamał i pokruszył zawory jej; król jej i książęta jej są między poganami; niemasz ani zakonu, także ani prorocy jej nie miewają widzenia od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Starcy córki Syońskiej usiadłszy na ziemi umilknęli, posypali prochem głowę swoję, a przepasują się worami; panny Jeruzalemskie zwiszają ku ziemi głowy swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Oczy moje od łez ustały; strwożyły się wnętrzności moje, wylała się na ziemię wątroba moja dla starcia córki ludu mojego, gdy i niemowlątka, i dziatki ssące na ulicach miasta omdlewają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Matkom swoim mówią: Gdzież jest zboże i wino? Gdy mdleją jako zranieni po ulicach miasta, i wypuszczają duszę swoję na łonie matek swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Kogoć za świadka stawię? Kogo tobie przyrównam, o córko Jeruzalemska? Kogoć przypodobam, abym cię ucieszył, panno, córko Syońska? bo skruszenie twoje wielkie jako morze, któż cię uleczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Prorocy twoi opowiadalić kłamstwo i marność, a nie odkrywali nieprawości twojej, aby odwrócili pojmanie twoje; aleć przepowiadali ciężary, kłamstwa i wygnanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Klaskają nad tobą rękoma wszyscy, którzy idą drogą, świstają, a chwieją głową swoją nad córką Jeruzalemską, mówiąc: A onoż to miasto, o którem powiadano, że jest doskonałej piękności, i weselem wszystkiej ziemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Otworzyli na cię usta swe wszyscy nieprzyjaciele twoi, świstają i zgrzytają zębami, mówiąc: Pożryjmy je; tenci jest zaiste on dzień, któregośmy czekali, znaleźliśmy i oglądaliśmy go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Uczynił Pan, co był umyślił, wypełnił słowo swoje, które był przykazał ode dni dawnych; zburzył bez litości, a rozweselił nad tobą nieprzyjaciela, wywyższył róg przeciwników twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Wołało serce ich do Pana. O murze córki Syońskiej! wylewaj łzy we dnie i w nocy jako strumień, nie dawaj sobie odpocznienia, a niech się nie uspokaja źrenica oka twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Wstań, wołaj w nocy na początku straży, wylewaj serce twoje przed obliczem Pańskiem jako wodę; podnoś do niego ręce swoje za duszę dziatek swych, które omdlewają od głodu na rogu wszystkich ulic, a rzecz: Wejrzyj Panie! a obacz, komuś tak kiedy u czynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Izali mają niewiasty jeść płód swój, niemowlątka ucieszne? Izali zamordowany być ma w świątnicy Pańskiej kapłan i prorok?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Leży na ziemi po ulicach dziecię, i starzec; panny moje, i młodzieńcy moi polegli od miecza; pobiłeś ich w dzień zapalczywości twojej, pomordowałeś ich, a nie sfolgowałeś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Zwołałeś strachów moich zewsząd, jako w dzień uroczystego święta, a nie był w dzień zapalczywości Pańskiej, ktoby uszedł a żyw został; którychem na ręku piastowała i wychowywała, tych nieprzyjaciel mój wyniszczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Jam jest ten mąż, którym widział utrapienie od rózgi rozgniewania Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Zaprowadził mię, i zawiódł do ciemności, a nie do światłości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Tylko się na mię obórzył, a obrócił rękę swoję przez cały dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Do starości przywiódł ciało moje i skórę moję, a połamał kości moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Obudował mię a ogarnął żółcią i pracą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'W ciemnych miejscach posadził mię, jako tych, którzy dawno pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Ogrodził mię, abym nie wyszedł, obciążył okowy moje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'A choć wołam i krzyczę, zatula uszy na modlitwę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Ogrodził drogę moję ciosanym kamieniem, ścieszki moje wywrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Jest jako niedźwiedziem czyhającym na mię, jako lwem w skrytościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Drogi moje odwrócił, owszem, rozszarpał mię, i uczynił mię spustoszoną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Naciągnął łuk swój, a postawił mię jako cel strzałom swym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'Przestrzelił nerki moje strzałami z sajdaka swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'Jestem pośmiewiskiem ze wszystkim ludem moim, pieśnią ich przez cały dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Nasyca mię gorzkościami; upija mię piołunem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Nadto pokruszył o kamyczki zęby moje, i pogrążył mię w popiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Takeś oddalił, o Boże! od pokoju duszę moję, aż na wczasy zapominam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'I mówię: Zginęła siła moja, i nadzieja moja, którąm miał w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Wszakże wspominając na utrapienie moje, i na płacz mój, na piołun, i na żółć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Wspominając ustawicznie, uniża się we mnie dusza moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Przywodząc to sobie do serca swego, mam nadzieję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Wielkie jest miłosierdzie Pańskie, żeśmy do szczętu nie zginęli; nie ustawają zaiste litości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Ale się na każdy poranek odnawiają; wielka jest prawda twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Pan jest działem moim, mówi dusza moja, dlatego mam w nim nadzieję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Dobry jest Pan tym, którzy nań oczekują, duszy takowej, która go szuka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Dobrze jest, cierpliwie oczekiwać na zbawienie Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Dobrze jest mężowi nosić jarzmo od dzieciństwa swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Który będąc opuszczony, cierpliwym jest w tem, co nań włożono;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Kładzie w prochu usta swe, ażby się okazała nadzieja;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Nadstawia bijącemu policzka, a nasycony bywa obelżeniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Bo Pan na wieki nie odrzuca;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Owszem, jeźli zasmuca, zasię się zmiłuje według mnóstwa miłosierdzia swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Zaiste nie z serca trapi i zasmuca synów ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Aby kto starł nogami swemi wszystkich więźniów w ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Aby kto niesprawiedliwie sądził męża przed obliczem Najwyższego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Aby kto wywrócił człowieka w sprawie jego, Pan się w tem nie kocha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Któż jest, coby rzekł: Stało się, a Pan nie przykazał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Izali z ust Najwyższego nie pochodzi złe i dobre?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Przeczżeby tedy sobie utyskiwać miał człowiek żyjący, a mąż nad kaźnią za grzechy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Dowiadujmy się raczej, a badajmy się dróg naszych, nawróćmy się do Pana;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Podnieśmy serca i ręce nasze w niebo do Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Myśmy wstąpili i staliśmy się odpornymi; przetoż ty nie odpuszczasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Okryłeś się zapalczywością, i gonisz nas, mordujesz, a nie szanujesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Okryłeś się obłokiem, aby cię nie dochodziła modlitwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Za śmieci i za pomiotło położyłeś nas w pośrodku tych narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Otworzyli na nas usta swoje wszyscy nieprzyjaciele nasi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Strach i dół przyszedł na nas, spustoszenie i skruszenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Strumienie wód płyną z oczów moich, dla skruszenia córki ludu mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Oczy moje płyną bez przestanku, przeto, że niemasz żadnej ulgi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Ażby wejrzał i obaczył Pan z nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Oczy moje trapią duszę moję dla wszystkich córek miasta mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Łowili mię ustawicznie jako ptaka nieprzyjaciele moi bez przyczyny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Wrzucili do dołu żywot mój, a przywalili mię kamieniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Wezbrały wody nad głową moją, i rzekłem: Jużci po mnie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Wzywam imienia twego, o Panie! z dołu bardzo głębokiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Głos mój wysłuchiwałeś; nie zatulajże ucha twego przed wzdychaniem mojem, i przed wołaniem mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Przybliżając się do mnie w dzień, któregom cię wzywał, mawiałeś: Nie bój się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Zastawiałeś się, Panie! o sprawę duszy mojej, a wybawiałeś żywot mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Widzisz, o Panie! bezprawie, które mi się dzieje, osądźże sprawę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Widzisz wszystkę pomstę ich, i wszystkie zamysły ich przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Słyszysz urąganie ich, o Panie! i wszystkie zamysły ich przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Słyszysz wargi powstawających przeciwko mnie, i przemyśliwanie ich przeciwko mnie przez cały dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Obacz siadanie ich, i wstawanie ich; jam zawżdy jest pieśnią ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Oddajże im nagrodę, Panie! według sprawy rąk ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Dajże im zatwardziałe serce, i przeklęstwo swe na nich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Goń ich w zapalczywości, a zgładź ich, aby nie byli pod niebem twojem, o Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'O jakoż pośniedziało złoto! zmieniło się wyborne złoto, rozmiotano kamienie świątnicy, po rogach wszystkich ulic.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Szlachetni synowie Syońscy, którzy byli przyrównani do złota szczerego, jakoż są poczytani za naczynie gliniane, za dzieło rąk garncarskich!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'I smoki więc podawając piersi, karmią młode swoje; ale córka ludu mojego dla okrutnika podobna jest sowie na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Przylgnął język ssącego do podniebienia jego dla upragnienia, dzieci proszą o chleb: ale niemasz, ktoby im go ułamał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Ci, którzy jadali potrawy rozkoszne, giną na ulicach, a którzy byli wychowani w szarłacie, przytulają się do gnoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Większe jest karanie córki ludu mojego, niżeli pomsta Sodomy, która jest podwrócona w jednem okamgnieniu, i nie zostały na niej ręce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Czystsi byli Nazarejczycy jego nad śnieg, jaśniejsi nad mleko, rumieńsze ciała ich, niżeli drogie kamienie, jakoby z szafiru wyciosani byli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Ale teraz wejrzenie ich czerniejsze jest niż czarność, nie mogą poznani być na ulicach; przyschła skóra ich do kości ich, wyschła jest jako drzewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Lepiej się tym stało, którzy są pobici mieczem, niżeli tym, co umierają głodem, gdyż oni zginęli przebitymi będąc, ale ci dla niedostatku urodzajów polnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Ręce niewiast miłosiernych warzyły synów swych, aby im byli za pokarm w potarciu córki ludu mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Wypełnił Pan popędliwość swoję, i wylał gniew zapalczywości swojej, i zapalił ogień na Syonie, który pożarł grunty jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Nigyby byli nie wierzyli królowie ziemscy, i wszysscy obywatele świata, żeby był miał wnijść przeciwnik, i nieprzyjaciel w bramy Jeruzalemskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Ale się to stało dla grzechów proroków jego, i nieprawości kapłanów jego, którzy wylewali w pośrodku jego krew sprawiedliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Tułali się jako ślepi po ulicach, mażąć się krwią, której nie mogli, tylko się dotykać szatami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Przetoż wołali na nich: Ustępujcie, nieczyści! ustępujcie, ustępujcie, nie dotykajcie się! Prawieć ustąpili, i tułają się; dlatego mówią między narodami: Nie będą już więcej mieli własnego mieszkania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Oblicze Pańskie rozproszyło ich, a nie wejrzy na nich więcej; nieprzyjaciele kapłanów nie szanują, a nad starcami miłosierdzia nie używają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'A wżdzy jeszcze aż do ustania oczów swych wyglądamy próżnego ratunku swego; oglądając się na naród, który wybawić nie może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Szlakują stopy nasze, tak, że ani po ulicach naszych chodzić nie możemy; przybliżył się koniec nasz, wypełniły się dni nasze, zaiste przyszło dokończenie nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Prędsi są ci, którzy nas gonią, niż orły niebieskie; po górach nas gonią, na pustyniach czyhają na nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Tchnienie nozdrzy naszych, to jest pomazaniec Pański, pojmany jest w jamach ich, o którymeśmy mówili: W cieniu jego żyć będziemy między narodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Raduj się i wesel się córko Edomska! która mieszkasz w ziemi Hus; przyjdzie też do ciebie kubek, upijesz się, i obnażysz się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Wzięło koniec karanie twoje, o córko Syońska! nie zaniecha cię Bóg dłużej w pojmaniu twojem; ale twoję nieprawość nawiedzi, o córko Edomska! a odkryje grzechy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Wspomnij, Panie! na to, co się nam przydało; wejrzyj a obacz pohańbienie nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Dziedzictwo nasze obrócone jest do obcych, a domy nasze do cudzoziemców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Sierotamiśmy a bez ojca; matki nasze są jako wdowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Wody nasze za pieniądze pijemy, drwa nasze za pieniądze kupujemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Na szyi swej prześladowanie cierpiemy, pracujemy, a nie dadzą nam odpocząć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Egipczykom podajemy rękę i Assyryjczykom, żebyśmy się nasycili chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Ojcowie nasi zgrzeszyli, niemasz ich, a my nieprawość ich ponosimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Niewolnicy panują nad nami, niemasz, ktoby nas wybawił z ręki ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Z odwagą duszy naszej szukamy chleba swego dla strachu miecza i na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Skóra nasza jako piec zczerniała od srogości głodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Niewiasty w Syonie pogwałcono; i panny w miastach Judzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Książęta ręką ich powieszeni są, a osoby starszych nie mają w uczciwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Młodzięców do żarn biorą, a młodzieniaszkowie po drwami padają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Starcy w bramach więcej nie siadają, a młodzieńcy przestali pieśni swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Ustało wesele serca naszego, pląsanie nasze w kwilenie się obróciło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Spadła korona z głowy naszej; biada nam, żeśmy zgrzeszyli!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Dlategoż mdłe jest serce nasze, dlatego zaćmione są oczy nasze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Dla góry Syońskiej, że jest spustoszona, liszki chodzą po niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Ty, Panie! trwasz na wieki, a stolica twoja od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Przeczże nas na wieki zapominasz, a opuszczasz nas przez tak długi czas?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Nawróć nas do siebie, o Panie! a nawróceni będziemy; odnów dni nasze, jako z dawna były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Bo izali nas cale odrzucisz, a gniewać się będziesz na nas tak bardzo?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'I stało się trzydziestego roku, miesiąca czwartego, piątego dnia tegoż miesiąca, gdym był w pośrodku pojmanych u rzeki Chebar, że się otworzyły niebiosa, i widziałem widzenie Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Piątego dnia tegoż miesiąca, (ten jest rok piąty po zaprowadzeniu króla Joachyna.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Prawdziwie stało się słowo Pańskie do Ezechyjela kapłana, syna Buzowego, w ziemi Chaldejskiej u rzeki Chebar, a była nad nim ręka Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'I widziałem, a oto wiatr gwałtowny przychodził od północy, i obłok wielki, i ogień pałający, a blask był około niego, a z pośrodku jego wynikała jakoby niejaka prędka światłość, z pośrodku, mówię, onego ognia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Także z pośrodku jego ukazało się podobieństwo czworga zwierząt, których takowy był kształt: Podobieństwo człowieka miały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'A każde po cztery twarze, także po cztery skrzydła każde z nich miało;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Nogi ich były nogi proste, a stopa nóg ich jako stopa nogi cielęcej, a lśniały się właśnie jako miedź wypolerowana;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Ręce ludzkie były pod skrzydłami ich po czterech stronach ich, a twarze ich i skrzydła ich na czterech onych stronach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Skrzydła ich spojone były jedno z drugiem, nie obracały się, gdy chodziły, ale każde w prost na swą stronę chodziło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'A podobieństwo twarzy ich takie: Z przodku twarz ludzka a twarz lwia po prawej stronie każdego z nich, a twarz wołowa po lewej stronie wszystkich czworga, także twarz orlą z tyłu miało wszystko czworo z nich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'A twarze ich i skrzydła ich były podniesione ku górze; każde zwierzę dwa skrzydła spajało z dwoma skrzydłami drugiego, a dwoma przykrywały ciało swoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'A każde z nich wprost na swą stronę chodziło; kędykolwiek duch chciał, aby szły, tam szły, nie obracały się, gdy chodziły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Także podobieństwo onych zwierząt na wejrzeniu było jako węgle w ogniu rozpalone, palące się jako pochodnie; ten ogień ustawicznie chodził między zwierzętami, a on ogień miał blask, z którego ognia wychodziła błyskawica.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Biegały też one zwierzęta, i wracały się jako prędkie błyskawice.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'A gdym się przypatrywał onym zwierzętom, a oto koło jedno było na ziemi przy zwierzętach u czterech twarzy każdego z nich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Na wejrzeniu były koła, i robota ich jako barwa kamienia Tarsys, a podobieństwo było jednakie onych czterech kół, a były na wejrzeniu i robota ich, jakoby było koło w pośrodku koła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Mając iść na cztery strony swoje chodziły, a nie obracały się, gdy chodziły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Dzwona taką wysokość miały, aż strach z nich pochodził; te dzwona w około wszystkich czterech kół pełne były oczów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'A gdy chodziły zwierzęta, koła też chodziły podle nich; a gdy się podnosiły zwierzęta w górę od ziemi, podnosiły się i koła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Gdziekolwiek chciał duch, aby szły, tam szły; gdzie mówię duch chciał, aby szły; a koła podnosiły się przed niemi, bo duch zwierząt był w kołach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Gdy one szły, szły i koła, a gdy one stały, stały; a gdy się podniosły od ziemi, podniosły się też koła z niemi; bo duch zwierząt był w kołach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Nad głowami zwierząt było podobieństwo rozpostarcia jako podobieństwo kryształu przezroczystego rozciągnionego nad głowami ich z wierzchu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'A pod onem rozpostarciem skrzydła ich były podniesione, jedno z drugiem spojone; każde miało dwa, któremi się przykrywało, każde, mówię, miało dwa, któremi przykrywało ciało swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'I słyszałem szum skrzydeł ich, jako szum wód wielkich, jako szum Wszechmocnego, gdy chodziły, i szum huku jako szum wojska; a gdy stały, spuściły skrzydła swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'A gdy stały i spuszczały skrzydła swoje, tedy był szum z wierzchu nad rozpostarciem, które było nad głową ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'A z wierzchu na rozpostarciu, które było nad głową ich, było podobieństwo stolicy na wejrzeniu jako kamień szafirowy, a nad podobieństwem stolicy, na nim z wierzchu na wejrzeniu jako osoba człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'I widziałem na wejrzeniu jakoby prędką światłość, a wewnątrz w niej w około na wejrzeniu jako ogień od biódr jego w górę; także też od biódr jego na dół widziałem na wejrzeniu jako ogień, i blask około niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Jaka bywa tęcza na wejrzeniu, która bywa na obłoku czasu deszczu, taki był na wejrzeniu blask w około. Toć było widzenie podobieństwa chwały Pańskiej, które gdym widział, upadłem na oblicze swoje, i usłyszałem głos mówiącego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'I rzekł do mnie: Synu człowieczy! stań na nogi twe, a będę mówił z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'I wstąpił w mię duch, gdy przemówił do mnie, a postawił mię na nogi moje, i słyszałem mówiącego do mnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Który rzekł do mnie: Synu człowieczy! Ja cię posyłam do synów Izraelskich, do narodów odpornych, którzy mi się sprzeciwili; oni i ojcowie ich występowali przeciwko mnie aż prawie do dnia tego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Do tych, mówię, synów niewstydliwej twarzy, i zatwardziałego serca Ja cię posyłam, i rzeczesz im: Tak mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Niech oni słuchają albo nie, gdyż domem odpornym są, przecież niech wiedzą, że prorok był w pośrodku ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Ale ty, synu człowieczy! nie bój się ich, ani się lękaj słów ich, że odporni a jako ciernie są przeciwko tobie, a że między niedźwiadkami mieszkasz; słów ich nie bój się, ani się twarzy ich lękaj, przeto, że domem odpornym są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Ale mów słowa moje do nich, niech oni słuchają albo nie, gdyż odpornymi są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Lecz ty, synu człowieczy! słuchaj, co Ja mówię do ciebie: Nie bądź odporny, jako ten dom odporny; otwórz usta swe, a zjedz, coć dam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'I widziałem, a oto ręka była wyciągniona do mnie, a oto w niej zwinione księgi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Które rozwinął przedemną; a były popisane z przodku i z końca, a w nich były napisane narzekania, i wzdychania i bieda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'I rzekł do mnie: Synu człowieczy! co przed tobą jest, zjedz; zjedz te księgi, a idź i mów do domu Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Otworzyłem tedy usta swe, i dał mi zjeść one księgi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'A mówił do mnie: Synu człowieczy! nakarm brzuch twój, a wnętrzności twoje napełnij temi księgami, któreć daję. I zjadłem je, i były w ustach moich słodkie jako miód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Zatem rzekł do mnie: Synu człowieczy! idź a wnijdź do domu Izraelskiego, i mów słowy mojemi do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Bo cię nie do ludu nieznajomej mowy, albo trudnego języka posyłam, ale do domu Izraelskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Nie do wielu narodów nieznajomej mowy, i trudnego języka, którychbyś słów nie zrozumiał, którzy jednak, gdybym cię do nich posłał, usłuchaliby cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Lecz dom Izraelski nie będzie cię chciał usłuchać, ponieważ mnie samego usłuchać nie chcą; bo wszystek dom Izraelski jest twardego czoła i zatwardzonego serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Ale otom uczynił twarz twoję twardą przeciwko twarzy ich, a czoło twe twarde przeciwko czołu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Uczyniłem czoło twe jako dyjament, i twardsze nad skałę; nie bójże się ich, ani się lękaj twarzy ich, przeto, że są domem odpornym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'I rzekł do mnie: Synu człowieczy! wszystkie słowa moje, które mówić będę do ciebie, przyjmij do serca twego, a słuchaj uszyma twemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Idź a wnijdź do pojmanych, do synów ludu twego, i mów do nich, a powiedz im: Tak mówi panujący Pan, niech oni słuchają, albo nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Tedy mię duch podniósł, i słyszałem za sobą głos grzmotu wielkiego: Błogosławiona niech będzie chwała Pańska z miejsca swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'I szum skrzydeł onych zwierząt, które się naspół dotykały, i głos kół naprzeciwko nim, i głos grzmotu wielkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'A duch podniósł mię i wziął mię. I odszedłem z gorzkością w rozgniewaniu ducha mego; ale ręka Pańska nademną mocna była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'I przyszedłem do pojmanych do Telabib, którzy mieszkali przy rzece Chebar, i siadłem gdzie oni mieszkali, a siedziałem tam siedm dni w pośrodku ich, zdumiawszy się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'A gdy minęło siedm dni, było słowo Pańskie do mnie mówiące:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Synu człowieczy! Dałem cię stróżem domowi Izraelskiemu, abyś słysząc słowo z ust moich napomniał ich odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Gdybym Ja rzekł niepobożnemu: Śmiercią umrzesz, a nie napomniałbyś go, i nie mówiłbyś, abyś go odwiódł od niezbożnej drogi jego, tak, żebyś go przy żywocie zachował, tedy onci niezbożny w nieprawości swojej umrze; ale krwi jego z ręki twojej szukać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Lecz jeźlibyś ty napomniał niezbożnego, a nie odwróciłby się od niezbożności swej, i od drogi swej niezbożnej, tedy onci w nieprawości swojej umrze; ale ty duszę swoję wybawisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Także jeźliby się odwrócił sprawiedliwy od sprawiedliwości swojej, a czyniłby nieprawość, a Jabym położył zawadę przed nim, i takby umarł, a tybyś go nie napomniał: w grzechu swym umrze, a nie przyjdą na pamięć sprawiedliwości jego, które czynił, lecz krwi jego z ręki twojej szukać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Ale jeźlibyś ty napomniał sprawiedliwego, aby nie zgrzeszył ten sprawiedliwy, i nie grzeszyłby, zaiste żyć będzie, bo napomnienie przyjął, a ty duszę swoję wybawisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'I była tam nademną ręka Pańska, i rzekł do mnie: Wstawszy wyjdź w pole, a tam się z tobą rozmówię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'A tak wstawszy szedłem w pole, a oto chwała Pańska stała tam, jako chwała, którąm widział u rzeki Chebar, i upadłem na oblicze moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Tedy duch wstąpił w mię, a postawiwszy mię na nogi moje mówił do mnie, i rzekł mi: Wnijdź, zamknij się w domu swym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Bo oto na cię, synu człowieczy! włożą powrozy, i zwiążą cię niemi, a nie będziesz mógł wynijść między nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'A Ja uczynię, że język twój przylgnie do podniebienia twego, i będziesz niemy, a nie będziesz im mężem strofującym, przeto, że są domem odpornym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Ale gdy z tobą mówić będę, otworzę usta twoje; tedy rzeczesz do nich: Tak mówi panujący Pan: Kto chce słuchać, niech słucha, a kto nie chce, niech nie słucha, gdyż domem odpornym są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'A ty, synu człowieczy! weźmij sobie cegłę, a położywszy ją przed sobą, wyryj na niej miasto Jeruzalem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'I sporządź na niej oblężenie, i zbuduj na niej szańce, i usyp na niej wał, a postaw na niej wojska, i zasadź na niej tarany w około;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Potem weźmij sobie panew żelazną, i postaw ją miasto muru żelaznego między sobą a między miastem, a obróć twarz swoję przeciwko niemu, niech będzie oblężone, a oblężesz je. To będzie znakiem domowi Izraelskiemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'A ty układź się na lewy bok twój, a włóż nań nieprawość domu Izraelskiego; jak wiele dni leżeć będziesz na nim, tak długo poniesiesz nieprawość ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'A Ja tobie daję lata nieprawości ich według liczby dni, to jest trzy sta i dziewięćdziesiąt dni, tak długo poniesiesz nieprawość domu Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'A gdy je wypełnisz, układziesz się powtóre na prawy bok twój, a poniesiesz nieprawość domu Judzkiego przez czterdzieści dni; dzień za rok, dzień, mówię, za rok daję tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Tak tedy obróć twarz swoję przeciwko oblężeniu Jeruzalemu, ramię swoje wysmuknij, a prorokuj przeciwko niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'A oto kładę na cię powrozy, abyś się nie obrócił z jednego boku na drugi, dokąd nie wypełnisz dni oblężenia swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Przetoż nabierz sobie pszenicy, i jęczmienia, i bobu, i soczewicy, i prosa, i wiki, a włóż to do jednego naczynia, i uczyń sobie z tego pokarm, według liczby dni, których leżeć będziesz na boku swym, to jest, przez trzysta i dziewięćdziesiąt dni jeść go będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'A ta waga będzie pokarmu twego, który jeść będziesz, mianowicie dwadzieścia syklów na dzień, od czasu aż do czasu jeść go będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Także wodę pod miarą pić będziesz; szóstą część hynu od czasu do czasu pić będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'A podpłomyk jęczmienny, który jeść będziesz, ten przy łajnach człowieczych upieczesz przed oczyma ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'I rzekł Pan: Tak będą jeść synowie Izraelscy chleb swój plugawy dla pogan, których tam zgromadzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'I rzekłem: Ach panujący Panie! oto dusza moja nie jest splugawiona zdechliną, a tego, co zwierz rozszarpał, nie jadłem od dzieciństwa mego aż dotąd, i nie wchodziło do ust moich żadne mięso obrzydłe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Ale on rzekł do mnie: Oto daję ci łajna wołowe miasto łajen człowieczych, abyś sobie przy nich napiekł chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Zatem rzekł do mnie: Synu człowieczy! Oto Ja złamię laskę chleba w Jeruzalemie, tak, że chleb pod wagą jeść będą, i to z frasunkiem, także wodę pod miarą pić będą, i to z zdumieniem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Aby niedostatek mając chleba i wody, zdumiewał się każdy z nich, i uwiądł w nieprawościach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Potem ty, synu człowieczy! weźmij sobie nóż ostry, to jest brzytwę barwierską, weźmij ją sobie, a ogól nią głowę swoję i brodę swoję; potem weźmij sobie wagę, i rozdziel je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Jednę trzecią część ogniem spal w pośród miasta, gdy się wypełnią dni oblężenia; potem wziąwszy drugą trzecią część, posiekaj mieczem około niego, a ostatnią trzecią część roztrząśnij na wiatr; bo miecza dobędę za nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'A wszakże weźmij z nich jaką trochę, i zawiąż w kraje szaty twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'A i z tych jeszcze wziąwszy wrzuć je w pośród ognia, i spal je w ogniu, skąd wynijdzie ogień na wszystek dom Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Tak mówi panujący Pan: Toć jest Jeruzalem, którem postawił w pośród pogan, a zewsząd otoczył krainami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Ale odmieniło sądy moje w niezbożność, bardziej niż poganie, a ustawy moje bardziej niż inne krainy, które są około niego; bo sądami mojemi pogardzili, i w ustawach moich nie chodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Przetoż tak mówi panujący Pan: Dlatego, żeście pogaństwo grzechami przewyższyli, które jest około was, a w ustawach moich nie chodziliście, i sądów moich nie zachowaliście, nawet ani tak jako poganie, którzy są około was, sąduście nie czynili;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Przetoż tak mówi panujący Pan: Otom Ja przeciwko tobie, otom Ja, i wykonam w pośrodku ciebie sądy przed oczyma pogan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Bo uczynię przy tobie to, czegom pierwej nie uczynił, i czego napotem nie uczynię dla wszystkich obrzydliwości twoich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Tak, że ojcowie jeść będą synów w pośrodku ciebie, a synowie jeść będą ojców swoich; i wykonam sądy przeciwko tobie, a rozproszę wszystkie ostatki twoje na wszystkie strony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Przetoż jako żyję Ja, mówi panujący Pan: Ponieważeś ty świątnicę moję splugawiło wszelakiemi nieczystościami twojemi, i wszelakiemi obrzydliwościami twemi, i Ja cię też podam w lekkość, a nie sfolgujeć oko moje, ani się zlituję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Trzecia część z ciebie morem pomrze i głodem wyginie w pośrodku ciebie, a druga trzecia część od miecza padnie około ciebie, a trzecią ostatnią część na wszystkie strony rozproszę, i miecza dobędę za nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'A tak się do końca wyleje zapalczywość moja, i natrę popędliwością swoją na nich, i ucieszę się, i doznają, żem Ja Pan, którym to wyrzekł w zapalczywości mojej, gdy wypełnię gniew swój nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'A podam cię w spustoszenie i w pohańbienie narodom, które są około ciebie, przed oczyma każdego mijającego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'A tak będziesz na hańbę, na pośmiech, na srogi przykład i na zdumienie narodom, które są około ciebie, gdy wykonam przeciwko tobie sądy w popędliwości i w gniewie i w srogiem zagniewaniu. Ja Pan mówiłem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Gdy wypuszczę srogie strzały głodu na zgubę waszę, które wypuszczę, abym was wygubił, a głód zgromadzę przeciwko wam, i złamię wam laskę chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Poślę zaiste na was głód, i zwierzęta okrutne, które cię osierocą; i mór i krew przyjdzie na cię, gdy na cię miecz przywiodę. Ja Pan mówiłem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Synu człowieczy! obróć twarz twoję ku górom Izraelskim, a prorokuj przeciwko nim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'I rzecz: Góry Izraelskie! słuchajcie słowa panującego Pana. Tak mówi panujący Pan górom i pagórkom, strumieniom i dolinom: Oto Ja, Ja przywiodę na was miecz, i pokażę wyżyny wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'A tak spustoszone będą ołtarze wasze, i zdruzgotane będą słoneczne obrazy wasze, a porozrzucam pobitych waszych przed plugawemi bałwanami waszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Położę też trupy synów Izraelskich przed plugawemi bałwanami ich, a rozrzucę kości wasze około ołtarzów waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Po wszystkich mieszkaniach waszych miasta spustoszone będą, i wyżyny spustoszeją, tak, iż będą skażone i rozwalone ołtarze wasze, zdruzgotane będą, i ustaną plugawe bałwany wasze, a będą podrąbione słoneczne obrazy wasze, a tak wygładzone będą dzieła wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'I padnie zraniony w pośrodku was, a poznacie, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Wszakże z was niektórych pozostawię, którzyby uszli miecza między poganami, gdy rozproszeni będziecie po ziemiach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'I wspomną na mię, którzy z was zachowani będą między narodami, u krórych będą w pojmaniu, żem ubolewał nad sercem ich wszetecznem, które odstąpiło odemnie, i nad oczyma ich, które nierząd płodziły, chodząc za plugawemi bałwanami swojemi: i omierzną sami sobie dla złości, które czynili we wszystkich obrzydliwościach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'I poznają, żem Ja Pan, a iżem nie darmo mówił, że na nich to złe przywiodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Tak mówi panujący Pan: Klaśnij ręką twoją, a tąpnij nogą twoją, i mów: Niestetyż na wszystkie złe obrzydliwości domu Izraelskiego; bo od miecza, od głodu, od morowego powietrza polegną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Ten, co będzie daleko, morem umrze, a ten, co blisko, od miecza polegnie, a ten, co zostanie, i oblężony, od głodu umrze; a tak wykonam popędliwość moję nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Tedy poznacie, żem Ja Pan, gdy będą pobici ich leżeli w pośrodku plugawych bałwanów ich, i około ołtarzów ich, na każdym pagórku wysokim, po wszystkich wierzchach gór, i pod każdem drzewem zielonem, i pod każdym dębem krzewistym, na któremkolwiek miejscu sprawowali wonność wdzięczną wszystkim plugawym bałwanom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Bo rękę swoję wyciągnę przeciwko nim, i uczynię tę ziemię spustoszoną i bardziej spustoszoną niż pustynię Dyblat, we wszystkich mieszkaniach ich. A tak poznają, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Potem stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Słuchaj ty, synu człowieczy: Tak mówi panujący Pan o ziemi Izraelskiej: Koniec, koniec przyszedł na wszystkie cztery strony ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Teraz przyjdzie koniec na cię; poślę na cię popędliwość moję, i będę cię sądził według dróg twoich, i zwalę na cię wszystkie obrzydliwości twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'A nie sfolgujeć oko moje, i nie zmiłuję się, ale drogi twoje zwalę na cię, a obrzydliwości twoje będą w pośrodku ciebie, i poznacie, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Tak mówi panujący Pan: Utrapienie jedno, oto utrapienie straszne przychodzi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Koniec przychodzi, przychodzi koniec, ocknął się przeciwko tobie, oto przychodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Przychodzi prędki poranek na cię, o obywatelu ziemi! przychodzi ten czas, przybliża się ten dzień grzmotu, a nie głosu rozlegającego się po górach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Już prędko, już wyleję gniew mój na cię, a wykonam zapalczywość moję nad tobą, a osądzę cię według dróg twoich, i włożę na cię wszystkie obrzydliwości twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Nie sfolgujeć zaiste oko moje, ani się zlituję, ale według dróg twoich nagrodzęć, i obrzydliwości twoje w pośrodku ciebie będą; a tak poznacie, żem Ja Pan, który biję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Oto ten dzień, oto przyszedł; przyszedł prędki poranek, zakwitnęła rózga, wybija się pycha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Okrucieństwo wyrosło w rózgę niezbożności; nie zostanie z nich nic, ani z mnóstwa ich, ani z huku ich, i nie będzie żadnego narzekania nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Idzie czas, przybliża się dzień. Kto kupi, nie będzie się weselił, a kto sprzeda, nie będzie żałował; bo popędliwość przyjdzie na wszystko mnóstwo jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Bo kto sprzedał, nie wróci się do rzeczy sprzedanej choćby jeszcze między żyjącymi był żywot ich; ponieważ widzenie na wszystko mnóstwo jej nie wróci się, a żaden w nieprawości żywota swego nie zmocni się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Trąbić będą w trąbę, i wszystko przygotują, jednak nie będzie kto miał iść na wojnę; bo popędliwość moja oburzy się na wszystko mnóstwo jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Miecz zewnątrz, a mór i głód będzie wewnątrz; kto będzie na polu, od miecza umrze; a kto w mieście, głód i mór go pożre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'A którzy z nich uciekną, ci będą na górach jako gołębice w dolinie; wszyscy będą narzekali, każdy nad nieprawością swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Wszystkie ręce osłabieją, i wszystkie się kolana rozpłyną jako woda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'I obloką się w wory, i okryje ich strach, i na wszelkiej twarzy będzie wstyd, i na wszystkich głowach ich łysina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Srebro swoje po ulicach rozrzucą, a złoto ich będzie jako nieczystość; srebro ich i złoto ich nie będzie ich mogło wybawić w dzień popędliwości Pańskiej; nie nasycą duszy swojej, i wnętrzności swych nie napełnią, przeto, że im jest ku obrażeniu nieprawość ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'A iż w sławie ozdoby swojej, którą na chwałę swoją Bóg wystawił, obrazów obrzydliwości swoich i sprosności swoich naczynili, przetożem im je w nieczystość obrócił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'I podam je w ręce cudzoziemców na rozchwycenie, i niezbożnych w ziemi na łup, którzy ją splugawią;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Odwrócę też twarz moję od nich, a zgwałcą świątnicę moję, a wnijdą do niej rozbójnicy, i splugawią ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Uczyń łańcuch; bo ziemia pełna jest krwawych sądów, a miasto pełne jest krzywd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Przetoż najgorszych z pogan przywiodę, aby posiedli domy ich; i uczynię wstręt pysze mocarzów, a splugawieni będą, którzy je poświęcają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Zginienie przyszło; przetoż szukać będą pokoju, ale go nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Ucisk za uciskiem przyjdzie, a wieść za wieścią przypadnie; i będą szukać widzenia od proroka! ale zakon zginie od kapłana, a rada od starców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Król płakać będzie, a książę w smutek obleczony będzie, a ręce ludu w ziemi przestraszone będą. Według drogi ich uczynię im, i według sądów ich osądzę ich, i poznają, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'I stało się roku szóstego, piątego dnia, szóstego miesiąca, gdym siedzał w domu swym, a starsi Judzcy siedzieli przedemną, tedy tam przypadła na mię ręka panującego Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'I widzałem, a oto podobieństwo na wejrzeniu jako ogień; od biódr jego na dół jako ogień, a od biódr jego w górę na wejrzeniu jako blask, i niby prędka światłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Tedy ściągnąwszy podobieństwo ręki, uchwycił mię za kędzierze głowy mojej, i podniósł mię duch między ziemią i między niebem, a przywiódł mię do Jeruzalemu w widzeniach Bożych, do wejścia bramy wewnętrznej, która patrzy ku północy, gdzie była stolica bałwana do gorliwości i zapalczywości pobudzająca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'A oto tam była chwała Boga Izraelskiego na wejrzeniu jako ona, którąm widział na polu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'I rzekł do mnie: Synu człowieczy! teraz podnieś oczy swe ku drodze na północy; a tak podniosłem oczy swe ku drodze na północy, a oto na północy był u bramy ołtarzowej on bałwan pobudzający do gorliwości w samem prawie wejściu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Wtem mi rzekł: Synu człowieczy! widziszże ty, co ci czynią, obrzydliwości wielkie, które tu czyni dom Izraelski? tak, że się oddalić muszę od świątnicy mojej; ale obróciwszy się ujrzysz obrzydliwości jeszcze większe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'I przywiódł mię do drzwi sieni, gdziem ujrzał, a oto dziura jedna była w ścianie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'I rzekł do mnie: Synu człowieczy! przekop teraz tę ścianę: i przekopałem ścianę, a oto drzwi jedne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'I rzekł do mnie: Wnijdź, a obacz te złe obrzydliwości, które tu oni czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Przetoż wszedłszy ujrzałem, a oto wszelakie podobieństwa płazu, i zwierząt obrzydłych, i wszelakich plugawych bałwanów domu Izraelskiego wyryte były na ścianie wszędy w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'A siedmdziesiąt mężów starszych z domu Izraelskiego, z Jazanijaszem, synem Safanowym, stojącym w pośród nich, stali przed nimi, mając każdy kadzielnicę swoję w ręcę swej, tak, że gęsty obłok kadzenia w górę wstępował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'I rzekł do mnie: A widziałżeś, synu człowieczy! co starsi domu Izraelskiego w ciemności czynią, każdy w pokojach swoich malowanych? Bo mówią: Nie widzi nas Pan, opuścił Pan tę ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Znowu rzekł do mnie: Jeszcze obróciwszy się ujrzysz obrzydliwości większe, które oni czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'I przywiódł mię do wrót bramy domu Pańskiego, która jest na półnpcy, a oto tam niewiasty siedziały, płacząc Tammusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'I rzekł mi: A widziałżeś, synu człowieczy? Ale obróciwszy się ujrzysz jeszcze większe obrzydliwości, niżeli te.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Tedy mię wprowadził do wnętrznej sieni domu Pańskiego, a oto u drzwi kościoła Pańskiego między przysionkim i ołtarzem było dwadzieścia i pięć mężów, których tyły były obrócone ku kościołowi Pańskiemu, a twarze ich na wschód, którzy się kłaniali przeciwko wschodowi słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'I rzekł mi: A widziałżeś, synu człowieczy? Izali to lekka rzecz jest domowi Judzkiemu, czynić takie obrzydliwości, jakie tu czynią? Bo napełniwszy ziemię nieprawością, obrócili się, aby mię draźnili, a oto przykładają latorośl winną do nosów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Przetoż i Ja postąpię z nimi wedłu zapalczywości; oko moje nie sfolguje ani się zmiłuję; i będą wołać do uszów moich głosem wielkim, a nie wysłucham ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Potem zawołał, gdziem ja słyszał, głosem wielkim, mówiąc: Hetmani, nastąpcie na to miasto, mając każdy broń swoję ku zabijaniu w ręce swej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'A oto sześć mężów przyszło drogą ku brami wyższej, która patrzy na północy, i miał każdy broń swoję ku wytraceniu w ręce swej; ale mąż jeden był w pośród nich odziany szatą lnianą, a kałamarz pisarski przy biodrach jego; i przyszedłszy stanęli u ołtarza miedzanego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'A chwała Boga Izraelskiego zstąpiła była z Cherubina, na którym była, do progu domu, i zawołała na męża onego odzianego szatą lnianą, przy którego biodrach był kałamarz pisarski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'I rzekł Pan do niego: Przejdź przez pośrodek miasta, przez pośrodek Jeruzalemu, a uczyń znak na czołach mężów, którzy wzdychają i narzekają nad wszystkiemi obrzydliwościami, które się dzieją w pośród niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'A onym rzekł, gdziem ja słyszał: Idźcie po mieście za nim; a zabijajcie; niech nie folguje oko wasze, ani się zmiłujcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Starca, młodzieńca, i pannę, i maluczkich, i niewiasty wybijcie do szczętu; ale do żadnego męża, na którymby był znak, nie przystępujcie, od świątnicy mojej poczniecie. A tak poczęli od onych mężów starszych, którzy byli przed domem Pańskim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, '(Bo im był rzekł: Splugawcie ten dom, a napełnijcie sieni pobitymi; idźcież.) A wyszedłszy zabijali w miście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'A gdy ich pozabijali, a jam pozostał, tedym padł na oblicze moje, i zawołałem a rzekłem: Ach panujący Panie! izali ty wytracisz wszystek ostatek Izraelski, wylewając popędliwość swoję na Jeruzalem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'I rzekł do mnie: Nieprawość domu Izraelskiego i Judzkiego nader jest bardzo wielka, i napełniona jest ziemia krwią, a miasto pełne jest przewrotności; bo mówili: Pan tę ziemię opuścił, a Pan nie widzi nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Przetoż i Ja toż uczynię, nie sfolguje oko moje, ani się zmiłuję, drogę ich na głowę ich obrócę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'A oto mąż on odziany szatą lnianą, przy którego biodrach był kałamarz, oznajmił to mówiąc: Uczyniłem tak, jakoś mi rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'I widziałem; a oto na rozpostarciu, które było nad głową Cherubinów, jakoby kamień szafirowy, na wejrzeniu jako podobieństwo stolicy, ukazało się nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Tedy rzekł do onego męża odzianego szatą lnianą, mówiąc: Wnijdź między koła pod Cherubinów, a napełń ręce swe węglem ognistym z pośród Cherubinów, i rozrzuć po mieście. I wszedł przed oczyma memi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, '(A Cherubowie stali po prawej stronie domu, gdy wchodził on mąż, a obłok napełnił sień wnętrzną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Bo gdy się była podniosła chwała Pańska z Cherubinów, ku progowi domu, tedy napełniony był dom obłokiem, a sień napełniona była jasnością chwały Pańskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'A szum skrzydeł Cherubinów słyszany był aż do sieni zewnętrznej, jako głos Boga wszechmocnego, gdy mówi.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Gdy tedy rozkazał onemu mężowi odzianemu w szatę lnianą, mówiąc: Weźmij ognia z pośrodku kół, z pośrodku Cherubinów: wszedł i stanął podle kół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Tedy wyciągnął Cherubin jeden rękę swą w pośród Cherubinów do onego ognia, który był w pośrodku Cherubinów, a wziąwszy podał go w rękę onego odzianego szatą lnianą, który wziąwszy go wyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Bo się ukazało na onych Cherubinach podobieństwo ręki człowieczej pod skrzydłami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Potemem wejrzał, a oto cztery koła podle Cherubinów, koło jedno podle jednego Cherubina, a tak każde koło podle każdego Cherubina, a podobieństwo kół jako barwa kanienia Tarsys;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'A na wejrzeniu miały jednakie podobieństwa one koła, jakoby było koło w pośrodku koła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Gdy chodziły, na cztery strony swoje chodziły; nie uchylały się, gdy szły, ale do onego miejsca, do którego się wódź obracał, za nim szły; nie uchylały się, gdy szły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'A wszytko ciało ich, i grzbiety ich, i ręce ich, i skrzydła ich, także i koła pełne były oczów około onych samych czterech, i kół ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'A koła one nazwał okręgiem, gdziem ja słyszał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'A każde zwierzę miało cztery twarze; twarz pierwsza była twarz Cherubinowa, druga twarz była twarz człowiecza, trzecia była twarz lwia, a czwarta była twarz orla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'I podnieśli się Cherubinowie. Toć są one zwierzęta, którem widział nad rzeką Chebar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'A gdy chodzili Cherubinowie, chodziły i koła podle nich; a gdy ponosili Cherubinowie skrzydła swoje, aby się wzbili od ziemi, nie odwracały się też koła od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Gdy oni stali, stały, a gdy się ponosili, podnosiły się też z nimi; bo duch zwierząt był w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'I odeszła chwała Pańska od progu domu, i stanęła nad Cherubinami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Gdy podnieśli Cherubinowie skrzydła swoje, a wzbili się od ziemi przed oczyma mojemi odchodząc, a koła przeciwko nim, i stanęli w wejściu bramy domu Pańskiego wschodniej, tedy chwała Boga Izraelskiego z wierzchu nad nimi była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Toć są one zwierzęta, którem widział pod Bogiem Izraelskim nad rzeką Chebar; i poznałem, iż to byli Cherubinowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Po cztery twarze miał każdy z nich, i po cztery skrzydła każdy z nich, a podobieństwo rąk ludzkich pod skrzydłami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'A podobieństwo twarzy ich było jako twarzy, którem widział u rzeki Chebar; także i oblicze ich takież było, i oni sami; każdy z nich prosto ku swej stronie chodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'I podniósł mię duch, a przywiódł mię do bramy domu Pańskiego wschodniej, która patrzy na wschód słońca; a oto w wejściu onej bramy było dwadzieścia i pięć mężów, między którymi widziałem Jazanijasza, syna Assurowego, i Pelatyjasza, syna Banaja szowego, książąt ludu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Tedy mi rzekł: Synu człowieczy! onić to są mężowie, którzy zamyślają o nieprawości, a radzą złą radę w tem mieście,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Mówiąc: Nie budujmy domów blisko; boby tak miasto było kotłem, a my mięsem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Dlatego prorokuj przeciwko nim, prorokuj, synu człowieczy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Tedy przypadł na mię duch Pański, i rzekł do mnie: Mów: Tak mówi Pan: Takeście mówili, domie Izraelski! bo co wam kolwiek przychodzi na myśl, to Ja znam;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Wielkieście mnóstwo pobili w tem mieście, a napełniliście ulice jego pobitymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Dlatego tak mówi panujący Pan: Którzy są pobici od was, którycheście składali w pośrodku jego, oni są mięsem, a miasto kotłem; ale was wywiodą z pośrodku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Baliście się miecza; ale miecz przywiodę na was, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'A wywiodę was z pośrodku jego, a podam was w ręce obcych, i wykonam nad wami sądy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Od miecza polężecie, na granicach Izraelskich osądzę was, i dowiecie się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Miasto nie będzie wam kotłem, ani wy będziecie w pośród jego mięsem; na granicach Izraelskich osądzę was,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'I dowiecie się, żem Ja Pan; ponieważeście w ustawach moich nie chodzili, a sądów moich nie czynili, aleście według sądów tych narodów, którzy około was są, czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'A gdym prorokował, tedy Pelatyjasz, syn Banajaszowy, umarł: dlatego upadłem na twarz moję, a wołając głosem wielkim, rzekłem: Ach, panujący Panie! do gruntu wygładzisz ostatki Izraelskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Synu człowieczy! bracia twoi, bracia twoi, powinowaci twoi, i wszystek dom Izraelski, wszystek mówię dom, cić są, którym mówili obywatele Jeruzalemscy: Oddalcie się od Pana; namci dana jest ta ziemia w osiadłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Przetoż mów: Tak mówi panujący Pan: Chociażem ich daleko zagnał między narody, i chociażem ich rozproszył po ziemiach, wszakże będę im świątnicą i przez ten mały czas w ziemiach, do których przyjdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Przetoż mów: Tak mówi panujący Pan: Zgromadzę was z narodów, a zbiorę was z ziem, do którycheście rozproszeni, i dam wam ziemię Izraelską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'I wnijdą tam, a zniosą wszystkie splugawienia jej, i wszystkie jej obrzydliwości z niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Bo im dam serce jedno, i ducha nowego dam do wnętrzności waszych, i odejmę sece kamienne z ciała ich, a dam im serce mięsiste,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'Aby w ustawach moich chodzili, a sądów moich strzegli, i czynili je; i będą ludem moim, a Ja będę Bogiem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Ale którychby serce chodziło za żądzami plugastw swoich, i obrzydliwości swoich, tych drogę obrócę na głowy ich, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Tedy podnieśli Cherubinowie skrzydła swoje, i koła z nimi, a chwała Boga Izraelskiego była nad nimi z wierzchu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'I odeszła chwała Pańska z pośrodku miasta, a stanęła na górze, która jest na wschód miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'A duch podniósł mię, i zaś mię przywiódł do ziemi Chaldejskiej do pojmanych, w widzeniu w Duchu Bożym. I odeszło odemnie widzenie, którem widział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'I mówiłem do pojmanych te wszystkie rzeczy Pańskie, które mi ukazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'I stało się słowo Pańskie do mnie mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Synu człowieczy! ty w pośrodku domu odpornego mieszkasz, którzy mają oczy, aby widzieli, a nie widzą, uszy mają, aby słyszeli, a nie słyszą; przeto, że domem odpornym są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Ty tedy, synu człowieczy! spraw sobie sprzęt przeprowadzenia, a przeprowadzaj się we dnie przed oczyma ich, a przeprowadzaj się z miejsca swego na miejsce inne przed oczyma ich, aza wżdy obaczą, acz domem odpornym są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'I wyniesiesz sprzęt swój, jako sprzęt przeprowadzenia, we dnie przed oczyma ich; a sam wynijdź w wieczór przed oczyma ich, jako wychodzą, którzy się przeprowadzają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Przed oczyma ich przekop sobie mur, a wynieś przezeń sprzęt twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Przed oczyma ich na ramionach nieś, z zmierzkiem wynieś, twarz swoję zakryj, a nie patrz na ziemię; bom cię dał za dziw domowi Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'I uczyniłem tak, jako mi rozkazano; sprzęt mój wyniosłem jako sprzęt prowadzącego się we dnie, a w wieczór przekopałem sobie mur ręką; z zmierzkiem wyniosłem go na ramieniu niosąc przed oczyma ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Znowu stało się słowo Pańskie do mnie rano, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Synu człowieczy! Izali nie rzekł do ciebie dom Izraelski, dom ten odporny: Cóż to czynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Rzeczże im, tak mówi panujący Pan: Na księcia, który jest w Jeruzalemie, ściąga się to brzemię, i na wszystek dom Izraelski, którzy są w pośród jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Rzeczże do nich: Jam jest dziwem waszym; jakom uczynił, tak się im stanie; przeprowadzą się, i w niewolę pójdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'A książę, który jest w pośrodku nich, na ramieniu poniesie sprzęt swój z zmierzkiem, i wynijdzie; mur przekopią, aby go wywiedli przezeń; twarz swoję zakryje, tak, że nie będzie widział ziemi okiem swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Bo rozciągnę nań sieć swoję, i pojmany będzie niewodem moim, i przywiodę go do Babilonu, do ziemi Chaldejskiej, a tej nie ogląda, i tam umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Także też wszystkich, którzy są około niego, pomoc jego, i wszystkie hufy jego rozproszę na wszystkie strony, i miecza dobędę za nimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'I poznają, żem Ja Pan, gdy ich rozproszę między narody, i rozwieję ich po ziemiach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Jednak zostawię z nich trochę mężów po mieczu, po głodzie i po morze, aby opowiadali wszystkie obrzydliwości swe między narodami, do których wnijdą, i poznają, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Znowu stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Synu człowieczy! chleb swój z strachem jedz i wodę twoję ze drżeniem i z smutkiem pij,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'A rzecz do ludu tej ziemi: Tak mówi panujący Pan o tych, którzy mieszkają w Jeruzalemie, o ziemi Izraelskiej: Chleb swój z smutkiem jeść, a wodę swą z trwogą pić będą, aby była ziemia jego złupiona z dostatków swoich dla bezprawia wszystkich mieszkających w niej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Także miasta, w których mieszkają, spustoszone będą, i ziemia spustoszeje; i dowiecie się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Stało się zaś słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Synu człowieczy! cóż to za przypowieść u was o ziemi Izraelskiej, iż mówicie: Przedłużąć się dni, a z tego widzenia nic nie będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Przetoż mów do nich: Tak mówi panujący Pan: Sprawię Ja to, iż ustanie ta przypowieść, a nie będą używać tej przypowieści więcej w Izraelu; powiedz im: I owszem, przybliżyły się te dni, i spełnienie wszelkiego widzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Bo nie będzie więcej żadnego marnego widzenia, ani wieszczby pochlebcy w pośrodku domu Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Przeto, że Ja Pan mówić będę, a którekolwiek słowo wyrzekę, stanie się; nie pójdzie w długą, ale za dni waszych, domie odporny! wyrzekę słowo, i wypełnię je, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Synu człowieczy! oto dom Izraelski mówią: To widzenie, które ten widzi, odwlecze się na wiele dni, a o dalekich czasach ten prorokuje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Przeto im rzecz: Tak mówi panujący Pan: Nie pójdzieć w długą żadne słowo moje; ale słowo, które wyrzekę, stanie się, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Synu człowieczy! prorokuj przeciw prorokom Izraelskim, którzy prorokują, a rzecz prorokującym z serca swego: Słuchajcie słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Tak mówi panujący Pan: Biada prorokom głupim, którzy idą za duchem swoim, choć nic nie widzieli!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Izraelu!Prorocy twoi są jako liszki na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Nie wstępujcie na przerwane miejsca, ani grodzcie płotu około domu Izraelskiego, żeby się mógł ostać w bitwie w dzień Pański.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Widzą marność i wieszczbę kłamliwą; powiadają: Pan mówi, choć ich Pan nie posłał; i cieszą lud, aby tylko utwierdzili słowo swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Izali widzenia marnego nie widzicie, a wieszczby kłamliwej nie opowiadacie? I mówicie: Pan mówił, chociażem Ja nie mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Przetoż tak mówi panujący Pan: Ponieważ mówicie marność, a widzicie kłamstwo, przetoż oto Ja jestem przeciwko wam, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Bo ręka moja będzie przeciwko prorokom, którzy widzą marność, a opowiadają kłamstwo; w zgromadzeniu ludu mego nie będą, a w poczet domu Izraelskiego nie będą wpisani, i do ziemi Izraelskiej nie wnijdą; a dowiecie się, żem Ja panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Przeto, przeto mówię, że w błąd wprowadzili lud mój, mówiąc: Pokój, choć nie było pokoju; jeden zaiste zbudował ścianę glinianą, drudzy ją tynkowali wapnem nieczynionem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Mówże do tych, którzy ją tynkują wapnem nieczynionem: Upadnie to, przyjdzie deszcz gwałtowny, a wy, kamienie gradowe! spadniecie, i wiatr wichrowaty rozwali ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'A oto gdy upadnie ona ściana, izali wam nie rzeką: Gdzież jest ono tynkowanie, któremeście tynkowali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Prztoż tak mówi panujący Pan! Rozwalę ją, mówię, wiatrem wichrowatym w zapalczywości mojej, i deszcz gwałtowny w popędliwości mojej przyjdzie, a kamienie gradowe w rozgniewaniu mojem na zniszczenie jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Bo obalę tę ścianę, którąście potynkowali wapnem nieczynionem, a zrównam ją z ziemią, tak, że odkryty będzie grunt jej, i upadnie, i skażeni będziecie w pośrodku jej, i dowiecie się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'A gdy wykonam popędliwość moję nad tą ścianą, i nad tymi, którzy ją tynkowali wapnem nieczynionem, rzekę do was: Niemasz już onej ściany, niemasz i tych, którzy ją tynkowali,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'To jest, proroków Izraelskich, którzy prorokują o Jeruzalemie, i ogłaszają mu widzenie pokoju, choć niemasz pokoju, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Ale ty, synu człowieczy! obróć twarz twoję przeciwko córkom ludu swego, które prorokują z serca swego, a prorokuj przeciwko nim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'I rzecz: Tak mówi panujący Pan: Biada tym, które szyją wezgłówka pod wszelkie łokcie rąk ludu mojego, a czynią duchny na głowy wszelkiego wzrostu, aby łowiły dusze! izali łowić macie dusze ludu mego, abyście się żywić mogły?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Bo mię podawacie w lekkość u ludu mego dla garści jęczmienia, i dla kęsa chleba, zabijając dusze, które nie umrą, a ożywiając dusze, które żywe nie będą, kłamiąc ludowi memu, którzy słuchają kłamstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Dlatego, tak mówi panujący Pan: Oto Ja będę przeciwko wezgłówkom waszym, któremi wy tam dusze łowicie, abyście je zwiodły; bo je stargnę z ramion waszych, a wypuszczę dusze, które wy łowicie, abyście je zwiodły;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'I rozerwę duchny wasze, a wybawię lud mój z ręki waszej, abyście ich więcej nie mogły łowić ręką swoją; a dowiecie się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Przeto, że zasmucacie serce sprawiedliwego kłamstwy, chociażem go Ja nie zasmucił, a zmacniacie ręce niezbożnego, aby się nie odwrócił od złej drogi swojej, ożywiając go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Przetoż nie będziecie więcej widywać marności, ani wieszczby więcej prorokować będziecie; bo wyrwę lud mój z ręki waszej, a dowiecie się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Potem przyszedłszy do mnie mężowie z starszych Izraelskich, usiedli przedemną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'I stało sie słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Synu człowieczy! ci mężowie złożyli plugawe bałwany swoje do serca swego, a nieprawość, która im jest ku obrażeniu. położyli przed twarzą swoją; mniemaszże, iż mię uprzejmie pytają o radę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Dlategoż powiedz im, i mów do nich: Tak mówi panujący Pan: Ktokolwiek z domu Izraelsiego położył plugawe bałwany swoje w sercu swojem, a nieprawość, która mu jest ku obrażeniu, położył przed twarzą swoją, a przyszedłby do proroka, Ja Pan odpowiem temu, który przyjdzie, o mnóstwie plugawych bałwanów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Abym ułapał dom Izraelski w sercu ich, że się odwrócili odemnie od plugawych bałwanów swoich wszyscy zgoła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Przetoż rzecz do domu Izraelskiego: Tak mówi panujący Pan: Nawróćcie się, a cofnijcie się od plugawych bałwanów waszych, i od wszystkich obrzydliwości waszych odwróćcie twarz swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Bo ktobykolwiek z domu Izraelskiego i z przychodniów, którzy mieszkają w Izraelu, odwrócił się od naśladowania mnie, a położyłby plugawe bałwany swoje w sercu swem, i nieprawość, która mu jest ku obrażeniu, położyłby przed twarz swoją, i przyszedł by do proroka, aby mię przezeń pytał, Ja Pan odpowiem mu sam przez się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'I postawię oblicze moje przeciw temu mężowi, i dam go na znak, i na przysłowie, a wytracę go z pośrodku ludu mojego; i dowiecie się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'A gdyby się prorok dał zwieść, aby mówił słowo, Ja Pan zwiodłem proroka onego, i wyciągnę nań rękę swoję, i wygładzę go z pośrodku ludu mego Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'I tak poniosą nieprawość swoję; jaka jest kaźń na tego, któryby się pytał, taka też kaźń na proroka będzie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Aby więcej nie błądził dom Izraelski odemnie, a nie mazali się więcej żadnemi przestępstwami swojemi, aby byli ludem moim, a Ja abym był Bogiem ich, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Znowu stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Synu człowieczy! gdyby ziemia zgrzeszyła przeciwko mnie, dopuszczając się przestępstwa, tedy jeźlibym wyciągnął rękę moję na nią, a złamałbym jej łaskę chleba, i posłałbym na nią głód, i wytraciłbym z niej ludzi i zwierzęta;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'Choćby byli w pośrodku niej ci trzej mężowie, Noe, Danijel i Ijob, oni w sprawiedliwości swojej wybawiliby dusze swe, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Także jeźlibym zły zwierz przepuścił na ziemię, a osierociłby ją, i byłaby spustoszona, żeby jej nikt przechodzić nie mógł dla zwierza,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Jako żyję Ja, mówi panujący Pan, że choćby ci trzej mężowie byli w pośrodku jej, żadną miarąby nie wybawili synów ani córek: oniby tylko sami wybawieni byli, leczby ziemia spustoszona była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Albo jeźlibym przywiódł miecz na tę ziemię, a rzekłbym mieczowi: Przejdź przez tę ziemię, abym wytracił z niej ludzi i zwierzęta,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'Jako żyję Ja, mówi panujący Pan, że choćby ci trzej mężowie byli w pośrodku jej, żadną miarąby nie wybawili synów ani córek, aleby oni tylko sami byli wybawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Albo posłałlibym mór na tę ziemię, i wylałbym popędliwość swoję na nią ku wytraceniu, aby z niej ludzie i zwierzęta byli wytraceni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Że choćby Noe, Danijel i Ijob byli w pośrodku jej, jako żyję Ja, mówi panujący Pan, żadną miarąby ani syna ani córki nie wybawili, oniby tylko w sprawiedliwości swojej wybawili dusze swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Owszem, tak mówi panujący Pan: Choćbym cztery kaźni moje ciężkie, miecz, i głód, i zły zwierz, i mór posłał na Jeruzalem, abym wytracił z niego ludzi i zwierzęta,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'A oto jeźliby zostali w nim, którzyby tego uszli, a wywiedzeni byli synowie albo córki, oto i oni muszą iść do was; i oglądacie drogę ich, i sprawy ich, i ucieszycie się nad tem złem, które przywiodę na Jeruzalem, nad wszystkiem, co przywiodę na nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'A tak ucieszą was, gdy ujrzycie drogę ich i sprawy ich; i zrozumiecie, żem to wszystko nie darmo uczynił, com uczynił w nim, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Tedy się stało słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Synu człowieczy! cóż jest drzewo macicy winnej przeciwko wszelkiemu innemu drzewu, albo przeciwko latoroślom drzewa leśnego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Izali wezmą z niego drzewo ku urobieniu czego? Izali urobią z niego kołek do zawieszania na nim jakiego naczynia?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Oto ogniowi podane bywa na strawienie; gdy oba końce jego ogień strawi, a pośrodek jego ogore, azaż się na co przyda?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Oto póki było całe, nic nie mogło być z niego urobione; dopieroż gdy je ogień strawił, a spaliło się, na nic się więcej nie przyda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Przetoż tak mówi panujący Pan: Jako jest drzewo macicy między drzewem leśnem, którem podał ogniowi na strawienie, takem podał obywateli Jeruzalemskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Bo postawię oblicze swoje przeciwko nim; z jednego ognia wyjdą, a drugi ogień strawi ich: i dowiecie się, żem Ja Pan, gdy postawię twarz swoję przeciwko nim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'A podam ziemię ich na spustoszenie, przeto, iż się dopuścili przestępstwa, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Synu człowieczy! oznajmij Jeruzalemowi obrzydliwości jego, i rzecz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'Tak mówi panujący Pan do córki Jeruzalemskiej: Obcowanie twoje i ród twój jest z ziemi Chananejskiej; ojciec twój jest Amorejczyk, a matka twoja Hetejka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'A narodzenie twoje takie: W dzień, któregoś się urodziła, nie urzniono pępka twego, i wodą cię nie obmyto dla ochędożenia, ani cię solą posolono, ani w pieluchy uwiniono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Nie zlitowało się nad tobą oko, abyć uczyniło jedno z tych, ulitowawszy się ciebie; ale cię porzucono na polu, przeto, żeś była obmierzła w dzień, któregoś się urodziła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'A idąc mimo cię, i widząc cię ku podeptaniu podaną we krwi twojej, rzekłem ci: Żyj we krwi twojej; rzekłem ci, mówię: Żyj we krwi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Rozmnożyłem cię na tysiące, jako urodzaj polny, i rozmnożonaś, i stałaś się wielką, a przyszłaś do bardzo wielkiej ozdoby; piersi twoje odęły się, a włosy twoje urosły, chociażeś była naga i odkryta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Prztoż idąc mimo cię, a widząc cię, że oto czas twój, czas miłości, rozciągnąłem podołek mój na cię, i nakryłem nagość twoję, i obowiązałem ci się przysięgą, a wszedłem w przymierze z tobą, mówi panujący Pan, i stałaś się moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'I omyłem cię wodą, a spłukawszy krew twoję z ciebie, pomazałem cię olejkiem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Nadto przyodziałem cię szatą haftowaną, i obułem cię w kosztowne trzewiki, i opasałem cię bisiorem, a przyodziałem cię szatą jedwabną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'I przybrałem cię w ochędostwo, a dałem manele na ręce twoje, i łańcuch złoty na szyję twoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Dałem też naczelnik na czoło twoje, a nausznice na uszy twoje,i koronę ozdobną na głowę twoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'A tak byłaś ozdobiona złotem i srebrem, a odzienie twoje było bisior, i szata jedwabna, i haftowana; jadałaś bułkę i miód, i oliwę, a byłaś nader piękną, i szczęśliwieć się powodziło w królestwie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Tak, że się rozeszła powieść o tobie między narodami dla piękności twojej; boś doskonałą była dla sławy mojej, którąm był włożył na cię, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Aleś ufała w piękności twojej, i płodziłaś nierząd, będąc tak sławną; boś płodziła nierząd z każdym mimo cię idącym, każdy snadnie użył piękności twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'A nabrwaszy szat swoich naczyniłaś sobie wyżyn rozmaitych farb, a płodziłaś nierząd przy nich, któremu podobny nigdy nie przyjdzie, ani będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Nadto nabrawszy klejnotów ozdoby swojej ze złota mego i z srebra mego, którem ci był dał, naczyniłaś sobie obrazów pogłowia męskiego, i płodziłaś z nimi nierząd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Wzięłaś też szaty swe haftowane, a przyodziałaś je, olejek mój i kadzidło moje kładłaś przed nie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Nawet i chleb mój, którem ci dał, bułkę i oliwę, i miód, którymem cię karmił, kładłaś przed nie na wonność przyjemną, i było tak, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Brałaś też synów swoich, i córki swoje, którycheś mi narodziła, a oneś im ofiarowała ku pożarciu; izali to jeszcze małe wszeteczeństwa twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Do tego i synóweś moich zabijała, a dawałaś ich, aby ich przenoszono przez ogień im kwoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Nadto przy wszystkich obrzydliwościach swoich, i wszeteczeństwach swoich nie pamiętałaś na dni młodości twojej, gdyś była nagą i odkrytą, podaną na podeptanie we krwi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Nadto mimo wszystkich onych złości twoich (Biada, biada tobie! mówi panujący Pan.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Zbudowałaś sobie dom nierządny, i wystawiłaś sobie wyżynę w każdej ulicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Po wszystkich rozstaniach dróg pobudowałaś wyżyny swoje, a uczyniłaś obmierzłą piękność swoję, rozkładając nogi swoje każdemu mimo idącemu, i rozmnożyłaś wszeteczeństwa swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Boś nierząd płodziła z synami Egipskimi, sąsiadami twymi wielkich ciał, a rozmnożyłaś wszeteczeństwa twe, abyś mię do gniewu pobudzała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Przetoż otom wyciągnął rękę moję na cię, a uminiejszyłem obroku twego, i podałem cię na wolę nienawidzących cię córek Filistyńskich, które się wstydzą za złe drogi twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Nadto płodziłaś nierząd z synami Assyryjskimi, przeto, żeś się nie mogła nasycić, a nierząd płodząc z nimi, i takeś się nie nasyciła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'A tak rozmnożyłaś wszeteczeństwo swe w ziemi Chananejskiej i Chaldejskiej, a i tak nie nasyciłaś się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'O jako jest zmamione serce twoje! mówi panujący Pan, ponieważ się dopuszczasz tych postępków niewiasty nierządnej i wszetecznej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Budując sobie nierządne domy na rozstaniu każdego gościńca, a wyżynę sobie stawiając w każdej ulicy, owszem pogardzając zapłatą nie jesteś ani jako wszetecznica,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Ani jako niewiasta cudzołożąca, która mimo męża swego obcych przypuszcza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Wszystkim wszetecznicom dawają zapłatę; aleś ty dawała zapłatę swoję wszystkim zalotnikom twoim, i dawałaś im upominki, aby chodzili do ciebie zewsząd na wszeteczeństwa z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'A tak znajduje się przy tobie przeciwna rzecz od innych niewiast we wszeteczeństwach twoich, ponieważ cię dla wszeteczeństwa nie szukają; ale ty dajesz zapłatę, a nie tobie zapłatę dawają, co się opak dzieje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Przetoż, o wszetecznico! słuchaj słowa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Tak mówi panujący Pan: Dlatego, iż się wylała sprośność twoja, i odkryła się nagość twoja we wszeteczeństwach twoich z zalotnikami twoimi i ze wszystkimi plugawemi bałwanami obrzydliwości twoich, i dla rozlania krwi synów twoich, którycheś im dał a.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'Przetoż oto Ja zgromadzę wszystkich zalotników twoich, z którymiś obcowała, i wszystkich, którycheś miłowała, ze wszystkimi, coś ich nienawidziała, i zgromadzę ich przeciwko tobie zewsząd, i odkryję nagość twoję przed nimi, aby widzieli wszystkę na gość twoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'I osądzę cię sądem cudzołożnic i krew rozlewających, i podam cię na śmierć gniewu i zapalczywości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Bo cię podam w ręce ich, i zburzą dom twój nierządny, a rozrzucą wyżyny twoje, i zewloką cię z szaty twojej, i pobiorą klejnoty ozdoby twojej, i zostawią cię nagą i odkrytą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'I przywiodą na cię gromadę, i ukamionują cię kamieniem, i przebiją cię mieczami swemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'I popalą domy twoje ogniem, a uczynią nad tobą sąd przed oczyma wielu niewiast. A tak uczynię wstręt wszeteczeństwu twemu, i nie będziesz więcej dawała zapłaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'A tak odpocznie sobie gniew mój na tobie, i odstąpi zapalczywość moja od ciebie, i uspokoję się, a nie będę się więcej gniewał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Dlatego, żeś nie pamiętała na dni młodości twojej, aleś mię tem wszystkiem draźniła, przetoż oto i Ja obróciłem drogę twoję na głowę twoję, mówi panujący Pan, tak, że nie będziesz nierządu płodziła, ani jakich obrzydliwości swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Oto ktokolwiek przez przypowieści mówi, na cię przypowieści obróci, mówiąc: Jaka matka, taka córka jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Córką matki twojej jesteś, która sobie zbrzydziła męża swego i dziatki swoje; a siostrą obu sióstr swoich jesteś, które sobie zbrzydziły mężów swoich i dziatki swoje. Matka wasza jest Hetejka, a ojciec wasz Amorejczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Ale siostra twoja starsza, która siedzi po lewicy twojej, jest Samaryja i córki jej; a siostra twoja młodsza niż ty, która siedzi po prawicy twojej, jest Sodoma i córki jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Aczkolwiekeś po drogach ich nie chodziła, aniś według obrzydliwości ich czyniła, obrzydziwszy to sobie jako rzecz małą, przecięś się bardziej niż one popsowała na wszystkich drogach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Jako żyję Ja, mówi panujący Pan, że Sodoma siostra twoja i córki jej nie czyniły, jakoś ty czyniła i córki twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Oto ta była nieprawość Sodomy, siostry twojej, pycha, sytość chleba, i obfitość pokoju; co ona mając i córki jej, ręki jednak ubogiego i nędznego nie posilała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Owszem, wyniósłszy się, czyniły obrzydliwość przed obliczem mojem; przetożem je zniósł, jako mi się zdało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Samaryja także ani połowy grzechów twoich nie grzeszyła; boś rozmnożyła obrzydliwości twoje nad nią; a tak usprawiedliwiłaś siostry twoje obrzydliwościami twojemi, któreś czyniła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Ponośże i ty hańbę swoję, którąś przysądziła siostrom swoim, dla grzechów swych, któremiś obrzydliwości czyniła bardziej niż one, sprawiedliwszemić były niżeli ty; i ty, mówię, zawstydź się, a noś na sobie hańbę swoję, gdyżeś usprawiedliwiła sios try twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Przywrócęli zaż więźniów ich, to jest, więźniów Sodomy i córek jej, i więźniów Samaryji i córek jej; tedyć też przywiodę pojmanych więźniów twoich w pośrodku ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Abyś tak nosiła hańbę twoję, a wstydziła się za wszystko, coś czyniła, a tak abyś je ucieszyła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Jeźliżeć siostry twoje, Sodoma i córki jej, wrócą się do pierwszego stanu swego, także Samaryja i córki jej wrócą się do pierwszego stanu swego; tedy się też i ty z córkami swemi nawrócisz do pierwszego stanu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Ponieważ Sodoma siostra twoja nie była powieścią w ustach twoich w dzień pychy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'Pierwej niż była objawiona złość twoja, jako za czasu oblężenia od córek Syryjskich, i wszystkich, którzy są około nich, córek Filistyńskich, które cię niszczyły ze wszystkich stron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Niecnotę twoję i obrzydliwość twoje ponosisz, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Bo tak mówi panujący Pan: Tak uczynię z tobą, jakoś uczyniła, gdyś wzgardziła przysięgą, i złamała przymierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Wszakże wspomnę na przymierze moje z tobą, uczynione za dni młodości twojej, i stwierdzę z tobą przymierze wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'I wspomnisz na drogi twoje, i zawstydzisz się, gdy przyjmiesz siostry twoje starsze nad cię, i młodsze niż ty, i dam ci je za córki, ale nie według przymierza twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'A tak utwierdzę przymierze moje z tobą, a dowiesz się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Abyś wspomniała, i zawstydziła się, i nie mogła więcej otworzyć ust dla wstydu swego, gdy cię oczyszczę od wszystkiego, coś czyniła, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Stało się zaś słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Synu człowieczy! zadaj zagadkę, a mów w podobieństwie o domu Izraelskim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'I rzecz: Tak mówi panujący Pan: Orzeł wielki z wielkiemi skrzydłami i z długiemi pióry, pełen pierza pstrego, przyleciał na Liban, i wziął wierzch cedru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Wierzch młodocianych latorośli jego ułamał, i zaniósł go do ziemi kupieckiej, a w mieście kupieckiem położył go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Wziął też nasienia onej ziemi, a wsadził je na polu urodzajnem, a wsadził je bardzo ostrożnie przy wodach wielkich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Które weszłoby było, i byłoby winną macicą bujną, choć niskiego wzrostu; i byłyby latorośli jej ku niemu, a korzenie jej byłyby mu poddane. A tak byłoby było macicą winną, któraby była wydała latorośli, i wypuściła gałązki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Ale był orzeł jeden wielki z wielkiemi skrzydłami i z gęstem pierzem, a oto ona winna macica przypoiła korzenie swoje ku niemu, i gałązki swe rozciągnęła do niego, aby ją odwilżał z brózd sadu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Choć na polu dobrem przy wodach wielkich wsadzona była, aby wypuściła latorośli, i przyniosła owoce, i była macicą winną wspaniałą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Rzeczże tedy: Tak mówi panujący Pan: Izali się jej poszczęści? Izali orzeł korzenia jej nie wyrwie, i owocu jej nie oberwie, i nie posuszy? Izali wszystkich latorośli wyrosłych z niej nie ususzy? Izali z wielką mocą a z obfitym ludem jej nie wygładzi z korzenia jej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Oto jakożkolwiek wsadzona jest, izali się jej poszczęści? Izali do szczętu nie uschnie, skoro się jej dotknie wiatr wschodni? Izali przy brózdach, przy którch się przyjęła, nie uschnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Zatem stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Mów teraz do domu odpornego: Azaż nie wiecie, co to jest? Zatem mów: Oto przyciągnął król Babiloński do Jeruzalemu, i zabrał króla jego, i książąt jego, i zawiódł ich z sobą do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Wziął też z nasienia królewskiego, a uczyniwszy z nim przymierze, zawiązał go przysięgą, i mocnych z onej ziemi zabrał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'Aby było królestwo zniżone, przeto, żeby się nie wyniosło, żeby tak strzegąc przymierza jego, stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Ale mu się sprzeciwił, posławszy posłów swych do Egiptu, aby mu dał koni i wiele ludu. Izali się to poszczęści? Izali pomsty ujdzie ten, co tak uczynił? Ten, który wzrusza przymierze, izali pomsty ujdzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Jako żyję Ja, mówi panujący Pan, że na miejscu króla tego, który go królem uczynił, którego przysięgą wzgardził, a którego przymierze wzruszył, u niego w Babilonie umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Ani mu Farao z wielkim wojskiem i z ludem gęstym co pomoże na wojnie, gdy usypie wał, i porobi szańce, aby wykorzenił mnóstwo ludu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Ponieważ pogardził przysięgą, zrzuciwszy przymierze; bo oto dał na to rękę swą, a przecie to wszystko uczyni; nie ujdzie pomsty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Dlatego tak mówi panujący Pan: Jako żyję Ja, że przysięgę swoję, którą wzgardził, i przymierze moje, które wzruszył, pewnie obrócę na głowę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Bo rozciągnę nań sieć moję, a będzie niewodem moim pojmany, i zawiodę go do Babilonu, a tam się z nim rozsądzę o występek jego, którym wystąpił przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'A wszyscy też, którzy uciekli od niego ze wszystkiemi hufami jego, od miecza polegną, a pozostali na wszystkie strony rozproszeni będą, a dowiecie się, że Ja Pan mówiłem to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Tak mówi panujący Pan: Wszakże wezmę z wierzchu tego wysokiego cedru, i wsadzę; z wierzchu młodocianych latorośli jego młodą latorostkę ułamię, a wszczepię ją na górze wysokiej i wyniosłej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Na wysokiej górze Izraelskiej wszczepię ją, i wypuści gałązki, i wyda owoc, i będzie cedrem zacnym; i będzie pod nim mieszkać wszelkie ptastwo, i wszystko, co ma skrzydła, pod cieniem gałęzia jego mieszkać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'A tak poznają wszystkie drzewa polne, żem Ja Pan poniżył drzewo wysokie, a wywyższyłem drzewo niskie, ususzyłem drzewo zielone, a uczyniłem, że zakwitło drzewo suche. Ja Pan rzekłem to, i uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Cóż wam po tem, iż używacie tej przypowieści o ziemi Izraelskiej mówiąc: Ojcowie jedli jagodę cierpką, a synów zęby drętwieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Jako żyję Ja, mówi panujący Pan, że wy nie będziecie więcej mogli używać tej przypowieści w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Oto dusze wszystkie moje są, jako dusza ojcowska tak i dusza synowska moje są; dusza, która grzeszy, ta umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Bo byłliby mąż sprawiedliwy, a czyniłby sąd i sprawiedliwość,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'Któryby na górach nie jadał, a oczówby swych nie podnosił do plugawych bałwanów domu Izraelskiego, a żonyby bliźniego swego nie zmazał, i do niewiasty dla nieczystoty oddalonej nie przystąpił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'Któryby nikogo nie uciskał, zastawby dłużnikowi swemu wracał, cudzegoby gwałtem nie brał, chlebaby swego łaknącemu udzielał, a nagiegoby szatą przyodziewał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Któryby na lichwę nie dawał, i płatuby nie brał, od nieprawościby odwracał rękę swoję, a sądby sprawiedliwy czynił między mężem a mężem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'Któryby w ustawach moich chodził, a sądówby moich przestrzegał, czyniąc, co jest prawego: ten sprawiedliwy pewnie żyć będzie, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'A gdyby spłodził syna łotra, krew wylewającego, któryby czemkolwiek z tych rzeczy bratu szkodził,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'A tegoby wszystkiego nie czynił, owszemby i na górach jadał, i żonęby bliźniego swego zmazał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Ubogiegoby i nędznego uciskał, co cudzego jest, gwałtemby zabierał, zastawuby nie wracał, a do plugawych bałwanów podnosiłby oczy swoje, i obrzydliwościby czynił,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Na lichwęby dawał, i płat brał, izali żyć będzie? Nie będzie żył; ponieważ te wszystkie obrzydliwości czynił: śmiercią umrze, krew jego na nim będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'A oto jeżeliby spłodził syna, któryby widział wszystkie grzechy ojca swego, które czynił, a widząc nie czyniłby tak;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Na górachby nie jadał, a oczówby swych nie podnosił do plugawych bałwanów domu Izraelskiego, żonyby bliźniego swego nie zmazał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'I nikogoby nie uciskał, zastawuby nie zatrzymywał, a cudzegoby gwałtem nie brał, chlebaby swego łaknącemu udzielał, a nagiegoby szatą przyodział,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Od nieprawegoby odwrócił rękę swoję, lichwyby i płatu nie brał, sądyby moje czynił, w ustawachby moich chodził: ten nie umrze dla nieprawości ojca swego, ale pewnie żyć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Lecz ojciec jego, przeto, że czynił krzywdę, co jest cudzego, bratu gwałtem brał, a to, co jest dobrego, nie czynił w pośrodku ludu swego: przetoż oto umrze dla nieprawości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Ale mówicie: Czemuż? Izali nie poniesie syn nieprawości ojcowskiej? Gdy syn sąd i sprawiedliwość czyni, wszystkich ustaw moich strzeże i czyni je, pewnie żyć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Dusza, która grzeszy, ta umrze; ale syn nie poniesie nieprawości ojcowskiej, ani ojciec poniesie nieprawości synowskiej; sprawiedliwość sprawiedliwego przy nim zostanie, a niepobożność niepobożnego nań przypadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'A jeźliby się niepobożny odwrócił od wszystkich grzechów swoich, które czynił, a strzegłby wszystkich ustaw moich, i czyniłby sąd i sprawiedliwość, pewnie żyć będzie, nie umrze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Żadne przestępstwa jego, których się dopuścił, nie będą mu przypominane; w sprawiedliwości swej, którąby czynił, żyć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Azaż Ja się kocham w śmierci niepobożnego? mrwi panujący Pan. Izali nie raczej, gdy się odwróci od dróg swoich, aby żył?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Ale jeźliby się odwrócił sprawiedliwy od sprawiedliwości swojej, a czyniłby nieprawość, czyniąc według wszystkich obrzydliwości, które czyni niezbożny, izali taki żyć będzie? Wszystkie sprawiedliwości jego, które czynił, nie będą wspominane; dla przestępstwa swego, które popełniał, i dla grzechu swego, którego się dopuścił, dla tych rzeczy umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'A iż mówicie: Nie prosta jest droga Pańska; słuchajcież teraz, o domie Izraelski! izali droga moja nie jest prosta? Izali drogi wasze nie są krzywe?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Gdyby się odwrócił sprawiedliwy od sprawiedliwości swojej, a czyniąc nieprawość w temby umarł, dla nieprawości swojej, którą czynił, umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Ale gdyby się odwrócił niezbożny od niezbożności swojej, której się dopuścił, a czyniłby sąd i sprawiedliwość, ten duszę swoję zachowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Bo obaczywszy się odwrócił się od wszystkich występków swoich, których się dopuszczał, pewnie żyć będzie, nie umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'A przecie mówi dom Izraelski: Nie prosta jest droga Pańska; izali drogi moje nie są proste, o domie Izraelski? Izali nie raczej drogi wasze są krzywe?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'A przetoż każdego z was według dróg jego sądzić będę, o domie Izraelski! mówi panujący Pan. Nawróćcież się, a odwróćcie się od wszystkich występków waszych, aby wam nieprawość nie była na obrażenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Odrzućcie od siebie wszystkie przestępstwa wasze, którycheście się dopuszczali, a uczyńcie sobie serce nowe i ducha nowego. I przeczże macie umrzeć, o domie Izraelski?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Albowiem się Ja nie kocham w śmierci umierającego, mówi panujący Pan; nawróćcież się tedy, a żyć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'A ty uczyń narzekanie nad książętami Izraelskimi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'A mów: Cóż była matka twoja? Lwica między lwami leżąca, która w pośrodku lwiąt wychowywała szczenięta swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'A gdy odchowała jedno z szczeniąt swoich, stało się lwem, tak, że nauczywszy się chwytać łupu pożerał i ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'To gdy usłyszały o nim narody, w jamie ich pojmany jest, a zawiedziony w łańcuchach do ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Co widząc lwica, że nadzieja jej, którą miała, zginęła, wziąwszy jedno z szczeniąt swoich, lwem je uczyniła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Który chodząc w pośrodku lwów stał się lwem, a nauczywszy się chwytać łupu pożerał i ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Poburzył też pałace ich, i miasta ich spustoszył, tak, iż i ziemia i pełność jej od głosu ryku jego spustoszała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'I zeszły się przeciwko niemu narody z okolicznych krain, i zarzucili nań sieci swoje; a tak w jamie ich pojmany jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'I wsadzili go do klatki w łańcuchach, i przywiedli go do króla Babilońskiego, i wprowadzili go do więzienia ciężkiego, aby więcej nie był słyszany głos jego po górach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Matka twoja była czasu pokoju twego jako winna macica przy wodach szczepiona; płodną i gałęzistą była dla wód obfitych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'I miała rózgi mocne na sceptry panujących, a wywyższył się wzrost jej między gęstemi gałęziami, tak, że była okazała dla wysokości swojej, i dla mnóstwa latorośli swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Ale w rozgniewaniu wyrwana będąc, na ziemię porzucona jest, a wiatr wschodni ususzył owoc jej; obłamane są i poschły rózgi mocy jej, ogień pożarł je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'A teraz wszczepiona jest na puszczy w ziemi suchej i pragnącej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Nadto wyszedł ogień z rózgi latorośli jej, a pożarł owoc jej, tak, że niemasz na niej rózgi mocnej dla sceptru panującego. Toć jest narzekanie, i będzie narzekaniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'I stało się roku siódmego, miesiąca piątego, dziesiątego dnia tegoż miesiąca, przyszli niektórzy z starszych Izraelskich, aby się radzili Pana; i usiedli przedemną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Tedy się stało słowo Pańskie do mnie, mówąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Synu człowieczy! mów do starszych Izraelsich, a powiedz im: Tak mówi panujący Pan: Izali wy przychodzicie, abyście się mnie radzili? Jako żyję Ja, że się wy mnie nie radzicie, mówi panujący Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Izali się za nich zastawiać będziesz? Izali się za nich zastawiać będziesz, synu człowieczy? Oznajmij im raczej obrzydliwości ojców ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'A rzecz do nich: Tak mówi panujacy Pan: Tego dnia, któregom wybrał Izraela, podniosłem rękę moję nasieniu domu Jakóbowego, i dałem się im poznać w ziemi Egipskiej; podniosłem rękę moję dla nich, mówiąc: Jam Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'Onego dnia podniosłem rękę moję dla nich, że ich wywiodę z ziemi Egipskiej do ziemi, którąm im upatrzył, opływającej mlekiem i miodem, która jest ozdobą wszystkich ziem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'I rzekłem im: Każdy z was niech porzuci obrzydliwości oczów swoich, a nie kalajcie się plugawemi bałwanami egipskiemi; bom Ja Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Ale mi byli odpornymi, i nie chcieli mię słuchać; żaden z nich obrzydliwości oczów swoich nie odrzucił, i plugawych bałwanów egipskich nie opóścił; prztożem rzekł: Wyleję gniew mój na nich, a wypęłnie popędliwość moję nad nimi w pośrodku ziemi egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'A wszakżem uczynił dla imienia mego, aby nie było zelżone przed oczyma tych narodów, między którymi oni byli, przed których oczyma dałem się im poznać, że ich chcę wywieść z ziemi egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'A tak wywiodłem ich z ziemi egipskiej, i przyprowadziłem ich na puszczę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'I dałem im ustawy moje, i sądy moje podałem im do wiadomości; które jeźliby człowiek zachowywał, żyć w nich będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Nadto i sabaty moje dałem im, aby były znakiem między mną i między nimi, aby wiedzieli, żem Ja jest Pan, który ich poświęcam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Ale mi się odpornym stał dom Izraelski na puszczy; w ustawach moich nie chodzili, i sądy moje odrzucili, które jeźliby człowiek czynił, żyć w nich będzie. Sabaty też moje bardzo zgwałcili; prztożem mówił, iż wleję popędliwość moję na nich na pus zczy, abym ich wygubił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Leczem uczynił dla imienia mego, aby nie było zelżone przed oczyma tych narodów przed którychem ich oczyma wywiódł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'A wszakżem podniósł rękę moję dla nich na tej puszczy, że ich nie wprowadzę do ziemi, którąm im był dał, opływającej mlekiem i miodem, i która jest ozdobą wszystkich ziem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Ponieważ sądy moje odrzucili, a w ustawach moich nie chodzili, i sabaty moje pogwałcili, a że serce ich za plugawemi bałwanami chodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Ale im przecie przepuściło oko moje, tak, żem ich nie wytracił, i nie wygładził do szczętu na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'I mówiłem do synów ich na tej puszczy: W ustawach ojców waszych nie chodźcie, i sądów ich nie przestrzegajcie, ani się plugawemi bałwanami ich kalajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Jam Pan, Bóg wasz; w ustawach moich chodźcie, a sądów moich strzeżcie, i czyńcie ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Sabaty też moje święćcie, i będą znakiem między mną i między wami, abyście wiedzieli żem Ja Pan, Bóg wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Lecz mi byli odpornymi ci synowie; w ustawach moich nie chodzili, i sądów moich nie przestrzegali, aby je czynili, (które jeźliby czynił człowiek pewnieby żył w nich) i sabaty moje pogwałcili. I rzekłem: Wyleję popędliwość moję na nich, abym wyko nał gniew swój na nich na tej puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Alem odwrócił rękę moję, a uczyniłem to dla imienia mego, aby nie było zelżone przed oczyma tych narodów, przed którychem ich oczyma wywiódł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Alem ja podniósł rękę moję dla nich na puszczy, żem ich miał rozproszyć między pogan, i rozwiać ich po ziemiach,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Przeto, że sądów moich nie czynili, i ustawy moje odrzucili, i sabaty moje pogwałcili, a za plugawemi bałwanami ojców swoich oczy swe obrócili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Dlategoż i Jam im dał ustawy nie dobre i sądy, w których żyć nie będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'I splugawiłem ich z darami ich, gdy przewodzili przez ogień wszelkie otwarzające żywot, abym ich spustoszył, a żeby się dowiedzieli żem ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Prztoż mów do domu Izraelskigo, synu człowieczy! a powiedz im: Tak mówi panujący Pan: Jeszcze i w tem lżyli mię ojcowie wasi, dopuszczając się przeciwko mnie przestępstwa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Że gdym ich wwiódł do ziemi, o którąm był podniósł rękę moję, żem ją im dać miał, gdzie ujrzeli jaki pagórek wysoki, albo jakie drzewo gałęziste, zaraz tam ofiarowali ofiary swoje, i dawali tam draźniące dary swoje, tamże kładli i wdzięczną wonno ść swoję, tamże sprawowali mokre ofiary swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'A chociażem mówił do nich: Cóż to za wyżyna, do której wy chadzacie? Przecie ją zowią wyżyną aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Przetoż rzecz domowi Izraelskiemu: Tak mówi panujący Pan: Izali się wy drogami ojców waszych kalać macie, a z obrzydliwościami ich nierząd płodzić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'I macież się kalać przy wszystkich plugawych bałwanach waszych, przynosząc dary wasze i przewodząc synów waszych przez ogień aż do dnia tego, a przecie odemnie rady szukać, o domie Izraelski? Jako żyję Ja, mówi panujący Pan, że się wy mnie więcej radzić nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'A to, co wstępuje na myśl waszę, nigdy się nie stanie. Wy mówicie: Będziemy jako inne narody, jako pokolenia innych ziem, drewnu i kamieniowi służące;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Jako żyję Ja, mówi panujący Pan, że ręką możną i ramieniem wyciągnionem, a w popędliwości wylanej będę królował nad wami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'I wywiodę was z narodów, a zgromadzę was z ziem, do którycheście rozproszeni, ręką możną, i ramieniem wyciągnionem, i w popędliwości wylanej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'A prowadząc was po puszczy tych narodów, tam się z wami twarzą w twarz sądzić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Jakom się sądził z ojcami waszymi na puszczy ziemi Egipskiej, tak się z wami sądzić będę, mówi panujący Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'I popędzę was pod rózgą, abym was przywiódł do związku przymierza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Ale z was wybiorę odpornych i występujących przeciwko mnie; z ziemi pielgrzymstwa ich wywiodę ich, wszakże do ziemi Izraelskiej nie wnijdą; i poznacie, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Wy tedy, o domie Izraelski! tak mówi panujący Pan: Idźcież, służcie każdy plugawym bałwanom swoim i na potem, ponieważ mnie nie słuchacie; a imienia mego świętego nie kalajcie więcej darami waszemi, i plugawemi bałwanami waszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Bo na świętej górze mojej, na wysokiej górze Izraeskiej, mówi panujący Pan, tam mi służyć będzie wszystek dom Izraeski, ile ich będzie w onej ziemi; tam ich łaskawie przyjmę, i tam się pytać będę o ofiarach waszych podnoszonych, i o pierwiastkach darów waszych ze wszystkiemi świętemi rzeczami waszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Z wdzięczną wonnością łaskawie was przyjmę, gdy was wywiodę z narodów, a zgromadzę was z onych ziem, do którycheście rozproszeni byli, a tak poświęcony będę w was przed oczyma onych narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'A poznacie, żem Ja Pan, gdy was wprowadzę do ziemi Izraelskiej, do ziemi onej, o którąm podniósł rękę moję, że ją dam ojcom waszym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'A wspomnicie tam na drogi wasze, i na wszystkie sprawy wasze, któremiście się splugawili, a obmierzniecie sami sobie przed obliczem waszem dla wszystkich złości waszych, któreście czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Tam się dowiecie, żem Ja Pan, gdy wam to uczynię dla imienia mego, nie według dróg waszych złych, ani według spraw waszych skażonych, o domie Izraelski! mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, 'Synu człowieczy! obróć twarz twoję ku stronie południowej, a krop jako rosą na południe, i prorokuj przeciwko losowi pola południowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'A rzecz lasowi południowemu: Słuchaj słowa Pańskiego: Tak mówi panujący Pan: Oto Ja rozniecę w tobie ogień, który pożre w tobie wszelkie drzewo zielone, i wszelkie drzewo suche; nie będzie ugaszony płomień pałający, i zgoreją w nim wszystkie twar ze od południa aż do północy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'I ujrzy wszelkie ciało, żem go Ja Pan zapalił; nie będzie ugaszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'I rzekłem: Ach panujący Panie! Oni mówią o mnie: Ten tylko w przypowieściach mówi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Synu człowieczy! obróć twarz swoję ku Jeruzalemowi, a krop jako rosą przeciwko miejscom świętym, i prorokuj przeciwko ziemi Izraelskiej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'A powiedz ziemi Izraelskiej: Tak mówi panujący Pan: Otom Ja przeciwko tobie, i dobędę miecza mego z pochew jego, i wytnę z ciebie sprawiedliwego i niezbożnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Abym tedy wyciął z ciebie sprawiedliwego, i niezbożnego, przeto wynijdzie miecz mój z pochew swoich na wszelkie ciało od południa aż ku północy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'I dowie się wszelkie ciało, żem Ja Pan dobył miecza mego z pochew jego; a nie obróci się więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'A ty, synu człowieczy! wzdychaj, jakobyś miał biodro złamane, a w gorzkości wzdychaj przed oczyma ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'A gdyć rzeką: Dlaczego wzdychasz? Tedy odpowiesz: Dla wieści, która idzie, na którą się rozpłynie wszelkie serce, i osłabieją wszelkie ręce, i ściśniony będzie wszelki duch, i wszelkie kolano rozpłynie się jako woda; oto idzie, i stanie się, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Synu człowieczy! prorokuj, a rzecz: Tak mówi Pan: Powiedz, miecz, miecz naostrzony jest i wypolerowany;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Wyostrzony jest na pomordowanie ku zabiciu naznaczonych, wypolerowany jest, aby się lśnił. Izali się weselić mamy? Gdyż rózga syna mego każde drzewo lekce waży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Dałci go na wypolerowanie, aby mógł być ujęty ręką, jestci wyostrzony ten miecz, jest i wypolerowany, aby dany był do ręki zabijającego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Wołaj a kwil, synu człowieczy, przeto, że ten miecz będzie przeciwko ludowi memu, ten też przeciwko wszystkim książętom Izraelskim; strachy miecza przyjdą na lud mój; przetoż się w biodrę uderz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Gdym ich karał, cóż to pomogło? I nie mamże rózgi wszystko lekce poważającej na nich wyciągnąć? mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Ty tedy, synu człowieczy! prorokuj, a bij ręką w rękę; bo powtóre i potrzecie miecz przyjdzie, miecz mordujących, ten miecz mordujących bez litości, przenikający aż do pokojów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'We wszystkich bramach ich dałem strach miecza, aby się rozpłynęło serce, i upadków się namnożyło. Ach! wypolerowany jest, aby się błyszczał, a wyostrzony, aby zabijał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Zbierz się mieczu, udaj się na prawo i na lewo, gdziekolwiek jest chęć twarzy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Boć i Ja uderzę ręką moją w rękę moję, i uspokoję rozgniewanie moje. Ja Pan mówiłem to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Wtem się stało słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'A ty, synu człowieczy! połóż przed sobą dwie drogi, którędyby iść miał miecz króla Babilońskiego; z jednej ziemi niech wychodzą obiedwie, a na rozdrożu obierz tę ku miastu, tę obierz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Pokaż drogę, którąby miecz iść miał, czyli ku Rabbacie synów Ammonowych, czyli ku ziemi Judzkiej na Jeruzalemskie twierdze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Albowiem stanie król Babiloński na rozdrożu, na początku dwóch dróg, pytając się wieszczby; będzie polerował strzały, będzie się radził bałwanów, będzie patrzył na wątrobę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Po prawej ręce jego wieszczba ukaże Jeruzalem, aby szykował hetmanów, którzyby pobudzali do mordowania, a podnosili głos z okrzykiem, aby zasadzili tarany przeciwko bramom, aby usypali wał, a urobili szańce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'I będą to mieli za próżną wieszczbę przed oczyma swemi ci, co się obowiązali przysięgami; a to przywiedzie na pamięć nieprawość ich, aby pojmani byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Przetoż tak mówi panujący Pan: Dlatego, że na pamięć przywodzicie nieprawość swoję, a odkrywa się przestępstwo wasze, tak, że jawne są grzechy wasze we wszystkich sprawach waszych, przto, mówię, że na pamięć przychodzicie, tą ręką pojmani będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'A ty, nieczysty bezbożniku, księciu Izraelski! którego dzień przychodzi, gdy nieprawość skończona będzie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Tak mówi panujący Pan: Zdejm tę czapkę, a zrzuć tę koronę, która już nigdy takowa nie będzie; tego, który w poniżenie przyszedł, wywyższę, a wywyższonego poniżę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'W niwecz, w niwecz, w niwecz ją obrócę, czego pierwej nie bywało, aż przyjdzie ten, co do niej ma prawo, którem mu dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Ale ty, synu człowieczy! prorokuj, a mów: Tak mówi panujący Pan o synach Ammonowych i o hańbie ich; rzecz mówię: Miecz, miecz dobyty jest, ku zabijaniu wypoleroawny jest, aby wytracił wszystko, i aby się błyskał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'I chociaż ci opowiadają marność, i wróżą kłamstwo, aby cię przyłożyli do szyi niezbożników pobitych, których dzień przychodzi, gdy nieprawość, skończona będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Schowaj jednak miecz do pochew jego; na miejscu, na któremeś spłodzona, w ziemi mieszkania twego, sądzić cię będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'I wyleję na cię rozgniewanie moje; ogniem popędliwości mojej na cię dmuchać będę, i podam cię w ręce ludzi zuchwałych i przemyślnych na wytracenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Ogniowi potrawą będziesz, krew twoja będzie w pośrodku ziemi, nie będziesz więcej wspominana; bo Ja Pan mówiłem to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'A ty, synu człowieczy! izalibyś się zastawiał, izalibyś się zastawiał za to miasto krwi? Raczej mu oznajmij wszystkie obrzydliwości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'I rzecz: Tak mówi panujący Pan: O miasto, które wylejesz krew w pośrodku siebie; a czynisz plugwe bałwany samo przeciwko sobie, abyś się splugawiło, przychodzić czas twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Tyś wylaniem krwi twojej zgrzeszyło, i plugawemi bałwanami swemi, którycheś naczyniło, siebieś skalało, i sprawiłoś, że się przybliżyły dni twoje, a żeś przyszło aż do lat swoich; przetoż cię podam na pohańbienie narodom, i na pośmiech wszystkim ziemiom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Biliskie i dalekie od ciebie będą się naśmiewać z ciebie, o miasto złej sławy i zwad pełne!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Oto książęta Izraelscy, każdy wszystką siłą na to się udali, aby krew w tobie przelewali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Ojca i matkę znieważają w tobie, przychodniowi krzywdę czynią w pośród ciebie, sierotę i wdowę uciskają w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Świętemi rzeczami mojemi pogardzasz, a sabaty moje splugawiasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Potwarcy są w tobie, aby wylewali krew; i na górach jadają w tobie, złości popełniają w pośrodku ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Nagość ojcowską syn odkrywa w tobie, a oddalone dla nieczystości gwałcą w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'A drugi z żoną bliźniego swego czyni obrzydliwość, a inny z synową swoją sprośnie się maże; inny zaś siostrę swoję, córkę ojca swego, gwałci w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Podarki biorą w tobie na wylewanie krwi; lichwę i płat bierzesz, a zysku szukasz z uciskiem bliźniego swego, a na mię zapominasz, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Przetoż otom Ja klasnął rękami swemi nad zyskiem twoim, którego nabywasz, i nad krwią twoją, która była w pośrodku ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Izali wytrzyma serce twoje? izali zdołają ręce twoje dniom, których Ja z tobą będę miał sprawę? Ja Pan rzekłem, i uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Bo cię rozproszę między pogany, i rozwieję cię po ziemiach, i uprzątnę do końca nieczystość twoję z ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'I będziesz splugawione przed oczyma pogan, aż poznasz, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Potem się stało słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Synu człowieczy, dom Izraaelski mi się obrócił w zużelicę; wszyscy zgoła są miedzią i cyną i żelazam i ołowiem w pośród pieca, zużelicą srebra się stali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Przetoż tak mówi panujący Pan: Dlatego, żeście wy się wszyscy obrócili w zużelicę, przetoż oto Ja zgromadzę was do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Jako zgromadzają srebro, i miedź, i żelazo, i ołów i cynę w pośród pieca, aby rozdymano ogień koło nich dla roztopienia, tak was zgromadzę w zapalczywości mojej i w gniewie moim, a złożywszy roztapiać was będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Owa zgromadzę was a rozedmę około was ogień popędliwości mojej, i roztopieni będziecie w pośrodku niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Jako się srebro topi w pośrodku pieca, tak się roztopicie w pośrodku niego, a dowiesie się, że Ja Pan wylałem na was popędliwość swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Nadto stało się słowo Pańskie do mnie mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Synu człowieczy! mów do tej ziemi: Ty ziemio nieczystaś jest, nie będziesz deszczem odwilżana w dzień zapalczywości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Sprzysiężenie proroków jej jest w pośrodku jej; podobni są lwowi ryczącemu, obłów chwytającemu; dusze pożerają, bogactwa i drogie rzeczy zbierają, a czynią wiele wdów w pośrodku niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Kapłani jej gwałcą zakon mój, i święte rzeczy moje splugawiają; między świętym i pospolitym różności nie czynią, a między nieczystym a czystym nie rozsądzają. Nadto od sabatów moich zakrywają oczy swe, tak, iż zelżony bywam między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Książęta jej w pośrodku jej są jako wilki chwytające łup, wylewający krew, tracący dusze, udawający się za zyskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'A prorocy ich tynkują wapnem nieczynionem, prorokując marność, a wróżąc im kłamstwo mówiąc: Tak mówi panujący Pan, choć Pan nie mówi panujący Pan: Biada temu miastu krwawemu, garncowi, w którym zostaje przywara jego, z którego, mówię, przywara jego nie wychodzi; po sztukach, po sztukach wyciągaj z niego, a padnieć nań los.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Lud tej ziemi gwałt czyni, gwałtem biorąc, co jest cudzego; ubogiemu i nędznemu krzywdę czynią, a przychodnia bezprawnie uciskają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Szukałem między nimi męża, któryby płot ugrodził, i stanął w przerwie przed twarzą moją za tą ziemią, abym jej nie zburzył; alem żadnego nie znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Przetoż wyleję na nich gniew mój, ogniem popędliwości mojej wyniszczę ich; drogę ich na głowę ich obrócę, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Synu człowieczy! były dwie niewiasty, córki jednej matki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Te nierząd płodziły w Egipcie, w młodości swojej nierząd płodziły; tam są omacane piersi ich, i tam są zgniecione piersi panieństwa ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Imiona ich te są: Większej Ahola, a siostry jej Aholiba. Teć były moje, i zrodziły synów i córki; imiona, mówię, ich są, Samaryja Ahola, a Jeruzalem Aholiba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Ale Ahola płodziła wszeteczeństwo przy mnie, a nierządu pilnowała z miłośnikami swojemi, z Assyryjkczykami bliskimi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Którzy byli obleczeni w hijacynt, z książętami, i panami, i ze wszystkimi młodzieńcami udatnymi, i z jezdnymi jeżdżącymi na koniach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Udała się, mówię, na wszeteczeństwo swoje z nimi, ze wszystkimi najprzedniejszymi synami Assyryjskimi, i ze wszystkimi, za którymi miłością pałała, a splugawiała się wszystkiemi plugawemi bałwanami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'A tak wszeteczeństw swoich egipskich nie zaniechała: bo z nią sypiali w młodości jej, a oni omacali piersi panieństwa jej, i wylali wszeteczeństwo swe na nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Dlatego podałem ją w rękę zalotników jej, w rękę synów Assyryjskich, za którymi miłością pałała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Oni odkryli nagość jej, synów jej i córki jej zabrali, a samę mieczem zabili; i stała się osławioną między niewiastami, gdy sądy wykonali przy niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'To widząc siostra jej Aholiba, bardziej się niż ona zapaliła miłością, a wszeteczeństwo jej większe było niżeli siostry jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Za synami Assyryjskimi pałała miłością, za książętami, i panami bliskimi, ubranymi w szaty kosztowne, za jezdnymi jeżdżącymi na koniach, i za wszystkimi młodzieńcami urodziwymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'I widziałem, że się splugawiła, a iż jednaka droga obu była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Ale ta jeszcze to przydała do wszeteczeństw swoich, że widząc mężów wymalowanych na ścianie, obrazy Chaldejczyków malowane farbami,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Opasane pasami na biodrach ich, i kołpaki farbowane na gowach ich, a że wszyscy na wejrzeniu byli jako hetmani, podobni synom Babilońskim, w ziemi Chaldejskiej zrodzonym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'I pałała miłością ku nim, ujrzawszy ich oczyma swemi, a wyprawiła posłów do nich do ziemi Chaldejskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Tedy weszli do niej synowie Babilońscy do komory nierządu, i zmazali ją wszeteczeństwem swojem; a gdy się splugawiła z nimi, odstąpiła dusza jej od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'I gdy odkryła wszeteczeństwa swe, odkryła i nagość swoję; odstąpiła dusza moja od niej, jako była odstąpiła dusza moja od siostry jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Bo rozmnożyła wszeteczeństwa swoje, wspominając na dni młodości swojej, których nierządu patrzyła w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'I pałała miłością przeciwko nierządnikom ich, których ciała są jako ciała osłów, a przyrodzenie ich jako przyrodzenie końskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'A takeś się zaś nawróciła do sprośności młodości twojej, gdy macali Egipczanie piersi twoje dla piersi młodości twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Przetoż, o Aholibo! tak mówi panujący Pan: Oto ja pobudzę zalotników twoich przeciwko tobie, tych, od których odstąpiła dusza twoja, i przywiodę ich na cię zewsząd;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Synów Babilońskich, i wszystkich Chaldejczyków z Pekot, i z Soby, i z Kohy, i wszystkich synów Assyryjskich z nimi, młodzieńców udatnych, książąt i panów wszystkich, hetmanów i ludzi zacnych, wszystkich jeżdżących na koniach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'I przyjadą przeciwko tobie na wozach żelaznych, i na rydwanach, i na karach, a to z zgrają narodów, z tarczami, i z pancerzami, i z przyłbicami, położą się przeciwko tobie zewsząd; i dam im prawo, aby cię sądzili według praw swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'I wyleję gorliwość moję na cię, i obejdą się z tobą zapalczywie, nos twój i uszy twoje oberżną, a ostatek twój od miecza polegnie; oni synów twoich i córki twoje pojmają, a ostatek twój ogniem pożarty będzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'I zewloką cię z szat twoich, a pobiorą strój ozdoby twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'A tak uczynię koniec sprośności twojej przy tobie, i wszeteczeństwu twemu, któreś przyniosła z ziemi Egipskiej, a nie podniesiesz oczów twych do nich, ani na Egipt nie wspomnisz więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Bo tak mówi panujący Pan: Oto cię Ja podaję w ręce tych, których masz w nienawiści, w ręce tych, od których odstąpiła dusza twoja;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'I obejdą się z tobą według nienawiści, i zabiorą wszystkę pracę twoję, a zostawią cię nagą i obnażoną, i będzie jawna nagość wszeteczeństw twoich, i sprośności twojej, i nierządów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Toć się stanie przeto, żeś nierząd płodziła naśladując pogan, przeto, żeś się zmazała plugawemi bałwanami ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Chodziłaś drogą siostry swej, dlatego dam kubek jej w rękę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Tak mówi panujący Pan: Kubek siostry twojej głęboki i szeroki pić będziesz, spory będzie; pośmiech także i igrzysko będą mieli z ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Pijaństwem i boleścią napełniona będziesz, kubkiem spustoszenia i smutku, kubkiem siostry swej Samaryi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'I wypijesz go i wysączysz, potem go pokruszysz, a piersi swe poobrywasz; bom Ja rzekł, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Dlatego tak mówi panujący Pan: Ponieważeś zapomniała na mię, a zarzuciłaś mię za tył swój, i ty też ponoś niecnotę, swoję, i wszeteczeństwa swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'I rzekł Pan do mnie: Synu człowieczy! izali się będziesz zastawiał za Aholę albo za Aholibę? Oznajmij im raczej obrzydliwości ich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Że cudzołożyły, a krew jest na rękach ich, i z plugawemi bałwanami swemi cudzołożyły; nadto i synów swych, których mi narodziły, przez ogień przeporowadzały im na pożarcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Więc i to mi uczyniły, że świątnicę moję splugawiły dnia onego, a sabaty moje pogwałciły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Bo gdy ofiarowały synów swych plugawym bałwanom swoich, wchodziły do świątnicy mojej onegoż dnia, aby ją zmazały; oto takci czyniły w pośrodku domu mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Nadto posyłały też do mężów, aby przyszli z daleka; którzy zaraz przychodzili, kiedy poseł do nich wysłany był. Tymeś kwoli się ty umywała, farbowałaś twarz swoję, i zdobiłaś się ochędóstwem swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Siadałaś na łożu zacnem, przed którym był stół przygotowany, na któremeś i kadzeniw moje i olejek mój pokładała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'A gdy głos onego mnóstwa ucichł, tedy i do mężów ludu pospolitego posyłały, których przywodzono ożartych z puszczy, i kładli manele na ręce ich, i korony ozdobne ne ręce ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'A chociażem przymawiał onej cudzołożnicy zastarzałej, a iż oni raz z jedną, raz z drugą nierząd płodzą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'I że każdy z nich wchodzi do niej, jako wchodzą do niewiasty wszetecznej: przecie jednak wchodzili do Aholi i do Aholiby, niewiast niecnotliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Przetoż sprawiedliwi mężowie, ci je osądzą sądem cudzołożnic, i sądem wylewających krew, przeto, że cudzołożyły, a krew jest na rękach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Bo tak mówi panujący Pan: Przywiodę na nie wojsko, a poddam je na potłukanie i na łup;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'I ukamionuje je ono zgromadzenie kamieniem, i rozsieką je mieczami swemi, synów ich i córki ich pobiją, a domy ich ogniem spalą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'A tak uprzątnę sprośność z tej ziemi, i będą się tem karać wszystkie niewiasty, a nie uczynią według niecnoty waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Bo włożona będzie na was niecnota wasza, a grzechy plugawych bałwanów waszych poniesiecie, i poznacie, żem Ja panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'I stało się słowo Pańskie do mnie roku dziewiątego, miesiąc dziesiątego, dziesiątego dnia tegoż miesiąca, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Synu człowieczy! napisz sobię imię dnia tego, tegoż właśnie dnia; bo obległ król Babiloński Jeruzalem prawie tegoż dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'A rzecz przez przypowieść do tego domu odpornego, podobieństwo mówiąc do nich: Tak mówi panujący Pan: Przystaw ten garniec, przystaw, a nalej weń wody;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'A zebrawszy sztuki należące do niego, każdą sztukę dobrą, udziec i łopatkę, najlepszemi kościami napełń go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Weźmijże i co najwyborniejsze bydlę, a nałóż ogień z kości pod niem; sprawże aby to wrzało i kipiało, żeby i kości jego rozewrzały w niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Przetoż tak mówi panujący Pan: Biada temu miastu krwawemu, garncowi, w którym zostaje przywara jego, z którego, mówię, przywara jego nie wychodzi: po sztukach, po sztukach wyciągaj z niego, nie padnieć nań los.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Bo iż krew jego jest w pośrodku jego, na wierzchu skały wystawiło ją, nie wylało jej na ziemię, aby była zakryta prochem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Tedy i Ja rozniecę zapalczywość na wykonanie pomsty, wystawię krew jego na wierzchu skały, aby nie była zakryta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Przetoż tak mówi panujący Pan: Biada temu miastu krwawemu; bo i Ja naniecę wielki ogień,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Przykładając drew, rozniecając ogień, wniwecz obracając mięso, i zaprawiając korzeniem, tak, że i kości spalone będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'A postawię ten garniec na węgle jego próżny, aby się zagrzała i rozpaliła miedź jego, a żeby się rozpłynęły w pośród jego plugastwa jego, a iżby zniesiona była przywara jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Utrudziło mię kłamstwami swemi, przetoż nie wynijdzie z niego wielkość szumowin jego, do ognia muszą szumowiny jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'W nieczystości twojej jest sprosność; dlatego, żem cię oczyszczał; a przecięś nie oczyszczona, i od nieczystości twojej nie będziesz więcej oczyszczana, aż uspokoję na tobie rozgniewanie moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Ja Pan mówiłem; przyjdzie to, i uczynię to, nie cofnę się, ani sfolguję, ani mi żal będzie; według dróg twoich, i według spraw twoich sądzić cię będę, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Synu człowieczy! oto Ja od ciebie odejmę żądność oczów twoich z prędka; wszakże nie kwil, ani płacz, a niech nie wychodzą łzy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Zaniechaj kwilenia, nie czyń żałoby, jako bywa nad umarłym; czapkę twoję włóż na się, a obuwie twoje wzuj na nogi twoje, a nie zasłaniaj warg, a chleba niczyjego nie jedz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Co gdym z poranku ludowi powiedział, tedy umarła żona moja w wieczór; i uczyniłem rano, jako mi rozkazano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'I mówił lud do mnie: I nie oznajmiszże nam, co nam te rzeczy znaczą, które ty czynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Tedym rzekł do nich: Słowo Pańskie stało się do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Powiedz domowi Izraelskiemu: Tak mówi panujący Pan: Oto Ja splugawię świątnicę moję, wyniosłość mocy waszej, żądność oczów waszych, i to, w czem się kocha dusza wasza, a synowie wasi i córki wasze, któreście zostawili, od miecza polegną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'I uczynicie, jakom uczynił; nie zasłonicie wargi, a chleba niczyjego jeść nie będziecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'A czapki swe na głowach swych, i bóty swoje na nogach swoich mając, nie będziecie kwilić ani płakać; ale będziecie schnąć dla nieprawosci waszych, a wzdychać jeden z drugim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Bo wam jest Ezechyjel dziwem, według wszystkiego, co on czyni, czynić będziecie; a gdy to przyjdzie, dowiecie się, żem ja panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'A ty, synu człowieczy! azaż w ten dzień, którego Ja odejmę od nich moc ich, wesele ozdoby ich, żądność oczów ich, i to, po czem tęskni dusza ich, synów ich i córki ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'Izali dnia onego nie przyjdzie do ciebie ten, co uciecze, oznajmując ci to?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'Dnia onego otworza się usta twoje przy tym, który ujdzie; a będziesz mówił, i nie będziesz więcej niemym; i będziesz im dziwem, a poznają, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Synu człowieczy! obróć twarz twoję przeciwko synom Ammonowym, a prorokuj przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'I rzecz synom Ammonowym: Słuchajcie słowa panującego Pana. Tak mówi panujący Pan: Przeto, żeś wykrzykał mówiąc: Hej, hej! nad świątnicą moją, gdy była splugawiona, i nad ziemią Izraelską, i gdy była spustoszona, i nad domem Judzkim, i gdy szedł w niewolę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'Przetoż oto Ja cię też podam narodom wschodnim w dziedzictwo i pobudują pałace swoje w tobie, a wystawią mieszkanie swoje w tobie, one będą jeść urodzaje twoje, oni też będą pić mleko twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'I dam Rabbę na mieszkanie wielbłądom, a miasta synów Ammonowych na legowisko trzodom; i dowiecie się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Bo tak mówi panujacy Pan: Przeto, iżeś klaskał ręką, a tąpał nogą, i weseliłeś się z serca, żeś cale spustoszył ziemię Izraelską:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Przetoż oto Ja wyciągnę rękę swą przeciwko tobie, a dam cię w rozchwycenie narodom, i wytnę cię z narodów, a wytracę cię z ziem, i wygładzę cię, a dowiesz się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Tak mówi panujący Pan: Dlatego, że Moab i Seir mówił: Oto dom Judzki podobny jest wszystkim innym narodom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Dlatego oto Ja otworzę stronę Moabczyków od miast, od miast mówię ich, i od granic ich, ozdobę ziemi Betiesymot, Baalmeon, i Karyjataim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Narodom wschodnim z ziemią synów Ammonowych; bom ją dał w dziedzictwo, aby nie było pamiątki synów Ammonowych między narodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'A tak nad Moabem sądy wykonam, iż poznają, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Tak mówi panujący Pan: Przetoż, iż się Edomczycy srodze mścili nad domem Judzkim, i przywiedli na się winę wielką, mszcząc się nad nimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Przetoż tak mówi panujący Pan: Wyciągnę też rękę moję na ziemię Edomczyków, a wytrcę z niej ludzi i bydło, i uczynię ją pustynią; od Teman aż do Dedan od miecza polegną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'A tak wykonam pomstę moję nad Edomczykami przez ręce ludu mojego Izraelskiego, a obejdą się z Edomczykami według popędliwości mojej, i według gniewu mego; i poznają pomstę moję, mówi panujacy Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Tak mówi panujący Pan: Przeto, iż się Filistyńczycy mścili, i pomstę wykonywali, pustosząc ich z serca, a do zginienia przywodząc z nieprzyjaźni starodawnej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Dlatego tak mówi panujący Pan: Oto Ja wyciągnę rękę moję na Filistyńczyków, i wykorzenię Cheretejczyków, i wytracę ostatek krainy pomorskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'A tak uczynię nad nimi pomsty wielkie, karząc ich w zapalczywości; i dowiedzą się, żem Ja Pan, gdy wykonam pomstę moję nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'I stało się roku jedenastego, pierwszego dnia miesiąca, stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Synu człowieczy! przeto, iż Tyr mówił o Jeruzalemie wykrzykając: Hej, hej! zniszczone jest miasto bram bardzo ludnych, obraca się do mnie, teraz napełniony będę, gdyż to jest spustoszone;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Dlatego tak mówi panujący Pan: Otom Ja powstał przeciwko tobie, o Tyrze! a przywiodę na cię wiele narodów, jakobym przywiódł morze z nawałnościami jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'I zburzą mury Tyrskie, i rozwalą wieże jego; i wymiotę z niego proch jego, i uczynię go wierzchołkiem skały gładkiej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Tak, że będą wysuszać sieci w pośród morza; bom Ja rzekł, mówi panujący Pan, przeto będzie na rozchwycenie narodom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'A córki jego, które będą na polu, mieczem pobite będą, a dowiedzą się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Bo tak mówi panujący Pan: Oto Ja przywiodę przeciwko Tyrowi Nabuchodonozora, króla Babilońskiego, od północy, króla nad królmi, z końmi i z wozami, i z jezdnymi i z zgrają, i z ludem wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Córki twoje na polu mieczem pomorduje, i przeciwko tobie porobi baszty, i usypie wał przeciwko tobie, i postawi przeciwko tobie tarcz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'I tarany zasadzi przeciwko murom twoim, a wieże twoje potłucze młotami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Od mnóstwa koni jego okryje cię proch ich; od grzmotu jezdnych i kar i wozów poruszą się mury twoje, gdy wchodzić będzie w bramy twoje, jako wchodzą do miasta zburzonego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Kopytami koni swoich zdepcze wszystkie ulice twoje, lud twój mieczem pobije, a mocne słupy twoje upadną na ziemię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'I robiorą majętność twoję, a rozchwycą towary twoje, i rozwalą mury twoje, i domy twoje rozkoszne poburzą, a kamienie twoje, i drzewo twoje, i proch twój do wody wrzucą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'I uczynię. że ustanie głos pieśni twoich, a dźwięk harf twoich nie będzie więcej słyszany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'I uczynię cię wierzchołkiem gładkiej skały; staniesz się miejscem ku wysuszaniu sieci, nie będziesz więcj zbudowany; bom Ja Pan powiedział, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Tak mówi panujący Pan do Tyru: Izali się od trzasku upadku twego, gdy ranni wołać będą, gdy okrutne morderstwo będzie w pośrodku ciebie, wyspy się nie poruszą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'I powstaną z stolic swoich wszyscy książęta pomorscy, i złożą z siebie płaszcze swoje, a szaty swe haftowane zewleką, strachem będą przyodziani, na ziemi usiądą, a wzdrygając się co chwila zdumiewać się będą nad tobą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'I podniosą nad tobą lament i rzekną do ciebie: Jakoś zginęło, o miasto! w którem mieszkano dla przyległości morza, miasto sławne, które było mocne na morzu, ono i z obywatelami swymi, którzy byli straszni wszystkim obywatelom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Tedy się zatrwożą wyspy w dzień upadku twego; zatrwożą się mówię wyspy morskie nad zginieniem twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Bo tak mówi panujący Pan: Gdy cię uczynię miastem spustoszonem, jako miasta, w których nie mieszkają, gdy na cię przepaść przywiodę, tak, że cię wody wielkie przykryją;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Gdy uczynię, że zstąpisz z tymi, którzy zstępują do dołu, do ludu dawnego, a położę cię w najniższych stronach ziemi, na pustyniach dawnych, z tymi, co zstępują do dołu, aby nie mieszkano w tobie, tedy dokażę sławy w ziemi żyjących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Bo uczynię to, że będziesz na wielki postrach, gdy cię nie stanie; a choćby cię szukano, nie znajdą cię na wieki, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'A ty, synu człowieczy! podnieś nad Tyrem lament,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'A rzecz do Tyru, który leży nad portami morskiemi i handluje z narodami na wielu wyspach: Tak mówi panujący Pan: O Tyrze! tyś mówił: Jam jest doskonały w piękności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'W pośrodku morza były granice twoje, budownicy twoi doskonałą uczynili piękność twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Z jedliny z Sanir pobudowalić wszystkie piętra twoje, cedry z Libanu brali, aby czynili maszty twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Z dębów Basańskich czynili wiosła twoje, ławy twoje urobili z kości słoniowych i z bukszpanu z wysep Cytymskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Bisior haftowany egipski bywał płótnem twojem, z któregoś żagle miewał; hijacynt i szarłat z wysep Elisa był nakryciem twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Obywatele Sydonu, i Arwadczycy bywali żeglarzami twymi; mędrcy twoi, Tyrze! którzy bywali w tobie, ci byli sternikami twymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Starcy z Giebal, i mędrcy jego oprawiali w tobie rozpadliny twoje; wszystkie okręty morskie i żeglarze ich bywali w tobie, handlując z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Persowie, i Ludczycy, i Putejczycy bywali w wojsku twojem, mężowie waleczni twoi; tarcz i przyłbicę zawieszali w tobie, ci przydawali tobie ozdoby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Synowie Arwad z wojskiem twojem na murach twoich w około, także Gamadczycy na wieżach twoich bywali, tarcze twoje zawieszali na murach twoich w około; cić są, którzy doskonałą uczynili piękność twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Zamorscy kupcy twoi dla wielkości wszelakich dostatków, srebrem, żelazem, cyną i ołowiem kupczyli na jarmarkach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Jawan, Tubal, i Mesech, kupcy twoi, ludzi i naczynie miedziane dawali na zamianę tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Z domu Togorma końmi, i jezdnymi, i mułami kupczyli na jarmarkach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Synowie Dedanowi, kupcy twoi, i wiele wysep przekupowali towary ręki twojej, rogi, kości słoniowe, i drzewo hebanowe dawali na zamianę za zapłatę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Syryjczycy kupcy twoi dla mnóstwa przemyślnych robót twoich, karbunkułami, szarłatem, i haftarskiemi rzeczami, płótnem subtelnem, i koralami, i kryształami handlowali na jarmarkach twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda i ziemia Izraelska, i ci kupcy twoi, pszenicę z Minnit i z Pannag, i miód, i oliwę. i kadzidło na zamianęć dawali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damaszczanie, kupcy twoi dla mnóstwa przemyślnych robót twoich, i dla mnóstwa wszelkich dostatków, winem z Helbonu i wełnę białą kupczyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Także Dan i Jawan, kramarze na jarmarkach twoich, sprzedawali żelazo polerowane, kassyję, i Tatarskie ziela na zamianęć dawali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan kupczył w tobie suknami kosztownemi na wozy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabczycy, i wszyscy książęta Kedarscy, i ci kupczyli z tobą skopami i baranami, i kozłami, tem handlowali w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Kupcy Sabejscy i z Ramy kupczyli z tobą wszelakiemi przedniejszemi wonnemi rzeczami, i wszelakim kamieniem drogim i złotem kupczyli na jarmarkach twoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haran, i Kanne, i Eden kupcy z Saby; Assur i Kilmad kupczył w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Ci kupcy twoi, sztukami hijacyntu, i rzeczami haftowanemi, i skrzyniami dla kosztownych szat, także towarami, które powrozami obwiązują albo w skrzyniach cedrowych zawierają, kupczyli w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Okręty morskie przodkowały w kupiectwie twojem; i byłoś napełnione i uwielbione bardzo w pośród morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Na wody wielkie zaprowadzili cię żeglarze twoi; wiatr wschodni rozbije cię w pośród morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Bogactwa twoje, i jarmarki twoje, kupiectwo twoje, żeglarze twoi, i sternicy twoi, i ci, którzy zaprawiali rozpadliny twoje, i kupcy towarów twoich, i wszyscy mężowie waleczni twoi, którzy byli w tobie, i wszystko mnóstwo twoje, które jest w pośród ciebie, wpadną w pośród morza w dzień upadku twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Na głos krzyku sterników twoich zadrżą wały morskie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'I wystąpią z okrętów swoich wszyscy robiący wiosłem, żeglarze, i wszyscy sternicy morscy na ziemi staną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'I będą narzekali nad tobą głosem wielkim, i będą gorzko wołali, a sypiąc proch na głowy swoje, w popiele się walać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Nadto poczynią sobie dla ciebie łysiny, a opaszą się worami; i będą płakać nad tobą w gorzkości duszy swej płaczem gorzkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Uczynią, mówię, nad tobą lament żałośny, a będą narzekali nad tobą, mówiąc: Któreż miasto podobne jest Tyrowi, wyciętemu w pośrodku morza?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Gdy wychodziły towary twoje z morza, nasycałoś wiele narodów; mnóstwem bogactw twoich i handlów twoich bogaciłoś królów ziemskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Ale gdy będziesz podruzgotane od morza w głębokościach wód, kupiectwo twoje i wszystko mnóstwo twoje w pośrodku ciebie upadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Wszyscy na wyspach mieszkający zdumieją się nad tobą, a królowie ich strachem zdjęci będąc, bardzo się zatrwożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Kupcy między narodami zaświsną nad tobą; na postrach im będziesz, a nie będzie cię na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'I stało się słowo Pańskie do mnie mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Synu człowieczy! mów książęciu Tyrskiemu: Tak mówi panujący Pan: Dlatego, iż się podniosło serce twoje, a mówisz: Jam jest Bóg, siedzę w pośród morza na stolicy Boskiej, gdyżeś ty człowiek, a nie Bóg, choć serce swoje stawiasz jako serce Boże;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Otoś mędrszym nad Danijela, żadna tajemnica nie jest zakryta przed tobą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Mądrością twoją i roztropnością twoją nazbierałeś sobie bogactw, i nabyłeś złota i srebra do skarbów toich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Wielkością mądrości twojej w kupiectwie twojem rozmnożyłeś bogactwa twoje; a tak podniosło się serce twoje dla bogactw twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Przetoż tak mówi panujący Pan: Ponieważ stawiasz serce twoje jako serce Boże,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'Dlatego oto Ja przywiodę na cię cudzoziemców najsroższych z narodów, którzy dobywszy mieczów swoich na piękność mądrości twojej splugawią jasność twoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'W dół cię wepchną, i umrzesz srogą śmiercią w pośród morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Izali mówiąc rzeczesz przed tym, który cię zabijać będzie: Jestem Bóg? gdyżeś człowiek a nie Bóg w ręku mordercy twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Śmiercią nieobrzezańców umrzesz od ręki cudzoziemców; bo Ja mówiłem, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'I stało się słowo Pańskie do mnie mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Synu człowieczy! podnieś lament nad królem Tyrskim, a mów do niego: Tak mówi panujący Pan: Ty, co pieczętujesz sumy, pełen mądrości i doskonałej piękności;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'Byłeś w Eden, ogrodzie Bożym; wszelki kamień drogi był nakryciem twojem, sardyjusz, topazyjusz, i jaspis, chrysolit, onyks, i beryl, szafir, kabunkuł, i szmaragd, i złoto; w ten dzień, któregoś ty stworzony, zgotowane są u ciebie narzędy bębnów twoich i piszczałek twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Tyś był Cherubinem pomazanym, nakrywającym; Jam cię wystawił, byłeś na górze Bożej świętej, w pośród kamienia ognistego przechadzałeś się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Byłeś doskonałym na drogach twoich ode dnia tego, któregoś jest stworzony, aż się znalazła nieprawość w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Dla wielkości kupiectwa twego pełno w pośród ciebie bezprawia, i zgrzeszyłeś; dlatego wytracę cię z góry Bożej, o Cherubinie nakrywający! a z pośrodku kamienia ognistego wygubię cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Podniosło cię serce twoje dla piękności twojej, na złeś używał mądrości swojej dla jasności twojej; przetoż cię uderzę o ziemię, a przed obliczem królów położę cię, abyć się dziwowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Dla mnóstwa nieprawości twoich, i dla sprawiedliwości kupiectwa twego splugwiłeś świątnicę twoję; przetoż wywiodę ogień z pośrodku ciebie, który cię pożre, a obrócę cię w popiół na ziemi przed oczyma wszystkich, co na cię patrzą,.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Wszyscy, co cię znali między narodami, zdumiewają się nad tobą; będziesz na wielki postrach, a nie będzie cię aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'I stało się słowo Pańskie do mnie mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Synu człowieczy! obróć twarz swoję przeciw Sydonowi, a prorokuj przeciw niemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'I mów: Tak mówi panujący Pan: Otom Ja przeciwko tobie, o Sydonie! a będę uwielbiony w pośród ciebie; i dowiedzą się, żem Ja Pan, gdy nad nimi sądy wykonam, i w nim poświęcony będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'I poślę nań mór, i krew na ulice jego, i upadną zranieni w pośrodku niego od miecza, który na nich przyjdzie ze wszystkich stron; a dowiedzą się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'A tak nie będzie miał więcej dom Izraelski ciernia kolącego, i głogu boleści zadawającego z wszystkich okolicznych swych, którzy ich pustoszą; i dowiedzą się, żem Ja panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Tak mówi panujący Pan: Gdy zgromadzę dom Izraelski z narodów, między którymi są rozproszeni, i poświęcony będę w nich przed oczyma pogan, i będą mieszkali w ziemi swojej, którąm był dał słudze memu Jakóbowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Tedy w niej będą bezpiecznie mieszkali, a pobudują domy, i naszczepią winnic; mieszkać mówię będą bezpiecznie, gdy wykonam sądy nad wszystkimi okolicznymi ich, którzy ich pustoszyli; i dowiedzą się, żem Ja Pan, Bóg ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Roku dziesątego, dziesątego miesiąca, dwunastego dnia tegoż miesiąca stało się słowo Pańskie do mnie mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Synu człowieczy! obróć twarz swoję przeciwko Faraonowi, królowi Egipskiemu, a prorokuj przeciw niemu i przeciwko wszystkiemu Egiptowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Mów, a rzecz: Tak mówi panujący Pan: Otom Ja przeciwko tobie o Faraonie, królu Egipski, wielorybie wielki, który leżysz w pośrodku rzek twoich, i mówisz: Mojać jest rzeka, i jam ją sobie uczynił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Przetoż włożę wędę w czeluści twoje, i uczynię, że powięzną ryby rzek twoich na łuskach twych, i wywlekę cię z pośrodku rzek twoich i wszystkie ryby rzek twoich, które na łuskach twoich powięzną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'I zostawię cię na puszczy, ciebie i wszystkie ryby rzek twoich: polężesz na polu, i nie będziesz zebrany ani zgromadzony; dam cię bestyjom ziemskim i ptastwu niebieskiemu ku pożarciu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'I dowiedzą się wszyscy mieszkający w Egipcie, żem Ja Pan, przeto żeście laską trzcinianą domowi Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Gdy się ciebie ręką chwytają, łamiesz się i rozcinasz im wszystko ramię; a gdy się podpierają tobą, kruszysz się, choć im nadstawiasz wszystkich biódr.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Dlategoż tak mówi panujący Pan: Oto Ja przywiodę na cię miecz, i wygładzę z ciebie człowieka i bydlę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'A ziemia Egipska będzie pustynią i spustoszeniem, i dowiedzą się, żem Ja Pan, dlatego, żeś mówił: Rzeka moja, i jam ją uczynił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Przetoż oto Ja będę przeciwko tobie i przeciwko rzece twojej, i podam ziemię Egipską w spustoszenie, i we srogie poburzenie, od wieży Sewene aż do granic Murzyńskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Nie przejdzie przez nią noga człowiecza, i noga bydlęca nie przejdzie przez nią, ani w niej będą mieszkać przez czterdzieści lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'A tak uczynię ziemię Egipską pustnią nad inne ziemie spustoszone, a miasta jej nad inne miasta spustoszone, będą spustoszone przez czterdzieści lat: gdyż rozproszę Egipczan między narody, i rozwieję ich po ziemiach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'A wszakże tak mówi panujący Pan: Gdy się skończy czterdzieści lat, zgromadzę Egipczan z narodów, do których rozproszeni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'I przywrócę zasię więźniów Egipskich, i przywiodę ich do ziemi Patros, do ziemi mieszkania ich, i będą tam królestwem podłem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Między innemi królestwami będzie najpodlejszen, a nie wyniesie się więcej nad inne narody, i umniejszę ich, aby nie panowali nad narodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'I nie będzie więcej domowi Izraelskiemu ufnością, któraby mi na pamięć przywodziła nieprawość, gdyby się oglądali na nie; i dowiedzą się, żem Ja panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Potem stało się dwudziestego i siódmego roku, pierwszego miesiąca, pierwszego dnia tegoż miesiąca, stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Synu człowieczy! Nabuchodonozor, król Babiloński, przyniewolił gwałtem wojsko swe do służby ciężkiej przeciwko Tyrowi; każda głowa obłysiała, i każde ramię obnażone, a przecie nie ma zapłaty on, ani wojsko jego z Tyru za onę służbę, którą podejmo wał, walcząc przeciwko jemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Przetoż tak mówi panujący Pan: Oto Ja daję Nabuchodonozorowi, królowi Babilońskiemu, ziemię Egipską, aby zabrał dostatki jej, i rozszarpał łupy jej, i rozchwycił korzyści jej, aby miało zapłatę wojsko jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Za pracę ich, którą dla mnie podjęli, dam im ziemię Egipską, przeto, że mnie pracowali, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Dnia onego uczynię, że wyrośnie róg domu Izraelskiego, tobie też usta twoje otworzę w pośrodku ich; i dowiedzą się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'I stało się słowo Pańskie do mnie mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Synu człowieczy! prorokuj a mów: Tak mówi panujący Pan; kwilcie mówiąc: Ach niestetyż na ten dzień!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Bo bliski jest dzień, bliski jest mówię dzień Pański; ten będzie dzień chmury, i czas narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'I przyjdzie miecz na Egipt, a będzie wielka trwoga w ziemi Murzyńskiej, gdy polegną pobici w Egipcie, a zabiorą dostatki jego, i podwrócone będą grunty jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Murzyni i Putejczycy, i Ludczycy, i wszystko pospólstwo, i Kubejczycy, i obywatele innych ziem, w przymierzu będących, z nimi od miecza upadną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Tak mówi Pan, że upadną, którzy podpierają Egipt, i strącona będzie pycha mocy jego; od wieży Sewene od miecza upadną w niej, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'I będą spustoszeni nad inne ziemie spustoszone, a miasta ich nad inne miasta poburzone będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'I dowiedzą się, żem Ja Pan, gdy zapalę ogień w Egipcie, i będą potarci wszyscy pomocnicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Dnia onego wynijdą posłowie od oblicza mego w okrętach na postrach ziemi Murzyńskiej bezpiecznej; i będzie wielka trwoga między nimi, jaka była w dzień porażki Egipskiej; bo oto pewnie przychodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Tak mówi panujący Pan: Uczynię zaiste koniec mnóstwu Egipskiemu przez rękę Nabuchodonozora, króla Babilońskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'On i lud jego z nimi, najsrożsi z narodów, przywiedzeni będą na wytracenie tej ziemi; bo dobędą mieczów swych przeciw Egiptowi, i napełnią ziemię pobitymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'I wysuszę rzeki, a zaprzedam ziemię w rękę złośników; a tak spustoszę ziemię, i pełność jej przez rękę cudzoziemców. Ja Pan mówiłem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Tak mówi panujący Pan: Wytracę też plugawe bałwany, i zniosę obraz z Nof, a książęcia ziemi Egipskiej więcej nie będzie, gdyż puszczę strach na ziemię Egipską;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Bo spustoszę Patros, a rozniecę ogień w Soan, i wykonam sąd nad No;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Wyleję też popędliwość moję na Syn, obronne miejsce Egipskie, a wytracę mnóstwo z No.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Gdyż rozniecę ogień w Egipcie, Syn bolejąc boleć będzie, i No rozwalone będzie, a Nof na każdy dzień udręczone będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Młodzieńcy miasta On i Bubasto od miecza polegną, a panny w pojmanie pójdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Także w Tachpanches zaćmi się dzień, gdy tam pokruszę zawory Egipskie, i ustanie w niem pycha mocy jego, chmura je okryje, a córki jego w pojmanie pójdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'A tak wykonam sądy nad Egiptem, i dowiedzą się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'I stało się jedenastego roku, pierwszego miesiąca, siódmego dnia stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Synu człowieczy! złamałem ramię Faraona, króla Egipskiego; a oto nie będzie zawiązane, aby było uleczone, ani będzie chustkami obwinione, ani będzie związane, aby było zmocnione do trzymania miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Przetoż tak mówi panujący Pan: Otom Ja przeciwko Faraonowi, królowi Egipskiemu, a skruszę ramiona jego, tak mocne jako i złamane, i wytrącę miecz z ręki jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'I rozproszę Egipczan między narody, a rozwieję ich po ziemiach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Umocnię zasię ramiona króla Babilońskiego, i dam miecz mój w ręce jego, a ramiona Faraonowe złamię, i będzie stękał przed obliczem jego, jako stęka zraniony na śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Umocnię, mówię, ramiona króla Babilońskiego, a ramiona Faraonowe upadną; i dowiedzą się, żem Ja Pan, gdy dam miecz mój w rękę króla Babilońskiego, aby go wyciągnął na ziemię Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'A tak rozproszę Egipczan między narody, i rozwieję ich po ziemiach: i dowiedzą się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Potem jedenastego roku, trzeciego miesiąca, pierwszego dnia tegoż miesiąca, stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Synu człowieczy! mów do Faraona, króla Egipskiego, i do ludu jego: Komużeś podobnym w wielmożności twojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Oto Assur był jako cedr na Libanie, pięknych gałęzi i szeroko cień podawający i wysokiego wzrostu, a między gęstwiną gałęzi był wierzch jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Wody mu wzrost dały, głębokość go wywyższyła, a rzekami jej otoczony był w około korzeń jego, a strumienie tylko swoje wypuszczała na wszystkie drzewa polne,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Tak, że się wywyższył wzrost jego nad wszystkie drzewa polne, i rozkrzewiły się latorośle jego, a dla obfitości wód rozszerzyły się gałęzie jego, które wypuścił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Na gałęziach jego czyniło gniazda wszelakie ptastwo niebieskie, a pod latoroślami jego mnożyły się wszelkie zwierzęta polne, i pod cieniem jego siadały wszystkie narody zacne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'I był piękny dla wielkości swojej, i dla długości gałęzi swoich; bo korzeń jego był przy wodach obfitych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Cedry go nie przewyższały w ogrodzie Bożym, jedliny nie były równe latoroślom jego, a kasztanowe drzewa nie były podobne gałęziom jego; żadne drzewo w ogrodzie Bożym nie było mu równe w piękności swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Jam go pięknym uczynił dla mnóstwa gałęzi jego, i zajrzały mu wszystkie drzewa w Eden, które były w ogrodzie Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Przetoż tak mówi panujący Pan: Dlatego, że wysoko wzrósł, a wywyższył wierzch swój między gęstwiną gałęzi, i podniosło się serce jego dla wysokości jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'Przetożen go podał w rękę najmocniejszego z narodów, aby się z nim srogo obchodził; dla niezbożności jego odrzuciłem go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'A tak wygładzili go cudzoziemcy najsrożsi z narodów, i porzucili go; na górach i na wszystkich dolinach odpadły gałęzie jego, i połamane są latorośli jego przy wszystkich strumieniach tej ziemi; dlatego ustąpiły z cienia jego wszystkie narody zie mskie, i opuściły go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Na obaleniu jego mieszka wszelkie ptastwo niebieskie, a na gałęziach jego jest wszelki zwierz polny,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Dlatego, aby się na potem nie wywyższało wzrostem swoim żadne drzewo przy wodach, i żeby nie wypuszczało wierzchów swoich, między gęstwiną gałęzi, i nie wspinało się nad inne wysokością swoją żadne drzewo wodami opojone. Albowiem ci wszyscy podan i są na śmierć, i wrzuceni w niskości ziemi w pośród synów ludzkich z tymi, którzy zstępują do dołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Tak mówi panujący Pan: Dnia, którego on zstąpił do grobu, uczyniłem lament, zawarłem dla niego przepaść, i zahamowałem strumienie jej, aby się zastanowiły wody wielkie; i uczyniłaem, że się zaćmił dla niego Liban, a wszystkie drzewa polne dla nie go zemdlały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Od grzmotu upadku jego zatrwożyłem narody, gdym go wepchnął do grobu z tymi, co w dół zstępują, nad czem się ucieszyły na ziemi na dole wszystkie drzewa Eden, i co jest najwyborniejszego, i najlepszego na Libanie, i wszystko, co jest opojone wodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'I ci z nim zstąpili do grobu, do pobitych mieczem, którzy byli ramieniem jego, i którzy siadali w cieniu jego w pośrodku narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Komużeś podobny był sławą i wielkością między drzewami Eden? Oto zrzucony będziesz z drzewami Eden na dół na ziemię; w pośrodku nieobrzezańców polężesz między pobitymi mieczem. Toć jest Farao i wszystka zgraja jego, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'A dwunastego roku, miesiąca dwunastego, pierwszego dnia tegoż miesiąca, stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Synu człowieczy! podnieś lament nad Faraonem, królem Egipskim, a powiedz mu: Podobnyś ty lwowi młodemu między narodami, tyś jest jako wieloryb w morzu, gdyż bujając po rzekach twoich mącisz wodę nogami twemi, i mięszasz rzeki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Tak mówi panujący Pan: Rozciągnę też na cię sieć moję przez zebranie wielu narodów, którzy cię wyciągną niewodem moim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'I zostawię cię na ziemi, na polu porzucę cię, i sprawię, że mieszkać będzie na tobie wszelkie ptastwo niebieskie, i nakarmię tobą zwierza wszystkiej ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'I rozrzucę mięso twoje po górach, i napełnię doliny wysokością twoją,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'I napoję ziemię twoję, w której pływasz, krwią twoją aż do gór, tak, że i rzeki będą napełnione tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'A gdy cię zgaszę, zakryję niebiosa, i ciemne uczynię gwiazdy ich, słońce obłokiem zasłonię, a księżyc nie da światła swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Wszystkie światła jasne na niebiosach zaćmię dla ciebie, i przywiodę ciemność na ziemię twoję, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Nadto zasmucę serce wielu narodów, gdy za sprawą moją przyjdzie wieść o starciu twojem między narody, do ziem, którycheś nie znał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Uczynię, mówię, że się zdumieje nad tobą wiele narodów, a królowie ich zatrwożą się bardzo dla ciebie, gdy szermować będę mieczem swoim przed twarzą ich; będą się zaiste lękać co chwila każdy o duszę swoję w dzień upadku twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Bo tak mówi panujący Pan: Miecz króla Babilońskiego przyjdzie na cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Mieczami mocarzów porażę zgraję twoję; najokrutniejsi ze wszystkich narodów, ci skażą pychę Egipską, i będzie zgładzone wszystko mnóstwo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Zagładzę i wszystko bydło jego, które jest przy wodach wielkich, tak, że ich więcej nie zmąci noga człowiecza, ani kopyta bydlęce mącić ich będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Tedy uczynię, że się wody ich ustoją, a rzeki ich jako oliwa pójdą, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Gdyż obrócę ziemię Egipską w spustoszenie, a ziemia będzie wypróżniona z pełności swojej, gdy pobiję wszystkich mieszkających w niej; i dowiedzą się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Toć jest lament, którym nad nią lamentować będą; córki narodów narzekać będą nad nią, nad Egiptem i nad wszystkiem mnóstwem jego narzekać będą, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Potem dwunastego roku, piętnastego dnia tegoż miesiąca, stało się słowo Pańskie do mnie, mówiąc;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Synu człowieczy! narzekaj nad mnóstwem Egipskiem, a zepchnij je, i córki tych narodów sławnych aż do najniższych miejsc ziemi, do tych, co zstępują do dołu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'I mów: Nad kogożeś wdzięczniejszy? Zstąp, a połóż się z nieobrzezańcami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'W pośród pobitych mieczem upadną; pod miecz podany jest, wywleczcież go ze wszystką zgrają jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Mówić do niego będą najmocniejsi z mocarzów z pośrodku grobu z pomocnikami jego, którzy tam zstąpiwszy, leżą z nieobrzezańcami pobitymi mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Tam jest Assur, i wszystka zgraja jego, w około niego są groby jego; wszyscy ci pobici upadli od miecza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Którego groby położone są przy stronach dołu, aby była zgraja jego w około grobu jego; ci wszyscy pobici polegli od miecza, którzy puszczali strach w ziemi żyjacych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Tam Elam i wszystka zgraja jego około grobu jego, ci wszyscy pobici upadli od miecza, którzy zstąpili w nieobrzezce do niskości ziemi, którzy puszczali strach swój w ziemi żyjących; jużci odnoszą hańbę swoją z tymi, którzy zstępują do dołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'W pośrodku pobitych postawili mu łoże, i wszystkiej zgrai jego, w około niego są groby jego; wszyscy ci nieobrzezańcy pobici są mieczem, przychodził strach ich na ziemię żyjących, jużci odnoszą hańbę swoję z tymi, którzy zstąpili do grobu, a w poś rodku pobitych położeni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Tam Mesech, Tubal i wszystka zgraja jego, i w około niego groby jego, ci wszyscy nieobrzezańcy pobici mieczem, choć puszczali strach swój w ziemi żyjących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Aczkolwiekci jeszcze nie polegli z mocarzami, którzy upadli z nieobrzezańców, co zstąpili do grobu z wojennym orężem swoim, i położyli miecze swe pod głowy swe; a wszakże przyjdzie nieprawość ich na kości ich, chociaż strach tych mocarzów był w ziemi żyjących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'I ty w pośrodku nieobrzezańców starty będziesz, i będziesz leżał między pobitymi mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Tam Edom, i królowie jego, i wszyscy książęta jego, którzy położeni są, z mocą swoją i z pobitymi mieczem; i ci z nieobrzezańcami leżeć będą, i z tymi, którzy zstępują do dołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Tam wszyscy zgoła książęta północnej strony, i wszyscy Sydończycy, którzy zstępują do pobitych z strachem swoim, za moc swoję wstydzić się będą, i leżeć będą ci nieobrzezańcy z pobitymi mieczem, a odniosą hańbę swoję z tymi, którzy zstępują do dołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Tych ujrzawszy Farao ucieszy się nad wszystką zgrają swoją, która jest mieczem pobita, Farao i wszystko wojsko jego, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Bo puszczę strach mój w ziemi żyjących, i położony będzie między nieobrzezańcami z pobitymi mieczem Farao i wszystka zgraja jego, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Synu człowieczy! mów do synów ludu twego, a rzecz do nich: Gdy przywiodę miecz na którą ziemię, jeźliże lud onej ziemi weźmie męża jednego z granic swoich, a postanowi go sobie za stróża,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'A on widząc miecz przychodzący na onę ziemię, zatrąbiłby w trąbę i przestrzegłby lud,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'A któryby słyszał głos trąby, i nie dbałby na przestrogę, a wtem przyszedłszy miecz, zgładziłby go; krew jego będzie na głowie jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Bo głos trąby słyszał, wszakże nie dbał na przestrogę, dlatego krew jego na nim będzie; być był przyjął przestrogę, zachowałby był duszę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Ale jeźliby stróż ujrzał miecz przychodzący, a nie zatrąbiłby w trąbę, a luduby nie przestrzegł, i przyszedłby miecz, i zniósłby którego z nich, takowy będzie w nieprawości swojej zachwycony; ale krwi jego z ręki onego stróża szukać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Ciebieć, synu człowieczy! ciebiem postanowił stróżem domu Izraelskiego, abyś słysząc słowo z ust moich, przestrzegł ich odemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Gdybym Ja tedy rzekł niezbożnemu: Niezbożniku! śmiercią, umrzesz, a tybyś mu tego nie powiedział, przestrzegając niezbożnika od drogi jego; tenci niezbożnik dla nieprawości swojej umrze; ale krwi jego z ręki twojej szukać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Ale jeźlibyś ty przestrzegł niezbożnego od drogi jego, aby się od niej odwrócił, wszakże nie odwróciłby się od drogi swojej, onci dla nieprawości swojej umrze; ale ty duszę swoję wybawisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'A tak ty, synu człowieczy! mów do domu Izraelskiego: Tak powiadacie mówiąc: Przeto, że występki nasze i grzechy nasze są na nas, tak, że w nich schniemy, i jakożbyśmy żyć mogli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Rzeczże tedy do nich: Jako żyję Ja, mówi panujący Pan: Nie chcę śmierci niepobożnego, ale aby się odwrócił niepobożny od drogi sojej, a żył. Odwróćcież się, odwróćcież się od złych dróg swoich, przeczże macie umrzeć, o domie Izraelski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Ty tedy, synu człowieczy! mów do synów ludu swego: Sprawiedliwość sprawiedliwego nie wybawi go w dzień przestępstwa jego, a niezbożny nie upadnie w swojej niezbożności w dzień, któregoby się odwrócił od niezbożności swojej; także sprawiedliwy nie będzie mógł żyć dla sprawiedliwości swojej w dzień, któregoby zgrzeszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Jeźlibym zaś rzekł sprawiedliwemu: Pewnie żyć będziesz, a onby ufając sprawiedliwości swojej czynił nieprawość, żadna sprawiedliwość jego nie przyjdzie na pamięć; ale dla tej nieprawości swojej, którą czynił, umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Zasię, rzekęli niepobożnemu: Śmiercią umrzesz, a onby się odwrócił od grzechu swego, i czyniłby sąd i sprawiedliwość,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'Wróciłby niezbożny zastaw, a co wydarł, oddałliby, i chodziłby w ustawach żywota, nie czyniąc nieprawości, pewnie żyć będzie, a nie umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'Żadne grzechy jego, któremi grzeszył, nie będą mu wspominane; sąd i sprawiedliwość czynił, pewnie żyć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'A wżdy mówią synowie ludu twego: Nie prawa jest droga Pańska, choć onych samych droga nie jest prawa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Gdyby się odwrócił sprawiedliwy od sprawiedliwości swojej, a czyniłby nieprawość, umrze dla niej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Ale gdyby się odwrócił niezbożny od niezbożności swojej, a czyniłby sąd i sprawiedliwość, dlatego żyć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'A przecie mówicie: Nie prawa jest droga Pańska; każdego z was według drogi jego sądzić będę, o domie Izraelski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'I stało się dwunastego roku, dziesiątego miesiąca, piątego dnia tegoż miesiąca od zaprowadzenia naszego, że przyszedł do mnie jeden, który uszedł z Jeruzalemu, mówiąc: Dobyto miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'A ręka Pańska była przy mnie w wieczór przedtem, niż przyszedł ten, który uciekł, i otworzyła usta moje, aż do mnie rano przyszedł; otworzyła mówię usta moje, abym niemym dalej nie był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Synu człowieczy! Obywatele tych spustoszonych miejsc w ziemi Izraelskiej powiadają, mówiąc: Abraham sam jeden był, a wżdy posiadł tę ziemię; ale nas jest wiele, namci dana jest ta ziemia w osiadłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Dlategoż mów do nich: Tak mówi panujący Pan: Ze krwią jadacie, i oczy swe podnosicie do plugawych bałwanów swoich, i krew wylewacie, a chcielibyście tę ziemię posiąść?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Stoicie na mieczu waszym, czynicie obrzydliwość, a każdy żonę bliźniego swego plugawi; izali ziemię posiądziecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Tak rzecz do nich: Tak mówi panujący Pan: Jako żyję Ja, że ci, którzy są na miejscach spustoszonych, od miecza polegną; a kto jest na polu, tego podam bestyjom na pożarcie; a którzy są na zamkach albo w jaskiniach, morem pomrą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'I podam ziemię na wielkie spustoszenie, i ustanie pycha mocy jej; i spustoszeją góry Izraelskie, a nie będzie, ktoby po nich chodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'I dowiedzą się, żem Ja Pan, gdy podam ziemię ich na wielkie spustoszenie dla wszystkich obrzydliwości ich, które czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Ale ty, synu człowieczy! słuchaj. Synowie ludu twojego często mówią o tobie około ścian i we drzwiach domów, i mówi jeden do drugiego, i każdy do bliźniego swego, mówiąc: Pójdźcie, a posłuchajcie, co za słowo od Pana wyszło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'I schodzą się do ciebie, tak, jako się schodzi lud, i siadają przed obliczem twojem, jako lud mój, i słuchają słów twoich, ale ich nie czynią; a choć je sobie usty swemi smakują, wszakże za szkaradnym zyskiem swoim serce ich chodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'A oto tyś im jest jako pieśń wdzięczna pięknego głosu, i dobrze umiejętnego śpiewaka; słuchając w prawdzie słów twoich, ale ich nie czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Lecz gdy to przyjdzie, (jakoż oto przychodzi) dopiero się dowiedzą, że prorok był w pośrodku nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'I stało się słowo Pańskie do mnie mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Synu człowieczy! prorokuj przeciwko pasterzom Izraelskim, prorokuj, a mówi do tych pasterzy: Tak mówi panujący Pan: Biada pasterzom Izraelskim, którzy sami siebie pasą!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Izali pasterze trzody paść nie mają? Tłustość jadacie, a wełną się przyodziewacie, to, co jest tłustego zabijacie, a trzody nie pasiecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Słabych nie posilacie, a chorego nie leczycie, i złamanego nie zawiązujecie, a zapłoszonego nie przywodzicie, ani zgubionego nie szukacie, owszem, nad nimi surowie i srodze panujecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Tak, że rozproszone będąc są bez paterza i stały się na pożarcie wszelkiemu zwierzowi polnemu. ponieważ się rozpierzchnęły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Błąkają się owce moje po wszystkich górach, i po każdym pagórku wysokim; owszem, po wszystkiej ziemi rozproszyły się owce moje, a nie był, ktoby ich szukał, i ktoby się za niemi pytał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Dlatego, wy pasterze! słuchajcie słowa Pańskiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Jako żyję Ja, mówi panujący Pan: Przeto, iż trzoda moje jest na łup dana, a owce moje są na pożarcie wszelkiemu zwierzowi polnemu, będąc bez pasterza a iż nie szukają pasterze moi owiec moich, ale tylko pasterze samych siebie pasą, a owiec moich nie pasą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Przetoż o pasterze! słuchajcie słowo Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Tak mówi panujący Pan: Otom Ja przeciwko pasterzom, i szukać będę owiec moich z rąk ich, a uczynię, że oni przestaną paść owiec moich, aby nie paśli więcej pasterze samych siebie; wydrę zaiste owce moje z gęby ich, i nie będą im więcej pokarmem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Bo tak mówi panujący Pan: Oto Ja, Ja szukać będę owiec moich, i pytać się za niemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Jako się pyta pasterz o trzodę swoję, kiedy bywa w pośrodku owiec swoich rozproszonych: tak się Ja będę pytał za owcami mojemi, i wyrwę je ze wszystkich miejsc, kędy były rozproszone w dzień obłoku i chmury;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'I wywiodę je z narodów, a zgromadzę je z ziem, i przywiodę je do ziemi ich, a paść je będę na górach Izraelskich nad strumieniami, i po wszystkich mieszkaniach tej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Na pastwiskach dobrych paść je będę, a na górach wysokich Izraelskich będą pastwiska ich; tam odpoczywać będą w trawach bujnych, a w paszach tłustych paść się będą na górach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Ja sam paść będę owce moje, i Ja im poczynię legowiska, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Zgubionej szukać będę, a zapłoszoną przywiodę, i połamaną zawiążę, a słabą posilę; ale tłustą i mocną wytracę; bo je będę pasł w sądzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'A wy, trzodo moja! tak mówi panujący Pan: Oto Ja uczynię sąd między owcą a owcą, między barany a kozły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Azaż wam na tem mało, paść się na dobrej paszy, że jeszcze ostatek pastwisk waszychdepczecie nogami swojemi? a czystą wodę pić, że ostatek nogami swemi mącicie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Tak, że się owce moje tem, co było podeptane nogami waszemi, paść, a męciny nóg waszych pić muszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Przetoż tak mówi panujący Pan do nich: Oto Ja, Ja sąd uczynię między bydlęciem tłustym i między bydlęciem chudem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Dlatego, że wy bokami i plecami trącacie, a rogami waszemi bodziecie wszystkie słabe, tak żeścieje precz rozegnali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Przetoż wyzwolę owce moje, że już dalej łupem nie będą, i uczynię sąd między owcą i owcą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'I wzbudzę nad niemi pasterza jednego, który je paść będzie, sługę mego Dawida, on je paść będzie, i on będzie pasterzem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'A Ja Pan będę im Bogiem, a sługa mój Dawid książęciem w pośrodku nich, Ja Pan mówiłem to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'I uczynię z nimi przymierze pokoju, a wygubię zły zwierz z ziemi; i będą na puszczy bezpiecznie mieszkać, a w lasach sypiać będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Nadto dam im, i okolicy pagórka mego, błogasławieństwo, i spuszczać będę deszcz czasu swego; deszcze to błogosłwieństwa będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'I wypuści drzewo polne owoc swój, a ziemia wyda urodzaj swój, i będą na ziemi swojej bezpieczni, a dowiedzą się, żem Ja Pan, gdy połamię zawory jarzma ich, a wyrwię je z ręki tych, którzy je zniewalają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'I nie będą więcej łupem narodom, a zwierz ziemiski pożerać ich nie będzie; ale mieszkać będą bezpiecznie, a nie będzie, ktoby je straszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'I wzbudzę im latorośl sławną, że nie będą więcej głodem niszczeni na ziemi, ani poniosą pohańbienia od pogan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'I dowiedzą się, żem Ja Pan, Bóg ich, z nimi, a oni lud mój, dom Izraelski, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Ale wy owce moje, owce pastwiska mego, wyście lud mój, a Jam Bóg wasz, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Synu człowieczy! obróć twarz swoję przeciwko górze Seir, a prorokuj przeciwko niej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'I mów do niej: Tak mówi panujący Pan: Otom Ja przeciwko tobie, góro Seir! a wyciągnę rękę moję na cię, i podam cię na wielkie spustoszenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Miasta twoje w spustoszenie obrócę, że będziesz spustoszona, i dowiesz się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Przeto, iż wieczną nieprzyjaźń wiedziesz, i rozpraszasz synów Izraelskich ostrzem miecza czasu utrapienia ich, czasu wykonywania kaźni ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Dlatego, jako żyję Ja, mówi panujący pan, że cię podam na zabicie, a krew cię ścigać będzie; ponieważ krwi rozlewania w nienawiści nie masz, przetoż cię krew ścigać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'I obrócę górę Seir w wielkie spustoszenie, a wygubię z niej przechodzącego, i wracającego się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'I napełnię góry jej pobitymi jej; na pagórkach twoich,i na dolinach twoich, i przy wszystkich strumieniach twoich pobici mieczem polegną na nich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Na pustynie wieczne podam cię, i w miastach twoich mieszkać nie będą; a dowiecie się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Przetoż iż mówisz: Te dwa narody, i te dwie ziemie moje będą a posiądziemy tę, w której Pan mieszkał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Dlategoż, jako żyję Ja, mówi panujący Pan, że uczynię według gniewu twego i według zawiści twojej, którąś czyniła w nienawiści swej przeciwko nim; i będę poznany od nich, gdy cię sądzić będę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'I dowiesz się, żem Ja Pan słyszał wszystkie urągania twoje, któreś wyrzekła przeciw górom Izraelskim, mówiąc: Spustoszone są, a nam podane są ku pożarciu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Boście się przeciwko mnie wynosili usty waszemi, a rozmnożyliście słowa swoje przeciwko mnie, com Ja słyszał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Tak mówi panujący Pan: Jako się ta wszystka ziemia weseli, tak cię obrócę w pustnię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Jako się ty weselisz nad dziedzictwem domu Izraelskiego, przeto, że jest spustoszone, tak uczynię i tobie; będziesz spustoszona, o góro Seir! a zgoła wszystka ziemia Edomska; i dowiedzą się żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'A ty synu człowieczy! prorokuj o górach Izraelskich, a mów: Góry Izraelskie! słuchajcie słowa Pańskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Tak mówi panujący Pan: Przeto, iż nieprzyjaciel rzekł o was: Hej, hej! i wysokości wieczne dostały się nam w dziedzictwo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Przetoż prorokuj a mów: Tak mówi panujący Pan: Dlatego, dlatego, mówię, iż was zburzyli, a pochłonęli zewsząd, i staliście się dziedzictwem pozostałym narodom, i przyszliście na język i na obmowisko ludzkie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Przetoż, góry Izraelskie! słuchajcie słowa panującego Pana. Tak mówi panujący Pan górom i pagórkom, strumieniom i dolinom, pustyniom, obalinom, i miastom opuszczonym, które są na splundrowanie, i na pośmiewisko ostatkowi narodów okolicznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Dlatego, tak mówi panujący Pan, zaprawdę w ogniu zapalczywości mojej mówić będę przeciw ostatkom tych narodów, i przeciwko wszystkiej ziemi Edomskiej, którzy sobie przywłaszczyli ziemię moję za dziedzictwo z weselem całego serca, i z ochotnem pust oszeniem, aby siedlisko wygnanych jego było na rozszarpanie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Przetoż prorokuj o ziemi Izrelskiej, a mów górom, i pagórkom, strumieniom i dolinom: Tak mówi panujący Pan: Oto Ja w zapalczywości mojej, i w popędliwości mojej mówię, dlatego, iż hańbę od narodów ponosicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Przetoż tak mówi panujący Pan: Jam podniósł rękę moję, iż te narody, które są zewsząd około was, sami hańbę swoję poniosą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'A wy, góry Izraelskie! wypuście gałązki swe, i owoc swój przynieście ludowi memu Izraelskiemu, gdy się przybliżą a przyjdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Bo oto Ja idę do was, i nawrócę się do was, a uprawiane i posiewane będziecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'I rozmnożę na was ludzi, wszystek zgoła dom Izarelski; i będą mieszkać w miastach, a miejsca zburzone pobudowane będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Rozmnożę, mówię, na was ludzi i dobytek, a rozmnożą się i urosną; i sprawię, że mieszkać będziecie jako za dawnych czasów waszych, i lepiej wam czynić będę niż przedtem, i dowiecie się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Bo przyprowadzę na was ludzi, lud mój Izraelski, i posiądą cię, i będziesz im dziedzictwem, a więcej ich nie osierocisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Tak mówi panujący Pan: Dlatego, że o was powiadają: Tyś jest ta ziemia, która pożerasz ludzi, i osieracasz narody twoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'Przetoż nie będziesz więcej ludzi pożerała, ani narodów twoich więcej osieracała, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'I nie dopuszczę w tobie więcej słyszeć hańby narodów, ani zelżywości ludzkiej nie poniesiesz więcej, i narodów twoich nie przywiedziesz więcej do upadku, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Synu człowieczy!dom Izrelski mieszkając w ziemi swej splugawiał ją drogami swemi i sprawami swemi, tak, że droga ich przed obliczem mojem była jako nieczystość niewiasty odłączonej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Przetoż wylałem gniew mój na nich dla krwi, którą wylali na ziemię, i dla plugawych bałwanów ich, któremi ją splugawili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'I rozproszyłem ich między narody, a rozwiani są po ziemiach; według dróg ich i według spraw ich sądziłem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'A gdy weszli do narodów, do których przyszli, pomazali tam imię świątobliwości mojej, gdy o nich mówiono: Lud to Pański, a z ziemi jego wyszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Alem im sfolgował dla imienia świętobliwości mojej, które splugawił dom Izraelski między narodami, do których przyszli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Przetoż mów do domu Izraelskiego: Tak mówi panujący Pan: Nie dla was Ja to czynię, o domie Izraelski! ale dla imienia świętobliwości mojej, któreście splugawili między narodami, do którycheście przyszli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Abym poświęcił wielkie imię moje, które było splugawione między narodami, któreście wy zmazali w pośrodku ich; i dowiedzą się narody, żem Ja Pan, mówi panujący Pan, gdy poświęcony będę w was przed oczyma ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Bo was zbiorę z narodów, i zgromadzę was ze wszystkich ziem, i przywiodę was do ziemi waszej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'I pokropię was wodą czystą, a oczyszczeni będziecie od wszystkich nieczystót waszych, i od wszystkich plugawych bałwanów waszych oczyszczę was;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'I dam wam serce nowe, a ducha nowego dam do wnętrzności waszych, i odejmę serce kamienne z ciała waszego, a dam wam serce mięsiste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Ducha mego, mówię, dam do wnętrzności waszej, a uczynię, że w ustawach moich chodzić, a sądów moich przestrzegać, i czynić je będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'A będziecie mieszkać w ziemi, którąm dał ojcom waszym, i będziecie ludem moim, a Ja będę Bogiem waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Bo was wyzwolę od wszystkich nieczystót waszych, i przywołam zboża, i rozmnożę je, a nie dopuszczę na was głodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Rozmnożę też owoc drzew, i urodzaje polne, abyście więcej nie nosili hańby głodu między narodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'I wspomnicie na złe drogi wasze, i na sprawy wasze, które nie były dobre, i omierzniecie sami sobie w oczach swoich dla nieprawości waszych i dla obrzydliwości waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Nie dla wasci Ja to czynię, mówi panujący Pan, niech wam to jawno będzie; sromajcie się, a wstydźcie się za drogi wasze, o domie Izraelski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Tak mówi panujący Pan: Którego was dnia oczyszczę od wszystkich nieprawości waszych, osadzę miasta, a miejsca zburzone będą pobudowane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'A tak ziemia spustoszała sprawowana będzie, która przedtem była spustoszona przed oczyma wszystkich przechodzących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'I rzeką: Ziemia ta spustoszała stała się jako ogród Eden; także miasta puste i opuszczone i rozwalone, obronne są i osadzone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'I dowiedzą się narody, którekolwiek zostną około was, żem Ja Pan pobudował rozwaliny, a nasadził miejsca spustoszone. Ja Pan mówiłem, i uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Tak mówi panujący Pan: Jeszcze tego będzie u mnie szukał dom Izraelski, abym to im uczynił, abym ich rozmnożył w ludzi jako trzodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Jako trzodę na ofiary, jako trzodę Jeruzalemską na święta jego uroczyste, tak spustoszone miasta będą napełnione trzodami ludzi; i dowiedzą się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Była nademną ręka Pańska, i wywiódł mię Pan w duchu, i postawił mię w pośrodku pola, które było pełne kości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'I przewiódł mię przez nie w około a w około, a oto było ich bardzo wiele na onem polu, a oto były bardzo suche.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'I rzekł do mnie: Synu człowieczy! ożyjąli te kości? I rzekłem: Panujący Panie! ty wiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'W tem rzekł do mnie: Prorokuj o tych kościach, a mów do nich: Kości suche, słuchajcie słowa Pańskiego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Tak mówi panujący Pan o tych kościach: Oto ja wprowadzę w was ducha, a ożyjecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'A włożę na was żyły, i uczynię, że porośnie na was mięso, i powlekę was skórą, a dam wam ducha, i ożyjecie, i poznacie, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Prorokowałem tedy, jako mi rozkazano; i stał się szum, gdym ja prorokował, a oto poruszenie; i przystąpiły kości, kość do kości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'I ujrzałem, a oto na nich żyły, i mięso porosło, i powleczone były skórą po wierzchu; ale ducha nie było w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'I rzekł do mnie: Prorokuj do ducha, prorokuj, synu człowieczy! i rzecz do ducha: Tak mówi panujący Pan: Od czterech wiatrów przyjdź, duchu! i natchnij te pobite, a niech ożyją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Prorokowałem tedy jako mi był rozkazał, i wstąpił w nie duch, a ożyły, i stanęły na nogach swoich, wojsko nader bardzo wielkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'I rzekł do mnie: Synu człowieczy! te kości są wszystek dom Izraelski. Oto mówią: Wyschły kości nasze, i zginęła nadzieja nasza, wygładzeni jesteśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Dlategoż prorokuj, a mów do nich: Tak mówi panujący Pan: Oto Ja otworzę groby wasze, i wywiodę was z grobów waszych, ludu mój! i przywiodę was do ziemi Izraelskiej!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'I dowiecie się, żem Ja Pan, gdy Ja otworzę groby wasze, a wywiodę was z grobów waszych, ludu mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'I dam w was ducha mego, a ożyjecie, i dam wam odpocząć w ziemi waszej; i dowiecie się, że Ja Pan mówię to i uczynię, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'A ty, synu człowieczy! weźmij sobie jedno drewno, i napisz na niem: Judzie i synom Izraelskim, towarzyszom jego. Weźmij też i drugie drewno, a napisz na niem: Józefowi drewnu Efraimowemu, i wszystkiemu domowi Izraelskiemu, towarzyszom jego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'I złóż je sobie jedno do drugiego w jedno drewno, aby były jako jedno w ręce twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'A gdy rzekną do ciebie synowie ludu twego, mówiąc: Izali nam nie oznajmisz, co przez to rozumiesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Rzeczesz im: Tak mówi panujący Pan: Oto Ja wezmę drewno Józefowe, które jest w ręce Efraimowej i pokolenia Izraelskie, towarzyszów jego, i przyłożę je z nim do drewna Judowego, i uczynię je jednem drewnem, a będą jednem w ręce mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'A gdy będą one drewna, na których napiszesz, w ręce twojej przed oczyma ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Tedy rzecz do nich: Tak mówi panujący Pan: Oto Ja wezmę synów Izraelskich z pośrodku tych narodów, do których byli zaszli, i zgromadzę ich zewsząd, a przywiodę ich do ziemi ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'I uczynię ich narodem jednym w ziemi, na górach Izraelskich, i będzie król jeden nad onymi wszystkimi za króla; a nie będą więcej dwa narody, nie rozdzielą się nigdy więcej na dwoje królestw;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Nie splugwią się więcej plugawemi bałwanami swemi, i obrzydliwościami swemi, ani jakiemi przestępstwy swemi; i wybawię ich z każdego mieszkania ich, gdzie zgrzeszyli, i oczyszczę ich, i będą ludem moim, a Ja będę Bogiem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'A sługa mój Dawid będzie królem nad nimi, i pasterza jednego wszyscy mieć będą, aby w sądach moich chodzili, i ustaw moich przestrzegali, i czynili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'I będą mieszkać w onej ziemi, którąm był dał słudze memu Jakóbowi, w której mieszkali ojcowie wasi; będą, mówię, w niej mieszkali oni i synowie ich, i synowie synów ich aż na wieki, a Dawid, sługa mój, będzie książęciem ich na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'I uczynię też z nimi przymierze pokoju, a przymierze wieczne będzie z nimi; i osadzę ich i rozmnożę ich, i założę świątnicę moję w pośrodku ich na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'I będzie przybytek mój między nimi, i będę Bogiem ich, a oni będą ludem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'I dowiedzą się narody, żem Ja Pan, który poświęcam Izraela, gdy będzie świątnica moja w pośrodku ich na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'I stało się słowo Pańskie do mnie mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Synu człowieczy! obróć twarz swoję przeciw Gogowi w ziemi Magog, książęciu głównemu w Mesech i Tubal, a prorokuj przeciw niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'I rzecz: Tak mówi panujący Pan: Otom Ja przeciw tobie, o Gogu, księciu główny w Mesechu i w Tubalu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Bo cię zawrócę, i włożę wędzidło w czeluści twoje, i wywiodę cię, i wszystko wojsko twoje, konie i jezdnych wszystkich poubieranych w zupełny kirys, hufy wielkie z tarczami i z przyłbicami, wszystkich tych, którzy władają mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Persów, Murzynów i Putejczyków z nimi, tych wszystkich z tarczami i z przyłbicami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomer i wszystkie hufy jego, dom Togormy mieszkającego w stronach północnych, i wszystkie poczty jego, narodów wiele z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Gotuj się, a wypraw się, ty i wszystkie półki twoje, które się zebrały do ciebie, a bądź stróżem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Po wielu dniach nawiedziony będziesz, a w ostatnie lata przyciągniesz na lud uwolniony od miecza, i zebrany z wielu narodów, na góry Izraelskie, które były pustynią ustawiczną, gdyż oni z narodów będąc wywiedzieni, wszyscy bezpiecznie mieszkać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'W tem przyciągniesz i przyjdziesz jako burza, będziesz jako obłok okrywający ziemię, ty i wszystkie poczty twoje, i wiele narodów z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Tak mówi panujący Pan: Dnia onego wstąpią dziwne rzeczy na serce twoje, a będziesz złe zamysły myślał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'I rzeczesz: Wtargnę do ziemi, w której są wsi; przypadnę na spokojnych i bezpiecznie mieszkających, na wszystkich, którzy mieszkają bez muru, a zawór i bram nie mają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Abym wziął łupy, a rozchwycił korzyści; abym obrócił rękę swoję na spustoszone miejsca już znowu osadzone, i na lud zgromadzony z narodów, którzy się bydłem i kupiectwem bawią, a mieszkają w pośrodku ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Seba, i Dedan, i kupcy morscy, i wszystkie lwięta jego rzekną do ciebie: Izali ty na branie łupów idziesz? Izali na rozchwycenie korzyści zebrałeś półki twoje, abyś wybrał srebro i złoto, i zabrał dobytek i majętności, a żebyś zebrał łup wielki?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Przetoż prorokuj, synu człowieczy! a mów do Goga: Tak mówi panujący Pan: Izali się w on dzień, gdy lud mój Izraelski bezpiecznie mieszkać będzie, nie dowiesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'I przyjdziesz z miejsca swego z stron północnych, ty i narodów wiele z tobą, wszyscy wsiadający na konie, lud wielki i wojsko gwałtowne;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'I przypadniesz na lud mój Izraelski jako obłok, abyś okrył tę ziemię. W ostatnie dni przywiodę cię do ziemi mojej, aby mię poznały narody, gdy będę poświęcony w tobie, przed oczyma ich, o Gogu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Tak mówi panujący Pan: Azażeś ty nie jest on, o którymem powiedział za dni dawnych przez sług moich, proroków Izraelskich, którzy prorokowali za dni onych lat, żem cię miał przywieść na nich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Wszakże w on dzień, w dzień, którego przyciągnie Gog na ziemię Izraelską, mówi panujący Pan, wzruszy się gniew mój w popędliwości mojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'A w gorliwości mojej, i w ogniu gniewu mego mówić będę, że dnia onego będzie wielki rozruch w ziemi Izraelskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'I zadrżą od obliczności mojej ryby morskie, i ptastwo niebieskie, i zwierz polny, i wszelka gadzina płazająca się po ziemi, i wszyscy ludzie, którzy są na obliczu ziemi; i porozwalają się góry, i upadną wysokie wieże, i każdy mur obali się na zie mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Bo przywołam przeciwko niemu po wszystkich górach moich miecz, mówi panujący Pan; miecz każdego obróci się na brata jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'I będę się z nim sądził morem i krwią, a deszcz gwałtowny i grad kamienny, ogień i siarkę spuszczę nań, i na wojska jego, i na wiele narodów, które z nim będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'I pokażę się wielmożnym, i poświęcę się, i znajomym się uczynię przed oczyma wielu narodów, i dowiedzą się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'A ty, synu człowieczy! prorokuj przeciwko Gogowi, a mów: Tak mówi panujący Pan: Otom Ja przeciwko tobie, Gogu, księciu główny w Mesechu i w Tubalu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'I zawrócę cię, a sześcioraką plagą ścisnę cię, i wywiodę cię z stron północych, a przywiodę cię na góry Izraelskie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'A wytrącę łuk twój z ręki twojej lewej, i strzały twoje z prawej ręki twojej wybiję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Na górach Izraelskich upadniesz, ty i wszystkie hufy twoje, i narody, które z tobą będą; ptastwu i wszelkiej rzeczy skrzydlastej, i zwierzowi polnenu podam cię na pożarcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Na obliczu pola upadniesz; bom Ja to wyrzekł, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'I puszczę ogień na Magoga, i na tych, co bezpiecznie na wyspach mieszkają; a dowiedzą się, żem Ja Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'A imię świętobliwości mojej oznajmię w pośrodku ludu mego Izraelskiego, i nie dopuszczę więcej zmazać imienia świętobliwości mojej; i dowiedzą się narody, żem Ja Pan, święty w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Oto przyjdzie i stanie się to, mówi panujący Pan, tegoż dnia, o któremem mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Tedy wynijdą obywatele miast Izraelskich, a zapaliwszy spalą oręże i tarcze, i drzewca, łuki i strzały, kije ręczne i włócznie, i będą z nich niecić ogień przez siedm lat;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'A nie będą drew nosić z pola, ani ich rąbać w lasach, ale z oręża ogień niecić będą a złupią tych, którzy ich łupili, i splundrują tych, którzy ich plundrowali, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'I stanie się dnia onego, że dam Gogowi miejsce na grób, tam w Izraelu, dolinę, którędy chodzą na wschód słońca ku morzu, która zatka usta mimo idących; i pogrzebią tam Goga i wszystkie zgraje jego, a będą ją zwać doliną mnóstwa Gogowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Bo ich grześć będzie dom Izrelski przez siedm miesięcy aby oczyścili ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'A tak pogrzebie ich wszystek lud onej ziemi, i obróci się im to w sławę, w dzień, którego Ja będę uwielbiony, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'I obiorą mężów ustwaicznych, którzyby się przechodzili po onej ziemi, przechodzili, mówię, a chowali tych, którzyby zostali na ziemi, aby ją wyczyścili, a po wyjściu siedmiu miesięcy szukać poczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'A ci przechodząc chodzić będą po ziemi, a ujrzawszy kości człowiecze postawią przy nich znak, aby je pochowali ci, co chowają umarłych, w dolini mnóstwa Gogowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Owszem, to mnóstwo jego będzie ku sławie miastu, gdy oczyszczą onę ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'A ty synu człowieczy! tak mówi panujący Pan: Rzecz ptastwu i wszelkiej rzeczy skrzydlastej, i każdej bestyi polnej: Zbierzcie się, a przyjdźcie, zgromadźcie się zewsząd na ofiarę moję, którą Ja wam sprawuję, ofiarę wielką na górach Izraelskiech, żebyście jedli mięso, i pili krew.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Mięso mocarzy jeść będziecie, a krew książąt ziemskich pić będziecie, baranów, baranków, i kozłów, i cielców, którzy wszyscy potyli w Basan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Najecie się tłustości do sytości a napijecie się krwi do upicia z tej ofiary mojej, którą wam nagotuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'I nasycicie się z stołu mego końmi, i jeźdźcami, mocarzami, i każdym mężem walecznym, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'A tak objawię chwałę moję między narodami, i oglądają wszystkie narody sąd mój, którym uczynił, i rękę moję, którąm na nie wyciągnął;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'A dowie się dom Izraelski, żem Ja Pan, Bóg ich od onego dnia i na potem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Poznają też i narody, iż dla nieprawości swojej zawiedzieni są do więzienia dom Izraelski, dlatego, iż wystąpili przeciwko mnie. Dlategom też był zakrył oblicze swoje przed nimi, a podałem ich w ręce nieprzyjaciół ich, aby wszyscy od miecza polegli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Według nieczystości ich, i według przewrotności ich obszedłem się z nimi, i zakryłem oblicze moje przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Przetoż tak mówi panujący Pan: Jużci przywrócę więźniów Jakóbowych; a zmiłuję się nad wszystkim domem Izraelskim; i gorliwym będę dla imienia świętobliwości mojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Gdy odniosą pohańbienie swoje i wszystko przestępstwo swoje, którem wystąpili przeciwko mnie, gdy bezpiecznie mieszkali w ziemi swojej, a nie był, ktoby ich trwożył;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'A gdy ich przywrócę z narodów, i zgromadzę ich z ziem nieprzyjaciół ich, i będę poświęcony w nich przed oczyma wielu narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Tedy się dowiedzą, żem Ja Pan, Bóg ich, gdy zawiódłszy ich do narodów zasię ich zgromadzę do ziemi ich, a nie zostawię tam więcej żadnego z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'I nie zakryję więcej oblicza mego przed nimi, gdyż wyleję ducha mojego na dom Izraelski, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Dwudziestego i piątego roku zaprowadzenia naszego, na początku roku, dziesiątego dnia miesiąca, czternastego roku po zburzeniu miasta, tegoż prawie dnia była nademną ręka Pańska, a przywiódł mię tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'W widzeniach Bożych przywiódł mię do ziemi Izraelskiej, a postawił mię na górze bardzo wysokiej, na której było jakoby budowanie miasta na południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'I przywiódł mię tam, a oto mąż, który był na wejrzeniu jako kształt miedzi, mając sznur lniany w ręce swej i laskę ku rozmierzaniu, a ten stał w bramie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'I mówił do mnie ten mąż: Synu człowieczy! patrz oczyma swemi, a uszyma swemi słuchaj, i przyłóż serce swoje do wszystkiego, coć okażę; boś tu na to przywiedziony, abyć to ukazano, a ty oznajmisz wszystko, co widzisz, domowi Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'A oto mur zewnątrz przy domu zewsząd w około; a w ręce onego męża była laska ku rozmierzaniu na sześć łokci, (a każdy łokieć na dłoń był nad zwyczajny dłuższy.) i wymierzył szerokość onego budowania na laskę jednę, i wysokość na laskę jednę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Potem wszedłszy do bramy, która była na drodze wschodniej, wstąpił po schodach jej, i wymierzył próg bramy na laskę jednę wszerz, a próg drugiej na jednę laskę wszerz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Każdą też komorę na jednę laskę wdłuż, a na jednę laskę wszerz; a między komorami był plac na pięć łokci, próg też bramy podle przysionku bramy wewnątrz był na jednę laskę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'I wymierzył przysionek bramy wewnątrz na jednę laskę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Wymierzył też przysionek bramy na ośm łokci, a podwoje jej na dwa łokcie, a ten przysionek bramy był wewnątrz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Komory też bramy ku drodze wschodniej były trzy z jednej a trzy z drugiej strony; jednaka miara była wszystkich trzech, jednaka też miara podwoi ich z obu stron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Wymierzył też szerokość drzwi onej bramy na dziesięć łokci, a długość bramy na trzynaście łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Była też wystawa przed komorami na jeden łokieć, także wystawa z drugiej strony na jeden łokieć, a każda też komora na sześć łokci z jednej, a na sześć łokci z drugiej strony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Potem wymierzył bramę od dachu komory jednej aż do dachu drugiej, szerokość na dwadzieścia i pięć łokci, a drzwi były przeciwko drzwiom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'I uczynił podwoje na sześćdziesiąt łokci, a każdy podwój u sieni i u bramy zewsząd w około był pod jedną miarą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'A od przodku bramy, gdzie się wchodzi do przodku przysionka bramy wnętrznej, było pięćdziesięt łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Okna też pochodziste były w komorach, i nad podwojami ich wewnątrz bramy zewsząd w około, także też i w przysionkach, a na oknach zewsząd w około wewnątrz, i na podwojach były palmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Potem mię przywiódł do sieni zewnętrznej, a oto komory i tło uczynione było w sieni wszędy w około, a trzydzieści komór było na onem tle.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'A to tło było po stronach bram, jako długie były bramy, a toć było tło niższe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Wymierzył także szerokość od przodku bramy niższej aż do przodku sieni wewnętrznej z dworu na sto łokci ku wschodowi i ku północy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Bramę też, która była ku północy przy sieni zewnętrznej, wymierzy wdłuż i wszerz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, '(A komory jej były trzy z jednej, a trzy z drugiej strony, a podwoje jej i przysionki jej były według pomiaru pierwszej bramy;) na pięćdziesiąt łokci była długość jej, a szerokość na dwadzieścia i pięć łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Okna też jej, i przysionki jej, i palmy jej były według pomiaru bramy onej, która patrzyła na wschód, a po siedmiu stopniach wstępowano na nią, a przysionki jej były tuż przed schodami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Także brama sieni wewnętrznej była przeciw bramie ku północy i ku wschodowi, a wymierzył od bramy do bramy sto łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Potem mię wywiódł na drogę południową, a oto brama była ku drodze południowej, i wymierzył podwoje jej, i przysionki jej według tejże miary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, '(A okna jej, i przysionki jej wszędy w około były, także jako i drugie) na pięćdziesięt łokci wdłuż a wszerz na dwadzieścia i pięć łokci,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Wschód też był do niej o siedmiu stopniach, a przysionki jej były przed nimi, także i palmy, jedna z jednej a druga z drugiej strony przy podwojach jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Rozmierzył też bramę sieni wewnętrznej ku południu, od bramy do bramy ku południu sto łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Potem mię wwiódł do sieni wewnętrznej przez południową bramę, i rozmierzył onę bramę południową według tychże miar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'A komory jej i podwoje jej i przysionki jej były według tychże miar, a okna jej i przysionki jej około niej zewsząd mające na pięćdziesiąt łokci wdłuż a wszerz na dwadzieścia i pięć łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'A przysionki zewsząd w około na dwadzieścia i pięć łokci wdłuż, a wszerz na pięćdziesiąt łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'A przysionki jej były jako sień zewnętrzna, mając palmy na podwojach; wchód też był do niej o ośmiu stopniach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Wwiódł mię także do sieni wewnętrznej drogą wschodnią, i wymierzył onę bramę według onychże miar;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Taże komory jej i podwoje jej i przysionki jej według onychże miar, i okna jej i przysionki jej wszędy w około; wdłuż na pięćdziesiąt łokci, a wszerz na dwadzieścia i pięć łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Taże przysionki jej przy sieni zewnętrznej, i palmy przy podwojach jej z obu stron; wchód też był do niej o ośmiu stopniach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Potem mię wwiódł do bramy północnej, i wymierzył ją według onychże miar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Komory jej, podwoje jej, i przysionki jej i okna jej były wszędy w około wdłuż na pięćdziesiąt łokci, a wszerz na dwadzieścia i pięć łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'A podwoje jej przy sieni zewnętrznej, i palmy przy podwojach jej z obu stron, a wchód był do niej o ośmiu stopniach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Były też komory i drzwi ich przy podwojach bram, a tam omywano całopalenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'W przysionku też bramy były dwa stoły z jednej strony, a dwa stoły z drugiej strony, na których bito całopalenia, i ofiary za grzech, i ofiary za występek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Na stronie też przed wchodem przy drzwiach bramy północnej były dwa stoły, także i przy drugiej stronie, która jest u przysionku bramy, były dwa stoły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Cztery stoły z jednej, a cztery stoły z drugiej strony były przy stronie bramy; ośm było wszystkich stołów, na których bito ofiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'A cztery stoły do całopalenia były z ciosanego kamienia, na półtora łokcia wdłuż, a wszerz na półtora łokcia, a wzwyż na jeden łokieć; na których kładziono naczynia, któremi bito całopalenia i inne ofiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Haki też wmięsz na jednę dłoń w domu wszędy w około były zgotowane, a mięso na stołach dla ofiar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Były też zewnątrz przed bramą wnętrzną komory śpiewaków w sieni wnętrznej, których rząd jeden był przy stronie bramy północnej, patrzący na południe; drugi rząd był przy stronie bramy wschodniej, patrzący na północ.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'I rzeł do mnie: Te komory, które patrzą ku drodze południowej, są dla kapłanów straż trzymających w domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'A te zaś komory, których przodek jest ku drodze północnej, są dla kapłanów straż trzymających koło ołtarza; ci są synowie Sadokowi, którzy się przybliżają z synów Lewiego do Pana, aby mu służyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'I wymierzył tę sień na cztery granie, wdłuż na sto łokci, a wszerz na sto łokci, a ołtarz był przed domem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Wwiódł mię potem do przysionka domu, i rozmierzył podwoje przysionka na pięć łokci z jednej, a na pięć łokci z drugiej strony; szerz zasię bramy była na trzy łokcie z jednej, a na trzy łokcie z drugiej strony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'A długość przysionka była na dwadzieścia łokci, a szerokość na jedenaście łokci, a po stopniach wchodzono do niego; słupy też były przy podwojach, jeden z jednej, a drugi z drugiej strony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'I wwiódł mię do kościoła, a wymierzył podwoje, sześć łokci wszerz z jednej strony, a sześć łokci wszerz z drugiej strony, według szerokości namiotu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'A szerokość drzwi była na dziesięć łokci, a boki drzwi na pięć łokci z jednej, a na pięć łokci z drugiej strony; i rozmierzył długość ich na czterdzieści łokci, a szerokość na dwadzieścia łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'A wszedłszy wewnątrz wymierzył podwoje na dwa łokcie, a drzwi na sześć łokci, a szerokość drzwi na siedm łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Wymierzył też długość świątnicy na dwadzieścia łokci, a szerokość jej na dwadzieścia łokci w kościele, i rzekł do mnie: To jest świątnica świętych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Wymierzył też mur domu na sześć łokci, a szerokość komory na cztery łokcie wszędy około domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'A te komory, komora nad komorą, były na trzydzieści i na trzy stopy, a schodziły się przy murze domu społem, tak, że się komory wszędy w około trzymały, a nie trzymały się na murze domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Bo się rozszerzał mur w około im dalej tem bardziej z wierzchu dla komór, które były około domu, od wierzchu aż do dołu zewsząd w około domu, ponieważ on dom im dalej tem szerszy był od wierzchu, a tak najniższe komory rozszerzały się ku wierzchow i dla średniej komory.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Widziałem też przy domu i najwyższe komory wszędy w około, a podłogi onych komór były wymierzone na całą laskę, to jest, na sześć łokci aż do końca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Szerokość też muru przy komorach z dworu była na pięć łokci, i plac próżny pod komorami, które były przy domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'A między komorami i komórkami była szerokość na dwadzieścia łokci około domu zewsząd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'A drzwi do komór były ku placowi onemu próżnemu, i były drzwi jedne ku drodze północnej, a drugie ku drodze południowej, a szerokość onego próżnego placu była na pięć łokci zewsząd w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'A budowanie, które było przed piętrem w kącie drogi zachodniej, było na siedmdziesiąt łokci na szerz, a mur onego budowania był na pięć łokci wszerz wszędy w około, a długość jego na dziewięćdziesiąt łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Potem rozmierzył dom, którego długość była na sto łokci; także i piętro i budowanie, i mury jego były wdłuż na sto łokci;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Także szerokość przodku domu i piętra ku wschodowi słońca była na sto łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Wymierzył też i długość budowania przed piętrem, które było za niem, także i ganki jego z jednej i z drugiej strony, a było tego na sto łokci, także kościół wnętrzny i z przysionkami sieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Progi i okna pochodziste, i ganki, które były w około po trzech stronach ich przeciwko progom, obite były deskami wszędy w około od ziemi aż do okien, także i okna deskami obite były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Od wierzchu drzwi aż do wnętrznej i zewnętrznej strony domu, wszystek mur zewsząd w około wewnątrz i zewnątrz dobrze wymierzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Która robota była uczyniona z Cherubinami, i z palmami, a każda palma była między Cherubinem a Cherubinem, a każdy Cherubin miał dwie twarze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Minowicie twarz ludzka była naprzeciwko palmy z jednej strony, a twarz lwięca naprzeciwko palmy z drugiej strony; tak uczyniono po wszystkim domu wszędy w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Od ziemi aż do wierzchu drzwi byli Cherubinowie i palmy wyryte, taże i na ścianie kościelnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Podwoje kościelne były na cztery granie, a kształt świątnicy był jako kształt kościelny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Ołtarz drewniany był na trzy łokcie wzwyż, a wdłuż na dwa łokcie z węgłami swemi; którego długość i ściany jego były drewniane. Tedy rzekł do mnie: Oto ten jest stół, który stoi przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'A były dwoiste drzwi u kościoła i u świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'A dwoiste drzwi we wrotach, to jest, dwoiste drzwi obracające się, dwoiste we wrotach jednych i dwoiste we wrotach drugich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'A uczyniono na nich, to jest na tych drzwiach kościelnych, Cherubiny i palmy, tak jako je było uczyniono na ścianach; belki także drewniane były przed przedsionkiem z dworu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Także na oknach pochodzistych były palmy z obu stron na bokach przysionku, także i na komorach domu onego i na belkach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'I wwiódł mię do sieni zewnętrznej drogą, która idzie ku północy, i wwiódł mię do onych komórek, które były przeciwko piętru, a które były przeciwko budowaniu na północy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Którego długość przy drzwiach na północy była na wejrzeniu na sto łokci, a szerokość na pięćdziesiąt łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Przeciwko sieni wewnętrzej, która miała dwadzieścia łokci i przeciwko tłu, które było w sieni zewnętrznej z dworu, był ganek przeciwko gankowi trzema rzędami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'A przed komórkami był plac do przechadzki na dziesięć łokci wszerz wewnątrz, ścieszka do nich na jednym łokciu, a drzwi ich były na północy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'A komórki najwyższe były ciaśniejsze, przeto, że ganki były szersze niż one, niżeli spodnie i średnie budowania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Bo było o trzech piętrach, ale nie miało słupów, jakie słupy były w sieniach; przetoż wąższe było niż spodnie i niż średnie od ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Ogrodzenia też, które było z dworu przeciwko onym komorom ku sieni zewnętrznej przed komórkami, długość była na pięćdziesiąt łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Bo długość komórek, które były w sieni zewnętrzej, była na pięćdziesiąt łokci, a przed kościołem sto łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'A pod temi komórkami było wejście od wschodu słońca, przez które wchodzono do nich z onej sieni zewnętrznej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Na szerokości ogrodzenia onej sieni ku wschodowi przed piętrem i przed budowaniem były komórki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'A ścieszka przed niemi była podobna ścieszce onych komórek, które były na północy; a jako była długość ich, taka też była szerokość ich, a wszystkie wyjścia ich i drzwi ich były im podobne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'A drzwi onych komórek, które były na południe, podobne były drzwiom na początku drogi, drogi, mówię, przed ogrodzeniem prosto na wschód słońca, kędy się wchodzi do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Tedy rzekł do mnie: Komórki na północy, i komórki na południe, które są przed piętrem, są komórki święte, gdzie będą jadali kapłani, którzy przystępują do Pana, przynosząc rzeczy najświętsze; tam kłaść będą rzeczy najświętsze, i ofiary śniedne, i ofiary za grzech, i za występek; bo to miejsce święte jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Tam gdy wnijdą kapłani, nie wynijdą z świątnicy do sieni zewnętrznej, ale tam zostawią odzienia swoje, w których służyli (bo święte jest) a obloką się w insze szaty, gdy będą mieli przystąpić do tego, co należy ludowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'A gdy odprawił wymiar domu wewnętrznego, wywiódł mię drogą ku bramie, która idzie ku wschodowi, i wymierzył go wszędy w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Wymierzył stronę od wschodu słońca laską pomiaru na pięćset lasek laski pomiarowej w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Wymierzył też stronę północną na pięćset lasek laską pomiaru w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Także stronę od południa wymierzył na pięćset laską pomiaru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'A obróciwszy się ku stronie zachodniej, wymierzył ją na pięćset lasek laską pomiaru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Na cztery strony wymierzył to, to jest mur zewsząd w około, długość na pięćset, a szerokość także na pięćset lasek, aby się dzieliło święte miejsce od pospolitego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Wiódł mię potem ku bramie, która brama patrzyła ku drodze na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'A oto chwała Boga Izraelskiego przychodziła drogą od wschodu, a szum jej był jako szum wód wielkich, a ziemia się lśniła od chwały jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'A podobne było ono widzenie, którem widział, cale onemu widzeniu, którem widział, gdym przychodził, abym psuł miasto; widzenie, mówię, podobne onemu widzeniu, którem widział u rzeki Chebar, i upadłem na twarz moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'A gdy chwała Pańska wchodziła do domu drogą bramy, która patrzała ku drodze na wschód słońca,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Tedy mię podniósł duch, i wwiódł mię do sieni wewnętrznej, a oto dom pełen był chwały Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'I usłyszałem, a oto mówiono do mnie z domu, a on mąż stał podle mnie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'I mówił do mnie: Synu człowieczy! miejsce stolicy mojej, i miejsce stóp nóg moich, na którem mieszkać będę w pośród synów Izraelskich na wieki; nie splugawi więcej dom Izraelski imienia świętobliwości mojej, ani oni, ani królowie ich w szeteczeńs twy swemi i trupami królów swych, ani wyżynami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Gdy kładli próg swój podle progu mego, a podwoje swoje podle podwoi moich, a ścianę między mną i między sobą; a tak splugawiali imię świętobliwości mojej obrzydliwościami swemi, które czynili, przetożem ich zniszczył w popędliwości mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Ale teraz niech odrzucą wszeteczeństwo swoje, i trupy królów swoich odemnie, a będę mieszkał w pośrodku ich na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Ty, synu człowieczy! powiedz domowi Izraelskiemu o tym domu, a niech się wstydzą za nieprawości swoje, i niech sobie rozmierzą wizerunek jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'A jeźliby się zawstydzili za wszystko, co czynili, tydy im oznajmij wizerunek domu tego, i wymiar jego, wyjście jego, i wejście jego, i wszystkie kształty jego, i wszystkie ustawy jego, wszystkie, mówię, kształty, i wszystkie prawa jego, a napisz przed oczyma ich, aby przestrzegali wszystkiego kształtu jego, i wszystkich ustaw jego, i czynili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'A tenci jest zakon domu tego: Na wierzchu góry wszystko ogrodzenie jego wszędzie w około najświętsze jest; oto tenci jest zakon domu tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'A teć są pomiary ołtarza według tychże łokci, a miara łokcia na łokieć i na dłoń; podstawek jego na łokieć wzwyż, a wszerz także na łokieć, a kraniec jego aż do kraju jego w około był na piędź jedną; a tać była wystawa ołtarza;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'To jest od podstawku, który był przy ziemi, aż do przepasania niższego, dwa łokcie, a szerokość na jeden łokieć; a od mniejszego przepasania aż do przepasania większego cztery łokcie, a szerokość na łokieć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Ale sam ołtarz niech będzie na cztery łokcie, a z ołtarza w górę cztery rogi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'A ołtarz na dwanaście łokci wdłuż, a na dwanaście wszerz czworograniasty po czterech stronach swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'A przepasanie jego na czternaście łokci wdłuż, a na czternaście wszerz, po czterech stronach jego, a kraniec około niego na pół łokcia, a podstawek jego na łokieć w około, a wschód jego na wschód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'I rzekł do mnie: Synu człowieczy! tak mówi panujący Pan: Teć są ustawy około ołtarza w dzień, w który zbudowany będzie, aby na nim ofiarowano całopalenia, i krwią na nim kropiono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'A kapłanom Lewitom, którzy są z nasienia Sadokowego, a przystępują do mnie, mówi panujący Pan, aby mi służyli, dasz cielca młodego na ofiarę za grzech;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Weźmiesz tedy ze krwi jego, a włożysz na cztery rogi jego, i na cztery węgły przepasania, i na kraniec w około; a tak go oczyścisz, i poświęcisz go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Potem weźmiesz onego cielca za grzech, a spalisz go na miejscu postanowionem w onym domu zewnątrz przed świątnicą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'A wtórego dnia będziesz ofiarował kozła z kóz bez wady za grzech, i oczyszczą ołtarz, tak jako go cielcem oczyścili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'A gdy dokończysz oczyszczania, będziesz ofiarował cielca młodego bez wady, i barana z trzody bez wady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Które gdy ofiarować będziesz przed Panem, wrzucą kapłani na nie soli, i uczynią z nich ofiarę całopalenia Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Przez siedm dni będziesz ofiarował kozła za grzech na każdy dzień, także i cielca młodego, i barana z trzody bez wady ofiarować będą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Przez siedm dni oczyszczać będą ołtarz, i oczyszczą go, a poświęcą ręce swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'A wypełniwszy te dni, ósmego dnia napotem sprawować będą kapłani na ołtarzu całopalenia wasze, i spokojne ofiary wasze, i przyjmę was łaskawie, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Tedy mię zaś przywiódł drogą ku bramie świątnicy zewnętrznej, która patrzy na wschód słońca, a ta była zamkniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'I rzekł do mnie Pan: Ta brama zamkniona będzie, nie będzie otworzona, a żaden nie wnijdzie przez nią; bo Pan, Bóg Izraelski, przeszedł przez nią, przetoż będzie zamkniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Książęca jest; książę sam będzie siadał w niej, aby jadł chleb przed obliczem Pańskiem; drogą przysionku tej bramy wchodzić, a drogą jej wychodzić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'I przywiódł mię drogą bramy północnej ku przedniej stronie domu; i ujrzałem, a oto napełniła chwała Pańska dom Pański, i upadłem na oblicze swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'A Pan rzekł do mnie: Synu człowieczy! uważaj to, a obacz oczyma twemi, i uszyma twemi słuchaj wszystkiego, co Ja mówię tobie o wszystkich ustawach domu Pańskiego, i o wszystkich prawach jego; uważaj, mówię, abyś obaczył wejście w dom, i wszystkie wyjścia z świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'A rzecz odpornemu domowi Izraelskiemu: Tak mówi panujący Pan: Dosyć miejcie na wszystkich obrzydliwościach waszych, o domie Izraelski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Żeście tu przywodzili cudzoziemców nieobrzezanych na sercu, i nie obrzezanych na ciele, żeby bywali w świątnicy mojej a splugawili dom mój; wyście też ofiarowali chleb mój, tłustość, i krew, gdy oni łamali przymierze moje mimo wszystkie obrzydliwośc i wasze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'A nie trzymaliście straży nad świętymi rzeczami mojemi, aleście postawili stróżów na straży mojej w świątnicy mojej miasto siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Tak mówi panujący Pan: Żaden cudzoziemiec nieobrzezany na sercu i nieobrzezany na ciele nie wnijdzie do świątnicy mojej ze wszystkich cudzoziemców, którzy są między synami Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Także i Lewitowie, którzy się oddalali odemnie, gdy błądził Izrael, którzy się obłądzili odemnie za plugawemi bałwanami swemi, ci poniosą nieprawość swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Bo będą w świątnicy mojej za sług w powinnościach przy bramach domu, i za sług przy domu; onić będą bić ofiary na całopalenie, i ofiary za lud, i oni stać będą przed obliczem ich, aby im służyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Dlatego, że im służyli przed plugawemi bałwanami ich, a byli domowi Izraelskiemi przyczyną upadku w nieprwość, przetożem podniósł rękę moję dla nich, mówi panujący Pan, że poniosą nieprawość swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'A nie przystąpią do mnie, aby mi sprawowali urząd kapłański, ani przystąpią do jakich świętych rzeczy moich, albo do najświętszych, ale poniosą pohańbienie swoje i obrzydliwości swoje, które czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Przetoż ich postanowię za stróżów obrzędów domu na każdą posługę jego, i na wszystko, co w nim będzie sprawowane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Lecz kapłani z Lewitów, synowie Sadokowi, którzy trzymali straż nad świątnicą moją, gdy się obłądzili synowie Izraelscy odemnie, ci przstąpią do mnie, aby mi służyli, i staną przed twarzą moją, aby mi ofiarowali tłustość i krew, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Ci wchodzić będą do świątnicy mojej, ci też przystąpią do stołu mego, aby mi służyli i straż moję trzymali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'A gdy będą mieli wchodzić do bramy sieni wewnętrznej, tedy się obleką w szaty lniane, a nie wezmą na się nic wełnianego, gdy służyć będą w bramach sieni wnętrznej, i wewnątrz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Czapki lniane będą mieli na głowie swojej, i ubiory płócienne będą na biodrach ich, a nie będą się przepasywać niczem, coby pot czyniło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'A gdy wychodzić będą do sieni zewnętrznej, do sieni mówię zewnętrznej do ludu, zewleką szaty swe, w których służyli, a położą je w komorach świątnicy, i obloką się w inne szaty, a nie będą poświęcali ludu szatami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Głowy też swojej nie będą golić, ani włosów zapuszczać, ale je równo przystrzygać będą na głowach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Wina też nie będzie pił żaden kapłan, gdy będzie miał wchodzić do sieni wnętrznej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Wdowy też i porzuconej nie będą sobie pojmować za żony; ale panny z nasienia domu Izraelskiego, albo wdowę, któraby pozostała wdową po kapłanie; pojmować będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'A ludu mego uczyć będą różności między rzeczą świętą i nieświętą, także między nieczystem i czystem niech ich uczą różności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'A gdy będzie jaki spór, oni się niech stawią do rozsądzania, a według sądów moich rozsądzą go; praw też moich i ustaw moich we wszystkie uroczyste święta moje strzedz będą, a sabaty moje święcić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Do umarłego też człowieka nie wnijdzie kapłan, aby się nie zmazał; chyba do ojca i do matki; i do syna, i do córki, i do brata, i do siostry, któraby jeszcze nie była za mężem; przy tych może się zmazać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'A po oczyszczeniu jego, (siedm dni naliczą mu.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'W ten dzień, którego wnijdzie do świątnicy, do sieni wewnętrznej, aby służył w świątnicy, uczyni ofiarę za grzech swój, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'A miasto dziedzictwa ich Jam jest dziedzictwem ich; przetoż osiadłości nie dawajcie im w Izraelu, Jam jest osiadłością ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Ofiarę śniedną i ofiarę za grzech i za występek, to oni jeść będą; także wszelka rzecz ofiarowana Bogu w Izraelu ich będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Także też najprzedniejsze rzeczy wszystkich pierwocin ze wszystkiego, i każda ofiara podnoszenia wszystkich rzeczy ze wszystkich ofiar waszych kapłańska będzie; pierwiastki też ciast waszych dacie kapłanowi, aby włożył błogosławieństwo na dom twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Żadnego ścierwu, i rozszarpanego od zwierza ani z ptastwa ani z bydląt kapłani jeść nie będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'A gdy podzielicie losem tę ziemię w dziedzictwo, oddacie za ofiarę Panu dział święty z tej ziemi, wdłuż na dwadzieścia i pięć tysięcy łokci, a wszerz na dziesięć tysięcy; ten dział będzie święty po wszystkich granicach swoich w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Z niego będzie miejsce święte na pięć set wdłuż, i na pięć set wszerz, czworograniaste w około; a niech ma pięćdziesiąt łokci wolnego placu w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Z tegoż wymiaru odmierzysz wdłuż dwadzieścia i pięć tysięcy łokci, a wszerz dziesięć tysięcy łokci, aby na nim była świątnica, i świątnica najświętsza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Ten dział ziemi święty jest; kapłanom, sługom świątnicy, należeć będzie, którzy przystępują, aby służyli Panu, aby mieli miejsce dla domów, i miejsce święte dla świątnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'A tych dwadzieścia i pięć tysięcy łokci wdłuż, a dziesięć tysięcy wszerz niech będzie także Lewitom, którzy służą w domu onym, w dzierżawę po dwadzieścia komórek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'A na osadzenie miasta dacie pięć tysięcy łokci wszerz, a wdłuż dwadzieścia i pięć tysięcy przeciwko ofierze miejsca świętego; a to będzie dla wszystkiego domu Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'A książęciu dacie z obu stron tej ofiary miejsca świętego, i położenia miasta przed ofiarą miejsca świętego, i przed położeniem miasta od strony zachodniej dział ku zachodowi, a od strony wschodniej dział ku wschodowi, a długość naprzeciwko każdem u z tych działów od granicy zachodniej aż do granicy wschodniej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Ten dział ziemi będzie mu za osiadłość w Izraelu, a nie będą więcej uciskali książęta moi ludu mego; ale wydzielą ziemię domowi Izraelskiemu według pokolenia ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Tak mówi panujący Pan: Dosyć miejsca na tem, o książęta Izraelscy! Gwałtu i łupiestwa zaniechajcie, sąd i sprawiedliwość czyńcie, a odejmijcie obciążenia wasze od ludu mego, mówi panujący Pan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Wagę sprawiedliwą i Efa sprawiedliwe, i Bat sprawiedliwy mieć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Efa i Bat pod jedną miarą niech będą, aby Bat brał w się dziesiątą część Chomeru, także Efa dziesiątą część Chomeru; według Chomeru jednaka obojga miara będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'A sykiel niech ma dwadzieścia pieniędzy a dwadzieścia syklów, dwadzieścia pięć syklów, a piętnaście syklów grzywną wam będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'A tak będzie ofiara podnoszenia, którą ofiarować będziecie szóstą część Efy z Chomeru pszenicy, także szóstą część Efy dacie z Chomeru jęczmienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Ustawa zaś około oliwy ta jest: Bat jest miara oliwy; dziesiątą część Batu dacie z miary Chomeru, dziesięciu Batów; bo dziesięć Batów jest Chomer.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Owcę też jednę z trzody dwóch set z obfitych pastwisk Izraelskich na ofiarę śniedną, i na całopalenie, i na ofiary spokojne ku oczyszczeniu was, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Wszystek lud tej ziemi obowiązany będzie do tej ofiary podnoszenia i z książęciem w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Bo książę będzie powinien dawać całopalenia, i śniedne i mokre ofiary na święta, i na nowie miesięcy, i na sabaty, i na wszystkie święta uroczyste domu Izraelskiego; on sprawować będzie ofiarę za grzech, i śniedną i paloną ofiarę, i ofiary spokoj ne na oczyszczenie za dom Iazraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Tak mówi panujący Pan: Pierwszego dnia pierwszego miesiąca weźmiesz młodego cielca bez wady, a oczyścisz świątnicę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Weźmie też kapłan ze krwi ofiary za grzech, i pomaże podwoje domu, i cztery węgły onego przepasania na ołtarzu, i podwoje bramy sieni wnętrznej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Także też uczyni siódmego dnia tegoż miesiąca za każdego, który z omyłki i z prostoty zgrzeszył; tak oczyścicie dom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Pierwszego miesiąca, czternastego dnia tegoż miesiąca, będziecie mieć święto przejścia, święto siedm dni, których chleby przaśne jedzone będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'I będzie książę ofiarował dnia onego za się, i za wszystek lud onej ziemi cielca na ofiarę za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'A przez siedm dni onego święta uroczystego ofiarować będzie całopalenie Panu, siedm cielców i siedm baranów bez wady na każdy dzień, przez siedm dni, a na ofiarę za grzech kozła z kóz na każdy dzień;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'A ofiarę śniedną Efy przy cielcu, i Efę przy baranie, także oliwy hyn przy Efie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Siódmego miesiąca, dnia piętnastego tegoż miesiąca w święto także właśnie ofiarować będzie przez siedm dni, jako ofiarę za grzech, tak całopalenie, tak i ofiarę śniedną i oliwę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Tak mówi panujący Pan: Brama sieni wnętrznej, która patrzy na wschód słońca, zamkniona będzie przez sześć dni robotnych; ale będzie otworzona w dzień sabatu, także i w dzień nowiu miesiąca będzie otworzona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'I przyjdzie książę drogą przysionku bramy zewnątrz, a stanie u podwoi onej bramy, a kapłani sprawować będą całopalenie jego, i spokojne ofiary jego, a pokłoniwszy się na progu bramy, potem wynijdzie, a brama nie będzie zamkniona aż do wieczora,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Aby się kłaniał lud onej ziemi u drzwi bramy we dni sabatu i na nowiu miesiąca przed obliczem Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Ale całopalenie, które będzie książę sprawował Panu w dzień sabatu, będzie sześć baranków zupełnych i baran zupełny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'I ofiara śniedna, efa na barana, i na baranki ofiara śniedna według przemożenia ręki jego, a oliwy hyn na efa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'A na dzień nowiu miesiąca niech będzie cielec młody zupełny, i sześć baranków i baran zupełny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Także niech ofiaruje efa ofiary suchej przy cielcu, i efa przy baranie, a przy barankach według przemożenia ręki swojej, a oliwy hyn na efa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'A książę wchodząc drogą przysionku i bramy pójdzie, i drogą jej odejdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Ale gdy będzie lud onej ziemi wchodził przed obliczność Pańską na święta uroczyste, tedy ten, co wnijdzie drogą bramy od północy, aby się kłaniał, wynijdzie drogą bramy południowej; a kto wnijdzie drogą bramy południowej, wynijdzie drogą bramy pół nocnej; nie wróci się drogą onej bramy, którą wszedł, ale przeciwko niej wynijdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'A gdy oni wchodzić będą, książę między nimi wchodzić będzie; a gdy odchodzić będą, odejdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Także na święta i na uroczyste święta niech będzie ofiara śniedna efa na cielca, i efa na barana, a na baranki, co przemoże ręka jego, a oliwy hyn na efa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'A będzieli książę ofiarował ofiarę dobrowolną, całopalenie albo spokojne dobrowolne ofiary Panu, tedy mu niech będzie otworzona brama, która patrzy na wschód słońca, a niech sprawuje całopalenie swoje albo spokojne ofiary swoje, jako ofiarę w dzień sabatu; potem odejdzie, i zamkną bramę, gdy wynijdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Nadto baranka rocznego zupełnego Panu ofiarować będzie co dzień na całopalenie; na każdy poranek baranka ofiarować będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Także ofiarę śniedną będzie ofiarował przy nim na każdy poranek szóstą część efy, a oliwy trzecią część hynu na skropienie pszennej mąki, śniedną mówię ofiarę Panu postanowieniem wiecznem ustwicznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Tak tedy ofiarować będą baranka i ofiarę śniedną i oliwę na każdy poranek, całopalenie ustwiczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Tak mówi panujący Pan: Jeźli komu da książe dar z synów swoich, póki dziedzictwem jego jest, synów jego niech będzie ku osiadłości i ku dziedzicwu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Ale jeźli da dar z dziedzictwa swego któremu z sług swoich, tedy będzie jego aż do roku wolności, a potem wróci się na onego księcia; a wszakże dziedzictwo jego mieć będą synowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Nie będzie też nic brał książę z dziedzictwa ludu, gwałtem ich wyrzucając z osiadłości ich; ale z osiadłości swojej da dziedzictwo synom swoim, żeby nie był rozproszony lud mój, nikt z osiadłości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Tedy mię wwiódł przez wejście, które jest przy stronie bramy, do kapłanów, do komórek świętych, które patrzyły na północy, a oto tu było miejsce po obu stronach ku zachodowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'I rzekł do mnie: To jest miejsce, gdzie warzą kapłani ofiarę za występek i za grzech, i smażą ofiarę śniednią, aby nic nie wynosili do sieni zewnętrznej ku poświęcaniu ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Potem mię wywiódł do sieni zewnętrznej, i obwiódł mię po czterech kątach sieni, a oto sień była w każdym kącie onej sieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'Na czterech węgłach onej sieni były sieni z kominami na czterdzieści łokci wdłuż a na trzydzieści łokci wszerz, jednaż miara onych czterech sieni narożnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'A w onych czterech były kuchnie w około, także ogniska poczynione w onych kuchniach w około.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'I rzekł mi: Te miejsca są tych, którzy warzą, gdzie słudzy domu warzą ofiary ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Potem mię przywiódł ku drzwiom domu, a oto wody wychodziły z pod progu domu na wschód słońca; bo przednia strona domu była na wschód słońca, a wody one schodziły spodkiem po prawej stronie domu po stronie południowej ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Stamtąd mię wywiódł drogą bramy północnej, i obwiódł mię drogą zewnętrzną do bramy zewnętrznej, drogą, która patrzy na wschód słońca; a oto wody wynikły po prawej stronie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'A gdy wychodził on mąż na wschód słońca, w którego ręku była miara, i wymierzył tysiąc łokci, i przewiódł mię przez wodę, przez wodę aż do kostek;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Potem wymierzył drugi tysiąc, a przewiódł mię przez wodę, przez wodę aż do kolan; i zaś wymierzył trzeci tysiąc, i przewiódł mię przez wodę aż do biódr.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'A gdy zaś wymierzył tysiąc, był potok, któregom nie mógł przebrnąć; bo były wezbrały wody, wody, które trzeba było przepłynąć, potok, któregom nie mógł przebrnąć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Tedy rzekł do mnie: Widziałżeś, synu człowieczy? I wywiódł mię, i obrócił mię na brzeg onego potoku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'A gdym się obrócił, oto na brzegu onego potoku było drzewo bardzo wielkie po obu stronach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'I rzekł do mnie: Te wody wychodzą od Galilei pierwszej, a schodzą po równinie, i wchodzą w morze; a gdy do morza wpadną, uzdrowione bywają wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'I stanie się, że każda dusza żyjąca, która się płaza, gdziekolwiek przyjdą potoki, żyć będzie, i będzie ryb bardzo wiele, przeto, że gdy przyjdą tam one wody, oczerstwieją, i żyć będą wszędy, kędykolwiek przyjdzie ten potok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Stanie się i to, że staną podle niego rybitwi od Engaddy aż do zdroju Eglaim, tam będą rozciągać sieci; ryb będzie bardzo wiele rozmaitego rodzaju, jako ryb morza wielkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Błota jego i kałuże jego nie będą uzdrowine, ale soli oddane będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'A nad potokiem wyrośnie na brzegu jego po obu stronach wszelkie drzewo owoce przynoszące, którego liść nie opada, ani owoc jego ustaje, w miesiącach swoich przynosi pierwociny; bo wody jego z świątnicy wychodzą, przetoż owoc jego jest na pokarm, a liście jego na lekarstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Tak mówi panujący Pan: Tać jest granica, w której sobie dziedzicznie przywłaszczycie ziemię według dwunastu pokoleń Izraelskich; Józefowi się dostaną dwa sznury.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Dziedzicznie, mówię, posiądziecie ją, równie jeden jako drugi, o którą podniosłem rękę moję, że ją dam ojcom waszym; i przypadnie wam ta ziemia w dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Tać jest tedy granica tej ziemi ku stronie północnej, od morza wielkiego, drogą do Hetlonu, kędy wchodzą do Sedad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Emat, Berota, Sybraim, które są między granicą Damaszku i między granicą Emat, wsi pośrednie, które są przy granicy Hawran.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'A tak będzie granica od morza Chatzar Enon, będzie granica Damaszek, a północna strona na północy, i granica Emat; a toć jest strona północna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'A strona wschodnia między Hawran i między Damaszkiem i między Galaad i między ziemią Izraelską przy Jordanie; od tej granicy przy morzu wschodniem mierzyć będziecie; a toć jest strona wschodnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'A strona południowa na południe od Tamar aż do wód poswarków w Kades, od potoku aż do morza wielkiego; a toć jest strona południwoa na południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Strona zaś zachodnia morze wielkie od granicy aż przeciwko kędy się wchodzi do Emat, tać jest strona zachodnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'A tak rozmierzycie sobie tę ziemię, według pokoleń Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'A gdy ją rozmierzycie, będzie wam w dziedzictwo, i przychodniom, którzyby mieszkali między wami, którzyby spłodzili synów między wami, bo wam będą jako tu zrodzeni między synami Izraelskimi; z wami dziedziczyć będą między pokoleniami Izraelskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'A w któremkolwiek pokoleniu przychodzień przychodniem będzie, tam mu dacie dziedzictwo jego, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'A teć są imiona pokoleń: W granicach na północną stronę podle drogi Hetlon, kędy wchodzą do Emat Chatzar Enon, ku granicy Damaszku na północną stronę podle Emat, od wschodniej strony aż na zachód osadzi się pokolenie jedno, to jest Dan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'A przy granicy Dan, od strony wschodniej aż do strony zachodniej, jedno, to jest Aser.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'A przy granicy Aser, od strony wschodniej aż do strony zachodniej, jedno, to jest Neftalim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'A przy granicy Neftalim, od strony wschodniej aż do strony zachodniej, jedno, to jest Manase.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'A przy granicy Manase, od strony wschodniej aż do strony zachodniej, jedno, to jest Efraim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'A przy granicy Efraim, od strony wschodniej aż do strony zachodniej, jedno, to jest Ruben.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'A przy granicy Rubenowej, od strony wschodniej aż do strony zachodniej, jedno, to jest Juda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'A przy granicy Judy, od strony wschodniej aż do strony zachodniej będzie ofiara, którą ofiarować będą, dwadzieścia i pięć tysięcy łokci wszerz, a wdłuż zarówno z jednym z innych działów od strony wschodniej aż do strony zachodniej, i będzie świątnica w pośrodku niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Ta ofiara, którą ofiarować macie Panu, będzie wdłuż dwadzieścia i pięć tysięcy łokci, a wszerz dziesięć tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'A tym się dostanie ta ofiara święta, to jest kapłanom, na północy dwadzieścia i pięć tysięcy łokci, a na zachód wszerz dziesięć tysięcy, a na wschód wszerz dziesięć tysięcy, a na południe wdłuż dwadzieścia i pięć tysięcy, a świątnica Pańska będzie w pośród niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'To ma być każdemu kapłanowi poświęconemu z synów Sadokowych, którzy trzymają straż moję, którzy nie błądzili, gdy błądzili synowie Izraelscy, jako błądzili inni Lewitowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'I będzie dział ich ofiarowany z ofiary onej ziemi, rzecz najświętsza, przy granicy Lewitów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'A Lewitów dział będzie na przeciwko granicy kapłańskiej dwadzieścia i pięć tysięcy łokci wdłuż, a wszerz dziesięć tysięcy; każda długość dwadzieścia i pięć tysięcy, a szerokość dziesięć tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'I nie będą go sprzedawać, ani frymarczyć, ani przynosić pierwocin ziemi, przeto że jest poświęcona Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'A pięć tysięcy łokci, które pozostaną wszerz przeciwko onym dwudziestu i pięciu tysięcy, będzie miejsce pospolite dla miasta na mieszkanie i dla przedmieścia, a miasto będzie w pośrodku niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'A teć są pomiary jego: Strona północna na cztery tysiące i na pięć set łokci, także strona południowa na cztery tysiące i na pięć set; od strony też wschodniej cztery tysiące i pięć set, a strona zachodnia na cztery tysiące i na pięć set.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'A będzie przedmieścia miejskiego na północy dwieście i pięćdziesiąt łokci; a na południe dwieście i pięćdziesiąt, także na wschód słońca dwieście i pięćdziesiąt, a na zachód słońca dwieście i pięćdziesiąt;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'A co zbędzie wdłuż przeciw ofierze świętej, dziesięć tysięcy łokci na wschód, i dziesięć tysięcy na zachód; a z tego, co będzie naprzeciw onej ofierze świętej, będą mieć dochody ku wychowaniu słudzy miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'A ci słudzy miasta służyć będą miastu ze wszystkich pokoleń Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Wszystkę tę ofiarę na dwadzieścia i pięć tysięcy łokci według tych dwudziestu i pięciu tysięcy, czworograniastą ofiarować będziecie na ofiarę świętą ku osiadłości miastu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'A to, co zostani, książęce będzie z obu stron ofiary świętej, i osiadłości mejskiej, przed onemi dwudziestu i pięciu tysiącami łokci ofiary aż ku granicy wschodniej, i od zachodu przeciwko tymże dwudziestu i pięciu tysiącom łokci, podle granicy zachodniej przciwko tym działom, książęciu będzie; a to będzie ofiara święta, a świątnica domu będzie w pośrodku niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'A od osiadłości Lewitów i od osiadłości miejskiej w pośród tego, co jest książęcego, między granicą Judową i między granicą Benijaminową, to książęce będzie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'A ostatnie pokolenia, od strony wschodniej aż do strony zachodniej osadzi się pokolenie jedno, to jest Benjamin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'A przy granicy Benjaminowej od strony wschodniej aż do strony zachodniej, jedno, to jest Symeon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'A przy granicy Symeonowej, od strony wschodniej aż do strony zachodniej, jedno, to jest Isaschar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'A przy granicy Isascharowej, od strony wschodniej aż do strony zachodniej, jedno to jest Zabulon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'A przy granicy Zabulonowej, od strony wschodniej aż do strony zachodniej, jedno, to jest Gad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'A przy granicy Gadowej, ku stronie południowej na południe, tu będzie granica od Tamar aż do wód poswarku w Kades, ku potokowi przy morzu wielkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Toć jest ona ziemia, którą losem rozdzielicie od potoku według pokoleń Izraelskich, i teć działy ich, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Teć też są granice miejskie od strony północnej cztery tysiące i pięć set łokci miary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'A bramy miasta według imion pokoleń Izraelskich; trzy bramy na północy, brama Rubenowa jedna, brama Judowa jedna, brama Lewiego jedna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'A od strony wschodniej cztery tysiące i pięć set, a bramy trzy, to jest brama Józefowa jedna, brama Benjaminowa jedna, bramam Danowa jedna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Od strony też południowej cztery tysiące i pięć set łokci miary, i trzy bramy: brama Symeonowa jedna, brama Isascharowa jedna, brama Zabulonowa jedna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Od strony zachodniej cztery tysiący i pięć set, bramy ich trzy: Brama Gadowa jedna, brama Aserowa jedna, brama Neftalimowa jedna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'W okrąg ośmnaście tysięcy łokci; a imię miasta ode dnia tego będzie: Pan tam mieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Roku trzeciego królowania Joakima, króla Judzkiego, przyciągnął Nabuchodonozor, król Babiloński, do Jeruzalemu, i obległ je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'I podał Pan w rękę jego Joakima, króla Judzkiego, i część naczynia domu Bożego, który je zawiózł do ziemi Senaar, do domu boga swego, i wniósł ono naczynie do domu skarbu boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'I rozkazał król Aspenasowi przełożonemu nad komornikami swymi, aby przyprowadził z synów Izraelskich, i z nasienia królewskiego i z książąt,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Młodzieńców, na którychby nie było żadnej zmazy, a pięknych na wejrzeniu i dowcipnych do wszelakiej mądrości, i sposobnych do umiejętności, i dostąpienia jej, i którzyby byli sposobni, aby stali w pałacu królewskim, a uczyli się pisma i języka chaldejskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'I postanowił im król obrok na każdy dzień z potraw swoich królewskich i z wina, które on sam pijał, a żeby ich tak chował przez trzy lata, a po wyjściu ich żeby stawali przed obliczem królewskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'A byli między nimi z synów Judzkich: Danijel, Ananijasz, Misael, i Azaryjasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'I dał im przełożony nad komornikami imiona, a Danijela nazwał Baltazarem, a Ananijasza Sadrachem, a Misaela Mesachem, a Azaryjasza Abednegiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Ale Danijel postanowił w sercu swojem, żeby się nie mazał pokarmem potraw królewskich, ani winem, które król pijał; przetoż tego szukał u przełożonego nad komornikami, żeby się nie zmazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'I zjednał Bóg Danijelowi łaskę i miłość przed obliczem przełożonego nad komornikami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'I rzekł przełożony nad komornikami do Danijela: Ja się boję króla, pana mego, który wam postanowił pokarm wasz i napój wasz: który jeźliby obaczył, że twarzy wasze chudsze są niż innych młodzieńców, którzy jednako z wami mają być wychowani, tedy mię przyprawicie o gardło u króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'I rzekł Danijel do sługi, którego był postanowił przełożony nad komornikami nad Danijelem, Ananijaszem, Misaelem i Azaryjaszem:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Doświadcz proszę sług twoich przez dziesięć dni, a niech nam dadzą jarzyn, którebyśmy jedli, i wody, którąbyśmy pili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Potem przypatrzysz się twarzom naszym, i twarzom innych młodzieńców, którzy jadają pokarm z potraw królewskich, a jako obaczysz, tak uczynisz z sługami twymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'I usłuchał ich w tem, a doświadczył ich przez dziesięć dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'A po wyjściu dziesięciu dni okazało się, że twarze ich były piękniejsze, i byli tłustsi na ciele, niż wszyscy młodzieńcy, którzy jadali pokarm z potraw królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Przetoż on sługa brał on obrok potraw ich, i wino napoju ich, a dawał im jarzyny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'A onym czterem młodzieńcom dał Bóg umiejętność i rozum we wszelakiem piśmie i mądrości; nadto Danijelowi dał wyrozumienie wszelakiego widzenia i snów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'A gdy wyszły dni, po których ich król przyprowadzić rozkazał, przywiódł ich przełożony nad komornikami przed twarz Nabuchodonozora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'I mówił z nimi król; ale nie był znaleziony między onymi wszystkimi, jako Danijel, Ananijasz, Misael i Azaryjasz; i stawali przed obliczem królewskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'A w każdem słowie mądrości i rozumu, o które się ich król pytał, znalazł ich dziesięć kroć bieglejszych nad wszystkich mędrców i praktykarzy, którzy byli we wszystkiem królewstwie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'I był tam Danijel aż do roku pierwszego króla Cyrusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Roku wtórego królowania Nabuchodonozora miał Nabuchodonozor sen, i strwożył się duch jego, i przerwał mu się sen jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Tedy król rozkazał zwołać mędrców, i praktykarzy, i czarnoksiężników, i Chaldejczyków, aby oznajmili królowi sen jego; którzy przyszli i stanęli przed obliczem królewskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'I rzekł król do nich: Miałem sen, i strwożył się duch mój, tak, że nie wiem, co mi się śniło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Tedy odpowiedzieli Chaldejczycy królowi po syryjsku: Królu, żyj na wieki! Powiedz sen sługom twoim, a oznajmiemyć wykład jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Odpowiedział król i rzekł do Chaldejczyków: Ta rzecz już mi z pamięci wypadła; jeźli mi nie oznajmicie snu i wykładu jego, na sztuki rozsiekani będziecie, a domy wasze w gnojowisko obrócone będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Ale jeźli mi sen i wykład jego oznajmicie, dary i upominki i uczciwość wielką odniesiecie odemnie; przetoż sen i wykład jego oznajmijcie mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Odpowiedzieli powtóre, i rzekli: Król niech powie sen sługom swoim, a wykład jego oznajmiemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Odpowiedział król, i rzekł: Zaiste wiem, że umyślnie odwłaczacie, bacząc, że mi ten sen z pamięci wyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Jeźliże mi snu nie oznajmicie, pewny jest o was dekret, boście rzecz kłamliwą i przewrotną umyślili mówić przedemną, ażby czas przeminął; przetoż mi sen powiedzcie, a dowiem się, będziecieli mogli wykład jego oznajmić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Odpowiedzieli Chaldejczycy królowi, i rzekli: Niemasz człowieka na ziemi, któryby tę rzecz królowi oznajmić mógł; dotego żaden król, książę albo pan o taką się rzecz nie pytał żadnego mędrca, i praktykarza, i Chaldejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Bo rzecz, o którą się król pyta, trudna jest, a niemasz nikogo, coby ją mógł królowi oznajmić, oprócz bogów, którzy nie mieszkają z ludźmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Z tej przyczyny zasrożył się król, i rozgniewał się bardzo, a rozkazał wytracić wszystkich mędrców Babilońskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'A gdy wyszedł dekret, aby mordowano mędrców, szukano i Danijela i towarzyszów jego, aby ich zamordowano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'tedy Danijel odpowiedział mądrze i roztropnie Aryjochowi, hetmanowi nad żołnierzami królewskimi, który wyszedł, aby zabijał mędrców Babilońskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'A odpowiadając rzekł do Aryjocha, hetmana królewskiego: Przecz ten dekret tak prędko wyszedł od króla? I oznajmił tę rzecz Aryjoch Danijelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Skąd Danijel wszedł, i prosił króla, aby mu dał czas na oznajmienie wykładu królowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Odszedłszy tedy Danijel do domu swego, oznajmił tę rzecz Ananijaszowi, Misaelowi i Azaryjaszowi, towarzyszom swoim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Aby o miłosierdzie prosili Boga niebieskiego dla tej tajemnicy, żeby nie zginęli Danijel i towarzysze jego z pozostałymi mędrcami Babilońskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Tedy objawiona jest Danijelowi w widzeniu nocnem ta tajemnica, za co Danijel błogosławił Bogu niebieskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'A mówiąc Danijel rzekł: Niech będzie imię Boże błogosławione od wieku aż na wieki; albowiem mądrość i moc jego jest;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'On sam odmienia czasy i chwile; zrzuca królów i stanowi królów; daje mądrość mądrym, a umiejętnym rozum;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'On odkrywa rzeczy głębokie i skryte, zna, co jest w ciemnościach, a światłość z nim mieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Ciebie ja, o Boże ojców moich! wysławiam i chwalę, żeś mi dał mądrość i moc, owszem, żeś mi teraz oznajmił to, o cośmy cię prosili; boś nam sen królewski oznajmił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Dla tego Danijel wszedł do Aryjocha, którego był postanowił król, aby wytracił mędrców Babilońskich; a przyszedłszy tak rzekł do niego: Nie trać mędrców Babilońskich, wprowadź mię do króla, a ja ten wykład królowi oznajmię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Tedy Aryjoch z kwapieniem wprowadził Danijela do króla i tak mu rzekł: Znalazłem męża z więźniów synów Judzkich, który ten wykład królowi oznajmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Odpowiedział król, i rzekł Danijelowi, któremu imię było Baltazar: Izali mnie ty możesz oznajmić sen, którym widział, i wykład jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Odpowiedział Danijel królowi, i rzekł: Tajemnicy, o której się król pyta, mędrcy, praktykarze, czarnoksiężnicy i wieszczkowie królowi oznajmić nie mogą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'A wszakże jest Bóg na niebie, który objawia tajemnice, a on okazał królowi Nabuchodonozorowi, co ma być potomnych dni. Sen twój i widzenia, któreś widział na łożu twojem, te są:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Tobie o królu! przychodziło na myśl na łożu twojem, coby miało być na potem, a ten, który odkrywa tajemnice, oznajmił ci to, co ma być.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Mnie też nie przez mądrość, któraby przy mnie była nad wszystkich ludzi, tajemnica ta objawiona jest, ale przez modlitwę, aby ten wykład królowi oznajmiony był, a iżbyś się myśli serca twego dowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Tyś, królu! widział, a oto obraz jeden wielki(obraz to był wielki, a blask jego znaczny)stał przeciwko tobie, który na wejrzeniu był straszny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Tego obrazu głowa była ze złota szczerego, piersi jego i ramiona jego ze srebra, brzuch jego i biodra jego z miedzi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Golenie jego z żelaza, nogi jego częścią z żelaza, a częścią z gliny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Patrzałeś na to, aż odcięty był kamień, który nie bywał w ręku, a uderzył ten obraz w nogi jego żelazne i gliniane, i skruszył je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Tedy się skruszyło społem żelazo, glina, miedź, srebro i złoto, a było to wszystko jako plewy na bojewisku w lecie, i rozniósł to wiatr, tak, że ich na żadnem miejscu nie znaleziono; a kamień on, który uderzył o obraz, stał się górą wielką i napełnił wszystkę ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Tenci jest sen. Wykład też jego powiemy przed królem:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Tyś, królu! królem królów; bo tobie Bóg niebieski królestwo, moc, potęgę i sławę dał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'I wszystko, gdzie jedno mieszkają synowie ludzcy, zwierz polny i ptastwo niebieskie, dał w rękę twoję i postanowił cię panem nad tem wszystkiem, a tyś jest tą głową złotą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Ale po tobie powstanie królestwo insze, podlejsze niżeli twoje, a inne królestwo trzecie miedziane, które panować będzie po wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'A królestwo czwarte będzie mocne jako żelazo; bo jako żelazo łamie i kruszy wszystko, jako żelazo, mówię, kruszy wszystko, tak i ono połamie i pokruszy wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'A iżeś widział nogi, i palce częścią z gliny garncarskiej a częścią z żelaza, królestwo rozdzielone znaczy, w którem będzie nieco mocy żelaznej, tak jakoś widział żelazo zmięszane z skorupą glinianą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Ale palce nóg częścią z żelaza a częścią z gliny znaczą królestwo częścią mocne a częścią do skruszenia snadne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'A iżeś widział żelazo zmięszane z skorupą glinianą, znaczy, że się spokrewnią z sobą ludzie; a wszakże nie będzie się trzymał jeden drugiego, tak jako żelazo nie może się zmięszać z gliną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Ale za dni tych królów wzbudzi Bóg niebieski królestwo, które na wieki zepsute nie będzie, a królestwo to na inszy naród nie spadnie, ale ono połamie, i koniec uczyni tym wszystkim królestwom, a samo stać będzie na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Tak jakoś widział, iż z góry odcięty był kamień, który nie bywał w ręku, a skruszył żelazo, miedź, glinę, srebro i złoto, przez to Bóg wielki królowi oznajmił, co ma być na potem; i prawdziwy jest ten sen, i wierny wykład jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Tedy król Nabuchodonozor padł na oblicze swoje, i ukłonił się Danijelowi, a rozkazał, aby mu ofiarę i kadzenia ofiarowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Tedy odpowiadając król Danijelowi rzekł: Zaprawdę Bóg wasz jest Bogiem bogów, a Panem królów, który odkrywa tajemnice, ponieważeś mógł objawić tę tajemnicę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Zatem król zacnie wywyższył Danijela, i darów wielkich i wiele dał mu, i uczynił go panem nad wszystką krainą Babilońską, i książęciem nad przełożonymi i nad wszystkimi mędrcami Babilońskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Ale Danijel prosił króla, aby przełożył nad sprawami krainy Babilońskiej Sadracha, Mesacha i Abednego; a Danijel bywał w bramie królewskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Nabuchodonozor król uczynił obraz złoty, którego wysokość była na sześćdziesiąt łokci, a szerokość jego na sześć łokci, i postawił go na polu Dura w krainie Babilońskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Tedy król Nabuchodonozor posłał, aby zebrano książąt, starostów i hetmanów, starszych, poborców, w prawach biegłych, urzędników, i wszystkich przełożonych nad krainami, aby przyszli na poświęcenie obrazu, który był wystawił król Nabuchodonozor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Tedy się zgromadzili książęta, starostowie i hetmani, starsi, poborcy, w prawach biegli, urzędnicy, i wszyscy przełożeni nad krainami ku poświęcaniu obrazu, który był wystawił Nabuchodonozor król, i stanęli przed obrazem, który był wystawił Nabuch odonozor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'A woźny wołał wielkim głosem: Wam się opowiada, ludziom, narodom, i językom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Skoro usłyszycie głos trąby, piszczałki, lutni, skrzypiec, harfy, symfonału, i wszelakiego instrumentu muzyki, upadnijcie a kłaniajcie się obrazowi złotemu, który wystawił król Nabuchodonozor;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'A ktoby nie upadł i nie pokłonił się, tejże godziny wrzucony będzie w pośród pieca ogniem pałającego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Zaraz tedy, skoro usłyszeli wszyscy ludzie głos trąby, piszczałki, lutni, skrzypiec, harfy i wszelakiego instrumentu muzyki, upadli wszyscy ludzie, narody i języki, kłaniając się obrazowi złotemu, który wystawił król Nabuchodonozor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Przetoż tego czasu przystąpiwszy mężowie Chaldejscy skargę uczynili przeciwko Żydom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'A mówiąc rzekli do króla Nabuchodonozora: Królu, żyj na wieki!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Ty, królu! uczyniłeś dekret, żeby każdy człowiek, któryby usłyszał głos trąby, piszczałki, lutni, skrzypiec, harfy, i symfonału i wszelakiego instrumentu muzyki, upadł i pokłonił się obrazowi złotemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'A ktobykolwiek nie upadł i nie pokłonił się, aby był wrzucony w pośrodek pieca ogniem pałającego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Wszakże się znaleźli niektórzy Żydowie, którycheś przełożył nad sprawami krainy Babilońskiej, Sadrach, Mesach i Abednego; ci mężowie lekce poważyli, o królu! dekret twój, bogów twoich nie chwalą, i obrazowi się złotemu, któryś wystawił, nie kłaniają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Tedy Nabuchodonozor w popędliwości i w gniewie rozkazał przyprowadzić Sadracha, Mesacha i Abednego, których wnet przywiedziono przed króla.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'I mówił Nabuchodonozor a rzekł im: Umyślnież wy, Sadrachu, Mesachu, i Abednego, bogów moich nie czcicie, i obrazowi się złotemu, którym wystawił, nie kłaniacie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Teraz tedy wy bądźcie gotowi, abyście zaraz, skoro usłyszycie głos trąby, piszczałki, lutni, skrzypiec, harfy i symfonału i wszelakiego instrumentu muzyki, upadli, i pokłonili się temu obrazowi, którym uczynił; a oto jeźli się nie pokłonicie, tej że godziny będziecie wrzuceni w pośród pieca ogniem pałającego; a któryż jest ten Bóg, coby was wyrwał z ręki mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Odpowiedzieli Sadrach, Mesach i Abednego, i rzekli do króla: O Nabuchodonozorze! my się nie frasujemy o to, cobyśmy mieli odpowiedzieć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Bo oto lubo Bóg nasz, którego my chwalimy, (który mocen jest wyrwać nas z pieca ogniem pałającego, i z ręki twojej, o królu!) wyrwie nas,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Lubo nie wyrwie, niech ci będzie wiadomo, o królu! że bogów twoich chwalić, i obrazowi złotemu, któryś wystawił, kłaniać się nie będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Tedy Nabuchodonozor pełen będąc popędliwości, tak, że się kształt twarzy jego odmienił przeciw Sadrachowi, Mesachowi i Abednegowi, odpowiadając rozkazał piec rozpalić siedm kroć bardziej, niżeli był zwyczaj rozpalać go,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'A mężom co mocniejszym, którzy byli w wojsku jego, rozkazał, aby związawszy Sadracha, Mesacha i Abednega, wrzucili do pieca ogniem pałającego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Tedy onych mężów związano w płaszczach ich, w ubraniach ich i w czapkach ich i w szatach ich, a wrzucono ich w pośrodek pieca ogniem pałającego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'A iż rozkazanie królewskie przynaglało, a piec bardzo był rozpalony, dlatego onych mężów, którzy wrzucili Sadracha, Mesacha i Abednega, zadusił płomień ogniowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Ale ci trzej mężowie, Sadrach, Mesach i Abednego, wpadli w pośród pieca ogniem pałającego związani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Tedy król Nabuchodonozor zdumiał się i powstał prędko, a mówiąc rzekł hetmanom swoim: Izaliśmy nie trzech mężów związanych wrzucili w pośród ognia? którzy odpowiadając rzekli królowi: Prawda, królu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'A on odpowiadając rzekł: Oto Ja widzę czterech mężów rozwiązanych przechodzących się w pośrodku ognia, a niemasz żadnego naruszenia przy nich, a osoba czwartego podobna jest Synowi Bożemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Tedy przystąpiwszy Nabuchodonozor do czeluści pieca ogniem pałającego, rzekł mówiąc: Sadrachu, Mesachu i Abednegu, słudzy Boga najwyższego! wynijdźcie, a przyjdźcie sam; i wyszli Sadrach, Mesach i Abednego z pośrodku ognia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'A zgromadziwszy się książęta, starostowie urzędnicy i hetmani królewscy oglądali onych mężów, że nie panował ogień nad ciałami ich, i włos głowy ich nie opalił się, i płaszcze ich nie naruszyły się, ani zapach ognia nie przeszedł przez nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Tedy rzekł Nabuchodonozor, mówiąc: Błogosławiony Bóg ich, to jest, Sadracha, Mesacha i Abednega, który posłał Anioła swego, a wyrwał sług swoich, którzy ufali w nim, którzy słowa królewskiego nie usłuchali, ale ciała swe wydali, aby nie służyli, a nie kłaniali się żadnemu bogu, oprócz Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Przetoż ja daję taki dekret, aby każdy ze wszelkiego ludu, narodu, i języka, ktobykolwiek bluźnierstwo wyrzekł przeciwko Bogu Sadrachowemu, Mesachowemu i Abednegowemu, był na sztuki rozsiekany, a dom jego w gnojowisko obrócony, gdyż niemasz Boga innego, któryby mógł wyrwać, jako ten.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Tedy król zacnie wywyższył Sadracha, Mesacha i Abednega w krainie Babilońskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Nabuchodonozor król, wszystkim ludziom, narodom, i językom, którzy mieszkają po wszystkiej ziemi: Pokój się wam niech rozmnoży!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Znaki i dziwy, które uczynił ze mną Bóg najwyższy, zdało mi się za rzecz przystojną opowiedzieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'O jakoż są wielkie znaki jego! a dziwy jego jako mocne! królestwo jego królestwo wieczne, i władza jego od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Ja Nabuchodonozor żyjąc w pokoju w domu moim, i kwitnąc na pałacu moim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Miałem sen, który mię przestraszył, i myśli, którem miał na łożu mojem, a widzenia, którem widział, zatrwożyły mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'A przetoż wydany jest ode mnie dekret, aby przywiedziono przed mię wszystkich mędrców Babilońskich, którzyby mi wykład snu tego oznajmili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Tedy przyszli mędrcy i praktykarze Chaldejscy, i wieszczkowie; i powiedziałem im sen, a wszakże wykładu jego nie mogli mi oznajmić;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Aż na ostatek przyszedł przed mię Danijel, którego imię Baltazar według imienia boga mego, a w którym jest duch bogów świętych, a sen powiedziałem przed nim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Mówiąc: Baltazarze, przedniejszy z mędrców! Ja wiem, iż duch bogów świętych jest w tobie, a żadna tajemnica nie jest ci trudna; widzenia snu mego, którym miał, posłuchaj, a wykład jego powiedz mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Te są widzenia, którem widział na łożu mojem: Widziałem, a oto drzewo w pośrodku ziemi, którego wysokość zbytnia była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Wielkie było ono drzewo i mocne, a wysokość jego dosięgała nieba, a okazałe było aż do granic wszystkiej ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Gałęzie jego piękne, a owoc jego obfity, i pokarm dla wszystkich był na niem; pod sobą dawało cień zwierzowi polnemu, a na gałęziach jego mieszkało ptastwo niebieskie, a z niego miało pożywienie wszelkie ciało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Widziałem nadto w widzeniach moich na łożu mojem, a oto stróż i Święty z nieba zstąpiwszy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Wołał ze wszystkiej mocy, i tak rzekł: Podrąbcie to drzewo, i obetnijcie gałęzie jego, a otłuczcie liście jego, i rozrzućcie owoc jego; niech się rozbieży zwierz, który jest pod niem, i ptastwo z gałęzi jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Wszakże pień korzenia jego w ziemi zostawcie, a niech będzie związany łańcuchem żelaznym i miedzianym na trawie polnej, aby rosą niebieską był skrapiany, a z zwierzętami niech się pasie w trawie ziemskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Serce jego od człowieczego niech się odmieni, a serce zwierzęce niech mu dane będzie, a siedm lat niech pominą nad nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Ta rzecz według wyroku stróżów, a to żądanie według mowy świętych stanie się, aż do tego przyjdzie, że poznają ludzie, iż Najwyższy panuje nad królestwem ludzkiem, a daje je, komu chce, a najpodlejszego z ludzi stanowi nad niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Ten sen widziałem ja król Nabuchodonozor; a ty, Baltazarze! powiedz wykład jego, gdyż wszyscy mędrcy królestwa mego nie mogli mi tego wykładu oznajmić; ale ty możesz, bo duch bogów świętych jest w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Tedy Danijel, którego imię Baltazar, zdumiewał się przez jednę godzinę, a myśli jego trwożyły go. A odpowiadając król rzekł: Baltazarze! sen i wykład jego niech cię nie trwoży. Odpowiedział Baltazar, i rzekł: Panie mój! ten sen niech przyjdzie na tych, którzy cię nienawidzą, a wykład jego na nieprzyjaciół twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Drzewo, któreś widział rosłe i mocne, którego wysokość dosięgała nieba, a które okazałe było wszystkiej ziemi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Którego gałąź piękna, a owoc jego obfity, a pokarm dla wszystkich na niem, pod którem mieszkał zwierz polny, a na gałęziach jego przebywało ptastwo niebieskie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Tyś jest tym, o królu! któryś się rozwielmożył i zmocnił, a wielkość twoja urosła, i podniosła się aż do nieba, a władza twoja aż do kończyn ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'A iż król widział stróża i Świętego zstępującego z nieba a mówiącego: Podrąbcie to drzewo, a zepsujcie je, wszakże pień i z korzeniem jego w ziemi zostawcie, aby rosą niebieską był skrapiany a z zwierzętami polnemi niech się pasie, ażby się wypeł niło siedm lat nad nim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Tenci jest wykład, o królu! i ten dekret Najwyższego, który wyszedł na króla, pana mego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Bo cię wyrzucą od ludzi, a z zwierzem polnym będzie mieszkanie twoje, a trawą jako wół paść się będziesz, a rosą niebieską skrapiany będziesz, aż się wypełni siedm lat nad tobą, dokądbyś nie poznał, że Najwyższy panuje nad królestwem ludzkiem, a że je daje, komu chce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'A iż rozkazano zostawić pień i z korzeniem onego drzewa, znaczy, że królestwo twoje tobie zostanie, gdy poznasz, że niebiosa panują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Przetoż o królu! rada moja niech ci się podoba, a grzechy twoje przerwij sprawiedliwością, a nieprawości twoje miłosierdziem nad utrapionym, owa snać stanie się przedłużenie pokoju twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Wszystko to przyszło na króla Nabuchodonozora;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Bo po wyjściu dwunastu miesięcy, przechodząc się w Babilonie na pałacu królewskim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Mówił król i rzekł: Izali nie to jest on Babilon wielki, którym ja w sile mocy mojej zbudował, aby był stolicą królestwa i ku ozdobie sławy mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'A gdy jeszcze ta mowa była w ustach królewskich, oto głos z nieba przyszedł mówiąc: Tobie się mówi, królu Nabuchodonozorze! że królestwo twoje odeszło od ciebie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'I od ludzi wyrzucą cię, a z zwierzem polnym będzie mieszkanie twoje; trawą jako wół paść się będziesz, ażby się wypełniło siedm lat nad tobą, dokądbyś nie poznał, że Najwyższy panuje nad królestwem ludzkiem, a że je daje, komu chce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Tejże godziny wypełniło się ono słowo nad Nabuchodonozorem; bo go wyrzucono od ludzi, a trawę jadał jako wół, a rosą niebieską ciało jego skrapiane było, aż na nim włosy urosły jako pierze orle, a paznogcie jego jako pazury u ptaków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'A po skończeniu onych dni podniosłem ja Nabuchodonozor w niebo oczy moje, a rozum mój do mnie się zaś wrócił, i błogosławiłem Najwyższego, a Żyjącego na wieki chwaliłem i wysławiałem; bo władza jego władza wieczna, a królestwo jego od narodu do narodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'A wszyscy obywatele ziemi jako za nic poczytani są. Według woli swojej postępuje, z wojskiem niebieskiem i z obywatelami ziemi, a niemasz, ktoby wstręt uczynił ręce jego i rzekł mu: Cóż to czynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'Tegoż czasu rozum mój wrócił się do mnie, a do sławy królestwa mego ozdoba moja, i dostojność moja wróciła się do mnie; nadto hetmani moi i książęta moi szukali mię, a na królestwie mojem zmocniłem się, i wielmożność większa mi jest przydana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'A tak teraz ja Nabuchodonozor chwalę, i wywyższam i wysławiam króla niebieskiego, którego wszystkie sprawy są prawdą, a ścieszki jego sądem, a który chodzących w hardości poniżyć może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Balsazar król uczynił ucztę wielką na tysiąc książąt swoich, i przed onym tysiącem pił wino.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'A gdy pił wino Balsazar, rozkazał przynieść naczynie złote i srebrne, które był zabrał Nabuchodonozor, ojciec jego, z kościoła Jeruzalemskiego, aby pili z niego król i książęta jego, żony jego, i założnice jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Tedy przyniesiono naczynia złote, które byli zabrali z kościoła domu Bożego, który był w Jeruzalemie, i pili z nich król i książęta jego, żony jego, i założnice jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'A pijąc wino chwalili bogi złote i srebrne, miedziane, żelazne, drewniane, i kamienne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Tejże godziny wyszły palce ręki człowieczej, które pisały przeciwko świecznikowi na ścianie pałacu królewskiego, a król widział część ręki, która pisała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Tedy się jasność królewska zmieniła, a myśli jego zatrwożyły nim, i zwiąski biódr jego rozwiązały się, a kolana jego jedno o drugie się tłukły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'I zawołał król ze wszystkiej siły, aby przywiedziono praktykarzy, Chaldejczyków i wieszczków. A mówiąc król rzekł do mędrców Babilońskich: Ktokolwiek to pismo przeczyta, a wykład jego mnie oznajmi, obleczony będzie w szarłat, a łańcuch złoty dadzą na szyję jego, i trzecim w królestwie po mnie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Tedy weszli wszyscy mędrcy królewscy; ale nie mogli ani pisma przeczytać, ani wykładu jego królowi oznajmić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Skąd król Balsazar był bardzo zatrwożony, a jasność jego zmieniła się na nim, i książęta jego potrwożyli się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Tedy królowa weszła do domu uczty dla tego, co się przydało królowi i książętom jego; a przemówiwszy królowa rzekła: Królu, żyj na wieki! Niech cię nie trwożą myśli twoje, a jasność twoja niech się nie mieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Jest mąż w królestwie twojem, w którym jest duch bogów świętych, w którym się znalazło za dni ojca twego oświecenie, i rozum, i mądrość, jako mądrość bogów, którego król Nabuchodonozor, ojciec twój, przedniejszym między mędrcami, i praktykarzami Chaldejczykami, i wieszczkami, postanowił, ojciec twój mówię, o królu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Dlatego, iż duch obfity, i umiejętność, i zrozumienie, wykładanie snów, i objawienie zagadek, i rozwiązanie rzeczy trudnych znalazły się przy Danijelu, któremu król dał imię Baltazar, teraz tedy niech przyzowią Danijela, a oznajmić ten wykład.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Tedy przywiedziony jest Danijel do króla; a król mówiąc rzekł Danijelowi: Tyżeś jest on Danijel, któryś jest z synów więźniów Judzkich, którego przywiódł król, ojciec mój, z ziemi Judzkiej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Słyszałem zaiste o tobie, iż duch bogów jest w tobie, a oświecenie i rozum i mądrość obfita znalazła się w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'A teraz przywiedziono przed mię mędrców i praktykarzy, aby mi to pismo przeczytali, i wykład jego oznajmili: wszakże nie mogli wykładu tej rzeczy oznajmić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'A jam słyszał o tobie, że możesz to, co jest niepojętego, wykładać, a co jest trudnego, rozwiązywać; przetoż teraz, możeszli to pismo przeczytać a wykład jego mnie oznajmić, w szarłat obleczony będziesz, i łańcuch złoty na szyję twoję włożony będzie, a trzecim w królestwie po mnie będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Tedy odpowiedział Danijel przed królem i rzekł: Upominki twoje niech tobie zostaną, a dary twoje daj innemu; wszakże pismo przeczytam królowi, i wykład mu oznajmię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Ty, królu! słuchaj. Bóg najwyższy królestwo i wielmożność i sławę, i zacność dał Nabuchodonozorowi, ojcu twemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'A dla wielmożności, którą mu był dał, wszyscy ludzie, narody i języki drżeli i bali się przed obliczem jego; bo kogo chciał, zabijał, a kogo chciał, żywił, a kogo chciał, wywyższał, a kogo chciał, poniżał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Ale gdy się wyniosło serce jego, a duch jego zmocnił się w pysze, złożony jest z stolicy królestwa swego, a sława odjęta była od niego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'I był wyrzucony od synów ludzkich, a serce jego zwierzęcemu podobne było, i z dzikiemi osłami było mieszkanie jego; trawą się pasł jako wół, i rosą niebieską ciało jego skrapiane było, dokąd nie poznał, że Bóg najwyższy ma władzę nad królestwem ludzkiem, a tego, kogo chce, stanowi nad niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Ty, też, Balsazarze, synu jego! nie upokorzyłeś serca swego, chociażeś to wszystko wiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Owszem, przeciwko Panu nieba podniosłeś się, i naczynie domu jego przyniesiono przed cię; a ty i książęta twoi, żony twoje, i założnice twoje, piliście wino z niego; nadto bogi srebrne i złote, miedziane, żelazne, drewniane, i kamienne, którzy nie widzą, ani słyszą, i nic nie wiedzą, chwaliłeś, a Boga, w którego ręku jest tchnienie twoje, i u którego są wszystkie drogi twoje, nie uczciłeś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Przetoż teraz od niego posłana jest ta część ręki, i pismo to wyrażone jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'A toć jest pismo, które wyrażone jest: Mene, Mene, Thekel, upharsin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'A tenci jest wykład tych słów: Mene, zliczył Bóg królestwo twoje i do końca je przywiódł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Thekel, zważonyś na wadze, a znalezionyś lekki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres, rozdzielone jest królestwo twoje, a dane jest Medom i Persom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Tedy rozkazał Balsazar; i obleczono Danijela w szarłat, a łańcuch złoty włożono na szyję jego, i obwołano o nim, że ma być trzecim panem w królestwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Tejże nocy zabity jest Balsazar, król Chaldejski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'A Daryjusz, Medczyk, ujął królestwo, mając lat około sześćdziesiąt i dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'I podobało się Daryjuszowi, aby postanowił nad królestwem sto i dwadzieścia starostów, którzyby byli we wszystkiem królestwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'A nad nimi troje książąt, z których był Danijel przedniejszym, którymby oni starostowie liczbę czynili, aby król szkody nie miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'A sam Danijel przewyższał onych książąt i starszych, przeto, że duch znamienitszy był w nim, skąd go król myślał postanowić nad wszystkiem królestwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Tedy książęta i starostowie szukali, aby znaleźli przyczynę przeciwko Danijelowi z strony królestwa; wszakże żadnej przyczyny ani wady znaleść nie mogli, ponieważ on był wiernym, ani żadna wina ani wada nie znajdowała się w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Przetoż rzekli oni mężowie: Nie znajdziemy przeciwko temu Danijelowi żadnej przyczyny, chyba żebyśmy co znaleźli przeciwko niemu w zakonie Boga jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Tedy oni książęta i starostowie zgromadzili się do króla, i tak mu rzekli: Daryjuszu królu, żyj na wieki!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Uradzili wszyscy książęta królestwa, przełożeni i starostowie, urzędnicy i hetmani, aby postanowiony był dekret królewski, i stwierdzony wyrok, aby każdy, któryby do trzydziestu dni o cokolwiek prosił którego boga albo człowieka oprócz ciebie, królu! był wrzucony do dołu lwiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'A tak teraz, o królu! potwierdź ten wyrok, a podaj go na piśmie, żeby się nie odmienił według prawa Medskiego i Perskiego, które się nie odmienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Skąd król Daryjusz podał na piśmie ten wyrok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Czego gdy się Danijel dowiedział, że był podany na piśmie, wszedł do domu swego, gdzie otworzone były okna w pokoju jego przeciw Jeruzalemowi, a trzy kroć przez dzień klękał na kolana swoje, i modlił się, a chwałę dawał Bogu swemu, jako to był z wykł przedtem czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Tedy oni mężowie zgromadziwszy się, a znalazłszy Danijela modlącego się i prośby wylewającego do Boga swego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Przystąpili i mówili królowi o wyroku królewskim: Izaliś wyroku nie wydał, aby każdy człowiek, któryby do trzydziestu dni o cokolwiek prosił którego boga albo człowieka oprócz ciebie, królu! był wrzucony do dołu lwiego? Odpowiedział król, i rzekł: Prawdziwa to mowa według prawa Medskiego i Perskiego, które się nie odmienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Tedy odpowiadając rzekli do króla: Ten Danijel, który jest z więźniów synów Judzkich, nie ma względu na cię, o królu! ani na twój wyrok, któryś wydał; bo trzy kroć przez dzień odprawuje modlitwy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Te słowa gdy król usłyszał, bardzo się zasmucił nad tem; i skłonił król do Danijela serce swoje, aby go wyswobodził; aż do zachodu słońca starał się, aby go wyrwał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Ale mężowie oni zgromadzili się do króla, i rzekli królowi: Wiedz, królu! iż to jest prawo u Medów i u Persów, aby żaden wyrok i dekret, któryby król postanowił, nie był odmieniony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Tedy król rozkazał, aby przywiedziono Danijela, i wrzucono go do dołu lwiego; a król mówiąc rzekł do Danijela: Bóg twój, któremu ty ustawicznie służysz, ten cię wybawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Tedy przyniesiono kamień jeden, i położono go na dziurze onego dołu, i zapieczętował go król sygnetem swoim, i sygnetami książąt swoich, aby nie był odmieniony dekret wydany przeciwko Danijelowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Potem odszedł król na pałac swój, i przenocował nic nie jadłszy, i nic nie przypuścił przed się, coby go uweselić mogło, tak, że i sen jego odstąpił od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Tedy król wstawszy bardzo rano na świtaniu z kwapieniem poszedł do dołu lwiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'A gdy się przybliżył do dołu, zawołał na Danijela głosem żałośnym, a mówiąc król rzekł do Danijela: Danijelu, sługo Boga żywego! Bóg twój, któremu ty ustawicznie służysz, mógłże cię wybawić ode lwów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Tedy Danijel do króla rzekł: Królu, żyj na wieki!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Bóg mój posłał Anioła swego, który zamknął paszczękę lwom, aby mi nie zaszkodziły, dlatego, że się przed nim znalazła niewinność we mnie; owszem, ani przed tobą, królu! nicem złego nie uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Tedy się król wielce ucieszył z tego, i rozkazał Danijela wyciągnąć z dołu; i wyciągniono Danijela z dołu, a żadnego obrażenia nie znaleziono na nim; bo wierzył w Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'I rozkazał król, aby przywiedziono onych mężów, którzy byli oskarżyli Danijela, i wrzucono ich do dołu lwiego, onych samych, i synów ich, i żony ich; a pierwej niż dopadli do dna onego dołu, pochwyciły ich lwy, i wszystkie kości ich pokruszyły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Tedy król Daryjusz napisał do wszystkich ludzi, narodów, i języków, którzy mieszkali po wszystkiej ziemi: Pokój się wam niech rozmnoży!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Wydany jest odemnie ten wyrok, aby po wszystkiem państwie królestwa mego wszyscy drżeli a bali się oblicza Boga Danijelowego; bo on jest Bóg żyjący i trwający na wieki, a królestwo jego ani władza jego nie będzie skażona aż do końca;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'On wyrywa i wybawia, a czyni znaki i cuda na niebie i na ziemi, który wyrwał Danijela z mocy lwów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'A Danijelowi się szczęśliwie powodziło w królestwie Daryjusza, i w królestwie Cyrusa, Persy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Roku pierwszego Balsazara, króla Babilońskiego, miał Danijel sen i widzenia swoje na łożu swem; tedy spisał on sen, i sumę rzeczy powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'A mówiąc Danijel rzekł: Widziałem w widzeniu mojem w nocy, a oto cztery wiatry niebieskie potykały się na morzu wielkiem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'A cztery bestyje wielkie występowały z morza, różne jedna od drugiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Pierwsza podobna lwowi, mając skrzydła orle; i przypatrywałem się, aż wyrwane były skrzydła jej, któremi się podnosiła od ziemi, tak, że na nogach jako człowiek stanęła, a serce człowiecze jej dane jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Potem oto bestyja druga podobna niedźwiedziowi; i stanęła przy jednej stronie, a trzy żebra były w paszczęce jej między zębami jej, i tak mówiono do niej: Wstań, nażryj się dostatkiem mięsa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Potemem widział, a oto inna bestyja podobna lampartowi, która miała cztery skrzydła ptasze na grzbiecie swym, cztery też głowy miała ta bestyja, i dano jej władzę wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Potemem widział w widzeniach nocnych, a oto bestyja czwarta straszna i sroga i bardzo mocna, mająca zęby żelazne wielkie, która pożerała i kruszyła, a ostatek nogami swemi deptała; a ta była różna od wszystkich bestyj, które były przed nią, i miał a dziesięć rogów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Pilniem się przypatrywał rogom, a oto róg pośledni mały wyrastał między niemi, i trzy z tych rogów pierwszych wyłamane są przed nim; a oto w onym rogu były oczy podobne oczom człowieczym, i usta mówiące rzeczy wielkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'I przypatrywałem się, aż one stolice postawione były, a Starodawny usiadł, którego szata była jako śnieg biała, a włosy głowy jego jako wełna czysta, stolica jego jako płomienie ogniste, a koła jej jako ogień gorejący.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Rzeka ognista płynąc wychodziła od oblicza jego. Tysiąc tysięcy służyło mu, a dziesięć kroć tysiąc tysięcy stało przed nim; sąd zasiadł, a księgi otworzone były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Tedym się przypatrywał, skoro się głos począł tych słów wielkich, które on róg mówił; przypatrywałem się, aż była ta bestyja zabita, i zginęło ciało jej, a podane było na spalenie ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Także i pozostałym bestyjom odjęta jest władza ich: bo długość żywota dana im była aż do czasu, a to do zamierzonego czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Widziałem też w widzeniu nocnem, a oto przychodził w obłokach niebieskich podobny synowi człowieczemu, a przyszedł aż do Starodawnego, i przywiedziono go przed obliczność jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'I dał mu władzę i cześć i królestwo, aby mu wszyscy ludzie, narody i języki służyli; władza jego władza wieczna, która nie będzie odjęta, a królestwo jego, które nie będzie skażone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'I zatrwożył się we mnie Danijelu duch mój w pośród ciała mego, a widzenia, którem widział, przestraszyły mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Tedym przystąpił do jednego z tych, którzy tam stali, a pewnościm się dowiadywał od niego o tem wszystkiem, i powiedział mi, i wykład mów oznajmił mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Te bestyje wielkie, których są cztery, są cztery królowie, którzy powstaną z ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Ci ujmą królestwo świętych najwyższych miejsc, którzy posiąść mają królestwo aż na wieki, i aż na wieki wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Tedym pragnął wziąć sprawę o bestyi czwartej, która była różna od wszystkich innych, bardzo straszna, której zęby były żelazne, a paznogcie jej miedziane; która pożerała i kruszyła, a ostatek nogami swemi deptała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Także o onych rogach dziesięciu, które były na głowie jej, i o poślednim, który był wyrósł, przed którym wypadły trzy; o tym rogu mówię, który miał oczy i usta mówiące wielkie rzeczy, a na wejrzeniu był większy nad inne rogi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'I przypatrywałem się, a oto róg ten walczył z świętymi, i przemagał ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Aż przyszedł Starodawny a podany jest sąd świętym najwyższych miejsc, a czas przyszedł, aby to królestwo święci otrzymali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'I rzekł tak: Bestyja czwarta, czwarte królestwo znaczy na ziemi, które będzie różne od wszystkich królestw, a pożre wszystkę ziemię, a podepcze a pokruszy ją;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'A dziesięć rogów to znaczy, że z królestwa onego dziesięć królów powstanie; a po nich powstanie pośledni, który będzie różny od pierwszych, i trzech królów poniży;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'A słowa przeciw Najwyższemu mówić będzie, i święte najwyższych miejsc zetrze; nadto będzie zamyślał, aby odmienił czasy i prawa, gdyż wydane będą w ręce jego aż do czasu i czasów, i pół czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Potem zasiądzie sąd, a tam władzę jego odejmą, aby był zniszczony i wytracony aż do końca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'A królestwo i władza, i dostojeństwo królewskie pod wszystkiem niebem dane będzie ludowi świętych najwyższych miejsc, którego królestwo będzie królestwo wieczne, a wszystkie zwierzchności jemu służyć i onego słuchać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Aż dotąd koniec tych słów. A mnie Danijela myśli moje wielce zatrwożyły, a jasność moja zmieniła się przy mnie; wszakżem to słowo w sercu mojem zachował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Roku trzeciego królowania Balsazara, króla, okazało mi się widzenie, mnie Danijelowi, po onem, które mi się okazało na początku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'I widziałem w widzeniu, a (gdym to widział, byłem w Susan, mieście głównem, które było w krainie Elam) widziałem, mówię, w widzeniu, gdym był u potoku Ulaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'I podniosłem oczy moje, i ujrzałem, a oto u onego potoku stał baran jeden mający dwa rogi, a te dwa rogi były wysokie, lecz jeden był wyższy niż drugi; ale ten wyższy rósł pośledzej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Widziałem onego barana trykającego na zachód, i na północ, i na południe, a żadna mu bestyja zdołać nie mogła, i nie był, ktoby co wyrwał z ręki jego; skąd czynił według woli swojej, i stał się wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Co gdym ja uważał, oto kozieł z kóz przychodził od zachodu na oblicze wszystkiej ziemi, a nikt się go nie dotykał na ziemi; a ten kozieł miał róg znaczny między oczyma swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'I przyszedł aż do onego barana, który miał dwa rogi, któregom widział stojącego u potoku; a przybieżał do niego w popędliwości siły swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Widziałem także, iż natarł na onego barana, a rozjadłszy się nań uderzył barana, tak, że złamał one oba rogi jego, i nie było mocy w baranie, żeby mu mógł odpór; a rzuciwszy go o ziemię zdeptał go, a nie był, ktoby wyrwał barana z mocy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Tedy on kozieł z kóz stał się bardzo wielkim; ale gdy się zmocnił, złamał się on róg wielki, a wyrosły cztery rogi znaczne miasto niego na cztery strony świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'A z jednego z nich wyszedł róg jeden mały, a ten wielce urósł ku południowi, i ku wschodowi i ku ziemi ozdobnej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'I wyrósł aż do wojska niebieskiego, i zrzucił niektórych na ziemię z onego wojska i z gwiazd, i podeptał ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Nawet aż do książęcia onego wojska wyrósł; bo przezeń odjęta była ustawiczna ofiara, i zarzucone miejsce świątnicy Bożej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Także wojsko one podane w przestępstwo przeciwko ustawicznej ofierze, i porzuciło prawdę na ziemię, a cokolwiek czyniło, szczęściło mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Tedym usłyszał jednego z świętych mówiącego: i rzekł ten święty do onego, który mając policzone tajemnice, mówi: Dokądże to widzenie o ofierze ustawicznej i przestępstwo pustoszące trwać będzie, i święte usługi, i wojsko na podeptanie podane będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'I rzekł do mnie: Aż do dwóch tysięcy i trzech set wieczorów i poranków; tedy przyjdą do odnowienia swego usługi święte.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'A gdym ja Danijel patrzył na to widzenie, i pytałem się o wyrozumieniu jego, tedy oto stanął ktoś podle mnie, na wejrzeniu jako mąż.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Słyszałem też głos ludzki między Ulajem, który zawoławszy rzekł: Gabryjelu! wyłóż mu to widzenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'I przyszedł do mnie, gdziem stał; a gdy przyszedł, zlękłem się i padłem na oblicze swoje. I rzekł do mnie: Wyrozumij, synu człowieczy! bo czasu pewnego to widzenie się wypełni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'A gdy on mówił ze mną, usnąłem twardo, leżąc twarzą swoją na ziemi, i dotknął się mnie, i postawił mię tam, gdziem pierwej stał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'I rzekł: Oto ja tobie oznajmię, co się dziać będzie aż do wykonania tego gniewu; bo czasu naznaczonego koniec będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Ten baran, któregoś widział mającego dwa rogi, są królowie, Medski i Perski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'A ten kozieł kosmaty jest król Grecki, a ten róg wielki, który jest między oczyma jego, jest król pierwszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'A iż złamany jest, a powstały cztery miasto niego, czworo królestw z jego narodu powstaną, ale nie z taką mocą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'A przy skończeniu królestwa ich, gdy przestępnicy złości dopełnią, powstanie król niewstydliwej twarzy i chytry;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'I zmocni się siła jego, aczkolwiek nie jego siłą, tak, że na podziw będzie wytracał, a szczęśliwie mu się powiedzie, i wszystko wykona; bo wytracać będzie mocarzów i lud święty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'A przemysłem jego poszczęści mu się zdrada w ręku jego, a uwielbi sam siebie w sercu swojem, i czasu pokoju wiele ich pogubi; nadto i przeciw książęciu książąt powstanie, a wszakże bez ręki pokruszony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'A to widzenie wieczorne i poranne, o którem powiedziano, jest sama prawda; przetoż ty zapieczętuj to widzenie, bo jest wielu dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Tedym ja Danijel zemdlał, i chorowałem przez kilka dni; potem wstawszy odprawowałem sprawy królewskie, a zdumiewałem się nad onem widzeniem, czego jednak nikt nie obaczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Roku pierwszego Daryjusza, syna Aswerusowego, z nasienia Medów, który był postanowiony królem na królestwem Chaldejskiem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'Roku pierwszego królowania jego, ja Danijel zrozumiałem z ksiąg liczbę lat, o których było słowo Pańskie do Jeremijasza proroka, że się wypełnić miało spustoszenie Jeruzalemskie w siedmdziesięt lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'I obróciłem oblicze moje do Pana Boga, szukając go modlitwą i prośbami w poście i w worze i w popiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Modliłem się tedy Panu Bogu memu, a wzywając rzekłem: Proszę Panie! Boże wielki i straszny, strzegący przymierza i miłosierdzia tym, którzy cię miłują, i strzegą przykazań twoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Zgrzeszyliśmy i przewrotnieśmy czynili, i niezbożnieśmy się sprawowali, i sprzeciwiliśmy się, a odstąpiliśmy od przykazań twoich i od sądów twoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'I nie słuchaliśmy sług twoich, proroków, którzy mawiali w imieniu twojem do królów naszych, do książąt naszych, i do ojców naszych, i do wszystkiego ludu ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Tobie, Panie! sprawiedliwość, a nam zawstydzenie twarzy należy, jako się to dzieje dnia tego mężom Judzkim i obywatelom Jeruzalemskim i wszystkiemu Izraelowi, bliskim i dalekim we wszystkich ziemiach, do którycheś ich wygnał dla przestępstwa ich, którem wystąpili przeciwko tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'Panie! namci należy zawstydzenie twarzy, królom naszym, książętom naszym i ojcom naszym, bośmy zgrzeszyli przeciwko tobie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Ale Panu, Bogu naszemu, miłosierdzie i litość; ponieważeśmy mu odporni byli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'A nie byliśmy posłuszni głosowi Pana, Boga naszego, żebyśmy chodzili w ustawach jego, które on dał przed oblicze nasze przez proroków, sług swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Owszem, wszyscy Izraelczycy przestąpili zakon twój i odchylili się, żeby nie słuchali głosu twego: przetoż się wylało na nas to złorzeczeństwo i przeklęstwo, które jest napisane w zakonie Mojżesza, sługi Bożego; bośmy zgrzeszyli przeciwko niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Skąd spełnił słowa swoje, które mówił przeciwko nam, i przeciwko sędziom naszym, którzy nas sądzili, a przywiódł na nas to wielkie złe, które się nie stało pod wszystkiem niebem, jakie się stało w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Tak jako napisano w zakonie Mojżeszowym, wszystko to złe przyszło na nas; a wżdyśmy nie prosili oblicza Pana, Boga naszego, abyśmy się odwrócili od nieprawości naszych, a mieli wzgląd na prawdę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Przetoż nie omieszkał Pan z tem złem, ale je przywiódł na nas; bo sprawiedliwy jest Pan, Bóg nasz, we wszystkich sprawach swoich, które czyni, któregośmy głosu nie słuchali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Wszakże teraz, o Panie, Boże nasz! któryś wywiódł lud swój z ziemi Egipskiej ręką możną, i uczyniłeś sobie imię. jako się to dziś pokazuje, zgrzeszyliśmy, niepobożnieśmy czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'O Panie! według wszystkich sprawiedliwości twoich niech się proszę odwróci popędliwość twoja i gniew twój od miasta twego Jeruzalemu, góry świętobliwości twojej: bo dla grzechów naszych i dla nieprawości ojców naszych Jeruzalem i lud twój nosi po hańbienie u wszystkich, którzy są około nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Teraz tedy wysłuchaj, o Boże nasz! modlitwę sługi twego i prośby jego, a oświeć oblicze twoje nad spustoszoną świątnicą twoją, dla Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Nakłoń, Boże mój! ucha twego a usłysz; otwórz oczy twoje a obacz spustoszenia nasze i miasto, które jest nazwane od imienia twego; bo my przekładamy modlitwy nasze przed obliczem twojem, nie dla jakiej naszej sprawiedliwości, ale dla obfitego miłosierdzia twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'O Panie! wysłuchaj, Panie! odpuść, Panie! obacz a uczyń; nie odwłaczaj sam dla siebie, Boże mój! bo od imienia twego nazwane jest to miasto i lud twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'A gdym ja jeszcze mówił, i modliłem się, i wyznawałem grzech mój i grzech ludu mego Izraelskiego, i przekładałem modlitwę moję przed twarzą Pana, Boga mego, za górę świętobliwości Boga mego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Prawie gdym ja jeszcze mówił i modliłem się, oto mąż on Gabryjel, któregom widział w widzeniu na początku, prędko lecąc dotknął się mnie czasu ofiary wieczornej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'A usługując mi do zrozumienia mówił ze mną i rzekł: Danijelu! terazem wyszedł, abym cię nauczył wyrozumienia tajemnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Na początku modlitw twoich wyszło słowo, a jam przyszedł, abym ci je oznajmił, boś ty wielce przyjemny; a tak miej wzgląd na to słowo, a zrozumiej to widzenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Siedmdziesiąt tego dni zamierzono ludowi twemu i miastu twemu świętemu na zniesienie przestępstwa, i na zagładzenie grzechów i na oczyszczenie nieprawości, i na przywiedzienie sprawiedliwości wiecznej, i na zapieczętowanie widzenia i proroctwa, a na pomazanie Świętego świętych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Przetoż wiedz a zrozumiej, że od wyjścia słowa o przywróceniu i zbudowaniu Jeruzalemu aż do Mesyjasza wodza będzie tygodni siedm, potem tygodni sześćdziesiąt i dwa, gdy znowu zbudowana będzie ulica i przekopanie, a te czasy będą bardzo trudne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'A po onych sześćdzesięciu i dwóch tygodniach zabity będzie Mesyjasz, wszakże mu to nic nie zaszkodzi; owszem, to miasto i tę świątnicę skazi lud wodza przyszłego, tak, że koniec jego będzie z powodzią, i aż do skończenia wojny będzie ustawiczne pustoszenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Wszakże zmocni przymierze wielom ich w tygodniu ostatnim; a w połowie onego tygodnia uczyni koniec ofierze palonej i ofierze śniednej, a przez wojsko obrzydliwe pustoszyciel przyjdzie, i aż do skończenia naznaczonego wyleje się spustoszenie na te go, który ma być spustoszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Roku trzeciego Cyrusa, króla Perskiego objawione było słowo Danijelowi, którego imię nazwano Baltazar; a to słowo było prawdziwe, i czas zamierzony długi; i zrozumiał ono słowo, bo wziął zrozumienie w widzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'W one dni ja Danijel byłem smutny przez trzy tygodnie dni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Chlebam smacznego nie jadł, a mięso i wino nie wchodziło w usta moje, anim się mazał olejkiem, aż się wypełniły dni trzech tygodni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'A dnia dwudziestego i czwartego miesiąca pierwszego byłem nad brzegiem rzeki wielkiej, to jest Chydekel;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'A podniósłszy oczy moje ujrzałem, a oto mąż niejaki ubrany w szatę lnianą, a biodra jego przepasane były złotem szczerem z Ufas;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'A ciało jego było jako Tarsys, a oblicze jego na wejrzeniu jako błyskawica, a oczy jego były jako lampy gorejące, a ramiona jego i nogi jego na wejrzeniu jako miedź wypolerowana, a głos słów jego jako głos mnóstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'A widziałem ja Danijel sam to widzenie; lecz mężowie, którzy byli ze mną nie widzieli tego widzenia; ale strach wielki przypadł na nich, i pouciekali a pokryli się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'A jam sam został, i widziałem to wielkie widzenie; ale siła nie została we mnie, i krasa moja odmieniła się we mnie, i skaziła się, i nie miałem żadnej siły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Tedym słyszał głos słów jego; a usłyszawszy głos słów jego usnąłem twardo na twarzy mojej, na twarzy mojej, mówię, na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Wtem oto ręka dotknęła się mnie, i podniosła mię na kolana moje, i na dłonie rąk moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'I rzekł do mnie: Danijelu, mężu wielce przyjemny! miej wzgląd na słowa moje, które ja będę mówił do ciebie, a stój na miejscu swem, bom teraz posłany do ciebie. A gdy przemówił do mnie to słowo, stałem drżąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'I rzekł do mnie: Nie bój się Danijelu! bo od pierwszego dnia, jakoś przyłożył serce twoje ku wyrozumieniu i trapiłeś się Bogiem twoim, wysłuchane są słowa twoje, a jam przyszedł dla słów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Lecz książę królestwa Perskiego sprzeciwiał mi się przez dwadzieścia dni i jeden, aż oto Michał, jeden z przedniejszych książąt, przyszedł mi na pomoc; przetożem ja tam został przy królach Perskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Alem przyszedł, abym ci oznajmił, co ma przyjść na lud twój w ostateczne dni; bo jeszcze widzenie będzie o tych dniach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'A gdy mówił do mnie temi słowy, spuściłem twarz moję ku ziemi, i zamilknąłem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'A oto jako podobieństwo synów ludzkich dotknęło się warg moich; a otworzywszy usta swe mówiłem i rzekłem do stojącego przeciwko mnie: Panie mój! dla tego widzenia obróciły się na mię boleści moje, i nie miałem żadnej siły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'A jakoż będzie mógł taki sługa Pana mego rozmówić się z takim Panem moim? Gdyż od tegoż czasu nie została we mnie siła, ani tchnienie zostało we mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Tedy się mnie znowu dotknął na wejrzeniu jako człowiek, i posilił mię,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'I rzekł: Nie bój się, mężu wielce przyjemny, pokój tobie! posil się, posil się, mówię. A gdy mówił ze mną, wziąłem siłę i rzekłem: Niech mówi Pan mój; albowiemeś mię posilił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'I rzekł: Wieszże, dlaczegom przyszedł do ciebie? Potem się wrócę, abym walczył z książęciem Perskim, a gdy odejdę, oto książę Grecki przyciągnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Wszakże oznajmięć to, co jest wyrażono w piśmie prawdy; ale i jednego niemasz, któryby mężnie stał przy mnie w tych rzeczach, oprócz Michała, książęcia waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Ja tedy roku pierwszego za Daryjusza Medskiego stanąłem, abym go posilił i zmocnił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'A teraz ci prawdę oznajmię: Oto jeszcze trzej królowie królować będą w Perskiej ziemi; potem czwarty zbogaci się bogactwy wielkimi nade wszystkich, a gdy się zmocni w bogactwach swoich, pobudzi wszystkich przeciw królestwu Greckiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'I powstanie król mocny, a będzie panował mocą wielką, a będzie czynił według woli swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'A gdy się on zmocni, będzie skruszone królestwo jego, i będzie rozdzielone na cztery strony świata, wszakże nie między potomków jego, ani będzie państwo jego takie, jakie było; bo wykorzenione będzie królestwo jego, a innym mimo onych dostanie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Tedy się zmocni król z południa i jeden z książąt jego; ten mocniejszy będzie nadeń, i panować będzie, a państwo jego będzie państwo szerokie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Lecz po wyjściu kilku lat złączą się; bo córka króla od południa pójdzie za króla północnego, aby uczyniła przymierze; wszakże nie otrzyma siły ramienia, ani się ostoi z ramieniem swojem, ale wydana będzie ona, i ci, którzy ją przyprowadzą, i syn jej, i ten, co ją zmacniał za onych czasów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Potem powstanie z latorośli korzenia jej na miejsce jego, który przyciągnie z wojskiem swem, a uderzy na miejsce obronne króla północnego, i przewiedzie nad nimi i zmocni się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Nadto i bogów ich z książętami ich, z naczyniem ich drogiem, srebrnem i złotem w niewolę zawiedzie do Egiptu; a ten będzie bezpieczen przez wiele lat od króla północnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'A tak wtargnie w królestwo król od południa, i wróci się do ziemi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Ale synowie jego walczyć będą, i zbiorą mnóstwo wojsk wielkich; a z nagła następując jako powódź przechodzić będzie, potem wracając się, wojskiem nacierać będzie aż na twierdze jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Skąd rozdrażniony będąc król z południa wyciągnie, i będzie walczył z nim, to jest, z królem północnym; a uszykuje mnóstwo wielkie, ale ono mnóstwo będzie podane w rękę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'A gdy zniesione będzie ono mnóstwo, podniesie się serce jego; a choć porazi wiele tysięcy, przecie się nie zmocni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Bo się wróci król północny, i uszykuje większe mnóstwo niż pierwsze; lecz po wyjściu czasu kilku lat z nagła przyjdzie z wielkiem wojskiem i z wielkim dostatkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Onychże czasów wiele ich powstanie przeciwko królowi z południa; ale synowie przestępników z ludu twego będą zniesieni dla utwierdzenia tego widzenia, i upadną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Bo przyciągnie król z północy, i usypie wały, i weźmie miasto obronne, a ramiona południowe nie oprą się, ani lud jego wybrany, i nie stanie im siły, aby dali odpór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'I uczyni on, który przyciągnie przeciwko niemu, według woli swojej, i nie będzie nikogo, coby się stawił przeciwko niemu; stawi się też w ziemi ozdobnej, która zniszczeje przez rękę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Potem obróci twarz swoję, aby przyszedł z mocą wszystkiego królestwa swego, i okazał się, jakoby zgody szukał, i uczyni coś; bo mu da córkę piękną, aby go zgubił przez nią; ale ona w tem nie będzie stateczna, i nie będzie z nim przestawała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Zatem obróci twarz swoję do wysep, i wiele ich pobierze; ale wódz wstręt uczyni hańbieniu jego, owszem, ono hańbienie jego nań obróci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Dlaczego obróci twarz swoję ku twierdzom ziemi swej; lecz się potknie i upadnie, i nie będzie więcej znaleziony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'I powstanie na miejsce jego taki, który roześle poborców w sławie królewskiej; ale ten po niewielu dniach starty będzie, a to nie w gniewie ani przez wojnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Potem powstanie wzgardzony na jego miejsce, acz nie włożą nań ozdoby królewskiej; wszakże przyszedłszy w pokoju, otrzyma królestwo pochlebstwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'A ramionami jako powodzią wiele ich zachwyceni będą przed obliczem jego, i skruszeni będą, także też i sam wódz, który z nimi przymierze uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Bo wszedłszy z nimi w przyjaźń, uczyni zdradę, a przyciągnąwszy zmocni się w małym poczcie ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Bezpiecznie i do najobfitszych miejsc onej krainy wpadnie, a uczyni to, czego nie czynili ojcowie jego, ani ojcowie ojców jego; łup i korzyść i majętności rozdzieli im, nawet i o miejscach obronnych chytrze przemyśliwać będzie, a to aż do czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Potem wzbudzi moc swoję, i serce swoje przeciw królowi z południa z wojskiem wielkiem, z którem król z południa walecznie się potykać będzie z wojskiem wielkiem i bardzo mocnem; ale się nie oprze, przeto, że wymyśli przeciwko niemu zdradę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Bo ci, którzy jedzą chleb jego, zniszczą go, gdy wojsko onego jako powódź przypadnie, a pobitych wiele polęże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Natenczas obaj królowie w sercu swem myślić będą, jakoby jeden drugiemu szkodzić mógł, a przy jednymże stole kłamstwo mówić będą; ale się im nie nada, gdyż jeszcze koniec na inszy czas odłożony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Przetoż się wróci do ziemi swojej z bogactwy wielkiemi, a serce jego obróci się przeciwko przymierzu świętemu; co uczyniwszy wróci się do ziemi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'A czasu zamierzonego wróci się i pociągnie na południe; ale mu się nie tak powiedzie, jako za pierwszym i za ostatnim razem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Bo przyjdą przeciwko niemu okręty z Cytym, skąd on nad tem bolejąc znowu się rozgniewa przeciwko przymierzu świętemu; co uczyniwszy wróci się, a będzie miał porozumienie z onymi, którzy opuścili przymierze święte;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'A wojska wielkie przy nim stać będą, które splugawią świątnicę, i twierdze zniosą; odejmą też ustawiczną ofiarę, a postawią obrzydliwość spustoszenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Tak aby tych, którzy niezbożnie przeciwko przymierzu postępować będą, w obłudzie pochlebstwem utwierdził, a żeby lud znający Boga swego imali, co też uczynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Zaczem ci, którzy nauczają lud, którzy nauczają wielu, padać będą od miecza i od ognia, od pojmania i od łupu przez wiele dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'A gdy padać będą, małą pomoc mieć będą; bo się do nich wiele pochlebców przyłączy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'A z tych, którzy innych nauczają, padać będą, aby doświadczeni i oczyszczeni, i wybieleni byli aż do czasu zamierzonego; bo to jeszcze potrwa aż do czasu zamierzonego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Tak uczyni król według woli swojej, i podniesie się i wielmożnym się uczyni nad każdego boga, i przeciwko Bogu nad bogami dziwne rzeczy mówić będzie, i poszczęści mu się, aż się dokona gniew, ażby się to, co jest postanowiono, wykonało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Ani na bogów ojców swych nie będzie dbał, ani o miłość niewiast, ani o żadnego boga dbać będzie, przeto, że się nade wszystko wyniesie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'A na miejscu Boga najmocniejszego czcić będzie boga, którego nie znali ojcowie jego; czcić będzie złotem i srebrem i kamieniem drogiem i rzeczami kosztownemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'A tak dowiedzie tego, że twierdze Najmocniejszego będą boga obcego; a których mu się będzie zdało, tych rozmnoży sławę, i uczyni, aby panowali nad wielą, a rozdzieli im ziemię miasto zapłaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'A przy skończeniu tego czasu będzie się z nim potykał król z południa; ale król północny jako burza nań przyjdzie z wozami i z jezdnymi i z wielą okrętów, a wtargnie w ziemię, i jako powódź przejdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Potem przyciągnie do ziemi ozdobnej, i wiele krain upadnie; wszakże ci ujdą rąk jego, Edomczycy i Moabczycy, i pierwociny synów Ammonowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'A gdy rękę swą ściągnie na krainy, ani ziemia Egipska tego ujść nie będzie mogła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Bo opanuje skarby złota i srebra, i wszystkie rzeczy drogie Egipskie, a Libijczycy i Murzynowie za nim pójdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'W tem wieści od wschodu słońca i od północy przestraszą go; przetoż wyciągnie z popędliwością wielką, aby wygubił i zamordował wielu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'I rozbije namioty pałacu swego między morzami na górze ozdobnej świętobliwości; a gdy przyjdzie do końca swego, nie będzie miał nikogo na pomocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Tego czasu powstanie Michał, książę wielki, który się zastawia za synami ludu twego; a będzie czas uciśnienia, jakiego nie było, jako narody poczęły być, aż do tego czasu; tego, mówię, czasu wyswobodzony będzie lud twój, ktokolwiek znaleziony będzie napisany w księgach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'A wiele z tych, którzy śpią w prochu ziemi, ocucą się, jedni ku żywotowi wiecznemu, a drudzy na pohańbienie i na wzgardę wieczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Ale ci, którzy innych nauczają, świecić się będą jako światłość na niebie, a którzy wielu ku sprawiedliwości przywodzą, jako gwiazdy na wieki wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Ale ty, Danijelu! zamknij te słowa, i zapieczętuj tę księgę aż do czau naznaczonego; bo to wiele ich przebieży, a rozmnoży się umiejętność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'I widziałem ja Danijel, a oto drudzy dwaj stali, jeden stąd nad brzegiem rzeki, a drugi z onąd nad drugim brzegiem rzeki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'I rzekł do męża obleczonego w szatę lnianą, który stał nad wodą onej rzeki: Kiedyż przyjdzie koniec tym dziwnym rzeczom?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'I usłyszałem tego męża obleczonego w szatę lnianą, który stał nad wodą onej rzeki, że podniósłszy prawicę swoję i lewicę swoję ku niebu przysiągł przez Żyjącego na wieki, iż po zamierzonym czasie i po zamierzonych czasach i po połowie czasu, i gdy do szczętu rozproszy siłą ręki ludu świętego, tedy się to wszystko wypełni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'A gdym ja to słyszał a nie zrozumiałem, rzekłem: Panie mój! cóż za koniec będzie tych rzeczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Tedy rzekł: Idź, Danijelu! bo zawarte i zapieczętowane są te słowa aż do czasu zamierzonego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Oczyszczonych i wybielonych i doświadczonych wiele będzie, a niezbożni niezbożnie czynić będą; nadto wszyscy niezbożni nie zrozumieją, ale mądrzy zrozumieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'A od tego czasu, którego odjęta będzie ofiara ustawiczna, a postawiona będzie obrzydliwość spustoszenia, będzie dni tysiąc, dwieście i dziewięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Błogosławiony, kto doczeka a dojdzie do tysiąca trzech set trzydziestu i pięciu dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Ale ty idź do miejsca twego, a odpoczniesz, i zostaniesz w losie twoim aż do skończenia dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Słowo Pańskie, które się stało do Ozeasza, syna Berowego, za dni Uzyjasza, Joatama, Achaza, Ezechyjasza, królów Judzkich, i za dni Jeroboama, syna Joazowego, króla Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Gdy począł Pan mówić do Ozeasza, rzekł Pan do Ozeasza: Idź, pojmij sobie żonę wszetecznicę, i spłódź dzieci z wszeteczeństwa; bo się ta ziemia, bez wstydu wszeteczeństwo płodząc, od Pana odwróciła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Odszedł tedy, i pojął Gomorę, córkę Dyblaimską, która poczęła i porodziła mu syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'I rzekł Pan do niego: Nazów imię jego Jezreel: bo jeszcze po małym czasie nawiedzę krew Jezreel nad domem Jehu, a sprawię to, że ustanie królestwo domu Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'A dnia onego złamię łuk Izraelski w dolinie Jezreel.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'I poczęła znowu i porodziła córkę; i rzekł mu Pan: Nazów imię jej Loruchama; bo się więcej nie zmiłuję nad domem Izraelskim, lecz ich zapewne wygładzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Ale nad domem Judzkim zmiłuję się, i wybawię ich przez Pana, Boga ich, a nie wybawię ich przez łuk, i przez miecz, i przez wojnę, i przez konie i przez jezdnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Potem ostawiwszy Loruchamę znowu poczęła i porodziła syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'I rzekł Pan: Nazów imię jego Loami; boście wy nie ludem moim, a Ja też nie będę waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Wszakże liczba synów Izraelskich będzie jako piasek morski, który ani zmierzony ani zliczony być może; i stanie się, że miasto tego, co im rzeczono: Nie jesteście wy ludem moim, rzeczono im będzie: Wyście synami Boga żyjącego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'I będą zgromadzeni synowie Judzcy i synowie Izraelscy wespół, a postanowiwszy nad sobą głowę jednę, wynijdą z tej ziemi; bo będzie wielki dzień Jezreela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Mówcie braciom waszym, o ludu mój! i siostrom waszym, o ty, coś miłosierdzia dostąpiła!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Rozpierajcie się z matką waszą, rozpierajcie się; bo ona nie jest żoną moją, a Jam też nie jest mężem jej, póki nie odejmie wszeteczeństw swoich od oblicza swego, a cudzołóstw swych z pośród piersi swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Bym jej snać nago nie zewlekł a nie postawił jej, jaką była w dzień narodzenia swego, i nie uczynił jej jako pustynia, i nie zostawił jej jako ziemia sucha, i nie umorzył jej pragnieniem:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'I nad synami jej nie zmiłowałbym się, przeto, że są synami z wszeteczeństwa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Bo wszeteczeństwo płodzi matka ich, sprosność czyni rodzicielka ich; bo mówiła: Pójdę za miłośnikami moimi, którzy mi dodawają chleba mego, i wody mojej, wełny mojej, i lnu mego, oliwy mojej i napojów moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Przetoż oto Ja zagrodzę cierniem drogę jej, a ugrodzę płot, aby ścieżek swoich nie znalazła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Tedy biegać będzie za miłośnikami swymi, wszakże ich nie dogoni; i szukać ich będzie, ale nie znajdzie. Tedy rzecze: Pójdę a wrócę się do męża swego pierwszego; bo mi lepiej było na on czas, niżeli teraz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Bo ona nie wie tego, żem Ja dawał jej zboże, i moszcz, i oliwę; nawet dawałem jej obfitość srebra i złota, które oni obracają na Baala.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Dlatego wrócę się, i zabiorę zboże moje czasu jego, i moszcz mój czasu jego, i odbiorę jej wełnę moję, i len mój dany na okrywanie nagości jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'A teraz odkryję sprosność jej przed oczyma miłośników jej, a nikt jej nie wyrwie z ręki mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'I uczynię koniec wszystkiemu weselu jej, świętom jej, nowym miesiącom jej, i sabatom jej, i wszystkim uroczystym świętom jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Popustoszę też winne macice jej i figowe drzewa jej, przeto, że mówi: Moja to zapłata, którą mi dali miłośnicy moi; i obrócę je w lasy, a pożrą je zwierzęta polne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'I nawiedzę na niej dni Baalowe, w które im kadzi, a strojąc się w nausznice swoje i w klejnoty swoje, chodzi za miłośnikami swymi, ale mnie zapomina, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Przetoż oto Ja nią łudzić będę, gdy ją wywiodę na puszczę, a łaskawie z nią mówić będę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'I dam jej winnice jej od tegoż miejsca, i dolinę Achor, miasto drzwi nadziei; i będzie tam śpiewała, jako za dni młodości swojej, to jest, jako w dzień, którego wychodziła z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'A dnia onego mówi Pan, będziesz mię zwała: Mężu mój! a nie będziesz mię więcej zwała: Baalu mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Bo odejmę imiona Baalów od ust twoich, że ani wspominani będą więcej imieniem swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'I uczynię dla ciebie przymierze dnia onego z zwierzem polnym, i z ptastwem niebieskiem i z płazem ziemskim, a łuk i miecz pokruszę, i wojnę z ziemi zniosę, i sprawię, że bezpiecznie mieszkać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'I poślubię cię sobie na wieki: poślubię cię, mówię, sobie w sprawiedliwości i w sądzie i w miłosierdziu i w litościach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Poślubię cię też sobie w wierze, i poznasz Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Dnia onego wysłucham, mówi Pan, wysłucham, mówi, niebiosa, a one wusłuchają ziemię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'A ziemia wysłucha zboże i moszcz i oliwę, a te rzeczy wysłuchają Jezreela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Bo ją sobie rozsieję na ziemi, a zmiłuję się nad tą, co była w niełasce, i rzekę do tego, co nie był ludem moim: Tyś jest lud mój! a on rzecze: Tyś jest Bóg mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'I rzekł Pan do mnie: Jeszcze idź, a rozmiłuj się niewiasty umiłowanej od innego, a cudzołożnicy, tak jako miłuje Pan synów Izraelskich, choć się oni oglądają na cudzych bogów, a miłują fasy wina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'I kupiłem ją sobie za piętnaście srebrników i za półtora homera jęczmienia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'I rzekłem do niej: Siedź mi tak przez wiele dni, a nie płódź wszeteczeństwa, ani chodź za mąż, a ja też dla ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Bo przez wiele dni będą synowie Izraelscy bez króla i bez książęcia, i bez ofiary i bez bałwana, i bez Efodu i bez Terafim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'A potem nawrócą się synowie Izraelscy i szukać będą Pana, Boga swego, i Dawida, króla swego, a przestraszeni będąc pójdą do Pana i do dobrotliwości jego w ostatnie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Słuchajcie słowa Pańskiego, o synowie Izraelscy! bo się Pan rozpiera z obywatelami tej ziemi, gdyż niemasz prawdy, ani żadnego miłosierdzia, ani znajomości Bożej w tej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Krzywoprzysięstwem, i kłamstwem, i mężobójstwem, i złodziejstwem, i cudzołóstwem wylewali z brzegów, a mężobójstwo mężobójstwa ścigało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Dlatego ziemia kwilić będzie, a zemdleje wszystko, co na niej mieszka; zwierz polny i ptastwo niebieskie, nawet i ryby morskie zginą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'A wszakże niech się nikt z nimi nie spiera, ani ich kto strofuje; bo lud twój jest jako ci, którzy się z kapłanem wadzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Przetoż upadniesz we dnie, upadnie też i prorok z tobą w nocy; zagładzę i matkę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Lud mój wygładzony będzie dla nieumiejętności; a ponieważeś ty odrzucił umiejętność, i Ja też ciebie odrzucę, abyś mi kapłańskiego urzędu nie odprawował; a iżeś zapomniał zakonu Boga twego, Ja też zapomnę na synów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Czem się więcej rozmnożyli, tem więcej grzeszyli przeciwko mnie; dlatego sławę ich odmienię w hańbę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Ofiary za grzech ludu mego jedzą: przetoż do nieprawości ich podnoszą duszę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Przetoż stanie się jako ludowie, tak i kapłanowi; bo nawiedzę na nim drogi jego, a uczynki jego oddam mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'I będą jeść, wszakże się nie nasycą, nierząd płodzić będą, ale się nie rozrodzą; bo nie chcą mieć względu na Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Wszeteczństwo, i wino, i moszcz odejmuje serce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Lud mój drewna swego się pyta, a kij jego odpowiada mu; bo ich duch wszeteczeństwa w błąd prowadzi, aby nierząd płodzili, odstępując od Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Na wierzchach gór ofiarują, a na pagórkach kadzą pod dębiną i pod topoliną, i pod więziną, bo dobry jest cień ich; dlatego wszeteczeństwo płodzą córki wasze, a niewiasty wasze cudzołożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Nie miałżebym nawiedzić córek waszych, gdy nierząd płodzą? i niewiast waszych, gdy cudzołożą? Albo gdy się i oni sami z nierządnicami odłączają, i z wszetecznicami ofiarują? Owszem, lud, który sobie tego w rozum nie bierze, upadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Jeźli nierząd płodzisz, ty Izraelu! niechże wżdy nie występuje Juda; przetoż nie chodźcie do Galgal, ani wstępujcie do Bet Awen, ani przysięgajcie mówiąc: Jako żyje Pan!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Bo Izrael jest nieokrócony jako jałowica nieokrócona: zaprawdę Pan ich paść będzie, jako baranki na przestrzeństwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Stowarzyszył się Efraim z bałwanami; zaniechaj go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Odpornymi ich czyni napój ich, nierząd ustawicznie płodzą; obrońcy jego z hańbą miłują dary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Zachwyci ich wiatr skrzydłami swemi, i będą zawstydzeni dla ofiar swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Słuchajcie tego, o kapłani! a miejcie wzgląd na to, domie Izraelski! i ty, domie królewski! słuchajcie; bo przeciwko wam sąd jest, przeto, żeście sidłem w Masfa, a siecią rozciągnioną na wierzchu Tabor.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Owszem, udawając się na zabijanie, przypadają do ziemi; ale Ja pokarzę każdego z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Ja znam Efraima, i Izrael nie jest skryty przedemną; bo teraz nierząd płodzisz, Efraimie! a Izrael splugawił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Nie mają się do tego, aby się nawrócili do Boga swego, przeto, że duch wszeteczeństwa jest w pośrodku nich, a Pana nie poznali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Świadczyć też będzie hardość Izraelska przeciwko niemu; przetoż Izrael i Efraim upadną dla nieprawości swojej, upadnie też i Juda z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Z trzodami swemi i z bydłem swojem pójdą szukać Pana; wszakże go nie znajdą; bo odstąpił od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Wystąpili przeciwko Panu, bo synów cudzych napłodzili; a tak teraz pożre ich miesiąc z majętnościami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Zatrąbcie w trąbę w Gabaa, i w trąbę w Rama; krzyczcie w Bet Awen: Nieprzyjaciel za tobą, o Benjaminie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraim spustoszony będzie w dzień karania, w pokoleniach Izraelskich oznajmiłem, że to prawda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Książęta Judzcy stali się jako ci, którzy granice przenoszą; wyleję na nich popędliwość moję jako wodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Uciśniony jest Efraim, pokruszony sądem; wszakże przecie ma wolę chodzić za rozkazaniem ludzkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Przetoż i Ja byłem Efraimowi jako mól, a domowi Judzkiemu jako spróchniałość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Skąd widząc Efraim mdłość swoję a Juda ranę swoję, uciekł się Efraim do Assura, i posłał do króla Jareba; ale on was nie będzie mógł uzdrowić, ani was uleczy od rany waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Bom Ja jest Efraimowi jako lew srogi, a domowi Judzkiemu jako lwię; Ja, Ja porwę, i odejdę; wezmę, a nikt mi nie wydrze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Pójdę, wrócę się do miejsca mego, aż się winnymi dadzą a szukać będę oblicza mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'W utrapieniu swojem rano mię szukać będą, mówiąc: Pójdźcie, a nawróćmy się do Pana; bo on porwał, a uzdrowi nas; uderzył, i zawiąże rany nasze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Ożywi nas po dwóch dniach, a dnia trzeciego wzbudzi nas, i żyć będziemy przed obliczem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Tedy poznawszy Pana starać się będziemy, abyśmy go więcej poznali; bo wyjście jego jako ranna zorza zgotowane jest, a przyjdzie nam jako deszcz na wiosnę i w jesieni na zimę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Cóż mam czynić z tobą, o Efraimie? cóż mam czynić z tobą, o Judo? gdyż miłosierdzie wasze jest jako obłok poranny a jako rosa rano przemijająca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Dlatego ociosywałem ich przez proroków, zabijałem ich słowy ust moich, aby światłość sądów twoich weszła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Bo miłosierdzia chcę, a nie ofiary, a znajomości Bożej więcej, niż całopalenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Ale oni przestąpili przymierze moje, jako ludzkie, a temci wystąpili przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Galaad jest miastem czyniących nieprawość, pełne stóp krwawych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'A jako zbójcy czynią, którzy na kogo czyhają na drodze, kędy chodzą do Sychem, tak czyni rota kapłanów; bo umyślnie niecnotę płodzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'W domu Izraelskim widzę sprosność; tam się wszeteczeństwem Efraimowem splugawił Izrael;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'I w tobie, o Judo! Efraim żniwo położył, gdym Ja zaś przywrócił pojmany lud mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Gdy leczę Izraela, tedy się odkrywa nieprawość Efraimowa i złości Samaryjskie, bo się bawią kłamstwem; w miastach złodziejstwo, a na dworze łupiestwo przewodzą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'A nie myślą w sercu swojem, że na wszystkie złości ich pamiętam; a teraz ich ogarniają sprawy ich, i są przed obliczem mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Króla uweselają złością swoją a książąt kłamstwy swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Wszyscy zgoła cudzołożą, są jako piec rozpalony od piekarza, który przestaje czuć, gdy zaczynił ciasto, ażby ukisiało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'W dzień króla naszego w chorobę go wprawiają książęta łagwiami wina, tak że i on rękę swą z naśmiewcami wyciąga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Bo przyłożyli serce swe do zasadzek, jako piec rozpalony; całą noc śpi piekarz ich, a z poranku gore jako płomień ognia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Wszyscy zgoła rozpalili się jako piec, a pożerają sędziów swoich; wszyscy królowie ich upadają, niemasz między nimi, ktoby wołał do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraim ten się z narodami zmieszał; Efraim będzie jako podpłomyk nieprzewracany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Pożarli obcy siłę jego, a on o tem nie wie; sędziwość też nań występuje, wszakże on tego nie wie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'A choć pycha Izraelska świadczy w oczy przeciwko niemu, wszakże się nie nawracają do Pana, Boga swego, ani go w tem wszystkiem szukają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'I stał się Efraim jako gołębica głupia, nie mająca serca; Egiptu przyzywają a do Assura się uciekają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Ale gdy odejdą, rozciągnę na nich sieć moję, a jako ptastwo niebieskie potargnę ich; skarzę ich, jako im o tem powiadano w zgromadzeniu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Biada im, że się rozbiegli odemnie! spustoszenie przyjdzie na nich, bo wystąpili przeciwko mnie; choćem Ja ich odkupił, ale oni przeciwko mnie mówili kłamstwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'I nie wołają do mnie z serca swego, gdy wyją na łożach swoich; wprawdźieć dla zboża i moszczu zgromadzają się, ale mię potem odstępują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Choćem utwierdzał ramiona ich pokarawszy ich, ale oni złe myślą przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Nawracają się, ale nie do Najwyższego; są jako łuk zdradliwy, polegną od miecza, książęta ich od popędliwości języka ich, co im jest ku pośmiewisku w ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Przyłóż trąbę do ust twoich, a rzecz: Oto leci na dom Pański jako orzeł, przeto, że przestąpili przymierze moje, a przeciwko zakonowi mojemu wykroczyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Będąć do mnie wołać: Boże mój! My, lud twój Izrael, znamy cię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Ale Izrael opuścił dobro; przetoż go nieprzyjaciel gonić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Oni stanowią królów, ale bezemnie: książąt obierają, do których się Ja nie znam; ze srebra swego i ze złota swego czynią sobie bałwany na swoje zginienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Opuści ich cielec twój, o Samaryja! gdy się zapali na nich gniew mój; dokądże nie będą mogli przestrzegać niewinności?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Wszak i on jest z Izraela; rzemieślnik go urobił, a nie jest Bogiem; bo się w proch obróci cielec Samaryjski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Bo iż wiatr siali, wicher też żąć będą, a żadnego źdźbła mieć nie będą; urodzaj nie wyda mąki, a choćby wydał, cudzoziemcy to zjedzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Izrael pożarty będzie, wnetże będzie między poganami jako naczynie, z którego niemasz żadnej uciechy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Przeto, że się oni do Assyryjczyka, osła leśnego, uciekają, który się samotnie chowa, a że Efraim sobie miłośników najmuje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'A iż dary posyłali między pogan: przetoż i Ja ich wnetże zbiorę, owszem, już cośkolwiek ucierpieli dla brzemienia króla książąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Bo iż rozmnożył Efraim ołtarze ku grzeszeniu, stały mu się one ołtarze ku grzeszeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Spisałem mu wielkie rzeczy w zakonie moim; ale tak je sobie waży jako co obcego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Z ofiar darów moich ofiarują mięso i jedzą, ale ich Pan nie przyjmuje; już wspomnę nieprawości ich, i nawiedzę grzechy ich, że się oni do Egiptu nawracają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'A że zapomniał Izrael stworzyciela swego, i nabudował kościołów, a Juda rozmnożył miasta obronne, przetoż poślę ogień na miasta jego, który pożre pałace jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Nie wesel się, Izraelu! nie raduj się jako inne narody, że nierząd płodzisz, odwracając się od Boga swego, a miłujesz zapłatę wszetecznicy na wszystkich bojewiskach zboża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Bojewisko ani prasa nie będzie ich żywiła, a moszcz omyli ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Nie będą mieszkać w ziemi Pańskiej; ale się Efraim wróci do Egiptu, a w Assyryi nieczyste rzeczy jeść będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Nie będą Panu wina ofiarowali, ani mu będą przyjemne. Ofiary ich będą im jako chleb płaczących; którzybykolwiek z niego jedli, zmazaliby się, przeto, że chleb ich za umarłych ich nie wnijdzie do domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Cóż będziecie czynić w dzień uroczysty i w dzień święta Pańskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Bo oto zaginą przez spustoszenie, Egipt zgromadzi ich a Memfis pogrzebie ich; srebro ich pożądane pokrzywa odziedziczy, a ciernie porosną w przybytkach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Przyjdą dni nawiedzenia, przyjdą dni zapłaty; pozna to Izrael, że ten prorok ich jest głupi, szalony, mąż nikczemny dla mnóstwa nieprawości twojej i dla wielkiej nienawiści twojej, o Izraelu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Prorok, który straż trzyma nad Efraimem pospołu z Bogiem moim, stał się sidłem ptasznika na wszystkich drogach jego, nienawiść jest w domu boga jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Głęboko zabrnęli, popsuli się jako za dni Gabaa; wspomnić Pan na nieprawości ich, i nawiedzi grzechy ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Znalazłem Izraela jako jagody winne na puszczy; widziałem ojców waszych jako pierwszy owoc figowy na początku ich; ale oni poszli za Baal Fegorem, a oddali się tej obrzydliwości; przetoż będą obrzydłymi, tak jako się im upodobało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Efraim uleci jako ptak, a sława ich zaraz od porodzenia, i od żywota, i od poczęcia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'A choćby odchowali synów swych, przecie ich pozbawię wieku męskiego; owszem, i onym biada, gdy Ja ich odstąpię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efraim, jako widzę, jest jako Tyr wszczepiony na miejscu rozkosznem; wszakże Efraim wywiedzie do mordercy synów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Daj im Panie! Cóż im dasz? Daj im żywot niepłodny a piersi wyschłe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Wszystka złość ich jest w Galgal, przetoż i tam ich nienawidzę; dla złości uczynków ich z domu mego wyrzucę ich, nie będę ich więcej miłował, wszyscy książęta ich odporni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Efraim porażony będzie, korzeń ich uschnie, owocu nie przyniosą; a choćby też spłodzili, tedy wybiję najmilsze dziatki żywota ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Odrzuci ich Bóg mój, bo go słuchać nie chcą; a między poganami tułaczami będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Izrael jest macicą próżną, owoc przynosi sobie; czem więcej miewał owocu swego, tem więcej nabudował ołtarzów; a czem obfitsza jest ziemia jego, tem więcej nastawiał obrazów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Rozdziela się serce ich, przetoż winnymi są; on pokruszy ołtarze ich, i obrazy ich popsuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Ponieważ mówią: Nie mamy króla, nawet nie boimy się Pana, a król nam co uczyni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Mówią słowa, przysięgając kłamliwie, gdy czynią przymierze; i wzrośnie sąd jako jad na zagonach polnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Dla jałowic Bet Aweńskich zatrwożą się obywatele Samaryjscy, gdy kwilić będą nad nim, lud jego, i popije go, (którzy się więc radowali z niego) przeto, że sława jego odchodzi od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Nawet i sam do Assyryi zaprowadzony będzie za dar królowi Jareb; zawstydzi się Efraim, i zasroma się Izrael za radę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Wycięty będzie król Samaryjski, jako piana na wierzchu wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'I będą wyżyny Awenu wytracone, grzech Izraelski; ciernie i oset wyrośnie na ołtarzach ich; a rzekną górom: Przykryjcie nas; a pagórkom: Upadnijcie na nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Ode dni Gabaa grzeszyłeś, Izraelu! tam się ostali, nie zachwyciła ich w Gabaa bitwa przeciwko synom nieprawości podniesiona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Przetoż ich pokarzę według upodobania mego; bo się zbiorą na nich narody, aby byli karani dla dwojakich nieprawości swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Bo Efraim jest jako jałowica wyuczona, kocha się w młóceniu, chociażem Ja następował na cudny kark jej, abym do jazdy używał Efraima, Juda aby orał, a Jakób aby włóczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'I mówiłem: Siejcie sobie ku sprawiedliwości; żnijcie ku miłosierdziu, orzcie sobie nowinę; bo czas jest szukać Pana, aż przyjdzie, i spuści na was sprawiedliwość jako deszcz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Aleście orali niepobożność, żęliście nieprawość, jedliście owoc kłamstwa; albowiem ufasz w drodze swej i w mnóstwie mocarzów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Dlategoż powstanie rozruch między ludem twoim, a wszystkie zamki twoje poburzone będą, tak jako poburzył Salman Bet Arbel w dzień bitwy; matki z synami roztrącone będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Oto tak wam uczyni Betel dla wielkiej złości waszej; król Izraelski na świtaniu do szczętu zgładzony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Gdy Izrael był dziecięciem, miłowałem go, a z Egiptu wezwałem syna mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Wzywali ich prorocy, ale oni tem więcej uchodzili od oblicza ich, Baalom ofiary czynili, a bałwanom rytym kadzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Chociażem Ja Efraima na nogi stawiał, przecie on ich brał na ramiona swoje; a nie chcieli znać, żem Ja ich leczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Powrozami ludzkiemi pociągałem ich, powrozami miłości, a byłem im jako którzy odejmują jarzmo z czeluści ich, i dawałem im pokarm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Nie wrócić się do ziemi Egipskiej: ale Assur będzie królem jego, przeto że się nie chcieli nawrócić do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Nadto miecz będzie trwać w miastach jego, i skazi zawory jego, a pożre ich dla rady ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Bo lud mój udał się na to, aby się odwracał odemnie; a chociaż go wołają do Najwyższego, przecież go nikt nie wywyższa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Jakożbym cię podał, o Efraimie? jakożbym cię podał, o Izraelu? jakożbym cię podał jako Adamę i położył jako Seboim? Ale się obróciło we mnie serce moje, nawet i wnętrzności litości poruszyły się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Nie wykonam gniewu zapalczywości mojej, nie udam się na skażenie Efraima; bom Ja Bóg, a nie człowiek, w pośrodku ciebie święty, i nie przyjdę przeciwko miastu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Pójdą za Panem, który jako lew będzie ryczał; on zaiste tak ryczeć będzie, że ze strachem przybieżą synowie od morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Ze strachem przybieżą jako ptaki z Egiptu, i jako gołębica z ziemi Assyryjskiej, i posadzę ich w domach ich, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Efraimczycy mię ogarnęli kłamstwem, a dom Izraelski zdradą, gdy jeszcze Juda panował z Bogiem, a z świętymi wierny był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efraim się karmi wiatrem, a goni wiatr wschodni, przez cały dzień mnoży kłamstwo i spustoszenie; bo przymierze z Assyryjczykami stanowi, i oliwę do Egiptu wynosi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Ma też Pan poswarek z Judą, a nawiedzi Jakóba według dróg jego, według spraw jego odda mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Jeszcze w żywocie za piętę dzierżył brata swego, a mocą swoją mężnie sobie poczynał z Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Mężnie, mówię, sobie poczynał z Aniołem, a przemógł; płakał i prosił go; w Betelu go znalazł, i tam mówił z nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Toć jest Pan, Bóg zastępów, Pan jest pamiętne imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Przetoż się ty do Boga twego nawróć, miłosierdzia i sądu przestrzegaj, a oczekiwaj zawżdy na Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Kupcem jest, w którego ręku są szale fałszywe; gwałt umiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'I mówi Efraim: Zaiste zbogaciłem się, nabyłem sobie bogactw we wszystkich pracach moich, nie znajdą przy mnie nieprawości, coby grzechem była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Alem Ja jest Panem, Bogiem twoim, od wyjścia z ziemi Egipskiej; jeszczeć dopuszczę mieszkać w namiotach, jako za dni uroczystych świąt;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'A mówiąc przez proroków widzenia wiele pokazywać będę, a przez proroków podobieństwa podawać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Czyli tylko w Galaad była nieprawość i marność? I w Galgalu woły ofiarują, owszem, i ołtarzów ich pełno jako gromad na zagonach pól moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Tamci był uciekł Jakób z krainy Syryjskiej, gdzie służył Izrael za żonę, i za żonę strzegł stada;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Ale tu przez proroka Pan Izraela przywiódł z Egiptu, i przez proroka był strzeżony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Lecz Efraim Pana pobudził do gniewu gorzkiego; przetoż się nań wyleje krew jego, a pohańbienie jego odda mu Pan jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Gdy mawiał Efraim, strach bywał, bo był wywyższony w Izraelu; ale gdy zgrzeszył przy Baalu, tedy umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'A teraz jeszcze przyczyniają grzechu; bo sobie czynią i leją z srebra swego według przemysłu swego straszne bałwany, co wszystko tylko jest robotą rzemieślnika, o których jednak sami mówią: Ludzie, którzy chcą ofiarować, niech całują cielce,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, '(Przetoż się staną jako obłok poranny, a jako rosa poranna przechodząca, i jako plewy od wichru porwane z bojewiska, i jako dym z komina.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Gdyżem Ja jest Pan, Bóg twój, od wyjścia z ziemi Egipskiej; a Boga oprócz mnie nie poznałeś, i niemasz zbawiciela oprócz mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Jam cię poznał na puszczy w ziemi bardzo suchej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Dobremi pastwiskami swemi nasyceni są; ale gdy się nasycili, podniosło się serce ich; przetoż mię zapomnieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Dlatego będę im jako lew srogi, jako lampart przy drodze będę czyhał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Zabierzę im jako niedźwiedż osierociały, a roztargam zawarcie serca ich, i pożrę ich tam jako lew, jako zwierz dziki szarpając ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Zginienie twoje z ciebie, o Izraelu! ale ze mnie wspomożenie twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Gdzież jest król twój? gdzież jest? Niech cię zachowa we wszystkich miastach twoich! I sędziowie twoi, o którycheś mówił: Daj mi króla i książąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Dałem ci tedy króla w zapalczywości mojej, alem go odjął w zagniewaniu mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Związana jest nieprawość Efraimowa, schowany jest grzech jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Boleści rodzącej ogarną go; on synem niemądrym, bo inaczej nie zostawałby tak długo w żywocie matki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Z ręki grobu wybawię ich, od śmierci wykupię ich. O śmierci! będę śmiercią twoją; o grobie! będę skażeniem twojem; żałość skryta będzie od oczów moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Bo on między braćmi owoc przyniesie; pierwej jednak przyjdzie wiatr ze wschodu, wiatr Pański od puszczy występujący, i wysuszy źródło jego, wysuszy i zdrój jego; onci rozchwyci skarby wszelkiego naczynia pożądanego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samaryja będzie spustoszona, przeto, że się sprzeciwiła Bogu swemu; od miecza upadną, maluczcy jej roztrąceni będą, a brzemienne jej rozcięte będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'O Izraelu! nawróć się cale do Pana, Boga swego; albowiemeś upadł dla nieprawości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Weźmijcie z sobą słowa, i nawróćcie się do Pana, mówcie do niego: Odpuść wszystkę nieprawość, a daj to, co jest dobrego, tedyż oddamy cielce warg naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Assur nie wzybawi nas, na koniach jeździć nie będziemy, i nie rzeczemy więcej robocie rąk naszych: Wyście bogowie nasi; bo w tobie sierotka znajduje miłosierdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Uzdrowię odwrócenie ich, a rozmiłuję się w nich dobrowolnie; bo się odwróci zapalczywość moja od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Będę Izraelowi jako rosa, że się rozkwitnie jako lilija, a zapuści korzenie swe jako Liban.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Rozrosną się gałęzie jego, a ozdoba jego będzie jako oliwne drzewo, a woń jego jako Libańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Nawrócą się, aby siedzieli pod cieniem jego, ożyją jako zboże, i puszczą się jako winna macica, której pamiątka będzie jako wino Libańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Efraimie! cóż mi już do bałwanów? Ja cię wysłucham, i wejrzę na cię; Jam jest jako jodła zielona, ze mnie się owoc twój znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Kto mądry, niech to zrozumie, a kto roztropny, niech to pozna; bo drogi Pańskie są proste, a sprawiedliwi po nich chodzić będą, ale przestępcy na nich upadną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Słowo Pańskie, które się stało do Joela syna Patuelowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Słuchajcie tego starcy, a bierzcie w uszy wszyscy obywatele tej ziemi! Izali się to stało za dni waszych, albo za dni ojców waszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Powiadajcie o tem synom waszym, a synowie wasi synom swoim, a synowie ich rodzajowi potomnemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Co zostało po gąsienicach, pojadła szarańcza, a co zostało po szarańczy, pojadł chrząszcz, a co zostało po chrząszczu, pojadł czerw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Ocućcie się pijani a płaczcie, i narzekajcie wszyscy, którzy pijecie wino, dla moszczu; bo wydarty jest od ust waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Albowiem naród przyciągnął do ziemi mojej mocny a niezliczony; zęby jego zęby lwie, a trzonowe zęby jako lwa srogiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Winną macicę moję podał na spustoszenie, a figowe drzewo moje na obłupienie; w szcząt je obnażył i porzucił, tak, że zbielały gałęzie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Narzekaj, jako panna przepasana worem nad mężem młodości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Odjęta jest śniedna i mokra ofiara od domu Pańskiego; płaczą kapłani, słudzy Pańscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Spustoszone jest pole, i smuci się ziemia, przeto, że popsowano zboże; wysechł moszcz, oliwa zginęła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Wstydzą się oracze, narzekają winiarze dla pszenicy i dla jęczmienia; bo zginęło żniwo polne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Winna macica uschła, a figowe drzewo uwiędło; drzewo granatowe i palma, i jabłoń, i wszystkie drzewa polne poschły, i wesele zginęło od synów ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Przepaszcie się, a płaczcie, o kapłani! narzekajcie słudzy ołtarza; wnijdźcie a legajcie w nocy w worach, słudzy Boga mojego! bo zawściągniona jest od domu Boga waszego ofiara śniedna i ofiara mokra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Poświęćcie post, zwołajcie zgromadzenia, zbierzcie starców i wszystkich obywateli ziemi do domu Pana, Boga waszego, i wołajcie do Pana:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Ach biada na ten dzień! bo bliski jest dzień Pański, a przychodzi jako spustoszenie od Wszechmocnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Izali przed oczyma naszemi nie zginęła żywność, a z domu Boga naszego radość i wesele?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Pogniły ziarna pod skibami swemi, spustoszone są gumna, zburzone są szpichlerze; bo wyschło zboże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Czemu wzdycha bydło? Błąkają się stada wołów, że nie mają pastwisk, nawet i trzody owiec wyginęły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Do ciebie wołam, o Panie! bo ogień pożarł pastwiska na puszczy a płomień popalił wszystkie drzewa polne;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Także i zwierzęta polne ryczą do ciebie, przeto, że wyschły strumienie wód, a ogień pożarł pastwiska na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Trąbcie w trąbę na Syonie, a krzyczcie na świętej górze mojej! niechaj zadrżą wszyscy obywatele ziemi; bo przychodzi dzień Pański, bo już bliski jest;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Dzień ciemności i mroku, dzień obłoku i chmury, jako ranna zorza rozciągniona po górach; lud wielki a mocny, któremu równego nie było od wieku, i nie będzie po nim nigdy aż do lat rodzaju i rodzaju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Przed obliczem jako ogień pożerający, a za nim płomień pałający; ta ziemia jest przed nim jako ogród Eden, ale po nim będzie pustynią pustą i nie ujdzie nikt przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Kształt ich jest jako kształt koni, a tak pobieżą jako jezdni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Po wierzchu gór skakać będą jako grzmot wozów, a jako szum płomienia ognistego pożerającego ściernisko, jako lud możny uszykowany do bitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Ulękną się narody przed obliczem jego, wszystkie twarze ich jako garniec poczernieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Pobieżą jako mocarze, a wbieżą na mury jako mężowie waleczni; każdy z nich drogą swoją pójdzie, a nie ustąpią z ścieżek swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Jeden drugiego nie ściśnie, każdy drogą swoją pójdzie; a choć i na miecz upadną, nie będą zranieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Po mieście chodzić będą, po murze biegać, na domy wstąpią, a oknami wlezą jako złodziej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Przed obliczem jego ziemia zadrży, niebiosa się poruszą, słońce i miesiąc się zaćmi, a gwiazdy zawściągną jasność swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'A Pan wyda głos swój przed wojskiem swojem, przeto, że bardzo wielki będzie obóz jego, przeto, że mocny ten, co wykona słowo jego; wielki bowiem dzień Pański będzie i straszliwy bardzo, i któż go zniesie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'A przetoż jeszcze i teraz mówi Pan: Nawróćcie się do mnie samego całem sercem swojem, i w poście i w płaczu i w kwileniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Rozedrzyjcie serce wasze a nie szaty wasze, i nawróćcie się do Pana, Boga waszego; boć on jest łaskawy i miłosierny, nierychły ku gniewu, a hojny w miłosierdziu, i żałujący złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Któż wie, nie obrócili się, a nie będzieli mu żal, i nie zostawili po sobie błogosławieństwa na śniedną i mokrą ofiarę Panu, Bogu waszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Trąbcie w trąbę na Syonie, poświęćcie post, zwołajcie zgromadzenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Zgromadźcie lud, poświęćcie zgromadzenie, zbierzcie starców, znieście maluczkie i ssące piersi; niech wynijdzie oblubieniec z łożnicy swojej, a oblubienica z pokoju swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Kapłani, słudzy Pańscy, między przysionkiem a ołtarzem niech płaczą i mówią: Przepuść, Panie! ludowi twemu, a nie daj dziedzictwa swego na pohańbienie, aby nad nimi poganie panować mieli. Przeczżeby mówiono między narodami: Gdzież jest Bóg ich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'I zapali się Pan miłością ku ziemi swojej, a zmiłuje się nad ludem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'I ozwie się Pan, a rzecze do ludu swego: Oto Ja poślę wam zboże, i moszcz, i oliwę, a będziecie niemi nasyceni, i nie podam was więcej na pohańbienie między pogan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Bo północne wojsko oddalę od was, a zapędzę je do ziemi suchej i spustoszonej; przedni huf jego obróci się ku morzu wschodniemu, a koniec jego ku morzu ostatecznemu, i wynijdzie z niego smród i zgniłość, choć sobie hardzie poczyna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Nie bój się, ziemio! wesel się a raduj się; bo Pan wielkie rzeczy uczyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Nie bójcie się zwierzęta pól moich; boć wzrosło pastwisko na pustyni, a drzewa przyniosą owoce swoje, figowe drzewo i macica winna wydadzą moc swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'I wy, synowie Syońscy! weselcie się i radujcie się w Panu, Bogu waszym; bo wam da deszcz wczesny, a ześle wam deszcz obfity w jesieni i na wiosnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'I będą gumna zbożem napełnione, a prasy opływać będą moszczem i oliwą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'A tak nagrodzę wam lata, które zjadła szarańcza, czerw, chrząszcze i gąsienice, wojsko moje wielkie, którem posyłał na was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Tedy jedząc jeść będziecie, a nasyceni będąc chwalić będziecie imię Pana, Boga swego, który uczynił z wami dziwne rzeczy, i nie będzie pohańbiony lud mój na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'I dowiecie się, żem Ja jest w pośród Izraela, a żem Ja Panem, Bogiem waszym, a że niemasz inszego; boć nie będzie pohańbiony lud mój na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'A potem wyleję Ducha mego na wszelkie ciało, a prorokować będą synowie wasi i córki wasze; starcom waszym sny się śnić będą, a młodzieńcy wasi widzenia widzieć będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'Nawet i na sługi i na służebnice wyleję w one dni Ducha mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'I dam cuda na niebie i na ziemi, krew i ogień i słupy dymowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'Słońce obróci się w ciemność, a miesiąc w krew, pierwej niż dzień Pański wielki a straszny przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'Wszakże stanie się, że ktobykolwiek wzywał imienia Pańskiego, wybawiony będzie; bo na górze Syon i w Jeruzalemie będzie wybawienie, jako rzekł Pan, to jest w ostatkach, które Pan powoła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Bo oto w one dni i w on czas, gdy nawrócę pojmany lud Judzki i Jeruzalemski,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Zgromadzę też wszystkie narody, i sprowadzę je na dolinę Jozafat, i będę się tam z nimi sądził o lud swój, i o dziedzictwo swoje Izraelskie, które rozproszyli między pogan, i ziemię moję rozdzielili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'O lud też mój los miotali, a dawali młodzieniaszka za wszetecznicę, a dzieweczkę sprzedawali za wino, aby pili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Ale wy cóż przeciwko mnie macie, o Tyryjczycy i Sydończycy i wszystkie granice Filistyńskie? Izali wy mnie nagrodę czynicie? Jeźli mi tak nagrodę czynicie, snadnieć i prędko i Ja obrócę nagrodę waszę na głowę waszę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Którzy srebro moje i złoto moje zabieracie, a klejnoty moje wyborne wnosicie do kościołów swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'A synów Judzkich i synów Jeruzalemskich sprzedawacie synom Jawanowym, abyście ich oddalili od granic ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'Oto Ja wzbudzę ich z tego miejsca, na któreście ich zaprzedali, a obrócę nagrodę waszę na głowę waszę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'I zaprzedam synów waszych i córki wasze w ręce synów Judzkich, i zaprzedadzą ich Sebejcykom do narodu dalekiego; bo Pan mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Obwołajcie to między narodami, ogłoście wojnę, pobudźcie mocarzów, niech przyciągną a dadzą się nająć wszyscy mężowie waleczni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Przekujcie lemiesze wasze na miecze, a kosy wasze na oszczepy; kto słaby, niech rzecze: Mocnym ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Zgromadźcie się, a zbieżcie się wszystkie narody okoliczne, zbierzcie się; spraw to, o Panie! że tam zstąpią mocarze twoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Niech się ocucą i przyciągną te narody na dolinę Jozafat; bo tam siedzieć będę, abym sądził wszystkie narody okoliczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Zapuśćciesz sierp, bo się dostało żniwo; pójdźcie, zstąpcie, bo pełna jest prasa; opływają kadzi, bo wiele jest złości ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Gromady, gromady leżeć będą w dolinie posieczenia; bo bliski jest dzień Pański w dolinie posieczenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Słońce i miesiąc zaćmią się, a gwiazdy stracą jasność swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'Nadto Pan z Syonu zaryczy, a z Jeruzalemu wyda głos swój, tak, że zadrżą niebiosa i ziemia; Ale Pan jest ucieczką ludu swego i siłą synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'I dowiecie się, żem Ja Pan, Bóg wasz, mieszkający na Syonie, górze świętobliwości swojej; a tak Jeruzalem będzie święte, a obcy nie przejdą więcej przez nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'I stanie się dnia onego, że góry kropić będą moszczem a pagórki opływać mlekiem, i wszystkie strumienie Judzkie będą pełne wody, a z domu Pańskiego wynijdzie źródło, które obleje dolinę Syttym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Egipt przyjdzie na spustoszenie, a ziemia Edomska w straszną się pustynię obróci dla gwałtu synom Judzkim uczynionego; bo wylewali krew niewinną w ziemi ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Ale Juda na wieki trwać będzie, a Jeruzalem od narodu do narodu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'I oczyszczę tych, którychem krwi nie oczyścił; a Pan mieszka na Syonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Słowa Amosa, który był między pasterzami z Tekua, które widział o Izraelu za dni Uzyjasza, króla Judzkiego, i za dni Jeroboama, syna Joazowego, króla Izraelskiego, dwa lata przed trzęsieniem ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'i rzekł: Zaryczy Pan z Syonu, z Jeruzalemu wyda głos swój;i będą płakały mieszkania pasterzy, a wyschną pola najwyborniejsze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Tak mówi Pan: Dla trzech występków Damaszku, owszem, dla czterech, nie przepuszczę mu, przeto, że młócili wozami żelaznemi Galaada;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Ale poślę ogień na dom Hazaela, który pożre pałace Benadadowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Połamię też zaworę w Damaszku, a wykorzenię obywatela z doliny Awen, i tego, który trzyma sceptr z domu Heden; i pójdzie w niewolę lud Syryjski do Kir, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Tak mówi Pan: Dla trzech występków Gazy, owszem, dla czterech, nie przepuszczę im, przeto, że ich pojmawszy, w więzienie wieczne podawali Edomczykom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Ale poślę ogień na mur Gazy, który pożre pałace jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Wykorzenię też obywatela z Azotu, i tego, który trzyma sceptr z Aszkalonu, i obrócę rękę moję przeciwko Akkaronowi, że zginie ostatek Filistynów, mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Tak mówi Pan: Dla trzech występków Tyru, owszem, dla czterech, nie przepuszczę mu, przeto, że ich w więzienie wieczne podali Edomczykom, a nie wspomnieli na przymierze braterskie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Ale poślę ogień na mur Tyrski, który pożre pałace jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Tak mówi Pan: Dla trzech występków Edoma, owszem, dla czterech, nie przepuszczę mu, przeto, że zepsowawszy w sobie wszelaką litość swoję prześladuje mieczem brata swego, a gniewem swym ustawicznie pała, owszem, zapalczywość jego rozsila się bez przestania;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Ale poślę ogień na Teman, i pożre pałace w Bocra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Tak mówi Pan: Dla trzech występków synów Amonowych, owszem, dla czterech, nie przepuszczę mu, przeto, iż rozcinali brzemienne w Galaad, tylko aby rozszerzali granice swoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Ale rozniecę ogień na murze Rabby, który pożre pałace jego z krzykiem w dzień wojny, i z wichrem w dzień niepogody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'I pójdzie król ich w niewolę, on i książęta jego z nim, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Tak mówi Pan: Dla trzech występków Moaba, owszem, dla czterech, nie przepuszczę mu, przeto, iż spalił kości króla Edomskiego na popiół;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Ale poślę ogień na Moaba, który pożre pałace Karyjot; i umrze Moab w huku, w krzyku i w głosie trąby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'I wygładzę sędziów z pośrodku jego, i wszystkich książąt jego pobiję z nim, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Tak mówi Pan: Dla trzech występków Judzkich, owszem, dla czterech, nie przepuszczę mu, przeto, że odrzucają zakon Pański, i ustaw jego nie przestrzegają, a dadzą się zwodzić kłamstwom swoim, których naśladowali ojcowie ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Ale poślę ogień na Judę, który pożre pałace Jeruzalemskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Tak mówi Pan: Dla trzech występków Izraelskich, owszem, dla czterech, nie przepuszczę mu, przeto, że sprawiedliwego za pieniądze sprzedawają, a ubogiego za parę trzewików;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Którzy usiłują, aby na proch potarli głowy ubogich, a drogę pokornych podwracają; nadto syn i ojciec jego wchodzą do jednejże dziewki, aby splugawili imię świętobliwości mojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'I na szatach zastawionych kłaniają się przy każdym ołtarzu, a wino tych, co podpadli pod kaźń, piją w domu bogów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Chociażem Ja wytracił Amorejczyka od oblicza ich, którego wysokość była jako wysokość cedrów, aczkolwiek warownie stał jako dąb, wszakżem skaził owoc jego z wierzchu, a korzenie jego ze spodku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'A was wywiodłem z ziemi Egipskiej, i prowadziłem was po puszczy czterdzieści lat, żebyście posiedli ziemię Amorejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Nadto wzbudzałem z synów waszych proroków, a z młodzieńców waszych Nazarejczyków; izali nie tak jest, o synowie Izraelowi? mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Aleście wy napawali Nazarejczyków winem, a prorokom zakazywaliście, mówiąc: Nie prorokujcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Oto Ja ścisnę ziemię waszę, tak jako ciśnie wóz napełniony snopami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'I zginie ucieczka od prędkiego, a mocarz nie pokrzepi mocy swojej, i duży nie wybawi duszy swojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'A ten, który trzyma łuk, nie ostoi się, i prędki na nogi swe nie uciecze, a ten, który jeździ na koniu, nie zachowa duszy swej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Ale i rycerz serca zmężałego między mocarzami nago uciecze w on dzień, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Słuchajcie słowa tego, które mówi Pan przeciwko wam, synowie Izraelscy! przeciwko wszystkiemu rodzajowi, którym wywiódł z ziemi Egipskiej, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Tylkom was samych poznał ze wszystkich rodzajów ziemi; przetoż was nawiedzę dla wszystkich nieprawości waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Izali dwa społem pójdą nie zgodziwszy się?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Izali zaryczy lew w lesie, gdyby nie miał łupu? Izali wyda lwię głos swój z jaskini swojej, gdyby łapać nie miało?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Izali ptak wpadnie w sidło na ziemi, gdyby sidła nie było? Izali będzie podniesione sidło z ziemi, gdyby nic nie uwięzło?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Izali się ludzie nie lękają, gdy trąba w mieście zabrzmi? izali jest w mieście co złego, którego by Pan nie uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Zaiste nic nie czyni panujący Pan, chyba żeby objawił tajemnice swoję sługom swoim, prorokom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Lew ryczy, któżby się nie bał? Panujący Pan mówi, któżby nie prorokował?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Obwołajcie w pałacach w Azocie i w pałacach ziemi Egipskiej, a mówcie: Zbierzcie się na góry Samaryi, a obaczcie wielkie zamięszania w pośrodku jej, i ucisk cierpiących w niej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'I że nie umieją czynić, co jest prawego, mówi Pan, zbierając na pałacach swoich skarby z zdzierstwa i z łupiestwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Przetoż tak mówi panujący Pan: Oto nieprzyjaciel około tej ziemi, a ten odejmie od ciebie siłę twoję, i rozchwycone będą pałace twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Tak mówi Pan: Jako wyrywa pasterz z paszczęki lwiej dwa gnaty albo kęs ucha, tak wyrwani będą synowie Izraelscy, którzy mieszkają w Samaryi na stronie łoża, i na stronie pościeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Słuchajcie a oświadczajcie w domu Jakóbowym, mówi panujący Pan, Bóg zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Bo dnia onego, którego Izraela nawiedzę dla przestępstwa jego, nawiedzę też ołtarze w Betel, i odcięte będą rogi ołtarza, tak, że na ziemię upadną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'I uderzę dom zimy o dom lata, a zginą domy z kości słoniowych, a domy zacne koniec wezmą, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Słuchajcie słowa tego, o krowy Basańskie! któreście na górach Samaryi, które uciskacie nędzników a niszczycie ubogich, które mówicie panom ich: Przynieście, abyśmy piły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Przysiągł panujący Pan przez świętobliwość swoję, iż oto dni idą na was, których nieprzyjaciel weźmie was na haki, a potomki wasze na wędy rybackie, i wyjdziecie przerwami, każda tak jako stoi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'I będziecie rozrzucać cokolwiek było w pałacach waszych, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Idźcież do Betel a bądzcie tułaczami w Galgal; rozmnóżcie przestępstwa, a przynoście na każdy poranek ofiary wasze, i trzeciego roku dziesięciny wasze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'A paląc ofiarę chwały z kwaszonych rzeczy, obwołajcie ofiary dobrowolne, i rozgłoście, ponieważ się wam tak podoba, o synowie Izraelscy! mówi panujący Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'A chociażem Ja wam dał czystość zębów we wszystkich miastach waszych, to jest, niedostatek chleba po wszystkich miejscach waszych, wszakżeście się nie nawrócili do mnie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Jam też zahamował od was deszcz, gdy jeszcze były trzy miesięce do żniwa, a spuściłem deszcz na jedne miasto, a na drugiem miasto nie spuścił; jedna dziedzina była deszczem odwilżona, a druga dziedzina, na którą deszcz nie padał, uschła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'I chodziły dwa i trzy miasta do jednego miasta, aby piły wodę, a nie mogły się napić; a wszakżeście się nie nawrócili do mnie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Uderzyłem was suszą i rdzą; obfitość, którą przynosiły ogrody wasze, i winnice wasze, i figowe sady wasze, i oliwnice wasze, gąsienice pożarły, a wszakżeście się nie nawrócili do mnie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Posłałem na was mór, tak jako na Egipt, pobiłem mieczem młodzieńców waszych, w pojmaniem podał konie wasze, i sprawiłem, że smród wojsk waszych występował w nozdrza wasze; a wszakżeście się nie nawrócili do mnie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Wywróciłem was, jako Bóg wywrócił Sodomę i Gomorę, tak, żeście byli jako głownia wyrwana z ognia; a wszakżeście się nie nawrócili do mnie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Przetoż tak ci uczynię, o Izraelu! a iż ci tak uczynić chcę, bądźże gotowym na zabieżenie Bogu swemu, o Izraelu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Albowiem oto on jest, który kształtuje góry, a tworzy wiatry, i który oznajmuje człowiekowi, jaka jest myśl jego; on z rannej zorzy ciemność czyni, a depcze wysokości ziemi; Pan Bóg zastępów jest imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Słuchajcie słowa tego, które Ja wydaję przeciwko wam, to jest narzekania, o domie Izraelski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Upadnie, a nie powstanie więcej panna Izraelska; opuszczona będzie w ziemi swej, a nie będzie, ktoby ją podniósł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Bo tak mówi panujący Pan: W mieście, z którego wychodziło tysiąc, zostanie sto, a w tem, z którego wychodziło sto, zostanie dziesięć domowi Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Bo tak mówi Pan domowi Izraelskiemu: Szukajcie mię, a żyć będziecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'A nie szukajcie Betela, ani chodźcie do Galgal, i do Beerseby nie udawajcie się,; bo Galgal w niewolę zawiedzione będzie, a Betel się wniwecz obróci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Szukajcie Pana, a żyć będziecie, by snać domu Józefowego nie przeniknął jako ogień, i nie pochłonął Betel, a nie byłby, ktoby ugasił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Którzy obracacie sąd w piołun, a sprawiedliwość na ziemi opuszczacie: Szukajcie, mówię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Tego, który uczynił Baby na niebie i Oriona, który cień śmierci w poranek odmienia i dzień w ciemności nocne; który przywołuje wody morskie, a wylewa je na oblicze ziemi, Pan jest imię jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Który pokrzepia słabego przeciwko mocarzowi, tak że ten osłabiały do twierdzy uchodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Mają w nienawiści tego, który ich w bramie karze; a tym, co mówi rzeczy dobre, brzydzą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Przetoż, iż uciskacie ubogiego, a brzemię zboża bierzecie od niego, domuweście wprawdzie z ciosanego kamienia nabudowali, ale nie będziecie w nich mieszkać; winnic rozkosznych nasadziliście, ale wina z nich pić nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Bo wiem o wielkich przestępstwach waszych, i srogich grzechach waszych, że ciemiężycie sprawiedliwego, biorąc poczty, a ubogich sprawy w bramie podwracacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Przetoż roztropny czasu onego milczeć musi; bo czas zły jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Szukajcie dobrego a nie złego, abyście żyli; a będzie tak Pan Bóg zastępów z wami, jako mówicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Miejcie w nienawiści złe, a miłujcie dobre, a sąd postanówcie w bramie; owa się snać Pan, Bóg zastępów, nad ostatkiem Józefa zmiłuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Przetoż tak mówi panujący Pan, Bóg zastępów: Po wszystkich ulicach będzie narzekanie, a po wszystkich stronach zakrzykną: Biada, biada! i zawołają oracza do płaczu i do kwilenia z tymi, którzy narzekać umieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Owszem, i po wszystkich winnicach będzie narzekanie, gdy przejdę przez pośrodek ciebie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Biada tym, którzy żądają dnia Pańskiego! cóż wam po tym dniu Pańskim, ponieważ jest ciemnością, a nie światłością?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Jako gdyby kto uciekał przede lwem, a zabieżał mu niedźwiedź; albo gdyby wszedł do domu, a podparł się ręką swą na ścianie, ukąsiłby go wąż.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Izali dzień Pański nie jest dzień ciemności, a nie światłości, w którym niemasz jasności, ale chmura?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Mam w nienawiści i odrzuciłem uroczyste święta wasze, ani się kocham w ofiarach zgromadzenia waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Bo jeźli mi ofiarować będziecie całopalenia, i śniedne ofiary wasze, nie przyjmę ich, a na spokojne ofiary tłustych bydeł waszych nie wejrzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Odejmij odemnie wrzask pieśni swoich; bo ich i dźwięku harf waszych słuchać nie chcę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Ale sąd nawalnie popłynie, jako woda, a sprawiedliwość jako strumień gwałtowny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Izaliście mi ofiary i dar ofiarowali na puszczy przez czterdzieści lat, domie Izraelski?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Owszem, nosiliście namiot Molocha waszego i Kijuna, obrazy wasze, gwiazdę bogów waszych, którycheście sobie naczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Przetoż was zaprowadzę za Damaszek, mówi Pan, Bóg zastępów imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Biada bezpiecznym na Syonie, i ufającym w górze Samaryjskiej! którzy są sławni mimo innych u tych narodów, do których się schodzi dom Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Zajdźcie do Chalny, i idźcie z onąd do Emat wielkiego, a zstąpcie do Giet Filistyńskiego, a obaczcie, sąli które królestwa lepsze niżeli te, i jeżeli szersza jest granica ich, niż granica wasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, '(Biada wam) którzy mniemacie, że daleki jest dzień zły, a przystawiacie stolicę drapiestwa!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Którzy sypiacie na łożach słoniowych, a rozciągacie się na pościelach waszych; którzy jadacie barany z trzody, a cielce tuczone ze stani;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Którzy śpiewacie przy lutni, wymyślając sobie naczynia muzyczne, jako Dawid;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Którzy pijacie wino czaszami, a drogiemi się maściami namazujecie, i nie bolejecie nad utrapieniem Józefowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Przetoż teraz pójdą w niewolę na czele pojmanych; a tak odstąpi biesiada od zbyteczników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Przysiągł panujący Pan sam przez się, mówi Pan, Bóg zastępów: Zbrzydziłem sobie pychę Jakóbową i pałace jego mam w nienawiści; przetoż podam miasto i wszystko, co w niem jest, nieprzyjacielowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'A zostanieli dziesięć osób w domu jednym, i ci pomrą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'I weźmie każdego z nich stryj jego, i spali go, aby wyniósł kości z domu, a rzecze temu, który jest w gmachach domu: Jestże kto więcej z tobą? I odpowie: Niemasz. Tedy rzecze: Milcz; przeto, że nie wspominali imienia Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Bo oto Pan rozkaże, i uderzy na dom wielki rozstąpieniem, a na dom mniejszy rozpadlinami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Izali konie mogą biegać po skale? Izali tam wołami orać mogą? Boście obrócili sąd w truciznę, a owoc sprawiedliwości w piołun;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Biada wam! którzy się weselicie, a niemasz z czego, mówiąc: Izaliśmy sobie nie naszą mocą wzięli rogi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Ale oto Ja wzbudzę przeciwko wam, o domie Izraelski! mówi Pan, Bóg zastępów, naród, który was uciśnie od wejścia do Emat aż do strumienia pustyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'To mi ukazał panujący Pan. Oto tworzył szarańczę, gdy najpierwej począł odrastać potraw, gdy oto potraw był po pokoszeniu królewskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'A gdy zjadły trawę ziemi, rzekłem: Panujący Panie! sfolguj proszę; bo któż zostanie Jakóbowi, gdyż maluczki jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'I żałował Pan tego; a rzekł Pan: Nie stanie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Tedy mi ukazał panujący Pan, a oto panujący Pan wołał, że sprawę swoję powiedzie ogniem, a spaliwszy przepaść wielką, spalił i część królestwa Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Tedym rzekł: Panujący Panie! przestań proszę; bo któż zostanie Jakóbowi, gdyż maluczki jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'I żałował Pan tego, a rzekł panujący Pan: I toć się nie stanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Potem ukazał mi, a oto Pan stał na murze według sznuru zbudowanym, w którego ręku było prawidło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'I rzekł Pan do mnie: Cóż widzisz Amosie? I rzekłem: Prawidło. Tedy rzekł Pan: Oto Ja położę prawidło w pośrodku ludu mego Izraelskiego, a już mu więcej nie będę przeglądał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Bo wyżyny Izaakowe spustoszone będą, a świątnice Izraelskie zburzone będą, gdy powstanę przeciwko domowi Jeroboamowemu z mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Tedy posłał Amazyjasz, kapłan Betelski, do Jeroboama, króla Izraelskiego, mówiąc: Sprzysiągł się przeciwko tobie w pośrodku domu Izraelskiego, tak, iż ziemia nie może znieść wszystkich słów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Bo tak mówi Amos: Jeroboam od miecza umrze, a Izrael zapewne do więzienia z ziemi swojej zaprowadzony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Potem rzekł Amazyjasz do Amosa: O widzący! uchodź, uciekaj do ziemi Judzkiej, a jedz tam chleb, i tam prorokuj;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Ale w Betelu więcej nie prorokuj; bo to jest świątnica królewska, i dom królewski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Tedy odpowiedział i rzekł do Amazyjasza: Nie byłem ja prorokiem, nawet ani synem prorockim; alem był skotarzem, a zbierałem figi leśne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Ale mię Pan wziął, gdym chodził za bydłem, i rzekł do mnie Pan: Idź, prorokuj ludowi memu Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Teraz tedy słuchaj słowa Pańskiego. Ty mówisz: Nie prorokuj w Izraelu, i nie każ w domu Izaakowym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Przetoż tak mówi Pan: Żona twoja w mieście nierząd płodzić będzie, a synowie twoi i córki twoje od miecza polegną, a ziemia twoja sznurem będzie podzielona, a ty w ziemi splugawionej umrzesz; lecz Izrael zapewne zaprowadzony będzie do więzienia z ziemi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'To mi jeszcze ukazał panujący Pan, oto był kosz letniego owocu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Tedy rzekł: Cóż widzisz Amosie? I rzekłem: Kosz letniego owocu. Znowu rzekł Pan do mnie: Przyszedł koniec ludowi memu Izraelskiemu, nie będę mu już więcej przeglądał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Tedy się obrócą w kwilenie pieśni kościelne dnia onego, mówi panujący Pan, mnóstwa trupów na każde miejsce po cichu narzucają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Słuchajcież tego, którzy pożeracie ubogiego, abyście wygubili chudziny z ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'I mawiacie: Kiedyż przeminie nów miesiąca, abyśmy sprzedawali zboże? i sabat, abyśmy otworzyli spichlerze? abyśmy umniejszyli miary efa, a podwyższyli wagi, a szale zdradliwie sfałszowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Kupując ubogich za pieniądze, a chudzinę za parę trzewików; nadto abyśmy odmieciny zbóż sprzedawali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Przysiągł Pan przez zacność Jakóbową, że nie zapomnę na wieki wszystkich spraw ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Izali by się i ziemia nad tem nie poruszyła, i nie płakałby każdy, kto mieszka na niej? i owszem, wzbierze wszystka jako rzeka, i porwana i zatopiona będzie jako rzeką Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'A dnia onego, mówi panujący Pan, sprawię, że słońce zajdzie o południu, i przywiodę ciemność na ziemię w dzień jasny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'I obrócę w płacz święta wasze, a wszystkie pieśni wasze w narzekanie, i sprawię to, że będzie na wszystkich biodrach wór, i na każdej głowie obłysienie; i będzie w tej ziemi kwilenie, jako nad jednorocznym, a ostateczne rzeczy jej jako dzień gorz kości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Oto dni przychodzą, mówi panujący Pan, że poślę głód na ziemię, nie głód chleba, ani pragnienie wody, ale słuchania słów Pańskich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Tak, że się tułać będą od morza aż do morza, i od północy aż na wschód biegać będą, szukając słowa Pańskiego, wszakże nie znajdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Dnia onego pomdleją panienki piękne, nawet i młodzieńcy od onego pragnienia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Którzy przysięgają przez obrzydliwość Samaryi, i mówią: Jako żyje Bóg twój, o Dan! i jako żyje droga Beerseba; i upadną, a nie powstaną więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Widziałem Pana stojącego na ołtarzu, który rzekł: Uderz w gałkę, aż zadrżą podwoje, a rozetnij je wszystkie od wierzchu ich, a ostatek mieczem pobiję; żaden z nich nie uciecze, i nie będzie z nich nikt, coby tego uszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Choćby się zakopali w ziemię, i stamtądby ich ręka moja wzięła; choćby wstąpili aż do nieba, i stamtądby ich stargnął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'A choćby się skryli na wierzchu Karmelu, wyszpieguję i wezmę ich stamtąd; a choćby się skryli przed oczyma mojemi na dnie morskiem, przykażę wężowi, aby ich i stamtąd wykąsał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'A choćby poszli w niewolę przed nieprzyjaciółmi swymi, i tam przykażę mieczowi, aby ich pomordował; obrócę zaiste przeciwko nim oko swe na złe, a nie na dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Bo panujący Pan zastępów, gdy się dotknie ziemi, rozpływa się, a płaczą wszyscy mieszkający na niej, i wzbiera wszystka jako rzeka, a zatopiona bywa jako rzeką Egipską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Który na niebiesiech zbudował pałace swoje, a zastęp swój na ziemi uszykował; który może zawołać wody morskie, a wylać je na oblicze ziemi; Pan jest imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Izali nie jesteście podobni synom Murzyńskim przedemną, o synowie Izraelscy? mówi Pan; izalim Izraela nie wywiódł z ziemi Egipskiej jako Filistyńczyków z Kaftor, i Syryjczyków z Kir?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Oto oczy panującego Pana przeciwko temu królestwu grzeszącemu, abym je wygładził z oblicza ziemi; wszakże nie wygładzę do szczętu domu Jakóbowemu, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Bom oto Ja rozkazał, a rozmiecę między wszystkie narody dom Izraelski jako miotana bywa pszenica na przetaku, tak, iż nie przepadnie i kamyk na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Wszyscy grzesznicy z ludu mojego od miecza pomrą, którzy mówią: Nie przybliży się do nas, ani nas zachwyci to złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Dnia onego wystawię upadły przybytek Dawidowy, a zagrodzę rozerwanie jego, i obaliny jego naprawię, a pobuduję go, jako za dni dawnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Aby posiedli ostatki Edomczyków i wszystkie narody nad którymi wzywano imienia mojego, mówi Pan, który to czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Oto dni idą, mówi Pan, że oracz żeńcę zajmie, a ten, co tłoczy winne jagody, rozsiewającego nasienie; a góry moszczem kropić będą, a wszystkie pagórki się rozpłyną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'I nawrócę zaś z więzienia lud mój Izraelski, i pobudują miasta spustoszone, a mieszkać w nich będą; sądzić też będą winnice, i wino z nich pić będą; sadów też naszczepią, i owoc ich jeść będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'A tak ich wszczepię w ziemi ich, że nie będą więcej wykorzenieni z ziemi swojej, którąm im dał, mówi Pan, Bóg twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Widzenie Abdyjaszowe. Tak mówi panujący Pan o ziemi Edomskiej: Słyszeliśmy wieść od Pana i od posła wysłanego do narodów: Ruszcie się, a powstańmy przeciwko niemu ku bitwie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Oto cię maluczkim uczynię między narodami, ty będziesz bardzo wzgardzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Pycha serca twego zdradziła cię, o ty! który mieszkasz w rozpadlinach skalnych, w wysokiem mieszkaniu twojem, który mówisz w sercu swojem: Któż mię na ziemię ściągnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Choćbyś się wywyższył jako orzeł, owszem, choćbyś między gwiazdami położył gniazdo twoje, i stamtąd cię stargnę, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'O jakożeś zniszczony! Izaliż złodzieje przyszli na cię? Izali zbójcy nocni? Izaliby kradli nad potrzebę swoję? Gdyby ci na cię przyszli, co wino zbierają, izaliby nie zostawili którego grona?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Jakoż wyszpiegowane są skarby Ezaw, a wynalezione są skryte rzeczy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Aż do granicy wypchną cię wszyscy, z którymi masz przymierze; zdradzą cię, moc wezmą nad tobą ci, z którymi masz pokój; którzy chleb twój jedzą, ranęć zdradliwie zadadzą, tak, iż się nie obaczysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Izali dnia onego, mówi Pan, nie wytracę mędrców z Edom, a roztropnych z góry Ezawa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'I ulękną się mocarze twoi, o Temanie! dlatego, że porażeni będąc wygubieni będą wszyscy z góry Ezawa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Dla bezprawia bratu twemu Jakóbowi uczynionego hańba cię okryje, a wykorzeniony będziesz na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Stałeś dnia onego naprzeciwko, dnia onego, gdy cudzy imali wojsko jego, i gdy cudzoziemcy wchodzili w bramy jego, a o Jeruzalem los miotali, tyś też był jako jeden z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Nie patrzże tedy na dzień brata swego, na dzień pojmania jego; ani się wesel nad synami Judzkimi w dzień zginienia ich, ani hardzie mów usty swemi w dzień ucisku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Nie wchodź w bramę ludu mego w dzień utrapienia ich, ani patrz na złe jego w dzień doległości jego, ani ściągaj ręki swej na majętność jego, w dzień skruszenia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Ani stój na rozstaniu dróg, abyś zatracał tych, którzy z nich uchodzą; ani podawaj nieprzyjacielowi w moc tych, którzy z nich zostali w dzień ucisku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Bo bliski jest dzień Pański przeciwko tym wszystkim narodom; jakoś uczynił, tak ci się stanie, nagroda twoja obróci się na głowę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Bo ponieważ wy pić będziecie na górze mojej świętej, tak pić będą wszystkie narody; ustawicznie, mówię, pić i pożerać będą, aż się staną, jakoby ich nie było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'A na górze Syon będzie wybawienie, a ta góra będzie święta, i posiędzie dom Jakóbowy osiadłości swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'I stanie się dom Jakóbowy ogniem, a dom Józefowy płomieniem, dom zaś Ezawowy ścierniskiem; i rozpali się na nich, i strawi ich, a nikt nie zostanie z domu Ezawowego; bo Pan to mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'A tak odziedziczą krainę południową z górą Ezawa, i równinę z Filistyńczykami; posiędą też krainę Efraimową, i krainę Samaryi, i Benjaminową i Galaadską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'A zaprowadzeni w niewolę tego wojska synów Izraelskich posiędą to, co było Chananejczyków aż do Sarepty; a zaprowadzeni w niewolę Jeruzalemczyków posiędą to, co jest na końcu państwa, posiędą z miastami na południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'I wstąpią wybawiciele na górę Syon, aby sądzili górę Ezawa; a tak będzie królestwo samego Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'I stało się słowo Pańskie do Jonasza, syna Amaty, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Wstań, idź do Niniwy miasta tego wielkiego, a wołaj przeciwko niemu; bo wstąpiła złość ich przed oblicze moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Ale Jonasz wstał, aby uciekł do Tarsu od oblicza Pańskiego; a przyszedłszy do Joppen, znalazł okręt, który miał iść do Tarsu, a zapłaciwszy od niego wstąpił nań, aby płynął z nimi do Tarsu od oblicza Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Ale Pan wzruszył wiatr wielki na morzu, i powstał wicher wielki na morzu; i zdało się, jakoby się okręt rozbić miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'A żeglarze ulękłszy się wołali każdy do boga swego, a wyrzucali do morza to, co mieli na okręcie, aby tem lżejszy był; ale Jonasz zszedł był na stronę okrętu, a położywszy się spał twardo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Tedy przystąpił do niego sternik, i rzekł mu: Cóż czynisz ty, ospalcze? wstań, wołaj do Boga swego, owa snać wspomni Bóg na nas, abyśmy nie zginęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Tedy rzekł jeden do drugiego: Chodźcie, rzućmy losy, abyśmy się dowiedzieli, dla kogo to złe na nas przyszło; rzucili tedy losy, i padł los na Jonasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'I rzekli do niego: Powiedz nam proszę, dla kogo to złe przyszło na nas? coś za rzemiosła? skąd idziesz? z którejś ziemi i z któregoś narodu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'I rzekł do nich: Jestem Hebrejczyk, a boję się Pana, Boga niebieskiego, który stworzył morze i ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Tedy się zlękli mężowie strachem wielkim; a dowiedziawszy się mężowie oni, że od oblicza Pańskiego ucieka, (bo im był oznajmił) rzekli do niego: Cóżeś to uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Nadto rzekli do niego: Cóż z tobą uczynimy, aby się morze uspokoiło? Bo się morze im dalej tem bardziej burzyło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Tedy rzekł do nich: Weźmijcie mię, a wrzućcie mię w morze, a uspokoi się morze przed wami, gdyż ja wiem, iż dla mnie to wzruszenie wielkie na was przyszło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Ale oni mężowie robili wiosłami, chcąc się do brzegu dostać, wszakże nie mogli; bo się morze im dalej tem więcej burzyło przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Wołali tedy do Pana, mówiąc: O Panie! prosimy, abyśmy nie zginęli dla śmierci męża tego, ani wkładaj na nas krwi niewinnej; bo ty, o Panie! jako chcesz, tak czynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Zatem wzięli Jonasza i wrzucili go w morze; i uspokoiło się morze od wzburzenia swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Bali się tedy mężowie strachem wielkim Pana, i ofiarowali ofiarę Panu, i śluby czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Lecz Pan był nagotował rybę wielką, żeby pożarła Jonasza; i był Jonasz we wnętrznościach onej ryby trzy dni i trzy nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'I modlił się Jonasz Panu, Bogu swemu, we wnętrznościach onej ryby,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'I rzekł: Wołałem z ucisku swego do Pana, a ozwał mi się; z głębokości grobu wołałem, a wysłuchałeś głos mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Boś mię wrzucił w głębokość w pośrodek morza, i rzeka ogarnęła mię; wszystkie nawałności twoje i powodzi twoje zwaliły się na mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Jużem był rzekł: Wygnanym jest od oczów twoich, wszakże jeszcze będę patrzał na kościół twój święty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Ogarnęły mię wody aż do duszy, przepaść mię ogarnęła, rogożem obwiniona była głowa moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Zstąpiłem aż do spodku gór, ziemia się zaworami swemi zawarła nademną na wieki; tyś jednak wywiódł z dołu żywot mój, o Panie, Boże mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Gdy ustawała we mnie dusza moja, wspomniałem na Pana; modlitwa moja przyszła do ciebie, do świętego kościoła twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Którzy pilnują marności nikczemnych, pozbawiają się miłosierdzia Bożego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Ale ja z głosem dziękczynienia ofiarować ci będę, com ślubował, spełnię; od Pana jest obfite wybawienie. I rozkazał Pan onej rybie, a wyrzuciła Jonasza na brzeg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Tedy się stało słowo Pańskie do Jonasza powtóre, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Wstań, idź do Niniwy, tego miasta wielkiego, a każ przeciwko niemu to, coć rozkazuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Wstał tedy Jonasz, i poszedł do Niniwy według słowa Pańskiego. (A Niniwe było miasto bardzo wielkie na trzy dni drogi.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Tedy Jonasz począł chodzić po mieście, ile mógł za jeden dzień ujść, i wołał mówiąc: Po czterdziestu dniach Niniwe będzie wywrócone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'I uwierzyli Niniwczycy Bogu; a zapowiedziawszy post oblekli się w wory, od największego z nich aż do najmniejszego z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Bo gdy ta rzecz przyszła do króla Niniwskiego, powstawszy z stolicy swojej złożył z siebie odzienie swoje, a oblekłszy się w wór, siedział w popiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'I rozkazał wywołać i opowiadać w Niniwie z dekretu królewskiego, i książąt swoich, tak mówiąc: Ludzie i bydło, woły i owce niech nic nie ukuszają, i niech się nie pasą, i wody nie piją;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Ale się niech okryją worami ludzie i bydło, a niech do Boga gorliwie wołają, a niech się odwróci każdy od złej drogi swojej i od łupiestwa, które jest w ręku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Kto wie, jeźli się nie obróci Bóg, a nie użali się tego, nie odwrócili się, mówię, od popędliwości gniewu swego, abyśmy nie zginęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'I widział Bóg sprawy ich, iż się odwrócili od złej drogi swej i użalił się Bóg nad tem złem, które rzekł, że im miał uczynić, a nie uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'I nie podobało się to bardzo Jonaszowi, i rozpalił się gniew jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Przetoż się modlił Panu, i rzekł: Proszę Panie! azażem tego nie mówił, gdym jeszcze był w ziemi mojej? Dlategom się pospieszył, abym uciekł do Tarsu, gdyżem wiedział, żeś ty Bóg łaskawy i litościwy, długo cierpliwy i wielkiego miłosierdzia, a który żałujesz złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'A teraz, o Panie! proszę, odbierz duszę moję odemnie: bo mi lepiej umrzeć, niżeli żyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'I rzekł Pan: A dobrzeż to, że się tak gniewasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Bo wyszedł był Jonasz z miasta, i siedział na wschód słońca przeciwko miastu; a uczyniwszy tam sobie budę, usiadł pod nią w cieniu, ażby ujrzał, coby się działo z onem miastem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'A Pan Bóg był zgotował banię, która wyrosła nad Jonaszem, aby zasłaniała głowę jego, i zastawiała go od gorąca; tedy się Jonasz bardzo z onej bani radował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Wtem nazajutrz na świtaniu nagotował Bóg robaka, który podgryzł onę banię, tak, że uschła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'I stało się, gdy weszło słońce, wzbudził Bóg wiatr suchy od wschodu słońca, i biło słońce na głowę Jonaszową, tak, iż omdlewał, i życzył sobie śmierci, mówiąc: Lepiej mi umrzeć, niżeli żyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'I rzekł Bóg do Jonasza: Dobrzeż to, że się tak gniewasz o tę banię? I rzekł: Dobrze, że się gniewam aż na śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Tedy mu rzekł Pan: Ty żałujesz tej bani, około którejś nie pracował, aniś jej dał wzrost, która jednej nocy urosła, i jednej nocy zginęła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'A Jabym nie miał żałować Niniwy, miasta tak wielkiego? w którem jest więcej niżeli sto i dwadzieścia tysięcy ludzi, którzy nie umieją rozeznać między prawicą swoją i lewicą swoją, i bydła wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Słowo Pańskie, które się stało do Micheasza Morastytczyka za dni Joatama, Achaza, i Ezechyjasza, królów Judzkich, które w widzeniu słyszał o Samaryi i o Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Słuchajcie wszystkie narody! niech słucha ziemia, i wszystko, co na niej jest, a niech będzie panujący Pan przeciwko wam świadkiem, panujący z kościoła świętobliwości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Bo oto Pan wyjdzie z miejsca swojego, a zstąpiwszy deptać będzie po wysokościach ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'I rozpłyną się góry pod nim, a doliny popadają się, tak jako wosk od ognia, i jako wody, które spadają na dół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'To wszystko się stanie dla przestępstwa Jakóbowego, i dla grzechów domu Izraelskiego. Któż jest przyczyną przestępstwa Jakóbowego? izali nie Samaryja? i któż wyżyn Judzkich? izali nie Jeruzalem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Przetoż obrócę Samaryję w gromadę gruzu, jako bywa na polu około winnic, i powrzucam w dolinę kamienie jej, a grunty jej odkryję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'I wszystkie obrazy jej ryte będą potłuczone, i wszystkie jej dary ogniem spalone, i wszystkie jej bałwany obrócę w pustynię; bo to z zapłaty nierządnicy zgromadziła, przetoż się to zaś na zapłatę nierządnicy obróci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Nad tem kwilić i narzekać będę, chodząc zewleczony i nagi; uczynię lament jako smoki i narzekanie jako młode strusięta;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Przeto, że nieuleczone są rany jej, gdyż doszły aż do Judy, a dosięgły do bramy ludu mego aż do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'W Giet tego nie opowiadajcie, ani kwiląc płaczcie; walaj się w prochu w domu Orfa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Przejdziesz ty, która mieszkasz na miejscu pięknem, obnażoną mając hańbę; nie wnijdzie ta, która mieszka na miejscu w bydło obfitem; płacz będzie w miejscach okolicznych, które od was mają żywność swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Będzie bowiem bolesna dla dobrych rzeczy ta, która mieszka na miejscach przykrych, przeto, że zstąpi złe od Pana aż do bramy Jeruzalemskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Zaprzęż w wóz prędkie konie, obywatelko Lachys! któraś powodem grzechu córki Syońskiej, gdyż w tobie znalezione są przestępstwa Izraelskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Przetoż poślę upominki swe do Moreset w Giet; domy Achzyb na oszukanie będą królom Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Jeszczeć dziedzice przywiodę, o obywatelko Maresy! przyjdzie aż do Odollam, i aż do chwały Izraelskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Obłyś się i ostrzyż się dla synów rozkoszy twoich; rozszerz łysinę twoję jako orzeł, bo się prowadzą od ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Biada tym, którzy wymyślają nieprawość, i knują złe na łożach swoich, a na świtaniu rano do skutku je przywodzą, gdyż to jest w mocy rąk ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Pożądają pól, i wydzierają; także i domów, i odejmują; a tak przewodzą gwałt nad mężem i domem jego, nad każdym mężem i nad dziedzictwem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Dlatego tak mówi Pan: Oto Ja złe myślę przeciwko rodzajowi temu, z którego nie wyjmiecie szyj waszych, ani będziecie chodzić pysznie; bo czas zły będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'W on dzień urośnie o was przypowieść, i narzekać będą nad wami płaczem żałośnym, mówiąc: Spustoszeniśmy do szczętu, Pan odmienił dział ludu mojego; o jakoć mi go odjął! jakoć wziąwszy pole nasze rozdzielił!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Dlatego nie będziesz miał, ktoby rzucił sznurem na los w zgromadzeniu Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Mówią: Nie prorokujcie, niech nam inni prorokują; bo nie prorokują tak jako ci; żaden z nich nie przestaje mów zelżywych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'O ty ludu, który słyniesz domem Jakóbowym! izali ukrócony ma być duch Pański? Izali takowe są sprawy jego? Azaż słowa moje nie są dobre temu, który chodzi w uprzejmości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Wczoraj był ludem moim, a dziś jako nieprzyjaciel powstaje; mając odzienie, zdzieracie płaszcz z tych, którzy chodzą bezpiecznie, którzy się wracają z wojny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Żony ludu mego wyganiacie z domu rozkoszy ich, od dziatek ich ustawicznie odejmujecie sławę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Wstańcie, a odejdźcie, bo tu nie masz odpocznienia; pogubi was dla nieczystości, a to pogubieniem srogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Gdy się kto za proroka udaje, a kłamstwo opowiadając mówi: Będęć prorokował o winie albo o napoju mocnym: takowyć bywa miłym prorokiem ludu tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Zgromadzając cale cię zgromadzę, Jakóbie! zgromadzając zgromadzę ostatki Izraela, a spędzę je w gromadę jako owce Bocra, jako trzodę w pośród obory jego, i wyjdzie huk od ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Zstąpi ten, który przełamywać będzie przed nimi; przełamie, a przejdą bramą, i wnijdą przez nią; nawet i król ich pójdzie przed nimi, a Pan na czele ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Przetoż mówię: Słuchajcie przedniejsi w Jakóbie, i wodzowie domu Izraelskiego! izali wy nie macie być powiadomi sądu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Ale oni nienawidzą dobrego, a miłują złe; odzierają lud z skóry ich, i mięso ich z kości ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'A jedzą mięso ludu mojego, a skórę ich z nich zdzierają,i kości ich łamią, i rąbią je jako do garnca, a jako mięso do kotła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Tedy do Pana wołać będą, a nie wysłucha ich, owszem, zakryje oblicze swoje przed nimi czasu onego, tak jako oni wykonywali złe przedsięwzięcia swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Tak mówi Pan o tych prorokach, którzy w błąd zawodzą lud mój, a kąsając zębami swemi opowiadają pokój, a przeciwko temu, któryby im nic do gęby nie dał, wojnę podnoszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Dlatego się wam widzenie obróci w noc, a wieszczba wasza w ciemność; bo tym prorokom słońce zajdzie, a dzień im się zaćmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'I będą się wstydzili oni widzący, a wieszczkowie się zapłoną, a ci wszyscy zakryją zwierzchnią wargę swoję, przeto, że nie będzie żadnej odpowiedzi Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Alem ja napełniony siłą ducha Pańskiego i sądem i mocą, abym oznajmił Jakóbowi przestępstwa jego, a Izraelowi grzech jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Słuchajcież już tego przedniejsi w domu Jakóbowym, i wodzowie domu Izraelskiego, którzy macie sąd w obrzydliwości, a co jest sprawiedliwego, podwracacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Każdy buduje Syon krwią, a Jeruzalem nieprawością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Przedniejsi jego sądzą według darów, a kapłani jego za zapłatę uczą, a prorocy jego za pieniądze prorokują; a przecie na Panu polegają, mówiąc: Izali nie jest Pan w pośrodku nas? Nie przyjdzieć na nas nic złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Przetoż Syon dla was jako pole poorany będzie, a Jeruzalem w gromady gruzu obrócone będzie, a góra domu Bożego w wysokie lasy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Ale się stanie w ostateczne dni, że utwierdzona będzie góra domu Pańskiego na wierzchu gór, i wywyższona nad pagórki, a narody się do niej zbiegać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'I pójdzie wiele narodów, mówiąc: Pójdźcie, a wstąpmy na górę Pańską, to jest do domu Boga Jakóbowego, a będzie nas nauczał dróg swoich, i będziemy chodzili ścieszkami jego; bo zakon z Syonu wyjdzie, a słowo Pańskie z Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Onci sądzić będzie między wieloma narodami, a karać będzie narody mocne na długie czasy; i przekują miecze swe na lemiesze, a oszczepy swe na kosy: nie podniesie miecza naród przeciwko narodowi, ani się więcej ćwiczyć będą do boju');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Ale każdy będzie siedział pod winną macicą swoją, i pod figowem drzewem swojem, a nie będzie nikt, coby ich przestraszył; bo to usta Pana zastępów mówiły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Bo wszystkie narody chodzić będą, każdy w imieniu boga swego; ale my chodzić będziemy w imieniu Pana, Boga naszego, na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'Dnia onego, mówi Pan, zgromadzę chromą i wygnaną zbiorę, i onę, którejm był źle uczynił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'A dam tej chromej potomstwo, a precz wygnanej naród możny; i będzie Pan królował nad nimi na górze Syon odtąd aż na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'A ty, wieżo trzody, baszto córki Syońskiej! wiedz, że aż do ciebie przyjdzie; przyjdzie mówię, pierwsze państwo, i królestwo córki Jeruzalemskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Czemuż teraz tak bardzo krzyczysz? Izali króla niemasz w tobie? Izali radca twój zginął, że cię zjął ból, jako rodzącą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Bolej a stękaj, córko Syońska? jako rodząca; bo już wyjdziesz z miasta, i będziesz mieszkała w polu, a przyjdziesz aż do Babilonu; tam będziesz wybawiona, tam cię Pan odkupi z rąk nieprzyjaciół twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'A choć się teraz zebrało przeciwko tobie wiele narodów, które mówią: Niech będzie splugawiony Syon, a niech na to patrzy oko nasze,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Wszakże one nie znają myśli Pańskich, ani rozumieją rady jego, iż je zgromadza jako snopy na bojewisko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Wstańże, a młóć, córko Syońska! bo róg twój uczynię żelazny, a kopyta twoje uczynię miedziane, i pokruszysz wiele narodów; i poświęcę Panu korzyści ich, a majętności ich Panu wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Zbierzże się teraz w hufy, o walecznico! oblęż nas; niech laską biją w lice sędziego Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Ale ty, Betlehemie Efrata! acześ najmniejszy między tysiącami Judzkimi, z ciebie mi jednak wyjdzie ten, który będzie panującym w Izraelu, a wyjścia jego są z dawna, ode dni wiecznych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Przetoż choć ich wyda w rozproszenie aż do czasu, któregoby rodząca porodziła, wszakże ostatek braci jego nawrócą się z synami Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'I stanie się a paść ich będzie w sile Pańskiej, i w sławie imienia Pana, Boga swego; i będą mieszkać, bo już wielmożnym będzie aż do granic ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'I będzie taki pokój, że gdy Assyryjczyk wtargnie w ziemię naszę, i gdy podepcze pałace nasze, tedy wystawimy przeciw niemu siedmiu pasterzy, i ośmiu książąt z ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Ci wypasą ziemię Assyryjską mieczem, i ziemię Nimrodową w granicach ich; a tak wyrwie nas Assyryjczykowi, gdy przyciągnie do ziemi naszej, i gdy będzie deptał granicę nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Przetoż ostatki Jakóbowe w pośrodku wielu narodów będą jako rosa od Pana, jako ciche deszcze skrapiające trawę, których się nie spodziewa od człowieka, ani ich czeka od synów ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Będą też ostatki Jakóbowe między poganami w pośrodku wielu narodów jako lew między zwierzętami leśnemi, a jako szczenię lwie między trzodą owiec, które gdy idzie, a depcze i łapie, niemasz nikogo, ktoby wydarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Wywyższy się ręka twoja nad nieprzyjaciołmi twoimi, a wszyscy przeciwnicy twoi wykorzenieni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'I stanie się dnia onego, mówi Pan, że wytracę konie twoje z pośrodku ciebie, a wozy twoje popsuję,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'I wygubię miasta ziemi twojej, a poburzę wszystkie twierdze twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Wygubię też gusła z ciebie, a wieszczków nie będzie w tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Wygubię też ryte bałwany twoje i obrazy twoje z pośrodku ciebie, a nie będziesz się więcej kłaniał robocie rąk twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Wykorzenię i gaje twoje z pośrodku ciebie, a wygładzę nieprzyjaciół twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'A tak w gniewie i w zapalczywości wykonam pomstę nad narodami, które nie były posłuszne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Słuchajcie, proszę, co mówi Pan: Wstań, rozpieraj się z temi górami, a niech słuchają pagórki głosu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Słuchajcie góry sporu Pańskiego, i najmocniejsze grunty ziemi; bo Pan ma spór z ludem swoim, a z Jeruzalemem prawo wiedzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Ludu mój! cóżem ci uczynił, a w czemem ci się uprzykrzył? Odłóż świadectwo przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Wszakiem cię wywiódł z ziemi Egipskiej, a z domu niewolników odkupiłem cię, i posłałem przed obliczem twojem Mojżesza, Aarona i Maryję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Ludu mój! Wspomnij teraz, co za radę uczynił Balak, król Moabski, a co mu odpowiedział Balaam, syn Beorowy; wspomnij też, coć się działo od Syttym aż do Galgal, abyś poznał sprawiedliwości Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Ale mówisz: Z czemże się stawię przed Panem, a pokłonię się Bogu najwyższemu? Izali się przedeń stawię z ofiarami całopalonemi, z cielcami rocznemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Izali się Pan kocha w tysiącach baranów, i w tysiącu tysięcy strumieni oliwy? Izali dam pierworodnego swego za przestępstwo moje? albo owoc żywota mego za grzech duszy mojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Oznajmił ci człowiecze, co jest dobrego, i czegoż Pan chce po tobie; tylko abyś czynił sąd, a miłował miłosierdzie i pokornie chodził z Bogiem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Głos Pański na miasto woła: (ale roztropny sam się ogląda na imię twoje, o Boże!) Słuchajcież o rózdze, i kto ją postanowił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Izali jeszcze są w domu niezbożnego skarby niesprawiedliwe, i miara niesprawiedliwa i obrzydła?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Izali mam usprawiedliwić szale niesprawiedliwe, i w worku gwichty fałszywe?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Bogacze jego pełni są zdzierstwa, a obywatele jego mówią kłamstwa, i język ich kłamliwy jest w ustach ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Przetoż i Ja cię też nawiedzę chorobą, uderzę cię, i zniszczę cię dla grzechów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Jeść będziesz, a nie nasycisz się, i poniżenie twoje będzie w pośrodku ciebie: pochwycisz ale nie wyniesiesz; a co wyniesiesz, na miecz podam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Ty będziesz siał, ale nie będziesz żął; ty będziesz tłoczył oliwki, ale nie będziesz się oliwą mazał, i moszcz, ale nie będziesz pił wina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Bo to miasto pilnie przestrzega ustaw Amrego, i wszelakiej sprawy domu Achabowego,i sprawujecie się radami ich, tak abym cię wydał na spustoszenie, i obywateli jego na pośmiech; przetoż hańbę ludu mego nosić będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Biada mnie! żem jako ostatki po sprzątanieniu owoców letnich, jako pozostałe grona po zbieraniu wina; niemasz grona ku zjedzeniu, pierwocin z owocu pragnie dusza moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Pobożny z ziemi zginął, a szczerego niemasz między ludźmi; wszyscy zgoła o wylaniu krwi myślą, każdy łowi siecią brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Co złego robią rękoma, chcą, aby to za dobre uszło; książę podatków żąda, a sędzia z datku sądzi, a kto możny jest, ten mówi przewrotność duszy swojej, i w gromadę ją plotą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Najlepszy z nich jest jako oset, najszczerszy przechodzi ciernie; dzień stróżów twoich i nawiedzenia twego przychodzi; już nastanie powikłanie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Nie wierzcie przyjacielowi, ani ufajcie wodzowi; przed tą, która leży na łonie twojem, strzeż drzwi ust swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Bo syn lekce waży ojca, a córka powstaje przeciwko matce swej, synowa przeciwko świekrze swej, a nieprzyjaciele każdego są domownicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Przetoż ja na Pana patrzyć będę, oczekiwać będę Boga zbawienia mego; Bóg mój wysłucha mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Nie wesel się ze mnie, nieprzyjaciółko moja! jeźlim upadła, powstanę; jeźli siedzę w ciemnościach, Pan jest światłością moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Gniew Pański poniosę: bom przeciwko niemu zgrzeszył, aż się wżdy zastawi o sprawę moję, a wykona sąd mój: wywiedzie mię na światło, ujrzę sprawiedliwość jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Ujrzy to nieprzyjaciółka moja, a wstyd okryje tę, która do mnie mówi: Gdzież jest Pan, Bóg twój? Oczy moje na nią patrzyć będą, gdy jako błoto na ulicach podeptana będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Dnia onego, którego pobudowane będą parkany twoje, dnia onego, mówię, daleko się wyrok rozejdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'Onegoż dnia przychodzić będą do ciebie i z Assyryi aż do miast obronnych, i od miast obronnych aż do rzeki, i od morza aż do morza, i od góry aż do góry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Wszakże ta ziemia spustoszona będzie dla obywateli swoich, dla owocu wynalazków ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Paśże lud twój laską twoją, trzodę dziedzictwa twego, która osobno mieszka w lesie i w pośród pola; niech wypasą Basan i Galaad jako za dni starodawnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Ukażę mu dziwne rzeczy, jako za dni, którycheś wyszedł z ziemi Egipskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Co widząc narody zawstydzą się nad wszystką mocą swoją, włożą rękę na usta, a uszy ich ogłuszeją');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Proch jako wąż lizać będą, jako gadziny ziemskie ruszą się z lochów swoich, do Pana, Boga naszego, z strachem pobieżą, i bać się ciebie będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Któryż Bóg jest podobny tobie? Któryby nieprawość odpuszczał, i mijał przestępstwa ostatków dziedzictwa swego, któryby nie zatrzymywał na wieki gniewu swego, przeto, że się kocha w miłosierdziu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Nawróci się, a zmiłuje się nad nami; zatłumi nieprawości nasze i wrzuci w głębokość morską wszystkie grzechy nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Pokażesz się Jakóbowi prawdomównym, a miłosiernym Abrahamowi, jakoś przysiągł ojcom naszym ode dni dawnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Brzemię Niniwy. Księgi widzenia Nahuma Elkosejczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Pan jest Bóg zapalczywy i mściwy; mściwy jest Pan a gniewliwy; Pan, który się mści nad przeciwnikami swymi, i chowa gniew przeciwko nieprzyjaciołom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Pan nierychły do gniewu a wielkiej mocy, który winnego nie czyni niewinnym; w wichrze i w burzy jest droga Pańska, a obłok jest prochem nóg jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Który gromi morze i wysusza je, i wszystkie rzeki wysusza; przed nim Basan i Karmel mdleje, a kwiat Libański więdnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Góry drżą przed nim, a pagórki się rozpływają; ziemia gore od oblicza jego, i okrąg ziemi i wszyscy mieszkający na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Przed rozgniewaniem jego, któż się ostoi? a kto się stawi przeciwko popędliwości gniewu jego? Gniew jego się wylewa jako ogień, a skały się padają przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Dobry jest Pan, i posila w dzień uciśnienia, a zna tych, którzy ufają w nim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Przetoż powodzią prędką koniec uczyni miejscu jego, a nieprzyjaciół Bożych ciemności gonić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Cóż zamyślacie przeciwko Panu?onci koniec uczyni, utrapienie drugi raz nie powstanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Bo tak jako ciernie splecieni a opojeni są jako winem; przetoż jako ściernisko suche do szczętu pożarci będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Z ciebie wyszedł ten, który złe myśli przeciwko Panu, radca złośliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Tak mówi Pan: Być się byli spokojnie zachowali, zostałoby ich było wiele, alboby tylko byli przerzedzeni, byłoby ich to minęło, a nietrapiłbym ich był więcej, tak jakom ich trapił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Ale teraz skruszę jarzmo jego, aby na tobie nie leżało, a związki twoje potargam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Bo przeciwko tobie, o Niniwczyku! Pan przykazał, że nie będzie więcej imienia nasienia twego; z domu boga twego wygładzę ryte i lane obrazy, a gdy znieważony będziesz, grób ci zgotuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Oto na tych górach nogi wdzięczne poselstwo opowiadającego, zwiastującego pokój. Obchodźże, o Judo! uroczyste święta twoje, oddawaj śluby twoje; bo się więcej złośnik mimo cię chodzić nie pokusi, do szczętu jest wygładzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Ciągnie skażyciel przeciw tobie, o Niniwe! opatrz miejsca obronne, wyglądaj na drogę, zmocnij biodra, a bardzo umocnij siłę twoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Bo Pan odwrócił pychę Jakóbową, jako pychę Izraelową, przeto, że ich wyniszczyli skażyciele, a latorośle ich popsowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Tarcza mocarzy jego czerwona, rycerstwo jego szarłatem odziane, wozy jego jako pochodnie gorejące iskrzyć się będą w dzień potykania jego, a jodły straszne trząść się będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Wozy po ulicach grzmieć i po rynku skrzypieć będą; na wejrzeniu będą jako pochodnie, a jako błyskawice biegać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Szykuje mocarzy swoich, ale jednak upadną w szyku swym; pospieszy się do murów, jakoby tam zgotowana była obrona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Bramy się przy rzekach otworzą, a kościół się rozpłynie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'A Chusab pojmana będąc zawiedziona będzie, a służebnice jej prowadzić ją będą, hucząc jako gołębica a bijąc się w piersi swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'A aczkolwiek Niniwe było jako sadzawka wód od początku swego, wszakże już sami uciekają; a choć kto rzecze: Stójcie, stójcie! wszakże się nikt nie obejrzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Rozchwyćcież srebro, rozchwyćcież złoto, i niezmierne bogactwa, i cokolwiek najkosztowniejszego ze wszystkich klejnotów drogich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Wyplundrowane i wybrane będzie, owszem, do szczętu spustoszone będzie; serce się rozpłynie, kolano o kolano tłuc się będzie, i boleść na wszystkich biodrach będzie, a oblicza wszystkich poczernieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Gdzież jest jaskinia lwów, i pastwisko lwiąt? gdzie chodził lew, lew, mówię, i lwica, a nie było nikogo, ktoby je przestraszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Lew, który dostatkiem chwytał lwiętom swoim i zaduszał dla lwic swoich, który napełniał łupem jaskinie swoje, a obłowem łożyska swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Otom Ja przeciwko tobie, mówi Pan zastępów, a popalę na proch wozy twoje, a miecz pożre lwięta twoje; i wykorzenię z ziemi łup twój, a nie będzie więcej słyszany głos posłów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Biada miastu krwawemu; wszystko kłamstwa i łupiestwa pełne jest, a ździerstwo z niego nie wychodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Tam będzie słyszane trzaskanie biczów, i grzmot kół, i tupanie koni, i skakanie wozów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Jezdny dobędzie błyszczącego miecza swego, i lśniącego oszczepa; tam będzie wiele pobitych i wielkie gromady trupów, tak, że nie będzie liczby trupów, a przez ciała pobitych walić się będą:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Dla wielkości wszeteczeństw nierządnicy rozkosznej, która się bawiła czarami, a zaprzedawała narody wszeteczeństwami swemi, i ludzi gusłami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Otom Ja przeciwko tobie, mówi Pan zastępów, i odkryję podołek twój na twarz twoję, a okażę narodom sprosność twoję, a królestwom hańbę twoję:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'I wyrzucę na cię obrzydliwości i zelżę cię, i wystawię cię za dziw,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Tak, że ktokolwiek cię ujrzy, oddali się od ciebie i rzecze: Zburzone jest Niniwe, któżby się go użalił? Gdzieżbym szukał tych, którzyby cię cieszyli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Izaliś ty lepsza, niż ludne miasto No, które leżało między rzekami, wodami otoczone będąc; którego wałem było morze, i od morza mur jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Murzyńska ziemia i Egipt były siłą jego, i narody niezliczone, Putczycy i Lubimczycy, były mu na pomocy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Wszakże i to w zaprowadzenie i w pojmanie przyszło; maluczkie jego na rogach wszystkich ulic roztrącano a o najsławniejszych jego losy miotano, nawet wszyscy przedniejsi jego okowani są w pęta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Takżeć i ty opojona będziesz, i skryć się musisz, i ty szukać będziesz pomocy przeciwko nieprzyjacielowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Wszystkie twierdze twoje są jako figowe drzewo z owocem rannym, którym gdy kto zatrząśnie, zaraz wpadają w usta tego, co je jeść chce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Oto lud twój są niewiastami w pośród ciebie; nieprzyjaciołom twoim szeroko otworzone będą bramy ziemi twojej, a ogień pożre zawory twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Naczerpaj sobie wody do oblężenia, zmacniaj twierdze twoje, wleź w błoto, i depcz glinę, oprawiwszy cegielnicę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Tam cię pożre ogień, wytnie cię miecz, pożre cię jako chrząszcze; zgromadź się jako chrząszcze, zbierz się jako szarańcza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Rozmnożyłeś kupców twoich nad gwiazdy niebieskie; ale jako chrząszcze przypadają i odlatują, tak i ci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Panowie twoi są jako szarańcza, a hetmani twoi jako wielcy chrząszcze, którzy się kładą obozami na płotach czasu zimna, jedno słońce weszło, alić odlatują, i nie znać miejsca ich, gdzie byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Zdrzemią się pasterze twoi, o królu Assyryjski! leżeć będą sławni twoi; obfitość ludu twego będzie po górach, ale nie będzie, ktoby go zgromadził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Niemasz lekarstwa na ranę twoję, nieuleczona jest plaga twoja; wszyscy, którzy powieść o tobie usłyszą, klaskać będą rękoma nad tobą; bo na kogoż ustawicznie nie przychodziło okrucieństwo twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Brzemię, które widział prorok Abakuk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Dokądże wołać będę, o Panie! a nie wysłuchasz? Dokądże do ciebie przed gwałtem krzyczeć będę, a nie wybawisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Przeczże dopuszczasz, abym patrzył na nieprawość, i widział bezprawie, i zgubę, i gwałt przeciwko sobie? i przecz się znajduje ten, który swar i niezgodę roznieca?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Dlatego naruszony bywa zakon, a prawu się nigdy dosyć nie dzieje; albowiem niepobożny otacza sprawiedliwego, dlatego wychodzi sąd przewrotny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Spojrzyjcie na narody a obaczcie i dziwujcie się z zdumieniem, przeto, iż czynię nieco za dni waszych, o czem gdy wam powiadać będą, nie uwierzycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Albowiem oto Ja wzbudzę Chaldejczyków, naród srogi i prędki, który szeroko pójdzie przez ziemię, aby posiadł mieszkania cudze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Straszny jest i ogromny; od niego samego wynijdzie sąd jego, i wywyższenie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Konie jego prędsze będą niż lamparty, a sroższe nad wilki wieczorne; szeroko rozciągną się jezdni jego, a jezdni jego z daleka przyjdą, przylecą jako orzeł spieszący się do żeru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Każdy z nich dla łupiestwa przyjdzie; obrócą twarze swoje na wschód słońca, a więźniów zgromadzą jako piasek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Ten i z królów szydzić będzie, a książęta będą na pośmiech u niego; ten też z każdej twierdzy naśmiewać się będzie, a usypawszy wały weźmie ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Tedy się odmieni duch jego, a wystąpi i przewini, myśląc, że ta moc jego jest boga jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Izaliś ty nie jest od wieku, Panie, Boże mój, święty mój? myć nie pomrzemy; o Panie! postawiłeś go na sąd; ty, o skało nasza! na karanieś go ugruntował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Czyste są oczy twoje, tak, że na złe patrzyć i bazprawia widzieć nie mogą; przeczżebyś miał patrzyć na czyniących przewrotność? Przeczżebyś miał milczeć, ponieważ niezbożnik pożera sprawiedliwszego niżeli sam?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Miałżebyś zaniechać ludzi jako ryb morskich, jako płazu, który nie ma pana?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Wszystkie wędą wyciąga, zagarnia je niewodem swoim, i zgromadza je do sieci swoich; dlategoż się weseli i raduje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Przeto ofiaruje niewodowi swemu i kadzi sieci swojej; albowiem przez nie utył dział jego, a pożywienie jego hojniejsze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Izali dlatego będzie zapuszczał niewód swój, a ustawicznie zabijał narody bez litości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Na straży swej stać będę, i stanę na baszcie, wyglądając, abym obaczył, co będzie Bóg mówił, cobym miał odpowiedzieć po karaniu mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Tedy mi odpowiedział Pan, mówiąc: Napisz widzenie, a napisz rzetelnie na tablicach, aby je prędko czytelnik przeczytał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Przeto, że jeszcze do pewnego czasu odłożone jest widzenie, które wypowie na skończeniu jego, a nie skłamie; a jeźliby na chwilę odwłaczał, oczekuj nań; boć zapewne przyjdzie, a nie omieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Oto kto sobie hardzie poczyna, tego dusza nie jest szczera w nim; ale sprawiedliwy z wiary swej żyć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Dopieroż człowiek opiły, przewrotny i hardy nie ostoi się w mieszkaniu swojem, który rozszerza jako piekło duszę swoję, a jest jako śmierć, która się nie może nasycić, choćby zgromadził do siebie wszystkie narody, a zebrał do siebie wszystkich lud zi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Izali ci wszyscy o nim przypowieści nie uczynią i wykładów i gadanin o nim? mówiąc: Biada temu, który rozmnaża rzeczy nie swoje, (a dokądże?) i obciąża się gęstem błotem!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Izali nie powstaną z prędka, którzy cię kąsać będą, i nie ocucą się, którzy cię szarpać będą? i staniesz się im łupem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Bo iżeś ty złupił wiele narodów, złupią cię też wszystkie ostatki narodów, dla krwi ludzkiej i dla gwałtu uczynionego ziemi i miastu i wszystkim, którzy mieszkają w niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Biada temu, który łakomie szuka zysku szkaradnego domowi swemu, aby wystawił wysoko gniazdo swoje, a tak uszedł z mocy złego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Uradziłeś hańbę domowi swemu, abyś wytracił wiele narodów, a grzeszył przeciwko duszy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Albowiem kamień z muru wołać będzie, i sęk z drzewa wyda o tem świadectwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Biada temu, który krwią buduje miasto, a utwierdza miasta nieprawością!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Azaż to nie jest od Pana zastępów, iż koło czego ludzie pracują, to ogień skazi, a nad czem się narody spracowały, to nadaremno będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Albowiem ziemia będzie napełniona znajomością chwały Pańskiej, jako morze wody napełniają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Biada temu, który poi bliźniego swego, przystawiając naczynia swego, tak aby go upoił, i napatrzył się nagości jego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Nasycisz się hańby dla sławy; pić będziesz i ty, a obnażony będziesz; obróci się do ciebie kielich prawicy Pańskiej, i zwrócenie sromotne przyjdzie na sławę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Bo cię łupiestwo Libanu okryje i spustoszenie zwierząt, które ich straszyło: dla krwi ludzkiej i dla gwałtu ziemi i miasta, i wszystkich, którzy mieszkają w niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Cóż pomoże ryty obraz, że go wyrył rzemieślnik jego? albo odlewany obraz i nauczyciel kłamstwa, że ufa rzemieślnik w robocie swojej, czyniąc bałwany nieme?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Biada temu! który mówi drewnu: Ocuć się, a kamieniowi niememu: Obudź się! Tenże to ma uczyć? Spojrzyj nań, powleczonyć jest złotem i srebrem; ale w nim niemasz zgoła żadnego ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Pan jest w kościele świętobliwości swojej; umilknij przed obliczem jego wszystka ziemio!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Modlitwa Abakuka proroka według rozmaitych pieśni złożona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'O Panie! usłyszawszy wyrok twój ulękłem się. O Panie! zachowaj sprawę twoję w pośrodku lat, i objaw ją w pośrodku lat; w gniewie wspomnij na miłosierdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Gdy Bóg szedł od południa, a Święty z góry Faran, Sela! okryła niebiosa sława jego, a chwały jego ziemia pełna była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Jasność jego była jako światłość, rogi były na bokach jego, a tam była skryta siła jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Przed obliczem jego szedł mór, a węgle pałające szły przed nogami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Stanął i rozmierzył ziemię, wejrzał i rozproszył narody, skruszone są góry wieczne, i skłoniły się pagórki dawne: drogi jego są wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Widziałem namioty Chusan próżności poddane, a opony ziemi Madyjańskiej drżały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Izali się na rzeki, o Panie! izali się na rzeki rozpalił gniew twój? Izali na morze rozgniewanie twoje, gdyś jechał na koniach twoich, i na wozach twoich zbawiennych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Jawnie odkryty jest łuk twój dla przysięgi pokoleniom wyrzeczonej, Sela!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Rozdzieliłeś rzeki ziemi: widziały cię góry i zadrżały, powódź wód przeminęła; przepaść wydała głos swój, głębokość ręce swoje podniosła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Słońce i miesiąc zastanowił się w mieszkaniu swojem, przy jegoż świetle latały strzały twe, i przy blasku lśniącej się włóczni twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'W zagniewaniu podeptałeś ziemię, w zapalczywości młóciłeś pogan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Wyszedłeś na wybawienie ludu swego, na wybawienie z pomazańcem twoim; przebiłeś głowę z domu niezbożnika, odkrywszy grunt aż do szyi, Sela!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Potłukłeś kijmi jego głowę wsi jego, gdy się burzyli jako wicher, aby mię rozproszyli; weselili się, jakoby pożreć mieli ubogiego w skrytości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Jechałeś przez morze na koniach twoich, przez gromadę wód wielkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Gdym to słyszał, zatrząsnął się brzuch mój! na ten głos drżały wargi moje, zgniłość weszła w kości moje, i wszystekem się trząsł, słysząc, że mam odpocząć w dzień utrapienia, gdy przyciągnie na ten lud nieprzyjaciel, aby go przez wojnę wygładził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Choćby figowe drzewo nie zakwitnęło i nie było urodzaju na winnicach, choćby i owoc oliwy pochybił, i role nie przyniosłyby pożytku, i z owczarniby owce wybite były, a nie byłoby bydła w oborach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Wszakże się ja w Panu weselić będę, rozraduję się w Bogu zbawienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Panujący Pan jest siłą moją, który czyni nogi moje, jako nogi łani, i po miejscach wysokich poprowadzi mię. Przedniejszemu nad śpiewakami na muzycznem naczyniu mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Słowo Pańskie, które się stało do Sofonijasza, syna Chusego, syna Godolijaszowego, syna Amaryjaszowego, syna Ezechyjaszowego, za dni Jozyjasza, syna Amonowego, króla Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Wszystko zapewne zniosę z oblicza tej ziemi, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Zniosę ludzi i bydło, zniosę ptastwo niebieskie i ryby morskie, i zgorszenie z niepobożnymi; wykorzenię człowieka z oblicza tej ziemi, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Bo wyciągnę rękę moję na Judę, i na wszystkich obywateli Jeruzalemskich; wykorzenię z miejsca tego ostatki Baalowe, i popy jego z kapłanami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'I tych, którzy się kłaniają na dachach wojsku niebieskiemu, i tych, którzy kłaniając się przysięgają przez Pana, także i tych, którzy przysięgają przez Molocha swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'I tych, którzy się odwracają od naśladowania Pana, i którzy nie szukają Pana, ani się pytają o nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Umilknij przed obliczem panującego Pana, gdyż bliski jest dzień Pański; bo Pan zgotował ofiarę, i poświęcił wezwanych swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'A w dzień ofiary Pańskiej nawiedzę książąt i synów królewskich, i wszystkich, którzy się obłóczą w szaty cudzoziemskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Nawiedzę też dnia onego każdego, który próg przeskakuje, którzy napełniają domy panów swych łupiestwem i bezprawiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'A dnia onego, mówi Pan, będzie głos wołania od bramy rybnej, i narzekanie od drugiej strony (miasta), i skruszenie wielkie od pagórków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Narzekajcie wy, którzy mieszkacie wewnątrz: bo wygładzony będzie wszystek lud kupiecki, wygładzeni będą wszyscy, którzy srebro noszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'I stanie się w on czas, że Jeruzalem szpiegować będę z pochodniami, i nawiedzę mężów, którzy polgnęli w drożdżach swoich, mówiąc w sercu swojem: Pan nie uczyni dobrze, ani źle uczyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Bo majętność ich przyjdzie na rozchwycenie, i domy ich na spustoszenie; pobudują domy, lecz w nich mieszkać nie będą; i będą sadzić winnice, ale z nich wina pić nie będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Bliski jest wielki dzień Pański, bliski jest i spieszny bardzo głos dnia Pańskiego; tam i mocarz gorzko wołać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Dzień gniewu będzie ten dzień, dzień utrapienia i ucisku, dzień zamięszania i spustoszenia, dzień ciemności i mroku, dzień obłoku i chmury;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Dzień trąby i trąbienia przeciwko miastom obronnym i przeciwko basztom wysokim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'W który ludzi utrapieniem ścisnę, że jako ślepi chodzić będą, ponieważ przeciwko Panu zgrzeszyli; i wylana będzie krew ich jako proch, a ciała ich jako gnój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Ani srebro ich, ani złoto ich nie będzie ich mogło wyrwać w dzień gniewu Pańskiego; bo ogniem zapalczywości jego będzie ta wszystka ziemia pożarta, przeto, że zapewne koniec prędki uczyni wszystkim obywatelom ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Wejrzyjcie w się, wejrzyjcie w się, mówię, o narody przemierzłe!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Pierwej, niżeli wyjdzie dekret, i niż dzień jako plewa przeminie; pierwej niż przyjdzie na was gniew zapalczywości Pańskiej, pierwej niż przyjdzie na was dzień gniewu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Szukajcie Pana wszyscy pokorni na ziemi, którzy sąd jego czynicie; szukajcie sprawiedliwości, szukajcie pokory, snać się ukryjecie w dzień zapalczywości Pańskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Bo Gaza opuszczona będzie, i Aszkalon spustoszony, Azot w południe wyrzucą, a Akkaron wykorzeniony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Biada mieszkającym w krainie pomorskiej, narodowi Ceretejczyków! słowo Pańskie przeciwko wam jest, o ziemio Chananejska Filystyńczyków! że cię tak wytracę, aby nie było obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'I będzie kraina pomorska owczarniami i budami pasterskiemi, i oborą dla trzód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Będzie też i ostatkowi domu Judzkiego krainą dla pasienia; w domach Aszkalon na wieczór legać będą, gdyż ich nawiedzi Pan, Bóg ich, i przywróci zaś więźniów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Słyszałem urąganie Moabczyków i hańbienia synów Amonowych, któremi urągali ludowi mojemu, i wynosili się na granicach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Przetoż jako żyję Ja, mówi Pan zastępów, Bóg Izraelski, że się Moab stanie jako Sodoma, a synowie Ammonowi jako Gomora, miejscem pokrzyw i jamą solną i pustynią aż na wieki; ostatki ludu mego rozchwycą ich, i pozostali z ludu mego osiędą ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'To ich spotka za pychę ich, iż lżyli i wynosili się nad lud Pana zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Straszny im będzie Pan, bo sprawi, że schudną wszyscy bogowie ziemi; i będzie mu się kłaniał każdy z miejsca swego, wszystkie wyspy narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'I wy też, Murzynowie! mieczem moim pobici będziecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Bo wyciągnę rękę moję na północy, i wytracę Assura, i podam Niniwę w spustoszenie i suszę, jako pustynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'I będą trzody legały w pośrodku jego, i wszystek zwierz narodów, i pelikan i sowa na gałkach jego przebywać będą, głos ptastwa w oknach słyszany będzie, podwoje jego spustoszeją, gdy cedrowe listwowania jego odedrą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Takieć będzie ono miasto weselące się, które siedzi bezpiecznie, mówiące w sercu swojem: Jam miasto, a oprócz mnie niemasz takiego. Jakoć się stało spustoszeniem! jaskinią zwierzowi! każdy przechodzący przez nie zaświśnie, i kiwać będzie ręką swo ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Biada temu miastu zmazanemu i splugawionemu, gwałty czyniącemu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Nie słucha głosu, ani przyjmuje karności, w Panu nie ufa, do Boga swego nie przybliża się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Książęta jego w pośrodku jego są lwy ryczące, sędziowie jego są wilki wieczorne, które nie gryzą kości aż do poranku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Prorocy jego skwapliwi, mężowie przewrotni; kapłani jego splugawili rzeczy święte, zakon gwałcą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Pan sprawiedliwy jest w pośród niego, nie czyni nieprawości, każdego dnia sąd swój wydaje na światłość bez przestania; wszakże złośnik wstydzić się nie umie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Wykorzeniłem narody, spustoszone są zamki ich, obróciłem w pustynię ulice ich, tak, że niemasz, ktoby przez nie chodził; spustoszone są miasta ich, tak, że niemasz ani człowieka ani obywatela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Rzekłem: Wżdyć się mnie bać będziesz, przyjmiesz karność, aby nie był wytracony przybytek twój, przez to, czemem cię nawiedzić chciał; ale rano wstawszy psują wszystkie przedsięwzięcia swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Przetoż oczekiwajcie na mię, mówi Pan, do dnia, którego powstanę do łupu; bo sąd mój jest, abym zebrał narody, i zgromadził królestwa, abym na nie wylał rozgniewanie moje i wszystkę popędliwość gniewu mego; ogniem zaiste gorliwości mojej będzie po żarta ta wszystka ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Bo na ten czas przywrócę narodom wargi czyste, któremiby wzywali wszyscy imienia Pańskiego, a służyli mu jednomyślnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Ci, którzy są za rzekami ziemi Murzyńskiej, pokłon mi oddają z córką rozproszonych moich, przyniosą mi dary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Dnia onego nie zawstydzisz się za żadne uczynki twoje, któremiś wystąpiło przeciwko mnie; bo na ten czas odejmę z pośrodku ciebie tych, którzy się weselą z sławy twojej, a nie będziesz się więcej wywyższało na górze świętobliwości mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'I zostawię w pośrodku ciebie lud ubogi a nędzny, i ufać będą w imieniu Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Ostatki Izraela nie będą czyniły nieprawości, ani będą mówiły kłamstwa, ani się znajdzie w ustach ich język zdradliwy; ale się paść będą i odpoczywać, a nie będzie, ktoby je przestraszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Zaśpiewaj, córko Syońska! wykrzykajcie, Izraelczycy! wesel się a raduj się ze wszystkiego serca, córko Jeruzalemska!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Że odjął Pan sądy twoje, uprzątnął nieprzyjaciela twego; król Izraelski jest Panem w pośrodku ciebie, nie oglądasz więcej złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'Dnia onego rzeką do Jeruzalemu: Nie bój się! a do Syonu: Niech nie mdleją ręce twoje!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Pan, Bóg twój, w pośrodku ciebie mocny zachowa cię, rozweseli się wielce nad tobą, przestanie na miłości swej przeciwko tobie, i rozweseli się nad tobą z śpiewaniem, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Tęskniących po Jeruzalemie zasię zgromadzę, bo z ciebie są i smutni dla brzemienia zelżywości włożonej na cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Oto Ja koniec uczynię wszystkim, którzy cię trapić będą na on czas, a zachowam chromą, i wygnaną zgromadzę; owszem sposobię im chwałę i imię po wszystkiej ziemi, w której zelżywość ponosili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Wtenczas przywiodę was, wtenczas, mówię, zgromadzę was; albowiem dam wam imię i chwałę między wszystkimi narodami ziemi, gdy zaś przywiodę więźnie wasze przed oczyma waszemi, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Roku wtórego Daryjusza króla, miesiąca szóstego, dnia pierwszego tegoż miesiąca, stało się słowo Pańskie przez Aggieusza proroka do Zorobabela, syna Salatyjelowego, książęcia Judzkiego, i do Jesuego, syna Jozedekowego, kapłana najwyższego, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Tak powiada Pan zastępów, mówiąc: Ten lud mówi: Jeszcze nie przyszedł czas, czas budowania domu Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Przetoż się stało słowo Pańskie przez Aggieusza proroka, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Izali wam jest czas, abyście mieszkali w domach waszych listwowanych, a dom ten aby pusty stał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Teraz tedy tak mówi Pan zastępów: Uważajcież, jako się wam powodzi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Siejecie wiele, a mało zbieracie; jecie, ale się nie nasycacie; pijecie, ale nie ugaszacie pragnienia; obłóczycie się, ale się nikt nie może zagrzać, a ten, co sobie zapłatę zgromadza, zgromadza ją do worka dziurawego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Tak mówi Pan zastępów: Uważajcie, jako się wam powodzi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Wstąpcie na tę górę, i zwoźcie drzewo; budujcie ten dom, a zakocham się w nim, i będę uwielbiony, mówiPan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Poglądacie na wiele, a oto, mało dostawacie, a co wnosicie do domu, to Ja rozdmuchywam; dlaczego? mówi Pan zastępów; dlatego, że dom mój jest pusty, a międzytem się każdy z was stara o dom swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Przetoż się nad wami niebo zawarło, aby rosy nie dawało; ziemia także zawarła się, aby nie wydawała urodzaju swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'A tak przyzwałem suszę na tę ziemię, i na te góry, i na pszenicę, i na moszcz, i na oliwę, i na to, coby miała wydać ziemia, i na ludzi i na bydło, i na wszystkę pracę ręczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Tedy usłuchał Zorobabel, syn Salatyjelowy, i Jesua, syn Jozedekowy, kapłan najwyższy, i wszystkie ostatki ludu, głosu Pana, Boga swego, i słów Aggieusza proroka, ponieważ go posłał Pan, Bóg ich; bo się lud bał oblicza Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Tedy Aggieusz, poseł Pański, rzekł do ludu, będąc w poselstwie Pańskiem, mówiąc: Jam z wami, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Wtem wzbudził Pan ducha Zorobabela, syna Salatyjelowego, książęcia Judzkiego, i ducha Jesuego, syna Jozedekowego, kapłana najwyższego, i ducha ostatków wszystkiego ludu, że przyszedłszy robili około domu Pana zastępów, Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Dnia dwudziestego i czwartego, miesiąca szóstego, roku wtórego Daryjusza króla;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Siódmego miesiąca, dwudziestego i pierwszego dnia tegoż miesiąca stało się słowo Pańskie przez Aggieusza proroka, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Mów teraz do Zorobabela, syna Salatyjelowego, książęcia Judzkiego, i do Jesuego, syna Jozedekowego, kapłana najwyższego, i do ostatku ludu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Któż między wami pozostał, co widział ten dom w sławie pierwszej jego? I jaki wy teraz widzicie? Izali nie jest przeciwko onemu jako nic w oczach waszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Jednak teraz zmocnij się Zorobabelu! mówi Pan; zmocnij się, Jesue, synu Jozedekowy, kapłanie najwyższy! zmocnij się też wszystek ludu tej ziemi, mówi Pan, a róbcie; bom Ja z wami, mówi Pan zastępów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Według słowa, któremem przymierze uczynił z wami, gdyście wychodzili z Egiptu; duch także mój stanie w pośrodku was, nie bójcież się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Bo tak mówi Pan zastępów: Oto Ja jeszcze raz, a to po małym czasie, poruszę niebem i ziemią, i morzem i suchą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Poruszę, mówię, wszystkie narody, i przyjdą do Pożądanego od wszystkich narodów; i napełnię ten dom chwałą, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Mojeć jest srebro, i moje złoto, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Większa będzie sława domu tego pośledniego, niż onego pierwszego, mówi Pan zastępów; bo na tem miejscu dam pokój, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Dwudziestego i czwartego dnia, dziewiątego miesiąca, roku wtórego Daryjusza, stało się słowo Pańskie przez Aggieusza proroka, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Tak mówi Pan zastępów: Pytaj się teraz kapłanów o zakon, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Gdyby kto niósł mięso poświęcone w podołku sukni swej, alboby się dotknął podołkiem swoim chleba, albo potrawy, albo wina, albo oliwy, albo wszelkiego pokarmu, izali się poświęci? I odpowiedzieli kapłani a rzekli: Nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Tedy rzekł Aggieusz: Jeźli kto będąc nieczysty od trupa, dotknąłby się czego z tych rzeczy, będzieli nieczyste? I odpowiedzieli kapłani i rzekli: Będzie nieczyste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Tedy odpowiadając Aggieusz rzekł: Takci lud ten, tak i naród ten przed obliczem mojem, mówi Pan, tak i wszystka sprawa rąk ich, i cokolwiek tam ofiarowali, nieczyste było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'A tak uważajcież, proszę, jako się wam powodziło od tego dnia aż do onego, kiedy przestano kłaść kamienia na kamieniu w kościele Pańskim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Od tego czasu, gdy kto przyszedł do gromady zboża, od dwudziestu korcy znalazł dziesięć; gdy przyszedł do prasy, aby naczerpał pięćdziesiąt wiader wina, znalazł tylko dwadzieścia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Karałem was zarazą zbóż i rdzą, i gradem wszystkie prace rąk waszych; wszakże żaden z was nie wrócił się do mnie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Uważajcież teraz ode dnia tego aż do onego, ode dnia dwudziestego i czwartego miesiąca dziewiątego aż do dnia, którego był założony kościół Pański, uważajcie, mówię:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Izali jeszcze jest nasienie w szpichlerzu? I owszem, ani macica winna, ani figowe ani granatowe ani oliwne drzewo nie wydały owocu; lecz ode dnia tego będę błogosławił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Potem stało się słowo Pańskie powtóre do Aggieusza dnia dwudziestego i czwartego tegoż miesiąca, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Mów do Zorobabela, książęcia Judzkiego, a rzecz: Ja poruszę niebiosa i ziemię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'I podwrócę stolice królestw, i zepsuję moc królestw pogańskich; podwrócę, mówię, wóz, i tych, którzy na nim jeżdżą, i upadną konie i jeżdżący na nich, każdy od miecza brata swego. W on dzień, mówi Pan zastępów, wezmę cię, Zorobabelu, synu Salatyjelowy, sługo mój! mówi Pan, i uczynię cię jako sygnet; albowiem wybrałem cię, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Miesiąca ósmego roku wtórego Daryjusza stało się słowo Pańskie do mnie Zacharyjasza, syna Barachyjaszowego, syna Iddowego, proroka, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Rozgniewał się Pan na ojców waszych bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Przetoż rzecz do nich: Tak mówi Pan zastępów: Nawróćcie się do mnie, mówi Pan zastępów, a nawrócę się do was, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Nie bądźcież jako ojcowie wasi, na których wołali ojcowie pierwsi, mówiąc: Tak mówi Pan zastępów: Nawróćcież się teraz od złych dróg waszych, i od złych spraw waszych; ale nie usłuchali, ani dbali na mię, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Gdzież są ojcowie wasi, i prorocy? Izali na wieki żyć będą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Wszakże izali słowa moje i ustawy moje, którem rozkazał prorokom, sługom moim, nie zasięgły ojców waszych? tak, że nawróciwszy się rzekli: Jako nam Pan zastępów uczynić umyślił według dróg naszych i według uczynków naszych, tak nam uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Dnia dwudziestego i czwartego jedenastego miesiąca (ten jest miesiąc Sebat) roku wtórego Daryjuszowego stało się słowo Pańskie do Zacharyjasza, syna Barachyjaszowego, syna Iddowego, proroka, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Widziałem w nocy, a oto mąż jechał na koniu rydzym, który stał między mirtami, które były w nizinie, a za nim konie rydze, czarne i białe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Tedym rzekł: Co zacz są ci, panie mój? I rzekł do mnie Anioł rozmawiający zemną: Ja tobie okażę, co zacz są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'I odpowiedział mąż, który stał między mirtami, i rzekł: Ci są, których posłał Pan, aby przeszli ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'I odpowiedzieli Aniołowi Pańskiemu stojącemu między mirtami, i rzekli: Przeszliśmy ziemię, a oto wszystka ziemia bezpieczeństwa i pokoju używa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Tedy odpowiedział Anioł Pański, i rzekł: O Panie zastępów! i dokądże się nie zmiłujesz nad Jeruzalemem, i nad miastami Judzkiemi, na któreś się gniewał już siedmdziesiąt lat?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'I odpowiedział Pan Aniołowi onemu, który mówił zemną, słowy dobremi, słowy pociesznemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'I rzekł do mnie Anioł, który mówił zemną: Wołaj a rzecz: Tak mówi Pan zastępów: Zapaliłem się za Jeruzalemem i za Syonem gorliwością wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'A gniewam się bardzo na te narody, które używają pokoju; bo gdym się Ja trochę zagniewał, tedy one pomagały do złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Przetoż tak mówi Pan: Nawróciłem się do Jeruzalemu w miłosierdziu, dom mój zbudowany będzie w niem, mówi Pan zastępów, i sznur rozciągniony będzie na Jeruzalem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Jeszcze wołaj, mówiąc: Tak mówi Pan zastępów: Jeszcze się osadzą miasta moje dla obfitości dobrego; bo jeszcze Pan Syon pocieszy, i obierze jeszcze Jeruzalem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'Tedym podniósł oczy swe i ujrzałem, a oto cztery rogi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'I rzekłem do Anioła, który mówił zemną: Cóż to jest? I rzekł do mnie: Teć są rogi, które rozrzuciły Judę i Izraela i Jeruzalem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Ukazał mi też Pan czterech kowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'I rzekłem: Cóż ci idą czynić? I odpowiedział, mówiąc: Teć są rogi, które rozrzuciły Judę, tak, iż żaden nie mógł podnieść głowy swojej; przetoż ci przyszli, aby je przestraszyli, i strącili rogi tych narodów, które podniosły róg przeciwko ziemi Judzkiej, aby ją rozrzuciły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Potem podniosłem oczy swoje i ujrzałem, a oto mąż, w którego ręce był sznur pomiarowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'I rzekłem: Dokąd idziesz? I rzekł do mnie: Abym rozmierzył Jeruzalem, i obaczył, jako wielka jest szerokość jego, i jako wielka długość jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'A oto gdy on Anioł, który rozmawiał zemną, wychodził, inszy Anioł wychodził przeciwko niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'I rzekł do niego: Bież, rzecz do tego młodzieńca, mówiąc: Jeruzalemczycy po wsiach mieszkać będą dla mnóstwa ludu i bydła w pośrodku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'A ja będę, mówi Pan, murem jego ognistym w około, i będę sławą w pośrodku jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Nuże, nuże! Ucieczcie już z ziemi północnej, mówi Pan, ponieważ na cztery strony świata, mówi Pan, rozproszyłem was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Nuże Syonie! który mieszkasz u córki Babilońskiej, wyswobódź się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Bo tak mówi Pan zastępów: Posłał mię po sławę przeciwko tym narodom, którzy was złupili; bo kto się was dotyka, dotyka się źrenicy oka mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Albowiem oto Ja podniosę rękę moję przeciwko nim, i będą łupem sługom swoim, a dowiecie się, iż mię Pan zastępów posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Zaśpiewaj a rozraduj się, córko Syońska! bo oto Ja przyjdę, a mieszkać będę w pośrodku ciebie, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'I przyłączy się w on dzień wiele narodów do Pana, i będą ludem moim, i będę mieszkał w pośród ciebie, a dowiesz się, iż Pan zastępów posłał mię do ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Tedy Pan Judę weźmie w osiadłość za dział swój w ziemi świętej, i obierze zaś Jeruzalem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Niech umilknie wszelkie ciało przed obliczem Pańskiem; albowiem się ocuci z mieszkania świętobliwości swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Zatem mi okazał Jesuego, kapłana najwyższego, stojącego przed Aniołem Pańskim, i szatana stojącego po prawicy jego, aby mu się sprzeciwił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Ale Pan rzekł do szatana: Niech cię Pan zgromi, szatanie! niech cię, mówię, zgromi Pan, który obrał Jeruzalem. Izali ten nie jest jako głownia wyrwana z ognia?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Ale Jesua był obleczon w szatę plugawą, a stał przed Aniołem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'A odpowiadając rzekł do tych, którzy stali przed nim, mówiąc: Zdejmijcie tę szatę plugawą z niego. I rzekł do niego: Otom przeniósł z ciebie nieprawość twoję, a oblekłem cię w szaty odmienne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Znowu rzekł: Niech włożą piękną czapkę na głowę jego; i włożyli piękną czapkę na głowę jego, i oblekli go w szaty, a Anioł Pański stał przytem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'I oświadczał się Anioł Pański przed Jesuem, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Tak mówi Pan zastępów: Jeźli drogami mojemi chodzić będziesz, a jeźli ustaw moich przestrzegać będziesz, tedy też ty będziesz sądził dom mój, i będziesz strzegł sieni moich; i dam ci to zapewne, abyś chodził między tymi, którzy tu stoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Słuchajże tedy teraz, Jesue, kapłanie najwyższy! ty i towarzysze twoi, którzy siedzą przed tobą: Aczkolwiek ci mężowie są dziwem, wszakże oto Ja przywiodę sługę mego Latorośl.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Albowiem oto ten kamień, który kładę przed Jesuego, na ten kamień jeden obrócone będą siedm oczów; oto Ja wyrzeżę na nim rzezanie, mówi Pan zastępów, a odejmę nieprawość tej ziemi, dnia jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'Dnia onego, mówi Pan zastępów, wezwie każdy bliźniego swego pod macicę winną i pod figowe drzewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Potem nawrócił się Anioł, który mówił zemną, i obudził mię, jako gdy kto budzony bywa ze snu swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'I rzekł do mnie: Cóż widzisz? I rzekłem: Widzę, a oto świecznik wszystek złoty, a czasza na wierzchu jego, i siedm lamp jego na nim, siedm też nalewek do onych siedmiu lamp, które są na wierzchu jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Dwie też oliwy przytem, jedna po prawej stronie czaszy, a druga po lewej stronie jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Tedy odpowiadając rzekłem do Anioła, który mówił zemną, mówiąc: Cóż to jest, panie mój?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'I odpowiedział Anioł, który mówił zemną, i rzekł mi: Izaż nie wiesz, co to jest? I rzekłem: Nie wiem, panie mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Tedy odpowiadając rzekł do mnie, mówiąc: Toć jest słowo Pańskie do Zorobabela mówiące: Nie wojskiem ani siłą stanie się to, ale duchem moim, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Cóżeś ty jest,o góro wielka! przeciwko Zorobabelowi? Równina; bo on wywiedzie kamień główny z głośnym okrzykiem: Łaska, łaska nad nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Ręce Zorobabelowe założyły dom ten, i ręce jego dokonają go; a dowiesz się, że Pan zastępów posłał mię do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Bo któżby wzgardził dniem małych początków? ponieważ się weselą, patrząc na ten kamień, to jest, na prawidło w ręce Zorobabelowej, na te siedm oczów Pańskich przechodzących wszystkę ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Tedy odpowiadając rzekłem mu: Cóż są te dwie oliwy po prawej stronie tego świecznika, i po lewej stronie jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Znowu odpowiadając rzekłem mu: Cóż są te dwie oliwki, które są między dwoma rurkami złotemi, które z siebie złoto wylewają?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Tedy rzekł do mnie, mówiąc: Izali nie wiesz, co to jest? Rzekłem: Nie wiem, Panie mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'I rzekł: Teć są one dwie oliwy, które są u Panującego na wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Potemem się obrócił, a podniósłszy oczu swych ujrzałem, a oto księga leciała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'I rzekł do mnie: Cóż widzisz? I rzekłem: Widzę księgę lecącą, której długość na dwadzieścia łokci, a szerokość na dziesięć łokci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'I rzekł do mnie: Toć jest przeklęstwo, które wyjdzie na oblicze wszystkiej ziemi: bo każdy złodziej według tego przeklęstwa, jako i ta ziemia, wygładzony, i każdy fałszywie przysięgający według niego, jako i ona, wygładzony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Wywiodę je, mówi Pan zastępów, aby przyszło na dom złodzieja, i na dom kłamliwie przez imię moje przysięgającego; owszem, mieszkać będzie w pośrodku domu jego, i zniszczy go, i drzewo jego i kamienie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Wyszedł tedy Anioł on, który zemną mówił, i rzekł mi: Podnieśże teraz oczu swych, a obacz, co to jest, co wychodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'I rzekłem: Cóż jest? A on odpowiedział: To jest efa wychodzące. Potem rzekł: Toć jest oko ich przypatrujące się wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'A oto sztukę ołowiu niesiono, a przytem była niewiasta jedna, która siedziała w pośrodku efa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Tedy rzekł Anioł: Toć jest ona niezbożność; i wrzucił ją w pośród efa, wrzucił i onę sztukę ołowiu na wierzch efy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'A podniósłszy oczu swych ujrzałem, a oto dwie niewiasty wychodziły, mające wiatr w skrzydłach swych, a miały skrzydła, jako skrzydła bocianie, i podniosły ono efa między ziemię i między niebo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Tedym rzekł do onego Anioła, który mówił zemną: Dokądże niosą to efa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'I rzekł do mnie: Aby mu zbudowano dom w ziemi Senaar, gdzieby umocnione było i postawione na podstawku swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Potem obróciwszy się podniosłem oczu swych i ujrzałem, a oto cztery wozy wychodziły z pośrodku dwóch gór, a góry one były góry miedziane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'W pierwszym wozie były konie rydze, a w drugim wozie konie wrone (kare):');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'W trzecim wozie konie białe, a w czwartym wozie były konie strokate, a wszystkie mocne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Tedy odpowiadając rzekłem do Anioła, który mówił zemną: Co to jest, Panie mój?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'I odpowiedział Anioł a rzekł do mnie: Te są cztery wiatry niebieskie, wychodzące z miejsca, gdzie stały, przed panującym nad wszystką ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Konie wrone zaprzężone wychodzą do ziemi północnej, a białe wychodzą za nimi, strokate zaś wychodzą do ziemi południowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Te tedy mocne konie wyszedłszy chciały iść, aby obeszły ziemię; tedy rzekł: Idźcie, a obejdźcie ziemię! I obeszły ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'A zawoławszy mię rzekł do mnie, mówiąc: Oto te, które wyszły do ziemi północnej, uspokoiły ducha mego w ziemi północnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'I stało się słowo Pańskie do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Weźmij od tych, co byli pojmani od Cheldajego i od Tobijasza, i od Jedajasza; (a ty przyjdziesz tegoż dnia, i wnijdziesz do domu Josyjasza, syna Sofonijaszowego) którzy idą z Babilonu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Weźmij, mówię, srebro i złoto, a uczyń korony, a włóż je na głowę Jesuego, syna Jozedekowego, kapłana najwyższego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'I rzecz do niego, mówiąc: Tak powiada Pan zastępów, mówiąc: Oto mąż, którego imię jest Latorośl, który z miejsca swego wyrośnie, ten wystawi kościół Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Bo ten ma wystawić kościół Panu, ten zaś przyniesie sławę, i siedzieć i panować będzie na stolicy swojej, i będzie kapłanem na stolicy swojej, a rada pokoju będzie między nimi obiema.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'A te korony zostaną Chelemowi, i Tobijaszowi, i Jedajaszowi, i Chenowi, synowi Sofonijaszowemu, na pamiątkę w kościele Pańskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Bo dalecy przyjdą, a będą budować kościół Pański; i dowiecie się, że Pan zastępów posłał mię do was; a to się stanie, jeźli pilnie słuchać będziecie głosu Pana, Boga swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Potem stało się roku czwartego Daryjusza króla, stało się słowo Pańskie do Zacharyjasza dnia czwartego, miesiąca dziewiątego, który jest Kislew;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Gdy posłał lud do domu Bożego Sarassara i Regiemmelecha, i mężów jego, aby się modlili przed obliczem Pańskiem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'I aby mówili do kapłanów, którzy byli w domu Pana zastępów, także i do proroków, mówiąc: Izali jeszcze płakać będę miesiąca piątego, wyłączywszy się tak, jakom już czynił przez kilka lat?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'I stało się słowo Pana zastępów do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Rzecz do wszystkiego ludu tej ziemi, i do kapłanów, mówiąc: Gdyście pościli i płakali piątego i siódmego miesiąca przez te siedmdziesiąt lat, izażeście mnie, mnie, mówię, post pościli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'A gdy jecie albo pijecie, izali nie sobie jecie i nie sobie pijecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Izaliście nie tak czynić mieli według słowa, które przepowiedział Pan przez proroków przeszłych, gdy jeszcze Jeruzalem bezpieczeństwa i pokoju używało, i miasta jego około niego, i lud w stronie południowej i po polach mieszkał (w pokoju?)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'I stało się słowo Pańskie do Zacharyjasza, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Tak powiedział Pan zastępów, mówiąc: Sprawiedliwie sądźcie, a miłosierdzie i litość pokazujcie każdy nad bliźnim swoim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'A wdowy i sieroty, i przychodnia, i ubogiego nie uciskajcie, i złego jeden przeciwko drugiemu nie myślcie w sercu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Ale nie chcieli dbać; i obrócili się tyłem, a uszy swe zatulili, aby nie słuchali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Serca też swe zatwardzili jako dyjament, aby nie słuchali zakonu tego i słów, które posyłał Pan zastępów duchem swoim przez proroków przeszłych, skąd przyszedł wielki gniew od Pana zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Bo jako oni, gdy ich wołano, nie słuchali, tak też, gdy oni wołali, nie wysłuchałem, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'I rozproszyłem ich jako wicher między wszystkie narody, które nie znali, i ta ziemia spustoszała po nich, tak, że nie był przechodzący i wracający się, a tak ziemię pożądaną w spustoszenie obrócili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Potem stało się słowo Pana zastępów, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Tak mówi Pan zastępów: Zapaliłem się nad Syonem gorliwością wielką, owszem, rozgniewaniem wielkiem zapaliłem się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Tak mówi Pan: Nawróciłem się do Syonu, i mieszkam w pośród Jeruzalemu, aby Jeruzalem zwano miastem wiernem, a górę Pana zastępów, górą świętobliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Tak mówi Pan zastępów: Jeszcze siadać będą starcy i baby na ulicach Jeruzalemskich, mając każdy z nich laskę w ręce swej dla zeszłości wieku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Ulice także miasta pełne będą chłopiąt i dziewcząt grających na ulicach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Tak mówi Pan zastępów: Izali, że się to niepodobna widzi przed oczyma ostatków ludu tego tych dni, będzie też to niepodobna przed oczyma mojemi? mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Tak mówi Pan zastępów: Oto Ja wybawię lud mój z ziemi na wschód, i z ziemi na zachód słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'I przywiodę ich zaś; a będą mieszkać w pośród Jeruzalemu, i będą ludem moim, a Ja będę Bogiem ich w prawdzie i w sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Tak mówi Pan zastępów: Niech się zmocnią ręce wasze, którzyście słuchali w tych dniach słów tych z ust proroków, którzy byli ode dnia, którego założony jest dom Pana zastępów, że kościół ma być dobudowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Bo się przed temi dniami praca ludzka i praca bydląt nie nagradzała, nawet wychodzącemu i wchodzącemu nie było pokoju dla nieprzyjaciela; bom Ja spuścił wszystkich ludzi jednego z drugim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Lecz teraz nie tak jako za dni przeszłych czynię ostatkowi ludu tego, mówi Pan zastępów:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Ale siewy macie spokojne; winna macica wydaje owoc swój, i ziemia wydaje urodzaj swój, niebiosa także wydawają rosę twoję, a to wszystko daję w osiadłość ostatkom ludu tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'I stanie się, że jakoście byli przeklęstwem między poganami, o domie Judzki i domie Izraelski! tak was zaś będę ochraniał, i będziecie błogosławieństwem; nie bójcie się, niech się zmacniają ręce wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Bo tak mówi Pan zastępów: Jakom wam był umyślił źle uczynić, gdy mię do gniewu pobudzali ojcowie wasi, mówi Pan zastępów, a nie żałowałem tego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'Tak nawróciwszy się umyśliłem w te dni dobrze czynić Jeruzalemowi i domowi Judzkiemu; nie bójcież się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Teć są rzeczy, które czynić będziecie: Prawdę mówcie każdy z bliźnim swoim, prawy i spokojny sąd czyńcie w bramach waszych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'A jeden drugiemu nic złego nie myślcie w sercach waszych, a w krzywoprzysięstwie się nie kochajcie; bo to wszystko jest, czego nienawidzę, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'I stało się słowo Pana zastępów do mnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Tak mówi Pan zastępów: Post czwartego, i post piątego, i post siódmego, i post dziesiątego miesiąca obróci się domowi Judzkiemu w radość i wesele, i w rozkoszne uroczyste święta; ale prawdę i pokój miłujcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Tak mówi Pan zastępów: Jeszczeć będą przychodzić narody i obywatele wielu miast;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'Przychodzić, mówię, będą obywatele jednego miasta do drugiego, mówiąc: Pójdźmy ochotnie błagać oblicze Pańskie, a szukać Pana zastępów; i rzecze każdy: Pójdę i ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'A tak wiele ludu i narodów niezliczonych przyjdzie szukać Pana zastępów w Jeruzalemie, i błagać oblicze Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Tak mówi Pan zastępów: W one dni uchwycą się dziesięć mężów ze wszystkich języków onych narodów; uchwycą się, mówię, podołka jednego Żyda, mówiąc: Pójdziemy z wami, bo słyszymy, że Bóg jest z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Brzemię słowa Pańskiego przeciwko ziemi, która jest w około ciebie, a Damaszek będzie odpocznieniem jego; albowiem oko Pańskie przypatruje się ludziom i wszystkim pokoleniom Izraelskim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'Nawet i do Emat dosięże, i do Tyru i do Sydonu, choć jest mądry bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Bo sobie Tyr obronę zbudował, i nazbierał srebra jako prochu, a złota jako błota po ulicach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Oto Pan go wypędzi, a wrazi w morze siłę jego, a sam od ognia pożarty będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Co widząc Aszkalon, ulęknie się, także Gaza wielce żałośne będzie, i Akaron, przeto, że je zawstydziła nadzieja ich; i zginie król z Gazy, a Aszkalon nie będzie osadzone;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'I będzie mieszkał bękart w Azocie, a tak wykorzenię pychę Filistyńczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'I odejmę krew każdego od ust jego, i obrzydliwości jego od zębów jego; zostawiony też będzie i on Bogu naszemu, aby był jako książę w Judzie, a Akaron jako Jebuzejczycy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'I położę się obozem u domu swego dla wojska, i dla przechodzącego a wracającego się; i nie przejdzie więcej przez nich łupieżca, przeto, że się tak teraz podoba w oczach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Wesel się bardzo, córko Syońska! wykrzykaj, córko Jeruzalemska! Oto król twój przyjdzie tobie sprawiedliwy i zbawiciel ubogi i siedzący na ośle, to jest, na oślęciu, źrebiątku oślicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Bo wytracę wozy z Efraima, i konie z Jeruzalemu, i będzie połamany łuk wojenny; i ogłosi pokój narodom, a władza jego (będzie) od morza aż do morza, i od rzeki aż do kończyn ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Owszem, ty wesel się dla krwi przymierza swego; albowiem wypuściłem więźniów twoich z dołu, w którym niemasz wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Wróćcież się tedy do twierdzy, o więźniowie, którzy nadzieję macie! albowiemci i dziś dwojako opowiadam i nagrodzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Gdyż sobie naciągnę Judę, a łuk napełnię Efraimem; i wzbudzę synów twoich, o Syonie! przeciwko synom twoim, o Jawanie! i zgotuję cię jako miecz mocarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Bo się Pan ukaże przeciwko nim, a jako blask wyniknie strzała jego; panujący, mówię, Pan zatrąbi w trąbę, a pójdzie w wichrach południowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Pan zastępów ochraniać będzie lud swój, aby podbiwszy sobie kamienie z procy, jedli i pili wykrzykając jako od wina; i napełnią, jako miednice, tak i rogi ołtarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'A tak wybawi ich dnia onego Pan, Bóg ich, jako trzodę ludu swego; bo kamienie wieńcami ozdobione, wystawione będą miasto chorągwi w ziemi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Albowiem oto o jakie błogosławieństwo jego! i jako wielka ozdoba jego! Zboże młodzieńców, a moszcz panny mowne uczyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Żądajcie od Pana dżdżu czasu potrzebnego, a Pan uczyni obłoki dżdżyste, a deszcz obfity da wam i każdemu trawę na polu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Bo obrazy mówią próżność, a wieszczkowie prorokują kłamstwo i sny próżne opowiadają, daremnie cieszą; dlatego poszli w niewolę, jako trzoda, utrapieni są, że nie mieli pasterza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Przeciwko takim pasterzom zapaliła się popędliwość moja, a te kozły nawiedzę; ale trzodę swoję, dom Judzki, nawiedzi Pan zastępów, i wystawi ich jako ubranego konia do boju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Od niego węgiel, od niego gwóźdź, od niego łuk wojenny, od niego także wynijdzie wszelki poborca;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'I będą jako mocarze depczący w błoto po ulicach w bitwie, i walczyć będą, bo Pan z nimi; a zawstydzą tych, którzy wsiadaja na koń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'I umocnię dom Judowy, a dom Józefowy wybawię, i w pokoju ich osadzę, bo mam litość nad nimi; i będą, jakobym ich nie odrzucił; bom Ja jest Pan, Bóg ich, a wysłucham ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'I będą Efraimczycy jako mocarz, a rozweseli się jako od wina serce ich; a synowie ich widząc to weselić się będą, i rozraduje się serce ich w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Zaświsnę na nich, a zgromadzę ich, bo ich odkupię; i będą rozmnożeni, jako przedtem rozmnożeni byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'I rozsieję ich między narody, aby na miejscach dalekich wspomnieli na mię, a żywi będąc z synami swoimi nawrócili się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'A tak ich przywiodę z ziemi Egipskiej, i z Assyryi zgromadzę ich, a do ziemi Galaad i do Libanu przywiodę ich; ale im miejsca stawać nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Przetoż dla ciasności przez morze przejdzie, i rozbije na morzu wały, i wyschną wszystkie głębokości rzeki; tedy będzie zniżona pycha Assyryi, a sceptr od Egiptu odjęty będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Zmocnię ich też w Panu, a w imieniu jego chodzić będą, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Otwórz, Libanie! wrota swe, niech pożre ogień cedry twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Rozkwil się jodło! bo upadł cedr, bo wielmożni spustoszeni są; kwilcie dęby Basańskie, bo wycięty jest las ogrodzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Głos narzekania pasterzy słyszany jest, iż zburzona jest wielmożność ich; głos ryku lwiąt, iż zburzona jest pycha Jordanu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Tak mówi Pan, Bóg mój: Paś owce na rzeź zgotowane;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Które dzierżawcy ich zabijają, a nie bywają obwinieni, i owszem, sprzedawający je mówią: Błogosławiony Pan, żeśmy się zbogacili, a którzy je pasą, nie mają litości nad niemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Przetoż nie sfolguję więcej obywatelom tej ziemi, mówi Pan; bo oto Ja podam tych ludzi każdego w rękę bliźniego jego, i w rękę króla ich, i potrą ziemię, a nie wyrwie jej z rąk ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Bom pasł owce zgotowane na rzeź, was, mówię, o nędzne owce! i wziąwszy sobie dwie laski, jednęm nazwał Uciechą, a drugąm nazwał Związujących, a pasłem one owce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'I zgładziłem trzech pasterzy w jednym miesiącu; ale utęskniła sobie dusza moja z nimi, przeto, że dusza ich brzydziła się mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Rzekłem tedy: Nie będęć was pasł; co zdycha, niech zdechnie, a co ma być wygładzone, niech będzie wygładzone, a które pozostaną, niech pożera mięso jedna drugiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Przetoż wziąwszy laskę moję Uciechy, porąbałem ją, wzruszywszy przymierze moje, którem postanowił z tym wszystkim ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'A dnia onego, gdy wzruszone było, pewnie poznali nędzni z trzody, którzy się na mię oglądali, że to słowo Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Bom rzekł do nich: Jeźli to jest dobre w oczach waszych, dajcie zapłatę moję, a jeźli nie, zaniechajcież; tedy odważyli zapłatę moję trzydzieści srebrników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Zatem rzekł Pan do mnie: Porzuć je przed garncarza; zacnaż to zapłata, którąm jest od nich tak drogo oszacowany! Wziąłem tedy trzydzieści srebrników, a porzuciłem je w domu Pańskim przed garncarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Potem porąbałem laskę moję drugą Związujących, wzruszywszy braterstwo między Judą i między Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'I rzekł Pan do mnie: Weźmij sobie jeszcze oręż pasterza głupiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Bo oto Ja wzbudzę pasterza w tej ziemi, który nie będzie obłąkanych nawiedzał, ani będzie jagniątek szukał, złamanego też leczyć, i tego, co ustanie, nosić nie będzie; ale mięso tłustych jeść będzie, a kopyta ich postrąca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Biada pasterzowi niepożytecznemu, który opuszcza trzodę! miecz nad ramieniem jego i nad prawem okiem jego; ramię jego cale uschnie, a prawe oko jego cale zaćmione będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Brzemię słowa Pańskiego nad Izraelem. Tak mówi Pan, który rozpostarł niebiosa, a ugruntował ziemię, który tworzy ducha człowieczego we wnętrznościach jego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Oto Ja postawię Jeruzalem kubkiem opojenia wszystkim narodom okolicznym, którzy będą przeciwko Judzie na oblężenie, i przeciwko Jeruzalemowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Owszem, stanie się dnia onego, że uczynię Jeruzalem kamieniem ciężkim wszystkim narodom; wszyscy, którzy go dźwigać będą, bardzo się urażą, choćby się zgromadziły przeciwko niemu wszystkie narody ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Dnia onego, mówi Pan, zarażę każdego konia zdrętwieniem i jeźdźca jego szaleństwem; ale nad domem Juda otworzę oczy moje, a każdego konia narodów zarażę ślepotą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'I rzekną książęta Judzcy w sercu swem: Mamy siłę i obywatele Jeruzalemscy w Panu zastępów, Bogu swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'Dnia onego położę książąt Judzkich jako węgle ogniste między drwy, a jako pochodnię gorejącą między snopy; i pożrą na prawą i na lewą stronę wszystkie narody okoliczne, i zostanie jeszcze Jeruzalem na miejscu swem w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Zachowa Pan i namioty Judzkie pierwej, aby się nie wywyższała chwała domu Dawidowego, i chwała obywateli Jeruzalemskich przeciwko Judzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'Dnia onego Pan będzie bronił obywateli Jeruzalemskich, a któryby był między nimi najsłabszy, stanie się dnia onego podobny Dawidowi, a dom Dawidowy podobny bogom, podobny Aniołowi Pańskiemu przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Bo się stanie dnia onego, że szukać będę wszystkie narody, które przyciągną przeciwko Jeruzalemowi, abym je wytracił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'I wyleję na dom Dawidowy, i na obywateli Jeruzalemskich Ducha łaski i modlitw, a patrzyć będą na mię, którego przebodli; i płakać będą nad nim płaczem, jako nad jednorodzonym; gorzko, mówię, płakać będą nad nim, jako gorzko płaczą nad pierworodnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Dnia onego będzie wielkie kwilenie w Jeruzalemie, jako kwilenie w Adadrymon na polu Magieddon;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Bo ziemia kwilić będzie, każde pokolenie osobno, pokolenie domu Dawidowego osobno, i niewiasty ich osobno; pokolenie domu Natanowego osobno, i niewiasty ich osobno;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'Pokolenie domu Lewiego osobno, i niewiasty ich osobno; pokolenie Semejego osobno, i niewisty ich osobno;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'Wszystkie insze pokolenia, każde pokolenie osobno, i niewiasty ich osobno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'W on dzień będzie otworzona studnica domowi Dawidowemu i obywatelom Jeruzalemskim na omycie grzechu i nieczystości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'I stanie się dnia onego, mówi Pan zastępów, że wykorzenię imiona bałwanów z ziemi, tak, że nie będą więcej wspominane; dotego i tych proroków i ducha nieczystego zniosę z ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'I stanie się, gdyby kto dalej prorokował, że mu rzekną ojciec jego i matka jego, którzy go spłodzili: Nie będziesz żył, przeto żeś kłamstwo mówił w imieniu Pańskiem; i przebiją go ojciec jego i matka jego, którzy go spłodzili, że prorokował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'I stanie się dnia onego, że się zawstydzą oni prorocy, każdy za widzenie swoje, gdyby prorokowali, i nie obleką się w suknię kosmatą, aby kłamali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Ale każdy rzecze: Nie jestem ja prorokiem, ale rolnikiem; bo mię tego nauczono od dzieciństwa mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'A jeżeli mu kto rzecze: Cóż to masz za rany na rękach twoich? Tedy rzecze: Temi jestem zraniony w domu tych, którzy mię miłują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'O mieczu! ocknij się na pasterza mego, i na męża towarzysza mego, mówi Pan zastępów; uderz pasterza, a owce rozproszone będą; ale zaś obrócę rękę moję ku maluczkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Bo się stanie po tej wszystkiej ziemi, mówi Pan, że dwie części w niej wytracone będą i pomrą, a trzecia zostanie w niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'I wwiodę i onę trzecią część do ognia, a wypławię je jako pławią srebro, a doświadczać ich będę, jako doświadczają złota; każdy będzie wzywał imienia mego, a Ja go wysłucham: rzekę: Tyś lud mój, a on rzecze: Tyś Pan Bóg mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Oto przychodzi dzień Pański, a rozdzielone będą korzyści twoje w pośrodku ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Bo zgromadzę wszystkie narody przeciwko Jeruzalemowi na wojnę, a miasto wzięte będzie, i domy rozchwycone będą, i niewiasty pogwałcone będą; a gdy pójdzie część miasta w pojmanie, ostatek ludu nie będzie wygładzony z miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Bo wyjdzie Pan, i będzie walczył przeciwko onym narodom, jako zwykł wojować w dzień potykania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'I staną nogi jego w on dzień na górze Oliwnej, która jest przeciwko Jeruzalemowi na wschód słońca, a góra Oliwna się na poły rozszczepi, na wschód i na zachód słońca rozpadliną bardzo wielką, i odwali się połowa onej góry na północ, a połowa jej na południe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Tedy ucieczecie przed doliną gór; (bo dolina tych gór dosięże aż do Azal) będziecie, mówię, uciekać, jakoście uciekali przed trzęsieniem ziemi za dni Ozyjasza, króla Judzkiego, gdy przyjdzie Pan, Bóg mój, i wszyscy święci z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'I stanie się dnia onego, że nie będzie światłości drogiej, ani ciemności gęstej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Lecz będzie dzień jeden, który jest wiadomy Panu, a nie będzie dnia ani nocy; wszakże czasu wieczornego będzie światło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'A dnia onego wyjdą wody żywe z Jeruzalemu; połowa ich do morza na wschód słońca, a połowa ich do morza ostatniego, a to będzie w lecie i w zimie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'A Pan będzie królem nad wszystką ziemią; w on dzień będzie Pan jeden, i imię jego jedno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'I uczyniona będzie ta wszystka ziemia, jako równina od Gabaa aż do Remmon na południe ku Jeruzalemowi, który wywyższony będąc, stać będzie na miejscu swojem od bramy Benjaminowej aż do miejsca bramy pierwszej i aż do bramy węgielnej, a od wieży Chananeel aż do pras królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'I będą w nim mieszkać, a nie będzie więcej przeklęstwem, a Jeruzalem bezpiecznie mieszkać będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'A tać będzie plaga, którą uderzy Pan wszystkie narody, któreby walczyły przeciwko Jeruzalemowi: Ciało każdego stojącego na nogach swoich schnąć będzie, a oczy ich wypłyną z dołków swoich, i język ich uschnie w ustach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'I stanie się dnia onego wielkie uciśnienie Pańskie między nimi, tak, iż rękę jeden drugiego uchwyci, a ręka jego podniesie się na rękę bliźniego swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'I tyć też, Judo! walczyć będziesz w Jeruzalemie, a zgromadzone będą bogactwa wszystkich narodów okolicznych, złoto i srebro i szat obfitość wielka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'A takaż będzie plaga na konie, muły, wielbłądy, i osły, i na wszystkie bydlęta, które będą w onym obozie, jako i ta plaga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'A ile ich pozostanie z onych wszystkich narodów, któreby przyciągnęły przeciwko Jeruzalemowi, będą przychodzić od roku do roku, pokłon oddawać królowi, Panu zastępów, i obchodzić święto Kuczek;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'A ktoby nie szedł z pokolenia ziemi do Jeruzalemu, pokłon oddawać królowi, Panu zastępów, na tych deszcz padać nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'A jeśli pokolenie Egipskie nie wstąpi, i nie przyjdzie, choć na nich deszcz nie pada, przyjdzie jednak ta plaga, którą uderzy Pan narody, które nie przyszły, obchodzić święta Kuczek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'A tać będzie kaźń grzechu Egipskiego, i kaźń grzechu wszystkich narodów, któreby nie przychodziły ku obchodzeniu święta Kuczek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'Dnia onego będzie na rzędach końskich napisane: Świętobliwość Pańska; a kotłów będzie w domu Pańskim, jako miednic przed ołtarzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Owszem, każdy kocieł w Jeruzalemie i w Judzie poświęcony będzie Panu zastępów; a przychodząc wszyscy, którzy ofiarować mają, brać je i warzyć w nich będą, a nie będzie Chananejczyka więcej w domu Pana zastępów dnia onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Brzemię słowa Pańskiego przeciwko Izraelowi, przez Malachyjasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Umiłowałem was, mówi Pan, a wy mówicie: W czemżeś nas umiłował? Izali Ezaw nie był bratem Jakóbowi? mówi Pan; wszakżem umiłował Jakóba,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'A Ezawa miałem w nienawiści, i podałem góry jego na spustoszenie, a dziedzictwo jego smokom na pustyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Jeźliby rzekła ziemia Edomska: Staliśmy się ubogimi, ale wrócimy się, i pobudujemy miejsca popustoszone, tedy tak mówi Pan zastępów: Niechaj oni budują, a Ja rozwalę; i nazwię ich granicą niepobożności i ludem, który sobie zbrzydził Pan aż na wiek i.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'To oglądają oczy wasze, a wy rzeczecie: Niech będzie Pan uwielbiony w granicach Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Syn ma w uczciwości ojca, a sługa pana swego; jaźlim tedy Ja ojcem, gdzież jest cześć moja? i jeźliżem Ja panem, gdzież jest bojaźń moja? mówi Pan zastępów wam, o kapłani! którzy lekce poważacie imię moje, a wszakże mówicie: W czemże lekce poważamy imię twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Którzy przynosząc na ołtarz mój ofiarę splugawioną, mówicie: Czemżeśmy cię splugawili? Tem, że mówicie: Stół Pański splugawiony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Bo gdy przywodzicie, co ślepego jest, na ofiarę, izali to nie zła rzecz? I gdy przywodzicie chrome i chore, izali to nie zła rzecz? Ofiaruj to jedno książęciu twemu, obaczysz, jeżeli mu się to podobać będzie, a przyjmieli twarz twoję, mówi Pan zas tępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Przetoż teraz błagajcie, proszę, oblicze Boże, aby się zmiłował nad nami; ale póki się to dzieje z ręki waszej, izali przyjmie oblicze którego z was? mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Owszem, kto jest między wami, aby zawarł drzwi, albo darmo zapalił na ołtarzu moim? Nie mam chęci do was, mówi Pan zastępów, i ofiary nie przyjmię z ręki waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Albowiem od wschodu słońca aż do zachodu jego wielkie jest imię moje między narodami, a na wszelkiem miejscu przyniesione będzie kadzenie imieniowi memu i ofiara czysta; wielkie zaiste imię moje będzie między narodami, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Lecz wy plugawicie je, gdy mówicie: Stół Pański splugawiony jest; a co nań kładą, jest wzgardzonym pokarmem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Mówicie też: O jakaż to praca! choćbyście to zdmuchnąć mogli mówi Pan zastępów; bo przynosicie to, co jest wydartego, i chromego i schorzałego, a przynosicie to na ofiarę: izali to przyjmę z ręki waszej? mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'I owszem przeklęty jest zdradliwy, który mając w trzodzie swej samca, a przecię czyniąc śluby ofiaruje Panu to, co jest ułomnego; bom Ja królem wielkim mówi Pan zastępów, a imię moje straszne jest między narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'A tak teraz do was mówię to rozkazanie, o kapłani!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Jeźli nie usłuchacie, i jeźli nie złożycie do serca, abyście dali chwałę imieniowi memu, mówi Pan zastępów, tedy poślę na was przeklęstwo, a przeklinać będę błogosławieństwa wasze; owszem jużem je przeklął: boście tego nie złożyli do serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Oto, Ja wam popsuję siewy wasze, a wrzucę łajno na twarzy wasze, łajno, mówię, ofiar waszych, tak, że was przytargnie do siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'I dowiecie się, iżem posłał do was to rozkazanie, aby było przymierze moje z Lewim, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Przymierze moje było z nim żywota i pokoju, a dałem mu je dla bojaźni; bo się mnie bał, i dla imienia mojego skruszony był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Zakon prawdy był w ustach jego, a nieprawość nie była znaleziona w wargach jego; chodził zemną w pokoju i w prawości, i wielu odwrócił od nieprawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Bo wargi kapłańskie umiejętności strzedz mają, a pytać się będą na zakon z ust jego; Aniołem zaiste jest Pana zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Aleście wy zstąpili z drogi, i byliście zgorszeniem wielom w zakonie, zepsowaliście przymierze Lewiego, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Przetoż i Jam was uczynił wzgardzone i poniżone u wszystkich ludzi, tak jakoście wy nie strzegli dróg moich, a mieliście wzgląd na osobę w zakonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Izali nie jeden ojciec jest nas wszystkich? Izali nie jaden Bóg stworzył nas? Czemuż tedy brat zdradza brata swego, gwałcąc przymierze ojców naszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Zdradliwie się sprawuje Juda, a obrzydliwość się dzieje w Izraelu i w Jeruzalemie; bo Juda splugawił świętobliwość Pańską, w której się kochać miał, pojąwszy za żone córkę boga obcego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Pan męża, który to czyni, wykorzeni z namiotów Jakóbowych, tak czującego, jako i odpowiadającego i ofiarującego dar Panu zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'A toście drugi raz uczynili, okrywając łzami ołtarz Pański, płaczem i wołaniem, tak, że więcej nie patrzy na dar, i nie przyjmuje wdzięcznej ofiary z ręki waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Wszakże mówicie: Dlaczegoż to? Dla tego, że Pan jest świadkiem między tobą i między żoną młodości twojej, przeciw którejś ty wystąpił, gdyż ona jest towarzyszką twoją, i żoną przymierza twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Bo azaż nie uczynił jednym, choć mu jeszcze ducha zbywało? A czemuż jednym? aby szukali nasienia Bożego; a tak strzeżcie ducha swego, a z żoną młodości swojej się zdradliwie nie obchodźcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Bo on ma w nienawiści opuszczenie żony, mówi Pan, Bóg Izraelski, przto że taki okrywa okrucieństwo płaszczem jego, mówi Pan zastępów; a tak strzeżcie ducha waszego, a nie obchodźcie się zdradliwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Pracęście zadali Panu słowy swojemi, a przecię mówicie: W czemżeśmy mu pracę zadali? W tem, gdy mówicie: Wszelki, który złość czyni, podoba się Panu, i w tych ma kochanie; albo: Gdzież jest Bóg sądu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Oto ja posyłam Anioła mego, który zgotuje drogę przed obliczem mojem; a zarazem przyjdzie do kościoła swego Panujący, którego wy szukacie, i Anioł przymierza, którego wy żądacie; oto, przyjdzie, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Lecz któż będzie mógł znieść dzień przyjścia jego? I kto się ostoi, gdy on się okaże? Bo on jest jako ogień roztapiający, i jako mydło blecharzów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'I będzie siedział roztapiając i wyczyszczając srebro, i oczyści syny Lewiego, i przepławi je jako złoto i jako srebro, i będą ofiarować Panu dar w sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Tedy Panu będzie wdzięczna ofiara od Judy i od Jeruzalemu, jako za dni pierwszych i jako za lat starodawnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Ale się do was przybliżę z sądem, i będę świadkiem prędkim przeciwko czarownikom, i przeciwko cudzołożnikom, i przeciwko krzywoprzysiężcom, i przeciwko tym, którzy krzywdę czyniąc zatrzymywają zapłatę najemnikowi, wdowie i sierocie i cudzoziemcowi krzywdę czynią, a nie boją się mnie, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Gdyż ja Pan nie odmieniam się, przetoż wy, synowie Jakóbowi! nie jesteście zniszczeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Zaraz ode dni ojców waszych odstąpiliście od ustaw moich, a nie strzegliście ich; nawróćcież się do mnie, a nawrócę się do was, mówi Pan zastępów. Ale mówicie: W czemże się nawrócimy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Izali człowiek ma Boga złupić, że wy mnie łupicie? Wszakże mówicie: W czemże cię łupimy? W dziesięcinach i w ofiarach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Zgołaście przeklęci, iż mię tak łupicie, wy i wszystek naród wasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Znieście wszystkę dziesięcinę do szpichleża, aby była żywność w domu moim, a doświadczcie mię teraz w tem, mówi Pan zastępów; jeźli wam nie otworzę okien niebieskich, a nie wyleję na was błogosławieństwa, tak że go nie będziecie mieli gdzie podziać;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'I zgromię dla was pożerającego, a nie popsuję wam urodzaju ziemskiego, i nie pochybi winna macica na polu, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'I będą was błogosławić wszyscy narodowie; bo wy będziecie ziemią rozkoszną, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Zmocniły się przeciwko mnie słowa wasze, mówi Pan; wszakże mówicie: Cóżeśmy mówili przeciwko tobie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Mówiliście: Próżna to Bogu służyć, a cóż za pożytek, choć będziemy strzedz rozkazania jego, i będziemy smętnie chodzić, bojąc się Pana zastępów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Owszem, pyszne mamy za błogosławione, ponieważ się ci budują, którzy czynią niezbożność, a którzy kuszą Boga, zachowani bywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Tedy rozmawiali o tem ci, którzy się boją Pana, każdy z bliźnim swoim. I obaczył Pan, a usłyszał, i napisano księgę pamiątki przed obliczem jego dla bojących się Pana i myślących o imieniu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Cić mi będą, mówi Pan zastępów, w dzień, który Ja uczynię, własnością; i zmiłuję się nad nimi, jako się zmiłowywa ojciec nad synem swoim, który mu służy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Tedy się nawrócicie, a obaczycie różność między sprawiedliwym i niezbożnym, między tym, który służy Bogu, i między tym, który mu nie służy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Bo oto, przychodzi dzień pałający jako piec, w który wszyscy pyszni, i wszyscy czyniący niezbożność będą jako ciernisko, a popali je ten dzień przyszły, mówi Pan zastępów, tak, że im nie zostawi ani korzenia ani gałązki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Ale wam, którzy się boicie imienia mego, wznijdzie słońce sprawiedliwości, a zdrowie będzie na skrzydłach jego; tedy wychodzić będziecie, i porościecie jako cielęta karmne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'A podepczecie niezbożne, tak, że będą jako proch pod nogami waszemi w dzień, który Ja uczynię, mówi Pan zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Pamiętajcież na zakon Mojżesza, sługi mego, któremum rozkazał na Horebie, przedłożyć wszystkiemu Izraelowi ustawy i sądy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Oto, Ja wam poślę Elijasza proroka, pierwej niż przyjdzie on wielki i straszny dzień Pański,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'Aby obrócił serca ojców ku synom, a serca synów ku ojcom ich, abym przyszedłszy ziemi przeklęstwem nie skarał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Księga o rodzie Jezusa Chrystusa, syna Dawidowego, syna Abrahamowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham spłodził Izaaka, a Izaak spłodził Jakóba, a Jakób spłodził Judę, i braci jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'A Juda spłodził Faresa i Zarę z Tamary, a Fares spłodził Hesrona, a Hesron spłodził Arama.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'A Aram spłodził Aminadaba, a Aminadab spłodził Naasona, a Naason spłodził Salmona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'A Salmon spłodził Booza z Rachaby, a Booz spłodził Obeda z Ruty, a Obed spłodził Jessego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'A Jesse spłodził Dawida króla, a Dawid król spłodził Salomona z tej, która była żoną Uryjaszową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'A Salomon spłodził Roboama, a Roboam spłodził Abijasza, a Abijasz spłodził Azę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'A Aza spłodził Jozafata, a Jozafat spłodził Jorama, a Joram spłodził Ozyjasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'A Ozyjasz spłodził Joatama, a Joatam spłodził Achaza, a Achaz spłodził Ezechijasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'A Ezechijasz spłodził Manasesa, a Manases spłodził Amona, a Amon spłodził Jozyjasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'A Jozyjasz spłodził Jechonijasza i braci jego podczas zaprowadzenia do Babilonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'A po zaprowadzeniu do Babilonu Jechonijasz spłodził Salatyjela, a Salatyjel spłodził Zorobabela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'A Zorobabel spłodził Abijuda, a Abijud spłodził Elijakima, a Elijakim spłodził Azora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'A Azor spłodził Sadoka, a Sadok spłodził Achima, a Achim spłodził Elijuda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'A Elijud spłodził Eleazara, a Eleazar spłodził Matana, a Matan spłodził Jakóba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'A Jakób spłodził Józefa, męża Maryi, z której się narodził Jezus, którego zowią Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'A tak wszystkiego pokolenia od Abrahama aż do Dawida jest pokoleń czternaście, a od Dawida aż do zaprowadzenia do Babilonu, pokoleń czternaście, a od zaprowadzenia do Babilonu aż do Chrystusa, pokoleń czternaście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'A narodzenie Jezusa Chrystusa takie było: Albowiem gdy Maryja, matka jego, poślubiona była Józefowi, pierwej niżeli się zeszli, znaleziona jest brzemienną z Ducha Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Ale Józef, mąż jej, będąc sprawiedliwym i nie chcąc jej osławić, chciał ją potajemnie opuścić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'A gdy on o tem zamyślał, oto mu się Anioł Pański we śnie ukazał, mówiąc: Józefie, synu Dawidów! nie bój się przyjąć Maryi, żony twojej; albowiem, co się w niej poczęło, z Ducha Świętego jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'A urodzi syna, i nazowiesz imię jego Jezus; albowiem on zbawi lud swój od grzechów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'A to się wszystko stało, aby się wypełniło, co powiedziano od Pana przez proroka, mówiącego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Oto panna będzie brzemienna i porodzi syna, a nazowią imię jego Emanuel, co się wykłada: Bóg z nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Tedy Józef ocuciwszy się ze snu, uczynił, jako mu rozkazał Anioł Pański, i przyjął żonę swoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Ale jej nie uznał, aż porodziła onego syna swego pierworodnego, i nazwał imię jego Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'A gdy się Jezus narodził w Betlehemie Judzkiem za dnia Heroda króla, oto mędrcy ze wschodu słońca przybyli do Jeruzalemu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Gdzież jest ten, który się narodził, król żydowski? Bośmy widzieli gwiazdę jego na wschód słońca, i przyjechaliśmy, abyśmy mu się pokłonili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Co gdy król Herod usłyszał, zatrwożył się, i wszystko Jeruzalem z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Przetoż zebrawszy wszystkie przedniejsze kapłany i nauczyciele ludu, dowiadywał się od nich, gdzie by się miał Chrystus narodzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'A oni mu rzekli: W Betlehemie Judzkiem: bo tak napisano przez proroka:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'I ty Betlehemie, ziemio Judzka! żadną miarą nie jesteś najmniejsze między książęty Judzkimi; albowiem z ciebie wynijdzie wódz, który rządzić będzie lud mój Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Tedy Herod wezwawszy potajemnie onych mędrców, pilnie się wywiadywał od nich o czasie, którego się gwiazda ukazała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'A posławszy je do Betlehemu, rzekł: Jechawszy, pilnie się wywiadujcie o tem dzieciątku; a gdy znajdziecie, oznajmijcie mi, abym i ja przyjechawszy, pokłonił mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Oni tedy, wysłuchawszy króla, poszli; a oto ona gwiazda, którą widzieli na wschód słońca, prowadziła je, aż przyszedłszy, stanęła nad miejscem, gdzie było dzieciątko;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'A gdy ujrzeli onę gwiazdę, uradowali się radością bardzo wielką;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'I wszedłszy w dom, znaleźli dzieciątko z Maryją, matką jego, a upadłszy, pokłonili mu się, i otworzywszy skarby swoje, ofiarowali mu dary: złoto i kadzidło i myrrę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Lecz będąc upomnieni od Boga we śnie, aby się nie wracali do Heroda, inszą drogą wrócili się do krainy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'A gdy oni odeszli, oto Anioł Pański ukazał się we śnie Józefowi mówiąc: Wstawszy, weźmij to dzieciątko i matkę jego, a uciecz do Egiptu, a bądź tam, aż ci powiem; albowiem Herod będzie szukał dzieciątka, aby je zatracił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Który wstawszy, wziął dzieciątko i matkę jego w nocy, i uszedł do Egiptu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'I był tam aż do śmierci Herodowej, aby się wypełniło, co powiedziano od Pana przez proroka, mówiącego: Z Egiptum wezwał syna mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Tedy Herod ujrzawszy, że był oszukany od mędrców, rozgniewał się bardzo, a posławszy pobił wszystkie dziatki, które były w Betlehemie i po wszystkich granicach jego, od dwóch lat i niżej, według czasu, o którym się był pilnie wywiedział od mędrców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Tedy się wypełniło, co powiedziano przez Jeremijasza proroka, mówiącego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'Głos w Ramie słyszany jest, lament, i płacz, i narzekanie wielkie: Rachel płacząca synów swoich nie dała się pocieszyć, przeto, że ich nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'A gdy umarł Herod, oto Anioł Pański ukazał się we śnie Józefowi w Egipcie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Mówiąc: Wstawszy, weźmij dzieciątko i matkę jego, a idź do ziemi Izraelskiej; albowiem pomarli ci, którzy szukali duszy dziecięcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'A on wstawszy, wziął do siebie dzieciątko i matkę jego, i przyszedł do ziemi Izraelskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Lecz gdy usłyszał, iż Archelaus królował w Judzkiej ziemi na miejscu Heroda, ojca swego, bał się tam iść; ale napomniany będąc od Boga we śnie, ustąpił w strony Galilejskie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'I przyszedłszy mieszkał w mieście, które zowią Nazaret, aby się wypełniło co powiedziano przez proroki: Iż Nazarejczykiem nazwany będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'W one dni przyszedł Jan Chrzciciel, każąc na puszczy w ziemi Judzkiej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'A mówiąc: Pokutujcie; albowiem się przybliżyło królestwo niebieskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Tenci bowiem jest on, o którym powiedziano przez Izajasza proroka, mówiącego: Głos wołającego na puszczy: Gotujcie drogę Pańską, proste czyńcie ścieżki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'A ten Jan miał odzienie z sierści wielbłądziej, i pas skórzany około biódr swoich, a pokarm jego był szarańcza i miód leśny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Tedy wychodziło do niego Jeruzalem i wszystka Judzka ziemia i wszystka kraina około Jordanu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'I byli chrzczeni od niego w Jordanie, wyznawając grzechy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'A gdy ujrzał wiele z Faryzeuszów i Saduceuszów przychodzących do chrztu swego, rzekł im: Rodzaju jaszczurczy! któż wam pokazał, żebyście uciekali przed przyszłym gniewem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Przynoścież tedy owoce godne pokuty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'A nie mniemajcie, że możecie mówić sami o sobie: Ojca mamy Abrahama; albowiemci powiadam wam, iż Bóg i z tych kamieni wzbudzić może dzieci Abrahamowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'A już i siekiera do korzenia drzew przyłożona jest; wszelkie tedy drzewo, które nie przynosi owocu dobrego, bywa wycięte, i w ogień wrzucone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Jać was chrzczę wodą ku pokucie; ale ten, który idzie za mną, mocniejszy jest nad mię; któregom obuwia nosić nie jest godzien; ten was chrzcić będzie Duchem Świętym i ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Którego łopata jest w ręku jego, a wyczyści bojewisko swoje, i zgromadzi pszenicę swoję do gumna, ale plewy spali ogniem nieugaszonym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Tedy Jezus przyszedł od Galilei nad Jordan do Jana, aby był ochrzczony od niego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Ale mu Jan bardzo zabraniał, mówiąc: Ja potrzebuję, abym był ochrzczony od ciebie, a ty idziesz do mnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'A odpowiadając Jezus, rzekł do niego: Zaniechaj teraz; albowiem tak przystoi na nas, abyśmy wypełnili wszelką sprawiedliwość; tedy go zaniechał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'A Jezus ochrzczony będąc, wnet wystąpił z wody, a oto się mu otworzyły niebiosa, i widział Ducha Bożego, zstępującego jako gołębicę, i przychodzącego na niego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'A oto głos z niebios mówiący: Ten jest on Syn mój miły, w którym mi się upodobało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Tedy Jezus zawiedziony jest na puszczę od Ducha, aby był kuszony od dyjabła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'A gdy pościł czterdzieści dni i czterdzieści nocy, potem łaknął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'I przystąpiwszy do niego kusiciel, rzekł: Jeźliś jest Syn Boży, rzecz, aby się te kamienie stały chlebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'A on odpowiadając rzekł: Napisano: Nie samym chlebem człowiek żyć będzie, ale każdem słowem pochodzącem przez usta Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Tedy go wziął dyjabeł do miasta świętego, i postawił go na ganku kościelnym,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'I rzekł mu: Jeźliś jest Syn Boży, spuść się na dół, albowiem napisano: Iż Aniołom swoim przykazał o tobie, i będą cię na rękach nosili, abyś snać nie obraził o kamień nogi swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Rzekł mu Jezus: Zasię napisano: Nie będziesz kusił Pana, Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Wziął go zasię dyjabeł na górę bardzo wysoką, i pokazał mu wszystkie królestwa świata i sławę ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'I rzekł mu: To wszystko dam tobie, jeźli upadłszy, pokłonisz mi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Tedy mu rzekł Jezus: Pójdź precz, szatanie! albowiem napisano: Panu Bogu twemu kłaniać się będziesz, i jemu samemu służyć będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Tedy go opuścił dyjabeł, a oto Aniołowie przystąpili i służyli mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'A gdy usłyszał Jezus, iż Jan był podany do więzienia, wrócił się do Galilei;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'A opuściwszy Nazaret, przyszedł, i mieszkał w Kapernaum, które jest nad morzem w granicach Zabulonowych i Neftalimowych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Aby się wypełniło, co powiedziano przez Izajasza proroka, mówiącego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Ziemia Zabulonowa i ziemia Neftalimowa przy drodze morskiej za Jordanem, Galilea poganów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Lud, który siedział w ciemności, widział światłość wielką, a siedzącym w krainie i w cieniu śmierci weszła im światłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Od onego czasu począł Jezus kazać i mówić: Pokutujcie, albowiem się przybliżyło królestwo niebieskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'A gdy Jezus chodził nad morzem Galilejskiem, ujrzał dwóch braci: Szymona, którego zowią Piotrem, i Andrzeja, brata jego, którzy zapuszczali sieć w morze; albowiem byli rybitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'I rzekł im: Pójdźcie za mną, a uczynię was rybitwami ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'A oni zaraz opuściwszy sieci, szli za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'A postąpiwszy stamtąd, ujrzał drugich dwóch braci, Jakóba, syna Zebedeuszowego, i Jana, brata jego, w łodzi z Zebedeuszem, ojcem ich, poprawiających sieci swoje, i wezwał ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'A oni wnetże opuściwszy łódź i ojca swego, poszli za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'I obchodził Jezus wszystkę Galileją, ucząc w bóżnicach ich, i każąc Ewangieliją królestwa, a uzdrawiając wszelką chorobę i wszelką niemoc między ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'I rozeszła się wieść o nim po wszystkiej Syryi; i przywodzono do niego wszystkie źle się mające, a rozmaitemi chorobami i mękami zdjęte, także i opętane, i lunatyki i powietrzem ruszone; i uzdrawiał je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'A szedł za nim lud wielki z Galilei, z dziesięciu miast, i z Jeruzalemu, i z Judzkiej ziemi, i zza Jordanu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'A Jezus widząc lud, wstąpił na górę; a gdy usiadł, przystąpili do niego uczniowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'A otworzywszy usta swe, uczył je, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Błogosławieni ubodzy w duchu; albowiem ich jest królestwo niebieskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Błogosławieni, którzy się smęcą; albowiem pocieszeni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Błogosławieni cisi; albowiem oni odziedziczą ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Błogosławieni, którzy łakną i pragną sprawiedliwości; albowiem oni nasyceni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Błogosławieni miłosierni: albowiem oni miłosierdzia dostąpią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Błogosławieni czystego serca; albowiem oni Boga oglądają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Błogosławieni pokój czyniący; albowiem oni synami Bożymi nazwani będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Błogosławieni, którzy cierpią prześladowanie dla sprawiedliwości; albowiem ich jest królestwo niebieskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Błogosławieni jesteście, gdy wam złorzeczyć będą, i prześladować was, i mówić wszystko złe przeciwko wam, kłamając dla mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Radujcie się, i weselcie się; albowiem zapłata wasza obfita jest w niebiesiech; tak bowiem prześladowali proroki, którzy byli przed wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Wy jesteście sól ziemi; jeźli tedy sól zwietrzeje, czemże solić będą? Do niczego się już nie zgodzi, tylko aby była precz wyrzucona i od ludzi podeptana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Wy jesteście światłość świata, nie może się miasto ukryć na górze leżące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Ani zapalają świecy, i stawiają jej pod korzec, ale na świecznik, i świeci wszystkim, którzy są w domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Tak niechaj świeci światłość wasza przed ludźmi, aby uczynki wasze dobre widzieli, a chwalili ojca waszego, który jest w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Nie mniemajcie, abym przyszedł rozwiązywać zakon albo proroki; nie przyszedłem rozwiązywać, ale wypełnić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Zaprawdę bowiem powiadam wam: Aż przeminie niebo i ziemia, jedna jota albo jedna kreska nie przeminie z zakonu, ażby się wszystko stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Kto by tedy rozwiązał jedno z tych przykazań najmniejszych, i uczyłby tak ludzi, najmniejszym będzie nazwany w królestwie niebieskiem; a ktokolwiek by czynił i uczył, ten będzie wielkim nazwany w królestwie niebieskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Albowiem powiadam wam: Jeźli nie będzie obfitsza sprawiedliwość wasza, niż nauczonych w Piśmie i Faryzeuszów, żadnym sposobem nie wnijdziecie do królestwa niebieskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Słyszeliście, iż rzeczono starym: Nie będziesz zabijał; a ktobykolwiek zabił, będzie winien sądu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Ale ja wam powiadam: Iż każdy, kto się gniewa na brata swego bez przyczyny, będzie winien sądu; a ktokolwiek rzecze bratu swemu: Racha; będzie winien rady, a ktokolwiek rzecze: Błaźnie! będzie winien ognia piekielnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'A tak jeźlibyś ofiarował dar twój na ołtarzu, a tam byś wspomniał, iż brat twój ma co przeciwko tobie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'Zostaw tam dar twój przed ołtarzem, a odejdź, pierwej się pojednaj z bratem twoim; a potem przyszedłszy ofiaruj dar twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Zgódź się z przeciwnikiem twoim rychło, pókiś jest z nim w drodze, by cię snać przeciwnik nie podał sędziemu, a sędzia by cię podał słudze, i byłbyś wrzucony do więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Zaprawdę ci powiadam: Nie wynijdziesz stamtąd, póki byś nie oddał do ostatniego pieniążka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Słyszeliście, iż rzeczono starym: Nie będziesz cudzołożył;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Aleć Ja wam powiadam: Iż każdy, który patrzy na niewiastę, aby jej pożądał, już z nią cudzołóstwo popełnił w sercu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Jeźli cię tedy oko twoje prawe gorszy, wyłup je, a zarzuć od siebie; albowiem pożyteczniej jest tobie, aby zginął jeden z członków twoich, a wszystko ciało twoje nie było wrzucone do ognia piekielnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'A jeźliż cię prawa ręka twoja gorszy, odetnij ją, i zarzuć od siebie; albowiem pożyteczniej jest tobie, aby zginął jeden z członków twoich, a wszystko ciało twoje nie było wrzucone do ognia piekielnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Zasię rzeczono: Ktobykolwiek opuścił żonę swoją, niech jej da list rozwodny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Ale Ja wam powiadam: Ktobykolwiek opuścił żonę swoję oprócz przyczyny cudzołóstwa, przywodzi ją w cudzołóstwo, a kto by opuszczoną pojął, cudzołoży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Słyszeliście zasię, iż rzeczono starym: Nie będziesz krzywo przysięgał, ale oddasz Panu przysięgi twoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Ale Ja wam powiadam, abyście zgoła nie przysięgali, ani na niebo, gdyż jest stolicą Bożą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'Ani na ziemię, gdyż jest podnóżkiem nóg jego; ani na Jeruzalem, gdyż jest miasto wielkiego króla;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Ani na głowę twoję będziesz przysięgał, gdyż nie możesz jednego włosa białym albo czarnym uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Ale mowa wasza niech będzie: Tak, tak; nie, nie; a co więcej nadto jest, to od złego jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Słyszeliście, iż rzeczono: Oko za oko, a ząb za ząb;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Ale Ja wam powiadam: Żebyście się nie sprzeciwiali złemu, ale kto by cię uderzył w prawy policzek twój, nadstaw mu i drugi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'I temu, który się z tobą chce prawować, a suknię twoję wziąć, puść mu i płaszcz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'A kto by cię przymuszał iść milę jednę, idź z nim i dwie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Temu, co cię prosi, daj, a od tego, co chce u ciebie pożyczyć, nie odwracaj się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Słyszeliście, iż rzeczono: Będziesz miłował bliźniego twego, a będziesz miał w nienawiści nieprzyjaciela twego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Aleć Ja wam powiadam: Miłujcie nieprzyjacioły wasze; błogosławcie tym, którzy was przeklinają; dobrze czyńcie tym, którzy was mają w nienawiści, i módlcie się za tymi, którzy wam złość wyrządzają i prześladują was;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'Abyście byli synami Ojca waszego, który jest w niebiesiech; bo on to czyni, że słońce jego wschodzi na złe i na dobre, i deszcz spuszcza na sprawiedliwe i na niesprawiedliwe,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Albowiem jeźli miłujecie te, którzy was miłują, jakąż zapłatę macie? azaż i celnicy tego nie czynią?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'A jeźlibyście tylko braci waszych pozdrawiali, cóż osobliwego czynicie? azaż i celnicy tak nie czynią?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Bądźcież wy tedy doskonałymi, jako i Ojciec wasz, który jest w niebiesiech, doskonały jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Strzeżcie się, abyście jałmużny waszej nie czynili przed ludźmi dlatego, abyście byli widziani od nich; inaczej nie będziecie mieli zapłaty u Ojca waszego, który jest w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Przetoż, gdy czynisz jałmużnę, nie trąb przed sobą, jako obłudnicy czynią w bóżnicach i na ulicach, aby byli chwaleni od ludzi; zaprawdę powiadam wam, odbierają zapłatę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Ale ty gdy czynisz jałmużnę, niechaj nie wie lewica twoja, co czyni prawica twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Aby jałmużna twoja była w skrytości, a Ojciec twój, który widzi w skrytości, ten ci jawnie odda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'A gdy się modlisz, nie bądź jako obłudnicy; albowiem się oni radzi w bóżnicach i na rogach ulic stojąc, modlą, aby byli widziani od ludzi; zaprawdę powiadam wam, iż odbierają zapłatę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Ale ty, gdy się modlisz, wnijdź do komory swojej, a zawarłszy drzwi swoje, módl się Ojcu twemu, który jest w skrytości; a Ojciec twój, który widzi w skrytości, odda ci jawnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'A modląc się, nie bądźcie wielomówni, jako poganie; albowiem oni mniemają, że dla swojej wielomówności wysłuchani będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Nie bądźcież tedy im podobni, gdyż wie Ojciec wasz, czego potrzebujecie, pierwej niżbyście wy go prosili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Wy tedy tak się módlcie; Ojcze nasz, któryś jest w niebiesiech! Święć się imię twoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Przyjdź królestwo twoje; bądź wola twoja jako w niebie, tak i na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Chleba naszego powszedniego daj nam dzisiaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'I odpuść nam nasze winy, jako i my odpuszczamy naszym winowajcom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'I nie wódź nas na pokuszenie, ale nas zbaw ode złego; albowiem twoje jest królestwo i moc i chwała na wieki. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Bo jeźli odpuścicie ludziom upadki ich, odpuści i wam Ojciec wasz niebieski;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'A jeźli nie odpuścicie ludziom upadków ich, i Ojciec wasz nie odpuści wam upadków waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'A gdy pościcie, nie bądźcież smętnej twarzy, jako obłudnicy; szpecą bowiem twarzy swoje, aby byli widziani od ludzi, że poszczą; zaprawdę powiadam wam, odbierają zapłatę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Ale ty, gdy pościsz, namaż głowę twoję, i umyj twarz twoję,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Abyś nie był widziany od ludzi, że pościsz, ale od Ojca twojego, który jest w skrytości; a Ojciec twój, który widzi w skrytości, odda ci jawnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Nie skarbcie sobie skarbów na ziemi, gdzie mól i rdza psuje, i gdzie złodzieje podkopywują i kradną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Ale sobie skarbcie skarby w niebie, gdzie ani mól ani rdza psuje, i gdzie złodzieje nie podkopywują, ani kradną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Albowiem gdzie jest skarb wasz, tam jest i serce wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Oko twoje jestci świecą ciała twego; jeźliby tedy oko twoje było szczere, wszystko ciało twoje jasne będzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Jeźliby zaś oko twoje złe było, wszystko ciało twoje ciemne będzie; jeźli tedy światłość, która jest w tobie, ciemnością jest, sama ciemność jakaż będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Nikt nie może dwom panom służyć, gdyż albo jednego będzie miał w nienawiści, a drugiego będzie miłował; albo jednego trzymać się będzie, a drugim pogardzi; nie możecie Bogu służyć i mamonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Dlatego powiadam wam: Nie troszczcie się o żywot wasz, co byście jedli, albo co byście pili, ani o ciało wasze, czem byście się odziewali; azaż żywot nie jest zacniejszy niż pokarm, i ciało niż odzienie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Spojrzyjcie na ptaki niebieskie, iż nie sieją ani żną, ani zbierają do gumien, a wżdy Ojciec wasz niebieski żywi je; izali wy nie jesteście daleko zacniejsi nad nie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'I któż z was troskliwie myśląc, może przydać do wzrostu swego łokieć jeden?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'A o odzienie przeczże się troszczycie? Przypatrzcie się liliom polnym, jako rosną; nie pracują, ani przędą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'A Ja wam powiadam, iż ani Salomon we wszystkiej sławie swojej nie był tak przyodziany, jako jedna z tych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Jeźli tedy trawę polną, która dziś jest, a jutro bywa w piec wrzucona, Bóg tak przyodziewa, azaż nie daleko więcej was! o małowierni!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Nie troszczcie się tedy, mówiąc: Cóż będziemy jeść? albo co będziemy pić? albo czem się będziemy przyodziewać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Boć tego wszystkiego poganie szukają; wieć bowiem Ojciec wasz niebieski, że tego wszystkiego potrzebujecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Ale szukajcie naprzód królestwa Bożego, i sprawiedliwości jego, a to wszystko będzie wam przydano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Przetoż nie troszczcie się o jutrzejszy dzień: albowiem jutrzejszy dzień troskać się będzie o swoje potrzeby. Dosyćci ma dzień na swojem utrapieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Nie sądźcie, abyście nie byli sądzeni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Albowiem jakim sądem sądzicie, takim sądzeni będziecie, i jaką miarą mierzycie, taką wam odmierzono będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'A czemuż widzisz źdźbło w oku brata twego, a balki, która jest w oku twojem, nie baczysz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Albo jakoż rzeczesz bratu twemu: Dopuść, iż wyjmę źdźbło z oka twego, a oto balka jest w oku twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Obłudniku! wyjmij pierwej balkę z oka twego, tedy przejrzysz, abyś wyjął źdźbło z oka brata twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Nie dawajcie świętego psom, ani miećcie pereł waszych przed świnie, by ich snać nie podeptały nogami swemi, i obróciwszy się nie rozszarpały was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Proście, a będzie wam dano, szukajcie, a znajdziecie; kołaczcie, a będzie wam otworzono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Każdy bowiem, kto prosi, bierze; a kto szuka, znajduje; a temu, co kołacze, będzie otworzono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'I któryż z was jest człowiek, którego prosiłliby syn jego o chleb, izali mu da kamień?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'A prosiłby o rybę, izali mu da węża?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Jeźli wy tedy będąc złymi, umiecie dary dobre dawać dzieciom waszym, czemże więcej Ojciec wasz, który jest w niebiesiech, da rzeczy dobre tym, którzy go proszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Wszystko tedy, co byście chcieli, aby wam ludzie czynili, tak i wy czyńcie im; tenci bowiem jest zakon i prorocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Wchodźcie przez ciasną bramę; albowiem przestronna jest brama i szeroka droga, która prowadzi na zatracenie, a wiele ich jest, którzy przez nię wchodzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'A ciasna jest brama i wąska droga, która prowadzi do żywota; a mało ich jest, którzy ją znajdują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'A strzeżcie się fałszywych proroków, którzy przychodzą do was w odzieniu owczem, ale wewnątrz są wilcy drapieżni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Z owoców ich poznacie je; izali zbierają z ciernia grona winne, albo z ostu figi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Tak ci wszelkie drzewo dobre owoce dobre przynosi; ale złe drzewo owoce złe przynosi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Nie może dobre drzewo owoców złych przynosić, ani drzewo złe owoców dobrych przynosić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Wszelkie drzewo, które nie przynosi owocu dobrego, bywa wycięte i w ogień wrzucone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'A tak z owoców ich poznacie je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Nie każdy, który mi mówi: Panie, Panie! wnijdzie do królestwa niebieskiego; ale który czyni wolę Ojca mojego, który jest w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Wiele ich rzecze mi dnia onego: Panie, Panie! izażeśmy w imieniu twojem nie prorokowali, i w imieniu twojem dyjabłów nie wyganiali, i w imieniu twojem wiele cudów nie czynili?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'A tedy im wyznam: Żem was nigdy nie znał; odstąpcie ode mnie, którzy czynicie nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Wszelkiego tedy, który słucha tych słów moich i czyni je, przypodobam mężowi mądremu, który zbudował dom swój na opoce;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'I spadł gwałtowny deszcz, i przyszła powódź, i wiatry wiały, i uderzyły na on dom, ale nie upadł, bo był założony na opoce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'A wszelki, który słucha tych słów moich, a nie czyni ich, przypodobany będzie mężowi głupiemu, który zbudował dom swój na piasku;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'I spadł deszcz gwałtowny, i przyszła powódź, i wiatry wiały, a uderzyły na on dom, i upadł, a był wielki upadek jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'I stało się, gdy dokończył Jezus tych słów, że się zdumiewał lud nad nauką jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'Albowiem je uczył jako moc mający, a nie jako nauczeni w Piśmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'A gdy zstępował z góry, szedł za nim wielki lud;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'A oto trędowaty przyszedłszy, pokłonił mu się, mówiąc: Panie! jeźli chcesz, możesz mnie oczyścić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'I wyciągnąwszy Jezus rękę, dotknął się go, mówiąc: Chcę, bądź oczyszczony; i zaraz oczyszczony jest trąd jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Tedy mu rzekł Jezus: Patrz, abyś nikomu nie powiadał, ale idź, ukaż się kapłanowi, i ofiaruj dar on, który przykazał Mojżesz na świadectwo przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'A gdy Jezus wszedł do Kapernaum, przyszedł do niego setnik, prosząc go,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'I mówiąc: Panie! sługa mój leży w domu powietrzem ruszony, i ciężko się trapi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'I rzekł mu Jezus: Ja przyjdę i uzdrowię go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'A odpowiadając setnik rzekł: Panie! nie jestem godzien, abyś wszedł pod dach mój; ale tylko rzecz słowo, a będzie uzdrowiony sługa mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Bomci i ja człowiek pod mocą innego, mający pod sobą żołnierze; i mówię temu: Idź, a idzie; a drugiemu: Przyjdź, a przychodzi; a słudze memu: Czyń to, a czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'A gdy to usłyszał Jezus, zadziwił się, i rzekł tym, którzy szli za nim: Zaprawdę powiadam wam: Anim w Izraelu tak wielkiej wiary nie znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'A powiadam wam: Iż wiele ich od wschodu i od zachodu słońca przyjdzie, a usiądą za stołem z Abrahamem i z Izaakiem i z Jakóbem w królestwie niebieskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Ale synowie królestwa będą wyrzuceni w ciemności zewnętrzne, tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'I rzekł Jezus setnikowi: Idź, a jakoś uwierzył, niech ci się stanie; i uzdrowiony jest sługa jego onejże godziny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'A gdy Jezus przyszedł do domu Piotrowego, ujrzał świekrę jego, leżącą na łożu i mającą gorączkę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'I dotknął się ręki jej, i opuściła ją gorączka; i wstała, a posługowała im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'A gdy był wieczór, przywiedli do niego wiele opętanych: i wyganiał duchy słowem; i wszystkie, którzy się źle mieli, uzdrawiał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Aby się wypełniło, co powiedziano przez Izajasza proroka, mówiącego: On niemocy nasze na się wziął, a choroby nasze nosił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'A widząc Jezus wielki lud około siebie, kazał się przeprawić na drugą stronę morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Tedy przystąpiwszy niektóry z nauczonych w Piśmie, rzekł mu: Mistrzu! pójdę za tobą, gdziekolwiek pójdziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'I rzekł mu Jezus: Liszki mają jamy, a ptaki niebieskie gniazda; ale Syn człowieczy nie ma, gdzie by głowę skłonił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'A drugi z uczniów jego rzekł mu: Panie! dopuść mi pierwej odejść i pogrześć ojca mego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Ale mu Jezus rzekł: Pójdź za mną, a niechaj umarli grzebią umarłe swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'A gdy on wstąpił w łódź, wstąpili za nim i uczniowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'A oto się wzruszenie wielkie stało na morzu, tak iż się łódź wałami okrywała; a on spał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'A przystąpiwszy uczniowie jego, obudzili go, mówiąc: Panie! ratuj nas, giniemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'I rzekł do nich: Przeczże jesteście bojaźliwi? o małowierni! Tedy wstawszy, zgromił wiatry i morze, i stało się uciszenie wielkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'A ludzie się dziwowali, mówiąc: Jakiż to jest ten, że mu i wiatry i morze posłuszne są?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'A gdy się on przewiózł na drugą stronę do krainy Giergiezeńczyków, zabieżeli mu dwaj opętani z grobów wychodzący, bardzo okrutni, tak iż nie mógł nikt przechodzić oną drogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'A oto zakrzyknęli, mówiąc: Cóż my z tobą mamy, Jezusie, Synu Boży? Przyszedłeś tu przed czasem, dręczyć nas?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'I była daleko od nich trzoda wielka świń pasących się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Tedy go dyjabli prosili, mówiąc: Jeźli nas wyganiasz, dopuść nam wnijść w trzodę tych świń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'I rzekł im: Idźcie. A oni wyszedłszy, weszli w onę trzodę świń, a oto porwawszy się ona wszystka trzoda świń, z przykra wpadła w morze, i pozdychała w wodach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Lecz pasterze uciekli, a poszedłszy do miasta, opowiedzieli wszystko, i to, co się z onymi opętanymi stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'A oto wszystko miasto wyszło przeciwko Jezusowi, a ujrzawszy go prosili, aby z ich granic odszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Tedy wstąpiwszy w łódź, przewiózł się, i przyszedł do miasta swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'A oto przynieśli mu powietrzem ruszonego, na łożu leżącego. A widząc Jezus wiarę ich, rzekł powietrzem ruszonemu: Ufaj, synu! odpuszczone są tobie grzechy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'A oto niektórzy z nauczonych w Piśmie mówili sami w sobie: Ten bluźni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'A widząc Jezus myśli ich, rzekł: Przeczże wy myślicie złe rzeczy w sercach waszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Albowiem cóż łatwiej rzec: Odpuszczone są tobie grzechy, czyli rzec: Wstań, a chodź?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Ale abyście wiedzieli, iż ma moc Syn człowieczy na ziemi odpuszczać grzechy, tedy rzekł powietrzem ruszonemu: Wstawszy, weźmij łoże twoje, a idź do domu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Tedy wstawszy, poszedł do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Co ujrzawszy lud, dziwował się, i chwalił Boga, który dał taką moc ludziom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'A odchodząc stamtąd Jezus, ujrzał człowieka siedzącego na cle, którego zwano Mateusz, i rzekł mu: Pójdź za mną; tedy wstawszy, szedł za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'I stało się, gdy Jezus siedział za stołem w domu jego, że oto wiele celników i grzeszników przyszedłszy, usiedli z Jezusem i z uczniami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Co widząc Faryzeuszowie, rzekli uczniom jego: Przeczże z celnikami i grzesznikami je nauczyciel wasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'A Jezus usłyszawszy to, rzekł im: Nie potrzebująć zdrowi lekarza, ale ci, co się źle mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Owszem idźcie, a nauczcie się, co to jest: Miłosierdzia chcę, a nie ofiary; bom nie przyszedł wzywać sprawiedliwych, ale grzesznych do pokuty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Tedy przyszli do niego uczniowie Janowi, mówiąc: Przecz my i Faryzeuszowie często pościmy, a uczniowie twoi nie poszczą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'I rzekł im Jezus: Izali się mogą synowie łożnicy małżeńskiej smęcić, póki z nimi jest oblubieniec? Ale przyjdą dni, gdy od nich będzie oblubieniec odjęty, a tedy pościć będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'A żaden nie wprawuje łaty sukna nowego w szatę wiotchą; albowiem ono załatanie ujmuje nieco od szaty, i stawa się gorsze rozdarcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Ani leją wina młodego w stare statki; bo inaczej pukają się statki, a wino wycieka, i statki się psują; ale młode wino leją w nowe statki, i oboje bywają zachowane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'To gdy on do nich mówił, oto niektóry przełożony bóżnicy przyszedłszy pokłonił mu się, mówiąc: Córka moja dopiero skonała; ale pójdź, a włóż na nią rękę twoję, a ożyje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Tedy wstawszy Jezus, szedł za nim, i uczniowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, '(A oto niewiasta, która płynienie krwi ode dwunastu lat cierpiała, przystąpiwszy z tyłu, dotknęła się podołka szat jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Bo rzekła sama w sobie: Jeźli się tylko dotknę szaty jego, będę uzdrowiona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Ale Jezus obróciwszy się i ujrzawszy ją, rzekł: Ufaj, córko! wiara twoja ciebie uzdrowiła; i uzdrowiona była niewiasta od onej godziny.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'A gdy przyszedł Jezus w dom przełożonego, i ujrzał piszczki i lud zgiełk czyniący,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'Rzekł im: Ustąpcie; albowiem dzieweczka nie umarła, ale śpi. I naśmiewali się z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Ale gdy wygnany był on lud, wszedłszy, ujął ją za rękę jej, i wstała dzieweczka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'I rozeszła się ta wieść po wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'A gdy Jezus odchodził stamtąd, szli za nim dwaj ślepi, wołając i mówiąc: Synu Dawidowy! zmiłuj się nad nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'A gdy on wszedł do domu, przyszli do niego ślepi; i rzekł im Jezus: Wierzycież, iż to mogę uczynić? Rzekli mu: Owszem Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Tedy się dotknął oczu ich, mówiąc: Według wiary waszej niechaj się wam stanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'I otworzyły się oczy ich; i przygroził im srodze Jezus, mówiąc: Patrzcież, aby nikt o tem nie wiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Lecz oni wyszedłszy, rozsławili go po wszystkiej onej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'A gdy oni wychodzili, oto przywiedli mu człowieka niemego, opętanego od dyjabła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'A gdy był wygnany on dyjabeł, przemówił niemy; i dziwował się lud, mówiąc: Nigdy się taka rzecz nie pokazała w Izraelu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Ale Faryzeuszowie mówili: Przez książęcia dyjabelskiego wygania dyjabły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'I obchodził Jezus wszystkie miasta i miasteczka, nauczając w bóżnicach ich, i każąc Ewangieliję królestwa, a uzdrawiając wszelką chorobę, i wszelką niemoc między ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'A widząc on lud, użalił się go, iż był strudzony i rozproszony jako owce nie mające pasterza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Tedy rzekł uczniom swoim: Żniwoć wprawdzie wielkie, ale robotników mało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Proście tedy Pana żniwa, aby wypchnął robotniki na żniwo swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'A zwoławszy dwunastu uczniów swoich, dał im moc nad duchy nieczystymi, aby je wyganiali, i uzdrawiali wszelką chorobę i wszelką niemoc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'A dwunastu Apostołów te są imiona: Pierwszy Szymon, którego zowią Piotr, i Andrzej, brat jego; Jakób, syn Zebedeusza, i Jan, brat jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filip i Bartłomiej, Tomasz i Mateusz on celnik, Jakób, syn Alfeusza, i Lebeusz, nazwany Tadeusz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Szymon Kananejczyk, i Judasz Iszkaryjot, który go też wydał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Tych dwunastu posłał Jezus, rozkazując im i mówiąc: Na drogę poganów nie zachodźcie, i do miasta Samarytańczyków nie wchodźcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Ale raczej idźcie do owiec, które zginęły z domu Izraelskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'A idąc każcie, mówiąc: Przybliżyło się królestwo niebieskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Chore uzdrawiajcie, trędowate oczyszczajcie, umarłe wskrzeszajcie, dyjabły wyganiajcie; darmoście wzięli, darmo dawajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Nie bierzcie z sobą złota, ani srebra, ani miedzi w trzosy wasze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Ani taistry na drogę, ani dwóch sukien, ani butów, ani laski; albowiem godzien jest robotnik żywności swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'A do któregokolwiek miasta albo miasteczka wnijdziecie, wywiadujcie się, kto by w niem tego był godzien, a tamże mieszkajcie, póki nie wynijdziecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'A wszedłszy w dom, pozdrówcie go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'A jeźliby on dom tego był godny, niech na niego przyjdzie pokój wasz; a jeźliby nie był godny, pokój wasz niech się wróci do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'A kto by was nie przyjął, ani słuchał słów waszych, wychodząc z domu albo z miasta onego, otrząśnijcie proch z nóg waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Zaprawdę wam powiadam: Lżej będzie ziemi Sodomskiej i Gomorskiej w dzień sądny, niżeli miastu onemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Oto Ja was posyłam jako owce między wilki; bądźcież tedy roztropnymi jako węże, a szczerymi jako gołębice,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'A strzeżcie się ludzi; albowiem was będą wydawać do rady, i w zgromadzeniach swoich was biczować będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Także przed starosty i przed króle wodzeni będziecie dla mnie, na świadectwo przeciwko nim i poganom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Ale gdy was podadzą, nie troszczcie się, jako i co byście mówili; albowiem wam dano będzie onejże godziny, co byście mówili;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Bo wy nie jesteście, którzy mówicie, ale duch Ojca waszego, który mówi w was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'I wyda brat brata na śmierć, i ojciec syna, i powstaną dzieci przeciwko rodzicom, i będą je zabijać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'I będziecie w nienawiści u wszystkich dla imienia mego; ale kto wytrwa do końca, ten będzie zbawion.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'A gdy was prześladować będą w tem mieście, uciekajcie do drugiego; bo zaprawdę powiadam wam, że nie obejdziecie miast Izraelskich, aż przyjdzie Syn człowieczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Nie jestci uczeń nad mistrza, ani sługa nad Pana swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Dosyć uczniowi, aby był jako mistrz jego, a sługa jako Pan jego; jeźlić gospodarza Beelzebubem nazywali, czem więcej domowniki jego nazywać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Przetoż nie bójcie się ich; albowiem nic nie jest skrytego, co by nie miało być objawiono, i nic tajemnego, czego by się dowiedzieć nie miano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Co wam w ciemności mówię, powiadajcie na świetle; a co w ucho słyszycie, obwoływajcie na dachach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'A nie bójcie się tych, którzy zabijają ciało, lecz duszy zabić nie mogą; ale raczej bójcie się tego, który może i duszę i ciało zatracić w piekielnym ogniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Izali dwóch wróbelków za pieniążek nie sprzedają, a wżdy jeden z nich nie upadnie na ziemię oprócz woli Ojca waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Nawet i włosy wszystkie na głowie waszej policzone są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Nie bójcie się tedy; nad wiele wróbelków wy zacniejszymi jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Wszelki tedy, który by mię wyznał przed ludźmi, wyznam go Ja też przed Ojcem moim, który jest w niebiesiech;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'A kto by się mnie zaparł przed ludźmi, zaprę się go i Ja przed Ojcem moim, który jest w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Nie mniemajcie, żem przyszedł dawać pokój na ziemię; nie przyszedłem dawać pokoju, ale miecz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Bom przyszedł, abym rozerwanie uczynił między synem a ojcem jego, i między córką a matką jej, także między synową i świekrą jej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'I nieprzyjaciołmi będą człowiekowi domownicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Kto miłuje ojca albo matkę nad mię, nie jest mię godzien; a kto miłuje syna albo córkę nad mię, nie jest mię godzien;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'A kto nie bierze krzyża swego, i nie idzie za mną, nie jest mię godzien.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Kto by znalazł duszę swoję, straci ją; a kto by stracił duszę swoję dla mnie, znajdzie ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Kto was przyjmuje, mnie przyjmuje; a kto mnie przyjmuje, przyjmuje tego, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Kto przyjmuje proroka w imieniu proroka, zapłatę proroka weźmie; a kto przyjmuje sprawiedliwego w imieniu sprawiedliwego, sprawiedliwego zapłatę weźmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Kto by też napoił jednego z tych to małych tylko kubkiem zimnej wody w imię ucznia, zaprawdę powiadam wam, nie straci zapłaty swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'I stało się, gdy Jezus przestał rozkazywać dwunastu uczniom swoim, poszedł z onąd, aby uczył i kazał w miastach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'A Jan usłyszawszy w więzieniu o uczynkach Chrystusowych, posławszy dwóch z uczniów swoich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Rzekł mu: Tyżeś jest on, który ma przyjść, czyli inszego czekać mamy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'A odpowiadając Jezus, rzekł im: Szedłszy, oznajmijcie Janowi, co słyszycie i widzicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Ślepi widzą, a chromi chodzą, trędowaci biorą oczyszczenie, a głusi słyszą, umarli zmartwychwstają, i ubogim Ewangielija opowiadana bywa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'A błogosławiony jest, który się nie zgorszy ze mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'A gdy oni odeszli, począł Jezus mówić do ludu o Janie: Coście wyszli na puszczę widzieć? Izali trzcinę chwiejącą się od wiatru?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Ale coście wyszli widzieć? Izali człowieka w miękkie szaty obleczonego? oto którzy miękkie szaty noszą, w domach królewskich są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Ale coście wyszli widzieć? Izali proroka? zaiste powiadam wam, i więcej niż proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Boć ten jest, o którym napisano: Oto ja posyłam Anioła mego przed obliczem twojem, który zgotuje drogę twoję przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Zaprawdę powiadam wam: Nie powstał z tych, którzy się z niewiast rodzą, większy nad Jana Chrzciciela; ale który jest najmniejszym w królestwie niebieskiem, większy jest, niżeli on.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'A ode dni Jana Chrzciciela aż dotąd królestwo niebieskie gwałt cierpi, a gwałtownicy porywają je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Bo wszyscy prorocy i zakon aż do Jana prorokowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'A jeźli chcecie przyjąć, onci jest Elijasz, który miał przyjść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Kto ma uszy ku słuchaniu, niechaj słucha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Ale komuż przypodobam ten naród? podobny jest dziatkom, które siedzą na rynkach, i wołają na towarzysze swoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'I mówią: Grałyśmy wam na piszczałce, a nie tańcowałyście; śpiewałyśmy pieśni żałobne, a nie płakałyście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Albowiem przyszedł Jan ani jedząc ani pijąc, a mówią: Iż dyjabelstwo ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Przyszedł Syn człowieczy jedząc i pijąc, a mówią: Oto człowiek obżerca i pijanica wina, przyjaciel celników i grzeszników; i usprawiedliwiona jest mądrość od synów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Tedy począł przymawiać miastom, w których się najwięcej działo cudów jego, że nie pokutowały, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Biada tobie Chorazynie! biada tobie Betsaido! bo gdyby się były w Tyrze i w Sydonie te cuda stały, które się w was stały, dawno by były w worze i w popiele pokutowały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Wszakże powiadam wam: Lżej będzie Tyrowi i Sydonowi w dzień sądny, niżeli wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'A ty Kapernaum! któreś aż do nieba wywyższone, aż do piekła strącone będziesz; bo gdyby się były w Sodomie te cuda działy, które się działy w tobie, zostałaby była aż do dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Nawet powiadam wam: Iż lżej będzie ziemi Sodomskiej w dzień sądny, niżeli tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'W on czas odpowiadając Jezus, rzekł: Wysławiam cię, Ojcze, Panie nieba i ziemi! żeś te rzeczy zakrył przed mądrymi i roztropnymi, a objawiłeś je niemowlątkom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Zaprawdę, Ojcze! tak się upodobało tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Wszystkie rzeczy dane mi są od Ojca mego, i nikt nie zna Syna, tylko Ojciec, ani Ojca kto zna, tylko Syn, a komu by chciał Syn objawić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Pójdźcie do mnie wszyscy, którzyście spracowani i obciążeni, a Ja wam sprawię odpocznienie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Weźmijcie jarzmo moje na się, a uczcie się ode mnie, żem Ja cichy i pokornego serca; a znajdziecie odpocznienie duszom waszym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Albowiem jarzmo moje wdzięczne jest, a brzemię moje lekkie jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'W on czas szedł Jezus w sabat przez zboża, a uczniowie jego łaknęli, i poczęli rwać kłosy i jeść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'A ujrzawszy to Faryzeuszowie, rzekli mu: Oto uczniowie twoi czynią, czego się nie godzi czynić w sabat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'A on im rzekł: Izaście nie czytali, co uczynił Dawid, gdy łaknął, on i ci, którzy z nim byli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Jako wszedł do domu Bożego, i chleby pokładne jadł, których mu się nie godziło jeść, ani tym, którzy z nim byli, tylko samym kapłanom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Alboście nie czytali w zakonie, że w sabat i kapłani w kościele sabat gwałcą, a bez winy są?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Ale mówię wam, iż tu większy jest niż kościół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'A gdybyście wiedzieli, co to jest: Miłosierdzia chcę, a nie ofiary, nie potępialibyście niewinnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Albowiem Syn człowieczy Panem jest i sabatu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'A odszedłszy stamtąd przyszedł do bóżnicy ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'A oto był tam człowiek mający rękę uschłą; i pytali go, mówiąc: Godzili się w sabat uzdrawiać? aby go oskarżyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'A on im rzekł: Któryż człowiek z was będzie, który by miał owcę jedną, a gdyby mu ta w sabat w dół wpadła, izali jej nie dobędzie i nie wyciągnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'A czemże zacniejszy jest człowiek niżeli owca? Przetoż godzi się w sabat dobrze czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Tedy rzekł człowiekowi onemu: Wyciągnij rękę twoję; a on wyciągnął, i przywrócona jest do zdrowia jako i druga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'A wyszedłszy Faryzeuszowie, uczynili radę przeciwko niemu, jakoby go stracili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Ale Jezus poznawszy to, odszedł stamtąd, i szedł za nim lud wielki; i uzdrowił one wszystkie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'I przygroził im, aby go nie objawiali,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Żeby się wypełniło, co powiedziano przez Izajasza proroka, mówiącego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Oto ten sługa mój, któregom obrał, ten umiłowany mój, w którym się upodobało duszy mojej; położę ducha mojego na nim, a sąd narodom opowie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Nie będzie się wadził, ani będzie wołał, i nikt na ulicach nie usłyszy głosu jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Trzciny nałamanej nie dołamie, a lnu kurzącego się nie zagasi, aż wystawi sąd ku zwycięstwu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'A w imieniu jego narodowie będą nadzieję mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Tedy przywiedziono do niego opętanego, ślepego i niemego, i uzdrowił go, tak iż on ślepy i niemy i mówił i widział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'I zdumiał się wszystek lud, i mówili: Nie tenże jest on syn Dawidowy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Ale Faryzeuszowie usłyszawszy to, rzekli: Ten nie wygania dyjabłów, tylko przez Beelzebuba, książęcia dyjabelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Lecz Jezus widząc myśli ich, rzekł im: Każde królestwo rozdzielone samo przeciwko sobie pustoszeje, i każde miasto albo dom, sam przeciwko sobie rozdzielony, nie ostoi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'A jeźliż szatan szatana wygania, sam przeciwko sobie rozdzielony jest; jakoż się tedy ostoi królestwo jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'A jeźliż ja przez Beelzebuba wyganiam dyjabły, synowie wasi przez kogoż wyganiają? Przetoż oni sędziami waszymi będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'A jeźliż ja duchem Bożym wyganiam dyjabły, tedyż do was przyszło królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Albo jakoż może kto wnijść do domu mocarza, i sprzęt jego rozchwycić, jeźliby pierwej nie związał mocarza onego? toż dopiero dom jego rozchwyci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Kto nie jest ze mną, przeciwko mnie jest, a kto nie zbiera ze mną, rozprasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Dlatego powiadam wam: Wszelki grzech i bluźnierstwo ludziom odpuszczone będzie; ale bluźnierstwo przeciwko Duchowi Świętemu nie będzie odpuszczone ludziom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'I ktobykolwiek rzekł słowo przeciwko Synowi człowieczemu, będzie mu odpuszczono; ale kto by mówił przeciwko Duchowi Świętemu, nie będzie mu odpuszczono, ani w tym wieku ani w przyszłym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Czyńcież albo drzewo dobre, i owoc jego dobry; albo czyńcie drzewo złe, i owoc jego zły; albowiem z owocu drzewo poznane bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Rodzaju jaszczurczy! jakoż możecie mówić dobre rzeczy, będąc złymi, gdyż z obfitości serca usta mówią?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Dobry człowiek z dobrego skarbu serca wynosi rzeczy dobre, a zły człowiek ze złego skarbu wynosi rzeczy złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Ale powiadam wam, iż z każdego słowa próżnego, które by mówili ludzie, dadzą z niego liczbę w dzień sądny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Albowiem z mów twoich będziesz usprawiedliwiony, i z mów twoich będziesz osądzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Tedy odpowiedzieli niektórzy z nauczonych w Piśmie i Faryzeuszów, mówiąc: Nauczycielu, chcemy od ciebie znamię widzieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'A on odpowiadając rzekł im: Rodzaj zły i cudzołożny znamienia szuka; ale mu nie będzie znamię dane, tylko ono znamię Jonasza proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Albowiem jako Jonasz był w brzuchu wieloryba trzy dni i trzy noce, tak będzie Syn człowieczy w sercu ziemi trzy dni i trzy noce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Mężowie Niniwiccy staną na sądzie z tym rodzajem, i potępią go, przeto że pokutowali na kazanie Jonaszowe; a oto tu więcej niżeli Jonasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Królowa z południa stanie na sądzie z tym rodzajem, i potępi go; iż przyszła od krajów ziemi, aby słuchała mądrości Salomonowej; a oto tu więcej niżeli Salomon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'A gdy nieczysty duch od człowieka wychodzi, przechadza się po miejscach suchych, szukając odpocznienia, ale nie znajduje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Tedy mówi: Wrócę się do domu mego, skądem wyszedł; a przyszedłszy znajduje go próżny i umieciony i ochędożony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Tedy idzie, i bierze z sobą siedm inszych duchów gorszych, niżeli sam: a wszedłszy mieszkają tam, i bywają ostatnie rzeczy człowieka onego gorsze, niżeli pierwsze. Tak się stanie i temu rodzajowi złemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'A gdy on jeszcze mówił do ludu, oto matka i bracia jego stali przed domem chcąc z nim mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'I rzekł mu niektóry: Oto matka twoja i bracia twoi stoją przed domem, chcąc z tobą mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'A on odpowiadając, rzekł temu, co mu to powiedział: Któraż jest matka moja? i którzy są bracia moi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'A wyciągnąwszy rękę swoję na uczniów swoich, rzekł: Oto matka moja i bracia moi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Albowiem ktobykolwiek czynił wolę Ojca mojego, który jest w niebiesiech, ten jest bratem moim, i siostrą i matką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'A dnia onego wyszedłszy Jezus z domu, usiadł nad morzem:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'I zebrał się do niego wielki lud, tak iż wstąpiwszy w łódź, siedział, a wszystek lud stał na brzegu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'I mówił do nich wiele w podobieństwach i rzekł: Oto wyszedł rozsiewca, aby rozsiewał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'A gdy on rozsiewał, niektóre padło podle drogi; i przyleciały ptaki, a podziobały je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Drugie zasię padło na miejsce opoczyste, gdzie nie miało wiele ziemi; i wnet weszło, iż nie miało głębokości ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Ale gdy słońce weszło, wygorzało, a iż nie miało korzenia, uschło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'A drugie padło między ciernie, i wzrosły ciernie, a zadusiły je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'A drugie padło na ziemię dobrą i wydało pożytek, jedno setny, drugie sześćdziesiątny, a drugie trzydziestny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Kto ma uszy ku słuchaniu, niechaj słucha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Tedy przystąpiwszy uczniowie, rzekli mu: Dlaczegoż im w podobieństwach mówisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'A on odpowiadając, rzekł im: Wam dano wiedzieć tajemnicę królestwa niebieskiego, ale onym nie dano;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Albowiem kto ma, będzie mu dano, i obfitować będzie, ale kto nie ma, i to, co ma, będzie od niego odjęto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Dlategoć im w podobieństwach mówię, iż widząc nie widzą, i słysząc nie słyszą, ani rozumieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'I pełni się w nich proroctwo Izajaszowe, które mówi: Słuchem słuchać będziecie, ale nie zrozumiecie; i widząc widzieć będziecie, ale nie ujrzycie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Albowiem zatyło serce ludu tego, a uszyma ciężko słyszeli, i oczy swe zamrużyli, żeby kiedy oczyma nie widzieli i uszyma nie słyszeli, a sercem nie zrozumieli, i nie nawrócili się, a uzdrowiłbym je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Ale oczy wasze błogosławione, że widzą, i uszy wasze, że słyszą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Bo zaprawdę powiadam wam, iż wiele proroków i sprawiedliwych żądało widzieć to, co wy widzicie, ale nie widzieli, i słyszeć to, co słyszycie, ale nie słyszeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Wy tedy słuchajcie podobieństwa onego rozsiewcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Gdy kto słucha słowa o tem królestwie, a nie rozumie, przychodzi on zły i porywa to, co wsiano w serce jego; tenci jest on, który podle drogi posiany jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'A na opoczystych miejscach posiany, ten jest, który słucha słowa i zaraz je z radością przyjmuje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Ale nie ma korzenia w sobie, lecz doczesny jest; a gdy przychodzi ucisk, albo prześladowanie dla słowa, wnet się gorszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'A między ciernie posiany, ten jest, który słucha słowa; ale pieczołowanie świata tego i omamienie bogactw zadusza słowo, i staje się bez pożytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'A na dobrej ziemi posiany, jest ten, który słucha słowa i rozumie, tenci pożytek przynosi; a przynosi jeden setny, drugi sześćdziesiątny, a drugi trzydziestny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Drugie podobieństwo przełożył im, mówiąc: Podobne jest królestwo niebieskie człowiekowi, rozsiewającemu dobre nasienie na roli swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'A gdy ludzie zasnęli, przyszedł nieprzyjaciel jego, i nasiał kąkolu między pszenicą, i odszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'A gdy urosła trawa i pożytek przyniosła, tedy się pokazał i kąkol.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Tedy przystąpiwszy słudzy gospodarscy, rzekli mu: Panie! izaliś dobrego nasienia nie nasiał na roli twojej? Skądże tedy ma kąkol?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'A on im rzekł: Nieprzyjaciel człowiek to uczynił. I rzekli słudzy do niego: A chceszże, iż pójdziemy, a zbierzemy go?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'A on rzekł: Nie! byście snać zbierając kąkol, nie wykorzenili zaraz z nim i pszenicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Dopuśćcie obojgu społem rość aż do żniwa; a czasu żniwa rzekę żeńcom: Zbierzcie pierwej kąkol, a zwiążcie go w snopki ku spaleniu; ale pszenicę zgromadźcie do gumna mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Insze podobieństwo przełożył im, mówiąc: Podobne jest królestwo niebieskie ziarnu gorczycznemu, które wziąwszy człowiek, wsiał na roli swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Które najmniejszeć jest ze wszystkich nasion; ale kiedy urośnie, największe jest ze wszystkich jarzyn, i staje się drzewem, tak iż ptaki niebieskie przylatując, gniazda sobie czynią na gałązkach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Insze podobieństwo powiedział im: Podobne jest królestwo niebieskie kwasowi, który wziąwszy niewiasta, zakryła we trzy miary mąki, ażby wszystka skwaśniała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'To wszystko mówił Jezus w podobieństwach do ludu, a bez podobieństwa nie mówił do nich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Aby się wypełniło, co powiedziano przez proroka mówiącego: Otworzę w podobieństwach usta moje, wypowiem skryte rzeczy od założenia świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Tedy rozpuściwszy on lud, przyszedł Jezus do domu; i przystąpili do niego uczniowie jego, mówiąc: Wyłóż nam podobieństwo o kąkolu onej roli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'A on odpowiadając, rzekł im: Ten, który rozsiewa dobre nasienie, jest Syn człowieczy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'A rola jest świat, a dobre nasienie są synowie królestwa; ale kąkol są synowie onego złego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'Nieprzyjaciel zasię, który go rozsiał, jestci dyjabeł, a żniwo jest dokonanie świata, a żeńcy są Aniołowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Jako tedy zbierają kąkol, a palą go ogniem, tak będzie przy dokonaniu świata tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Pośle Syn człowieczy Anioły swoje, a oni zbiorą z królestwa jego wszystkie zgorszenia, i te, którzy nieprawość czynią;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'I wrzucą je w piec ognisty, tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Tedy sprawiedliwi lśnić się będą jako słońce w królestwie Ojca swego. Kto ma uszy ku słuchaniu, niechaj słucha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Zasię podobne jest królestwo niebieskie skarbowi skrytemu w roli, który znalazłszy człowiek skrył, i od radości, którą miał z niego, odchodzi, i wszystko, co ma, sprzedaje, i kupuje onę rolę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Zasię podobne jest królestwo niebieskie człowiekowi kupcowi, szukającemu pięknych pereł;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Który znalazłszy jednę perłę bardzo drogą, odszedł, i posprzedawał wszystko, co miał, i kupił ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Zasię podobne jest królestwo niebieskie niewodowi zapuszczonemu w morze, i ryby wszelkiego rodzaju zagarniającemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Który gdy był pełen, wyciągnęli rybitwi na brzeg, a usiadłszy, wybierali dobre ryby w naczynia, a złe precz wyrzucali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Takci będzie przy dokonaniu świata; wynijdą Aniołowie, i wyłączą złe z pośrodku sprawiedliwych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'I wrzucą je w piec ognisty; tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Rzekł im Jezus: Wyrozumieliście to wszystko? Rzekli mu: Tak, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'A on im rzekł: Przetoż każdy nauczony w Piśmie, wyćwiczony w królestwie niebieskiem, podobny jest człowiekowi gospodarzowi, który wynosi z skarbu swego nowe i stare rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'I stało się, gdy Jezus dokończył tych podobieństw, puścił się stamtąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'A przyszedłszy do ojczyzny swojej, nauczał je w bóżnicy ich, tak iż się bardzo zdumiewali i mówili: Skądże temu ta mądrość, i ta moc?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Izaż ten nie jest on syn cieśli? Izaż matki jego nie zowią Maryją, a bracia jego Jakób, i Jozes, i Szymon, i Judas?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'A siostry jego izali wszystkie u nas nie są? Skądże tedy temu to wszystko?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'I gorszyli się z niego; ale Jezus rzekł im: Nie jest prorok beze czci, tylko w ojczyźnie swojej i w domu swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'I nie uczynił tam wiele cudów dla niedowiarstwa ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'W on czas usłyszał Herod Tetrarcha, wieść o Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'I rzekł sługom swoim: Tenci jest Jan Chrzciciel; on to zmartwychwstał, i dlatego się cuda przez niego dzieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Albowiem Herod pojmawszy Jana, związał go był i wsadził do więzienia dla Herodyjady, żony Filipa, brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Bo mu Jan mówił: Nie godzi ci się jej mieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Ale gdy go on chciał zabić, bał się ludu: albowiem go za proroka mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Gdy tedy obchodzono dzień narodzenia Herodowego, tańcowała córka Herodyjady w pośrodku gości, i podobała się Herodowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Skąd pod przysięgą obiecał jej dać, czegobykolwiek żądała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'A ona przedtem będąc naprawiona od matki swojej, rzekła: Daj mi tu na misie głowę Jana Chrzciciela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'I zasmucił się król; ale dla przysięgi i dla spółsiedzących kazał jej dać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'A posławszy kata, ściął Jana w więzieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'I przyniesiono głowę jego na misie, i oddano dzieweczce, i odniosła ją matce swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'A przyszedłszy uczniowie jego wzięli ciało i pogrzebli je, a szedłszy powiedzieli Jezusowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'To usłyszawszy Jezus, ustąpił stamtąd w łodzi na miejsce puste osobno; a usłyszawszy lud, szli za nim z miast pieszo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Wyszedłszy tedy Jezus ujrzał wielki lud, i użalił się ich, a uzdrawiał chore ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'A gdy nadchodził wieczór, przystąpili do niego uczniowie jego, mówiąc: Puste jest to miejsce, a czas już przeminął; rozpuść ten lud, aby odszedłszy do miasteczek, kupili sobie żywności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'A Jezus im rzekł: Nie potrzeba im odchodzić, dajcie wy im co jeść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Ale mu oni rzekli: Nie mamy tu, tylko pięć chlebów i dwie ryby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'A on rzekł: Przynieście mi je tu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'I rozkazawszy ludowi usiąść na trawie, wziął onych pięć chlebów i dwie ryby, a wejrzawszy w niebo, błogosławił, a łamiąc dawał uczniom chleby, a uczniowie ludowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'I jedli wszyscy, a nasyceni byli; i zebrali, co zbywało ułomków, dwanaście koszów pełnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'A tych, którzy jedli, było około pięciu tysięcy mężów, oprócz niewiast i dziatek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'A wnetże przymusił Jezus uczniów swoich, aby wstąpili w łódź, i uprzedzili go na drugą stronę, ażby rozpuścił lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'A rozpuściwszy lud, wstąpił na górę z osobna, aby się modlił; a gdy był wieczór, sam tam był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'A łódź już w pośrodku morza będąc, miotana była od wałów; albowiem był wiatr przeciwny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Lecz o czwartej straży nocnej szedł do nich Jezus, chodząc po morzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'A ujrzawszy go uczniowie po morzu chodzącego, zatrwożyli się, mówiąc: Obłuda to jest! i od bojaźni krzyknęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Lecz wnet rzekł do nich Jezus, mówiąc: Ufajcie! Jam ci to jest; nie bójcie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'A odpowiadając mu Piotr rzekł: Panie! Jeźliżeś ty jest, każ mi przyjść do ciebie po wodzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'A on rzekł: Pójdź! A Piotr, wystąpiwszy z łodzi, szedł po wodzie, aby przyszedł do Jezusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Ale widząc wiatr gwałtowny, zląkł się; a gdy począł tonąć, zakrzyknął, mówiąc: Panie, ratuj mię!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'A Jezus zaraz wyciągnąwszy rękę, uchwycił go i rzekł mu: O małowierny! przeczżeś wątpił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'A gdy oni wstąpili w łódź, uciszył się wiatr.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'A ci, którzy byli w łodzi, przystąpiwszy pokłonili mu się, mówiąc: Prawdziwie jesteś Synem Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'I przeprawiwszy się, przyszli do ziemi Gienezaret.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'A poznawszy go mężowie miejsca onego, posłali do wszystkiej onej okolicznej krainy; i przyniesiono do niego wszystkie, którzy się źle mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'I prosili go, aby się tylko podołku szaty jego dotykali; a którzykolwiek się dotknęli, uzdrowieni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Tedy przystąpili do Jezusa z Jeruzalemu nauczeni w Piśmie i Faryzeuszowie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Czemu uczniowie twoi przestępują ustawę starszych? albowiem nie umywają rąk swych, gdy mają jeść chleb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'A on odpowiadając, rzekł im: Czemuż i wy przestępujecie przykazanie Boże dla ustawy waszej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Albowiem Bóg przykazał, mówiąc: Czcij ojca twego i matkę; i kto by złorzeczył ojcu albo matce, śmiercią niechaj umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Ale wy powiadacie: Kto by rzekł ojcu albo matce: Dar, którykolwiek jest ode mnie, tobie pożyteczny będzie; a nie uczciłby ojca swego albo matki swojej, bez winy będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'I wzruszyliście przykazania Boże dla ustawy waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Obłudnicy! dobrze o was prorokował Izajasz, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Lud ten przybliża się do mnie usty swemi, i wargami czci mię; ale serce ich daleko jest ode mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Lecz próżno mię czczą, nauczając nauk, które są przykazania ludzkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'A zawoławszy do siebie ludu, rzekł im: Słuchajcie, a rozumiejcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Nie to, co wchodzi w usta, pokala człowieka; ale co wychodzi z ust, to pokala człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Tedy przystąpiwszy uczniowie jego, rzekli mu: Wiesz, iż Faryzeuszowie, usłyszawszy tę mowę, zgorszyli się?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'A on odpowiadając rzekł: Wszelki szczep, którego nie szczepił Ojciec mój niebieski, wykorzeniony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Zaniechajcie ich; ślepi są wodzowie ślepych, a ślepy jeźliby ślepego prowadził, obadwa w dół wpadną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'A odpowiadając Piotr, rzekł mu: Wyłóż nam to podobieństwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'I rzekł Jezus: Jeszczeż i wy bezrozumni jesteście?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Jeszczeż nie rozumiecie, iż wszystko, co wchodzi w usta, w brzuch idzie, i do wychodu bywa wyrzucono?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Ale co z ust pochodzi, z serca wychodzi, a toć pokala człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Albowiem z serca wychodzą złe myśli, mężobójstwa, cudzołóstwa, wszeteczeństwa, złodziejstwa, fałszywe świadectwa, bluźnierstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Toć jest, co pokala człowieka: ale jeść nieumytemi rękoma, toć nie pokala człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'A wyszedłszy Jezus stamtąd, ustąpił w strony Tyru i Sydonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'A oto niewiasta Chananejska z onych granic wyszedłszy, wołała, mówiąc do niego: Zmiłuj się nade mną Panie, synu Dawidowy! córka moja ciężko bywa od dyjabła dręczona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'A on jej nie odpowiedział i słowa. Tedy przystąpiwszy uczniowie jego, prosili go, mówiąc: Odpraw ją, boć woła za nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'A on odpowiadając rzekł: Nie jestem posłany, tylko do owiec, które zginęły z domu Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Lecz ona przystąpiwszy, pokłoniła mu się, mówiąc: Panie, ratuj mię!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'A on odpowiadając rzekł: Niedobra jest brać chleb dziecinny, a miotać szczeniętom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'A ona rzekła: Tak jest, Panie! a wszakże i szczenięta jedzą odrobiny, które padają z stołu panów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Tedy odpowiadając Jezus rzekł jej: O niewiasto! wielka jest wiara twoja; niechaj ci się stanie, jako chcesz. I uzdrowiona jest córka jej od onejże godziny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'A Jezus poszedłszy stamtąd, przyszedł nad morze Galilejskie, a wstąpiwszy na górę, siedział tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'I przyszedł do niego wielki lud, mając z sobą chrome, ślepe, nieme, ułomne i inszych wiele, i kładli je u nóg Jezusowych, i uzdrawiał je,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'Tak iż się on lud dziwował, widząc, że niemi mówią, ułomni uzdrowieni są, chromi chodzą, a ślepi widzą; i wielbili Boga Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Lecz Jezus zwoławszy uczniów swoich, rzekł: Żal mi tego ludu; albowiem już trzy dni przy mnie trwają, a nie mają, co by jedli, a nie chcę ich rozpuścić głodnych, by snać nie pomdleli na drodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Tedy mu rzekli uczniowie jego: Skądże byśmy wzięli tak wiele chleba na tej puszczy, abyśmy tak wielki lud nasycili?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'I rzekł im Jezus: Wieleż macie chlebów? A oni rzekli: Siedm, i trochę rybek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Tedy rozkazał ludowi, aby siedli na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'A wziąwszy one siedm chlebów i one ryby, uczyniwszy dzięki, łamał i dał uczniom swoim, a uczniowie ludowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'I jedli wszyscy i nasyceni są, i zebrali, co zbyło ułomków, siedm koszów pełnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'A było tych, którzy jedli, cztery tysiące mężów, oprócz niewiast i dziatek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Tedy rozpuściwszy lud, wstąpił w łódź, i przyszedł na granice Magdalańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'A przystąpiwszy Faryzeuszowie i Saduceuszowie, kusząc prosili go, aby im znamię z nieba ukazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'A on odpowiadając, rzekł im: Gdy bywa wieczór, mówicie: Pogoda będzie; bo się niebo czerwieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'A rano: Dziś będzie niepogoda; albowiem się niebo pochmurne czerwieni. Obłudnicy! postawę nieba rozsądzić umiecie, a znamion tych czasów nie możecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Rodzaj zły i cudzołożny znamienia szuka; ale mu znamię nie będzie dane, tylko ono znamię Jonasza proroka. I opuściwszy je, odszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'A gdy się przeprawili uczniowie jego na drugą stronę morza, zapamiętali wziąć chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'I rzekł im Jezus: Patrzcie, a strzeżcie się kwasu Faryzeuszów i Saduceuszów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'A oni rozmawiali między sobą, mówiąc: Nie wzięliśmy chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Co obaczywszy Jezus, rzekł im: O czemże rozmawiacie między sobą, o małowierni, żeście chleba nie wzięli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Jeszczeż nie rozumiecie, ani pamiętacie onych pięciu chlebów, a onych pięciu tysięcy ludzi, i jakoście wiele koszów zebrali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Ani onych siedmiu chlebów i czterech tysięcy ludzi, a jakoście wiele koszów nazbierali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Jakoż nie rozumiecie, żem wam nie o chlebie powiedział, mówiąc: Abyście się strzegli kwasu Faryzeuszów i Saduceuszów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Tedy zrozumieli, że nie mówił, aby się strzegli kwasu chleba, ale nauki Faryzeuszów i Saduceuszów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'A gdy przyszedł Jezus w strony Cezaryi Filippowej, pytał uczniów swoich, mówiąc: Kimże mię powiadają być ludzie Syna człowieczego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'A oni rzekli: Jedni Janem Chrzcicielem, a drudzy Elijaszem, insi też Jeremijaszem, albo jednym z proroków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'I rzekł im: A wy kim mię być powiadacie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'A odpowiadając Szymon Piotr rzekł: Tyś jest Chrystus, on Syn Boga żywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Tedy odpowiadając Jezus rzekł mu: Błogosławiony jesteś Szymonie, synu Jonaszowy! bo tego ciało i krew nie objawiły tobie, ale Ojciec mój, który jest w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'A Ja ci też powiadam, żeś ty jest Piotr; a na tej opoce zbuduję kościół mój, a bramy piekielne nie przemogą go:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'I tobie dam klucze królestwa niebieskiego; a cokolwiek zwiążesz na ziemi, będzie związane i w niebiesiech; a cokolwiek rozwiążesz na ziemi, będzie rozwiązane i w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Tedy przykazał uczniom swoim, aby nikomu nie powiadali, że on jest Jezus Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'I odtąd począł Jezus pokazywać uczniom swoim, iż musi odejść do Jeruzalemu, i wiele cierpieć od starszych i od przedniejszych kapłanów i nauczonych w Piśmie, a być zabitym i trzeciego dnia zmartwychwstać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'A wziąwszy go Piotr na stronę, począł go strofować, mówiąc: Zmiłuj się sam nad sobą, Panie! nie przyjdzie to na cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'A on obróciwszy się, rzekł Piotrowi: Idź ode mnie, szatanie! jesteś mi zgorszeniem; albowiem nie pojmujesz tego, co jest Bożego, ale co jest ludzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Tedy rzekł Jezus do uczniów swoich: Jeźli kto chce iść za mną, niechajże samego siebie zaprze, a weźmie krzyż swój, i naśladuje mię!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Bo kto by chciał duszę swoję zachować, straci ją; a kto by stracił duszę swoję dla mnie, znajdzie ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Albowiem cóż pomoże człowiekowi, choćby wszystek świat pozyskał, a na duszy swojej szkodował? albo co za zamianę da człowiek za duszę swoję?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Albowiem Syn człowieczy przyjdzie w chwale Ojca swego z Anioły swoimi, a tedy odda każdemu według uczynków jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Zaprawdę powiadam wam: Są niektórzy z tych, co tu stoją, którzy nie ukuszą śmierci, ażby ujrzeli Syna człowieczego, idącego w królestwie swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'A po sześciu dniach wziął Jezus Piotra i Jakóba i Jana, brata jego, i wprowadził je na górę wysoką osobno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'I przemieniony jest przed nimi, a rozjaśniło się oblicze jego jako słońce, a szaty jego stały się białe jako światłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'A oto ukazali się im Mojżesz i Elijasz, z nim rozmawiający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'I odpowiadając Piotr, rzekł do Jezusa: Panie! dobrze nam tu być; jeźli chcesz, uczynimy tu trzy namioty, tobie jeden, i Mojżeszowi jeden, i Elijaszowi jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'A gdy on jeszcze mówił, oto obłok jasny zacienił je; a oto głos z obłoku mówiący: Ten jest Syn mój miły, w którym mi się upodobało, tego słuchajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'To usłyszawszy uczniowie, upadli na twarz swoję i bali się bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Tedy przystąpiwszy Jezus dotknął się ich i rzekł: Wstańcie, a nie bójcie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'A oni podniósłszy oczy swoje, nikogo nie widzieli, tylko Jezusa samego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'A gdy zstępowali z góry, przykazał im Jezus, mówiąc: Nikomu nie powiadajcie tego widzenia, aż Syn człowieczy zmartwychwstanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'I pytali go uczniowie jego, mówiąc: Cóż tedy nauczeni w Piśmie powiadają, że ma Elijasz pierwej przyjść?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'A Jezus odpowiadając, rzekł im: Elijaszci pierwej przyjdzie i naprawi wszystko;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Ale wam powiadam: Iż Elijasz już przyszedł, wszakże nie poznali go, ale uczynili mu, cokolwiek chcieli; takci i Syn człowieczy ma ucierpieć od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Tedy zrozumieli uczniowie, że o Janie Chrzcicielu mówił do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'A gdy przyszli do ludu, przystąpił do niego człowiek, i upadł przed nim na kolana,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'I rzekł: Panie! zmiłuj się nad synem moim: albowiem lunatykiem jest, i ciężko się trapi; częstokroć bowiem wpada w ogień, i częstokroć w wodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'I przywiodłem go do uczniów twoich, ale go nie mogli uzdrowić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'A odpowiadając Jezus, rzekł: O rodzaju niewierny i przewrotny! Dokądże będę z wami? Dokądże was będę cierpiał? przywiedźcie mi go sam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'I zgromił onego dyjabła Jezus; i wyszedł od niego, i uzdrowiony jest on młodzieniec od onejże godziny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Tedy przystąpiwszy uczniowie do Jezusa osobno, rzekli mu: Czemużeśmy go my wygnać nie mogli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Lecz Jezus rzekł do nich: Dla niedowiarstwa waszego; zaprawdę bowiem powiadam wam: Jeźlibyście, mając wiarę jako ziarno gorczyczne, rzekli tej górze: Przenieś się stąd na ono miejsce, tedy się przeniesie, a nic niemożebnego wam nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Ale ten rodzaj nie wychodzi, tylko przez modlitwę i przez post.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'A gdy przebywali w Galilei, rzekł do nich Jezus: Syn człowieczy będzie wydany w ręce ludzkie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'I zabiją go, ale trzeciego dnia zmartwychwstanie. I zasmucili się bardzo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'A gdy przyszli do Kapernaum, przystąpili do Piotra ci, którzy podatek wybierali, i rzekli: Izali nauczyciel wasz nie daje podatku?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'I rzekł: Tak. A gdy wchodził w dom, uprzedził go Jezus, mówiąc: Cóż ci się zda, Szymonie? Królowie ziemscy od kogoż biorą cło albo czynsz? od synów swoich, czyli od obcych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Rzekł mu Piotr: Od obcych. I rzekł mu Jezus: Toć tedy synowie są wolni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Wszakże abyśmy ich nie zgorszyli, szedłszy do morza, zarzuć wędkę, a tę rybę, która najpierwej uwięźnie, weźmij, a otworzywszy gębę jej, znajdziesz stater, który wziąwszy, daj im za mię i za się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Onej godziny przystąpili uczniowie do Jezusa, mówiąc: Któż wżdy największy jest w królestwie niebieskiem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'A zawoławszy Jezus dziecięcia, postawił je w pośrodku ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'I rzekł: Zaprawdę powiadam wam: Jeźli się nie nawrócicie i nie staniecie się jako dzieci, żadnym sposobem nie wnijdziecie do królestwa niebieskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Kto się tedy uniży jako to dziecię, tenci jest największym w królestwie niebieskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'A kto by przyjął jedno dziecię takie w imieniu mojem, mnie przyjmuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Kto by zaś zgorszył jednego z tych małych, którzy we mię wierzą, pożyteczniej by mu było, aby zawieszony był kamień młyński na szyi jego, a utopiony był w głębokości morskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Biada światu dla zgorszenia! albowiem muszą zgorszenia przyjść; wszakże biada człowiekowi onemu, przez którego przychodzi zgorszenie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Przetoż jeźli ręka twoja albo noga twoja gorszy cię, odetnij ją i zarzuć od siebie; lepiej jest tobie wnijść do żywota chromym albo ułomnym, niżeli dwie ręce albo dwie nogi mając, wrzuconym być do ognia wiecznego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'A jeźli cię oko twoje gorszy, wyłup je i zarzuć od siebie; lepiej jest tobie jednookim wnijść do żywota, niżeli oba oczy mając, być wrzuconym do ognia piekielnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Patrzajcież, abyście nie gardzili żadnym z tych maluczkich; albowiem wam powiadam, iż Aniołowie ich w niebiesiech zawsze patrzą na oblicze Ojca mojego, który jest w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Przyszedł bowiem Syn człowieczy, aby zbawił to, co było zginęło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Co się wam zda? Gdyby który człowiek miał sto owiec, a zabłąkałaby się jedna z nich, azaż nie zostawia onych dziewięćdziesięciu i dziewięciu, a poszedłszy na góry, nie szuka zbłąkanej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'A jeźli mu się zdarzy, znaleźć ją, zaprawdę powiadam wam, że się z niej bardziej raduje, niż z onych dziewięćdziesięciu i dziewięciu nie zbłąkanych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Tak nie jest wola Ojca waszego, który jest w niebiesiech, aby zginął jeden z tych maluczkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'A jeźliby zgrzeszył przeciwko tobie brat twój, idź, strofuj go między tobą i onym samym: jeźli cię usłucha, pozyskałeś brata twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Ale jeźli cię nie usłucha, przybierz do siebie jeszcze jednego albo dwóch, aby w uściech dwóch albo trzech świadków stanęło każde słowo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'A jeźliby ich nie usłuchał, powiedz zborowi; a jeźliby zboru nie usłuchał, niech ci będzie jako poganin i celnik.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Zaprawdę powiadam wam: Cokolwiek byście związali na ziemi, będzie związane i na niebie; a co byście rozwiązali na ziemi; będzie rozwiązane i na niebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Zasię powiadam wam: Iż gdyby się z was dwaj zgodzili na ziemi o wszelką rzecz, o którą by prosili, stanie się im od Ojca mego, który jest w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Albowiem gdzie są dwaj albo trzej zgromadzeni w imię moje, tam jestem w pośrodku ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Tedy przystąpiwszy do niego Piotr, rzekł: Panie! wielekroć zgrzeszy przeciwko mnie brat mój, a odpuszczę mu? czyż aż do siedmiu kroć?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'I rzekł mu Jezus: Nie mówię ci aż do siedmiu kroć, ale aż do siedmdziesiąt siedmiu kroć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Dlatego podobne jest królestwo niebieskie człowiekowi królowi, który się chciał rachować z sługami swymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'A gdy się począł rachować, stawiono mu jednego, który był winien dziesięć tysięcy talentów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'A gdy nie miał skąd oddać, kazał go pan jego zaprzedać, i żonę jego, i dzieci, i wszystko, co miał, i dług oddać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Upadłszy tedy sługa on, pokłonił mu się, mówiąc: Panie! miej cierpliwość nade mną, a wszystko ci oddam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'A użaliwszy się pan onego sługi, uwolnił go, i dług mu odpuścił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'A wyszedłszy on sługa, znalazł jednego z spółsług swoich, który mu był winien sto groszy; a porwawszy go, dusił go, mówiąc: Oddaj mi, coś winien.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Przypadłszy tedy on spółsługa jego do nóg jego, prosił go, mówiąc: Miej cierpliwość nade mną, a oddam ci wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Lecz on nie chciał, ale szedłszy wrzucił go do więzienia, ażby oddał, co był winien.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Ujrzawszy tedy spółsłudzy jego, co się stało, zasmucili się bardzo, a szedłszy oznajmili panu swemu wszystko, co się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Tedy zawoławszy go pan jego, rzekł mu: Sługo zły! wszystek on dług odpuściłem ci, żeś mię prosił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Azażeś się i ty nie miał zmiłować nad spółsługą twoim, jakom się i ja zmiłował nad tobą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'A rozgniewawszy się pan jego, podał go katom, ażby oddał to wszystko, co mu był winien.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Tak i Ojciec mój niebieski uczyni wam, jeźli nie odpuścicie każdy bratu swemu z serc waszych upadków ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'I stało się, gdy dokończył Jezus tych mów, odszedł z Galilei, a przyszedł na granice Judzkie nad Jordan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'I szedł za nim wielki lud, i uzdrawiał je tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Tedy przyszli do niego Faryzeuszowie, kusząc go i mówiąc mu: Godzili się człowiekowi opuścić żonę swoją dla każdej przyczyny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'A on odpowiadając rzekł im: Nie czytaliście, iż ten, który stworzył na początku człowieka, mężczyznę i niewiastę uczynił je?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'I rzekł: Dlatego opuści człowiek ojca i matkę, a przyłączy się do żony swojej, i będą dwoje jednem ciałem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'A tak już nie są dwoje, ale jedno ciało; co tedy Bóg złączył, człowiek niechaj nie rozłącza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Rzekli mu: Przeczże tedy Mojżesz kazał dać list rozwodny i opuścić ją?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Rzekł im: Mojżesz dla zatwardzenia serca waszego dopuścił wam, opuścić żony wasze, lecz z początku nie było tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Ale ja powiadam wam: Iż ktobykolwiek opuścił żonę swoję, (oprócz dla wszeteczeństwa), a inszą by pojął, cudzołoży; a kto by opuszczoną pojął, cudzołoży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Rzekli mu uczniowie jego: Jeźlić taka jest sprawa męża z żoną, tedy nie jest dobrze żenić się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'A on im rzekł: Nie wszyscy pojmują tej rzeczy, ale tylko ci, którym to dano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Albowiem są rzezańcy, którzy się tak z żywota matki narodzili; są też rzezańcy, którzy od ludzi są urzezani; są też rzezańcy, którzy się sami urzezali dla królestwa niebieskiego. Kto może pojąć, niechaj pojmuje!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Tedy mu przynoszono dziatki, aby na nie ręce wkładał i modlił się; ale uczniowie gromili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Lecz Jezus rzekł: Zaniechajcie dziatek, a nie zabraniajcie im przychodzić do mnie; albowiem takich jest królestwo niebieskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'A włożywszy na nie ręce, poszedł stamtąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'A oto jeden przystąpiwszy, rzekł mu: Nauczycielu dobry! co dobrego mam czynić, abym miał żywot wieczny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Ale mu on rzekł: Przecz mię zowiesz dobrym? nikt nie jest dobry, tylko jeden, to jest Bóg; a jeźli chcesz wnijść do żywota, przestrzegaj przykazań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'I rzekł mu: Których? A Jezus rzekł: Nie będziesz zabijał, nie będziesz cudzołożył, nie będziesz kradł, nie będziesz mówił fałszywego świadectwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Czcij ojca twego i matkę, i miłować będziesz bliźniego swego, jako siebie samego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Rzekł mu młodzieniec: Tegom wszystkiego przestrzegał od młodości swojej; czegoż mi jeszcze nie dostaje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Rzekł mu Jezus: Jeźli chcesz być doskonałym, idź, sprzedaj majętności twoje, i rozdaj ubogim, a będziesz miał skarb w niebie, a przyszedłszy, naśladuj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'A gdy młodzieniec te słowa usłyszał, odszedł smutny; albowiem wiele miał majętności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Tedy Jezus rzekł uczniom swoim: Zaprawdę powiadam wam, że z trudnością bogaty wnijdzie do królestwa niebieskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'I zasię powiadam wam: Że snadniej wielbłądowi przez ucho igielne przejść, niż bogatemu wnijść do królestwa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Co usłyszawszy uczniowie jego, zdumieli się bardzo, mówiąc: Któż tedy może być zbawion?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'A Jezus wejrzawszy na nie, rzekł im: U ludzić to nie można; lecz u Boga wszystko jest możebne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Tedy odpowiadając Piotr, rzekł mu: Otośmy my opuścili wszystko, i poszliśmy za tobą; cóż nam tedy za to będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'A Jezus rzekł im: Zaprawdę powiadam wam: Iż wy, którzyście mię naśladowali w odrodzeniu, gdy usiądzie Syn człowieczy na stolicy chwały swojej, usiądziecie i wy na dwunastu stolicach, sądząc dwanaście pokoleń Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'A każdy, kto by opuścił domy, albo braci, albo siostry, albo ojca, albo matkę, albo żonę, albo dzieci, albo rolę, dla imienia mego, stokroć więcej weźmie, i żywot wieczny odziedziczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'A wiele pierwszych będą ostatnimi, a ostatnich pierwszymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Albowiem podobne jest królestwo niebieskie człowiekowi gospodarzowi, który wyszedł bardzo rano najmować robotników do winnicy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'A zmówiwszy się z robotnikami z grosza na dzień posłał je do winnicy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'A wyszedłszy o trzeciej godzinie, ujrzał drugich, którzy stali na rynku próżnujący;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'I rzekł im: Idźcie i wy do winnicy, a co będzie sprawiedliwego, dam wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'A oni poszli. Zasię wyszedłszy o szóstej i dziewiątej godzinie, także uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Potem o jedenastej godzinie wyszedłszy, znalazł drugie, którzy stali próżnujący, i rzekł im: Przecz tu stoicie cały dzień próżnujący?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Rzekli mu: Iż nas nikt nie najął; i rzekł im: Idźcie i wy do winnicy, a co będzie sprawiedliwego, weźmiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'A gdy był wieczór, rzekł pan winnicy sprawcy swemu: Zawołaj robotników, a oddaj im zapłatę, począwszy od ostatnich aż do pierwszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'A gdy przyszli oni, którzy o jedenastej godzinie byli najęci, wziął każdy z nich po groszu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Przyszedłszy też i pierwsi, mniemali, że więcej wezmą; ale wzięli i oni, każdy z nich, po groszu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'A wziąwszy, szemrali przeciwko gospodarzowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Mówiąc: Ci ostatni jednę godzinę robili, a uczyniłeś je nam równymi, którzyśmy znosili ciężar dnia i upalenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'A on odpowiadając rzekł jednemu z nich: Przyjacielu! nie czynię ci krzywdy; azaż się nie z grosza zmówił ze mną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Weźmij, co twojego jest, a idź; chcę bowiem temu ostatniemu dać jako i tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Azaż mi się nie godzi czynić z mojem, co chcę? Czyli oko twoje złośliwe jest, iżem ja jest dobry?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Takci będą ostatni pierwszymi, a pierwsi ostatnimi; albowiem wiele jest wezwanych, ale mało wybranych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'A wstępując Jezus do Jeruzalemu, wziął z sobą dwanaście uczniów na osobne miejsce w drodze, i rzekł im:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Oto wstępujemy do Jeruzalemu, Syn człowieczy będzie wydany przedniejszym kapłanom i nauczonym w Piśmie, i osądzą go na śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'I wydadzą go poganom na pośmiewanie i na ubiczowanie i na ukrzyżowanie; ale trzeciego dnia zmartwychwstanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Tedy przystąpiła do niego matka synów Zebedeuszowych z synami swoimi, kłaniając mu się, i prosząc nieco od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'A on jej rzekł; Czegóż chcesz? Rzekła mu: Rzecz, aby siedzieli ci dwaj synowie moi, jeden po prawicy twojej a drugi po lewicy w królestwie twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Ale Jezus odpowiadając rzekł: Nie wiecie, o co prosicie; możecież pić kielich, który ja będę pił? i chrztem, którym się ja chrzczę, być ochrzczeni? Rzekli mu: Możemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Tedy im rzekł: Kielichci mój pić będziecie, i chrztem, którym się ja chrzczę, ochrzczeni będziecie; ale siedzieć po prawicy mojej i po lewicy mojej, nie jest moja rzecz dać wam, ale tym, którym jest zgotowano od Ojca mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'A usłyszawszy to oni dziesięciu, rozgniewali się na onych dwóch braci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Ale Jezus zwoławszy ich, rzekł: Wiecie, iż książęta narodów panują nad nimi, a którzy wielcy są, mocy dokazują nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Lecz nie tak będzie między wami: ale ktobykolwiek między wami chciał być wielkim, niech będzie sługą waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'A ktobykolwiek między wami chciał być pierwszym, niech będzie sługą waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Jako i Syn człowieczy nie przyszedł, aby mu służono, ale aby służył, i aby dał duszę swą na okup za wielu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'A gdy oni wychodzili z Jerycha, szedł za nim wielki lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'A oto dwaj ślepi, siedzący przy drodze, usłyszawszy, iż Jezus przechodził, zawołali, mówiąc: Zmiłuj się nad nami, Panie, synu Dawidowy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Ale on lud gromił ich, aby milczeli; lecz oni tem więcej wołali, mówiąc: Zmiłuj się nad nami, Panie, synu Dawidowy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'A zastanowiwszy się Jezus, zawołał ich i rzekł: Cóż chcecie, abym wam uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Rzekli mu: Panie! aby były otworzone oczy nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'A użaliwszy się ich Jezus, dotknął się oczu ich, a zaraz przejrzały oczy ich; i szli za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'A gdy się przybliżyli do Jeruzalemu, i przyszli do Betfagie, do góry oliwnej, tedy Jezus posłał dwóch uczniów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'Mówiąc im: Idźcie do miasteczka, które jest przeciwko wam, a zaraz znajdziecie oślicę uwiązaną i oślę z nią; odwiążcież je, a przywiedźcie do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'A jeźliby wam co kto rzekł, powiedzcie, iż Pan ich potrzebuje; a zarazem puści je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'A to się wszystko stało, aby się wypełniło, co powiedziano przez proroka, mówiącego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Powiedzcie córce Syońskiej: Oto król twój idzie tobie cichy, a siedzący na oślicy, i na oślęciu, synu oślicy pod jarzmem będącej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Szedłszy tedy uczniowie, a uczyniwszy tak, jako im był rozkazał Jezus,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Przywiedli oślicę i oślę, i włożyli na nie szaty swoje, i wsadzili go na nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'A wielki lud słał szaty swoje na drodze, a drudzy obcinali gałązki z drzew, i słali na drodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'A lud wprzód i pozad idący wołał, mówiąc: Hosanna synowi Dawidowemu! błogosławiony, który idzie w imieniu Pańskiem, Hosanna na wysokościach!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'A gdy on wjechał do Jeruzalemu, wzruszyło się wszystko miasto, mówiąc: Któż ten jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'A lud mówił: Tenci jest Jezus, on prorok z Nazaretu Galilejskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Tedy wszedł Jezus do kościoła Bożego, i wygnał wszystkie sprzedawające i kupujące w kościele, a stoły tych, co pieniędzmi handlowali, i stołki sprzedawających gołębie poprzewracał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'I rzekł im: Napisano: Dom mój dom modlitwy nazwany będzie; aleście wy uczynili z niego jaskinię zbójców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Tedy przystąpili do niego ślepi i chromi w kościele, i uzdrowił je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'A obaczywszy przedniejsi kapłani i nauczeni w Piśmie cuda, które czynił, i dzieci wołające w kościele, i mówiące: Hosanna synowi Dawidowemu: rozgniewali się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'I rzekli mu: Słyszyszże, co ci mówią? A Jezus im rzekł: I owszem. Nigdyścież nie czytali, iż z ust niemowlątek i ssących wykonałeś chwałę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'A opuściwszy je, wyszedł z miasta do Betanii, i tam został;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'A rano wracając się do miasta, łaknął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'I ujrzawszy jedno figowe drzewo przy drodze, przyszedł do niego, i nie znalazł nic na niem, tylko same liście, i rzekł mu: Niechaj się więcej z ciebie owoc nie rodzi na wieki. I uschło zarazem one figowe drzewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'A ujrzawszy to uczniowie, dziwowali się, mówiąc: Jakoć prędko uschło to figowe drzewo!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Tedy odpowiadając Jezus, rzekł im: Zaprawdę powiadam wam: Jeźlibyście mieli wiarę, a nie wątpilibyście, nie tylko to, co się stało z figowem drzewem, uczynicie, ale gdybyście i tej górze rzekli: Podnieś się, a rzuć się w morze, stanie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'I wszystko, o cobyściekolwiek prosili w modlitwie wierząc, weźmiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'A gdy on przyszedł do kościoła, przystąpili do niego, gdy uczył, przedniejsi kapłani i starsi ludu, mówiąc: Którąż mocą to czynisz? a kto ci dał tę moc?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'A odpowiadając Jezus, rzekł im: Spytam i ja was o jednę rzecz, którą jeźli mi powiecie, i ja wam powiem, którą mocą to czynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Chrzest Jana skąd był? z nieba czyli z ludzi? A oni myśleli sami w sobie, mówiąc: Jeźli powiemy z nieba, rzecze nam: Czemużeście mu tedy nie uwierzyli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Jeźli zaś powiemy z ludzi, boimy się ludu; bo Jana wszyscy mają za proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'A odpowiadając Jezusowi rzekli: Nie wiemy. Rzekł im i on: I ja wam nie powiem, którą mocą to czynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Ale cóż się wam zda? Człowiek niektóry miał dwóch synów; a przystąpiwszy do pierwszego, rzekł: Synu! idź, rób dziś na winnicy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Ale on odpowiadając rzekł: Nie chcę, a potem obaczywszy się, poszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'A przystąpiwszy do drugiego, rzekł także; a on odpowiadając rzekł: Ja idę, panie! ale nie szedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Któryż z tych dwóch uczynił wolę ojcowską? Rzekli mu: On pierwszy. Rzekł im Jezus: Zaprawdę powiadam wam, że was celnicy i wszetecznice uprzedzają do królestwa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Albowiem przyszedł do was Jan drogą sprawiedliwości, a nie uwierzyliście mu, ale celnicy i wszetecznice uwierzyli mu: a wy widząc to, przecież się nie obaczyliście, abyście mu uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Drugiego podobieństwa słuchajcie: Człowiek niektóry był gospodarzem, który nasadził winnicę, i płotem ją ogrodził, i wkopał w niej prasę, i zbudował wieżę, i najął ją winiarzom, i odjechał precz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'A gdy się przybliżył czas odbierania pożytków, posłał sługi swoje do onych winiarzy, aby odebrali pożytki jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Ale winiarze pojmawszy sługi jego, jednego ubili, a drugiego zabili, a drugiego ukamionowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Zasię posłał inszych sług, więcej niż pierwszych; i także im uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Ale na ostatek posłał syna swego, mówiąc: Będą się wstydzić syna mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Lecz winiarze, ujrzawszy onego syna, rzekli między sobą: Tenci jest dziedzic; pójdźcie, zabijmy go, a otrzymamy dziedzictwo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Tedy porwawszy go, wyrzucili go precz z winnicy i zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Gdy tedy pan winnicy przyjdzie, cóż uczyni onym winiarzom?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Rzekli mu: Złe, źle potraci, a winnicę najmie inszym winiarzom, którzy mu oddawać będą pożytki czasów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Rzekł im Jezus: Nie czytaliścież nigdy w Pismach: Kamień, który odrzucili budujący, ten się stał głową węgielną: od Panać się to stało, i dziwne jest w oczach naszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Przetoż powiadam wam: Iż od was odjęte będzie królestwo Boże, i będzie dane narodowi czyniącemu pożytki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'A kto by padł na ten kamień, roztrąci się, a na kogo by on upadł, zetrze go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'A usłyszawszy przedniejsi kapłani i Faryzeuszowie podobieństwa jego, domyślili się, iż o nich mówił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'A chcąc go pojmać, bali się ludu, ponieważ go mieli za proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'A odpowiadając Jezus, zasię im rzekł w podobieństwach, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Podobne jest królestwo niebieskie człowiekowi królowi, który sprawił wesele synowi swemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'I posłał sługi swe, aby wezwali zaproszonych na wesele; ale nie chcieli przyjść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Znowu posłał insze sługi, mówiąc: Powiedzcie zaproszonym: Otom obiad mój nagotował, woły moje i co było karmnego, pobito, i wszystko gotowe, pójdźcież na wesele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Ale oni zaniedbawszy odeszli, jeden do roli swojej, a drugi do kupiectwa swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'A drudzy pojmawszy sługi jego, zelżyli i pobili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Co gdy król usłyszał, rozgniewał się, a posławszy wojska swoje, wytracił one morderce, i miasto ich zapalił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Tedy rzekł sługom swoim: Weseleć wprawdzie jest gotowe; lecz zaproszeni nie byli godni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Przetoż idźcie na rozstania dróg, kogokolwiek znajdziecie, wezwijcie na wesele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Tedy wyszedłszy oni słudzy na drogi, zgromadzili wszystkie, którekolwiek znaleźli, złe i dobre, i napełnione jest wesele gośćmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'A wszedłszy król, aby oglądał goście, obaczył tam człowieka nie odzianego szatą weselną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'I rzekł mu: Przyjacielu! jakoś tu wszedł, nie mając szaty weselnej? A on zamilknął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Tedy rzekł król sługom: Związawszy nogi i ręce jego, weźmijcie go, a wrzućcie do ciemności zewnętrznych, tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Albowiem wiele jest wezwanych, ale mało wybranych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Tedy odszedłszy Faryzeuszowie uczynili radę, jako by go usidlili w mowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'I posłali do niego ucznie swoje z Herodyjany, mówiąc: Nauczycielu! wiemy, żeś jest prawdziwy, i drogi Bożej w prawdzie uczysz, a nie dbasz na nikogo; albowiem nie patrzysz na osobę ludzką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Przetoż powiedz nam, co ci się zda? Godzili się dać czynsz cesarzowi, czyli nie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Ale Jezus poznawszy złość ich, rzekł im: Czemuż mię kusicie, obłudnicy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Pokażcie mi monetę czynszową; a oni mu podali grosz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'I rzekł im: Czyjże to obraz i napis?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Rzekli mu: Cesarski. Tedy im rzekł: Oddawajcież tedy, co jest cesarskiego, cesarzowi, a co jest Bożego, Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'To usłyszawszy, zadziwili się, a opuściwszy go, odeszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Dnia onego przyszli do niego Saduceuszowie, którzy mówią, iż nie masz zmartwychwstania, i pytali go,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'Mówiąc: Nauczycielu! Mojżesz powiedział: Jeźliby kto umarł, nie mając dzieci, aby brat jego prawem powinowactwa pojął żonę jego, i wzbudził nasienie bratu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Było tedy u nas siedm braci; a pierwszy pojąwszy żonę, umarł, a nie mając nasienia, zostawił żonę swoję bratu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Także też wtóry i trzeci, aż do siódmego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'A na ostatek po wszystkich umarła i ona niewiasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Przetoż przy zmartwychwstaniu, któregoż z tych siedmiu będzie żoną, gdyż ją wszyscy mieli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'A odpowiadając Jezus rzekł im: Błądzicie, nie będąc powiadomieni Pisma, ani mocy Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Albowiem przy zmartwychwstaniu ani się żenić, ani za mąż chodzić nie będą, ale będą jako Aniołowie Boży w niebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'A o powstaniu umarłych nie czytaliście, co wam powiedziano od Boga mówiącego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Jam jest Bóg Abrahama, i Bóg Izaaka, i Bóg Jakóba? Bóg nie jestci Bogiem umarłych, ale żywych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'A usłyszawszy to lud, zdumiał się nad nauką jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Lecz gdy usłyszeli Faryzeuszowie, że zawarł usta Saduceuszom, zeszli się wespół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'I spytał go jeden z nich, zakonnik, kusząc go i mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Nauczycielu! które jest największe przykazanie w zakonie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'A Jezus mu rzekł: Będziesz miłował Pana, Boga twego, ze wszystkiego serca twego, i ze wszystkiej duszy twojej i ze wszystkiej myśli twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'To jest pierwsze i największe przykazanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'A wtóre podobne jest temuż: Będziesz miłował bliźniego twego, jako samego siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'Na tych dwóch przykazaniach wszystek zakon i prorocy zawisnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'A gdy się Faryzeuszowie zebrali, spytał ich Jezus,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'Mówiąc: Co się wam zda o Chrystusie? Czyim jest synem? Rzekli mu: Dawidowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'I rzekł im: Jakoż tedy Dawid w duchu nazywa go Panem? mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Rzekł Pan Panu memu: Siądź po prawicy mojej, aż położę nieprzyjacioły twoje podnóżkiem nóg twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Ponieważ go tedy Dawid nazywa Panem, jakoż jest synem jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'A żaden mu nie mógł odpowiedzieć i słowa, i nie śmiał go nikt więcej od onego dnia pytać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Tedy Jezus rzekł do ludu i do uczniów swoich, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'Na stolicy Mojżeszowej usiedli nauczeni w Piśmie i Faryzeuszowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Przetoż wszystkiego, czegokolwiek by wam rozkazali przestrzegać, przestrzegajcie i czyńcie, ale według uczynków ich nie czyńcie; albowiem oni mówią, ale nie czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Bo wiążą brzemiona ciężkie i nieznośne, i kładą je na ramiona ludzkie, lecz palcem swoim nie chcą ich ruszyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'A wszystkie uczynki swoje czynią, aby byli widziani od ludzi, i rozszerzają bramy swoje, i rozpuszczają podołki płaszczów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'Nadto miłują pierwsze miejsca na wieczerzach, i pierwsze stołki w bóżnicach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'I pozdrawiania na rynkach, i aby je nazywali ludzie: Mistrzu, mistrzu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Ale wy nie nazywajcie się mistrzami; albowiem jeden jest mistrz wasz, Chrystus; ale wy jesteście wszyscy braćmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'I nikogo nie zówcie ojcem waszym na ziemi; albowiem jeden jest Ojciec wasz, który jest w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'A niechaj was nie zowią mistrzami, gdyż jeden jest mistrz wasz, Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Ale kto z was największy jest, będzie sługą waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'A kto by się wywyższał, będzie poniżony; a kto by się poniżał, będzie wywyższony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Lecz biada wam, nauczeni w Piśmie i Faryzeuszowie obłudni! iż zamykacie królestwo niebieskie przed ludźmi; albowiem tam sami nie wchodzicie, ani tym, którzy by wnijść chcieli, wchodzić nie dopuszczacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Biada wam, nauczeni w Piśmie i Faryzeuszowie obłudni! iż pożeracie domy wdów, a to pod pokrywką długich modlitw, dlatego cięższy sąd odniesiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Biada wam, nauczeni w Piśmie i Faryzeuszowie obłudni! iż obchodzicie morze i ziemię, abyście uczynili jednego nowego Żyda; a gdy się stanie, czynicie go synem zatracenia, dwakroć więcej niżeliście sami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Biada wam, wodzowie ślepi! którzy powiadacie: kto by przysiągł na kościół, nic nie jest: ale kto by przysiągł na złoto kościelne, winien jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Głupi i ślepi! albowiem cóż jest większego, złoto czy kościół, który poświęca złoto?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'A kto by przysiągł na ołtarz, nic nie jest; lecz kto by przysiągł na dar, który jest na nim, winien jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Głupi i ślepi! albowiem cóż większego jest? dar, czyli ołtarz, który poświęca dar?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Kto tedy przysięga na ołtarz, przysięga na niego, i na to wszystko, co na nim jest;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'A kto przysięga na kościół, przysięga na niego, i na tego, który w nim mieszka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'I kto przysięga na niebo, przysięga na stolicę Bożą, i na tego, który siedzi na niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Biada wam, nauczeni w Piśmie i Faryzeuszowie obłudni! iż dawacie dziesięcinę z miętki i z anyżu i z kminu, a opuszczacie poważniejsze rzeczy w zakonie, sąd i miłosierdzie i wiarę; te rzeczy mieliście czynić, a onych nie opuszczać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Wodzowie ślepi! którzy przecedzacie komara, i wielbłąda połykacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Biada wam, nauczeni w Piśmie i Faryzeuszowie obłudni! iż oczyszczacie kubek z wierzchu i misę, a wewnątrz pełne są drapiestwa i zbytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Faryzeuszu ślepy! oczyść pierwej to, co jest wewnątrz w kubku i w misie, aby i to, co jest z wierzchu, czystem było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Biada wam, nauczeni w Piśmie i Faryzeuszowie obłudni! iżeście podobni grobom pobielanym, które się zdadzą z wierzchu być cudne, ale wewnątrz pełne są kości umarłych i wszelakiej nieczystości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Także i wy z wierzchu zdacie się być ludziom sprawiedliwi; ale wewnątrz jesteście pełni obłudy i nieprawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Biada wam, nauczeni w Piśmie i Faryzeuszowie obłudni! iż budujecie groby proroków, i zdobicie nagrobki sprawiedliwych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'I mówicie: Byśmy byli za dni ojców naszych, nie bylibyśmy uczestnikami ich we krwi proroków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'A tak świadczycie sami przeciwko sobie, że jesteście synowie tych, którzy proroki pozabijali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'I wy też dopełniacie miary ojców waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Wężowie! rodzaju jaszczurczy! i jakoż będziecie mogli ujść przed sądem ognia piekielnego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Przetoż oto ja posyłam do was proroki, i mędrce, i nauczone w Piśmie, a z nich niektóre zabijecie i ukrzyżujecie, a niektóre z nich ubiczujecie w bóżnicach waszych, i będziecie je prześladować od miasta do miasta;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'Aby przyszła na was wszystka krew sprawiedliwa, wylana na ziemi, ode krwi Abla sprawiedliwego aż do krwi Zacharyjasza, syna Barachyjaszowego, któregoście zabili między kościołem i ołtarzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Zaprawdę powiadam wam: Przyjdzie to wszystko na ten naród.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jeruzalem! Jeruzalem! które zabijasz proroki, i które kamionujesz te, którzy do ciebie byli posyłani: ilekroć chciałem zgromadzić dzieci twoje, tak jako zgromadza kokosz kurczęta swoje pod skrzydła, a nie chcieliście?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Oto wam dom wasz pusty zostanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Albowiem powiadam wam, że mię nie ujrzycie od tego czasu, aż rzeczecie: Błogosławiony, który idzie w imieniu Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'A wyszedłszy Jezus z kościoła szedł; i przystąpili uczniowie jego, aby mu ukazali budowanie kościelne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'I rzekł im Jezus: Izaż nie widzicie tego wszystkiego? Zaprawdę powiadam wam, nie zostanie tu kamień na kamieniu, który by nie był rozwalony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'A gdy siedział na górze oliwnej, przystąpili do niego uczniowie osobno, mówiąc: Powiedz nam, kiedy się to stanie, i co za znak przyjścia twego i dokonania świata?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'I odpowiadając Jezus, rzekł im: Patrzcie, aby was kto nie zwiódł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Albowiem wiele ich przyjdzie pod imieniem mojem, mówiąc: Jam jest Chrystus; i wiele ich zwiodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'I usłyszycie wojny i wieści o wojnach; patrzcież, abyście sobą nie trwożyli; albowiem musi to wszystko być, ale jeszcze nie tu jest koniec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Albowiem powstanie naród przeciwko narodowi, i królestwo przeciwko królestwu, i będą głody i mory i trzęsienia ziemi miejscami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Ale to wszystko jest początkiem boleści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Tedy was podadzą w udręczenie, i będą was zabijać, i będziecie w nienawiści u wszystkich narodów dla imienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'A tedy wiele się ich zgorszy, a jedni drugich wydadzą, i jedni drugich nienawidzieć będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'I wiele fałszywych proroków powstanie, i zwiodą wielu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'A iż się rozmnoży nieprawość, oziębnie miłość wielu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Ale kto wytrwa aż do końca, ten zbawion będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'I będzie kazana ta Ewangielija królestwa po wszystkim świecie, na świadectwo wszystkim narodom. A tedyć przyjdzie koniec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Przetoż gdy ujrzycie obrzydliwość spustoszenia, opowiedzianą przez Danijela proroka, stojącą na miejscu świętem, (kto czyta, niechaj uważa),');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'Tedy ci, co będą w ziemi Judzkiej, niech uciekają na góry;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'A kto na dachu, niechaj nie zstępuje, aby co wziął z domu swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'A kto na roli, niech się nazad nie wraca, aby wziął szaty swe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'A biada brzemiennym i piersiami karmiącym w one dni!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Przetoż módlcie się, aby nie było uciekanie wasze w zimie, albo w sabat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Albowiem naonczas będzie wielki ucisk, jaki nie był od początku świata aż dotąd, ani potem będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'A gdyby nie były skrócone one dni, nie byłoby zbawione żadne ciało: ale dla wybranych będą skrócone one dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Tedy jeźliby wam kto rzekł: Oto tu jest Chrystus, albo tam, nie wierzcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Albowiem powstaną fałszywi Chrystusowie, i fałszywi prorocy, i czynić będą znamiona wielkie i cuda, tak iżby zwiedli (by można) i wybrane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Otom wam przepowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Jeźliby wam tedy rzekli: Oto na puszczy jest, nie wychodźcie; oto w komorach, nie wierzcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Albowiem jako błyskawica wychodzi od wschodu słońca i ukazuje się aż na zachód, tak będzie i przyjście Syna człowieczego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Bo gdziekolwiek będzie ścierw, tam się zgromadzą i orły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'A zaraz po utrapieniu onych dni słońce się zaćmi, a księżyc nie da jasności swojej, i gwiazdy będą padać z nieba, i mocy niebieskie poruszą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Tedyć się ukaże znamię Syna człowieczego na niebie, a tedy będą narzekać wszystkie pokolenia ziemi, i ujrzą Syna człowieczego, przychodzącego na obłokach niebieskich, z mocą i z chwałą wielką;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'I pośle Anioły swoje z trąbą głosu wielkiego, i zgromadzą wybrane jego od czterech wiatrów, od krajów niebios aż do krajów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'A od drzewa figowego nauczcie się tego podobieństwa: Gdy się już gałąź jego odmładza i liście wypuszcza, poznajecie, iż blisko jest lato.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'Także i wy, gdy ujrzycie to wszystko, poznawajcie, iż blisko jest, a we drzwiach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Zaprawdę powiadam wam, że nie przeminie ten wiek, ażby się to wszystko stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Niebo i ziemia przeminą, ale słowa moje nie przeminą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'A o onym dniu i godzinie nikt nie wie, ani Aniołowie niebiescy, tylko sam Ojciec mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Ale jako było za dni Noego, tak będzie i przyjście Syna człowieczego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Albowiem jako za dni onych przed potopem jedli, i pili, i ożeniali się i za mąż wydawali, aż do onego dnia, którego wszedł Noe do korabia,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'I nie spostrzegli się, aż przyszedł potop i zabrał wszystkie: tak będzie i przyjście Syna człowieczego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Tedy będą dwaj na roli; jeden będzie wzięty, a drugi zostawiony;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Dwie będą mleć we młynie; jedna będzie wzięta, a druga zostawiona;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Czujcież tedy, ponieważ nie wiecie, której godziny Pan wasz przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'A to wiedzcie, że, gdyby wiedział gospodarz, o której straży złodziej ma przyjść, wżdyby czuł, i nie dałby podkopać domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Przetoż i wy bądźcie gotowi; bo której się godziny nie spodziejecie, Syn człowieczy przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Któryż tedy jest sługa wierny i roztropny, którego postanowił pan jego nad czeladzią swoją, aby im dawał pokarm na czas słuszny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Błogosławiony on sługa, którego by, przyszedłszy Pan jego, znalazł tak czyniącego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Zaprawdę powiadam wam, że go nad wszystkiemi dobrami swemi postanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'A jeźliby rzekł on zły sługa w sercu swojem: Odwłacza pan mój z przyjściem swojem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'I począłby bić spółsługi, a jeść i pić z pijanicami:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'Przyjdzie pan sługi onego, dnia, którego się nie spodzieje, i godziny, której nie wie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'I odłączy go, a część jego położy z obłudnikami; tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Tedy podobne będzie królestwo niebieskie dziesięciu pannom, które wziąwszy lampy swoje, wyszły przeciwko oblubieńcowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'A było z nich pięć mądrych, a pięć głupich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'One głupie wziąwszy lampy swoje, nie wzięły oleju z sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Lecz mądre wzięły oleju w naczynia swoje z lampami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'A gdy oblubieniec odwłaczał z przyjściem, zdrzemały się wszystkie i posnęły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'A o północy stał się krzyk: Oto oblubieniec idzie; wynijdźcie przeciwko niemu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Tedy wstały one wszystkie panny i ochędożyły lampy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Ale głupie rzekły do mądrych: Dajcie nam z oleju waszego, boć lampy nasze gasną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'I odpowiedziały one mądre, mówiąc: Nie damy, by snać nam i wam nie dostało; idźcie raczej do sprzedawających, a kupcie sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'A gdy odeszły kupować, przyszedł oblubieniec; a te, które były gotowe, weszły z nim na wesele; i zamknione są drzwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Lecz potem przyszły i one drugie panny, mówiąc: Panie, Panie, otwórz nam!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'A on odpowiadając, rzekł: Zaprawdę powiadam wam, nie znam was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Czujcież tedy; bo nie wiecie dnia ani godziny, której Syn człowieczy przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Albowiem jako człowiek precz odjeżdżający zwołał sług swoich i oddał im dobra swoje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'I dał jednemu pięć talentów, a drugiemu dwa, a drugiemu jeden, każdemu według przemożenia jego, i zaraz precz odjechał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'A poszedłszy on, który wziął pięć talentów, robił niemi, i zyskał drugie pięć talentów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Także i on, który wziął dwa, zyskał i ten drugie dwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Ale ten, który wziął jeden, odszedłszy wykopał dół w ziemi, i skrył pieniądze pana swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'A po długim czasie przyszedł pan onych sług, i rachował się z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Tedy przystąpiwszy on, który był wziął pięć talentów, przyniósł drugie pięć talentów, mówiąc: Panie! oddałeś mi pięć talentów, otom drugie pięć talentów zyskał niemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'I rzekł mu pan jego: To dobrze, sługo dobry i wierny! nad małem byłeś wiernym, nad wielem cię postanowię; wnijdź do radości pana twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'A przystąpiwszy i on, który był dwa talenty wziął, rzekł: Panie! oddałeś mi dwa talenty, otom drugie dwa talenty zyskał niemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Rzekł mu pan jego: To dobrze, sługo dobry i wierny! gdyżeś był wierny nad małem, nad wielem cię postanowię; wnijdź do radości pana twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'A przystąpiwszy i ten, który był wziął jeden talent, rzekł: Panie! wiedziałem, że jesteś człowiek srogi, który żniesz, gdzieś nie rozsiewał, i zbierasz, gdzieś nie rozsypywał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Bojąc się tedy, szedłem i skryłem talent twój w ziemię; oto masz, co twego jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'A odpowiadając pan jego, rzekł mu: Sługo zły i gnuśny! wiedziałeś, iż żnę, gdziem nie rozsiewał, i zbieram, gdziem nie rozsypywał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Przetożeś miał pieniądze moje dać tym, co pieniędzmi handlują, a ja przyszedłszy, wziąłbym był, co jest mojego, z lichwą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Przetoż weźmijcie od niego ten talent, a dajcie temu, który ma dziesięć talentów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, '(Albowiem każdemu, który ma, będzie dano, i obfitować będzie; a od tego, który nie ma, i to, co ma, będzie od niego odjęto.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'A niepożytecznego sługę wrzućcie do onych ciemności zewnętrznych, tam będzie płacz i zgrzytanie zębów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'A gdy przyjdzie Syn człowieczy w chwale swojej, i wszyscy święci Aniołowie z nim, tedy usiądzie na stolicy chwały swojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'I będą zgromadzone przed niego wszystkie narody, i odłączy je, jedne od drugich, jako pasterz odłącza owce od kozłów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'A postawi owce zaiste po prawicy swojej, a kozły po lewicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Tedy rzecze król tym, którzy będą po prawicy jego: Pójdźcie, błogosławieni Ojca mego! odziedziczcie królestwo wam zgotowane od założenia świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Albowiem łaknąłem, a daliście mi jeść; pragnąłem, a daliście mi pić; byłem gościem, a przyjęliście mię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'Byłem nagim, a przyodzialiście mię; byłem chorym, a nawiedziliście mię; byłem w więzieniu, a przychodziliście do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Tedy mu odpowiedzą sprawiedliwi, mówiąc: Panie! kiedyżeśmy cię widzieli łaknącym, a nakarmiliśmy cię? albo pragnącym, a napoiliśmy cię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'I kiedyśmy cię widzieli gościem, a przyjęliśmy cię? albo nagim, a przyodzialiśmy cię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Albo kiedyśmy cię widzieli chorym, albo w więzieniu, a przychodziliśmy do ciebie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'A odpowiadając król, rzecze im: Zaprawdę powiadam wam, cokolwiekieście uczynili jednemu z tych braci moich najmniejszych, mnieście uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Potem rzecze i tym, którzy będą po lewicy: Idźcie ode mnie, przeklęci! w ogień wieczny, który zgotowany jest dyjabłu i Aniołom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Albowiem łaknąłem, a nie daliście mi jeść; pragnąłem, a nie daliście mi pić;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'Byłem gościem, a nie przyjęliście mię; nagim, a nie przyodzialiście mię; chorym i w więzieniu, a nie nawiedziliście mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Tedy mu odpowiedzą i oni, mówiąc: Panie! kiedyśmy cię widzieli łaknącym, albo pragnącym, albo gościem, albo nagim, albo chorym, albo w więzieniu, a nie służyliśmy tobie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Tedy im odpowie, mówiąc: Zaprawdę powiadam wam, czegościekolwiek nie uczynili jednemu z tych najmniejszych, i mnieście nie uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'I pójdą ci na męki wieczne; ale sprawiedliwi do żywota wiecznego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'I stało się, gdy dokończył Jezus tych wszystkich mów, rzekł do uczniów swoich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Wiecie, iż po dwóch dniach będzie wielkanoc, a Syn człowieczy będzie wydany, aby był ukrzyżowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Tedy się zebrali przedniejsi kapłani i nauczeni w Piśmie i starsi ludu do dworu najwyższego kapłana, którego zwano Kaifasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'I naradzali się, jakoby Jezusa zdradą pojmali i zabili;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Lecz mówili: Nie w święto, aby nie był rozruch między ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'A gdy Jezus był w Betanii, w domu Szymona trędowatego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'Przystąpiła do niego niewiasta, mająca słoik alabastrowy maści bardzo kosztownej, i wylała ją na głowę jego, gdy siedział u stołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Co widząc uczniowie jego, rozgniewali się, mówiąc: I na cóż ta utrata?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Albowiem mogła być ta maść drogo sprzedana, i mogło się to dać ubogim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Co gdy poznał Jezus, rzekł im: Przecz się przykrzycie tej niewieście? Dobry zaprawdę uczynek uczyniła przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Albowiem ubogie zawsze macie z sobą, ale mnie nie zawsze mieć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Bo ona wylawszy tę maść na ciało moje, uczyniła to, gotując mię ku pogrzebowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Zaprawdę powiadam wam: Gdziekolwiek będzie kazana ta Ewangielija po wszystkim świecie, i to będzie powiadano, co ona uczyniła, na pamiątkę jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Tedy odszedłszy jeden ze dwunastu, którego zwano Judaszem Iszkaryjotem, do przedniejszych kapłanów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'Rzekł im: Co mi chcecie dać, a ja go wam wydam? A oni mu odważyli trzydzieści srebrników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'A odtąd szukał czasu sposobnego, aby go wydał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'A pierwszego dnia przaśników przystąpili uczniowie do Jezusa, mówiąc mu: Gdzież chcesz, żeć nagotujemy, abyś jadł baranka?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'A on rzekł: Idźcie do miasta, do niektórego człowieka, a rzeczcie mu: Kazałci nauczyciel powiedzieć: Czas mój blisko jest, u ciebie jeść będę baranka z uczniami moimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'I uczynili uczniowie, jako im rozkazał Jezus, i nagotowali baranka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'A gdy był wieczór, usiadł za stołem ze dwunastoma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'A gdy jedli, rzekł: Zaprawdę powiadam wam, iż jeden z was wyda mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'I zasmuciwszy się bardzo, poczęli mówić do niego każdy z nich: Azażem ja jest Panie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'A on odpowiadając, rzekł: Który macza ze mną rękę w misie, ten mię wyda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Synci człowieczy idzie, jako napisano o nim; ale biada człowiekowi temu, przez którego Syn człowieczy wydany bywa! dobrze by mu było, by się był nie narodził ten człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'A odpowiadając Judasz, który go wydawał, rzekł: Izalim ja jest, Mistrzu? Mówi mu: Tyś powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'A gdy oni jedli, wziąwszy Jezus chleb, a pobłogosławiwszy łamał, i dał uczniom i rzekł: Bierzcie, jedzcie, to jest ciało moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'A wziąwszy kielich i podziękowawszy, dał im, mówiąc: Pijcie z tego wszyscy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Albowiem to jest krew moja nowego testamentu, która się za wielu wylewa na odpuszczenie grzechów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Ale powiadam wam, iż nie będę pił odtąd z tego rodzaju winnej macicy, aż do dnia onego, gdy go będę pił z wami nowy w królestwie Ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'I zaśpiewawszy pieśń, wyszli na górę oliwną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Tedy im rzekł Jezus: Wy wszyscy zgorszycie się ze mnie tej nocy; albowiem napisano: Uderzę pasterza, i będą rozproszone owce trzody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Lecz gdy ja zmartwychwstanę, poprzedzę was do Galilei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'A odpowiadając Piotr, rzekł mu: Choćby się wszyscy zgorszyli z ciebie, ja się nigdy nie zgorszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Rzekł mu Jezus: Zaprawdę powiadam ci, iż tej nocy, pierwej niż kur zapieje, trzykroć się mnie zaprzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Rzekł mu Piotr: Choćbym z tobą miał i umrzeć, nie zaprę się ciebie. Także i wszyscy uczniowie mówili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Tedy przyszedł Jezus z nimi na miejsce, które zwano Gietsemane, i rzekł uczniom: Siądźcież tu, aż odszedłszy, będę się tam modlił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'A wziąwszy z sobą Piotra i dwóch synów Zebedeuszowych, począł się smęcić i tęsknić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Tedy im rzekł Jezus: Smętna jest dusza moja aż do śmierci; zostańcież tu, a czujcie ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'A postąpiwszy trochę, padł na oblicze swoje, modląc się i mówiąc: Ojcze mój, jeźli można, niech mię ten kielich minie; a wszakże nie jako ja chcę, ale jako ty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Tedy przyszedł do uczniów, i znalazł je śpiące, i rzekł Piotrowi: Takżeście nie mogli przez jednę godzinę czuć ze mną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Czujcież, a módlcie się, abyście nie weszli w pokuszenie; duchci jest ochotny, ale ciało mdłe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Zasię po wtóre odszedłszy, modlił się, mówiąc: Ojcze mój, jeźli mię nie może ten kielich minąć, tylko abym go pił, niech się stanie wola twoja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'A przyszedłszy, znalazł je zasię śpiące; albowiem oczy ich były obciążone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'A zaniechawszy ich, znowu odszedł i modlił się po trzecie, też słowa mówiąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Tedy przyszedł do uczniów swoich i rzekł im: Śpijcież już i odpoczywajcie; oto się przybliżyła godzina, a Syn człowieczy będzie wydany w ręce grzeszników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Wstańcie, pójdźmy! oto się przybliżył ten, który mię wydaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'A gdy on jeszcze mówił, oto Judasz, jeden z dwunastu, przyszedł, a z nim wielka zgraja z mieczami i z kijami, od przedniejszych kapłanów i starszych ludu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Ale ten, który go wydawał, dał był im znak, mówiąc: Któregokolwiek pocałuję, tenci jest; imajcież go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'A wnet przystąpiwszy do Jezusa, rzekł: Bądź pozdrowiony, Mistrzu! i pocałował go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Ale mu rzekł Jezus: Przyjacielu! na coś przyszedł? Tedy przystąpiwszy, rzucili ręce na Jezusa i pojmali go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'A oto jeden z tych, którzy byli z Jezusem, wyciągnął rękę, i dobył miecza swego, a uderzywszy sługę kapłana najwyższego, uciął mu ucho.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Tedy mu rzekł Jezus: Obróć miecz swój na miejsce jego; albowiem wszyscy, którzy miecz biorą, od miecza poginą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Azaż mniemasz, że bym nie mógł teraz prosić Ojca mego, a stawiłby mi więcej niż dwanaście wojsk Aniołów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Ale jakożby się wypełniły Pisma, które mówią, iż się tak musi stać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'Onejże godziny mówił Jezus do onej zgrai: Wyszliście jako na zbójcę z mieczami i z kijmi, pojmać mię; na każdy dzień siadałem u was, ucząc w kościele, a nie pojmaliście mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Aleć się to wszystko stało, aby się wypełniły Pisma prorockie. Tedy uczniowie jego wszyscy opuściwszy go, uciekli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'A oni pojmawszy Jezusa, wiedli go do Kaifasza, najwyższego kapłana, gdzie się byli zebrali nauczeni w Piśmie i starsi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Ale Piotr szedł za nim z daleka aż do dworu najwyższego kapłana; a wszedłszy tam, siedział z sługami, aby ujrzał koniec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Ale przedniejsi kapłani i starsi, i wszelka rada szukali fałszywego świadectwa przeciwko Jezusowi, aby go na śmierć wydali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'Ale nie znaleźli; i choć wiele fałszywych świadków przychodziło, przecię nie znaleźli. A na ostatek wystąpiwszy dwaj fałszywi świadkowie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Rzekli: Ten mówił: Mogę rozwalić kościół Boży, a za trzy dni zbudować go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'A wstawszy najwyższy kapłan, rzekł mu: Nic nie odpowiadasz? Cóż to jest, co ci przeciwko tobie świadczą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Lecz Jezus milczał. A odpowiadając najwyższy kapłan rzekł: Poprzysięgam cię przez Boga żywego, abyś nam powiedział, jeźliś ty jest Chrystus, on Syn Boży?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Rzekł mu Jezus: Tyś powiedział; wszakże powiadam wam: Odtąd ujrzycie Syna człowieczego siedzącego na prawicy mocy Bożej, i przychodzącego na obłokach niebieskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Tedy najwyższy kapłan rozdarł szaty swoje, mówiąc: Bluźnił! Cóż jeszcze potrzebujemy świadków? Otoście teraz słyszeli bluźnierstwo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Cóż się wam zda? A oni odpowiadając, rzekli: Winien jest śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Tedy plwali na oblicze jego, i pięściami go bili, a drudzy go policzkowali,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'Mówiąc: Prorokuj nam, Chrystusie! kto jest ten, co cię uderzył?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Ale Piotr siedział przed domem na podwórzu. Tedy przystąpiła do niego jedna dziewka, mówiąc: I tyś był z tym Jezusem Galilejskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'A on się zaprzał przed wszystkimi, mówiąc: Nie wiem, co powiadasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'A gdy on wychodził do przysionka, ujrzała go insza dziewka, i rzekła do tych, co tam byli: I tenci był z tym Jezusem Nazareńskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Tedy po wtóre zaprzał się z przysięgą, mówiąc: Nie znam tego człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'A przystąpiwszy po małej chwilce ci, co tam stali, rzekli Piotrowi: Prawdziwie i tyś jest z nich; bo i mowa twoja ciebie wydaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Tedy się począł przeklinać i przysięgać, mówiąc: Nie znam tego człowieka; a zarazem kur zapiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'I wspomniał Piotr na słowa Jezusowe, który mu był powiedział: Pierwej niż kur zapieje, trzykroć się mnie zaprzesz; a wyszedłszy precz, gorzko płakał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'A gdy było rano, weszli w radę wszyscy przedniejsi kapłani i starsi ludu przeciwko Jezusowi, aby go zabili;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'I związawszy go, wiedli i podali Ponckiemu Piłatowi, staroście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Tedy Judasz, który go był wydał, widząc, iż był osądzony, żałując tego, wrócił trzydzieści srebrników, przedniejszym kapłanom i starszym ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'Mówiąc: Zgrzeszyłem, wydawszy krew niewinną! A oni rzekli: Cóż nam do tego? ty ujrzysz!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'A porzuciwszy one srebrniki w kościele, odszedł, a odszedłszy powiesił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Ale przedniejsi kapłani wziąwszy one srebrniki, mówili: Nie godzi się ich kłaść do skarbu kościelnego, gdyż zapłata jest krwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'I naradziwszy się, kupili za nie rolę garncarzową na pogrzeb gościom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Dlatego ona rola nazwana jest rolą krwi, aż do dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Tedy się wypełniło, co powiedziano przez Jeremijasza proroka, mówiącego: I wzięli trzydzieści srebrników, zapłatę oszacowanego, który był oszacowany od synów Izraelskich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'I dali je za rolę garncarzową, jako mi postanowił Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'A Jezus stał przed starostą; i pytał go starosta, mówiąc: Tyżeś jest on król żydowski? A Jezus mu rzekł: Ty powiadasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'A gdy nań skarżyli przedniejsi kapłani i starsi, nic nie odpowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Tedy mu rzekł Piłat: Nie słyszyszże jako wiele przeciwko tobie świadczą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Lecz mu nie odpowiedział i na jedno słowo, tak iż się starosta bardzo dziwował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Ale na święto zwykł był starosta wypuszczać ludowi jednego więźnia, którego by chcieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'I mieli natenczas więźnia znacznego, którego zwano Barabbasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'A gdy się zebrali, rzekł do nich Piłat: Któregoż chcecie, abym wam wypuścił? Barabbasza, czyli Jezusa, którego zowią Chrystusem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Bo wiedział, iż go z nienawiści wydali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'A gdy on siedział na sądowej stolicy, posłała do niego żona jego, mówiąc: Nie miej żadnej sprawy z tym sprawiedliwym; bom wiele ucierpiała dziś we śnie dla niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Ale przedniejsi kapłani i starsi namówili lud, aby prosili o Barabbasza, a Jezusa, aby stracili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'A odpowiadając starosta, rzekł im: Którego chcecie, abym wam z tych dwóch wypuścił? a oni odpowiedzieli: Barabbasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Rzekł im Piłat: Cóż tedy uczynię z Jezusem, którego zowią Chrystusem? Rzekli mu wszyscy: Niech będzie ukrzyżowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'A starosta rzekł: Cóż wżdy złego uczynił? Ale oni tem bardziej wołali, mówiąc: Niech będzie ukrzyżowany!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'A widząc Piłat, iż to nic nie pomagało, ale owszem się większy rozruch wszczynał, wziąwszy wodę, umył ręce przed ludem, mówiąc: Nie jestem ja winien krwi tego sprawiedliwego; wy ujrzycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'A odpowiadając wszystek lud, rzekł: Krew jego na nas i na dziatki nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Tedy im wypuścił Barabbasza; ale Jezusa ubiczowawszy, wydał go, aby był ukrzyżowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Tedy żołnierze starościni przywiódłszy Jezusa na ratusz, zebrali do niego wszystkę rotę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'A zewlekłszy go, przyodziali go płaszczem szarłatowym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'I uplótłszy koronę z ciernia, włożyli na głowę jego, i dali trzcinę w prawą rękę jego, a upadając przed nim na kolana, naśmiewali się z niego, mówiąc: Bądź pozdrowiony, królu żydowski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'A plując na niego, wzięli onę trzcinę, i bili go w głowę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'A gdy się z niego naśmiali, zewlekli go z onego płaszcza, i oblekli go w szatę jego, i wiedli go, aby był ukrzyżowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'A wychodząc znaleźli człowieka Cyrenejczyka, imieniem Szymon; tego przymusili, aby niósł krzyż jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'A przyszedłszy na miejsce rzeczone Golgota, które zowią miejscem trupich głów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Dali mu pić ocet z żółcią zmieszany; a skosztowawszy, nie chciał pić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'A ukrzyżowawszy go, rozdzielili szaty jego, i miotali los, aby się wypełniło, co powiedziano przez proroka: Rozdzielili sobie szaty moje, a o odzienie moje los miotali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'A siedząc, strzegli go tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'I przybili nad głową jego winę jego napisaną: Ten jest Jezus, król żydowski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Byli też ukrzyżowani z nim dwaj zbójcy, jeden po prawicy, a drugi po lewicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'A ci, którzy mimo chodzili, bluźnili go, chwiejąc głowami swojemi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'I mówiąc: Ty, co rozwalasz kościół, a w trzech dniach budujesz go, ratuj samego siebie; jeźliś jest Syn Boży, zstąp z krzyża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Także i przedniejsi kapłani z nauczonymi w Piśmie, i z starszymi, naśmiewając się, mówili:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Inszych ratował, a samego siebie ratować nie może; jeźliż jest król Izraelski, niech teraz zstąpi z krzyża, a uwierzymy mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Dufał w Bogu, niechże go teraz wybawi, jeźli się w nim kocha; boć powiedział: Jestem Synem Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Także też i zbójcy, którzy byli z nim ukrzyżowani, urągali mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'A od szóstej godziny stała się ciemność po wszystkiej ziemi aż do dziewiątej godziny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'A około dziewiątej godziny zawołał Jezus głosem wielkim, mówiąc: Eli, Eli, Lama Sabachtani! to jest, Boże mój! Boże mój! czemuś mię opuścił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Tedy niektórzy z tych, co tam stali, usłyszawszy to, mówili: Elijasza ten woła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'A zarazem bieżawszy jeden z nich, wziął gąbkę, i napełnił ją octem, a włożywszy na trzcinę, dał mu pić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'A drudzy mówili: Zaniechaj; patrzajmy, jeźli przyjdzie Elijasz, aby go wybawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Ale Jezus zawoławszy po wtóre głosem wielkim, oddał ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'A oto zasłona kościelna rozerwała się na dwoje od wierzchu aż do dołu, i trzęsła się ziemia, a skały się rozpadały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'I groby się otwierały, a wiele ciał świętych, którzy byli zasnęli, powstało:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'A wyszedłszy z grobów po zmartwychwstaniu jego, weszli do miasta świętego, i pokazali się wielom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Tedy setnik i ci, co z nim Jezusa strzegli, widząc trzęsienie ziemi, i to, co się działo, zlękli się bardzo, mówiąc: Prawdziwieć ten był Synem Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'A było tam wiele niewiast z daleka się przypatrujących, które były przyszły za Jezusem od Galilei, posługując mu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Między któremi była Maryja Magdalena, i Maryja, matka Jakóbowa i Jozesowa, i matka synów Zebedeuszowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'A gdy był wieczór, przyszedł człowiek bogaty z Arymatyi, imieniem Józef, który też był uczniem Jezusowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Ten przyszedłszy do Piłata, prosił o ciało Jezusowe. Tedy Piłat rozkazał, aby mu było ono ciało oddane;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'A Józef wziąwszy ono ciało, uwinął je w czyste prześcieradło;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'I położył je w nowym grobie swoim, który był w opoce wykował; a przywaliwszy do drzwi grobowych kamień wielki, odszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'A była tam Maryja Magdalena, i druga Maryja, które siedziały przeciwko grobowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'A drugiego dnia, który był pierwszy po przygotowaniu, zgromadzili się przedniejsi kapłani i Faryzeuszowie do Piłata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'Mówiąc: Panie! wspomnieliśmy, iż on zwodziciel powiedział, gdy jeszcze żyw był: Po trzech dniach zmartwychwstanę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Rozkaż tedy obwarować grób aż do dnia trzeciego, by snać przyszedłszy uczniowie jego w nocy, nie ukradli go, i nie powiedzieli ludowi, iż powstał od umarłych; i będzie pośledni błąd gorszy niż pierwszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Rzekł im Piłat: Macie straż, idźcież, obwarujcie, jako umiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'A oni poszedłszy, osadzili grób strażą, zapieczętowawszy kamień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'A gdy się skończył sabat, i już świtało na pierwszy dzień onego tygodnia, przyszła Maryja Magdalena i druga Maryja, aby grób oglądały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'A oto stało się wielkie trzęsienie ziemi; albowiem Anioł Pański zstąpiwszy z nieba, przystąpił i odwalił kamień ode drzwi, i usiadł na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'A było wejrzenie jego jako błyskawica, a szata jego biała jako śnieg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'A ci, którzy strzegli grobu, drżeli, bojąc się go, i stali się jako umarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Ale Anioł odpowiadając, rzekł do niewiast: Nie bójcie się wy; boć wiem, iż Jezusa ukrzyżowanego szukacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Nie maszci go tu; albowiem powstał, jako powiedział; chodźcie, oglądajcie miejsce, gdzie leżał Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'A prędko idąc, powiedzcie uczniom jego, że zmartwychwstał; a oto uprzedza was do Galilei, tam go ujrzycie; otom wam powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Tedy wyszedłszy prędko od grobu z bojaźnią i z radością wielką, bieżały, aby to opowiedziały uczniom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'A gdy szły, aby to opowiedziały uczniom jego, oto Jezus spotkał się z niemi, mówiąc: Bądźcie pozdrowione. A one przystąpiwszy, uchwyciły się nóg jego i pokłoniły mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Tedy im rzekł Jezus: Nie bójcie się; idźcie, opowiedzcie braciom moim, aby poszli do Galilei, a tam mię ujrzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'A gdy one poszły, oto niektórzy z straży przyszedłszy do miasta, oznajmili przedniejszym kapłanom wszystko, co się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Którzy zgromadziwszy się z starszymi, i naradziwszy się, dali niemało pieniędzy żołnierzom,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'Mówiąc: Powiadajcie, iż uczniowie jego w nocy przyszedłszy, ukradli go, gdyśmy spali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'A jeźliby się to do starosty doniosło, my go namówimy, a was bezpiecznymi uczynimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'A oni wziąwszy pieniądze, uczynili, jako ich nauczono. I rozniosła się ta powieść między Żydy aż do dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Lecz jedenaście uczniów poszli do Galilei na górę, gdzie im był naznaczył Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Ale ujrzawszy go, pokłonili mu się; lecz niektórzy wątpili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Ale Jezus przystąpiwszy, mówił do nich, a rzekł: Dana mi jest wszelka moc na niebie i na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Idąc tedy, nauczajcie wszystkie narody, chrzcząc je w imię Ojca, i Syna, i Ducha Świętego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Ucząc je przestrzegać wszystkiego, com wam przykazał. A oto Jam jest z wami po wszystkie dni, aż do skończenia świata. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Ten jest początek Ewangielii Jezusa Chrystusa, Syna Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Jako napisano w prorokach: Oto Ja posyłam Anioła mego przed obliczem twojem, który zgotuje drogę twoję przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Głos wołającego na puszczy: Gotujcie drogę Pańską, proste czyńcie ścieżki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Jan chrzcił na puszczy, i kazał chrzest pokuty na odpuszczenie grzechów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'I wychodziła do niego wszystka kraina Judzka, i Jeruzalemczycy, a wszyscy byli od niego chrzczeni w rzece Jordanie, wyznawając grzechy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Ale Jan przyodziany był sierścią wielbłądową, a pas skórzany był około biódr jego, a jadał szarańczę i miód leśny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'I kazał, mówiąc: Idzie za mną możniejszy niżeli ja, któremum nie jest godzien, schyliwszy się, rozwiązać rzemyka u obuwia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Jamci was chrzcił wodą; ale on was będzie chrzcił Duchem Świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'I stało się w one dni, że przyszedł Jezus z Nazaretu Galilejskiego, a ochrzczony jest od Jana w Jordanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'A zarazem wystąpiwszy z wody, ujrzał rozstępujące się niebiosa, i Ducha jako gołębicę na niego zstępującego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'I stał się głos z nieba: Tyś jest on Syn mój miły, w którym mi się upodobało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'A zaraz Duch wypędził go na puszczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'I był tam na puszczy przez czterdzieści dni, będąc kuszony od szatana, a był z zwierzęty, a Aniołowie służyli mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Lecz potem, gdy Jan był podany do więzienia, przyszedł Jezus do Galilei, każąc Ewangieliję królestwa Bożego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'A mówiąc: Wypełnił się czas i przybliżyło się królestwo Boże: Pokutujcie, a wierzcie Ewangielii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'A przechodząc się nad morzem Galilejskiem, ujrzał Szymona i Andrzeja, brata jego, zapuszczających sieć w morze; bo byli rybitwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'I rzekł im Jezus: Pójdźcie za mną, a uczynię was rybitwami ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'A oni zarazem opuściwszy sieci swoje, poszli za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'A stamtąd troszeczkę odszedłszy, ujrzał Jakóba, syna Zebedeuszowego, i Jana, brata jego, a oni w łodzi poprawiali sieci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'I zaraz ich powołał; a oni zostawiwszy ojca swego Zebedeusza w łodzi z czeladzią, poszli za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Potem weszli do Kapernaum; a zaraz w sabat wszedłszy Jezus do bóżnicy, nauczał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'I zdumiewali się nad nauką jego; albowiem on ich uczył jako mający moc, a nie jako nauczeni w Piśmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'A był w bóżnicy ich człowiek mający ducha nieczystego, który zawołał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'Mówiąc: Ach! cóż my z tobą mamy, Jezusie Nazareński? Przyszedłeś, abyś nas wytracił. Znam cię, ktoś jest, żeś on święty Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'I zgromił go Jezus, mówiąc: Umilknij, a wynijdź z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Tedy rozdarłszy go duch nieczysty i zawoławszy głosem wielkim, wyszedł z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'I wylękli się wszyscy, tak iż się pytali między sobą, mówiąc: Cóż to jest? cóż to za nowa nauka, iż mocą i duchom nieczystym rozkazuje, i są mu posłuszni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'I rozeszła się powieść o nim prędko po wszystkiej krainie, leżącej około Galilei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'A wyszedłszy zaraz z bóżnicy, przyszli do domu Szymonowego i Andrzejowego z Jakóbem i z Janem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'A świekra Szymonowa leżała, mając gorączkę, o której mu wnet powiedzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Tedy przystąpiwszy podniósł ją, ująwszy ją za rękę jej; a zaraz ją gorączka opuściła, i posługowała im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'A gdy był wieczór i słońce zachodziło, przynosili do niego wszystkie, którzy się źle mieli, i opętane;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'A wszystko miasto zgromadziło się do drzwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'I uzdrowił wiele tych, co się źle mieli na rozliczne choroby, i wygnał wiele dyjabłów, a nie dopuścił mówić dyjabłom; bo go znali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'A bardzo rano przede dniem wstawszy, wyszedł i odszedł na puste miejsce, a tam się modlił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'I poszli za nim Szymon i ci, którzy z nim byli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'A znalazłszy go, rzekli mu: Wszyscy cię szukają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Tedy im on rzekł: Idźmy do przyległych miasteczek, abym i tam kazał; bom na to przyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'I kazał w bóżnicach ich po wszystkiej Galilei, i wyganiał dyjabły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Tedy przyszedł do niego trędowaty, prosząc go i upadając przed nim na kolana, i mówiąc mu: Jeźli chcesz, możesz mię oczyścić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'A tak Jezus użaliwszy się, wyciągnął rękę, a dotknął się go i rzekł mu: Chcę, bądź oczyszczony!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'A gdy to Pan rzekł, zarazem odszedł trąd od niego, i był oczyszczony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'A srodze mu przygroziwszy Jezus, zaraz go odprawił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'I rzekł mu: Patrz, abyś nikomu nic nie powiadał, ale idź, a ukaż się kapłanowi, i ofiaruj za oczyszczenie twoje to, co rozkazał Mojżesz, na świadectwo przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Ale on odszedłszy, począł wiele opowiadać i rozsławiać tę rzecz, tak iż już nie mógł Jezus jawnie wnijść do miasta, ale był na ustroniu na miejscach pustych. I schodzili się do niego zewsząd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'A zasię przyszedł po kilku dniach do Kapernaum, i usłyszano, że jest w domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'A wnet zeszło się ich tak wiele, że się zmieścić nie mogli ani przede drzwiami; i opowiadał im słowo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Tedy przyszli do niego niosący powietrzem ruszonego, którego czterej nieśli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'A gdy do niego przystąpić nie mogli dla ciżby, odarli dach, gdzie był Jezus, a przełamawszy go, spuścili po powrozach na dół łoże, na którem leżał powietrzem ruszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'A widząc Jezus wiarę ich, rzekł powietrzem ruszonemu: Synu! odpuszczone są tobie grzechy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'A byli tam niektórzy z nauczonych w Piśmie, siedząc i myśląc w sercach swoich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Czemuż ten takie mówi bluźnierstwa? któż może grzechy odpuszczać, tylko sam Bóg?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'A zaraz poznawszy Jezus duchem swym, iż tak w sobie myśleli, rzekł im: Czemuż tak myślicie w sercach waszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Cóż łatwiejszego jest, rzec powietrzem ruszonemu: Odpuszczone są tobie grzechy, czyli rzec: Wstań i weźmij łoże twoje, a chodź?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Ale żebyście wiedzieli, iż Syn człowieczy ma moc na ziemi grzechy odpuszczać, rzekł powietrzem ruszonemu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Tobie mówię: Wstań, a weźmij łoże twoje, a idź do domu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'A on zarazem wstał, i wziąwszy łoże swoje, wyszedł przed wszystkimi, tak iż się wszyscy zdumiewali i chwalili Boga, mówiąc: Nigdyśmy nic takiego nie widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'I wyszedł zasię nad morze, a wszystek lud przychodził do niego, i nauczał je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'A idąc mimo cła, ujrzał Lewiego, syna Alfeuszowego, siedzącego na cle, i rzekł mu: Pójdź za mną! a on wstawszy szedł za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'I stało się, gdy Jezus siedział za stołem w domu jego, że wiele celników i grzeszników wespół siedziało z Jezusem i z uczniami jego; bo ich wiele było, i chodzili za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'A nauczeni w Piśmie i Faryzeuszowie widząc go, że jadł z celnikami i z grzesznikami, mówili do uczniów jego: Cóż jest, iż z celnikami i z grzesznikami je i pije?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'A usłyszawszy to Jezus, rzekł im: Nie potrzebują zdrowi lekarza, ale ci, co się źle mają; nie przyszedłem, wzywać sprawiedliwych, ale grzesznych do pokuty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'A uczniowie Janowi i Faryzejscy pościli, a przyszedłszy mówili do niego: Czemuż uczniowie Janowi i Faryzejscy poszczą, a twoi uczniowie nie poszczą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'I rzekł im Jezus: Izali mogą synowie łożnicy małżeńskiej pościć, póki z nimi jest oblubieniec? Póki z sobą oblubieńca mają, nie mogą pościć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Ale przyjdą dni, gdy od nich odjęty będzie oblubieniec, a tedy będą pościć w one dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'A żaden nie wprawuje łaty sukna nowego w szatę wiotchą, inaczej ona jego łata nowa ujmuje nieco od wiotchej szaty, i stawa się gorsze rozdarcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'I żaden nie leje wina młodego w stare statki; bo inaczej wino młode rozsadza statki, i wycieka wino, a statki się psują; ale wino nowe ma być wlewane w statki nowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'I stało się, że szedł Jezus w sabat przez zboża, i poczęli uczniowie jego idąc rwać kłosy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Ale Faryzeuszowie mówili do niego: Oto czemu ci czynią w sabat, czego się nie godzi czynić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'A on im rzekł: Nigdyście nie czytali, co uczynił Dawid, gdy niedostatek cierpiał, a łaknął, sam i ci, którzy z nim byli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Jako wszedł do domu Bożego za Abijatara, kapłana najwyższego, i jadł chleby pokładne, (których się nie godziło jeść, tylko kapłanom), a dał i tym, którzy z nim byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Dotego rzekł im: Sabat dla człowieka uczyniony, a nie człowiek dla sabatu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Dlatego Syn człowieczy jest Panem i sabatu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Wszedł zasię do bóżnicy, a był tam człowiek, który miał rękę uschłą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'I podstrzegali go, jeźliby go w sabat uzdrowił, aby go oskarżyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'I rzekł onemu człowiekowi, który miał rękę uschłą: Wystąp w pośrodek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'I rzekł do nich: Godzili się w sabat dobrze czynić, czyli źle czynić? człowieka zachować, czyli zabić? a oni milczeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Tedy spojrzawszy po nich z gniewem i zasmuciwszy się nad zatwardzeniem serca ich, rzekł onemu człowiekowi: Wyciągnij rękę twoję! i wyciągnął; i przywrócona jest ręka jego do zdrowia jako i druga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Tedy wyszedłszy Faryzeuszowie, uczynili wnet radę z Herodyjany przeciwko niemu, jakoby go stracili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Ale Jezus z uczniami swymi ustąpił nad morze, a wielkie mnóstwo szło za nim z Galilei i z ziemi Judzkiej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'I z Jeruzalemu, i z Idumei, i zza Jordanu, i z tych, którzy mieszkali około Tyru i Sydonu, wielkie mnóstwo, słysząc, jak wielkie rzeczy czynił, przyszli do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'I rozkazał uczniom swoim, aby łódkę mieli zawsze w pogotowiu, dla ludu, aby go nie cisnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Albowiem ich wiele uzdrawiał, tak iż nań padali, aby się go dotykali, którzykolwiek choroby mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'A duchowie nieczyści, gdy go ujrzeli, upadali przed nim i wołali, mówiąc: Ty jesteś Syn Boży!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Ale ich on srodze gromił, żeby go nie objawiali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'I wstąpił na górę, a wezwał do siebie tych, których sam chciał, i przyszli do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'I postanowił ich dwanaście, aby z nim byli, a iżby je wysłał kazać Ewangieliję:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'I żeby mieli moc uzdrawiać choroby i wyganiać dyjabły:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Szymona, któremu imię dał Piotr;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'I Jakóba, syna Zebedeuszowego, i Jana, brata Jakóbowego, (którym dał imię Boanerges, to jest: synowie gromu);');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'I Andrzeja, i Filipa, i Bartłomieja, i Mateusza, i Tomasza, i Jakóba, syna Alfeuszowego, i Tadeusza, i Szymona Kananejczyka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'I Judasza Iszkaryjota, który go też wydał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'I przyszli do domu. I zgromadził się znowu lud, tak iż nie mogli ani chleba jeść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'A gdy o tem usłyszeli jego powinni, przyszli, aby go pojmali; bo mówili, że odszedł od rozumu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'A nauczeni w Piśmie, którzy byli przyszli z Jeruzalemu, mówili: Iż ma Beelzebuba, a iż przez książęcia dyjabelskiego wygania dyjabły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'I wezwawszy ich, mówił do nich w podobieństwach: Jakoż może szatan szatana wyganiać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'A jeźliże królestwo samo w sobie będzie rozdzielone, nie może się ostać ono królestwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'I dom, jeźliby sam przeciwko sobie był rozdzielony, nie będzie się mógł ostać on dom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'Takci, jeźli szatan powstał sam przeciwko sobie i jest rozdzielony, nie może się ostać, ale koniec bierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Nikt nie może sprzętu mocarzowego, wszedłszy do domu jego, rozchwycić, jeźliby pierwej mocarza onego nie związał; a potem dom jego splądruje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Zaprawdę powiadam wam, że wszystkie grzechy synom ludzkim będą odpuszczone, i bluźnierstwa, któremibykolwiek bluźnili;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'Ale kto bluźni przeciwko Duchowi Świętemu, nie ma odpuszczenia na wieki, ale winien jest sądu wiecznego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Bo mówili: Ma ducha nieczystego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Przyszli tedy bracia i matka jego, a stojąc przed domem, posłali do niego, i kazali go zawołać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'A lud siedział około niego, i rzekli mu: Oto matka twoja i bracia twoi szukają cię przed domem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Ale im on odpowiedział, mówiąc: Któż jest matka moja, i bracia moi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'A spojrzawszy wokoło po tych, którzy koło niego siedzieli, rzekł: Oto matka moja, i bracia moi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Albowiem ktobykolwiek czynił wolę Bożą, ten jest brat mój, i siostra moja, i matka moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'I począł zasię uczyć przy morzu; i zgromadził się do niego lud wielki, tak iż wstąpiwszy w łódź, siedział na morzu, a wszystek lud był przy morzu na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'I nauczał ich wiele rzeczy w podobieństwach, a mówił do nich w nauce swojej: Słuchajcie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Oto wyszedł rozsiewca, aby rozsiewał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'I stało się, gdy rozsiewał, że jedno padło podle drogi, a ptaki niebieskie przyleciały i podziobały je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Drugie zasię padło na miejsce opoczyste, gdzie nie miało wiele ziemi; i prędko weszło, przeto iż nie miało głębokości ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'A gdy słońce weszło, wygorzało, a iż korzenia nie miało, uschło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'A drugie padło między ciernie; i wzrosły ciernie i zadusiły je, i nie wydało pożytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Drugie zasię padło na ziemię dobrą, i wydało pożytek bujno wschodzący i rosnący; i przyniosło jedno trzydziesiątny, a drugie sześćdziesiątny, a drugie setny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'I mówił im: Kto ma uszy ku słuchaniu, niechaj słucha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'A gdy sam tylko był, pytali go ci, co przy nim byli ze dwunastoma, o to podobieństwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'A on im odpowiedział: Wam dano wiedzieć tajemnicę królestwa Bożego; ale tym, którzy są obcymi, wszystko się podawa w podobieństwach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'Aby patrząc patrzeli, ale nie widzieli, i słysząc słyszeli, ale nie zrozumieli, by się snać nie nawrócili, a byłyby im grzechy odpuszczone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Zatem rzekł do nich: Nie rozumiecie tego podobieństwa? A jakoż zrozumiecie wszystkie inne podobieństwa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Rozsiewca on rozsiewa słowo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'A którzy podle drogi, ci są, którym się rozsiewa słowo; ale gdy usłyszeli, zaraz przychodzi szatan, a wybiera słowo wsiane w serca ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Także i ci, którzy na opoczystych miejscach posiani są, ci są, którzy, gdy usłyszeli słowo, zaraz je z radością przyjmują;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'Wszakże nie mają korzenia w sobie, ale są doczesnymi; potem, gdy przychodzi ucisk albo prześladowanie dla słowa, wnet się gorszą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'A którzy między cierniem są posiani, ci są, którzy słuchają słowa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'Ale pieczołowanie świata tego i omamienie bogactw, i pożądliwości innych rzeczy, wszedłszy zaduszają słowo, i staje się bez pożytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'A którzy na dobrą ziemię przyjęli nasienie, ci są, co słuchają słowa, i przyjmują je, przynoszą pożytek, jedno trzydziesiątny, a drugie sześćdziesiątny, a drugie setny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Nadto mówił im: Izali przynoszą świecę, aby wstawiona była pod korzec albo pod łoże? izali nie dlatego, aby ją na świecznik wstawiono?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Bo nic nie masz tajemnego, co by nie miało być objawiono; ani się stało co skrytego, aby na jaw nie wyszło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Jeźli kto ma uszy ku słuchaniu, niechaj słucha!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'I rzekł do nich: Patrzcież, czego słuchacie; jaką miarą mierzycie, taką wam będzie odmierzono, a będzie wam przydano, którzy słuchacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Albowiem kto ma, będzie mu dano; a kto nie ma, i to, co ma, będzie od niego odjęto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'I mówił: Takie jest królestwo Boże, jako gdyby człowiek wrzucił nasienie w ziemię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'A spałby i wstawałby we dnie i w nocy, a nasienie by weszło i urosło, gdy on nie wie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Boć ziemia sama z siebie pożytek wydawa, naprzód trawę, potem kłos, a potem zupełne zboże w kłosie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'A skoro się okaże urodzaj, wnet gospodarz zapuszcza sierp; bo żniwo przyszło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Nad to rzekł: Do czego przypodobamy królestwo Boże, albo którem je podobieństwem wyrazimy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Jest jako ziarno gorczyczne; które, gdy wsiane bywa w ziemię, najmniejsze jest ze wszystkich nasion, które są na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Ale gdy bywa wsiane, wzrasta, i bywa największe nad wszystkie jarzyny, i rozpuszcza gałęzie wielkie, tak iż pod cieniem jego mogą sobie czynić gniazda ptaki niebieskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'I przez wiele takich podobieństw mówił do nich słowo, tak jako słuchać mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'A bez podobieństwa nie mówił do nich; wszakże uczniom swym wszystko z osobna wykładał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'I rzekł do nich w tenże dzień, gdy już był wieczór: Przeprawmy się na drugą stronę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'A rozpuściwszy lud, wzięli go z sobą, tak jako był w łodzi; ale i inne łódki były przy nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Tedy powstała wielka nawałność wiatru, a wały biły na łódź, tak że się już napełniała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'A on na zadzie łodzi spał na wezgłówku; i obudzili go i mówili mu: Nauczycielu! nie dbasz, że giniemy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'A tak ocknąwszy się, zgromił wiatr, i rzekł morzu: Umilknij, a uśmierz się. I przestał wiatr, a stało się wielkie uciszenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Zatem rzekł im: Przecz jesteście tak bojaźliwi? Jakoż nie macie wiary?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'I bali się bojaźnią wielką, i mówili jedni do drugich: Któż wżdy ten jest, że mu i wiatr i morze są posłuszne?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Tedy się przeprawili za morze do krainy Gadareńczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'A gdy on wyszedł z łodzi, zaraz mu zabieżał z grobów człowiek mający ducha nieczystego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Który miał mieszkanie w grobach, a nie mógł go nikt i łańcuchami związać,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Przeto że on często będąc pętami i łańcuchami związany, łańcuchy porwał, i pęta pokruszył; a nie mógł go nikt ukrócić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'A zawsze we dnie i w nocy na górach w grobach był, wołając i kamieniem się tłukąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Ujrzawszy tedy Jezusa z daleka, bieżał i pokłonił mu się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'A wołając głosem wielkim, rzekł: Cóż mam z tobą Jezusie, Synu Boga najwyższego? Poprzysięgam cię przez Boga, abyś mię nie trapił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, '(Albowiem mu mówił: Wynijdź, duchu nieczysty! z tego człowieka.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Tedy go pytał: Co masz za imię? A on odpowiadając, rzekł: Imię moje jest wojsko: albowiem nas jest wiele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'I prosił go bardzo, aby ich nie wyganiał z onej krainy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'A była tam przy górach wielka trzoda świni, która się pasła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'I prosili go oni wszyscy dyjabli, mówiąc: Puść nas w te świnie, abyśmy w nie weszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'I pozwolił im zaraz Jezus. A wyszedłszy oni duchowie nieczyści, weszli w one świnie; i porwała się ona trzoda z przykra w morze (a było ich około dwóch tysięcy,) i potonęły w morzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'A oni, którzy świnie paśli, uciekli, i oznajmili to w mieście i we wsiach; i wyszli, aby oglądali to, co się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'I przyszli do Jezusa, i ujrzeli onego, który był opętany, i siedział obleczony, będąc przy dobrem baczeniu; onego, mówię, w którym było wojsko dyjabłów; i bali się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'A ci, którzy to widzieli, opowiedzieli im, co się działo z onym opętanym, i o świniach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Tedy go poczęli prosić, aby odszedł z granic ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'A gdy wstąpił w łódź, prosił go on, co był opętanym, aby był przy nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Lecz mu Jezus nie dopuścił, ale mu rzekł: Idź do domu swego, do swoich, a oznajmij im, jakoć wielkie rzeczy Pan uczynił, a jako się nad tobą zmiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Tedy odszedł, i począł opowiadać w dziesięciu miastach, jako mu wielkie rzeczy uczynił Jezus; i dziwowali się wszyscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'A gdy się zasię Jezus przeprawił w łodzi na drugą stronę, zebrał się do niego wielki lud; a on był nad morzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'A oto przyszedł jeden z przełożonych bóżnicy, imieniem Jairus, a ujrzawszy go, przypadł do nóg jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'I prosił go wielce, mówiąc: Ponieważ córeczka moja kona, pójdźże, włóż na nię ręce, aby była uzdrowiona, i będzie żywa. I poszedł z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'I szedł za nim lud wielki, i cisnęli go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Tedy niektóra niewiasta, która cierpiała płynienie krwi ode dwunastu lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'I wiele ucierpiała od wielu lekarzy, i wynałożyła wszystko, co miała; a nic jej nie pomogło, owszem się jej tem więcej pogorszało:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Usłyszawszy o Jezusie, przyszła z tyłu między ludem, i dotknęła się szaty jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Bo mówiła: Jeźli się tylko dotknę szaty jego, będę uzdrowiona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'A zarazem wyschło źródło krwi jej, i poczuła na ciele, że uzdrowiona była od choroby swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'A wnet poznawszy Jezus sam w sobie, że z niego moc wyszła, obrócił się do ludu i rzekł: Kto się dotknął szat moich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'I rzekli mu uczniowie jego: Widzisz, że cię ten lud ciśnie, a mówisz: Kto się mnie dotknął?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'I spojrzał w koło, aby ujrzał tę, która to uczyniła:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Ale niewiasta ona z bojaźnią i ze drżeniem, wiedząc, co się przy niej stało, przystąpiła i upadła przed nim, a powiedziała mu wszystkę prawdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Zatem jej on rzekł: Córko! wiara twoja ciebie uzdrowiła, idźże w pokoju, a bądź zdrowa od choroby twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'A gdy on jeszcze mówił, przyszli słudzy od przełożonego bóżnicy, mówiąc: Córka twoja umarła, czemuż jeszcze trudzisz nauczyciela?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Ale Jezus skoro usłyszał to, co oni mówili, rzekł do przełożonego bóżnicy: Nie bój się, tylko wierz!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'I nie dopuścił nikomu iść za sobą, tylko Piotrowi, i Jakóbowi, i Janowi, bratu Jakóbowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'A przyszedł do domu przełożonego bóżnicy, i ujrzał tam zgiełk, i płaczące i bardzo narzekające.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Wszedłszy tedy, rzekł im: Przecz zgiełk czynicie i płaczecie? nie umarłać dzieweczka, ale śpi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'I naśmiewali się z niego. Ale on wygnawszy wszystkie, wziął z sobą ojca i matkę dzieweczki, i te, którzy przy nim byli, i wszedł tam, gdzie dzieweczka leżała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'A ująwszy za rękę onę dzieweczkę, rzekł do niej: Talita kumi! co się wykłada: Dzieweczko (tobie mówię) wstań!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'A zaraz dzieweczka wstała, i chodziła; albowiem była w dwunastym roku. I zdumieli się zdumieniem wielkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Tedy im przykazał wielce, aby tego nikt nie wiedział, i rozkazał, aby jej dano jeść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'A wyszedłszy stamtąd przyszedł do ojczyzny swojej, i szli za nim uczniowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'A gdy przyszedł sabat, począł uczyć w bóżnicy, a wiele ich słuchając, zdumiewali się i mówili: Skądże temu to wszystko? a co to za mądrość, która mu jest dana, że się i takie mocy dzieją przez ręce jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Izali ten nie jest cieśla, syn Maryi, i brat Jakóba, i Jozesa, i Judasa, i Szymona? Azaż tu nie masz i sióstr jego u nas? I gorszyli się z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Ale Jezus rzekł do nich: Nie jestci prorok beze czci, chyba w ojczyźnie swojej, a między pokrewnymi, i w domu swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'I nie mógł tam uczynić żadnego cudu, oprócz iż niektóre chore, wkładając na nie ręce, uzdrowił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'A dziwował się niedowiarstwu ich, i obchodził okoliczne miasteczka, nauczając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Tedy zwoławszy do siebie onych dwunastu, począł je po dwóch rozsyłać, i dał im moc nad duchami nieczystymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'I rozkazał im, aby nic nie brali na drogę, jedno tylko laskę: ani taistry, ani chleba, ani w trzos pieniędzy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Ale żeby się obuli w trzewiki, a nie obłoczyli dwóch sukien.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Zatem mówił do nich: Gdziekolwiek wnijdziecie w dom, tam zostańcie, póki byście stamtąd nie wyszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'A którzykolwiek by was nie przyjęli, ani was słuchali, wyszedłszy stamtąd, otrząśnijcie proch z nóg waszych na świadectwo im; zaprawdę powiadam wam: Lżej będzie Sodomie i Gomorze w dzień sądny, niż miastu onemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Tedy wyszedłszy kazali, aby ludzie pokutowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'I wyganiali wiele dyjabłów, i wiele chorych olejkiem mazali i uzdrawiali je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'A usłyszał o tem król Herod, (bo się imię jego stało rozsławione,) i rzekł: Jan Chrzciciel zmartwychwstał, dlatego się cuda dzieją przez niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'A drudzy mówili: Elijasz to jest; drudzy zaś mówili: Prorok to jest, albo jako jeden z onych proroków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Co usłyszawszy Herod, rzekł: Ten jest Jan, któregom ja ściął, on zmartwychwstał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Albowiem tenże Herod posławszy pojmał Jana, i wsadził go do więzienia dla Herodyjady, żony Filipa, brata swego, iż ją był pojął za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Bo Jan mówił Herodowi: Nie godzi się mieć żony brata twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'A Herodyjas czyhała nań, i chciała go zabić, ale nie mogła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Albowiem Herod obawiał się Jana, wiedząc, iż był mężem sprawiedliwym i świętym; i oglądał się nań, i słuchając go, wiele czynił i rad go słuchał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'A gdy przyszedł dzień sposobny, którego Herod, obchodząc pamiątkę narodzenia swego, wieczerzą sprawił na książęta swoje i na hetmany i na przedniejsze z Galilei;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'A gdy weszła córka onej Herodyjady i tańcowała, i podobała się Herodowi i spółsiedzącym, rzekł król do dzieweczki: Proś mię o co chcesz, a dam ci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'I przysiągł jej: O cokolwiek byś mię prosiła, dam ci, aż do połowy królestwa mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Ona tedy wyszedłszy, rzekła matce swojej: O co mam prosić? A ona rzekła: O głowę Jana Chrzciciela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'A tak ona zaraz wszedłszy prędko do króla, prosiła mówiąc: Chcę, abyś mi teraz dał na misie głowę Jana Chrzciciela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'I zasmucił się król bardzo, wszakże dla przysięgi i dla spółsiedzących nie chciał jej odmówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'A zarazem posławszy król kata, rozkazał przynieść głowę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'A on poszedłszy ściął go w więzieniu, i przyniósł głowę jego na misie, a dał ją dzieweczce, a dzieweczka dała ją matce swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Co gdy usłyszeli uczniowie jego, przyszli i wzięli ciało jego, i położyli je w grobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'A Apostołowie zszedłszy się do Jezusa, opowiedzieli mu wszystko, i co czynili, i czego uczyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'I rzekł im: Pójdźcie wy sami osobno na miejsce puste, a odpocznijcie trochę; bo ich wiele było, co przychodzili, i odchodzili, tak iż nie mieli wolnego czasu, żeby jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'I odjechali w łodzi na miejsce puste osobno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'A widząc je lud, że odjeżdżali, poznało go wiele ich, i zbieżeli się tam pieszo ze wszystkich miast, i poprzedzili je, i zgromadzili się do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'A wyszedłszy Jezus ujrzał wielki lud, i użalił się ich, iż byli jako owce nie mające pasterza, i począł ich nauczać wiele rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'A gdy już czas mijał, przystąpiwszy do niego uczniowie jego, rzekli: To miejsce jest puste, a już czas mija.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Rozpuść je, aby poszedłszy do okolicznych wsi i miasteczek, nakupili sobie chleba; bo nie mają, coby jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'A on odpowiadając, rzekł im: Dajcie wy im jeść. I rzekli mu: Szedłszy kupimy za dwieście groszy chleba, a damy im jeść?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'A on im rzekł: Wieleż chleba macie? Idźcie, a dowiedzcie się. A oni dowiedziawszy się, powiedzieli: Pięcioro, i dwie ryby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Tedy im kazał wszystkie gromadami posadzić na zielonej trawie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'I usiedli rząd podle rządu, tu po stu, tu zaś po pięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'A wziąwszy one pięć chlebów, i one dwie ryby, wejrzawszy w niebo, błogosławił. I połamał one chleby i dawał uczniom swoim, aby kładli przed nie; i one dwie ryby rozdzielił między wszystkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'I jedli wszyscy, i nasyceni byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'I zebrali ułomków, dwanaście koszów pełnych, i z onych ryb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'A było tych, którzy jedli chleby, około pięciu tysięcy mężów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'I wnet przymusił ucznie swoje, aby wstąpili w łódź, i uprzedzili go na drugą stronę ku Betsaidzie, ażby on rozpuścił lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'A odprawiwszy je, odszedł na górę, aby się modlił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'A gdy był wieczór, była łódź w pośród morza, a on sam był na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'I widział, że się spracowali, wiosłami robiąc; (bo wiatr mieli przeciwny,) a tak około czwartej straży nocnej przyszedł do nich, chodząc po morzu, i chciał je wyminąć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Ale oni ujrzawszy go chodzącego po morzu, mniemali, żeby była obłuda, i krzyknęli:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, '(Bo go wszyscy widzieli, i wylękli się.) Ale zaraz przemówił do nich, i rzekł im: Ufajcie, jam jest; nie bójcie się!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'I wstąpił do nich w łódź, i uciszył się wiatr; a oni się sami w sobie nader zdumiewali i dziwowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Bo nie zrozumieli z strony chlebów, gdyż serce ich było zdrętwiało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'A przeprawiwszy się przyszli do ziemi Gienezaret i przybili się do brzegu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'A gdy wyszli z łodzi, zaraz ci, co go poznali,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'Obieżawszy wszystkę onę okoliczną krainę, poczęli nosić na łożach tych, którzy się źle mieli, gdziekolwiek usłyszeli o nim, że tam jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'A gdziekolwiek on wszedł do miasteczek, albo do miast, albo do wsi, kładli niemocne po ulicach, i prosili go, aby się tylko dotykali podołka szaty jego; a ile się go ich dotknęli, byli uzdrowieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Tedy się zgromadzili do niego Faryzeuszowie, i niektórzy z nauczonych w Piśmie, którzy byli przyszli z Jeruzalemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'A ujrzawszy niektóre z uczniów jego, że pospolitemi rękoma, (to jest, nieumytemi) jedli chleb, ganili to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Albowiem Faryzeuszowie i wszyscy Żydzi nie jedzą, jeźliby pilnie rąk nie umyli, trzymając ustawę starszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'I z rynku przyszedłszy, jeźliby się nie umyli, nie jedzą; i innych rzeczy wiele jest, które przyjęli ku trzymaniu, jako umywanie kubków, konewek, i miednic, i stołów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Potem go pytali Faryzeuszowie i nauczeni w Piśmie: Przecz uczniowie twoi nie chodzą według podania starszych, ale nieumytemi rękoma chleb jedzą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Tedy on odpowiadając, rzekł im: Dobrze Izajasz o was obłudnikach prorokował, jako napisano: Lud ten czci mię wargami, ale serce ich daleko jest ode mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Lecz próżno mię czczą nauczając nauk i ustaw ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Albowiem wy opuściwszy przykazania Boże, trzymacie ustawy ludzkie, umywanie konewek i kubków, i wiele innych takich tym podobnych rzeczy czynicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Mówił im też: Wy czysto znosicie przykazania Boże, abyście ustawy wasze zachowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Bo Mojżesz rzekł: Czcij ojca twego i matkę twoję; a kto złorzeczy ojcu albo matce, niech śmiercią umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Ale wy mówicie: Jeźliby człowiek rzekł ojcu albo matce: Korban, (co jest dar), którykolwiek będzie ode mnie, tobie pożyteczny będzie, bez winy będzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'I nie dopuścicie mu nic więcej czynić ojcu swemu albo matce swojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Wniwecz obracając słowo Boże ustawą waszą, którąście ustawili; i wiele innych rzeczy tym podobnych czynicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'A zwoławszy wszystkiego ludu, mówił im: Słuchajcie mię wszyscy, a zrozumiejcie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Nie masz nic z rzeczy zewnętrznych, które wchodzą w człowieka, co by go mogło pokalać; ale to, co pochodzi z niego, to jest, co pokala człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Jeźli kto ma uszy ku słuchaniu, niechaj słucha!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'A gdy wszedł w dom od onego ludu, pytali go uczniowie jego o to podobieństwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Tedy im rzekł: Także i wy bezrozumni jesteście? Azaż nie rozumiecie, iż wszystko, co zewnątrz wchodzi w człowieka, nie może go pokalać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Albowiem nie wchodzi w serce jego, ale w brzuch, i do wychodu wychodzi, czyszcząc wszystkie pokarmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'I powiedział, że co pochodzi z człowieka, to pokala człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Bo z wnętrzności serca ludzkiego pochodzą złe myśli, cudzołóstwa, wszeteczeństwa, mężobójstwa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Kradzieże, łakomstwa, złości, zdrada, niewstyd, oko złe, bluźnierstwo, pycha, głupstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Wszystkie te złe rzeczy pochodzą z wnętrzności, i pokalają człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'A stamtąd wstawszy, poszedł na granice Tyru i Sydonu, a wszedłszy w dom, nie chciał, aby kto wiedział; lecz się utaić nie mógł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Albowiem usłyszawszy o nim niewiasta, której córeczka miała ducha nieczystego, przyszła i przypadła do nóg jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, '(A ta niewiasta była Grecka, rodem z Syrofenicyi) i prosiła go, aby dyjabła wygnał z córki jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Ale jej Jezus rzekł: Niech się pierwej dzieci nasycą; boć nie jest dobra, brać chleb dzieciom i miotać szczeniętom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'A ona odpowiedziała i rzekła mu: Tak jest, Panie! Wszakże i szczenięta jadają pod stołem z odrobin dziecinnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'I rzekł do niej: Dla tej mowy idź, wyszedł dyjabeł z córki twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'A gdy ona odeszła do domu swego, znalazła iż dyjabeł wyszedł, a córka leżała na łożu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'A wyszedłszy zaś z granic Tyrskich i Sydońskich, przyszedł nad morze Galilejskie, pośrodkiem granic dziesięciu miast.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'I przywiedli mu głuchego i z ciężkością mówiącego, a prosili go, aby na niego rękę włożył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'A wziąwszy go Pan od ludu osobno, włożył palce swoje w uszy jego, a plunąwszy dotknął się języka jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'A wejrzawszy w niebo, westchnął i rzekł do niego: Efata! to jest, otwórz się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'I wnet się otworzyły uszy jego, i rozwiązała się związka języka jego, i wymawiał dobrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Tedy im zakazał, aby tego nikomu nie powiadali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Ale czem on im bardziej zakazywał, tem oni to bardziej rozgłaszali, i nader się bardzo zdumiewali, mówiąc: Dobrze wszystko uczynił; bo czyni, iż głusi słyszą i niemi mówią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'A w oneż dni, gdy nader wielki lud był, a nie mieli, co by jedli, zwoławszy Jezus uczniów swoich, rzekł im:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Żal mi tego ludu; bo już trzy dni trwają przy mnie, a nie mają, co by jedli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'A jeźli je rozpuszczę głodne do domów ich, pomdleją na drodze; albowiem niektórzy z nich z daleka przyszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Tedy mu odpowiedzieli uczniowie jego: Skądże te kto będzie mógł nasycić chlebem tu na puszczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'I spytał ich: Wieleż macie chlebów? A oni rzekli: Siedm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'I rozkazał ludowi, żeby usiadł na ziemi; a wziąwszy one siedm chlebów, podziękowawszy łamał, i dawał uczniom swoim, aby przed lud kładli; i kładli przed lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Mieli też trochę rybek, które pobłogosławiwszy, kazał i one przed lud kłaść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Jedli tedy i nasyceni są, i zebrali, co zbyło ułomków, siedm koszów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'A było tych, co jedli, około czterech tysięcy; i rozpuścił je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'A wnet wstąpiwszy w łódź z uczniami swoimi, przyszedł w strony Dalmanutskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'I wyszli Faryzeuszowie, a poczęli z nim spór wieść, szukając od niego znamienia z nieba, a kusząc go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Tedy westchnąwszy serdecznie w duchu swym, rzekł: Przeczże ten rodzaj znamienia szuka? Zaprawdę powiadam wam, że nie będzie dane znamię temu rodzajowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'I opuściwszy ich, wstąpił zasię w łódź, i przeprawił się na drugą stronę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'A zapomnieli byli uczniowie wziąć z sobą chleba, i nie mieli z sobą nic więcej, tylko jeden chleb w łodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Tedy im przykazał, mówiąc: Baczcież, a strzeżcie się kwasu Faryzeuszów i kwasu Herodowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'I rozmawiali między sobą i rzekli: O tem snać mówi, że nie mamy chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Co poznawszy Jezus, rzekł im: O czemże rozmawiacie, iż nie macie chleba? Jeszczeż nie baczycie i nie zrozumiewacie? Jeszczeż macie serce swoje zdrętwiałe?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Oczy mając nie widzicie, i uszy mając nie słyszycie, i nie pamiętacie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Gdym onych pięć chlebów łamał między pięć tysięcy ludzi, wiele żeście pełnych koszów ułomków zebrali? Rzekli mu: Dwanaście;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'A gdym onych siedm chlebów łamał między cztery tysiące ludzi, wieleście koszów pełnych ułomków zebrali? A oni rzekli: Siedm.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'A on im rzekł: Jakoż tedy nie rozumiecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Potem przyszedł do Betsaidy; i przywiedli do niego ślepego, prosząc go, aby się go dotknął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'A ująwszy onego ślepego za rękę, wywiódł go precz za miasteczko, i plunąwszy na oczy jego, włożył na niego ręce, i pytał go, jeźliby co widział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'A on spojrzawszy w górę, rzekł: Widzę ludzi; bo widzę, że chodzą jako drzewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Potem zasię włożył ręce na oczy jego, i rozkazał mu w górę spojrzeć; i uzdrowiony jest na wzroku, tak że i z daleka wszystkich jasno widział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'I odesłał go do domu jego, mówiąc: I do tego miasteczka nie wchodź, i nikomu z miasteczka nie powiadaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Tedy wyszedł Jezus i uczniowie jego do miasteczek należących do Cezaryi Filipowej, a w drodze pytał uczniów swoich, mówiąc im: Kimże mię powiadają być ludzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'A oni mu odpowiedzieli: Jedni Janem Chrzcicielem, a drudzy Elijaszem, a drudzy jednym z proroków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Ale on im rzekł: A wy kim mię być powiadacie? A odpowiadając Piotr, rzekł mu: Tyś jest on Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'I przygroził im, aby o nim nikomu nie powiadali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'I począł je nauczać, że Syn człowieczy musi wiele ucierpieć, i odrzuconym być od starszych ludu, i od przedniejszych kapłanów i nauczonych w Piśmie, i być zabity, a po trzech dniach zmartwychwstać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'A to mówił jawnie. Tedy go Piotr wziąwszy na stronę, począł go strofować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Ale on obróciwszy się, a wejrzawszy na ucznie swoje, zgromił Piotra, mówiąc: Idź ode mnie, szatanie; albowiem nie pojmujesz tego, co jest Bożego, ale co jest ludzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'A zwoławszy ludu z uczniami swoimi, rzekł im: Ktokolwiek chce za mną iść, niech samego siebie zaprze, a weźmie krzyż swój, i naśladuje mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Albowiem kto by chciał zachować duszę swą, straci ją; a kto by stracił duszę swą dla mnie i dla Ewangielii, ten ją zachowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Bo cóż pomoże człowiekowi, choćby wszystek świat pozyskał, a szkodowałby na duszy swojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Albo co za zamianę da człowiek za duszę swoję?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Albowiem kto by się wstydził za mię i za słowa moje między tym rodzajem cudzołożnym i grzesznym, i Syn człowieczy wstydzić się za niego będzie, gdy przyjdzie w chwale Ojca swego z Anioły świętymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'I mówił im: Zaprawdę powiadam wam, iż są niektórzy z tych, co tu stoją, którzy nie ukuszą śmierci, ażby ujrzeli, że królestwo Boże przyszło w mocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'A po sześciu dniach wziął z sobą Jezus Piotra, Jakóba i Jana, i wiódł je na górę wysoką same osobno, i przemienił się przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'A szaty jego stały się lśniące, i bardzo białe jako śnieg, jak ich blecharz na ziemi nie może wybielić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'I ujrzeli Elijasza z Mojżeszem, którzy rozmawiali z Jezusem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'A odpowiadając Piotr, rzekł Jezusowi: Mistrzu! dobrze nam tu być; przetoż uczynimy tu trzy namioty, tobie jeden, Mojżeszowi jeden, i Elijaszowi jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Albowiem nie wiedział, co by mówił; bo przestraszeni byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'I stał się obłok, który je zacienił, a przyszedł głos z obłoku mówiący: Ten jest Syn mój miły, tegoż słuchajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'A wnet obejrzawszy się, nikogo więcej nie widzieli, tylko Jezusa samego z sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'A gdy oni zstępowali z góry, przykazał im, aby tego nikomu nie powiadali, co widzieli, aż kiedy by Syn człowieczy zmartwychwstał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'A tak oni zatrzymali tę rzecz u siebie, pytając się między sobą, co by to było zmartwychwstać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'I pytali go, mówiąc: Cóż tedy nauczeni w Piśmie powiadają, że Elijasz pierwej przyjść ma?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'A on odpowiadając, rzekł im: Elijaszci przyszedłszy pierwej, naprawi wszystko, a jako napisano o Synu człowieczym, że musi wiele ucierpieć, a za nic poczytanym być.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Aleć wam powiadam, że i Elijasz przyszedł, i uczynili mu cokolwiek chcieli, jako o nim napisano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'A przyszedłszy do uczniów, ujrzał lud wielki około nich, i nauczone w Piśmie spór mające z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'A wnetże lud wszystek ujrzawszy go, polękali się, i zbieżawszy się, przywitali go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'I pytał nauczonych w Piśmie: O cóż spór macie między sobą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'A odpowiadając jeden z onego ludu, rzekł: Nauczycielu! przywiodłem do ciebie syna mego, który ma ducha niemego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Ten gdziekolwiek go popadnie, rozdziera go, a on się ślini, i zgrzyta zębami swemi i schnie; i mówiłem uczniom twoim, aby go wygnali; ale nie mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Lecz on odpowiadając mu, rzekł: O rodzaju niewierny! dokądże z wami będę? i dokądże was cierpieć będę? przywiedźcie go do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'I przywiedli go do niego; a skoro go ujrzał, zaraz go duch rozdarł, a on upadłszy na ziemię, przewracał się, śliniąc się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Zatem spytał Jezus ojca jego: Jakoż mu się to dawno przydało? A on powiedział: Z dzieciństwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'I często go miotał w ogień i w wodę, żeby go stracił, ale możeszli co, ratuj nas, użaliwszy się nad nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Ale mu Jezus rzekł: Jeźli możesz temu wierzyć? Wszystko jest możno wierzącemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'A zarazem zawoławszy ojciec onego młodzieńca, ze łzami rzekł: Wierzę, Panie! ty ratuj niedowiarstwa mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'A widząc Jezus, iż się lud zbiegał, zgromił onego ducha nieczystego, mówiąc mu: Duchu niemy i głuchy! ja tobie rozkazuję, wynijdź z niego, a nie wchodź więcej w niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Zawoławszy tedy bardzo, rozdarłszy go, wyszedł; i stał się on człowiek jako umarły, tak że ich wiele mówiło, iż umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Ale Jezus ująwszy go za rękę, podniósł go; i wstał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'A gdy wszedł w dom, pytali go osobno uczniowie jego: Czemużeśmy go wygnać nie mogli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'A on im rzekł: Ten rodzaj dyjabłów inaczej wynijść nie może, tylko przez modlitwę i przez post.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'A stamtąd wyszedłszy, szli z sobą przez Galileję; ale nie chciał, aby kto o tem wiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Albowiem uczył ucznie swoje, i mówił im: Syn człowieczy będzie wydany w ręce ludzkie, i zabiją go; ale gdy będzie zabity, dnia trzeciego zmartwychwstanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Lecz oni tej rzeczy nie rozumieli; wszakże bali się go spytać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Zatem przyszedł do Kapernaum, a będąc w domu, pytał ich: O czemżeście w drodze między sobą rozmawiali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Lecz oni milczeli; albowiem rozmawiali między sobą w drodze, kto by z nich był większy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'A usiadłszy, zawołał dwunastu i mówił im: Jeźli kto chce być pierwszym, niech będzie ze wszystkich ostatnim, i sługą wszystkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'A wziąwszy dzieciątko, postawił je w pośrodku nich, a wziąwszy je na ręce, rzekł im:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Kto by jedno z takich dziateczek przyjął w imieniu mojem, mnie przyjmuje; a kto by mnie przyjął, nie mnie przyjmuje, ale onego, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Tedy mu odpowiedział Jan, mówiąc: Nauczycielu! widzieliśmy niektórego w imieniu twojem dyjabły wyganiającego, który nie chodzi za nami, i zabranialiśmy mu, przeto że nie chodzi za nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Ale Jezus rzekł: Nie zabraniajcie mu; albowiem nikt nie jest, co by czynił cuda w imieniu mojem, aby mógł snadnie mówić źle o mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Bo kto nie jest przeciwko nam, za nami jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Albowiem kto by was napoił kubkiem wody w imieniu mojem, dlatego iż jesteście Chrystusowi, zaprawdę powiadam wam, nie straci zapłaty swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'A kto by zgorszył jednego z tych małych, którzy w mię wierzą, daleko by mu lepiej było, aby był zawieszony kamień młyński u szyi jego, i w morze był wrzucony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'A jeźliby cię gorszyła ręka twoja, odetnij ją; bo lepiej jest tobie ułomnym wnijść do żywota, niżeli dwie ręce mając, iść do piekła w on ogień nieugaszony,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'Gdzie robak ich nie umiera, a ogień nie gaśnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'A jeźliby cię noga twoja gorszyła, odetnij ją; bo lepiej tobie chromym wnijść do żywota, niżeli dwie nogi mając, być wrzuconym do piekła, w ogień nieugaszony,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'Gdzie robak ich nie umiera, a ogień nie gaśnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'A jeźliby cię oko twoje gorszyło, wyłup je; bo lepiej tobie jednookim wnijść do królestwa Bożego, niżeli dwoje oczu mając, wrzuconym być do ognia piekielnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'Gdzie robak ich nie umiera, a ogień nie gaśnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Albowiem każdy człowiek ogniem osolony będzie, i każda ofiara solą osolona będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Dobrać jest sól; ale jeźli się sól niesłoną stanie, czemże ją osolicie? Miejcież sól sami w sobie, a miejcie pokój między sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'A wstawszy stamtąd, przyszedł do granic Judzkich przez krainę za Jordanem leżącą; i zszedł się zaś do niego lud, i uczył je zaś jako miał zwyczaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Tedy przystąpiwszy Faryzeuszowie, pytali go: Godzili się mężowi żonę opuścić? a to czynili, kusząc go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Ale on odpowiadając, rzekł im: Cóż wam przykazał Mojżesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'A oni rzekli: Mojżesz pozwolił napisać list rozwodny i opuścić ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'A odpowiadając Jezus, rzekł im: Dla zatwardzenia serca waszego napisał wam to przykazanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Aleć od początku stworzenia mężczyznę i niewiastę uczynił je Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Dlatego opuści człowiek ojca swego i matkę, a przyłączy się do żony swojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'I będą dwoje jednem ciałem; a tak już nie są dwoje, ale jedno ciało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Co tedy Bóg złączył, człowiek niechaj nie rozłącza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'A w domu zaś uczniowie jego o toż go pytali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'I rzekł im: Ktobykolwiek opuścił żonę swą, a pojąłby inną, cudzołoży przeciwko niej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'A jeźliby niewiasta opuściła męża swego, a szłaby za drugiego, cudzołoży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Tedy przynoszono do niego dziatki, aby się ich dotykał; ale uczniowie gromili tych, którzy je przynosili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Co ujrzawszy Jezus, rozgniewał się i rzekł im: Dopuśćcie dziatkom przychodzić do mnie, a nie zabraniajcie im; albowiem takich jest królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Zaprawdę powiadam wam: Ktobykolwiek nie przyjął królestwa Bożego jako dzieciątko, nie wnijdzie do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'I biorąc je na ręce swoje, i kładąc na nie ręce, błogosławił im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'A gdy on wychodził w drogę, przybieżał jeden, i upadłszy przed nim na kolana, pytał go: Nauczycielu dobry! cóż czynić mam, abym odziedziczył żywot wieczny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Ale mu Jezus rzekł: Przecz mię zowiesz dobrym? Nikt nie jest dobry, tylko jeden, to jest Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Przykazania umiesz: nie będziesz cudzołożył, nie będziesz zabijał, nie będziesz kradł, nie będziesz mówił świadectwa fałszywego, nie będziesz oszukiwał nikogo, czcij ojca twego i matkę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'A on odpowiadając, rzekł mu: Nauczycielu! tegom wszystkiego przestrzegał od młodości mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'A Jezus spojrzawszy nań, rozmiłował się go, i rzekł mu: Jednego ci nie dostaje; idź, sprzedaj co masz, a rozdaj ubogim, a będziesz miał skarb w niebie, a przyjdź, naśladuj mię, wziąwszy krzyż.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'A on zafrasowawszy się dla tego słowa, odszedł smutny; albowiem miał wiele majętności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'A spojrzawszy Jezus w około, rzekł do uczniów swoich: Jakoż trudno ci, którzy mają bogactwa, wnijdą do królestwa Bożego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Tedy uczniowie zdumieli się nad temi słowami jego. Lecz Jezus zaś odpowiadając, rzekł im: Dziatki! jakoż jest trudno tym, co ufają w bogactwach, wnijść do królestwa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Snadniej jest wielbłądowi przejść przez ucho igielne, niż bogaczowi wnijść do królestwa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'A oni się tem więcej zdumiewali, mówiąc między sobą: I któż może być zbawiony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'A Jezus spojrzawszy na nie, rzekł: U ludzić to niemożno, ale nie u Boga; albowiem u Boga wszystko jest możno.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'I począł Piotr mówić do niego: Otośmy my opuścili wszystko, a poszliśmy za tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'A Jezus odpowiadając, rzekł: Zaprawdę powiadam wam: Nikt nie jest, kto by opuścił dom, albo braci, albo siostry, albo ojca, albo matkę, albo żonę, albo dzieci, albo role dla mnie i dla Ewangielii,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'Żeby nie miał wziąć stokrotnie teraz w tym czasie domów, i braci, i sióstr, i matek, i dzieci, i ról z prześladowaniem, a w przyszłym wieku żywota wiecznego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Aleć wiele pierwszych będą ostatnimi, a ostatnich pierwszymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'I byli w drodze, wstępując do Jeruzalemu; a Jezus szedł przed nimi, i zdumiewali się, a idąc za nim, bali się. A on wziąwszy zasię z sobą onych dwanaście, począł im powiadać, co nań przyjść miało,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Mówiąc: Oto wstępujemy do Jeruzalemu, a Syn człowieczy będzie wydany przedniejszym kapłanom i nauczonym w Piśmie, i osądzą go na śmierć, i wydadzą go poganom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'A oni się z niego naśmiewać będą, i ubiczują go, i będą nań plwać, i zabiją go; ale dnia trzeciego zmartwychwstanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Tedy przystąpili do niego Jakób i Jan, synowie Zebedeuszowi, mówiąc: Nauczycielu! chcemy, abyś nam uczynił, o co cię prosić będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'A on im rzekł: Cóż chcecie, abym wam uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'A oni mu rzekli: Daj nam, abyśmy jeden na prawicy twojej a drugi na lewicy twojej siedzieli w chwale twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Lecz im Jezus rzekł: Nie wiecie, o co prosicie. Możecież pić kielich, który ja piję, i chrztem, którym się ja chrzczę, być ochrzczeni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'A oni mu rzekli: Możemy. A Jezus im rzekł: Kielichci, który ja piję, pić będziecie i chrztem, którym ja się chrzczę, ochrzczeni będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Ale siedzieć po prawicy mojej albo po lewicy mojej, nie moja rzecz jest dać; ale będzie dano tym, którym zgotowano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'A usłyszawszy to oni dziesięciu, poczęli się gniewać na Jakóba i na Jana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Ale Jezus zwoławszy ich, rzekł im: Wiecie, iż ci, którym się zda, że władzę mają nad narody, panują nad nimi, a którzy z nich wielcy są, moc przewodzą nad nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Lecz nie tak będzie między wami; ale ktobykolwiek chciał być wielkim między wami, będzie sługą waszym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'A ktobykolwiek z was chciał być pierwszym, będzie sługą wszystkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Bo i Syn człowieczy nie przyszedł, aby mu służono, ale aby służył, i aby dał duszę swą na okup za wielu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Tedy przyszli do Jerycha; a gdy on wychodził z Jerycha, i uczniowie jego i lud wielki, syn Tymeusza, Bartymeusz ślepy, siedział podle drogi żebrząc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'A usłyszawszy, iż jest Jezus on Nazareński, począł wołać, mówiąc: Jezusie, Synu Dawida! zmiłuj się nade mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'I gromiło go wiele ich, aby milczał, ale on tem więcej wołał: Synu Dawida! zmiłuj się nade mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Tedy zastanowiwszy się Jezus, kazał go zawołać. I zawołano ślepego, mówiąc mu: Ufaj, wstań, woła cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'A on porzuciwszy płaszcz swój, wstał, i przyszedł do Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'I odpowiadając Jezus, rzekł mu: Cóż chcesz, abym ci uczynił? A ślepy mu rzekł: Mistrzu! abym przejrzał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'A Jezus mu rzekł: Idź, wiara twoja ciebie uzdrowiła. A zarazem przejrzał, i szedł drogą za Jezusem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'A gdy się przybliżyli do Jeruzalemu i do Betfagie i do Betanii ku górze oliwnej, posłał dwóch z uczniów swoich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'I rzekł im: Idźcie do miasteczka, które jest przeciwko wam, a wszedłszy do niego, zaraz znajdziecie oślę uwiązane, na którem nikt z ludzi nie siedział; odwiążcież je, a przywiedźcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'A jeźliby wam kto rzekł: Cóż to czynicie? Powiedzcie, iż go Pan potrzebuje; a wnet je tu pośle.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Szli tedy i znaleźli oślę uwiązane u drzwi na dworze na rozstaniu dróg, i odwiązali je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Tedy niektórzy z onych, co tam stali, mówili: Cóż czynicie, że odwiązujecie oślę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'A oni im rzekli, jako im był rozkazał Jezus. I puścili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Przywiedli tedy oślę do Jezusa, i włożyli na nie szaty swoje; i wsiadł na nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'A wiele ich słali szaty swoje na drodze; drudzy zasię obcinali gałązki z drzew, i słali na drodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'A którzy wprzód szli, i którzy pozad szli, wołali, mówiąc: Hosanna, błogosławiony, który idzie w imieniu Pańskiem!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Błogosławione królestwo ojca naszego Dawida, które przyszło w imieniu Pańskiem! Hosanna na wysokościach!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'I wjechał Jezus do Jeruzalemu i przyszedł do kościoła, a obejrzawszy wszystko, gdy już była wieczorna godzina, wyszedł do Betanii z dwunastoma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'A drugiego dnia, gdy wychodzili z Betanii, łaknął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'I ujrzawszy z daleka figowe drzewo, mające liście, przyszedł, jeźliby snać co na niem znalazł; a gdy do niego przyszedł, nic nie znalazł, tylko liście; bo nie był czas figom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'A odpowiadając Jezus, rzekł mu: Niechajże więcej na wieki nikt z ciebie owocu nie je. A słyszeli to uczniowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'I przyszli do Jeruzalemu; a wszedłszy Jezus do kościoła, począł wyganiać sprzedawające i kupujące w kościele, i poprzewracał stoły tych, co pieniędzmi handlowali, i stołki tych, co sprzedawali gołębie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'A nie dopuścił, żeby kto miał nieść naczynie przez kościół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'I nauczał, mówiąc im: Azaż nie napisano: Że dom mój, dom modlitwy będzie nazwany od wszystkich narodów? a wyście go uczynili jaskinią zbójców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'A słyszeli to nauczeni w Piśmie i przedniejsi kapłani i szukali, jakoby go stracili; albowiem się go bali, przeto iż wszystek lud zdumiewał się nad nauką jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'A gdy przyszedł wieczór, wyszedł z miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'A rano idąc mimo figowe drzewo, ujrzeli, iż z korzenia uschło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Tedy wspomniawszy Piotr, rzekł mu: Mistrzu! oto figowe drzewo, któreś przeklął, uschło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'A Jezus odpowiadając, rzekł im: Miejcie wiarę w Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Bo zaprawdę powiadam wam, iż ktobykolwiek rzekł tej górze: Podnieś się, a rzuć się w morze, a nie wątpiłby w sercu swojem, leczby wierzył, że się stanie, co mówi, stanie się mu, cokolwiek rzecze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Przetoż powiadam wam: O cokolwiekbyście, modląc się, prosili, wierzcie, że weźmiecie, a stanie się wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'A gdy stoicie modląc się, odpuśćcież, jeźli co przeciw komu macie, aby i Ojciec wasz, który jest w niebiesiech, odpuścił wam upadki wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Bo jeźli wy nie odpuścicie, i Ojciec wasz, który jest w niebiesiech, nie odpuści wam upadków waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'I przyszli znowu do Jeruzalemu. A gdy się on przechodził po kościele, przystąpili do niego przedniejsi kapłani i nauczeni w Piśmie i starsi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'I mówili do niego: Którąż to mocą czynisz? a kto ci dał tę moc, abyś to czynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Tedy Jezus odpowiadając, rzekł im: Spytam was i ja o jednę rzecz; odpowiedzcież mi, a powiem, którą mocą to czynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Chrzest Jana z niebaż był, czyli z ludzi? Odpowiedzcie mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'I rozbierali to sami między sobą, mówiąc: Jeźli powiemy, z nieba, rzecze: Przeczżeście mu tedy nie wierzyli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'A jeźli powiemy, z ludzi, bojemy się ludu; albowiem wszyscy Jana mieli za prawdziwego proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Tedy odpowiadając rzekli Jezusowi: Nie wiemy. Jezus też odpowiadając rzekł im: I ja wam nie powiem, którą mocą to czynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Tedy począł do nich mówić w podobieństwach: Człowiek jeden nasadził winnicę, i ogrodził ją płotem, i wykopał prasę, i zbudował wieżę, i najął ją winiarzom, i odjechał precz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'I posłał, gdy tego był czas, sługę do winiarzy, aby od winiarzy odebrał pożytki onej winnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Lecz oni pojmawszy go, ubili, i odesłali próżnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'I zasię posłał do nich sługę drugiego, którego też oni ukamionowawszy, głowę mu zranili, i odesłali obelżonego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'I zasię posłał inszego sługę; ale i tego zabili, i wiele innych, z których jedne ubili, a drugie pozabijali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'A mając jeszcze jednegoż swego miłego syna, posłał na ostatek do nich i tego, mówiąc: Wżdyć się będą wstydzili syna mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Ale oni winiarze rzekli między sobą: Tenci jest dziedzic; pójdźcie, zabijmy go, a będzie nasze dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'I wziąwszy go zabili, a wyrzucili precz z winnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Cóż tedy uczyni pan onej winnicy? Przyjdzie, a potraci one winiarze, i da winnicę innym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Izaliście nie czytali tego pisma: Kamień, który odrzucili budujący, ten się stał głową węgielną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Od Panać się to stało, i jest dziwne w oczach naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Starali się tedy, jakoby go pojmać, ale się ludu bali; bo poznali, iż przeciwko nim ono podobieństwo powiedział. I zaniechawszy go, odeszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Potem posłali do niego niektóre z Faryzeuszów i z Herodyjanów, aby go usidlili w mowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'A tak oni przyszedłszy rzekli mu: Nauczycielu! wiemy, żeś jest prawdziwy, a nie dbasz na nikogo; albowiem nie patrzysz na osobę ludzką, ale w prawdzie drogi Bożej uczysz; godziż się dać czynsz cesarzowi, czyli nie? Mamyż go dać, czyli nie dać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'A on poznawszy obłudę ich, rzekł im: Czemuż mię kusicie? Przynieście mi grosz, abym go oglądał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Tedy mu oni przynieśli; a on im rzekł: Czyjże to jest obraz i napis? A oni mu powiedzieli: Cesarski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'I odpowiadając Jezus, rzekł im: Oddawajcież tedy, co jest cesarskiego, cesarzowi, a co jest Bożego, Bogu. I dziwowali mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'I przyszli do niego Saduceuszowie, którzy mówią, iż nie masz zmartwychwstania, i pytali go mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Nauczycielu! Mojżesz nam napisał, iż jeźliby czyj brat umarł, i zostawił żonę, a dziatek by nie zostawił, aby brat jego pojął żonę jego, a wzbudził nasienie bratu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Było tedy siedm braci; a pierwszy pojąwszy żonę umarł, i nie zostawił nasienia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'A drugi pojąwszy ją, umarł, lecz i ten nie zostawił nasienia; także i trzeci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'A tak ją pojęło onych siedm braci, a nie zostawili nasienia. Na ostatek po wszystkich umarła i ona niewiasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Przetoż przy zmartwychwstaniu gdy powstaną, któregoż z nich będzie żoną? bo siedm ich mieli ją za żonę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Na to Jezus odpowiadając rzekł im: Zaż nie dlatego błądzicie, iżeście nie powiadomi Pisma ani mocy Bożej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Albowiem gdy zmartwychwstaną, ani się żenią, ani za mąż wydawają; ale są jako Aniołowie w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'A o umarłych, iż będą wzbudzeni, nie czytaliścież w księgach Mojżeszowych, jako Bóg do niego ze krza mówił, i rzekł: Jam jest Bóg Abrahama, Bóg Izaaka, i Bóg Jakóba?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Bóg nie jestci Bogiem umarłych, ale Bogiem żywych: przetoż wy bardzo błądzicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'A przystąpiwszy jeden z nauczonych w Piśmie, słysząc, że z sobą gadali, a widząc, że im dobrze odpowiedział, spytał go: Które jest najpierwsze ze wszystkich przykazanie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'A Jezus mu odpowiedział: Najpierwsze ze wszystkich przykazanie jest: Słuchaj, Izraelu! Pan, Bóg nasz, Pan jeden jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Przetoż będziesz miłował Pana, Boga twego, ze wszystkiego serca twego, i ze wszystkiej duszy twojej, i ze wszystkiej myśli twojej, i ze wszystkiej siły twojej; toć jest pierwsze przykazanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'A wtóre temu podobne to jest: Będziesz miłował bliźniego twego, jako samego siebie. Większego przykazania innego nad to nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Tedy mu rzekł on nauczony w Piśmie: Nauczycielu! zaprawdę dobrześ powiedział, iż jeden jest Bóg, a nie masz inszego oprócz niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'I miłować go ze wszystkiego serca i ze wszystkiej myśli i ze wszystkiej duszy i ze wszystkiej siły, a miłować bliźniego jako samego siebie, więcej jest nad wszystkie całopalenia i ofiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'A widząc Jezus, że on mądrze odpowiedział, rzekł mu: Niedalekoś jest od królestwa Bożego. I nie śmiał go nikt dalej pytać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Tedy Jezus odpowiadając rzekł, gdy uczył w kościele: Jakoż mówią nauczeni w Piśmie, iż Chrystus jest Syn Dawida?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Bo sam Dawid przez Ducha Świętego powiedział: Rzekł Pan Panu memu, siądź po prawicy mojej, aż położę nieprzyjacioły twoje podnóżkiem nóg twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Ponieważ go sam Dawid nazywa Panem, jakoż tedy jest synem jego? a wielki lud rad go słuchał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'I mówił do nich w nauce swojej: Strzeżcie się nauczonych w Piśmie, którzy chcą w długich szatach chodzić, a być pozdrawiani na rynkach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'I na pierwszych stołkach siadać w bóżnicach, i pierwsze miejsca mieć na wieczerzach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Którzy pożerają domy wdów, a to pod pokrywką długich modlitw; cić odniosą cięższy sąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'A Jezus siedząc przeciwko skarbnicy, przypatrywał się, jako lud rzucał pieniądze do skarbnicy, i jako wiele bogaczów wiele rzucało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'I przyszedłszy jedna wdowa uboga, wrzuciła dwa drobne pieniążki, co czyni kwartnik.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Tedy zwoławszy uczniów swoich rzekł im: Zaprawdę wam powiadam, że ta uboga wdowa więcej wrzuciła, niżeli ci wszyscy, którzy rzucali do skarbnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Albowiem ci wszyscy z tego, co im zbywało, rzucali; ale ta z ubóstwa swego wszystko, co miała, wrzuciła, wszystkę żywność swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'A gdy on wychodził z kościoła, rzekł mu jeden z uczniów jego: Nauczycielu! patrz, jakie to kamienie, i jakie budowania?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'A Jezus odpowiadając rzekł mu: Widzisz te wielkie budowania? Nie będzie zostawiony kamień na kamieniu, który by nie był rozwalony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'A gdy siedział na górze oliwnej przeciwko kościołowi, pytali go osobno Piotr, i Jakób, i Jan, i Andrzej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Powiedz nam, kiedy się to stanie, i co za znak, kiedy się to wszystko pełnić będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'A Jezus odpowiadając im, począł mówić: Patrzcie, aby was kto nie zwiódł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Albowiem wiele ich przyjdzie pod imieniem mojem, mówiąc: Jam jest Chrystus, a wiele ich zwiodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Gdy tedy usłyszycie wojny, i wieści o wojnach, nie trwożcież sobą; boć to musi być; ale jeszcze nie tu koniec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Albowiem powstanie naród przeciwko narodowi, i królestwo przeciwko królestwu, i będą miejscami trzęsienia ziemi, i będą głody i zamieszania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'A toć początki boleści. Lecz wy strzeżcie samych siebie; boć was podawać będą przed rady i do zgromadzenia, będą was bić, a przed starostami i królmi dla mnie stawać będziecie na świadectwo przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Ale u wszystkich narodów musi być przedtem kazana Ewangielija.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'A gdy was powiodą wydawając, nie troszczcież się przed czasem, co byście mówić mieli, ani o tem myślcie, ale co wam będzie dano onejże godziny, to mówcie; albowiem nie wy jesteście, którzy mówicie, ale Duch Święty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'I wyda brat brata na śmierć, a ojciec syna; i powstaną dzieci przeciwko rodzicom, i będą je zabijać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'A będziecie w nienawiści u wszystkich dla imienia mego; ale kto wytrwa aż do końca, ten będzie zbawion.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Gdy tedy ujrzycie onę obrzydliwość spustoszenia, opowiedzianą od Danijela proroka, stojącą, gdzie stać nie miała, (kto czyta, niechaj uważa,) tedy ci, którzy będą w Judzkiej ziemi, niech uciekają na góry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'A kto będzie na dachu, niech nie zstępuje do domu, ani wchodzi, aby co wziął z domu swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'A kto będzie na roli, niech się nie wraca nazad, aby wziął szatę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Lecz biada brzemiennym i piersiami karmiącym w one dni!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Przetoż módlcie się, aby uciekanie wasze nie było w zimie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Albowiem będą te dni takiem uciśnieniem, jakiego nie było od początku stworzenia, które stworzył Bóg, aż dotąd, ani będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'A jeźliby Pan nie skrócił dni onych, nie byłoby żadne ciało zbawione; lecz dla wybranych, które wybrał, skrócił dni onych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'A tedy jeźliby wam kto rzekł: Oto tu jest Chrystus, albo oto tam, nie wierzcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Boć powstaną fałszywi Chrystusowie, i fałszywi prorocy, i będą czynić znamiona i cuda ku zwiedzeniu, by można, i wybranych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Wy tedy strzeżcie się; otom wam wszystko przepowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Ale w one dni po uciśnieniu onem, zaćmi się słońce, i księżyc nie wyda światłości swojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'I gwiazdy niebieskie będą padały, a mocy, które są na niebie, poruszą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'A tedy ujrzą Syna człowieczego, przychodzącego w obłokach z mocą i z chwałą wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'A tedy pośle Anioły swoje i zgromadzi wszystkie wybrane swoje od czterech wiatrów, od kończyn ziemi aż do kończyn nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'A od figowego drzewa nauczcie się tego podobieństwa: Gdy się już gałąź jego odmładza i puszcza liście, poznajecie, iż blisko jest lato.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Także i wy, gdy ujrzycie, iż się to dziać będzie, poznawajcie, że blisko jest i we drzwiach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Zaprawdę powiadam wam, żeć nie przeminie ten rodzaj, ażby się to wszystko stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Niebo i ziemia przeminą; ale słowa moje nie przeminą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Lecz o onym dniu i godzinie nikt nie wie, ani Aniołowie, którzy są w niebie, ani Syn, tylko Ojciec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Patrzcież, czujcie, a módlcie się; bo nie wiecie, kiedy ten czas będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Jako człowiek, który precz odjeżdżając, zostawił dom swój, i rozdał urzędy sługom swoim, i każdemu robotę jego, i wrotnemu przykazał, aby czuł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Czujcież tedy; (bo nie wiecie, kiedy Pan domu onego przyjdzie, z wieczorali, czyli o północy, czyli gdy kury pieją, czyli rano.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'By snać niespodzianie przyszedłszy, nie znalazł was śpiącymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'A co wam mówię, wszystkimci mówię: Czujcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'A po dwóch dniach była wielkanoc, święto przaśników; i szukali przedniejsi kapłani i nauczeni w Piśmie, jakoby go zdradą pojmawszy, zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Lecz mówili: Nie w święto, aby snać nie był rozruch między ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'A gdy on był w Betanii, w domu Szymona trędowatego, gdy siedział u stołu, przyszła niewiasta, mając słoik alabastrowy maści szpikanardowej płynącej, bardzo kosztownej, a stłukłszy słoik alabastrowy, wylała ją na głowę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'I gniewali się niektórzy sami w sobie, a mówili: Na cóż się stała utrata tej maści?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Albowiem się to mogło sprzedać drożej niż za trzysta groszy, i rozdać ubogim; i szemrali przeciwko niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Ale Jezus rzekł: Zaniechajcie jej, przeczże się jej przykrzycie? Dobryć uczynek uczyniła przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Zawsze bowiem ubogie macie z sobą, i kiedykolwiek chcecie, możecie im dobrze czynić; ale mnie nie zawsze mieć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Ona, co mogła, to uczyniła; poprzedziła, aby ciało moje pomazała ku pogrzebowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Zaprawdę powiadam wam: Gdziekolwiek kazana będzie ta Ewangielija po wszystkim świecie, i to co ona uczyniła, powiadano będzie na pamiątkę jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Tedy Judasz Iszkaryjot, jeden ze dwunastu, odszedł do przedniejszych kapłanów, aby im go wydał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Co oni usłyszawszy, uradowali się, i obiecali mu dać pieniądze. I szukał sposobnego czasu, jakoby go wydał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Pierwszego tedy dnia przaśników, gdy baranka wielkanocnego zabijano, rzekli mu uczniowie jego: Gdzie chcesz, abyśmy szedłszy nagotowali, żebyś jadł baranka?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'I posłał dwóch z uczniów swych, i rzekł im: Idźcie do miasta, a spotka się z wami człowiek, dzban wody niosący; idźcież za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'A dokądkolwiek wnijdzie, rzeczcie gospodarzowi: Nauczyciel mówi: Gdzież jest gospoda, kędy bym jadł baranka z uczniami moimi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'A on wam ukaże salę wielką usłaną i gotową, tamże nam nagotujecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'I odeszli uczniowie jego, i przyszli do miasta, i znaleźli tak, jako im był powiedział, i nagotowali baranka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'A gdy był wieczór, przyszedł ze dwunastoma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'A gdy za stołem siedzieli i jedli, rzekł Jezus: Zaprawdę wam powiadam, iż jeden z was wyda mię, który je ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Tedy oni poczęli się smucić, i do niego mówić, każdy z osobna: Azażem ja jest? A drugi: Azaż ja?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Lecz on odpowiadając rzekł im: Jeden ze dwunastu, który ze mną macza w misie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Synci człowieczy idzie, jako o nim napisano: ale biada człowiekowi temu, przez którego Syn człowieczy będzie wydany! dobrze by mu było, by się był ten człowiek nie narodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'A gdy oni jedli, wziął Jezus chleb, a pobłogosławiwszy, łamał i dał im, mówiąc: Bierzcie, jedzcie, to jest ciało moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'A wziąwszy kielich, i podziękowawszy, dał im; i pili z niego wszyscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'I rzekł im: To jest krew moja nowego testamentu, która się za wielu wylewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Zaprawdę powiadam wam: Iż nie będę więcej pił z rodzaju winnej macicy, aż do dnia onego, gdy go pić będę nowy w królestwie Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'A zaśpiewawszy pieśń, wyszli na górę oliwną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Potem im rzekł Jezus: Wszyscy wy zgorszycie się ze mnie tej nocy; bo napisano: Uderzę pasterza, i będą rozproszone owce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Lecz gdy zmartwychwstanę, poprzedzę was do Galileii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Ale mu Piotr powiedział: Choćby się wszyscy zgorszyli, ale ja nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'I rzekł mu Jezus: Zaprawdę powiadam tobie, iż dziś tej nocy, pierwej niż dwakroć kur zapieje, trzykroć się mnie zaprzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Ale on tem więcej mówił: Bym z tobą miał i umrzeć, nie zaprę się ciebie. Toć też i wszyscy mówili:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'I przyszli na miejsce, które zwano Gietsemane; tedy rzekł do uczniów swoich: Siedźcie tu, aż się pomodlę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'I wziąwszy z sobą Piotra, i Jakóba, i Jana, począł się lękać, i bardzo tęsknić;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'I rzekł im: Bardzo jest smutna dusza moja aż do śmierci; zostańcie tu, a czujcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'A postąpiwszy trochę, padł na ziemię i modlił się, aby, jeźli można, odeszła od niego ta godzina;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'I rzekł: Abba Ojcze! wszystko tobie jest możno, przenieś ode mnie ten kielich; wszakże nie co ja chcę, ale co Ty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Tedy przyszedł, i znalazł je śpiące, i rzekł Piotrowi: Szymonie, śpisz? nie mogłeś czuć jednej godziny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Czujcie, a módlcie się, abyście nie weszli w pokuszenie; duchci jest ochotny, ale ciało mdłe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'I odszedłszy znowu, modlił się, też słowa mówiąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'A wróciwszy się znalazł je zasię śpiące, (bo oczy ich były obciążone,) a nie wiedzieli, co mu odpowiedzieć mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'I przyszedł po trzecie, a rzekł im: Śpijcież już i odpoczywajcie! Dosyćci! przyszłać ta godzina, oto wydany bywa Syn człowieczy w ręce grzeszników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Wstańcie, pójdźmy! oto który mię wydawa, blisko jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'A wnetże, gdy on jeszcze mówił, przyszedł Judasz, który był jeden ze dwunastu, a z nim wielka zgraja z mieczami i z kijami od przedniejszych kapłanów, i od nauczonych w Piśmie i od starszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'A ten, który go wydawał, dał im był znak, mówiąc: Któregokolwiek pocałuję, tenci jest, imajcież go, a wiedźcie ostrożnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'A przyszedłszy, zarazem przystąpił do niego, i rzekł: Mistrzu, Mistrzu! i pocałował go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Tedy się oni na niego rękoma rzucili, i pojmali go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'A jeden z tych, co tam stali, dobywszy miecza, uderzył sługę najwyższego kapłana, i uciął mu ucho.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'A Jezus odpowiadając rzekł im: Jako na zbójcę wyszliście z mieczami i z kijami, abyście mię pojmali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Na każdy dzień bywałem u was w kościele, ucząc, a nie pojmaliście mię: ale trzeba, aby się wypełniły Pisma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'A tak opuściwszy go, wszyscy uciekli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'A jeden jakiś młodzieniec szedł za nim, przyodziany prześcieradłem na nagie ciało; i uchwycili go młodzieńcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Ale on opuściwszy prześcieradło, nago uciekł od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Tedy przywiedli Jezusa do najwyższego kapłana: a zeszli się do niego wszyscy przedniejsi kapłani, i starsi, i nauczeni w Piśmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'A Piotr szedł z nim z daleka aż do dworu najwyższego kapłana, i siedział z sługami, grzejąc się u ognia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Ale przedniejsi kapłani, i wszystka rada szukali przeciwko Jezusowi świadectwa, aby go na śmierć wydali; wszakże nie znaleźli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Albowiem ich wiele fałszywie świadczyli przeciwko niemu; ale świadectwa ich nie były zgodne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Tedy niektórzy powstawszy, fałszywie świadczyli przeciwko niemu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Myśmy to słyszeli, że mówił: Ja rozwalę ten kościół ręką uczyniony, a we trzech dniach inny nie ręką uczyniony zbuduję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Lecz i tak nie było zgodne świadectwo ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Tedy stanąwszy w pośrodku najwyższy kapłan, pytał Jezusa, mówiąc: Nie odpowiadasz nic? Cóż to jest, co ci przeciwko tobie świadczą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Ale on milczał, a nic nie odpowiedział. Znowu go pytał najwyższy kapłan, i rzekł mu: Tyżeś jest on Chrystus, Syn onego Błogosławionego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'A Jezus rzekł: Jam jest; i ujrzycie Syna człowieczego, siedzącego na prawicy mocy Bożej, i przychodzącego z obłokami niebieskiemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Tedy najwyższy kapłan rozdarłszy szaty swoje, rzekł: Cóż jeszcze potrzebujemy świadków?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Słyszeliście bluźnierstwo. Cóż się wam zda? A oni wszyscy osądzili go winnym być śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'I poczęli niektórzy nań plwać, i zakrywać oblicze jego, i bić weń pięściami i mówić mu: Prorokuj! A słudzy policzkowali go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'A gdy Piotr był we dworze na dole, przyszła jedna z dziewek najwyższego kapłana;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'A ujrzawszy Piotra grzejącego się, wejrzała nań, i rzekła: I tyś był z Jezusem Nazareńskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Ale on się zaprzał, mówiąc: Nie znam go, a nie wiem, co ty mówisz. I wyszedł na dwór do przysionka, a kur zapiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Tedy dziewka ujrzawszy go zasię, poczęła mówić tym, którzy tam stali: Ten jest jeden z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'A on zasię zaprzał się. A znowu po małej chwilce ci, co tam stali, rzekli Piotrowi: Prawdziwie z nich jesteś; bo jesteś i Galilejczyk, i mowa twoja podobna jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'A on się począł przeklinać i przysięgać, mówiąc: Nie znam człowieka tego, o którym mówicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Tedy po wtóre kur zapiał. I wspomniał Piotr na słowa, które mu był powiedział Jezus: że pierwej niż kur dwakroć zapieje, trzykroć się mnie zaprzesz. A wyszedłszy, płakał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'A zaraz rano naradziwszy się przedniejsi kapłani z starszymi i z nauczonymi w Piśmie i ze wszystką radą, związali Jezusa, i wiedli go, i podali Piłatowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'I pytał go Piłat: Tyżeś jest król Żydowski? A on mu odpowiadając rzekł: Ty powiadasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'I skarżyli nań przedniejsi kapłani o wiele rzeczy: (ale on nic nie odpowiedział.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Tedy go zasię pytał Piłat, mówiąc: Nic nie odpowiadasz? Oto jako wiele rzeczy świadczą przeciwko tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Ale Jezus przecię nic nie odpowiedział, tak iż się Piłat dziwował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'A na święto zwykł im był wypuszczać więźnia jednego, o którego by prosili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'I był jeden, którego zwano Barabbasz, w więzieniu z tymi, co rozruch czynią, którzy byli w rozruchu mężobójstwo popełnili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Tedy lud wystąpiwszy i głosem zawoławszy, począł prosić, żeby uczynił tak, jako im zawsze czynił,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Ale Piłat im odpowiedział, mówiąc: Chcecież, wypuszczę wam króla Żydowskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, '(Wiedział bowiem, iż go z nienawiści wydali przedniejsi kapłani.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Ale przedniejsi kapłani podburzali lud, iżby im raczej Barabbasza wypuścił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'A odpowiadając Piłat, rzekł im zasię: Cóż tedy chcecie, abym uczynił temu, którego nazywacie królem żydowskim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'A oni znowu zawołali: Ukrzyżuj go!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'A Piłat rzekł do nich: I cóż wżdy złego uczynił? Ale oni tem bardziej wołali: Ukrzyżuj go!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'A tak Piłat, chcąc ludowi dosyć uczynić, wypuścił im Barabbasza, a Jezusa ubiczowawszy, podał im, aby był ukrzyżowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Lecz żołnierze wprowadzili go do dworu, to jest do ratusza, i zwołali wszystkiej roty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'A oblekłszy go w szarłat, i uplótłszy koronę z ciernia, włożyli nań;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'I poczęli go pozdrawiać, mówiąc: Bądź pozdrowiony, królu żydowski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'I bili głowę jego trzciną i plwali nań, a upadając na kolana, kłaniali mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'A gdy się z niego naśmiali, zewlekli go z szarłatu, i oblekli go w szaty jego własne, i wiedli go, aby go ukrzyżowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Tedy przymusili mimo idącego niektórego Szymona Cyrenejczyka, (który szedł z pola,) ojca Aleksandrowego i Rufowego, aby niósł krzyż jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'I przywiedli go na miejsce Golgota, co się wykłada: Miejsce trupich głów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'I dawali mu pić wino z myrrą; ale go on nie przyjął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'A gdy go ukrzyżowali, rozdzielili szaty jego, miecąc o nie los, co by kto wziąć miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'A była trzecia godzina, gdy go ukrzyżowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Był też napis winy jego napisany: Król żydowski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Ukrzyżowali też z nim dwóch zbójców; jednego po prawicy, a drugiego po lewicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'I wypełniło się Pismo, które mówi: Z złoczyńcami jest policzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'A ci, którzy mimo chodzili, bluźnili go, chwiejąc głowami swemi a mówiąc: Ehej! który rozwalasz kościół, a we trzech dniach budujesz go!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Ratuj samego siebie, a zstąp z krzyża!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Także też i przedniejsi kapłani naśmiewając się, jedni do drugich z nauczonymi w Piśmie mówili: Innych ratował, a siebie samego ratować nie może;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Niechże teraz Chrystus on król Izraelski zstąpi z krzyża, abyśmy ujrzeli i uwierzyli. Ci też, co z nim byli ukrzyżowani, urągali mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'A gdy było o godzinie szóstej, stała się ciemność po wszystkiej ziemi, aż do godziny dziewiątej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'A o godzinie dziewiątej zawołał Jezus głosem wielkim, mówiąc: Eloi! Eloi! Lamma sabachtani, co się wykłada: Boże mój! Boże mój! czemuś mię opuścił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'A niektórzy z tych, co tam stali, usłyszawszy mówili: Oto Elijasza woła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Zatem bieżawszy jeden, napełnił gąbkę octem, a włożywszy ją na trzcinę, dawał mu pić, mówiąc: Zaniechajcie, patrzmy, jeźli przyjdzie Elijasz, zdejmować go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'A Jezus zawoławszy głosem wielkim, oddał ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'I rozerwała się zasłona kościelna na dwoje, od wierzchu aż do dołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Tedy widząc setnik, który stał przeciwko niemu, iż tak wołając oddał ducha, rzekł: Prawdziwie człowiek ten był Synem Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Były też i niewiasty z daleka się przypatrując, między któremi była Maryja Magdalena, i Maryja, Jakóba małego i Jozesa matka, i Salome;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'Które gdy jeszcze były w Galilei, chodziły za nim, a posługowały mu; i wiele innych, które z nim były wstąpiły do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'A gdy już był wieczór, (ponieważ był dzień przygotowania,) który jest przed sabatem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Przyszedłszy Józef z Arymatyi, poczesny radny pan, który też sam oczekiwał królestwa Bożego, śmiele wszedł do Piłata, i prosił o ciało Jezusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'A Piłat się dziwował, jeźliby już umarł; i zawoławszy setnika, pytał go, dawnoli umarł?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'A dowiedziawszy się od setnika, darował ciało Józefowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'A on kupiwszy prześcieradło, zdjąwszy go, obwinął w prześcieradło, i położył go w grobie, który był wykowany z opoki, i przywalił kamień do drzwi grobowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Ale Maryja Magdalena, i Maryja, matka Jozesowa, patrzały, kędy go położono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'A gdy minął sabat, Maryja Magdalena, i Maryja, matka Jakóbowa, i Salome, nakupiły wonnych rzeczy, aby przyszedłszy namazały go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'A bardzo rano pierwszego dnia po sabacie przyszły do grobu, gdy weszło słońce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'I mówili do siebie: Któż nam odwali kamień ode drzwi grobowych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, '(A spojrzawszy ujrzały, iż był kamień odwalony;) bo był bardzo wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'I wszedłszy w grób, ujrzały młodzieńca, siedzącego na prawicy, odzianego szatą białą; i ulękły się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Ale im on rzekł: Nie lękajcie się; Jezusa szukacie onego Nazareńskiego, który był ukrzyżowany; wstał z martwych, nie masz go tu; oto miejsce, gdzie go było położono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Ale idźcie, a powiedzcie uczniom jego, i Piotrowi, że was uprzedza do Galilei; tam go oglądacie, jako wam powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'A wyszedłszy prędko, uciekły od grobu: albowiem zdjęło je drżenie i zdumienie, a nikomu nic nie powiadały; bo się bały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'A Jezus, gdy zmartwychwstał raniuczko pierwszego dnia po sabacie, ukazał się naprzód Maryi Magdalenie, z której był wygnał siedm dyjabłów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'A ona szedłszy, opowiedziała tym, co z nim bywali, którzy się smucili i płakali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'A oni usłyszawszy, iż żyje, a iż jest widziany od niej, nie wierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Potem się też dwom z nich idącym ukazał w innym kształcie, gdy szli przez pole.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'A ci szedłszy opowiedzieli drugim; i tym nie uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Na ostatek się też onym jedenastu wespół siedzącym ukazał, i wyrzucał im na oczy niedowiarstwo ich, i zatwardzenie serca, iż tym, którzy go widzieli wzbudzonego, nie wierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'I rzekł im: Idąc na wszystek świat, każcie Ewangieliję wszystkiemu stworzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Kto uwierzy, a ochrzci się, zbawion będzie; ale kto nie uwierzy, będzie potępion.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'A znamiona tych, co uwierzą, te naśladować będą: W imieniu mojem dyjabły wyganiać będą, nowemi językami mówić będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Węże brać będą, a choćby co śmiertelnego pili, nie zaszkodzi im; na niemocne ręce kłaść będą, a dobrze się mieć będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'A tak Pan przestawszy z nimi mówić, wzięty jest do nieba, i usiadł na prawicy Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'A oni wyszedłszy kazali wszędy, a Pan im pomagał, i słowa ich potwierdzał przez cuda, które czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Ponieważ wiele się ich podjęło sporządzić historyję o tych sprawach, o których my pewną wiadomość mamy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Tak jako nam podali ci, którzy od początku sami widzieli, i sługami tego słowa byli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'Zdało się też i mnie, którym tego wszystkiego z początku pilnie doszedł, tobie to porządnie wypisać, zacny Teofilu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Abyś poznał pewność tych rzeczy, których cię nauczono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Był za dni Heroda, króla Judzkiego, kapłan niektóry, imieniem Zacharyjasz, z przemiany Abijaszowej, a żona jego była z córek Aaronowych, której imię było Elżbieta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'A byli oboje sprawiedliwymi przed obliczem Bożem, chodząc we wszystkich przykazaniach i usprawiedliwieniach Pańskich bez nagany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'I nie mieli potomstwa, przeto iż Elżbieta była niepłodna, a byli oboje podeszłymi w latach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Stało się tedy, gdy odprawiał urząd kapłański w porządku przemiany swojej przed Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Że według zwyczaju urzędu kapłańskiego przypadł nań los, aby kadził, wszedłszy do kościoła Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'A wszystko mnóstwo ludu było na dworze, modląc się w godzinę kadzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Tedy mu się pokazał Anioł Pański, stojący po prawej stronie ołtarza, na którym kadzono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'I zatrwożył się Zacharyjasz ujrzawszy go, a bojaźń przypadła nań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'I rzekł do niego Anioł: Nie bój się, Zacharyjaszu! boć jest wysłuchana modlitwa twoja, a Elżbieta, żona twoja, urodzi ci syna, i nazwiesz imię jego Jan,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Z którego będziesz miał radość i wesele, i wiele ich radować się będą z narodzenia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Albowiem będzie wielkim przed obliczem Pańskiem; wina i napoju mocnego nie będzie pił, a Duchem Świętym będzie napełniony zaraz z żywota matki swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'A wielu z synów Izraelskich obróci ku Panu, Bogu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Bo on pójdzie wprzód przed obliczem jego w duchu i w mocy Elijaszowej, aby obrócił serca ojców ku dzieciom, a odporne ku roztropności sprawiedliwych, aby sporządził Panu lud gotowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'I rzekł Zacharyjasz do Anioła: Po czemże to poznam? bom ja jest stary, a żona moja podeszła w dniach swych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'A odpowiadając Anioł, rzekł mu: Jam jest Gabryjel, który stoję przed obliczem Bożem, a posłanym jest, abym mówił do ciebie, a iżbym ci to wesołe poselstwo odniósł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'A oto oniemiejesz, i nie będziesz mógł mówić aż do onego dnia, którego się to stanie, dlatego, żeś nie uwierzył słowom moim, które się wypełnią czasu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'A lud oczekiwał Zacharyjasza; i dziwowali się, że tak długo bawił w kościele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'A wyszedłszy nie mógł do nich mówić; i poznali, że widzenie widział w kościele; bo im przez znaki ukazywał, i został niemym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'I stało się, gdy się wypełniły dni posługiwania jego, odszedł do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'A po onych dniach poczęła Elżbieta, żona jego, i kryła się przez pięć miesięcy, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Iż mi tak Pan uczynił we dni, w które na mię wejrzał, aby odjął hańbę moję między ludźmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'A w miesiącu szóstym posłany jest Anioł Gabryjel od Boga do miasta Galilejskiego, które zwano Nazaret,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'Do Panny poślubionej mężowi, któremu imię było Józef, z domu Dawidowego, a imię Panny Maryja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'A wszedłszy Anioł do niej, rzekł: Bądź pozdrowiona, łaską udarowana, Pan jest z tobą; błogosławionaś ty między niewiastami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Ale ona ujrzawszy go, zatrwożyła się na słowa jego, i myślała, jakie by to było pozdrowienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'I rzekł jej Anioł: Nie bój się, Maryjo! albowiem znalazłaś łaskę u Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'A oto poczniesz w żywocie i porodzisz syna, i nazwiesz imię jego Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Ten będzie wielki, a Synem Najwyższego będzie nazwany, i da mu Pan Bóg stolicę Dawida, ojca jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'I będzie królował nad domem Jakóbowym na wieki, a królestwu jego nie będzie końca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Zatem Maryja rzekła do Anioła: Jakoż to będzie, gdyż ja męża nie znam?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'A odpowiadając Anioł, rzekł jej: Duch Święty zstąpi na cię, a moc Najwyższego zacieni cię; przetoż i to, co się z ciebie święte narodzi, nazwane będzie Synem Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'A oto Elżbieta, pokrewna twoja, i ona poczęła syna w starości swojej, a ten miesiąc jest szósty onej, którą nazywano niepłodną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Bo nie będzie niemożne u Boga żadne słowo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'I rzekła Maryja: Oto służebnica Pańska; niechże mi się stanie według słowa twego. I odszedł od niej Anioł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Tedy wstawszy Maryja w onych dniach, poszła w górną krainę z kwapieniem do miasta Judzkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'A wszedłszy w dom Zacharyjaszowy, pozdrowiła Elżbietę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'I stało się, skoro usłyszała Elżbieta pozdrowienie Maryi, skoczyło niemowlątko w żywocie jej, i napełniona jest Elżbieta Duchem Świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'I zawołała głosem wielkim, i rzekła: Błogosławionaś ty między niewiastami, i błogosławiony owoc żywota twego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'A skądże mi to, iż przyszła matka Pana mego do mnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Albowiem jako doszedł głos pozdrowienia twego do uszów moich, podskoczyło od radości niemowlątko w żywocie moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'A błogosławiona, która uwierzyła: Gdyż się wykonają te rzeczy, które jej są opowiedziane od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Tedy rzekła Maryja: Wielbi dusza moja Pana;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'I rozradował się duch mój w Bogu, zbawicielu moim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Iż wejrzał na uniżenie służebnicy swojej; albowiem oto odtąd błogosławioną mię zwać będą wszystkie narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Bo mi uczynił wielkie rzeczy ten, który mocny jest, i święte imię jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'I którego miłosierdzie zostaje od narodu do narodu nad tymi, co się go boją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Dokazał mocy ramieniem swojem, i rozproszył pyszne w myślach serca ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Ściągnął mocarze z stolic ich, a wywyższył uniżone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Łaknące napełnił dobremi rzeczami, a bogacze rozpuścił próżne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Przyjął Izraela, sługę swego, pamiętając na miłosierdzie swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'Jako mówił do ojców naszych, do Abrahama i nasienia jego na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'I została z nią Maryja jakoby trzy miesiące; potem się wróciła do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'A Elżbiecie wypełnił się czas, aby porodziła, i porodziła syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'A usłyszawszy sąsiedzi i pokrewni jej, iż Pan z nią uczynił wielkie miłosierdzie swoje, radowali się pospołu z nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'I stało się, że ósmego dnia przyszli, aby obrzezali dzieciątko; i nazwali je imieniem ojca jego, Zacharyjaszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Ale odpowiadając matka jego rzekła: Nie tak; lecz nazwany będzie Janem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'I rzekli do niej: Żadnego nie masz w rodzinie twojej, co by go zwano tem imieniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'I skinęli na ojca jego, jako by go chciał nazwać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'A on kazawszy sobie podać tabliczkę, napisał mówiąc: Jan jest imię jego. I dziwowali się wszyscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'A zarazem otworzyły się usta jego, i język jego, i mówił, wielbiąc Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'I przyszedł strach na wszystkie sąsiady ich, i po wszystkiej górnej krainie Judzkiej rozgłoszone są wszystkie te słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Tedy wszyscy, którzy o tem słyszeli, składali to do serca swego, mówiąc: Cóż to wżdy za dziecię będzie? I była z nim ręka Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'A Zacharyjasz, ojciec jego, napełniony będąc Duchem Świętym, prorokował mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Błogosławiony niech będzie Pan, Bóg Izraelski, iż nawiedził i sprawił odkupienie ludowi swojemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'I wystawił nam róg zbawienia w domu Dawida, sługi swego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'Tak jako mówił przez usta świętych proroków swoich, którzy byli od wieku:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Iż im miał dać wybawienie od nieprzyjaciół naszych i z ręki wszystkich, którzy nas nienawidzili;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Aby uczynił miłosierdzie z ojcami naszymi, i wspomniał na przymierze swoje święte,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'I na przysięgę, którą przysiągł Abrahamowi, ojcu naszemu, że nam to dać miał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'Iżbyśmy mu bez bojaźni, z ręki nieprzyjaciół naszych będąc wybawieni, służyli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'W świętobliwości i w sprawiedliwości przed obliczem jego, po wszystkie dni żywota naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'A ty dzieciątko! Prorokiem Najwyższego nazwane będziesz; bo pójdziesz wprzód przed obliczem Pańskiem, abyś gotował drogi jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'A iżbyś dał znajomość zbawienia ludowi jego przez odpuszczenie grzechów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Przez wnętrzności miłosierdzia Boga naszego, w których nawiedził nas Wschód z wysokości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'Aby się ukazał siedzącym w ciemności i w cieniu śmierci ku wyprostowaniu nóg naszych na drogę pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'A ono dzieciątko rosło, i umacniało się w duchu, i było na pustyniach aż do onego dnia, którego się okazało przed Izraelem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'I stało się w one dni, że wyszedł dekret od cesarza Augusta, aby popisano wszystek świat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'A ten popis pierwszy stał się, gdy Cyreneusz był starostą Syryjskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'I szli wszyscy, aby popisani byli, każdy do miasta swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Wstąpił też i Józef z Galilei z miasta Nazaretu do ziemi Judzkiej, do miasta Dawidowego, które zowią Betlehem, (przeto iż on był z domu i z familii Dawidowej;)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Aby był popisany z Maryją, poślubioną sobie małżonką, która była brzemienną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'I stało się, gdy tam byli, wypełniły się dni, aby porodziła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'I porodziła syna swego pierworodnego; a uwinęła go w pieluszki, i położyła go w żłobie, przeto iż miejsca nie mieli w gospodzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'A byli pasterze w onej krainie w polu nocujący i straż nocną trzymający nad stadem swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'A oto Anioł Pański stanął podle nich, a chwała Pańska zewsząd oświeciła je, i bali się bojaźnią wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'I rzekł do nich Anioł: Nie bójcie się; bo oto zwiastuję wam radość wielką, która będzie wszystkiemu ludowi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Iż się wam dziś narodził zbawiciel, który jest Chrystus Pan, w mieście Dawidowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'A to wam będzie za znak: znajdziecie niemowlątko uwinione w pieluszki, leżące w żłobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'A zaraz z onym Aniołem przybyło mnóstwo wojsk niebieskich, chwalących Boga i mówiących:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Chwała na wysokościach Bogu, a na ziemi pokój, w ludziach dobre upodobanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'I stało się, gdy odeszli Aniołowie od nich do nieba, że oniż pasterze rzekli jedni do drugich: Pójdźmyż aż do Betlehemu, a oglądajmy tę rzecz, która się stała, którą nam Pan oznajmił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'A tak spiesząc się, przyszli i znaleźli Maryję i Józefa, i ono niemowlątko leżące w żłobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'I ujrzawszy rozsławili to, co im było powiedziano o tem dzieciątku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'A wszyscy, którzy słyszeli, dziwowali się temu, co im pasterze powiadali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Lecz Maryja zachowywała wszystkie te słowa, uważając je w sercu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'I wrócili się pasterze, wielbiąc i chwaląc Boga ze wszystkiego, co słyszeli i widzieli, tak jako im było powiedziano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'A gdy się wypełniło ośm dni, aby obrzezano ono dzieciątko, tedy imię jego nazwane jest Jezus, którem było nazwane od Anioła, pierwej niż się w żywocie poczęło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Gdy się też wypełniły dni oczyszczenia jej według zakonu Mojżeszowego, przynieśli go do Jeruzalemu, aby go stawili Panu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, '(Tak jako napisano w zakonie Pańskim: że wszelki mężczyzna, otwierający żywot, świętym Panu nazwany będzie.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'A żeby oddali ofiarę według tego, co powiedziano w zakonie Pańskim, parę synogarlic, albo dwoje gołąbiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'A oto był człowiek w Jeruzalemie, któremu imię było Symeon; a ten człowiek był sprawiedliwy i bogobojny, oczekujący pociechy Izraelskiej, a Duch Święty był nad nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'I obwieszczony był od Boga przez Ducha Świętego, że nie miał oglądać śmierci, ażby pierwej oglądał Chrystusa Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Ten przyszedł z natchnienia Ducha Świętego do kościoła; a gdy rodzice wnosili dzieciątko, Jezusa, aby uczynili według zwyczaju zakonnego przy nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'Tedy on wziąwszy go na ręce swoje, chwalił Boga i mówił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Teraz puszczasz sługę twego, Panie! według słowa twego, w pokoju:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Gdyż oczy moje oglądały zbawienie twoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'Któreś zgotował przed obliczem wszystkich ludzi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Światłość ku objawieniu poganom, a chwałę ludu twego Izraelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'A ojciec i matka jego dziwowali się temu, co powiadano o nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'I błogosławił im Symeon, i rzekł do Maryi, matki jego: Oto ten położony jest na upadek i na powstanie wielu ich w Izraelu, i na znak, przeciw któremu mówić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(I twoję własną duszę miecz przeniknie,) aby myśli z wielu serc objawione były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'A była Anna prorokini, córka Fanuelowa, z pokolenia Asser, która była bardzo podeszła w latach, i żyła siedm lat z mężem od panieństwa swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'A ta była wdową, około ośmdziesiąt i czterech lat; która nie wychodziła z kościoła, w postach i w modlitwach służąc Bogu w nocy i we dnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Ta też onejże godziny nadszedłszy, wyznawała Pana, i mówiła o nim wszystkim, którzy oczekiwali odkupienia w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'A tak wykonawszy wszystko według zakonu Pańskiego, wrócili się do Galilei, do miasta swego Nazaretu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'A dzieciątko ono rosło, i umacniało się w Duchu, pełne będąc mądrości, a łaska Boża była nad niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'A rodzice jego chadzali na każdy rok do Jeruzalemu na święto wielkanocne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'A gdy już był we dwunastym roku, a oni wstępowali do Jeruzalemu według zwyczaju onego święta;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'I gdy skończyli one dni, a już się wracali nazad, zostało dziecię Jezus w Jeruzalemie, a tego nie wiedział Józef i matka jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Lecz mniemając, że jest w towarzystwie podróżnem, uszli dzień drogi, i szukali go między krewnymi i między znajomymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'A gdy go nie znaleźli, wrócili się do Jeruzalemu, szukając go,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'I stało się po trzech dniach, że go znaleźli siedzącego w kościele w pośrodku doktorów, słuchającego ich i pytającego ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'I zdumiewali się wszyscy, którzy go słuchali, nad rozumem i nad odpowiedziami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'A ujrzawszy go rodzice, zdumieli się. I rzekła do niego matka jego: Synu! przeczżeś nam to uczynił? Oto ojciec twój i ja z boleścią szukaliśmy cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'I rzekł do nich: Cóż jest, żeście mię szukali? Izaliście nie wiedzieli, iż w tych rzeczach, które są Ojca mego, ja być muszę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Lecz oni nie zrozumieli tego słowa, które im mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'I zstąpił z nimi, i przyszedł do Nazaretu, a był im poddany. A matka jego zachowywała wszystkie te słowa w sercu swojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'A Jezus pomnażał się w mądrości, i we wzroście i w łasce u Boga i u ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'A roku piętnastego panowania Tyberyjusza Cesarza, gdy Poncki Piłat był starostą Judzkim, a Herod Tetrarchą Galilejskim, a Filip, brat jego, Tetrarchą Iturejskim i krainy Trachonickiej, a Lizanijasz Tetrarchą Abileńskim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'Za najwyższych kapłanów Annasza i Kaifasza, stało się słowo Boże do Jana, Zacharyjaszowego syna, na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'I przyszedł do wszystkiej krainy leżącej około Jordanu, każąc chrzest pokuty na odpuszczenie grzechów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Jako napisano w księgach proroctw Izajasza proroka, mówiącego: Głos wołającego na puszczy; gotujcie drogę Pańską, proste czyńcie ścieżki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Każdy padół będzie wypełniony, a każda góra i pagórek będzie zniżony, i miejsca krzywe wyprostują się, a ostre drogi będą gładkiemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'I ogląda wszelkie ciało zbawienie Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Mówił tedy ludowi, który wychodził, aby był ochrzczony od niego: Rodzaju jaszczurczy! któż wam pokazał, żebyście uciekali przed przyszłym gniewem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Przynoścież tedy owoce godne pokuty, a nie poczynajcie mówić sami w sobie: Ojca mamy Abrahama; albowiem powiadam wam, że Bóg może i z tych kamieni wzbudzić dzieci Abrahamowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'A już siekiera do korzenia drzew przyłożona jest; przetoż każde drzewo, które nie przynosi owocu dobrego, bywa wycięte i w ogień wrzucone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'I pytał go lud mówiąc: Cóż tedy czynić będziemy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'A on odpowiadając rzekł im: Kto ma dwie suknie, niechaj udzieli temu, co nie ma; a kto ma pokarm niech także uczyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Przyszli też i celnicy, aby byli chrzczeni, i rzekli do niego: Nauczycielu! a my cóż czynić będziemy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'A on rzekł do nich: Nic więcej nie wyciągajcie nad to, co wam postanowiono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Pytali go też i żołnierze, mówiąc: A my cóż czynić będziemy? I rzekł do nich: Nikomu gwałtu nie czyńcie, i nikogo nie potwarzajcie, a przestawajcie na żołdzie waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'A gdy lud oczekiwał, i myślili wszyscy w sercach swych o Janie, jeśliby snać on nie był Chrystusem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Odpowiedział Jan wszystkim, mówiąc: Jać was chrzczę wodą; lecz idzie mocniejszy nad mię, któremum nie jest godzien rozwiązać rzemyka u butów jego; ten was chrzcić będzie Duchem Świętym i ogniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Którego łopata jest w ręku jego, a wyczyści bojewisko swoje, i zgromadzi pszenicę do gumna swego, ale plewy spali ogniem nieugaszonym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'A tak wiele i innych rzeczy napominając, odpowiadał ludowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'A Herod Tetrarcha, będąc strofowany od niego dla Herodyjady, żony Filipa, brata jego, i dla wszystkich złych spraw, które czynił Herod.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'Przydał i to nade wszystko, iż wsadził Jana do więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'I stało się, gdy był ochrzczony wszystek lud, i gdy Jezus był ochrzczony, i modlił się, że się niebo otworzyło;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'I zstąpił nań Duch Święty w kształcie cielesnym jako gołębica, i stał się głos z nieba, mówiąc: Tyś jest on Syn mój miły; w tobie mi się upodobało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'A Jezus poczynał być jakoby w trzydziestu latach, będąc (jako mniemano,) synem Józefa, syna Helego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Syna Matatowego, syna Lewiego, syna Melchyjego, syna Jannego, syna Józefowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'Syna Matatyjaszowego, syna Amosowego, syna Naumowego, syna Eslego, syna Naggiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'Syna Maatowego, syna Mattatyjaszowego, syna Semejego, syna Józefowego, syna Judowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'Syna Joannowego, syna Resowego, syna Zorobabelowego, syna Salatyjelowego, syna Neryjego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'Syna Melchyjego, syna Addyjego, syna Kosamowego, syna Elmodamowego, syna Irowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'Syna Jozego, syna Elijezerowego, syna Jorymowego, syna Mattatego, syna Lewiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'Syna Symeonowego, syna Judowego, syna Józefowego, syna Jonanowego, syna Elijakimowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'Syna Meleowego, syna Mainanowego, syna Mattatanowego, syna Natanowego, syna Dawidowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Syna Jessego, syna Obedowego, syna Boozowego, syna Salmonowego, syna Nasonowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Syna Aminadabowego, syna Aramowego, syna Esromowego, syna Faresowego, syna Judowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'Syna Jakóbowego, syna Izaakowego, syna Abrahamowego, syna Tarego, syna Nachorowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'Syna Saruchowego, syna Ragawowego, syna Falekowego, syna Heberowego, syna Salego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Syna Kainowego, syna Arfaksadowego, syna Semowego, syna Noego, syna Lamechowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Syna Matusalemowego, syna Enochowego, syna Jaredowego, syna Malaleelowego, syna Kainanowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'Syna Enosowego, syna Setowego, syna Adamowego, syna Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'A Jezus pełen będąc Ducha Świętego, wrócił się od Jordanu, i pędzony jest od Ducha na puszczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'I był przez czterdzieści dni kuszony od dyjabła, a nie jadł nic przez one dni; ale gdy się te skończyły, potem łaknął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'I rzekł mu dyjabeł: Jeźliś jest Syn Boży, rzecz kamieniowi temu, aby się stał chlebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Ale Jezus odpowiedział mu, mówiąc: Napisano, iż nie samym chlebem żyć będzie człowiek, ale każdem słowem Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'I wwiódł go dyjabeł na górę wysoką, i pokazał mu wszystkie królestwa świata we mgnieniu oka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'I rzekł mu dyjabeł: Dam ci tę wszystkę moc i sławę ich; bo mi jest dana, a komu chcę, dawam ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'A tak jeźli się ukłonisz przede mną, będzie wszystko twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'A odpowiadając Jezus rzekł mu: Pójdź precz ode mnie, szatanie! albowiem napisano: Panu, Bogu twemu, kłaniać się będziesz, i jemu samemu służyć będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Potem wiódł go do Jeruzalemu, i postawił go na ganku kościelnym, i rzekł mu: Jeźliś jest Syn Boży, spuść się stąd na dół;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Albowiem napisano: Że Aniołom swoim przykazał o tobie, aby cię strzegli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'A że cię na rękach nosić będą, byś snać nie obraził o kamień nogi twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'A odpowiadając Jezus rzekł mu: Powiedziano: Nie będziesz kusił Pana, Boga twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'A gdy dokończył wszystkich pokus dyjabeł, odstąpił od niego do czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'I wrócił się Jezus w mocy onego Ducha do Galilei. I rozeszła się o nim wieść po wszystkiej onej okolicznej krainie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'A on nauczał w bóżnicach ich, i był sławiony od wszystkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'I przyszedł do Nazaretu, gdzie był wychowany, i wszedł według zwyczaju swego w dzień sabatu do bóżnicy, i wstał, aby czytał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'I podano mu księgi Izajasza proroka; a otworzywszy księgi, znalazł miejsce, gdzie było napisano:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'Duch Pański nade mną; przeto mię pomazał, abym opowiadał Ewangieliję ubogim; posłał mię, abym uzdrawiał skruszone na sercu, abym zwiastował pojmanym wyzwolenie, i ślepym przejrzenie, i abym wypuścił uciśnione na wolność;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'Abym opowiadał rok Pański przyjemny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'A zawarłszy księgę i oddawszy ją słudze, usiadł; a oczy wszystkich w bóżnicy pilnie nań patrzały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'I począł do nich mówić: Dziści się wypełniło to pismo w uszach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'I wszyscy mu dawali świadectwo, i dziwowali się wdzięczności onych słów, które pochodziły z ust jego, i mówili: Izaż ten nie jest syn Józefowy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'I rzekł do nich: Pewnie mi rzeczecie onę przypowieść: Lekarzu! ulecz samego siebie! Cośmy słyszeli, żeś uczynił w Kapernaum, uczyń i tu w ojczyźnie swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'I rzekł do nich: Zaprawdę wam powiadam: Żaden prorok nie jest przyjemnym w ojczyźnie swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Aleć wam w prawdzie powiadam, że wiele wdów było za dni Elijaszowych w ludzie Izraelskim, gdy było zamknione niebo przez trzy lata i sześć miesięcy, tak iż był wielki głód po wszystkiej ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Wszakże do żadnej z nich nie był posłany Elijasz, tylko do Sarepty, miasta Sydońskiego, do jednej wdowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'I wiele było trędowatych za Elizeusza proroka, w ludzie Izraelskim, wszakże żaden z nich nie był oczyszczony, tylko Naaman, Syryjczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Tedy wszyscy w bóżnicy, gdy to słyszeli, napełnieni byli gniewem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'A wstawszy, wypchnęli go precz z miasta, i wywiedli go na wierzch góry, na której miasto ich zbudowane było, aby go z niej na dół zrzucili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Ale on przeszedłszy przez pośrodek ich, uszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'I zstąpił do Kapernaum, miasta Galilejskiego, a tam je nauczał w sabaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'I zdumiewali się nad nauką jego; bo była mocna mowa jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'A w bóżnicy był człowiek, który miał ducha dyjabła nieczystego, i zawołał głosem wielkim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'Mówiąc: Ach! Cóż my z tobą mamy, Jezusie Nazareński? Przyszedłeś, abyś nas wytracił; znam cię, ktoś jest, żeś on Święty Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'I zgromił go Jezus, mówiąc: Umilknij, a wynijdź z niego. Tedy dyjabeł porzuciwszy go w pośrodek, wyszedł z niego, nic mu nie zaszkodziwszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'I przyszedł strach na wszystkie, i rozmawiali między sobą, mówiąc: Cóż to za słowo, że z władzą i z mocą rozkazuje duchom nieczystym, a wychodzą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'I rozeszła się o nim wieść na wszystkie miejsca okolicznej krainy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'A Jezus wstawszy, z bóżnicy wszedł w dom Szymona, a świekra Szymonowa miała gorączkę wielką; i prosili go za nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Tedy on stanąwszy nad nią, zgromił gorączkę, i opuściła ją; a zarazem wstawszy, posługiwała im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'A gdy słońce zachodziło, wszyscy, którzy mieli chorujące na rozmaite niemocy, przywodzili je do niego, a on na każdego z nich ręce włożywszy, uzdrawiał je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Ku temu wychodzili i dyjabli z wielu ich, wołając i mówiąc: Tyś jest on Chrystus, Syn Boży; ale on zgromiwszy je, nie dopuszczał im mówić; bo wiedzieli, iż on jest Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'A gdy był dzień, wyszedłszy, szedł na miejsce puste. A lud go szukał, i przyszli aż do niego, i zatrzymywali go, aby nie odchodził od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'A on rzekł do nich: I innym miastom muszę opowiadać królestwo Boże; bom na to posłany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'I kazał w bóżnicach Galilejskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'I stało się, gdy nań lud nalegał, aby słuchał słowa Bożego, że on stał podle jeziora Gienezaretskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'I ujrzał dwie łodzi stojące przy jeziorze; ale rybitwi wyszedłszy z nich, płukali sieci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'A wstąpiwszy w jedną z tych łodzi, która była Szymonowa, prosił go, aby maluczko odjechał od brzegu; a usiadłszy, uczył on lud z onej łodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'A gdy przestał mówić, rzekł do Szymona: Zajedź na głębię, a zapuśćcie sieci wasze ku łowieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'A odpowiadając Szymon, rzekł mu: Mistrzu! przez całą noc robiąc, niceśmy nie pojmali, wszakże na słowo twoje zapuszczę sieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'A gdy to uczynili, zagarnęli ryb mnóstwo wielkie, tak że się rwała sieć ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'I skinęli na towarzysze, którzy byli w drugiej łodzi, aby przybywszy ratowali ich; i przybyli i napełnili obie łodzi, aż się zanurzały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Co widząc Szymon Piotr, przypadł do kolan Jezusowych, mówiąc: Wynijdź ode mnie; bom jest człowiek grzeszny, Panie!.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Albowiem go był strach ogarnął, i wszystkie, co z nim byli, z onego obłowu ryb, które byli zagarnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Także i Jakóba i Jana, syny Zebedeuszowe, którzy byli towarzysze Szymonowi. I rzekł Jezus do Szymona: Nie bój się; od tego czasu ludzi łowić będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'A oni wyciągnąwszy łódź na brzeg, wszystko opuściwszy, poszli za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'I stało się, gdy był w niektórem mieście, że oto był tam mąż pełen trądu, który ujrzawszy Jezusa, padł na twarz, i prosił go, mówiąc: Panie! jeźli chcesz, możesz mię oczyścić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Tedy wyciągnąwszy Jezus rękę, dotknął się go, mówiąc: Chcę, bądź oczyszczony; i zaraz odszedł trąd od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'I przykazał mu, aby tego nikomu nie powiadał: ale rzekł: Idź, a ukaż się kapłanowi, i ofiaruj za oczyszczenie twoje, tak jako rozkazał Mojżesz, na świadectwo przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'I rozchodziła się tem więcej powieść o nim; i schodziły się mnóstwa wielkie, aby go słuchały i uzdrowieni byli od niego od niemocy swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Ale on odchodził na pustynią, i modlił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'I stało się dnia niektórego, że on nauczał, a siedzieli też tam i Faryzeuszowie i nauczyciele Zakonu, którzy się byli zeszli ze wszystkich miasteczek Galilejskich i Judzkich, i z Jeruzalemu; a moc Pańska przytomna była uzdrawianiu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'A oto mężowie nieśli na łożu człowieka powietrzem ruszonego, i szukali, jakoby go wnieść i postawić przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'A gdy nie znaleźli, którędy by go wnieśli, dla ciżby, wstąpiwszy na dach, przez posowę spuścili go łożem w pośrodek przed Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Który ujrzawszy wiarę ich, rzekł mu: Człowiecze! odpuszczone są tobie grzechy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Tedy poczęli myślić nauczeni w Piśmie i Faryzeuszowie, mówiąc: Któż to jest, co mówi bluźnierstwa? Któż może odpuszczać grzechy, tylko sam Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Ale Jezus poznawszy myśli ich, odpowiadając rzekł do nich: Cóż myślicie w sercach waszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Cóż jest łatwiejszego, rzec: Odpuszczone są tobie grzechy twoje, czyli rzec: Wstań a chodź?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Ale iżbyście wiedzieli, że Syn człowieczy ma moc na ziemi odpuszczać grzechy, (rzekł powietrzem ruszonemu:) Tobie mówię: Wstań, a wziąwszy na się łoże swoje, idź do domu twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'A on zarazem wstawszy przed nimi, wziąwszy na się to, na czem leżał, szedł do domu swego, wielbiąc Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'I zdumieli się wszyscy, i chwalili Boga, i napełnieni byli bojaźnią, mówiąc: Widzieliśmy dziś dziwne rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'A potem wyszedł i ujrzał celnika, imieniem Lewiego, siedzącego na cle, i rzekł mu: Pójdź za mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'I opuścił wszystko, a wstawszy, szedł za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'I sprawił mu lewi ucztę wielką w domu swoim; a było wielkie zgromadzenie celników i innych, którzy z nim za stołem siedzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Tedy szemrali nauczeni w Piśmie i Faryzeuszowie, mówiąc do uczniów jego: Przecz z celnikami i z grzesznikami jecie i pijecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'A Jezus odpowiadając, rzekł do nich: Nie potrzebująć zdrowi lekarza, ale ci, co się źle mają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Nie przyszedłem, wzywać sprawiedliwych, ale grzesznych do pokuty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'A oni mu rzekli: Przecz uczniowie Janowi często poszczą i modlą się, także i Faryzejscy, a twoi jedzą i piją?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'A on im rzekł: Izali możecie uczynić, żeby synowie łożnicy małżeńskiej pościli, póki z nimi jest oblubieniec?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Lecz przyjdą dni, gdy oblubieniec odjęty będzie od nich; tedy w one dni pościć będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Powiedział im też podobieństwo: Iż żaden łaty z szaty nowej nie przyprawia do szaty wiotchej; bo inaczej to, co jest nowego, drze wiotche, a do wiotchego nie zgadza się łata z nowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'I nikt nie leje wina nowego w stare statki; bo inaczej wino młode rozsadzi statki, i samo wyciecze, i statki się popsują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Ale młode wino ma być wlewane w statki nowe; a tak oboje bywają zachowane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'A nikt, kto się napił starego, nie zaraz chce młodego; ale mówi: Lepsze jest stare.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'I stało się w drugi sabat, że szedł Jezus przez zboża; i rwali uczniowie jego kłosy, a rękami wycierając jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Ale niektórzy z Faryzeuszów rzekli do nich: Przeczże czynicie to, czego się nie godzi czynić w sabat?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'A odpowiadając Jezus, rzekł do nich: Azaście tego nie czytali, co uczynił Dawid, gdy łaknął sam, i ci, którzy z nim byli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Jako wszedł do domu Bożego, a wziął chleby pokładne, i jadł, a dał i tym, którzy z nim byli; których się nie godziło jeść, tylko samym kapłanom?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'I rzekł im: Syn człowieczy jestci Panem i sabatu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Stało się także i w inszy sabat, że Jezus wszedł do bóźnicy, i nauczał; i był tam człowiek, którego ręka prawa była uschła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'I podstrzegli go nauczeni w Piśmie i Faryzeuszowie, jeźliby w sabat uzdrawiał, aby znaleźli, o coby nań skarżyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Ale on wiedział myśli ich, i rzekł człowiekowi, który miał rękę uschłą: Wstań a stań pośrodku. A on wstawszy, stanął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Rzekł tedy do nich Jezus: Spytam was o jednę rzecz: Godzili się w sabaty dobrze czynić, czyli źle czynić? Człowieka zachować, czyli zatracić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'A spojrzawszy w koło po wszystkich, rzekł onemu człowiekowi: Wyciągnij rękę twoję! a on tak uczynił i przywrócona jest do zdrowia ręka jego, jako i druga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Ale oni napełnieni będąc szaleństwem, rozmawiali miedzy sobą, coby uczynić mieli Jezusowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'I stało się w oneż dni, odszedł na górę, aby się modlił; i był tam przez noc na modlitwie Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'A gdy był dzień, zwołał uczniów swych i wybrał z nich dwanaście, które też nazwał Apostołami:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Szymona, którego też nazwał Piotrem, i Andrzeja brata jego, Jakóba, i Jana, Filipa, i Bartłomieja;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Mateusza, i Tomasza, Jakóba, syna Alfeuszowego, i Szymona, którego zowią Zelotes;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Judasza, brata Jakóbowego, i Judasza Iszkarjotę, który potem był zdrajcą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'A zstąpiwszy z nimi stanął na miejscu pola równego, i gormada uczniów jego, i wielkie mnóstwo ludu ze wszystkiej Judzkiej ziemi, i z Jeruzalemu, i z kraju pomorskiego, leżącego przy Tyrze i Sydonie, którzy byli przyszli, aby go słuchali, i byli uzdrowieni od chorób swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'I ci, którzy byli trapieni od duchów nieczystych, byli uzdrowieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'A wszystek lud szukał, jakoby się go dotknąć; albowiem moc wychodziła z niego, i uzdrawiała wszystkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'A on podniósłszy oczy swoje na uczniów, mówił: Błogosławieni jesteście wy, ubodzy! bo wasze jest królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Błogosławieni jesteście, którzy teraz łakniecie; bo będziecie nasyceni. Błogosławieni jesteście, którzy teraz płaczecie; bo się śmiać będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Błogosławieni będziecie, gdy was ludzie nienawidzieć będą, i gdy wyłączą, i będą was sromocić, i imię wasze wyrzucą jako złe, dla Syna człowieczego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Radujcie się dnia tego i weselcie się; albowiem oto zapłata wasza jest obfita w niebiesiech; boć tak właśnie prorokom czynili ojcowie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Ale biada wam bogaczom! bo już macie pociechę waszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Biada wam, którzyście nasyceni! albowiem łaknąć będziecie. Biada wam, którzy się teraz śmiejecie! bo się smucić i płakać będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Biada wam, gdyby dobrze o was mówili wszyscy ludzie; bo tak czynili fałszywym prorokom ojcowie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Ale wam powiadam, którzy słuchacie: Miłujcie nieprzyjacioły wasze, czyńcie dobrze tym, którzy was mają w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Błogosławcie tym, którzy was przeklinają; módlcie się za tymi, którzy wam złość wyrządzają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Temu, któryby cię uderzył w policzek, nastaw mu i drugiego: a temu, któryćby brał płaszcz, i sukni nie zabraniaj;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'I każdemu, któryby cię prosił, daj, a temu, co twoje bierze, nie upominaj się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'I cobyście chcieli, aby wam ludzie czynili, tak i wy im czyńcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Albowiem jeźli miłujecie te, którzy was miłują, jakąż łaskę macie? albowiem toż i grzesznicy właśnie czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'A jeźli dobrze czynicie tym, którzy wam dobrze czynią, jakąż łaskę macie? albowiem toż i grzesznicy właśnie czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'A jeźli pożyczacie tym, od których się spodziewacie odebrać, jakąż łaskę macie? albowiem i grzesznicy grzesznikom pożyczają, aby zasię tyle odebrali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Owszem miłujcie nieprzyjacioły wasze, i czyńcie im dobrze, i pożyczajcie, nic się stąd nie spodziewając, a będzie wielka zapłata wasza, i będziecie synami Najwyższego; albowiem on dobrotliwy jest przeciw niewdzięcznym i złym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Przetoż bądźcie miłosierni, jako i Ojciec wasz miłosierny jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Nie sądźcie, a nie bądziecie sądzeni; nie potępiajcie, a nie będziecie potępieni, a będzie wam odpuszczono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Dawajcie, a będzie wam dano; miarę dobrą, natłoczoną, i potrzęsioną, i opływającą dadzą na łono wasze; albowiem tąż miarą, którą mierzycie, będzie wam zaś obmierzono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'I powiedział im podobieństwo: Izali może ślepy ślepego prowadzić? azaż nie obadwaj w dół wpadną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Nie jestci uczeń nad mistrza swego; lecz doskonały będzie każdy, będzieli jako mistrz jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'A czemuż widzisz źdźbło w oku brata twego, a balki, która jest w oku twojem, nie baczysz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Albo jakoż możesz rzec bratu twemu: Bracie! dopuść, iż wyjmę źdźbło, które jest w oku twojem, a sam balki, która jest w oku twojem, nie widzisz? Obłudniku! wyjmij pierwej balkę z oka twego, a tedy przejrzysz, abyś wyjął źdźbło, które jest w oku brata twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Nie jest bowiem drzewo dobre, które przynosi owoc zły; ani jest drzewo złe, które przynosi owoc dobry;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Gdyż każde drzewo z owocu własnego poznane bywa; boć nie zbierają z ciernia figów, ani z głogu zbierają winnych gron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Człowiek dobry z dobrego skarbu serca swego wynosi rzeczy dobre, a zły człowiek ze złego skarbu serca swego wynosi rzeczy złe; albowiem z obfitości serca mówią usta jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Przeczże mię tedy zowiecie Panie, Panie! a nie czynicie tego, co mówię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Każdy, który przychodzi do mnie, a słucha słów moich, i czyni je, pokażę wam, komu jest podobnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Podobny jest człowiekowi dom budującemu, który kopał i wykopał głęboko, a założył grunt na opoce; a gdy przyszła powódź, otrąciła się rzeka o on dom, ale nie mogła go poruszyć; bo był założony na opoce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Ale który słucha, a nie czyni, podobny jest człowiekowi, który zbudował dom swój na ziemi bez gruntu; o który się otrąciła rzeka, i zarazem upadł, a był upadek domu onego wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'A gdy dokończył wszystkich mów swoich przed onym ludem, wszedł do Kapernaum;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'A niektórego setnika sługa źle się mając, już prawie miał umrzeć, którego on sobie bardzo poważał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Ten usłyszawszy o Jezusie, posłał do niego starszych z Żydów, prosząc go, aby przyszedłszy uzdrowił sługę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'A oni przyszedłszy do Jezusa, prosili go z pilnością, mówiąc: Godzien jest, abyś mu to uczynił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'Albowiem miłuje naród nasz, i on nam bóżnicę zbudował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'A tak Jezus szedł z nimi. Ale gdy niedaleko był od domu, posłał do niego on setnik przyjacioły, mówiąc mu: Panie! nie zadawaj sobie pracy; bomci nie jest godzien, abyś wszedł pod dach mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Przetoż i samego siebie nie miałem za godnego, abym miał przyjść do ciebie; ale rzecz słowo, a będzie uzdrowiony sługa mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Bomci i ja człowiek pod mocą postanowiony, mający pod sobą żołnierzy, i mówię temu: Idź, a idzie, a drugiemu: Przyjdź, a przychodzi, a słudze mojemu: Czyń to, a czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Tedy usłyszawszy to Jezus, zadziwił mu się, i obróciwszy się, rzekł do ludu, który za nim szedł: Powiadam wam, żem ani w Izraelu tak wielkiej wiary nie znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'A wróciwszy się do domu ci, którzy byli posłani, znaleźli sługę, który się źle miał, zdrowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'I stało się nazajutrz, że szedł do miasta, które zowią Naim, a szło z nim uczniów jego wiele i lud wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'A gdy się przybliżył do bramy miejskiej, tedy oto wynoszono umarłego, syna jedynego matki swojej, a ta była wdową, a z nią szedł wielki lud miasta onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Którą ujrzawszy Pan użalił się jej, i rzekł jej: Nie płacz!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'I przystąpiwszy dotknął się trumny (mar), (a ci, co nieśli, stanęli) i rzekł: Młodzieńcze! tobie mówię, wstań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'I usiadł on, który był umarł, i począł mówić; i oddał go matce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Tedy wszystkich strach zdjął, a wielbili Boga, mówiąc: Prorok wielki powstał między nami, a Bóg nawiedził lud swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'I rozeszła się o nim ta wieść po wszystkiej Judzkiej ziemi, i po wszystkiej okolicznej krainie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'I oznajmili Janowi uczniowie jego o tem wszystkiem. A Jan wezwawszy dwóch niektórych z uczniów swoich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Posłał je do Jezusa, mówiąc: Tyżeś jest ten, który ma przyjść, czyli inszego czekać mamy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'A gdy przyszli do niego mężowie oni, rzekli: Jan Chrzciciel posłał nas do ciebie, mówiąc: Tyżeś jest ten, który ma przyjść, czyli inszego czekać mamy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'A onejże godziny wiele ich uzdrowił od chorób, od niemocy, i od duchów złych, i wiele ślepych wzrokiem darował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'A odpowiadając Jezus, rzekł im: Szedłszy oznajmijcie Janowi, coście widzieli i słyszeli, iż ślepi widzą, chromi chodzą, trędowaci biorą oczyszczenie, głusi słyszą, umarli zmartwychwstają, a ubogim opowiadana bywa Ewangielija.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'A błogosławiony jest, kto by się nie zgorszył ze mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'A gdy odeszli posłowie Janowi, począł mówić do ludu o Janie: Coście wyszli na puszczę widzieć? Izali trzcinę chwiejącą się od wiatru?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Ale coście wyszli widzieć? Izali człowieka w miękkie szaty obleczonego? Oto ci, którzy w szatach kosztownych i w rozkoszy żyją, są w domach królewskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Ale coście wyszli widzieć? Izali proroka? Zaiste powiadam wam, iż więcej niż proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Tenci bowiem jest, o którym napisano: Oto Ja posyłam Anioła mego przed obliczem twojem, który zgotuje drogę twoję przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Albowiem powiadam wam: Większego proroka z tych, którzy się z niewiast rodzą, nie masz nad Jana Chrzciciela żadnego; lecz kto najmniejszy jest w królestwie Bożem, większy jest, niżeli on.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Tedy wszystek lud słysząc to, i celnicy, wielbili Boga, będąc ochrzczeni chrztem Janowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Ale Faryzeuszowie i zakonnicy pogardzili radą Bożą sami przeciwko sobie, nie będąc ochrzczeni od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'I rzekł Pan: Komuż tedy przypodobam ludzi rodzaju tego, a komu są podobni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Podobni są dzieciom, które siedzą na rynku, a jedne na drugie wołają, mówiąc: Grałyśmy wam na piszczałkach, a nie tańcowaliście; śpiewałyśmy żałobne pieśni, a nie płakaliście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Albowiem przyszedł Jan Chrzciciel, i chleba nie jedząc i wina nie pijąc, a mówicie: Dyjabelstwo ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Przyszedł Syn człowieczy jedząc i pijąc, a mówicie: Oto człowiek obżerca i pijanica wina, przyjaciel celników i grzeszników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Ale usprawiedliwiona jest mądrość od wszystkich synów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'I prosił go niektóry z Faryzeuszów, aby z nim jadł. A tak wszedłszy w dom Faryzeuszów, usiadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'A oto niewiasta, która była w mieście grzeszna, dowiedziawszy się, iż siedzi w domu Faryzeuszowym, przyniosła alabastrowy słoik maści;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'A stanąwszy z tyłu u nóg jego, płacząc poczęła łzami polewać nogi jego, a włosami głowy swojej ucierała, i całowała nogi jego, i maścią mazała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'A widząc to Faryzeusz, który go był wezwał, rzekł sam w sobie, mówiąc: Być ten był prorokiem, wiedziałby, która i jaka jest ta niewiasta, co się go dotyka; bo jest grzesznica.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'A odpowiadając Jezus, rzekł do niego: Szymonie! mam ci nieco powiedzieć, a on rzekł: Powiedz, Nauczycielu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Miał niektóry lichwiarz dwóch dłużników; jeden dłużen był pięćset groszy, a drugi pięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'A gdy oni nie mieli czem zapłacić, odpuścił obydwom. Powiedz tedy, któryż z nich bardziej go miłować będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'A odpowiadając Szymon, rzekł: Mniemam, iż ten, któremu więcej odpuścił. A on mu rzekł: Dobrześ rozsądził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'I obróciwszy się do niewiasty, rzekł Szymonowi: Widzisz tę niewiastę? Wszedłem do domu twego, nie dałeś wody na nogi moje; ale ta łzami polała nogi moje, i włosami głowy swej otarła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Nie pocałowałeś mię, ale ta jako weszła, nie przestała całować nóg moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Nie pomazałeś oliwą głowy mojej, ale ta maścią pomazała nogi moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Dlaczego, mówię tobie, odpuszczono jej wiele grzechów, gdyż wiele umiłowała; a komu mało odpuszczono, mało miłuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'A on jej rzekł: Odpuszczone są tobie grzechy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'I poczęli spółsiedzący mówić między sobą: Któż jest ten, który i grzechy odpuszcza?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'I rzekł do niewiasty: Wiara twoja ciebie zbawiła. Idźże w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'I stało się potem, że on chodził po miastach i po miasteczkach każąc i opowiadając królestwo Boże, a oni dwunastu byli z nim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'I niektóre niewiasty, które był uzdrowił od duchów złych i od niemocy ich, jako Maryja, którą zwano Magdaleną, z której było siedm dyjabłów wyszło;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'I Joanna, żona Chuzego, urzędnika Herodowego, i Zuzanna, i inszych wiele, które mu służyły z majętności swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'A gdy się schodził wielki lud, i z różnych miast garnęli się do niego, rzekł przez podobieństwo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Wyszedł rozsiewca, aby rozsiewał nasienie swoje; a gdy on rozsiewał, tedy jedno padło podle drogi i podeptane jest, a ptaki niebieskie podziobały je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'A drugie padło na opokę, a gdy wzeszło, uschło, przeto iż nie miało wilgotności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'A drugie padło między ciernie; ale ciernie wespół z niem wzrosły, i zadusiły je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'A drugie padło na ziemię dobrą, a gdy wzeszło, przyniosło pożytek stokrotny. To mówiąc wołał: Kto ma uszy ku słuchaniu, niechaj słucha!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'I pytali go uczniowie jego, mówiąc: Co by to było za podobieństwo?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'A on im rzekł: Wam dano wiedzieć tajemnicę królestwa Bożego; ale innym w podobieństwach, aby widząc nie widzieli, a słysząc nie rozumieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'A to podobieństwo takie jest: nasienie jest słowo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'A którzy podle drogi, ci są, którzy słuchają, zatem przychodzi dyjabeł, i wybiera słowo z serca ich, aby uwierzywszy, nie byli zbawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'A którzy na opoce, ci są, którzy gdy słuchają, z radością słowo przyjmują, ale ci korzenia nie mają, ci do czasu wierzą, a czasu pokusy odstępują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'A które padło między ciernie, ci są, którzy słuchają słowa: ale odszedłszy, od pieczołowania i bogactw, i rozkoszy żywota bywają zaduszeni, i nie przynoszą pożytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Ale które padło na ziemię dobrą, ci są, którzy w sercu uprzejmem i dobrem słyszane słowo zachowują, i owoc przynoszą w cierpliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'A żaden zapaliwszy świecę, nie nakrywa jej naczyniem, ani jej kładzie pod łoże, ale ją stawia na świeczniku, aby ci, którzy wchodzą, widzieli światło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Bo nie masz nic tajemnego, co by nie miało być objawiono; i nie masz nic skrytego, czego by się nie dowiedziano, i co by na jaw nie wyszło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Przetoż patrzcie, jako słuchacie: albowiem kto ma, temu będzie dane, a kto nie ma, i to, co mniema, że ma, będzie odjęte od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Tedy przyszli do niego matka i bracia jego; ale do niego przystąpić nie mogli dla ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'I dano mu znać, mówiąc: Matka twoja i bracia twoi stoją przed domem, chcąc cię widzieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'A on odpowiadając, rzekł do nich: Matka moja i bracia moi są ci, którzy słowa Bożego słuchają i czynią je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'I stało się dnia jednego, że on wstąpił w łódź i uczniowie jego, i rzekł do nich: Przeprawmy się na drugą stronę jeziora. I puścili się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'A gdy płynęli, usnął. I przypadła nawałność wiatru na jezioro, i łódź się zalewała, tak że byli w niebezpieczeństwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'A przystąpiwszy, obudzili go, mówiąc: Mistrzu, mistrzu! giniemy. A on ocknąwszy się, zgromił wiatr i wały wodne, i uśmierzyły się, i stało się uciszenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Tedy im rzekł: Gdzież jest wiara wasza? A bojąc się, dziwowali się, mówiąc jedni do drugich: Któż wżdy jest ten, że i wiatrom rozkazuje i wodom, a są mu posłuszne?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'I przewieźli się do krainy Gadareńczyków, która jest przeciw Galilei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'A gdy wstąpił na ziemię, zabieżał mu mąż niektóry z onego miasta, co miał dyjabły od niemałego czasu, a nie obłóczył się w szaty, i nie mieszkał w domu, tylko w grobach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Ten ujrzawszy Jezusa, zakrzyknął, i upadł przed nim, a głosem wielkim rzekł: Cóż ja mam z tobą, Jezusie, Synu Boga najwyższego? proszę cię, nie dręcz mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Albowiem rozkazał onemu duchowi nieczystemu, aby wyszedł z onego człowieka: bo od wielu czasów porywał go; a chociaż go wiązano łańcuchami i w pętach strzeżono, jednak on porwawszy okowy, bywał od dyjabła na pustynię pędzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'I pytał go Jezus, mówiąc: Co masz za imię? A on rzekł: Wojsko; albowiem wiele dyjabłów wstąpiło było weń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Tedy go prosili, aby im nie rozkazywał stamtąd odejść w przepaść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'A była tam trzoda wielka świń, która się pasła na górze, i prosili go, aby im dopuścił wstąpić w nie. I dopuścił im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'A wyszedłszy dyjabli z onego człowieka, weszli w świnie; i porwała się ona trzoda pędem z przykra do jeziora, i utonęła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'A widząc pasterze, co się stało, uciekli; a poszedłszy, oznajmili to w mieście i we wsiach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'I wyszli, aby oglądali to, co się stało; a przyszedłszy do Jezusa, znaleźli człowieka onego, z którego wyszli dyjabli, obleczonego, przy dobrem baczeniu, siedzącego u nóg Jezusowych, i bali się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Opowiedzieli im tedy ci, którzy widzieli, jako uzdrowiono tego, który był opętany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'I prosiło go wszystko mnóstwo onej okolicznej krainy Gadareńczyków, aby odszedł od nich; albowiem ich był wielki strach ogarnął. A on wstąpiwszy w łódź, wrócił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'I prosił go on mąż, z którego wyszli dyjabli, aby był przy nim; ale go Jezus odprawił, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Wróć się do domu twego, a opowiadaj, jakoć wielkie rzeczy Bóg uczynił. I odszedł, po wszystkiem mieście opowiadając, jako mu wielkie rzeczy Jezus uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'I stało się, gdy się wrócił Jezus, że go przyjął lud; albowiem nań wszyscy oczekiwali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'A oto przyszedł mąż imieniem Jairus, a ten był przełożonym bóżnicy; a przypadłszy do nóg Jezusowych, prosił go, aby wszedł w dom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Albowiem miał córkę jedyną około dwunastu lat, która już konała. (A gdy on szedł, cisnął go lud.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'A niewiasta, która płynienie krwi cierpiała od lat dwunastu, i wynałożyła była na lekarzy wszystko swoje pożywienie, a nie mogła być od nikogo uleczona,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Przystąpiwszy z tyłu, dotknęła się podołka szaty jego, a zarazem się zastanowiło płynienie krwi jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'I rzekł Jezus: Któż jest, co się mnie dotknął? a gdy się wszyscy zapierali, rzekł Piotr, i ci, którzy z nim byli: Mistrzu! lud cię ciśnie i tłoczy, a ty mówisz: Kto się mnie dotknął?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'I rzekł Jezus: Dotknął się mnie ktoś, bom poznał, że moc ode mnie wyszła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'A widząc ona niewiasta, że się nie utaiła, ze drżeniem przystąpiła i upadła przed nim, i dlaczego się go dotknęła, powiedziała mu przed wszystkim ludem, i jako zaraz uzdrowiona była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'A on jej rzekł: Ufaj, córko! wiara twoja ciebie uzdrowiła; idźże w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'A gdy on to jeszcze mówił, przyszedł niektóry od przełożonego bóżnicy, powiadając mu: Iż umarła córka twoja, nie trudź Nauczyciela.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Ale Jezus usłyszawszy to, odpowiedział mu, mówiąc: Nie bój się, tylko wierz, a będzie uzdrowiona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'A wszedłszy w dom, nie dopuścił z sobą wnijść nikomu, tylko Piotrowi, i Jakóbowi, i Janowi, i ojcu i matce onej dzieweczki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'A płakali wszyscy, i narzekali nad nią. Ale on rzekł: Nie płaczcież! Nie umarłać, ale śpi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'I naśmiewali się z niego, wiedząc, iż była umarła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'A on wygnawszy precz wszystkich, i ująwszy ją za rękę, zawołał, mówiąc: Dzieweczko, wstań!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'I wrócił się duch jej; i wstała zaraz; i rozkazał, aby jej jeść dano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'I zdumieli się rodzice jej. A on im zakazał, aby nikomu nie powiadali tego, co się było stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'A zwoławszy Jezus dwunastu uczniów swoich, dał im moc i władzę nad wszystkimi dyjabły, i aby uzdrawiali choroby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'I rozesłał je, żeby kazali królestwo Boże, i uzdrawiali niemocne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Tedy rzekł do nich: Nie bierzcie nic na drogę, ani laski, ani taistry, ani chleba, ani pieniędzy, ani dwóch sukien miejcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'A do któregokolwiek domu wnijdziecie, tamże zostańcie, i stamtąd wynijdźcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'A którzybykolwiek was nie przyjęli, wychodząc z miasta onego, i proch z nóg waszych otrząśnijcie na świadectwo przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Wyszedłszy tedy, obchodzili wszystkie miasteczka, opowiadając Ewangieliję, a wszędzie chore uzdrawiając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'I usłyszał Herod, Tetrarcha, o wszystkiem, co się działo od niego, i był wątpliwym dla tego, że niektórzy powiadali, iż Jan zmartwychwstał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'A niektórzy zasię: Iż się Elijasz ukazał; a drudzy, iż prorok jeden z onych starych zmartwychwstał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Tedy rzekł Herod: Janamci ja ściął; któż wżdy ten jest, o którym ja takie rzeczy słyszę? i pragnął go widzieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'A wróciwszy się Apostołowie, powiadali mu, cokolwiek czynili. A on wziąwszy je z sobą, ustąpił osobno na miejsce puste przy mieście, które zowią Betsaida.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Czego gdy się lud dowiedział, szedł za nim; a przyjąwszy je, mówił im o królestwie Bożem; a te, którzy uzdrowienia potrzebowali, uzdrawiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'A gdy się dzień począł skłaniać ku wieczorowi, przystąpiwszy oni dwunastu, rzekli mu: Rozpuść ten lud, aby odszedłszy do miasteczek okolicznych, i do wsi, i do gospód, znaleźli żywność; bośmy tu na miejscu pustem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Ale on rzekł do nich: Dajcież wy im jeść. A oni powiedzieli: Nie mamy więcej, tylko pięć chlebów i dwie ryby, oprócz żebyśmy szli, a kupili, na ten wszystek lud żywności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Albowiem było mężów około pięciu tysięcy. I rzekł do uczniów swoich: Rozkażcie im usiąść w każdym rzędzie po pięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'I uczynili tak, i usiedli wszyscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'A on wziąwszy onych pięć chlebów i one dwie ryby, wejrzawszy w niebo, błogosławił im, i łamał i dawał uczniom, aby kładli przed on lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'I jedli, i nasyceni są wszyscy; i zebrano, co im zbyło z ułomków, dwanaście koszów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'I stało się, gdy się on sam osobno modlił, że z nim byli uczniowie; i pytał ich mówiąc: Kimże mię być powiadają ludzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'A oni odpowiadając rzekli: Janem Chrzcicielem, a drudzy Elijaszem, a drudzy mówią, iż prorok niektóry z onych starych zmartwychwstał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'I rzekł im: A wy kim mię być powiadacie? A odpowiadając Piotr rzekł: Chrystusem, onym Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Ale on przygroziwszy im, rozkazał, aby tego nikomu nie powiadali,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'Mówiąc: Że Syn człowieczy musi wiele cierpieć, a być odrzuconym od starszych ludu i od przedniejszych kapłanów i od nauczonych w Piśmie, i być zabitym, a trzeciego dnia zmartwychwstać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'I mówił do wszystkich: Kto chce za mną iść, niech zaprze samego siebie, a niech bierze krzyż swój na każdy dzień, i naśladuje mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Albowiem ktobykolwiek chciał zachować duszę swoję, straci ją; a ktobykolwiek stracił duszę swą dla mnie, ten ją zachowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Albowiem cóż pomoże człowiekowi, choćby wszystek świat pozyskał, gdyby samego siebie stracił, albo sobie uszkodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Albowiem ktokolwiek by się wstydził za mię i za słowa moje, za tego się Syn człowieczy wstydzić będzie, gdy przyjdzie w chwale swej i w ojcowskiej i świętych Aniołów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Aleć wam powiadam prawdziwie: Są niektórzy z tych co tu stoją, którzy nie ukuszą śmierci, aż oglądają królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'I stało się po tych mowach, jakoby po ośmiu dniach, że wziąwszy z sobą Piotra i Jana i Jakóba, wstąpił na górę, aby się modlił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'A gdy się modlił, stał się inakszy kształt oblicza jego, i szaty jego stały się białe i świetne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'A oto dwaj mężowie rozmawiali z nim, a ci byli Mojżesz i Elijasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Którzy pokazawszy się w sławie, powiadali o jego śmierci, którą miał podstąpić w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'A Piotr i ci, którzy byli z nim, obciążeni byli snem, a ocuciwszy się, ujrzeli chwałę jego i onych dwóch mężów, którzy z nim stali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'I stało się, gdy oni odeszli od niego, rzekł Piotr do Jezusa: Mistrzu! dobrze nam tu być; przetoż uczyńmy trzy namioty, tobie jeden i Mojżeszowi jeden i Elijaszowi jeden; nie wiedząc, co mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'A gdy on to mówił, stał się obłok, i zacienił je; i bali się, gdy oni wchodzili w obłok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'I stał się głos z obłoku mówiący: Ten jest Syn mój miły, tego słuchajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'A gdy się stał on głos, znaleziony jest sam Jezus. A oni milczeli, i nie powiadali w one dni nikomu nic z tego, co widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'I stało się nazajutrz, gdy oni zstąpili z góry, że mu lud wielki zabieżał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'A oto mąż z onego ludu zawołał, mówiąc: Nauczycielu! proszę cię, wejrzyj na syna mego; boć jedynego mam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'A oto duch zły popada go, a zaraz krzyczy, a on rozdziera go, śliniącego się, a zaledwie odchodzi od niego, skruszywszy go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'I prosiłem uczniów twoich, aby go wygnali; ale nie mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Tedy Jezus odpowiadając rzekł: O rodzaju niewierny i przewrotny! dokądże z wami będę, i dokądże was cierpieć będę? Przywiedź tu syna twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'A wtem, gdy on przychodził, rozdarł go dyjabeł i roztargał; ale Jezus zgromił ducha nieczystego i uzdrowił młodzieńca, i oddał go ojcu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'I zdumieli się wszyscy nad wielmożnością Bożą. A gdy się wszyscy dziwowali wszystkim rzeczom, które czynił Jezus, rzekł do uczniów swoich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Składajcie wy do uszów waszych słowa te: albowiem Syn człowieczy ma być wydany w ręce ludzkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Lecz oni nie rozumieli słowa tego, i było zakryte od nich, że go pojąć nie mogli, i nie śmieli go pytać o to słowo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'I wszczęła się gadka między nimi, kto by z nich był największym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'A Jezus widząc myśl serca ich, wziąwszy dziecię, postawił je podle siebie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'I rzekł im: Ktobykolwiek przyjął to dzieciątko w imieniu mojem, mnie przyjmuje; a ktobykolwiek mnie przyjął, przyjmuje onego, który mię posłał: albowiem kto jest najmniejszy między wszystkimi wami, tenci będzie wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'A Jan odpowiadając, rzekł: Mistrzu! widzieliśmy niektórego w imieniu twojem dyjabły wyganiającego, i zabranialiśmy mu, przeto że za tobą z nami nie chodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'I rzekł do niego Jezus: Nie zabraniajcie mu; bo kto nie jest przeciwko nam, za nami jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'I stało się, gdy się wypełniły dni, aby był wzięty w górę, że się on na to udał, aby szedł do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Tedy posłał posły przed sobą; którzy weszli do miasteczka Samarytańskiego, aby mu nagotowali gospodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Lecz oni go nie przyjęli, przeto że oblicze jego obrócone było do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'A widząc to uczniowie jego, Jakób i Jan, rzekli: Panie! chceszże, iż rzeczemy, aby ogień zstąpił z nieba i spalił je, jako i Elijasz uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Ale Jezus obróciwszy się, zgromił je, i rzekł: Nie wiecie wy, jakiego jesteście ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Albowiem Syn człowieczy nie przyszedł, zatracać dusz ludzkich, ale zachować. I szli do inszego miasteczka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'I stało się, gdy oni szli, że w drodze rzekł niektóry do niego: Pójdę za tobą, gdziekolwiek pójdziesz, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'A Jezus mu rzekł: Liszki mają jamy, i ptaszki niebieskie gniazda; ale Syn człowieczy nie ma, gdzie by głowę skłonił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'I rzekł do drugiego: Pójdź za mną! Ale on rzekł: Panie! dopuść mi pierwej odejść i pogrześć ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Ale mu Jezus rzekł: Niechaj umarli grzebią umarłych swoich; a ty poszedłszy, opowiadaj królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Rzekł też i drugi: Pójdę za tobą, Panie! ale mi pierwej dopuść pożegnać się z tymi, którzy są w domu moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Rzekł do niego Jezus: Żaden, który by przyłożył rękę swoję do pługa, a oglądałby się nazad, nie jest sposobny do królestwa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'A potem naznaczył Pan i drugich siedmdziesiąt, i rozesłał je po dwóch przed obliczem swojem do każdego miasta i miejsca, do którego przyjść miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'I mówił im: Żniwoć wprawdzie wielkie, ale robotników mało; proścież tedy Pana żniwa, aby wypchnął robotników na żniwo swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Idźcież: Oto ja was posyłam jako baranki wpośród wilków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Nie noścież mieszka, ani taistry, ani obuwia, i nikogo w drodze nie pozdrawiajcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'A do któregokolwiek domu wnijdziecie, naprzód mówcie: Pokój temu domowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'A jeźliby tam był który syn pokoju, odpocznie nad nim pokój wasz; a jeźliż nie, wróci się do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'A w tymże domu zostańcie, jedząc i pijąc to, co mają; albowiem godzien jest robotnik zapłaty swojej; nie przechodźcie się z domu do domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'A do któregokolwiek miasta weszlibyście, a przyjęliby was, jedzcie, co przed was położą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'I uzdrawiajcie niemocnych, którzy by w niem byli, a mówcie im: Przybliżyło się do was królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'A do któregobyściekolwiek miasta weszli, a nie przyjęto by was, wyszedłszy na ulice jego, mówcie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'I proch, który przylgnął do nas z miasta waszego, otrząsamy na was; wszakże to wiedzcie, że się do was przybliżyło królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'A mówię wam: Iż Sodomie w on dzień lżej będzie, niż onemu miastu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Biada tobie, Chorazynie! biada tobie, Betsaido! bo gdyby się były w Tyrze i w Sydonie te cuda stały, które się stały w was, dawno by były w worze i w popiele siedząc pokutowały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Dlatego Tyrowi i Sydonowi lżej będzie na sądzie, niżeli wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'A ty, Kapernaum! któreś aż do nieba wywyższone, aż do piekła strącone będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Kto was słucha, mnie słucha: a kto wami gardzi, mną gardzi; a kto mną gardzi, gardzi onym, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'A tak wrócili się oni siedmdziesiąt z weselem, mówiąc: Panie! i dyjablić się nam poddawają w imieniu twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Tedy im rzekł: Widziałem szatana, jako błyskawicę z nieba spadającego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Oto wam daję moc, abyście deptali po wężach i po niedźwiadkach i po wszystkiej mocy nieprzyjacielskiej, a nic wam nie uszkodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Wszakże nie radujcie się z tego, iż się wam duchy poddawają; ale raczej radujcie się, że imiona wasze napisane są w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'Onejże godziny rozradował się Jezus w duchu, i rzekł: Wysławiam cię, Ojcze, Panie nieba i ziemi! żeś te rzeczy zakrył przed mądrymi i roztropnymi, a objawiłeś je niemowlątkom; zaprawdę, Ojcze! że się tak upodobało tobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Wszystkie rzeczy dane mi są od Ojca mego, a nikt nie zna, kto jest Syn, tylko Ojciec, i kto jest Ojciec, tylko Syn, a komu by chciał Syn objawić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Tedy obróciwszy się do uczniów, rzekł im z osobna: Błogosławione oczy, które widzą, co wy widzicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Bo powiadam wam, iż wiele proroków i królów żądali widzieć, co wy widzicie, ale nie widzieli; i słyszeć, co wy słyszycie, ale nie słyszeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'A oto niektóry zakonnik powstał, kusząc go i mówiąc: Nauczycielu! co czyniąc odziedziczę żywot wieczny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'A on rzekł do niego: W zakonie co napisano, jako czytasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'A on odpowiadając rzekł: Będziesz miłował Pana, Boga twego, ze wszystkiego serca twego, i ze wszystkiej duszy twojej, i ze wszystkiej siły twojej, i ze wszystkiej myśli twojej; a bliźniego twego, jako samego siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'I rzekł mu: Dobrześ odpowiedział; to czyń, a będziesz żył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'A on chcąc samego siebie usprawiedliwić, rzekł do Jezusa: I któż jest mi bliźni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Ale Jezus odpowiadając rzekł: Człowiek niektóry zstępował z Jeruzalemu do Jerycha, i wpadł między zbójców, którzy złupiwszy go i rany mu zadawszy, odeszli, na pół umarłego zostawiwszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'I przydało się, że kapłan niektóry szedł tą drogą, a ujrzawszy go, pominął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Także i Lewita, dostawszy się na ono miejsce, a przyszedłszy i ujrzawszy go, pominął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Ale Samarytanin niektóry jadąc, przyjechał do niego, a ujrzawszy, użalił się go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'A przystąpiwszy zawiązał rany jego, a nalawszy oliwy i wina, i włożywszy go na bydlę swoje, wiódł go do gospody, i miał staranie o nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'A nazajutrz odjeżdżając, wyjął dwa grosze, i dał gospodarzowi, mówiąc: Miej o nim staranie, a cokolwiek nadto wyłożysz, ja, gdy się wrócę, oddam ci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Któryż tedy z tych trzech zda się tobie bliźnim być onemu, co był wpadł między zbójców?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'A on rzekł: Ten, który uczynił miłosierdzie nad nim. Rzekł mu tedy Jezus: Idźże, i ty uczyń także.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'I stało się, gdy oni szli, że on wszedł do niektórego miasteczka, a niewiasta niektóra, imieniem Marta, przyjęła go do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'A ta miała siostrę, którą zwano Maryją, która usiadłszy u nóg Jezusowych, słuchała słów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Ale Marta roztargniona była około rozmaitej posługi; która przystąpiwszy, rzekła: Panie! i nie dbasz, że siostra moja mnie samą zostawiła, abym posługiwała? Rzeczże jej, aby mi pomogła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'A odpowiadając Jezus rzekł jej: Marto, Marto! troszczysz się i kłopoczesz się około wielu rzeczy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Aleć jednego potrzeba. Lecz Maryja dobrą cząstkę obrała, która od niej odjęta nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'I stało się, gdy on był na niektórem miejscu, modląc się, że gdy przestał, rzekł do niego jeden z uczniów jego, Panie! naucz nas modlić się, tak jako i Jan nauczył uczniów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'I rzekł im: Gdy się modlicie, mówcie: Ojcze nasz, któryś jest w niebiesiech! Święć się imię twoje; przyjdź królestwo twoje; bądź wola twoja, jako w niebie tak i na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Chleba naszego powszedniego daj nam na każdy dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'I odpuść nam grzechy nasze; bo też i my odpuszczamy każdemu winowajcy naszemu. A nie wwódź nas na pokuszenie, ale nas zbaw od złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Zatem rzekł do nich: Któż z was mieć będzie przyjaciela, i pójdzie do niego o północy i rzecze mu: Przyjacielu! pożycz mi trzech chlebów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Albowiem przyjaciel mój przyszedł z drogi do mnie, a nie mam, co przed niego położyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'A on będąc w domu, odpowiedziałby mówiąc: Nie uprzykrzaj mi się; już są drzwi zamknięte, a dziatki moje są ze mną w pokoju; nie mogę wstać, abym ci dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Powiadam wam: Chociażby mu nie dał wstawszy, przeto że jest przyjacielem jego, wszakże dla niewstydliwego nalegania jego wstawszy, da mu, ile potrzebuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'I jać wam powiadam: Proście, a będzie wam dano; szukajcie, a znajdziecie; kołaczcie, a będzie wam otworzono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Każdy bowiem, kto prosi, bierze, a kto szuka, znajduje, a temu, co kołacze, będzie otworzono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'A któryż jest z was ojciec, którego gdyby prosił syn o chleb, izali mu da kamień? Albo prosiłby o rybę, izali mu zamiast ryby da węża?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Albo prosiłliby o jaje, izali mu da niedźwiadka?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Ponieważ tedy wy, będąc złymi, umiecie dobre dary dawać dzieciom waszym: jakoż daleko więcej Ojciec wasz niebieski da Ducha Świętego tym, którzy go oń proszą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Tedy wyganiał dyjabła, który był niemy. I stało się, gdy wyszedł on dyjabeł, przemówił niemy; i dziwował się lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Ale niektórzy z nich mówili: Przez Beelzebuba, książęcia dyjabelskiego, wygania dyjabły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Drudzy zasię kusząc go, żądali znamienia od niego z nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Ale on widząc myśli ich, rzekł im: Każde królestwo rozdzielone samo przeciwko sobie pustoszeje, a dom na dom upada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'A jeźliżeć i szatan rozdzielony jest przeciwko sobie, jakoż się ostoi królestwo jego? albowiem powiadacie, iż ja przez Beelzebuba wyganiam dyjabły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'A jeźliż ja przez Beelzebuba wyganiam dyjabły, synowie wasi przez kogoż wyganiają? Przetoż oni będą sędziami waszymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Ale jeźliż ja palcem Bożym wyganiam dyjabły, zaisteć przyszło do was królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Gdy mocarz uzbrojony strzeże pałacu swego, w pokoju są majętności jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Ale gdy mocniejszy nadeń nadszedłszy, zwycięży go, odejmuje wszystko oręże jego, w którem ufał, a łupy jego rozdaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Kto nie jest ze mną, przeciwko mnie jest; a kto nie zbiera ze mną, rozprasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Gdy duch nieczysty wychodzi od człowieka, przechadza się po miejscach suchych, szukając odpocznienia, a nie znalazłszy, mówi: Wrócę się do domu mego, skądem wyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'A przyszedłszy znajduje umieciony i ochędożony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Tedy idzie i bierze z sobą siedm innych duchów gorszych niżeli sam, a wszedłszy mieszkają tam, i bywają rzeczy ostatnie człowieka onego gorsze, niżeli pierwsze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'I stało się, gdy on to mówił, że wyniósłszy głos niektóra niewiasta z ludu, rzekła mu: Błogosławiony żywot, który cię nosił, i piersi, któreś ssał!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Ale on rzekł: Owszem błogosławieni są, którzy słuchają słowa Bożego i strzegą go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'A gdy się lud gromadził, począł mówić: Rodzaj ten rodzaj zły jest; znamienia szuka, ale mu znamię nie będzie dane, tylko ono znamię Jonasza proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Albowiem jako Jonasz był za znamię Niniwczykom, tak będzie i Syn człowieczy temu rodzajowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Królowa z południa stanie na sądzie z mężami rodzaju tego, i potępi je; bo przyjechała od kończyn ziemi, aby słuchała mądrości Salomonowej; a oto tu więcej, niżeli Salomon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Mężowie Niniwiccy staną na sądzie z tym rodzajem i potępią go, przeto że pokutowali na kazanie Jonaszowe; a oto tu więcej, niżeli Jonasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'A nikt świecę zapaliwszy, nie stawia jej w skrytości, ani pod korzec, ale na świecznik, aby ci, którzy wchodzą, światło widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Świecą ciała jest oko; jeźliby tedy oko twoje było szczere, i ciało twoje wszystko będzie jasne; a jeźliby złe było, i ciało twoje ciemne będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Patrzajże tedy, aby światło, które jest w tobie, nie było ciemnością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Jeźli tedy wszystko ciało twoje jasne będzie, nie mając jakiej cząstki zaćmionej, będzieć wszystko tak jasne, że cię jako świeca blaskiem oświeci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'A gdy to mówił, prosił go niektóry Faryzeusz, aby jadł obiad u niego; wszedłszy tedy, usiadł za stołem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'A widząc to Faryzeusz, dziwował się, że się nie umył przed obiadem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'I rzekł Pan do niego: Teraz wy, Faryzeuszowie! to, co jest zewnątrz kubka i misy, ochędażacie, ale to, co jest wewnątrz w was, pełne jest drapiestwa i złości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Szaleni! izaż ten, który uczynił to, co jest zewnątrz, nie uczynił też tego, co jest wewnątrz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Wszakże i z tego, co jest wewnątrz, dawajcie jałmużnę, a oto wszystkie rzeczy będą wam czyste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Ale biada wam, Faryzeuszowie! że dajecie dziesięcinę z mięty, i z ruty, i z każdego ziela, lecz opuszczacie sąd i miłość Bożą: teć rzeczy trzeba czynić, a onych nie opuszczać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Biada wam Faryzeuszowie! że miłujecie pierwsze miejsca w bóżnicach i pozdrawiania na rynkach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Biada wam, nauczeni w Piśmie i Faryzeuszowie obłudni! bo jesteście jako groby, których nie widać, a ludzie, którzy chodzą po nich, nie wiedzą o nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'A odpowiadając niektóry z zakonników, rzekł mu: Nauczycielu! to mówiąc i nas hańbisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'A on rzekł: I wam zakonnikom biada! albowiem obciążacie ludzi brzemiony nieznośnemi, a sami się i jednym palcem swoim tych brzemion nie dotykacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Biada wam! że budujecie groby proroków, a ojcowie wasi pozabijali je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Zaiste świadczycie, iż się kochacie w uczynkach ojców waszych; albowiem oni je pozabijali, a wy budujecie groby ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Dlategoż też mądrość Boża rzekła: Poślę do nich proroki i Apostoły, a z nich niektóre zabijać i prześladować będą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'Aby szukano od tego rodzaju krwi wszystkich proroków, która wylana jest od założenia świata,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'Od krwi Abla aż do krwi Zacharyjasza, który zginął między ołtarzem, i kościołem; zaiste powiadam wam, będą jej szukać od rodzaju tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Biada wam zakonnikom! boście wzięli klucz umiejętności; samiście nie weszli, a tym, którzy wnijść chcieli, zabranialiście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'A gdy im to mówił, poczęli nań nauczeni w Piśmie i Faryzeuszowie bardzo nacierać, i przyczynę mu dawać do mówienia o wielu rzeczach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'Czyhając nań i szukając, aby co uchwycili z ust jego, żeby go oskarżyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Między tem, gdy się zgromadziło wiele tysięcy ludu, tak iż jedni po drugich deptali, począł mówić do uczniów swoich. Naprzód strzeżcie się kwasu Faryzejskiego, który jest obłuda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Boć nie jest nic skrytego, co by objawione być nie miało, ani tajemnego czego by się dowiedzieć nie miano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Przetoż, coście mówili w ciemności, na świetle słyszane będzie, a coście w ucho szeptali w komorach, obwołane będzie na dachach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'A mówię wam przyjaciołom moim: Nie bójcie się tych, którzy ciało zabijają, a potem nie mają co by więcej uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Ale wam okażę, kogo się bać macie: Bójcie się tego, który, gdy zabije, ma moc wrzucić do piekielnego ognia; zaiste powiadam wam, tego się bójcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Izali pięciu wróblików nie sprzedają za dwa pieniążki? Wszakże jeden z nich nie jest w zapamiętaniu przed obliczem Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Owszem i włosy głowy waszej wszystkie są policzone. Przetoż się nie bójcie, nad wiele wróblików wy jesteście zacniejsi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'A mówię wam: Wszelaki, który by mię wyznał przed ludźmi, i Syn człowieczy wyzna go przed Anioły Bożymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Ale kto by się mię zaprzał przed ludźmi, zaprę się go przed Anioły Bożymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'I każdemu, kto by mówił słowo przeciwko Synowi człowieczemu, będzie mu odpuszczone: ale temu, kto by przeciwko Duchowi Świętemu bluźnił, nie będzie odpuszczone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'A gdy was będą wodzić do bóżnic, i do przełożonych, i do zwierzchności, nie troszczcie się, jako i co byście ku obronie odpowiedzieć, albo co byście mówić mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Albowiem Duch Święty nauczy was onejże godziny, co byście mówić mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'I rzekł mu niektóry z ludu: Nauczycielu! rzecz bratu memu, aby się ze mną podzielił dziedzictwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Ale mu on rzekł: Człowiecze! któż mię postanowił sędzią albo dzielcą między wami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'I rzekł do nich: Patrzcie, a strzeżcie się łakomstwa, gdyż nie w tem, że kto ma obfite majętności, żywot jego zależy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'I powiedział im podobieństwo, mówiąc: Niektórego człowieka bogatego pole obfity urodzaj przyniosło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'I rozmyślał sam w sobie, mówiąc: Cóż uczynię, gdyż nie mam, gdzie bym zgromadził urodzaje moje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'I rzekł: To uczynię: Rozwalę gumna moje, a większe pobuduję i zgromadzę tam wszystkie urodzaje moje i dobra moje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'I rzekę do duszy mojej: Duszo! masz wiele dóbr złożonych na wiele lat; odpocznijże, jedz, pij, bądź dobrej myśli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Ale mu rzekł Bóg: O głupi, tej nocy upomnę się duszy twojej od ciebie, a to, coś nagotował, czyjeż będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Takci jest, który sobie skarbi, a nie jest w Bogu bogaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'I rzekł do uczniów swoich: Dlatego powiadam wam, nie troszczcie się o żywot wasz, co byście jedli, ani o ciało, czem byście się przyodziewali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Zacniejszy jest żywot, niż pokarm, a ciało, niż odzienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Przypatrzcie się krukom, iż nie sieją ani żną, i nie mają spiżarni, ani gumna, a wżdy je Bóg żywi; czemżeście wy zacniejsi niż ptacy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'I któż z was troskliwie myśląc, może przydać do wzrostu swego łokieć jeden?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Ponieważ tedy i najmniejszej rzeczy nie przemożecie, czemuż się o inne troszczycie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Przypatrzcie się lilijom, jako rosną, nie pracują, ani przędą; a powiadam wam, że ani Salomon we wszystkiej sławie swojej nie był tak przyodziany, jako jedna z tych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'A jeźliże trawę, która dziś jest na polu, a jutro będzie w piec wrzucona, Bóg tak przyodziewa, jakoż daleko więcej was, o małowierni!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Wy tedy nie pytajcie się, co byście jeść, albo co byście pić mieli, ani wysoko latajcie myślami waszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Albowiem tego wszystkiego narody świata szukają; aleć Ojciec wasz wie, że tego potrzebujecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Owszem szukajcie królestwa Bożego, a to wszystko będzie wam przydane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Nie bój się, o maluczkie stadko! albowiem się upodobało Ojcu waszemu, dać wam królestwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Sprzedawajcie majętności wasze, a dawajcie jałmużnę; gotujcie sobie mieszki, które nie wiotszeją, skarb, którego nie ubywa w niebiesiech, gdzie złodziej przystępu nie ma, ani mól psuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Bo gdzie jest skarb wasz, tam będzie i serce wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Niech będą przepasane biodra wasze, i świece zapalone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'A wy bądźcie podobni ludziom oczekującym pana swego, ażeby się wrócił z wesela, żeby gdyby przyszedł, a zakołatał, wnet mu otworzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Błogosławieni oni słudzy, których gdy przyjdzie pan, czujących znajdzie; zaprawdę powiadam wam, iż się przepasze, a posadzi ich za stół, a przechadzając się, będzie im służył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'A jeźliby przyszedł o wtórej straży, i o trzeciej straży przyszedłliby, a tak by ich znalazł, błogosławieni są oni słudzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'A to wiedzcie, iżby gdyby wiedział gospodarz, o której godzinie złodziej ma przyjść, wżdyby czuł, a nie dopuściłby podkopać domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Przetoż i wy bądźcie gotowi; bo o tej godzinie, o której się nie spodziewacie, Syn człowieczy przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'I rzekł mu Piotr: Panie! do nasże mówisz to podobieństwo, czyli do wszystkich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'A Pan rzekł: Któryż tedy jest wierny szafarz i roztropny, którego Pan postanowi nad czeladzią swoją, aby im na czas wydawał obrok naznaczony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Błogosławiony jest on sługa, którego gdyby przyszedł pan jego, znajdzie, że tak czyni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Zaprawdę wam powiadam, że go nad wszystkiemi dobrami swojemi postanowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Ale jeźliby rzekł on sługa w sercu swojem: Odwłacza pan mój z przyjściem swojem, i począłby bić sługi i służebnice, a jeść, pić i opijać się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'Przyjdzie pan sługi onego dnia, którego się nie spodzieje, i godziny, której nie wie, i odłączy go, a część jego położy z niewiernymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Ten zasię sługa, który by znał wolę pana swego, a nie był gotowym, ani czynił według woli jego, wielce będzie karany;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Ale który nie znał, a czynił rzeczy godne karania, mniej plag odniesie; a od każdego, komu wiele dano, wiele się od niego upominać będą: a komu wiele powierzono, więcej będą chcieć od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Przyszedłem, abym ogień puścił na ziemię, i czegoż chcę, jeźli już gore?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Aleć mam być chrztem ochrzczony; a jakom jest ściśniony, póki się to nie wykona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Mniemacie, abym przyszedł, pokój dawać na ziemię? Bynajmniej, powiadam wam, ale rozerwanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Albowiem od tego czasu będzie ich pięć w domu jednym rozerwanych, trzej przeciwko dwom, a dwaj przeciwko trzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Powstanie ojciec przeciwko synowi, a syn przeciwko ojcu, matka przeciwko córce, a córka przeciwko matce, świekra przeciwko synowej swojej, a synowa przeciwko świekrze swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Mówił też i do ludu: Gdy widzicie obłok wschodzący od zachodu, zaraz mówicie: Przychodzi gwałtowny deszcz; i tak bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'A gdy wiatr wiejący od południa, mówicie: Gorąco będzie; i bywa tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Obłudnicy! postawę nieba i ziemi rozeznawać umiecie, a tego czasu jakoż nie poznawacie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Przeczże i sami przez się nie sądzicie, co jest sprawiedliwego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Gdy tedy idziesz z przeciwnikiem swoim przed urząd, starajże się w drodze, abyś był wolen, by cię snać nie pociągnął przed sędziego, a sędzia by cię podał ceklarzowi, a ceklarz by cię wrzucił do więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Powiadam ci: Nie wynijdziesz stamtąd, póki byś nie oddał do ostatniego pieniążka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'A prawie natenczas byli przytomni niektórzy, oznajmując mu o Galilejczykach, których krew Piłat pomieszał z ofiarami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'A Jezus odpowiadając, rzekł im: Mniemacie, że ci Galilejczycy nad wszystkie inne Galilejczyki grzeszniejszymi byli, iż takowe rzeczy ucierpieli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Bynajmniej, mówię wam: i owszem, jeźli nie będziecie pokutować, wszyscy także poginiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Albo ośmnaście onych, na które upadła wieża w Syloe i pobiła je, mniemacie żeby ci winniejszymi byli nad wszystkie ludzie mieszkające w Jeruzalemie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Bynajmniej, mówię wam: i owszem, jeźli pokutować nie będziecie, wszyscy także poginiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'I powiedział im to podobieństwo: Człowiek niektóry miał figowe drzewo wsadzone na winnicy swojej, a przyszedłszy, szukał na niem owocu, ale nie znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Tedy rzekł do winiarza: Oto po trzy lata przychodzę, szukając owocu na tem drzewie figowem, ale nie znajduję. Wytnijże je; bo przeczże tę ziemię próżno zastępuje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Ale on odpowiadając rzekł mu: Panie! zaniechaj go jeszcze i na ten rok, aż je okopię i obłożę gnojem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Owa snać przyniesie owoc, a jeźli nie, potem je wytniesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'I nauczał w jednej bóżnicy w sabat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'A oto była tam niewiasta, która miała ducha niemocy ośmnaście lat, a była skurczona, tak iż się żadną miarą nie mogła rozprostować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Tę gdy ujrzał Jezus, zawołał jej do siebie i rzekł: Niewiasto! uwolnionaś od niemocy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'I włożył na nią ręce, a zarazem rozprostowała się i chwaliła Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Tedy odpowiadając przełożony nad bóżnicą, który się bardzo gniewał, że Jezus w sabat uzdrawiał, rzekł do ludu: Sześć dni jest, w które trzeba robić; w te tedy dni przychodząc, leczcie się, a nie w dzień sabatu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Ale mu odpowiedział Pan i rzekł: Obłudniku, azaż każdy z was w sabat nie odwiązuje wołu swego, albo osła swego od żłobu, a nie wiedzie, żeby go napoił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'A ta córka Abrahamowa, którą był związał szatan oto już ośmnaście lat, zaż nie miała być rozwiązana od tej związki w dzień sabatu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'A gdy on to mówił, zawstydzili się wszyscy przeciwnicy jego: ale wszystek lud radował się ze wszystkich onych chwalebnych spraw, które się działy od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Zatem rzekł Jezus: Komuż podobne jest królestwo Boże, a do czegoż je przypodobam?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Podobne jest ziarnu gorczycznemu, które wziąwszy człowiek, wrzucił do ogrodu swego; i rosło i stało się drzewem wielkiem, a ptaszki niebieskie czyniły sobie gniazda na gałęziach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'I rzekł znowu: Do czegoż przypodobam królestwo Boże?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Podobne jest kwasowi, który wziąwszy niewiasta, zakryła go we trzy miary mąki, ażby wszystko skwaśniało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'I chodził po miastach i miasteczkach, nauczając a idąc w drogę do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'I rzekł mu niektóry: Panie! czyli mało tych jest, którzy mają być zbawieni? A on rzekł do nich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Usiłujcie, abyście weszli przez ciasną bramę; albowiem powiadam wam: Wiele ich będą chcieli wnijść, ale nie będą mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Gdy wstanie gospodarz i zamknie drzwi, a poczniecie stać przede drzwiami, i kołatać we drzwi, mówiąc: Panie, Panie! otwórz nam, tedy on odpowiadając rzecze wam: Nie znam was, skąd jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Tedy poczniecie mówić: Jadaliśmy przed tobą i pijali, i uczyłeś na ulicach naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'A on rzecze: Powiadam wam, nie znam was, skąd jesteście; odstąpcie ode mnie wszyscy, którzy czynicie nieprawość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Tam będzie płacz i zgrzytanie zębów, gdy ujrzycie Abrahama, Izaaka, i Jakóba, i wszystkie proroki w królestwie Bożem, a samych siebie precz wyrzuconych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'I przyjdą drudzy od wschodu i od zachodu, i od północy, i od południa, a usiądą za stołem w królestwie Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'A oto są ostatni, którzy będą pierwszymi, a są pierwsi, którzy będą ostatnimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'W onże dzień przystąpili niektórzy z Faryzeuszów, mówiąc mu: Wynijdź, a idź stąd; bo cię Herod chce zabić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'I rzekł im: Idźcie, a powiedzcie temu lisowi: Oto wyganiam dyjabły, i uzdrawiam dziś i jutro, a trzeciego dnia dokończenie wezmę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Wszakże muszę dziś i jutro i pojutrze odprawiać drogę: albowiem nie może być, aby miał prorok zginąć, oprócz w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jeruzalem! Jeruzalem! które zabijasz proroki, a kamionujesz te, którzy do ciebie bywają posłani; ilekroć chciałem zgromadzić dzieci twoje, tak jako kokosz zgromadza kurczęta swoje pod skrzydła, a nie chcieliście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Otoż zostanie wam dom wasz pusty. A zaprawdęć wam powiadam, że mię nie ujrzycie, aż przyjdzie czas, gdy rzeczecie: Błogosławiony, który idzie w imieniu Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'I stało się, gdy wszedł Jezus w dom niektórego przedniejszego Faryzeusza w sabat, aby jadł chleb, że go oni podstrzegali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'A oto człowiek niektóry opuchły był przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'A odpowiadając Jezus, rzekł do zakonników, i do Faryzeuszów, mówiąc: Godzili się w sabat uzdrawiać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'A oni milczeli. Tedy on ująwszy go, uzdrowił i odprawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'A odpowiadając rzekł do nich: Któregoż z was osieł albo wół wpadnie w studnię, a nie wnet go wyciągnie w dzień sabatu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'I nie mogli mu na to odpowiedzieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Powiedział też i wezwanym podobieństwo, (bacząc, jako przedniejsze miejsca obierali,) mówiąc do nich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Gdybyś był od kogo wezwany na wesele, nie siadajże na przedniejszem miejscu, by snać zacniejszy nad cię nie był wezwany od niego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'A przyszedłszy ten, który ciebie i onego wezwał, rzekłby tobie: Daj temu miejsce: a tedy byś ze wstydem począł siedzieć na pośledniem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Ale gdybyś był wezwany, szedłszy, usiądź na pośledniem miejscu; a gdyby przyszedł ten, który cię wezwał, rzekłby tobie: Przyjacielu! posiądź się wyżej; tedy będziesz miał cześć przed spółsiedzącymi z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Bo wszelki, kto się wywyższa, poniżony będzie, a kto się poniża, wywyższony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Mówił też i onemu, który go był wezwał: Gdy sprawujesz obiad albo wieczerzę, nie wzywajże przyjaciół twoich, ani braci twoich, ani krewnych twoich, ani sąsiadów bogatych, żeby cię snać i oni zasię nie wezwali, a stałaby ci się nagroda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Ale gdy sprawujesz ucztę, wezwijże ubogich, ułomnych, chromych i ślepych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'A będziesz błogosławionym; bo nie mają tobie czem nagrodzić, ale ci będzie nagrodzono przy zmartwychwstaniu sprawiedliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'A usłyszawszy to niektóry z spółsiedzących, rzekł mu: Błogosławiony, który je chleb w królestwie Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'A on mu rzekł: Człowiek niektóry sprawił wieczerzę wielką i zaprosił wielu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'I posłał sługę swego w godzinę wieczerzy, żeby rzekł zaproszonym: Pójdźcie! bo już wszystko gotowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'I poczęli się wszyscy jednostajnie wymawiać. Pierwszy mu rzekł: Kupiłem wieś, i muszę iść, a oglądać ją, proszę cię, miej mię za wymówionego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'A drugi rzekł: Kupiłem pięć jarzm wołów, i idę, abym ich doświadczył: proszę cię, miej mię za wymówionego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'A drugi rzekł: Żonęm pojął, a dlatego przyjść nie mogę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'A wróciwszy się on sługa, oznajmił to panu swemu. Tedy się gospodarz rozgniewawszy, rzekł słudze swemu: Wynijdź prędko na ulice i na drogi miejskie, a ubogie i ułomne i chrome i ślepe wprowadź tu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'I rzekł sługa: Panie! stało się, jakoś rozkazał, a jeszcze miejsce jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'I rzekł Pan do sługi: Wynijdź na drogi i między opłotki, a przymuś wnijść, aby był napełniony dom mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Albowiem powiadam wam, że żaden z onych mężów, którzy byli zaproszeni, nie ukusi wieczerzy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'I szedł z nim wielki lud; a obróciwszy się, rzekł do nich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Jeźli kto idzie do mnie, a nie ma w nienawiści ojca swego, i matki, i żony, i dzieci, i braci, i sióstr, nawet i duszy swojej, nie może być uczniem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'A ktokolwiek nie niesie krzyża swego, a idzie za mną, nie może być uczniem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Bo któż z was jest, chcąc zbudować wieżę, aby pierwej usiadłszy, nie obrachował nakładu, mali to, czemby jej dokończył?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Aby snać, gdyby założył fundament, a dokończyć nie mógł, wszyscy którzy by to widzieli, nie poczęli się naśmiewać z niego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'Mówiąc: Ten człowiek począł budować, a nie mógł dokończyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Albo który król jadąc na wojnę, potykać się z drugim królem, pierwej usiadłszy, nie radzi się, mógłliby się w dziesięć tysięcy spotkać z onym, który we dwadzieścia tysięcy jedzie przeciwko niemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'A jeźli nie, gdy on jeszcze jest daleko od niego, posły wyprawiwszy do niego, prosi o to, co należy do pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Takżeć i każdy z was, kto by się nie wyrzekł wszystkich majętności swoich, nie może być uczniem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Dobrać jest sól; lecz jeźli sól zwietrzeje, czemże ją naprawią?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Nie przygodzi się ani do ziemi ani do gnoju, ale ją precz wyrzucają. Kto ma uszy ku słuchaniu, niechaj słucha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'I przybliżali się do niego wszyscy celnicy i grzesznicy, aby go słuchali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'I szemrali Faryzeuszowie i nauczeni w Piśmie, mówiąc: Ten grzeszniki przyjmuje i je z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'I powiedział im to podobieństwo, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Któryż z was człowiek, gdyby miał sto owiec, a straciłby jednę z nich, izali nie zostawia onych dziewięćdziesięciu i dziewięciu na puszczy, a nie idzie za oną, która zginęła, ażby ją znalazł?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'A znalazłszy kładzie ją na ramiona swoje, radując się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'A przyszedłszy do domu, zwołuje przyjaciół, i sąsiadów, mówiąc im: Radujcie się ze mną; bom znalazł owcę, która była zginęła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Powiadam wam, że taka będzie radość w niebie nad jednym grzesznikiem pokutującym, więcej niż nad dziewięćdziesiąt i dziewięciu sprawiedliwych, którzy nie potrzebują pokuty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Albo która niewiasta mając dziesięć groszy, jeźliby straciła grosz jeden, izali nie zapala świecy, i nie umiata domu, a nie szuka z pilnością, ażby znalazła?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'A znalazłszy, zwołuje przyjaciółek i sąsiadek, mówiąc: Radujcie się ze mną; albowiem znalazłam grosz, którym była straciła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Tak, powiadam wam, będzie radość przed Anioły Bożymi nad jednym grzesznikiem pokutującym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Nadto rzekł: Człowiek niektóry miał dwóch synów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'I rzekł młodszy z nich ojcu: Ojcze! daj mi dział majętności na mię przypadający. I rozdzielił im majętność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'A po niewielu dniach, zebrawszy wszystko on młodszy syn, odjechał w daleką krainę, i rozproszył tam majętność swoję, żyjąc rozpustnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'A gdy wszystko potracił, stał się głód wielki w onej krainie, a on począł niedostatek cierpieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'A tak szedłszy, przystał do jednego mieszczanina onej krainy, który go posłał do folwarku swego, aby pasł świnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'I żądał napełnić brzuch swój młótem, które jadały świnie; ale mu nikt nie dawał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Potem przyszedłszy do siebie, rzekł: O jako wiele najemników ojca mego mają dosyć chleba, a ja od głodu ginę!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Wstawszy tedy, pójdę do ojca mego i rzekę mu: Ojcze! zgrzeszyłem przeciwko niebu i przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'I nie jestem godzien więcej być nazywany synem twoim, uczyń mię jako jednego z najemników twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Tedy wstawszy, szedł do ojca swego. A gdy on jeszcze był opodal, ujrzał go ojciec jego, i użaliwszy się go, przybieżał, a padłszy na szyję jego, pocałował go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'I rzekł mu syn: Ojcze! zgrzeszyłem przeciwko niebu i przed tobą, i jużem nie jest godzien, abym był nazywany synem twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Rzekł tedy ojciec do sług swoich: Przynieście onę przednią szatę, a obleczcie go, i dajcie pierścień na rękę jego, i obuwie na nogi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'A przywiódłszy ono tłuste cielę, zabijcie, a jedząc bądźmy weseli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Albowiem ten syn mój umarł był, a zasię ożył; zginął był, i znaleziony jest; i poczęli się weselić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Ale starszy syn jego był na polu; a gdy przychodząc przybliżył się ku domowi, usłyszał muzykę i tańce;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'A zawoławszy jednego z sług, pytał, co by to było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'A on mu powiedział: Brat twój przyszedł, i zabił ojciec twój ono tłuste cielę, iż go zdrowego dostał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'I rozgniewał się, a nie chciał wnijść; ale ojciec jego wyszedłszy prosił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'A on odpowiadając, rzekł ojcu: Oto przez tak wiele lat służę tobie, a nigdym nie przestąpił przykazania twego; wszakżeś mi nigdy nie dał koźlęcia, abym się z przyjacioły moimi weselił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Ale gdy ten syn twój, który pożarł majętność twoję z wszetecznicami, przyszedł, zabiłeś mu ono tłuste cielę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'A on mu rzekł; Synu! tyś zawsze ze mną, a wszystkie dobra moje twoje są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Lecz trzeba było weselić się i radować, że ten brat twój umarł był, a zasię ożył, i zginął był a znaleziony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Mówił też i do uczniów swoich: Człowiek niektóry był bogaty, który miał szafarza, a ten był odniesiony do niego, jakoby rozpraszał dobra jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'A zawoławszy go, rzekł mu: Cóż słyszę o tobie? Oddaj liczbę z szafarstwa twego; albowiem już więcej nie będziesz mógł szafować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'I rzekł on szafarz sam w sobie: Cóż uczynię, gdyż pan mój odbiera ode mnie szafarstwo? Kopać nie mogę, żebrać się wstydzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Wiem, co uczynię, że gdy będę złożony z szafarstwa, przyjmą mię do domów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Zawoławszy tedy do siebie każdego z dłużników pana swego rzekł pierwszemu: Wieleś winien panu memu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'A on rzekł: Sto bareł oliwy. I rzekł mu: Weźmij zapis twój, a siadłszy prędko, napisz pięćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Potem drugiemu rzekł: A tyś wiele winien? A on mu rzekł: Sto korcy pszenicy. I rzekł mu: Weźmij zapis twój, a napisz ośmdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'I pochwalił pan szafarza niesprawiedliwego, iż roztropnie uczynił; bo synowie tego świata roztropniejsi są nad syny światłości w rodzaju swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'I jać wam powiadam: Czyńcie sobie przyjacioły z mammony niesprawiedliwości, aby gdy ustaniecie, przyjęli was do wiecznych przybytków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Kto wierny jest w małem, i w wielu wiernym jest; a kto w małem niesprawiedliwy, i w wielu niesprawiedliwym jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Ponieważeście tedy w mammonie niesprawiedliwej wiernymi nie byli, prawdziwego któż wam powierzy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'A jeźliście w cudzem wiernymi nie byli, któż wam da, co waszego jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Żaden sługa nie może dwom panom służyć, gdyż albo jednego będzie miał w nienawiści, a drugiego będzie miłował; albo się jednego trzymać będzie, a drugim pogardzi; nie możecie Bogu służyć i mammonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'A słuchali tego wszystkiego i Faryzeuszowie, którzy byli łakomi, i naśmiewali się z niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'I rzekł im: Wy jesteście, którzy sami siebie usprawiedliwiacie przed ludźmi, ale Bóg zna serca wasze; bo co jest u ludzi wyniosłego, obrzydliwością jest przed Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Zakon i prorocy aż do Jana; a od tego czasu królestwo Boże opowiadane bywa, a każdy się do niego gwałtem ciśnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'I łatwiej jest niebu i ziemi przeminąć, niżeli jednej kresce zakonu upaść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Wszelki, który opuszcza żonę swoję, a inną pojmuje, cudzołoży; a kto od męża opuszczoną pojmuje, cudzołoży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'A był niektóry człowiek bogaty, który się obłóczył w szarłat i w bisior, i używał na każdy dzień hojnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Był też niektóry żebrak, imieniem Łazarz, który leżał u wrót jego owrzodziały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Pragnąc być nasycony z odrobin, które padały z stołu bogaczowego; ale i psy przychodząc lizały wrzody jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'I stało się, że umarł on żebrak, i odniesiony był od Aniołów na łono Abrahamowe; umarł też i bogacz, i pogrzebiony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'A będąc w piekle, podniósłszy oczy swe, gdy był w mękach, ujrzał Abrahama z daleka, i Łazarza na łonie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Tedy bogacz zawoławszy, rzekł: Ojcze Abrahamie! zmiłuj się nade mną, a poślij Łazarza, aby omoczył koniec palca swego w wodzie, a ochłodził język mój, bo męki cierpię w tym płomieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'I rzekł Abraham: Synu! wspomnij, żeś ty odebrał dobre rzeczy twoje za żywota twego, a Łazarz także złe; a teraz on ma pociechę, a ty męki cierpisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'A nad to wszystko między nami i wami otchłań wielka jest utwierdzona, aby ci, którzy chcą stąd przyjść do was, nie mogli, ani owi stamtąd przyjść do nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'A on rzekł: Proszę cię tedy, ojcze! abyś posłał do domu ojca mego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Albowiem mam pięć braci, aby im świadectwo wydał, żeby też i oni nie przyszli na to miejsce męki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'I rzekł mu Abraham: Mająć Mojżesza i proroków, niechże ich słuchają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'A on rzekł: Nie, ojcze Abrahamie! ale gdyby kto z umarłych szedł do nich, będą pokutować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'I rzekł mu: Ponieważ Mojżesza i proroków nie słuchają, tedy, choćby też kto zmartwychwstał, nie uwierzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'I rzekł do uczniów: Nie można, aby zgorszenia przyjść nie miały; ale biada temu, przez którego przychodzą!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Lepiej by mu było, aby młyński kamień zawieszony był na szyi jego, i wrzucony był w morze, niżby jednego z tych małych zgorszyć miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Miejcież się na pieczy. A jeźliby zgrzeszył przeciwko tobie brat twój, strofuj go, a jeźliby się upamiętał, odpuść mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'A choćby siedmkroć na dzień zgrzeszył przeciwko tobie, i siedmkroć przez dzień się do ciebie nawrócił, mówiąc: Żal mi tego; odpuść mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'I rzekli Apostołowie Panu: Przymnóż nam wiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'A Pan rzekł: Jeźlibyście mieli wiarę jako ziarno gorczyczne, a rzeklibyście temu drzewu leśnej figi: Wyrwij się z korzenia, a wsadź się w morzu, usłuchałoby was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'I któż z was jest, co by miał sługę orzącego albo pasącego, który gdyby się wrócił, zaraz by mu rzekł: Pójdź, a usiądź za stół?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'I owszem, izali mu nie rzecze: Nagotuj, co bym wieczerzał, a przepasawszy się, służ mi, aż się najem i napiję, a potem i ty jedz i pij?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Izali dziękuje słudze onemu, iż uczynił to, co mu było rozkazano? Nie zda mi się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Także i wy, gdy uczynicie wszystko, co wam rozkazano, mówcie: Słudzy nieużyteczni jesteśmy, bo cośmy byli powinni uczynić, uczyniliśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'I stało się, gdy szedł do Jeruzalemu, że szedł pośrodkiem Samaryi i Galilei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'A gdy wchodził do niektórego miasteczka, zabieżało mu dziesięć mężów trędowatych, którzy stanęli z daleka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'A ci podniósłszy głos swój, rzekli: Jezusie, Nauczycielu! zmiłuj się nad nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Które on ujrzawszy, rzekł im: Szedłszy okażcie się kapłanom. I stało się, gdy szli, że oczyszczeni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Ale jeden z nich ujrzawszy, że jest uzdrowiony, wrócił się, wielkim głosem chwaląc Boga;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'I padł na oblicze swoje u nóg jego, dziękując mu; a ten był Samarytanin.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'A Jezus odpowiadając, rzekł: Zaż nie dziesięć jest oczyszczonych, a dziewięć kędy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Nie znaleźli się, aby się wrócili, i dali chwałę Bogu, jedno ten cudzoziemiec?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'I rzekł mu: Wstań, idź, wiara twoja ciebie uzdrowiła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'A będąc pytany od Faryzeuszów, kiedy przyjdzie królestwo Boże, odpowiedział im i rzekł: Nie przyjdzieć królestwo Boże z postrzeżeniem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Ani rzeką: Oto tu, albo oto tam jest: albowiem oto królestwo Boże wewnątrz was jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'I rzekł do uczniów: Przyjdą dni, że będziecie żądać, abyście widzieli jeden dzień ze dni Syna człowieczego, ale nie oglądacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'I rzeką wam: Oto tu, albo oto tam jest; ale nie chodźcie, ani się za nimi udawajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Albowiem jako błyskawica, błyskając się od jednej strony, która jest pod niebem, aż do drugiej, która jest pod niebem, świeci: tak będzie i Syn człowieczy w dzień swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Ale pierwej musi wiele ucierpieć, i być odrzuconym od narodu tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'A jako było za dni Noego, tak będzie i za dni Syna człowieczego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Jedli, pili, żenili się i za mąż wydawali aż do onego dnia, którego wszedł Noe do korabia, i przyszedł potop, a wytracił wszystkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Także też jako się działo za dni Lotowych, jedli, pili, kupowali, sprzedawali, szczepili, budowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'Ale dnia tego, gdy wyszedł Lot z Sodomy, spadł jako deszcz ogień z siarką z nieba, i wytracił wszystkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Takci też będzie w on dzień, którego się Syn człowieczy objawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Onegoż dnia, byłliby kto na dachu, a naczynia jego w domu, niech nie zstępuje, aby je pobrał; a kto na roli, niech się także nie wraca do tego, co jest pozad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Pamiętajcie na żonę Lotową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Ktobykolwiek chciał zachować duszę swoję, straci ją; a kto by ją kolwiek stracił, ożywi ją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Powiadam wam: Onej nocy będą dwaj na jednem łożu; jeden wzięty będzie, a drugi zostawiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Dwie będą mleć z sobą; jedna wzięta będzie, a druga zostawiona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Dwaj będą na roli; jeden będzie wzięty, a drugi zostawiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'A odpowiadając rzekli mu: Gdzież Panie? A on im rzekł: Gdzie będzie ścierw, tam się zgromadzą i orły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'I powiedział im jeszcze podobieństwo do tego zmierzające, iż się zawsze potrzeba modlić, a nie ustawać,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Mówiąc: Był niektóry sędzia w jednem mieście, który się Boga nie bał, i człowieka się nie wstydził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Była też wdowa w temże mieście, która przychodziła do niego, mówiąc: Pomścij się krzywdy mojej nad przeciwnikiem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Lecz on długo nie chciał. Ale potem rzekł sam w sobie: Aczci się Boga nie boję i człowieka się nie wstydzę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'Wszakże iż mi się uprzykrza ta wdowa, pomszczę się krzywdy jej, aby na ostatek przyszedłszy, nie była mi ciężką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Rzekł tedy Pan: Słuchajcież, co mówi niesprawiedliwy sędzia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'A Bóg izali się nie pomści krzywdy wybranych swoich, wołających do siebie we dnie i w nocy, chociaż im długo cierpi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Powiadam wam, iż się pomści krzywdy ich w rychle. Ale gdy przyjdzie Syn człowieczy, izali znajdzie wiarę na ziemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Rzekł też i do niektórych, którzy ufali sami w sobie, że byli sprawiedliwymi, a inszych za nic nie mieli, to podobieństwo:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Dwoje ludzi wstąpiło do kościoła, aby się modlili, jeden Faryzeusz a drugi celnik.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Faryzeusz stanąwszy, tak się sam u siebie modlił: Dziękuję tobie, Boże! żem nie jest jako inni ludzie, drapieżni, niesprawiedliwi, cudzołożnicy, albo jako i ten celnik.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Poszczę dwakroć w tydzień; daję dziesięcinę ze wszystkiego, co mam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'A celnik stojąc z daleka, nie chciał podnieść i oczu swych w niebo, ale się bił w piersi swoje, mówiąc: Boże! bądź miłościw mnie grzesznemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Powiadam wam, żeć ten odszedł usprawiedliwionym do domu swego, więcej niżeli on: albowiem kto się wywyższa, będzie poniżony, a kto się poniża, będzie wywyższony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Przynoszono też do niego i niemowlątka, aby się ich dotykał; co gdy widzieli uczniowie, gromili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Ale Jezus zwoławszy ich, rzekł: Dopuśćcie dziatkom przychodzić do mnie, a nie zabraniajcie im; albowiem takowych jest królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Zaprawdę powiadam wam: Ktobykolwiek nie przyjął królestwa Bożego jako dzieciątko, nie wnijdzie do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'I pytał go niektóry książę, mówiąc: Nauczycielu dobry! co czyniąc odziedziczę żywot wieczny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'I rzekł mu Jezus: Przecz mię zowiesz dobrym? Nikt nie jest dobry, tylko jeden, to jest Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Umiesz przykazania? Nie cudzołóż, nie zabijaj, nie kradnij, nie świadcz fałszywie, czcij ojca twego i matkę twoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'A on rzekł: Tegom wszystkiego przestrzegał od młodości mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Co usłyszawszy Jezus, rzekł mu: Jednego ci jeszcze nie dostaje; wszystko, co masz, sprzedaj, a rozdaj ubogim, a będziesz miał skarb w niebie; a przyszedłszy naśladuj mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'A on usłyszawszy to, bardzo się zasmucił; bo był nader bogaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'A gdy go Jezus ujrzał bardzo zasmuconego, rzekł: Jakoż trudno ci, co mają pieniądze, wnijdą do królestwa Bożego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Albowiem łatwiej jest wielbłądowi przejść przez ucho igielne, niż bogatemu wnijść do królestwa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Tedy rzekli ci, którzy to słyszeli: I któż może być zbawiony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Ale on rzekł: Co jest niemożebne u ludzi, możebne jest u Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'I rzekł Piotr: Otośmy my opuścili wszystko, a poszliśmy za tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Tedy im on rzekł: Zaprawdę powiadam wam, iż nie masz nikogo, co by opuścił dom, albo rodziców, albo braci, albo żonę, albo dzieci dla królestwa Bożego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'Aby nie wziął daleko więcej w tym czasie, a w przyszłym wieku żywota wiecznego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'A wziąwszy z sobą onych dwunastu, rzekł im: Oto wstępujemy do Jeruzalemu, a wypełni się wszystko, co napisano przez proroki o Synu człowieczym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Bo będzie wydany poganom, i będzie naśmiewany, i zelżony, i uplwany:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'A ubiczowawszy zabiją go; ale dnia trzeciego zmartwychwstanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Lecz oni z tego nic nie zrozumieli, i było to słowo zakryte przed nimi, i nie wiedzieli, co mówiono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'I stało się, gdy się on przybliżał do Jerycha, ślepy niektóry siedział podle drogi, żebrząc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'A usłyszawszy lud przechodzący, pytał, co by to było?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'I powiedziano mu, iż Jezus Nazareński tędy idzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'I zawołał, mówiąc: Jezusie, Synu Dawidowy! zmiłuj się nade mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Lecz ci, co szli wprzód, gromili go, aby milczał. Ale on tem więcej wołał: Synu Dawidowy! zmiłuj się nade mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Zastanowiwszy się tedy Jezus, kazał go przywieść do siebie; a gdy się przybliżył, pytał go, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Co chcesz, abym ci uczynił? A on rzekł: Panie! abym przejrzał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'A Jezus mu rzekł: Przejrzyj, wiara twoja ciebie uzdrowiła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'I zarazem przejrzał, i szedł za nim, wielbiąc Boga. Co wszystek lud widząc, dał chwałę Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'A Jezus wszedłszy, szedł przez Jerycho.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'A oto mąż, którego zwano imieniem Zacheusz, który był przełożony nad celnikami, a ten był bogaty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'I żądał widzieć Jezusa, co by zacz był; lecz nie mógł przed ludem, bo był małego wzrostu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'A bieżawszy naprzód, wstąpił na drzewo leśnej figi, aby go ujrzał; bo tamtędy iść miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'A gdy przyszedł na ono miejsce, spojrzawszy Jezus w górę, ujrzał go, i rzekł do niego: Zacheuszu! zstąp prędko na dół, albowiem dziś muszę zostać w domu twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'I zstąpił prędko i przyjął go z radością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'A widząc to wszyscy, szemrali, mówiąc: U człowieka grzesznego gospodą stanął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'A stanąwszy Zacheusz, rzekł do Pana: Oto połowę majętności moich dam ubogim, Panie! a jeźliżem kogo w czem podszedł, oddam w czwórnasób.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'I rzekł mu Jezus: Dziś się stało zbawienie domowi temu, dlatego że i on jest synem Abrahamowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Bo przyszedł Syn człowieczy, aby szukał i zachował, co było zginęło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Tedy gdy oni słuchali, mówiąc dalej powiedział im podobieństwo, dlatego że był blisko od Jeruzalemu, a iż oni mniemali, że się wnet królestwo Boże objawić miało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Rzekł tedy: Niektóry człowiek rodu zacnego jechał w daleką krainę, aby sobie wziął królestwo, i zasię się wrócił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'A zawoławszy dziesięciu sług swoich, dał im dziesięć grzywien i rzekł do nich: Handlujcie, aż przyjadę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Lecz mieszczanie jego mieli go w nienawiści, i wyprawili za nim poselstwo, mówiąc: Nie chcemy, aby ten królował nad nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'I stało się, gdy się wrócił wziąwszy królestwo, że rozkazał do siebie zawołać sług onych, którym był dał pieniądze, aby się dowiedział, co który handlując zyskał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Tedy przyszedł pierwszy, mówiąc: Panie! grzywna twoja dziesięć grzywien urobiła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'I rzekł mu: Dobrze, sługo dobry! iżeś był nad małem wiernym, miejże władzę nad dziesięcioma miastami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Przyszedł i drugi, mówiąc: Panie! grzywna twoja pięć grzywien urobiła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Rzekł i temu: I ty bądź nad pięcioma miastami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'A inszy przyszedł, mówiąc: Panie! oto grzywna twoja, którąm miał schowaną w chustce;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Bom się ciebie bał, żeś jest człowiek srogi; bierzesz, czegoś nie położył, a żniesz, czegoś nie siał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Tedy mu rzekł: Z ust twoich sądzę cię, zły sługo! Wiedziałeś, żem ja jest człowiek srogi, który biorę, czegom nie położył, a żnę, czegom nie siał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Przeczżeś tedy nie dał srebra mego do lichwiarzy? a ja przyszedłszy, wziąłbym je był z lichwą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'I rzekł tym, którzy tuż stali: Weźmijcie od niego tę grzywnę, a dajcie temu, który ma dziesięć grzywien.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'I rzekli mu: Panie! mać dziesięć grzywien.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Zaprawdę powiadam wam, iż wszelkiemu, który ma, będzie dane, a od tego, który nie ma, i to, co ma, będzie od niego odjęte.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Ale i nieprzyjacioły moje, którzy nie chcieli, abym królował nad nimi, przywiedźcie tu, a pobijcie przede mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'A to powiedziawszy, szedł wprzód, wstępując do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'I stało się, gdy się przybliżył do Betfagie i Betanii, ku górze, którą zowią oliwną, posłał dwóch z uczniów swoich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'Mówiąc: Idźcie do miasteczka, które jest przeciwko wam, do którego wszedłszy, znajdziecie oślę uwiązane, na którem żaden człowiek nigdy nie siedział; odwiązawszy je, przywiedźcie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'A jeźliby was kto spytał, przecz je odwiązujecie? tak mu powiecie: Przeto, że go Pan potrzebuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Odszedłszy tedy ci, którzy byli posłani, znaleźli, jako im był powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'A gdy oni odwiązywali ono oślę, rzekli panowie jego do nich: Przecz odwiązujecie oślę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'A oni powiedzieli: Pan go potrzebuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'I przywiedli je do Jezusa, a włożywszy szaty swoje na ono oślę, wsadzili Jezusa na nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'A gdy on jechał, słali szaty swoje na drodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'A gdy się już przybliżał tam, gdzie się spuszczają z góry oliwnej, poczęło wszystko mnóstwo uczniów radując się chwalić Boga głosem wielkim ze wszystkich cudów, które widzieli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Mówiąc: Błogosławiony król, który idzie w imieniu Pańskiem; pokój na niebie, a chwała na wysokościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Ale niektórzy z Faryzeuszów z onego ludu rzekli do niego: Nauczycielu! zgrom ucznie twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'A on odpowiadając, rzekł im: Powiadam wam, jeźliby ci milczeli, wnet kamienie wołać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'A gdy się przybliżył, ujrzawszy miasto, płakał nad niem, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'O gdybyś poznało i ty, a zwłaszcza w ten to dzień twój, co jest ku pokojowi twemu! lecz to teraz zakryte od oczów twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Albowiem przyjdą na cię dni, gdy cię otoczą nieprzyjaciele twoi wałem, i oblęgą cię, i ścisną cię zewsząd;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'I zrównają cię z ziemią, i dzieci twoje w tobie, a nie zostawią w tobie kamienia na kamieniu, dlatego żeś nie poznało czasu nawiedzenia twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'A wszedłszy do kościoła, począł wyganiać te, którzy w nim sprzedawali i kupowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'Mówiąc im: Napisano: Dom mój dom modlitwy jest, a wyście go uczynili jaskinią zbójców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'I uczył na każdy dzień w kościele; lecz przedniejsi kapłani i nauczeni w Piśmie, i przedniejsi z ludu szukali go stracić;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'Ale nie znaleźli, co by mu uczynili; albowiem wszystek lud zawieszał się na nim, słuchając go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'I stało się z onych dni dnia jednego, gdy uczył lud w kościele i kazał Ewangeliję, że nadeszli przedniejsi kapłani i nauczeni w Piśmie z starszymi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'I rzekli do niego, mówiąc: Powiedz nam, którą mocą to czynisz, albo kto jest ten, coć dał tę moc?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'A on odpowiadając, rzekł do nich: Spytam i ja was o jednę rzecz, a powiedzcie mi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Chrzest Jana byłli z nieba, czyli z ludzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'A oni myślili sami w sobie, mówiąc: Jeźli powiemy, z nieba, rzecze: Czemużeście mu tedy nie wierzyli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Jeźliż zasię rzeczemy, z ludzi, wszystek lud ukamionuje nas, ponieważ za pewne mają, że Jan jest prorokiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'I odpowiedzieli, że nie wiedzą, skąd by był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'A Jezus im rzekł: I ja wam nie powiem, którą mocą to czynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'I począł do ludu mówić to podobieństwo: Człowiek niektóry nasadził winnicę, i najął ją winiarzom, i odjechał precz na czas niemały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'A czasu swego posłał sługę do onych winiarzy, aby mu dali z pożytku onej winnicy; ale oni winiarze ubiwszy go, odesłali próżnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'I posłał zasię drugiego sługę; ale oni i tego ubiwszy i zelżywszy, odesłali próżnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'I posłał zasię trzeciego; ale oni i tego zraniwszy, wyrzucili precz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'A tak rzekł Pan onej winnicy: Cóż uczynię? poślę syna mego miłego, snać gdy tego ujrzą, zawstydzą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Ale winiarze ujrzawszy go, rzekli między sobą, mówiąc: Tenci jest dziedzic; pójdźcie zabijmy go, aby nasze było dziedzictwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'I wypchnąwszy go precz z winnicy, zabili. Cóż im tedy uczyni Pan onej winnicy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Przyjdzie, a potraci one winiarze, a winnicę odda innym. Co oni usłyszawszy, rzekli: Nie daj tego Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Lecz on spojrzawszy na nie, rzekł: Cóż tedy jest ono, co napisano: Kamień, który odrzucili budujący, ten się stał głową węgielną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Wszelki, który upadnie na ten kamień, roztrąci się, a na kogo by upadł, zetrze go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'I starali się przedniejsi kapłani i nauczeni w Piśmie, jakoby nań ręce wrzucili onejże godziny, ale się ludu bali; albowiem poznali, iż przeciwko nim wyrzekł to podobieństwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'A tak podstrzegając go, posłali szpiegi, którzy zmyślali, jakoby byli sprawiedliwymi, aby go podchwycili w mowie jego, a potem aby go podali zwierzchności i w moc starościną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'I pytali go, mówiąc: Nauczycielu! wiemy, że dobrze mówisz i uczysz, ani przyjmujesz osób; ale drogi Bożej w prawdzie uczysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Godzili się nam dać czynsz cesarzowi, czyli nie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Ale on obaczywszy chytrość ich, rzekł do nich: Czemuż mię kusicie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Ukażcie mi grosz; czyj ma obraz i napis? A odpowiadając rzekli: Cesarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Zatem on im rzekł: Oddawajcież tedy, co jest cesarskiego, cesarzowi, a co jest Bożego, Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'I nie mogli go podchwycić w mowie jego przed ludem, a zadziwiwszy się odpowiedzi jego, umilknęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'A przyszedłszy niektórzy z Saduceuszów, (którzy przeczą i mówią, iż nie masz zmartwychwstania), pytali go,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Mówiąc: Nauczycielu! Mojżesz nam napisał: Jeźliby komu brat umarł, mając żonę, a umarłby bez dziatek, aby brat jego pojął jego żonę, a wzbudził nasienie bratu swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Było tedy siedm braci, z których pierwszy pojąwszy żonę, umarł bez dziatek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'I pojął wtóry onę żonę, a umarł i ten bez dziatek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Potem ją pojął i trzeci, także i oni wszyscy siedmiu, a nie zostawiwszy dziatek, pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Po wszystkich też umarła i ona niewiasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Przetoż przy zmartwychwstaniu, któregoż z nich ona będzie żoną, ponieważ siedmiu ich miało ją za żonę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Tedy odpowiadając, rzekł im Jezus: Synowie tego wieku żenią się i za mąż wydają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Ale ci, którzy godni są, aby dostąpili onego wieku, i powstaną od umarłych, ani się żenić, ani za mąż dawać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Albowiem umierać więcej nie będą mogli; bo będą równi Aniołom, będąc synami Bożymi, gdyż są synami zmartwychwstania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'A iż umarli zmartwychwstaną, i Mojżesz pokazał przy onym krzaku, gdy zowie Pana Boga Bogiem Abrahamowym i Bogiem Izaakowym i Bogiem Jakóbowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'A Bógci nie jest Bogiem umarłych, ale żywych; bo jemu wszyscy żyją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Tedy odpowiadając niektórzy z nauczonych w Piśmie, rzekli: Nauczycielu! dobrześ powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'I nie śmieli go więcej o nic pytać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'I rzekł do nich: Jakoż powiadają, że Chrystus jest synem Dawidowym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'A sam Dawid mówi w księgach Psalmów: Rzekł Pan Panu memu: Siądź po prawicy mojej');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'Aż położę nieprzyjacioły twoje podnóżkiem nóg twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'Ponieważ go tedy Dawid nazywa Panem, i jakoż jest synem jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'A gdy słuchał wszystek lud, rzekł uczniom swoim:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Strzeżcie się nauczonych w Piśmie, którzy chcą chodzić w szatach długich, i miłują pozdrawiania na rynkach i pierwsze stołki w bóżnicach, i pierwsze miejsca na wieczerzach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Którzy pożerają domy wdów, a to pod pokrywką długich modlitw: cić odniosą cięższy sąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'A spojrzawszy ujrzał bogacze rzucające dary swoje do skarbnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Ujrzał też i niektórą wdowę ubożuchną, wrzucającą tamże dwa drobne pieniążki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'I rzekł: Prawdziwieć wam powiadam, żeć ta uboga wdowa więcej niż ci wszyscy wrzuciła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Ci bowiem wszyscy z tego, co im zbywało, wrzucili do darów Bożych, ale ta z niedostatku swego wszystkę żywność, którą miała, wrzuciła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'A gdy niektórzy mówili o kościele, iż był pięknym kamieniem i upominkami ozdobiony, rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Z tego, co widzicie, przyjdą dni, w które nie będzie zostawiony kamień na kamieniu, który by nie był rozwalony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'I pytali go, mówiąc: Nauczycielu! kiedyż to będzie? a co za znak, gdy się to będzie miało dziać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'A on rzekł: Patrzcie, abyście nie byli zwiedzeni; boć wiele ich przyjdzie w imieniu mojem, mówiąc: Jam jest Chrystus, a czas się przybliżył; nie udawajcież się tedy za nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'A gdy usłyszycie o wojnach i rozruchach, nie lękajcie się; albowiem musi to być pierwej, aleć jeszcze nie tu jest koniec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Tedy im mówił: Powstanie naród przeciwko narodowi, i królestwo przeciwko królestwu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'I będą miejscami wielkie trzęsienia ziemi, i głody i mory, także strachy i znaki wielkie z nieba będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Ale przed tem wszystkiem wrzucą na was ręce swoje, i będą was prześladować, podawając do bóżnic i do więzienia, wodząc przed króle i przed starosty dla imienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'A to was spotka na świadectwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Przetoż złóżcie to do serc waszych, abyście przed czasem nie myślili, jako byście odpowiadać mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Albowiem ja wam dam usta i mądrość, której nie będą mogli odeprzeć, ani się sprzeciwić wszyscy przeciwnicy wasi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'A będziecie też wydani od rodziców i od braci i od krewnych i od przyjaciół, i zabiją niektóre z was;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'Będziecie w nienawiści u wszystkich dla imienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Ale ani włos z głowy waszej nie zginie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'W cierpliwości waszej posiadajcie dusze wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'A gdy ujrzycie Jeruzalem od wojsk otoczone, tedy wiedzcie, żeć się przybliżyło spustoszenie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Tedy ci, co są w Judzkiej ziemi, niech uciekają na góry, a ci, co są w pośrodku jej, niech wychodzą, a ci, co są w polach, niechaj nie wchodzą do niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Albowiem te dni są pomsty, aby się wypełniło wszystko, co napisane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Ale biada brzemiennym i piersiami karmiącym w owe dni! albowiem będzie ucisk wielki w tej ziemi i gniew Boży nad tym ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'I polegną od ostrza miecza, i zapędzeni będą w niewolę między wszystkie narody, i będzie Jeruzalem deptane od pogan, aż się wypełnią czasy pogan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Tedy będą znaki na słońcu i na księżycu i na gwiazdach, a na ziemi uciśnienie narodów z rozpaczą, gdy zaszumi morze i wały;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Tak, iż ludzie drętwieć będą przed strachem i oczekiwaniem tych rzeczy, które przyjdą na wszystek świat; albowiem mocy niebieskie poruszą się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'A tedy ujrzą Syna człowieczego, przychodzącego w obłoku z mocą i chwałą wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'A gdy się to pocznie dziać, spoglądajcież a podnoście głowy wasze, przeto iż się przybliża odkupienie wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'I powiedział im podobieństwo: Spojrzyjcie na figowe drzewo i na wszystkie drzewa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Gdy się już pukają, widząc to sami to uznawacie, że już blisko jest lato.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Także i wy, gdy ujrzycie, iż się to dzieje, wiedzcie, że blisko jest królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Zaprawdę powiadam wam, żeć nie przeminie ten wiek, ażby się to wszystko stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Niebo i ziemia przeminą, ale słowa moje nie przeminą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'A strzeżcie się, aby snać nie były obciążone serca wasze obżarstwem i opilstwem i pieczołowaniem o ten żywot, a nagle by na was przyszedł ten dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Albowiem jako sidło przypadnie na wszystkie, którzy mieszkają na obliczu wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Przetoż czujcie, modląc się na każdy czas, abyście byli godni ujść tego wszystkiego, co się dziać ma, i stanąć przed Synem człowieczym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'I nauczał we dnie w kościele; ale w nocy wychodząc, przebywał na górze, którą zowią oliwną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'A wszystek lud rano się schodził do niego, aby go słuchał w kościele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'A przybliżało się święto przaśników, które zowią wielkanocą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'I szukali przedniejsi kapłani i nauczeni w Piśmie, jakoby go zabili; ale się bali ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'I wstąpił szatan w Judasza, którego zwano Iszkaryjotem, który był z liczby dwunastu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Ten tedy odszedłszy, zmówił się z przedniejszymi kapłanami, i z przełożonymi kościoła, jakoby go im wydał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'I uradowali się, i umówili się z nim, że mu chcą dać pieniądze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'I obiecał, i szukał sposobnego czasu, aby go im wydał bez rozruchu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Tedy przyszedł dzień przaśników, którego miał baranek być zabity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'I posłał Piotra i Jana, mówiąc: Poszedłszy nagotujcie nam baranka, abyśmy jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Ale oni mu rzekli: Gdzież chcesz, abyśmy go nagotowali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'A on rzekł do nich: Oto gdy do miasta wchodzić będziecie, spotka się z wami człowiek, niosący dzban wody; idźcież za nim do domu, do którego wnijdzie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'A rzeczcie gospodarzowi domu onego: Kazał ci powiedzieć nauczyciel: Gdzie jest gospoda, kędy bym jadł baranka z uczniami moimi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'A on wam ukaże salę wielką usłaną, tamże nagotujcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Tedy odszedłszy znaleźli, jako im był powiedział, i nagotowali baranka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'A gdy przyszła godzina, usiadł za stół, i dwanaście apostołów z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'I rzekł do nich: Żądając żądałem tego baranka jeść z wami, pierwej niżbym cierpiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Boć wam powiadam, że go więcej jeść nie będę, aż się wypełni w królestwie Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'A wziąwszy kielich i podziękowawszy, rzekł: Weźmijcie to, a podzielcie między się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Albowiem powiadam wam, że nie będę pił z rodzaju winnej macicy, aż przyjdzie królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'A wziąwszy chleb i podziękowawszy, łamał i dał im, mówiąc: To jest ciało moje, które się za was daje; to czyńcie na pamiątkę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Także i kielich, gdy było po wieczerzy, mówiąc: Ten kielich jest nowy testament we krwi mojej, która się za was wylewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Ale oto ręka tego, co mię wydaje, ze mną jest za stołem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Synci zaiste człowieczy idzie, tak jako jest postanowione; ale biada człowiekowi temu, który go wydaje!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Tedy się oni poczęli między sobą pytać o tem, kto by wżdy z nich był, co by to uczynić miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'A wszczął się też spór między nimi o tem, kto by się z nich zdał być większy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Ale on im rzekł: Królowie narodów panują nad nimi, a którzy nad nimi moc mają, dobrodziejami nazywani bywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Lecz wy nie tak: owszem kto największy jest między wami, niech będzie jako najmniejszy, a kto jest wodzem, będzie jako ten, co służy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Bo któryż większy jest? Ten, co siedzi, czyli ten, co służy? Izali nie ten, co siedzi? Alem ja jest w pośrodku was jako ten, co służy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'A wy jesteście, którzyście wytrwali przy mnie w pokusach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'I jać wam sporządzam, jako mi sporządził Ojciec mój, królestwo,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'Abyście jedli i pili za stołem moim w królestwie mojem, i siedzieli na stolicach, sądząc dwanaście pokoleń Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'I rzekł Pan: Szymonie, Szymonie! oto szatan wyprosił was, aby was odwiewał jako pszenicę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Alem ja prosił za tobą, aby nie ustała wiara twoja; a ty niekiedy nawróciwszy się, utwierdzaj braci twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'A on mu rzekł: Panie! gotówem z tobą iść i do więzienia i na śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'A on rzekł: Powiadam ci, Piotrze! nie zapieje dziś kur, aż się pierwej trzykroć zaprzesz, że mię nie znasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'I rzekł im: Gdym was posyłał bez mieszka, i bez taistry, i bez butów, izali wam czego nie dostawało? A oni rzekli: Niczego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Tedy im rzekł: Ale teraz kto ma mieszek, niech go weźmie, także i taistrę; a kto nie ma miecza, niech sprzeda suknię swoję, a kupi miecz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Albowiem powiadam wam, iż się jeszcze musi to, co napisano, wypełnić na mnie, mianowicie: I z złoczyńcami policzony jest; boć te rzeczy, które świadczą o mnie, koniec biorą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Ale oni rzekli: Panie! oto tu dwa miecze. A on im rzekł: Dosyć jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'I wyszedłszy szedł według zwyczaju na górę Oliwną, a szli za nim i uczniowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'A gdy przyszedł na miejsce, rzekł im: Módlcie się, abyście nie weszli w pokuszenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'A sam oddalił się od nich, jakoby na ciśnienie kamieniem, a klęknąwszy na kolana, modlił się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'Mówiąc: Ojcze! jeźli chcesz, przenieś ten kielich ode mnie; wszakże nie moja wola, lecz twoja niech się stanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'I ukazał mu się Anioł z nieba, posilający go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Ale będąc w boju, gorliwiej się modlił, a był pot jego jako krople krwi ściekające na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'A wstawszy od modlitwy, przyszedł do uczniów, i znalazł je śpiące od smutku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'I rzekł im: Cóż śpicie? wstańcie, a módlcie się, byście nie weszli w pokuszenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'A gdy on jeszcze mówił, oto zgraja i ten, którego zwano Judaszem, jeden ze dwunastu, szedł przed nimi, i przybliżył się do Jezusa, aby go pocałował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'A Jezus mu rzekł: Judaszu! pocałowaniem wydajesz Syna człowieczego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'A widząc ci, którzy przy nim byli, co się dziać miało, rzekli mu: Panie! mamyli bić mieczem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'I uderzył jeden z nich sługę najwyższego kapłana, i uciął mu ucho prawe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Ale Jezus odpowiadając, rzekł: Zaniechajcie aż póty; a dotknąwszy się ucha jego, uzdrowił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'I rzekł Jezus do onych, którzy byli przyszli przeciwko niemu, do przedniejszych kapłanów i przełożonych świątyni, i do starszych: Wyszliście jako na zbójcę z mieczami i z kijami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Gdym na każdy dzień bywał z wami w kościele, nie ściągnęliście rąk na mię; ale tać jest ona godzina wasza i moc ciemności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Pojmawszy go tedy, prowadzili go i przyprowadzili go w dom najwyższego kapłana, a Piotr szedł za nim z daleka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'A gdy oni rozniecili ogień w pośrodku dworu i wespół usiedli, usiadł i Piotr między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'A ujrzawszy go niektóra dziewka u ognia siedzącego, i pilnie mu się przypatrzywszy, rzekła: I ten z nim był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'A on się go zaprzał, mówiąc: Niewiasto! Nie znam go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'A po małej chwili ujrzawszy go drugi, rzekł: I tyś jest z nich; ale Piotr rzekł: Człowiecze! nie jestem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'A gdy wyszła jakoby jedna godzina, ktoś inszy twierdził, mówiąc: Prawdziwie i ten z nim był; bo też jest Galilejczyk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'A Piotr rzekł: Człowiecze! nie wiem, co mówisz; a zatem zaraz, gdy on jeszcze mówił, kur zapiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'A Pan obróciwszy się, spojrzał na Piotra. I wspomniał Piotr na słowo Pańskie, jako mu był powiedział: Iż pierwej niż kur zapieje, trzykroć się mnie zaprzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'A Piotr wyszedłszy precz, gorzko płakał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Lecz mężowie, którzy wespół trzymali Jezusa, naśmiewali się z niego, bijąc go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'A zakrywszy go, bili twarz jego i pytali go, mówiąc: Prorokuj, kto jest, co cię uderzył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'I wiele innych rzeczy bluźniąc mówili przeciwko niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'A gdy był dzień, zeszli się starsi z ludu i najwyżsi kapłani i nauczeni w Piśmie, a przywiedli go do rady swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Mówiąc: Jeźliś ty jest Chrystus, powiedz nam? I rzekł im: Choćbym wam powiedział, nie uwierzycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'A jeźlibym też o co pytał, nie odpowiecie mi, ani mię wypuścicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Od tego czasu będzie Syn człowieczy siedział na prawicy mocy Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'I rzekli wszyscy: Tyś tedy jest on syn Boży? A on rzekł do nich: Wy powiadacie, żem ja jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'A oni rzekli: Cóż jeszcze potrzebujemy świadectwa? Wszakieśmy sami słyszeli z ust jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Tedy powstawszy wszystko mnóstwo ich, wiedli go do Piłata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'I poczęli nań skarżyć, mówiąc: Tegośmy znaleźli, że odwraca lud i zakazuje dani dawać cesarzowi, powiadając: Że on jest Chrystusem królem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'I pytał go Piłat, mówiąc: Tyżeś jest on król żydowski? A on mu odpowiadając rzekł: Ty powiadasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'I rzekł Piłat do przedniejszych kapłanów i do ludu: Żadnej winy nie znajduję w tym człowieku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Lecz się oni bardziej silili, mówiąc: Iż wzrusza lud, ucząc po wszystkiej Judzkiej ziemi, począwszy od Galilei aż dotąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Tedy Piłat usłyszawszy o Galilei, pytał, jeźliby był człowiekiem Galilejskim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'A gdy się dowiedział, iż był z państwa Herodowego, odesłał go do Heroda, który też w Jeruzalemie był w one dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'A Herod ujrzawszy Jezusa, uradował się bardzo; bo go z dawna pragnął widzieć, dlatego, iż wiele o nim słyszał, i spodziewał się, iż miał ujrzeć jaki cud od niego uczyniony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'I pytał go wielą słów; ale mu on nic nie odpowiadał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'A przedniejsi kapłani i nauczeni w Piśmie stali, potężnie skarżąc nań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Ale wzgardziwszy nim Herod z żołnierstwem swem i naśmiawszy się z niego, oblekł go w szatę białą i odesłał go zaś do Piłata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'I stali się sobie przyjaciołmi Piłat z Herodem onegoż to dnia; bo sobie byli przedtem nieprzyjaciołmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'A Piłat zwoławszy przedniejszych kapłanów i przełożonych, i ludu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'Rzekł do nich: Oddaliście mi tego człowieka, jakoby lud odwracał: a oto ja przed wami pytając go, żadnej winy nie znalazłem w tym człowieku z tego, co nań skarżycie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Ale ani Herod, bom was odesłał do niego, a oto nic mu się godnego śmierci nie stało;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Przetoż skarawszy wypuszczę go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'A musiał im Piłat wypuszczać jednego na święto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Tedy zawołało społem wszystko mnóstwo, mówiąc: Strać tego a wypuść nam Barabbasza!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Który był dla niejakiego rozruchu w mieście uczynionego, i dla mężobójstwa wsadzony do więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Tedy Piłat znowu mówił, chcąc wypuścić Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Ale oni przecię wołali, mówiąc: Ukrzyżuj, ukrzyżuj go!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'A on po trzecie rzekł do nich: I cóż wżdy ten złego uczynił? Żadnej winy śmierci nie znalazłem w nim; przetoż skarawszy wypuszczę go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'A oni przecię nalegali głosy wielkimi, żądając, aby był ukrzyżowany; i zmacniały się głosy ich i przedniejszych kapłanów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'A tak Piłat przysądził, aby się dosyć stało żądności ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'I wypuścił im onego, który był dla rozruchu i mężobójstwa wsadzony do więzienia, o którego prosili; ale Jezusa podał na wolę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Gdy go tedy wiedli, uchwyciwszy Szymona niektórego Cyrenejczyka, idącego z pola, włożyli nań krzyż, aby go niósł za Jezusem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'I szło za nim wielkie mnóstwo ludu i niewiast, które go płakały i narzekały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Ale Jezus obróciwszy się do nich, rzekł: Córki Jeruzalemskie! nie płaczcie nade mną, ale raczej same nad sobą płaczcie i nad dziatkami waszemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Albowiemci oto idą dni, których będą mówić: Błogosławione niepłodne i żywoty, które nie rodziły, i piersi, które nie karmiły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Tedy poczną mówić górom: Padnijcie na nas! a pagórkom: Przykryjcie nas!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Albowiem ponieważ się to na zielonem drzewie dzieje, a cóż będzie na suchem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Wiedzieni też byli i inni dwaj złoczyńcy, aby wespół z nim straceni byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'A gdy przyszli na miejsce, które zowią trupich głów, tam go ukrzyżowali, i onych złoczyńców, jednego po prawicy, a drugiego po lewicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Tedy Jezus rzekł: Ojcze! odpuść im: boć nie wiedzą, co czynią. A rozdzieliwszy szaty jego, los o nie miotali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'I stał lud, przypatrując się, a naśmiewali się z niego i przełożeni z nimi, mówiąc: Inszych ratował, niechże ratuje samego siebie, jeźliże on jest Chrystus, on wybrany Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Naśmiewali się też z niego i żołnierze, przystępując, a ocet mu podawając,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'I mówiąc: Jeźliś ty jest król żydowski, ratujże samego siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'A był też i napis napisany nad nim literami Greckiemi i Łacińskiemi i Żydowskiemi: Tenci jest on król żydowski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'A jeden z onych złoczyńców, którzy z nim wisieli, urągał mu, mówiąc: Jeźliżeś ty jest Chrystus, ratujże siebie i nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'A odpowiadając drugi, gromił go mówiąc: I ty się Boga nie boisz, chociażeś jest w temże skazaniu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'A myć zaiste sprawiedliwie; (bo godną zapłatę za uczynki nasze bierzemy;) ale ten nic złego nie uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'I rzekł do Jezusa: Panie! pomnij na mnie, gdy przyjdziesz do królestwa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'A Jezus mu rzekł: Zaprawdę powiadam tobie, dziś ze mną będziesz w raju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'A było około szóstej godziny, i stała się ciemność po wszystkiej ziemi aż do godziny dziewiątej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'I zaćmiło się słońce, a zasłona kościelna rozerwała się w pół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'A Jezus zawoławszy głosem wielkim, rzekł: Ojcze! w ręce twoje polecam ducha mojego; a to rzekłszy, skonał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'A widząc setnik, co się działo, chwalił Boga, mówiąc: Zaprawdę człowiek to był sprawiedliwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Także i wszystek lud, który się był zszedł na to dziwowisko, widząc, co się działo, bijąc się w piersi swoje, wracał się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'A znajomi jego wszyscy z daleka stali, i niewiasty, które za nim były przyszły z Galilei, przypatrując się temu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'A oto mąż, imieniem Józef, który był senatorem, mąż dobry i sprawiedliwy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'Który był nie zezwolił na radę i na uczynek ich, z Arymatyi, miasta Judzkiego, który też oczekiwał królestwa Bożego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Ten przyszedłszy do Piłata, prosił o ciało Jezusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'I zdjąwszy je, obwinął je prześcieradłem a położył je w grobie w opoce wykowanym, w którym jeszcze nikt nigdy nie był położony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'A był dzień przygotowania, i sabat nastawał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Poszedłszy też za nim i niewiasty, które były z nim przyszły z Galilei, oglądały grób, i jako było położone ciało jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'A wróciwszy się, nagotowały wonnych rzeczy i maści; ale w sabat odpoczęły według przykazania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'A pierwszego dnia po sabacie bardzo rano przyszły do grobu, niosąc rzeczy wonne, które były nagotowały i niektóre inne z niemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'I znalazły kamień odwalony od grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'A wszedłszy w grób, nie znalazły ciała Pana Jezusowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'I stało się, gdy się dlatego zatrwożyły, że oto dwaj mężowie stanęli przy nich w szatach świetnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'A gdy się one bały i schyliły twarz swoję ku ziemi, rzekli do nich: Cóż szukacie żyjącego między umarłymi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Nie maszci go tu, ale wstał: wspomnijcie, jako wam powiadał, gdy jeszcze był w Galilei,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'Mówiąc: Iż Syn człowieczy musi być wydany w ręce ludzi grzesznych, i być ukrzyżowany, a trzeciego dnia zmartwychwstać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'I wspomniały na słowa jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'A wróciwszy się od grobu, oznajmiły to wszystko onym jedenastu i innym wszystkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'A była Maryja Magdalena i Joanna, i Maryja, matka Jakóbowa, i inne z niemi, które to powiadały Apostołom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Ale się im zdały jako plotki słowa ich, i nie wierzyli im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Tedy Piotr wstawszy, bieżał do grobu, a nachyliwszy się, ujrzał same tylko prześcieradła leżące, i odszedł, dziwując się sam u siebie temu, co się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'A oto dwaj z nich tegoż dnia szli do miasteczka, które było na sześćdziesiąt stajan od Jeruzalemu, które zwano Emaus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'A ci rozmawiali z sobą o tem wszystkiem, co się było stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'I stało się, gdy oni rozmawiali i wespół się pytali, że i Jezus przybliżywszy się, szedł z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Ale oczy ich były zatrzymane, aby go nie poznali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'I rzekł do nich: Cóż to za rozmowy, które macie między sobą idąc, a jesteście smutni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'A odpowiadając mu jeden, któremu było imię Kleofas, rzekł mu: Tyś sam przychodniem w Jeruzalemie, a nie wiesz, co się w niem w tych dniach stało?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'I rzekł im: Cóż? A oni mu rzekli: O Jezusie Nazareńskim, który był mąż prorok, mocny w uczynku i w mowie przed Bogiem i wszystkim ludem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'A jako go wydali przedniejsi kapłani i przełożeni nasi, aby był skazany na śmierć; i ukrzyżowali go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'A myśmy się spodziewali, iż on miał odkupić Izraela; ale teraz temu wszystkiemu dziś jest trzeci dzień, jako się to stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Lecz i niewiasty niektóre z naszych przestraszyły nas, które raniuczko były u grobu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'A nie znalazłszy ciała jego, przyszły powiadając, iż widzenie Anielskie widziały, którzy powiadają, iż on żyje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'I chodzili niektórzy z naszych do grobu, i tak znaleźli, jako i niewiasty powiadały; ale samego nie widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Tedy on rzekł do nich: O głupi, a leniwego serca ku wierzeniu temu wszystkiemu, co powiedzieli prorocy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Azaż nie musiał Chrystus tego cierpieć i wnijść do chwały swojej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'A począwszy od Mojżesza i od wszystkich proroków, wykładał im wszystkie one Pisma, które o nim napisane były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'I przybliżył się ku miasteczku, do którego szli, a on pokazywał, jakoby miał dalej iść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Ale go oni przymusili, mówiąc: Zostań z nami, boć się ma ku wieczorowi, i już się dzień nachylił. I wszedł, aby został z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'I stało się, gdy on siedział z nimi za stołem, wziąwszy chleb, błogosławił, a łamiąc podawał im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'I otworzyły się oczy ich, i poznali go; ale on zniknął z oczu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'I mówili między sobą: Izali serce nasze nie pałało w nas, gdy z nami w drodze mówił, i gdy nam Pisma otwierał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'A wstawszy onejże godziny, wrócili się do Jeruzalemu, i znaleźli zgromadzonych onych jedenaście, i tych, którzy z nimi byli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'Powiadających: Iż wstał Pan prawdziwie, i ukazał się Szymonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'A oni też powiedzieli, co się stało w drodze, i jako go poznali w łamaniu chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'A gdy oni to mówili, stanął sam Jezus w pośrodku nich, i rzekł im: Pokój wam!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'A oni przelęknąwszy się i przestraszeni będąc, mniemali, iż ducha widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'I rzekł im: Czemuście się zatrwożyli, i czemu myśli wstępują do serc waszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Oglądajcie ręce moje i nogi moje, żemci ja jest on; dotykajcie się mnie, a obaczcie; bo duch nie ma ciała ani kości, jako widzicie, że ja mam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'A to rzekłszy, pokazał im ręce i nogi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Lecz gdy oni jeszcze nie wierzyli od radości, ale się dziwowali, rzekł im: Macie tu co jeść?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'A oni mu podali sztukę ryby pieczonej i plastr miodu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'A on wziąwszy, jadł przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'I rzekł do nich: Teć są słowa, którem mówił do was, będąc jeszcze z wami, iż się musi wypełnić wszystko, co napisano w zakonie Mojżeszowym i w prorokach, i w psalmach o mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Tedy im otworzył zmysł, żeby rozumieli Pisma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'I rzekł im: Takci napisano, i tak musiał Chrystus cierpieć, i trzeciego dnia zmartwychwstać;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'I aby była kazana w imieniu jego pokuta i odpuszczenie grzechów między wszystkimi narody, począwszy od Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'A wy jesteście świadkami tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'A oto ja poślę na was obietnicę Ojca mego, a wy zostańcie w mieście Jeruzalemie, dokąd nie będziecie przyobleczeni mocą z wysokości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'I wywiódł je precz aż do Betanii, a podniósłszy ręce swoje błogosławił im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'I stało się, gdy im błogosławił, rozstał się z nimi, i był niesiony w górę do nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'A oni pokłoniwszy mu się, wrócili się do Jeruzalemu z radością wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'I byli zawsze w kościele, chwaląc i błogosławiąc Boga. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Na początku było Słowo, a ono Słowo było u Boga, a Bogiem było ono Słowo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'To było na początku u Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Wszystkie rzeczy przez nie się stały, a bez niego nic się nie stało, co się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'W niem był żywot, a żywot był oną światłością ludzką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'A ta światłość w ciemnościach świeci, ale ciemności jej nie ogarnęły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Był człowiek posłany od Boga, któremu imię było Jan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Ten przyszedł na świadectwo, aby świadczył o tej światłości, aby przezeń wszyscy uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Nie byłci on tą światłością, ale przyszedł, aby świadczył o tej światłości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Tenci był tą prawdziwą światłością, która oświeca każdego człowieka, przychodzącego na świat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Na świecie był, a świat przezeń uczyniony jest; ale go świat nie poznał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Do swej własności przyszedł, ale go właśni jego nie przyjęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Lecz którzykolwiek go przyjęli, dał im tę moc, aby się stali synami Bożymi, to jest tym, którzy wierzą w imię jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Którzy nie z krwi, ani z woli ciała, ani z woli męża, ale z Boga narodzeni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'A to Słowo ciałem się stało, i mieszkało między nami, i widzieliśmy chwałę jego, chwałę jako jednorodzonego od Ojca, pełne łaski i prawdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Jan świadczył o nim, i wołał, mówiąc: Tenci był, o którymem powiadał: Który po mnie przyszedłszy, uprzedził mię; bo pierwej był niż ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'A z pełności jego myśmy wszyscy wzięli i łaskę za łaskę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Albowiem zakon przez Mojżesza jest dany, a łaska i prawda przez Jezusa Chrystusa stała się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Boga nikt nigdy nie widział: on jednorodzony syn, który jest w łonie ojcowskiem, ten nam opowiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'A toć jest świadectwo Janowe, gdy posłali Żydzi z Jeruzalemu kapłany i Lewity, aby go pytali: Ty ktoś jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'I wyznał, a nie zaprzał, a wyznał, żem ja nie jest Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'I pytali go: Cóżeś tedy? Elijasześ ty? A on rzekł: Nie jestem. A oni: Prorokiemeś ty? i odpowiedział: Nie jestem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Rzekli mu tedy: Któżeś jest, żebyśmy odpowiedź dali tym, którzy nas posłali? Cóż wżdy powiadasz o sobie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Rzekł: Jam jest głos wołającego na puszczy: Prostujcie drogę Pańską, jako powiedział Izajasz prorok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'A ci, którzy byli posłani, byli z Faryzeuszów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'I pytali go i rzekli mu: Czemuż tedy chrzcisz, jeźliżeś ty nie jest Chrystus, ani Elijasz, ani prorok?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Odpowiedział im Jan, mówiąc: Jać chrzczę wodą; ale w pośrodku was stoi, którego wy nie znacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Tenci jest, który po mnie przyszedłszy, uprzedził mię, któremum ja nie jest godzien, żebym rozwiązał rzemyk obuwia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'To się stało w Betabarze za Jordanem, gdzie Jan chrzcił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'A nazajutrz ujrzał Jan Jezusa idącego do siebie, i rzekł: Oto Baranek Boży, który gładzi grzech świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Tenci jest, o którymem powiadał, że idzie za mną mąż, który mię uprzedził; bo pierwej był niż ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'A jam go nie znał; ale aby był objawiony Izraelowi, dlategom ja przyszedł, chrzcząc wodą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'I świadczył Jan, mówiąc: Widziałem Ducha zstępującego jako gołębicę z nieba, i został na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'A jam go nie znał; ale który mię posłał chrzcić wodą, ten mi rzekł: Na kogo byś ujrzał Ducha zstępującego i zostającego na nim, tenci jest, który chrzci Duchem Świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'A jam widział i świadczył, że ten jest Syn Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Nazajutrz zasię stał Jan i dwaj z uczniów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'A ujrzawszy Jezusa chodzącego, rzekł: Oto Baranek Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'I słyszeli go oni dwaj uczniowie mówiącego, i szli za Jezusem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'A obróciwszy się Jezus i ujrzawszy je za sobą idące, rzekł do nich: Czego szukacie? A oni mu rzekli: Rabbi! (co się wykłada: Mistrzu), gdzie mieszkasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Rzekł im: Pójdźcie, a oglądajcie. I szli i widzieli, gdzie mieszkał, a zostali przy nim onego dnia; bo było około dziesiątej godziny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'A był Andrzej, brat Szymona Piotra, jeden z onych dwóch, którzy to słyszeli od Jana, i szli byli za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Ten najpierw znalazł Szymona, brata swego własnego, i rzekł mu: Znaleźliśmy Mesyjasza, co się wykłada Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'I przywiódł go do Jezusa. A wejrzawszy nań Jezus, rzekł: Tyś jest Szymon, syn Jonasza; ty będziesz nazwany Kiefas, co się wykłada Piotr.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'A nazajutrz chciał Jezus wynijść do Galilei, i znalazł Filipa i rzekł mu: Pójdź za mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'A Filip był z Betsaidy, z miasta Andrzejowego i Piotrowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Filip znalazł Natanaela i rzekł mu: Znaleźliśmy onego, o którym pisał Mojżesz w zakonie i prorocy, Jezusa, syna Józefowego, z Nazaretu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'I rzekł mu Natanael: Możesz z Nazaretu być co dobrego? Rzekł mu Filip: Pójdź, a oglądaj!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Ujrzawszy tedy Jezus Natanaela idącego do siebie, rzekł o nim: Oto prawdziwie Izraelczyk, w którym nie masz zdrady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Rzekł mu Natanael: Skądże mię znasz? Odpowiedział Jezus i rzekł mu: Pierwej niż cię Filip zawołał, gdyś był pod figowem drzewem, widziałem cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Odpowiedział Natanael i rzekł mu: Mistrzu! tyś jest on Syn Boży, tyś jest on król Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Odpowiedział Jezus i rzekł mu: Iżem ci powiedział: Widziałem cię pod figowem drzewem, wierzysz; większe rzeczy nad te ujrzysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'I rzekł mu: Zaprawdę, zaprawdę powiadam wam: Od tego czasu ujrzycie niebo otworzone i Anioły Boże wstępujące i zstępujące na Syna człowieczego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'A dnia trzeciego było wesele w Kanie Galilejskiej, i była tam matka Jezusowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Wezwany też był i Jezus i uczniowie jego na ono wesele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'A gdy nie stało wina, rzekła matka Jezusowa do niego: Wina nie mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Rzekł jej Jezus: Co ja mam z tobą, niewiasto? jeszczeć nie przyszła godzina moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Rzekła matka jego sługom: Cokolwiek wam rzecze, uczyńcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'I było tam sześć stągwi kamiennych, postawionych według oczyszczenia żydowskiego, biorących w się każda dwie albo trzy wiadra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Rzekł im Jezus: Napełnijcie te stągwie wodą; i napełnili je aż do wierzchu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Tedy im rzekł: Czerpajcież teraz, a donieście przełożonemu wesela. I donieśli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'A gdy skosztował przełożony wesela onej wody, która się stała winem, (a nie wiedział, skąd by było; lecz słudzy wiedzieli, którzy wodę czerpali), zawołał on przełożony oblubieńca;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'I rzekł mu: Każdy człowiek pierwej daje wino dobre, a gdy sobie podpiją, tedy podlejsze; a tyś dobre wino zachował aż do tego czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Tenci początek cudów uczynił Jezus w Kanie Galilejskiej, a objawił chwałę swoję; i uwierzyli weń uczniowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Potem zstąpił do Kapernaum, on i matka jego i bracia jego i uczniowie jego, i zamieszkali tam niewiele dni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Albowiem była blisko wielkanoc żydowska; i wstąpił Jezus do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'I znalazł w kościele siedzące te, co sprzedawali woły i owce i gołębie, i te, co pieniędzmi handlowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'A uczyniwszy bicz z powrozków, wszystkie wygnał z kościoła, i owce i woły: a tych, co pieniędzmi handlowali, pieniądze rozsypał i stoły poprzewracał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'A tym, co gołębie sprzedawali, rzekł: Wynieście to stąd, a nie czyńcie domu Ojca mego domem kupieckim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'I wspomnieli sobie uczniowie jego, iż napisano: Gorliwość domu twego zżarła mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Tedy odpowiedzieli Żydowie i rzekli mu: Cóż nam za znak pokażesz, iż to czynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Odpowiedział Jezus i rzekł im: Rozwalcie ten kościół, a we trzech dniach wystawię go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Rzekli tedy Żydowie: Czterdzieści i sześć lat budowano ten kościół, a ty go we trzech dniach wystawisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Ale on mówił o kościele ciała swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Przetoż, gdy zmartwychwstał, wspomnieli uczniowie jego, iż im to był powiedział; i uwierzyli Pismu i słowu, które wyrzekł Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'A gdy był w Jeruzalemie na wielkanoc w święto, wiele ich uwierzyło w imię jego, widząc cuda jego, które czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Ale Jezus nie zwierzał im samego siebie, przeto iż on znał wszystkie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'A iż nie potrzebował, aby mu kto świadectwo wydawał o człowieku; albowiem on wiedział, co było w człowieku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'A był niektóry człowiek z Faryzeuszów, imieniem Nikodem, książę żydowski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Ten przyszedł do Jezusa w nocy i rzekł mu: Mistrzu! wiemy, żeś przyszedł od Boga nauczycielem; bo nikt tych cudów czynić nie może, które ty czynisz, jeźliby Bóg z nim nie był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Odpowiedział Jezus i rzekł mu: Zaprawdę, zaprawdę powiadam ci: Jeźli się kto nie narodzi znowu, nie może widzieć królestwa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Rzekł do niego Nikodem: Jakoż się może człowiek narodzić, będąc stary? izali powtóre może wnijść w żywot matki swojej i narodzić się?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Odpowiedział Jezus: Zaprawdę, zaprawdę powiadam ci: Jeźliby się kto nie narodził z wody i z Ducha, nie może wnijść do królestwa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Co się narodziło z ciała, ciało jest, a co się narodziło z Ducha, duch jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Nie dziwuj się, żem ci powiedział: Musicie się znowu narodzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Wiatr, gdzie chce, wieje i głos jego słyszysz, ale nie wiesz, skąd przychodzi i dokąd idzie; takżeć jest każdy, który się narodził z Ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Odpowiedział Nikodem i rzekł mu: Jakoż to być może?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Odpowiedział Jezus i rzekł mu: Tyś jest nauczycielem w Izraelu, a tego nie wiesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Zaprawdę, zaprawdę powiadam ci, iż co wiemy, mówimy, a cośmy widzieli, świadczymy: ale świadectwa naszego nie przyjmujecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Jeźliż gdym wam ziemskie rzeczy powiadał, a nie wierzycie, jakoż, będęli wam powiadał niebieskie, uwierzycie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'A nikt nie wstąpił do nieba, tylko ten, który zstąpił z nieba, Syn człowieczy, który jest w niebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'A jako Mojżesz węża na puszczy wywyższył, tak musi być wywyższony Syn człowieczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Aby każdy, kto weń wierzy, nie zginął, ale miał żywot wieczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Albowiem tak Bóg umiłował świat, że Syna swego jednorodzonego dał, aby każdy, kto weń wierzy, nie zginął, ale miał żywot wieczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Boć nie posłał Bóg Syna swego na świat, aby sądził świat, ale aby świat był zbawiony przezeń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Kto wierzy weń, nie będzie osądzony; ale kto nie wierzy, już jest osądzony, iż nie uwierzył w imię jednorodzonego Syna Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'A tenci jest sąd, że światłość przyszła na świat, lecz ludzie bardziej umiłowali ciemność niż światłość; bo były złe uczynki ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Każdy bowiem, kto źle czyni, nienawidzi światłości i nie idzie na światłość, aby nie były zganione uczynki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Lecz kto czyni prawdę, przychodzi do światłości, aby były jawne uczynki jego, iż w Bogu są uczynione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Potem przyszedł Jezus i uczniowie jego do Judzkiej ziemi, i tam przemieszkiwał z nimi i chrzcił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Chrzcił też i Jan w Enon, blisko Salim; bo tam było wiele wód, a ludzie przychodzili i chrzcili się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Bo jeszcze Jan nie był podany do więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Wszczęła się tedy gadka między uczniami Janowymi i między Żydami o oczyszczaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'I przyszli do Jana i rzekli mu: Mistrzu! ten, który był z tobą za Jordanem, któremuś ty dał świadectwo, ten oto chrzci, a wszyscy idą do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Odpowiedział Jan i rzekł: Nie może nic wziąć człowiek, jeźliby mu nie było dane z nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Wy sami jesteście mi świadkami, żem powiedział: Nie jestem ja Chrystus, ale żem posłany przed nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Kto ma oblubienicę, ten jest oblubieniec, a przyjaciel oblubieńca, który stoi, a słucha go, weseli się weselem dla głosu oblubieńcowego; przetoż to wesele moje wypełnione jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'On musi rość, a mnie musi ubywać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Kto z góry przyszedł, nade wszystkie jest; kto z ziemi jest, ziemski jest i ziemskie rzeczy mówi; ten, który z nieba przyszedł, nade wszystkie jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'A co widział i słyszał, to świadczy, ale świadectwa jego żaden nie przyjmuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Kto przyjmuje świadectwo jego, ten zapieczętował, że Bóg jest prawdziwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Albowiem ten, którego Bóg posłał, słowo Boże mówi; boć mu nie pod miarą daje Bóg Ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Ojciec miłuje Syna, i wszystko dał w ręce jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Kto wierzy w Syna, ma żywot wieczny; ale kto nie wierzy Synowi, nie ogląda żywota, lecz gniew Boży zostaje nad nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'A gdy poznał Pan, iż usłyszeli Faryzeuszowie, że Jezus więcej uczniów czynił i chrzcił niżeli Jan,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(Chociaż sam Jezus nie chrzcił, ale uczniowie jego),');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Opuścił Judzką ziemię i odszedł zasię do Galilei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'A musiał iść przez Samaryję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'I przyszedł do miasta Samaryi, które zowią Sychar, blisko folwarku, który był dał Jakób Józefowi, synowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'I była tam studnia Jakóbowa; przetoż będąc Jezus na drodze spracowany, siedział tak na studni; a było około szóstej godziny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'I przyszła niewiasta z Samaryi czerpać wodę, której rzekł Jezus: Daj mi pić!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, '(Bo uczniowie jego odeszli byli do miasta, aby nakupili żywności.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Rzekła mu tedy ona niewiasta Samarytańska: Jakoż ty będąc Żydem, żądasz ode mnie napoju, od niewiasty Samarytanki? (gdyż Żydowie nie obcują z Samarytany.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Odpowiedział Jezus i rzekł jej: Gdybyś wiedziała ten dar Boży, i kto jest ten, co ci mówi: Daj mi pić, ty byś go prosiła, a dałby ci wodę żywą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'I rzekła mu niewiasta: Panie! nie masz i czem naczerpać, a studnia jest głęboka, skądże tedy masz tę wodę żywą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Izażeś ty jest większy niżeli ojciec nasz Jakób, który nam dał tę studnię, i sam z niej pił, i synowie jego, i dobytek jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Odpowiedział Jezus i rzekł jej: Każdy, kto pije tę wodę, zasię będzie pragnął;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Lecz kto by pił onę wodę, którą ja mu dam, nie będzie pragnął na wieki; ale ta woda, którą ja mu dam, stanie się w nim studnią wody wyskakującej ku żywotowi wiecznemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Rzekła do niego niewiasta: Panie! daj mi tej wody, abym nie pragnęła, ani tu czerpać chodziła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Rzekł jej Jezus: Idź, zawołaj męża swego, a przyjdź tu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Odpowiedziała niewiasta i rzekła: Nie mam męża. Rzekł jej Jezus: Dobrześ rzekła: Nie mam męża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Albowiemeś pięciu mężów miała, a teraz ten, którego masz, nie jest mężem twoim; toś prawdę powiedziała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Rzekła mu niewiasta: Panie! widzę, żeś ty jest prorok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Ojcowie nasi na tej górze chwalili Boga, a wy powiadacie, że w Jeruzalemie jest miejsce, kędy przyzwoita chwalić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Rzekł jej Jezus: Niewiasto! wierz mi, iż idzie godzina, gdy ani na tej górze, ani w Jeruzalemie nie będziecie chwalili Ojca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Wy chwalicie, co nie wiecie; a my chwalimy, co wiemy; albowiem zbawienie jest z Żydów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Aleć idzie godzina, i teraz jest, gdy prawdziwi chwalcy będą chwalić Ojca w duchu i w prawdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Bo i Ojciec takowych szuka, którzy by go chwalili. Bóg jest duch, a ci, którzy go chwalą, powinni go chwalić w duchu i w prawdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Rzekła mu niewiasta: Wiem, że przyjdzie Mesyjasz, którego zowią Chrystusem, ten, gdy przyjdzie, oznajmi nam wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Rzekł jej Jezus: Jam jest ten, który z tobą mówię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'A wtem przyszli uczniowie jego, i dziwowali się, iż z niewiastą mówił; wszakże żaden nie rzekł: O co się pytasz, albo co z nią rozmawiasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'I zostawiła ona niewiasta wiadro swoje, a szła do miasta i rzekła onym ludziom:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Pójdźcie, oglądajcie człowieka, który mi powiedział wszystko, comkolwiek czyniła, nie tenci jest Chrystus?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'A przetoż wyszli z miasta i przyszli do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'A tymczasem prosili go uczniowie, mówiąc: Mistrzu! jedz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'A on im rzekł: Mamci ja pokarm ku jedzeniu, o którym wy nie wiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Mówili tedy uczniowie między sobą: Alboć mu kto przyniósł jeść?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Rzekł im Jezus: Mójci jest pokarm, abym czynił wolę tego, który mię posłał, a dokonał sprawy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Izaż wy nie mówicie, że jeszcze są cztery miesiące, a żniwo przyjdzie? Otoż powiadam wam: Podnieście oczy wasze, a przypatrzcie się krainom, żeć już białe są ku żniwu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'A kto żnie, bierze zapłatę, i zbiera owoc do żywota wiecznego, aby i ten, który sieje, radował się wespół, i ten, który żnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Albowiem w tem prawdziwe jest ono przysłowie: Że inszy jest, który sieje, a inszy, który żnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Jam was posłał, żąć to, około czegoście wy nie pracowali; insić pracowali, a wyście weszli w pracę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Tedy z miasta onego wiele Samarytanów uwierzyło weń dla powieści onej niewiasty, która świadczyła: Że mi wszystko powiedział, comkolwiek czyniła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Gdy tedy przyszli do niego Samarytanie, prosili go, aby u nich został; i został tam przez dwa dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'I daleko więcej ich uwierzyło dla słowa jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'A onej niewieście mówili: Iż już nie dla twojej powieści wierzymy; albowiemeśmy sami słyszeli i wiemy, że ten jest prawdziwie zbawiciel świata, Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'A po dwóch dniach wyszedł stamtąd i szedł do Galilei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Albowiem sam Jezus świadectwo wydał, iż prorok w ojczyźnie swojej nie jest we czci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'A gdy przyszedł do Galilei, przyjęli go Galilejczycy, widząc wszystko, co czynił w Jeruzalemie w święto; bo i oni byli przyszli na święto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Tedy zasię przyszedł Jezus do Kany Galilejskiej, gdzie był uczynił z wody wino. A był niektóry dworzanin królewski w Kapernaum, którego syn chorował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Ten usłyszawszy, iż Jezus przyszedł z Judzkiej ziemi do Galilei, szedł do niego i prosił go, aby zstąpił, a uzdrowił syna jego; bo poczynał umierać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'I rzekł do niego Jezus: Jeźli nie ujrzycie znamion i cudów, nie uwierzycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Rzekł mu on królewski dworzanin: Panie! zstąp pierwej niż umrze dziecię moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Rzekł mu Jezus: Idź, syn twój żyje. I uwierzył on człowiek mowie, którą mu powiedział Jezus, i poszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'A gdy już szedł, zabieżeli mu słudzy jego i oznajmili, mówiąc: Dziecię twoje żyje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Tedy ich pytał o godzinę, w którą by się lepiej miało; i rzekli mu, że wczoraj o siódmej godzinie opuściła go gorączka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Poznał tedy ojciec, iż to ona godzina była, której mu był rzekł Jezus: Iż syn twój żyje. I uwierzył sam i wszystek dom jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Tenci zasię wtóry cud uczynił Jezus, przyszedłszy z Judzkiej ziemi do Galilei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Było potem święto żydowskie, i wstąpił Jezus do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'A była w Jeruzalemie przy owczej bramie sadzawka, którą zowią po żydowsku Betesda, mająca pięć ganków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'W tych leżało mnóstwo wielkie niedołężnych, ślepych, chromych, wyschłych, którzy czekali poruszenia wody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Albowiem Anioł czasu pewnego zstępował w sadzawkę i poruszał wodę; a tak, kto pierwszy wstąpił po wzruszeniu wody, stawał się zdrowym, jakąbykolwiek chorobą zdjęty był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'A był tam niektóry człowiek trzydzieści i ośm lat chorobą złożony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Tego gdy Jezus ujrzał leżącego, a poznawszy, że już przez długi czas chorował, rzekł mu: Chcesz być zdrów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Odpowiedział mu on chory: Panie! nie ma człowieka, który by mię, gdy bywa poruszona woda, wrzucił do sadzawki; ale gdy ja idę, inszy przede mną wstępuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Rzekł mu Jezus: Wstań, weźmij łoże twoje, a chodź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'A zarazem stał się zdrowym on człowiek, i wziął łoże swoje, i chodził. A był sabat onego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Tedy rzekli Żydowie onemu uzdrowionemu: Sabat jest, nie godzi ci się łoża nosić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Odpowiedział im: Ten, który mię uzdrowił, tenże mi rzekł: Weźmij łoże twoje, a chodź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'I pytali go: Któryż jest ten człowiek, co ci powiedział: Weźmij łoże twoje, a chodź?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'A on uzdrowiony nie wiedział, kto by był; albowiem był Jezus ustąpił, ponieważ wiele ludu było na onem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Potem go Jezus znalazł w kościele i rzekł mu: Otoś się stał zdrowym, nie grzesz więcej, aby co gorszego na cię nie przyszło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'A odszedłszy on człowiek, powiedział Żydom, iż to był Jezus, który go uzdrowił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'A przetoż Żydowie prześladowali Jezusa i szukali, jakoby go zabili, że to uczynił w sabat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'A Jezus im odpowiedział: Ojciec mój aż dotąd pracuje, i ja pracuję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Dlatego tedy tem więcej szukali Żydowie, jakoby go zabili, nie tylko, iż gwałcił sabat, ale że i Ojca swego powiadał być Bogiem, czyniąc się równym Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Odpowiedział tedy Jezus i rzekł im: Zaprawdę, zaprawdę powiadam wam, nie może Syn sam od siebie nic czynić, jedno co widzi, że Ojciec czyni; albowiem cokolwiek on czyni, to także i Syn czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Boć Ojciec miłuje Syna i ukazuje mu wszystko, co sam czyni, i większe mu nad te sprawy pokaże, abyście się wy dziwowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Albowiem jako Ojciec wzbudza umarłe i ożywia, tak i Syn, które chce, ożywia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Bo Ojciec nikogo nie sądzi, lecz wszystek sąd dał Synowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Aby wszyscy czcili Syna, tak jako czczą Ojca; kto nie czci Syna, nie czci i Ojca, który go posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Zaprawdę, zaprawdę powiadam wam: Kto słowa mego słucha i wierzy onemu, który mię posłał, ma żywot wieczny i nie przyjdzie na sąd, ale przeszedł z śmierci do żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Zaprawdę, zaprawdę powiadam wam: Że idzie godzina i teraz jest, gdy umarli usłyszą głos Syna Bożego, a którzy usłyszą, żyć będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Albowiem jako Ojciec ma żywot sam w sobie, tak dał i Synowi, aby miał żywot w samym sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'I dał mu moc i sąd czynić; bo jest Synem człowieczym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Nie dziwujcież się temu; boć przyjdzie godzina, w którą wszyscy, co są w grobach, usłyszą głos jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'I pójdą ci, którzy dobrze czynili, na powstanie żywota; ale ci, którzy źle czynili, na powstanie sądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Nie mogęć ja sam od siebie nic czynić; jako słyszę, tak sądzę, a sąd mój jest sprawiedliwy; bo nie szukam woli mojej, ale woli tego, który mię posłał, Ojca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Jeźliżeć ja sam o sobie świadczę, świadectwo moje nie jest prawdziwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Inszy jest, co o mnie świadczy, i wiem, że prawdziwe jest świadectwo, które wydaje o mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Wyście słali do Jana, a on dał świadectwo prawdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Ale ja nie od człowieka świadectwo biorę, ale to mówię, abyście wy byli zbawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Onci był świecą gorejącą i świecącą, a wyście się chcieli do czasu poradować w światłości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Ale ja mam świadectwo większe niż Janowe; albowiem sprawy, które mi dał Ojciec, abym je wykonał, te same sprawy, które ja czynię, świadczą o mnie, iż mię Ojciec posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'A Ojciec, który mię posłał, onże świadczył o mnie, któregoście wy głosu nigdy nie słyszeli, aniście osoby jego widzieli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'I słowa jego nie macie w sobie mieszkającego; albowiem, którego on posłał, temu nie wierzycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Badajcież się Pism; boć się wam zda, że w nich żywot wieczny macie, a one są, które świadectwo wydawają o mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'A wżdy do mnie przyjść nie chcecie, abyście żywot mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Chwały od ludzi nie przyjmuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Alem was poznał, że miłości Bożej nie macie w sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Jam przyszedł w imieniu Ojca mego, a nie przyjmujecie mnie: jeźliżby przyszedł inny w imieniu swojem, onego przyjmiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Jakoż wy możecie wierzyć, chwałę jedni od drugich przyjmując, ponieważ chwały, która jest od samego Boga, nie szukacie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Nie mniemajcie, abym ja was miał oskarżać przed Ojcem; jestci, który skarży na was, Mojżesz, w którym wy nadzieję macie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Bo gdybyście wierzyli Mojżeszowi, wierzylibyście i mnie; gdyż on o mnie pisał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Ale ponieważ pismom jego nie wierzycie, i jakoż słowom moim uwierzycie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Potem odszedł Jezus za morze Galilejskie, które jest Tyberyjadzkie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'I szedł za nim lud wielki, iż widzieli cuda jego, które czynił nad chorymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'I wszedł Jezus na górę, i siedział tam z uczniami swoimi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'A była blisko wielkanoc, święto żydowskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Tedy podniósł Jezus oczy i ujrzawszy, iż wielki lud idzie do niego, rzekł do Filipa: Skąd kupimy chleba, aby ci jedli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, '(Ale to mówił, kusząc go; bo on wiedział, co miał czynić.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Odpowiedział mu Filip: Za dwieście groszy chleba nie dosyć im będzie, choćby każdy z nich mało co wziął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Rzekł mu jeden z uczniów jego, Andrzej, brat Szymona Piotra:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Jest tu jedno pacholę, co ma pięcioro chleba jęczmiennego i dwie rybki; ale cóż to jest na tak wielu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Tedy rzekł Jezus: Każcie ludowi usiąść. A było trawy dość na onemże miejscu, i usiadło mężów w liczbie około pięciu tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Wziął tedy Jezus one chleby, a podziękowawszy rozdał uczniom, a uczniowie siedzącym; także i z onych rybek, ile jedno chcieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'A gdy byli nasyceni, rzekł uczniom swoim: Zbierzcie te ułomki, które zbywają, żeby nic nie zginęło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'I zebrali i napełnili dwanaście koszów ułomków z onego pięciorga chleba jęczmiennego, które zbywały tym, co jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'A oni ludzie, ujrzawszy cud, który uczynił Jezus, mówili: Tenci jest zaprawdę on prorok, który miał przyjść na świat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Tedy Jezus poznawszy, iż mieli przyjść i porwać go, aby go uczynili królem, uszedł zasię sam tylko na górę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'A gdy był wieczór, zstąpili uczniowie jego do morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'A wstąpiwszy w łódź, jechali za morze do Kapernaum, a już było ciemno, a Jezus nie przyszedł był do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'A morze, gdy powstał wielki wiatr, burzyć się poczynało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Gdy tedy odpłynęli jakoby na dwadzieścia i pięć lub trzydzieści stajan, ujrzeli Jezusa chodzącego po morzu, przybliżającego się ku łodzi, i ulękli się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'A on im rzekł: Jamci jest, nie bójcie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'I wzięli go ochotnie do łodzi, a zarazem łódź przypłynęła do ziemi, do której jechali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Nazajutrz lud, który był za morzem, widząc, że tam nie było drugiej łodzi, tylko ona jedna, w którą byli wstąpili uczniowie jego, a iż Jezus nie wszedł był w łódź z uczniami swoimi, ale sami uczniowie jego ujechali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '(Przyszły też były drugie łodzie z Tyberyjady, blisko do onego miejsca, gdzie jedli chleb, gdy był Pan dzięki uczynił.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'To gdy obaczył lud, iż tam nie było Jezusa, ani uczniów jego, wstąpili i oni w łodzie i przeprawili się do Kapernaum, szukając Jezusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'A znalazłszy go za morzem, rzekli mu: Mistrzu! kiedyś tu przybył?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Odpowiedział im Jezus i rzekł: Zaprawdę, zaprawdę powiadam wam: Szukacie mię nie przeto, iżeście widzieli cuda, ale iżeście jedli chleb, i byliście nasyceni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Sprawujcież nie pokarm, który ginie, ale pokarm, który trwa ku żywotowi wiecznemu, który wam da Syn człowieczy; albowiem tego zapieczętował Bóg Ojciec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Rzekli tedy do niego: Cóż będziemy czynili, abyśmy sprawowali sprawy Boże?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Odpowiedział Jezus i rzekł im: Toć jest sprawa Boża, abyście wierzyli w tego, którego on posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Rzekli mu tedy: Cóż wżdy ty za znak czynisz, abyśmy widzieli i wierzyli tobie? Cóż czynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Ojcowie nasi jedli mannę na puszczy, jako jest napisano: Chleb z nieba dał im ku jedzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Rzekł im tedy Jezus: Zaprawdę, zaprawdę powiadam wam: Nie Mojżesz wam dał chleb z nieba, ale Ojciec mój daje wam chleb on prawdziwy z nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Albowiem chleb Boży ten jest, który zstępuje z nieba i żywot daje światu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Tedy mu rzekli: Panie! daj nam zawsze tego chleba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'I rzekł im Jezus: Jamci jest on chleb żywota; kto do mnie przychodzi, łaknąć nie będzie, a kto wierzy w mię, nigdy pragnąć nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Alem wam powiedział: Owszem, widzieliście mię, a nie wierzycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Wszystko, co mi daje Ojciec, do mnie przyjdzie, a tego, co do mnie przyjdzie, nie wyrzucę precz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Bom zstąpił z nieba, nie iżbym czynił wolę moję, ale wolę onego, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'A tać jest wola onego, który mię posłał, Ojca, abym z tego wszystkiego, co mi dał, nic nie stracił, ale abym to wzbudził w on ostateczny dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'A tać jest wola onego, który mię posłał, aby każdy, kto widzi Syna, a wierzy weń, miał żywot wieczny; a ja go wzbudzę w on ostateczny dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'I szemrali Żydowie o nim, iż rzekł: Jam jest on chleb, który z nieba zstąpił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'I mówili: Izaż ten nie jest Jezus, syn Józefa, którego my ojca i matkę znamy; jakoż teraz tedy ten powiada: Żem z nieba zstąpił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Tedy odpowiedział Jezus i rzekł im: Nie szemrzyjcie między sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Żaden do mnie przyjść nie może, jeźli go Ojciec mój, który mię posłał, nie pociągnie; a ja go wzbudzę w ostateczny dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Napisano w prorokach: I będą wszyscy wyuczeni od Boga; przetoż każdy, kto słyszał od Ojca, a nauczył się, przychodzi do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Nie iżby kto widział Ojca, oprócz tego, który jest od Boga; ten widział Ojca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Zaprawdę, zaprawdę powiadam wam: Kto w mię wierzy, ma żywot wieczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Jam jest on chleb żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Ojcowie wasi jedli mannę na puszczy, a pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Ten jest on chleb, który z nieba zstępuje; jeźliby go kto jadł, nie umrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Jamci jest chleb on żywy, którym z nieba zstąpił: jeźliby kto jadł z tego chleba, żyć będzie na wieki; a chleb, który ja dam, jest ciało moje, które ja dam za żywot świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Wadzili się tedy Żydowie między sobą, mówiąc: Jakoż ten może nam dać ciało swoje ku jedzeniu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'I rzekł im Jezus: Zaprawdę, zaprawdę powiadam wam: Jeźli nie będziecie jedli ciała Syna człowieczego, i pili krwi jego, nie macie żywota w sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Kto je ciało moje, a pije krew moję, ma żywot wieczny, a ja go wzbudzę w on ostateczny dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Albowiem ciało moje prawdziwie jest pokarm, a krew moja prawdziwie jest napój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Kto je ciało moje i pije krew moję, we mnie mieszka, a ja w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Jako mię posłał żyjący Ojciec, i ja żyję przez Ojca; tak kto mnie pożywa, i on żyć będzie przez mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Tenci jest chleb on, który z nieba zstąpił, nie jako ojcowie wasi jedli mannę, a pomarli; kto je ten chleb, żyć będzie na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'To mówił w bóżnicy, ucząc w Kapernaum.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Wiele ich tedy z uczniów jego słysząc to, mówili: Twardać to jest mowa, któż jej słuchać może?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Ale wiedząc Jezus sam w sobie, iż o tem szemrali uczniowie jego, rzekł im: Toż was obraża?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Cóż, gdybyście ujrzeli Syna człowieczego wstępującego, gdzie był pierwej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Duchci jest, który ożywia, ciało nic nie pomaga; słowa, które ja wam mówię, duch są i żywot są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Ale są niektórzy z was, co nie wierzą; albowiem wiedział od początku Jezus, którzy byli, co nie wierzyli, i kto jest, co go miał wydać;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'I mówił: Dlategomci wam powiedział: Iż żaden nie może przyjść do mnie, jeźliby mu nie było dane od Ojca mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Od tego czasu wiele uczniów jego odeszło nazad, a więcej z nim nie chodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Tedy rzekł Jezus do onych dwunastu: Izali i wy chcecie odejść?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'I odpowiedział mu Szymon Piotr: Panie! do kogóż pójdziemy? Ty masz słowa żywota wiecznego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'A myśmy uwierzyli i poznali, żeś ty jest Chrystus, on Syn Boga żywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Odpowiedział im Jezus: Izalim ja nie dwunastu was obrał? a jeden z was jest dyjabeł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'A to mówił o Judaszu, synu Szymona, Iszkaryjocie; bo go ten wydać miał, będąc jednym z onych dwunastu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'A potem chodził Jezus po Galilei; bo się nie chciał bawić w ziemi Judzkiej, przeto że Żydowie szukali, aby go zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'I było blisko święto żydowskie kuczek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Tedy rzekli do niego bracia jego: Odejdź stąd, a idź do Judzkiej ziemi, żeby uczniowie twoi widzieli sprawy twoje, które czynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Albowiem żaden nic w skrytości nie czyni, kto chce być widziany; przetoż ty, jeźli takie rzeczy czynisz, objaw się światu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Bo i bracia jego nie wierzyli weń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'I rzekł im Jezus: Czas mój jeszcze nie przyszedł; ale czas wasz zawsze jest w pogotowiu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Nie możeć was świat nienawidzieć, ale mnie nienawidzi; bo ja świadczę o nim, iż sprawy jego złe są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Idźcież wy na to święto, jać jeszcze nie pójdę na to święto; bo mój czas jeszcze się nie wypełnił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'A to im powiedziawszy, został w Galilei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'A gdy poszli bracia jego, tedy i on szedł na święto, nie jawnie, ale jakoby potajemnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'A Żydowie szukali go w święto i mówili: Gdzież on jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'I było o nim wielkie szemranie między ludem; bo jedni mówili: Że jest dobry; a drudzy mówili: Nie, ale zwodzi lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Wszakże o nim żaden jawnie nie mówił, dla bojaźni żydowskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'A gdy już było w pół święta, wstąpił Jezus do kościoła i uczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'I dziwowali się Żydowie, mówiąc: Jakoż ten umie Pismo, gdyż się nie uczył?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Odpowiedział im Jezus i rzekł: Nauka moja nie jestci moja, ale tego, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Jeźliby kto chciał czynić wolę jego, ten będzie umiał rozeznać, jeźli ta nauka jest z Boga, czyli ja sam od siebie mówię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Ktoć z samego siebie mówi, chwały własnej szuka; ale kto szuka chwały tego, który go posłał, ten jest prawdziwy, a nie masz w nim niesprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Izali wam Mojżesz nie dał zakonu? a żaden z was nie przestrzega zakonu. Przeczże szukacie, abyście mię zabili?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Odpowiedział lud i rzekł: Dyjabelstwo masz; któż cię szuka zabić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Odpowiedział Jezus i rzekł im: Jedenem uczynek uczynił, a wszyscy się temu dziwujecie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Wszak Mojżesz wydał wam obrzezkę, (nie iżby była z Mojżesza, ale z ojców), a w sabat obrzezujecie człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Ponieważ człowiek przyjmuje obrzezkę w sabat, aby nie był zgwałcony zakon Mojżeszowy, przecz się na mię gniewacie, żem całego człowieka uzdrowił w sabat?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Nie sądźcie według widzenia, ale sprawiedliwy sąd sądźcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Mówili tedy niektórzy z Jeruzalemczyków: Izali to nie jest ten, którego szukają zabić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'A oto jawnie mówi, a nic mu nie mówią. Izali prawdziwie poznali książęta, iż ten jest prawdziwie Chrystus?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Ale o tym wiemy, skąd jest: ale gdy Chrystus przyjdzie, nikt nie będzie wiedział, skąd by był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Wołał tedy Jezus w kościele ucząc a mówiąc: I mnie znacie, i skądem jest, wiecie; a nie przyszedłem sam od siebie, ale jest prawdziwy, który mię posłał, którego wy nie znacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Lecz go ja znam; bom od niego jest, a on mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'I szukali, jakoby go pojmać; ale żaden nie ściągnął nań ręki; bo jeszcze nie przyszła godzina jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'A wiele ich z ludu uwierzyli weń i mówili: Chrystus gdy przyjdzie, izaż więcej cudów uczyni nad te, które ten uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'A słyszeli Faryzeuszowie, iż to lud o nim szemrał; i posłali Faryzeuszowie i przedniejsi kapłani sługi, aby go pojmali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Rzekł im tedy Jezus: Jeszcze na mały czas jestem z wami; potem odejdę do tego, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Szukać mię będziecie, ale nie znajdziecie; a gdzie ja będę, wy przyjść nie możecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Mówili tedy Żydowie między sobą: Dokądże ten pójdzie, że my go nie znajdziemy? czyli do rozproszonych poganów pójdzie i będzie uczył pogany?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Cóż to za mowa, którą wyrzekł: Szukać mię będziecie, ale nie znajdziecie, i gdzie ja będę, wy przyjść nie możecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'A w on ostateczny dzień wielki święta onego stanął Jezus i wołał mówiąc: Jeźli kto pragnie, niech do mnie przyjdzie, a pije.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Kto wierzy w mię, jako mówi Pismo, rzeki wody żywej popłyną z żywota jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, '(A to mówił o Duchu, którego wziąć mieli wierzący weń; albowiem jeszcze nie był dany Duch Święty, przeto że jeszcze Jezus nie był uwielbiony.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Wiele ich tedy z owego ludu słysząc te słowa, mówili: Tenci jest prawdziwie on prorok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'A drudzy mówili: Ten jest Chrystus; ale niektórzy mówili: Azaż z Galilei przyjdzie Chrystus?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Azaż nie mówi Pismo, iż z nasienia Dawidowego i z Betlehemu miasteczka, gdzie był Dawid, przyjdzie Chrystus?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'A tak stało się rozerwanie dla niego między ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'I chcieli go niektórzy z nich pojmać; ale żaden nie ściągnął nań rąk swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Przyszli tedy słudzy do przedniejszych kapłanów i do Faryzeuszów; którzy im rzekli: Przeczżeście go nie przywiedli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Odpowiedzieli oni słudzy: Nigdy tak nie mówił człowiek jako ten człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'I odpowiedzieli im Faryzeuszowie: Alboście i wy zwiedzeni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Izali kto uwierzył weń z książąt albo z Faryzeuszów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Tylko ten gmin, który nie zna zakonu; przeklęci są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'I rzekł do nich Nikodem, który był przyszedł w nocy do niego, będąc jeden z nich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Izali zakon nasz sądzi człowieka, jeźliby pierwej nie słyszał od niego i nie poznałby, co czyni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'A oni mu odpowiedzieli i rzekli: Izaliś i ty Galilejczyk? Badajże się, a obacz, żeć prorok z Galilei nie powstał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'I poszedł każdy do domu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'A Jezus poszedł na górę Oliwną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'Potem zasię raniuczko przyszedł do kościoła, a lud wszystek zszedł się do niego; i siadłszy uczył je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'I przywiedli do niego nauczeni w Piśmie i Faryzeusze niewiastę na cudzołóstwie zastaną, a postawiwszy ją w pośrodku,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Rzekli mu: Nauczycielu! tę niewiastę zastano na samem uczynku cudzołóstwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'A w zakonie nam Mojżesz przykazał takie kamionować; a ty co mówisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'A to mówili kusząc go, aby go mogli oskarżyć. A Jezus schyliwszy się na dół, pisał palcem na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'A gdy się go nie przestawali pytać, podniósł się, rzekł do nich: Kto z was jest bez grzechu, niech na nią pierwszy kamieniem rzuci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'A zasię schyliwszy na dół, pisał na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'A gdy oni usłyszeli, będąc od sumienia przekonani, jeden za drugim wychodzili, począwszy od starszych aż do ostatecznych, iż tylko sam Jezus został, a ona niewiasta w pośrodku stojąca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'A podniósłszy się Jezus i żadnego nie widząc, tylko onę niewiastę, rzekł jej: Niewiasto! gdzież są oni, co na cię skarżyli? Żaden cię nie potępił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'A ona niewiasta rzekła: Żaden, Panie! A Jezus jej rzekł: Ani ja ciebie potępiam; idźże, a już więcej nie grzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Zasię im rzekł Jezus, mówiąc: Jam jest światłość świata; kto mię naśladuje, nie będzie chodził w ciemności, ale będzie miał światłość żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'I rzekli mu tedy Faryzeuszowie: Ty sam o sobie świadczysz, a świadectwo twoje nie jest prawdziwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Odpowiedział Jezus i rzekł im: Chociaż ja świadczę sam o sobie, jednak prawdziwe jest świadectwo moje; bo wiem, skądem przyszedł i dokąd idę; lecz wy nie wiecie, skądem przyszedł i dokąd idę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Wy według ciała sądzicie; ale ja nikogo nie sądzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'A choćbym i ja sądził, sąd mój jest prawdziwy; bom nie jest sam, ale ja i który mię posłał, Ojciec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'W zakonie waszym napisane jest: Iż dwojga ludzi świadectwo prawdziwe jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Jam jest, który sam o sobie świadczę; świadczy o mnie i ten, który mię posłał, Ojciec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Tedy mu rzekli: Gdzież jest ten twój Ojciec? Odpowiedział Jezus: Ani mnie znacie, ani Ojca mego; byście mnie znali, i Ojca byście mego znali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Te słowa mówił Jezus w skarbnicy, ucząc w kościele, a żaden go nie pojmał; bo jeszcze była nie przyszła godzina jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Rzekł im tedy zasię Jezus: Ja idę, i będziecie mię szukać, a w grzechu waszym pomrzecie; gdzie ja idę, wy przyjść nie możecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Mówili tedy Żydowie: Alboż się sam zabije, że mówi: Gdzie ja idę, wy przyjść nie możecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'I rzekł do nich: Wyście z niskości, a jam z wysokości; wyście z tego świata, a jam zasię nie jest z tego świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Przetomci wam powiedział, iż pomrzecie w grzechach waszych; bo jeźli nie wierzycie, żem ja jest, pomrzecie w grzechach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Tedy mu rzekli: Któżeś ty jest? I rzekł im Jezus: To, co wam z początku powiadam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Wieleć mam o was mówić i sądzić; ale ten, który mię posłał, jest prawdziwy, a ja, com od niego słyszał, to mówię na świecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Ale nie zrozumieli, że im o Ojcu mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Przetoż im rzekł Jezus: Gdy wywyższycie Syna człowieczego, tedy poznacie, żem ja jest, a sam od siebie nic nie uczynię, ale jako mię nauczył Ojciec mój, tak mówię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'A ten, który mię posłał, ze mną jest; nie zostawił mię samego Ojciec; bo co mu się podoba, to ja zawsze czynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'To gdy on mówił, wiele ich weń uwierzyło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Tedy mówił Jezus do tych Żydów, co mu uwierzyli: Jeźli wy zostaniecie w słowie mojem, prawdziwie uczniami moimi będziecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'Poznacie prawdę, a prawda was wyswobodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'I odpowiedzieli mu: Myśmy nasienie Abrahamowe, a nigdyśmy nie służyli nikomu; jakoż ty mówisz: Iż wolnymi będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Odpowiedział im Jezus: Zaprawdę, zaprawdę, powiadam wam, iż wszelki, kto czyni grzech, sługą jest grzechu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'A sługać nie mieszka w domu na wieki, ale Syn mieszka na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'A przetoż jeźli was Syn wyswobodzi, prawdziwie wolnymi będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Wiem, żeście nasienie Abrahamowe; lecz szukacie, abyście mię zabili, iż mowa moja nie ma u was miejsca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Ja com widział u Ojca mego, powiadam, a wy też to, coście widzieli u ojca waszego, czynicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Odpowiedzieli mu i rzekli: Ojciec nasz jest Abraham. Rzekł im Jezus: Byście byli synami Abrahamowymi, czynilibyście uczynki Abrahamowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Ale teraz szukacie, byście mię zabili, człowieka tego, którym wam prawdę mówił, którąm słyszał od Boga; tego Abraham nie czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Wy czynicie uczynki ojca waszego. Rzekli mu tedy: My z nierządu nie jesteśmy spłodzeni, jednegoż Ojca mamy, Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Tedy im rzekł Jezus: Być był Bóg Ojcem waszym, tedy byście mię miłowali, gdyżem ja od Boga wyszedł i przyszedłem, anim sam od siebie przyszedł, ale mię on posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Przeczże tej powieści mojej nie pojmujecie? przeto, iż nie możecie słuchać mowy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Wyście z ojca dyjabła i pożądliwości ojca waszego czynić chcecie; onci był mężobójcą od początku i w prawdzie nie został, bo w nim prawdy nie masz: gdy mówi kłamstwo, z swego własnego mówi, iż jest kłamcą i ojcem kłamstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'A ja, że prawdę mówię, nie wierzycie mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Któż mię z was obwini z grzechu? Jeźliż prawdę mówię, przeczże wy mi nie wierzycie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Ktoć z Boga jest, słów Bożych słucha; dlatego wy nie słuchacie, że z Boga nie jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Odpowiedzieli tedy Żydowie i rzekli mu: Izali my nie dobrze mówimy, żeś ty jest Samarytanin i dyjabelstwo masz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Odpowiedział Jezus: Jać dyjabelstwa nie mam, ale czczę Ojca mego; a wyście mię nie uczcili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Jać nie szukam chwały mojej; jest ten, który szuka i sądzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Zaprawdę, zaprawdę powiadam wam: Jeźli kto słowa moje zachowywać będzie, śmierci nie ogląda na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Tedy mu rzekli Żydowie: Terażeśmy poznali, że dyjabelstwo masz, Abraham umarł i prorocy, a ty powiadasz: Jeźli kto słowa moje zachowywać będzie, śmierci nie skosztuje na wieki;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Izaś ty nie większy nad ojca naszego Abrahama, który umarł? i prorocy pomarli; kimże się ty wżdy czynisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Odpowiedział Jezus: Jeźli się ja sam chwalę, chwała moja nic nie jest. Jestci Ojciec mój, który mię chwali, o którym wy powiadacie, że jest Bogiem waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Lecz go nie znacie, a ja go znam; i jeźlibym rzekł, że go nie znam, byłbym podobnym wam, kłamcą; ale go znam i słowa jego zachowuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, ojciec wasz, z radością żądał, aby oglądał dzień mój, i oglądał i radował się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Tedy rzekli Żydowie do niego: Pięćdziesiąt lat jeszcze nie masz, a Abrahamaś widział?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Rzekł im Jezus: Zaprawdę, zaprawdę powiadam wam: Pierwej niż Abraham był, jam jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Porwali tedy kamienie, aby nań ciskali; lecz Jezus schronił się, i wyszedł z kościoła, przechodząc przez pośrodek ich, i tak uszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'A mimo idąc, ujrzał człowieka ślepego od narodzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'I pytali go uczniowie jego, mówiąc: Mistrzu! któż zgrzeszył, ten czyli rodzice jego, iż się ślepym narodził?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Odpowiedział Jezus: Ani ten zgrzeszył, ani rodzice jego; ale żeby się okazały sprawy Boże na nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Jać muszę sprawować sprawy onego, który mię posłał, pokąd dzień jest; przychodzi noc, gdy żaden nie będzie mógł nic sprawować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Pókim jest na świecie, jestem światłością świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'To rzekłszy plunął na ziemię, a uczynił błoto z śliny i pomazał onem błotem oczy ślepego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'I rzekł mu: Idź, umyj się w sadzawce Syloe, co się wykłada posłany. Poszedł tedy i umył się, i przyszedł widząc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'A tak sąsiedzi i którzy go przedtem widywali ślepego, mówili: Izali nie ten jest, który siadał i żebrał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Drudzy mówili: Iż ten jest; a drudzy, iż jest jemu podobny. Lecz on mówił, żem ja jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Tedy mu rzekli: Jakoż są otworzone oczy twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'A on odpowiedział i rzekł: Człowiek, którego zowią Jezusem, uczynił błoto i pomazał oczy moje, a rzekł mi: Idź do sadzawki Syloe, a umyj się; a tak odszedłszy i umywszy się, przejrzałem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Tedy mu rzekli: Gdzież on jest? Rzekł: Nie wiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Tedy przywiedli onego, który przedtem był ślepy, do Faryzeuszów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'A był sabat, gdy Jezus uczynił błoto i otworzył oczy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Tedy go znowu pytali i Faryzeuszowie, jako przejrzał? A on im rzekł: Włożył mi błota na oczy, i umyłem się i widzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Tedy niektóry z Faryzeuszów rzekł: Człowiek ten nie jest z Boga; bo nie strzeże sabatu. Drudzy zasię mówili: Jakoż może człowiek grzeszny takowe cuda czynić? I było rozerwanie między nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Rzekli tedy ślepemu po wtóre: Ty co mówisz o nim, ponieważ otworzył oczy twoje? A on rzekł: Prorok jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'A nie wierzyli Żydowie o nim, żeby był ślepym, a że przejrzał, aż zawołali rodziców onego, który przejrzał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'I pytali ich, mówiąc: Tenże jest syn wasz, o którym wy powiadacie, iż się ślepo narodził? jakoż wżdy teraz widzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Odpowiedzieli im rodzice jego i rzekli: Wiemy, żeć to jest syn nasz, i że się ślepo narodził;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Lecz jako teraz widzi, nie wiemy, albo kto otworzył oczy jego, my nie wiemy; mać lata, pytajcież go, on sam o sobie powie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Tak mówili rodzice jego, że się bali Żydów; albowiem już byli Żydowie postanowili, aby ktokolwiek by go Chrystusem wyznał, był z bóżnicy wyłączony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Przetoż rzekli rodzice jego: Mać lata, pytajcież go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Tedy zawołali powtóre człowieka onego, który był ślepy, i rzekli mu: Daj chwałę Bogu; myć wiemy, iż ten człowiek jest grzeszny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'A on odpowiedział i rzekł: Jeźli grzeszny jest, nie wiem; to tylko wiem, iż będąc ślepym, teraz widzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'I rzekli mu znowu: Cóż ci uczynił? Jakoż otworzył oczy twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Odpowiedział im: Jużemci wam powiedział, a nie słyszeliście; przeczże jeszcze słyszeć chcecie? Izali i wy chcecie być uczniami jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Tedy mu złorzeczyli i rzekli: Ty bądź uczniem jego; aleśmy my uczniami Mojżeszowymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'My wiemy, że Bóg do Mojżesza mówił; lecz ten, skąd by był, nie wiemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Odpowiedział on człowiek i rzekł im: Toć zaprawdę rzecz dziwna, że wy nie wiecie, skąd jest, a otworzył oczy moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'A wiemy, iż Bóg grzeszników nie wysłuchiwa; ale jeźliby kto chwalcą Bożym był i wolę jego czynił, tego wysłuchiwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Od wieku nie słyszano, aby kto otworzył oczy ślepo narodzonego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Być ten nie był od Boga, nie mógłciby nic uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Odpowiedzieli i rzekli mu: Tyś się wszystek w grzechach narodził, a ty nas uczysz? I wygnali go precz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'A usłyszawszy Jezus, iż go precz wygnali i znalazłszy go, rzekł mu: Wierzyszże ty w Syna Bożego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'A on odpowiedział i rzekł: A któż jest, Panie! abym weń wierzył?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'I rzekł mu Jezus: I widziałeś go, i który mówi z tobą, onci jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'A on rzekł: Wierzę Panie! i pokłonił mu się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'I rzekł mu Jezus: Na sądemci ja przyszedł na ten świat, aby ci, którzy nie widzą, widzieli, a ci, którzy widzą, aby ślepymi byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'I usłyszeli to niektórzy z Faryzeuszów, którzy byli z nim, i rzekli mu: Izali i my ślepymi jesteśmy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Rzekł im Jezus: Byście byli ślepymi, nie mielibyście grzechu; lecz teraz mówicie, iż widzimy, przetoż grzech wasz zostaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Zaprawdę, zaprawdę powiadam wam: Kto nie wchodzi drzwiami do owczarni, ale wchodzi inędy, ten jest złodziej i zbójca;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Lecz kto wchodzi drzwiami, pasterzem jest owiec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Temu odźwierny otwiera i owce słuchają głosu jego, a on swoich własnych owiec z imienia woła i wywodzi je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'A gdy wypuści owce swoje, idzie przed niemi, a owce idą za nim; bo znają głos jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Ale za cudzym nie idą, lecz uciekają od niego; bo nie znają głosu obcych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Tę im przypowieść Jezus powiedział; lecz oni nie zrozumieli tego, co im mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Rzekł im tedy zasię Jezus: Zaprawdę, zaprawdę powiadam wam, iżem ja jest drzwiami owiec.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Wszyscy, ile ich przede mną przyszło, złodzieje są i zbójcy; ale ich nie słuchały owce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Jamci jest drzwiami; jeźli kto przez mię wnijdzie, zbawiony będzie, a wnijdzie i wynijdzie, a pastwisko znajdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Złodziej nie przychodzi, jedno żeby kradł, a zabijał i tracił; jam przyszedł, aby żywot miały, i obficie miały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Jam jest on dobry pasterz; dobry pasterz duszę swoję kładzie za owce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Lecz najemnik i ten, który nie jest pasterzem, którego nie są owce własne, widząc wilka przychodzącego, opuszcza owce i ucieka, a wilk porywa i rozprasza owce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'A najemnik ucieka, iż jest najemnik i nie ma pieczy o owcach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Jam jest on pasterz dobry i znam moje, a moje mię też znają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Jako mię zna Ojciec i ja znam Ojca, i duszę moję kładę za owce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'A mam i drugie owce, które nie są z tej owczarni, i teć muszę przywieść; i głosu mego słuchać będą, a będzie jedna owczarnia i jeden pasterz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Dlatego mię miłuje Ojciec, iż ja kładę duszę moję, abym ją zasię wziął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Żaden jej nie bierze ode mnie, ale ja kładę ją sam od siebie; mam moc położyć ją i mam moc zasię wziąć ją. Toć rozkazanie wziąłem od Ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Tedy się stało znowu rozerwanie między Żydami dla tych słów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'I mówiło ich wiele z nich: Dyjabelstwo ma i szaleje; czemuż go słuchacie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Drudzy mówili: Te słowa nie są dyjabelstwo mającego; izali dyjabeł może ślepych oczy otwierać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'A było w Jeruzalemie poświęcanie kościoła, a zima była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'I przechadzał się Jezus w kościele, w przysionku Salomonowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Tedy go obstąpili Żydowie i rzekli mu: Dokądże dusze nasze na rzeczy trzymasz? Jeźliżeś ty jest Chrystus, powiedz nam jawnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Odpowiedział im Jezus: Powiedziałem wam, a nie wierzycie; sprawy, które ja czynię w imieniu Ojca mego, te o mnie świadczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Ale wy nie wierzycie; bo nie jesteście z owiec moich, jakom wam powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Owce moje głosu mego słuchają, a ja je znam i idą za mną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'A ja żywot wieczny daję im i nie zginą na wieki, ani ich żaden wydrze z ręki mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Ojciec mój, który mi je dał, większy jest nad wszystkie, a żaden nie może ich wydrzeć z ręki Ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Ja i Ojciec jedno jesteśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Porwali tedy znowu kamienie Żydowie, aby go ukamionowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Odpowiedział im Jezus: Wiele dobrych uczynków ukazałem wam od Ojca mego, dla któregoż z tych uczynków kamionujecie mię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Odpowiedzieli mu Żydowie, mówiąc: Dla dobrego uczynku nie kamionujemy cię, ale dla bluźnierstwa, to jest, że ty będąc człowiekiem, czynisz się sam Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Odpowiedział im Jezus: Izali nie jest napisano w zakonie waszym: Jam rzekł: Bogowie jesteście?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Jeźliżeć one nazwał bogami, do których się stało słowo Boże, a nie może być Pismo skażone;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'A mnie, którego Ojciec poświęcił i posłał na świat, wy mówicie: Bluźnisz, żem rzekł: Jestem Synem Bożym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Jeźliż nie czynię spraw Ojca mego, nie wierzcież mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'A jeźliż czynię, chociażbyście mnie nie wierzyli, wierzcież uczynkom, abyście poznali i wierzyli, żeć Ojciec jest we mnie, a ja w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Tedy zasię szukali, jakoby go pojmać; ale uszedł z rąk ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'I odszedł zasię za Jordan na ono miejsce, gdzie przedtem Jan chrzcił, i tamże mieszkał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'A wiele ich do niego przychodziło i mówili: Janci wprawdzie żadnego cudu nie uczynił; wszakże wszystko, cokolwiek Jan o tym powiedział, prawdziwe było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'I wiele ich tam uwierzyło weń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'A był niektóry chory Łazarz z Betanii, z miasteczka Maryi i Marty, siostry jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, '(A to była ona Maryja, która pomazała Pana maścią, i ucierała nogi jego włosami swojemi, której brat Łazarz chorował.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Posłały tedy siostry do niego, mówiąc: Panie! oto ten, którego miłujesz, choruje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'A usłyszawszy to Jezus, rzekł: Ta choroba nie jest na śmierć, ale dla chwały Bożej, aby był uwielbiony Syn Boży przez nią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'A Jezus umiłował Martę i siostrę jej, i Łazarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'A gdy usłyszał, iż choruje, tedy został przez dwa dni na onemże miejscu, gdzie był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Lecz potem rzekł do uczniów swoich: Idźmy zasię do Judzkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Rzekli mu uczniowie: Mistrzu! teraz szukali Żydowie, jakoby cię ukamionowali, a zasię tam idziesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Odpowiedział Jezus: Azaż nie dwanaście jest godzin dnia? Jeźli kto chodzi we dnie, nie obrazi się; bo widzi światłość tego świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'A jeźli kto chodzi w nocy, obrazi się; bo w nim światła nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'To powiedziawszy, potem rzekł do nich: Łazarz, przyjaciel nasz, śpi; ale idę, abym go ze snu obudził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Tedy rzekli uczniowie jego: Panie! jeźliże śpi, będzie zdrów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Ale Jezus mówił o śmierci jego; lecz oni mniemali, iż o zaśnięciu snem mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Tedy im rzekł Jezus jawnie: Łazarz umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'I raduję się dla was, (abyście wierzyli), żem tam nie był; ale pójdziemy do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Rzekł zatem Tomasz, którego zwano Dydymus, spółuczniom: Pójdźmy i my, abyśmy z nim pomarli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Przyszedłszy tedy Jezus, znalazł go już cztery dni w grobie leżącego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, '(A była Betania blisko Jeruzalemu, jakoby na piętnaście stajan.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'A przyszło było wiele Żydów do Marty i Maryi, aby je cieszyli po bracie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Marta tedy, gdy usłyszała, że Jezus idzie, bieżała przeciwko niemu; ale Maryja w domu siedziała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'I rzekła Marta do Jezusa: Panie! byś tu był, nie umarłby był brat mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Ale i teraz wiem, że o cokolwiek byś prosił Boga, da ci to Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Rzekł jej Jezus: Wstanieć brat twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Rzekła mu Marta: Wiem, iż wstanie przy zmartwychwstaniu w on ostateczny dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'I rzekł jej Jezus: Jam jest zmartwychwstanie i żywot; kto w mię wierzy, choćby też umarł, żyć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'A wszelki, który żyje, a wierzy w mię, nie umrze na wieki. Wierzyszże temu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Rzekła mu: I owszem Panie! Jam uwierzyła, żeś ty jest Chrystus, Syn Boży, który miał przyjść na świat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'A to rzekłszy szła i potajemnie zawołała Maryję, siostrę swoję, mówiąc: jest tu nauczyciel, i woła cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Ona skoro usłyszała, wnet wstała i szła do niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, '(A Jezus jeszcze był nie przyszedł do miasteczka, ale był na temże miejscu, gdzie Marta była wyszła przeciwko niemu.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Żydowie tedy, którzy z nią byli w domu, a cieszyli ją, ujrzawszy Maryję, iż prędko wstała i wyszła, szli za nią, mówiąc: Idzie do grobu, aby tam płakała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Ale Maryja, gdy tam przyszła, gdzie był Jezus, ujrzawszy go, przypadła do nóg jego i rzekła: Panie! byś tu był, nie umarłby był brat mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Jezus tedy, gdy ją ujrzał płaczącą, i Żydy, którzy byli z nią przyszli, płaczące, rozrzewnił się w duchu i zafrasował się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'I rzekł: Gdzieście go położyli? Rzekli mu: Panie! pójdź, a oglądaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'I zapłakał Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Tedy rzekli Żydowie: Wej! jakoć go miłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'A niektórzy z nich mówili: Nie mógłże ten, który otworzył oczy ślepego, uczynić, żeby ten był nie umarł?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Ale Jezus zasię rozrzewniwszy się sam w sobie, przyszedł do grobu; a była jaskinia, a kamień był położony na niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'I rzekł Jezus: Odejmijcie ten kamień. Rzekła mu Marta, siostra onego umarłego: Panie! jużci cuchnie; bo już cztery dni w grobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Powiedział jej Jezus: Azażem ci nie rzekł, iż jeźli uwierzysz, oglądasz chwałę Bożą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Odjęli tedy kamień, gdzie był umarły położony. A Jezus podniósłszy oczy swe w górę, rzekł: Ojcze! dziękuję tobie, żeś mię wysłuchał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'A jamci wiedział, że mię zawsze wysłuchiwasz; alem to rzekł dla ludu wokoło stojącego, aby wierzyli, żeś ty mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'A to rzekłszy, zawołał głosem wielkim: Łazarzu! wynijdź sam!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'I wyszedł ten, który był umarł, mając związane ręce i nogi chustkami, a twarz jego była chustką obwiązana. Rzekł im Jezus: Rozwiążcie go, a niechaj odejdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Wiele tedy z Żydów, którzy byli przyszli do Maryi, a widzieli to, co uczynił Jezus, uwierzyło weń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Niektórzy też z nich odeszli do Faryzeuszów i powiedzieli im, co uczynił Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Tedy się zebrali przedniejsi kapłani i Faryzeuszowie w radę, i mówili: Cóż uczynimy? Albowiem ten człowiek wiele cudów czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'A jeźli go tak zaniechamy, wszyscy weń uwierzą, i przyjdą Rzymianie, a wezmą nam to miejsce nasze i lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'A jeden z nich, Kaifasz, będąc najwyższym kapłanem onego roku, rzekł im: Wy nic nie wiecie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'Ani myślicie, iż nam jest pożyteczno, żeby jeden człowiek umarł za lud, a żeby wszystek ten naród nie zginął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'A tegoć nie mówił sam od siebie, ale będąc najwyższym kapłanem roku onego, prorokował, iż Jezus miał umrzeć za on naród;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'A nie tylko za on naród, ale żeby też syny Boże rozproszone w jedno zgromadził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Od onego tedy dnia radzili się społem, aby go zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'A Jezus już nie chodził jawnie między Żydami, ale stamtąd odszedł do krainy, która jest blisko puszczy, do miasta, które zowią Efraim, i tamże mieszkał z uczniami swoimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'A była blisko wielkanoc żydowska, a wiele ich szło do Jeruzalemu z onej krainy przed wielkanocą, aby się oczyścili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'I szukali Jezusa, i mówili jedni do drugich, w kościele stojąc: Co się wam zda, że nie przyszedł na święto?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'A przedniejsi kapłani i Faryzeuszowie wydali byli rozkazanie: Jeźliby się kto dowiedział, gdzie by był, żeby oznajmił, aby go pojmali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Tedy Jezus szóstego dnia przed wielkanocą przyszedł do Betanii, kędy był Łazarz, który był umarł, którego wzbudził od umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Tamże mu sprawili wieczerzę, a Marta posługiwała, a Łazarz był jednym z onych, którzy z nim społem u stołu siedzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'A Maryja wziąwszy funt maści szpikanardowej bardzo drogiej, namaściła nogi Jezusowe, i utarła włosami swojemi nogi jego, i napełniony był on dom wonnością onej maści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Tedy rzekł jeden z uczniów jego, Judasz, syn Szymona, Iszkaryjot, który go miał wydać:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Przeczże tej maści nie sprzedano za trzysta groszy, a nie dano ubogim?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'A to mówił, nie iżby miał pieczą o ubogich, ale iż był złodziejem, i mieszek miał, a cokolwiek włożono, nosił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Tedy rzekł Jezus: Zaniechaj jej; na dzień pogrzebu mego to chowała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Albowiem ubogie zawsze z sobą macie, ale mnie nie zawsze mieć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Dowiedział się tedy lud wielki z Żydów, iż tam był, i przyszli nie tylko dla Jezusa, ale też aby Łazarza widzieli, którego był wzbudził od umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'I radzili się przedniejsi kapłani, żeby i Łazarza zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Bo wiele z Żydów dla niego odstępowali i wierzyli w Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Nazajutrz wielki lud, który był przyszedł na święto, usłyszawszy, iż Jezus idzie do Jeruzalemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Nabrali gałązek palmowych i wyszli naprzeciwko niemu i wołali: Hosanna! błogosławiony, który idzie w imieniu Pańskiem, król Izraelski!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'A dostawszy Jezus oślęcia, wsiadł na nie, jako jest napisane:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Nie bój się, córko Syońska! oto król twój idzie, siedząc na oślęciu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Ale tego z przodku nie zrozumieli uczniowie jego, ale gdy był Jezus uwielbiony, tedy wspomnieli, iż to było o nim napisane, a że mu to uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Świadczył tedy lud, który z nim był, iż Łazarza zawołał z grobu i wzbudził go od umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Dlatego też wyszedł przeciwko niemu lud, że słyszał, iż on ten cud uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Tedy mówili Faryzeuszowie między sobą: Widzicie, że nic nie sprawicie; oto świat za nim poszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'A byli niektórzy Grekowie z tych, którzy przychodzili do Jeruzalemu, żeby się modlili w święto.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Ci tedy przyszli do Filipa, który był z Betsaidy Galilejskiej, i prosili go, mówiąc: Panie, chcemy Jezusa widzieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Przyszedł Filip i powiedział Andrzejowi, a Andrzej zasię i Filip powiedzieli Jezusowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'A Jezus odpowiedział im, mówiąc: Przyszła godzina, aby był uwielbiony Syn człowieczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Zaprawdę, zaprawdę powiadam wam: Jeźliby ziarno pszeniczne wpadłszy do ziemi, nie obumarło, ono samo zostaje; lecz jeźliby obumarło, wielki pożytek przynosi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Kto miłuje duszę swoję, utraci ją, a kto nienawidzi duszy swojej na tym świecie, ku wiecznemu żywotowi strzeże jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Jeźli mnie kto służy, niechże mię naśladuje, a gdziem ja jest, tam i sługa mój będzie; a jeźli mnie kto służyć będzie, uczci go Ojciec mój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Terazci dusza moja zatrwożona jest; i cóż rzekę? Ojcze! zachowaj mię od tej godziny; alemci dlatego przyszedł na tę godzinę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Ojcze! uwielbij imię twoje. Przyszedł tedy głos z nieba: Uwielbiłem i jeszcze uwielbię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'A lud ten, który stał i słyszał, mówił: Zagrzmiało; a drudzy mówili: Anioł do niego mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Odpowiedział Jezus i rzekł: Nie dla mnie się ten głos stał, ale dla was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Teraz jest sąd świata tego, teraz książę świata tego precz wyrzucony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'A ja jeźli będę podwyższony od ziemi, pociągnę wszystkich do siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, '(A mówił to, oznajmując, jaką śmiercią miał umrzeć.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Odpowiedział mu on lud: Myśmy słyszeli z zakonu, iż Chrystus trwa na wieki; a jakoż ty mówisz, że musi być podwyższony Syn człowieczy? i któryż to jest Syn człowieczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Tedy im rzekł Jezus: Jeszcze do małego czasu jest z wami światłość; chodźcież tedy, póki światłość macie, żeby was ciemność nie ogarnęła; bo kto w ciemności chodzi, nie wie, kędy idzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Póki światłość macie, wierzcie w światłość, abyście byli synami światłości. To powiedział Jezus, a odszedłszy schronił się od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'A choć tak wiele cudów uczynił przed nimi, przecię nie uwierzyli weń,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'Aby się wypełniło słowo Izajasza proroka, które powiedział: Panie! i któż uwierzył kazaniu naszemu, a ramię Pańskie komuż jest objawione?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Dlatego uwierzyć nie mogli, iż jeszcze powiedział Izajasz:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Zaślepił oczy ich, i zatwardził serce ich, aby oczyma nie widzieli i sercem nie zrozumieli, i nie nawrócili się, abym je uzdrowił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'To powiedział Izajasz, gdy widział chwałę jego, i mówił o nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Wszakże jednak i z książąt wiele ich weń uwierzyło; ale dla Faryzeuszów nie wyznali, aby z bóżnicy nie byli wyłączeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Bo umiłowali chwałę ludzką więcej, niż chwałę Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'I wołał Jezus, a mówił: Kto wierzy w mię, nie w mię wierzy, ale w onego, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'I kto mię widzi, widzi onego, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Ja światłość przyszedłem na świat, aby żaden, kto wierzy w mię, w ciemnościach nie został.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'A jeźliby kto słuchał słów moich, a nie uwierzyłby, jać go nie sądzę; bom nie przyszedł, ażebym sądził świat, ale ażebym zbawił świat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Kto mną gardzi, a nie przyjmuje słów moich, ma kto by go sądził; słowa, którem ja mówił, one go osądzą w ostateczny dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Bom ja z siebie samego nie mówił, ale ten, który mię posłał, Ojciec, on mi rozkazanie dał, co bym mówił i co bym powiadać miał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'I wiem, że rozkazanie jego jest żywot wieczny; przetoż to, co ja wam mówię, jako mi powiedział Ojciec, tak mówię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'A przed świętem wielkanocnem wiedząc Jezus, iż przyszła godzina jego, aby przeszedł z tego świata do Ojca, umiłowawszy swoje, którzy byli na świecie, aż do końca umiłował je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'A gdy była wieczerza, a dyjabeł już był wrzucił w serce Judasza, syna Szymonowego Iszkaryjoty, aby go wydał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Widząc Jezus, iż wszystko Ojciec podał do rąk jego, a iż od Boga wyszedł i do Boga idzie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Wstał od wieczerzy i złożył szaty, a wziąwszy prześcieradło, przepasał się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Potem nalał wody do miednicy, i począł nogi umywać uczniom i ucierać prześcieradłem, którem był przepasany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Tedy przyszedł do Szymona Piotra; a on mu rzekł: Panie! i tyż mnie masz nogi umywać?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Odpowiedział Jezus, i rzekł mu: Co ja czynię, ty nie wiesz teraz, ale się potem dowiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Rzekł mu Piotr: Nie będziesz ty nóg moich umywał na wieki. Odpowiedział mu Jezus: Jeźli cię nie umyję, nie będziesz miał cząstki ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Tedy mu rzekł Szymon Piotr: Panie! nie tylko nogi moje, ale i ręce, i głowę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Rzekł mu Jezus: Ktoć jest umyty, nie potrzebuje, jedno aby nogi umył, bo czysty jest wszystek; i wy jesteście czystymi, ale nie wszyscy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Albowiem wiedział, który go wydać miał; dlategoż rzekł: Nie wszyscy jesteście czystymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Gdy tedy umył nogi ich i wziął szaty swoje, usiadłszy zasię za stół, rzekł im: Wiecież, com wam uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Wy mię nazywacie nauczycielem i Panem, a dobrze mówicie; bomci jest nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Ponieważem ja tedy umył nogi wasze, Pan i nauczyciel, i wyście powinni jedni drugim nogi umywać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Albowiem dałem wam przykład, abyście jakom ja wam uczynił, i wy czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Zaprawdę, zaprawdę powiadam wam: Nie jest sługa większy nad pana swego, ani poseł jest większy nad onego, który go posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Jeźlić to wiecie, błogosławieni jesteście, jeźli to uczynicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Nie o wszystkichci was mówię, jać wiem, którem obrał; ale żeby się wypełniło Pismo: Który je ze mną chleb, podniósł przeciwko mnie piętę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Teraz wam powiadam, przedtem niż się to stanie, abyście gdy się to stanie, uwierzyli, żem ja jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Zaprawdę, zaprawdę powiadam wam: Kto przyjmuje tego, którego bym posłał, mię przyjmuje; a kto mię przyjmuje, onego przyjmuje, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'To rzekłszy Jezus, zasmucił się w duchu, i oświadczył, a rzekł: Zaprawdę, zaprawdę powiadam wam, że jeden z was wyda mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Tedy uczniowie spoglądali po sobie, wątpiąc, o kim by to mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'A był jeden z uczniów jego, który się był położył na łonie Jezusowem, ten, którego miłował Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Przetoż na tego skinął Szymon Piotr, aby się wypytał, który by to był, o którym mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'A on położywszy się na piersiach Jezusowych, rzekł mu: Panie! któryż to jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Odpowiedział Jezus: Ten jest, któremu ja omoczywszy sztuczkę chleba, podam; a omoczywszy sztuczkę chleba, dał Judaszowi, synowi Szymona, Iszkaryjotowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'A zaraz po onej sztuczce chleba wstąpił weń szatan. Tedy mu rzekł Jezus: Co czynisz, czyń rychło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'A tego żaden nie zrozumiał z spółsiedzących, na co mu to rzekł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Albowiem niektórzy mniemali, gdyż Judasz miał mieszek, iż mu rzekł Jezus: Nakup, czego nam potrzeba na święto, albo iżby co dał ubogim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Tedy on wziąwszy onę sztuczkę chleba, zarazem wyszedł; a noc była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'A gdy wyszedł, rzekł Jezus: Teraz jest uwielbiony Syn człowieczy, a Bóg uwielbiony jest w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'A ponieważ Bóg uwielbiony jest w nim, tedy go też Bóg uwielbi sam w sobie, i wnetże uwielbi go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Synaczkowie! jeszcze maluczko jestem z wami; będziecie mię szukać, ale ja jakom rzekł Żydom: Gdzie ja idę, wy przyjść nie możecie; tak i wam teraz powiadam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Przykazanie nowe daję wam, abyście się społecznie miłowali; jakom i ja was umiłował, abyście się i wy społecznie miłowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Stądci poznają wszyscy, żeście uczniami moimi, jeźli miłość mieć będziecie jedni przeciwko drugim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Rzekł mu Szymon Piotr: Panie! dokądże idziesz? Odpowiedział mu Jezus: Dokąd ja idę, ty teraz za mną iść nie możesz, ale potem pójdziesz za mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Tedy mu rzekł Piotr: Panie! czemuż teraz za tobą iść nie mogę? Duszę moję za cię położę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Odpowiedział mu Jezus: Duszę twoję za mię położysz? Zaprawdę, zaprawdę powiadam ci: Nie zapieje kur, aż się mnie po trzykroć zaprzesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Niechaj się nie trwoży serce wasze; wierzycie w Boga i w mię wierzycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'W domu Ojca mego wiele jest mieszkania; a jeźli nie, wżdybymci wam powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Idę, abym wam zgotował miejsce; a gdy odejdę i zgotuję wam miejsce, przyjdę zasię i wezmę was do siebie, żebyście, gdziem ja jest, i wy byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'A dokąd ja idę, wiecie, i drogę wiecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Rzekł mu Tomasz: Panie! nie wiemy, dokąd idziesz, a jakoż możemy drogę wiedzieć?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Rzekł mu Jezus: Jamci jest ta droga, i prawda, i żywot; żaden nie przychodzi do Ojca, tylko przez mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Gdybyście mię znali, i Ojca byście też mego znali; i już go teraz znacie i widzieliście go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Rzekł mu Filip: Panie! ukaż nam Ojca, a dosyć nam na tem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Rzekł mu Jezus: Przez tak długi czas jestem z wami, a nie poznałeś mię? Filipie! kto mnie widzi, widzi i Ojca mego; jakoż ty mówisz: Ukaż nam Ojca?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Nie wierzysz, iżem ja w Ojcu, a Ojciec we mnie? Słowa, które ja do was mówię, nie od samego siebie mówię, lecz Ojciec, który we mnie mieszka, on czyni sprawy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Wierzcie mi, żem ja w Ojcu, a Ojciec we mnie; wżdy przynajmniej dla samych spraw wierzcie mi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Zaprawdę, zaprawdę powiadam wam: Kto wierzy w mię, sprawy które Ja czynię, i on czynić będzie, i większe nad te czynić będzie; bo ja odchodzę do Ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'A o cokolwiek prosić będziecie w imieniu mojem, to uczynię, aby był uwielbiony Ojciec w Synu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Jeźli o co będziecie prosić w imieniu mojem, ja uczynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Jeźli mię miłujecie, przykazania moje zachowajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'A ja prosić będę Ojca, a innego pocieszyciela da wam, aby z wami mieszkał na wieki,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Onego Ducha prawdy, którego świat przyjąć nie może; bo go nie widzi, ani go zna; lecz wy go znacie, gdyż u was mieszka i w was będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Nie zostawię was sierotami, przyjdę do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Jeszcze maluczko, a świat mię już więcej nie ogląda; lecz wy mię oglądacie; bo ja żyję, i wy żyć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'W on dzień wy poznacie, żem ja jest w Ojcu moim, a wy we mnie, i ja w was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Kto ma przykazania moje i zachowuje je, ten jest, który mię miłuje; a kto mię miłuje, będzie go też miłował Ojciec mój; i ja go miłować będę, i objawię mu siebie samego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Powiedział mu Judasz, nie on Iszkaryjot: Panie! cóż jest, że się nam objawić masz, a nie światu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Odpowiedział Jezus, i rzekł mu: Jeźli mię kto miłuje, słowo moje zachowywać będzie; i Ojciec mój umiłuje go, i do niego przyjdziemy, a mieszkanie u niego uczynimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Kto mię nie miłuje, słów moich nie zachowywuje; a słowo, które słyszycie, nie jest moje, ale onego, który mię posłał, Ojca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Tomci wam powiedział, u was mieszkając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Lecz pocieszyciel on, Duch Święty, którego pośle Ojciec w imieniu mojem, onci was nauczy wszystkiego, i przypomni wam wszystko, comkolwiek wam powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Pokój zostawuję wam, pokój on mój daję wam; nie jako daje świat, ja wam daję; niechże się nie trwoży serce wasze, ani się lęka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Słyszeliście, żem ja wam powiedział: Odchodzę, i zaś przyjdę do was. Gdybyście mię miłowali, wżdybyście się radowali, żem rzekł: Idę do Ojca; bo Ojciec mój większy jest niż ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'I terazem wam powiedział, przedtem niż się to stanie, żebyście gdy się to stanie, uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Już dalej z wami wiele mówić nie będę; albowiem idzie książę świata tego, a we mnie nic nie ma;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Ale iżby poznał świat, że miłuję Ojca, a jako mi rozkazał Ojciec, tak czynię. Wstańcież, pójdźmy stąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Jam jest ona winna macica prawdziwa, a Ojciec mój jestci winiarzem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Każdą latorośl, która we mnie owocu nie przynosi, odcina, a każdą, która przynosi owoc, oczyszcza, aby obfitszy owoc przyniosła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Już wy jesteście czystymi, dla słów, którem do was mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Mieszkajcież we mnie, a ja w was; jako latorośl nie może przynosić owocu sama z siebie, jeźli nie będzie trwała w winnej macicy, także ani wy, jeźli we mnie mieszkać nie będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Jam jest winna macica, a wyście latorośle; kto mieszka we mnie, a ja w nim, ten przynosi wiele owocu; bo beze mnie nic uczynić nie możecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Jeźliby kto nie mieszkał we mnie, precz wyrzucony będzie jako latorośl, i uschnie; i zbiorą je i na ogień wrzucą, i zgoreje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Jeźli we mnie mieszkać będziecie i słowa moje w was mieszkać będą, czegobyściekolwiek chcieli, proście, a stanie się wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'W tem będzie uwielbiony Ojciec mój, kiedy obfity owoc przyniesiecie, a będziecie moimi uczniami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Jako mię umiłował Ojciec, tak i ja umiłowałem was; trwajcież w miłości mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Jeźli przykazania moje zachowacie, trwać będziecie w miłości mojej, jakom i ja zachował przykazania Ojca mego i trwam w miłości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Tomci wam powiedział, aby wesele moje w was trwało, a wesele wasze było zupełne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Toć jest przykazanie moje, abyście się społecznie miłowali, jakom i ja was umiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Większej miłości nad tę żaden nie ma, jedno gdyby kto duszę swoję położył za przyjacioły swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Wy jesteście przyjaciele moi, jeźli czynić będziecie, cokolwiek ja wam przykazuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Jużci was dalej nie będę zwał sługami; bo sługa nie wie, co czyni pan jego; leczem was nazwał przyjaciółmi, bo wszystko, comkolwiek słyszał od Ojca mego, oznajmiłem wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Nie wyście mnie obrali, alem ja was obrał; i postanowiłem, abyście wyszli i przynieśli owoc, a owoc wasz aby trwał, i o cokolwiek byście prosili Ojca w imieniu mojem, żeby wam dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Toć wam przykazuję, abyście się społecznie miłowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Jeźli was świat nienawidzi, wiedzcie, żeć mię pierwej, niżeli was, miał w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Byście byli z świata, świat, co jest jego, miłowałby; lecz iż nie jesteście z świata, alem ja was wybrał z świata, przetoż was świat nienawidzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Wspomnijcie na słowo, którem ja wam powiedział: Nie jest sługa większy nad pana swego. Jeźlić mię prześladowali, i was prześladować będą; jeźli słowa moje zachowywali, i wasze zachowywać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Aleć wam to wszystko czynić będą dla imienia mego, iż nie znają onego, który mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Bym był nie przyszedł, a nie mówił im, nie mieliby grzechu; lecz teraz nie mają wymówki z grzechu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Kto mnie nienawidzi, i Ojca mego nienawidzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Bym był tych uczynków nie czynił między nimi, których żaden inszy nie czynił, grzechu by nie mieli; lecz teraz i widzieli i nienawidzili i mnie, i Ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Ale iżby się wypełniło słowo, które jest w zakonie ich napisane: Że mię darmo mieli w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'A gdy przyjdzie on pocieszyciel, którego ja wam poślę od Ojca, Duch prawdy, który od Ojca przychodzi, on o mnie świadczyć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Ale i wy świadczyć będziecie; bo ze mną od początku jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Tomci wam powiedział, abyście się nie gorszyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Wyłączać was będą z bóżnic; owszem przyjdzie godzina, że wszelki, który was zabije, będzie mniemał, że Bogu posługę czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'A toć wam uczynią, iż nie poznali Ojca ani mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Alemci wam to powiedział, abyście gdy przyjdzie ta godzina, wspomnieli na to, żem ja wam opowiedział; a tegom wam z początku nie powiadał, bom był z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Lecz teraz idę do onego, który mię posłał, a żaden z was nie pyta mię: Dokąd idziesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Ale żem wam to powiedział, smutek napełnił serce wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Lecz ja wam prawdę mówię, wamci to pożyteczno, abym ja odszedł; bo jeźli ja nie odejdę, pocieszyciel on nie przyjdzie do was, a jeźli odejdę, poślę go do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'A on przyszedłszy, będzie karał świat z grzechu i z sprawiedliwości, i z sądu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Z grzechu mówię, iż nie uwierzyli we mnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'Z sprawiedliwości zasię, iż do Ojca mego idę, a już mnie więcej nie ujrzycie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'Z sądu, iż książę tego świata już jest osądzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Mamci wam jeszcze wiele mówić, ale teraz znieść nie możecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Lecz gdy przyjdzie on Duch prawdy, wprowadzi was we wszelką prawdę; bo nie sam od siebie mówić będzie, ale cokolwiek usłyszy, mówić będzie, i przyszłe rzeczy wam opowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'On mię uwielbi; bo z mego weźmie, a opowie wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Wszystko, co ma Ojciec, moje jest; dlategom rzekł: Że z mego weźmie, a wam opowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Maluczko, a nie ujrzycie mię, i zasię maluczko, a ujrzycie mię; bo ja idę do Ojca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Mówili tedy niektórzy z uczniów jego między sobą: Cóż to jest, co nam mówi: Maluczko, a nie ujrzycie mię, i zasię maluczko, a ujrzycie mię, a iż ja idę do Ojca?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Przetoż mówili: Cóż to jest, co mówi: Maluczko? Nie wiemy, co mówi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Tedy Jezus poznał, że go pytać chcieli, i rzekł im: O tem się pytacie między sobą, żem rzekł: Maluczko, a nie ujrzycie mię, i zasię maluczko, a ujrzycie mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Zaprawdę, zaprawdę powiadam wam: Że wy będziecie płakać i narzekać, a świat się będzie weselił; wy smutni będziecie, ale smutek wasz obróci się wam w wesele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Niewiasta gdy rodzi, smutek ma, bo przyszła godzina jej; lecz gdy porodzi dzieciątko, już nie pamięta uciśnienia, dla radości, iż się człowiek na świat narodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'I wy teraz smutek macie; ale zasię ujrzę was, a będzie się radowało serce wasze, a radości waszej nikt nie odejmie od was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'A dnia onego nie będziecie mnie o nic pytać. Zaprawdę, zaprawdę powiadam wam: O cokolwiek byście prosili Ojca w imieniu mojem, da wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Dotąd o niceście nie prosili w imieniu mojem; proścież, a weźmiecie, aby radość wasza była doskonała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Tomci wam przez przypowieść mówił; ale idzie godzina, gdy już dalej nie przez przypowieści mówić wam będę, ale jawnie o Ojcu moim oznajmię wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'W on dzień w imieniu mojem prosić będziecie; a nie mówię wam: Iż ja będę Ojca prosił za wami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Albowiem sam Ojciec miłuje was, żeście wy mię umiłowali i uwierzyliście, żem ja od Boga przyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Wyszedłem od Ojca, a przyszedłem na świat; i zasię opuszczam świat, a idę do Ojca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Rzekli mu uczniowie jego: Oto teraz jawnie mówisz, a żadnej przypowieści nie powiadasz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Teraz wiemy, że wszystko wiesz, a nie potrzebujesz, aby cię kto pytał; przez to wierzymy, żeś od Boga wyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Odpowiedział im Jezus: Teraz wierzycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Oto przyjdzie godzina; owszem już przyszła, że się rozproszycie każdy do swego, a mię samego zostawicie; lecz nie jestem sam, bo Ojciec jest ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Tomci wam powiedział, abyście we mnie pokój mieli. Na świecie ucisk mieć będziecie; ale ufajcie, jam zwyciężył świat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'To powiedziawszy Jezus, podniósł oczy swoje w niebo i rzekł: Ojcze! przyszła godzina, uwielbij Syna twego, aby też i Syn twój uwielbił ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Jakoś mu dał moc nad wszelkiem ciałem, aby tym wszystkim, któreś mu dał, dał żywot wieczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'A toć jest żywot wieczny, aby cię poznali samego prawdziwego Boga, i któregoś posłał, Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Jam cię uwielbił na ziemi, i dokończyłem sprawę, którąś mi dał, abym ją czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'A teraz uwielbij mię ty, Ojcze! u siebie samego tą chwałą, którąm miał u ciebie, pierwej, niżeli świat był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Objawiłem imię twoje ludziom, któreś mi dał z świata; toć byli i dałeś mi je, i zachowali słowa twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'A teraz poznali, iż wszystko, coś mi dał, od ciebie jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Albowiem słowa, któreś mi dał, dałem im; a oni je przyjęli, i poznali prawdziwie, iżem od ciebie wyszedł, a uwierzyli, żeś ty mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Jać za nimi proszę, a nie za światem proszę, ale za tymi, któreś mi dał; bo twoi są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'I wszystko moje jest twoje, a twoje moje, i uwielbionym jest w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'A nie jestem więcej na świecie, ale oni są na świecie, a ja do ciebie idę. Ojcze święty, zachowaj je w imieniu twojem, któreś mi dał, aby byli jedno, jako i my.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Gdym z nimi był na świecie, jam je zachował w imieniu twojem, któreś mi dał; strzegłem ich i żaden z nich nie zginął, tylko on syn zatracenia, żeby się Pismo wypełniło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Ale teraz do ciebie idę i mówię to na świecie, aby mieli radość moję doskonałą w sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Jam im dał słowo twoje, a świat je miał w nienawiści; bo nie są z świata, jako i ja nie jestem z świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Nie proszę, abyś je wziął z świata, ale abyś je zachował ode złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Nie sąć z świata, jako i ja nie jestem z świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Poświęć je w prawdzie twojej; słowo twoje jest prawdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Jakoś ty mię posłał na świat, tak i ja posyłam je na świat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'A ja poświęcam samego siebie za nich, aby i oni poświęceni byli w prawdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Nie tylko za tymi proszę, lecz i za onymi, którzy przez słowo ich uwierzą w mię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Aby wszyscy byli jedno, jako ty, Ojcze! we mnie, a ja w tobie; aby i oni w nas jedno byli, aby świat uwierzył, żeś ty mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'A ja tę chwałę, którąś mi dał, dałem im, aby byli jedno, jako my jedno jesteśmy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Ja w nich, a ty we mnie, aby byli doskonałymi w jedno, a iżby poznał świat, żeś ty mię posłał, a iżeś je umiłował, jakoś i mię umiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Ojcze! któreś mi dał, chcę, abym gdziem ja jest, i oni byli ze mną, aby oglądali chwałę moję, którąś mi dał; albowiemeś mię umiłował przed założeniem świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Ojcze sprawiedliwy! i świat cię nie poznał; alem ja cię poznał, a i ci poznali, żeś ty mię posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'I uczyniłem im znajome imię twoje i znajome uczynię, aby miłość, którąś mię umiłował, w nich była, a ja w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'To powiedziawszy Jezus wyszedł z uczniami swoimi przez potok Cedron, gdzie był ogród, do którego on wszedł i uczniowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'A wiedział i Judasz, który go wydawał, ono miejsce; bo się tam często schadzał Jezus z uczniami swoimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Przetoż Judasz wziąwszy rotę i sługi od przedniejszych kapłanów i Faryzeuszów, przyszedł tam z latarniami i z pochodniami, i z broniami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Tedy Jezus wiedząc wszystko, co nań przyjść miało, wyszedłszy rzekł im: Kogo szukacie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Odpowiedzieli mu: Jezusa Nazareńskiego. Rzekł im Jezus: Jam jest. A stał z nimi i Judasz, który go wydawał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'A skoro im rzekł: Jam jest, postąpili nazad i padli na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Tedy ich zasię spytał: Kogo szukacie? A oni rzekli: Jezusa Nazareńskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Odpowiedział Jezus: Powiedziałem wam, żem ja jest; jeźli tedy mię szukacie, dopuśćcież tym odejść;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Aby się wypełniły słowa, które był powiedział: Nie straciłem żadnego z tych, któreś mi dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Tedy Szymon Piotr mając miecz, dobył go, i uderzył sługę kapłana najwyższego, i uciął mu ucho jego prawe; a temu słudze imię było Malchus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'I rzekł Jezus Piotrowi: Włóż miecz twój w pochwę; izali nie mam pić kielicha tego, który mi dał Ojciec?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Rota tedy i rotmistrz, i słudzy żydowscy pojmali Jezusa i związali go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'I wiedli go naprzód do Annasza; bo był świekier Kaifaszowy, który był najwyższym kapłanem roku onego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'A Kaifasz ten był, który Żydom radził, że pożyteczno jest, aby jeden człowiek umarł za lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'I szedł za Jezusem Szymon Piotr i drugi uczeń. A ten uczeń był znajomy najwyższemu kapłanowi, i wszedł z Jezusem do dworu najwyższego kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Ale Piotr stał u drzwi na dworze. Wyszedł tedy on drugi uczeń, który był znajomy najwyższemu kapłanowi, i mówił z odźwierną, i wprowadził tam Piotra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Tedy rzekła Piotrowi dziewka odźwierna: Izaliś i ty nie jest z uczniów tego człowieka? On odpowiedział: Nie jestem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Stali tedy słudzy i czeladź, uczyniwszy ogień, bo zimno było; i grzali się; był też z nimi Piotr, stojąc i grzejąc się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'A tak najwyższy kapłan pytał Jezusa o jego uczniów i o naukę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Odpowiedział mu Jezus: Jam jawnie mówił światu; Jam zawsze uczył w bóżnicy i w kościele, gdzie się zewsząd Żydowie schadzają, a potajemnie nicem nie mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Cóż mię pytasz? Pytaj tych, którzy słuchali, com im mówił; cić to wiedzą, com ja mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'A gdy on to mówił, jeden z sług, który tam stał, wyciął policzek Jezusowi, mówiąc: I także (to) odpowiadasz najwyższemu kapłanowi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Odpowiedział mu Jezus: Izalim źle rzekł, daj świadectwo o złem, a jeźlim dobrze, przeczże mię bijesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'I odesłał go Annasz związanego do Kaifasza, najwyższego kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'A Szymon Piotr stał i grzał się. I rzekli do niego: Azażeś i ty nie jest z uczniów jego? A on się zaprzał, mówiąc: Nie jestem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Rzekł mu niektóry z sług kapłana najwyższego, powinowaty onego, któremu był Piotr uciął ucho: Izażem ja ciebie nie widział w ogrodzie z nimi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Zaprzał się zasię Piotr, a zarazem kur zapiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Prowadzili tedy Jezusa od Kaifasza na ratusz, a było rano. I nie weszli sami na ratusz, aby się nie zmazali, ale iżby pożywali baranka wielkanocnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Tedy wyszedł do nich Piłat, i rzekł: Jakąż skargę przynosicie przeciwko człowiekowi temu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Odpowiedzieli mu i rzekli: Być ten nie był złoczyńcą, tedybyśmy ci go nie podali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'I rzekł Piłat: Weźmijcież go wy, a według zakonu waszego osądźcie go. Rzekli mu Żydowie: Nam się nie godzi zabijać nikogo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Aby się wypełniły słowa Jezusowe, które rzekł oznajmując, jaką miał śmiercią umrzeć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Tedy zasię wszedł Piłat na ratusz i zawołał Jezusa i rzekł mu: Tyżeś jest król żydowski?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Odpowiedział mu Jezus: A samże to od siebie mówisz, czylić insi powiedzieli o mnie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Odpowiedział Piłat: Azażem ja Żyd? Naród twój i przedniejsi kapłani podali mi cię; cóżeś wżdy uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Odpowiedział Jezus: Królestwo moje nie jest z tego świata; gdyby królestwo moje z tego świata było, wżdyć by mię słudzy moi bronili, abym nie był wydany Żydom; lecz teraz królestwo moje nie jest stąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Tedy mu rzekł Piłat: Toś ty przecię jest królem? Odpowiedział mu Jezus: Ty powiadasz, żem jest królem. Jam się na to narodził i na tom przyszedł na świat, abym świadectwo wydał prawdzie; wszelki, który jest z prawdy, słucha głosu mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Rzekł mu Piłat: Cóż jest prawda? A to rzekłszy, wyszedł zasię do Żydów i rzekł im: Ja w nim żadnej winy nie znajduję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'A też u was jest ten zwyczaj, abym wam jednego wypuścił na wielkanoc; chcecież tedy, abym wam wypuścił tego króla Żydowskiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Tedy zasię wszyscy zawołali, mówiąc: Nie tego, ale Barabbasza! A ten Barabbasz był zbójca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Tedy Piłat wziął Jezusa i ubiczował go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'A żołnierze uplótłszy koronę z cierni, włożyli na głowę jego i płaszczem szarłatowym przyodziali go,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'A mówili: Bądź pozdrowiony, królu żydowski! i dawali mu policzki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'I zasię wyszedł Piłat na dwór, i rzekł im: Oto go wam wywiodę na dwór, abyście wiedzieli, iż w nim żadnej winy nie znajduję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Tedy Jezus wyszedł na dwór, niosąc onę cierniową koronę i on płaszcz szarłatowy; i rzekł im Piłat: Oto człowiek!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'A gdy go ujrzeli przedniejsi kapłani i słudzy ich, zawołali mówiąc: Ukrzyżuj, ukrzyżuj go! Rzekł im Piłat: Weźmijcie go wy, a ukrzyżujcie, boć ja w nim żadnej winy nie znajduję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Odpowiedzieli mu Żydowie: Myć zakon mamy i według zakonu naszego ma umrzeć; bo się czynił Synem Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'A gdy Piłat usłyszał te słowa, bardziej się uląkł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'I wszedł zasię do ratusza i rzekł do Jezusa: Skądżeś ty jest? Lecz mu Jezus nie dał odpowiedzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Tedy mu rzekł Piłat: Nie mówisz ze mną? Nie wiesz, iż mam moc ukrzyżować cię i mam moc wypuścić cię?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Odpowiedział Jezus: Nie miałbyś żadnej mocy nade mną, jeźliby ci nie była dana z góry; przetoż, kto mię tobie wydał, większy grzech ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Odtąd Piłat starał się o to, jakoby go wypuścił; lecz Żydowie wołali mówiąc: Jeźli go wypuścisz, nie jesteś przyjacielem cesarskim; każdy bowiem, co się królem czyni, sprzeciwia się cesarzowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'A przetoż Piłat usłyszawszy te słowa, wywiódł Jezusa na dwór i siadł na stolicy, na miejscu, które zowią Litostrotos, a po żydowsku Gabbata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'A było to w dzień przygotowania przed wielkanocą, około szóstej godziny, i rzekł Piłat Żydom: Oto król wasz!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'A oni zawołali: Strać, strać! Ukrzyżuj go! Rzekł im Piłat: Królaż waszego ukrzyżuję? Odpowiedzieli przedniejsi kapłani: Nie mamy króla, tylko cesarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Tedy im go wydał, żeby był ukrzyżowany. I wzięli Jezusa i wywiedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'A on niosąc krzyż swój, wyszedł na ono miejsce, które zwano trupich głów, a po żydowsku zowią je Golgota;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Gdzie go ukrzyżowali, a z nim drugich dwóch z obu stron, a w pośrodku Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Napisał też Piłat i napis, i postawił nad krzyżem; a było napisane: Jezus Nazareński, król żydowski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'A ten napis czytało wiele Żydów; bo blisko miasta było ono miejsce, gdzie był ukrzyżowany Jezus; a było napisane po żydowsku, po grecku i po łacinie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Tedy rzekli Piłatowi przedniejsi kapłani żydowscy: Nie pisz król żydowski; ale iż on powiadał: Jestem królem żydowskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Odpowiedział Piłat: Com napisał, tom napisał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'A gdy żołnierze Jezusa ukrzyżowali, wzięli szaty jego i uczynili cztery części, każdemu żołnierzowi część, i suknią; a była ta suknia nie szyta, ale od wierzchu wszystka dziana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Tedy rzekli jedni do drugich: Nie krajmy jej, ale o nię rzućmy losy, czyja ma być; aby się Pismo wypełniło, które mówi: Podzielili między się szaty moje, a o odzienie moje los miotali. To tedy uczynili żołnierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'A stały podle krzyża Jezusowego matka jego i siostra matki jego, Maryja, żona Kleofaszowa, i Maryja Magdalena.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Tedy Jezus ujrzawszy matkę i ucznia, którego miłował, tuż stojącego, rzekł matce swojej: Niewiasto, oto syn twój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Potem rzekł uczniowi: Oto matka twoja! a od onej godziny wziął ją on uczeń do siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Potem widząc Jezus, iż się już wszystko wykonało, aby się wypełniło Pismo, rzekł: Pragnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'A było tam naczynie postawione octu pełne; tedy oni napełniwszy gąbkę octem, a obłożywszy (ją) hizopem podali do ust jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'A gdy Jezus skosztował octu, rzekł: Wykonało się; a nachyliwszy głowę, oddał ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Tedy Żydowie, aby ciała na krzyżu na sabat nie zostały, ponieważ był dzień przygotowania, (albowiem był wielki on dzień sabatu,) prosili Piłata, aby im golenie połamano, i zdjęto je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Przyszli tedy żołnierze, a pierwszemu wprawdzie złamali golenie i drugiemu, który z nim był ukrzyżowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Ale do Jezusa przyszedłszy, gdy ujrzeli, że już umarł, nie łamali goleni jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Lecz jeden z żołnierzy włócznią otworzył bok jego, a zarazem wyszła krew i woda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'A ten, co to widział, świadczył o tem i prawdziwe jest świadectwo jego; a on wie, iż prawdę powiada, abyście wy wierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Albowiem się to stało, aby się wypełniło Pismo: Kość jego nie będzie złamana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'I zasię drugie Pismo mówi: Ujrzą, kogo przebodli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'A potem prosił Piłata Józef z Arymatyi, (który był uczniem Jezusowym, ale tajemnym dla bojaźni żydowskiej), aby zdjął ciało Jezusowe. I pozwolił Piłat. Szedł tedy i zdjął ciało Jezusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Przyszedł też i Nikodem, (który był przedtem przyszedł w nocy do Jezusa), niosąc zmieszanej myrry i aloes, około sta funtów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Wzięli tedy ciało Jezusowe i uwinęli je w prześcieradła z onemi rzeczami wonnemi, jako jest zwyczaj Żydom umarłe chować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'A był na onem miejscu, gdzie był ukrzyżowany, ogród, a w ogrodzie grób nowy, w którym jeszcze nikt nie był położony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Przetoż tam dla dnia przygotowania żydowskiego, iż on grób był blisko, położyli Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'A pierwszego dnia po sabacie Maryja Magdalena przyszła rano do grobu, gdy jeszcze było ciemno, i ujrzała kamień odwalony od grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'I bieżała, a przyszła do Szymona Piotra i do onego drugiego ucznia, którego miłował Jezus, i rzekła im: Wzięli Pana z grobu, a nie wiemy, gdzie go położyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Tedy wyszedł Piotr i on drugi uczeń, a szli do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'I bieżeli obaj społem; ale on drugi uczeń wyścignął Piotra i pierwej przyszedł do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'A nachyliwszy się, ujrzał leżące prześcieradła; wszakże tam nie wszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Przyszedł też i Szymon Piotr, idąc za nim, i wszedł w grób, i ujrzał prześcieradła leżące,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'I chustkę, która była na głowie jego, nie z prześcieradłami położoną, ale z osobna na jednem miejscu zwiniętą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Potem wszedł i on drugi uczeń, który był pierwej przyszedł do grobu, i ujrzał, a uwierzył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Albowiem jeszcze nie rozumieli Pisma, iż miał zmartwychwstać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'I odeszli zaś oni uczniowie do domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Ale Maryja stała u grobu, na dworze płacząc; a gdy płakała, nachyliła się w grób.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'I ujrzała dwóch Aniołów w bieli siedzących, jednego u głowy, a drugiego u nóg, tam gdzie było położone ciało Jezusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Którzy jej rzekli: Niewiasto! czemu płaczesz? Rzekła im: Iż wzięli Pana mego, a nie wiem, gdzie go położyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'A to rzekłszy, obróciła się nazad i ujrzała Jezusa stojącego; lecz nie wiedziała, iż Jezus był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Rzekł jej Jezus: Niewiasto! czemu płaczesz? kogo szukasz? A ona mniemając, że był ogrodnik, rzekła mu: Panie! jeźliś go ty wziął, powiedz mi, gdzieś go położył, a ja go wezmę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Rzekł jej Jezus: Maryjo! Która obróciwszy się, rzekła mu: Rabbuni! co się wykłada: Nauczycielu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Rzekł jej Jezus: Nie dotykaj się mnie, bom jeszcze nie wstąpił do Ojca mego; ale idź do braci moich, a powiedz im: Wstępuję do Ojca mego i Ojca waszego, i do Boga mego i Boga waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Tedy przyszła Maryja Magdalena, oznajmując uczniom, że widziała Pana, a że jej to powiedział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'A gdy był wieczór dnia onego pierwszego po sabacie, a drzwi były zamknięte, gdzie byli uczniowie zgromadzeni dla bojaźni żydowskiej, przyszedł Jezus i stanął w pośrodku nich, i rzekł im: Pokój wam!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'A to rzekłszy pokazał im ręce i bok swój; a uradowali się uczniowie, ujrzawszy Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Rzekł im zasię Jezus: Pokój wam; jako mię posłał Ojciec, tak i ja was posyłam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'A to rzekłszy tchnął na nie i rzekł im: Weźmijcie Ducha Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Którymkolwiek grzechy odpuścicie, są im odpuszczone, a którymkolwiek zatrzymacie, są zatrzymane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'A Tomasz, jeden ze dwunastu, którego zowią Dydymus, nie był z nimi, gdy był przyszedł Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'I rzekli mu drudzy uczniowie: Widzieliśmy Pana. Ale im on rzekł: Jeźli nie ujrzę w ręku jego znaków gwoździ, a nie włożę palca mego w znaki gwoździ, a nie włożę ręki mojej w bok jego, nie uwierzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'A po ośmiu dniach byli zasię uczniowie jego w domu, i Tomasz z nimi. I przyszedł Jezus, gdy były drzwi zamknięte, a stanął w pośrodku nich, i rzekł: Pokój wam!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Potem rzekł Tomaszowi: Włóż sam palec twój, a oglądaj ręce moje i ściągnij rękę twoję, i włóż ją w bok mój, a nie bądź niewiernym, ale wiernym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Tedy odpowiedział Tomasz i rzekł mu: Panie mój, i Boże mój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Rzekł mu Jezus: Żeś mię ujrzał, Tomaszu, uwierzyłeś; błogosławieni którzy nie widzieli, a uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Wieleć i innych cudów uczynił Jezus przed oczyma uczniów swoich, które nie są napisane w tych księgach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Ale te są napisane, abyście wy wierzyli, że Jezus jest Chrystus, Syn Boży, a żebyście wierząc żywot mieli w imieniu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Potem się zaś ukazał Jezus uczniom u morza Tyberyjadzkiego, a ukazał się tak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Byli pospołu Szymon Piotr i Tomasz, którego zowią Dydymus, i Natanael, który był z Kany Galilejskiej, i synowie Zebedeuszowi, i drudzy dwaj z uczniów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Rzekł im Szymon Piotr: Pójdę ryby łowić. Mówią mu: Pójdziemy i my z tobą. I szli, i wnet wstąpili w łódź, a onej nocy nic nie pojmali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'A gdy już było rano, stanął Jezus na brzegu; wszakże nie wiedzieli uczniowie, żeby był Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Rzekł im tedy Jezus: Dzieci! a macież co jeść? Odpowiedzieli mu: Nie mamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'A on im rzekł: Zapuśćcie sieć po prawej stronie łodzi, a znajdziecie. I zapuścili, a już dalej nie mogli jej ciągnąć przed mnóstwem ryb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'I rzekł on uczeń, którego miłował Jezus Piotrowi: Pan jest. Szymon tedy Piotr, usłyszawszy iż Pan jest, przepasał się koszulą, (albowiem był nagi) i rzucił się w morze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'A drudzy zasię uczniowie przybyli w łodzi; (bo niedaleko było od brzegu, ale jakoby na dwieście łokci) ciągnąc sieć z rybami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'A gdy wstąpili na brzeg, ujrzeli węgle nałożone, i rybę na nich leżącą i chleb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Rzekł im Jezus: Przynieście z tych ryb, któreście teraz pojmali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Wstąpił tedy Szymon Piotr i wyciągnął sieć na ziemię, pełną wielkich ryb, których było sto pięćdziesiąt i trzy; a choć ich tak wiele było, nie zdarła się sieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Rzekł im Jezus: Pójdźcie, obiadujcie. I żaden z uczniów nie śmiał go pytać: Ty ktoś jest? wiedząc, że jest Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Tedy przyszedł Jezus i wziął on chleb, i dał im, także i rybę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'A toć już trzeci raz ukazał się Jezus uczniom swoim po zmartwychwstaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'A gdy obiad odprawili, rzekł Jezus Szymonowi Piotrowi: Szymonie Jonaszowy, miłujesz mię więcej niżeli ci? Rzekł mu: Tak jest, Panie! ty wiesz, że cię miłuję. Rzekł mu: Paśże baranki moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Rzekł mu zasię po wtóre: Szymonie Jonaszowy! miłujesz mię? Rzekł mu: Tak jest, Panie! ty wiesz, że cię miłuję. Rzekł mu: Paśże owce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Rzekł mu po trzecie: Szymonie Jonaszowy! miłujesz mię? I zasmucił się Piotr, że mu po trzecie rzekł: Miłujesz mię? I odpowiedział mu: Panie! ty wszystko wiesz, ty znasz, że cię miłuję. Rzekł mu Jezus: Paśże owce moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Zaprawdę, zaprawdę powiadam tobie: Gdyś był młodszym, opasywałeś się i chodziłeś, kędyś chciał; lecz gdy się zestarzejesz, wyciągniesz ręce twoje, a inny cię opasze i poprowadzi, gdzie byś nie chciał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'A to powiedział, dając znać, jaką śmiercią miał uwielbić Boga. A to powiedziawszy, rzekł mu: Pójdź za mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'A Piotr obróciwszy się, ujrzał onego ucznia, którego miłował Jezus, pozad idącego, który się też był położył przy wieczerzy na piersiach jego, i rzekł był: Panie! któryż jest ten, co cię wyda?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Tego ujrzawszy Piotr, rzekł Jezusowi: Panie! a ten co?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Rzekł mu Jezus: Jeźlibym chciał, żeby on został, aż przyjdę, co tobie do tego? Ty pójdź za mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'I wyszła ta powieść między braci, żeby on uczeń umrzeć nie miał. Lecz mu nie rzekł Jezus, iż nie miał umrzeć; ale: Jeźli chcę, aby został aż przyjdę, cóż tobie do tego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Tenci jest on uczeń, który świadczy o tem, i to napisał; a wiemy, że prawdziwe jest świadectwo jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Jest też jeszcze i innych wiele rzeczy, które czynił Jezus; które gdyby miały być wszystkie z osobna spisane, tuszę, iż i sam świat nie mógłby ogarnąć ksiąg, które by napisane były. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Pierwsze wprawdzie księgi napisałem, o Teofilu! o wszystkiem, co począł Jezus i czynić, i uczyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Aż do dnia onego, którego dawszy rozkazanie Apostołom, które był przez Ducha Świętego obrał, wzięty jest w górę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Którym też samego siebie po męce swojej żywym stawił w wielu niewątpliwych dowodach, przez czterdzieści dni ukazując się im i mówiąc o królestwie Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'A zgromadziwszy je przykazał im, aby nie odchodzili z Jeruzalemu, ale iżby czekali obietnicy ojcowskiej, o którejście mówić słyszeli ode mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Albowiemci Jan chrzcił wodą; ale wy będziecie ochrzczeni Duchem Świętym po niewielu tych dniach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'A tak oni zszedłszy się, pytali go, mówiąc: Panie! izali w tym czasie naprawisz królestwo Izraelskie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Lecz on rzekł do nich: Nie wasza rzecz jest, znać czasy i chwile, które Ojciec w swojej mocy położył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Ale przyjmiecie moc Ducha Świętego, który przyjdzie na was; i będziecie mi świadkami i w Jeruzalemie, i we wszystkiej Judzkiej ziemi, i w Samaryi, aż do ostatniego kraju ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'A to rzekłszy, gdy oni patrzali, w górę podniesiony jest, a obłok wziął go od oczów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'A gdy za nim do nieba idącym pilnie patrzali, oto dwaj mężowie stanęli przy nich w białem odzieniu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'I rzekli: Mężowie Galilejscy! przecz stoicie, patrząc w niebo? Ten Jezus, który w górę wzięty jest od was do nieba, tak przyjdzie, jakoście go widzieli idącego do nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Tedy się wrócili do Jeruzalemu od góry, którą zowią oliwną, która jest blisko Jeruzalemu, mając drogi przez jeden sabat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'A gdy weszli, wstąpili na salę, gdzie mieszkali Piotr, i Jakób, i Jan, i Andrzej, i Filip, i Tomasz, Bartłomiej, i Mateusz, Jakób Alfeuszowy, i Szymon Zelotes, i Judas Jakóbowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Ci wszyscy trwali jednomyślnie na modlitwie i prośbach, z żonami i z Maryją, matką Jezusową, i z braćmi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'A w oneż dni, powstawszy Piotr w pośrodku uczniów, rzekł: (A był poczet osób wespół zgromadzonych około sta i dwudziestu):');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Mężowie bracia! musiało się wypełnić ono pismo, które opowiedział Duch Święty przez usta Dawidowe o Judaszu, który był wodzem tych, co pojmali Jezusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Bo był policzony z nami i dostał był cząstki tego usługiwania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Tenci wprawdzie otrzymał rolę z zapłaty niesprawiedliwości, a powiesiwszy się, rozpukł się na poły i wypłynęły wszystkie wnętrzności jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'I było to jawne wszystkim mieszkającym w Jeruzalemie, tak iż nazwano onę rolę własnym ich językiem Akieldama, to jest rola krwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Albowiem napisano w księgach Psalmów: Niechaj będzie mieszkanie jego puste, a niech nie będzie, kto by w niem mieszkał, a biskupstwo jego niech weźmie inny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Potrzeba tedy, aby jeden z tych mężów, którzy z nami bywali po wszystek czas, który Pan Jezus przebywał między nami,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'Począwszy od chrztu Janowego, aż do tego dnia, którego jest wzięty w górę od nas, był z nami świadkiem zmartwychwstania jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'I postawili dwóch: Józefa, którego zwano Barsabaszem, którego też nazywano Justem, i Macieja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'A modląc się mówili: Ty Panie! który znasz serca wszystkich, okaż z tych dwóch jednego, któregoś obrał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Aby przyjął cząstkę usługiwania tego i apostolstwa, z którego wypadł Judasz, aby odszedł na miejsce swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'I rzucili losy ich. I padł los na Macieja; a przyłączony jest spólnem zdaniem do jedenastu Apostołów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'A gdy przyszedł dzień pięćdziesiąty, byli wszyscy jednomyślnie pospołu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Tedy się stał z prędka z nieba szum, jakoby przypadającego wiatru gwałtownego i napełnił wszystek dom, kędy siedzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'I ukazały się im rozdzielone języki na kształt ognia, który usiadł na każdym z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'I napełnieni są wszyscy Duchem Świętym, a poczęli mówić innemi językami, jako im Duch on dawał wymawiać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'A byli w Jeruzalemie mieszkający Żydowie, mężowie nabożni, z każdego narodu tych, którzy są pod niebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'A gdy się stał ten głos, zeszło się mnóstwo ludzi i strwożyli się, że je słyszał każdy z nich mówiące własnym językiem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'I zdumiewali się wszyscy, i dziwowali się, mówiąc jedni do drugich: Izali oto ci wszyscy, którzy mówią, nie są Galilejczycy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'A jakoż my od nich słyszymy każdy z nas swój własny język, w którymeśmy się urodzili?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Partowie i Medowie, i Elamitowie, i którzy mieszkamy w Mezopotamii, w Judzkiej ziemi, i w Kapadocyi, w Poncie, i w Azyi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'W Frygii, i w Pamfilii, w Egipcie, i w stronach Libii, która jest podle Cyreny, i przychodniowie Rzymscy; Żydowie, i nowonawróceni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Kreteńczycy, i Arabczycy; słyszymy ich, mówiących językami naszemi wielkie sprawy Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'I zdumiewali się wszyscy, i dziwowali się, mówiąc jeden do drugiego: Cóż to wżdy ma być?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Lecz drudzy naśmiewając się, mówili: Ci się młodem winem popili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'A stanąwszy Piotr z jedenastoma, podniósł głos swój i przemówił do nich: Mężowie Judzcy i wszyscy, którzy mieszkacie w Jeruzalemie! niech wam to jawno będzie, a przyjmijcie w uszy słowa moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Albowiem nie są ci, jako wy mniemacie, pijani, gdyż dopiero jest trzecia na dzień godzina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Aleć to jest ono, co przepowiedziano przez proroka Joela:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'I będzie w ostateczne dni, (mówi Bóg): Wyleję z Ducha mego na wszelkie ciało, a prorokować będą synowie wasi i córki wasze, a młodzieńcy wasi widzenia widzieć będą, a starcom waszym sny się śnić będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Nawet w oneż dni na sługi moje i na służebnice moje wyleję z Ducha mego, i będą prorokować;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'I ukażę cuda na niebie w górze i znamiona na ziemi nisko, krew, i ogień, i parę dymu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Słońce się obróci w ciemność, a księżyc w krew, przedtem niż przyjdzie on dzień Pański wielki i znaczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'I stanie się, że ktobykolwiek wzywał imienia Pańskiego, zbawion będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Mężowie Izraelscy! słuchajcie słów tych Jezusa, onego Nazareńskiego, męża od Boga wsławionego u was mocami i cudami, i znamionami, które czynił Bóg przez niego w pośrodku was, jako i wy sami wiecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'Tego za ułożoną radą i przejrzeniem Bożem wydanego wziąwszy, a przez ręce niezbożników ukrzyżowawszy, zabiliście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Którego Bóg wzbudził, rozwiązawszy boleści śmierci, jakoż było to niepodobne, aby od niej miał być zatrzymany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Albowiem o nim mówi Dawid: Upatrywałem zawsze Pana przed obliczem mojem; bo mi jest po prawicy, abym nie był wzruszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Przetoż rozweseliło się serce moje i rozradował się język mój, nadto i ciało moje odpocznie w nadziei;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Albowiem nie zostawisz duszy mojej w piekle, a nie dasz świętemu twojemu oglądać skażenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Oznajmiłeś mi drogi żywota, a napełnisz mię radością przed obliczem twojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Mężowie bracia! mogę bezpiecznie mówić do was o patryjarsze Dawidzie, żeć umarł i pogrzebiony jest, a grób jego jest u nas aż do dnia dzisiejszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Będąc tedy prorokiem i wiedząc, że mu się Bóg obowiązał przysięgą, iż z owocu biódr jego według ciała miał wzbudzić Chrystusa, a posadzić na stolicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'To przeglądając, powiedział o zmartwychwstaniu Chrystusowem, iż nie została dusza jego w piekle, ani ciało jego widziało skażenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Tegoć Jezusa wzbudził Bóg, czego my wszyscy jesteśmy świadkami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Prawicą tedy Bożą będąc wywyższony, a obietnicę Ducha Świętego wziąwszy od Ojca, wylał to, co wy teraz widzicie i słyszycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Albowiemci Dawid nie wstąpił do nieba, lecz sam powiada: Rzekł Pan Panu memu, siądź po prawicy mojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Aż położę nieprzyjacioły twoje podnóżkiem nóg twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Niechajże tedy wie zapewne wszystek dom Izraelski, że go Bóg i Panem, i Chrystusem uczynił, tego Jezusa, któregoście wy ukrzyżowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'A to słysząc, przerażeni są na sercu i rzekli do Piotra i do innych Apostołów: Cóż mamy czynić, mężowie bracia?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Tedy Piotr rzekł do nich: Pokutujcie, a ochrzcij się każdy z was w imieniu Jezusa Chrystusa na odpuszczenie grzechów, a weźmiecie dar Ducha Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Albowiemci wam ta obietnica należy i dziatkom waszym, i wszystkim, którzy daleko są, którekolwiek by powołał Pan, Bóg nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'I wielą inszych słów oświadczał się i napominał je, mówiąc: Wyzwólcie się od tego rodzaju przewrotnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Którzy tedy wdzięcznie przyjęli słowa jego, ochrzczeni są i przystało dnia onego dusz około trzech tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'I trwali w nauce apostolskiej i w społeczności, i w łamaniu chleba, i w modlitwach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'I przyszedł strach na każdą duszę, a wiele się znamion i cudów przez Apostołów działo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'A wszyscy, którzy uwierzyli byli pospołu, i wszystkie rzeczy mieli spólne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'A osiadłości i majętności sprzedawali, i udzielali ich wszystkim, jako komu było potrzeba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'A na każdy dzień trwając zgodnie w kościele i chleb łamiąc po domach, przyjmowali pokarm z radością i w prostocie serdecznej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Chwaląc Boga i mając łaskę u wszystkiego ludu. A Pan przydawał zborowi na każdy dzień tych, którzy mieli być zbawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'A Piotr i Jan społem wstępowali do kościoła w godzinę modlitwy, dziewiątą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'A mąż niektóry będąc chromy, zaraz z żywota matki swojej był noszony, którego na każdy dzień sadzano u drzwi kościelnych, które zwano piękne, aby prosił jałmużny od tych, którzy wchodzili do kościoła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Ten ujrzawszy Piotra i Jana, że mieli wnijść do kościoła, prosił ich o jałmużnę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'A Piotr z Janem pilnie na niego patrząc, rzekli: Wejrzyj na nas!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Tedy on z pilnością patrzał na nie, spodziewając się co wziąć od nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'I rzekł Piotr: Srebra i złota nie mam; lecz co mam, to ci daję: W imieniu Jezusa Chrystusa Nazareńskiego wstań, a chodź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'A ująwszy go za prawą rękę jego, podniósł go, a zarazem utwierdzone były nogi jego i kostki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'I wyskoczywszy, stanął i chodził, a wszedł z nimi do kościoła, chodząc i skacząc, a chwaląc Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'A widział go wszystek lud chodzącego i chwalącego Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'I poznali go, iż to on był, który dla jałmużny siadał u drzwi pięknych kościelnych; i napełnieni są strachu i zdumienia nad tem, co mu się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'A gdy się trzymał on chromy, który był uzdrowiony, Piotra i Jana, zbieżał się do nich wszystek lud do przysionka, który zwano Salomonowym, zdumiawszy się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Co widziąc Piotr, przemówił do ludu: Mężowie Izraelscy! cóż się temu dziwujecie, albo czemu się nam tak pilnie przypatrujecie, jakobyśmy to własną mocą albo pobożnością uczynili, aby ten chodził?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Bóg Abrahama i Izaaka i Jakóba, Bóg ojców naszych, uwielbił Jezusa, Syna swego, któregoście wy wydali i zaparliście się go przed twarzą Piłatową, który go sądził być godnym wypuszczenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'A wyście się onego świętego i sprawiedliwego zaparli, a prosiliście o mężobójcę, aby wam był darowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'I zabiliście dawcę żywota, którego Bóg wzbudził od umarłych, czego my świadkami jesteśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'A przez wiarę w imię jego, tego, którego wy widzicie i znacie, utwierdziło imię jego; wiara, mówię, która przez niego jest, dała temu to zupełne zdrowie przed obliczem was wszystkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Ale teraz, bracia! wiem, żeście to z niewiadomości uczynili, jako i książęta wasi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Lecz Bóg, co przez usta wszystkich proroków swoich przepowiedział, iż Chrystus jego cierpieć miał, to tak ziścił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Przetoż pokutujcie, a nawróćcie się, aby były zgładzone grzechy wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'Gdyby przyszły czasy ochłody od obliczności Pańskiej, a posłałby onego, który wam opowiedziany jest, Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Który zaiste niebiosa ma objąć aż do czasu naprawienia wszystkich rzeczy, co był przepowiedział Bóg przez usta wszystkich świętych swoich proroków od wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Albowiem Mojżesz do ojców rzekł: Proroka wam wzbudzi Pan, Bóg wasz, z braci waszych, jako mię; onego słuchać będziecie we wszystkiem, cokolwiek do was mówić będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'I stanie się, że każda dusza, która by nie słuchała tego proroka, będzie wygładzona z ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Aleć i wszyscy prorocy od Samuela i od innych po nim, ilekolwiek ich mówiło, przepowiadali też te dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Wy jesteście synami prorockimi i przymierza, które postanowił Bóg z ojcami naszymi, mówiąc do Abrahama: A w nasieniu twojem błogosławione będą wszystkie narody ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Wamci naprzód Bóg wzbudziwszy Syna swego Jezusa, posłał go, aby wam błogosławił; żeby się każdy z was odwrócił od złości swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'A gdy to oni mówili do ludu, nadeszli ich kapłani i hetmani kościelni, i Saduceuszowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Obrażając się, iż uczyli lud, a opowiadali w Jezusie powstanie od umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'I wrzucili na nie ręce, a podali je do więzienia aż do jutra; bo już był wieczór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'A wiele z tych, którzy one słowa słyszeli, uwierzyli; i była liczba mężów około pięciu tysięcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'I stało się nazajutrz, że się zebrali przełożeni ich i starsi, i nauczeni w Piśmie w Jeruzalemie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'I Annasz, najwyższy kapłan, i Kaifasz, i Jan, i Aleksander, i ile ich było z rodu najwyższych kapłanów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'A postawiwszy je w pośrodku, pytali ich: Którą mocą a któremeście to imieniem uczynili?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Tedy Piotr, będąc pełen Ducha Świętego, rzekł do nich: Przełożeni ludu i starsi Izraelscy!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Ponieważ my dziś mamy być sądzeni dla dobrodziejstwa człowiekowi niemocnemu uczynionego, jakoby on był uzdrowiony;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'Niech wam wszystkim wiadomo będzie i wszystkiemu ludowi Izraelskiemu, że w imieniu Jezusa Chrystusa Nazareńskiego, któregoście wy ukrzyżowali, którego Bóg wzbudził od umarłych, przez tego ten stoi przed wami zdrowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Tenci jest kamień on wzgardzony od was budujących, który się stał głową węgielną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'I nie masz w żadnym innym zbawienia; albowiem nie masz żadnego imienia pod niebem, danego ludziom, przez które byśmy mogli być zbawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Widząc tedy bezpieczność Piotrową i Janową, i zrozumiawszy, iż ludźmi byli nieuczonymi i prostakami, dziwowali się i poznali je, iż byli z Jezusem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Widząc też onego człowieka z nimi stojącego, który był uzdrowiony, nie mieli co przeciwko temu mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'A rozkazawszy im precz ustąpić z rady, radzili się między sobą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Mówiąc: Cóż uczynimy tym ludziom? Bo, że jawny cud przez nie jest uczyniony, to wszystkim mieszkającym w Jeruzalemie wiadomo jest, a nie możemy tego zaprzeć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Ale aby się to więcej nie rozsławiało między ludźmi, zagroźmy im srodze, aby więcej w tem imieniu żadnemu człowiekowi nie mówili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'A zawoławszy ich, zakazali im, aby koniecznie nie mówili, ani uczyli w imieniu Jezusowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Lecz Piotr i Jan odpowiedziawszy rzekli do nich: Jeźliż to sprawiedliwa przed obliczem Bożem, was raczej słuchać niż Boga, rozsądźcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Albowiem my nie możemy tego, cośmy widzieli i słyszeli, nie mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'A oni zagroziwszy im, wypuścili je, nic nie znalazłszy, jakoby je skarać dla ludu i wszyscy chwalili Boga za to, co się było stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Bo onemu człowiekowi było więcej niż czterdzieści lat, nad którym się stał ten cud uzdrowienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'A gdy je wypuszczono, przyszli do swoich i oznajmili im, cokolwiek do nich przedniejsi kapłani i starsi mówili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Którzy usłyszawszy to, jednomyślnie podnieśli głos swój ku Bogu i rzekli: Panie! tyś jest Bóg, któryś uczynił niebo i ziemię, i morze i wszystko, co w nich jest:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Któryś Duchem Świętym przez usta Dawida, sługi swego, powiedział: Przeczże się zburzyli narodowie, a ludzie próżne rzeczy przemyślali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Stanęli królowie ziemi i książęta zebrali się wespół przeciwko Panu i przeciwko pomazańcowi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Albowiem się zebrali prawdziwie przeciwko świętemu Synowi twemu Jezusowi, któregoś pomazał, Herod i Poncki Piłat z pogany i z ludem Izraelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Aby uczynili, cokolwiek ręka twoja i rada twoja przedtem postanowiła, aby się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Przetoż teraz, Panie! wejrzyj na pogróżki ich, a daj sługom twoim ze wszystkiem bezpieczeństwem mówić słowo twoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'Ściągając rękę twoję ku uzdrawianiu i ku czynieniu znamion i cudów, przez imię świętego Syna twego Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'A gdy się oni modlili, zatrząsnęło się ono miejsce, na którem byli zgromadzeni, i napełnieni są wszyscy Duchem Świętym i mówili słowo Boże z bezpieczeństwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'A onego mnóstwa wierzących było serce jedno i dusza jedna, a żaden z majętności swoich nie zwał nic swojem własnem, ale mieli wszystkie rzeczy spólne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'A wielką mocą Apostołowie dawali świadectwo o zmartwychwstaniu Pana Jezusowem i była wielka łaska nad nimi wszystkimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Bo żadnego nie było między nimi niedostatecznego; gdyż którzykolwiek mieli role albo domy, sprzedawając przynosili pieniądze za to, co posprzedawali,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'I kładli przed nogi apostolskie, i rozdawano to każdemu, ile komu było potrzeba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Tedy Jozes, który nazwany był od Apostołów Barnabaszem, (co się wykłada: syn pociechy), Lewita, z Cypru rodem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Mając rolę, sprzedawszy ją, przyniósł pieniądze i położył je u nóg apostolskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'A mąż niektóry imieniem Ananijasz, z Safirą, żoną swoją, sprzedał majętność,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'I ujął nieco z onych pieniędzy z wiadomością żony swojej, a przyniósłszy część niejaką, położył u nóg apostolskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'I rzekł Piotr: Ananijaszu! przeczże szatan napełnił serce twoje, abyś kłamał Duchowi Świętemu i ujął z pieniędzy za rolę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Izali to, coś miał, nie twoje było? a coś sprzedał, nie w twojej mocy zostawało? Przeczżeś tę rzecz przypuścił do serca twego? Nie skłamałeś ludziom, ale Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Tedy usłyszawszy Ananijasz te słowa, padł nieżywy. I przyszedł strach wielki na wszystkich, którzy to słyszeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'A wstawszy młodzieńcy, porwali go, a wyniósłszy pogrzebli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'I stało się po chwili, jakoby po trzech godzinach, że i żona jego nie wiedząc, co się stało, weszła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'I rzekł jej Piotr: Powiedz mi, jeźliście za tyle tę rolę sprzedali? A ona rzekła: Tak jest, za tyle.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'A Piotr rzekł do niej: Przeczżeście się z sobą zmówili, abyście kusili Ducha Pańskiego? Oto nogi tych, którzy pogrzebli męża twego, u drzwi są i ciebieć wyniosą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'I padła zaraz przed nogami jego nieżywa. A wszedłszy młodzieńcy, znaleźli ją umarłą, a wyniósłszy pogrzebli ją podle męża jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'I przyszedł strach wielki na wszystek zbór i na wszystkich, którzy to słyszeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Lecz przez ręce apostolskie działo się wiele znamion i cudów między ludem, (a byli wszyscy jednomyślnie w przysionku Salomonowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'A z innych żaden nie śmiał się do nich przyłączyć; ale lud wiele o nich trzymał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'I owszem przybywało mnóstwo wierzących Panu, mężów i niewiast).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'Tak że i na ulice wynosili chorych i kładli je na pościelach i łóżkach, aby przynajmniej cień Piotra przychodzącego zacienił niektórych z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Schodziło się też i mnóstwo z okolicznych miast do Jeruzalemu, przynosząc chorych i nagabanych od duchów nieczystych; a ci wszyscy byli uzdrowieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Tedy powstawszy najwyższy kapłan i wszyscy, którzy z nim byli, którzy byli z sekty Saduceuszów, napełnieni są zazdrością;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'I targnęli się rękoma na Apostoły i podali je do więzienia pospolitego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Ale Anioł Pański w nocy otworzył drzwi u więzienia, a wywiódłszy je rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Idźcież, a stawiwszy się, mówcie do ludu w kościele wszystkie słowa tego żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Tedy oni usłyszawszy to, weszli na świtaniu do kościoła i uczyli. A przyszedłszy najwyższy kapłan i którzy z nim byli, zwołali radę i wszystkie starsze synów Izraelskich, i posłali do więzienia, aby byli przywiedzieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'A gdy słudzy przyszli, nie znaleźli ich w więzieniu, co wróciwszy się, oznajmili, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'Więzienieć wprawdzie znaleźliśmy zamknione ze wszelką pilnością i stróże na dworze przede drzwiami stojące, lecz otworzywszy, żadnegośmy w niem nie znaleźli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'A gdy te słowa usłyszeli i najwyższy kapłan, i hetman kościelny, i przedniejsi kapłani wątpili o nich, co by to było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'A przyszedłszy ktoś, oznajmił im, mówiąc: Oto mężowie, któreście podali do więzienia, stoją w kościele, a uczą lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Tedy poszedł hetman z sługami i przywiódł je bez gwałtu; (bo się ludu bali, aby nie byli ukamionowani.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'A przywiódłszy je, stawili je przed radą; i pytał ich najwyższy kapłan, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Izaliśmy wam surowo nie zakazali, abyście w tem imieniu nie uczyli? A oto napełniliście Jeruzalem nauką waszą i chcecie na nas wprowadzić krew człowieka tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Tedy odpowiadając Piotr i Apostołowie, rzekli: Więcej trzeba słuchać Boga, niż ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Bóg on ojców naszych wzbudził Jezusa, któregoście wy zabili, zawiesiwszy na drzewie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Tego Bóg za książęcia i zbawiciela wywyższył prawicą swoją, aby dana była ludowi Izraelskiemu pokuta i odpuszczenie grzechów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'A my jesteśmy świadkami jego w tem, co mówimy, także i Duch Święty, którego dał Bóg tym, którzy mu są posłuszni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'A oni to słysząc, pukali się i radzili o tem, jakoby je zgładzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Tedy powstawszy w radzie niektóry Faryzeusz, imieniem Gamalijel, nauczyciel zakonny, zacny u wszystkiego ludu, rozkazał, aby na małą chwilę precz wywiedziono Apostoły;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'I rzekł do nich: Mężowie Izraelscy! miejcie się na baczeniu z strony tych ludzi, co byście mieli czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Albowiem przed temi dniami powstał był Teudas, udawając się za coś, do którego się przywiązało mężów w liczbie około czterechset; którego zabito, a wszyscy, którzy z nim przestawali, rozproszeni są i wniwecz się obrócili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Po nim powstał Judas Galilejczyk za dni popisu i uwiódł wiele ludu za sobą; ale i on zginął, i wszyscy, którzy z nim przestawali, rozproszeni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Przetoż teraz powiadam wam: Dajcie pokój tym ludziom i zaniechajcie ich; albowiem jeźliżeć jest z ludzi ta rada albo ta sprawa, wniwecz się obróci;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Ale jeźlić jest z Boga, nie będziecie mogli tego rozerwać, byście snać i z Bogiem walczącymi nie byli znalezieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'I usłuchali go. A zawoławszy Apostołów i ubiwszy je, zakazali, aby nie mówili w imieniu Jezusowem; i wypuścili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'A tak oni szli od obliczności onej rady, radując się, iż się stali godnymi odnosić zelżywość dla imienia Jezusowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'I nie przestawali na każdy dzień w kościele i po domach nauczać i opowiadać Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'A w oneż dni, gdy się przymnażało uczniów, wszczęło się szemranie Greków przeciwko Żydom, iż były zaniedbywane w posługiwaniu powszedniem wdowy ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'A tak oni dwunastu zwoławszy mnóstwo uczniów, rzekli: Nie jest słuszna, żebyśmy my opuściwszy słowo Boże, służyli stołom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Upatrzcież tedy, bracia! między sobą siedm mężów, dobre świadectwo mających, pełnych Ducha Świętego i mądrości, których byśmy postanowili nad tą sprawą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'A my modlitwy i usługi słowa pilnować będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'I podobała się ta rzecz onemu wszystkiemu mnóstwu. I obrali Szczepana, męża pełnego wiary i Ducha Świętego, i Filipa, i Prochora, i Nikanora, i Tymona, i Parmena, i Mikołaja, nowonawróconego Antyjocheńczyka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Tych stawili przed Apostołów, którzy pomodliwszy się, kładli na nich ręce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'I rosło słowo Boże, i pomnażał się bardzo poczet uczniów w Jeruzalemie: wielkie też mnóstwo kapłanów było posłuszne wierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'A Szczepan będąc pełen wiary i mocy, czynił cuda i znamiona wielkie między ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'I powstali niektórzy z tych, którzy byli z bóżnicy, którą zowią Libertynów i Cyrenejczyków, i Aleksandryjanów, i tych, którzy byli z Cylicyi i z Azyi, gadając z Szczepanem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Lecz nie mogli odporu dać mądrości i duchowi, który mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Tedy naprawili mężów, którzy powiedzieli: Myśmy go słyszeli mówiącego słowa bluźniercze przeciwko Mojżeszowi i przeciwko Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'A tak wzruszyli lud i starszych, i nauczonych w Piśmie; a powstawszy, porwali go i przywiedli do rady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'I stawili fałszywych świadków, którzy rzekli: Ten człowiek nie przestaje mówić słów bluźnierczych przeciwko temu świętemu miejscu i zakonowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Albowiemeśmy go słyszeli mówiącego: Iż ten Jezus Nazareński zburzy to miejsce i odmieni ustawy, które nam podał Mojżesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'A patrząc na niego pilnie oni wszyscy, którzy siedzieli w radzie, widzieli oblicze jego jako oblicze anielskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Tedy rzekł najwyższy kapłan: A także się ma ta rzecz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'A on rzekł: Mężowie bracia i ojcowie, słuchajcie! Bóg chwały ukazał się ojcu naszemu Abrahamowi, gdy był w Mezopotamii, przedtem niż mieszkał w Haranie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'I rzekł do niego: Wynijdź z ziemi twojej i od twojej rodziny, a idź do ziemi, którą ci ukażę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Tedy wyszedłszy z ziemi Chaldejskiej, mieszkał w Haranie, a stamtąd, gdy umarł ojciec jego, przeniósł go Bóg do ziemi tej, w której wy teraz mieszkacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'I nie dał mu w niej dziedzictwa i na stopę nogi, choć mu ją był obiecał dać w dzierżawę, i nasieniu jego po nim, gdy jeszcze nie miał potomka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'I mówił mu tak Bóg: Nasienie twoje będzie przychodniem w cudzej ziemi i zniewolą je, i trapić je będą przez czterysta lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Ale ten naród, któremu służyć będą, ja będę sądził, rzekł Bóg; a potem wynijdą i służyć mi będą na tem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'I dał mu przymierze obrzezki; i tak Abraham spłodził Izaaka i obrzezał go dnia ósmego, a Izaak Jakóba, a Jakób dwunastu patryjarchów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'A patryjarchowie nienawidząc Józefa, sprzedali go do Egiptu; ale Bóg był z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'I wyrwał go ze wszystkich jego ucisków, a dał mu łaskę i mądrość przed Faraonem, królem Egipskim, który go postanowił książęciem nad Egiptem i nad wszystkim domem swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Potem przyszedł głód na wszystkę ziemię Egipską i Chananejską, i ucisk wielki, i nie znajdowali żywności ojcowie nasi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'A gdy usłyszał Jakób, iż zboża były w Egipcie, posłał ojców naszych pierwszy raz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'A za wtórym razem poznany jest Józef od braci swych i objawiony jest Faraonowi naród Józefowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Tedy Józef posławszy, przyzwał ojca swego Jakóba i wszystkę swoję rodzinę w siedmdziesiąt i pięciu duszach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'I zstąpił Jakób do Egiptu, i tam umarł on i ojcowie nasi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'I przeniesieni są do Sychem, i położeni w grobie, który był kupił Abraham za pieniądze u synów Hemora, ojca Sychemowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'A gdy się przybliżył czas obietnicy, o którą był przysiągł Bóg Abrahamowi, rozrodził się lud i rozmnożył się w Egipcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Aż nastał inny król, który nie znał Józefa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Ten podchodząc zdradliwie naród nasz, trapił ojców naszych, tak iż musieli wymiatać niemowlątka swoje, żeby się nie rozkrzewiały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Pod ten czas narodził się Mojżesz, a był krasnym z daru Bożego, którego chowano przez trzy miesiące w domu ojca jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'A gdy był wyrzucony, wzięła go córka Faraonowa i wychowała go sobie za syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'I wyćwiczony jest Mojżesz we wszelkiej mądrości Egipskiej, a był możny w mowach i w uczynkach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'A gdy mu było czterdzieści lat, przyszło mu na myśl, aby nawiedził braci swych, syny Izraelskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'A ujrzawszy jednego ukrzywdzonego, ujął się oń i pomścił się krzywdy tego, który bezprawie cierpiał, zabiwszy Egipczanina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Albowiem mniemał, że bracia jego rozumieją, że Bóg przez rękę jego daje im wybawienie; lecz oni tego nie rozumieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'A nazajutrz pokazał się im, gdy się z sobą bili i prowadził je do pokoju, mówiąc: Mężowie! bracia jesteście sobie; przeczże się społem krzywdzicie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Lecz ten, co krzywdził bliźniego, odegnał go, mówiąc: Któż cię postanowił książęciem i sędzią nad nami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Izali mię ty chcesz zabić, jakoś wczoraj zabił Egipczanina?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'I uciekł Mojżesz za temi słowy i był przychodniem w ziemi Madyjańskiej, gdzie spłodził dwóch synów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'A gdy się wypełniło czterdzieści lat, ukazał mu się na puszczy góry Synaj Anioł Pański w płomieniu ognistym w krzaku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'A Mojżesz ujrzawszy, zadziwił się onemu widzeniu; a gdy przystąpił, aby się temu przypatrzył, stał się do niego głos Pański:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Jam jest Bóg ojców twoich, Bóg Abrahama, Bóg Izaaka, i Bóg Jakóba. A zadrżawszy Mojżesz nie śmiał się przypatrywać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'I rzekł mu Pan: Zzuj obuwie z nóg twoich; bo miejsce, na którem stoisz, jest ziemia święta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Widząc widziałem utrapienie ludu mego, który jest w Egipcie, i słyszałem wzdychanie ich, a zstąpiłem, żebym je wybawił; przetoż teraz chodź, poślę cię do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Tego Mojżesza, którego się byli zaprzali, mówiąc: Któż cię postanowił książęciem i sędzią? Tego Bóg książęciem i wybawicielem posłał przez rękę Anioła, który mu się ukazał w krzaku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'I ten je wywiódł, czyniąc cuda i znamiona w ziemi Egipskiej i na morzu Czerwonem, i na puszczy, przez czterdzieści lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Tenci jest Mojżesz, który rzekł synom Izraelskim: Proroka wam wzbudzi Pan, Bóg wasz, z braci waszych, jako mię, onego słuchać będziecie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Ten jest, który był w zgromadzeniu na puszczy z Aniołem, który mówił do niego na górze Synaj, i z ojcami naszymi, który przyjął słowa Boże żywe, aby je nam podał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Któremu nie chcieli posłuszni być ojcowie nasi; ale go odrzucili i obrócili się sercy swemi do Egiptu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'Mówiąc do Aarona: Uczyń nam bogi, którzy by szli przed nami; albowiem Mojżeszowi onemu, który nas wywiódł z ziemi Egipskiej, nie wiemy co się stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'I uczynili w one dni cielca i sprawowali ofiarę onemu bałwanowi, i weselili się w sprawach rąk swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'I odwrócił się Bóg i podał je, aby służyli wojsku niebieskiemu, jako napisano jest w księgach prorockich: Zażeście mu bite i inne ofiary ofiarowali na puszczy przez czterdzieści lat, domu Izraelski?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Owszem nosiliście namiot Molocha i gwiazdę boga waszego Remfana, te obrazy, któreście sobie uczynili, abyście się im kłaniali; przetoż was zaprowadzę za Babilon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Namiot świadectwa mieli ojcowie nasi na puszczy, jako był rozrządził ten, który powiedział Mojżeszowi, aby go uczynił według kształtu, który widział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Który wziąwszy ojcowie nasi, wnieśli z Jozuem tam, gdzie była osiadłość poganów, których Bóg wygnał od obliczności ojców naszych, aż do dni Dawidowych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Który znalazł łaskę przed obliczem Bożem i prosił, aby znalazł namiot Bogu Jakóbowemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'A Salomon zbudował mu dom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Ale on Najwyższy nie mieszka w kościołach ręką uczynionych, jako prorok mówi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'Niebo jest stolica moja, a ziemia podnóżek nóg moich. Cóż mi za dom zbudujecie, mówi Pan, albo które jest miejsce odpocznienia mego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Izali ręka moja tego wszystkiego nie uczyniła?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Ludzie twardego karku i nieobrzezanego serca, i uszów! wy się zawżdy sprzeciwiacie Duchowi Świętemu jako ojcowie wasi, tak i wy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Któregoż z proroków nie prześladowali ojcowie wasi, i nie pozabijali tych, którzy przedtem opowiadali o przyjściu tego Sprawiedliwego, któregoście wy się teraz stali zdrajcami i mordercami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'Którzyście wzięli zakon przez rozrządzenie anielskie, a nie strzegliście go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Tedy słuchając tego, pukali się w sercach swych i zgrzytali na niego zębami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'A on będąc pełen Ducha Świętego, patrząc pilnie w niebo, ujrzał chwałę Bożą i Jezusa stojącego po prawicy Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'I rzekł: Oto widzę niebiosa otworzone i Syna człowieczego stojącego po prawicy Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'A oni krzyknąwszy głosem wielkim, zatulili uszy swoje i rzucili się na niego jednomyślnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'A wypchnąwszy go z miasta, kamionowali; a świadkowie złożyli szaty swoje u stóp młodzieńca, którego zwano Saul.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'I kamionowali Szczepana modlącego się i mówiącego: Panie Jezu! przyjmij ducha mojego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'A klęknąwszy na kolana, zawołał głosem wielkim: Panie! nie poczytaj im tego za grzech! A to rzekłszy, zasnął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'A Saul zezwolił na zabicie jego. I wszczęło się onegoż czasu wielkie prześladowanie przeciwko zborowi, który był w Jeruzalemie, i rozproszyli się wszyscy po krainach ziemi Judzkiej i Samaryi, oprócz Apostołów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'I pogrzebli Szczepana mężowie bogobojni i uczynili nad nim płacz wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'A Saul niszczył zbór, wchodząc w domy, a wywłóczając męże i niewiasty, podawał je do więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'A ci, którzy byli rozproszeni, chodzili opowiadając słowo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Lecz Filip zaszedłszy do miasta Samaryjskiego, opowiadał im Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'A lud miał wzgląd jednomyślnie na to, co Filip mówił, słuchając i widząc cuda, które czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Albowiem duchy nieczyste od wielu tych, którzy je mieli, wołając głosem wielkim wychodziły, a wiele powietrzem ruszonych i chromych uzdrowieni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'I stała się radość wielka w onem mieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'A niektóry mąż, imieniem Szymon, był przedtem w onem mieście bawiący się nauką czarnoksięską i lud Samaryjski mamił, powiadając się być czymś wielkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Na którego się oglądali wszyscy od najmniejszego aż do największego, mówiąc: Tenci jest ona moc Boża wielka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'A oglądali się nań przeto, iż je od niemałego czasu mamił czarnoksięstwy swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'A gdy uwierzyli Filipowi, opowiadającemu królestwo Boże i imię Jezusa Chrystusa, chrzcili się mężowie i niewiasty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Tedy i sam Szymon uwierzył, a ochrzciwszy się, trzymał się Filipa, a widząc cuda i mocy wielkie, które się działy, zdumiewał się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'A usłyszawszy Apostołowie, którzy byli w Jeruzalemie, iż Samaryja przyjęła słowo Boże, posłali do nich Piotra i Jana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Którzy tam przyszedłszy, modlili się za nimi, aby przyjęli Ducha Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, '(Albowiem jeszcze był na żadnego z nich nie zstąpił; ale tylko pochrzczeni byli w imię Pana Jezusowe.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Tedy na nie wkładali ręce, a oni przyjmowali Ducha Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'A ujrzawszy Szymon, że przez wkładanie rąk apostolskich był dawany Duch Święty, przyniósł im pieniądze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Mówiąc: Dajcie i mnie tę moc, aby ten, na któregokolwiek bym ręce włożył, wziął Ducha Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'I rzekł mu Piotr: Pieniądze twoje niech z tobą będą na zginienie, żeś mniemał, żeby dar Boży miał być za pieniądze nabywany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Nie masz w tej rzeczy cząstki, ani losu, gdy serce twoje nie jest proste przed obliczem Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Przetoż pokutuj z tej twojej złości, a proś Boga; ować snać będzie odpuszczony ten zamysł serca twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Albowiem cię widzę być w gorzkości żółci i w związce nieprawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Odpowiedziawszy tedy Szymon, rzekł: Módlcie się wy za mną Panu, aby na mię nic nie przyszło z tych rzeczy, któreście powiedzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'A tak oni oświadczywszy i opowiedziawszy słowo Pańskie, wrócili się do Jeruzalemu i w wielu miasteczkach Samarytańskich Ewangieliję opowiadali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Lecz Anioł Pański rzekł do Filipa, mówiąc: Wstań, a idź ku południowi na drogę, która od Jeruzalemu idzie ku Gazie, która jest pusta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'A on wstawszy, szedł. A oto mąż Murzyn rzezaniec, komornik królowej murzyńskiej Kandaces, który był nad wszystkiemi skarbami jej, a przyjechał był do Jeruzalemu, aby się modlił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'I wracał się, siedząc na wozie swoim, a czytał Izajasza proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'I rzekł Duch Filipowi: Przystąp, a przyłącz się do tego wozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'A przybieżawszy Filip, usłyszał go czytającego Izajasza proroka i rzekł: Rozumieszże, co czytasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'A on rzekł: Jakoż mogę rozumieć, jeźliby mi kto nie wyłożył? I prosił Filipa, a wstąpił i siedział z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'A miejsce onego Pisma, które czytał, to było: Jako owca ku zabiciu wiedziony jest, a jako baranek niemy przed tym, który go strzyże, tak nie otworzył ust swoich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'W uniżeniu jego sąd jego zniesiony jest, a rodzaj jego któż wypowie? albowiem zniesiony był z ziemi żywot jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'A odpowiadając rzezaniec Filipowi, rzekł: Proszę cię, o kim to prorok mówi? Sam o sobie, czyli o kim innym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Tedy otworzywszy Filip usta swe, a począwszy od tego Pisma, opowiadał mu Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'A gdy jechali drogą, przyjechali nad jednę wodę. Tedy rzekł rzezaniec: Otóż woda! Cóż na przeszkodzie, abym nie miał być ochrzczony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'I rzekł Filip: Jeźliż wierzysz z całego serca, wolnoć. A on odpowiedziawszy, rzekł: Wierzę, iż Jezus Chrystus jest Syn Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'I kazał stanąć wozowi; i zstąpili obadwaj w wodę, Filip i rzezaniec, i ochrzcił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'A gdy wystąpili z wody, porwał Filipa Duch Pański i nie widział go więcej rzezaniec, ale jechał drogą swoją, radując się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'A Filip aż w Azocie jest znaleziony, a chodząc kazał Ewangieliję po wszystkich miastach, aż przyszedł do Cezaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'A Saul jeszcze dychając groźbą i morderstwem przeciwko uczniom Pańskim, przyszedł do najwyższego kapłana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'I prosił go o listy do Damaszku do bóżnic, iż jeźliby tam znalazł tej drogi (tą drogą idących) których mężów albo niewiasty, aby ich związane przywiódł do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'A gdy jechał, stało się, gdy się przybliżał do Damaszku, że z prędka oświeciła go światłość z nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'A padłszy na ziemię, usłyszał głos do siebie mówiący: Saulu! Saulu! przeczże mię prześladujesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Tedy rzekł: Ktoś jest, Panie? A Pan rzekł: Jam jest Jezus, którego ty prześladujesz; trudno tobie przeciw ościeniowi wierzgać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'A Saul drżąc i bojąc się, rzekł: Panie! co chcesz, abym ja uczynił? A Pan do niego: Wstań, a wnijdź do miasta, a tam ci powiedzą, co byś ty miał czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'A mężowie, którzy z nim byli w drodze, stanęli, zdumiawszy się; głos tylko słysząc, ale nikogo nie widząc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'I wstał Saul z ziemi, a otworzywszy oczy swoje, nikogo nie widział. Tedy ująwszy go za rękę; prowadzili go do Damaszku,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Kędy był trzy dni nie widząc, i nie jadł ani pił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'A był niektóry uczeń w Damaszku, imieniem Ananijasz; i rzekł Pan do niego w widzeniu: Ananijaszu! A on rzekł: Otom ja, Panie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'A Pan rzekł do niego: Wstań, a idź na ulicę, którą zowią prostą, a szukaj w domu Judowym Saula imieniem Tarseńczyka; albowiem oto się modli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'I widział w widzeniu męża, imieniem Ananijasz, wchodzącego i rękę na się wkładającego, aby przejrzał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'I odpowiedział Ananijasz: Panie! słyszałem od wielu o tym mężu, jako wiele złego czynił świętym twoim w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'I tu ma moc od najwyższych kapłanów, aby wiązał wszystkie wzywające imienia twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'I rzekł do niego Pan: Idźże, albowiem mi ten jest naczyniem wybranem, aby nosił imię moje przed pogany i królmi, i przed syny Izraelskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Albowiem ja mu ukażę, jako wiele musi cierpieć dla imienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'I poszedł Ananijasz, i wszedł do onego domu, a włożywszy na niego ręce, rzekł: Saulu, bracie! Pan mię posłał, Jezus on, któryć się ukazał w drodze, którąś jechał, abyś przejrzał, a był napełniony Duchem Świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'I zarazem spadły z oczów jego jako łuski i wnet przejrzał, a wstawszy ochrzczony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'A wziąwszy pokarm, posilił się. I był Saul z uczniami, którzy byli w Damaszku, kilka dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'I zaraz kazał w bóżnicach Chrystusa, że on jest Synem Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'I zdumiewali się wszyscy, którzy go słuchali, i mówili: Izali to nie jest ten, który burzył w Jeruzalemie tych, którzy wzywali imienia tego? i tuć na to przyszedł, aby ich związawszy, wiódł do najwyższych kapłanów?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'A Saul tem więcej zmacniał się i zawstydzał Żydy, którzy mieszkali w Damaszku, dowodząc, iż ten jest Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'A gdy przeszło niemało dni, uradzili Żydowie między sobą, aby go zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Ale się dowiedział Saul o zasadzce ich. Strzegli też bram we dnie i w nocy, aby go zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Lecz uczniowie wziąwszy go w nocy, spuścili go po powrozie przez mur w koszu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'A gdy przyszedł Saul do Jeruzalemu, kusił się przyłączyć do uczniów; ale się go wszyscy bali, nie wierząc, aby był uczniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Lecz Barnabasz wziąwszy go, przywiódł go do Apostołów i powiadał im, jako w drodze widział Pana, a iż mówił do niego, i jako w Damaszku bezpiecznie mówił w imieniu Jezusowem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'I mieszkał z nimi w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'A bezpiecznie sobie poczynając w imieniu Pana Jezusowem, mówił i gadał z Grekami; a oni się starali, jako by go zabić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'O czem dowiedziawszy się bracia, odprowadzili go do Cezaryi i odesłali go do Tarsu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'A tak zbory po wszystkiej Judzkiej ziemi i Galilei, i Samaryi miały pokój, budując się i chodząc w bojaźni Pańskiej, a przez pociechę Ducha Świętego rozmnażały się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'I stało się, gdy Piotr obchodził wszystkie, przyszedł też do świętych, którzy mieszkali w Liddzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Tamże znalazł człowieka niektórego, imieniem Eneasz, od ośmiu lat na łożu leżącego, który był powietrzem ruszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'I rzekł mu Piotr: Eneaszu! uzdrawia cię Jezus Chrystus; wstańże, a pościel sobie. I zarazem wstał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'A widzieli go wszyscy, którzy mieszkali w Liddzie i w Saronie, którzy się nawrócili do Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'A była w Joppie niektóra uczennica, imieniem Tabita, która wyłożywszy, zowie się Dorka; ta była pełna dobrych uczynków i jałmużny, które czyniła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'I stało się w one dni, że rozniemógłszy się, umarła; którą omywszy, położyli na sali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'A iż Lidda była blisko Joppy, uczniowie usłyszawszy, że tam jest Piotr, posłali do niego dwóch mężów, prosząc go, aby się nie lenił przyjść do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Tedy wstawszy Piotr, szedł z nimi; a gdy przyszedł, wprowadzili go na salę i obstąpiły go wszystkie wdowy, płacząc i ukazując suknie i płaszcze, które im Dorka robiła, póki była z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'A Piotr wygnawszy precz wszystkie, klęknął na kolana i modlił się, a obróciwszy się do onego ciała, rzekł: Tabito, wstań! a ona otworzyła oczy swoje i ujrzawszy Piotra, usiadła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'A on podawszy jej rękę, podniósł ją, a zawoławszy świętych i wdów, stawił ją żywą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'I rozsławiło się to po wszystkiej Joppie, i wiele ich uwierzyło w Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'I stało się, że przez wiele dni został Piotr w Joppie u niejakiego Szymona, garbarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'A w Cezaryi był mąż niektóry, imieniem Kornelijusz, setnik, z roty, którą zwano Włoską;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Pobożny i bojący się Boga ze wszystkim domem swoim, i czyniący jałmużny wielkie ludowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'A ten się zawsze Bogu modląc, widział jawnie w widzeniu, jakoby o dziewiątej godzinie na dzień, Anioła Bożego, że wszedł do niego i rzekł mu: Kornelijuszu!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'A on pilnie nań patrząc, a przestraszony będąc, rzekł: Cóż jest, Panie? I rzekł mu: Modlitwy twoje i jałmużny twoje wstąpiły na pamięć przed obliczność Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Przetoż teraz poślij męże do Joppy, a przyzwij Szymona, którego zowią Piotrem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Ten ma gospodę u niektórego Szymona, garbarza, który ma dom nad morzem; ten ci powie, co byś miał czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'A gdy odszedł Anioł, który mówił z Kornelijuszem, zawoławszy dwóch sług swoich i żołnierza pobożnego z tych, którzy przy nim ustawicznie byli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'A rozpowiedziawszy im wszystko, posłał je do Joppy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'A nazajutrz, gdy byli w drodze, a przybliżali się do miasta, wstąpił Piotr na dach, aby się modlił około godziny szóstej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'A będąc łaknącym chciał jeść; a gdy mu oni jeść gotowali, przypadło na niego zachwycenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'I ujrzał niebo otworzone i zstępujące na się naczynie niejakie, jakoby prześcieradło wielkie, za cztery rogi uwiązane i spuszczone na ziemię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'W którem były wszelkie ziemskie czworonogie zwierzęta i bestyje, i gadziny i ptastwo niebieskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'I stał się głos do niego: Wstań Piotrze! rzeż, a jedz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'A Piotr rzekł: Żadną miarą, Panie! gdyżem nigdy nie jadł nic pospolitego albo nieczystego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Tedy zasię powtóre stał się głos do niego: Co Bóg oczyścił, ty nie miej tego za nieczyste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'A to się stało po trzykroć. I wzięte jest zasię ono naczynie do nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'A gdy Piotr sam w sobie wątpił, co by to było za widzenie, które widział, tedy oto ci mężowie, którzy byli posłani do Kornelijusza, pytający się o dom Szymonowy, stali przede drzwiami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'A zawoławszy, wywiadywali się, jeźliby tam Szymon, którego zowią Piotrem, gospodę miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'A gdy Piotr myślił o onem widzeniu, rzekł mu Duch: Oto cię trzej mężowie szukają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Przetoż wstawszy, zstąp, a idź z nimi, nic nie wątpiąc, bomci ja je posłał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Tedy Piotr zstąpiwszy do onych mężów, którzy od Kornelijusza do niego posłani byli, rzekł: Otom ja jest, którego szukacie. Cóż za przyczyna, dla którejście przyszli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'A oni rzekli: Kornelijusz setnik, mąż sprawiedliwy i bojący się Boga i mający dobre świadectwo od wszystkiego narodu żydowskiego, w widzeniu jest od Anioła świętego napomniony, aby cię wezwał w dom swój i słuchał słów od ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Tedy zawoławszy ich do domu, przyjął je do gospody. A drugiego dnia Piotr szedł z nimi i niektórzy z braci z Joppy szli z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'A nazajutrz weszli do Cezaryi. A Kornelijusz czekał ich, wezwawszy powinowatych swoich i bliskich przyjaciół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'I stało się, gdy wchodził Piotr, zabieżawszy mu Kornelijusz, przypadł do nóg jego i pokłonił się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Ale go Piotr podniósł, mówiąc: Wstań! i jamci też jest człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'A rozmawiając z nim, wszedł, a znalazł wiele tych, którzy się byli zeszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'I rzekł do nich: Wy wiecie, że się nie godzi mężowi Żydowinowi przyłączać albo schadzać z cudzoziemcem; lecz mnie Bóg ukazał, żebym żadnego człowieka nie nazywał pospolitym albo nieczystym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Przetożem też nie zbraniając się przyszedł, wezwany będąc; pytam tedy, dlaczegoście mię wezwali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'A Kornelijusz rzekł: Od czwartego dnia aż do tej godziny pościłem, a o dziewiątej godzinie modliłem się w domu moim, a oto mąż niektóry stanął przede mną w odzieniu jasnem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'I rzekł: Kornelijuszu! wysłuchana jest modlitwa twoja, a jałmużny twoje przyszły na pamięć przed obliczność Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Przetoż poślij do Joppy, a przyzwij Szymona, którego nazywają Piotrem; ten ma gospodę w domu Szymona, garbarza, nad morzem, który przyszedłszy, mówić z tobą będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Zaraz tedy posłałem do ciebie, a tyś dobrze uczynił, żeś przyszedł. Teraz tedy jesteśmy wszyscy przed obliczem Bożem przytomni, abyśmy słuchali wszystkiego, coć rozkazano od Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Tedy Piotr otworzywszy usta, rzekł: Prawdziwie dochodzę tego, iż Bóg nie ma względu na osoby;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'Ale w każdym narodzie, kto się go boi, a czyni sprawiedliwość, jest mu przyjemnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'A co się tknie słowa, które posłał synom Izraelskim, opowiadając pokój przez Jezusa Chrystusa, który jest Panem wszystkiego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Wy wiecie, co się działo po wszystkiem Żydostwie, począwszy od Galilei, po chrzcie, który Jan opowiadał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Jako Jezusa z Nazaretu pomazał Bóg Duchem Świętym i mocą, który chodził, czyniąc dobrze i uzdrawiając wszystkie opanowane od dyjabła; albowiem Bóg był z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'A myśmy świadkami wszystkiego tego, co czynił w krainie Judzkiej i w Jeruzalemie, którego zabili, zawiesiwszy na drzewie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Tego Bóg wzbudził dnia trzeciego i sprawił, żeby był objawiony;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'Nie wszystkiemu ludowi, ale świadkom przedtem sporządzonym od Boga, nam, którzyśmy z nim jedli i pili po jego zmartwychwstaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'I rozkazał nam, abyśmy kazali ludowi i świadczyli, że on jest onym postanowionym od Boga sędzią żywych i umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Temu wszyscy prorocy świadectwo wydają, iż przez imię jego odpuszczenie grzechów weźmie każdy, co w niego wierzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'A gdy jeszcze Piotr mówił te słowa, przypadł Duch Święty na wszystkie słuchające tych słów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'I zdumieli się oni, którzy byli z obrzezania wierzący, którzy byli z Piotrem przyszli, że i na pogany dar Ducha Świętego jest wylany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Albowiem słyszeli je mówiące językami rozlicznemi i wielbiące Boga. Tedy odpowiedział Piotr:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Izali kto może zabronić wody, żeby ci nie byli pochrzczeni, którzy wzięli Ducha Świętego jako i my?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'I rozkazał je pochrzcić w imieniu Pańskiem. I prosili go, aby u nich został na kilka dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'I usłyszeli Apostołowie i bracia, którzy byli w Judzkiej ziemi, że i poganie przyjęli słowo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'A gdy Piotr przyszedł do Jeruzalemu, spierali się z nim ci, którzy byli z obrzezania,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Mówiąc: Wszedłeś do mężów nieobrzezanych, a jadłeś z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Tedy począwszy Piotr, powiadał im porządnie, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Byłem w mieście Joppie, modląc się; i widziałem w zachwyceniu widzenie, naczynie niejakie zstępujące jako prześcieradło wielkie, za cztery rogi uwiązane, i spuszczone z nieba, i przyszło aż do mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'W które pilnie wejrzawszy, obaczyłem i widziałem czworonogie ziemskie zwierzęta i bestyje, i gadziny, i ptastwo niebieskie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'I usłyszałem głos mówiący do mnie: Wstań, Piotrze; rzeż, a jedz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'I rzekłem: Żadną miarą, Panie! albowiem nigdy nic pospolitego albo nieczystego nie wchodziło w usta moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Tedy mi odpowiedział po wtóre głos z nieba: Co Bóg oczyścił, ty nie miej tego za nieczyste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'A to się stało po trzykroć i zasię to wszystko wciągniono do nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'A oto zarazem trzej mężowie stanęli przed domem, w którymem był, posłani będąc do mnie z Cezaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'I rzekł mi Duch, abym z nimi szedł, nic nie wątpiąc. Szli też ze mną i ci sześć bracia, i weszliśmy do domu onego męża;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Który nam oznajmił, jako widział Anioła w domu swym stojącego i mówiącego do siebie: Poślij męże do Joppy, a przyzwij Szymona, którego zowią Piotrem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'On ci powie słowa, przez które zbawiony będziesz ty i wszystek dom twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'A gdym ja począł mówić, przypadł Duch Święty na nie, jako i na nas na początku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'I wspomniałem na słowo Pańskie, jako był powiedział: Janci chrzcił wodą, ale wy będziecie ochrzczeni Duchem Świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Ponieważ im tedy Bóg dał równy dar i jako i nam, wierzącym w Pana Jezusa Chrystusa, i któżem ja był, abym mógł zabronić Bogu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'A to usłyszawszy, uspokoili się i chwalili Boga mówiąc; Toć tedy i poganom dał Bóg pokutę ku żywotowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Lecz oni, którzy byli rozproszeni przed utrapieniem, które się stało dla Szczepana, przeszli aż do Fenicyi i Cypru, i do Antyjochii, nikomu nie opowiadając słowa Bożego, tylko samym Żydom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'A byli niektórzy z nich mężowie z Cypru i z Cyreny, którzy przyszedłszy do Antyjochii, mówili Grekom, opowiadając Pana Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'A była z nimi ręka Pańska, a wielki poczet uwierzywszy, nawrócił się do Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'I przyszła o nich wieść do uszów zboru, który był w Jeruzalemie, i posłali Barnabasza, aby szedł aż do Antyjochii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Który tam przyszedłszy a ujrzawszy łaskę Bożą, uradował się i napominał wszystkich, aby w przedsięwzięciu serca trwali przy Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Albowiem był mąż dobry i pełen Ducha Świętego i wiary. I przybyło wielkie mnóstwo Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Potem odszedł Barnabasz do Tarsu, aby szukał Saula, a znalazłszy go, przyprowadził go do Antyjochii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'I bawili się przez cały rok przy onym zborze, i uczyli mnóstwo wielkie; a najpierwej w Antyjochii uczniowie nazwani są Chrześcijanami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'A w one dni przyszli prorocy z Jeruzalemu do Antyjochii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'A powstawszy jeden z nich imieniem Agabus, oznajmił przez Ducha, iż miał być głód wielki po wszystkim okręgu ziemskiem, który też był za Klaudyjusza cesarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Tedy uczniowie, każdy z nich według przemożenia swego, postanowili posłać na wspomożenie braci, którzy mieszkali w Judzkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Co też uczynili, posławszy do starszych przez rękę Barnabaszową i Saulową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'A pod onże czas, udał się na to Herod król, aby trapił niektóre ze zboru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'I zabił Jakóba, brata Janowego, mieczem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'A widząc, że się to podobało Żydom, umyślił pojmać i Piotra: (a były dni przaśników).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Którego pojmawszy, podał do więzienia, poruczywszy go szesnastu żołnierzom, aby go strzegli, chcąc go po wielkanocy wywieść ludowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Tedy strzeżono Piotra w więzieniu, a modlitwa ustawiczna działa się od zboru do Boga za nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'A gdy go już miał wywieść Herod, onejże nocy spał Piotr między dwoma żołnierzami, związany dwoma łańcuchami, a stróże przed drzwiami strzegli więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'A oto Anioł Pański przystąpił, a światłość się rozświeciła w gmachu; a trąciwszy w bok Piotra, obudził go, mówiąc: Wstań rychło! I opadły łańcuchy z rąk jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'I rzekł Anioł do niego: Opasz się, a powiąż obuwie twoje. I uczynił tak. I rzekł mu: Odziej się w płaszcz twój, a pójdź za mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Tedy wyszedłszy Piotr, szedł za nim, a nie wiedział, że się to działo po prawdzie, co się działo przez Anioła; lecz mniemał, że widzenie widział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'A gdy minęli pierwszą i wtórą straż, przyszli do bramy żelaznej, która wiedzie do miasta; a ta się im sama przez się otworzyła. A wyszedłszy, przeszli jednę ulicę, a zarazem odstąpił Anioł od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Tedy Piotr przyszedłszy do siebie rzekł: Teraz znam prawdziwie, iż posłał Pan Anioła swego i wyrwał mię z ręki Herodowej i ze wszystkiego oczekiwania ludu żydowskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'A obaczywszy się, przyszedł do domu Maryi, matki Janowej, którego nazywano Markiem, gdzie się ich było wiele zgromadziło i modlili się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'A gdy Piotr kołatał we drzwi u przysionka, wyszła dzieweczka, imieniem Rode, aby posłuchała:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'A poznawszy głos Piotrowy, od radości nie otworzyła drzwi, ale wbieżawszy oznajmiła, iż Piotr stoi u drzwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'A oni rzekli do niej: Szalejesz! Wszakże ona twierdziła, iż się tak rzecz ma. A oni rzekli: Anioł jego jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Ale Piotr nie przestał kołatać; a gdy otworzyli, ujrzeli go i zdumieli się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'A skinąwszy na nie ręką, aby umilknęli, rozpowiedział im, jako go Pan wywiódł z więzienia i rzekł: Oznajmijcie to Jakóbowi i braciom. A wyszedłszy, szedł na inne miejsce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'A gdy był dzień, stał się rozruch niemały między żołnierzami o to, co by się z Piotrem stało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Lecz Herod, gdy się o nim wywiadywał, a nie znalazł go, uczyniwszy sąd o stróżach, kazał je na stracenie wywieść; a wyjechawszy z Judzkiej ziemi do Cezaryi, mieszkał tam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'A natenczas Herod myślił o wojnie przeciwko Tyryjczykom i Sydończykom; ale oni jednomyślnie przyszli do niego, a namówiwszy Blasta, podkomorzego królewskiego, prosili o pokój, dlatego iż kraina ich miała żywność z dzierżawy królewskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'A dnia pewnego Herod oblekłszy się w szatę królewską i siadłszy na stolicy, uczynił rzecz do nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'A lud wołał: Głos Boży a nie człowieczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'A zarazem uderzył go Anioł Pański, przeto, że nie dał chwały Bogu, a będąc roztoczony od robactwa, zdechł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'A słowo Pańskie rozrastało się i rozmnażało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'A Barnabasz i Saul wrócili się z Jeruzalemu, wykonawszy posługę, wziąwszy z sobą Jana, którego nazywano Markiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'A byli w Antyjochii we zborze, który tam był, niektórzy prorocy i nauczyciele, jako Barnabasz i Symeon, którego zwano Niger, i Lucyjus Cyrenejczyk, i Manahen, który był wychowany z Herodem Tetrarchą, i Saul.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'A gdy oni służbę Pańską jawnie odprawiali i pościli, rzekł im Duch Święty: Odłączcie mi Barnabasza i Saula do tej sprawy, do którejm ich powołał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Tedy poszcząc i modląc się, i wkładając na nie ręce, odprawili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Oni tedy wysłani będąc od Ducha Świętego, przyszli do Seleucyi, a stamtąd płynęli do Cypru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'A gdy byli w Salaminie, opowiadali słowo Boże w bóżnicach żydowskich, a mieli z sobą i Jana do usługi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'A przeszedłszy onę wyspę aż do Pafu, znaleźli tam jakiegoś czarnoksiężnika, fałszywego proroka, Żyda, któremu imię było Barjezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Który był przy zacnym staroście, Sergijuszu Pawle, mężu roztropnym. Ten przyzwawszy Barnabasza i Saula, pragnął słuchać słowa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Lecz się im sprzeciwił Elimas, on czarnoksiężnik, (albowiem się tak wykłada imię jego), starając się, jakoby starostę od wiary odwrócił:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Tedy Saul, (którego zowią i Pawłem) napełniony będąc Ducha Świętego, a pilnie na niego patrząc,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Rzekł: O pełny wszelkiej zdrady i wszelkiej przewrotności, synu dyjabelski, nieprzyjacielu wszelkiej sprawiedliwości! nie przestanieszże podwracać prostych dróg Pańskich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'A oto teraz ręka Pańska nad tobą: i będziesz ślepym, nie widząc słońca aż do czasu. A zarazem przypadła na niego chmura i ciemność, a błąkając się szukał, kto by go wiódł za rękę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Tedy widząc starosta, co się stało, uwierzył, zdumiewając się nad nauką Pańską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'A puściwszy się z Pafu Paweł i ci, którzy z nim byli, przyszli do Pergi Pamfiliejskiej. A Jan odszedłszy od nich, wrócił się do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'A oni odszedłszy z Pergi, przyszli do Antyjochii Pisydejskiej, a wszedłszy do bóżnicy w dzień sobotni, usiedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'A po przeczytaniu zakonu i proroków, posłali do nich przełożeni bóżnicy, mówiąc: Mężowie bracia! macieli wolę jakie napominanie uczynić do ludu, mówcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Tedy powstawszy Paweł, a ręką skinąwszy rzekł: Mężowie Izraelscy i którzy się boicie Boga! słuchajcie:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Bóg ludu tego Izraelskiego wybrał ojców naszych i wywyższył lud, gdy byli przychodniami w ziemi egipskiej, i w ramieniu wyciągnionem wywiódł je z niej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'I przez czas czterdziestu lat znosił obyczaje ich na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'A wygładziwszy siedm narodów w ziemi Chananejskiej, losem rozdzielił między nie onę ziemię ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'A potem około czterysta i pięćdziesiąt lat dawał im sędziów, aż do Samuela proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'A od onego czasu prosili o króla. I dał im Bóg Saula, syna Cysowego, męża z pokolenia Benjaminowego, przez lat czterdzieści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'A gdy go odrzucił, wzbudził im Dawida za króla, któremu też świadectwo wydawając powiedział: Znalazłem Dawida, syna Jessego, męża według serca mego, który będzie czynił wszystkę wolę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Z jegoż nasienia Bóg według obietnicy wzbudził Izraelowi zbawiciela Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Przed którego przyjściem kazał Jan chrzest pokuty wszystkiemu ludowi Izraelskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'A gdy Jan dokonał biegu swego, rzekł: Kim mię być mniemacie? Nie jestem ja, ale oto idzie za mną, u którego nóg obuwia nie jestem godzien rozwiązać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Mężowie bracia, synowie narodu Abrahamowego i którzy się między wami Boga boją! wamci słowo zbawienia tego posłane jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Albowiem ci, co mieszkają w Jeruzalemie i przełożeni ich, nie znając tego Jezusa i głosów prorockich, które przez każdy sabat bywają czytane, wypełnili je, osądziwszy go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'A żadnej przyczyny śmierci w nim nie znalazłszy, prosili Piłata, aby był zabity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'A gdy wykonali wszystko, co o nim było napisane, zdjąwszy go z drzewa, włożyli go do grobu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Ale go Bóg wzbudził od umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Który widziany jest przez wiele dni od tych, którzy z nim pospołu przyszli z Galilei do Jeruzalemu, którzy są świadkami jego przed ludem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'I my wam opowiadamy tę obietnicę, która się ojcom stała, iż ją Bóg wypełnił nam, dziatkom ich, wzbudziwszy Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Jako też w Psalmie wtórym napisane jest: Syn mój jesteś ty, jam ciebie dziś spłodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'A iż go wzbudził od umarłych, aby się więcej nie wrócił do skażenia, tak powiedział: Dam wam święte dobrodziejstwa Dawidowe wierne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Przeto i indziej powiada: Nie dasz Świętemu twemu widzieć skażenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Albowiemci Dawid za wieku swego usłużywszy woli Bożej, zasnął i przyłączony jest do ojców swoich, a widział skażenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Lecz ten, którego Bóg wzbudził, nie widział skażenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Niechże wam tedy będzie wiadomo, mężowie bracia, iż się wam przez tego opowiada odpuszczenie grzechów:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'I od wszystkiego od czegoście nie mogli być przez zakon Mojżeszowy usprawiedliwieni, przez tego każdy wierzący usprawiedliwiony bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'A przetoż patrzcie, aby na was nie przyszło to, co powiedziano w prorokach:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Obaczcie wy wzgardziciele i dziwujcie się, a wniwecz się obróćcie; bo ja sprawuję sprawę za dni waszych, sprawę, której nie wierzycie, choćby wam kto o niej powiadał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'A gdy oni wychodzili z bóżnicy żydowskiej, prosili ich poganie, aby i w drugi sabat mówili do nich też słowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'A po rozpuszczeniu zgromadzenia, poszło wiele Żydów i nabożnych nowowierników za Pawłem i Barnabaszem, którzy mówiąc do nich, radzili im, aby trwali w łasce Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'A w drugi sabat niemal wszystko miasto się zgromadziło na słuchanie słowa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Tedy Żydowie widząc lud, napełnieni są zazdrością i sprzeciwiali się temu, co Paweł powiadał, mówiąc przeciwko temu i bluźniąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'A Paweł i Barnabasz, bezpiecznie mówiąc, rzekli: Wamci najpierwej miało być opowiadane słowo Boże; ale ponieważ je odrzucacie, a sądzicie się być niegodnymi żywota wiecznego, oto się obracamy do pogan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Albowiem nam tak rozkazał Pan, mówiąc: Położyłem cię światłością poganom, abyś był zbawieniem aż do krajów ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'A słysząc to poganie, radowali się i wielbili słowo Pańskie, i uwierzyli, ilekolwiek ich było sporządzonych do żywota wiecznego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'I roznosiło się słowo Pańskie po wszystkiej onej krainie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'A Żydowie poduszczali niewiasty nabożne i uczciwe, i przedniejsze w mieście; a wzbudzili prześladowanie przeciwko Pawłowi i przeciwko Barnabaszowi, i wygnali je z granic swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'A oni otrząsnąwszy proch z nóg swoich na nie, przyszli do Ikonii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'A uczniowie byli napełnieni radości i Ducha Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'I stało się w Ikonii, że także weszli do bóżnicy żydowskiej, a tak mówili, że uwierzyło i Żydów, i Greków wielkie mnóstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Lecz Żydowie, którzy nie uwierzyli, podburzyli i zajątrzyli serca pogan przeciwko braciom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'I byli tam przez długi czas, bezpiecznie mówiąc w Panu, który dawał świadectwo słowu łaski swojej i czynił to, że się działy znamiona i cuda przez ręce ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'I rozerwało się mnóstwo miejskie, a byli jedni z Żydami a drudzy z Apostołami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'A gdy się wzburzyli i poganie, i Żydzi z książęty swoimi, aby je zelżyli i ukamionowali:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Zrozumiawszy to, uciekli do miast Likaońskich, do Listry i do Derby, i do okolicznej krainy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'A tam kazali Ewangieliję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'A mąż niektóry w Listrze chory na nogi siedział, będąc chromy z żywota matki swojej, który nigdy nie chodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Ten słuchał Pawła mówiącego; który nań pilnie patrząc i widząc, iż miał wiarę, żeby mógł być uzdrowiony,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Rzekł wielkim głosem: Stań prosto na nogi twoje; i wyskoczył i chodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'A lud widząc, co Paweł uczynił, podnieśli głos swój, mówiąc po likaońsku: Bogowie stawszy się podobni ludziom, zstąpili do nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'I nazwali Barnabasza Jowiszem, a Pawła Merkuryjuszem, ponieważ on prowadził rzecz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Tedy kapłan Jowisza, który był przed miastem ich, woły z wieńcami do wrót przywiódłszy, chciał ofiary z ludem sprawować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Co gdy usłyszeli Apostołowie Barnabasz i Paweł, rozdarłszy szaty swoje, wpadli między lud, wołając,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'I mówiąc: Mężowie! cóż to czynicie? I myśmyć ludzie, tymże biedom jako i wy poddani, którzy wam opowiadamy, abyście się od tych marności nawrócili do Boga żywego, który uczynił niebo i ziemię i morze, i wszystko co w nich jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Który za przeszłych wieków dopuszczał wszystkim poganom, aby chodzili za drogami swemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Aczkolwiek nie zaniechał samego siebie prócz świadectwa, czyniąc dobrze, dawając nam z nieba dżdże i czasy urodzajne, napełniając pokarmem i weselem serca nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'A to mówiąc, zaledwie uspokoili lud, że im nie ofiarował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'A nadeszli z Antyjochyi i z Ikonii Żydowie, którzy namówiwszy lud i ukamionowawszy Pawła, wywlekli za miasto, mniemając żeby umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Lecz gdy go uczniowie obstąpili, wstawszy wszedł do miasta, a nazajutrz odszedł z Barnabaszem do Derby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'A opowiedziawszy Ewangieliję onemu miastu i wiele uczniów pozyskawszy, wrócili się do Listry, do Ikonii, i do Antyjochyi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Utwierdzając dusze uczniów i napominając, aby trwali w wierze, i mówiąc: Że przez wiele ucisków musimy wnijść do królestwa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'A gdy im przez głosy postanowili starsze w każdym zborze i modlili się z postami, poruczyli je Panu, w którego uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'A przeszedłszy Pisydyję, przyszli do Pamfilii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'I opowiedziawszy słowo Boże w Pergi, poszli do Atalii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'A stamtąd płynęli do Antyjochyi, skąd byli oddani łasce Bożej ku tej sprawie, którą wykonali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'A gdy tam przyszli i zgromadzili zbór, oznajmili, co Bóg przez nie uczynił, a iż poganom drzwi wiary otworzył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'I mieszkali tam czas niemały z uczniami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'A niektórzy przyszedłszy z Judzkiej ziemi, nauczali braci: Iż jeźli się nie obrzeżecie według zwyczaju Mojżeszowego, nie możecie być zbawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'A gdy różnicę i spór niemały Paweł i Barnabasz mieli z nimi, postanowili, aby Paweł i Barnabasz i niektórzy inni z nich szli do Apostołów i do starszych do Jeruzalemu, z strony tego sporu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Oni tedy będąc odprowadzeni od zboru, szli przez Fenicyję i Samaryję, powiadając o nawróceniu poganów i uczynili wielką radość wszystkim braciom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'A gdy przyszli do Jeruzalemu, przyjęci byli od zboru i od Apostołów, i starszych, i opowiedzieli, cokolwiek Bóg przez nie czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Ale powstali niektórzy z sekty Faryzeuszów, którzy byli uwierzyli, mówiąc: Że ich trzeba obrzezać i rozkazać im, żeby zachowali zakon Mojżeszowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Zgromadzili się tedy Apostołowie i starsi, aby wejrzeli w tę sprawę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'A gdy był wielki spór o tem, powstawszy Piotr, rzekł do nich: Mężowie bracia! wy wiecie, że od dawnych dni Bóg mię obrał między wami, aby przez usta moje poganie słuchali słowa Ewangielii i uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'A Bóg, który zna serca, wydał im świadectwo, dawszy im Ducha Świętego, jako i nam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'I nie uczynił żadnej różnicy między nami a nimi, wiarą oczyściwszy serca ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Przetoż teraz, przecz kusicie Boga, kładąc jarzmo na szyję uczniów, którego ani ojcowie nasi, ani myśmy znosić nie mogli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Ale przez łaskę Pana Jezusa Chrystusa wierzymy, iż będziemy zbawieni tym sposobem, jako i oni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'I milczało wszystko ono mnóstwo, a słuchali Barnabasza i Pawła, którzy opowiadali, jako wielkie znamiona i cuda czynił Bóg przez nie między pogany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'A gdy oni umilknęli, odpowiedział Jakób, mówiąc: Mężowie bracia! słuchajcie mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Szymon powiedział, jako Bóg najpierwej wejrzał na pogany, aby z nich wziął lud imieniowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'A z tem się zgadzają mowy prorockie, jako jest napisano:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Potem się wrócę, a pobuduję zasię przybytek Dawidowy upadły, a obaliny jego zasię pobuduję i znowu go wystawię,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Aby ci, co pozostali z ludzi, szukali Pana i wszyscy narodowie, nad którymi wzywano imienia mojego, mówi Pan, który to wszystko czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'Znajomeć są Bogu od wieku wszystkie sprawy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Przetoż moje zdanie jest, żeby nie trwożyć tych, którzy się z poganów do Boga nawracają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Ale raczej pisać do nich, aby się wstrzymywali od splugawienia bałwanów i od wszeteczeństwa, i od rzeczy dławionych, i ode krwi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Albowiem Mojżesz od dawnych wieków ma w każdym mieście te, którzy go opowiadają, gdyż go w bóżnicach na każdy sabat czytają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Tedy się zdało Apostołom i starszym ze wszystkim zborem, aby wybrane spośród siebie męże posłali do Antyjochyi z Pawłem i z Barnabaszem, to jest Judasa, którego zwano Barsabaszem, i Sylę, męże przedniejsze między braćmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Napisawszy to przez rękę ich: Apostołowie i starsi, i bracia tym, którzy są w Antyjochyi i w Syryi, i w Cylicyi, braciom którzy są z pogan, zdrowia życzymy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Ponieważeśmy słyszeli, że niektórzy wyszedłszy od nas, zatrwożyli was słowy, wątląc dusze wasze, a mówiąc, że się musicie obrzezać i zakon zachowywać, którymeśmy tego nie poruczyli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Zdało się nam jednomyślnie zgromadzonym, posłać do was męże wybrane z miłymi naszymi, Barnabaszem i z Pawłem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'Z ludźmi, którzy wydali dusze swe dla imienia Pana naszego, Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Przetoż posłaliśmy Judasa i Sylę, którzy wam i ustnie toż powiedzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Albowiem zdało się Duchowi Świętemu i nam, abyśmy więcej nie kładli na was żadnego ciężaru, oprócz tych rzeczy potrzebnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'Abyście się wstrzymywali od rzeczy bałwanom ofiarowanych, i od krwi, i od rzeczy dławionych, i od wszeteczeństwa, których rzeczy jeźli się strzec będziecie, dobrze uczynicie. Miejcie się dobrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'A tak oni będąc odprawieni, przyszli do Antyjochyi, a zgromadziwszy mnóstwo, oddali list.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'A przeczytawszy, radowali się z onej pociechy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'A Judas i Sylas, będąc i oni prorokami, długiemi słowy napominali braci i utwierdzali je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'A zamieszkawszy tam do czasu, odprawieni są z pokojem od braci do Apostołów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Lecz Syli zdało się tam zostać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Także Paweł i Barnabasz zamieszkali w Antyjochyi, nauczając i opowiadając z wieloma innymi słowo Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'A po kilku dniach rzekł Paweł do Barnabasza: Wróciwszy się, nawiedźmy braci naszych po wszystkich miastach, w którycheśmy opowiadali słowo Pańskie, jakoli się mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Tedy Barnabasz radził, aby z sobą wzięli i Jana, którego zwano Markiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Ale się to Pawłowi nie zdało brać tego z sobą, który był odszedł od nich z Pamfilii, a nie chodził z nimi na onę pracę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'I wszczął się między nimi wielki gniew, tak iż odszedł jeden od drugiego, a Barnabasz wziąwszy z sobą Marka, płynął do Cypru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Ale Paweł obrawszy sobie Sylę, wyszedł, będąc poruczony łasce Bożej od braci:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'I przechodził Syryję, i Cilicyję, utwierdzając zbory.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'I przyszedł do Derby i do Listry; a oto tam był uczeń niektóry, imieniem Tymoteusz, syn niektórej niewiasty Żydówki wiernej a ojca Greka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Temu świadectwo dawali bracia, którzy byli w Listrze i w Ikonii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Chciał tedy Paweł, aby ten z nim szedł, którego wziąwszy, obrzezał dla Żydów, którzy byli na onych miejscach; bo wszyscy wiedzieli, że ojciec jego był Grekiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'A gdy chodzili po miastach, podawali im ku chowaniu ustawy, które były postanowione od Apostołów i starszych, którzy byli w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'A tak się zbory utwierdzały w wierze i przybywało ich w liczbie na każdy dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Tedy przeszedłszy Frygiję i Galatską krainę, zawściągnieni będąc od Ducha Świętego, aby nie opowiadali słowa Bożego w Azyi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Przyszedłszy do Mizyi, kusili się iść do Bitynii, ale im Duch Jezusowy nie dopuścił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'Tedy minąwszy Mizyję, zstąpili do Troady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'I pokazało się Pawłowi w nocy widzenie: Mąż niejaki Macedończyk stał, prosząc go i mówiąc: Przepraw się do Macedonii, a ratuj nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'A ujrzawszy to widzenie, zaraześmy się starali o to, jakobyśmy się puścili do Macedonii, będąc tego pewni, iż nas Pan powołał, abyśmy im kazali Ewangieliję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Puściwszy się tedy z Troady, prostośmy bieżeli do Samotracyi, a nazajutrz do Neapolu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'A stamtąd do Filipowa, które jest pierwsze miasto tej części Macedonii nowo osadzone; i zostaliśmy w onem mieście przez kilka dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'A w dzień sabatu wyszliśmy przed miasto nad rzekę, gdzie zwykły bywać modlitwy, a usiadłszy mówiliśmy do niewiast, które się tam były zeszły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'A niektóra niewiasta, imieniem Lidyja, która szarłat sprzedawała w mieście Tyjatyrskiem, Boga się bojąca, słuchała; której Pan otworzył serce, aby pilnie słuchała tego, co Paweł mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'A gdy się ochrzciła i dom jej, prosiła, mówiąc: Ponieważeście mię osądzili wierną być Panu, wszedłszy do domu mego, mieszkajcie; i przymusiła nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'I stało się, gdyśmy szli na modlitwę, iż niektóra dzieweczka, co miała ducha wieszczego, zabieżała nam, a ta wielki zysk panom swoim przynosiła, wróżąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Ta chodząc za Pawłem i za nami, wołała mówiąc: Ci ludzie sługami są Boga najwyższego, którzy nam opowiadają drogę zbawienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'A to czyniła przez wiele dni; ale Paweł bolejąc nad tem i obróciwszy się, rzekł onemu duchowi: Rozkazuję ci w imieniu Jezusa Chrystusa, abyś wyszedł od niej. I wyszedł onejże godziny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'A widząc panowie jej, iż zginęła nadzieja zysku ich, pojmawszy Pawła i Sylę, ciągnęli je na rynek przed urząd,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'A stawiwszy je przed hetmany, rzekli: Ci ludzie czynią zamieszanie w mieście naszem, będąc Żydami:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'I opowiadają zwyczaje, których się nam nie godzi przyjmować ani zachowywać, ponieważ jesteśmy Rzymianie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'I powstało pospólstwo przeciwko nim, a hetmani rozdarłszy szaty ich, kazali je siec rózgami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'A gdy im wiele plag zadali, wrzucili je do więzienia przykazawszy stróżowi więzienia, aby ich dobrze opatrzył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Który wziąwszy takie rozkazanie, wsadził je do najgłębszego więzienia, a nogi ich zamknął w kłodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'A o północy Paweł i Sylas modląc się, chwalili Boga pieśniami, tak że je słyszeli więźniowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'I powstało z prędka wielkie trzęsienie ziemi, że się poruszyły grunty więzienia, i zarazem się otworzyły wszystkie drzwi, i wszystkich się związki rozwiązały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'A ocuciwszy się stróż więzienia i ujrzawszy otworzone drzwi u więzienia, dobył miecza, chcąc się sam zabić, mniemając, iż więźniowie pouciekali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Lecz Paweł zawołał głosem wielkim, mówiąc: Nie czyń sobie nic złego: bo jesteśmy sami wszyscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'A kazawszy zaświecić, wpadł tam, a drżąc przypadł do nóg Pawłowi i Syli:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'A wywiódłszy je z więzienia, rzekł: Panowie! co mam czynić, abym był zbawiony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'A oni rzekli: Wierz w Pana Jezusa Chrystusa, a będziesz zbawiony, ty i dom twój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'I opowiadali mu słowo Pańskie i wszystkim, którzy byli w domu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'A wziąwszy je onejże godziny w nocy, omył rany ich i ochrzcił się zaraz, on i wszyscy domownicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'A wprowadziwszy je do domu swego, nagotował im stół i weselił się ze wszystkim domem swoim, uwierzywszy Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'A gdy był dzień, posłali hetmani sługi miejskie, mówiąc: Wypuść one ludzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'I oznajmił stróż więzienia te słowa Pawłowi, iż hetmani posłali, abyście byli wypuszczeni: teraz tedy wyszedłszy, idźcie w pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Ale im Paweł rzekł: Usiekłszy nas jawnie rózgami nie przekonanych, gdyżeśmy są ludzie Rzymianie, wrzucili do więzienia; a teraz nas potajemnie wyganiają? Nic z tego; ale sami niech przyjdą i wyprowadzą nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Tedy powiedzieli hetmanom słudzy miejscy te słowa. I zlękli się, usłyszawszy, że byli Rzymianie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'A przyszedłszy, przeprosili ich, a wywiódłszy ich, prosili ich, aby wyszli z miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Wyszedłszy tedy z więzienia, weszli do Lidyi, a ujrzawszy braci pocieszyli je i odeszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'A przeszedłszy Amfipolim i Apoloniję przyszli do Tesaloniki, gdzie była bóżnica żydowska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Tedy Paweł według zwyczaju swego wszedł do nich, a przez trzy sabaty kazał im z Pisma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Wywodząc i pokazując to, że Chrystus miał cierpieć i powstać od umarłych, a iż ten Jezus jest Chrystusem, którego ja wam opowiadam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'I uwierzyli niektórzy z nich, a przyłączyli się do Pawła i do Syli, i wielkie mnóstwo nabożnych Greków, i niewiast przedniejszych niemało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Ale Żydowie, którzy nie uwierzyli, zdjęci zazdrością, przywziąwszy do siebie niektórych lekkomyślnych i złych mężów, a zebrawszy kupę uczynili rozruch w mieście, a naszedłszy na dom Jazona, szukali ich, aby ich wywiedli przed lud.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'A nie znalazłszy ich, ciągnęli Jazona i niektórych braci do przełożonych miasta, wołając: Oto ci, którzy wszystek świat wzruszyli i tu też przyszli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Które przyjął Jazon; a ci wszyscy czynią przeciwko dekretom cesarskim, powiadając, iż jest inszy król, Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'A tak wzburzyli pospólstwo i przełożonych miasta, którzy to słyszeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Ale oni wziąwszy słuszną sprawę od Jazona i od innych, puścili je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'A bracia wnet w nocy wysłali i Pawła, i Sylę do Berei; którzy tam przyszedłszy weszli do bóżnicy żydowskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'A cić byli zacniejsi nad one, co byli w Tesalonice, którzy przyjęli słowo Boże ze wszystką ochotą, na każdy dzień rozsądzając Pisma, jeźliby się tak miało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Przetoż wiele ich z nich uwierzyło, i Greckich niewiast uczciwych, i mężów niemało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'A gdy się dowiedzieli oni, co byli z Tesaloniki Żydowie, że i w Berei opowiadane było słowo Boże od Pawła, przyszli i tam, podburzając pospólstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Ale bracia wnet wysłali Pawła, aby szedł jakoby do morza; a Sylas i Tymoteusz tam zostali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'A ci, którzy prowadzili Pawła, doprowadzili go aż do Aten, a wziąwszy rozkazanie do Syli i do Tymoteusza, żeby co najrychlej przyszli do niego, odeszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'A gdy ich Paweł w Atenach czekał, poruszał się w nim duch jego, widząc ono miasto poddane bałwochwalstwu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'A przetoż miewał rozmowę z Żydami i z ludźmi nabożnymi, w bóżnicy i na rynku na każdy dzień, z kim się mu trafiło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Tedy niektórzy z Epikurejczyków i Stoików filozofowie spierali się z nim, a niektórzy mówili: Cóż wżdy ten plotkarz mówić chce? A drudzy: Zdaje się być opowiadaczem obcych bogów; bo im Jezusa i zmartwychwstanie opowiadał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'A porwawszy go, wiedli do Areopagu, mówiąc: Możemyli wiedzieć, co to jest za nowa nauka, którą ty opowiadasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Bo jakieś obce rzeczy przynosisz do uszów naszych; chcemy tedy wiedzieć, co wżdy z tego ma być?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, '(A wszyscy Ateńczycy i cudzoziemscy goście niczem inszem się nie bawili, tylko powiadaniem albo słuchaniem nowin.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Tedy Paweł stanąwszy w pośrodku Areopagu, rzekł: Mężowie Ateńscy! z każdej miary was widzę nader nabożnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Albowiem przechadzając się i przypatrując waszym nabożeństwom, znalazłem też ołtarz, na którym napisano: Nieznajomemu Bogu. Którego tedy nie znając chwalicie, tego ja wam opowiadam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Bo Bóg, który uczynił świat i wszystko, co na nim, ten będąc Panem nieba i ziemi, nie mieszka w kościołach ręką uczynionych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Ani rękoma ludzkiemi chwalony bywa, jakoby czego potrzebował, ponieważ on daje wszystkim żywot i oddech, i wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'I uczynił z jednej krwi wszystek naród ludzki, aby mieszkał po wszystkiem obliczu ziemi, zamierzywszy przedtem rozrządzone czasy i zamierzone granice mieszkania ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Aby szukali Pana, owaby go snać namacali i znaleźli, aczkolwiek od każdego z nas nie jest daleko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Albowiem w nim żyjemy i ruszamy się, i jesteśmy, jako i niektórzy z waszych poetów powiedzieli: Żeśmy i my rodziną jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Będąc tedy rodziną Bożą, nie mamy rozumieć, żeby złotu albo srebru, albo kamieniowi misternie rytemu, albo wymysłowi człowieczemu, Bóg miał być podobny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Aczkolwiek tedy przeglądał Bóg czasom tej niewiadomości, ale teraz oznajmuje ludziom wszystkim wszędy, aby pokutowali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Przeto iż postanowił dzień, w który będzie sądził wszystek świat w sprawiedliwości przez męża, którego na to naznaczył, upewniając o tem wszystkich, wzbudziwszy go od umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'A usłyszawszy o zmartwychwstaniu jedni się naśmiewali, a drudzy mówili: Będziemy cię znowu o tem słuchać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'I tak Paweł wyszedł z pośrodku ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'A mężowie niektórzy przyłączywszy się do niego, uwierzyli, między którymi też był Dyjonizyjusz Areopagitczyk i niewiasta imieniem Damarys, i inni z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Potem Paweł odszedłszy z Aten, przyszedł do Koryntu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'A znalazłszy niektórego Żyda, imieniem Akwilas, rodem z Pontu, który był świeżo z Włoch przyszedł z Pryscyllą, żoną swą, (dlatego, iż był Klaudyjusz postanowił, aby wszyscy Żydowie z Rzymu wyszli), przyszedł do nich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'A iż był tegoż rzemiosła, mieszkał u nich i robił; albowiem rzemiosło ich było robić namioty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Tedy miewał rozmowę w bóżnicy na każdy sabat i pozyskiwał i Żydy, i Greki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'A gdy przyszli z Macedonii Sylas i Tymoteusz, ściśniony był w duchu Paweł, oświadczając Żydom, że Jezus jest Chrystusem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Lecz gdy się oni sprzeciwiali i bluźnili, otrząsnąwszy proch z szat, rzekł do nich: Krew wasza na głowę waszę; jam jest czysty, od tego czasu pójdę do pogan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'A odszedłszy stamtąd wszedł do domu niejakiego człowieka, imieniem Justus, służącego Bogu, którego dom był podle samej bóżnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Lecz Kryspus, przełożony bóżnicy, uwierzył Panu ze wszystkim domem swoim, i wiele z Koryntczyków słuchając, uwierzyli i ochrzczeni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Zatem Pan rzekł Pawłowi w nocy w widzeniu: Nie bój się, ale mów, a nie milcz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Bom ja jest z tobą, a żaden się na cię nie targnie, abyć miał co złego uczynić; albowiem ja wielki lud mam w tem mieście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'I mieszkał tam rok i sześć miesięcy, nauczając u nich słowa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'A gdy Galijo był starostą w Achai, powstali jednomyślnie Żydowie przeciwko Pawłowi i przywiedli go do sądu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Ten namawia ludzi, aby przeciwko zakonowi Boga chwalili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'A gdy Paweł miał usta otworzyć, rzekł Galijo do Żydów: O Żydowie! gdyby się wam było jakie bezprawie stało, albo jaka krzywda, słusznie bym was znosił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Lecz jeźli jest jaka gadka o słowach i o imionach i o zakonie waszym, sami tego patrzcie; albowiem ja tego sędzią być nie chcę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'I odegnał je od sądowej stolicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Tedy porwawszy wszyscy Grekowie Sostena, przełożonego bóżnicy, bili go przed sądową stolicą, a Galijo na to nic nie dbał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'A Paweł pomieszkawszy tam jeszcze przez niemało dni, pożegnawszy się z braćmi, płynął do Syryi, a z nim Pryscylla i Akwilas, ogoliwszy głowę w Kienchreach: bo był uczynił ślub.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Zatem przyszedł do Efezu i tam je zostawił, a sam wszedłszy do bóżnicy, miał rozmowę z Żydami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'A gdy go oni prosili, aby u nich przez dłuższy czas zamieszkał, nie zezwolił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Ale się z nimi pożegnawszy, rzekł: Koniecznie ja muszę święto nadchodzące w Jeruzalemie obchodzić; lecz się zasię do was wrócę, będzieli wola Boża. I puścił się z Efezu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'A gdy przyszedł do Cezaryi, wstąpiwszy do Jeruzalemu a pozdrowiwszy zbór, szedł do Antyjochyi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'I zamieszkawszy tam przez niektóry czas, wyszedł obchodząc krainę Galatską i Frygiję, utwierdzając wszystkich uczniów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'A Żyd niektóry imieniem Apollos, rodem z Aleksandryi, mąż wymowny, przyszedł do Efezu, będąc możnym w Pismach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Ten był wprawiony w drogę Pańską, a pałając w duchu, mówił i nauczał pilnie o Panu, wiedząc tylko o chrzcie Janowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Ten począł bezpiecznie mówić w bóżnicy. Którego usłyszawszy Akwilas i Pryscylla, przyjęli go do siebie i dostateczniej mu wyłożyli drogę Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'A gdy chciał iść do Achai, napomniawszy go bracia, pisali do uczniów, aby go przyjęli; który gdy tam przyszedł, wiele pomagał tym, którzy uwierzyli z łaski Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Albowiem potężnie Żydy przekonywał, jawnie tego dowodząc z Pisma, iż Jezus jest Chrystusem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'I stało się, gdy Apollos był w Koryncie, iż Paweł obszedłszy górne krainy, przyszedł do Efezu; a znalazłszy tam niektórych uczniów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Rzekł do nich: Izaliście wzięli Ducha Świętego, uwierzywszy? A oni mu rzekli: Owszemeśmy ani słyszeli, jeźli jest Duch Święty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Tedy rzekł do nich: W cóżeście tedy ochrzczeni? A oni rzekli: W chrzest Janowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Zatem rzekł Paweł: Janci chrzcił chrztem pokuty, mówiąc ludowi, aby w onego, który miał przyjść po nim, uwierzyli, to jest w Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'A usłyszawszy to, ochrzczeni są w imię Pana Jezusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'A gdy na nie włożył Paweł ręce, zstąpił na nie Duch Święty i mówili językami i prorokowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'A było wszystkich mężów około dwunastu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'A wszedłszy do bóżnicy, mówił bezpiecznie przez trzy miesiące, nauczając i namawiając ich do królestwa Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'A gdy się niektórzy zatwardzili, a wierzyć nie chcieli, źle mówiąc o tej drodze Bożej przed mnóstwem, odstąpiwszy od nich, odłączył ucznie, na każdy dzień ucząc w szkole niektórego Tyranna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'A to się działo przez dwa lata, tak iż wszyscy, którzy mieszkali w Azyi, słuchali słowa Pana Jezusowego, tak Żydowie, jako i Grekowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'A nie lada cuda czynił Bóg przez ręce Pawłowe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'Tak iż na chore przynoszono chustki albo przepaski od ciała jego, i odchodziły od nich choroby, i duchowie źli wychodzili z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Tedy niektórzy z biegunów żydowskich, którzy się bawili zaklinaniem, ważyli się wzywać imienia Pana Jezusowego nad tymi, którzy mieli duchy złe, mówiąc: Poprzysięgamy was przez Jezusa, którego Paweł opowiada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'A było ich siedm synów jednego Żyda, imieniem Scewas, najwyższego kapłana, którzy to czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Tedy odpowiedziawszy duch zły, rzekł: Znam Jezusa i wiem co Paweł; ale wy coście zacz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'A rzuciwszy się na nie człowiek on, w którym był duch zły, a opanowawszy je, zmocnił się przeciwko nim, tak iż nadzy i zranieni wybiegli z onego domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'I było to wiadomo wszystkim, i Żydom i Grekom, którzy mieszkali w Efezie; i przypadł strach na nie wszystkie, i było uwielbione imię Pana Jezusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'A wiele tych, którzy uwierzyli, przychodziło, wyznawając i oznajmując sprawy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'I wiele z tych, którzy się naukami niepotrzebnemi parali, zniósłszy księgi, spalili je przed wszystkimi, a obrachowawszy cenę ich, znaleźli tego pięćdziesiąt tysięcy srebrników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Tak potężnie rosło słowo Pańskie i zmacniało się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'A gdy się to dokonało, postanowił Paweł w duchu, aby przeszedłszy Macedoniję i Achaję, szedł do Jeruzalemu, mówiąc: Iż potem, gdy tam będę, muszę i Rzym widzieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'A posławszy do Macedonii dwóch z tych, którzy mu służyli, Tymoteusza i Erasta, sam do czasu został w Azyi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'A pod on czas stał się rozruch niemały około drogi Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Albowiem niektóry złotnik, imieniem Demetryjusz, który robił kościoły srebrne Dyjany, niemały zysk przywodził rzemieślnikom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Które zgromadziwszy i inne, którzy takież rzemiosło robili, rzekł: Mężowie! wiecie, iż z tego rzemiosła mamy dostatki nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'A widzicie i słyszycie, że nie tylko w Efezie, ale mało nie po wszystkiej Azyi ten Paweł namówił i odwrócił wielki lud, mówiąc: Że to nie są bogowie, którzy są rękami uczynieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Przetoż nam się obawiać potrzeba, aby nie tylko rzemiosło nasze w lekkie poważenie nie przyszło, ale aby i kościół wielkiej bogini Dyjany za nic nie był poczytany, a żeby nie przyszło do skazy dostojeństwo jej, którą wszystka Azyja i wszystek świat chwali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'A słuchając tego i będąc pełni gniewu, krzyknęli, mówiąc: Wielka jest Dyjana Efeska!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'I było pełno po wszystkiem mieście zamieszania, i wpadli jednomyślnie na plac, porwawszy Gaja i Arystarcha, Macedończyki, podróżne towarzysze Pawłowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'A gdy Paweł chciał wnijść do pospólstwa, nie dopuścili mu uczniowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'A niektórzy też z przedniejszych mężów Azyjackich, będąc mu przyjaciołmi, posławszy do niego, prosili go, aby nie wychodził na plac.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Tedy jedni tak, a drudzy inaczej wołali; albowiem ona gromada była zamieszana, a więcej ich nie wiedziało, dlaczego się zbieżeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'A z onej zgrai wywlekli Aleksandra, którego popychali Żydowie; a Aleksander skinąwszy ręką, chciał dać sprawę ludowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Ale gdy poznali, iż był Żydem, wszczął się jednostajny głos od wszystkich, jakoby przez dwie godziny wołających: Wielka jest Dyjana Efeska!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Tedy pisarz uśmierzywszy onę zgraję, rzekł: Mężowie Efescy! i któryż jest człowiek, co by nie wiedział, iż miasto Efeskie opiekuje się kościołem wielkiej boginii Dyjany i obrazem, który spadł od Jowisza?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'A ponieważ się temu nikt sprzeciwić nie może, słuszna, abyście się uspokoili, a nic skwapliwie nie czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Albowiemeście przywiedli tych mężów, którzy nie są ani świętokradcami, ani bluźniercami boginii waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'A jeźliż Demetryjusz i ci, którzy z nim są rzemieślnicy, mają co przeciw komu, wszak bywa prawo, są też starostowie, niechże jedni drugich pozywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Jeźli się też o czem inszem pytacie, to się może w porządnem zgromadzeniu odprawić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Albowiem trzeba się obawiać, abyśmy oskarżeni nie byli o rozruch dzisiejszy, gdyż nie masz żadnej przyczyny, z której byśmy mogli dać sprawę, żeśmy się tu zbiegli. A to powiedziawszy, rozpuścił ono zgromadzenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'A gdy się on rozruch uciszył, zwoławszy Paweł uczniów i z nimi się pożegnawszy, wyszedł stamtąd, aby szedł do Macedonii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'A przeszedłszy one strony i napomniawszy je szerokiemi słowy, przyszedł do Grecyi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'A tam zamieszkawszy przez trzy miesiące, gdzie nań Żydowie zasadzkę uczynili, gdy miał płynąć do Syryi, umyślił się powrócić przez Macedoniję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'I puścił się z nim aż do Azyi Sopater, Bereeńczyk, a z Tesalończyków Arystarchus i Sekundus, i Gajus Derbejczyk, i Tymoteusz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'A z Azyjatczyków Tychykus i Trofimus, którzy wprzód poszedłszy, czekali nas w Troadzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'A my po dniach przaśników odpłynęliśmy z Filipowa i przyszliśmy do nich do Troady za pięć dni, gdzieśmy zamieszkali siedm dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Tedy pierwszy dzień po sabacie, gdy się uczniowie zgromadzili na łamanie chleba, Paweł rozmawiał z nimi, mając iść precz nazajutrz, i przedłużył mowę aż do północy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'A było wiele lamp na onej sali, gdzie byli zgromadzeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Tam siedząc niektóry młodzieniec, imieniem Eutychus, w oknie, będąc ciężkim snem zdjęty, gdy tak Paweł długo mówił, snem zmorzony padł na dół z trzeciego piętra i podniesiony jest umarły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'A Paweł zstąpiwszy na dół, przypadł nań, a ujrzawszy go, rzekł: Nie trwożcie się; boć w nim jest dusza jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'A wstąpiwszy zasię, łamał chleb i jadł, i kazał im długo aż do świtania; potem odszedł precz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'I przywiedli onego młodzieńca żywego, i byli nader ucieszeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'A my przyszedłszy wprzód do okrętu, puściliśmy się do Assonu, abyśmy stamtąd wzięli Pawła; albowiem tak był postanowił, mając sam pieszo iść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'A gdy się z nami zszedł w Assonie, wziąwszy go, przyjechaliśmy do Mityleny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'A stamtąd odpłynąwszy, drugiego dnia przyszliśmy przeciw Chyju, a trzeciego dnia przypłynęliśmy do Samu, a pomieszkawszy w Trogillu, nazajutrz przyszliśmy do Miletu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Albowiem Paweł umyślił był minąć Efez, aby mu nie przyszło czasu trawić w Azyi, bo się kwapił, jeźliby mu można, aby na dzień świąteczny był w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Tedy z Miletu posławszy do Efezu, przyzwał do siebie starszych zborowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Którzy gdy do niego przyszli, rzekł im: Wy wiecie od pierwszego dnia, któregom przyszedł do Azyi, jakom z wami po wszystek czas był,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Służąc Panu ze wszelką uniżonością i z wielą łez i pokus, które na mię przychadzały z zasadzek żydowskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Jakom się nie schraniał niczego, co by było pożyteczne, abym wam nie oznajmił i nie uczył was jawnie i po domach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Świadectwo wydawając i Żydom, i Grekom o pokucie ku Bogu i o wierze w Pana naszego Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'A oto teraz ja będąc związany duchem, idę do Jeruzalemu, nie wiedząc co tam na mię przyjść ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Tylko że Duch Święty po miastach świadczy, powiadając, że mię więzienie i uciski czekają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Wszakże ja na nic nie dbam i nie jest mi tak droga dusza moja, bym tylko bieg mój z radością wykonał i posługę, którąm wziął od Pana Jezusa na oświadczenie Ewangielii łaski Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'A teraz oto ja wiem, że już więcej nie oglądacie oblicza mojego wy wszyscy, między którymim chodził, każąc królestwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Przetoż oświadczam się wam dnia dzisiejszego, żem ja jest czysty od krwi wszystkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Albowiem nie chroniłem się, żebym wam nie miał oznajmić wszelkiej rady Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Pilnujcież tedy samych siebie i wszystkiej trzody, w której was Duch Święty postanowił biskupami, abyście paśli zbór Boży, którego nabył przez własną krew.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Boć ja to wiem, że po odejściu mojem wnijdą między was wilcy okrutni, którzy trzodzie folgować nie będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'A z was samych powstaną mężowie, mówiący rzeczy przewrotne, aby za sobą pociągnęli uczniów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Przetoż czujcie, pomnąc, żem przez trzy lata w nocy i we dnie nie przestawał napominać ze łzami każdego z was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'A teraz, bracia! poruczam was Bogu i słowu łaski jego, który może pobudować i dać wam dziedzictwo między wszystkimi poświęconymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Srebra albo złota, albo szaty nie pożądałem od nikogo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Owszem sami wiecie, że moim potrzebom i tych, którzy są ze mną, służyły te ręce,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Wszystkomci wam okazał, iż tak pracując, musimy podejmować słabe, a pamiętać na słowa Pana Jezusowe, że on rzekł: Szczęśliwsza jest rzecz dawać, niżeli brać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'A to powiedziawszy, klęknął na kolana swoje i modlił się z nimi wszystkimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'I stał się wielki płacz wszystkich, a upadając na szyję Pawłową, całowali go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Smucąc się bardzo, najwięcej tych słów, które im rzekł, że już więcej nie mieli oglądać oblicza jego. I prowadzili go do okrętu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'A gdyśmy odjechali, rozstawszy się z nimi, prosto jadąc, przyjechaliśmy do Kou, a nazajutrz do Rodu, a stamtąd do Patary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'A tam znalazłszy okręt, który miał płynąć do Fenicyi, wsiadłszy weń, jechaliśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'A gdy się nam ukazał Cypr, tedy zostawiwszy go po lewej stronie, płynęliśmy do Syryi i przypłynęliśmy do Tyru; albowiem tam z okrętu towary składać miano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'A znalazłszy uczniów, zamieszkaliśmy tam siedm dni; którzy mówili Pawłowi przez ducha, aby nie chodził do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'A gdyśmy przemieszkali one dni, wyszedłszy, poszliśmy, a wszyscy nas prowadzili z żonami i z dziatkami aż za miasto, a klęknąwszy na kolana na brzegu, modliliśmy się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'A pożegnawszy się jedni z drugimi, wstąpiliśmy w okręt, a oni się wrócili do domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'A my odprawiwszy płynienie z Tyru, przypłynęliśmy do Ptolemaidy, a pozdrowiwszy braci, zamieszkaliśmy u nich przez jeden dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'A nazajutrz wyszedłszy Paweł i my, którzyśmy z nim byli, przyszliśmy do Cezaryi, a wszedłszy w dom Filipa Ewangielisty, który był jeden z onych siedmiu, zostaliśmy u niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'A ten miał cztery córki panny, które prorokowały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'A gdyśmy tam przez niemało dni zamieszkali, przyszedł z Judzkiej ziemi prorok niektóry, imieniem Agabus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Ten przyszedłszy do nas i wziąwszy pas Pawła, a związawszy sobie ręce i nogi, rzekł: To mówi Duch Święty: Męża, którego jest ten pas, tak zwiążą w Jeruzalemie Żydowie i podadzą go w ręce poganom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'A gdyśmy to usłyszeli, prosiliśmy i my i ci, którzy na onem miejscu byli, aby on nie chodził do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Tedy odpowiedział Paweł: Cóż czynicie płacząc i serce mi psując? Albowiem ja nie tylko być związanym, ale i umrzeć jestem gotowy w Jeruzalemie dla imienia Pana Jezusowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'A gdy się on nie dał namówić, daliśmy pokój, mówiąc: Niech się stanie wola Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'A po onych dniach, wziąwszy rzeczy swoje, szliśmy do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'A szli z nami i niektórzy uczniowie z Cezaryi, wiodąc z sobą tego, u któregośmy gospodą stać mieli, niejakiego Mnazona Cypryjczyka, starego ucznia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'A gdyśmy przyszli do Jeruzalemu, wdzięcznie nas bracia przyjęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'A nazajutrz wszedł z nami Paweł do Jakóba, gdzie się byli wszyscy starsi zeszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Które pozdrowiwszy, rozpowiedział im wszystko porządnie, co Bóg uczynił między pogany przez usługę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Co oni usłyszawszy, chwalili Pana i rzekli mu: Widzisz, bracie! jako jest wiele tysięcy Żydów, którzy uwierzyli; a ci wszyscy gorliwi są miłośnicy zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Ale o tobie wzięli sprawę, że odwodzisz od Mojżesza wszystkich tych Żydów, którzy są między pogany, mówiąc, że nie mają obrzezywać dziatek, ani mają chodzić według ustaw zakonnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Cóż tedy jest? Koniecznieć się musi zejść lud; bo usłyszą, żeś przyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'A przetoż czyń to, coć mówimy; Mamy tu czterech mężów, którzy na sobie ślub mają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Tych wziąwszy do siebie, oczyść się z nimi i uczyń nakład na nie, aby ogolili głowy; a poznają wszyscy, że to, co o tobie słyszeli, nic nie jest, ale że i ty sam chodzisz przestrzegając zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'A o tych, którzy uwierzyli z pogan, myśmy pisali, stanowiąc, aby nic takowego nie zachowywali, tylko aby się wystrzegali tego, co jest ofiarowane bałwanom i od krwi, i od rzeczy dławionych, i od wszeteczeństwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Tedy Paweł wziąwszy z sobą one męże, nazajutrz oczyszczony będąc z nimi, wszedł do kościoła, opowiadając wypełnienie dni oczyszczenia, aż za każdego z nich oddana była ofiara.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'A gdy się miało wypełnić siedm dni, niektórzy Żydowie z Azyi, ujrzawszy go w kościele, wzbudzili wszystek lud i wrzucili na niego ręce,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Wołając: Mężowie Izraelscy, ratujcie! Tenci to jest człowiek, który przeciwko ludowi i zakonowi, i miejscu temu wszystkich wszędy uczy, nadto i Greki wprowadził do kościoła, i splugawił to miejsce święte.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Albowiem przedtem widzieli z nim w mieście Trofima Efeskiego, o którym mniemali, żeby go Paweł wprowadził do kościoła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'I wzruszyło się miasto wszystko, i zbiegł się lud; a pojmawszy Pawła, wywlekli go precz z kościoła, a zatem zaraz drzwi zamkniono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'A gdy się starali, jakoby go zabili, dano znać hetmanowi wojska, iż się wzruszyło wszystko Jeruzalem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Który zarazem wziąwszy z sobą żołnierze i setniki, przybieżał do nich. A oni ujrzawszy hetmana i żołnierze, przestali Pawła bić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Tedy hetman przybliżywszy się, pojmał go i kazał go dwoma łańcuchami związać, i wywiadywał się, kto by był i co by uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'A jedni tak, drudzy inaczej między ludem wołali; a gdy się nic pewnego dla zgiełku dowiedzieć nie mógł, rozkazał go wieść do obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'A gdy był u wschodu, przydało się, że go prawie żołnierze nieśli dla gwałtu onego ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Albowiem wielki lud szedł za nim, wołając: Zgładź go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'A gdy miał być Paweł prowadzony do obozu, rzekł hetmanowi: A godzi mi się co mówić do ciebie? A on rzekł: Umiesz po grecku?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'I nie tyżeś jest on Egipczanin, któryś przed temi dniami uczynił rozruch i wywiodłeś na puszczę cztery tysiące mężów zbójców?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'A Paweł rzekł: Jamci jest człowiek Żyd Tarseńczyk, mieszczanin nie z podłego miasta w Cylicyi: przetoż proszę cię, dopuść mi mówić do ludu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'A gdy on dopuścił, Paweł stojąc na wschodzie, skinął ręką na lud. A gdy było wielkie milczenie, uczynił rzecz do nich żydowskim językiem, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Mężowie bracia i ojcowie! słuchajcie mojej, którą teraz do was czynię, obrony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'A gdy usłyszeli, iż do nich rzecz czynił żydowskim językiem, tem się bardziej uciszyli. I rzekł:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Jamci jest mąż Żyd, urodzony w Tarsie Cylicyjskim, lecz wychowany w mieście tem u nóg Gamalijelowych, wyćwiczony dostatecznie w zakonie ojczystym, gorliwym będąc miłośnikiem Bożym, jako wy wszyscy dziś jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Którym prześladował tę drogę aż na śmierć, wiążąc i podawając do więzienia i męże, i niewiasty,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Jako mi tego i najwyższy kapłan jest świadkiem, i wszyscy starsi, od których też list wziąwszy do braci, jechałem do Damaszku, abym i te, którzy tam byli, związane przywiódł do Jeruzalemu, aby byli karani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'I stało się, gdym jechał i gdym się przybliżał do Damaszku o południu, że z nagła ogarnęła mię światłość wielka z nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'I upadłem na ziemię, a usłyszałem głos mówiący do mnie: Saulu! Saulu! czemu mię prześladujesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'A jam odpowiedział: Ktoś jest, Panie? I rzekł do mnie: Jam jest Jezus Nazareński, którego ty prześladujesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'A ci, którzy byli ze mną, acz widzieli światłość i polękli się, ale głosu nie słyszeli onego, który ze mną mówił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'I rzekłem: Cóż uczynię, Panie? A Pan rzekł do mnie: Wstań; idź do Damaszku, a tam ci powiedzą o wszystkiem, co postanowiono, abyś ty uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'A gdym nie widział przed jasnością światłości onej, będąc prowadzony za rękę od tych, co ze mną byli, przyszedłem do Damaszku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Tam niejaki Ananijasz, mąż pobożny według zakonu, mając świadectwo od wszystkich Żydów tam mieszkających,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Przyszedłszy do mnie i przystąpiwszy, rzekł mi: Saulu bracie, przejrzyj! A jam tejże godziny wejrzał na niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'A on rzekł: Bóg ojców naszych obrał cię, abyś poznał wolę jego, a iżbyś oglądał onego sprawiedliwego i słuchał głosu z ust jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Albowiem mu będziesz świadkiem u wszystkich ludzi tego, coś widział i słyszał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Przetoż teraz cóż odwłaczasz? Wstań, a ochrzcij się, a omyj grzechy twoje, wzywając imienia Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'I stało się potem, gdym się wrócił do Jeruzalemu, a modliłem się w kościele, żem był w zachwyceniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'I widziałem go mówiącego do siebie: Spiesz się; a wynijdź rychło z Jeruzalemu, ponieważ świadectwa twego nie przyjmą o mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'A jam rzekł: Panie! onić wiedzą, żemci ja podawał do więzienia i bijał w bóżnicach te, którzy wierzyli w cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'I gdy wylewano krew Szczepana, świadka twojego, jam też przy tem stał i zezwalałem na zabicie jego, i strzegłem szat tych, którzy go zabijali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'I rzekł do mnie: Idźże, boć ja cię do pogan daleko poślę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'A słuchali go aż do tego słowa; i podnieśli głos swój, mówiąc: Zgładź z ziemi takiego; bo nie słuszna, aby miał żyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'A gdy oni wołali i miotali szaty, i ciskali proch na powietrze,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Rozkazał go hetman wieść do obozu i kazał go biczami spróbować, żeby się dowiedział, dla której by przyczyny nań tak wołano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'A gdy go rozciągniono, aby go biczami bito, rzekł Paweł do setnika, który tuż stał: Izali się wam godzi człowieka Rzymianina nieosądzonego biczami bić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Co usłyszawszy setnik, przystąpiwszy do hetmana, powiedział mu, mówiąc: Patrz, co czynisz; boć ten człowiek jest Rzymianinem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'A przystąpiwszy hetman, rzekł mu: Powiedz mi, jeźliś ty jest Rzymianinem? A on rzekł: Tak jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'I odpowiedział hetman: Jam za wielką summę tego miejskiego prawa dostał. A Paweł rzekł: A jam się Rzymianinem i urodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'A wnetże odstąpili od niego ci, którzy go mieli wziąć na próby. Do tego i hetman się bał, dowiedziawszy się, że był Rzymianinem, a iż go był kazał związać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'A tak nazajutrz chcąc się pewnie dowiedzieć tego, o co by był oskarżony od Żydów, uwolnił go od onych związek i rozkazał się zejść przedniejszym kapłanom i wszystkiej radzie ich, a wywiódłszy Pawła, stawił go przed nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'A Paweł pilnie patrząc na onę radę rzekł: Mężowie bracia! ja ze wszystkiego sumienia dobrego chodziłem przed Bogiem aż do dnia tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Tedy Ananijasz, najwyższy kapłan, rozkazał go tym, którzy przy nim stali, bić w gębę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Tedy rzekł Paweł do niego: Uderzy cię Bóg, ściano pobielana! i ty siedzisz, sądząc mię według zakonu, a rozkazujesz mię bić przeciwko zakonowi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Zatem ci, którzy tam stali, rzekli: Najwyższemu kapłanowi Bożemu złorzeczysz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'A Paweł rzekł: Nie wiedziałem, bracia! żeby był najwyższym kapłanem; bo napisano: Książęciu ludu twego złorzeczyć nie będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'A poznawszy Paweł, że ich jedna część była Saduceuszów a druga Faryzeuszów, zawołał w onej radzie: Mężowie bracia! jam jest Faryzeusz, syn Faryzeusza: o nadzieję i o powstanie umarłych mię tu dziś sądzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'A gdy on to mówił, wszczął się rozruch między Faryzeuszami i Saduceuszami, i rozerwało się ono mnóstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Albowiem Saduceuszowie mówią, iż nie masz zmartwychwstania, ani Anioła, ani ducha; ale Faryzeuszowie to oboje wyznawają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'I wszczęło się wołanie wielkie. A powstawszy nauczeni w Piśmie z strony Faryzeuszów, spierali się mówiąc: Niceśmy złego nie znaleźli w tym człowieku; i jeźli mu co powiedział duch albo Anioł, nie walczmyż z Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'A gdy się wszczął wielki rozruch, obawiając się hetman, aby Pawła między sobą nie rozszarpali, rozkazał iść żołnierzom na dół, a wydrzeć go z pośrodku ich i odwieść do obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'A drugiej nocy stanąwszy przy nim Pan, rzekł: Bądź dobrego serca, Pawle! albowiem jakoś o mnie świadczył w Jeruzalemie, tak musisz świadczyć i w Rzymie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'A gdy był dzień, zszedłszy się niektórzy z Żydów, zawiązali się klątwą, mówiąc: Że nie mieli jeść ani pić, ażby Pawła zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'A było ich więcej niż czterdzieści, którzy to przysiężenie uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Którzy przyszedłszy do przedniejszych kapłanów i do starszych, rzekli: Klątwąśmy się zawiązali, że nic nie ukusimy, ażbyśmy Pawła zabili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Przetoż wy teraz dajcie znać hetmanowi z pozwoleniem wszystkiej rady, aby go jutro do was wywiódł, jakobyście się chcieli dostateczniej wywiedzieć o sprawach jego, a my, pierwej niż tu przyjdzie, jesteśmy gotowi go zabić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'A gdy usłyszał siostrzeniec Pawła o tej zasadzce, przyszedł, a wszedłszy do obozu, oznajmił to Pawłowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Tedy Paweł zawoławszy jednego z setników, rzekł: Zaprowadź tego młodzieńca do hetmana, bo mu coś ma powiedzieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'A tak on wziąwszy go, wiódł go do hetmana i rzekł: Paweł więzień, zawoławszy mię, prosił, abym tego młodzieńca przywiódł do ciebie, któryć ma coś powiedzieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Tedy hetman wziąwszy go za rękę i ustąpiwszy na stronę, wywiadywał się: Cóż to jest, co mi masz powiedzieć?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'A on rzekł: Postanowili Żydowie prosić cię, abyś jutro wywiódł Pawła przed radę, jakoby się chcieli co dostateczniejszego wywiedzieć o nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Ale ty nie pozwalaj im tego; bo się nań nasadziło z nich więcej niż czterdzieści mężów, którzy się klątwą zawiązali, iż nie mają ani jeść ani pić, ażby go zabili; i są już w pogotowiu, czekając od ciebie odpowiedzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Tedy hetman odprawił onego młodzieńca, przykazawszy mu, aby tego przed nikim nie powiadał, iż mu to oznajmił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'A zawoławszy dwóch niektórych z setników, rzekł: Nagotujcie dwieście żołnierzy, aby szli aż do Cezaryi; do tego siedmdziesiąt jezdnych i dwieście drabantów na trzecią godzinę w nocy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Nagotować też bydlęta, aby wsadziwszy Pawła na nie, zdrowo go zaprowadzono do Feliksa starosty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Napisawszy list w ten sposób:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Klaudyjusz Lizyjasz najmożniejszemu staroście Feliksowi zdrowia życzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Tego męża pojmanego od Żydów, gdy już od nich miał być zabity, przypadłszy z rotą, odjąłem go, dowiedziawszy się, iż jest Rzymianinem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'A chcąc wiedzieć przyczynę, dla której by nań skarżyli, wywiodłem go przed ich radę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'I znalazłem, że nań skarżą o jakieś gadki z strony zakonu ich, a że nie ma żadnej winy, dla której by był godzien śmierci albo więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'A gdy mi powiedziano o zasadzce, którą mieli uczynić Żydzi na tego męża, zarazem go posłał do ciebie, opowiedziawszy też tym, co nań skarżyli, aby przed tobą mówili to, co by przeciwko niemu mieli. Miej się dobrze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Żołnierze tedy tak, jako im było rozkazano, wziąwszy Pawła, prowadzili go nocą do Antypatrydy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'A nazajutrz, zostawiwszy jezdne, aby z nim jechali, wrócili się do obozu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Którzy przyjechawszy do Cezaryi, a oddawszy list staroście, stawili przed nim i Pawła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'A starosta list przeczytawszy, spytał go, z której by był krainy, a zrozumiawszy, że był z Cylicyi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Rzekł: Będę cię słuchał, gdy też przybędą ci, którzy na cię skarżą. I rozkazał go strzec na ratuszu Herodowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'A po pięciu dniach jechał najwyższy kapłan Ananijasz z starszymi i z Tertullem niejakim prokuratorem; którzy stanęli przed starostą przeciwko Pawłowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'A gdy był pozwany, począł nań skarżyć Tertullus, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Ponieważeśmy wielkiego pokoju dostąpili i wiele się dobrego temu narodowi stało przez twoję opatrzność, i zawsze i wszędy to ze wszelkiem dziękowaniem przyznajemy, wielmożny Feliksie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Ale żebym cię długo nie bawił, proszę, abyś nas maluczko posłuchał według zwykłej twojej ludzkości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Albowiemeśmy znaleźli tego męża zaraźliwego i wszczynającego rozruch między wszystkimi Żydami po wszystkim świecie, i herszta tej sekty Nazarejczyków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Który się też ważył splugawić kościół; któregośmy też pojmawszy, według zakonu naszego chcieli sądzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Lecz przyszedłszy hetman Lizyjasz z wielką mocą, wziął go z rąk naszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Rozkazawszy tym, którzy nań skarżą, iść do ciebie, od którego się ty sam będziesz mógł, wywiadując się, dowiedzieć tego wszystkiego, o co my nań skarżymy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Na co się zgodzili i Żydowie, mówiąc: Że się tak rzecz ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Tedy Paweł odpowiedział, gdy nań starosta skinął, aby mówił: Od wielu lat wiedząc cię być sędzią tego narodu, tem ochotniej dam sprawę o tem, co się mnie dotycze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Gdyż ty wiedzieć możesz, iż nie masz więcej dni tylko dwanaście, jakom ja przyszedł do Jeruzalemu, abym się modlił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Do tego ani mię znaleźli w kościele z kim gadającego albo buntującego lud, ani w bóżnicach, ani w mieście;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Ani tego mogą dowieść, co tu teraz na mię skarżą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'To jednak przed tobą wyznaję, że według onej drogi, którą oni powiadają być heretyctwem, tak służę ojczystemu Bogu, wierząc wszystkiemu, cokolwiek napisano w zakonie i w prorokach,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Mając nadzieję w Bogu, że będzie, którego i oni czekają, zmartwychwstanie i sprawiedliwych, i niesprawiedliwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'A sam się o to pilnie staram, abym zawsze miał sumienie bez obrażenia przed Bogiem i przed ludźmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'A po wielu latach przyszedłem, abym przyniósł jałmużny narodowi memu i ofiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Na tem znaleźli mię w kościele oczyszczonego (nie z ludem ani z rozruchem) niektórzy Żydowie z Azyi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Którzy też tu mieli stanąć przed tobą i skarżyć, jeźliby co mieli przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Albo niechaj ci sami powiedzą, jeźli we mnie znaleźli jaką nieprawość, gdym stał przed radą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'Oprócz tego jednego głosu, żem między nimi stojąc, zawołał: Dla zmartwychwstania umarłych ja dziś sądzony bywam od was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'A usłyszawszy to Feliks, odłożył sprawę ich, mówiąc: Gdy się o tej drodze dostateczniej wywiem, kiedy tu hetman Lizyjasz przyjedzie, rozeznam sprawy wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'I rozkazał setnikowi, aby strzegł Pawła i pofolgował mu, i aby nie bronił żadnemu z przyjaciół jego posługiwać mu albo go nawiedzać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'A po kilku dniach przyjechawszy Feliks, z Drusyllą, żoną swoją, która była Żydówką, kazał zawołać Pawła i słuchał go o wierze w Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'A gdy on rzecz czynił o sprawiedliwości i o powściągliwości, i o przyszłym sądzie, uląkł się Feliks i odpowiedział: Już teraz odejdź, a gdy czas upatrzę, każę cię zawołać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'A przy tem spodziewał się, że mu Paweł miał dać pieniądze, żeby go wypuścił; dlatego też tem częściej go wzywając do siebie, rozmawiał z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'A po wyjściu dwóch lat miał po sobie Feliks namiestnika, Porcyjusa Festa; a chcąc sobie Feliks łaskę zjednać u Żydów, zostawił Pawła w więzieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Tedy Festus wjechawszy na państwo, po trzech dniach przyjechał do Jeruzalemu z Cezaryi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'I stawili się przed nim najwyższy kapłan i przedniejsi z Żydów przeciwko Pawłowi, i prosili go,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Żądając łaski przeciwko niemu, aby go kazał przywieść do Jeruzalemu, uczyniwszy zasadzkę, aby go zabili na drodze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Ale Festus powiedział: Iż Paweł jest pod strażą w Cezaryi, a iż sam tam w rychle pojedzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Którzy tedy, mówi, z was mogą, niechże z nami jadą; a jeźli jest jaka wina w tym mężu, niechże nań skarżą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'A zamieszkawszy u nich nie więcej tylko dziesięć dni, jechał do Cezaryi, a nazajutrz usiadłszy na sądzie, kazał Pawła przywieść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Który gdy przyszedł, obstąpili go ci, którzy byli przyszli z Jeruzalemu Żydowie, przynosząc wiele i ciężkich skarg przeciwko Pawłowi, których dowieść nie mogli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Gdyż on sprawę dawał o sobie: Żem ani przeciwko zakonowi żydowskiemu, ani przeciwko kościołowi, ani przeciwko cesarzowi nic nie zgrzeszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Ale Festus chcąc sobie zjednać łaskę u Żydów, odpowiedziawszy Pawłowi, rzekł: Chceszże iść do Jeruzalemu, a tam o te rzeczy sądzony być przede mną?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Ale Paweł rzekł: Przed sądem cesarskim stoję, gdzie mię sądzić potrzeba: Żydówem w niczem nie krzywdził, jako i ty lepiej wiesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Bo jeźlim w czem nieprawy i co godnego śmierci uczynił, nie zbraniam się umrzeć; ale jeźli nie masz nic takiego z tych rzeczy, o które na mię skarżą, nikt mię im wydać nie może; apeluję do cesarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Tedy Festus rozmówiwszy się z radą, odpowiedział: Do cesarzaś apelował? do cesarza pójdziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'A gdy wyszło kilka dni, król Agrypa i Bernice przyjechali do Cezaryi, witać Festa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'A gdy tam niemało dni zamieszkali, Festus przełożył królowi sprawę Pawłową, mówiąc: Mąż niektóry zostawiony jest od Feliksa w więzieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Dla którego, gdym był w Jeruzalemie, stawili się przede mną przedniejsi kapłani i starsi żydowscy, prosząc o dekret przeciwko niemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Którymem odpowiedział, że tego nie mają w zwyczaju Rzymianie, aby którego człowieka mieli wydać na stracenie, ażby pierwej oskarżony miał przed sobą te, co nań skarżą, i dano by mu plac do odpowiedzi na to, w czem go obwiniają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Gdy się tedy tu zeszli, bez wszelkiej odwłoki nazajutrz zasiadłszy na sądzie, kazałem przywieść tego męża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Przeciw któremu stanąwszy ci, co nań skarżyli, żadnej winy nie przynieśli z tych, którychem się ja spodziewał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Lecz jakieś spory o swoich zabobonach mieli przeciwko niemu i o niejakim Jezusie umarłym, o którym Paweł twierdził, że żyw jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Ja tedy wątpiąc o tem, o czem ten spór był, rzekłem: Jeźliby chciał iść do Jeruzalemu, a tam o tem być sądzony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Lecz iż Paweł apelował, aby zachowany był do Augustowego rozeznania, rozkazałem go chować, ażbym go posłał do cesarza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Zatem Agrypa rzekł do Festa: Chciałbym ja tego człowieka słyszeć. A on rzekł: Jutro go usłyszysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Nazajutrz tedy, gdy przyszedł Agrypa i Bernice z wielką okazałością, i weszli w dom sądowy z hetmanami i mężami przedniejszymi miasta onego, na rozkazanie Festowe przywiedziono Pawła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'I rzekł Festus: Królu Agrypo i wszyscy mężowie, którzyście tu z nami! widzicie tego, o którego mię wszystek lud żydowski prosił, i w Jeruzalemie i tu wołając, że nie słuszna, aby ten dłużej żyć miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'A ja zrozumiawszy, że nie uczynił nic śmierci godnego, a iż i on sam apelował do Augusta, uczyniłem dekret, aby był posłany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'O którym, co bym panu pewnego pisać miał, nie mam. Przetoż kazałem go przed was przywieść, a najwięcej przed cię, królu Agrypo! abym, po rozsądzeniu sprawy jego, miał co pisać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Bo mi się niesłuszna widzi, posłać więźnia, a tego, o co go obwiniają, nie oznajmić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Zatem Agrypa rzekł do Pawła: Pozwala ci się, abyś mówił sam od siebie. Tedy Paweł wyciągnąwszy rękę, taką sprawę dał:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Na to wszystko, z czego mię obwiniają Żydowie, królu Agrypo! poczytam się być za szczęśliwego, iż dziś mam odpowiadać przed tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'A zwłaszcza, żeś ty powiadom tych wszystkich, które są między Żydami, zwyczajów i sporów; przetoż cię proszę, żebyś mię cierpliwie posłuchał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Co się tedy tknie żywota mego od młodości, jaki był od początku między narodem moim w Jeruzalemie, wiedzą wszyscy Żydowie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Będąc mi świadkami z dawna, (gdyby świadectwo wydać chcieli), iż według najdoskonalszej sekty nabożeństwa naszego żyłem, będąc Faryzeuszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'A teraz o nadzieję onej obietnicy, ojcom od Boga uczynionej, stoję przed sądem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'Której dwanaście naszych pokoleń ustawicznie dniem i nocą służąc Bogu, mają nadzieję dostąpić; o tę nadzieję skarżą na mię Żydowie, o królu Agrypo!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Cóż za rzecz do wiary niepodobną u siebie sądzicie, że Bóg umarłe wzbudza?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Mnieć się wprawdzie samemu zdało, żem był powinien przeciwko imieniowi Jezusa Nazareńskiego wiele przeciwnych rzeczy czynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Com też czynił w Jeruzalemie i wielem ja świętych sadzał do więzienia, wziąwszy moc od przedniejszych kapłanów; a gdy mieli być zabijani, wotowałem przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'I po wszystkich bóżnicach częstokroć je trapiąc, przymuszałem bluźnić, a nader wściekle przeciwko nim postępując, prześladowałem je aż i do obcych miast.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'W czem, gdym też do Damaszku jechał, mając władzę i zlecenie od przedniejszych kapłanów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'W południe, w drodze będąc, widziałem; o królu! światłość z nieba, jaśniejszą nad jasność słoneczną, która oświeciła mnie i tych, którzy jechali ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'A gdyśmy wszyscy upadli na ziemię, usłyszałem głos mówiący do siebie, a mówiący żydowskim językiem: Saulu! Saulu! przeczże mię prześladujesz? trudno tobie przeciwko ościeniowi wierzgać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'A jam rzekł: Ktoś jest, Panie? A on rzekł: Jam jest Jezus, którego ty prześladujesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Ale wstań, a stań na nogach twoich; gdyżem ci się dlatego pokazał, abym cię uczynił sługą i świadkiem tak tych rzeczy, któreś widział, jako i innych, w których ci się pokażę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Wyrywając cię od tego ludu i od pogan, do których cię teraz posyłam,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Ku otworzeniu oczu ich, aby się nawrócili z ciemności do światłości, a z mocy szatańskiej do Boga, aby tak wzięli odpuszczenie grzechów i dział między poświęconymi przez wiarę, która jest w mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Przetoż, o królu Agrypo! nie byłem nieposłusznym temu niebieskiemu widzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Ale najprzód tym, którzy są w Damaszku i w Jeruzalemie, i we wszystkiej krainie Judzkiej, i poganom opowiadałem, aby pokutowali i nawrócili się do Boga, czyniąc uczynki godne pokuty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Dla tych rzeczy Żydowie w kościele mię pojmawszy, chcieli mię zabić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Ale za pomocą Bożą jeszcze aż do dnia tego stoję, świadcząc i małemu, i wielkiemu, nic nie mówiąc oprócz tego, co opowiedzieli prorocy i Mojżesz, że się stać miało;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'To jest, iż Chrystus miał cierpieć, a będąc pierwszym z zmartwychwstania opowiadać miał światłość ludowi temu i poganom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'To gdy on ku obronie swojej powiedział, rzekł Festus głosem wielkim: Szalejesz Pawle! wielka nauka przywodzi cię do szaleństwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Ale on rzekł: Nie szaleję, najmożniejszy Feście! aleć prawdziwe i zdrowe słowa powiadam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Wie bowiem i król o tych rzeczach, przed którym bezpiecznie mówię, gdyż nie tuszę, aby co z tych rzeczy u niego było tajno, ponieważ się to nie w kącie działo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Wierzysz, królu Agrypo! prorokom? Wiem, iż wierzysz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Zatem Agrypa rzekł do Pawła: Mało byś mnie nie namówił, żebym został chrześcijaninem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Ale Paweł rzekł: Życzyłbym od Boga, aby i w mału, i w wielu, nie tylko ty, ale i wszyscy, którzy mię dziś słuchają, stali się takimi, jakim i ja jest, oprócz tych związek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'A gdy on to rzekł, wstał król i starosta, i Bernice, i ci, którzy siedzieli z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'A ustąpiwszy na stronę, rzekli jedni do drugich, mówiąc: Nic godnego śmierci albo więzienia nie czyni ten człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Lecz Agrypa rzekł do Festa: Mógł ten człowiek być uwolniony, by był do cesarza nie apelował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'A gdy skazano, żebyśmy płynęli do Włoch, oddano i Pawła, i niektóre inne więźnie setnikowi, imieniem Julijuszowi, roty Augustowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Tedy wsiadłszy w okręt Adramiteński, mając płynąć podle krain Azyi, puścili się od brzegu, a był z nami Arystarchus, Macedończyk z Tesaloniki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'A drugiego dnia przypłynęliśmy do Sydonu, kędy Julijusz ludzko się Pawłowi stawiwszy, pozwolił mu iść do przyjaciół, aby wczasu zażył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'A stamtąd się puściwszy, przypłynęliśmy pod Cypr, dlatego że były wiatry przeciwne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'A przepłynąwszy ono morze, które jest podle Cylicyi i Pamfilii, przybyliśmy do Miry, miasta Licyjskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'A tam setnik znalazłszy okręt Aleksandryjski, który płynął do Włoch, wsadził nas weń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'A gdyśmy przez wiele dni z wolna płynęli, a zaledwie przeciwko Knidowi przyjechali, przeto że nam wiatr nie dopuszczał, popłynęliśmy pod Kretę podle Salmonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'A ledwie ją przeminąwszy, przyszliśmy na miejsce niektóre, które zowią piękne porty, od którego blisko było miasto Lasea.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'A gdy czas niemały wyszedł, i już było niebezpieczne żeglowanie, przeto iż już był i post przeminął, napominał je Paweł,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Mówiąc do nich: Mężowie! widzę ja, iż z ukrzywdzeniem i z wielką szkodą nie tylko towarów i okrętów, ale też i dusz naszych będzie to żeglowanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Jednak setnik więcej ufał sprawcy okrętu i sternikowi, niż temu, co Paweł powiadał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'A gdy nie było portu sposobnego ku zimowaniu, wiele ich radę dawało puścić się stamtąd, owaby jakożkolwiek mogli przeprawiwszy się do Fenicyi, przezimować u portu Kreteńskiego, który leży między wiatrem południowym i zachodnim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'A gdy powionął wiatr z południa, mniemając, że swego przedsięwzięcia dopięli, puściwszy się od brzegu, płynęli blisko Krety.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Lecz niedługo potem uderzył na nie wiatr gwałtowny, który zowią Euroklidon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'A gdy był okręt porwany, a nie mógł się oprzeć wiatrowi, puściwszy się płynęliśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'A gdyśmy pod niektórą małą wysepkę przypłynęli, którą zowią Klauda, ledwieśmy mogli bacik zatrzymać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Który wciągnąwszy, ratunku używali, podpasawszy okręt, a bojąc się, żeby nie wpadł na hak, spuściwszy żagle, tak płynęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'A iż nami nawałności bardzo miotały, nazajutrz towary wyrzucili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'A trzeciego dnia rękami naszemi okrętowe naczynia wyrzuciliśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Lecz gdy się ani słońce, ani gwiazdy przez wiele dni nie ukazały, a nawałność niemała nalegała, na ostatek odjęta była wszystka nadzieja, żebyśmy byli mogli być zachowani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'A gdyśmy długo nie jedli, tedy Paweł stojąc w pośrodku ich rzekł: Mieliście zaprawdę, o mężowie! usłyszawszy mię, nie puszczać się od Krety, a tak ujść tej straty i zguby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Lecz i teraz napominam was, abyście byli dobrej myśli; boć nie zginie z was żadna dusza, oprócz okrętu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Albowiem stanął przy mnie tej nocy Anioł Boga tego, któregom ja jest i któremu służę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Mówiąc: Nie bój się, Pawle! musisz stawiony być przed cesarzem, a oto darował ci Bóg wszystkich, którzy płyną z tobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Przetoż bądźcie dobrej myśli, mężowie! albowiem wierzę Bogu, że tak będzie, jako mi powiedziano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'A musimy opaść na niektórej wyspie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'A gdy przyszła noc czternasta, a myśmy się błąkali po morzu Adryjatyckiem, około północy zdało się żeglarzom, iż się im okazywała niektóra kraina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Tedy spuściwszy sznur z ołowiem, znaleźli głębiej dwadzieścia sążni; a maluczko odpłynąwszy, zasię spuścili ołów i znaleźli piętnaście sążni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'A bojąc się, aby snać na miejsca ostre nie wpadli, zrzuciwszy cztery kotwice z steru, pragnęli, aby dzień był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'A gdy żeglarze myślili z okrętu uciec i spuścili bacik na morze, chcąc rzekomo od przodku okrętu zarzucać kotwice,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Rzekł Paweł setnikowi i żołnierzom: Jeźli ci nie zostaną w okręcie, wy zachowani być nie możecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Tedy żołnierze obcięli powrozy u bacika i dopuścili mu odpaść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'A między tem niż się rozedniało, napominał Paweł wszystkie, aby pokarm przyjęli, mówiąc: Dziś temu czternasty dzień, jako czekając trwacie bez pokarmu, nic nie jedząc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Dlatego proszę was, abyście pokarm przyjęli; bo to służy ku zachowaniu waszemu, gdyż żadnego z was włos z głowy nie spadnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'A to rzekłszy i chleb wziąwszy, podziękował Bogu przed wszystkimi i złamawszy począł jeść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Zatem wszyscy będąc lepszej myśli i sami pokarm przyjmowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'A było nas wszystkich dusz w okręcie dwieście siedmdziesiąt i sześć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Będąc tem pokarmem nasyceni, ulżenie czynili okrętowi, wyrzucając zboże w morze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'A gdy był dzień, nie poznali ziemi; wszakże obaczyli niejaką odnogę mającą brzeg, do którego uradzili jeźliby mogło być, przybić okręt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'A wyciągnąwszy kotwice, puścili się na morze; a rozpuściwszy zawiasy sterowe i podniósłszy żagiel po wietrze, mieli się do brzegu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Ale napadłszy na miejsce, które miało z obu stron morze, otrącili okręt; a przodek okrętu uwięznąwszy, został nie ruszając się, lecz zad rozbijał się od gwałtownych wałów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Tedy żołnierze radzili, aby więźnie pozabijali, iżby który wypłynąwszy nie uciekł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Ale setnik chcąc zachować Pawła, pohamował je od tego przedsięwzięcia i rozkazał tym, którzy mogli pływać, aby się wprzód w morze puścili i na brzeg wyszli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'Inni zasię, niektórzy na deskach, a niektórzy na sztukach okrętu. I tak się stało, że wszyscy zdrowo wyszli na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'A gdy zdrowo uszli, dopiero poznali, iż onę wyspę Melitą nazywano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Ale on gruby lud pokazał nam nie lada ludzkość; albowiem zapaliwszy stos drew, przyjęli nas wszystkich dla deszczu padającego i dla zimna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'A gdy Paweł nagarnął gromadę chrustu i kładł na ogień, wyrwawszy się żmija z gorąca, przypięła się do ręki jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'A gdy on lud gruby ujrzał onę gadzinę wiszącą u ręki jego, mówili jedni do drugich: Pewnie ten człowiek jest mężobójcą; bo choć z morza uszedł, przecię mu pomsta żywym być nie dopuściła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Lecz on otrząsnąwszy onę gadzinę w ogień, nic złego nie ucierpiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'A oni czekali, żeby opuchł albo nagle upadłszy umarł; a gdy tego długo czekali, a widzieli, iż mu się nic złego nie stało, odmieniwszy się, mówili, że jest Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'A przy onych miejscach miał folwarki przedniejszy onej wyspy, imieniem Publijusz, który przyjąwszy nas, przez trzy dni przyjacielsko podejmował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'I stało się, że ojciec onego Publijusza, mając gorączkę i biegunkę, leżał; do którego Paweł wszedłszy modlił się, a włożywszy nań ręce uzdrowił go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'To gdy się stało, tedy drudzy, którzy byli złożeni chorobami na onej wyspie, przychodzili i byli uzdrowieni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Którzy nam też wielką uczciwość wyrządzali, a gdyśmy precz płynąć mieli, nakładli nam, czego było potrzeba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'A po trzech miesiącach puściliśmy się w okręcie Aleksandryjskim, który zimował na onej wyspie, mającym za herb Kastora i Polluksa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'A przypłynąwszy do Syrakus, zamieszkaliśmy tam trzy dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'A stamtąd płynąc kołem, przybyliśmy do Regijum, a po jednym dniu, gdy powstał wiatr południowy, wtórego dnia płynęliśmy do Puteolów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Gdzie znalazłszy braci, uproszeniśmy byli od nich, żebyśmy zamieszkali u nich przez siedm dni; a takieśmy szli do Rzymu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Stąd, gdy usłyszeli bracia o nas, wyszli przeciwko nam aż do rynku Appijuszowego i do Trzech Karczem; których gdy Paweł ujrzał, podziękowawszy Bogu, wziął śmiałość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'A gdyśmy przyszli do Rzymu, setnik oddał więźnie hetmanowi wojska; ale Pawłowi dopuszczono, mieszkać osobno z żołnierzem, który go strzegł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'I stało się po trzech dniach, że zwołał Paweł przedniejszych z Żydów; a gdy się zeszli, rzekł do nich: Mężowie bracia! ja nic nie uczyniwszy przeciwko ludowi i zwyczajom ojczystym, będąc związany w Jeruzalemie, podanym jest w ręce Rzymian;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Którzy wysłuchawszy mię, chcieli mię wypuścić dlatego, że we mnie żadnej winy godnej śmierci nie było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Lecz gdy się temu sprzeciwiali Żydowie, musiałem apelować do cesarza; nie żebym miał naród mój w czem oskarżać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Dla tej tedy przyczyny zwołałem was, abym się z wami ujrzał i rozmówił; albowiem dla nadziei ludu Izraelskiego tym łańcuchem jestem opasany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Lecz oni rzekli do niego: My aniśmy listów dostali o tobie z Judzkiej ziemi, ani kto z braci przyszedłszy oznajmił, albo mówił o tobie co złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Wszakże byśmy radzi od ciebie słyszeli, co rozumiesz; albowiem o tej sekcie wiemy, iż wszędzie przeciwko niej mówią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'A postanowiwszy mu dzień, przyszło ich do niego do gospody niemało, którym z doświadczeniem wykładał królestwo Boże, namawiając ich do tych rzeczy, które są o Jezusie, z zakonu Mojżeszowego i z proroków, od poranku aż do wieczora.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Tedy niektórzy uwierzyli temu, co mówił, a niektórzy nie uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'A będąc niezgodnymi między sobą, rozeszli się, gdy Paweł rzekł to jedno słowo: Iż dobrze Duch Święty powiedział przez Izajasza proroka, do ojców naszych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Mówiąc: Idź do tego ludu, a mów: Słuchem słuchać będziecie, ale nie zrozumiecie, a widząc widzieć będziecie, ale nic nie ujrzycie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Albowiem zgrubiało serce ludu tego, a ciężko uszyma słyszeli i zamrużyli oczy swe, aby snać oczyma nie widzieli, a uszyma nie słyszeli, i sercem nie zrozumieli, i nie nawrócili się, a uzdrowiłbym je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Niechże wam tedy wiadomo będzie, iż poganom posłane jest to zbawienie Boże, a oni słuchać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'A gdy to on rzekł, odeszli Żydowie, mając między sobą wielki spór.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'I mieszkał Paweł przez całe dwa lata w najemnej gospodzie swojej, i przyjmował wszystkich, którzy przychodzili do niego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Każąc o królestwie Bożem i ucząc tych rzeczy, które są o Panu Jezusie Chrystusie, ze wszystkiem bezpieczeństwem bez przeszkody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paweł, sługa Jezusa Chrystusa, powołany Apostoł, odłączony ku opowiadaniu Ewangielii Bożej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'Którą przedtem obiecał przez proroki swoje w pismach świętych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'O Synu swoim, który się narodził z nasienia Dawidowego według ciała;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'A pokazał się Synem Bożym możnie, według Ducha poświęcenia, przez zmartwychwstanie, to jest o Jezusie Chrystusie, Panu naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Przez którego wzięliśmy łaskę i urząd apostolski ku posłuszeństwu wiary między wszystkimi narody, dla imienia jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Między którymi jesteście i wy powołani od Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'Wszystkim, którzy jesteście w Rzymie, umiłowanym Bożym, powołanym świętym, łaska niech będzie wam i pokój od Boga, Ojca naszego, i od Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Najprzód tedy dziękuję Bogu mojemu przez Jezusa Chrystusa za was wszystkich, iż wiara wasza słynie po wszystkim świecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Świadkiem mi bowiem jest on Bóg, któremu służę w duchu moim w Ewangielii Syna jego, iż bez przestanku wzmiankę o was czynię,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Zawsze w modlitwach moich prosząc, iżby mi się wżdy kiedykolwiek droga zdarzyła za wolą Bożą przyjść do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Albowiem pragnę was widzieć, abym wam mógł udzielić jakiego daru duchownego ku utwierdzeniu waszemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'To jest, abyśmy się u was zobopólnie ucieszyli przez społeczną wiarę, i waszę, i moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'A nie chcę, abyście i wy wiedzieć nie mieli, bracia! żem często zamyślał pójść do was; (alem był dotąd zawściągniony), abym miał jaki pożytek i między wami, jako i między inszymi pogany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'I Grekom, i grubym narodom, i mądrym, i głupim jestem dłużnikiem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Tak, iż ile ze mnie jest, gotowym jest i wam, którzyście w Rzymie, Ewangieliję opowiadać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Albowiem nie wstydzę się za Ewangieliję Chrystusową, ponieważ jest mocą Bożą ku zbawieniu każdemu wierzącemu, Żydowi najprzód, potem i Greczynowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Bo sprawiedliwość Boża w niej bywa objawiona z wiary w wiarę, jako napisano: Że sprawiedliwy z wiary żyć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Bo gniew Boży objawia się z nieba przeciwko wszelkiej niepobożności i niesprawiedliwości tych ludzi, którzy zatrzymują prawdę Bożą w niesprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Przeto iż co może być wiedziano o Bogu, jest w nich jawno, gdyż im Bóg objawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Bo rzeczy jego niewidzialne od stworzenia świata, przez rzeczy uczynione widzialne bywają, to jest ona wieczna jego moc i bóstwo, na to, aby oni byli bez wymówki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Przeto iż poznawszy Boga, nie chwalili jako Boga, ani mu dziękowali, owszem znikczemnieli w myślach swoich i zaćmiło się bezrozumne serce ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Mieniąc się być mądrymi, zgłupieli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'I odmienili chwałę nieskazitelnego Boga w podobieństwo obrazu skazitelnego człowieka i ptaków, i czworonogich zwierząt, i płazów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'A przetoż podał je Bóg pożądliwościom serc ich ku nieczystości, aby lżyli ciała swoje między sobą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Jako te, którzy odmienili prawdę Bożą w kłamstwo i chwalili stworzenie, i służyli mu raczej niż Stworzycielowi, który jest błogosławiony na wieki. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Dlatego podał je Bóg w namiętności sromotne, gdyż i niewiasty ich odmieniły używanie przyrodzone w ono, które jest przeciwko przyrodzeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Także i mężczyźni opuściwszy przyrodzone używanie niewiasty, zapalili się w swej pożądliwości jedni ku drugim, mężczyzna z mężczyzną hańbę płodząc, a nagrodę należącą błędowi swemu na się biorąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'A jako się im nie upodobało mieć w znajomości Boga, tak też Bóg je podał w umysł opaczny, aby czynili, co nie przystoi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'Napełnieni będąc wszelakiej nieprawości, wszeteczeństwa, przewrotności, łakomstwa, złości, pełni zazdrości, morderstwa, sporu, zdrady, złych obyczajów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Zausznicy, obmówcy, Boga nienawidzący, potwarcy, pyszni, chlubni, wynalazcy złych rzeczy, rodzicom nieposłuszni,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Bezrozumni, przymierza nie trzymający, bez przyrodzonej miłości, nieprzejednani i niemiłosierni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Którzy poznawszy prawo Boże, iż ci, co takowe rzeczy czynią, godni są śmierci, nie tylko sami je czynią, ale też przestawają z tymi, co je czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Przetoż jesteś bez wymówki, o człowiecze! który osądzasz; bo w czem drugiego osądzasz, samego siebie osądzasz, ponieważ toż czynisz, który drugiego osądzasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Lecz wiemy, iż sąd Boży jest według prawdy przeciwko tym, którzy takowe rzeczy czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Czy mniemasz, o człowiecze! który osądzasz tych, co takowe rzeczy czynią, a sam je czynisz, że ty ujdziesz sądu Bożego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Czy bogactwy dobrotliwości jego i cierpliwości, i nieskwapliwości pogardzasz, nie wiedząc, iż cię dobrotliwość Boża do pokuty prowadzi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Ale podług zatwardziałości twojej i serca niepokutującego skarbisz sobie samemu gniew na dzień gniewu i objawienia sprawiedliwego sądu Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Który odda każdemu podług uczynków jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Tym, którzy przez wytrwanie w uczynku dobrym szukają sławy i czci i nieskazitelności, odda żywot wieczny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'A zaś swarliwym i prawdzie nieposłusznym, lecz posłusznym niesprawiedliwości, odda zapalczywość i gniew;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Utrapienie i ucisk duszy każdego człowieka, który złość popełnia, Żyda najprzód, potem i Greka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'A chwałę i cześć, i pokój wszelkiemu czyniącemu dobre, Żydowi najprzód, potem i Grekowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Albowiem nie masz względu na osoby u Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'A którzykolwiek bez zakonu zgrzeszyli, bez zakonu też poginą; a którzykolwiek w zakonie zgrzeszyli, przez zakon sądzeni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, '(Gdyż nie słuchacze zakonu sprawiedliwymi są u Boga; ale czyniciele zakonu usprawiedliwieni będą.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Bo ponieważ poganie nie mający zakonu, z przyrodzenia czynią, co jest w zakonie, ci, zakonu nie mając, sami sobie są zakonem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Którzy ukazują skutek zakonu, napisany na sercach swych, z poświadczaniem sumienia ich i myśli wespół siebie oskarżających albo też wymawiających,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'W dzień, gdy sądzić będzie Bóg skryte rzeczy ludzkie według Ewangielii mojej przez Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Oto się ty nazywasz Żydem i polegasz na zakonie, a chlubisz się Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'I znasz wolę jego i rozeznajesz rzeczy różne od niej, wyćwiczony będąc z zakonu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'I masz za to, żeś jest wodzem ślepych, światłością tych, którzy są w ciemności;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'Mistrzem bezrozumnych, nauczycielem niemowlątek, mając kształt znajomości i prawdy w zakonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Który tedy uczysz drugiego, siebie samego nie uczysz? Który opowiadasz, żeby nie kradziono, kradniesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Który mówisz, żeby nie cudzołożono, cudzołożysz? który się brzydzisz bałwany, święte rzeczy kradniesz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Który się chlubisz zakonem, przez przestępstwo zakonu Boga lżysz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Albowiem imię Boże dla was bluźnione bywa między pogany, jako napisano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Boć obrzezanie jest pożyteczne, jeźlibyś pełnił zakon; ale jeźlibyś był przestępcą zakonu, twoje obrzezanie stało się nieobrzezką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Jeźliby tedy nieobrzezka przestrzegała praw zakonnych, azaż jego nieobrzezka nie będzie przyczyną za obrzezkę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'I osądzi nieobrzezka z przyrodzenia zakon pełniąca ciebie, który przez literę i obrzezkę jesteś przestępcą zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Albowiem nie ten jest Żydem, który jest Żydem na jawie, ani to jest obrzezka, która jest na jawie na ciele;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Ale który jest w skrytości Żydem i obrzezka serca, która jest w duchu, nie w literze, której chwała nie jest z ludzi, ale z Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Czemże tedy zacniejszy Żyd? albo co za pożytek obrzezki?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Wielki z każdej miary. Albowiem to najpierwsza, iż im zwierzone były wyroki Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Bo cóż na tem, jeźli niektórzy nie uwierzyli? Azaż niedowiarstwo ich niszczy wiarę Bożą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Nie daj tego Boże! I owszem niech Bóg będzie prawdziwy, a wszelki człowiek kłamcą, jako napisano: A abyś był usprawiedliwiony w mowach twoich, a żebyś zwyciężył, gdybyś sądził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Jeźli tedy niesprawiedliwość nasza Bożą sprawiedliwość zaleca, cóż rzeczemy? Azaż niesprawiedliwy jest Bóg, który gniew przywodzi? (Po ludzku mówię.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Nie daj tego Boże! albowiem jakożby Bóg sądził świat?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Bo jeźli prawda Boża przez moje kłamstwo obfitowała ku chwale jego, czemuż jeszcze i ja bywam sądzony jako grzesznik?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'A nie raczej tak mówimy: (jako nas szkalują i jako niektórzy udawają, żebyśmy mówili:) Będziemy czynić złe rzeczy, aby przyszły dobre? Których potępienie jest sprawiedliwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Cóż tedy? Mamyż nad nie? Żadnym sposobem; gdyżeśmy przedtem dowiedli, że Żydowie i Grekowie, wszyscy są pod grzechem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Jako napisano: Nie masz sprawiedliwego ani jednego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Nie masz rozumnego i nie masz, kto by szukał Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Wszyscy się odchylili, wespół się stali nieużytecznymi, nie masz kto by czynił dobre, nie masz aż do jednego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Grobem otworzonym jest gardło ich, językami swemi zdradzali, jad żmiji pod wargami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Których usta napełnione są przeklinania i gorzkości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Nogi ich prędkie są ku wylewaniu krwi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Skruszenie z biedą w drogach ich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'A drogi pokoju nie poznali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Nie masz bojaźni Bożej przed oczami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'A wiemy, iż cokolwiek zakonowi mówi, tym którzy są pod zakonem, mówi, aby wszelkie usta były zatulone i aby wszystek świat podlegał karaniu Bożemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Przeto z uczynków zakonu nie będzie usprawiedliwione żadne ciało przed oblicznością jego, gdyż przez zakon jest poznanie grzechu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Lecz teraz bez zakonu sprawiedliwość Boża objawiona jest, mająca świadectwo z zakonu i z proroków;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Sprawiedliwość, mówię, Boża przez wiarę Jezusa Chrystusa ku wszystkim i na wszystkie wierzące; boć różności nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Albowiem wszyscy zgrzeszyli i nie dostaje im chwały Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'A bywają usprawiedliwieni darmo z łaski jego przez odkupienie, które się stało w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Którego Bóg wystawił ubłaganiem przez wiarę we krwi jego, ku okazaniu sprawiedliwości swojej przez odpuszczenie przedtem popełnionych grzechów w cierpliwości Bożej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'Ku okazaniu sprawiedliwości swojej w teraźniejszym czasie, na to, aby on był sprawiedliwym i usprawiedliwiającym tego, który jest z wiary Jezusowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Gdzież tedy jest chluba? Odrzucona jest. Przez któryż zakon? Czyli uczynków? Nie, ale przez zakon wiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Przetoż mamy za to, że człowiek bywa usprawiedliwiony wiarą bez uczynków zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Izali Bóg jest tylko Bogiem Żydów? izali też nie pogan? Zaiste i pogan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Ponieważ jeden jest Bóg, który usprawiedliwi obrzezkę z wiary i nieobrzezkę przez wiarę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'To tedy zakon niszczymy przez wiarę? Nie daj tego Boże! i owszem zakon stanowimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Cóż tedy, rzeczemy, znalazł Abraham, ojciec nasz według ciała?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Bo jeźli Abraham z uczynków jest usprawiedliwiony, ma się czem chlubić, ale nie u Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Albowiem cóż Pismo mówi? Uwierzył Abraham Bogu i przyczytano mu to za sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'A robiącemu zapłata nie bywa przyczytana podług łaski, ale podług długu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Nie robiącemu zaś, lecz wierzącemu w tego, który usprawiedliwia niepobożnego, przyczytana bywa wiara jego za sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Jako i Dawid powiada, że błogosławieństwo człowieka jest, któremu Bóg przyczyta sprawiedliwość bez uczynków, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Błogosławieni, których odpuszczone są nieprawości, a których zakryte są grzechy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Błogosławiony mąż, któremu Pan grzechu nie przyczyta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'To tedy błogosławieństwo tylko na obrzezkę przychodzi, czy też na nieobrzezkę? Gdyż mówimy, iż wiara Abrahamowi jest przyczytana za sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Jakoż mu tedy jest przyczytano? Gdy był w obrzezce, czyli w nieobrzezce? Nie w obrzezce, ale w nieobrzezce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'I przyjął znak obrzezki za pieczęć sprawiedliwości onej wiary, która była w nieobrzezce, na to, aby był ojcem wszystkich wierzących w nieobrzezce, aby i onym przyczytana była sprawiedliwość;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'I aby był ojcem obrzezki, nie tylko tych, którzy są z obrzezki, ale też i tych, którzy chodzą stopami wiary ojca naszego Abrahama, która była w nieobrzezce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Albowiem nie przez zakon się stała obietnica Abrahamowi albo nasieniu jego, aby był dziedzicem świata, ale przez sprawiedliwość wiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Bo jeźli ci, którzy są z zakonu, dziedzicami są, tedyć zniszczała wiara i wniwecz się obróciła obietnica.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Gdyż zakon gniew sprawuje; albowiem gdzie zakonu nie masz, tam ani przestępstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Przetoż z wiary jest dziedzictwo, aby było z łaski, i żeby była warowna obietnica wszystkiemu nasieniu, nie tylko temu, które jest z zakonu, ale i temu, które jest z wiary Abrahamowej, który jest ojcem nas wszystkich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(Jako napisano: Ojcem wielu narodów wystawiłem cię) przed Bogiem, któremu uwierzył, który ożywia umarłe i który przywołuje te rzeczy, których nie masz, i jakoby były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Który (Abraham) przeciwko nadziei w nadzieję uwierzył, że się stanie ojcem wielu narodów według tego, co mu powiedziano: Tak będzie nasienie twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'A nie będąc słabym w wierze, nie patrzył na ciało swoje już obumarłe, mając około stu lat, ani na obumarły żywot Sary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'O obietnicy tedy Bożej nie wątpił z niedowiarstwa; ale się umocnił wiarą i dał chwałę Bogu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Będąc też tego pewien, że cokolwiek on obiecał, mocen jest i uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Przetoż przyczytano mu to za sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'A nie napisano tego dla niego samego, iż mu to przyczytano,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'Ale i dla nas, którym ma być przyczytano, którzy wierzymy w tego, który wzbudził Jezusa, Pana naszego, z martwych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Który wydany jest dla grzechów naszych, a wstał z martwych dla usprawiedliwienia naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Będąc tedy usprawiedliwieni z wiary, pokój mamy z Bogiem przez Pana naszego Jezusa Chrystusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Przez któregośmy też przystęp otrzymali wiarą ku łasce, w której stoimy i chlubimy się nadzieją chwały Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'A nie tylko to, ale się też chlubimy z ucisków, wiedząc, iż ucisk cierpliwość sprawuje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'A cierpliwość doświadczenie, a doświadczenie nadzieję,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'A nadzieja nie pohańbia, przeto iż miłość Boża rozlana jest w sercach naszych przez Ducha Świętego, który nam jest dany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Albowiem Chrystus, gdy jeszcze byliśmy mdłymi, według czasu umarł za niepobożne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Choć ledwie by kto umarł za sprawiedliwego; wszakże za dobrego snaćby się kto umrzeć ważył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Lecz zaleca Bóg miłość swoję ku nam, że gdy jeszcze byliśmy grzesznymi, Chrystus za nas umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Daleko tedy więcej teraz usprawiedliwieni będąc krwią jego, zachowani będziemy przez niego od gniewu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Bo jeźliże będąc nieprzyjaciołmi, pojednaniśmy z Bogiem przez śmierć Syna jego; daleko więcej będąc pojednani, zachowani będziemy przez żywot jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'A nie tylko to, ale się też chlubimy Bogiem przez Pana naszego Jezusa Chrystusa, przez któregośmy teraz pojednanie otrzymali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Przetoż jako przez jednego człowieka grzech wszedł na świat, a przez grzech śmierć; tak też na wszystkich ludzi śmierć przyszła, ponieważ wszyscy zgrzeszyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Albowiem aż do zakonu grzech był na świecie; ale grzech nie bywa przyczytany, gdy zakonu nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Lecz śmierć królowała od Adama aż do Mojżesza i nad tymi, którzy nie zgrzeszyli, na podobieństwo przestępstwa Adamowego, który jest wzorem onego, który miał przyjść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Ale nie jako upadek, tak i dar z łaski; albowiem jeźli przez upadek jednego wiele ich pomarło, daleko więcej łaska Boża i dar z łaski onego jednego człowieka Jezusa Chrystusa na wiele ich opływała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'A dar nie jest taki, jako to, co przyszło przez jednego, który zgrzeszył. Albowiem wina jest z jednego upadku ku potępieniu, ale dar z łaski z wielu upadków ku usprawiedliwieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Albowiem jeźli dla jednego upadku śmierć królowała przez jednego, daleko więcej, którzy obfitość onej łaski i dar sprawiedliwości przyjmują, w żywocie królować będą przez tegoż jednego Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Przetoż tedy jako przez jednego upadek na wszystkich ludzi przyszła wina ku potępieniu; tak też przez jednego usprawiedliwienie na wszystkich ludzi przyszedł dar ku usprawiedliwieniu żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Bo jako przez nieposłuszeństwo jednego człowieka wiele się ich stało grzesznymi; tak przez posłuszeństwo jednego człowieka wiele się ich stało sprawiedliwymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'A zakon przytem nastąpił, aby obfitował grzech; lecz gdzie się grzech rozmnożył, tam łaska tem więcej obfitowała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'Aby jako grzech królował ku śmierci, tak też aby łaska królowała przez sprawiedliwość ku żywotowi wiecznemu przez Jezusa Chrystusa, Pana naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Cóż tedy rzeczemy? Zostaniemyż w grzechu, aby łaska obfitowała?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Nie daj tego Boże! albowiem którzyśmy umarli grzechowi, jakoż jeszcze w nim żyć będziemy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Azaż nie wiecie, iż którzykolwiek ochrzczeni jesteśmy w Chrystusa Jezusa, w śmierć jego ochrzczeni jesteśmy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Pogrzebieniśmy tedy z nim przez chrzest w śmierć, aby jako Chrystus wzbudzony jest z martwych przez chwałę ojcowską, tak żebyśmy i my w nowości żywota chodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Bo jeźliżeśmy z nim wszczepieni w podobieństwo śmierci jego, tedy też i w podobieństwo zmartwychwstania wszczepieni z nim będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'To wiedząc, że stary nasz człowiek pospołu jest z nim ukrzyżowany, aby ciało grzechu było zniszczone, żebyśmy już więcej nie służyli grzechowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Bo ktoć umarł, usprawiedliwiony jest od grzechu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Jeźliśmy tedy z Chrystusem umarli, wierzymy, iż też z nim żyć będziemy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Wiedząc, że Chrystus powstawszy z martwych, więcej nie umiera i śmierć mu więcej nie panuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Bo iż umarł, grzechowi raz umarł, a iż żyje, żyje Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Tak też i wy rozumiejcie, żeście wy umarłymi grzechowi, aleście żywymi Bogu w Chrystusie Jezusie, Panu naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Niechże tedy nie króluje grzech w śmiertelnem ciele waszem, żebyście mu posłuszni byli w pożądliwościach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Ani stawiajcie członków waszych orężem niesprawiedliwości grzechowi: ale stawiajcie siebie samych Bogu, jako z umarłych żywi, i członki wasze orężem sprawiedliwości Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Albowiem grzech panować nad wami nie będzie; bo jesteście nie pod zakonem, ale pod łaską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Cóż tedy? Będziemyż grzeszyli, żeśmy nie pod zakonem, ale pod łaską? Nie daj tego Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Azaż nie wiecie, że komu się stawiacie za sługi ku posłuszeństwu, tegoście sługami, komuście posłuszni; bądź grzechowi ku śmierci, bądź posłuszeństwu ku sprawiedliwości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Ale chwała Bogu, że bywszy sługami grzechu, usłuchaliście z serca sposobu onej nauki, którejście się poddali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'A będąc uwolnieni od grzechu, staliście się niewolnikami sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Po ludzku mówię dla mdłości ciała waszego. Albowiem jakoście stawiali członki wasze na służbę nieczystości i nieprawości ku czynieniu nieprawości: tak teraz stawiajcie członki wasze na służbę sprawiedliwości ku poświęceniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Bo pókiście byli sługami grzechu, byliście wolnymi od sprawiedliwości:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Jakiżeście tedy naonczas pożytek mieli onych rzeczy, za które się teraz wstydzicie? Bo koniec onych jest śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Lecz teraz, będąc uwolnieni od grzechu, a zniewoleni Bogu, macie pożytek swój ku poświęceniu, a koniec żywot wieczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Albowiem zapłata za grzech jest śmierć; ale dar z łaski Bożej jest żywot wieczny, w Chrystusie Jezusie, Panu naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Azaż nie wiecie, bracia! (bo powiadomym zakonu mówię), iż zakon panuje nad człowiekiem, póki żyje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Albowiem niewiasta, która jest za mężem, póki żyw mąż, obowiązana mu jest zakonem; a jeźliby mąż umarł, uwolniona jest od zakonu mężowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Przetoż tedy, póki mąż żyje, będzie zwana cudzołożnicą, jeźliby żoną inszego męża została; a jeźliby mąż jej umarł, wolna jest od zakonu onego, aby nie była cudzołożnicą, choćby się inszego męża żoną stała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'A tak, bracia moi! i wyście umartwieni zakonowi przez ciało Chrystusowe, abyście się stali inszego, to jest tego, który wzbudzony jest z martwych, abyśmy owoc przynosili Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Albowiem gdyśmy byli w ciele, namiętności grzechów, które się wzniecały przez zakon, mocy dokazywały w członkach naszych ku przynoszeniu owocu śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Lecz teraz staliśmy się wolni od zakonu, umarłszy temu, w którymeśmy byli zatrzymani, abyśmy Bogu służyli w nowości ducha, a nie w starości litery.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Cóż tedy rzeczemy? Iż zakon jest grzechem? Nie daj tego Boże! I owszemem grzechu nie poznał, tylko przez zakon; bo i o pożądliwości bym był nie wiedział, by był zakon nie rzekł: Nie będziesz pożądał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Lecz grzech wziąwszy przyczynę przez przykazanie, sprawił we mnie wszelką pożądliwość; albowiem bez zakonu grzech jest martwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'I jam żył niekiedy bez zakonu; lecz gdy przyszło przykazanie, grzech ożył, a jam umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'I znalazło się, że to przykazanie, które miało być ku żywotowi, jest mi ku śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Gdyż grzech, wziąwszy przyczynę przez przykazanie, zawiódł mię i przez nie zabił mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'A tak zakon jest święty i przykazanie święte, i sprawiedliwe, i dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'To tedy dobre stałoż mi się śmiercią? Nie daj tego Boże! I owszem grzech, aby się pokazał być grzechem, sprawił mi śmierć przez dobre, żeby się stał nader grzeszącym on grzech przez ono przykazanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Bo wiemy, iż zakon jest duchowny, alem ja cielesny, zaprzedany pod grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Albowiem tego, co czynię, nie pochwalam; bo nie, co chcę, to czynię, ale czego nienawidzę, to czynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'A jeźli czego nie chcę, to czynię, przyzwalam zakonowi, że dobry jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Już tedy teraz nie ja to czynię, ale grzech we mnie mieszkający;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Gdyż wiem, że nie mieszka we mnie (to jest w ciele mojem) dobre; albowiem chęć jest we mnie, ale wykonać to, co jest dobrego, nie znajduję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Bo nie czynię dobrego, które chcę; ale złe, którego nie chcę, to czynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'A jeźliż ja to czynię, czego nie chcę, już ja więcej nie czynię tego, ale grzech, który we mnie mieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Znajduję tedy ten zakon w sobie, gdy chcę dobre czynić, że się mnie złe trzyma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Albowiem kocham się w zakonie Bożym według wewnętrznego człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Lecz widzę inszy zakon w członkach moich, odporny zakonowi umysłu mego i który mię zniewala pod zakon grzechu, który jest w członkach moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Nędznyż ja człowiek! Któż mię wybawi z tego ciała śmierci?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Dziękuję Bogu przez Jezusa Chrystusa, Pana naszego. Przetoż tedy ja sam umysłem służę zakonowi Bożemu, lecz ciałem zakonowi grzechu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Przetoż teraz żadnego potępienia nie masz tym, który będąc w Chrystusie Jezusie nie według ciała chodzą, ale według Ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Albowiem zakon Ducha żywota, który jest w Chrystusie Jezusie, uwolnił mię od zakonu grzechu śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Bo co niemożnego było zakonowi, w czem on był słaby dla ciała, Bóg posławszy Syna swego w podobieństwie grzesznego ciała i dla grzechu, potępił grzech w ciele,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'Aby ona sprawiedliwość zakonu była wypełniona w nas, którzy nie według ciała chodzimy, ale według Ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Albowiem, którzy są według ciała, o tem myślą, co jest cielesnego; ale którzy są według Ducha, myślą o tem, co jest duchowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Gdyż zmysł ciała jest śmierć; ale zmysł ducha jest żywot i pokój,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Przeto iż zmysł ciała jest nieprzyjacielem Bogu; bo się zakonowi Bożemu nie poddaje, gdyż też i nie może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Przetoż którzy są w ciele, Bogu się podobać nie mogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Lecz wy nie jesteście w ciele, ale w duchu, gdyż Duch Boży mieszka w was: a jeźli kto Ducha Chrystusowego nie ma, ten nie jest jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Ale jeźli Chrystus w was jest, tedy ciało jest martwe dla grzechu, a duch jest żywy dla sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'A jeźli Duch tego, który Jezusa wzbudził z martwych, mieszka w was, ten który wzbudził Chrystusa z martwych, ożywi i śmiertelne ciała wasze przez Ducha swego, który w was mieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'A tak, bracia! dłużnikami jesteśmy nie ciału, abyśmy według ciała żyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Albowiem jeźlibyście według ciała żyli, pomrzecie; ale jeźlibyście Duchem sprawy ciała umartwili, żyć będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Bo którzykolwiek Duchem Bożym prowadzeni bywają, ci są synami Bożymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Gdyżeście nie wzięli ducha niewoli znowu ku bojaźni, aleście wzięli Ducha przysposobienia synowskiego, przez którego wołamy: Abba, to jest Ojcze!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Tenże duch poświadcza duchowi naszemu, iż jesteśmy dziećmi Bożymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'A jeźliż dziećmi, tedy i dziedzicami, dziedzicami wprawdzie Bożymi, a spółdziedzicami Chrystusowymi, jeźli tylko z nim cierpimy, abyśmy też z nim byli uwielbieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Albowiem, (bracia!) mam za to, iż utrapienia teraźniejszego czasu nie są godne onej przyszłej chwały, która się ma objawić w nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Bo troskliwe wyglądanie stworzenia oczekuje objawienia synów Bożych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Gdyż stworzenie marności jest poddane, nie dobrowolnie, ale dla tego, który je poddał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Pod nadzieją, że i samo stworzenie będzie uwolnione z niewoli skażenia na wolność chwały dziatek Bożych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Bo wiemy, iż wszystko stworzenie wespół wzdycha i wespół boleje aż dotąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'A nie tylko ono stworzenie, ale i my, którzy mamy pierwiastki Ducha, i my sami w sobie wzdychamy, oczekując przysposobienia synowskiego, odkupienia ciała naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Albowiem nadziejąśmy zbawieni. A nadzieja widoma nie jest nadzieją; bo co kto widzi, przecz się tego spodziewa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Ale czego nie widzimy, tego się spodziewamy i tego przez cierpliwość oczekujemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Także też i Duch dopomaga mdłościom naszym. Albowiem o co byśmy się modlić mieli, jako potrzeba, nie wiemy; ale tenże Duch przyczynia się za nami wzdychaniem niewymownem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'A ten, który się serc bada, wie, który jest zmysł Ducha, ponieważ według Boga przyczynia się za świętymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'A wiemy, iż tym, którzy miłują Boga, wszystkie rzeczy dopomagają ku dobremu, to jest tym, którzy według postanowienia Bożego powołani są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Albowiem, które on przejrzał, te też przenaznaczył, aby byli przypodobani obrazowi Syna jego, żeby on był pierworodnym między wieloma braćmi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'A które przenaznaczył, te też powołał; a które powołał, te też usprawiedliwił; a które usprawiedliwił, te też uwielbił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Cóż tedy rzeczemy na to? Jeźli Bóg za nami, któż przeciwko nam?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Który ani własnemu Synowi nie przepuścił, ale go za nas wszystkich wydał: jakoż by wszystkiego z nim nie darował nam?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Któż będzie skarżył na wybrane Boże? Bóg jest, który usprawiedliwia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Któż jest, co by je potępił? Chrystus jest, który umarł, owszem i zmartwychwstał, który też jest na prawicy Bożej, który się też przyczynia za nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Któż nas odłączy od miłości Chrystusowej? czyli utrapienie? czyli ucisk? czyli prześladowanie? czyli głód? czyli nagość? czyli niebezpieczeństwo? czyli miecz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Jako napisano: Dla ciebie cały dzień zabijani bywamy, poczytaniśmy jako owce na rzeź naznaczone;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Ale w tem wszystkiem przezwyciężamy przez tego, który nas umiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Albowiem pewienem tego, iż ani śmierć, ani żywot, ani Aniołowie, ani księstwa, ani mocarstwa, ani teraźniejsze ani przyszłe rzeczy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'Ani wysokość, ani głębokość, ani żadne insze stworzenie nie będzie nas mogło odłączyć od miłości Bożej, która jest w Jezusie Chrystusie, Panu naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Prawdę mówię w Chrystusie, a nie kłamię, w czem mi poświadcza sumienie moje przez Ducha Świętego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Że mam wielki smutek i nieustawający ból w sercu mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Albowiem żądałbym sam, abym się stał odłączonym od Chrystusa za braci moich, za pokrewnych moich według ciała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Którzy są Izraelczycy, których jest przysposobienie synowskie i chwała, i przymierza, i zakonu danie, i służba Boża, i obietnice;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Których są ojcowie i z których poszedł Chrystus ile według ciała, który jest nad wszystkimi Bóg błogosławiony na wieki. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Lecz nie można, żeby miało upaść słowo Boże; albowiem nie wszyscy, którzy są z Izraela, są Izraelem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Ani iż są nasieniem Abrahamowem, wszyscy są dziećmi; ale rzeczono: W Izaaku będzie tobie nazwane nasienie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'To jest, nie dzieci ciała są dziećmi Bożymi; ale dzieci obietnicy bywają w nasienie policzone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Albowiem obietnicy słowo to jest: O tym właśnie czasie przyjdę, a Sara będzie miała syna;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'A nie tylko to, ale i Rebeka, gdy z jednego ojca naszego Izaaka brzemienną została.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Gdy się jeszcze były dziatki nie narodziły, ani co dobrego albo złego uczyniły, aby się ostało postanowienie Boże według wybrania, nie z uczynków, ale z tego, który powołuje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Rzeczono jej, że większy będzie służył mniejszemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Jako napisano: Jakóbam umiłował, alem Ezawa miał w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Cóż tedy rzeczemy? Jestże niesprawiedliwość u Boga? Nie daj tego Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Albowiem do Mojżesza mówi: Zmiłuję się, nad kim się zmiłuję; a zlituję się, nad kim się zlituję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'A przetoż nie zależy na tym co chce, ani na tym, co bieży, ale na Bogu, który się zmiłowywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Albowiem mówi Pismo do Faraona: Na tom cię samo wzbudził, abym okazał moc moję na tobie, a iżby opowiadane było imię moje po wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'A tak nad kim chce, zmiłowywa się, a kogo chce, zatwardza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Ale mi rzeczesz: Przeczże się jeszcze uskarża? bo któż się sprzeciwił woli jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'I owszem, o człowiecze! któżeś ty jest, który spór wiedziesz z Bogiem? Izali lepianka rzecze lepiarzowi: Przeczżeś mię tak uczynił?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Izali nie ma mocy garncarz nad gliną, żeby z tejże gliny uczynił jedno naczynie ku uczciwości, a drugie ku zelżywości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'A jeźliż Bóg chcąc okazać gniew i znajomą uczynić możność swoję, znosił w wielkiej cierpliwości naczynia gniewu na zginienie zgotowane,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'A iżby znajome uczynił bogactwo chwały swojej nad naczyniem miłosierdzia, które zgotował ku chwale;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Których i powołał, to jest nas, nie tylko z Żydów, ale i z poganów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Jako też u Ozeasza mówi: Nazwię lud, który nie był moim, ludem moim, a onę, która nie była umiłowaną, nazwię umiłowaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'I stanie się, że na tem miejscu, gdzie im mawiano: Nie jesteście wy ludem moim, tam nazwani będą synami Boga żywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'A Izajasz woła nad Izraelem, mówiąc: Choćby liczba synów Izraelskich była jako piasek morski, ostatki zachowane będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Albowiem sprawę skończy i skróci w sprawiedliwości; sprawę zaiste skróconą uczyni Pan na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'I jako przedtem powiedział Izajasz: By nam był Pan zastępów nie zostawił nasienia, bylibyśmy się stali jako Sodoma i Gomorze bylibyśmy podobni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Cóż tedy rzeczemy? To, iż poganie, którzy nie szukali sprawiedliwości, dostąpili sprawiedliwości, a sprawiedliwości, która jest z wiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'A Izrael szukając zakonu sprawiedliwości, nie doszedł zakonu sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Dlaczegoż? Iż nie z wiary, ale jako z uczynków zakonu jej szukali; albowiem się obrazili o kamień obrażenia,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'Jako napisano: Oto kładę w Syonie kamień obrażenia i opokę otrącenia, a wszelki, który w niego wierzy, nie będzie pohańbiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Bracia! przychylna wola serca mego i modlitwa, którą czynię do Boga za Izraelem, jestci ku zbawieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Albowiem daję im świadectwo, iż gorliwość ku Bogu mają, ale nie według wiadomości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Bo nie znając sprawiedliwości Bożej, a chcąc własną sprawiedliwość wystawić, sprawiedliwości Bożej nie byli poddani.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Albowiem koniec zakonu jest Chrystus ku sprawiedliwości każdemu wierzącemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Gdyż Mojżesz pisze o sprawiedliwości, która jest z zakonu, iż ktobykolwiek te rzeczy czynił, przez nie żyć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Ale sprawiedliwość, która jest z wiary, tak mówi: Nie mów w sercu swem: Kto wstąpi na niebo? to jest Chrystusa na dół sprowadzić:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Albo kto zstąpi do przepaści? to jest Chrystusa od umarłych wyprowadzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Ale (Mojżesz) cóż mówi: Blisko ciebie jest słowo w ustach twoich i w sercu twojem. Toć jest słowo wiary, które opowiadamy:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Że jeźlibyś usty wyznał Pana Jezusa i uwierzyłbyś w sercu twojem, że go Bóg z martwych wzbudził, zbawiony będziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Albowiem sercem wierzono bywa ku sprawiedliwości, ale się usty wyznanie dzieje ku zbawieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Bo Pismo mówi: Wszelki, kto w niego wierzy, nie będzie pohańbiony;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Gdyż nie masz różności między Żydem i Grekiem; bo tenże Pan wszystkich, bogaty jest ku wszystkim, którzy go wzywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Każdy bowiem, kto by wzywał imienia Pańskiego, zbawiony będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Jakoż tedy wzywać będą tego, w którego nie uwierzyli? a jako uwierzą w tego, o którym nie słyszeli? a jako usłyszą bez kaznodziei?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Jakoż też będą kazać, jeźliby nie byli posłani? Jako napisano: O jako śliczne są nogi tych, którzy opowiadają pokój, tych, którzy opowiadają dobre rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Aleć nie wszyscy posłuszni byli Ewangielii; albowiem Izajasz mówi: Panie! któż uwierzył kazaniu naszemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Wiara tedy jest z słuchania, a słuchanie przez słowo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Ale mówię: Izali nie słyszeli? i owszem na wszystkę ziemię wyszedł głos ich i na kończyny okręgu ziemi słowa ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Ale mówię: Izali tego nie poznał Izrael? Pierwszy Mojżesz mówi: Ja was do zawiści pobudzę przez naród, który nie jest narodem, przez naród nierozumny rozdrażnię was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'A Izajasz śmiałości używając mówi: Jestem znaleziony od tych, którzy mnie nie szukali, i jestem objawiony tym, którzy się o mnie nie pytali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Ale przeciwko Izraelowi mówi: Cały dzień wyciągałem ręce moje do ludu upornego i sprzeciwiającego się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Mówię tedy: Izali Bóg odrzucił lud swój? Nie daj tego Boże! Albowiem i jam jest Izraelczyk z nasienia Abrahamowego, z pokolenia Benjaminowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Nie odrzuciłci Bóg ludu swego, który przejrzał. Azaż nie wiecie, co mówi Pismo o Elijaszu? jako się przyczynia do Boga przeciwko Izraelowi mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Panie! Proroki twoje pomordowali i ołtarze twoje zburzyli, a zostałem ja sam i szukają duszy mojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Ale cóż mu mówi Boska odpowiedź? Zostawiłem sobie siedm tysięcy mężów, którzy nie skłonili kolana Baalowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Tak tedy i teraźniejszego czasu ostatki podług wybrania z łaski zostały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'A ponieważ z łaski, tedyć już nie z uczynków, inaczej łaska już by nie była łaską; a jeźli z uczynków, jużci nie jest łaska; inaczej uczynek już by nie był uczynkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Cóż tedy? Czego Izrael szuka, tego nie dostąpił; ale wybrani dostąpili, a inni zatwardzeni są,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, '(Jako napisano: Dał im Bóg ducha twardego snu, oczy, aby nie widzieli i uszy, aby nie słyszeli), aż do dzisiejszego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'A Dawid mówi: Niechaj im będzie stół ich sidłem i ułowieniem i otrąceniem i odpłatą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Niech zaćmione będą oczy ich, aby nie widzieli, a grzbietu ich zawsze nachylaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Mówię tedy: Azaż się potknęli, aby padli? Nie daj tego Boże! Ale przez ich upadek doszło zbawienie pogan, aby je do zawiści przywiódł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'A ponieważ upadek ich jest bogactwem świata, a umniejszenie ich bogactwem pogan, jakoż daleko więcej ich zupełność?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Albowiem mówię wam poganom, ilem ja jest Apostołem pogan, usługiwanie moje zalecam,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Azażbym jako ku zawiści pobudził ciało moje i zbawiłbym niektóre z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Albowiem jeźlić odrzucenie ich jest pojednaniem świata, cóż będzie przyjęcie ich, tylko ożycie od umarłych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Ponieważ jeźli pierwiastki święte, tedyć i zaczynienie; a jeźli korzeń święty, tedyć i gałęzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'A jeźli niektóre z gałęzi odłamane są, a ty, któryś był płonną oliwą, jesteś wszczepiony zamiast nich i stałeś się uczestnikiem korzenia i tłustości oliwnego drzewa:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'Nie chlubże się przeciw gałęziom, bo jeźli się chlubisz, wiedzże, iż nie ty korzenia nosisz, ale korzeń ciebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Ale rzeczesz: Odłamane są gałęzie, abym ja był wszczepiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Dobrze; dla niedowiarstwa odłamane są, ale ty wiarą stoisz; nie bądźże hardej myśli, ale się bój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Albowiem jeźli Bóg przyrodzonym gałęziom nie przepuścił, wiedz, że i tobie nie przepuści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Obaczże tedy dobrotliwość i srogość Bożą; przeciwko tym wprawdzie, którzy upadli, srogość, ale przeciwko tobie dobrotliwość, jeźlibyś trwał w dobroci; inaczej i ty będziesz wycięty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Aleć i oni, jeźli nie będą trwali w niedowiarstwie, wszczepieni zaś będą, gdyż mocny jest Bóg one zasię wszczepić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Albowiem jeźliś ty jest wycięty z oliwy, z przyrodzenia płonnej, a przeciwko przyrodzeniu jesteś wszczepiony w dobrą oliwę, jakoż daleko więcej, którzy są według przyrodzenia, wszczepieni będą w swoję własną oliwę!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Bo nie chcę, abyście nie mieli wiedzieć, bracia! tej tajemnicy, (żebyście nie byli sami u siebie mądrymi), iż zatwardzenie z części przyszło na Izraela, póki by nie weszła zupełność pogan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'A tak wszystek Izrael będzie zbawiony, jako napisano: Przyjdzie z Syonu wybawiciel i odwróci niepobożności od Jakóba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'A toć będzie przymierze moje z nimi, gdy odejmę grzechy ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'A tak według Ewangielii nieprzyjaciółmi są dla was; lecz według wybrania są miłymi dla ojców.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Albowiem darów swoich i wezwania Bóg nie żałuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Bo jako i wy niekiedy nie wierzyliście Bogu, ale teraz dostąpiliście miłosierdzia dla ich niedowiarstwa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'Tak i oni teraz stali się nieposłusznymi, aby dla miłosierdzia wam okazanego i oni miłosierdzia dostąpili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Albowiem zamknął je Bóg wszystkie w niedowiarstwo, aby się nad wszystkimi zmiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'O głębokości bogactwa i mądrości, i znajomości Bożej! Jako są niewybadane sądy jego i niedoścignione drogi jego!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Bo któż poznał umysł Pański? albo kto był rajcą jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Albo kto mu co pierwej dał, a będzie mu zasię oddano?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Albowiem z niego i przez niego i w nim są wszystkie rzeczy; jemu niech będzie chwała na wieki. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Proszę was tedy, bracia! przez litości Boże, abyście stawiali ciała wasze ofiarą żywą, świętą, przyjemną Bogu, to jest rozumną służbę waszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'A nie przypodobywajcie się temu światu, ale się przemieńcie przez odnowienie umysłu waszego na to, abyście doświadczyli, która jest wola Boża dobra, przyjemna i doskonała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Albowiem powiadam przez łaskę, która mi jest dana, każdemu, co jest między wami, aby więcej o sobie nie rozumiał, niżeli potrzeba rozumieć; ale żeby o sobie rozumiał skromnie, tak jako komu Bóg udzielił miarę wiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Albowiem jako w jednem ciele wiele członków mamy, ale wszystkie członki nie jednoż dzieło mają:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Tak wiele nas jest jednem ciałem w Chrystusie, aleśmy z osobna jedni drugich członkami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Mając tedy różne dary według łaski, która nam jest dana; jeźli proroctwo, niech będzie według sznuru wiary;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Jeźli posługowanie, niech będzie w posługowaniu; jeźli kto naucza, niech trwa w nauczaniu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Jeźli kto napomina, w napominaniu; kto rozdaje, w szczerości; kto przełożony jest, w pilności; kto czyni miłosierdzie, niech czyni z ochotą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Miłość niech będzie nieobłudna; miejcie w obrzydliwości złe; imając się dobrego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Miłością braterską jedni ku drugim skłonni bądźcie, uczciwością jedni drugich uprzedzając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'W pracy nie leniwi, duchem pałający, Panu służący;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'W nadziei się weselący, w ucisku cierpliwi, w modlitwie ustawiczni;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Potrzebom świętych udzielający, gościnności naśladujący.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Dobrorzeczcie tym, którzy was prześladują; dobrorzeczcie, a nie przeklinajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Weselcie się z weselącymi, a płaczcie z płaczącymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Bądźcie między sobą jednomyślni, wysoko o sobie nie rozumiejąc, ale się do niskich nakłaniając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, '(Bracia!) nie bądźcie mądrymi sami u siebie; żadnemu złem za złe nie oddawajcie, obmyśliwając to, co jest uczciwego przed wszystkimi ludźmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Jeźli można, ile z was jest, ze wszystkimi ludźmi pokój miejcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Nie mścijcie się sami, najmilsi: ale dajcie miejsce gniewowi; albowiem napisano: Mnie pomsta, a Ja oddam, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Jeźli tedy łaknie nieprzyjaciel twój, nakarm go; jeźli pragnie, napój go: bo to czyniąc, węgle rozpalone zgarniesz na głowę jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Nie daj się zwyciężyć złemu, ale złe dobrem zwyciężaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Każda dusza niech będzie zwierzchnościom wyższym poddana: boć nie masz zwierzchności, tylko od Boga; a te, które są zwierzchności, od Boga są postanowione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'A tak, kto się zwierzchności sprzeciwia, Bożemu się postanowieniu sprzeciwia; a którzy się sprzeciwiają, sami sobie potępienie zjednają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Albowiem przełożoni nie są na postrach dobrym uczynkom, ale złym. A chcesz się nie bać zwierzchności, czyń, co jest dobrego, a będziesz miał pochwałę od niej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Bożym bowiem jest sługą tobie ku dobremu. Ale jeźli uczynisz, co jest złego, bój się; boć nie darmo miecz nosi, gdyż jest sługą Bożym, mszczącym się w gniewie nad czyniącym, co jest złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Przetoż trzeba być poddanym nie tylko dla gniewu, ale i dla sumienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Albowiem dla tego też podatki dajecie, gdyż są sługami Bożymi, którzy tego samego ustawicznie pilnują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Oddawajcież tedy każdemu, cobyście powinni: komu podatek, temu podatek, komu cło, temu cło, komu bojaźń, temu bojaźń; komu cześć, temu cześć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Nikomu nic winni nie bądźcie, tylko abyście się społecznie miłowali; bo kto miłuje bliźniego, zakon wypełnił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Gdyż to przykazanie: Nie będziesz cudzołożył, nie będziesz zabijał, nie będziesz kradł, nie będziesz fałszywie świadczył, nie będziesz pożądał, i jeźli które insze jest przykazanie, w tem słowie sumownie się zamyka, mianowicie: Będziesz miłował bliźniego twego, jako siebie samego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Miłość bliźniemu złości nie wyrządza; a tak wypełnieniem zakonu jest miłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'A to czyńcie, wiedząc czas, iż już przyszła godzina, abyśmy się ze snu ocucili; albowiem teraz bliższe nas jest zbawienie, aniżeli kiedyśmy uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Noc przeminęła, a dzień się przybliżył; odrzućmyż tedy uczynki ciemności, a obleczmy się w zbroję światłości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Chodźmy uczciwie jako we dnie, nie w biesiadach i w pijaństwach, nie we wszeteczeństwach i rozpustach, nie w poswarkach ani w zazdrości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Ale obleczcie się w Pana Jezusa Chrystusa, a nie czyńcie starania o ciele ku wykonywaniu pożądliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'A tego, który jest w wierze słaby, przyjmujcie, nie na sprzeczania około sporów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Boć jeden wierzy, iż może jeść wszystko, a drugi będąc słaby, jarzynę jada.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Ten, który je, niech lekce nie waży tego, który nie je; a który nie je, niech nie potępia tego, który je; albowiem go Bóg przyjął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Ktoś ty jest, co sądzisz cudzego sługę? Panu własnemu stoi, albo upada, a ostoi się; albowiem go Bóg może utwierdzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Bo jeden różność czyni między dniem a dniem, a drugi każdy dzień za równo sądzi; każdy niech będzie dobrze upewniony w zmyśle swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Kto przestrzega dnia, Panu przestrzega; a kto nie przestrzega dnia, Panu nie przestrzega; kto je, Panu je, bo dziękuje Bogu; a kto nie je, Panu nie je, a dziękuje Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Albowiem nikt z nas sobie nie żyje, i nikt sobie nie umiera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Bo choć żyjemy, Panu żyjemy; choć umieramy, Panu umieramy; przetoż choć i żyjemy, choć i umieramy, Pańscy jesteśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Gdyż na to Chrystus i umarł i powstał i ożył, aby i nad umarłymi i nad żywymi panował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Ale ty przeczże potępiasz brata twego? Albo też ty czemu lekceważysz brata twego, gdyż wszyscy staniemy przed stolicą Chrystusową?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Bo napisano: Jako żyję Ja, mówi Pan, iż mi się każde kolano ukłoni, i każdy język wysławiać będzie Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'A przeto każdy z nas sam za się odda rachunek Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'A tak już nie sądźmy jedni drugich; ale raczej to rozsądzajcie, abyście nie kładli obrażenia, ani dawali zgorszenia bratu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Wiem i upewnionym jest przez Pana Jezusa, iż nie masz nic przez się nieczystego, tylko temu, który mniema co być nieczystem, to temu nieczyste jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Lecz jeźli dla pokarmu brat twój bywa zasmucony, już nie postępujesz według miłości; nie zatracaj pokarmem twoim tego, za którego Chrystus umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Niechże tedy dobro wasze bluźnione nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Albowiem królestwo Boże nie jest pokarm ani napój, ale sprawiedliwość i pokój i radość w Duchu Świętym:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Bo kto w tych rzeczach służy Chrystusowi, miły jest Bogu, a przyjemny ludziom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Przetoż tedy naśladujmy tego, co należy do pokoju i do społecznego budowania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Dla pokarmu nie psuj sprawy Bożej. Wszystkoć wprawdzie jest czyste; ale złe jest człowiekowi, który je z obrażeniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Dobrać jest, nie jeść mięsa i nie pić wina, ani żadnej rzeczy, którą się brat twój obraża albo gorszy albo słabieje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Ty wiarę masz? miejże ją sam u siebie przed Bogiem. Błogosławiony, który samego siebie nie sądzi w tem, co ma za dobre.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Ale kto jest wątpliwy, jeźliby jadł, potępiony jest, iż nie je z wiary; albowiem cokolwiek nie jest z wiary, grzechem jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'A tak powinniśmy znosić, my, którzyśmy mocni, mdłości słabych, a nie podobać się samym sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Przetoż każdy z nas niech się bliźniemu podoba ku dobremu dla zbudowania;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Ponieważ i Chrystus nie podobał się samemu sobie, ale jako napisano: Urągania urągających tobie przypadły na mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Bo cokolwiek przedtem napisano, ku naszej nauce napisano, abyśmy przez cierpliwość i przez pociechę Pism nadzieję mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'A Bóg cierpliwości i pociechy niech wam da, abyście byli jednomyślni między sobą według Chrystusa Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'Abyście jednomyślnie jednemi usty wysławiali Boga, Ojca Pana naszego Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Przetoż przyjmujcie jedni drugich, jako i Chrystus przyjął nas do chwały Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Bo powiadam, iż Jezus Chrystus był sługą obrzezki dla prawdy Bożej, aby potwierdził obietnice ojcom uczynione,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'A poganie żeby za miłosierdzie chwalili Boga, jako napisano: Dlatego będę cię wysławiał między pogany i imieniowi twemu śpiewać będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'I zasię mówi: Weselcie się poganie z ludem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'I zasię: Chwalcie Pana wszyscy poganie, a wysławiajcie go wszyscy ludzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'I zasię Izajasz mówi: Będzie korzeń Jessego, a który powstanie, aby panował nad pogany, w nim poganie nadzieję pokładać będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'A Bóg nadziei niech was napełni wszelką radością i pokojem w wierze, abyście obfitowali w nadziei przez moc Ducha Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'A pewienem, bracia moi! i ja sam o was, że jesteście i wy sami pełni dobroci, napełnieni wszelką znajomością, i możecie jedni drugich napominać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'A pisałem do was, bracia! poniekąd śmielej, jakoby was napominając przez łaskę, która mi jest dana od Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'Na to, abym był sługą Jezusa Chrystusa między pogany, świętobliwie pracując w Ewangielii Bożej, aby ofiara pogan stała się przyjemna, poświęcona przez Ducha Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Mam się tedy czem chlubić w Chrystusie Jezusie, w rzeczach Bożych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Albowiem nie śmiałbym mówić tego, czego by nie sprawował Chrystus przez mię w przywodzeniu ku posłuszeństwu pogan, przez słowo i przez uczynek,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'Przez moc znamion i cudów, przez moc Ducha Bożego, tak iżem od Jeruzalemu i okolicznych krain aż do Iliryku napełnił Ewangieliją Chrystusową;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'A to tak usiłując kazać Ewangieliję, gdzie i mianowany nie był Chrystus, abym na cudzym fundamencie nie budował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Ale jako napisano: Którym nie powiadano o nim, oglądają; a którzy o nim nie słyszeli, zrozumieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Dlaczegom też często miewał przeszkody, żem do was przyjść nie mógł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Lecz teraz nie mam więcej miejsca w tych samych krainach, a mając chęć przyjść do was od wielu lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'Kiedykolwiek pójdę do Hiszpanii, przyjdę do was: bo się spodziewam, że tamtędy idąc ujrzę was, a że wy mię tam poprowadzicie, kiedy się pierwej z wami troszeczkę ucieszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'A teraz idę do Jeruzalemu, usługując świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Albowiem się upodobało Macedonii i Achai, nieco spólnie złożyć na ubogich świętych, którzy są w Jeruzalemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Owa podobało się im i są ich dłużnikami; bo ponieważ dóbr ich duchownych poganie się uczestnikami stali, powinni im też są cielesnemi usługiwać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Przetoż gdy to wykonam, a onym jako zapieczętowany ten pożytek oddam, pójdę przez was do Hiszpanii;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'A wiem, iż gdy przyjdę do was, z hojnem błogosławieństwem Ewangielii Chrystusowej przyjdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'A proszę was, bracia! przez Pana naszego Jezusa Chrystusa i przez miłość Ducha, abyście wespół ze mną pracowali w modlitwach za mię do Boga,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'Abym był wybawiony od tych, którzy są niewiernymi w ziemi Judzkiej, a iżby usługa moja, którą wykonywam przeciw Jeruzalemowi, przyjemna była świętym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Abym z radością przyszedł do was za wolą Bożą i z wami się wespół ucieszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'A Bóg pokoju niech będzie z wami wszystkimi. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'A zalecam wam Febę, siostrę naszę, która jest służebnicą zboru Kienchreeńskiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Abyście ją przyjęli w Panu, jako przystoi świętym, i stali przy niej, w którejkolwiek by was rzeczy potrzebowała; albowiem i ona wielom gospody użyczała, aż i mnie samemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Pozdrówcie Pryscyllę i Akwilę, pomocniki moje w Chrystusie Jezusie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, '(Którzy za duszę moję swojej własnej szyi nadstawiali; którym nie ja sam dziękuję, ale i wszystkie zbory pogańskie.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Także zbór, który jest w domu ich. Pozdrówcie Epeneta miłego mojego, który jest pierwiastkiem Achai do Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Pozdrówcie Maryję, która wiele pracowała dla nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Pozdrówcie Andronika i Junijasza, krewnych moich i spółwięźni moich, którzy znacznymi są między Apostołami, którzy i przede mną byli w Chrystusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Pozdrówcie Amplijasa, miłego mojego w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Pozdrówcie Urbana, pomocnika naszego w Chrystusie i Stachyna mnie miłego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Pozdrówcie Apellesa doświadczonego w Chrystusie. Pozdrówcie tych, którzy są z domu Arystobulowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Pozdrówcie Herodijona, pokrewnego mojego. Pozdrówcie tych, którzy są z domu Narcyssowego, tych, którzy są w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Pozdrówcie Tryfenę i Tryfosę, które pracują w Panu. Pozdrówcie Persydę miłą, która wiele pracowała w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Pozdrówcie Rufa, wybranego w Panu i matkę jego, i moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Pozdrówcie Asynkryta, Flegonta, Hermana, Patrobę, Hermena i braci, którzy są z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Pozdrówcie Filologa i Juliję, Nerego i siostrę jego, i Olimpa, i wszystkich świętych, którzy są z nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Pozdrówcie jedni drugich z pocałowaniem świętem. Pozdrawiają was zbory Chrystusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'A proszę was, bracia! abyście upatrywali tych, którzy czynią rozerwania i zgorszenia przeciwko tej nauce, którejście się wy nauczyli; i chrońcie się ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Albowiem takowi Panu naszemu Jezusowi Chrystusowi nie służą, ale własnemu brzuchowi swemu, a przez łagodną mowę i pochlebstwo serca prostych zwodzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Bo posłuszeństwo wasze wszystkich doszło. A przetoż raduję się z was; ale chcę, abyście byli mądrymi na dobre, a prostymi na złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'A Bóg pokoju zetrze szatana pod nogi wasze w rychle. Łaska Pana naszego Jezusa Chrystusa niech będzie z wami. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Pozdrawiają was Tymoteusz, pomocnik mój, i Lucyjusz, i Jazon, i Sosypater, pokrewni moi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Pozdrawiam was w Panu ja Tercyjusz, którym ten list pisał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Pozdrawia was Gajus, gospodarz mój i wszystkiego zboru. Pozdrawia was Erastus, szafarz miejski, i Kwartus brat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Łaska Pana naszego Jezusa Chrystusa niech będzie z wami wszystkimi. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'A temu, który was może utwierdzić według Ewangielii mojej i opowiadania Jezusa Chrystusa, według objawienia tajemnicy od czasów wiecznych zamilczanej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'Lecz teraz objawionej i przez Pisma prorockie według postanowienia wiecznego Boga ku posłuszeństwu wiary między wszystkimi narody oznajmionej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Temu, samemu mądremu Bogu niech będzie chwała przez Jezusa Chrystusa na wieki. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paweł, powołany Apostoł Jezusa Chrystusa przez wolę Bożą, i Sostenes brat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'Zborowi Bożemu, który jest w Koryncie, poświęconym w Chrystusie Jezusie, powołanym świętym, ze wszystkimi, którzy wzywają imienia Pana naszego Jezusa Chrystusa na wszelkiem miejscu, i ich, i naszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Łaska wam i pokój niech będzie od Boga, Ojca naszego, i od Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Dziękuję Bogu mojemu zawsze za was dla łaski Bożej, która wam jest dana w Chrystusie Jezusie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Iżeście we wszystkiem ubogaceni w nim we wszelkiej mowie i we wszelkiej znajomości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Jako świadectwo Chrystusowe utwierdzone jest w was,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'Tak iż wam na żadnym darze nie schodzi, którzy oczekujecie objawienia Pana naszego Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Który was też utwierdzi aż do końca, abyście byli bez nagany w dzień Pana naszego, Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Wiernyć jest Bóg, przez którego jesteście powołani ku społeczności Syna jego, Jezusa Chrystusa, Pana naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'A proszę was, bracia! przez imię Pana naszego, Jezusa Chrystusa, abyście toż mówili wszyscy, a iżby nie były między wami rozerwania, ale abyście byli spojeni jednakim umysłem i jednakiem zdaniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Albowiem oznajmiono mi o was, bracia moi! od domowników Chloi, iż poswarki są między wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'A to powiadam, iż każdy z was mówi: Jamci jest Pawłowy, a jam Apollosowy, a jam Kiefasowy, alem ja Chrystusowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Rozdzielonyż jest Chrystus? Azaż Paweł za was ukrzyżowany? Alboście w imię Pawłowe ochrzczeni?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Dziękuję Bogu, żem żadnego z was nie chrzcił, oprócz Kryspa i Gajusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'Aby kto nie rzekł, żem chrzcił w imię moje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Ochrzciłem też i dom Stefanowy; nadto nie wiem, jeźlim kogo drugiego ochrzcił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Boć mnie nie posłał Chrystus chrzcić, ale Ewangieliję kazać, wszakże nie w mądrości mowy, aby nie był wyniszczony krzyż Chrystusowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Albowiem mowa o krzyżu tym, którzy giną, jest głupstwem; ale nam, którzy bywamy zbawieni, jest mocą Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Bo napisano: Wniwecz obrócę mądrość mądrych, a rozum rozumnych odrzucę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Gdzież jest mądry? Gdzież jest uczony w Piśmie? Gdzież badacz wieku tego? Izali w głupstwo nie obrócił Bóg mądrości świata tego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Albowiem ponieważ w mądrości Bożej świat nie poznał Boga przez mądrość, upodobało się Bogu przez głupie kazanie zbawić wierzących,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Gdyż i Żydowie się cudów domagają, a Grekowie mądrości szukają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Ale my każemy Chrystusa ukrzyżowanego, Żydom wprawdzie zgorszenie, a Grekom głupstwo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Lecz samym powołanym i Żydom, i Grekom każemy Chrystusa, który jest mocą Bożą i mądrością Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Albowiem głupstwo Boże jest mędrsze niż ludzie; a mdłość Boża jest mocniejsza niż ludzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Widzicie zaiste powołanie wasze, bracia! iż niewiele mądrych według ciała, niewiele możnych, niewiele zacnego rodu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Ale co głupiego jest u świata tego, to wybrał Bóg, aby zawstydził mądrych, a co mdłego u świata, wybrał Bóg, aby zawstydził mocnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'A podłego rodu u świata i wzgardzone wybrał Bóg, owszem te rzeczy, których nie masz, aby te, które są, zniszczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Aby się nie chlubiło żadne ciało przed obliczem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Lecz z niego wy jesteście w Chrystusie Jezusie, który się nam stał mądrością od Boga i sprawiedliwością, i poświęceniem, i odkupieniem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Aby, jako napisano: Kto się chlubi, w Panu się chlubił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'A ja gdym przyszedł do was, bracia! nie przyszedłem z wyniosłością mowy albo mądrości, opowiadając wam świadectwo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Albowiem nie osądziłem za rzecz potrzebną, co inszego umieć między wami, tylko Jezusa Chrystusa, i to onego ukrzyżowanego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'I byłem ja u was w słabości i w bojaźni i w strachu wielkim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'A mowa moja i kazanie moje nie było w powabnych mądrości ludzkiej słowach, ale w okazaniu ducha i mocy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Aby się wiara wasza nie gruntowała na mądrości ludzkiej, ale na mocy Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'A mądrość mówimy między doskonałymi; ale mądrość nie tego świata, ani książąt tego świata, którzy giną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Ale mówimy mądrość Bożą w tajemnicy, która jest zakryta, którą Bóg przeznaczył przed wieki ku chwale naszej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Której żaden z książąt tego świata nie poznał; bo gdyby byli poznali, nigdy by Pana chwały nie ukrzyżowali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Ale opowiadamy, jako napisano: Czego oko nie widziało i ucho nie słyszało i na serce ludzkie nie wstąpiło, co nagotował Bóg tym, którzy go miłują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Ale nam to Bóg objawił przez Ducha swojego; albowiem duch wszystkiego się bada, i głębokości Bożych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Bo któż z ludzi wie, co jest w człowieku, tylko duch człowieczy, który w nim jest? Także też i tego, co jest w Bogu, nikt nie wie, tylko Duch Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Aleśmy my nie przyjęli ducha świata, lecz Ducha, który jest z Boga, abyśmy wiedzieli, które rzeczy nam są od Boga darowane;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'O których też mówimy, nie temi słowy, których ludzka mądrość naucza, ale których Duch Święty naucza, do duchownych rzeczy duchowne stosując.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Ale cielesny człowiek nie pojmuje tych rzeczy, które są Ducha Bożego; albowiem mu są głupstwem i nie może ich poznać, przeto iż duchownie bywają rozsądzone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Aleć duchowny rozsądza wszystko; lecz sam od nikogo nie bywa rozsądzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Albowiem któż poznał zmysł Pański? Któż go będzie uczył? Ale my zmysł Chrystusowy mamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'I ja, bracia! nie mogłem wam mówić jako duchownym, ale jako cielesnym i jako niemowlątkom w Chrystusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Napawałem was mlekiem, a nie karmiłem was pokarmem; boście jeszcze nie mogli znieść, owszem i teraz jeszcze nie możecie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Gdyż jeszcze cielesnymi jesteście. Bo ponieważ między wami jest zazdrość i swary, i rozterki, azażeście nie cieleśni i według człowieka nie chodzicie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Albowiem gdy kto mówi: Jam jest Pawłowy, a drugi: Jam Apollosowy, azaż cielesnymi nie jesteście?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Bo któż jest, Paweł? Kto Apollos? jedno słudzy, przez którycheście uwierzyli, a to jako każdemu Pan dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Jam szczepił, Apollos polewał, ale Bóg wzrost dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'A tak, ani ten, co szczepi, jest czem, ani ten, co polewa, ale Bóg, który wzrost daje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Lecz ten, który szczepi, i ten, który polewa, jedno są, a każdy swoję zapłatę weźmie według pracy swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Albowiem jesteśmy pomocnikami Bożymi, wy Bożą rolą, Bożym budynkiem jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Według łaski Bożej, która mi jest dana, jako mądry budownik założyłem grunt, a drugi na nim buduje: wszakże każdy niechaj baczy, jako na nim buduje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Albowiem gruntu innego nikt nie może założyć, oprócz tego, który jest założony, który jest Jezus Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'A jeźli kto na tym gruncie buduje złoto, srebro, kamienie drogie, drwa, siano, słomę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'Każdego robota jawna będzie; bo to dzień pokaże, gdyż przez ogień objawiona będzie, a każdego roboty, jaka jest, ogień doświadczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Jeźli czyja robota zostanie, którą na nim budował, zapłatę weźmie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Jeźli czyja robota zgore, ten szkodę podejmie; lecz on sam będzie zachowany, wszakże tak jako przez ogień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Azaż nie wiecie, iż kościołem Bożym jesteście, a Duch Boży mieszka w was?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'A jeźli kto gwałci kościół Boży, tego Bóg skazi, albowiem kościół Boży święty jest, którym wy jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Niechajże nikt samego siebie nie zwodzi; jeźli się kto sobie zda być mądrym między wami na tym świecie, niech się stanie głupim, aby się stał mądrym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Albowiem mądrość tego świata głupstwem jest u Boga; bo napisano: Który chwyta mądrych w chytrości ich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'I zasię: Pan zna myśli mądrych, iż są marnością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'A tak niech się nikt nie chlubi ludźmi; albowiem wszystkie rzeczy są wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Bądź Paweł, bądź Apollos, bądź Kiefas, bądź świat, bądź żywot, bądź śmierć, bądź przytomne, bądź przyszłe rzeczy, wszystkie są wasze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Aleście wy Chrystusowi, a Chrystus Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Tak niechaj o nas człowiek rozumie, jako o sługach Chrystusowych i o szafarzach tajemnic Bożych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'A tegoć więc szukają przy szafarzach, aby każdy znaleziony był wiernym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Aleć u mnie to jest najmniejsza, żebym był od was sądzony, albo od sądu ludzkiego; lecz i sam siebie nie sądzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Albowiem choć nic na się nie wiem, wszakże nie przeto jestem usprawiedliwiony; ale ten, który mnie sądzi, Pan jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'A tak nie sądźcie przed czasem, ażby Pan przyszedł, który też oświeci, co skrytego jest w ciemności i objawi rady serc; a tedy każdy będzie miał chwałę od Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'A te rzeczy, bracia! w podobieństwie obróciłem na się i na Apollosa dla was, abyście się nauczyli z nas nad to, co napisane, nie rozumieć, iżbyście się jeden dla drugiego nie nadymali przeciwko drugiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Albowiem któż cię różnym czyni? I cóż masz, czego byś nie wziął? A jeźliżeś wziął, przeczże się chlubisz, jakobyś nie wziął?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Jużeście nasyceni, jużeście ubogaceni, bez nas królujecie; a bodajeście królowali, abyśmy i my z wami pospołu królowali!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Bo mam za to, iż Bóg nas ostatnich Apostołów wystawił jakoby na śmierć skazanych; albowiem staliśmy się dziwowiskiem światu, Aniołom i ludziom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Myśmy głupi dla Chrystusa, aleście wy roztropni w Chrystusie; myśmy słabi, aleście wy mocni; wyście zacni, aleśmy my bezecni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Jeszcze aż do tej godziny i łakniemy, i pragniemy, i nadzy jesteśmy, i bywamy policzkowani, i tułamy się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'I pracujemy, robiąc własnemi rękami; gdy nas hańbią, dobrorzeczemy, gdy nas prześladują, znosimy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Gdy nam złorzeczą, modlimy się za nich: staliśmy się jako śmieci tego świata i jako omieciny u wszystkich, aż dotąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'To piszę, nie przeto, abym was zawstydził; ale jako dziatki moje miłe napominam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Bo choćbyście mieli dziesięć tysięcy pedagogów w Chrystusie, wszakże niewiele ojców macie; bom ja was w Jezusie Chrystusie przez Ewangieliję spłodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Proszę was tedy, bądźcie naśladowcami moimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Dlategom posłał do was Tymoteusza, który jest syn mój miły i wierny w Panu; ten wam przypomni drogi moje w Chrystusie, jako wszędy w każdym zborze nauczam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Ale tak się niektórzy nadęli, jakobym nie miał przyjść do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Lecz przyjdę rychło do was, jeźli Pan będzie chciał, i poznam nie mowę tych nadętych, ale moc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Albowiem nie w mowie zależy królestwo Boże, ale w mocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Cóż chcecie? z rózgąli mam przyjść do was, czyli z miłością i duchem cichości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Zapewne słychać, że jest między wami wszeteczeństwo, a takie wszeteczeństwo, jakie i między pogany nie bywa mianowane, aby kto miał mieć żonę ojca swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'A wyście się nadęli, a nie raczejście się smucili, aby był uprzątniony z pośrodku was ten, który ten uczynek popełnił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Przetoż ja, aczem odległy ciałem, lecz przytomny duchem, jużem jakobym był przytomny, osądził tego, który to tak popełnił,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Gdy się w imieniu Pana naszego Jezusa Chrystusa zgromadzicie, i z duchem moim, i z mocą Pana naszego, Jezusa Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Oddać szatanowi na zatracenie ciała, żeby duch był zachowany w on dzień Pana Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Nie dobrać to chluba wasza. Azaż nie wiecie, iż trochę kwasu wszystko zaczynienie zakwasza?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Wyczyścież tedy stary kwas, abyście byli nowem zaczynieniem, jako przaśnymi jesteście; albowiem Baranek nasz wielkanocny za nas ofiarowany jest, Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'A tak obchodźmy święto nie w starym kwasie, ani w kwasie złości i rozpusty, ale w przaśnikach szczerości i prawdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Pisałem wam w liście, abyście się nie mieszali z wszetecznikami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'Ale nie zgoła z wszetecznikami tego świata albo z łakomcami, albo z drapieżcami, albo z bałwochwalcami; bo inaczej musielibyście z tego świata wynijść.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Lecz teraz pisałem wam, abyście się nie mieszali; jeźliby kto, mieniąc się być bratem, był wszetecznikiem, albo łakomcą, albo bałwochwalcą, albo obmówcą, albo pijanicą, albo ździercą, żebyście z takowym i nie jadali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Albowiem cóż ja mam sądzić i obcych? Azaż wy tych, co są domowi, nie sądzicie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Ale tych, którzy są obcymi, Bóg sądzi. Przetoż uprzątnijcie tego złośnika z pośrodku samych siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Śmież kto z was, mając sprawę z drugim, sądzić się przed niesprawiedliwymi, a nie przed świętymi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Azaż nie wiecie, iż święci będą sądzili świat? A jeźli świat od was będzie sądzony, czyliście niegodni, abyście sądy mniejsze odprawiali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Azaż nie wiecie, iż Anioły sądzić będziemy? A cóż tych doczesnych rzeczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Przeto jeźlibyście mieli sądy o rzeczy doczesne, tych, którzy są najpodlejsi we zborze, na sąd wysadzajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Ku zawstydzeniu waszemu to mówię. Nie maszże między wami mądrego i jednego, który by mógł rozsądzić między braćmi swoimi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Ale się brat z bratem prawuje, i to przed niewiernymi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Już tedy zapewne jest między wami niedostatek, że się z sobą prawujecie. Czemuż raczej krzywdy nie cierpicie? Czemuż raczej szkody nie podejmujecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Owszem wy krzywdzicie i do szkody przywodzicie, a to braci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Azaż nie wiecie, iż niesprawiedliwi królestwa Bożego nie odziedziczą? Nie mylcie się: ani wszetecznicy, ani bałwochwalcy, ani cudzołożnicy, ani pieszczotliwi, ani samcołożnicy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Ani złodzieje, ani łakomcy, ani pijanicy, ani złorzeczący, ani ździercy królestwa Bożego nie odziedziczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'A takimiście niektórzy byli; aleście omyci, aleście poświęceni, aleście usprawiedliwieni w imieniu Pana Jezusa i przez Ducha Boga naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Wszystko mi wolno, ale nie wszystko pożyteczno; wszystko mi wolno, ale ja się nie dam zniewolić żadnej rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Pokarmy brzuchowi należą, a brzuch pokarmom; ale Bóg i brzuch i pokarmy skazi; lecz ciało nie należy wszeteczeństwu ale Panu, a Pan ciału.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Bo Bóg i Pana wzbudził, i nas wzbudzi mocą swoją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Azaż nie wiecie, iż ciała wasze są członkami Chrystusowymi? Wziąwszy tedy członki Chrystusowe, czyli je uczynię członkami wszetecznicy? Nie daj tego Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Azaż nie wiecie, iż ten, co się złącza z wszetecznicą, jednem ciałem z nią jest? albowiem mówi: Będą dwoje jednem ciałem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'A kto się złącza z Panem, jednym duchem jest z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Uciekajcie przed wszeteczeństwem. Wszelki grzech, który by człowiek popełnił, oprócz ciała jest; lecz kto wszeteczeństwo płodzi, przeciwko swemu własnemu ciału grzeszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Azaż nie wiecie, iż ciało wasze jest kościołem Ducha Świętego, który w was jest, którego macie od Boga? a nie jesteście sami swoi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Albowiemeście drogo kupieni. Wysławiajcież tedy Boga w ciele waszym i w duchu waszym, które są Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Lecz o tem, coście mi pisali: Dobrzećby człowiekowi, nie tykać się niewiasty;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Ale dla uwarowania się wszeteczeństwa niech każdy ma swoję własną żonę, a każda niech ma swego własnego męża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Mąż niech żonie powinną chęć oddaje, także też i żona mężowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Żona własnego ciała swego w mocy nie ma, ale mąż; także też i mąż własnego ciała swego w mocy nie ma, ale żona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Nie oszukiwajcie jeden drugiego; chybaby z spólnego zezwolenia do czasu, abyście się uwolnili do postu i do modlitwy; a zasię wespół się schodźcie, aby was szatan nie kusił dla waszej niepowściągliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Ale to mówię jako pozwalając, a nie jako rozkazując.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Albowiem chciałbym, aby wszyscy ludzie tak byli jako i ja; aleć każdy ma swój własny dar od Boga, jeden tak a drugi owak.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'A mówię nieżonatym i wdowom: Dobrze im jest, jeźliby tak zostali, jako i ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Ale jeźli się wstrzymać nie mogą, niechże w stan małżeński wstąpią; boć lepiej w stan małżeński wstąpić, niż upalenie cierpieć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Tym zasię, którzy są w stanie małżeńskim, rozkazuję nie ja, ale Pan, mówiąc: Żeby się żona od męża nie odłączała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Ale jeźliby się też odłączyła, niechajże zostaje bez męża, albo niech się z mężem pojedna, a mąż żony niechaj nie opuszcza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'A inszym zasię ja mówię, a nie Pan: Jeźli który brat ma żonę niewierną, a ta z nim przyzwala mieszkać, niechże jej nie opuszcza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'A jeźli która żona męża niewiernego ma, a on przyzwala z nią mieszkać, niechże go nie opuszcza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Albowiem poświęcony jest mąż niewierny przez żonę i żona niewierna poświęcona jest przez męża; bo inaczej dziatki wasze byłyby nieczystemi, lecz teraz świętemi są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'A jeźli ten, co jest niewierny, chce się odłączyć, niechże się odłączy; albowiem nie jest niewolnikiem brat albo siostra w takowych rzeczach; aleć ku pokojowi nas Bóg powołał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Albowiem co ty wiesz, żono! jeźli pozyskasz męża? Albo co ty wiesz, mężu! pozyskaszli żonę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Jednak jako każdemu udzielił Bóg, jako każdego powołał Pan, tak niech postępuje; a takci we wszystkich zborach stanowię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Obrzezanym kto powołany jest, niechaj nie wprowadza na się nieobrzezki; a w nieobrzezce kto jest powołany, niech się nie obrzezuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Obrzezka nic nie jest, także nieobrzezka nic nie jest; ale zachowywanie przykazań Bożych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Każdy w tem powołaniu, w którem powołany jest, niech zostaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Jesteś powołany niewolnikiem, nie dbajże na to; ale jeźli też możesz być wolny, raczej wolności używaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Albowiem kto w Panu powołany jest niewolnikiem, wolny jest w Panu; także też, kto jest powołany wolnym, niewolnikiem jest Chrystusowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Drogoście kupieni; nie bądźcie niewolnikami ludzkimi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Każdy tedy, jakim jest powołany bracia! takim niechaj zostaje przed Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'A o pannach rozkazania Pańskiego nie mam; wszakże radę daję, jako ten, któremu Pan z miłosierdzia swego dał, aby był wiernym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Mniemam tedy, że to jest rzecz dobra dla następującej potrzeby, że jest rzecz dobra człowiekowi tak być.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Przywiązałeś się do żony, nie szukajże rozwiązania; rozwiązanyś od żony, nie szukajże żony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'A jeźlibyś się ożenił, nie zgrzeszyłeś; jeźliby też panna szła za mąż, nie zgrzeszyła; wszakże utrapienie w ciele takowi mieć będą; lecz ja was szanuję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'A toć mówię, bracia! ponieważ czas potomny ukrócony jest, aby i ci, którzy żony mają, byli, jakoby ich nie mieli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'A którzy płaczą, jakoby nie płakali; a którzy się radują, jakoby się nie radowali; a którzy kupują, jakoby nie trzymali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'A którzy używają tego świata, jakoby źle nie używali; bo przemija kształt tego świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'A chcę, abyście wy byli bez kłopotu, bo kto nie ma żony, stara się o rzeczy Pańskie, jakoby się podobał Panu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Ale kto się ożenił, stara się o rzeczy tego świata, jakoby się podobał żonie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Jest różność między mężatką i panną; która nie szła za mąż, stara się o rzeczy Pańskie, aby była święta i ciałem i duchem; ale która szła za mąż, stara się o rzeczy tego świata, jakoby się podobała mężowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'A toć mówię ku dobru waszemu; nie abym sidło na was wrzucił, ale abyście słusznie i przystojnie stali przy Panu bez rozerwania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'A jeźli kto mniema, że nieprzystojnie sobie poczyna z panną swoją, gdyby z lat swoich wyszła, i do tego by jej przyszło, co chce, niechaj czyni, nie grzeszy; niechże idzie za mąż.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Ale kto statecznie postanowił w sercu swem, potrzeby tego nie mając, lecz ma w mocy własną swoję wolę i to usądził w sercu swem, aby zachował pannę swoję, dobrze czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'A tak ten, kto daje za mąż, dobrze czyni; ale który nie daje za mąż, lepiej czyni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Żona związana jest zakonem, póki żyje mąż jej; a jeźliby umarł mąż jej, wolna jest, aby szła, za kogo chce, tylko w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Ale szczęśliwszą jest, jeźliby tak została według rady mojej; a mniemam, że i ja mam Ducha Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'A o rzeczach, które bałwanom ofiarowane bywają, wiemy, iż wszyscy umiejętność mamy. Umiejętność nadyma, ale miłość buduje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'A jeźli kto mniema, żeby co umiał, jeszcze nic nie umie, tak jakoby miał umieć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Lecz jeźli kto miłuje Boga, ten jest wyuczony od niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'A przetoż o pokarmach, które bywają bałwanom ofiarowane, wiemy, iż bałwan na świecie nic nie jest, a iż nie masz żadnego inszego Boga, tylko jeden.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Bo choć są, którzy bogami nazywani bywają i na niebie, i na ziemi: (jakoż jest wiele bogów i wiele panów.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'Ale my mamy jednego Boga Ojca, z którego wszystko, a my w nim; i jednego Pana Jezusa Chrystusa, przez którego wszystko, a my przezeń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Ale nie we wszystkich jest ta umiejętność; albowiem niektórzy sumienie mając dla bałwana aż dotąd, jedzą jako rzecz bałwanom ofiarowaną, a sumienie ich będąc mdłe, pokalane bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Aleć nas pokarm nie zaleca Bogu; bo choćbyśmy jedli, nic nam nie przybywa; a choćbyśmy i nie jedli, nic nam nie ubywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Jednak baczcie, aby snać ta wolność wasza nie była mdłym ku zgorszeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Albowiem jeźliby kto ujrzał cię, który masz umiejętność, w bałwochwalni siedzącego, azaż sumienie onego, który jest mdły, nie będzie pobudzone ku jedzeniu rzeczy bałwanom ofiarowanych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'I zginie dla onej twojej umiejętności brat mdły, za którego Chrystus umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'A grzesząc tak przeciwko braciom i mdłe ich sumienie obrażając, grzeszycie przeciwko Chrystusowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Przeto, jeźli pokarm gorszy brata mego, nie będę jadł mięsa na wieki, abym brata mego nie zgorszył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Izalim nie jest Apostołem? Izalim nie jest wolnym? Izalim Jezusa Chrystusa, Pana naszego nie widział? Izali wy nie jesteście pracą moją w Panu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Choćbym innym nie był Apostołem, alem wam jest; albowiem pieczęcią apostolstwa mego wy jesteście w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Tać jest obrona moja przeciwko tym, którzy mię sądzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Izali nie mamy wolności jeść i pić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Izali nie mamy wolności wodzić z sobą siostry żony, jako i drudzy Apostołowie i bracia Pańscy, i Kiefas?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Izali ja tylko i Barnabasz nie mamy wolności, abyśmy nie pracowali?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Któż kiedy służy żołnierkę swoim kosztem? Któż sadzi winnicę, a owocu jej nie pożywa? Albo któż trzodę pasie, a mleka trzody nie pożywa?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Izali to obyczajem ludzkim mówię? Izali i zakon tegoż nie mówi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Albowiem w zakonie Mojżeszowym napisano: Nie zawiążesz gęby wołowi młócącemu; izali się Bóg o woły stara?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Czyli zgoła dla nas to mówi? Albowiem dla nas to napisano; gdyż w nadziei ma orać ten, co orze, a kto młóci w nadziei, nadziei swojej ma być uczestnikiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Ponieważeśmy my wam duchowne dobra siali, wielkaż to, gdybyśmy wasze cielesne żęli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Jeźliż insi tej wolności nad wami używają, czemuż nie raczej my? A wszakżeśmy tej wolności nie używali, ale wszystko znaszamy, abyśmy jakiego wstrętu Ewangielii Chrystusowej nie uczynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Azaż nie wiecie, iż ci, którzy około rzeczy świętych pracują, z świętych rzeczy jadają? a którzy ołtarza pilnują, spólną cząstkę z ołtarzem mają?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Tak też Pan postanowił tym, którzy Ewangieliję opowiadają, aby z Ewangielii żyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Alem ja nic z tych rzeczy nie używał. I nie pisałem tego, aby się tak przy mnie działo; bo mnie daleko lepiej umrzeć, niżby kto przechwalanie moje miał próżnem uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Bo jeźli Ewangieliję opowiadam, nie mam się czem chlubić, gdyż ta powinność na mnie leży; a biada mnie, jeźlibym Ewangielii nie opowiadał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Albowiem jeźli to dobrowolnie czynię, mam zapłatę; jeźli poniewolnie, szafarstwa mi powierzono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Jakąż tedy mam zapłatę? Abym Ewangieliję opowiadając, bez nakładu wystawił Ewangieliję Chrystusową, na to, żebym źle nie używał wolności mojej przy Ewangielii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Albowiem będąc wolnym od wszystkich, samegom siebie uczynił niewolnikiem wszystkim, abym ich więcej pozyskał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'I stałem się Żydom jako Żyd, abym Żydów pozyskał; a tym, którzy są pod zakonem, jakobym był pod zakonem, abym tych, którzy są pod zakonem, pozyskał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Tym, którzy są bez zakonu, jakobym bez zakonu, (nie będąc bez zakonu Bogu, ale będąc pod zakonem Chrystusowi), abym pozyskał tych, którzy są bez zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Stałem się mdłym jako mdły, abym mdłych pozyskał. Wszystkim stałem się wszystko, abym przecię niektórych zbawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'A to czynię dla Ewangielii, abym się jej stał uczestnikiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Azaż nie wiecie, iż ci, którzy w zawód bieżą, wszyscyć więc bieżą, lecz jeden zakład bierze? Także bieżcie, abyście otrzymali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'A każdy, który się potyka, we wszystkiem się powściąga, onić wprawdzie, aby wzięli koronę skazitelną, ale my nieskazitelną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Ja tedy tak bieżę, nie jako na niepewne; tak szermuję, nie jako wiatr bijąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Ale karzę ciało moje i w niewolę podbijam, abym snać inszym każąc, sam nie był odrzucony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'A nie chcę, abyście nie mieli wiedzieć bracia! iż ojcowie nasi wszyscy pod obłokiem byli i wszyscy przez morze przeszli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'I wszyscy w Mojżesza ochrzczeni są w obłoku i w morzu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'I wszyscy tenże pokarm duchowny jedli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'I wszyscy tenże napój duchowny pili; albowiem pili z opoki duchownej, która za nimi szła; a tą opoką był Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Lecz większej części z nich nie upodobał sobie Bóg; albowiem polegli na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'A te rzeczy stały się nam za wzór na to, abyśmy złych rzeczy nie pożądali, jako i oni pożądali');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Nie bądźcież tedy bałwochwalcami jako niektórzy z nich, tak jako napisano: Siadł lud, aby jadł i pił, i wstali grać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Ani się dopuszczajmy wszeteczeństwa, jako się niektórzy z nich wszeteczeństwa dopuszczali i padło ich jednego dnia dwadzieścia i trzy tysiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Ani kuśmy Chrystusa, jako niektórzy z nich kusili i od wężów poginęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Ani szemrzyjcie, jako niektórzy z nich szemrali, i poginęli od tego, który wytraca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'A te wszystkie rzeczy przydały się im za wzór, a napisane są dla napomnienia naszego, na których koniec świata przyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'A tak kto mniema, że stoi, niechże patrzy, aby nie upadł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Pokuszenie się was nie jęło, tylko ludzkie; ale wiernyć jest Bóg, który nie dopuści, abyście byli kuszeni nad możność waszę, ale uczyni z pokuszeniem i wyjście, abyście znosić mogli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Przetoż, najmilsi moi! uciekajcie przed bałwochwalstwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Jako mądrym mówię; rozsądźcie wy, co mówię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Kielich błogosławienia, który błogosławimy, izali nie jest społecznością krwi Chrystusowej? Chleb, który łamiemy, izali nie jest społecznością ciała Chrystusowego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Albowiem jednym chlebem, jednym ciałem wiele nas jest; bo wszyscy chleba jednego jesteśmy uczestnikami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Spojrzyjcie na Izraela, który jest według ciała; izaż ci, którzy jedzą ofiary, nie są uczestnikami ołtarza?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Cóż tedy mówię? Żeby bałwan miał być czem, a iżby to, co bywa bałwanom ofiarowane, miało czem być?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Owszem powiadam, iż to, co poganie ofiarują, dyjabłom ofiarują a nie Bogu; a nie chciałbym, abyście byli uczestnikami dyjabłów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Nie możecie pić kielicha Pańskiego i kielicha dyjabelskiego; nie możecie być uczestnikami stołu Pańskiego i stołu dyjabelskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'I mamyż drażnić Pana? Izaliśmy mocniejsi niżeli on?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Wszystko mi wolno, ale nie wszystko pożyteczne; wszystko mi wolno, ale nie wszystko buduje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Nikt niechaj nie szuka tego, co jest jego, ale każdy, co jest bliźniego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Cokolwiek w jatkach sprzedawają, jedzcie, nic nie pytając dla sumienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Albowiem Pańska jest ziemia i napełnienie jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'A jeźliby was kto zaprosił z niewiernych, a chcecie iść, wszystko, co przed was położą, jedzcie, nic nie pytając dla sumienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Ale jeźliby wam kto rzekł: To jest bałwanom ofiarowane, nie jedzcie dla onego, który to oznajmił i dla sumienia; albowiem Pańska jest ziemia i napełnienie jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'A powiadam dla sumienia, nie twego, ale onego drugiego; bo przeczże wolność moja ma być osądzona od cudzego sumienia?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'A ponieważ ja z dziękowaniem pożywam, czemuż o to mam być bluźniony, za co ja dziękuję?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Przetoż lub jecie lub pijecie, lub cokolwiek czynicie, wszystko ku chwale Bożej czyńcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Nie bądźcie obrażeniem i Żydom, i Grekom, i zborowi Bożemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Jako i ja we wszystkiem się wszystkim podobam, nie szukając w tem swego pożytku, ale wielu ich, aby byli zbawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Bądźcie naśladowcami moimi, jakom i ja Chrystusowy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'A chwalę was, bracia! iż pamiętacie wszystkie moje nauki, a jakom wam podał, podania trzymacie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'A chcę, abyście wiedzieli, iż każdego męża głową jest Chrystus, a głową niewiasty mąż, a głową Chrystusową Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Każdy mąż, gdy się modli albo prorokuje z przykrytą głową, szpeci głowę swoję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'I każda niewiasta, gdy się modli albo prorokuje, nie nakrywszy głowy swojej, szpeci głowę swoję; boć to jedno, a toż samo jest, jakoby ogolona była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Albowiem jeźli się nie nakrywa niewiasta, niechże się też strzyże; a jeźli szpetna rzecz jest niewieście, strzyc się albo golić, niechże się nakrywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Albowiem mąż nie ma nakrywać głowy, gdyż jest wyobrażeniem i chwałą Bożą; ale niewiasta jest chwałą mężową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Bo mąż nie jest z niewiasty, ale niewiasta z męża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Albowiem mąż nie jest stworzony dla niewiasty, ale niewiasta dla męża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'A przetoż niewiasta powinna mieć władzę na głowie dla Aniołów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'A wszakże mąż nie jest bez niewiasty, ani niewiasta nie jest bez męża w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Albowiem jako niewiasta z męża jest, tak też mąż przez niewiastę; jednak wszystkie rzeczy są z Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Sami u siebie rozsądźcie, przystoili niewieście bez nakrycia modlić się Bogu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Azaż was i samo przyrodzenie nie uczy, iż mężowi, gdyby włosy zapuszczał, jest mu ku zelżywości?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Ale niewiasta, jeźli zapuszcza włosy, jest jej ku poczciwości, przeto iż jej włosy dane są za przykrycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'A jeźliby się kto zdał być swarliwym, my takiego obyczaju nie mamy, ani zbory Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'A to opowiadając nie chwalę, że się nie ku lepszemu, ale ku gorszemu schodzicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Albowiem najprzód, gdy się wy schodzicie we zborze, słyszę, iż rozerwania bywają między wami, i poniekąd wierzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Bo muszą być kacerstwa między wami, aby ci, którzy są doświadczeni, byli jawnymi między wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Gdy się wy tedy wespół schodzicie, nie jest to używać wieczerzy Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Albowiem każdy wieczerzę swoję pierwej zjada i jeden łaknie, a drugi jest pijany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Azaż domów nie macie do jedzenia i do picia? Albo zborem Bożym gardzicie i zawstydzacie tych, którzy nie mają? Cóż wam rzekę? Pochwalęż was? W tem nie chwalę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Albowiem jam wziął od Pana, com też wam podał, iż Pan Jezus tej nocy, której był wydan, wziął chleb,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'A podziękowawszy, złamał i rzekł: Bierzcie, jedzcie; to jest ciało moje, które za was bywa łamane; to czyńcie na pamiątkę moję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Także i kielich, gdy było po wieczerzy mówiąc: Ten kielich jest nowy testament we krwi mojej; to czyńcie, ilekroć pić będziecie, na pamiątkę moję');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Albowiem ilekroć byście jedli ten chleb i ten kielich byście pili, śmierć Pańską opowiadajcie, ażby przyszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'A tak, kto by jadł ten chleb, albo pił ten kielich Pański niegodnie, będzie winien ciała i krwi Pańskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Niechże tedy człowiek samego siebie doświadczy, a tak niech je z chleba tego i z kielicha tego niechaj pije.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Albowiem kto je i pije niegodnie, sąd sobie samemu je i pije, nie rozsądzając ciała Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Dlatego między wami wiele jest słabych i chorych, i niemało ich zasnęło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Bo gdybyśmy się sami rozsądzali, nie bylibyśmy sądzeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Lecz gdy sądzeni bywamy, od Pana bywamy ćwiczeni, abyśmy z światem nie byli potępieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Ale tak, bracia moi! gdy się schodzicie ku jedzeniu, oczekiwajcie jedni drugich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'A jeźli kto łaknie, niechże je w domu, abyście się na sąd nie schodzili. A inne rzeczy, gdy przyjdę, postanowię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'A o duchownych darach, bracia! nie chcę, abyście wiedzieć nie mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Wiecie, iż gdyście poganami byli, do bałwanów niemych, jako was wodzono, daliście się prowadzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Przetoż oznajmuję wam, iż nikt przez Ducha Bożego mówiąc, nie rzecze Jezusa być przeklęstwem; i nikt nie może nazwać Jezusa Panem, tylko przez Ducha Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'A różneć są dary, ale tenże Duch.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'I różne są posługi, ale tenże Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'I różne są sprawy, ale tenże Bóg, który sprawuje wszystko we wszystkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'A każdemu bywa dane objawienie Ducha ku pożytkowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Albowiem jednemu przez Ducha bywa dana mowa mądrości, a drugiemu mowa umiejętności przez tegoż Ducha;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'A drugiemu wiara w tymże Duchu, a drugiemu dar uzdrawiania w tymże Duchu, a drugiemu czynienie cudów, a drugiemu proroctwo, a drugiemu rozeznanie duchów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'A drugiemu rozmaite języki, a drugiemu wykładanie języków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'A to wszystko sprawuje jeden a tenże Duch, udzielając z osobna każdemu, jako chce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Albowiem jako ciało jedno jest, a członków ma wiele, ale wszystkie członki ciała jednego, choć ich wiele jest, są jednym ciałem: tak i Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Albowiem przez jednego Ducha my wszyscy w jedno ciało jesteśmy ochrzczeni, bądź Żydowie, bądź Grekowie, bądź niewolnicy, bądź wolni, a wszyscy napojeni jesteśmy w jednego Ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Albowiem ciało nie jest jednym członkiem, ale wieloma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Jeźliby rzekła noga: Ponieważem nie jest ręką, nie jestem z ciała; izali dlatego nie jest z ciała?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'A jeźliby rzekło ucho: Ponieważem nie jest okiem, nie jestem z ciała; izali dlatego nie jest z ciała?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Jeźliż wszystko ciało jest okiem, gdzież słuch? a jeźliż wszystko słuchem, gdzież powonienie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Ale teraz Bóg ułożył członki, każdy z nich z osobna w ciele, jako chciał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'A jeźliby wszystkie były jednym członkiem, gdzieżby było ciało?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Ale teraz, acz jest wiele członków, lecz jedno jest ciało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Nie może tedy rzec oko ręce: Nie potrzebuję ciebie, albo zaś głowa nogom: Nie potrzebuję was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'I owszem daleko więcej członki, które się zdadzą być najmdlejsze w ciele, potrzebne są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'A które mamy za najniepoczciwsze w ciele, tym większą poczciwość wyrządzamy, a niepoczciwe członki nasze obfitszą poczciwość mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Bo poczciwe członki nasze tego nie potrzebują; lecz Bóg tak umiarkował ciało, dawszy członkowi, któremu czci nie dostaje, obfitszą poczciwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Aby nie było rozerwania w ciele, ale iżby jedne członki o drugich jednakież staranie miały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'A przetoż jeźliże jeden członek cierpi, cierpią z nim wszystkie członki; a jeźli bywa uczczony jeden członek, radują się z nim wszystkie członki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Lecz wy jesteście ciałem Chrystusowym i członkami, każdy z osobna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'A niektórych Bóg postanowił we zborze, najprzód Apostołów, potem proroków, po trzecie nauczycieli, potem cudotwórców, potem dary uzdrawiania, pomocników, rządców, rozmaitość języków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Izali wszyscy są Apostołami? Izali wszyscy prorokami? Izali wszyscy nauczycielami? Izali wszyscy cudotwórcami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Izali wszyscy mają dary uzdrawiania? Izali wszyscy językami mówią? Izali wszyscy tłumaczą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Starajcie się usilnie o lepsze dary; a ja wam jeszcze zacniejszą drogę ukażę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Choćbym mówił językami ludzkimi i anielskimi, a miłości bym nie miał, stałem się jako miedź brząkająca, albo cymbał brzmiący.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'I choćbym miał proroctwo i wiedziałbym wszystkie tajemnice, i wszelką umiejętność, i choćbym miał wszystkę wiarę, tak żebym góry przenosił, a miłości bym nie miał, nicem nie jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'I choćbym wynałożył na żywność ubogich wszystkę majętność moję, i choćbym wydał ciało moje, abym był spalony, a miłości bym nie miał, nic mi to nie pomoże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Miłość jest długo cierpliwa, dobrotliwa jest; miłość nie zajrzy, miłość nie jest rozpustna, nie nadyma się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Nie czyni nic nieprzystojnego, nie szuka swoich rzeczy, nie jest porywcza do gniewu, nie myśli złego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Nie raduje się z niesprawiedliwości, ale się raduje z prawdy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Wszystko okrywa, wszystkiemu wierzy, wszystkiego się spodziewa, wszystko cierpi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Miłość nigdy nie ustaje; bo choć są proroctwa, te zniszczeją; choć języki, te ustaną; choć umiejętność, wniwecz się obróci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Albowiem po części znamy i po części prorokujemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Ale gdy przyjdzie to, co jest doskonałego, tedy to, co jest po części, zniszczeje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Pókim był dziecięciem, mówiłem jako dziecię, rozumiałem jako dziecię, rozmyślałem jako dziecię; lecz gdym się stał mężem, zaniechałem rzeczy dziecinnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Albowiem teraz widzimy przez zwierciadło i niby w zagadce; ale na on czas twarzą w twarz; teraz poznaję po części, ale na on czas poznam, jakom i poznany jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'A teraz zostaje wiara, nadzieja, miłość, te trzy rzeczy; lecz z nich największa jest miłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Naśladujcie miłości, starajcie się usilnie o dary duchowne; lecz najwięcej, abyście prorokowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Albowiem kto mówi językiem obcym, nie ludziom mówi, ale Bogu; bo żaden nie słucha, lecz on duchem mówi tajemnice.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Ale kto prorokuje, mówi ludziom zbudowanie i napominanie, i pociechę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Kto językiem obcym mówi, samego siebie buduje; ale kto prorokuje, ten zbór buduje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'A chciałbym, abyście wy wszyscy językami mówili, ale abyście raczej prorokowali; albowiem większy jest ten, co prorokuje, niż ten, co językami obcymi mówi, chyba żeby tłumaczył, aby zbór brał zbudowanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Teraz tedy, bracia! gdybym przyszedł do was, językami obcymi mówiąc, cóż wam pomogę, jeźlibym wam nie mówił albo przez objawienie, albo przez umiejętność, albo przez proroctwo, albo przez naukę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Wszak i rzeczy nieżywe, które dźwięk wydawają jako piszczałka albo cytra, jeźliby różnego dźwięku nie wydawały, jakoż poznane będzie, co na piszczałce, albo co na cytrze grają?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Albowiem jeźliby trąba niepewny głos dała, któż się do boju gotować będzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Także i wy, jeźlibyście językiem nie wydali mowy dobrze zrozumiałej, jakoż będzie zrozumiałe, co się mówi? albowiem będziecie tylko na wiatr mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Tak wiele, jako słyszymy, jest różnych głosów na świecie, a nic nie jest bez głosu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Jeźlibym tedy nie znał mocy głosu, będę temu, który mówi, cudzoziemcem; a ten, co mówi, będzie mi także cudzoziemcem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Także i wy, ponieważ się usilnie staracie o dary duchowne, szukajcież tego, abyście obfitowali ku zbudowaniu zboru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Dlatego kto mówi obcym językiem, niech się modli, aby mógł tłumaczyć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Bo jeźlibym się modlił obcym językiem, modlić się będzie mój duch; ale rozum mój jest bez pożytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Cóż tedy jest? Będę się modlił duchem, będę się też modlił i wyrozumieniem; będę śpiewał duchem, będę też śpiewał i wyrozumieniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Bo jeźlibyś błogosławił duchem, jakoż ten, który jest z pocztu prostaków, na twoje dziękowanie rzecze Amen, ponieważ nie wie, co mówisz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Bo choć ty wprawdzie dobrze dziękujesz, ale się drugi nie buduje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Dziękuję Bogu mojemu, iż więcej, niż wy wszyscy, językami mówię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'A wszakże we zborze wolę pięć słów zrozumiale przemówić, abym i drugich nauczył, niżeli dziesięć tysięcy słów językiem obcym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Bracia! nie bądźcie dziećmi wyrozumieniem, ale bądźcie dziećmi złością, a wyrozumieniem dorosłymi bądźcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'W zakonie napisano: Iż obcemi językami i obcemi wargami mówić będę ludowi temu; a przecię mnie i tak nie usłuchają, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Przetoż języki są za cud, nie tym, którzy wierzą, ale niewiernym; a proroctwo nie niewiernym, ale wierzącym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Jeźliby się tedy wszystek zbór na jedno miejsce zeszedł, a wszyscy by językami obcemi mówili, a weszliby tam prostacy albo niewierni, izali nie rzeką, że szalejecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Ale jeźliby wszyscy prorokowali, a wszedłby który niewierny albo prostak, od wszystkich przekonany i od wszystkich sądzony bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'A tak skrytości serca tego bywają objawione, a on upadłszy na oblicze, pokłonili się Bogu, wyznawając, że Bóg jest prawdziwie w was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Cóż tedy jest, bracia? Gdy się schodzicie, każdy z was ma psalm, ma naukę, ma język, ma objawienie, ma tłumaczenie; wszystko to niech się dzieje ku zbudowaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Jeźli kto językiem mówi, niech to będzie po dwóch albo najwięcej po trzech, i to na przemiany, a jeden niech tłumaczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'A jeźliby tłumacza nie było niechże we zborze milczy ten, który obcym językiem mówi, a niech mówi sobie i Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Ale prorocy niech mówią dwaj albo trzej, a drudzy niech rozsądzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Jeźliby też inszemu siedzącemu co było objawione, on pierwszy niechaj milczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Bo możecie wszyscy jeden po drugim prorokować, aby się wszyscy uczyli i wszyscy pocieszeni byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'I duchy proroków są poddane prorokom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Albowiem Bóg nie jest powodem nieporządku, ale pokoju, jako i we wszystkich zborach świętych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Niewiasty wasze niech milczą we zborach; albowiem nie pozwolono im, aby mówiły, ale aby poddanemi były, jako i zakon mówi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'A jeźli się czego nauczyć chcą, niechże w domu mężów swoich pytają, ponieważ sromota niewiastom we zborze mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Izali od was słowo Boże wyszło? Izali tylko do was samych przyszło?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Izali kto zda się być prorokiem albo duchownym, niech uzna, iż te rzeczy, które wam piszę, są Pańskiem rozkazaniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'A jeźli kto nie wie, niechajże nie wie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'A tak, bracia! starajcie się usilnie o to, abyście prorokowali, a językami obcemi mówić nie zabraniajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Wszystko się niech dzieje przystojnie i porządnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'A oznajmuję wam, bracia! Ewangieliję, którąm wam opowiedział, którąście też przyjęli i w której stoicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Przez którą też zbawienia dostępujecie, jeźli pamiętacie, jakim sposobem opowiedziałem wam, chyba jeźliście próżno uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Albowiem naprzód podałem wam, com też wziął, iż Chrystus umarł za grzechy nasze według Pism;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'A iż był pogrzebiony, a iż zmartwychwstał dnia trzeciego według Pism.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'A iż widziany jest od Kiefasa, potem od onych dwunastu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Potem widziany jest więcej niż od pięciuset braci na raz, z których wiele ich zostaje aż dotąd, a niektórzy też zasnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Potem jest widziany od Jakóba, potem od wszystkich Apostołów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'A na ostatek po wszystkich ukazał się i mnie, jako poronionemu płodowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Bom ja jest najmniejszy z Apostołów, którym nie jest godzien, abym był zwany Apostołem, przeto żem prześladował zbór Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Lecz łaską Bożą jestem tem, czemem jest, a łaska jego przeciwko mnie daremna nie była; alem obficiej niż oni wszyscy pracował, wszakże nie ja, ale łaska Boża, która jest ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Przetoż i ja, i oni tak każemy, i takeście uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'A ponieważ się o Chrystusie każe, iż z martwych wzbudzony jest, jakoż mówią niektórzy między wami, iż zmartwychwstania nie masz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Bo jeźlić zmartwychwstania nie masz, tedyć i Chrystus nie jest wzbudzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'A jeźlić Chrystus nie jest wzbudzony, tedyć daremne kazanie nasze, daremna też wiara wasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'I bylibyśmy też znalezieni fałszywymi świadkami Bożymi, iżeśmy świadczyli o Bogu, że Chrystusa wzbudził, którego nie wzbudził, jeźliże umarli nie bywają wzbudzeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Albowiem jeźliż umarli nie bywają wzbudzeni, i Chrystus nie jest wzbudzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'A jeźli Chrystus nie jest wzbudzony, daremna jest wiara wasza i jeszczeście w grzechach waszych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Zatem i ci poginęli, którzy zasnęli w Chrystusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Bo jeźli tylko w tym żywocie w Chrystusie nadzieję mamy, nad wszystkich ludzi jesteśmy najnędzniejszymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Lecz teraz Chrystus z martwych wzbudzony jest i stał się pierwiastkiem tych, którzy zasnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Bo ponieważ przez człowieka śmierć, przez człowieka też powstanie umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Albowiem jako w Adamie wszyscy umierają, tak i w Chrystusie wszyscy ożywieni będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Ale każdy w swoim rzędzie, Chrystus jako pierwiastek, a potem ci, co są Chrystusowi w przyjście jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'A potem będzie koniec, gdy odda królestwo Bogu i Ojcu, gdy zniszczy wszelkie przełożeństwo i wszelką zwierzchność, i moc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Bo on musi królować, póki by nie położył wszystkich nieprzyjaciół pod nogi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'A ostatni nieprzyjaciel, który będzie zniszczony, jest śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Bo wszystkie rzeczy poddał pod nogi jego. A gdy mówi, że mu wszystkie rzeczy poddane są, jawna jest, iż oprócz tego, który mu poddał wszystkie rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'A gdy mu wszystkie rzeczy poddane będą, tedyć też i sam Syn będzie poddany temu, który mu poddał wszystkie rzeczy, aby był Bóg wszystkim we wszystkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Bo inaczej cóż uczynią ci, którzy się chrzczą nad umarłymi, jeźliż zgoła umarli nie bywają wzbudzeni? przeczże się chrzczą nad umarłymi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Przecz i my niebezpieczeństwa podejmujemy każdej godziny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Na każdy dzień umieram przez chwałę naszę, którą mam w Chrystusie Jezusie, Panu naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Jeźliżem się obyczajem ludzkim z bestyjami w Efezie potykał, cóż mam za pożytek, jeźli umarli nie bywają wzbudzeni? Jedzmy i pijmy; boć jutro pomrzemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Nie błądźcież; złe rozmowy psują dobre obyczaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Ocućcież się ku sprawiedliwości, a nie grzeszcie; albowiem niektórzy nie mają znajomości Bożej; ku zawstydzeniu waszemu mówię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Ale rzecze kto: Jakoż wzbudzeni bywają umarli i w jakim ciele wychodzą?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'O głupi! To, co ty siejesz, nie bywać ożywione, jeźliby nie umarło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'I co siejesz, nie siejesz ciała, które ma potem wyrość, ale gołe ziarno, jako się trafi, albo pszeniczne, albo jakiekolwiek inne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Ale Bóg daje mu ciało jako chce, a każdemu nasieniu jego własne ciało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Nie każde ciało jest jednakiem ciałem; ale inszeć jest ciało ludzkie, a insze ciało bydlęce, insze rybie, a insze ptasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'I są ciała niebieskie i ciała ziemskie; lecz insza jest chwała ciał niebieskich, a insza ludzkich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Insza chwała słońca, a insza chwała księżyca, i insza chwała gwiazd; albowiem gwiazda od gwiazdy różna jest w jasności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Takci będzie i powstanie umarłych. Bywa wsiane ziarno w skazitelności, a będzie wzbudzone w nieskazitelności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Bywa wsiane w niesławie, a będzie wzbudzone w sławie; bywa wsiane w słabości, a będzie wzbudzone w mocy; bywa wsiane ciało cielesne, a będzie wzbudzone ciało duchowne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Jest ciało cielesne, jest też ciało duchowne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Takci też napisane: Stał się pierwszy człowiek Adam w duszę żywą, ale pośledni Adam w ducha ożywiającego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Wszakże nie jest pierwsze duchowne, ale cielesne, potem duchowne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Pierwszy człowiek z ziemi ziemski; wtóry człowiek sam Pan z nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Jaki jest ten ziemski, tacy też i ziemscy; a jaki jest niebieski, tacy też będą niebiescy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'A jakośmy nosili wyobrażenie ziemskiego, tak też będziemy nosili wyobrażenie niebieskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'To jednak powiadam, bracia! iż ciało i krew królestwa Bożego odziedziczyć nie mogą; ani skazitelność nie odziedziczy nieskazitelności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Oto ja tajemnicę wam powiadam; nie wszyscyć zaśniemy, ale wszyscy przemienieni będziemy, bardzo prędko w okamgnieniu, na trąbę ostateczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'Albowiem zatrąbi, a umarli wzbudzeni będą nieskazitelni, a my będziemy przemienieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Boć musi to, co jest skazitelnego, przyoblec nieskazitelność, i co jest śmiertelnego, przyoblec nieśmiertelność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'A gdy to, co jest skazitelnego, przyoblecze nieskazitelność, i to, co jest śmiertelnego, przyoblecze nieśmiertelność, tedy się wypełni ono słowo, które napisane: Połkniona jest śmierć w zwycięstwie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Gdzież jest, o śmierci! bodziec twój? Gdzież jest, piekło! zwycięstwo twoje?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Lecz bodziec śmierci jest grzech, a moc grzechu jest zakon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Ale niech będą Bogu dzięki, który nam dał zwycięstwo przez Pana naszego Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'A tak, bracia moi mili! bądźcie mocni, nieporuszeni, obfitujący w uczynku Pańskim zawsze, wiedząc, iż praca wasza nie jest nadaremna w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'A około składania na świętych, jakom postanowił we zborach Galickich, tak też i wy czyńcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Każdego pierwszego dnia w tygodniu każdy z was niech odkłada u siebie, zbierając według tego, jako mu się powodzi, aby nie dopiero, gdy przyjdę, składania czynione były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'A gdy przyjdę, którychkolwiek uchwalicie przez listy, tych poślę, aby odnieśli dobrodziejstwo wasze do Jeruzalemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'A jeźliby słuszna rzecz była, żebym i ja szedł, wespół ze mną pójdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'A przyjdę do was, gdy przejdę Macedoniję; (bo pójdę przez Macedoniję).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'A podobno zamieszkam u was albo i przezimuję, abyście wy mię odprowadzili, kędykolwiek pójdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Albowiem nie chcę was teraz widzieć, mijając; ale spodziewam się, iż pomieszkam z wami czas niejaki, będzieli Pan chciał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'A zostanę w Efezie aż do Świątek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Albowiem drzwi mi są otworzone wielkie i mocne, i mam wiele przeciwników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Jeźliby tedy przyszedł Tymoteusz, patrzcie, aby bez bojaźni był między wami, bo dzieło Pańskie sprawuje, jako i ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Przetoż niechaj go nikt nie lekceważy; ale odprowadźcie go w pokoju, aby przyszedł do mnie; bo go czekam z braćmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'A o bracie Apollosie wiedzcie, żem go bardzo prosił, aby szedł do was z braćmi; ale zgoła nie miał woli, aby teraz szedł; przyjdzie jednak, gdy czas po temu mieć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Czujcież, stójcie w wierze, mężnie sobie poczynajcie, zmacniajcie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Wszystkie rzeczy wasze niech się dzieją w miłości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'A proszę was, bracia! wiedzcie, iż dom Stefanowy jest pierwiastkiem Achai, a iż sami siebie oddali na posługiwanie świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Abyście i wy poddani byli takowym, i każdemu pomagającemu i pracującemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'A cieszę się z przyjścia Stefana i Fortunata, i Achaika; bo ci niedostatek wasz napełnili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Ochłodzili bowiem ducha mego i waszego; znajcież tedy takowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Pozdrawiają was zbory, które są w Azyi. Pozdrawiają was wielce w Panu Akwilas i Pryscylla, ze zborem, który jest w domu ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Pozdrawiają was bracia wszyscy. Pozdrówcie jedni drugich w świętem pocałowaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Pozdrowienie ręką moją Pawłową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Jeźliże kto nie miłuje Pana Jezusa Chrystusa, niech będzie przeklęstwem, które zowią Maran ata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Łaska Pana Jezusa Chrystusa niech będzie z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Miłość moja niech będzie z wami wszystkimi w Chrystusie Jezusie. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paweł, Apostoł Jezusa Chrystusa przez wolę Bożą, i Tymoteusz brat, zborowi Bożemu, który jest w Koryncie, ze wszystkimi świętymi, którzy są we wszystkiej Achai.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Łaska niech będzie wam i pokój od Boga, Ojca naszego, i Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Błogosławiony niech będzie Bóg i Ojciec Pana naszego, Jezusa Chrystusa, Ojciec miłosierdzia a Bóg wszelkiej pociechy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Który nas cieszy w każdym ucisku naszym, abyśmy i my cieszyć mogli i tych, którzy są w jakimkolwiek ucisku, tąż pociechą, którą my sami pocieszeni bywamy od Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Gdyż jako w nas obfitują utrapienia Chrystusowe, tak przez Chrystusa obfituje i pociecha nasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Bo choć bywamy uciśnieni, dla waszej to pociechy i zbawienia, które się sprawuje przez znoszenie tegoż utrapienia, które i my cierpimy; choć też pocieszeni bywamy, i to dla waszej pociechy i zbawienia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'A nadzieja nasza mocna jest o was, ponieważ wiemy, iż jakoście uczestnikami utrapienia, tak i pociechy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Albowiem nie chcemy, abyście nie mieli wiedzieć, bracia! o ucisku naszym, który nas spotkał w Azyi, iżeśmy nazbyt byli obciążeni i nad możność, tak iżeśmy byli poczęli wątpić i o żywocie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Owszem i sami w sobie mieliśmy wyrok śmierci, abyśmy nie ufali sami w sobie, ale w Bogu, który wzbudza umarłych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Który z tak wielkiej śmierci wyrwał nas i jeszcze wyrywa, w którym nadzieję mamy, iż i napotem wyrwie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Zwłaszcza gdy się też i wy pomożecie modlić za nami, aby za ten dar, który przez wiele osób nam jest pokazany, były też od wielu osób dzięki czynione za nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Albowiem toć jest chluba nasza, świadectwo sumienia naszego, żeśmy w prostocie i w szczerości Bożej, nie w cielesnej mądrości, ale w łasce Bożej na świecie obcowali, a najwięcej między wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Albowiem nic inszego wam nie piszemy, tylko to, co czytacie, albo też poznawacie, a spodziewam się, iż też aż do końca poznacie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Jakoście też nas poznali po części, żeśmy chlubą waszą, jako i wy naszą w dzień Pana Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'I z tąć ufnością chciałem był iść do was najpierwej, abyście wtóre dobrodziejstwo odebrali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'I przez was iść do Macedonii, i zasię z Macedonii przyjść do was, i od was być odprowadzony do Judzkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'O tem tedy myśląc, izalim co lekkomyślnie uczynił? albo to, o czem myślę, izali według ciała myślę, aby było u mnie: Tak tak i Nie nie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Aleć wierny jest Bóg, iż mowa nasza do was nie była: Tak i Nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Albowiem Syn Boży, Jezus Chrystus, który między wami przez nas jest opowiadany, to jest, przez mię i przez Sylwana, i przez Tymoteusza, nie był: Tak i Nie; ale Tak w nim było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Bo ile jest obietnic Bożych, w nim są Tak i w nim są Amen, ku chwale Bożej przez nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Ale ten, który nas utwierdza z wami w Chrystusie i który nas pomazał, Bóg jest;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Który też zapieczętował nas i dał zadatek Ducha w serca nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Aleć ja Boga przyzywam na świadectwo na duszę moję, iż szanując was, dotądem nie przyszedł do Koryntu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Nie iżbyśmy panowali nad wiarą waszą, ale iż jesteśmy pomocnikami wesela waszego; bo wiarą stoicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'A postanowiłem to u siebie, abym znowu nie przyszedł z zasmuceniem do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Bo jeźlibym ja was zasmucił, i któż jest, co by mię rozweselił, tylko ten, który jest przez mię zasmucony?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'A tomci wam napisał, abym przyszedłszy, nie miał smutku z tych, z których miałbym się weselić; pewien będąc o was wszystkich, że radość moję wszyscy za swoję macie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Albowiem z wielkiego ucisku i utrapienia serca, i z wielą łez pisałem wam, nie żebyście mieli być zasmuceni, ale żebyście miłość poznali, którą nader obficie mam przeciwko wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Jeźli tedy kto zasmucił, nie mnieć zasmucił, ale poniekąd (abym go nie obciążył), was wszystkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Dosyćci ma taki na zgromieniu tem, które się stało od wielu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'Tak iż przeciwnym obyczajem, inaczej byście mu odpuścić mieli i onego pocieszyć, by snać zbytni smutek takiego nie pożarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Przetoż proszę was, abyście miłość przeciwko niemu utwierdzili,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Albowiem i dlategom był napisał, abym doświadczenia waszego doznał, jeźliże we wszystkiem posłuszni jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'A komu wy co odpuszczacie, temu i ja; gdyż i ja, jeźlim co odpuścił temu, komum odpuścił, uczyniłem to dla was przed oblicznością Chrystusową, aby was szatan nie podszedł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Albowiem zamysły jego nie są nam tajne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'A gdym przyszedł do Troady dla opowiadania Ewangielii Chrystusowej, a drzwi mi były otworzone w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Nie miałem ulżenia w duchu moim dlatego, żem nie znalazł Tytusa, brata mego; ale rozstawszy się z nimi, poszedłem do Macedonii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Lecz chwała Bogu, który nam zawsze zwycięstwo daje w Chrystusie i wonność znajomości swojej objawia przez nas na każdem miejscu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Bośmy dobrą wonnością Chrystusową Bogu w tych, którzy zbawieni bywają i w tych, którzy giną;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Tymci wonnością śmierci na śmierć, ale onym wonnością żywota ku żywotowi; lecz do tego, któż jest sposobny?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Bo nie jesteśmy jako wiele ich, którzy fałszują słowo Boże; ale jako z szczerości, ale jako z Boga, przed oblicznością Bożą o Chrystusie mówimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Poczynamyż zasię zalecać samych siebie? czyli potrzebujemy, jako niektórzy, listów zalecających do was albo też listów zalecających od was?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Listem naszym wy jesteście, napisanym na sercach naszych, który znają i czytają wszyscy ludzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Gdyż to jawna jest, żeście listem Chrystusowym przez usługę naszę zgotowanym, napisanym nie inkaustem, ale Duchem Boga żywego, nie na tablicach kamiennych, ale na tablicach serc mięsnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'A takieć ufanie mamy przez Chrystusa ku Bogu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Nie iżbyśmy byli sposobni, co myśleć sami z siebie, jako sami z siebie, ale sposobność nasza z Boga jest;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'Który nas też uczynił sposobnymi sługami nowego testamentu, nie litery, ale Ducha; albowiem litera zabija, ale Duch ożywia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Bo jeźlić posługiwanie śmierci literami wyrażone na tablicach kamiennych było chwalebne, tak iż synowie Izraelscy nie mogli śmiele patrzeć na oblicze Mojżeszowe dla chwały oblicza jego, która miała być skażona:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Jakoż daleko więcej usługiwanie Ducha nie ma być chwalebne?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Bo jeźlić usługiwanie potępienia było chwalebne, daleko więcej usługiwanie sprawiedliwości obfituje w chwale.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Albowiem i to, co chwałę miało, nie miało chwały w tej części, co się tknie onej przewyższającej chwały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Bo jeźlić to, co niszczeje, było chwalebne, daleko więcej to, co zostaje, jest chwalebne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Przetoż mając taką nadzieję, wielkiej bezpieczności w mowie używamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'A nie jesteśmy jako Mojżesz, który kładł zasłonę na oblicze swoje, aby synowie Izraelscy śmiele nie patrzyli na koniec onego, co zniszczeć miało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Ale zatwardzone są zmysły ich; albowiem aż do dzisiejszego dnia taż zasłona w czytaniu starego testamentu zostaje nie odkryta, która przez Chrystusa skażenie bierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Przetoż aż do dnia dzisiejszego, gdy Mojżesz czytany bywa, zasłona jest na sercu ich położona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Lecz gdyby się do Pana obrócili, odjęta będzie ona zasłona,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Aleć Pan jest tym Duchem; a gdzie jest ten Duch Pański, tam i wolność.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Lecz my wszyscy, którzy odkrytem obliczem na chwałę Pańską, jako w zwierciadle patrzymy, w toż wyobrażenie przemienieni bywamy z chwały w chwałę, jako od Ducha Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Dlatego mając to usługiwanie, tak jakośmy miłosierdzie otrzymali, nie słabiejemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Aleśmy się odrzekli skrytej sromoty, nie obchodząc się chytrze, ani fałszując słowa Bożego; ale objawieniem prawdy zalecając samych siebie u każdego sumienia ludzkiego przed obliczem Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Jeźli tedy zakryta jest Ewangielija nasza, zakryta jest przed tymi, którzy giną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'W których bóg świata tego oślepił zmysły, to jest w niewiernych, aby im nie świeciła światłość Ewangielii chwały Chrystusowej, który jest wyobrażeniem Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Albowiem nie samych siebie opowiadamy, ale Chrystusa Jezusa, że jest Panem, a samych siebie sługami waszymi dla Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Ponieważ Bóg, który rzekł, aby się z ciemności światłość rozświeciła, ten się rozświecił w sercach naszych ku rozświeceniu (w nas) znajomości chwały Bożej w obliczu Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'A mamy ten skarb w naczyniu glinianem, aby dostojność tej mocy była z Boga, a nie z nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Gdy zewsząd uciśnieni bywamy, ale nie bywamy potłoczeni; powątpiewamy, ale nie zwątpimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Prześladowanie cierpimy, ale nie bywamy opuszczeni; bywamy porzuceni, ale nie giniemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'Zawsze umartwienie Pana Jezusowe na ciele nosimy, aby i żywot Jezusowy na ciele naszem był objawiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Zawsze bowiem my, którzy żyjemy, bywamy wydawani na śmierć dla Jezusa, aby też żywot Jezusowy był objawiony w śmiertelnem ciele naszem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Dlatego śmierć mocy swojej w nas dokazuje, ale w was żywot.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Mając tedy tegoż ducha wiary, tak jako napisane: Uwierzyłem, przetom też mówił; i my wierzymy, przeto też mówimy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Wiedząc, iż ten, który wzbudził Pana Jezusa, i nas wzbudzi przez Jezusa, i postawi z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Boć to wszystko dzieje się dla was, aby łaska ona obfitująca przez dziękowanie wielu ich rozmnożyła się ku chwale Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Dlatego nie słabiejmy, ale choć się też nasz zewnętrzny człowiek kazi, wszakże on wewnętrzny się odnawia ode dnia do dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Albowiem ten króciuchny i lekki ucisk nasz nader zacnej chwały wieczną wagę nam sprawuje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Gdy nie patrzymy na rzeczy widzialne, ale na niewidzialne; albowiem rzeczy widzialne są doczesne, ale niewidzialne są wieczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Wiemy bowiem, że jeźli tego naszego ziemskiego mieszkania namiot zburzony będzie, budowanie mamy od Boga, dom nie rękoma urobiony, wieczny w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Albowiem w tym namiocie wzdychamy, domem naszym, który jest z nieba, żądając być przyobleczeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'Jeźliż tylko przyobleczonymi a nie nagimi znalezieni będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Bo którzyśmy w tym namiocie, wzdychamy, będąc obciążeni, ponieważ nie żądamy być zewleczeni, ale przyobleczeni, aby pożarta była śmiertelność od żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'A ten, który nas ku temuż właśnie przygotował, jestci Bóg, który nam też dał zadatek Ducha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Przetoż mając zawsze ufność i wiedząc, że póki mieszkamy w tem ciele, pielgrzymujemy od Pana:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '(Bo przez wiarę chodzimy, a nie przez widzenie).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Lecz ufamy i wolimy raczej wynijść z ciała, a iść na mieszkanie do Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Przetoż też usiłujemy, bądź w ciele mieszkamy, bądź z ciała wychodzimy, onemu się podobać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Albowiem musimy się wszyscy pokazać przed sądową stolicą Chrystusową, aby każdy odniósł, co czynił w ciele, według tego, co czynił, lub dobre, lub złe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Przetoż wiedząc o tym strachu Pańskim, ludzi do wiary namawiamy, a Bogu jawnymi jesteśmy; i mam nadzieję, iż w sumieniach waszych jawnymi jesteśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Albowiem nie samych siebie wam znowu zalecamy, ale wam dajemy przyczynę, abyście się chlubili nami i żebyście mieli co mówić przeciwko tym, którzy się chlubią z powierzchownych rzeczy, a nie z serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Bo choć od rozumu odchodzimy, Bogu odchodzimy, choć przy rozumie jesteśmy, wam jesteśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Albowiem miłość Chrystusowa przyciska nas, jako tych, którzyśmy to osądzili, iż ponieważ jeden za wszystkich umarł, tedy wszyscy byli umarłymi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'A że za wszystkich umarł, aby ci, którzy żyją, już więcej sobie nie żyli, ale temu, który za nich umarł i jest wzbudzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Dlatego my od tego czasu nikogo według ciała nie znamy, a chociaśmy też znali Chrystusa według ciała, lecz już teraz więcej nie znamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'A tak jeźli kto jest w Chrystusie, nowem jest stworzeniem; stare rzeczy przeminęły, oto się wszystkie nowemi stały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'A to wszystko z Boga jest, który nas z samym sobą pojednał przez Jezusa Chrystusa i dał nam usługiwanie tego pojednania,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Ponieważ Bóg był w Chrystusie, świat z samym sobą jednając, nie przyczytując im upadków ich, i położył w nas to słowo pojednania:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Przetoż na miejscu Chrystusowem poselstwo sprawujemy, jakoby was Bóg upominał przez nas, prosimy na miejscu Chrystusowem, jednajcie się z Bogiem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Albowiem on tego, który nie znał grzechu, za nas grzechem uczynił, abyśmy się my stali sprawiedliwością Bożą w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Przetoż pomagając mu, napominamy was, abyście nadaremno łaski Bożej nie przyjmowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, '(Bo mówi Bóg: Czasu przyjemnego wysłuchałem cię, a w dzień zbawienia poratowałem cię; oto teraz dzień przyjemny, oto teraz dzień zbawienia.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Żadnego w niczem nie dawając zgorszenia, aby nie było zganione usługiwanie nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Ale we wszystkiem zalecając samych siebie, jako słudzy Boży, w wielkiej cierpliwości, w uciskach, w niedostatkach, w utrapieniach,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'W razach, w więzieniach, w potłukaniu, w pracach, w niedosypianiu, w postach,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'W czystości, w umiejętności, w nieskwapliwości, w dobrotliwości, w Duchu Świętym, w miłości nieobłudnej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'W mowie prawdy, w mocy Bożej, przez oręże sprawiedliwości na prawo i na lewo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Przez chwałę i zelżywość, przez niesławę i dobrą sławę, jakoby zwodziciele, wszakże prawdziwi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Jako nieznajomi, wszakże znajomi; jako umierający, a oto żyjemy; jako pokarani, ale nie zabici;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Jako smutni, wszakże zawsze weseli; jako ubodzy, wszakże wielu ubogacający; jako nic nie mający, wszakże wszystko trzymający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Usta nasze otworzone są ku wam, o Koryntowie! serce nasze rozszerzone jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Nie jesteście ściśnieni w nas, lecz ściśnieni jesteście we wnętrznościach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'O wzajemną tedy nagrodę jako dziatkom mówię: Rozszerzcież się i wy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Nie ciągnijcież nierównego jarzma z niewiernymi; bo cóż za społeczność sprawiedliwości z nieprawością? albo co za społeczność światłości z ciemnością?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'A co za zgoda Chrystusa z Belijałem? albo co za dział wiernemu z niewiernym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'A co za zgoda kościoła Bożego z bałwanami? Albowiem wy jesteście kościołem Boga żywego, tak jako mówi Bóg: Będę mieszkał w nich i będę się przechadzał w nich, i będę Bogiem ich, a oni będą ludem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Przetoż wynijdźcie z pośrodku ich i odłączcie się, mówi Pan, a nieczystego się nie dotykajcie, a Ja was przyjmę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'I będę wam za Ojca, a wy mi będziecie za synów i za córki, mówi Pan wszechmogący.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Te tedy obietnice mając, najmilsi! oczyszczajmy samych siebie od wszelakiej zmazy ciała i ducha, wykonywając poświęcenie w bojaźni Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Przyjmijcież nas; nikogośmy nie ukrzywdzili, nikogośmy nie uszkodzili, nikogośmy przez łakomstwo nie podeszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Nie mówięć tego, abym was potępiać miał; bom przedtem powiedział, iż wy w sercach naszych tak jesteście, żebyśmy radzi z wami społecznie umierali i społecznie żyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Mam wielkie bezpieczeństwo do mówienia u was, mam wielką chlubę z was, napełnionym jest pociechą, nader obfituję weselem w każdym ucisku naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Albowiem gdyśmy przyszli do Macedonii, ciało nasze żadnego odpoczynku nie miało, ale we wszystkiem byliśmy uciśnieni, zewnątrz walki, a wewnątrz postrachy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Ale Bóg, który cieszy uniżonych, pocieszył nas przez przyjście Tytusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'A nie tylko przez przyjście jego, ale też przez pociechę, którą on ucieszony jest z was, oznajmiwszy nam żądność waszę, narzekanie wasze, gorliwość waszę za mną, tak żem się też więcej uweselił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Bo chociażem was zasmucił przez list, nie żal mi tego, chociaż mi żal było; bo widzę, iż ten list, chociaż na chwilę, zasmucił was był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Jednak teraz weselę się, nie dlatego, żeście zasmuceni byli, ale żeście zasmuceni byli w pokucie; albowiem byliście zasmuceni według Boga, żebyście w niczem nie szkodowali przez nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Albowiem smutek, który jest według Boga, pokutę sprawuje ku zbawieniu, której nikt nie żałuje; ale smutek według świata sprawuje śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Bo oto to samo, żeście według Boga byli zasmuceni, jako wielką w was pilność sprawiło, owszem obronę, owszem zapalczywość, owszem bojaźń, owszem żądność, owszem gorliwość, owszem pomstę, tak iż we wszystkiem okazaliście się być czystymi w tej sprawie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'A tak chociażem pisał do was, nie pisałem dla tego, który krzywdę uczynił, ani dla owego, któremu się krzywda stała, ale dla tego, iżby wam wiadoma była ona pilność nasza o was przed oblicznością Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Dlategośmy się ucieszyli z pociechy waszej; aleśmy się więcej ucieszyli z wesela Tytusowego, i ochłodzony jest duch jego od was wszystkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'A iż jeźlim się w czem przed nim z was chlubił, nie zawstydziłem się; ale jakośmy wam prawdziwie wszystko mówili, tak się też chluba nasza przed Tytusem prawdziwa pokazała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'A wnętrzności jego tem więcej skłonione są ku wam, gdy wspomina posłuszeństwo wszystkich was, i jakoście go bojaźnią i ze drżeniem przyjęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Raduję się tedy, iż wam we wszystkiem mogę zaufać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'A oznajmujemy wam, bracia! o łasce Bożej, która jest dana zborom Macedońskim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Iż w rozlicznem doświadczeniu utrapienia obfita ich radość i bardzo wielkie ubóstwo ich obfitowało w bogactwo szczerości ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Bo daję im świadectwo, że według możności i nad możność ochotnymi się pokazali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Z wielką prośbą nas żądając, abyśmy to dobrodziejstwo i spólne udzielenie, którem się usługuje świętym, przyjęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'A nie tylko tak sobie postąpili, jakośmy się spodziewali; ale najprzód samych siebie oddali Panu, potem i nam za wolą Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'Tak, żeśmy musieli napomnieć Tytusa, aby jako przedtem począł, tak aby też dokonał u was tegoż dobrodziejstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Przetoż jako we wszystkiem obfitujecie w wierze i w mowie, i w umiejętności, i we wszelakiej pilności, i w miłości waszej przeciwko nam, tak i w tem dobrodziejstwie obfitujcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Nie mówię jako rozkazując, ale przez pilność innych, jako jest szczera miłość wasza, na jawią wystawiając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Albowiem znacie łaskę Pana naszego, Jezusa Chrystusa, że dla was stał się ubogim, będąc bogatym, abyście wy ubóstwem jego ubogaceni byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'A w tem podaję wam zdanie swoje; albowiem to wam jest pożyteczno, którzy nie tylko czynić, ale i chcieć przedtemeście poczęli roku przeszłego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'A teraz to, coście czynić poczęli, wykonajcie, aby jako była ochotna myśl ku chceniu, tak też aby było i dokończenie z tego, co macie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Albowiem jeźli przedtem była ochotna myśl, taż przyjemna jest według tego, co kto ma, a nie według tego, czego nie ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Bo nie chcę, aby insi mieli ulżenie a wy uciśnienie, ale żeby za równo natenczas wasza obfitość ich niedostatkowi usłużyła;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'Aby też ich obfitość waszemu niedostatkowi usłużyła, żeby się stało porównanie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Jako napisane: Kto wiele nazbierał, nie miał nazbyt; a kto mało nazbierał, nie miał mało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Ale chwała Bogu, który dał takież staranie o was do serca Tytusowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Iż ono napomnienie przyjął, a stawszy się pilniejszym, dobrowolnie poszedł do was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'A posłaliśmy wespół z nim brata, który ma chwałę w Ewangielii po wszystkich zborach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'A nie tylko to, ale obrany jest przez głosy od zborów, za towarzysza drogi naszej z tem dobrodziejstwem, którem się dzieje usługa od nas ku chwale samego Pana i ku doświadczeniu ochotnego umysłu waszego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Uchodząc tego, aby nam kto nie przyganił dla tej obfitości, którą się przez nas usługuje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Pilnie się starając o uczciwe rzeczy, nie tylko przed Panem, ale też i przed ludźmi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'A posłaliśmy z nimi brata naszego, któregośmy często doświadczyli, w wielu rzeczach być pilnym, a teraz daleko pilniejszym dla wielkiej dowierności, którą ma przeciwko wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'A jeźli idzie o Tytusa, ten jest moim towarzyszem i u was pomocnikiem; a jeźli też o braci naszych, posłami są zborów i chwałą Chrystusową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Przetoż oświadczenie miłości waszej i chluby naszej z was pokażcie przeciwko nim przed oblicznością zborów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Lecz o usłudze, która się dzieje świętym, niepotrzebna mi jest wam pisać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Bo znam ochotę umysłu waszego, którą się ja chlubię z was u Macedończyków, iż Achaja gotowa była od przeszłego roku; a ta wasza gorliwość wiele ich pobudziła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Posłałem tedy tych braci, żeby chluba nasza, którą mamy z was, nie była daremna z tej miary, ale abyście (jakom powiedział), gotowymi byli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Abyśmy snać, jeźliby ze mną przyszli Macedończycy, a znaleźli was niegotowymi, nie zawstydzili się my, (że nie rzekę wy), za tak bezpieczną chlubę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Zdało mi się tedy za rzecz potrzebną, napomnieć braci, aby do was wprzód poszli i pierwej zgotowali przedtem opowiedzianą waszę szczodrobliwość, aby była gotowa tak jako szczodrobliwość, a nie jako rzecz przymuszona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Ale tak mówię: Kto skąpo sieje, skąpo też żąć będzie; a kto obficie sieje, obficie też żąć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Każdy jako umyślił w sercu swem, tak niech uczyni, nie z zamarszczeniem ani z przymuszenia; albowiem ochotnego dawcę Bóg miłuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'A mocen jest Bóg uczynić, aby obfitowała na was wszelka łaska, abyście mając we wszystkiem zawsze wszelaki dostatek, obfitowali ku wszelakiemu uczynkowi dobremu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Jako napisane: Rozproszył, dał ubogim, sprawiedliwość jego zostaje na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'A ten, który daje nasienie siejącemu, niechże i wam da chleb ku jedzeniu i rozmnoży nasienie wasze, i przysporzy urodzajów sprawiedliwości waszej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Abyście z każdej miary byli ubogaceni ku wszelkiej prostości, która sprawuje przez nas, aby dzięki Bogu czynione były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Albowiem usługiwanie tej ofiary nie tylko dopełnia niedostatki świętych, ale też opływa przez wielkie dziękczynienia na Boga przez pochwałę tej posługi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Gdy Boga chwalą za wasze poddaństwo Ewangielii Chrystusowej, za szczerość w udzielaniu przeciwko sobie i przeciwko wszystkim innym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'I modlą się za wami, żądając was dla łaski Bożej obfitującej w was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Lecz Bogu niech będzie chwała za niewypowiedziany dar jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Ja też Paweł sam was proszę przez cichość i dobrotliwość Chrystusową, który gdym jest wam przytomny, jestem pokorny między wami; lecz gdym nie jest przytomny, jestem śmiały przeciwko wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'A proszę, abym będąc przytomnym, nie musiał być śmiały tą śmiałością, o której myślę, abym śmiały był przeciwko niektórym, którzy nas szacują, jakobyśmy według ciała chodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Albowiem w ciele chodząc, nie według ciała walczymy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, '(Albowiem broń żołnierstwa naszego nie jest cielesna, ale z Boga jest, mocna ku zburzeniu miejsc obronnych.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Burząc rady i wszelaką wysokość, wynoszącą się przeciwko znajomości Bożej, i podbijając wszelaką myśl pod posłuszeństwo Chrystusowe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'I w pogotowiu mając pomstę na wszelakie nieposłuszeństwo, gdy się wypełni posłuszeństwo wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Na toż tylko, co przed oczyma jest, patrzycie? Mali kto tę nadzieję o sobie, iż jest Chrystusowy, niechże też to sam z siebie uważa, iż jako on jest Chrystusowy, tak też i my Chrystusowymi jesteśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Albowiem choćbym się ja też co więcej chełpił z mocy naszej, którą nam dał Pan ku zbudowaniu, a nie ku zepsowaniu waszemu, nie zawstydzę się;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Abym się nie zdał, jakobym was straszył przez listy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Albowiem mówią: Listy ważne są i potężne, ale ciała obecność niepotężna jest i mowa niepłatna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'To niechaj myśli taki, iż jakimiśmy w mowie przez listy, nie będąc obecnymi, takimiż będziemy i w uczynku, będąc obecnymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Albowiem nie śmiemy samych siebie w poczet drugich kłaść, albo porównywać z niektórymi, którzy sami siebie zalecają; ale i ci nie zrozumiewają, iż się sami sobą miarkują i sami się do siebie przyrównywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Ale my nie będziemy się chlubili nad miarę, ale według sznuru miary, którą miarę wymierzył nam Bóg, tak żeśmy dosięgli aż do was,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Bo się nie rozciągamy nad miarę, jakobyśmy nie dosięgli aż do was; bośmy aż i do was przyszli w Ewangielii Chrystusowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'A nie chlubimy się nad miarę z cudzych prac; ale mając nadzieję, iż gdy się pomnoży wiara wasza w was, pomnożymy się i my między wami według sznuru naszego z obfitością,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Ku opowiadaniu Ewangielii w onych krainach, które leżą za wami, nie chlubiąc się z rzeczy gotowych cudzego pomiaru.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Kto się tedy chlubi, niech się Panu chlubi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Albowiem nie ten, co się sam zaleca, doświadczony jest, ale ten, którego Pan zaleca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Obyście chcieli na chwilę znosić głupstwo moje! ale i znaszajcie mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Albowiem gorliwym jestem ku wam gorliwością Bożą; bom was przygotował, abym was stawił czystą panną jednemu mężowi Chrystusowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Lecz boję się, by snać jako wąż oszukał Ewę chytrością swoją, tak też skażone myśli wasze nie odpadły od prostoty onej, która jest w Chrystusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Bo gdyby kto przyszedł, co by inszego Jezusa opowiadał, któregośmy nie opowiadali; albo gdybyście innego ducha wzięli, któregoście nie wzięli, albo inszą Ewangieliję, którejście nie przyjęli, dobrze byście go znosili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Boć mam za to, żem nie był w niczem podlejszy, niżeli oni bardzo wielcy Apostołowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Bo chociażem też i prostakiem w mowie, wszakże nie w umiejętności; ale zgoła jawnymiśmy się stali we wszystkich rzeczach u was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Izalim się grzechu dopuścił, żem samego siebie uniżył, abyście wy byli wywyższeni, a żem wam darmo Ewangieliję Bożą opowiadał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Złupiłem inne zbory, biorąc od nich żołd, abym wam służył; a będąc u was i cierpiąc niedostatek, nie obciążyłem próżnując nikogo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Albowiem niedostatek mój dopełnili bracia, którzy przyszli z Macedonii, i we wszystkim strzegłem się, abym wam ciężkim nie był, i na potem strzec się będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Jestci prawda Chrystusowa we mnie, iż ta chluba nie będzie zatłumiona we mnie w krainach Achajskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Dlategoż? czy że was nie miłuję? Bógci wie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Ale co czynię, czynić jeszcze będę dlatego, abym odciął przyczynę tym, którzy przyczyny szukają, aby w tem, z czego się chlubią, byli znalezieni tacy, jako i my.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Albowiem takowi fałszywi Apostołowie są robotnicy zdradliwi, którzy się przemieniają w Apostoły Chrystusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'A nie dziw: bo i szatan sam przemienia się w Anioła światłości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Nie wielka tedy, jeźli też słudzy jego przemieniają się, jakoby byli sługami sprawiedliwości, których koniec będzie podług uczynków ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Znowu powiadam, żeby mię kto nie miał za głupiego; jeźliż inaczej, więc jako głupiego przyjmijcie mię, abym się ja też nieco maluczko przechwalał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Co mówię, nie mówięć jako od Pana, ale jako w głupstwie z strony tej bezpiecznej chluby.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Ponieważ się ich wiele chlubi według ciała, i ja się chlubić będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Bo radzi znosicie głupich, będąc sami mądrymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Bo znosicie, choć was kto zniewala, choć kto pożera, choć kto bierze, choć się kto wynosi, choć was kto policzkuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Mówiąc według zelżywości, jakobyśmy byli słabymi; lecz w czem kto śmiałym jest, (w głupstwie mówię) i jam śmiały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Żydowie są, jestem i ja. Izraelczycy są, jestem i ja. Nasieniem Abrahamowem są, jestem i ja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Sługami Chrystusowymi są, (głupio mówię), więcej ja; w pracach obficiej, w razach nad miarę, w więzieniach obficiej, w śmierciach częstokroć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Od Żydów wziąłem pięciokroć po czterdzieści plag bez jednej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Trzykrociem był bity rózgami; razem był kamionowany; trzykroć się ze mną okręt rozbił, dzień i noc byłem w głębokości morskiej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'W drogach częstokroć, w niebezpieczeństwach na rzekach, w niebezpieczeństwach od zbójców, w niebezpieczeństwach od swego narodu, w niebezpieczeństwach od pogan, w niebezpieczeństwach w mieście, w niebezpieczeństwach na puszczy, w niebezpieczeństwach na morzu, w niebezpieczeństwach między fałszywymi braćmi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'W pracy i w utrapieniu, w niedosypianiu często, w głodzie, i w pragnieniu, w postach często, i w zimnie, i w nagości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Oprócz tego, co skądinąd przyda, ono naleganie na mię na każdy dzień i ono staranie o wszystkie zbory.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Któż choruje, a ja nie choruję? Któż się gorszy, a ja nie palę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Jeźli się mam chlubić, z krewkości moich chlubić się będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Bóg i Ojciec Pana naszego, Jezusa Chrystusa, który jest błogosławiony na wieki, wie, iż nie kłamię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'W Damaszku hetman ludu króla Arety osadził był strażą miasto Damaszek, chcąc mię pojmać; alem oknem po powrozie w koszyku przez mur był spuszczony i uszedłem rąk jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Wprawdzieć mi się chlubić nie jest pożyteczno: jednak przyjdę do widzenia i objawienia Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Znam człowieka w Chrystusie przed czternastoma laty, (jeźli się to działo w ciele, nie wiem, jeźli oprócz ciała, nie wiem, Bóg wie), który zachwycony był aż do trzeciego nieba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'A znam takiego człowieka, (Jeźli się to działo w ciele, jeźli oprócz ciała, nie wiem, Bóg wie).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Iż był zachwycony do raju i słyszał niewypowiedziane słowa, których człowiekowi nie godzi się mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Z takiego człowieka chlubić się będę; ale z siebie samego chlubić się nie będę, tylko z krewkości moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Albowiem jeźlibym się chciał chlubić, nie będę głupi, bo prawdę powiem, ale wstrzymam się, aby kto o mnie nie rozumiał nad to, czem mię być widzi, albo co słyszy ode mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'A iżbym się zacnością objawienia nader nie wynosił, dany mi jest bodziec ciału, anioł szatan, aby mię policzkował, żebym się nad miarę nie wynosił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Dlategom trzykroć Pana prosił, aby odstąpił ode mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Ale mi rzekł: Dosyć masz na łasce mojej; albowiem moc moja wykonywa się w słabości. Raczej się tedy więcej chlubić będę z krewkości moich, aby we mnie mieszkała moc Chrystusowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Dlatego się kocham w krewkościach, w potwarzach, w niedostatkach, w prześladowaniach, i w uciskach dla Chrystusa; bo gdym jest słaby, tedym jest mocny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Stałem się głupim, chlubiąc się; wyście mię do tego przymusili. Bom ja od was miał być chwalony, ponieważem nie był podlejszym, niżeli oni bardzo wielcy Apostołowie, chociażem nic nie jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Jednak znaki Apostoła pokazane są u was we wszelkiej cierpliwości, w znamionach i w cudach, i w mocach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Bo cóż jest, w czem byście podlejsi byli nad insze zbory, tylko żem ja sam próżnując, nie obciążył was? Odpuśćcież mi tę krzywdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Oto trzeci raz jestem gotów przyjść do was, a nie obciążę was próżnując; albowiem nie szukam tego, co jest waszego, ale w was samych; boć nie dziatki mają rodzicom skarbić, ale rodzice dziatkom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Lecz ja bardzo rad nakład uczynię i samego siebie wynałożę za duszę waszę, aczkolwiek bardzo was miłując, mniej bywam od was miłowany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Ale niech tak będzie; jam was nie obciążył, tylko chytrym będąc, zdradąm was pojmał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Izalim was przez którego z tych, którychem do was posłał, oszukał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Uprosiłem Tytusa i posłałem z nim brata tego. Izali was Tytus oszukał? Izaliśmy nie jednym duchem postępowali? Izali nie jednemi stopami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Znowuż mniemacie, że się przed wami obawiamy? Przed oblicznością Bożą w Chrystusie mówimy, a to wszystko, najmilsi! dla waszego zbudowania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Bo się boję, bym snać przyszedłszy, nie znalazł was takimi, jakimi bym nie chciał, a ja też żebym nie był znaleziony od was, jakiego byście wy nie chcieli; by snać między wami nie było swarów, zazdrości, gniewów, zwad, obmowisk, mruczenia, nadymania i rozterków;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'By mię zasię Bóg mój, gdy przyjdę, nie poniżył u was, i żałowałbym wielu tych, którzy przedtem grzeszyli, a nie pokutowali z nieczystości i z wszeteczeństwa, i z rozpusty, którą popełnili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Trzeci to już raz idę do was. W ustach dwóch lub trzech świadków stanie każde słowo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Powiedziałem przedtem i znowu powiadam jako powtóre obecny, a teraz nie będąc obecny piszę tym, którzy przedtem grzeszyli i wszystkim inszym, że jeźli znowu przyjdę, nie przepuszczę im.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Ponieważ chcecie doświadczyć tego, który we mnie mówi, Chrystusa, który ku wam nie jest słaby, ale mocny jest w was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Bo aczkolwiek ukrzyżowany jest jako słaby, ale żyje z mocy Bożej, a tak i my jesteśmy z nim słabymi, ale żyć będziemy z nim z mocy Bożej przeciwko wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Doświadczajcie samych siebie, jeźli jesteście w wierze, samych siebie doznawajcie. Czyli samych siebie znacie, że Jezus Chrystus w was jest? chyba żebyście byli odrzuceni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Mam jednak nadzieję, że poznacie, iż my nie jesteśmy odrzuconymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'I modlę się Bogu, abyście nic złego nie czynili; nie iżbyśmy się my doświadczonymi okazali, ale abyście wy to, co jest dobrego, czynili, a my żebyśmy byli jako odrzuceni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Boć nie możemy nic przeciwko prawdzie, ale za prawdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Albowiem się radujemy, że chociaśmy my słabymi, ale wy jesteście mocnymi; a tegoć i życzymy, abyście wy byli doskonałymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Przetoż to piszę, nie będąc obecny, abym będąc obecnym, nie musiał używać srogości według mocy, którą mi dał Pan na zbudowanie, a nie na zepsowanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Na ostatek, bracia! miejcie się dobrze; doskonałymi bądźcie, cieszcie się, jednomyślnymi bądźcie, w pokoju żyjcie, a Bóg miłości i pokoju będzie z wami. Pozdrówcie jedni drugich świętem pocałowaniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Pozdrawiają was wszyscy święci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Łaska Pana Jezusa Chrystusa i miłość Boża, i społeczność Ducha Świętego niech będzie z wami wszystkimi. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paweł, Apostoł (nie od ludzi, ani przez człowieka, ale przez Jezusa Chrystusa i Boga Ojca, który go wzbudził od umarłych;)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'I wszyscy bracia, którzy są ze mną, zborom Galackim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Łaska wam i pokój niech będzie od Boga Ojca i Pana naszego, Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Który wydał samego siebie za grzechy nasze, aby nas wyrwał z teraźniejszego wieku złego według woli Boga i Ojca naszego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Któremu niech będzie chwała na wieki wieków. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Dziwuję się, iż tak prędko dacie się przenosić od tego, który was powołał ku łasce Chrystusowej, do inszej Ewangielii;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'Która nie jest inszą; tylko niektórzy są, co was turbują i chcą wywrócić Ewangieliję Chrystusową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Ale choćbyśmy i my, albo Anioł z nieba opowiadał wam Ewangieliję mimo tę, którąśmy wam opowiadali, niech będzie przeklęty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Jakośmy przedtem powiedzieli i teraz znowu mówię: Jeźliby wam kto inną Ewangieliję opowiadał mimo tę, którąście przyjęli, niech będzie przeklęty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Albowiem terazże do ludzi was namawiam, czyli do Boga? Albo szukamli, abym się podobał ludziom? Zaiste, jeźlibym się jeszcze ludziom chciał podobać, nie byłbym sługą Chrystusowym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'A oznajmuję wam bracia! iż Ewangielija, która jest opowiadana ode mnie, nie jest według człowieka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Albowiem ja anim jej wziął, anim się jej nauczył od człowieka, ale przez objawienie Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Boście słyszeli o mojem obcowaniu niekiedy w Żydostwie, żem nader prześladował zbór Boży i burzyłem go;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'I postępowałem w Żydostwie nad wiele rówieśników moich w narodzie moim, będąc nader gorliwym miłośnikiem ustaw moich ojczystych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Ale gdy się upodobało Bogu, który mię odłączył z żywota matki mojej, i powołał z łaski swojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'Aby objawił Syna swego we mnie, abym go opowiadał między poganami, wnetże nie radziłem się ciała i krwi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Anim się wrócił do Jeruzalemu, do tych, którzy przede mną byli Apostołami, alem szedł do Arabii i wróciłem się zasię do Damaszku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Potem po trzech latach wstąpiłem do Jeruzalemu, abym się ujrzał z Piotrem; i mieszkałem u niego piętnaście dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'A inszegom z Apostołów nie widział, oprócz Jakóba, brata Pańskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'A co wam piszę, oto się przed Bogiem oświadczam, żeć nie kłamię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Zatemem przyszedł do krain Syryi i Cylicyi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'A byłem nieznajomym z twarzy zborom żydowskim, które są w Chrystusie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Lecz tylko byli usłyszeli, iż ten, który prześladował nas niekiedy, teraz opowiada wiarę, którą przedtem burzył. I chwalili Boga ze mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, '');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Potem po czternastu latach wstąpiłem zasię do Jeruzalemu z Barnabaszem, wziąwszy z sobą i Tytusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'A wstąpiłem według objawienia i przełożyłem im Ewangieliję, którą każę między poganami, a zwłaszcza zacniejszym, bym snać nadaremno nie bieżał, albo przedtem nie biegał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Ale ani Tytus, który ze mną był, będąc Grekiem, nie był przymuszony obrzezać się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'A to dla wprowadzonych fałszywych braci, którzy się wkradli, aby wyszpiegowali wolność naszę, którą mamy w Chrystusie Jezusie, aby nas w niewolę podbili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Którymeśmy i na chwilkę nie ustąpili, i nie poddali się, aby u was prawda Ewangielii została.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'A od tych, którzy się zdadzą być czemś, (acz jakimi niekiedy byli, nic mi na tem; bo osoby człowieczej Bóg nie przyjmuje), ci mówię, którzy się zdali być czemś, nic mi nie przydali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Owszem, przeciwnym obyczajem, widząc, iż mi jest zwierzona Ewangielija między nieobrzezanymi, jako Piotrowi między obrzezanymi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(Albowiem ten, który był skuteczny przez Piotra w apostolstwie między obrzezanymi, skuteczny był i we mnie między poganami.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'I poznawszy łaskę mnie daną, Jakób i Kiefas, i Jan, którzy się zdadzą być filarami, podali prawicę mnie i Barnabaszowi na towarzystwo, abyśmy my między poganami, a oni między obrzezanymi kazali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Tylko upomnieli, abyśmy na ubogich pamiętali, o com się też pilnie starał, abym to uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'A gdy przyszedł Piotr do Antyjochii, sprzeciwiłem się mu w twarz; i był godzien nagany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Albowiem przedtem, niż przyszli niektórzy od Jakóba, wespół z poganami jadał; a gdy ci przyszli, schraniał się i odłączał, bojąc się tych, którzy byli z obrzezania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'A wespół z nim obłudnie się obchodzili i drudzy Żydzi, tak że i Barnabasz uwiedziony był tą ich obłudą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Ale gdym obaczył, iż nie prosto chodzą w prawdzie Ewangielii, rzekłem Piotrowi przed wszystkimi: Ponieważ ty, będąc Żydem, po pogańsku żyjesz a nie po żydowsku, czemuż pogan przymuszasz po żydowsku żyć?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'My, którzyśmy z przyrodzenia Żydowie a nie z pogan grzesznicy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Wiedząc, iż nie bywa usprawiedliwiony człowiek z uczynków zakonu, ale przez wiarę w Jezusa Chrystusa, i myśmy w Jezusa Chrystusa uwierzyli, abyśmy byli usprawiedliwieni z wiary Chrystusowej, a nie z uczynków zakonu, przeto że nie będzie usprawiedliwione z uczynków zakonu żadne ciało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'A jeźli my szukając, abyśmy byli usprawiedliwieni w Chrystusie, znajdujemy się też grzesznikami, tedyć Chrystus jest sługą grzechu? Nie daj tego Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Albowiem jeźli to, com zburzył, znowu zasię buduję, przestępcą samego siebie czynię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Bom ja przez zakon zakonowi umarł, abym żył Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Z Chrystusem jestem ukrzyżowany, a żyję już nie ja, lecz żyje we mnie Chrystus; a to że teraz w ciele żyję, w wierze Syna Bożego żyję, który mię umiłował i wydał samego siebie za mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Nie odrzucam tej łaski Bożej; bo jeźli przez zakon jest sprawiedliwość, tedyć Chrystus próżno umarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'O głupi Galatowie! Któż was omamił, abyście prawdzie nie byli posłuszni, którym przed oczyma Jezus Chrystus przedtem był wymalowany, i między wami ukrzyżowany?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Tego tylko rad bym się nauczył od was: Z uczynkówli zakonu wzięliście Ducha, czyli z słuchania wiary?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Takeście głupi? począwszy duchem, teraz ciałem dokonywacie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Takeście wiele cierpieli darmo, jeźli tylko i darmo?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Ten tedy, który wam dodaje ducha i czyni cuda między wami, z uczynkówże zakonu to czyni, czyli z słuchania wiary?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Tak jako \"Abraham uwierzył Bogu i przyczytano mu to ku sprawiedliwości\".');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Widzicie tedy, że ci, którzy są z wiary, ci są synami Abrahamowymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'A upatrzywszy to Pismo, iż z wiary Bóg usprawiedliwia pogan, przedtem opowiedziało Abrahamowi, iż w tobie będą błogosławione wszystkie narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'A tak ci, którzy są z wiary, dostępują błogosławieństwa z wiernym Abrahamem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Albowiem ile ich jest z uczynków zakonu, pod przeklęstwem są; bo napisane: Przeklęty każdy, który by nie został we wszystkiem, co napisane w księgach zakonu, aby to czynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'A iż przez zakon nikt nie bywa usprawiedliwiony przed Bogiem, jawna jest stąd, bo \"sprawiedliwy z wiary żyć będzie\".');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Ale zakon nie jestci z wiary; lecz \"człowiek, który by je czynił, żyć będzie przez nie\".');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Ale Chrystus odkupił nas z przeklęstwa zakonu, stawszy się za nas przeklęstwem, (albowiem napisane: Przeklęty każdy, który wisi na drzewie).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Aby na pogan błogosławieństwo Abrahamowe przyszło w Chrystusie Jezusie, i abyśmy obietnicę Ducha wzięli przez wiarę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Bracia! po ludzku mówię: a wszak i człowieczego testamentu utwierdzonego nikt nie łamie, ani do niego co przydaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Lecz Abrahamowi uczynione są obietnice i nasieniu jego; nie mówi: I nasieniom jego, jako o wielu, ale jako o jednem: I nasieniu twemu, które jest Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'To tedy mówię, iż przymierza przedtem od Boga utwierdzonego względem Chrystusa, zakon, który po czterechset i po trzydziestu lat nastał, nie znosi, aby miał zepsuć obietnicę Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Albowiem jeźliż z zakonu jest dziedzictwo, jużci nie z obietnicy; lecz Abrahamowi przez obietnicę darował je Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Cóż tedy zakon? Dla przestępstwa przydany jest, ażby przyszło ono nasienie, któremu się stała obietnica, sporządzony przez Aniołów i przez rękę pośrednika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Lecz pośrednik nie jest jednego, ale Bóg jeden jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Zakon tedy jestże przeciwko obietnicom Bożym? Nie daj tego Boże! albowiem gdyby był dany zakon, który by mógł ożywiać, prawdziwieć by z zakonu była sprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Ale Pismo zamknęło wszystko pod grzech, aby obietnica z wiary Jezusa Chrystusa była dana wierzącym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'A przedtem, niż przyszła wiara, byliśmy pod zakonem strzeżeni, wespół zamknieni będąc w tę wiarę, która potem miała być objawiona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'A przetoż zakon pedagogiem naszym był do Chrystusa, abyśmy z wiary byli usprawiedliwieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Ale gdy przyszła wiara, już nie jesteśmy pod pedagogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Albowiem wszyscy synami Bożymi jesteście przez wiarę w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Bo którzykolwiek jesteście w Chrystusa ochrzczeni, w Chrystusaście się oblekli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Nie masz Żyda, ani Greka; nie masz niewolnika ani wolnego; nie masz mężczyzny i niewiasty; albowiem wszyscy wy jednym jesteście w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'A jeźliście wy Chrystusowi, tedyście nasieniem Abrahamowem, a według obietnicy dziedzicami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Mówię tedy: (bracia!) Pokąd dziedzic jest dziecięciem, nic nie jest różny od sługi, panem będąc wszystkiego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Ale jest pod opiekunami i dozorcami aż do czasu zamierzenia ojcowskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Także i my, gdyśmy byli dziećmi, pod żywioły świata byliśmy zniewoleni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Lecz gdy przyszło wypełnienie czasu, posłał Bóg onego Syna swego, który się urodził z niewiasty, który się stał pod zakonem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Aby tych, którzy pod zakonem byli, wykupił, żebyśmy prawa przysposobienia za synów dostąpili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'A iżeście synowie, przetoż posłał Bóg Ducha Syna swego w serca wasze, wołającego Abba, to jest Ojcze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'A tak już więcej nie jesteś niewolnikiem, ale synem; a ponieważ synem, tedy i dziedzicem Bożym przez Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Aleć naonczas nie znając Boga, służyliście tym, którzy z przyrodzenia nie są bogowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'A teraz poznawszy Boga, owszem i poznani będąc od Boga, jakoż się zaś nazad wracacie ku żywiołom mdłym i mizernym, którym zasię znowu służyć chcecie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Przestrzegacie dni i miesiące, i czasy, i lata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Boję się o was, bym snać darmo nie pracował około was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Bądźcie jako ja, gdyżem i ja jest jako wy, bracia! proszę was. W niczemeście mnie nie ukrzywdzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Bo wiecie, żem w słabości ciała wam z przodku Ewangieliję opowiadał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'A pokuszenia mego, które było w ciele mojem, sobie nie lekceważyliście, aniście niem gardzili, aleście mię jako Anioła Bożego przyjęli i jako Chrystusa Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Jakież tedy było błogosławieństwo wasze? albowiem wam daję świadectwo, iż, by była rzecz można, dalibyście mi byli wyłupiwszy oczy wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Takżem się stał nieprzyjacielem waszym, prawdę wam mówiąc?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Pałają ku wam miłością nie dobrze, owszem chcą was odstrychnąć, abyście ich miłowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'A dobrać rzecz, pałać miłością w dobrem zawsze, a nie tylko, gdym jest obecnym u was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Dziatki moje! (które znowu z boleścią rodzę, ażby Chrystus był wykształtowany w was),');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Chciałbym teraz być u was i odmienić głos mój, ponieważ wątpię o was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Powiedzcie mi, którzy pod zakonem chcecie być, nie słuchacież zakonu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Albowiem napisane, iż Abraham miał dwóch synów, jednego z niewolnicy, a drugiego z wolnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Lecz ten, który był z niewolnicy, według ciała się urodził, a który z wolnej, według obietnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Przez co znaczą się insze rzeczy; albowiem te są one dwa testamenty; jeden z góry Synajskiej, który rodzi w niewolę; a ten jest jako Agar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Albowiem Agar jest góra Synaj w Arabii, a stosuje się do niej teraźniejsze Jeruzalem; bo jest w niewoli z dziatkami swojemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Lecz ono górne Jeruzalem wolne jest, które jest matką wszystkich nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Albowiem napisano: Rozwesel się niepłodna, która nie rodzisz; porwij się, a zawołaj, która nie pracujesz w porodzeniu; bo ta opuszczona wiele ma dziatek, więcej niż ta, która ma męża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'My tedy, bracia! tak jako Izaak, jesteśmy dziatkami obietnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Ale jako na on czas ten, który się był urodził według ciała, prześladował tego, który się był urodził według ducha, tak się dzieje i teraz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Ale co mówi Pismo? Wyrzuć niewolnicę i syna jej; albowiem nie będzie dziedziczył syn niewolnicy z synem wolnej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'A tak, bracia! nie jesteśmy dziećmi niewolnicy, ale wolnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Stójcie tedy w tej wolności, którą nas Chrystus wolnymi uczynił, a nie poddawajcie się znowu pod jarzmo niewoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Oto ja Paweł mówię wam, iż jeźli się obrzezywać będziecie, Chrystus wam nic nie pomoże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'A oświadczam się zasię przed każdym człowiekiem, który się obrzezuje, iż powinien wszystek zakon pełnić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Pozbawiliście się Chrystusa, którzykolwiek się przez zakon usprawiedliwiacie; wypadliście z łaski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Albowiem my duchem z wiary nadziei sprawiedliwości oczekujemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Bo w Chrystusie Jezusie ani obrzezka nic nie waży, ani nieobrzezka, ale wiara przez miłość skuteczna;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Bieżeliście dobrze; któż wam przeszkodził, abyście nie byli posłusznymi prawdzie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Ta namowa nie jestci z tego, który was powołuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Trochę kwasu wszystko zaczynienie zakwasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Ja mam nadzieję o was w Panu, iż nic inszego rozumieć nie będziecie; a ten, który was turbuje, odniesie sąd, ktokolwiek jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'A ja, bracia! jeźli jeszcze obrzezkę każę, czemuż jeszcze prześladowanie cierpię? Toć tedy zniszczone jest zgorszenie krzyżowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Bodajże i odjęci byli, którzy wam niepokój czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Albowiem wy ku wolności powołani jesteście, bracia! tylko pod zasłoną tej wolności ciału nie pozwalajcie, ale z miłości służcie jedni drugim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Bo wszystek zakon w jednem się słowie zamyka, to jest w tem: Będziesz miłował bliźniego twego jako samego siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Ale jeźli jedni drugich kąsacie i pożeracie, patrzajcież, abyście jedni od drugich nie byli strawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'A to mówię: Duchem postępujcie, a pożądliwości ciała nie wykonywajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Albowiem ciało pożąda przeciwko duchowi, a duch przeciwko ciału; a te rzeczy są sobie przeciwne, abyście nie to, co chcecie, czynili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Lecz jeźli duchem bywacie prowadzeni, nie jesteście pod zakonem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'A jawneć są uczynki ciała, które te są: Cudzołóstwo, wszeteczeństwo, nieczystość, rozpusta,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Bałwochwalstwo, czary, nieprzyjaźni, swary, nienawiści, gniewy, spory, niesnaski, kacerstwa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Zazdrości, mężobójstwa, pijaństwa, biesiady, i tym podobne rzeczy, o których przepowiadam wam, jakom i przedtem powiedział, iż którzy takowe rzeczy czynią, królestwa Bożego nie odziedziczą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Ale owoc Ducha jest miłość, wesele, pokój, nieskwapliwość, dobrotliwość, dobroć, wiara, cichość, wstrzemięźliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Przeciwko takowym nie masz zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Albowiem którzy są Chrystusowi, ciało swoje ukrzyżowali z namiętnościami i z pożądliwościami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Jeźli duchem żyjemy, duchem też postępujmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Nie bądźmy chciwi próżnej chwały, jedni drugich wyzywając, jedni drugim zajrząc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Bracia! jeźliby też człowiek zachwycony był w jakim upadku, wy duchowni: naprawiajcie takiego w duchu cichości, upatrując każdy samego siebie, abyś i ty nie był kuszony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Jedni drugich brzemiona noście, a tak wypełniajcie zakon Chrystusowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Albowiem jeźli kto mniema, żeby czem był, nie będąc niczem, takiego zawodzi własny umysł jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Ale każdy niechaj własnego swego uczynku doświadcza, a tedy sam w sobie chwałę mieć będzie, a nie w drugim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Albowiem każdy swoje własne brzemię poniesie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'A niech udziela ten, który bywa nauczany w słowie, temu, który go naucza, ze wszystkich dóbr.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Nie błądźcie; Bóg się nie da z siebie naśmiewać; albowiem cobykolwiek siał człowiek, to też żąć będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Bo kto sieje ciału swemu, z ciała żąć będzie skażenie; ale kto sieje duchowi, z ducha żąć będzie żywot wieczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'A dobrze czyniąc nie słabiejmy; albowiem czasu swojego żąć będziemy nie ustawając.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Przeto tedy, póki czas mamy, dobrze czyńmy wszystkim, a najwięcej domownikom wiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Widzicie, jakim długi list wam napisał ręką moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Którzykolwiek chcą być pozorni według ciała, ci was przymuszają, abyście się obrzezali, tylko aby dla krzyża Chrystusowego prześladowania nie cierpieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Albowiem i ci, którzy się obrzezują, nie zachowywują zakonu sami, ale chcą, abyście się wy obrzezali, żeby się z ciała waszego chlubili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Ale ja, nie daj Boże, abym się miał chlubić, tylko w krzyżu Pana naszego Jezusa Chrystusa, przez którego mi jest świat ukrzyżowany, a ja światu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Albowiem w Chrystusie Jezusie ani obrzezka nic nie waży, ani nieobrzezka, ale nowe stworzenie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'A którzykolwiek według tego sznuru postępować będą, pokój na nich przyjdzie i miłosierdzie, i na lud Boży Izraelski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Na ostatek niechaj mi nikt trudności nie zadaje; albowiem ja piętna Pana Jezusowe noszę na ciele mojem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Łaska Pana naszego Jezusa Chrystusa niech będzie z duchem waszym, bracia! Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paweł, Apostoł Jezusa Chrystusa przez wolę Bożą, świętym, którzy są w Efezie, i wiernym w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Łaska wam i pokój niech będzie od Boga, Ojca naszego, i Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Błogosławiony niech będzie Bóg i Ojciec Pana naszego Jezusa Chrystusa, który nas ubłogosławił wszelkiem błogosławieństwem duchownem w niebieskich rzeczach w Chrystusie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Jako nas wybrał w nim przed założeniem świata, abyśmy byli świętymi i nienaganionymi przed oblicznością jego w miłości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Który nas przenaznaczył ku przysposobieniu za synów przez Jezusa Chrystusa dla siebie samego, według upodobania woli swojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Ku chwale sławnej łaski swojej, którą nas udarował w onym umiłowanym:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'W którym mamy odkupienie przez krew jego, to jest odpuszczenie grzechów, według bogactwa łaski jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Którą hojnie pokazał przeciwko nam we wszelkiej mądrości i roztropności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Oznajmiwszy nam tajemnicę woli swojej według upodobania swego, które był postanowił w samym sobie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'Aby w rozrządzeniu zupełności czasów w jedno zgromadził wszystkie rzeczy w Chrystusie, i te, które są na niebiesiech, i te, które są na ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'W nim, mówię, w którymeśmy i do działu przypuszczeni, przenaznaczeni będąc według postanowienia tego, który sprawuje wszystko według rady woli swojej;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Abyśmy my byli ku chwale sławy jego, którzyśmy pierwej nadzieję mieli w Chrystusie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'W którym i wy nadzieję macie, usłyszawszy słowo prawdy, to jest Ewangieliję zbawienia waszego, przez którą też uwierzywszy, jesteście zapieczętowani Duchem onym Świętym obiecanym,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Który jest zadatkiem dziedzictwa naszego na wykupienie nabytej własności, ku chwale sławy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Przetoż i ja usłyszawszy o tej wierze, którą macie w Panu Jezusie, i o miłości ku wszystkim świętym,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Nie przestaję dziękować za was, wzmiankę czyniąc o was w modlitwach moich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Aby Bóg Pana naszego Jezusa Chrystusa, Ojciec on chwały, dał wam Ducha mądrości i objawienia ku poznaniu samego siebie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Ażeby oświecił oczy myśli waszej, abyście wiedzieli, która jest nadzieja powołania jego i które jest bogactwo chwały dziedzictwa jego w świętych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'I która jest ona przewyższająca wielkość mocy jego przeciwko nam, którzy wierzymy według skutecznej mocy siły jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Której dokazał w Chrystusie, gdy go wzbudził od umarłych i posadził na prawicy swojej na niebiesiech,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Wysoko nad wszystkie księstwa i zwierzchności, i mocy, i państwa, i nad wszelkie imię, które się mianuje, nie tylko w tym wieku, ale i w przyszłym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'I wszystko poddał pod nogi jego, a onego dał za głowę nad wszystkim kościołowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Który jest ciałem jego i pełnością tego, który wszystko we wszystkich napełnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'I was ożywił, którzyście byli umarli w upadkach i w grzechach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'W którycheście niekiedy chodzili według zwyczaju świata tego i według książęcia, który ma władzę na powietrzu, ducha tego, który teraz jest skuteczny w synach niedowiarstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Między którymi i my wszyscy obcowaliśmy niekiedy w pożądliwościach ciała naszego, czyniąc to, co się podobało ciału i myślom, i byliśmy z przyrodzenia dziećmi gniewu, jako i drudzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Lecz Bóg, który jest bogaty w miłosierdziu, dla wielkiej miłości swojej, którą nas umiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'I gdyśmy byli umarłymi w grzechach, ożywił nas pospołu z Chrystusem, (gdyż łaską zbawieni jesteście)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'I pospołu z nim wzbudził, i pospołu z nim posadził na niebiesiech w Chrystusie Jezusie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Aby okazał w przyszłych wiekach ono nader obfite bogactwo łaski swojej, z dobrotliwości swojej przeciwko nam w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Albowiem łaską jesteście zbawieni przez wiarę, i to nie jest z was, dar to Boży jest;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Nie z uczynków, aby się kto nie chlubił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Albowiem czynem jego jesteśmy stworzeni w Chrystusie Jezusie ku uczynkom dobrym, które przedtem Bóg zgotował, abyśmy w nich chodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Przetoż pamiętajcie, że wy niekiedy będąc poganami w ciele, którzyście byli zwani nieobrzezką od onych, których zwano obrzezką w ciele, która się ręką dzieje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Iżeście byli naonczas bez Chrystusa, oddaleni od społeczności Izraelskiej i obcymi od umów obietnicy, nadziei nie mający i bez Boga na świecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Ale teraz w Chrystusie Jezusie wy, którzyście niekiedy byli dalekimi, staliście się bliskimi przez krew Chrystusową,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Albowiem on jest pokojem naszym, który oboje jednem uczynił i średnią ścianę, która była przegrodą, rozwalił;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Nieprzyjaźń, to jest zakon przykazań, który zależał w ustawach, skaziwszy przez ciało swoje, aby dwóch stworzył w samym sobie w jednego nowego człowieka, czyniąc pokój;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'I pojednał obydwóch w jednem ciele z Bogiem przez krzyż, zgładziwszy nieprzyjaźń przezeń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'I przyszedłszy opowiedział pokój wam, którzyście dalekimi i którzyście bliskimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Albowiem przezeń mamy przystęp obie strony w jednym Duchu do Ojca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'A przetoż już więcej nie jesteście gośćmi i przychodniami, ale spółmieszczaninami świętych i domownikami Bożymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Zbudowani na fundamencie Apostołów i proroków, którego jest gruntownym węgielnym kamieniem sam Jezus Chrystus,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'Na którym wszystko budowanie wespół spojone rośnie w kościół święty w Panu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'Na którym też i wy się wespół budujecie, abyście byli mieszkaniem Bożem w Duchu Świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Dlatego ja Paweł jestem więźniem Chrystusa Jezusa za was pogan;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Jeźliście tylko słyszeli o udzieleniu łaski Bożej, która mi jest dana dla was,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Iż mi Bóg przez objawienie oznajmił tajemnicę, (jakom wam przedtem krótko napisał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Skąd czytając możecie obaczyć wiadomość moję w tajemnicy Chrystusowej).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Która inszych wieków nie była znajoma synom ludzkim, jako teraz objawiona jest świętym Apostołom jego i prorokom przez Ducha;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'To jest, iż poganie są spółdziedzicami i spólnem ciałem, i spółuczestnikami obietnicy jego w Chrystusie przez Ewangieliję.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Której stałem się sługą według daru łaski Bożej, która mi jest dana według skutku mocy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Mnie mówię, najmniejszemu ze wszystkich świętych dana jest ta łaska, abym między poganami opowiadał te niedościgłe bogactwa Chrystusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'A iżbym objaśnił wszystkim, jaka by była społeczność onej tajemnicy zakrytej od wieków w Bogu, który wszystko stworzył przez Jezusa Chrystusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Aby teraz przez zbór wiadoma była księstwom i mocom na niebiesiech nader rozliczna mądrość Boża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Według postanowienia wiecznego, które uczynił w Chrystusie Jezusie, Panu naszym,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'W którym mamy bezpieczność i przystęp z ufnością przez wiarę jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Przetoż proszę, abyście nie słabieli dla ucisków moich za was, co jest chwałą waszą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Dlatego skłaniam kolana swoje przed Ojcem Pana naszego Jezusa Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'Z którego się wszelka rodzina na niebie i na ziemi nazywa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Aby wam dał według bogactwa chwały swej, żebyście byli mocą utwierdzeni przez Ducha jego w wewnętrznym człowieku;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Aby Chrystus przez wiarę mieszkał w sercach waszych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'Żebyście w miłości wkorzenieni i ugruntowani będąc, mogli doścignąć ze wszystkimi świętymi, która jest szerokość i długość, i głębokość, i wysokość;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'I poznać miłość Chrystusową przewyższającą wszelką znajomość, abyście napełnieni byli wszelaką zupełnością Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'A temu, który może nade wszystko uczynić daleko obficiej niżeli prosimy albo myślimy, według onej mocy, która skuteczna jest w nas;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Temu niech będzie chwała w kościele przez Chrystusa Jezusa po wszystkie czasy na wieki wieków. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Proszę was tedy ja więzień w Panu, abyście chodzili tak, jako przystoi na powołanie, którem jesteście powołani;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Ze wszelaką pokorą i cichością, i z nieskwapliwością, znosząc jedni drugich w miłości,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Starając się, abyście zachowali jedność ducha w związce pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Jedno jest ciało i jeden duch, jako też jesteście powołani w jednej nadziei powołania waszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Jeden Pan, jedna wiara, jeden chrzest;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Jeden Bóg i Ojciec wszystkich, który jest nade wszystko i po wszystkich, i we wszystkich was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Lecz każdemu z nas dana jest łaska według miary daru Chrystusowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Dlatego Pismo mówi: Wstąpiwszy na wysokość, wiódł pojmanych więźni i dał dary ludziom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Ale to, że wstąpił, cóż jest, jedno iż pierwej był zstąpił do najniższych stron ziemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'A który zstąpił, ten jest, który i wstąpił wysoko nad wszystkie niebiosa, aby napełnił wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'I tenże dał niektóre Apostoły, a niektóre proroki, a drugie ewangielisty, drugie też pasterze i nauczyciele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Ku spojeniu świętych, ku pracy usługiwania, ku budowaniu ciała Chrystusowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'A iżbyśmy się wszyscy zeszli w jedność wiary i znajomości Syna Bożego, w męża doskonałego, w miarę zupełnego wieku Chrystusowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Abyśmy więcej nie byli dziećmi, chwiejącymi się i unoszącymi się każdym wiatrem nauki przez fortel ludzki i przez chytrość podejścia błędem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Ale szczerymi będąc w miłości, rośnijmy w onego we wszystkiem, który jest głową, to jest w Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Z którego wszystko ciało przystojnie złożone i spojone we wszystkich stawach, przez które jeden członek drugiemu posiłku dodaje przez moc, która jest w każdym członku, według miary jego, wzrost ciału należący bierze ku budowaniu samego siebie w miłości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'To tedy mówię i oświadczam się przez Pana, abyście już więcej nie postępowali, jako insi poganie postępują, w próżności umysłu swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Zaćmiony mając rozsądek, będąc oddaleni od żywota Bożego dla nieumiejętności, która w nich jest z zatwardzenia serca ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Którzy zakamieniawszy, udali się na rozpustę ku popełnianiu wszelakiej nieczystości z chciwością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Lecz wy nie takeście się nauczyli Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Jeźliście go tylko słuchali i o nim wyuczeni byli, jako jest (ta) prawda w Jezusie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'To jest, żebyście złożyli według pierwszego obcowania starego człowieka, który się psuje przez pożądliwości oszukiwające;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'I odnowili się duchem umysłu waszego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'I oblekli się w onego nowego człowieka, który według Boga stworzony jest w sprawiedliwości i w świętobliwości prawdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Przetoż złożywszy kłamstwo mówcie prawdę, każdy z bliźnim swoim; boście członkami jedni drugich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Gniewajcie się, a nie grzeszcie; słońce niech nie zachodzi na rozgniewanie wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Nie dawajcie miejsca dyjabłu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Kto kradł, niech więcej nie kradnie, ale raczej niech pracuje, robiąc rękoma, co jest dobrego, aby miał skąd udzielać potrzebującemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Żadna mowa plugawa niech z ust waszych nie pochodzi; ale jeźli która jest dobra ku potrzebnemu zbudowaniu, aby była przyjemna słuchającym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'A nie zasmucajcie Ducha Świętego Bożego, którym zapieczętowani jesteście na dzień odkupienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Wszelka gorzkość i zapalczywość, i gniew, i wrzask, i bluźnierstwo, niech będzie odjęte od was, ze wszelaką złością;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'A bądźcie jedni przeciwko drugim dobrotliwi, miłosierni, odpuszczając sobie, jako wam Bóg w Chrystusie odpuścił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Bądźcież tedy naśladowcami Bożymi, jako dzieci miłe;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'A chodźcie w miłości, jako i Chrystus umiłował nas i wydał samego siebie na ofiarę i na zabicie Bogu ku wdzięcznej wonności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'A wszeteczeństwo i wszelka nieczystość albo łakomstwo niechaj nie będzie ani mianowane między wami, jako przystoi na świętych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Także sprośność i błazeńskie mowy, i żarty, które nie przystoją, ale raczej dziękowanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Bo to wiecie, iż żaden wszetecznik, albo nieczysty, albo łakomca, (który jest bałwochwalcą), nie ma dziedzictwa w królestwie Chrystusowem i Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Niechaj was nikt nie zwodzi próżnemi mowami; albowiem dla tych rzeczy przychodzi gniew Boży na synów upornych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Nie bądźcież tedy uczestnikami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Albowiemeście byli niekiedy ciemnością; aleście teraz światłością w Panu; chodźcież jako dziatki światłości,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(Bo owoc Ducha zależy we wszelakiej dobrotliwości i w sprawiedliwości i w prawdzie.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Obierając to, co by się podobało Panu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'A nie spółkujcie z uczynkami niepożytecznemi ciemności, ale je raczej strofujcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Albowiem co się potajemnie od nich dzieje, sromota i mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Lecz to wszystko, gdy bywa od światłości strofowane, bywa objawione; albowiem to wszystko, co bywa objawione, jest światłością;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Dlatego mówi Pismo: Ocuć się, który śpisz i powstań od umarłych, a oświeci cię Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Patrzajcie tedy, jakobyście ostrożnie chodzili, nie jako niemądrzy, ale jako mądrzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Czas odkupując; bo dni złe są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Przetoż nie bądźcie nierozumnymi, ale zrozumiewającymi, która jest wola Pańska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'A nie upijajcie się winem, w którem jest rozpusta; ale bądźcie napełnieni duchem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Rozmawiając z sobą przez psalmy i hymny, i pieśni duchowne, śpiewając i grając w sercu swojem Panu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Dzięki czyniąc zawsze za wszystko, w imieniu Pana naszego, Jezusa Chrystusa, Bogu i Ojcu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Będąc poddani jedni drugim w bojaźni Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Żony! bądźcie poddane mężom swoim, jako Panu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Albowiem mąż jest głową żony, jako i Chrystus głową kościoła; a on jest zbawicielem ciała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Jako tedy kościół poddany jest Chrystusowi, tak też żony mężom swoim we wszystkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Mężowie! miłujcie żony wasze, jako i Chrystus umiłował kościół i wydał samego siebie za niego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Aby go poświęcił, oczyściwszy omyciem wody przez słowo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'Aby go sobie wystawił chwalebnym kościołem, nie mającym zmazy albo zmarszczku, albo czego takiego, ale iżby był święty i bez nagany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Tak powinni mężowie miłować żony swoje, jako swoje własne ciała; kto miłuje żonę swoję, samego siebie miłuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Albowiem żaden nigdy ciała swego nie miał w nienawiści, ale je żywi i ogrzewa, jako i Pan kościół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Gdyżeśmy członkami ciała jego, z ciała jego i z kości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Dlatego opuści człowiek ojca swego i matkę, i przyłączy się do żony swojej, i będą dwoje jednem ciałem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Tajemnica to wielka jest; lecz ja mówię o Chrystusie i o kościele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'A wszakże i każdy z was z osobna niechaj miłuje żonę swoję jako siebie samego, a żona niech się boi męża swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Dziatki! bądźcie posłuszne rodzicom waszym w Panu; boć to jest sprawiedliwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Czcij ojca twego i matkę (toć jest pierwsze przykazanie z obietnicą).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Aby ci się dobrze działo i abyś długo żył na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'A wy ojcowie! nie pobudzajcie do gniewu dziatek waszych, ale je wychowujcie w karności i w napominaniu Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Słudzy! posłuszni bądźcie panom według ciała, z bojaźnią i ze drżeniem w prostości serca waszego, jako Chrystusowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Nie na oko służąc, jako ci, którzy się ludziom podobać chcą, ale jako słudzy Chrystusowi, czyniąc z duszy wolę Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Z dobrą wolą służąc jako Panu a nie ludziom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Wiedząc, iż każdy, co by uczynił dobrego, za to odniesie nagrodę od Pana, choć niewolnik, choć wolny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'A wy panowie! także się zachowujcie przeciwko nim, odpuszczając groźby, wiedząc, że i wy sami macie Pana w niebiesiech, a względu na osoby u niego nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Na ostatek, bracia moi! zmacniajcie się w Panu i w sile mocy jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Obleczcie się w zupełną zbroję Bożą, abyście mogli stać przeciwko zasadzkom dyjabelskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Albowiem nie mamy boju przeciwko krwi i ciału, ale przeciwko księstwom, przeciwko zwierzchnościom, przeciwko dzierżawcom świata ciemności wieku tego, przeciwko duchownym złościom, które są wysoko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'A przetoż weźmijcie zupełną zbroję Bożą, abyście mogli dać odpór w dzień zły, a wszystko wykonawszy, ostać się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Stójcież tedy, przepasawszy biodra wasze prawdą i oblekłszy pancerz sprawiedliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'I obuwszy nogi w gotowość Ewangielii pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'A nade wszystko wziąwszy tarczę wiary, którą byście mogli wszystkie strzały ogniste onego złośnika zagasić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Przyłbicę też zbawienia weźmijcie i miecz Ducha, który jest słowo Boże!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'W każdej modlitwie i w prośbie modląc się na każdy czas w duchu, i około tego czując ze wszelką ustawicznością i z prośbą za wszystkich świętych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'I za mię, aby mi była dana mowa ku otworzeniu ust moich z bezpieczeństwem, abym oznajmiał tajemnicę Ewangielii,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'Dla której poselstwo sprawuję w łańcuchu, abym w nim bezpiecznie mówił, jako mi mówić potrzeba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'A iżbyście wiedzieli i wy, co się ze mną dzieje i co czynię, wszystko wam oznajmi Tychykus, brat miły i wierny sługa w Panu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Któregom posłał do was dla tego samego, abyście wiedzieli, co się z nami dzieje i aby pocieszył serca wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Pokój niech będzie braciom i miłość z wiarą od Boga Ojca i Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Łaska niech będzie ze wszystkimi miłującymi Pana naszego, Jezusa Chrystusa ku nieskazitelności. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paweł i Tymoteusz, słudzy Jezusa Chrystusa, wszystkim świętym w Chrystusie Jezusie, którzy są w mieście Filipis, z biskupami i z dyjakonami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Łaska wam i pokój niech będzie od Boga, Ojca naszego, i od Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Dziękuję Bogu memu, ilekroć na was wspominam,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, '(Zawsze w każdej modlitwie mojej za wszystkich was z radością prośbę czyniąc).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Za społeczność waszę w Ewangielii, od pierwszego dnia aż dotąd;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Pewien tego będąc, iż ten, który począł w was dobrą sprawę, dokona aż do dnia Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Jakoż sprwiedliwa jest, abym ja to rozumiał o was wszystkich, dlatego iż was mam w sercu mojem i w więzieniu mojem, i w obronie, i w utwierdzeniu Ewangielii, was, mówię, wszystkich, którzy jesteście ze mną uczestnikami łaski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Albowiem świadkiem mi jest Bóg, jako was wszystkich pragnę we wnętrznościach Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'I o to się modlę, aby miłość wasza im dalej tem więcej pomnażała się w znajomości i we wszelkim zmyśle,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Abyście mogli rozeznać rzeczy różne, żebyście byli szczerymi i bez obrażenia na dzień Chrystusowy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Będąc napełnieni owocami sprawiedliwości, które przynosicie przez Jezusa Chrystusa ku sławie i chwale Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'A chcę, bracia! abyście wiedzieli, iż to, co się ze mną dzieje, na większe pomnożenie Ewangielii wyszło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Tak iż związki moje dla Chrystusa rozgłoszone są po wszystkim pałacu cesarskim i u wszystkich inszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'A wiele ich z braci w Panu serca nabywszy z moich związek, śmielszymi są, bez bojaźni mówić słowo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Wszakże niektórzy z zazdrości i z sporu, a niektórzy też z dobrej woli Chrystusa każą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'A ci, którzy z sporu Chrystusa opowiadają nieszczerze, mniemają, iż przydawają ucisku związkom moim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'A którzy z miłości, wiedzą, żem jest wystawiony ku obronie Ewangielii,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Ale cóż na tem? Owszem jakimkolwiek sposobem, lub postawnie, lub w prawdzie Chrystus bywa opowiadany, i z tego się raduję, i jeszcze się radować będę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Gdyż wiem, iż mi to wynijdzie na zbawienie przez modlitwę waszę i pomoc Ducha Jezusa Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Według troskliwego oczekiwania i nadziei mojej, iż się w niczem nie zawstydzę; ale z wszelakiem bezpieczeństwem, jako zawsze, tak i teraz, uwielbionym będzie Chrystus w ciele mojem, lub przez żywot, lub przez śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Albowiem mnie życiem jest Chrystus, a umrzeć zysk.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'A jeźliż żyć w ciele jest mi to owocem pracy mojej, jednak nie wiem, co bym obrać miał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Albowiem jestem ściśniony od tego obojga, pragnąc być rozwiązany, a być z Chrystusem, bo to daleko lepiej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Ale zostać w ciele potrzebniej jest dla was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'A będąc tego pewien, wiem, iż zostanę i z wami wszystkimi pomieszkam ku waszemu pomnożeniu i weselu wiary,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Aby obfitowała chluba wasza w Chrystusie Jezusie ze mnie, gdy do was zasię przybędę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Tylko się tak sprawujcie, jako przystoi Ewangielii Chrystusowej, abym, lub przyjdę i oglądam was, lub nie przyjdę, słyszał o was, iż stoicie w jednym duchu, jednomyślnie bojując w wierze Ewangielii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'Ani w czem nie strachając się przeciwników, co onym jest pewnym znakiem zginienia, a wam zbawienia, a to od Boga;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Gdyż wam to dane dla Chrystusa, abyście nie tylko weń wierzyli, ale abyście też dla niego cierpieli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Tenże bój mając, jakiście widzieli we mnie, i jaki teraz o mnie słyszycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Jeźli tedy macie jaką pociechę w Chrystusie, jeźli jaką uciechę miłości, jeźli jaką społeczność ducha, jeźli są jakie wnętrzności i zlitowania w was,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'Dopełnijcież wesela mojego, abyście jednoż rozumieli, jednostajną miłość mając, będąc jednomyślni i jednoż rozumiejący;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Nic nie czyniąc spornie, albo przez próżną chwałę, ale w pokorze jedni drugich mając za wyższych nad się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Nie upatrujcie każdy tylko, co jest jego, ale każdy też, co jest drugich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Tego tedy bądźcie o sobie rozumienia, które było i w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Który, będąc w kształcie Bożym, nie poczytał sobie tego za drapiestwo równym być Bogu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Ale wyniszczył samego siebie, przyjąwszy kształt niewolnika, stawszy się podobny ludziom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'I postawą znaleziony jako człowiek, sam się poniżył, będąc posłusznym aż do śmierci, a to śmierci krzyżowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Dlatego też Bóg nader go wywyższył i darował mu imię, które jest nad wszystkie imię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Aby w imieniu Jezusowem wszelkie się kolano skłaniało, tych, którzy są na niebiesiech i tych, którzy są na ziemi, i tych, którzy są pod ziemią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'A wszelki język aby wyznawał, że Jezus Chrystus jest Panem ku chwale Boga Ojca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Przetoż, moi mili! jakoście zawsze posłuszni byli, nie tylko w przytomności mojej, ale teraz daleko więcej w niebytności mojej, z bojaźnią i ze drżeniem zbawienie swoje sprawujcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Albowiem Bóg jest, który sprawuje w was chcenie i skuteczne wykonanie według upodobania swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Wszystko czyńcie bez szemrania i poswarków,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'Abyście byli bez nagany i szczeremi dziatkami Bożemi, nienaganionymi w pośrodku narodu złego i przewrotnego, między którymi świecicie jako światła na świecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Zachowywując słowa żywota ku chlubie mojej w dzień Chrystusowy, żem darmo nie bieżał i darmo nie pracował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Ale choćbym ofiarowany był dla ofiary i usługi wiary waszej, weselę się i spółweselę się ze wszystkimi wami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Z tegoż tedy i wy weselcie się i spółweselcie się ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'A mam nadzieję w Panu Jezusie, iż Tymoteusza w rychle poślę do was, abym się i ja ucieszył, dowiedziawszy się, co się z wami dzieje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Albowiem nie mam nikogo w umyśle jemu równego, który by się uprzejmie o rzeczy wasze starać chciał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Bo wszyscy swoich rzeczy szukają, a nie tych, które są Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Ale wiecie, iż on jest doświadczonym, a iż jako syn z ojcem ze mną służył w Ewangielii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Mam tedy nadzieję, że tego do was poślę, skoro obaczę, co się ze mną dalej dziać będzie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'A mam ufność w Panu, że i sam w rychle do was przyjdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Alem rozumiał rzeczą potrzebną, Epafrodyta, brata i pomocnika i spółbojownika mego, a waszego Apostoła i sługę w potrzebie mojej, posłać do was,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Ponieważ pragnął was wszystkich i bardzo się frasował, żeście słyszeli, iż zachorował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Bo wprawdzie chorował mało nie na śmierć; ale się Bóg zmiłował nad nim, a nie tylko nad nim, ale i nade mną, abym nie miał smutku na smutek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Przetoż tem ochotniej posłałem go, abyście zasię ujrzawszy go, uweselili się, a ja abym miał mniej smutku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Przyjmijcież go tedy w Panu ze wszystkiem weselem; a takich w poczciwości miejcie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Boć dla dzieła Chrystusowego bliskim był śmierci, odważywszy zdrowie swoje, aby dopełnił tego, czego nie dostawało w usłudze waszej przeciwko mnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Dalej mówiąc, bracia moi! radujcie się w Panu. Jedneż rzeczy wam pisać mnie nie mierzi, a wam jest bezpiecznie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Upatrujcie psy, upatrujcie złych robotników, upatrujcie rozerwanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Albowiem my jesteśmy obrzezaniem, którzy duchem służymy Bogu i chlubimy się w Chrystusie Jezusie, a w ciele nie ufamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Aczci i ja w ciele mam ufanie; jeźli kto inszy zda się mieć ufanie w ciele, bardziej ja,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Obrzezany będąc ósmego dnia, z narodu Izraelskiego, z pokolenia Benjaminowego, Żyd z Żydów, według zakonu Faryzeusz;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'Według gorliwości prześladowca kościoła, według sprawiedliwości onej, która jest z zakonu, będąc bez przygany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Ale to, co mi było zyskiem, tom poczytał dla Chrystusa za szkodę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Owszem i wszystko poczytam sobie za szkodę dla zacności znajomości Chrystusa Jezusa, Pana mojego, dla któregom wszystko utracił i mam to sobie za gnój, abym Chrystusa zyskał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'I był znaleziony w nim, nie mając sprawiedliwości mojej, tej która jest z zakonu, ale tę, która jest przez wiarę Chrystusową, to jest sprawiedliwość z Boga, która jest przez wiarę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Żebym go poznał i moc zmartwychwstania jego, i społeczność ucierpienia jego, przykształtowany będąc śmierci jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Owabym jakimkolwiek sposobem doszedł do powstania z martwych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Nie iżbym już uchwycił, albo już doskonałym był; ale ścigam, ażbym też uchwycił to, na com też od Chrystusa Jezusa uchwycony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Bracia! jać o sobie nie rozumiem, żebym już uchwycił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Ale jedno czynię, że tego, co za mną jest, zapamiętywając, a do tego się, co przede mną jest, spiesząc, bieżę do kresu ku zakładowi powołania onego Bożego, które jest z góry w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Ile tedy nas doskonałych, toż rozumiejmy; a jeźli co inaczej rozumiecie, i toć wam Bóg objawi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Wszakże w tem, czegośmy doszli, według jednegoż sznuru postępujmy i jednoż rozumiejmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Bądźcież wespół naśladowcami moimi, bracia! a upatrujcie tych, którzy tak chodzą, jako nas za wzór macie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Albowiem wiele ich chodzi, o którychem wam często powiadał, a teraz i z płaczem mówię, iż są nieprzyjaciołmi krzyża Chrystusowego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Których koniec jest zatracenie, których Bóg jest brzuch, a chwała w hańbie ich, którzy się o rzeczy ziemskie starają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Aleć nasza rzeczpospolita jest w niebiesiech, skąd też zbawiciela oczekujemy, Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Który przemieni ciało nasze podłe, aby się podobne stało chwalebnemu ciału jego, według skutecznej mocy, którą też wszystkie rzeczy sobie podbić może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Przetoż, bracia moi mili i pożądani! radości i korono moja! tak stójcie w Panu, najmilsi moi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Ewodyi proszę i Syntychy proszę, aby jednegoż rozumienia były w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Proszę też i cię, towarzyszu wierny! bądź tym na pomoc, które w Ewangielii wespół ze mną pracowały, i z Klemensem i z innymi pomocnikami moimi, których imiona są w księgach żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Radujcie się zawsze w Panu; znowu mówię, radujcie się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Skromność wasza niech będzie wiadoma wszystkim ludziom; Pan blisko jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Nie troszczcie się o żadną rzecz, ale we wszystkiem przez modlitwę i prośbę z dziękowaniem żądności wasze niech będą znajome u Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'A pokój Boży, który przewyższa wszelki rozum, będzie strzegł serc waszych i myśli waszych w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'A dalej mówiąc, bracia, cokolwiek jest prawdziwego, cokolwiek poczciwego, cokolwiek sprawiedliwego, cokolwiek czystego, cokolwiek przyjemnego, cokolwiek chwalebnego, jeźli która cnota i jeźli która chwała, o tem przemyślajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Czegoście się też nauczyli i coście przyjęli, i słyszeli, i widzieli przy mnie, to czyńcie, a Bóg pokoju będzie z wami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'A uradowałem się wielce w Panu, żeście się już wżdy znowu zazielenili w swojem staraniu o mię, jakoż i staraliście się o to, lecz wam na sposobnym czasie schodziło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Nie żebym to mówił dla niedostatku; bomci się ja nauczył, na tem przestawać, co mam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Umiem i uniżać się, umiem i obfitować; wszędy i we wszystkich rzeczach jestem wyćwiczony i nasyconym być, i łaknąć, i obfitować, i niedostatek cierpieć;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Wszystko mogę w Chrystusie, który mię posila.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Wszakże dobrzeście uczynili, żeście społecznie dogodzili uciskowi mojemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'A wiecie i wy Filipensowie, iż na początku Ewangielii, gdym wyszedł z Macedonii, żaden mi zbór nie udzielił na rachunek dawania i brania, tylko wy sami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Ponieważ i do Tesaloniki raz i drugi, czego potrzeba było, posłaliście mi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Nie przeto, żebym datku szukał; ale szukam pożytku, który by obfitował na rachunku waszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Gdyżem odebrał wszystko i mam dostatek, pełenem, wziąwszy od Epafrodyta, co posłano od was, wonność dobrego zapachu, ofiarę przyjemną i Bogu się podobającą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'A Bóg mój napełni wszelką potrzebę waszę według bogactwa swego, chwalebnie, w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'A Bogu i Ojcu naszemu niech będzie chwała na wieki wieków. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Pozdrówcie wszystkich świętych w Chrystusie Jezusie. Pozdrawiają was bracia, którzy są ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Pozdrawiają was wszyscy święci; ale osobliwie, którzy są z cesarskiego domu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Łaska Pana naszego Jezusa Chrystusa niech będzie z wami wszystkimi. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paweł, Apostoł Jezusa Chrystusa przez wolę Bożą, i Tymoteusz brat,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'Tym, którzy są w Kolosiech, świętym i wiernym braciom w Chrystusie Jezusie. Łaska wam i pokój niech będzie od Boga, Ojca naszego, i od Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Dziękujemy Bogu i Ojcu Pana naszego Jezusa Chrystusa, zawsze modląc się za was,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Usłyszawszy o wierze waszej w Chrystusie Jezusie i miłości przeciwko wszystkim świętym,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'Dla nadziei onej wam odłożonej w niebiesiech, o którejście przedtem słyszeli przez słowo prawdy, to jest Ewangielii,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Która przyszła do was jako i na wszystek świat, i przynosi owoc, jako i u was, od onego dnia, któregoście usłyszeli i poznali łaskę Bożą w prawdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Jakoście się też nauczyli od Epafry, miłego spółsługi naszego, który jest wiernym sługą Chrystusowym dla was;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Który też oznajmił nam miłość waszę w duchu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Dlatego i my od onego dnia, któregośmy to usłyszeli, nie przestajemy się za was modlić i prosić, abyście byli napełnieni znajomością woli jego we wszelkiej mądrości i w wyrozumieniu duchownem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Abyście chodzili przystojnie przed Panem ku wszelkiemu jego upodobaniu, w każdym uczynku dobrym owoc przynosząc i rosnąc w znajomości Bożej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Wszelką mocą umocnieni będąc według chwalebnej mocy jego, ku wszelkiej cierpliwości i nieskwapliwości z radością,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Dziękując Ojcu, który nas godnymi uczynił, abyśmy byli uczestnikami dziedzictwa świętych w światłości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Który nas wyrwał z mocy ciemności i przeniósł do królestwa Syna swego miłego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'W którym mamy odkupienie przez krew jego, to jest odpuszczenie grzechów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Który jest obrazem Boga niewidzialnego i pierworodny wszystkich rzeczy stworzonych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Albowiem przezeń stworzone są wszystkie rzeczy, które są na niebie i na ziemi, widzialne i niewidzialne, bądź trony, bądź państwa, bądź księstwa, bądź zwierzchności, wszystko przezeń i dla niego stworzone jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'A on jest przed wszystkimi i wszystko w nim stoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'On też jest głową ciała, to jest kościoła, który jest początkiem i pierworodnym z umarłych, aby on między wszystkimi przodkował;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Ponieważ się upodobało Ojcu, aby w nim wszystka zupełność mieszkała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'I żeby przezeń z sobą pojednał wszystko, uczyniwszy pokój przez krew krzyża jego; przezeń, mówię, tak to, co jest na ziemi, jako i to, co jest na niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'I was, którzyście niekiedy byli oddaleni i nieprzyjaciele umysłem w złośliwych uczynkach, teraz też pojednał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Ciałem własnem swojem przez śmierć, aby was wystawił świętemi i niepokalanemi, i bez nagany przed obliczem swojem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'Jeźli tylko trwacie w wierze ugruntowani i utwierdzeni, a nie poruszeni od nadziei Ewangielii, którąście słyszeli, która jest kazana wszelkiemu stworzeniu, które jest pod niebem, której ja Paweł stałem się sługą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Który się teraz raduję w doległościach moich dla was i dopełniam ostatków ucisków Chrystusowych na ciele mojem za ciało jego, które jest kościół.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Któregom się ja stał sługą według daru Bożego, który mi jest dany dla was, abym wypełnił słowo Boże,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'To jest, tajemnicę onę, która była zakryta od wieków i od rodzajów, ale teraz objawiona jest świętym jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Którym chciał Bóg oznajmić, jakie jest bogactwo tej tajemnicy chwalebnej między poganami, która jest Chrystus między wami, nadzieja ona chwały;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Którego my opowiadamy, napominając każdego człowieka i ucząc każdego człowieka we wszelkiej mądrości, abyśmy wystawili każdego człowieka doskonałym w Chrystusie Jezusie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'W czem też pracuję, bojując według skutecznej mocy jego, która we mnie dzieło swoje potężnie sprawuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Albowiem chcę, abyście wiedzieli jako wielką trudność mam o was i o tych, którzy są w Laodycei i którzykolwiek nie widzieli oblicza mego w ciele;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'Aby pocieszone były serca ich, będąc spojone miłością, a to ku wszelkiemu bogactwu zupełnego i pewnego wyrozumienia, ku poznaniu tajemnicy Boga i Ojca, i Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'W którym skryte są wszystkie skarby mądrości i umiejętności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'A toć mówię, aby was nikt fałszywemi dowodami nie oszukał przez wystawną mowę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Bo aczkolwiek nie jestem obecny ciałem, ale duchem jestem z wami, radując się i widząc porządek wasz i utwierdzenie wiary waszej w Chrystusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Przetoż jakoście przyjęli Pana Jezusa Chrystusa, tak w nim chodźcie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Będąc wkorzenieni i wybudowani na nim, i utwierdzeni w wierze, jakoście się nauczyli, obfitując w niej z dziękowaniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Patrzcież, żeby was kto sobie w korzyść nie obrócił przez filozofiję i przez próżne oszukanie, ucząc według ustawy ludzkiej, według żywiołów świata, a nie według Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Gdyż w nim mieszka wszystka zupełność bóstwa cieleśnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'I jesteście w nim dopełnieni, który jest głową wszelkiego księstwa i zwierzchności,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'W którym i obrzezani jesteście obrzezką nie ręką uczynioną, to jest, zewlekłszy ciało wszystkich grzechów ciała przez obrzezkę Chrystusową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'Pogrzebieni z nim będąc w chrzcie; w którymeście też społem z nim wzbudzeni przez wiarę, którą sprawuje Bóg, który go wzbudził od umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'I was, gdyście byli umarłymi w grzechach i nieobrzezce ciała waszego, wespół z nim ożywił, odpuściwszy wam wszystkie grzechy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Zmazawszy on, który był przeciwko nam, cyrograf w ustawach zależący, który nam był przeciwny, zniósł go z pośrodku, przybiwszy go do krzyża;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'I złupiwszy księstwa i mocy, wiódł je na podziw, jawnie tryumfując z nich sam przez się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Niechajże was tedy nikt nie sądzi dla pokarmu, albo dla napoju; albo z strony święta, albo nowiu miesiąca, albo sabatów,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Które są cieniem rzeczy przyszłych, ale prawdą jest ciało Chrystusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Niechaj was nikt wygranego zakładu nie osądza, który się dobrowolnie w pokorę i w służbę Aniołów, których nie widział, wdaje, próżno się nadymając z umysłu ciała swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'A nie trzymając się głowy Chrystusa, z którego wszystko ciało przez stawy i związania posiłek biorąc i wespół spojone będąc, rośnie wzrostem Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Jeźliście tedy umarli z Chrystusem żywiołom świata tego, przeczże się, jakobyście jeszcze żyli światu, ustawami bawicie?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Mówią niektórzy: Nie dotykaj się, ani kosztuj, ani ruszaj;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Co wszystko kazi się samem używaniem, według przykazań i nauk ludzkich;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Które mają kształt mądrości w nabożeństwie dobrowolnie obranem i w pokorze, i w niefolgowaniu ciału; wszakże nie mają żadnej wagi, tylko do nasycenia ciała służą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'A tak jeźliście powstali z Chrystusem, tego, co jest w górze, szukajcie, gdzie Chrystus na prawicy Bożej siedzi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'O tem, co jest w górze, myślcie, nie o tem, co jest na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Albowiemeście umarli i żywot wasz skryty jest z Chrystusem w Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Ale gdy się Chrystus, on żywot nasz, pokaże, tedy i wy z nim okażecie się w chwale.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Umartwiajcież tedy członki wasze, które są na ziemi; wszeteczeństwo, nieczystość, namiętność, złą pożądliwość i łakomstwo, które jest bałwochwalstwem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'Dla których rzeczy przychodzi gniew Boży na syny odporne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'W którycheście i wy niekiedy chodzili, gdyście żyli w nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Lecz teraz złóżcie i wy to wszystko: gniew, zapalczywość, złość, bluźnierstwo i sprośną mowę z ust waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Nie kłamcie jedni przeciwko drugim, gdyżeście zewlekli człowieka starego z uczynkami jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'A oblekliście nowego tego, który się odnawia w znajomość, podług obrazu tego, który go stworzył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Gdzie nie masz Greka i Żyda, obrzezki i nieobrzezki, cudzoziemca i Tatarzyna, niewolnika i wolnego; ale wszystko i we wszystkich Chrystus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Przetoż przyobleczcie jako wybrani Boży, święci i umiłowani, wnętrzności miłosierdzia, dobrotliwość, pokorę, cichość, cierpliwość,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Znaszając jedni drugich i odpuszczając sobie wzajemnie, jeźli ma kto przeciw komu skargę: jako i Chrystus odpuścił wam, tak i wy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'A nad to wszystko (przyobleczcie) miłość, która jest związką doskonałości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'A pokój Boży niech rząd prowadzi w sercach waszych, do któregoście też powołani w jedno ciało; a bądźcie wdzięcznymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Słowo Chrystusowe niechaj mieszka w was obficie ze wszelką mądrością, nauczając i napominając samych siebie przez psalmy i hymny, i pieśni duchowne, wdzięcznie śpiewając w sercach waszych Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'A wszystko, cokolwiek czynicie w słowie albo w uczynku, wszystko czyńcie w imieniu Pana Jezusa, dziękując Bogu i Ojcu przezeń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Żony! Bądźcie poddane mężom swym, tak jako przystoi w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Mężowie! Miłujcie żony wasze, a nie bądźcie surowymi przeciwko nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Dziatki! Posłuszne bądźcie rodzicom we wszystkiem; albowiem się to podoba Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Ojcowie! Nie pobudzajcie do gniewu dzieci waszych, aby serca nie traciły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Słudzy! Posłuszni bądźcie we wszystkiem panom cielesnym, nie służąc na oko jako ci, co się ludziom podobać chcą, ale w szczerości serca, bojąc się Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'A wszystko, cokolwiek czynicie, z duszy czyńcie, jako Panu, a nie ludziom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Wiedząc, iż od Pana weźmiecie zapłatę dziedzictwa; albowiem Panu Chrystusowi służycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'A ten, co krzywdę czyni, odniesie zapłatę ukrzywdzenia, a nie maszci względu na osoby u Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Panowie! Sprawiedliwie i słusznie się z sługami obchodźcie, wiedząc, iż i wy Pana macie w niebiesiech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'W modlitwach trwajcie, czując w nich z dziękowaniem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Modląc się społecznie i za nami, aby nam Bóg otworzył drzwi słowa, żebyśmy mówili o tajemnicy Chrystusowej dla której też jestem związany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Abym ją objawił, jako mi się godzi mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Mądrze chodźcie przed obcymi, czas odkupując.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Mowa wasza niech zawsze będzie przyjemna, solą okraszona, abyście wiedzieli, jakobyście każdemu z osobna odpowiedzieć mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'O wszystkiem, co się ze mną dzieje oznajmi wam Tychykus, miły brat i wierny sługa, i spółsługa w Panu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Któregom posłał do was dla tego samego, aby się wywiedział, co się z wami dzieje i pocieszył serca wasze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Z Onezymem, wiernym a miłym bratem, który jest z was; ci wam wszystko oznajmią, co się tu dzieje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Pozdrawia was Arystarchus spółwięzień mój i Marek, siostrzeniec Barnabaszowy, (o któremeście wzięli rozkazanie: Jeźliby do was przyszedł, przyjmijcież go.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'I Jezus, którego zowią Justem, którzy są z obrzezki. Ci tylko są pomocnikami moimi w królestwie Bożem, którzy byli pociechą moją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Pozdrawia was Epafras, który z was jest sługa Chrystusowy, który zawsze bojuje za was w modlitwach, abyście stali doskonałymi i zupełnymi we wszelkiej woli Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Bo mu daję świadectwo, iż gorliwą miłość ma przeciwko wam i przeciwko tym, którzy są w Laodycei i którzy są w Hijerapolu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Pozdrawia was Łukasz, lekarz miły, także i Demas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Pozdrówcie braci, którzy są w Laodycei, i Nymfasa, i zbór, który jest w domu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'A gdy ten list u was przeczytany będzie, sprawcie to, aby też był w Laodyceńskim zborze przeczytany; a ten, który jest pisany z Laodycei i wy też przeczytajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'A powiedzcie Archipowi: Patrzaj na to posługiwanie, któreś przyjął w Panu, abyś je wypełnił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Pozdrowienie ręką moją Pawłową. Pamiętajcie na więzienie moje. Łaska niech będzie z wami. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paweł i Sylwan, i Tymoteusz zborowi Tesaloniceńskiemu w Bogu Ojcu i w Panu Jezusie Chrystusie. Łaska wam i pokój niech będzie od Boga Ojca naszego, i od Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Dziękujemy Bogu zawsze za was wszystkich, wzmiankę czyniąc o was w modlitwach naszych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Bez przestanku przypominając skuteczną onę wiarę waszę i onę pracowitą miłość, i onę cierpliwą nadzieję w Panu naszym, Jezusie Chrystusie, przed Bogiem i Ojcem naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Wiedząc, bracia umiłowani od Boga, wybranie wasze,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Gdyż Ewangielija nasza nie była u was tylko w mowie, ale też w mocy i w Duchu Świętym, i we wszelkiem upewnieniu, jako wiecie, jakimyśmy byli między wami dla was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'A wyście się naśladowcami naszymi i Pańskimi stali, przyjąwszy słowo we wszelkiem uciśnieniu z radością Ducha Świętego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Tak żeście się wy stali za wzór wszystkim wierzącym w Macedonii i w Achai.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Albowiem od was się rozgłosiło słowo Pańskie, nie tylko w Macedonii i w Achai, ale się też rozeszła na wszelkie miejsce wiara wasza, która jest w Bogu, tak iż nam nie trzeba, o tem co mówić;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Ponieważ oni sami oznajmują o was, jakie było przyjście nasze do was i jakoście się nawrócili do Boga od bałwanów, abyście służyli Bogu żywemu i prawdziwemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'I oczekiwali Syna jego z niebios, którego wzbudził od umarłych, to jest Jezusa, który nas wyrwał od gniewu przyszłego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Albowiem wy sami wiecie, bracia! że przyjście nasze do was nie było próżne;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Ale chociażeśmy i przedtem cierpieli, i zelżeni byli (jako wiecie) w mieście Filipach, wszakże bezpiecznieśmy sobie poczęli w Bogu naszym, w opowiadaniu u was Ewangielii Bożej z wielkim bojem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Albowiem napominanie nasze nie było z oszukania, ani z nieczystości, ani z zdrady;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Ale jako nas Bóg sobie upodobał, żeby nam była zwierzona Ewangielija, tak mówimy, nie jako ludziom się podobając, ale Bogu, który sobie upodobywa serca nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Albowiem nigdyśmy nie używali mowy pochlebnej, jako wiecie; aniśmy pod zasłoną czego łakomstwu dogadzali; Bóg jest świadkiem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Aniśmy szukali od ludzi chwały, ani od was, ani od inszych, mogąc wam być ciężkimi, jako Apostołowie Chrystusowi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Aleśmy byli skromnymi między wami, jako gdy mamka odchowuje dziatki swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Tak wam życzliwymi będąc, gotowiśmy byli użyczyć wam nie tylko Ewangielii Bożej, ale też i dusz naszych, dlatego iżeście nam miłymi byli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Albowiem pamiętajcie, bracia! pracę naszę i trudy, gdyż w nocy i we dnie robiąc, abyśmy żadnego z was nie obciążyli, kazaliśmy u was Ewangielię Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Wyście świadkami i Bóg, żeśmy świętobliwie i sprawiedliwie, i bez nagany żyli między wami, którzyście uwierzyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Jakoż wiecie, żeśmy każdego z was, jako ojciec dziatki swoje, napominali i cieszyli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'I oświadczali się, abyście chodzili godnie Bogu, który was powołał do swego królestwa i do chwały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Przetoż i my dziękujemy Bogu bez przestanku, iż przyjąwszy słowo Boże, któreście słyszeli od nas, przyjęliście nie jako słowo ludzkie, ale (jako w prawdzie jest) jako słowo Boże, które też skuteczne jest w was, którzy wierzycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Albowiem wy, bracia! staliście się naśladowcami zborów Bożych, które są w żydowskiej ziemi, w Chrystusie Jezusie; boście i wy też cierpieli od ziomków waszych, jako i oni od Żydów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Którzy i Pana Jezusa zabili, i swoich własnych proroków, i nas wygnali, a Bogu się nie podobają, i wszystkim ludziom są przeciwni,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'Zabraniając nam, żebyśmy nie mówili poganom, żeby byli zbawieni, aby tak zawsze dopełniali grzechów swoich; albowiem przyszedł na nich gniew aż do końca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Lecz my, bracia! będąc pozbawieni was na chwileczkę obliczem, nie sercem, tem pilniejśmy się starali oglądać oblicze wasze z wielką żądnością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Dlategośmy chcieli przyjść do was (zwłaszcza ja Paweł) i raz, i drugi; ale nam przekaził szatan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Albowiem któraż jest nadzieja nasza, albo radość, albo korona chluby? Izali nie wy przed oblicznością Pana naszego, Jezusa Chrystusa w przyjście jego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Wy zaiste jesteście chwałą naszą i radością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Przeto nie mogąc dłużej znosić, upodobało się nam, abyśmy sami w Atenach zostali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'I posłaliśmy Tymoteusza, brata naszego i sługę Bożego, i pomocnika naszego w Ewangielii Chrystusowej, aby was utwierdził i napominał z strony wiary waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Aby się żaden nie poruszał w tych uciskach; gdyż sami wiecie, żeśmy na to wystawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Albowiem gdyśmy byli u was, opowiadaliśmy wam, żeśmy mieli być uciśnieni, jakoż się też to stało, i wiecie o tem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Dlatego i ja, nie mogąc tego dłużej znosić, posłałem go, abym się dowiedział o wierze waszej, by was snać nie kusił ten, co kusi, a nie była daremna praca nasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Lecz teraz Tymoteusz od was do nas przyszedł i zwiastował nam wesołą nowinę o wierze i miłości waszej, a iż nas zawsze dobrze wspominacie, żądając nas widzieć, tak jako i my was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Dlatego pocieszeni jesteśmy, bracia! z was w każdym utrapieniu i potrzebie naszej przez wiarę waszę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Bo teraz my żyjemy, jeźli wy stoicie w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Albowiem jakież dziękowanie możemy Bogu oddać za was za wszelkie wesele, którem się weselimy dla was przed Bogiem naszym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'W nocy i we dnie bardzo się gorliwie modląc, abyśmy oglądali oblicze wasze i dopełnili niedostatków wiary waszej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Lecz sam Bóg i Ojciec nasz, i Pan nasz, Jezus Chrystus, niech wyprostuje drogę naszę do was;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'A was Pan niech pomnoży i obfitującymi uczyni w miłości jednego ku drugiemu, i ku wszystkim, jako i nas ku wam,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Aby utwierdzone były serca wasze nienaganione w świętobliwości przed Bogiem i Ojcem naszym, na przyjście Pana naszego, Jezusa Chrystusa, ze wszystkimi świętymi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'A dalej mówiąc, bracia! prosimy was i napominamy przez Pana Jezusa, jakoście przyjęli od nas, jakobyście sobie mieli postępować i Bogu się podobać, (), abyście tem więcej obfitowali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Gdyż wiecie, jakieśmy wam rozkazania dali przez Pana Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Albowiem ta jest wola Boża, to jest poświęcenie wasze, żebyście się powściągali od wszeteczeństwa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'A żeby umiał każdy z was naczyniem swojem władać w świętobliwości i w uczciwości,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Nie w namiętności żądzy, jako i poganie, którzy nie znają Boga;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'I aby nikt nie uciskał i nie oszukiwał w żadnej sprawie brata swego: bo Pan jest mścicielem tego wszystkiego, jakośmy wam przedtem powiadali i oświadczali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Bo nas nie powołał Bóg ku nieczystości, ale ku poświęceniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'A przetoż kto to odrzuca, nie odrzuca człowieka, ale Boga, który nam też dał Ducha swego Świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'A o miłości braterskiej nie potrzeba wam pisać; boście wy sami od Boga nauczeni, abyście miłowali jedni drugich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Albowiem też to czynicie przeciwko wszystkim braciom, którzy są we wszystkiej Macedonii; ale was napominamy, bracia! iżbyście tem więcej obfitowali,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'I pilnie się starali, abyście spokojnymi byli i rzeczy swoich pilnowali, i pracowali własnymi rękami swemi, jakośmy wam przykazali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'Abyście uczciwie chodzili przed obcymi, a w niczem abyście nie mieli niedostatku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'A nie chcę, bracia! abyście wiedzieć nie mieli o tych, którzy zasnęli, iżbyście się nie smucili, jako i drudzy, którzy nadziei nie mają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Albowiem jeźli wierzymy, iż Jezus umarł i zmartwychwstał, tak Bóg i tych, którzy zasnęli w Jezusie, przywiedzie z nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Boć to wam powiadamy słowem Pańskiem, że my, którzy żywi pozostaniemy do przyjścia Pańskiego, nie uprzedzimy onych, którzy zasnęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Gdyż sam Pan z okrzykiem, a głosem archanielskim i z trąbą Bożą zstąpi z nieba, a pomarli w Chrystusie powstaną najpierwej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Zatem my żywi, którzy pozostaniemy, wespół z nimi zachwyceni będziemy w obłokach naprzeciwko Panu na powietrze, a tak zawsze z Panem będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Przetoż pocieszajcie jedni drugich temi słowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'A o czasach i o chwilach, bracia! nie potrzebujecie, aby wam pisano.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Albowiem sami dostatecznie wiecie, iż on dzień Pański jako złodziej w nocy, tak przyjdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Bo gdy mówić będą: Pokój i bezpieczeństwo! tedy na nich nagłe zginienie przyjdzie, jako ból na niewiastę brzemienną, a nie ujdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Lecz wy, bracia! nie jesteście w ciemności, aby was on dzień jako złodziej zachwycił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Wszyscy wy jesteście synowie światłości i synowie dnia; nie jesteśmy synowie nocy ani ciemności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Przeto nie śpijmy jako i insi, ale czujmy i bądźmy trzeźwymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Albowiem którzy śpią, w nocy śpią, a którzy się upijają, w nocy się upijają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Lecz my synami dnia będąc, bądźmy trzeźwymi, oblekłszy się w pancerz wiary i miłości, i w przyłbicę nadziei zbawienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Gdyż Bóg nie postawił nas ku gniewu, ale ku nabyciu zbawienia przez Pana naszego, Jezusa Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Który umarł za nas, abyśmy lub czujemy, lub śpimy, wespół z nim żyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Przetoż napominajcie jedni drugich i budujcie jeden drugiego, jako i czynicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'A prosimy was, bracia! abyście poznali tych, którzy pracują między wami i którzy są przełożonymi waszymi w Panu, i napominają was;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Abyście ich jak najbardziej miłowali dla ich pracy. Pokój też zachowajcie między sobą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'A prosimy was, bracia! napominajcie tych, którzy nie stoją w rzędzie, cieszcie bojaźliwych, znaszajcie słabych, nieskwapliwymi bądźcie przeciwko wszystkim;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Patrzcie, aby kto złem za złe komu nie oddawał; ale zawsze dobrego naśladujcie, i sami między sobą i ku wszystkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Zawsze się radujcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Bez przestanku się módlcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Za wszystko dziękujcie; albowiem tać jest wola Boża w Chrystusie Jezusie przeciwko wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Ducha nie zagaszajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Proroctw nie lekceważcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Wszystkiego doświadczajcie, a co jest dobrego, tego się trzymajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Od wszelkiego podobieństwa złości się wstrzymywajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'A sam Bóg pokoju niech was zupełnie poświęci; a cały duch wasz, i dusza, i ciało niech będą bez nagany na przyjście Pana naszego, Jezusa Chrystusa, zachowane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Wiernyż jest ten, który was powołał, który też to uczyni,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Bracia! módlcie się za nami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Pozdrówcie braci wszystkich z pocałowaniem świętem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Poprzysięgam was przez Pana, aby ten list przeczytany był wszystkim braciom świętym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Łaska Pana naszego, Jezusa Chrystusa, niech będzie z wami. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paweł i Sylwan, i Tymoteusz zborowi Tesaloniceńskiemu w Bogu, Ojcu naszym, i w Panu Jezusie Chrystusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Łaska wam i pokój niech będzie od Boga, Ojca naszego, i Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Powinniśmy Bogu zawsze dziękować za was, bracia! tak jako się godzi, iż bardzo rośnie wiara wasza i pomnaża się miłość każdego z was, jednych przeciwko drugim,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Tak iż i my sami chlubimy się z was we zborach Bożych z waszej cierpliwości i wiary we wszystkich prześladowaniach waszych i w uciskach, które ponosicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Co jest jawnym dowodem sprawiedliwego sądu Bożego, abyście godnymi byli poczytani królestwa Bożego, dla którego też cierpicie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Ponieważ sprawiedliwa jest u Boga, żeby wzajem oddał uciśnienie tym, którzy was uciskają;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'A wam, którzyście uciśnieni, odpocznienie z nami przy objawieniu Pana Jezusa z nieba z Aniołami mocy jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'W ogniu płomienistym oddawając pomstę tym, którzy Boga nie znają i tym, którzy nie są posłuszni Ewangielii Pana naszego, Jezusa Chrystusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Którzy pomstę odniosą, wieczne zatracenie od obliczności Pańskiej i od chwały mocy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Gdy przyjdzie, aby był uwielbiony w świętych swoich i aby się dziwnym okazał we wszystkich wierzących (dlatego iż uwierzono naszemu świadectwu u was) w on dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Dlaczego też modlimy się zawsze za was, aby Bóg nasz godnymi was uczynił powołania tego i wypełnił wszystko upodobanie dobrotliwości swojej, i skutek wiary w mocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Aby było uwielbione imię Pana naszego, Jezusa Chrystusa w was, a wy w nim, według łaski Boga naszego i Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'A prosimy was, bracia! przez przyjście Pana naszego Jezusa Chrystusa i nasze zgromadzenie do niego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'Abyście się nie zaraz dali zrażać z zmysłu waszego, ani sobą trwożyć, lub przez ducha lub przez mowę, lub przez list, jakoby od nas pisany, jakoby nadchodził dzień Chrystusowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Niech was nikt nie zwodzi żadnym sposobem; albowiem nie przyjdzie on dzień, ażby pierwej przyszło odstąpienie i byłby objawiony człowiek on grzechu, on syn zatracenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'Który się sprzeciwia i wynosi nad to wszystko, co się zowie Bogiem, albo co ma Boską cześć, tak iż on w kościele Bożym jako Bóg usiądzie, udawając się za Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Izali nie pamiętacie, iż jeszcze z wami będąc, o temem wam powiadał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'A teraz wiecie, co przeszkadza, aby był objawiony czasu swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Albowiem się już sprawuje tajemnica nieprawości, tylko że ten, który teraz przeszkadza, przeszkadzać będzie, ażby był z pośrodku odjęty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'A tedy objawiony będzie on niezbożnik, którego Pan zabije duchem ust swoich i zniesie objawieniem przyjścia swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Którego niezbożnika przyjście jest podług skutku szatańskiego, ze wszelką mocą i znakami, i cudami kłamliwemi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'I ze wszystkiem oszukaniem nieprawości w tych, którzy giną, przeto iż miłości prawdy nie przyjęli, aby byli zbawieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'A przetoż pośle im Bóg skutek błędów, aby wierzyli kłamstwu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'Aby byli osądzeni wszyscy, którzy nie uwierzyli prawdzie, ale sobie upodobali niesprawiedliwość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Lecz my powinniśmy Bogu dziękować zawsze za was, bracia umiłowani od Pana! iż was Bóg od początku wybrał ku zbawieniu w poświęceniu Ducha i w wierze prawdy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'Do czego was powołał przez Ewangieliję naszę ku dostąpieniu chwały Pana naszego, Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Przetoż, bracia! stójcie, a trzymajcie się nauki podanej, którejście się nauczyli lub przez mowę, lub przez list nasz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'A sam Pan nasz, Jezus Chrystus i Bóg a Ojciec nasz, który nas umiłował i dał pociechę wieczną, i nadzieję dobrą przez łaskę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Niech cieszy serca wasze i utwierdza was w każdej mowie i w uczynku dobrym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Na ostatek, bracia! módlcie się za nas, aby się słowo Pańskie szerzyło i rozsławiało, jako i u was;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'I abyśmy byli wyrwani od niezbędnych i złych ludzi; albowiem nie wszystkich jest wiara.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Aleć wierny jest Pan, który was utwierdzi i strzec będzie od złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'A ufamy w Panu o was, iż to, co wam rozkazujemy, i czynicie i czynić będziecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'A Pan niech sprawuje serca wasze ku miłości Bożej i ku cierpliwemu oczekiwaniu Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'A rozkazujemy wam, bracia! w imieniu Pana naszego, Jezusa Chrystusa, abyście się odłączyli od każdego brata nieporządnie chodzącego, a nie według podanej nauki, którą wziął od nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Albowiem sami wiecie, jako nas potrzeba naśladować, ponieważeśmy nie żyli między wami nieporządnie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Aniśmy darmo chleba jedli u kogo, ale z pracą i z kłopotem we dnie i w nocy robiąc, abyśmy nikomu z was ciężkimi nie byli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Nie iżbyśmy tej mocy nie mieli, ale żebyśmy wam sami siebie za przykład podali, abyście nas naśladowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Albowiem gdyśmy byli u was, tośmy wam rozkazali, że jeźli kto nie chce robić, niechajże też nie je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Bo słyszymy, iż niektórzy między wami nieporządnie chodzą, nic nie robiąc, ale się niepotrzebnemi rzeczami bawiąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Przetoż takowym rozkazujemy i napominamy ich przez Pana naszego, Jezusa Chrystusa, aby w pokoju robiąc, swój własny chleb jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'A wy, bracia! nie słabiejcie, dobrze czyniąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'A jeźli kto jest nieposłuszny słowu naszemu przez list pisanemu, tego naznaczcie, a nie mieszajcie się z nim, aby się zawstydził;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Wszakże nie miejcie go za nieprzyjaciela, ale napominajcie jako brata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'A sam Pan pokoju niech wam da pokój zawsze i wszelkim sposobem. Pan niech będzie z wami wszystkimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Pozdrowienie ręką moją Pawłową, co jest znakiem w każdym liście; tak piszę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Łaska Pana naszego, Jezusa Chrystusa, niech będzie z wami wszystkimi. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paweł, Apostoł Jezusa Chrystusa podług rozrządzenia Boga, zbawiciela naszego, i Pana Jezusa Chrystusa, który jest nadzieja nasza,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Tymoteuszowi, własnemu synowi w wierze, niech będzie łaska, miłosierdzie, pokój od Boga, Ojca naszego, i Chrystusa Jezusa, Pana naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Jakom cię prosił, abyś został w Efezie, gdym szedł do Macedonii, patrzże, abyś rozkazał niektórym, żeby inaczej nie uczyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'I nie bawili się baśniami i wywodami nieskończonemi rodzaju, które więcej sporów przynoszą, niż zbudowania Bożego, które w wierze zależy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Lecz koniec przykazania jest miłość z czystego serca i z sumienia dobrego, i z wiary nieobłudnej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Czego niektórzy jako celu uchybiwszy, obrócili się ku próżnomówności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Chcąc być nauczycielami zakonu, nie rozumieją ani tego, co mówią, ani co za pewne twierdzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'A wiemy, że dobry jest zakon, jeźliby go kto przystojnie używał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Wiedząc to, że sprawiedliwemu nie jest zakon postanowiony, ale niesprawiedliwym i niepoddanym, niepobożnym i grzesznikom, złośliwym i nieczystym, ojcomordercom i matkomordercom, mężobójcom,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Wszetecznikom, samcołożnikom, ludokradcom, kłamcom, krzywoprzysiężcom, i jeźli co innego jest przeciwnego zdrowej nauce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Według chwalebnej Ewangielii błogosławionego Boga, która mi jest zwierzona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Przetoż dziękuję temu, który mię umocnił, Chrystusowi Jezusowi, Panu naszemu, iż mię za wiernego osądził, na usługiwanie postanowiwszy mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Którym pierwej był bluźniercą i prześladowcą, i gwałtownikiem; alem miłosierdzia dostąpił, bom to z niewiadomości czynił, będąc w niewierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Lecz nader obfitowała łaska Pana naszego z wiarą i z miłością, która jest w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Wierna jest ta mowa i wszelkiego przyjęcia godna, iż Chrystus Jezus przyszedł na świat, aby grzeszników zbawił, z których jam jest pierwszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Alem dlatego miłosierdzia dostąpił, aby na mnie pierwszym okazał Jezus Chrystus wszelką cierpliwość na przykład tym, którzy weń uwierzyć mają ku żywotowi wiecznemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Przetoż królowi wieków nieśmiertelnemu, niewidzialnemu samemu mądremu Bogu, niech będzie cześć i chwała na wieki wieków. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Toć rozkazanie zalecam, synu Tymoteuszu! abyś według proroctw, które uprzedziły o tobie, bojował w nich on dobry bój,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Mając wiarę i dobre sumienie, które niektórzy odrzuciwszy, szkodę podjęli w wierze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Z których jest Hymeneusz i Aleksander, którychem oddał szatanowi, aby pokarani będąc, nauczyli się nie bluźnić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Napominam tedy, aby przed wszystkiemi rzeczami czynione były prośby, modlitwy, przyczyny i dziękowania za wszystkich ludzi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Za królów i za wszystkich w przełożeństwie będących, abyśmy cichy i spokojny żywot wiedli we wszelkiej pobożności i uczciwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Albowiem to jest rzecz dobra i przyjemna przed Bogiem, zbawicielem naszym,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Który chce, aby wszyscy ludzie byli zbawieni i ku znajomości prawdy przyszli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Boć jeden jest Bóg, jeden także pośrednik między Bogiem i ludźmi, człowiek Chrystus Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Który dał samego siebie na okup za wszystkich, co jest świadectwem czasów jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Na com ja jest postanowiony za kaznodzieję i Apostoła, (prawdę mówię w Chrystusie, nie kłamię), za nauczyciela pogan w wierze i w prawdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Chcę tedy, aby się mężowie modlili na każdem miejscu, podnosząc czyste ręce bez gniewu i bez poswarku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Także i niewiasty, aby się ubiorem przystojnym ze wstydem i skromnością zdobiły, nie z trefionemi włosami, albo złotem, albo perłami, albo szatami kosztownemi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Ale (jako przystoi niewiastom, które się ozywają do pobożności), dobremi uczynkami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Niewiasta niech się uczy w milczeniu ze wszelkiem poddaństwem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Bo niewieście nie pozwalam uczyć, ani władzy mieć nad mężem, ale aby była w milczeniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Bo Adam pierwszy stworzony jest, potem Ewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'I Adam nie był zwiedziony, ale niewiasta zwiedziona będąc, przestępstwa przyczyną była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Lecz zbawiona będzie przez rodzenie dziatek, jeźliby zostały w wierze i w miłości, i w świętobliwości z miernością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Wierna jest ta mowa: Jeźli kto biskupstwa żąda, dobrej pracy żąda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Ale biskup ma być nienaganiony, mąż jednej żony, czuły, trzeźwy, poważny, gościnny, ku nauczaniu sposobny;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Nie pijanica wina, nie bitny, nie sprośnego zysku chciwy, ale słuszność miłujący, nieswarliwy, niełakomy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Który by dom swój dobrze rządził, który by dziatki miał w posłuszeństwie ze wszelaką uczciwością;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(Bo jeźliby kto nie umiał swego własnego domu rządzić, jakoż pieczę będzie miał o kościele Bożym?)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Nie nowotny, aby będąc nadęty, nie wpadł w sąd potwarcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Musi też mieć świadectwo dobre od obcych, aby nie wpadł w hańbę i w sidło potwarcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Dyjakonowie także mają być poważni, nie dwoistego słowa, nie pijanicy wielu wina, nie chciwi sprośnego zysku,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Mający tajemnicę wiary w czystem sumieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'A ci też niech będą pierwej doświadczeni, zatem niech służą, jeźli są bez nagany;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Żony także niech mają poważne, nie potwarliwe, trzeźwe, wierne we wszystkiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Dyjakonowie niech będą mężami jednej żony, którzy by dziatki dobrze rządzili i własne domy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Albowiem którzy by dobrze służyli, stopień sobie dobry zjednają i wielkie bezpieczeństwo w wierze, która jest w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Toć tobie piszę, mając nadzieję, że w rychle przyjdę do ciebie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'A jeźlibym omieszkał, abyś wiedział, jako się masz w domu Bożym sprawować, który jest kościołem Boga żywego, filarem i utwierdzeniem prawdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'A zaprawdę wielka jest tajemnica pobożności, że Bóg objawiony jest w ciele, usprawiedliwiony jest w duchu, widziany jest od Aniołów, kazany jest poganom, uwierzono mu na świecie, wzięty jest w górę do chwały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'A Duch jawnie mówi, iż w ostateczne czasy odstaną niektórzy od wiary, słuchając duchów zwodzących i nauk dyjabelskich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'W obłudzie kłamstwo mówiących i piętnowane mających sumienie swoje,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Zabraniających wstępować w małżeństwo, rozkazujących wstrzymywać się od pokarmów, które Bóg stworzył ku przyjmowaniu z dziękowaniem wiernym i tym, którzy poznali prawdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Bo wszelkie stworzenie Boże dobre jest, a nic nie ma być odrzuconem, co z dziękowaniem bywa przyjmowane;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Albowiem poświęcone bywa przez słowo Boże i przez modlitwę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'To przekładając braciom, będziesz dobrym sługą Chrystusa Jezusa, wychowanym w słowach wiary i nauki dobrej, którejś naśladował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'A świeckich i babich baśni chroń się; ale się ćwicz w pobożności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Albowiem cielesne ćwiczenie mało jest pożyteczne; lecz pobożność do wszystkiego jest pożyteczna, mając obietnicę żywota teraźniejszego i przyszłego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Wierna to jest mowa i wszelkiego przyjęcia godna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Albowiem przeto też pracujemy i lżeni bywamy, że nadzieję mamy w Bogu żywym, który jest zbawicielem wszystkich ludzi, a najwięcej wiernych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'To przykazuj i tego nauczaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Żaden młodością twoją niech nie gardzi; ale bądź przykładem wiernych w mowie, w obcowaniu, w miłości, w duchu, w wierze, w czystości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Póki nie przyjdę, pilnuj czytania, napominania i nauki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Nie zaniedbywaj daru Bożego, który w tobie jest, któryć dany jest przez prorokowanie z włożeniem rąk starszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'O tem rozmyślaj, tem się zabawiaj, aby postępek twój jawny był wszystkim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Pilnuj samego siebie i nauczania, trwaj w tych rzeczach; bo to czyniąc, i samego siebie zbawisz, i tych, którzy cię słuchają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Starszemu nie łaj, ale jako ojca napominaj, młodszych jako braci,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Starsze niewiasty jako matki, młodsze jako siostry, ze wszelaką czystością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Wdowy miej w uczciwości, które prawdziwie są wdowami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'A jeźli która wdowa dzieci albo wnuczęta ma, niech się uczą pierwej przeciwko domowi własnemu być pobożnemi i wzajem oddawać rodzicom; albowiem to jest rzecz chwalebna i przyjemna przed obliczem Bożem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'A która jest prawdziwie wdowa i osierociała, ma nadzieję w Bogu i trwa w prośbach i w modlitwach w nocy i we dnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Ale która w rozkoszach żyje, ta żyjąc umarłą jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'To tedy rozkazuj, żeby były nienaganione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'A jeźli kto o swoich, a najwięcej o domowych starania nie ma, wiary się zaprzał i gorszy jest niż niewierny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Wdowa niech będzie obrana, która by nie miała mniej niż sześćdziesiąt lat, która była żoną jednego męża,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Mająca świadectwo w dobrych uczynkach, jeźli dzieci wychowała, jeźli gości przyjmowała, jeźli świętych nogi umywała, jeźli utrapionych wspomagała, jeźli każdego uczynku dobrego naśladowała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Wdów zasię młodszych chroń się; bo gdyby się zbestwiły przeciw Chrystusowi, chcą za mąż iść,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Mając osądzenie, iż pierwszą wiarę odrzuciły;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Owszem też próżnując uczą się chodzić od domu do domu; a nie tylko są próżnujące, ale też świegotliwe, niepotrzebnemi rzeczami się bawiące, mówiąc, co nie przystoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Chcę tedy, aby młodsze szły za mąż, dzieci rodziły, gospodyniami były; przeciwnikowi żadnej przyczyny nie dawały ku obmowisku;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Albowiem się już niektóre obróciły za szatanem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Przetoż, jeźli który wierny albo która wierna ma wdowy, niechże je opatruje, a niech zbór nie będzie obciążony, aby tym, które są prawdziwie wdowami, starczyło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Starsi, którzy się w przełożeństwie dobrze sprawują, niech będą mieni za godnych dwojakiej czci, a zwłaszcza ci, którzy pracują w słowie i w nauce.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Albowiem Pismo mówi: Wołowi młócącemu nie zawiążesz gęby; i: Godzien jest robotnik zapłaty swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Przeciwko starszemu nie przyjmuj skargi, chyba za dwoma albo trzema świadkami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'A tych, którzy grzeszą, strofuj przed wszystkimi, aby i drudzy bojaźń mieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Oświadczam się przed Bogiem i Panem Jezusem Chrystusem, i przed Anioły wybranymi, abyś tych rzeczy przestrzegał, w osobach nie brakując, nic nie czyniąc z przychylności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Rąk z prędka na nikogo nie wkładaj, ani bądź uczestnikiem cudzych grzechów: samego siebie czystym zachowaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Samej wody więcej nie pijaj, ale używaj po trosze wina dla żołądka twego i częstych chorób twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Grzechy niektórych ludzi przedtem są jawne i uprzedzają na sąd, a za niektórymi idą pozad.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Także też dobre uczynki przedtem są jawne; ale które są insze, utaić się nie mogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Którzykolwiek słudzy są pod jarzmem, niech rozumieją panów swych godnych być wszelakiej czci, aby imię Boże i nauka nie była bluźniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'A którzy mają panów wiernych, niech nimi nie gardzą, dlatego iż są braćmi, ale tem raczej niech służą, iż są wierni i mili, dobrodziejstwa Bożego uczestnicy. Tego nauczaj i do tego upominaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Jeźli kto inaczej uczy, a nie przystępuje do zdrowych mów Pana naszego, Jezusa Chrystusa, i do tej nauki, która jest według pobożności,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Taki nadęty jest i nic nie umie, ale szaleje około gadek i sporów o słowa, z których pochodzi zazdrość, swar, złorzeczenia, złe podejrzenia,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Przewrotne ćwiczenia ludzi umysłu skażonego i którzy pozbawieni są prawdy, którzy rozumieją, że pobożność jest zyskiem cielesnym; odstąpże od takich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'A jestci wielki zysk pobożność z przestawaniem na swem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Albowiem niceśmy nie przynieśli na ten świat, bez pochyby że też wynieść nic nie możemy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Ale mając żywność i odzienie, na tem przestawać mamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Bo którzy chcą bogatymi być, wpadają w pokuszenie i w sidło, i w wiele głupich i szkodliwych pożądliwości, które pogrążają ludzi na zatracenie i zginienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Albowiem korzeń wszystkiego złego jest miłość pieniędzy, których niektórzy pragnąc, pobłądzili od wiary i poprzebijali się wieloma boleściami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Ale ty, człowiecze Boży! chroń się takich rzeczy, a naśladuj sprawiedliwości, pobożności, wiary, miłości, cierpliwości, cichości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Bojuj on dobry bój wiary, chwyć się żywota wiecznego, do któregoś też powołany, i wyznałeś dobre wyznanie przed wieloma świadkami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Rozkazuję ci przed Bogiem, który wszystko ożywia i przed Chrystusem Jezusem, który oświadczył przed Ponckim Piłatem dobre wyznanie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Abyś zachował to przykazanie, będąc bez zmazy, bez nagany, aż do objawienia Pana naszego, Jezusa Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Które czasów swoich okaże on błogosławiony i sam możny król królujących i Pan panujących;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Który sam ma nieśmiertelność i mieszka w światłości nieprzystępnej, którego nie widział żaden z ludzi, ani widzieć może; któremu niech będzie cześć i moc wieczna. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Bogaczom w tym teraźniejszym wieku rozkaż, aby nie byli wysokomyślnymi, ani nadziei pokładali w bogactwie niepewnem, ale w Bogu żywym, który nam wszystkiego obficie ku używaniu dodaje:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Aby innym dobrze czynili, w uczynki dobre bogatymi byli, radzi dawali, a radzi udzielali,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Skarbiąc sami sobie grunt dobry na przyszły czas, aby otrzymali żywot wieczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'O Tymoteuszu! strzeż tego, czegoć się powierzono, a brzydź się świecką próżnomównością i sprzeczaniem około fałszywie nazwanej umiejętności,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Którą się niektórzy szczycąc z strony wiary, celu uchybili. Łaska niech będzie z tobą. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paweł, Apostoł Jezusa Chrystusa przez wolę Bożą, według obietnicy żywota onego, który jest w Chrystusie Jezusie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Tymoteuszowi, miłemu synowi, niech będzie łaska, miłosierdzie i pokój od Boga Ojca i Chrystusa Jezusa, Pana naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Dziękuję Bogu, któremu służę z przodków w czystem sumieniu, że cię bez przestanku wspominam w prośbach moich, w nocy i we dnie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Żądając cię widzieć, wspominając na twoje łzy, abym był radością napełniony,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Przywodząc sobie na pamięć onę, która w tobie jest, nieobłudną wiarę, która pierwej mieszkała w babce twojej Loidzie i w matce twojej Eunice, a pewienem, że i w tobie mieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Dla której przyczyny przypominam ci, abyś wzniecał dar Boży, który w tobie jest przez włożenie rąk moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Albowiem nie dał nam Bóg Ducha bojaźni, ale mocy i miłości, i zdrowego zmysłu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Przetoż nie wstydź się za świadectwo Pana naszego, ani za mię, więźnia jego, ale cierp złe z Ewangieliją według mocy Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Który nas zbawił i powołał powołaniem świętem, nie według uczynków naszych, ale według postanowienia swego i łaski, która nam jest dana w Chrystusie Jezusie przed czasy wiecznemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'A teraz objawiona jest przez okazanie się zbawiciela naszego, Jezusa Chrystusa, który i śmierć zgładził, i żywot na jaśnię wywiódł, i nieśmiertelność przez Ewangieliję,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Której jam jest postanowiony kaznodzieją i Apostołem, i nauczycielem pogan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Dla której też przyczyny te rzeczy cierpię; aleć się nie wstydzę, gdyż wiem, komum uwierzył i pewienem, iż on mocen jest tego, czego mi się powierzył, strzec aż do onego dnia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Zatrzymaj wzór zdrowych słów, któreś ode mnie usłyszał, w wierze i w miłości, która jest w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Strzeż dobrego pokładu przez Ducha Świętego, który w nas mieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Wiesz to, iż mię odstąpili wszyscy, którzy są w Azyi, z których jest Fygellus i Hermogenes.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Niech da Pan miłosierdzie swoje Onezyforowemu domowi, iż mię często ochłodził i za łańcuch mój się nie wstydził;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Ale będąc w Rzymie, bardzo mię pilno szukał i znalazł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Niech mu Pan da, aby znalazł miłosierdzie u Pana w on dzień; a ty lepiej wiesz, jako mi wiele usługiwał w Efezie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Przetoż ty, synu mój! zmacniaj się w łasce, która jest w Chrystusie Jezusie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'A coś słyszał ode mnie przed wieloma świadkami, tegoż się powierz wiernym ludziom, którzy by sposobni byli i inszych nauczać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Przetoż ty cierp złe, jako dobry żołnierz Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Żaden, który żołnierkę służy, nie wikle się sprawami tego żywota, aby się temu, od którego za żołnierza przyjęty jest, podobał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'A choćby się też kto potykał, nie bywa koronowany, jeźliby się przystojnie nie potykał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Oracz, który pracuje, ma najprzód pożytki odbierać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Rozumiej, co mówię, a Pan niech ci da we wszystkiem wyrozumienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Pamiętaj, iż Jezus Chrystus powstał z martwych, który jest z nasienia Dawidowego, według Ewangielii mojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'W której cierpię złe, jakoby złoczyńca, aż do związek; aleć słowo Boże nie jest związane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Przetoż wszystko znoszę dla wybranych, aby i oni zbawienia dostąpili, które jest w Chrystusie Jezusie, z chwałą wieczną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Wierna jest ta mowa; albowiem jeźliśmy z nim umarli, z nim też żyć będziemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Jeźli cierpimy, z nim też królować będziemy; jeźli się go zapieramy, i on się nas zaprze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Jeźliśmy niewiernymi, on wiernym zostaje i zaprzeć samego siebie nie może.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Te rzeczy przypominaj, oświadczając przed obliczem Pańskiem, aby się nie wdawali w spory około słów, co ku niczemu nie jest pożyteczne, tylko ku podwróceniu tych, którzy słuchają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Staraj się, abyś się doświadczonym stawił Bogu robotnikiem, który by się nie zawstydził i który by dobrze rozbierał słowo prawdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'A świeckim próżnomównościom czyń wstręt; albowiem postępują ku większej niepobożności.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'A mowa ich szerzy się jako kancer (rak), z których jest Hymeneusz i Filetus,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'Którzy względem prawdy celu uchybili, gdy powiadają, iż się już stało zmartwychwstanie i podwracają wiarę niektórych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'A wszakże mocny stoi grunt Boży, mając tę pieczęć: Zna Pan, którzy są jego; i Niech odstąpi od niesprawiedliwości wszelki, który mianuje imię Chrystusowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'A w wielkim domu nie tylko są naczynia złote i srebrne, ale też drewniane i gliniane, a niektóre ku uczciwości, drugie zasię ku zelżywości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Jeźliby tedy kto samego siebie oczyścił od tych rzeczy, będzie naczyniem ku uczciwości, poświęconem i użytecznem Panu, do wszelkiej dobrej sprawy zgotowanem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Chroń się też pożądliwości młodzieńczych, a naśladuj sprawiedliwości, wiary, miłości, pokoju z tymi, którzy wzywają Pana z czystego serca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Chroń się też gadek głupich i nieumiejętnych, wiedząc, iż rodzą zwady.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Ale sługa Pański nie ma być zwadliwy, lecz ma być układny przeciwko wszystkim, sposobny ku nauczaniu, złych cierpliwie znaszający;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Który by w cichości nauczał tych, którzy się sprzeciwiają, owaby im kiedy Bóg dał pokutę ku uznaniu prawdy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'Aby obaczywszy się, wywikłali się z sidła dyjabelskiego, od którego pojmani są ku czynieniu woli jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'A to wiedz, iż w ostateczne dni nastaną czasy trudne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Albowiem będą ludzie sami siebie miłujący, łakomi, chlubni, pyszni, bluźniercy, rodzicom nieposłuszni, niewdzięczni, niepobożni,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Bez przyrodzonej miłości, przymierza nie trzymający, potwarcy, niepowściągliwi, nieskromni, dobrych nie miłujący,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Zdrajcy, skwapliwi, nadęci, rozkoszy raczej miłujący niż miłujący Boga;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Którzy mają kształt pobożności, ale się skutku jej zaparli; i tych się chroń.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Albowiem z tych są ci, którzy się wrywają w domy i pojmane wiodą niewiastki grzechami obciążone, które uwodzą rozmaite pożądliwości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Które się zawsze uczą, a nigdy do znajomości prawdy przyjść nie mogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'A jako Jannes i Jambres sprzeciwiali się Mojżeszowi, tak i ci sprzeciwiają się prawdzie, ludzie rozumu skażonego, odrzuceni z strony wiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Ale nie postąpią dalej; albowiem głupstwo ich jawne będzie wszystkim, jako i onych było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Aleś ty doszedł nauki mojej, sposobu żywota mego, przedsięwzięcia wiary, nieskwapliwości, miłości i cierpliwości,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'Prześladowania, ucierpienia, które mię spotkały w Antyjochii, w Ikonii i w Listrze, jakiem prześladowania podejmował; a ze wszystkich wyrwał mię Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Aleć i wszyscy, którzy chcą pobożnie żyć w Chrystusie Jezusie, prześladowani będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Lecz źli ludzie i zwodziciele postąpią w gorsze, jako zwodzący tak i zwiedzeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Ale ty trwaj w tem, czegoś się nauczył i czegoć powierzono, wiedząc, od kogoś się tego nauczył.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'A iż z dzieciństwa umiesz Pisma święte, które cię mogą uczynić mądrym ku zbawieniu przez wiarę, która jest w Chrystusie Jezusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Wszystko Pismo od Boga jest natchnione i pożyteczne ku nauce, ku strofowaniu, ku naprawie, ku ćwiczeniu, które jest w sprawiedliwości;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Aby człowiek Boży był doskonały, ku wszelkiej sprawie dobrej dostatecznie wyćwiczony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Ja tedy oświadczam się przed Bogiem i Panem Jezusem Chrystusem, który ma sądzić żywych i umarłych w sławnem przyjściu swojem i królestwie swojem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Każ słowo Boże, nalegaj w czas albo nie w czas, strofuj, grom i napominaj ze wszelką cierpliwością i nauką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Albowiem przyjdzie czas, gdy zdrowej nauki nie ścierpią, ale według swoich pożądliwości zgromadzą sobie sami nauczycieli, mając świerzbiące uszy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'A odwrócą uszy od prawdy, a ku baśniom je obrócą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Ale ty bądź czułym we wszystkiem, cierp złe, wykonywaj uczynek kaznodziei, usługiwania twego zupełnie dowódź.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Albowiem ja już bywam ofiarowany, a czas rozwiązania mego nadchodzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Dobrym bój bojował, biegem wykonał, wiaręm zachował;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Zatem odłożona mi jest korona sprawiedliwości, którą mi odda w on dzień Pan, sędzia sprawiedliwy, a nie tylko mnie, ale i wszystkim, którzy umiłowali sławne przyjście jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Staraj się, abyś do mnie przyszedł rychło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Albowiem Demas mię opuścił, umiłowawszy ten świat, i poszedł do Tesaloniki, Krescens do Galacyi, Tytus do Dalmacyi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Sam tylko Łukasz ze mną jest. Marka wziąwszy, przywiedź ze sobą; bo mi jest bardzo pożyteczny ku posłudze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'A Tychykam posłał do Efezu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Opończę, którąm zostawił w Troadzie u Karpusa, gdy przyjdziesz, przynieś z sobą i księgi, zwłaszcza membrany.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Aleksander kotlarz wiele mi złego wyrządził; niech mu Pan odda według uczynków jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Którego i ty się strzeż; albowiem się bardzo sprzeciwił słowom naszym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'W pierwszej obronie mojej żaden przy mnie nie stał, ale mię wszyscy opuścili; niech im to nie będzie przyczytane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Ale Pan przy mnie stał i umocnił mię, aby przez mię zupełnie utwierdzone było kazanie, a iżby je słyszeli wszyscy poganie, i byłem wyrwany z paszczęki lwiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'A wyrwie mię Pan z każdego uczynku złego i zachowa do królestwa swego niebieskiego; któremu chwała na wieki wieków. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Pozdrów Pryszkę i Akwilę, i dom Onezyforowy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erastus został w Koryncie, a Trofimam zostawił w Milecie chorego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Staraj się, abyś przyszedł przed zimą. Pozdrawia cię Eubulus i Pudens, i Linus, i Klaudyja, i bracia wszyscy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Pan Jezus Chrystus niech będzie z duchem twoim. Łaska Boża niech będzie z wami. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paweł, sługa Boży i Apostoł Jezusa Chrystusa według wiary wybranych Bożych i znajomości prawdy, która jest według pobożności,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'Ku nadziei żywota wiecznego, który obiecał przed czasy wiekuistemi ten, który nie kłamie, Bóg, a objawił czasów swoich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'To słowo swoje przez kazanie, które mi jest zwierzone według rozrządzenia zbawiciela naszego Boga:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Tytusowi, własnemu synowi według spólnej wiary, łaska, miłosierdzie i pokój niech będzie od Boga Ojca, i Pana Jezusa Chrystusa, zbawiciela naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Dlategom cię zostawił w Krecie, abyś to, co tam jeszcze zostaje, w rząd dobry wprawił i postanowił po miastach starszych, jakom ci ja był rozkazał;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Jeźli kto jest bez nagany, mąż jednej żony, dzieci wierne mający, które by nie mogły być obwinione w zbytku, albo niepoddane rządowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Albowiem biskup ma być bez nagany, jako szafarz Boży, nie sam sobie się podobający, nie gniewliwy, nie pijanica wina, nie bitny, nie szukający zysku sprośnego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Ale gościnny, dobre miłujący, roztropny, sprawiedliwy, świętobliwy, powściągliwy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Trzymający się onej wiernej mowy, która jest według nauki, iżby też mógł napominać nauką zdrową i tych, którzy się sprzeciwiają, przekonywać;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Albowiem jest wiele rządowi niepoddanych, próżnomównych i zwodzicieli myśli, a najwięcej tych, którzy są z obrzezki,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Którym trzeba usta zatkać; którzy całe domy podwracają, ucząc rzeczy niesłusznych dla zysku sprośnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Powiedział niektóry z nich własny ich prorok: Kreteńczycy zawsze są kłamcami, złemi bestyjami, brzuchami leniwemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'To świadectwo jest prawdziwe; dla której przyczyny ostro ich karz, aby zdrowi byli w wierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Nie pilnując żydowskich baśni i przykazań ludzi tych, którzy się odwracają od prawdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Wszystkoć czyste czystym, lecz pokalanym i niewiernym nie masz nic czystego, ale pokalany jest i umysł, i sumienie ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Udawają, że Boga znają; ale uczynkami swemi tego się zapierają, będąc obrzydłymi i nieposłusznymi, a do wszelkiego dobrego uczynku niesposobnymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'A ty mów co należy na zdrową naukę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Starcy, aby byli trzeźwi, poważni, roztropni, zdrowi w wierze, w miłości, w cierpliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Także i stare niewiasty niech chodzą w ubiorze przystojnym, jako przystoi świętym; niech nie będą potwarliwe, nie kochające się w wielu wina, poczciwych rzeczy nauczające;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'Aby młodych pań rozumu uczyły, jakoby mężów swoich i dziatki miłować miały,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'A były roztropne, czyste, domu pilne, dobrotliwe, mężom swym poddane, aby słowo Boże nie było bluźnione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Młodzieńców także napominaj, aby byli trzeźwi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'We wszystkiem samego siebie wystawiając za wzór dobrych uczynków, mając w nauce całość, powagę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Słowo zdrowe, nienaganione, aby ten, kto by się sprzeciwił, zawstydzić się musiał, nie mając nic, co by o was miał złego mówić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Sług nauczaj, aby byli poddani panom swoim, we wszystkiem się im podobając, nie odmawiając,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'W niczem nie oszukując, ale we wszystkiem wierność uprzejmą pokazując, aby naukę zbawiciela naszego, Boga, we wszystkiem zdobili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Albowiem okazała się łaska Boża, zbawienna wszystkim ludziom,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Ćwicząca nas, abyśmy odrzekłszy się niepobożności i świeckich pożądliwości, trzeźwie i sprawiedliwie, i pobożnie żyli na tym świecie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Oczekując onej błogosławionej nadziei i objawienia chwały wielkiego Boga i zbawiciela naszego, Jezusa Chrystusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Który dał samego siebie za nas, aby nas wykupił od wszelkiej nieprawości i oczyścił sobie samemu lud własny, gorliwie naśladujący dobrych uczynków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'To mów i napominaj, i strofuj ze wszelką powagą; żaden tobą niechaj nie gardzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Napominaj ich, aby zwierzchnościom i przełożeństwom poddanymi i posłusznymi byli, i aby do każdego dobrego uczynku gotowymi byli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Nikogo nie lżyli, byli niezwadliwymi, ale układnymi, okazując wszelką skromność przeciwko wszystkim ludziom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Albowiem i myśmy byli niekiedy głupimi, upornymi, błądzącymi, służąc pożądliwościom i rozkoszom rozmaitym, w złości i w zazdrości mieszkając, przemierzłymi, jedni drugich nienawidzącymi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Ale gdy się okazała dobrotliwość i miłość ku ludziom zbawiciela naszego, Boga,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Nie z uczynków sprawiedliwości, które byśmy my czynili, ale podług miłosierdzia swego zbawił nas przez omycie odrodzenia i odnowienia Ducha Świętego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Którego wylał na nas obficie przez Jezusa Chrystusa, zbawiciela naszego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'Abyśmy usprawiedliwieni będąc łaską jego, stali się dziedzicami według nadziei żywota wiecznego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Wiernać to mowa; a chcę, abyś ty to twierdził, aby się starali, jakoby w dobrych uczynkach przodkowali, którzy uwierzyli Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'A te rzeczy są dobre i ludziom pożyteczne; a głupich gadek i wyliczania rodzajów, i sporów, i swarów zakonnych pohamuj; albowiem są niepożyteczne i próżne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Człowieka heretyka po pierwszem i wtórem napominaniu strzeż się,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Wiedząc, iż takowy jest wywrócony i grzeszy, będąc sam własnym sądem swoim osądzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Gdy poślę do ciebie Artemana albo Tychyka, staraj się, abyś do mnie przyszedł do Nikopolim; bom tam postanowił zimować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zenasa nauczonego w zakonie i Apollona pilnie odprowadź, aby im na niczem nie schodziło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'A niech się uczą i nasi w dobrych uczynkach przodkować, gdzie tego potrzeba, żeby nie byli nieużytecznymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Pozdrawiają cię, którzy są ze mną wszyscy. Pozdrów tych, którzy nas miłują w wierze. Łaska Boża niech będzie ze wszystkimi wami. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paweł, więzień Chrystusa Jezusa i Tymoteusz brat, Filemonowi miłemu a pomocnikowi naszemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'I Apfii miłej i Archipowi, społecznemu naszemu bojownikowi, i zborowi, który jest w domu twoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Łaska wam i pokój niech będzie od Boga, Ojca naszego, i Pana Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Dziękuję Bogu mojemu zawsze wzmiankę czyniąc o tobie w modlitwach moich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Słysząc o miłości i o wierze, którą masz przeciwko Panu Jezusowi i przeciwko wszystkim świętym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Aby społeczność wiary twojej była skuteczna ku poznaniu wszystkiego dobrego, które w was jest przez Chrystusa Jezusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Albowiem radość wielką mamy i pociechę z miłości twojej, bracie! iż wnętrzności świętych są ochłodzone przez cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Przetoż choć mam wielką bezpieczność w Chrystusie, abym ci rozkazał, co przynależy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'Jednak dla miłości raczej proszę, takowym będąc, to jest Paweł stary, a teraz i więzień Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Proszę cię tedy za synem moim Onezymem, któregom urodził w więzieniu mojem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Który tobie niekiedy był niepożyteczny, ale teraz tobie i mnie bardzo pożyteczny; któregom odesłał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Przetoż go ty jako wnętrzności moje przyjmij.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Któregom ja chciał przy sobie zatrzymać, aby mi posługiwał zamiast ciebie w więzieniu dla Ewangielii.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Ale bez woli twojej nie chciałem nic uczynić, aby dobry twój uczynek nie był jako z przymuszenia, ale z dobrej woli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Albowiem snać dla tego odłączył się był na chwilę od ciebie, abyś go zaś miał wiecznie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Już nie jako sługę, ale więcej niż sługę, to jest brata miłego, zwłaszcza mnie, a jako daleko więcej tobie i według ciała, i w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Przetoż maszli mię za towarzysza, przyjmij go jako mię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'A jeźlić w czem niepraw, albo ci co winien, to mnie przyczytaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Jam Paweł napisał ręką moją, ja nagrodzę, żeć nie rzekę, iżeś mi i samego siebie winien.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Tak, bracie! niech cię w tem użyję w Panu, ochłodź wnętrzności moje w Panu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Pewien będąc posłuszeństwa twego, pisałem ci, wiedząc, że i więcej, niż mówię uczynisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Zaraz mi też i gospodę zgotuj; albowiem spodziewam się, iż wam przez modlitwy wasze darowany będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Pozdrawiają cię Epafras, spółwięzień mój w Chrystusie Jezusie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Marek, Arystarchus, Demas, Łukasz, pomocnicy moi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Łaska Pana naszego, Jezusa Chrystusa, niech będzie z duchem waszym. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Częstokroć i wieloma sposobami mawiał niekiedy Bóg ojcom przez proroków;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'W te dni ostateczne mówił nam przez Syna swego, którego postanowił dziedzicem wszystkich rzeczy, przez którego i wieki uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Który będąc jasnością chwały i wyrażeniem istności jego, i zatrzymując wszystkie rzeczy słowem mocy swojej, oczyszczenie grzechów naszych przez samego siebie uczyniwszy, usiadł na prawicy majestatu na wysokościach,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Tem się zacniejszym stawszy nad Anioły, czem zacniejsze nad nie odziedziczył imię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Albowiem któremuż kiedy z Aniołów rzekł: Tyś jest syn mój, jam cię dziś spłodził? I zasię: Ja mu będę ojcem, a on mnie będzie synem?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'A zasię, gdy wprowadza pierworodnego na okrąg świata, mówi: A niech się mu kłaniają wszyscy Aniołowie Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'A zasię o Aniołach mówi: Który Anioły swoje czyni duchami, a sługi swoje płomieniem ognistym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Ale do Syna mówi: Stolica twoja, o Boże! na wieki wieków; laska sprawiedliwości jest laska królestwa twego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Umiłowałeś sprawiedliwość, a nienawidziłeś nieprawości; przetoż pomazał cię, o Boże! Bóg twój olejkiem wesela nad uczestników twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'I tyś, Panie! na początku ugruntował ziemię, a niebiosa są dziełem rąk twoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Oneć pominą, ale ty zostajesz; a wszystkie jako szata zwiotszeją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'A jako odzienie zwiniesz je i będą odmienione; ale ty tenżeś jest, a lata twoje nie ustaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'A do któregoż kiedy z Aniołów rzekł: Siądź po prawicy mojej, dokąd nie położę nieprzyjaciół twoich podnóżkiem nóg twoich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Izali wszyscy nie są duchami usługującymi, którzy na posługę bywają posłani dla tych, którzy zbawienie odziedziczyć mają?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Przetoż musimy tem pilniej przestrzegać tego, cośmy słyszeli, byśmy snać nie przeciekli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Bo ponieważ przez Anioły mówione słowo było pewne, a każde przestępstwo i nieposłuszeństwo wzięło sprawiedliwą zapłatę pomsty:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Jakoż my ucieczemy, jeźli zaniedbamy tak wielkiego zbawienia, które wziąwszy początek opowiadania przez samego Pana od tych, którzy go słyszeli, nam jest potwierdzone?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Którym i Bóg świadectwo wydawał przez znamiona i cuda, i rozliczne mocy, i przez udzielanie Ducha Świętego według woli swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Albowiem nie Aniołom poddał świat przyszły, o którym mówimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'A świadczył ktoś na niektórem miejscu, mówiąc: Cóż jest człowiek, iż nań pamiętasz, albo syn człowieczy, iż go nawiedzasz?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Na małą chwilę mniejszym uczyniłeś go od Aniołów, chwałą i czcią ukoronowałeś go i postanowiłeś go nad uczynkami rąk twoich,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Wszystkoś poddał pod nogi jego. A poddawszy mu wszystko, nic nie zostawił, co by mu poddanego nie było; lecz teraz jeszcze nie widzimy, aby mu wszystko poddane było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Ale tego, który na małą chwilę mniejszym stał się od Aniołów, Jezusa, widzimy przez ucierpienie śmierci chwałą i czcią ukoronowanego, aby z łaski Bożej za wszystkich śmierci skosztował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Albowiem należało na tego, dla którego jest wszystko i przez którego jest wszystko, aby wiele synów do chwały przywodząc wodza zbawienia ich przez ucierpienie doskonałym uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Bo ten, który poświęca i ci, którzy bywają poświęceni, z jednego są wszyscy, dla której przyczyny nie wstydzi się ich braćmi nazywać,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Mówiąc: Opowiem imię twoje braciom moim, w pośrodku zgromadzenia śpiewać ci będę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'I zasię: Ja w nim ufać będę; a zasię: Oto ja i dzieci, które mi dał Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Ponieważ tedy dzieci społeczność mają ciała i krwi, i on także stał się ich uczestnikiem, aby przez śmierć zniszczył tego, który miał władzę śmierci, to jest dyjabła,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'A iżby wyswobodził tych, którzy dla bojaźni śmierci po wszystek czas żywota podlegli byli niewoli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Bo zaiste nigdzie nie przyjął Aniołów, ale nasienie Abrahamowe przyjął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Skąd miał być we wszystkiem podobny braciom, aby był miłosiernym i wiernym najwyższym kapłanem w tem, co się u Boga na ubłaganie za grzechy ludzkie dziać miało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Albowiem że sam cierpiał będąc kuszony, może tych, którzy są w pokusach, ratować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Przetoż, bracia święci, powołania niebieskiego uczestnicy! obaczcie Apostoła i najwyższego kapłana wyznania naszego, Chrystusa Jezusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Wiernego temu, który go postanowił, jako i Mojżesz był we wszystkim domu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Albowiem tem większej chwały ten nad Mojżesza godzien, im większą cześć ma budownik domu, niżeli sam dom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Bo każdy dom bywa budowany od kogo; ale który wszystkie rzeczy zbudował, Bóg jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'A byłci Mojżesz wiernym we wszystkim domu jego, jako sługa, na świadectwo tego, co potem miało być mówione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Ale Chrystus jako syn nad domem swoim panuje, którego domem my jesteśmy, jeźli tylko tę pewną ufność i tę chwałę nadziei aż do końca stateczną zachowamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Przetoż jako mówi Duch Święty: Dziś, jeźlibyście głos jego usłyszeli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'Nie zatwardzajcież serc waszych, jako w rozdrażnieniu, w dzień onego pokuszenia na puszczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Gdzie mię kusili ojcowie wasi i doświadczali mię, i widzieli sprawy moje przez czterdzieści lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Dlategom się rozgniewał na ten naród i rzekłem: Ci zawsze błądzą sercem, a oni nie poznawają dróg moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'Jakom przysiągł w gniewie moim, że nie wnijdą do odpocznienia mojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Patrzcież, bracia! by snać nie było w którym z was serce złe i niewierne, które by odstępowało od Boga żywego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Ale napominajcie jedni drugich na każdy dzień, póki się Dziś nazywa, aby kto z was nie był zatwardzony oszukaniem grzechu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Albowiem staliśmy się uczestnikami Chrystusa, jeźliże tylko początek tego gruntu aż do końca stateczny zachowamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Przetoż póki bywa rzeczone: Dziś, jeźlibyście głos jego usłyszeli, nie zatwardzajcież serc waszych, jako w onem rozdrażnieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Albowiem niektórzy usłyszawszy, rozdrażnili Pana, ale nie wszyscy, którzy byli wyszli z Egiptu przez Mojżesza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'A na którychże się gniewał przez czterdzieści lat? Izali nie na tych, którzy grzeszyli, których ciała poległy na puszczy?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'A którymże przysiągł, że nie mieli wnijść do odpocznienia jego? Azaż nie tym, którzy byli nieposłusznymi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'I widzimy, iż tam nie mogli wnijść dla niedowiarstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Bójmyż się tedy, aby snać zaniedbawszy obietnicy o wejściu do odpocznienia jego, nie zdał się kto z was być upośledzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Albowiem i nam zwiastowana jest Ewangielija jako i onym; ale im nie pomogło słowo, które słyszeli, przeto iż nie było złączone z wiarą tych, którzy słyszeli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Albowiem wnijdziemy do odpocznienia, którzyśmy uwierzyli, jako powiedział: Przetożem przysiągł w gniewie moim, że nie wnijdą do odpocznienia mojego; choć dokonane są dzieła Boże od założenia świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Albowiem tak powiedział na jednem miejscu o siódmym dniu: I odpoczął Bóg dnia siódmego od wszystkich spraw swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'A tu zasię: Że nie wnijdą do odpocznienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Ponieważ tedy to zostaje, że niektórzy wchodzą do niego, a ci, którym pierwej zwiastowano, nie weszli dla niedowiarstwa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Zasię naznacza dzień niektóry: Dziś, mówiąc przez Dawida po tak długim czasie (jako powiedziano): Dziś, jeźlibyście głos jego usłyszeli, nie zatwardzajcież serc waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Albowiem jeźliby im Jozue odpocznienie sprawił, nie mówiłby był potem o inszym dniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'A tak zostaje jeszcze odpocznienie ludowi Bożemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Albowiem ktobykolwiek wszedł do odpocznienia jego i on także odpoczął od spraw swoich, jako i Bóg od swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Starajmyż się tedy, abyśmy weszli do onego odpocznienia, żeby kto nie wpadł w tenże przykład niedowiarstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Boć żywe jest słowo Boże i skuteczne, i przeraźliwsze nad wszelki miecz po obu stronach ostry, i przenikające aż do rozdzielenia i duszy, i ducha, i stawów, i szpików, i rozeznawające myśli i zdania serdeczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'A nie masz żadnego stworzenia, które by nie było jawne przed obliczem jego; owszem wszystkie rzeczy obnażone są i odkryte oczom tego, o którym mówimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Przetoż mając najwyższego kapłana wielkiego, który przeniknął niebiosa, Jezusa, Syna Bożego, trzymajmyż się tego wyznania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Albowiem nie mamy najwyższego kapłana, który by nie mógł z nami cierpieć krewkości naszych, lecz skuszonego we wszystkiem na podobieństwo nas, oprócz grzechu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Przystąpmyż tedy z ufnością do tronu łaski, abyśmy dostąpili miłosierdzia i łaskę znaleźli ku pomocy czasu przygodnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Albowiem każdy najwyższy kapłan z ludzi wzięty, za ludzi bywa postanowiony w tych rzeczach, które do Boga należą, to jest, aby ofiarował dary i ofiary za grzechy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Który by mógł, jako przystoi, użalić się nieumiejętnych i błądzących, będący sam obłożony krewkością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'A dla tej jest powinien, jako za lud, tak i sam za się ofiarować za grzechy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'A nikt sobie tej czci nie bierze, tylko ten, który bywa powołany od Boga jako i Aaron.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Tak i Chrystus nie sam sobie tej czci przywłaszczył, aby się stał najwyższym kapłanem; ale ten, który mu rzekł: Syn mój jesteś ty, jam cię dziś spłodził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Jako i na inszem miejscu mówi: Tyś jest kapłanem na wieki według porządku Melchisedekowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Który za dni ciała swego modlitwy i uniżone prośby do tego, który go mógł zachować od śmierci, z wołaniem wielkiem i ze łzami ofiarował, i wysłuchany jest dla uczciwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'A choć był Synem Bożym, wszakże z tego, co cierpiał, nauczył się posłuszeństwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'A tak doskonałym będąc, stał się wszystkim sobie posłusznym przyczyną zbawienia wiecznego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Nazwany będąc od Boga kapłanem najwyższym według porządku Melchisedekowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'O którym wiele by się miało mówić i trudnych rzeczy do wyłożenia; aleście się wy stali leniwi ku słuchaniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Albowiem mając być nauczycielami względem czasu, zasię potrzebujecie, aby was uczono, które są pierwsze początki mów Bożych, i staliście się jako mleka potrzebujący, a nie twardego pokarmu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Bo każdy, co się tylko mlekiem karmi, ten nie jest powiadomy mowy sprawiedliwości: (gdyż jest niemowlątkiem),');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Aleć doskonałym należy twardy pokarm, to jest tym, którzy przez przyzwyczajenie mają zmysły wyćwiczone ku rozeznaniu dobrego i złego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Przetoż zaniechawszy początkowych nauk o Chrystusie, miejmy się ku doskonałości, nie znowu zakładając grunty pokuty od uczynków martwych i wiary w Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Nauki o chrzcie i o wkładaniu rąk, i o powstaniu umarłych, i o sądzie wiecznym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'A to uczynimy, jeźli tylko Bóg dopuści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Albowiem niemożebne jest, aby ci, którzy są raz oświeceni i skosztowali daru niebieskiego, i uczestnikami się stali Ducha Świętego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'Skosztowali też dobrego słowa Bożego i mocy przyszłego wieku,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Gdyby odpadli, aby się zaś odnowili ku pokucie, jako ci, którzy sobie znowu krzyżują Syna Bożego i jawnie go sromocą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Albowiem ziemia, która często na się przychodzący deszcz pije i rodzi ziele przygodne tym, którzy ją sprawują, bierze błogosławieństwo od Boga;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Lecz która przynosi ciernie i osty, odrzucona jest i bliska przeklęstwa, która na koniec bywa spalona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'A wszakże, najmilsi! pewniśmy o was coś lepszego i zbawienia bliższego, chociaż tak mówimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Albowiem nie jest Bóg niesprawiedliwy, aby zapamiętał pracy waszej i pracowitej miłości, którąście okazali ku imieniu jego, gdyście służyli świętym i jeszcze służycie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'A żądamy, aby każdy z was toż staranie pokazywał ku nabyciu zupełnej nadziei aż do końca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Abyście nie byli gnuśnymi, ale naśladowcami tych, którzy przez wiarę i cierpliwość odziedziczyli obietnicę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Albowiem Bóg obietnicę czyniąc Abrahamowi, gdy nie miał przez kogo większego przysiąc, przysiągł przez siebie samego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Mówiąc: Zaiste błogosławiąc błogosławić ci będę i rozmnażając rozmnożę cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'A tak długo czekając, dostąpił obietnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Ludzieć wprawdzie przez większego przysięgają, a przysięga, która się dzieje ku potwierdzeniu, jest między nimi końcem wszystkich sporów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Dlatego też Bóg chcąc dostatecznie okazać dziedzicom obietnicy nieodmienność rady swojej, uczynił na to przysięgę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Abyśmy przez dwie rzeczy nieodmienne (w których niemożebne, aby Bóg kłamał), warowną pociechę mieli, my, którzyśmy się uciekli ku otrzymaniu wystawionej nadziei,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Którą mamy jako kotwicę duszy, i bezpieczną, i pewną, i wchodzącą aż wewnątrz za zasłonę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Gdzie przewodnik dla nas wszedł, Jezus, stawszy się według porządku Melchisedekowego najwyższym kapłanem na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Albowiem ten Melchisedek był król Salem, kapłan Boga najwyższego, który zaszedł drogę Abrahamowi, gdy się wracał od porażki królów i błogosławił mu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Któremu i dziesięciny ze wszystkiego udzielił Abraham; który najprzód wykłada się król sprawiedliwości, potem też król Salem, co jest król pokoju.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Bez ojca, bez matki, bez rodu, ani początku dni, ani końca żywota nie mając, ale przypodobany będąc Synowi Bożemu, zostaje kapłanem na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Obaczcież tedy, jako wielki ten był, któremu też dziesięcinę z łupów dał Abraham patryjarcha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'A ci, którzy są z synów Lewiego, urząd kapłański przyjmujący, rozkazanie mają, aby brali dziesięcinę od ludu według zakonu, to jest od braci swoich, choć wyszli z biódr Abrahamowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Ale ten, którego ród nie jest poczytany między nimi, dziesięcinę wziął od Abrahama i temu, który miał obietnicę, błogosławił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'A bez wszelkiego sporu mniejszy od większego błogosławieństwo bierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'A tuć dziesięciny biorą ludzie, którzy umierają; tam zasię on, o którym świadczono, iż żyje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'A iż tak rzekę i sam Lewi, który dziesięciny bierze, dał w Abrahamie dziesięcinę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Albowiem jeszcze był w biodrach ojcowskich, gdy wyszedł przeciwko niemu Melchisedek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'A przetoż byłali doskonałość przez kapłaństwo lewickie, (gdyż za niego wydany jest zakon ludowi), jakaż tego jeszcze była potrzeba, aby inszy kapłan według porządku Melchisedekowego powstał, a nie był według porządku Aaronowego mianowany?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'A ponieważ kapłaństwo jest przeniesione, musi też i zakon przeniesiony być.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Bo ten, o którym się to mówi, inszego jest pokolenia, z którego żaden nie służył ołtarzowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Albowiem jawna jest, iż z pokolenia Judowego poszedł Pan nasz, o którem pokoleniu nic z strony kapłaństwa nie mówi Mojżesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Owszem obficie to jeszcze i z tego jawna jest, iż powstał inszy kapłan według porządku Melchisedekowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Który się stał nie według zakonu przykazania cielesnego, ale według mocy żywota nieskazitelnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Albowiem tak świadczy: Tyś jest kapłanem na wieki według porządku Melchisedekowego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Bo się stało zniesienie onego przyszłego przykazania dla słabości jego i niepożytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Bo niczego do doskonałości nie przywiódł zakon; ale na miejsce jego wprowadzona jest lepsza nadzieja, przez którą się przybliżamy do Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'A to i względem tego, że nie bez przysięgi jest wprowadzona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Boć się oni bez przysięgi kapłanami stawali, a ten z przysięgą przez tego, który rzekł do niego: Przysiągł Pan, a nie będzie tego żałował: Tyś jest kapłanem na wieki według porządku Melchisedekowego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'Tak dalece lepszego przymierza rękojmią stał się Jezus.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Więc też onych wiele bywało kapłanów dlatego, iż im śmierć nie dopuściła zawsze trwać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Ale ten, iż na wieki zostaje, wieczne ma kapłaństwo,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Przetoż i doskonale zbawić może tych, którzy przez niego przystępują do Boga, zawsze żyjąc, aby orędował za nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Takiegoć zaiste przystało nam mieć najwyższego kapłana, świętego, niewinnego, niepokalanego, odłączonego od grzeszników i który by się stał wyższy nad niebiosa:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Który by nie potrzebował na każdy dzień, jako oni najwyżsi kapłani, pierwej za swoje grzechy własne ofiar sprawować, a potem za ludzkie; bo to uczynił raz samego siebie ofiarowawszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Albowiem zakon ludzi podległych krewkości stanowił za najwyższych kapłanów: ale słowo przysięgi, które się stało po zakonie, postanowiło Syna Bożego doskonałego na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Ale suma tego, co się mówi, ta jest: Iż takiego mamy najwyższego kapłana, który usiadł na prawicy stolicy wielmożności na niebiesiech;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Sługą będąc świątnicy, a prawdziwego onego przybytku, który Pan zbudował, a nie człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Albowiem każdy najwyższy kapłan ku ofiarowaniu darów i ofiar bywa postanowiony, skąd potrzeba było, aby i ten miał, co by ofiarował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Bo gdyby był na ziemi, nie byłby kapłanem, póki by zostawali oni kapłani, którzy według zakonu dary ofiarują,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Którzy służą kształtowi i cieniowi rzeczy niebieskich, jako Mojżeszowi od Boga powiedziane było, gdy miał dokończyć przybytku: Patrzajże, (mówi), abyś uczynił wszystko według kształtu, który ci jest okazany na tej górze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Ale teraz nasz kapłan tem zacniejszego urzędu dostąpił, im jest pośrednikiem lepszego przymierza, które lepszemi obietnicami jest utwierdzone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Bo gdyby ono pierwsze było bez przygany, tedyćby wtóremu nie szukano miejsca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Albowiem ganiąc Żydów, mówi: Oto dni idą, mówi Pan, gdy uczynię z domem Izraelskim i z domem Judzkim przymierze nowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Nie według przymierza, którem uczynił z ojcami ich w dzień, któregom ich ujął za rękę ich, abym ich wywiódł z ziemi Egipskiej; albowiem oni nie zostali w tem przymierzu mojem, a Jam ich zaniedbał, mówi Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Przetoż toć jest przymierze, które postanowię z domem Izraelskim po tych dniach, mówi Pan: Dam prawa moje w myśl ich i na sercach ich napiszę je, i będę Bogiem ich, a oni będą ludem moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'I nie będzie uczył żaden bliźniego swego, i żaden brata swego, mówiąc: Poznaj Pana; albowiem wszyscy mię poznają, od najmniejszego z nich aż do największego z nich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Bo miłościw będę nieprawościom ich, a grzechów ich i nieprawości ich nie wspomnę więcej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'A gdy mówi: Nowe, pierwsze czyni wiotchem; a to, co wiotszeje i zestarzeje się, bliskie jest zniszczenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'A miałoć i pierwsze ono przymierze ustawy około służby Bożej i świątnicę świecką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Albowiem sprawiony był przybytek pierwszy, w którym był świecznik, i stół, i pokładne chleby, który zwano świątnicą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'A za drugą zasłoną był przybytek, który zwano świątnicą najświętszą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Mając złotą kadzielnicę i skrzynię przymierza zewsząd złotem powleczoną, w której było wiadro złote, mające w sobie mannę, i laska Aaronowa, która była zakwitnęła, i tablice przymierza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'A nad skrzynią byli Cherubinowie chwały, którzy zacieniali ubłagalnię, o których rzeczach teraz nie potrzeba mówić o każdej z osobna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'A to gdy tak przygotowano, do pierwszego przybytku zawsze wchodzą kapłani, służby Boże odprawując;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'Ale do drugiego raz w rok sam najwyższy kapłan, nie bez krwi, którą ofiaruje sam za się i za ludzkie niewiadomości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Przez co daje znać Duch Święty, iż jeszcze nie była objawiona droga do świątnicy, póki jeszcze trwał pierwszy przybytek,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Który był wzorem na ten teraźniejszy czas, w którym dary i ofiary bywają ofiarowane, które nie mogą w sumieniu doskonałym uczynić tego, co służbę Bożą odprawuje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Tylko w pokarmach i w napojach, i w różnych omywaniach, i w ustawach cielesnych aż do czasu naprawienia włożone były.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Ale Chrystus przyszedłszy, najwyższy kapłan przyszłych dóbr, przez większy i doskonalszy przybytek, nie ręką zbudowany, to jest nie tego budynku;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Ani przez krew kozłów i cielców, ale przez własną krew swoję wszedł raz do świątnicy, znalazłszy wieczne odkupienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Albowiem jeźli krew wołów i kozłów, i popiół jałowicy pokrapiający splugawione poświęca ku oczyszczeniu ciała:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'Jakoż daleko więcej krew Chrystusowa, który przez Ducha wiecznego samego siebie ofiarował nienaganionym Bogu, oczyści sumienie wasze od uczynków martwych ku służeniu Bogu żywemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'I dlatego jest nowego testamentu pośrednikiem, aby gdyby śmierć nastąpiła na odkupienie onych występków, które były pod pierwszym testamentem, ci którzy są powołani, wzięli obietnicę wiecznego dziedzictwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Albowiem gdzie jest testament, potrzeba, aby śmierć nastąpiła tego, który czyni testament.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Bo testament tych, którzy zmarli, mocny jest, gdyż jeszcze nie jest ważny, póki żyje ten, co testament uczynił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Skąd ani on pierwszy testament bez krwi nie był poświęcony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Albowiem gdy Mojżesz wszystko przykazanie według zakonu opowiedział wszystkiemu ludowi, wziąwszy krew cielców i kozłów z wodą i z wełną szarłatową, i z hizopem, i same księgi, i lud wszystek pokropił,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Mówiąc: Tać jest krew przymierza, które wam Bóg przykazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Do tego i przybytek, i wszystko naczynie do służby Bożej należące krwią także pokropił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'A niemal wszystko według zakonu krwią oczyszczone bywa, a bez rozlania krwi nie bywa odpuszczenie grzechów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'A tak potrzeba było, aby kształty onych rzeczy, które są na niebie, temi rzeczami były oczyszczone, a same rzeczy niebieskie lepszemi ofiarami, niżeli te.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Albowiem Chrystus nie wszedł do świątnicy ręką uczynionej, która by była wizerunkiem prawdziwej, ale do samego nieba, aby się teraz okazywał przed oblicznością Bożą za nami,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'A nie iżby często ofiarował samego siebie, jako najwyższy kapłan wchodzi do świątnicy co rok ze krwią cudzą;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, '(Bo inaczej musiałby był częstokroć cierpieć od początku świata), lecz teraz przy skończeniu wieków raz objawiony jest ku zgładzeniu grzechu przez ofiarowanie samego siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'A jako postanowiono ludziom raz umrzeć, a potem będzie sąd:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Tak i Chrystus, raz będąc ofiarowany na zgładzenie wielu grzechów, drugi raz się bez grzechu okaże tym, którzy go oczekują ku zbawieniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Albowiem zakon mając cień przyszłych dóbr, a nie sam obraz rzeczy, jednakiemiż ofiarami, które na każdy rok ustawicznie ofiarują, nigdy nie może tych, którzy do nich przystępują, doskonałymi uczynić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Bo inaczej przestano by ich było ofiarować, przeto żeby już nie mieli żadnego sumienia o grzechy ci, którzy ofiarują, będąc raz oczyszczeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'Ale przy tych ofiarach dzieje się przypomnienie grzechów na każdy rok.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Albowiem nie można rzec, aby krew wołów i kozłów miała gładzić grzechy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Przetoż wchodząc na świat, mówi: Ofiary i obiaty nie chciałeś, aleś mi ciało sposobił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'Całopalenia i ofiary za grzech nie upodobałyć się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Tedym rzekł: Oto idę (na początku księgi napisano o mnie), abym czynił, o Boże! wolę twoję;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Powiedziawszy wyżej: Żeś ofiary i obiaty, i całopalenia za grzech nie chciał, ani sobie upodobał, (które według zakonu bywają ofiarowane).');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Tedy rzekł: Oto idę, abym czynił, o Boże wolę twoję; znosi pierwsze, aby wtóre postanowił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Przez którą wolę jesteśmy poświęceni przez ofiarę ciała Jezusa Chrystusa raz uczynioną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'A wszelkić kapłan stoi na każdy dzień, służbę Bożą odprawując, a jednakież ofiary częstokroć ofiarując, które nigdy grzechów zgładzić nie mogą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Lecz ten jednę ofiarę ofiarowawszy za grzechy, na wieki siedzi na prawicy Bożej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Na koniec oczekując, ażby położeni byli nieprzyjaciele jego podnóżkiem nóg jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Albowiem jedną ofiarą doskonałymi uczynił na wieki tych, którzy bywają poświęceni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'A świadczy nam to i sam Duch Święty; albowiem powiedziawszy pierwej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Toć jest przymierze, które postanowię z nimi po onych dniach, mówi Pan: Dam prawa moje do serca ich, a na myślach ich napiszę je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'A grzechów ich i nieprawości ich nie wspomnę więcej:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'A gdzieć jest odpuszczenie ich, jużci więcej ofiary nie potrzeba za grzech.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Mając tedy, bracia! wolność, wnijść do świątnicy przez krew Jezusową,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, '(Drogą nową i żywą, którą nam poświęcił przez zasłonę, to jest przez ciało swoje.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'I kapłana wielkiego nad domem Bożym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'Przystąpmyż z prawdziwem sercem w zupełności wiary, mając oczyszczone serca od sumienia złego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'I omyte ciało wodą czystą, trzymajmy wyznanie nadziei niechwiejące się; (boć wierny jest ten, który obiecał;)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'I przypatrujmy się jedni drugim ku pobudzaniu się do miłości i do dobrych uczynków,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Nie opuszczając społecznego zgromadzenia naszego, jako niektórzy obyczaj mają, ale napominając jedni drugich, a to tem więcej, czem więcej widzicie, iż się on dzień przybliża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Albowiem jeźlibyśmy dobrowolnie grzeszyli po wzięciu znajomości prawdy, nie zostawałaby już ofiara za grzechy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Ale straszliwe niejakie oczekiwanie sądu i zapalenie ognia, który pożreć ma przeciwników.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Kto by odrzucił zakon Mojżeszowy, bez miłosierdzia za świadectwem dwóch albo trzech umiera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Co się wam zda? Jakoż sroższego karania godzien jest ten, kto by Syna Bożego podeptał i krew przymierza, przez którą był poświęcony, za pospolitą miał, i Ducha łaski zelżył?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Albowiem znamy tego, który powiedział: Mnie pomsta, Ja oddam, mówi Pan; i zasię: Pan sądzić będzie lud swój.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Strasznać rzecz jest wpaść w ręce Boga żywego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Wspomnijcie na dni pierwsze, w których będąc oświeceni, znosiliście wielki bój utrapienia,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Lubo to, gdyście byli i urąganiem, i utrapieniem na podziw wystawieni lub też gdyście się stali uczestnikami tych, z którymi się tak obchodzono.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Albowiemeście i z więzienia mego ze mną utrapieni byli i rozchwycenie majętności waszych przyjęliście z radością, wiedząc, że macie w sobie lepszą majętność w niebie, i trwającą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Przetoż nie odrzucajcie ufności waszej, która ma wielką zapłatę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Albowiem cierpliwości wam potrzeba, abyście wolę Bożą czyniąc, odnieśli obietnicę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Boć jeszcze bardzo, bardzo maluczko, a oto ten, który ma przyjść, przyjdzie, a nie omieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'A sprawiedliwy z wiary żyć będzie; a jeźliby się kto schraniał, nie kocha się w nim dusza moja.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Lecz my nie jesteśmy z tych, którzy się schraniają ku zginieniu, ale z tych, którzy wierzą ku pozyskaniu duszy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'A wiara jest gruntem tych rzeczy, których się spodziewamy i dowodem rzeczy niewidzialnych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Albowiem przez nią świadectwa doszli przodkowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Wiarą rozumiemy, iż świat jest sprawiony słowem Bożem, tak iż rzeczy, które widzimy, nie stały się z rzeczy widzialnych, ale z niczego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Wiarą lepszą ofiarę ofiarował Abel Bogu, niżeli Kain, przez którą świadectwo otrzymał, że jest sprawiedliwy, jakoż sam Bóg świadectwo dał o darach jego, a przez te umarłszy jeszcze mówi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Wiarą Enoch jest przeniesiony, aby nie oglądał śmierci i nie jest znaleziony, przeto że go Bóg przeniósł; albowiem pierwej niż jest przeniesiony, miał świadectwo, że się podobał Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'A bez wiary nie można podobać się Bogu; albowiem ten, co przystępuje do Boga, wierzyć musi, że jest Bóg, a że nagrodę daje tym, którzy go szukają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Wiarą obwieszczony będąc od Boga Noe o tem, czego jeszcze nie było widzieć, uczciwości wyświadczając, przygotował korab ku zachowaniu domu swego, przez który potępił świat i stał się dziedzicem sprawiedliwości tej, która jest z wiary.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Wiarą powołany będąc Abraham, usłuchał Boga, aby poszedł na ono miejsce, które miał wziąć za dziedzictwo i wyszedł, nie wiedząc, dokąd idzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Wiarą mieszkał w ziemi obiecanej jako w cudzej, mieszkając w namiotach z Izaakiem i z Jakóbem, spólnymi dziedzicami tejże obietnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Albowiem oczekiwał miasta mającego grunty, którego sprawcą i budownikiem jest Bóg.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Wiarą także Sara wzięła moc ku przyjęciu nasienia i mimo czasu wieku porodziła, gdyż miała za wiernego tego, który obiecał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'A przetoż z jednego, i to obumarłego, rozpłodziło się potomstwo jako mnóstwo gwiazd niebieskich i jako piasek niezliczony, który jest na brzegu morskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Według wiary umarli ci wszyscy, nie wziąwszy obietnic, ale z daleka je upatrując i cieszyli się niemi, i witali je i wyznawali, iż są gośćmi i przychodniami na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Bo ci, którzy tak mówią, jawnie okazują, iż ojczyzny szukają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'A wprawdzie, gdyby byli na onę pamiętali, z której byli wyszli, mieli dosyć czasu wrócić się zaś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Ale oni lepszej żądają, to jest niebieskiej; przetoż i sam Bóg nie wstydzi się nazywać Bogiem ich, bo im miasto zgotował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Wiarą ofiarował Abraham Izaaka, będąc kuszony, a ofiarował jednorodzonego ten, który był wziął obietnicę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'Do którego rzeczono: W Izaaku tobie będzie nazwane nasienie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Uważając to, iż Bóg może i od umarłych wzbudzić; skąd go też w podobieństwie zmartwychwstania przyjął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Wiarą około przyszłych rzeczy błogosławił Izaak Jakóba i Ezawa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Wiarą Jakób umierając, każdemu z synów Józefowych błogosławił i pokłonił się podparłszy się na wierzch laski swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Wiarą Józef umierając, o wyjściu synów Izraelskich wzmiankę uczynił i z strony kości swoich rozkazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Wiarą narodziwszy się Mojżesz, był ukryty przez trzy miesiące od rodziców swoich, przeto że widzieli nadobne dzieciątko i nie bali się wyroku królewskiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Wiarą Mojżesz, będąc już dorosłym, zbraniał się być zwany synem córki Faraonowej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Raczej sobie obrawszy złe rzeczy cierpieć z ludem Bożym, niżeli doczesną mieć z grzechu rozkosz,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Za większe pokładając bogactwo nad skarby Egipskie urąganie Chrystusowe; bo się oglądał na odpłatę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Wiarą opuścił Egipt, nie bojąc się gniewu królewskiego; bo jakoby widział niewidzialnego, mężnie sobie poczynał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Wiarą obchodził wielkanoc i wylanie krwi, aby ten, który tracił pierworodnych, nie dotknął się ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Wiarą przeszli przez morze Czerwone, jako po suszy, o co kusiwszy się Egipczanie, potonęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Wiarą mury Jerycha upadły, gdy je obchodzono przez siedm dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Wiarą Rachab wszetecznica nie zginęła wespół z nieposłusznymi, przyjąwszy z pokojem szpiegów do gospody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'A cóż więcej mam mówić? Bo by mi czasu nie stało, gdybym miał powiadać o Giedeonie i o Baraku, i o Samsonie, i o Jefcie, i o Dawidzie, i o Samuelu, i o prorokach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Którzy przez wiarę zwalczyli królestwa, czynili sprawiedliwość, dostępowali obietnic, lwom paszczęki zawierali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'Zagaszali moc ognia, uchodzili ostrza mieczów, mocnymi się stawali z niemocnych, mężnymi bywali na wojnie, wojska cudzoziemców do uciekania przywodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Niewiasty odbierały umarłych swoich wzbudzonych; a drudzy są na próbach rozciągnieni, nie przyjąwszy wybawienia, aby lepszego dostąpili zmartwychwstania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Drudzy zasię pośmiewisk i biczowania doświadczyli, nadto i związek i więzienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Byli kamionowani, piłą przecierani, kuszeni, mieczem zabijani, chodzili w owczych i kozich skórach; byli w niedostatku, w ucisku, w niewczasach;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(Których nie był świat godzien;) tułali się po pustyniach i po górach, i jaskiniach, i jamach ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'A ci wszyscy świadectwo otrzymawszy przez wiarę, nie dostąpili obietnicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Przeto, że Bóg o nas coś lepszego przejrzał, aby oni bez nas nie stali się doskonałymi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Przetoż i my, mając tak wielki około siebie leżący obłok świadków, złożywszy wszelaki ciężar i grzech, który nas snadnie obstępuje, przez cierpliwość bieżmy w zawodzie, który nam jest wystawiony;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Patrząc na Jezusa, wodza i dokończyciela wiary, który dla wystawionej sobie radości, podjął krzyż, wzgardziwszy sromotę, i usiadł na prawicy stolicy Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Przetoż uważajcie, jaki jest ten, który podejmował takowe od grzeszników przeciwko sobie sprzeciwianie, abyście osłabiwszy w umysłach waszych, nie ustawali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Jeszczeście się aż do krwi nie sprzeciwili, walcząc przeciwko grzechowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Czyliście zapamiętali napominania, które wam jako synom mówi: Synu mój, nie lekceważ sobie kaźni Pańskiej, a nie trać serca, gdy od niego bywasz karany;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Albowiem kogo Pan miłuje, tego karze, a smaga każdego, którego za syna przyjmuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Jeźli znosicie karanie, Bóg się wam ofiaruje jako synom; albowiem któryż jest syn, którego by ojciec nie karał?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'A jeźli jesteście bez karania, którego wszyscy są uczestnikami, tedy jesteście bękartami, a nie synami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'A nadto cielesnych ojców naszych mieliśmy, którzy nas karali, a baliśmy się ich; zaż daleko więcej nie mamy być poddani Ojcu duchów, abyśmy żyli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Albowiem oni na mało dni, jako się im zdało, nas karali; ale ten ku pożytkowi naszemu na to, abyśmy byli uczestnikami świętobliwości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'A wszelkie karanie, gdy przytomne jest, nie zda się być wesołe, ale smutne; lecz potem owoc sprawiedliwości spokojny przynosi tym, którzy są przez nie wyćwiczeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Przeto opuszczone ręce i zemdlone kolana wyprostujcie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'A czyńcie koleje proste nogami waszemi, iżby to, co jest chromego, z drogi nie ustąpiło, ale raczej uzdrowione było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Pokoju naśladujcie ze wszystkimi i świętobliwości, bez której żaden nie ogląda Pana;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Upatrując, żeby kto nie odpadł od łaski Bożej, a żeby który korzeń gorzkości nie podrósł, a nie przekaził i przez niego, aby się ich wiele nie pokalało;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Aby kto nie był wszetecznym albo sprośnym jako Ezaw, który za potrawę jedną sprzedał pierworodztwo swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Albowiem wiecie, iż i potem, gdy chciał odziedziczyć błogosławieństwo, był odrzucony; bo nie znalazł miejsca pokuty, choć jej z płaczem szukał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Boście nie przystąpili do góry, która się da dotknąć, i do ognia gorejącego, i do wichru, i do ciemności i do burzy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'I do dźwięku trąby, i do głosu słów, który ci, co słyszeli, prosili, aby więcej do nich nie mówiono;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, '(Albowiem nie mogli znieść tego, co im rozkazywano: Gdyby się i bydlę góry dotknęło, będzie ukamionowane, albo pociskiem przebite.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'A tak straszne to było, co widzieli, że też Mojżesz rzekł: Uląkłem się i drżę.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Aleście przystąpili do góry Syon i do miasta Boga żywego, do Jeruzalemu niebieskiego, i do niezliczonych tysięcy Aniołów;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Do walnego zgromadzenia, i do zebrania pierworodnych, którzy są spisani w niebie, i do Boga, sędziego wszystkich, i do duchów sprawiedliwych i doskonałych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'I do pośrednika nowego testamentu, Jezusa, i do krwi pokropienia, lepsze rzeczy mówiącej niż Ablowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Patrzajcież, abyście nie gardzili tym, który mówi; albowiem jeźliż oni nie uszli, którzy gardzili tym, który na ziemi na miejscu Bożem mówił, daleko więcej my, jeźliże się od tego, który z nieba jest, odwrócimy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Którego głos na on czas poruszył był ziemią, a teraz obiecał, mówiąc: Jeszcze ja raz poruszę nie tylko ziemią, ale i niebem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'A to też mówi: Jeszcze raz, pokazuje zniesienie rzeczy chwiejących się, jako tych, które są uczynione, aby zostawały te, które się nie chwieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Przetoż przyjmując królestwo nie chwiejące się, miejmy łaskę, przez którą służymy przyjemnie Bogu ze wstydem i z uczciwością.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Albowiem Bóg nasz jest ogniem trawiącym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Miłość braterska niech zostaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Nie zapominajcie ochoty ku gościom; albowiem przez tę niektórzy nie wiedząc, Anioły za goście przyjmowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Pamiętajcie na więźniów, jakobyście spółwięźniami byli; na utrapionych, jako ci, którzy też w ciele jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Uczciwe jest małżeństwo między wszystkimi i łoże niepokalane; ale wszeteczników i cudzołożników Bóg będzie sądził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Obcowanie wasze niech będzie bez łakomstwa, przestwając na tem, co macie; boć sam powiedział: Nie zaniecham cię, ani cię opuszczę:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Tak abyśmy śmiele mówić mogli: Pan mi jest pomocnikiem, nie będę się bał, aby mi co miał uczynić człowiek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Pamiętajcie na wodzów waszych, którzy wam mówili słowo Boże, których obcowania koniec upatrując naśladujcie wiary ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jezus Chrystus wczoraj i dziś, tenże i na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Za naukami rozmaitemi i obcemi nie unoście się; albowiem dobra rzecz jest, aby łaską było utwierdzone serce a nie pokarmami, które nie pomogły tym, co się nimi bawili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Mamy ołtarz, z którego nie mają wolności jeść ci, którzy przybytkowi służą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Albowiem bydląt, których krew bywa wnoszona za grzech do świątnicy przez najwyższego kapłana, tych ciała palone bywają za obozem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Dlatego i Jezus, aby poświęcił lud własną krwią swoją, za bramą ucierpiał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Wynijdźmyż tedy do niego za obóz, nosząc urąganie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Albowiem nie mamy tu miasta trwałego, ale onego przyszłego szukamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Przetoż przez niego ofiarujmy Bogu ofiarę chwały ustawicznie, to jest owoce warg wyznawających imieniowi jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'A dobroczynności i udzielania nie przepominajcie; albowiem się Bóg w takowych ofiarach kocha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Bądźcie posłuszni wodzom waszym i bądźcie im oddani; albowiem oni czują nad duszami waszemi, jako ci, którzy liczbę oddać mają; aby to z radością czynili, a nie z wzdychaniem; boć wam to nie jest pożyteczne.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Módlcie się za nami; albowiem ufamy, iż mamy dobre sumienie, jako ci, którzy się chcemy we wszystkiem dobrze zachować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'A tem więcej proszę was, abyście to czynili, abym wam tem rychlej był przywrócony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'A Bóg pokoju, który wywiódł od umarłych we krwi przymierza wiecznego, onego wielkiego pasterza owiec, Pana naszego Jezusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Niech was doskonałymi uczyni w każdym uczynku dobrym ku czynieniu woli swojej, sprawując w was to, co przyjemnego przed obliczem jego, przez Jezusa Chrystusa, któremu niech będzie chwała na wieki wieków. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'A proszę was, bracia! znoście cierpliwie słowo napominania tego; bomci do was krótko pisał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Wiedzcie o bracie Tymoteuszu, że jest wypuszczony, z którym (jeźlibym szybko przyszedł), oglądam was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Pozdrówcie wszystkich wodzów waszych i wszystkich świętych. Pozdrawiają was bracia z Włoch.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Łaska niech będzie z wami wszystkimi. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakób, sługa Boży i Pana Jezusa Chrystusa, dwunastu pokoleniom, które są w rozproszeniu, zdrowia życzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Za największą radość miejcie, bracia moi! gdy w rozmaite pokusy wpadacie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Wiedząc, iż doświadczenie wiary waszej sprawuje cierpliwość;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'A cierpliwość niech ma doskonały uczynek, żebyście byli doskonali i zupełni, którym by na niczem nie schodziło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'A jeźli komu z was schodzi na mądrości, niech prosi u Boga, który ją szczerze wszystkim daje, a nie wymawia; i będzie mu dana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Ale niech prosi z wiarą, nic nie wątpiąc; albowiem kto wątpi, jest podobny wałowi morskiemu, który od wiatru pędzony i miotany bywa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Bo niechaj nie mniema ten człowiek, aby co miał wziąć od Pana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Mąż umysłu dwoistego jest niestateczny we wszystkich drogach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'A niech się chlubi brat niskiego stanu w wywyższeniu swojem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'A bogaty w poniżeniu swojem; bo jako kwiat trawy przeminie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Albowiem jako słońce, kiedy weszło z gorącością, ususzyło trawę, a kwiat jej opadł i zginęła ona śliczność kształtu jego, tak i bogaty w drogach swoich uwiędnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Błogosławiony mąż, który znosi pokuszenie; bo gdy będzie doświadczony, weźmie koronę żywota, którą obiecał Pan tym, którzy go miłują.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Żaden, gdy bywa kuszony, niech nie mówi: Od Boga kuszony bywam; bo Bóg nie może kuszony być we złem, a sam nikogo nie kusi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Ale każdy bywa kuszony, gdy od swoich własnych pożądliwości bywa pociągniony i przynęcony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Zatem pożądliwość począwszy, rodzi grzech, a grzech będąc wykonany, rodzi śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Nie błądźcież, bracia moi mili!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Wszelki datek dobry i wszelki dar doskonały z góry jest, zstępujący od Ojca światłości, u którego nie masz odmiany, ani zaćmienia na wstecz się wracającego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Który, przeto że chciał, porodził nas słowem prawdy ku temu, żebyśmy byli niejakiemi pierwiastkami stworzenia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'A tak, bracia moi mili! niech będzie każdy człowiek prędki ku słuchaniu, ale nierychły ku mówieniu i nierychły ku gniewowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Bo gniew męża nie sprawuje sprawiedliwości Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'A tak odrzuciwszy wszelakie plugastwo i zbytek złości, z cichością przyjmijcie słowo wszczepione, które może zbawić dusze wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'A bądźcie czynicielami słowa, a nie słuchaczami tylko, oszukiwającymi samych siebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Albowiem jeźli kto jest słuchaczem słowa a nie czynicielem, ten podobny jest mężowi przypatrującemu się obliczu narodzenia swego we zwierciadle;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Bo samego siebie obejrzał i odszedł, a wnet zapomniał, jakim był.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Ale kto by wejrzał w on doskonały zakon wolności i zostawałby w nim, ten nie będąc słuchaczem zapamiętliwym, ale czynicielem uczynku, ten błogosławionym będzie w uczynku swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Jeźli kto między wami zda się być nabożnym, nie kiełznając języka swego, ale zwodząc serce swe, tego nabożeństwo próżne jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Nabożeństwo czyste i niepokalane u Boga i Ojca to jest: Nawiedzać sieroty i wdowy w ucisku ich i zachować samego siebie niepokalanym od świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Bracia moi! nie miejcie z brakowaniem osób wiary Pana naszego Jezusa Chrystusa, który chwalebny jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Albowiem gdyby wszedł do zgromadzenia waszego mąż, mając pierścień złoty w szacie świetnej, a wszedłby też i ubogi w podłym odzieniu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'I wejrzelibyście na tego, co ma świetną szatę, a rzeklibyście mu: Ty! siądź sam poczciwie! a ubogiemu byście rzekli: Ty! tam stój, albo siądź tu pod podnóżkiem moim!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Azażeście już nie uczynili różności między sobą i nie staliście się sędziami myśli złych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Słuchajcie, bracia moi mili! azaż Bóg nie obrał ubogich na tym świecie, aby byli bogatymi w wierze i dziedzicami królestwa, które obiecał tym, którzy go miłują?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Aleście wy znieważyli ubogiego. Azaż bogacze gwałtem was nie uciskają i do sądów was nie pociągają?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Azaż oni nie bluźnią onego zacnego imienia, które jest wzywane nad wami?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'A jeźliże pełnicie zakon królewski według Pisma: Będziesz miłował bliźniego twego jako samego siebie, dobrze czynicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'Lecz jeźli osobami brakujecie, grzech popełniacie i bywacie przekonani od zakonu jako przestępcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Albowiem ktobykolwiek zachował wszystek zakon, a w jednym by upadł, stał się winien wszystkich przykazań.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Bo który rzekł: Nie będziesz cudzołożył, ten też rzekł: Nie będziesz zabijał, a jeźlibyś nie cudzołożył, ale byś zabił, stałeś się przestępcą zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Tak mówcie i tak czyńcie jako ci, którzy według zakonu wolności macie być sądzeni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Albowiem sąd bez miłosierdzia będzie temu, co nie czynił miłosierdzia; ale miłosierdzie chlubi się przeciwko sądowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Cóż pomoże, bracia moi! jeźliby kto rzekł, iż ma wiarę, a uczynków by nie miał? izali go ona wiara może zbawić?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'A gdyby brat albo siostra byli nieodziani i schodziłoby im na powszedniej żywności,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'I rzekłby im kto z was: Idźcie w pokoju, ugrzejcie się i najedzcie się, a nie dalibyście im potrzeb ciału należących, cóż to pomoże?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Także i wiara, nie mali uczynków, martwa jest sama w sobie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Ale rzecze kto: Ty masz wiarę, a ja mam uczynki; ukaż mi wiarę twoję bez uczynków twoich, a ja tobie ukażę wiarę moję z uczynków moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Ty wierzysz, iż jeden jest Bóg, dobrze czynisz; i dyjabli temu wierzą, wszakże drżą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Ale chceszli wiedzieć, o człowiecze marny! iż wiara bez uczynków martwa jest?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Abraham, ojciec nasz, izali nie z uczynków usprawiedliwiony jest, gdy ofiarował Izaaka, syna swego, na ołtarzu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Widzisz, iż wiara spólnie robiła z uczynkami jego, a z uczynków wiara doskonała się stała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'A tak wypełniło się Pismo, które mówi: I uwierzył Abraham Bogu, i przyczytano mu to ku sprawiedliwości, i przyjacielem Bożym nazwany jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'A widzicież, iż z uczynków usprawiedliwiony bywa człowiek, a nie z wiary tylko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Także też i Rachab, wszetecznica, izali nie z uczynków jest usprawiedliwiona, gdy przyjęła onych posłów i inszą drogą wypuściła?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Albowiem jako ciało bez duszy jest martwe, tak i wiara bez uczynków martwa jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Niechaj was niewiele będzie nauczycielami, bracia moi! wiedząc, że cięższy sąd odniesiemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Albowiem w wielu upadamy wszyscy; jeźli kto nie upada w słowie, ten jest doskonałym mężem, który też może na wodzy trzymać i wszystko ciało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Oto koniom wędzidła w gęby wprawujemy, aby nam powolne były i wszystkiem ciałem ich kierujemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Oto i okręty, choć tak wielkie są i tęgiemi wiatrami pędzone bywają, wszak i najmniejszym sterem bywają kierowane, gdziekolwiek jest wola sternikowa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Tak i język mały jest członek, wszakże bardzo się wynosi. Oto maluczki ogień, jako wielki las zapala!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'I język jest ogień i świat niesprawiedliwości; takci jest postanowiony język między członkami naszemi, który szpeci wszystko ciało i zapala koło urodzenia naszego, i bywa zapalony od ognia piekielnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Albowiem wszelkie przyrodzenie i dzikich zwierząt, i ptaków, i gadzin, i morskich potworów bywa okrócone i jest okrócone od ludzi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Ale języka żaden z ludzi okrócić nie może, który jest nieokrócone złe i pełne jadu śmiertelnego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Przez niego błogosławimy Boga i Ojca, i przez niego przeklinamy ludzi, którzy na podobieństwo Boże stworzeni są;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Z jednychże ust wychodzi błogosławieństwo i przeklęstwo. Nie tak ma być, bracia moi!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Izali zdrój z jednego źródła wypuszcza i słodką, i gorzką wodę?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Izali może, bracia moi! figowe drzewo przynosić oliwki, albo winna macica figi? Tak żaden zdrój słonej i słodkiej wody oraz nie wydaje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Jeźli kto jest mądry i umiejętny między wami? niech pokaże dobrem obcowaniem uczynki swoje w mądrej cichości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Ale jeźli macie gorzką zawiść i zajątrzenie w sercu waszem, nie chlubcież się, ani kłamcie przeciwko prawdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Nie jestci ta mądrość z góry zstępująca, ale ziemska, bydlęca, dyjabelska.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Bo gdzie jest zawiść i zajątrzenie, tam i rozterki, i wszelka zła sprawa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Ale mądrość, która jest z góry, najprzódci jest czysta, potem spokojna, mierna, powolna, pełna miłosierdzia i owoców dobrych, nieposądzająca, i nieobłudna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Ale owoc sprawiedliwości w pokoju bywa siany tym, którzy pokój czynią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Skądże są walki i zwady między wami? Izali nie stąd, to jest z lubości waszych, które walczą w członkach waszych?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Pożądacie, a nie macie, zajrzycie i zawidzicie, a nie możecie dostać; wadzicie się i walczycie, wszakże nie otrzymujecie, przeto iż nie prosicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Prosicie, a nie bierzecie, przeto iż źle prosicie, abyście to na rozkosze wasze obracali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Cudzołożnicy i cudzołożnice! nie wiecież, iż przyjaźń świata jest nieprzyjaźnią Bożą? Przetoż, ktobykolwiek chciał być przyjacielem tego świata, staje się nieprzyjacielem Bożym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Albo mniemacie, iż próżno Pismo mówi: Izali ku zazdrości pożąda duch, który w nas mieszka?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Owszem, hojniejszą daje łaskę; bo mówi: Bóg się pysznym sprzeciwia, ale pokornym łaskę daje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Poddajcież się tedy Bogu, a dajcie odpór dyjabłu, a uciecze od was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Przybliżcie się ku Bogu, a przybliży się ku wam. Ochędóżcie ręce grzesznicy i oczyście serca, którzyście umysłu dwoistego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Bądźcie utrapieni i żałujcie, i płaczcie; śmiech wasz niech się obróci w żałość, a radość w smutek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Uniżajcie się przed obliczem Pańskiem, a wywyższy was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Nie obmawiajcie jedni drugich, bracia! Kto obmawia brata i potępia brata swego, obmawia zakon i potępia zakon; a jeźli potępisz zakon, nie jesteś czynicielem zakonu, ale sędzią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Jeden jest zakonodawca, który może zbawić i zatracić. Ale ty ktoś jest, co potępiasz drugiego?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Nuż teraz wy, co mówicie: Dziś albo jutro pójdziemy do tego miasta i zamieszkamy tam przez jeden rok, a będziemy kupczyć i zysk sobie przywiedziemy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, '(Którzy nie wiecie, co jutro będzie; bo cóż jest żywot wasz? Para zaiste jest, która się na mały czas pokazuje, a potem niszczeje.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Zamiast tego, co byście mieli mówić: Będzieli Pan chciał, a będziemyli żywi, uczynimy to albo owo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Ale teraz chlubicie się w pysze waszej; wszelka chluba takowa zła jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Przetoż, kto umie dobrze czynić, a nie czyni, grzech ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Nuż teraz, bogacze! płaczcie, narzekając nad nędzami waszemi, które przyjdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Bogactwo wasze zgniło, a szaty wasze mole zgryzły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Złoto wasze i srebro wasze pordzewiało, a rdza ich będzie na świadectwo przeciwko wam i pożre ciała wasze jako ogień; zgromadziliście skarb na ostatnie dni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Oto, zapłata robotników, którzy żęli krainy wasze, od was zatrzymana woła, a wołania żeńców weszły do uszów Pana zastępów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Żyliście w rozkoszach na ziemi i bujaliście; wytuczyliście serca wasze jako na dzień zabijania ofiar.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Potępiliście, zamordowaliście sprawiedliwego, a nie sprzeciwia się wam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Przetoż, bracia! bądźcie cierpliwymi aż do przyjścia Pańskiego. Oto, oracz oczekuje drogiego pożytku ziemi, cierpliwie go oczekując, ażby otrzymał deszcz ranny i wieczorny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Bądźcież i wy cierpliwymi, a utwierdzajcie serca wasze; albowiem się przybliża przyjście Pańskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Nie wzdychajcie jedni przeciwko drugim, bracia! abyście nie byli osądzeni. Oto, sędzia już przede drzwiami stoi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Bierzcie za przykład, bracia moi! utrapienia i cierpliwości proroków, którzy mówili w imieniu Pańskiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Oto za błogosławionych mamy tych, którzy cierpieli. O cierpliwości Ijobowej słyszeliście i koniec Pański widzieliście, iż wielce miłosierny jest Pan i litościwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'A przed wszystkiemi rzeczami, bracia moi! nie przysięgajcie ani przez niebo, ani przez ziemię, ani żadną inszą przysięgą; ale niech będzie mowa wasza: Tak, tak; i Nie, nie; abyście w obłudę nie wpadli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Jest kto utrapiony między wami, niechże się modli; jest kto dobrej myśli, niechajże śpiewa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Choruje kto między wami, niechże zawoła starszych zborowych, a niech się modlą za nim, pomazując go olejkiem w imieniu Pańskiem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'A modlitwa wiary uzdrowi chorego i podniesie go Pan; a jeźliby się grzechu dopuścił, będzie mu odpuszczone.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Wyznawajcie jedni przed drugimi upadki, a módlcie się za drugimi; abyście byli uzdrowieni. Wiele może uprzejma modlitwa sprawiedliwego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elijasz był człowiek tymże biedom poddany jako i my, a modlitwą modlił się, żeby deszcz nie padał; i nie padał deszcz na ziemię trzy lata i sześć miesięcy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'I zaś się modlił, a wydało niebo deszcz i ziemia zrodziła owoce swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Bracia! jeźliby się kto z was obłądził od prawdy, a nawróciłby go kto,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Niechże wie, że kto by odwrócił grzesznika od błędnej drogi jego, zachowa duszę od śmierci i zakryje mnóstwo grzechów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Piotr, Apostoł Jezusa Chrystusa, przychodniom rozproszonym w Poncie, w Galacyi, w Kapadocyi, w Azji i w Bitynii;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Wybranym według przejrzenia Boga Ojca przez poświęcenie Ducha, ku posłuszeństwu i pokropieniu krwi Jezusa Chrystusa. Łaska wam i pokój niech będzie rozmnożony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Błogosławiony niech będzie Bóg i Ojciec Pana naszego, Jezusa Chrystusa, który według wielkiego miłosierdzia swego odrodził nas ku nadziei żywej przez zmartwychwstanie Jezusa Chrystusa od umarłych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'Ku dziedzictwu nieskazitelnemu i niepokalanemu, i niezwiędłemu, w niebiesiech dla was zachowanemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Którzy mocą Bożą strzeżeni bywacie przez wiarę ku zbawieniu, które zgotowane jest, aby było objawione czasu ostatecznego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'W czem weselicie się teraz maluczko, (jeźliże potrzeba) zasmuceni w rozmaitych pokusach,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Aby doświadczenie wiary waszej daleko droższe niż złoto, które ginie, którego jednak przez ogień doświadczają, znalezione było wam ku chwale i ku czci, i ku sławie w objawienie Jezusa Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Którego nie widziawszy, miłujecie, którego teraz nie widząc, wszakże weń wierząc, weselicie się radością niewymowną i chwalebną,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Odnosząc koniec wiary waszej: zbawienie dusz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'O którem zbawieniu wywiadywali się i badali się prorocy, którzy o tej łasce, która na was przyjść miała, prorokowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Badając się, na który albo na jaki czas objawiał Duch Chrystusowy, który w nich był, świadcząc pierwej o utrapieniach, które miały przyjść na Chrystusa i o wielkiej za tem chwale.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Którym objawione jest, iż nie samym sobie, ale nam tem usługiwali, co wam teraz zwiastowano przez tych, którzy wam kazali Ewangieliję przez Ducha Świętego z nieba zesłanego, na które rzeczy pragną patrzyć Aniołowie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Przetoż przepasawszy biodra myśli waszej i trzeźwymi będąc, doskonałą miejcie nadzieję ku tej łasce, która wam dana będzie w objawienie Jezusa Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Jako synowie posłuszni, którzy się nie przypodobywacie przeszłym w nieumiejętności waszej pożądliwościom;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Ale jako ten, który was powołał, święty jest, i wy bądźcie świętymi we wszelkiem obcowaniu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Dlatego że napisano: Świętymi bądźcie, iżem Ja jest święty.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'A ponieważ Ojcem nazywacie tego, który bez braku osób każdego sądzi według uczynku, patrzcież, abyście w bojaźni czas pielgrzymowania waszego trawili,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Wiedząc, iż nie skazitelnemi rzeczami, srebrem albo złotem, wykupieni jesteście od marnego obcowania waszego, od ojców podanego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Ale drogą krwią, jako baranka niewinnego i niepokalanego, Chrystusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Przejrzanego przed założeniem świata, a objawionego czasów ostatecznych dla was,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Którzy przez niego wierzycie w Boga, który go wzbudził od umarłych i dał mu chwałę, aby wiara i nadzieja wasza była w Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Oczyszczając dusze wasze w posłuszeństwie prawdy przez Ducha Świętego ku nieobłudnej braterskiej miłości, z czystego serca jedni drugich miłujcie uprzejmie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Odrodzeni będąc nie z nasienia skazitelnego, ale z nieskazitelnego przez słowo Boże żywe i trwające na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Ponieważ wszelkie ciało jest jako trawa i wszelka chwała człowieka jako kwiat trawy; uwiędła trawa i kwiat jej opadł;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Ale słowo Pańskie trwa na wieki. A toć jest słowo, które wam jest zwiastowane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Przetoż złożywszy wszelką złość i wszelką zdradę, i obłudę, i zazdrość, i wszelakie obmowiska,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Jako dopiero narodzone niemowlątka, szczerego mleka słowa Bożego pożądajcie, abyście przez nie urośli,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'Jeźliście tylko skosztowali, że dobrotliwy jest Pan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Do którego przystępując, do kamienia żywego, acz od ludzi odrzuconego, ale od Boga wybranego i kosztownego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'I wy jako żywe kamienie budujcie się w dom duchowny, w kapłaństwo święte, ku ofiarowaniu duchowych ofiar, przyjemnych Bogu przez Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'A przetoż mówi Pismo: Oto kładę na Syonie kamień narożny węgielny, wybrany, kosztowny; a kto w niego uwierzy, nie będzie zawstydzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Wam tedy wierzącym jest uczciwością, ale nieposłusznym, kamień, który odrzucili budujący, ten się stał głową węgielną,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'I kamieniem obrażenia, i opoką zgorszenia tym, którzy się obrażają o słowo, nie wierząc, na co też wystawieni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Ale wy jesteście rodzajem wybranym, królewskim kapłaństwem, narodem świętym, ludem nabytym, abyście opowiadali cnoty tego, który was powołał z ciemności ku dziwnej swojej światłości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Którzyście niekiedy byli nie ludem, aleście teraz ludem Bożym; którzyście niekiedy nie dostąpili byli miłosierdzia, aleście teraz miłosierdzia dostąpili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Najmilsi! proszę was, abyście się jako przychodniowie i goście wstrzymywali od cielesnych pożądliwości, które walczą przeciwko duszy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Obcowanie wasze mając poczciwe między poganami, aby zamiast tego, w czem was pomawiają jako złoczyńców, dobrym się uczynkom waszym przypatrując, chwalili Boga w dzień nawiedzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Bądźcież tedy poddani wszelkiemu ludzkiemu urzędowi dla Pana, bądź królowi, jako najwyższemu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Bądź przełożonym, jako od niego posłanym ku pomście źle czyniących, a ku chwale dobrze czyniących.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Albowiem taka jest wola Boża, abyście dobrze czyniąc, usta zatkali nieumiejętności głupich ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, '(Bądźcież) jako wolni, a nie jako ci, którzy wolność zasłoną złości mają, ale jako słudzy Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Wszystkich czcijcie, braterstwo miłujcie, Boga się bójcie, króla w uczciwości miejcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Słudzy! bądźcie poddani panom we wszelakiej bojaźni, nie tylko dobrym i bacznym, ale i dziwnym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Boć to jest łaska, jeźli kto dla sumienia Bożego ponosi frasunki, cierpiąc bezwinnie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Bo cóż jest za chwała, jeźlibyście grzesząc, cierpliwie znosili, by was i pięściami bito? Ale jeźli dobrze czyniąc i cierpiąc znosicie, to jest łaska u Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Albowiem na to też powołani jesteście, ponieważ i Chrystus cierpiał za was, zostawiwszy wam przykład, abyście naśladowali stóp jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Który grzechu nie uczynił, ani znaleziona jest zdrada w ustach jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Któremu gdy złorzeczono, nie odzłorzeczył; gdy cierpiał, nie groził, ale poruczył krzywdę temu, który sprawiedliwie sądzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Który grzechy nasze na ciele swoim zaniósł na drzewo, abyśmy obumarłszy grzechom sprawiedliwości żyli, którego sinością uzdrowieni jesteście.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Albowiemeście byli jako owce błądzące; ale teraz jesteście nawróceni do pasterza i biskupa dusz waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Także i żony! bądźcie poddane mężom swoim, aby i ci, którzy nie wierzą słowu, przez pobożne obcowanie żon, bez słowa byli pozyskani,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Obaczywszy czyste w bojaźni Bożej obcowanie wasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Których ochędostwo niech będzie nie ono zwierzchne, w splecieniu włosów i obłożeniu się złotem, albo w ubieraniu się w szaty:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Ale on skryty serdeczny człowiek, zależący w nieskażeniu cichego i spokojnego ducha, który jest przed obliczem Bożem kosztowny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Albowiem tak niekiedy i one święte małżonki, które nadzieję miały w Bogu, zdobiły się, będąc poddane mężom swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Jako Sara była posłuszną Abrahamowi nazywając go panem; której wy stałyście się córkami, gdy dobrze czynicie, nie bojąc się żadnego postrachu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Także i wy, mężowie! mieszkajcie z niemi umiejętnie, a jako mdlejszemu naczyniu niewieściemu oddawajcie uczciwość, jako też spółdziedziczkom łaski żywota, aby się modlitwy wasze nie przerywały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'A na koniec wszyscy bądźcie jednomyślni, spółcierpiący doległości, braterstwo miłujący, miłosierni i dobrotliwi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Nie oddawając złego za złe, ani łajania za łajanie, lecz przeciwnym obyczajem dobrorzecząc, gdyż wiecie, iż na to powołani jesteście, abyście błogosławieństwo odziedziczyli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Albowiem kto chce żywot miłować i oglądać dni dobre, niech pohamuje języka swego od złego, a usta jego niech nie mówią zdrady;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Niech się odwróci od złego, a czyni dobre; niech szuka pokoju i ściga go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Albowiem oczy Pańskie otworzone są na sprawiedliwych, a uszy jego ku prośbie ich; lecz oblicze Pańskie przeciwko tym, którzy czynią złe rzeczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'I któż jest, co by wam złe uczynił, jeźlibyście dobrego naśladowcami byli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Ale chociażbyście też cierpieli dla sprawiedliwości, błogosławieni jesteście, a strachu ich nie lękajcie się, ani trwożcie sobą, ale Pana Boga poświęcajcie w sercach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Bądźcie zawsze gotowi ku daniu odpowiedzi każdemu domagającemu się od was rachunku o tej nadziei, która w was jest, z cichością i z bojaźnią, mając sumienie dobre;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Aby w tem, w czem was pomawiają jako złoczyńców, zawstydzili się ci, którzy naganę dawają waszemu dobremu obcowaniu w Chrystusie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Lepiej bowiem jest, abyście dobrze czyniąc, jeźli się tak podoba woli Bożej, cierpieli, niżeli źle czyniąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Bo i Chrystus raz za grzechy cierpiał, sprawiedliwy za niesprawiedliwych, aby nas przywiódł do Boga, umartwiony będąc ciałem, ale ożywiony duchem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'Przez którego i tym duchom, którzy są w więzieniu, przyszedłszy kazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Którzy niekiedy nieposłuszni byli, gdy raz oczekiwała Boża cierpliwość za dni Noego, kiedy korab gotowano, w którym mało (to jest ośm) dusz zachowane są w wodzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Czego teraz chrzest wzorem będąc, zbawia nas (nie składanie cielesnego plugastwa, ale obietnica spólna sumienia dobrego u Boga,) przez zmartwychwstanie Jezusa Chrystusa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Który jest na prawicy Bożej, szedłszy do nieba, podbiwszy sobie Aniołów i zwierzchności, i mocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Ponieważ tedy Chrystus ucierpiał za nas w ciele, i wy też tąż myślą bądźcie uzbrojeni, że ten, co cierpiał w ciele, poprzestał grzechu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'Aby już więcej nie cielesnym pożądliwościom, ale woli Bożej żył ostatek czasu w ciele.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Albowiem dosyć nam, żeśmy przeszłego czasu żywota popełniali lubości pogan, chodząc w rozpustach, w pożądliwościach, w opilstwach, w biesiadach, w pijaństwach i sprośnych bałwochwalstwach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Przetoż, że się wy z nimi nie schadzacie na taką zbyteczną rozpustę, zda się im rzeczą obcą i bluźnią to.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Ci dadzą liczbą temu, który gotowy jest sądzić żywych i umarłych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Dlatego bowiem i umarłym kazano Ewangieliję, aby sądzeni byli według ludzi z strony ciała, ale żyli według Boga duchem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'A wszystkiemuć się koniec przybliża.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'Przetoż trzeźwymi bądźcie i czułymi ku modlitwom, a nade wszystko miejcie uprzejmą miłość jedni ku drugim; albowiem miłość zakryje mnóstwo grzechów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Gościnnymi bądźcie jedni ku drugim bez szemrania.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Każdy jako wziął dar, tak nim jeden drugiemu usługujcie, jako dobrzy szafarze rozlicznej łaski Bożej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Jeźli kto mówi, niech mówi jako wyroki Boże, jeźli kto posługuje, niech to czyni jako z siły, której Bóg dodaje, aby we wszystkiem chwalony był Bóg przez Jezusa Chrystusa, któremu należy chwała i panowanie na wieki wieków. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Najmilsi! niech wam nie będzie rzeczą dziwną ten ogień, który na was przychodzi ku doświadczeniu waszemu, jakoby co obcego na was przychodziło;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Ale radujcie się z tego, żeście uczestnikami ucierpienia Chrystusowego, abyście się i w objawienie chwały jego z radością weselili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Jeźli was lżą dla imienia Chrystusowego, błogosławieni jesteście, gdyż on Duch chwały a Duch Boży odpoczywa na was, który względem nich bywa bluźniony, ale względem was bywa uwielbiony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'A żaden z was niech nie cierpi jako mężobójca, albo złodziej, albo złoczyńca, albo jako w cudzy urząd się wtrącający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Lecz jeźli cierpi jako chrześcijanin, niech się nie wstydzi, owszem niech chwali Boga w tej mierze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Albowiem czas jest, aby się sąd począł od domu Bożego; a ponieważ najprzód zaczyna się od nas, jakiż będzie koniec tych, co są nieposłuszni Ewangielii Bożej?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'A ponieważ sprawiedliwy ledwie zbawiony będzie, niezbożny i grzeszny gdzież się okaże?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Przetoż i ci, którzy cierpią według woli Bożej, niechaj jemu, jako wiernemu Stworzycielowi, poruczają dusze swoje, dobrze czyniąc.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Starszych, którzy są między wami, proszę ja spółstarszy i świadek ucierpienia Chrystusowego, i uczestnik chwały, która ma być objawiona:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Paście trzodę Bożą, która jest między wami, doglądając jej nie poniewolnie, ale dobrowolnie; nie dla sprośnego zysku, ale ochotnym umysłem:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Ani jako panując nad dziedzictwem Pańskiem, ale wzorami będąc trzody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'A gdy się okaże on książę pasterzy, odniesiecie niezwiędłą koronę chwały.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Także, młodsi! bądźcie poddani starszym, a wszyscy jedni drugim bądźcie poddani. Pokorą bądźcie wewnątrz ozdobieni, gdyż Bóg pysznym się sprzeciwia, a pokornym łaskę daje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Uniżajcież się tedy pod mocną ręką Bożą, aby was wywyższył czasu swego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Wszystko staranie wasze wrzuciwszy na niego, gdyż on ma pieczę o was.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Trzeźwymi bądźcie, czujcie; albowiem przeciwnik wasz dyjabeł, jako lew ryczący obchodzi, szukając kogo by pożarł.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Któremu dawajcie odpór, mocni będąc w wierze, wiedząc, iż się takoweż ucierpienia nad braterstwem waszem, które jest na świecie, wykonywają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'A Bóg wszelkiej łaski, który nas powołał do wiecznej chwały swojej w Chrystusie Jezusie, gdy maluczko ucierpicie, ten niech was doskonałymi uczyni, utwierdzi, umocni i ugruntuje;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Jemu niech będzie chwała i panowanie na wieki wieków. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Przez Sylwana wam wiernego brata, jako rozumiem, krótkom pisał, napominając i świadcząc, iż ta jest prawdziwa łaska Boża, w której stoicie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Pozdrawia was spółwybrany zbór, ten, który jest w Babilonie i Marek, syn mój');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Pozdrówcie jedni drugich w pocałowaniu miłości. Pokój niech będzie wam wszystkim, którzyście w Chrystusie Jezusie. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Szymon Piotr, sługa i Apostoł Jezusa Chrystusa, tym, którzy równie z nami kosztownej wiary dostali przez sprawiedliwość Boga naszego i zbawiciela naszego, Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Łaska i pokój niech się wam rozmnoży przez poznanie Boga i Jezusa, Pana naszego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Jako nam jego Boska moc wszystko, co do żywota i do pobożności należy, darowała przez poznanie tego, który nas powołał przez sławę i przez cnotę;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Przez co bardzo wielkie i kosztowne obietnice nam są darowane, abyście się przez nie stali uczestnikami Boskiego przyrodzenia, uszedłszy skażenia tego, które jest na świecie w pożądliwościach.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Ku temu tedy samemu wszelkiej pilności przykładając, przydajcie do wiary waszej cnotę, a do cnoty umiejętność;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'A do umiejętności powściągliwość, a do powściągliwości cierpliwość, a do cierpliwości pobożność;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'A do pobożności braterską miłość, a do miłości braterskiej łaskę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Albowiem gdy to będzie przy was, a obficie będzie, nie próżnymi, ani niepożytecznymi wystawi was w znajomości Pana naszego, Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Bo przy kim tych rzeczy nie masz, ślepy jest; a tego, co jest daleko, nie widzi, zapomniawszy na oczyszczenie od dawnych grzechów swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Przetoż, bracia! raczej się starajcie, abyście powołanie i wybranie wasze mocne czynili; albowiem to czyniąc, nigdy się nie potkniecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Tak bowiem hojnie wam dane będzie wejście do wiecznego królestwa Pana naszego i Zbawiciela, Jezusa Chrystusa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Przetoż nie zaniedbam was zawsze upominać o tych rzeczach, chociażeście umiejętni i utwierdzeni w teraźniejszej prawdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Boć to mam za słuszną rzecz, pókim jest w tym przybytku, abym was pobudzał przez napominanie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Wiedząc, iż prędkie jest złożenie przybytku mojego, jako mi i Pan nasz, Jezus Chrystus objawił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'A starać się będę o to ze wszelakiej miary, abyście wy i po zejściu mojem te rzeczy sobie przypominali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Albowiem nie baśni jakich misternie wymyślonych naśladując, uczyniliśmy wam znajomą Pana naszego, Jezusa Chrystusa moc i przyjście, ale jako ci, którzyśmy oczami naszemi widzieli wielmożność jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Wziął bowiem od Boga Ojca cześć i chwałę, gdy mu był przyniesiony głos taki od wielmożnej chwały: ten jest on Syn mój miły, w którym mi się upodobało.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'A głos ten myśmy słyszeli z nieba przyniesiony, będąc z nim na onej górze świętej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'I mamy mocniejszą mowę prorocką, której pilnując jako świecy w ciemnem miejscu świecącej, dobrze czynicie, ażby dzień oświtnął, i jutrzenka weszła w sercach waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'To najpierw wiedząc, iż żadne proroctwo Pisma nie jest własnego wykładu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Albowiem nie z woli ludzkiej przyniesione jest niekiedy proroctwo, ale od Ducha Świętego pędzeni będąc mówili święci Boży ludzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Byli też i fałszywi prorocy między ludem, jako i między wami będą fałszywi nauczyciele, którzy z sobą wprowadzą kacerstwa zatracenia i Pana, który ich kupił, zaprzą się, sami na się przywodząc prędkie zginienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'A wiele ich naśladować będą zginienia ich, przez których droga prawdy będzie bluźniona.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'I przez łakomstwo zmyślonemi słowami kupczyć będą, którym sąd z dawna nie omieszkuje i zatracenie ich nie drzemie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Albowiem jeźli Bóg Aniołom, którzy byli zgrzeszyli, nie przepuścił, ale strąciwszy ich do piekła, podał łańcuchom ciemności, aby byli zachowani na sąd:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Także i pierwszemu światu nie przepuścił, ale Noego samoósmego, kaznodzieję sprawiedliwości, zachował, przywiódłszy potop na świat niepobożnych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'I miasta Sodomczyków i Gomorry w popiół obróciwszy podwróceniem potępił, wystawiwszy je na przykład tym, którzy by niepobożnie żyli;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'A sprawiedliwego Lota, onych niezbożników rozpustnem obcowaniem strapionego, wyrwał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Albowiem widzeniem i słyszeniem on sprawiedliwy mieszkając między nimi, dzień po dniu duszę sprawiedliwą uczynkami ich niezbożnymi trapił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Umie Pan pobożnych z pokuszenia wyrywać, a niesprawiedliwych na dzień sądu ku karaniu chować;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'A najwięcej tych, którzy za ciałem w pożądliwości plugastwa chodzą, a zwierzchnością pogardzają, śmieli i sobie się podobający, nie wzdrygają się bluźnić przełożeństw.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'Chociaż Aniołowie będąc większymi siłą i mocą, nie przynoszą przeciwko nim przed Pana bluźnierczego sądu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Ale ci, jako bydło bezrozumne, które za przyrodzeniem idzie, sprawione na ułowienie i skazę, bluźniąc to, czego nie wiedzą, w tej skazie swojej zaginą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'I odniosą zapłatę niesprawiedliwości jako ci, którzy mają za rozkosz każdodzienne lubości, będąc plugastwem i zmazą, rozkosz mają w zdradach swoich z wami bankietując:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Oczy mają pełne cudzołóstwa i bez przestania grzeszące, przyłudzając dusze niestateczne, mając serce wyćwiczone w łakomstwie, synowie przeklęstwa,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Którzy opuściwszy prostą drogę, zbłądzili, naśladując drogi Balaama, syna Bosorowego, który zapłatę niesprawiedliwości umiłował;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Ale miał karanie za swój występek, ponieważ jarzmu niema oślica poddana, człowieczym głosem przemówiwszy, zahamowała szaleństwo proroka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ci są studniami bez wody, obłoki od wichru pędzone, którym chmura ciemności na wieki jest zachowana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Albowiem nadętą próżność mówiąc, przyłudzają przez pożądliwość ciała i rozpusty tych, którzy byli prawdziwie uciekli od obcujących w błędzie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Wolność im obiecując, a sami będąc niewolnikami skazy. Albowiem kto jest od kogo przezwyciężony, temu też jest zniewolony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Bo ponieważ oni uszli plugastw świata przez poznanie Pana i zbawiciela, Jezusa Chrystusa, a znowu się zaś niemi uwikławszy, zwyciężeni bywają; stały się ich ostateczne rzeczy gorsze niż pierwsze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Bo by im było lepiej, nie uznać drogi sprawiedliwości, niżeli poznawszy ją, odwrócić się od podanego im rozkazania świętego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Aleć się im przydało według onej prawdziwej przypowieści: Pies wrócił się do zwracania swego, a świnia umyta do walania się w błocie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Najmilsi! już ten drugi list do was piszę, którym wzbudzam przez napominanie uprzejmą myśl waszę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Abyście pamiętali na słowa przepowiedziane od świętych proroków, i na przykazanie nasze, którzyśmy Apostołami Pana i Zbawiciela:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'To najpierwej wiedząc, że przyjdą w ostateczne dni naśmiewcy, według własnych swoich pożądliwości chodzący,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'I mówiący: Gdzież jest obietnica przyjścia jego? Bo jako ojcowie zasnęli, wszystko tak trwa od początku stworzenia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Tego zaiste umyślnie wiedzieć nie chcą, że się niebiosa dawno stały i ziemia z wody i w wodzie stanęła przez słowo Boże,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Dlaczego on pierwszy świat wodą będąc zatopiony, zginął.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Lecz te niebiosa, które teraz są i ziemia temże słowem odłożone są i zachowane ogniowi na dzień sądu i zatracenia niepobożnych ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Ale ta jedna rzecz niech wam nie będzie tajna, najmilsi! iż jeden dzień u Pana jest jako tysiąc lat, a tysiąc lat, jako jeden dzień.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Nie omieszkiwać Pan z obietnicą, (jako to niektórzy mają za omieszkanie), ale używa cierpliwości przeciwko nam, nie chcąc, aby którzy zginęli, ale żeby się wszyscy do pokuty udali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'A on dzień Pański przyjdzie jako złodziej w nocy, w który niebiosa z wielkim trzaskiem przeminą, a żywioły rozpalone ogniem stopnieją, a ziemia i rzeczy, które są na niej, spalone będą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Ponieważ się tedy to wszystko ma rozpłynąć, jakimiż wy macie być w świętych obcowaniach i pobożnościach?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Którzy oczekujecie i spieszycie się na przyjście dnia Bożego, w który niebiosa gorejące rozpuszczą się i żywioły pałające stopnieją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Lecz nowych niebios i nowej ziemi według obietnicy jego oczekujemy, w których sprawiedliwość mieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Przetoż najmilsi! tego oczekując, starajcie się, abyście bez zmazy i bez nagany od niego znalezieni byli w pokoju;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'A nieskwapliwość Pana naszego miejcie za zbawienie wasze, jako wam i miły brat nasz Paweł według danej sobie mądrości pisał,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Jako i we wszystkich listach swoich mówiąc o tych rzeczach, między któremi są niektóre rzeczy trudne ku wyrozumieniu, które nieumiejętni i niestateczni wykręcają jako i inne pisma, ku swemu własnemu zatraceniu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Wy tedy, najmilsi! wiedząc to przedtem; strzeżcie się, abyście błędem tych niezbożników nie byli zwiedzeni i nie wypadli z waszej stateczności;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Ale rośćcie w łasce i w znajomości Pana naszego i Zbawiciela, Jezusa Chrystusa, któremu niech będzie chwała i teraz, i na czasy wieczne. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Co było od początku, cośmy słyszeli, cośmy oczyma naszemi widzieli i na cośmy patrzyli, i czego się ręce nasze dotykały, o Słowie żywota;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(Bo żywot objawiony jest i widzieliśmy, i świadczymy i zwiastujemy wam on żywot wieczny, który był u Ojca, i objawiony nam jest.)');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Cośmy, mówię, widzieli i słyszeli, to wam zwiastujemy, abyście i wy z nami społeczność mieli, a społeczność nasza, aby była z Ojcem i z Synem jego, Jezusem Chrystusem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'A toć wam piszemy, aby radość wasza zupełna była.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'A toć jest poselstwo, któreśmy słyszeli od niego i zwiastujemy wam: Iż Bóg jest światłość, a żadnej ciemności w nim nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Jeźlibyśmy rzekli, iż społeczność mamy z nim, a w ciemności chodzimy, kłamiemy, a nie czynimy prawdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'A jeźli w światłości chodzimy, jako on jest w światłości, społeczność mamy między sobą, a krew Jezusa Chrystusa, Syna jego, oczyszcza nas od wszelkiego grzechu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Jeźlibyśmy rzekli, iż grzechu nie mamy, sami siebie zwodzimy, a prawdy w nas nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Jeźlibyśmy wyznali grzechy nasze, wiernyć jest Bóg i sprawiedliwy, aby nam odpuścił grzechy i oczyścił nas od wszelkiej nieprawości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Jeźliśmy rzekli, żeśmy nie zgrzeszyli, kłamcą go czynimy, a słowa jego nie masz w nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Dziatki moje! to wam piszę, abyście nie grzeszyli; i jeźliby kto zgrzeszył, mamy orędownika u Ojca, Jezusa Chrystusa sprawiedliwego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'A on jest ubłaganiem za grzechy nasze; a nie tylko za nasze, ale też za grzechy wszystkiego świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'A przez to wiemy, żeśmy go poznali, jeźli przykazania jego zachowujemy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Kto mówi: Znam go, a przykazania jego nie zachowuje, kłamcą jest, a prawdy w nim nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Lecz kto by zachował słowa jego, prawdziwie się w tym miłość Boża wykonała; przez to znamy, iż w nim jesteśmy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Kto mówi, że w nim mieszka, powinien, jako on chodził, i sam także chodzić.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Bracia! nie nowe przykazanie wam piszę, ale przykazanie stare, któreście mieli od początku; a to stare przykazanie jest ono słowo, któreście słyszeli od początku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Zasię przykazanie nowe piszę wam, które jest prawdziwe w nim i w was; iż ciemność przemija, a prawdziwa ona światłość już świeci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Kto mówi, iż jest w światłości, a brata swego nienawidzi, w ciemności jest aż dotąd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Kto miłuje brata swego, w światłości mieszka i zgorszenia w nim nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Lecz kto nienawidzi brata swego, w ciemności jest i w ciemności chodzi, a nie wie, gdzie idzie, iż ciemność zaślepiła oczy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Piszę wam, dziatki! iż wam są odpuszczone grzechy dla imienia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Piszę wam, ojcowie! żeście poznali tego, który jest od początku. Piszę wam, młodzieńcy! żeście zwyciężyli onego złośnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Piszę wam, dziateczki! żeście poznali Ojca. Pisałem wam, ojcowie! żeście poznali onego, który jest od początku. Pisałem wam, młodzieńcy! że jesteście mocni, a słowo Boże mieszka w was, a żeście zwyciężyli onego złośnika.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Nie miłujcie świata, ani tych rzeczy, które są na świecie; jeźli kto miłuje świat, nie masz w nim miłości ojcowskiej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Albowiem wszystko, co jest na świecie, jako pożądliwość ciała i pożądliwość oczu, i pycha żywota, toć nie jest z Ojca, ale jest z świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Światci przemija i pożądliwość jego; ale kto czyni wolę Bożą, trwa na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Dziateczki! ostateczna godzina jest; a jakoście słyszeli, że antychryst przyjść ma, i teraz wiele antychrystów powstało; stąd wiemy, iż jest ostateczna godzina.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Z nas wyszli, ale nie byli z nas; albowiem gdyby byli z nas, zostaliby byli z nami; ale wyszli z nas, aby objawieni byli, iż wszyscy nie byli z nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Ale wy macie pomazanie od onego Świętego i wiecie wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Nie pisałem wam, przeto żeście prawdy nie znali, ale że ją znacie, a iż wszelkie kłamstwo nie jest z prawdy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Kto jest kłamcą? Azaż nie ten, który zapiera, iż Jezus nie jest Chrystusem? Ten jest antychryst, który się zapiera Ojca i Syna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Każdy, co się zapiera Syna, i Ojca nie ma; a kto wyznaje Syna, ma i Ojca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Wy tedy, coście słyszeli od początku, to niechaj w was zostaje; jeźliby w was zostawało, coście słyszeli od początku, i wy w Synu i w Ojcu zostaniecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'A tać jest obietnica, którą on nam obiecał, to jest żywot on wieczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Tom wam napisał o tych, którzy was zwodzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Ale to pomazanie, któreście wy wzięli od niego, zostaje w was, a nie potrzebujecie, aby was kto uczył: ale jako to pomazanie uczy was o wszystkiem, a jest prawdziwe, i nie jest kłamstwem, a jako was nauczyło, tak w niem zostaniecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'I teraz, dziateczki! zostańcie w niem, abyśmy, gdy się ukaże, ufanie mieli, a nie byli zawstydzeni od niego w przyjściu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Ponieważ wiecie, że on sprawiedliwy jest, wiedzcież też, iż każdy, który czyni sprawiedliwość, z niego narodzony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Patrzcie, jaką miłość dał nam Ojciec, abyśmy dziatkami Bożemi nazwani byli. Dlategoć świat nie zna nas, iż onego nie zna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Najmilsi! teraz dziatkami Bożemi jesteśmy, ale się jeszcze nie objawiło, czem będziemy; lecz wiemy, iż gdy się on objawi, podobni mu będziemy; albowiem ujrzymy go tak, jako jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'A ktokolwiek ma tę nadzieję w nim, oczyszcza się, jako i on czysty jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Każdy, co czyni grzech, ten i zakon przestępuje; albowiem grzech jest przestępstwo zakonu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'A wiecie, iż się on objawił, aby grzechy nasze zgładził, a grzechu w nim nie masz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Wszelki tedy, kto w nim mieszka, nie grzeszy; ale ktokolwiek grzeszy, nie widział go, ani go poznał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Dziateczki! niechaj was nikt nie zwodzi; kto czyni sprawiedliwość, sprawiedliwy jest, jako i on sprawiedliwy jest;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Kto czyni grzech, z dyjabła jest; gdyż od początku dyjabeł grzeszy. Na to się objawił Syn Boży, aby zepsował uczynki dyjabelskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Wszelki, co się narodził z Boga, grzechu nie czyni, iż nasienie jego w nim zostaje, i nie może grzeszyć, iż z Boga narodzony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Po tem poznać dziatki Boże i dzieci dyjabelskie. Wszelki, który nie czyni sprawiedliwości, nie jest z Boga, i który nie miłuje brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Albowiem to jest poselstwo, któreście słyszeli od początku, abyśmy jedni drugich miłowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Nie jako Kain, który był z tego złośnika i zabił brata swego. A dlaczegoż go zabił? Iż uczynki jego złe były, a brata jego sprawiedliwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Nie dziwujcie się, bracia moi! jeźli was świat nienawidzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'My wiemy, żeśmy przeniesieni z śmierci do żywota, iż miłujemy braci; kto nie miłuje brata, zostaje w śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Każdy, co nienawidzi brata swego, mężobójcą jest; a wiecie, iż żaden mężobójca nie ma żywota wiecznego w sobie zostawającego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Przez tośmy poznali miłość Bożą, iż on duszę swoję za nas położył; i myśmy powinni kłaść duszę za braci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'A kto by miał majętność świata tego i widziałby brata swego potrzebującego, a zawarłby wnętrzności swoje przed nim, jakoż w nim zostaje miłość Boża?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Dziateczki moje! nie miłujmy słowem ani językiem, ale uczynkiem i prawdą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'A przez to poznajemy, iż z prawdy jesteśmy i przed nim uspokojemy serca nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Bo jeźliby nas potępiało serce nasze, daleko większy jest Bóg niż serce nasze i wie wszystko.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Najmilsi! jeźliby serce nasze nas nie potępiało, ufanie mamy ku Bogu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'I o cokolwiek byśmy prosili, bierzemy od niego; bo przykazania jego chowamy i to, co się podoba przed obliczem jego, czynimy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'A toć jest przykazanie jego, abyśmy wierzyli imieniowi Syna jego, Jezusa Chrystusa, i miłowali jedni drugich, jako nam przykazał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Bo kto chowa przykazania jego, w nim mieszka, a on też w nim; a przez to znamy, iż mieszka w nas, to jest z Ducha, którego nam dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Najmilsi! nie każdemu duchowi wierzcie; ale doświadczajcie duchów, jeźli z Boga są. Bo wiele fałszywych proroków wyszło na świat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Przez to poznawajcie Ducha Bożego: Wszelki duch, który wyznaje, iż Jezus Chrystus w ciele przyszedł, z Boga jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Ale wszelki duch, który nie wyznaje, że Jezus Chrystus w ciele przyszedł, nie jest z Boga; ale ten jest on duch antychrystowy, o którymeście słyszeli, iż idzie i teraz już jest na świecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Wy z Boga jesteście, dziateczki! i zwyciężyliście ich; iż większy jest ten, który w was jest, niż ten, który jest na świecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Onić są z świata; przetoż o świecie mówią, a świat ich słucha.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'My z Boga jesteśmy. Kto zna Boga, słucha nas; kto nie jest z Boga, nie słucha nas. Przez to poznajemy ducha prawdy i ducha błędu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Najmilsi! miłujmyż jedni drugich, gdyż miłość jest z Boga; i każdy, co miłuje, z Boga jest narodzony i zna Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Kto nie miłuje, nie zna Boga; gdyż Bóg jest miłość.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Przez to objawiona jest miłość Boża ku nam, iż Syna swego jednorodzonego posłał Bóg na świat, abyśmy żyli przez niego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'W tem jest miłość, nie iżbyśmy my umiłowali Boga, ale iż on umiłował nas i posłał Syna swego, aby był ubłaganiem za grzechy nasze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Najmilsi! ponieważ nas tak Bóg umiłował, i myśmy powinni jedni drugich miłować.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Boga żaden nigdy nie widział; ale jeźli miłujemy jedni drugich, Bóg w nas mieszka, a miłość jego doskonała jest w nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Przez to poznajemy, iż w nim mieszkamy, a on w nas, iż z Ducha swego nam dał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'A myśmy widzieli i świadczymy, iż Ojciec posłał Syna, aby był Zbawicielem świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Ktobykolwiek wyznał, iż Jezus jest Synem Bożym, Bóg w nim mieszka, a on w Bogu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'I myśmy poznali i uwierzyli o miłości, którą Bóg ma ku nam. Bóg jest miłość; a kto mieszka w miłości, w Bogu mieszka, a Bóg w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'W tem doskonała jest miłość Boża z nami, abyśmy ufanie mieli w dzień sądny, iż jaki on jest, tacy i my jesteśmy na tym świecie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Nie maszci bojaźni w miłości, ale miłość doskonała precz wyrzuca bojaźń: bo bojaźń ma udręczenie, a kto się boi, nie jest doskonały w miłości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'My go miłujemy, iż on nas pierwej umiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Jeźliby kto rzekł: Miłuję Boga, a brata by swego nienawidził, kłamcą jest; albowiem kto nie miłuje brata swego, którego widział, Boga, którego nie widział, jakoż może miłować?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'A toć rozkazanie mamy od niego, aby ten, co miłuje Boga, miłował i brata swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Wszelki, co wierzy, iż Jezus jest Chrystusem, z Boga się narodził; a wszelki, co miłuje tego, który urodził, miłuje i tego, który z niego jest narodzony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Przez to znamy, iż miłujemy dziatki Boże, gdy Boga miłujemy i przykazania jego chowamy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Albowiem ta jest miłość Boża, abyśmy przykazania jego chowali; a przykazania jego nie są ciężkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Bo wszystko, co się narodziło z Boga, zwycięża świat; a to jest zwycięstwo, które zwyciężyło świat, wiara nasza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Któż jest, co zwycięża świat, tylko kto wierzy, iż Jezus jest Synem Bożym?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Tenci jest, który przyszedł przez wodę i krew, Jezus Chrystus, nie w wodzie tylko, ale w wodzie i we krwi; a Duch jest, który świadczy, iż Duch jest prawda.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Albowiem trzej są, którzy świadczą na niebie: Ojciec, Słowo i Duch Święty, a ci trzej jedno są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'A trzej są, którzy świadczą na ziemi: Duch i woda, i krew, a ci trzej ku jednemu są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Ponieważ świadectwo ludzkie przyjmujemy, świadectwo Boże większe jest; albowiem to jest świadectwo Boże, które świadczył o Synu swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Kto wierzy w Syna Bożego, ma świadectwo sam w sobie. Kto nie wierzy Bogu, kłamcą go uczynił, iż nie uwierzył temu świadectwu, które Bóg świadczył o Synu swoim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'A toć jest świadectwo, iż nam Bóg dał żywot wieczny; a ten żywot jest w Synu jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Kto ma Syna, ma żywot; kto nie ma Syna Bożego, nie ma żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Te rzeczy napisałem wam, którzy wierzycie w imię Syna Bożego, żebyście wiedzieli, iż macie żywot wieczny, i abyście wierzyli w imię Syna Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'A toć jest ufanie, które mamy do niego, iż jeźlibyśmy o co prosili według woli jego, słyszy nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'A jeźli wiemy, iż nas słyszy, o cokolwiek byśmy prosili, tedy wiemy, iż mamy te rzeczy, o któreśmy go prosili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Jeźliby kto widział brata swego grzeszącego grzechem nie na śmierć, niechże się modli za nim, a da mu Bóg żywot, to jest grzeszącym nie na śmierć. Jestci grzech na śmierć; nie za tym, mówię, aby się kto modlił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Wszelka niesprawiedliwość jest grzech; ale jest grzech nie na śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Wiemy, iż wszelki, który się z Boga narodził, nie grzeszy; ale który się narodził z Boga, zachowuje samego siebie, a on złośnik nie dotyka się go.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Wiemy, iż z Boga jesteśmy; ale świat wszystek w złem położony jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'A wiemy, iż Syn Boży przyszedł i dał nam zmysł, abyśmy poznali onego prawdziwego Boga, i jesteśmy w onym prawdziwym, to jest w Synu jego, Jezusie Chrystusie; tenci jest prawdziwy Bóg i żywot wieczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Dziateczki! strzeżcie się bałwanów. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Starszy wybranej pani i dziatkom jej, które ja miłuję w prawdzie, a nie ja tylko, ale i wszyscy, którzy poznali prawdę,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'Dla prawdy, która zostaje w nas i z nami będzie na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Niech będzie z wami łaska, miłosierdzie i pokój od Boga Ojca i od Pana Jezusa Chrystusa, Syna Ojcowego, w prawdzie i w miłości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Uradowałem się bardzo, żem znalazł niektóre z dziatek twoich chodzące w prawdzie, jakośmy przykazanie wzięli od Ojca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'A teraz proszę cię, Pani! nie jako przykazanie nowe pisząc ci, ale któreśmy mieli od początku, abyśmy jedni drugich miłowali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'A tać jest miłość, abyśmy chodzili według przykazań jego. A przykazanie to jest, jakoście słyszeli od początku, abyście w niem chodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Gdyż wiele zwodzicieli wyszło na świat, którzy nie wyznawają, że Jezus Chrystus przyszedł w ciele; ten jest zwodzicielem i antychrystem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Strzeżcie samych siebie, żebyśmy nie stracili tego, koło czegośmy pracowali, ale żebyśmy odpłatę zupełną wzięli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Wszelki, co przestępuje, a nie zostaje w nauce Chrystusowej, Boga nie ma; kto zostaje w nauce Chrystusowej, ten i Ojca, i Syna ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Jeźli kto przychodzi do was, a tej nauki nie przynosi, nie przyjmujcie go w dom, ani go pozdrawiajcie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Albowiem kto takiego pozdrawia, uczestnikiem jest złych uczynków jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Mając wam wiele pisać, nie chciałem przez papier i inkaust, ale mam nadzieję, że do was przyjdę i ustnie z wami mówić będę, aby radość nasza była zupełna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Pozdrawiają cię dziatki siostry twojej w Panu wybranej. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Starszy Gajowi miłemu, którego ja miłuję w prawdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Najmilszy! najprzód żądam, aby ci się dobrze powodziło i abyś był zdrów, tak jako się dobrze powodzi duszy twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Albowiem wielcem się uradował, gdy przyszli bracia, i dali świadectwo o twojej prawdzie, jako ty w prawdzie chodzisz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Większej nad tę radości nie mam, jako gdy słyszę, iż dziatki moje chodzą w szczerości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Najmilszy! Wiernie czynisz, cokolwiek czynisz przeciwko braciom i przeciw gościom,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Którzy świadectwo wydali o miłości twojej przed zborem; i dobrze uczynisz, jeźli ich odprowadzisz, jako przystoi przed Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Albowiem dla imienia jego wyszli, nic nie wziąwszy od pogan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'My tedy takowych powinniśmy przyjmować, abyśmy byli pomocnikami prawdzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Pisałem do zboru waszego; ale Dyjotrefes, który chce być przedniejszy między nimi, nie przyjmuje nas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Przeto jeźli przyjdę, przypomnę uczynki jego, które czyni, słowami złemi obmawiając nas, a nie mając dosyć na tem, i sam braci nie przyjmuje, i tym, co by przyjąć chcieli, zabrania i ze zboru ich wyłącza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Najmilszy! nie naśladuj złego, ale dobrego. Kto dobrze czyni, z Boga jest; ale kto źle czyni, nie widział Boga.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demetryjuszowi świadectwo jest dane od wszystkich, i od samej prawdy; lecz i my świadectwo o nim dajemy, a wiecie, iż świadectwo nasze prawdziwe jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Wielem miał pisać; lecz nie chcę pisać inkaustem i piórem;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Bo mam nadzieję, że cię w rychle ujrzę, a tedy ustnie mówić będziemy. Pokój tobie. Pozdrawiają cię przyjaciele. Pozdrów i ty przyjaciół z imienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, sługa Jezusa Chrystusa a brat Jakóba, od Boga Ojca poświęconym i w Jezusie Chrystusie zachowanym i powołanym:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Miłosierdzie i pokój, i miłość niech się wam rozmnoży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Najmilsi! Wszelką pilność czyniąc, abym wam pisał o społecznem zbawieniu, musiałem wam pisać, napominając, iżbyście bojowali o wiarę raz świętym podaną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Albowiem wkradli się niektórzy ludzie, dawno już przedtem naznaczeni na to potępienie, niepobożni, którzy łaskę Boga naszego obracają w rozpustę i samego się Boga i panującego Pana naszego, Jezusa Chrystusa zapierają.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Przetoż chcę wam przypomnieć, którzy już raz o tem wiecie, że chociaż Pan lud z ziemi Egipskiej wyswobodził, przecież potem tych, którzy nie wierzyli, potracił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Także Aniołów, którzy nie zachowali pierwszego stanu swego, ale opuścili mieszkanie swoje, na sąd dnia wielkiego związkami wiecznemi pod chmurą zachował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Jako Sodoma i Gomorra, i okoliczne miasta, gdy tymże sposobem jako i one zwszeteczniały i udały się za cudzem ciałem, wystawione są na przykład, ognia wiecznego karanie ponosząc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Także też i ci jako snem zmożeni ciało plugawią, ale zwierzchnością pogardzają i przełożeństwa bluźnią.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Lecz Michał Archanioł, gdy się z dyjabłem rozpierając wadził o ciało Mojżeszowe, nie śmiał podnieść przeciwko niemu sądu bluźnierczego, ale rzekł: Niech cię Pan zgromi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'A ci, czego nie znają, to bluźnią; a co z przyrodzenia znają, jako bezrozumne bydła w tem się psują,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Biada im! bo się drogą Kainową udali, a za błędem Baalamowej zapłaty puścili się i przeciwieństwem Korego poginęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Cić są na świętych ucztach waszych zmazani, którzy z wami godując bez wstydu, sami się pasą; są obłoki bezwodne, które od wiatrów tam i sam unoszone bywają; drzewa zwiędłe nieużyteczne, dwakroć zmarłe i wykorzenione;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Wały wściekłe morskie, wyrzucające swoje sprośności, gwiazdy błąkające się, którym chmura ciemności zachowana jest na wieki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'A prorokował też o nich siódmy od Adama Enoch, mówiąc: Oto Pan idzie z świętymi tysiącami swoimi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Aby uczynił sąd wszystkim i karał wszystkich niezbożników między nimi ze wszystkich niepobożności ich, które niezbożnie płodzili i ze wszystkich przykrości, które mówili przeciwko niemu niezbożni grzesznicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Ci są szemracze utyskujący sobie, według pożądliwości swoich chodzący, i których usta mówią bardzo harde słowa; pochlebiając osobom dla swego pożytku.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Lecz wy, najmilsi! pamiętajcie na słowa przepowiedziane od Apostołów Pana naszego Jezusa Chrystusa;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Iż wam powiadali, że w ostateczny czas będą naśmiewcy, chodzący według swoich niezbożnych pożądliwości.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Cić są, którzy się sami odłączają, bydlęcy, ducha Chrystusowego nie mający.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Ale wy najmilsi! budując się na najświętszej wierze waszej i modląc się w Duchu Świętym,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Samych siebie w miłości Bożej zachowajcie, oczekując miłosierdzia Pana naszego, Jezusa Chrystusa, ku żywotowi wiecznemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'A nad niektórymi zmiłujcie się, rozsądkiem się rządząc;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'A drugich przez postrach do zbawienia przywódźcie, z ognia ich wyrywając, mając w nienawiści i suknię, która by była od ciała pokalana.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'A temu, który was może zachować od upadku i stawić przed oblicznością chwały swojej bez nagany z weselem,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'Samemu mądremu Bogu, Zbawicielowi naszemu, niech będzie chwała i wielmożność, moc i zwierzchność, i teraz i po wszystkie wieki. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Objawienie Jezusa Chrystusa, które mu dał Bóg, aby okazał sługom swoim rzeczy, które się w rychle dziać mają; a on je oznajmił i posłał przez Anioła swojego słudze swemu Janowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Który świadectwo wydał słowu Bożemu i świadectwu Jezusa Chrystusa, i cokolwiek widział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Błogosławiony, który czyta i ci, którzy słuchają słów proroctwa tego, i zachowują to, co w niem jest napisane; albowiem czas blisko jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Jan siedmiu zborom, które są w Azyi. Łaska wam i pokój niech będzie od tego, który jest i który był, i który przyjść ma; i od siedmiu duchów, którzy są przed oblicznością stolicy jego;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'I od Jezusa Chrystusa, który jest onym świadkiem wiernym, pierworodnym z umarłych i książęciem królów ziemi; który nas umiłował i omył nas z grzechów naszych krwią swoją;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'I uczynił nas królami i kapłanami Bogu, Ojcu swemu; jemuż niech będzie chwała i moc na wieki wieków. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Oto idzie z obłokami i ujrzy go wszelkie oko, i ci, którzy go przebili; i narzekać będą przed nim wszystkie pokolenia ziemi. Tak, Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Jam jest Alfa i Omega, początek i koniec, mówi Pan, który jest i który był, i który przyjść ma, on Wszechmogący.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Ja Jan, którym też jest bratem waszym i uczestnikiem w ucisku i w królestwie, i w cierpliwości Jezusa Chrystusa, byłem na wyspie, którą zowią Patmos, dla słowa Bożego i dla świadectwa Jezusa Chrystusa:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Byłem w zachwyceniu ducha w dzień Pański i słyszałem za sobą głos wielki jako trąby, mówiący:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Jam jest Alfa i Omega, on pierwszy i ostatni; a co widzisz, napisz w księgi i poślij siedmiu zborom, które są w Azyi, do Efezu i do Smyrny, i do Pergamu, i do Tyjatyru, i do Sardów, i do Filadelfii, i do Laodycei.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'I obróciłem się, abym widział on głos, który mówił ze mną; a obróciwszy się, ujrzałem siedm świeczników złotych,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'A w pośrodku onych siedmiu świeczników podobnego Synowi człowieczemu, obleczonego w długą szatę, i przepasanego na piersiach pasem złotym;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'A głowa jego i włosy były białe jako wełna biała, jako śnieg, a oczy jego jako płomień ognia;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'A nogi jego podobne mosiądzowi, jakoby w piecu rozpalone, a głos jego jako głos wielu wód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'I miał w prawej ręce swojej siedm gwiazd, a z ust jego wychodził miecz z obu stron ostry, a oblicze jego jako słońce, kiedy jasno świeci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'A gdym go ujrzał, upadłem do nóg jego jako martwy. I włożył prawą rękę swoję na mię, mówiąc mi: Nie bój się! Jam jest on pierwszy i ostatni,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'I żyjący; a byłem umarły, a otom jest żywy na wieki wieków. I mam klucze piekła i śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Napisz te rzeczy, któreś widział i które są, i które się dziać mają napotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Tajemnicę onych siedmiu gwiazd, któreś widział w prawej ręce mojej i siedmiu świeczników złotych. Siedm onych gwiazd są Aniołowie siedmiu zborów, a siedm świeczników, któreś widział, jest siedm zborów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Aniołowi zboru Efeskiego napisz: To mówi ten, który trzyma siedm gwiazd w prawej ręce swojej, który się przechadza w pośród onych siedmiu świeczników złotych:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Znam uczynki twoje i pracę twoję, i cierpliwość twoję, a iż nie możesz cierpieć złych i doświadczyłeś tych, którzy się mienią być Apostołami, a nie są, i znalazłeś ich, że są kłamcami;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'I masz cierpliwość, i znaszałeś i pracowałeś dla imienia mego, a nie ustałeś.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Ale mam nieco przeciwko tobie, żeś miłość twoję pierwszą opuścił.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Pamiętajże tedy, skądeś wypadł, a pokutuj i czyń uczynki pierwsze; a jeźli nie chcesz, przyjdę przeciwko tobie rychło, a poruszę świecznik twój z miejsca swego, jeźlibyś nie pokutował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Ale wżdy to masz, iż nienawidzisz uczynków Nikolaitów, których i ja nienawidzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Kto ma uszy, niechaj słucha, co Duch mówi zborom: Temu, co zwycięży, dam jeść z drzewa żywota, które jest w pośrodku raju Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'A Aniołowi zboru Smyrneńskiego napisz: To mówi pierwszy i ostatni, który był umarł i ożył:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Znam uczynki twoje i ucisk, i ubóstwo, (aleś bogaty), i bluźnierstwo tych, którzy się powiadają być Żydami, a nie są, ale są bóżnicą szatańską.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Nic się nie bój tego, co masz cierpieć. Oto wrzuci dyjabeł niektórych z was do więzienia, abyście byli doświadczeni; i będziecie mieli ucisk przez dziesięć dni. Bądź wierny aż do śmierci, a dam ci koronę żywota.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Kto ma uszy, niechaj słucha, co Duch mówi zborom: Kto zwycięży, nie będzie obrażony od wtórej śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'A Aniołowi zboru Pergameńskiego napisz: To mówi ten, który ma miecz on z obydwóch stron ostry;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Znam uczynki twoje i gdzie mieszkasz, to jest, gdzie jest stolica szatańska, a iż trzymasz imię moje i nie zaprzałeś się wiary mojej, i w one dni, w które Antypas, świadek mój wierny, zabity jest u was, gdzie szatan mieszka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Ale mam nieco przeciwko tobie, iż tam masz tych, którzy trzymają naukę Balaamową, który uczył Balaka, aby wrzucił zgorszenie przed syny Izraelskie, żeby jedli rzeczy bałwanom ofiarowane i wszeteczeństwo płodzili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Także masz i tych, którzy trzymają naukę Nikolaitów, co ja mam w nienawiści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Pokutujże: a jeźli nie będziesz, przyjdę przeciwko tobie w rychle i będę walczył z nimi mieczem ust moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Kto ma uszy, niechaj słucha, co Duch mówi zborom: Temu, co zwycięży, dam jeść z onej manny skrytej i dam mu kamyk biały, a na onym kamyku imię nowe napisane, którego nikt nie zna, tylko ten, który je przyjmuje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'A Aniołowi zboru Tyjatyrskiego napisz: To mówi syn Boży, który ma oczy swoje jako płomień ognia, a nogi jego podobne są mosiądzowi:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Znam uczynki twoje i miłość, i posługi, i wiarę, i cierpliwość twoję, i uczynki twoje, a że ostatnich rzeczy więcej jest niż pierwszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Ale mam nieco przeciwko tobie, iż niewieście Jezabeli, która się mieni być prorokinią, dopuszczasz uczyć i zwodzić sługi moje, żeby wszeteczeństwo płodzili i rzeczy bałwanom ofiarowane jedli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'I dałem jej czas, aby pokutowała z wszeteczeństwa swego; ale nie pokutowała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Oto ja porzucę ją na łoże i tych, którzy z nią cudzołożą, w ucisk wielki, jeźliby nie pokutowali z uczynków swoich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'A dzieci jej pobiję na śmierć; i poznają wszystkie zbory, żem ja jest ten, który się badam nerek i serc; i dam każdemu z was według uczynków waszych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'A wam mówię i drugim, którzyście w Tyjatyrzech, którzykolwiek nie mają tej nauki i którzy nie poznali głębokości szatańskich, jako mówią: Nie włożę na was innego brzemienia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Wszakże to, co macie, trzymajcie, aż przyjdę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'A kto zwycięży i zachowa aż do końca uczynki moje, dam mu zwierzchność nad poganami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'I będzie ich rządził laską żelazną; jako statki garncarskie skruszeni będą, jakom i ja wziął od Ojca mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'I dam mu gwiazdę poranną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Kto ma uszy, niechaj słucha, co Duch mówi zborom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'A aniołowi zboru, który jest w Sardziech, napisz: To mówi ten, który ma siedm duchów Bożych i siedm gwiazd: Znam uczynki twoje, i masz imię, że żyjesz; aleś jest umarły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Bądź czujny, a utwierdzaj innych, którzy umrzeć mają; albowiem nie znalazłem uczynków twoich zupełnych przed Bogiem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Pamiętaj tedy, jakoś wziął i słyszał, a chowaj i pokutuj. Jeźli tedy czuć nie będziesz, przyjdę na cię jako złodziej, a nie zrozumiesz, której godziny przyjdę na cię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Ale masz niektóre osoby w Sardziech, które nie pokalały szat swoich; przetoż chodzić będą ze mną w szatach białych, iż godni są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Kto zwycięży, ten będzie obleczony w szaty białe i nie wymażę imienia jego z ksiąg żywota, ale wyznam imię jego przed obliczem Ojca mojego i przed Aniołami jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Kto ma uszy, niechaj słucha, co Duch mówi zborom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'A Aniołowi zboru Filadelfskiego napisz: To mówi on Święty i Prawdziwy, który ma klucz Dawidowy, który otwiera, a nikt nie zawiera i zawiera, a nikt nie otwiera.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Znam uczynki twoje; otom wystawił przed tobą drzwi otworzone, a żaden nie może ich zamknąć; bo acz masz niewielką moc, przecięś zachował słowo moje i nie zaprzałeś się imienia mego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Otoć dam niektórych z bóżnicy szatańskiej, którzy się powiadają być Żydami, a nie są, ale kłamią. Oto sprawię, że przyjdą i będą się kłaniali przed nogami twemi, i poznają, żem ja cię umiłował.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Żeś zachował słowo cierpliwości mojej, ja też cię zachowam od godziny pokuszenia, która przyjdzie na wszystek świat, aby doświadczyła mieszkających na ziemi;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Oto idę rychło; trzymaj, co masz, aby nikt nie wziął korony twojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Kto zwycięży, uczynię go filarem w kościele Boga mojego, a więcej z niego już nie wynijdzie; i napiszę na nim imię Boga mego i imię miasta Boga mego, nowego Jeruzalemu, które zstępuje z nieba od Boga mego i imię moje nowe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Kto ma uszy, niechaj słucha, co Duch mówi zborom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'A Aniołowi zboru Laodyceńskiego napisz: To mówi Amen, świadek on wierny i prawdziwy, początek stworzenia Bożego:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Znam uczynki twoje, żeś nie jest ani zimny ani gorący, bodajżeś był zimny albo gorący!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'A tak, ponieważ jesteś letni, a ani zimny ani gorący, wyrzucę cię z ust moich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Albowiem mówisz: Jestem bogaty i zbogaciłem się, a niczego nie potrzebuję; a nie wiesz, żeś ty biedny i mizerny, i ubogi, i ślepy, i nagi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Radzę ci, abyś kupił u mnie złota w ogniu doświadczonego, abyś był bogaty, i szaty białe, abyś był obleczony, a żeby się nie okazywała sromota nagości twojej; a oczy twoje namaż maścią wzrok naprawiającą, abyś widział.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Ja którychkolwiek miłuję, strofuję i karzę. Bądź tedy gorliwym, a pokutuj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Oto stoję u drzwi i kołaczę; jeźliby kto usłyszał głos mój i otworzył drzwi, wnijdę do niego i będę z nim wieczerzał, a on ze mną.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Kto zwycięży, dam mu siedzieć z sobą na stolicy mojej, jakom i ja zwyciężył i usiadłem z Ojcem moim na stolicy jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Kto ma uszy, niechaj słucha, co Duch mówi zborom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Potemem widział, a oto drzwi były otworzone w niebie, a głos pierwszy, którym słyszał, jako trąby mówiącej ze mną, i rzekł: Wstąp sam, a pokażę ci, co się ma dziać napotem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'A zarazem byłem w zachwyceniu ducha, a oto stolica postawiona była na niebie, a na stolicy siedziała osoba.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'A ten, który siedział, podobny był na wejrzeniu kamieniowi jaspisowi i sardynowi; a około onej stolicy była tęcza, na wejrzeniu podobna szmaragdowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'A około onej stolicy było stolic dwadzieścia i cztery; a na onych stolicach widziałem dwudziestu i czterech starców siedzących, obleczonych w szaty białe, a na głowach swoich mieli korony złote.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'A z onej stolicy wychodziły błyskawice i gromy, i głosy, i siedm lamp ognistych gorejących przed stolicą, które są siedm duchów Bożych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'A przed oną stolicą było morze szklane, podobne kryształowi, a w pośrodku stolicy i około stolicy czworo zwierząt pełnych oczu z przodku i z tyłu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'A pierwsze zwierzę podobne było lwowi, a wtóre zwierzę podobne cielcowi, a trzecie zwierzę miało twarz jako człowiek, a czwarte zwierzę podobne było orłowi latającemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'A oto każde z osobna z onych czterech zwierząt miało sześć skrzydeł wokoło, a wewnątrz były pełne oczów, a odpoczynku nie mają we dnie i w nocy, mówiąc: Święty, święty, święty Pan, Bóg wszechmogący, który był i jest, i przyjść ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'A gdy one zwierzęta dawały chwałę i cześć, i dziękowanie siedzącemu na stolicy, żyjącemu na wieki wieków;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Upadli dwadzieścia cztery starcy przed obliczem siedzącego na stolicy i kłaniali się żyjącemu na wieki wieków, i rzucali korony swoje przed stolicą, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Godzieneś jest, Panie! wziąć chwałę i cześć, i moc; boś ty stworzył wszystkie rzeczy i za wolą twoją trwają, i stworzone są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'I widziałem po prawej ręce siedzącego na stolicy księgi napisane, wewnątrz i zewnątrz zapieczętowane siedmioma pieczęciami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'I widziałem Anioła mocnego, wołającego głosem wielkim: Kto jest godzien otworzyć te księgi i odpieczętować pieczęci ich?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'A nikt nie mógł ani w niebie, ani na ziemi, ani pod ziemią otworzyć onych ksiąg, ani wejrzeć w nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'I płakałem bardzo, iż nikt nie był znaleziony godny, aby otworzył i czytał księgi, i wejrzał w nie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Tedy mi jeden z onych starców rzekł: Nie płacz! Oto zwyciężył lew, który jest z pokolenia Judowego, korzeń Dawidowy, aby otworzył księgi i odpieczętował siedm pieczęci ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'I spojrzałem, a oto między stolicą i czterema onemi zwierzętami, i między onymi starcami Baranek stał jako zabity, mając siedm rogów i siedm oczy, które są siedm duchów Bożych, posłanych na wszystkę ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Ten przyszedł i wziął one księgi z prawej ręki siedzącego na stolicy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'A gdy wziął one księgi, zaraz ono czworo zwierząt i oni dwadzieścia i cztery starcy upadli przed Barankiem, mając każdy z nich cytry i czasze złote, pełne wonnych rzeczy, które są modlitwy świętych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'I śpiewali nową pieśń, mówiąc: Godzieneś jest wziąć księgi i otworzyć pieczęci ich, żeś był zabity i odkupiłeś nas Bogu przez krew swoję ze wszelkiego pokolenia i języka, i ludu, i narodu:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'I uczyniłeś nas Bogu naszemu królami i kapłanami, i królować będziemy na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'I widziałem, i słyszałem głos wielu Aniołów około onej stolicy, i onych zwierząt i onych starców; a była liczba ich tysiąckroć sto tysięcy i dziesięćkroć sto tysięcy,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Mówiących głosem wielkim: Godzien jest ten Baranek zabity, wziąć moc i bogactwo, i mądrość, i siłę, i cześć, i chwałę, i błogosławieństwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'A wszelkie stworzenie, które jest na niebie i na ziemi, i pod ziemią i w morzu, i wszystko, co w nich jest, słyszałem mówiące: Siedzącemu na stolicy i Barankowi błogosławieństwo i cześć, i chwała, i siła na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'A czworo onych zwierząt rzekło: Amen. A oni dwadzieścia i cztery starcy upadli i kłaniali się żyjącemu na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'I widziałem, gdy otworzył Baranek jedną z onych pieczęci, i słyszałem jedno ze czterech zwierząt mówiące, jako głos gromu: Chodź, a patrzaj!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'I widziałem, a oto koń biały, a ten, który na nim siedział, miał łuk, i dano mu koronę, i wyszedł jako zwycięzca, ażeby zwyciężał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'A gdy otworzył wtórą pieczęć, słyszałem wtóre zwierzę mówiące: Chodź, a patrzaj!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'I wyszedł drugi koń rydzy; a temu, który na nim siedział, dano, aby odjął pokój z ziemi, a iżby jedni drugich zabijali, i dano mu miecz wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'A gdy otworzył trzecią pieczęć, słyszałem trzecie zwierzę mówiące: Chodź, a patrzaj! I widziałem, a oto koń wrony, a ten, co na nim siedział, miał szalę w ręce swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'I słyszałem głos z pośrodku onych czworga zwierząt mówiący: Miarka pszenicy za grosz, a trzy miarki jęczmienia za grosz; a nie szkodź oliwie i winu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'A gdy otworzył czwartą pieczęć, słyszałem głos czwartego zwierzęcia mówiący: Chodź, a patrzaj!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'I widziałem, a oto koń płowy, a tego, który siedział na nim, imię było śmierć, a piekło szło za nim; i dana im jest moc nad czwartą częścią ziemi, aby zabijali mieczem i głodem, i morem, i przez zwierzęta ziemskie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'A gdy otworzył piątą pieczęć, widziałem pod ołtarzem dusze pobitych dla słowa Bożego i dla świadectwa, które wydawali;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'I wołali głosem wielkim, mówiąc: Dokądże, Panie święty i prawdziwy! nie sądzisz i nie mścisz się krwi naszej nad tymi, którzy mieszkają na ziemi?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'I dane są każdemu z nich szaty białe, i powiedziano im, aby odpoczywali jeszcze na mały czas, ażby się dopełnił poczet spółsług ich i braci ich, którzy mają być pobici, jako i oni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'I widziałem, gdy otworzył szóstą pieczęć, a oto stało się wielkie trzęsienie ziemi, a słońce sczerniało jako wór włosiany i księżyc wszystek stał się jako krew;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'A gwiazdy niebieskie padały na ziemię, tak jako drzewo figowe zrzuca z siebie figi swoje niedostałe, gdy od wiatru wielkiego bywa zachwiane.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'A niebo ustąpiło jako księgi zwinione, a wszelka góra i wyspy z miejsca się swego poruszyły;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'A królowie ziemi i książęta, i bogacze, i hetmani, i mocarze, i każdy niewolnik, i każdy wolny pokryli się w jaskinie i w skały gór,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'I rzekli górom i skałom: Upadnijcie na nas i zakryjcie nas przed obliczem tego, który siedzi na stolicy i przed gniewem tego Baranka;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Albowiem przyszedł dzień on wielki gniewu jego, i któż się ostać może?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Potemem widział czterech Aniołów, stojących na czterech węgłach ziemi, trzymających cztery wiatry ziemi, aby nie wiał wiatr na ziemię, ani na morze, ani na żadne drzewo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'I widziałem inszego Anioła występującego od wschodu słońca, mającego pieczęć Boga żywego, i zawołał głosem wielkim na onych czterech Aniołów, którym dano, aby szkodzili ziemi i morzu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Mówiąc: Nie szkodźcie ziemi ani morzu, ani drzewom, aż popieczętujemy sługi Boga naszego na czołach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'I usłyszałem liczbę popieczętowanych: sto czterdzieści i cztery tysiące jest popieczętowanych ze wszystkich pokoleń synów Izraelskich:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Z pokolenia Judowego dwanaście tysięcy popieczętowanych; z pokolenia Rubenowego dwanaście tysięcy popieczętowanych; z pokolenia Gadowego dwanaście tysięcy popieczętowanych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Z pokolenia Aserowego dwanaście tysięcy popieczętowanych; z pokolenia Neftalimowego dwanaście tysięcy popieczętowanych; z pokolenia Manasesowego dwanaście tysięcy popieczętowanych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'Z pokolenia Symeonowego dwanaście tysięcy popieczętowanych; z pokolenia Lewiego dwanaście tysięcy popieczętowanych; z pokolenia Isacharowego dwanaście tysięcy popieczętowanych;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'Z pokolenia Zabulonowego dwanaście tysięcy popieczętowanych; z pokolenia Józefowego dwanaście tysięcy popieczętowanych; z pokolenia Benjaminowego dwanaście tysięcy popieczętowanych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Potemem widział, a oto lud wielki, którego nie mógł nikt zliczyć, z każdego narodu i pokolenia, i ludzi, i języków, którzy stali przed stolicą i przed oblicznością Baranka, obleczeni w szaty białe, a palmy były w rękach ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'I wołali głosem wielkim, mówiąc: Zbawienie należy Bogu naszemu, siedzącemu na stolicy i Barankowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'A wszyscy Aniołowie stali około stolicy i starców i czworga zwierząt, i upadli przed stolicą na oblicze swoje, i kłaniali się Bogu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'Mówiąc: Amen! Błogosławieństwo i chwała, i mądrość, i dziękowanie, i cześć, i moc, i siła Bogu naszemu na wieki wieków. Amen.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'I odpowiedział jeden z onych starców i rzekł mi: Ci, którzy są obleczeni w szaty białe, co zacz są? i skąd przyszli?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'I rzekłem mu: Panie! ty wiesz. I rzekł mi: Cić są, którzy przyszli z ucisku wielkiego i omyli szaty swoje, i wybielili je we krwi Barankowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Dlatego są przed stolicą Bożą i służą mu we dnie i w nocy w kościele jego, a ten, który siedzi na stolicy, jako namiotem zasłoni ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Nie będą więcej łaknąć i nie będą więcej pragnąć, i nie uderzy na nich słońce, ani żadne gorąco');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Albowiem Baranek, który jest w pośrodku stolicy, będzie ich pasł i poprowadzi ich do żywych źródeł wód, i otrze Bóg wszelką łzę z oczów ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'A gdy otworzył siódmą pieczęć, stało się milczenie na niebie, jakoby przez pół godziny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'I widziałem siedm onych Aniołów, którzy stoją przed obliczem Bożem, a dano im siedm trąb.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'A inszy Anioł przyszedł i stanął przed ołtarzem, mając kadzielnicę złotą; i dano mu wiele kadzenia, aby je ofiarował z modlitwami wszystkich świętych na ołtarzu złotym, który jest przed stolicą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'I wstąpił dym kadzenia z modlitwami świętych z ręki Anioła przed obliczność Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'I wziął Anioł kadzielnicę i napełnił ją ogniem z ołtarza, i zrzucił ją na ziemię, i stały się głosy i gromy, i błyskawice, i trzęsienie ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'A onych siedm Aniołów, którzy mieli siedm trąb, nagotowało się, aby trąbili.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'I zatrąbił pierwszy Anioł i stał się grad i ogień zmieszany ze krwią; i zrzucono to na ziemię, a trzecia część drzew zgorzała i wszelka trawa zielona spalona jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Potem zatrąbił wtóry Anioł, a jakoby góra wielka ogniem pałająca wrzucona jest w morze i obrócona jest w krew trzecia część morza.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'I pozdychała w morzu trzecia część rzeczy stworzonych, które miały duszę i trzecia część okrętów zginęła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'I zatrąbił trzeci Anioł i spadła z nieba gwiazda wielka, gorejąca jako pochodnia, i upadła na trzecią część rzek i na źródła wód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'A imię onej gwiazdy zowią piołunem; i obróciła się trzecia część wód w piołun, a wiele ludzi pomarło od onych wód, bo się stały gorzkie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Potem zatrąbił czwarty Anioł, a uderzona jest trzecia część słońca i trzecia część księżyca, i trzecia część gwiazd, tak iż się trzecia część ich zaćmiła, i trzecia część dnia nie świeciła, także i nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'I widziałem, i słyszałem jednego Anioła lecącego przez pośrodek nieba, mówiącego głosem wielkim: Biada, biada, biada mieszkającym na ziemi dla innych głosów trąby trzech Aniołów, którzy zatrąbić mają!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'I zatrąbił piąty Anioł i widziałem, że gwiazda spadła z nieba na ziemię, a dano jej klucz studni przepaści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'I otworzyła studnię przepaści; i wystąpił dym z onej studni, jakoby dym pieca wielkiego, i zaćmiło się słońce i powietrze od dymu onej studni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'A z onego dymu wyszły szarańcze na ziemię i dano im moc, jako mają moc niedźwiadki ziemskie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'A rzeczono im, żeby nie szkodziły trawie ziemi, ani żadnej rzeczy zielonej, ani żadnemu drzewu, ale tylko samym ludziom, którzy nie mają pieczęci Bożej na czołach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'A dano im, nie żeby ich zabijały, ale aby ich dręczyły przez pięć miesięcy, a udręczenie ich, aby było jako udręczenie od niedźwiadka, gdy człowieka ukąsi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Przetoż w one dni szukać będą ludzie śmierci, ale jej nie znajdą; i będą chcieli umrzeć, ale śmierć od nich uciecze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'A kształt onych szarańczy podobny był koniom zgotowanym do bitwy, a na głowach ich były jakoby korony podobne złotu, a twarze ich jako twarze ludzkie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'I miały włosy jako włosy niewieście, a zęby ich były jako lwie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'A miały pancerze jako pancerze żelazne, a szum skrzydeł ich, jako grzmot wozów, gdy wiele koni bieży do bitwy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'A ogony miały podobne niedźwiadkom, a żądła były w ogonach ich, a moc ich była szkodzić ludziom przez pięć miesięcy;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'A miały nad sobą króla, anioła przepaści, któremu imię po żydowsku Abaddon, a po grecku ma imię Apolijon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Biada jedno przeszło, a oto jeszcze idą dwa biada potem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Tedy zatrąbił Anioł szósty, a słyszałem głos jeden ze czterech rogów ołtarza złotego, który jest przed oblicznością Bożą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Mówiący szóstemu Aniołowi, który miał trąbę: Rozwiąż onych czterech Aniołów związanych u wielkiej rzeki Eufrates.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'I rozwiązani są oni czterej Aniołowie, zgotowani na godzinę i na dzień, i na miesiąc, i na rok, aby pobili trzecią część ludzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'A liczba wojska jezdnego była dwieściekroć tysiąc tysięcy; bom słyszał liczbę ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Widziałem także konie w widzeniu, a ci, którzy siedzieli na nich, mieli pancerze ogniste hijacyntowe i siarczane; a głowy onych koni były jako głowy lwie, a z gęby ich wychodził ogień i dym i siarka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'A od tego trojga pobita jest trzecia część ludzi od ognia i od dymu, i od siarki, które wychodziły z gąb ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Albowiem moc ich jest w gębach ich i w ogonach ich; bo ogony ich wężom są podobne, mając głowy, któremi szkodzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'A inni ludzie, którzy nie są pobici temi plagami, ani pokutowali od uczynków rąk swoich, aby się nie kłaniali dyjabłom i bałwanom złotym i srebrnym, i miedzianym, i kamiennym i drewnianym, którzy ani widzieć nie mogą, ani słyszeć, ani chodzić;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Ani pokutowali z mężobójstw swoich, ani z czarów swoich, ani z wszeteczeństw swoich, ani z złodziejstw swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'I widziałem drugiego Anioła mocnego, zstępującego z nieba, obłokiem odzianego, a na głowie jego była tęcza, a oblicze jego jako słońce, a nogi jego jako słupy ognia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'A miał w ręce swojej książeczki otworzone i postawił nogę swoję prawą na morzu, a lewą na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'I zawołał głosem wielkim, jako lew ryczy; a gdy przestał wołać, mówiło siedm gromów głosy swoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'A gdy odmówiło siedm gromów głosy swoje, miałem pisać; alem usłyszał głos z nieba, mówiący do mnie: Zapieczętuj to, co mówiło siedm gromów, a nie pisz tego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Tedy Anioł, któregom widział stojącego na morzu i na ziemi, podniósł rękę swoję ku niebu,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'I przysiągł przez Żyjącego na wieki wieków, który stworzył niebo i to, co w niem jest, i ziemię, i to, co na niej jest, i morze, i to, co w niem jest, że czasu już nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Ale we dni głosu Anioła siódmego, gdy będzie trąbił, dokona się tajemnica Boża, jako opowiedział sługom swoim prorokom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'A głos, którym słyszał z nieba, zasię mówił ze mną i rzekł: Idź, a weźmij te książeczki otworzone z ręki Anioła stojącego na morzu i na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'I szedłem do Anioła, i rzekłem mu: Daj mi te książeczki. I rzekł mi: Weźmij, a zjedz je, a uczynią gorzkość w brzuchu twoim; ale w ustach twoich słodkie będą jako miód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'I wziąłem książeczki z ręki Anioła i zjadłem je, a były w ustach moich słodkie jako miód; ale gdym je zjadł, gorzko było w brzuchu moim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'I rzekł mi: Musisz zasię prorokować przed wielą ludzi i narodów, i języków, i królów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'I dano mi trzcinę podobną lasce; a Anioł stanął, mówiąc: Wstań, a zmierz kościół Boży i ołtarz, i tych, którzy się modlą w nim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Ale sień, która jest przed kościołem, wyrzuć precz, a nie mierz jej; albowiem dana jest poganom, a miasto święte deptać będą czterdzieści i dwa miesiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'I dam je dwom świadkom moim, którzy prorokować będą tysiąc dwieście i sześćdziesiąt dni, obleczeni będąc w wory.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Ci są dwie oliwy i dwa świeczniki, stojące przed obliczem Pana wszystkiej ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'A jeźliby im kto chciał szkodzić, ogień wynijdzie z ust ich i pożre nieprzyjacioły ich; a jeźliby im kto chciał szkodzić, ten też tak musi być zabity.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Ci moc mają zamykać niebo, aby deszcz nie padał za dni proroctwa ich; i mają moc nad wodami, aby je obrócili w krew, i uderzyć ziemię wszelką plagą, ilekroć by chcieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'A gdy dokończą świadectwa swojego, bestyja, która występuje z przepaści, stoczy z nimi bitwę, a zwycięży ich i pobije ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'A trupy ich leżeć będą na ulicy miasta wielkiego, które nazywają duchownie Sodomą i Egiptem, gdzie też Pan nasz ukrzyżowany jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'I widzieć będą wiele ich z ludzi, z pokolenia i z języków, i z narodów trupy ich przez półczwarta dnia; ale trupów ich nie dopuszczą włożyć w groby:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Owszem mieszkający na ziemi radować się nad nimi będą i weselić; i poślą dary jedni drugim, iż ci dwaj prorocy dręczyli mieszkających na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'A po półczwarta dnia duch żywota od Boga wstąpił w nich i stanęli na nogach swoich, a bojaźń wielka przypadła na tych, którzy ich widzieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Potem usłyszeli głos wielki z nieba, mówiący im: Wstąpcie sam! I wstąpili na niebo w obłoku, i patrzyli na nich nieprzyjaciele ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'A w onęż godzinę stało się wielkie trzęsienie ziemi. I upadła dziesiąta część miasta, i pobito w onem trzęsieniu ziemi osób ludzi siedm tysięcy, a drudzy przestraszeni są, i dali chwałę Bogu niebieskiemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Biada wtóra przeszła, a oto biada trzecia przyjdzie rychło.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'I zatrąbił Anioł siódmy i stały się głosy wielkie na niebie mówiące: Królestwa świata stały się królestwami Pana naszego i Chrystusa jego, i królować będzie na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Tedy oni dwadzieścia i cztery starcy, którzy przed oblicznością Bożą siedzą na stolicach swoich, upadli na oblicza swe i pokłonili się Bogu, mówiąc:');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Dziękujemy tobie, Panie Boże wszechmogący, któryś jest i któryś był, i który masz przyjść! żeś wziął moc swoję wielką i ująłeś królestwo;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'I rozgniewały się narody, i przyszedł gniew twój i czas umarłych, aby byli sądzeni i abyś oddał zapłatę sługom twoim, prorokom i świętym, i bojącym się imienia twego, małym i wielkim, i abyś wytracił tych, co psują ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Tedy otworzony jest kościół Boży na niebie i widziana jest skrzynia przymierza jego w kościele jego; i stały się błyskawice i głosy, i grzmienia, i trzęsienia ziemi i grad wielki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'I ukazał się cud wielki na niebie: Niewiasta obleczona w słońce, a księżyc pod nogami jej, a na głowie jej była korona z dwunastu gwiazd;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'A będąc brzemienna, wołała pracując ku porodzeniu i męczyła się, aby porodziła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'I ukazał się drugi cud na niebie, a oto smok wielki rydzy, mając siedm głów i rogów dziesięć, a na głowach jego siedm koron;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'A ogon jego ciągnął trzecią część gwiazd niebieskich i zrzucił je na ziemię; a smok on stanął przed niewiastą, która miała porodzić, aby skoro by porodziła, pożarł dziecię jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'I urodziła syna, mężczyznę, który ma rządzić wszystkie narody laską żelazną; i porwane jest dziecię jej do Boga i do stolicy jego,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'A niewiasta uciekła na pustynię, gdzie ma miejsce od Boga zgotowane, aby ją tam żywiono przez dni tysiąc dwieście i sześćdziesiąt.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'I stała się bitwa na niebie. Michał i Aniołowie jego potykali się z smokiem, smok się też potykał i aniołowie jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Ale nie przemogli, ani miejsce ich dalej znalezione jest na niebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'I zrzucony jest smok wielki, wąż on starodawny, którego zowią dyjabłem i szatanem, który zwodzi wszystek okrąg świata; zrzucony jest na ziemię i aniołowie jego z nim są zrzuceni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'I słyszałem głos wielki mówiący na niebie: Terazci się stało zbawienie i moc, i królestwo Boga naszego, i zwierzchność Chrystusa jego, iż zrzucony jest oskarżyciel braci naszych, który na nich skarżył przed oblicznością Boga naszego we dnie i w nocy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Ale go oni zwyciężyli przez krew Baranka i przez słowa świadectwa swego, a nie umiłowali duszy swojej aż do śmierci.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Przetoż rozweselcie się nieba! i wy, którzy mieszkacie na nich. Biada mieszkającym na ziemi i na morzu! iż zstąpił dyjabeł do was, mając wielki gniew, wiedząc, iż krótki czas ma.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'A gdy wiedział smok, iż był zrzucony na ziemię, prześladował niewiastę, która była porodziła mężczyznę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'I dano niewieście dwa skrzydła orła wielkiego, aby leciała od obliczności wężowej na pustynię, na miejsce swoje, gdzie by ją żywiono przez czas i czasy, i połowę czasu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'I wypuścił wąż z gęby swojej za niewiastą wodę jako rzekę, chcąc sprawić, aby ją rzeka porwała.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Ale ziemia ratowała niewiastę; i otworzyła ziemia usta swoje, i wypiła rzekę, którą był wypuścił smok z gęby swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'I rozgniewał się smok na niewiastę, i poszedł, aby walczył z drugimi z nasienia jej, którzy zachowują przykazania Boże i mają świadectwo Jezusa Chrystusa. I stanąłem na piasku morskim.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'I widziałem bestyję występującą z morza, mającą siedm głów i rogów dziesięć; a na rogach jej było dziesięć koron, a na głowach jej imię bluźnierstwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'A ta bestyja, którąm widział, podobna była rysiowi, a nogi jej jako niedźwiedzie, a gęba jej jako gęba lwia; i dał jej smok moc swoję i stolicę swoję, i moc wielką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'A widziałem jednę z głów jej, jakoby na śmierć zabitą; ale rana jej śmiertelna uleczona jest. Tedy się dziwowała wszystka ziemia i szła za oną bestyją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'I kłaniali się onemu smokowi, który dał moc bestyi; kłaniali się też bestyi, mówiąc: Któż podobny bestyi? Któż z nią walczyć może?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'I dane jej są usta, mówiące wielkie rzeczy i bluźnierstwa; dana jej też jest moc, aby władzę miała przez czterdzieści i dwa miesiące.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'I otworzyła usta swoje ku bluźnierstwu przeciwko Bogu, aby bluźniła imię jego i przybytek jego, i tych, którzy mieszkają na niebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Dano jej też walczyć z świętymi i zwyciężać ich. I dana jej moc nad wszelkiem pokoleniem i językiem, i narodem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'I będą się jej kłaniać wszyscy mieszkający na ziemi, których imiona nie są napisane w księgach żywota Baranka zabitego od założenia świata.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Jeźli kto ma uszy, niechaj słucha!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Jeźli kto w pojmanie wiedzie, w pojmanie pójdzie; jeźli kto mieczem zabije, musi i on być mieczem zabity. Tuć jest cierpliwość i wiara świętych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Zatem widziałem drugą bestyję występującą z ziemi, a miała dwa rogi podobne Barankowym; ale mówiła jako smok,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'A wszystkiej mocy pierwszej onej bestyi dokazuje przed twarzą jej i czyni, że ziemia i mieszkający na niej kłaniają się bestyi pierwszej, której śmiertelna rana była uzdrowiona;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'A czyni cuda wielkie, tak iż i ogień z nieba zstępuje przed oczyma ludzi na ziemię;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'I zwodzi mieszkających na ziemi przez one cuda, które jej dano czynić przed bestyją, mówiąc obywatelom ziemi, aby uczynili obraz onej bestyi, która miała ranę od miecza, ale zasię ożyła.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'I dano jej, aby mogła dać ducha onemu obrazowi bestyi, żeby też mówił obraz tej bestyi i to sprawił, aby ci, którzy by się nie kłaniali obrazowi onej bestyi, byli pobici.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'A czyni, aby wszyscy, mali i wielcy, bogaci i ubodzy, i wolni, i niewolnicy, wzięli piętna na prawą rękę swoję albo na czoła swe,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'A żeby żaden nie mógł kupować ani sprzedawać, tylko ten, który ma piętno albo imię bestyi albo liczbę imienia jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Tu jest mądrość. Kto ma rozum, niech zrachuje liczbę onej bestyi; albowiem jest liczba człowieka. A ta jest liczba jej, sześćset sześćdziesiąt i sześć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'I widziałem, a oto Baranek stał na górze Syońskiej, a z nim sto czterdzieści i cztery tysiące, mających imię Ojca jego napisane na czołach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'I słyszałem głos z nieba, jako głos wielu wód, i jako głos gromu wielkiego; i słyszałem głos cytrystów grających na cytrach swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'A śpiewali, jakoby nową pieśń, przed stolicą i przed onem czworgiem zwierząt, i przed starcami, a żaden się nie mógł onej pieśni nauczyć, oprócz onych stu czterdziestu i czterech tysięcy, którzy są z ziemi kupieni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Cić są, którzy się z niewiastami nie pokalali; bo pannami są. Ci są, którzy naśladują Baranka, gdziekolwiek idzie. Ci kupieni są z ludzi, aby byli pierwiastkami Bogu i Barankowi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'A w ustach ich nie znalazła się zdrada; albowiem są bez zmazy przed stolicą Bożą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'I widziałem drugiego Anioła, lecącego przez pośrodek nieba, mającego Ewangieliję wieczną, aby ją zwiastował mieszkającym na ziemi i wszelkiemu narodowi, i pokoleniu, i językowi, i ludowi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Mówiącego głosem wielkim: Bójcie się Boga i chwałę mu dajcie, gdyż przyszła godzina sądu jego, a kłaniajcie się temu, który uczynił niebo i ziemię, i morze, i źródła wód.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'A za nim szedł drugi Anioł, mówiąc: Upadł Babilon, ono miasto wielkie! bo winem gniewu wszeteczeństwa swego napoił wszystkie narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'A trzeci Anioł szedł za nimi, mówiąc głosem wielkim: Jeźli się kto pokłoni bestyi i obrazowi jej, i jeźli weźmie piętno na czoło swoje albo na rękę swoję,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'I ten pić będzie z wina gniewu Bożego, z wina szczerego i nalanego w kielich gniewu jego i będzie męczony w ogniu i siarce przed oblicznością Aniołów świętych i przed oblicznością Baranka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'A dym męki ich występuje na wieki wieków, i nie mają odpoczynku we dnie i w nocy, którzy się kłaniają bestyi i obrazowi jej, i jeźli kto bierze piętno imienia jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Tuć jest cierpliwość świętych, tuć są ci, którzy chowają przykazania Boże i wiarę Jezusową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'I usłyszałem głos z nieba, mówiący do mnie: Napisz: Błogosławieni są odtąd umarli, którzy w Panu umierają. Zaprawdę mówi Duch im, aby odpoczywali od prac swoich, a uczynki ich idą za nimi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'I widziałem, a oto obłok biały; a na onym obłoku siedział podobny Synowi człowieczemu, który miał na głowie swojej koronę złotą, a w ręce swojej sierp ostry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'A drugi Anioł wyszedł z kościoła, wołając głosem wielkim na tego, który siedział na obłoku: Zapuść sierp twój, a żnij, gdyż tobie przyszła godzina, abyś żął, ponieważ się dostało żniwo ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'I zapuścił ten, który siedział na obłoku, sierp swój na ziemię i pożęta jest ziemia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'A drugi Anioł wyszedł z kościoła onego, który jest w niebie, mając i ten sierp ostry.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Potem wyszedł drugi Anioł z ołtarza, który miał moc nad ogniem i zawołał głosem wielkim na tego, który miał sierp ostry, mówiąc: Zapuść ten sierp twój ostry, a zbieraj grona winnicy ziemi; bo dojrzałe są jagody jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Zapuścił tedy Anioł sierp swój ostry na ziemię i zebrał grona winnicy ziemi, i wrzucił je w prasę wielką gniewu Bożego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'I tłoczona jest prasa przed miastem, i wyszła krew z prasy aż do wędzideł końskich przez tysiąc i sześćset stajan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Potemem widział drugi cud na niebie wielki i dziwny, to jest siedm Aniołów mających siedm plag ostatecznych, iż przez nie skończony jest gniew Boży.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'I widziałem, jakoby morze szklane zmieszane z ogniem; a tych, co zwycięstwo otrzymali nad oną bestyją i nad obrazem jej, i nad piętnem jej, i nad liczbą imienia jej, stojących nad morzem szklanem, mających cytry Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'A śpiewali pieśń Mojżesza, sługi Bożego, i pieśń Barankową, mówiąc: Wielkie i dziwne są sprawy twoje, Panie Boże wszechmogący! sprawiedliwe i prawdziwe są drogi twoje, o królu świętych!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Któż by się ciebie nie bał, Panie! i nie wielbił imienia twego? gdyżeś sam święty, gdyż wszystkie narody przyjdą i kłaniać się będą przed obliczem twojem, że się okazały sprawiedliwe sądy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'A potemem widział, a oto otworzony był kościół przybytku świadectwa na niebie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'I wyszło z kościoła siedm onych Aniołów, mających siedm plag, obleczonych płótnem czystem i świetnem, i przepasanych na piersiach złotemi pasami.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'A jedno ze czworga zwierząt dało siedmiu Aniołom siedm czasz złotych, pełnych gniewu Boga żyjącego na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'I napełniony jest kościół dymem od chwały Bożej i od mocy jego, a nie mógł nikt wnijść do kościoła, aż się skończyło siedm plag onych siedmiu Aniołów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'I słyszałem głos wielki z kościoła, mówiący siedmiu Aniołom: Idźcie, a wylejcie siedm czasz zapalczywości Bożej na ziemię.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'I wyszedł pierwszy Anioł, a wylał czaszę swoję na ziemię; i wyrzucił się zły i szkodliwy wrzód na ludzi, którzy mieli piętno bestyi i na tych, którzy się kłaniali obrazowi jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'I wylał wtóry Anioł czaszę swoję na morze, i stało się jakoby krew umarłego, a każda dusza żywa zdechła w morzu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'I wylał trzeci Anioł czaszę swoję na rzeki i źródła wód, i obróciły się w krew.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'I słyszałem Anioła wód mówiącego: Sprawiedliwyś jest, Panie! któryś jest i któryś był, i święty, żeś to rozsądził.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Ponieważ krew świętych i proroków wylewali, dałeś im też krew pić; bo tego są godni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'I słyszałem drugiego od ołtarza mówiącego: Zaiste, Panie, Boże wszechmogący! prawdziwe i sprawiedliwe są sądy twoje.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Potem czwarty Anioł wylał czaszę swoję na słońce, i dano mu moc trapić ludzi gorącością ognia.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'I byli upaleni ludzie gorącością wielką, i bluźnili imię Boga, który ma moc nad temi plagami; wszakże nie pokutowali, aby mu chwałę dali.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Tedy wylał piąty Anioł czaszę swoję na stolicę bestyi; i stało się królestwo jej zaćmione, i żwali języki swoje od boleści.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'I bluźnili Boga niebieskiego dla boleści swoich i dla wrzodów swoich; wszakże nie pokutowali z uczynków swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'I wylał szósty Anioł czaszę swoję na onę wielką rzekę Eufrates i wyschła woda jej, aby zgotowana była droga królom od wschodu słońca.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'I widziałem z ust smokowych i z ust bestyi, i z ust fałszywego proroka trzy nieczyste duchy wychodzące, podobne żabom.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Albowiem są duchy dyjabelskie, czyniące cuda, które wychodzą do królów ziemi i na wszystek okrąg świata, aby ich zgromadzili na wojnę onego wielkiego dnia Boga wszechmogącego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Oto idę jako złodziej: Błogosławiony, który czuje i strzeże szat swoich, aby nie chodził nago i nie widziano sromoty jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'I zgromadził ich na miejsce, które zowią po żydowsku Armagieddon.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Tedy wylał siódmy Anioł czaszę swoję na powietrze; i wyszedł głos wielki z kościoła niebieskiego od stolicy, mówiący: Stało się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'I stały się głosy i gromy, i błyskawice; i stało się wielkie trzęsienie ziemi, jakiego nigdy nie było, jako są ludzie na ziemi, trzęsienia ziemi tak wielkiego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'I stało się ono miasto wielkie na trzy części rozerwane, i miasta narodów upadły; i Babilon on wielki przyszedł na pamięć przed obliczem Bożem, aby mu dał kielich wina zapalczywości gniewu swojego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'I wszystkie wyspy uciekły, i góry nie są znalezione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'I wielki grad jako cetnarowy spadł z nieba na ludzi, i bluźnili ludzie Boga dla plagi gradu, iż plaga jego była bardzo wielka.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'I przyszedł jeden z siedmiu Aniołów, którzy mieli siedm czasz, i rzekł do mnie, mówiąc mi: Chodź, okażę ci osądzenie onej wielkiej wszetecznicy, która siedzi nad wodami wielkiemi,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'Z którą wszeteczeństwo płodzili królowie ziemi i upili się winem wszeteczeństwa jej obywatele ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'I odniósł mię na puszczę w duchu. I widziałem niewiastę siedzącą na szarłatnoczerwonej bestyi, pełnej imion bluźnierstwa, która miała siedm głów i dziesięć rogów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'A ona niewiasta przyobleczona była w purpurę i w szarłat, i uzłocona złotem i drogim kamieniem, i perłami, mając kubek złoty w ręce swej, pełen obrzydliwości i nieczystości wszeteczeństwa swego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'A na czole jej było imię napisane: Tajemnica, Babilon wielki, matka wszeteczeństw i obrzydliwości ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'I widziałem niewiastę onę pijaną krwią świętych i krwią męczenników Jezusowych; a widząc ją, dziwowałem się wielkim podziwieniem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'I rzekł mi Anioł: Czemuż się dziwujesz? Ja tobie powiem tajemnicę tej niewiasty i bestyi, która ją nosi, która ma siedm głów i dziesięć rogów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Bestyja, którąś widział, była, a nie jest, a ma wystąpić z przepaści, a iść na zginienie; i zadziwią się mieszkający na ziemi, (których imiona nie są napisane w księgach żywota od założenia świata), widząc bestyję, która była, a nie jest, a przecię jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Tuć jest rozum mający mądrość: Te siedm głów są siedm gór, na których ta niewiasta siedzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'A królów jest siedm, pięć ich upadło, a jeden jest, inszy jeszcze nie przyszedł, a gdy przyjdzie, na mały czas musi trwać.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'A bestyja, która była a nie jest, toć jest ten ósmy, a jest z onych siedmiu, a idzie na zginienie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'A dziesięć rogów, któreś widział, jest dziesięć królów, którzy królestwa jeszcze nie wzięli; ale wezmą moc jako królowie, na jednę godzinę z bestyją.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Ci jedną radę mają i moc, i zwierzchność swoję bestyi podadzą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Ci z Barankiem walczyć będą, i Baranek ich zwycięży, bo jest Panem panów i królem królów, i którzy są z nim powołani i wybrani, i wierni.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'I rzekł mi: Wody, któreś widział, gdzie wszetecznica siedzi, są ludzie i zastępy, i narody, i języki.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'A dziesięć rogów, któreś widział na bestyi, cić w nienawiści mieć będą wszetecznicę i uczynią ją spustoszoną i nagą, i ciało jej będą jeść, a samą ogniem spalą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Albowiem Bóg podał do serc ich, aby czynili wolę jego, a czynili jednomyślnie, i dali królestwo swoje bestyi, ażby się wypełniły słowa Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'A niewiasta, którąś widział, jest miasto ono wielkie, które ma królestwo nad królami ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'A potemem widział drugiego Anioła zstępującego z nieba, mającego moc wielką i oświeciła się ziemia od chwały jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'I zawołał potężnie głosem wielkim, mówiąc: Upadł, upadł Babilon on wielki i stał się przybytkiem czartów i mieszkaniem wszelkiego ducha nieczystego, i mieszkaniem wszelkiego ptastwa nieczystego i przemierzłego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Iż z win zapalczywości wszeteczeństwa jego piły wszystkie narody, a królowie ziemi wszeteczeństwo z nim płodzili, i kupcy ziemscy z zbytecznej rozkoszy jego zbogacieli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'I słyszałem inszy głos z nieba mówiący: Wynijdźcie z niego, ludu mój! abyście nie byli uczestnikami grzechów jego, a iżbyście nie wzięli z plag jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Albowiem dosięgły grzechy jego aż do nieba i wspomniał Bóg na nieprawości jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Oddajcież mu, jako i on oddawał wam, a w dwójnasób oddajcie mu według uczynków jego; w kubku, który wam nalewał, nalejcie mu w dwójnasób.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Jako się wiele chlubił i rozkoszował, tak mu wiele dajcie mąk i smutku; bo mówi w sercu swojem: Siedzę jako królowa, a nie jestem wdową, i smutku nie ujrzę.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Przetoż w jeden dzień przyjdą plagi jego, śmierć i smutek, i głód, i ogniem będzie spalony; bo mocny jest Pan Bóg, który go osądzi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'I będą go płakać, i narzekać nad nim będą królowie ziemi, którzy z nim wszeteczeństwo płodzili i rozkoszowali, gdy ujrzą dym zapalenia jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Z daleka stojąc dla bojaźni męki jego i mówiąc: Biada, biada, miasto ono wielkie Babilon, miasto ono mocne, iż w jednę godzinę przyszedł sąd twój!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Do tego i kupcy ziemscy płakać będą i narzekać nad niem, przeto iż towaru ich żaden więcej kupować nie będzie,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Towaru złota i srebra, i kamienia drogiego, i pereł, i lnu cienkiego, i purpury, i jedwabiu, i szarłatu, i wszelkiego drzewa tyinowego, i wszelkiego naczynia słoniowego, i wszelkiego naczynia z drzewa najkosztowniejszego, i z miedzi, i z żelaza, i z marmuru,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'I cynamonu, i kadzenia, i maści, i kadzidła, i wina, i oliwy, i mąki czystej, i pszenicy, i bydła, i owiec, i koni, i wozów, i niewolników, i dusz ludzkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'I owoce pożądliwości duszy twojej odeszły od ciebie, i wszystkie rzeczy tłuste i świetne odeszły od ciebie, a tych rzeczy już więcej nie znajdziesz.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Kupcy tych rzeczy, zbogaciwszy się tem, z daleka stać będą dla bojaźni męki jego, płacząc i narzekając,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'A mówiąc: Biada, biada, miasto ono wielkie, które było obleczone w bisior, i w purpurę, i w szarłat, i uzłocone złotem, i kamieniem drogim, i perłami; gdyż w jednej godzinie zginęło tak wielkie bogactwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'I wszelki sternik, i wszystko mnóstwo ludu, które jest na okręcie, i żeglarze, i którzykolwiek na morzu pożytku szukają, z daleka stanęli.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'I zawołali, widząc dym zapalenia jego, mówiąc: Któreż miasto było podobne temu miastu wielkiemu?');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'A sypali proch na głowy swoje i wołali, płacząc i smucąc się, i mówiąc: Biada, biada, miasto ono wielkie, w którem zbogatnieli wszyscy, którzy mieli okręty na morzu z dostatków jego, iż jednej godziny spustoszało!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Rozraduj się nad niem niebo i święci Apostołowie i prorocy; bo się pomścił krzywdy waszej Bóg nad niem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'I podniósł jeden Anioł mocny kamień jakoby młyński wielki, i wrzucił go w morze, mówiąc: Takim pędem wrzucony będzie Babilon, miasto ono wielkie, i już więcej nie będzie znaleziony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'I głos cytrystów, i śpiewaków, i piszczków, i trębaczy więcej w tobie słyszany nie będzie, i żaden rzemieślnik wszelkiego rzemiosła nie znajdzie się więcej w tobie, i grzmot młyna nie będzie więcej słyszany w tobie;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'I światłość świecy nie będzie się więcej świeciła w tobie, i głos oblubieńca i oblubienicy nie będzie więcej słyszany w tobie; iż kupcy twoi byli wielcy panowie ziemscy, iż czarami twojemi byli zwiedzeni wszystkie narody.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'I w niem znalazła się krew proroków i świętych, i wszystkich, którzy są pobici na ziemi.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Potemem słyszał wielki głos wielkiego ludu na niebie, mówiącego: Halleluja! Zbawienie i chwała, i cześć, i moc Panu, Bogu naszemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Bo prawdziwe i sprawiedliwe są sądy jego, iż osądził wszetecznicę onę wielką, która kaziła ziemię wszeteczeństwem swojem i pomścił się krwi sług swoich z ręki jej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'I rzekli po wtóre: Halleluja! A dym jej wstępuje na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'I upadli dwadzieścia i czterej starcy, i czworo zwierząt, a pokłonili się Bogu siedzącemu na stolicy, mówiąc: Amen, Halleluja!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Tedy wyszedł głos z stolicy, mówiący: Chwalcie Boga naszego wszyscy słudzy jego i którzy się go boicie, i mali, i wielcy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'I słyszałem głos jako ludu wielkiego i jako głos wielu wód, i jako głos mocnych gromów, mówiących: Halleluja! iż ujął królestwo Pan Bóg wszechmogący.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Weselmy się i radujmy się, a dajmy mu chwałę; bo przyszło wesele Barankowe, a małżonka jego nagotowała się.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'I dano jej, aby się oblekła w bisior czysty i świetny,; albowiem bisior są usprawiedliwienia świętych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'I rzekł mi: Napisz: Błogosławieni, którzy są wezwani na wieczerzę wesela Barankowego. I rzekł mi: Te słowa Boże są prawdziwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'I upadłem do nóg jego, abym się mu pokłonił; ale mi rzekł: Patrz, abyś tego nie czynił; bom jest spółsługa twój i braci twoich, którzy mają świadectwo Jezusowe. Bogu się kłaniaj; albowiem świadectwo Jezusowe jest duch proroctwa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'I widziałem niebo otworzone, a oto koń biały, a tego, który siedział na nim, zwano Wiernym i Prawdziwym, a sądzi w sprawiedliwości i walczy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'A oczy jego były jako płomień ognia, a na głowie jego wiele koron; i miał imię napisane, którego nikt nie zna, tylko on sam.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'A przyodziany był szatą omoczoną we krwi, a imię jego zowią Słowo Boże.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'A wojska, które są na niebie, szły za nim na koniach białych, obleczone lnem cienkim, białym i czystym.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'A z ust jego wychodził miecz ostry, aby nim bił narody; albowiem on je rządzić będzie laską żelazną, a on tłoczy prasę wina zapalczywości i gniewu Boga wszechmogącego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'A ma na szacie i na biodrach swoich imię napisane: Król królów i Pan panów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'I widziałem jednego Anioła stojącego w słońcu i wołającego głosem wielkim, mówiąc wszystkim ptakom latającym po pośrodku nieba: Chodźcie i zgromadźcie się na wieczerzę wielkiego Boga,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Abyście jedli ciała królów i ciała hetmanów, i ciała mocarzy, i ciała koni, i siedzących na nich, i ciała wszystkich wolnych i niewolników, i małych, i wielkich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'I widziałem bestyję i królów ziemskich, i wojska ich zebrane, aby stoczyli bitwę z siedzącym na koniu i z wojskiem jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Ale pojmana jest bestyja, a z nią fałszywy on prorok, który czynił cuda przed nią, któremi zwodził tych, którzy przyjęli piętno bestyi i którzy się kłaniali obrazowi jej, i obaj wrzuceni są żywo do jeziora ognistego, gorejącego siarką.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'A drudzy pobici są mieczem tego, który siedział na koniu, wychodzącym z ust jego, a wszystkie ptaki nasycone są ciałami ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'I widziałem Anioła zstępującego z nieba, mającego klucz od przepaści i łańcuch wielki w ręce swojej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'I uchwycił smoka, węża onego starego, który jest dyjabeł i szatan, i związał go na tysiąc lat;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'I wrzucił go w przepaść i zamknął go, i zapieczętował z wierzchu nad nim, aby nie zwodził więcej narodów, ażeby się wypełniło tysiąc lat; a potem musi być rozwiązany na mały czas.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'I widziałem stolice, a usiedli na nich i dany im jest sąd i dusze pościnanych dla świadectwa Jezusowego i dla słowa Bożego, i którzy się nie kłaniali bestyi ani obrazowi jej, i nie przyjęli piętna jej na czoło swoje i na rękę swoję; i ożyli, i królowali z Chrystusem tysiąc lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'A insi z umarłych nie ożyli, ażby się skończyło tysiąc lat. Toć jest pierwsze zmartwychwstanie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Błogosławiony i święty, który ma część w pierwszem zmartwychwstaniu; albowiem nad tymi wtóra śmierć mocy nie ma; ale będą kapłanami Bożymi i Chrystusowymi, i będą z nim królować tysiąc lat.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'A gdy się skończy tysiąc lat, będzie rozwiązany szatan z ciemnicy swojej,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'I wynijdzie, aby zwodził narody, które są na czterech węgłach ziemi, Goga, i Magoga, aby je zgromadził do bitwy; których liczba jest jako piasek morski.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'I wstąpili na szerokość ziemi i otoczyli obóz świętych i miasto umiłowane. Ale zstąpił ogień od Boga z nieba i pożarł je.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'A dyjabeł, który je zwodził, wrzucony jest w jezioro ognia i siarki, gdzie jest ona bestyja i fałszywy prorok; i będą męczeni we dnie i w nocy, na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'I widziałem stolicę wielką białą, i siedzącego na niej, przed którego obliczem uciekła ziemia i niebo, a miejsce im nie jest znalezione.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'I widziałem umarłych, wielkich i małych, stojących przed oblicznością Bożą, a księgi otworzone są; i druga księga także otworzona jest, to jest księga żywota; i sądzeni są umarli według tego, jako napisano było w onych księgach, to jest według uczynków ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'I wydało morze umarłych, którzy w niem byli, także śmierć i piekło wydały umarłych, którzy w nich byli; i byli sądzeni każdy według uczynków swoich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'A śmierć i piekło wrzucone są w jezioro ogniste. Tać jest wtóra śmierć.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'A jeśli się kto nie znalazł napisany w księgach żywota, wrzucony jest w jezioro ogniste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Potemem widział niebo nowe i ziemię nową; albowiem pierwsze niebo i pierwsza ziemia przeminęła, a morza już więcej nie było.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'A ja Jan widziałem ono święte miasto, Jeruzalem nowe, zstępujące z nieba od Boga zgotowane, jako oblubienicę ubraną mężowi swemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'I słyszałem głos wielki z nieba mówiący: Oto przybytek Boży z ludźmi, i będzie mieszkał z nimi; a oni będą ludem jego, a sam Bóg będzie z nimi, będąc Bogiem ich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'I otrze Bóg wszelką łzę z oczów ich; a śmierci więcej nie będzie, ani smutku, ani krzyku, ani boleści nie będzie; albowiem pierwsze rzeczy pominęły.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'I rzekł ten, który siedział na stolicy: Oto wszystko nowe czynię. I rzekł mi: Napisz: bo te słowa są wierne i prawdziwe.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'I rzekł mi: Stało się. Jam jest Alfa i Omega, początek i koniec. Ja pragnącemu dam darmo ze źródła wody żywej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Kto zwycięży, odziedziczy wszystko i będę mu Bogiem, a on mi będzie synem.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Lecz bojaźliwym i niewiernym, i obmierzłym, i mężobójcom, i wszetecznikom, i czarownikom, i bałwochwalcom, i wszystkim kłamcom część ich dana będzie w jeziorze gorejącem ogniem i siarką: Tać jest śmierć wtóra.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Tedy przyszedł do mnie jeden z onych siedmiu Aniołów, którzy mieli siedm czasz napełnionych siedmioma plagami ostatecznemi, i mówił ze mną, i rzekł: Chodź sam, okażę ci oblubienicę, małżonkę Barankową.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'I zaniósł mię w duchu na górę wielką i wysoką, i okazał mi miasto wielkie, ono święte Jeruzalem, zstępujące z nieba od Boga,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Mające chwałę Bożą, którego światłość podobna była kamieniowi najkosztowniejszemu, jako kamieniowi jaspisowi, na kształt kryształu przezroczystemu;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'I mające mur wielki i wysoki, mające bram dwanaście, a na onych bramach dwanaście Aniołów i imiona napisane, które są dwanaście pokoleń synów Izraelskich.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Od wschodu bramy trzy, od północy bramy trzy, od południa bramy trzy, od zachodu bramy trzy.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'A mur miasta miał gruntów dwanaście, a na nich dwanaście imion dwunastu Apostołów Barankowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'A ten, co mówił ze mną, miał trzcinę złotą, a zmierzył miasto i bramy jego, i mur jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'A położenie miasta onego jest czworograniaste, a długość jego taka jest, jako i szerokość. I pomierzył miasto ono trzciną na dwanaście tysięcy stajan; a długość i szerokość i wysokość jego równe są.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'I zmierzył mur jego na sto czterdzieści cztery łokcie miary człowieczej, która jest miara Aniołowa.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'A było budowanie muru jego z jaspisu; a samo miasto było złoto czyste, podobne szkłu czystemu.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'A grunty muru miasta ozdobione były wszelkim kamieniem drogim. Pierwszy grunt był jaspis, wtóry szafir, trzeci chalcedon, czwarty szmaragd.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'Piąty sardoniks, szósty sardyjusz, siódmy chrysolit, ósmy beryllus, dziewiąty topazyjusz, dziesiąty chrysopras, jedenasty hijacynt, dwunasty ametyst.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'A dwanaście bram jest dwanaście pereł: a każda brama była z jednej perły, a rynek miasta złoto czyste jako szkło przezroczyste.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Alem kościoła nie widział w niem; albowiem Pan, Bóg wszechmogący, jest kościołem jego, i Baranek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'A nie potrzebuje to miasto słońca ani księżyca, aby świeciły w niem; albowiem chwała Boża oświeciła je, a świecą jego jest Baranek.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'A narody, które będą zbawione, będą chodziły w świetle jego, a królowie ziemscy chwałę i cześć swoję do niego przyniosą.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'A bramy jego nie będą zamknięte we dnie; albowiem tam nocy nie będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'I wniosą do niego chwałę i cześć narodów.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'I nie wnijdzie do niego nic nieczystego i czyniącego obrzydliwość i kłamstwo, tylko ci, którzy są napisani w księgach żywota Barankowych.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'I ukazał mi rzekę czystą wody żywota, jasną jako kryształ, wychodzącą z stolicy Bożej i Barankowej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'A w pośród rynku jego z obu stron rzeki było drzewo żywota, przynoszące owoc dwanaścioraki, na każdy miesiąc wydawające owoc swój, a liście drzewa służyły ku uzdrowieniu pogan.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'I nie będzie więcej żadnego przeklęstwa, ale stolica Boża i Barankowa w niem będzie, a słudzy jego służyć mu będą,');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'I patrzyć będą na oblicze jego, a imię jego na czołach ich będzie.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'I nocy tam nie będzie i nie będą potrzebować świecy i światłości słonecznej; bo je Pan Bóg oświeca, i królować będą na wieki wieków.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'I rzekł mi: Te słowa wierne są i prawdziwe, a Pan, Bóg świętych proroków, posłał Anioła swego, aby ukazał sługom swoim, co się ma stać w rychle.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Oto przychodzę rychło: Błogosławiony, który zachowuje słowa proroctwa księgi tej.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'A ja Jan widziałem i słyszałem te rzeczy. A gdym słyszał i widział, upadłem, abym się pokłonił przed nogami Anioła onego, który mi to pokazywał.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Ale mi on rzekł: Patrz, abyś tego nie czynił; bom jest spółsługa twój i braci twoich proroków, i tych, co chowają słowa księgi tej; Bogu się kłaniaj.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Potem mi rzekł: Nie pieczętuj słów proroctwa księgi tej; albowiem czas blisko jest.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Kto szkodzi, niech jeszcze szkodzi; a kto jest plugawy, niech jeszcze będzie plugawszy; a kto jest sprawiedliwy, niech się jeszcze usprawiedliwi; a kto święty, niech jeszcze będzie poświęcony.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'A oto przychodzę rychło, a zapłata moja jest ze mną, abym oddał każdemu według uczynków jego.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Jam jest Alfa i Omega, początek i koniec, pierwszy i ostateczny.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Błogosławieni, którzy czynią przykazania jego, aby mieli prawo do drzewa żywota, i aby weszli bramami do miasta.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'A na dworze będą psy i czarownicy, i wszetecznicy, i mężobójcy, i bałwochwalcy, i każdy, który miłuje i czyni kłamstwo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Ja Jezus posłałem Anioła mojego, aby wam świadczył o tych rzeczach we zborach. Jam jest korzeń i rodzaj on Dawidowy, gwiazda jasna i poranna.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'A Duch i oblubienica mówią: Przyjdź! A kto słyszy, niech rzecze: Przyjdź! A kto pragnie, niech przyjdzie; a kto chce, niech bierze wodę żywota darmo.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'A oświadczam się każdemu słuchającemu słów proroctwa księgi tej: Jeźliby kto przydał do tego, przyda mu też Bóg plag opisanych w tej księdze;');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'A jeźliby kto ujął ze słów księgi proroctwa tego, odejmie też Bóg część jego z księgi żywota i z miasta świętego, i z tych rzeczy, które są napisane w tej księdze.');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Tak mówi ten, który świadectwo daje o tych rzeczach: Zaiste, przyjdę rychło. Amen. I owszem przyjdź, Panie Jezusie!');
INSERT INTO `PolGdanska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Łaska Pana naszego, Jezusa Chrystusa, niech będzie z wami wszystkimi. Amen.');
